INSERT INTO public.ir_act_window VALUES (68, NULL, 1, 1, 'ir.actions.act_window', 'action', 'list,form', '{"en_US": "Groups"}', '{"en_US": "<p>A group is a set of functional areas that will be assigned to the user in order to give them access and rights to specific applications and tasks in the system. You can create custom groups or edit the ones existing by default in order to customize the view of the menu that users will be able to see. Whether they can have a read, write, create and delete access right can be managed from here.</p>"}', '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872', NULL, NULL, 80, NULL, NULL, '{''search_default_filter_no_share'': 1, ''ir.ui.menu.full_list'': 1}', 'res.groups', 'current', 'tree,form', 'kanban', NULL, NULL);
