INSERT INTO public.ir_act_window VALUES (145, NULL, 1, 1, 'ir.actions.act_window', 'action', 'list,form', '{"en_US": "Gross Margin"}', '{"en_US": "<p class=\"o_view_nocontent_empty_folder\">\n                No activity yet on this account\n            </p><p>\n                In Odoo, sales orders and projects are implemented using\n                analytic accounts. You can track costs and revenues to analyse\n                your margins easily.\n            </p><p>\n                Costs will be created automatically when you register supplier\n                invoices, expenses or timesheets.\n            </p><p>\n                Revenues will be created automatically when you create customer\n                invoices. Customer invoices can be created based on sales orders\n                (fixed price invoices), on timesheets (based on the work done) or\n                on expenses (e.g. reinvoicing of travel costs).\n            </p>\n        "}', '2026-05-10 01:11:46.819771', '2026-05-10 01:11:46.819771', 402, NULL, 80, 403, '[(''auto_account_id'',''='', active_id)]', '{''search_default_group_date'': 1, ''default_auto_account_id'': active_id}', 'account.analytic.line', 'current', 'tree,form,graph,pivot', 'kanban', NULL, NULL);
