INSERT INTO public.ir_act_window VALUES (252, NULL, 1, 1, 'ir.actions.act_window', 'action', 'list,form', '{"en_US": "Journal Entries"}', '{"en_US": "<p class=\"o_view_nocontent_smiling_face\">\n                Create a journal entry\n              </p><p>\n                A journal entry consists of several journal items, each of\n                which is either a debit or a credit transaction.\n              </p>\n            "}', '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295', 667, NULL, 80, 678, NULL, '{''default_move_type'': ''entry'', ''search_default_posted'':1, ''view_no_maturity'': True}', 'account.move', 'current', 'tree,kanban,form,activity', 'kanban', NULL, NULL);
INSERT INTO public.ir_act_window VALUES (253, NULL, 1, 1, 'ir.actions.act_window', 'action', 'list,form', '{"en_US": "Invoices"}', '{"en_US": "<p class=\"o_view_nocontent_smiling_face\">\n                Create a customer invoice\n              </p><p>\n                Create invoices, register payments and keep track of the discussions with your customers.\n              </p>\n            "}', '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295', 669, NULL, 80, 679, '[(''move_type'', ''='', ''out_invoice'')]', '{''default_move_type'': ''out_invoice''}', 'account.move', 'current', 'tree,kanban,form,activity', 'kanban', NULL, NULL);
INSERT INTO public.ir_act_window VALUES (254, NULL, 1, 1, 'ir.actions.act_window', 'action', 'list,form', '{"en_US": "Credit Notes"}', '{"en_US": "<p class=\"o_view_nocontent_smiling_face\">\n                Create a credit note\n              </p><p>\n                Note that the easiest way to create a credit note is to do it directly\n                from the customer invoice.\n              </p>\n            "}', '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295', 670, NULL, 80, 679, '[(''move_type'', ''='', ''out_refund'')]', '{''default_move_type'': ''out_refund'', ''display_account_trust'': True}', 'account.move', 'current', 'tree,kanban,form,activity', 'kanban', NULL, NULL);
INSERT INTO public.ir_act_window VALUES (255, NULL, 1, 1, 'ir.actions.act_window', 'action', 'list,form', '{"en_US": "Bills"}', '{"en_US": "<p class=\"o_view_nocontent_smiling_face\">\n                Create a vendor bill\n              </p><p>\n                Create invoices, register payments and keep track of the discussions with your vendors.\n              </p>\n            "}', '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295', 672, NULL, 80, 679, '[(''move_type'', ''='', ''in_invoice'')]', '{''default_move_type'': ''in_invoice'', ''display_account_trust'': True}', 'account.move', 'current', 'tree,kanban,form,activity', 'kanban', NULL, NULL);
INSERT INTO public.ir_act_window VALUES (256, NULL, 1, 1, 'ir.actions.act_window', 'action', 'list,form', '{"en_US": "Refunds"}', '{"en_US": "<p class=\"o_view_nocontent_smiling_face\">\n                Create a vendor credit note\n              </p><p>\n                Note that the easiest way to create a vendor credit note is to do it directly from the vendor bill.\n              </p>\n            "}', '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295', 673, NULL, 80, 679, '[(''move_type'', ''='', ''in_refund'')]', '{''default_move_type'': ''in_refund''}', 'account.move', 'current', 'tree,kanban,form,activity', 'kanban', NULL, NULL);
INSERT INTO public.ir_act_window VALUES (257, NULL, 1, 1, 'ir.actions.act_window', 'action', 'list,form', '{"en_US": "Customer Amounts to Settle"}', '{"en_US": "<p class=\"o_view_nocontent_smiling_face\">\n                    Amounts to settle\n                </p><p>\n                    Cool, it looks like you don''t have any customer credit notes to pay.\n                </p>\n            "}', '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295', 665, NULL, 80, 666, '[(''parent_state'', ''='', ''posted''), (''date_maturity'', ''!='', False), (''amount_residual'', ''>'', 0), (''account_id.reconcile'', ''='', True), (''journal_id.type'', ''='', ''sale'')]', '{}', 'account.move.line', 'current', 'tree', 'kanban', NULL, NULL);
INSERT INTO public.ir_act_window VALUES (258, NULL, 1, 1, 'ir.actions.act_window', 'action', 'list,form', '{"en_US": "Amounts to Settle"}', '{"en_US": "<p class=\"o_view_nocontent_smiling_face\">\n                    Amounts to settle\n                </p><p>\n                    Cool, it looks like you don''t have any vendor bills to pay.\n                </p>\n            "}', '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295', 665, NULL, 80, 666, '[(''parent_state'', ''='', ''posted''), (''date_maturity'', ''!='', False), (''amount_residual'', ''<'', 0), (''account_id.reconcile'', ''='', True), (''journal_id.type'', ''='', ''purchase'')]', '{}', 'account.move.line', 'current', 'tree', 'kanban', NULL, NULL);
INSERT INTO public.ir_act_window VALUES (259, NULL, 1, 1, 'ir.actions.act_window', 'action', 'list,form', '{"en_US": "Receipts"}', '{"en_US": "<p class=\"o_view_nocontent_smiling_face\">\n                Create a new sales receipt\n              </p><p>\n                When the sale receipt is confirmed, you can record the customer\n                payment related to this sales receipt.\n              </p>\n            "}', '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295', 668, NULL, 80, 679, '[(''move_type'', ''='', ''out_receipt'')]', '{''default_move_type'': ''out_receipt''}', 'account.move', 'current', 'tree,kanban,form,activity', 'kanban', NULL, NULL);
INSERT INTO public.ir_act_window VALUES (260, NULL, 1, 1, 'ir.actions.act_window', 'action', 'list,form', '{"en_US": "Receipts"}', '{"en_US": "<p class=\"o_view_nocontent_smiling_face\">\n                Register a new purchase receipt\n              </p><p>\n                When the purchase receipt is confirmed, you can record the\n                vendor payment related to this purchase receipt.\n              </p>\n            "}', '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295', 674, NULL, 80, 679, '[(''move_type'', ''='', ''in_receipt'')]', '{''default_move_type'': ''in_receipt'', ''display_account_trust'': True}', 'account.move', 'current', 'tree,kanban,form,activity', 'kanban', NULL, NULL);
INSERT INTO public.ir_act_window VALUES (261, NULL, 1, 1, 'ir.actions.act_window', 'action', 'list,form', '{"en_US": "Entries"}', NULL, '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295', 667, NULL, 80, 678, NULL, '{}', 'account.move', 'current', 'tree,form', 'kanban', NULL, NULL);
INSERT INTO public.ir_act_window VALUES (265, NULL, 1, 1, 'ir.actions.act_window', 'action', 'list,form', '{"en_US": "Chart of Accounts"}', '{"en_US": "<p class=\"o_view_nocontent_smiling_face\">\n                Add a new account\n              </p><p>\n                An account is part of a ledger allowing your company\n                to register all kinds of debit and credit transactions.\n                Companies present their annual accounts in two main parts: the\n                balance sheet and the income statement (profit and loss\n                account). The annual accounts of a company are required by law\n                to disclose a certain amount of information.\n              </p>\n            "}', '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295', 684, NULL, 80, 686, NULL, '{''search_default_activeacc'': True}', 'account.account', 'current', 'tree,kanban,form', 'kanban', NULL, NULL);
INSERT INTO public.ir_act_window VALUES (266, NULL, 1, 1, 'ir.actions.act_window', 'action', 'list,form', '{"en_US": "Journals"}', '{"en_US": "<p class=\"o_view_nocontent_smiling_face\">\n                Add a journal\n              </p><p>\n                A journal is used to record transactions of all accounting data\n                related to the day-to-day business.\n              </p>\n            "}', '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295', NULL, NULL, 80, NULL, NULL, '{}', 'account.journal', 'current', 'tree,kanban,form', 'kanban', NULL, NULL);
INSERT INTO public.ir_act_window VALUES (267, NULL, 1, 1, 'ir.actions.act_window', 'action', 'list,form', '{"en_US": "Journal Groups"}', '{"en_US": "<p class=\"o_view_nocontent_smiling_face\">\n                Add a journal group\n              </p><p>\n                Journal group are used in reporting to display relevant data together.\n              </p>\n            "}', '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295', NULL, NULL, 80, NULL, NULL, '{}', 'account.journal.group', 'current', 'tree,form', 'kanban', NULL, NULL);
INSERT INTO public.ir_act_window VALUES (268, NULL, 1, 1, 'ir.actions.act_window', 'action', 'list,form', '{"en_US": "Bank Statements"}', '{"en_US": "<p class=\"o_view_nocontent_smiling_face\">\n                Register a bank statement\n              </p><p>\n                A bank statement is a summary of all financial transactions\n                occurring over a given period of time on a bank account. You\n                should receive this periodically from your bank.\n              </p><p>\n                Odoo allows you to reconcile a statement line directly with\n                the related sale or purchase invoices.\n              </p>\n            "}', '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295', NULL, NULL, 80, 700, '[''|'', (''journal_id'', ''='', False), (''journal_id.type'', ''='', ''bank'')]', '{''journal_type'':''bank''}', 'account.bank.statement', 'current', 'tree,pivot,graph', 'kanban', NULL, NULL);
INSERT INTO public.ir_act_window VALUES (269, NULL, 1, 1, 'ir.actions.act_window', 'action', 'list,form', '{"en_US": "Cash Registers"}', '{"en_US": "<p class=\"o_view_nocontent_smiling_face\">\n                Create a new cash log\n              </p><p>\n                A Cash Register allows you to manage cash entries in your cash\n                journals. This feature provides an easy way to follow up cash\n                payments on a daily basis.\n              </p>\n            "}', '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295', 699, NULL, 80, 700, '[''|'', (''journal_id'', ''='', False), (''journal_id.type'', ''='', ''cash'')]', '{''journal_type'':''cash''}', 'account.bank.statement', 'current', 'tree,pivot,graph', 'kanban', NULL, NULL);
INSERT INTO public.ir_act_window VALUES (270, NULL, 1, 1, 'ir.actions.act_window', 'action', 'list,form', '{"en_US": "Reconciliation Models"}', '{"en_US": "<p class=\"o_view_nocontent_smiling_face\">\n                Create a new reconciliation model\n              </p><p>\n                Those can be used to quickly create a journal items when reconciling\n                a bank statement or an account.\n              </p>\n            "}', '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295', NULL, NULL, 80, 706, NULL, '{}', 'account.reconcile.model', 'current', 'tree,form', 'kanban', NULL, NULL);
