INSERT INTO public.ir_act_window VALUES (276, 451, 1, 1, 'ir.actions.act_window', 'action', 'list', '{"en_US": "Post entries"}', '{"en_US": "<p>This wizard will validate all journal entries selected. Once journal entries are validated, you can not update them anymore.</p>"}', '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295', 732, NULL, 80, NULL, NULL, '{}', 'validate.account.move', 'new', 'form', 'kanban', NULL, NULL);
