INSERT INTO public.ir_act_window VALUES (280, NULL, 1, 1, 'ir.actions.act_window', 'action', 'list,form', '{"en_US": "Invoices Analysis"}', '{"en_US": "<p>From this report, you can have an overview of the amount invoiced from your vendors. The search tool can also be used to personalise your Invoices reports and so, match this analysis to your needs.</p>"}', '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295', NULL, NULL, 80, 760, NULL, '{''search_default_current'':1, ''search_default_supplier'': 1, ''group_by'':[''invoice_date:month''], ''group_by_no_leaf'':1}', 'account.invoice.report', 'current', 'graph,pivot', 'kanban', NULL, NULL);
INSERT INTO public.ir_act_window VALUES (281, NULL, 1, 1, 'ir.actions.act_window', 'action', 'list,form', '{"en_US": "Invoices Analysis"}', '{"en_US": "<p>From this report, you can have an overview of the amount invoiced to your customers. The search tool can also be used to personalise your Invoices reports and so, match this analysis to your needs.</p>"}', '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295', NULL, NULL, 80, 760, NULL, '{''search_default_current'':1, ''search_default_customer'': 1, ''group_by'':[''invoice_date:month''], ''group_by_no_leaf'':1}', 'account.invoice.report', 'current', 'graph,pivot', 'kanban', NULL, NULL);
