INSERT INTO public.ir_act_window VALUES (285, NULL, 1, 1, 'ir.actions.act_window', 'action', 'list,form', '{"en_US": "Vendor Bills"}', '{"en_US": "<p class=\"o_view_nocontent_smiling_face\">\n                    Record a new vendor bill\n                </p><p>\n                Vendors bills can be pre-generated based on purchase\n                orders or receipts. This allows you to control bills\n                you receive from your vendor according to the draft\n                document in Odoo.\n            </p>\n            "}', '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295', NULL, NULL, 80, NULL, '[(''move_type'',''in'',(''in_invoice'', ''in_refund''))]', '{''search_default_partner_id'': active_id, ''default_move_type'': ''in_invoice'', ''default_partner_id'': active_id}', 'account.move', 'current', 'tree,form,graph', 'kanban', NULL, NULL);
