INSERT INTO public.ir_act_window VALUES (288, NULL, 1, 1, 'ir.actions.act_window', 'action', 'list,form', '{"en_US": "Vendors"}', '{"en_US": "<p class=\"o_view_nocontent_smiling_face\">\n                Create a new supplier in your address book\n              </p><p>\n                Odoo helps you easily track all activities related to a supplier.\n              </p>\n            "}', '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295', NULL, NULL, 80, NULL, NULL, '{''search_default_supplier'': 1,''res_partner_search_mode'': ''supplier'', ''default_is_company'': True, ''default_supplier_rank'': 1}', 'res.partner', 'current', 'kanban,tree,form', 'kanban', NULL, NULL);
INSERT INTO public.ir_act_window VALUES (289, NULL, 1, 1, 'ir.actions.act_window', 'action', 'list,form', '{"en_US": "Accounting Dashboard"}', '{"en_US": "<p class=\"o_view_nocontent_neutral_face\">\n                This is the accounting dashboard\n            </p><p>\n                If you have not installed a chart of account, please install one first.<br>\n               <a class=\"btn-link\" type=\"action\" name=\"283\" tabindex=\"-1\">Browse available countries.</a>\n            </p>\n        "}', '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295', 772, NULL, 80, NULL, '[]', '{''search_default_dashboard'':1}', 'account.journal', 'current', 'kanban,form', 'kanban', 'menu', NULL);
INSERT INTO public.ir_act_window VALUES (292, NULL, 1, 1, 'ir.actions.act_window', 'action', 'list,form', '{"en_US": "Incoterms"}', '{"en_US": "<p class=\"o_view_nocontent_smiling_face\">\n                Create a new incoterm\n              </p><p>\n                Incoterms are used to divide transaction costs and responsibilities between buyer and seller.\n              </p>\n            "}', '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295', NULL, NULL, 80, NULL, NULL, '{}', 'account.incoterms', 'current', 'tree,form', 'kanban', NULL, NULL);
INSERT INTO public.ir_act_window VALUES (146, NULL, 1, 1, 'ir.actions.act_window', 'action', 'list,form', '{"en_US": "Analytic Items"}', '{"en_US": "<p class=\"o_view_nocontent_empty_folder\">\n               No activity yet\n            </p><p>\n                In Odoo, sales orders and projects are implemented using\n                analytic accounts. You can track costs and revenues to analyse\n                your margins easily.\n            </p><p>\n                Costs will be created automatically when you register supplier\n                invoices, expenses or timesheets.\n            </p><p>\n                Revenues will be created automatically when you create customer\n                invoices. Customer invoices can be created based on sales orders\n                (fixed price invoices), on timesheets (based on the work done) or\n                on expenses (e.g. reinvoicing of travel costs).\n            </p>\n        "}', '2026-05-10 01:11:46.819771', '2026-05-10 01:11:56.885295', 402, NULL, 80, 747, NULL, '{''search_default_group_by_analytic_account'': 1}', 'account.analytic.line', 'current', 'tree,kanban,form,graph,pivot', 'kanban', NULL, NULL);
