INSERT INTO public.ir_act_window VALUES (318, NULL, 1, 1, 'ir.actions.act_window', 'action', 'list,form', '{"en_US": "Orders to Upsell"}', '{"en_US": "<p class=\"o_view_nocontent_smiling_face\">\n            No orders to upsell found.\n            </p><p>\n            An order is to upsell when delivered quantities are above initially\n            ordered quantities, and the invoicing policy is based on ordered quantities.\n            </p><p>\n            As an example, if you sell pre-paid hours of services, Odoo recommends you\n            to sell extra hours when all ordered hours have been consumed.\n            </p>\n        "}', '2026-05-10 01:12:05.269262', '2026-05-10 01:12:05.269262', NULL, NULL, 80, 884, '[(''invoice_status'',''='',''upselling'')]', '{''create'': False}', 'sale.order', 'current', 'tree,form,calendar,graph,pivot,kanban,activity', 'kanban', NULL, NULL);
