INSERT INTO public.ir_act_window VALUES (400, NULL, 1, 1, 'ir.actions.act_window', 'action', 'list,form', '{"en_US": "Inventory Overview"}', '{"en_US": "<p class=\"o_view_nocontent_smiling_face\">\n            Create a new operation type\n            </p><p>\n            The operation type system allows you to assign each stock\n            operation a specific type which will alter its views accordingly.\n            On the operation type you could e.g. specify if packing is needed by default,\n            if it should show the customer.\n            </p>\n        "}', '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', NULL, NULL, 80, NULL, NULL, '{}', 'stock.picking.type', 'current', 'kanban,form', 'kanban', NULL, NULL);
