INSERT INTO public.ir_act_window VALUES (404, NULL, 1, 1, 'ir.actions.act_window', 'action', 'list,form', '{"en_US": "Products"}', '{"en_US": "<p class=\"o_view_nocontent_smiling_face\">\n                    No product found. Let''s create one!\n                </p><p>\n                    Track your stock quantities by creating storable products.\n                </p>\n            "}', '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', NULL, NULL, 80, 1070, NULL, '{"search_default_consumable": 1, ''default_detailed_type'': ''product''}', 'product.template', 'current', 'kanban,tree,form', 'kanban', NULL, NULL);
