INSERT INTO public.ir_act_window VALUES (407, NULL, 1, 1, 'ir.actions.act_window', 'action', 'list,form', '{"en_US": "Locations"}', NULL, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', NULL, NULL, 80, NULL, '[(''storage_category_id'', ''='', active_id)]', '{}', 'stock.location', 'current', 'tree,form', 'kanban', NULL, NULL);
INSERT INTO public.ir_act_window VALUES (408, NULL, 1, 1, 'ir.actions.act_window', 'action', 'list,form', '{"en_US": "Locations"}', '{"en_US": "<p class=\"o_view_nocontent_smiling_face\">\n            Add a new location\n          </p><p>\n            Define your locations to reflect your warehouse structure and\n            organization. Odoo is able to manage physical locations\n            (warehouses, shelves, bin, etc), partner locations (customers,\n            vendors) and virtual locations which are the counterpart of\n            the stock operations like the manufacturing orders\n            consumptions, inventories, etc.\n          </p><p>\n            Every stock operation in Odoo moves the products from one\n            location to another one.  For instance, if you receive products\n            from a vendor, Odoo will move products from the Vendor\n            location to the Stock location. Each report can be performed on\n            physical, partner or virtual locations.\n          </p>\n        "}', '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', 1086, NULL, 80, 1085, NULL, '{''search_default_in_location'':1}', 'stock.location', 'current', 'tree,form', 'kanban', NULL, NULL);
INSERT INTO public.ir_act_window VALUES (409, NULL, 1, 1, 'ir.actions.act_window', 'action', 'list,form', '{"en_US": "Locations"}', NULL, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', 1086, NULL, 80, 1085, NULL, '{''search_default_prod_inv_location'': 1}', 'stock.location', 'current', 'tree,form', 'kanban', NULL, NULL);
INSERT INTO public.ir_act_window VALUES (410, NULL, 1, 1, 'ir.actions.act_window', 'action', 'list,form', '{"en_US": "Routes"}', '{"en_US": "<p class=\"o_view_nocontent_smiling_face\">\n                Add a new route\n              </p><p>\n                You can define here the main routes that run through\n                your warehouses and that define the flows of your products. These\n                routes can be assigned to a product, a product category or be fixed\n                on procurement or sales order.\n              </p>\n            "}', '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', 1088, NULL, 80, NULL, NULL, '{}', 'stock.route', 'current', 'tree,form', 'kanban', NULL, NULL);
INSERT INTO public.ir_act_window VALUES (411, NULL, 1, 1, 'ir.actions.act_window', 'action', 'list,form', '{"en_US": "Replenishment"}', '{"en_US": "<p class=\"o_view_nocontent_replenishment\">\n            You are good, no replenishment to perform!\n          </p><p>\n            You''ll find here smart replenishment propositions based on inventory forecasts.\n            Choose the quantity to buy or manufacture and launch orders in a click.\n            To save time in the future, set the rules as \"automated\".\n          </p>\n        "}', '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', 1092, NULL, 80, 1093, NULL, '{}', 'stock.warehouse.orderpoint', 'current', 'tree', 'kanban', NULL, NULL);
INSERT INTO public.ir_act_window VALUES (412, NULL, 1, 1, 'ir.actions.act_window', 'action', 'list,form', '{"en_US": "Reordering Rules"}', '{"en_US": "<p class=\"o_view_nocontent_smiling_face\">\n            No reordering rule found\n          </p><p>\n            Define a minimum stock rule so that Odoo automatically creates requests for quotations or confirmed manufacturing orders to resupply your stock.\n          </p>\n        "}', '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', 1092, NULL, 80, 1094, NULL, '{''search_default_trigger'': ''auto''}', 'stock.warehouse.orderpoint', 'current', 'tree,kanban,form', 'kanban', NULL, NULL);
INSERT INTO public.ir_act_window VALUES (414, NULL, 1, 1, 'ir.actions.act_window', 'action', 'list,form', '{"en_US": "Storage Categories"}', '{"en_US": "<p class=\"o_view_nocontent_smiling_face\">\n                Add a new storage category\n            </p>\n        "}', '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', 1097, NULL, 80, NULL, NULL, '{}', 'stock.storage.category', 'current', 'tree,form', 'kanban', NULL, NULL);
