INSERT INTO public.ir_act_window VALUES (416, NULL, 1, 1, 'ir.actions.act_window', 'action', 'list,form', '{"en_US": "Settings"}', NULL, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', NULL, NULL, 80, NULL, NULL, '{''module'' : ''stock'', ''bin_size'': False}', 'res.config.settings', 'inline', 'form', 'kanban', NULL, NULL);
