INSERT INTO public.ir_act_window VALUES (421, NULL, 1, 1, 'ir.actions.act_window', 'action', 'list,form', '{"en_US": "Stock Valuation"}', '{"en_US": "<p class=\"o_view_nocontent_smiling_face\"></p>\n            <p>\n                There are no valuation layers. Valuation layers are created when there are product moves that impact the valuation of the stock.\n            </p>\n        "}', '2026-05-10 01:12:23.260984', '2026-05-10 01:12:23.260984', 1121, NULL, 80, NULL, '[(''product_id.type'', ''='', ''product'')]', '{''search_default_group_by_product_id'': True}', 'stock.valuation.layer', 'current', 'tree,form,pivot', 'kanban', NULL, NULL);
INSERT INTO public.ir_act_window VALUES (423, NULL, 1, 1, 'ir.actions.act_window', 'action', 'list,form', '{"en_US": "Inventory Aging"}', '{"en_US": "<p class=\"o_view_nocontent_smiling_face\"></p>\n            <p>\n                There are no valuation layers. Valuation layers are created when there are product moves that impact the valuation of the stock.\n            </p>\n        "}', '2026-05-10 01:12:23.260984', '2026-05-10 01:12:23.260984', NULL, NULL, 80, NULL, '[(''product_id.type'', ''='', ''product'')]', '{
            ''search_default_has_remaining_qty'': True,
            ''search_default_incoming'': True,
            ''pivot_column_groupby'': [''create_date:month''],
            ''pivot_row_groupby'': [''categ_id''],
            ''pivot_measures'': [''remaining_qty'', ''remaining_value''],
            ''graph_mode'': ''bar'',
            ''graph_groupbys'': [''create_date:month''],
            }', 'stock.valuation.layer', 'current', 'pivot,tree,graph', 'kanban', NULL, NULL);
INSERT INTO public.ir_act_window VALUES (428, NULL, 1, 1, 'ir.actions.act_window', 'action', 'list,form', '{"en_US": "Products"}', '{"en_US": "<p class=\"o_view_nocontent_smiling_face\">\n            No product found. Let''s create one!\n          </p><p>\n            You must define a product for everything you sell or purchase,\n            whether it''s a storable product, a consumable or a service.\n          </p>\n        "}', '2026-05-10 01:12:29.662147', '2026-05-10 01:12:29.662147', NULL, NULL, 80, 454, NULL, '{"search_default_filter_to_purchase":1, "purchase_product_template": 1}', 'product.template', 'current', 'kanban,tree,form,activity', 'kanban', NULL, NULL);
INSERT INTO public.ir_act_window VALUES (429, NULL, 1, 1, 'ir.actions.act_window', 'action', 'list,form', '{"en_US": "Product Variants"}', '{"en_US": "<p class=\"o_view_nocontent_smiling_face\">\n                Create a new product variant\n              </p><p>\n                You must define a product for everything you sell or purchase,\n                whether it''s a storable product, a consumable or a service.\n              </p>\n            "}', '2026-05-10 01:12:29.662147', '2026-05-10 01:12:29.662147', NULL, NULL, 80, 455, NULL, '{"search_default_filter_to_purchase": 1}', 'product.product', 'current', 'tree,kanban,form,activity', 'kanban', NULL, NULL);
INSERT INTO public.ir_act_window VALUES (430, NULL, 1, 1, 'ir.actions.act_window', 'action', 'list,form', '{"en_US": "Requests for Quotation"}', '{"en_US": "<p class=\"o_view_nocontent_smiling_face\">\n                No request for quotation found. Let''s create one!\n              </p><p>\n                Requests for quotation are documents that will be sent to your suppliers to request prices for different products you consider buying.\n                Once an agreement has been found with the supplier, they will be confirmed and turned into purchase orders.\n              </p>\n            "}', '2026-05-10 01:12:29.662147', '2026-05-10 01:12:29.662147', 1167, NULL, 80, 1162, '[]', '{''quotation_only'': True}', 'purchase.order', 'current', 'tree,kanban,form,pivot,graph,calendar,activity', 'kanban', NULL, NULL);
INSERT INTO public.ir_act_window VALUES (431, NULL, 1, 1, 'ir.actions.act_window', 'action', 'list,form', '{"en_US": "Purchase Orders"}', '{"en_US": "<p class=\"o_view_nocontent_smiling_face\">\n                No purchase order found. Let''s create one!\n              </p><p>\n                Once you ordered your products to your supplier, confirm your request for quotation and it will turn into a purchase order.\n              </p>\n            "}', '2026-05-10 01:12:29.662147', '2026-05-10 01:12:29.662147', NULL, NULL, 80, 1163, '[(''state'',''in'',(''purchase'', ''done''))]', '{}', 'purchase.order', 'current', 'tree,kanban,form,pivot,graph,calendar,activity', 'kanban', NULL, NULL);
INSERT INTO public.ir_act_window VALUES (432, NULL, 1, 1, 'ir.actions.act_window', 'action', 'list,form', '{"en_US": "Purchase Order Line"}', '{"en_US": "<p class=\"o_view_nocontent_smiling_face\">\n                No purchase order were made for this product yet!\n            </p>\n        "}', '2026-05-10 01:12:29.662147', '2026-05-10 01:12:29.662147', 1173, NULL, 80, NULL, NULL, '{}', 'purchase.order.line', 'current', 'tree', 'kanban', NULL, NULL);
