INSERT INTO public.ir_act_window VALUES (436, NULL, 1, 1, 'ir.actions.act_window', 'action', 'list,form', '{"en_US": "Requests for Quotation"}', NULL, '2026-05-10 01:12:29.662147', '2026-05-10 01:12:29.662147', 1161, NULL, 80, 1162, NULL, '{}', 'purchase.order', 'main', 'form', 'kanban', NULL, NULL);
