INSERT INTO public.ir_act_window VALUES (438, NULL, 1, 1, 'ir.actions.act_window', 'action', 'list,form', '{"en_US": "RFQs and Purchases"}', '{"en_US": "<p class=\"o_view_nocontent_smiling_face\">\n                    This vendor has no purchase order. Create a new RfQ\n                </p><p>\n                    The request for quotation is the first step of the purchases flow. Once\n                    converted into a purchase order, you will be able to control the receipt\n                    of the products and the vendor bill.\n                </p>\n            "}', '2026-05-10 01:12:29.662147', '2026-05-10 01:12:29.662147', NULL, NULL, 80, NULL, NULL, '{''search_default_partner_id'': active_id, ''default_partner_id'': active_id}', 'purchase.order', 'current', 'tree,kanban,form,graph', 'kanban', NULL, NULL);
INSERT INTO public.ir_act_window VALUES (439, NULL, 1, 1, 'ir.actions.act_window', 'action', 'list,form', '{"en_US": "Vendor Bills"}', '{"en_US": "<p class=\"o_view_nocontent_smiling_face\">\n                    Record a new vendor bill\n                </p><p>\n                    Vendors bills can be pre-generated based on purchase\n                    orders or receipts. This allows you to control bills\n                    you receive from your vendor according to the draft\n                    document in Odoo.\n                </p>\n            "}', '2026-05-10 01:12:29.662147', '2026-05-10 01:12:29.662147', NULL, NULL, 80, NULL, '[(''move_type'',''in'',(''in_invoice'', ''in_refund''))]', '{''search_default_partner_id'': active_id, ''default_move_type'': ''in_invoice'', ''default_partner_id'': active_id}', 'account.move', 'current', 'tree,form,graph', 'kanban', NULL, NULL);
INSERT INTO public.ir_act_window VALUES (440, NULL, 1, 1, 'ir.actions.act_window', 'action', 'list,form', '{"en_US": "Purchase Analysis"}', '{"en_US": "<p class=\"o_view_nocontent_smiling_face\">\n                No Purchase Analysis\n            </p><p>\n                This analysis allows you to easily check and analyse your company purchase history and performance.\n                You can track your negotiation performance, the delivery performance of your vendors, etc\n            </p>\n        "}', '2026-05-10 01:12:29.662147', '2026-05-10 01:12:29.662147', NULL, NULL, 80, NULL, NULL, '{''search_default_orders'': 1, ''search_default_filter_date_approve'': 1}', 'purchase.report', 'current', 'graph,pivot', 'kanban', NULL, NULL);
INSERT INTO public.ir_act_window VALUES (441, NULL, 1, 1, 'ir.actions.act_window', 'action', 'list,form', '{"en_US": "On-time Delivery"}', '{"en_US": "<p>Vendor On-time Delivery analysis</p>"}', '2026-05-10 01:12:32.247193', '2026-05-10 01:12:32.247193', NULL, NULL, 80, 1213, NULL, '{''search_default_later_than_a_year_ago'':1}', 'vendor.delay.report', 'current', 'graph', 'kanban', NULL, NULL);


