INSERT INTO public.ir_model_constraint VALUES (1, 3, 36, 1, 1, 'ir_model_obj_name_uniq', 'unique(model)', 'u', '{"en_US": "Each model must have a unique name."}', '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872');
INSERT INTO public.ir_model_constraint VALUES (2, 4, 36, 1, 1, 'ir_model_fields_name_unique', 'unique(model,name)', 'u', '{"en_US": "Field names must be unique per model."}', '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872');
INSERT INTO public.ir_model_constraint VALUES (3, 4, 36, 1, 1, 'ir_model_fields_size_gt_zero', 'check(size>=0)', 'u', '{"en_US": "Size of the field cannot be negative."}', '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872');
INSERT INTO public.ir_model_constraint VALUES (4, 4, 36, 1, 1, 'ir_model_fields_name_manual_field', 'check(state != ''manual'' or name like ''x\_%'')', 'u', '{"en_US": "Custom fields must have a name that starts with ''x_''!"}', '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872');
INSERT INTO public.ir_model_constraint VALUES (5, 5, 36, 1, 1, 'ir_model_inherit_uniq', 'unique(model_id,parent_id)', 'u', '{"en_US": "Models inherits from another only once"}', '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872');
INSERT INTO public.ir_model_constraint VALUES (6, 6, 36, 1, 1, 'ir_model_fields_selection_selection_field_uniq', 'unique(field_id,value)', 'u', '{"en_US": "Selections values must be unique per field"}', '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872');
INSERT INTO public.ir_model_constraint VALUES (7, 7, 36, 1, 1, 'ir_model_constraint_module_name_uniq', 'unique(name,module)', 'u', '{"en_US": "Constraints with the same name are unique per module."}', '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872');
INSERT INTO public.ir_model_constraint VALUES (8, 10, 36, 1, 1, 'ir_model_data_name_nospaces', 'check(name not like ''% %'')', 'u', '{"en_US": "External IDs cannot contain spaces"}', '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872');
INSERT INTO public.ir_model_constraint VALUES (9, 13, 36, 1, 1, 'ir_sequence_date_range_unique_range_per_sequence', 'unique(sequence_id,date_from,date_to)', 'u', '{"en_US": "You cannot create two date ranges for the same sequence with the same date range."}', '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872');
INSERT INTO public.ir_model_constraint VALUES (10, 16, 36, 1, 1, 'ir_ui_view_inheritance_mode', 'check(mode != ''extension'' or inherit_id is not null)', 'u', '{"en_US": "Invalid inheritance mode: if the mode is ''extension'', the view must extend an other view"}', '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872');
INSERT INTO public.ir_model_constraint VALUES (11, 16, 36, 1, 1, 'ir_ui_view_qweb_required_key', 'check(type != ''qweb'' or key is not null)', 'u', '{"en_US": "Invalid key: QWeb view should have a key"}', '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872');
INSERT INTO public.ir_model_constraint VALUES (12, 32, 36, 1, 1, 'ir_filters_name_model_uid_unique', 'unique(model_id,user_id,action_id,name)', 'u', '{"en_US": "Filter names must be unique"}', '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872');
INSERT INTO public.ir_model_constraint VALUES (13, 36, 36, 1, 1, 'ir_rule_no_access_rights', 'check(perm_read!=false or perm_write!=false or perm_create!=false or perm_unlink!=false)', 'u', '{"en_US": "Rule must have at least one checked access right!"}', '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872');
INSERT INTO public.ir_model_constraint VALUES (14, 37, 36, 1, 1, 'ir_config_parameter_key_uniq', 'unique(key)', 'u', '{"en_US": "Key must be unique."}', '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872');
INSERT INTO public.ir_model_constraint VALUES (15, 67, 36, 1, 1, 'ir_module_module_name_uniq', 'unique(name)', 'u', '{"en_US": "The name of the module must be unique!"}', '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872');
INSERT INTO public.ir_model_constraint VALUES (16, 79, 36, 1, 1, 'res_country_name_uniq', 'unique(name)', 'u', '{"en_US": "The name of the country must be unique!"}', '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872');
INSERT INTO public.ir_model_constraint VALUES (17, 79, 36, 1, 1, 'res_country_code_uniq', 'unique(code)', 'u', '{"en_US": "The code of the country must be unique!"}', '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872');
INSERT INTO public.ir_model_constraint VALUES (18, 81, 36, 1, 1, 'res_country_state_name_code_uniq', 'unique(country_id,code)', 'u', '{"en_US": "The code of the state must be unique by country!"}', '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872');
INSERT INTO public.ir_model_constraint VALUES (19, 82, 36, 1, 1, 'res_lang_name_uniq', 'unique(name)', 'u', '{"en_US": "The name of the language must be unique!"}', '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872');
INSERT INTO public.ir_model_constraint VALUES (20, 82, 36, 1, 1, 'res_lang_code_uniq', 'unique(code)', 'u', '{"en_US": "The code of the language must be unique!"}', '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872');
INSERT INTO public.ir_model_constraint VALUES (21, 82, 36, 1, 1, 'res_lang_url_code_uniq', 'unique(url_code)', 'u', '{"en_US": "The URL code of the language must be unique!"}', '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872');
INSERT INTO public.ir_model_constraint VALUES (22, 86, 36, 1, 1, 'res_partner_check_name', 'check((type=''contact'' and name is not null) or(type!=''contact'') )', 'u', '{"en_US": "Contacts require a name"}', '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872');
INSERT INTO public.ir_model_constraint VALUES (23, 89, 36, 1, 1, 'res_partner_bank_unique_number', 'unique(sanitized_acc_number,partner_id)', 'u', '{"en_US": "The combination Account Number/Partner must be unique."}', '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872');
INSERT INTO public.ir_model_constraint VALUES (24, 93, 36, 1, 1, 'res_currency_unique_name', 'unique(name)', 'u', '{"en_US": "The currency code must be unique!"}', '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872');
INSERT INTO public.ir_model_constraint VALUES (25, 93, 36, 1, 1, 'res_currency_rounding_gt_zero', 'check(rounding>0)', 'u', '{"en_US": "The rounding factor must be greater than 0!"}', '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872');
INSERT INTO public.ir_model_constraint VALUES (26, 94, 36, 1, 1, 'res_currency_rate_unique_name_per_day', 'unique(name,currency_id,company_id)', 'u', '{"en_US": "Only one currency rate per day allowed!"}', '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872');
