INSERT INTO public.ir_model_constraint VALUES (28, 95, 36, 1, 1, 'res_company_name_uniq', 'unique(name)', 'u', '{"en_US": "The company name must be unique!"}', '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872');
INSERT INTO public.ir_model_constraint VALUES (29, 96, 36, 1, 1, 'res_groups_name_uniq', 'unique(category_id,name)', 'u', '{"en_US": "The name of the group must be unique within an application!"}', '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872');
INSERT INTO public.ir_model_constraint VALUES (30, 98, 36, 1, 1, 'res_users_login_key', 'unique(login)', 'u', '{"en_US": "You can not have two users with the same login!"}', '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872');
