INSERT INTO public.ir_model_constraint VALUES (906, 452, 1, 1, 1, 'account_move_line_check_credit_debit', 'check(display_type in(''line_section'',''line_note'') or credit * debit=0)', 'u', '{"en_US": "Wrong credit or debit value in accounting entry!"}', '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295');
INSERT INTO public.ir_model_constraint VALUES (907, 452, 1, 1, 1, 'account_move_line_check_amount_currency_balance_sign', 'check(
                display_type in(''line_section'',''line_note'')
                or(
                   (balance <= 0 and amount_currency <= 0)
                    or
                   (balance >= 0 and amount_currency >= 0)
                )
            )', 'u', '{"en_US": "The amount expressed in the secondary currency must be positive when account is debited and negative when account is credited. If the currency is the same as the one from the company, this amount must strictly be equal to the balance."}', '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295');
INSERT INTO public.ir_model_constraint VALUES (908, 452, 1, 1, 1, 'account_move_line_check_accountable_required_fields', 'check(display_type in(''line_section'',''line_note'') or account_id is not null)', 'u', '{"en_US": "Missing required account on accountable line."}', '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295');
INSERT INTO public.ir_model_constraint VALUES (909, 452, 1, 1, 1, 'account_move_line_check_non_accountable_fields_null', 'check(display_type not in(''line_section'',''line_note'') or(amount_currency = 0 and debit = 0 and credit = 0 and account_id is null))', 'u', '{"en_US": "Forbidden balance or account on non-accountable line"}', '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295');
INSERT INTO public.ir_model_constraint VALUES (910, 455, 1, 1, 1, 'account_payment_check_amount_not_negative', 'check(amount >= 0.0)', 'u', '{"en_US": "The payment amount cannot be negative."}', '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295');
INSERT INTO public.ir_model_constraint VALUES (911, 456, 1, 1, 1, 'account_payment_method_name_code_unique', 'unique(code,payment_type)', 'u', '{"en_US": "The combination code/payment type already exists!"}', '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295');
INSERT INTO public.ir_model_constraint VALUES (912, 465, 1, 1, 1, 'account_report_line_code_uniq', 'unique(report_id,code)', 'u', '{"en_US": "A report line with the same code already exists."}', '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295');
INSERT INTO public.ir_model_constraint VALUES (913, 466, 1, 1, 1, 'account_report_expression_domain_engine_subformula_required', 'check(engine != ''domain'' or subformula is not null)', 'u', '{"en_US": "Expressions using ''domain'' engine should all have a subformula."}', '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295');
INSERT INTO public.ir_model_constraint VALUES (914, 466, 1, 1, 1, 'account_report_expression_line_label_uniq', 'unique(report_line_id,label)', 'u', '{"en_US": "The expression label must be unique per report line."}', '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295');
