INSERT INTO public.ir_model_fields VALUES (340, NULL, 24, NULL, NULL, NULL, NULL, 'state', NULL, 'ir.actions.server', NULL, NULL, 'selection', NULL, 'base', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"en_US": "Type"}', '{"en_US": "Type of server action. The following values are available:\n- ''Update a Record'': update the values of a record\n- ''Create Activity'': create an activity (Discuss)\n- ''Send Email'': post a message, a note or send an email (Discuss)\n- ''Send SMS'': send SMS, log them on documents (SMS)- ''Add/Remove Followers'': add or remove followers to a record (Discuss)\n- ''Create Record'': create a new record with new values\n- ''Execute Code'': a block of Python code that will be executed\n- ''Send Webhook Notification'': send a POST request to an external system, also known as a Webhook\n- ''Execute Existing Actions'': define an action that triggers several other server actions\n"}', NULL, true, true, false, false, false, NULL, true, true, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
