INSERT INTO public.ir_model_fields VALUES (4158, NULL, 442, NULL, NULL, NULL, NULL, 'payment_sequence', NULL, 'account.journal', NULL, NULL, 'boolean', NULL, 'base', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"en_US": "Dedicated Payment Sequence"}', '{"en_US": "Check this box if you don''t want to share the same sequence on payments and bank transactions posted on this journal"}', NULL, true, false, false, false, false, NULL, true, true, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.ir_model_fields VALUES (4159, NULL, 442, NULL, NULL, NULL, NULL, 'sequence_override_regex', NULL, 'account.journal', NULL, NULL, 'text', NULL, 'base', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"en_US": "Sequence Override Regex"}', '{"en_US": "Technical field used to enforce complex sequence composition that the system would normally misunderstand.\nThis is a regex that can include all the following capture groups: prefix1, year, prefix2, month, prefix3, seq, suffix.\nThe prefix* groups are the separators between the year, month and the actual increasing sequence number (seq).\ne.g: ^(?P<prefix1>.*?)(?P<year>\\d{4})(?P<prefix2>\\D*?)(?P<month>\\d{2})(?P<prefix3>\\D+?)(?P<seq>\\d+)(?P<suffix>\\D*?)$"}', NULL, true, false, false, false, false, NULL, true, true, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.ir_model_fields VALUES (4160, NULL, 442, NULL, NULL, NULL, NULL, 'inbound_payment_method_line_ids', NULL, 'account.journal', 'account.payment.method.line', 'journal_id', 'one2many', NULL, 'base', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"en_US": "Inbound Payment Methods"}', '{"en_US": "Manual: Get paid by any method outside of Odoo.\nPayment Providers: Each payment provider has its own Payment Method. Request a transaction on/to a card thanks to a payment token saved by the partner when buying or subscribing online.\nBatch Deposit: Collect several customer checks at once generating and submitting a batch deposit to your bank. Module account_batch_payment is necessary.\nSEPA Direct Debit: Get paid in the SEPA zone thanks to a mandate your partner will have granted to you. Module account_sepa is necessary.\n"}', NULL, false, false, false, false, false, NULL, true, true, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.ir_model_fields VALUES (4161, NULL, 442, NULL, NULL, NULL, NULL, 'outbound_payment_method_line_ids', NULL, 'account.journal', 'account.payment.method.line', 'journal_id', 'one2many', NULL, 'base', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"en_US": "Outbound Payment Methods"}', '{"en_US": "Manual: Pay by any method outside of Odoo.\nCheck: Pay bills by check and print it from Odoo.\nSEPA Credit Transfer: Pay in the SEPA zone by submitting a SEPA Credit Transfer file to your bank. Module account_sepa is necessary.\n"}', NULL, false, false, false, false, false, NULL, true, true, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
