INSERT INTO public.ir_model_fields VALUES (4225, NULL, 444, NULL, NULL, NULL, NULL, 'amount_type', NULL, 'account.tax', NULL, NULL, 'selection', NULL, 'base', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"en_US": "Tax Computation"}', '{"en_US": "\n    - Group of Taxes: The tax is a set of sub taxes.\n    - Fixed: The tax amount stays the same whatever the price.\n    - Percentage of Price: The tax amount is a % of the price:\n        e.g 100 * (1 + 10%) = 110 (not price included)\n        e.g 110 / (1 + 10%) = 100 (price included)\n    - Percentage of Price Tax Included: The tax amount is a division of the price:\n        e.g 180 / (1 - 10%) = 200 (not price included)\n        e.g 200 * (1 - 10%) = 180 (price included)\n        "}', NULL, true, true, false, false, false, NULL, true, true, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 100);
