INSERT INTO public.ir_model_fields VALUES (6169, NULL, 455, NULL, NULL, NULL, NULL, 'check_number', NULL, 'account.payment', NULL, NULL, 'char', NULL, 'base', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"en_US": "Check Number"}', '{"en_US": "The selected journal is configured to print check numbers. If your pre-printed check paper already has numbers or if the current numbering is wrong, you can change it in the journal configuration page."}', NULL, false, false, true, false, false, NULL, true, true, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
