INSERT INTO public.ir_model_fields VALUES (6298, NULL, 518, NULL, NULL, NULL, NULL, 'removal_strategy_id', NULL, 'stock.location', 'product.removal', NULL, 'many2one', NULL, 'base', 'set null', NULL, NULL, NULL, NULL, NULL, NULL, '{"en_US": "Removal Strategy"}', '{"en_US": "Defines the default method used for suggesting the exact location (shelf) where to take the products from, which lot etc. for this location. This method can be enforced at the product category level, and a fallback is made on the parent locations if none is set here.\n\nFIFO: products/lots that were stocked first will be moved out first.\nLIFO: products/lots that were stocked last will be moved out first.\nCloset location: products/lots closest to the target location will be moved out first.\nFEFO: products/lots with the closest removal date will be moved out first (the availability of this method depends on the \"Expiration Dates\" setting)."}', NULL, true, false, false, false, false, NULL, true, true, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
