INSERT INTO public.ir_model_fields VALUES (6353, NULL, 520, NULL, NULL, NULL, NULL, 'location_id', NULL, 'stock.move', 'stock.location', NULL, 'many2one', NULL, 'base', 'restrict', NULL, NULL, NULL, NULL, NULL, NULL, '{"en_US": "Source Location"}', '{"en_US": "Sets a location if you produce at a fixed location. This can be a partner location if you subcontract the manufacturing operations."}', NULL, true, true, false, true, false, NULL, true, true, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.ir_model_fields VALUES (6354, NULL, 520, NULL, NULL, NULL, NULL, 'location_dest_id', NULL, 'stock.move', 'stock.location', NULL, 'many2one', NULL, 'base', 'restrict', NULL, NULL, NULL, NULL, NULL, NULL, '{"en_US": "Destination Location"}', '{"en_US": "Location where the system will stock the finished products."}', NULL, true, true, false, true, false, NULL, true, true, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.ir_model_fields VALUES (6355, NULL, 520, NULL, NULL, NULL, NULL, 'location_usage', NULL, 'stock.move', NULL, NULL, 'selection', 'location_id.usage', 'base', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"en_US": "Source Location Type"}', '{"en_US": "* Vendor Location: Virtual location representing the source location for products coming from your vendors\n* View: Virtual location used to create a hierarchical structures for your warehouse, aggregating its child locations ; can''t directly contain products\n* Internal Location: Physical locations inside your own warehouses,\n* Customer Location: Virtual location representing the destination location for products sent to your customers\n* Inventory Loss: Virtual location serving as counterpart for inventory operations used to correct stock levels (Physical inventories)\n* Production: Virtual counterpart location for production operations: this location consumes the components and produces finished products\n* Transit Location: Counterpart location that should be used in inter-company or inter-warehouses operations"}', NULL, false, false, true, false, false, NULL, true, false, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.ir_model_fields VALUES (6356, NULL, 520, NULL, NULL, NULL, NULL, 'location_dest_usage', NULL, 'stock.move', NULL, NULL, 'selection', 'location_dest_id.usage', 'base', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"en_US": "Destination Location Type"}', '{"en_US": "* Vendor Location: Virtual location representing the source location for products coming from your vendors\n* View: Virtual location used to create a hierarchical structures for your warehouse, aggregating its child locations ; can''t directly contain products\n* Internal Location: Physical locations inside your own warehouses,\n* Customer Location: Virtual location representing the destination location for products sent to your customers\n* Inventory Loss: Virtual location serving as counterpart for inventory operations used to correct stock levels (Physical inventories)\n* Production: Virtual counterpart location for production operations: this location consumes the components and produces finished products\n* Transit Location: Counterpart location that should be used in inter-company or inter-warehouses operations"}', NULL, false, false, true, false, false, NULL, true, false, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
