INSERT INTO public.ir_model_fields VALUES (6361, NULL, 520, NULL, NULL, NULL, NULL, 'state', NULL, 'stock.move', NULL, NULL, 'selection', NULL, 'base', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"en_US": "Status"}', '{"en_US": "* New: The stock move is created but not confirmed.\n* Waiting Another Move: A linked stock move should be done before this one.\n* Waiting Availability: The stock move is confirmed but the product can''t be reserved.\n* Available: The product of the stock move is reserved.\n* Done: The product has been transferred and the transfer has been confirmed."}', NULL, false, false, true, true, false, NULL, true, true, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
