INSERT INTO public.ir_model_fields VALUES (6445, NULL, 521, NULL, NULL, NULL, NULL, 'state', NULL, 'stock.move.line', NULL, NULL, 'selection', 'move_id.state', 'base', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"en_US": "Status"}', '{"en_US": "* New: The stock move is created but not confirmed.\n* Waiting Another Move: A linked stock move should be done before this one.\n* Waiting Availability: The stock move is confirmed but the product can''t be reserved.\n* Available: The product of the stock move is reserved.\n* Done: The product has been transferred and the transfer has been confirmed."}', NULL, false, false, true, false, false, NULL, true, true, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
