INSERT INTO public.ir_model_fields VALUES (7249, NULL, 382, NULL, NULL, NULL, NULL, 'property_stock_account_input_categ_id', NULL, 'product.category', 'account.account', NULL, 'many2one', NULL, 'base', 'set null', NULL, NULL, NULL, NULL, NULL, NULL, '{"en_US": "Stock Input Account"}', '{"en_US": "Counterpart journal items for all incoming stock moves will be posted in this account, unless there is a specific valuation account\n                set on the source location. This is the default value for all products in this category. It can also directly be set on each product."}', NULL, false, false, false, false, false, NULL, true, false, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.ir_model_fields VALUES (7250, NULL, 382, NULL, NULL, NULL, NULL, 'property_stock_account_output_categ_id', NULL, 'product.category', 'account.account', NULL, 'many2one', NULL, 'base', 'set null', NULL, NULL, NULL, NULL, NULL, NULL, '{"en_US": "Stock Output Account"}', '{"en_US": "When doing automated inventory valuation, counterpart journal items for all outgoing stock moves will be posted in this account,\n                unless there is a specific valuation account set on the destination location. This is the default value for all products in this category.\n                It can also directly be set on each product."}', NULL, false, false, false, false, false, NULL, true, false, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
