INSERT INTO public.ir_module_module VALUES (440, NULL, NULL, '2026-05-10 01:12:29.662147', 1, '', '{"en_US": ""}', 'resource', 'Odoo S.A.', '/base/static/description/icon.png', 'installed', '17.0.1.1', '{"en_US": "Resource"}', 4, '{"en_US": "\nModule for resource management.\n===============================\n\nA resource represent something that can be scheduled (a developer on a task or a\nwork center on manufacturing orders). This module manages a resource calendar\nassociated to every resource. It also manages the leaves of every resource.\n"}', false, true, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, 'Settings/Technical/Resource
