INSERT INTO public.ir_module_module VALUES (201, NULL, NULL, '2026-05-10 01:12:29.662147', 1, 'https://www.odoo.com/documentation/17.0/applications/finance/fiscal_localizations/hong_kong.html', '{"en_US": ""}', 'l10n_hk', 'Odoo S.A.', '/account/static/description/l10n.png', 'uninstalled', NULL, '{"en_US": "Hong Kong - Accounting"}', 38, '{"en_US": "This is the base module to manage chart of accounting and localization for Hong Kong "}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (59, NULL, NULL, '2026-05-10 01:07:00.002872', 1, '', '{"en_US": ""}', 'delivery', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Delivery Costs"}', 14, '{"en_US": "\nAllows you to add delivery methods in sale orders.\n==================================================\nYou can define your own carrier for prices.\nThe system is able to add and compute the shipping line.\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (63, NULL, NULL, '2026-05-10 01:07:00.002872', 1, 'https://www.odoo.com/app/events', '{"en_US": "Trainings, Conferences, Meetings, Exhibitions, Registrations"}', 'event', 'Odoo S.A.', '/event/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Events Organization"}', 18, '{"en_US": "\nOrganization and management of Events.\n======================================\n\nThe event module allows you to efficiently organize events and all related tasks: planning, registration tracking,\nattendances, etc.\n\nKey Features\n------------\n* Manage your Events and Registrations\n* Use emails to automatically confirm and send acknowledgments for any event registration\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (68, NULL, NULL, '2026-05-10 01:07:00.002872', 1, 'https://www.odoo.com/app/events', '{"en_US": ""}', 'event_sale', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Events Sales"}', 18, '{"en_US": "\nCreating registration with sales orders.\n========================================\n\nThis module allows you to automate and connect your registration creation with\nyour main sale flow and therefore, to enable the invoicing feature of registrations.\n\nIt defines a new kind of service products that offers you the possibility to\nchoose an event category associated with it. When you encode a sales order for\nthat product, you will be able to choose an existing event of that category and\nwhen you confirm your sales order it will automatically create a registration for\nthis event.\n"}', false, false, false, 'LGPL-3', 100, true, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (69, NULL, NULL, '2026-05-10 01:07:00.002872', 1, '', '{"en_US": ""}', 'event_sms', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "SMS on Events"}', 18, '{"en_US": "Schedule SMS in event management"}', false, false, false, 'LGPL-3', 100, true, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (72, NULL, NULL, '2026-05-10 01:07:00.002872', 1, '', '{"en_US": ""}', 'gamification_sale_crm', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "CRM Gamification"}', 12, '{"en_US": "Example of goal definitions and challenges that can be used related to the usage of the CRM Sale module."}', false, false, false, 'LGPL-3', 100, true, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (77, NULL, NULL, '2026-05-10 01:07:00.002872', 1, 'https://www.odoo.com/app/employees', '{"en_US": "Centralize employee information"}', 'hr', 'Odoo S.A.', '/hr/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Employees"}', 21, '{"en_US": "Odoo Human Resources\n--------------------\n\nWith Odoo <a href=\"https://www.odoo.com/app/employees\">Human Resources</a>,\nmanage the most important asset in your company: People\n\nGet all your HR operations managed easily: knowledge sharing, recruitments,\nappraisals, timesheets, contracts, attendances, payroll, etc.\n\nEach need is provided by a specific app that you activate on demand.\n\nManage Your Employees\n---------------------\n\nOversee all important information in your company address book. Some\ninformation are restricted to HR managers, others are public to easily look\ncolleagues.\n\nRecord employee contracts and get alerts when they have to be renewed.\n\nStreamline Your Recruitment Process\n-----------------------------------\n\nIndex resumes, track applicants, search profiles with <a href=\"https://www.odoo.com/app/employees\">Odoo HR</a>.\n\nPost job offers and keep track of each application received. Follow applicants\nin your recruitment process with the smart kanban view.\n\nSave time by automating some communications with email templates. Resumes are\nindexed automatically, allowing you to easily find for specific profiles.\n\nEnterprise Social Network\n-------------------------\n\nBreak down information silos. Share knowledge and best practices amongst all\nemployees. Follow specific people or documents and join groups of interests to\nshare expertise and documents.\n\nInteract with your coworkers in real time with website live chat.\n\nTrack time and attendances\n--------------------------\n\nKeep track of the time spent by project, client or task. It''s easy to record\ntimesheets or check attendances for each employee. Get your analytic accounting\nposted automatically based on time spent on your projects.\n\nTime Off Management\n-----------------\n\nKeep track of the vacation days accrued by each employee. Employees enter their\nrequests (paid time off, sick time off, etc), for managers to approve and\nvalidate. It''s all done in just a few clicks. The agenda of each employee is\nupdated accordingly.\n\nKeep Track of Employee Expenses\n-------------------------------\n\nGet rid of the paper work and follow employee''s expenses directly in Odoo.\nDon''t loose time or money by controlling the full flow: expense validation,\nreimbursement of employees, posting in the accounting and re-invoicing to\ncustomers.\n\nFollow Periodic Appraisals\n--------------------------\n\nSet-up appraisals plans and/or surveys for your employees and watch their\nevolution. Define steps for interviews and Odoo will notify managers or\nsubordinates automatically to prepare appraisals. Keep track of the progress of\nyour staff periodically.\n\nBoost Engagement With Gamification\n----------------------------------\n\n### Define clear objective and provide real time feedback\n\nInspire achievement with challenges, goals and rewards. Define clear objectives\nand provide real time feedback and tangible results. Showcase the top\nperformers to the entire channel and publicly recognize a job well done.\n\n### Leaderboards\n\nPromote leaders and competition amongst Sales Team with performance ratios.\n\n### Personal Objectives\n\nAssign clear goals to users to align them with the company objectives.\n\n### Team Targets\n\nCompare revenues with forecasts and budgets in real time.\n\n"}', true, false, false, 'LGPL-3', 95, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (203, NULL, NULL, '2026-05-10 01:12:29.662147', 1, 'https://www.odoo.com/documentation/17.0/applications/finance/fiscal_localizations.html', '{"en_US": ""}', 'l10n_hr', 'Odoo S.A.', '/account/static/description/l10n.png', 'uninstalled', NULL, '{"en_US": "Croatia - Accounting (Euro)"}', 38, '{"en_US": "\nCroatian Chart of Accounts updated (RRIF ver.2021)\n\nSources:\nhttps://www.rrif.hr/dok/preuzimanje/Bilanca-2016.pdf\nhttps://www.rrif.hr/dok/preuzimanje/RRIF-RP2021.PDF\nhttps://www.rrif.hr/dok/preuzimanje/RRIF-RP2021-ENG.PDF\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (81, NULL, NULL, '2026-05-10 01:07:00.002872', 1, '', '{"en_US": "Get history of driven cars by employees"}', 'hr_fleet', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Fleet History"}', 19, '{"en_US": ""}', false, false, false, 'LGPL-3', 100, true, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (82, NULL, NULL, '2026-05-10 01:07:00.002872', 1, '', '{"en_US": ""}', 'hr_gamification', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "HR Gamification"}', 19, '{"en_US": "Use the HR resources for the gamification process.\n\nThe HR officer can now manage challenges and badges.\nThis allow the user to send badges to employees instead of simple users.\nBadge received are displayed on the user profile.\n"}', false, false, false, 'LGPL-3', 100, true, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (83, NULL, NULL, '2026-05-10 01:07:00.002872', 1, 'https://www.odoo.com/app/time-off', '{"en_US": "Allocate PTOs and follow leaves requests"}', 'hr_holidays', 'Odoo S.A.', '/hr_holidays/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Time Off"}', 25, '{"en_US": "\nManage time off requests and allocations\n=====================================\n\nThis application controls the time off schedule of your company. It allows employees to request time off. Then, managers can review requests for time off and approve or reject them. This way you can control the overall time off planning for the company or department.\n\nYou can configure several kinds of time off (sickness, paid days, ...) and allocate time off to an employee or department quickly using time off allocation. An employee can also make a request for more days off by making a new time off allocation. It will increase the total of available days for that time off type (if the request is accepted).\n\nYou can keep track of time off in different ways by following reports:\n\n* Time Off Summary\n* Time Off by Department\n* Time Off Analysis\n\nA synchronization with an internal agenda (Meetings of the CRM module) is also possible in order to automatically create a meeting when a time off request is accepted by setting up a type of meeting in time off Type.\n"}', true, false, false, 'LGPL-3', 85, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (85, NULL, NULL, '2026-05-10 01:07:00.002872', 1, '', '{"en_US": ""}', 'hr_homeworking', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Remote Work"}', 26, '{"en_US": ""}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (87, NULL, NULL, '2026-05-10 01:07:00.002872', 1, '', '{"en_US": ""}', 'hr_livechat', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "HR - Livechat"}', 19, '{"en_US": "\nBridge between HR and Livechat."}', false, false, false, 'LGPL-3', 100, true, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (88, NULL, NULL, '2026-05-10 01:07:00.002872', 1, '', '{"en_US": "Equipment, Assets, Internal Hardware, Allocation Tracking"}', 'hr_maintenance', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Maintenance - HR"}', 19, '{"en_US": "\nBridge between HR and Maintenance."}', false, false, false, 'LGPL-3', 125, true, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (91, NULL, NULL, '2026-05-10 01:07:00.002872', 1, 'https://www.odoo.com/app/recruitment', '{"en_US": "Track your recruitment pipeline"}', 'hr_recruitment', 'Odoo S.A.', '/hr_recruitment/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Recruitment"}', 29, '{"en_US": "Manage Recruitment and Job applications\n---------------------------------------\n\nPublish, promote and organize your job offers with the Odoo\n<a href=\"https://www.odoo.com/app/recruitment\">Open Source Recruitment Application</a>.\n\nOrganize your job board, promote your job announces and keep track of\napplication submissions easily. Follow every applicant and build up a database\nof skills and profiles with indexed documents.\n\nPost Your Jobs on Best Job Boards\n---------------------------------\n\nConnect automatically to most famous job board websites; linkedIn, Monster,\nCraigslist, ... Every job position has a new email address automatically\nassigned to route applications automatically to the right job position.\n\nWhether applicants contact you by email or using an online form, you get all\nthe data indexed automatically (resumes, motivation letter) and you can answer\nin just a click, reusing templates of answers.\n\nCustomize Your Recruitment Process\n----------------------------------\n\nUse the kanban view and customize the steps of your recruitments process;\npre-qualification, first interview, second interview, negociaiton, ...\n\nGet accurate statistics on your recruitment pipeline. Get reports to compare\nthe performance of your different investments on external job boards.\n\nStreamline Your Recruitment Process\n-----------------------------------\n\nFollow applicants in your recruitment process with the smart kanban view. Save\ntime by automating some communications with email templates.\n\nDocuments like resumes and motivation letters are indexed automatically,\nallowing you to easily find for specific skills and build up a database of\nprofiles.\n"}', true, false, false, 'LGPL-3', 90, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (92, NULL, NULL, '2026-05-10 01:07:00.002872', 1, '', '{"en_US": "Manage skills of your employees"}', 'hr_recruitment_skills', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Recruitment - Skills Management"}', 29, '{"en_US": ""}', false, false, false, 'LGPL-3', 270, true, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
