INSERT INTO public.ir_module_module VALUES (105, NULL, NULL, '2026-05-10 01:07:00.002872', 1, 'https://www.odoo.com/app/point-of-sale-hardware', '{"en_US": "Hardware Driver for ESC/POS Printers and Cashdrawers"}', 'hw_escpos', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstallable', NULL, '{"en_US": "ESC/POS Hardware Driver"}', 32, '{"en_US": "\nESC/POS Hardware Driver\n=======================\n\nThis module allows Odoo to print with ESC/POS compatible printers and\nto open ESC/POS controlled cashdrawers in the point of sale and other modules\nthat would need such functionality.\n\n"}', false, false, false, 'LGPL-3', 6, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (106, NULL, NULL, '2026-05-10 01:07:00.002872', 1, 'https://www.odoo.com/app/point-of-sale-hardware', '{"en_US": "A homepage for the IoT Box"}', 'hw_posbox_homepage', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstallable', NULL, '{"en_US": "IoT Box Homepage"}', 32, '{"en_US": "\nIoT Box Homepage\n================\n\nThis module overrides Odoo web interface to display a simple\nHomepage that explains what''s the iotbox and shows the status,\nand where to find documentation.\n\nIf you activate this module, you won''t be able to access the \nregular Odoo interface anymore.\n\n"}', false, false, false, 'LGPL-3', 6, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
