INSERT INTO public.ir_module_module VALUES (383, NULL, NULL, '2026-05-10 01:12:29.662147', 1, '', '{"en_US": "Customer Portal"}', 'portal', 'Odoo S.A.', '/base/static/description/icon.png', 'installed', '17.0.1.0', '{"en_US": "Customer Portal"}', 4, '{"en_US": "\nThis module adds required base code for a fully integrated customer portal.\nIt contains the base controller class and base templates. Business addons\nwill add their specific templates and controllers to extend the customer\nportal.\n\nThis module contains most code coming from odoo v10 website_portal. Purpose\nof this module is to allow the display of a customer portal without having\na dependency towards website editing and customization capabilities."}', false, true, false, 'LGPL-3', 9000, false, false, NULL, NULL, NULL, NULL, '', '', '* INHERIT Footer Language Selector (qweb)
