INSERT INTO public.ir_module_module VALUES (202, NULL, NULL, '2026-05-10 01:12:29.662147', 1, 'https://www.odoo.com/documentation/17.0/applications/finance/fiscal_localizations.html', '{"en_US": ""}', 'l10n_hn', 'Salvatore Josue Trimarchi Pinto', '/account/static/description/l10n.png', 'uninstalled', NULL, '{"en_US": "Honduras - Accounting"}', 38, '{"en_US": "\nThis is the base module to manage the accounting chart for Honduras.\n====================================================================\n\nAgrega una nomenclatura contable para Honduras. También incluye impuestos y la\nmoneda Lempira. -- Adds accounting chart for Honduras. It also includes taxes\nand the Lempira currency."}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (376, NULL, NULL, '2026-05-10 01:07:00.002872', 1, '', '{"en_US": "Easy Razorpay Onboarding With Oauth."}', 'payment_razorpay_oauth', 'Odoo S.A.', '/payment_razorpay/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Razorpay OAuth Integration"}', 57, '{"en_US": ""}', false, false, false, 'LGPL-3', 350, true, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (41, NULL, NULL, '2026-05-10 01:12:29.662147', 1, '', '{"en_US": ""}', 'base_import', 'Odoo S.A.', '/base/static/description/icon.png', 'installed', '17.0.2.0', '{"en_US": "Base import"}', 5, '{"en_US": "\nNew extensible file import for Odoo\n======================================\n\nRe-implement Odoo''s file import system:\n\n* Server side, the previous system forces most of the logic into the\n  client which duplicates the effort (between clients), makes the\n  import system much harder to use without a client (direct RPC or\n  other forms of automation) and makes knowledge about the\n  import/export system much harder to gather as it is spread over\n  3+ different projects.\n\n* In a more extensible manner, so users and partners can build their\n  own front-end to import from other file formats (e.g. OpenDocument\n  files) which may be simpler to handle in their work flow or from\n  their data production sources.\n\n* In a module, so that administrators and users of Odoo who do not\n  need or want an online import can avoid it being available to users.\n"}', false, true, false, 'LGPL-3', 100, true, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
