INSERT INTO public.ir_module_module VALUES (580, NULL, NULL, '2026-05-10 01:12:29.662147', 1, '', '{"en_US": "Find free high-resolution images from Unsplash"}', 'web_unsplash', 'Odoo S.A.', '/web_unsplash/static/description/icon.png', 'installed', '17.0.1.1', '{"en_US": "Unsplash Image Library"}', 4, '{"en_US": "Explore the free high-resolution image library of Unsplash.com and find images to use in Odoo. An Unsplash search bar is added to the image library modal."}', false, true, false, 'LGPL-3', 100, true, false, NULL, NULL, NULL, NULL, '', '', '* INHERIT res.config.settings.view.form.inherit.web.unsplash (form)', 'official', NULL);
