INSERT INTO public.ir_module_module VALUES (386, NULL, NULL, '2026-05-10 01:07:00.002872', 1, '', '{"en_US": "Simple Discounts in the Point of Sale "}', 'pos_discount', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Point of Sale Discounts"}', 32, '{"en_US": "\n\nThis module allows the cashier to quickly give percentage-based\ndiscount to a customer.\n\n"}', false, false, false, 'LGPL-3', 6, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
