INSERT INTO public.ir_module_module VALUES (108, NULL, NULL, '2026-05-10 01:12:29.662147', 1, '', '{"en_US": "Bridge between IAP and CRM"}', 'iap_crm', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "IAP / CRM"}', 5, '{"en_US": "Bridge between IAP and CRM"}', false, false, false, 'LGPL-3', 100, true, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (45, NULL, NULL, '2026-05-10 01:12:29.662147', 1, '', '{"en_US": "Implementation of sparse fields."}', 'base_sparse_field', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Sparse Fields"}', 4, '{"en_US": "\nThe purpose of this module is to implement \"sparse\" fields, i.e., fields\nthat are mostly null. This implementation circumvents the PostgreSQL\nlimitation on the number of columns in a table. The values of all sparse\nfields are stored in a \"serialized\" field in the form of a JSON mapping.\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (46, NULL, NULL, '2026-05-10 01:12:29.662147', 1, '', '{"en_US": ""}', 'base_vat', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "VAT Number Validation"}', 2, '{"en_US": "\nVAT validation for Partner''s VAT numbers.\n=========================================\n\nAfter installing this module, values entered in the VAT field of Partners will\nbe validated for all supported countries. The country is inferred from the\n2-letter country code that prefixes the VAT number, e.g. ``BE0477472701``\nwill be validated using the Belgian rules.\n\nThere are two different levels of VAT number validation:\n--------------------------------------------------------\n    * By default, a simple off-line check is performed using the known validation\n      rules for the country, usually a simple check digit. This is quick and \n      always available, but allows numbers that are perhaps not truly allocated,\n      or not valid anymore.\n\n    * When the \"VAT VIES Check\" option is enabled (in the configuration of the user''s\n      Company), VAT numbers will be instead submitted to the online EU VIES\n      database, which will truly verify that the number is valid and currently\n      allocated to a EU company. This is a little bit slower than the simple\n      off-line check, requires an Internet connection, and may not be available\n      all the time. If the service is not available or does not support the\n      requested country (e.g. for non-EU countries), a simple check will be performed\n      instead.\n\nSupported countries currently include EU countries, and a few non-EU countries\nsuch as Chile, Colombia, Mexico, Norway or Russia. For unsupported countries,\nonly the country code will be validated.\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (97, NULL, NULL, '2026-05-10 01:12:29.662147', 1, '', '{"en_US": "Add certification to resume of your employees"}', 'hr_skills_survey', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Skills Certification"}', 4, '{"en_US": "\nCertification and Skills for HR\n===============================\n\nThis module adds certification to resume for employees.\n"}', false, false, false, 'LGPL-3', 100, true, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (99, NULL, NULL, '2026-05-10 01:12:29.662147', 1, '', '{"en_US": ""}', 'hr_timesheet_attendance', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Timesheets/attendances reporting"}', 4, '{"en_US": "\nModule linking the attendance module to the timesheet app.\n"}', false, false, false, 'LGPL-3', 100, true, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (112, NULL, NULL, '2026-05-10 01:12:29.662147', 1, '', '{"en_US": ""}', 'l10n_account_edi_ubl_cii_tests', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Testing the Import/Export invoices with UBL/CII"}', 36, '{"en_US": "\nThis module tests the module ''account_edi_ubl_cii'', it is separated since dependencies to some\nlocalizations were required. Its name begins with ''l10n'' to not overload runbot.\n\nThe test files are separated by sources, they were taken from:\n\n* the factur-x doc (form the FNFE)\n* the peppol-bis-invoice-3 doc (the github repository: https://github.com/OpenPEPPOL/peppol-bis-invoice-3/tree/master/rules/examples contains examples)\n* odoo, these files pass all validation tests (using ecosio or the FNFE validator)\n\nWe test that the external examples are correctly imported (currency, total amount and total tax match).\nWe also test that generating xml from odoo with given parameters gives exactly the same xml as the expected,\nvalid ones.\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (113, NULL, NULL, '2026-05-10 01:12:29.662147', 1, 'https://www.odoo.com/documentation/17.0/applications/finance/fiscal_localizations/united_arab_emirates.html', '{"en_US": ""}', 'l10n_ae', 'Odoo S.A.', '/account/static/description/l10n.png', 'uninstalled', NULL, '{"en_US": "United Arab Emirates - Accounting"}', 38, '{"en_US": "\nUnited Arab Emirates Accounting Module\n=======================================================\nUnited Arab Emirates accounting basic charts and localization.\n\nActivates:\n\n- Chart of Accounts\n- Taxes\n- Tax Report\n- Fiscal Positions\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (114, NULL, NULL, '2026-05-10 01:12:29.662147', 1, '', '{"en_US": ""}', 'l10n_anz_ubl_pint', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Australia & New Zealand - UBL PINT"}', 39, '{"en_US": "\nThe UBL PINT e-invoicing format for Australia & New Zealand is based on the Peppol International (PINT) model for Billing.\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (398, NULL, NULL, '2026-05-10 01:07:00.002872', 1, 'https://www.odoo.com/app/point-of-sale-restaurant', '{"en_US": "Restaurant extensions for the Point of Sale "}', 'pos_restaurant', 'Odoo S.A.', '/pos_restaurant/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Restaurant"}', 32, '{"en_US": "\n\nThis module adds several features to the Point of Sale that are specific to restaurant management:\n- Bill Printing: Allows you to print a receipt before the order is paid\n- Bill Splitting: Allows you to split an order into different orders\n- Kitchen Order Printing: allows you to print orders updates to kitchen or bar printers\n\n"}', true, false, false, 'LGPL-3', 6, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
