INSERT INTO public.ir_module_module VALUES (417, NULL, NULL, '2026-05-10 01:07:00.002872', 1, '', '{"en_US": ""}', 'product_expiry', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Products Expiration Date"}', 53, '{"en_US": "\nTrack different dates on products and production lots.\n======================================================\n\nFollowing dates can be tracked:\n-------------------------------\n    - end of life\n    - best before date\n    - removal date\n    - alert date\n\nAlso implements the removal strategy First Expiry First Out (FEFO) widely used, for example, in food industries.\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (116, NULL, NULL, '2026-05-10 01:12:29.662147', 1, '', '{"en_US": ""}', 'l10n_ar_pos', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Argentinean - Point of Sale with AR Doc"}', 40, '{"en_US": "\nThis module brings the technical requirement for the Argentinean regulation.\nInstall this if you are using the Point of Sale app in Argentina.\n"}', false, false, false, 'LGPL-3', 100, true, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (119, NULL, NULL, '2026-05-10 01:12:29.662147', 1, 'https://www.odoo.com/documentation/17.0/applications/finance/fiscal_localizations.html', '{"en_US": "Austrian Standardized Charts & Tax"}', 'l10n_at', 'WT-IO-IT GmbH, Wolfgang Taferner (https://www.wt-io-it.at)', '/account/static/description/l10n.png', 'uninstalled', NULL, '{"en_US": "Austria - Accounting"}', 38, '{"en_US": "\n\nAustrian charts of accounts (Einheitskontenrahmen 2010).\n==========================================================\n\n    * Defines the following chart of account templates:\n        * Austrian General Chart of accounts 2010\n    * Defines templates for VAT on sales and purchases\n    * Defines tax templates\n    * Defines fiscal positions for Austrian fiscal legislation\n    * Defines tax reports U1/U30\n\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (227, NULL, NULL, '2026-05-10 01:12:29.662147', 1, 'https://www.odoo.com/documentation/17.0/applications/finance/fiscal_localizations/italy.html', '{"en_US": ""}', 'l10n_it_edi_doi', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Italy - Declaration of Intent"}', 37, '{"en_US": "\nAdd support for the Declaration of Intent (Dichiarazione di Intento) to the Italian localization.\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (120, NULL, NULL, '2026-05-10 01:12:29.662147', 1, 'https://www.odoo.com/documentation/17.0/applications/finance/fiscal_localizations/australia.html', '{"en_US": ""}', 'l10n_au', 'Odoo S.A.', '/account/static/description/l10n.png', 'uninstalled', NULL, '{"en_US": "Australia - Accounting"}', 38, '{"en_US": "\nAustralian Accounting Module\n============================\n\nAustralian accounting basic charts and localizations.\n\nAlso:\n    - activates a number of regional currencies.\n    - sets up Australian taxes.\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (121, NULL, NULL, '2026-05-10 01:12:29.662147', 1, 'https://www.odoo.com/documentation/17.0/applications/finance/fiscal_localizations.html', '{"en_US": ""}', 'l10n_bd', 'Odoo S.A.', '/account/static/description/l10n.png', 'uninstalled', NULL, '{"en_US": "Bangladesh - Accounting"}', 38, '{"en_US": "This is the base module to manage chart of accounts and localization for the Bangladesh "}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
