INSERT INTO public.ir_module_module VALUES (419, NULL, NULL, '2026-05-10 01:07:00.002872', 1, '', '{"en_US": ""}', 'product_margin', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Margins by Products"}', 9, '{"en_US": "\nAdds a reporting menu in products that computes sales, purchases, margins and other interesting indicators based on invoices.\n=============================================================================================================================\n\nThe wizard to launch the report has several options to help you get the data you need.\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (421, NULL, NULL, '2026-05-10 01:07:00.002872', 1, 'https://www.odoo.com/app/project', '{"en_US": "Organize and plan your projects"}', 'project', 'Odoo S.A.', '/project/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Project"}', 60, '{"en_US": "Project Management\n------------------\n\n### Infinitely flexible. Incredibly easy to use.\n\n\nOdoo''s collaborative and realtime <a href=\"https://www.odoo.com/app/project\">open source project management</a>\nhelps your team get work done. Keep track of everything, from the big picture\nto the minute details, from the customer contract to the billing.\n\nDesigned to Fit Your Own Process\n--------------------------------\n\nOrganize projects around your own processes. Work on tasks and issues using the\nkanban view, schedule tasks using the gantt chart and control deadlines in the\ncalendar view. Every project may have its own stages, allowing teams to\noptimize their job.\n\nEasy to Use\n-----------\n\nGet organized as fast as you can think. The easy-to-use interface takes no time\nto learn, and every action is instantaneous, so there’s nothing standing\nbetween you and your sweet productive flow.\n\nWork Together\n-------------\n\n### Real-time chats, document sharing, email integration\n\nUse the chatter to communicate with your team or customers and share comments\nand documents on tasks and issues. Integrate discussion fast with the email\nintegration.\n\nTalk to other users or customers with the website live chat feature.\n\nCollaborative Writing\n---------------------\n\n### The power of etherpad, inside your tasks\n\nCollaboratively edit the same specifications or meeting minutes right inside\nthe application. The integrated etherpad feature allows several people to\nwork on the same tasks, at the same time.\n\nThis is very efficient for scrum meetings, meeting minutes or complex\nspecifications. Every user has their own color and you can replay the whole\ncreation of the content.\n\nGet Work Done\n-------------\n\nGet alerts on followed events to stay up to date with what interests you. Use\ninstant green/red visual indicators to scan through what has been done and what\nrequires your attention.\n\nTimesheets, Contracts & Invoicing\n---------------------------------\n\nProjects are automatically integrated with customer contracts, allowing you to\ninvoice based on time & materials and record timesheets easily.\n\nTrack Issues\n------------\n\nSingle out the issues that arise in a project in order to have a better focus\non resolving them. Integrate customer interaction on every issue and get\naccurate reports on your team''s performance.\n\n"}', true, false, false, 'LGPL-3', 45, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (423, NULL, NULL, '2026-05-10 01:07:00.002872', 1, '', '{"en_US": "Project expenses"}', 'project_hr_expense', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Project Expenses"}', 61, '{"en_US": "Bridge created to add the number of expenses linked to an AA to a project form"}', false, false, false, 'LGPL-3', 100, true, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (424, NULL, NULL, '2026-05-10 01:07:00.002872', 1, 'https://www.odoo.com/app/project', '{"en_US": "Integrate your inbox with projects"}', 'project_mail_plugin', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Project Mail Plugin"}', 60, '{"en_US": "Turn emails received in your mailbox into tasks and log their content as internal notes."}', false, false, false, 'LGPL-3', 5, true, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (425, NULL, NULL, '2026-05-10 01:07:00.002872', 1, '', '{"en_US": "Monitor MRP using project"}', 'project_mrp', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "MRP Project"}', 60, '{"en_US": ""}', false, false, false, 'LGPL-3', 100, true, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
