INSERT INTO public.ir_module_module VALUES (430, NULL, NULL, '2026-05-10 01:07:00.002872', 1, '', '{"en_US": "Organize your work with memos and to-do lists"}', 'project_todo', 'Odoo S.A.', '/project_todo/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "To-Do"}', 62, '{"en_US": ""}', true, false, false, 'LGPL-3', 260, true, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (122, NULL, NULL, '2026-05-10 01:12:29.662147', 1, 'https://www.odoo.com/documentation/17.0/applications/finance/fiscal_localizations/belgium.html', '{"en_US": ""}', 'l10n_be', 'Noviat, Odoo S.A.', '/account/static/description/l10n.png', 'uninstalled', NULL, '{"en_US": "Belgium - Accounting"}', 38, '{"en_US": "\nThis is the base module to manage the accounting chart for Belgium in Odoo.\n==============================================================================\n\nAfter installing this module, the Configuration wizard for accounting is launched.\n    * We have the account templates which can be helpful to generate Charts of Accounts.\n    * On that particular wizard, you will be asked to pass the name of the company,\n      the chart template to follow, the no. of digits to generate, the code for your\n      account and bank account, currency to create journals.\n\nThus, the pure copy of Chart Template is generated.\n\nWizards provided by this module:\n--------------------------------\n    * Partner VAT Intra: Enlist the partners with their related VAT and invoiced\n      amounts. Prepares an XML file format.\n\n        **Path to access:** Invoicing/Reporting/Legal Reports/Belgium Statements/Partner VAT Intra\n    * Periodical VAT Declaration: Prepares an XML file for Vat Declaration of\n      the Main company of the User currently Logged in.\n\n        **Path to access:** Invoicing/Reporting/Legal Reports/Belgium Statements/Periodical VAT Declaration\n    * Annual Listing Of VAT-Subjected Customers: Prepares an XML file for Vat\n      Declaration of the Main company of the User currently Logged in Based on\n      Fiscal year.\n\n        **Path to access:** Invoicing/Reporting/Legal Reports/Belgium Statements/Annual Listing Of VAT-Subjected Customers\n\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (126, NULL, NULL, '2026-05-10 01:12:29.662147', 1, '', '{"en_US": ""}', 'l10n_bh', 'Odoo S.A.', '/account/static/description/l10n.png', 'uninstalled', NULL, '{"en_US": "Bahrain - Accounting"}', 38, '{"en_US": "\nThis is the base module to manage the accounting chart for Bahrain in Odoo.\n===========================================================================\nBahrain accounting basic charts and localization.\n\nActivates:\n - Chart of Accounts\n - Taxes\n - Tax reports\n - Fiscal Positions\n - States\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (128, NULL, NULL, '2026-05-10 01:12:29.662147', 1, 'https://www.odoo.com/documentation/17.0/applications/finance/fiscal_localizations.html', '{"en_US": ""}', 'l10n_bo', 'Odoo / Cubic ERP', '/account/static/description/l10n.png', 'uninstalled', NULL, '{"en_US": "Bolivia - Accounting"}', 38, '{"en_US": "\nBolivian accounting chart and tax localization.\n\nPlan contable boliviano e impuestos de acuerdo a disposiciones vigentes\n\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (434, NULL, NULL, '2026-05-10 01:07:00.002872', 1, '', '{"en_US": ""}', 'purchase_requisition', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Purchase Agreements"}', 54, '{"en_US": "\nThis module allows you to manage your Purchase Agreements.\n===========================================================\n\nManage calls for tenders and blanket orders. Calls for tenders are used to get\ncompeting offers from different vendors and select the best ones. Blanket orders\nare agreements you have with vendors to benefit from a predetermined pricing.\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (452, NULL, NULL, '2026-05-10 01:12:09.434736', 1, '', '{"en_US": ""}', 'sale_pdf_quote_builder', 'Odoo S.A.', '/base/static/description/icon.png', 'installed', '17.0.1.0', '{"en_US": "Sales PDF Quotation Builder"}', 9, '{"en_US": "Build nice quotations"}', false, true, false, 'LGPL-3', 100, true, false, NULL, NULL, NULL, NULL, '', 'Quotation / Order', '* INHERIT res.config.settings.view.form.inherit.sale.pdf.quote.builder (form)
* INHERIT sale.order.template.form (form)', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (133, NULL, NULL, '2026-05-10 01:12:29.662147', 1, 'https://www.odoo.com/documentation/17.0/applications/finance/fiscal_localizations.html', '{"en_US": ""}', 'l10n_ca', 'Savoir-faire Linux (https://www.savoirfairelinux.com); Odoo SA', '/account/static/description/l10n.png', 'uninstalled', NULL, '{"en_US": "Canada - Accounting"}', 38, '{"en_US": "\nThis is the module to manage the Canadian accounting chart in Odoo.\n===========================================================================================\n\nCanadian accounting charts and localizations.\n\nFiscal positions\n----------------\n\nWhen considering taxes to be applied, it is the province where the delivery occurs that matters.\nTherefore we decided to implement the most common case in the fiscal positions: delivery is the\nresponsibility of the vendor and done at the customer location.\n\nSome examples:\n\n1) You have a customer from another province and you deliver to his location.\nOn the customer, set the fiscal position to his province.\n\n2) You have a customer from another province. However this customer comes to your location\nwith their truck to pick up products. On the customer, do not set any fiscal position.\n\n3) An international vendor doesn''t charge you any tax. Taxes are charged at customs\nby the customs broker. On the vendor, set the fiscal position to International.\n\n4) An international vendor charge you your provincial tax. They are registered with your\nposition.\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (134, NULL, NULL, '2026-05-10 01:12:29.662147', 1, '', '{"en_US": ""}', 'l10n_cd', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Democratic Republic of the Congo - Accounting"}', 38, '{"en_US": "\nThis module implements the tax for the Democratic Republic of the Congo.\n===========================================================================\n\nThe Chart of Accounts is from SYSCOHADA.\n\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (135, NULL, NULL, '2026-05-10 01:12:29.662147', 1, '', '{"en_US": ""}', 'l10n_cf', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Central African Republic - Accounting"}', 38, '{"en_US": "\nThis module implements the tax for Central African Republic.\n=================================================================\n\nThe Chart of Accounts is from SYSCOHADA.\n\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (174, NULL, NULL, '2026-05-10 01:12:29.662147', 1, '', '{"en_US": ""}', 'l10n_es_edi_tbai', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Spain - TicketBAI"}', 39, '{"en_US": "\nThis module sends invoices and vendor bills to the \"Diputaciones\nForales\" of Araba/Álava, Bizkaia and Gipuzkoa.\n\nInvoices and bills get converted to XML and regularly sent to the\nBasque government servers which provides them with a unique identifier.\nA hash chain ensures the continuous nature of the invoice/bill\nsequences. QR codes are added to emitted (sent/printed) invoices,\nbills and tickets to allow anyone to check they have been declared.\n\nYou need to configure your certificate and the tax agency.\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (127, NULL, NULL, '2026-05-10 01:12:29.662147', 1, '', '{"en_US": ""}', 'l10n_bj', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Benin - Accounting"}', 38, '{"en_US": "\nThis module implements the tax for Benin.\n=================================================================\n\nThe Chart of Accounts is from SYSCOHADA.\n\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (137, NULL, NULL, '2026-05-10 01:12:29.662147', 1, 'https://www.odoo.com/documentation/17.0/applications/finance/fiscal_localizations/switzerland.html', '{"en_US": ""}', 'l10n_ch', 'Odoo S.A.', '/account/static/description/l10n.png', 'uninstalled', NULL, '{"en_US": "Switzerland - Accounting"}', 38, '{"en_US": "\nSwiss localization\n==================\nThis module defines a chart of account for Switzerland (Swiss PME/KMU 2015), taxes and enables the generation of a QR-bill when you print an invoice or send it by mail.\nThe QR bill is attached to the invoice and eases its payment.\n\nA QR-bill will be generated if:\n    - The partner set on your invoice has a complete address (street, city, postal code and country) in Switzerland\n    - The option to generate the Swiss QR-code is selected on the invoice (done by default)\n    - A correct account number/QR IBAN is set on your bank journal\n    - (when using a QR-IBAN): the payment reference of the invoice is a QR-reference\n\nThe generation of the QR-bill is automatic if you meet the previous criteria. The QR-bill will be appended after the invoice when printing or sending by mail. \n\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (139, NULL, NULL, '2026-05-10 01:12:29.662147', 1, '', '{"en_US": ""}', 'l10n_ci', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Ivory Coast - Accounting"}', 38, '{"en_US": "\nThis module implements the taxes for Ivory Coast.\n=================================================================\n\nThe Chart of Accounts is from SYSCOHADA.\n\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (140, NULL, NULL, '2026-05-10 01:12:29.662147', 1, 'https://www.odoo.com/documentation/17.0/applications/finance/fiscal_localizations/chile.html', '{"en_US": ""}', 'l10n_cl', 'Blanco Martín & Asociados', '/account/static/description/l10n.png', 'uninstalled', NULL, '{"en_US": "Chile - Accounting"}', 38, '{"en_US": "\nChilean accounting chart and tax localization.\nPlan contable chileno e impuestos de acuerdo a disposiciones vigentes.\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
