INSERT INTO public.ir_module_module VALUES (462, NULL, NULL, '2026-05-10 01:07:00.002872', 1, '', '{"en_US": ""}', 'sale_stock_margin', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Sale Stock Margin"}', 9, '{"en_US": "Once the delivery is validated, update the cost on the SO to have an exact margin computation."}', false, false, false, 'LGPL-3', 100, true, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
