INSERT INTO public.ir_module_module VALUES (141, NULL, NULL, '2026-05-10 01:12:29.662147', 1, '', '{"en_US": ""}', 'l10n_cm', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Cameroon - Accounting"}', 38, '{"en_US": "\nThis module implements the tax for Cameroon.\n===========================================================\n\nThe Chart of Accounts is from SYSCOHADA.\n\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (142, NULL, NULL, '2026-05-10 01:12:29.662147', 1, 'https://www.odoo.com/documentation/17.0/applications/finance/fiscal_localizations.html', '{"en_US": ""}', 'l10n_cn', 'openerp-china', '/account/static/description/l10n.png', 'uninstalled', NULL, '{"en_US": "China - Accounting"}', 38, '{"en_US": "\nIncludes the following data for the Chinese localization\n========================================================\n\nAccount Type/科目类型\n\nState Data/省份数据\n\n    科目类型\\会计科目表模板\\增值税\\辅助核算类别\\管理会计凭证簿\\财务会计凭证簿\n\n    添加中文省份数据\n\n    增加小企业会计科目表\n\n    修改小企业会计科目表\n\n    修改小企业会计税率\n\n    增加大企业会计科目表\n\nWe added the option to print a voucher which will also\nprint the amount in words (special Chinese characters for numbers)\ncorrectly when the cn2an library is installed. (e.g. with pip3 install cn2an)\n"}', false, false, false, 'LGPL-3', 100, false, false, 'jeff@osbzr.com', NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (143, NULL, NULL, '2026-05-10 01:12:29.662147', 1, '', '{"en_US": ""}', 'l10n_cn_city', 'Jeffery Chen Fan<jeffery9@gmail.com>', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "China - City Data"}', 37, '{"en_US": "\nIncludes the following data for the Chinese localization\n========================================================\n\nCity Data/城市数据\n\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (146, NULL, NULL, '2026-05-10 01:12:29.662147', 1, 'https://www.odoo.com/documentation/17.0/applications/finance/fiscal_localizations.html', '{"en_US": ""}', 'l10n_cr', 'ClearCorp S.A.', '/account/static/description/l10n.png', 'uninstalled', NULL, '{"en_US": "Costa Rica - Accounting"}', 38, '{"en_US": "\nChart of accounts for Costa Rica.\n=================================\n\nIncludes:\n---------\n    * account.account.template\n    * account.tax.template\n    * account.chart.template\n\nEverything is in English with Spanish translation. Further translations are welcome,\nplease go to http://translations.launchpad.net/openerp-costa-rica.\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, 'https://github.com/CLEARCORP/odoo-costa-rica', NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (147, NULL, NULL, '2026-05-10 01:12:29.662147', 1, '', '{"en_US": ""}', 'l10n_cy', 'Odoo S.A.', '/account/static/description/l10n.png', 'uninstalled', NULL, '{"en_US": "Cyprus - Accounting"}', 38, '{"en_US": "\nBasic package for Cyprus that contains the chart of accounts, taxes, tax reports,...\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (148, NULL, NULL, '2026-05-10 01:12:29.662147', 1, 'https://www.odoo.com/documentation/17.0/applications/finance/fiscal_localizations.html', '{"en_US": ""}', 'l10n_cz', '26HOUSE (http://www.26house.com)', '/account/static/description/l10n.png', 'uninstalled', NULL, '{"en_US": "Czech - Accounting"}', 38, '{"en_US": "\nCzech accounting chart and localization.  With Chart of Accounts with taxes and basic fiscal positions.\n\nTento modul definuje:\n\n- Českou účetní osnovu za rok 2020\n\n- Základní sazby pro DPH z prodeje a nákupu\n\n- Základní fiskální pozice pro českou legislativu\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (489, NULL, NULL, '2026-05-10 01:07:00.002872', 1, '', '{"en_US": ""}', 'stock_delivery', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Delivery - Stock"}', 16, '{"en_US": "\nAllows you to add delivery methods in pickings.\n===============================================\n\nWhen creating invoices from picking, the system is able to add and compute the shipping line.\n"}', false, false, false, 'LGPL-3', 100, true, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (490, NULL, NULL, '2026-05-10 01:07:00.002872', 1, '', '{"en_US": "Drop Shipping"}', 'stock_dropshipping', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Drop Shipping"}', 53, '{"en_US": "\nManage drop shipping orders\n===========================\n\nThis module adds a pre-configured Drop Shipping operation type\nas well as a procurement route that allow configuring Drop\nShipping products and orders.\n\nWhen drop shipping is used the goods are directly transferred\nfrom vendors to customers (direct delivery) without\ngoing through the retailer''s warehouse. In this case no\ninternal transfer document is needed.\n\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (497, NULL, NULL, '2026-05-10 01:12:29.662147', 1, '', '{"en_US": ""}', 'test_action_bindings', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Test Action Bindings"}', 36, '{"en_US": ""}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (149, NULL, NULL, '2026-05-10 01:12:29.662147', 1, 'https://www.odoo.com/documentation/17.0/applications/finance/fiscal_localizations/germany.html', '{"en_US": ""}', 'l10n_de', 'openbig.org (http://www.openbig.org)', '/account/static/description/l10n.png', 'uninstalled', NULL, '{"en_US": "Germany - Accounting"}', 38, '{"en_US": "\nDieses  Modul beinhaltet einen deutschen Kontenrahmen basierend auf dem SKR03 oder SKR04.\n=========================================================================================\n\nGerman accounting chart and localization.\nBy default, the audit trail is enabled for GoBD compliance.\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (173, NULL, NULL, '2026-05-10 01:12:29.662147', 1, '', '{"en_US": ""}', 'l10n_es_edi_sii', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Spain - SII EDI Suministro de Libros"}', 39, '{"en_US": "\nThis module sends the taxes information (mostly VAT) of the\nvendor bills and customer invoices to the SII.  It is called\nProcedimiento G417 - IVA. Llevanza de libros registro.  It is\nrequired for every company with a turnover of +6M€ and others can\nalready make use of it.  The invoices are automatically\nsent after validation.\n\nHow the information is sent to the SII depends on the\nconfiguration that is put in the taxes.  The taxes\nthat were in the chart template (l10n_es) are automatically\nconfigured to have the right type.  It is possible however\nthat extra taxes need to be created for certain exempt/no sujeta reasons.\n\nYou need to configure your certificate and the tax agency.\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (6, NULL, NULL, '2026-05-10 01:12:29.662147', 1, '', '{"en_US": "Debit Note Sequence"}', 'account_debit_note_sequence', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Debit Note Sequence"}', 2, '{"en_US": "\nThis module allows you to add sequence for Debit note\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (156, NULL, NULL, '2026-05-10 01:12:29.662147', 1, 'https://www.odoo.com/documentation/17.0/applications/finance/fiscal_localizations.html', '{"en_US": ""}', 'l10n_dk', 'Odoo House ApS, VK DATA ApS, FlexERP ApS', '/account/static/description/l10n.png', 'uninstalled', NULL, '{"en_US": "Denmark - Accounting"}', 38, '{"en_US": "\n\nLocalization Module for Denmark\n===============================\n\nThis is the module to manage the **accounting chart for Denmark**. Cover both one-man business as well as I/S, IVS, ApS and A/S\n\n**Modulet opsætter:**\n\n- **Dansk kontoplan**\n\n- Dansk moms\n        - 25 % moms\n        - Restaurationsmoms 6,25 %\n        - Omvendt betalingspligt\n\n- Konteringsgrupper\n        - EU (Virksomhed)\n        - EU (Privat)\n        - Tredjelande\n\n- Finansrapporter\n        - Resultatopgørelse\n        - Balance\n        - Momsafregning\n            - Afregning\n            - Rubrik A, B og C\n\n- **Anglo-saksisk regnskabsmetode**\n\n.\n\nProduktopsætning:\n=================\n\n**Vare**\n\n**Salgsmoms:**      Salgsmoms 25 %\n\n**Salgskonto:**     1.010 Salg af varer inkl. moms\n\n**Købsmoms:**       Købsmoms 25 %\n\n**Købskonto:**      2.010 Direkte vareomkostninger inkl. moms\n\n.\n\n**Ydelse**\n\n**Salgsmoms:**      Salgsmoms 25 %, ydelser\n\n**Salgskonto:**     1.011 Salg af ydelser inkl. moms\n\n**Købsmoms:**       Købsmoms 25 %, ydelser\n\n**Købskonto:**      2.011 Direkte omkostninger ydelser inkl. moms\n\n.\n\n**Vare med omvendt betalingspligt**\n\n**Salgsmoms:**      Salg med omvendt betalingspligt\n\n**Salgskonto:**     1.012 Salg af varer ekskl. moms\n\n**Købsmoms:**       Køb med omvendt betalingspligt\n\n**Købskonto:**      2.012 Direkte vareomkostninger ekskl. moms\n\n\n.\n\n**Restauration**\n\n**Købsmoms:**       Restaurationsmoms 6,25 %, købsmoms\n\n**Købskonto:**      4010 Restaurationsbesøg\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (161, NULL, NULL, '2026-05-10 01:12:29.662147', 1, 'https://www.odoo.com/documentation/17.0/applications/finance/fiscal_localizations.html', '{"en_US": ""}', 'l10n_do', 'Gustavo Valverde - iterativo | Consultores de Odoo (http://iterativo.do)', '/account/static/description/l10n.png', 'uninstalled', NULL, '{"en_US": "Dominican Republic - Accounting"}', 38, '{"en_US": "\n\nLocalization Module for Dominican Republic\n===========================================\n\nCatálogo de Cuentas e Impuestos para República Dominicana, Compatible para\n**Internacionalización** con **NIIF** y alineado a las normas y regulaciones\nde la Dirección General de Impuestos Internos (**DGII**).\n\n**Este módulo consiste de:**\n\n- Catálogo de Cuentas Estándar (alineado a DGII y NIIF)\n- Catálogo de Impuestos con la mayoría de Impuestos Preconfigurados\n        - ITBIS para compras y ventas\n        - Retenciones de ITBIS\n        - Retenciones de ISR\n        - Grupos de Impuestos y Retenciones:\n                - Telecomunicaiones\n                - Proveedores de Materiales de Construcción\n                - Personas Físicas Proveedoras de Servicios\n        - Otros impuestos\n- Secuencias Preconfiguradas para manejo de todos los NCF\n        - Facturas con Valor Fiscal (para Ventas)\n        - Facturas para Consumidores Finales\n        - Notas de Débito y Crédito\n        - Registro de Proveedores Informales\n        - Registro de Ingreso Único\n        - Registro de Gastos Menores\n        - Gubernamentales\n- Posiciones Fiscales para automatización de impuestos y retenciones\n        - Cambios de Impuestos a Exenciones (Ej. Ventas al Estado)\n        - Cambios de Impuestos a Retenciones (Ej. Compra Servicios al Exterior)\n        - Entre otros\n\n**Nota:**\nEsta localización, aunque posee las secuencias para NCF, las mismas no pueden\nser utilizadas sin la instalación de módulos de terceros o desarrollo\nadicional.\n\nEstructura de Codificación del Catálogo de Cuentas:\n===================================================\n\n**Un dígito** representa la categoría/tipo de cuenta del del estado financiero.\n**1** - Activo        **4** - Cuentas de Ingresos y Ganancias\n**2** - Pasivo        **5** - Costos, Gastos y Pérdidas\n**3** - Capital       **6** - Cuentas Liquidadoras de Resultados\n\n**Dos dígitos** representan los rubros de agrupación:\n11- Activo Corriente\n21- Pasivo Corriente\n31- Capital Contable\n\n**Cuatro dígitos** se asignan a las cuentas de mayor: cuentas de primer orden\n1101- Efectivo y Equivalentes de Efectivo\n2101- Cuentas y Documentos por pagar\n3101- Capital Social\n\n**Seis dígitos** se asignan a las sub-cuentas: cuentas de segundo orden\n110101 - Caja\n210101 - Proveedores locales\n\n**Ocho dígitos** son para las cuentas de tercer orden (las visualizadas\nen Odoo):\n1101- Efectivo y Equivalentes\n110101- Caja\n11010101 Caja General\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (167, NULL, NULL, '2026-05-10 01:12:29.662147', 1, 'https://www.odoo.com/documentation/17.0/applications/finance/fiscal_localizations/egypt.html', '{"en_US": ""}', 'l10n_eg', 'Odoo S.A.', '/account/static/description/l10n.png', 'uninstalled', NULL, '{"en_US": "Egypt - Accounting"}', 38, '{"en_US": "\nEgypt Accounting Module\n==============================================================================\nEgypt Accounting Basic Charts and Localization.\n\nActivates:\n\n- Chart of Accounts\n- Taxes\n- VAT Return\n- Withholding Tax Report\n- Schedule Tax Report\n- Other Taxes Report\n- Fiscal Positions\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (170, NULL, NULL, '2026-05-10 01:12:29.662147', 1, 'https://www.facturae.gob.es/face/Paginas/FACE.aspx', '{"en_US": ""}', 'l10n_es_edi_facturae', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Spain - Facturae EDI"}', 39, '{"en_US": "\nThis module create the Facturae file required to send the invoices information to the General State Administrations.\nIt allows the export and signature of the signing of Facturae files.\nThe current version of Facturae supported is the 3.2.2\n\nfor more informations, see https://www.facturae.gob.es/face/Paginas/FACE.aspx\n"}', false, false, false, 'LGPL-3', 100, true, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
