INSERT INTO public.ir_module_module VALUES (171, NULL, NULL, '2026-05-10 01:12:29.662147', 1, '', '{"en_US": ""}', 'l10n_es_edi_facturae_adm_centers', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Spain - Facturae EDI - Administrative Centers Patch"}', 39, '{"en_US": "\nPatch module to fix the missing Administrative Centers in the Facturae EDI.\n"}', false, false, false, 'LGPL-3', 100, true, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (172, NULL, NULL, '2026-05-10 01:12:29.662147', 1, '', '{"en_US": ""}', 'l10n_es_edi_facturae_invoice_period', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Spain - Facturae EDI - Invoice Period"}', 39, '{"en_US": "\nPatch module to add the missing Invoice Period in the Facturae EDI.\n"}', false, false, false, 'LGPL-3', 100, true, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (224, NULL, NULL, '2026-05-10 01:12:29.662147', 1, '', '{"en_US": ""}', 'l10n_iq', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Iraq - Accounting"}', 38, '{"en_US": "\nThis is the base module to manage the accounting chart for Iraq in Odoo.\n==============================================================================\nIraq accounting basic charts and localization.\nActivates:\n- Chart of accounts\n- Taxes\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (181, NULL, NULL, '2026-05-10 01:12:29.662147', 1, 'https://www.odoo.com/documentation/17.0/applications/finance/fiscal_localizations.html', '{"en_US": ""}', 'l10n_et', 'Michael Telahun Makonnen <mmakonnen@gmail.com>', '/account/static/description/l10n.png', 'uninstalled', NULL, '{"en_US": "Ethiopia - Accounting"}', 38, '{"en_US": "\nBase Module for Ethiopian Localization\n======================================\n\nThis is the latest Ethiopian Odoo localization and consists of:\n    - Chart of Accounts\n    - VAT tax structure\n    - Withholding tax structure\n    - Regional State listings\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (182, NULL, NULL, '2026-05-10 01:12:29.662147', 1, '', '{"en_US": ""}', 'l10n_eu_oss', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "EU One Stop Shop (OSS)"}', 37, '{"en_US": "\nEU One Stop Shop (OSS) VAT\n==========================\n\nFrom July 1st 2021, EU businesses that are selling goods within the EU above EUR 10 000 to buyers located in another EU Member State need to register and pay VAT in the buyers’ Member State.\nBelow this new EU-wide threshold you can continue to apply the domestic rules for VAT on your cross-border sales. In order to simplify the application of this EU directive, the One Stop Shop (OSS) registration scheme allows businesses to make a unique tax declaration.\n\nThis module makes it possible by helping with the creation of the required EU fiscal positions and taxes in order to automatically apply and record the required taxes.\n\nAll you have to do is check that the proposed mapping is suitable for the products and services you sell.\n\nReferences\n++++++++++\nCouncil Directive (EU) 2017/2455 Council Directive (EU) 2019/1995\nCouncil Implementing Regulation (EU) 2019/2026\n\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (183, NULL, NULL, '2026-05-10 01:12:29.662147', 1, 'https://www.odoo.com/documentation/17.0/applications/finance/fiscal_localizations.html', '{"en_US": ""}', 'l10n_fi', 'Avoin.Systems, Tawasta, Vizucom, Sprintit', '/account/static/description/l10n.png', 'uninstalled', NULL, '{"en_US": "Finnish Localization"}', 38, '{"en_US": "\nThis is the Odoo module to manage the accounting in Finland.\n============================================================\n\nAfter installing this module, you''ll have access to:\n    * Finnish chart of account\n    * Fiscal positions\n    * Invoice Payment Reference Types (Finnish Standard Reference & Finnish Creditor Reference (RF))\n    * Finnish Reference format for Sale Orders\n\nSet the payment reference type from the Sales Journal.\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (192, NULL, NULL, '2026-05-10 01:12:29.662147', 1, '', '{"en_US": ""}', 'l10n_ga', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Gabon - Accounting"}', 38, '{"en_US": "\nThis module implements the tax for Gabon.\n=================================================================\n\nThe Chart of Accounts is from SYSCOHADA.\n\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
