INSERT INTO public.ir_module_module VALUES (205, NULL, NULL, '2026-05-10 01:12:29.662147', 1, 'https://www.odoo.com/documentation/17.0/applications/finance/fiscal_localizations.html', '{"en_US": ""}', 'l10n_hu', 'Odoo S.A.', '/account/static/description/l10n.png', 'uninstalled', NULL, '{"en_US": "Hungary - Accounting"}', 38, '{"en_US": "\nAccounting chart and localization for Hungary\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (206, NULL, NULL, '2026-05-10 01:12:29.662147', 1, 'https://www.odootech.hu', '{"en_US": ""}', 'l10n_hu_edi', 'DO Tech (OdooTech Zrt.), BDSC Business Consulting Kft. & Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Hungary - E-invoicing"}', 39, '{"en_US": "\n* Electronically report invoices to the NAV (Hungarian Tax Agency) when issuing physical (paper) invoices.\n* Perform the Tax Audit Export (Adóhatósági Ellenőrzési Adatszolgáltatás) in NAV 3.0 format.\n"}', false, false, false, 'LGPL-3', 100, true, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (225, NULL, NULL, '2026-05-10 01:12:29.662147', 1, 'https://www.odoo.com/documentation/17.0/applications/finance/fiscal_localizations/italy.html', '{"en_US": ""}', 'l10n_it', 'OpenERP Italian Community', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Italy - Accounting"}', 38, '{"en_US": "\nPiano dei conti italiano di un''impresa generica.\n================================================\n\nItalian accounting chart and localization.\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
