INSERT INTO public.ir_module_module VALUES (226, NULL, NULL, '2026-05-10 01:12:29.662147', 1, 'http://www.odoo.com/', '{"en_US": ""}', 'l10n_it_edi', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Italy - E-invoicing"}', 39, '{"en_US": "\nE-invoice implementation\n"}', false, false, false, 'LGPL-3', 100, true, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (208, NULL, NULL, '2026-05-10 01:12:29.662147', 1, '', '{"en_US": ""}', 'l10n_id_efaktur', 'Odoo S.A.', '/account/static/description/l10n.png', 'uninstalled', NULL, '{"en_US": "Indonesia E-faktur"}', 39, '{"en_US": "\nE-Faktur Menu(Indonesia)\nFormat: 010.000-16.00000001\n* 2 (dua) digit pertama adalah Kode Transaksi\n* 1 (satu) digit berikutnya adalah Kode Status\n* 3 (tiga) digit berikutnya adalah Kode Cabang\n* 2 (dua) digit pertama adalah Tahun Penerbitan\n* 8 (delapan) digit berikutnya adalah Nomor Urut\n\nTo be able to export customer invoices as e-Faktur,\nyou need to put the ranges of numbers you were assigned\nby the government in Accounting > Customers > e-Faktur\n\nWhen you validate an invoice, where the partner has the ID PKP\nfield checked, a tax number will be assigned to that invoice.\nAfterwards, you can filter the invoices still to export in the\ninvoices list and click on Action > Download e-Faktur to download\nthe csv and upload it to the site of the government.\n\nYou can replace an already sent invoice by another by indicating\nthe replaced invoice and the new one and you can reset an invoice\nyou have not already sent to the government to reuse its number.\n"}', false, false, false, 'LGPL-3', 100, true, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (209, NULL, NULL, '2026-05-10 01:12:29.662147', 1, '', '{"en_US": ""}', 'l10n_id_efaktur_coretax', 'Odoo S.A.', '/account/static/description/l10n.png', 'uninstalled', NULL, '{"en_US": "Indonesia E-faktur (Coretax)"}', 39, '{"en_US": "\nE-invoicing feature provided by DJP (Indonesian Tax Office). As of January 1st 2025,\nIndonesia is using CoreTax system, which changes the file format and content of E-Faktur.\nWe''re changing from CSV files into XML.\nAt the same time, due to tax regulation changes back and forth, for general E-Faktur now,\nTaxBase (DPP) has to be mulitplied by factor of 11/12 while multiplied to tax of 12% which\nis resulting to 11%.\n"}', false, false, false, 'LGPL-3', 100, true, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (211, NULL, NULL, '2026-05-10 01:12:29.662147', 1, 'https://www.odoo.com/documentation/17.0/applications/finance/fiscal_localizations.html', '{"en_US": ""}', 'l10n_il', 'Odoo S.A.', '/account/static/description/l10n.png', 'uninstalled', NULL, '{"en_US": "Israel - Accounting"}', 38, '{"en_US": "\nThis is the latest basic Israelian localisation necessary to run Odoo in Israel:\n================================================================================\n\nThis module consists of:\n - Generic Israel Chart of Accounts\n - Taxes and tax report\n - Multiple Fiscal positions\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (212, NULL, NULL, '2026-05-10 01:12:29.662147', 1, 'https://www.odoo.com/documentation/17.0/applications/finance/fiscal_localizations/india.html', '{"en_US": ""}', 'l10n_in', 'Odoo S.A.', '/account/static/description/l10n.png', 'uninstalled', NULL, '{"en_US": "Indian - Accounting"}', 38, '{"en_US": "\nIndian Accounting: Chart of Account.\n====================================\n\nIndian accounting chart and localization.\n\nOdoo allows to manage Indian Accounting by providing Two Formats Of Chart of Accounts i.e Indian Chart Of Accounts - Standard and Indian Chart Of Accounts - Schedule VI.\n\nNote: The Schedule VI has been revised by MCA and is applicable for all Balance Sheet made after\n31st March, 2011. The Format has done away with earlier two options of format of Balance\nSheet, now only Vertical format has been permitted Which is Supported By Odoo.\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (213, NULL, NULL, '2026-05-10 01:12:29.662147', 1, '', '{"en_US": ""}', 'l10n_in_edi', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Indian - E-invoicing"}', 39, '{"en_US": "\nIndian - E-invoicing\n====================\nTo submit invoicing through API to the government.\nWe use \"Tera Software Limited\" as GSP\n\nStep 1: First you need to create an API username and password in the E-invoice portal.\nStep 2: Switch to company related to that GST number\nStep 3: Set that username and password in Odoo (Goto: Invoicing/Accounting -> Configuration -> Settings -> Customer Invoices or find \"E-invoice\" in search bar)\nStep 4: Repeat steps 1,2,3 for all GSTIN you have in odoo. If you have a multi-company with the same GST number then perform step 1 for the first company only.\n\nFor the creation of API username and password please ref this document: <https://service.odoo.co.in/einvoice_create_api_user>\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (214, NULL, NULL, '2026-05-10 01:12:29.662147', 1, '', '{"en_US": ""}', 'l10n_in_edi_ewaybill', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Indian - E-waybill"}', 39, '{"en_US": "\nIndian - E-waybill\n====================================\nTo submit E-waybill through API to the government.\nWe use \"Tera Software Limited\" as GSP\n\nStep 1: First you need to create an API username and password in the E-waybill portal.\nStep 2: Switch to company related to that GST number\nStep 3: Set that username and password in Odoo (Goto: Invoicing/Accounting -> Configration -> Settings -> Indian Electronic WayBill or find \"E-waybill\" in search bar)\nStep 4: Repeat steps 1,2,3 for all GSTIN you have in odoo. If you have a multi-company with the same GST number then perform step 1 for the first company only.\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (215, NULL, NULL, '2026-05-10 01:12:29.662147', 1, '', '{"en_US": ""}', 'l10n_in_ewaybill_port', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Indian - Shipping Ports for E-waybill"}', 37, '{"en_US": "\nIndian - E-waybill Shipping Ports\n====================================\nIntroduced a new module to manage Indian port codes, specifically for transport\nmodes classified as Air or Sea in the e-Way Bill system.\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (216, NULL, NULL, '2026-05-10 01:12:29.662147', 1, '', '{"en_US": ""}', 'l10n_in_ewaybill_stock', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Indian - E-waybill Stock"}', 39, '{"en_US": "\nIndian E-waybill for Stock\n==========================\n\nThis module enables users to create E-waybill from Inventory App without generating an invoice\n"}', false, false, false, 'LGPL-3', 100, true, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (219, NULL, NULL, '2026-05-10 01:12:29.662147', 1, 'https://www.odoo.com', '{"en_US": "Get warehouse address if the bill is created from Purchase Order"}', 'l10n_in_purchase_stock', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "India Purchase and Warehouse Management"}', 46, '{"en_US": "\nGet the warehouse address if the bill is created from the Purchase Order\n\nSo this module is to get the warehouse address if the bill is created from Purchase Order\n"}', false, false, false, 'LGPL-3', 100, true, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (221, NULL, NULL, '2026-05-10 01:12:29.662147', 1, 'https://www.odoo.com', '{"en_US": "Get warehouse address if the invoice is created from Sale Order"}', 'l10n_in_sale_stock', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "India Sales and Warehouse Management"}', 47, '{"en_US": "\nGet the warehouse address if the invoice is created from the Sale Order\nIn Indian EDI we send shipping address details if available\n\nSo this module is to get the warehouse address if the invoice is created from Sale Order\n"}', false, false, false, 'LGPL-3', 100, true, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (223, NULL, NULL, '2026-05-10 01:12:29.662147', 1, '', '{"en_US": ""}', 'l10n_in_withholding', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Indian - TDS"}', 37, '{"en_US": "\nSupport for Indian TDS (Tax Deducted at Source).\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (548, NULL, NULL, '2026-05-10 01:07:00.002872', 1, '', '{"en_US": "University, Education, Schools, Young, Play, Kids"}', 'theme_bewise', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Be Wise Theme"}', 68, '{"en_US": "Be Wise Theme"}', false, false, false, 'LGPL-3', 240, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (228, NULL, NULL, '2026-05-10 01:12:29.662147', 1, 'https://www.odoo.com/documentation/master/applications/finance/fiscal_localizations/italy.html', '{"en_US": ""}', 'l10n_it_edi_ndd', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Italy - E-invoicing - Additional module to support the debit notes (nota di debito - NDD)"}', 39, '{"en_US": "\nAdditional module to support the debit notes (nota di debito - NDD) by adding payment method and document types\n"}', false, false, false, 'LGPL-3', 100, true, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (229, NULL, NULL, '2026-05-10 01:12:29.662147', 1, 'https://www.odoo.com/documentation/master/applications/finance/fiscal_localizations/italy.html', '{"en_US": ""}', 'l10n_it_edi_ndd_account_dn', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Italy - E-invoicing - Bridge module between Italy NDD and Account Debit Note"}', 39, '{"en_US": "\nBridge module to support the debit notes (nota di debito - NDD) by adding debit note fields.\n"}', false, false, false, 'LGPL-3', 100, true, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (232, NULL, NULL, '2026-05-10 01:12:29.662147', 1, 'https://www.odoo.com/documentation/17.0/applications/finance/accounting/fiscal_localizations/localizations/italy.html', '{"en_US": ""}', 'l10n_it_edi_withholding', 'Odoo', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Italy - E-invoicing (Withholding)"}', 39, '{"en_US": "\nWithholding and Pension Fund handling for the E-invoice implementation for Italy.\n\n    The Withholding tax and the Pension Fund tax are computed like every other tax\n    with the ordering by sequence, so please be careful with the order of the taxes\n    in your tax configuration.\n\n    Please also update the Italian Accounting module (l10n_it) when you install this module.\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (233, NULL, NULL, '2026-05-10 01:12:29.662147', 1, 'https://www.odoo.com', '{"en_US": ""}', 'l10n_it_stock_ddt', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Italy - Stock DDT"}', 39, '{"en_US": "\nDocumento di Trasporto (DDT)\n\nWhenever goods are transferred between A and B, the DDT serves\nas a legitimation e.g. when the police would stop you.\n\nWhen you want to print an outgoing picking in an Italian company,\nit will print you the DDT instead.  It is like the delivery\nslip, but it also contains the value of the product,\nthe transportation reason, the carrier, ... which make it a DDT.\n\nWe also use a separate sequence for the DDT as the number should not\nhave any gaps and should only be applied at the moment the goods are sent.\n\nWhen invoices are related to their sale order and the sale order with the\ndelivery, the system will automatically calculate the linked DDTs for every\ninvoice line to export in the FatturaPA XML.\n"}', false, false, false, 'LGPL-3', 100, true, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (234, NULL, NULL, '2026-05-10 01:12:29.662147', 1, '', '{"en_US": ""}', 'l10n_jo', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Jordan - Accounting"}', 38, '{"en_US": "\nThis is the base module to manage the accounting chart for Jordan in Odoo.\n==============================================================================\n\nJordan accounting basic charts and localization.\n\nActivates:\n\n- Chart of accounts\n\n- Taxes\n\n- Tax report\n\n- Fiscal positions\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (235, NULL, NULL, '2026-05-10 01:12:29.662147', 1, '', '{"en_US": "Electronic Invoicing for Jordan UBL 2.1"}', 'l10n_jo_edi', 'Odoo S.A., Smart Way Business Solutions', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Jordan E-Invoicing"}', 39, '{"en_US": "\nAllows the users to integrate with JoFotara.\n"}', false, false, false, 'LGPL-3', 100, true, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (236, NULL, NULL, '2026-05-10 01:12:29.662147', 1, '', '{"en_US": "Extended features for JoFotara"}', 'l10n_jo_edi_extended', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Jordan E-Invoicing Extended Features"}', 39, '{"en_US": "\nThis module improves the Jordan E-invoicing (JoFotara) by the following:\n       1. Adds support for different invoice types and payment methods.\n       2. Introduces demo mode.\n"}', false, false, false, 'LGPL-3', 100, true, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (569, NULL, NULL, '2026-05-10 01:07:00.002872', 1, '', '{"en_US": "Environment, Nature, Ecology, Sustainable Development, Non Profit, NGO, Travels"}', 'theme_treehouse', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Treehouse Theme"}', 75, '{"en_US": "Treehouse Theme - Responsive Bootstrap Theme for Odoo CMS"}', false, false, false, 'LGPL-3', 140, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (581, NULL, NULL, '2026-05-10 01:07:00.002872', 1, 'https://www.odoo.com/app/website', '{"en_US": "Enterprise website builder"}', 'website', 'Odoo S.A.', '/website/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Website"}', 77, '{"en_US": "Odoo Website Builder\n--------------------\n\nGet an awesome and <a href=\"https://www.odoo.com/app/website\">free website</a>,\neasily customizable with the Odoo <a href=\"https://www.odoo.com/app/website\">website builder</a>.\n\nCreate enterprise grade website with our super easy builder. Use finely\ndesigned building blocks and edit everything inline.\n\nBenefit from out-of-the-box business features; e-Commerce, events, blogs, jobs\nannounces, customer references, call-to-actions, etc.\n\nEdit Anything Inline\n--------------------\n\nCreate beautiful websites with no technical knowledge. Odoo''s unique *''edit\ninline''* approach makes website creation surprisingly easy. No more complex\nbackend; just click anywhere to change any content.\n\n\"Want to change the price of a product? or put it in bold? Want to change a\nblog title?\" Just click and change. What you see is what you get. Really.\n\nAwesome. Astonishingly Beautiful.\n---------------------------------\n\nOdoo''s building blocks allow to design modern websites that are not possible\nwith traditional WYSIWYG page editors.\n\nWhether it''s for products descriptions, blogs or static pages, you don''t need\nto be a professional designer to create clean contents. Just drag and drop and\ncustomize predefined building blocks.\n\nEnterprise-Ready, out-of-the-box\n--------------------------------\n\nActivate ready-to-use enterprise features in just a click; e-commerce,\ncall-to-actions, jobs announces, events, customer references, blogs, etc.\n\nTraditional eCommerce and CMS have poorly designed backends as it''s not their\ncore focus. With the Odoo integration, you benefit from the best management\nsoftware to follow-up on your orders, your jobs applicants, your leads, etc.\n\nA Great Mobile Experience\n-------------------------\n\nGet a mobile friendly website thanks to our responsive design based on\nbootstrap. All your pages adapt automatically to the screen size. (mobile\nphones, tablets, desktop) You don''t have to worry about mobile contents, it\nworks by default.\n\nSEO tools at your finger tips\n-----------------------------\n\nThe *Promote* tool suggests keywords according to Google most searched terms.\nSearch Engine Optimization tools are ready to use, with no configuration\nrequired.\n\nGoogle Analytics tracks your shopping cart events by default. Sitemap and\nstructured content are created automatically for Google indexation.\n\nMulti-Languages Made Easy\n-------------------------\n\nGet your website translated in multiple languages with no effort. Odoo proposes\nand propagates translations automatically across pages, following what you edit\non the master page.\n\nDesigner-Friendly Templates\n---------------------------\n\nTemplates are awesome and easy to design. You don''t need to develop to create\nnew pages, themes or building blocks. We use a clean HTML structure, a\n[bootstrap](http://getbootstrap.com/) CSS.\n\nCustomize every page on the fly with the integrated template editor. Distribute\nyour work easily as an Odoo module.\n\nFluid Grid Layouting\n--------------------\n\nDesign perfect pages by drag and dropping building blocks. Move and scale them\nto fit the layout you are looking for.\n\nBuilding blocks are based on a responsive, mobile friendly fluid grid system\nthat appropriately scales up to 12 columns as the device or viewport size\nincreases.\n\nProfessional Themes\n-------------------\n\nDesign a custom theme or reuse pre-defined themes to customize the look and\nfeel of your website.\n\nTest new color scheme easily; you can change your theme at any time in just a\nclick.\n\nIntegrated With Odoo Apps\n-------------------------\n\n### e-Commerce\n\nPromote products, sell online, optimize visitors'' shopping experience.\n\n\n### Blog\n\nWrite news, attract new visitors, build customer loyalty.\n\n\n### Online Events\n\nSchedule, organize, promote or sell events online; conferences, trainings, webinars, etc.\n"}', true, false, false, 'LGPL-3', 20, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (582, NULL, NULL, '2026-05-10 01:07:00.002872', 1, 'https://www.odoo.com/app/blog', '{"en_US": "Publish blog posts, announces, news"}', 'website_blog', 'Odoo S.A.', '/website_blog/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Blog"}', 77, '{"en_US": "Odoo Blog\n----------\n\nWrite, Design, Promote and Engage with <a href=\"https://www.odoo.com/app/blog\">Odoo Blog</a>.\n\nExpress yourself with the Odoo enterprise grade blogging platform. Write\nbeautiful blog posts, engage with visitors, translate content and moderate\nsocial streams.\n\nGet your blog posts efficiently referenced in Google and translated in mutiple\nlanguages in just a few clicks.\n\nWrite Beautiful Blog Posts\n--------------------------\n\nDrag & Drop well designed *''Building Blocks''* to create beautifull blog posts\nthat perfectly integrates images, videos, call-to-actions, quotes, banners,\netc.\n\nWith our unique *''edit inline''* approach, you don''t need to be a designer to\ncreate awsome, good-looking, content. Each blog post will look like it''s\ndesigned by a professional designer.\n\nAutomated Translation by Professionals\n--------------------------------------\n\nGet your blog posts translated in multiple languages with no effort. Our\ntranslation \"on demand\" feature allows you to benefit from professional\ntranslators to translate all your changes automatically. (\\$0.05 per word)\nTranslated versions are updated automatically once translated by professionals\n(around 32 hours).\n\nEngage With Your Visitors\n-------------------------\n\nThe integrated website live chat feature allows you to start chatting in real time with\nyour visitors to get feedback on your recent posts or get ideas to write new\nposts.\n\nEngaging with your visitors is also a great way to convert visitors into\ncustomers.\n\nBuild Visitor Loyalty\n---------------------\n\nThe one click *follow* button will allow visitors to receive your blog posts by\nemail with no effort, without having to register. Social media icons allow\nvisitors to share your best blog posts easily.\n\nGoogle Analytics Integration\n----------------------------\n\nGet a clear visibility of your sales funnel. Odoo''s Google Analytics trackers\nare configured by default to track all kinds of events related to shopping\ncarts, call-to-actions, etc.\n\nAs Odoo marketing tools (mass mailing, campaigns, etc) are also linked with\nGoogle Analytics, you get a 360° view of your business.\n\nSEO Optimized Blog Posts\n------------------------\n\nSEO tools are ready to use, with no configuration required. Odoo suggests\nkeywords for your titles according to Google''s most searched terms, Google\nAnalytics tracks interests of your visitors, sitemaps are created automatically\nfor quick Google indexing, etc.\n\nThe system even creates structured content automatically to promote your\nproducts and events effectively in Google.\n\nDesigner-Friendly Themes\n------------------------\n\nThemes are awesome and easy to design. You don''t need to develop to create new\npages, themes or building blocks. We use a clean HTML structure, a\n[bootstrap](http://getbootstrap.com/) CSS and our modularity allows you to\ndistribute your themes easily.\n\nThe building block approach allows the website to remain clean after end-users\nstart creating new contents.\n\nEasy Access Rights\n------------------\n\nNot everyone requires the same access to your website. Designers manage the\nlayout of the site, editors approve content and authors write that content.\nThis lets you organize your publishing process according to your needs.\n\nOther access rights are related to business objects (products, people, events,\netc) and directly following Odoo''s standard access rights management, so you do\nnot have to configure things twice.\n"}', false, false, false, 'LGPL-3', 200, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (584, NULL, NULL, '2026-05-10 01:07:00.002872', 1, '', '{"en_US": "Generate leads from a contact form"}', 'website_crm', 'Odoo S.A.', '/website_crm/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Contact Form"}', 77, '{"en_US": "\nAdd capability to your website forms to generate leads or opportunities in the CRM app.\nForms has to be customized inside the *Website Builder* in order to generate leads.\n\nThis module includes contact phone and mobile numbers validation."}', false, false, false, 'LGPL-3', 54, true, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (585, NULL, NULL, '2026-05-10 01:07:00.002872', 1, '', '{"en_US": "Generate Leads/Opportunities from your website''s traffic"}', 'website_crm_iap_reveal', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Lead Generation From Website Visits"}', 12, '{"en_US": ""}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (588, NULL, NULL, '2026-05-10 01:07:00.002872', 1, '', '{"en_US": "Allows to send sms to website visitor that have lead"}', 'website_crm_sms', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Send SMS to Visitor with leads"}', 77, '{"en_US": "Allows to send sms to website visitor if the visitor is linked to a lead."}', false, false, false, 'LGPL-3', 54, true, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (590, NULL, NULL, '2026-05-10 01:07:00.002872', 1, 'https://www.odoo.com/app/events', '{"en_US": "Publish events, sell tickets"}', 'website_event', 'Odoo S.A.', '/website_event/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Events"}', 18, '{"en_US": "Organize Events, Trainings & Webinars\n-------------------------------------\n\n### Schedule, Promote, Sell, Organize\n\nOrganize, promote and sell events online. Whether you organize meetings, conferences, trainings or webinars, Odoo gives you all the features you need to manage your events.\n\nCreate Awesome Event Pages\n--------------------------\n\n### Get rid of old WYSIWYG editors\n\nCreate beautiful event pages by drag & droping well designed *''Building Blocks''*. Publish event photos, speakers, schedule, etc.\n\nOdoo''s unique *''edit inline''* approach makes website creation surprisingly easy. \"Want to introduce a speaker? to change the price of a ticket? to update a banner? promote sponsors?\" just click and change.\n\nSell Tickets Online\n-------------------\n\n### Automate the registration and payment process\n\nSell registrations to your event with the multi-ticketing feature. Events can be free or for a fee. Attendees can pay online with a credit card or on invoice, based on your configuration.\n\nBoost your sales with early-bird prices, special conditions for members, or extra services with multiple tickets.\n\nA Clean Google Analytics Integration\n------------------------------------\n\n### Control your sales funnel with Google Analytics\n\nGet a clear visibility of your sales funnel. Odoo''s Google Analytics trackers are configured by default to track all kind of events related to shopping carts, call-to-actions, etc.\n\nAs Odoo marketing tools (mass mailing, campaigns, etc) are also linked with Google Analytics, you get a full view of your business.\n\nPromote Events Efficiently\n--------------------------\n\n### Mass Mailing & Social Media\n\nUse the segmentation, the social network integration and mass mailing features to promote your events to the right audience. Setup automated emails to attendees to send them last minute details.\n\nDesigner-Friendly Themes\n------------------------\n\n### Designers love working on Odoo\n\nThemes are awesome and easy to design. You don''t need to develop to create new pages, themes or building blocks. We use a clean HTML structure, a [bootstrap](http://getbootstrap.com/) CSS and our modularity allows to distribute your themes easily.\n\nThe building block approach allows the website to stay clean after the end-users start creating new contents.\n\nMake Your Event More Visible\n----------------------------\n\n### SEO tools at your finger tips\n\nSEO tools are ready to use, with no configuration required. Odoo suggests keywords according to Google most searched terms, Google Analytics tracks your shopping cart events and sitemap are created automatically.\n\nWe even do structured content automatically to promote your events and products efficiently in Google.\n\nLeverage Social Media\n---------------------\n\n### Optimize: from Ads to Conversions\n\nCreate new landing pages easily with the Odoo inline editing feature. Send visitors of your different marketing campaigns to event landing pages to optimize conversions.\n\nAnd Much More...\n----------------\n\n### Schedule\n\n-   Calendar of Events\n-   Publish related documents\n-   Ressources allocation\n-   Automate purchases (catering...)\n-   Multiple locations and organizers\n-   Mobile Interface\n\n### Sell\n\n-   Online or offline sales\n-   Automated invoicing\n-   Cancellation policies\n-   Specific prices for members\n-   Dashboards and reporting\n\n### Organize\n\n-   Advanced Planification\n-   Print Badges\n-   Automate Follow-up Emails\n-   Min/Max capacities\n-   Manage classes and ressources\n-   Create group of attendees\n-   Automate statisfaction surveys\n\nFully Integrated With Others Apps\n---------------------------------\n\n### Get hundreds of open source apps for free\n\n\n### eCommerce\n\nPromote products, sell online, optimize visitors'' shopping experiences.\n\n\n### Blog\n\nWrite news, attract new visitors, build customer loyalty.\n\n\n### Our Team\n\nCreate a great \"About us\" page by presenting your team efficiently.\n"}', true, false, false, 'LGPL-3', 140, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
