INSERT INTO public.ir_module_module VALUES (237, NULL, NULL, '2026-05-10 01:12:29.662147', 1, 'https://www.odoo.com/documentation/17.0/applications/finance/fiscal_localizations.html', '{"en_US": ""}', 'l10n_jp', 'Quartile Limited (https://www.quartile.co/)', '/account/static/description/l10n.png', 'uninstalled', NULL, '{"en_US": "Japan - Accounting"}', 38, '{"en_US": "\n\nOverview:\n---------\n\n* Chart of Accounts and Taxes template for companies in Japan.\n* This probably does not cover all the necessary accounts for a company. You are expected to add/delete/modify accounts based on this template.\n\nNote:\n-----\n\n* Fiscal positions ''内税'' and ''外税'' have been added to handle special requirements which might arise from POS implementation. [1]  Under normal circumstances, you might not need to use those at all.\n\n[1] See https://github.com/odoo/odoo/pull/6470 for detail.\n\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (238, NULL, NULL, '2026-05-10 01:12:29.662147', 1, '', '{"en_US": ""}', 'l10n_jp_ubl_pint', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Japan - UBL PINT"}', 39, '{"en_US": "\nThe UBL PINT e-invoicing format for Japan is based on the Peppol International (PINT) model for Billing.\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
