INSERT INTO public.ir_module_module VALUES (242, NULL, NULL, '2026-05-10 01:12:29.662147', 1, '', '{"en_US": ""}', 'l10n_kw', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Kuwait - Accounting"}', 38, '{"en_US": "\nThis is the base module to manage the accounting chart for Kuwait in Odoo.\n==============================================================================\nKuwait accounting basic charts and localization.\nActivates:\n- Chart of accounts\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
