INSERT INTO public.ir_module_module VALUES (247, NULL, NULL, '2026-05-10 01:12:29.662147', 1, '', '{"en_US": ""}', 'l10n_lb_account', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Lebanon - Accounting"}', 38, '{"en_US": "\nThis is the base module to manage the accounting chart for Lebanon in Odoo.\n==============================================================================\nLebanon accounting basic charts,taxes and localization.\nActivates:\n* Chart of Accounts\n* Taxes\n* Fiscal Positions\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
