INSERT INTO public.ir_module_module VALUES (248, NULL, NULL, '2026-05-10 01:12:29.662147', 1, 'https://www.odoo.com/documentation/17.0/applications/finance/fiscal_localizations.html', '{"en_US": ""}', 'l10n_lt', 'Focusate', '/account/static/description/l10n.png', 'uninstalled', NULL, '{"en_US": "Lithuania - Accounting"}', 38, '{"en_US": "\nChart of Accounts (COA) Template for Lithuania''s Accounting.\n\nThis module also includes:\n\n* List of available banks in Lithuania.\n* Tax groups.\n* Most common Lithuanian Taxes.\n* Fiscal positions.\n* Account Tags.\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (250, NULL, NULL, '2026-05-10 01:12:29.662147', 1, 'https://allegro.lv', '{"en_US": ""}', 'l10n_lv', 'Allegro IT, Chick.Farm', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Latvia - Accounting"}', 38, '{"en_US": "\nChart of Accounts (COA) Template for Latvia''s Accounting.\nThis module also includes:\n* Tax groups,\n* Most common Latvian Taxes,\n* Fiscal positions,\n* Latvian bank list.\n\nauthor is Allegro IT (visit for more information https://www.allegro.lv)\nco-author is Chick.Farm (visit for more information https://www.myacc.cloud)\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (252, NULL, NULL, '2026-05-10 01:12:29.662147', 1, '', '{"en_US": ""}', 'l10n_ml', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Mali - Accounting"}', 38, '{"en_US": "\nThis module implements the tax for Mali.\n=================================================================\n\nThe Chart of Accounts is from SYSCOHADA.\n\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (254, NULL, NULL, '2026-05-10 01:12:29.662147', 1, 'https://www.odoo.com/documentation/master/applications/finance/fiscal_localizations.html', '{"en_US": ""}', 'l10n_mr', 'Odoo S.A.', '/account/static/description/l10n.png', 'uninstalled', NULL, '{"en_US": "Mauritania - Accounting"}', 38, '{"en_US": "\nMauritania basic package that contains the chart of accounts, the taxes, tax reports, etc.\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (257, NULL, NULL, '2026-05-10 01:12:29.662147', 1, '', '{"en_US": ""}', 'l10n_mu_account', 'Odoo SA', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Mauritius - Accounting"}', 38, '{"en_US": "\nThis is the base module to manage the accounting chart for the Republic of Mauritius in Odoo.\n==============================================================================================\n    - Chart of accounts\n    - Taxes\n    - Fiscal positions\n    - Default settings\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (258, NULL, NULL, '2026-05-10 01:12:29.662147', 1, 'https://www.odoo.com/documentation/17.0/applications/finance/fiscal_localizations/mexico.html', '{"en_US": ""}', 'l10n_mx', 'Vauxoo', '/account/static/description/l10n.png', 'uninstalled', NULL, '{"en_US": "Mexico - Accounting"}', 38, '{"en_US": "\nMinimal accounting configuration for Mexico.\n============================================\n\nThis Chart of account is a minimal proposal to be able to use OoB the\naccounting feature of Odoo.\n\nThis doesn''t pretend be all the localization for MX it is just the minimal\ndata required to start from 0 in mexican localization.\n\nThis modules and its content is updated frequently by openerp-mexico team.\n\nWith this module you will have:\n\n - Minimal chart of account tested in production environments.\n - Minimal chart of taxes, to comply with SAT_ requirements.\n\n.. _SAT: http://www.sat.gob.mx/\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (260, NULL, NULL, '2026-05-10 01:12:29.662147', 1, 'https://www.odoo.com/documentation/17.0/applications/finance/fiscal_localizations.html', '{"en_US": ""}', 'l10n_my', 'Odoo PS', '/account/static/description/l10n.png', 'uninstalled', NULL, '{"en_US": "Malaysia - Accounting"}', 38, '{"en_US": "\nThis is the base module to manage the accounting chart for Malaysia in Odoo.\n==============================================================================\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
