INSERT INTO public.ir_module_module VALUES (262, NULL, NULL, '2026-05-10 01:12:29.662147', 1, '', '{"en_US": "Extended features for the E-invoicing using MyInvois"}', 'l10n_my_edi_extended', 'Odoo S.A.', '/account/static/description/l10n.png', 'uninstalled', NULL, '{"en_US": "Malaysia - E-invoicing Extended Features"}', 39, '{"en_US": "\nThis module improves the MyInvois E-invoicing feature by adding proper support for self billing, rendering the MyInvois\nQR code in the invoice PDF file and allows better management of foreign customer TIN.\n"}', false, false, false, 'LGPL-3', 100, true, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
