INSERT INTO public.ir_module_module VALUES (269, NULL, NULL, '2026-05-10 01:12:29.662147', 1, 'https://www.odoo.com/documentation/17.0/applications/finance/fiscal_localizations.html', '{"en_US": ""}', 'l10n_nz', 'Odoo S.A., Richard deMeester - Willow IT', '/account/static/description/l10n.png', 'uninstalled', NULL, '{"en_US": "New Zealand - Accounting"}', 38, '{"en_US": "\nNew Zealand Accounting Module\n=============================\n\nNew Zealand accounting basic charts and localizations.\n\nAlso:\n    - activates a number of regional currencies.\n    - sets up New Zealand taxes.\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (384, NULL, NULL, '2026-05-10 01:12:29.662147', 1, '', '{"en_US": ""}', 'portal_rating', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Portal Rating"}', 4, '{"en_US": "\nBridge module adding rating capabilities on portal. It includes notably\ninclusion of rating directly within the customer portal discuss widget.\n"}', false, false, false, 'LGPL-3', 100, true, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (272, NULL, NULL, '2026-05-10 01:12:29.662147', 1, '', '{"en_US": ""}', 'l10n_pe_pos', 'Vauxoo, Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Peruvian - Point of Sale with Pe Doc"}', 40, '{"en_US": "\nThis module brings the technical requirement for the Peruvian regulation.\nInstall this if you are using the Point of Sale app in Peru.\n"}', false, false, false, 'LGPL-3', 100, true, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (275, NULL, NULL, '2026-05-10 01:12:29.662147', 1, 'https://www.odoo.com/documentation/17.0/applications/finance/fiscal_localizations.html', '{"en_US": ""}', 'l10n_pk', 'Odoo S.A.', '/account/static/description/l10n.png', 'uninstalled', NULL, '{"en_US": "Pakistan - Accounting"}', 38, '{"en_US": "\nPakistan Accounting Module\n=======================================================\nPakistan accounting basic charts and localization.\n\nActivates:\n\n- Chart of Accounts\n- Taxes\n- Tax Report\n- Withholding Tax Report\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (276, NULL, NULL, '2026-05-10 01:12:29.662147', 1, 'https://www.odoo.com/documentation/17.0/applications/finance/fiscal_localizations.html', '{"en_US": ""}', 'l10n_pl', 'Odoo S.A., Grzegorz Grzelak (OpenGLOBE) (http://www.openglobe.pl)', '/account/static/description/l10n.png', 'uninstalled', NULL, '{"en_US": "Poland - Accounting"}', 38, '{"en_US": "\nThis is the module to manage the accounting chart and taxes for Poland in Odoo.\n==================================================================================\n\nTo jest moduł do tworzenia wzorcowego planu kont, podatków, obszarów podatkowych i\nrejestrów podatkowych. Moduł ustawia też konta do kupna i sprzedaży towarów\nzakładając, że wszystkie towary są w obrocie hurtowym.\n\nNiniejszy moduł jest przeznaczony dla odoo 8.0.\nWewnętrzny numer wersji OpenGLOBE 1.02\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (278, NULL, NULL, '2026-05-10 01:12:29.662147', 1, '', '{"en_US": ""}', 'l10n_qa', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Qatar - Accounting"}', 38, '{"en_US": "\nThis is the base module to manage the accounting chart for Qatar in Odoo.\n==============================================================================\nQatar accounting basic charts and localization.\nActivates:\n- Chart of accounts\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (634, NULL, NULL, '2026-05-10 01:07:00.002872', 1, 'https://www.odoo.com/app/elearning', '{"en_US": "Manage and publish an eLearning platform"}', 'website_slides', 'Odoo S.A.', '/website_slides/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "eLearning"}', 78, '{"en_US": "\nCreate Online Courses\n=====================\n\nFeaturing\n\n * Integrated course and lesson management\n * Fullscreen navigation\n * Support Youtube videos, Google documents, PDF, images, articles\n * Test knowledge with quizzes\n * Filter and Tag\n * Statistics\n"}', true, false, false, 'LGPL-3', 125, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
