INSERT INTO public.ir_module_module VALUES (637, NULL, NULL, '2026-05-10 01:07:00.002872', 1, '', '{"en_US": "Allows to send sms to website visitor"}', 'website_sms', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Send SMS to Visitor"}', 77, '{"en_US": "Allows to send sms to website visitor if the visitor is linked to a partner."}', false, false, false, 'LGPL-3', 54, true, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (30, NULL, NULL, '2026-05-10 01:07:08.393265', 1, '', '{"en_US": ""}', 'auth_totp', 'Odoo S.A.', '/base/static/description/icon.png', 'installed', '17.0.1.0', '{"en_US": "Two-Factor Authentication (TOTP)"}', 7, '{"en_US": "\nTwo-Factor Authentication (TOTP)\n================================\nAllows users to configure two-factor authentication on their user account\nfor extra security, using time-based one-time passwords (TOTP).\n\nOnce enabled, the user will need to enter a 6-digit code as provided\nby their authenticator app before being granted access to the system.\nAll popular authenticator apps are supported.\n\nNote: logically, two-factor prevents password-based RPC access for users\nwhere it is enabled. In order to be able to execute RPC scripts, the user\ncan setup API keys to replace their main password.\n"}', false, true, false, 'LGPL-3', 100, true, false, NULL, NULL, NULL, NULL, '', '', '* INHERIT res.users.view.search.inherit.auth.totp (search)
* INHERIT user form: add totp status (form)
* INHERIT users preference: totp (form)
Two-Factor Authentication (qweb)
auth_totp wizard (form)', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (279, NULL, NULL, '2026-05-10 01:12:29.662147', 1, 'https://www.odoo.com/documentation/17.0/applications/finance/fiscal_localizations/romania.html', '{"en_US": ""}', 'l10n_ro', 'Fekete Mihai (NextERP Romania SRL), Odoo S.A.', '/account/static/description/l10n.png', 'uninstalled', NULL, '{"en_US": "Romania - Accounting"}', 38, '{"en_US": "\nThis is the module to manage the Accounting Chart, VAT structure, Fiscal Position and Tax Mapping.\nIt also adds the Registration Number for Romania in Odoo.\n================================================================================================================\n\nRomanian accounting chart and localization.\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
