INSERT INTO public.ir_module_module VALUES (294, NULL, NULL, '2026-05-10 01:12:29.662147', 1, 'https://www.odoo.com/documentation/17.0/applications/finance/fiscal_localizations/singapore.html', '{"en_US": ""}', 'l10n_sg', 'Tech Receptives', '/account/static/description/l10n.png', 'uninstalled', NULL, '{"en_US": "Singapore - Accounting"}', 38, '{"en_US": "\nSingapore accounting chart and localization.\n=======================================================\n\nThis module add, for accounting:\n - The Chart of Accounts of Singapore\n - Field UEN (Unique Entity Number) on company and partner\n - Field PermitNo and PermitNoDate on invoice\n\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
