INSERT INTO public.ir_module_module VALUES (297, NULL, NULL, '2026-05-10 01:12:29.662147', 1, 'https://www.odoo.com/documentation/17.0/applications/finance/fiscal_localizations.html', '{"en_US": ""}', 'l10n_sk', '26HOUSE (http://www.26house.com)', '/account/static/description/l10n.png', 'uninstalled', NULL, '{"en_US": "Slovak - Accounting"}', 38, '{"en_US": "\nSlovakia accounting chart and localization: Chart of Accounts 2020, basic VAT rates +\nfiscal positions.\n\nTento modul definuje:\n• Slovenskú účtovú osnovu za rok 2020\n\n• Základné sadzby pre DPH z predaja a nákupu\n\n• Základné fiškálne pozície pre slovenskú legislatívu\n\n\nPre viac informácií kontaktujte info@26house.com alebo navštívte https://www.26house.com.\n\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
