INSERT INTO public.ir_module_module VALUES (534, NULL, NULL, '2026-05-10 01:12:29.662147', 1, '', '{"en_US": "Spreadsheet Test, mainly to test the mixin behavior"}', 'test_spreadsheet', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Spreadsheet Test"}', 4, '{"en_US": "This module contains tests related to spreadsheet.\n    The modules exposes some mixin that are only implemented in other functional modules.\n    When trying to test a global behavior of the mixin, it makes no sense to test it in\n    each module implementing the mixin but rather test a dummy implementation of the later,\n    hence the need for this test module.\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (617, NULL, NULL, '2026-05-10 01:12:29.662147', 1, '', '{"en_US": "Partner module for website"}', 'website_partner', 'Odoo S.A.', '/website_partner/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Website Partner"}', 4, '{"en_US": "\nThis is a base module. It holds website-related stuff for Contact model (res.partner).\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (573, NULL, NULL, '2026-05-10 01:12:29.662147', 1, '', '{"en_US": "Add a link to edit a translation in Transifex"}', 'transifex', 'Odoo S.A.', '/transifex/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Transifex integration"}', 5, '{"en_US": "\nTransifex integration\n=====================\nThis module will add a link to the Transifex project in the translation view.\nThe purpose of this module is to speed up translations of the main modules.\n\nTo work, Odoo uses Transifex configuration files `.tx/config` to detect the\nproject source. Custom modules will not be translated (as not published on\nthe main Transifex project).\n\nThe language the user tries to translate must be activated on the Transifex\nproject.\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (578, NULL, NULL, '2026-05-10 01:12:29.662147', 1, '', '{"en_US": ""}', 'web_hierarchy', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Web Hierarchy"}', 4, '{"en_US": "\nOdoo Web Hierarchy view\n=======================\n\nThis module adds a new view called to be able to define a view to display\nan organization such as an Organization Chart for employees for instance.\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (583, NULL, NULL, '2026-05-10 01:12:29.662147', 1, '', '{"en_US": ""}', 'website_cf_turnstile', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Cloudflare Turnstile"}', 4, '{"en_US": "\nThis module implements Cloudflare Turnstile so that you can prevent bot spam on your forms.\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (611, NULL, NULL, '2026-05-10 01:12:29.662147', 1, '', '{"en_US": "Chat with your website visitors"}', 'website_livechat', 'Odoo S.A.', '/website_livechat/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Website Live Chat"}', 4, '{"en_US": "\nAllow website visitors to chat with the collaborators. This module also brings a feedback tool for the livechat and web pages to display your channel with its ratings on the website.\n"}', false, false, false, 'LGPL-3', 100, true, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
