INSERT INTO public.ir_module_module VALUES (285, NULL, NULL, '2026-05-10 01:12:29.662147', 1, '', '{"en_US": "Additional module to synchronize bills with the SPV"}', 'l10n_ro_efactura_synchronize', 'Odoo', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Romania - Synchronize E-Factura"}', 39, '{"en_US": ""}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (289, NULL, NULL, '2026-05-10 01:12:29.662147', 1, 'https://www.odoo.com/documentation/17.0/applications/finance/fiscal_localizations/saudi_arabia.html', '{"en_US": ""}', 'l10n_sa', 'Odoo S.A., DVIT.ME (http://www.dvit.me)', '/account/static/description/l10n.png', 'uninstalled', NULL, '{"en_US": "Saudi Arabia - Accounting"}', 38, '{"en_US": "\nSaudi Arabia Accounting Module\n===========================================================\nSaudi Arabia Accounting Basic Charts and Localization\n\nActivates:\n\n- Chart of Accounts\n- Taxes\n- Vat Filling Report\n- Withholding Tax Report\n- Fiscal Positions\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (303, NULL, NULL, '2026-05-10 01:12:29.662147', 1, '', '{"en_US": ""}', 'l10n_tn', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Tunisia - Accounting"}', 38, '{"en_US": "\nThis is the module to manage the accounting chart for Tunisia in Odoo.\n=======================================================================\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (314, NULL, NULL, '2026-05-10 01:12:29.662147', 1, 'https://www.odoo.com/documentation/master/applications/finance/fiscal_localizations/uruguay.html', '{"en_US": ""}', 'l10n_uy', 'Uruguay l10n Team, Guillem Barba, ADHOC', '/account/static/description/l10n.png', 'uninstalled', NULL, '{"en_US": "Uruguay - Accounting"}', 38, '{"en_US": "\nGeneral Chart of Accounts.\n==========================\n\nThis module adds accounting functionalities for the Uruguayan localization, representing the minimum required configuration for a company to operate in Uruguay under the regulations and guidelines provided by the DGI (Dirección General Impositiva).\n\nAmong the functionalities are:\n\n* Uruguayan Generic Chart of Account\n* Pre-configured VAT Taxes and Tax Groups.\n* Legal document types in Uruguay.\n* Valid contact identification types in Uruguay.\n* Configuration and activation of Uruguayan Currencies  (UYU, UYI - Unidad Indexada Uruguaya).\n* Frequently used default contacts already configured: DGI, Consumidor Final Uruguayo.\n\nConfiguration\n-------------\n\nDemo data for testing:\n\n* Uruguayan company named \"UY Company\" with the Uruguayan chart of accounts already installed, pre configured taxes, document types and identification types.\n* Uruguayan contacts for testing:\n\n   * IEB Internacional\n   * Consumidor Final Anónimo Uruguayo.\n\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (316, NULL, NULL, '2026-05-10 01:12:29.662147', 1, 'https://www.odoo.com/documentation/17.0/applications/finance/fiscal_localizations.html', '{"en_US": ""}', 'l10n_ve', 'Odoo S.A., Vauxoo', '/account/static/description/l10n.png', 'uninstalled', NULL, '{"en_US": "Venezuela - Accounting"}', 38, '{"en_US": "\nChart of Account for Venezuela.\n===============================\n\nVenezuela doesn''t have any chart of account by law, but the default\nproposed in Odoo should comply with some Accepted best practices in Venezuela,\nthis plan comply with this practices.\n\nThis module has been tested as base for more of 1000 companies, because\nit is based in a mixtures of most common software in the Venezuelan\nmarket what will allow for sure to accountants feel them first steps with\nOdoo more comfortable.\n\nThis module doesn''t pretend be the total localization for Venezuela,\nbut it will help you to start really quickly with Odoo in this country.\n\nThis module give you.\n---------------------\n\n- Basic taxes for Venezuela.\n- Have basic data to run tests with community localization.\n- Start a company from 0 if your needs are basic from an accounting PoV.\n\nWe recomend use of account_anglo_saxon if you want valued your\nstocks as Venezuela does with out invoices.\n\nIf you install this module, and select Custom chart a basic chart will be proposed,\nbut you will need set manually account defaults for taxes.\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (422, NULL, NULL, '2026-05-10 01:12:29.662147', 1, '', '{"en_US": "project profitability items computation"}', 'project_account', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Project - Account"}', 4, '{"en_US": "\nAllows the computation of some section for the project profitability\n==================================================================================================\nThis module allows the computation of the ''Vendor Bills'', ''Other Costs'' and ''Other Revenues'' section for the project profitability, in the project update view.\n"}', false, false, false, 'LGPL-3', 100, true, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
