INSERT INTO public.ir_module_module VALUES (439, NULL, NULL, '2026-05-10 01:07:00.002872', 1, '', '{"en_US": "Repair damaged products"}', 'repair', 'Odoo S.A.', '/repair/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Repairs"}', 53, '{"en_US": "\nThe aim is to have a complete module to manage all products repairs.\n====================================================================\n\nThe following topics are covered by this module:\n------------------------------------------------------\n    * Add/remove products in the reparation\n    * Impact for stocks\n    * Warranty concept\n    * Repair quotation report\n    * Notes for the technician and for the final customer\n"}', true, false, false, 'LGPL-3', 230, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (444, NULL, NULL, '2026-05-10 01:07:00.002872', 1, '', '{"en_US": "Quotation, Sales Orders, Delivery & Invoicing Control"}', 'sale_expense', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Sales Expense"}', 9, '{"en_US": "\nReinvoice Employee Expense\n==========================\n\nCreate some products for which you can re-invoice the costs.\nThis module allow to reinvoice employee expense, by setting the SO directly on the expense.\n"}', false, false, false, 'LGPL-3', 100, true, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (445, NULL, NULL, '2026-05-10 01:07:00.002872', 1, '', '{"en_US": ""}', 'sale_expense_margin', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Sales Expense Margin"}', 9, '{"en_US": "When re-invoicing the expense on the SO, set the cost to the total untaxed amount of the expense."}', false, false, false, 'LGPL-3', 100, true, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
