INSERT INTO public.ir_module_module VALUES (86, NULL, NULL, '2026-05-10 01:07:07.223274', 1, '', '{"en_US": "Employee Hourly Wage"}', 'hr_hourly_cost', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Employee Hourly Wage"}', 28, '{"en_US": "\nThis module assigns an hourly wage to employees to be used by other modules.\n============================================================================\n\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (18, NULL, NULL, '2026-05-10 01:07:07.223274', 1, '', '{"en_US": ""}', 'account_qr_code_sepa', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Account SEPA QR Code"}', 3, '{"en_US": "\nThis module adds support for SEPA Credit Transfer QR-code generation.\n"}', false, false, false, 'LGPL-3', 100, true, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (38, NULL, NULL, '2026-05-10 01:07:07.223274', 1, '', '{"en_US": ""}', 'base_automation', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Automation Rules"}', 9, '{"en_US": "\nThis module allows to implement automation rules for any object.\n================================================================\n\nUse automation rules to automatically trigger actions for various screens.\n\n**Example:** A lead created by a specific user may be automatically set to a specific\nSales Team, or an opportunity which still has status pending after 14 days might\ntrigger an automatic reminder email.\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (5, NULL, NULL, '2026-05-10 01:12:29.662147', 1, '', '{"en_US": "Debit Notes"}', 'account_debit_note', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Debit Notes"}', 2, '{"en_US": "\nIn a lot of countries, a debit note is used as an increase of the amounts of an existing invoice \nor in some specific cases to cancel a credit note. \nIt is like a regular invoice, but we need to keep track of the link with the original invoice.  \nThe wizard used is similar as the one for the credit note.\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (7, NULL, NULL, '2026-05-10 01:12:29.662147', 1, '', '{"en_US": ""}', 'account_edi', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Import/Export Invoices From XML/PDF"}', 2, '{"en_US": "\nElectronic Data Interchange\n=======================================\nEDI is the electronic interchange of business information using a standardized format.\n\nThis is the base module for import and export of invoices in various EDI formats, and the\nthe transmission of said documents to various parties involved in the exchange (other company,\ngovernements, etc.)\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (8, NULL, NULL, '2026-05-10 01:12:29.662147', 1, '', '{"en_US": ""}', 'account_edi_proxy_client', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Proxy features for account_edi"}', 2, '{"en_US": "\nThis module adds generic features to register an Odoo DB on the proxy responsible for receiving data (via requests from web-services).\n- An edi_proxy_user has a unique identification on a specific proxy type (e.g. l10n_it_edi, peppol) which\nallows to identify him when receiving a document addressed to him. It is linked to a specific company on a specific\nOdoo database.\n- Encryption features allows to decrypt all the user''s data when receiving it from the proxy.\n- Authentication offers an additionnal level of security to avoid impersonification, in case someone gains to the user''s database.\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (49, NULL, NULL, '2026-05-10 01:07:07.223274', 1, '', '{"en_US": "Schedule employees'' meetings"}', 'calendar', 'Odoo S.A.', '/calendar/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Calendar"}', 11, '{"en_US": "\nThis is a full-featured calendar system.\n========================================\n\nIt supports:\n------------\n    - Calendar of events\n    - Recurring events\n\nIf you need to manage your meetings, you should install the CRM module.\n"}', true, false, false, 'LGPL-3', 165, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (60, NULL, NULL, '2026-05-10 01:07:07.223274', 1, '', '{"en_US": " Let''s choose a Point Relais® as shipping address "}', 'delivery_mondialrelay', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "delivery_mondialrelay"}', 16, '{"en_US": "\nThis module allow your customer to choose a Point Relais® and use it as shipping address.\nThis module doesn''t implement the WebService. It is only the integration of the widget.\n\nDelivery price pre-configured is an example, you need to adapt the pricing''s rules.\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (64, NULL, NULL, '2026-05-10 01:07:07.223274', 1, '', '{"en_US": "Manage event booths"}', 'event_booth', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Events Booths"}', 18, '{"en_US": "\nCreate booths for your favorite event.\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (65, NULL, NULL, '2026-05-10 01:07:07.223274', 1, '', '{"en_US": "Manage event booths sale"}', 'event_booth_sale', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Events Booths Sales"}', 18, '{"en_US": "\nSell your event booths and track payments on sale orders.\n"}', false, false, false, 'LGPL-3', 100, true, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (78, NULL, NULL, '2026-05-10 01:07:07.223274', 1, 'https://www.odoo.com/app/employees', '{"en_US": "Track employee attendance"}', 'hr_attendance', 'Odoo S.A.', '/hr_attendance/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Attendances"}', 22, '{"en_US": "\nThis module aims to manage employee''s attendances.\n==================================================\n\nKeeps account of the attendances of the employees on the basis of the\nactions(Check in/Check out) performed by them.\n"}', true, false, false, 'LGPL-3', 240, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (79, NULL, NULL, '2026-05-10 01:07:07.223274', 1, 'https://www.odoo.com/app/employees', '{"en_US": ""}', 'hr_contract', 'Odoo S.A.', '/hr_contract/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Employee Contracts"}', 23, '{"en_US": "\nAdd all information on the employee form to manage contracts.\n=============================================================\n\n    * Contract\n    * Place of Birth,\n    * Medical Examination Date\n    * Company Vehicle\n\nYou can assign several contracts per employee.\n"}', true, false, false, 'LGPL-3', 335, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (80, NULL, NULL, '2026-05-10 01:07:07.223274', 1, 'https://www.odoo.com/app/expenses', '{"en_US": "Submit, validate and reinvoice employee expenses"}', 'hr_expense', 'Odoo S.A.', '/hr_expense/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Expenses"}', 24, '{"en_US": "\nManage expenses by Employees\n============================\n\nThis application allows you to manage your employees'' daily expenses. It gives you access to your employees’ fee notes and give you the right to complete and validate or refuse the notes. After validation it creates an invoice for the employee.\nEmployee can encode their own expenses and the validation flow puts it automatically in the accounting after validation by managers.\n\n\nThe whole flow is implemented as:\n---------------------------------\n* Draft expense\n* Submitted by the employee to his manager\n* Approved by his manager\n* Validation by the accountant and accounting entries creation\n\nThis module also uses analytic accounting and is compatible with the invoice on timesheet module so that you are able to automatically re-invoice your customers'' expenses if your work by project.\n"}', true, false, false, 'LGPL-3', 70, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (84, NULL, NULL, '2026-05-10 01:07:07.223274', 1, '', '{"en_US": "Attendance Holidays"}', 'hr_holidays_attendance', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "HR Attendance Holidays"}', 19, '{"en_US": "\nConvert employee''s extra hours to leave allocations.\n"}', false, false, false, 'LGPL-3', 100, true, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (76, NULL, NULL, '2026-05-10 01:12:29.662147', 1, '', '{"en_US": ""}', 'google_recaptcha', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Google reCAPTCHA integration"}', 4, '{"en_US": "\nThis module implements reCaptchaV3 so that you can prevent bot spam on your public modules.\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (90, NULL, NULL, '2026-05-10 01:07:07.223274', 1, '', '{"en_US": ""}', 'hr_presence', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Employee Presence Control"}', 19, '{"en_US": "\nControl Employees Presence\n==========================\n\nBased on:\n    * The IP Address\n    * The User''s Session\n    * The Sent Emails\n\nAllows to contact directly the employee in case of unjustified absence.\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (94, NULL, NULL, '2026-05-10 01:07:07.223274', 1, '', '{"en_US": "Surveys"}', 'hr_recruitment_survey', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Hr Recruitment Interview Forms"}', 19, '{"en_US": "\nUse interview forms during recruitment process.\nThis module is integrated with the survey module\nto allow you to define interviews for different jobs.\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (95, NULL, NULL, '2026-05-10 01:07:07.223274', 1, '', '{"en_US": "Manage skills, knowledge and resume of your employees"}', 'hr_skills', 'Odoo S.A.', '/hr_skills/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Skills Management"}', 21, '{"en_US": "\nSkills and Resume for HR\n========================\n\nThis module introduces skills and resume management for employees.\n"}', true, false, false, 'LGPL-3', 270, true, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (98, NULL, NULL, '2026-05-10 01:07:07.223274', 1, 'https://www.odoo.com/app/timesheet', '{"en_US": "Track employee time on tasks"}', 'hr_timesheet', 'Odoo S.A.', '/hr_timesheet/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Task Logs"}', 30, '{"en_US": "\nThis module implements a timesheet system.\n==========================================\n\nEach employee can encode and track their time spent on the different projects.\n\nLots of reporting on time and employee tracking are provided.\n\nIt is completely integrated with the cost accounting module. It allows you to set\nup a management by affair.\n"}', false, false, false, 'LGPL-3', 23, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
