INSERT INTO public.ir_module_module VALUES (110, NULL, NULL, '2026-05-10 01:07:07.223274', 1, 'https://www.odoo.com/app/live-chat', '{"en_US": "Chat with your website visitors"}', 'im_livechat', 'Odoo S.A.', '/im_livechat/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Live Chat"}', 34, '{"en_US": "\nLive Chat Support\n==========================\n\nAllow to drop instant messaging widgets on any web page that will communicate\nwith the current server and dispatch visitors request amongst several live\nchat operators.\nHelp your customers with this chat, and analyse their feedback.\n\n"}', true, false, false, 'LGPL-3', 210, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
