INSERT INTO public.ir_module_module VALUES (270, NULL, NULL, '2026-05-10 01:12:29.662147', 1, 'https://www.odoo.com/documentation/17.0/applications/finance/fiscal_localizations.html', '{"en_US": ""}', 'l10n_pa', 'Cubic ERP', '/account/static/description/l10n.png', 'uninstalled', NULL, '{"en_US": "Panama - Accounting"}', 38, '{"en_US": "\nPanamenian accounting chart and tax localization.\n\nPlan contable panameño e impuestos de acuerdo a disposiciones vigentes\n\nCon la Colaboración de\n- AHMNET CORP http://www.ahmnet.com\n\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (356, NULL, NULL, '2026-05-10 01:07:07.223274', 1, '', '{"en_US": "Advanced views to manage landed cost for subcontracting orders"}', 'mrp_subonctracting_landed_costs', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Landed Costs With Subcontracting order"}', 52, '{"en_US": "\nThis module allows users to more easily identify subcontracting orders when applying landed costs,\nby also displaying the associated picking reference in the search view.\n"}', false, false, false, 'LGPL-3', 100, true, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (323, NULL, NULL, '2026-05-10 01:07:07.223274', 1, '', '{"en_US": "Handle lunch orders of your employees"}', 'lunch', 'Odoo S.A.', '/lunch/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Lunch"}', 48, '{"en_US": "\nThe base module to manage lunch.\n================================\n\nMany companies order sandwiches, pizzas and other, from usual vendors, for their employees to offer them more facilities.\n\nHowever lunches management within the company requires proper administration especially when the number of employees or vendors is important.\n\nThe “Lunch Order” module has been developed to make this management easier but also to offer employees more tools and usability.\n\nIn addition to a full meal and vendor management, this module offers the possibility to display warning and provides quick order selection based on employee’s preferences.\n\nIf you want to save your employees'' time and avoid them to always have coins in their pockets, this module is essential.\n"}', true, false, false, 'LGPL-3', 300, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (327, NULL, NULL, '2026-05-10 01:07:07.223274', 1, '', '{"en_US": "Manage your mailing lists"}', 'mail_group', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Mail Group"}', 43, '{"en_US": "\nManage your mailing lists from Odoo.\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (341, NULL, NULL, '2026-05-10 01:07:07.223274', 1, 'https://www.odoo.com/app/mailing', '{"en_US": "Design gorgeous mails"}', 'mass_mailing_themes', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Mass Mailing Themes"}', 51, '{"en_US": "\nDesign gorgeous mails\n"}', false, false, false, 'LGPL-3', 110, true, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
