INSERT INTO public.ir_module_module VALUES (320, NULL, NULL, '2026-05-10 01:12:29.662147', 1, '', '{"en_US": ""}', 'l10n_zm_account', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Zambia - Accounting"}', 38, '{"en_US": "\nThis is the basic Zambian localization necessary to run Odoo in ZM:\n================================================================================\n    - Chart of Accounts\n    - Taxes\n    - Fiscal Positions\n    - Default Settings\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (342, NULL, NULL, '2026-05-10 01:07:07.223274', 1, 'https://www.odoo.com/app/forum', '{"en_US": ""}', 'membership', 'Odoo S.A.', '/membership/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Members"}', 9, '{"en_US": "\nThis module allows you to manage all operations for managing memberships.\n=========================================================================\n\nIt supports different kind of members:\n--------------------------------------\n    * Free member\n    * Associated member (e.g.: a group subscribes to a membership for all subsidiaries)\n    * Paid members\n    * Special member prices\n\nIt is integrated with sales and accounting to allow you to automatically\ninvoice and send propositions for membership renewal.\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (348, NULL, NULL, '2026-05-10 01:07:07.223274', 1, '', '{"en_US": "Landed Costs on Manufacturing Order"}', 'mrp_landed_costs', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Landed Costs On MO"}', 52, '{"en_US": "\nThis module allows you to easily add extra costs on manufacturing order \nand decide the split of these costs among their stock moves in order to \ntake them into account in your stock valuation.\n"}', false, false, false, 'LGPL-3', 100, true, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
