INSERT INTO public.ir_module_module VALUES (377, NULL, NULL, '2026-05-10 01:07:07.223274', 1, '', '{"en_US": "A French payment provider for online payments all over the world."}', 'payment_sips', 'Odoo S.A.', '/payment_sips/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Payment Provider: Worldline SIPS"}', 57, '{"en_US": ""}', false, false, false, 'LGPL-3', 350, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (392, NULL, NULL, '2026-05-10 01:07:07.223274', 1, '', '{"en_US": "Credit card support for Point Of Sale"}', 'pos_mercury', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Vantiv Payment Services"}', 32, '{"en_US": "\nAllow credit card POS payments\n==============================\n\nThis module allows customers to pay for their orders with credit\ncards. The transactions are processed by Vantiv (developed by Wells\nFargo Bank). A Vantiv merchant account is necessary. It allows the\nfollowing:\n\n* Fast payment by just swiping a credit card while on the payment screen\n* Combining of cash payments and credit card payments\n* Cashback\n* Supported cards: Visa, MasterCard, American Express, Discover\n"}', false, false, false, 'LGPL-3', 6, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (616, NULL, NULL, '2026-05-10 01:07:07.223274', 1, '', '{"en_US": "Publish your members directory"}', 'website_membership', 'Odoo S.A.', '/website_membership/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Online Members Directory"}', 77, '{"en_US": "\nPublish your members/association directory publicly.\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (396, NULL, NULL, '2026-05-10 01:07:07.223274', 1, '', '{"en_US": "Integrate your POS with a PayTM payment terminal"}', 'pos_paytm', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "POS PayTM"}', 32, '{"en_US": "\nAllow Paytm POS payments\n==============================\n\nThis module allows customers to pay for their orders with debit/credit\ncards and UPI. The transactions are processed by Paytm POS. A Paytm merchant account is necessary. It allows the\nfollowing:\n\n* Fast payment by just swiping/scanning a credit/debit card or a QR code while on the payment screen\n* Supported cards: Visa, MasterCard, Rupay, UPI\n"}', false, false, false, 'LGPL-3', 6, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (397, NULL, NULL, '2026-05-10 01:07:07.223274', 1, '', '{"en_US": "Integrate your POS with a Razorpay payment terminal"}', 'pos_razorpay', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "POS Razorpay"}', 32, '{"en_US": "\nAllow Razorpay POS payments\n==============================\n\nThis module allows customers to pay for their orders with debit/credit\ncards and UPI. The transactions are processed by Razorpay POS. A Razorpay merchant account is necessary. It allows the\nfollowing:\n\n* Fast payment by just swiping/scanning a credit/debit card or a QR code while on the payment screen\n* Supported cards: Visa, MasterCard, Rupay, UPI\n"}', false, false, false, 'LGPL-3', 6, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (418, NULL, NULL, '2026-05-10 01:07:07.223274', 1, '', '{"en_US": ""}', 'product_images', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Product Images"}', 59, '{"en_US": "\nAutomatically set product images based on the barcode\n=====================================================\n\nThis module integrates with the Google Custom Search API to set images on products based on the\nbarcode.\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (420, NULL, NULL, '2026-05-10 01:07:07.223274', 1, '', '{"en_US": "Technical module: Matrix Implementation"}', 'product_matrix', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Product Matrix"}', 9, '{"en_US": "\nPlease refer to Sale Matrix or Purchase Matrix for the use of this module.\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (429, NULL, NULL, '2026-05-10 01:07:07.223274', 1, '', '{"en_US": "Schedule timesheet when on time off"}', 'project_timesheet_holidays', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Timesheet when on Time Off"}', 19, '{"en_US": "\nBridge module to integrate leaves in timesheet\n================================================\n\nThis module allows to automatically log timesheets when employees are\non leaves. Project and task can be configured company-wide.\n"}', false, false, false, 'LGPL-3', 100, true, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (432, NULL, NULL, '2026-05-10 01:07:07.223274', 1, '', '{"en_US": ""}', 'purchase_mrp', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Purchase and MRP Management"}', 54, '{"en_US": "\nThis module provides facility to the user to install mrp and purchase modules at a time.\n========================================================================================\n\nIt is basically used when we want to keep track of production orders generated\nfrom purchase order.\n"}', false, false, false, 'LGPL-3', 100, true, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (433, NULL, NULL, '2026-05-10 01:07:07.223274', 1, '', '{"en_US": "Add variants to your purchase orders through an Order Grid Entry."}', 'purchase_product_matrix', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Purchase Matrix"}', 54, '{"en_US": "\nThis module allows to fill Purchase Orders rapidly\nby choosing product variants quantity through a Grid Entry.\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (607, NULL, NULL, '2026-05-10 01:07:07.223274', 1, '', '{"en_US": "Show your company address on Google Maps"}', 'website_google_map', 'Odoo S.A.', '/website_google_map/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Google Maps"}', 77, '{"en_US": "\nShow your company address/partner address on Google Maps. Configure an API key in the Website settings.\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (388, NULL, NULL, '2026-05-10 01:12:29.662147', 1, '', '{"en_US": "Link module between Point of Sale and HR"}', 'pos_hr', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "POS - HR"}', 4, '{"en_US": "\nThis module allows Employees (and not users) to log in to the Point of Sale application using a barcode, a PIN number or both.\nThe actual till still requires one user but an unlimited number of employees can log on to that till and process sales.\n"}', false, false, false, 'LGPL-3', 100, true, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (416, NULL, NULL, '2026-05-10 01:12:29.662147', 1, '', '{"en_US": ""}', 'product_email_template', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Product Email Template"}', 2, '{"en_US": "\nAdd email templates to products to be sent on invoice confirmation\n==================================================================\n\nWith this module, link your products to a template to send complete information and tools to your customer.\nFor instance when invoicing a training, the training agenda and materials will automatically be sent to your customers.''\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (449, NULL, NULL, '2026-05-10 01:07:07.223274', 1, '', '{"en_US": ""}', 'sale_margin', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Margins in Sales Orders"}', 9, '{"en_US": "\nThis module adds the ''Margin'' on sales order.\n=============================================\n\nThis gives the profitability by calculating the difference between the Unit\nPrice and Cost Price.\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (454, NULL, NULL, '2026-05-10 01:07:07.223274', 1, '', '{"en_US": "Add variants to Sales Order through a grid entry."}', 'sale_product_matrix', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Sale Matrix"}', 9, '{"en_US": "\nThis module allows to fill Sales Order rapidly\nby choosing product variants quantity through a Grid Entry.\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (491, NULL, NULL, '2026-05-10 01:07:07.223274', 1, '', '{"en_US": "Landed Costs"}', 'stock_landed_costs', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "WMS Landed Costs"}', 53, '{"en_US": "\nLanded Costs Management\n=======================\nThis module allows you to easily add extra costs on pickings and decide the split of these costs among their stock moves in order to take them into account in your stock valuation.\n"}', false, false, false, 'LGPL-3', 16, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (492, NULL, NULL, '2026-05-10 01:07:07.223274', 1, '', '{"en_US": ""}', 'stock_landed_costs_company', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Landed Costs for company''s branches"}', 53, '{"en_US": "\nThis module is a patch that stores the company_id field on the landed cost model.\nThat way, it is possible to create/use landed costs from a branch.\n"}', false, false, false, 'LGPL-3', 16, true, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (493, NULL, NULL, '2026-05-10 01:07:07.223274', 1, '', '{"en_US": ""}', 'stock_picking_batch', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Warehouse Management: Batch Transfer"}', 53, '{"en_US": "\nThis module adds the batch transfer option in warehouse management\n==================================================================\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (443, NULL, NULL, '2026-05-10 01:12:29.662147', 1, '', '{"en_US": ""}', 'sale_crm', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Opportunity to Quotation"}', 4, '{"en_US": "\nThis module adds a shortcut on one or several opportunity cases in the CRM.\n===========================================================================\n\nThis shortcut allows you to generate a sales order based on the selected case.\nIf different cases are open (a list), it generates one sales order by case.\nThe case is then closed and linked to the generated sales order.\n\nWe suggest you to install this module, if you installed both the sale and the crm\nmodules.\n"}', false, false, false, 'LGPL-3', 100, true, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (495, NULL, NULL, '2026-05-10 01:07:07.223274', 1, 'https://www.odoo.com/app/surveys', '{"en_US": "Send your surveys or share them live."}', 'survey', 'Odoo S.A.', '/survey/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Surveys"}', 63, '{"en_US": "\nCreate beautiful surveys and visualize answers\n==============================================\n\nIt depends on the answers or reviews of some questions by different users. A\nsurvey may have multiple pages. Each page may contain multiple questions and\neach question may have multiple answers. Different users may give different\nanswers of question and according to that survey is done. Partners are also\nsent mails with personal token for the invitation of the survey.\n"}', true, false, false, 'LGPL-3', 220, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (586, NULL, NULL, '2026-05-10 01:07:07.223274', 1, '', '{"en_US": "View livechat sessions for leads"}', 'website_crm_livechat', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Lead Livechat Sessions"}', 77, '{"en_US": "Adds a stat button on lead form view to access their livechat sessions."}', false, false, false, 'LGPL-3', 100, true, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (587, NULL, NULL, '2026-05-10 01:07:07.223274', 1, '', '{"en_US": "Publish your resellers/partners and forward leads to them"}', 'website_crm_partner_assign', 'Odoo S.A.', '/website_crm_partner_assign/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Resellers"}', 77, '{"en_US": "\nThis module allows to publish your resellers/partners on your website and to forward incoming leads/opportunities to them.\n\n\n**Publish a partner**\n\nTo publish a partner, set a *Level* in their contact form (in the Partner Assignment section) and click the *Publish* button.\n\n**Forward leads**\n\nForwarding leads can be done for one or several leads at a time. The action is available in the *Assigned Partner* section of the lead/opportunity form view and in the *Action* menu of the list view.\n\nThe automatic assignment is figured from the weight of partner levels and the geolocalization. Partners get leads that are located around them.\n\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (589, NULL, NULL, '2026-05-10 01:07:07.223274', 1, '', '{"en_US": "Publish your customer references"}', 'website_customer', 'Odoo S.A.', '/website_customer/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Customer References"}', 77, '{"en_US": "\nPublish your customers as business references on your website to attract new potential prospects.\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (591, NULL, NULL, '2026-05-10 01:07:07.223274', 1, '', '{"en_US": "Events, display your booths on your website"}', 'website_event_booth', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Online Event Booths"}', 18, '{"en_US": "\nDisplay your booths on your website for the users to register.\n"}', false, false, false, 'LGPL-3', 100, true, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (592, NULL, NULL, '2026-05-10 01:07:07.223274', 1, '', '{"en_US": "Event Booths, automatically create a sponsor."}', 'website_event_booth_exhibitor', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Booths/Exhibitors Bridge"}', 18, '{"en_US": "\nAutomatically create a sponsor when renting a booth.\n"}', false, false, false, 'LGPL-3', 100, true, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (593, NULL, NULL, '2026-05-10 01:07:07.223274', 1, '', '{"en_US": "Events, sell your booths online"}', 'website_event_booth_sale', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Online Event Booth Sale"}', 18, '{"en_US": "\nUse the e-commerce to sell your event booths.\n"}', false, false, false, 'LGPL-3', 100, true, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (600, NULL, NULL, '2026-05-10 01:07:07.223274', 1, '', '{"en_US": "Sell event tickets online"}', 'website_event_sale', 'Odoo S.A.', '/website_event_sale/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Online Event Ticketing"}', 77, '{"en_US": "\nSell event tickets through eCommerce app.\n"}', false, false, false, 'LGPL-3', 100, true, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (605, NULL, NULL, '2026-05-10 01:07:07.223274', 1, '', '{"en_US": "Add a task suggestion form to your website"}', 'website_form_project', 'Odoo S.A.', '/website_form_project/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Online Task Submission"}', 77, '{"en_US": "\nGenerate tasks in Project app from a form published on your website. This module requires the use of the *Form Builder* module (available in Odoo Enterprise) in order to build the form.\n"}', false, false, false, 'LGPL-3', 100, true, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (606, NULL, NULL, '2026-05-10 01:07:07.223274', 1, 'https://www.odoo.com/app/forum', '{"en_US": "Manage a forum with FAQ and Q&A"}', 'website_forum', 'Odoo S.A.', '/website_forum/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Forum"}', 77, '{"en_US": "\nAsk questions, get answers, no distractions\n"}', false, false, false, 'LGPL-3', 265, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (535, NULL, NULL, '2026-05-10 01:12:29.662147', 1, '', '{"en_US": ""}', 'test_testing_utilities', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Test testing utilities"}', 36, '{"en_US": "Non-trivial testing utilities can require models & all\n\nThis here module is useful to validate that they''re doing what they''re \nsupposed to do\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (610, NULL, NULL, '2026-05-10 01:07:07.223274', 1, '', '{"en_US": "Generate trackable & short URLs"}', 'website_links', 'Odoo S.A.', '/website_links/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Link Tracker"}', 77, '{"en_US": "\nGenerate short links with analytics trackers (UTM) to share your pages through marketing campaigns.\nThose trackers can be used in Google Analytics to track clicks and visitors, or in Odoo reports to analyze the efficiency of those campaigns in terms of lead generation, related revenues (sales orders), recruitment, etc.\n"}', false, false, false, 'LGPL-3', 100, true, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (614, NULL, NULL, '2026-05-10 01:07:07.223274', 1, '', '{"en_US": "Attract visitors to subscribe to mailing lists"}', 'website_mass_mailing', 'Odoo S.A.', '/website_mass_mailing/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Newsletter Subscribe Button"}', 77, '{"en_US": "\nThis module brings a new building block with a mailing list widget to drop on any page of your website.\nOn a simple click, your visitors can subscribe to mailing lists managed in the Email Marketing app.\n"}', false, false, false, 'LGPL-3', 100, true, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (615, NULL, NULL, '2026-05-10 01:07:07.223274', 1, '', '{"en_US": "Attract visitors to subscribe to mailing lists"}', 'website_mass_mailing_sms', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Newsletter Subscribe SMS Template"}', 77, '{"en_US": "\nThis module adds a new template to the Newsletter Block to allow \nyour visitors to subscribe with their phone number.\n"}', false, false, false, 'LGPL-3', 100, true, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (623, NULL, NULL, '2026-05-10 01:07:07.223274', 1, '', '{"en_US": "Allow shoppers to compare products based on their attributes"}', 'website_sale_comparison', 'Odoo S.A.', '/website_sale_comparison/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Product Comparison"}', 77, '{"en_US": "\nThis module adds a comparison tool to your eCommerce shop, so that your shoppers can easily compare products based on their attributes. It will considerably accelerate their purchasing decision.\n\nTo configure product attributes, activate *Attributes & Variants* in the Website settings. This will add a dedicated section in the product form. In the configuration, this module adds a category field to product attributes in order to structure the shopper''s comparison table.\n\nFinally, the module comes with an option to display an attribute summary table in product web pages (available in Customize menu).\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (624, NULL, NULL, '2026-05-10 01:07:07.223274', 1, '', '{"en_US": "Bridge module for Website sale comparison and wishlist"}', 'website_sale_comparison_wishlist', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Product Availability Notifications"}', 77, '{"en_US": "\nIt allows for comparing products from the wishlist\n"}', false, false, false, 'LGPL-3', 100, true, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (625, NULL, NULL, '2026-05-10 01:07:07.223274', 1, '', '{"en_US": "Use coupon, promotion, gift cards and loyalty programs in your eCommerce store"}', 'website_sale_loyalty', 'Odoo S.A.', '/website_sale_loyalty/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Coupons, Promotions, Gift Card and Loyalty for eCommerce"}', 77, '{"en_US": "\nCreate coupon, promotion codes, gift cards and loyalty programs to boost your sales (free products, discounts, etc.). Shoppers can use them in the eCommerce checkout.\n\nCoupon & promotion programs can be edited in the Catalog menu of the Website app.\n"}', false, false, false, 'LGPL-3', 100, true, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (626, NULL, NULL, '2026-05-10 01:07:07.223274', 1, '', '{"en_US": "Let''s choose Point Relais® on your ecommerce"}', 'website_sale_mondialrelay', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "eCommerce Mondialrelay Delivery"}', 77, '{"en_US": "\nThis module allow your customer to choose a Point Relais® and use it as shipping address.\n"}', false, false, false, 'LGPL-3', 100, true, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (627, NULL, NULL, '2026-05-10 01:07:07.223274', 1, '', '{"en_US": "Manage Kit product inventory & availability"}', 'website_sale_mrp', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Kit Availability"}', 77, '{"en_US": "\nManage the inventory of your Kit products and display their availability status in your eCommerce store.\n"}', false, false, false, 'LGPL-3', 100, true, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (631, NULL, NULL, '2026-05-10 01:07:07.223274', 1, '', '{"en_US": "Manage product inventory & availability"}', 'website_sale_stock', 'Odoo S.A.', '/website_sale_stock/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Product Availability"}', 77, '{"en_US": "\nManage the inventory of your products and display their availability status in your eCommerce store.\nIn case of stockout, you can decide to block further sales or to keep selling.\nA default behavior can be selected in the Website settings.\nThen it can be made specific at the product level.\n"}', false, false, false, 'LGPL-3', 100, true, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (632, NULL, NULL, '2026-05-10 01:07:07.223274', 1, '', '{"en_US": "Notify the user when a product is back in stock"}', 'website_sale_stock_wishlist', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Product Availability Notifications"}', 77, '{"en_US": "\nAllow the user to select if he wants to receive email notifications when a product of his wishlist gets back in stock.\n"}', false, false, false, 'LGPL-3', 100, true, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (633, NULL, NULL, '2026-05-10 01:07:07.223274', 1, '', '{"en_US": "Allow shoppers to enlist products"}', 'website_sale_wishlist', 'Odoo S.A.', '/website_sale_wishlist/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Shopper''s Wishlist"}', 77, '{"en_US": "\nAllow shoppers of your eCommerce store to create personalized collections of products they want to buy and save them for future reference.\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (638, NULL, NULL, '2026-05-10 01:07:07.223274', 1, '', '{"en_US": "Twitter scroller snippet in website"}', 'website_twitter', 'Odoo S.A.', '/website_twitter/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Twitter Snippet"}', 77, '{"en_US": "\nThis module adds a Twitter scroller building block to the website builder, so that you can display Twitter feeds on any page of your website.\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (11, NULL, NULL, '2026-05-10 01:12:29.662147', 1, '', '{"en_US": "Manage accounting with fleets"}', 'account_fleet', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Accounting/Fleet bridge"}', 2, '{"en_US": ""}', false, false, false, 'LGPL-3', 100, true, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (23, NULL, NULL, '2026-05-10 01:12:29.662147', 1, '', '{"en_US": ""}', 'attachment_indexation', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Attachments List and Document Indexation"}', 5, '{"en_US": "\nAttachments list and document indexation\n========================================\n* Show attachment on the top of the forms\n* Document Indexation: odt, pdf, xlsx, docx\n\nThe `pdfminer.six` Python library has to be installed in order to index PDF files\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (175, NULL, NULL, '2026-05-10 01:12:29.662147', 1, '', '{"en_US": "Link one refund with multiple invoices"}', 'l10n_es_edi_tbai_multi_refund', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "TicketBAI multi refund"}', 39, '{"en_US": ""}', false, false, false, 'LGPL-3', 100, true, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (317, NULL, NULL, '2026-05-10 01:12:29.662147', 1, 'https://www.odoo.com/documentation/17.0/applications/finance/fiscal_localizations/vietnam.html', '{"en_US": ""}', 'l10n_vn', 'General Solutions', '/account/static/description/l10n.png', 'uninstalled', NULL, '{"en_US": "Vietnam - Accounting"}', 38, '{"en_US": "\nThis is the module to manage the accounting chart, bank information for Vietnam in Odoo.\n========================================================================================\n\n- This module applies to companies based in Vietnamese Accounting Standard (VAS)\n  with Chart of account under Circular No. 200/2014/TT-BTC\n- Add Vietnamese bank information (like name, bic ..) as announced and yearly updated by State Bank\n  of Viet Nam (https://sbv.gov.vn/webcenter/portal/en/home/sbv/paytreasury/bankidno).\n- Add VietQR feature for invoice\n\n**Credits:**\n    - General Solutions.\n    - Trobz\n    - Jean Nguyen - The Bean Family (https://github.com/anhjean/vietqr) for VietQR.\n\n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (319, NULL, NULL, '2026-05-10 01:12:29.662147', 1, 'https://www.odoo.com/documentation/17.0/applications/finance/fiscal_localizations.html', '{"en_US": ""}', 'l10n_za', 'Paradigm Digital (https://www.paradigmdigital.co.za)', '/account/static/description/l10n.png', 'uninstalled', NULL, '{"en_US": "South Africa - Accounting"}', 38, '{"en_US": "\nThis is the latest basic South African localisation necessary to run Odoo in ZA:\n================================================================================\n    - a generic chart of accounts\n    - SARS VAT Ready Structure"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (428, NULL, NULL, '2026-05-10 01:12:29.662147', 1, '', '{"en_US": "Send text messages when project/task stage move"}', 'project_sms', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Project - SMS"}', 4, '{"en_US": "Send text messages when project/task stage move"}', false, false, false, 'LGPL-3', 100, true, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (455, NULL, NULL, '2026-05-10 01:12:29.662147', 1, '', '{"en_US": "Task Generation from Sales Orders"}', 'sale_project', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Sales - Project"}', 4, '{"en_US": "\nAllows to create task from your sales order\n=============================================\nThis module allows to generate a project/task from sales orders.\n"}', false, false, false, 'LGPL-3', 100, true, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (459, NULL, NULL, '2026-05-10 01:12:29.662147', 1, '', '{"en_US": "Interaction between Sales and services apps (project and planning)"}', 'sale_service', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Sales - Service"}', 4, '{"en_US": "\nAllows to display sale information in the SOL services apps\n===========================================================\nAdditional information is displayed in the name of the SOL when it is used in services apps (project and planning). \n"}', false, false, false, 'LGPL-3', 100, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (458, NULL, NULL, '2026-05-10 01:12:33.820447', 1, '', '{"en_US": "SO/PO relation in case of MTO"}', 'sale_purchase_stock', 'Odoo S.A.', '/base/static/description/icon.png', 'installed', '17.0.1.0', '{"en_US": "MTO Sale <-> Purchase"}', 4, '{"en_US": "\nAdd relation information between Sale Orders and Purchase Orders if Make to Order (MTO) is activated on one sold product.\n"}', false, true, false, 'LGPL-3', 100, true, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
