INSERT INTO public.ir_module_module VALUES (520, NULL, NULL, '2026-05-10 01:12:29.662147', 1, '', '{"en_US": "Mail Tests: performances and tests specific to mail"}', 'test_mail', 'Odoo S.A.', '/base/static/description/icon.png', 'uninstalled', NULL, '{"en_US": "Mail Tests"}', 4, '{"en_US": "This module contains tests related to mail. Those are\npresent in a separate module as it contains models used only to perform\ntests independently to functional aspects of other models. "}', false, false, false, 'LGPL-3', 9876, false, false, NULL, NULL, NULL, NULL, '', '', '', 'official', NULL);
INSERT INTO public.ir_module_module VALUES (42, NULL, NULL, '2026-05-10 01:12:29.662147', 1, '', '{"en_US": ""}', 'base_import_module', 'Odoo S.A.', '/base/static/description/icon.png', 'installed', '17.0.1.0', '{"en_US": "Base import module"}', 5, '{"en_US": "\nImport a custom data module\n===========================\n\nThis module allows authorized users to import a custom data module (.xml files and static assests)\nfor customization purpose.\n"}', false, true, false, 'LGPL-3', 100, true, false, NULL, NULL, NULL, NULL, 'Apps/Import Module', '', '* INHERIT Apps (form)
