INSERT INTO public.ir_ui_view VALUES (1, 16, NULL, 1, 1, 'ir.demo.form', 'ir.demo', NULL, 'form', 'base/data/ir_demo_data.xml', 'primary', '{"en_US": "<form>\n                <div class=\"row container\">\n                    <div class=\"col-12 text-center\">\n                      <div class=\"card text-white bg-danger mb-3 w-75 ml64\">\n                        <div class=\"card-header\">\n                                <span class=\"fa fa-2x fa-warning\" t-translation=\"off\">&amp;nbsp;</span>\n                                <span class=\"text-white text-uppercase\">Danger Zone</span>\n                        </div>\n                        <div class=\"card-body bg-transparent text-center\">\n                          <p>Demo data should only be used on test databases!\n                             Once they are loaded, they cannot be removed!</p>\n                          <p>Please confirm that you want to <b>irreversibly</b> make this database a demo database.</p>\n                        </div>\n                      </div>\n                    </div>\n                </div>\n\n                <footer>\n                    <button special=\"cancel\" data-hotkey=\"x\" string=\"Oops, no!\" class=\"btn-primary\"/>\n                    <button name=\"install_demo\" string=\"Yes, I understand the risks\" type=\"object\" class=\"btn-secondary\" data-hotkey=\"q\"/>\n                </footer>\n            </form>"}', '<?xml version="1.0"?>
<form>
                <div class="row container">
                    <div class="col-12 text-center">
                      <div class="card text-white bg-danger mb-3 w-75 ml64">
                        <div class="card-header">
                                <span class="fa fa-2x fa-warning" t-translation="off">&amp;nbsp;</span>
                                <span class="text-white text-uppercase">Danger Zone</span>
                        </div>
                        <div class="card-body bg-transparent text-center">
                          <p>Demo data should only be used on test databases!
                             Once they are loaded, they cannot be removed!</p>
                          <p>Please confirm that you want to <b>irreversibly</b> make this database a demo database.</p>
                        </div>
                      </div>
                    </div>
                </div>

                <footer>
                    <button special="cancel" data-hotkey="x" string="Oops, no!" class="btn-primary"/>
                    <button name="install_demo" string="Yes, I understand the risks" type="object" class="btn-secondary" data-hotkey="q"/>
                </footer>
            </form>
        ', false, true, '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872', NULL);
