INSERT INTO public.ir_ui_view VALUES (9, 16, NULL, 1, 1, 'ir.actions.report', 'ir.actions.report', NULL, 'form', 'base/views/ir_actions_views.xml', 'primary', '{"en_US": "<form string=\"Report\">\n                    <field name=\"binding_model_id\" invisible=\"1\"/>\n                    <sheet>\n                        <div class=\"oe_button_box\" name=\"button_box\">\n                            <button name=\"create_action\" type=\"object\" invisible=\"binding_model_id\" icon=\"fa-plus-square\" help=\"Display an option on related documents to print this report\" class=\"oe_stat_button\">\n                                    <div class=\"o_field_widget o_stat_info\">\n                                        <span class=\"o_stat_text\">Add to the ''Print'' menu</span>\n                                    </div>\n                            </button>\n                            <button name=\"unlink_action\" type=\"object\" invisible=\"not binding_model_id\" icon=\"fa-minus-square\" help=\"Remove the contextual action related to this report\" class=\"oe_stat_button\">\n                                    <div class=\"o_field_widget o_stat_info\">\n                                        <span class=\"o_stat_text\">Remove from the ''Print'' menu</span>\n                                    </div>\n                            </button>\n                            <button name=\"associated_view\" type=\"object\" invisible=\"report_type not in [''qweb-pdf'', ''qweb-html'', ''qweb-text'']\" icon=\"fa-code\" class=\"oe_stat_button\">\n                                    <div class=\"o_field_widget o_stat_info\">\n                                        <span class=\"o_stat_text\">Qweb Views</span>\n                                    </div>\n                            </button>\n                        </div>\n                        <group>\n                            <group>\n                                <field name=\"name\"/>\n                                <field name=\"report_type\"/>\n                                <field name=\"paperformat_id\" invisible=\"report_type != ''qweb-pdf''\"/>\n                            </group>\n                            <group>\n                                <field name=\"model\"/>\n                                <field name=\"report_name\"/>\n                                <field name=\"print_report_name\"/>\n                            </group>\n                        </group>\n                        <notebook>\n                            <page name=\"security\" string=\"Visibility\">\n                                <field name=\"groups_id\"/>\n                            </page>\n                            <page name=\"advanced\" string=\"Advanced Properties\">\n                                <group>\n                                    <field name=\"attachment_use\"/>\n                                    <field name=\"attachment\"/>\n                                </group>\n                            </page>\n                        </notebook>\n                    </sheet>\n                </form>"}', '<?xml version="1.0"?>
<form string="Report">
                    <field name="binding_model_id" invisible="1"/>
                    <sheet>
                        <div class="oe_button_box" name="button_box">
                            <button name="create_action" type="object" invisible="binding_model_id" icon="fa-plus-square" help="Display an option on related documents to print this report" class="oe_stat_button">
                                    <div class="o_field_widget o_stat_info">
                                        <span class="o_stat_text">Add to the ''Print'' menu</span>
                                    </div>
                            </button>
                            <button name="unlink_action" type="object" invisible="not binding_model_id" icon="fa-minus-square" help="Remove the contextual action related to this report" class="oe_stat_button">
                                    <div class="o_field_widget o_stat_info">
                                        <span class="o_stat_text">Remove from the ''Print'' menu</span>
                                    </div>
                            </button>
                            <button name="associated_view" type="object" invisible="report_type not in [''qweb-pdf'', ''qweb-html'', ''qweb-text'']" icon="fa-code" class="oe_stat_button">
                                    <div class="o_field_widget o_stat_info">
                                        <span class="o_stat_text">Qweb Views</span>
                                    </div>
                            </button>
                        </div>
                        <group>
                            <group>
                                <field name="name"/>
                                <field name="report_type"/>
                                <field name="paperformat_id" invisible="report_type != ''qweb-pdf''"/>
                            </group>
                            <group>
                                <field name="model"/>
                                <field name="report_name"/>
                                <field name="print_report_name"/>
                            </group>
                        </group>
                        <notebook>
                            <page name="security" string="Visibility">
                                <field name="groups_id"/>
                            </page>
                            <page name="advanced" string="Advanced Properties">
                                <group>
                                    <field name="attachment_use"/>
                                    <field name="attachment"/>
                                </group>
                            </page>
                        </notebook>
                    </sheet>
                </form>
            ', false, true, '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872', NULL);
INSERT INTO public.ir_ui_view VALUES (10, 16, NULL, 1, 1, 'ir.actions.report.tree', 'ir.actions.report', NULL, 'tree', 'base/views/ir_actions_views.xml', 'primary', '{"en_US": "<tree string=\"Report xml\">\n                    <field name=\"name\"/>\n                    <field name=\"model\"/>\n                    <field name=\"type\"/>\n                    <field name=\"report_name\"/>\n                    <field name=\"report_type\"/>\n                    <field name=\"attachment\"/>\n                </tree>"}', '<?xml version="1.0"?>
