INSERT INTO public.ir_ui_view VALUES (14, 16, NULL, 1, 1, 'ir.actions.windows.form', 'ir.actions.act_window', NULL, 'form', 'base/views/ir_actions_views.xml', 'primary', '{"en_US": "<form string=\"Open a Window\">\n                <sheet>\n                    <group>\n                        <group name=\"main_details\">\n                            <field name=\"name\"/>\n                            <field name=\"xml_id\" string=\"External ID\"/>\n                            <field name=\"res_model\" string=\"Object\"/>\n                        </group>\n                        <group name=\"action_details\">\n                            <field name=\"usage\"/>\n                            <field name=\"type\" readonly=\"1\"/>\n                            <field name=\"target\"/>\n                        </group>\n                    </group>\n                    <notebook>\n                        <page name=\"general_settings\" string=\"General Settings\">\n                            <group>\n                                <group name=\"views\" string=\"Views\">\n                                    <field name=\"view_mode\"/>\n                                    <field name=\"mobile_view_mode\"/>\n                                    <field name=\"view_id\"/>\n                                    <field name=\"search_view_id\"/>\n                                </group>\n                                <group name=\"filters\" string=\"Filters\">\n                                    <field name=\"domain\"/>\n                                    <field name=\"context\"/>\n                                    <field name=\"limit\"/>\n                                    <field name=\"filter\"/>\n                                </group>\n                            </group>\n                            <group name=\"help\" string=\"Help\">\n                                <field colspan=\"2\" name=\"help\" options=\"{''codeview'': true}\" nolabel=\"1\" class=\"oe-bordered-editor\"/>\n                            </group>\n                            <group name=\"views_tree\" string=\"Views\">\n                                <field colspan=\"2\" name=\"view_ids\" nolabel=\"1\">\n                                    <form string=\"Views\">\n                                        <group>\n                                            <field name=\"sequence\"/>\n                                            <field name=\"view_mode\"/>\n                                            <field domain=\"[(''type'', ''='', view_mode)]\" name=\"view_id\"/>\n                                        </group>\n                                    </form>\n                                    <tree string=\"Views\">\n                                        <field name=\"sequence\" widget=\"handle\"/>\n                                        <field name=\"view_mode\"/>\n                                        <field name=\"view_id\"/>\n                                    </tree>\n                                </field>\n                            </group>\n                        </page>\n                        <page string=\"Visibility\" name=\"security\">\n                            <field name=\"groups_id\"/>\n                        </page>\n                    </notebook>\n                </sheet>\n                </form>"}', '<?xml version="1.0"?>
<form string="Open a Window">
                <sheet>
                    <group>
                        <group name="main_details">
                            <field name="name"/>
                            <field name="xml_id" string="External ID"/>
                            <field name="res_model" string="Object"/>
                        </group>
                        <group name="action_details">
                            <field name="usage"/>
                            <field name="type" readonly="1"/>
                            <field name="target"/>
                        </group>
                    </group>
                    <notebook>
                        <page name="general_settings" string="General Settings">
                            <group>
                                <group name="views" string="Views">
                                    <field name="view_mode"/>
                                    <field name="mobile_view_mode"/>
                                    <field name="view_id"/>
                                    <field name="search_view_id"/>
                                </group>
                                <group name="filters" string="Filters">
                                    <field name="domain"/>
                                    <field name="context"/>
                                    <field name="limit"/>
                                    <field name="filter"/>
                                </group>
                            </group>
                            <group name="help" string="Help">
                                <field colspan="2" name="help" options="{''codeview'': true}" nolabel="1" class="oe-bordered-editor"/>
                            </group>
                            <group name="views_tree" string="Views">
                                <field colspan="2" name="view_ids" nolabel="1">
                                    <form string="Views">
                                        <group>
                                            <field name="sequence"/>
                                            <field name="view_mode"/>
                                            <field domain="[(''type'', ''='', view_mode)]" name="view_id"/>
                                        </group>
                                    </form>
                                    <tree string="Views">
                                        <field name="sequence" widget="handle"/>
                                        <field name="view_mode"/>
                                        <field name="view_id"/>
                                    </tree>
                                </field>
                            </group>
                        </page>
                        <page string="Visibility" name="security">
                            <field name="groups_id"/>
                        </page>
                    </notebook>
                </sheet>
                </form>
            ', false, true, '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872', NULL);
INSERT INTO public.ir_ui_view VALUES (15, 16, NULL, 1, 1, 'ir.actions.windows.search', 'ir.actions.act_window', NULL, 'search', 'base/views/ir_actions_views.xml', 'primary', '{"en_US": "<search string=\"Open a Window\">\n                    <field name=\"name\" filter_domain=\"[''|'', (''name'',''ilike'',self), (''res_model'',''ilike'',self)]\" string=\"Action\"/>\n                    <group>\n                        <filter string=\"Binding Model\" name=\"binding_model_id\" context=\"{''group_by'':''binding_model_id''}\"/>\n                        <filter string=\"Target Window\" name=\"target\" context=\"{''group_by'':''target''}\"/>\n                    </group>\n                </search>"}', '<?xml version="1.0"?>
<search string="Open a Window">
                    <field name="name" filter_domain="[''|'', (''name'',''ilike'',self), (''res_model'',''ilike'',self)]" string="Action"/>
                    <group>
                        <filter string="Binding Model" name="binding_model_id" context="{''group_by'':''binding_model_id''}"/>
                        <filter string="Target Window" name="target" context="{''group_by'':''target''}"/>
                    </group>
                </search>
            ', false, true, '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872', NULL);
