INSERT INTO public.ir_ui_view VALUES (17, 16, NULL, 1, 1, 'Server Action', 'ir.actions.server', NULL, 'form', 'base/views/ir_actions_views.xml', 'primary', '{"en_US": "<form string=\"Server Action\">\n                    <header>\n                        <field name=\"binding_model_id\" invisible=\"1\"/>\n                        <button name=\"create_action\" string=\"Create Contextual Action\" type=\"object\" class=\"btn-primary\" invisible=\"binding_model_id\" help=\"Display an option in the ''More'' top-menu in order to run this action.\"/>\n                        <button name=\"unlink_action\" string=\"Remove Contextual Action\" type=\"object\" invisible=\"not binding_model_id\" help=\"Remove ''More'' top-menu contextual action related to this action\"/>\n                        <button name=\"run\" string=\"Run\" type=\"object\" class=\"btn-primary\" invisible=\"model_name != ''ir.actions.server'' or state != ''code''\" help=\"Run this action manually.\"/>\n                    </header>\n                    <sheet>\n                        <h1 class=\"oe_title\">\n                            <field name=\"name\" placeholder=\"e.g. Mass archive contacts\"/>\n                        </h1>\n                        <div class=\"d-flex flex-column\">\n                            <label for=\"state\"/>\n                            <field name=\"state\" widget=\"selection_badge\" options=\"{''size'': ''sm''}\"/>\n                        </div>\n                        <group string=\"Technical Settings\" groups=\"base.group_no_one\">\n                            <group>\n                                <field name=\"model_id\" options=\"{''no_create'': True, ''no_open'': True}\"/>\n                                <field name=\"groups_id\" widget=\"many2many_tags\"/>\n                            </group>\n                        </group>\n                        <separator string=\"Action Details\" groups=\"base.group_no_one\"/>\n                        <div class=\"d-flex flex-row flex-wrap gap-2\" invisible=\"state != ''object_write''\">\n                            <field name=\"evaluation_type\" class=\"oe_inline\"/>\n                            <field name=\"update_path\" widget=\"DynamicModelFieldSelectorChar\" class=\"oe_inline\" options=\"{''model'': ''model_name''}\"/>\n                            <field name=\"update_field_id\" invisible=\"1\"/>\n                            <field name=\"value_field_to_show\" invisible=\"1\"/>\n                            <field name=\"update_related_model_id\" invisible=\"1\"/>\n                            <field name=\"update_field_type\" invisible=\"1\"/>\n                            <span invisible=\"evaluation_type != ''value'' or update_field_type not in [''one2many'', ''many2many'']\">by</span>\n                            <field name=\"update_m2m_operation\" class=\"oe_inline\" invisible=\"evaluation_type != ''value'' or update_field_type not in [''one2many'', ''many2many'']\" required=\"update_field_type in [''one2many'', ''many2many'']\"/>\n                            <span invisible=\"evaluation_type != ''value'' or update_field_type in [''one2many'', ''many2many'']\">to</span>\n                            <field name=\"value\" class=\"oe_inline\" placeholder=\"Set a value...\" invisible=\"update_field_id == False or value_field_to_show != ''value'' or evaluation_type != ''value''\" string=\"Custom Value\"/>\n                            <field name=\"resource_ref\" class=\"oe_inline\" placeholder=\"Choose a value...\" string=\"Custom Value\" options=\"{''model_field'': ''update_related_model_id'', ''no_create'': True, ''no_open'': True}\" invisible=\" update_field_id == False or value_field_to_show != ''resource_ref'' or evaluation_type == ''equation'' or update_m2m_operation == ''clear''\"/>\n                            <field name=\"selection_value\" class=\"oe_inline\" placeholder=\"Choose a value...\" options=\"{''no_create'': True, ''no_open'': True}\" invisible=\" update_field_id == False or value_field_to_show != ''selection_value'' or evaluation_type == ''equation''\"/>\n                            <field name=\"update_boolean_value\" class=\"oe_inline\" invisible=\"evaluation_type != ''value'' or value_field_to_show != ''update_boolean_value''\" required=\"value_field_to_show == ''update_boolean_value''\"/>\n                            <span invisible=\"update_field_id != False or evaluation_type == ''equation''\" class=\"text-muted\">Set a value...</span>\n                            <span invisible=\"evaluation_type != ''equation''\">\n                                to this Python expression:\n                            </span>\n                            <div class=\"w-100 d-flex flex-row gap-3\" invisible=\"evaluation_type != ''equation''\">\n                                <field name=\"value\" class=\"w-50\" widget=\"code\" options=\"{''mode'': ''python''}\" string=\"Expression\"/>\n                                <div class=\"w-50 opacity-75\">\n                                    <span colspan=\"2\" class=\"text-muted\"> Available variables: </span>\n                                        <ul colspan=\"2\" class=\"text-muted\">\n                                            <li><code>env</code>: environment on which the action is triggered</li>\n                                            <li><code>model</code>: model of the record on which the action is triggered; is a void recordset</li>\n                                            <li><code>record</code>: record on which the action is triggered</li>\n                                            <li><code>records</code>: recordset of all records on which the action is triggered in multi mode</li>\n                                            <li><code>time</code>, <code>datetime</code>, <code>dateutil</code>, <code>timezone</code>: useful Python libraries</li>\n                                            <li><code>float_compare()</code>: utility function to compare floats based on a specific precision</li>\n                                        </ul>\n                                </div>\n                            </div>\n                        </div>\n                        <group name=\"action_wrapper\">\n                            <group name=\"action_content\">\n                                <field name=\"model_name\" invisible=\"1\"/>\n                                <field name=\"available_model_ids\" invisible=\"1\"/>\n                                <field name=\"model_id\" options=\"{''no_create'': True, ''no_open'': True}\" groups=\"!base.group_no_one\" invisible=\"context.get(''default_model_id'')\" domain=\"[(''id'', ''in'', available_model_ids)]\"/>\n\n                                <field name=\"type\" invisible=\"1\"/>\n                                <field name=\"crud_model_id\" options=\"{''no_create'': True, ''no_open'': True}\" invisible=\"state != ''object_create''\" required=\"state == ''object_create''\"/>\n                                <field name=\"crud_model_name\" invisible=\"1\"/>\n                                <field name=\"value\" widget=\"char\" string=\"Name\" invisible=\"state != ''object_create''\" help=\"The name of the record to create\" placeholder=\"e.g. Follow-up\"/>\n                                <field name=\"link_field_id\" domain=\"[(''model_id'', ''='', model_id), (''relation'', ''='', crud_model_name),                                     (''ttype'', ''in'', [''many2one'', ''one2many'', ''many2many''])]\" placeholder=\"Select a field to link the record to\" options=\"{''no_create'': True, ''no_open'': True}\" invisible=\"state != ''object_create''\" context=\"{''default_model_id'': model_id, ''default_relation'': crud_model_name}\"/>\n                                    <field name=\"webhook_url\" string=\"URL\" invisible=\"state != ''webhook''\" placeholder=\"e.g. https://maker.ifttt.com/use/...\"/>\n                                    <field name=\"webhook_field_ids\" string=\"Fields\" invisible=\"state != ''webhook''\" widget=\"many2many_tags\" context=\"{''hide_model'': 1}\" domain=\"[(''model_id'', ''='', model_id)]\" placeholder=\"Select fields to include in the request...\"/>\n                                </group>\n                                <group invisible=\"state != ''webhook''\">\n                                    <label for=\"webhook_sample_payload\"/>\n                                    <field name=\"webhook_sample_payload\" string=\"Sample Payload\" nolabel=\"1\" colspan=\"2\" readonly=\"1\" widget=\"code\" options=\"{''mode'': ''js''}\"/>\n                                </group>\n                        </group>\n                        <field name=\"child_ids\" domain=\"[(''model_id'', ''='', model_id)]\" invisible=\"state != ''multi''\"/>\n                        <p class=\"oe_grey\" invisible=\"state != ''multi''\">\n                            If several child actions return an action, only the last one will be executed.\n                            This may happen when having server actions executing code that returns an action, or server actions returning a client action.\n                        </p>\n                        <notebook invisible=\"state != ''code''\">\n                            <page string=\"Code\">\n                                <field name=\"code\" invisible=\"state != ''code''\" widget=\"code\" options=\"{''mode'': ''python''}\" placeholder=\"Enter Python code here. Help about Python expression is available in the help tab of this document.\"/>\n                            </page>\n                            <page string=\"Help\">\n                                <p>The following variables can be used:</p>\n                                <ul>\n                                    <li><code>env</code>: environment on which the action is triggered</li>\n                                    <li><code>model</code>: model of the record on which the action is triggered; is a void recordset</li>\n                                    <li><code>record</code>: record on which the action is triggered; may be be void</li>\n                                    <li><code>records</code>: recordset of all records on which the action is triggered in multi mode; may be void</li>\n                                    <li><code>time</code>, <code>datetime</code>, <code>dateutil</code>, <code>timezone</code>: useful Python libraries</li>\n                                    <li><code>float_compare()</code>: utility function to compare floats based on a specific precision</li>\n                                    <li><code>log(message, level=''info'')</code>: logging function to record debug information in <code>ir.logging</code> table</li>\n                                    <li><code>_logger.info(message)</code>: logger to emit messages in server logs</li>\n                                    <li><code>UserError</code>: exception class for raising user-facing warning messages</li>\n                                    <li><code>Command</code>: x2many commands namespace</li>\n                                    <li>To return an action, assign: <code>action = {...}</code></li>\n                                </ul>\n                                <div>\n                                    <p>Example of Python code:</p>\n<pre style=\"white-space: pre-wrap\">partner_name = record.name + ''_code''\nenv[''res.partner''].create({''name'': partner_name})\n    </pre>\n                                </div>\n                            </page>\n                        </notebook>\n                    </sheet>\n                </form>"}', '<?xml version="1.0"?>
<form string="Server Action">
                    <header>
                        <field name="binding_model_id" invisible="1"/>
                        <button name="create_action" string="Create Contextual Action" type="object" class="btn-primary" invisible="binding_model_id" help="Display an option in the ''More'' top-menu in order to run this action."/>
                        <button name="unlink_action" string="Remove Contextual Action" type="object" invisible="not binding_model_id" help="Remove ''More'' top-menu contextual action related to this action"/>
                        <button name="run" string="Run" type="object" class="btn-primary" invisible="model_name != ''ir.actions.server'' or state != ''code''" help="Run this action manually."/>
                    </header>
                    <sheet>
                        <h1 class="oe_title">
                            <field name="name" placeholder="e.g. Mass archive contacts"/>
                        </h1>
                        <div class="d-flex flex-column">
                            <label for="state"/>
                            <field name="state" widget="selection_badge" options="{''size'': ''sm''}"/>
                        </div>
                        <group string="Technical Settings" groups="base.group_no_one">
                            <group>
                                <field name="model_id" options="{''no_create'': True, ''no_open'': True}"/>
                                <field name="groups_id" widget="many2many_tags"/>
                            </group>
                        </group>
                        <separator string="Action Details" groups="base.group_no_one"/>
                        <div class="d-flex flex-row flex-wrap gap-2" invisible="state != ''object_write''">
                            <field name="evaluation_type" class="oe_inline"/>
                            <field name="update_path" widget="DynamicModelFieldSelectorChar" class="oe_inline" options="{''model'': ''model_name''}"/>
                            <field name="update_field_id" invisible="1"/>
                            <field name="value_field_to_show" invisible="1"/>
                            <field name="update_related_model_id" invisible="1"/>
                            <field name="update_field_type" invisible="1"/>
                            <span invisible="evaluation_type != ''value'' or update_field_type not in [''one2many'', ''many2many'']">by</span>
                            <field name="update_m2m_operation" class="oe_inline" invisible="evaluation_type != ''value'' or update_field_type not in [''one2many'', ''many2many'']" required="update_field_type in [''one2many'', ''many2many'']"/>
                            <span invisible="evaluation_type != ''value'' or update_field_type in [''one2many'', ''many2many'']">to</span>
                            <field name="value" class="oe_inline" placeholder="Set a value..." invisible="update_field_id == False or value_field_to_show != ''value'' or evaluation_type != ''value''" string="Custom Value"/>
                            <field name="resource_ref" class="oe_inline" placeholder="Choose a value..." string="Custom Value" options="{''model_field'': ''update_related_model_id'', ''no_create'': True, ''no_open'': True}" invisible=" update_field_id == False or value_field_to_show != ''resource_ref'' or evaluation_type == ''equation'' or update_m2m_operation == ''clear''"/>
                            <field name="selection_value" class="oe_inline" placeholder="Choose a value..." options="{''no_create'': True, ''no_open'': True}" invisible=" update_field_id == False or value_field_to_show != ''selection_value'' or evaluation_type == ''equation''"/>
                            <field name="update_boolean_value" class="oe_inline" invisible="evaluation_type != ''value'' or value_field_to_show != ''update_boolean_value''" required="value_field_to_show == ''update_boolean_value''"/>
                            <span invisible="update_field_id != False or evaluation_type == ''equation''" class="text-muted">Set a value...</span>
                            <span invisible="evaluation_type != ''equation''">
                                to this Python expression:
                            </span>
                            <div class="w-100 d-flex flex-row gap-3" invisible="evaluation_type != ''equation''">
                                <field name="value" class="w-50" widget="code" options="{''mode'': ''python''}" string="Expression"/>
                                <div class="w-50 opacity-75">
                                    <span colspan="2" class="text-muted"> Available variables: </span>
                                        <ul colspan="2" class="text-muted">
                                            <li><code>env</code>: environment on which the action is triggered</li>
                                            <li><code>model</code>: model of the record on which the action is triggered; is a void recordset</li>
                                            <li><code>record</code>: record on which the action is triggered</li>
                                            <li><code>records</code>: recordset of all records on which the action is triggered in multi mode</li>
                                            <li><code>time</code>, <code>datetime</code>, <code>dateutil</code>, <code>timezone</code>: useful Python libraries</li>
                                            <li><code>float_compare()</code>: utility function to compare floats based on a specific precision</li>
                                        </ul>
                                </div>
                            </div>
                        </div>
                        <group name="action_wrapper">
                            <group name="action_content">
                                <field name="model_name" invisible="1"/>
                                <field name="available_model_ids" invisible="1"/>
                                <field name="model_id" options="{''no_create'': True, ''no_open'': True}" groups="!base.group_no_one" invisible="context.get(''default_model_id'')" domain="[(''id'', ''in'', available_model_ids)]"/>

                                <field name="type" invisible="1"/>
                                <field name="crud_model_id" options="{''no_create'': True, ''no_open'': True}" invisible="state != ''object_create''" required="state == ''object_create''"/>
                                <field name="crud_model_name" invisible="1"/>
                                <field name="value" widget="char" string="Name" invisible="state != ''object_create''" help="The name of the record to create" placeholder="e.g. Follow-up"/>
                                <field name="link_field_id" domain="[(''model_id'', ''='', model_id), (''relation'', ''='', crud_model_name),                                     (''ttype'', ''in'', [''many2one'', ''one2many'', ''many2many''])]" placeholder="Select a field to link the record to" options="{''no_create'': True, ''no_open'': True}" invisible="state != ''object_create''" context="{''default_model_id'': model_id, ''default_relation'': crud_model_name}"/>
                                    <field name="webhook_url" string="URL" invisible="state != ''webhook''" placeholder="e.g. https://maker.ifttt.com/use/..."/>
                                    <field name="webhook_field_ids" string="Fields" invisible="state != ''webhook''" widget="many2many_tags" context="{''hide_model'': 1}" domain="[(''model_id'', ''='', model_id)]" placeholder="Select fields to include in the request..."/>
                                </group>
                                <group invisible="state != ''webhook''">
                                    <label for="webhook_sample_payload"/>
                                    <field name="webhook_sample_payload" string="Sample Payload" nolabel="1" colspan="2" readonly="1" widget="code" options="{''mode'': ''js''}"/>
                                </group>
                        </group>
                        <field name="child_ids" domain="[(''model_id'', ''='', model_id)]" invisible="state != ''multi''"/>
                        <p class="oe_grey" invisible="state != ''multi''">
                            If several child actions return an action, only the last one will be executed.
                            This may happen when having server actions executing code that returns an action, or server actions returning a client action.
                        </p>
                        <notebook invisible="state != ''code''">
                            <page string="Code">
                                <field name="code" invisible="state != ''code''" widget="code" options="{''mode'': ''python''}" placeholder="Enter Python code here. Help about Python expression is available in the help tab of this document."/>
                            </page>
                            <page string="Help">
                                <p>The following variables can be used:</p>
                                <ul>
                                    <li><code>env</code>: environment on which the action is triggered</li>
                                    <li><code>model</code>: model of the record on which the action is triggered; is a void recordset</li>
                                    <li><code>record</code>: record on which the action is triggered; may be be void</li>
                                    <li><code>records</code>: recordset of all records on which the action is triggered in multi mode; may be void</li>
                                    <li><code>time</code>, <code>datetime</code>, <code>dateutil</code>, <code>timezone</code>: useful Python libraries</li>
                                    <li><code>float_compare()</code>: utility function to compare floats based on a specific precision</li>
                                    <li><code>log(message, level=''info'')</code>: logging function to record debug information in <code>ir.logging</code> table</li>
                                    <li><code>_logger.info(message)</code>: logger to emit messages in server logs</li>
                                    <li><code>UserError</code>: exception class for raising user-facing warning messages</li>
                                    <li><code>Command</code>: x2many commands namespace</li>
                                    <li>To return an action, assign: <code>action = {...}</code></li>
                                </ul>
                                <div>
                                    <p>Example of Python code:</p>
<pre style="white-space: pre-wrap">partner_name = record.name + ''_code''
env[''res.partner''].create({''name'': partner_name})
    </pre>
                                </div>
                            </page>
                        </notebook>
                    </sheet>
                </form>
            ', false, true, '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872', NULL);
INSERT INTO public.ir_ui_view VALUES (18, 16, NULL, 1, 1, 'Server Actions', 'ir.actions.server', NULL, 'tree', 'base/views/ir_actions_views.xml', 'primary', '{"en_US": "<tree string=\"Server Actions\">\n                    <field name=\"name\"/>\n                    <field name=\"state\"/>\n                    <field name=\"model_id\"/>\n                    <field name=\"usage\"/>\n                </tree>"}', '<?xml version="1.0"?>
<tree string="Server Actions">
                    <field name="name"/>
                    <field name="state"/>
                    <field name="model_id"/>
                    <field name="usage"/>
                </tree>
            ', false, true, '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872', NULL);
INSERT INTO public.ir_ui_view VALUES (19, 16, NULL, 1, 1, 'ir.actions.server.search', 'ir.actions.server', NULL, 'search', 'base/views/ir_actions_views.xml', 'primary', '{"en_US": "<search string=\"Server Actions\">\n                    <field name=\"name\" string=\"Server Action\"/>\n                    <field name=\"model_id\"/>\n                    <field name=\"state\"/>\n                    <group expand=\"0\" string=\"Group By\" colspan=\"4\" col=\"4\">\n                        <filter string=\"Action Type\" name=\"action_type\" domain=\"[]\" context=\"{''group_by'':''state''}\"/>\n                        <filter string=\"Model\" name=\"model\" domain=\"[]\" context=\"{''group_by'':''model_id''}\"/>\n                        <filter string=\"Usage\" name=\"usage\" domain=\"[]\" context=\"{''group_by'':''usage''}\"/>\n                    </group>\n                </search>"}', '<?xml version="1.0"?>
<search string="Server Actions">
                    <field name="name" string="Server Action"/>
                    <field name="model_id"/>
                    <field name="state"/>
                    <group expand="0" string="Group By" colspan="4" col="4">
                        <filter string="Action Type" name="action_type" domain="[]" context="{''group_by'':''state''}"/>
