INSERT INTO public.ir_ui_view VALUES (20, 16, NULL, 1, 1, 'Config Wizard Steps', 'ir.actions.todo', NULL, 'tree', 'base/views/ir_actions_views.xml', 'primary', '{"en_US": "<tree string=\"Config Wizard Steps\">\n                    <field name=\"sequence\" widget=\"handle\"/>\n                    <field name=\"action_id\"/>\n                    <field name=\"state\" readonly=\"1\"/>\n                    <button name=\"action_launch\" invisible=\"state != ''open''\" string=\"Launch\" type=\"object\" icon=\"fa-cogs\" help=\"Launch Configuration Wizard\"/>\n                    <button name=\"action_open\" invisible=\"state != ''done''\" string=\"Todo\" type=\"object\" help=\"Set as Todo\" icon=\"fa-exchange\"/>\n                </tree>"}', '<?xml version="1.0"?>
