INSERT INTO public.ir_ui_view VALUES (21, 16, NULL, 1, 1, 'Config Wizard Steps', 'ir.actions.todo', NULL, 'form', 'base/views/ir_actions_views.xml', 'primary', '{"en_US": "<form string=\"Config Wizard Steps\">\n                  <header>\n                        <button name=\"action_launch\" invisible=\"state != ''open''\" string=\"Launch\" type=\"object\" icon=\"fa-cogs\" class=\"oe_highlight\" help=\"Launch Configuration Wizard\"/>\n                        <button name=\"action_open\" invisible=\"state != ''done''\" string=\"Set as Todo\" type=\"object\" icon=\"fa-exchange\" class=\"oe_highlight\"/>\n                        <field name=\"state\" widget=\"statusbar\" statusbar_visible=\"open,done\" nolabel=\"1\" readonly=\"1\"/>\n                  </header>\n                  <sheet>\n                    <group col=\"4\">\n                        <field name=\"action_id\"/>\n                        <field name=\"sequence\"/>\n                    </group>\n                  </sheet>\n                </form>"}', '<?xml version="1.0"?>
