INSERT INTO public.ir_ui_view VALUES (29, 16, 17, 1, 1, 'ir.cron.view.form', 'ir.cron', NULL, 'form', 'base/views/ir_cron_views.xml', 'primary', '{"en_US": "<data><xpath expr=\"//button[@name=''create_action'']\" position=\"replace\">\n                    <button name=\"method_direct_trigger\" type=\"object\" string=\"Run Manually\" class=\"oe_highlight\" invisible=\"state != ''code''\"/>\n                </xpath>\n                <xpath expr=\"//button[@name=''unlink_action'']\" position=\"replace\">\n                </xpath>\n                <xpath expr=\"//button[@name=''run'']\" position=\"replace\">\n                </xpath>\n                <xpath expr=\"//group[@name=''action_content'']\" position=\"inside\">\n                    <field name=\"user_id\"/>\n                    <label for=\"interval_number\" string=\"Execute Every\"/>\n                    <div>\n                        <field name=\"interval_number\" class=\"oe_inline\"/>\n                        <field name=\"interval_type\" class=\"oe_inline\"/>\n                    </div>\n                    <field name=\"active\" widget=\"boolean_toggle\"/>\n                    <field name=\"nextcall\"/>\n                    <field name=\"numbercall\"/>\n                    <field name=\"priority\"/>\n                    <field name=\"doall\"/>\n                </xpath>\n                <field name=\"state\" position=\"attributes\">\n                    <attribute name=\"invisible\">1</attribute>\n                </field>\n            </data>"}', '<?xml version="1.0"?>
<data><xpath expr="//button[@name=''create_action'']" position="replace">
                    <button name="method_direct_trigger" type="object" string="Run Manually" class="oe_highlight" invisible="state != ''code''"/>
                </xpath>
                <xpath expr="//button[@name=''unlink_action'']" position="replace">
                </xpath>
                <xpath expr="//button[@name=''run'']" position="replace">
                </xpath>
                <xpath expr="//group[@name=''action_content'']" position="inside">
                    <field name="user_id"/>
                    <label for="interval_number" string="Execute Every"/>
                    <div>
                        <field name="interval_number" class="oe_inline"/>
                        <field name="interval_type" class="oe_inline"/>
                    </div>
                    <field name="active" widget="boolean_toggle"/>
                    <field name="nextcall"/>
                    <field name="numbercall"/>
                    <field name="priority"/>
                    <field name="doall"/>
                </xpath>
                <field name="state" position="attributes">
                    <attribute name="invisible">1</attribute>
                </field>
            </data>', false, true, '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872', NULL);
INSERT INTO public.ir_ui_view VALUES (30, 16, NULL, 1, 1, 'ir.cron tree', 'ir.cron', NULL, 'tree', 'base/views/ir_cron_views.xml', 'primary', '{"en_US": "<tree string=\"Scheduled Actions\" decoration-muted=\"(not active)\">\n                    <field name=\"priority\"/>\n                    <field name=\"name\"/>\n                    <field name=\"model_id\"/>\n                    <field name=\"nextcall\"/>\n                    <field name=\"interval_number\"/>\n                    <field name=\"interval_type\"/>\n                    <field name=\"numbercall\"/>\n                    <field name=\"user_id\" column_invisible=\"True\"/>\n                    <field name=\"active\"/>\n                </tree>"}', '<?xml version="1.0"?>
