INSERT INTO public.ir_ui_view VALUES (32, 16, NULL, 1, 1, 'ir.cron search', 'ir.cron', NULL, 'search', 'base/views/ir_cron_views.xml', 'primary', '{"en_US": "<search string=\"Scheduled Actions\">\n                    <field name=\"name\" string=\"Scheduled Action\"/>\n                    <field name=\"user_id\"/>\n                    <field name=\"model_id\"/>\n                    <field name=\"nextcall\"/>\n                    <field name=\"active\"/>\n                    <separator/>\n                    <filter string=\"All\" name=\"all\" domain=\"[''|'', (''active'', ''='', False), (''active'', ''='', True)]\"/>\n                    <separator/>\n                    <filter string=\"Archived\" name=\"inactive\" domain=\"[(''active'', ''='', False)]\"/>\n                    <group expand=\"0\" string=\"Group By\">\n                        <filter string=\"User\" name=\"user\" domain=\"[]\" context=\"{''group_by'': ''user_id''}\"/>\n                        <filter string=\"Execution\" name=\"execution\" domain=\"[]\" context=\"{''group_by'': ''nextcall''}\"/>\n                        <filter string=\"Model\" name=\"groupby_model_id\" domain=\"[]\" context=\"{''group_by'': ''model_id''}\"/>\n                    </group>\n                </search>"}', '<?xml version="1.0"?>
<search string="Scheduled Actions">
