INSERT INTO public.ir_ui_view VALUES (36, 16, NULL, 1, 1, 'ir.filters form', 'ir.filters', NULL, 'form', 'base/views/ir_filters_views.xml', 'primary', '{"en_US": "<form string=\"Filters\">\n                  <sheet>\n                    <group col=\"4\">\n                        <field name=\"name\"/>\n                        <field name=\"user_id\" string=\"Available for User\"/>\n                        <field name=\"model_id\"/>\n                        <field name=\"is_default\"/>\n                        <field name=\"action_id\"/>\n                        <field name=\"active\" widget=\"boolean_toggle\"/>\n                    </group>\n                    <group>\n                        <field name=\"domain\" widget=\"domain\" options=\"{''model'': ''model_id''}\"/>\n                        <field name=\"context\"/>\n                        <field name=\"sort\"/>\n                    </group>\n                   </sheet>\n                </form>"}', '<?xml version="1.0"?>
