INSERT INTO public.ir_ui_view VALUES (37, 16, NULL, 1, 1, 'ir.filters tree', 'ir.filters', NULL, 'tree', 'base/views/ir_filters_views.xml', 'primary', '{"en_US": "<tree string=\"Filters\">\n                    <field name=\"name\"/>\n                    <field name=\"model_id\"/>\n                    <field name=\"user_id\"/>\n                    <field name=\"is_default\"/>\n                    <field name=\"action_id\"/>\n                    <field name=\"domain\" groups=\"base.group_no_one\"/>\n                    <field name=\"context\" groups=\"base.group_no_one\"/>\n                    <field name=\"sort\" groups=\"base.group_no_one\"/>\n                </tree>"}', '<?xml version="1.0"?>
