INSERT INTO public.ir_ui_view VALUES (38, 16, NULL, 1, 1, 'ir.filters search', 'ir.filters', NULL, 'search', 'base/views/ir_filters_views.xml', 'primary', '{"en_US": "<search string=\"Filters\">\n                    <field name=\"name\" string=\"Filter Name\"/>\n                    <filter string=\"User\" domain=\"[(''user_id'',''!='',False)]\" name=\"user\" help=\"Filters visible only for one user\"/>\n                    <filter string=\"Shared\" domain=\"[(''user_id'',''='',False)]\" name=\"shared\" help=\"Filters shared with all users\"/>\n                    <filter string=\"My filters\" domain=\"[(''user_id'',''='',uid)]\" name=\"my_filters\" help=\"Filters created by myself\"/>\n                    <separator/>\n                    <filter string=\"Archived\" name=\"inactive\" domain=\"[(''active'', ''='', False)]\"/>\n                    <group expand=\"0\" string=\"Group By\">\n                        <filter string=\"User\" name=\"user\" domain=\"[]\" context=\"{''group_by'':''user_id''}\"/>\n                        <filter string=\"Model\" name=\"model\" domain=\"[]\" context=\"{''group_by'':''model_id''}\"/>\n                    </group>\n                    <field name=\"model_id\"/>\n                    <field name=\"user_id\"/>\n                </search>"}', '<?xml version="1.0"?>
<search string="Filters">
                    <field name="name" string="Filter Name"/>
                    <filter string="User" domain="[(''user_id'',''!='',False)]" name="user" help="Filters visible only for one user"/>
                    <filter string="Shared" domain="[(''user_id'',''='',False)]" name="shared" help="Filters shared with all users"/>
                    <filter string="My filters" domain="[(''user_id'',''='',uid)]" name="my_filters" help="Filters created by myself"/>
                    <separator/>
                    <filter string="Archived" name="inactive" domain="[(''active'', ''='', False)]"/>
                    <group expand="0" string="Group By">
                        <filter string="User" name="user" domain="[]" context="{''group_by'':''user_id''}"/>
                        <filter string="Model" name="model" domain="[]" context="{''group_by'':''model_id''}"/>
                    </group>
                    <field name="model_id"/>
                    <field name="user_id"/>
                </search>
            ', false, true, '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872', NULL);
INSERT INTO public.ir_ui_view VALUES (39, 16, NULL, 1, 1, 'ir.mail_server form', 'ir.mail_server', NULL, 'form', 'base/views/ir_mail_server_views.xml', 'primary', '{"en_US": "<form string=\"Outgoing Mail Servers\">\n                    <header>\n                        <button string=\"Test Connection\" type=\"object\" name=\"test_smtp_connection\" class=\"btn-primary\"/>\n                    </header>\n                    <sheet>\n                        <widget name=\"web_ribbon\" title=\"Archived\" bg_color=\"text-bg-danger\" invisible=\"active\"/>\n                        <group>\n                            <group>\n                                <field name=\"name\" placeholder=\"e.g. My Outgoing Server\"/>\n                                <field name=\"from_filter\" placeholder=\"e.g. email@domain.com, domain.com\"/>\n                            </group>\n                            <group>\n                                <field name=\"sequence\"/>\n                                <field name=\"active\" invisible=\"1\"/>\n                            </group>\n                        </group>\n                        <group>\n                            <group>\n                                <field name=\"smtp_authentication\" widget=\"radio\"/>\n                            </group>\n                            <group>\n                                <div class=\"text-muted fst-italic\" role=\"alert\" colspan=\"2\" invisible=\"not smtp_authentication_info\">\n                                    <field name=\"smtp_authentication_info\"/>\n                                </div>\n                            </group>\n                        </group>\n                        <notebook colspan=\"4\" invisible=\"smtp_authentication == ''cli''\">\n                            <page name=\"connection\" string=\"Connection\">\n                                <group>\n                                    <group>\n                                        <field name=\"smtp_encryption\" widget=\"radio\"/>\n                                        <field name=\"smtp_debug\" groups=\"base.group_no_one\"/>\n                                        <field name=\"smtp_host\" required=\"smtp_authentication != ''cli''\"/>\n                                        <field name=\"smtp_port\" options=\"{''format'': false}\" required=\"smtp_authentication != ''cli''\"/>\n                                    </group>\n                                    <group>\n                                        <field name=\"smtp_user\" invisible=\"smtp_authentication == ''certificate''\" force_save=\"1\"/>\n                                        <field name=\"smtp_pass\" invisible=\"smtp_authentication != ''login''\" password=\"True\" force_save=\"1\"/>\n                                        <field name=\"smtp_ssl_certificate\" invisible=\"smtp_authentication != ''certificate''\" force_save=\"1\"/>\n                                        <field name=\"smtp_ssl_private_key\" invisible=\"smtp_authentication != ''certificate''\" force_save=\"1\"/>\n                                    </group>\n                                </group>\n                            </page>\n                        </notebook>\n                    </sheet>\n                </form>"}', '<?xml version="1.0"?>
<form string="Outgoing Mail Servers">
                    <header>
                        <button string="Test Connection" type="object" name="test_smtp_connection" class="btn-primary"/>
                    </header>
                    <sheet>
                        <widget name="web_ribbon" title="Archived" bg_color="text-bg-danger" invisible="active"/>
                        <group>
                            <group>
                                <field name="name" placeholder="e.g. My Outgoing Server"/>
                                <field name="from_filter" placeholder="e.g. email@domain.com, domain.com"/>
                            </group>
                            <group>
                                <field name="sequence"/>
                                <field name="active" invisible="1"/>
                            </group>
                        </group>
                        <group>
                            <group>
                                <field name="smtp_authentication" widget="radio"/>
                            </group>
                            <group>
                                <div class="text-muted fst-italic" role="alert" colspan="2" invisible="not smtp_authentication_info">
                                    <field name="smtp_authentication_info"/>
                                </div>
                            </group>
                        </group>
                        <notebook colspan="4" invisible="smtp_authentication == ''cli''">
                            <page name="connection" string="Connection">
                                <group>
                                    <group>
                                        <field name="smtp_encryption" widget="radio"/>
                                        <field name="smtp_debug" groups="base.group_no_one"/>
                                        <field name="smtp_host" required="smtp_authentication != ''cli''"/>
                                        <field name="smtp_port" options="{''format'': false}" required="smtp_authentication != ''cli''"/>
                                    </group>
                                    <group>
                                        <field name="smtp_user" invisible="smtp_authentication == ''certificate''" force_save="1"/>
                                        <field name="smtp_pass" invisible="smtp_authentication != ''login''" password="True" force_save="1"/>
                                        <field name="smtp_ssl_certificate" invisible="smtp_authentication != ''certificate''" force_save="1"/>
                                        <field name="smtp_ssl_private_key" invisible="smtp_authentication != ''certificate''" force_save="1"/>
                                    </group>
                                </group>
                            </page>
                        </notebook>
                    </sheet>
                </form>
            ', false, true, '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872', NULL);
INSERT INTO public.ir_ui_view VALUES (40, 16, NULL, 1, 1, 'ir.mail_server tree', 'ir.mail_server', NULL, 'tree', 'base/views/ir_mail_server_views.xml', 'primary', '{"en_US": "<tree string=\"Outgoing Mail Servers\">\n                    <field name=\"sequence\" widget=\"handle\"/>\n                    <field name=\"name\"/>\n                    <field name=\"smtp_host\"/>\n                    <field name=\"smtp_user\"/>\n                    <field name=\"smtp_encryption\"/>\n                    <field name=\"from_filter\" optional=\"hide\"/>\n                </tree>"}', '<?xml version="1.0"?>
<tree string="Outgoing Mail Servers">
                    <field name="sequence" widget="handle"/>
                    <field name="name"/>
                    <field name="smtp_host"/>
                    <field name="smtp_user"/>
                    <field name="smtp_encryption"/>
                    <field name="from_filter" optional="hide"/>
                </tree>
            ', false, true, '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872', NULL);
INSERT INTO public.ir_ui_view VALUES (41, 16, NULL, 1, 1, 'ir.mail_server search', 'ir.mail_server', NULL, 'search', 'base/views/ir_mail_server_views.xml', 'primary', '{"en_US": "<search string=\"Outgoing Mail Servers\">\n                    <field name=\"name\" filter_domain=\"[''|'', ''|'',                                         (''name'', ''ilike'', self),                                         (''smtp_host'', ''ilike'', self),                                         (''smtp_user'', ''ilike'', self)]\" string=\"Outgoing Mail Server\"/>\n                    <field name=\"smtp_encryption\"/>\n                    <field name=\"from_filter\"/>\n                    <separator/>\n                    <filter string=\"Archived\" name=\"inactive\" domain=\"[(''active'', ''='', False)]\"/>\n                </search>"}', '<?xml version="1.0"?>
<search string="Outgoing Mail Servers">
                    <field name="name" filter_domain="[''|'', ''|'',                                         (''name'', ''ilike'', self),                                         (''smtp_host'', ''ilike'', self),                                         (''smtp_user'', ''ilike'', self)]" string="Outgoing Mail Server"/>
                    <field name="smtp_encryption"/>
                    <field name="from_filter"/>
                    <separator/>
                    <filter string="Archived" name="inactive" domain="[(''active'', ''='', False)]"/>
                </search>
            ', false, true, '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872', NULL);
INSERT INTO public.ir_ui_view VALUES (42, 16, NULL, 1, 1, 'Create Menu', 'wizard.ir.model.menu.create', NULL, 'form', 'base/views/ir_model_views.xml', 'primary', '{"en_US": "<form string=\"Create Menu\">\n                    <group>\n                        <field name=\"name\"/>\n                        <field name=\"menu_id\"/>\n                    </group>\n                    <footer>\n                        <button name=\"menu_create\" string=\"Create Menu\" type=\"object\" class=\"btn-primary\" data-hotkey=\"q\"/>\n                        <button string=\"Cancel\" class=\"btn-secondary\" special=\"cancel\" data-hotkey=\"x\"/>\n                    </footer>\n                </form>"}', '<?xml version="1.0"?>
<form string="Create Menu">
                    <group>
                        <field name="name"/>
                        <field name="menu_id"/>
                    </group>
                    <footer>
                        <button name="menu_create" string="Create Menu" type="object" class="btn-primary" data-hotkey="q"/>
                        <button string="Cancel" class="btn-secondary" special="cancel" data-hotkey="x"/>
                    </footer>
                </form>
            ', false, true, '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872', NULL);
INSERT INTO public.ir_ui_view VALUES (43, 16, NULL, 1, 1, 'ir.model form', 'ir.model', NULL, 'form', 'base/views/ir_model_views.xml', 'primary', '{"en_US": "<form string=\"Model Description\">\n                  <header><!-- used for override --></header>\n                  <sheet>\n                    <group>\n                        <group>\n                            <field name=\"id\" invisible=\"1\"/>\n                            <field name=\"name\"/>\n                            <field name=\"model\" readonly=\"id\"/>\n                            <field name=\"order\"/>\n                            <field name=\"transient\" readonly=\"id\" groups=\"base.group_no_one\"/>\n                        </group>\n                        <group>\n                            <field name=\"state\" readonly=\"1\" groups=\"base.group_no_one\"/>\n                            <field name=\"modules\" groups=\"base.group_no_one\"/>\n                        </group>\n                    </group>\n                    <notebook>\n                        <page string=\"Fields\" name=\"fields\">\n                            <field name=\"field_id\">\n                                <tree string=\"Fields Description\">\n                                    <field name=\"name\"/>\n                                    <field name=\"field_description\"/>\n                                    <field name=\"ttype\"/>\n                                    <field name=\"required\"/>\n                                    <field name=\"readonly\"/>\n                                    <field name=\"index\" groups=\"base.group_no_one\"/>\n                                    <field name=\"state\" groups=\"base.group_no_one\"/>\n                                </tree>\n                                <form string=\"Fields Description\">\n                                    <group>\n                                        <group>\n                                            <field name=\"name\"/>\n                                            <field name=\"field_description\"/>\n                                        </group>\n                                        <group>\n                                            <field name=\"ttype\"/>\n                                            <field name=\"help\"/>\n                                        </group>\n                                    </group>\n                                    <notebook>\n                                        <page name=\"base\" string=\"Properties\">\n                                            <group string=\"Base Properties\">\n                                                <group>\n                                                    <field name=\"required\"/>\n                                                    <field name=\"readonly\"/>\n                                                    <field name=\"store\" groups=\"base.group_no_one\"/>\n                                                    <field name=\"index\" groups=\"base.group_no_one\"/>\n                                                    <field name=\"copied\" groups=\"base.group_no_one\"/>\n                                                </group>\n                                                <group>\n                                                    <field name=\"translate\" invisible=\"ttype not in [''char'', ''text'', ''html'']\" readonly=\"ttype not in [''char'', ''text'', ''html'']\"/>\n                                                    <field name=\"size\" groups=\"base.group_no_one\" invisible=\"ttype not in [''char'', ''reference'']\" readonly=\"ttype not in [''char'', ''reference'']\"/>\n                                                    <field name=\"relation\" invisible=\"ttype not in [''many2one'', ''one2many'', ''many2many'']\" readonly=\"ttype not in [''many2one'', ''one2many'', ''many2many'']\" required=\"ttype in [''many2one'', ''one2many'', ''many2many'']\"/>\n                                                    <field name=\"on_delete\" groups=\"base.group_no_one\" invisible=\"ttype != ''many2one''\" readonly=\"ttype != ''many2one''\"/>\n                                                    <field name=\"relation_field\" invisible=\"ttype != ''one2many''\" readonly=\"ttype != ''one2many''\" required=\"ttype == ''one2many''\"/>\n                                                    <field name=\"relation_table\" groups=\"base.group_no_one\" invisible=\"ttype != ''many2many'' or state != ''manual''\" readonly=\"ttype != ''many2many'' or state != ''manual''\"/>\n                                                    <field name=\"column1\" groups=\"base.group_no_one\" invisible=\"ttype != ''many2many'' or state != ''manual''\" readonly=\"ttype != ''many2many'' or state != ''manual''\"/>\n                                                    <field name=\"column2\" groups=\"base.group_no_one\" invisible=\"ttype != ''many2many'' or state != ''manual''\" readonly=\"ttype != ''many2many'' or state != ''manual''\"/>\n                                                    <field name=\"domain\" groups=\"base.group_no_one\" invisible=\"ttype not in [''many2one'', ''one2many'', ''many2many'']\" readonly=\"ttype not in [''many2one'', ''one2many'', ''many2many'']\"/>\n                                                </group>\n                                            </group>\n                                            <group invisible=\"ttype not in [''selection'', ''reference'']\" readonly=\"ttype not in [''selection'', ''reference'']\">\n                                                <field name=\"selection_ids\">\n                                                    <tree editable=\"bottom\">\n                                                        <field name=\"sequence\" widget=\"handle\"/>\n                                                        <field name=\"value\"/>\n                                                        <field name=\"name\"/>\n                                                    </tree>\n                                                </field>\n                                            </group>\n                                            <group string=\"Advanced Properties\" groups=\"base.group_no_one\">\n                                                <field name=\"related\"/>\n                                                <field name=\"depends\" required=\"compute not in [False, '''']\"/>\n                                                <field name=\"compute\" widget=\"code\" options=\"{''mode'': ''python''}\"/>\n                                            </group>\n                                            <div groups=\"base.group_no_one\">\n                                                <h3>How to define a computed field</h3>\n                                                <p>Computed fields are defined with the fields\n                                                <strong>Dependencies</strong> and <strong>Compute</strong>.</p>\n                                                <p>The field <strong>Dependencies</strong> lists the fields that\n                                                the current field depends on. It is a comma-separated list of\n                                                field names, like <code>name, size</code>. You can also refer to\n                                                fields accessible through other relational fields, for instance\n                                                <code>partner_id.company_id.name</code>.</p>\n                                                <p>The field <strong>Compute</strong> is the Python code to\n                                                compute the value of the field on a set of records. The value of\n                                                the field must be assigned to each record with a dictionary-like\n                                                assignment.</p>\n                                                <pre>\n    for record in self:\n        record[''size''] = len(record.name)\n</pre>\n                                                <p>The only predefined variables are</p>\n                                                <ul>\n                                                    <li><code>self</code> (the set of records to compute)</li>\n                                                    <li><code>datetime</code> (Python module)</li>\n                                                    <li><code>dateutil</code> (Python module)</li>\n                                                    <li><code>time</code> (Python module)</li>\n                                                </ul>\n                                                <p>Other features are accessible through <code>self</code>, like\n                                                <code>self.env</code>, etc.</p>\n                                            </div>\n                                        </page>\n                                        <page name=\"groups\" string=\"Access Rights\">\n                                            <field name=\"groups\"/>\n                                        </page>\n                                        <page name=\"misc\" string=\"Miscellaneous\" groups=\"base.group_no_one\">\n                                            <group>\n                                                <field name=\"state\"/>\n                                                <field name=\"modules\"/>\n                                            </group>\n                                        </page>\n                                    </notebook>\n                                </form>\n                            </field>\n                            <button groups=\"base.group_no_one\" icon=\"fa-align-justify\" name=\"18\" string=\"Create a Menu\" type=\"action\" target=\"new\"/>\n                        </page>\n                        <page string=\"Access Rights\" name=\"access_rights\">\n                            <field name=\"access_ids\">\n                                <tree string=\"Access Rights\" editable=\"top\" decoration-warning=\"not group_id and                                                          (perm_read or perm_write or                                                           perm_create or perm_unlink)\">\n                                    <field name=\"name\"/>\n                                    <field name=\"group_id\"/>\n                                    <field name=\"perm_read\"/>\n                                    <field name=\"perm_write\"/>\n                                    <field name=\"perm_create\"/>\n                                    <field name=\"perm_unlink\"/>\n                                </tree>\n                            </field>\n                        </page>\n                        <page string=\"Record Rules\" name=\"record_rules\">\n                            <field name=\"rule_ids\">\n                                <tree string=\"Record Rules\" editable=\"top\" decoration-info=\"not groups\">\n                                    <field name=\"name\"/>\n                                    <field name=\"groups\" widget=\"many2many_tags\" options=\"{''no_create'':True}\"/>\n                                    <field name=\"domain_force\"/>\n                                    <field name=\"perm_read\"/>\n                                    <field name=\"perm_write\"/>\n                                    <field name=\"perm_create\"/>\n                                    <field name=\"perm_unlink\"/>\n                                </tree>\n                            </field>\n                        </page>\n                        <page string=\"Notes\" name=\"notes\" groups=\"base.group_no_one\">\n                            <field name=\"info\"/>\n                        </page>\n                        <page string=\"Views\" name=\"views\" groups=\"base.group_no_one\">\n                            <field name=\"view_ids\"/>\n                        </page>\n                    </notebook>\n                  </sheet>\n                </form>"}', '<?xml version="1.0"?>
<form string="Model Description">
                  <header><!-- used for override --></header>
                  <sheet>
                    <group>
                        <group>
                            <field name="id" invisible="1"/>
                            <field name="name"/>
                            <field name="model" readonly="id"/>
                            <field name="order"/>
                            <field name="transient" readonly="id" groups="base.group_no_one"/>
                        </group>
                        <group>
                            <field name="state" readonly="1" groups="base.group_no_one"/>
                            <field name="modules" groups="base.group_no_one"/>
                        </group>
                    </group>
                    <notebook>
                        <page string="Fields" name="fields">
                            <field name="field_id">
                                <tree string="Fields Description">
                                    <field name="name"/>
                                    <field name="field_description"/>
                                    <field name="ttype"/>
                                    <field name="required"/>
                                    <field name="readonly"/>
                                    <field name="index" groups="base.group_no_one"/>
                                    <field name="state" groups="base.group_no_one"/>
                                </tree>
                                <form string="Fields Description">
                                    <group>
                                        <group>
                                            <field name="name"/>
                                            <field name="field_description"/>
                                        </group>
                                        <group>
                                            <field name="ttype"/>
                                            <field name="help"/>
                                        </group>
                                    </group>
                                    <notebook>
                                        <page name="base" string="Properties">
                                            <group string="Base Properties">
                                                <group>
                                                    <field name="required"/>
                                                    <field name="readonly"/>
                                                    <field name="store" groups="base.group_no_one"/>
                                                    <field name="index" groups="base.group_no_one"/>
                                                    <field name="copied" groups="base.group_no_one"/>
                                                </group>
                                                <group>
                                                    <field name="translate" invisible="ttype not in [''char'', ''text'', ''html'']" readonly="ttype not in [''char'', ''text'', ''html'']"/>
                                                    <field name="size" groups="base.group_no_one" invisible="ttype not in [''char'', ''reference'']" readonly="ttype not in [''char'', ''reference'']"/>
                                                    <field name="relation" invisible="ttype not in [''many2one'', ''one2many'', ''many2many'']" readonly="ttype not in [''many2one'', ''one2many'', ''many2many'']" required="ttype in [''many2one'', ''one2many'', ''many2many'']"/>
                                                    <field name="on_delete" groups="base.group_no_one" invisible="ttype != ''many2one''" readonly="ttype != ''many2one''"/>
                                                    <field name="relation_field" invisible="ttype != ''one2many''" readonly="ttype != ''one2many''" required="ttype == ''one2many''"/>
                                                    <field name="relation_table" groups="base.group_no_one" invisible="ttype != ''many2many'' or state != ''manual''" readonly="ttype != ''many2many'' or state != ''manual''"/>
                                                    <field name="column1" groups="base.group_no_one" invisible="ttype != ''many2many'' or state != ''manual''" readonly="ttype != ''many2many'' or state != ''manual''"/>
                                                    <field name="column2" groups="base.group_no_one" invisible="ttype != ''many2many'' or state != ''manual''" readonly="ttype != ''many2many'' or state != ''manual''"/>
                                                    <field name="domain" groups="base.group_no_one" invisible="ttype not in [''many2one'', ''one2many'', ''many2many'']" readonly="ttype not in [''many2one'', ''one2many'', ''many2many'']"/>
                                                </group>
                                            </group>
                                            <group invisible="ttype not in [''selection'', ''reference'']" readonly="ttype not in [''selection'', ''reference'']">
                                                <field name="selection_ids">
                                                    <tree editable="bottom">
                                                        <field name="sequence" widget="handle"/>
                                                        <field name="value"/>
                                                        <field name="name"/>
                                                    </tree>
                                                </field>
                                            </group>
                                            <group string="Advanced Properties" groups="base.group_no_one">
                                                <field name="related"/>
                                                <field name="depends" required="compute not in [False, '''']"/>
                                                <field name="compute" widget="code" options="{''mode'': ''python''}"/>
                                            </group>
                                            <div groups="base.group_no_one">
                                                <h3>How to define a computed field</h3>
                                                <p>Computed fields are defined with the fields
                                                <strong>Dependencies</strong> and <strong>Compute</strong>.</p>
                                                <p>The field <strong>Dependencies</strong> lists the fields that
                                                the current field depends on. It is a comma-separated list of
                                                field names, like <code>name, size</code>. You can also refer to
                                                fields accessible through other relational fields, for instance
                                                <code>partner_id.company_id.name</code>.</p>
                                                <p>The field <strong>Compute</strong> is the Python code to
                                                compute the value of the field on a set of records. The value of
                                                the field must be assigned to each record with a dictionary-like
                                                assignment.</p>
                                                <pre>
    for record in self:
        record[''size''] = len(record.name)
</pre>
                                                <p>The only predefined variables are</p>
                                                <ul>
                                                    <li><code>self</code> (the set of records to compute)</li>
                                                    <li><code>datetime</code> (Python module)</li>
                                                    <li><code>dateutil</code> (Python module)</li>
                                                    <li><code>time</code> (Python module)</li>
                                                </ul>
                                                <p>Other features are accessible through <code>self</code>, like
                                                <code>self.env</code>, etc.</p>
                                            </div>
                                        </page>
                                        <page name="groups" string="Access Rights">
                                            <field name="groups"/>
                                        </page>
                                        <page name="misc" string="Miscellaneous" groups="base.group_no_one">
                                            <group>
                                                <field name="state"/>
                                                <field name="modules"/>
                                            </group>
                                        </page>
                                    </notebook>
                                </form>
                            </field>
                            <button groups="base.group_no_one" icon="fa-align-justify" name="18" string="Create a Menu" type="action" target="new"/>
                        </page>
                        <page string="Access Rights" name="access_rights">
                            <field name="access_ids">
                                <tree string="Access Rights" editable="top" decoration-warning="not group_id and                                                          (perm_read or perm_write or                                                           perm_create or perm_unlink)">
                                    <field name="name"/>
                                    <field name="group_id"/>
                                    <field name="perm_read"/>
                                    <field name="perm_write"/>
                                    <field name="perm_create"/>
                                    <field name="perm_unlink"/>
                                </tree>
                            </field>
                        </page>
                        <page string="Record Rules" name="record_rules">
                            <field name="rule_ids">
                                <tree string="Record Rules" editable="top" decoration-info="not groups">
                                    <field name="name"/>
                                    <field name="groups" widget="many2many_tags" options="{''no_create'':True}"/>
                                    <field name="domain_force"/>
                                    <field name="perm_read"/>
                                    <field name="perm_write"/>
                                    <field name="perm_create"/>
                                    <field name="perm_unlink"/>
                                </tree>
                            </field>
                        </page>
                        <page string="Notes" name="notes" groups="base.group_no_one">
                            <field name="info"/>
                        </page>
                        <page string="Views" name="views" groups="base.group_no_one">
                            <field name="view_ids"/>
                        </page>
                    </notebook>
                  </sheet>
                </form>
            ', false, true, '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872', NULL);
INSERT INTO public.ir_ui_view VALUES (44, 16, NULL, 1, 1, 'ir.model tree', 'ir.model', NULL, 'tree', 'base/views/ir_model_views.xml', 'primary', '{"en_US": "<tree string=\"Model Description\">\n                    <field name=\"model\"/>\n                    <field name=\"name\"/>\n                    <field name=\"state\"/>\n                    <field name=\"transient\"/>\n                </tree>"}', '<?xml version="1.0"?>
<tree string="Model Description">
