                    <field name="name"/>
                    <field name="state"/>
                    <field name="transient"/>
                </tree>
            ', false, true, '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872', NULL);
INSERT INTO public.ir_ui_view VALUES (45, 16, NULL, 1, 1, 'ir.model search', 'ir.model', NULL, 'search', 'base/views/ir_model_views.xml', 'primary', '{"en_US": "<search string=\"Model Description\">\n                    <field name=\"name\" filter_domain=\"[''|'', (''name'',''ilike'',self), (''model'',''ilike'',self)]\" string=\"Model\"/>\n                    <field name=\"model\" filter_domain=\"[(''model'',''ilike'',self)]\" string=\"Technical Name\"/>\n                    <filter string=\"Transient\" name=\"transient\" domain=\"[(''transient'', ''='', True)]\"/>\n                    <separator/>\n                    <filter string=\"Custom\" name=\"custom\" domain=\"[(''state'', ''='', ''manual'')]\"/>\n                    <filter string=\"Base\" name=\"base\" domain=\"[(''state'', ''='', ''base'')]\"/>\n                </search>"}', '<?xml version="1.0"?>
<search string="Model Description">
                    <field name="name" filter_domain="[''|'', (''name'',''ilike'',self), (''model'',''ilike'',self)]" string="Model"/>
                    <field name="model" filter_domain="[(''model'',''ilike'',self)]" string="Technical Name"/>
                    <filter string="Transient" name="transient" domain="[(''transient'', ''='', True)]"/>
                    <separator/>
                    <filter string="Custom" name="custom" domain="[(''state'', ''='', ''manual'')]"/>
                    <filter string="Base" name="base" domain="[(''state'', ''='', ''base'')]"/>
                </search>
            ', false, true, '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872', NULL);
INSERT INTO public.ir_ui_view VALUES (46, 16, NULL, 1, 1, 'ir.model.fields form', 'ir.model.fields', NULL, 'form', 'base/views/ir_model_views.xml', 'primary', '{"en_US": "<form string=\"Fields\" duplicate=\"false\">\n                    <field name=\"state\" invisible=\"1\"/>\n                    <sheet>\n                        <group>\n                            <group>\n                                <field name=\"name\"/>\n                                <field name=\"field_description\"/>\n                                <field name=\"model_id\" readonly=\"state != ''manual''\"/>\n                            </group>\n                            <group>\n                                <field name=\"ttype\"/>\n                                <field name=\"help\"/>\n                            </group>\n                        </group>\n                        <notebook>\n                            <page name=\"base\" string=\"Properties\">\n                                <group string=\"Base Properties\">\n                                    <group>\n                                        <field name=\"required\"/>\n                                        <field name=\"readonly\"/>\n                                        <field name=\"store\" groups=\"base.group_no_one\"/>\n                                        <field name=\"index\" groups=\"base.group_no_one\"/>\n                                        <field name=\"copied\" groups=\"base.group_no_one\"/>\n                                    </group>\n                                    <group>\n                                        <field name=\"translate\" invisible=\"ttype not in [''char'', ''text'', ''html'']\" readonly=\"ttype not in [''char'', ''text'', ''html'']\"/>\n                                        <field name=\"size\" groups=\"base.group_no_one\" invisible=\"ttype not in [''char'', ''reference'']\" readonly=\"ttype not in [''char'', ''reference'']\"/>\n                                        <field name=\"relation\" invisible=\"ttype not in [''many2one'', ''one2many'', ''many2many'']\" readonly=\"ttype not in [''many2one'', ''one2many'', ''many2many'']\" required=\"ttype in [''many2one'', ''one2many'', ''many2many'']\"/>\n                                        <field name=\"group_expand\" groups=\"base.group_no_one\" invisible=\"ttype not in [''many2one'', ''selection'']\" readonly=\"ttype not in [''many2one'', ''selection'']\"/>\n                                        <field name=\"on_delete\" groups=\"base.group_no_one\" invisible=\"ttype != ''many2one''\" readonly=\"ttype != ''many2one''\"/>\n                                        <field name=\"relation_field\" invisible=\"ttype != ''one2many''\" readonly=\"ttype != ''one2many''\" required=\"ttype == ''one2many''\"/>\n                                        <field name=\"relation_table\" groups=\"base.group_no_one\" invisible=\"ttype != ''many2many'' or state != ''manual''\" readonly=\"ttype != ''many2many'' or state != ''manual''\"/>\n                                        <field name=\"column1\" groups=\"base.group_no_one\" invisible=\"ttype != ''many2many'' or state != ''manual''\" readonly=\"ttype != ''many2many'' or state != ''manual''\"/>\n                                        <field name=\"column2\" groups=\"base.group_no_one\" invisible=\"ttype != ''many2many'' or state != ''manual''\" readonly=\"ttype != ''many2many'' or state != ''manual''\"/>\n                                        <field name=\"domain\" groups=\"base.group_no_one\" invisible=\"ttype not in [''many2one'', ''one2many'', ''many2many'']\" readonly=\"ttype not in [''many2one'', ''one2many'', ''many2many'']\"/>\n                                        <field name=\"currency_field\" invisible=\"ttype != ''monetary''\" readonly=\"ttype != ''monetary''\"/>\n                                    </group>\n                                </group>\n                                <group string=\"HTML/Sanitization Properties\">\n                                    <group>\n                                        <field name=\"sanitize\" invisible=\"ttype != ''html''\" readonly=\"ttype != ''html''\"/>\n                                        <field name=\"sanitize_overridable\" invisible=\"ttype != ''html'' or sanitize == False\" readonly=\"ttype != ''html'' or sanitize == False\"/>\n                                        <field name=\"sanitize_tags\" invisible=\"ttype != ''html'' or sanitize == False\" readonly=\"ttype != ''html'' or sanitize == False\"/>\n                                        <field name=\"sanitize_attributes\" invisible=\"ttype != ''html'' or sanitize == False\" readonly=\"ttype != ''html'' or sanitize == False\"/>\n                                    </group>\n                                    <group>\n                                        <field name=\"sanitize_style\" invisible=\"ttype != ''html'' or sanitize == False\" readonly=\"ttype != ''html'' or sanitize == False\"/>\n                                        <field name=\"sanitize_form\" invisible=\"ttype != ''html'' or sanitize == False\" readonly=\"ttype != ''html'' or sanitize == False\"/>\n                                        <field name=\"strip_style\" invisible=\"ttype != ''html'' or sanitize == False\" readonly=\"ttype != ''html'' or sanitize == False\"/>\n                                        <field name=\"strip_classes\" invisible=\"ttype != ''html'' or sanitize == False\" readonly=\"ttype != ''html'' or sanitize == False\"/>\n                                    </group>\n                                </group>\n                                <group invisible=\"ttype not in [''selection'', ''reference'']\" readonly=\"ttype not in [''selection'', ''reference'']\">\n                                    <field name=\"selection_ids\">\n                                        <tree editable=\"bottom\">\n                                            <field name=\"sequence\" widget=\"handle\"/>\n                                            <field name=\"value\"/>\n                                            <field name=\"name\"/>\n                                        </tree>\n                                    </field>\n                                </group>\n                                <group string=\"Advanced Properties\" groups=\"base.group_no_one\">\n                                    <field name=\"related\"/>\n                                    <field name=\"depends\" required=\"compute not in [False, '''']\"/>\n                                    <field name=\"compute\" widget=\"code\" options=\"{''mode'': ''python''}\"/>\n                                </group>\n                                <div groups=\"base.group_no_one\">\n                                    <h3>How to define a computed field</h3>\n                                    <p>Computed fields are defined with the fields\n                                    <strong>Dependencies</strong> and <strong>Compute</strong>.</p>\n                                    <p>The field <strong>Dependencies</strong> lists the fields that\n                                    the current field depends on. It is a comma-separated list of\n                                    field names, like <code>name, size</code>. You can also refer to\n                                    fields accessible through other relational fields, for instance\n                                    <code>partner_id.company_id.name</code>.</p>\n                                    <p>The field <strong>Compute</strong> is the Python code to\n                                    compute the value of the field on a set of records. The value of\n                                    the field must be assigned to each record with a dictionary-like\n                                    assignment.</p>\n                                    <pre>\n    for record in self:\n        record[''size''] = len(record.name)\n</pre>\n                                    <p>The only predefined variables are</p>\n                                    <ul>\n                                        <li><code>self</code> (the set of records to compute)</li>\n                                        <li><code>datetime</code> (Python module)</li>\n                                        <li><code>dateutil</code> (Python module)</li>\n                                        <li><code>time</code> (Python module)</li>\n                                    </ul>\n                                    <p>Other features are accessible through <code>self</code>, like\n                                    <code>self.env</code>, etc.</p>\n                                </div>\n                            </page>\n                            <page name=\"groups\" string=\"Access Rights\">\n                                <field name=\"groups\"/>\n                            </page>\n                            <page name=\"misc\" string=\"Miscellaneous\" groups=\"base.group_no_one\">\n                                <group>\n                                    <field name=\"state\"/>\n                                    <field name=\"modules\"/>\n                                </group>\n                            </page>\n                        </notebook>\n                    </sheet>\n                </form>"}', '<?xml version="1.0"?>
<form string="Fields" duplicate="false">
                    <field name="state" invisible="1"/>
                    <sheet>
                        <group>
                            <group>
                                <field name="name"/>
                                <field name="field_description"/>
                                <field name="model_id" readonly="state != ''manual''"/>
                            </group>
                            <group>
                                <field name="ttype"/>
                                <field name="help"/>
                            </group>
                        </group>
                        <notebook>
                            <page name="base" string="Properties">
                                <group string="Base Properties">
                                    <group>
                                        <field name="required"/>
                                        <field name="readonly"/>
                                        <field name="store" groups="base.group_no_one"/>
                                        <field name="index" groups="base.group_no_one"/>
                                        <field name="copied" groups="base.group_no_one"/>
                                    </group>
                                    <group>
                                        <field name="translate" invisible="ttype not in [''char'', ''text'', ''html'']" readonly="ttype not in [''char'', ''text'', ''html'']"/>
                                        <field name="size" groups="base.group_no_one" invisible="ttype not in [''char'', ''reference'']" readonly="ttype not in [''char'', ''reference'']"/>
                                        <field name="relation" invisible="ttype not in [''many2one'', ''one2many'', ''many2many'']" readonly="ttype not in [''many2one'', ''one2many'', ''many2many'']" required="ttype in [''many2one'', ''one2many'', ''many2many'']"/>
                                        <field name="group_expand" groups="base.group_no_one" invisible="ttype not in [''many2one'', ''selection'']" readonly="ttype not in [''many2one'', ''selection'']"/>
                                        <field name="on_delete" groups="base.group_no_one" invisible="ttype != ''many2one''" readonly="ttype != ''many2one''"/>
                                        <field name="relation_field" invisible="ttype != ''one2many''" readonly="ttype != ''one2many''" required="ttype == ''one2many''"/>
                                        <field name="relation_table" groups="base.group_no_one" invisible="ttype != ''many2many'' or state != ''manual''" readonly="ttype != ''many2many'' or state != ''manual''"/>
                                        <field name="column1" groups="base.group_no_one" invisible="ttype != ''many2many'' or state != ''manual''" readonly="ttype != ''many2many'' or state != ''manual''"/>
                                        <field name="column2" groups="base.group_no_one" invisible="ttype != ''many2many'' or state != ''manual''" readonly="ttype != ''many2many'' or state != ''manual''"/>
                                        <field name="domain" groups="base.group_no_one" invisible="ttype not in [''many2one'', ''one2many'', ''many2many'']" readonly="ttype not in [''many2one'', ''one2many'', ''many2many'']"/>
                                        <field name="currency_field" invisible="ttype != ''monetary''" readonly="ttype != ''monetary''"/>
                                    </group>
                                </group>
                                <group string="HTML/Sanitization Properties">
                                    <group>
                                        <field name="sanitize" invisible="ttype != ''html''" readonly="ttype != ''html''"/>
                                        <field name="sanitize_overridable" invisible="ttype != ''html'' or sanitize == False" readonly="ttype != ''html'' or sanitize == False"/>
                                        <field name="sanitize_tags" invisible="ttype != ''html'' or sanitize == False" readonly="ttype != ''html'' or sanitize == False"/>
                                        <field name="sanitize_attributes" invisible="ttype != ''html'' or sanitize == False" readonly="ttype != ''html'' or sanitize == False"/>
                                    </group>
                                    <group>
                                        <field name="sanitize_style" invisible="ttype != ''html'' or sanitize == False" readonly="ttype != ''html'' or sanitize == False"/>
                                        <field name="sanitize_form" invisible="ttype != ''html'' or sanitize == False" readonly="ttype != ''html'' or sanitize == False"/>
                                        <field name="strip_style" invisible="ttype != ''html'' or sanitize == False" readonly="ttype != ''html'' or sanitize == False"/>
                                        <field name="strip_classes" invisible="ttype != ''html'' or sanitize == False" readonly="ttype != ''html'' or sanitize == False"/>
                                    </group>
                                </group>
                                <group invisible="ttype not in [''selection'', ''reference'']" readonly="ttype not in [''selection'', ''reference'']">
                                    <field name="selection_ids">
                                        <tree editable="bottom">
                                            <field name="sequence" widget="handle"/>
                                            <field name="value"/>
                                            <field name="name"/>
                                        </tree>
                                    </field>
                                </group>
                                <group string="Advanced Properties" groups="base.group_no_one">
                                    <field name="related"/>
                                    <field name="depends" required="compute not in [False, '''']"/>
                                    <field name="compute" widget="code" options="{''mode'': ''python''}"/>
                                </group>
                                <div groups="base.group_no_one">
                                    <h3>How to define a computed field</h3>
                                    <p>Computed fields are defined with the fields
                                    <strong>Dependencies</strong> and <strong>Compute</strong>.</p>
                                    <p>The field <strong>Dependencies</strong> lists the fields that
                                    the current field depends on. It is a comma-separated list of
                                    field names, like <code>name, size</code>. You can also refer to
                                    fields accessible through other relational fields, for instance
                                    <code>partner_id.company_id.name</code>.</p>
                                    <p>The field <strong>Compute</strong> is the Python code to
                                    compute the value of the field on a set of records. The value of
                                    the field must be assigned to each record with a dictionary-like
                                    assignment.</p>
                                    <pre>
    for record in self:
        record[''size''] = len(record.name)
</pre>
                                    <p>The only predefined variables are</p>
                                    <ul>
                                        <li><code>self</code> (the set of records to compute)</li>
                                        <li><code>datetime</code> (Python module)</li>
                                        <li><code>dateutil</code> (Python module)</li>
                                        <li><code>time</code> (Python module)</li>
                                    </ul>
                                    <p>Other features are accessible through <code>self</code>, like
                                    <code>self.env</code>, etc.</p>
                                </div>
                            </page>
                            <page name="groups" string="Access Rights">
                                <field name="groups"/>
                            </page>
                            <page name="misc" string="Miscellaneous" groups="base.group_no_one">
                                <group>
                                    <field name="state"/>
                                    <field name="modules"/>
                                </group>
                            </page>
                        </notebook>
                    </sheet>
                </form>
            ', false, true, '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872', NULL);
INSERT INTO public.ir_ui_view VALUES (47, 16, NULL, 1, 1, 'ir.model.fields tree', 'ir.model.fields', NULL, 'tree', 'base/views/ir_model_views.xml', 'primary', '{"en_US": "<tree string=\"Fields\" duplicate=\"false\">\n                    <field name=\"name\"/>\n                    <field name=\"field_description\"/>\n                    <field name=\"model_id\"/>\n                    <field name=\"ttype\"/>\n                    <field name=\"state\"/>\n                    <field name=\"index\"/>\n                    <field name=\"store\"/>\n                    <field name=\"readonly\"/>\n                    <field name=\"relation\"/>\n                </tree>"}', '<?xml version="1.0"?>
<tree string="Fields" duplicate="false">
                    <field name="name"/>
                    <field name="field_description"/>
                    <field name="model_id"/>
                    <field name="ttype"/>
                    <field name="state"/>
                    <field name="index"/>
                    <field name="store"/>
                    <field name="readonly"/>
                    <field name="relation"/>
                </tree>
            ', false, true, '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872', NULL);
INSERT INTO public.ir_ui_view VALUES (48, 16, NULL, 1, 1, 'ir.model.fields search', 'ir.model.fields', NULL, 'search', 'base/views/ir_model_views.xml', 'primary', '{"en_US": "<search string=\"Fields\">\n                    <field name=\"name\" filter_domain=\"[''|'', (''name'',''ilike'',self), (''field_description'',''ilike'',self)]\" string=\"Field\"/>\n                    <filter string=\"Required\" name=\"required\" domain=\"[(''required'', ''='', True)]\"/>\n                    <separator/>\n                    <filter string=\"Readonly\" name=\"readonly\" domain=\"[(''readonly'', ''='', True)]\"/>\n                    <separator/>\n                    <filter string=\"Custom\" name=\"custom\" domain=\"[(''state'', ''='', ''manual'')]\"/>\n                    <filter string=\"Base\" name=\"base\" domain=\"[(''state'', ''='', ''base'')]\"/>\n                    <separator/>\n                    <filter string=\"Translate\" name=\"translate\" domain=\"[(''translate'', ''='', True)]\"/>\n                    <field name=\"model_id\"/>\n                    <field name=\"ttype\"/>\n                    <field name=\"required\"/>\n                    <field name=\"readonly\"/>\n                    <field name=\"relation\"/>\n                    <group expand=\"0\" string=\"Group By\">\n                        <filter string=\"Model\" name=\"group_by_object\" domain=\"[]\" context=\"{''group_by'':''model_id''}\"/>\n                        <filter string=\"Field Type\" name=\"group_by_ttype\" domain=\"[]\" context=\"{''group_by'':''ttype''}\"/>\n                    </group>\n                </search>"}', '<?xml version="1.0"?>
<search string="Fields">
                    <field name="name" filter_domain="[''|'', (''name'',''ilike'',self), (''field_description'',''ilike'',self)]" string="Field"/>
                    <filter string="Required" name="required" domain="[(''required'', ''='', True)]"/>
                    <separator/>
                    <filter string="Readonly" name="readonly" domain="[(''readonly'', ''='', True)]"/>
                    <separator/>
                    <filter string="Custom" name="custom" domain="[(''state'', ''='', ''manual'')]"/>
                    <filter string="Base" name="base" domain="[(''state'', ''='', ''base'')]"/>
                    <separator/>
                    <filter string="Translate" name="translate" domain="[(''translate'', ''='', True)]"/>
                    <field name="model_id"/>
                    <field name="ttype"/>
                    <field name="required"/>
                    <field name="readonly"/>
                    <field name="relation"/>
                    <group expand="0" string="Group By">
                        <filter string="Model" name="group_by_object" domain="[]" context="{''group_by'':''model_id''}"/>
                        <filter string="Field Type" name="group_by_ttype" domain="[]" context="{''group_by'':''ttype''}"/>
                    </group>
                </search>
            ', false, true, '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872', NULL);
INSERT INTO public.ir_ui_view VALUES (49, 16, NULL, 1, 1, 'ir.model.fields.selection form', 'ir.model.fields.selection', NULL, 'form', 'base/views/ir_model_views.xml', 'primary', '{"en_US": "<form string=\"Fields\" duplicate=\"false\">\n                    <sheet>\n                        <group>\n                            <field name=\"field_id\" options=\"{''no_create'': True}\"/>\n                            <field name=\"value\" groups=\"base.group_no_one\"/>\n                            <field name=\"name\"/>\n                            <field name=\"sequence\" groups=\"base.group_no_one\"/>\n                        </group>\n                    </sheet>\n                </form>"}', '<?xml version="1.0"?>
<form string="Fields" duplicate="false">
