                        </group>
                    </sheet>
                </form>
            ', false, true, '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872', NULL);
INSERT INTO public.ir_ui_view VALUES (50, 16, NULL, 1, 1, 'ir.model.fields.selection tree', 'ir.model.fields.selection', NULL, 'tree', 'base/views/ir_model_views.xml', 'primary', '{"en_US": "<tree>\n                    <field name=\"sequence\" widget=\"handle\"/>\n                    <field name=\"field_id\"/>\n                    <field name=\"value\"/>\n                    <field name=\"name\"/>\n                </tree>"}', '<?xml version="1.0"?>
<tree>
                    <field name="sequence" widget="handle"/>
                    <field name="field_id"/>
                    <field name="value"/>
                    <field name="name"/>
                </tree>
            ', false, true, '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872', NULL);
INSERT INTO public.ir_ui_view VALUES (51, 16, NULL, 1, 1, 'ir.model.fields.selection search', 'ir.model.fields.selection', NULL, 'search', 'base/views/ir_model_views.xml', 'primary', '{"en_US": "<search string=\"Fields\">\n                    <field name=\"field_id\" string=\"Field\"/>\n                    <field name=\"name\" filter_domain=\"[''|'', (''name'',''ilike'',self), (''value'',''ilike'',self)]\" string=\"Selection\"/>\n                    <filter name=\"group_by_field\" context=\"{''group_by'':''field_id''}\" string=\"Field\"/>\n                </search>"}', '<?xml version="1.0"?>
<search string="Fields">
                    <field name="field_id" string="Field"/>
                    <field name="name" filter_domain="[''|'', (''name'',''ilike'',self), (''value'',''ilike'',self)]" string="Selection"/>
                    <filter name="group_by_field" context="{''group_by'':''field_id''}" string="Field"/>
                </search>
            ', false, true, '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872', NULL);
INSERT INTO public.ir_ui_view VALUES (52, 16, NULL, 1, 1, 'ir.model.data form', 'ir.model.data', NULL, 'form', 'base/views/ir_model_views.xml', 'primary', '{"en_US": "<form string=\"External Identifiers\">\n                    <sheet>\n                        <h1>\n                            <field name=\"complete_name\"/>\n                        </h1>\n                        <group>\n                            <group>\n                                <field name=\"module\"/>\n                                <field name=\"name\"/>\n                                <field name=\"noupdate\"/>\n                                <field name=\"write_date\"/>\n                                <field name=\"create_date\"/>\n                            </group>\n                            <group>\n                                <field name=\"display_name\"/>\n                                <field name=\"model\"/>\n                                <field name=\"res_id\"/>\n                                <field name=\"reference\" widget=\"reference\" string=\"Record\"/>\n                            </group>\n                        </group>\n                    </sheet>\n                </form>"}', '<?xml version="1.0"?>
<form string="External Identifiers">
                    <sheet>
                        <h1>
                            <field name="complete_name"/>
                        </h1>
                        <group>
                            <group>
                                <field name="module"/>
                                <field name="name"/>
                                <field name="noupdate"/>
                                <field name="write_date"/>
                                <field name="create_date"/>
                            </group>
                            <group>
                                <field name="display_name"/>
                                <field name="model"/>
                                <field name="res_id"/>
                                <field name="reference" widget="reference" string="Record"/>
                            </group>
                        </group>
                    </sheet>
                </form>
            ', false, true, '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872', NULL);
INSERT INTO public.ir_ui_view VALUES (53, 16, NULL, 1, 1, 'ir.model.data tree', 'ir.model.data', NULL, 'tree', 'base/views/ir_model_views.xml', 'primary', '{"en_US": "<tree string=\"External Identifiers\">\n                    <field name=\"complete_name\"/>\n                    <field name=\"display_name\"/>\n                    <field name=\"model\" groups=\"base.group_no_one\"/>\n                    <field name=\"module\" column_invisible=\"True\"/>\n                    <field name=\"res_id\"/>\n                </tree>"}', '<?xml version="1.0"?>
<tree string="External Identifiers">
                    <field name="complete_name"/>
                    <field name="display_name"/>
                    <field name="model" groups="base.group_no_one"/>
                    <field name="module" column_invisible="True"/>
                    <field name="res_id"/>
                </tree>
            ', false, true, '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872', NULL);
INSERT INTO public.ir_ui_view VALUES (54, 16, NULL, 1, 1, 'ir.model.data search', 'ir.model.data', NULL, 'search', 'base/views/ir_model_views.xml', 'primary', '{"en_US": "<search string=\"External Identifiers\">\n                    <field name=\"name\" filter_domain=\"[(''name'',''ilike'',self)]\" string=\"External Identifier\"/>\n                    <filter string=\"Updatable\" name=\"updatable\" domain=\"[(''noupdate'', ''='', False)]\"/>\n                    <field name=\"module\"/>\n                    <field name=\"model\"/>\n                    <field name=\"res_id\"/>\n                    <field name=\"noupdate\"/>\n                    <group expand=\"0\" string=\"Group By\">\n                        <filter string=\"Module\" name=\"group_by_module\" domain=\"[]\" context=\"{''group_by'':''module''}\"/>\n                        <filter string=\"Model\" name=\"group_by_object\" domain=\"[]\" context=\"{''group_by'':''model''}\"/>\n                    </group>\n                </search>"}', '<?xml version="1.0"?>
<search string="External Identifiers">
                    <field name="name" filter_domain="[(''name'',''ilike'',self)]" string="External Identifier"/>
                    <filter string="Updatable" name="updatable" domain="[(''noupdate'', ''='', False)]"/>
                    <field name="module"/>
                    <field name="model"/>
                    <field name="res_id"/>
                    <field name="noupdate"/>
                    <group expand="0" string="Group By">
                        <filter string="Module" name="group_by_module" domain="[]" context="{''group_by'':''module''}"/>
                        <filter string="Model" name="group_by_object" domain="[]" context="{''group_by'':''model''}"/>
                    </group>
                </search>
            ', false, true, '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872', NULL);
INSERT INTO public.ir_ui_view VALUES (55, 16, NULL, 1, 1, 'ir.model.constraint form', 'ir.model.constraint', NULL, 'form', 'base/views/ir_model_views.xml', 'primary', '{"en_US": "<form string=\"Model Constraints\">\n                <sheet>\n                    <group col=\"4\">\n                        <field name=\"type\"/>\n                        <field name=\"name\"/>\n                        <field name=\"module\" can_create=\"false\"/>\n                        <field name=\"model\"/>\n                    </group>\n                    <group>\n                        <field name=\"message\"/>\n                    </group>\n                </sheet>\n                </form>"}', '<?xml version="1.0"?>
<form string="Model Constraints">
                <sheet>
                    <group col="4">
                        <field name="type"/>
                        <field name="name"/>
                        <field name="module" can_create="false"/>
                        <field name="model"/>
                    </group>
                    <group>
                        <field name="message"/>
                    </group>
                </sheet>
                </form>
            ', false, true, '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872', NULL);
INSERT INTO public.ir_ui_view VALUES (56, 16, NULL, 1, 1, 'ir.model.constraint tree', 'ir.model.constraint', NULL, 'tree', 'base/views/ir_model_views.xml', 'primary', '{"en_US": "<tree string=\"Model Constraints\">\n                    <field name=\"type\"/>\n                    <field name=\"name\"/>\n                    <field name=\"module\"/>\n                    <field name=\"model\"/>\n                </tree>"}', '<?xml version="1.0"?>
<tree string="Model Constraints">
                    <field name="type"/>
                    <field name="name"/>
                    <field name="module"/>
                    <field name="model"/>
