INSERT INTO public.ir_ui_view VALUES (62, 16, NULL, 1, 1, 'ir.model.access form', 'ir.model.access', NULL, 'form', 'base/views/ir_model_views.xml', 'primary', '{"en_US": "<form string=\"Access Rights\">\n                   <sheet>\n                    <div class=\"alert alert-warning text-center\" role=\"alert\">\n                        Please note that modifications will be applied for all users of the specified group\n                    </div>\n                    <group col=\"4\">\n                        <field name=\"name\"/>\n                        <field name=\"model_id\"/>\n                        <field name=\"group_id\"/>\n                        <field name=\"active\" widget=\"boolean_toggle\"/>\n                    </group>\n                    <group string=\"Access\" col=\"4\">\n                        <field name=\"perm_read\"/>\n                        <field name=\"perm_write\"/>\n                        <field name=\"perm_create\"/>\n                        <field name=\"perm_unlink\"/>\n                    </group>\n                   </sheet>\n                </form>"}', '<?xml version="1.0"?>
<form string="Access Rights">
                   <sheet>
                    <div class="alert alert-warning text-center" role="alert">
                        Please note that modifications will be applied for all users of the specified group
                    </div>
                    <group col="4">
                        <field name="name"/>
                        <field name="model_id"/>
                        <field name="group_id"/>
                        <field name="active" widget="boolean_toggle"/>
                    </group>
                    <group string="Access" col="4">
                        <field name="perm_read"/>
                        <field name="perm_write"/>
                        <field name="perm_create"/>
                        <field name="perm_unlink"/>
                    </group>
                   </sheet>
                </form>
            ', false, true, '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872', NULL);
INSERT INTO public.ir_ui_view VALUES (63, 16, NULL, 1, 1, 'ir.model.access search', 'ir.model.access', NULL, 'search', 'base/views/ir_model_views.xml', 'primary', '{"en_US": "<search string=\"Access Rights\">\n                    <field name=\"name\" string=\"Access Rights\"/>\n                    <filter string=\"Global\" name=\"global\" domain=\"[(''group_id'', ''='', False)]\"/>\n                    <separator/>\n                    <filter string=\"Full Access\" name=\"full_access\" domain=\"[(''perm_read'', ''='', True), (''perm_write'', ''='', True), (''perm_create'', ''='', True), (''perm_unlink'', ''='', True)]\"/>\n                    <filter string=\"Read Access\" name=\"read_access\" domain=\"[(''perm_read'', ''='', True)]\"/>\n                    <filter string=\"Write Access\" name=\"write_access\" domain=\"[(''perm_write'', ''='', True)]\"/>\n                    <separator/>\n                    <filter string=\"Archived\" name=\"inactive\" domain=\"[(''active'', ''='', False)]\"/>\n                    <field name=\"model_id\"/>\n                    <field name=\"group_id\"/>\n                    <group expand=\"0\" string=\"Group By\" colspan=\"11\" col=\"11\" groups=\"base.group_no_one\">\n                        <filter string=\"Group\" name=\"group\" domain=\"[]\" context=\"{''group_by'': ''group_id''}\"/>\n                        <filter string=\"Model\" name=\"group_by_object\" domain=\"[]\" context=\"{''group_by'': ''model_id''}\"/>\n                    </group>\n                </search>"}', '<?xml version="1.0"?>
<search string="Access Rights">
                    <field name="name" string="Access Rights"/>
                    <filter string="Global" name="global" domain="[(''group_id'', ''='', False)]"/>
                    <separator/>
                    <filter string="Full Access" name="full_access" domain="[(''perm_read'', ''='', True), (''perm_write'', ''='', True), (''perm_create'', ''='', True), (''perm_unlink'', ''='', True)]"/>
                    <filter string="Read Access" name="read_access" domain="[(''perm_read'', ''='', True)]"/>
                    <filter string="Write Access" name="write_access" domain="[(''perm_write'', ''='', True)]"/>
                    <separator/>
                    <filter string="Archived" name="inactive" domain="[(''active'', ''='', False)]"/>
                    <field name="model_id"/>
                    <field name="group_id"/>
                    <group expand="0" string="Group By" colspan="11" col="11" groups="base.group_no_one">
                        <filter string="Group" name="group" domain="[]" context="{''group_by'': ''group_id''}"/>
                        <filter string="Model" name="group_by_object" domain="[]" context="{''group_by'': ''model_id''}"/>
                    </group>
                </search>
            ', false, true, '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872', NULL);
