INSERT INTO public.ir_ui_view VALUES (64, 16, NULL, 1, 1, 'ir.attachment form', 'ir.attachment', NULL, 'form', 'base/views/ir_attachment_views.xml', 'primary', '{"en_US": "<form string=\"Attachments\">\n                   <sheet>\n                    <label for=\"name\"/>\n                    <h1>\n                        <field name=\"name\"/>\n                    </h1>\n                    <group>\n                        <group class=\"w-100\">\n                            <field name=\"type\"/>\n                            <label for=\"datas\" class=\"mt-1\" invisible=\"type == ''url''\"/>\n                            <field name=\"datas\" nolabel=\"1\" class=\"w-100\" filename=\"name\" invisible=\"type == ''url''\"/>\n                            <field name=\"url\" widget=\"url\" invisible=\"type == ''binary''\"/>\n                            <field name=\"mimetype\" groups=\"base.group_no_one\"/>\n                        </group>\n                        <group string=\"Attached To\" groups=\"base.group_no_one\">\n                            <field name=\"res_model\"/>\n                            <field name=\"res_field\"/>\n                            <field name=\"res_id\"/>\n                            <field name=\"res_name\"/>\n                            <field name=\"company_id\" groups=\"base.group_multi_company\" options=\"{''no_create'': True}\"/>\n                            <field name=\"public\"/>\n                        </group>\n                        <group string=\"History\" groups=\"base.group_no_one\" invisible=\"not create_date\">\n                            <label for=\"create_uid\" string=\"Creation\"/>\n                            <div name=\"creation_div\">\n                                <field name=\"create_uid\" readonly=\"1\" class=\"oe_inline\"/> on\n                                <field name=\"create_date\" readonly=\"1\" class=\"oe_inline\"/>\n                            </div>\n                        </group>\n                        <group name=\"description_group\" string=\"Description\" groups=\"base.group_no_one\" colspan=\"4\">\n                            <field name=\"description\" nolabel=\"1\" colspan=\"2\"/>\n                        </group>\n                        <group groups=\"base.group_no_one\" string=\"Indexed Content\" colspan=\"4\">\n                            <field name=\"index_content\" nolabel=\"1\" colspan=\"2\"/>\n                        </group>\n                    </group>\n                  </sheet>\n                </form>"}', '<?xml version="1.0"?>
<form string="Attachments">
                   <sheet>
                    <label for="name"/>
                    <h1>
                        <field name="name"/>
                    </h1>
                    <group>
                        <group class="w-100">
                            <field name="type"/>
                            <label for="datas" class="mt-1" invisible="type == ''url''"/>
                            <field name="datas" nolabel="1" class="w-100" filename="name" invisible="type == ''url''"/>
                            <field name="url" widget="url" invisible="type == ''binary''"/>
                            <field name="mimetype" groups="base.group_no_one"/>
                        </group>
                        <group string="Attached To" groups="base.group_no_one">
                            <field name="res_model"/>
                            <field name="res_field"/>
                            <field name="res_id"/>
                            <field name="res_name"/>
                            <field name="company_id" groups="base.group_multi_company" options="{''no_create'': True}"/>
                            <field name="public"/>
                        </group>
                        <group string="History" groups="base.group_no_one" invisible="not create_date">
                            <label for="create_uid" string="Creation"/>
                            <div name="creation_div">
                                <field name="create_uid" readonly="1" class="oe_inline"/> on
                                <field name="create_date" readonly="1" class="oe_inline"/>
                            </div>
                        </group>
                        <group name="description_group" string="Description" groups="base.group_no_one" colspan="4">
                            <field name="description" nolabel="1" colspan="2"/>
                        </group>
                        <group groups="base.group_no_one" string="Indexed Content" colspan="4">
                            <field name="index_content" nolabel="1" colspan="2"/>
                        </group>
                    </group>
                  </sheet>
                </form>
            ', false, true, '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872', NULL);
INSERT INTO public.ir_ui_view VALUES (65, 16, NULL, 1, 1, 'ir.attachment tree', 'ir.attachment', NULL, 'tree', 'base/views/ir_attachment_views.xml', 'primary', '{"en_US": "<tree string=\"Attachments\">\n                    <field name=\"name\"/>\n                    <field name=\"res_model\"/>\n                    <field name=\"res_field\"/>\n                    <field name=\"res_id\"/>\n                    <field name=\"type\"/>\n                    <field name=\"file_size\"/>\n                    <field name=\"company_id\" groups=\"base.group_multi_company\"/>\n                    <field name=\"create_uid\"/>\n                    <field name=\"create_date\"/>\n                </tree>"}', '<?xml version="1.0"?>
