                    <field name="res_id"/>
                    <field name="type"/>
                    <field name="file_size"/>
                    <field name="company_id" groups="base.group_multi_company"/>
                    <field name="create_uid"/>
                    <field name="create_date"/>
                </tree>
            ', false, true, '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872', NULL);
INSERT INTO public.ir_ui_view VALUES (66, 16, NULL, 1, 1, 'ir.attachment search', 'ir.attachment', NULL, 'search', 'base/views/ir_attachment_views.xml', 'primary', '{"en_US": "<search string=\"Attachments\">\n                    <field name=\"name\" filter_domain=\"[(''name'',''ilike'',self)]\" string=\"Attachment\"/>\n                    <field name=\"create_date\"/>\n                    <filter name=\"my_documents_filter\" string=\"My Document(s)\" domain=\"[(''create_uid'',''='',uid)]\" help=\"Filter on my documents\"/>\n                    <filter name=\"url_filter\" string=\"URL\" domain=\"[(''type'', ''='', ''url'')]\"/>\n                    <filter name=\"binary_filter\" string=\"Stored\" domain=\"[(''type'', ''='', ''binary'')]\"/>\n                    <separator/>\n                    <field name=\"create_uid\" string=\"Created by\"/>\n                    <field name=\"type\"/>\n                    <group expand=\"0\" string=\"Group By\">\n                        <filter name=\"owner\" string=\"Owner\" domain=\"[]\" context=\"{''group_by'':''create_uid''}\"/>\n                        <filter string=\"Type\" name=\"type\" domain=\"[]\" context=\"{''group_by'':''type''}\" groups=\"base.group_no_one\"/>\n                        <filter string=\"Company\" name=\"company\" domain=\"[]\" context=\"{''group_by'':''company_id''}\" groups=\"base.group_multi_company\"/>\n                        <filter string=\"Creation Date\" name=\"creation_month\" domain=\"[]\" context=\"{''group_by'':''create_date''}\"/>\n                    </group>\n                </search>"}', '<?xml version="1.0"?>
<search string="Attachments">
                    <field name="name" filter_domain="[(''name'',''ilike'',self)]" string="Attachment"/>
                    <field name="create_date"/>
                    <filter name="my_documents_filter" string="My Document(s)" domain="[(''create_uid'',''='',uid)]" help="Filter on my documents"/>
                    <filter name="url_filter" string="URL" domain="[(''type'', ''='', ''url'')]"/>
                    <filter name="binary_filter" string="Stored" domain="[(''type'', ''='', ''binary'')]"/>
                    <separator/>
                    <field name="create_uid" string="Created by"/>
                    <field name="type"/>
                    <group expand="0" string="Group By">
                        <filter name="owner" string="Owner" domain="[]" context="{''group_by'':''create_uid''}"/>
                        <filter string="Type" name="type" domain="[]" context="{''group_by'':''type''}" groups="base.group_no_one"/>
                        <filter string="Company" name="company" domain="[]" context="{''group_by'':''company_id''}" groups="base.group_multi_company"/>
                        <filter string="Creation Date" name="creation_month" domain="[]" context="{''group_by'':''create_date''}"/>
                    </group>
                </search>
            ', false, true, '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872', NULL);
INSERT INTO public.ir_ui_view VALUES (67, 16, NULL, 1, 1, 'ir.rule form', 'ir.rule', NULL, 'form', 'base/views/ir_rule_views.xml', 'primary', '{"en_US": "<form string=\"Record rules\">\n                  <sheet>\n                    <group>\n                        <group string=\"General\">\n                            <field name=\"name\"/>\n                            <field name=\"model_id\"/>\n                            <field name=\"active\" widget=\"boolean_toggle\"/>\n                        </group>\n                        <group string=\"Access Rights\">\n                            <group>\n                                <field name=\"perm_read\"/>\n                                <field name=\"perm_create\"/>\n                            </group>\n                            <group>\n                                <field name=\"perm_write\"/>\n                                <field name=\"perm_unlink\"/>\n                            </group>\n                        </group>\n                    </group>\n                    <separator string=\"Rule Definition (Domain Filter)\"/>\n                    <field name=\"domain_force\" colspan=\"2\" nolabel=\"1\"/>\n                    <group string=\"Groups (no group = global)\">\n                        <field name=\"global\"/>\n                        <field name=\"groups\" nolabel=\"1\" colspan=\"2\"/>\n                    </group>\n                    <i class=\"fa fa-info fa-3x text-info float-start\" role=\"img\" aria-label=\"Info\" title=\"Info\"/>\n                    <h3>Interaction between rules</h3>\n                    <div>\n                      <p>\n                         Global rules (non group-specific) are restrictions, and cannot be bypassed.\n                         Group-specific rules grant additional permissions, but are constrained within the bounds of global ones.\n                         The first group rules restrict further the global rules, but can be relaxed by additional group rules.\n                      </p>\n                      <p>\n                        Detailed algorithm:\n                        <ol>\n                          <li>Global rules are combined together with a logical AND operator, and with the result of the following steps</li>\n                          <li>Group-specific rules are combined together with a logical OR operator</li>\n                          <li>If user belongs to several groups, the results from step 2 are combined with logical OR operator</li>\n                        </ol>\n                      </p>\n                      <p>Example: GLOBAL_RULE_1 AND GLOBAL_RULE_2 AND ( (GROUP_A_RULE_1 OR GROUP_A_RULE_2) OR (GROUP_B_RULE_1 OR GROUP_B_RULE_2) )</p>\n                    </div>\n                   </sheet>\n                </form>"}', '<?xml version="1.0"?>
<form string="Record rules">
                  <sheet>
                    <group>
                        <group string="General">
                            <field name="name"/>
                            <field name="model_id"/>
                            <field name="active" widget="boolean_toggle"/>
                        </group>
                        <group string="Access Rights">
                            <group>
                                <field name="perm_read"/>
                                <field name="perm_create"/>
                            </group>
                            <group>
                                <field name="perm_write"/>
                                <field name="perm_unlink"/>
                            </group>
                        </group>
                    </group>
                    <separator string="Rule Definition (Domain Filter)"/>
                    <field name="domain_force" colspan="2" nolabel="1"/>
                    <group string="Groups (no group = global)">
                        <field name="global"/>
                        <field name="groups" nolabel="1" colspan="2"/>
                    </group>
                    <i class="fa fa-info fa-3x text-info float-start" role="img" aria-label="Info" title="Info"/>
                    <h3>Interaction between rules</h3>
                    <div>
                      <p>
                         Global rules (non group-specific) are restrictions, and cannot be bypassed.
                         Group-specific rules grant additional permissions, but are constrained within the bounds of global ones.
                         The first group rules restrict further the global rules, but can be relaxed by additional group rules.
                      </p>
                      <p>
                        Detailed algorithm:
                        <ol>
                          <li>Global rules are combined together with a logical AND operator, and with the result of the following steps</li>
                          <li>Group-specific rules are combined together with a logical OR operator</li>
                          <li>If user belongs to several groups, the results from step 2 are combined with logical OR operator</li>
                        </ol>
                      </p>
                      <p>Example: GLOBAL_RULE_1 AND GLOBAL_RULE_2 AND ( (GROUP_A_RULE_1 OR GROUP_A_RULE_2) OR (GROUP_B_RULE_1 OR GROUP_B_RULE_2) )</p>
                    </div>
                   </sheet>
                </form>
            ', false, true, '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872', NULL);
INSERT INTO public.ir_ui_view VALUES (68, 16, NULL, 1, 1, 'ir.rule tree', 'ir.rule', NULL, 'tree', 'base/views/ir_rule_views.xml', 'primary', '{"en_US": "<tree string=\"Record Rules\" decoration-info=\"not groups\">\n                    <field name=\"name\"/>\n                    <field name=\"model_id\"/>\n                    <field name=\"groups\" widget=\"many2many_tags\" options=\"{''no_create'':True}\"/>\n                    <field name=\"domain_force\"/>\n                    <field name=\"perm_read\" width=\"85px\"/>\n                    <field name=\"perm_write\" width=\"85px\"/>\n                    <field name=\"perm_create\" width=\"85px\"/>\n                    <field name=\"perm_unlink\" width=\"85px\"/>\n                </tree>"}', '<?xml version="1.0"?>
<tree string="Record Rules" decoration-info="not groups">
                    <field name="name"/>
                    <field name="model_id"/>
                    <field name="groups" widget="many2many_tags" options="{''no_create'':True}"/>
                    <field name="domain_force"/>
