                    <field name="perm_write" width="85px"/>
                    <field name="perm_create" width="85px"/>
                    <field name="perm_unlink" width="85px"/>
                </tree>
            ', false, true, '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872', NULL);
INSERT INTO public.ir_ui_view VALUES (111, 16, NULL, 1, 1, 'IR Profile List', 'ir.profile', NULL, 'tree', 'base/views/ir_profile_views.xml', 'primary', '{"en_US": "<tree string=\"Profile Session\" default_order=\"session desc, id desc\">\n                <field name=\"create_date\"/>\n                <field name=\"session\"/>\n                <field name=\"name\"/>\n                <field name=\"entry_count\"/>\n                <field name=\"sql_count\" optional=\"hide\"/>\n                <field name=\"speedscope_url\" widget=\"url\"/>\n                <field name=\"duration\"/>\n            </tree>"}', '<?xml version="1.0"?>
