                <field name="session"/>
                <field name="name"/>
                <field name="entry_count"/>
                <field name="sql_count" optional="hide"/>
                <field name="speedscope_url" widget="url"/>
                <field name="duration"/>
            </tree>
        ', false, true, '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872', NULL);
INSERT INTO public.ir_ui_view VALUES (69, 16, NULL, 1, 1, 'ir.rule search', 'ir.rule', NULL, 'search', 'base/views/ir_rule_views.xml', 'primary', '{"en_US": "<search string=\"Record Rules\">\n                    <field name=\"name\" string=\"Record Rule\"/>\n                    <field name=\"domain_force\"/>\n                    <field name=\"model_id\"/>\n                    <field name=\"groups\"/>\n                    <filter string=\"Global\" name=\"global\" domain=\"[(''global'', ''='', True)]\"/>\n                    <filter string=\"Group-based\" name=\"group_based\" domain=\"[(''global'', ''='', False)]\"/>\n                    <separator/>\n                    <filter string=\"Full Access\" name=\"full_access_right\" domain=\"[(''perm_read'', ''='', True), (''perm_write'', ''='', True), (''perm_create'', ''='', True), (''perm_unlink'', ''='', True)]\"/>\n                    <filter string=\"Read\" name=\"read_access_right\" domain=\"[(''perm_read'', ''='', True)]\"/>\n                    <filter string=\"Write\" name=\"write_access_right\" domain=\"[(''perm_write'', ''='', True)]\"/>\n                    <filter string=\"Create\" name=\"create_access_right\" domain=\"[(''perm_create'', ''='' ,True)]\"/>\n                    <filter string=\"Delete\" name=\"delete_access_right\" domain=\"[(''perm_unlink'', ''='', True)]\"/>\n                    <separator/>\n                    <filter string=\"Archived\" name=\"inactive\" domain=\"[(''active'', ''='', False)]\"/>\n                    <group string=\"Group By\">\n                        <filter string=\"Model\" name=\"group_by_object\" domain=\"[]\" context=\"{''group_by'': ''model_id''}\"/>\n                        <separator/>\n                        <filter string=\"Group\" name=\"group_by_group\" domain=\"[]\" context=\"{''group_by'': ''groups''}\"/>\n                    </group>\n                </search>"}', '<?xml version="1.0"?>
<search string="Record Rules">
                    <field name="name" string="Record Rule"/>
                    <field name="domain_force"/>
                    <field name="model_id"/>
                    <field name="groups"/>
                    <filter string="Global" name="global" domain="[(''global'', ''='', True)]"/>
                    <filter string="Group-based" name="group_based" domain="[(''global'', ''='', False)]"/>
                    <separator/>
                    <filter string="Full Access" name="full_access_right" domain="[(''perm_read'', ''='', True), (''perm_write'', ''='', True), (''perm_create'', ''='', True), (''perm_unlink'', ''='', True)]"/>
                    <filter string="Read" name="read_access_right" domain="[(''perm_read'', ''='', True)]"/>
                    <filter string="Write" name="write_access_right" domain="[(''perm_write'', ''='', True)]"/>
                    <filter string="Create" name="create_access_right" domain="[(''perm_create'', ''='' ,True)]"/>
                    <filter string="Delete" name="delete_access_right" domain="[(''perm_unlink'', ''='', True)]"/>
                    <separator/>
                    <filter string="Archived" name="inactive" domain="[(''active'', ''='', False)]"/>
                    <group string="Group By">
                        <filter string="Model" name="group_by_object" domain="[]" context="{''group_by'': ''model_id''}"/>
                        <separator/>
                        <filter string="Group" name="group_by_group" domain="[]" context="{''group_by'': ''groups''}"/>
                    </group>
                </search>
            ', false, true, '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872', NULL);
INSERT INTO public.ir_ui_view VALUES (70, 16, NULL, 1, 1, 'ir.sequence form', 'ir.sequence', NULL, 'form', 'base/views/ir_sequence_views.xml', 'primary', '{"en_US": "<form string=\"Sequences\">\n                  <sheet>\n                    <group>\n                      <group>\n                        <field name=\"name\"/>\n                        <field name=\"implementation\"/>\n                      </group>\n                      <group>\n                        <field name=\"code\"/>\n                        <field name=\"active\" widget=\"boolean_toggle\"/>\n                        <field name=\"company_id\" groups=\"base.group_multi_company\"/>\n                      </group>\n                    </group>\n                    <notebook>\n                    <page string=\"Sequence\" name=\"sequence\">\n                        <group>\n                          <group>\n                            <field name=\"prefix\"/>\n                            <field name=\"suffix\"/>\n                            <field name=\"use_date_range\"/>\n                          </group>\n                          <group>\n                            <field name=\"padding\"/>\n                            <field name=\"number_increment\"/>\n                            <field name=\"number_next_actual\" string=\"Next Number\" invisible=\"use_date_range\"/>\n                          </group>\n                        </group>\n                        <field name=\"date_range_ids\" invisible=\"not use_date_range\">\n                            <tree string=\"Sequences\" editable=\"top\">\n                                <field name=\"date_from\"/>\n                                <field name=\"date_to\"/>\n                                <field name=\"number_next_actual\" string=\"Next Number\"/>\n                            </tree>\n                        </field>\n                        <group col=\"3\" string=\"Legend (for prefix, suffix)\">\n                            <group>\n                                <span colspan=\"2\">Current Year with Century: %(year)s</span>\n                                <span colspan=\"2\">Current Year without Century: %(y)s</span>\n                                <span colspan=\"2\">Month: %(month)s</span>\n                                <span colspan=\"2\">Day: %(day)s</span>\n                            </group>\n                            <group>\n                                <span colspan=\"2\">Day of the Year: %(doy)s</span>\n                                <span colspan=\"2\">Week of the Year: %(woy)s</span>\n                                <span colspan=\"2\">Day of the Week (0:Monday): %(weekday)s</span>\n                            </group>\n                            <group>\n                                <span colspan=\"2\">Hour 00-&gt;24: %(h24)s</span>\n                                <span colspan=\"2\">Hour 00-&gt;12: %(h12)s</span>\n                                <span colspan=\"2\">Minute: %(min)s</span>\n                                <span colspan=\"2\">Second: %(sec)s</span>\n                            </group>\n                        </group>\n                        <group invisible=\"not use_date_range\">\n                            <div colspan=\"2\">\n                                When subsequences per date range are used, you can prefix variables with ''range_''\n                                to use the beginning of the range instead of the current date, e.g. %(range_year)s instead of %(year)s.\n                            </div>\n                        </group>\n                    </page>\n                    </notebook>\n                   </sheet>\n                </form>"}', '<?xml version="1.0"?>
<form string="Sequences">
                  <sheet>
                    <group>
                      <group>
                        <field name="name"/>
                        <field name="implementation"/>
                      </group>
                      <group>
                        <field name="code"/>
                        <field name="active" widget="boolean_toggle"/>
                        <field name="company_id" groups="base.group_multi_company"/>
                      </group>
                    </group>
                    <notebook>
                    <page string="Sequence" name="sequence">
                        <group>
                          <group>
                            <field name="prefix"/>
                            <field name="suffix"/>
                            <field name="use_date_range"/>
                          </group>
                          <group>
                            <field name="padding"/>
                            <field name="number_increment"/>
                            <field name="number_next_actual" string="Next Number" invisible="use_date_range"/>
                          </group>
                        </group>
                        <field name="date_range_ids" invisible="not use_date_range">
                            <tree string="Sequences" editable="top">
                                <field name="date_from"/>
                                <field name="date_to"/>
                                <field name="number_next_actual" string="Next Number"/>
                            </tree>
                        </field>
                        <group col="3" string="Legend (for prefix, suffix)">
                            <group>
                                <span colspan="2">Current Year with Century: %(year)s</span>
                                <span colspan="2">Current Year without Century: %(y)s</span>
                                <span colspan="2">Month: %(month)s</span>
                                <span colspan="2">Day: %(day)s</span>
                            </group>
                            <group>
                                <span colspan="2">Day of the Year: %(doy)s</span>
                                <span colspan="2">Week of the Year: %(woy)s</span>
                                <span colspan="2">Day of the Week (0:Monday): %(weekday)s</span>
                            </group>
                            <group>
                                <span colspan="2">Hour 00-&gt;24: %(h24)s</span>
                                <span colspan="2">Hour 00-&gt;12: %(h12)s</span>
                                <span colspan="2">Minute: %(min)s</span>
                                <span colspan="2">Second: %(sec)s</span>
                            </group>
                        </group>
                        <group invisible="not use_date_range">
                            <div colspan="2">
                                When subsequences per date range are used, you can prefix variables with ''range_''
                                to use the beginning of the range instead of the current date, e.g. %(range_year)s instead of %(year)s.
                            </div>
                        </group>
                    </page>
                    </notebook>
                   </sheet>
                </form>
            ', false, true, '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872', NULL);
INSERT INTO public.ir_ui_view VALUES (71, 16, NULL, 1, 1, 'ir.sequence tree', 'ir.sequence', NULL, 'tree', 'base/views/ir_sequence_views.xml', 'primary', '{"en_US": "<tree string=\"Sequences\">\n                    <field name=\"code\"/>\n                    <field name=\"name\"/>\n                    <field name=\"prefix\"/>\n                    <field name=\"padding\"/>\n                    <field name=\"company_id\" groups=\"base.group_multi_company\"/>\n                    <field name=\"number_next_actual\" string=\"Next Number\"/>\n                    <field name=\"number_increment\"/>\n                    <field name=\"implementation\"/>\n                </tree>"}', '<?xml version="1.0"?>
