INSERT INTO public.ir_ui_view VALUES (73, 16, NULL, 1, 1, 'ir.ui.menu form', 'ir.ui.menu', NULL, 'form', 'base/views/ir_ui_menu_views.xml', 'primary', '{"en_US": "<form string=\"Menu\">\n                    <sheet>\n                        <field name=\"active\" invisible=\"1\"/>\n                        <group>\n                            <group>\n                                <field name=\"name\"/>\n                                <field name=\"parent_id\" groups=\"base.group_no_one\"/>\n                                <field name=\"sequence\" groups=\"base.group_no_one\"/>\n                            </group>\n                            <group groups=\"base.group_no_one\">\n                                <field name=\"complete_name\"/>\n                                <field name=\"action\"/>\n                                <field name=\"web_icon\"/>\n                                <field name=\"web_icon_data\"/>\n                            </group>\n                        </group>\n                        <notebook>\n                            <page string=\"Visibility\" name=\"access_rights\">\n                                <field name=\"groups_id\"/>\n                            </page>\n                            <page string=\"Submenus\" name=\"submenus\" groups=\"base.group_no_one\">\n                                <!-- Note: make sure you have ''ir.ui.menu.full_list''\n                                    in the context to see all submenus! -->\n                                <field name=\"child_id\" context=\"{''default_parent_id'': id}\">\n                                    <tree string=\"Menu\">\n                                        <field name=\"sequence\"/>\n                                        <field icon=\"icon\" name=\"name\" string=\"Menu\"/>\n                                    </tree>\n                                </field>\n                            </page>\n                        </notebook>\n                   </sheet>\n                </form>"}', '<?xml version="1.0"?>
<form string="Menu">
                    <sheet>
                        <field name="active" invisible="1"/>
                        <group>
                            <group>
                                <field name="name"/>
                                <field name="parent_id" groups="base.group_no_one"/>
                                <field name="sequence" groups="base.group_no_one"/>
                            </group>
                            <group groups="base.group_no_one">
                                <field name="complete_name"/>
                                <field name="action"/>
                                <field name="web_icon"/>
                                <field name="web_icon_data"/>
                            </group>
                        </group>
                        <notebook>
                            <page string="Visibility" name="access_rights">
                                <field name="groups_id"/>
                            </page>
                            <page string="Submenus" name="submenus" groups="base.group_no_one">
                                <!-- Note: make sure you have ''ir.ui.menu.full_list''
                                    in the context to see all submenus! -->
                                <field name="child_id" context="{''default_parent_id'': id}">
                                    <tree string="Menu">
                                        <field name="sequence"/>
                                        <field icon="icon" name="name" string="Menu"/>
                                    </tree>
                                </field>
                            </page>
                        </notebook>
                   </sheet>
                </form>
            ', false, true, '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872', NULL);
