INSERT INTO public.ir_ui_view VALUES (78, 16, NULL, 1, 1, 'ir.ui.view search', 'ir.ui.view', NULL, 'search', 'base/views/ir_ui_view_views.xml', 'primary', '{"en_US": "<search string=\"Views\">\n                    <field name=\"name\" filter_domain=\"[''|'', ''|'', (''name'',''ilike'',self), (''model'',''ilike'',self), (''model_data_id'',''ilike'',self)]\" string=\"View\"/>\n                    <field name=\"key\"/>\n                    <field name=\"model\"/>\n                    <field name=\"inherit_id\"/>\n                    <field name=\"type\"/>\n                    <field name=\"arch_db\" string=\"View Architecture\"/>\n                    <filter string=\"Form\" name=\"form\" domain=\"[(''type'', ''='',''form'')]\"/>\n                    <filter string=\"Tree\" name=\"tree\" domain=\"[(''type'', ''='', ''tree'')]\"/>\n                    <filter string=\"Kanban\" name=\"kanban\" domain=\"[(''type'', ''='', ''kanban'')]\"/>\n                    <filter string=\"Search\" name=\"search\" domain=\"[(''type'', ''='', ''search'')]\"/>\n                    <filter string=\"QWeb\" name=\"qweb\" domain=\"[(''type'', ''='', ''qweb'')]\"/>\n                    <separator/>\n                    <filter string=\"Modified Architecture\" name=\"arch_updated\" domain=\"[(''arch_updated'', ''='',True)]\"/>\n                    <separator/>\n                    <filter string=\"Active\" name=\"active\" domain=\"[(''active'', ''='',True)]\"/>\n                    <filter string=\"Inactive\" name=\"inactive\" domain=\"[(''active'', ''='',False)]\"/>\n                    <group expand=\"0\" string=\"Group By\">\n                        <filter string=\"Model\" name=\"object\" domain=\"[]\" context=\"{''group_by'':''model''}\"/>\n                        <filter string=\"Type\" name=\"type\" domain=\"[]\" context=\"{''group_by'':''type''}\"/>\n                        <filter string=\"Inherit\" name=\"inherit\" domain=\"[]\" context=\"{''group_by'':''inherit_id''}\"/>\n                    </group>\n                </search>"}', '<?xml version="1.0"?>
<search string="Views">
                    <field name="name" filter_domain="[''|'', ''|'', (''name'',''ilike'',self), (''model'',''ilike'',self), (''model_data_id'',''ilike'',self)]" string="View"/>
                    <field name="key"/>
                    <field name="model"/>
                    <field name="inherit_id"/>
                    <field name="type"/>
                    <field name="arch_db" string="View Architecture"/>
                    <filter string="Form" name="form" domain="[(''type'', ''='',''form'')]"/>
                    <filter string="Tree" name="tree" domain="[(''type'', ''='', ''tree'')]"/>
                    <filter string="Kanban" name="kanban" domain="[(''type'', ''='', ''kanban'')]"/>
                    <filter string="Search" name="search" domain="[(''type'', ''='', ''search'')]"/>
                    <filter string="QWeb" name="qweb" domain="[(''type'', ''='', ''qweb'')]"/>
                    <separator/>
                    <filter string="Modified Architecture" name="arch_updated" domain="[(''arch_updated'', ''='',True)]"/>
                    <separator/>
                    <filter string="Active" name="active" domain="[(''active'', ''='',True)]"/>
                    <filter string="Inactive" name="inactive" domain="[(''active'', ''='',False)]"/>
                    <group expand="0" string="Group By">
                        <filter string="Model" name="object" domain="[]" context="{''group_by'':''model''}"/>
                        <filter string="Type" name="type" domain="[]" context="{''group_by'':''type''}"/>
                        <filter string="Inherit" name="inherit" domain="[]" context="{''group_by'':''inherit_id''}"/>
                    </group>
                </search>
            ', false, true, '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872', NULL);
INSERT INTO public.ir_ui_view VALUES (79, 16, NULL, 1, 1, 'Reset View Architecture', 'reset.view.arch.wizard', NULL, 'form', 'base/views/ir_ui_view_views.xml', 'primary', '{"en_US": "<form string=\"Reset View Architecture\">\n                    <group>\n                        <group>\n                            <field name=\"has_diff\" invisible=\"1\"/>\n                            <field name=\"view_id\" invisible=\"1\"/>\n                            <field name=\"view_name\"/>\n                            <field name=\"compare_view_id\" invisible=\"reset_mode != ''other_view''\" options=\"{''no_create'': True, ''no_open'': True}\"/>\n                        </group>\n                        <group>\n                            <field name=\"reset_mode\" widget=\"radio\"/>\n                        </group>\n                    </group>\n                    <field name=\"arch_diff\" invisible=\"not arch_diff\"/>\n                    <div class=\"alert alert-warning my-2\" role=\"alert\" invisible=\"arch_diff\">\n                        <span invisible=\"reset_mode != ''soft''\">This view has no previous version.</span>\n                        <span invisible=\"reset_mode != ''hard''\">This view is not coming from a file.</span>\n                        <span invisible=\"reset_mode != ''other_view''\">You need two views to compare.</span>\n                    </div>\n                    <footer>\n                        <button string=\"Reset View\" name=\"reset_view_button\" type=\"object\" class=\"btn-primary\" invisible=\"not has_diff\" data-hotkey=\"q\"/>\n                        <button string=\"Cancel\" class=\"btn-secondary\" special=\"cancel\" data-hotkey=\"x\"/>\n                    </footer>\n                </form>"}', '<?xml version="1.0"?>
<form string="Reset View Architecture">
                    <group>
                        <group>
                            <field name="has_diff" invisible="1"/>
                            <field name="view_id" invisible="1"/>
                            <field name="view_name"/>
                            <field name="compare_view_id" invisible="reset_mode != ''other_view''" options="{''no_create'': True, ''no_open'': True}"/>
                        </group>
                        <group>
                            <field name="reset_mode" widget="radio"/>
                        </group>
                    </group>
                    <field name="arch_diff" invisible="not arch_diff"/>
                    <div class="alert alert-warning my-2" role="alert" invisible="arch_diff">
                        <span invisible="reset_mode != ''soft''">This view has no previous version.</span>
                        <span invisible="reset_mode != ''hard''">This view is not coming from a file.</span>
                        <span invisible="reset_mode != ''other_view''">You need two views to compare.</span>
                    </div>
                    <footer>
                        <button string="Reset View" name="reset_view_button" type="object" class="btn-primary" invisible="not has_diff" data-hotkey="q"/>
                        <button string="Cancel" class="btn-secondary" special="cancel" data-hotkey="x"/>
                    </footer>
                </form>
            ', false, true, '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872', NULL);
INSERT INTO public.ir_ui_view VALUES (80, 16, NULL, 1, 1, 'ir.ui.view.custom form', 'ir.ui.view.custom', NULL, 'form', 'base/views/ir_ui_view_views.xml', 'primary', '{"en_US": "<form string=\"Customized Views\">\n                  <sheet>\n                    <group col=\"4\">\n                        <field name=\"user_id\"/>\n                        <field name=\"ref_id\"/>\n                        <separator string=\"View Architecture\" colspan=\"4\"/>\n                        <field name=\"arch\" colspan=\"4\" nolabel=\"1\"/>\n                    </group>\n                   </sheet>\n                </form>"}', '<?xml version="1.0"?>
<form string="Customized Views">
                  <sheet>
                    <group col="4">
                        <field name="user_id"/>
                        <field name="ref_id"/>
                        <separator string="View Architecture" colspan="4"/>
                        <field name="arch" colspan="4" nolabel="1"/>
                    </group>
                   </sheet>
                </form>
            ', false, true, '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872', NULL);
INSERT INTO public.ir_ui_view VALUES (81, 16, NULL, 1, 1, 'ir.ui.view.custom tree', 'ir.ui.view.custom', NULL, 'tree', 'base/views/ir_ui_view_views.xml', 'primary', '{"en_US": "<tree string=\"Customized Views\">\n                    <field name=\"user_id\"/>\n                    <field name=\"ref_id\"/>\n                </tree>"}', '<?xml version="1.0"?>
<tree string="Customized Views">
                    <field name="user_id"/>
                    <field name="ref_id"/>
                </tree>
            ', false, true, '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872', NULL);
INSERT INTO public.ir_ui_view VALUES (82, 16, NULL, 1, 1, 'ir.ui.view.custom search', 'ir.ui.view.custom', NULL, 'search', 'base/views/ir_ui_view_views.xml', 'primary', '{"en_US": "<search string=\"Customized Views\">\n                    <field name=\"user_id\"/>\n                    <field name=\"ref_id\"/>\n                </search>"}', '<?xml version="1.0"?>
<search string="Customized Views">
                    <field name="user_id"/>
                    <field name="ref_id"/>
                </search>
            ', false, true, '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872', NULL);
INSERT INTO public.ir_ui_view VALUES (108, 16, NULL, 1, 1, 'Demo Failure Dialog', 'ir.demo_failure.wizard', NULL, 'form', 'base/data/ir_demo_failure_data.xml', 'primary', '{"en_US": "<form>\n                <h3>\n                    The demonstration data of <field name=\"failures_count\"/>\n                    module(s) failed to install and were disabled\n                </h3>\n                <field name=\"failure_ids\">\n                    <tree>\n                        <field name=\"module_id\"/>\n                        <field name=\"error\"/>\n                    </tree>\n                </field>\n                <footer>\n                    <button string=\"Ok\" class=\"oe_highlight\" type=\"object\" name=\"done\" data-hotkey=\"q\"/>\n                </footer>\n            </form>"}', '<?xml version="1.0"?>
<form>
                <h3>
                    The demonstration data of <field name="failures_count"/>
                    module(s) failed to install and were disabled
                </h3>
                <field name="failure_ids">
                    <tree>
                        <field name="module_id"/>
                        <field name="error"/>
                    </tree>
                </field>
                <footer>
                    <button string="Ok" class="oe_highlight" type="object" name="done" data-hotkey="q"/>
                </footer>
            </form>
        ', false, true, '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872', NULL);
INSERT INTO public.ir_ui_view VALUES (83, 16, NULL, 1, 1, 'ir.default form view', 'ir.default', NULL, 'form', 'base/views/ir_default_views.xml', 'primary', '{"en_US": "<form string=\"User-defined Defaults\">\n            <sheet>\n                <group>\n                    <group name=\"field_value\">\n                        <field name=\"field_id\" options=\"{''no_create'': True}\"/>\n                        <field name=\"json_value\"/>\n                        <field name=\"condition\"/>\n                    </group>\n                    <group name=\"user_company_details\">\n                        <field name=\"user_id\"/>\n                        <field name=\"company_id\" groups=\"base.group_multi_company\"/>\n                    </group>\n                </group>\n            </sheet>\n            </form>"}', '<?xml version="1.0"?>
<form string="User-defined Defaults">
            <sheet>
                <group>
                    <group name="field_value">
                        <field name="field_id" options="{''no_create'': True}"/>
                        <field name="json_value"/>
                        <field name="condition"/>
                    </group>
                    <group name="user_company_details">
                        <field name="user_id"/>
                        <field name="company_id" groups="base.group_multi_company"/>
                    </group>
                </group>
            </sheet>
            </form>
        ', false, true, '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872', NULL);
INSERT INTO public.ir_ui_view VALUES (84, 16, NULL, 1, 1, 'ir.default tree view', 'ir.default', NULL, 'tree', 'base/views/ir_default_views.xml', 'primary', '{"en_US": "<tree string=\"User-defined Defaults\">\n                <field name=\"field_id\"/>\n                <field name=\"json_value\"/>\n                <field name=\"condition\" optional=\"hide\"/>\n                <field name=\"user_id\"/>\n                <field name=\"company_id\" groups=\"base.group_multi_company\"/>\n            </tree>"}', '<?xml version="1.0"?>
<tree string="User-defined Defaults">
                <field name="field_id"/>
                <field name="json_value"/>
                <field name="condition" optional="hide"/>
                <field name="user_id"/>
                <field name="company_id" groups="base.group_multi_company"/>
            </tree>
        ', false, true, '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872', NULL);
INSERT INTO public.ir_ui_view VALUES (85, 16, NULL, 1, 1, 'ir.default search view', 'ir.default', NULL, 'search', 'base/views/ir_default_views.xml', 'primary', '{"en_US": "<search string=\"User-defined Defaults\">\n                <field name=\"field_id\"/>\n                <field name=\"user_id\"/>\n                <field name=\"company_id\" groups=\"base.group_multi_company\"/>\n                <group expand=\"0\" string=\"Group By\">\n                    <filter string=\"User\" name=\"groupby_user\" domain=\"[]\" context=\"{''group_by'':''user_id''}\"/>\n                    <filter string=\"Company\" name=\"groupby_company\" domain=\"[]\" context=\"{''group_by'':''company_id''}\"/>\n                </group>\n            </search>"}', '<?xml version="1.0"?>
<search string="User-defined Defaults">
                <field name="field_id"/>
                <field name="user_id"/>
                <field name="company_id" groups="base.group_multi_company"/>
                <group expand="0" string="Group By">
                    <filter string="User" name="groupby_user" domain="[]" context="{''group_by'':''user_id''}"/>
                    <filter string="Company" name="groupby_company" domain="[]" context="{''group_by'':''company_id''}"/>
                </group>
            </search>
        ', false, true, '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872', NULL);
INSERT INTO public.ir_ui_view VALUES (86, 16, NULL, 1, 1, 'report_irmodeloverview', NULL, 'base.report_irmodeloverview', 'qweb', 'base/report/ir_model_templates.xml', 'primary', '{"en_US": "<t t-name=\"base.report_irmodeloverview\">\n    <t t-call=\"web.html_container\">\n        <t t-foreach=\"docs\" t-as=\"o\">\n            <div class=\"article\" t-att-data-oe-model=\"o._name\" t-att-data-oe-id=\"o.id\">\n                <table class=\"table table-bordered mb64\">\n                    <tr>\n                        <td colspan=\"12\">\n                            <strong>Object: <span t-field=\"o.model\"/>\n                            <p>Name: <span t-field=\"o.name\"/></p></strong>\n                        </td>\n                        <td colspan=\"8\">\n                            <p>Type: <span t-field=\"o.state\"/></p>\n                            <p t-if=\"o.transient\">Transient: True</p>\n                            <p t-if=\"not o.transient\">Transient: False</p>\n                            <p>Apps: <span t-field=\"o.modules\"/></p>\n                        </td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"20\"><u><strong>Security</strong></u></td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"4\"><strong>Group</strong></td>\n                        <td><strong>R</strong></td>\n                        <td><strong>W</strong></td>\n                        <td><strong>C</strong></td>\n                        <td><strong>U</strong></td>\n                        <td colspan=\"12\"><strong>Name</strong></td>\n                    </tr>\n                    <tr t-foreach=\"o.access_ids\" t-as=\"access\">\n                        <td colspan=\"4\"><span t-field=\"access.group_id\"/></td>\n                        <td><t t-if=\"access.perm_read\">X</t></td>\n                        <td><t t-if=\"access.perm_write\">X</t></td>\n                        <td><t t-if=\"access.perm_create\">X</t></td>\n                        <td><t t-if=\"access.perm_unlink\">X</t></td>\n                        <td colspan=\"12\"><span t-field=\"access.name\"/></td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"20\"><u><strong>Fields</strong></u></td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"3\"><strong>Name</strong></td>\n                        <td colspan=\"3\"><strong>Label</strong></td>\n                        <td colspan=\"2\"><strong>Type</strong></td>\n                        <td colspan=\"4\"><strong>Attribute</strong></td>\n                        <td><strong>Rq</strong></td>\n                        <td><strong>Ro</strong></td>\n                        <td><strong>Tr</strong></td>\n                        <td><strong>Idx</strong></td>\n                        <td colspan=\"4\"><strong>Apps</strong></td>\n                    </tr>\n                    <tr t-foreach=\"o.field_id\" t-as=\"field\">\n                        <td colspan=\"3\"><span t-field=\"field.name\"/></td>\n                        <td colspan=\"3\"><span t-field=\"field.field_description\"/></td>\n                        <td colspan=\"2\"><span t-field=\"field.ttype\"/></td>\n                        <td colspan=\"4\">\n                            <p t-if=\"field.relation\"><span>- relation = <span t-field=\"field.relation\"/></span></p>\n                            <p t-if=\"field.relation_field\"><span>- field = <span t-field=\"field.relation_field\"/></span></p>\n                            <div t-if=\"field.selection_ids\">\n                                <span>- selection = [\n                                    <t t-foreach=\"field.selection_ids\" t-as=\"selection\">\n                                        (<span t-field=\"selection.value\"/>, <span t-field=\"selection.name\"/>),\n                                    </t>]\n                                </span>\n                            </div>\n                            <div t-if=\"field.size\"><span>- size = <span t-field=\"field.size\"/></span></div>\n                            <div t-if=\"field.on_delete\"><span>- ondelete = <span t-field=\"field.on_delete\"/></span></div>\n                            <div t-if=\"field.domain\"><span>- domain = <span t-field=\"field.domain\"/></span></div>\n                            <div t-if=\"field.groups\"><span>- groups = <span t-esc=\"'', ''.join(g.name for g in field.groups)\"/></span></div>\n                        </td>\n                        <td><t t-if=\"field.required\">X</t></td>\n                        <td><t t-if=\"field.readonly\">X</t></td>\n                        <td><t t-if=\"field.translate\">X</t></td>\n                        <td><t t-if=\"field.index\">X</t></td>\n                        <td colspan=\"4\"><span t-field=\"field.modules\"/></td>\n                    </tr>\n                    <tr>\n                        <td colspan=\"20\"><u><strong>Views</strong></u></td>\n                    </tr>\n                    <tr>\n                        <td><strong>Seq</strong></td>\n                        <td><strong>Type</strong></td>\n                        <td colspan=\"4\"><strong>Name</strong></td>\n                        <td colspan=\"6\"><strong>XML ID</strong></td>\n                        <td colspan=\"8\"><strong>Inherited</strong></td>\n                    </tr>\n                    <tr t-foreach=\"o.view_ids\" t-as=\"view\">\n                        <td><span t-field=\"view.priority\"/></td>\n                        <td><span t-field=\"view.type\"/></td>\n                        <td colspan=\"4\"><span t-field=\"view.name\"/></td>\n                        <td colspan=\"6\"><span t-field=\"view.xml_id\"/></td>\n                        <td colspan=\"8\" t-if=\"view.inherit_id.xml_id\"><span t-field=\"view.inherit_id.xml_id\"/></td>\n                        <td colspan=\"8\" t-if=\"not view.inherit_id.xml_id\"><span t-field=\"view.inherit_id.name\"/></td>\n                    </tr>\n                </table>\n            </div>\n        </t>\n    </t>\n</t>"}', '<?xml version="1.0"?>
<t t-name="base.report_irmodeloverview">
    <t t-call="web.html_container">
        <t t-foreach="docs" t-as="o">
            <div class="article" t-att-data-oe-model="o._name" t-att-data-oe-id="o.id">
                <table class="table table-bordered mb64">
                    <tr>
                        <td colspan="12">
                            <strong>Object: <span t-field="o.model"/>
                            <p>Name: <span t-field="o.name"/></p></strong>
                        </td>
                        <td colspan="8">
                            <p>Type: <span t-field="o.state"/></p>
                            <p t-if="o.transient">Transient: True</p>
                            <p t-if="not o.transient">Transient: False</p>
                            <p>Apps: <span t-field="o.modules"/></p>
                        </td>
                    </tr>
                    <tr>
                        <td colspan="20"><u><strong>Security</strong></u></td>
                    </tr>
                    <tr>
                        <td colspan="4"><strong>Group</strong></td>
                        <td><strong>R</strong></td>
                        <td><strong>W</strong></td>
                        <td><strong>C</strong></td>
                        <td><strong>U</strong></td>
                        <td colspan="12"><strong>Name</strong></td>
                    </tr>
                    <tr t-foreach="o.access_ids" t-as="access">
                        <td colspan="4"><span t-field="access.group_id"/></td>
                        <td><t t-if="access.perm_read">X</t></td>
                        <td><t t-if="access.perm_write">X</t></td>
                        <td><t t-if="access.perm_create">X</t></td>
                        <td><t t-if="access.perm_unlink">X</t></td>
                        <td colspan="12"><span t-field="access.name"/></td>
                    </tr>
                    <tr>
                        <td colspan="20"><u><strong>Fields</strong></u></td>
                    </tr>
                    <tr>
                        <td colspan="3"><strong>Name</strong></td>
                        <td colspan="3"><strong>Label</strong></td>
                        <td colspan="2"><strong>Type</strong></td>
                        <td colspan="4"><strong>Attribute</strong></td>
                        <td><strong>Rq</strong></td>
                        <td><strong>Ro</strong></td>
                        <td><strong>Tr</strong></td>
                        <td><strong>Idx</strong></td>
                        <td colspan="4"><strong>Apps</strong></td>
                    </tr>
                    <tr t-foreach="o.field_id" t-as="field">
                        <td colspan="3"><span t-field="field.name"/></td>
                        <td colspan="3"><span t-field="field.field_description"/></td>
                        <td colspan="2"><span t-field="field.ttype"/></td>
                        <td colspan="4">
                            <p t-if="field.relation"><span>- relation = <span t-field="field.relation"/></span></p>
                            <p t-if="field.relation_field"><span>- field = <span t-field="field.relation_field"/></span></p>
                            <div t-if="field.selection_ids">
                                <span>- selection = [
                                    <t t-foreach="field.selection_ids" t-as="selection">
                                        (<span t-field="selection.value"/>, <span t-field="selection.name"/>),
                                    </t>]
                                </span>
                            </div>
                            <div t-if="field.size"><span>- size = <span t-field="field.size"/></span></div>
                            <div t-if="field.on_delete"><span>- ondelete = <span t-field="field.on_delete"/></span></div>
                            <div t-if="field.domain"><span>- domain = <span t-field="field.domain"/></span></div>
                            <div t-if="field.groups"><span>- groups = <span t-esc="'', ''.join(g.name for g in field.groups)"/></span></div>
                        </td>
                        <td><t t-if="field.required">X</t></td>
                        <td><t t-if="field.readonly">X</t></td>
                        <td><t t-if="field.translate">X</t></td>
                        <td><t t-if="field.index">X</t></td>
                        <td colspan="4"><span t-field="field.modules"/></td>
                    </tr>
                    <tr>
                        <td colspan="20"><u><strong>Views</strong></u></td>
                    </tr>
                    <tr>
                        <td><strong>Seq</strong></td>
                        <td><strong>Type</strong></td>
                        <td colspan="4"><strong>Name</strong></td>
                        <td colspan="6"><strong>XML ID</strong></td>
                        <td colspan="8"><strong>Inherited</strong></td>
                    </tr>
                    <tr t-foreach="o.view_ids" t-as="view">
                        <td><span t-field="view.priority"/></td>
                        <td><span t-field="view.type"/></td>
                        <td colspan="4"><span t-field="view.name"/></td>
                        <td colspan="6"><span t-field="view.xml_id"/></td>
                        <td colspan="8" t-if="view.inherit_id.xml_id"><span t-field="view.inherit_id.xml_id"/></td>
                        <td colspan="8" t-if="not view.inherit_id.xml_id"><span t-field="view.inherit_id.name"/></td>
                    </tr>
                </table>
            </div>
        </t>
    </t>
</t>
', false, true, '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872', NULL);
INSERT INTO public.ir_ui_view VALUES (87, 16, NULL, 1, 1, 'ir.logging form', 'ir.logging', NULL, 'form', 'base/views/ir_logging_views.xml', 'primary', '{"en_US": "<form string=\"Log\">\n                <sheet>\n                    <group name=\"creation_details\" string=\"Creation details\">\n                        <field name=\"create_date\"/>\n                        <field name=\"create_uid\"/>\n                        <field name=\"dbname\"/>\n                    </group>\n                    <group name=\"log_details\" string=\"Logging details\">\n                        <field name=\"type\"/>\n                        <field name=\"name\"/>\n                        <field name=\"level\"/>\n                        <field name=\"path\"/>\n                        <field name=\"line\"/>\n                        <field name=\"func\"/>\n                        <field name=\"message\"/>\n                    </group>\n                </sheet>\n                </form>"}', '<?xml version="1.0"?>
