                    </group>
                    <group name="log_details" string="Logging details">
                        <field name="type"/>
                        <field name="name"/>
                        <field name="level"/>
                        <field name="path"/>
                        <field name="line"/>
                        <field name="func"/>
                        <field name="message"/>
                    </group>
                </sheet>
                </form>
            ', false, true, '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872', NULL);
