INSERT INTO public.ir_ui_view VALUES (90, 16, NULL, 1, 1, 'contact_name', NULL, 'base.contact_name', 'qweb', 'base/views/ir_qweb_widget_templates.xml', 'primary', '{"en_US": "<t t-name=\"base.contact_name\">\n    <div t-if=\"''name'' in fields\">\n        <t t-if=\"object.name\">\n            <span itemprop=\"name\" t-esc=\"name\"/>\n        </t>\n        <t t-if=\"not object.name and object.parent_name\">\n            <span itemprop=\"name\" t-esc=\"object.parent_name\"/>\n        </t>\n        <t t-if=\"options.get(''country_image'') and ''country_id'' in fields and object.country_id and object.country_id.image_url\">\n            <span t-field=\"object.country_id.image_url\" t-options=\"{&quot;widget&quot;: &quot;image_url&quot;, &quot;class&quot;: &quot;country_flag&quot;}\"/>\n        </t>\n    </div>\n</t>"}', '<?xml version="1.0"?>
<t t-name="base.contact_name">
    <div t-if="''name'' in fields">
        <t t-if="object.name">
            <span itemprop="name" t-esc="name"/>
        </t>
        <t t-if="not object.name and object.parent_name">
            <span itemprop="name" t-esc="object.parent_name"/>
        </t>
        <t t-if="options.get(''country_image'') and ''country_id'' in fields and object.country_id and object.country_id.image_url">
            <span t-field="object.country_id.image_url" t-options="{&quot;widget&quot;: &quot;image_url&quot;, &quot;class&quot;: &quot;country_flag&quot;}"/>
        </t>
    </div>
</t>

', false, true, '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872', NULL);
INSERT INTO public.ir_ui_view VALUES (91, 16, NULL, 1, 1, 'contact', NULL, 'base.contact', 'qweb', 'base/views/ir_qweb_widget_templates.xml', 'primary', '{"en_US": "<t t-name=\"base.contact\">\n    <address t-ignore=\"true\" class=\"o_portal_address mb-0\" itemscope=\"itemscope\" itemtype=\"http://schema.org/Organization\">\n        <div t-if=\"not ((''name'' in fields) or (address and ''address'' in fields) or (city and ''city'' in fields) or (mobile and ''mobile'' in fields) or (website and ''website'' in fields) or (email and ''email'' in fields))\" class=\"css_non_editable_mode_hidden\">\n            --<span class=\"text-muted\" t-esc=\"name\"/>--\n        </div>\n        <t t-if=\"object.country_id.name_position != ''after''\">\n            <t t-call=\"base.contact_name\"/>\n        </t>\n        <div class=\"gap-2\" itemprop=\"address\" itemscope=\"itemscope\" itemtype=\"http://schema.org/PostalAddress\">\n            <div t-if=\"address and ''address'' in fields\" t-attf-class=\"d-flex align-items-baseline gap-1\">\n                <i t-if=\"not options.get(''no_marker'')\" class=\"fa fa-map-marker fa-fw\" role=\"img\" aria-label=\"Address\" title=\"Address\"/>\n                <span class=\"d-block w-100 lh-sm\" itemprop=\"streetAddress\" t-esc=\"address\"/>\n            </div>\n            <div t-if=\"city and ''city'' in fields\" t-attf-class=\"d-flex align-items-baseline gap-1\">\n                <i t-if=\"not options.get(''no_marker'')\" class=\"fa fa-map-marker fa-fw\" role=\"img\" aria-label=\"Address\" title=\"Address\"/>\n                <span>\n                    <div>\n                        <span itemprop=\"addressLocality\" t-esc=\"city\"/>,\n                        <span itemprop=\"addressCountry\" t-esc=\"country_id\"/>\n                    </div>\n                </span>\n            </div>\n            <div class=\"d-flex align-items-center gap-1\" t-if=\"phone and ''phone'' in fields\">\n                <i t-if=\"not options.get(''no_marker'') or options.get(''phone_icons'')\" class=\"fa fa-phone fa-fw\" role=\"img\" aria-label=\"Phone\" title=\"Phone\"/> <span class=\"o_force_ltr\" itemprop=\"telephone\" t-esc=\"phone\"/>\n            </div>\n            <div class=\"d-flex align-items-center gap-1\" t-if=\"mobile and ''mobile'' in fields\">\n                <i t-if=\"not options.get(''no_marker'') or options.get(''phone_icons'')\" class=\"fa fa-mobile fa-fw\" role=\"img\" aria-label=\"Mobile\" title=\"Mobile\"/> <span class=\"o_force_ltr\" itemprop=\"telephone\" t-esc=\"mobile\"/>\n            </div>\n            <!-- Prevent issue with iOS Safari parsing of schema data without telephone itemprops -->\n            <div t-if=\"not (phone and ''phone'' in fields) and not (mobile and ''mobile'' in fields)\" itemprop=\"telephone\"/>\n            <div class=\"d-flex align-items-center gap-1\" t-if=\"website and ''website'' in fields\">\n                <i t-if=\"not options.get(''no_marker'')\" class=\"fa fa-globe fa-fw\" role=\"img\" aria-label=\"Website\" title=\"Website\"/>\n                <a t-att-href=\"website and ''%s%s'' % (''http://'' if ''://'' not in website else '''',website)\"><span itemprop=\"website\" t-esc=\"website\"/></a>\n            </div>\n            <div class=\"d-flex align-items-center gap-1\" t-if=\"email and ''email'' in fields\"><i t-if=\"not options.get(''no_marker'')\" class=\"fa fa-envelope fa-fw\" role=\"img\" aria-label=\"Email\" title=\"Email\"/> <span class=\"text-break\" itemprop=\"email\" t-esc=\"email\"/></div>\n        </div>\n        <div t-if=\"vat and ''vat'' in fields\"><span t-esc=\"vat_label\"/>: <span itemprop=\"vatID\" t-esc=\"vat\"/></div>\n        <t t-if=\"object.country_id and object.country_id.name_position == ''after''\">\n            <t t-call=\"base.contact_name\"/>\n        </t>\n    </address>\n</t>"}', '<?xml version="1.0"?>
<t t-name="base.contact">
    <address t-ignore="true" class="o_portal_address mb-0" itemscope="itemscope" itemtype="http://schema.org/Organization">
        <div t-if="not ((''name'' in fields) or (address and ''address'' in fields) or (city and ''city'' in fields) or (mobile and ''mobile'' in fields) or (website and ''website'' in fields) or (email and ''email'' in fields))" class="css_non_editable_mode_hidden">
            --<span class="text-muted" t-esc="name"/>--
        </div>
        <t t-if="object.country_id.name_position != ''after''">
            <t t-call="base.contact_name"/>
        </t>
        <div class="gap-2" itemprop="address" itemscope="itemscope" itemtype="http://schema.org/PostalAddress">
            <div t-if="address and ''address'' in fields" t-attf-class="d-flex align-items-baseline gap-1">
                <i t-if="not options.get(''no_marker'')" class="fa fa-map-marker fa-fw" role="img" aria-label="Address" title="Address"/>
                <span class="d-block w-100 lh-sm" itemprop="streetAddress" t-esc="address"/>
            </div>
            <div t-if="city and ''city'' in fields" t-attf-class="d-flex align-items-baseline gap-1">
                <i t-if="not options.get(''no_marker'')" class="fa fa-map-marker fa-fw" role="img" aria-label="Address" title="Address"/>
                <span>
                    <div>
                        <span itemprop="addressLocality" t-esc="city"/>,
                        <span itemprop="addressCountry" t-esc="country_id"/>
                    </div>
                </span>
            </div>
            <div class="d-flex align-items-center gap-1" t-if="phone and ''phone'' in fields">
                <i t-if="not options.get(''no_marker'') or options.get(''phone_icons'')" class="fa fa-phone fa-fw" role="img" aria-label="Phone" title="Phone"/> <span class="o_force_ltr" itemprop="telephone" t-esc="phone"/>
            </div>
            <div class="d-flex align-items-center gap-1" t-if="mobile and ''mobile'' in fields">
                <i t-if="not options.get(''no_marker'') or options.get(''phone_icons'')" class="fa fa-mobile fa-fw" role="img" aria-label="Mobile" title="Mobile"/> <span class="o_force_ltr" itemprop="telephone" t-esc="mobile"/>
            </div>
            <!-- Prevent issue with iOS Safari parsing of schema data without telephone itemprops -->
            <div t-if="not (phone and ''phone'' in fields) and not (mobile and ''mobile'' in fields)" itemprop="telephone"/>
            <div class="d-flex align-items-center gap-1" t-if="website and ''website'' in fields">
                <i t-if="not options.get(''no_marker'')" class="fa fa-globe fa-fw" role="img" aria-label="Website" title="Website"/>
                <a t-att-href="website and ''%s%s'' % (''http://'' if ''://'' not in website else '''',website)"><span itemprop="website" t-esc="website"/></a>
            </div>
            <div class="d-flex align-items-center gap-1" t-if="email and ''email'' in fields"><i t-if="not options.get(''no_marker'')" class="fa fa-envelope fa-fw" role="img" aria-label="Email" title="Email"/> <span class="text-break" itemprop="email" t-esc="email"/></div>
        </div>
        <div t-if="vat and ''vat'' in fields"><span t-esc="vat_label"/>: <span itemprop="vatID" t-esc="vat"/></div>
        <t t-if="object.country_id and object.country_id.name_position == ''after''">
            <t t-call="base.contact_name"/>
        </t>
    </address>
</t>

', false, true, '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872', NULL);
INSERT INTO public.ir_ui_view VALUES (92, 16, NULL, 1, 1, 'no_contact', NULL, 'base.no_contact', 'qweb', 'base/views/ir_qweb_widget_templates.xml', 'primary', '{"en_US": "<t t-name=\"base.no_contact\">\n    <address t-ignore=\"true\" class=\"mb-0\" itemscope=\"itemscope\" itemtype=\"http://schema.org/Organization\">\n        <div itemprop=\"address\" itemscope=\"itemscope\" itemtype=\"http://schema.org/PostalAddress\">\n            <div class=\"d-flex align-items-baseline\">\n                <i t-if=\"not options.get(''no_marker'')\" class=\"fa fa-map-marker fa-fw\" role=\"img\" aria-label=\"Address\" title=\"Address\"/>\n                <span class=\"w-100 o_force_ltr d-block\" t-out=\"options.get(''null_text'')\"/>\n            </div>\n        </div>\n    </address>\n</t>"}', '<?xml version="1.0"?>
<t t-name="base.no_contact">
    <address t-ignore="true" class="mb-0" itemscope="itemscope" itemtype="http://schema.org/Organization">
        <div itemprop="address" itemscope="itemscope" itemtype="http://schema.org/PostalAddress">
            <div class="d-flex align-items-baseline">
                <i t-if="not options.get(''no_marker'')" class="fa fa-map-marker fa-fw" role="img" aria-label="Address" title="Address"/>
                <span class="w-100 o_force_ltr d-block" t-out="options.get(''null_text'')"/>
            </div>
        </div>
    </address>
</t>

', false, true, '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872', NULL);
INSERT INTO public.ir_ui_view VALUES (93, 16, NULL, 1, 1, 'ir.module.category.form', 'ir.module.category', NULL, 'form', 'base/views/ir_module_views.xml', 'primary', '{"en_US": "<form string=\"Module Category\">\n                    <group col=\"4\">\n                        <field name=\"name\"/>\n                        <field name=\"parent_id\"/>\n                        <field name=\"sequence\"/>\n                    </group>\n                    <field name=\"description\"/>\n                </form>"}', '<?xml version="1.0"?>
<form string="Module Category">
                    <group col="4">
                        <field name="name"/>
                        <field name="parent_id"/>
                        <field name="sequence"/>
                    </group>
                    <field name="description"/>
                </form>
            ', false, true, '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872', NULL);
INSERT INTO public.ir_ui_view VALUES (94, 16, NULL, 1, 1, 'ir.module.module.list.select', 'ir.module.module', NULL, 'search', 'base/views/ir_module_views.xml', 'primary', '{"en_US": "<search string=\"Search modules\">\n                    <field name=\"name\" filter_domain=\"[''|'', ''|'', (''summary'', ''ilike'', self), (''shortdesc'', ''ilike'', self), (''name'',                         ''ilike'', self)]\" string=\"Module\"/>\n                    <filter name=\"app\" string=\"Apps\" domain=\"[(''application'', ''='', True)]\"/>\n                    <filter name=\"extra\" string=\"Extra\" domain=\"[(''application'', ''='', False)]\"/>\n                    <separator/>\n                    <filter name=\"installed\" string=\"Installed\" domain=\"[(''state'', ''in'', [''installed'', ''to upgrade'', ''to remove''])]\"/>\n                    <filter name=\"not_installed\" string=\"Not Installed\" domain=\"[(''state'', ''in'', [''uninstalled'', ''uninstallable'', ''to install''])]\"/>\n                    <field name=\"category_id\"/>\n                    <group expand=\"0\" string=\"Group By\">\n                        <filter string=\"Author\" name=\"author\" domain=\"[]\" context=\"{''group_by'':''author''}\"/>\n                        <filter string=\"Category\" name=\"category\" domain=\"[]\" context=\"{''group_by'':''category_id''}\"/>\n                        <filter string=\"Status\" name=\"state\" domain=\"[]\" context=\"{''group_by'':''state''}\"/>\n                    </group>\n                    <searchpanel>\n                        <field name=\"category_id\" string=\"Categories\" enable_counters=\"1\"/>\n                    </searchpanel>\n               </search>"}', '<?xml version="1.0"?>
<search string="Search modules">
                    <field name="name" filter_domain="[''|'', ''|'', (''summary'', ''ilike'', self), (''shortdesc'', ''ilike'', self), (''name'',                         ''ilike'', self)]" string="Module"/>
                    <filter name="app" string="Apps" domain="[(''application'', ''='', True)]"/>
                    <filter name="extra" string="Extra" domain="[(''application'', ''='', False)]"/>
                    <separator/>
                    <filter name="installed" string="Installed" domain="[(''state'', ''in'', [''installed'', ''to upgrade'', ''to remove''])]"/>
                    <filter name="not_installed" string="Not Installed" domain="[(''state'', ''in'', [''uninstalled'', ''uninstallable'', ''to install''])]"/>
                    <field name="category_id"/>
                    <group expand="0" string="Group By">
                        <filter string="Author" name="author" domain="[]" context="{''group_by'':''author''}"/>
                        <filter string="Category" name="category" domain="[]" context="{''group_by'':''category_id''}"/>
                        <filter string="Status" name="state" domain="[]" context="{''group_by'':''state''}"/>
                    </group>
                    <searchpanel>
                        <field name="category_id" string="Categories" enable_counters="1"/>
                    </searchpanel>
               </search>
            ', false, true, '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872', NULL);
INSERT INTO public.ir_ui_view VALUES (95, 16, NULL, 1, 1, 'ir.module.module.form', 'ir.module.module', NULL, 'form', 'base/views/ir_module_views.xml', 'primary', '{"en_US": "<form create=\"0\" edit=\"0\" string=\"Module\" class=\"o_module_form\">\n                    <link rel=\"stylesheet\" href=\"/base/static/src/css/description.css\"/>\n                    <sheet>\n                    <field name=\"icon_image\" widget=\"image\" class=\"oe_avatar\"/>\n                    <div class=\"mb32\">\n                        <h1 class=\"d-flex flex-column\">\n                            <field name=\"shortdesc\" placeholder=\"Module Name\"/>\n                            <field class=\"fs-2 text-muted\" name=\"summary\" invisible=\"not summary\"/>\n                        </h1>\n                        <h4 class=\"text-muted d-flex flex-column\">\n                            <div>By <field name=\"author\" class=\"oe_inline\" placeholder=\"Author Name\"/> </div>\n                            <small><field name=\"website\" widget=\"url\" invisible=\"not website\"/></small>\n                        </h4>\n\n                        <div>\n                            <field name=\"state\" invisible=\"1\"/>\n                            <field name=\"to_buy\" invisible=\"1\"/>\n                            <field name=\"has_iap\" invisible=\"1\"/>\n                            <button name=\"button_immediate_install\" string=\"Activate\" invisible=\"to_buy or state != ''uninstalled''\" type=\"object\" class=\"btn btn-primary me-1\" groups=\"base.group_system\"/>\n                            <a href=\"https://odoo.com/pricing?utm_source=db&amp;utm_medium=module#hosting=on_premise\" target=\"_blank\" class=\"btn btn-primary me-1\" invisible=\"not to_buy or state not in (''uninstalled'', ''uninstallable'')\" role=\"button\">Upgrade</a>\n                            <button name=\"button_immediate_upgrade\" invisible=\"state != ''installed''\" string=\"Upgrade\" type=\"object\" class=\"btn btn-primary me-1\" groups=\"base.group_system\"/>\n                            <button name=\"button_uninstall_wizard\" invisible=\"state != ''installed''\" string=\"Uninstall\" type=\"object\" class=\"btn btn-secondary me-1\" groups=\"base.group_system\"/>\n                            <button name=\"button_uninstall_cancel\" invisible=\"state != ''to remove''\" string=\"Cancel Uninstall\" type=\"object\" class=\"btn btn-secondary me-1\" groups=\"base.group_system\"/>\n                            <button name=\"button_upgrade_cancel\" invisible=\"state != ''to upgrade''\" string=\"Cancel Upgrade\" type=\"object\" class=\"btn btn-secondary me-1\" groups=\"base.group_system\"/>\n                            <button name=\"button_install_cancel\" invisible=\"state != ''to install''\" string=\"Cancel Install\" type=\"object\" class=\"btn btn-secondary me-1\" groups=\"base.group_system\"/>\n                        </div>\n                        <h6 class=\"text-muted mt-2\" invisible=\"not has_iap\">Contains In-App Purchases</h6>\n                    </div>\n                    <div class=\"clearfix\"/>\n                    <notebook groups=\"base.group_no_one\">\n                        <page string=\"Information\" name=\"information\">\n                            <group>\n                                <group>\n                                    <field name=\"category_id\" options=\"{''no_open'': True, ''no_create'': True}\"/>\n                                    <field name=\"name\"/>\n                                    <field name=\"license\"/>\n                                    <field name=\"installed_version\"/>\n                                </group>\n                            </group>\n                        </page>\n                        <page string=\"Technical Data\" name=\"technical_data\">\n                            <group col=\"4\">\n                                <field name=\"demo\"/>\n                                <field name=\"application\"/>\n                                <field name=\"state\"/>\n                            </group>\n                            <group>\n                                <group string=\"Dependencies\">\n                                    <field name=\"dependencies_id\" colspan=\"2\" nolabel=\"1\">\n                                        <tree string=\"Dependencies\">\n                                            <field name=\"name\"/>\n                                            <field name=\"state\"/>\n                                        </tree>\n                                    </field>\n                                </group>\n                                <group string=\"Exclusions\">\n                                    <field name=\"exclusion_ids\" colspan=\"2\" nolabel=\"1\">\n                                        <tree string=\"Exclusions\">\n                                            <field name=\"name\"/>\n                                            <field name=\"state\"/>\n                                        </tree>\n                                    </field>\n                                </group>\n                            </group>\n                        </page>\n                        <page string=\"Installed Features\" name=\"installed_features\" invisible=\"state != ''installed''\">\n                            <group string=\"Created Menus\"/>\n                            <field name=\"menus_by_module\"/>\n                            <group string=\"Created Views\"/>\n                            <field name=\"views_by_module\"/>\n                            <group string=\"Defined Reports\"/>\n                            <field name=\"reports_by_module\"/>\n                        </page>\n                    </notebook>\n                    <field name=\"description_html\" class=\"oe_styling_v8\" invisible=\"not description_html\"/>\n                    </sheet>\n                </form>"}', '<?xml version="1.0"?>
<form create="0" edit="0" string="Module" class="o_module_form">
                    <link rel="stylesheet" href="/base/static/src/css/description.css"/>
                    <sheet>
                    <field name="icon_image" widget="image" class="oe_avatar"/>
                    <div class="mb32">
                        <h1 class="d-flex flex-column">
                            <field name="shortdesc" placeholder="Module Name"/>
                            <field class="fs-2 text-muted" name="summary" invisible="not summary"/>
                        </h1>
                        <h4 class="text-muted d-flex flex-column">
                            <div>By <field name="author" class="oe_inline" placeholder="Author Name"/> </div>
                            <small><field name="website" widget="url" invisible="not website"/></small>
                        </h4>

                        <div>
                            <field name="state" invisible="1"/>
                            <field name="to_buy" invisible="1"/>
                            <field name="has_iap" invisible="1"/>
                            <button name="button_immediate_install" string="Activate" invisible="to_buy or state != ''uninstalled''" type="object" class="btn btn-primary me-1" groups="base.group_system"/>
                            <a href="https://odoo.com/pricing?utm_source=db&amp;utm_medium=module#hosting=on_premise" target="_blank" class="btn btn-primary me-1" invisible="not to_buy or state not in (''uninstalled'', ''uninstallable'')" role="button">Upgrade</a>
                            <button name="button_immediate_upgrade" invisible="state != ''installed''" string="Upgrade" type="object" class="btn btn-primary me-1" groups="base.group_system"/>
                            <button name="button_uninstall_wizard" invisible="state != ''installed''" string="Uninstall" type="object" class="btn btn-secondary me-1" groups="base.group_system"/>
                            <button name="button_uninstall_cancel" invisible="state != ''to remove''" string="Cancel Uninstall" type="object" class="btn btn-secondary me-1" groups="base.group_system"/>
                            <button name="button_upgrade_cancel" invisible="state != ''to upgrade''" string="Cancel Upgrade" type="object" class="btn btn-secondary me-1" groups="base.group_system"/>
                            <button name="button_install_cancel" invisible="state != ''to install''" string="Cancel Install" type="object" class="btn btn-secondary me-1" groups="base.group_system"/>
                        </div>
                        <h6 class="text-muted mt-2" invisible="not has_iap">Contains In-App Purchases</h6>
                    </div>
                    <div class="clearfix"/>
                    <notebook groups="base.group_no_one">
                        <page string="Information" name="information">
                            <group>
                                <group>
                                    <field name="category_id" options="{''no_open'': True, ''no_create'': True}"/>
                                    <field name="name"/>
                                    <field name="license"/>
                                    <field name="installed_version"/>
                                </group>
                            </group>
                        </page>
                        <page string="Technical Data" name="technical_data">
                            <group col="4">
                                <field name="demo"/>
                                <field name="application"/>
                                <field name="state"/>
                            </group>
                            <group>
                                <group string="Dependencies">
                                    <field name="dependencies_id" colspan="2" nolabel="1">
                                        <tree string="Dependencies">
                                            <field name="name"/>
                                            <field name="state"/>
                                        </tree>
                                    </field>
                                </group>
                                <group string="Exclusions">
                                    <field name="exclusion_ids" colspan="2" nolabel="1">
                                        <tree string="Exclusions">
                                            <field name="name"/>
                                            <field name="state"/>
                                        </tree>
                                    </field>
                                </group>
                            </group>
                        </page>
                        <page string="Installed Features" name="installed_features" invisible="state != ''installed''">
                            <group string="Created Menus"/>
                            <field name="menus_by_module"/>
                            <group string="Created Views"/>
                            <field name="views_by_module"/>
                            <group string="Defined Reports"/>
                            <field name="reports_by_module"/>
                        </page>
                    </notebook>
                    <field name="description_html" class="oe_styling_v8" invisible="not description_html"/>
                    </sheet>
                </form>
            ', false, true, '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872', NULL);
INSERT INTO public.ir_ui_view VALUES (96, 16, NULL, 1, 1, 'ir.module.module.tree', 'ir.module.module', NULL, 'tree', 'base/views/ir_module_views.xml', 'primary', '{"en_US": "<tree create=\"false\" string=\"Apps\" decoration-info=\"state == ''uninstalled''\" decoration-muted=\"state == ''uninstallable''\">\n                    <header>\n                        <button name=\"button_immediate_install\" type=\"object\" string=\"Activate\" groups=\"base.group_system\"/>\n                        <button name=\"button_immediate_upgrade\" type=\"object\" string=\"Upgrade\" groups=\"base.group_system\"/>\n                    </header>\n                    <field name=\"shortdesc\"/>\n                    <field name=\"name\" groups=\"base.group_no_one\"/>\n                    <field name=\"author\"/>\n                    <field name=\"website\"/>\n                    <field name=\"installed_version\"/>\n                    <field name=\"state\" widget=\"badge\" decoration-muted=\"state == ''uninstallable''\" decoration-info=\"state  == ''uninstalled''\" decoration-success=\"state == ''installed''\"/>\n                    <field name=\"category_id\" column_invisible=\"True\"/>\n                </tree>"}', '<?xml version="1.0"?>
<tree create="false" string="Apps" decoration-info="state == ''uninstalled''" decoration-muted="state == ''uninstallable''">
                    <header>
                        <button name="button_immediate_install" type="object" string="Activate" groups="base.group_system"/>
                        <button name="button_immediate_upgrade" type="object" string="Upgrade" groups="base.group_system"/>
                    </header>
                    <field name="shortdesc"/>
                    <field name="name" groups="base.group_no_one"/>
                    <field name="author"/>
                    <field name="website"/>
                    <field name="installed_version"/>
                    <field name="state" widget="badge" decoration-muted="state == ''uninstallable''" decoration-info="state  == ''uninstalled''" decoration-success="state == ''installed''"/>
                    <field name="category_id" column_invisible="True"/>
                </tree>
            ', false, true, '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872', NULL);
INSERT INTO public.ir_ui_view VALUES (97, 16, NULL, 1, 1, 'Apps Kanban', 'ir.module.module', NULL, 'kanban', 'base/views/ir_module_views.xml', 'primary', '{"en_US": "<kanban create=\"false\" class=\"o_modules_kanban\">\n                  <field name=\"icon\"/>\n                  <field name=\"icon_flag\"/>\n                  <field name=\"to_buy\"/>\n                  <field name=\"name\"/>\n                  <field name=\"state\"/>\n                  <field name=\"summary\"/>\n                  <field name=\"website\"/>\n                  <field name=\"application\"/>\n                  <templates>\n                    <t t-name=\"kanban-menu\">\n                        <t t-set=\"installed\" t-value=\"record.state.raw_value == ''installed''\"/>\n                        <a type=\"edit\" class=\"dropdown-item\">Module Info</a>\n                        <a t-if=\"record.website.raw_value\" role=\"menuitem\" class=\"dropdown-item o-hidden-ios\" t-att-href=\"record.website.raw_value\" target=\"_blank\">Learn More</a>\n                        <a t-if=\"installed\" name=\"button_immediate_upgrade\" type=\"object\" role=\"menuitem\" class=\"dropdown-item\" groups=\"base.group_system\">Upgrade</a>\n                        <a t-if=\"installed\" name=\"button_uninstall_wizard\" type=\"object\" role=\"menuitem\" class=\"dropdown-item\" groups=\"base.group_system\">Uninstall</a>\n                    </t>\n                    <t t-name=\"kanban-box\">\n                      <div class=\"oe_module_vignette\">\n                        <div class=\"oe_module_icon\">\n                            <img t-attf-src=\"#{record.icon.value}\" class=\"w-100\" alt=\"Icon\"/>\n                            <span t-if=\"record.icon_flag\" class=\"oe_module_flag\"><t t-out=\"record.icon_flag.raw_value\"/></span>\n                        </div>\n                        <div class=\"oe_module_desc\" t-att-title=\"record.shortdesc.value\">\n                          <h4 class=\"o_kanban_record_title\">\n                            <field name=\"shortdesc\"/>&amp;nbsp;\n                          </h4>\n                          <p class=\"oe_module_name\">\n                            <field groups=\"!base.group_no_one\" name=\"summary\"/>\n                            <code groups=\"base.group_no_one\"><field name=\"name\"/></code>\n                          </p>\n                          <div class=\"oe_module_action d-flex flex-wrap justify-content-between\">\n                            <button type=\"object\" class=\"btn btn-primary btn-sm\" name=\"button_immediate_install\" invisible=\"state != ''uninstalled''\" t-if=\"! record.to_buy.raw_value\" groups=\"base.group_system\">Activate</button>\n                            <div t-if=\"installed\" class=\"d-flex align-items-center text-muted float-start\">Installed</div>\n                            <a t-att-href=\"record.website.raw_value\" target=\"_blank\" invisible=\"website in (False, '''')\" class=\"btn btn-sm btn-secondary float-end o-hidden-ios\" role=\"button\">Learn More</a>\n                            <a type=\"edit\" class=\"btn btn-secondary btn-sm float-end\" role=\"button\" invisible=\"website != ''''\">Module Info</a>\n                            <a href=\"https://odoo.com/pricing?utm_source=db&amp;utm_medium=module#hosting=on_premise\" target=\"_blank\" class=\"btn btn-info btn-sm\" invisible=\"state not in (''uninstalled'', ''uninstallable'')\" t-if=\"record.to_buy.raw_value\" role=\"button\" groups=\"base.group_system\">Upgrade</a>\n                            <button invisible=\"state != ''to remove''\" type=\"object\" class=\"btn btn-sm btn-primary\" name=\"button_uninstall_cancel\" groups=\"base.group_system\">Cancel Uninstall</button>\n                            <button invisible=\"state != ''to install''\" type=\"object\" class=\"btn btn-sm btn-primary\" name=\"button_install_cancel\" groups=\"base.group_system\">Cancel Install</button>\n                          </div>\n                        </div>\n                      </div>\n                    </t>\n                  </templates>\n                </kanban>"}', '<?xml version="1.0"?>
<kanban create="false" class="o_modules_kanban">
                  <field name="icon"/>
                  <field name="icon_flag"/>
                  <field name="to_buy"/>
                  <field name="name"/>
                  <field name="state"/>
                  <field name="summary"/>
                  <field name="website"/>
                  <field name="application"/>
                  <templates>
                    <t t-name="kanban-menu">
                        <t t-set="installed" t-value="record.state.raw_value == ''installed''"/>
                        <a type="edit" class="dropdown-item">Module Info</a>
                        <a t-if="record.website.raw_value" role="menuitem" class="dropdown-item o-hidden-ios" t-att-href="record.website.raw_value" target="_blank">Learn More</a>
                        <a t-if="installed" name="button_immediate_upgrade" type="object" role="menuitem" class="dropdown-item" groups="base.group_system">Upgrade</a>
                        <a t-if="installed" name="button_uninstall_wizard" type="object" role="menuitem" class="dropdown-item" groups="base.group_system">Uninstall</a>
                    </t>
                    <t t-name="kanban-box">
                      <div class="oe_module_vignette">
                        <div class="oe_module_icon">
                            <img t-attf-src="#{record.icon.value}" class="w-100" alt="Icon"/>
                            <span t-if="record.icon_flag" class="oe_module_flag"><t t-out="record.icon_flag.raw_value"/></span>
                        </div>
                        <div class="oe_module_desc" t-att-title="record.shortdesc.value">
                          <h4 class="o_kanban_record_title">
                            <field name="shortdesc"/>&amp;nbsp;
                          </h4>
                          <p class="oe_module_name">
                            <field groups="!base.group_no_one" name="summary"/>
                            <code groups="base.group_no_one"><field name="name"/></code>
                          </p>
                          <div class="oe_module_action d-flex flex-wrap justify-content-between">
                            <button type="object" class="btn btn-primary btn-sm" name="button_immediate_install" invisible="state != ''uninstalled''" t-if="! record.to_buy.raw_value" groups="base.group_system">Activate</button>
                            <div t-if="installed" class="d-flex align-items-center text-muted float-start">Installed</div>
                            <a t-att-href="record.website.raw_value" target="_blank" invisible="website in (False, '''')" class="btn btn-sm btn-secondary float-end o-hidden-ios" role="button">Learn More</a>
                            <a type="edit" class="btn btn-secondary btn-sm float-end" role="button" invisible="website != ''''">Module Info</a>
                            <a href="https://odoo.com/pricing?utm_source=db&amp;utm_medium=module#hosting=on_premise" target="_blank" class="btn btn-info btn-sm" invisible="state not in (''uninstalled'', ''uninstallable'')" t-if="record.to_buy.raw_value" role="button" groups="base.group_system">Upgrade</a>
                            <button invisible="state != ''to remove''" type="object" class="btn btn-sm btn-primary" name="button_uninstall_cancel" groups="base.group_system">Cancel Uninstall</button>
                            <button invisible="state != ''to install''" type="object" class="btn btn-sm btn-primary" name="button_install_cancel" groups="base.group_system">Cancel Install</button>
                          </div>
                        </div>
                      </div>
                    </t>
                  </templates>
                </kanban>
            ', false, true, '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872', NULL);
INSERT INTO public.ir_ui_view VALUES (98, 16, NULL, 1, 1, 'report_irmodulereference', NULL, 'base.report_irmodulereference', 'qweb', 'base/report/ir_module_report_templates.xml', 'primary', '{"en_US": "<t t-name=\"base.report_irmodulereference\">\n    <t t-call=\"web.html_container\">\n        <t t-foreach=\"docs\" t-as=\"o\">\n            <t t-call=\"web.internal_layout\">\n                <div class=\"page\">\n                    <h3 class=\"text-center\">Introspection report on objects</h3>\n                        <table class=\"table table-bordered mt32\">\n                            <thead>\n                                <tr>\n                                    <th class=\"text-center\"><span>Module</span></th>\n                                    <th class=\"text-center\"><span>Name</span></th>\n                                    <th class=\"text-center\"><span>Version</span></th>\n                                    <th class=\"text-center\"><span>Directory</span></th>\n                                    <th class=\"text-center\"><span>Web</span></th>\n                                </tr>\n                            </thead>\n                            <tbody>\n                                <tr class=\"text-center\">\n                                    <td><span t-field=\"o.name\"/></td>\n                                    <td><span t-field=\"o.shortdesc\"/></td>\n                                    <td><span t-field=\"o.latest_version\"/></td>\n                                    <td><span t-field=\"o.name\"/></td>\n                                    <td><span t-field=\"o.website\"/></td>\n                                </tr>\n                            </tbody>\n                        </table>\n                        <span t-field=\"o.description\"/>\n                        <div>\n                            <strong>Reports:</strong>\n                        </div>\n                        <span t-field=\"o.reports_by_module\"/>\n                        <div>\n                            <strong>Menu:</strong>\n                        </div>\n                        <span t-field=\"o.menus_by_module\"/>\n                        <div>\n                            <strong>View:</strong>\n                        </div>\n                        <span t-field=\"o.views_by_module\"/>\n                        <div>\n                            <strong>Dependencies:</strong>\n                        </div>\n                        <div t-foreach=\"o.dependencies_id\" t-as=\"dependency_id\">\n                            <span t-field=\"dependency_id.name\"/> - <span t-field=\"dependency_id.module_id.state\"/>\n                        </div>\n\n                        <table t-foreach=\"findobj(o)\" t-as=\"obj\" class=\"table table-sm mt16 mb32\">\n                            <tr>\n                                <th colspan=\"2\"><span>Object:</span> <span t-esc=\"obj.model\"/></th>\n                            </tr>\n                            <tr t-foreach=\"findfields(obj.model, o)\" t-as=\"field\">\n                                <td class=\"col-3\"><t t-esc=\"field[0]\"/></td>\n                                <td>\n                                    <span t-esc=\"field[1].get(''string'',''Unknown'')\"/><span>, </span><span t-esc=\"field[1].get(''type'')\"/><span t-if=\"field[1].get(''required'')\">, required</span><span t-if=\"field[1].get(''readonly'',False)\">, readonly</span>\n                                    <div t-esc=\"field[1].get(''help'', '''')\"/>\n                                </td>\n                            </tr>\n                        </table>\n                </div>\n            </t>\n        </t>\n    </t>\n</t>"}', '<?xml version="1.0"?>
<t t-name="base.report_irmodulereference">
    <t t-call="web.html_container">
        <t t-foreach="docs" t-as="o">
            <t t-call="web.internal_layout">
                <div class="page">
                    <h3 class="text-center">Introspection report on objects</h3>
                        <table class="table table-bordered mt32">
                            <thead>
                                <tr>
                                    <th class="text-center"><span>Module</span></th>
                                    <th class="text-center"><span>Name</span></th>
                                    <th class="text-center"><span>Version</span></th>
                                    <th class="text-center"><span>Directory</span></th>
                                    <th class="text-center"><span>Web</span></th>
                                </tr>
                            </thead>
                            <tbody>
                                <tr class="text-center">
                                    <td><span t-field="o.name"/></td>
                                    <td><span t-field="o.shortdesc"/></td>
                                    <td><span t-field="o.latest_version"/></td>
                                    <td><span t-field="o.name"/></td>
                                    <td><span t-field="o.website"/></td>
                                </tr>
                            </tbody>
                        </table>
                        <span t-field="o.description"/>
                        <div>
                            <strong>Reports:</strong>
                        </div>
                        <span t-field="o.reports_by_module"/>
                        <div>
                            <strong>Menu:</strong>
                        </div>
                        <span t-field="o.menus_by_module"/>
                        <div>
                            <strong>View:</strong>
                        </div>
                        <span t-field="o.views_by_module"/>
                        <div>
                            <strong>Dependencies:</strong>
                        </div>
                        <div t-foreach="o.dependencies_id" t-as="dependency_id">
                            <span t-field="dependency_id.name"/> - <span t-field="dependency_id.module_id.state"/>
                        </div>

                        <table t-foreach="findobj(o)" t-as="obj" class="table table-sm mt16 mb32">
                            <tr>
                                <th colspan="2"><span>Object:</span> <span t-esc="obj.model"/></th>
                            </tr>
                            <tr t-foreach="findfields(obj.model, o)" t-as="field">
                                <td class="col-3"><t t-esc="field[0]"/></td>
                                <td>
                                    <span t-esc="field[1].get(''string'',''Unknown'')"/><span>, </span><span t-esc="field[1].get(''type'')"/><span t-if="field[1].get(''required'')">, required</span><span t-if="field[1].get(''readonly'',False)">, readonly</span>
                                    <div t-esc="field[1].get(''help'', '''')"/>
                                </td>
                            </tr>
                        </table>
                </div>
            </t>
        </t>
    </t>
</t>
', false, true, '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872', NULL);
INSERT INTO public.ir_ui_view VALUES (109, 16, NULL, 1, 1, 'Demo Failure Form', 'ir.demo_failure', NULL, 'form', 'base/data/ir_demo_failure_data.xml', 'primary', '{"en_US": "<form>\n                <sheet>\n                    <group>\n                        <group>\n                            <field name=\"module_id\"/>\n                            <field name=\"wizard_id\"/>\n                        </group>\n                        <group>\n                            <field name=\"error\"/>\n                        </group>\n                    </group>\n                </sheet>\n            </form>"}', '<?xml version="1.0"?>
<form>
                <sheet>
                    <group>
                        <group>
                            <field name="module_id"/>
                            <field name="wizard_id"/>
                        </group>
                        <group>
                            <field name="error"/>
                        </group>
                    </group>
                </sheet>
            </form>
        ', false, true, '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872', NULL);
INSERT INTO public.ir_ui_view VALUES (99, 16, NULL, 1, 1, 'Module Update', 'base.module.update', NULL, 'form', 'base/wizard/base_module_update_views.xml', 'primary', '{"en_US": "<form string=\"Update Module List\">\n                    <field name=\"state\" invisible=\"1\"/>\n                    <separator string=\"Module Update Result\" invisible=\"state != ''done''\"/>\n                    <group invisible=\"state != ''init''\">\n                        <span class=\"o_form_label\" colspan=\"2\">Click on Update below to start the process...</span>\n                    </group>\n                    <group invisible=\"state != ''done''\">\n                        <field name=\"updated\"/>\n                        <field name=\"added\"/>\n                    </group>\n                    <footer>\n                        <div invisible=\"state != ''init''\" class=\"d-flex gap-1\">\n                            <button name=\"update_module\" string=\"Update\" type=\"object\" class=\"btn-primary\" data-hotkey=\"q\"/>\n                            <button special=\"cancel\" data-hotkey=\"x\" string=\"Cancel\" class=\"btn-secondary\"/>\n                        </div>\n                        <div invisible=\"state != ''done''\" class=\"d-flex gap-1\">\n                            <button name=\"action_module_open\" string=\"Open Apps\" type=\"object\" class=\"btn-primary\" data-hotkey=\"q\"/>\n                            <button special=\"cancel\" data-hotkey=\"x\" string=\"Close\" class=\"btn-secondary\"/>\n                        </div>\n                    </footer>\n                </form>"}', '<?xml version="1.0"?>
<form string="Update Module List">
                    <field name="state" invisible="1"/>
                    <separator string="Module Update Result" invisible="state != ''done''"/>
                    <group invisible="state != ''init''">
                        <span class="o_form_label" colspan="2">Click on Update below to start the process...</span>
                    </group>
                    <group invisible="state != ''done''">
                        <field name="updated"/>
                        <field name="added"/>
                    </group>
                    <footer>
                        <div invisible="state != ''init''" class="d-flex gap-1">
                            <button name="update_module" string="Update" type="object" class="btn-primary" data-hotkey="q"/>
                            <button special="cancel" data-hotkey="x" string="Cancel" class="btn-secondary"/>
                        </div>
                        <div invisible="state != ''done''" class="d-flex gap-1">
                            <button name="action_module_open" string="Open Apps" type="object" class="btn-primary" data-hotkey="q"/>
                            <button special="cancel" data-hotkey="x" string="Close" class="btn-secondary"/>
                        </div>
                    </footer>
                </form>
            ', false, true, '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872', NULL);
INSERT INTO public.ir_ui_view VALUES (100, 100, NULL, 1, 1, 'Switch to language', 'base.language.install', NULL, 'form', 'base/wizard/base_language_install_views.xml', 'primary', '{"en_US": "<form string=\"Switch to language\">\n                    <div>\n                        <strong>\n                            <field name=\"first_lang_id\" readonly=\"True\" options=\"{''no_open'': True}\"/>\n                        </strong>\n                        has been successfully installed.\n                            Users can choose their favorite language in their preferences.\n                    </div>\n                    <footer>\n                        <button name=\"reload\" string=\"Close\" type=\"object\" class=\"btn-primary\" data-hotkey=\"q\"/>\n                        <button name=\"switch_lang\" type=\"object\" class=\"btn-primary ms-1\" data-hotkey=\"w\">\n                            Switch to <field name=\"first_lang_id\" readonly=\"True\" options=\"{''no_open'': True}\"/> &amp; Close\n                        </button>\n                    </footer>\n                </form>"}', '<?xml version="1.0"?>
<form string="Switch to language">
                    <div>
                        <strong>
                            <field name="first_lang_id" readonly="True" options="{''no_open'': True}"/>
                        </strong>
                        has been successfully installed.
                            Users can choose their favorite language in their preferences.
                    </div>
                    <footer>
                        <button name="reload" string="Close" type="object" class="btn-primary" data-hotkey="q"/>
                        <button name="switch_lang" type="object" class="btn-primary ms-1" data-hotkey="w">
                            Switch to <field name="first_lang_id" readonly="True" options="{''no_open'': True}"/> &amp; Close
                        </button>
                    </footer>
                </form>
           ', false, true, '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872', NULL);
INSERT INTO public.ir_ui_view VALUES (101, 16, NULL, 1, 1, 'Load a Translation', 'base.language.install', NULL, 'form', 'base/wizard/base_language_install_views.xml', 'primary', '{"en_US": "<form string=\"Load a Translation\">\n                    <group>\n                        <field name=\"lang_ids\" widget=\"many2many_tags\" context=\"{''active_test'': False}\" options=\"{''no_quick_create'': True, ''no_create_edit'': True}\"/>\n                        <field name=\"overwrite\" groups=\"base.group_no_one\"/>\n                    </group>\n                    <footer>\n                        <button name=\"lang_install\" string=\"Add\" data-hotkey=\"q\" type=\"object\" class=\"btn-primary\"/>\n                        <button special=\"cancel\" data-hotkey=\"x\" string=\"Cancel\" class=\"btn-secondary\"/>\n                    </footer>\n                </form>"}', '<?xml version="1.0"?>
<form string="Load a Translation">
                    <group>
                        <field name="lang_ids" widget="many2many_tags" context="{''active_test'': False}" options="{''no_quick_create'': True, ''no_create_edit'': True}"/>
                        <field name="overwrite" groups="base.group_no_one"/>
                    </group>
                    <footer>
                        <button name="lang_install" string="Add" data-hotkey="q" type="object" class="btn-primary"/>
                        <button special="cancel" data-hotkey="x" string="Cancel" class="btn-secondary"/>
                    </footer>
                </form>
           ', false, true, '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872', NULL);
INSERT INTO public.ir_ui_view VALUES (102, 16, NULL, 1, 1, 'Import Translation', 'base.language.import', NULL, 'form', 'base/wizard/base_import_language_views.xml', 'primary', '{"en_US": "<form string=\"Import Translation\">\n                    <group>\n                        <field name=\"name\" placeholder=\"e.g. English\"/>\n                        <field name=\"code\" string=\"Code\" placeholder=\"e.g. en_US\"/>\n                        <field name=\"data\" filename=\"filename\" options=\"{''accepted_file_extensions'': ''.csv,.po''}\"/>\n                        <field name=\"filename\" invisible=\"1\"/>\n                        <field name=\"overwrite\" groups=\"base.group_no_one\"/>\n                    </group>\n                    <footer>\n                        <button name=\"import_lang\" string=\"Import\" type=\"object\" class=\"btn-primary\" data-hotkey=\"q\"/>\n                        <button string=\"Cancel\" class=\"btn-secondary\" special=\"cancel\" data-hotkey=\"x\"/>\n                    </footer>\n                </form>"}', '<?xml version="1.0"?>
<form string="Import Translation">
                    <group>
                        <field name="name" placeholder="e.g. English"/>
                        <field name="code" string="Code" placeholder="e.g. en_US"/>
                        <field name="data" filename="filename" options="{''accepted_file_extensions'': ''.csv,.po''}"/>
                        <field name="filename" invisible="1"/>
                        <field name="overwrite" groups="base.group_no_one"/>
                    </group>
                    <footer>
                        <button name="import_lang" string="Import" type="object" class="btn-primary" data-hotkey="q"/>
                        <button string="Cancel" class="btn-secondary" special="cancel" data-hotkey="x"/>
                    </footer>
                </form>
            ', false, true, '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872', NULL);
INSERT INTO public.ir_ui_view VALUES (110, 16, NULL, 1, 1, 'IR Profile Search', 'ir.profile', NULL, 'search', 'base/views/ir_profile_views.xml', 'primary', '{"en_US": "<search>\n                <field name=\"name\" string=\"Name\"/>\n                <field name=\"session\" string=\"Session\"/>\n                <filter name=\"group_session\" string=\"Session\" context=\"{''group_by'':''session''}\"/>\n            </search>"}', '<?xml version="1.0"?>
<search>
                <field name="name" string="Name"/>
                <field name="session" string="Session"/>
                <filter name="group_session" string="Session" context="{''group_by'':''session''}"/>
            </search>
        ', false, true, '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872', NULL);
INSERT INTO public.ir_ui_view VALUES (103, 16, NULL, 1, 1, 'Module Upgrade', 'base.module.upgrade', NULL, 'form', 'base/wizard/base_module_upgrade_views.xml', 'primary', '{"en_US": "<form string=\"System Update\">\n                    <p>This module will trigger the uninstallation of below modules.</p>\n                    <p><strong>This operation will permanently erase all data currently stored by the modules!</strong></p>\n                    <p>If you wish to cancel the process, press the cancel button below</p>\n                    <separator string=\"Impacted Apps\"/>\n                    <field name=\"module_info\"/>\n                    <footer>\n                        <button name=\"upgrade_module\" string=\"Confirm\" type=\"object\" class=\"btn-primary\" data-hotkey=\"q\"/>\n                        <button string=\"Cancel\" class=\"btn-secondary\" name=\"upgrade_module_cancel\" type=\"object\" data-hotkey=\"x\"/>\n                    </footer>\n                </form>"}', '<?xml version="1.0"?>
<form string="System Update">
                    <p>This module will trigger the uninstallation of below modules.</p>
                    <p><strong>This operation will permanently erase all data currently stored by the modules!</strong></p>
                    <p>If you wish to cancel the process, press the cancel button below</p>
                    <separator string="Impacted Apps"/>
                    <field name="module_info"/>
                    <footer>
                        <button name="upgrade_module" string="Confirm" type="object" class="btn-primary" data-hotkey="q"/>
                        <button string="Cancel" class="btn-secondary" name="upgrade_module_cancel" type="object" data-hotkey="x"/>
                    </footer>
                </form>
            ', false, true, '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872', NULL);
INSERT INTO public.ir_ui_view VALUES (104, 20, NULL, 1, 1, 'Module Upgrade Install', 'base.module.upgrade', NULL, 'form', 'base/wizard/base_module_upgrade_views.xml', 'primary', '{"en_US": "<form string=\"Apply Schedule Upgrade\">\n                    <div><span class=\"o_form_label\">The selected modules have been updated/installed!</span></div>\n                    <div><span class=\"o_form_label\">We suggest to reload the menu tab to see the new menus (Ctrl+T then Ctrl+R).\"</span></div>\n                    <footer>\n                        <button name=\"config\" string=\"Start configuration\" type=\"object\" class=\"btn-primary\" data-hotkey=\"q\"/>\n                        <button string=\"Cancel\" class=\"btn-secondary\" special=\"cancel\" data-hotkey=\"x\"/>\n                    </footer>\n                </form>"}', '<?xml version="1.0"?>
<form string="Apply Schedule Upgrade">
                    <div><span class="o_form_label">The selected modules have been updated/installed!</span></div>
                    <div><span class="o_form_label">We suggest to reload the menu tab to see the new menus (Ctrl+T then Ctrl+R)."</span></div>
                    <footer>
                        <button name="config" string="Start configuration" type="object" class="btn-primary" data-hotkey="q"/>
                        <button string="Cancel" class="btn-secondary" special="cancel" data-hotkey="x"/>
                    </footer>
                </form>
            ', false, true, '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872', NULL);
INSERT INTO public.ir_ui_view VALUES (105, 16, NULL, 1, 1, 'Uninstall module', 'base.module.uninstall', NULL, 'form', 'base/wizard/base_module_uninstall_views.xml', 'primary', '{"en_US": "<form string=\"Uninstall module\">\n                    <div class=\"alert alert-warning oe_button_box\" role=\"alert\">\n                        <p class=\"mt-3\">\n                            Uninstalling modules can be risky, we recommend you to try it on a duplicate or test database first.\n                        </p>\n                    </div>\n                    <field name=\"module_id\" invisible=\"1\"/>\n                    <div class=\"d-flex bd-highlight\">\n                        <div class=\"me-auto p-2 bd-highlight\"><h3>Apps to Uninstall</h3></div>\n                        <div class=\"p-2 bd-highlight\"><field name=\"show_all\"/> Show All</div>\n                    </div>\n                    <field name=\"module_ids\" mode=\"kanban\" class=\"o_modules_field\">\n                        <kanban create=\"false\" class=\"o_modules_kanban\">\n                            <field name=\"icon\"/>\n                            <field name=\"state\"/>\n                            <field name=\"summary\"/>\n                                <templates>\n                                    <t t-name=\"kanban-box\">\n                                        <div class=\"oe_module_vignette\">\n                                            <t t-set=\"installed\" t-value=\"record.state.raw_value == ''installed''\"/>\n                                            <img t-attf-src=\"#{record.icon.value}\" class=\"oe_module_icon\" alt=\"Icon\"/>\n                                            <div class=\"oe_module_desc\" t-att-title=\"record.shortdesc.value\">\n                                                <h4 class=\"o_kanban_record_title\">\n                                                    <field name=\"shortdesc\"/>&amp;nbsp;\n                                                </h4>\n                                                <p class=\"oe_module_name\">\n                                                    <field groups=\"!base.group_no_one\" name=\"summary\"/>\n                                                    <code groups=\"base.group_no_one\">\n                                                        <field name=\"name\"/></code>\n                                                </p>\n                                            </div>\n                                        </div>\n                                    </t>\n                                </templates>\n                        </kanban>\n                    </field>\n                    <h3>Documents to Delete</h3>\n                    <field name=\"model_ids\" string=\"Models\" nolabel=\"1\">\n                        <tree string=\"Models\">\n                            <field name=\"name\" string=\"Document\"/>\n                            <field name=\"count\"/>\n                        </tree>\n                    </field>\n                    <footer>\n                        <button string=\"Uninstall\" class=\"btn-secondary\" type=\"object\" name=\"action_uninstall\" data-hotkey=\"q\"/>\n                        <button string=\"Discard\" class=\"btn-primary\" special=\"cancel\" data-hotkey=\"x\"/>\n                    </footer>\n                </form>"}', '<?xml version="1.0"?>
<form string="Uninstall module">
                    <div class="alert alert-warning oe_button_box" role="alert">
                        <p class="mt-3">
                            Uninstalling modules can be risky, we recommend you to try it on a duplicate or test database first.
                        </p>
                    </div>
                    <field name="module_id" invisible="1"/>
                    <div class="d-flex bd-highlight">
                        <div class="me-auto p-2 bd-highlight"><h3>Apps to Uninstall</h3></div>
                        <div class="p-2 bd-highlight"><field name="show_all"/> Show All</div>
                    </div>
                    <field name="module_ids" mode="kanban" class="o_modules_field">
                        <kanban create="false" class="o_modules_kanban">
                            <field name="icon"/>
                            <field name="state"/>
                            <field name="summary"/>
                                <templates>
                                    <t t-name="kanban-box">
                                        <div class="oe_module_vignette">
                                            <t t-set="installed" t-value="record.state.raw_value == ''installed''"/>
                                            <img t-attf-src="#{record.icon.value}" class="oe_module_icon" alt="Icon"/>
                                            <div class="oe_module_desc" t-att-title="record.shortdesc.value">
                                                <h4 class="o_kanban_record_title">
                                                    <field name="shortdesc"/>&amp;nbsp;
                                                </h4>
                                                <p class="oe_module_name">
                                                    <field groups="!base.group_no_one" name="summary"/>
                                                    <code groups="base.group_no_one">
                                                        <field name="name"/></code>
                                                </p>
                                            </div>
                                        </div>
                                    </t>
                                </templates>
                        </kanban>
                    </field>
                    <h3>Documents to Delete</h3>
                    <field name="model_ids" string="Models" nolabel="1">
                        <tree string="Models">
                            <field name="name" string="Document"/>
                            <field name="count"/>
                        </tree>
                    </field>
                    <footer>
                        <button string="Uninstall" class="btn-secondary" type="object" name="action_uninstall" data-hotkey="q"/>
                        <button string="Discard" class="btn-primary" special="cancel" data-hotkey="x"/>
                    </footer>
                </form>
            ', false, true, '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872', NULL);
INSERT INTO public.ir_ui_view VALUES (106, 16, NULL, 1, 1, 'Export Translations', 'base.language.export', NULL, 'form', 'base/wizard/base_export_language_views.xml', 'primary', '{"en_US": "<form string=\"Export Translations\">\n                    <field invisible=\"1\" name=\"state\"/>\n                    <field name=\"name\" invisible=\"1\"/>\n                    <group invisible=\"state != ''choose''\" string=\"Export Settings\">\n                        <field name=\"lang\"/>\n                        <field name=\"format\"/>\n                        <field name=\"export_type\"/>\n                        <field name=\"modules\" widget=\"many2many_tags\" options=\"{''no_create'': True}\" invisible=\"export_type == ''model''\"/>\n                        <field name=\"model_id\" options=\"{''no_create'': True}\" invisible=\"export_type == ''module''\" required=\"export_type == ''model''\"/>\n                        <field name=\"model_name\" invisible=\"1\"/>\n                        <field name=\"domain\" widget=\"domain\" options=\"{''model'': ''model_name''}\" invisible=\"export_type == ''module''\"/>\n                    </group>\n                    <div invisible=\"state != ''get''\">\n                        <h2>Export Complete</h2>\n                        <p>Here is the exported translation file: <field name=\"data\" readonly=\"1\" filename=\"name\"/></p>\n                        <p>This file was generated using the universal <strong>Unicode/UTF-8</strong> file encoding, please be sure to view and edit\n                           using the same encoding.</p>\n                        <p>The next step depends on the file format:\n                            <ul>\n                            <li>CSV format: you may edit it directly with your favorite spreadsheet software,\n                                the rightmost column (value) contains the translations</li>\n                            <li>PO(T) format: you should edit it with a PO editor such as\n                                <a href=\"http://www.poedit.net/\" target=\"_blank\">POEdit</a>, or your preferred text editor</li>\n                            <li>TGZ format: bundles multiple PO(T) files as a single archive</li>\n                            </ul>\n                        </p>\n                        <p>For more details about translating Odoo in your language, please refer to the\n                           <a href=\"https://github.com/odoo/odoo/wiki/Translations\" target=\"_blank\">documentation</a>.</p>\n                    </div>\n                    <footer invisible=\"state != ''choose''\">\n                        <button name=\"act_getfile\" string=\"Export\" type=\"object\" class=\"btn-primary\" data-hotkey=\"q\"/>\n                        <button special=\"cancel\" data-hotkey=\"x\" string=\"Cancel\" type=\"object\" class=\"btn-secondary\"/>\n                    </footer>\n                    <footer invisible=\"state != ''get''\">\n                        <button special=\"cancel\" data-hotkey=\"x\" string=\"Close\" type=\"object\" class=\"btn-primary\"/>\n                    </footer>\n                </form>"}', '<?xml version="1.0"?>
<form string="Export Translations">
                    <field invisible="1" name="state"/>
                    <field name="name" invisible="1"/>
                    <group invisible="state != ''choose''" string="Export Settings">
                        <field name="lang"/>
                        <field name="format"/>
                        <field name="export_type"/>
                        <field name="modules" widget="many2many_tags" options="{''no_create'': True}" invisible="export_type == ''model''"/>
                        <field name="model_id" options="{''no_create'': True}" invisible="export_type == ''module''" required="export_type == ''model''"/>
                        <field name="model_name" invisible="1"/>
                        <field name="domain" widget="domain" options="{''model'': ''model_name''}" invisible="export_type == ''module''"/>
                    </group>
                    <div invisible="state != ''get''">
                        <h2>Export Complete</h2>
                        <p>Here is the exported translation file: <field name="data" readonly="1" filename="name"/></p>
                        <p>This file was generated using the universal <strong>Unicode/UTF-8</strong> file encoding, please be sure to view and edit
                           using the same encoding.</p>
                        <p>The next step depends on the file format:
                            <ul>
                            <li>CSV format: you may edit it directly with your favorite spreadsheet software,
                                the rightmost column (value) contains the translations</li>
                            <li>PO(T) format: you should edit it with a PO editor such as
                                <a href="http://www.poedit.net/" target="_blank">POEdit</a>, or your preferred text editor</li>
                            <li>TGZ format: bundles multiple PO(T) files as a single archive</li>
                            </ul>
                        </p>
                        <p>For more details about translating Odoo in your language, please refer to the
                           <a href="https://github.com/odoo/odoo/wiki/Translations" target="_blank">documentation</a>.</p>
                    </div>
                    <footer invisible="state != ''choose''">
                        <button name="act_getfile" string="Export" type="object" class="btn-primary" data-hotkey="q"/>
                        <button special="cancel" data-hotkey="x" string="Cancel" type="object" class="btn-secondary"/>
                    </footer>
                    <footer invisible="state != ''get''">
                        <button special="cancel" data-hotkey="x" string="Close" type="object" class="btn-primary"/>
                    </footer>
                </form>
            ', false, true, '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872', NULL);
INSERT INTO public.ir_ui_view VALUES (107, 16, NULL, 1, 1, 'base.partner.merge.automatic.wizard.form', 'base.partner.merge.automatic.wizard', NULL, 'form', 'base/wizard/base_partner_merge_views.xml', 'primary', '{"en_US": "<form string=\"Automatic Merge Wizard\" class=\"o_partner_merge_wizard\">\n                    <sheet>\n                        <group invisible=\"state != ''finished''\">\n                            <h2 colspan=\"2\">There are no more contacts to merge for this request</h2>\n                            <button name=\"48\" string=\"Deduplicate the other Contacts\" class=\"oe_highlight\" type=\"action\" colspan=\"2\"/>\n                        </group>\n                        <p class=\"oe_grey\" invisible=\"state != ''option''\">\n                            Select the list of fields used to search for\n                            duplicated records. If you select several fields,\n                            Odoo will propose you to merge only those having\n                            all these fields in common. (not one of the fields).\n                        </p>\n                        <group invisible=\"state not in (''selection'', ''finished'') or number_group == 0\">\n                            <field name=\"state\" invisible=\"1\"/>\n                            <field name=\"number_group\"/>\n                        </group>\n                        <group string=\"Search duplicates based on duplicated data in\" invisible=\"state not in (''option'',)\">\n                            <field name=\"group_by_email\"/>\n                            <field name=\"group_by_name\"/>\n                            <field name=\"group_by_is_company\"/>\n                            <field name=\"group_by_vat\"/>\n                            <field name=\"group_by_parent_id\"/>\n                        </group>\n                        <group string=\"Exclude contacts having\" invisible=\"state not in (''option'',)\">\n                            <field name=\"exclude_contact\"/>\n                            <field name=\"exclude_journal_item\"/>\n                        </group>\n                        <separator string=\"Options\" invisible=\"state not in (''option'',)\"/>\n                        <group invisible=\"state not in (''option'', ''finished'')\">\n                            <field name=\"maximum_group\" readonly=\"state == ''finished''\"/>\n                        </group>\n                        <separator string=\"Merge the following contacts\" invisible=\"state in (''option'', ''finished'')\"/>\n                        <group invisible=\"state in (''option'', ''finished'')\" col=\"1\">\n                            <p class=\"oe_grey\">\n                                Selected contacts will be merged together.\n                                All documents linked to one of these contacts\n                                will be redirected to the destination contact.\n                                You can remove contacts from this list to avoid merging them.\n                            </p>\n                            <group col=\"2\">\n                                <field name=\"dst_partner_id\" domain=\"[(''id'', ''in'', partner_ids or False)]\" required=\"state == ''selection''\" context=\"{''partner_show_db_id'': True}\"/>\n                            </group>\n                            <field name=\"partner_ids\" nolabel=\"1\">\n                                <tree string=\"Partners\">\n                                    <field name=\"id\"/>\n                                    <field name=\"display_name\"/>\n                                    <field name=\"email\"/>\n                                    <field name=\"is_company\"/>\n                                    <field name=\"vat\"/>\n                                    <field name=\"country_id\"/>\n                                </tree>\n                            </field>\n                        </group>\n                    </sheet>\n                    <footer>\n                        <button name=\"action_merge\" string=\"Merge Contacts\" class=\"oe_highlight\" type=\"object\" data-hotkey=\"q\" invisible=\"state in (''option'', ''finished'')\"/>\n                        <button name=\"action_skip\" string=\"Skip these contacts\" type=\"object\" invisible=\"state != ''selection''\"/>\n                        <button name=\"action_start_manual_process\" string=\"Merge with Manual Check\" data-hotkey=\"w\" type=\"object\" class=\"oe_highlight\" invisible=\"state != ''option''\"/>\n                        <button name=\"action_start_automatic_process\" string=\"Merge Automatically\" data-hotkey=\"l\" type=\"object\" class=\"oe_highlight\" confirm=\"Are you sure to execute the automatic merge of your contacts?\" invisible=\"state != ''option''\"/>\n                        <button name=\"action_update_all_process\" string=\"Merge Automatically all process\" type=\"object\" data-hotkey=\"y\" confirm=\"Are you sure to execute the list of automatic merges of your contacts?\" invisible=\"state != ''option''\"/>\n                        <button special=\"cancel\" data-hotkey=\"x\" string=\"Cancel\" type=\"object\" class=\"btn btn-secondary oe_inline\" invisible=\"state == ''finished''\"/>\n                        <button special=\"cancel\" data-hotkey=\"x\" string=\"Close\" type=\"object\" class=\"btn btn-secondary oe_inline\" invisible=\"state != ''finished''\"/>\n                    </footer>\n                </form>"}', '<?xml version="1.0"?>
<form string="Automatic Merge Wizard" class="o_partner_merge_wizard">
                    <sheet>
                        <group invisible="state != ''finished''">
                            <h2 colspan="2">There are no more contacts to merge for this request</h2>
                            <button name="48" string="Deduplicate the other Contacts" class="oe_highlight" type="action" colspan="2"/>
                        </group>
                        <p class="oe_grey" invisible="state != ''option''">
                            Select the list of fields used to search for
                            duplicated records. If you select several fields,
                            Odoo will propose you to merge only those having
                            all these fields in common. (not one of the fields).
                        </p>
                        <group invisible="state not in (''selection'', ''finished'') or number_group == 0">
                            <field name="state" invisible="1"/>
                            <field name="number_group"/>
                        </group>
                        <group string="Search duplicates based on duplicated data in" invisible="state not in (''option'',)">
                            <field name="group_by_email"/>
                            <field name="group_by_name"/>
                            <field name="group_by_is_company"/>
                            <field name="group_by_vat"/>
                            <field name="group_by_parent_id"/>
                        </group>
                        <group string="Exclude contacts having" invisible="state not in (''option'',)">
                            <field name="exclude_contact"/>
                            <field name="exclude_journal_item"/>
                        </group>
                        <separator string="Options" invisible="state not in (''option'',)"/>
                        <group invisible="state not in (''option'', ''finished'')">
                            <field name="maximum_group" readonly="state == ''finished''"/>
                        </group>
                        <separator string="Merge the following contacts" invisible="state in (''option'', ''finished'')"/>
                        <group invisible="state in (''option'', ''finished'')" col="1">
                            <p class="oe_grey">
                                Selected contacts will be merged together.
                                All documents linked to one of these contacts
                                will be redirected to the destination contact.
                                You can remove contacts from this list to avoid merging them.
                            </p>
                            <group col="2">
                                <field name="dst_partner_id" domain="[(''id'', ''in'', partner_ids or False)]" required="state == ''selection''" context="{''partner_show_db_id'': True}"/>
                            </group>
                            <field name="partner_ids" nolabel="1">
                                <tree string="Partners">
                                    <field name="id"/>
                                    <field name="display_name"/>
                                    <field name="email"/>
                                    <field name="is_company"/>
                                    <field name="vat"/>
                                    <field name="country_id"/>
                                </tree>
                            </field>
                        </group>
                    </sheet>
                    <footer>
                        <button name="action_merge" string="Merge Contacts" class="oe_highlight" type="object" data-hotkey="q" invisible="state in (''option'', ''finished'')"/>
                        <button name="action_skip" string="Skip these contacts" type="object" invisible="state != ''selection''"/>
                        <button name="action_start_manual_process" string="Merge with Manual Check" data-hotkey="w" type="object" class="oe_highlight" invisible="state != ''option''"/>
                        <button name="action_start_automatic_process" string="Merge Automatically" data-hotkey="l" type="object" class="oe_highlight" confirm="Are you sure to execute the automatic merge of your contacts?" invisible="state != ''option''"/>
                        <button name="action_update_all_process" string="Merge Automatically all process" type="object" data-hotkey="y" confirm="Are you sure to execute the list of automatic merges of your contacts?" invisible="state != ''option''"/>
                        <button special="cancel" data-hotkey="x" string="Cancel" type="object" class="btn btn-secondary oe_inline" invisible="state == ''finished''"/>
                        <button special="cancel" data-hotkey="x" string="Close" type="object" class="btn btn-secondary oe_inline" invisible="state != ''finished''"/>
                    </footer>
                </form>
            ', false, true, '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872', NULL);
INSERT INTO public.ir_ui_view VALUES (328, 10, NULL, 1, 1, 'discuss.gif.favorite.tree', 'discuss.gif.favorite', NULL, 'tree', 'mail/views/discuss/discuss_gif_favorite_views.xml', 'primary', '{"en_US": "<tree string=\"GIF favorite\">\n                <field name=\"id\"/>\n                <field name=\"tenor_gif_id\"/>\n                <field name=\"create_uid\"/>\n            </tree>"}', '<?xml version="1.0"?>
<tree string="GIF favorite">
                <field name="id"/>
                <field name="tenor_gif_id"/>
                <field name="create_uid"/>
            </tree>
        ', false, true, '2026-05-10 01:11:43.555423', '2026-05-10 01:11:43.555423', NULL);
INSERT INTO public.ir_ui_view VALUES (112, 16, NULL, 1, 1, 'IR Profile Form', 'ir.profile', NULL, 'form', 'base/views/ir_profile_views.xml', 'primary', '{"en_US": "<form string=\"IR Profile\">\n                <group>\n                    <field name=\"name\"/>\n                    <field name=\"session\"/>\n                    <field name=\"entry_count\"/>\n                    <!-- Do not rely on sql field for the invisible attrs to avoid fetching whole trace from server. -->\n                    <field name=\"sql_count\" invisible=\"sql_count == 0\"/>\n                    <field name=\"speedscope_url\" widget=\"url\"/>\n                </group>\n                <group invisible=\"not qweb\">\n                    <field name=\"qweb\" widget=\"profiling_qweb_view\" nolabel=\"1\" colspan=\"2\"/>\n                </group>\n            </form>"}', '<?xml version="1.0"?>
<form string="IR Profile">
                <group>
                    <field name="name"/>
                    <field name="session"/>
                    <field name="entry_count"/>
                    <!-- Do not rely on sql field for the invisible attrs to avoid fetching whole trace from server. -->
                    <field name="sql_count" invisible="sql_count == 0"/>
                    <field name="speedscope_url" widget="url"/>
                </group>
                <group invisible="not qweb">
                    <field name="qweb" widget="profiling_qweb_view" nolabel="1" colspan="2"/>
                </group>
            </form>
        ', false, true, '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872', NULL);
INSERT INTO public.ir_ui_view VALUES (113, 16, NULL, 1, 1, 'Enable profiling', 'base.enable.profiling.wizard', NULL, 'form', 'base/views/ir_profile_views.xml', 'primary', '{"en_US": "<form string=\"Enable profiling\">\n                <div class=\"alert alert-warning\" role=\"alert\">\n                    <h3>Profiling is currently disabled.</h3>\n                    Profiling is a developer feature that should be used with caution on production database.\n                    It may add some load on the server, and potentially make it less responsive.\n                    Enabling the profiling here allows all users to activate profiling on their session.\n                    Profiling can be disabled at any moment in the settings.\n                </div>\n                <group>\n                    <field name=\"duration\"/>\n                    <field name=\"expiration\"/>\n                </group>\n                <footer>\n                    <button string=\"Cancel\" class=\"btn-secondary\" special=\"cancel\" data-hotkey=\"x\"/>\n                    <button string=\"Enable profiling\" type=\"object\" name=\"submit\" class=\"btn btn-primary\" data-hotkey=\"q\"/>\n                </footer>\n            </form>"}', '<?xml version="1.0"?>
<form string="Enable profiling">
                <div class="alert alert-warning" role="alert">
                    <h3>Profiling is currently disabled.</h3>
                    Profiling is a developer feature that should be used with caution on production database.
                    It may add some load on the server, and potentially make it less responsive.
                    Enabling the profiling here allows all users to activate profiling on their session.
                    Profiling can be disabled at any moment in the settings.
                </div>
                <group>
                    <field name="duration"/>
                    <field name="expiration"/>
                </group>
                <footer>
                    <button string="Cancel" class="btn-secondary" special="cancel" data-hotkey="x"/>
                    <button string="Enable profiling" type="object" name="submit" class="btn btn-primary" data-hotkey="q"/>
                </footer>
            </form>
        ', false, true, '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872', NULL);
INSERT INTO public.ir_ui_view VALUES (114, 16, NULL, 1, 1, 'res.company.form', 'res.company', NULL, 'form', 'base/views/res_company_views.xml', 'primary', '{"en_US": "<form string=\"Company\" duplicate=\"0\">\n                  <field name=\"all_child_ids\" invisible=\"1\"/>\n                  <sheet>\n                    <div class=\"oe_button_box\" name=\"button_box\">\n                        <button class=\"oe_stat_button\" name=\"action_all_company_branches\" type=\"object\" invisible=\"not all_child_ids\" icon=\"fa-sitemap\" string=\"Branches\"/>\n                    </div>\n                    <field name=\"logo\" widget=\"image\" class=\"oe_avatar\"/>\n                    <div class=\"oe_title\">\n                        <label for=\"name\"/>\n                        <h1>\n                            <field name=\"name\" placeholder=\"e.g. My Company\"/>\n                        </h1>\n                    </div>\n                    <notebook colspan=\"4\">\n                        <page string=\"General Information\" name=\"general_info\">\n                            <group>\n                                <group>\n                                    <field name=\"partner_id\" string=\"Contact\" readonly=\"1\" required=\"0\" groups=\"base.group_no_one\"/>\n                                    <label for=\"street\" string=\"Address\"/>\n                                    <div class=\"o_address_format\">\n                                        <field name=\"street\" placeholder=\"Street...\" class=\"o_address_street\"/>\n                                        <field name=\"street2\" placeholder=\"Street 2...\" class=\"o_address_street\"/>\n                                        <field name=\"city\" placeholder=\"City\" class=\"o_address_city\"/>\n                                        <field name=\"state_id\" class=\"o_address_state\" placeholder=\"State\" options=\"{&quot;no_open&quot;: True}\"/>\n                                        <field name=\"zip\" placeholder=\"ZIP\" class=\"o_address_zip\"/>\n                                        <field name=\"country_id\" placeholder=\"Country\" class=\"o_address_country\" options=\"{&quot;no_open&quot;: True, &quot;no_create&quot;: True}\"/>\n                                    </div>\n                                    <field name=\"vat\"/>\n                                    <field name=\"company_registry\"/>\n                                    <field name=\"currency_id\" options=\"{''no_create'': True, ''no_open'': True}\" id=\"company_currency\" context=\"{''active_test'': False}\"/>\n                                </group>\n                                <group>\n                                    <field name=\"phone\" class=\"o_force_ltr\"/>\n                                    <field name=\"mobile\" class=\"o_force_ltr\"/>\n                                    <field name=\"email\"/>\n                                    <field name=\"website\" string=\"Website\" widget=\"url\" placeholder=\"e.g. https://www.odoo.com\"/>\n                                    <field name=\"parent_id\" groups=\"base.group_no_one\"/>\n                                    <field name=\"parent_id\" invisible=\"1\"/>\n                                    <field name=\"sequence\" invisible=\"1\"/>\n                                    <field name=\"color\" widget=\"color_picker\"/>\n                                </group>\n                                <group name=\"social_media\"/>\n                            </group>\n                        </page>\n                        <page string=\"Branches\" name=\"branches\">\n                            <field name=\"child_ids\" nolabel=\"1\" context=\"{''default_parent_id'': id}\"/>\n                        </page>\n                    </notebook>\n                    </sheet>\n                </form>"}', '<?xml version="1.0"?>
<form string="Company" duplicate="0">
                  <field name="all_child_ids" invisible="1"/>
                  <sheet>
                    <div class="oe_button_box" name="button_box">
                        <button class="oe_stat_button" name="action_all_company_branches" type="object" invisible="not all_child_ids" icon="fa-sitemap" string="Branches"/>
                    </div>
                    <field name="logo" widget="image" class="oe_avatar"/>
                    <div class="oe_title">
                        <label for="name"/>
                        <h1>
                            <field name="name" placeholder="e.g. My Company"/>
                        </h1>
                    </div>
                    <notebook colspan="4">
                        <page string="General Information" name="general_info">
                            <group>
                                <group>
                                    <field name="partner_id" string="Contact" readonly="1" required="0" groups="base.group_no_one"/>
                                    <label for="street" string="Address"/>
                                    <div class="o_address_format">
                                        <field name="street" placeholder="Street..." class="o_address_street"/>
                                        <field name="street2" placeholder="Street 2..." class="o_address_street"/>
                                        <field name="city" placeholder="City" class="o_address_city"/>
                                        <field name="state_id" class="o_address_state" placeholder="State" options="{&quot;no_open&quot;: True}"/>
                                        <field name="zip" placeholder="ZIP" class="o_address_zip"/>
                                        <field name="country_id" placeholder="Country" class="o_address_country" options="{&quot;no_open&quot;: True, &quot;no_create&quot;: True}"/>
                                    </div>
                                    <field name="vat"/>
                                    <field name="company_registry"/>
                                    <field name="currency_id" options="{''no_create'': True, ''no_open'': True}" id="company_currency" context="{''active_test'': False}"/>
                                </group>
                                <group>
                                    <field name="phone" class="o_force_ltr"/>
                                    <field name="mobile" class="o_force_ltr"/>
                                    <field name="email"/>
                                    <field name="website" string="Website" widget="url" placeholder="e.g. https://www.odoo.com"/>
                                    <field name="parent_id" groups="base.group_no_one"/>
                                    <field name="parent_id" invisible="1"/>
                                    <field name="sequence" invisible="1"/>
                                    <field name="color" widget="color_picker"/>
                                </group>
                                <group name="social_media"/>
                            </group>
                        </page>
                        <page string="Branches" name="branches">
                            <field name="child_ids" nolabel="1" context="{''default_parent_id'': id}"/>
                        </page>
                    </notebook>
                    </sheet>
                </form>
            ', false, true, '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872', NULL);
INSERT INTO public.ir_ui_view VALUES (115, 16, NULL, 1, 1, 'res.company.tree', 'res.company', NULL, 'tree', 'base/views/res_company_views.xml', 'primary', '{"en_US": "<tree string=\"Companies\" decoration-muted=\"not active\">\n                    <field name=\"sequence\" widget=\"handle\"/>\n                    <field name=\"name\"/>\n                    <field name=\"partner_id\" required=\"0\"/>\n                    <field name=\"child_ids\" widget=\"many2many_tags\" options=\"{''color_field'': ''color''}\"/>\n                    <field name=\"active\" column_invisible=\"True\"/>\n                </tree>"}', '<?xml version="1.0"?>
<tree string="Companies" decoration-muted="not active">
