                    <field name="name"/>
                    <field name="partner_id" required="0"/>
                    <field name="child_ids" widget="many2many_tags" options="{''color_field'': ''color''}"/>
                    <field name="active" column_invisible="True"/>
                </tree>
            ', false, true, '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872', NULL);
INSERT INTO public.ir_ui_view VALUES (116, 16, NULL, 1, 1, 'res.company.kanban', 'res.company', NULL, 'kanban', 'base/views/res_company_views.xml', 'primary', '{"en_US": "<kanban>\n                    <field name=\"name\"/>\n                    <field name=\"email\"/>\n                    <field name=\"phone\"/>\n                    <templates>\n                        <t t-name=\"kanban-box\">\n                            <div t-attf-class=\"oe_kanban_global_click\">\n                                <div t-attf-class=\"#{!selection_mode ? ''text-center'' : ''''}\">\n                                    <i class=\"fa fa-building\" role=\"img\" aria-label=\"Enterprise\" title=\"Enterprise\"/> <strong><field name=\"name\"/></strong>\n                                </div>\n                                <hr class=\"mt4 mb4\"/>\n                                <div class=\"row\" t-if=\"!selection_mode\">\n                                    <div t-if=\"record.email.value\" class=\"col-6 text-center\">\n                                        <strong>Email:</strong>\n                                    </div>\n                                    <div t-if=\"record.phone.value\" class=\"col-6 text-center\">\n                                        <strong>Phone</strong>\n                                    </div>\n                                    <div t-if=\"record.email.value\" class=\"col-6 text-center\">\n                                        <field name=\"email\"/>\n                                    </div>\n                                    <div t-if=\"record.phone.value\" class=\"col-6 text-center o_force_ltr\">\n                                        <field name=\"phone\"/>\n                                    </div>\n                                </div>\n                                <div t-else=\"\">\n                                    <div t-if=\"record.email.value\">\n                                        <strong>Email:</strong>\n                                        <field name=\"email\"/>\n                                    </div>\n                                    <div t-if=\"record.phone.value\" class=\"o_force_ltr\">\n                                        <strong>Phone:</strong>\n                                        <field name=\"phone\"/>\n                                    </div>\n                                </div>\n                            </div>\n                        </t>\n                    </templates>\n                </kanban>"}', '<?xml version="1.0"?>
<kanban>
                    <field name="name"/>
                    <field name="email"/>
                    <field name="phone"/>
                    <templates>
                        <t t-name="kanban-box">
                            <div t-attf-class="oe_kanban_global_click">
                                <div t-attf-class="#{!selection_mode ? ''text-center'' : ''''}">
                                    <i class="fa fa-building" role="img" aria-label="Enterprise" title="Enterprise"/> <strong><field name="name"/></strong>
                                </div>
                                <hr class="mt4 mb4"/>
                                <div class="row" t-if="!selection_mode">
                                    <div t-if="record.email.value" class="col-6 text-center">
                                        <strong>Email:</strong>
                                    </div>
                                    <div t-if="record.phone.value" class="col-6 text-center">
                                        <strong>Phone</strong>
                                    </div>
                                    <div t-if="record.email.value" class="col-6 text-center">
                                        <field name="email"/>
                                    </div>
                                    <div t-if="record.phone.value" class="col-6 text-center o_force_ltr">
                                        <field name="phone"/>
                                    </div>
                                </div>
                                <div t-else="">
                                    <div t-if="record.email.value">
                                        <strong>Email:</strong>
                                        <field name="email"/>
                                    </div>
                                    <div t-if="record.phone.value" class="o_force_ltr">
                                        <strong>Phone:</strong>
                                        <field name="phone"/>
                                    </div>
                                </div>
                            </div>
                        </t>
                    </templates>
                </kanban>
            ', false, true, '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872', NULL);
INSERT INTO public.ir_ui_view VALUES (129, 16, NULL, 1, 1, 'Contact Tags', 'res.partner.category', NULL, 'form', 'base/views/res_partner_views.xml', 'primary', '{"en_US": "<form string=\"Contact Tag\">\n                    <sheet>\n                        <group col=\"4\">\n                            <field name=\"name\" placeholder=\"e.g. &quot;Consulting Services&quot;\"/>\n                            <field name=\"color\" widget=\"color_picker\"/>\n                            <field name=\"parent_id\"/>\n                            <field name=\"active\" widget=\"boolean_toggle\"/>\n                        </group>\n                    </sheet>\n                </form>"}', '<?xml version="1.0"?>
