INSERT INTO public.ir_ui_view VALUES (117, 16, NULL, 1, 1, 'res.lang.tree', 'res.lang', NULL, 'tree', 'base/views/res_lang_views.xml', 'primary', '{"en_US": "<tree string=\"Languages\" limit=\"200\">\n                    <header>\n                        <button name=\"action_activate_langs\" type=\"object\" string=\"Activate\"/>\n                    </header>\n                    <field name=\"name\"/>\n                    <field name=\"code\" groups=\"base.group_no_one\"/>\n                    <field name=\"iso_code\" groups=\"base.group_no_one\"/>\n                    <field name=\"url_code\" groups=\"base.group_no_one\" column_invisible=\"True\"/>\n                    <field name=\"direction\" groups=\"base.group_no_one\"/>\n                    <field name=\"active\"/>\n                    <button name=\"43\" string=\"Activate\" type=\"action\" icon=\"fa-check\" invisible=\"active\"/>\n                    <button name=\"43\" string=\"Update\" type=\"action\" icon=\"fa-refresh\" invisible=\"not active\"/>\n                    <button name=\"action_archive\" string=\"Disable\" type=\"object\" icon=\"fa-times\" invisible=\"not active\"/>\n                </tree>"}', '<?xml version="1.0"?>
<tree string="Languages" limit="200">
                    <header>
                        <button name="action_activate_langs" type="object" string="Activate"/>
                    </header>
                    <field name="name"/>
                    <field name="code" groups="base.group_no_one"/>
                    <field name="iso_code" groups="base.group_no_one"/>
                    <field name="url_code" groups="base.group_no_one" column_invisible="True"/>
                    <field name="direction" groups="base.group_no_one"/>
                    <field name="active"/>
                    <button name="43" string="Activate" type="action" icon="fa-check" invisible="active"/>
                    <button name="43" string="Update" type="action" icon="fa-refresh" invisible="not active"/>
                    <button name="action_archive" string="Disable" type="object" icon="fa-times" invisible="not active"/>
                </tree>
            ', false, true, '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872', NULL);
INSERT INTO public.ir_ui_view VALUES (118, 16, NULL, 1, 1, 'res.lang.form', 'res.lang', NULL, 'form', 'base/views/res_lang_views.xml', 'primary', '{"en_US": "<form string=\"Languages\">\n                    <sheet>\n                        <div class=\"oe_button_box\" name=\"button_box\">\n                            <button name=\"43\" type=\"action\" class=\"oe_stat_button\" icon=\"fa-refresh\">\n                                <div class=\"o_field_widget o_stat_info\">\n                                    <span class=\"o_stat_text\">Activate and Translate</span>\n                                </div>\n                            </button>\n                        </div>\n                        <field name=\"flag_image\" widget=\"image\" class=\"oe_avatar\"/>\n                        <div class=\"oe_title\">\n                            <label for=\"name\"/>\n                            <h1><field name=\"name\" placeholder=\"e.g. French\"/></h1>\n                        </div>\n                        <group>\n                            <group>\n                                <field name=\"code\"/>\n                                <field name=\"iso_code\"/>\n                                <field name=\"url_code\" invisible=\"1\" required=\"0\"/>\n                                <field name=\"active\" widget=\"boolean_toggle\"/>\n                            </group>\n                            <group>\n                                <field name=\"direction\"/>\n                                <field name=\"grouping\"/>\n                                <field name=\"decimal_point\"/>\n                                <field name=\"thousands_sep\"/>\n                                <field name=\"date_format\"/>\n                                <field name=\"time_format\"/>\n                                <field name=\"week_start\"/>\n                            </group>\n                        </group>\n\n                        <div class=\"row\">\n                            <div class=\"col-md-8 row\">\n                                <div class=\"col-12\">\n                                    <div class=\"o_horizontal_separator mb-3 mt-4 text-uppercase fw-bolder small\">Legends for supported Date and Time Formats</div>\n                                </div>\n                                <div class=\"col-sm\">\n                                    <div>%a - Abbreviated day of the week.</div>\n                                    <div>%A - Full day of the week.</div>\n                                    <div>%b - Abbreviated month name.</div>\n                                    <div>%B - Full month name.\"</div>\n                                    <div>%d - Day of the month [01,31].\"</div>\n                                    <div>%j - Day of the year [001,366].\"</div>\n                                    <div>%H - Hour (24-hour clock) [00,23].\"</div>\n                                    <div>%I - Hour (12-hour clock) [01,12].\"</div>\n                                </div>\n                                <div class=\"col-sm\">\n                                    <div>%M - Minute [00,59].\"</div>\n                                    <div>%p - Equivalent of either AM or PM.\"</div>\n                                    <div>%S - Seconds [00,61].\"</div>\n                                    <div>%w - Day of the week number [0(Sunday),6].\"</div>\n                                    <div>%y - Year without century [00,99].\"</div>\n                                    <div>%Y - Year with century.\"</div>\n                                    <div>%m - Month number [01,12].\"</div>\n                                </div>\n                            </div>\n                            <div class=\"col-md-4 text-info\">\n                                <div class=\"o_horizontal_separator mb-3 mt-4 text-uppercase fw-bolder small\">Examples</div>\n                                <div>1. %b, %B         ==&gt; Dec, December</div>\n                                <div>2. %a ,%A         ==&gt; Fri, Friday</div>\n                                <div>3. %y, %Y         ==&gt; 08, 2008</div>\n                                <div>4. %d, %m         ==&gt; 05, 12</div>\n                                <div>5. %H:%M:%S      ==&gt; 18:25:20</div>\n                                <div>6. %I:%M:%S %p  ==&gt; 06:25:20 PM</div>\n                                <div>7. %j              ==&gt; 340</div>\n                                <div>8. %S              ==&gt; 20</div>\n                                <div>9. %w              ==&gt; 5 ( Friday is the 6th day)</div>\n                            </div>\n                        </div>\n                    </sheet>\n                </form>"}', '<?xml version="1.0"?>
<form string="Languages">
                    <sheet>
                        <div class="oe_button_box" name="button_box">
                            <button name="43" type="action" class="oe_stat_button" icon="fa-refresh">
                                <div class="o_field_widget o_stat_info">
                                    <span class="o_stat_text">Activate and Translate</span>
                                </div>
                            </button>
                        </div>
                        <field name="flag_image" widget="image" class="oe_avatar"/>
                        <div class="oe_title">
                            <label for="name"/>
                            <h1><field name="name" placeholder="e.g. French"/></h1>
                        </div>
                        <group>
                            <group>
                                <field name="code"/>
                                <field name="iso_code"/>
                                <field name="url_code" invisible="1" required="0"/>
                                <field name="active" widget="boolean_toggle"/>
                            </group>
                            <group>
                                <field name="direction"/>
                                <field name="grouping"/>
                                <field name="decimal_point"/>
                                <field name="thousands_sep"/>
                                <field name="date_format"/>
                                <field name="time_format"/>
                                <field name="week_start"/>
                            </group>
                        </group>

                        <div class="row">
                            <div class="col-md-8 row">
                                <div class="col-12">
                                    <div class="o_horizontal_separator mb-3 mt-4 text-uppercase fw-bolder small">Legends for supported Date and Time Formats</div>
                                </div>
                                <div class="col-sm">
                                    <div>%a - Abbreviated day of the week.</div>
                                    <div>%A - Full day of the week.</div>
                                    <div>%b - Abbreviated month name.</div>
                                    <div>%B - Full month name."</div>
                                    <div>%d - Day of the month [01,31]."</div>
                                    <div>%j - Day of the year [001,366]."</div>
                                    <div>%H - Hour (24-hour clock) [00,23]."</div>
                                    <div>%I - Hour (12-hour clock) [01,12]."</div>
                                </div>
                                <div class="col-sm">
                                    <div>%M - Minute [00,59]."</div>
                                    <div>%p - Equivalent of either AM or PM."</div>
                                    <div>%S - Seconds [00,61]."</div>
                                    <div>%w - Day of the week number [0(Sunday),6]."</div>
                                    <div>%y - Year without century [00,99]."</div>
                                    <div>%Y - Year with century."</div>
                                    <div>%m - Month number [01,12]."</div>
                                </div>
                            </div>
                            <div class="col-md-4 text-info">
                                <div class="o_horizontal_separator mb-3 mt-4 text-uppercase fw-bolder small">Examples</div>
                                <div>1. %b, %B         ==&gt; Dec, December</div>
                                <div>2. %a ,%A         ==&gt; Fri, Friday</div>
                                <div>3. %y, %Y         ==&gt; 08, 2008</div>
                                <div>4. %d, %m         ==&gt; 05, 12</div>
                                <div>5. %H:%M:%S      ==&gt; 18:25:20</div>
                                <div>6. %I:%M:%S %p  ==&gt; 06:25:20 PM</div>
                                <div>7. %j              ==&gt; 340</div>
                                <div>8. %S              ==&gt; 20</div>
                                <div>9. %w              ==&gt; 5 ( Friday is the 6th day)</div>
                            </div>
                        </div>
                    </sheet>
                </form>
            ', false, true, '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872', NULL);
INSERT INTO public.ir_ui_view VALUES (119, 16, NULL, 1, 1, 'res.lang.search', 'res.lang', NULL, 'search', 'base/views/res_lang_views.xml', 'primary', '{"en_US": "<search string=\"Languages\">\n                    <field name=\"name\" filter_domain=\"[''|'', ''|'', (''name'', ''ilike'', self), (''code'', ''ilike'', self), (''iso_code'', ''ilike'', self)]\" string=\"Language\"/>\n                    <field name=\"direction\"/>\n                    <separator/>\n                    <filter string=\"Active\" name=\"active\" domain=\"[(''active'', ''='', True)]\"/>\n                </search>"}', '<?xml version="1.0"?>
