INSERT INTO public.ir_ui_view VALUES (122, 8, NULL, 1, 1, 'res.partner.tree', 'res.partner', NULL, 'tree', 'base/views/res_partner_views.xml', 'primary', '{"en_US": "<tree string=\"Contacts\" sample=\"1\" multi_edit=\"1\">\n                    <field name=\"display_name\" string=\"Name\" column_invisible=\"1\"/>\n                    <field name=\"complete_name\" string=\"Name\"/>\n                    <field name=\"function\" column_invisible=\"True\"/>\n                    <field name=\"phone\" class=\"o_force_ltr\" optional=\"show\"/>\n                    <field name=\"mobile\" optional=\"hide\"/>\n                    <field name=\"email\" optional=\"show\"/>\n                    <field name=\"user_id\" optional=\"show\" widget=\"many2one_avatar_user\" domain=\"[(''share'', ''='', False)]\"/>\n                    <field name=\"city\" optional=\"show\"/>\n                    <field name=\"state_id\" optional=\"hide\" readonly=\"1\"/>\n                    <field name=\"country_id\" optional=\"show\" readonly=\"1\"/>\n                    <field name=\"vat\" optional=\"hide\" readonly=\"1\"/>\n                    <field name=\"category_id\" optional=\"hide\" widget=\"many2many_tags\" options=\"{''color_field'': ''color''}\"/>\n                    <field name=\"company_id\" groups=\"base.group_multi_company\" readonly=\"1\"/>\n                    <field name=\"is_company\" column_invisible=\"True\"/>\n                    <field name=\"parent_id\" readonly=\"1\" column_invisible=\"True\"/>\n                    <field name=\"active\" column_invisible=\"True\"/>\n                </tree>"}', '<?xml version="1.0"?>
<tree string="Contacts" sample="1" multi_edit="1">
                    <field name="display_name" string="Name" column_invisible="1"/>
                    <field name="complete_name" string="Name"/>
                    <field name="function" column_invisible="True"/>
                    <field name="phone" class="o_force_ltr" optional="show"/>
                    <field name="mobile" optional="hide"/>
                    <field name="email" optional="show"/>
                    <field name="user_id" optional="show" widget="many2one_avatar_user" domain="[(''share'', ''='', False)]"/>
                    <field name="city" optional="show"/>
                    <field name="state_id" optional="hide" readonly="1"/>
                    <field name="country_id" optional="show" readonly="1"/>
                    <field name="vat" optional="hide" readonly="1"/>
                    <field name="category_id" optional="hide" widget="many2many_tags" options="{''color_field'': ''color''}"/>
                    <field name="company_id" groups="base.group_multi_company" readonly="1"/>
                    <field name="is_company" column_invisible="True"/>
                    <field name="parent_id" readonly="1" column_invisible="True"/>
                    <field name="active" column_invisible="True"/>
                </tree>
            ', false, true, '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872', NULL);
INSERT INTO public.ir_ui_view VALUES (130, 6, NULL, 1, 1, 'Contact Tags', 'res.partner.category', NULL, 'tree', 'base/views/res_partner_views.xml', 'primary', '{"en_US": "<tree string=\"Contact Tags\">\n                    <field name=\"display_name\"/>\n                    <field name=\"color\" widget=\"color_picker\"/>\n                </tree>"}', '<?xml version="1.0"?>
