INSERT INTO public.ir_ui_view VALUES (125, 1, NULL, 1, 1, 'res.partner.form', 'res.partner', NULL, 'form', 'base/views/res_partner_views.xml', 'primary', '{"en_US": "<form string=\"Partners\">\n                <div class=\"alert alert-warning oe_edit_only\" role=\"alert\" name=\"warning_tax\" invisible=\"not same_vat_partner_id\">\n                  A partner with the same <span><span class=\"o_vat_label\">Tax ID</span></span> already exists (<field name=\"same_vat_partner_id\" context=\"{''show_address'': False, ''show_vat'': False}\"/>), are you sure to create a new one?\n                </div>\n                <div class=\"alert alert-warning oe_edit_only\" role=\"alert\" name=\"warning_company\" invisible=\"not same_company_registry_partner_id\">\n                  A partner with the same <span><span class=\"o_vat_label\">Company Registry</span></span> already exists (<field name=\"same_company_registry_partner_id\" context=\"{''show_address'': False, ''show_vat'': False}\"/>), are you sure to create a new one?\n                </div>\n                <sheet>\n                    <div class=\"oe_button_box\" name=\"button_box\"/>\n                    <widget name=\"web_ribbon\" title=\"Archived\" bg_color=\"text-bg-danger\" invisible=\"active\"/>\n                    <field name=\"avatar_128\" invisible=\"1\"/>\n                    <field name=\"image_1920\" widget=\"image\" class=\"oe_avatar\" options=\"{&quot;preview_image&quot;: &quot;avatar_128&quot;}\"/>\n                    <div class=\"oe_title mb24\">\n                        <field name=\"is_company\" invisible=\"1\"/>\n                        <field name=\"commercial_partner_id\" invisible=\"1\"/>\n                        <field name=\"active\" invisible=\"1\"/>\n                        <field name=\"company_id\" invisible=\"1\"/>\n                        <field name=\"country_code\" invisible=\"1\"/>\n                        <field name=\"company_type\" widget=\"radio\" options=\"{''horizontal'': true}\"/>\n                        <h1>\n                            <field id=\"company\" options=\"{''line_breaks'': False}\" widget=\"text\" class=\"text-break\" name=\"name\" default_focus=\"1\" placeholder=\"e.g. Lumber Inc\" invisible=\"not is_company\" required=\"type == ''contact''\"/>\n                            <field id=\"individual\" options=\"{''line_breaks'': False}\" widget=\"text\" class=\"text-break\" name=\"name\" default_focus=\"1\" placeholder=\"e.g. Brandom Freeman\" invisible=\"is_company\" required=\"type == ''contact''\"/>\n                        </h1>\n                        <div class=\"o_row\">\n                            <field name=\"parent_id\" widget=\"res_partner_many2one\" placeholder=\"Company Name...\" domain=\"[(''is_company'', ''='', True)]\" context=\"{''default_is_company'': True, ''show_vat'': True, ''default_user_id'': user_id}\" invisible=\"((is_company and not parent_id) or company_name) and company_name != ''''\"/>\n                                <field name=\"company_name\" invisible=\"not company_name or company_name == '''' or is_company\"/>\n                                <button name=\"create_company\" icon=\"fa-plus-square\" string=\"Create company\" type=\"object\" class=\"oe_edit_only btn-link\" invisible=\"is_company or company_name == '''' or not company_name\"/>\n                        </div>\n                    </div>\n\n                    <group>\n                        <group>\n                            <span class=\"o_form_label o_td_label\" name=\"address_name\">\n                                <field name=\"type\" invisible=\"is_company\" readonly=\"user_ids\" required=\"not is_company\" class=\"fw-bold\"/>\n                                <b invisible=\"not is_company\">Address</b>\n                            </span>\n                            <div class=\"o_address_format\">\n                                <field name=\"street\" placeholder=\"Street...\" class=\"o_address_street\" readonly=\"type == ''contact'' and parent_id\"/>\n                                <field name=\"street2\" placeholder=\"Street 2...\" class=\"o_address_street\" readonly=\"type == ''contact'' and parent_id\"/>\n                                <field name=\"city\" placeholder=\"City\" class=\"o_address_city\" readonly=\"type == ''contact'' and parent_id\"/>\n                                <field name=\"state_id\" class=\"o_address_state\" placeholder=\"State\" options=\"{''no_open'': True, ''no_quick_create'': True}\" readonly=\"type == ''contact'' and parent_id\" context=\"{''country_id'': country_id, ''default_country_id'': country_id, ''zip'': zip}\"/>\n                                <field name=\"zip\" placeholder=\"ZIP\" class=\"o_address_zip\" readonly=\"type == ''contact'' and parent_id\"/>\n                                <div name=\"partner_address_country\" class=\"d-flex justify-content-between\">\n                                    <field name=\"country_id\" placeholder=\"Country\" class=\"o_address_country\" options=\"{&quot;no_open&quot;: True, &quot;no_create&quot;: True}\" readonly=\"type == ''contact'' and parent_id\"/>\n                                </div>\n                            </div>\n                            <field name=\"vat\" placeholder=\"e.g. BE0477472701\" readonly=\"parent_id\"/>\n                        </group>\n                        <group>\n                            <field name=\"function\" placeholder=\"e.g. Sales Director\" invisible=\"is_company\"/>\n                            <field name=\"phone\" widget=\"phone\"/>\n                            <field name=\"mobile\" widget=\"phone\"/>\n                            <field name=\"user_ids\" invisible=\"1\"/>\n                            <field name=\"email\" widget=\"email\" context=\"{''gravatar_image'': True}\" required=\"user_ids\"/>\n                            <field name=\"website\" string=\"Website\" widget=\"url\" placeholder=\"e.g. https://www.odoo.com\"/>\n                            <field name=\"title\" options=\"{&quot;no_open&quot;: True}\" placeholder=\"e.g. Mister\" invisible=\"is_company\"/>\n                            <field name=\"active_lang_count\" invisible=\"1\"/>\n                            <field name=\"lang\" invisible=\"active_lang_count &lt;= 1\"/>\n                            <field name=\"category_id\" widget=\"many2many_tags\" options=\"{''color_field'': ''color'', ''no_create_edit'': True}\" placeholder=\"e.g. &quot;B2B&quot;, &quot;VIP&quot;, &quot;Consulting&quot;, ...\"/>\n                        </group>\n                    </group>\n\n                    <notebook colspan=\"4\">\n                        <page string=\"Contacts &amp; Addresses\" name=\"contact_addresses\" autofocus=\"autofocus\">\n                            <field name=\"child_ids\" mode=\"kanban\" context=\"{''default_parent_id'': id, ''default_street'': street, ''default_street2'': street2, ''default_city'': city, ''default_state_id'': state_id, ''default_zip'': zip, ''default_country_id'': country_id, ''default_lang'': lang, ''default_user_id'': user_id, ''default_type'': ''other''}\">\n                                <kanban>\n                                    <field name=\"id\"/>\n                                    <field name=\"color\"/>\n                                    <field name=\"name\"/>\n                                    <field name=\"title\"/>\n                                    <field name=\"type\"/>\n                                    <field name=\"email\"/>\n                                    <field name=\"parent_id\"/>\n                                    <field name=\"is_company\"/>\n                                    <field name=\"function\"/>\n                                    <field name=\"phone\"/>\n                                    <field name=\"street\"/>\n                                    <field name=\"street2\"/>\n                                    <field name=\"zip\"/>\n                                    <field name=\"city\"/>\n                                    <field name=\"country_id\"/>\n                                    <field name=\"mobile\"/>\n                                    <field name=\"state_id\"/>\n                                    <field name=\"image_128\"/>\n                                    <field name=\"avatar_128\"/>\n                                    <field name=\"lang\"/>\n                                    <!-- fields in form x2many view to diminish requests -->\n                                    <field name=\"comment\"/>\n                                    <field name=\"display_name\"/>\n                                    <templates>\n                                        <t t-name=\"kanban-box\">\n                                            <t t-set=\"color\" t-value=\"kanban_color(record.color.raw_value)\"/>\n                                            <div t-att-class=\"color + (record.title.raw_value == 1 ? '' oe_kanban_color_alert'' : '''') + '' oe_kanban_global_click''\">\n                                                <div class=\"o_kanban_image\">\n                                                    <img alt=\"Contact image\" t-att-src=\"kanban_image(''res.partner'', ''avatar_128'', record.id.raw_value)\"/>\n                                                </div>\n                                                <div class=\"oe_kanban_details\">\n                                                    <field name=\"name\"/>\n                                                    <div t-if=\"record.function.raw_value\"><field name=\"function\"/></div>\n                                                    <div t-if=\"record.email.raw_value\"><field name=\"email\" widget=\"email\"/></div>\n                                                    <div t-if=\"record.type.raw_value != ''contact''\">\n                                                        <div>\n                                                            <field name=\"zip\"/><t t-if=\"record.city\"> </t>\n                                                            <field name=\"city\"/>\n                                                        </div>\n                                                        <field t-if=\"record.state_id.raw_value\" name=\"state_id\"/><t t-if=\"record.country_id\"> </t>\n                                                        <field name=\"country_id\"/>\n                                                    </div>\n                                                    <div t-if=\"record.phone.raw_value\">Phone: <t t-esc=\"record.phone.value\"/></div>\n                                                    <div t-if=\"record.mobile.raw_value\">Mobile: <t t-esc=\"record.mobile.value\"/></div>\n                                                </div>\n                                            </div>\n                                        </t>\n                                    </templates>\n                                </kanban>\n                                <form string=\"Contact / Address\">\n                                    <sheet>\n                                        <field name=\"type\" required=\"1\" widget=\"radio\" options=\"{''horizontal'': true}\"/>\n                                        <field name=\"parent_id\" invisible=\"1\"/>\n                                        <div class=\"text-muted oe_edit_only\">\n                                            <p class=\"mb-0\" invisible=\"type != ''contact''\">\n                                                <span>Use this to organize the contact details of employees of a given company (e.g. CEO, CFO, ...).</span>\n                                            </p>\n                                            <p class=\"mb-0\" invisible=\"type != ''invoice''\">\n                                                <span>Preferred address for all invoices. Selected by default when you invoice an order that belongs to this company.</span>\n                                            </p>\n                                            <p class=\"mb-0\" invisible=\"type != ''delivery''\">\n                                                <span>Preferred address for all deliveries. Selected by default when you deliver an order that belongs to this company.</span>\n                                            </p>\n                                            <p class=\"mb-0\" invisible=\"type != ''other''\">\n                                                <span>Other address for the company (e.g. subsidiary, ...)</span>\n                                            </p>\n                                        </div>\n                                        <hr/>\n                                        <group>\n                                            <group>\n                                                <field name=\"name\" string=\"Contact Name\" required=\"type == ''contact''\"/>\n                                                <field name=\"title\" options=\"{''no_open'': True}\" placeholder=\"e.g. Mr.\" invisible=\"type != ''contact''\"/>\n                                                <field name=\"function\" placeholder=\"e.g. Sales Director\" invisible=\"type != ''contact''\"/>\n                                                <label for=\"street\" string=\"Address\" invisible=\"type == ''contact''\"/>\n                                                <div invisible=\"type == ''contact''\">\n                                                    <div class=\"o_address_format\" name=\"div_address\">\n                                                        <field name=\"street\" placeholder=\"Street...\" class=\"o_address_street\"/>\n                                                        <field name=\"street2\" placeholder=\"Street 2...\" class=\"o_address_street\"/>\n                                                        <field name=\"city\" placeholder=\"City\" class=\"o_address_city\"/>\n                                                        <field name=\"state_id\" class=\"o_address_state\" placeholder=\"State\" options=\"{''no_open'': True, ''no_quick_create'': True}\" context=\"{''country_id'': country_id, ''default_country_id'': country_id, ''zip'': zip}\"/>\n                                                        <field name=\"zip\" placeholder=\"ZIP\" class=\"o_address_zip\"/>\n                                                        <field name=\"country_id\" placeholder=\"Country\" class=\"o_address_country\" options=\"{&quot;no_open&quot;: True, &quot;no_create&quot;: True}\"/>\n                                                    </div>\n                                                </div>\n                                            </group>\n                                            <group>\n                                                <field name=\"email\" widget=\"email\"/>\n                                                <field name=\"phone\" widget=\"phone\"/>\n                                                <field name=\"mobile\" widget=\"phone\"/>\n                                                <field name=\"company_id\" invisible=\"1\"/>\n                                            </group>\n                                        </group>\n                                        <group>\n                                            <field name=\"comment\" placeholder=\"Internal notes...\" nolabel=\"1\" colspan=\"2\"/>\n                                        </group>\n                                        <field name=\"lang\" invisible=\"True\"/>\n                                        <field name=\"user_id\" invisible=\"True\"/>\n                                    </sheet>\n                                </form>\n                            </field>\n                        </page>\n                        <page name=\"sales_purchases\" string=\"Sales &amp; Purchase\">\n                            <group name=\"container_row_2\">\n                                <group string=\"Sales\" name=\"sale\" priority=\"1\">\n                                    <field name=\"user_id\" widget=\"many2one_avatar_user\" domain=\"[(''share'', ''='', False)]\"/>\n                                </group>\n                                <group string=\"Purchase\" name=\"purchase\" priority=\"2\">\n                                </group>\n                                <group name=\"misc\" string=\"Misc\">\n                                    <field name=\"company_registry\" invisible=\"parent_id\"/>\n                                    <field name=\"ref\" string=\"Reference\"/>\n                                    <field name=\"company_id\" groups=\"base.group_multi_company\" options=\"{''no_create'': True}\" readonly=\"parent_id\" force_save=\"1\"/>\n                                    <field name=\"industry_id\" invisible=\"not is_company\" options=\"{''no_create'': True}\"/>\n                                </group>\n                            </group>\n                        </page>\n                        <page name=\"internal_notes\" string=\"Internal Notes\">\n                            <field name=\"comment\" placeholder=\"Internal notes...\"/>\n                        </page>\n                    </notebook>\n                </sheet>\n                </form>"}', '<?xml version="1.0"?>
<form string="Partners">
                <div class="alert alert-warning oe_edit_only" role="alert" name="warning_tax" invisible="not same_vat_partner_id">
                  A partner with the same <span><span class="o_vat_label">Tax ID</span></span> already exists (<field name="same_vat_partner_id" context="{''show_address'': False, ''show_vat'': False}"/>), are you sure to create a new one?
                </div>
                <div class="alert alert-warning oe_edit_only" role="alert" name="warning_company" invisible="not same_company_registry_partner_id">
                  A partner with the same <span><span class="o_vat_label">Company Registry</span></span> already exists (<field name="same_company_registry_partner_id" context="{''show_address'': False, ''show_vat'': False}"/>), are you sure to create a new one?
                </div>
                <sheet>
                    <div class="oe_button_box" name="button_box"/>
                    <widget name="web_ribbon" title="Archived" bg_color="text-bg-danger" invisible="active"/>
                    <field name="avatar_128" invisible="1"/>
                    <field name="image_1920" widget="image" class="oe_avatar" options="{&quot;preview_image&quot;: &quot;avatar_128&quot;}"/>
                    <div class="oe_title mb24">
                        <field name="is_company" invisible="1"/>
                        <field name="commercial_partner_id" invisible="1"/>
                        <field name="active" invisible="1"/>
                        <field name="company_id" invisible="1"/>
                        <field name="country_code" invisible="1"/>
                        <field name="company_type" widget="radio" options="{''horizontal'': true}"/>
                        <h1>
                            <field id="company" options="{''line_breaks'': False}" widget="text" class="text-break" name="name" default_focus="1" placeholder="e.g. Lumber Inc" invisible="not is_company" required="type == ''contact''"/>
                            <field id="individual" options="{''line_breaks'': False}" widget="text" class="text-break" name="name" default_focus="1" placeholder="e.g. Brandom Freeman" invisible="is_company" required="type == ''contact''"/>
                        </h1>
                        <div class="o_row">
                            <field name="parent_id" widget="res_partner_many2one" placeholder="Company Name..." domain="[(''is_company'', ''='', True)]" context="{''default_is_company'': True, ''show_vat'': True, ''default_user_id'': user_id}" invisible="((is_company and not parent_id) or company_name) and company_name != ''''"/>
                                <field name="company_name" invisible="not company_name or company_name == '''' or is_company"/>
                                <button name="create_company" icon="fa-plus-square" string="Create company" type="object" class="oe_edit_only btn-link" invisible="is_company or company_name == '''' or not company_name"/>
                        </div>
                    </div>

                    <group>
                        <group>
                            <span class="o_form_label o_td_label" name="address_name">
                                <field name="type" invisible="is_company" readonly="user_ids" required="not is_company" class="fw-bold"/>
                                <b invisible="not is_company">Address</b>
                            </span>
                            <div class="o_address_format">
                                <field name="street" placeholder="Street..." class="o_address_street" readonly="type == ''contact'' and parent_id"/>
                                <field name="street2" placeholder="Street 2..." class="o_address_street" readonly="type == ''contact'' and parent_id"/>
                                <field name="city" placeholder="City" class="o_address_city" readonly="type == ''contact'' and parent_id"/>
                                <field name="state_id" class="o_address_state" placeholder="State" options="{''no_open'': True, ''no_quick_create'': True}" readonly="type == ''contact'' and parent_id" context="{''country_id'': country_id, ''default_country_id'': country_id, ''zip'': zip}"/>
                                <field name="zip" placeholder="ZIP" class="o_address_zip" readonly="type == ''contact'' and parent_id"/>
                                <div name="partner_address_country" class="d-flex justify-content-between">
                                    <field name="country_id" placeholder="Country" class="o_address_country" options="{&quot;no_open&quot;: True, &quot;no_create&quot;: True}" readonly="type == ''contact'' and parent_id"/>
                                </div>
                            </div>
                            <field name="vat" placeholder="e.g. BE0477472701" readonly="parent_id"/>
                        </group>
                        <group>
                            <field name="function" placeholder="e.g. Sales Director" invisible="is_company"/>
                            <field name="phone" widget="phone"/>
                            <field name="mobile" widget="phone"/>
                            <field name="user_ids" invisible="1"/>
                            <field name="email" widget="email" context="{''gravatar_image'': True}" required="user_ids"/>
                            <field name="website" string="Website" widget="url" placeholder="e.g. https://www.odoo.com"/>
                            <field name="title" options="{&quot;no_open&quot;: True}" placeholder="e.g. Mister" invisible="is_company"/>
                            <field name="active_lang_count" invisible="1"/>
                            <field name="lang" invisible="active_lang_count &lt;= 1"/>
                            <field name="category_id" widget="many2many_tags" options="{''color_field'': ''color'', ''no_create_edit'': True}" placeholder="e.g. &quot;B2B&quot;, &quot;VIP&quot;, &quot;Consulting&quot;, ..."/>
                        </group>
                    </group>

                    <notebook colspan="4">
                        <page string="Contacts &amp; Addresses" name="contact_addresses" autofocus="autofocus">
                            <field name="child_ids" mode="kanban" context="{''default_parent_id'': id, ''default_street'': street, ''default_street2'': street2, ''default_city'': city, ''default_state_id'': state_id, ''default_zip'': zip, ''default_country_id'': country_id, ''default_lang'': lang, ''default_user_id'': user_id, ''default_type'': ''other''}">
                                <kanban>
                                    <field name="id"/>
                                    <field name="color"/>
                                    <field name="name"/>
                                    <field name="title"/>
                                    <field name="type"/>
                                    <field name="email"/>
                                    <field name="parent_id"/>
                                    <field name="is_company"/>
                                    <field name="function"/>
                                    <field name="phone"/>
                                    <field name="street"/>
                                    <field name="street2"/>
                                    <field name="zip"/>
                                    <field name="city"/>
                                    <field name="country_id"/>
                                    <field name="mobile"/>
                                    <field name="state_id"/>
                                    <field name="image_128"/>
                                    <field name="avatar_128"/>
                                    <field name="lang"/>
                                    <!-- fields in form x2many view to diminish requests -->
                                    <field name="comment"/>
                                    <field name="display_name"/>
                                    <templates>
                                        <t t-name="kanban-box">
                                            <t t-set="color" t-value="kanban_color(record.color.raw_value)"/>
                                            <div t-att-class="color + (record.title.raw_value == 1 ? '' oe_kanban_color_alert'' : '''') + '' oe_kanban_global_click''">
                                                <div class="o_kanban_image">
                                                    <img alt="Contact image" t-att-src="kanban_image(''res.partner'', ''avatar_128'', record.id.raw_value)"/>
                                                </div>
                                                <div class="oe_kanban_details">
                                                    <field name="name"/>
                                                    <div t-if="record.function.raw_value"><field name="function"/></div>
                                                    <div t-if="record.email.raw_value"><field name="email" widget="email"/></div>
                                                    <div t-if="record.type.raw_value != ''contact''">
                                                        <div>
                                                            <field name="zip"/><t t-if="record.city"> </t>
                                                            <field name="city"/>
                                                        </div>
                                                        <field t-if="record.state_id.raw_value" name="state_id"/><t t-if="record.country_id"> </t>
                                                        <field name="country_id"/>
                                                    </div>
                                                    <div t-if="record.phone.raw_value">Phone: <t t-esc="record.phone.value"/></div>
                                                    <div t-if="record.mobile.raw_value">Mobile: <t t-esc="record.mobile.value"/></div>
                                                </div>
                                            </div>
                                        </t>
                                    </templates>
                                </kanban>
                                <form string="Contact / Address">
                                    <sheet>
                                        <field name="type" required="1" widget="radio" options="{''horizontal'': true}"/>
                                        <field name="parent_id" invisible="1"/>
                                        <div class="text-muted oe_edit_only">
                                            <p class="mb-0" invisible="type != ''contact''">
                                                <span>Use this to organize the contact details of employees of a given company (e.g. CEO, CFO, ...).</span>
                                            </p>
                                            <p class="mb-0" invisible="type != ''invoice''">
                                                <span>Preferred address for all invoices. Selected by default when you invoice an order that belongs to this company.</span>
                                            </p>
                                            <p class="mb-0" invisible="type != ''delivery''">
                                                <span>Preferred address for all deliveries. Selected by default when you deliver an order that belongs to this company.</span>
                                            </p>
                                            <p class="mb-0" invisible="type != ''other''">
                                                <span>Other address for the company (e.g. subsidiary, ...)</span>
                                            </p>
                                        </div>
                                        <hr/>
                                        <group>
                                            <group>
                                                <field name="name" string="Contact Name" required="type == ''contact''"/>
                                                <field name="title" options="{''no_open'': True}" placeholder="e.g. Mr." invisible="type != ''contact''"/>
                                                <field name="function" placeholder="e.g. Sales Director" invisible="type != ''contact''"/>
                                                <label for="street" string="Address" invisible="type == ''contact''"/>
                                                <div invisible="type == ''contact''">
                                                    <div class="o_address_format" name="div_address">
                                                        <field name="street" placeholder="Street..." class="o_address_street"/>
                                                        <field name="street2" placeholder="Street 2..." class="o_address_street"/>
                                                        <field name="city" placeholder="City" class="o_address_city"/>
                                                        <field name="state_id" class="o_address_state" placeholder="State" options="{''no_open'': True, ''no_quick_create'': True}" context="{''country_id'': country_id, ''default_country_id'': country_id, ''zip'': zip}"/>
                                                        <field name="zip" placeholder="ZIP" class="o_address_zip"/>
                                                        <field name="country_id" placeholder="Country" class="o_address_country" options="{&quot;no_open&quot;: True, &quot;no_create&quot;: True}"/>
                                                    </div>
                                                </div>
                                            </group>
                                            <group>
                                                <field name="email" widget="email"/>
                                                <field name="phone" widget="phone"/>
                                                <field name="mobile" widget="phone"/>
                                                <field name="company_id" invisible="1"/>
                                            </group>
                                        </group>
                                        <group>
                                            <field name="comment" placeholder="Internal notes..." nolabel="1" colspan="2"/>
                                        </group>
                                        <field name="lang" invisible="True"/>
                                        <field name="user_id" invisible="True"/>
                                    </sheet>
                                </form>
                            </field>
                        </page>
                        <page name="sales_purchases" string="Sales &amp; Purchase">
                            <group name="container_row_2">
                                <group string="Sales" name="sale" priority="1">
                                    <field name="user_id" widget="many2one_avatar_user" domain="[(''share'', ''='', False)]"/>
                                </group>
                                <group string="Purchase" name="purchase" priority="2">
                                </group>
                                <group name="misc" string="Misc">
                                    <field name="company_registry" invisible="parent_id"/>
                                    <field name="ref" string="Reference"/>
                                    <field name="company_id" groups="base.group_multi_company" options="{''no_create'': True}" readonly="parent_id" force_save="1"/>
                                    <field name="industry_id" invisible="not is_company" options="{''no_create'': True}"/>
                                </group>
                            </group>
                        </page>
                        <page name="internal_notes" string="Internal Notes">
                            <field name="comment" placeholder="Internal notes..."/>
                        </page>
                    </notebook>
                </sheet>
                </form>
            ', false, true, '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872', NULL);
INSERT INTO public.ir_ui_view VALUES (126, 300, NULL, 1, 1, 'res.partner.view.form.private', 'res.partner', NULL, 'form', 'base/views/res_partner_views.xml', 'primary', '{"en_US": "<form string=\"Private Address Form\">\n                    <sheet>\n                        <field name=\"type\" invisible=\"1\"/>\n                        <field name=\"parent_id\" invisible=\"1\"/>\n                        <label for=\"name\" class=\"oe_edit_only\"/>\n                        <field name=\"name\" required=\"0\"/>\n                        <group>\n                            <group>\n                                <label for=\"street\" string=\"Address\"/>\n                                <div>\n                                    <div class=\"o_address_format\" name=\"div_address\">\n                                        <field name=\"street\" placeholder=\"Street...\" class=\"o_address_street\"/>\n                                        <field name=\"street2\" placeholder=\"Street 2...\" class=\"o_address_street\"/>\n                                        <field name=\"city\" placeholder=\"City\" class=\"o_address_city\"/>\n                                        <field name=\"state_id\" class=\"o_address_state\" placeholder=\"State\" options=\"{''no_open'': True, ''no_quick_create'': True}\" context=\"{''country_id'': country_id, ''default_country_id'': country_id, ''zip'': zip}\"/>\n                                        <field name=\"zip\" placeholder=\"ZIP\" class=\"o_address_zip\"/>\n                                        <field name=\"country_id\" placeholder=\"Country\" class=\"o_address_country\" options=\"{&quot;no_open&quot;: True, &quot;no_create&quot;: True}\"/>\n                                    </div>\n                                </div>\n                            </group>\n                            <group>\n                                <field name=\"phone\" widget=\"phone\" options=\"{''enable_sms'': false}\"/>\n                                <field name=\"mobile\" widget=\"phone\" options=\"{''enable_sms'': false}\"/>\n                                <field name=\"email\"/>\n                                <field name=\"lang\"/>\n                            </group>\n                        </group>\n                        <group string=\"Bank Accounts\">\n                            <field name=\"bank_ids\">\n                                <tree editable=\"bottom\">\n                                    <field name=\"bank_id\"/>\n                                    <field name=\"acc_number\"/>\n                                    <field name=\"acc_holder_name\" column_invisible=\"True\"/>\n                                </tree>\n                            </field>\n                        </group>\n                    </sheet>\n                </form>"}', '<?xml version="1.0"?>
<form string="Private Address Form">
                    <sheet>
                        <field name="type" invisible="1"/>
                        <field name="parent_id" invisible="1"/>
                        <label for="name" class="oe_edit_only"/>
                        <field name="name" required="0"/>
                        <group>
                            <group>
                                <label for="street" string="Address"/>
                                <div>
                                    <div class="o_address_format" name="div_address">
                                        <field name="street" placeholder="Street..." class="o_address_street"/>
                                        <field name="street2" placeholder="Street 2..." class="o_address_street"/>
                                        <field name="city" placeholder="City" class="o_address_city"/>
                                        <field name="state_id" class="o_address_state" placeholder="State" options="{''no_open'': True, ''no_quick_create'': True}" context="{''country_id'': country_id, ''default_country_id'': country_id, ''zip'': zip}"/>
                                        <field name="zip" placeholder="ZIP" class="o_address_zip"/>
                                        <field name="country_id" placeholder="Country" class="o_address_country" options="{&quot;no_open&quot;: True, &quot;no_create&quot;: True}"/>
                                    </div>
                                </div>
                            </group>
                            <group>
                                <field name="phone" widget="phone" options="{''enable_sms'': false}"/>
                                <field name="mobile" widget="phone" options="{''enable_sms'': false}"/>
                                <field name="email"/>
                                <field name="lang"/>
                            </group>
                        </group>
                        <group string="Bank Accounts">
                            <field name="bank_ids">
                                <tree editable="bottom">
                                    <field name="bank_id"/>
                                    <field name="acc_number"/>
                                    <field name="acc_holder_name" column_invisible="True"/>
                                </tree>
                            </field>
                        </group>
                    </sheet>
                </form>
            ', false, true, '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872', NULL);
INSERT INTO public.ir_ui_view VALUES (127, 16, NULL, 1, 1, 'res.partner.select', 'res.partner', NULL, 'search', 'base/views/res_partner_views.xml', 'primary', '{"en_US": "<search string=\"Search Partner\">\n                    <field name=\"name\" filter_domain=\"[''|'', ''|'', ''|'', ''|'', (''complete_name'', ''ilike'', self), (''ref'', ''ilike'', self), (''email'', ''ilike'', self), (''vat'', ''ilike'', self), (''company_registry'', ''ilike'', self)]\"/>\n                    <field name=\"parent_id\" domain=\"[(''is_company'', ''='', True)]\" operator=\"child_of\"/>\n                    <field name=\"email\" filter_domain=\"[(''email'', ''ilike'', self)]\"/>\n                    <field name=\"phone\" filter_domain=\"[''|'', (''phone'', ''ilike'', self), (''mobile'', ''ilike'', self)]\"/>\n                    <field name=\"category_id\" string=\"Tag\" operator=\"child_of\"/>\n                    <field name=\"user_id\"/>\n                    <separator/>\n                    <filter string=\"Individuals\" name=\"type_person\" domain=\"[(''is_company'', ''='', False)]\"/>\n                    <filter string=\"Companies\" name=\"type_company\" domain=\"[(''is_company'', ''='', True)]\"/>\n                    <separator/>\n                    <filter string=\"Archived\" name=\"inactive\" domain=\"[(''active'', ''='', False)]\"/>\n                    <separator/>\n                    <group expand=\"0\" name=\"group_by\" string=\"Group By\">\n                        <filter name=\"salesperson\" string=\"Salesperson\" domain=\"[]\" context=\"{''group_by'' : ''user_id''}\"/>\n                        <filter name=\"group_company\" string=\"Company\" context=\"{''group_by'': ''parent_id''}\"/>\n                        <filter name=\"group_country\" string=\"Country\" context=\"{''group_by'': ''country_id''}\"/>\n                    </group>\n                </search>"}', '<?xml version="1.0"?>
<search string="Search Partner">
                    <field name="name" filter_domain="[''|'', ''|'', ''|'', ''|'', (''complete_name'', ''ilike'', self), (''ref'', ''ilike'', self), (''email'', ''ilike'', self), (''vat'', ''ilike'', self), (''company_registry'', ''ilike'', self)]"/>
                    <field name="parent_id" domain="[(''is_company'', ''='', True)]" operator="child_of"/>
                    <field name="email" filter_domain="[(''email'', ''ilike'', self)]"/>
                    <field name="phone" filter_domain="[''|'', (''phone'', ''ilike'', self), (''mobile'', ''ilike'', self)]"/>
                    <field name="category_id" string="Tag" operator="child_of"/>
                    <field name="user_id"/>
                    <separator/>
                    <filter string="Individuals" name="type_person" domain="[(''is_company'', ''='', False)]"/>
                    <filter string="Companies" name="type_company" domain="[(''is_company'', ''='', True)]"/>
                    <separator/>
                    <filter string="Archived" name="inactive" domain="[(''active'', ''='', False)]"/>
                    <separator/>
                    <group expand="0" name="group_by" string="Group By">
                        <filter name="salesperson" string="Salesperson" domain="[]" context="{''group_by'' : ''user_id''}"/>
                        <filter name="group_company" string="Company" context="{''group_by'': ''parent_id''}"/>
                        <filter name="group_country" string="Country" context="{''group_by'': ''country_id''}"/>
                    </group>
                </search>
            ', false, true, '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872', NULL);
INSERT INTO public.ir_ui_view VALUES (128, 16, NULL, 1, 1, 'res.partner.kanban', 'res.partner', NULL, 'kanban', 'base/views/res_partner_views.xml', 'primary', '{"en_US": "<kanban sample=\"1\">\n                    <field name=\"id\"/>\n                    <field name=\"color\"/>\n                    <field name=\"display_name\"/>\n                    <field name=\"title\"/>\n                    <field name=\"email\"/>\n                    <field name=\"parent_id\"/>\n                    <field name=\"is_company\"/>\n                    <field name=\"function\"/>\n                    <field name=\"phone\"/>\n                    <field name=\"street\"/>\n                    <field name=\"street2\"/>\n                    <field name=\"zip\"/>\n                    <field name=\"city\"/>\n                    <field name=\"country_id\"/>\n                    <field name=\"mobile\"/>\n                    <field name=\"state_id\"/>\n                    <field name=\"category_id\"/>\n                    <field name=\"avatar_128\"/>\n                    <field name=\"type\"/>\n                    <field name=\"active\"/>\n                    <templates>\n                        <t t-name=\"kanban-box\">\n                            <div class=\"oe_kanban_global_click o_kanban_record_has_image_fill o_res_partner_kanban\">\n                                <t t-if=\"!record.is_company.raw_value\">\n                                    <t t-set=\"avatar_image\" t-value=\"kanban_image(''res.partner'', ''avatar_128'', record.id.raw_value)\"/>\n                                    <div class=\"o_kanban_image_fill_left d-none d-md-block\">\n                                        <img t-attf-src=\"#{avatar_image}\" t-att-alt=\"record.id.value\"/>\n                                        <img class=\"o_kanban_image_inner_pic\" t-if=\"record.parent_id.raw_value\" t-att-alt=\"record.parent_id.value\" t-att-src=\"kanban_image(''res.partner'', ''avatar_128'', record.parent_id.raw_value)\"/>\n                                    </div>\n                                    <div class=\"o_kanban_image d-md-none d-block\">\n                                        <img t-attf-src=\"#{avatar_image}\" t-att-alt=\"record.id.value\"/>\n                                        <img class=\"o_kanban_image_inner_pic\" t-if=\"record.parent_id.raw_value\" t-att-alt=\"record.parent_id.value\" t-att-src=\"kanban_image(''res.partner'', ''avatar_128'', record.parent_id.raw_value)\"/>\n                                    </div>\n                                </t>\n                                <t t-else=\"\">\n                                    <div class=\"o_kanban_image_fill_left d-none d-md-block o_kanban_image_full\">\n                                        <img t-attf-src=\"#{kanban_image(''res.partner'', ''avatar_128'', record.id.raw_value)}\" role=\"img\" t-att-alt=\"record.id.value\"/>\n                                    </div>\n                                    <div class=\"o_kanban_image d-md-none d-block o_kanban_image_full\">\n                                        <img t-attf-src=\"#{kanban_image(''res.partner'', ''avatar_128'', record.id.raw_value)}\" role=\"img\" t-att-alt=\"record.id.value\"/>\n                                    </div>\n                                </t>\n                                <div class=\"ribbon ribbon-top-right\" invisible=\"active\">\n                                    <span class=\"text-bg-danger\">Archived</span>\n                                </div>\n                                <div class=\"oe_kanban_details d-flex flex-column justify-content-between\">\n                                    <div>\n                                        <strong class=\"o_kanban_record_title oe_partner_heading\"><field name=\"display_name\"/></strong>\n                                        <div class=\"o_kanban_tags_section oe_kanban_partner_categories\"/>\n                                        <ul>\n                                            <li t-if=\"record.parent_id.raw_value and !record.function.raw_value\"><field name=\"parent_id\"/></li>\n                                            <li t-elif=\"!record.parent_id.raw_value and record.function.raw_value\"><field name=\"function\"/></li>\n                                            <li t-elif=\"record.parent_id.raw_value and record.function.raw_value\"><field name=\"function\"/> at <field name=\"parent_id\"/></li>\n                                            <li t-if=\"record.city.raw_value or record.country_id.raw_value\">\n                                                <t t-if=\"record.city.raw_value\"><field name=\"city\"/><t t-if=\"record.country_id.raw_value\">, </t></t>\n                                                <t t-if=\"record.country_id.raw_value\"><field name=\"country_id\"/></t>\n                                            </li>\n                                            <li t-if=\"record.email.raw_value\" class=\"o_text_overflow\"><field name=\"email\"/></li>\n                                        </ul>\n                                    </div>\n                                    <div class=\"o_kanban_record_bottom\">\n                                        <div class=\"oe_kanban_bottom_left\"/>\n                                        <div class=\"oe_kanban_bottom_right\"/>\n                                    </div>\n                                </div>\n                            </div>\n                        </t>\n                    </templates>\n                </kanban>"}', '<?xml version="1.0"?>
<kanban sample="1">
                    <field name="id"/>
                    <field name="color"/>
                    <field name="display_name"/>
                    <field name="title"/>
                    <field name="email"/>
                    <field name="parent_id"/>
                    <field name="is_company"/>
                    <field name="function"/>
                    <field name="phone"/>
                    <field name="street"/>
                    <field name="street2"/>
                    <field name="zip"/>
                    <field name="city"/>
                    <field name="country_id"/>
                    <field name="mobile"/>
                    <field name="state_id"/>
                    <field name="category_id"/>
                    <field name="avatar_128"/>
                    <field name="type"/>
                    <field name="active"/>
                    <templates>
                        <t t-name="kanban-box">
                            <div class="oe_kanban_global_click o_kanban_record_has_image_fill o_res_partner_kanban">
                                <t t-if="!record.is_company.raw_value">
                                    <t t-set="avatar_image" t-value="kanban_image(''res.partner'', ''avatar_128'', record.id.raw_value)"/>
                                    <div class="o_kanban_image_fill_left d-none d-md-block">
                                        <img t-attf-src="#{avatar_image}" t-att-alt="record.id.value"/>
                                        <img class="o_kanban_image_inner_pic" t-if="record.parent_id.raw_value" t-att-alt="record.parent_id.value" t-att-src="kanban_image(''res.partner'', ''avatar_128'', record.parent_id.raw_value)"/>
                                    </div>
                                    <div class="o_kanban_image d-md-none d-block">
                                        <img t-attf-src="#{avatar_image}" t-att-alt="record.id.value"/>
                                        <img class="o_kanban_image_inner_pic" t-if="record.parent_id.raw_value" t-att-alt="record.parent_id.value" t-att-src="kanban_image(''res.partner'', ''avatar_128'', record.parent_id.raw_value)"/>
                                    </div>
                                </t>
                                <t t-else="">
                                    <div class="o_kanban_image_fill_left d-none d-md-block o_kanban_image_full">
                                        <img t-attf-src="#{kanban_image(''res.partner'', ''avatar_128'', record.id.raw_value)}" role="img" t-att-alt="record.id.value"/>
                                    </div>
                                    <div class="o_kanban_image d-md-none d-block o_kanban_image_full">
                                        <img t-attf-src="#{kanban_image(''res.partner'', ''avatar_128'', record.id.raw_value)}" role="img" t-att-alt="record.id.value"/>
                                    </div>
                                </t>
                                <div class="ribbon ribbon-top-right" invisible="active">
                                    <span class="text-bg-danger">Archived</span>
                                </div>
                                <div class="oe_kanban_details d-flex flex-column justify-content-between">
                                    <div>
                                        <strong class="o_kanban_record_title oe_partner_heading"><field name="display_name"/></strong>
                                        <div class="o_kanban_tags_section oe_kanban_partner_categories"/>
                                        <ul>
                                            <li t-if="record.parent_id.raw_value and !record.function.raw_value"><field name="parent_id"/></li>
                                            <li t-elif="!record.parent_id.raw_value and record.function.raw_value"><field name="function"/></li>
                                            <li t-elif="record.parent_id.raw_value and record.function.raw_value"><field name="function"/> at <field name="parent_id"/></li>
                                            <li t-if="record.city.raw_value or record.country_id.raw_value">
                                                <t t-if="record.city.raw_value"><field name="city"/><t t-if="record.country_id.raw_value">, </t></t>
                                                <t t-if="record.country_id.raw_value"><field name="country_id"/></t>
                                            </li>
                                            <li t-if="record.email.raw_value" class="o_text_overflow"><field name="email"/></li>
                                        </ul>
                                    </div>
                                    <div class="o_kanban_record_bottom">
                                        <div class="oe_kanban_bottom_left"/>
                                        <div class="oe_kanban_bottom_right"/>
                                    </div>
                                </div>
                            </div>
                        </t>
                    </templates>
                </kanban>
            ', false, true, '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872', NULL);
INSERT INTO public.ir_ui_view VALUES (132, 16, NULL, 1, 1, 'Industry', 'res.partner.industry', NULL, 'form', 'base/views/res_partner_views.xml', 'primary', '{"en_US": "<form string=\"Industry\">\n                    <sheet>\n                        <group col=\"4\">\n                            <field name=\"name\"/>\n                            <field name=\"full_name\"/>\n                            <field name=\"active\" widget=\"boolean_toggle\"/>\n                        </group>\n                    </sheet>\n                </form>"}', '<?xml version="1.0"?>
