INSERT INTO public.ir_ui_view VALUES (135, 16, NULL, 1, 1, 'res.bank.form', 'res.bank', NULL, 'form', 'base/views/res_bank_views.xml', 'primary', '{"en_US": "<form string=\"Bank\">\n                    <sheet>\n                        <widget name=\"web_ribbon\" title=\"Archived\" bg_color=\"text-bg-danger\" invisible=\"active\"/>\n                        <group name=\"bank_details\" col=\"4\">\n                            <field name=\"name\"/>\n                            <field name=\"bic\"/>\n                        </group>\n                        <group>\n                            <group name=\"address_details\">\n                                <label for=\"street\" string=\"Bank Address\"/>\n                                <div class=\"o_address_format\">\n                                    <field name=\"street\" placeholder=\"Street...\" class=\"o_address_street\"/>\n                                    <field name=\"street2\" placeholder=\"Street 2...\" class=\"o_address_street\"/>\n                                    <field name=\"city\" placeholder=\"City\" class=\"o_address_city\"/>\n                                    <field name=\"state\" class=\"o_address_state\" placeholder=\"State\" options=\"{&quot;no_open&quot;: True}\"/>\n                                    <field name=\"zip\" placeholder=\"ZIP\" class=\"o_address_zip\"/>\n                                    <field name=\"country\" placeholder=\"Country\" class=\"o_address_country\" options=\"{&quot;no_open&quot;: True, &quot;no_create&quot;: True}\"/>\n                                </div>\n                            </group>\n                            <group name=\"communication_details\">\n                                <field name=\"phone\" class=\"o_force_ltr\"/>\n                                <field name=\"email\" widget=\"email\"/>\n                                <field name=\"active\" invisible=\"1\"/>\n                            </group>\n                        </group>\n                    </sheet>\n                </form>"}', '<?xml version="1.0"?>
<form string="Bank">
                    <sheet>
                        <widget name="web_ribbon" title="Archived" bg_color="text-bg-danger" invisible="active"/>
                        <group name="bank_details" col="4">
                            <field name="name"/>
                            <field name="bic"/>
                        </group>
                        <group>
                            <group name="address_details">
                                <label for="street" string="Bank Address"/>
                                <div class="o_address_format">
                                    <field name="street" placeholder="Street..." class="o_address_street"/>
                                    <field name="street2" placeholder="Street 2..." class="o_address_street"/>
                                    <field name="city" placeholder="City" class="o_address_city"/>
                                    <field name="state" class="o_address_state" placeholder="State" options="{&quot;no_open&quot;: True}"/>
                                    <field name="zip" placeholder="ZIP" class="o_address_zip"/>
                                    <field name="country" placeholder="Country" class="o_address_country" options="{&quot;no_open&quot;: True, &quot;no_create&quot;: True}"/>
                                </div>
                            </group>
                            <group name="communication_details">
                                <field name="phone" class="o_force_ltr"/>
                                <field name="email" widget="email"/>
                                <field name="active" invisible="1"/>
                            </group>
                        </group>
                    </sheet>
                </form>
            ', false, true, '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872', NULL);
INSERT INTO public.ir_ui_view VALUES (136, 16, NULL, 1, 1, 'res.bank.tree', 'res.bank', NULL, 'tree', 'base/views/res_bank_views.xml', 'primary', '{"en_US": "<tree string=\"Banks\">\n                    <field name=\"name\"/>\n                    <field name=\"bic\"/>\n                    <field name=\"country\"/>\n                </tree>"}', '<?xml version="1.0"?>
<tree string="Banks">
