INSERT INTO public.ir_ui_view VALUES (138, 15, NULL, 1, 1, 'res.partner.bank.form', 'res.partner.bank', NULL, 'form', 'base/views/res_bank_views.xml', 'primary', '{"en_US": "<form string=\"Bank account\" name=\"bank_account_form\">\n                <sheet>\n                    <widget name=\"web_ribbon\" title=\"Archived\" bg_color=\"text-bg-danger\" invisible=\"active\"/>\n                    <group>\n                        <group>\n                            <field name=\"sequence\" invisible=\"1\"/>\n                            <field name=\"acc_type\" invisible=\"1\"/>\n                            <field name=\"acc_number\"/>\n                            <field name=\"bank_id\"/>\n                            <field name=\"acc_holder_name\"/>\n                            <field name=\"partner_id\"/>\n                        </group>\n                        <group>\n                            <field name=\"company_id\" groups=\"base.group_multi_company\" options=\"{''no_create'': True}\"/>\n                            <field name=\"currency_id\" groups=\"base.group_multi_currency\" options=\"{''no_create'': True}\"/>\n                            <field name=\"allow_out_payment\" widget=\"boolean_toggle\"/>\n                            <field name=\"active\" invisible=\"1\"/>\n                        </group>\n                    </group>\n                </sheet>\n                </form>"}', '<?xml version="1.0"?>
