INSERT INTO public.ir_ui_view VALUES (139, 16, NULL, 1, 1, 'res.partner.bank.tree', 'res.partner.bank', NULL, 'tree', 'base/views/res_bank_views.xml', 'primary', '{"en_US": "<tree string=\"Bank Accounts\" multi_edit=\"1\">\n                    <field name=\"sequence\" widget=\"handle\"/>\n                    <field name=\"acc_number\"/>\n                    <field name=\"bank_name\" string=\"Bank\"/>\n                    <field name=\"company_id\" groups=\"base.group_multi_company\"/>\n                    <field name=\"partner_id\"/>\n                    <field name=\"acc_holder_name\" column_invisible=\"True\"/>\n                    <field name=\"allow_out_payment\" widget=\"boolean_toggle\"/>\n                </tree>"}', '<?xml version="1.0"?>
