INSERT INTO public.ir_ui_view VALUES (142, 16, NULL, 1, 1, 'res.country.form', 'res.country', NULL, 'form', 'base/views/res_country_views.xml', 'primary', '{"en_US": "<form create=\"0\" delete=\"0\">\n                    <sheet>\n                        <div class=\"oe_button_box\" name=\"button_box\">\n                        </div>\n                        <field name=\"image_url\" widget=\"image_url\" class=\"oe_avatar\" options=\"{''size'': [128,128]}\"/>\n                        <group name=\"main_group\">\n                            <group name=\"country_details\">\n                                <field name=\"name\"/>\n                                <field name=\"currency_id\"/>\n                                <field name=\"code\"/>\n                            </group>\n                            <group name=\"phone_vat_settings\">\n                                <field name=\"phone_code\" options=\"{''format'': false}\"/>\n                                <field name=\"vat_label\"/>\n                                <field name=\"zip_required\"/>\n                                <field name=\"state_required\"/>\n                            </group>\n                        </group>\n                        <group name=\"advanced_address_formatting\" string=\"Advanced Address Formatting\" groups=\"base.group_no_one\">\n                            <label for=\"address_view_id\"/>\n                            <div class=\"o_row\">\n                                <field name=\"address_view_id\"/>\n                                <div class=\"text-muted ms-2\">Choose a subview of partners that includes only address fields, to change the way users can input addresses.</div>\n                            </div>\n                            <label for=\"address_format\"/>\n                            <div class=\"o_row\">\n                                <field name=\"address_format\" placeholder=\"Address format...\"/>\n                                <div name=\"div_address_format ms-2\" class=\"text-muted\">Change the way addresses are displayed in reports</div>\n                            </div>\n                            <field name=\"name_position\" class=\"oe_inline\"/>\n                        </group>\n                        <label for=\"state_ids\"/>\n                        <field name=\"state_ids\">\n                            <tree editable=\"bottom\">\n                                <field name=\"name\"/>\n                                <field name=\"code\"/>\n                            </tree>\n                        </field>\n                    </sheet>\n                </form>"}', '<?xml version="1.0"?>
<form create="0" delete="0">
                    <sheet>
                        <div class="oe_button_box" name="button_box">
                        </div>
                        <field name="image_url" widget="image_url" class="oe_avatar" options="{''size'': [128,128]}"/>
                        <group name="main_group">
                            <group name="country_details">
                                <field name="name"/>
                                <field name="currency_id"/>
                                <field name="code"/>
                            </group>
                            <group name="phone_vat_settings">
                                <field name="phone_code" options="{''format'': false}"/>
                                <field name="vat_label"/>
                                <field name="zip_required"/>
                                <field name="state_required"/>
                            </group>
                        </group>
                        <group name="advanced_address_formatting" string="Advanced Address Formatting" groups="base.group_no_one">
                            <label for="address_view_id"/>
                            <div class="o_row">
                                <field name="address_view_id"/>
                                <div class="text-muted ms-2">Choose a subview of partners that includes only address fields, to change the way users can input addresses.</div>
                            </div>
                            <label for="address_format"/>
                            <div class="o_row">
                                <field name="address_format" placeholder="Address format..."/>
                                <div name="div_address_format ms-2" class="text-muted">Change the way addresses are displayed in reports</div>
                            </div>
                            <field name="name_position" class="oe_inline"/>
                        </group>
                        <label for="state_ids"/>
                        <field name="state_ids">
                            <tree editable="bottom">
                                <field name="name"/>
                                <field name="code"/>
                            </tree>
                        </field>
                    </sheet>
                </form>
            ', false, true, '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872', NULL);
