INSERT INTO public.ir_ui_view VALUES (152, 16, NULL, 1, 1, 'res.currency.search', 'res.currency', NULL, 'search', 'base/views/res_currency_views.xml', 'primary', '{"en_US": "<search string=\"Currencies\">\n                    <field name=\"name\" string=\"Currency\" filter_domain=\"(''|'',''|'',''|'',''|'',                                                                         (''name'', ''ilike'', self),                                                                         (''full_name'', ''ilike'', self),                                                                         (''symbol'', ''ilike'', self),                                                                         (''currency_unit_label'', ''ilike'', self),                                                                         (''currency_subunit_label'', ''ilike'', self),                                                                         )\"/>\n                    <filter name=\"active\" string=\"Active\" domain=\"[(''active'',''='',True)]\" help=\"Show active currencies\"/>\n                    <filter name=\"inactive\" string=\"Inactive\" domain=\"[(''active'',''='',False)]\" help=\"Show inactive currencies\"/>\n                </search>"}', '<?xml version="1.0"?>
