INSERT INTO public.ir_ui_view VALUES (154, 16, NULL, 1, 1, 'res.currency.kanban', 'res.currency', NULL, 'kanban', 'base/views/res_currency_views.xml', 'primary', '{"en_US": "<kanban class=\"o_kanban_mobile\">\n                    <field name=\"name\"/>\n                    <field name=\"symbol\"/>\n                    <field name=\"full_name\"/>\n                    <field name=\"active\"/>\n                    <templates>\n                        <t t-name=\"kanban-box\">\n                            <div t-attf-class=\"oe_kanban_global_click\">\n                                <div class=\"row mb4\">\n                                    <div class=\"col-2\">\n                                        <h3><t t-esc=\"record.name.value\"/></h3>\n                                    </div>\n                                    <div class=\"col-5\">\n                                        <span class=\"badge rounded-pill\"><t t-esc=\"record.symbol.value\"/></span>\n                                    </div>\n                                    <div class=\"col-5 text-end\">\n                                        <t t-if=\"! record.active.raw_value\"><span class=\"badge rounded-pill bg-light border\">inactive</span></t>\n                                    </div>\n                                </div>\n                                <div class=\"row\">\n                                    <div class=\"col-12\">\n                                        <div><field name=\"rate_string\"/></div>\n                                        <t t-if=\"record.date.raw_value\"><div>Last update: <field name=\"date\"/></div></t>\n                                    </div>\n                                </div>\n                            </div>\n                        </t>\n                    </templates>\n                </kanban>"}', '<?xml version="1.0"?>
<kanban class="o_kanban_mobile">
                    <field name="name"/>
                    <field name="symbol"/>
                    <field name="full_name"/>
                    <field name="active"/>
                    <templates>
                        <t t-name="kanban-box">
                            <div t-attf-class="oe_kanban_global_click">
                                <div class="row mb4">
                                    <div class="col-2">
                                        <h3><t t-esc="record.name.value"/></h3>
                                    </div>
                                    <div class="col-5">
                                        <span class="badge rounded-pill"><t t-esc="record.symbol.value"/></span>
                                    </div>
                                    <div class="col-5 text-end">
                                        <t t-if="! record.active.raw_value"><span class="badge rounded-pill bg-light border">inactive</span></t>
                                    </div>
                                </div>
                                <div class="row">
                                    <div class="col-12">
                                        <div><field name="rate_string"/></div>
                                        <t t-if="record.date.raw_value"><div>Last update: <field name="date"/></div></t>
                                    </div>
                                </div>
                            </div>
                        </t>
                    </templates>
                </kanban>
            ', false, true, '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872', NULL);
INSERT INTO public.ir_ui_view VALUES (209, 16, NULL, 1, 1, 'styles_company_report', NULL, 'web.styles_company_report', 'qweb', 'web/views/report_templates.xml', 'primary', '{"en_US": "<t t-name=\"web.styles_company_report\">\n        <t t-foreach=\"company_ids\" t-as=\"company\" t-translation=\"off\">\n            <t t-set=\"forced_vat\" t-value=\"False\"/>\n            <t t-set=\"font\" t-value=\"company.font or ''Lato''\"/>\n            <t t-set=\"primary\" t-value=\"company.primary_color or ''black''\"/>\n            <t t-set=\"secondary\" t-value=\"company.secondary_color or ''black''\"/>\n            <t t-set=\"layout\" t-value=\"company.external_report_layout_id.key or ''web.external_layout_standard''\"/>\n                .o_company_<t t-esc=\"company.id\"/>_layout {\n                font-family: <t t-esc=\"font\"/>;\n            <t t-if=\"layout == ''web.external_layout_striped''\">\n                &amp;.o_report_layout_striped {\n                   strong {\n                        color: <t t-esc=\"secondary\"/>;\n                    }\n                    h2 {\n                        color: <t t-esc=\"primary\"/>;\n                    }\n                    thead tr th {\n                        color: <t t-esc=\"secondary\"/>;\n                    }\n                }\n                .row &gt; div &gt; table,\n                div#total table, .totals_taxes_company_currency table {\n                    &amp;:first-child,\n                    &amp;:last-child,\n                    &amp;.o_subtotal,\n                    &amp;.o_total {\n                        strong {\n                            color: <t t-esc=\"primary\"/>;\n                        }\n                    }\n                }\n            </t>\n            <t t-elif=\"layout == ''web.external_layout_boxed''\">\n                &amp;.o_report_layout_boxed {\n                    #total strong {\n                        color: <t t-esc=\"primary\"/>;\n                    }\n                    .totals_taxes_company_currency strong{\n                        color: <t t-esc=\"primary\"/>;\n                    }\n                    #informations strong {\n                        color: <t t-esc=\"secondary\"/>;\n                    }\n                    h2 span {\n                        color: <t t-esc=\"primary\"/>;\n                    }\n                    table {\n                        thead {\n                            tr th {\n                                color: <t t-esc=\"secondary\"/>;\n                            }\n                        }\n                        tbody tr td {\n                            &amp;.o_line_section td {\n                                    background-color: rgba(<t t-esc=\"primary\"/>, 0.7);\n                                }\n                            &amp;.is-subtotal,\n                                td.o_price_total {\n                                    background-color: rgba(<t t-esc=\"secondary\"/>, 0.1);\n                                }\n                        }\n                    }\n                }\n                .row &gt; div &gt; table,\n                div#total table, .totals_taxes_company_currency table {\n                    tr {\n                        &amp;.o_total td {\n                            background-color: rgba(<t t-esc=\"primary\"/>, 0.9);\n                        }\n                    }\n                }\n            </t>\n            <t t-elif=\"layout == ''web.external_layout_bold''\">\n                &amp;.o_clean_footer {\n                    border-top: 3px solid <t t-esc=\"secondary\"/>;\n                    h4 {\n                        color: <t t-esc=\"secondary\"/>;\n                    }\n                    .pagenumber {\n                        border: 3px solid <t t-esc=\"primary\"/>;\n                        background-color: <t t-esc=\"secondary\"/>;\n                    }\n                }\n                &amp;.o_report_layout_bold {\n                    h1, h2, h3 {\n                        color: <t t-esc=\"primary\"/>;\n                    }\n                    strong {\n                        color: <t t-esc=\"secondary\"/>;\n                    }\n                    table {\n                       thead {\n                           color: <t t-esc=\"secondary\"/>;\n                           tr th {\n                                border-top: 3px solid <t t-esc=\"secondary\"/> !important;\n                            }\n                        }\n                        tbody {\n                            tr:last-child td {\n                                border-bottom: 3px solid <t t-esc=\"secondary\"/>;\n                            }\n                        }\n                    }\n                    #total, .totals_taxes_company_currency {\n                        strong {\n                            color: <t t-esc=\"secondary\"/>;\n                        }\n                    }\n                }\n            </t>\n            <t t-elif=\"layout == ''web.external_layout_standard''\">\n                &amp;.o_report_layout_standard {\n                    h2 {\n                        color: <t t-esc=\"primary\"/>;\n                    }\n                    #informations strong {\n                        color: <t t-esc=\"secondary\"/>;\n                    }\n                    #total strong{\n                        color: <t t-esc=\"primary\"/>;\n                    }\n                    .totals_taxes_company_currency strong{\n                        color: <t t-esc=\"primary\"/>;\n                    }\n                    table {\n                        thead {\n                            color: <t t-esc=\"secondary\"/>;\n                        }\n                    }\n                }\n            </t>\n            }\n        </t>\n    </t>"}', '<?xml version="1.0"?>
<t t-name="web.styles_company_report">
        <t t-foreach="company_ids" t-as="company" t-translation="off">
            <t t-set="forced_vat" t-value="False"/>
            <t t-set="font" t-value="company.font or ''Lato''"/>
            <t t-set="primary" t-value="company.primary_color or ''black''"/>
            <t t-set="secondary" t-value="company.secondary_color or ''black''"/>
            <t t-set="layout" t-value="company.external_report_layout_id.key or ''web.external_layout_standard''"/>
                .o_company_<t t-esc="company.id"/>_layout {
                font-family: <t t-esc="font"/>;
            <t t-if="layout == ''web.external_layout_striped''">
                &amp;.o_report_layout_striped {
                   strong {
                        color: <t t-esc="secondary"/>;
                    }
                    h2 {
                        color: <t t-esc="primary"/>;
                    }
                    thead tr th {
                        color: <t t-esc="secondary"/>;
                    }
                }
                .row &gt; div &gt; table,
                div#total table, .totals_taxes_company_currency table {
                    &amp;:first-child,
                    &amp;:last-child,
                    &amp;.o_subtotal,
                    &amp;.o_total {
                        strong {
                            color: <t t-esc="primary"/>;
                        }
                    }
                }
            </t>
            <t t-elif="layout == ''web.external_layout_boxed''">
                &amp;.o_report_layout_boxed {
                    #total strong {
                        color: <t t-esc="primary"/>;
                    }
                    .totals_taxes_company_currency strong{
                        color: <t t-esc="primary"/>;
                    }
                    #informations strong {
                        color: <t t-esc="secondary"/>;
                    }
                    h2 span {
                        color: <t t-esc="primary"/>;
                    }
                    table {
                        thead {
                            tr th {
                                color: <t t-esc="secondary"/>;
                            }
                        }
                        tbody tr td {
                            &amp;.o_line_section td {
                                    background-color: rgba(<t t-esc="primary"/>, 0.7);
                                }
                            &amp;.is-subtotal,
                                td.o_price_total {
                                    background-color: rgba(<t t-esc="secondary"/>, 0.1);
                                }
                        }
                    }
                }
                .row &gt; div &gt; table,
                div#total table, .totals_taxes_company_currency table {
                    tr {
                        &amp;.o_total td {
                            background-color: rgba(<t t-esc="primary"/>, 0.9);
                        }
                    }
                }
            </t>
            <t t-elif="layout == ''web.external_layout_bold''">
                &amp;.o_clean_footer {
                    border-top: 3px solid <t t-esc="secondary"/>;
                    h4 {
                        color: <t t-esc="secondary"/>;
                    }
                    .pagenumber {
                        border: 3px solid <t t-esc="primary"/>;
                        background-color: <t t-esc="secondary"/>;
                    }
                }
                &amp;.o_report_layout_bold {
                    h1, h2, h3 {
                        color: <t t-esc="primary"/>;
                    }
                    strong {
                        color: <t t-esc="secondary"/>;
                    }
                    table {
                       thead {
                           color: <t t-esc="secondary"/>;
                           tr th {
                                border-top: 3px solid <t t-esc="secondary"/> !important;
                            }
                        }
                        tbody {
                            tr:last-child td {
                                border-bottom: 3px solid <t t-esc="secondary"/>;
                            }
                        }
                    }
                    #total, .totals_taxes_company_currency {
                        strong {
                            color: <t t-esc="secondary"/>;
                        }
                    }
                }
            </t>
            <t t-elif="layout == ''web.external_layout_standard''">
                &amp;.o_report_layout_standard {
                    h2 {
                        color: <t t-esc="primary"/>;
                    }
                    #informations strong {
                        color: <t t-esc="secondary"/>;
                    }
                    #total strong{
                        color: <t t-esc="primary"/>;
                    }
                    .totals_taxes_company_currency strong{
                        color: <t t-esc="primary"/>;
                    }
                    table {
                        thead {
                            color: <t t-esc="secondary"/>;
                        }
                    }
                }
            </t>
            }
        </t>
    </t>

    ', false, true, '2026-05-10 01:07:07.223274', '2026-05-10 01:07:07.223274', NULL);
INSERT INTO public.ir_ui_view VALUES (155, 16, NULL, 1, 1, 'res.currency.form', 'res.currency', NULL, 'form', 'base/views/res_currency_views.xml', 'primary', '{"en_US": "<form string=\"Currency\">\n                    <field name=\"is_current_company_currency\" invisible=\"1\"/>\n                    <div class=\"alert alert-info text-center\" role=\"alert\" groups=\"base.group_no_one\">\n                        You cannot reduce the number of decimal places of a currency already used on an accounting entry.\n                    </div>\n                    <div class=\"alert alert-info text-center\" role=\"alert\" invisible=\"not is_current_company_currency\">\n                        This is your company''s currency.\n                    </div>\n                    <sheet>\n                        <group>\n                            <group>\n                                <field name=\"name\"/>\n                                <field name=\"full_name\" string=\"Name\"/>\n                                <field name=\"active\" widget=\"boolean_toggle\"/>\n                            </group>\n                            <group>\n                                <field name=\"symbol\"/>\n                                <field name=\"currency_unit_label\"/>\n                                <field name=\"currency_subunit_label\"/>\n                            </group>\n                        </group>\n\n                        <group groups=\"base.group_no_one\">\n                            <group string=\"Price Accuracy\">\n                                <field name=\"rounding\"/>\n                                <field name=\"decimal_places\"/>\n                            </group>\n\n                            <group string=\"Display\">\n                                <field name=\"position\"/>\n                            </group>\n                        </group>\n                        <notebook class=\"o_currency_rate_list\" invisible=\"is_current_company_currency\">\n                            <page string=\"Rates\" name=\"rates\">\n                                <field name=\"rate_ids\" widget=\"one2many\">\n                                    <tree string=\"Rates\" editable=\"top\" limit=\"25\">\n                                        <field name=\"name\"/>\n                                        <field name=\"company_id\" groups=\"base.group_multi_company\"/>\n                                        <field name=\"company_rate\" digits=\"[12,12]\"/>\n                                        <field name=\"inverse_company_rate\" digits=\"[12,12]\"/>\n                                        <field name=\"rate\" digits=\"[12,12]\" optional=\"hide\"/>\n                                        <field name=\"write_date\" optional=\"hide\"/>\n                                    </tree>\n                                </field>\n                            </page>\n                        </notebook>\n                    </sheet>\n                </form>"}', '<?xml version="1.0"?>
<form string="Currency">
                    <field name="is_current_company_currency" invisible="1"/>
                    <div class="alert alert-info text-center" role="alert" groups="base.group_no_one">
                        You cannot reduce the number of decimal places of a currency already used on an accounting entry.
                    </div>
                    <div class="alert alert-info text-center" role="alert" invisible="not is_current_company_currency">
                        This is your company''s currency.
                    </div>
                    <sheet>
                        <group>
                            <group>
                                <field name="name"/>
                                <field name="full_name" string="Name"/>
                                <field name="active" widget="boolean_toggle"/>
                            </group>
                            <group>
                                <field name="symbol"/>
                                <field name="currency_unit_label"/>
                                <field name="currency_subunit_label"/>
                            </group>
                        </group>

                        <group groups="base.group_no_one">
                            <group string="Price Accuracy">
                                <field name="rounding"/>
                                <field name="decimal_places"/>
                            </group>

                            <group string="Display">
                                <field name="position"/>
                            </group>
                        </group>
                        <notebook class="o_currency_rate_list" invisible="is_current_company_currency">
                            <page string="Rates" name="rates">
                                <field name="rate_ids" widget="one2many">
                                    <tree string="Rates" editable="top" limit="25">
                                        <field name="name"/>
                                        <field name="company_id" groups="base.group_multi_company"/>
                                        <field name="company_rate" digits="[12,12]"/>
                                        <field name="inverse_company_rate" digits="[12,12]"/>
                                        <field name="rate" digits="[12,12]" optional="hide"/>
                                        <field name="write_date" optional="hide"/>
                                    </tree>
                                </field>
                            </page>
                        </notebook>
                    </sheet>
                </form>
            ', false, true, '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872', NULL);
INSERT INTO public.ir_ui_view VALUES (156, 16, NULL, 1, 1, 'Change Own Password', 'change.password.own', NULL, 'form', 'base/views/res_users_views.xml', 'primary', '{"en_US": "<form string=\"Change Password\">\n                    <group>\n                        <field name=\"new_password\" password=\"True\" required=\"1\"/>\n                        <field name=\"confirm_password\" password=\"True\" required=\"1\"/>\n                    </group>\n                    <footer>\n                        <button string=\"Change Password\" name=\"change_password\" type=\"object\" class=\"btn-primary\" data-hotkey=\"q\"/>\n                        <button string=\"Cancel\" class=\"btn-secondary\" special=\"cancel\" data-hotkey=\"x\"/>\n                    </footer>\n                </form>"}', '<?xml version="1.0"?>
<form string="Change Password">
                    <group>
                        <field name="new_password" password="True" required="1"/>
                        <field name="confirm_password" password="True" required="1"/>
                    </group>
                    <footer>
                        <button string="Change Password" name="change_password" type="object" class="btn-primary" data-hotkey="q"/>
                        <button string="Cancel" class="btn-secondary" special="cancel" data-hotkey="x"/>
                    </footer>
                </form>
            ', false, true, '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872', NULL);
INSERT INTO public.ir_ui_view VALUES (157, 16, NULL, 1, 1, 'Change Password', 'change.password.wizard', NULL, 'form', 'base/views/res_users_views.xml', 'primary', '{"en_US": "<form string=\"Change Password\">\n                    <field mode=\"tree\" name=\"user_ids\"/>\n                    <footer>\n                        <button string=\"Change Password\" name=\"change_password_button\" type=\"object\" class=\"btn-primary\" data-hotkey=\"q\"/>\n                        <button string=\"Cancel\" class=\"btn-secondary\" special=\"cancel\" data-hotkey=\"x\"/>\n                    </footer>\n                </form>"}', '<?xml version="1.0"?>
<form string="Change Password">
                    <field mode="tree" name="user_ids"/>
                    <footer>
                        <button string="Change Password" name="change_password_button" type="object" class="btn-primary" data-hotkey="q"/>
                        <button string="Cancel" class="btn-secondary" special="cancel" data-hotkey="x"/>
                    </footer>
                </form>
            ', false, true, '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872', NULL);
INSERT INTO public.ir_ui_view VALUES (158, 16, NULL, 1, 1, 'Change Password Users', 'change.password.user', NULL, 'tree', 'base/views/res_users_views.xml', 'primary', '{"en_US": "<tree string=\"Users\" editable=\"bottom\" create=\"false\" delete=\"false\">\n                    <field name=\"user_id\" invisible=\"1\"/>\n                    <field name=\"user_login\" force_save=\"1\"/>\n                    <field name=\"new_passwd\" password=\"True\" width=\"20px\"/>\n                </tree>"}', '<?xml version="1.0"?>
<!-- the user list is editable, but one cannot add or delete rows -->
                <tree string="Users" editable="bottom" create="false" delete="false">
                    <field name="user_id" invisible="1"/>
                    <field name="user_login" force_save="1"/>
                    <field name="new_passwd" password="True" width="20px"/>
                </tree>
            ', false, true, '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872', NULL);
INSERT INTO public.ir_ui_view VALUES (159, 16, NULL, 1, 1, 'res.groups.search', 'res.groups', NULL, 'search', 'base/views/res_users_views.xml', 'primary', '{"en_US": "<search string=\"Groups\">\n                    <field name=\"name\" filter_domain=\"[''|'', (''full_name'',''ilike'',self), (''category_id'',''ilike'',self)]\" string=\"Group\"/>\n                    <separator orientation=\"vertical\"/>\n                    <field name=\"share\"/>\n                    <filter name=\"filter_no_share\" string=\"Internal Groups\" domain=\"[(''share'',''='',False)]\"/>\n                </search>"}', '<?xml version="1.0"?>
<search string="Groups">
                    <field name="name" filter_domain="[''|'', (''full_name'',''ilike'',self), (''category_id'',''ilike'',self)]" string="Group"/>
                    <separator orientation="vertical"/>
                    <field name="share"/>
                    <filter name="filter_no_share" string="Internal Groups" domain="[(''share'',''='',False)]"/>
                </search>
            ', false, true, '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872', NULL);
INSERT INTO public.ir_ui_view VALUES (160, 16, NULL, 1, 1, 'res.groups.form', 'res.groups', NULL, 'form', 'base/views/res_users_views.xml', 'primary', '{"en_US": "<form string=\"Groups\">\n                  <sheet>\n                    <group col=\"4\">\n                        <field name=\"category_id\"/>\n                        <field name=\"name\"/>\n                        <field name=\"share\"/>\n                    </group>\n                    <notebook>\n                        <page string=\"Users\" name=\"users\">\n                            <field name=\"users\" context=\"{''search_default_filter_no_share'':1}\"/>\n                        </page>\n                        <page string=\"Inherited\" name=\"inherit_groups\">\n                            <label for=\"implied_ids\" string=\"Users added to this group are automatically added in the following groups.\"/>\n                            <field name=\"implied_ids\"/>\n                        </page>\n                        <page string=\"Menus\" name=\"menus\">\n                            <field name=\"menu_access\"/>\n                        </page>\n                        <page string=\"Views\" name=\"views\">\n                            <field name=\"view_access\" groups=\"base.group_system\"/>\n                        </page>\n                        <page string=\"Access Rights\" name=\"access_rights\">\n                            <field name=\"model_access\">\n                                <tree string=\"Access Rights\" editable=\"top\">\n                                    <field name=\"name\"/>\n                                    <field name=\"model_id\"/>\n                                    <field name=\"perm_read\"/>\n                                    <field name=\"perm_write\"/>\n                                    <field name=\"perm_create\"/>\n                                    <field name=\"perm_unlink\"/>\n                                </tree>\n                            </field>\n                        </page>\n                        <page string=\"Record Rules\" name=\"record_rules\">\n                            <field name=\"rule_groups\">\n                                <tree string=\"Record Rules\" editable=\"top\">\n                                    <field name=\"name\"/>\n                                    <field name=\"model_id\"/>\n                                    <field name=\"domain_force\"/>\n                                    <field name=\"perm_read\"/>\n                                    <field name=\"perm_write\"/>\n                                    <field name=\"perm_create\"/>\n                                    <field name=\"perm_unlink\"/>\n                                </tree>\n                            </field>\n                        </page><page string=\"Notes\" name=\"notes\">\n                            <field name=\"comment\"/>\n                        </page>\n                    </notebook>\n                  </sheet>\n                </form>"}', '<?xml version="1.0"?>
<form string="Groups">
                  <sheet>
                    <group col="4">
                        <field name="category_id"/>
                        <field name="name"/>
                        <field name="share"/>
                    </group>
                    <notebook>
                        <page string="Users" name="users">
                            <field name="users" context="{''search_default_filter_no_share'':1}"/>
                        </page>
                        <page string="Inherited" name="inherit_groups">
                            <label for="implied_ids" string="Users added to this group are automatically added in the following groups."/>
                            <field name="implied_ids"/>
                        </page>
                        <page string="Menus" name="menus">
                            <field name="menu_access"/>
                        </page>
                        <page string="Views" name="views">
                            <field name="view_access" groups="base.group_system"/>
                        </page>
                        <page string="Access Rights" name="access_rights">
                            <field name="model_access">
                                <tree string="Access Rights" editable="top">
                                    <field name="name"/>
                                    <field name="model_id"/>
                                    <field name="perm_read"/>
                                    <field name="perm_write"/>
                                    <field name="perm_create"/>
                                    <field name="perm_unlink"/>
                                </tree>
                            </field>
                        </page>
                        <page string="Record Rules" name="record_rules">
                            <field name="rule_groups">
                                <tree string="Record Rules" editable="top">
                                    <field name="name"/>
                                    <field name="model_id"/>
                                    <field name="domain_force"/>
                                    <field name="perm_read"/>
                                    <field name="perm_write"/>
                                    <field name="perm_create"/>
                                    <field name="perm_unlink"/>
                                </tree>
                            </field>
                        </page><page string="Notes" name="notes">
                            <field name="comment"/>
                        </page>
                    </notebook>
                  </sheet>
                </form>
            ', false, true, '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872', NULL);
INSERT INTO public.ir_ui_view VALUES (281, 16, NULL, 1, 1, 'utm.medium.view.search', 'utm.medium', NULL, 'search', 'utm/views/utm_medium_views.xml', 'primary', '{"en_US": "<search string=\"Search UTM Medium\">\n                <field name=\"name\"/>\n                <separator/>\n                <filter string=\"Archived\" name=\"inactive\" domain=\"[(''active'', ''='', False)]\"/>\n            </search>"}', '<?xml version="1.0"?>
<search string="Search UTM Medium">
                <field name="name"/>
                <separator/>
                <filter string="Archived" name="inactive" domain="[(''active'', ''='', False)]"/>
            </search>
        ', false, true, '2026-05-10 01:11:43.219791', '2026-05-10 01:11:43.219791', NULL);
INSERT INTO public.ir_ui_view VALUES (161, 1, NULL, 1, 1, 'res.users.simplified.form', 'res.users', NULL, 'form', 'base/views/res_users_views.xml', 'primary', '{"en_US": "<form string=\"Users\">\n                    <sheet>\n                        <field name=\"id\" invisible=\"1\"/>\n                        <div class=\"alert alert-info text-center mb-3\" invisible=\"id &gt; 0\" role=\"alert\">\n                            You are inviting a new user.\n                        </div>\n                        <field name=\"avatar_128\" invisible=\"1\"/>\n                        <field name=\"image_1920\" widget=\"image\" class=\"oe_avatar\" options=\"{&quot;zoom&quot;: true, &quot;preview_image&quot;: &quot;avatar_128&quot;}\"/>\n                        <div class=\"oe_title\">\n                            <label for=\"name\"/>\n                            <h1><field name=\"name\" placeholder=\"e.g. John Doe\" required=\"1\"/></h1>\n                            <field name=\"email\" invisible=\"1\"/>\n                            <label for=\"login\" string=\"Email Address\"/>\n                            <h2>\n                                <field name=\"login\" placeholder=\"e.g. email@yourcompany.com\"/>\n                            </h2>\n                        </div>\n                        <group name=\"phone_numbers\">\n                            <field name=\"company_id\" context=\"{''user_preference'': 0}\" groups=\"base.group_multi_company\"/>\n                            <label for=\"groups_id\" string=\"Access Rights\" invisible=\"id &gt; 0\" groups=\"base.group_no_one\"/>\n                            <div invisible=\"id &gt; 0\" groups=\"base.group_no_one\">\n                                <field name=\"groups_id\" readonly=\"1\" widget=\"many2many_tags\" options=\"{''color_field'': ''color''}\" style=\"display: inline;\"/> You will be able to define additional access rights by editing the newly created user under the Settings / Users menu.\n                            </div>\n                            <field name=\"phone\" widget=\"phone\"/>\n                            <field name=\"mobile\" widget=\"phone\"/>\n                        </group>\n                    </sheet>\n                </form>"}', '<?xml version="1.0"?>
<form string="Users">
                    <sheet>
                        <field name="id" invisible="1"/>
                        <div class="alert alert-info text-center mb-3" invisible="id &gt; 0" role="alert">
                            You are inviting a new user.
                        </div>
                        <field name="avatar_128" invisible="1"/>
                        <field name="image_1920" widget="image" class="oe_avatar" options="{&quot;zoom&quot;: true, &quot;preview_image&quot;: &quot;avatar_128&quot;}"/>
                        <div class="oe_title">
                            <label for="name"/>
                            <h1><field name="name" placeholder="e.g. John Doe" required="1"/></h1>
                            <field name="email" invisible="1"/>
                            <label for="login" string="Email Address"/>
                            <h2>
                                <field name="login" placeholder="e.g. email@yourcompany.com"/>
                            </h2>
                        </div>
                        <group name="phone_numbers">
                            <field name="company_id" context="{''user_preference'': 0}" groups="base.group_multi_company"/>
                            <label for="groups_id" string="Access Rights" invisible="id &gt; 0" groups="base.group_no_one"/>
                            <div invisible="id &gt; 0" groups="base.group_no_one">
                                <field name="groups_id" readonly="1" widget="many2many_tags" options="{''color_field'': ''color''}" style="display: inline;"/> You will be able to define additional access rights by editing the newly created user under the Settings / Users menu.
                            </div>
                            <field name="phone" widget="phone"/>
                            <field name="mobile" widget="phone"/>
                        </group>
                    </sheet>
                </form>
            ', false, true, '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872', NULL);
INSERT INTO public.ir_ui_view VALUES (162, 16, NULL, 1, 1, 'res.users.form', 'res.users', NULL, 'form', 'base/views/res_users_views.xml', 'primary', '{"en_US": "<form string=\"Users\">\n                    <header>\n                    </header>\n                    <sheet>\n                        <field name=\"id\" invisible=\"1\"/>\n                        <div class=\"oe_button_box\" name=\"button_box\">\n                            <button name=\"action_show_groups\" type=\"object\" groups=\"base.group_no_one\" class=\"oe_stat_button\" icon=\"fa-users\">\n                                <field string=\"Groups\" name=\"groups_count\" widget=\"statinfo\"/>\n                            </button>\n                            <button name=\"action_show_accesses\" type=\"object\" groups=\"base.group_no_one\" class=\"oe_stat_button\" icon=\"fa-list\">\n                                <field string=\"Access Rights\" name=\"accesses_count\" widget=\"statinfo\"/>\n                            </button>\n                            <button name=\"action_show_rules\" type=\"object\" groups=\"base.group_no_one\" class=\"oe_stat_button\" icon=\"fa-list-ul\">\n                                <field string=\"Record Rules\" name=\"rules_count\" widget=\"statinfo\"/>\n                            </button>\n                        </div>\n                        <widget name=\"web_ribbon\" title=\"Archived\" bg_color=\"text-bg-danger\" invisible=\"active\"/>\n                        <field name=\"active_partner\" required=\"0\" readonly=\"1\" invisible=\"1\"/>\n                        <div class=\"alert alert-info text-center o_form_header\" invisible=\"active and active_partner or not active and not active_partner or active and not active_partner\" role=\"alert\">\n                          <a class=\"close\" data-bs-dismiss=\"alert\" href=\"#\">x</a>\n                          <div>\n                            <strong>The contact linked to this user is still active</strong>\n                          </div>\n                          <div>You can archive the contact\n                            <field name=\"partner_id\" required=\"0\" readonly=\"1\"/>\n                          </div>\n                        </div>\n                        <field name=\"avatar_128\" invisible=\"1\"/>\n                        <field name=\"image_1920\" widget=\"image\" class=\"oe_avatar\" options=\"{&quot;preview_image&quot;: &quot;avatar_128&quot;}\"/>\n                        <div class=\"oe_title\">\n                            <label for=\"name\"/>\n                            <h1><field name=\"name\" placeholder=\"e.g. John Doe\" required=\"1\"/></h1>\n                            <field name=\"email\" invisible=\"1\"/>\n                            <label for=\"login\" string=\"Email Address\"/>\n                            <h2><field name=\"login\" placeholder=\"e.g. email@yourcompany.com\"/></h2>\n                            <group>\n                                <field name=\"partner_id\" groups=\"base.group_no_one\" readonly=\"1\" required=\"0\" invisible=\"not id\"/>\n                                <field name=\"share\" invisible=\"1\"/>\n                            </group>\n                        </div>\n                        <notebook colspan=\"4\">\n                            <page name=\"access_rights\" string=\"Access Rights\">\n                                <group string=\"Multi Companies\" invisible=\"companies_count &lt;= 1\">\n                                    <field string=\"Allowed Companies\" name=\"company_ids\" widget=\"many2many_tags\" options=\"{''no_create'': True, ''color_field'': ''color''}\"/>\n                                    <field string=\"Default Company\" name=\"company_id\" context=\"{''user_preference'': 0}\"/>\n                                    <field string=\"Companies count\" name=\"companies_count\" invisible=\"1\"/>\n                                </group>\n                                <field name=\"groups_id\"/>\n                            </page>\n                            <page string=\"Preferences\" name=\"preferences\">\n                                <group>\n                                    <group string=\"Localization\" name=\"preferences\">\n                                        <field name=\"active\" invisible=\"1\"/>\n                                        <label for=\"lang\"/>\n                                        <div class=\"o_row\">\n                                            <field name=\"lang\" required=\"1\"/>\n                                            <button type=\"action\" name=\"43\" class=\"oe_edit_only btn-sm btn-link mb4 fa fa-globe\" aria-label=\"Add a language\" title=\"Add a language\"/>\n                                        </div>\n                                        <field name=\"tz\" widget=\"timezone_mismatch\" options=\"{''tz_offset_field'': ''tz_offset''}\"/>\n                                        <field name=\"tz_offset\" invisible=\"1\"/>\n                                    </group>\n                                    <group string=\"Menus Customization\" groups=\"base.group_no_one\" invisible=\"share\">\n                                        <field name=\"action_id\"/>\n                                    </group>\n                                </group>\n                                <group name=\"messaging\">\n                                    <field name=\"signature\" options=\"{''style-inline'': true, ''codeview'': true}\"/>\n                                </group>\n                            </page>\n                        </notebook>\n                    </sheet>\n                </form>"}', '<?xml version="1.0"?>
<form string="Users">
                    <header>
                    </header>
                    <sheet>
                        <field name="id" invisible="1"/>
                        <div class="oe_button_box" name="button_box">
                            <button name="action_show_groups" type="object" groups="base.group_no_one" class="oe_stat_button" icon="fa-users">
                                <field string="Groups" name="groups_count" widget="statinfo"/>
                            </button>
                            <button name="action_show_accesses" type="object" groups="base.group_no_one" class="oe_stat_button" icon="fa-list">
                                <field string="Access Rights" name="accesses_count" widget="statinfo"/>
                            </button>
                            <button name="action_show_rules" type="object" groups="base.group_no_one" class="oe_stat_button" icon="fa-list-ul">
                                <field string="Record Rules" name="rules_count" widget="statinfo"/>
                            </button>
                        </div>
                        <widget name="web_ribbon" title="Archived" bg_color="text-bg-danger" invisible="active"/>
                        <field name="active_partner" required="0" readonly="1" invisible="1"/>
                        <div class="alert alert-info text-center o_form_header" invisible="active and active_partner or not active and not active_partner or active and not active_partner" role="alert">
                          <a class="close" data-bs-dismiss="alert" href="#">x</a>
                          <div>
                            <strong>The contact linked to this user is still active</strong>
                          </div>
                          <div>You can archive the contact
                            <field name="partner_id" required="0" readonly="1"/>
                          </div>
                        </div>
                        <field name="avatar_128" invisible="1"/>
                        <field name="image_1920" widget="image" class="oe_avatar" options="{&quot;preview_image&quot;: &quot;avatar_128&quot;}"/>
                        <div class="oe_title">
                            <label for="name"/>
                            <h1><field name="name" placeholder="e.g. John Doe" required="1"/></h1>
                            <field name="email" invisible="1"/>
                            <label for="login" string="Email Address"/>
                            <h2><field name="login" placeholder="e.g. email@yourcompany.com"/></h2>
                            <group>
                                <field name="partner_id" groups="base.group_no_one" readonly="1" required="0" invisible="not id"/>
                                <field name="share" invisible="1"/>
                            </group>
                        </div>
                        <notebook colspan="4">
                            <page name="access_rights" string="Access Rights">
                                <group string="Multi Companies" invisible="companies_count &lt;= 1">
                                    <field string="Allowed Companies" name="company_ids" widget="many2many_tags" options="{''no_create'': True, ''color_field'': ''color''}"/>
                                    <field string="Default Company" name="company_id" context="{''user_preference'': 0}"/>
                                    <field string="Companies count" name="companies_count" invisible="1"/>
                                </group>
                                <field name="groups_id"/>
                            </page>
                            <page string="Preferences" name="preferences">
                                <group>
                                    <group string="Localization" name="preferences">
                                        <field name="active" invisible="1"/>
                                        <label for="lang"/>
                                        <div class="o_row">
                                            <field name="lang" required="1"/>
                                            <button type="action" name="43" class="oe_edit_only btn-sm btn-link mb4 fa fa-globe" aria-label="Add a language" title="Add a language"/>
                                        </div>
                                        <field name="tz" widget="timezone_mismatch" options="{''tz_offset_field'': ''tz_offset''}"/>
                                        <field name="tz_offset" invisible="1"/>
                                    </group>
                                    <group string="Menus Customization" groups="base.group_no_one" invisible="share">
                                        <field name="action_id"/>
                                    </group>
                                </group>
                                <group name="messaging">
                                    <field name="signature" options="{''style-inline'': true, ''codeview'': true}"/>
                                </group>
                            </page>
                        </notebook>
                    </sheet>
                </form>
            ', false, true, '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872', NULL);
INSERT INTO public.ir_ui_view VALUES (163, 16, NULL, 1, 1, 'res.users.tree', 'res.users', NULL, 'tree', 'base/views/res_users_views.xml', 'primary', '{"en_US": "<tree string=\"Users\" multi_edit=\"1\">\n                    <field name=\"name\" readonly=\"1\"/>\n                    <field name=\"login\" readonly=\"1\"/>\n                    <field name=\"lang\"/>\n                    <field name=\"login_date\" readonly=\"1\"/>\n                    <field name=\"company_id\" groups=\"base.group_multi_company\"/>\n                </tree>"}', '<?xml version="1.0"?>
<tree string="Users" multi_edit="1">
                    <field name="name" readonly="1"/>
                    <field name="login" readonly="1"/>
                    <field name="lang"/>
                    <field name="login_date" readonly="1"/>
                    <field name="company_id" groups="base.group_multi_company"/>
                </tree>
            ', false, true, '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872', NULL);
INSERT INTO public.ir_ui_view VALUES (164, 16, NULL, 1, 1, 'res.users.kanban', 'res.users', NULL, 'kanban', 'base/views/res_users_views.xml', 'primary', '{"en_US": "<kanban class=\"o_kanban_mobile\">\n                    <field name=\"id\"/>\n                    <field name=\"name\"/>\n                    <field name=\"login\"/>\n                    <field name=\"lang\"/>\n                    <field name=\"active\"/>\n                    <field name=\"login_date\"/>\n                    <templates>\n                        <t t-name=\"kanban-box\">\n                            <div t-attf-class=\"oe_kanban_global_click\">\n                                <div class=\"o_kanban_image\">\n                                    <img alt=\"Avatar\" t-att-src=\"kanban_image(''res.users'', ''avatar_128'', record.id.raw_value)\"/>\n                                </div>\n                                <div class=\"oe_kanban_details\">\n                                    <ul>\n                                        <li class=\"text-success float-end mb4\" t-if=\"record.active.raw_value\"><i class=\"fa fa-circle\" role=\"img\" aria-label=\"Ok\" title=\"Ok\"/></li>\n                                        <li class=\"text-danger float-end mb4\" t-if=\"!record.active.raw_value\"><i class=\"fa fa-circle\" role=\"img\" aria-label=\"Invalid\" title=\"Invalid\"/></li>\n                                        <li class=\"mb4\">\n                                            <strong><field name=\"name\"/></strong>\n                                        </li>\n                                        <li class=\"d-flex flex-wrap\">\n                                            <span class=\"mb4 text-truncate\" title=\"Login\">\n                                                <i class=\"fa fa-envelope me-1\" role=\"img\" aria-label=\"Login\"/>\n                                                <field name=\"login\"/>\n                                            </span>\n                                            <field class=\"badge rounded-pill mb4 ms-auto\" name=\"lang\"/>\n                                        </li>\n                                    </ul>\n                                </div>\n                            </div>\n                        </t>\n                    </templates>\n                </kanban>"}', '<?xml version="1.0"?>
<kanban class="o_kanban_mobile">
                    <field name="id"/>
                    <field name="name"/>
                    <field name="login"/>
                    <field name="lang"/>
                    <field name="active"/>
                    <field name="login_date"/>
                    <templates>
                        <t t-name="kanban-box">
                            <div t-attf-class="oe_kanban_global_click">
                                <div class="o_kanban_image">
                                    <img alt="Avatar" t-att-src="kanban_image(''res.users'', ''avatar_128'', record.id.raw_value)"/>
                                </div>
                                <div class="oe_kanban_details">
                                    <ul>
                                        <li class="text-success float-end mb4" t-if="record.active.raw_value"><i class="fa fa-circle" role="img" aria-label="Ok" title="Ok"/></li>
                                        <li class="text-danger float-end mb4" t-if="!record.active.raw_value"><i class="fa fa-circle" role="img" aria-label="Invalid" title="Invalid"/></li>
                                        <li class="mb4">
                                            <strong><field name="name"/></strong>
                                        </li>
                                        <li class="d-flex flex-wrap">
                                            <span class="mb4 text-truncate" title="Login">
                                                <i class="fa fa-envelope me-1" role="img" aria-label="Login"/>
                                                <field name="login"/>
                                            </span>
                                            <field class="badge rounded-pill mb4 ms-auto" name="lang"/>
                                        </li>
                                    </ul>
                                </div>
                            </div>
                        </t>
                    </templates>
                </kanban>
            ', false, true, '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872', NULL);
INSERT INTO public.ir_ui_view VALUES (165, 16, NULL, 1, 1, 'res.users.search', 'res.users', NULL, 'search', 'base/views/res_users_views.xml', 'primary', '{"en_US": "<search string=\"Users\">\n                    <field name=\"name\" filter_domain=\"[''|'', ''|'', (''name'',''ilike'',self), (''login'',''ilike'',self), (''email'',''ilike'',self)]\" string=\"User\"/>\n                    <field name=\"company_ids\" string=\"Company\" groups=\"base.group_multi_company\"/>\n                    <field name=\"share\"/>\n                    <filter name=\"filter_no_share\" string=\"Internal Users\" domain=\"[(''share'', ''='', False)]\"/>\n                    <filter name=\"filter_share\" string=\"Portal Users\" domain=\"[(''share'', ''='', True)]\"/>\n                    <separator/>\n                    <filter name=\"Inactive\" string=\"Inactive Users\" domain=\"[(''active'',''='',False)]\"/>\n                </search>"}', '<?xml version="1.0"?>
<search string="Users">
                    <field name="name" filter_domain="[''|'', ''|'', (''name'',''ilike'',self), (''login'',''ilike'',self), (''email'',''ilike'',self)]" string="User"/>
                    <field name="company_ids" string="Company" groups="base.group_multi_company"/>
                    <field name="share"/>
                    <filter name="filter_no_share" string="Internal Users" domain="[(''share'', ''='', False)]"/>
                    <filter name="filter_share" string="Portal Users" domain="[(''share'', ''='', True)]"/>
                    <separator/>
                    <filter name="Inactive" string="Inactive Users" domain="[(''active'',''='',False)]"/>
                </search>
            ', false, true, '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872', NULL);
INSERT INTO public.ir_ui_view VALUES (167, 16, NULL, 1, 1, 'API Key: description input form', 'res.users.apikeys.description', NULL, 'form', 'base/views/res_users_views.xml', 'primary', '{"en_US": "<form>\n                    <sheet>\n                    <h3 class=\"fw-bold\">\n                        Name your key\n                    </h3>\n                    <p>Enter a description of and purpose for the key.</p>\n                    <field name=\"name\" placeholder=\"What''s this key for?\"/>\n                    <p>\n                        It is very important that this description be clear\n                        and complete, <strong>it will be the only way to\n                        identify the key once created</strong>.\n                    </p>\n                    <footer>\n                        <button name=\"make_key\" type=\"object\" string=\"Generate key\" class=\"btn-primary\" data-hotkey=\"q\"/>\n                        <button special=\"cancel\" data-hotkey=\"x\" string=\"Cancel\" class=\"btn-secondary\"/>\n                    </footer>\n                    </sheet>\n                </form>"}', '<?xml version="1.0"?>
<form>
                    <sheet>
                    <h3 class="fw-bold">
                        Name your key
                    </h3>
                    <p>Enter a description of and purpose for the key.</p>
                    <field name="name" placeholder="What''s this key for?"/>
                    <p>
                        It is very important that this description be clear
                        and complete, <strong>it will be the only way to
                        identify the key once created</strong>.
                    </p>
                    <footer>
                        <button name="make_key" type="object" string="Generate key" class="btn-primary" data-hotkey="q"/>
                        <button special="cancel" data-hotkey="x" string="Cancel" class="btn-secondary"/>
                    </footer>
                    </sheet>
                </form>
            ', false, true, '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872', NULL);
INSERT INTO public.ir_ui_view VALUES (168, 16, NULL, 1, 1, 'API Key: show', 'res.users.apikeys.show', NULL, 'form', 'base/views/res_users_views.xml', 'primary', '{"en_US": "<form>\n                    <sheet>\n                        <h3 class=\"fw-bold\">\n                            Write down your key\n                        </h3>\n                        <p>\n                            Here is your new API key, use it instead of a password for RPC access.\n                            Your login is still necessary for interactive usage.\n                        </p>\n                        <p><code><field name=\"key\" readonly=\"True\"/></code></p>\n                        <p class=\"alert alert-warning\" role=\"alert\">\n                            <strong>Important:</strong>\n                            The key cannot be retrieved later and provides <b>full access</b>\n                            to your user account, it is very important to store it securely.\n                        </p>\n                        <footer>\n                            <button special=\"cancel\" data-hotkey=\"x\" string=\"Done!\"/>\n                        </footer>\n                    </sheet>\n                </form>"}', '<?xml version="1.0"?>
<form>
                    <sheet>
                        <h3 class="fw-bold">
                            Write down your key
                        </h3>
                        <p>
                            Here is your new API key, use it instead of a password for RPC access.
                            Your login is still necessary for interactive usage.
                        </p>
                        <p><code><field name="key" readonly="True"/></code></p>
                        <p class="alert alert-warning" role="alert">
                            <strong>Important:</strong>
                            The key cannot be retrieved later and provides <b>full access</b>
                            to your user account, it is very important to store it securely.
                        </p>
                        <footer>
                            <button special="cancel" data-hotkey="x" string="Done!"/>
                        </footer>
                    </sheet>
                </form>
            ', false, true, '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872', NULL);
INSERT INTO public.ir_ui_view VALUES (169, 18, NULL, 1, 1, 'res.users.preferences.form', 'res.users', NULL, 'form', 'base/views/res_users_views.xml', 'primary', '{"en_US": "<form string=\"Users\" edit=\"1\">\n                    <widget name=\"notification_alert\"/>\n                    <field name=\"avatar_128\" invisible=\"1\"/>\n                    <field name=\"image_1920\" readonly=\"0\" widget=\"image\" class=\"oe_avatar\" options=\"{&quot;preview_image&quot;: &quot;avatar_128&quot;}\"/>\n                    <h1>\n                        <field name=\"name\" readonly=\"1\" class=\"oe_inline\"/>\n                    </h1>\n                    <notebook>\n                        <page string=\"Preferences\" name=\"preferences_page\">\n                            <group name=\"preferences\">\n                                <group>\n                                    <field name=\"email\" widget=\"email\" readonly=\"0\"/>\n                                </group>\n                                <group>\n                                    <label for=\"lang\"/>\n                                    <div class=\"o_row\">\n                                        <field name=\"lang\" required=\"1\" readonly=\"0\"/>\n                                        <button type=\"action\" name=\"43\" class=\"oe_edit_only btn-sm btn-link mb4 fa fa-globe\" aria-label=\"Add a language\" groups=\"base.group_system\" title=\"Add a language\"/>\n                                    </div>\n                                    <field name=\"tz\" widget=\"timezone_mismatch\" options=\"{''tz_offset_field'': ''tz_offset''}\" readonly=\"0\"/>\n                                    <field name=\"tz_offset\" invisible=\"1\"/>\n                                </group>\n                                <field name=\"share\" invisible=\"1\"/>\n                            </group>\n                            <group name=\"signature\">\n                                <field name=\"signature\" readonly=\"0\" options=\"{''style-inline'': true, ''codeview'': true}\"/>\n                            </group>\n                            <group name=\"status\" string=\"Status\" invisible=\"1\">\n                                <field name=\"company_id\" options=\"{''no_create'': True}\" readonly=\"0\" groups=\"base.group_multi_company\"/>\n                            </group>\n                            <group name=\"preference_contact\"/>\n                        </page>\n                        <page string=\"Account Security\" name=\"page_account_security\">\n                            <group name=\"auth\" string=\"Password Management\">\n                                <div colspan=\"2\">\n                                    <button name=\"preference_change_password\" type=\"object\" string=\"Change password\" class=\"btn btn-secondary\"/>\n                                </div>\n                            </group>\n                            <group name=\"access\" string=\"Other Devices\">\n                                <div colspan=\"2\">\n                                    <button name=\"action_revoke_all_devices\" type=\"object\" string=\"Log out from all devices\" class=\"btn btn-secondary\"/>\n                                </div>\n                            </group>\n                            <group string=\"API Keys\">\n                                <div class=\"text-muted\" colspan=\"2\">\n                                    API Keys are used to connect to Odoo from external tools without the need for a password or Two-factor Authentication.\n                                    <a href=\"https://www.odoo.com/documentation/17.0/developer/misc/api/external_api.html#api-keys\" target=\"_blank\">\n                                        <i title=\"Documentation\" class=\"fa fa-fw o_button_icon fa-info-circle\"/>\n                                        Learn more\n                                    </a>\n                                </div>\n                                <div colspan=\"2\" invisible=\"not api_key_ids\">\n                                    <field name=\"api_key_ids\" nolabel=\"1\" colspan=\"4\" readonly=\"0\">\n                                        <tree editable=\"bottom\" create=\"false\" delete=\"false\">\n                                            <field name=\"name\"/>\n                                            <field name=\"scope\"/>\n                                            <field name=\"create_date\"/>\n                                            <button type=\"object\" name=\"remove\" string=\"Delete API key.\" icon=\"fa-trash\"/>\n                                        </tree>\n                                    </field>\n                                </div>\n                                <div colspan=\"2\">\n                                    <button name=\"api_key_wizard\" string=\"New API Key\" type=\"object\" class=\"btn btn-secondary\"/>\n                                </div>\n                            </group>\n                        </page>\n                    </notebook>\n                    <footer>\n                        <button name=\"preference_save\" type=\"object\" string=\"Save\" class=\"btn-primary\" data-hotkey=\"q\"/>\n                        <button name=\"preference_cancel\" string=\"Cancel\" special=\"cancel\" data-hotkey=\"x\" class=\"btn-secondary\"/>\n                    </footer>\n                </form>"}', '<?xml version="1.0"?>
<form string="Users" edit="1">
                    <widget name="notification_alert"/>
                    <field name="avatar_128" invisible="1"/>
                    <field name="image_1920" readonly="0" widget="image" class="oe_avatar" options="{&quot;preview_image&quot;: &quot;avatar_128&quot;}"/>
                    <h1>
                        <field name="name" readonly="1" class="oe_inline"/>
                    </h1>
                    <notebook>
                        <page string="Preferences" name="preferences_page">
                            <group name="preferences">
                                <group>
                                    <field name="email" widget="email" readonly="0"/>
                                </group>
                                <group>
                                    <label for="lang"/>
                                    <div class="o_row">
                                        <field name="lang" required="1" readonly="0"/>
                                        <button type="action" name="43" class="oe_edit_only btn-sm btn-link mb4 fa fa-globe" aria-label="Add a language" groups="base.group_system" title="Add a language"/>
                                    </div>
                                    <field name="tz" widget="timezone_mismatch" options="{''tz_offset_field'': ''tz_offset''}" readonly="0"/>
                                    <field name="tz_offset" invisible="1"/>
                                </group>
                                <field name="share" invisible="1"/>
                            </group>
                            <group name="signature">
                                <field name="signature" readonly="0" options="{''style-inline'': true, ''codeview'': true}"/>
                            </group>
                            <group name="status" string="Status" invisible="1">
                                <field name="company_id" options="{''no_create'': True}" readonly="0" groups="base.group_multi_company"/>
                            </group>
                            <group name="preference_contact"/>
                        </page>
                        <page string="Account Security" name="page_account_security">
                            <group name="auth" string="Password Management">
                                <div colspan="2">
                                    <button name="preference_change_password" type="object" string="Change password" class="btn btn-secondary"/>
                                </div>
                            </group>
                            <group name="access" string="Other Devices">
                                <div colspan="2">
                                    <button name="action_revoke_all_devices" type="object" string="Log out from all devices" class="btn btn-secondary"/>
                                </div>
                            </group>
                            <group string="API Keys">
                                <div class="text-muted" colspan="2">
                                    API Keys are used to connect to Odoo from external tools without the need for a password or Two-factor Authentication.
                                    <a href="https://www.odoo.com/documentation/17.0/developer/misc/api/external_api.html#api-keys" target="_blank">
                                        <i title="Documentation" class="fa fa-fw o_button_icon fa-info-circle"/>
                                        Learn more
                                    </a>
                                </div>
                                <div colspan="2" invisible="not api_key_ids">
                                    <field name="api_key_ids" nolabel="1" colspan="4" readonly="0">
                                        <tree editable="bottom" create="false" delete="false">
                                            <field name="name"/>
                                            <field name="scope"/>
                                            <field name="create_date"/>
                                            <button type="object" name="remove" string="Delete API key." icon="fa-trash"/>
                                        </tree>
                                    </field>
                                </div>
                                <div colspan="2">
                                    <button name="api_key_wizard" string="New API Key" type="object" class="btn btn-secondary"/>
                                </div>
                            </group>
                        </page>
                    </notebook>
                    <footer>
                        <button name="preference_save" type="object" string="Save" class="btn-primary" data-hotkey="q"/>
                        <button name="preference_cancel" string="Cancel" special="cancel" data-hotkey="x" class="btn-secondary"/>
                    </footer>
                </form>
            ', false, true, '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872', NULL);
INSERT INTO public.ir_ui_view VALUES (170, 16, NULL, 1, 1, 'API Keys Listing', 'res.users.apikeys', NULL, 'tree', 'base/views/res_users_views.xml', 'primary', '{"en_US": "<tree create=\"false\" edit=\"false\" delete=\"false\" editable=\"bottom\">\n                    <field name=\"user_id\"/>\n                    <field name=\"name\"/>\n                    <field name=\"scope\"/>\n                    <field name=\"create_date\"/>\n                    <button type=\"object\" name=\"remove\" title=\"Delete API key.\" icon=\"fa-trash\"/>\n                </tree>"}', '<?xml version="1.0"?>
