INSERT INTO public.ir_ui_view VALUES (178, 16, NULL, 1, 1, 'paper_format_view_form', 'report.paperformat', NULL, 'form', 'base/views/report_paperformat_views.xml', 'primary', '{"en_US": "<form string=\"Paper format configuration\">\n                <sheet>\n                    <group>\n                        <field name=\"name\"/>\n                        <field name=\"format\"/>\n                        <field name=\"page_height\" invisible=\"format != ''custom''\"/>\n                        <field name=\"page_width\" invisible=\"format != ''custom''\"/>\n                        <field name=\"orientation\"/>\n                        <field name=\"margin_top\"/>\n                        <field name=\"margin_bottom\"/>\n                        <field name=\"margin_left\"/>\n                        <field name=\"margin_right\"/>\n                        <field name=\"header_line\"/>\n                        <field name=\"header_spacing\"/>\n                        <field name=\"disable_shrinking\"/>\n                        <field name=\"dpi\"/>\n                        <field name=\"report_ids\" widget=\"many2many_tags\" options=\"{''not_delete'': True}\"/>\n                    </group>\n                </sheet>\n                </form>"}', '<?xml version="1.0"?>
<form string="Paper format configuration">
                <sheet>
                    <group>
                        <field name="name"/>
                        <field name="format"/>
                        <field name="page_height" invisible="format != ''custom''"/>
                        <field name="page_width" invisible="format != ''custom''"/>
                        <field name="orientation"/>
                        <field name="margin_top"/>
                        <field name="margin_bottom"/>
                        <field name="margin_left"/>
                        <field name="margin_right"/>
                        <field name="header_line"/>
                        <field name="header_spacing"/>
                        <field name="disable_shrinking"/>
                        <field name="dpi"/>
                        <field name="report_ids" widget="many2many_tags" options="{''not_delete'': True}"/>
                    </group>
                </sheet>
                </form>
            ', false, true, '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872', NULL);
INSERT INTO public.ir_ui_view VALUES (171, 16, NULL, 1, 1, 'res.users.identitycheck form', 'res.users.identitycheck', NULL, 'form', 'base/views/res_users_identitycheck_views.xml', 'primary', '{"en_US": "<form string=\"Password Confirmation\">\n                    <sheet>\n                        <h3><strong>Please enter your password to confirm you own this account</strong></h3>\n                        <div>\n                            <field class=\"o_field_highlight col-10 col-md-6 px-0\" name=\"password\" autocomplete=\"current-password\" required=\"True\" password=\"True\" placeholder=\"************\"/>\n                        </div>\n                        <a href=\"/web/reset_password/\" class=\"btn btn-link\" role=\"button\">Forgot password?</a>\n                    </sheet>\n                    <footer>\n                        <button string=\"Confirm Password\" type=\"object\" name=\"run_check\" class=\"btn btn-primary\" data-hotkey=\"q\"/>\n                        <button string=\"Cancel\" special=\"cancel\" data-hotkey=\"z\" class=\"btn btn-secondary\"/>\n                    </footer>\n                </form>"}', '<?xml version="1.0"?>
<form string="Password Confirmation">
                    <sheet>
                        <h3><strong>Please enter your password to confirm you own this account</strong></h3>
                        <div>
                            <field class="o_field_highlight col-10 col-md-6 px-0" name="password" autocomplete="current-password" required="True" password="True" placeholder="************"/>
                        </div>
                        <a href="/web/reset_password/" class="btn btn-link" role="button">Forgot password?</a>
                    </sheet>
                    <footer>
                        <button string="Confirm Password" type="object" name="run_check" class="btn btn-primary" data-hotkey="q"/>
                        <button string="Cancel" special="cancel" data-hotkey="z" class="btn btn-secondary"/>
                    </footer>
                </form>
            ', false, true, '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872', NULL);
INSERT INTO public.ir_ui_view VALUES (172, 40, NULL, 1, 1, 'Revoke All Devices', 'res.users.identitycheck', NULL, 'form', 'base/views/res_users_identitycheck_views.xml', 'primary', '{"en_US": "<form string=\"Log out from all devices\">\n                    <div>\n                        You are about to log out from all devices that currently have access to your account.<br/><br/>\n                        <strong>Type in your password to confirm :</strong>\n                        <field class=\"oe_inline o_field_highlight\" name=\"password\" password=\"True\" required=\"True\"/>\n                    </div>\n                    <footer>\n                        <button string=\"Log out from all devices\" name=\"revoke_all_devices\" type=\"object\" class=\"btn-primary\" data-hotkey=\"q\"/>\n                        <button string=\"Cancel\" class=\"btn-secondary\" special=\"cancel\" data-hotkey=\"z\"/>\n                    </footer>\n                </form>"}', '<?xml version="1.0"?>
<form string="Log out from all devices">
                    <div>
                        You are about to log out from all devices that currently have access to your account.<br/><br/>
                        <strong>Type in your password to confirm :</strong>
                        <field class="oe_inline o_field_highlight" name="password" password="True" required="True"/>
                    </div>
                    <footer>
                        <button string="Log out from all devices" name="revoke_all_devices" type="object" class="btn-primary" data-hotkey="q"/>
                        <button string="Cancel" class="btn-secondary" special="cancel" data-hotkey="z"/>
                    </footer>
                </form>
            ', false, true, '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872', NULL);
INSERT INTO public.ir_ui_view VALUES (173, 16, NULL, 1, 1, 'ir.property.search', 'ir.property', NULL, 'search', 'base/views/ir_property_views.xml', 'primary', '{"en_US": "<search string=\"Parameters\">\n                    <field name=\"name\" string=\"Name\"/>\n                    <filter string=\"Generic\" name=\"generic\" help=\"Parameters that are used by all resources.\" domain=\"[(''res_id'',''='',False)]\"/>\n                    <field name=\"fields_id\"/>\n                    <field name=\"company_id\" groups=\"base.group_multi_company\"/>\n                </search>"}', '<?xml version="1.0"?>
