INSERT INTO public.ir_ui_view VALUES (174, 16, NULL, 1, 1, 'ir.property.form', 'ir.property', NULL, 'form', 'base/views/ir_property_views.xml', 'primary', '{"en_US": "<form string=\"Parameters\">\n                  <sheet>\n                    <group col=\"4\">\n                        <field name=\"name\"/>\n                        <field name=\"company_id\" groups=\"base.group_multi_company\"/>\n                        <newline/>\n                        <field name=\"fields_id\"/>\n                        <field name=\"type\"/>\n                        <field name=\"res_id\"/>\n                    </group>\n                    <group>\n\t                    <field name=\"value_integer\" string=\"Value\" invisible=\"type not in (''integer'', ''boolean'')\"/>\n\t                    <field name=\"value_float\" string=\"Value\" invisible=\"type != ''float''\"/>\n\t                    <field name=\"value_datetime\" string=\"Value\" invisible=\"type not in (''date'', ''datetime'')\"/>\n\t                    <field name=\"value_text\" string=\"Value\" invisible=\"type not in (''char'', ''text'', ''selection'')\"/>\n\t                    <field name=\"value_reference\" string=\"Value\" invisible=\"type != ''many2one''\"/>\n\t                    <field name=\"value_binary\" string=\"Value\" invisible=\"type != ''binary''\"/>\n                    </group>\n                  </sheet>\n                </form>"}', '<?xml version="1.0"?>
<form string="Parameters">
                  <sheet>
                    <group col="4">
                        <field name="name"/>
                        <field name="company_id" groups="base.group_multi_company"/>
                        <newline/>
                        <field name="fields_id"/>
                        <field name="type"/>
                        <field name="res_id"/>
                    </group>
                    <group>
	                    <field name="value_integer" string="Value" invisible="type not in (''integer'', ''boolean'')"/>
	                    <field name="value_float" string="Value" invisible="type != ''float''"/>
	                    <field name="value_datetime" string="Value" invisible="type not in (''date'', ''datetime'')"/>
	                    <field name="value_text" string="Value" invisible="type not in (''char'', ''text'', ''selection'')"/>
	                    <field name="value_reference" string="Value" invisible="type != ''many2one''"/>
	                    <field name="value_binary" string="Value" invisible="type != ''binary''"/>
                    </group>
                  </sheet>
                </form>
            ', false, true, '2026-05-10 01:07:00.002872', '2026-05-10 01:07:00.002872', NULL);
