INSERT INTO public.ir_ui_view VALUES (179, 16, NULL, 1, 1, 'Tests Assets Bundle', NULL, 'web.conditional_assets_tests', 'qweb', 'web/views/webclient_templates.xml', 'primary', '{"en_US": "<t name=\"Tests Assets Bundle\" t-name=\"web.conditional_assets_tests\">\n        <t t-if=\"''tests'' in debug or test_mode_enabled\">\n            <t t-if=\"ignore_missing_deps\">\n                <!-- FIXME: This is only to ignore the errors for the lazy loading. To allow all tests assets and tours to be in the same bundle, the assets_tests bundle ignores missing dependencies -->\n                <t t-call-assets=\"web.__assets_tests_call__\" defer_load=\"True\"/>\n            </t>\n            <t t-else=\"\">\n                <t t-call-assets=\"web.assets_tests\" defer_load=\"True\"/>\n            </t>\n        </t>\n    </t>"}', '<?xml version="1.0"?>
<t name="Tests Assets Bundle" t-name="web.conditional_assets_tests">
        <t t-if="''tests'' in debug or test_mode_enabled">
            <t t-if="ignore_missing_deps">
                <!-- FIXME: This is only to ignore the errors for the lazy loading. To allow all tests assets and tours to be in the same bundle, the assets_tests bundle ignores missing dependencies -->
                <t t-call-assets="web.__assets_tests_call__" defer_load="True"/>
            </t>
            <t t-else="">
                <t t-call-assets="web.assets_tests" defer_load="True"/>
            </t>
        </t>
    </t>

    ', false, true, '2026-05-10 01:07:07.223274', '2026-05-10 01:07:07.223274', NULL);
INSERT INTO public.ir_ui_view VALUES (180, 16, NULL, 1, 1, 'Web layout', NULL, 'web.layout', 'qweb', 'web/views/webclient_templates.xml', 'primary', '{"en_US": "<t name=\"Web layout\" t-name=\"web.layout\">&lt;!DOCTYPE html&gt;\n<html t-att=\"html_data or {}\">\n    <head>\n        <meta charset=\"utf-8\"/>\n        <meta http-equiv=\"X-UA-Compatible\" content=\"IE=edge\"/>\n        <title t-esc=\"title or ''Odoo''\"/>\n        <link type=\"image/x-icon\" rel=\"shortcut icon\" t-att-href=\"x_icon or ''/web/static/img/favicon.ico''\"/>\n        <script id=\"web.layout.odooscript\" type=\"text/javascript\">\n            var odoo = {\n                csrf_token: \"<t t-nocache=\"The csrf token must always be up to date.\" t-esc=\"request.csrf_token(None)\"/>\",\n                debug: \"<t t-esc=\"debug\"/>\",\n            };\n        </script>\n        <t t-out=\"head or ''''\"/>\n    </head>\n    <body t-att-class=\"body_classname\">\n        <t t-out=\"0\"/>\n    </body>\n</html>\n    </t>"}', '<?xml version="1.0"?>
<t name="Web layout" t-name="web.layout">&lt;!DOCTYPE html&gt;
<html t-att="html_data or {}">
    <head>
        <meta charset="utf-8"/>
        <meta http-equiv="X-UA-Compatible" content="IE=edge"/>
        <title t-esc="title or ''Odoo''"/>
        <link type="image/x-icon" rel="shortcut icon" t-att-href="x_icon or ''/web/static/img/favicon.ico''"/>
        <script id="web.layout.odooscript" type="text/javascript">
            var odoo = {
                csrf_token: "<t t-nocache="The csrf token must always be up to date." t-esc="request.csrf_token(None)"/>",
                debug: "<t t-esc="debug"/>",
            };
        </script>
        <t t-out="head or ''''"/>
    </head>
    <body t-att-class="body_classname">
        <t t-out="0"/>
    </body>
</html>
    </t>

    ', false, true, '2026-05-10 01:07:07.223274', '2026-05-10 01:07:07.223274', NULL);
INSERT INTO public.ir_ui_view VALUES (181, 16, 180, 1, 1, 'Frontend Layout', NULL, 'web.frontend_layout', 'qweb', 'web/views/webclient_templates.xml', 'primary', '{"en_US": "<data name=\"Frontend Layout\" inherit_id=\"web.layout\" primary=\"True\">\n      <xpath expr=\"//head/meta[last()]\" position=\"after\">\n        <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\"/>\n      </xpath>\n      <xpath expr=\"//head/link[last()]\" position=\"after\">\n        <link rel=\"preload\" href=\"/web/static/src/libs/fontawesome/fonts/fontawesome-webfont.woff2?v=4.7.0\" as=\"font\" crossorigin=\"\"/>\n        <t t-call-assets=\"web.assets_frontend\" t-js=\"false\"/>\n      </xpath>\n      <xpath expr=\"//head/script[@id=''web.layout.odooscript'']\" position=\"after\">\n        <script t-nocache=\"Session information should always be up to date.\" type=\"text/javascript\">\n            odoo.__session_info__ = <t t-out=\"json.dumps(request.env[''ir.http''].get_frontend_session_info())\"/>;\n            if (!/(^|;\\s)tz=/.test(document.cookie)) {\n                const userTZ = Intl.DateTimeFormat().resolvedOptions().timeZone;\n                document.cookie = `tz=${userTZ}; path=/`;\n            }\n        </script>\n        <t t-call-assets=\"web.assets_frontend_minimal\" t-css=\"false\" defer_load=\"True\"/>\n        <t t-call=\"web.conditional_assets_tests\">\n            <t t-set=\"ignore_missing_deps\" t-value=\"True\"/>\n        </t>\n        <t t-call-assets=\"web.assets_frontend_lazy\" t-css=\"false\" lazy_load=\"True\"/>\n      </xpath>\n        <xpath expr=\"//t[@t-out=''0'']\" position=\"replace\">\n            <div id=\"wrapwrap\" t-attf-class=\"#{pageName or ''''}\">\n                <header t-if=\"not no_header\" id=\"top\" data-anchor=\"true\">\n                    <img class=\"img-responsive d-block mx-auto\" t-attf-src=\"/web/binary/company_logo\" alt=\"Logo\"/>\n                </header>\n                <main>\n                    <t t-out=\"0\"/>\n                </main>\n                <footer t-cache=\"no_footer,no_copyright\" t-if=\"not no_footer\" id=\"bottom\" data-anchor=\"true\" t-attf-class=\"bg-light o_footer\">\n                    <div id=\"footer\"/>\n                    <div t-if=\"not no_copyright\" class=\"o_footer_copyright\">\n                        <div class=\"container py-3\">\n                            <div class=\"row\">\n                                <div class=\"col-sm text-center text-sm-start text-muted\">\n                                    <span class=\"o_footer_copyright_name me-2\">Copyright &amp;copy; <span t-field=\"res_company.name\" itemprop=\"name\">Company name</span></span>\n                                </div>\n                                <div class=\"col-sm text-center text-sm-end\">\n                                    <t t-call=\"web.brand_promotion\"/>\n                                </div>\n                            </div>\n                        </div>\n                    </div>\n                </footer>\n            </div>\n        </xpath>\n    <xpath expr=\".\" position=\"attributes\"><attribute name=\"t-name\">web.frontend_layout</attribute></xpath></data>"}', '<?xml version="1.0"?>
<data name="Frontend Layout" inherit_id="web.layout" primary="True">
      <xpath expr="//head/meta[last()]" position="after">
        <meta name="viewport" content="width=device-width, initial-scale=1"/>
      </xpath>
      <xpath expr="//head/link[last()]" position="after">
        <link rel="preload" href="/web/static/src/libs/fontawesome/fonts/fontawesome-webfont.woff2?v=4.7.0" as="font" crossorigin=""/>
        <t t-call-assets="web.assets_frontend" t-js="false"/>
      </xpath>
      <xpath expr="//head/script[@id=''web.layout.odooscript'']" position="after">
        <script t-nocache="Session information should always be up to date." type="text/javascript">
            odoo.__session_info__ = <t t-out="json.dumps(request.env[''ir.http''].get_frontend_session_info())"/>;
            if (!/(^|;\s)tz=/.test(document.cookie)) {
                const userTZ = Intl.DateTimeFormat().resolvedOptions().timeZone;
                document.cookie = `tz=${userTZ}; path=/`;
            }
        </script>
        <t t-call-assets="web.assets_frontend_minimal" t-css="false" defer_load="True"/>
        <t t-call="web.conditional_assets_tests">
            <t t-set="ignore_missing_deps" t-value="True"/>
        </t>
        <t t-call-assets="web.assets_frontend_lazy" t-css="false" lazy_load="True"/>
      </xpath>
        <xpath expr="//t[@t-out=''0'']" position="replace">
            <div id="wrapwrap" t-attf-class="#{pageName or ''''}">
                <header t-if="not no_header" id="top" data-anchor="true">
                    <img class="img-responsive d-block mx-auto" t-attf-src="/web/binary/company_logo" alt="Logo"/>
                </header>
                <main>
                    <t t-out="0"/>
                </main>
                <footer t-cache="no_footer,no_copyright" t-if="not no_footer" id="bottom" data-anchor="true" t-attf-class="bg-light o_footer">
                    <div id="footer"/>
                    <div t-if="not no_copyright" class="o_footer_copyright">
                        <div class="container py-3">
                            <div class="row">
                                <div class="col-sm text-center text-sm-start text-muted">
                                    <span class="o_footer_copyright_name me-2">Copyright &amp;copy; <span t-field="res_company.name" itemprop="name">Company name</span></span>
                                </div>
                                <div class="col-sm text-center text-sm-end">
                                    <t t-call="web.brand_promotion"/>
                                </div>
                            </div>
                        </div>
                    </div>
                </footer>
            </div>
        </xpath>
    <xpath expr="." position="attributes"><attribute name="t-name">web.frontend_layout</attribute></xpath></data>

    ', false, true, '2026-05-10 01:07:07.223274', '2026-05-10 01:07:07.223274', NULL);
INSERT INTO public.ir_ui_view VALUES (182, 16, NULL, 1, 1, 'Brand Promotion Message', NULL, 'web.brand_promotion_message', 'qweb', 'web/views/webclient_templates.xml', 'primary', '{"en_US": "<t name=\"Brand Promotion Message\" t-name=\"web.brand_promotion_message\">\n        <t t-set=\"odoo_logo\">\n            <a target=\"_blank\" t-attf-href=\"http://www.odoo.com?utm_source=db&amp;utm_medium=#{_utm_medium}\" class=\"badge text-bg-light\">\n                <img alt=\"Odoo\" src=\"/web/static/img/odoo_logo_tiny.png\" width=\"62\" height=\"20\" style=\"width: auto; height: 1em; vertical-align: baseline;\"/>\n            </a>\n        </t>\n        <t t-set=\"final_message\">Powered by %s%s</t>\n        <t t-out=\"final_message % (odoo_logo, _message and (''- '' + _message) or '''')\"/>\n    </t>"}', '<?xml version="1.0"?>
<t name="Brand Promotion Message" t-name="web.brand_promotion_message">
        <t t-set="odoo_logo">
            <a target="_blank" t-attf-href="http://www.odoo.com?utm_source=db&amp;utm_medium=#{_utm_medium}" class="badge text-bg-light">
                <img alt="Odoo" src="/web/static/img/odoo_logo_tiny.png" width="62" height="20" style="width: auto; height: 1em; vertical-align: baseline;"/>
            </a>
        </t>
        <t t-set="final_message">Powered by %s%s</t>
        <t t-out="final_message % (odoo_logo, _message and (''- '' + _message) or '''')"/>
    </t>
    ', false, true, '2026-05-10 01:07:07.223274', '2026-05-10 01:07:07.223274', NULL);
INSERT INTO public.ir_ui_view VALUES (183, 16, NULL, 1, 1, 'Brand Promotion', NULL, 'web.brand_promotion', 'qweb', 'web/views/webclient_templates.xml', 'primary', '{"en_US": "<t name=\"Brand Promotion\" t-name=\"web.brand_promotion\">\n        <div class=\"o_brand_promotion\">\n            <t t-call=\"web.brand_promotion_message\">\n                <t t-set=\"_message\"/>\n                <t t-set=\"_utm_medium\" t-valuef=\"portal\"/>\n            </t>\n        </div>\n    </t>"}', '<?xml version="1.0"?>
<t name="Brand Promotion" t-name="web.brand_promotion">
        <div class="o_brand_promotion">
            <t t-call="web.brand_promotion_message">
                <t t-set="_message"/>
                <t t-set="_utm_medium" t-valuef="portal"/>
            </t>
        </div>
    </t>

    ', false, true, '2026-05-10 01:07:07.223274', '2026-05-10 01:07:07.223274', NULL);
INSERT INTO public.ir_ui_view VALUES (206, 16, NULL, 1, 1, 'preview_internalreport', NULL, 'web.preview_internalreport', 'qweb', 'web/views/report_templates.xml', 'primary', '{"en_US": "<t t-name=\"web.preview_internalreport\">\n        <t t-set=\"company\" t-value=\"env.company\"/>\n        <t t-call=\"web.html_container\">\n            <t t-set=\"o\" t-value=\"res_company\"/>\n            <t t-call=\"web.internal_layout\">\n                <div class=\"page\">\n                    <p>This is a sample of an internal report.</p>\n                </div>\n            </t>\n        </t>\n    </t>"}', '<?xml version="1.0"?>
<t t-name="web.preview_internalreport">
        <t t-set="company" t-value="env.company"/>
        <t t-call="web.html_container">
            <t t-set="o" t-value="res_company"/>
            <t t-call="web.internal_layout">
                <div class="page">
                    <p>This is a sample of an internal report.</p>
                </div>
            </t>
        </t>
    </t>
    ', false, true, '2026-05-10 01:07:07.223274', '2026-05-10 01:07:07.223274', NULL);
INSERT INTO public.ir_ui_view VALUES (184, 16, NULL, 1, 1, 'Login Layout', NULL, 'web.login_layout', 'qweb', 'web/views/webclient_templates.xml', 'primary', '{"en_US": "<t name=\"Login Layout\" t-name=\"web.login_layout\">\n        <t t-call=\"web.frontend_layout\">\n            <t t-set=\"html_data\" t-value=\"{''style'': ''height: 100%;''}\"/>\n            <t t-set=\"body_classname\" t-value=\"''bg-100''\"/>\n            <t t-set=\"no_header\" t-value=\"True\"/>\n            <t t-set=\"no_footer\" t-value=\"True\"/>\n\n            <div class=\"container py-5\">\n                <div t-attf-class=\"card border-0 mx-auto bg-100 {{login_card_classes}} o_database_list\" style=\"max-width: 300px;\">\n                    <div class=\"card-body\">\n                        <div t-attf-class=\"text-center pb-3 border-bottom {{''mb-3'' if form_small else ''mb-4''}}\">\n                            <img t-attf-src=\"/web/binary/company_logo{{ ''?dbname=''+db if db else '''' }}\" alt=\"Logo\" style=\"max-height:120px; max-width: 100%; width:auto\"/>\n                        </div>\n                        <t t-out=\"0\"/>\n                        <div class=\"text-center small mt-4 pt-3 border-top\" t-if=\"not disable_footer\">\n                            <t t-if=\"not disable_database_manager\">\n                                <a class=\"border-end pe-2 me-1\" href=\"/web/database/manager\">Manage Databases</a>\n                            </t>\n                            <a href=\"https://www.odoo.com?utm_source=db&amp;utm_medium=auth\" target=\"_blank\">Powered by <span>Odoo</span></a>\n                        </div>\n                    </div>\n                </div>\n            </div>\n        </t>\n    </t>"}', '<?xml version="1.0"?>
<t name="Login Layout" t-name="web.login_layout">
        <t t-call="web.frontend_layout">
            <t t-set="html_data" t-value="{''style'': ''height: 100%;''}"/>
            <t t-set="body_classname" t-value="''bg-100''"/>
            <t t-set="no_header" t-value="True"/>
            <t t-set="no_footer" t-value="True"/>

            <div class="container py-5">
                <div t-attf-class="card border-0 mx-auto bg-100 {{login_card_classes}} o_database_list" style="max-width: 300px;">
                    <div class="card-body">
                        <div t-attf-class="text-center pb-3 border-bottom {{''mb-3'' if form_small else ''mb-4''}}">
                            <img t-attf-src="/web/binary/company_logo{{ ''?dbname=''+db if db else '''' }}" alt="Logo" style="max-height:120px; max-width: 100%; width:auto"/>
                        </div>
                        <t t-out="0"/>
                        <div class="text-center small mt-4 pt-3 border-top" t-if="not disable_footer">
                            <t t-if="not disable_database_manager">
                                <a class="border-end pe-2 me-1" href="/web/database/manager">Manage Databases</a>
                            </t>
                            <a href="https://www.odoo.com?utm_source=db&amp;utm_medium=auth" target="_blank">Powered by <span>Odoo</span></a>
                        </div>
                    </div>
                </div>
            </div>
        </t>
    </t>

    ', false, true, '2026-05-10 01:07:07.223274', '2026-05-10 01:07:07.223274', NULL);
INSERT INTO public.ir_ui_view VALUES (185, 16, NULL, 1, 1, 'Login', NULL, 'web.login', 'qweb', 'web/views/webclient_templates.xml', 'primary', '{"en_US": "<t name=\"Login\" t-name=\"web.login\">\n        <t t-call=\"web.login_layout\">\n            <form class=\"oe_login_form\" role=\"form\" t-attf-action=\"/web/login\" method=\"post\" onsubmit=\"this.action = ''/web/login'' + location.hash\">\n                <input type=\"hidden\" name=\"csrf_token\" t-att-value=\"request.csrf_token()\"/>\n\n                <div class=\"mb-3\" t-if=\"databases and len(databases) &gt; 1\">\n                    <label for=\"db\" class=\"col-form-label\">Database</label>\n                    <div t-attf-class=\"input-group {{''input-group-sm'' if form_small else ''''}}\">\n                        <input type=\"text\" name=\"db\" t-att-value=\"request.db\" id=\"db\" t-attf-class=\"form-control #{''form-control-sm'' if form_small else ''''}\" required=\"required\" readonly=\"readonly\"/>\n                        <a role=\"button\" href=\"/web/database/selector\" class=\"btn btn-secondary\">Select <i class=\"fa fa-database\" role=\"img\" aria-label=\"Database\" title=\"Database\"/></a>\n                    </div>\n                </div>\n\n                <div class=\"mb-3 field-login\">\n                    <label for=\"login\" class=\"form-label\">Email</label>\n                    <input type=\"text\" placeholder=\"Email\" name=\"login\" t-att-value=\"login\" id=\"login\" t-attf-class=\"form-control #{''form-control-sm'' if form_small else ''''}\" required=\"required\" autocomplete=\"username\" autofocus=\"autofocus\" autocapitalize=\"off\"/>\n                </div>\n\n                <div class=\"mb-3\">\n                    <label for=\"password\" class=\"form-label\">Password</label>\n                    <input type=\"password\" placeholder=\"Password\" name=\"password\" id=\"password\" t-attf-class=\"form-control #{''form-control-sm'' if form_small else ''''}\" required=\"required\" autocomplete=\"current-password\" t-att-autofocus=\"''autofocus'' if login else None\" maxlength=\"4096\"/>\n                </div>\n\n                <p class=\"alert alert-danger\" t-if=\"error\" role=\"alert\">\n                    <t t-esc=\"error\"/>\n                </p>\n                <p class=\"alert alert-success\" t-if=\"message\" role=\"status\">\n                    <t t-esc=\"message\"/>\n                </p>\n\n                <div t-attf-class=\"clearfix oe_login_buttons text-center gap-1 d-grid mb-1 {{''pt-2'' if form_small else ''pt-3''}}\">\n                    <button type=\"submit\" class=\"btn btn-primary\">Log in</button>\n                    <t t-if=\"debug\">\n                        <button type=\"submit\" name=\"redirect\" value=\"/web/become\" class=\"btn btn-link btn-sm\">Log in as superuser</button>\n                    </t>\n                    <div class=\"o_login_auth\"/>\n                </div>\n\n                <input type=\"hidden\" name=\"redirect\" t-att-value=\"redirect\"/>\n            </form>\n        </t>\n    </t>"}', '<?xml version="1.0"?>
<t name="Login" t-name="web.login">
        <t t-call="web.login_layout">
            <form class="oe_login_form" role="form" t-attf-action="/web/login" method="post" onsubmit="this.action = ''/web/login'' + location.hash">
                <input type="hidden" name="csrf_token" t-att-value="request.csrf_token()"/>

                <div class="mb-3" t-if="databases and len(databases) &gt; 1">
                    <label for="db" class="col-form-label">Database</label>
                    <div t-attf-class="input-group {{''input-group-sm'' if form_small else ''''}}">
                        <input type="text" name="db" t-att-value="request.db" id="db" t-attf-class="form-control #{''form-control-sm'' if form_small else ''''}" required="required" readonly="readonly"/>
                        <a role="button" href="/web/database/selector" class="btn btn-secondary">Select <i class="fa fa-database" role="img" aria-label="Database" title="Database"/></a>
                    </div>
                </div>

                <div class="mb-3 field-login">
                    <label for="login" class="form-label">Email</label>
                    <input type="text" placeholder="Email" name="login" t-att-value="login" id="login" t-attf-class="form-control #{''form-control-sm'' if form_small else ''''}" required="required" autocomplete="username" autofocus="autofocus" autocapitalize="off"/>
                </div>

                <div class="mb-3">
                    <label for="password" class="form-label">Password</label>
                    <input type="password" placeholder="Password" name="password" id="password" t-attf-class="form-control #{''form-control-sm'' if form_small else ''''}" required="required" autocomplete="current-password" t-att-autofocus="''autofocus'' if login else None" maxlength="4096"/>
                </div>

                <p class="alert alert-danger" t-if="error" role="alert">
                    <t t-esc="error"/>
                </p>
                <p class="alert alert-success" t-if="message" role="status">
                    <t t-esc="message"/>
                </p>

                <div t-attf-class="clearfix oe_login_buttons text-center gap-1 d-grid mb-1 {{''pt-2'' if form_small else ''pt-3''}}">
                    <button type="submit" class="btn btn-primary">Log in</button>
                    <t t-if="debug">
                        <button type="submit" name="redirect" value="/web/become" class="btn btn-link btn-sm">Log in as superuser</button>
                    </t>
                    <div class="o_login_auth"/>
                </div>

                <input type="hidden" name="redirect" t-att-value="redirect"/>
            </form>
        </t>
    </t>

    ', false, true, '2026-05-10 01:07:07.223274', '2026-05-10 01:07:07.223274', NULL);
INSERT INTO public.ir_ui_view VALUES (186, 16, NULL, 1, 1, 'Login successful', NULL, 'web.login_successful', 'qweb', 'web/views/webclient_templates.xml', 'primary', '{"en_US": "<t name=\"Login successful\" t-name=\"web.login_successful\">\n        <t t-call=\"web.login_layout\">\n            <div class=\"oe_login_form\">\n                <p>\n                    You are logged in.\n                </p>\n                <div t-attf-class=\"clearfix oe_login_buttons text-center mb-1 pt-3\">\n                    <a class=\"btn btn-primary btn-block\" href=\"/web/session/logout\">Log out</a>\n                </div>\n            </div>\n        </t>\n    </t>"}', '<?xml version="1.0"?>
<t name="Login successful" t-name="web.login_successful">
        <t t-call="web.login_layout">
            <div class="oe_login_form">
                <p>
                    You are logged in.
                </p>
                <div t-attf-class="clearfix oe_login_buttons text-center mb-1 pt-3">
                    <a class="btn btn-primary btn-block" href="/web/session/logout">Log out</a>
                </div>
            </div>
        </t>
    </t>

    ', false, true, '2026-05-10 01:07:07.223274', '2026-05-10 01:07:07.223274', NULL);
INSERT INTO public.ir_ui_view VALUES (187, 16, NULL, 1, 1, 'web.test_helpers', NULL, 'web.test_helpers', 'qweb', 'web/views/webclient_templates.xml', 'primary', '{"en_US": "<t t-name=\"web.test_helpers\">\n        <t t-call-assets=\"web.tests_assets\" t-js=\"False\"/>\n        <style>\n            body {\n                position: relative; /* bootstrap-datepicker needs this */\n            }\n            body:not(.debug) .modal-backdrop, body:not(.debug) .modal:not(.o_module_error), body:not(.debug) .ui-autocomplete {\n                opacity: 0 !important;\n            }\n            #qunit-testrunner-toolbar label {\n                font-weight: inherit;\n                margin-bottom: inherit;\n            }\n            #qunit-testrunner-toolbar input[type=text] {\n                width: inherit;\n                display: inherit;\n            }\n        </style>\n        <t t-call-assets=\"web.tests_assets\" t-css=\"False\"/>\n    </t>"}', '<?xml version="1.0"?>
<t t-name="web.test_helpers">
        <t t-call-assets="web.tests_assets" t-js="False"/>
        <style>
            body {
                position: relative; /* bootstrap-datepicker needs this */
            }
            body:not(.debug) .modal-backdrop, body:not(.debug) .modal:not(.o_module_error), body:not(.debug) .ui-autocomplete {
                opacity: 0 !important;
            }
            #qunit-testrunner-toolbar label {
                font-weight: inherit;
                margin-bottom: inherit;
            }
            #qunit-testrunner-toolbar input[type=text] {
                width: inherit;
                display: inherit;
            }
        </style>
        <t t-call-assets="web.tests_assets" t-css="False"/>
    </t>

    ', false, true, '2026-05-10 01:07:07.223274', '2026-05-10 01:07:07.223274', NULL);
INSERT INTO public.ir_ui_view VALUES (188, 16, NULL, 1, 1, 'web.qunit_suite', NULL, 'web.qunit_suite', 'qweb', 'web/views/webclient_templates.xml', 'primary', '{"en_US": "<t t-name=\"web.qunit_suite\">\n        <t t-call=\"web.layout\">\n            <t t-set=\"html_data\" t-value=\"{''style'': ''height: 100%;''}\"/>\n            <t t-set=\"title\">Web Tests</t>\n            <t t-set=\"head\">\n                <t t-call=\"web.test_helpers\"/>\n\n                <t t-call-assets=\"web.qunit_suite_tests\" t-js=\"false\"/>\n                <t t-call-assets=\"web.qunit_suite_tests\" t-css=\"false\"/>\n            </t>\n            <div id=\"qunit\"/>\n            <div id=\"qunit-fixture\"/>\n        </t>\n    </t>"}', '<?xml version="1.0"?>
<t t-name="web.qunit_suite">
