            </t>
            <div id="qunit"/>
            <div id="qunit-fixture"/>
        </t>
    </t>

    ', false, true, '2026-05-10 01:07:07.223274', '2026-05-10 01:07:07.223274', NULL);
INSERT INTO public.ir_ui_view VALUES (207, 16, NULL, 1, 1, 'preview_externalreport', NULL, 'web.preview_externalreport', 'qweb', 'web/views/report_templates.xml', 'primary', '{"en_US": "<t t-name=\"web.preview_externalreport\">\n        <t t-set=\"company\" t-value=\"env.company\"/>\n        <t t-call=\"web.html_container\">\n            <t t-set=\"o\" t-value=\"res_company\"/>\n            <t t-call=\"web.external_layout\">\n                <div class=\"page\">\n                    <p>This is a sample of an external report.</p>\n                </div>\n            </t>\n        </t>\n    </t>"}', '<?xml version="1.0"?>
