INSERT INTO public.ir_ui_view VALUES (189, 16, NULL, 1, 1, 'web.qunit_mobile_suite', NULL, 'web.qunit_mobile_suite', 'qweb', 'web/views/webclient_templates.xml', 'primary', '{"en_US": "<t t-name=\"web.qunit_mobile_suite\">\n        <t t-call=\"web.layout\">\n            <t t-set=\"html_data\" t-value=\"{''style'': ''height: 100%;''}\"/>\n            <t t-set=\"title\">Web Mobile Tests</t>\n            <t t-set=\"head\">\n                <meta name=\"viewport\" content=\"width=device-width, initial-scale=1, user-scalable=no\"/>\n\n                <t t-call=\"web.test_helpers\"/>\n\n                <t t-call-assets=\"web.qunit_mobile_suite_tests\" t-js=\"false\"/>\n                <t t-call-assets=\"web.qunit_mobile_suite_tests\" t-css=\"false\"/>\n            </t>\n            <div id=\"qunit\"/>\n            <div id=\"qunit-fixture\"/>\n        </t>\n    </t>"}', '<?xml version="1.0"?>
<t t-name="web.qunit_mobile_suite">
