INSERT INTO public.ir_ui_view VALUES (190, 16, NULL, 1, 1, 'web.webclient_bootstrap', NULL, 'web.webclient_bootstrap', 'qweb', 'web/views/webclient_templates.xml', 'primary', '{"en_US": "<t t-name=\"web.webclient_bootstrap\">\n        <t t-call=\"web.layout\">\n            <t t-set=\"head_web\">\n                <meta name=\"viewport\" content=\"width=device-width, initial-scale=1, user-scalable=no\"/>\n                <meta name=\"theme-color\" content=\"#71639e\"/>\n                <link rel=\"manifest\" href=\"/web/manifest.webmanifest\" crossorigin=\"use-credentials\"/>\n                <link rel=\"apple-touch-icon\" href=\"/web/static/img/odoo-icon-ios.png\"/>\n                <script type=\"text/javascript\">\n                    // Block to avoid leaking variables in the script scope\n                    {\n                        odoo.__session_info__ = <t t-out=\"json.dumps(session_info)\"/>;\n                        const { user_context,  cache_hashes } = odoo.__session_info__;\n                        const lang = new URLSearchParams(document.location.search).get(\"lang\");\n                        let menuURL = `/web/webclient/load_menus/${cache_hashes.load_menus}`;\n                        if (lang) {\n                            user_context.lang = lang;\n                            menuURL += `?lang=${lang}`\n                        }\n                        odoo.reloadMenus = () =&gt; fetch(menuURL).then(res =&gt; res.json());\n                        odoo.loadMenusPromise = odoo.reloadMenus();\n                        // Prefetch translations to speedup webclient. This is done in JS because link rel=\"prefetch\"\n                        // is not yet supported on safari.\n                        fetch(`/web/webclient/translations/${cache_hashes.translations}?lang=${user_context.lang}`);\n                    }\n                </script>\n                <t t-if=\"request.httprequest.cookies.get(''color_scheme'') == ''dark''\">\n                    <t t-call-assets=\"web.assets_web_dark\"/>\n                </t>\n                <t t-else=\"\">\n                    <t t-call-assets=\"web.assets_web\"/>\n                </t>\n                <t t-call=\"web.conditional_assets_tests\"/>\n            </t>\n            <t t-set=\"head\" t-value=\"head_web + (head or '''')\"/>\n            <t t-set=\"body_classname\" t-value=\"''o_web_client''\"/>\n        </t>\n    </t>"}', '<?xml version="1.0"?>
<t t-name="web.webclient_bootstrap">
        <t t-call="web.layout">
            <t t-set="head_web">
                <meta name="viewport" content="width=device-width, initial-scale=1, user-scalable=no"/>
                <meta name="theme-color" content="#71639e"/>
                <link rel="manifest" href="/web/manifest.webmanifest" crossorigin="use-credentials"/>
                <link rel="apple-touch-icon" href="/web/static/img/odoo-icon-ios.png"/>
                <script type="text/javascript">
                    // Block to avoid leaking variables in the script scope
                    {
                        odoo.__session_info__ = <t t-out="json.dumps(session_info)"/>;
                        const { user_context,  cache_hashes } = odoo.__session_info__;
                        const lang = new URLSearchParams(document.location.search).get("lang");
                        let menuURL = `/web/webclient/load_menus/${cache_hashes.load_menus}`;
                        if (lang) {
                            user_context.lang = lang;
                            menuURL += `?lang=${lang}`
                        }
                        odoo.reloadMenus = () =&gt; fetch(menuURL).then(res =&gt; res.json());
                        odoo.loadMenusPromise = odoo.reloadMenus();
                        // Prefetch translations to speedup webclient. This is done in JS because link rel="prefetch"
                        // is not yet supported on safari.
                        fetch(`/web/webclient/translations/${cache_hashes.translations}?lang=${user_context.lang}`);
                    }
                </script>
                <t t-if="request.httprequest.cookies.get(''color_scheme'') == ''dark''">
                    <t t-call-assets="web.assets_web_dark"/>
                </t>
                <t t-else="">
                    <t t-call-assets="web.assets_web"/>
                </t>
                <t t-call="web.conditional_assets_tests"/>
            </t>
            <t t-set="head" t-value="head_web + (head or '''')"/>
            <t t-set="body_classname" t-value="''o_web_client''"/>
        </t>
    </t>

    ', false, true, '2026-05-10 01:07:07.223274', '2026-05-10 01:07:07.223274', NULL);
INSERT INTO public.ir_ui_view VALUES (191, 16, NULL, 1, 1, 'webclient_offline', NULL, 'web.webclient_offline', 'qweb', 'web/views/webclient_templates.xml', 'primary', '{"en_US": "<t t-name=\"web.webclient_offline\">\n        <t t-call=\"web.layout\">\n            <t t-set=\"html_data\" t-value=\"{''style'': ''height: 100%;''}\"/>\n            <t t-set=\"title\">Offline</t>\n            <t t-set=\"head\">\n                <script type=\"text/javascript\">\n                    window.addEventListener(''online'', () =&gt; location.reload());\n                </script>\n                <style>\n                    body {\n                    font-family: -apple-system, BlinkMacSystemFont, \"Segoe UI\", Roboto, \"Helvetica Neue\", Ubuntu, \"Noto Sans\", Arial, sans-serif, \"Apple Color Emoji\", \"Segoe UI Emoji\", \"Segoe UI Symbol\", \"Noto Color Emoji\";\n                    padding:0;\n                    margin:0;\n                    background-color: #fff;\n                    color: rgb(17, 24, 39);\n                    display: flex;\n                    align-items: center;\n                    justify-content: center;\n                    text-align: center;\n                    height: 100vh;\n                    width: 100vw;\n                    user-select: none;\n                    }\n                    .card {\n                    width: 80%;\n                    }\n                    .card img {\n                    width: 96px;\n                    height: auto;\n                    filter: grayscale(.6);\n                    }\n                    .card button {\n                    background-color: #714B67;\n                    color: #FFFFFF;\n                    border: 1px solid #714B67;\n                    border-radius: .25rem;\n                    padding: .5rem 1rem;\n                    cursor: pointer;\n                    font-size: 1.2rem;\n                    font-weight: 500;\n                    }\n                </style>\n                <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\"/>\n            </t>\n            <div class=\"card\">\n                <img t-attf-src=\"data:image/png;base64,{{odoo_icon}}\" alt=\"Odoo logo\"/>\n                <h1>You are offline</h1>\n                <p>Check your network connection and come back here. Odoo will load as soon as you''re back online.</p>\n                <button onclick=\"location.reload()\">Check again</button>\n            </div>\n        </t>\n    </t>"}', '<?xml version="1.0"?>
<t t-name="web.webclient_offline">
        <t t-call="web.layout">
            <t t-set="html_data" t-value="{''style'': ''height: 100%;''}"/>
            <t t-set="title">Offline</t>
            <t t-set="head">
                <script type="text/javascript">
                    window.addEventListener(''online'', () =&gt; location.reload());
                </script>
                <style>
                    body {
                    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Ubuntu, "Noto Sans", Arial, sans-serif, "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol", "Noto Color Emoji";
                    padding:0;
                    margin:0;
                    background-color: #fff;
                    color: rgb(17, 24, 39);
                    display: flex;
                    align-items: center;
                    justify-content: center;
                    text-align: center;
                    height: 100vh;
                    width: 100vw;
                    user-select: none;
                    }
                    .card {
                    width: 80%;
                    }
                    .card img {
                    width: 96px;
                    height: auto;
                    filter: grayscale(.6);
                    }
                    .card button {
                    background-color: #714B67;
                    color: #FFFFFF;
                    border: 1px solid #714B67;
                    border-radius: .25rem;
                    padding: .5rem 1rem;
                    cursor: pointer;
                    font-size: 1.2rem;
                    font-weight: 500;
                    }
                </style>
                <meta name="viewport" content="width=device-width, initial-scale=1"/>
            </t>
            <div class="card">
                <img t-attf-src="data:image/png;base64,{{odoo_icon}}" alt="Odoo logo"/>
                <h1>You are offline</h1>
                <p>Check your network connection and come back here. Odoo will load as soon as you''re back online.</p>
                <button onclick="location.reload()">Check again</button>
            </div>
        </t>
    </t>
', false, true, '2026-05-10 01:07:07.223274', '2026-05-10 01:07:07.223274', NULL);
INSERT INTO public.ir_ui_view VALUES (192, 16, NULL, 1, 1, 'Report layout', NULL, 'web.report_layout', 'qweb', 'web/views/report_templates.xml', 'primary', '{"en_US": "<t name=\"Report layout\" t-name=\"web.report_layout\">&lt;!DOCTYPE html&gt;\n        <html t-att-lang=\"lang and lang.replace(''_'', ''-'')\" t-att-data-report-margin-top=\"data_report_margin_top\" t-att-data-report-header-spacing=\"data_report_header_spacing\" t-att-data-report-dpi=\"data_report_dpi\" t-att-data-report-landscape=\"data_report_landscape\" t-att-web-base-url=\"web_base_url\">\n            <head>\n                <meta charset=\"utf-8\"/>\n                <meta name=\"viewport\" content=\"initial-scale=1\"/>\n                <title><t t-esc=\"title or ''Odoo Report''\"/></title>\n                <t t-call-assets=\"web.report_assets_common\"/>\n                <!-- Temporary code: only used to maintain CSS for legacy HTML reports (full width...) -->\n                <!-- Should be removed once the reports are fully converted. -->\n                <script type=\"text/javascript\">\n                    document.addEventListener(''DOMContentLoaded'', () =&gt; {\n                        if (window.self !== window.top) {\n                            document.body.classList.add(\"o_in_iframe\", \"container-fluid\");\n                            document.body.classList.remove(\"container\");\n                        }\n                    });\n                </script>\n            </head>\n            <body t-att-class=\"''container'' if not full_width else ''container-fluid''\" t-att-dir=\"env[''res.lang'']._lang_get(lang or env.user.lang).direction or ''ltr''\">\n                <div id=\"wrapwrap\">\n                    <main>\n                        <t t-out=\"0\"/>\n                    </main>\n                </div>\n            </body>\n        </html>\n    </t>"}', '<?xml version="1.0"?>
<t name="Report layout" t-name="web.report_layout">&lt;!DOCTYPE html&gt;
        <html t-att-lang="lang and lang.replace(''_'', ''-'')" t-att-data-report-margin-top="data_report_margin_top" t-att-data-report-header-spacing="data_report_header_spacing" t-att-data-report-dpi="data_report_dpi" t-att-data-report-landscape="data_report_landscape" t-att-web-base-url="web_base_url">
            <head>
                <meta charset="utf-8"/>
                <meta name="viewport" content="initial-scale=1"/>
                <title><t t-esc="title or ''Odoo Report''"/></title>
                <t t-call-assets="web.report_assets_common"/>
                <!-- Temporary code: only used to maintain CSS for legacy HTML reports (full width...) -->
                <!-- Should be removed once the reports are fully converted. -->
                <script type="text/javascript">
                    document.addEventListener(''DOMContentLoaded'', () =&gt; {
                        if (window.self !== window.top) {
                            document.body.classList.add("o_in_iframe", "container-fluid");
                            document.body.classList.remove("container");
                        }
                    });
                </script>
            </head>
            <body t-att-class="''container'' if not full_width else ''container-fluid''" t-att-dir="env[''res.lang'']._lang_get(lang or env.user.lang).direction or ''ltr''">
                <div id="wrapwrap">
                    <main>
                        <t t-out="0"/>
                    </main>
                </div>
            </body>
        </html>
    </t>

    ', false, true, '2026-05-10 01:07:07.223274', '2026-05-10 01:07:07.223274', NULL);
INSERT INTO public.ir_ui_view VALUES (193, 16, NULL, 1, 1, 'Report layout', NULL, 'web.report_preview_layout', 'qweb', 'web/views/report_templates.xml', 'primary', '{"en_US": "<t name=\"Report layout\" t-name=\"web.report_preview_layout\">&lt;!DOCTYPE html&gt;\n        <html t-att-lang=\"lang and lang.replace(''_'', ''-'')\" t-att-data-report-margin-top=\"data_report_margin_top\" t-att-data-report-header-spacing=\"data_report_header_spacing\" t-att-data-report-dpi=\"data_report_dpi\" t-att-data-report-landscape=\"data_report_landscape\" t-att-web-base-url=\"web_base_url\">\n            <head>\n                <meta charset=\"utf-8\"/>\n                <meta name=\"viewport\" content=\"initial-scale=1\"/>\n                <title><t t-esc=\"title or ''Odoo Report''\"/></title>\n                <t t-call-assets=\"web.report_assets_common\" t-js=\"false\"/>\n                <style>\n                    <t t-out=\"preview_css\"/>\n\n                    /**\n                        Some css is overridden as it doesn''t work properly in the preview.\n                        Before generating ''real'' reports, a lot of processing is applied. It is therefore quite\n                        complicated to have an almost exact replica of the pdf report.\n                        This changes down here are hacks to make the preview look as good as possible.\n                    **/\n\n                    /** The footers are not at the bottom of the page, so we push them down. **/\n                    .o_background_footer, .o_standard_footer, .o_boxed_footer, .o_clean_footer {\n                        position: absolute;\n                        bottom: 0;\n                        left:50px;\n                        right:50px;\n                        font-size: 0.8rem\n                    }\n                    /** Avoid image overflowing and creating a scrollbar **/\n                    .o_background_header {\n                        min-width: initial !important;\n                    }\n\n                    /** This rule is overridden in web/report.scss to hack around whtml2pdf\n                        Simply set it to its default value so it works properly in preview **/\n                    .col-auto{\n                        -webkit-box-flex: 0 !important;\n                        -webkit-flex: 0 0 auto !important;\n                        flex: 0 0 auto !important;\n                        width: auto !important;\n                        max-width: 100% !important;\n                    }\n\n                </style>\n            </head>\n            <body t-att-class=\"''container'' if not full_width else ''container-fluid''\" style=\"overflow:hidden\" t-att-dir=\"env[''res.lang'']._lang_get(lang or env.user.lang).direction or ''ltr''\">\n                <div id=\"wrapwrap\">\n                        <t t-out=\"0\"/>\n                </div>\n            </body>\n        </html>\n    </t>"}', '<?xml version="1.0"?>
<t name="Report layout" t-name="web.report_preview_layout">&lt;!DOCTYPE html&gt;
        <html t-att-lang="lang and lang.replace(''_'', ''-'')" t-att-data-report-margin-top="data_report_margin_top" t-att-data-report-header-spacing="data_report_header_spacing" t-att-data-report-dpi="data_report_dpi" t-att-data-report-landscape="data_report_landscape" t-att-web-base-url="web_base_url">
            <head>
                <meta charset="utf-8"/>
                <meta name="viewport" content="initial-scale=1"/>
                <title><t t-esc="title or ''Odoo Report''"/></title>
                <t t-call-assets="web.report_assets_common" t-js="false"/>
                <style>
                    <t t-out="preview_css"/>

                    /**
                        Some css is overridden as it doesn''t work properly in the preview.
                        Before generating ''real'' reports, a lot of processing is applied. It is therefore quite
                        complicated to have an almost exact replica of the pdf report.
                        This changes down here are hacks to make the preview look as good as possible.
                    **/

                    /** The footers are not at the bottom of the page, so we push them down. **/
                    .o_background_footer, .o_standard_footer, .o_boxed_footer, .o_clean_footer {
                        position: absolute;
                        bottom: 0;
                        left:50px;
                        right:50px;
                        font-size: 0.8rem
                    }
                    /** Avoid image overflowing and creating a scrollbar **/
                    .o_background_header {
                        min-width: initial !important;
                    }

                    /** This rule is overridden in web/report.scss to hack around whtml2pdf
                        Simply set it to its default value so it works properly in preview **/
                    .col-auto{
                        -webkit-box-flex: 0 !important;
                        -webkit-flex: 0 0 auto !important;
                        flex: 0 0 auto !important;
                        width: auto !important;
                        max-width: 100% !important;
                    }

                </style>
            </head>
            <body t-att-class="''container'' if not full_width else ''container-fluid''" style="overflow:hidden" t-att-dir="env[''res.lang'']._lang_get(lang or env.user.lang).direction or ''ltr''">
                <div id="wrapwrap">
                        <t t-out="0"/>
                </div>
            </body>
        </html>
    </t>

    ', false, true, '2026-05-10 01:07:07.223274', '2026-05-10 01:07:07.223274', NULL);
INSERT INTO public.ir_ui_view VALUES (194, 16, NULL, 1, 1, 'html_container', NULL, 'web.html_container', 'qweb', 'web/views/report_templates.xml', 'primary', '{"en_US": "<t t-name=\"web.html_container\">\n        <t t-set=\"body_classname\" t-value=\"''container''\"/>\n        <t t-call=\"web.report_layout\">\n            <t t-out=\"0\"/>\n        </t>\n    </t>"}', '<?xml version="1.0"?>
<t t-name="web.html_container">
        <t t-set="body_classname" t-value="''container''"/>
        <t t-call="web.report_layout">
            <t t-out="0"/>
        </t>
    </t>

    ', false, true, '2026-05-10 01:07:07.223274', '2026-05-10 01:07:07.223274', NULL);
INSERT INTO public.ir_ui_view VALUES (195, 16, NULL, 1, 1, 'html_preview_container', NULL, 'web.html_preview_container', 'qweb', 'web/views/report_templates.xml', 'primary', '{"en_US": "<t t-name=\"web.html_preview_container\">\n        <t t-set=\"body_classname\" t-value=\"''container''\"/>\n        <t t-call=\"web.report_preview_layout\">\n            <t t-out=\"0\"/>\n        </t>\n    </t>"}', '<?xml version="1.0"?>
