INSERT INTO public.ir_ui_view VALUES (196, 16, NULL, 1, 1, 'report_invoice_wizard_preview', NULL, 'web.report_invoice_wizard_preview', 'qweb', 'web/views/report_templates.xml', 'primary', '{"en_US": "<t t-name=\"web.report_invoice_wizard_preview\">\n        <t t-call=\"web.html_preview_container\">\n           <t t-call=\"web.external_layout\">\n                   <t t-set=\"address\">\n                       <address class=\"mb-0\" itemscope=\"itemscope\" itemtype=\"http://schema.org/Organization\">\n                           <div>\n                               <span itemprop=\"name\">Acme Corporation</span>\n                           </div>\n                           <div itemprop=\"address\" itemscope=\"itemscope\" itemtype=\"http://schema.org/PostalAddress\">\n                               <div class=\"d-flex align-items-baseline\">\n                                   <span class=\"w-100 o_force_ltr\" itemprop=\"streetAddress\">77 Santa Barbara\n                                       Rd<br/>Pleasant Hill CA 94523<br/>United States</span>\n                               </div>\n                           </div>\n                       </address>\n                   </t>\n                   <div class=\"page mt-5\">\n                       <h2>\n                           <span>Invoice</span>\n                           <span>INV/2023/00003</span>\n                       </h2>\n                       <div id=\"informations\" class=\"row mt-4 mb-4\">\n                           <div class=\"col-auto col-3 mw-100 mb-2\" name=\"invoice_date\">\n                               <strong>Invoice Date:</strong>\n                               <p class=\"m-0\">07/08/2020</p>\n                           </div>\n                           <div class=\"col-auto col-3 mw-100 mb-2\" name=\"due_date\">\n                               <strong>Due Date:</strong>\n                               <p class=\"m-0\">08/07/2020</p>\n                           </div>\n                       </div>\n                       <table class=\"table table-sm o_main_table table-borderless\" name=\"invoice_line_table\">\n                           <thead>\n                               <tr>\n                                   <th name=\"th_description\" class=\"text-start\"><span>Description</span></th>\n                                   <th name=\"th_quantity\" class=\"text-end\"><span>Quantity</span></th>\n                                   <th name=\"th_priceunit\" class=\"text-end d-md-table-cell\"><span>Unit Price</span></th>\n                                   <th name=\"th_taxes\" class=\"text-end d-md-table-cell\"><span>Taxes</span></th>\n                                   <th name=\"th_subtotal\" class=\"text-end\">\n                                       <span>Amount</span>\n                                   </th>\n                               </tr>\n                           </thead>\n                           <tbody class=\"invoice_tbody\">\n                               <tr>\n                                   <td name=\"account_invoice_line_name\"><span>[FURN_8999] Three-Seat Sofa<br/>\n                                       Three Seater Sofa with Lounger in Steel Grey Colour</span></td>\n                                   <td class=\"text-end\">\n                                       <span>5.00</span>\n                                   </td>\n                                   <td class=\"text-end d-md-table-cell\">\n                                       <span class=\"text-nowrap\">1,500.00</span>\n                                   </td>\n                                   <td class=\"text-end d-md-table-cell\">\n                                       <span id=\"line_tax_ids\">Tax 15%</span>\n                                   </td>\n                                   <td class=\"text-end o_price_total\">\n                                       <span class=\"text-nowrap\">$ <span class=\"oe_currency_value\">7,500.00</span></span>\n                                   </td>\n                               </tr>\n                               <tr>\n                                   <td name=\"account_invoice_line_name\"><span>[FURN_8220] Four Person Desk<br/>\n                                       Four person modern office workstation</span></td>\n                                   <td class=\"text-end\">\n                                       <span>5.00</span>\n                                   </td>\n                                   <td class=\"text-end d-md-table-cell\">\n                                       <span class=\"text-nowrap\">2,350.00</span>\n                                   </td>\n                                   <td class=\"text-end d-md-table-cell\">\n                                       <span id=\"line_tax_ids\">Tax 15%</span>\n                                   </td>\n                                   <td class=\"text-end o_price_total\">\n                                       <span class=\"text-nowrap\">$ <span class=\"oe_currency_value\">11,750.00</span></span>\n                                   </td>\n                               </tr>\n                           </tbody>\n                       </table>\n                       <div id=\"right-elements\" t-attf-class=\"#{''col-5'' if report_type != ''html'' else ''col-12 col-md-5''} ms-5 d-inline-block float-end\">\n                           <div id=\"total\" class=\"clearfix row\">\n                               <div class=\"ms-auto\">\n                                   <table class=\"table table-sm table-borderless\" style=\"page-break-inside: avoid; position:relative;\">\n                                       <tbody><tr class=\"border-black o_subtotal\" style=\"\">\n                                           <td><strong>Untaxed Amount</strong></td>\n                                           <td class=\"text-end\">\n                                               <span>$ <span class=\"oe_currency_value\">19,250.00</span></span>\n                                           </td>\n                                       </tr>\n                                           <tr style=\"\">\n                                               <td><span class=\"text-nowrap\">Tax 15%</span></td>\n                                               <td class=\"text-end o_price_total\">\n                                                   <span class=\"text-nowrap\">$ 2,887.50</span>\n                                               </td>\n                                           </tr>\n                                           <tr class=\"border-black o_total\">\n                                               <td><strong>Total</strong></td>\n                                               <td class=\"text-end\">\n                                                   <span class=\"text-nowrap\">$ <span class=\"oe_currency_value\">\n                                                       22,137.50</span></span>\n                                               </td>\n                                           </tr>\n                                       </tbody></table>\n                               </div>\n                           </div>\n                       </div>\n                       <div id=\"payment_term\">\n                            <div class=\"mb-3\">\n                                <p name=\"payment_term\">\n                                    <span>Payment terms: 30 Days</span>\n                                </p>\n                                <p name=\"payment_communication\">\n                                    Payment Communication: <b><span>INV/2023/00003</span></b>\n                                </p>\n                            </div>\n                        </div>\n                   </div>\n           </t>\n        </t>\n    </t>"}', '<?xml version="1.0"?>
<t t-name="web.report_invoice_wizard_preview">
        <t t-call="web.html_preview_container">
           <t t-call="web.external_layout">
                   <t t-set="address">
                       <address class="mb-0" itemscope="itemscope" itemtype="http://schema.org/Organization">
                           <div>
                               <span itemprop="name">Acme Corporation</span>
                           </div>
                           <div itemprop="address" itemscope="itemscope" itemtype="http://schema.org/PostalAddress">
                               <div class="d-flex align-items-baseline">
                                   <span class="w-100 o_force_ltr" itemprop="streetAddress">77 Santa Barbara
                                       Rd<br/>Pleasant Hill CA 94523<br/>United States</span>
                               </div>
                           </div>
                       </address>
                   </t>
                   <div class="page mt-5">
                       <h2>
                           <span>Invoice</span>
                           <span>INV/2023/00003</span>
                       </h2>
                       <div id="informations" class="row mt-4 mb-4">
                           <div class="col-auto col-3 mw-100 mb-2" name="invoice_date">
                               <strong>Invoice Date:</strong>
                               <p class="m-0">07/08/2020</p>
                           </div>
                           <div class="col-auto col-3 mw-100 mb-2" name="due_date">
                               <strong>Due Date:</strong>
                               <p class="m-0">08/07/2020</p>
                           </div>
                       </div>
                       <table class="table table-sm o_main_table table-borderless" name="invoice_line_table">
                           <thead>
                               <tr>
                                   <th name="th_description" class="text-start"><span>Description</span></th>
                                   <th name="th_quantity" class="text-end"><span>Quantity</span></th>
                                   <th name="th_priceunit" class="text-end d-md-table-cell"><span>Unit Price</span></th>
                                   <th name="th_taxes" class="text-end d-md-table-cell"><span>Taxes</span></th>
                                   <th name="th_subtotal" class="text-end">
                                       <span>Amount</span>
                                   </th>
                               </tr>
                           </thead>
                           <tbody class="invoice_tbody">
                               <tr>
                                   <td name="account_invoice_line_name"><span>[FURN_8999] Three-Seat Sofa<br/>
                                       Three Seater Sofa with Lounger in Steel Grey Colour</span></td>
                                   <td class="text-end">
                                       <span>5.00</span>
                                   </td>
                                   <td class="text-end d-md-table-cell">
                                       <span class="text-nowrap">1,500.00</span>
                                   </td>
                                   <td class="text-end d-md-table-cell">
                                       <span id="line_tax_ids">Tax 15%</span>
                                   </td>
                                   <td class="text-end o_price_total">
                                       <span class="text-nowrap">$ <span class="oe_currency_value">7,500.00</span></span>
                                   </td>
                               </tr>
                               <tr>
                                   <td name="account_invoice_line_name"><span>[FURN_8220] Four Person Desk<br/>
                                       Four person modern office workstation</span></td>
                                   <td class="text-end">
                                       <span>5.00</span>
                                   </td>
                                   <td class="text-end d-md-table-cell">
                                       <span class="text-nowrap">2,350.00</span>
                                   </td>
                                   <td class="text-end d-md-table-cell">
                                       <span id="line_tax_ids">Tax 15%</span>
                                   </td>
                                   <td class="text-end o_price_total">
                                       <span class="text-nowrap">$ <span class="oe_currency_value">11,750.00</span></span>
                                   </td>
                               </tr>
                           </tbody>
                       </table>
                       <div id="right-elements" t-attf-class="#{''col-5'' if report_type != ''html'' else ''col-12 col-md-5''} ms-5 d-inline-block float-end">
                           <div id="total" class="clearfix row">
                               <div class="ms-auto">
                                   <table class="table table-sm table-borderless" style="page-break-inside: avoid; position:relative;">
                                       <tbody><tr class="border-black o_subtotal" style="">
                                           <td><strong>Untaxed Amount</strong></td>
                                           <td class="text-end">
                                               <span>$ <span class="oe_currency_value">19,250.00</span></span>
                                           </td>
                                       </tr>
                                           <tr style="">
                                               <td><span class="text-nowrap">Tax 15%</span></td>
                                               <td class="text-end o_price_total">
                                                   <span class="text-nowrap">$ 2,887.50</span>
                                               </td>
                                           </tr>
                                           <tr class="border-black o_total">
                                               <td><strong>Total</strong></td>
                                               <td class="text-end">
                                                   <span class="text-nowrap">$ <span class="oe_currency_value">
                                                       22,137.50</span></span>
                                               </td>
                                           </tr>
                                       </tbody></table>
                               </div>
                           </div>
                       </div>
                       <div id="payment_term">
                            <div class="mb-3">
                                <p name="payment_term">
                                    <span>Payment terms: 30 Days</span>
                                </p>
                                <p name="payment_communication">
                                    Payment Communication: <b><span>INV/2023/00003</span></b>
                                </p>
                            </div>
                        </div>
                   </div>
           </t>
        </t>
    </t>

    ', false, true, '2026-05-10 01:07:07.223274', '2026-05-10 01:07:07.223274', NULL);
INSERT INTO public.ir_ui_view VALUES (197, 16, NULL, 1, 1, 'minimal_layout', NULL, 'web.minimal_layout', 'qweb', 'web/views/report_templates.xml', 'primary', '{"en_US": "<t t-name=\"web.minimal_layout\">\n        &lt;!DOCTYPE html&gt;\n        <html style=\"height: 0;\">\n            <head>\n                <base t-att-href=\"base_url\"/>\n                <t t-call-assets=\"web.report_assets_pdf\" t-js=\"false\"/>\n                <t t-call-assets=\"web.report_assets_common\" t-js=\"false\"/>\n                <t t-call-assets=\"web.report_assets_pdf\" t-css=\"false\"/>\n                <meta charset=\"utf-8\"/>\n                <script t-if=\"subst\">\n                    function subst() {\n                        var vars = {};\n                        var x = document.location.search.substring(1).split(''&amp;'');\n                        for (var i in x) {\n                            var z = x[i].split(''='', 2);\n                            vars[z[0]] = unescape(z[1]);\n                        }\n                        var x = [''sitepage'', ''sitepages'', ''section'', ''subsection'', ''subsubsection''];\n                        var z = {''sitepage'': ''page'', ''sitepages'': ''topage''};\n                        for (var i in x) {\n                            var y = document.getElementsByClassName(z[x[i]] || x[i])\n                            for (var j=0; j&lt;y.length; ++j)\n                                y[j].textContent = vars[x[i]];\n                        }\n\n                        var index = vars[''webpage''].split(''.'', 4)[3];\n                        var header = document.getElementById(''minimal_layout_report_headers'');\n                        if(header){\n                            var companyHeader = header.children[index];\n                            header.textContent = '''';\n                            header.appendChild(companyHeader);\n                        }\n                        var footer = document.getElementById(''minimal_layout_report_footers'');\n                        if(footer){\n                            var companyFooter = footer.children[index];\n                            footer.textContent = '''';\n                            footer.appendChild(companyFooter);\n                        }\n                    }\n                </script>\n            </head>\n            <body class=\"container\" t-att-data-report-id=\"report_xml_id\" t-att-onload=\"subst and ''subst()''\" style=\"overflow:hidden\" t-att-dir=\"env[''res.lang'']._lang_get(lang or env.user.lang).direction or ''ltr''\">\n                <t t-out=\"body\"/>\n            </body>\n        </html>\n    </t>"}', '<?xml version="1.0"?>
<t t-name="web.minimal_layout">
        &lt;!DOCTYPE html&gt;
        <html style="height: 0;">
            <head>
                <base t-att-href="base_url"/>
                <t t-call-assets="web.report_assets_pdf" t-js="false"/>
                <t t-call-assets="web.report_assets_common" t-js="false"/>
                <t t-call-assets="web.report_assets_pdf" t-css="false"/>
                <meta charset="utf-8"/>
                <script t-if="subst">
                    function subst() {
                        var vars = {};
                        var x = document.location.search.substring(1).split(''&amp;'');
                        for (var i in x) {
                            var z = x[i].split(''='', 2);
                            vars[z[0]] = unescape(z[1]);
                        }
                        var x = [''sitepage'', ''sitepages'', ''section'', ''subsection'', ''subsubsection''];
                        var z = {''sitepage'': ''page'', ''sitepages'': ''topage''};
                        for (var i in x) {
                            var y = document.getElementsByClassName(z[x[i]] || x[i])
                            for (var j=0; j&lt;y.length; ++j)
                                y[j].textContent = vars[x[i]];
                        }

                        var index = vars[''webpage''].split(''.'', 4)[3];
                        var header = document.getElementById(''minimal_layout_report_headers'');
                        if(header){
                            var companyHeader = header.children[index];
                            header.textContent = '''';
                            header.appendChild(companyHeader);
                        }
                        var footer = document.getElementById(''minimal_layout_report_footers'');
                        if(footer){
                            var companyFooter = footer.children[index];
                            footer.textContent = '''';
                            footer.appendChild(companyFooter);
                        }
                    }
                </script>
            </head>
            <body class="container" t-att-data-report-id="report_xml_id" t-att-onload="subst and ''subst()''" style="overflow:hidden" t-att-dir="env[''res.lang'']._lang_get(lang or env.user.lang).direction or ''ltr''">
                <t t-out="body"/>
            </body>
        </html>
    </t>

    ', false, true, '2026-05-10 01:07:07.223274', '2026-05-10 01:07:07.223274', NULL);
INSERT INTO public.ir_ui_view VALUES (198, 16, NULL, 1, 1, 'address_layout', NULL, 'web.address_layout', 'qweb', 'web/views/report_templates.xml', 'primary', '{"en_US": "<t t-name=\"web.address_layout\">\n        <t t-set=\"colclass\" t-value=\"(''col-sm-5'' if report_type == ''html'' else ''col-5'') + '' ms-auto''\"/>\n        <div t-if=\"address\" class=\"address row \" title=\"This block is not always present depending on the printed document.\">\n            <t t-if=\"information_block\">\n                <t t-set=\"colclass\" t-value=\"''col-5 offset-1''\"/>\n                <div name=\"information_block\" class=\"col-6\">\n                    <t t-out=\"information_block or None\">\n                        <div class=\"bg-light border-1 rounded h-100 d-flex flex-column align-items-center justify-content-center p-4 opacity-75 text-muted text-center\">\n                            <strong>Information block</strong>\n                            <div>Usually contains a source address or a complementary address.</div>\n                        </div>\n                    </t>\n                </div>\n            </t>\n\n            <div name=\"address\" t-att-class=\"colclass\">\n                <t t-esc=\"address or None\">\n                    <div class=\"bg-light border-1 rounded h-100 d-flex flex-column align-items-center justify-content-center p-4 opacity-75 text-muted text-center\">\n                        <strong>Address block</strong>\n                        <div>Usually contains the address of the document''s recipient.</div>\n                    </div>\n                </t>\n            </div>\n        </div>\n        <div class=\"oe_structure\" t-else=\"\"/>\n    </t>"}', '<?xml version="1.0"?>
<t t-name="web.address_layout">
        <t t-set="colclass" t-value="(''col-sm-5'' if report_type == ''html'' else ''col-5'') + '' ms-auto''"/>
        <div t-if="address" class="address row " title="This block is not always present depending on the printed document.">
            <t t-if="information_block">
                <t t-set="colclass" t-value="''col-5 offset-1''"/>
                <div name="information_block" class="col-6">
                    <t t-out="information_block or None">
                        <div class="bg-light border-1 rounded h-100 d-flex flex-column align-items-center justify-content-center p-4 opacity-75 text-muted text-center">
                            <strong>Information block</strong>
                            <div>Usually contains a source address or a complementary address.</div>
                        </div>
                    </t>
                </div>
            </t>

            <div name="address" t-att-class="colclass">
                <t t-esc="address or None">
                    <div class="bg-light border-1 rounded h-100 d-flex flex-column align-items-center justify-content-center p-4 opacity-75 text-muted text-center">
                        <strong>Address block</strong>
                        <div>Usually contains the address of the document''s recipient.</div>
                    </div>
                </t>
            </div>
        </div>
        <div class="oe_structure" t-else=""/>
    </t>

    ', false, true, '2026-05-10 01:07:07.223274', '2026-05-10 01:07:07.223274', NULL);
INSERT INTO public.ir_ui_view VALUES (199, 16, NULL, 1, 1, 'external_layout_striped', NULL, 'web.external_layout_striped', 'qweb', 'web/views/report_templates.xml', 'primary', '{"en_US": "<t t-name=\"web.external_layout_striped\">\n        <div t-attf-class=\"o_company_#{company.id}_layout header\" t-att-style=\"report_header_style\">\n            <div class=\"o_background_header\">\n            <div class=\"float-end\">\n                <div class=\"mt0 text-end h3\" t-if=\"company.report_header\" t-field=\"company.report_header\">Company tagline</div>\n            </div>\n            <img t-if=\"company.logo\" t-att-src=\"image_data_uri(company.logo)\" class=\"float-start\" alt=\"Logo\"/>\n            <div class=\"float-start company_address\">\n                <ul class=\"list-unstyled\" name=\"company_address_list\">\n                    <li t-if=\"company.is_company_details_empty\"><span t-field=\"company.partner_id\" t-options=\"{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;], &quot;no_marker&quot;: true}\">\n                        <div class=\"bg-light border-1 rounded h-100 d-flex flex-column align-items-center justify-content-center p-4 w-100 opacity-75 text-muted text-center\">\n                            <strong>Company address block</strong>\n                            <div>Contains the company address.</div>\n                        </div>\n                    </span></li>\n                    <li t-else=\"\">\n                        <span t-field=\"company.company_details\">\n                            <div class=\"bg-light border-1 rounded h-100 d-flex flex-column align-items-center justify-content-center p-4 w-100 opacity-75 text-muted text-center\">\n                                <strong>Company details block</strong>\n                                <div>Contains the company details.</div>\n                            </div>\n                        </span>\n                    </li>\n                    <li t-if=\"not forced_vat\"/>\n                    <li t-else=\"\">\n                        <t t-esc=\"company.country_id.vat_label or ''Tax ID''\">Tax ID</t>:\n                        <span t-esc=\"forced_vat\">US12345671</span>\n                    </li>\n                </ul>\n            </div>\n            <div class=\"clearfix mb8\"/>\n            </div>\n        </div>\n\n        <t t-set=\"layout_background_url\" t-value=\"''data:image/png;base64,%s'' % company.layout_background_image.decode(''utf-8'') if company.layout_background_image and company.layout_background == ''Custom'' else ''/base/static/img/bg_background_template.jpg'' if company.layout_background == ''Geometric'' else ''''\"/>\n        <div t-attf-class=\"o_company_#{company.id}_layout article o_report_layout_striped {{  ''o_report_layout_background'' if company.layout_background in [''Geometric'', ''Custom'']  else  '''' }}\" t-attf-style=\"{{ ''background-image: url(%s);'' % layout_background_url if layout_background_url else '''' }}\" t-att-data-oe-model=\"o and o._name\" t-att-data-oe-id=\"o and o.id\" t-att-data-oe-lang=\"o and o.env.context.get(''lang'')\">\n            <t t-call=\"web.address_layout\"/>\n            <t t-out=\"0\"/>\n        </div>\n\n        <div t-attf-class=\"o_company_#{company.id}_layout footer o_background_footer\">\n            <div class=\"text-center\">\n                <ul class=\"list-inline\">\n                    <div t-field=\"company.report_footer\"/>\n                </ul>\n                <div t-if=\"report_type == ''pdf''\" class=\"text-muted\">\n                    Page:\n                    <span class=\"page\"/>\n                    of\n                    <span class=\"topage\"/>\n                </div>\n                <div t-if=\"report_type == ''pdf'' and display_name_in_footer\" class=\"text-muted\">\n                    <span t-out=\"o.name\">(document name)</span>\n                </div>\n            </div>\n        </div>\n    </t>"}', '<?xml version="1.0"?>
<t t-name="web.external_layout_striped">
        <div t-attf-class="o_company_#{company.id}_layout header" t-att-style="report_header_style">
            <div class="o_background_header">
            <div class="float-end">
                <div class="mt0 text-end h3" t-if="company.report_header" t-field="company.report_header">Company tagline</div>
            </div>
            <img t-if="company.logo" t-att-src="image_data_uri(company.logo)" class="float-start" alt="Logo"/>
            <div class="float-start company_address">
                <ul class="list-unstyled" name="company_address_list">
                    <li t-if="company.is_company_details_empty"><span t-field="company.partner_id" t-options="{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;], &quot;no_marker&quot;: true}">
                        <div class="bg-light border-1 rounded h-100 d-flex flex-column align-items-center justify-content-center p-4 w-100 opacity-75 text-muted text-center">
                            <strong>Company address block</strong>
                            <div>Contains the company address.</div>
                        </div>
                    </span></li>
                    <li t-else="">
                        <span t-field="company.company_details">
                            <div class="bg-light border-1 rounded h-100 d-flex flex-column align-items-center justify-content-center p-4 w-100 opacity-75 text-muted text-center">
                                <strong>Company details block</strong>
                                <div>Contains the company details.</div>
                            </div>
                        </span>
                    </li>
                    <li t-if="not forced_vat"/>
                    <li t-else="">
                        <t t-esc="company.country_id.vat_label or ''Tax ID''">Tax ID</t>:
                        <span t-esc="forced_vat">US12345671</span>
                    </li>
                </ul>
            </div>
            <div class="clearfix mb8"/>
            </div>
        </div>

        <t t-set="layout_background_url" t-value="''data:image/png;base64,%s'' % company.layout_background_image.decode(''utf-8'') if company.layout_background_image and company.layout_background == ''Custom'' else ''/base/static/img/bg_background_template.jpg'' if company.layout_background == ''Geometric'' else ''''"/>
        <div t-attf-class="o_company_#{company.id}_layout article o_report_layout_striped {{  ''o_report_layout_background'' if company.layout_background in [''Geometric'', ''Custom'']  else  '''' }}" t-attf-style="{{ ''background-image: url(%s);'' % layout_background_url if layout_background_url else '''' }}" t-att-data-oe-model="o and o._name" t-att-data-oe-id="o and o.id" t-att-data-oe-lang="o and o.env.context.get(''lang'')">
            <t t-call="web.address_layout"/>
            <t t-out="0"/>
        </div>

        <div t-attf-class="o_company_#{company.id}_layout footer o_background_footer">
            <div class="text-center">
                <ul class="list-inline">
                    <div t-field="company.report_footer"/>
                </ul>
                <div t-if="report_type == ''pdf''" class="text-muted">
                    Page:
                    <span class="page"/>
                    of
                    <span class="topage"/>
                </div>
                <div t-if="report_type == ''pdf'' and display_name_in_footer" class="text-muted">
                    <span t-out="o.name">(document name)</span>
                </div>
            </div>
        </div>
    </t>

    ', false, true, '2026-05-10 01:07:07.223274', '2026-05-10 01:07:07.223274', NULL);
INSERT INTO public.ir_ui_view VALUES (200, 16, NULL, 1, 1, 'external_layout_boxed', NULL, 'web.external_layout_boxed', 'qweb', 'web/views/report_templates.xml', 'primary', '{"en_US": "<t t-name=\"web.external_layout_boxed\">\n        <div t-attf-class=\"header o_company_#{company.id}_layout\" t-att-style=\"report_header_style\">\n            <div class=\"o_boxed_header\">\n            <div class=\"row mb8\">\n                <div class=\"col-6\">\n                    <img t-if=\"company.logo\" t-att-src=\"image_data_uri(company.logo)\" alt=\"Logo\"/>\n                </div>\n                <div class=\"col-6 text-end mb4\">\n                    <t t-if=\"company.report_header and company.report_header.strip() != ''&lt;p&gt;&lt;br&gt;&lt;/p&gt;''\">\n                        <div class=\"mt0 h4\" t-field=\"company.report_header\"/>\n                    </t>\n                    <div name=\"company_address\" class=\"float-end mb4\">\n                        <ul class=\"list-unstyled\" name=\"company_address_list\">\n                            <li t-if=\"company.is_company_details_empty\"><span t-field=\"company.partner_id\" t-options=\"{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;], &quot;no_marker&quot;: true}\">\n                                <div class=\"bg-light border-1 rounded h-100 d-flex flex-column align-items-center justify-content-center p-4 w-100 opacity-75 text-muted text-center\">\n                                    <strong>Company address block</strong>\n                                    <div>Contains the company address.</div>\n                                </div>\n                            </span></li>\n                            <li t-else=\"\">\n                                <span t-field=\"company.company_details\">\n                                    <div class=\"bg-light border-1 rounded h-100 d-flex flex-column align-items-center justify-content-center p-4 w-100 opacity-75 text-muted text-center\">\n                                        <strong>Company details block</strong>\n                                        <div>Contains the company details.</div>\n                                    </div>\n                                </span>\n                            </li>\n                            <li t-if=\"not forced_vat\"/>\n                            <li t-else=\"\">\n                                <t t-esc=\"company.country_id.vat_label or ''Tax ID''\">Tax ID</t>:\n                                <span t-esc=\"forced_vat\">US12345671</span>\n                            </li>\n                        </ul>\n                    </div>\n                </div>\n            </div>\n            </div>\n        </div>\n\n        <t t-set=\"layout_background_url\" t-value=\"''data:image/png;base64,%s'' % company.layout_background_image.decode(''utf-8'') if company.layout_background_image and company.layout_background == ''Custom'' else ''/base/static/img/bg_background_template.jpg'' if company.layout_background == ''Geometric'' else ''''\"/>\n        <div t-attf-class=\"article o_report_layout_boxed o_company_#{company.id}_layout {{  ''o_report_layout_background'' if company.layout_background in [''Geometric'', ''Custom'']  else  '''' }}\" t-attf-style=\"{{ ''background-image: url(%s);'' % layout_background_url if layout_background_url else '''' }}\" t-att-data-oe-model=\"o and o._name\" t-att-data-oe-id=\"o and o.id\" t-att-data-oe-lang=\"o and o.env.context.get(''lang'')\">\n            <div class=\"pt-5\">\n                <!-- This div ensures that the address is not cropped by the header. -->\n                <t t-call=\"web.address_layout\"/>\n            </div>\n            <t t-out=\"0\"/>\n        </div>\n\n        <div t-attf-class=\"footer o_boxed_footer o_company_#{company.id}_layout\">\n            <div class=\"text-center\">\n                <div t-field=\"company.report_footer\">Company Report Footer</div>\n                <div t-if=\"report_type == ''pdf''\">\n                    Page: <span class=\"page\"/> / <span class=\"topage\"/>\n                </div>\n                <div t-if=\"report_type == ''pdf'' and display_name_in_footer\" class=\"text-muted\">\n                    <span t-out=\"o.name\">(document name)</span>\n                </div>\n            </div>\n        </div>\n    </t>"}', '<?xml version="1.0"?>
<t t-name="web.external_layout_boxed">
        <div t-attf-class="header o_company_#{company.id}_layout" t-att-style="report_header_style">
            <div class="o_boxed_header">
            <div class="row mb8">
                <div class="col-6">
                    <img t-if="company.logo" t-att-src="image_data_uri(company.logo)" alt="Logo"/>
                </div>
                <div class="col-6 text-end mb4">
                    <t t-if="company.report_header and company.report_header.strip() != ''&lt;p&gt;&lt;br&gt;&lt;/p&gt;''">
                        <div class="mt0 h4" t-field="company.report_header"/>
                    </t>
                    <div name="company_address" class="float-end mb4">
                        <ul class="list-unstyled" name="company_address_list">
                            <li t-if="company.is_company_details_empty"><span t-field="company.partner_id" t-options="{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;], &quot;no_marker&quot;: true}">
                                <div class="bg-light border-1 rounded h-100 d-flex flex-column align-items-center justify-content-center p-4 w-100 opacity-75 text-muted text-center">
                                    <strong>Company address block</strong>
                                    <div>Contains the company address.</div>
                                </div>
                            </span></li>
                            <li t-else="">
                                <span t-field="company.company_details">
                                    <div class="bg-light border-1 rounded h-100 d-flex flex-column align-items-center justify-content-center p-4 w-100 opacity-75 text-muted text-center">
                                        <strong>Company details block</strong>
                                        <div>Contains the company details.</div>
                                    </div>
                                </span>
                            </li>
                            <li t-if="not forced_vat"/>
                            <li t-else="">
                                <t t-esc="company.country_id.vat_label or ''Tax ID''">Tax ID</t>:
                                <span t-esc="forced_vat">US12345671</span>
                            </li>
                        </ul>
                    </div>
                </div>
            </div>
            </div>
        </div>

        <t t-set="layout_background_url" t-value="''data:image/png;base64,%s'' % company.layout_background_image.decode(''utf-8'') if company.layout_background_image and company.layout_background == ''Custom'' else ''/base/static/img/bg_background_template.jpg'' if company.layout_background == ''Geometric'' else ''''"/>
        <div t-attf-class="article o_report_layout_boxed o_company_#{company.id}_layout {{  ''o_report_layout_background'' if company.layout_background in [''Geometric'', ''Custom'']  else  '''' }}" t-attf-style="{{ ''background-image: url(%s);'' % layout_background_url if layout_background_url else '''' }}" t-att-data-oe-model="o and o._name" t-att-data-oe-id="o and o.id" t-att-data-oe-lang="o and o.env.context.get(''lang'')">
            <div class="pt-5">
                <!-- This div ensures that the address is not cropped by the header. -->
                <t t-call="web.address_layout"/>
            </div>
            <t t-out="0"/>
        </div>

        <div t-attf-class="footer o_boxed_footer o_company_#{company.id}_layout">
            <div class="text-center">
                <div t-field="company.report_footer">Company Report Footer</div>
                <div t-if="report_type == ''pdf''">
                    Page: <span class="page"/> / <span class="topage"/>
                </div>
                <div t-if="report_type == ''pdf'' and display_name_in_footer" class="text-muted">
                    <span t-out="o.name">(document name)</span>
                </div>
            </div>
        </div>
    </t>

    ', false, true, '2026-05-10 01:07:07.223274', '2026-05-10 01:07:07.223274', NULL);
INSERT INTO public.ir_ui_view VALUES (201, 16, NULL, 1, 1, 'external_layout_bold', NULL, 'web.external_layout_bold', 'qweb', 'web/views/report_templates.xml', 'primary', '{"en_US": "<t t-name=\"web.external_layout_bold\">\n        <div t-attf-class=\"header o_company_#{company.id}_layout\" t-att-style=\"report_header_style\">\n            <div class=\"o_clean_header\">\n                <div class=\"row\">\n                    <div class=\"col-6\">\n                        <img t-if=\"company.logo\" t-att-src=\"image_data_uri(company.logo)\" alt=\"Logo\"/>\n                    </div>\n                    <div class=\"col-5 offset-1\" name=\"company_address\">\n                        <ul class=\"list-unstyled\" name=\"company_address_list\">\n                            <li t-if=\"company.is_company_details_empty\"><span t-field=\"company.partner_id\" t-options=\"{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;], &quot;no_marker&quot;: true}\">\n                                <div class=\"bg-light border-1 rounded h-100 d-flex flex-column align-items-center justify-content-center p-4 w-100 opacity-75 text-muted text-center\">\n                                    <strong>Company address block</strong>\n                                    <div>Contains the company address.</div>\n                                </div>\n                            </span></li>\n                            <li t-else=\"\">\n                                <span t-field=\"company.company_details\">\n                                    <div class=\"bg-light border-1 rounded h-100 d-flex flex-column align-items-center justify-content-center p-4 w-100 opacity-75 text-muted text-center\">\n                                        <strong>Company details block</strong>\n                                        <div>Contains the company details.</div>\n                                    </div>\n                                </span>\n                            </li>\n                            <li t-if=\"not forced_vat\"/>\n                            <li t-else=\"\">\n                                <t t-esc=\"company.country_id.vat_label or ''Tax ID''\">Tax ID</t>:\n                                <span t-esc=\"forced_vat\">US12345671</span>\n                            </li>\n                        </ul>\n                    </div>\n                </div>\n            </div>\n        </div>\n\n        <t t-set=\"layout_background_url\" t-value=\"''data:image/png;base64,%s'' % company.layout_background_image.decode(''utf-8'') if company.layout_background_image and company.layout_background == ''Custom'' else ''/base/static/img/bg_background_template.jpg'' if company.layout_background == ''Geometric'' else ''''\"/>\n        <div t-attf-class=\"article o_report_layout_bold o_company_#{company.id}_layout {{  ''o_report_layout_background'' if company.layout_background in [''Geometric'', ''Custom'']  else  '''' }}\" t-attf-style=\"{{ ''background-image: url(%s);'' % layout_background_url if layout_background_url else '''' }}\" t-att-data-oe-model=\"o and o._name\" t-att-data-oe-id=\"o and o.id\" t-att-data-oe-lang=\"o and o.env.context.get(''lang'')\">\n            <t t-call=\"web.address_layout\"/>\n            <t t-out=\"0\"/>\n        </div>\n\n        <div t-attf-class=\"footer o_clean_footer o_company_#{company.id}_layout\">\n            <div class=\"row\">\n                <div class=\"col-4\">\n                    <span t-field=\"company.report_footer\"/>\n                </div>\n                <div class=\"col-4\">\n                    <span t-if=\"company.is_company_details_empty\" t-field=\"company.partner_id\" t-options=\"{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;], &quot;no_marker&quot;: true}\"/>\n                    <span t-else=\"\" t-field=\"company.company_details\"/>\n                </div>\n                <div class=\"col-3\">\n                    <div class=\"mt0 mb0 h5\" t-if=\"company.report_header\" t-field=\"company.report_header\">Company tagline</div>\n                </div>\n                <div class=\"col-1\">\n                    <ul t-if=\"report_type == ''pdf''\" class=\"list-inline pagenumber float-end text-center\">\n                        <li class=\"list-inline-item\"><strong><span class=\"page\"/></strong></li>\n                    </ul>\n                </div>\n            </div>\n        </div>\n    </t>"}', '<?xml version="1.0"?>
<t t-name="web.external_layout_bold">
        <div t-attf-class="header o_company_#{company.id}_layout" t-att-style="report_header_style">
            <div class="o_clean_header">
                <div class="row">
                    <div class="col-6">
                        <img t-if="company.logo" t-att-src="image_data_uri(company.logo)" alt="Logo"/>
                    </div>
                    <div class="col-5 offset-1" name="company_address">
                        <ul class="list-unstyled" name="company_address_list">
                            <li t-if="company.is_company_details_empty"><span t-field="company.partner_id" t-options="{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;], &quot;no_marker&quot;: true}">
                                <div class="bg-light border-1 rounded h-100 d-flex flex-column align-items-center justify-content-center p-4 w-100 opacity-75 text-muted text-center">
                                    <strong>Company address block</strong>
                                    <div>Contains the company address.</div>
                                </div>
                            </span></li>
                            <li t-else="">
                                <span t-field="company.company_details">
                                    <div class="bg-light border-1 rounded h-100 d-flex flex-column align-items-center justify-content-center p-4 w-100 opacity-75 text-muted text-center">
                                        <strong>Company details block</strong>
                                        <div>Contains the company details.</div>
                                    </div>
                                </span>
                            </li>
                            <li t-if="not forced_vat"/>
                            <li t-else="">
                                <t t-esc="company.country_id.vat_label or ''Tax ID''">Tax ID</t>:
                                <span t-esc="forced_vat">US12345671</span>
                            </li>
                        </ul>
                    </div>
                </div>
            </div>
        </div>

        <t t-set="layout_background_url" t-value="''data:image/png;base64,%s'' % company.layout_background_image.decode(''utf-8'') if company.layout_background_image and company.layout_background == ''Custom'' else ''/base/static/img/bg_background_template.jpg'' if company.layout_background == ''Geometric'' else ''''"/>
        <div t-attf-class="article o_report_layout_bold o_company_#{company.id}_layout {{  ''o_report_layout_background'' if company.layout_background in [''Geometric'', ''Custom'']  else  '''' }}" t-attf-style="{{ ''background-image: url(%s);'' % layout_background_url if layout_background_url else '''' }}" t-att-data-oe-model="o and o._name" t-att-data-oe-id="o and o.id" t-att-data-oe-lang="o and o.env.context.get(''lang'')">
            <t t-call="web.address_layout"/>
            <t t-out="0"/>
        </div>

        <div t-attf-class="footer o_clean_footer o_company_#{company.id}_layout">
            <div class="row">
                <div class="col-4">
                    <span t-field="company.report_footer"/>
                </div>
                <div class="col-4">
                    <span t-if="company.is_company_details_empty" t-field="company.partner_id" t-options="{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;], &quot;no_marker&quot;: true}"/>
                    <span t-else="" t-field="company.company_details"/>
                </div>
                <div class="col-3">
                    <div class="mt0 mb0 h5" t-if="company.report_header" t-field="company.report_header">Company tagline</div>
                </div>
                <div class="col-1">
                    <ul t-if="report_type == ''pdf''" class="list-inline pagenumber float-end text-center">
                        <li class="list-inline-item"><strong><span class="page"/></strong></li>
                    </ul>
                </div>
            </div>
        </div>
    </t>

    ', false, true, '2026-05-10 01:07:07.223274', '2026-05-10 01:07:07.223274', NULL);
INSERT INTO public.ir_ui_view VALUES (202, 16, NULL, 1, 1, 'external_layout_standard', NULL, 'web.external_layout_standard', 'qweb', 'web/views/report_templates.xml', 'primary', '{"en_US": "<t t-name=\"web.external_layout_standard\">\n        <div t-attf-class=\"header o_company_#{company.id}_layout\" t-att-style=\"report_header_style\">\n            <div class=\"row\">\n                <div class=\"col-3 mb4\">\n                    <img t-if=\"company.logo\" t-att-src=\"image_data_uri(company.logo)\" style=\"max-height: 45px;\" alt=\"Logo\"/>\n                </div>\n                <div class=\"col-9 text-end\" style=\"margin-top:22px;\" t-if=\"company.report_header\" t-field=\"company.report_header\" name=\"moto\">Company tagline</div>\n            </div>\n            <div t-if=\"company.logo or company.report_header\" class=\"row zero_min_height\">\n                <div class=\"col-12\">\n                    <div style=\"border-bottom: 1px solid black;\"/>\n                </div>\n            </div>\n            <div class=\"row\">\n                <div class=\"col-6\" name=\"company_address\">\n                    <ul class=\"list-unstyled\" name=\"company_address_list\">\n                        <li t-if=\"company.is_company_details_empty\"><span t-field=\"company.partner_id\" t-options=\"{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;], &quot;no_marker&quot;: true}\">\n                            <div class=\"bg-light border-1 rounded h-100 d-flex flex-column align-items-center justify-content-center p-4 w-100 opacity-75 text-muted text-center\">\n                                <strong>Company address block</strong>\n                                <div>Contains the company address.</div>\n                            </div>\n                        </span></li>\n                        <li t-else=\"\">\n                            <span t-field=\"company.company_details\">\n                                <div class=\"bg-light border-1 rounded h-100 d-flex flex-column align-items-center justify-content-center p-4 w-100 opacity-75 text-muted text-center\">\n                                    <strong>Company details block</strong>\n                                    <div>Contains the company details.</div>\n                                </div>\n                            </span>\n                        </li>\n                        <li t-if=\"not forced_vat\"/>\n                        <li t-else=\"\">\n                            <t t-esc=\"company.country_id.vat_label or ''Tax ID''\">Tax ID</t>:\n                            <span t-esc=\"forced_vat\">US12345671</span>\n                        </li>\n                    </ul>\n                </div>\n            </div>\n        </div>\n\n        <t t-set=\"layout_background_url\" t-value=\"''data:image/png;base64,%s'' % company.layout_background_image.decode(''utf-8'') if company.layout_background_image and company.layout_background == ''Custom'' else ''/base/static/img/bg_background_template.jpg'' if company.layout_background == ''Geometric'' else ''''\"/>\n        <div t-attf-class=\"article o_report_layout_standard o_company_#{company.id}_layout {{  ''o_report_layout_background'' if company.layout_background in [''Geometric'', ''Custom'']  else  '''' }}\" t-attf-style=\"{{ ''background-image: url(%s);'' % layout_background_url if layout_background_url else '''' }}\" t-att-data-oe-model=\"o and o._name\" t-att-data-oe-id=\"o and o.id\" t-att-data-oe-lang=\"o and o.env.context.get(''lang'')\">\n            <div class=\"pt-5\">\n                <!-- This div ensures that the address is not cropped by the header. -->\n                <t t-call=\"web.address_layout\"/>\n            </div>\n            <t t-out=\"0\"/>\n        </div>\n\n        <div t-attf-class=\"footer o_standard_footer o_company_#{company.id}_layout\">\n            <div class=\"text-center\" style=\"border-top: 1px solid black;\">\n                <ul class=\"list-inline mb4\">\n                    <div t-field=\"company.report_footer\"/>\n                </ul>\n\n                <div t-if=\"report_type == ''pdf''\" class=\"text-muted\">\n                    Page: <span class=\"page\"/> / <span class=\"topage\"/>\n                </div>\n                <div t-if=\"report_type == ''pdf'' and display_name_in_footer\" class=\"text-muted\">\n                    <span t-out=\"o.name\">(document name)</span>\n                </div>\n            </div>\n        </div>\n    </t>"}', '<?xml version="1.0"?>
<t t-name="web.external_layout_standard">
        <div t-attf-class="header o_company_#{company.id}_layout" t-att-style="report_header_style">
            <div class="row">
                <div class="col-3 mb4">
                    <img t-if="company.logo" t-att-src="image_data_uri(company.logo)" style="max-height: 45px;" alt="Logo"/>
                </div>
                <div class="col-9 text-end" style="margin-top:22px;" t-if="company.report_header" t-field="company.report_header" name="moto">Company tagline</div>
            </div>
            <div t-if="company.logo or company.report_header" class="row zero_min_height">
                <div class="col-12">
                    <div style="border-bottom: 1px solid black;"/>
                </div>
            </div>
            <div class="row">
                <div class="col-6" name="company_address">
                    <ul class="list-unstyled" name="company_address_list">
                        <li t-if="company.is_company_details_empty"><span t-field="company.partner_id" t-options="{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;], &quot;no_marker&quot;: true}">
                            <div class="bg-light border-1 rounded h-100 d-flex flex-column align-items-center justify-content-center p-4 w-100 opacity-75 text-muted text-center">
                                <strong>Company address block</strong>
                                <div>Contains the company address.</div>
                            </div>
                        </span></li>
                        <li t-else="">
                            <span t-field="company.company_details">
                                <div class="bg-light border-1 rounded h-100 d-flex flex-column align-items-center justify-content-center p-4 w-100 opacity-75 text-muted text-center">
                                    <strong>Company details block</strong>
                                    <div>Contains the company details.</div>
                                </div>
                            </span>
                        </li>
                        <li t-if="not forced_vat"/>
                        <li t-else="">
                            <t t-esc="company.country_id.vat_label or ''Tax ID''">Tax ID</t>:
                            <span t-esc="forced_vat">US12345671</span>
                        </li>
                    </ul>
                </div>
            </div>
        </div>

        <t t-set="layout_background_url" t-value="''data:image/png;base64,%s'' % company.layout_background_image.decode(''utf-8'') if company.layout_background_image and company.layout_background == ''Custom'' else ''/base/static/img/bg_background_template.jpg'' if company.layout_background == ''Geometric'' else ''''"/>
        <div t-attf-class="article o_report_layout_standard o_company_#{company.id}_layout {{  ''o_report_layout_background'' if company.layout_background in [''Geometric'', ''Custom'']  else  '''' }}" t-attf-style="{{ ''background-image: url(%s);'' % layout_background_url if layout_background_url else '''' }}" t-att-data-oe-model="o and o._name" t-att-data-oe-id="o and o.id" t-att-data-oe-lang="o and o.env.context.get(''lang'')">
            <div class="pt-5">
                <!-- This div ensures that the address is not cropped by the header. -->
                <t t-call="web.address_layout"/>
            </div>
            <t t-out="0"/>
        </div>

        <div t-attf-class="footer o_standard_footer o_company_#{company.id}_layout">
            <div class="text-center" style="border-top: 1px solid black;">
                <ul class="list-inline mb4">
                    <div t-field="company.report_footer"/>
                </ul>

                <div t-if="report_type == ''pdf''" class="text-muted">
                    Page: <span class="page"/> / <span class="topage"/>
                </div>
                <div t-if="report_type == ''pdf'' and display_name_in_footer" class="text-muted">
                    <span t-out="o.name">(document name)</span>
                </div>
            </div>
        </div>
    </t>

    ', false, true, '2026-05-10 01:07:07.223274', '2026-05-10 01:07:07.223274', NULL);
INSERT INTO public.ir_ui_view VALUES (203, 16, NULL, 1, 1, 'external_layout', NULL, 'web.external_layout', 'qweb', 'web/views/report_templates.xml', 'primary', '{"en_US": "<t t-name=\"web.external_layout\">\n        <t t-if=\"not o\" t-set=\"o\" t-value=\"doc\"/>\n\n        <t t-if=\"not company\">\n            <!-- Multicompany -->\n            <t t-if=\"company_id\">\n                <t t-set=\"company\" t-value=\"company_id\"/>\n            </t>\n            <t t-elif=\"o and ''company_id'' in o and o.company_id.sudo()\">\n                <t t-set=\"company\" t-value=\"o.company_id.sudo()\"/>\n            </t>\n            <t t-else=\"else\">\n                <t t-set=\"company\" t-value=\"res_company\"/>\n            </t>\n        </t>\n\n        <t t-if=\"company.external_report_layout_id\" t-call=\"{{company.external_report_layout_id.sudo().key}}\"><t t-out=\"0\"/></t>\n        <t t-else=\"else\" t-call=\"web.external_layout_standard\"><t t-out=\"0\"/></t>\n\n    </t>"}', '<?xml version="1.0"?>
<t t-name="web.external_layout">
        <t t-if="not o" t-set="o" t-value="doc"/>

        <t t-if="not company">
            <!-- Multicompany -->
            <t t-if="company_id">
                <t t-set="company" t-value="company_id"/>
            </t>
            <t t-elif="o and ''company_id'' in o and o.company_id.sudo()">
                <t t-set="company" t-value="o.company_id.sudo()"/>
            </t>
            <t t-else="else">
                <t t-set="company" t-value="res_company"/>
            </t>
        </t>

        <t t-if="company.external_report_layout_id" t-call="{{company.external_report_layout_id.sudo().key}}"><t t-out="0"/></t>
        <t t-else="else" t-call="web.external_layout_standard"><t t-out="0"/></t>

    </t>

    ', false, true, '2026-05-10 01:07:07.223274', '2026-05-10 01:07:07.223274', NULL);
INSERT INTO public.ir_ui_view VALUES (204, 16, NULL, 1, 1, 'internal_layout', NULL, 'web.internal_layout', 'qweb', 'web/views/report_templates.xml', 'primary', '{"en_US": "<t t-name=\"web.internal_layout\">\n        <t t-if=\"not o\" t-set=\"o\" t-value=\"doc\"/>\n\n        <t t-if=\"not company\">\n            <!-- Multicompany -->\n            <t t-if=\"company_id\">\n                <t t-set=\"company\" t-value=\"company_id\"/>\n            </t>\n            <t t-elif=\"o and ''company_id'' in o and o.company_id.sudo()\">\n                <t t-set=\"company\" t-value=\"o.company_id.sudo()\"/>\n            </t>\n            <t t-else=\"else\">\n                <t t-set=\"company\" t-value=\"res_company\"/>\n            </t>\n        </t>\n\n        <div class=\"header\">\n            <div class=\"row\">\n                <div class=\"col-3\">\n                    <span t-esc=\"context_timestamp(datetime.datetime.now()).strftime(''%Y-%m-%d %H:%M'')\"/>\n                </div>\n                <div class=\"col-2 offset-2 text-center\">\n                    <span t-esc=\"company.name\"/>\n                </div>\n                <div class=\"col-2 offset-3 text-end\">\n                    <ul class=\"list-inline\">\n                        <li class=\"list-inline-item\"><span class=\"page\"/></li>\n                        <li class=\"list-inline-item\">/</li>\n                        <li class=\"list-inline-item\"><span class=\"topage\"/></li>\n                    </ul>\n                </div>\n            </div>\n        </div>\n        <div class=\"article\" t-att-data-oe-model=\"o and o._name\" t-att-data-oe-id=\"o and o.id\" t-att-data-oe-lang=\"o and o.env.context.get(''lang'')\">\n          <t t-out=\"0\"/>\n        </div>\n    </t>"}', '<?xml version="1.0"?>
<t t-name="web.internal_layout">
        <t t-if="not o" t-set="o" t-value="doc"/>

        <t t-if="not company">
            <!-- Multicompany -->
            <t t-if="company_id">
                <t t-set="company" t-value="company_id"/>
            </t>
            <t t-elif="o and ''company_id'' in o and o.company_id.sudo()">
                <t t-set="company" t-value="o.company_id.sudo()"/>
            </t>
            <t t-else="else">
                <t t-set="company" t-value="res_company"/>
            </t>
        </t>

        <div class="header">
            <div class="row">
                <div class="col-3">
                    <span t-esc="context_timestamp(datetime.datetime.now()).strftime(''%Y-%m-%d %H:%M'')"/>
                </div>
                <div class="col-2 offset-2 text-center">
                    <span t-esc="company.name"/>
                </div>
                <div class="col-2 offset-3 text-end">
                    <ul class="list-inline">
                        <li class="list-inline-item"><span class="page"/></li>
                        <li class="list-inline-item">/</li>
                        <li class="list-inline-item"><span class="topage"/></li>
                    </ul>
                </div>
            </div>
        </div>
        <div class="article" t-att-data-oe-model="o and o._name" t-att-data-oe-id="o and o.id" t-att-data-oe-lang="o and o.env.context.get(''lang'')">
          <t t-out="0"/>
        </div>
    </t>

    ', false, true, '2026-05-10 01:07:07.223274', '2026-05-10 01:07:07.223274', NULL);
INSERT INTO public.ir_ui_view VALUES (205, 16, NULL, 1, 1, 'basic_layout', NULL, 'web.basic_layout', 'qweb', 'web/views/report_templates.xml', 'primary', '{"en_US": "<t t-name=\"web.basic_layout\">\n        <t t-call=\"web.html_container\">\n            <t t-if=\"not o\" t-set=\"o\" t-value=\"doc\"/>\n            <div class=\"article\" t-att-data-oe-model=\"o and o._name\" t-att-data-oe-id=\"o and o.id\" t-att-data-oe-lang=\"o and o.env.context.get(''lang'')\">\n                <t t-out=\"0\"/>\n            </div>\n        </t>\n    </t>"}', '<?xml version="1.0"?>
<t t-name="web.basic_layout">
