            <t t-if="not o" t-set="o" t-value="doc"/>
            <div class="article" t-att-data-oe-model="o and o._name" t-att-data-oe-id="o and o.id" t-att-data-oe-lang="o and o.env.context.get(''lang'')">
                <t t-out="0"/>
            </div>
        </t>
    </t>

    ', false, true, '2026-05-10 01:07:07.223274', '2026-05-10 01:07:07.223274', NULL);
INSERT INTO public.ir_ui_view VALUES (208, 16, NULL, 1, 1, 'preview_layout_report', NULL, 'web.preview_layout_report', 'qweb', 'web/views/report_templates.xml', 'primary', '{"en_US": "<t t-name=\"web.preview_layout_report\">\n        <t t-set=\"company\" t-value=\"env.company\"/>\n        <t t-call=\"web.html_container\">\n            <t t-set=\"o\" t-value=\"res_company\"/>\n            <t t-call=\"web.report_invoice_wizard_preview\"/>\n        </t>\n    </t>"}', '<?xml version="1.0"?>
<t t-name="web.preview_layout_report">
        <t t-set="company" t-value="env.company"/>
        <t t-call="web.html_container">
            <t t-set="o" t-value="res_company"/>
            <t t-call="web.report_invoice_wizard_preview"/>
        </t>
    </t>

    ', false, true, '2026-05-10 01:07:07.223274', '2026-05-10 01:07:07.223274', NULL);
INSERT INTO public.ir_ui_view VALUES (210, 16, NULL, 1, 1, 'Document Layout', 'base.document.layout', NULL, 'form', 'web/views/base_document_layout_views.xml', 'primary', '{"en_US": "<form class=\"o_document_layout\">\n                    <group>\n                        <group class=\"o_document_layout_company\">\n                            <field name=\"company_id\" invisible=\"1\"/>\n                            <field name=\"external_report_layout_id\" invisible=\"1\"/>\n                            <field name=\"logo_primary_color\" invisible=\"1\"/>\n                            <field name=\"logo_secondary_color\" invisible=\"1\"/>\n                            <field name=\"report_layout_id\" widget=\"radio\" string=\"Layout\" required=\"1\"/>\n                            <field name=\"font\" widget=\"selection\" required=\"1\"/>\n                            <field name=\"logo\" widget=\"image\" options=\"{''size'': [0, 50]}\"/>\n                            <label for=\"primary_color\" string=\"Colors\"/>\n                            <div class=\"o_document_layout_colors d-flex align-items-end mb-4\">\n                                <field name=\"primary_color\" widget=\"color\" class=\"w-auto m-0 me-1\"/>\n                                <field name=\"secondary_color\" widget=\"color\" class=\"w-auto m-0\"/>\n                                <a class=\"o_custom_colors btn btn-secondary btn-sm position-relative ms-2\" role=\"button\" title=\"Reset to logo colors\" invisible=\"not custom_colors\">\n                                    <i class=\"fa fa-repeat\"/> Reset\n                                    <field name=\"custom_colors\" class=\"position-absolute top-0 start-0 w-100 h-100 opacity-0\" nolabel=\"1\"/>\n                                </a>\n                            </div>\n                            <field name=\"layout_background\" widget=\"selection\" required=\"1\"/>\n                            <field name=\"layout_background_image\" options=\"{''accepted_file_extensions'': ''image/*''}\" invisible=\"layout_background != ''Custom''\" required=\"layout_background == ''Custom''\">Upload your file</field>\n                            <field name=\"report_header\" placeholder=\"e.g. Global Business Solutions\" options=\"{''resizable'': false}\"/>\n                            <field name=\"company_details\" string=\"Company Details\" options=\"{''resizable'': false}\"/>\n                            <field name=\"report_footer\" string=\"Footer\" options=\"{''resizable'': false}\"/>\n                            <field name=\"paperformat_id\" widget=\"selection\" required=\"1\" domain=\"[(''report_ids'', ''='', False)]\"/>\n                        </group>\n                        <div>\n                            <field name=\"preview\" widget=\"iframe_wrapper\"/>\n                            <button name=\"web.action_report_layout_preview\" string=\"Download PDF Preview\" type=\"action\" class=\"oe_link\" icon=\"oi-arrow-right\"/>\n                        </div>\n                    </group>\n                    <footer>\n                        <button string=\"Save\" class=\"btn-primary\" type=\"object\" name=\"document_layout_save\" data-hotkey=\"q\"/>\n                        <button special=\"cancel\" data-hotkey=\"x\" string=\"Cancel\"/>\n                    </footer>\n                </form>"}', '<?xml version="1.0"?>
<form class="o_document_layout">
                    <group>
                        <group class="o_document_layout_company">
                            <field name="company_id" invisible="1"/>
                            <field name="external_report_layout_id" invisible="1"/>
                            <field name="logo_primary_color" invisible="1"/>
                            <field name="logo_secondary_color" invisible="1"/>
                            <field name="report_layout_id" widget="radio" string="Layout" required="1"/>
                            <field name="font" widget="selection" required="1"/>
                            <field name="logo" widget="image" options="{''size'': [0, 50]}"/>
                            <label for="primary_color" string="Colors"/>
                            <div class="o_document_layout_colors d-flex align-items-end mb-4">
                                <field name="primary_color" widget="color" class="w-auto m-0 me-1"/>
                                <field name="secondary_color" widget="color" class="w-auto m-0"/>
                                <a class="o_custom_colors btn btn-secondary btn-sm position-relative ms-2" role="button" title="Reset to logo colors" invisible="not custom_colors">
                                    <i class="fa fa-repeat"/> Reset
                                    <field name="custom_colors" class="position-absolute top-0 start-0 w-100 h-100 opacity-0" nolabel="1"/>
                                </a>
                            </div>
                            <field name="layout_background" widget="selection" required="1"/>
                            <field name="layout_background_image" options="{''accepted_file_extensions'': ''image/*''}" invisible="layout_background != ''Custom''" required="layout_background == ''Custom''">Upload your file</field>
                            <field name="report_header" placeholder="e.g. Global Business Solutions" options="{''resizable'': false}"/>
                            <field name="company_details" string="Company Details" options="{''resizable'': false}"/>
                            <field name="report_footer" string="Footer" options="{''resizable'': false}"/>
                            <field name="paperformat_id" widget="selection" required="1" domain="[(''report_ids'', ''='', False)]"/>
                        </group>
                        <div>
                            <field name="preview" widget="iframe_wrapper"/>
                            <button name="web.action_report_layout_preview" string="Download PDF Preview" type="action" class="oe_link" icon="oi-arrow-right"/>
                        </div>
                    </group>
                    <footer>
                        <button string="Save" class="btn-primary" type="object" name="document_layout_save" data-hotkey="q"/>
                        <button special="cancel" data-hotkey="x" string="Cancel"/>
                    </footer>
                </form>
            ', false, true, '2026-05-10 01:07:07.223274', '2026-05-10 01:07:07.223274', NULL);
INSERT INTO public.ir_ui_view VALUES (211, 16, NULL, 1, 1, 'view_speedscope_index', NULL, 'web.view_speedscope_index', 'qweb', 'web/views/speedscope_template.xml', 'primary', '{"en_US": "<t t-name=\"web.view_speedscope_index\">\n        &lt;!DOCTYPE html&gt;\n        <html lang=\"en\">\n            <head>\n                <meta charset=\"UTF-8\"/>\n                <title>Speedscope for odoo</title>\n                <script t-if=\"profile\">window.location.hash=\"#profileURL=<t t-esc=\"url_root\"/>web/content/ir.profile/<t t-esc=\"profile.id\"/>/speedscope\"</script>\n                <link href=\"https://fonts.googleapis.com/css?family=Source+Code+Pro\" rel=\"stylesheet\"/>\n                <link rel=\"stylesheet\" t-attf-href=\"{{cdn}}reset.8c46b7a1.css\" crossorigin=\"anonymous\" integrity=\"sha256-mrA/937EwtEDE+8XZ/62tNz2T/BnCLth8QmWsWKpvD8=\"/>\n            </head>\n            <body>\n                <script t-attf-src=\"{{cdn}}speedscope.026f36b0.js\" crossorigin=\"anonymous\" integrity=\"sha256-CvDqAOMjq0Sv/D59O5JSbzzXoClZ3rptt6ts8D/6CWw=\"/>\n            </body>\n        </html>\n    </t>"}', '<?xml version="1.0"?>
<t t-name="web.view_speedscope_index">
        &lt;!DOCTYPE html&gt;
        <html lang="en">
            <head>
                <meta charset="UTF-8"/>
                <title>Speedscope for odoo</title>
                <script t-if="profile">window.location.hash="#profileURL=<t t-esc="url_root"/>web/content/ir.profile/<t t-esc="profile.id"/>/speedscope"</script>
                <link href="https://fonts.googleapis.com/css?family=Source+Code+Pro" rel="stylesheet"/>
                <link rel="stylesheet" t-attf-href="{{cdn}}reset.8c46b7a1.css" crossorigin="anonymous" integrity="sha256-mrA/937EwtEDE+8XZ/62tNz2T/BnCLth8QmWsWKpvD8="/>
            </head>
            <body>
                <script t-attf-src="{{cdn}}speedscope.026f36b0.js" crossorigin="anonymous" integrity="sha256-CvDqAOMjq0Sv/D59O5JSbzzXoClZ3rptt6ts8D/6CWw="/>
            </body>
        </html>
    </t>
', false, true, '2026-05-10 01:07:07.223274', '2026-05-10 01:07:07.223274', NULL);
INSERT INTO public.ir_ui_view VALUES (212, 16, 180, 1, 1, 'Neutralize Banner', NULL, 'web.neutralize_banner', 'qweb', 'web/views/neutralize_views.xml', 'extension', '{"en_US": "<data name=\"Neutralize Banner\" inherit_id=\"web.layout\" active=\"False\">\n        <xpath expr=\"//body\" position=\"inside\">\n            <div>\n                <span id=\"oe_neutralize_banner\" t-attf-style=\"                         text-align: center;                         color: #FFFFFF;                         background-color: #D0442C;                         position: relative;                         display: block;                         font-size: 16px;                         {{ neutralize_banner_style or '''' }}\">\n                    <t t-out=\"neutralize_banner_text\">Database neutralized for testing: no emails sent, etc.</t>\n                </span>\n            </div>\n        </xpath>\n        <xpath expr=\"//head\">\n            <meta name=\"robots\" content=\"noindex, nofollow\"/>\n        </xpath>\n    </data>"}', '<?xml version="1.0"?>
<data name="Neutralize Banner" inherit_id="web.layout" active="False">
        <xpath expr="//body" position="inside">
            <div>
                <span id="oe_neutralize_banner" t-attf-style="                         text-align: center;                         color: #FFFFFF;                         background-color: #D0442C;                         position: relative;                         display: block;                         font-size: 16px;                         {{ neutralize_banner_style or '''' }}">
                    <t t-out="neutralize_banner_text">Database neutralized for testing: no emails sent, etc.</t>
                </span>
            </div>
        </xpath>
        <xpath expr="//head">
            <meta name="robots" content="noindex, nofollow"/>
        </xpath>
    </data>
', false, false, '2026-05-10 01:07:07.223274', '2026-05-10 01:07:07.223274', NULL);
INSERT INTO public.ir_ui_view VALUES (213, 16, 165, 1, 1, 'res.users.view.search.inherit.auth.totp', 'res.users', NULL, 'search', 'auth_totp/views/res_users_views.xml', 'extension', '{"en_US": "<xpath expr=\"//search\" position=\"inside\">\n                <separator/>\n                <filter name=\"totp_enabled\" string=\"Two-factor authentication Enabled\" domain=\"[(''totp_enabled'',''!='',False)]\"/>\n                <filter name=\"totp_disabled\" string=\"Two-factor authentication Disabled\" domain=\"[(''totp_enabled'',''='',False)]\"/>\n            </xpath>"}', '<?xml version="1.0"?>
<xpath expr="//search" position="inside">
                <separator/>
                <filter name="totp_enabled" string="Two-factor authentication Enabled" domain="[(''totp_enabled'',''!='',False)]"/>
                <filter name="totp_disabled" string="Two-factor authentication Disabled" domain="[(''totp_enabled'',''='',False)]"/>
            </xpath>
        ', false, true, '2026-05-10 01:07:08.264439', '2026-05-10 01:07:08.264439', NULL);
INSERT INTO public.ir_ui_view VALUES (214, 16, 162, 1, 1, 'user form: add totp status', 'res.users', NULL, 'form', 'auth_totp/views/res_users_views.xml', 'extension', '{"en_US": "<xpath expr=\"//page[@name=''preferences'']\" position=\"after\">\n                <page string=\"Account Security\" name=\"security\" invisible=\"not id\">\n                    <field name=\"totp_enabled\" invisible=\"1\"/>\n                    <!-- For own user, allow to activate the two-factor Authentication -->\n                    <div>\n                        <div class=\"o_horizontal_separator d-flex align-items-center mt-2 mb-4 text-uppercase fw-bolder small\">Two-factor Authentication\n                                <div invisible=\"totp_enabled\">\n                                    <button invisible=\"id == uid\" name=\"action_totp_enable_wizard\" disabled=\"1\" type=\"object\" class=\"fa fa-toggle-off o_auth_2fa_btn disabled\" aria-label=\"Enable 2FA\"/>\n                                            <button invisible=\"id != uid\" name=\"action_totp_enable_wizard\" type=\"object\" class=\"fa fa-toggle-off o_auth_2fa_btn disabled pe-auto\" aria-label=\"Enable 2FA\"/>\n                                </div>\n                                <button invisible=\"not totp_enabled\" name=\"action_totp_disable\" type=\"object\" class=\"fa fa-toggle-on o_auth_2fa_btn text-primary enabled\" aria-label=\"Disable 2FA\"/>\n                            </div>\n                            <span invisible=\"totp_enabled\" class=\"text-muted\">\n                                Two-factor Authentication (\"2FA\") is a system of double authentication.\n                                The first one is done with your password and the second one with a code you get from a dedicated mobile app.\n                                Popular ones include Authy, Google Authenticator or the Microsoft Authenticator.\n                                <a href=\"https://www.odoo.com/documentation/17.0/applications/general/auth/2fa.html\" title=\"Learn More\" target=\"_blank\">\n                                    <i title=\"Documentation\" class=\"fa fa-fw o_button_icon fa-info-circle\"/>\n                                    Learn More\n                                </a>\n                                </span>\n                                <span invisible=\"not totp_enabled\" class=\"text-muted\">This account is protected!</span>\n                            </div>\n                        <group name=\"auth_devices\" string=\"Trusted Devices\" invisible=\"not totp_trusted_device_ids\">\n                            <div colspan=\"2\">\n                                <field name=\"totp_trusted_device_ids\" nolabel=\"1\" colspan=\"4\" readonly=\"1\">\n                                    <tree create=\"false\" delete=\"false\">\n                                        <field name=\"name\" string=\"Device\"/>\n                                        <field name=\"create_date\" string=\"Added On\"/>\n                                        <button type=\"object\" name=\"remove\" title=\"Revoke\" icon=\"fa-trash\"/>\n                                    </tree>\n                                </field>\n                                <button name=\"revoke_all_devices\" string=\"Revoke All\" type=\"object\" class=\"btn btn-secondary\" confirm=\"Are you sure? The user may be asked to enter two-factor codes again on those devices\"/>\n                            </div>\n                        </group>\n                </page>\n            </xpath>"}', '<?xml version="1.0"?>
<xpath expr="//page[@name=''preferences'']" position="after">
                <page string="Account Security" name="security" invisible="not id">
                    <field name="totp_enabled" invisible="1"/>
                    <!-- For own user, allow to activate the two-factor Authentication -->
                    <div>
                        <div class="o_horizontal_separator d-flex align-items-center mt-2 mb-4 text-uppercase fw-bolder small">Two-factor Authentication
                                <div invisible="totp_enabled">
                                    <button invisible="id == uid" name="action_totp_enable_wizard" disabled="1" type="object" class="fa fa-toggle-off o_auth_2fa_btn disabled" aria-label="Enable 2FA"/>
                                            <button invisible="id != uid" name="action_totp_enable_wizard" type="object" class="fa fa-toggle-off o_auth_2fa_btn disabled pe-auto" aria-label="Enable 2FA"/>
                                </div>
                                <button invisible="not totp_enabled" name="action_totp_disable" type="object" class="fa fa-toggle-on o_auth_2fa_btn text-primary enabled" aria-label="Disable 2FA"/>
                            </div>
                            <span invisible="totp_enabled" class="text-muted">
                                Two-factor Authentication ("2FA") is a system of double authentication.
                                The first one is done with your password and the second one with a code you get from a dedicated mobile app.
                                Popular ones include Authy, Google Authenticator or the Microsoft Authenticator.
                                <a href="https://www.odoo.com/documentation/17.0/applications/general/auth/2fa.html" title="Learn More" target="_blank">
                                    <i title="Documentation" class="fa fa-fw o_button_icon fa-info-circle"/>
                                    Learn More
                                </a>
                                </span>
                                <span invisible="not totp_enabled" class="text-muted">This account is protected!</span>
                            </div>
                        <group name="auth_devices" string="Trusted Devices" invisible="not totp_trusted_device_ids">
                            <div colspan="2">
                                <field name="totp_trusted_device_ids" nolabel="1" colspan="4" readonly="1">
                                    <tree create="false" delete="false">
                                        <field name="name" string="Device"/>
                                        <field name="create_date" string="Added On"/>
                                        <button type="object" name="remove" title="Revoke" icon="fa-trash"/>
                                    </tree>
                                </field>
                                <button name="revoke_all_devices" string="Revoke All" type="object" class="btn btn-secondary" confirm="Are you sure? The user may be asked to enter two-factor codes again on those devices"/>
                            </div>
                        </group>
                </page>
            </xpath>
        ', false, true, '2026-05-10 01:07:08.264439', '2026-05-10 01:07:08.264439', NULL);
INSERT INTO public.ir_ui_view VALUES (282, 16, NULL, 1, 1, 'utm.source.view.tree', 'utm.source', NULL, 'tree', 'utm/views/utm_source_views.xml', 'primary', '{"en_US": "<tree string=\"Source\" editable=\"bottom\" sample=\"1\">\n                <field name=\"name\" placeholder=\"e.g. &quot;Christmas Mailing&quot;\"/>\n            </tree>"}', '<?xml version="1.0"?>
<tree string="Source" editable="bottom" sample="1">
                <field name="name" placeholder="e.g. &quot;Christmas Mailing&quot;"/>
            </tree>
        ', false, true, '2026-05-10 01:11:43.219791', '2026-05-10 01:11:43.219791', NULL);
INSERT INTO public.ir_ui_view VALUES (215, 16, 169, 1, 1, 'users preference: totp', 'res.users', NULL, 'form', 'auth_totp/views/res_users_views.xml', 'extension', '{"en_US": "<group name=\"auth\" position=\"after\">\n                <field name=\"totp_enabled\" invisible=\"1\"/>\n                <div>\n                    <div class=\"o_horizontal_separator mt-2 mb-4 text-uppercase fw-bolder small\">Two-factor Authentication\n                        <button invisible=\"totp_enabled\" name=\"action_totp_enable_wizard\" type=\"object\" class=\"fa fa-toggle-off o_auth_2fa_btn\" aria-label=\"Enable 2FA\"/>\n                        <button invisible=\"not totp_enabled\" name=\"action_totp_disable\" type=\"object\" class=\"fa fa-toggle-on o_auth_2fa_btn text-primary\" aria-label=\"Disable 2FA\"/>\n                    </div>\n                    <span invisible=\"not totp_enabled\" class=\"text-muted\">Your account is protected!</span>\n                    <span invisible=\"totp_enabled\" class=\"text-muted\">\n                        Two-factor Authentication (\"2FA\") is a system of double authentication.\n                        The first one is done with your password and the second one with a code you get from a dedicated mobile app.\n                        Popular ones include Authy, Google Authenticator or the Microsoft Authenticator.\n                        <a href=\"https://www.odoo.com/documentation/17.0/applications/general/auth/2fa.html\" title=\"Learn More\" target=\"_blank\">\n                            <i title=\"Documentation\" class=\"fa fa-fw o_button_icon fa-info-circle\"/>\n                            Learn More\n                        </a>\n                    </span>\n                    <group name=\"auth_devices\" string=\"Trusted Devices\" invisible=\"not totp_trusted_device_ids\">\n                        <div colspan=\"2\">\n                            <field name=\"totp_trusted_device_ids\" nolabel=\"1\" colspan=\"4\" readonly=\"1\">\n                                <tree create=\"false\" delete=\"false\">\n                                    <field name=\"name\" string=\"Device\"/>\n                                    <field name=\"create_date\" string=\"Added On\"/>\n                                    <button type=\"object\" name=\"remove\" title=\"Revoke\" icon=\"fa-trash\"/>\n                                </tree>\n                            </field>\n                            <button name=\"revoke_all_devices\" string=\"Revoke All\" type=\"object\" class=\"btn btn-secondary\" confirm=\"Are you sure? You may be asked to enter two-factor codes again on those devices\"/>\n                        </div>\n                    </group>\n                </div>\n            </group>"}', '<?xml version="1.0"?>
<group name="auth" position="after">
                <field name="totp_enabled" invisible="1"/>
                <div>
                    <div class="o_horizontal_separator mt-2 mb-4 text-uppercase fw-bolder small">Two-factor Authentication
                        <button invisible="totp_enabled" name="action_totp_enable_wizard" type="object" class="fa fa-toggle-off o_auth_2fa_btn" aria-label="Enable 2FA"/>
                        <button invisible="not totp_enabled" name="action_totp_disable" type="object" class="fa fa-toggle-on o_auth_2fa_btn text-primary" aria-label="Disable 2FA"/>
                    </div>
                    <span invisible="not totp_enabled" class="text-muted">Your account is protected!</span>
                    <span invisible="totp_enabled" class="text-muted">
                        Two-factor Authentication ("2FA") is a system of double authentication.
                        The first one is done with your password and the second one with a code you get from a dedicated mobile app.
                        Popular ones include Authy, Google Authenticator or the Microsoft Authenticator.
                        <a href="https://www.odoo.com/documentation/17.0/applications/general/auth/2fa.html" title="Learn More" target="_blank">
                            <i title="Documentation" class="fa fa-fw o_button_icon fa-info-circle"/>
                            Learn More
                        </a>
                    </span>
                    <group name="auth_devices" string="Trusted Devices" invisible="not totp_trusted_device_ids">
                        <div colspan="2">
                            <field name="totp_trusted_device_ids" nolabel="1" colspan="4" readonly="1">
                                <tree create="false" delete="false">
                                    <field name="name" string="Device"/>
                                    <field name="create_date" string="Added On"/>
                                    <button type="object" name="remove" title="Revoke" icon="fa-trash"/>
                                </tree>
                            </field>
                            <button name="revoke_all_devices" string="Revoke All" type="object" class="btn btn-secondary" confirm="Are you sure? You may be asked to enter two-factor codes again on those devices"/>
                        </div>
                    </group>
                </div>
            </group>
        ', false, true, '2026-05-10 01:07:08.264439', '2026-05-10 01:07:08.264439', NULL);
INSERT INTO public.ir_ui_view VALUES (216, 16, NULL, 1, 1, 'Two-Factor Authentication', NULL, 'auth_totp.auth_totp_form', 'qweb', 'auth_totp/views/templates.xml', 'primary', '{"en_US": "<t name=\"Two-Factor Authentication\" t-name=\"auth_totp.auth_totp_form\">\n        <t t-call=\"web.login_layout\">\n            <t t-set=\"disable_footer\">1</t>\n            <div class=\"oe_login_form\">\n                <h5 class=\"card-title\">Two-factor Authentication</h5>\n                <form method=\"POST\" action=\"\" class=\"\">\n                    <div class=\"mb-2 mt-2 text-muted\">\n                        To login, enter below the six-digit authentication code provided by your Authenticator app.\n                        <br/>\n                        <a href=\"https://www.odoo.com/documentation/17.0/applications/general/auth/2fa.html\" title=\"Learn More\" target=\"_blank\">Learn More</a>\n                    </div>\n                    <input type=\"hidden\" name=\"csrf_token\" t-att-value=\"request.csrf_token()\"/>\n                    <input type=\"hidden\" name=\"redirect\" t-att-value=\"redirect\"/>\n                    <div class=\"mb-3\">\n                        <label class=\"fw-bold\" for=\"totp_token\">Authentication Code</label>\n                        <input id=\"totp_token\" name=\"totp_token\" class=\"form-control mb-2\" autocomplete=\"off\" inputmode=\"numeric\" autofocus=\"autofocus\" required=\"required\" placeholder=\"e.g. 123456\"/>\n                    </div>\n                    <div class=\"text-center py-2 border-top\">\n                        <p class=\"alert alert-danger\" t-if=\"error\" role=\"alert\">\n                            <t t-esc=\"error\"/>\n                        </p>\n                    <div class=\"mb-2 mt-2 text-muted\">\n                        <input type=\"checkbox\" name=\"remember\" id=\"switch-remember\" value=\"1\"/>\n                        <label for=\"switch-remember\">Don''t ask again on this device</label>\n                    </div>\n                        <div t-attf-class=\"clearfix oe_login_buttons text-center d-grid mb-1\">\n                            <button type=\"submit\" class=\"btn btn-primary\">\n                                Log in\n                            </button>\n                        </div>\n\n                    </div>\n                </form>\n\n                <form method=\"POST\" action=\"/web/session/logout\">\n                    <input type=\"hidden\" name=\"csrf_token\" t-att-value=\"request.csrf_token()\"/>\n                    <div class=\"w-100 text-center\">\n                        <button type=\"submit\" class=\"btn btn-link btn-sm mb-2\">\n                            Cancel\n                        </button>\n                    </div>\n                </form>\n            </div>\n        </t>\n    </t>"}', '<?xml version="1.0"?>
<t name="Two-Factor Authentication" t-name="auth_totp.auth_totp_form">
        <t t-call="web.login_layout">
            <t t-set="disable_footer">1</t>
            <div class="oe_login_form">
                <h5 class="card-title">Two-factor Authentication</h5>
                <form method="POST" action="" class="">
                    <div class="mb-2 mt-2 text-muted">
                        To login, enter below the six-digit authentication code provided by your Authenticator app.
                        <br/>
                        <a href="https://www.odoo.com/documentation/17.0/applications/general/auth/2fa.html" title="Learn More" target="_blank">Learn More</a>
                    </div>
                    <input type="hidden" name="csrf_token" t-att-value="request.csrf_token()"/>
                    <input type="hidden" name="redirect" t-att-value="redirect"/>
                    <div class="mb-3">
                        <label class="fw-bold" for="totp_token">Authentication Code</label>
                        <input id="totp_token" name="totp_token" class="form-control mb-2" autocomplete="off" inputmode="numeric" autofocus="autofocus" required="required" placeholder="e.g. 123456"/>
                    </div>
                    <div class="text-center py-2 border-top">
                        <p class="alert alert-danger" t-if="error" role="alert">
                            <t t-esc="error"/>
                        </p>
                    <div class="mb-2 mt-2 text-muted">
                        <input type="checkbox" name="remember" id="switch-remember" value="1"/>
                        <label for="switch-remember">Don''t ask again on this device</label>
                    </div>
                        <div t-attf-class="clearfix oe_login_buttons text-center d-grid mb-1">
                            <button type="submit" class="btn btn-primary">
                                Log in
                            </button>
                        </div>

                    </div>
                </form>

                <form method="POST" action="/web/session/logout">
                    <input type="hidden" name="csrf_token" t-att-value="request.csrf_token()"/>
                    <div class="w-100 text-center">
                        <button type="submit" class="btn btn-link btn-sm mb-2">
                            Cancel
                        </button>
                    </div>
                </form>
            </div>
        </t>
    </t>
', false, true, '2026-05-10 01:07:08.264439', '2026-05-10 01:07:08.264439', NULL);
INSERT INTO public.ir_ui_view VALUES (217, 16, NULL, 1, 1, 'auth_totp wizard', 'auth_totp.wizard', NULL, 'form', 'auth_totp/wizard/auth_totp_wizard_views.xml', 'primary', '{"en_US": "<form>\n                <sheet>\n                    <div class=\"o_auth_totp_enable_2FA container\">\n                        <div class=\"mb-3 w-100\">\n                            <h3 class=\"fw-bold\">Authenticator App Setup</h3>\n                            <ul>\n                                <div class=\"d-md-none d-block\">\n                                    <li>\n                                        <field class=\"text-wrap\" name=\"url\" widget=\"url\" options=\"{''website_path'': True}\" text=\"Click on this link to open your authenticator app\"/></li>\n                                </div>\n                                <li>\n                                    <div class=\"d-flex align-items-center flex-wrap\">\n                                        <span class=\"d-md-none d-block\">Or install an authenticator app</span>\n                                        <span class=\"d-none d-md-block\">Install an authenticator app on your mobile device</span>\n                                        <div class=\"d-block d-md-none\">\n                                            <a href=\"https://play.google.com/store/search?q=authenticator&amp;c=apps\" class=\"mx-2\" target=\"blank\">\n                                                <img alt=\"On Google Play\" style=\"width: 24px;\" src=\"/base_setup/static/src/img/logo_google_play.png\"/>\n                                            </a>\n                                            <a href=\"http://appstore.com/2fa\" class=\"mx-2\" target=\"blank\">\n                                                <img alt=\"On Apple Store\" style=\"width: 24px;\" src=\"/base_setup/static/src/img/logo_apple_store.png\"/>\n                                            </a>\n                                        </div>\n                                    </div>\n                                </li>\n\n                                <span class=\"text-muted\">Popular ones include Authy, Google Authenticator or the Microsoft Authenticator.</span>\n                                <li>Look for an \"Add an account\" button</li>\n                                <li>\n                                    <span class=\"d-none d-md-block\">When requested to do so, scan the barcode below</span>\n                                    <span class=\"d-block d-md-none\">When requested to do so, copy the key below</span>\n                                </li>\n                            </ul>\n\n                            <!-- Desktop version -->\n                            <div class=\"text-center d-none d-md-block\">\n                                <field name=\"qrcode\" readonly=\"True\" widget=\"image\" options=\"{''reload'': false }\"/>\n\n                                <h3 class=\"fw-bold\"><a data-bs-toggle=\"collapse\" href=\"#collapseTotpSecret\" role=\"button\" aria-expanded=\"false\" aria-controls=\"collapseTotpSecret\">Cannot scan it?</a></h3>\n                                <div class=\"collapse\" id=\"collapseTotpSecret\">\n                                  <field name=\"secret\" widget=\"CopyClipboardChar\" readonly=\"1\" class=\"mb-3 ps-3\"/>\n                                </div>\n                            </div>\n\n                            <!-- Mobile Version -->\n                            <div class=\"text-center d-block d-md-none\">\n                                <field name=\"secret\" widget=\"CopyClipboardChar\" readonly=\"1\" class=\"mb-3 ps-3\"/>\n                            </div>\n\n                            <h3 class=\"fw-bold\">Enter your six-digit code below</h3>\n                            <div class=\"mt-2\">\n                                <label for=\"code\" class=\"px-0\">Verification Code</label>\n                                <div class=\"d-flex align-items-center\">\n                                    <field required=\"True\" name=\"code\" autocomplete=\"off\" class=\"o_field_highlight px-0 me-2\" placeholder=\"e.g. 123456\"/>\n                                </div>\n                            </div>\n                        </div>\n                    </div>\n                </sheet>\n                <footer>\n                    <button type=\"object\" name=\"enable\" class=\"btn btn-primary\" string=\"Activate\" data-hotkey=\"q\"/>\n                    <button string=\"Cancel\" special=\"cancel\" data-hotkey=\"x\"/>\n                </footer>\n            </form>"}', '<?xml version="1.0"?>
<form>
                <sheet>
                    <div class="o_auth_totp_enable_2FA container">
                        <div class="mb-3 w-100">
                            <h3 class="fw-bold">Authenticator App Setup</h3>
                            <ul>
                                <div class="d-md-none d-block">
                                    <li>
                                        <field class="text-wrap" name="url" widget="url" options="{''website_path'': True}" text="Click on this link to open your authenticator app"/></li>
                                </div>
                                <li>
                                    <div class="d-flex align-items-center flex-wrap">
                                        <span class="d-md-none d-block">Or install an authenticator app</span>
                                        <span class="d-none d-md-block">Install an authenticator app on your mobile device</span>
                                        <div class="d-block d-md-none">
                                            <a href="https://play.google.com/store/search?q=authenticator&amp;c=apps" class="mx-2" target="blank">
                                                <img alt="On Google Play" style="width: 24px;" src="/base_setup/static/src/img/logo_google_play.png"/>
                                            </a>
                                            <a href="http://appstore.com/2fa" class="mx-2" target="blank">
                                                <img alt="On Apple Store" style="width: 24px;" src="/base_setup/static/src/img/logo_apple_store.png"/>
                                            </a>
                                        </div>
                                    </div>
                                </li>

                                <span class="text-muted">Popular ones include Authy, Google Authenticator or the Microsoft Authenticator.</span>
                                <li>Look for an "Add an account" button</li>
                                <li>
                                    <span class="d-none d-md-block">When requested to do so, scan the barcode below</span>
                                    <span class="d-block d-md-none">When requested to do so, copy the key below</span>
                                </li>
                            </ul>

                            <!-- Desktop version -->
                            <div class="text-center d-none d-md-block">
                                <field name="qrcode" readonly="True" widget="image" options="{''reload'': false }"/>

                                <h3 class="fw-bold"><a data-bs-toggle="collapse" href="#collapseTotpSecret" role="button" aria-expanded="false" aria-controls="collapseTotpSecret">Cannot scan it?</a></h3>
                                <div class="collapse" id="collapseTotpSecret">
                                  <field name="secret" widget="CopyClipboardChar" readonly="1" class="mb-3 ps-3"/>
                                </div>
                            </div>

                            <!-- Mobile Version -->
                            <div class="text-center d-block d-md-none">
                                <field name="secret" widget="CopyClipboardChar" readonly="1" class="mb-3 ps-3"/>
                            </div>

                            <h3 class="fw-bold">Enter your six-digit code below</h3>
                            <div class="mt-2">
                                <label for="code" class="px-0">Verification Code</label>
                                <div class="d-flex align-items-center">
                                    <field required="True" name="code" autocomplete="off" class="o_field_highlight px-0 me-2" placeholder="e.g. 123456"/>
                                </div>
                            </div>
                        </div>
                    </div>
                </sheet>
                <footer>
                    <button type="object" name="enable" class="btn btn-primary" string="Activate" data-hotkey="q"/>
                    <button string="Cancel" special="cancel" data-hotkey="x"/>
                </footer>
            </form>
        ', false, true, '2026-05-10 01:07:08.264439', '2026-05-10 01:07:08.264439', NULL);
INSERT INTO public.ir_ui_view VALUES (218, 16, NULL, 1, 1, 'base.import.module.form', 'base.import.module', NULL, 'form', 'base_import_module/views/base_import_module_view.xml', 'primary', '{"en_US": "<form string=\"Install the application\">\n                    <field name=\"state\" invisible=\"1\"/>\n                    <p class=\"alert alert-warning\" role=\"alert\" invisible=\"state == ''done'' or context.get(''data_module'')\">Note: you can only import data modules (.xml files and static assets)</p>\n                    <field name=\"modules_dependencies\" readonly=\"1\" nolabel=\"1\" invisible=\"state == ''done''\"/>\n                    <group invisible=\"state != ''init''\">\n                        <field name=\"module_file\" string=\"Module file (.zip)\" options=\"{''accepted_file_extensions'': ''.zip''}\" invisible=\"context.get(''data_module'')\"/>\n                        <field name=\"force\" groups=\"base.group_no_one\"/>\n                        <field name=\"with_demo\" string=\"Load demo data\"/>\n                    </group>\n                    <group invisible=\"state != ''done''\">\n                        <field name=\"import_message\" nolabel=\"1\" readonly=\"1\"/>\n                    </group>\n                    <footer>\n                        <div invisible=\"state != ''init''\">\n                            <button name=\"import_module\" string=\"Install\" type=\"object\" class=\"btn-primary\" data-hotkey=\"q\"/>\n                            <button special=\"cancel\" data-hotkey=\"x\" string=\"Cancel\" class=\"btn-secondary\"/>\n                        </div>\n                        <div invisible=\"state != ''done''\">\n                            <button special=\"cancel\" data-hotkey=\"x\" string=\"Close\" class=\"btn-secondary\"/>\n                        </div>\n                    </footer>\n                </form>"}', '<?xml version="1.0"?>
<form string="Install the application">
                    <field name="state" invisible="1"/>
                    <p class="alert alert-warning" role="alert" invisible="state == ''done'' or context.get(''data_module'')">Note: you can only import data modules (.xml files and static assets)</p>
                    <field name="modules_dependencies" readonly="1" nolabel="1" invisible="state == ''done''"/>
                    <group invisible="state != ''init''">
                        <field name="module_file" string="Module file (.zip)" options="{''accepted_file_extensions'': ''.zip''}" invisible="context.get(''data_module'')"/>
                        <field name="force" groups="base.group_no_one"/>
                        <field name="with_demo" string="Load demo data"/>
                    </group>
                    <group invisible="state != ''done''">
                        <field name="import_message" nolabel="1" readonly="1"/>
                    </group>
                    <footer>
                        <div invisible="state != ''init''">
                            <button name="import_module" string="Install" type="object" class="btn-primary" data-hotkey="q"/>
                            <button special="cancel" data-hotkey="x" string="Cancel" class="btn-secondary"/>
                        </div>
                        <div invisible="state != ''done''">
                            <button special="cancel" data-hotkey="x" string="Close" class="btn-secondary"/>
                        </div>
                    </footer>
                </form>
            ', false, true, '2026-05-10 01:07:08.864289', '2026-05-10 01:07:08.864289', NULL);
INSERT INTO public.ir_ui_view VALUES (219, 16, 97, 1, 1, 'Apps Kanban Data Modules', 'ir.module.module', NULL, 'kanban', 'base_import_module/views/ir_module_views.xml', 'extension', '{"en_US": "<data><xpath expr=\"//field[@name=''application'']\" position=\"after\">\n                    <field name=\"module_type\"/>\n                </xpath>\n                <xpath expr=\"//button[@name=''button_immediate_install'']\" position=\"after\">\n                    <button type=\"object\" class=\"btn btn-primary btn-sm\" name=\"button_immediate_install_app\" invisible=\"state != ''uninstalled'' or module_type in (''official'', False)\" groups=\"base.group_system\" context=\"{''module_name'':name}\">Activate</button>\n                    <button type=\"object\" class=\"btn btn-primary btn-sm\" name=\"button_immediate_install_app\" invisible=\"state == ''uninstalled'' or module_type in (''official'', False)\" groups=\"base.group_system\" context=\"{''module_name'':name}\">Upgrade</button>\n                </xpath>\n                <xpath expr=\"//button[@name=''button_immediate_install'']\" position=\"attributes\">\n                    <attribute name=\"invisible\">state != ''uninstalled'' or (module_type and module_type != ''official'')</attribute>\n                </xpath>\n                <xpath expr=\"//t[@t-name=''kanban-menu'']/a[@type=''edit'']\" position=\"attributes\">\n                    <attribute name=\"context\">{''module_type'': module_type, ''module_name'':name}</attribute>\n                    <attribute name=\"type\">object</attribute>\n                    <attribute name=\"name\">more_info</attribute>\n                </xpath>\n                <xpath expr=\"//div[hasclass(''oe_module_action'')]/a[@type=''edit'']\" position=\"attributes\">\n                    <attribute name=\"context\">{''module_type'': module_type, ''module_name'':name}</attribute>\n                    <attribute name=\"type\">object</attribute>\n                    <attribute name=\"name\">more_info</attribute>\n                </xpath>\n            </data>"}', '<?xml version="1.0"?>
<data><xpath expr="//field[@name=''application'']" position="after">
                    <field name="module_type"/>
                </xpath>
                <xpath expr="//button[@name=''button_immediate_install'']" position="after">
                    <button type="object" class="btn btn-primary btn-sm" name="button_immediate_install_app" invisible="state != ''uninstalled'' or module_type in (''official'', False)" groups="base.group_system" context="{''module_name'':name}">Activate</button>
                    <button type="object" class="btn btn-primary btn-sm" name="button_immediate_install_app" invisible="state == ''uninstalled'' or module_type in (''official'', False)" groups="base.group_system" context="{''module_name'':name}">Upgrade</button>
                </xpath>
                <xpath expr="//button[@name=''button_immediate_install'']" position="attributes">
                    <attribute name="invisible">state != ''uninstalled'' or (module_type and module_type != ''official'')</attribute>
                </xpath>
                <xpath expr="//t[@t-name=''kanban-menu'']/a[@type=''edit'']" position="attributes">
                    <attribute name="context">{''module_type'': module_type, ''module_name'':name}</attribute>
                    <attribute name="type">object</attribute>
                    <attribute name="name">more_info</attribute>
                </xpath>
                <xpath expr="//div[hasclass(''oe_module_action'')]/a[@type=''edit'']" position="attributes">
                    <attribute name="context">{''module_type'': module_type, ''module_name'':name}</attribute>
                    <attribute name="type">object</attribute>
                    <attribute name="name">more_info</attribute>
                </xpath>
            </data>', false, true, '2026-05-10 01:07:08.864289', '2026-05-10 01:07:08.864289', NULL);
