INSERT INTO public.ir_ui_view VALUES (220, 16, 96, 1, 1, 'Apps List Data Modules', 'ir.module.module', NULL, 'tree', 'base_import_module/views/ir_module_views.xml', 'extension', '{"en_US": "<data><xpath expr=\"//field[@name=''category_id'']\" position=\"after\">\n                    <field name=\"module_type\" column_invisible=\"1\"/>\n                    <field name=\"name\" column_invisible=\"1\"/>\n                </xpath>\n                <tree position=\"attributes\">\n                    <attribute name=\"js_class\">ir_module_module_tree_view</attribute>\n                </tree>\n            </data>"}', '<?xml version="1.0"?>
