INSERT INTO public.ir_ui_view VALUES (228, 16, NULL, 1, 1, 'iap.account.form', 'iap.account', NULL, 'form', 'iap/views/iap_views.xml', 'primary', '{"en_US": "<form string=\"IAP Account\">\n                <sheet>\n                    <group name=\"account\" string=\"Account Information\">\n                        <group>\n                            <field name=\"name\"/>\n                            <field name=\"service_name\"/>\n                            <field name=\"description\"/>\n                            <field name=\"company_ids\" widget=\"many2many_tags\" domain=\"[(''id'', ''in'', allowed_company_ids)]\"/>\n                            <field name=\"show_token\" invisible=\"1\"/>\n                            <label for=\"account_token\"/>\n                            <div class=\"o_row\">\n                                <field name=\"account_token\" password=\"False\" invisible=\"not show_token\"/>\n                                <field name=\"account_token\" password=\"True\" invisible=\"show_token\"/>\n                                <button name=\"action_toggle_show_token\" icon=\"fa-eye\" type=\"object\" class=\"oe_stat_button\" invisible=\"show_token\" title=\"Show Token\"/>\n                                <button name=\"action_toggle_show_token\" icon=\"fa-eye-slash\" type=\"object\" class=\"oe_stat_button\" invisible=\"not show_token\" title=\"Hide Token\"/>\n                            </div>\n                            <field name=\"warn_me\"/>\n                            <field name=\"warning_threshold\" invisible=\"not warn_me\"/>\n                            <field name=\"warning_email\" invisible=\"not warn_me\"/>\n                        </group>\n                        <group class=\"d-flex flex-column\">\n                            <group class=\"d-flex\">\n                                <button name=\"action_buy_credits\" type=\"object\" string=\"Buy Credit\" class=\"oe_highlight\"/>\n                            </group>\n                            <group>\n                                <field name=\"balance\" class=\"oe-inline\"/>\n                            </group>\n                        </group>\n                    </group>\n                </sheet>\n            </form>"}', '<?xml version="1.0"?>
<form string="IAP Account">
                <sheet>
                    <group name="account" string="Account Information">
                        <group>
                            <field name="name"/>
                            <field name="service_name"/>
                            <field name="description"/>
                            <field name="company_ids" widget="many2many_tags" domain="[(''id'', ''in'', allowed_company_ids)]"/>
                            <field name="show_token" invisible="1"/>
                            <label for="account_token"/>
                            <div class="o_row">
                                <field name="account_token" password="False" invisible="not show_token"/>
                                <field name="account_token" password="True" invisible="show_token"/>
                                <button name="action_toggle_show_token" icon="fa-eye" type="object" class="oe_stat_button" invisible="show_token" title="Show Token"/>
                                <button name="action_toggle_show_token" icon="fa-eye-slash" type="object" class="oe_stat_button" invisible="not show_token" title="Hide Token"/>
                            </div>
                            <field name="warn_me"/>
                            <field name="warning_threshold" invisible="not warn_me"/>
                            <field name="warning_email" invisible="not warn_me"/>
                        </group>
                        <group class="d-flex flex-column">
                            <group class="d-flex">
                                <button name="action_buy_credits" type="object" string="Buy Credit" class="oe_highlight"/>
                            </group>
                            <group>
                                <field name="balance" class="oe-inline"/>
                            </group>
                        </group>
                    </group>
                </sheet>
            </form>
        ', false, true, '2026-05-10 01:07:09.223872', '2026-05-10 01:07:09.223872', NULL);
