INSERT INTO public.ir_ui_view VALUES (229, 16, NULL, 1, 1, 'iap.account.tree', 'iap.account', NULL, 'tree', 'iap/views/iap_views.xml', 'primary', '{"en_US": "<tree string=\"IAP Accounts\">\n                <field name=\"name\"/>\n                <field name=\"service_name\"/>\n                <field name=\"company_ids\" widget=\"many2many_tags\"/>\n                <field name=\"account_token\" readonly=\"1\" password=\"True\"/>\n                <field name=\"balance\"/>\n                <field name=\"warning_threshold\" optional=\"hidden\"/>\n                <field name=\"description\" optional=\"hidden\"/>\n            </tree>"}', '<?xml version="1.0"?>
