INSERT INTO public.ir_ui_view VALUES (231, 16, NULL, 1, 1, 'Color-Picker', NULL, 'web_editor.colorpicker', 'qweb', 'web_editor/views/editor.xml', 'primary', '{"en_US": "<t name=\"Color-Picker\" t-name=\"web_editor.colorpicker\">\n    <colorpicker>\n        <div class=\"o_colorpicker_section\" data-name=\"theme\">\n            <button data-color=\"o-color-1\"/>\n            <button data-color=\"o-color-3\"/>\n            <button data-color=\"o-color-2\"/>\n            <button data-color=\"o-color-4\" class=\"ms-2\"/>\n            <button data-color=\"o-color-5\"/>\n        </div>\n        <div class=\"o_colorpicker_section\" data-name=\"common\">\n            <button data-color=\"black\"/>\n            <button data-color=\"900\"/>\n            <button data-color=\"800\"/>\n            <button data-color=\"700\" class=\"d-none\"/>\n            <button data-color=\"600\"/>\n            <button data-color=\"500\" class=\"d-none\"/>\n            <button data-color=\"400\"/>\n            <button data-color=\"300\" class=\"d-none\"/>\n            <button data-color=\"200\"/>\n            <button data-color=\"100\"/>\n            <button data-color=\"white\"/>\n        </div>\n        <div class=\"o_colorpicker_section\" data-name=\"transparent_grayscale\">\n            <button data-color=\"black-15\"/>\n            <button data-color=\"black-25\"/>\n            <button data-color=\"black-50\"/>\n            <button data-color=\"black-75\"/>\n            <button data-color=\"white-25\"/>\n            <button data-color=\"white-50\"/>\n            <button data-color=\"white-75\"/>\n            <button data-color=\"white-85\"/>\n        </div>\n        <div class=\"o_colorpicker_section\" data-name=\"predefined_gradients\">\n            <t t-set=\"gradients\" t-value=\"[                 ''linear-gradient(135deg, rgb(255, 204, 51) 0%, rgb(226, 51, 255) 100%)'',                 ''linear-gradient(135deg, rgb(102, 153, 255) 0%, rgb(255, 51, 102) 100%)'',                 ''linear-gradient(135deg, rgb(47, 128, 237) 0%, rgb(178, 255, 218) 100%)'',                 ''linear-gradient(135deg, rgb(203, 94, 238) 0%, rgb(75, 225, 236) 100%)'',                 ''linear-gradient(135deg, rgb(214, 255, 127) 0%, rgb(0, 179, 204) 100%)'',                 ''linear-gradient(135deg, rgb(255, 222, 69) 0%, rgb(69, 33, 0) 100%)'',                 ''linear-gradient(135deg, rgb(222, 222, 222) 0%, rgb(69, 69, 69) 100%)'',                 ''linear-gradient(135deg, rgb(255, 222, 202) 0%, rgb(202, 115, 69) 100%)''             ]\"/>\n            <t t-foreach=\"gradients\" t-as=\"gradient\">\n                <button class=\"w-50\" t-attf-style=\"background-image: #{gradient};\" t-att-data-color=\"gradient\"/>\n            </t>\n        </div>\n        <div class=\"o_colorpicker_section o_custom_gradient_editor\" data-name=\"custom_gradient\">\n            <button class=\"w-50 o_custom_gradient_btn o_we_color_btn py-1 btn\" title=\"Define a custom gradient\">Custom</button>\n            <div class=\"o_color_picker_inputs mx-1\">\n                <t t-set=\"input_classes\" t-value=\"''p-0 border-0 text-center font-monospace bg-transparent text-white''\"/>\n                <div class=\"d-flex justify-content-between my-2 o_type_row\">\n                    <we-title>Type</we-title>\n                    <span class=\"d-flex justify-content-between bg-black-50\">\n                        <we-button data-gradient-type=\"linear-gradient\" class=\"d-flex align-items-baseline active\">Linear</we-button>\n                        <we-button data-gradient-type=\"radial-gradient\" class=\"d-flex align-items-baseline\">Radial</we-button>\n                    </span>\n                </div>\n                <div class=\"d-flex justify-content-between my-2 o_angle_row\">\n                    <we-title>Angle</we-title>\n                    <span class=\"o_custom_gradient_input bg-black-50 px-1 d-flex align-items-baseline\">\n                        <input data-name=\"angle\" type=\"text\" t-attf-class=\"{{input_classes}}\" style=\"width: 5ch;\" value=\"90\"/>\n                        <span class=\"flex-grow-0 ms-1 text-white-50\">deg</span>\n                    </span>\n                </div>\n                <div class=\"d-flex justify-content-between my-2 o_position_row\">\n                    <we-title>Position</we-title>\n                    <span class=\"d-flex\">\n                    <span class=\"me-2\">X</span>\n                    <span class=\"o_custom_gradient_input bg-black-50 px-1 d-flex\">\n                        <input data-name=\"positionX\" type=\"text\" t-attf-class=\"{{input_classes}}\" style=\"width: 3ch;\" value=\"25\"/>\n                        <span class=\"flex-grow-0 ms-1 text-white-50\">%</span>\n                    </span>\n                    <span class=\"me-2 ms-3\">Y</span>\n                    <span class=\"o_custom_gradient_input bg-black-50 px-1 d-flex\">\n                        <input data-name=\"positionY\" type=\"text\" t-attf-class=\"{{input_classes}}\" style=\"width: 3ch;\" value=\"25\"/>\n                        <span class=\"flex-grow-0 ms-1 text-white-50\">%</span>\n                    </span>\n                    </span>\n                </div>\n                <div class=\"d-flex justify-content-between my-2 o_size_row\">\n                    <we-title>Size</we-title>\n                    <span class=\"d-flex justify-content-between\">\n                        <we-button data-gradient-size=\"closest-side\" class=\"d-flex align-items-baseline\" title=\"Extend to the closest side\">\n                            <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"16\" height=\"20\" viewBox=\"0 0 16 20\" fill=\"none\">\n                                <rect x=\"1.5\" y=\"3.5\" width=\"13\" height=\"13\" stroke=\"#AAAAAD\"/>\n                                <path d=\"M3 4H9V8C9 8.55228 8.55228 9 8 9H4C3.44772 9 3 8.55228 3 8V4Z\" fill=\"#8C8C92\"/>\n                                <path d=\"M6 11C7.65685 11 9 9.65685 9 8C9 6.34315 7.65685 5 6 5C4.34315 5 3 6.34315 3 8C3 9.65685 4.34315 11 6 11Z\" fill=\"#74747B\"/>\n                                <path d=\"M6 10C7.10457 10 8 9.10457 8 8C8 6.89543 7.10457 6 6 6C4.89543 6 4 6.89543 4 8C4 9.10457 4.89543 10 6 10Z\" fill=\"white\"/>\n                                <rect x=\"2\" y=\"3\" width=\"12\" height=\"1\" fill=\"white\"/>\n                            </svg>\n                        </we-button>\n                        <we-button data-gradient-size=\"closest-corner\" class=\"d-flex align-items-baseline\" title=\"Extend to the closest corner\">\n                            <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"16\" height=\"20\" viewBox=\"0 0 16 20\" fill=\"none\">\n                                <rect x=\"1.5\" y=\"3.5\" width=\"13\" height=\"13\" stroke=\"#AAAAAD\"/>\n                                <path d=\"M2 4H9V7C9 9.20914 7.20914 11 5 11H2V4Z\" fill=\"#8C8C92\"/>\n                                <path d=\"M6 11C7.65685 11 9 9.65685 9 8C9 6.34315 7.65685 5 6 5C4.34315 5 3 6.34315 3 8C3 9.65685 4.34315 11 6 11Z\" fill=\"#74747B\"/>\n                                <path d=\"M6 10C7.10457 10 8 9.10457 8 8C8 6.89543 7.10457 6 6 6C4.89543 6 4 6.89543 4 8C4 9.10457 4.89543 10 6 10Z\" fill=\"white\"/>\n                                <rect x=\"1\" y=\"3\" width=\"8\" height=\"1\" fill=\"white\"/>\n                                <rect x=\"1\" y=\"11\" width=\"8\" height=\"1\" transform=\"rotate(-90 1 11)\" fill=\"white\"/>\n                            </svg>\n                        </we-button>\n                        <we-button data-gradient-size=\"farthest-side\" class=\"d-flex align-items-baseline active\" title=\"Extend to the farthest side\">\n                            <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"16\" height=\"20\" viewBox=\"0 0 16 20\" fill=\"none\">\n                                <rect x=\"1.5\" y=\"3.5\" width=\"13\" height=\"13\" stroke=\"#AAAAAD\"/>\n                                <path d=\"M7 12C10.3137 12 14 10.2091 14 8C14 5.79086 10.3137 4 7 4C3.68629 4 2 5.79086 2 8C2 10.2091 3.68629 12 7 12Z\" fill=\"#8C8C92\"/>\n                                <path d=\"M6 11C7.65685 11 9 9.65685 9 8C9 6.34315 7.65685 5 6 5C4.34315 5 3 6.34315 3 8C3 9.65685 4.34315 11 6 11Z\" fill=\"#74747B\"/>\n                                <path d=\"M6 10C7.10457 10 8 9.10457 8 8C8 6.89543 7.10457 6 6 6C4.89543 6 4 6.89543 4 8C4 9.10457 4.89543 10 6 10Z\" fill=\"white\"/>\n                                <rect x=\"14\" y=\"4\" width=\"1\" height=\"12\" fill=\"white\"/>\n                            </svg>\n                        </we-button>\n                        <we-button data-gradient-size=\"farthest-corner\" class=\"d-flex align-items-baseline\" title=\"Extend to the farthest corner\">\n                            <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"16\" height=\"20\" viewBox=\"0 0 16 20\" fill=\"none\">\n                                <rect x=\"1.5\" y=\"3.5\" width=\"13\" height=\"13\" stroke=\"#AAAAAD\"/>\n                                <path d=\"M2 4H14V10C14 13.3137 11.3137 16 8 16H2V4Z\" fill=\"#8C8C92\"/>\n                                <path d=\"M6 11C7.65685 11 9 9.65685 9 8C9 6.34315 7.65685 5 6 5C4.34315 5 3 6.34315 3 8C3 9.65685 4.34315 11 6 11Z\" fill=\"#74747B\"/>\n                                <path d=\"M6 10C7.10457 10 8 9.10457 8 8C8 6.89543 7.10457 6 6 6C4.89543 6 4 6.89543 4 8C4 9.10457 4.89543 10 6 10Z\" fill=\"white\"/>\n                                <rect x=\"15\" y=\"17\" width=\"7\" height=\"0.999999\" transform=\"rotate(-180 15 17)\" fill=\"white\"/>\n                                <rect x=\"15\" y=\"10\" width=\"7\" height=\"1\" transform=\"rotate(90 15 10)\" fill=\"white\"/>\n                            </svg>\n                        </we-button>\n                    </span>\n                </div>\n                <div class=\"mx-1 o_custom_gradient_scale\">\n                    <div class=\"w-100\"/>\n                </div>\n                <div class=\"w-100 o_slider_multi\" role=\"group\"/>\n                <we-button class=\"o_remove_color fa fa-fw fa-trash o_we_link o_we_hover_danger\" title=\"Remove Selected Color\" aria-label=\"Remove Selected Color\"/>\n            </div>\n        </div>\n    </colorpicker>\n</t>"}', '<?xml version="1.0"?>
<t name="Color-Picker" t-name="web_editor.colorpicker">
    <colorpicker>
        <div class="o_colorpicker_section" data-name="theme">
            <button data-color="o-color-1"/>
            <button data-color="o-color-3"/>
            <button data-color="o-color-2"/>
            <button data-color="o-color-4" class="ms-2"/>
            <button data-color="o-color-5"/>
        </div>
        <div class="o_colorpicker_section" data-name="common">
            <button data-color="black"/>
            <button data-color="900"/>
            <button data-color="800"/>
            <button data-color="700" class="d-none"/>
            <button data-color="600"/>
            <button data-color="500" class="d-none"/>
            <button data-color="400"/>
            <button data-color="300" class="d-none"/>
            <button data-color="200"/>
            <button data-color="100"/>
            <button data-color="white"/>
        </div>
        <div class="o_colorpicker_section" data-name="transparent_grayscale">
            <button data-color="black-15"/>
            <button data-color="black-25"/>
            <button data-color="black-50"/>
            <button data-color="black-75"/>
            <button data-color="white-25"/>
            <button data-color="white-50"/>
            <button data-color="white-75"/>
            <button data-color="white-85"/>
        </div>
        <div class="o_colorpicker_section" data-name="predefined_gradients">
            <t t-set="gradients" t-value="[                 ''linear-gradient(135deg, rgb(255, 204, 51) 0%, rgb(226, 51, 255) 100%)'',                 ''linear-gradient(135deg, rgb(102, 153, 255) 0%, rgb(255, 51, 102) 100%)'',                 ''linear-gradient(135deg, rgb(47, 128, 237) 0%, rgb(178, 255, 218) 100%)'',                 ''linear-gradient(135deg, rgb(203, 94, 238) 0%, rgb(75, 225, 236) 100%)'',                 ''linear-gradient(135deg, rgb(214, 255, 127) 0%, rgb(0, 179, 204) 100%)'',                 ''linear-gradient(135deg, rgb(255, 222, 69) 0%, rgb(69, 33, 0) 100%)'',                 ''linear-gradient(135deg, rgb(222, 222, 222) 0%, rgb(69, 69, 69) 100%)'',                 ''linear-gradient(135deg, rgb(255, 222, 202) 0%, rgb(202, 115, 69) 100%)''             ]"/>
            <t t-foreach="gradients" t-as="gradient">
                <button class="w-50" t-attf-style="background-image: #{gradient};" t-att-data-color="gradient"/>
            </t>
        </div>
        <div class="o_colorpicker_section o_custom_gradient_editor" data-name="custom_gradient">
            <button class="w-50 o_custom_gradient_btn o_we_color_btn py-1 btn" title="Define a custom gradient">Custom</button>
            <div class="o_color_picker_inputs mx-1">
                <t t-set="input_classes" t-value="''p-0 border-0 text-center font-monospace bg-transparent text-white''"/>
                <div class="d-flex justify-content-between my-2 o_type_row">
                    <we-title>Type</we-title>
                    <span class="d-flex justify-content-between bg-black-50">
                        <we-button data-gradient-type="linear-gradient" class="d-flex align-items-baseline active">Linear</we-button>
                        <we-button data-gradient-type="radial-gradient" class="d-flex align-items-baseline">Radial</we-button>
                    </span>
                </div>
                <div class="d-flex justify-content-between my-2 o_angle_row">
                    <we-title>Angle</we-title>
                    <span class="o_custom_gradient_input bg-black-50 px-1 d-flex align-items-baseline">
                        <input data-name="angle" type="text" t-attf-class="{{input_classes}}" style="width: 5ch;" value="90"/>
                        <span class="flex-grow-0 ms-1 text-white-50">deg</span>
                    </span>
                </div>
                <div class="d-flex justify-content-between my-2 o_position_row">
                    <we-title>Position</we-title>
                    <span class="d-flex">
                    <span class="me-2">X</span>
                    <span class="o_custom_gradient_input bg-black-50 px-1 d-flex">
                        <input data-name="positionX" type="text" t-attf-class="{{input_classes}}" style="width: 3ch;" value="25"/>
                        <span class="flex-grow-0 ms-1 text-white-50">%</span>
                    </span>
                    <span class="me-2 ms-3">Y</span>
                    <span class="o_custom_gradient_input bg-black-50 px-1 d-flex">
                        <input data-name="positionY" type="text" t-attf-class="{{input_classes}}" style="width: 3ch;" value="25"/>
                        <span class="flex-grow-0 ms-1 text-white-50">%</span>
                    </span>
                    </span>
                </div>
                <div class="d-flex justify-content-between my-2 o_size_row">
                    <we-title>Size</we-title>
                    <span class="d-flex justify-content-between">
                        <we-button data-gradient-size="closest-side" class="d-flex align-items-baseline" title="Extend to the closest side">
                            <svg xmlns="http://www.w3.org/2000/svg" width="16" height="20" viewBox="0 0 16 20" fill="none">
                                <rect x="1.5" y="3.5" width="13" height="13" stroke="#AAAAAD"/>
                                <path d="M3 4H9V8C9 8.55228 8.55228 9 8 9H4C3.44772 9 3 8.55228 3 8V4Z" fill="#8C8C92"/>
                                <path d="M6 11C7.65685 11 9 9.65685 9 8C9 6.34315 7.65685 5 6 5C4.34315 5 3 6.34315 3 8C3 9.65685 4.34315 11 6 11Z" fill="#74747B"/>
                                <path d="M6 10C7.10457 10 8 9.10457 8 8C8 6.89543 7.10457 6 6 6C4.89543 6 4 6.89543 4 8C4 9.10457 4.89543 10 6 10Z" fill="white"/>
                                <rect x="2" y="3" width="12" height="1" fill="white"/>
                            </svg>
                        </we-button>
                        <we-button data-gradient-size="closest-corner" class="d-flex align-items-baseline" title="Extend to the closest corner">
                            <svg xmlns="http://www.w3.org/2000/svg" width="16" height="20" viewBox="0 0 16 20" fill="none">
                                <rect x="1.5" y="3.5" width="13" height="13" stroke="#AAAAAD"/>
                                <path d="M2 4H9V7C9 9.20914 7.20914 11 5 11H2V4Z" fill="#8C8C92"/>
                                <path d="M6 11C7.65685 11 9 9.65685 9 8C9 6.34315 7.65685 5 6 5C4.34315 5 3 6.34315 3 8C3 9.65685 4.34315 11 6 11Z" fill="#74747B"/>
                                <path d="M6 10C7.10457 10 8 9.10457 8 8C8 6.89543 7.10457 6 6 6C4.89543 6 4 6.89543 4 8C4 9.10457 4.89543 10 6 10Z" fill="white"/>
                                <rect x="1" y="3" width="8" height="1" fill="white"/>
                                <rect x="1" y="11" width="8" height="1" transform="rotate(-90 1 11)" fill="white"/>
                            </svg>
                        </we-button>
                        <we-button data-gradient-size="farthest-side" class="d-flex align-items-baseline active" title="Extend to the farthest side">
                            <svg xmlns="http://www.w3.org/2000/svg" width="16" height="20" viewBox="0 0 16 20" fill="none">
                                <rect x="1.5" y="3.5" width="13" height="13" stroke="#AAAAAD"/>
                                <path d="M7 12C10.3137 12 14 10.2091 14 8C14 5.79086 10.3137 4 7 4C3.68629 4 2 5.79086 2 8C2 10.2091 3.68629 12 7 12Z" fill="#8C8C92"/>
                                <path d="M6 11C7.65685 11 9 9.65685 9 8C9 6.34315 7.65685 5 6 5C4.34315 5 3 6.34315 3 8C3 9.65685 4.34315 11 6 11Z" fill="#74747B"/>
                                <path d="M6 10C7.10457 10 8 9.10457 8 8C8 6.89543 7.10457 6 6 6C4.89543 6 4 6.89543 4 8C4 9.10457 4.89543 10 6 10Z" fill="white"/>
                                <rect x="14" y="4" width="1" height="12" fill="white"/>
                            </svg>
                        </we-button>
                        <we-button data-gradient-size="farthest-corner" class="d-flex align-items-baseline" title="Extend to the farthest corner">
                            <svg xmlns="http://www.w3.org/2000/svg" width="16" height="20" viewBox="0 0 16 20" fill="none">
                                <rect x="1.5" y="3.5" width="13" height="13" stroke="#AAAAAD"/>
                                <path d="M2 4H14V10C14 13.3137 11.3137 16 8 16H2V4Z" fill="#8C8C92"/>
                                <path d="M6 11C7.65685 11 9 9.65685 9 8C9 6.34315 7.65685 5 6 5C4.34315 5 3 6.34315 3 8C3 9.65685 4.34315 11 6 11Z" fill="#74747B"/>
                                <path d="M6 10C7.10457 10 8 9.10457 8 8C8 6.89543 7.10457 6 6 6C4.89543 6 4 6.89543 4 8C4 9.10457 4.89543 10 6 10Z" fill="white"/>
                                <rect x="15" y="17" width="7" height="0.999999" transform="rotate(-180 15 17)" fill="white"/>
                                <rect x="15" y="10" width="7" height="1" transform="rotate(90 15 10)" fill="white"/>
                            </svg>
                        </we-button>
                    </span>
                </div>
                <div class="mx-1 o_custom_gradient_scale">
                    <div class="w-100"/>
                </div>
                <div class="w-100 o_slider_multi" role="group"/>
                <we-button class="o_remove_color fa fa-fw fa-trash o_we_link o_we_hover_danger" title="Remove Selected Color" aria-label="Remove Selected Color"/>
            </div>
        </div>
    </colorpicker>
</t>
', false, true, '2026-05-10 01:07:09.335023', '2026-05-10 01:07:09.335023', NULL);
INSERT INTO public.ir_ui_view VALUES (232, 16, NULL, 1, 1, 'web_editor.tests', NULL, 'web_editor.tests', 'qweb', 'web_editor/views/editor.xml', 'primary', '{"en_US": "<t t-name=\"web_editor.tests\">\n    <t t-call=\"web.layout\">\n        <t t-set=\"title\">Odoo Editor Tests</t>\n        <t t-set=\"head\">\n            <t t-call-assets=\"web_editor.assets_tests_styles\" t-js=\"false\"/>\n            <link rel=\"stylesheet\" href=\"/web_editor/static/src/js/editor/odoo-editor/test/lib/mocha.css\"/>\n            <style type=\"text/css\">\n                #mocha-report b.zws, #mocha-report b.tab {\n                    background-color: #833112;\n                    color: white;\n                    border-radius: 3px;\n                    padding: 1px 3px;\n                    font-size: 8px;\n                    vertical-align: middle;\n                }\n                #mocha-report b.tab {\n                    background-color: #14386e;\n                }\n            </style>\n            <script src=\"/web_editor/static/lib/DOMPurify.js\"/>\n            <script src=\"/web_editor/static/src/js/editor/odoo-editor/test/lib/mocha.js\"/>\n            <script src=\"/web_editor/static/src/js/editor/odoo-editor/test/lib/chai.js\"/>\n            <script>mocha.setup(''bdd'').fullTrace()</script>\n            <t t-call-assets=\"web_editor.mocha_tests\"/>\n        </t>\n        <div id=\"mocha\"/>\n        <div id=\"editor-test-container\"/>\n    </t>\n</t>"}', '<?xml version="1.0"?>
<t t-name="web_editor.tests">
    <t t-call="web.layout">
        <t t-set="title">Odoo Editor Tests</t>
        <t t-set="head">
            <t t-call-assets="web_editor.assets_tests_styles" t-js="false"/>
            <link rel="stylesheet" href="/web_editor/static/src/js/editor/odoo-editor/test/lib/mocha.css"/>
            <style type="text/css">
                #mocha-report b.zws, #mocha-report b.tab {
                    background-color: #833112;
                    color: white;
                    border-radius: 3px;
                    padding: 1px 3px;
                    font-size: 8px;
                    vertical-align: middle;
                }
                #mocha-report b.tab {
                    background-color: #14386e;
                }
            </style>
            <script src="/web_editor/static/lib/DOMPurify.js"/>
            <script src="/web_editor/static/src/js/editor/odoo-editor/test/lib/mocha.js"/>
            <script src="/web_editor/static/src/js/editor/odoo-editor/test/lib/chai.js"/>
            <script>mocha.setup(''bdd'').fullTrace()</script>
            <t t-call-assets="web_editor.mocha_tests"/>
        </t>
        <div id="mocha"/>
        <div id="editor-test-container"/>
    </t>
</t>
', false, true, '2026-05-10 01:07:09.335023', '2026-05-10 01:07:09.335023', NULL);
INSERT INTO public.ir_ui_view VALUES (233, 16, NULL, 1, 1, 'snippets', NULL, 'web_editor.snippets', 'qweb', 'web_editor/views/snippets.xml', 'primary', '{"en_US": "<t t-name=\"web_editor.snippets\">\n    <div class=\"o_we_website_top_actions\">\n        <div class=\"o_we_external_history_buttons d-flex\">\n            <button type=\"button\" data-action=\"undo\" class=\"btn btn-secondary fa fa-undo\" disabled=\"true\"/>\n            <button type=\"button\" data-action=\"redo\" class=\"btn btn-secondary fa fa-repeat\" disabled=\"true\"/>\n        </div>\n        <form class=\"ms-auto d-flex\">\n            <!-- Uncomment the following line when the mobile preview will be available. -->\n            <!-- <button type=\"button\" class=\"btn btn-secondary fa fa-mobile\" name=\"mobile\" data-action=\"mobilePreview\"/> -->\n            <button type=\"button\" class=\"btn btn-secondary\" data-action=\"cancel\" title=\"Discard record\" accesskey=\"j\">Discard</button>\n            <button type=\"button\" class=\"btn btn-primary\" data-action=\"save\" title=\"Save record\" accesskey=\"s\">Save</button>\n        </form>\n    </div>\n    <div id=\"snippets_menu\">\n        <button type=\"button\" tabindex=\"1\" class=\"o_we_add_snippet_btn active text-uppercase\" accesskey=\"1\">\n            <span>Blocks</span>\n        </button>\n        <button type=\"button\" tabindex=\"2\" class=\"o_we_customize_snippet_btn text-uppercase\">\n            <span>Customize</span>\n        </button>\n    </div>\n\n    <div class=\"o_snippet_search_filter\">\n        <input type=\"text\" class=\"o_snippet_search_filter_input\" placeholder=\"Search for a block (e.g. numbers, image wall, ...)\"/>\n        <i role=\"button\" class=\"fa fa-times o_snippet_search_filter_reset d-none\"/>\n    </div>\n\n    <div id=\"o_scroll\">\n        <div id=\"snippet_custom\" class=\"o_panel d-none\">\n            <div class=\"o_panel_header\">Custom</div>\n            <div id=\"snippet_custom_body\" class=\"o_panel_body\"/>\n        </div>\n        <t id=\"default_snippets\">\n            <div id=\"snippet_structure\" class=\"o_panel\">\n                <div class=\"o_panel_header\">First Panel</div>\n                <div class=\"o_panel_body\">\n                    <t t-snippet=\"web_editor.s_hr\" string=\"Separator\" t-thumbnail=\"/web_editor/static/src/img/snippets_thumbs/s_hr.svg\"/>\n                </div>\n            </div>\n        </t>\n    </div>\n\n    <div id=\"snippet_options\" class=\"d-none\">\n        <t t-call=\"web_editor.snippet_options\"/>\n    </div>\n</t>"}', '<?xml version="1.0"?>
<t t-name="web_editor.snippets">
    <div class="o_we_website_top_actions">
        <div class="o_we_external_history_buttons d-flex">
            <button type="button" data-action="undo" class="btn btn-secondary fa fa-undo" disabled="true"/>
            <button type="button" data-action="redo" class="btn btn-secondary fa fa-repeat" disabled="true"/>
        </div>
        <form class="ms-auto d-flex">
            <!-- Uncomment the following line when the mobile preview will be available. -->
            <!-- <button type="button" class="btn btn-secondary fa fa-mobile" name="mobile" data-action="mobilePreview"/> -->
            <button type="button" class="btn btn-secondary" data-action="cancel" title="Discard record" accesskey="j">Discard</button>
            <button type="button" class="btn btn-primary" data-action="save" title="Save record" accesskey="s">Save</button>
        </form>
    </div>
    <div id="snippets_menu">
        <button type="button" tabindex="1" class="o_we_add_snippet_btn active text-uppercase" accesskey="1">
            <span>Blocks</span>
        </button>
        <button type="button" tabindex="2" class="o_we_customize_snippet_btn text-uppercase">
            <span>Customize</span>
        </button>
    </div>

    <div class="o_snippet_search_filter">
        <input type="text" class="o_snippet_search_filter_input" placeholder="Search for a block (e.g. numbers, image wall, ...)"/>
        <i role="button" class="fa fa-times o_snippet_search_filter_reset d-none"/>
    </div>

    <div id="o_scroll">
        <div id="snippet_custom" class="o_panel d-none">
            <div class="o_panel_header">Custom</div>
            <div id="snippet_custom_body" class="o_panel_body"/>
        </div>
        <t id="default_snippets">
            <div id="snippet_structure" class="o_panel">
                <div class="o_panel_header">First Panel</div>
                <div class="o_panel_body">
                    <t t-snippet="web_editor.s_hr" string="Separator" t-thumbnail="/web_editor/static/src/img/snippets_thumbs/s_hr.svg"/>
                </div>
            </div>
        </t>
    </div>

    <div id="snippet_options" class="d-none">
        <t t-call="web_editor.snippet_options"/>
    </div>
</t>

', false, true, '2026-05-10 01:07:09.335023', '2026-05-10 01:07:09.335023', NULL);
INSERT INTO public.ir_ui_view VALUES (234, 16, NULL, 1, 1, 'snippet_options_image_optimization_widgets', NULL, 'web_editor.snippet_options_image_optimization_widgets', 'qweb', 'web_editor/views/snippets.xml', 'primary', '{"en_US": "<t t-name=\"web_editor.snippet_options_image_optimization_widgets\">\n    <t t-set=\"filter_label\">Filter</t>\n    <we-select t-att-string=\"filter_label\" t-att-class=\"indent and ''o_we_sublevel_2''\">\n        <we-button data-gl-filter=\"\">None</we-button>\n        <we-button data-gl-filter=\"blur\">Blur</we-button>\n        <we-button data-gl-filter=\"1977\">1977</we-button>\n        <we-button data-gl-filter=\"aden\">Aden</we-button>\n        <we-button data-gl-filter=\"brannan\">Brannan</we-button>\n        <we-button data-gl-filter=\"earlybird\">EarlyBird</we-button>\n        <we-button data-gl-filter=\"inkwell\">Inkwell</we-button>\n        <we-button data-gl-filter=\"maven\">Maven</we-button>\n        <we-button data-gl-filter=\"toaster\">Toaster</we-button>\n        <we-button data-gl-filter=\"walden\">Walden</we-button>\n        <we-button data-gl-filter=\"valencia\">Valencia</we-button>\n        <we-button data-gl-filter=\"xpro\">Xpro</we-button>\n        <we-button data-gl-filter=\"custom\" data-name=\"custom_glfilter_opt\">Custom</we-button>\n    </we-select>\n    <t t-set=\"color_label\">Color</t>\n    <t t-set=\"saturation_label\">Saturation</t>\n    <t t-set=\"contrast_label\">Contrast</t>\n    <t t-set=\"brightness_label\">Brightness</t>\n    <t t-set=\"sepia_label\">Sepia</t>\n    <t t-set=\"blur_label\">Blur</t>\n    <we-row t-att-string=\"color_label\" t-att-class=\"indent and ''o_we_sublevel_3'' or ''o_we_sublevel_1''\">\n        <we-select data-filter-property=\"blend\" data-dependencies=\"custom_glfilter_opt\">\n            <we-button data-custom-filter=\"normal\">Normal</we-button>\n            <we-button data-custom-filter=\"overlay\">overlay</we-button>\n            <we-button data-custom-filter=\"screen\">screen</we-button>\n            <we-button data-custom-filter=\"multiply\">multiply</we-button>\n            <we-button data-custom-filter=\"lighter\">add</we-button>\n            <we-button data-custom-filter=\"exclusion\">exclusion</we-button>\n            <we-button data-custom-filter=\"darken\">darken</we-button>\n            <we-button data-custom-filter=\"lighten\">lighten</we-button>\n        </we-select>\n        <we-colorpicker data-dependencies=\"custom_glfilter_opt\" data-custom-filter=\"\" data-filter-property=\"filterColor\" data-excluded=\"common, theme\"/>\n    </we-row>\n    <we-range t-att-string=\"saturation_label\" t-att-class=\"indent and ''o_we_sublevel_3'' or ''o_we_sublevel_1''\" data-dependencies=\"custom_glfilter_opt\" data-custom-filter=\"\" data-filter-property=\"saturation\" data-min=\"-100\" data-step=\"10\"/>\n    <we-range t-att-string=\"contrast_label\" t-att-class=\"indent and ''o_we_sublevel_3'' or ''o_we_sublevel_1''\" data-dependencies=\"custom_glfilter_opt\" data-custom-filter=\"\" data-filter-property=\"contrast\" data-min=\"-100\" data-step=\"10\"/>\n    <we-range t-att-string=\"brightness_label\" t-att-class=\"indent and ''o_we_sublevel_3'' or ''o_we_sublevel_1''\" data-dependencies=\"custom_glfilter_opt\" data-custom-filter=\"\" data-filter-property=\"brightness\" data-min=\"-100\" data-step=\"10\"/>\n    <we-range t-att-string=\"sepia_label\" t-att-class=\"indent and ''o_we_sublevel_3'' or ''o_we_sublevel_1''\" data-dependencies=\"custom_glfilter_opt\" data-custom-filter=\"\" data-filter-property=\"sepia\" data-step=\"5\"/>\n    <we-range t-att-string=\"blur_label\" t-att-class=\"indent and ''o_we_sublevel_3'' or ''o_we_sublevel_1''\" data-dependencies=\"custom_glfilter_opt\" data-custom-filter=\"\" data-filter-property=\"blur\" data-max=\"2000\" data-step=\"100\"/>\n\n    <t t-set=\"format_label\">Format</t>\n    <we-select t-att-string=\"format_label\" t-att-class=\"indent and ''o_we_sublevel_2''\" data-name=\"format_select_opt\"/>\n\n    <t t-set=\"quality_label\">Quality</t>\n    <we-range t-att-string=\"quality_label\" t-att-class=\"indent and ''o_we_sublevel_2''\" data-name=\"quality_range_opt\" data-set-quality=\"\"/>\n</t>"}', '<?xml version="1.0"?>
<t t-name="web_editor.snippet_options_image_optimization_widgets">
    <t t-set="filter_label">Filter</t>
    <we-select t-att-string="filter_label" t-att-class="indent and ''o_we_sublevel_2''">
        <we-button data-gl-filter="">None</we-button>
        <we-button data-gl-filter="blur">Blur</we-button>
        <we-button data-gl-filter="1977">1977</we-button>
        <we-button data-gl-filter="aden">Aden</we-button>
        <we-button data-gl-filter="brannan">Brannan</we-button>
        <we-button data-gl-filter="earlybird">EarlyBird</we-button>
        <we-button data-gl-filter="inkwell">Inkwell</we-button>
        <we-button data-gl-filter="maven">Maven</we-button>
        <we-button data-gl-filter="toaster">Toaster</we-button>
        <we-button data-gl-filter="walden">Walden</we-button>
        <we-button data-gl-filter="valencia">Valencia</we-button>
        <we-button data-gl-filter="xpro">Xpro</we-button>
        <we-button data-gl-filter="custom" data-name="custom_glfilter_opt">Custom</we-button>
    </we-select>
    <t t-set="color_label">Color</t>
    <t t-set="saturation_label">Saturation</t>
    <t t-set="contrast_label">Contrast</t>
    <t t-set="brightness_label">Brightness</t>
    <t t-set="sepia_label">Sepia</t>
    <t t-set="blur_label">Blur</t>
    <we-row t-att-string="color_label" t-att-class="indent and ''o_we_sublevel_3'' or ''o_we_sublevel_1''">
        <we-select data-filter-property="blend" data-dependencies="custom_glfilter_opt">
            <we-button data-custom-filter="normal">Normal</we-button>
            <we-button data-custom-filter="overlay">overlay</we-button>
            <we-button data-custom-filter="screen">screen</we-button>
            <we-button data-custom-filter="multiply">multiply</we-button>
            <we-button data-custom-filter="lighter">add</we-button>
            <we-button data-custom-filter="exclusion">exclusion</we-button>
            <we-button data-custom-filter="darken">darken</we-button>
            <we-button data-custom-filter="lighten">lighten</we-button>
        </we-select>
        <we-colorpicker data-dependencies="custom_glfilter_opt" data-custom-filter="" data-filter-property="filterColor" data-excluded="common, theme"/>
    </we-row>
    <we-range t-att-string="saturation_label" t-att-class="indent and ''o_we_sublevel_3'' or ''o_we_sublevel_1''" data-dependencies="custom_glfilter_opt" data-custom-filter="" data-filter-property="saturation" data-min="-100" data-step="10"/>
    <we-range t-att-string="contrast_label" t-att-class="indent and ''o_we_sublevel_3'' or ''o_we_sublevel_1''" data-dependencies="custom_glfilter_opt" data-custom-filter="" data-filter-property="contrast" data-min="-100" data-step="10"/>
    <we-range t-att-string="brightness_label" t-att-class="indent and ''o_we_sublevel_3'' or ''o_we_sublevel_1''" data-dependencies="custom_glfilter_opt" data-custom-filter="" data-filter-property="brightness" data-min="-100" data-step="10"/>
    <we-range t-att-string="sepia_label" t-att-class="indent and ''o_we_sublevel_3'' or ''o_we_sublevel_1''" data-dependencies="custom_glfilter_opt" data-custom-filter="" data-filter-property="sepia" data-step="5"/>
    <we-range t-att-string="blur_label" t-att-class="indent and ''o_we_sublevel_3'' or ''o_we_sublevel_1''" data-dependencies="custom_glfilter_opt" data-custom-filter="" data-filter-property="blur" data-max="2000" data-step="100"/>

    <t t-set="format_label">Format</t>
    <we-select t-att-string="format_label" t-att-class="indent and ''o_we_sublevel_2''" data-name="format_select_opt"/>

    <t t-set="quality_label">Quality</t>
    <we-range t-att-string="quality_label" t-att-class="indent and ''o_we_sublevel_2''" data-name="quality_range_opt" data-set-quality=""/>
</t>

