INSERT INTO public.ir_ui_view VALUES (239, 16, 223, 1, 1, 'res.config.settings.view.form.inherit.web.unsplash', 'res.config.settings', NULL, 'form', 'web_unsplash/views/res_config_settings_view.xml', 'extension', '{"en_US": "<div id=\"web_unsplash_warning\" position=\"replace\">\n                <div invisible=\"not module_web_unsplash\">\n                    <div class=\"content-group mt16\">\n                        <label for=\"unsplash_access_key\" class=\"o_light_label mr8\"/>\n                        <field name=\"unsplash_access_key\"/>\n                    </div>\n                    <div class=\"content-group\">\n                        <label for=\"unsplash_app_id\" class=\"o_light_label mr8\"/>\n                        <field name=\"unsplash_app_id\"/>\n                    </div>\n                    <div>\n                        <a href=\"https://www.odoo.com/documentation/17.0/applications/websites/website/optimize/unsplash.html#generate-an-unsplash-access-key\" class=\"oe_link\" target=\"_blank\">\n                            <i class=\"oi oi-arrow-right\"/> Generate an Access Key\n                        </a>\n                    </div>\n                </div>\n            </div>"}', '<?xml version="1.0"?>
<div id="web_unsplash_warning" position="replace">
                <div invisible="not module_web_unsplash">
                    <div class="content-group mt16">
                        <label for="unsplash_access_key" class="o_light_label mr8"/>
                        <field name="unsplash_access_key"/>
                    </div>
                    <div class="content-group">
                        <label for="unsplash_app_id" class="o_light_label mr8"/>
                        <field name="unsplash_app_id"/>
                    </div>
                    <div>
                        <a href="https://www.odoo.com/documentation/17.0/applications/websites/website/optimize/unsplash.html#generate-an-unsplash-access-key" class="oe_link" target="_blank">
                            <i class="oi oi-arrow-right"/> Generate an Access Key
                        </a>
                    </div>
                </div>
            </div>
        ', false, true, '2026-05-10 01:07:09.804979', '2026-05-10 01:07:09.804979', NULL);
INSERT INTO public.ir_ui_view VALUES (240, 16, NULL, 1, 1, 'uom.uom.tree', 'uom.uom', NULL, 'tree', 'uom/views/uom_uom_views.xml', 'primary', '{"en_US": "<tree string=\"Units of Measure\" create=\"false\">\n                <field name=\"name\"/>\n                <field name=\"category_id\"/>\n                <field name=\"uom_type\"/>\n            </tree>"}', '<?xml version="1.0"?>
<tree string="Units of Measure" create="false">
                <field name="name"/>
                <field name="category_id"/>
                <field name="uom_type"/>
            </tree>
        ', false, true, '2026-05-10 01:11:41.799394', '2026-05-10 01:11:41.799394', NULL);
INSERT INTO public.ir_ui_view VALUES (241, 16, NULL, 1, 1, 'uom.uom.form', 'uom.uom', NULL, 'form', 'uom/views/uom_uom_views.xml', 'primary', '{"en_US": "<form string=\"Units of Measure\">\n                <sheet>\n                    <group>\n                         <group name=\"uom_details\">\n                             <field name=\"name\"/>\n                             <field name=\"category_id\"/>\n                             <field name=\"uom_type\" readonly=\"1\"/>\n                             <label for=\"factor\" invisible=\"uom_type != ''smaller''\"/>\n                            <div invisible=\"uom_type != ''smaller''\">\n                                <field name=\"factor\" digits=\"[42,5]\" readonly=\"uom_type == ''bigger''\"/>\n                                <span class=\"oe_grey oe_inline\">\n                                    e.g: 1*(reference unit)=ratio*(this unit)\n                                </span>\n                            </div>\n                            <label for=\"factor_inv\" invisible=\"uom_type != ''bigger''\"/>\n                            <div invisible=\"uom_type != ''bigger''\">\n                                <field name=\"factor_inv\" digits=\"[42,5]\" readonly=\"uom_type != ''bigger''\"/>\n                                <span class=\"oe_grey oe_inline\">\n                                    e.g: 1*(this unit)=ratio*(reference unit)\n                                </span>\n                            </div>\n                         </group>\n                         <group name=\"active_rounding\">\n                             <field name=\"active\" widget=\"boolean_toggle\"/>\n                             <field name=\"rounding\" digits=\"[42, 5]\"/>\n                         </group>\n                     </group>\n                </sheet>\n            </form>"}', '<?xml version="1.0"?>
<form string="Units of Measure">
                <sheet>
                    <group>
                         <group name="uom_details">
                             <field name="name"/>
                             <field name="category_id"/>
                             <field name="uom_type" readonly="1"/>
                             <label for="factor" invisible="uom_type != ''smaller''"/>
                            <div invisible="uom_type != ''smaller''">
                                <field name="factor" digits="[42,5]" readonly="uom_type == ''bigger''"/>
                                <span class="oe_grey oe_inline">
                                    e.g: 1*(reference unit)=ratio*(this unit)
                                </span>
                            </div>
                            <label for="factor_inv" invisible="uom_type != ''bigger''"/>
                            <div invisible="uom_type != ''bigger''">
                                <field name="factor_inv" digits="[42,5]" readonly="uom_type != ''bigger''"/>
                                <span class="oe_grey oe_inline">
                                    e.g: 1*(this unit)=ratio*(reference unit)
                                </span>
                            </div>
                         </group>
                         <group name="active_rounding">
                             <field name="active" widget="boolean_toggle"/>
                             <field name="rounding" digits="[42, 5]"/>
                         </group>
                     </group>
                </sheet>
            </form>
        ', false, true, '2026-05-10 01:11:41.799394', '2026-05-10 01:11:41.799394', NULL);
INSERT INTO public.ir_ui_view VALUES (242, 16, NULL, 1, 1, 'uom.uom.view.search', 'uom.uom', NULL, 'search', 'uom/views/uom_uom_views.xml', 'primary', '{"en_US": "<search string=\"Search UOM\">\n                <field name=\"name\"/>\n                <separator/>\n                <filter string=\"Archived\" name=\"inactive\" domain=\"[(''active'', ''='', False)]\"/>\n                <group string=\"Group By\">\n                  <filter string=\"Category\" name=\"group_by_category\" context=\"{''group_by'': ''category_id''}\"/>\n                </group>\n            </search>"}', '<?xml version="1.0"?>
<search string="Search UOM">
                <field name="name"/>
                <separator/>
                <filter string="Archived" name="inactive" domain="[(''active'', ''='', False)]"/>
                <group string="Group By">
                  <filter string="Category" name="group_by_category" context="{''group_by'': ''category_id''}"/>
                </group>
            </search>
        ', false, true, '2026-05-10 01:11:41.799394', '2026-05-10 01:11:41.799394', NULL);
INSERT INTO public.ir_ui_view VALUES (243, 16, NULL, 1, 1, 'uom.category.form', 'uom.category', NULL, 'form', 'uom/views/uom_uom_views.xml', 'primary', '{"en_US": "<form string=\"Units of Measure categories\">\n                <sheet>\n                    <group>\n                        <field name=\"name\"/>\n                        <field name=\"reference_uom_id\" invisible=\"1\"/>\n                    </group>\n                    <notebook>\n                        <page string=\"Units of Measure\" name=\"uom_lines\">\n                            <field name=\"uom_ids\" force_save=\"1\" context=\"{''default_uom_type'': ''smaller'', ''default_category_id'': id}\">\n                                <tree editable=\"bottom\">\n                                    <field name=\"name\" decoration-bf=\"uom_type == ''reference''\"/>\n                                    <field name=\"uom_type\" decoration-bf=\"uom_type == ''reference''\"/>\n                                    <field name=\"factor\" column_invisible=\"True\"/>\n                                    <field name=\"factor_inv\" column_invisible=\"True\"/>\n                                    <field name=\"ratio\" string=\"Ratio\" readonly=\"uom_type == ''reference''\" digits=\"[42,5]\"/>\n                                    <field name=\"active\"/>\n                                    <field name=\"rounding\" digits=\"[42, 5]\"/>\n                                </tree>\n                            </field>\n                        </page>\n                    </notebook>\n                </sheet>\n            </form>"}', '<?xml version="1.0"?>
<form string="Units of Measure categories">
                <sheet>
                    <group>
                        <field name="name"/>
                        <field name="reference_uom_id" invisible="1"/>
                    </group>
                    <notebook>
                        <page string="Units of Measure" name="uom_lines">
                            <field name="uom_ids" force_save="1" context="{''default_uom_type'': ''smaller'', ''default_category_id'': id}">
                                <tree editable="bottom">
                                    <field name="name" decoration-bf="uom_type == ''reference''"/>
                                    <field name="uom_type" decoration-bf="uom_type == ''reference''"/>
                                    <field name="factor" column_invisible="True"/>
                                    <field name="factor_inv" column_invisible="True"/>
                                    <field name="ratio" string="Ratio" readonly="uom_type == ''reference''" digits="[42,5]"/>
                                    <field name="active"/>
                                    <field name="rounding" digits="[42, 5]"/>
                                </tree>
                            </field>
                        </page>
                    </notebook>
                </sheet>
            </form>
        ', false, true, '2026-05-10 01:11:41.799394', '2026-05-10 01:11:41.799394', NULL);
INSERT INTO public.ir_ui_view VALUES (244, 16, NULL, 1, 1, 'uom.category.tree', 'uom.category', NULL, 'tree', 'uom/views/uom_uom_views.xml', 'primary', '{"en_US": "<tree string=\"Units of Measure categories\">\n                <field name=\"name\"/>\n                <field name=\"uom_ids\" widget=\"many2many_tags\" options=\"{''color_field'': ''color''}\"/>\n            </tree>"}', '<?xml version="1.0"?>
<tree string="Units of Measure categories">
