            </tree>
        ', false, true, '2026-05-10 01:11:41.799394', '2026-05-10 01:11:41.799394', NULL);
INSERT INTO public.ir_ui_view VALUES (245, 16, NULL, 1, 1, 'uom.category.view.search', 'uom.category', NULL, 'search', 'uom/views/uom_uom_views.xml', 'primary', '{"en_US": "<search string=\"Search UoM Category\">\n                <field name=\"name\"/>\n                <field name=\"uom_ids\"/>\n            </search>"}', '<?xml version="1.0"?>
