INSERT INTO public.ir_ui_view VALUES (246, 16, NULL, 1, 1, 'HTTP Error', NULL, 'http_routing.http_error', 'qweb', 'http_routing/views/http_routing_template.xml', 'primary', '{"en_US": "<t name=\"HTTP Error\" t-name=\"http_routing.http_error\">\n        <t t-call=\"web.frontend_layout\">\n            <div id=\"wrap\">\n                <div class=\"oe_structure\">\n                    <h1 class=\"container mt32\"><t t-esc=\"status_code\"/>: <t t-esc=\"status_message\"/></h1>\n                </div>\n                <t t-if=\"editable or debug\">\n                    <t t-call=\"http_routing.http_error_debug\"/>\n                </t>\n            </div>\n        </t>\n    </t>"}', '<?xml version="1.0"?>
<t name="HTTP Error" t-name="http_routing.http_error">
        <t t-call="web.frontend_layout">
            <div id="wrap">
                <div class="oe_structure">
                    <h1 class="container mt32"><t t-esc="status_code"/>: <t t-esc="status_message"/></h1>
                </div>
                <t t-if="editable or debug">
                    <t t-call="http_routing.http_error_debug"/>
                </t>
            </div>
        </t>
    </t>

    ', false, true, '2026-05-10 01:11:42.59324', '2026-05-10 01:11:42.59324', NULL);
INSERT INTO public.ir_ui_view VALUES (247, 16, NULL, 1, 1, 'error_message', NULL, 'http_routing.error_message', 'qweb', 'http_routing/views/http_routing_template.xml', 'primary', '{"en_US": "<t t-name=\"http_routing.error_message\">\n        <p t-if=\"error_message\">\n            <strong>Error message:</strong>\n            <pre t-esc=\"error_message\"/>\n        </p>\n    </t>"}', '<?xml version="1.0"?>
<t t-name="http_routing.error_message">
        <p t-if="error_message">
            <strong>Error message:</strong>
            <pre t-esc="error_message"/>
        </p>
    </t>

    ', false, true, '2026-05-10 01:11:42.59324', '2026-05-10 01:11:42.59324', NULL);
INSERT INTO public.ir_ui_view VALUES (248, 16, NULL, 1, 1, 'http_error_debug', NULL, 'http_routing.http_error_debug', 'qweb', 'http_routing/views/http_routing_template.xml', 'primary', '{"en_US": "<t t-name=\"http_routing.http_error_debug\">\n        <div class=\"container accordion mb32 mt32\" id=\"debug_infos\">\n            <div class=\"card\" t-if=\"error_message\">\n                <h4 class=\"card-header\">\n                    <a data-bs-toggle=\"collapse\" href=\"#error_main\">Error</a>\n                </h4>\n                <div id=\"error_main\" class=\"collapse show\">\n                    <div class=\"card-body\">\n                        <t t-call=\"http_routing.error_message\"/>\n                    </div>\n                </div>\n            </div>\n            <div class=\"card\" t-if=\"qweb_exception\">\n                <h4 class=\"card-header\">\n                    <a data-bs-toggle=\"collapse\" href=\"#error_qweb\">QWeb</a>\n                </h4>\n                <div id=\"error_qweb\" class=\"collapse show\">\n                    <div class=\"card-body\">\n                        <p>\n                            <strong>Error message:</strong>\n                            <pre t-esc=\"exception\"/>\n                        </p>\n                        <p>\n                            The error occurred while rendering the template <code t-esc=\"qweb_exception.name\"/> \n                            <t t-if=\"qweb_exception.html\">and evaluating the following expression: <code t-esc=\"qweb_exception.html\"/></t>\n                        </p>\n                    </div>\n                </div>\n            </div>\n            <div class=\"card\" t-if=\"traceback\">\n                <h4 class=\"card-header\">\n                    <a data-bs-toggle=\"collapse\" href=\"#error_traceback\">Traceback</a>\n                </h4>\n                <div id=\"error_traceback\" t-attf-class=\"collapse #{not error_message and not qweb_exception and ''show''}\">\n                    <div class=\"card-body\">\n                        <pre id=\"exception_traceback\" t-esc=\"traceback\"/>\n                    </div>\n                </div>\n            </div>\n        </div>\n    </t>"}', '<?xml version="1.0"?>
<t t-name="http_routing.http_error_debug">
        <div class="container accordion mb32 mt32" id="debug_infos">
            <div class="card" t-if="error_message">
                <h4 class="card-header">
                    <a data-bs-toggle="collapse" href="#error_main">Error</a>
                </h4>
                <div id="error_main" class="collapse show">
                    <div class="card-body">
                        <t t-call="http_routing.error_message"/>
                    </div>
                </div>
            </div>
            <div class="card" t-if="qweb_exception">
                <h4 class="card-header">
                    <a data-bs-toggle="collapse" href="#error_qweb">QWeb</a>
                </h4>
                <div id="error_qweb" class="collapse show">
                    <div class="card-body">
                        <p>
                            <strong>Error message:</strong>
                            <pre t-esc="exception"/>
                        </p>
                        <p>
                            The error occurred while rendering the template <code t-esc="qweb_exception.name"/> 
                            <t t-if="qweb_exception.html">and evaluating the following expression: <code t-esc="qweb_exception.html"/></t>
                        </p>
                    </div>
                </div>
            </div>
            <div class="card" t-if="traceback">
                <h4 class="card-header">
                    <a data-bs-toggle="collapse" href="#error_traceback">Traceback</a>
                </h4>
                <div id="error_traceback" t-attf-class="collapse #{not error_message and not qweb_exception and ''show''}">
                    <div class="card-body">
                        <pre id="exception_traceback" t-esc="traceback"/>
                    </div>
                </div>
            </div>
        </div>
    </t>

    ', false, true, '2026-05-10 01:11:42.59324', '2026-05-10 01:11:42.59324', NULL);
INSERT INTO public.ir_ui_view VALUES (249, 16, NULL, 1, 1, '400', NULL, 'http_routing.400', 'qweb', 'http_routing/views/http_routing_template.xml', 'primary', '{"en_US": "<t t-name=\"http_routing.400\">\n        <t t-call=\"web.frontend_layout\">\n            <div id=\"wrap\">\n                <div class=\"container\">\n                    <h1 class=\"mt-5\">Oops! Something went wrong.</h1>\n                    <p>Take a look at the error message below.</p>\n                </div>\n                <t t-if=\"editable or debug\">\n                    <t t-call=\"http_routing.http_error_debug\"/>\n                </t>\n                <t t-else=\"\">\n                    <div class=\"container\">\n                        <t t-call=\"http_routing.error_message\"/>\n                    </div>\n                </t>\n        </div>\n        </t>\n    </t>"}', '<?xml version="1.0"?>
<t t-name="http_routing.400">
        <t t-call="web.frontend_layout">
            <div id="wrap">
                <div class="container">
                    <h1 class="mt-5">Oops! Something went wrong.</h1>
                    <p>Take a look at the error message below.</p>
                </div>
                <t t-if="editable or debug">
                    <t t-call="http_routing.http_error_debug"/>
                </t>
                <t t-else="">
                    <div class="container">
                        <t t-call="http_routing.error_message"/>
                    </div>
                </t>
        </div>
        </t>
    </t>

    ', false, true, '2026-05-10 01:11:42.59324', '2026-05-10 01:11:42.59324', NULL);
INSERT INTO public.ir_ui_view VALUES (250, 16, NULL, 1, 1, '403', NULL, 'http_routing.403', 'qweb', 'http_routing/views/http_routing_template.xml', 'primary', '{"en_US": "<t t-name=\"http_routing.403\">\n        <t t-call=\"web.frontend_layout\">\n            <div id=\"wrap\">\n                <div class=\"container\">\n                    <h1 class=\"mt-5\">403: Forbidden</h1>\n                    <p>The page you were looking for could not be authorized.</p>\n                </div>\n                    <t t-if=\"editable or debug\">\n                        <t t-call=\"http_routing.http_error_debug\"/>\n                    </t>\n                    <t t-else=\"\">\n                        <div class=\"container\">\n                            <t t-call=\"http_routing.error_message\"/>\n                        </div>\n                    </t>\n            </div>\n        </t>\n    </t>"}', '<?xml version="1.0"?>
<t t-name="http_routing.403">
        <t t-call="web.frontend_layout">
            <div id="wrap">
                <div class="container">
                    <h1 class="mt-5">403: Forbidden</h1>
                    <p>The page you were looking for could not be authorized.</p>
                </div>
                    <t t-if="editable or debug">
                        <t t-call="http_routing.http_error_debug"/>
                    </t>
                    <t t-else="">
                        <div class="container">
                            <t t-call="http_routing.error_message"/>
                        </div>
                    </t>
            </div>
        </t>
    </t>

    ', false, true, '2026-05-10 01:11:42.59324', '2026-05-10 01:11:42.59324', NULL);
INSERT INTO public.ir_ui_view VALUES (251, 16, NULL, 1, 1, 'Page Not Found', NULL, 'http_routing.404', 'qweb', 'http_routing/views/http_routing_template.xml', 'primary', '{"en_US": "<t name=\"Page Not Found\" t-name=\"http_routing.404\">\n        <t t-call=\"web.frontend_layout\">\n            <div id=\"wrap\">\n                <t t-out=\"0\"/>\n                <div class=\"oe_structure oe_empty\">\n                    <section class=\"s_text_image pt104 pb104\" data-snippet=\"s_image_text\" data-name=\"Image - Text\">\n                        <div class=\"container\">\n                            <div class=\"row align-items-center\">\n                                <div class=\"col-lg-4 pb32\">\n                                    <img class=\"img img-fluid mx-auto\" src=\"/web_editor/shape/http_routing/404.svg?c2=o-color-2\"/>\n                                </div>\n                                <div class=\"col-lg-8 text-lg-start text-center my-auto\">\n                                    <h1 class=\"visually-hidden\">Error 404</h1>\n                                    <h2>We couldn''t find the page you''re looking for!</h2>\n                                    <p/>\n                                    <p><b>Don''t panic.</b> If you think it''s our mistake, please send us a message on <a href=\"/contactus\">this page</a>.</p>\n                                </div>\n                                <div class=\"col-lg-12\">\n                                    <div class=\"s_hr pt32 pb48\" data-snippet=\"s_hr\" data-name=\"Separator\">\n                                        <hr class=\"w-100 mx-auto\" style=\"border-top-width: 1px; border-top-style: solid; border-top-color: var(--400);\"/>\n                                    </div>\n                                </div>\n                                <div class=\"col-lg-12\">\n                                    <p class=\"text-center\">Maybe you were looking for one of these <b>popular pages?</b></p>\n                                    <ul class=\"list-inline text-center\">\n                                        <li class=\"list-inline-item mb-2\"><a href=\"/\" class=\"btn btn-primary\">Home</a></li>\n                                    </ul>\n                                </div>\n                            </div>\n                        </div>\n                    </section>\n                </div>\n            </div>\n        </t>\n    </t>"}', '<?xml version="1.0"?>
<t name="Page Not Found" t-name="http_routing.404">
        <t t-call="web.frontend_layout">
            <div id="wrap">
                <t t-out="0"/>
                <div class="oe_structure oe_empty">
                    <section class="s_text_image pt104 pb104" data-snippet="s_image_text" data-name="Image - Text">
                        <div class="container">
                            <div class="row align-items-center">
                                <div class="col-lg-4 pb32">
                                    <img class="img img-fluid mx-auto" src="/web_editor/shape/http_routing/404.svg?c2=o-color-2"/>
                                </div>
                                <div class="col-lg-8 text-lg-start text-center my-auto">
                                    <h1 class="visually-hidden">Error 404</h1>
                                    <h2>We couldn''t find the page you''re looking for!</h2>
                                    <p/>
                                    <p><b>Don''t panic.</b> If you think it''s our mistake, please send us a message on <a href="/contactus">this page</a>.</p>
                                </div>
                                <div class="col-lg-12">
                                    <div class="s_hr pt32 pb48" data-snippet="s_hr" data-name="Separator">
                                        <hr class="w-100 mx-auto" style="border-top-width: 1px; border-top-style: solid; border-top-color: var(--400);"/>
                                    </div>
                                </div>
                                <div class="col-lg-12">
                                    <p class="text-center">Maybe you were looking for one of these <b>popular pages?</b></p>
                                    <ul class="list-inline text-center">
                                        <li class="list-inline-item mb-2"><a href="/" class="btn btn-primary">Home</a></li>
                                    </ul>
                                </div>
                            </div>
                        </div>
                    </section>
                </div>
            </div>
        </t>
    </t>

    ', false, true, '2026-05-10 01:11:42.59324', '2026-05-10 01:11:42.59324', NULL);
INSERT INTO public.ir_ui_view VALUES (252, 16, NULL, 1, 1, '500', NULL, 'http_routing.500', 'qweb', 'http_routing/views/http_routing_template.xml', 'primary', '{"en_US": "<t t-name=\"http_routing.500\">\n        <!-- !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!! -->\n        <!-- This template should not use any variable except those provided by http_routing.ir_http._handle_exception  -->\n        <!--    no request.crsf_token, no theme style, no assets, ... cursor can be broken during rendering !      -->\n        <!--    see test_05_reset_specific_view_controller_broken_request                                          -->\n        <!-- !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!! -->\n        <html>\n            <head>\n                <title t-esc=\"status_message\">Internal Server Error</title>\n\n                <link rel=\"stylesheet\" href=\"/web/static/lib/bootstrap/dist/css/bootstrap.css\"/>\n                <script src=\"/web/static/lib/jquery/jquery.js\" type=\"text/javascript\"/>\n                <script type=\"text/javascript\" src=\"/web/static/lib/bootstrap/js/dist/dom/data.js\"/>\n                <script type=\"text/javascript\" src=\"/web/static/lib/bootstrap/js/dist/dom/event-handler.js\"/>\n                <script type=\"text/javascript\" src=\"/web/static/lib/bootstrap/js/dist/dom/manipulator.js\"/>\n                <script type=\"text/javascript\" src=\"/web/static/lib/bootstrap/js/dist/dom/selector-engine.js\"/>\n                <script type=\"text/javascript\" src=\"/web/static/lib/bootstrap/js/dist/base-component.js\"/>\n                <script type=\"text/javascript\" src=\"/web/static/lib/bootstrap/js/dist/collapse.js\"/>\n                <style>\n                    html {\n                        font-size: 14px;\n                    }\n                </style>\n            </head>\n            <body>\n                <div id=\"wrapwrap\">\n                    <header>\n                        <div class=\"navbar navbar-expand-md navbar-light bg-light\">\n                            <div class=\"container\">\n                                <div class=\"collapse navbar-collapse navbar-top-collapse\">\n                                    <ul class=\"navbar-nav ms-auto\" id=\"top_menu\">\n                                        <li class=\"nav-item\"><a href=\"/\" class=\"nav-link\">Home</a></li>\n                                        <li class=\"nav-item\"><a href=\"javascript: window.history.back()\" class=\"nav-link\">Back</a></li>\n                                    </ul>\n                                </div>\n                            </div>\n                        </div>\n                    </header>\n                    <main>\n                        <div id=\"error_message\" class=\"oe_structure\">\n                            <h2 class=\"container mt32\"><t t-esc=\"status_code\"/>: <t t-esc=\"status_message\"/></h2>\n                        </div>\n\n                        <t t-if=\"editable or debug\">\n                            <t t-call=\"http_routing.http_error_debug\"/>\n                        </t>\n                    </main>\n                </div>\n            </body>\n        </html>\n    </t>"}', '<?xml version="1.0"?>
<t t-name="http_routing.500">
        <!-- !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!! -->
        <!-- This template should not use any variable except those provided by http_routing.ir_http._handle_exception  -->
        <!--    no request.crsf_token, no theme style, no assets, ... cursor can be broken during rendering !      -->
        <!--    see test_05_reset_specific_view_controller_broken_request                                          -->
        <!-- !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!! -->
        <html>
            <head>
                <title t-esc="status_message">Internal Server Error</title>

                <link rel="stylesheet" href="/web/static/lib/bootstrap/dist/css/bootstrap.css"/>
                <script src="/web/static/lib/jquery/jquery.js" type="text/javascript"/>
                <script type="text/javascript" src="/web/static/lib/bootstrap/js/dist/dom/data.js"/>
                <script type="text/javascript" src="/web/static/lib/bootstrap/js/dist/dom/event-handler.js"/>
                <script type="text/javascript" src="/web/static/lib/bootstrap/js/dist/dom/manipulator.js"/>
                <script type="text/javascript" src="/web/static/lib/bootstrap/js/dist/dom/selector-engine.js"/>
                <script type="text/javascript" src="/web/static/lib/bootstrap/js/dist/base-component.js"/>
                <script type="text/javascript" src="/web/static/lib/bootstrap/js/dist/collapse.js"/>
                <style>
                    html {
                        font-size: 14px;
                    }
                </style>
            </head>
            <body>
                <div id="wrapwrap">
                    <header>
                        <div class="navbar navbar-expand-md navbar-light bg-light">
                            <div class="container">
                                <div class="collapse navbar-collapse navbar-top-collapse">
                                    <ul class="navbar-nav ms-auto" id="top_menu">
                                        <li class="nav-item"><a href="/" class="nav-link">Home</a></li>
                                        <li class="nav-item"><a href="javascript: window.history.back()" class="nav-link">Back</a></li>
                                    </ul>
                                </div>
                            </div>
                        </div>
                    </header>
                    <main>
                        <div id="error_message" class="oe_structure">
                            <h2 class="container mt32"><t t-esc="status_code"/>: <t t-esc="status_message"/></h2>
                        </div>

                        <t t-if="editable or debug">
                            <t t-call="http_routing.http_error_debug"/>
                        </t>
                    </main>
                </div>
            </body>
        </html>
    </t>
', false, true, '2026-05-10 01:11:42.59324', '2026-05-10 01:11:42.59324', NULL);
INSERT INTO public.ir_ui_view VALUES (253, 16, 118, 1, 1, 'res.lang.form.http_routing.inherit', 'res.lang', NULL, 'form', 'http_routing/views/res_lang_views.xml', 'extension', '{"en_US": "<field name=\"url_code\" position=\"attributes\">\n                <attribute name=\"invisible\">0</attribute>\n            </field>"}', '<?xml version="1.0"?>
