INSERT INTO public.ir_ui_view VALUES (255, 16, NULL, 1, 1, 'onboarding_panel', NULL, 'onboarding.onboarding_panel', 'qweb', 'onboarding/views/onboarding_templates.xml', 'primary', '{"en_US": "<t t-name=\"onboarding.onboarding_panel\">\n        <t t-call=\"onboarding.onboarding_container\">\n            <t t-foreach=\"steps\" t-as=\"step\">\n                <t t-call=\"onboarding.onboarding_step\">\n                    <t t-set=\"title\" t-value=\"step.title\"/>\n                    <t t-set=\"description\" t-value=\"step.description\"/>\n                    <t t-set=\"done_icon\" t-value=\"step.done_icon\"/>\n                    <t t-set=\"btn_text\" t-value=\"step.button_text\"/>\n                    <t t-set=\"done_text\" t-value=\"step.done_text\"/>\n                    <t t-set=\"image\" t-value=\"''/web/image/onboarding.onboarding.step/''+str(step.id)+''/step_image''\"/>\n                    <t t-set=\"alt\" t-value=\"step.step_image_alt\"/>\n                    <!-- Model/method used by JS implementation of banners for each step-->\n                    <t t-set=\"method\" t-value=\"step.panel_step_open_action_name\"/>\n                    <t t-set=\"model\">onboarding.onboarding.step</t>\n                    <!-- to mimic first implementation of onboarding, the ''state'' queried holds\n                    a rendering state for all steps. See _get_and_update_onboarding_state -->\n                    <t t-set=\"state\" t-value=\"state.get(step.id)\"/>\n                </t>\n            </t>\n        </t>\n    </t>"}', '<?xml version="1.0"?>
<t t-name="onboarding.onboarding_panel">
        <t t-call="onboarding.onboarding_container">
            <t t-foreach="steps" t-as="step">
                <t t-call="onboarding.onboarding_step">
                    <t t-set="title" t-value="step.title"/>
                    <t t-set="description" t-value="step.description"/>
                    <t t-set="done_icon" t-value="step.done_icon"/>
                    <t t-set="btn_text" t-value="step.button_text"/>
                    <t t-set="done_text" t-value="step.done_text"/>
                    <t t-set="image" t-value="''/web/image/onboarding.onboarding.step/''+str(step.id)+''/step_image''"/>
                    <t t-set="alt" t-value="step.step_image_alt"/>
                    <!-- Model/method used by JS implementation of banners for each step-->
                    <t t-set="method" t-value="step.panel_step_open_action_name"/>
                    <t t-set="model">onboarding.onboarding.step</t>
                    <!-- to mimic first implementation of onboarding, the ''state'' queried holds
                    a rendering state for all steps. See _get_and_update_onboarding_state -->
                    <t t-set="state" t-value="state.get(step.id)"/>
                </t>
            </t>
        </t>
    </t>

    ', false, true, '2026-05-10 01:11:42.65887', '2026-05-10 01:11:42.65887', NULL);
INSERT INTO public.ir_ui_view VALUES (287, 16, NULL, 1, 1, 'utm.tag.view.tree', 'utm.tag', NULL, 'tree', 'utm/views/utm_tag_views.xml', 'primary', '{"en_US": "<tree string=\"Campaign Tags\" editable=\"top\">\n                <field name=\"name\"/>\n            </tree>"}', '<?xml version="1.0"?>
