INSERT INTO public.ir_ui_view VALUES (256, 16, NULL, 1, 1, 'onboarding_container', NULL, 'onboarding.onboarding_container', 'qweb', 'onboarding/views/onboarding_templates.xml', 'primary', '{"en_US": "<t t-name=\"onboarding.onboarding_container\">\n        <div class=\"modal o_onboarding_modal o_technical_modal\" tabindex=\"-1\" role=\"dialog\">\n            <div class=\"modal-dialog\" role=\"document\">\n                <div class=\"modal-content\">\n                    <div class=\"modal-header\">\n                        <h5 class=\"modal-title\">Hide Onboarding Tips</h5>\n                        <button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"modal\" aria-label=\"Close\"/>\n                    </div>\n                    <div class=\"modal-body\">\n                        <p>Are you sure you want to hide these configuration steps?</p>\n                    </div>\n                    <div class=\"modal-footer justify-content-start\">\n                        <a type=\"action\" class=\"btn btn-primary me-1\" data-bs-dismiss=\"modal\" data-o-hide-banner=\"true\" t-att-data-model=\"close_model\" t-att-data-method=\"close_method\">\n                            Get them out of my sight!\n                        </a>\n                        <button type=\"button\" class=\"btn btn-secondary\" data-bs-dismiss=\"modal\">Cancel</button>\n                    </div>\n                </div>\n            </div>\n        </div>\n        <div class=\"o_onboarding_main position-relative border-bottom overflow-hidden\">\n            <div class=\"o_onboarding_wrap py-3 py-lg-4\">\n                <a href=\"#\" data-bs-toggle=\"modal\" data-bs-target=\".o_onboarding_modal\" class=\"o_onboarding_btn_close position-absolute top-0 end-0 py-2 px-3 h2 z-index-1\" title=\"Close the onboarding panel\"><i class=\"oi oi-close\"/></a>\n                <div class=\"o_onboarding_steps d-flex\" t-out=\"0\"/>\n\n                <div t-if=\"state.get(''onboarding_state'') == ''just_done''\" t-att-state=\"state.get(''onboarding_state'')\" class=\"o_onboarding_completed_message position-absolute end-0 start-0 border-bottom py-4 bg-white d-flex align-items-center justify-content-center\">\n                    <span class=\"h3 m-0\">\n                        <i class=\"fa fa-check text-success me-3\"/>\n                        <t t-if=\"text_completed\" t-out=\"text_completed\"/>\n                    </span>\n                    <a type=\"action\" class=\"btn btn-primary ms-4\" t-att-data-model=\"close_model\" t-att-data-method=\"close_method\">\n                        Close Panel\n                    </a>\n                </div>\n            </div>\n        </div>\n    </t>"}', '<?xml version="1.0"?>
<t t-name="onboarding.onboarding_container">
        <div class="modal o_onboarding_modal o_technical_modal" tabindex="-1" role="dialog">
            <div class="modal-dialog" role="document">
                <div class="modal-content">
                    <div class="modal-header">
                        <h5 class="modal-title">Hide Onboarding Tips</h5>
                        <button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close"/>
                    </div>
                    <div class="modal-body">
                        <p>Are you sure you want to hide these configuration steps?</p>
                    </div>
                    <div class="modal-footer justify-content-start">
                        <a type="action" class="btn btn-primary me-1" data-bs-dismiss="modal" data-o-hide-banner="true" t-att-data-model="close_model" t-att-data-method="close_method">
                            Get them out of my sight!
                        </a>
                        <button type="button" class="btn btn-secondary" data-bs-dismiss="modal">Cancel</button>
                    </div>
                </div>
            </div>
        </div>
        <div class="o_onboarding_main position-relative border-bottom overflow-hidden">
            <div class="o_onboarding_wrap py-3 py-lg-4">
                <a href="#" data-bs-toggle="modal" data-bs-target=".o_onboarding_modal" class="o_onboarding_btn_close position-absolute top-0 end-0 py-2 px-3 h2 z-index-1" title="Close the onboarding panel"><i class="oi oi-close"/></a>
                <div class="o_onboarding_steps d-flex" t-out="0"/>

                <div t-if="state.get(''onboarding_state'') == ''just_done''" t-att-state="state.get(''onboarding_state'')" class="o_onboarding_completed_message position-absolute end-0 start-0 border-bottom py-4 bg-white d-flex align-items-center justify-content-center">
                    <span class="h3 m-0">
                        <i class="fa fa-check text-success me-3"/>
                        <t t-if="text_completed" t-out="text_completed"/>
                    </span>
                    <a type="action" class="btn btn-primary ms-4" t-att-data-model="close_model" t-att-data-method="close_method">
                        Close Panel
                    </a>
                </div>
            </div>
        </div>
    </t>

    ', false, true, '2026-05-10 01:11:42.65887', '2026-05-10 01:11:42.65887', NULL);
INSERT INTO public.ir_ui_view VALUES (257, 16, NULL, 1, 1, 'onboarding_step', NULL, 'onboarding.onboarding_step', 'qweb', 'onboarding/views/onboarding_templates.xml', 'primary', '{"en_US": "<t t-name=\"onboarding.onboarding_step\">\n        <div class=\"o_onboarding_step position-relative d-flex flex-column align-items-center justify-content-start text-center\" t-att-data-step-state=\"state\">\n            <img t-if=\"state == ''just_done''\" class=\"o_onboarding_confetti position-absolute w-100\" src=\"/base/static/img/onboarding_confetti.svg\" alt=\"o_onboarding_confetti\"/>\n\n            <div class=\"o_onboarding_line position-absolute\"/>\n            <div class=\"o_onboarding_step_side d-flex\">\n                <img class=\"z-index-1\" t-attf-src=\"#{image}\" t-attf-alt=\"#{alt}\"/>\n            </div>\n\n            <div class=\"o_onboarding_step_content position-relative pt-2 flex-grow-1 d-flex flex-column align-items-center justify-content-around\">\n                <div class=\"o_onboarding_step_content_info flex-grow-1 mb-2\">\n                    <a type=\"action\" data-reload-on-close=\"true\" role=\"button\" t-att-data-method=\"method\" t-att-data-model=\"model\">\n                        <h5 class=\"o_onboarding_step_title mb-1\" t-out=\"title\"/>\n                    </a>\n                    <p class=\"m-0 small\" t-out=\"description\"/>\n                </div>\n                <a t-if=\"state == ''not_done''\" class=\"o_onboarding_step_action btn px-4\" type=\"action\" data-reload-on-close=\"true\" role=\"button\" t-att-data-method=\"method\" t-att-data-model=\"model\">\n                    <span>\n                        <t t-if=\"btn_text\" t-out=\"btn_text\"/>\n                        <t t-else=\"\">Let''s do it</t>\n                    </span>\n                </a>\n                <a t-else=\"\" class=\"o_onboarding_step_action__done btn\" type=\"action\" data-reload-on-close=\"true\" role=\"button\" t-att-data-method=\"method\" t-att-data-model=\"model\">\n                    <span>\n                        <i t-attf-class=\"p-1 me-1 fa #{done_icon if done_icon else ''fa-check''} rounded-circle\"/>\n                        <t t-if=\"done_text\" t-out=\"done_text\"/>\n                        <t t-else=\"\">All done!</t>\n                    </span>\n                </a>\n            </div>\n        </div>\n    </t>"}', '<?xml version="1.0"?>
<t t-name="onboarding.onboarding_step">
        <div class="o_onboarding_step position-relative d-flex flex-column align-items-center justify-content-start text-center" t-att-data-step-state="state">
            <img t-if="state == ''just_done''" class="o_onboarding_confetti position-absolute w-100" src="/base/static/img/onboarding_confetti.svg" alt="o_onboarding_confetti"/>

            <div class="o_onboarding_line position-absolute"/>
            <div class="o_onboarding_step_side d-flex">
                <img class="z-index-1" t-attf-src="#{image}" t-attf-alt="#{alt}"/>
            </div>

            <div class="o_onboarding_step_content position-relative pt-2 flex-grow-1 d-flex flex-column align-items-center justify-content-around">
                <div class="o_onboarding_step_content_info flex-grow-1 mb-2">
                    <a type="action" data-reload-on-close="true" role="button" t-att-data-method="method" t-att-data-model="model">
                        <h5 class="o_onboarding_step_title mb-1" t-out="title"/>
                    </a>
                    <p class="m-0 small" t-out="description"/>
                </div>
                <a t-if="state == ''not_done''" class="o_onboarding_step_action btn px-4" type="action" data-reload-on-close="true" role="button" t-att-data-method="method" t-att-data-model="model">
                    <span>
                        <t t-if="btn_text" t-out="btn_text"/>
                        <t t-else="">Let''s do it</t>
                    </span>
                </a>
                <a t-else="" class="o_onboarding_step_action__done btn" type="action" data-reload-on-close="true" role="button" t-att-data-method="method" t-att-data-model="model">
                    <span>
                        <i t-attf-class="p-1 me-1 fa #{done_icon if done_icon else ''fa-check''} rounded-circle"/>
                        <t t-if="done_text" t-out="done_text"/>
                        <t t-else="">All done!</t>
                    </span>
                </a>
            </div>
