INSERT INTO public.ir_ui_view VALUES (259, 16, NULL, 1, 1, 'onboarding.onboarding.view.form', 'onboarding.onboarding', NULL, 'form', 'onboarding/views/onboarding_views.xml', 'primary', '{"en_US": "<form>\n                <header>\n                    <field name=\"current_progress_id\" invisible=\"1\"/>\n                    <button name=\"action_toggle_visibility\" type=\"object\" string=\"Toggle visibility\" invisible=\"not current_progress_id\"/>\n                </header>\n                <sheet>\n                    <group col=\"2\">\n                        <field name=\"name\"/>\n                        <field name=\"route_name\"/>\n                        <field name=\"is_per_company\"/>\n                        <field name=\"is_onboarding_closed\"/>\n                    </group>\n                    <notebook>\n                        <page name=\"Onboarding steps\">\n                            <group string=\"Steps\">\n                                <field name=\"step_ids\" nolabel=\"1\" colspan=\"2\"/>\n                            </group>\n                        </page>\n                    </notebook>\n                </sheet>\n            </form>"}', '<?xml version="1.0"?>
