INSERT INTO public.ir_ui_view VALUES (288, 16, NULL, 1, 1, 'Activity schedule', 'mail.activity.schedule', NULL, 'form', 'mail/wizard/mail_activity_schedule_views.xml', 'primary', '{"en_US": "<form>\n                    <field name=\"activity_category\" invisible=\"1\"/>\n                    <field name=\"chaining_type\" invisible=\"1\"/>\n                    <field name=\"company_id\" invisible=\"1\"/>\n                    <field name=\"has_error\" invisible=\"1\"/>\n                    <field name=\"plan_has_user_on_demand\" invisible=\"1\"/>\n                    <field name=\"res_ids\" invisible=\"1\"/>\n                    <field name=\"plan_available_ids\" invisible=\"1\"/>\n                    <header invisible=\"not bool(plan_available_ids)\">\n                        <group>\n                            <field name=\"plan_id\" options=\"{&quot;no_open&quot;: True, &quot;no_create&quot;: True}\"/>\n                        </group>\n                    </header>\n                    <sheet>\n                        <group invisible=\"not plan_id\">\n                            <group>\n                                <field name=\"plan_date_deadline\"/>\n                                <field name=\"plan_on_demand_user_id\" widget=\"many2one_avatar_user\" invisible=\"not plan_has_user_on_demand\"/>\n                            </group>\n                            <group>\n                                <label for=\"plan_assignation_summary\" class=\"o_form_label\" string=\"Plan summary\" colspan=\"2\"/>\n                                <field name=\"plan_assignation_summary\" colspan=\"2\" nolabel=\"1\"/>\n                            </group>\n                        </group>\n                        <group invisible=\"plan_id\">\n                            <group>\n                                <field name=\"res_model\" invisible=\"1\"/>\n                                <field name=\"activity_type_id\" required=\"not plan_id\" options=\"{''no_create'': True, ''no_open'': True}\"/>\n                                <field name=\"summary\" placeholder=\"e.g. Discuss proposal\"/>\n                            </group>\n                            <group>\n                                <field name=\"date_deadline\"/>\n                                <field name=\"activity_user_id\" widget=\"many2one_avatar_user\" required=\"not plan_id\"/>\n                            </group>\n                            <field name=\"note\" class=\"oe-bordered-editor\" placeholder=\"Log a note...\"/>\n                        </group>\n                        <div role=\"alert\" class=\"alert alert-danger mb8\" invisible=\"not has_error\">\n                            <field name=\"error\"/>\n                        </div>\n                    </sheet>\n                    <footer invisible=\"plan_id\">\n                        <button name=\"action_schedule_activities\" string=\"Schedule\" type=\"object\" class=\"btn-primary\" invisible=\"has_error\" data-hotkey=\"q\"/>\n                        <button name=\"action_schedule_activities_done\" string=\"Schedule &amp; Mark as Done\" type=\"object\" invisible=\"has_error or chaining_type == ''trigger''\" class=\"btn-secondary\" data-hotkey=\"w\" context=\"{''mail_activity_quick_update'': True}\"/>\n                        <button name=\"action_schedule_activities_done_and_schedule\" string=\"Done &amp; Schedule Next\" type=\"object\" invisible=\"has_error or chaining_type == ''trigger''\" class=\"btn-secondary\" data-hotkey=\"z\" context=\"{''mail_activity_quick_update'': True}\"/>\n                        <button name=\"action_schedule_activities_done_and_schedule\" string=\"Done &amp; Launch Next\" type=\"object\" invisible=\"has_error or chaining_type == ''suggest''\" class=\"btn-secondary\" data-hotkey=\"z\" context=\"{''mail_activity_quick_update'': True}\"/>\n                        <button string=\"Cancel\" class=\"btn-secondary\" special=\"cancel\" data-hotkey=\"x\"/>\n                    </footer>\n                    <footer invisible=\"not plan_id\">\n                        <button name=\"action_schedule_plan\" string=\"Schedule\" type=\"object\" class=\"btn-primary\" invisible=\"has_error\" data-hotkey=\"q\"/>\n                        <button string=\"Cancel\" class=\"btn-secondary\" special=\"cancel\" data-hotkey=\"x\"/>\n                    </footer>\n                </form>"}', '<?xml version="1.0"?>
<form>
                    <field name="activity_category" invisible="1"/>
                    <field name="chaining_type" invisible="1"/>
                    <field name="company_id" invisible="1"/>
                    <field name="has_error" invisible="1"/>
                    <field name="plan_has_user_on_demand" invisible="1"/>
                    <field name="res_ids" invisible="1"/>
                    <field name="plan_available_ids" invisible="1"/>
                    <header invisible="not bool(plan_available_ids)">
                        <group>
                            <field name="plan_id" options="{&quot;no_open&quot;: True, &quot;no_create&quot;: True}"/>
                        </group>
                    </header>
                    <sheet>
                        <group invisible="not plan_id">
                            <group>
                                <field name="plan_date_deadline"/>
                                <field name="plan_on_demand_user_id" widget="many2one_avatar_user" invisible="not plan_has_user_on_demand"/>
                            </group>
                            <group>
                                <label for="plan_assignation_summary" class="o_form_label" string="Plan summary" colspan="2"/>
                                <field name="plan_assignation_summary" colspan="2" nolabel="1"/>
                            </group>
                        </group>
                        <group invisible="plan_id">
                            <group>
                                <field name="res_model" invisible="1"/>
                                <field name="activity_type_id" required="not plan_id" options="{''no_create'': True, ''no_open'': True}"/>
                                <field name="summary" placeholder="e.g. Discuss proposal"/>
                            </group>
                            <group>
                                <field name="date_deadline"/>
                                <field name="activity_user_id" widget="many2one_avatar_user" required="not plan_id"/>
                            </group>
                            <field name="note" class="oe-bordered-editor" placeholder="Log a note..."/>
                        </group>
                        <div role="alert" class="alert alert-danger mb8" invisible="not has_error">
                            <field name="error"/>
                        </div>
                    </sheet>
                    <footer invisible="plan_id">
                        <button name="action_schedule_activities" string="Schedule" type="object" class="btn-primary" invisible="has_error" data-hotkey="q"/>
                        <button name="action_schedule_activities_done" string="Schedule &amp; Mark as Done" type="object" invisible="has_error or chaining_type == ''trigger''" class="btn-secondary" data-hotkey="w" context="{''mail_activity_quick_update'': True}"/>
                        <button name="action_schedule_activities_done_and_schedule" string="Done &amp; Schedule Next" type="object" invisible="has_error or chaining_type == ''trigger''" class="btn-secondary" data-hotkey="z" context="{''mail_activity_quick_update'': True}"/>
                        <button name="action_schedule_activities_done_and_schedule" string="Done &amp; Launch Next" type="object" invisible="has_error or chaining_type == ''suggest''" class="btn-secondary" data-hotkey="z" context="{''mail_activity_quick_update'': True}"/>
                        <button string="Cancel" class="btn-secondary" special="cancel" data-hotkey="x"/>
                    </footer>
                    <footer invisible="not plan_id">
                        <button name="action_schedule_plan" string="Schedule" type="object" class="btn-primary" invisible="has_error" data-hotkey="q"/>
                        <button string="Cancel" class="btn-secondary" special="cancel" data-hotkey="x"/>
                    </footer>
                </form>
            ', false, true, '2026-05-10 01:11:43.555423', '2026-05-10 01:11:43.555423', NULL);
INSERT INTO public.ir_ui_view VALUES (261, 16, NULL, 1, 1, 'onboarding.onboarding.step.view.form', 'onboarding.onboarding.step', NULL, 'form', 'onboarding/views/onboarding_views.xml', 'primary', '{"en_US": "<form>\n                <sheet>\n                    <group>\n                        <field name=\"title\"/>\n                        <field name=\"current_step_state\"/>\n                        <field name=\"panel_step_open_action_name\"/>\n                        <field name=\"is_per_company\"/>\n                    </group>\n                    <notebook>\n                        <page name=\"Onboardings using this step\">\n                            <group string=\"Onboardings\">\n                                <field name=\"onboarding_ids\" nolabel=\"1\" colspan=\"2\"/>\n                            </group>\n                        </page>\n                        <page name=\"Step rendering\">\n                            <group>\n                                <field name=\"description\"/>\n                                <field name=\"button_text\"/>\n                                <field name=\"done_text\"/>\n                                <field name=\"done_icon\"/>\n                                <field name=\"step_image_filename\" invisible=\"1\"/>\n                                <field name=\"step_image\" filename=\"step_image_filename\"/>\n                                <field name=\"step_image_alt\"/>\n                            </group>\n                        </page>\n                    </notebook>\n                </sheet>\n            </form>"}', '<?xml version="1.0"?>
<form>
                <sheet>
                    <group>
                        <field name="title"/>
                        <field name="current_step_state"/>
                        <field name="panel_step_open_action_name"/>
                        <field name="is_per_company"/>
                    </group>
                    <notebook>
                        <page name="Onboardings using this step">
                            <group string="Onboardings">
                                <field name="onboarding_ids" nolabel="1" colspan="2"/>
                            </group>
                        </page>
                        <page name="Step rendering">
                            <group>
                                <field name="description"/>
                                <field name="button_text"/>
                                <field name="done_text"/>
                                <field name="done_icon"/>
                                <field name="step_image_filename" invisible="1"/>
                                <field name="step_image" filename="step_image_filename"/>
                                <field name="step_image_alt"/>
                            </group>
                        </page>
                    </notebook>
                </sheet>
            </form>
        ', false, true, '2026-05-10 01:11:42.65887', '2026-05-10 01:11:42.65887', NULL);
INSERT INTO public.ir_ui_view VALUES (262, 16, NULL, 1, 1, 'resource.resource.search', 'resource.resource', NULL, 'search', 'resource/views/resource_resource_views.xml', 'primary', '{"en_US": "<search string=\"Search Resource\">\n               <field name=\"name\"/>\n               <field name=\"resource_type\"/>\n               <field name=\"user_id\"/>\n               <field name=\"calendar_id\"/>\n               <field name=\"company_id\" groups=\"base.group_multi_company\"/>\n               <filter string=\"Human\" name=\"human\" domain=\"[(''resource_type'',''='', ''user'')]\"/>\n               <filter string=\"Material\" name=\"material\" domain=\"[(''resource_type'',''='', ''material'')]\"/>\n               <separator/>\n               <filter string=\"Archived\" name=\"inactive\" domain=\"[(''active'',''='',False)]\"/>\n               <group expand=\"0\" string=\"Group By\">\n                    <filter string=\"User\" name=\"user\" domain=\"[]\" context=\"{''group_by'':''user_id''}\"/>\n                    <filter string=\"Type\" name=\"type\" domain=\"[]\" context=\"{''group_by'':''resource_type''}\"/>\n                    <filter string=\"Company\" name=\"company\" domain=\"[]\" context=\"{''group_by'':''company_id''}\" groups=\"base.group_multi_company\"/>\n                    <filter string=\"Working Time\" name=\"working_period\" domain=\"[]\" context=\"{''group_by'':''calendar_id''}\"/>\n                </group>\n           </search>"}', '<?xml version="1.0"?>
<search string="Search Resource">
               <field name="name"/>
               <field name="resource_type"/>
               <field name="user_id"/>
               <field name="calendar_id"/>
               <field name="company_id" groups="base.group_multi_company"/>
               <filter string="Human" name="human" domain="[(''resource_type'',''='', ''user'')]"/>
               <filter string="Material" name="material" domain="[(''resource_type'',''='', ''material'')]"/>
               <separator/>
               <filter string="Archived" name="inactive" domain="[(''active'',''='',False)]"/>
               <group expand="0" string="Group By">
                    <filter string="User" name="user" domain="[]" context="{''group_by'':''user_id''}"/>
                    <filter string="Type" name="type" domain="[]" context="{''group_by'':''resource_type''}"/>
                    <filter string="Company" name="company" domain="[]" context="{''group_by'':''company_id''}" groups="base.group_multi_company"/>
                    <filter string="Working Time" name="working_period" domain="[]" context="{''group_by'':''calendar_id''}"/>
                </group>
           </search>
        ', false, true, '2026-05-10 01:11:42.911705', '2026-05-10 01:11:42.911705', NULL);
INSERT INTO public.ir_ui_view VALUES (263, 16, NULL, 1, 1, 'resource.resource.form', 'resource.resource', NULL, 'form', 'resource/views/resource_resource_views.xml', 'primary', '{"en_US": "<form string=\"Resource\">\n            <sheet>\n                <field name=\"active\" invisible=\"1\"/>\n                <field name=\"company_id\" invisible=\"1\"/>\n                <widget name=\"web_ribbon\" title=\"Archived\" bg_color=\"text-bg-danger\" invisible=\"active\"/>\n                <group>\n                    <group name=\"user_details\">\n                        <field name=\"name\"/>\n                        <field name=\"user_id\" invisible=\"resource_type == ''material''\" required=\"resource_type == ''user''\"/>\n                        <field name=\"company_id\" options=\"{''no_create'': True}\" groups=\"base.group_multi_company\"/>\n                        <field name=\"resource_type\"/>\n                    </group>\n                    <group name=\"resource_details\">\n                        <field name=\"calendar_id\"/>\n                        <field name=\"tz\"/>\n                        <field name=\"time_efficiency\"/>\n                    </group>\n                </group>\n            </sheet>\n            </form>"}', '<?xml version="1.0"?>
