INSERT INTO public.ir_ui_view VALUES (269, 16, NULL, 1, 1, 'resource.calendar.attendance.tree', 'resource.calendar.attendance', NULL, 'tree', 'resource/views/resource_calendar_attendance_views.xml', 'primary', '{"en_US": "<tree string=\"Working Time\" editable=\"bottom\" default_order=\"sequence, week_type, dayofweek, hour_from\">\n                <field name=\"sequence\" widget=\"handle\"/>\n                <field name=\"display_type\" column_invisible=\"True\"/>\n                <field name=\"display_name\" width=\"1\" string=\" \" invisible=\"display_type != ''line_section''\"/>\n                <field name=\"name\" invisible=\"display_type == ''line_section''\"/>\n                <field name=\"dayofweek\"/>\n                <field name=\"day_period\"/>\n                <field name=\"hour_from\" widget=\"float_time\"/>\n                <field name=\"hour_to\" widget=\"float_time\"/>\n                <field name=\"duration_days\" optional=\"show\"/>\n                <field name=\"date_from\" optional=\"hide\"/>\n                <field name=\"date_to\" optional=\"hide\"/>\n                <field name=\"week_type\" readonly=\"1\" force_save=\"1\" optional=\"hide\"/>\n            </tree>"}', '<?xml version="1.0"?>
<tree string="Working Time" editable="bottom" default_order="sequence, week_type, dayofweek, hour_from">
                <field name="sequence" widget="handle"/>
