                <field name="display_name" width="1" string=" " invisible="display_type != ''line_section''"/>
                <field name="name" invisible="display_type == ''line_section''"/>
                <field name="dayofweek"/>
                <field name="day_period"/>
                <field name="hour_from" widget="float_time"/>
                <field name="hour_to" widget="float_time"/>
                <field name="duration_days" optional="show"/>
                <field name="date_from" optional="hide"/>
                <field name="date_to" optional="hide"/>
                <field name="week_type" readonly="1" force_save="1" optional="hide"/>
            </tree>
        ', false, true, '2026-05-10 01:11:42.911705', '2026-05-10 01:11:42.911705', NULL);
INSERT INTO public.ir_ui_view VALUES (350, 10, 349, 1, 1, 'mail.activity.plan.view.form.fixed.model', 'mail.activity.plan', NULL, 'form', 'mail/views/mail_activity_plan_views.xml', 'primary', '{"en_US": "<data><xpath expr=\"//tree\" position=\"attributes\">\n                    <attribute name=\"editable\">bottom</attribute>\n                </xpath>\n                <xpath expr=\"//group[@name=''plan_res_model'']\" position=\"attributes\">\n                    <attribute name=\"invisible\">1</attribute>\n                </xpath>\n            </data>"}', '<?xml version="1.0"?>
