INSERT INTO public.ir_ui_view VALUES (270, 16, NULL, 1, 1, 'resource.calendar.attendance.form', 'resource.calendar.attendance', NULL, 'form', 'resource/views/resource_calendar_attendance_views.xml', 'primary', '{"en_US": "<form string=\"Working Time\">\n                <sheet>\n                <group>\n                    <field name=\"name\"/>\n                    <field name=\"date_from\"/>\n                    <field name=\"date_to\"/>\n                    <field name=\"dayofweek\"/>\n                    <label for=\"hour_from\" string=\"Hours\"/>\n                    <div class=\"o_row\">\n                        <field name=\"hour_from\" widget=\"float_time\"/> -\n                        <field name=\"hour_to\" widget=\"float_time\"/>\n                    </div>\n                    <field name=\"day_period\"/>\n                    <field name=\"duration_days\"/>\n                </group>\n                </sheet>\n            </form>"}', '<?xml version="1.0"?>
<form string="Working Time">
                <sheet>
                <group>
                    <field name="name"/>
                    <field name="date_from"/>
                    <field name="date_to"/>
                    <field name="dayofweek"/>
                    <label for="hour_from" string="Hours"/>
