INSERT INTO public.ir_ui_view VALUES (272, 16, NULL, 1, 1, 'resource.calendar.form', 'resource.calendar', NULL, 'form', 'resource/views/resource_calendar_views.xml', 'primary', '{"en_US": "<form string=\"Working Time\">\n                <field name=\"two_weeks_calendar\" invisible=\"1\"/>\n                <header>\n                    <button name=\"switch_calendar_type\" invisible=\"two_weeks_calendar\" string=\"Switch to 2 weeks calendar\" type=\"object\" confirm=\"Are you sure you want to switch this calendar to 2 weeks calendar? All entries will be lost\"/>\n                    <button name=\"switch_calendar_type\" invisible=\"not two_weeks_calendar\" string=\"Switch to 1 week calendar\" type=\"object\" confirm=\"Are you sure you want to switch this calendar to 1 week calendar? All entries will be lost\"/>\n                </header>\n                <sheet string=\"Working Time\">\n                    <widget name=\"web_ribbon\" title=\"Archived\" bg_color=\"text-bg-danger\" invisible=\"active\"/>\n                    <div class=\"oe_button_box\" name=\"button_box\">\n                        <button name=\"94\" type=\"action\" icon=\"fa-plane\" class=\"oe_stat_button\" groups=\"base.group_no_one\">\n                                <div class=\"o_field_widget o_stat_info\">\n                                    <span class=\"o_stat_text\">Time Off</span>\n                                </div>\n                        </button>\n                        <button name=\"92\" type=\"action\" icon=\"fa-cogs\" class=\"oe_stat_button\" groups=\"base.group_user\">\n                                <div class=\"o_field_widget o_stat_info\">\n                                    <span class=\"o_stat_text\">Work Resources</span>\n                                </div>\n                        </button>\n                    </div>\n                    <h1>\n                        <field name=\"name\"/>\n                    </h1>\n                    <group name=\"resource_details\">\n                        <group>\n                            <field name=\"active\" invisible=\"1\"/>\n                            <field name=\"company_id\" groups=\"base.group_multi_company\"/>\n                            <field name=\"hours_per_day\" widget=\"float_time\"/>\n                            <field name=\"tz\" widget=\"timezone_mismatch\" options=\"{''tz_offset_field'': ''tz_offset'', ''mismatch_title'': ''Timezone Mismatch : This timezone is different from that of your browser.\\nPlease, be mindful of this when setting the working hours or the time off.''}\"/>\n                            <field name=\"tz_offset\" invisible=\"1\"/>\n                        </group>\n                    </group>\n                    <notebook>\n                        <page string=\"Working Hours\" name=\"working_hours\">\n                            <field name=\"two_weeks_explanation\" invisible=\"not two_weeks_calendar\"/>\n                            <field name=\"attendance_ids\" widget=\"section_one2many\"/>\n                        </page>\n                    </notebook>\n                </sheet>\n            </form>"}', '<?xml version="1.0"?>
<form string="Working Time">
                <field name="two_weeks_calendar" invisible="1"/>
                <header>
                    <button name="switch_calendar_type" invisible="two_weeks_calendar" string="Switch to 2 weeks calendar" type="object" confirm="Are you sure you want to switch this calendar to 2 weeks calendar? All entries will be lost"/>
                    <button name="switch_calendar_type" invisible="not two_weeks_calendar" string="Switch to 1 week calendar" type="object" confirm="Are you sure you want to switch this calendar to 1 week calendar? All entries will be lost"/>
                </header>
                <sheet string="Working Time">
                    <widget name="web_ribbon" title="Archived" bg_color="text-bg-danger" invisible="active"/>
                    <div class="oe_button_box" name="button_box">
                        <button name="94" type="action" icon="fa-plane" class="oe_stat_button" groups="base.group_no_one">
                                <div class="o_field_widget o_stat_info">
                                    <span class="o_stat_text">Time Off</span>
                                </div>
                        </button>
                        <button name="92" type="action" icon="fa-cogs" class="oe_stat_button" groups="base.group_user">
                                <div class="o_field_widget o_stat_info">
                                    <span class="o_stat_text">Work Resources</span>
                                </div>
                        </button>
                    </div>
                    <h1>
                        <field name="name"/>
                    </h1>
                    <group name="resource_details">
                        <group>
                            <field name="active" invisible="1"/>
                            <field name="company_id" groups="base.group_multi_company"/>
                            <field name="hours_per_day" widget="float_time"/>
                            <field name="tz" widget="timezone_mismatch" options="{''tz_offset_field'': ''tz_offset'', ''mismatch_title'': ''Timezone Mismatch : This timezone is different from that of your browser.\nPlease, be mindful of this when setting the working hours or the time off.''}"/>
                            <field name="tz_offset" invisible="1"/>
                        </group>
                    </group>
                    <notebook>
                        <page string="Working Hours" name="working_hours">
                            <field name="two_weeks_explanation" invisible="not two_weeks_calendar"/>
                            <field name="attendance_ids" widget="section_one2many"/>
                        </page>
                    </notebook>
                </sheet>
            </form>
        ', false, true, '2026-05-10 01:11:42.911705', '2026-05-10 01:11:42.911705', NULL);
INSERT INTO public.ir_ui_view VALUES (273, 16, NULL, 1, 1, 'resource.calendar.tree', 'resource.calendar', NULL, 'tree', 'resource/views/resource_calendar_views.xml', 'primary', '{"en_US": "<tree string=\"Working Time\">\n                <field name=\"name\" string=\"Working Time\"/>\n                <field name=\"company_id\" groups=\"base.group_multi_company\"/>\n            </tree>"}', '<?xml version="1.0"?>
