INSERT INTO public.ir_ui_view VALUES (274, 16, NULL, 1, 1, 'utm.campaign.view.search', 'utm.campaign', NULL, 'search', 'utm/views/utm_campaign_views.xml', 'primary', '{"en_US": "<search string=\"UTM Campaigns\">\n                <field name=\"title\" string=\"Campaigns\"/>\n                <field name=\"tag_ids\"/>\n                <field name=\"user_id\"/>\n                <field name=\"is_auto_campaign\"/>\n                <filter string=\"My Campaigns\" name=\"filter_assigned_to_me\" domain=\"[(''user_id'', ''='', uid)]\" help=\"Campaigns that are assigned to me\"/>\n                <separator/>\n                <filter string=\"Archived\" name=\"filter_inactive\" domain=\"[(''active'', ''='', False)]\"/>\n                <group expand=\"0\" string=\"Group By\">\n                    <filter string=\"Stage\" name=\"group_stage_id\" context=\"{''group_by'': ''stage_id''}\"/>\n                    <filter string=\"Responsible\" name=\"group_user_id\" context=\"{''group_by'': ''user_id''}\"/>\n                    <filter string=\"Tags\" name=\"group_tags_id\" context=\"{''group_by'': ''tag_ids''}\"/>\n                </group>\n            </search>"}', '<?xml version="1.0"?>
<search string="UTM Campaigns">
                <field name="title" string="Campaigns"/>
                <field name="tag_ids"/>
                <field name="user_id"/>
                <field name="is_auto_campaign"/>
                <filter string="My Campaigns" name="filter_assigned_to_me" domain="[(''user_id'', ''='', uid)]" help="Campaigns that are assigned to me"/>
                <separator/>
                <filter string="Archived" name="filter_inactive" domain="[(''active'', ''='', False)]"/>
                <group expand="0" string="Group By">
                    <filter string="Stage" name="group_stage_id" context="{''group_by'': ''stage_id''}"/>
                    <filter string="Responsible" name="group_user_id" context="{''group_by'': ''user_id''}"/>
                    <filter string="Tags" name="group_tags_id" context="{''group_by'': ''tag_ids''}"/>
                </group>
            </search>
        ', false, true, '2026-05-10 01:11:43.219791', '2026-05-10 01:11:43.219791', NULL);
INSERT INTO public.ir_ui_view VALUES (294, 16, NULL, 1, 1, 'mail.template.preview.view.form', 'mail.template.preview', NULL, 'form', 'mail/wizard/mail_template_preview_views.xml', 'primary', '{"en_US": "<form string=\"Email Preview\">\n                    <sheet>\n                        <div class=\"oe_title\">\n                            <h3>Preview of <field name=\"mail_template_id\" readonly=\"1\" nolabel=\"1\" options=\"{''no_open'': True}\"/></h3>\n                        </div>\n                        <div class=\"alert alert-danger\" role=\"alert\" invisible=\"not error_msg\">\n                            <field name=\"error_msg\" widget=\"text\"/>\n                        </div>\n                        <field name=\"no_record\" invisible=\"1\"/>\n\n                        <group>\n                            <label for=\"resource_ref\" string=\"Test Record: \"/>\n                            <field name=\"resource_ref\" nolabel=\"1\" options=\"{''hide_model'': True, ''no_create'': True, ''no_open'': True}\" readonly=\"False\" invisible=\"no_record\"/>\n                            <b invisible=\"not no_record\" class=\"text-warning\">No record for this model</b>\n\n                            <field name=\"lang\" string=\"Force a Language:\" placeholder=\"Select a language\"/>\n\n                            <field name=\"subject\"/>\n                            <field name=\"email_from\" invisible=\"not email_from\"/>\n                            <field name=\"partner_ids\" widget=\"many2many_tags\" invisible=\"not partner_ids\"/>\n                            <field name=\"email_to\" invisible=\"not email_to\"/>\n                            <field name=\"email_cc\" invisible=\"not email_cc\"/>\n                            <field name=\"reply_to\" invisible=\"not reply_to\"/>\n                            <field name=\"scheduled_date\" invisible=\"not scheduled_date\"/>\n\n                            <field name=\"body_html\" widget=\"html\" colspan=\"2\" nolabel=\"1\" options=\"{''safe'': True}\"/>\n                            <field name=\"attachment_ids\" widget=\"many2many_binary\"/>\n                        </group>\n                    </sheet>\n                    <footer>\n                        <button string=\"Close\" class=\"btn-secondary\" special=\"cancel\" data-hotkey=\"x\"/>\n                    </footer>\n                </form>"}', '<?xml version="1.0"?>
<form string="Email Preview">
                    <sheet>
                        <div class="oe_title">
                            <h3>Preview of <field name="mail_template_id" readonly="1" nolabel="1" options="{''no_open'': True}"/></h3>
                        </div>
                        <div class="alert alert-danger" role="alert" invisible="not error_msg">
                            <field name="error_msg" widget="text"/>
                        </div>
                        <field name="no_record" invisible="1"/>

                        <group>
                            <label for="resource_ref" string="Test Record: "/>
                            <field name="resource_ref" nolabel="1" options="{''hide_model'': True, ''no_create'': True, ''no_open'': True}" readonly="False" invisible="no_record"/>
                            <b invisible="not no_record" class="text-warning">No record for this model</b>

                            <field name="lang" string="Force a Language:" placeholder="Select a language"/>

                            <field name="subject"/>
                            <field name="email_from" invisible="not email_from"/>
                            <field name="partner_ids" widget="many2many_tags" invisible="not partner_ids"/>
                            <field name="email_to" invisible="not email_to"/>
                            <field name="email_cc" invisible="not email_cc"/>
                            <field name="reply_to" invisible="not reply_to"/>
                            <field name="scheduled_date" invisible="not scheduled_date"/>

                            <field name="body_html" widget="html" colspan="2" nolabel="1" options="{''safe'': True}"/>
                            <field name="attachment_ids" widget="many2many_binary"/>
                        </group>
                    </sheet>
                    <footer>
                        <button string="Close" class="btn-secondary" special="cancel" data-hotkey="x"/>
                    </footer>
                </form>
            ', false, true, '2026-05-10 01:11:43.555423', '2026-05-10 01:11:43.555423', NULL);
INSERT INTO public.ir_ui_view VALUES (275, 16, NULL, 1, 1, 'utm.campaign.view.form', 'utm.campaign', NULL, 'form', 'utm/views/utm_campaign_views.xml', 'primary', '{"en_US": "<form string=\"UTM Campaign\">\n                <header>\n                    <field name=\"stage_id\" widget=\"statusbar\" options=\"{''clickable'': ''1''}\"/>\n                </header>\n                <sheet>\n                    <div class=\"oe_button_box d-flex justify-content-end\" name=\"button_box\">\n                    </div>\n                    <widget name=\"web_ribbon\" title=\"Archived\" bg_color=\"text-bg-danger\" invisible=\"active\"/>\n                    <group id=\"top-group\">\n                        <field name=\"active\" invisible=\"1\"/>\n                        <field class=\"text-break\" name=\"title\" string=\"Campaign Name\" placeholder=\"e.g. Black Friday\"/>\n                        <field name=\"name\" invisible=\"1\"/>\n                        <field name=\"user_id\" widget=\"many2one_avatar_user\" domain=\"[(''share'', ''='', False)]\"/>\n                        <field name=\"tag_ids\" widget=\"many2many_tags\" options=\"{''color_field'': ''color'', ''no_create_edit'': True}\"/>\n                    </group>\n                    <notebook>\n                    </notebook>\n                </sheet>\n            </form>"}', '<?xml version="1.0"?>
<form string="UTM Campaign">
                <header>
                    <field name="stage_id" widget="statusbar" options="{''clickable'': ''1''}"/>
                </header>
                <sheet>
                    <div class="oe_button_box d-flex justify-content-end" name="button_box">
                    </div>
                    <widget name="web_ribbon" title="Archived" bg_color="text-bg-danger" invisible="active"/>
                    <group id="top-group">
                        <field name="active" invisible="1"/>
                        <field class="text-break" name="title" string="Campaign Name" placeholder="e.g. Black Friday"/>
                        <field name="name" invisible="1"/>
                        <field name="user_id" widget="many2one_avatar_user" domain="[(''share'', ''='', False)]"/>
                        <field name="tag_ids" widget="many2many_tags" options="{''color_field'': ''color'', ''no_create_edit'': True}"/>
                    </group>
                    <notebook>
                    </notebook>
                </sheet>
            </form>
        ', false, true, '2026-05-10 01:11:43.219791', '2026-05-10 01:11:43.219791', NULL);
INSERT INTO public.ir_ui_view VALUES (276, 16, NULL, 1, 1, 'utm.campaign.view.tree', 'utm.campaign', NULL, 'tree', 'utm/views/utm_campaign_views.xml', 'primary', '{"en_US": "<tree string=\"UTM Campaigns\" multi_edit=\"1\" sample=\"1\">\n                <field name=\"title\" string=\"Name\" readonly=\"1\"/>\n                <field name=\"name\" column_invisible=\"True\"/>\n                <field name=\"user_id\" widget=\"many2one_avatar_user\"/>\n                <field name=\"stage_id\" decoration-bf=\"1\"/>\n                <field name=\"tag_ids\" widget=\"many2many_tags\" options=\"{''color_field'': ''color''}\"/>\n            </tree>"}', '<?xml version="1.0"?>
