INSERT INTO public.ir_ui_view VALUES (278, 16, NULL, 1, 1, 'utm.campaign.view.kanban', 'utm.campaign', NULL, 'kanban', 'utm/views/utm_campaign_views.xml', 'primary', '{"en_US": "<kanban default_group_by=\"stage_id\" class=\"o_utm_kanban\" on_create=\"quick_create\" quick_create_view=\"utm.utm_campaign_view_form_quick_create\" examples=\"utm_campaign\" sample=\"1\">\n                <field name=\"color\"/>\n                <field name=\"user_id\"/>\n                <field name=\"stage_id\"/>\n                <field name=\"active\"/>\n                <templates>\n                    <t t-name=\"kanban-menu\">\n                        <t t-if=\"widget.editable\">\n                            <a role=\"menuitem\" type=\"edit\" class=\"dropdown-item\">Edit</a>\n                        </t>\n                        <t t-if=\"widget.deletable\">\n                            <a role=\"menuitem\" type=\"delete\" class=\"dropdown-item\">Delete</a>\n                        </t>\n                        <a role=\"menuitem\" class=\"dropdown-item o_kanban_mailing_active\" name=\"toggle_active\" type=\"object\">\n                            <t t-if=\"record.active.raw_value\">Archive</t>\n                            <t t-else=\"\">Restore</t>\n                        </a>\n                        <div role=\"separator\" class=\"dropdown-divider\"/>\n                        <ul class=\"oe_kanban_colorpicker\" data-field=\"color\"/>\n                    </t>\n                    <t t-name=\"kanban-box\">\n                        <div t-attf-class=\"oe_kanban_color_#{kanban_getcolor(record.color.raw_value)} oe_kanban_card oe_kanban_global_click\">\n                            <div class=\"oe_kanban_content\">\n                                <div class=\"o_kanban_record_top\">\n                                    <div class=\"o_kanban_record_headings\">\n                                        <h3 class=\"oe_margin_bottom_8 o_kanban_record_title\"><field name=\"title\"/></h3>\n                                    </div>\n                                </div>\n                                <div class=\"o_kanban_record_body\">\n                                    <field name=\"tag_ids\" widget=\"many2many_tags\" options=\"{''color_field'': ''color''}\"/>\n                                    <ul id=\"o_utm_actions\" class=\"list-group list-group-horizontal my-0\"/>\n                                </div>\n                                <div class=\"o_kanban_record_bottom h5 mt-2 mb-0\">\n                                    <div class=\"oe_kanban_bottom_left py-auto\"/>\n                                    <div class=\"oe_kanban_bottom_right\">\n                                         <field name=\"user_id\" widget=\"many2one_avatar_user\"/>\n                                    </div>\n                                </div>\n                            </div>\n                            <div class=\"clearfix\"/>\n                        </div>\n                    </t>\n                </templates>\n            </kanban>"}', '<?xml version="1.0"?>
<kanban default_group_by="stage_id" class="o_utm_kanban" on_create="quick_create" quick_create_view="utm.utm_campaign_view_form_quick_create" examples="utm_campaign" sample="1">
                <field name="color"/>
                <field name="user_id"/>
                <field name="stage_id"/>
                <field name="active"/>
                <templates>
                    <t t-name="kanban-menu">
                        <t t-if="widget.editable">
                            <a role="menuitem" type="edit" class="dropdown-item">Edit</a>
                        </t>
                        <t t-if="widget.deletable">
                            <a role="menuitem" type="delete" class="dropdown-item">Delete</a>
                        </t>
                        <a role="menuitem" class="dropdown-item o_kanban_mailing_active" name="toggle_active" type="object">
                            <t t-if="record.active.raw_value">Archive</t>
                            <t t-else="">Restore</t>
                        </a>
                        <div role="separator" class="dropdown-divider"/>
                        <ul class="oe_kanban_colorpicker" data-field="color"/>
                    </t>
                    <t t-name="kanban-box">
                        <div t-attf-class="oe_kanban_color_#{kanban_getcolor(record.color.raw_value)} oe_kanban_card oe_kanban_global_click">
                            <div class="oe_kanban_content">
                                <div class="o_kanban_record_top">
                                    <div class="o_kanban_record_headings">
                                        <h3 class="oe_margin_bottom_8 o_kanban_record_title"><field name="title"/></h3>
                                    </div>
                                </div>
