INSERT INTO public.ir_ui_view VALUES (290, 16, NULL, 1, 1, 'mail.compose.message.form', 'mail.compose.message', NULL, 'form', 'mail/wizard/mail_compose_message_views.xml', 'primary', '{"en_US": "<form string=\"Compose Email\" class=\"pt-0 pb-0 o_mail_composer_form\" js_class=\"mail_composer_form\">\n                    <group>\n                        <!-- truly invisible fields for control and options -->\n                        <field name=\"author_id\" invisible=\"1\"/>\n                        <field name=\"auto_delete\" invisible=\"1\"/>\n                        <field name=\"auto_delete_keep_log\" invisible=\"1\"/>\n                        <field name=\"composition_batch\" invisible=\"1\"/>\n                        <field name=\"composition_mode\" invisible=\"1\"/>\n                        <field name=\"email_layout_xmlid\" invisible=\"1\"/>\n                        <field name=\"force_send\" invisible=\"1\"/>\n                        <field name=\"lang\" invisible=\"1\"/>\n                        <field name=\"mail_server_id\" invisible=\"1\"/>\n                        <field name=\"model\" invisible=\"1\"/>\n                        <field name=\"model_is_thread\" invisible=\"1\"/>\n                        <field name=\"parent_id\" invisible=\"1\"/>\n                        <field name=\"record_alias_domain_id\" invisible=\"1\"/>\n                        <field name=\"record_company_id\" invisible=\"1\"/>\n                        <field name=\"record_name\" invisible=\"1\"/>\n                        <field name=\"render_model\" invisible=\"1\"/>\n                        <field name=\"res_domain\" invisible=\"1\"/>\n                        <field name=\"res_domain_user_id\" invisible=\"1\"/>\n                        <field name=\"res_ids\" invisible=\"1\"/>\n                        <field name=\"scheduled_date\" invisible=\"1\"/>\n                        <field name=\"subtype_id\" invisible=\"1\"/>\n                        <field name=\"subtype_is_log\" invisible=\"1\"/>\n                        <field name=\"use_exclusion_list\" invisible=\"1\"/>\n                        <!-- visible wizard -->\n                        <field name=\"email_from\" invisible=\"composition_mode != ''mass_mail''\"/>\n                        <label for=\"partner_ids\" string=\"Recipients\" invisible=\"composition_mode != ''comment'' or subtype_is_log\"/>\n                        <div groups=\"base.group_user\" invisible=\"composition_mode != ''comment'' or subtype_is_log\">\n                            <span name=\"document_followers_text\" invisible=\"not model or composition_mode == ''mass_mail''\">Followers of the document and</span>\n                            <field name=\"partner_ids\" widget=\"many2many_tags_email\" placeholder=\"Add contacts to notify...\" options=\"{''no_quick_create'': True}\" context=\"{''show_email'':True, ''form_view_ref'': ''base.view_partner_simple_form''}\"/>\n                        </div>\n                        <field name=\"subject\" placeholder=\"Welcome to MyCompany!\" required=\"True\"/>\n                    </group>\n                    <field name=\"can_edit_body\" invisible=\"1\"/>\n                    <div invisible=\"composition_mode == ''mass_mail''\">\n                        <field name=\"body\" class=\"oe-bordered-editor\" placeholder=\"Write your message here...\" options=\"{''style-inline'': true}\" readonly=\"not can_edit_body\" force_save=\"1\"/>\n                        <group>\n                            <field name=\"attachment_ids\" widget=\"many2many_binary\" string=\"Attach a file\" nolabel=\"1\" colspan=\"2\"/>\n                        </group>\n                        <group>\n                            <field name=\"template_id\" string=\"Load template\" options=\"{''no_create'': True}\" class=\"w-50\" context=\"{''default_model'': model, ''default_body_html'': body, ''default_subject'': subject}\"/>\n                        </group>\n                    </div>\n                    <notebook invisible=\"composition_mode != ''mass_mail''\">\n                        <page string=\"Content\" name=\"page_content\">\n                            <div>\n                                <field name=\"body\" class=\"oe-bordered-editor\" placeholder=\"Write your message here...\" options=\"{''style-inline'': true}\" readonly=\"not can_edit_body\" force_save=\"1\"/>\n                                <group>\n                                    <field name=\"attachment_ids\" widget=\"many2many_binary\" string=\"Attach a file\" nolabel=\"1\" colspan=\"2\"/>\n                                </group>\n                                <group>\n                                    <field name=\"template_id\" string=\"Load template\" options=\"{''no_create'': True}\" class=\"w-50\" context=\"{''default_model'': model, ''default_body_html'': body, ''default_subject'': subject}\"/>\n                                </group>\n                            </div>\n                        </page>\n                        <page string=\"Settings\" name=\"page_settings\">\n                            <!-- mass mailing -->\n                            <field name=\"reply_to_force_new\" invisible=\"1\"/>\n                            <field name=\"reply_to_mode\" invisible=\"composition_mode != ''mass_mail''\" widget=\"radio\"/>\n                            <group>\n                                <field name=\"reply_to\" string=\"Reply-to Address\" placeholder=\"e.g: &quot;info@mycompany.odoo.com&quot;\" invisible=\"reply_to_mode == ''update'' or composition_mode != ''mass_mail''\" required=\"reply_to_mode != ''update'' and composition_mode == ''mass_mail''\"/>\n                            </group>\n                        </page>\n                    </notebook>\n                    <footer>\n                        <button string=\"Send\" name=\"action_send_mail\" type=\"object\" class=\"btn-primary o_mail_send\" data-hotkey=\"q\" invisible=\"subtype_is_log\"/>\n                        <button string=\"Log\" name=\"action_send_mail\" type=\"object\" class=\"btn-primary\" data-hotkey=\"q\" invisible=\"not subtype_is_log\"/>\n                        <button string=\"Discard\" class=\"btn-secondary\" special=\"cancel\" data-hotkey=\"x\"/>\n                        <button icon=\"fa-cloud-upload\" type=\"object\" name=\"open_template_creation_wizard\" string=\"Save Template\" invisible=\"not can_edit_body\" class=\"float-end btn-secondary\" data-hotkey=\"w\" help=\"Save as a new template\"/>\n                    </footer>\n                </form>"}', '<?xml version="1.0"?>
<form string="Compose Email" class="pt-0 pb-0 o_mail_composer_form" js_class="mail_composer_form">
                    <group>
                        <!-- truly invisible fields for control and options -->
                        <field name="author_id" invisible="1"/>
                        <field name="auto_delete" invisible="1"/>
                        <field name="auto_delete_keep_log" invisible="1"/>
                        <field name="composition_batch" invisible="1"/>
                        <field name="composition_mode" invisible="1"/>
                        <field name="email_layout_xmlid" invisible="1"/>
                        <field name="force_send" invisible="1"/>
                        <field name="lang" invisible="1"/>
                        <field name="mail_server_id" invisible="1"/>
                        <field name="model" invisible="1"/>
                        <field name="model_is_thread" invisible="1"/>
                        <field name="parent_id" invisible="1"/>
                        <field name="record_alias_domain_id" invisible="1"/>
                        <field name="record_company_id" invisible="1"/>
                        <field name="record_name" invisible="1"/>
                        <field name="render_model" invisible="1"/>
                        <field name="res_domain" invisible="1"/>
                        <field name="res_domain_user_id" invisible="1"/>
                        <field name="res_ids" invisible="1"/>
                        <field name="scheduled_date" invisible="1"/>
                        <field name="subtype_id" invisible="1"/>
                        <field name="subtype_is_log" invisible="1"/>
                        <field name="use_exclusion_list" invisible="1"/>
                        <!-- visible wizard -->
                        <field name="email_from" invisible="composition_mode != ''mass_mail''"/>
                        <label for="partner_ids" string="Recipients" invisible="composition_mode != ''comment'' or subtype_is_log"/>
                        <div groups="base.group_user" invisible="composition_mode != ''comment'' or subtype_is_log">
                            <span name="document_followers_text" invisible="not model or composition_mode == ''mass_mail''">Followers of the document and</span>
                            <field name="partner_ids" widget="many2many_tags_email" placeholder="Add contacts to notify..." options="{''no_quick_create'': True}" context="{''show_email'':True, ''form_view_ref'': ''base.view_partner_simple_form''}"/>
                        </div>
                        <field name="subject" placeholder="Welcome to MyCompany!" required="True"/>
                    </group>
                    <field name="can_edit_body" invisible="1"/>
                    <div invisible="composition_mode == ''mass_mail''">
                        <field name="body" class="oe-bordered-editor" placeholder="Write your message here..." options="{''style-inline'': true}" readonly="not can_edit_body" force_save="1"/>
                        <group>
                            <field name="attachment_ids" widget="many2many_binary" string="Attach a file" nolabel="1" colspan="2"/>
                        </group>
                        <group>
                            <field name="template_id" string="Load template" options="{''no_create'': True}" class="w-50" context="{''default_model'': model, ''default_body_html'': body, ''default_subject'': subject}"/>
                        </group>
                    </div>
                    <notebook invisible="composition_mode != ''mass_mail''">
                        <page string="Content" name="page_content">
                            <div>
                                <field name="body" class="oe-bordered-editor" placeholder="Write your message here..." options="{''style-inline'': true}" readonly="not can_edit_body" force_save="1"/>
                                <group>
                                    <field name="attachment_ids" widget="many2many_binary" string="Attach a file" nolabel="1" colspan="2"/>
                                </group>
                                <group>
                                    <field name="template_id" string="Load template" options="{''no_create'': True}" class="w-50" context="{''default_model'': model, ''default_body_html'': body, ''default_subject'': subject}"/>
                                </group>
                            </div>
                        </page>
                        <page string="Settings" name="page_settings">
                            <!-- mass mailing -->
                            <field name="reply_to_force_new" invisible="1"/>
                            <field name="reply_to_mode" invisible="composition_mode != ''mass_mail''" widget="radio"/>
                            <group>
                                <field name="reply_to" string="Reply-to Address" placeholder="e.g: &quot;info@mycompany.odoo.com&quot;" invisible="reply_to_mode == ''update'' or composition_mode != ''mass_mail''" required="reply_to_mode != ''update'' and composition_mode == ''mass_mail''"/>
                            </group>
                        </page>
                    </notebook>
                    <footer>
                        <button string="Send" name="action_send_mail" type="object" class="btn-primary o_mail_send" data-hotkey="q" invisible="subtype_is_log"/>
                        <button string="Log" name="action_send_mail" type="object" class="btn-primary" data-hotkey="q" invisible="not subtype_is_log"/>
                        <button string="Discard" class="btn-secondary" special="cancel" data-hotkey="x"/>
                        <button icon="fa-cloud-upload" type="object" name="open_template_creation_wizard" string="Save Template" invisible="not can_edit_body" class="float-end btn-secondary" data-hotkey="w" help="Save as a new template"/>
                    </footer>
                </form>
            ', false, true, '2026-05-10 01:11:43.555423', '2026-05-10 01:11:43.555423', NULL);
INSERT INTO public.ir_ui_view VALUES (291, 16, NULL, 1, 1, 'mail.compose.message.view.form.template.save', 'mail.compose.message', NULL, 'form', 'mail/wizard/mail_compose_message_views.xml', 'primary', '{"en_US": "<form string=\"Templates\">\n                    <group>\n                        <field name=\"subject\" placeholder=\"e.g. &quot;Welcome to MyCompany&quot; or &quot;Nice to meet you, {{ object.name }}&quot;\"/>\n                    </group>\n                    <footer>\n                        <button name=\"create_mail_template\" type=\"object\" class=\"btn btn-primary\" string=\"Save\"/>\n                        <button name=\"cancel_save_template\" type=\"object\" class=\"btn btn-secondary\" string=\"Cancel\"/>\n                    </footer>\n                </form>"}', '<?xml version="1.0"?>
<form string="Templates">
                    <group>
                        <field name="subject" placeholder="e.g. &quot;Welcome to MyCompany&quot; or &quot;Nice to meet you, {{ object.name }}&quot;"/>
                    </group>
                    <footer>
                        <button name="create_mail_template" type="object" class="btn btn-primary" string="Save"/>
                        <button name="cancel_save_template" type="object" class="btn btn-secondary" string="Cancel"/>
                    </footer>
                </form>
            ', false, true, '2026-05-10 01:11:43.555423', '2026-05-10 01:11:43.555423', NULL);
INSERT INTO public.ir_ui_view VALUES (292, 16, NULL, 1, 1, 'mail.resend.message.view.form', 'mail.resend.message', NULL, 'form', 'mail/wizard/mail_resend_message_views.xml', 'primary', '{"en_US": "<form string=\"Edit Partners\">\n                    <field name=\"mail_message_id\" invisible=\"1\"/>\n                    <field name=\"notification_ids\" invisible=\"1\"/>\n                    <field name=\"can_resend\" invisible=\"1\"/>\n                    <field name=\"partner_readonly\" invisible=\"1\"/>\n                    <field name=\"partner_ids\">\n                        <tree string=\"Recipient\" editable=\"top\" create=\"0\" delete=\"0\">\n                            <field name=\"name\" readonly=\"1\"/>\n                            <field name=\"email\" readonly=\"parent.partner_readonly\"/>\n                            <field name=\"message\" readonly=\"1\" class=\"text-wrap\"/>\n                            <field name=\"resend\" widget=\"boolean_toggle\"/>\n                            <button name=\"action_open_resend_partner\" type=\"object\" string=\"See Error Details\" class=\"btn-link\"/>\n                        </tree>\n                    </field>\n                    <footer>\n                        <button string=\"Send &amp; close\" name=\"resend_mail_action\" type=\"object\" class=\"btn-primary o_mail_send\" invisible=\"not can_resend\" data-hotkey=\"q\"/>\n                        <button string=\"Ignore all\" name=\"cancel_mail_action\" type=\"object\" class=\"btn-primary\" invisible=\"can_resend\" data-hotkey=\"w\"/>\n                        <button string=\"Ignore all\" name=\"cancel_mail_action\" type=\"object\" class=\"btn-secondary\" invisible=\"not can_resend\" data-hotkey=\"w\"/>\n                        <button string=\"Close\" class=\"btn-secondary\" special=\"cancel\" data-hotkey=\"x\"/>\n                    </footer>\n                </form>"}', '<?xml version="1.0"?>
<form string="Edit Partners">
                    <field name="mail_message_id" invisible="1"/>
                    <field name="notification_ids" invisible="1"/>
                    <field name="can_resend" invisible="1"/>
                    <field name="partner_readonly" invisible="1"/>
                    <field name="partner_ids">
                        <tree string="Recipient" editable="top" create="0" delete="0">
                            <field name="name" readonly="1"/>
                            <field name="email" readonly="parent.partner_readonly"/>
                            <field name="message" readonly="1" class="text-wrap"/>
                            <field name="resend" widget="boolean_toggle"/>
                            <button name="action_open_resend_partner" type="object" string="See Error Details" class="btn-link"/>
                        </tree>
                    </field>
                    <footer>
                        <button string="Send &amp; close" name="resend_mail_action" type="object" class="btn-primary o_mail_send" invisible="not can_resend" data-hotkey="q"/>
                        <button string="Ignore all" name="cancel_mail_action" type="object" class="btn-primary" invisible="can_resend" data-hotkey="w"/>
                        <button string="Ignore all" name="cancel_mail_action" type="object" class="btn-secondary" invisible="not can_resend" data-hotkey="w"/>
                        <button string="Close" class="btn-secondary" special="cancel" data-hotkey="x"/>
                    </footer>
                </form>
            ', false, true, '2026-05-10 01:11:43.555423', '2026-05-10 01:11:43.555423', NULL);
INSERT INTO public.ir_ui_view VALUES (293, 16, NULL, 1, 1, 'mail.resend.partner.view.form', 'mail.resend.partner', NULL, 'form', 'mail/wizard/mail_resend_partner_views.xml', 'primary', '{"en_US": "<form string=\"Partner\">\n                <header>\n                    <button name=\"action_resend\" type=\"object\" string=\"Resend\" class=\"oe_highlight\" invisible=\"not failure_reason\"/>\n                </header>\n                <sheet>\n                    <div class=\"oe_button_box\" name=\"button_box\">\n                        <button class=\"oe_stat_button\" name=\"action_open_record\" type=\"object\" icon=\"fa-user\">\n                            <span>Open Record</span>\n                        </button>\n                    </div>\n                    <group col=\"2\">\n                        <group colspan=\"1\">\n                            <field name=\"notification_id\" invisible=\"1\"/>\n                            <field name=\"partner_readonly\" invisible=\"1\"/>\n                            <field name=\"name\" readonly=\"1\" required=\"1\"/>\n                            <field name=\"email\" readonly=\"partner_readonly\"/>\n                        </group>\n                    </group>\n                    <notebook>\n                        <page string=\"Failure Reason\" name=\"page_failure_reason\">\n                            <field name=\"failure_reason\" class=\"text-wrap w-100 overflow-auto\" nolabel=\"1\"/>\n                        </page>\n                    </notebook>\n                </sheet>\n            </form>"}', '<?xml version="1.0"?>
<form string="Partner">
                <header>
                    <button name="action_resend" type="object" string="Resend" class="oe_highlight" invisible="not failure_reason"/>
                </header>
                <sheet>
                    <div class="oe_button_box" name="button_box">
                        <button class="oe_stat_button" name="action_open_record" type="object" icon="fa-user">
                            <span>Open Record</span>
                        </button>
                    </div>
                    <group col="2">
                        <group colspan="1">
                            <field name="notification_id" invisible="1"/>
                            <field name="partner_readonly" invisible="1"/>
                            <field name="name" readonly="1" required="1"/>
                            <field name="email" readonly="partner_readonly"/>
                        </group>
                    </group>
                    <notebook>
                        <page string="Failure Reason" name="page_failure_reason">
                            <field name="failure_reason" class="text-wrap w-100 overflow-auto" nolabel="1"/>
                        </page>
                    </notebook>
                </sheet>
            </form>
        ', false, true, '2026-05-10 01:11:43.555423', '2026-05-10 01:11:43.555423', NULL);
INSERT INTO public.ir_ui_view VALUES (301, 16, NULL, 1, 1, 'mail.message.subtype.form', 'mail.message.subtype', NULL, 'form', 'mail/views/mail_message_subtype_views.xml', 'primary', '{"en_US": "<form string=\"Email message\">\n                    <sheet>\n                        <group>\n                            <group string=\"Description\">\n                                <field name=\"name\"/>\n                                <field name=\"sequence\"/>\n                                <field name=\"res_model\"/>\n                                <field name=\"description\"/>\n                                <field name=\"default\"/>\n                                <field name=\"internal\"/>\n                                <field name=\"hidden\"/>\n                                <field name=\"track_recipients\"/>\n                            </group>\n                            <group string=\"Auto subscription\">\n                                <field name=\"parent_id\"/>\n                                <field name=\"relation_field\"/>\n                            </group>\n                        </group>\n                    </sheet>\n                </form>"}', '<?xml version="1.0"?>
