INSERT INTO public.ir_ui_view VALUES (295, 16, NULL, 1, 1, 'Add Followers', 'mail.wizard.invite', NULL, 'form', 'mail/wizard/mail_wizard_invite_views.xml', 'primary', '{"en_US": "<form string=\"Add Followers\">\n                    <group>\n                        <field name=\"res_model\" invisible=\"1\"/>\n                        <field name=\"res_id\" invisible=\"1\"/>\n                        <field name=\"partner_ids\" widget=\"many2many_tags_email\" placeholder=\"Add contacts to notify...\" options=\"{''no_quick_create'': True}\" context=\"{''show_email'': True, ''form_view_ref'': ''base.view_partner_simple_form''}\"/>\n                        <field name=\"notify\"/>\n                        <field name=\"message\" invisible=\"not notify\" options=\"{''style-inline'': true, ''no-attachment'': true}\" class=\"oe-bordered-editor\"/>\n                    </group>\n                    <footer>\n                        <button string=\"Add Followers\" name=\"add_followers\" type=\"object\" class=\"btn-primary\" data-hotkey=\"q\"/>\n                        <button string=\"Cancel\" class=\"btn-secondary\" special=\"cancel\" data-hotkey=\"x\"/>\n                    </footer>\n                </form>"}', '<?xml version="1.0"?>
