INSERT INTO public.ir_ui_view VALUES (297, 16, NULL, 1, 1, 'fetchmail.server.list', 'fetchmail.server', NULL, 'tree', 'mail/views/fetchmail_views.xml', 'primary', '{"en_US": "<tree string=\"POP/IMAP Servers\">\n                    <field name=\"name\"/>\n                    <field name=\"server_type\"/>\n                    <field name=\"user\" readonly=\"state != ''draft''\"/>\n                    <field name=\"date\"/>\n                    <field name=\"state\" widget=\"badge\" decoration-info=\"state == ''draft''\" decoration-success=\"state == ''done''\"/>\n                </tree>"}', '<?xml version="1.0"?>
