                </tree>
            ', false, true, '2026-05-10 01:11:43.555423', '2026-05-10 01:11:43.555423', NULL);
INSERT INTO public.ir_ui_view VALUES (298, 16, NULL, 1, 1, 'fetchmail.server.form', 'fetchmail.server', NULL, 'form', 'mail/views/fetchmail_views.xml', 'primary', '{"en_US": "<form string=\"Incoming Mail Server\">\n                    <header invisible=\"server_type == ''local''\">\n                        <button string=\"Test &amp; Confirm\" type=\"object\" name=\"button_confirm_login\" invisible=\"state != ''draft''\"/>\n                        <button string=\"Fetch Now\" type=\"object\" name=\"fetch_mail\" invisible=\"state != ''done''\"/>\n                        <button string=\"Reset Confirmation\" type=\"object\" name=\"set_draft\" invisible=\"state != ''done''\"/>\n                        <field name=\"state\" widget=\"statusbar\"/>\n                    </header>\n                    <sheet>\n                    <field name=\"active\" invisible=\"1\"/>\n                    <widget name=\"web_ribbon\" title=\"Archived\" bg_color=\"text-bg-danger\" invisible=\"active\"/>\n                     <group>\n                        <group>\n                            <field name=\"name\"/>\n                            <field name=\"server_type\" widget=\"radio\" readonly=\"state == ''done''\"/>\n                        </group>\n                        <group>\n                            <field name=\"date\" invisible=\"not date\"/>\n                            <div class=\"text-muted fst-italic\" colspan=\"8\" role=\"alert\" invisible=\"not server_type_info\">\n                                <field name=\"server_type_info\"/>\n                            </div>\n                        </group>\n                     </group>\n                     <notebook>\n                        <page string=\"Server &amp; Login\" name=\"server_login_details\">\n                            <group>\n                                <group invisible=\"server_type == ''local''\" string=\"Server Information\">\n                                    <field name=\"server\" readonly=\"state != ''draft''\" required=\"server_type != ''local''\"/>\n                                    <field name=\"port\" required=\"1\" readonly=\"state != ''draft''\" options=\"{''format'': false}\"/>\n                                    <field name=\"is_ssl\"/>\n                                </group>\n                                <group invisible=\"server_type == ''local''\" string=\"Login Information\">\n                                    <field name=\"user\" readonly=\"state != ''draft''\" required=\"server_type != ''local''\"/>\n                                    <field name=\"password\" password=\"True\" invisible=\"server_type not in (''imap'', ''pop'')\" readonly=\"state != ''draft''\" required=\"server_type in (''imap'', ''pop'')\"/>\n                                </group>\n                                <group string=\"Actions to Perform on Incoming Mails\">\n                                    <field name=\"object_id\"/>\n                                </group>\n                                <group invisible=\"server_type != ''local''\" string=\"Configuration\">\n                                    <field name=\"configuration\"/>\n                                    <field name=\"script\" widget=\"url\"/>\n                                </group>\n                            </group>\n                        </page>\n                        <page string=\"Advanced\" name=\"advanced_options\" groups=\"base.group_no_one\">\n                            <group>\n                                <group string=\"Advanced Options\">\n                                    <field name=\"priority\" readonly=\"state != ''draft''\"/>\n                                    <field name=\"attach\"/>\n                                    <field name=\"original\"/>\n                                </group>\n                            </group>\n                        </page>\n                    </notebook>\n                  </sheet>\n                </form>"}', '<?xml version="1.0"?>
<form string="Incoming Mail Server">
                    <header invisible="server_type == ''local''">
                        <button string="Test &amp; Confirm" type="object" name="button_confirm_login" invisible="state != ''draft''"/>
                        <button string="Fetch Now" type="object" name="fetch_mail" invisible="state != ''done''"/>
                        <button string="Reset Confirmation" type="object" name="set_draft" invisible="state != ''done''"/>
                        <field name="state" widget="statusbar"/>
                    </header>
                    <sheet>
                    <field name="active" invisible="1"/>
                    <widget name="web_ribbon" title="Archived" bg_color="text-bg-danger" invisible="active"/>
                     <group>
                        <group>
                            <field name="name"/>
                            <field name="server_type" widget="radio" readonly="state == ''done''"/>
                        </group>
                        <group>
                            <field name="date" invisible="not date"/>
                            <div class="text-muted fst-italic" colspan="8" role="alert" invisible="not server_type_info">
                                <field name="server_type_info"/>
                            </div>
                        </group>
                     </group>
                     <notebook>
                        <page string="Server &amp; Login" name="server_login_details">
                            <group>
                                <group invisible="server_type == ''local''" string="Server Information">
                                    <field name="server" readonly="state != ''draft''" required="server_type != ''local''"/>
                                    <field name="port" required="1" readonly="state != ''draft''" options="{''format'': false}"/>
                                    <field name="is_ssl"/>
                                </group>
                                <group invisible="server_type == ''local''" string="Login Information">
                                    <field name="user" readonly="state != ''draft''" required="server_type != ''local''"/>
                                    <field name="password" password="True" invisible="server_type not in (''imap'', ''pop'')" readonly="state != ''draft''" required="server_type in (''imap'', ''pop'')"/>
                                </group>
                                <group string="Actions to Perform on Incoming Mails">
                                    <field name="object_id"/>
                                </group>
                                <group invisible="server_type != ''local''" string="Configuration">
                                    <field name="configuration"/>
                                    <field name="script" widget="url"/>
                                </group>
                            </group>
                        </page>
                        <page string="Advanced" name="advanced_options" groups="base.group_no_one">
                            <group>
                                <group string="Advanced Options">
                                    <field name="priority" readonly="state != ''draft''"/>
                                    <field name="attach"/>
                                    <field name="original"/>
                                </group>
                            </group>
                        </page>
                    </notebook>
                  </sheet>
                </form>
            ', false, true, '2026-05-10 01:11:43.555423', '2026-05-10 01:11:43.555423', NULL);
INSERT INTO public.ir_ui_view VALUES (299, 16, NULL, 1, 1, 'fetchmail.server.search', 'fetchmail.server', NULL, 'search', 'mail/views/fetchmail_views.xml', 'primary', '{"en_US": "<search string=\"Search Incoming Mail Servers\">\n                    <field name=\"name\" string=\"Incoming Mail Server\"/>\n                    <field name=\"user\"/>\n                    <filter string=\"IMAP\" name=\"imap\" domain=\"[(''server_type'', ''='', ''imap'')]\" help=\"Server type IMAP.\"/>\n                    <filter string=\"POP\" name=\"pop\" domain=\"[(''server_type'', ''='', ''pop'')]\" help=\"Server type POP.\"/>\n                    <separator/>\n                    <filter string=\"SSL\" name=\"ssl\" domain=\"[(''is_ssl'', ''='', True)]\" help=\"If SSL required.\"/>\n                    <separator/>\n                    <filter string=\"Archived\" name=\"inactive\" domain=\"[(''active'', ''='', False)]\"/>\n                </search>"}', '<?xml version="1.0"?>
<search string="Search Incoming Mail Servers">
