INSERT INTO public.ir_ui_view VALUES (305, 16, NULL, 1, 1, 'mail.notification.view.form', 'mail.notification', NULL, 'form', 'mail/views/mail_notification_views.xml', 'primary', '{"en_US": "<form string=\"Notification\" duplicate=\"0\">\n                <header>\n                    <field name=\"notification_status\" widget=\"statusbar\" statusbar_visible=\"ready,sent\"/>\n                </header>\n                <sheet>\n                    <group>\n                        <group string=\"Source\">\n                            <field name=\"mail_message_id\"/>\n                            <field name=\"notification_type\"/>\n                            <field name=\"mail_mail_id\"/>\n                            <field name=\"res_partner_id\"/>\n                        </group>\n                        <group string=\"Status\">\n                            <field name=\"is_read\"/>\n                            <field name=\"read_date\"/>\n                            <field name=\"failure_type\"/>\n                            <field name=\"failure_reason\" class=\"o_text_overflow\"/>\n                        </group>\n                    </group>\n                </sheet>\n            </form>"}', '<?xml version="1.0"?>
