INSERT INTO public.ir_ui_view VALUES (319, 16, NULL, 1, 1, 'mail.ice.server.form', 'mail.ice.server', NULL, 'form', 'mail/views/mail_ice_server_views.xml', 'primary', '{"en_US": "<form string=\"ICE server\">\n                <sheet>\n                    <group>\n                        <label for=\"uri\"/>\n                        <div class=\"oe_inline\" name=\"URI\" style=\"display: inline;\">\n                            <field name=\"server_type\" class=\"oe_inline\"/><field name=\"uri\" class=\"oe_inline\"/>\n                        </div>\n                    </group>\n                    <group>\n                        <field name=\"username\"/>\n                        <field name=\"credential\"/>\n                    </group>\n                </sheet>\n            </form>"}', '<?xml version="1.0"?>
<form string="ICE server">
