INSERT INTO public.ir_ui_view VALUES (307, 20, NULL, 1, 1, 'mail.message.view.form', 'mail.message', NULL, 'form', 'mail/views/mail_message_views.xml', 'primary', '{"en_US": "<form string=\"Message\" duplicate=\"0\">\n                    <sheet>\n                        <div class=\"oe_button_box\" name=\"button_box\">\n                            <button name=\"action_open_document\" type=\"object\" class=\"oe_link\" icon=\"fa-file-text-o\" invisible=\"not model or res_id == 0\">\n                                <div class=\"o_field_widget o_stat_info\">\n                                    <span class=\"o_stat_text\">Open Document</span>\n                                </div>\n                            </button>\n                        </div>\n                        <group>\n                            <group>\n                                <field name=\"subject\"/>\n                                <field name=\"date\"/>\n                                <field name=\"email_from\"/>\n                                <field name=\"author_id\"/>\n                                <field name=\"message_type\"/>\n                                <field name=\"subtype_id\"/>\n                                <field name=\"is_internal\"/>\n                            </group>\n                            <group>\n                                <field name=\"model\"/>\n                                <field name=\"res_id\"/>\n                                <field name=\"record_name\"/>\n                                <field name=\"parent_id\"/>\n                            </group>\n                        </group>\n                        <notebook>\n                            <page string=\"Body\" name=\"body\">\n                                <field name=\"body\" options=\"{''style-inline'': true}\"/>\n                            </page>\n                            <page string=\"Gateway\" name=\"gateway\">\n                                <group>\n                                    <group>\n                                        <field name=\"reply_to\"/>\n                                        <field name=\"reply_to_force_new\"/>\n                                    </group>\n                                    <group>\n                                        <field name=\"message_id\"/>\n                                        <field name=\"mail_server_id\"/>\n                                    </group>\n                                </group>\n                            </page>\n                            <page string=\"Recipients\" name=\"recipients\">\n                                <group>\n                                    <group>\n                                        <field name=\"partner_ids\" widget=\"many2many_tags\"/>\n                                    </group>\n                                    <group>\n                                        <field name=\"notified_partner_ids\" widget=\"many2many_tags\"/>\n                                        <field name=\"starred_partner_ids\" widget=\"many2many_tags\"/>\n                                    </group>\n                                </group>\n                                <group>\n                                    <field name=\"notification_ids\">\n                                        <tree>\n                                            <field name=\"res_partner_id\"/>\n                                            <field name=\"is_read\"/>\n                                            <field name=\"notification_type\"/>\n                                            <field name=\"notification_status\"/>\n                                        </tree>\n                                    </field>\n                                </group>\n                            </page>\n                            <page string=\"Tracking\" name=\"page_tracking\">\n                                <field name=\"tracking_value_ids\"/>\n                            </page>\n                        </notebook>\n                    </sheet>\n                </form>"}', '<?xml version="1.0"?>
<form string="Message" duplicate="0">
                    <sheet>
                        <div class="oe_button_box" name="button_box">
                            <button name="action_open_document" type="object" class="oe_link" icon="fa-file-text-o" invisible="not model or res_id == 0">
                                <div class="o_field_widget o_stat_info">
                                    <span class="o_stat_text">Open Document</span>
                                </div>
                            </button>
                        </div>
                        <group>
                            <group>
                                <field name="subject"/>
                                <field name="date"/>
                                <field name="email_from"/>
                                <field name="author_id"/>
                                <field name="message_type"/>
                                <field name="subtype_id"/>
                                <field name="is_internal"/>
                            </group>
                            <group>
                                <field name="model"/>
                                <field name="res_id"/>
                                <field name="record_name"/>
                                <field name="parent_id"/>
                            </group>
                        </group>
                        <notebook>
                            <page string="Body" name="body">
                                <field name="body" options="{''style-inline'': true}"/>
                            </page>
                            <page string="Gateway" name="gateway">
                                <group>
                                    <group>
                                        <field name="reply_to"/>
                                        <field name="reply_to_force_new"/>
                                    </group>
                                    <group>
                                        <field name="message_id"/>
                                        <field name="mail_server_id"/>
                                    </group>
                                </group>
                            </page>
                            <page string="Recipients" name="recipients">
                                <group>
                                    <group>
                                        <field name="partner_ids" widget="many2many_tags"/>
                                    </group>
                                    <group>
                                        <field name="notified_partner_ids" widget="many2many_tags"/>
                                        <field name="starred_partner_ids" widget="many2many_tags"/>
                                    </group>
                                </group>
                                <group>
                                    <field name="notification_ids">
                                        <tree>
                                            <field name="res_partner_id"/>
                                            <field name="is_read"/>
                                            <field name="notification_type"/>
                                            <field name="notification_status"/>
                                        </tree>
                                    </field>
                                </group>
                            </page>
                            <page string="Tracking" name="page_tracking">
                                <field name="tracking_value_ids"/>
                            </page>
                        </notebook>
                    </sheet>
                </form>
            ', false, true, '2026-05-10 01:11:43.555423', '2026-05-10 01:11:43.555423', NULL);
INSERT INTO public.ir_ui_view VALUES (308, 25, NULL, 1, 1, 'mail.message.search', 'mail.message', NULL, 'search', 'mail/views/mail_message_views.xml', 'primary', '{"en_US": "<search string=\"Messages Search\">\n                    <field name=\"body\" string=\"Content\" filter_domain=\"[''|'', (''subject'', ''ilike'', self), (''body'', ''ilike'', self)]\"/>\n                    <field name=\"subject\"/>\n                    <field name=\"message_type\"/>\n                    <field name=\"author_id\"/>\n                    <field name=\"partner_ids\"/>\n                    <field name=\"model\"/>\n                    <field name=\"res_id\"/>\n                    <field name=\"parent_id\"/>\n                    <filter string=\"Has Mentions\" name=\"filter_has_mentions\" domain=\"[(''partner_ids.user_ids'', ''in'', [uid])]\"/>\n                    <separator/>\n                    <filter string=\"Need Action\" name=\"message_needaction\" help=\"Unread messages\" domain=\"[(''needaction'', ''='', True)]\"/>\n                    <separator/>\n                </search>"}', '<?xml version="1.0"?>
<search string="Messages Search">
                    <field name="body" string="Content" filter_domain="[''|'', (''subject'', ''ilike'', self), (''body'', ''ilike'', self)]"/>
                    <field name="subject"/>
                    <field name="message_type"/>
                    <field name="author_id"/>
                    <field name="partner_ids"/>
                    <field name="model"/>
                    <field name="res_id"/>
                    <field name="parent_id"/>
                    <filter string="Has Mentions" name="filter_has_mentions" domain="[(''partner_ids.user_ids'', ''in'', [uid])]"/>
                    <separator/>
                    <filter string="Need Action" name="message_needaction" help="Unread messages" domain="[(''needaction'', ''='', True)]"/>
                    <separator/>
                </search>
            ', false, true, '2026-05-10 01:11:43.555423', '2026-05-10 01:11:43.555423', NULL);
INSERT INTO public.ir_ui_view VALUES (309, 16, NULL, 1, 1, 'ir.attachment kanban', 'ir.attachment', NULL, 'kanban', 'mail/views/mail_message_views.xml', 'primary', '{"en_US": "<kanban edit=\"false\" import=\"false\">\n                    <field name=\"id\"/>\n                    <field name=\"mimetype\"/>\n                    <field name=\"type\"/>\n                    <field name=\"create_uid\"/>\n                    <field name=\"url\"/>\n                    <field name=\"create_date\"/>\n                    <field name=\"name\"/>\n                    <templates>\n                        <t t-name=\"kanban-menu\">\n                            <a t-attf-href=\"/web/content/ir.attachment/#{record.id.raw_value}/datas?download=true\" download=\"\" class=\"dropdown-item\">Download</a>\n                            <a t-if=\"widget.deletable\" role=\"menuitem\" type=\"delete\" class=\"dropdown-item\">Delete</a>\n                        </t>\n                        <t t-name=\"kanban-box\">\n                            <div class=\"oe_kanban_global_area oe_kanban_global_click o_kanban_attachment\">\n                                <div class=\"o_kanban_image\">\n                                    <div class=\"o_kanban_image_wrapper\">\n                                        <t t-set=\"webimage\" t-value=\"new RegExp(''image.*(gif|jpeg|jpg|png|webp)'').test(record.mimetype.value)\"/>\n                                        <div t-if=\"record.type.raw_value == ''url''\" class=\"o_url_image fa fa-link fa-3x text-muted\" aria-label=\"Image is a link\"/>\n                                        <img t-elif=\"webimage\" t-attf-src=\"/web/image/#{record.id.raw_value}\" width=\"100\" height=\"100\" alt=\"Document\" class=\"o_attachment_image\"/>\n                                        <div t-else=\"!webimage\" class=\"o_image o_image_thumbnail\" t-att-data-mimetype=\"record.mimetype.value\"/>\n                                    </div>\n                                </div>\n                                <div class=\"o_kanban_details\">\n                                    <div class=\"o_kanban_details_wrapper\">\n                                        <div t-att-title=\"record.name.raw_value\" class=\"o_kanban_record_title\">\n                                            <field name=\"name\" class=\"o_text_overflow\"/>\n                                        </div>\n                                        <div class=\"o_kanban_record_body\">\n                                            <t t-if=\"record.type.raw_value == ''url''\">\n                                                <span class=\"o_document_url\"><i class=\"fa fa-globe\" aria-label=\"Document url\"/> <field name=\"url\" widget=\"url\"/></span>\n                                            </t>\n                                            <samp t-else=\"\" class=\"text-muted\"> </samp>\n                                        </div>\n                                        <div class=\"o_kanban_record_bottom\">\n                                            <time class=\"oe_kanban_bottom_left\">\n                                                <field name=\"create_date\" widget=\"date\"/>\n                                            </time>\n                                            <div class=\"oe_kanban_bottom_right\">\n                                                <field name=\"create_uid\" widget=\"many2one_avatar_user\"/>\n                                            </div>\n                                        </div>\n                                    </div>\n                                </div>\n                            </div>\n                        </t>\n                    </templates>\n                </kanban>"}', '<?xml version="1.0"?>
<kanban edit="false" import="false">
                    <field name="id"/>
                    <field name="mimetype"/>
                    <field name="type"/>
                    <field name="create_uid"/>
                    <field name="url"/>
                    <field name="create_date"/>
                    <field name="name"/>
                    <templates>
                        <t t-name="kanban-menu">
                            <a t-attf-href="/web/content/ir.attachment/#{record.id.raw_value}/datas?download=true" download="" class="dropdown-item">Download</a>
                            <a t-if="widget.deletable" role="menuitem" type="delete" class="dropdown-item">Delete</a>
                        </t>
                        <t t-name="kanban-box">
                            <div class="oe_kanban_global_area oe_kanban_global_click o_kanban_attachment">
                                <div class="o_kanban_image">
                                    <div class="o_kanban_image_wrapper">
                                        <t t-set="webimage" t-value="new RegExp(''image.*(gif|jpeg|jpg|png|webp)'').test(record.mimetype.value)"/>
                                        <div t-if="record.type.raw_value == ''url''" class="o_url_image fa fa-link fa-3x text-muted" aria-label="Image is a link"/>
                                        <img t-elif="webimage" t-attf-src="/web/image/#{record.id.raw_value}" width="100" height="100" alt="Document" class="o_attachment_image"/>
                                        <div t-else="!webimage" class="o_image o_image_thumbnail" t-att-data-mimetype="record.mimetype.value"/>
                                    </div>
                                </div>
                                <div class="o_kanban_details">
                                    <div class="o_kanban_details_wrapper">
                                        <div t-att-title="record.name.raw_value" class="o_kanban_record_title">
                                            <field name="name" class="o_text_overflow"/>
                                        </div>
                                        <div class="o_kanban_record_body">
                                            <t t-if="record.type.raw_value == ''url''">
                                                <span class="o_document_url"><i class="fa fa-globe" aria-label="Document url"/> <field name="url" widget="url"/></span>
                                            </t>
                                            <samp t-else="" class="text-muted"> </samp>
                                        </div>
                                        <div class="o_kanban_record_bottom">
                                            <time class="oe_kanban_bottom_left">
                                                <field name="create_date" widget="date"/>
                                            </time>
                                            <div class="oe_kanban_bottom_right">
                                                <field name="create_uid" widget="many2one_avatar_user"/>
                                            </div>
                                        </div>
                                    </div>
                                </div>
                            </div>
                        </t>
                    </templates>
                </kanban>
            ', false, true, '2026-05-10 01:11:43.555423', '2026-05-10 01:11:43.555423', NULL);
INSERT INTO public.ir_ui_view VALUES (310, 16, NULL, 1, 1, 'mail.message.schedule.view.form', 'mail.message.schedule', NULL, 'form', 'mail/views/mail_message_schedule_views.xml', 'primary', '{"en_US": "<form string=\"Scheduled Message\" duplicate=\"0\">\n                <header>\n                    <button name=\"force_send\" string=\"Force Send\" type=\"object\"/>\n                </header>\n                <sheet>\n                    <group>\n                        <field name=\"mail_message_id\"/>\n                        <field name=\"scheduled_datetime\"/>\n                    </group>\n                    <group>\n                        <field name=\"notification_parameters\"/>\n                    </group>\n                </sheet>\n            </form>"}', '<?xml version="1.0"?>
