INSERT INTO public.ir_ui_view VALUES (313, 16, NULL, 1, 1, 'mail.mail.form', 'mail.mail', NULL, 'form', 'mail/views/mail_mail_views.xml', 'primary', '{"en_US": "<form string=\"Email message\" duplicate=\"0\">\n                    <header>\n                        <field name=\"message_type\" invisible=\"1\"/>\n                        <button name=\"send\" string=\"Send Now\" type=\"object\" class=\"oe_highlight\" invisible=\"state != ''outgoing'' or message_type == ''user_notification''\"/>\n                        <button name=\"mark_outgoing\" string=\"Retry\" type=\"object\" invisible=\"state not in (''exception'', ''cancel'')\"/>\n                        <button name=\"cancel\" string=\"Cancel\" type=\"object\" invisible=\"state != ''outgoing''\"/>\n                        <field name=\"state\" widget=\"statusbar\" statusbar_visible=\"outgoing,sent,received,exception,cancel\"/>\n                    </header>\n                    <sheet>\n                        <field name=\"model\" invisible=\"1\"/>\n                        <field name=\"res_id\" invisible=\"1\"/>\n                        <div class=\"oe_button_box\" name=\"button_box\">\n                            <button name=\"action_open_document\" type=\"object\" class=\"oe_link\" icon=\"fa-file-text-o\" invisible=\"not model or res_id == 0\">\n                                    <div class=\"o_field_widget o_stat_info\">\n                                        <span class=\"o_stat_text\">Open Document</span>\n                                    </div>\n                            </button>\n                        </div>\n                        <field name=\"mail_message_id_int\" required=\"0\" invisible=\"1\"/>\n                        <div class=\"oe_title\">\n                            <label for=\"subject\" class=\"oe_edit_only\"/>\n                            <h2><field name=\"subject\"/></h2>\n                        </div>\n                        <div style=\"vertical-align: top;\">\n                            by <field name=\"author_id\" class=\"oe_inline\" string=\"User\"/> on <field name=\"date\" readonly=\"1\" class=\"oe_inline\"/>\n                            <button name=\"103\" string=\"Reply\" type=\"action\" icon=\"fa-reply text-warning\" context=\"{''default_composition_mode'':''comment'', ''default_parent_id'': mail_message_id_int}\" invisible=\"state not in (''received'', ''sent'', ''exception'', ''cancel'')\"/>\n                        </div>\n                        <group>\n                            <field name=\"email_from\"/>\n                            <field name=\"email_to\"/>\n                            <field name=\"recipient_ids\" widget=\"many2many_tags\" domain=\"[(''active'', ''='', True)]\"/>\n                            <field name=\"email_cc\"/>\n                            <field name=\"reply_to\"/>\n                            <field name=\"scheduled_date\" placeholder=\"YYYY-MM-DD HH:MM:SS\"/>\n                        </group>\n                        <notebook>\n                            <page string=\"Body\" name=\"body\">\n                                <field name=\"body_content\"/>\n                                <field name=\"body_html\" invisible=\"1\"/><!--to be removed-->\n                            </page>\n                            <page string=\"Advanced\" name=\"advanced\" groups=\"base.group_no_one\">\n                                <group>\n                                    <group string=\"Status\">\n                                        <field name=\"auto_delete\" invisible=\"state != ''outgoing'' and state != ''exception''\"/>\n                                        <field name=\"is_notification\"/>\n                                        <field name=\"message_type\"/>\n                                        <field name=\"mail_server_id\"/>\n                                        <field name=\"model\"/>\n                                        <field name=\"res_id\"/>\n                                    </group>\n                                    <group string=\"Headers\">\n                                        <field name=\"message_id\"/>\n                                        <field name=\"references\"/>\n                                        <field name=\"fetchmail_server_id\"/>\n                                        <field name=\"headers\"/>\n                                    </group>\n                                </group>\n                            </page>\n                            <page string=\"Attachments\" name=\"attachments\">\n                                <div class=\"alert alert-warning\" role=\"alert\" invisible=\"restricted_attachment_count == 0\">\n                                    You do not have access to <field name=\"restricted_attachment_count\"/>\n                                    attachment(s) of this email.\n                                </div>\n                                <field name=\"unrestricted_attachment_ids\" domain=\"[(''res_field'',''='', False)]\"/>\n                            </page>\n                            <page string=\"Failure Reason\" name=\"failure_reason\" invisible=\"state != ''exception''\">\n                                <field name=\"failure_reason\"/>\n                            </page>\n                        </notebook>\n                    </sheet>\n                </form>"}', '<?xml version="1.0"?>
<form string="Email message" duplicate="0">
                    <header>
                        <field name="message_type" invisible="1"/>
                        <button name="send" string="Send Now" type="object" class="oe_highlight" invisible="state != ''outgoing'' or message_type == ''user_notification''"/>
                        <button name="mark_outgoing" string="Retry" type="object" invisible="state not in (''exception'', ''cancel'')"/>
                        <button name="cancel" string="Cancel" type="object" invisible="state != ''outgoing''"/>
                        <field name="state" widget="statusbar" statusbar_visible="outgoing,sent,received,exception,cancel"/>
                    </header>
                    <sheet>
                        <field name="model" invisible="1"/>
                        <field name="res_id" invisible="1"/>
                        <div class="oe_button_box" name="button_box">
                            <button name="action_open_document" type="object" class="oe_link" icon="fa-file-text-o" invisible="not model or res_id == 0">
                                    <div class="o_field_widget o_stat_info">
                                        <span class="o_stat_text">Open Document</span>
                                    </div>
                            </button>
                        </div>
                        <field name="mail_message_id_int" required="0" invisible="1"/>
                        <div class="oe_title">
                            <label for="subject" class="oe_edit_only"/>
                            <h2><field name="subject"/></h2>
                        </div>
                        <div style="vertical-align: top;">
                            by <field name="author_id" class="oe_inline" string="User"/> on <field name="date" readonly="1" class="oe_inline"/>
                            <button name="103" string="Reply" type="action" icon="fa-reply text-warning" context="{''default_composition_mode'':''comment'', ''default_parent_id'': mail_message_id_int}" invisible="state not in (''received'', ''sent'', ''exception'', ''cancel'')"/>
                        </div>
                        <group>
                            <field name="email_from"/>
                            <field name="email_to"/>
                            <field name="recipient_ids" widget="many2many_tags" domain="[(''active'', ''='', True)]"/>
                            <field name="email_cc"/>
                            <field name="reply_to"/>
                            <field name="scheduled_date" placeholder="YYYY-MM-DD HH:MM:SS"/>
                        </group>
                        <notebook>
                            <page string="Body" name="body">
                                <field name="body_content"/>
                                <field name="body_html" invisible="1"/><!--to be removed-->
                            </page>
                            <page string="Advanced" name="advanced" groups="base.group_no_one">
                                <group>
                                    <group string="Status">
                                        <field name="auto_delete" invisible="state != ''outgoing'' and state != ''exception''"/>
                                        <field name="is_notification"/>
                                        <field name="message_type"/>
                                        <field name="mail_server_id"/>
                                        <field name="model"/>
                                        <field name="res_id"/>
                                    </group>
                                    <group string="Headers">
                                        <field name="message_id"/>
                                        <field name="references"/>
                                        <field name="fetchmail_server_id"/>
                                        <field name="headers"/>
                                    </group>
                                </group>
                            </page>
                            <page string="Attachments" name="attachments">
                                <div class="alert alert-warning" role="alert" invisible="restricted_attachment_count == 0">
                                    You do not have access to <field name="restricted_attachment_count"/>
                                    attachment(s) of this email.
                                </div>
                                <field name="unrestricted_attachment_ids" domain="[(''res_field'',''='', False)]"/>
                            </page>
                            <page string="Failure Reason" name="failure_reason" invisible="state != ''exception''">
                                <field name="failure_reason"/>
                            </page>
                        </notebook>
                    </sheet>
                </form>
            ', false, true, '2026-05-10 01:11:43.555423', '2026-05-10 01:11:43.555423', NULL);
INSERT INTO public.ir_ui_view VALUES (314, 16, NULL, 1, 1, 'mail.mail.tree', 'mail.mail', NULL, 'tree', 'mail/views/mail_mail_views.xml', 'primary', '{"en_US": "<tree string=\"Emails\">\n                    <header>\n                        <button name=\"action_retry\" string=\"Retry\" type=\"object\"/>\n                    </header>\n                    <field name=\"date\"/>\n                    <field name=\"subject\"/>\n                    <field name=\"author_id\" string=\"User\"/>\n                    <field name=\"message_id\" column_invisible=\"True\"/>\n                    <field name=\"recipient_ids\" column_invisible=\"True\"/>\n                    <field name=\"model\" column_invisible=\"True\"/>\n                    <field name=\"res_id\" column_invisible=\"True\"/>\n                    <field name=\"email_from\" column_invisible=\"True\"/>\n                    <field name=\"message_type\" column_invisible=\"True\"/>\n                    <field name=\"state\" widget=\"badge\" decoration-muted=\"state in (''sent'', ''cancel'')\" decoration-info=\"state==''outgoing''\" decoration-danger=\"state==''exception''\"/>\n                    <button name=\"send\" string=\"Send Now\" type=\"object\" icon=\"fa-paper-plane\" invisible=\"state != ''outgoing'' or message_type == ''user_notification''\"/>\n                    <button name=\"mark_outgoing\" string=\"Retry\" type=\"object\" icon=\"fa-repeat\" invisible=\"state not in (''exception'', ''cancel'')\"/>\n                    <button name=\"cancel\" string=\"Cancel Email\" type=\"object\" icon=\"fa-times-circle\" invisible=\"state != ''outgoing''\"/>\n                </tree>"}', '<?xml version="1.0"?>
<tree string="Emails">
                    <header>
                        <button name="action_retry" string="Retry" type="object"/>
                    </header>
                    <field name="date"/>
                    <field name="subject"/>
                    <field name="author_id" string="User"/>
                    <field name="message_id" column_invisible="True"/>
                    <field name="recipient_ids" column_invisible="True"/>
                    <field name="model" column_invisible="True"/>
                    <field name="res_id" column_invisible="True"/>
                    <field name="email_from" column_invisible="True"/>
                    <field name="message_type" column_invisible="True"/>
                    <field name="state" widget="badge" decoration-muted="state in (''sent'', ''cancel'')" decoration-info="state==''outgoing''" decoration-danger="state==''exception''"/>
                    <button name="send" string="Send Now" type="object" icon="fa-paper-plane" invisible="state != ''outgoing'' or message_type == ''user_notification''"/>
                    <button name="mark_outgoing" string="Retry" type="object" icon="fa-repeat" invisible="state not in (''exception'', ''cancel'')"/>
                    <button name="cancel" string="Cancel Email" type="object" icon="fa-times-circle" invisible="state != ''outgoing''"/>
                </tree>
            ', false, true, '2026-05-10 01:11:43.555423', '2026-05-10 01:11:43.555423', NULL);
INSERT INTO public.ir_ui_view VALUES (315, 16, NULL, 1, 1, 'mail.mail.search', 'mail.mail', NULL, 'search', 'mail/views/mail_mail_views.xml', 'primary', '{"en_US": "<search string=\"Email Search\">\n                    <field name=\"email_from\" filter_domain=\"[''|'', ''|'',(''email_from'',''ilike'',self), (''email_to'',''ilike'',self), (''subject'',''ilike'',self)]\" string=\"Email\"/>\n                    <field name=\"date\"/>\n                    <filter name=\"received\" string=\"Received\" domain=\"[(''state'',''='',''received'')]\"/>\n                    <filter name=\"outgoing\" string=\"Outgoing\" domain=\"[(''state'',''='',''outgoing'')]\"/>\n                    <filter name=\"sent\" string=\"Sent\" domain=\"[(''state'',''='',''sent'')]\"/>\n                    <filter name=\"exception\" string=\"Failed\" domain=\"[(''state'',''='',''exception'')]\"/>\n                    <separator/>\n                    <filter name=\"filter_type_email_outgoing\" string=\"Outgoing Email\" domain=\"[(''message_type'',''='',''email_outgoing'')]\"/>\n                    <filter name=\"filter_type_email\" string=\"Incoming Email\" domain=\"[(''message_type'',''='',''email'')]\"/>\n                    <filter name=\"filter_type_comment\" string=\"Comment\" domain=\"[(''message_type'',''='',''comment'')]\"/>\n                    <filter name=\"filter_type_notification\" string=\"Notification\" domain=\"[(''message_type'',''='',''notification'')]\"/>\n                    <group expand=\"0\" string=\"Extended Filters...\">\n                        <field name=\"author_id\"/>\n                        <field name=\"recipient_ids\"/>\n                        <field name=\"model\"/>\n                        <field name=\"res_id\"/>\n                    </group>\n                    <group expand=\"0\" string=\"Group By\">\n                        <filter string=\"Status\" name=\"status\" domain=\"[]\" context=\"{''group_by'':''state''}\"/>\n                        <filter string=\"Author\" name=\"author\" context=\"{''group_by'':''author_id''}\"/>\n                        <filter string=\"Thread\" name=\"thread\" domain=\"[]\" context=\"{''group_by'':''message_id''}\"/>\n                        <filter string=\"Date\" name=\"month\" help=\"Creation Date\" domain=\"[]\" context=\"{''group_by'':''date''}\"/>\n                    </group>\n                </search>"}', '<?xml version="1.0"?>
<search string="Email Search">
                    <field name="email_from" filter_domain="[''|'', ''|'',(''email_from'',''ilike'',self), (''email_to'',''ilike'',self), (''subject'',''ilike'',self)]" string="Email"/>
                    <field name="date"/>
                    <filter name="received" string="Received" domain="[(''state'',''='',''received'')]"/>
                    <filter name="outgoing" string="Outgoing" domain="[(''state'',''='',''outgoing'')]"/>
                    <filter name="sent" string="Sent" domain="[(''state'',''='',''sent'')]"/>
                    <filter name="exception" string="Failed" domain="[(''state'',''='',''exception'')]"/>
                    <separator/>
                    <filter name="filter_type_email_outgoing" string="Outgoing Email" domain="[(''message_type'',''='',''email_outgoing'')]"/>
                    <filter name="filter_type_email" string="Incoming Email" domain="[(''message_type'',''='',''email'')]"/>
                    <filter name="filter_type_comment" string="Comment" domain="[(''message_type'',''='',''comment'')]"/>
                    <filter name="filter_type_notification" string="Notification" domain="[(''message_type'',''='',''notification'')]"/>
                    <group expand="0" string="Extended Filters...">
                        <field name="author_id"/>
                        <field name="recipient_ids"/>
                        <field name="model"/>
                        <field name="res_id"/>
                    </group>
                    <group expand="0" string="Group By">
                        <filter string="Status" name="status" domain="[]" context="{''group_by'':''state''}"/>
                        <filter string="Author" name="author" context="{''group_by'':''author_id''}"/>
                        <filter string="Thread" name="thread" domain="[]" context="{''group_by'':''message_id''}"/>
                        <filter string="Date" name="month" help="Creation Date" domain="[]" context="{''group_by'':''date''}"/>
                    </group>
                </search>
            ', false, true, '2026-05-10 01:11:43.555423', '2026-05-10 01:11:43.555423', NULL);
