INSERT INTO public.ir_ui_view VALUES (329, 10, NULL, 1, 1, 'discuss.channel.kanban', 'discuss.channel', NULL, 'kanban', 'mail/views/discuss_channel_views.xml', 'primary', '{"en_US": "<kanban>\n                    <field name=\"id\"/>\n                    <field name=\"description\"/>\n                    <field name=\"is_member\"/>\n                    <field name=\"group_ids\"/>\n                    <field name=\"active\"/>\n                    <templates>\n                        <t t-name=\"kanban-description\">\n                            <div class=\"oe_group_description\" t-if=\"record.description.raw_value\">\n                                <field name=\"description\"/>\n                            </div>\n                        </t>\n                        <t t-name=\"kanban-box\">\n                            <div class=\"o_discuss_channel_kanban oe_module_vignette oe_kanban_global_click\">\n                                <div class=\"ribbon ribbon-top-right o_small\" invisible=\"active\">\n                                    <span class=\"text-bg-danger\">Archived</span>\n                                </div>\n                                <div class=\"d-flex align-items-center\">\n                                    <img t-att-src=\"kanban_image(''discuss.channel'', ''avatar_128'', record.id.raw_value)\" class=\"oe_module_icon\" alt=\"Channel\"/>\n                                    <div class=\"oe_module_desc\">\n                                        <h4 class=\"o_kanban_record_title\">#<field name=\"name\"/></h4>\n                                        <field name=\"channel_type\" groups=\"base.group_no_one\"/>\n                                        <p class=\"oe_module_name\" t-att-class=\"!record.active.raw_value ? ''o_module_desc_short'': ''''\">\n                                            <field name=\"description\"/>\n                                        </p>\n                                        <button type=\"object\" invisible=\"is_member or group_ids\" class=\"btn btn-primary float-end\" name=\"channel_join\">Join</button>\n                                        <button type=\"object\" invisible=\"not is_member or group_ids\" class=\"btn btn-secondary float-end\" name=\"action_unfollow\">Leave</button>\n                                    </div>\n                                </div>\n                            </div>\n                        </t>\n                    </templates>\n                </kanban>"}', '<?xml version="1.0"?>
<kanban>
                    <field name="id"/>
                    <field name="description"/>
                    <field name="is_member"/>
                    <field name="group_ids"/>
                    <field name="active"/>
                    <templates>
                        <t t-name="kanban-description">
                            <div class="oe_group_description" t-if="record.description.raw_value">
                                <field name="description"/>
                            </div>
                        </t>
                        <t t-name="kanban-box">
                            <div class="o_discuss_channel_kanban oe_module_vignette oe_kanban_global_click">
                                <div class="ribbon ribbon-top-right o_small" invisible="active">
                                    <span class="text-bg-danger">Archived</span>
                                </div>
                                <div class="d-flex align-items-center">
                                    <img t-att-src="kanban_image(''discuss.channel'', ''avatar_128'', record.id.raw_value)" class="oe_module_icon" alt="Channel"/>
                                    <div class="oe_module_desc">
                                        <h4 class="o_kanban_record_title">#<field name="name"/></h4>
                                        <field name="channel_type" groups="base.group_no_one"/>
                                        <p class="oe_module_name" t-att-class="!record.active.raw_value ? ''o_module_desc_short'': ''''">
                                            <field name="description"/>
                                        </p>
                                        <button type="object" invisible="is_member or group_ids" class="btn btn-primary float-end" name="channel_join">Join</button>
                                        <button type="object" invisible="not is_member or group_ids" class="btn btn-secondary float-end" name="action_unfollow">Leave</button>
                                    </div>
                                </div>
                            </div>
                        </t>
                    </templates>
                </kanban>
            ', false, true, '2026-05-10 01:11:43.555423', '2026-05-10 01:11:43.555423', NULL);
INSERT INTO public.ir_ui_view VALUES (330, 10, NULL, 1, 1, 'discuss.channel.form', 'discuss.channel', NULL, 'form', 'mail/views/discuss_channel_views.xml', 'primary', '{"en_US": "<form string=\"Mail Channel Form\">\n                    <sheet>\n                        <div class=\"oe_button_box\" name=\"button_box\"/>\n                        <field name=\"avatar_128\" invisible=\"1\"/>\n                        <field name=\"is_editable\" invisible=\"1\"/>\n                        <field name=\"image_128\" widget=\"image\" class=\"oe_avatar\" options=\"{''size'': [90, 90], ''preview_image'':''avatar_128''}\" readonly=\"not is_editable\"/>\n                        <widget name=\"web_ribbon\" title=\"Archived\" bg_color=\"text-bg-danger\" invisible=\"active\"/>\n                        <div class=\"oe_title\">\n                            <label for=\"name\" string=\"Group Name\"/>\n                            <h1>\n                                #<field name=\"name\" class=\"oe_inline\" default_focus=\"1\" placeholder=\"e.g. support\" readonly=\"0\"/>\n                            </h1>\n                        </div>\n                        <group class=\"o_label_nowrap\">\n                            <field name=\"active\" invisible=\"1\"/>\n                            <field name=\"channel_type\" groups=\"base.group_no_one\"/>\n                            <field name=\"description\" placeholder=\"Topics discussed in this group...\"/>\n                        </group>\n                        <group class=\"o_label_nowrap\" groups=\"base.group_no_one\">\n                            <field name=\"sfu_channel_uuid\"/>\n                            <field name=\"sfu_server_url\"/>\n                        </group>\n                        <notebook>\n                            <page string=\"Privacy\" name=\"privacy\">\n                                <group class=\"o_label_nowrap\">\n                                    <field name=\"group_public_id\" invisible=\"channel_type != ''channel''\"/>\n                                    <field name=\"group_ids\" widget=\"many2many_tags\" invisible=\"channel_type != ''channel''\" string=\"Auto Subscribe Groups\"/>\n                                </group>\n                            </page>\n                            <page string=\"Members\" name=\"members\">\n                                <field name=\"channel_type\" invisible=\"1\"/>\n                                <field name=\"channel_member_ids\" mode=\"tree\" context=\"{''active_test'': False}\" readonly=\"channel_type == ''chat''\">\n                                    <tree string=\"Members\" editable=\"bottom\">\n                                        <field name=\"partner_id\" readonly=\"id or guest_id\" required=\"not guest_id\"/>\n                                        <field name=\"guest_id\" readonly=\"id or partner_id\" required=\"not partner_id\"/>\n                                    </tree>\n                                </field>\n                            </page>\n                            <page string=\"Integrations\" invisible=\"1\" name=\"discuss_channel_integrations\"/>\n                        </notebook>\n                    </sheet>\n                </form>"}', '<?xml version="1.0"?>
<form string="Mail Channel Form">
                    <sheet>
                        <div class="oe_button_box" name="button_box"/>
                        <field name="avatar_128" invisible="1"/>
                        <field name="is_editable" invisible="1"/>
                        <field name="image_128" widget="image" class="oe_avatar" options="{''size'': [90, 90], ''preview_image'':''avatar_128''}" readonly="not is_editable"/>
                        <widget name="web_ribbon" title="Archived" bg_color="text-bg-danger" invisible="active"/>
                        <div class="oe_title">
                            <label for="name" string="Group Name"/>
                            <h1>
                                #<field name="name" class="oe_inline" default_focus="1" placeholder="e.g. support" readonly="0"/>
                            </h1>
                        </div>
                        <group class="o_label_nowrap">
                            <field name="active" invisible="1"/>
                            <field name="channel_type" groups="base.group_no_one"/>
                            <field name="description" placeholder="Topics discussed in this group..."/>
                        </group>
                        <group class="o_label_nowrap" groups="base.group_no_one">
                            <field name="sfu_channel_uuid"/>
                            <field name="sfu_server_url"/>
                        </group>
                        <notebook>
                            <page string="Privacy" name="privacy">
                                <group class="o_label_nowrap">
                                    <field name="group_public_id" invisible="channel_type != ''channel''"/>
                                    <field name="group_ids" widget="many2many_tags" invisible="channel_type != ''channel''" string="Auto Subscribe Groups"/>
                                </group>
                            </page>
                            <page string="Members" name="members">
                                <field name="channel_type" invisible="1"/>
                                <field name="channel_member_ids" mode="tree" context="{''active_test'': False}" readonly="channel_type == ''chat''">
                                    <tree string="Members" editable="bottom">
                                        <field name="partner_id" readonly="id or guest_id" required="not guest_id"/>
                                        <field name="guest_id" readonly="id or partner_id" required="not partner_id"/>
                                    </tree>
                                </field>
                            </page>
                            <page string="Integrations" invisible="1" name="discuss_channel_integrations"/>
                        </notebook>
                    </sheet>
                </form>
            ', false, true, '2026-05-10 01:11:43.555423', '2026-05-10 01:11:43.555423', NULL);
