INSERT INTO public.ir_ui_view VALUES (338, 16, NULL, 1, 1, 'mail.activity.type.search', 'mail.activity.type', NULL, 'search', 'mail/views/mail_activity_views.xml', 'primary', '{"en_US": "<search string=\"Activities\">\n                <field name=\"name\"/>\n                <filter string=\"Archived\" domain=\"[(''active'', ''='', False)]\" name=\"archived\"/>\n            </search>"}', '<?xml version="1.0"?>
