INSERT INTO public.ir_ui_view VALUES (339, 16, NULL, 1, 1, 'mail.activity.type.view.tree', 'mail.activity.type', NULL, 'tree', 'mail/views/mail_activity_views.xml', 'primary', '{"en_US": "<tree string=\"Activities\" sample=\"1\">\n                <field name=\"sequence\" widget=\"handle\"/>\n                <field name=\"name\"/>\n                <field name=\"summary\"/>\n                <field name=\"delay_label\" string=\"Planned in\" class=\"text-end\"/>\n                <field name=\"delay_from\" string=\"Type\"/>\n                <field name=\"res_model\" groups=\"base.group_no_one\"/>\n                <field name=\"icon\" groups=\"base.group_no_one\"/>\n            </tree>"}', '<?xml version="1.0"?>
