INSERT INTO public.ir_ui_view VALUES (340, 20, NULL, 1, 1, 'mail.activity.view.form.popup', 'mail.activity', NULL, 'form', 'mail/views/mail_activity_views.xml', 'primary', '{"en_US": "<form string=\"Log an Activity\" create=\"false\">\n                <sheet string=\"Activity\">\n                    <div class=\"oe_button_box\" name=\"button_box\" invisible=\"1\">\n                        <button name=\"action_open_document\" type=\"object\" class=\"oe_link\" icon=\"fa-file-text-o\" invisible=\"not res_model or res_id == 0\">\n                                <div class=\"o_field_widget o_stat_info\">\n                                    <span class=\"o_stat_text\">Open Document</span>\n                                </div>\n                        </button>\n                    </div>\n                    <group invisible=\"1\">\n                        <field name=\"activity_category\" invisible=\"1\"/>\n                        <field name=\"res_model\" invisible=\"1\"/>\n                        <field name=\"res_model_id\" invisible=\"1\"/>\n                        <field name=\"res_id\" invisible=\"1\"/>\n                        <field name=\"chaining_type\" invisible=\"1\"/>\n                        <field name=\"previous_activity_type_id\"/>\n                        <field name=\"has_recommended_activities\"/>\n                    </group>\n                    <group invisible=\"not has_recommended_activities\">\n                        <field name=\"recommended_activity_type_id\" widget=\"selection_badge\" domain=\"[(''previous_type_ids'', ''='', previous_activity_type_id)]\" string=\"Recommended Activities\"/>\n                    </group>\n                    <group>\n                        <group>\n                            <field name=\"activity_type_id\" required=\"1\" options=\"{''no_create'': True, ''no_open'': True}\"/>\n                            <field name=\"summary\" placeholder=\"e.g. Discuss proposal\"/>\n                        </group>\n                        <group>\n                            <field name=\"date_deadline\"/>\n                            <field name=\"user_id\" widget=\"many2one_avatar_user\"/>\n                        </group>\n                    </group>\n                    <field name=\"note\" class=\"oe-bordered-editor\" placeholder=\"Log a note...\"/>\n                    <footer>\n                        <field name=\"id\" invisible=\"1\"/>\n                        <button id=\"mail_activity_schedule\" string=\"Schedule\" close=\"1\" name=\"action_close_dialog\" type=\"object\" class=\"btn-primary\" invisible=\"id\" data-hotkey=\"q\"/>\n                        <button id=\"mail_activity_save\" string=\"Save\" name=\"action_close_dialog\" type=\"object\" class=\"btn-primary\" invisible=\"not id\" data-hotkey=\"q\"/>\n                        <button invisible=\"chaining_type == ''trigger''\" string=\"Mark as Done\" name=\"action_done\" type=\"object\" class=\"btn-secondary\" data-hotkey=\"w\" context=\"{''mail_activity_quick_update'': True}\"/>\n                        <button invisible=\"chaining_type == ''trigger''\" string=\"Done &amp; Schedule Next\" name=\"action_done_schedule_next\" type=\"object\" class=\"btn-secondary\" data-hotkey=\"z\" context=\"{''mail_activity_quick_update'': True}\"/>\n                        <button invisible=\"chaining_type == ''suggest''\" string=\"Done &amp; Launch Next\" name=\"action_done_schedule_next\" type=\"object\" class=\"btn-secondary\" data-hotkey=\"z\" context=\"{''mail_activity_quick_update'': True}\"/>\n                        <button string=\"Discard\" class=\"btn-secondary\" special=\"cancel\" data-hotkey=\"x\"/>\n                    </footer>\n                </sheet>\n            </form>"}', '<?xml version="1.0"?>
<form string="Log an Activity" create="false">
                <sheet string="Activity">
                    <div class="oe_button_box" name="button_box" invisible="1">
                        <button name="action_open_document" type="object" class="oe_link" icon="fa-file-text-o" invisible="not res_model or res_id == 0">
                                <div class="o_field_widget o_stat_info">
                                    <span class="o_stat_text">Open Document</span>
                                </div>
                        </button>
                    </div>
                    <group invisible="1">
                        <field name="activity_category" invisible="1"/>
                        <field name="res_model" invisible="1"/>
                        <field name="res_model_id" invisible="1"/>
                        <field name="res_id" invisible="1"/>
                        <field name="chaining_type" invisible="1"/>
                        <field name="previous_activity_type_id"/>
                        <field name="has_recommended_activities"/>
                    </group>
                    <group invisible="not has_recommended_activities">
                        <field name="recommended_activity_type_id" widget="selection_badge" domain="[(''previous_type_ids'', ''='', previous_activity_type_id)]" string="Recommended Activities"/>
                    </group>
                    <group>
                        <group>
                            <field name="activity_type_id" required="1" options="{''no_create'': True, ''no_open'': True}"/>
                            <field name="summary" placeholder="e.g. Discuss proposal"/>
                        </group>
                        <group>
                            <field name="date_deadline"/>
                            <field name="user_id" widget="many2one_avatar_user"/>
                        </group>
                    </group>
                    <field name="note" class="oe-bordered-editor" placeholder="Log a note..."/>
                    <footer>
                        <field name="id" invisible="1"/>
                        <button id="mail_activity_schedule" string="Schedule" close="1" name="action_close_dialog" type="object" class="btn-primary" invisible="id" data-hotkey="q"/>
                        <button id="mail_activity_save" string="Save" name="action_close_dialog" type="object" class="btn-primary" invisible="not id" data-hotkey="q"/>
                        <button invisible="chaining_type == ''trigger''" string="Mark as Done" name="action_done" type="object" class="btn-secondary" data-hotkey="w" context="{''mail_activity_quick_update'': True}"/>
                        <button invisible="chaining_type == ''trigger''" string="Done &amp; Schedule Next" name="action_done_schedule_next" type="object" class="btn-secondary" data-hotkey="z" context="{''mail_activity_quick_update'': True}"/>
                        <button invisible="chaining_type == ''suggest''" string="Done &amp; Launch Next" name="action_done_schedule_next" type="object" class="btn-secondary" data-hotkey="z" context="{''mail_activity_quick_update'': True}"/>
                        <button string="Discard" class="btn-secondary" special="cancel" data-hotkey="x"/>
                    </footer>
                </sheet>
            </form>
        ', false, true, '2026-05-10 01:11:43.555423', '2026-05-10 01:11:43.555423', NULL);
INSERT INTO public.ir_ui_view VALUES (341, 21, 340, 1, 1, 'mail.activity.view.form', 'mail.activity', NULL, 'form', 'mail/views/mail_activity_views.xml', 'primary', '{"en_US": "<data><field name=\"activity_type_id\" position=\"before\">\n                <field name=\"res_name\" readonly=\"1\" string=\"Document\"/>\n            </field>\n            <footer position=\"replace\"/>\n            <xpath expr=\"//div[hasclass(''oe_button_box'')]\" position=\"attributes\">\n                <attribute name=\"invisible\">0</attribute>\n            </xpath>\n        </data>"}', '<?xml version="1.0"?>
