INSERT INTO public.ir_ui_view VALUES (342, 32, NULL, 1, 1, 'mail.activity.view.form.without.record.access', 'mail.activity', NULL, 'form', 'mail/views/mail_activity_views.xml', 'primary', '{"en_US": "<form string=\"Log an Activity\" create=\"false\" delete=\"false\">\n                <sheet string=\"Activity\">\n                    <field name=\"res_model\" invisible=\"1\"/>\n                    <field name=\"display_name\" invisible=\"1\"/>\n                    <group>\n                        <group>\n                            <field name=\"activity_type_id\" required=\"1\" options=\"{''no_create'': True, ''no_open'': True}\"/>\n                            <field name=\"summary\" placeholder=\"e.g. Discuss proposal\"/>\n                        </group>\n                        <group>\n                            <field name=\"date_deadline\"/>\n                        </group>\n                    </group>\n                    <field name=\"note\" class=\"oe-bordered-editor\" placeholder=\"Log a note...\"/>\n                </sheet>\n            </form>"}', '<?xml version="1.0"?>
