INSERT INTO public.ir_ui_view VALUES (343, 16, NULL, 1, 1, 'mail.activity.view.search', 'mail.activity', NULL, 'search', 'mail/views/mail_activity_views.xml', 'primary', '{"en_US": "<search string=\"Activity\">\n                <field name=\"res_model\"/>\n                <field name=\"summary\"/>\n                <field name=\"activity_type_id\"/>\n                <filter invisible=\"1\" string=\"Late Activities\" name=\"activities_overdue\" domain=\"[(''date_deadline'', ''&lt;'', context_today().strftime(''%Y-%m-%d''))]\" help=\"Show all records which has next action date is before today\"/>\n                <filter invisible=\"1\" string=\"Today Activities\" name=\"activities_today\" domain=\"[(''date_deadline'', ''='', context_today().strftime(''%Y-%m-%d''))]\"/>\n                <filter invisible=\"1\" string=\"Future Activities\" name=\"activities_upcoming_all\" domain=\"[(''date_deadline'', ''&gt;'', context_today().strftime(''%Y-%m-%d''))                         ]\"/>\n                <group expand=\"0\" string=\"Group By\">\n                    <filter string=\"Deadline\" name=\"date_deadline\" context=\"{''group_by'': ''date_deadline''}\"/>\n                    <filter string=\"Created By\" name=\"createdby\" context=\"{''group_by'': ''create_uid''}\"/>\n                    <filter string=\"Activity Type\" name=\"activittype\" context=\"{''group_by'': ''activity_type_id''}\"/>\n                </group>\n            </search>"}', '<?xml version="1.0"?>
<search string="Activity">
                <field name="res_model"/>
                <field name="summary"/>
                <field name="activity_type_id"/>
                <filter invisible="1" string="Late Activities" name="activities_overdue" domain="[(''date_deadline'', ''&lt;'', context_today().strftime(''%Y-%m-%d''))]" help="Show all records which has next action date is before today"/>
                <filter invisible="1" string="Today Activities" name="activities_today" domain="[(''date_deadline'', ''='', context_today().strftime(''%Y-%m-%d''))]"/>
                <filter invisible="1" string="Future Activities" name="activities_upcoming_all" domain="[(''date_deadline'', ''&gt;'', context_today().strftime(''%Y-%m-%d''))                         ]"/>
                <group expand="0" string="Group By">
                    <filter string="Deadline" name="date_deadline" context="{''group_by'': ''date_deadline''}"/>
                    <filter string="Created By" name="createdby" context="{''group_by'': ''create_uid''}"/>
                    <filter string="Activity Type" name="activittype" context="{''group_by'': ''activity_type_id''}"/>
                </group>
            </search>
        ', false, true, '2026-05-10 01:11:43.555423', '2026-05-10 01:11:43.555423', NULL);
INSERT INTO public.ir_ui_view VALUES (344, 16, NULL, 1, 1, 'mail.activity.view.tree', 'mail.activity', NULL, 'tree', 'mail/views/mail_activity_views.xml', 'primary', '{"en_US": "<tree string=\"Next Activities\" decoration-danger=\"date_deadline &lt; current_date\" decoration-success=\"date_deadline == current_date\" default_order=\"date_deadline\" create=\"false\">\n                <field name=\"res_name\"/>\n                <field name=\"activity_type_id\"/>\n                <field name=\"summary\"/>\n                <field name=\"date_deadline\"/>\n            </tree>"}', '<?xml version="1.0"?>
