INSERT INTO public.ir_ui_view VALUES (346, 2, NULL, 1, 1, 'mail.activity.view.calendar', 'mail.activity', NULL, 'calendar', 'mail/views/mail_activity_views.xml', 'primary', '{"en_US": "<calendar string=\"Activity\" date_start=\"date_deadline\" color=\"activity_type_id\">\n                <field name=\"user_id\" avatar_field=\"avatar_128\"/>\n                <field name=\"res_name\"/>\n                <field name=\"date_deadline\"/>\n                <field name=\"summary\"/>\n                <field name=\"activity_type_id\" filters=\"1\" invisible=\"1\"/>\n            </calendar>"}', '<?xml version="1.0"?>
