INSERT INTO public.ir_ui_view VALUES (349, 20, NULL, 1, 1, 'mail.activity.plan.view.form', 'mail.activity.plan', NULL, 'form', 'mail/views/mail_activity_plan_views.xml', 'primary', '{"en_US": "<form string=\"Planning\">\n                    <field name=\"company_id\" invisible=\"1\"/>\n                    <field name=\"active\" invisible=\"1\"/>\n                    <sheet>\n                        <widget name=\"web_ribbon\" title=\"Archived\" bg_color=\"text-bg-danger\" invisible=\"active\"/>\n                        <div class=\"oe_title\">\n                            <label for=\"name\" string=\"Plan Name\"/>\n                            <h1>\n                                <field name=\"name\" placeholder=\"e.g. Onboarding\"/>\n                            </h1>\n                        </div>\n                        <group>\n                            <group name=\"group_plan_fields\">\n                                <field name=\"company_id\" groups=\"base.group_multi_company\" placeholder=\"Available for all Companies\"/>\n                            </group>\n                        </group>\n                        <notebook>\n                            <page string=\"Activities To Generate\">\n                                <group name=\"plan_res_model\">\n                                    <field name=\"res_model\"/>\n                                </group>\n                                <field name=\"template_ids\" nolabel=\"1\">\n                                    <tree default_order=\"sequence, id\">\n                                        <field name=\"sequence\" widget=\"handle\"/>\n                                        <field name=\"activity_type_id\" context=\"{''form_view_ref'': ''mail.mail_activity_type_form_inherit''}\" options=\"{''no_quick_create'': True}\"/>\n                                        <field name=\"summary\"/>\n                                        <field name=\"responsible_type\"/>\n                                        <field name=\"responsible_id\" readonly=\"responsible_type != ''other''\"/>\n                                        <field name=\"note\"/>\n                                        <field name=\"company_id\" optional=\"hide\"/>\n                                    </tree>\n                                </field>\n                            </page>\n                        </notebook>\n                    </sheet>\n                </form>"}', '<?xml version="1.0"?>
<form string="Planning">
                    <field name="company_id" invisible="1"/>
                    <field name="active" invisible="1"/>
                    <sheet>
                        <widget name="web_ribbon" title="Archived" bg_color="text-bg-danger" invisible="active"/>
                        <div class="oe_title">
                            <label for="name" string="Plan Name"/>
                            <h1>
                                <field name="name" placeholder="e.g. Onboarding"/>
                            </h1>
                        </div>
                        <group>
                            <group name="group_plan_fields">
                                <field name="company_id" groups="base.group_multi_company" placeholder="Available for all Companies"/>
                            </group>
                        </group>
                        <notebook>
                            <page string="Activities To Generate">
                                <group name="plan_res_model">
                                    <field name="res_model"/>
                                </group>
                                <field name="template_ids" nolabel="1">
                                    <tree default_order="sequence, id">
                                        <field name="sequence" widget="handle"/>
                                        <field name="activity_type_id" context="{''form_view_ref'': ''mail.mail_activity_type_form_inherit''}" options="{''no_quick_create'': True}"/>
                                        <field name="summary"/>
                                        <field name="responsible_type"/>
                                        <field name="responsible_id" readonly="responsible_type != ''other''"/>
                                        <field name="note"/>
                                        <field name="company_id" optional="hide"/>
                                    </tree>
                                </field>
                            </page>
                        </notebook>
                    </sheet>
                </form>
            ', false, true, '2026-05-10 01:11:43.555423', '2026-05-10 01:11:43.555423', NULL);
INSERT INTO public.ir_ui_view VALUES (352, 16, NULL, 1, 1, 'mail.activity.plan.template.view.form', 'mail.activity.plan.template', NULL, 'form', 'mail/views/mail_activity_plan_template_views.xml', 'primary', '{"en_US": "<form string=\"Activity\">\n                    <field name=\"company_id\" invisible=\"1\"/>\n                    <field name=\"res_model\" invisible=\"1\"/>\n                    <sheet>\n                        <group>\n                            <field name=\"activity_type_id\" context=\"{''form_view_ref'': ''mail.mail_activity_type_form_inherit''}\"/>\n                            <field name=\"summary\"/>\n                            <field name=\"responsible_type\"/>\n                            <field name=\"responsible_id\" invisible=\"responsible_type != ''other''\"/>\n                            <field name=\"note\"/>\n                        </group>\n                    </sheet>\n                </form>"}', '<?xml version="1.0"?>
<form string="Activity">
                    <field name="company_id" invisible="1"/>
                    <field name="res_model" invisible="1"/>
                    <sheet>
                        <group>
                            <field name="activity_type_id" context="{''form_view_ref'': ''mail.mail_activity_type_form_inherit''}"/>
                            <field name="summary"/>
                            <field name="responsible_type"/>
                            <field name="responsible_id" invisible="responsible_type != ''other''"/>
                            <field name="note"/>
                        </group>
                    </sheet>
                </form>
            ', false, true, '2026-05-10 01:11:43.555423', '2026-05-10 01:11:43.555423', NULL);
INSERT INTO public.ir_ui_view VALUES (353, 16, 223, 1, 1, 'res.config.settings.view.form.inherit.mail', 'res.config.settings', NULL, 'form', 'mail/views/res_config_settings_views.xml', 'extension', '{"en_US": "<data><div id=\"emails\" position=\"replace\">\n                    <block title=\"Discuss\" id=\"emails\">\n                        <setting id=\"activities_setting\" string=\"Activities\" help=\"Configure your activity types\">\n                            <div class=\"content-group\">\n                                <div class=\"mt8\">\n                                    <button name=\"125\" string=\"Activity Types\" type=\"action\" class=\"oe_link\" icon=\"oi-arrow-right\"/>\n                                </div>\n                            </div>\n                        </setting>\n                        <setting id=\"email_servers_setting\" title=\"Using your own email server is required to send/receive emails in Community and Enterprise versions. Online users already benefit from a ready-to-use email server (@mycompany.odoo.com).\" documentation=\"/applications/general/email_communication/email_servers.html\" help=\"Configure your own email servers\">\n                            <field name=\"external_email_server_default\"/>\n                            <div class=\"content-group mb-3\" invisible=\"not external_email_server_default\">\n                                <div>\n                                    <div class=\"mt8\">\n                                        <button type=\"action\" name=\"108\" string=\"Incoming Email Servers\" icon=\"oi-arrow-right\" class=\"btn-link\"/>\n                                    </div>\n                                    <div class=\"mt8\">\n                                        <button type=\"action\" name=\"17\" string=\"Outgoing Email Servers\" icon=\"oi-arrow-right\" class=\"btn-link\"/>\n                                    </div>\n                                </div>\n                            </div>\n                        </setting>\n                        <setting id=\"email-alias-setting\" string=\"Alias Domain\" help=\"Use different domains for your mail aliases\" company_dependent=\"1\" documentation=\"/applications/general/email_communication/email_domain.html#be-spf-compliant\">\n                            <span class=\"me-1\">@</span>\n                            <field name=\"alias_domain_id\" placeholder=\"e.g. domain.com\" options=\"{''no_create_edit'': True}\"/>\n                        </setting>\n                        <setting string=\"Use a Gmail Server\" help=\"Send and receive emails through your Gmail account.\" documentation=\"https://console.developers.google.com/\" invisible=\"not external_email_server_default\">\n                            <field name=\"module_google_gmail\"/>\n                            <div class=\"content-group\" invisible=\"not module_google_gmail\" id=\"msg_module_google_gmail\">\n                                <div class=\"mt16 text-warning\"><strong>Save</strong> this page and come back here to set up the feature.</div>\n                            </div>\n                        </setting>\n                        <setting id=\"email-outlook-setting\" string=\"Use an Outlook Server\" help=\"Send and receive emails through your Outlook account.\" documentation=\"https://docs.microsoft.com/en-us/azure/active-directory/develop/quickstart-register-app\" invisible=\"not external_email_server_default\">\n                            <field name=\"module_microsoft_outlook\"/>\n                            <div class=\"content-group\" id=\"msg_module_microsoft_outlook\" invisible=\"not module_microsoft_outlook\">\n                                <div class=\"mt16 text-warning\">\n                                    <strong>Save</strong> this page and come back here to set up the feature.\n                                </div>\n                            </div>\n                        </setting>\n                        <setting help=\"Add your twilio credentials for ICE servers\">\n                            <field name=\"use_twilio_rtc_servers\"/>\n                            <div class=\"content-group\" invisible=\"not use_twilio_rtc_servers\">\n                                <div class=\"row mt16\" id=\"mail_twilio_sid\">\n                                    <label for=\"twilio_account_sid\" class=\"col-lg-3\"/>\n                                    <field name=\"twilio_account_sid\" placeholder=\"e.g. ACd5543a0b450ar4c7t95f1b6e8a39t543\"/>\n                                </div>\n                                <div class=\"row mt16\" id=\"mail_twilio_auth_token\">\n                                    <label for=\"twilio_account_token\" class=\"col-lg-3\"/>\n                                    <field name=\"twilio_account_token\" placeholder=\"e.g. 65ea4f9e948b693N5156F350256bd152\"/>\n                                </div>\n                            </div>\n                        </setting>\n                        <setting string=\"SFU server\">\n                            <div class=\"content-group\">\n                                <div class=\"row mt16\">\n                                    <label for=\"sfu_server_url\" string=\"URL\" class=\"col-lg-3\"/>\n                                    <field name=\"sfu_server_url\"/>\n                                </div>\n                                <div class=\"row mt16\">\n                                    <label for=\"sfu_server_key\" string=\"Key\" class=\"col-lg-3\"/>\n                                    <field name=\"sfu_server_key\"/>\n                                </div>\n                            </div>\n                        </setting>\n                        <setting string=\"Custom ICE server list\" help=\"Configure your ICE server list for webRTC\">\n                            <div class=\"content-group\">\n                                <div class=\"row col-lg-4\">\n                                    <button type=\"action\" name=\"117\" string=\"ICE Servers\" icon=\"oi-arrow-right\" class=\"btn-link\"/>\n                                </div>\n                            </div>\n                        </setting>\n                        <setting id=\"restrict_template_rendering_setting\" help=\"Restrict mail templates edition and QWEB placeholders usage.\">\n                            <field name=\"restrict_template_rendering\"/>\n                        </setting>\n                        <setting id=\"tenor_api_key\" string=\"Tenor GIF API key\" help=\"Add a Tenor GIF API key to enable GIFs support.\" documentation=\"https://developers.google.com/tenor/guides/quickstart#setup\">\n                            <field name=\"tenor_api_key\" placeholder=\"Paste your API key\"/>\n                        </setting>\n                        <setting id=\"tenor_content_filter\" string=\"Tenor GIF content filter\" help=\"Select the content filter used for filtering GIFs\" documentation=\"https://developers.google.com/tenor/guides/content-filtering\">\n                            <field name=\"tenor_content_filter\"/>\n                        </setting>\n                        <setting id=\"tenor_gif_limit\" string=\"Tenor GIF limits\" help=\"Fetch up to the specified number of GIF.\">\n                            <field name=\"tenor_gif_limit\"/>\n                        </setting>\n                        <setting string=\"Message Translation\" help=\"Google Translate Integration\" id=\"message_translation_setting\" documentation=\"https://cloud.google.com/translate/docs/setup\">\n                            <field name=\"google_translate_api_key\" placeholder=\"Paste your API key\"/>\n                        </setting>\n                    </block>\n                </div>\n                <setting id=\"document_layout_setting\" position=\"after\">\n                    <setting string=\"Email Templates\" help=\"Customize the look and feel of automated emails\" id=\"mail_templates_setting\" groups=\"mail.group_mail_template_editor,base.group_system\">\n                        <div class=\"w-50 row\">\n                            <span class=\"d-block w-75 py-2\">Header Color</span>\n                            <field name=\"email_primary_color\" class=\"d-block w-25 p-0 m-0\" widget=\"color\"/>\n                        </div>\n                        <div class=\"w-50 row mt-1\">\n                            <span class=\"d-block w-75 py-2\">Button Color</span>\n                            <field name=\"email_secondary_color\" class=\"d-block w-25 p-0 m-0\" widget=\"color\"/>\n                        </div>\n                        <button name=\"open_email_layout\" icon=\"oi-arrow-right\" type=\"object\" string=\"Update Mail Layout\" groups=\"base.group_no_one\" class=\"btn-link\"/>\n                        <br groups=\"base.group_no_one\"/>\n                        <button name=\"open_mail_templates\" icon=\"oi-arrow-right\" type=\"object\" string=\"Review All Templates\" class=\"btn-link\"/>\n                    </setting>\n                </setting>\n            </data>"}', '<?xml version="1.0"?>
<data><div id="emails" position="replace">
                    <block title="Discuss" id="emails">
                        <setting id="activities_setting" string="Activities" help="Configure your activity types">
                            <div class="content-group">
                                <div class="mt8">
                                    <button name="125" string="Activity Types" type="action" class="oe_link" icon="oi-arrow-right"/>
                                </div>
                            </div>
                        </setting>
                        <setting id="email_servers_setting" title="Using your own email server is required to send/receive emails in Community and Enterprise versions. Online users already benefit from a ready-to-use email server (@mycompany.odoo.com)." documentation="/applications/general/email_communication/email_servers.html" help="Configure your own email servers">
                            <field name="external_email_server_default"/>
                            <div class="content-group mb-3" invisible="not external_email_server_default">
                                <div>
                                    <div class="mt8">
                                        <button type="action" name="108" string="Incoming Email Servers" icon="oi-arrow-right" class="btn-link"/>
                                    </div>
                                    <div class="mt8">
                                        <button type="action" name="17" string="Outgoing Email Servers" icon="oi-arrow-right" class="btn-link"/>
                                    </div>
                                </div>
                            </div>
                        </setting>
                        <setting id="email-alias-setting" string="Alias Domain" help="Use different domains for your mail aliases" company_dependent="1" documentation="/applications/general/email_communication/email_domain.html#be-spf-compliant">
                            <span class="me-1">@</span>
                            <field name="alias_domain_id" placeholder="e.g. domain.com" options="{''no_create_edit'': True}"/>
                        </setting>
                        <setting string="Use a Gmail Server" help="Send and receive emails through your Gmail account." documentation="https://console.developers.google.com/" invisible="not external_email_server_default">
                            <field name="module_google_gmail"/>
                            <div class="content-group" invisible="not module_google_gmail" id="msg_module_google_gmail">
                                <div class="mt16 text-warning"><strong>Save</strong> this page and come back here to set up the feature.</div>
                            </div>
                        </setting>
                        <setting id="email-outlook-setting" string="Use an Outlook Server" help="Send and receive emails through your Outlook account." documentation="https://docs.microsoft.com/en-us/azure/active-directory/develop/quickstart-register-app" invisible="not external_email_server_default">
                            <field name="module_microsoft_outlook"/>
                            <div class="content-group" id="msg_module_microsoft_outlook" invisible="not module_microsoft_outlook">
                                <div class="mt16 text-warning">
                                    <strong>Save</strong> this page and come back here to set up the feature.
                                </div>
                            </div>
                        </setting>
                        <setting help="Add your twilio credentials for ICE servers">
                            <field name="use_twilio_rtc_servers"/>
                            <div class="content-group" invisible="not use_twilio_rtc_servers">
                                <div class="row mt16" id="mail_twilio_sid">
                                    <label for="twilio_account_sid" class="col-lg-3"/>
                                    <field name="twilio_account_sid" placeholder="e.g. ACd5543a0b450ar4c7t95f1b6e8a39t543"/>
                                </div>
                                <div class="row mt16" id="mail_twilio_auth_token">
                                    <label for="twilio_account_token" class="col-lg-3"/>
                                    <field name="twilio_account_token" placeholder="e.g. 65ea4f9e948b693N5156F350256bd152"/>
                                </div>
                            </div>
                        </setting>
                        <setting string="SFU server">
                            <div class="content-group">
                                <div class="row mt16">
                                    <label for="sfu_server_url" string="URL" class="col-lg-3"/>
                                    <field name="sfu_server_url"/>
                                </div>
                                <div class="row mt16">
                                    <label for="sfu_server_key" string="Key" class="col-lg-3"/>
                                    <field name="sfu_server_key"/>
                                </div>
                            </div>
                        </setting>
                        <setting string="Custom ICE server list" help="Configure your ICE server list for webRTC">
                            <div class="content-group">
                                <div class="row col-lg-4">
                                    <button type="action" name="117" string="ICE Servers" icon="oi-arrow-right" class="btn-link"/>
                                </div>
                            </div>
                        </setting>
                        <setting id="restrict_template_rendering_setting" help="Restrict mail templates edition and QWEB placeholders usage.">
                            <field name="restrict_template_rendering"/>
                        </setting>
                        <setting id="tenor_api_key" string="Tenor GIF API key" help="Add a Tenor GIF API key to enable GIFs support." documentation="https://developers.google.com/tenor/guides/quickstart#setup">
                            <field name="tenor_api_key" placeholder="Paste your API key"/>
                        </setting>
                        <setting id="tenor_content_filter" string="Tenor GIF content filter" help="Select the content filter used for filtering GIFs" documentation="https://developers.google.com/tenor/guides/content-filtering">
                            <field name="tenor_content_filter"/>
                        </setting>
                        <setting id="tenor_gif_limit" string="Tenor GIF limits" help="Fetch up to the specified number of GIF.">
                            <field name="tenor_gif_limit"/>
                        </setting>
                        <setting string="Message Translation" help="Google Translate Integration" id="message_translation_setting" documentation="https://cloud.google.com/translate/docs/setup">
                            <field name="google_translate_api_key" placeholder="Paste your API key"/>
                        </setting>
                    </block>
                </div>
                <setting id="document_layout_setting" position="after">
                    <setting string="Email Templates" help="Customize the look and feel of automated emails" id="mail_templates_setting" groups="mail.group_mail_template_editor,base.group_system">
                        <div class="w-50 row">
                            <span class="d-block w-75 py-2">Header Color</span>
                            <field name="email_primary_color" class="d-block w-25 p-0 m-0" widget="color"/>
                        </div>
                        <div class="w-50 row mt-1">
                            <span class="d-block w-75 py-2">Button Color</span>
                            <field name="email_secondary_color" class="d-block w-25 p-0 m-0" widget="color"/>
                        </div>
                        <button name="open_email_layout" icon="oi-arrow-right" type="object" string="Update Mail Layout" groups="base.group_no_one" class="btn-link"/>
                        <br groups="base.group_no_one"/>
                        <button name="open_mail_templates" icon="oi-arrow-right" type="object" string="Review All Templates" class="btn-link"/>
                    </setting>
                </setting>
            </data>', false, true, '2026-05-10 01:11:43.555423', '2026-05-10 01:11:43.555423', NULL);
INSERT INTO public.ir_ui_view VALUES (354, 16, NULL, 1, 1, 'message_user_assigned', NULL, 'mail.message_user_assigned', 'qweb', 'mail/data/mail_templates_chatter.xml', 'primary', '{"en_US": "<t t-name=\"mail.message_user_assigned\">\n    <span>Dear <t t-esc=\"object.user_id.sudo().name\"/>,</span>\n    <br/><br/>\n    <span style=\"margin-top: 8px;\">You have been assigned to the <t t-esc=\"model_description or ''document''\"/> <t t-esc=\"object.display_name\"/>.</span>\n    <br/>\n        </t>"}', '<?xml version="1.0"?>
<t t-name="mail.message_user_assigned">
    <span>Dear <t t-esc="object.user_id.sudo().name"/>,</span>
    <br/><br/>
    <span style="margin-top: 8px;">You have been assigned to the <t t-esc="model_description or ''document''"/> <t t-esc="object.display_name"/>.</span>
    <br/>
        </t>

        ', false, true, '2026-05-10 01:11:43.555423', '2026-05-10 01:11:43.555423', NULL);
INSERT INTO public.ir_ui_view VALUES (355, 16, NULL, 1, 1, 'message_activity_done', NULL, 'mail.message_activity_done', 'qweb', 'mail/data/mail_templates_chatter.xml', 'primary', '{"en_US": "<t t-name=\"mail.message_activity_done\">\n<div>\n    <p>\n        <span t-attf-class=\"fa #{activity.activity_type_id.icon} fa-fw\"/><span t-field=\"activity.activity_type_id.name\"/> done\n        <t t-if=\"display_assignee\"> (originally assigned to <span t-field=\"activity.user_id.name\"/>)</t>\n        <span t-if=\"activity.summary\">: </span><span t-if=\"activity.summary\" t-field=\"activity.summary\"/>\n    </p>\n    <div t-if=\"feedback\">\n        <t t-foreach=\"feedback.split(''\\n'')\" t-as=\"feedback_line\">\n            <t t-esc=\"feedback_line\"/>\n            <br t-if=\"not feedback_line_last\"/>\n        </t>\n    </div>\n    <t t-if=\"activity.note and activity.note != ''&lt;p&gt;&lt;br&gt;&lt;/p&gt;''\"><!-- <p></br></p> -->\n        <div class=\"o_mail_note_title\"><strong>Original note:</strong></div>\n        <div t-field=\"activity.note\"/>\n    </t>\n</div>\n        </t>"}', '<?xml version="1.0"?>
<t t-name="mail.message_activity_done">
<div>
    <p>
        <span t-attf-class="fa #{activity.activity_type_id.icon} fa-fw"/><span t-field="activity.activity_type_id.name"/> done
        <t t-if="display_assignee"> (originally assigned to <span t-field="activity.user_id.name"/>)</t>
        <span t-if="activity.summary">: </span><span t-if="activity.summary" t-field="activity.summary"/>
    </p>
    <div t-if="feedback">
        <t t-foreach="feedback.split(''\n'')" t-as="feedback_line">
            <t t-esc="feedback_line"/>
            <br t-if="not feedback_line_last"/>
        </t>
    </div>
    <t t-if="activity.note and activity.note != ''&lt;p&gt;&lt;br&gt;&lt;/p&gt;''"><!-- <p></br></p> -->
        <div class="o_mail_note_title"><strong>Original note:</strong></div>
        <div t-field="activity.note"/>
    </t>
</div>
        </t>

        ', false, true, '2026-05-10 01:11:43.555423', '2026-05-10 01:11:43.555423', NULL);
INSERT INTO public.ir_ui_view VALUES (356, 16, NULL, 1, 1, 'message_activity_assigned', NULL, 'mail.message_activity_assigned', 'qweb', 'mail/data/mail_templates_chatter.xml', 'primary', '{"en_US": "<t t-name=\"mail.message_activity_assigned\">\n<div style=\"margin: 0px; padding: 0px; font-size: 13px;\">\n    Dear <span t-field=\"activity.user_id.name\"/>,\n    <br/><br/>\n    <p>\n        <span t-field=\"activity.create_uid.name\"/> has just assigned you the following activity:\n        <ul>\n            <li>Document: \"<t t-esc=\"activity.res_name\"/>\"\n                <t t-if=\"model_description\"> (<t t-esc=\"model_description\"/>)</t>\n            </li>\n            <li t-if=\"activity.summary\">Summary: <span t-field=\"activity.summary\"/></li>\n            <li>Deadline: <span t-field=\"activity.date_deadline\"/></li>\n        </ul>\n    </p>\n</div>\n        </t>"}', '<?xml version="1.0"?>
<t t-name="mail.message_activity_assigned">
<div style="margin: 0px; padding: 0px; font-size: 13px;">
    Dear <span t-field="activity.user_id.name"/>,
    <br/><br/>
    <p>
        <span t-field="activity.create_uid.name"/> has just assigned you the following activity:
        <ul>
            <li>Document: "<t t-esc="activity.res_name"/>"
                <t t-if="model_description"> (<t t-esc="model_description"/>)</t>
            </li>
            <li t-if="activity.summary">Summary: <span t-field="activity.summary"/></li>
            <li>Deadline: <span t-field="activity.date_deadline"/></li>
        </ul>
    </p>
</div>
        </t>

        ', false, true, '2026-05-10 01:11:43.555423', '2026-05-10 01:11:43.555423', NULL);
INSERT INTO public.ir_ui_view VALUES (357, 16, NULL, 1, 1, 'message_origin_link', NULL, 'mail.message_origin_link', 'qweb', 'mail/data/mail_templates_chatter.xml', 'primary', '{"en_US": "<t t-name=\"mail.message_origin_link\">\n            <p>\n                <t t-if=\"edit\">This <t t-esc=\"self.env[''ir.model'']._get(self._name).name.lower()\"/> has been modified from:</t>\n                <t t-else=\"\">This <t t-esc=\"self.env[''ir.model'']._get(self._name).name.lower()\"/> has been created from:</t>\n                <t t-foreach=\"origin\" t-as=\"o\">\n                    <a href=\"#\" t-att-data-oe-model=\"o._name\" t-att-data-oe-id=\"o.id\"> <t t-esc=\"o.display_name\"/></a><span t-if=\"origin.ids[-1:] != o.ids\">, </span>\n                </t>\n            </p>\n        </t>"}', '<?xml version="1.0"?>
<t t-name="mail.message_origin_link">
            <p>
                <t t-if="edit">This <t t-esc="self.env[''ir.model'']._get(self._name).name.lower()"/> has been modified from:</t>
                <t t-else="">This <t t-esc="self.env[''ir.model'']._get(self._name).name.lower()"/> has been created from:</t>
                <t t-foreach="origin" t-as="o">
                    <a href="#" t-att-data-oe-model="o._name" t-att-data-oe-id="o.id"> <t t-esc="o.display_name"/></a><span t-if="origin.ids[-1:] != o.ids">, </span>
                </t>
            </p>
        </t>
    ', false, true, '2026-05-10 01:11:43.555423', '2026-05-10 01:11:43.555423', NULL);
INSERT INTO public.ir_ui_view VALUES (358, 16, NULL, 1, 1, 'Mail: mail notification layout template', NULL, 'mail.mail_notification_layout', 'qweb', 'mail/data/mail_templates_email_layouts.xml', 'primary', '{"en_US": "<t name=\"Mail: mail notification layout template\" t-name=\"mail.mail_notification_layout\">\n<html t-att-lang=\"lang\">\n<head>\n    <meta http-equiv=\"Content-Type\" content=\"text/html charset=UTF-8\"/>\n</head>\n<body style=\"font-family:Verdana, Arial,sans-serif; color: #454748;\">\n<t t-set=\"subtype_internal\" t-value=\"subtype and subtype.internal\"/>\n<!-- HEADER -->\n<t t-call=\"mail.notification_preview\"/>\n<div style=\"max-width: 900px; width: 100%;\">\n<div t-if=\"has_button_access\" itemscope=\"itemscope\" itemtype=\"http://schema.org/EmailMessage\">\n    <div itemprop=\"potentialAction\" itemscope=\"itemscope\" itemtype=\"http://schema.org/ViewAction\">\n        <link itemprop=\"target\" t-att-href=\"button_access[''url'']\"/>\n        <link itemprop=\"url\" t-att-href=\"button_access[''url'']\"/>\n        <meta itemprop=\"name\" t-att-content=\"button_access[''title'']\"/>\n    </div>\n</div>\n<div t-if=\"subtitles or has_button_access or actions or not is_discussion\" summary=\"o_mail_notification\" style=\"padding: 0px;\">\n    <table role=\"presentation\" cellspacing=\"0\" cellpadding=\"0\" border=\"0\" style=\"width: 100%; margin-top: 5px;\">\n        <tbody>\n            <tr>\n                <td valign=\"center\" t-if=\"company and not company.uses_default_logo\">\n                    <img t-att-src=\"''/logo.png?company=%s'' % company.id\" style=\"padding: 0px; margin: 0px; height: auto; max-width: 200px; max-height: 36px;\" t-att-alt=\"''%s'' % company.name\"/>\n                </td>\n            </tr>\n            <tr>\n                <td valign=\"center\">\n                    <hr width=\"100%\" style=\"background-color:rgb(204,204,204);border:medium none;clear:both;display:block;font-size:0px;min-height:1px;line-height:0; margin: 10px 0px;\"/>\n                </td>\n            </tr>\n            <tr>\n                <td valign=\"center\" style=\"white-space:nowrap;\">\n                    <table cellspacing=\"0\" cellpadding=\"0\" border=\"0\">\n                        <tbody>\n                            <tr>\n                                <td t-if=\"has_button_access\" t-att-style=\"''border-radius: 3px; text-align: center; background: '' + (company.email_secondary_color or ''#875A7B'') + '';''\">\n                                    <a t-att-href=\"button_access[''url'']\" style=\"font-size: 12px; color: #FFFFFF; display: block; padding: 8px 12px 11px; text-decoration: none !important; font-weight: 400;\">\n                                        <t t-out=\"button_access[''title'']\"/>\n                                    </a>\n                                </td>\n                                <td t-if=\"has_button_access\">&amp;nbsp;&amp;nbsp;</td>\n\n                                <td t-if=\"actions\">\n                                    <t t-foreach=\"actions\" t-as=\"action\">\n                                        <a t-att-href=\"action[''url'']\" t-att-style=\"''font-size: 12px; color: '' + (company.email_secondary_color or ''#875A7B'')+ ''; text-decoration:none !important;''\">\n                                            <t t-out=\"action[''title'']\"/>\n                                        </a>\n                                        &amp;nbsp;&amp;nbsp;\n                                    </t>\n                                </td>\n                                <td t-if=\"subtitles\" style=\"font-size: 12px;\">\n                                     <t t-foreach=\"subtitles\" t-as=\"subtitle\">\n                                        <span t-attf-style=\"{{ ''font-weight:bold;'' if subtitle_first else '''' }}\" t-out=\"subtitle\"/>\n                                        <br t-if=\"not subtitle_last\"/>\n                                    </t>\n                                </td>\n                                <td t-else=\"\"><span style=\"font-weight:bold;\" t-out=\"record_name\"/><br/></td>\n\n                            </tr>\n                        </tbody>\n                    </table>\n                </td>\n            </tr>\n            <tr>\n                <td valign=\"center\">\n                    <hr width=\"100%\" style=\"background-color:rgb(204,204,204);border:medium none;clear:both;display:block;font-size:0px;min-height:1px;line-height:0;margin: 10px 0px;\"/>\n                    <p t-if=\"subtype_internal\" style=\"background-color: #f2dede; padding: 5px; margin-bottom: 16px; font-size: 13px;\">\n                        <strong>Internal communication</strong>: Replying will post an internal note. Followers won''t receive any email notification.\n                    </p>\n                </td>\n            </tr>\n        </tbody>\n    </table>\n</div>\n<!-- CONTENT -->\n<div t-out=\"message.body\" style=\"font-size: 13px;\"/>\n<ul t-if=\"tracking_values\">\n    <t t-foreach=\"tracking_values\" t-as=\"tracking\">\n        <li><t t-out=\"tracking[0]\"/>: <t t-out=\"tracking[1]\"/> → <t t-out=\"tracking[2]\"/></li>\n    </t>\n</ul>\n<t class=\"o_signature\">\n    <div t-if=\"email_add_signature and not is_html_empty(signature)\" t-out=\"signature\" style=\"font-size: 13px;\"/>\n</t>\n<!-- FOOTER -->\n<div style=\"margin-top:32px;\">\n    <hr width=\"100%\" style=\"background-color:rgb(204,204,204);border:medium none;clear:both;display:block;font-size:0px;min-height:1px;line-height:0; margin: 16px 0px 4px 0px;\"/>\n    <b t-out=\"company.name\" style=\"font-size:11px;\"/><br/>\n    <p style=\"color: #999999; margin-top:2px; font-size:11px;\">\n        <t t-out=\"company.phone\"/>\n        <t t-if=\"company.email and company.phone\"> |</t>\n        <a t-if=\"company.email\" t-att-href=\"''mailto:%s'' % company.email\" style=\"text-decoration:none; color: #999999;\" t-out=\"company.email\"/>\n        <t t-if=\"company.website and (company.phone or company.email)\"> |</t>\n        <a t-if=\"company.website\" t-att-href=\"''%s'' % company.website\" style=\"text-decoration:none; color: #999999;\" t-out=\"company.website\"/>\n    </p>\n</div>\n<div style=\"color: #555555; font-size:11px;\">\n    Powered by <a target=\"_blank\" href=\"https://www.odoo.com?utm_source=db&amp;utm_medium=email\" t-att-style=\"''color: '' + (company.email_secondary_color or ''#875A7B'') + '';''\">Odoo</a>\n    <span id=\"mail_unfollow\">\n        | <a href=\"/mail/unfollow\" style=\"text-decoration:none; color:#555555;\">Unfollow</a>\n    </span>\n</div>\n</div>\n</body></html>\n        </t>"}', '<?xml version="1.0"?>
<t name="Mail: mail notification layout template" t-name="mail.mail_notification_layout">
<html t-att-lang="lang">
<head>
    <meta http-equiv="Content-Type" content="text/html charset=UTF-8"/>
</head>
<body style="font-family:Verdana, Arial,sans-serif; color: #454748;">
<t t-set="subtype_internal" t-value="subtype and subtype.internal"/>
<!-- HEADER -->
<t t-call="mail.notification_preview"/>
<div style="max-width: 900px; width: 100%;">
<div t-if="has_button_access" itemscope="itemscope" itemtype="http://schema.org/EmailMessage">
    <div itemprop="potentialAction" itemscope="itemscope" itemtype="http://schema.org/ViewAction">
        <link itemprop="target" t-att-href="button_access[''url'']"/>
        <link itemprop="url" t-att-href="button_access[''url'']"/>
        <meta itemprop="name" t-att-content="button_access[''title'']"/>
    </div>
</div>
<div t-if="subtitles or has_button_access or actions or not is_discussion" summary="o_mail_notification" style="padding: 0px;">
    <table role="presentation" cellspacing="0" cellpadding="0" border="0" style="width: 100%; margin-top: 5px;">
        <tbody>
            <tr>
                <td valign="center" t-if="company and not company.uses_default_logo">
                    <img t-att-src="''/logo.png?company=%s'' % company.id" style="padding: 0px; margin: 0px; height: auto; max-width: 200px; max-height: 36px;" t-att-alt="''%s'' % company.name"/>
                </td>
            </tr>
            <tr>
                <td valign="center">
                    <hr width="100%" style="background-color:rgb(204,204,204);border:medium none;clear:both;display:block;font-size:0px;min-height:1px;line-height:0; margin: 10px 0px;"/>
                </td>
            </tr>
            <tr>
                <td valign="center" style="white-space:nowrap;">
                    <table cellspacing="0" cellpadding="0" border="0">
                        <tbody>
                            <tr>
                                <td t-if="has_button_access" t-att-style="''border-radius: 3px; text-align: center; background: '' + (company.email_secondary_color or ''#875A7B'') + '';''">
                                    <a t-att-href="button_access[''url'']" style="font-size: 12px; color: #FFFFFF; display: block; padding: 8px 12px 11px; text-decoration: none !important; font-weight: 400;">
                                        <t t-out="button_access[''title'']"/>
                                    </a>
                                </td>
                                <td t-if="has_button_access">&amp;nbsp;&amp;nbsp;</td>

                                <td t-if="actions">
                                    <t t-foreach="actions" t-as="action">
                                        <a t-att-href="action[''url'']" t-att-style="''font-size: 12px; color: '' + (company.email_secondary_color or ''#875A7B'')+ ''; text-decoration:none !important;''">
                                            <t t-out="action[''title'']"/>
                                        </a>
                                        &amp;nbsp;&amp;nbsp;
                                    </t>
                                </td>
                                <td t-if="subtitles" style="font-size: 12px;">
                                     <t t-foreach="subtitles" t-as="subtitle">
                                        <span t-attf-style="{{ ''font-weight:bold;'' if subtitle_first else '''' }}" t-out="subtitle"/>
                                        <br t-if="not subtitle_last"/>
                                    </t>
                                </td>
                                <td t-else=""><span style="font-weight:bold;" t-out="record_name"/><br/></td>

                            </tr>
                        </tbody>
                    </table>
                </td>
            </tr>
            <tr>
                <td valign="center">
                    <hr width="100%" style="background-color:rgb(204,204,204);border:medium none;clear:both;display:block;font-size:0px;min-height:1px;line-height:0;margin: 10px 0px;"/>
                    <p t-if="subtype_internal" style="background-color: #f2dede; padding: 5px; margin-bottom: 16px; font-size: 13px;">
                        <strong>Internal communication</strong>: Replying will post an internal note. Followers won''t receive any email notification.
                    </p>
                </td>
            </tr>
        </tbody>
    </table>
</div>
<!-- CONTENT -->
<div t-out="message.body" style="font-size: 13px;"/>
<ul t-if="tracking_values">
    <t t-foreach="tracking_values" t-as="tracking">
        <li><t t-out="tracking[0]"/>: <t t-out="tracking[1]"/> → <t t-out="tracking[2]"/></li>
    </t>
</ul>
<t class="o_signature">
    <div t-if="email_add_signature and not is_html_empty(signature)" t-out="signature" style="font-size: 13px;"/>
</t>
<!-- FOOTER -->
<div style="margin-top:32px;">
    <hr width="100%" style="background-color:rgb(204,204,204);border:medium none;clear:both;display:block;font-size:0px;min-height:1px;line-height:0; margin: 16px 0px 4px 0px;"/>
    <b t-out="company.name" style="font-size:11px;"/><br/>
    <p style="color: #999999; margin-top:2px; font-size:11px;">
        <t t-out="company.phone"/>
        <t t-if="company.email and company.phone"> |</t>
        <a t-if="company.email" t-att-href="''mailto:%s'' % company.email" style="text-decoration:none; color: #999999;" t-out="company.email"/>
        <t t-if="company.website and (company.phone or company.email)"> |</t>
        <a t-if="company.website" t-att-href="''%s'' % company.website" style="text-decoration:none; color: #999999;" t-out="company.website"/>
    </p>
</div>
<div style="color: #555555; font-size:11px;">
    Powered by <a target="_blank" href="https://www.odoo.com?utm_source=db&amp;utm_medium=email" t-att-style="''color: '' + (company.email_secondary_color or ''#875A7B'') + '';''">Odoo</a>
    <span id="mail_unfollow">
        | <a href="/mail/unfollow" style="text-decoration:none; color:#555555;">Unfollow</a>
    </span>
</div>
</div>
</body></html>
        </t>

        ', false, true, '2026-05-10 01:11:43.555423', '2026-05-10 01:11:43.555423', NULL);
INSERT INTO public.ir_ui_view VALUES (359, 16, NULL, 1, 1, 'mail_notification_light', NULL, 'mail.mail_notification_light', 'qweb', 'mail/data/mail_templates_email_layouts.xml', 'primary', '{"en_US": "<t t-name=\"mail.mail_notification_light\">\n<html t-att-lang=\"lang\">\n<head>\n    <meta http-equiv=\"Content-Type\" content=\"text/html charset=UTF-8\"/>\n</head>\n<body>\n<t t-set=\"subtype_internal\" t-value=\"False\"/>\n<t t-call=\"mail.notification_preview\"/>\n<table role=\"presentation\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" style=\"padding-top: 16px; background-color: #F1F1F1; font-family:Verdana, Arial,sans-serif; color: #454748; width: 100%; border-collapse:separate;\"><tr><td align=\"center\">\n<table role=\"presentation\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"590\" style=\"padding: 24px; background-color: white; color: #454748; border-collapse:separate;\">\n<tbody>\n    <!-- HEADER -->\n    <tr>\n        <td align=\"center\" style=\"min-width: 590px;\">\n            <table role=\"presentation\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"100%\" style=\"background-color: white; padding: 0; border-collapse:separate;\">\n                <tr><td valign=\"middle\">\n                    <span style=\"font-size: 10px;\">Your <t t-out=\"model_description or ''document''\"/></span>\n                    <br/>\n                    <t t-if=\"has_button_access\">\n                        <a t-att-href=\"button_access[''url'']\">\n                            <span style=\"font-size: 20px; font-weight: bold;\">\n                                <t t-out=\"message.record_name and message.record_name.replace(''/'',''-'') or ''''\"/>\n                            </span>\n                        </a>\n                    </t>\n                    <t t-else=\"\">\n                        <span style=\"font-size: 20px; font-weight: bold;\">\n                            <t t-out=\"message.record_name and message.record_name.replace(''/'',''-'') or ''''\"/>\n                        </span>\n                    </t>\n                </td><td valign=\"middle\" align=\"right\" t-if=\"company and not company.uses_default_logo\">\n                    <img t-att-src=\"''/logo.png?company=%s'' % company.id\" style=\"padding: 0px; margin: 0px; height: 48px;\" t-att-alt=\"''%s'' % company.name\"/>\n                </td></tr>\n                <tr><td colspan=\"2\" style=\"text-align:center;\">\n                  <hr width=\"100%\" style=\"background-color:rgb(204,204,204);border:medium none;clear:both;display:block;font-size:0px;min-height:1px;line-height:0; margin:4px 0px 32px 0px;\"/>\n                </td></tr>\n            </table>\n        </td>\n    </tr>\n    <!-- CONTENT -->\n    <tr>\n        <td style=\"min-width: 590px;\">\n            <t t-out=\"message.body\"/>\n        </td>\n    </tr>\n    <!-- FOOTER -->\n    <tr>\n        <td align=\"center\" style=\"min-width: 590px; padding: 0 8px 0 8px; font-size:11px;\">\n            <hr width=\"100%\" style=\"background-color:rgb(204,204,204);border:medium none;clear:both;display:block;font-size:0px;min-height:1px;line-height:0; margin: 16px 0px 4px 0px;\"/>\n            <b t-out=\"company.name\"/><br/>\n            <div style=\"color: #999999;\">\n                <t t-out=\"company.phone\"/>\n                <t t-if=\"company.email and company.phone\"> |</t>\n                <a t-if=\"company.email\" t-att-href=\"''mailto:%s'' % company.email\" style=\"text-decoration:none; color: #999999;\" t-out=\"company.email\"/>\n                <t t-if=\"company.website and (company.phone or company.email)\"> |</t>\n                <a t-if=\"company.website\" t-att-href=\"''%s'' % company.website\" style=\"text-decoration:none; color: #999999;\" t-out=\"company.website\"/>\n            </div>\n        </td>\n    </tr>\n</tbody>\n</table>\n</td></tr>\n<!-- POWERED BY -->\n<tr><td align=\"center\" style=\"min-width: 590px;\">\n        Powered by <a target=\"_blank\" href=\"https://www.odoo.com?utm_source=db&amp;utm_medium=email\" t-att-style=\"''color: '' + (company.email_secondary_color or ''#875A7B'') + '';''\">Odoo</a>\n    <span id=\"mail_unfollow\">\n        | <a href=\"/mail/unfollow\" style=\"text-decoration:none; color:#555555;\">Unfollow</a>\n    </span>\n</td></tr>\n</table>\n</body>\n</html>\n        </t>"}', '<?xml version="1.0"?>
<t t-name="mail.mail_notification_light">
<html t-att-lang="lang">
<head>
    <meta http-equiv="Content-Type" content="text/html charset=UTF-8"/>
</head>
<body>
<t t-set="subtype_internal" t-value="False"/>
<t t-call="mail.notification_preview"/>
<table role="presentation" border="0" cellpadding="0" cellspacing="0" style="padding-top: 16px; background-color: #F1F1F1; font-family:Verdana, Arial,sans-serif; color: #454748; width: 100%; border-collapse:separate;"><tr><td align="center">
<table role="presentation" border="0" cellpadding="0" cellspacing="0" width="590" style="padding: 24px; background-color: white; color: #454748; border-collapse:separate;">
<tbody>
    <!-- HEADER -->
    <tr>
        <td align="center" style="min-width: 590px;">
            <table role="presentation" border="0" cellpadding="0" cellspacing="0" width="100%" style="background-color: white; padding: 0; border-collapse:separate;">
                <tr><td valign="middle">
                    <span style="font-size: 10px;">Your <t t-out="model_description or ''document''"/></span>
                    <br/>
                    <t t-if="has_button_access">
                        <a t-att-href="button_access[''url'']">
                            <span style="font-size: 20px; font-weight: bold;">
                                <t t-out="message.record_name and message.record_name.replace(''/'',''-'') or ''''"/>
                            </span>
                        </a>
                    </t>
                    <t t-else="">
                        <span style="font-size: 20px; font-weight: bold;">
                            <t t-out="message.record_name and message.record_name.replace(''/'',''-'') or ''''"/>
                        </span>
                    </t>
                </td><td valign="middle" align="right" t-if="company and not company.uses_default_logo">
                    <img t-att-src="''/logo.png?company=%s'' % company.id" style="padding: 0px; margin: 0px; height: 48px;" t-att-alt="''%s'' % company.name"/>
                </td></tr>
                <tr><td colspan="2" style="text-align:center;">
                  <hr width="100%" style="background-color:rgb(204,204,204);border:medium none;clear:both;display:block;font-size:0px;min-height:1px;line-height:0; margin:4px 0px 32px 0px;"/>
                </td></tr>
            </table>
        </td>
    </tr>
    <!-- CONTENT -->
    <tr>
        <td style="min-width: 590px;">
            <t t-out="message.body"/>
        </td>
    </tr>
    <!-- FOOTER -->
    <tr>
        <td align="center" style="min-width: 590px; padding: 0 8px 0 8px; font-size:11px;">
            <hr width="100%" style="background-color:rgb(204,204,204);border:medium none;clear:both;display:block;font-size:0px;min-height:1px;line-height:0; margin: 16px 0px 4px 0px;"/>
            <b t-out="company.name"/><br/>
            <div style="color: #999999;">
                <t t-out="company.phone"/>
                <t t-if="company.email and company.phone"> |</t>
                <a t-if="company.email" t-att-href="''mailto:%s'' % company.email" style="text-decoration:none; color: #999999;" t-out="company.email"/>
                <t t-if="company.website and (company.phone or company.email)"> |</t>
                <a t-if="company.website" t-att-href="''%s'' % company.website" style="text-decoration:none; color: #999999;" t-out="company.website"/>
            </div>
        </td>
    </tr>
</tbody>
</table>
</td></tr>
<!-- POWERED BY -->
<tr><td align="center" style="min-width: 590px;">
        Powered by <a target="_blank" href="https://www.odoo.com?utm_source=db&amp;utm_medium=email" t-att-style="''color: '' + (company.email_secondary_color or ''#875A7B'') + '';''">Odoo</a>
    <span id="mail_unfollow">
        | <a href="/mail/unfollow" style="text-decoration:none; color:#555555;">Unfollow</a>
    </span>
</td></tr>
</table>
</body>
</html>
        </t>

        ', false, true, '2026-05-10 01:11:43.555423', '2026-05-10 01:11:43.555423', NULL);
INSERT INTO public.ir_ui_view VALUES (360, 16, NULL, 1, 1, 'notification_preview', NULL, 'mail.notification_preview', 'qweb', 'mail/data/mail_templates_email_layouts.xml', 'primary', '{"en_US": "<t t-name=\"mail.notification_preview\">\n<div style=\"display: none; max-height: 0px; overflow: hidden; color:#fff; font-size:0px; line-height:0px\">\n    <t t-if=\"tracking_values\">\n        <t t-out=\"tracking_values[0][0]\"/>: <t t-out=\"tracking_values[0][1]\"/> → <t t-out=\"tracking_values[0][2]\"/>\n        <t t-if=\"len(tracking_values) &gt; 1\"> |...</t>\n        <t t-if=\"message.preview\"> | </t>\n    </t>\n    <t t-if=\"subtype_internal\">Internal communication: </t><t t-out=\"message.preview\"/>\n    <!--Trailing whitespace to push back email content so that it doesn''t appear in preview. Specific characters to use may change over time -->\n    <t t-out=\"''͏ ​ '' * 140\"/>\n</div>\n        </t>"}', '<?xml version="1.0"?>
<t t-name="mail.notification_preview">
<div style="display: none; max-height: 0px; overflow: hidden; color:#fff; font-size:0px; line-height:0px">
    <t t-if="tracking_values">
        <t t-out="tracking_values[0][0]"/>: <t t-out="tracking_values[0][1]"/> → <t t-out="tracking_values[0][2]"/>
        <t t-if="len(tracking_values) &gt; 1"> |...</t>
        <t t-if="message.preview"> | </t>
    </t>
    <t t-if="subtype_internal">Internal communication: </t><t t-out="message.preview"/>
    <!--Trailing whitespace to push back email content so that it doesn''t appear in preview. Specific characters to use may change over time -->
    <t t-out="''͏ ​ '' * 140"/>
</div>
        </t>

        ', false, true, '2026-05-10 01:11:43.555423', '2026-05-10 01:11:43.555423', NULL);
INSERT INTO public.ir_ui_view VALUES (361, 16, 358, 1, 1, 'Mail: mail notification layout with responsible signature (user_id of the record)', NULL, 'mail.mail_notification_layout_with_responsible_signature', 'qweb', 'mail/data/mail_templates_email_layouts.xml', 'primary', '{"en_US": "<data name=\"Mail: mail notification layout with responsible signature (user_id of the record)\" inherit_id=\"mail.mail_notification_layout\" primary=\"True\">\n            <xpath expr=\"//t[hasclass(''o_signature'')]\" position=\"replace\">\n                <t class=\"o_signature\">\n                    <div t-if=\"email_add_signature and ''user_id'' in record and record.user_id and not record.env.user._is_superuser() and not is_html_empty(record.user_id.sudo().signature)\" t-out=\"record.user_id.sudo().signature\" style=\"font-size: 13px;\"/>\n                </t>\n            </xpath>\n        <xpath expr=\".\" position=\"attributes\"><attribute name=\"t-name\">mail.mail_notification_layout_with_responsible_signature</attribute></xpath></data>"}', '<?xml version="1.0"?>
<data name="Mail: mail notification layout with responsible signature (user_id of the record)" inherit_id="mail.mail_notification_layout" primary="True">
            <xpath expr="//t[hasclass(''o_signature'')]" position="replace">
                <t class="o_signature">
                    <div t-if="email_add_signature and ''user_id'' in record and record.user_id and not record.env.user._is_superuser() and not is_html_empty(record.user_id.sudo().signature)" t-out="record.user_id.sudo().signature" style="font-size: 13px;"/>
                </t>
            </xpath>
        <xpath expr="." position="attributes"><attribute name="t-name">mail.mail_notification_layout_with_responsible_signature</attribute></xpath></data>
    ', false, true, '2026-05-10 01:11:43.555423', '2026-05-10 01:11:43.555423', NULL);
INSERT INTO public.ir_ui_view VALUES (362, 16, NULL, 1, 1, 'message_notification_limit_email', NULL, 'mail.message_notification_limit_email', 'qweb', 'mail/data/mail_templates_mailgateway.xml', 'primary', '{"en_US": "<t t-name=\"mail.message_notification_limit_email\">\n            <p>Dear Sender,</p>\n            <p>\n                The message below could not be accepted by the address <t t-esc=\"email\"/> because you have\n                contacted it too many times in the last few minutes.\n                <br/>\n                Please try again later.\n            </p>\n            <p>Kind Regards</p>\n        </t>"}', '<?xml version="1.0"?>
<t t-name="mail.message_notification_limit_email">
            <p>Dear Sender,</p>
            <p>
                The message below could not be accepted by the address <t t-esc="email"/> because you have
                contacted it too many times in the last few minutes.
                <br/>
                Please try again later.
            </p>
            <p>Kind Regards</p>
        </t>

        ', false, true, '2026-05-10 01:11:43.555423', '2026-05-10 01:11:43.555423', NULL);
INSERT INTO public.ir_ui_view VALUES (363, 16, NULL, 1, 1, 'mail_bounce_catchall', NULL, 'mail.mail_bounce_catchall', 'qweb', 'mail/data/mail_templates_mailgateway.xml', 'primary', '{"en_US": "<t t-name=\"mail.mail_bounce_catchall\">\n<div>\n    <p>Hello <t t-esc=\"message[''email_from'']\"/>,</p>\n    <p>The email sent to <t t-esc=\"message[''to'']\"/> cannot be processed. This address\n    is used to collect replies and should not be used to directly contact <t t-esc=\"res_company.name\"/>.</p>\n    <p>Please contact us instead using <a t-att-href=\"''mailto:%s'' % res_company.email\"><t t-esc=\"res_company.email\"/></a></p>\n    <p>Regards,</p>\n    <p>The <t t-esc=\"res_company.name\"/> team.</p>\n</div>\n<blockquote><t t-esc=\"message[''body'']\"/></blockquote>\n        </t>"}', '<?xml version="1.0"?>
<t t-name="mail.mail_bounce_catchall">
<div>
    <p>Hello <t t-esc="message[''email_from'']"/>,</p>
    <p>The email sent to <t t-esc="message[''to'']"/> cannot be processed. This address
    is used to collect replies and should not be used to directly contact <t t-esc="res_company.name"/>.</p>
    <p>Please contact us instead using <a t-att-href="''mailto:%s'' % res_company.email"><t t-esc="res_company.email"/></a></p>
    <p>Regards,</p>
    <p>The <t t-esc="res_company.name"/> team.</p>
</div>
<blockquote><t t-esc="message[''body'']"/></blockquote>
        </t>

        ', false, true, '2026-05-10 01:11:43.555423', '2026-05-10 01:11:43.555423', NULL);
INSERT INTO public.ir_ui_view VALUES (364, 16, NULL, 1, 1, 'mail_bounce_alias_security', NULL, 'mail.mail_bounce_alias_security', 'qweb', 'mail/data/mail_templates_mailgateway.xml', 'primary', '{"en_US": "<t t-name=\"mail.mail_bounce_alias_security\">\n<div><t t-out=\"body\"/></div>\n<blockquote><t t-out=\"message[''body'']\"/></blockquote>\n        </t>"}', '<?xml version="1.0"?>
<t t-name="mail.mail_bounce_alias_security">
<div><t t-out="body"/></div>
<blockquote><t t-out="message[''body'']"/></blockquote>
        </t>
    ', false, true, '2026-05-10 01:11:43.555423', '2026-05-10 01:11:43.555423', NULL);
INSERT INTO public.ir_ui_view VALUES (365, 16, NULL, 1, 1, 'account_security_setting_update', NULL, 'mail.account_security_setting_update', 'qweb', 'mail/data/security_notifications_templates.xml', 'primary', '{"en_US": "<t t-name=\"mail.account_security_setting_update\">\n<p>\n    <span>Dear <t t-out=\"user.name\"/>,</span>\n</p>\n<p>\n    <span t-out=\"security_update_text\"/>\n    <span>(<t t-out=\"update_datetime\" t-options=\"{&quot;widget&quot;: &quot;datetime&quot;, &quot;hide_seconds&quot;: True}\"/>).</span>\n</p>\n<p>\n    <span>If this was done by you:</span><br/>\n    <ul>\n        <li>You can safely ignore this message</li>\n    </ul>\n</p>\n<p>\n    <span>If this was not done by you:</span>\n</p>\n<ul class=\"o_mail_account_security_suggestions\">\n    <li t-if=\"suggest_password_reset\">\n        <span>We suggest you start by</span>\n        <a t-att-href=\"password_reset_url\">\n            Resetting Your Password\n        </a>\n    </li>\n    <li>\n        Contact your administrator\n    </li>\n</ul>\n        </t>"}', '<?xml version="1.0"?>
<t t-name="mail.account_security_setting_update">
<p>
    <span>Dear <t t-out="user.name"/>,</span>
</p>
<p>
    <span t-out="security_update_text"/>
    <span>(<t t-out="update_datetime" t-options="{&quot;widget&quot;: &quot;datetime&quot;, &quot;hide_seconds&quot;: True}"/>).</span>
</p>
<p>
    <span>If this was done by you:</span><br/>
    <ul>
        <li>You can safely ignore this message</li>
    </ul>
</p>
<p>
    <span>If this was not done by you:</span>
</p>
<ul class="o_mail_account_security_suggestions">
    <li t-if="suggest_password_reset">
        <span>We suggest you start by</span>
        <a t-att-href="password_reset_url">
            Resetting Your Password
        </a>
    </li>
    <li>
        Contact your administrator
    </li>
</ul>
        </t>
    ', false, true, '2026-05-10 01:11:43.555423', '2026-05-10 01:11:43.555423', NULL);
INSERT INTO public.ir_ui_view VALUES (366, 16, NULL, 1, 1, 'Discuss Public Template', NULL, 'mail.discuss_public_channel_template', 'qweb', 'mail/views/discuss_public_templates.xml', 'primary', '{"en_US": "<t name=\"Discuss Public Template\" t-name=\"mail.discuss_public_channel_template\">&lt;!DOCTYPE html&gt;\n        <html class=\"h-100\">\n            <head>\n                <meta charset=\"utf-8\"/>\n                <meta http-equiv=\"X-UA-Compatible\" content=\"IE=edge\"/>\n                <title t-esc=\"title or ''Odoo''\"/>\n                <link type=\"image/x-icon\" rel=\"shortcut icon\" t-att-href=\"x_icon or ''/web/static/img/favicon.ico''\"/>\n                <script>\n                    window.odoo = {\n                        __session_info__: <t t-out=\"json.dumps(session_info)\"/>,\n                        csrf_token: \"<t t-out=\"request.csrf_token(None)\"/>\",\n                        debug: \"<t t-out=\"debug\"/>\",\n                        discuss_data: <t t-out=\"json.dumps(data)\"/>\n                    };\n                    {\n                        const { user_context,  cache_hashes } = odoo.__session_info__;\n                        fetch(`/web/webclient/translations/${cache_hashes.translations}?lang=${user_context.lang}`);\n                    }\n                </script>\n                <t t-call-assets=\"mail.assets_public\"/>\n                <t t-call-assets=\"mail.assets_discuss_public_test_tours\" t-if=\"''tests'' in debug or test_mode_enabled\"/>\n                <style>\n                    body {\n                        direction: <t t-out=\"env[''res.lang'']._lang_get(lang or env.user.lang).direction or ''ltr''\"/>;\n                    }\n                </style>\n            </head>\n            <body class=\"d-flex flex-column h-100\">\n                <t t-out=\"body or ''''\"/>\n            </body>\n        </html>\n    </t>"}', '<?xml version="1.0"?>
<t name="Discuss Public Template" t-name="mail.discuss_public_channel_template">&lt;!DOCTYPE html&gt;
        <html class="h-100">
            <head>
                <meta charset="utf-8"/>
                <meta http-equiv="X-UA-Compatible" content="IE=edge"/>
                <title t-esc="title or ''Odoo''"/>
                <link type="image/x-icon" rel="shortcut icon" t-att-href="x_icon or ''/web/static/img/favicon.ico''"/>
                <script>
                    window.odoo = {
                        __session_info__: <t t-out="json.dumps(session_info)"/>,
                        csrf_token: "<t t-out="request.csrf_token(None)"/>",
                        debug: "<t t-out="debug"/>",
                        discuss_data: <t t-out="json.dumps(data)"/>
                    };
                    {
                        const { user_context,  cache_hashes } = odoo.__session_info__;
                        fetch(`/web/webclient/translations/${cache_hashes.translations}?lang=${user_context.lang}`);
                    }
                </script>
                <t t-call-assets="mail.assets_public"/>
                <t t-call-assets="mail.assets_discuss_public_test_tours" t-if="''tests'' in debug or test_mode_enabled"/>
                <style>
                    body {
                        direction: <t t-out="env[''res.lang'']._lang_get(lang or env.user.lang).direction or ''ltr''"/>;
                    }
                </style>
            </head>
            <body class="d-flex flex-column h-100">
                <t t-out="body or ''''"/>
            </body>
        </html>
    </t>
', false, true, '2026-05-10 01:11:43.555423', '2026-05-10 01:11:43.555423', NULL);
INSERT INTO public.ir_ui_view VALUES (367, 16, NULL, 1, 1, 'mail.alias.domain.view.form', 'mail.alias.domain', NULL, 'form', 'mail/views/mail_alias_domain_views.xml', 'primary', '{"en_US": "<form string=\"Alias Domain\" duplicate=\"false\">\n                <sheet>\n                    <group>\n                        <group>\n                            <label for=\"name\"/>\n                            <div>\n                                <span class=\"me-1 oe_inline\">@</span>\n                                <field name=\"name\" string=\"Domain\" class=\"oe_inline\" placeholder=\"e.g. &quot;mycompany.com&quot;\"/>\n                            </div>\n                            <field name=\"company_ids\" widget=\"many2many_tags\" string=\"Used In\" readonly=\"True\" groups=\"base.group_multi_company\"/>\n                        </group>\n                        <group>\n                            <field name=\"bounce_alias\" groups=\"base.group_no_one\" placeholder=\"e.g. &quot;bounce&quot;\"/>\n                            <field name=\"catchall_alias\" groups=\"base.group_no_one\" placeholder=\"e.g. &quot;catchall&quot;\"/>\n                            <field name=\"default_from\" groups=\"base.group_no_one\" placeholder=\"e.g. &quot;notifications&quot;\"/>\n                        </group>\n                    </group>\n                </sheet>\n            </form>"}', '<?xml version="1.0"?>
<form string="Alias Domain" duplicate="false">
                <sheet>
                    <group>
                        <group>
                            <label for="name"/>
                            <div>
                                <span class="me-1 oe_inline">@</span>
                                <field name="name" string="Domain" class="oe_inline" placeholder="e.g. &quot;mycompany.com&quot;"/>
                            </div>
                            <field name="company_ids" widget="many2many_tags" string="Used In" readonly="True" groups="base.group_multi_company"/>
                        </group>
                        <group>
                            <field name="bounce_alias" groups="base.group_no_one" placeholder="e.g. &quot;bounce&quot;"/>
                            <field name="catchall_alias" groups="base.group_no_one" placeholder="e.g. &quot;catchall&quot;"/>
                            <field name="default_from" groups="base.group_no_one" placeholder="e.g. &quot;notifications&quot;"/>
                        </group>
                    </group>
                </sheet>
            </form>
        ', false, true, '2026-05-10 01:11:43.555423', '2026-05-10 01:11:43.555423', NULL);
INSERT INTO public.ir_ui_view VALUES (368, 16, NULL, 1, 1, 'mail.alias.domain.view.tree', 'mail.alias.domain', NULL, 'tree', 'mail/views/mail_alias_domain_views.xml', 'primary', '{"en_US": "<tree string=\"Alias Domains\" duplicate=\"false\">\n                <field name=\"sequence\" widget=\"handle\"/>\n                <field name=\"name\"/>\n                <field name=\"bounce_alias\"/>\n                <field name=\"catchall_alias\"/>\n                <field name=\"default_from\"/>\n                <field name=\"company_ids\" optional=\"hide\" widget=\"many2many_tags\" groups=\"base.group_multi_company\"/>\n            </tree>"}', '<?xml version="1.0"?>
<tree string="Alias Domains" duplicate="false">
