                <field name="catchall_alias"/>
                <field name="default_from"/>
                <field name="company_ids" optional="hide" widget="many2many_tags" groups="base.group_multi_company"/>
            </tree>
        ', false, true, '2026-05-10 01:11:43.555423', '2026-05-10 01:11:43.555423', NULL);
INSERT INTO public.ir_ui_view VALUES (369, 16, NULL, 1, 1, 'mail.alias.domain.view.search', 'mail.alias.domain', NULL, 'search', 'mail/views/mail_alias_domain_views.xml', 'primary', '{"en_US": "<search string=\"Alias Domains\">\n                <field name=\"name\"/>\n                <field name=\"bounce_alias\"/>\n                <field name=\"catchall_alias\"/>\n                <field name=\"company_ids\" groups=\"base.group_multi_company\"/>\n                <group expand=\"0\" string=\"Group By\">\n                    <filter string=\"Company\" name=\"group_by_company_ids\" domain=\"[]\" context=\"{''group_by'': ''company_ids''}\" groups=\"base.group_multi_company\"/>\n                </group>\n            </search>"}', '<?xml version="1.0"?>
<search string="Alias Domains">
                <field name="name"/>
                <field name="bounce_alias"/>
                <field name="catchall_alias"/>
                <field name="company_ids" groups="base.group_multi_company"/>
                <group expand="0" string="Group By">
                    <filter string="Company" name="group_by_company_ids" domain="[]" context="{''group_by'': ''company_ids''}" groups="base.group_multi_company"/>
                </group>
            </search>
        ', false, true, '2026-05-10 01:11:43.555423', '2026-05-10 01:11:43.555423', NULL);
INSERT INTO public.ir_ui_view VALUES (370, 16, NULL, 1, 1, 'mail.alias.view.form', 'mail.alias', NULL, 'form', 'mail/views/mail_alias_views.xml', 'primary', '{"en_US": "<form string=\"Alias\">\n                    <field name=\"alias_status\" invisible=\"1\"/>\n                    <div invisible=\"alias_status != ''invalid''\" class=\"alert alert-danger text-center\" role=\"alert\">\n                        The last message received on this alias has caused an error.\n                    </div>\n                    <sheet>\n                        <div class=\"oe_button_box\" name=\"button_box\">\n                            <button name=\"open_document\" string=\"Open Document\" type=\"object\" class=\"oe_link\" icon=\"fa-sitemap\" invisible=\"not alias_model_id or alias_force_thread_id == 0\"/>\n                            <button name=\"open_parent_document\" type=\"object\" class=\"oe_link\" icon=\"fa-sitemap\" invisible=\"not alias_parent_model_id or alias_parent_thread_id == 0\">\n                                    <div class=\"o_field_widget o_stat_info\">\n                                        <span class=\"o_stat_text\">Open Parent Document</span>\n                                    </div>\n                            </button>\n                        </div>\n                        <div class=\"d-flex\">\n                            <h2 class=\"flex-grow-1\" dir=\"ltr\">\n                                <field name=\"alias_name\" class=\"oe_inline\"/>@\n                                <field name=\"alias_domain_id\" class=\"oe_inline\" placeholder=\"e.g. domain.com\" options=\"{''no_create'': True, ''no_open'': True}\"/>\n                            </h2>\n                            <field name=\"alias_status\" widget=\"badge\" decoration-success=\"alias_status == ''valid''\" decoration-warning=\"alias_status == ''not_tested''\" decoration-danger=\"alias_status == ''invalid''\"/>\n                        </div>\n                        <group>\n                            <field name=\"alias_model_id\"/>\n                            <field name=\"alias_force_thread_id\"/>\n                            <field name=\"alias_defaults\"/>\n                            <field name=\"alias_contact\"/>\n                            <field name=\"alias_incoming_local\"/>\n                            <field name=\"alias_parent_model_id\"/>\n                            <field name=\"alias_parent_thread_id\"/>\n                        </group>\n                        <label for=\"alias_bounced_content\" invisible=\"alias_contact == ''everyone''\"/>\n                        <field name=\"alias_bounced_content\" invisible=\"alias_contact == ''everyone''\"/>\n                    </sheet>\n                </form>"}', '<?xml version="1.0"?>
<form string="Alias">
                    <field name="alias_status" invisible="1"/>
                    <div invisible="alias_status != ''invalid''" class="alert alert-danger text-center" role="alert">
                        The last message received on this alias has caused an error.
                    </div>
                    <sheet>
                        <div class="oe_button_box" name="button_box">
                            <button name="open_document" string="Open Document" type="object" class="oe_link" icon="fa-sitemap" invisible="not alias_model_id or alias_force_thread_id == 0"/>
                            <button name="open_parent_document" type="object" class="oe_link" icon="fa-sitemap" invisible="not alias_parent_model_id or alias_parent_thread_id == 0">
                                    <div class="o_field_widget o_stat_info">
                                        <span class="o_stat_text">Open Parent Document</span>
                                    </div>
                            </button>
                        </div>
                        <div class="d-flex">
                            <h2 class="flex-grow-1" dir="ltr">
                                <field name="alias_name" class="oe_inline"/>@
                                <field name="alias_domain_id" class="oe_inline" placeholder="e.g. domain.com" options="{''no_create'': True, ''no_open'': True}"/>
                            </h2>
                            <field name="alias_status" widget="badge" decoration-success="alias_status == ''valid''" decoration-warning="alias_status == ''not_tested''" decoration-danger="alias_status == ''invalid''"/>
                        </div>
                        <group>
                            <field name="alias_model_id"/>
                            <field name="alias_force_thread_id"/>
                            <field name="alias_defaults"/>
                            <field name="alias_contact"/>
                            <field name="alias_incoming_local"/>
                            <field name="alias_parent_model_id"/>
                            <field name="alias_parent_thread_id"/>
                        </group>
                        <label for="alias_bounced_content" invisible="alias_contact == ''everyone''"/>
                        <field name="alias_bounced_content" invisible="alias_contact == ''everyone''"/>
                    </sheet>
                </form>
            ', false, true, '2026-05-10 01:11:43.555423', '2026-05-10 01:11:43.555423', NULL);
INSERT INTO public.ir_ui_view VALUES (371, 16, NULL, 1, 1, 'mail.alias.view.tree', 'mail.alias', NULL, 'tree', 'mail/views/mail_alias_views.xml', 'primary', '{"en_US": "<tree string=\"Alias\">\n                    <field name=\"alias_name\"/>\n                    <field name=\"alias_domain_id\"/>\n                    <field name=\"alias_model_id\"/>\n                    <field name=\"alias_force_thread_id\" optional=\"hide\"/>\n                    <field name=\"alias_parent_model_id\"/>\n                    <field name=\"alias_parent_thread_id\" optional=\"hide\"/>\n                    <field name=\"alias_defaults\" optional=\"hide\"/>\n                    <field name=\"alias_contact\"/>\n                    <field name=\"alias_incoming_local\" optional=\"hide\"/>\n                    <field name=\"alias_status\" widget=\"badge\" decoration-success=\"alias_status == ''valid''\" decoration-warning=\"alias_status == ''not_tested''\" decoration-danger=\"alias_status == ''invalid''\"/>\n                    <button name=\"open_document\" type=\"object\" string=\"Open Document\" icon=\"fa-sitemap\" invisible=\"not alias_model_id or alias_force_thread_id == 0\"/>\n                    <button name=\"open_parent_document\" type=\"object\" string=\"Open Owner\" icon=\"fa-sitemap\" invisible=\"not alias_parent_model_id or alias_parent_thread_id == 0\"/>\n                </tree>"}', '<?xml version="1.0"?>
<tree string="Alias">
                    <field name="alias_name"/>
                    <field name="alias_domain_id"/>
                    <field name="alias_model_id"/>
                    <field name="alias_force_thread_id" optional="hide"/>
                    <field name="alias_parent_model_id"/>
                    <field name="alias_parent_thread_id" optional="hide"/>
                    <field name="alias_defaults" optional="hide"/>
                    <field name="alias_contact"/>
                    <field name="alias_incoming_local" optional="hide"/>
                    <field name="alias_status" widget="badge" decoration-success="alias_status == ''valid''" decoration-warning="alias_status == ''not_tested''" decoration-danger="alias_status == ''invalid''"/>
                    <button name="open_document" type="object" string="Open Document" icon="fa-sitemap" invisible="not alias_model_id or alias_force_thread_id == 0"/>
                    <button name="open_parent_document" type="object" string="Open Owner" icon="fa-sitemap" invisible="not alias_parent_model_id or alias_parent_thread_id == 0"/>
                </tree>
            ', false, true, '2026-05-10 01:11:43.555423', '2026-05-10 01:11:43.555423', NULL);
INSERT INTO public.ir_ui_view VALUES (372, 16, NULL, 1, 1, 'mail.alias.view.search', 'mail.alias', NULL, 'search', 'mail/views/mail_alias_views.xml', 'primary', '{"en_US": "<search string=\"Search Alias\">\n                    <field name=\"alias_name\"/>\n                    <field name=\"alias_domain_id\"/>\n                    <field name=\"alias_model_id\"/>\n                    <field name=\"create_uid\"/>\n                    <field name=\"alias_force_thread_id\"/>\n                    <field name=\"alias_parent_model_id\"/>\n                    <field name=\"alias_parent_thread_id\"/>\n                    <separator/>\n                    <filter string=\"Active\" name=\"active\" domain=\"[(''alias_name'', ''!='', False)]\"/>\n                    <group expand=\"0\" string=\"Group By\">\n                        <filter string=\"Creator\" name=\"groupby_create_uid\" context=\"{''group_by'': ''create_uid''}\"/>\n                        <filter string=\"Alias Domain\" name=\"groupby_alias_domain_id\" context=\"{''group_by'': ''alias_domain_id''}\"/>\n                        <filter string=\"Document Model\" name=\"groupby_alias_model_id\" context=\"{''group_by'': ''alias_model_id''}\"/>\n                        <filter string=\"Container Model\" name=\"groupby_alias_model_id\" context=\"{''group_by'': ''alias_parent_model_id''}\"/>\n                    </group>\n                </search>"}', '<?xml version="1.0"?>
<search string="Search Alias">
                    <field name="alias_name"/>
                    <field name="alias_domain_id"/>
                    <field name="alias_model_id"/>
                    <field name="create_uid"/>
                    <field name="alias_force_thread_id"/>
                    <field name="alias_parent_model_id"/>
                    <field name="alias_parent_thread_id"/>
                    <separator/>
                    <filter string="Active" name="active" domain="[(''alias_name'', ''!='', False)]"/>
                    <group expand="0" string="Group By">
                        <filter string="Creator" name="groupby_create_uid" context="{''group_by'': ''create_uid''}"/>
                        <filter string="Alias Domain" name="groupby_alias_domain_id" context="{''group_by'': ''alias_domain_id''}"/>
                        <filter string="Document Model" name="groupby_alias_model_id" context="{''group_by'': ''alias_model_id''}"/>
                        <filter string="Container Model" name="groupby_alias_model_id" context="{''group_by'': ''alias_parent_model_id''}"/>
                    </group>
                </search>
            ', false, true, '2026-05-10 01:11:43.555423', '2026-05-10 01:11:43.555423', NULL);
INSERT INTO public.ir_ui_view VALUES (373, 16, NULL, 1, 1, 'mail.gateway.allowed.view.tree', 'mail.gateway.allowed', NULL, 'tree', 'mail/views/mail_gateway_allowed_views.xml', 'primary', '{"en_US": "<tree string=\"Mail Gateway Allowed\" editable=\"top\">\n                <field name=\"email\"/>\n            </tree>"}', '<?xml version="1.0"?>
