INSERT INTO public.ir_ui_view VALUES (383, 10, NULL, 1, 1, 'res.users.settings.tree', 'res.users.settings', NULL, 'tree', 'mail/views/res_users_settings_views.xml', 'primary', '{"en_US": "<tree string=\"User Settings\">\n                <field name=\"id\"/>\n                <field name=\"user_id\"/>\n                <field name=\"use_push_to_talk\"/>\n            </tree>"}', '<?xml version="1.0"?>
<tree string="User Settings">
                <field name="id"/>
