INSERT INTO public.ir_ui_view VALUES (379, 16, NULL, 1, 1, 'mail.public_layout', NULL, 'mail.public_layout', 'qweb', 'mail/views/mail_templates_public.xml', 'primary', '{"en_US": "<t t-name=\"mail.public_layout\">\n        <t t-call=\"web.layout\">\n            <t t-set=\"html_data\" t-value=\"{''style'': ''height: 100%;''}\"/>\n            <t t-set=\"head\">\n                <t t-call-assets=\"web.assets_frontend\" t-js=\"false\"/>\n                <title t-translation=\"off\">\n                    <t t-if=\"additional_title\"><t t-out=\"additional_title\"/> | </t><t t-out=\"res_company.name\"/>\n                </title>\n            </t>\n            <t t-out=\"0\"/>\n        </t>\n    </t>"}', '<?xml version="1.0"?>
