INSERT INTO public.ir_ui_view VALUES (380, 16, NULL, 1, 1, 'mail.message_document_unfollowed', NULL, 'mail.message_document_unfollowed', 'qweb', 'mail/views/mail_templates_public.xml', 'primary', '{"en_US": "<t t-name=\"mail.message_document_unfollowed\">\n        <t t-call=\"mail.public_layout\">\n            <t t-set=\"additional_title\">\"<t t-out=\"name\"/>\" no longer followed</t>\n            <div class=\"h-100 d-flex align-items-center justify-content-center\">\n                <div>\n                    <h1 t-out=\"model_name\"/>\n                    <div class=\"alert alert-success text-center p-5\" role=\"status\">\n                        <strong>You are no longer following the document:</strong>\n                        <div class=\"pt-4\">\n                            <a t-if=\"access_url\" class=\"o_access_record_link\" t-att-href=\"access_url\" t-out=\"name\"/>\n                            <i t-else=\"\" t-out=\"name\"/>\n                        </div>\n                    </div>\n                </div>\n            </div>\n        </t>\n    </t>"}', '<?xml version="1.0"?>
<t t-name="mail.message_document_unfollowed">
        <t t-call="mail.public_layout">
            <t t-set="additional_title">"<t t-out="name"/>" no longer followed</t>
            <div class="h-100 d-flex align-items-center justify-content-center">
                <div>
                    <h1 t-out="model_name"/>
                    <div class="alert alert-success text-center p-5" role="status">
                        <strong>You are no longer following the document:</strong>
                        <div class="pt-4">
                            <a t-if="access_url" class="o_access_record_link" t-att-href="access_url" t-out="name"/>
                            <i t-else="" t-out="name"/>
                        </div>
                    </div>
                </div>
            </div>
        </t>
    </t>
', false, true, '2026-05-10 01:11:43.555423', '2026-05-10 01:11:43.555423', NULL);
