INSERT INTO public.ir_ui_view VALUES (384, 16, NULL, 1, 1, 'res.users.settings.form', 'res.users.settings', NULL, 'form', 'mail/views/res_users_settings_views.xml', 'primary', '{"en_US": "<form string=\"User Settings\">\n                <sheet>\n                    <div class=\"oe_title\">\n                        <h1><field name=\"user_id\" readonly=\"id != False\"/></h1>\n                    </div>\n                    <group name=\"discuss_user_settings\">\n                        <group string=\"Discuss sidebar\">\n                            <field name=\"is_discuss_sidebar_category_channel_open\"/>\n                            <field name=\"is_discuss_sidebar_category_chat_open\"/>\n                        </group>\n                        <group string=\"Voice\">\n                            <field name=\"use_push_to_talk\"/>\n                            <field name=\"push_to_talk_key\" placeholder=\"e.g. true.true..f\" invisible=\"not use_push_to_talk\"/>\n                            <field name=\"voice_active_duration\" invisible=\"use_push_to_talk\"/>\n                        </group>\n                    </group>\n                    <notebook colspan=\"4\">\n                        <page string=\"Volume per partner\" name=\"page_volume_per_partner\">\n                            <field name=\"volume_settings_ids\">\n                                <tree editable=\"bottom\">\n                                    <field name=\"partner_id\"/>\n                                    <field name=\"volume\"/>\n                                </tree>\n                            </field>\n                        </page>\n                    </notebook>\n                </sheet>\n            </form>"}', '<?xml version="1.0"?>
<form string="User Settings">
                <sheet>
                    <div class="oe_title">
                        <h1><field name="user_id" readonly="id != False"/></h1>
                    </div>
                    <group name="discuss_user_settings">
                        <group string="Discuss sidebar">
                            <field name="is_discuss_sidebar_category_channel_open"/>
                            <field name="is_discuss_sidebar_category_chat_open"/>
                        </group>
                        <group string="Voice">
                            <field name="use_push_to_talk"/>
                            <field name="push_to_talk_key" placeholder="e.g. true.true..f" invisible="not use_push_to_talk"/>
                            <field name="voice_active_duration" invisible="use_push_to_talk"/>
                        </group>
                    </group>
                    <notebook colspan="4">
                        <page string="Volume per partner" name="page_volume_per_partner">
                            <field name="volume_settings_ids">
                                <tree editable="bottom">
                                    <field name="partner_id"/>
                                    <field name="volume"/>
                                </tree>
                            </field>
                        </page>
                    </notebook>
                </sheet>
            </form>
        ', false, true, '2026-05-10 01:11:43.555423', '2026-05-10 01:11:43.555423', NULL);
INSERT INTO public.ir_ui_view VALUES (385, 16, NULL, 1, 1, 'email.template.form', 'mail.template', NULL, 'form', 'mail/views/mail_template_views.xml', 'primary', '{"en_US": "<form string=\"Templates\">\n                    <header>\n                        <field name=\"ref_ir_act_window\" invisible=\"1\"/>\n                        <field name=\"template_fs\" invisible=\"1\"/>\n                        <field name=\"is_template_editor\" invisible=\"1\"/>\n                        <button string=\"Preview\" name=\"106\" type=\"action\" class=\"btn-primary\" target=\"new\"/>\n                        <button string=\"Reset Template\" name=\"107\" type=\"action\" groups=\"mail.group_mail_template_editor\" invisible=\"not template_fs\"/>\n                        <button string=\"Delete\" name=\"open_delete_confirmation_modal\" type=\"object\" class=\"btn btn-secondary\" invisible=\"(user_id != uid and not is_template_editor) or template_fs\" help=\"Permanently delete this template\"/>\n                        <button string=\"Add Context Action\" class=\"btn btn-secondary\" name=\"create_action\" type=\"object\" groups=\"base.group_no_one\" invisible=\"ref_ir_act_window\" help=\"Display an option on related documents to open a composition wizard with this template\"/>\n                        <button string=\"Remove Context Action\" class=\"btn btn-secondary\" name=\"unlink_action\" type=\"object\" groups=\"base.group_no_one\" invisible=\"not ref_ir_act_window\" help=\"Remove the contextual action to use this template on related documents\"/>\n                    </header>\n                    <sheet>\n                        <div class=\"oe_title\">\n                            <label for=\"name\"/>\n                            <h1><field name=\"name\" class=\"w-100\" required=\"1\" placeholder=\"e.g. &quot;Welcome email&quot;\"/></h1>\n                            <group>\n                                <field name=\"model_id\" placeholder=\"e.g. Contact\" required=\"1\" options=\"{''no_create'': True}\"/>\n                                <field name=\"subject\" options=\"{''dynamic_placeholder'': true}\" placeholder=\"e.g. &quot;Welcome to MyCompany&quot; or &quot;Nice to meet you, {{ object.name }}&quot;\"/>\n                                <field name=\"model\" invisible=\"1\"/>\n                            </group>\n                        </div>\n                        <notebook>\n                            <page string=\"Content\" name=\"content\">\n                                <field name=\"can_write\" invisible=\"1\"/>\n                                <field name=\"body_html\" widget=\"html\" class=\"oe-bordered-editor\" options=\"{''style-inline'': true, ''codeview'': true, ''dynamic_placeholder'': true}\" readonly=\"not can_write and id\"/>\n                                <field name=\"attachment_ids\" widget=\"many2many_binary\"/>\n                            </page>\n                            <page string=\"Email Configuration\" name=\"email_configuration\">\n                                <group>\n                                    <field name=\"email_from\" placeholder=\"Override author''s email\"/>\n                                    <field name=\"use_default_to\"/>\n                                    <field name=\"email_to\" invisible=\"use_default_to\" placeholder=\"Comma-separated recipient addresses\"/>\n                                    <field name=\"partner_to\" invisible=\"use_default_to\" placeholder=\"Comma-separated ids of recipient partners\"/>\n                                    <field name=\"email_cc\" invisible=\"use_default_to\" placeholder=\"Comma-separated carbon copy recipients addresses\"/>\n                                    <field name=\"reply_to\" placeholder=\"Email address to which replies will be redirected when sending emails in mass\"/>\n                                    <field name=\"scheduled_date\" string=\"Scheduled Send Date\"/>\n                                </group>\n                            </page>\n                            <page string=\"Settings\" name=\"email_settings\">\n                                <group col=\"2\">\n                                    <group>\n                                        <field name=\"lang\" placeholder=\"{{ object.partner_id.lang }}\"/>\n                                        <field name=\"mail_server_id\"/>\n                                        <field name=\"auto_delete\"/>\n                                        <field name=\"report_template_ids\" domain=\"[(''model'',''='',model)]\" widget=\"many2many_tags\" options=\"{''no_create'': True}\"/>\n                                    </group>\n                                    <group>\n                                        <field name=\"user_id\" widget=\"many2one_avatar_user\" readonly=\"not is_template_editor\" invisible=\"not is_template_editor\" placeholder=\"If not set, shared with all users.\" help=\"If set, will restrict the template to this specific user.                                                   If not set, shared with all users.\"/>\n                                        <field name=\"description\"/>\n                                    </group>\n                                </group>\n                            </page>\n                        </notebook>\n                       </sheet>\n                </form>"}', '<?xml version="1.0"?>
<form string="Templates">
                    <header>
                        <field name="ref_ir_act_window" invisible="1"/>
                        <field name="template_fs" invisible="1"/>
                        <field name="is_template_editor" invisible="1"/>
                        <button string="Preview" name="106" type="action" class="btn-primary" target="new"/>
                        <button string="Reset Template" name="107" type="action" groups="mail.group_mail_template_editor" invisible="not template_fs"/>
                        <button string="Delete" name="open_delete_confirmation_modal" type="object" class="btn btn-secondary" invisible="(user_id != uid and not is_template_editor) or template_fs" help="Permanently delete this template"/>
                        <button string="Add Context Action" class="btn btn-secondary" name="create_action" type="object" groups="base.group_no_one" invisible="ref_ir_act_window" help="Display an option on related documents to open a composition wizard with this template"/>
                        <button string="Remove Context Action" class="btn btn-secondary" name="unlink_action" type="object" groups="base.group_no_one" invisible="not ref_ir_act_window" help="Remove the contextual action to use this template on related documents"/>
                    </header>
                    <sheet>
                        <div class="oe_title">
                            <label for="name"/>
                            <h1><field name="name" class="w-100" required="1" placeholder="e.g. &quot;Welcome email&quot;"/></h1>
                            <group>
                                <field name="model_id" placeholder="e.g. Contact" required="1" options="{''no_create'': True}"/>
                                <field name="subject" options="{''dynamic_placeholder'': true}" placeholder="e.g. &quot;Welcome to MyCompany&quot; or &quot;Nice to meet you, {{ object.name }}&quot;"/>
                                <field name="model" invisible="1"/>
                            </group>
                        </div>
                        <notebook>
                            <page string="Content" name="content">
                                <field name="can_write" invisible="1"/>
                                <field name="body_html" widget="html" class="oe-bordered-editor" options="{''style-inline'': true, ''codeview'': true, ''dynamic_placeholder'': true}" readonly="not can_write and id"/>
                                <field name="attachment_ids" widget="many2many_binary"/>
                            </page>
                            <page string="Email Configuration" name="email_configuration">
                                <group>
                                    <field name="email_from" placeholder="Override author''s email"/>
                                    <field name="use_default_to"/>
                                    <field name="email_to" invisible="use_default_to" placeholder="Comma-separated recipient addresses"/>
                                    <field name="partner_to" invisible="use_default_to" placeholder="Comma-separated ids of recipient partners"/>
                                    <field name="email_cc" invisible="use_default_to" placeholder="Comma-separated carbon copy recipients addresses"/>
                                    <field name="reply_to" placeholder="Email address to which replies will be redirected when sending emails in mass"/>
                                    <field name="scheduled_date" string="Scheduled Send Date"/>
                                </group>
                            </page>
                            <page string="Settings" name="email_settings">
                                <group col="2">
                                    <group>
                                        <field name="lang" placeholder="{{ object.partner_id.lang }}"/>
                                        <field name="mail_server_id"/>
                                        <field name="auto_delete"/>
                                        <field name="report_template_ids" domain="[(''model'',''='',model)]" widget="many2many_tags" options="{''no_create'': True}"/>
                                    </group>
                                    <group>
                                        <field name="user_id" widget="many2one_avatar_user" readonly="not is_template_editor" invisible="not is_template_editor" placeholder="If not set, shared with all users." help="If set, will restrict the template to this specific user.                                                   If not set, shared with all users."/>
                                        <field name="description"/>
                                    </group>
                                </group>
                            </page>
                        </notebook>
                       </sheet>
                </form>
            ', false, true, '2026-05-10 01:11:43.555423', '2026-05-10 01:11:43.555423', NULL);
INSERT INTO public.ir_ui_view VALUES (386, 16, NULL, 1, 1, 'mail.template.view.form.confirm.delete', 'mail.template', NULL, 'form', 'mail/views/mail_template_views.xml', 'primary', '{"en_US": "<form string=\"Confirmation\">\n                    <p>Are you sure you want to delete this Mail Template?</p>\n                    <footer>\n                        <button name=\"unlink\" type=\"object\" string=\"Delete\" class=\"btn btn-primary\"/>\n                        <button name=\"cancel_unlink\" type=\"object\" string=\"Cancel\" class=\"btn btn-secondary\"/>\n                    </footer>\n                </form>"}', '<?xml version="1.0"?>
