INSERT INTO public.ir_ui_view VALUES (387, 16, NULL, 1, 1, 'email.template.tree', 'mail.template', NULL, 'tree', 'mail/views/mail_template_views.xml', 'primary', '{"en_US": "<tree string=\"Templates\">\n                    <field name=\"mail_server_id\" column_invisible=\"True\"/>\n                    <field name=\"name\"/>\n                    <field name=\"model_id\" groups=\"base.group_no_one\"/>\n                    <field name=\"user_id\" optional=\"show\" widget=\"many2one_avatar_user\"/>\n                    <field name=\"description\"/>\n                    <field name=\"subject\" optional=\"hidden\"/>\n                    <field name=\"email_from\" optional=\"hidden\"/>\n                    <field name=\"email_to\" optional=\"hidden\"/>\n                    <field name=\"partner_to\" optional=\"hidden\"/>\n                </tree>"}', '<?xml version="1.0"?>
<tree string="Templates">
                    <field name="mail_server_id" column_invisible="True"/>
                    <field name="name"/>
                    <field name="model_id" groups="base.group_no_one"/>
                    <field name="user_id" optional="show" widget="many2one_avatar_user"/>
                    <field name="description"/>
                    <field name="subject" optional="hidden"/>
                    <field name="email_from" optional="hidden"/>
                    <field name="email_to" optional="hidden"/>
                    <field name="partner_to" optional="hidden"/>
                </tree>
            ', false, true, '2026-05-10 01:11:43.555423', '2026-05-10 01:11:43.555423', NULL);
INSERT INTO public.ir_ui_view VALUES (388, 16, NULL, 1, 1, 'email.template.search', 'mail.template', NULL, 'search', 'mail/views/mail_template_views.xml', 'primary', '{"en_US": "<search string=\"Templates\">\n                    <field name=\"name\" filter_domain=\"[''|'', ''|'', (''name'',''ilike'',self), (''subject'',''ilike'',self), (''email_to'',''ilike'',self)]\" string=\"Templates\"/>\n                    <field name=\"lang\"/>\n                    <field name=\"model_id\"/>\n                    <filter name=\"my_templates\" string=\"My Templates\" domain=\"[(''user_id'', ''='', uid)]\"/>\n                    <filter name=\"base_templates\" string=\"Base Templates\" domain=\"[(''template_category'', ''='', ''base_template'')]\"/>\n                    <filter name=\"custom_templates\" string=\"Custom Templates\" domain=\"[(''template_category'', ''='', ''custom_template'')]\"/>\n                    <group expand=\"0\" string=\"Group by...\">\n                        <filter string=\"SMTP Server\" name=\"smtpserver\" domain=\"[]\" context=\"{''group_by'':''mail_server_id''}\"/>\n                        <filter string=\"Model\" name=\"model\" domain=\"[]\" context=\"{''group_by'':''model_id''}\"/>\n                    </group>\n                </search>"}', '<?xml version="1.0"?>
<search string="Templates">
                    <field name="name" filter_domain="[''|'', ''|'', (''name'',''ilike'',self), (''subject'',''ilike'',self), (''email_to'',''ilike'',self)]" string="Templates"/>
                    <field name="lang"/>
                    <field name="model_id"/>
                    <filter name="my_templates" string="My Templates" domain="[(''user_id'', ''='', uid)]"/>
                    <filter name="base_templates" string="Base Templates" domain="[(''template_category'', ''='', ''base_template'')]"/>
                    <filter name="custom_templates" string="Custom Templates" domain="[(''template_category'', ''='', ''custom_template'')]"/>
                    <group expand="0" string="Group by...">
                        <filter string="SMTP Server" name="smtpserver" domain="[]" context="{''group_by'':''mail_server_id''}"/>
                        <filter string="Model" name="model" domain="[]" context="{''group_by'':''model_id''}"/>
                    </group>
                </search>
            ', false, true, '2026-05-10 01:11:43.555423', '2026-05-10 01:11:43.555423', NULL);
INSERT INTO public.ir_ui_view VALUES (563, 16, NULL, 1, 1, 'Sidebar', NULL, 'portal.portal_sidebar', 'qweb', 'portal/views/portal_templates.xml', 'primary', '{"en_US": "<t name=\"Sidebar\" t-name=\"portal.portal_sidebar\">\n        <t t-call=\"portal.portal_layout\">\n            <body data-bs-spy=\"scroll\" data-target=\".navspy\" data-offset=\"50\">\n                <div class=\"container o_portal_sidebar\"/>\n                <div class=\"oe_structure mb32\" id=\"oe_structure_portal_sidebar_1\"/>\n            </body>\n        </t>\n    </t>"}', '<?xml version="1.0"?>
