    </t>

    ', false, true, '2026-05-10 01:11:52.573269', '2026-05-10 01:11:52.573269', false);
INSERT INTO public.ir_ui_view VALUES (389, 16, 17, 1, 1, 'ir.actions.server.form', 'ir.actions.server', NULL, 'form', 'mail/views/ir_actions_server_views.xml', 'extension', '{"en_US": "<data><xpath expr=\"//group[@name=''action_content'']\" position=\"inside\">\n                    <field name=\"activity_type_id\" options=\"{''no_create'': True, ''no_open'': True}\" required=\"state == ''next_activity''\" invisible=\"state != ''next_activity''\"/>\n                    <field name=\"activity_summary\" placeholder=\"e.g. Discuss proposal\" invisible=\"state != ''next_activity''\"/>\n                </xpath>\n                <xpath expr=\"//group[@name=''action_content'']\" position=\"after\">\n                    <group invisible=\"state != ''next_activity''\">\n                        <label for=\"activity_date_deadline_range\"/>\n                        <div class=\"o_row\">\n                            <field name=\"activity_date_deadline_range\" class=\"oe_inline\"/>\n                            <field name=\"activity_date_deadline_range_type\" class=\"oe_inline\" required=\"state == ''next_activity'' and activity_date_deadline_range &gt; 0\"/>\n                        </div>\n                        <field name=\"activity_user_type\" required=\"state == ''next_activity''\"/>\n                        <field name=\"activity_user_field_name\" placeholder=\"e.g. user_id\" invisible=\"activity_user_type == ''specific''\" required=\"state == ''next_activity'' and activity_user_type == ''generic''\"/>\n                        <field name=\"activity_user_id\" placeholder=\"Choose a user...\" invisible=\"activity_user_type == ''generic''\" required=\"state == ''next_activity'' and activity_user_type == ''specific''\"/>\n                    </group>\n                    <field name=\"activity_note\" class=\"oe-bordered-editor\" placeholder=\"Add a description to your activity...\" invisible=\"state != ''next_activity''\"/>\n                </xpath>\n                <xpath expr=\"//field[@name=''link_field_id'']\" position=\"after\">\n                    <field name=\"partner_ids\" string=\"Followers to add\" widget=\"many2many_tags\" placeholder=\"Choose a user...\" invisible=\"state != ''followers''\" required=\"state == ''followers''\"/>\n                    <field name=\"partner_ids\" string=\"Followers to remove\" widget=\"many2many_tags\" placeholder=\"Choose a user...\" invisible=\"state != ''remove_followers''\" required=\"state == ''remove_followers''\"/>\n                    <field name=\"template_id\" placeholder=\"Choose a template...\" invisible=\"state != ''mail_post''\" required=\"state == ''mail_post''\" context=\"{''default_model'': model_name,                                      ''default_use_default_to'': True}\"/>\n                    <label for=\"mail_post_method\" invisible=\"state != ''mail_post''\"/>\n                    <div class=\"d-flex flex-column\" invisible=\"state != ''mail_post''\">\n                        <field name=\"mail_post_method\" required=\"state == ''mail_post''\"/>\n                        <div class=\"text-muted\">\n                            <span invisible=\"mail_post_method != ''email''\">\n                                The message will be sent as an email to the recipients of the\n                                template and will not appear in the messaging history.\n                            </span>\n                            <span invisible=\"mail_post_method != ''note''\">\n                                The message will be posted as an internal note visible to internal\n                                users in the messaging history.\n                            </span>\n                            <span invisible=\"mail_post_method != ''comment''\">\n                                The message will be posted as a message on the record,\n                                notifying all followers. It will appear in the messaging history.\n                            </span>\n                        </div>\n                    </div>\n                    <field name=\"mail_post_autofollow\" invisible=\"1\"/>\n                </xpath>\n            </data>"}', '<?xml version="1.0"?>
<data><xpath expr="//group[@name=''action_content'']" position="inside">
                    <field name="activity_type_id" options="{''no_create'': True, ''no_open'': True}" required="state == ''next_activity''" invisible="state != ''next_activity''"/>
                    <field name="activity_summary" placeholder="e.g. Discuss proposal" invisible="state != ''next_activity''"/>
                </xpath>
                <xpath expr="//group[@name=''action_content'']" position="after">
                    <group invisible="state != ''next_activity''">
                        <label for="activity_date_deadline_range"/>
                        <div class="o_row">
                            <field name="activity_date_deadline_range" class="oe_inline"/>
                            <field name="activity_date_deadline_range_type" class="oe_inline" required="state == ''next_activity'' and activity_date_deadline_range &gt; 0"/>
                        </div>
                        <field name="activity_user_type" required="state == ''next_activity''"/>
                        <field name="activity_user_field_name" placeholder="e.g. user_id" invisible="activity_user_type == ''specific''" required="state == ''next_activity'' and activity_user_type == ''generic''"/>
                        <field name="activity_user_id" placeholder="Choose a user..." invisible="activity_user_type == ''generic''" required="state == ''next_activity'' and activity_user_type == ''specific''"/>
                    </group>
                    <field name="activity_note" class="oe-bordered-editor" placeholder="Add a description to your activity..." invisible="state != ''next_activity''"/>
                </xpath>
                <xpath expr="//field[@name=''link_field_id'']" position="after">
                    <field name="partner_ids" string="Followers to add" widget="many2many_tags" placeholder="Choose a user..." invisible="state != ''followers''" required="state == ''followers''"/>
                    <field name="partner_ids" string="Followers to remove" widget="many2many_tags" placeholder="Choose a user..." invisible="state != ''remove_followers''" required="state == ''remove_followers''"/>
                    <field name="template_id" placeholder="Choose a template..." invisible="state != ''mail_post''" required="state == ''mail_post''" context="{''default_model'': model_name,                                      ''default_use_default_to'': True}"/>
                    <label for="mail_post_method" invisible="state != ''mail_post''"/>
                    <div class="d-flex flex-column" invisible="state != ''mail_post''">
                        <field name="mail_post_method" required="state == ''mail_post''"/>
                        <div class="text-muted">
                            <span invisible="mail_post_method != ''email''">
                                The message will be sent as an email to the recipients of the
                                template and will not appear in the messaging history.
                            </span>
                            <span invisible="mail_post_method != ''note''">
                                The message will be posted as an internal note visible to internal
                                users in the messaging history.
                            </span>
                            <span invisible="mail_post_method != ''comment''">
                                The message will be posted as a message on the record,
                                notifying all followers. It will appear in the messaging history.
                            </span>
                        </div>
                    </div>
                    <field name="mail_post_autofollow" invisible="1"/>
                </xpath>
            </data>', false, true, '2026-05-10 01:11:43.555423', '2026-05-10 01:11:43.555423', NULL);
INSERT INTO public.ir_ui_view VALUES (390, 16, 43, 1, 1, 'ir.model form', 'ir.model', NULL, 'form', 'mail/views/ir_model_views.xml', 'extension', '{"en_US": "<data><field name=\"transient\" position=\"after\">\n                <field name=\"is_mail_thread\" readonly=\"state != ''manual''\" groups=\"base.group_no_one\"/>\n                <field name=\"is_mail_activity\" readonly=\"state != ''manual''\" groups=\"base.group_no_one\"/>\n                <field name=\"is_mail_blacklist\" readonly=\"state != ''manual''\" groups=\"base.group_no_one\"/>\n            </field>\n            <xpath expr=\"//field[@name=''field_id'']//field[@name=''copied'']\" position=\"after\">\n                <field name=\"state\" invisible=\"1\"/>\n                <field name=\"tracking\" readonly=\"state != ''manual''\"/>\n            </xpath>\n        </data>"}', '<?xml version="1.0"?>
<data><field name="transient" position="after">
                <field name="is_mail_thread" readonly="state != ''manual''" groups="base.group_no_one"/>
                <field name="is_mail_activity" readonly="state != ''manual''" groups="base.group_no_one"/>
                <field name="is_mail_blacklist" readonly="state != ''manual''" groups="base.group_no_one"/>
            </field>
            <xpath expr="//field[@name=''field_id'']//field[@name=''copied'']" position="after">
                <field name="state" invisible="1"/>
                <field name="tracking" readonly="state != ''manual''"/>
            </xpath>
        </data>', false, true, '2026-05-10 01:11:43.555423', '2026-05-10 01:11:43.555423', NULL);
INSERT INTO public.ir_ui_view VALUES (391, 16, 45, 1, 1, 'ir.model search', 'ir.model', NULL, 'search', 'mail/views/ir_model_views.xml', 'extension', '{"en_US": "<field name=\"model\" position=\"after\">\n                <filter string=\"Mail Thread\" name=\"is_mail_thread\" domain=\"[(''is_mail_thread'', ''='', True)]\"/>\n                <filter string=\"Mail Activity\" name=\"is_mail_activity\" domain=\"[(''is_mail_activity'', ''='', True)]\"/>\n                <filter string=\"Mail Blacklist\" name=\"is_mail_blacklist\" domain=\"[(''is_mail_blacklist'', ''='', True)]\"/>\n            </field>"}', '<?xml version="1.0"?>
