        ', false, true, '2026-05-10 01:11:43.555423', '2026-05-10 01:11:43.555423', NULL);
INSERT INTO public.ir_ui_view VALUES (392, 16, 46, 1, 1, 'ir.model.fields form', 'ir.model.fields', NULL, 'form', 'mail/views/ir_model_views.xml', 'extension', '{"en_US": "<field name=\"copied\" position=\"after\">\n                <field name=\"state\" invisible=\"1\"/>\n                <field name=\"tracking\" invisible=\"ttype in [''binary'', ''html'']\" readonly=\"state != ''manual''\"/>\n            </field>"}', '<?xml version="1.0"?>
