INSERT INTO public.ir_ui_view VALUES (393, 16, 125, 1, 1, 'res.partner.view.form.inherit.mail', 'res.partner', NULL, 'form', 'mail/views/res_partner_views.xml', 'extension', '{"en_US": "<data><xpath expr=\"//field[@name=''email'']\" position=\"replace\">\n                    <field name=\"is_blacklisted\" invisible=\"1\"/>\n                    <label for=\"email\" class=\"oe_inline\"/>\n                    <div class=\"o_row o_row_readonly\">\n                        <button name=\"mail_action_blacklist_remove\" class=\"fa fa-ban text-danger\" title=\"This email is blacklisted for mass mailings. Click to unblacklist.\" type=\"object\" context=\"{''default_email'': email}\" groups=\"base.group_user\" invisible=\"not is_blacklisted\"/>\n                        <field name=\"email\" widget=\"email\" context=\"{''gravatar_image'': True}\" required=\"user_ids\"/>\n                    </div>\n                </xpath>\n                <xpath expr=\"//sheet\" position=\"after\">\n                    <div class=\"oe_chatter\">\n                        <field name=\"message_follower_ids\"/>\n                        <field name=\"activity_ids\"/>\n                        <field name=\"message_ids\"/>\n                    </div>\n                </xpath>\n            </data>"}', '<?xml version="1.0"?>
<data><xpath expr="//field[@name=''email'']" position="replace">
                    <field name="is_blacklisted" invisible="1"/>
                    <label for="email" class="oe_inline"/>
                    <div class="o_row o_row_readonly">
                        <button name="mail_action_blacklist_remove" class="fa fa-ban text-danger" title="This email is blacklisted for mass mailings. Click to unblacklist." type="object" context="{''default_email'': email}" groups="base.group_user" invisible="not is_blacklisted"/>
                        <field name="email" widget="email" context="{''gravatar_image'': True}" required="user_ids"/>
                    </div>
                </xpath>
                <xpath expr="//sheet" position="after">
                    <div class="oe_chatter">
                        <field name="message_follower_ids"/>
                        <field name="activity_ids"/>
                        <field name="message_ids"/>
                    </div>
                </xpath>
            </data>', false, true, '2026-05-10 01:11:43.555423', '2026-05-10 01:11:43.555423', NULL);
INSERT INTO public.ir_ui_view VALUES (394, 16, 128, 1, 1, 'res.partner.view.kanban.inherit.mail', 'res.partner', NULL, 'kanban', 'mail/views/res_partner_views.xml', 'extension', '{"en_US": "<data><field name=\"type\" position=\"after\">\n                    <field name=\"activity_state\"/>\n                </field>\n                <xpath expr=\"//div[hasclass(''oe_kanban_bottom_right'')]\" position=\"inside\">\n                    <field name=\"activity_ids\" widget=\"kanban_activity\"/>\n                </xpath>\n            </data>"}', '<?xml version="1.0"?>
