INSERT INTO public.ir_ui_view VALUES (539, 16, 538, 1, 1, 'Footer Language Selector', NULL, 'portal.footer_language_selector', 'qweb', 'portal/views/portal_templates.xml', 'extension', '{"en_US": "<data inherit_id=\"portal.frontend_layout\" name=\"Footer Language Selector\">\n        <xpath expr=\"//*[hasclass(''o_footer_copyright_name'')]\" position=\"after\">\n            <t id=\"language_selector_call\" t-call=\"portal.language_selector\">\n                <t t-set=\"_div_classes\" t-value=\"(_div_classes or '''') + '' dropup''\"/>\n            </t>\n        </xpath>\n    </data>"}', '<?xml version="1.0"?>
