            ', false, true, '2026-05-10 01:11:43.555423', '2026-05-10 01:11:43.555423', NULL);
INSERT INTO public.ir_ui_view VALUES (398, 16, NULL, 1, 1, 'mail.blacklist.view.tree', 'mail.blacklist', NULL, 'tree', 'mail/views/mail_blacklist_views.xml', 'primary', '{"en_US": "<tree string=\"Email Blacklist\">\n                <field name=\"create_date\" string=\"Blacklist Date\"/>\n                <field name=\"email\"/>\n            </tree>"}', '<?xml version="1.0"?>
