            </tree>
        ', false, true, '2026-05-10 01:11:43.555423', '2026-05-10 01:11:43.555423', NULL);
INSERT INTO public.ir_ui_view VALUES (399, 16, NULL, 1, 1, 'mail.blacklist.view.form', 'mail.blacklist', NULL, 'form', 'mail/views/mail_blacklist_views.xml', 'primary', '{"en_US": "<form string=\"Add Email Blacklist\" duplicate=\"false\">\n                <header>\n                    <button name=\"mail_action_blacklist_remove\" string=\"Unblacklist\" type=\"object\" class=\"oe_highlight\" context=\"{''default_email'': email}\" invisible=\"not active or not email\"/>\n                    <button name=\"action_add\" string=\"Blacklist\" type=\"object\" class=\"oe_highlight\" invisible=\"active or not email\"/>\n                </header>\n                <sheet>\n                    <widget name=\"web_ribbon\" title=\"Archived\" bg_color=\"text-bg-danger\" invisible=\"active\"/>\n                    <group>\n                        <group>\n                            <field name=\"email\"/>\n                            <field name=\"active\" readonly=\"1\"/>\n                            <br/>\n                        </group>\n                    </group>\n                </sheet>\n                <div class=\"oe_chatter\">\n                    <field name=\"message_follower_ids\" groups=\"base.group_user\"/>\n                    <field name=\"message_ids\"/>\n                </div>\n            </form>"}', '<?xml version="1.0"?>
<form string="Add Email Blacklist" duplicate="false">
                <header>
                    <button name="mail_action_blacklist_remove" string="Unblacklist" type="object" class="oe_highlight" context="{''default_email'': email}" invisible="not active or not email"/>
                    <button name="action_add" string="Blacklist" type="object" class="oe_highlight" invisible="active or not email"/>
                </header>
                <sheet>
                    <widget name="web_ribbon" title="Archived" bg_color="text-bg-danger" invisible="active"/>
                    <group>
                        <group>
                            <field name="email"/>
                            <field name="active" readonly="1"/>
                            <br/>
                        </group>
                    </group>
                </sheet>
                <div class="oe_chatter">
                    <field name="message_follower_ids" groups="base.group_user"/>
                    <field name="message_ids"/>
                </div>
            </form>
        ', false, true, '2026-05-10 01:11:43.555423', '2026-05-10 01:11:43.555423', NULL);
INSERT INTO public.ir_ui_view VALUES (400, 16, NULL, 1, 1, 'mail.blacklist.view.search', 'mail.blacklist', NULL, 'search', 'mail/views/mail_blacklist_views.xml', 'primary', '{"en_US": "<search>\n                <field name=\"email\"/>\n                <filter string=\"Archived\" name=\"inactive\" domain=\"[(''active'',''='',False)]\"/>\n            </search>"}', '<?xml version="1.0"?>
