INSERT INTO public.ir_ui_view VALUES (401, 16, 114, 1, 1, 'res.company.view.form.inherit.mail', 'res.company', NULL, 'form', 'mail/views/res_company_views.xml', 'extension', '{"en_US": "<field name=\"sequence\" position=\"after\">\n                <field name=\"alias_domain_id\"/>\n                <field name=\"bounce_formatted\" groups=\"base.group_no_one\"/>\n                <field name=\"catchall_formatted\" groups=\"base.group_no_one\"/>\n                <field name=\"default_from_email\" groups=\"base.group_no_one\"/>\n            </field>"}', '<?xml version="1.0"?>
