                <field name="company_id" column_invisible="True"/>
                <field name="product_uom_category_id" column_invisible="True"/>
                <field name="date" optional="show"/>
                <field name="name"/>
                <field name="account_id"/>
                <field name="currency_id" column_invisible="True"/>
                <field name="unit_amount" sum="Quantity" optional="hide"/>
                <field name="product_uom_id" optional="hide"/>
                <field name="partner_id" optional="hide"/>
                <field name="company_id" groups="base.group_multi_company" optional="show"/>
                <field name="amount" sum="Total" optional="show"/>
            </tree>
        ', false, true, '2026-05-10 01:11:46.819771', '2026-05-10 01:11:46.819771', NULL);
INSERT INTO public.ir_ui_view VALUES (403, 16, NULL, 1, 1, 'account.analytic.line.select', 'account.analytic.line', NULL, 'search', 'analytic/views/analytic_line_views.xml', 'primary', '{"en_US": "<search string=\"Search Analytic Lines\">\n                <field name=\"name\"/>\n                <field name=\"date\"/>\n                <separator/>\n                <filter name=\"month\" string=\"Date\" date=\"date\"/>\n                <group string=\"Group By...\" expand=\"0\" name=\"groupby\">\n                    <separator/>\n                    <filter string=\"Date\" name=\"group_date\" context=\"{''group_by'': ''date''}\"/>\n                </group>\n            </search>"}', '<?xml version="1.0"?>
<search string="Search Analytic Lines">
                <field name="name"/>
                <field name="date"/>
                <separator/>
                <filter name="month" string="Date" date="date"/>
                <group string="Group By..." expand="0" name="groupby">
                    <separator/>
                    <filter string="Date" name="group_date" context="{''group_by'': ''date''}"/>
                </group>
