INSERT INTO public.ir_ui_view VALUES (404, 1, NULL, 1, 1, 'account.analytic.line.form', 'account.analytic.line', NULL, 'form', 'analytic/views/analytic_line_views.xml', 'primary', '{"en_US": "<form string=\"Analytic Item\">\n            <field name=\"company_id\" invisible=\"1\"/>\n            <sheet>\n                <group>\n                    <group name=\"analytic_item\" string=\"Analytic Item\">\n                        <field name=\"name\"/>\n                        <field name=\"account_id\"/>\n                        <field name=\"date\"/>\n                        <field name=\"company_id\" groups=\"base.group_multi_company\"/>\n                    </group>\n                    <group name=\"amount\" string=\"Amount\">\n                        <field name=\"amount\"/>\n                        <field name=\"unit_amount\"/>\n                        <field name=\"product_uom_category_id\" invisible=\"1\"/>\n                        <field name=\"product_uom_id\" class=\"oe_inline\"/>\n                        <field name=\"currency_id\" invisible=\"1\"/>\n                    </group>\n                </group>\n            </sheet>\n            </form>"}', '<?xml version="1.0"?>
