INSERT INTO public.ir_ui_view VALUES (407, 16, NULL, 1, 1, 'account.analytic.line.kanban', 'account.analytic.line', NULL, 'kanban', 'analytic/views/analytic_line_views.xml', 'primary', '{"en_US": "<kanban class=\"o_kanban_mobile\">\n                <field name=\"date\"/>\n                <field name=\"name\"/>\n                <field name=\"account_id\"/>\n                <field name=\"currency_id\"/>\n                <field name=\"amount\"/>\n                <templates>\n                    <t t-name=\"kanban-box\">\n                        <div t-attf-class=\"oe_kanban_card oe_kanban_global_click\">\n                            <div class=\"row\">\n                                <div class=\"col-6\">\n                                    <strong><span><t t-out=\"record.name.value\"/></span></strong>\n                                </div>\n                                <div class=\"col-6 text-end\">\n                                    <strong><t t-out=\"record.date.value\"/></strong>\n                                </div>\n                            </div>\n                            <div class=\"row\">\n                                <div class=\"col-6 text-muted\">\n                                    <span><t t-out=\"record.account_id.value\"/></span>\n                                </div>\n                                <div class=\"col-6\">\n                                    <span class=\"float-end text-end\">\n                                        <field name=\"amount\" widget=\"monetary\"/>\n                                    </span>\n                                </div>\n                            </div>\n                        </div>\n                    </t>\n                </templates>\n            </kanban>"}', '<?xml version="1.0"?>
<kanban class="o_kanban_mobile">
                <field name="date"/>
                <field name="name"/>
                <field name="account_id"/>
                <field name="currency_id"/>
                <field name="amount"/>
                <templates>
                    <t t-name="kanban-box">
                        <div t-attf-class="oe_kanban_card oe_kanban_global_click">
                            <div class="row">
                                <div class="col-6">
                                    <strong><span><t t-out="record.name.value"/></span></strong>
                                </div>
                                <div class="col-6 text-end">
                                    <strong><t t-out="record.date.value"/></strong>
                                </div>
