                            <div class="row">
                                <div class="col-6 text-muted">
                                    <span><t t-out="record.account_id.value"/></span>
                                </div>
                                <div class="col-6">
                                    <span class="float-end text-end">
                                        <field name="amount" widget="monetary"/>
                                    </span>
                                </div>
                            </div>
                        </div>
                    </t>
                </templates>
            </kanban>
        ', false, true, '2026-05-10 01:11:46.819771', '2026-05-10 01:11:46.819771', NULL);
INSERT INTO public.ir_ui_view VALUES (427, 16, 365, 1, 1, 'account_security_setting_update', NULL, 'auth_totp_mail.account_security_setting_update', 'qweb', 'auth_totp_mail/data/security_notifications_template.xml', 'extension', '{"en_US": "<data inherit_id=\"mail.account_security_setting_update\">\n            <xpath expr=\"//ul[hasclass(''o_mail_account_security_suggestions'')]/li[1]\" position=\"after\">\n                <li t-if=\"suggest_2fa\">\n                    <span>Consider</span>\n                    <a href=\"https://www.odoo.com/documentation/17.0/applications/general/auth/2fa.html\">\n                        activating Two-factor Authentication\n                    </a>\n                </li>\n            </xpath>\n        </data>"}', '<?xml version="1.0"?>
<data inherit_id="mail.account_security_setting_update">
            <xpath expr="//ul[hasclass(''o_mail_account_security_suggestions'')]/li[1]" position="after">
                <li t-if="suggest_2fa">
                    <span>Consider</span>
                    <a href="https://www.odoo.com/documentation/17.0/applications/general/auth/2fa.html">
                        activating Two-factor Authentication
                    </a>
                </li>
            </xpath>
        </data>
    ', false, true, '2026-05-10 01:11:47.631208', '2026-05-10 01:11:47.631208', NULL);
INSERT INTO public.ir_ui_view VALUES (408, 16, NULL, 1, 1, 'analytic.analytic.account.form', 'account.analytic.account', NULL, 'form', 'analytic/views/analytic_account_views.xml', 'primary', '{"en_US": "<form string=\"Analytic Account\">\n                    <field name=\"company_id\" invisible=\"1\"/>\n                    <sheet string=\"Analytic Account\">\n                        <div class=\"oe_button_box\" name=\"button_box\">\n                            <button class=\"oe_stat_button\" type=\"action\" name=\"145\" icon=\"fa-usd\">\n                                <div class=\"o_form_field o_stat_info\">\n                                    <span class=\"o_stat_text\">Gross Margin</span>\n                                    <span class=\"o_stat_value\">\n                                        <field name=\"balance\" widget=\"monetary\"/>\n                                    </span>\n                                </div>\n                            </button>\n                        </div>\n                        <widget name=\"web_ribbon\" title=\"Archived\" bg_color=\"text-bg-danger\" invisible=\"active\"/>\n                        <div class=\"oe_title\">\n                            <label for=\"name\"/>\n                            <h1>\n                                <field name=\"name\" class=\"oe_inline\" placeholder=\"e.g. Project XYZ\"/>\n                            </h1>\n                        </div>\n                        <div name=\"project\"/>\n                        <group name=\"main\">\n                            <group>\n                                <field name=\"active\" invisible=\"1\"/>\n                                <field name=\"partner_id\"/>\n                                <field name=\"code\"/>\n                            </group>\n                            <group>\n                                <field name=\"plan_id\" options=\"{''no_quick_create'': True}\"/>\n                                <field name=\"company_id\" options=\"{''no_create'': True}\" groups=\"base.group_multi_company\"/>\n                                <field name=\"currency_id\" options=\"{''no_create'': True}\" groups=\"base.group_multi_currency\"/>\n                            </group>\n                        </group>\n                    </sheet>\n                    <div class=\"oe_chatter\">\n                        <field name=\"message_follower_ids\"/>\n                        <field name=\"message_ids\"/>\n                    </div>\n                </form>"}', '<?xml version="1.0"?>
<form string="Analytic Account">
                    <field name="company_id" invisible="1"/>
                    <sheet string="Analytic Account">
                        <div class="oe_button_box" name="button_box">
                            <button class="oe_stat_button" type="action" name="145" icon="fa-usd">
                                <div class="o_form_field o_stat_info">
                                    <span class="o_stat_text">Gross Margin</span>
                                    <span class="o_stat_value">
                                        <field name="balance" widget="monetary"/>
                                    </span>
                                </div>
                            </button>
                        </div>
                        <widget name="web_ribbon" title="Archived" bg_color="text-bg-danger" invisible="active"/>
                        <div class="oe_title">
                            <label for="name"/>
                            <h1>
                                <field name="name" class="oe_inline" placeholder="e.g. Project XYZ"/>
                            </h1>
                        </div>
                        <div name="project"/>
                        <group name="main">
                            <group>
                                <field name="active" invisible="1"/>
                                <field name="partner_id"/>
                                <field name="code"/>
                            </group>
                            <group>
                                <field name="plan_id" options="{''no_quick_create'': True}"/>
                                <field name="company_id" options="{''no_create'': True}" groups="base.group_multi_company"/>
                                <field name="currency_id" options="{''no_create'': True}" groups="base.group_multi_currency"/>
                            </group>
                        </group>
                    </sheet>
                    <div class="oe_chatter">
                        <field name="message_follower_ids"/>
                        <field name="message_ids"/>
                    </div>
                </form>
            ', false, true, '2026-05-10 01:11:46.819771', '2026-05-10 01:11:46.819771', NULL);
INSERT INTO public.ir_ui_view VALUES (409, 8, NULL, 1, 1, 'account.analytic.account.list', 'account.analytic.account', NULL, 'tree', 'analytic/views/analytic_account_views.xml', 'primary', '{"en_US": "<tree string=\"Analytic Accounts\" multi_edit=\"1\">\n                    <field name=\"company_id\" column_invisible=\"True\"/>\n                    <field name=\"currency_id\" column_invisible=\"True\"/>\n                    <field name=\"name\" string=\"Name\"/>\n                    <field name=\"code\"/>\n                    <field name=\"partner_id\"/>\n                    <field name=\"plan_id\"/>\n                    <field name=\"active\" column_invisible=\"True\"/>\n                    <field name=\"company_id\" groups=\"base.group_multi_company\"/>\n                    <field name=\"debit\" sum=\"Debit\" column_invisible=\"True\"/>\n                    <field name=\"credit\" sum=\"Credit\" column_invisible=\"True\"/>\n                    <field name=\"balance\" sum=\"Balance\"/>\n                </tree>"}', '<?xml version="1.0"?>
<tree string="Analytic Accounts" multi_edit="1">
                    <field name="company_id" column_invisible="True"/>
                    <field name="currency_id" column_invisible="True"/>
                    <field name="name" string="Name"/>
