INSERT INTO public.ir_ui_view VALUES (411, 16, NULL, 1, 1, 'account.analytic.account.kanban', 'account.analytic.account', NULL, 'kanban', 'analytic/views/analytic_account_views.xml', 'primary', '{"en_US": "<kanban class=\"o_kanban_mobile\">\n                   <field name=\"display_name\"/>\n                   <field name=\"balance\"/>\n                   <field name=\"currency_id\"/>\n                   <templates>\n                        <t t-name=\"kanban-box\">\n                            <div t-attf-class=\"oe_kanban_card oe_kanban_global_click\">\n                                <div t-attf-class=\"#{!selection_mode ? ''text-center'' : ''''}\">\n                                   <strong><span><field name=\"display_name\"/></span></strong>\n                                </div>\n                                <hr class=\"mt8 mb8\"/>\n                                <div class=\"row\">\n                                    <div t-attf-class=\"col-12 #{!selection_mode ? ''text-center'' : ''''}\">\n                                        <span>\n                                            Balance: <field name=\"balance\" widget=\"monetary\"/>\n                                        </span>\n                                    </div>\n                                </div>\n                            </div>\n                        </t>\n                    </templates>\n                </kanban>"}', '<?xml version="1.0"?>
<kanban class="o_kanban_mobile">
                   <field name="display_name"/>
                   <field name="balance"/>
                   <field name="currency_id"/>
                   <templates>
                        <t t-name="kanban-box">
                            <div t-attf-class="oe_kanban_card oe_kanban_global_click">
                                <div t-attf-class="#{!selection_mode ? ''text-center'' : ''''}">
                                   <strong><span><field name="display_name"/></span></strong>
                                </div>
                                <hr class="mt8 mb8"/>
                                <div class="row">
                                    <div t-attf-class="col-12 #{!selection_mode ? ''text-center'' : ''''}">
                                        <span>
                                            Balance: <field name="balance" widget="monetary"/>
                                        </span>
                                    </div>
                                </div>
                            </div>
                        </t>
                    </templates>
                </kanban>
            ', false, true, '2026-05-10 01:11:46.819771', '2026-05-10 01:11:46.819771', NULL);
INSERT INTO public.ir_ui_view VALUES (412, 16, NULL, 1, 1, 'account.analytic.account.search', 'account.analytic.account', NULL, 'search', 'analytic/views/analytic_account_views.xml', 'primary', '{"en_US": "<search string=\"Analytic Account\">\n                    <field name=\"name\" filter_domain=\"[''|'', (''name'', ''ilike'', self), (''code'', ''ilike'', self)]\" string=\"Analytic Account\"/>\n                    <field name=\"partner_id\"/>\n                    <separator/>\n                    <filter string=\"Archived\" domain=\"[(''active'', ''='', False)]\" name=\"inactive\"/>\n                    <group expand=\"0\" string=\"Group By...\">\n                        <filter string=\"Associated Partner\" name=\"associatedpartner\" domain=\"[]\" context=\"{''group_by'': ''partner_id''}\"/>\n                    </group>\n                </search>"}', '<?xml version="1.0"?>
<search string="Analytic Account">
                    <field name="name" filter_domain="[''|'', (''name'', ''ilike'', self), (''code'', ''ilike'', self)]" string="Analytic Account"/>
                    <field name="partner_id"/>
                    <separator/>
                    <filter string="Archived" domain="[(''active'', ''='', False)]" name="inactive"/>
                    <group expand="0" string="Group By...">
                        <filter string="Associated Partner" name="associatedpartner" domain="[]" context="{''group_by'': ''partner_id''}"/>
                    </group>
                </search>
            ', false, true, '2026-05-10 01:11:46.819771', '2026-05-10 01:11:46.819771', NULL);
INSERT INTO public.ir_ui_view VALUES (428, 16, 214, 1, 1, 'res.users.view.form.inherit.auth.totp.mail', 'res.users', NULL, 'form', 'auth_totp_mail/views/res_users_views.xml', 'extension', '{"en_US": "<xpath expr=\"//button[@name=''action_totp_enable_wizard'']\" position=\"after\">\n                <button groups=\"base.group_erp_manager\" invisible=\"id == uid\" name=\"action_totp_invite\" string=\"Invite to use 2FA\" type=\"object\" class=\"btn btn-secondary\"/>\n            </xpath>"}', '<?xml version="1.0"?>
