INSERT INTO public.ir_ui_view VALUES (413, 16, NULL, 1, 1, 'account.analytic.plan.form', 'account.analytic.plan', NULL, 'form', 'analytic/views/analytic_plan_views.xml', 'primary', '{"en_US": "<form string=\"Analytic Plans\">\n                <sheet>\n                    <div class=\"oe_button_box\" name=\"button_box\">\n                        <button name=\"action_view_children_plans\" type=\"object\" class=\"oe_stat_button\" icon=\"fa-bars\">\n                            <field string=\"Subplans\" name=\"children_count\" widget=\"statinfo\"/>\n                        </button>\n                        <button name=\"action_view_analytical_accounts\" type=\"object\" class=\"oe_stat_button\" icon=\"fa-bars\">\n                            <div class=\"o_field_widget o_stat_info\">\n                                <span class=\"o_stat_value\"><field name=\"all_account_count\"/></span>\n                                <span class=\"o_stat_text\">Analytic Accounts</span>\n                            </div>\n                        </button>\n                    </div>\n                    <div class=\"oe_title\">\n                        <h1>\n                            <field name=\"name\"/>\n                        </h1>\n                    </div>\n                    <group>\n                        <group>\n                            <field name=\"parent_id\"/>\n                            <field name=\"default_applicability\" invisible=\"parent_id\"/>\n                        <field name=\"color\" widget=\"color_picker\"/>\n                        </group>\n                        <group>\n                        </group>\n                    </group>\n\n                    <notebook>\n                        <page string=\"Applicability\" name=\"applicability\" invisible=\"parent_id\">\n                            <field name=\"applicability_ids\">\n                                <tree editable=\"bottom\">\n                                    <field name=\"business_domain\"/>\n                                    <field name=\"applicability\"/>\n                                    <field name=\"company_id\" groups=\"base.group_multi_company\"/>\n                                </tree>\n                            </field>\n                        </page>\n                    </notebook>\n                </sheet>\n            </form>"}', '<?xml version="1.0"?>
<form string="Analytic Plans">
                <sheet>
                    <div class="oe_button_box" name="button_box">
                        <button name="action_view_children_plans" type="object" class="oe_stat_button" icon="fa-bars">
                            <field string="Subplans" name="children_count" widget="statinfo"/>
                        </button>
                        <button name="action_view_analytical_accounts" type="object" class="oe_stat_button" icon="fa-bars">
                            <div class="o_field_widget o_stat_info">
                                <span class="o_stat_value"><field name="all_account_count"/></span>
                                <span class="o_stat_text">Analytic Accounts</span>
                            </div>
                        </button>
                    </div>
                    <div class="oe_title">
                        <h1>
                            <field name="name"/>
                        </h1>
                    </div>
                    <group>
                        <group>
                            <field name="parent_id"/>
                            <field name="default_applicability" invisible="parent_id"/>
                        <field name="color" widget="color_picker"/>
                        </group>
                        <group>
                        </group>
                    </group>

                    <notebook>
                        <page string="Applicability" name="applicability" invisible="parent_id">
                            <field name="applicability_ids">
                                <tree editable="bottom">
                                    <field name="business_domain"/>
                                    <field name="applicability"/>
                                    <field name="company_id" groups="base.group_multi_company"/>
                                </tree>
                            </field>
                        </page>
                    </notebook>
                </sheet>
            </form>
        ', false, true, '2026-05-10 01:11:46.819771', '2026-05-10 01:11:46.819771', NULL);
INSERT INTO public.ir_ui_view VALUES (414, 16, NULL, 1, 1, 'account.analytic.plan.tree', 'account.analytic.plan', NULL, 'tree', 'analytic/views/analytic_plan_views.xml', 'primary', '{"en_US": "<tree string=\"Analytic Plans\" multi_edit=\"1\">\n                <field name=\"sequence\" widget=\"handle\"/>\n                <field name=\"name\"/>\n                <field name=\"default_applicability\"/>\n                <field name=\"color\" widget=\"color_picker\"/>\n            </tree>"}', '<?xml version="1.0"?>
