INSERT INTO public.ir_ui_view VALUES (415, 16, NULL, 1, 1, 'account.analytic.distribution.model.tree', 'account.analytic.distribution.model', NULL, 'tree', 'analytic/views/analytic_distribution_model_views.xml', 'primary', '{"en_US": "<tree string=\"Analytic Distribution Model\" editable=\"top\" multi_edit=\"1\">\n                <field name=\"partner_id\" optional=\"show\"/>\n                <field name=\"partner_category_id\" optional=\"hide\"/>\n                <field name=\"company_id\" column_invisible=\"True\"/>\n                <field name=\"company_id\" groups=\"base.group_multi_company\" optional=\"show\"/>\n                <field name=\"analytic_distribution\" widget=\"analytic_distribution\" optional=\"show\" options=\"{''force_applicability'': ''optional'', ''disable_save'': true}\"/>\n                <button name=\"action_read_distribution_model\" type=\"object\" string=\"View\" class=\"float-end btn-secondary\"/>\n            </tree>"}', '<?xml version="1.0"?>
