                <button name="action_read_distribution_model" type="object" string="View" class="float-end btn-secondary"/>
            </tree>
        ', false, true, '2026-05-10 01:11:46.819771', '2026-05-10 01:11:46.819771', NULL);
INSERT INTO public.ir_ui_view VALUES (416, 16, NULL, 1, 1, 'account.analytic.distribution.model.form', 'account.analytic.distribution.model', NULL, 'form', 'analytic/views/analytic_distribution_model_views.xml', 'primary', '{"en_US": "<form string=\"Analytic Distribution Model\">\n                <sheet>\n                    <group>\n                        <group string=\"Conditions to meet\" colspan=\"2\">\n                            <group>\n                                <field name=\"partner_id\"/>\n                                <field name=\"partner_category_id\"/>\n                            </group>\n                            <group>\n                                <field name=\"company_id\" groups=\"base.group_multi_company\"/>\n                                <field name=\"company_id\" invisible=\"1\"/>\n                            </group>\n                        </group>\n                        <group string=\"Distribution to apply\" colspan=\"2\">\n                            <field name=\"analytic_distribution\" widget=\"analytic_distribution\" options=\"{''force_applicability'': ''optional'', ''disable_save'': true}\" class=\"w-50\"/>\n                        </group>\n                    </group>\n                </sheet>\n            </form>"}', '<?xml version="1.0"?>
<form string="Analytic Distribution Model">
