                            <group>
                                <field name="company_id" groups="base.group_multi_company"/>
                                <field name="company_id" invisible="1"/>
                            </group>
                        </group>
                        <group string="Distribution to apply" colspan="2">
                            <field name="analytic_distribution" widget="analytic_distribution" options="{''force_applicability'': ''optional'', ''disable_save'': true}" class="w-50"/>
                        </group>
                    </group>
                </sheet>
            </form>
        ', false, true, '2026-05-10 01:11:46.819771', '2026-05-10 01:11:46.819771', NULL);
INSERT INTO public.ir_ui_view VALUES (417, 16, 223, 1, 1, 'res.config.settings.view.form.inherit.auth.signup', 'res.config.settings', NULL, 'form', 'auth_signup/views/res_config_settings_views.xml', 'extension', '{"en_US": "<xpath expr=\"//setting[@id=''access_rights'']\" position=\"before\">\n                    <setting id=\"login_documents\" title=\"To send invitations in B2B mode, open a contact or select several ones in list view and click on ''Portal Access Management'' option in the dropdown menu *Action*.\" help=\"Let your customers log in to see their documents\">\n                        <field name=\"auth_signup_uninvited\" class=\"o_light_label\" widget=\"radio\" options=\"{''horizontal'': true}\" required=\"True\"/>\n                        <div class=\"content-group\" invisible=\"auth_signup_uninvited == ''b2b''\">\n                            <div class=\"mt8\">\n                                <button type=\"object\" name=\"action_open_template_user\" string=\"Default Access Rights\" icon=\"oi-arrow-right\" class=\"btn-link\"/>\n                            </div>\n                        </div>\n                    </setting>\n                    <setting string=\"Password Reset\" help=\"Enable password reset from Login page\" id=\"enable_password_reset\">\n                        <field name=\"auth_signup_reset_password\"/>\n                    </setting>\n                </xpath>"}', '<?xml version="1.0"?>
<xpath expr="//setting[@id=''access_rights'']" position="before">
                    <setting id="login_documents" title="To send invitations in B2B mode, open a contact or select several ones in list view and click on ''Portal Access Management'' option in the dropdown menu *Action*." help="Let your customers log in to see their documents">
                        <field name="auth_signup_uninvited" class="o_light_label" widget="radio" options="{''horizontal'': true}" required="True"/>
                        <div class="content-group" invisible="auth_signup_uninvited == ''b2b''">
                            <div class="mt8">
                                <button type="object" name="action_open_template_user" string="Default Access Rights" icon="oi-arrow-right" class="btn-link"/>
                            </div>
                        </div>
                    </setting>
                    <setting string="Password Reset" help="Enable password reset from Login page" id="enable_password_reset">
                        <field name="auth_signup_reset_password"/>
                    </setting>
                </xpath>
            ', false, true, '2026-05-10 01:11:47.474459', '2026-05-10 01:11:47.474459', NULL);
INSERT INTO public.ir_ui_view VALUES (583, 16, NULL, 1, 1, 'sms.template.view.search', 'sms.template', NULL, 'search', 'sms/views/sms_template_views.xml', 'primary', '{"en_US": "<search string=\"Search SMS Templates\">\n                <field name=\"name\"/>\n                <field name=\"model_id\"/>\n            </search>"}', '<?xml version="1.0"?>
<search string="Search SMS Templates">
                <field name="name"/>
                <field name="model_id"/>
            </search>
        ', false, true, '2026-05-10 01:11:52.961149', '2026-05-10 01:11:52.961149', false);
INSERT INTO public.ir_ui_view VALUES (418, 16, 162, 1, 1, 'res.users.form.inherit', 'res.users', NULL, 'form', 'auth_signup/views/res_users_views.xml', 'extension', '{"en_US": "<data><!-- add state field in header -->\n                <xpath expr=\"//header\" position=\"inside\">\n                    <button string=\"Send Password Reset Instructions\" type=\"object\" name=\"action_reset_password\" invisible=\"state != ''active''\"/>\n                    <button string=\"Send an Invitation Email\" type=\"object\" name=\"action_reset_password\" context=\"{''create_user'': 1}\" invisible=\"state != ''new''\"/>\n                    <field name=\"state\" widget=\"statusbar\"/>\n                </xpath>\n\n                <xpath expr=\"//sheet\" position=\"before\">\n                    <div class=\"alert alert-success text-center o_form_header alert-dismissible\" invisible=\"not signup_valid\" role=\"status\">\n                        <button class=\"btn-close\" data-bs-dismiss=\"alert\" aria-label=\"Close\"/>\n                        <div invisible=\"state != ''active''\">\n                            <strong>A password reset has been requested for this user. An email containing the following link has been sent:</strong>\n                        </div>\n                        <div invisible=\"state != ''new''\">\n                            <strong>An invitation email containing the following subscription link has been sent:</strong>\n                        </div>\n                        <div><field name=\"signup_url\" widget=\"url\"/></div>\n                         <field name=\"signup_valid\" invisible=\"1\"/>\n                     </div>\n                 </xpath>\n            </data>"}', '<?xml version="1.0"?>
<data><!-- add state field in header -->
                <xpath expr="//header" position="inside">
                    <button string="Send Password Reset Instructions" type="object" name="action_reset_password" invisible="state != ''active''"/>
                    <button string="Send an Invitation Email" type="object" name="action_reset_password" context="{''create_user'': 1}" invisible="state != ''new''"/>
                    <field name="state" widget="statusbar"/>
                </xpath>

                <xpath expr="//sheet" position="before">
                    <div class="alert alert-success text-center o_form_header alert-dismissible" invisible="not signup_valid" role="status">
                        <button class="btn-close" data-bs-dismiss="alert" aria-label="Close"/>
                        <div invisible="state != ''active''">
                            <strong>A password reset has been requested for this user. An email containing the following link has been sent:</strong>
                        </div>
                        <div invisible="state != ''new''">
                            <strong>An invitation email containing the following subscription link has been sent:</strong>
                        </div>
                        <div><field name="signup_url" widget="url"/></div>
                         <field name="signup_valid" invisible="1"/>
                     </div>
                 </xpath>
            </data>', false, true, '2026-05-10 01:11:47.474459', '2026-05-10 01:11:47.474459', NULL);
INSERT INTO public.ir_ui_view VALUES (419, 16, 163, 1, 1, 'res.users.tree.inherit', 'res.users', NULL, 'tree', 'auth_signup/views/res_users_views.xml', 'extension', '{"en_US": "<xpath expr=\"//field[@name=''company_id'']\" position=\"after\">\n                    <field name=\"state\" widget=\"badge\" decoration-info=\"state == ''new''\" decoration-success=\"state == ''active''\"/>\n                </xpath>"}', '<?xml version="1.0"?>
<xpath expr="//field[@name=''company_id'']" position="after">
                    <field name="state" widget="badge" decoration-info="state == ''new''" decoration-success="state == ''active''"/>
                </xpath>
            ', false, true, '2026-05-10 01:11:47.474459', '2026-05-10 01:11:47.474459', NULL);
INSERT INTO public.ir_ui_view VALUES (420, 16, 185, 1, 1, 'Sign up - Reset Password', NULL, 'auth_signup.login', 'qweb', 'auth_signup/views/auth_signup_login_templates.xml', 'extension', '{"en_US": "<data inherit_id=\"web.login\" name=\"Sign up - Reset Password\">\n            <xpath expr=\"//button[@type=''submit'']\" position=\"after\">\n                <div class=\"justify-content-between mt-2 d-flex small\">\n                    <a t-if=\"signup_enabled\" t-attf-href=\"/web/signup?{{ keep_query() }}\">Don''t have an account?</a>\n                    <a t-if=\"reset_password_enabled\" t-attf-href=\"/web/reset_password?{{ keep_query() }}\">Reset Password</a>\n                </div>\n            </xpath>\n        </data>"}', '<?xml version="1.0"?>
<data inherit_id="web.login" name="Sign up - Reset Password">
            <xpath expr="//button[@type=''submit'']" position="after">
                <div class="justify-content-between mt-2 d-flex small">
                    <a t-if="signup_enabled" t-attf-href="/web/signup?{{ keep_query() }}">Don''t have an account?</a>
                    <a t-if="reset_password_enabled" t-attf-href="/web/reset_password?{{ keep_query() }}">Reset Password</a>
                </div>
            </xpath>
        </data>

        ', false, true, '2026-05-10 01:11:47.474459', '2026-05-10 01:11:47.474459', NULL);
INSERT INTO public.ir_ui_view VALUES (421, 16, NULL, 1, 1, 'Auth Signup/ResetPassword form fields', NULL, 'auth_signup.fields', 'qweb', 'auth_signup/views/auth_signup_login_templates.xml', 'primary', '{"en_US": "<t name=\"Auth Signup/ResetPassword form fields\" t-name=\"auth_signup.fields\">\n\n            <div class=\"mb-3 field-login\">\n                <label for=\"login\">Your Email</label>\n                <input type=\"text\" name=\"login\" t-att-value=\"login\" id=\"login\" class=\"form-control form-control-sm\" autofocus=\"autofocus\" autocapitalize=\"off\" required=\"required\" t-att-readonly=\"''readonly'' if only_passwords else None\"/>\n            </div>\n\n            <div class=\"mb-3 field-name\">\n                <label for=\"name\">Your Name</label>\n                <input type=\"text\" name=\"name\" t-att-value=\"name\" id=\"name\" class=\"form-control form-control-sm\" placeholder=\"e.g. John Doe\" required=\"required\" t-att-readonly=\"''readonly'' if only_passwords else None\" t-att-autofocus=\"''autofocus'' if login and not only_passwords else None\"/>\n            </div>\n\n            <div class=\"mb-3 field-password pt-2\">\n                <label for=\"password\">Password</label>\n                <input type=\"password\" name=\"password\" id=\"password\" class=\"form-control form-control-sm\" required=\"required\" t-att-autofocus=\"''autofocus'' if only_passwords else None\"/>\n            </div>\n\n            <div class=\"mb-3 field-confirm_password\">\n                <label for=\"confirm_password\">Confirm Password</label>\n                <input type=\"password\" name=\"confirm_password\" id=\"confirm_password\" class=\"form-control form-control-sm\" required=\"required\"/>\n            </div>\n        </t>"}', '<?xml version="1.0"?>
<t name="Auth Signup/ResetPassword form fields" t-name="auth_signup.fields">

            <div class="mb-3 field-login">
                <label for="login">Your Email</label>
                <input type="text" name="login" t-att-value="login" id="login" class="form-control form-control-sm" autofocus="autofocus" autocapitalize="off" required="required" t-att-readonly="''readonly'' if only_passwords else None"/>
            </div>

            <div class="mb-3 field-name">
                <label for="name">Your Name</label>
                <input type="text" name="name" t-att-value="name" id="name" class="form-control form-control-sm" placeholder="e.g. John Doe" required="required" t-att-readonly="''readonly'' if only_passwords else None" t-att-autofocus="''autofocus'' if login and not only_passwords else None"/>
            </div>

            <div class="mb-3 field-password pt-2">
                <label for="password">Password</label>
                <input type="password" name="password" id="password" class="form-control form-control-sm" required="required" t-att-autofocus="''autofocus'' if only_passwords else None"/>
            </div>

            <div class="mb-3 field-confirm_password">
                <label for="confirm_password">Confirm Password</label>
                <input type="password" name="confirm_password" id="confirm_password" class="form-control form-control-sm" required="required"/>
            </div>
        </t>

        ', false, true, '2026-05-10 01:11:47.474459', '2026-05-10 01:11:47.474459', NULL);
INSERT INTO public.ir_ui_view VALUES (422, 16, NULL, 1, 1, 'Sign up login', NULL, 'auth_signup.signup', 'qweb', 'auth_signup/views/auth_signup_login_templates.xml', 'primary', '{"en_US": "<t name=\"Sign up login\" t-name=\"auth_signup.signup\">\n            <t t-call=\"web.login_layout\">\n                <form class=\"oe_signup_form\" role=\"form\" method=\"post\" t-if=\"not message\">\n                  <input type=\"hidden\" name=\"csrf_token\" t-att-value=\"request.csrf_token()\"/>\n\n                    <t t-call=\"auth_signup.fields\">\n                        <t t-set=\"only_passwords\" t-value=\"bool(token and not invalid_token)\"/>\n                    </t>\n\n                    <p class=\"alert alert-danger\" t-if=\"error\" role=\"alert\">\n                        <t t-esc=\"error\"/>\n                    </p>\n                    <input type=\"hidden\" name=\"redirect\" t-att-value=\"redirect\"/>\n                    <input type=\"hidden\" name=\"token\" t-att-value=\"token\"/>\n                    <div class=\"text-center oe_login_buttons d-grid pt-3\">\n                        <button type=\"submit\" class=\"btn btn-primary\"> Sign up</button>\n                        <a t-attf-href=\"/web/login?{{ keep_query() }}\" class=\"btn btn-link btn-sm\" role=\"button\">Already have an account?</a>\n                        <div class=\"o_login_auth\"/>\n                    </div>\n                </form>\n            </t>\n        </t>"}', '<?xml version="1.0"?>
<t name="Sign up login" t-name="auth_signup.signup">
            <t t-call="web.login_layout">
                <form class="oe_signup_form" role="form" method="post" t-if="not message">
                  <input type="hidden" name="csrf_token" t-att-value="request.csrf_token()"/>

                    <t t-call="auth_signup.fields">
                        <t t-set="only_passwords" t-value="bool(token and not invalid_token)"/>
                    </t>

                    <p class="alert alert-danger" t-if="error" role="alert">
                        <t t-esc="error"/>
                    </p>
                    <input type="hidden" name="redirect" t-att-value="redirect"/>
                    <input type="hidden" name="token" t-att-value="token"/>
                    <div class="text-center oe_login_buttons d-grid pt-3">
                        <button type="submit" class="btn btn-primary"> Sign up</button>
                        <a t-attf-href="/web/login?{{ keep_query() }}" class="btn btn-link btn-sm" role="button">Already have an account?</a>
                        <div class="o_login_auth"/>
                    </div>
                </form>
            </t>
        </t>

        ', false, true, '2026-05-10 01:11:47.474459', '2026-05-10 01:11:47.474459', NULL);
INSERT INTO public.ir_ui_view VALUES (434, 100, 298, 1, 1, 'fetchmail.server.view.form.inherit.gmail', 'fetchmail.server', NULL, 'form', 'google_gmail/views/fetchmail_server_views.xml', 'extension', '{"en_US": "<field name=\"user\" position=\"after\">\n                <field name=\"google_gmail_uri\" invisible=\"1\"/>\n                <field name=\"google_gmail_refresh_token\" invisible=\"1\"/>\n                <div invisible=\"server_type != ''gmail''\" class=\"d-flex flex-row align-items-center\" colspan=\"2\">\n                    <span invisible=\"server_type != ''gmail'' or not google_gmail_refresh_token\" class=\"badge text-bg-success\">\n                        Gmail Token Valid\n                    </span>\n                    <button type=\"object\" name=\"open_google_gmail_uri\" class=\"btn-link px-0\" invisible=\"not google_gmail_uri or server_type != ''gmail'' or google_gmail_refresh_token\">\n                        <i class=\"oi oi-arrow-right\"/>\n                        Connect your Gmail account\n                    </button>\n                    <button type=\"object\" name=\"open_google_gmail_uri\" class=\"btn-link px-0 ms-2\" invisible=\"not google_gmail_uri or server_type != ''gmail'' or not google_gmail_refresh_token\">\n                        <i class=\"fa fa-cog\" title=\"Edit Settings\"/>\n                    </button>\n                    <button class=\"alert alert-warning d-block mt-2 text-start\" icon=\"oi-arrow-right\" type=\"action\" role=\"alert\" name=\"74\" invisible=\"server_type != ''gmail'' or google_gmail_uri\">\n                        Setup your Gmail API credentials in the general settings to link a Gmail account.\n                    </button>\n                </div>\n            </field>"}', '<?xml version="1.0"?>
<field name="user" position="after">
                <field name="google_gmail_uri" invisible="1"/>
                <field name="google_gmail_refresh_token" invisible="1"/>
                <div invisible="server_type != ''gmail''" class="d-flex flex-row align-items-center" colspan="2">
                    <span invisible="server_type != ''gmail'' or not google_gmail_refresh_token" class="badge text-bg-success">
                        Gmail Token Valid
                    </span>
                    <button type="object" name="open_google_gmail_uri" class="btn-link px-0" invisible="not google_gmail_uri or server_type != ''gmail'' or google_gmail_refresh_token">
                        <i class="oi oi-arrow-right"/>
                        Connect your Gmail account
                    </button>
                    <button type="object" name="open_google_gmail_uri" class="btn-link px-0 ms-2" invisible="not google_gmail_uri or server_type != ''gmail'' or not google_gmail_refresh_token">
                        <i class="fa fa-cog" title="Edit Settings"/>
                    </button>
                    <button class="alert alert-warning d-block mt-2 text-start" icon="oi-arrow-right" type="action" role="alert" name="74" invisible="server_type != ''gmail'' or google_gmail_uri">
                        Setup your Gmail API credentials in the general settings to link a Gmail account.
                    </button>
                </div>
            </field>
        ', false, true, '2026-05-10 01:11:47.868341', '2026-05-10 01:11:47.868341', NULL);
INSERT INTO public.ir_ui_view VALUES (423, 16, NULL, 1, 1, 'Reset password', NULL, 'auth_signup.reset_password', 'qweb', 'auth_signup/views/auth_signup_login_templates.xml', 'primary', '{"en_US": "<t name=\"Reset password\" t-name=\"auth_signup.reset_password\">\n            <t t-call=\"web.login_layout\">\n                <div t-if=\"message\" class=\"oe_login_form clearfix\">\n                    <p class=\"alert alert-success\" t-if=\"message\" role=\"status\">\n                        <t t-esc=\"message\"/>\n                    </p>\n                    <a href=\"/web/login\" class=\"btn btn-link btn-sm float-start\" role=\"button\">Back to Login</a>\n                </div>\n\n                <form class=\"oe_reset_password_form\" role=\"form\" method=\"post\" t-if=\"not message\">\n                  <input type=\"hidden\" name=\"csrf_token\" t-att-value=\"request.csrf_token()\"/>\n\n                    <t t-if=\"token and not invalid_token\">\n                        <t t-call=\"auth_signup.fields\">\n                            <t t-set=\"only_passwords\" t-value=\"1\"/>\n                        </t>\n                    </t>\n\n                    <t t-if=\"not token\">\n                        <div class=\"mb-3 field-login\">\n                            <label for=\"login\" class=\"col-form-label\">Your Email</label>\n                            <input type=\"text\" name=\"login\" t-att-value=\"login\" id=\"login\" class=\"form-control\" autofocus=\"autofocus\" required=\"required\" autocapitalize=\"off\"/>\n                        </div>\n                    </t>\n\n                    <p class=\"alert alert-danger\" t-if=\"error\" role=\"alert\">\n                        <t t-esc=\"error\"/>\n                    </p>\n                    <input type=\"hidden\" name=\"redirect\" t-att-value=\"redirect\"/>\n                    <input type=\"hidden\" name=\"token\" t-att-value=\"token\"/>\n                    <div class=\"clearfix oe_login_buttons d-grid mt-3\">\n                        <button type=\"submit\" class=\"btn btn-primary\">Reset Password</button>\n                        <div class=\"d-flex justify-content-between align-items-center small mt-2\">\n                            <a t-if=\"not token\" t-attf-href=\"/web/login?{{ keep_query() }}\">Back to Login</a>\n                            <a t-if=\"invalid_token\" href=\"/web/login\">Back to Login</a>\n                        </div>\n                        <div class=\"o_login_auth\"/>\n                    </div>\n\n                </form>\n\n            </t>\n        </t>"}', '<?xml version="1.0"?>
<t name="Reset password" t-name="auth_signup.reset_password">
            <t t-call="web.login_layout">
                <div t-if="message" class="oe_login_form clearfix">
                    <p class="alert alert-success" t-if="message" role="status">
                        <t t-esc="message"/>
                    </p>
                    <a href="/web/login" class="btn btn-link btn-sm float-start" role="button">Back to Login</a>
                </div>

                <form class="oe_reset_password_form" role="form" method="post" t-if="not message">
                  <input type="hidden" name="csrf_token" t-att-value="request.csrf_token()"/>

                    <t t-if="token and not invalid_token">
                        <t t-call="auth_signup.fields">
                            <t t-set="only_passwords" t-value="1"/>
                        </t>
                    </t>

                    <t t-if="not token">
                        <div class="mb-3 field-login">
                            <label for="login" class="col-form-label">Your Email</label>
                            <input type="text" name="login" t-att-value="login" id="login" class="form-control" autofocus="autofocus" required="required" autocapitalize="off"/>
                        </div>
                    </t>

                    <p class="alert alert-danger" t-if="error" role="alert">
                        <t t-esc="error"/>
                    </p>
                    <input type="hidden" name="redirect" t-att-value="redirect"/>
                    <input type="hidden" name="token" t-att-value="token"/>
                    <div class="clearfix oe_login_buttons d-grid mt-3">
                        <button type="submit" class="btn btn-primary">Reset Password</button>
                        <div class="d-flex justify-content-between align-items-center small mt-2">
                            <a t-if="not token" t-attf-href="/web/login?{{ keep_query() }}">Back to Login</a>
                            <a t-if="invalid_token" href="/web/login">Back to Login</a>
                        </div>
                        <div class="o_login_auth"/>
                    </div>

                </form>

            </t>
        </t>
', false, true, '2026-05-10 01:11:47.474459', '2026-05-10 01:11:47.474459', NULL);
INSERT INTO public.ir_ui_view VALUES (424, 16, NULL, 1, 1, 'User Reset Password', NULL, 'auth_signup.reset_password_email', 'qweb', 'auth_signup/views/auth_signup_templates_email.xml', 'primary', '{"en_US": "<t name=\"User Reset Password\" t-name=\"auth_signup.reset_password_email\">\n        <table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" style=\"padding-top: 16px; background-color: #FFFFFF; font-family:Verdana, Arial,sans-serif; color: #454748; width: 100%; border-collapse:separate;\"><tr><td align=\"center\">\n        <table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"590\" style=\"padding: 16px; background-color: #FFFFFF; color: #454748; border-collapse:separate;\">\n        <tbody>\n            <!-- HEADER -->\n            <tr>\n                <td align=\"center\" style=\"min-width: 590px;\">\n                    <table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"590\" style=\"min-width: 590px; background-color: white; padding: 0px 8px 0px 8px; border-collapse:separate;\">\n                        <tr><td valign=\"middle\">\n                            <span style=\"font-size: 10px;\">Your Account</span><br/>\n                            <span style=\"font-size: 20px; font-weight: bold;\">\n                                <t t-out=\"object.name or ''''\">Marc Demo</t>\n                            </span>\n                        </td><td valign=\"middle\" align=\"right\" t-if=\"not object.company_id.uses_default_logo\">\n                            <img t-attf-src=\"/logo.png?company={{ object.company_id.id }}\" style=\"padding: 0px; margin: 0px; height: auto; width: 80px;\" t-att-alt=\"object.company_id.name\"/>\n                        </td></tr>\n                        <tr><td colspan=\"2\" style=\"text-align:center;\">\n                          <hr width=\"100%\" style=\"background-color:rgb(204,204,204);border:medium none;clear:both;display:block;font-size:0px;min-height:1px;line-height:0; margin: 16px 0px 16px 0px;\"/>\n                        </td></tr>\n                    </table>\n                </td>\n            </tr>\n            <!-- CONTENT -->\n            <tr>\n                <td align=\"center\" style=\"min-width: 590px;\">\n                    <table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"590\" style=\"min-width: 590px; background-color: white; padding: 0px 8px 0px 8px; border-collapse:separate;\">\n                        <tr><td valign=\"top\" style=\"font-size: 13px;\">\n                            <div>\n                                Dear <t t-out=\"object.name or ''''\">Marc Demo</t>,<br/><br/>\n                                A password reset was requested for the Odoo account linked to this email.\n                                You may change your password by following this link which will remain valid during 24 hours:<br/>\n                                <div style=\"margin: 16px 0px 16px 0px;\">\n                                    <a t-att-href=\"object.signup_url\" style=\"background-color: #875A7B; padding: 8px 16px 8px 16px; text-decoration: none; color: #fff; border-radius: 5px; font-size:13px;\">\n                                        Change password\n                                    </a>\n                                </div>\n                                If you do not expect this, you can safely ignore this email.<br/><br/>\n                                Thanks,\n                                <t t-if=\"user.signature\">\n                                    <br/>\n                                    <t t-out=\"user.signature\">--<br/>Mitchell Admin</t>\n                                </t>\n                            </div>\n                        </td></tr>\n                        <tr><td style=\"text-align:center;\">\n                          <hr width=\"100%\" style=\"background-color:rgb(204,204,204);border:medium none;clear:both;display:block;font-size:0px;min-height:1px;line-height:0; margin: 16px 0px 16px 0px;\"/>\n                        </td></tr>\n                    </table>\n                </td>\n            </tr>\n            <!-- FOOTER -->\n            <tr>\n                <td align=\"center\" style=\"min-width: 590px;\">\n                    <table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"590\" style=\"min-width: 590px; background-color: white; font-size: 11px; padding: 0px 8px 0px 8px; border-collapse:separate;\">\n                        <tr><td valign=\"middle\" align=\"left\">\n                            <t t-out=\"object.company_id.name or ''''\">YourCompany</t>\n                        </td></tr>\n                        <tr><td valign=\"middle\" align=\"left\" style=\"opacity: 0.7;\">\n                            <t t-out=\"object.company_id.phone or ''''\">+1 650-123-4567</t>\n\n                            <t t-if=\"object.company_id.email\">\n                                | <a t-att-href=\"''mailto:%s'' % object.company_id.email\" style=\"text-decoration:none; color: #454748;\" t-out=\"object.company_id.email\">info@yourcompany.com</a>\n                            </t>\n                            <t t-if=\"object.company_id.website\">\n                                | <a t-att-href=\"''%s'' % object.company_id.website\" style=\"text-decoration:none; color: #454748;\" t-out=\"object.company_id.website\">http://www.example.com</a>\n                            </t>\n                        </td></tr>\n                    </table>\n                </td>\n            </tr>\n        </tbody>\n        </table>\n        </td></tr>\n        <!-- POWERED BY -->\n        <tr><td align=\"center\" style=\"min-width: 590px;\">\n            <table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"590\" style=\"min-width: 590px; background-color: #F1F1F1; color: #454748; padding: 8px; border-collapse:separate;\">\n              <tr><td style=\"text-align: center; font-size: 13px;\">\n                Powered by <a target=\"_blank\" href=\"https://www.odoo.com?utm_source=db&amp;utm_medium=auth\" style=\"color: #875A7B;\">Odoo</a>\n              </td></tr>\n            </table>\n        </td></tr>\n        </table>\n    </t>"}', '<?xml version="1.0"?>
<t name="User Reset Password" t-name="auth_signup.reset_password_email">
        <table border="0" cellpadding="0" cellspacing="0" style="padding-top: 16px; background-color: #FFFFFF; font-family:Verdana, Arial,sans-serif; color: #454748; width: 100%; border-collapse:separate;"><tr><td align="center">
        <table border="0" cellpadding="0" cellspacing="0" width="590" style="padding: 16px; background-color: #FFFFFF; color: #454748; border-collapse:separate;">
        <tbody>
            <!-- HEADER -->
            <tr>
                <td align="center" style="min-width: 590px;">
                    <table border="0" cellpadding="0" cellspacing="0" width="590" style="min-width: 590px; background-color: white; padding: 0px 8px 0px 8px; border-collapse:separate;">
                        <tr><td valign="middle">
                            <span style="font-size: 10px;">Your Account</span><br/>
                            <span style="font-size: 20px; font-weight: bold;">
                                <t t-out="object.name or ''''">Marc Demo</t>
                            </span>
                        </td><td valign="middle" align="right" t-if="not object.company_id.uses_default_logo">
                            <img t-attf-src="/logo.png?company={{ object.company_id.id }}" style="padding: 0px; margin: 0px; height: auto; width: 80px;" t-att-alt="object.company_id.name"/>
                        </td></tr>
                        <tr><td colspan="2" style="text-align:center;">
                          <hr width="100%" style="background-color:rgb(204,204,204);border:medium none;clear:both;display:block;font-size:0px;min-height:1px;line-height:0; margin: 16px 0px 16px 0px;"/>
                        </td></tr>
                    </table>
                </td>
            </tr>
            <!-- CONTENT -->
            <tr>
                <td align="center" style="min-width: 590px;">
                    <table border="0" cellpadding="0" cellspacing="0" width="590" style="min-width: 590px; background-color: white; padding: 0px 8px 0px 8px; border-collapse:separate;">
                        <tr><td valign="top" style="font-size: 13px;">
                            <div>
                                Dear <t t-out="object.name or ''''">Marc Demo</t>,<br/><br/>
                                A password reset was requested for the Odoo account linked to this email.
                                You may change your password by following this link which will remain valid during 24 hours:<br/>
                                <div style="margin: 16px 0px 16px 0px;">
                                    <a t-att-href="object.signup_url" style="background-color: #875A7B; padding: 8px 16px 8px 16px; text-decoration: none; color: #fff; border-radius: 5px; font-size:13px;">
                                        Change password
                                    </a>
                                </div>
                                If you do not expect this, you can safely ignore this email.<br/><br/>
                                Thanks,
                                <t t-if="user.signature">
                                    <br/>
                                    <t t-out="user.signature">--<br/>Mitchell Admin</t>
                                </t>
                            </div>
                        </td></tr>
                        <tr><td style="text-align:center;">
                          <hr width="100%" style="background-color:rgb(204,204,204);border:medium none;clear:both;display:block;font-size:0px;min-height:1px;line-height:0; margin: 16px 0px 16px 0px;"/>
                        </td></tr>
                    </table>
                </td>
            </tr>
            <!-- FOOTER -->
            <tr>
                <td align="center" style="min-width: 590px;">
                    <table border="0" cellpadding="0" cellspacing="0" width="590" style="min-width: 590px; background-color: white; font-size: 11px; padding: 0px 8px 0px 8px; border-collapse:separate;">
                        <tr><td valign="middle" align="left">
                            <t t-out="object.company_id.name or ''''">YourCompany</t>
                        </td></tr>
                        <tr><td valign="middle" align="left" style="opacity: 0.7;">
                            <t t-out="object.company_id.phone or ''''">+1 650-123-4567</t>

                            <t t-if="object.company_id.email">
                                | <a t-att-href="''mailto:%s'' % object.company_id.email" style="text-decoration:none; color: #454748;" t-out="object.company_id.email">info@yourcompany.com</a>
                            </t>
                            <t t-if="object.company_id.website">
                                | <a t-att-href="''%s'' % object.company_id.website" style="text-decoration:none; color: #454748;" t-out="object.company_id.website">http://www.example.com</a>
                            </t>
                        </td></tr>
                    </table>
                </td>
            </tr>
        </tbody>
        </table>
        </td></tr>
        <!-- POWERED BY -->
        <tr><td align="center" style="min-width: 590px;">
            <table border="0" cellpadding="0" cellspacing="0" width="590" style="min-width: 590px; background-color: #F1F1F1; color: #454748; padding: 8px; border-collapse:separate;">
              <tr><td style="text-align: center; font-size: 13px;">
                Powered by <a target="_blank" href="https://www.odoo.com?utm_source=db&amp;utm_medium=auth" style="color: #875A7B;">Odoo</a>
              </td></tr>
            </table>
        </td></tr>
        </table>
    </t>

    ', false, true, '2026-05-10 01:11:47.474459', '2026-05-10 01:11:47.474459', NULL);
INSERT INTO public.ir_ui_view VALUES (425, 16, NULL, 1, 1, 'Alert Login with new Device', NULL, 'auth_signup.alert_login_new_device', 'qweb', 'auth_signup/views/auth_signup_templates_email.xml', 'primary', '{"en_US": "<t name=\"Alert Login with new Device\" t-name=\"auth_signup.alert_login_new_device\">\n        <table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" style=\"padding-top: 16px; background-color: #FFFFFF; font-family:Verdana, Arial,sans-serif; color: #454748; width: 100%; border-collapse:separate;\"><tr><td align=\"center\">\n        <table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"590\" style=\"padding: 16px; background-color: #FFFFFF; color: #454748; border-collapse:separate;\">\n        <tbody>\n            <!-- HEADER -->\n            <tr>\n                <td align=\"center\" style=\"min-width: 590px;\">\n                    <table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"590\" style=\"min-width: 590px; background-color: white; padding: 0px 8px 0px 8px; border-collapse:separate;\">\n                    <tr><td valign=\"top\" style=\"font-size: 13px;\">\n                    <div>\n                        Dear <t t-out=\"object.name or ''''\">Marc Demo</t>,<br/><br/>\n                        A new device was used to sign in to your account. <br/><br/>\n                        Here are some details about the connection:<br/>\n                        <ul>\n                            <li><span style=\"font-weight: bold;\">\n                                Date:</span> <t t-out=\"format_datetime(login_date, dt_format=''long'')\">day, month dd, yyyy - hh:mm:ss (GMT)</t></li>\n                            <t t-if=\"location_address\">\n                                <li><span style=\"font-weight: bold;\">\n                                    Location:</span> <t t-out=\"location_address\">City, Region, Country</t></li>\n                            </t>\n                            <t t-if=\"useros\">\n                                <li><span style=\"font-weight: bold;\">\n                                    Platform:</span> <t t-out=\"useros\">OS</t></li>\n                            </t>\n                            <t t-if=\"browser\">\n                                <li><span style=\"font-weight: bold;\">\n                                    Browser:</span> <t t-out=\"browser\">Browser</t></li>\n                            </t>\n                            <li><span style=\"font-weight: bold;\">\n                                IP Address:</span> <t t-out=\"ip_address\">111.222.333.444</t></li>\n                        </ul>\n                        If you don''t recognize it, you should change your password immediately via this link:<br/>\n                        <div style=\"margin: 16px 0px 16px 0px;\">\n                            <a t-attf-href=\"{{ object.get_base_url() }}/web/reset_password\" style=\"background-color: #875A7B; padding: 8px 16px 8px 16px; text-decoration: none; color: #fff; border-radius: 5px; font-size:13px;\">\n                                Reset Password\n                            </a>\n                        </div>\n                        Otherwise, you can safely ignore this email.\n\n                    </div>\n                    </td></tr>\n                    <tr><td style=\"text-align:center;\">\n                      <hr width=\"100%\" style=\"background-color:rgb(204,204,204);border:medium none;clear:both;display:block;font-size:0px;min-height:1px;line-height:0; margin: 16px 0px 16px 0px;\"/>\n                    </td></tr>\n                    </table>\n                </td>\n            </tr>\n        </tbody>\n        </table>\n        </td></tr>\n        <!-- POWERED BY -->\n        <tr><td align=\"center\" style=\"min-width: 590px;\">\n            <table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"590\" style=\"min-width: 590px; background-color: #F1F1F1; color: #454748; padding: 8px; border-collapse:separate;\">\n              <tr><td style=\"text-align: center; font-size: 13px;\">\n                Powered by <a target=\"_blank\" href=\"https://www.odoo.com?utm_source=db&amp;utm_medium=auth\" style=\"color: #875A7B;\">Odoo</a>\n              </td></tr>\n            </table>\n        </td></tr>\n        </table>\n    </t>"}', '<?xml version="1.0"?>
<t name="Alert Login with new Device" t-name="auth_signup.alert_login_new_device">
        <table border="0" cellpadding="0" cellspacing="0" style="padding-top: 16px; background-color: #FFFFFF; font-family:Verdana, Arial,sans-serif; color: #454748; width: 100%; border-collapse:separate;"><tr><td align="center">
        <table border="0" cellpadding="0" cellspacing="0" width="590" style="padding: 16px; background-color: #FFFFFF; color: #454748; border-collapse:separate;">
        <tbody>
            <!-- HEADER -->
            <tr>
                <td align="center" style="min-width: 590px;">
                    <table border="0" cellpadding="0" cellspacing="0" width="590" style="min-width: 590px; background-color: white; padding: 0px 8px 0px 8px; border-collapse:separate;">
                    <tr><td valign="top" style="font-size: 13px;">
                    <div>
                        Dear <t t-out="object.name or ''''">Marc Demo</t>,<br/><br/>
                        A new device was used to sign in to your account. <br/><br/>
                        Here are some details about the connection:<br/>
                        <ul>
                            <li><span style="font-weight: bold;">
                                Date:</span> <t t-out="format_datetime(login_date, dt_format=''long'')">day, month dd, yyyy - hh:mm:ss (GMT)</t></li>
                            <t t-if="location_address">
                                <li><span style="font-weight: bold;">
                                    Location:</span> <t t-out="location_address">City, Region, Country</t></li>
                            </t>
                            <t t-if="useros">
                                <li><span style="font-weight: bold;">
                                    Platform:</span> <t t-out="useros">OS</t></li>
                            </t>
                            <t t-if="browser">
                                <li><span style="font-weight: bold;">
                                    Browser:</span> <t t-out="browser">Browser</t></li>
                            </t>
                            <li><span style="font-weight: bold;">
                                IP Address:</span> <t t-out="ip_address">111.222.333.444</t></li>
                        </ul>
                        If you don''t recognize it, you should change your password immediately via this link:<br/>
                        <div style="margin: 16px 0px 16px 0px;">
                            <a t-attf-href="{{ object.get_base_url() }}/web/reset_password" style="background-color: #875A7B; padding: 8px 16px 8px 16px; text-decoration: none; color: #fff; border-radius: 5px; font-size:13px;">
                                Reset Password
                            </a>
                        </div>
                        Otherwise, you can safely ignore this email.

                    </div>
                    </td></tr>
                    <tr><td style="text-align:center;">
                      <hr width="100%" style="background-color:rgb(204,204,204);border:medium none;clear:both;display:block;font-size:0px;min-height:1px;line-height:0; margin: 16px 0px 16px 0px;"/>
                    </td></tr>
                    </table>
                </td>
            </tr>
        </tbody>
        </table>
        </td></tr>
        <!-- POWERED BY -->
        <tr><td align="center" style="min-width: 590px;">
            <table border="0" cellpadding="0" cellspacing="0" width="590" style="min-width: 590px; background-color: #F1F1F1; color: #454748; padding: 8px; border-collapse:separate;">
              <tr><td style="text-align: center; font-size: 13px;">
                Powered by <a target="_blank" href="https://www.odoo.com?utm_source=db&amp;utm_medium=auth" style="color: #875A7B;">Odoo</a>
              </td></tr>
            </table>
        </td></tr>
        </table>
    </t>

', false, true, '2026-05-10 01:11:47.474459', '2026-05-10 01:11:47.474459', NULL);
INSERT INTO public.ir_ui_view VALUES (426, 16, 186, 1, 1, 'login_successful', NULL, 'auth_signup.login_successful', 'qweb', 'auth_signup/views/webclient_templates.xml', 'extension', '{"en_US": "<data inherit_id=\"web.login_successful\">\n        <xpath expr=\"//div[hasclass(''oe_login_form'')]/p\" position=\"before\">\n            <p class=\"alert alert-success\" t-if=\"account_created\" role=\"status\">\n                Registration successful.\n            </p>\n            <!-- Remove parameter from URL, do not show \"Account created\" if page is refreshed -->\n            <script defer=\"defer\" type=\"text/javascript\">\n                window.history.replaceState({}, null, ''/web/login_successful'');\n            </script>\n        </xpath>\n    </data>"}', '<?xml version="1.0"?>
<data inherit_id="web.login_successful">
        <xpath expr="//div[hasclass(''oe_login_form'')]/p" position="before">
            <p class="alert alert-success" t-if="account_created" role="status">
                Registration successful.
            </p>
            <!-- Remove parameter from URL, do not show "Account created" if page is refreshed -->
            <script defer="defer" type="text/javascript">
                window.history.replaceState({}, null, ''/web/login_successful'');
            </script>
        </xpath>
    </data>

', false, true, '2026-05-10 01:11:47.474459', '2026-05-10 01:11:47.474459', NULL);
INSERT INTO public.ir_ui_view VALUES (440, 16, 382, 1, 1, 'res.users.view.form.mail_bot', 'res.users', NULL, 'form', 'mail_bot/views/res_users_views.xml', 'extension', '{"en_US": "<data>\n                <field name=\"signature\" position=\"before\">\n                    <field name=\"odoobot_state\" groups=\"base.group_no_one\" readonly=\"0\" invisible=\"share\"/>\n                </field>\n            </data>"}', '<?xml version="1.0"?>
<data>
                <field name="signature" position="before">
                    <field name="odoobot_state" groups="base.group_no_one" readonly="0" invisible="share"/>
                </field>
            </data>
        ', false, true, '2026-05-10 01:11:48.039235', '2026-05-10 01:11:48.039235', NULL);
INSERT INTO public.ir_ui_view VALUES (429, 16, 169, 1, 1, 'res.users.view.form.auth.totp.mail', 'res.users', NULL, 'form', 'auth_totp_mail/views/res_users_views.xml', 'primary', '{"en_US": "<data><form position=\"attributes\">\n                <attribute name=\"create\">0</attribute>\n                <attribute name=\"edit\">0</attribute>\n                <attribute name=\"delete\">0</attribute>\n            </form>\n            <h1 position=\"replace\"/>\n            <xpath expr=\"//field[@name=''image_1920'']\" position=\"replace\"/>\n            <notebook position=\"replace\">\n                <header>\n                </header>\n                <sheet>$0</sheet>\n            </notebook>\n            <notebook position=\"before\">\n                <field name=\"image_1920\" widget=\"image\" class=\"oe_avatar\" options=\"{''zoom'': true, ''preview_image'':''image_128''}\"/>\n                    <div class=\"oe_title\">\n                        <h1>\n                            <field name=\"name\" placeholder=\"Name\" required=\"True\" readonly=\"context.get(''from_my_profile'', False)\"/>\n                        </h1>\n                    </div>\n            </notebook>\n            <page name=\"preferences_page\" position=\"replace\"/>\n            <footer position=\"replace\"/>\n        </data>"}', '<?xml version="1.0"?>
<data><form position="attributes">
                <attribute name="create">0</attribute>
                <attribute name="edit">0</attribute>
                <attribute name="delete">0</attribute>
            </form>
            <h1 position="replace"/>
            <xpath expr="//field[@name=''image_1920'']" position="replace"/>
            <notebook position="replace">
                <header>
                </header>
                <sheet>$0</sheet>
            </notebook>
            <notebook position="before">
                <field name="image_1920" widget="image" class="oe_avatar" options="{''zoom'': true, ''preview_image'':''image_128''}"/>
                    <div class="oe_title">
                        <h1>
                            <field name="name" placeholder="Name" required="True" readonly="context.get(''from_my_profile'', False)"/>
                        </h1>
                    </div>
            </notebook>
            <page name="preferences_page" position="replace"/>
            <footer position="replace"/>
        </data>', false, true, '2026-05-10 01:11:47.631208', '2026-05-10 01:11:47.631208', NULL);
INSERT INTO public.ir_ui_view VALUES (430, 16, NULL, 1, 1, 'base.module.install.request.view.form', 'base.module.install.request', NULL, 'form', 'base_install_request/wizard/base_module_install_request_views.xml', 'primary', '{"en_US": "<form>\n                <div class=\"alert alert-warning oe_button_box\" role=\"alert\">\n                    <p class=\"mt-3\">\n                        This app is included in your subscription. It''s free to activate, but only an administrator can do it. Fill this form to send an activation request.\n                    </p>\n                </div>\n                <field name=\"module_id\" invisible=\"1\"/>\n                <group string=\"Send to:\">\n                    <field colspan=\"2\" name=\"user_ids\" widget=\"many2many_tags\" nolabel=\"1\"/>\n                </group>\n                <group string=\"Why do you need this module?\">\n                    <field colspan=\"2\" name=\"body_html\" widget=\"html\" nolabel=\"1\" placeholder=\"e.g. I''d like to use the SMS Marketing module to organize the promotion of our internal events, and exhibitions. I need access for 3 people of my team.\"/>\n                </group>\n                <footer>\n                    <button string=\"Request Activation\" class=\"btn-primary\" type=\"object\" name=\"action_send_request\" data-hotkey=\"q\"/>\n                    <button string=\"Cancel\" class=\"btn-secondary\" special=\"cancel\" data-hotkey=\"x\"/>\n                </footer>\n            </form>"}', '<?xml version="1.0"?>
<form>
                <div class="alert alert-warning oe_button_box" role="alert">
                    <p class="mt-3">
                        This app is included in your subscription. It''s free to activate, but only an administrator can do it. Fill this form to send an activation request.
                    </p>
                </div>
                <field name="module_id" invisible="1"/>
                <group string="Send to:">
                    <field colspan="2" name="user_ids" widget="many2many_tags" nolabel="1"/>
                </group>
                <group string="Why do you need this module?">
                    <field colspan="2" name="body_html" widget="html" nolabel="1" placeholder="e.g. I''d like to use the SMS Marketing module to organize the promotion of our internal events, and exhibitions. I need access for 3 people of my team."/>
                </group>
                <footer>
                    <button string="Request Activation" class="btn-primary" type="object" name="action_send_request" data-hotkey="q"/>
                    <button string="Cancel" class="btn-secondary" special="cancel" data-hotkey="x"/>
                </footer>
            </form>
        ', false, true, '2026-05-10 01:11:47.730558', '2026-05-10 01:11:47.730558', NULL);
INSERT INTO public.ir_ui_view VALUES (431, 16, NULL, 1, 1, 'base.module.install.review.view.form', 'base.module.install.review', NULL, 'form', 'base_install_request/wizard/base_module_install_request_views.xml', 'primary', '{"en_US": "<form>\n                <div class=\"alert alert-success oe_button_box\" role=\"alert\">\n                    <p class=\"mt-3\">\n                        No extra cost, this application is free.\n                    </p>\n                </div>\n                <field name=\"module_id\" invisible=\"1\"/>\n                <field name=\"module_ids\" widget=\"many2many_tags\" invisible=\"1\"/>\n                <field name=\"modules_description\"/>\n                <footer>\n                    <button string=\"Install App\" class=\"btn-primary\" type=\"object\" name=\"action_install_module\" data-hotkey=\"q\"/>\n                    <button string=\"Cancel\" class=\"btn-secondary\" special=\"cancel\" data-hotkey=\"x\"/>\n                </footer>\n            </form>"}', '<?xml version="1.0"?>
<form>
                <div class="alert alert-success oe_button_box" role="alert">
                    <p class="mt-3">
