                    <button string="Cancel" class="btn-secondary" special="cancel" data-hotkey="x"/>
                </footer>
            </form>
        ', false, true, '2026-05-10 01:11:47.730558', '2026-05-10 01:11:47.730558', NULL);
INSERT INTO public.ir_ui_view VALUES (432, 16, NULL, 1, 1, 'base_install_request.base_module_install_review_description', NULL, 'base_install_request.base_module_install_review_description', 'qweb', 'base_install_request/data/mail_templates_module_install.xml', 'primary', '{"en_US": "<t t-name=\"base_install_request.base_module_install_review_description\">\n        <p t-if=\"any(app.application for app in apps)\">The following apps will be installed:</p>\n        <div class=\"container-fluid\">\n            <ul class=\"list-unstyled row\">\n                <t t-foreach=\"apps\" t-as=\"app\">\n                    <li class=\"mt8 col-lg-6\" t-if=\"app.application\">\n                        <div>\n                            <img width=\"24px\" height=\"24px\" class=\"img-fluid\" t-att-src=\"app.icon\"/>\n                            <t t-esc=\"app.shortdesc\"/>\n                        </div>\n                    </li>\n                </t>\n            </ul>\n        </div>\n    </t>"}', '<?xml version="1.0"?>
<t t-name="base_install_request.base_module_install_review_description">
        <p t-if="any(app.application for app in apps)">The following apps will be installed:</p>
        <div class="container-fluid">
            <ul class="list-unstyled row">
                <t t-foreach="apps" t-as="app">
                    <li class="mt8 col-lg-6" t-if="app.application">
                        <div>
                            <img width="24px" height="24px" class="img-fluid" t-att-src="app.icon"/>
                            <t t-esc="app.shortdesc"/>
                        </div>
                    </li>
                </t>
            </ul>
        </div>
    </t>
', false, true, '2026-05-10 01:11:47.730558', '2026-05-10 01:11:47.730558', NULL);
INSERT INTO public.ir_ui_view VALUES (433, 16, 97, 1, 1, 'ir.module.module.view.kanban.inherit.mail', 'ir.module.module', NULL, 'kanban', 'base_install_request/views/ir_module_module_views.xml', 'extension', '{"en_US": "<button name=\"button_immediate_install\" position=\"after\">\n                <button type=\"object\" class=\"btn btn-primary btn-sm\" name=\"action_open_install_request\" invisible=\"state != ''uninstalled''\" t-if=\"!record.to_buy.raw_value\" groups=\"!base.group_system\">Request Access</button>\n            </button>"}', '<?xml version="1.0"?>
<button name="button_immediate_install" position="after">
                <button type="object" class="btn btn-primary btn-sm" name="action_open_install_request" invisible="state != ''uninstalled''" t-if="!record.to_buy.raw_value" groups="!base.group_system">Request Access</button>
            </button>
