INSERT INTO public.ir_ui_view VALUES (435, 16, 39, 1, 1, 'ir.mail_server.view.form.inherit.gmail', 'ir.mail_server', NULL, 'form', 'google_gmail/views/ir_mail_server_views.xml', 'extension', '{"en_US": "<data><field name=\"smtp_user\" position=\"after\">\n                <field name=\"google_gmail_uri\" invisible=\"1\"/>\n                <field name=\"google_gmail_refresh_token\" invisible=\"1\"/>\n                <div invisible=\"smtp_authentication != ''gmail''\" class=\"d-flex flex-row align-items-center\" colspan=\"8\">\n                    <span invisible=\"smtp_authentication != ''gmail'' or not google_gmail_refresh_token\" class=\"badge text-bg-success\">\n                        Gmail Token Valid\n                    </span>\n                    <button type=\"object\" name=\"open_google_gmail_uri\" class=\"btn-link px-0\" invisible=\"not google_gmail_uri or smtp_authentication != ''gmail'' or google_gmail_refresh_token\">\n                        <i class=\"oi oi-arrow-right\"/>\n                        Connect your Gmail account\n                    </button>\n                    <button type=\"object\" name=\"open_google_gmail_uri\" class=\"btn-link px-0 ms-2\" invisible=\"not google_gmail_uri or smtp_authentication != ''gmail'' or not google_gmail_refresh_token\">\n                        <i class=\"fa fa-cog\" title=\"Edit Settings\"/>\n                    </button>\n                    <button class=\"alert alert-warning d-block mt-2 text-start\" icon=\"oi-arrow-right\" type=\"action\" role=\"alert\" name=\"74\" invisible=\"smtp_authentication != ''gmail'' or google_gmail_uri\">\n                        Setup your Gmail API credentials in the general settings to link a Gmail account.\n                    </button>\n                </div>\n            </field>\n            <field name=\"smtp_authentication_info\" position=\"after\">\n                <a href=\"https://www.odoo.com/documentation/17.0/applications/general/email_communication/email_servers.html?highlight=outgoing email server#use-a-default-from-email-address\" invisible=\"smtp_authentication != ''gmail''\" target=\"_blank\">\n                    Read More\n                </a>\n            </field>\n        </data>"}', '<?xml version="1.0"?>
<data><field name="smtp_user" position="after">
                <field name="google_gmail_uri" invisible="1"/>
                <field name="google_gmail_refresh_token" invisible="1"/>
                <div invisible="smtp_authentication != ''gmail''" class="d-flex flex-row align-items-center" colspan="8">
                    <span invisible="smtp_authentication != ''gmail'' or not google_gmail_refresh_token" class="badge text-bg-success">
                        Gmail Token Valid
                    </span>
                    <button type="object" name="open_google_gmail_uri" class="btn-link px-0" invisible="not google_gmail_uri or smtp_authentication != ''gmail'' or google_gmail_refresh_token">
                        <i class="oi oi-arrow-right"/>
                        Connect your Gmail account
                    </button>
                    <button type="object" name="open_google_gmail_uri" class="btn-link px-0 ms-2" invisible="not google_gmail_uri or smtp_authentication != ''gmail'' or not google_gmail_refresh_token">
                        <i class="fa fa-cog" title="Edit Settings"/>
                    </button>
                    <button class="alert alert-warning d-block mt-2 text-start" icon="oi-arrow-right" type="action" role="alert" name="74" invisible="smtp_authentication != ''gmail'' or google_gmail_uri">
                        Setup your Gmail API credentials in the general settings to link a Gmail account.
                    </button>
                </div>
            </field>
            <field name="smtp_authentication_info" position="after">
                <a href="https://www.odoo.com/documentation/17.0/applications/general/email_communication/email_servers.html?highlight=outgoing email server#use-a-default-from-email-address" invisible="smtp_authentication != ''gmail''" target="_blank">
                    Read More
                </a>
            </field>
        </data>', false, true, '2026-05-10 01:11:47.868341', '2026-05-10 01:11:47.868341', NULL);
INSERT INTO public.ir_ui_view VALUES (436, 16, 353, 1, 1, 'res.config.settings.view.form.inherit.google_gmail', 'res.config.settings', NULL, 'form', 'google_gmail/views/res_config_settings_views.xml', 'extension', '{"en_US": "<div id=\"msg_module_google_gmail\" position=\"replace\">\n                    <div class=\"row mt16\" id=\"gmail_client_identifier\">\n                        <label string=\"ID\" for=\"google_gmail_client_identifier\" class=\"col-lg-3 o_light_label\"/>\n                        <field name=\"google_gmail_client_identifier\" class=\"ms-2\" placeholder=\"ID of your Google app\"/>\n                    </div>\n                    <div class=\"row mt16\" id=\"gmail_client_secret\">\n                        <label string=\"Secret\" for=\"google_gmail_client_secret\" class=\"col-lg-3 o_light_label\"/>\n                        <field name=\"google_gmail_client_secret\" password=\"True\" class=\"ms-2\" placeholder=\"Secret of your Google app\"/>\n                    </div>\n                </div>"}', '<?xml version="1.0"?>
<div id="msg_module_google_gmail" position="replace">
                    <div class="row mt16" id="gmail_client_identifier">
                        <label string="ID" for="google_gmail_client_identifier" class="col-lg-3 o_light_label"/>
                        <field name="google_gmail_client_identifier" class="ms-2" placeholder="ID of your Google app"/>
                    </div>
                    <div class="row mt16" id="gmail_client_secret">
                        <label string="Secret" for="google_gmail_client_secret" class="col-lg-3 o_light_label"/>
                        <field name="google_gmail_client_secret" password="True" class="ms-2" placeholder="Secret of your Google app"/>
                    </div>
                </div>
            ', false, true, '2026-05-10 01:11:47.868341', '2026-05-10 01:11:47.868341', NULL);
INSERT INTO public.ir_ui_view VALUES (437, 16, NULL, 1, 1, 'enrich_company', NULL, 'iap_mail.enrich_company', 'qweb', 'iap_mail/data/mail_templates.xml', 'primary', '{"en_US": "<t t-name=\"iap_mail.enrich_company\">\n        <p t-esc=\"flavor_text\"/>\n        <div class=\"o_partner_autocomplete_enrich_info p-3 mt-3 mb-3 me-5\">\n            <div class=\"row p-0 m-0\">\n            <div class=\"col-sm-10 p-0\">\n                <h4>\n                    <span class=\"me-3 align-middle\" t-esc=\"name\"/>\n                    <a t-if=\"twitter\" class=\"ms-2\" target=\"_blank\" t-attf-href=\"http://www.twitter.com/{{twitter}}\">\n                        <img src=\"/web_editor/font_to_img/61569/rgb(0,132,180)/22\"/>\n                    </a>\n                    <a t-if=\"facebook\" class=\"ms-2\" target=\"_blank\" t-attf-href=\"http://www.facebook.com/{{facebook}}\">\n                        <img src=\"/web_editor/font_to_img/61570/rgb(59,89,152)/22\"/>\n                    </a>\n                    <a t-if=\"linkedin\" class=\"ms-2\" target=\"_blank\" t-attf-href=\"https://www.linkedin.com/{{linkedin}}\">\n                        <img src=\"/web_editor/font_to_img/61580/rgb(0,119,181)/22\"/>\n                    </a>\n                    <a t-if=\"crunchbase\" class=\"ms-2\" target=\"_blank\" t-attf-href=\"https://www.crunchbase.com/{{crunchbase}}\">\n                        <img width=\"19px\" height=\"19px\" src=\"/partner_autocomplete/static/img/crunchbase.ico\"/>\n                    </a>\n                </h4>\n                <p t-esc=\"description\"/>\n            </div>\n            <div t-if=\"logo\" class=\"col-sm-2 p-0 text-center text-md-end order-first order-md-last\">\n                <img t-attf-src=\"{{logo}}\" alt=\"\" style=\"max-width: 80px;\"/>\n            </div>\n            </div>\n            <hr/>\n\n            <div class=\"col-sm-12 row m-0 p-0\">\n                <div t-if=\"company_type\" class=\"d-flex my-1 p-0 col-sm-3\">\n                    <i class=\"fa fa-fw me-2 fa-building text-primary\"/>\n                    <b>Company type</b>\n                </div>\n                <div t-if=\"company_type\" class=\"my-1 col-sm-9\" t-esc=\"company_type\"/>\n                <div t-if=\"founded_year\" class=\"d-flex my-1 p-0 col-sm-3\">\n                    <i class=\"fa fa-fw me-2 fa-calendar text-primary\"/>\n                    <b>Founded</b>\n                </div>\n                <div t-if=\"founded_year\" class=\"my-1 col-sm-9\" t-esc=\"founded_year\"/>\n                <t t-set=\"sectors\" t-value=\"[]\"/>\n                <t t-if=\"sector_primary\" t-set=\"sectors\" t-value=\"sectors + [sector_primary]\"/>\n                <t t-if=\"industry\" t-set=\"sectors\" t-value=\"sectors + [industry]\"/>\n                <t t-if=\"industry_group\" t-set=\"sectors\" t-value=\"sectors + [industry_group]\"/>\n                <t t-if=\"sub_industry\" t-set=\"sectors\" t-value=\"sectors + [sub_industry]\"/>\n                <div t-if=\"sectors\" class=\"d-flex my-1 p-0 col-sm-3\">\n                    <i class=\"fa fa-fw me-2 fa-industry text-primary\"/>\n                    <b>Sectors</b>\n                </div>\n                <div t-if=\"sectors\" class=\"my-1 col-sm-9\">\n                    <t t-foreach=\"sectors\" t-as=\"inner_sector\">\n                        <label t-esc=\"inner_sector\" class=\"o_tag o_tag_color_7\" style=\"font-weight:normal; padding: 2px 10px; margin: 1px 0px; border-radius: 13px; display: inline-block;\"/>\n                    </t>\n                </div>\n                <div t-if=\"employees\" class=\"d-flex my-1 p-0 col-sm-3\">\n                    <i class=\"fa fa-fw me-2 fa-users text-primary\"/>\n                    <b>Employees</b>\n                </div>\n                <div t-if=\"employees\" class=\"my-1 col-sm-9\" t-esc=\"''%.0f'' % employees\"/>\n                <div t-if=\"estimated_annual_revenue\" class=\"d-flex my-1 p-0 col-sm-3\">\n                    <i class=\"fa fa-fw me-2 fa-money text-primary\"/>\n                    <b>Estimated revenue</b>\n                </div>\n                <div t-if=\"estimated_annual_revenue\" class=\"my-1 col-sm-9\">\n                    <span t-esc=\"estimated_annual_revenue\"/><span> per year</span>\n                </div>\n                <div t-if=\"phone_numbers\" class=\"d-flex my-1 p-0 col-sm-3\">\n                    <i class=\"fa fa-fw me-2 fa-phone text-primary\"/>\n                    <b>Phone</b>\n                </div>\n                <div t-if=\"phone_numbers\" class=\"col-sm-9\">\n                    <t t-foreach=\"phone_numbers\" t-as=\"phone_number\">\n                        <a t-attf-href=\"tel:{{phone_number}}\" t-esc=\"phone_number\" class=\"o_tag o_tag_color_7\" style=\"font-weight:normal; padding: 2px 10px; margin: 1px 0px; border-radius: 13px; display: inline-block;\"/>\n                    </t>\n                </div>\n                <div t-if=\"email\" class=\"d-flex my-1 p-0 col-sm-3\">\n                    <i class=\"fa fa-fw me-2 fa-envelope text-primary\"/>\n                    <b>Email</b>\n                </div>\n                <div t-if=\"email\" class=\"col-sm-9\">\n                    <t t-foreach=\"email\" t-as=\"email_item\">\n                        <a target=\"_top\" t-attf-href=\"mailto:{{email_item}}\" t-esc=\"email_item\" class=\"o_tag o_tag_color_7\" style=\"font-weight:normal; padding: 2px 10px; margin: 1px 0px; border-radius: 13px; display: inline-block;\"/>\n                    </t>\n                </div>\n                <div t-if=\"timezone\" class=\"d-flex my-1 p-0 col-sm-3\">\n                    <i class=\"fa fa-fw me-2 fa-globe text-primary\"/>\n                    <b>Timezone</b>\n                </div>\n                <div t-if=\"timezone\" class=\"my-1 col-sm-9\" t-esc=\"timezone.replace(''_'', '' '')\"/>\n                <div t-if=\"tech\" class=\"d-flex my-1 p-0 col-sm-3\">\n                    <i class=\"fa fa-fw me-2 fa-cube text-primary\"/>\n                    <b>Technologies Used</b>\n                </div>\n                <div t-if=\"tech\" class=\"my-1 col-sm-9\">\n                    <t t-foreach=\"tech\" t-as=\"tech_item\">\n                        <label t-esc=\"tech_item.replace(''_'', '' '').title()\" class=\"o_tag o_tag_color_7\" style=\"font-weight:normal; padding: 2px 10px; margin: 1px 0px; border-radius: 13px; display: inline-block;\"/>\n                    </t>\n                </div>\n                <div t-if=\"twitter_bio\" class=\"d-flex my-1 p-0 col-sm-3\">\n                    <i class=\"fa fa-fw me-2 fa-twitter text-primary\"/>\n                    <b>Twitter</b>\n                </div>\n                <div t-if=\"twitter_bio\" class=\"my-1 col-sm-9\">\n                    <div class=\"d-flex gap-2\">\n                        <a t-if=\"twitter\" target=\"_blank\" t-attf-href=\"http://www.twitter.com/{{twitter}}\" class=\"text-nowrap\">\n                            http://www.twitter.com/<t t-esc=\"twitter\"/>\n                        </a>\n                        <span t-if=\"twitter\"> • </span>\n                        <div t-if=\"twitter_followers\" class=\"text-nowrap\"><t t-esc=\"twitter_followers\"/> followers</div>\n                    </div>\n                    <div t-esc=\"twitter_bio\" class=\"mt-1\"/>\n                </div>\n            </div>\n        </div>\n    </t>"}', '<?xml version="1.0"?>
<t t-name="iap_mail.enrich_company">
        <p t-esc="flavor_text"/>
        <div class="o_partner_autocomplete_enrich_info p-3 mt-3 mb-3 me-5">
            <div class="row p-0 m-0">
            <div class="col-sm-10 p-0">
                <h4>
                    <span class="me-3 align-middle" t-esc="name"/>
                    <a t-if="twitter" class="ms-2" target="_blank" t-attf-href="http://www.twitter.com/{{twitter}}">
                        <img src="/web_editor/font_to_img/61569/rgb(0,132,180)/22"/>
                    </a>
                    <a t-if="facebook" class="ms-2" target="_blank" t-attf-href="http://www.facebook.com/{{facebook}}">
                        <img src="/web_editor/font_to_img/61570/rgb(59,89,152)/22"/>
                    </a>
                    <a t-if="linkedin" class="ms-2" target="_blank" t-attf-href="https://www.linkedin.com/{{linkedin}}">
                        <img src="/web_editor/font_to_img/61580/rgb(0,119,181)/22"/>
                    </a>
                    <a t-if="crunchbase" class="ms-2" target="_blank" t-attf-href="https://www.crunchbase.com/{{crunchbase}}">
                        <img width="19px" height="19px" src="/partner_autocomplete/static/img/crunchbase.ico"/>
                    </a>
                </h4>
                <p t-esc="description"/>
            </div>
            <div t-if="logo" class="col-sm-2 p-0 text-center text-md-end order-first order-md-last">
                <img t-attf-src="{{logo}}" alt="" style="max-width: 80px;"/>
            </div>
            </div>
            <hr/>

            <div class="col-sm-12 row m-0 p-0">
                <div t-if="company_type" class="d-flex my-1 p-0 col-sm-3">
                    <i class="fa fa-fw me-2 fa-building text-primary"/>
                    <b>Company type</b>
                </div>
                <div t-if="company_type" class="my-1 col-sm-9" t-esc="company_type"/>
                <div t-if="founded_year" class="d-flex my-1 p-0 col-sm-3">
                    <i class="fa fa-fw me-2 fa-calendar text-primary"/>
                    <b>Founded</b>
                </div>
                <div t-if="founded_year" class="my-1 col-sm-9" t-esc="founded_year"/>
                <t t-set="sectors" t-value="[]"/>
                <t t-if="sector_primary" t-set="sectors" t-value="sectors + [sector_primary]"/>
                <t t-if="industry" t-set="sectors" t-value="sectors + [industry]"/>
                <t t-if="industry_group" t-set="sectors" t-value="sectors + [industry_group]"/>
                <t t-if="sub_industry" t-set="sectors" t-value="sectors + [sub_industry]"/>
                <div t-if="sectors" class="d-flex my-1 p-0 col-sm-3">
                    <i class="fa fa-fw me-2 fa-industry text-primary"/>
                    <b>Sectors</b>
                </div>
                <div t-if="sectors" class="my-1 col-sm-9">
                    <t t-foreach="sectors" t-as="inner_sector">
                        <label t-esc="inner_sector" class="o_tag o_tag_color_7" style="font-weight:normal; padding: 2px 10px; margin: 1px 0px; border-radius: 13px; display: inline-block;"/>
                    </t>
                </div>
                <div t-if="employees" class="d-flex my-1 p-0 col-sm-3">
                    <i class="fa fa-fw me-2 fa-users text-primary"/>
                    <b>Employees</b>
                </div>
                <div t-if="employees" class="my-1 col-sm-9" t-esc="''%.0f'' % employees"/>
                <div t-if="estimated_annual_revenue" class="d-flex my-1 p-0 col-sm-3">
                    <i class="fa fa-fw me-2 fa-money text-primary"/>
                    <b>Estimated revenue</b>
                </div>
                <div t-if="estimated_annual_revenue" class="my-1 col-sm-9">
                    <span t-esc="estimated_annual_revenue"/><span> per year</span>
                </div>
                <div t-if="phone_numbers" class="d-flex my-1 p-0 col-sm-3">
                    <i class="fa fa-fw me-2 fa-phone text-primary"/>
                    <b>Phone</b>
                </div>
                <div t-if="phone_numbers" class="col-sm-9">
                    <t t-foreach="phone_numbers" t-as="phone_number">
                        <a t-attf-href="tel:{{phone_number}}" t-esc="phone_number" class="o_tag o_tag_color_7" style="font-weight:normal; padding: 2px 10px; margin: 1px 0px; border-radius: 13px; display: inline-block;"/>
                    </t>
                </div>
                <div t-if="email" class="d-flex my-1 p-0 col-sm-3">
                    <i class="fa fa-fw me-2 fa-envelope text-primary"/>
                    <b>Email</b>
                </div>
                <div t-if="email" class="col-sm-9">
                    <t t-foreach="email" t-as="email_item">
                        <a target="_top" t-attf-href="mailto:{{email_item}}" t-esc="email_item" class="o_tag o_tag_color_7" style="font-weight:normal; padding: 2px 10px; margin: 1px 0px; border-radius: 13px; display: inline-block;"/>
                    </t>
                </div>
                <div t-if="timezone" class="d-flex my-1 p-0 col-sm-3">
                    <i class="fa fa-fw me-2 fa-globe text-primary"/>
                    <b>Timezone</b>
                </div>
                <div t-if="timezone" class="my-1 col-sm-9" t-esc="timezone.replace(''_'', '' '')"/>
                <div t-if="tech" class="d-flex my-1 p-0 col-sm-3">
                    <i class="fa fa-fw me-2 fa-cube text-primary"/>
                    <b>Technologies Used</b>
                </div>
                <div t-if="tech" class="my-1 col-sm-9">
                    <t t-foreach="tech" t-as="tech_item">
                        <label t-esc="tech_item.replace(''_'', '' '').title()" class="o_tag o_tag_color_7" style="font-weight:normal; padding: 2px 10px; margin: 1px 0px; border-radius: 13px; display: inline-block;"/>
                    </t>
                </div>
                <div t-if="twitter_bio" class="d-flex my-1 p-0 col-sm-3">
                    <i class="fa fa-fw me-2 fa-twitter text-primary"/>
                    <b>Twitter</b>
                </div>
                <div t-if="twitter_bio" class="my-1 col-sm-9">
                    <div class="d-flex gap-2">
                        <a t-if="twitter" target="_blank" t-attf-href="http://www.twitter.com/{{twitter}}" class="text-nowrap">
                            http://www.twitter.com/<t t-esc="twitter"/>
                        </a>
                        <span t-if="twitter"> • </span>
                        <div t-if="twitter_followers" class="text-nowrap"><t t-esc="twitter_followers"/> followers</div>
                    </div>
                    <div t-esc="twitter_bio" class="mt-1"/>
                </div>
            </div>
        </div>
    </t>

    ', false, true, '2026-05-10 01:11:47.980333', '2026-05-10 01:11:47.980333', NULL);
INSERT INTO public.ir_ui_view VALUES (438, 16, NULL, 1, 1, 'enrich_company_by_dnb', NULL, 'iap_mail.enrich_company_by_dnb', 'qweb', 'iap_mail/data/mail_templates.xml', 'primary', '{"en_US": "<t t-name=\"iap_mail.enrich_company_by_dnb\">\n        <div class=\"o_partner_autocomplete_enrich_info p-3 mt-3 mb-3 me-5\">\n            <div class=\"row p-0 m-0\">\n            <div class=\"col-sm-10 p-0\">\n                <h4 class=\"me-3 align-middle\" t-att-style=\"logo and ''margin-top:25px'' or ''''\" t-out=\"name\"/>\n            </div>\n            <div t-if=\"logo\" class=\"col-sm-2 p-0 text-center text-md-end order-first order-md-last\">\n                <img t-attf-src=\"data:image/png;base64, {{logo}}\" alt=\"\" style=\"max-width: 80px;\"/>\n            </div>\n            </div>\n            <hr/>\n\n            <div class=\"col-sm-12 row m-0 p-0\">\n                <div t-if=\"company_type\" class=\"d-flex my-1 p-0 col-sm-3\">\n                    <i class=\"fa fa-fw me-2 fa-building mt-1 text-primary\"/>\n                    <b>Type</b>\n                </div>\n                <div t-if=\"company_type\" class=\"my-1 col-sm-9\" t-out=\"company_type\"/>\n                <div t-if=\"vat\" class=\"d-flex my-1 p-0 col-sm-3\">\n                    <i class=\"fa fa-fw me-2 fa-folder mt-1 text-primary\"/>\n                    <b>Tax ID</b>\n                </div>\n                <div t-if=\"vat\" class=\"my-1 col-sm-9\" t-out=\"vat\"/>\n                <t t-set=\"sectors\" t-value=\"[]\"/>\n                <t t-if=\"sector_primary\" t-set=\"sectors\" t-value=\"sectors + [sector_primary]\"/>\n                <t t-if=\"industry\" t-set=\"sectors\" t-value=\"sectors + [industry]\"/>\n                <t t-if=\"industry_group\" t-set=\"sectors\" t-value=\"sectors + [industry_group]\"/>\n                <t t-if=\"sub_industry\" t-set=\"sectors\" t-value=\"sectors + [sub_industry]\"/>\n                <div class=\"d-flex my-1 p-0 col-sm-3\">\n                    <i class=\"fa fa-fw me-2 fa-address-card text-primary mt-1\"/>\n                    <b>Address</b>\n                </div>\n                <div class=\"my-1 col-sm-9\">\n                    <div class=\"o_address_format\">\n                        <div t-if=\"street\" class=\"o_address_street\" t-out=\"street\"/>\n                        <div t-if=\"street2\" class=\"o_address_street\" t-out=\"street2\"/>\n                        <span t-if=\"city\" t-out=\"city\"/>\n                        <span t-if=\"state\" toutc=\"state\"/>\n                        <span t-if=\"zip_code\" t-out=\"zip_code\"/>\n                        <div t-if=\"country\" class=\"o_address_country\" t-out=\"country\"/>\n                    </div>\n                </div>\n                <div t-if=\"employees\" class=\"d-flex my-1 p-0 col-sm-3\">\n                    <i class=\"fa fa-fw me-2 fa-users text-primary\"/>\n                    <b>Employees</b>\n                </div>\n                <div t-if=\"employees\" class=\"my-1 col-sm-9\" t-out=\"''%.0f'' % employees\"/>\n                <div t-if=\"estimated_annual_revenue\" class=\"d-flex my-1 p-0 col-sm-3\">\n                    <i class=\"fa fa-fw me-2 fa-money mt-1 text-primary\"/>\n                    <b>Estimated revenue</b>\n                </div>\n                <div t-if=\"estimated_annual_revenue\" class=\"my-1 col-sm-9\">\n                    <span t-out=\"estimated_annual_revenue\"/><span> per year</span>\n                </div>\n                <div t-if=\"phone\" class=\"d-flex p-0 my-1 col-sm-3\">\n                    <i class=\"fa fa-fw me-2 fa-phone mt-1 text-primary\"/>\n                    <b>Phone</b>\n                </div>\n                 <div t-if=\"phone\" class=\"col-sm-9 my-1\">\n                    <a t-attf-href=\"tel:{{phone}}\" t-out=\"phone\"/>\n                </div>\n                <div t-if=\"email\" class=\"d-flex my-1 p-0 col-sm-3\">\n                    <i class=\"fa fa-fw me-2 fa-envelope text-primary\" style=\"margin-top: 3px;\"/>\n                    <b>Email</b>\n                </div>\n                <div t-if=\"email\" class=\"col-sm-9 my-1\">\n                    <a target=\"_top\" t-attf-href=\"mailto:{{email}}\" t-out=\"email\"/>\n                </div>\n                 <div t-if=\"website\" class=\"d-flex my-1 p-0 col-sm-3\">\n                    <i class=\"fa fa-fw me-2 fa-globe mt-1 text-primary\"/>\n                    <b>Website</b>\n                </div>\n                <div t-if=\"website\" class=\"my-1 col-sm-9\">\n                    <a target=\"_blank\" t-attf-href=\"{{website}}\" t-out=\"website\"/>\n                </div>\n                 <div t-if=\"tags\" class=\"d-flex my-1 p-0 col-sm-3\">\n                    <i class=\"fa fa-fw me-2 fa-industry text-primary\"/>\n                    <b>Industries</b>\n                </div>\n                 <div t-if=\"tags\" class=\"col-sm-9\">\n                    <t t-foreach=\"tags\" t-as=\"tag_item\">\n                        <label t-out=\"tag_item[1]\" class=\"o_tag o_tag_color_7\" style=\"font-weight:normal; padding: 2px 10px; margin: 1px 0px; border-radius: 13px; display: inline-block;\"/>\n                    </t>\n                </div>\n            </div>\n        </div>\n    </t>"}', '<?xml version="1.0"?>
<t t-name="iap_mail.enrich_company_by_dnb">
        <div class="o_partner_autocomplete_enrich_info p-3 mt-3 mb-3 me-5">
            <div class="row p-0 m-0">
            <div class="col-sm-10 p-0">
                <h4 class="me-3 align-middle" t-att-style="logo and ''margin-top:25px'' or ''''" t-out="name"/>
            </div>
            <div t-if="logo" class="col-sm-2 p-0 text-center text-md-end order-first order-md-last">
                <img t-attf-src="data:image/png;base64, {{logo}}" alt="" style="max-width: 80px;"/>
            </div>
            </div>
            <hr/>

            <div class="col-sm-12 row m-0 p-0">
                <div t-if="company_type" class="d-flex my-1 p-0 col-sm-3">
                    <i class="fa fa-fw me-2 fa-building mt-1 text-primary"/>
                    <b>Type</b>
                </div>
                <div t-if="company_type" class="my-1 col-sm-9" t-out="company_type"/>
                <div t-if="vat" class="d-flex my-1 p-0 col-sm-3">
                    <i class="fa fa-fw me-2 fa-folder mt-1 text-primary"/>
                    <b>Tax ID</b>
                </div>
                <div t-if="vat" class="my-1 col-sm-9" t-out="vat"/>
                <t t-set="sectors" t-value="[]"/>
                <t t-if="sector_primary" t-set="sectors" t-value="sectors + [sector_primary]"/>
                <t t-if="industry" t-set="sectors" t-value="sectors + [industry]"/>
                <t t-if="industry_group" t-set="sectors" t-value="sectors + [industry_group]"/>
                <t t-if="sub_industry" t-set="sectors" t-value="sectors + [sub_industry]"/>
                <div class="d-flex my-1 p-0 col-sm-3">
                    <i class="fa fa-fw me-2 fa-address-card text-primary mt-1"/>
                    <b>Address</b>
                </div>
                <div class="my-1 col-sm-9">
                    <div class="o_address_format">
                        <div t-if="street" class="o_address_street" t-out="street"/>
                        <div t-if="street2" class="o_address_street" t-out="street2"/>
                        <span t-if="city" t-out="city"/>
                        <span t-if="state" toutc="state"/>
                        <span t-if="zip_code" t-out="zip_code"/>
                        <div t-if="country" class="o_address_country" t-out="country"/>
                    </div>
                </div>
                <div t-if="employees" class="d-flex my-1 p-0 col-sm-3">
                    <i class="fa fa-fw me-2 fa-users text-primary"/>
                    <b>Employees</b>
                </div>
                <div t-if="employees" class="my-1 col-sm-9" t-out="''%.0f'' % employees"/>
                <div t-if="estimated_annual_revenue" class="d-flex my-1 p-0 col-sm-3">
                    <i class="fa fa-fw me-2 fa-money mt-1 text-primary"/>
                    <b>Estimated revenue</b>
                </div>
                <div t-if="estimated_annual_revenue" class="my-1 col-sm-9">
                    <span t-out="estimated_annual_revenue"/><span> per year</span>
                </div>
                <div t-if="phone" class="d-flex p-0 my-1 col-sm-3">
                    <i class="fa fa-fw me-2 fa-phone mt-1 text-primary"/>
                    <b>Phone</b>
                </div>
                 <div t-if="phone" class="col-sm-9 my-1">
                    <a t-attf-href="tel:{{phone}}" t-out="phone"/>
                </div>
                <div t-if="email" class="d-flex my-1 p-0 col-sm-3">
                    <i class="fa fa-fw me-2 fa-envelope text-primary" style="margin-top: 3px;"/>
                    <b>Email</b>
                </div>
                <div t-if="email" class="col-sm-9 my-1">
                    <a target="_top" t-attf-href="mailto:{{email}}" t-out="email"/>
                </div>
                 <div t-if="website" class="d-flex my-1 p-0 col-sm-3">
                    <i class="fa fa-fw me-2 fa-globe mt-1 text-primary"/>
                    <b>Website</b>
                </div>
                <div t-if="website" class="my-1 col-sm-9">
                    <a target="_blank" t-attf-href="{{website}}" t-out="website"/>
                </div>
                 <div t-if="tags" class="d-flex my-1 p-0 col-sm-3">
                    <i class="fa fa-fw me-2 fa-industry text-primary"/>
                    <b>Industries</b>
                </div>
                 <div t-if="tags" class="col-sm-9">
                    <t t-foreach="tags" t-as="tag_item">
                        <label t-out="tag_item[1]" class="o_tag o_tag_color_7" style="font-weight:normal; padding: 2px 10px; margin: 1px 0px; border-radius: 13px; display: inline-block;"/>
                    </t>
                </div>
            </div>
        </div>
    </t>
', false, true, '2026-05-10 01:11:47.980333', '2026-05-10 01:11:47.980333', NULL);
INSERT INTO public.ir_ui_view VALUES (439, 16, 381, 1, 1, 'res.users.view.form.preferences.mail_bot', 'res.users', NULL, 'form', 'mail_bot/views/res_users_views.xml', 'extension', '{"en_US": "<data>\n                <field name=\"notification_type\" position=\"after\">\n                    <field name=\"odoobot_state\" groups=\"base.group_no_one\" readonly=\"0\" invisible=\"share\"/>\n                </field>\n            </data>"}', '<?xml version="1.0"?>
