INSERT INTO public.ir_ui_view VALUES (442, 16, NULL, 1, 1, 'phone.blacklist.view.form', 'phone.blacklist', NULL, 'form', 'phone_validation/views/phone_blacklist_views.xml', 'primary', '{"en_US": "<form string=\"Phone Blacklist\" duplicate=\"false\" edit=\"false\">\n                <header>\n                    <button name=\"phone_action_blacklist_remove\" string=\"Unblacklist\" type=\"object\" class=\"oe_highlight\" context=\"{''default_phone'': number}\" invisible=\"not active or not number\"/>\n                    <button name=\"action_add\" string=\"Blacklist\" type=\"object\" class=\"oe_highlight\" invisible=\"active or not number\"/>\n                </header>\n                <sheet>\n                <widget name=\"web_ribbon\" title=\"Archived\" bg_color=\"text-bg-danger\" invisible=\"active\"/>\n                    <group>\n                        <group>\n                            <field name=\"number\"/>\n                            <field name=\"active\" readonly=\"1\"/>\n                            <br/>\n                        </group>\n                    </group>\n                </sheet>\n                <div class=\"oe_chatter\">\n                    <field name=\"message_follower_ids\"/>\n                    <field name=\"message_ids\"/>\n                </div>\n            </form>"}', '<?xml version="1.0"?>
<form string="Phone Blacklist" duplicate="false" edit="false">
                <header>
                    <button name="phone_action_blacklist_remove" string="Unblacklist" type="object" class="oe_highlight" context="{''default_phone'': number}" invisible="not active or not number"/>
                    <button name="action_add" string="Blacklist" type="object" class="oe_highlight" invisible="active or not number"/>
                </header>
                <sheet>
                <widget name="web_ribbon" title="Archived" bg_color="text-bg-danger" invisible="active"/>
                    <group>
                        <group>
                            <field name="number"/>
                            <field name="active" readonly="1"/>
                            <br/>
                        </group>
                    </group>
                </sheet>
                <div class="oe_chatter">
                    <field name="message_follower_ids"/>
                    <field name="message_ids"/>
                </div>
            </form>
        ', false, true, '2026-05-10 01:11:48.206409', '2026-05-10 01:11:48.206409', NULL);
INSERT INTO public.ir_ui_view VALUES (443, 16, NULL, 1, 1, 'phone.blacklist.view.search', 'phone.blacklist', NULL, 'search', 'phone_validation/views/phone_blacklist_views.xml', 'primary', '{"en_US": "<search>\n                <field name=\"number\"/>\n                <filter string=\"Archived\" name=\"inactive\" domain=\"[(''active'',''='',False)]\"/>\n            </search>"}', '<?xml version="1.0"?>
