INSERT INTO public.ir_ui_view VALUES (444, 16, NULL, 1, 1, 'phone.blacklist.remove.form', 'phone.blacklist.remove', NULL, 'form', 'phone_validation/wizard/phone_blacklist_remove_view.xml', 'primary', '{"en_US": "<form string=\"phone_blacklist_removal\">\n                <group class=\"oe_title\">\n                    <field name=\"phone\" string=\"Phone Number\"/>\n                    <field name=\"reason\" string=\"Reason\"/>\n                </group>\n                <footer>\n                    <button name=\"action_unblacklist_apply\" string=\"Confirm\" type=\"object\" class=\"btn-primary\" data-hotkey=\"q\"/>\n                    <button string=\"Discard\" class=\"btn-secondary\" special=\"cancel\" data-hotkey=\"x\"/>\n                </footer>\n            </form>"}', '<?xml version="1.0"?>
<form string="phone_blacklist_removal">
