        ', false, true, '2026-05-10 01:11:48.206409', '2026-05-10 01:11:48.206409', NULL);
INSERT INTO public.ir_ui_view VALUES (445, 16, NULL, 1, 1, 'privacy.lookup.wizard.view.form', 'privacy.lookup.wizard', NULL, 'form', 'privacy_lookup/wizard/privacy_lookup_wizard_views.xml', 'primary', '{"en_US": "<form string=\"Privacy Lookup\">\n                <header>\n                    <button string=\"Lookup\" name=\"action_lookup\" type=\"object\" class=\"oe_highlight\" data-hotkey=\"q\" invisible=\"line_ids\"/>\n                </header>\n                <sheet>\n                    <div class=\"oe_button_box\" name=\"button_box\">\n                        <button name=\"action_open_lines\" type=\"object\" class=\"oe_stat_button\" icon=\"fa-file-text-o\">\n                            <field name=\"line_count\" string=\"References\" widget=\"statinfo\"/>\n                        </button>\n                    </div>\n                    <group>\n                        <group>\n                            <field name=\"email\" readonly=\"line_ids\"/>\n                            <field name=\"name\" readonly=\"line_ids\"/>\n                            <field name=\"records_description\" invisible=\"1\"/>\n                            <field name=\"execution_details\" invisible=\"execution_details == ''''\"/>\n                            <field name=\"log_id\" invisible=\"1\"/>\n                        </group>\n                        <field name=\"line_ids\" options=\"{''no_open'': True, ''no_create'': True}\" invisible=\"1\"/>\n                    </group>\n                </sheet>\n           </form>"}', '<?xml version="1.0"?>
<form string="Privacy Lookup">
                <header>
                    <button string="Lookup" name="action_lookup" type="object" class="oe_highlight" data-hotkey="q" invisible="line_ids"/>
                </header>
                <sheet>
                    <div class="oe_button_box" name="button_box">
                        <button name="action_open_lines" type="object" class="oe_stat_button" icon="fa-file-text-o">
                            <field name="line_count" string="References" widget="statinfo"/>
                        </button>
                    </div>
                    <group>
                        <group>
                            <field name="email" readonly="line_ids"/>
                            <field name="name" readonly="line_ids"/>
                            <field name="records_description" invisible="1"/>
                            <field name="execution_details" invisible="execution_details == ''''"/>
                            <field name="log_id" invisible="1"/>
                        </group>
                        <field name="line_ids" options="{''no_open'': True, ''no_create'': True}" invisible="1"/>
                    </group>
                </sheet>
           </form>
        ', false, true, '2026-05-10 01:11:49.01162', '2026-05-10 01:11:49.01162', NULL);
INSERT INTO public.ir_ui_view VALUES (446, 16, NULL, 1, 1, 'privacy.lookup.wizard.line.view.tree', 'privacy.lookup.wizard.line', NULL, 'tree', 'privacy_lookup/wizard/privacy_lookup_wizard_views.xml', 'primary', '{"en_US": "<tree create=\"0\">\n                <field name=\"res_model_id\"/>\n                <field name=\"res_name\" column_invisible=\"True\"/>\n                <field name=\"res_model\" column_invisible=\"True\"/>\n                <field name=\"resource_ref\" options=\"{''model_field'': ''res_model_id'', ''no_create'': True}\" invisible=\"not resource_ref\"/>\n                <button name=\"action_open_record\" type=\"object\" icon=\"fa-external-link\" invisible=\"not resource_ref\" title=\"Open Record\"/>\n                <field name=\"res_id\" string=\"ID\"/>\n                <field name=\"has_active\" column_invisible=\"True\"/>\n                <field name=\"execution_details\" column_invisible=\"True\"/>\n                <field name=\"is_active\" widget=\"boolean_toggle\" invisible=\"is_unlinked or not has_active\"/>\n                <field name=\"is_unlinked\" column_invisible=\"True\"/>\n                <button name=\"action_unlink\" string=\"Delete\" type=\"object\" icon=\"fa-trash\" invisible=\"is_unlinked\" confirm=\"This operation is irreversible. Do you wish to proceed to the record deletion?\"/>\n            </tree>"}', '<?xml version="1.0"?>
<tree create="0">
                <field name="res_model_id"/>
                <field name="res_name" column_invisible="True"/>
                <field name="res_model" column_invisible="True"/>
                <field name="resource_ref" options="{''model_field'': ''res_model_id'', ''no_create'': True}" invisible="not resource_ref"/>
                <button name="action_open_record" type="object" icon="fa-external-link" invisible="not resource_ref" title="Open Record"/>
                <field name="res_id" string="ID"/>
                <field name="has_active" column_invisible="True"/>
                <field name="execution_details" column_invisible="True"/>
                <field name="is_active" widget="boolean_toggle" invisible="is_unlinked or not has_active"/>
                <field name="is_unlinked" column_invisible="True"/>
                <button name="action_unlink" string="Delete" type="object" icon="fa-trash" invisible="is_unlinked" confirm="This operation is irreversible. Do you wish to proceed to the record deletion?"/>
            </tree>
        ', false, true, '2026-05-10 01:11:49.01162', '2026-05-10 01:11:49.01162', NULL);
INSERT INTO public.ir_ui_view VALUES (584, 16, 192, 1, 1, 'report_layout', NULL, 'snailmail.report_layout', 'qweb', 'snailmail/views/report_assets.xml', 'extension', '{"en_US": "<data inherit_id=\"web.report_layout\">\n        <xpath expr=\"//head\" position=\"inside\">\n            <t t-if=\"env and env.context.get(''snailmail_layout'')\" t-call-assets=\"snailmail.report_assets_snailmail\"/>\n        </xpath>\n    </data>"}', '<?xml version="1.0"?>
