INSERT INTO public.ir_ui_view VALUES (447, 16, NULL, 1, 1, 'privacy.lookup.wizard.line.view.search', 'privacy.lookup.wizard.line', NULL, 'search', 'privacy_lookup/wizard/privacy_lookup_wizard_views.xml', 'primary', '{"en_US": "<search string=\"Search References\">\n                <field name=\"res_model_id\"/>\n                <field name=\"has_active\" invisible=\"1\"/>\n                <field name=\"is_active\" invisible=\"1\"/>\n                <filter string=\"Can be archived\" name=\"can_be_archived\" domain=\"[(''has_active'', ''='', True)]\"/>\n                <filter string=\"Archived\" name=\"archived\" domain=\"[(''is_active'', ''='', False)]\"/>\n                <group expand=\"0\" string=\"Group By\">\n                    <filter string=\"Model\" name=\"group_by_res_model_id\" domain=\"[]\" context=\"{''group_by'': ''res_model_id''}\"/>\n                </group>\n            </search>"}', '<?xml version="1.0"?>
