                    <filter string="Model" name="group_by_res_model_id" domain="[]" context="{''group_by'': ''res_model_id''}"/>
                </group>
            </search>
        ', false, true, '2026-05-10 01:11:49.01162', '2026-05-10 01:11:49.01162', NULL);
INSERT INTO public.ir_ui_view VALUES (448, 16, NULL, 1, 1, 'privacy.log.view.tree', 'privacy.log', NULL, 'tree', 'privacy_lookup/views/privacy_log_views.xml', 'primary', '{"en_US": "<tree string=\"Privacy Logs\">\n                <field name=\"date\"/>\n                <field name=\"anonymized_name\"/>\n                <field name=\"anonymized_email\"/>\n                <field name=\"user_id\" widget=\"many2one_avatar_user\"/>\n                <field name=\"execution_details\"/>\n            </tree>"}', '<?xml version="1.0"?>
