INSERT INTO public.ir_ui_view VALUES (449, 16, NULL, 1, 1, 'privacy.log.view.form', 'privacy.log', NULL, 'form', 'privacy_lookup/views/privacy_log_views.xml', 'primary', '{"en_US": "<form string=\"Privacy Log\">\n                <sheet>\n                    <div class=\"oe_title\">\n                        <h1>\n                            <field name=\"anonymized_name\"/>\n                        </h1>\n                    </div>\n                    <group>\n                        <group>\n                            <field name=\"anonymized_email\"/>\n                            <field name=\"date\"/>\n                            <field name=\"user_id\" widget=\"many2one_avatar_user\"/>\n                        </group>\n                        <group>\n                            <field name=\"records_description\"/>\n                            <field name=\"execution_details\"/>\n                        </group>\n                    </group>\n                    <group>\n                        <field name=\"additional_note\"/>\n                    </group>\n                </sheet>\n            </form>"}', '<?xml version="1.0"?>
