            </form>
        ', false, true, '2026-05-10 01:11:49.01162', '2026-05-10 01:11:49.01162', NULL);
INSERT INTO public.ir_ui_view VALUES (585, 16, 197, 1, 1, 'minimal_layout', NULL, 'snailmail.minimal_layout', 'qweb', 'snailmail/views/report_assets.xml', 'extension', '{"en_US": "<data inherit_id=\"web.minimal_layout\">\n        <xpath expr=\"//head\" position=\"inside\">\n            <t t-if=\"env and env.context.get(''snailmail_layout'')\" t-call-assets=\"snailmail.report_assets_snailmail\"/>\n        </xpath>\n    </data>"}', '<?xml version="1.0"?>
<data inherit_id="web.minimal_layout">
        <xpath expr="//head" position="inside">
            <t t-if="env and env.context.get(''snailmail_layout'')" t-call-assets="snailmail.report_assets_snailmail"/>
        </xpath>
    </data>
', false, true, '2026-05-10 01:11:54.209435', '2026-05-10 01:11:54.209435', false);
INSERT INTO public.ir_ui_view VALUES (450, 16, NULL, 1, 1, 'product.label.layout.form', 'product.label.layout', NULL, 'form', 'product/wizard/product_label_layout_views.xml', 'primary', '{"en_US": "<form>\n                <group>\n                    <group>\n                        <field name=\"product_ids\" invisible=\"1\"/>\n                        <field name=\"product_tmpl_ids\" invisible=\"1\"/>\n                        <field name=\"custom_quantity\"/>\n                        <field name=\"print_format\" widget=\"radio\"/>\n                    </group>\n                    <group>\n                        <field name=\"pricelist_id\" groups=\"product.group_product_pricelist\"/>\n                        <field name=\"extra_html\" widget=\"html\" invisible=\"print_format != ''2x7xprice''\"/>\n                    </group>\n                </group>\n                <footer>\n                    <button name=\"process\" string=\"Confirm\" type=\"object\" class=\"btn-primary\"/>\n                    <button string=\"Discard\" class=\"btn-secondary\" special=\"cancel\"/>\n                </footer>\n            </form>"}', '<?xml version="1.0"?>
<form>
                <group>
                    <group>
                        <field name="product_ids" invisible="1"/>
                        <field name="product_tmpl_ids" invisible="1"/>
                        <field name="custom_quantity"/>
                        <field name="print_format" widget="radio"/>
                    </group>
                    <group>
                        <field name="pricelist_id" groups="product.group_product_pricelist"/>
                        <field name="extra_html" widget="html" invisible="print_format != ''2x7xprice''"/>
                    </group>
                </group>
                <footer>
                    <button name="process" string="Confirm" type="object" class="btn-primary"/>
                    <button string="Discard" class="btn-secondary" special="cancel"/>
                </footer>
            </form>
        ', false, true, '2026-05-10 01:11:49.207732', '2026-05-10 01:11:49.207732', NULL);
INSERT INTO public.ir_ui_view VALUES (940, 16, 770, 1, 1, 'res.partner.property.form.inherit', 'res.partner', NULL, 'form', 'account_check_printing/views/res_partner_views.xml', 'extension', '{"en_US": "<field name=\"property_supplier_payment_term_id\" position=\"after\">\n                <field name=\"property_payment_method_id\" options=\"{''no_open'': True, ''no_create'': True}\" groups=\"account.group_account_invoice,account.group_account_readonly\"/>\n            </field>"}', '<?xml version="1.0"?>
<field name="property_supplier_payment_term_id" position="after">
                <field name="property_payment_method_id" options="{''no_open'': True, ''no_create'': True}" groups="account.group_account_invoice,account.group_account_readonly"/>
            </field>
        ', false, true, '2026-05-10 01:12:09.434736', '2026-05-10 01:12:09.434736', false);
INSERT INTO public.ir_ui_view VALUES (451, 16, NULL, 1, 1, 'product.tag.form', 'product.tag', NULL, 'form', 'product/views/product_tag_views.xml', 'primary', '{"en_US": "<form string=\"Product Tag\">\n                <sheet>\n                    <group>\n                        <field name=\"name\"/>\n                    </group>\n                    <notebook>\n                        <page string=\"Product Templates\" name=\"page_product_templates\">\n                            <field name=\"product_template_ids\" context=\"{''tree_view_ref'':''product.product_template_view_tree_tag''}\"/>\n                        </page>\n                        <page string=\"Product Variants\" name=\"page_product_variants\">\n                            <field name=\"product_product_ids\" context=\"{''tree_view_ref'':''product.product_product_view_tree_tag''}\"/>\n                        </page>\n                        <page string=\"All Products\" name=\"page_all_products\" invisible=\"not product_ids\">\n                            <field name=\"product_ids\" context=\"{''tree_view_ref'':''product.product_product_view_tree_tag''}\"/>\n                        </page>\n                    </notebook>\n                </sheet>\n            </form>"}', '<?xml version="1.0"?>
<form string="Product Tag">
                <sheet>
                    <group>
                        <field name="name"/>
                    </group>
                    <notebook>
                        <page string="Product Templates" name="page_product_templates">
                            <field name="product_template_ids" context="{''tree_view_ref'':''product.product_template_view_tree_tag''}"/>
                        </page>
                        <page string="Product Variants" name="page_product_variants">
                            <field name="product_product_ids" context="{''tree_view_ref'':''product.product_product_view_tree_tag''}"/>
                        </page>
                        <page string="All Products" name="page_all_products" invisible="not product_ids">
                            <field name="product_ids" context="{''tree_view_ref'':''product.product_product_view_tree_tag''}"/>
                        </page>
                    </notebook>
                </sheet>
            </form>
        ', false, true, '2026-05-10 01:11:49.207732', '2026-05-10 01:11:49.207732', NULL);
INSERT INTO public.ir_ui_view VALUES (452, 16, NULL, 1, 1, 'product.tag.tree', 'product.tag', NULL, 'tree', 'product/views/product_tag_views.xml', 'primary', '{"en_US": "<tree string=\"Product Tags\" multi_edit=\"1\">\n                <field name=\"name\"/>\n                <field name=\"product_template_ids\" widget=\"many2many_tags\" optional=\"show\"/>\n                <field name=\"product_product_ids\" widget=\"many2many_tags\" string=\"Product Variant\" optional=\"show\"/>\n            </tree>"}', '<?xml version="1.0"?>
<tree string="Product Tags" multi_edit="1">
                <field name="name"/>
                <field name="product_template_ids" widget="many2many_tags" optional="show"/>
                <field name="product_product_ids" widget="many2many_tags" string="Product Variant" optional="show"/>
            </tree>
        ', false, true, '2026-05-10 01:11:49.207732', '2026-05-10 01:11:49.207732', NULL);
INSERT INTO public.ir_ui_view VALUES (453, 16, NULL, 1, 1, 'product.template.common.form', 'product.template', NULL, 'form', 'product/views/product_views.xml', 'primary', '{"en_US": "<form string=\"Product\">\n                <header>\n                    <button string=\"Print Labels\" type=\"object\" name=\"action_open_label_layout\" invisible=\"detailed_type not in [''consu'', ''product'', ''combo'']\"/>\n                </header>\n                <sheet name=\"product_form\">\n                    <field name=\"product_variant_count\" invisible=\"1\"/>\n                    <field name=\"is_product_variant\" invisible=\"1\"/>\n                    <field name=\"attribute_line_ids\" invisible=\"1\"/>\n                    <field name=\"type\" invisible=\"1\"/>\n                    <field name=\"company_id\" invisible=\"1\"/>\n                    <div class=\"oe_button_box\" name=\"button_box\">\n                        <button class=\"oe_stat_button\" name=\"open_pricelist_rules\" icon=\"fa-list-ul\" groups=\"product.group_product_pricelist\" type=\"object\">\n                               <div class=\"o_field_widget o_stat_info\">\n                                    <span class=\"o_stat_value\">\n                                        <field name=\"pricelist_item_count\"/>\n                                    </span>\n                                    <span class=\"o_stat_text\" invisible=\"pricelist_item_count == 1\">\n                                        Extra Prices\n                                    </span>\n                                    <span class=\"o_stat_text\" invisible=\"pricelist_item_count != 1\">\n                                        Extra Price\n                                    </span>\n                               </div>\n                        </button>\n                        <button class=\"oe_stat_button\" name=\"action_open_documents\" type=\"object\" icon=\"fa-file-text-o\">\n                            <field string=\"Documents\" name=\"product_document_count\" widget=\"statinfo\"/>\n                        </button>\n                    </div>\n                    <widget name=\"web_ribbon\" title=\"Archived\" bg_color=\"text-bg-danger\" invisible=\"active\"/>\n                    <field name=\"id\" invisible=\"True\"/>\n                    <field name=\"image_1920\" widget=\"image\" class=\"oe_avatar\" options=\"{''preview_image'': ''image_128''}\"/>\n                    <div class=\"oe_title\">\n                        <label for=\"name\" string=\"Product Name\"/>\n                        <h1>\n                            <div class=\"d-flex\">\n                                <field name=\"priority\" widget=\"priority\" class=\"me-3\"/>\n                                <field class=\"text-break\" name=\"name\" options=\"{''line_breaks'': False}\" widget=\"text\" placeholder=\"e.g. Cheese Burger\"/>\n                            </div>\n                        </h1>\n                    </div>\n                    <div name=\"options\">\n                        <span class=\"d-inline-flex\">\n                            <field name=\"sale_ok\"/>\n                            <label for=\"sale_ok\"/>\n                        </span>\n                        <span class=\"d-inline-flex\">\n                            <field name=\"purchase_ok\"/>\n                            <label for=\"purchase_ok\"/>\n                        </span>\n                    </div>\n                    <notebook>\n                        <page string=\"General Information\" name=\"general_information\">\n                            <group>\n                                <group name=\"group_general\">\n                                    <field name=\"active\" invisible=\"1\"/>\n                                    <field name=\"detailed_type\"/>\n                                    <field name=\"product_tooltip\" string=\"\" class=\"fst-italic text-muted\" invisible=\"type == ''service'' and not sale_ok\"/>\n                                    <field name=\"uom_id\" groups=\"uom.group_uom\" options=\"{''no_create'': True}\"/>\n                                    <field name=\"uom_po_id\" groups=\"uom.group_uom\" options=\"{''no_create'': True}\"/>\n                                </group>\n                                <group name=\"group_standard_price\">\n                                    <label for=\"list_price\"/>\n                                    <div name=\"pricing\" class=\"o_row\">\n                                      <field name=\"list_price\" class=\"oe_inline\" widget=\"monetary\" options=\"{''currency_field'': ''currency_id'', ''field_digits'': True}\"/>\n                                    </div>\n\n                                    <!--\n                                        `id` condition to prevent invisibility on new products\n                                        when `product_variant_count` is 0.\n                                        `product_variant_count != 1` to handle cases with dynamic\n                                        / multiple variants since id will be set after saving.\n                                        #TODO : revert this and create a compute field in master\n                                        to ensure invisivility for dynamic variants only.\n                                    -->\n                                    <label for=\"standard_price\" invisible=\"id and product_variant_count != 1 and not is_product_variant\"/>\n                                    <div name=\"standard_price_uom\" invisible=\"id and product_variant_count != 1 and not is_product_variant\">\n                                        <field name=\"standard_price\" class=\"oe_inline\" widget=\"monetary\" options=\"{''currency_field'': ''cost_currency_id'', ''field_digits'': True}\"/>\n                                        <span groups=\"uom.group_uom\">per\n                                            <field name=\"uom_name\" class=\"oe_inline\"/>\n                                        </span>\n                                    </div>\n                                    <field name=\"categ_id\" string=\"Product Category\"/>\n                                    <field name=\"product_tag_ids\" widget=\"many2many_tags\" context=\"{''product_template_id'': id}\"/>\n                                    <button name=\"166\" icon=\"oi-arrow-right\" type=\"action\" class=\"btn-link ps-0\" colspan=\"2\" string=\"Configure tags\"/>\n                                    <field name=\"company_id\" groups=\"base.group_multi_company\" options=\"{''no_create'': True}\"/>\n                                    <field name=\"currency_id\" invisible=\"1\"/>\n                                    <field name=\"cost_currency_id\" invisible=\"1\"/>\n                                    <field name=\"product_variant_id\" invisible=\"1\"/>\n                                </group>\n                            </group>\n                            <group string=\"Internal Notes\">\n                                <field colspan=\"2\" name=\"description\" nolabel=\"1\" placeholder=\"This note is only for internal purposes.\"/>\n                            </group>\n                        </page>\n                        <page string=\"Sales\" name=\"sales\" invisible=\"1 or not sale_ok\">\n                            <group name=\"sale\">\n                                <group string=\"Upsell &amp; Cross-Sell\" name=\"upsell\" invisible=\"1\"/>\n                            </group>\n                            <group>\n                                <group string=\"Sales Description\" name=\"description\">\n                                    <field colspan=\"2\" name=\"description_sale\" nolabel=\"1\" placeholder=\"This note is added to sales orders and invoices.\"/>\n                                </group>\n                            </group>\n                        </page>\n                        <page string=\"Purchase\" name=\"purchase\" invisible=\"1 or not purchase_ok\">\n                            <group name=\"purchase\">\n                                <group string=\"Vendor Bills\" name=\"bill\"/>\n                            </group>\n                        </page>\n                        <page string=\"Inventory\" name=\"inventory\" groups=\"product.group_stock_packaging\" invisible=\"type == ''service''\">\n                            <group name=\"inventory\">\n                                <group name=\"group_lots_and_weight\" string=\"Logistics\" invisible=\"type not in [''product'', ''consu'']\">\n                                    <label for=\"weight\" invisible=\"product_variant_count &gt; 1 and not is_product_variant\"/>\n                                    <div class=\"o_row\" name=\"weight\" invisible=\"product_variant_count &gt; 1 and not is_product_variant\">\n                                        <field name=\"weight\" class=\"oe_inline\"/>\n                                        <field name=\"weight_uom_name\"/>\n                                    </div>\n                                    <label for=\"volume\" invisible=\"product_variant_count &gt; 1 and not is_product_variant\"/>\n                                    <div class=\"o_row\" name=\"volume\" invisible=\"product_variant_count &gt; 1 and not is_product_variant\">\n                                        <field name=\"volume\" string=\"Volume\" class=\"oe_inline\"/>\n                                        <field name=\"volume_uom_name\"/>\n                                    </div>\n                                </group>\n                            </group>\n                            <group name=\"packaging\" string=\"Packaging\" colspan=\"4\" invisible=\"(type not in [''product'', ''consu''] or product_variant_count &gt; 1) and not is_product_variant\" groups=\"product.group_stock_packaging\">\n                                <field colspan=\"2\" name=\"packaging_ids\" nolabel=\"1\" context=\"{''tree_view_ref'':''product.product_packaging_tree_view2'', ''default_company_id'': company_id}\"/>\n                            </group>\n                        </page>\n                    </notebook>\n                </sheet>\n                <div class=\"oe_chatter\">\n                    <field name=\"message_follower_ids\"/>\n                    <field name=\"activity_ids\"/>\n                    <field name=\"message_ids\"/>\n                </div>\n            </form>"}', '<?xml version="1.0"?>
<form string="Product">
                <header>
                    <button string="Print Labels" type="object" name="action_open_label_layout" invisible="detailed_type not in [''consu'', ''product'', ''combo'']"/>
                </header>
                <sheet name="product_form">
                    <field name="product_variant_count" invisible="1"/>
                    <field name="is_product_variant" invisible="1"/>
                    <field name="attribute_line_ids" invisible="1"/>
                    <field name="type" invisible="1"/>
                    <field name="company_id" invisible="1"/>
                    <div class="oe_button_box" name="button_box">
                        <button class="oe_stat_button" name="open_pricelist_rules" icon="fa-list-ul" groups="product.group_product_pricelist" type="object">
                               <div class="o_field_widget o_stat_info">
                                    <span class="o_stat_value">
                                        <field name="pricelist_item_count"/>
                                    </span>
                                    <span class="o_stat_text" invisible="pricelist_item_count == 1">
                                        Extra Prices
                                    </span>
                                    <span class="o_stat_text" invisible="pricelist_item_count != 1">
                                        Extra Price
                                    </span>
                               </div>
                        </button>
                        <button class="oe_stat_button" name="action_open_documents" type="object" icon="fa-file-text-o">
                            <field string="Documents" name="product_document_count" widget="statinfo"/>
                        </button>
                    </div>
                    <widget name="web_ribbon" title="Archived" bg_color="text-bg-danger" invisible="active"/>
                    <field name="id" invisible="True"/>
                    <field name="image_1920" widget="image" class="oe_avatar" options="{''preview_image'': ''image_128''}"/>
                    <div class="oe_title">
                        <label for="name" string="Product Name"/>
                        <h1>
                            <div class="d-flex">
                                <field name="priority" widget="priority" class="me-3"/>
                                <field class="text-break" name="name" options="{''line_breaks'': False}" widget="text" placeholder="e.g. Cheese Burger"/>
                            </div>
                        </h1>
                    </div>
                    <div name="options">
                        <span class="d-inline-flex">
                            <field name="sale_ok"/>
                            <label for="sale_ok"/>
                        </span>
                        <span class="d-inline-flex">
                            <field name="purchase_ok"/>
                            <label for="purchase_ok"/>
                        </span>
                    </div>
                    <notebook>
                        <page string="General Information" name="general_information">
                            <group>
                                <group name="group_general">
                                    <field name="active" invisible="1"/>
                                    <field name="detailed_type"/>
                                    <field name="product_tooltip" string="" class="fst-italic text-muted" invisible="type == ''service'' and not sale_ok"/>
                                    <field name="uom_id" groups="uom.group_uom" options="{''no_create'': True}"/>
                                    <field name="uom_po_id" groups="uom.group_uom" options="{''no_create'': True}"/>
                                </group>
                                <group name="group_standard_price">
                                    <label for="list_price"/>
                                    <div name="pricing" class="o_row">
                                      <field name="list_price" class="oe_inline" widget="monetary" options="{''currency_field'': ''currency_id'', ''field_digits'': True}"/>
                                    </div>

                                    <!--
                                        `id` condition to prevent invisibility on new products
                                        when `product_variant_count` is 0.
                                        `product_variant_count != 1` to handle cases with dynamic
                                        / multiple variants since id will be set after saving.
                                        #TODO : revert this and create a compute field in master
                                        to ensure invisivility for dynamic variants only.
                                    -->
                                    <label for="standard_price" invisible="id and product_variant_count != 1 and not is_product_variant"/>
                                    <div name="standard_price_uom" invisible="id and product_variant_count != 1 and not is_product_variant">
                                        <field name="standard_price" class="oe_inline" widget="monetary" options="{''currency_field'': ''cost_currency_id'', ''field_digits'': True}"/>
                                        <span groups="uom.group_uom">per
                                            <field name="uom_name" class="oe_inline"/>
                                        </span>
                                    </div>
                                    <field name="categ_id" string="Product Category"/>
                                    <field name="product_tag_ids" widget="many2many_tags" context="{''product_template_id'': id}"/>
                                    <button name="166" icon="oi-arrow-right" type="action" class="btn-link ps-0" colspan="2" string="Configure tags"/>
                                    <field name="company_id" groups="base.group_multi_company" options="{''no_create'': True}"/>
                                    <field name="currency_id" invisible="1"/>
                                    <field name="cost_currency_id" invisible="1"/>
                                    <field name="product_variant_id" invisible="1"/>
                                </group>
                            </group>
                            <group string="Internal Notes">
                                <field colspan="2" name="description" nolabel="1" placeholder="This note is only for internal purposes."/>
                            </group>
                        </page>
                        <page string="Sales" name="sales" invisible="1 or not sale_ok">
                            <group name="sale">
                                <group string="Upsell &amp; Cross-Sell" name="upsell" invisible="1"/>
                            </group>
                            <group>
                                <group string="Sales Description" name="description">
                                    <field colspan="2" name="description_sale" nolabel="1" placeholder="This note is added to sales orders and invoices."/>
                                </group>
                            </group>
                        </page>
                        <page string="Purchase" name="purchase" invisible="1 or not purchase_ok">
                            <group name="purchase">
                                <group string="Vendor Bills" name="bill"/>
                            </group>
                        </page>
                        <page string="Inventory" name="inventory" groups="product.group_stock_packaging" invisible="type == ''service''">
                            <group name="inventory">
                                <group name="group_lots_and_weight" string="Logistics" invisible="type not in [''product'', ''consu'']">
                                    <label for="weight" invisible="product_variant_count &gt; 1 and not is_product_variant"/>
                                    <div class="o_row" name="weight" invisible="product_variant_count &gt; 1 and not is_product_variant">
                                        <field name="weight" class="oe_inline"/>
                                        <field name="weight_uom_name"/>
                                    </div>
                                    <label for="volume" invisible="product_variant_count &gt; 1 and not is_product_variant"/>
                                    <div class="o_row" name="volume" invisible="product_variant_count &gt; 1 and not is_product_variant">
                                        <field name="volume" string="Volume" class="oe_inline"/>
                                        <field name="volume_uom_name"/>
                                    </div>
                                </group>
                            </group>
                            <group name="packaging" string="Packaging" colspan="4" invisible="(type not in [''product'', ''consu''] or product_variant_count &gt; 1) and not is_product_variant" groups="product.group_stock_packaging">
                                <field colspan="2" name="packaging_ids" nolabel="1" context="{''tree_view_ref'':''product.product_packaging_tree_view2'', ''default_company_id'': company_id}"/>
                            </group>
                        </page>
                    </notebook>
                </sheet>
                <div class="oe_chatter">
                    <field name="message_follower_ids"/>
                    <field name="activity_ids"/>
                    <field name="message_ids"/>
                </div>
            </form>
        ', false, true, '2026-05-10 01:11:49.207732', '2026-05-10 01:11:49.207732', NULL);
INSERT INTO public.ir_ui_view VALUES (454, 16, NULL, 1, 1, 'product.template.search', 'product.template', NULL, 'search', 'product/views/product_views.xml', 'primary', '{"en_US": "<search string=\"Product\">\n                <field name=\"name\" string=\"Product\" filter_domain=\"[''|'', ''|'', ''|'', (''default_code'', ''ilike'', self), (''product_variant_ids.default_code'', ''ilike'', self),(''name'', ''ilike'', self), (''barcode'', ''ilike'', self)]\"/>\n                <field name=\"categ_id\" filter_domain=\"[(''categ_id'', ''child_of'', raw_value)]\"/>\n                <separator/>\n                <filter string=\"Services\" name=\"services\" domain=\"[(''type'',''='',''service'')]\"/>\n                <filter string=\"Products\" name=\"consumable\" domain=\"[(''type'', ''in'', [''consu'', ''product''])]\"/>\n                <separator/>\n                <filter string=\"Can be Sold\" name=\"filter_to_sell\" domain=\"[(''sale_ok'',''='',True)]\"/>\n                <filter string=\"Can be Purchased\" name=\"filter_to_purchase\" domain=\"[(''purchase_ok'', ''='', True)]\"/>\n                <separator/>\n                <field string=\"Attributes\" name=\"attribute_line_ids\" groups=\"product.group_product_variant\"/>\n                <filter invisible=\"1\" string=\"Late Activities\" name=\"activities_overdue\" domain=\"[(''my_activity_date_deadline'', ''&lt;'', context_today().strftime(''%Y-%m-%d''))]\" help=\"Show all records which has next action date is before today\"/>\n                <filter invisible=\"1\" string=\"Today Activities\" name=\"activities_today\" domain=\"[(''my_activity_date_deadline'', ''='', context_today().strftime(''%Y-%m-%d''))]\"/>\n                <filter invisible=\"1\" string=\"Future Activities\" name=\"activities_upcoming_all\" domain=\"[(''my_activity_date_deadline'', ''&gt;'', context_today().strftime(''%Y-%m-%d''))                     ]\"/>\n                <separator/>\n                <filter string=\"Favorites\" name=\"favorites\" domain=\"[(''priority'',''='',''1'')]\"/>\n                <separator/>\n                <filter string=\"Warnings\" name=\"activities_exception\" domain=\"[(''activity_exception_decoration'', ''!='', False)]\"/>\n                <separator/>\n                <filter string=\"Archived\" name=\"inactive\" domain=\"[(''active'',''='',False)]\"/>\n                <group expand=\"1\" string=\"Group By\">\n                    <filter string=\"Product Type\" name=\"type\" context=\"{''group_by'':''detailed_type''}\"/>\n                    <filter string=\"Product Category\" name=\"categ_id\" context=\"{''group_by'':''categ_id''}\"/>\n                </group>\n            </search>"}', '<?xml version="1.0"?>
<search string="Product">
                <field name="name" string="Product" filter_domain="[''|'', ''|'', ''|'', (''default_code'', ''ilike'', self), (''product_variant_ids.default_code'', ''ilike'', self),(''name'', ''ilike'', self), (''barcode'', ''ilike'', self)]"/>
                <field name="categ_id" filter_domain="[(''categ_id'', ''child_of'', raw_value)]"/>
                <separator/>
                <filter string="Services" name="services" domain="[(''type'',''='',''service'')]"/>
                <filter string="Products" name="consumable" domain="[(''type'', ''in'', [''consu'', ''product''])]"/>
                <separator/>
                <filter string="Can be Sold" name="filter_to_sell" domain="[(''sale_ok'',''='',True)]"/>
                <filter string="Can be Purchased" name="filter_to_purchase" domain="[(''purchase_ok'', ''='', True)]"/>
                <separator/>
                <field string="Attributes" name="attribute_line_ids" groups="product.group_product_variant"/>
                <filter invisible="1" string="Late Activities" name="activities_overdue" domain="[(''my_activity_date_deadline'', ''&lt;'', context_today().strftime(''%Y-%m-%d''))]" help="Show all records which has next action date is before today"/>
                <filter invisible="1" string="Today Activities" name="activities_today" domain="[(''my_activity_date_deadline'', ''='', context_today().strftime(''%Y-%m-%d''))]"/>
                <filter invisible="1" string="Future Activities" name="activities_upcoming_all" domain="[(''my_activity_date_deadline'', ''&gt;'', context_today().strftime(''%Y-%m-%d''))                     ]"/>
                <separator/>
                <filter string="Favorites" name="favorites" domain="[(''priority'',''='',''1'')]"/>
                <separator/>
                <filter string="Warnings" name="activities_exception" domain="[(''activity_exception_decoration'', ''!='', False)]"/>
                <separator/>
                <filter string="Archived" name="inactive" domain="[(''active'',''='',False)]"/>
                <group expand="1" string="Group By">
                    <filter string="Product Type" name="type" context="{''group_by'':''detailed_type''}"/>
                    <filter string="Product Category" name="categ_id" context="{''group_by'':''categ_id''}"/>
                </group>
            </search>
        ', false, true, '2026-05-10 01:11:49.207732', '2026-05-10 01:11:49.207732', NULL);
INSERT INTO public.ir_ui_view VALUES (455, 16, 454, 1, 1, 'product.product.search', 'product.product', NULL, 'search', 'product/views/product_views.xml', 'primary', '{"en_US": "<data><field name=\"name\" position=\"replace\">\n                    <field name=\"name\" string=\"Product\" filter_domain=\"[''|'', ''|'', (''default_code'', ''ilike'', self), (''name'', ''ilike'', self), (''barcode'', ''ilike'', self)]\"/>\n                </field>\n                <field name=\"attribute_line_ids\" position=\"replace\">\n                    <field name=\"product_template_attribute_value_ids\" groups=\"product.group_product_variant\"/>\n                    <field name=\"product_tmpl_id\" string=\"Product Template\"/>\n                </field>\n            </data>"}', '<?xml version="1.0"?>
<data><field name="name" position="replace">
                    <field name="name" string="Product" filter_domain="[''|'', ''|'', (''default_code'', ''ilike'', self), (''name'', ''ilike'', self), (''barcode'', ''ilike'', self)]"/>
                </field>
                <field name="attribute_line_ids" position="replace">
