INSERT INTO public.ir_ui_view VALUES (456, 16, NULL, 1, 1, 'product.product.view.form.easy', 'product.product', NULL, 'form', 'product/views/product_views.xml', 'primary', '{"en_US": "<form string=\"Variant Information\" duplicate=\"false\">\n                    <header>\n                        <field name=\"detailed_type\" invisible=\"1\"/>\n                        <button string=\"Print Labels\" type=\"object\" name=\"action_open_label_layout\" invisible=\"detailed_type not in [''consu'', ''product'', ''combo'']\"/>\n                    </header>\n                    <sheet>\n                        <div class=\"oe_button_box\" name=\"button_box\"/>\n                        <widget name=\"web_ribbon\" title=\"Archived\" bg_color=\"text-bg-danger\" invisible=\"active\"/>\n                        <field name=\"active\" invisible=\"1\"/>\n                        <field name=\"id\" invisible=\"1\"/>\n                        <field name=\"company_id\" invisible=\"1\"/>\n                        <field name=\"image_1920\" widget=\"image\" class=\"oe_avatar\" options=\"{''preview_image'': ''image_128''}\"/>\n                        <div class=\"oe_title\">\n                            <label for=\"name\" string=\"Product Name\"/>\n                            <h1><field name=\"name\" readonly=\"1\" placeholder=\"e.g. Odoo Enterprise Subscription\"/></h1>\n                            <field name=\"product_template_attribute_value_ids\" widget=\"many2many_tags\" readonly=\"1\"/>\n                            <p>\n                                <span>All general settings about this product are managed on</span>\n                                <button name=\"open_product_template\" type=\"object\" string=\"the product template.\" class=\"oe_link oe_link_product ps-0 ms-1 mb-1\"/>\n                            </p>\n                        </div>\n                        <group>\n                            <group name=\"codes\" string=\"Codes\">\n                                <field name=\"default_code\"/>\n                                <field name=\"barcode\"/>\n                                <field name=\"type\" invisible=\"1\"/>\n                            </group>\n                            <group name=\"pricing\" string=\"Pricing\">\n                                <field name=\"product_variant_count\" invisible=\"1\"/>\n                                <label for=\"lst_price\" string=\"Sales Price\"/>\n                                <div class=\"o_row\">\n                                    <field name=\"lst_price\" class=\"oe_inline\" widget=\"monetary\" options=\"{''currency_field'': ''currency_id'', ''field_digits'': True}\" readonly=\"product_variant_count &gt; 1\"/>\n                                </div>\n                                <label for=\"standard_price\"/>\n                                <div class=\"o_row\">\n                                    <field name=\"standard_price\" widget=\"monetary\" class=\"oe_inline\" options=\"{''currency_field'': ''cost_currency_id''}\"/>\n                                </div>\n                                <field name=\"currency_id\" invisible=\"1\"/>\n                                <field name=\"cost_currency_id\" invisible=\"1\"/>\n                            </group>\n                        </group>\n                        <group>\n                            <group name=\"weight\" string=\"Logistics\" invisible=\"type not in [''product'', ''consu'']\">\n                                <label for=\"volume\"/>\n                                <div class=\"o_row\">\n                                    <field name=\"volume\" class=\"oe_inline\"/>\n                                    <span><field name=\"volume_uom_name\"/></span>\n                                </div>\n                                <label for=\"weight\"/>\n                                <div class=\"o_row\">\n                                    <field name=\"weight\" class=\"oe_inline\"/>\n                                    <span><field name=\"weight_uom_name\"/></span>\n                                </div>\n                            </group>\n                            <group name=\"tags\" string=\"Tags\">\n                                <field name=\"product_tag_ids\" widget=\"many2many_tags\" readonly=\"1\"/>\n                                <field name=\"additional_product_tag_ids\" widget=\"many2many_tags\" context=\"{''product_variant_id'': id}\"/>\n                                <button name=\"166\" icon=\"oi-arrow-right\" type=\"action\" class=\"btn-link ps-0\" colspan=\"2\" string=\"Configure tags\"/>\n                            </group>\n                        </group>\n                        <group>\n                            <group name=\"packaging\" string=\"Packaging\" groups=\"product.group_stock_packaging\">\n                                <field colspan=\"2\" name=\"packaging_ids\" nolabel=\"1\" context=\"{''tree_view_ref'':''product.product_packaging_tree_view2'', ''default_company_id'': company_id}\"/>\n                            </group>\n                        </group>\n                    </sheet>\n                </form>"}', '<?xml version="1.0"?>
<form string="Variant Information" duplicate="false">
                    <header>
                        <field name="detailed_type" invisible="1"/>
                        <button string="Print Labels" type="object" name="action_open_label_layout" invisible="detailed_type not in [''consu'', ''product'', ''combo'']"/>
                    </header>
                    <sheet>
                        <div class="oe_button_box" name="button_box"/>
                        <widget name="web_ribbon" title="Archived" bg_color="text-bg-danger" invisible="active"/>
                        <field name="active" invisible="1"/>
                        <field name="id" invisible="1"/>
                        <field name="company_id" invisible="1"/>
                        <field name="image_1920" widget="image" class="oe_avatar" options="{''preview_image'': ''image_128''}"/>
                        <div class="oe_title">
                            <label for="name" string="Product Name"/>
                            <h1><field name="name" readonly="1" placeholder="e.g. Odoo Enterprise Subscription"/></h1>
                            <field name="product_template_attribute_value_ids" widget="many2many_tags" readonly="1"/>
                            <p>
                                <span>All general settings about this product are managed on</span>
                                <button name="open_product_template" type="object" string="the product template." class="oe_link oe_link_product ps-0 ms-1 mb-1"/>
                            </p>
                        </div>
                        <group>
                            <group name="codes" string="Codes">
                                <field name="default_code"/>
                                <field name="barcode"/>
                                <field name="type" invisible="1"/>
                            </group>
                            <group name="pricing" string="Pricing">
                                <field name="product_variant_count" invisible="1"/>
                                <label for="lst_price" string="Sales Price"/>
                                <div class="o_row">
                                    <field name="lst_price" class="oe_inline" widget="monetary" options="{''currency_field'': ''currency_id'', ''field_digits'': True}" readonly="product_variant_count &gt; 1"/>
                                </div>
                                <label for="standard_price"/>
                                <div class="o_row">
                                    <field name="standard_price" widget="monetary" class="oe_inline" options="{''currency_field'': ''cost_currency_id''}"/>
                                </div>
                                <field name="currency_id" invisible="1"/>
                                <field name="cost_currency_id" invisible="1"/>
                            </group>
                        </group>
                        <group>
                            <group name="weight" string="Logistics" invisible="type not in [''product'', ''consu'']">
                                <label for="volume"/>
                                <div class="o_row">
                                    <field name="volume" class="oe_inline"/>
                                    <span><field name="volume_uom_name"/></span>
                                </div>
                                <label for="weight"/>
                                <div class="o_row">
                                    <field name="weight" class="oe_inline"/>
                                    <span><field name="weight_uom_name"/></span>
                                </div>
                            </group>
                            <group name="tags" string="Tags">
                                <field name="product_tag_ids" widget="many2many_tags" readonly="1"/>
                                <field name="additional_product_tag_ids" widget="many2many_tags" context="{''product_variant_id'': id}"/>
                                <button name="166" icon="oi-arrow-right" type="action" class="btn-link ps-0" colspan="2" string="Configure tags"/>
                            </group>
                        </group>
                        <group>
                            <group name="packaging" string="Packaging" groups="product.group_stock_packaging">
                                <field colspan="2" name="packaging_ids" nolabel="1" context="{''tree_view_ref'':''product.product_packaging_tree_view2'', ''default_company_id'': company_id}"/>
                            </group>
                        </group>
                    </sheet>
                </form>
            ', false, true, '2026-05-10 01:11:49.207732', '2026-05-10 01:11:49.207732', NULL);
INSERT INTO public.ir_ui_view VALUES (967, 16, NULL, 1, 1, 'report_deliveryslip', NULL, 'stock.report_deliveryslip', 'qweb', 'stock/report/report_deliveryslip.xml', 'primary', '{"en_US": "<t t-name=\"stock.report_deliveryslip\">\n        <t t-foreach=\"docs\" t-as=\"o\">\n            <t t-call=\"stock.report_delivery_document\" t-lang=\"o._get_report_lang()\"/>\n        </t>\n    </t>"}', '<?xml version="1.0"?>
<t t-name="stock.report_deliveryslip">
        <t t-foreach="docs" t-as="o">
            <t t-call="stock.report_delivery_document" t-lang="o._get_report_lang()"/>
        </t>
    </t>
', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (457, 7, NULL, 1, 1, 'product.product.tree', 'product.product', NULL, 'tree', 'product/views/product_views.xml', 'primary', '{"en_US": "<tree string=\"Product Variants\" multi_edit=\"1\" duplicate=\"false\" sample=\"1\">\n                <header>\n                    <button string=\"Print Labels\" type=\"object\" name=\"action_open_label_layout\"/>\n                </header>\n                    <field name=\"priority\" widget=\"priority\" nolabel=\"1\" readonly=\"1\"/>\n                    <field name=\"default_code\" optional=\"show\" readonly=\"1\"/>\n                    <field name=\"barcode\" optional=\"hide\" readonly=\"1\"/>\n                    <field name=\"name\" readonly=\"1\"/>\n                    <field name=\"product_template_variant_value_ids\" widget=\"many2many_tags\" groups=\"product.group_product_variant\" readonly=\"1\"/>\n                    <field name=\"company_id\" groups=\"base.group_multi_company\" optional=\"hide\" readonly=\"1\"/>\n                    <field name=\"lst_price\" optional=\"show\" string=\"Sales Price\"/>\n                    <field name=\"standard_price\" optional=\"show\"/>\n                    <field name=\"categ_id\" optional=\"hide\"/>\n                    <field name=\"product_tag_ids\" widget=\"many2many_tags\" readonly=\"1\" optional=\"hide\"/>\n                    <field name=\"additional_product_tag_ids\" widget=\"many2many_tags\" optional=\"hide\"/>\n                    <field name=\"type\" optional=\"hide\" readonly=\"1\"/>\n                    <field name=\"uom_id\" string=\"Unit\" groups=\"uom.group_uom\" optional=\"show\" readonly=\"1\"/>\n                    <field name=\"product_tmpl_id\" readonly=\"1\" column_invisible=\"True\"/>\n                    <field name=\"active\" column_invisible=\"True\"/>\n                </tree>"}', '<?xml version="1.0"?>
<tree string="Product Variants" multi_edit="1" duplicate="false" sample="1">
                <header>
                    <button string="Print Labels" type="object" name="action_open_label_layout"/>
                </header>
                    <field name="priority" widget="priority" nolabel="1" readonly="1"/>
                    <field name="default_code" optional="show" readonly="1"/>
                    <field name="barcode" optional="hide" readonly="1"/>
                    <field name="name" readonly="1"/>
                    <field name="product_template_variant_value_ids" widget="many2many_tags" groups="product.group_product_variant" readonly="1"/>
                    <field name="company_id" groups="base.group_multi_company" optional="hide" readonly="1"/>
                    <field name="lst_price" optional="show" string="Sales Price"/>
                    <field name="standard_price" optional="show"/>
                    <field name="categ_id" optional="hide"/>
                    <field name="product_tag_ids" widget="many2many_tags" readonly="1" optional="hide"/>
                    <field name="additional_product_tag_ids" widget="many2many_tags" optional="hide"/>
                    <field name="type" optional="hide" readonly="1"/>
                    <field name="uom_id" string="Unit" groups="uom.group_uom" optional="show" readonly="1"/>
                    <field name="product_tmpl_id" readonly="1" column_invisible="True"/>
                    <field name="active" column_invisible="True"/>
                </tree>
            ', false, true, '2026-05-10 01:11:49.207732', '2026-05-10 01:11:49.207732', NULL);
INSERT INTO public.ir_ui_view VALUES (458, 16, NULL, 1, 1, 'product.template.view.tree.tag', 'product.template', NULL, 'tree', 'product/views/product_views.xml', 'primary', '{"en_US": "<tree string=\"Product Templates\" editable=\"bottom\">\n                    <field name=\"name\" readonly=\"1\"/>\n                    <field name=\"default_code\" readonly=\"1\" optional=\"show\"/>\n                    <field name=\"description\" readonly=\"1\" optional=\"show\"/>\n                </tree>"}', '<?xml version="1.0"?>
