INSERT INTO public.ir_ui_view VALUES (459, 16, NULL, 1, 1, 'product.product.view.tree.tag', 'product.product', NULL, 'tree', 'product/views/product_views.xml', 'primary', '{"en_US": "<tree string=\"Product Variants\" editable=\"bottom\">\n                    <field name=\"name\" readonly=\"1\"/>\n                    <field name=\"default_code\" readonly=\"1\" optional=\"show\"/>\n                    <field name=\"product_template_variant_value_ids\" widget=\"many2many_tags\" groups=\"product.group_product_variant\" readonly=\"1\"/>\n                    <field name=\"description\" readonly=\"1\" optional=\"show\"/>\n                </tree>"}', '<?xml version="1.0"?>
