INSERT INTO public.ir_ui_view VALUES (460, 7, 453, 1, 1, 'product.product.form', 'product.product', NULL, 'form', 'product/views/product_views.xml', 'primary', '{"en_US": "<data><form position=\"attributes\">\n                    <attribute name=\"string\">Product Variant</attribute>\n                    <attribute name=\"duplicate\">false</attribute>\n                </form>\n                <xpath expr=\"//div[@name=''standard_price_uom'']\" position=\"after\">\n                    <field name=\"default_code\"/>\n                    <field name=\"barcode\"/>\n                </xpath>\n                <xpath expr=\"//field[@name=''priority'']\" position=\"attributes\">\n                    <attribute name=\"readonly\">1</attribute>\n                </xpath>\n                <field name=\"list_price\" position=\"attributes\">\n                   <attribute name=\"invisible\">1</attribute>\n                   <attribute name=\"readonly\">product_variant_count &gt; 1</attribute>\n                   </field>\n                <xpath expr=\"//label[@for=''list_price'']\" position=\"replace\">\n                    <label for=\"lst_price\"/>\n                </xpath>\n                <field name=\"list_price\" position=\"after\">\n                   <field name=\"lst_price\" class=\"oe_inline\" widget=\"monetary\" options=\"{''currency_field'': ''currency_id'', ''field_digits'': True}\"/>\n                </field>\n                <group name=\"packaging\" position=\"attributes\">\n                    <attribute name=\"invisible\">0</attribute>\n                </group>\n                <field name=\"name\" position=\"after\">\n                    <field name=\"product_tmpl_id\" class=\"oe_inline\" readonly=\"1\" invisible=\"1\" required=\"id\"/>\n                </field>\n                <xpath expr=\"//div[hasclass(''oe_title'')]\" position=\"inside\">\n                    <field name=\"product_template_variant_value_ids\" widget=\"many2many_tags\" readonly=\"1\" groups=\"product.group_product_variant\"/>\n                </xpath>\n                <field name=\"product_tag_ids\" position=\"attributes\">\n                    <attribute name=\"options\">{''no_open'': True}</attribute>\n                    <attribute name=\"context\">{''product_template_id'': product_tmpl_id}</attribute>\n                </field>\n                <field name=\"product_tag_ids\" position=\"after\">\n                    <field name=\"additional_product_tag_ids\" widget=\"many2many_tags\"/>\n                </field>\n            </data>"}', '<?xml version="1.0"?>
<data><form position="attributes">
                    <attribute name="string">Product Variant</attribute>
                    <attribute name="duplicate">false</attribute>
                </form>
                <xpath expr="//div[@name=''standard_price_uom'']" position="after">
                    <field name="default_code"/>
                    <field name="barcode"/>
                </xpath>
                <xpath expr="//field[@name=''priority'']" position="attributes">
                    <attribute name="readonly">1</attribute>
                </xpath>
                <field name="list_price" position="attributes">
                   <attribute name="invisible">1</attribute>
                   <attribute name="readonly">product_variant_count &gt; 1</attribute>
                   </field>
                <xpath expr="//label[@for=''list_price'']" position="replace">
                    <label for="lst_price"/>
                </xpath>
                <field name="list_price" position="after">
                   <field name="lst_price" class="oe_inline" widget="monetary" options="{''currency_field'': ''currency_id'', ''field_digits'': True}"/>
                </field>
                <group name="packaging" position="attributes">
                    <attribute name="invisible">0</attribute>
                </group>
                <field name="name" position="after">
                    <field name="product_tmpl_id" class="oe_inline" readonly="1" invisible="1" required="id"/>
                </field>
                <xpath expr="//div[hasclass(''oe_title'')]" position="inside">
                    <field name="product_template_variant_value_ids" widget="many2many_tags" readonly="1" groups="product.group_product_variant"/>
                </xpath>
                <field name="product_tag_ids" position="attributes">
                    <attribute name="options">{''no_open'': True}</attribute>
                    <attribute name="context">{''product_template_id'': product_tmpl_id}</attribute>
                </field>
                <field name="product_tag_ids" position="after">
                    <field name="additional_product_tag_ids" widget="many2many_tags"/>
                </field>
            </data>', false, true, '2026-05-10 01:11:49.207732', '2026-05-10 01:11:49.207732', NULL);
INSERT INTO public.ir_ui_view VALUES (461, 16, NULL, 1, 1, 'Product Kanban', 'product.product', NULL, 'kanban', 'product/views/product_views.xml', 'primary', '{"en_US": "<kanban sample=\"1\">\n                    <field name=\"id\"/>\n                    <field name=\"lst_price\"/>\n                    <field name=\"activity_state\"/>\n                    <field name=\"color\"/>\n                    <progressbar field=\"activity_state\" colors=\"{&quot;planned&quot;: &quot;success&quot;, &quot;today&quot;: &quot;warning&quot;, &quot;overdue&quot;: &quot;danger&quot;}\"/>\n                    <templates>\n                        <t t-name=\"kanban-box\">\n                            <div class=\"oe_kanban_card oe_kanban_global_click\">\n                                <div class=\"o_kanban_image me-1\">\n                                    <img t-att-src=\"kanban_image(''product.product'', ''image_128'', record.id.raw_value)\" alt=\"Product\" class=\"o_image_64_contain\"/>\n                                </div>\n                                <div class=\"oe_kanban_details\">\n                                    <div class=\"o_kanban_record_top mb-0\">\n                                        <div class=\"o_kanban_record_headings\">\n                                            <strong class=\"o_kanban_record_title\">\n                                                <field name=\"name\"/>\n                                            </strong>\n                                        </div>\n                                        <field name=\"priority\" widget=\"priority\"/>\n                                    </div>\n                                    <t t-if=\"record.default_code.value\">[<field name=\"default_code\"/>]</t>\n                                    <div class=\"o_kanban_tags_section\">\n                                        <field name=\"product_template_variant_value_ids\" groups=\"product.group_product_variant\" widget=\"many2many_tags\" options=\"{''color_field'': ''color''}\"/>\n                                    </div>\n                                    <div name=\"product_lst_price\" class=\"mt-1\">\n                                        Price: <field name=\"lst_price\"/>\n                                    </div>\n                                    <div name=\"tags\"/>\n                                </div>\n                            </div>\n                        </t>\n                    </templates>\n                </kanban>"}', '<?xml version="1.0"?>
<kanban sample="1">
                    <field name="id"/>
                    <field name="lst_price"/>
                    <field name="activity_state"/>
                    <field name="color"/>
                    <progressbar field="activity_state" colors="{&quot;planned&quot;: &quot;success&quot;, &quot;today&quot;: &quot;warning&quot;, &quot;overdue&quot;: &quot;danger&quot;}"/>
                    <templates>
                        <t t-name="kanban-box">
                            <div class="oe_kanban_card oe_kanban_global_click">
                                <div class="o_kanban_image me-1">
                                    <img t-att-src="kanban_image(''product.product'', ''image_128'', record.id.raw_value)" alt="Product" class="o_image_64_contain"/>
                                </div>
                                <div class="oe_kanban_details">
                                    <div class="o_kanban_record_top mb-0">
                                        <div class="o_kanban_record_headings">
                                            <strong class="o_kanban_record_title">
                                                <field name="name"/>
                                            </strong>
                                        </div>
                                        <field name="priority" widget="priority"/>
                                    </div>
                                    <t t-if="record.default_code.value">[<field name="default_code"/>]</t>
                                    <div class="o_kanban_tags_section">
                                        <field name="product_template_variant_value_ids" groups="product.group_product_variant" widget="many2many_tags" options="{''color_field'': ''color''}"/>
                                    </div>
                                    <div name="product_lst_price" class="mt-1">
                                        Price: <field name="lst_price"/>
                                    </div>
                                    <div name="tags"/>
                                </div>
                            </div>
                        </t>
                    </templates>
                </kanban>
            ', false, true, '2026-05-10 01:11:49.207732', '2026-05-10 01:11:49.207732', NULL);
INSERT INTO public.ir_ui_view VALUES (480, 16, NULL, 1, 1, 'product.packaging.tree.view', 'product.packaging', NULL, 'tree', 'product/views/product_packaging_views.xml', 'primary', '{"en_US": "<tree string=\"Product Packagings\" name=\"packaging\">\n                <field name=\"sequence\" widget=\"handle\"/>\n                <field name=\"product_id\"/>\n                <field name=\"name\" string=\"Packaging\"/>\n                <field name=\"qty\"/>\n                <field name=\"product_uom_id\" options=\"{''no_open'': True, ''no_create'': True}\" groups=\"uom.group_uom\"/>\n                <field name=\"barcode\" optional=\"hide\"/>\n                <field name=\"company_id\" groups=\"base.group_multi_company\" optional=\"hide\"/>\n                <field name=\"company_id\" groups=\"!base.group_multi_company\" invisible=\"1\"/>\n            </tree>"}', '<?xml version="1.0"?>
<tree string="Product Packagings" name="packaging">
                <field name="sequence" widget="handle"/>
                <field name="product_id"/>
                <field name="name" string="Packaging"/>
                <field name="qty"/>
                <field name="product_uom_id" options="{''no_open'': True, ''no_create'': True}" groups="uom.group_uom"/>
                <field name="barcode" optional="hide"/>
                <field name="company_id" groups="base.group_multi_company" optional="hide"/>
                <field name="company_id" groups="!base.group_multi_company" invisible="1"/>
            </tree>
        ', false, true, '2026-05-10 01:11:49.207732', '2026-05-10 01:11:49.207732', NULL);
INSERT INTO public.ir_ui_view VALUES (462, 16, NULL, 1, 1, 'product.product.activity', 'product.product', NULL, 'activity', 'product/views/product_views.xml', 'primary', '{"en_US": "<activity string=\"Product Variants\">\n                    <field name=\"id\"/>\n                    <field name=\"default_code\"/>\n                    <templates>\n                        <div t-name=\"activity-box\">\n                            <img t-att-src=\"activity_image(''product.product'', ''image_128'', record.id.raw_value)\" role=\"img\" t-att-title=\"record.id.value\" t-att-alt=\"record.id.value\"/>\n                            <div class=\"ms-2\">\n                                <field name=\"name\" display=\"full\" class=\"o_text_block\"/>\n                                <div t-if=\"record.default_code.value\" class=\"o_text_block text-muted\">\n                                    [<field name=\"default_code\"/>]\n                                </div>\n                            </div>\n                        </div>\n                    </templates>\n                </activity>"}', '<?xml version="1.0"?>
<activity string="Product Variants">
                    <field name="id"/>
                    <field name="default_code"/>
                    <templates>
                        <div t-name="activity-box">
                            <img t-att-src="activity_image(''product.product'', ''image_128'', record.id.raw_value)" role="img" t-att-title="record.id.value" t-att-alt="record.id.value"/>
                            <div class="ms-2">
                                <field name="name" display="full" class="o_text_block"/>
                                <div t-if="record.default_code.value" class="o_text_block text-muted">
                                    [<field name="default_code"/>]
                                </div>
                            </div>
                        </div>
                    </templates>
                </activity>
            ', false, true, '2026-05-10 01:11:49.207732', '2026-05-10 01:11:49.207732', NULL);
INSERT INTO public.ir_ui_view VALUES (463, 16, NULL, 1, 1, 'product.view.kanban.catalog', 'product.product', NULL, 'kanban', 'product/views/product_views.xml', 'primary', '{"en_US": "<kanban records_draggable=\"0\" js_class=\"product_kanban_catalog\">\n                <field name=\"id\" invisible=\"1\"/>\n                <field name=\"default_code\" invisible=\"1\"/>\n                <templates>\n                    <t t-name=\"kanban-menu\">\n                        <div class=\"o_product_catalog_cancel_global_click\">\n                            <a role=\"menuitem\" type=\"edit\" class=\"dropdown-item border-top-0\">Edit</a>\n                        </div>\n                    </t>\n                    <t t-name=\"kanban-box\">\n                        <div class=\"d-flex flex-grow-1\">\n                            <div class=\"o_kanban_image\">\n                                <img t-att-src=\"kanban_image(''product.product'', ''image_128'', record.id.raw_value)\" alt=\"Product\"/>\n                            </div>\n                            <div class=\"oe_kanban_details p-2 d-flex\">\n                                <div class=\"o_kanban_record_top flex-column m-0\" t-attf-id=\"product-{{record.id.raw_value}}\">\n                                    <div class=\"d-flex\">\n                                        <field style=\"margin-top: 2px;\" class=\"me-1\" name=\"priority\" widget=\"priority\"/>\n                                        <h4 class=\"text-reset\">\n                                            <strong class=\"o_kanban_record_title\"><field name=\"name\"/></strong>\n                                        </h4>\n                                    </div>\n                                    <div t-if=\"record.default_code.value\">\n                                        [<field name=\"default_code\"/>]\n                                    </div>\n                                    <!-- Used by @web/product/js/product_catalog/order_line to\n                                         show the price using a t-portal. -->\n                                    <div name=\"o_kanban_price\" t-attf-id=\"product-{{record.id.raw_value}}-price\" class=\"d-flex flex-column\"/>\n                                    <field name=\"product_template_attribute_value_ids\" widget=\"many2many_tags\" domain=\"[(''id'', ''in'', parent.ids)]\" groups=\"product.group_product_variant\" options=\"{''color_field'': ''color''}\"/>\n                                </div>\n                            </div>\n                        </div>\n                    </t>\n                </templates>\n            </kanban>"}', '<?xml version="1.0"?>
<kanban records_draggable="0" js_class="product_kanban_catalog">
                <field name="id" invisible="1"/>
                <field name="default_code" invisible="1"/>
                <templates>
                    <t t-name="kanban-menu">
                        <div class="o_product_catalog_cancel_global_click">
                            <a role="menuitem" type="edit" class="dropdown-item border-top-0">Edit</a>
                        </div>
                    </t>
                    <t t-name="kanban-box">
                        <div class="d-flex flex-grow-1">
                            <div class="o_kanban_image">
                                <img t-att-src="kanban_image(''product.product'', ''image_128'', record.id.raw_value)" alt="Product"/>
                            </div>
                            <div class="oe_kanban_details p-2 d-flex">
                                <div class="o_kanban_record_top flex-column m-0" t-attf-id="product-{{record.id.raw_value}}">
                                    <div class="d-flex">
                                        <field style="margin-top: 2px;" class="me-1" name="priority" widget="priority"/>
                                        <h4 class="text-reset">
                                            <strong class="o_kanban_record_title"><field name="name"/></strong>
                                        </h4>
                                    </div>
                                    <div t-if="record.default_code.value">
                                        [<field name="default_code"/>]
                                    </div>
                                    <!-- Used by @web/product/js/product_catalog/order_line to
                                         show the price using a t-portal. -->
                                    <div name="o_kanban_price" t-attf-id="product-{{record.id.raw_value}}-price" class="d-flex flex-column"/>
                                    <field name="product_template_attribute_value_ids" widget="many2many_tags" domain="[(''id'', ''in'', parent.ids)]" groups="product.group_product_variant" options="{''color_field'': ''color''}"/>
                                </div>
                            </div>
                        </div>
                    </t>
                </templates>
            </kanban>
        ', false, true, '2026-05-10 01:11:49.207732', '2026-05-10 01:11:49.207732', NULL);
INSERT INTO public.ir_ui_view VALUES (464, 16, NULL, 1, 1, 'product.view.search.catalog', 'product.product', NULL, 'search', 'product/views/product_views.xml', 'primary', '{"en_US": "<search string=\"Product\">\n                <!-- Search field -->\n                <field name=\"name\" string=\"Product\" filter_domain=\"[''|'', ''|'', (''default_code'', ''ilike'', self), (''name'', ''ilike'', self), (''barcode'', ''ilike'', self)]\"/>\n                <field name=\"categ_id\" filter_domain=\"[(''categ_id'', ''child_of'', raw_value)]\"/>\n                <field name=\"product_template_attribute_value_ids\" groups=\"product.group_product_variant\"/>\n                <field name=\"product_tmpl_id\" string=\"Product Template\"/>\n                <!-- Filter -->\n                <filter string=\"Favorites\" name=\"favorites\" domain=\"[(''priority'', ''='', ''1'')]\"/>\n                <separator/>\n                <filter string=\"Services\" name=\"services\" domain=\"[(''type'', ''='', ''service'')]\"/>\n                <filter string=\"Products\" name=\"products\" domain=\"[(''type'', ''in'', [''consu'', ''product''])]\"/>\n                <!-- Group By -->\n                <group expand=\"1\" string=\"Group By\">\n                    <filter string=\"Product Type\" name=\"type\" context=\"{''group_by'':''type''}\"/>\n                    <filter string=\"Product Category\" name=\"categ_id\" context=\"{''group_by'':''categ_id''}\"/>\n                </group>\n                <!-- searchpanel -->\n                <searchpanel>\n                    <field name=\"categ_id\" string=\"Product Category\" icon=\"fa-th-list\"/>\n                    <field name=\"product_template_attribute_value_ids\" string=\"Attributes\" icon=\"fa-th-list\" domain=\"[(''ptav_active'', ''='', True), (''product_tmpl_id.active'', ''='', True)]\" enable_counters=\"1\" select=\"multi\"/>\n                </searchpanel>\n            </search>"}', '<?xml version="1.0"?>
<search string="Product">
                <!-- Search field -->
                <field name="name" string="Product" filter_domain="[''|'', ''|'', (''default_code'', ''ilike'', self), (''name'', ''ilike'', self), (''barcode'', ''ilike'', self)]"/>
                <field name="categ_id" filter_domain="[(''categ_id'', ''child_of'', raw_value)]"/>
                <field name="product_template_attribute_value_ids" groups="product.group_product_variant"/>
                <field name="product_tmpl_id" string="Product Template"/>
                <!-- Filter -->
                <filter string="Favorites" name="favorites" domain="[(''priority'', ''='', ''1'')]"/>
                <separator/>
                <filter string="Services" name="services" domain="[(''type'', ''='', ''service'')]"/>
                <filter string="Products" name="products" domain="[(''type'', ''in'', [''consu'', ''product''])]"/>
                <!-- Group By -->
                <group expand="1" string="Group By">
                    <filter string="Product Type" name="type" context="{''group_by'':''type''}"/>
                    <filter string="Product Category" name="categ_id" context="{''group_by'':''categ_id''}"/>
                </group>
                <!-- searchpanel -->
                <searchpanel>
                    <field name="categ_id" string="Product Category" icon="fa-th-list"/>
                    <field name="product_template_attribute_value_ids" string="Attributes" icon="fa-th-list" domain="[(''ptav_active'', ''='', True), (''product_tmpl_id.active'', ''='', True)]" enable_counters="1" select="multi"/>
                </searchpanel>
            </search>
        ', false, true, '2026-05-10 01:11:49.207732', '2026-05-10 01:11:49.207732', NULL);
INSERT INTO public.ir_ui_view VALUES (465, 16, 223, 1, 1, 'res.config.settings.view.form.inherit.product', 'res.config.settings', NULL, 'form', 'product/views/res_config_settings_views.xml', 'extension', '{"en_US": "<data><xpath expr=\"//div[@id=''companies'']\" position=\"after\">\n                    <block title=\"Units of Measure\" id=\"product_general_settings\">\n                        <setting id=\"weight_uom_setting\" string=\"Weight\" help=\"Define your weight unit of measure\">\n                            <field name=\"product_weight_in_lbs\" class=\"o_light_label\" widget=\"radio\" options=\"{''horizontal'': true}\"/>\n                        </setting>\n                        <setting id=\"manage_volume_uom_setting\" string=\"Volume\" help=\"Define your volume unit of measure\">\n                            <field name=\"product_volume_volume_in_cubic_feet\" class=\"o_light_label\" widget=\"radio\" options=\"{''horizontal'': true}\"/>\n                        </setting>\n                    </block>\n                </xpath>\n                 <xpath expr=\"//div[@id=''product_get_pic_setting'']\" position=\"replace\">\n                    <setting id=\"product_get_pic_setting\" string=\"Google Images\" help=\"Get product pictures using Barcode\" documentation=\"/applications/sales/sales/products_prices/products/product_images.html\">\n                        <field name=\"module_product_images\"/>\n                        <div class=\"content-group mt16\" invisible=\"not module_product_images\" id=\"msg_module_product_images\">\n                            <div class=\"mt16 text-warning\">\n                                <strong>Save</strong> this page and come back\n                                here to set up the feature.\n                            </div>\n                        </div>\n                    </setting>\n                 </xpath>\n            </data>"}', '<?xml version="1.0"?>
<data><xpath expr="//div[@id=''companies'']" position="after">
                    <block title="Units of Measure" id="product_general_settings">
                        <setting id="weight_uom_setting" string="Weight" help="Define your weight unit of measure">
                            <field name="product_weight_in_lbs" class="o_light_label" widget="radio" options="{''horizontal'': true}"/>
                        </setting>
                        <setting id="manage_volume_uom_setting" string="Volume" help="Define your volume unit of measure">
                            <field name="product_volume_volume_in_cubic_feet" class="o_light_label" widget="radio" options="{''horizontal'': true}"/>
                        </setting>
                    </block>
                </xpath>
                 <xpath expr="//div[@id=''product_get_pic_setting'']" position="replace">
                    <setting id="product_get_pic_setting" string="Google Images" help="Get product pictures using Barcode" documentation="/applications/sales/sales/products_prices/products/product_images.html">
                        <field name="module_product_images"/>
                        <div class="content-group mt16" invisible="not module_product_images" id="msg_module_product_images">
                            <div class="mt16 text-warning">
                                <strong>Save</strong> this page and come back
                                here to set up the feature.
                            </div>
                        </div>
                    </setting>
                 </xpath>
            </data>', false, true, '2026-05-10 01:11:49.207732', '2026-05-10 01:11:49.207732', NULL);
INSERT INTO public.ir_ui_view VALUES (466, 16, NULL, 1, 1, 'product.attribute.tree', 'product.attribute', NULL, 'tree', 'product/views/product_attribute_views.xml', 'primary', '{"en_US": "<tree string=\"Variant Values\">\n                <field name=\"sequence\" widget=\"handle\"/>\n                <field name=\"name\"/>\n                <field name=\"display_type\"/>\n                <field name=\"create_variant\"/>\n            </tree>"}', '<?xml version="1.0"?>
<tree string="Variant Values">
                <field name="sequence" widget="handle"/>
                <field name="name"/>
                <field name="display_type"/>
                <field name="create_variant"/>
            </tree>
        ', false, true, '2026-05-10 01:11:49.207732', '2026-05-10 01:11:49.207732', NULL);
INSERT INTO public.ir_ui_view VALUES (467, 16, NULL, 1, 1, 'product.attribute.form', 'product.attribute', NULL, 'form', 'product/views/product_attribute_views.xml', 'primary', '{"en_US": "<form string=\"Product Attribute\">\n            <field name=\"number_related_products\" invisible=\"1\"/>\n            <sheet>\n                <div class=\"oe_button_box\" name=\"button_box\">\n                    <button class=\"oe_stat_button\" name=\"action_open_related_products\" type=\"object\" icon=\"fa-bars\" invisible=\"not number_related_products\">\n                        <div class=\"o_stat_info\">\n                            <span class=\"o_stat_value\"><field name=\"number_related_products\"/></span>\n                            <span class=\"o_stat_text\">Related Products</span>\n                        </div>\n                    </button>\n                </div>\n                <group name=\"main_fields\">\n                    <group name=\"sale_main_fields\">\n                        <label for=\"name\" string=\"Attribute Name\"/>\n                        <field name=\"name\" nolabel=\"1\"/>\n                        <field name=\"display_type\" widget=\"radio\"/>\n                        <field name=\"create_variant\" widget=\"radio\" readonly=\"number_related_products != 0\"/>\n                    </group>\n                </group>\n                <notebook>\n                    <page string=\"Attribute Values\" name=\"attribute_values\">\n                        <field name=\"value_ids\" widget=\"one2many\" nolabel=\"1\">\n                            <tree string=\"Values\" editable=\"bottom\">\n                                <field name=\"sequence\" widget=\"handle\"/>\n                                <field name=\"name\"/>\n                                <field name=\"display_type\" column_invisible=\"True\"/>\n                                <field name=\"is_custom\" groups=\"product.group_product_variant\" column_invisible=\"parent.display_type == ''multi''\"/>\n                                <field name=\"html_color\" column_invisible=\"parent.display_type != ''color''\" invisible=\"image\" widget=\"color\"/>\n                                <field name=\"image\" class=\"oe_avatar text-start float-none\" column_invisible=\"parent.display_type != ''color''\" options=\"{''size'': [70, 70]}\" widget=\"image\"/>\n                                <field name=\"default_extra_price\"/>\n                            </tree>\n                        </field>\n                    </page>\n                </notebook>\n            </sheet>\n            </form>"}', '<?xml version="1.0"?>
<form string="Product Attribute">
            <field name="number_related_products" invisible="1"/>
            <sheet>
                <div class="oe_button_box" name="button_box">
                    <button class="oe_stat_button" name="action_open_related_products" type="object" icon="fa-bars" invisible="not number_related_products">
                        <div class="o_stat_info">
                            <span class="o_stat_value"><field name="number_related_products"/></span>
                            <span class="o_stat_text">Related Products</span>
                        </div>
                    </button>
                </div>
                <group name="main_fields">
                    <group name="sale_main_fields">
                        <label for="name" string="Attribute Name"/>
                        <field name="name" nolabel="1"/>
                        <field name="display_type" widget="radio"/>
                        <field name="create_variant" widget="radio" readonly="number_related_products != 0"/>
                    </group>
                </group>
                <notebook>
                    <page string="Attribute Values" name="attribute_values">
                        <field name="value_ids" widget="one2many" nolabel="1">
                            <tree string="Values" editable="bottom">
                                <field name="sequence" widget="handle"/>
                                <field name="name"/>
                                <field name="display_type" column_invisible="True"/>
                                <field name="is_custom" groups="product.group_product_variant" column_invisible="parent.display_type == ''multi''"/>
                                <field name="html_color" column_invisible="parent.display_type != ''color''" invisible="image" widget="color"/>
                                <field name="image" class="oe_avatar text-start float-none" column_invisible="parent.display_type != ''color''" options="{''size'': [70, 70]}" widget="image"/>
                                <field name="default_extra_price"/>
                            </tree>
                        </field>
                    </page>
                </notebook>
            </sheet>
            </form>
        ', false, true, '2026-05-10 01:11:49.207732', '2026-05-10 01:11:49.207732', NULL);
INSERT INTO public.ir_ui_view VALUES (468, 8, NULL, 1, 1, 'product.template.attribute.line.form', 'product.template.attribute.line', NULL, 'form', 'product/views/product_attribute_views.xml', 'primary', '{"en_US": "<form string=\"Product Attribute and Values\">\n                <group name=\"main_field\">\n                    <label for=\"attribute_id\" string=\"Attribute Name\"/>\n                    <field name=\"attribute_id\" nolabel=\"1\"/>\n                    <field name=\"value_ids\" widget=\"one2many\">\n                        <tree string=\"Values\">\n                            <field name=\"name\"/>\n                            <field name=\"html_color\"/>\n                        </tree>\n                        <form string=\"Values\">\n                            <field name=\"name\"/>\n                        </form>\n                    </field>\n                </group>\n            </form>"}', '<?xml version="1.0"?>
<form string="Product Attribute and Values">
                <group name="main_field">
                    <label for="attribute_id" string="Attribute Name"/>
                    <field name="attribute_id" nolabel="1"/>
                    <field name="value_ids" widget="one2many">
                        <tree string="Values">
                            <field name="name"/>
                            <field name="html_color"/>
                        </tree>
                        <form string="Values">
                            <field name="name"/>
                        </form>
                    </field>
                </group>
            </form>
        ', false, true, '2026-05-10 01:11:49.207732', '2026-05-10 01:11:49.207732', NULL);
INSERT INTO public.ir_ui_view VALUES (469, 16, NULL, 1, 1, 'product.template.attribute.value.view.tree', 'product.template.attribute.value', NULL, 'tree', 'product/views/product_attribute_views.xml', 'primary', '{"en_US": "<tree string=\"Attributes\" create=\"0\" delete=\"0\">\n                <field name=\"attribute_id\" optional=\"hide\"/>\n                <field name=\"name\"/>\n                <field name=\"display_type\" optional=\"hide\"/>\n                <field name=\"html_color\" invisible=\"display_type != ''color'' or image\" widget=\"color\"/>\n                <field name=\"image\" invisible=\"display_type != ''color''\" widget=\"image\" options=\"{''size'': [70, 70]}\"/>\n                <field name=\"ptav_active\" optional=\"hide\"/>\n                <field name=\"price_extra\" widget=\"monetary\" options=\"{''field_digits'': True}\"/>\n                <field name=\"currency_id\" column_invisible=\"True\"/>\n            </tree>"}', '<?xml version="1.0"?>
<tree string="Attributes" create="0" delete="0">
                <field name="attribute_id" optional="hide"/>
                <field name="name"/>
                <field name="display_type" optional="hide"/>
                <field name="html_color" invisible="display_type != ''color'' or image" widget="color"/>
                <field name="image" invisible="display_type != ''color''" widget="image" options="{''size'': [70, 70]}"/>
                <field name="ptav_active" optional="hide"/>
                <field name="price_extra" widget="monetary" options="{''field_digits'': True}"/>
                <field name="currency_id" column_invisible="True"/>
            </tree>
        ', false, true, '2026-05-10 01:11:49.207732', '2026-05-10 01:11:49.207732', NULL);
INSERT INTO public.ir_ui_view VALUES (470, 16, NULL, 1, 1, 'product.template.attribute.value.view.form.', 'product.template.attribute.value', NULL, 'form', 'product/views/product_attribute_views.xml', 'primary', '{"en_US": "<form string=\"Product Attribute\" create=\"0\" delete=\"0\">\n                <sheet>\n                    <group>\n                        <field name=\"ptav_active\" readonly=\"1\" invisible=\"ptav_active\"/>\n                        <field name=\"name\"/>\n                        <field name=\"display_type\" invisible=\"1\"/>\n                        <field name=\"html_color\" invisible=\"display_type != ''color'' or image\"/>\n                        <field name=\"image\" invisible=\"display_type != ''color'' or not image\" widget=\"image\" options=\"{''size'': [70, 70]}\"/>\n                        <field name=\"price_extra\" widget=\"monetary\" options=\"{''field_digits'': True}\"/>\n                        <field name=\"currency_id\" invisible=\"1\"/>\n                        <field name=\"exclude_for\" widget=\"one2many\" mode=\"tree\">\n                            <tree editable=\"bottom\">\n                                <field name=\"product_tmpl_id\"/>\n                                <field name=\"value_ids\" widget=\"many2many_tags\" options=\"{''no_create'': True}\"/>\n                            </tree>\n                        </field>\n                    </group>\n                </sheet>\n            </form>"}', '<?xml version="1.0"?>
<form string="Product Attribute" create="0" delete="0">
                <sheet>
                    <group>
                        <field name="ptav_active" readonly="1" invisible="ptav_active"/>
                        <field name="name"/>
                        <field name="display_type" invisible="1"/>
                        <field name="html_color" invisible="display_type != ''color'' or image"/>
                        <field name="image" invisible="display_type != ''color'' or not image" widget="image" options="{''size'': [70, 70]}"/>
                        <field name="price_extra" widget="monetary" options="{''field_digits'': True}"/>
                        <field name="currency_id" invisible="1"/>
                        <field name="exclude_for" widget="one2many" mode="tree">
                            <tree editable="bottom">
                                <field name="product_tmpl_id"/>
                                <field name="value_ids" widget="many2many_tags" options="{''no_create'': True}"/>
                            </tree>
                        </field>
                    </group>
                </sheet>
            </form>
        ', false, true, '2026-05-10 01:11:49.207732', '2026-05-10 01:11:49.207732', NULL);
INSERT INTO public.ir_ui_view VALUES (471, 16, NULL, 1, 1, 'product.template.attribute.value search', 'product.template.attribute.value', NULL, 'search', 'product/views/product_attribute_views.xml', 'primary', '{"en_US": "<search>\n                <field name=\"name\"/>\n                <filter string=\"Active\" name=\"active\" domain=\"[(''ptav_active'', ''='', True)]\"/>\n                <filter string=\"Inactive\" name=\"inactive\" domain=\"[(''ptav_active'', ''='', False)]\"/>\n            </search>"}', '<?xml version="1.0"?>
