        ', false, true, '2026-05-10 01:11:49.207732', '2026-05-10 01:11:49.207732', NULL);
INSERT INTO public.ir_ui_view VALUES (473, 16, NULL, 1, 1, 'product.category.form', 'product.category', NULL, 'form', 'product/views/product_category_views.xml', 'primary', '{"en_US": "<form class=\"oe_form_configuration\">\n                <sheet>\n                    <div class=\"oe_button_box\" name=\"button_box\">\n                        <button class=\"oe_stat_button\" name=\"167\" icon=\"fa-th-list\" type=\"action\" context=\"{''search_default_categ_id'': id, ''default_categ_id'': id, ''group_expand'': True}\">\n                            <div class=\"o_field_widget o_stat_info\">\n                                <span class=\"o_stat_value\"><field name=\"product_count\"/></span>\n                                <span class=\"o_stat_text\"> Products</span>\n                            </div>\n                        </button>\n                    </div>\n                    <div class=\"oe_title\">\n                        <label for=\"name\" string=\"Category\"/>\n                        <h1><field name=\"name\" placeholder=\"e.g. Lamps\"/></h1>\n                    </div>\n                    <group name=\"first\" col=\"2\">\n                        <field name=\"parent_id\" class=\"oe_inline\"/>\n                    </group>\n                </sheet>\n            </form>"}', '<?xml version="1.0"?>
<form class="oe_form_configuration">
                <sheet>
                    <div class="oe_button_box" name="button_box">
                        <button class="oe_stat_button" name="167" icon="fa-th-list" type="action" context="{''search_default_categ_id'': id, ''default_categ_id'': id, ''group_expand'': True}">
                            <div class="o_field_widget o_stat_info">
                                <span class="o_stat_value"><field name="product_count"/></span>
                                <span class="o_stat_text"> Products</span>
                            </div>
                        </button>
                    </div>
                    <div class="oe_title">
                        <label for="name" string="Category"/>
                        <h1><field name="name" placeholder="e.g. Lamps"/></h1>
                    </div>
                    <group name="first" col="2">
                        <field name="parent_id" class="oe_inline"/>
                    </group>
                </sheet>
            </form>
        ', false, true, '2026-05-10 01:11:49.207732', '2026-05-10 01:11:49.207732', NULL);
INSERT INTO public.ir_ui_view VALUES (474, 1, NULL, 1, 1, 'product.category.list', 'product.category', NULL, 'tree', 'product/views/product_category_views.xml', 'primary', '{"en_US": "<tree string=\"Product Categories\">\n                <field name=\"display_name\" string=\"Product Category\"/>\n            </tree>"}', '<?xml version="1.0"?>
