            </search>
        ', false, true, '2026-05-10 01:11:49.207732', '2026-05-10 01:11:49.207732', NULL);
INSERT INTO public.ir_ui_view VALUES (476, 16, NULL, 1, 1, 'product.document.form', 'product.document', NULL, 'form', 'product/views/product_document_views.xml', 'primary', '{"en_US": "<form>\n                <sheet>\n                    <field name=\"res_model\" invisible=\"True\"/>\n                    <label for=\"name\"/>\n                    <h1>\n                        <field name=\"name\" readonly=\"not datas and type != ''url''\"/>\n                    </h1>\n                    <group>\n                        <field name=\"type\" readonly=\"datas or id\" class=\"oe_inline\"/>\n                        <field name=\"datas\" filename=\"name\" invisible=\"type == ''url''\" required=\"type == ''binary''\" class=\"oe_inline\"/>\n                        <field name=\"url\" widget=\"url\" invisible=\"type == ''binary''\" required=\"type == ''url''\"/>\n                        <field name=\"res_name\" string=\"Product Variant\" invisible=\"res_model != ''product.product''\"/>\n                    </group>\n                    <group string=\"Attached To\" groups=\"base.group_no_one\">\n                        <field name=\"res_name\"/>\n                        <field name=\"company_id\" groups=\"base.group_multi_company\" options=\"{''no_create'': True}\" class=\"oe_inline\"/>\n                    </group>\n                    <group string=\"History\" groups=\"base.group_no_one\" invisible=\"not create_date\">\n                        <label for=\"create_uid\" string=\"Creation\"/>\n                        <div name=\"creation_div\">\n                            <field name=\"create_uid\" readonly=\"1\" class=\"oe_inline\"/> on\n                            <field name=\"create_date\" readonly=\"1\" class=\"oe_inline\"/>\n                        </div>\n                    </group>\n                </sheet>\n            </form>"}', '<?xml version="1.0"?>
<form>
                <sheet>
                    <field name="res_model" invisible="True"/>
                    <label for="name"/>
                    <h1>
                        <field name="name" readonly="not datas and type != ''url''"/>
                    </h1>
                    <group>
                        <field name="type" readonly="datas or id" class="oe_inline"/>
                        <field name="datas" filename="name" invisible="type == ''url''" required="type == ''binary''" class="oe_inline"/>
                        <field name="url" widget="url" invisible="type == ''binary''" required="type == ''url''"/>
                        <field name="res_name" string="Product Variant" invisible="res_model != ''product.product''"/>
                    </group>
                    <group string="Attached To" groups="base.group_no_one">
                        <field name="res_name"/>
                        <field name="company_id" groups="base.group_multi_company" options="{''no_create'': True}" class="oe_inline"/>
                    </group>
                    <group string="History" groups="base.group_no_one" invisible="not create_date">
                        <label for="create_uid" string="Creation"/>
                        <div name="creation_div">
                            <field name="create_uid" readonly="1" class="oe_inline"/> on
                            <field name="create_date" readonly="1" class="oe_inline"/>
                        </div>
                    </group>
                </sheet>
            </form>
        ', false, true, '2026-05-10 01:11:49.207732', '2026-05-10 01:11:49.207732', NULL);
INSERT INTO public.ir_ui_view VALUES (477, 16, NULL, 1, 1, 'product.document.kanban', 'product.document', NULL, 'kanban', 'product/views/product_document_views.xml', 'primary', '{"en_US": "<kanban js_class=\"product_documents_kanban\">\n                <field name=\"ir_attachment_id\"/>\n                <field name=\"mimetype\"/>\n                <field name=\"type\"/>\n                <field name=\"name\"/>\n                <field name=\"create_uid\"/>\n                <field name=\"active\"/>\n                <templates>\n                    <t t-name=\"kanban-menu\">\n                        <a t-if=\"widget.editable\" type=\"edit\" class=\"dropdown-item\">Edit</a>\n                        <a t-if=\"widget.deletable\" type=\"delete\" class=\"dropdown-item\">Delete</a>\n                        <a t-attf-href=\"/web/content/#{record.ir_attachment_id.raw_value}?download=true\" download=\"\" class=\"dropdown-item\">Download</a>\n                    </t>\n                    <t t-name=\"kanban-box\">\n                        <div class=\"oe_kanban_global_area o_kanban_attachment\">\n                            <field name=\"res_model\" invisible=\"True\"/>\n                            <div class=\"ribbon ribbon-top-right\" invisible=\"active\">\n                                <span class=\"text-bg-danger\">Archived</span>\n                            </div>\n                            <div class=\"ribbon ribbon-top-right\" invisible=\"not active or res_model != ''product.product''\">\n                                <span class=\"text-bg-secondary\">Variant</span>\n                            </div>\n                            <div class=\"o_kanban_image\">\n                                <t t-set=\"webimage\" t-value=\"new RegExp(''image.*(gif|jpeg|jpg|png|webp)'').test(record.mimetype.value)\"/>\n                                <t t-set=\"binaryPreviewable\" t-value=\"new RegExp(''(image|video|application/pdf|text)'').test(record.mimetype.value) &amp;&amp; record.type.raw_value === ''binary''\"/>\n                                <div t-attf-class=\"o_kanban_image_wrapper #{(webimage or binaryPreviewable) ? ''o_kanban_previewer'' : ''''}\">\n                                    <div t-if=\"record.type.raw_value == ''url''\" class=\"o_url_image fa fa-link fa-3x text-muted\" aria-label=\"Image is a link\"/>\n                                    <img t-elif=\"webimage\" t-attf-src=\"/web/image/#{record.ir_attachment_id.raw_value}\" width=\"100\" height=\"100\" alt=\"Document\" class=\"o_attachment_image\"/>\n                                    <div t-else=\"\" class=\"o_image o_image_thumbnail\" t-att-data-mimetype=\"record.mimetype.value\"/>\n                                </div>\n                            </div>\n                            <div class=\"o_kanban_details h-100\">\n                                <div class=\"o_kanban_details_wrapper h-100 justify-content-between\">\n                                    <div class=\"o_kanban_record_title\">\n                                        <field name=\"name\" class=\"o_text_overflow\"/>\n                                    </div>\n                                    <div class=\"o_kanban_record_body\" name=\"body\" t-if=\"record.type.raw_value == ''url''\">\n                                        <field name=\"url\" widget=\"url\" invisible=\"type == ''binary''\"/>\n                                    </div>\n                                    <div class=\"o_kanban_record_bottom flex-column\" name=\"bottom\">\n                                        <div class=\"mt-2\" invisible=\"res_model != ''product.product''\">\n                                            <span>Variant </span>\n                                            <field name=\"res_name\" style=\"font-style: italic; text-decoration-line: underline;\"/>\n                                        </div>\n                                    </div>\n                                </div>\n                            </div>\n                        </div>\n                    </t>\n                </templates>\n            </kanban>"}', '<?xml version="1.0"?>
<kanban js_class="product_documents_kanban">
                <field name="ir_attachment_id"/>
                <field name="mimetype"/>
                <field name="type"/>
                <field name="name"/>
                <field name="create_uid"/>
                <field name="active"/>
                <templates>
                    <t t-name="kanban-menu">
                        <a t-if="widget.editable" type="edit" class="dropdown-item">Edit</a>
                        <a t-if="widget.deletable" type="delete" class="dropdown-item">Delete</a>
                        <a t-attf-href="/web/content/#{record.ir_attachment_id.raw_value}?download=true" download="" class="dropdown-item">Download</a>
                    </t>
                    <t t-name="kanban-box">
                        <div class="oe_kanban_global_area o_kanban_attachment">
                            <field name="res_model" invisible="True"/>
                            <div class="ribbon ribbon-top-right" invisible="active">
                                <span class="text-bg-danger">Archived</span>
                            </div>
                            <div class="ribbon ribbon-top-right" invisible="not active or res_model != ''product.product''">
                                <span class="text-bg-secondary">Variant</span>
                            </div>
                            <div class="o_kanban_image">
                                <t t-set="webimage" t-value="new RegExp(''image.*(gif|jpeg|jpg|png|webp)'').test(record.mimetype.value)"/>
                                <t t-set="binaryPreviewable" t-value="new RegExp(''(image|video|application/pdf|text)'').test(record.mimetype.value) &amp;&amp; record.type.raw_value === ''binary''"/>
                                <div t-attf-class="o_kanban_image_wrapper #{(webimage or binaryPreviewable) ? ''o_kanban_previewer'' : ''''}">
                                    <div t-if="record.type.raw_value == ''url''" class="o_url_image fa fa-link fa-3x text-muted" aria-label="Image is a link"/>
                                    <img t-elif="webimage" t-attf-src="/web/image/#{record.ir_attachment_id.raw_value}" width="100" height="100" alt="Document" class="o_attachment_image"/>
                                    <div t-else="" class="o_image o_image_thumbnail" t-att-data-mimetype="record.mimetype.value"/>
                                </div>
                            </div>
                            <div class="o_kanban_details h-100">
                                <div class="o_kanban_details_wrapper h-100 justify-content-between">
                                    <div class="o_kanban_record_title">
                                        <field name="name" class="o_text_overflow"/>
                                    </div>
                                    <div class="o_kanban_record_body" name="body" t-if="record.type.raw_value == ''url''">
                                        <field name="url" widget="url" invisible="type == ''binary''"/>
                                    </div>
                                    <div class="o_kanban_record_bottom flex-column" name="bottom">
                                        <div class="mt-2" invisible="res_model != ''product.product''">
                                            <span>Variant </span>
                                            <field name="res_name" style="font-style: italic; text-decoration-line: underline;"/>
                                        </div>
                                    </div>
                                </div>
                            </div>
                        </div>
                    </t>
                </templates>
            </kanban>
        ', false, true, '2026-05-10 01:11:49.207732', '2026-05-10 01:11:49.207732', NULL);
INSERT INTO public.ir_ui_view VALUES (478, 16, NULL, 1, 1, 'product.document.list', 'product.document', NULL, 'tree', 'product/views/product_document_views.xml', 'primary', '{"en_US": "<tree editable=\"top\" multi_edit=\"true\">\n                <field name=\"name\"/>\n                <field name=\"company_id\" groups=\"base.group_multi_company\" optional=\"show\"/>\n            </tree>"}', '<?xml version="1.0"?>
<tree editable="top" multi_edit="true">
                <field name="name"/>
                <field name="company_id" groups="base.group_multi_company" optional="show"/>
            </tree>
        ', false, true, '2026-05-10 01:11:49.207732', '2026-05-10 01:11:49.207732', NULL);
INSERT INTO public.ir_ui_view VALUES (479, 16, NULL, 1, 1, 'product.document.search', 'product.document', NULL, 'search', 'product/views/product_document_views.xml', 'primary', '{"en_US": "<search>\n                <field name=\"name\"/>\n                <filter name=\"archived\" string=\"Archived\" domain=\"[(''active'', ''='', False)]\"/>\n                <filter string=\"Documents of this variant\" name=\"context_variant\" domain=\"[(''res_model'', ''='', ''product.product''), (''res_id'', ''='', context.get(''default_res_id''))]\"/>\n            </search>"}', '<?xml version="1.0"?>
<search>
                <field name="name"/>
