                <filter string="Documents of this variant" name="context_variant" domain="[(''res_model'', ''='', ''product.product''), (''res_id'', ''='', context.get(''default_res_id''))]"/>
            </search>
        ', false, true, '2026-05-10 01:11:49.207732', '2026-05-10 01:11:49.207732', NULL);
INSERT INTO public.ir_ui_view VALUES (481, 16, 480, 1, 1, 'product.packaging.tree.view2', 'product.packaging', NULL, 'tree', 'product/views/product_packaging_views.xml', 'primary', '{"en_US": "<data><xpath expr=\"//field[@name=''product_id'']\" position=\"replace\"/>\n            <xpath expr=\"//tree[@name=''packaging'']\" position=\"attributes\">\n                <attribute name=\"editable\">bottom</attribute>\n            </xpath>\n        </data>"}', '<?xml version="1.0"?>
<data><xpath expr="//field[@name=''product_id'']" position="replace"/>
            <xpath expr="//tree[@name=''packaging'']" position="attributes">
                <attribute name="editable">bottom</attribute>
            </xpath>
