INSERT INTO public.ir_ui_view VALUES (482, 16, NULL, 1, 1, 'product.packaging.form.view', 'product.packaging', NULL, 'form', 'product/views/product_packaging_views.xml', 'primary', '{"en_US": "<form string=\"Product Packaging\">\n                <sheet>\n                    <label for=\"name\" string=\"Packaging\"/>\n                    <h1>\n                        <field name=\"name\"/>\n                    </h1>\n                    <group>\n                        <field name=\"id\" invisible=\"1\"/>\n                        <field name=\"company_id\" invisible=\"1\"/>\n                        <group name=\"group_product\">\n                            <field name=\"product_id\" readonly=\"id\"/>\n                        </group>\n                        <group name=\"qty\">\n                            <label for=\"qty\" string=\"Contained quantity\"/>\n                            <div class=\"o_row\">\n                                <field name=\"qty\"/>\n                                <field name=\"product_uom_id\" options=\"{''no_open'': True, ''no_create'': True}\" groups=\"uom.group_uom\"/>\n                            </div>\n                            <field name=\"barcode\"/>\n                            <field name=\"company_id\" groups=\"base.group_multi_company\"/>\n                        </group>\n                    </group>\n                </sheet>\n            </form>"}', '<?xml version="1.0"?>
<form string="Product Packaging">
                <sheet>
                    <label for="name" string="Packaging"/>
                    <h1>
                        <field name="name"/>
                    </h1>
                    <group>
                        <field name="id" invisible="1"/>
                        <field name="company_id" invisible="1"/>
                        <group name="group_product">
                            <field name="product_id" readonly="id"/>
                        </group>
                        <group name="qty">
                            <label for="qty" string="Contained quantity"/>
                            <div class="o_row">
                                <field name="qty"/>
                                <field name="product_uom_id" options="{''no_open'': True, ''no_create'': True}" groups="uom.group_uom"/>
                            </div>
                            <field name="barcode"/>
                            <field name="company_id" groups="base.group_multi_company"/>
                        </group>
                    </group>
                </sheet>
            </form>
        ', false, true, '2026-05-10 01:11:49.207732', '2026-05-10 01:11:49.207732', NULL);
INSERT INTO public.ir_ui_view VALUES (483, 16, 482, 1, 1, 'product.packaging.form.view2', 'product.packaging', NULL, 'form', 'product/views/product_packaging_views.xml', 'primary', '{"en_US": "<data><xpath expr=\"//group[@name=''group_product'']\" position=\"replace\"/>\n            <xpath expr=\"//field[@name=''id'']\" position=\"replace\"/>\n        </data>"}', '<?xml version="1.0"?>
<data><xpath expr="//group[@name=''group_product'']" position="replace"/>
            <xpath expr="//field[@name=''id'']" position="replace"/>
        </data>', false, true, '2026-05-10 01:11:49.207732', '2026-05-10 01:11:49.207732', NULL);
INSERT INTO public.ir_ui_view VALUES (484, 16, NULL, 1, 1, 'product.pricelist.item.search', 'product.pricelist.item', NULL, 'search', 'product/views/product_pricelist_item_views.xml', 'primary', '{"en_US": "<search string=\"Products Price Rules Search\">\n                <filter name=\"Product Rule\" domain=\"[(''applied_on'', ''='', ''1_product'')]\"/>\n                <filter name=\"Variant Rule\" domain=\"[(''applied_on'', ''='', ''0_product_variant'')]\" groups=\"product.group_product_variant\"/>\n                <separator/>\n                <field name=\"pricelist_id\"/>\n                <field name=\"company_id\" groups=\"base.group_multi_company\"/>\n                <field name=\"currency_id\" groups=\"base.group_multi_currency\"/>\n                <filter string=\"Active\" name=\"visible\" domain=\"[(''pricelist_id.active'', ''='', True)]\"/>\n                <group expand=\"0\" string=\"Group By\">\n                    <filter string=\"Product\" name=\"groupby_product\" domain=\"[]\" context=\"{''group_by'': ''product_tmpl_id''}\"/>\n                    <filter string=\"Variant\" name=\"groupby_product_variant\" domain=\"[(''applied_on'', ''='', ''0_product_variant'')]\" context=\"{''group_by'': ''product_id''}\" groups=\"product.group_product_variant\"/>\n                    <filter string=\"Pricelist\" name=\"groupby_vendor\" domain=\"[]\" context=\"{''group_by'': ''pricelist_id''}\" groups=\"product.group_product_pricelist\"/>\n                </group>\n            </search>"}', '<?xml version="1.0"?>
<search string="Products Price Rules Search">
                <filter name="Product Rule" domain="[(''applied_on'', ''='', ''1_product'')]"/>
                <filter name="Variant Rule" domain="[(''applied_on'', ''='', ''0_product_variant'')]" groups="product.group_product_variant"/>
                <separator/>
                <field name="pricelist_id"/>
                <field name="company_id" groups="base.group_multi_company"/>
                <field name="currency_id" groups="base.group_multi_currency"/>
                <filter string="Active" name="visible" domain="[(''pricelist_id.active'', ''='', True)]"/>
                <group expand="0" string="Group By">
                    <filter string="Product" name="groupby_product" domain="[]" context="{''group_by'': ''product_tmpl_id''}"/>
                    <filter string="Variant" name="groupby_product_variant" domain="[(''applied_on'', ''='', ''0_product_variant'')]" context="{''group_by'': ''product_id''}" groups="product.group_product_variant"/>
                    <filter string="Pricelist" name="groupby_vendor" domain="[]" context="{''group_by'': ''pricelist_id''}" groups="product.group_product_pricelist"/>
                </group>
            </search>
        ', false, true, '2026-05-10 01:11:49.207732', '2026-05-10 01:11:49.207732', NULL);
INSERT INTO public.ir_ui_view VALUES (485, 10, NULL, 1, 1, 'product.pricelist.item.tree', 'product.pricelist.item', NULL, 'tree', 'product/views/product_pricelist_item_views.xml', 'primary', '{"en_US": "<tree string=\"Price Rules\">\n          <field name=\"pricelist_id\"/>\n          <field name=\"name\" string=\"Applied On\"/>\n          <field name=\"price\"/>\n          <field name=\"min_quantity\" colspan=\"4\"/>\n          <field name=\"date_start\" optional=\"hide\"/>\n          <field name=\"date_end\" optional=\"hide\"/>\n          <field name=\"company_id\" groups=\"base.group_multi_company\" optional=\"show\"/>\n        </tree>"}', '<?xml version="1.0"?>
<tree string="Price Rules">
          <field name="pricelist_id"/>
          <field name="name" string="Applied On"/>
          <field name="price"/>
          <field name="min_quantity" colspan="4"/>
          <field name="date_start" optional="hide"/>
          <field name="date_end" optional="hide"/>
          <field name="company_id" groups="base.group_multi_company" optional="show"/>
        </tree>
      ', false, true, '2026-05-10 01:11:49.207732', '2026-05-10 01:11:49.207732', NULL);
INSERT INTO public.ir_ui_view VALUES (486, 100, NULL, 1, 1, 'product.pricelist.item.tree', 'product.pricelist.item', NULL, 'tree', 'product/views/product_pricelist_item_views.xml', 'primary', '{"en_US": "<tree string=\"Pricelist Rules\" editable=\"bottom\">\n                <!-- Scope = coming from a product/product template -->\n                <field name=\"pricelist_id\" string=\"Pricelist\" options=\"{''no_create_edit'':1, ''no_open'': 1}\"/>\n                <field name=\"name\" string=\"Applied On\"/>\n                <field name=\"company_id\" column_invisible=\"True\"/>\n                <field name=\"categ_id\" column_invisible=\"True\"/>\n                <field name=\"product_tmpl_id\" column_invisible=\"context.get(''active_model'') != ''product.category''\" required=\"applied_on == ''1_product''\" domain=\"[(''categ_id'', ''='', context.get(''default_categ_id'', True)), ''|'', (''company_id'', ''='', company_id), (''company_id'', ''='', False)]\" options=\"{''no_create_edit'':1, ''no_open'': 1}\"/>\n                <field name=\"product_id\" groups=\"product.group_product_variant\" readonly=\"context.get(''active_model'') == ''product.product''\" column_invisible=\"context.get(''product_without_variants'', False)\" required=\"applied_on == ''0_product_variant''\" domain=\"[''|'', ''|'',                     (''id'', ''='', context.get(''default_product_id'', 0)),                     (''product_tmpl_id'', ''='', context.get(''default_product_tmpl_id'', 0)),                     (''categ_id'', ''='', context.get(''default_categ_id'', 0)), ''|'', (''company_id'', ''='', company_id), (''company_id'', ''='', False)                   ]\" options=\"{''no_create_edit'':1, ''no_open'': 1}\"/>\n                <field name=\"min_quantity\" colspan=\"4\"/>\n                <field name=\"currency_id\" column_invisible=\"True\"/>\n                <field name=\"fixed_price\" string=\"Price\" required=\"1\"/>\n                <field name=\"date_start\" optional=\"show\"/>\n                <field name=\"date_end\" optional=\"show\"/>\n                <field name=\"applied_on\" column_invisible=\"True\"/>\n                <field name=\"company_id\" groups=\"base.group_multi_company\" optional=\"show\" options=\"{''no_create'':1, ''no_open'': 1}\"/>\n            </tree>"}', '<?xml version="1.0"?>
<tree string="Pricelist Rules" editable="bottom">
                <!-- Scope = coming from a product/product template -->
                <field name="pricelist_id" string="Pricelist" options="{''no_create_edit'':1, ''no_open'': 1}"/>
                <field name="name" string="Applied On"/>
                <field name="company_id" column_invisible="True"/>
                <field name="categ_id" column_invisible="True"/>
                <field name="product_tmpl_id" column_invisible="context.get(''active_model'') != ''product.category''" required="applied_on == ''1_product''" domain="[(''categ_id'', ''='', context.get(''default_categ_id'', True)), ''|'', (''company_id'', ''='', company_id), (''company_id'', ''='', False)]" options="{''no_create_edit'':1, ''no_open'': 1}"/>
                <field name="product_id" groups="product.group_product_variant" readonly="context.get(''active_model'') == ''product.product''" column_invisible="context.get(''product_without_variants'', False)" required="applied_on == ''0_product_variant''" domain="[''|'', ''|'',                     (''id'', ''='', context.get(''default_product_id'', 0)),                     (''product_tmpl_id'', ''='', context.get(''default_product_tmpl_id'', 0)),                     (''categ_id'', ''='', context.get(''default_categ_id'', 0)), ''|'', (''company_id'', ''='', company_id), (''company_id'', ''='', False)                   ]" options="{''no_create_edit'':1, ''no_open'': 1}"/>
                <field name="min_quantity" colspan="4"/>
                <field name="currency_id" column_invisible="True"/>
                <field name="fixed_price" string="Price" required="1"/>
                <field name="date_start" optional="show"/>
                <field name="date_end" optional="show"/>
                <field name="applied_on" column_invisible="True"/>
                <field name="company_id" groups="base.group_multi_company" optional="show" options="{''no_create'':1, ''no_open'': 1}"/>
            </tree>
        ', false, true, '2026-05-10 01:11:49.207732', '2026-05-10 01:11:49.207732', NULL);
INSERT INTO public.ir_ui_view VALUES (515, 16, NULL, 1, 1, 'report_pricelist_page', NULL, 'product.report_pricelist_page', 'qweb', 'product/report/product_pricelist_report_templates.xml', 'primary', '{"en_US": "<t t-name=\"product.report_pricelist_page\">\n        <div class=\"container bg-white p-4 my-4\">\n            <div class=\"oe_structure\"/>\n            <div class=\"row my-3\" t-if=\"display_pricelist_title\">\n                <div class=\"col-12\">\n                    <h2 t-if=\"is_html_type\">\n                        Pricelist:\n                        <a href=\"#\" class=\"o_action\" data-model=\"product.pricelist\" t-att-data-res-id=\"pricelist.id\">\n                            <span t-field=\"pricelist.display_name\">Gold Member Pricelist</span>\n                        </a>\n                    </h2>\n                    <h2 t-else=\"\">\n                        Pricelist: <span t-field=\"pricelist.display_name\">Gold Member Pricelist</span>\n                    </h2>\n                </div>\n            </div>\n            <div class=\"oe_structure\"/>\n            <div class=\"row\">\n                <div class=\"col-12\">\n                    <table class=\"table table-sm\">\n                        <thead>\n                            <th class=\"text-end\" colspan=\"100%\">Quantities (Price)</th>\n                            <tr>\n                                <th>Products</th>\n                                <th groups=\"uom.group_uom\">UOM</th>\n                                <t t-foreach=\"quantities\" t-as=\"qty\">\n                                    <th class=\"text-end\"><span t-out=\"qty\">10 Units</span></th>\n                                </t>\n                            </tr>\n                        </thead>\n                        <tbody>\n                            <t t-foreach=\"products\" t-as=\"product\">\n                                <tr>\n                                    <td t-att-class=\"is_product_tmpl and ''fw-bold'' or None\">\n                                        <a t-if=\"is_html_type\" href=\"#\" class=\"o_action\" t-att-data-model=\"is_product_tmpl and ''product.template'' or ''product.product''\" t-att-data-res-id=\"product[''id'']\">\n                                            <span t-out=\"product[''name'']\">Virtual Interior Design</span>\n                                        </a>\n                                        <span t-else=\"\" t-out=\"product[''name'']\">Acme Widget</span>\n                                    </td>\n                                    <td groups=\"uom.group_uom\" t-out=\"product[''uom'']\"/>\n                                    <t t-foreach=\"quantities\" t-as=\"qty\">\n                                        <td class=\"text-end\">\n                                            <span t-out=\"product[''price''][qty]\" t-options=\"{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: pricelist.currency_id}\">$15.00</span>\n                                        </td>\n                                    </t>\n                                </tr>\n                                <t t-if=\"is_product_tmpl and ''variants'' in product\">\n                                    <tr t-foreach=\"product[''variants'']\" t-as=\"variant\">\n                                        <td>\n                                            <a t-if=\"is_html_type\" href=\"#\" class=\"o_action ms-4\" data-model=\"product.product\" t-att-data-res-id=\"variant[''id'']\">\n                                                <span t-out=\"variant[''name'']\">Acme Widget - Blue</span>\n                                            </a>\n                                            <span t-else=\"\" class=\"ms-4\" t-out=\"variant[''name'']\">Acme Widget - Blue</span>\n                                        </td>\n                                        <td groups=\"uom.group_uom\" t-out=\"product[''uom'']\"/>\n                                        <t t-foreach=\"quantities\" t-as=\"qty\">\n                                            <td class=\"text-end\">\n                                                <span t-out=\"variant[''price''][qty]\" t-options=\"{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: pricelist.currency_id}\">$14.00</span>\n                                            </td>\n                                        </t>\n                                    </tr>\n                                </t>\n                            </t>\n                        </tbody>\n                    </table>\n                </div>\n            </div>\n            <div class=\"oe_structure\"/>\n        </div>\n    </t>"}', '<?xml version="1.0"?>
<t t-name="product.report_pricelist_page">
        <div class="container bg-white p-4 my-4">
            <div class="oe_structure"/>
            <div class="row my-3" t-if="display_pricelist_title">
                <div class="col-12">
                    <h2 t-if="is_html_type">
                        Pricelist:
                        <a href="#" class="o_action" data-model="product.pricelist" t-att-data-res-id="pricelist.id">
                            <span t-field="pricelist.display_name">Gold Member Pricelist</span>
                        </a>
                    </h2>
                    <h2 t-else="">
                        Pricelist: <span t-field="pricelist.display_name">Gold Member Pricelist</span>
                    </h2>
                </div>
            </div>
            <div class="oe_structure"/>
            <div class="row">
                <div class="col-12">
                    <table class="table table-sm">
                        <thead>
                            <th class="text-end" colspan="100%">Quantities (Price)</th>
                            <tr>
                                <th>Products</th>
                                <th groups="uom.group_uom">UOM</th>
                                <t t-foreach="quantities" t-as="qty">
                                    <th class="text-end"><span t-out="qty">10 Units</span></th>
                                </t>
                            </tr>
                        </thead>
                        <tbody>
                            <t t-foreach="products" t-as="product">
                                <tr>
                                    <td t-att-class="is_product_tmpl and ''fw-bold'' or None">
                                        <a t-if="is_html_type" href="#" class="o_action" t-att-data-model="is_product_tmpl and ''product.template'' or ''product.product''" t-att-data-res-id="product[''id'']">
                                            <span t-out="product[''name'']">Virtual Interior Design</span>
                                        </a>
                                        <span t-else="" t-out="product[''name'']">Acme Widget</span>
                                    </td>
                                    <td groups="uom.group_uom" t-out="product[''uom'']"/>
                                    <t t-foreach="quantities" t-as="qty">
                                        <td class="text-end">
                                            <span t-out="product[''price''][qty]" t-options="{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: pricelist.currency_id}">$15.00</span>
                                        </td>
                                    </t>
                                </tr>
                                <t t-if="is_product_tmpl and ''variants'' in product">
                                    <tr t-foreach="product[''variants'']" t-as="variant">
                                        <td>
                                            <a t-if="is_html_type" href="#" class="o_action ms-4" data-model="product.product" t-att-data-res-id="variant[''id'']">
                                                <span t-out="variant[''name'']">Acme Widget - Blue</span>
                                            </a>
                                            <span t-else="" class="ms-4" t-out="variant[''name'']">Acme Widget - Blue</span>
                                        </td>
                                        <td groups="uom.group_uom" t-out="product[''uom'']"/>
                                        <t t-foreach="quantities" t-as="qty">
                                            <td class="text-end">
                                                <span t-out="variant[''price''][qty]" t-options="{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: pricelist.currency_id}">$14.00</span>
                                            </td>
                                        </t>
                                    </tr>
                                </t>
                            </t>
                        </tbody>
                    </table>
                </div>
            </div>
            <div class="oe_structure"/>
        </div>
    </t>

    ', false, true, '2026-05-10 01:11:49.207732', '2026-05-10 01:11:49.207732', NULL);
INSERT INTO public.ir_ui_view VALUES (487, 16, NULL, 1, 1, 'product.pricelist.item.form', 'product.pricelist.item', NULL, 'form', 'product/views/product_pricelist_item_views.xml', 'primary', '{"en_US": "<form string=\"Pricelist Rule\">\n                <sheet>\n                    <field name=\"name\" invisible=\"1\"/>\n                    <field name=\"company_id\" invisible=\"1\"/>\n                    <group name=\"pricelist_rule_computation\" groups=\"product.group_sale_pricelist\" string=\"Price Computation\">\n                        <group name=\"pricelist_rule_method\">\n                            <field name=\"compute_price\" string=\"Computation\" widget=\"radio\"/>\n                        </group>\n                        <div class=\"alert alert-info\" role=\"alert\" groups=\"uom.group_uom\">\n                            The computed price is expressed in the default Unit of Measure of the product.\n                        </div>\n                    </group>\n                    <group name=\"pricelist_rule_base\" groups=\"product.group_sale_pricelist\">\n                        <group>\n                            <field name=\"price\" invisible=\"1\"/>\n                            <field name=\"fixed_price\" widget=\"monetary\" invisible=\"compute_price != ''fixed''\" options=\"{''field_digits'': True}\"/>\n                            <label for=\"percent_price\" string=\"Discount\" invisible=\"compute_price != ''percentage''\"/>\n                            <div class=\"o_row\" invisible=\"compute_price != ''percentage''\">\n                                <field name=\"percent_price\" class=\"oe_inline\" invisible=\"compute_price != ''percentage''\"/>%\n                            </div>\n                            <field name=\"base\" invisible=\"compute_price != ''formula''\"/>\n                            <field name=\"base_pricelist_id\" invisible=\"compute_price != ''formula'' or base != ''pricelist''\" readonly=\"base != ''pricelist''\" required=\"compute_price == ''formula'' and base == ''pricelist''\"/>\n                            <label for=\"price_discount\" string=\"Discount\" invisible=\"compute_price != ''formula''\"/>\n                            <div class=\"o_row\" invisible=\"compute_price != ''formula''\">\n                                <field name=\"price_discount\"/>\n                                <span>%</span>\n                            </div>\n                            <field name=\"price_surcharge\" widget=\"monetary\" string=\"Extra Fee\" invisible=\"compute_price != ''formula''\"/>\n                            <field name=\"price_round\" string=\"Rounding Method\" invisible=\"compute_price != ''formula''\"/>\n                            <label string=\"Margins\" for=\"price_min_margin\" invisible=\"compute_price != ''formula''\"/>\n                            <div class=\"o_row\" invisible=\"compute_price != ''formula''\">\n                                <field name=\"price_min_margin\" string=\"Min. Margin\" class=\"oe_inline\" widget=\"monetary\" nolabel=\"1\" options=\"{''field_digits'': True}\"/>\n                                <i class=\"fa fa-long-arrow-right mx-2 oe_edit_only\" aria-label=\"Arrow icon\" title=\"Arrow\"/>\n                                <field name=\"price_max_margin\" string=\"Max. Margin\" class=\"oe_inline\" widget=\"monetary\" nolabel=\"1\" options=\"{''field_digits'': True}\"/>\n                            </div>\n                        </group>\n                        <div class=\"alert alert-info\" role=\"alert\" style=\"white-space: pre;\" invisible=\"compute_price != ''formula''\">\n                            <field name=\"rule_tip\"/>\n                        </div>\n                    </group>\n\n                    <group string=\"Conditions\">\n                        <group name=\"pricelist_rule_target\">\n                            <field name=\"applied_on\" widget=\"radio\"/>\n                            <field name=\"categ_id\" options=\"{''no_create'':1}\" invisible=\"applied_on != ''2_product_category''\" required=\"applied_on == ''2_product_category''\"/>\n                            <field name=\"product_tmpl_id\" options=\"{''no_create'':1}\" invisible=\"applied_on != ''1_product''\" required=\"applied_on == ''1_product''\"/>\n                            <field name=\"product_id\" options=\"{''no_create'':1}\" invisible=\"applied_on != ''0_product_variant''\" required=\"applied_on == ''0_product_variant''\"/>\n                        </group>\n                        <group name=\"pricelist_rule_limits\">\n                            <field name=\"min_quantity\"/>\n                            <field name=\"date_start\" string=\"Validity\" widget=\"daterange\" options=\"{''end_date_field'': ''date_end''}\"/>\n                            <field name=\"date_end\" invisible=\"1\"/>\n                        </group>\n                        <group name=\"pricelist_rule_related\" groups=\"base.group_no_one\">\n                            <field name=\"pricelist_id\" invisible=\"1\"/>\n                            <field name=\"currency_id\" groups=\"base.group_multi_currency\"/>\n                            <field name=\"company_id\" groups=\"base.group_multi_company\"/>\n                        </group>\n                    </group>\n                </sheet>\n            </form>"}', '<?xml version="1.0"?>
<form string="Pricelist Rule">
                <sheet>
                    <field name="name" invisible="1"/>
                    <field name="company_id" invisible="1"/>
                    <group name="pricelist_rule_computation" groups="product.group_sale_pricelist" string="Price Computation">
                        <group name="pricelist_rule_method">
                            <field name="compute_price" string="Computation" widget="radio"/>
                        </group>
                        <div class="alert alert-info" role="alert" groups="uom.group_uom">
                            The computed price is expressed in the default Unit of Measure of the product.
                        </div>
                    </group>
                    <group name="pricelist_rule_base" groups="product.group_sale_pricelist">
                        <group>
                            <field name="price" invisible="1"/>
                            <field name="fixed_price" widget="monetary" invisible="compute_price != ''fixed''" options="{''field_digits'': True}"/>
                            <label for="percent_price" string="Discount" invisible="compute_price != ''percentage''"/>
                            <div class="o_row" invisible="compute_price != ''percentage''">
                                <field name="percent_price" class="oe_inline" invisible="compute_price != ''percentage''"/>%
                            </div>
                            <field name="base" invisible="compute_price != ''formula''"/>
                            <field name="base_pricelist_id" invisible="compute_price != ''formula'' or base != ''pricelist''" readonly="base != ''pricelist''" required="compute_price == ''formula'' and base == ''pricelist''"/>
                            <label for="price_discount" string="Discount" invisible="compute_price != ''formula''"/>
                            <div class="o_row" invisible="compute_price != ''formula''">
                                <field name="price_discount"/>
                                <span>%</span>
                            </div>
                            <field name="price_surcharge" widget="monetary" string="Extra Fee" invisible="compute_price != ''formula''"/>
                            <field name="price_round" string="Rounding Method" invisible="compute_price != ''formula''"/>
                            <label string="Margins" for="price_min_margin" invisible="compute_price != ''formula''"/>
                            <div class="o_row" invisible="compute_price != ''formula''">
                                <field name="price_min_margin" string="Min. Margin" class="oe_inline" widget="monetary" nolabel="1" options="{''field_digits'': True}"/>
                                <i class="fa fa-long-arrow-right mx-2 oe_edit_only" aria-label="Arrow icon" title="Arrow"/>
                                <field name="price_max_margin" string="Max. Margin" class="oe_inline" widget="monetary" nolabel="1" options="{''field_digits'': True}"/>
                            </div>
                        </group>
                        <div class="alert alert-info" role="alert" style="white-space: pre;" invisible="compute_price != ''formula''">
                            <field name="rule_tip"/>
                        </div>
                    </group>

                    <group string="Conditions">
                        <group name="pricelist_rule_target">
                            <field name="applied_on" widget="radio"/>
                            <field name="categ_id" options="{''no_create'':1}" invisible="applied_on != ''2_product_category''" required="applied_on == ''2_product_category''"/>
                            <field name="product_tmpl_id" options="{''no_create'':1}" invisible="applied_on != ''1_product''" required="applied_on == ''1_product''"/>
                            <field name="product_id" options="{''no_create'':1}" invisible="applied_on != ''0_product_variant''" required="applied_on == ''0_product_variant''"/>
                        </group>
                        <group name="pricelist_rule_limits">
                            <field name="min_quantity"/>
                            <field name="date_start" string="Validity" widget="daterange" options="{''end_date_field'': ''date_end''}"/>
                            <field name="date_end" invisible="1"/>
                        </group>
                        <group name="pricelist_rule_related" groups="base.group_no_one">
                            <field name="pricelist_id" invisible="1"/>
                            <field name="currency_id" groups="base.group_multi_currency"/>
                            <field name="company_id" groups="base.group_multi_company"/>
                        </group>
                    </group>
                </sheet>
            </form>
        ', false, true, '2026-05-10 01:11:49.207732', '2026-05-10 01:11:49.207732', NULL);
INSERT INTO public.ir_ui_view VALUES (488, 16, NULL, 1, 1, 'product.pricelist.search', 'product.pricelist', NULL, 'search', 'product/views/product_pricelist_views.xml', 'primary', '{"en_US": "<search string=\"Products Price Search\">\n                <field name=\"name\" string=\"Products Price\"/>\n                <field name=\"currency_id\" groups=\"base.group_multi_currency\"/>\n                <filter string=\"Archived\" name=\"inactive\" domain=\"[(''active'',''='',False)]\"/>\n            </search>"}', '<?xml version="1.0"?>
<search string="Products Price Search">
                <field name="name" string="Products Price"/>
                <field name="currency_id" groups="base.group_multi_currency"/>
                <filter string="Archived" name="inactive" domain="[(''active'',''='',False)]"/>
            </search>
        ', false, true, '2026-05-10 01:11:49.207732', '2026-05-10 01:11:49.207732', NULL);
INSERT INTO public.ir_ui_view VALUES (489, 16, NULL, 1, 1, 'product.pricelist.tree', 'product.pricelist', NULL, 'tree', 'product/views/product_pricelist_views.xml', 'primary', '{"en_US": "<tree string=\"Products Price List\" sample=\"1\">\n                <field name=\"sequence\" widget=\"handle\"/>\n                <field name=\"name\"/>\n                <field name=\"discount_policy\"/>\n                <field name=\"currency_id\" groups=\"base.group_multi_currency\"/>\n                <field name=\"company_id\" groups=\"base.group_multi_company\"/>\n            </tree>"}', '<?xml version="1.0"?>
<tree string="Products Price List" sample="1">
                <field name="sequence" widget="handle"/>
                <field name="name"/>
                <field name="discount_policy"/>
                <field name="currency_id" groups="base.group_multi_currency"/>
                <field name="company_id" groups="base.group_multi_company"/>
            </tree>
        ', false, true, '2026-05-10 01:11:49.207732', '2026-05-10 01:11:49.207732', NULL);
INSERT INTO public.ir_ui_view VALUES (490, 16, NULL, 1, 1, 'product.pricelist.kanban', 'product.pricelist', NULL, 'kanban', 'product/views/product_pricelist_views.xml', 'primary', '{"en_US": "<kanban class=\"o_kanban_mobile\" sample=\"1\">\n                <templates>\n                    <t t-name=\"kanban-box\">\n                        <div t-attf-class=\"oe_kanban_global_click\">\n                            <div id=\"product_pricelist\" class=\"o_kanban_record_top mb0\">\n                                <div class=\"o_kanban_record_headings\">\n                                    <strong class=\"o_kanban_record_title\">\n                                        <span><field name=\"name\"/></span>\n                                    </strong>\n                                </div>\n                                <strong>\n                                    <i class=\"fa fa-money\" role=\"img\" aria-label=\"Currency\" title=\"Currency\"/> <field name=\"currency_id\"/>\n                                </strong>\n                            </div>\n                            <field name=\"discount_policy\"/>\n                        </div>\n                    </t>\n                </templates>\n            </kanban>"}', '<?xml version="1.0"?>
<kanban class="o_kanban_mobile" sample="1">
                <templates>
                    <t t-name="kanban-box">
                        <div t-attf-class="oe_kanban_global_click">
                            <div id="product_pricelist" class="o_kanban_record_top mb0">
                                <div class="o_kanban_record_headings">
                                    <strong class="o_kanban_record_title">
                                        <span><field name="name"/></span>
                                    </strong>
                                </div>
                                <strong>
                                    <i class="fa fa-money" role="img" aria-label="Currency" title="Currency"/> <field name="currency_id"/>
                                </strong>
                            </div>
                            <field name="discount_policy"/>
                        </div>
                    </t>
                </templates>
            </kanban>
        ', false, true, '2026-05-10 01:11:49.207732', '2026-05-10 01:11:49.207732', NULL);
INSERT INTO public.ir_ui_view VALUES (491, 16, NULL, 1, 1, 'product.pricelist.form', 'product.pricelist', NULL, 'form', 'product/views/product_pricelist_views.xml', 'primary', '{"en_US": "<form string=\"Products Price List\">\n                <sheet>\n                    <widget name=\"web_ribbon\" title=\"Archived\" bg_color=\"text-bg-danger\" invisible=\"active\"/>\n                    <div class=\"oe_title\">\n                        <h1><field name=\"name\" placeholder=\"e.g. USD Retailers\"/></h1>\n                    </div>\n                    <group>\n                        <group name=\"pricelist_settings\">\n                            <field name=\"currency_id\" groups=\"base.group_multi_currency\"/>\n                            <field name=\"active\" invisible=\"1\"/>\n                            <field name=\"company_id\" groups=\"base.group_multi_company\" options=\"{''no_create'': True}\"/>\n                        </group>\n                    </group>\n                    <notebook>\n                        <page name=\"pricelist_rules\" string=\"Price Rules\">\n                            <field name=\"item_ids\" nolabel=\"1\" context=\"{''default_base'':''list_price''}\">\n                                <tree groups=\"!product.group_sale_pricelist\" string=\"Pricelist Rules\" editable=\"bottom\">\n                                    <field name=\"product_tmpl_id\" string=\"Products\" required=\"1\"/>\n                                    <field name=\"product_id\" string=\"Variants\" groups=\"product.group_product_variant\" domain=\"[(''product_tmpl_id'', ''='', product_tmpl_id)]\" options=\"{''no_create'':1}\"/>\n                                    <field name=\"min_quantity\"/>\n                                    <field name=\"fixed_price\" string=\"Price\"/>\n                                    <field name=\"currency_id\" column_invisible=\"True\"/>\n                                    <field name=\"pricelist_id\" column_invisible=\"True\"/>\n                                    <!-- Pricelist ID is here only for related fields to be correctly computed -->\n                                    <field name=\"date_start\"/>\n                                    <field name=\"date_end\"/>\n                                    <field name=\"base\" column_invisible=\"True\"/>\n                                    <field name=\"applied_on\" column_invisible=\"True\"/>\n                                    <field name=\"company_id\" column_invisible=\"True\"/>\n                                </tree>\n                                <!-- When in advanced pricelist mode : pricelist rules\n                                    Should open in a form view and not be editable inline anymore.\n                                -->\n                                <tree groups=\"product.group_sale_pricelist\" string=\"Pricelist Rules\">\n                                    <field name=\"product_tmpl_id\" column_invisible=\"True\"/>\n                                    <field name=\"name\" string=\"Applicable On\"/>\n                                    <field name=\"min_quantity\"/>\n                                    <field name=\"price\" string=\"Price\"/>\n                                    <field name=\"date_start\"/>\n                                    <field name=\"date_end\"/>\n                                    <field name=\"base\" column_invisible=\"True\"/>\n                                    <field name=\"price_discount\" column_invisible=\"True\"/>\n                                    <field name=\"applied_on\" column_invisible=\"True\"/>\n                                    <field name=\"compute_price\" column_invisible=\"True\"/>\n                                </tree>\n                            </field>\n                        </page>\n                        <page name=\"pricelist_config\" string=\"Configuration\">\n                            <group>\n                                <group name=\"pricelist_availability\" string=\"Availability\">\n                                    <field name=\"country_group_ids\" widget=\"many2many_tags\"/>\n                                </group>\n                                <group name=\"pricelist_discounts\" string=\"Discounts\">\n                                    <field name=\"discount_policy\" widget=\"radio\"/>\n                                </group>\n                            </group>\n                        </page>\n                    </notebook>\n                </sheet>\n                <div class=\"oe_chatter\">\n                    <field name=\"activity_ids\"/>\n                    <field name=\"message_follower_ids\"/>\n                    <field name=\"message_ids\"/>\n                </div>\n            </form>"}', '<?xml version="1.0"?>
<form string="Products Price List">
                <sheet>
                    <widget name="web_ribbon" title="Archived" bg_color="text-bg-danger" invisible="active"/>
                    <div class="oe_title">
                        <h1><field name="name" placeholder="e.g. USD Retailers"/></h1>
                    </div>
                    <group>
                        <group name="pricelist_settings">
                            <field name="currency_id" groups="base.group_multi_currency"/>
                            <field name="active" invisible="1"/>
                            <field name="company_id" groups="base.group_multi_company" options="{''no_create'': True}"/>
                        </group>
                    </group>
                    <notebook>
                        <page name="pricelist_rules" string="Price Rules">
                            <field name="item_ids" nolabel="1" context="{''default_base'':''list_price''}">
                                <tree groups="!product.group_sale_pricelist" string="Pricelist Rules" editable="bottom">
                                    <field name="product_tmpl_id" string="Products" required="1"/>
                                    <field name="product_id" string="Variants" groups="product.group_product_variant" domain="[(''product_tmpl_id'', ''='', product_tmpl_id)]" options="{''no_create'':1}"/>
                                    <field name="min_quantity"/>
                                    <field name="fixed_price" string="Price"/>
                                    <field name="currency_id" column_invisible="True"/>
                                    <field name="pricelist_id" column_invisible="True"/>
                                    <!-- Pricelist ID is here only for related fields to be correctly computed -->
                                    <field name="date_start"/>
                                    <field name="date_end"/>
                                    <field name="base" column_invisible="True"/>
                                    <field name="applied_on" column_invisible="True"/>
                                    <field name="company_id" column_invisible="True"/>
                                </tree>
                                <!-- When in advanced pricelist mode : pricelist rules
                                    Should open in a form view and not be editable inline anymore.
                                -->
                                <tree groups="product.group_sale_pricelist" string="Pricelist Rules">
                                    <field name="product_tmpl_id" column_invisible="True"/>
                                    <field name="name" string="Applicable On"/>
                                    <field name="min_quantity"/>
                                    <field name="price" string="Price"/>
                                    <field name="date_start"/>
                                    <field name="date_end"/>
                                    <field name="base" column_invisible="True"/>
                                    <field name="price_discount" column_invisible="True"/>
                                    <field name="applied_on" column_invisible="True"/>
                                    <field name="compute_price" column_invisible="True"/>
                                </tree>
                            </field>
                        </page>
                        <page name="pricelist_config" string="Configuration">
                            <group>
                                <group name="pricelist_availability" string="Availability">
                                    <field name="country_group_ids" widget="many2many_tags"/>
                                </group>
                                <group name="pricelist_discounts" string="Discounts">
                                    <field name="discount_policy" widget="radio"/>
                                </group>
                            </group>
                        </page>
                    </notebook>
                </sheet>
                <div class="oe_chatter">
                    <field name="activity_ids"/>
                    <field name="message_follower_ids"/>
                    <field name="message_ids"/>
                </div>
            </form>
        ', false, true, '2026-05-10 01:11:49.207732', '2026-05-10 01:11:49.207732', NULL);
INSERT INTO public.ir_ui_view VALUES (492, 16, NULL, 1, 1, 'product.supplierinfo.form.view', 'product.supplierinfo', NULL, 'form', 'product/views/product_supplierinfo_views.xml', 'primary', '{"en_US": "<form string=\"Vendor Information\">\n                <sheet>\n                    <group>\n                        <group name=\"vendor\" string=\"Vendor\">\n                            <field name=\"product_variant_count\" invisible=\"1\"/>\n                            <field name=\"partner_id\" context=\"{''res_partner_search_mode'': ''supplier''}\"/>\n                            <field name=\"product_name\"/>\n                            <field name=\"product_code\"/>\n                            <label for=\"delay\"/>\n                            <div>\n                                <field name=\"delay\" class=\"oe_inline\"/> days\n                            </div>\n                        </group>\n                        <group string=\"Pricelist\">\n                            <field name=\"product_tmpl_id\" string=\"Product\" invisible=\"context.get(''visible_product_tmpl_id'', True)\"/>\n                            <field name=\"product_id\" groups=\"product.group_product_variant\" options=\"{''no_create'': True}\"/>\n                            <label for=\"min_qty\"/>\n                            <div class=\"o_row\">\n                                <field name=\"min_qty\"/>\n                                <field name=\"product_uom\" groups=\"uom.group_uom\"/>\n                            </div>\n                            <label for=\"price\" string=\"Unit Price\"/>\n                            <div class=\"o_row\">\n                                <field name=\"price\" class=\"oe_inline\"/><field name=\"currency_id\" groups=\"base.group_multi_currency\"/>\n                            </div>\n                            <label for=\"date_start\" string=\"Validity\"/>\n                            <div class=\"o_row\"><field name=\"date_start\" class=\"oe_inline\"/> to <field name=\"date_end\" class=\"oe_inline\"/></div>\n                            <field name=\"discount\"/>\n                            <field name=\"company_id\" options=\"{''no_create'': True}\"/>\n                        </group>\n                    </group>\n                </sheet>\n            </form>"}', '<?xml version="1.0"?>
<form string="Vendor Information">
                <sheet>
                    <group>
                        <group name="vendor" string="Vendor">
                            <field name="product_variant_count" invisible="1"/>
                            <field name="partner_id" context="{''res_partner_search_mode'': ''supplier''}"/>
                            <field name="product_name"/>
                            <field name="product_code"/>
                            <label for="delay"/>
                            <div>
                                <field name="delay" class="oe_inline"/> days
                            </div>
                        </group>
                        <group string="Pricelist">
                            <field name="product_tmpl_id" string="Product" invisible="context.get(''visible_product_tmpl_id'', True)"/>
                            <field name="product_id" groups="product.group_product_variant" options="{''no_create'': True}"/>
                            <label for="min_qty"/>
                            <div class="o_row">
                                <field name="min_qty"/>
                                <field name="product_uom" groups="uom.group_uom"/>
                            </div>
                            <label for="price" string="Unit Price"/>
                            <div class="o_row">
                                <field name="price" class="oe_inline"/><field name="currency_id" groups="base.group_multi_currency"/>
                            </div>
                            <label for="date_start" string="Validity"/>
                            <div class="o_row"><field name="date_start" class="oe_inline"/> to <field name="date_end" class="oe_inline"/></div>
                            <field name="discount"/>
                            <field name="company_id" options="{''no_create'': True}"/>
                        </group>
                    </group>
                </sheet>
            </form>
        ', false, true, '2026-05-10 01:11:49.207732', '2026-05-10 01:11:49.207732', NULL);
INSERT INTO public.ir_ui_view VALUES (493, 16, NULL, 1, 1, 'product.supplierinfo.search.view', 'product.supplierinfo', NULL, 'search', 'product/views/product_supplierinfo_views.xml', 'primary', '{"en_US": "<search string=\"Vendor\">\n                <field name=\"partner_id\"/>\n                <field name=\"product_tmpl_id\"/>\n                <field name=\"product_name\"/>\n                <field name=\"product_code\"/>\n                <filter string=\"Active Products\" name=\"active_products\" domain=\"[''|'', (''product_tmpl_id.active'', ''='', True),(''product_id.active'', ''='', True)]\"/>\n                <separator/>\n                <filter string=\"Active\" name=\"active\" domain=\"[''|'', (''date_end'', ''='', False), (''date_end'', ''&gt;='',  (context_today() - datetime.timedelta(days=1)).strftime(''%Y-%m-%d''))]\"/>\n                <filter string=\"Archived\" name=\"archived\" domain=\"[(''date_end'', ''&lt;'',  (context_today() - datetime.timedelta(days=1)).strftime(''%Y-%m-%d''))]\"/>\n                <group expand=\"0\" string=\"Group By\">\n                    <filter string=\"Product\" name=\"groupby_product\" domain=\"[]\" context=\"{''group_by'': ''product_tmpl_id''}\"/>\n                    <filter string=\"Vendor\" name=\"groupby_vendor\" domain=\"[]\" context=\"{''group_by'': ''partner_id''}\"/>\n                </group>\n            </search>"}', '<?xml version="1.0"?>
<search string="Vendor">
                <field name="partner_id"/>
                <field name="product_tmpl_id"/>
                <field name="product_name"/>
                <field name="product_code"/>
                <filter string="Active Products" name="active_products" domain="[''|'', (''product_tmpl_id.active'', ''='', True),(''product_id.active'', ''='', True)]"/>
                <separator/>
                <filter string="Active" name="active" domain="[''|'', (''date_end'', ''='', False), (''date_end'', ''&gt;='',  (context_today() - datetime.timedelta(days=1)).strftime(''%Y-%m-%d''))]"/>
                <filter string="Archived" name="archived" domain="[(''date_end'', ''&lt;'',  (context_today() - datetime.timedelta(days=1)).strftime(''%Y-%m-%d''))]"/>
                <group expand="0" string="Group By">
                    <filter string="Product" name="groupby_product" domain="[]" context="{''group_by'': ''product_tmpl_id''}"/>
                    <filter string="Vendor" name="groupby_vendor" domain="[]" context="{''group_by'': ''partner_id''}"/>
                </group>
            </search>
        ', false, true, '2026-05-10 01:11:49.207732', '2026-05-10 01:11:49.207732', NULL);
INSERT INTO public.ir_ui_view VALUES (494, 16, NULL, 1, 1, 'product.supplierinfo.kanban', 'product.supplierinfo', NULL, 'kanban', 'product/views/product_supplierinfo_views.xml', 'primary', '{"en_US": "<kanban class=\"o_kanban_mobile\">\n                <field name=\"min_qty\"/>\n                <field name=\"delay\"/>\n                <field name=\"price\"/>\n                <field name=\"partner_id\"/>\n                <field name=\"currency_id\"/>\n                <templates>\n                    <t t-name=\"kanban-box\">\n                        <div class=\"oe_kanban_global_click\">\n                            <div class=\"row mb4\">\n                                <strong class=\"col-6\">\n                                    <span t-esc=\"record.partner_id.value\"/>\n                                </strong>\n                                <strong class=\"col-6 text-end\">\n                                    <strong><field name=\"price\" widget=\"monetary\"/></strong>\n                                </strong>\n                                <div class=\"col-6\">\n                                    <span t-esc=\"record.min_qty.value\"/>\n                                </div>\n                                <div class=\"col-6 text-end\">\n                                    <span t-esc=\"record.delay.value\"/> days\n                                </div>\n                            </div>\n                        </div>\n                    </t>\n                </templates>\n            </kanban>"}', '<?xml version="1.0"?>
<kanban class="o_kanban_mobile">
                <field name="min_qty"/>
                <field name="delay"/>
                <field name="price"/>
                <field name="partner_id"/>
                <field name="currency_id"/>
                <templates>
                    <t t-name="kanban-box">
                        <div class="oe_kanban_global_click">
                            <div class="row mb4">
                                <strong class="col-6">
                                    <span t-esc="record.partner_id.value"/>
                                </strong>
                                <strong class="col-6 text-end">
                                    <strong><field name="price" widget="monetary"/></strong>
                                </strong>
                                <div class="col-6">
                                    <span t-esc="record.min_qty.value"/>
                                </div>
                                <div class="col-6 text-end">
                                    <span t-esc="record.delay.value"/> days
                                </div>
                            </div>
                        </div>
                    </t>
                </templates>
            </kanban>
        ', false, true, '2026-05-10 01:11:49.207732', '2026-05-10 01:11:49.207732', NULL);
INSERT INTO public.ir_ui_view VALUES (495, 16, NULL, 1, 1, 'product.supplierinfo.tree.view', 'product.supplierinfo', NULL, 'tree', 'product/views/product_supplierinfo_views.xml', 'primary', '{"en_US": "<tree string=\"Vendor Information\" multi_edit=\"1\">\n                <field name=\"sequence\" widget=\"handle\"/>\n                <field name=\"partner_id\" readonly=\"1\"/>\n                <field name=\"product_id\" optional=\"hide\" readonly=\"1\" column_invisible=\"context.get(''product_template_invisible_variant'', False)\" groups=\"product.group_product_variant\" domain=\"[(''product_tmpl_id'', ''='', context.get(''default_product_tmpl_id''))] if context.get(''default_product_tmpl_id'') else [(''product_tmpl_id'', ''='', product_tmpl_id)]\"/>\n                <field name=\"product_tmpl_id\" string=\"Product\" readonly=\"1\" column_invisible=\"context.get(''visible_product_tmpl_id'', True)\"/>\n                <field name=\"product_name\" optional=\"hide\"/>\n                <field name=\"product_code\" optional=\"hide\"/>\n                <field name=\"date_start\" optional=\"hide\"/>\n                <field name=\"date_end\" optional=\"hide\"/>\n                <field name=\"company_id\" readonly=\"1\" groups=\"base.group_multi_company\"/>\n                <field name=\"min_qty\" optional=\"hide\"/>\n                <field name=\"product_uom\" groups=\"uom.group_uom\" optional=\"hide\"/>\n                <field name=\"price\" string=\"Price\"/>\n                <field name=\"discount\" optional=\"hide\"/>\n                <field name=\"currency_id\" groups=\"base.group_multi_currency\"/>\n                <field name=\"delay\" optional=\"show\"/>\n            </tree>"}', '<?xml version="1.0"?>
<tree string="Vendor Information" multi_edit="1">
                <field name="sequence" widget="handle"/>
                <field name="partner_id" readonly="1"/>
                <field name="product_id" optional="hide" readonly="1" column_invisible="context.get(''product_template_invisible_variant'', False)" groups="product.group_product_variant" domain="[(''product_tmpl_id'', ''='', context.get(''default_product_tmpl_id''))] if context.get(''default_product_tmpl_id'') else [(''product_tmpl_id'', ''='', product_tmpl_id)]"/>
                <field name="product_tmpl_id" string="Product" readonly="1" column_invisible="context.get(''visible_product_tmpl_id'', True)"/>
                <field name="product_name" optional="hide"/>
                <field name="product_code" optional="hide"/>
                <field name="date_start" optional="hide"/>
                <field name="date_end" optional="hide"/>
                <field name="company_id" readonly="1" groups="base.group_multi_company"/>
                <field name="min_qty" optional="hide"/>
                <field name="product_uom" groups="uom.group_uom" optional="hide"/>
                <field name="price" string="Price"/>
                <field name="discount" optional="hide"/>
                <field name="currency_id" groups="base.group_multi_currency"/>
                <field name="delay" optional="show"/>
            </tree>
        ', false, true, '2026-05-10 01:11:49.207732', '2026-05-10 01:11:49.207732', NULL);
INSERT INTO public.ir_ui_view VALUES (496, 16, NULL, 1, 1, 'product.template.product.tree', 'product.template', NULL, 'tree', 'product/views/product_template_views.xml', 'primary', '{"en_US": "<tree string=\"Product\" multi_edit=\"1\" sample=\"1\">\n            <header>\n                <button string=\"Print Labels\" type=\"object\" name=\"action_open_label_layout\"/>\n            </header>\n                <field name=\"product_variant_count\" column_invisible=\"True\"/>\n                <field name=\"sale_ok\" column_invisible=\"True\"/>\n                <field name=\"currency_id\" column_invisible=\"True\"/>\n                <field name=\"cost_currency_id\" column_invisible=\"True\"/>\n                <field name=\"priority\" widget=\"priority\" optional=\"show\" nolabel=\"1\"/>\n                <field name=\"name\" string=\"Product Name\"/>\n                <field name=\"default_code\" optional=\"show\"/>\n                <field name=\"product_tag_ids\" widget=\"many2many_tags\" optional=\"show\"/>\n                <field name=\"barcode\" optional=\"hide\" readonly=\"product_variant_count != 1\"/>\n                <field name=\"company_id\" options=\"{''no_create'': True}\" groups=\"base.group_multi_company\" optional=\"hide\"/>\n                <field name=\"list_price\" string=\"Sales Price\" widget=\"monetary\" options=\"{''currency_field'': ''currency_id''}\" optional=\"show\" decoration-muted=\"not sale_ok\"/>\n                <field name=\"standard_price\" widget=\"monetary\" options=\"{''currency_field'': ''cost_currency_id''}\" optional=\"show\" readonly=\"1\"/>\n                <field name=\"categ_id\" optional=\"hide\"/>\n                <field name=\"detailed_type\" optional=\"hide\" readonly=\"1\"/>\n                <field name=\"type\" column_invisible=\"True\"/>\n                <field name=\"uom_id\" string=\"Unit\" readonly=\"1\" optional=\"show\" groups=\"uom.group_uom\"/>\n                <field name=\"active\" column_invisible=\"True\"/>\n                <field name=\"activity_exception_decoration\" widget=\"activity_exception\"/>\n            </tree>"}', '<?xml version="1.0"?>
<tree string="Product" multi_edit="1" sample="1">
            <header>
                <button string="Print Labels" type="object" name="action_open_label_layout"/>
            </header>
                <field name="product_variant_count" column_invisible="True"/>
                <field name="sale_ok" column_invisible="True"/>
                <field name="currency_id" column_invisible="True"/>
                <field name="cost_currency_id" column_invisible="True"/>
                <field name="priority" widget="priority" optional="show" nolabel="1"/>
                <field name="name" string="Product Name"/>
                <field name="default_code" optional="show"/>
                <field name="product_tag_ids" widget="many2many_tags" optional="show"/>
                <field name="barcode" optional="hide" readonly="product_variant_count != 1"/>
                <field name="company_id" options="{''no_create'': True}" groups="base.group_multi_company" optional="hide"/>
                <field name="list_price" string="Sales Price" widget="monetary" options="{''currency_field'': ''currency_id''}" optional="show" decoration-muted="not sale_ok"/>
                <field name="standard_price" widget="monetary" options="{''currency_field'': ''cost_currency_id''}" optional="show" readonly="1"/>
                <field name="categ_id" optional="hide"/>
                <field name="detailed_type" optional="hide" readonly="1"/>
                <field name="type" column_invisible="True"/>
                <field name="uom_id" string="Unit" readonly="1" optional="show" groups="uom.group_uom"/>
                <field name="active" column_invisible="True"/>
                <field name="activity_exception_decoration" widget="activity_exception"/>
            </tree>
        ', false, true, '2026-05-10 01:11:49.207732', '2026-05-10 01:11:49.207732', NULL);
INSERT INTO public.ir_ui_view VALUES (497, 8, 453, 1, 1, 'product.template.product.form', 'product.template', NULL, 'form', 'product/views/product_template_views.xml', 'primary', '{"en_US": "<data><xpath expr=\"//form\" position=\"attributes\">\n                <attribute name=\"name\">Product Template</attribute>\n            </xpath>\n            <field name=\"categ_id\" position=\"after\">\n                <field name=\"default_code\" invisible=\"product_variant_count &gt; 1\"/>\n                <field name=\"valid_product_template_attribute_line_ids\" invisible=\"1\"/>\n                <field name=\"barcode\" invisible=\"product_variant_count &gt; 1 or (product_variant_count == 0 and valid_product_template_attribute_line_ids)\"/>\n            </field>\n\n            <div name=\"button_box\" position=\"inside\">\n                <button name=\"169\" type=\"action\" icon=\"fa-sitemap\" class=\"oe_stat_button\" invisible=\"product_variant_count &lt;= 1\" groups=\"product.group_product_variant\">\n                    <field string=\"Variants\" name=\"product_variant_count\" widget=\"statinfo\"/>\n                </button>\n            </div>\n\n            <xpath expr=\"//page[@name=''general_information'']\" position=\"after\">\n                <page name=\"variants\" string=\"Attributes &amp; Variants\" groups=\"product.group_product_variant\">\n                    <field name=\"attribute_line_ids\" widget=\"one2many\" context=\"{''show_attribute'': False}\">\n                        <tree string=\"Variants\" editable=\"bottom\" decoration-info=\"value_count &lt;= 1\">\n                            <field name=\"value_count\" column_invisible=\"True\"/>\n                            <field name=\"sequence\" widget=\"handle\"/>\n                            <field name=\"attribute_id\" readonly=\"id\"/>\n                            <field name=\"value_ids\" widget=\"many2many_tags\" options=\"{''no_create_edit'': True, ''color_field'': ''color''}\" context=\"{''default_attribute_id'': attribute_id, ''show_attribute'': False}\"/>\n                            <button string=\"Configure\" class=\"float-end btn-secondary\" type=\"object\" name=\"action_open_attribute_values\" groups=\"product.group_product_variant\"/>\n                        </tree>\n                    </field>\n                        <p class=\"oe_grey oe_edit_only\">\n                        <strong>Warning</strong>: adding or deleting attributes\n                        will delete and recreate existing variants and lead\n                        to the loss of their possible customizations.\n                    </p>\n                </page>\n            </xpath>\n            <xpath expr=\"//group[@name=''group_standard_price'']\" position=\"after\">\n                <field name=\"product_properties\" columns=\"2\"/>\n            </xpath>\n        </data>"}', '<?xml version="1.0"?>
<data><xpath expr="//form" position="attributes">
                <attribute name="name">Product Template</attribute>
            </xpath>
            <field name="categ_id" position="after">
                <field name="default_code" invisible="product_variant_count &gt; 1"/>
                <field name="valid_product_template_attribute_line_ids" invisible="1"/>
                <field name="barcode" invisible="product_variant_count &gt; 1 or (product_variant_count == 0 and valid_product_template_attribute_line_ids)"/>
            </field>

            <div name="button_box" position="inside">
                <button name="169" type="action" icon="fa-sitemap" class="oe_stat_button" invisible="product_variant_count &lt;= 1" groups="product.group_product_variant">
                    <field string="Variants" name="product_variant_count" widget="statinfo"/>
                </button>
            </div>

            <xpath expr="//page[@name=''general_information'']" position="after">
                <page name="variants" string="Attributes &amp; Variants" groups="product.group_product_variant">
                    <field name="attribute_line_ids" widget="one2many" context="{''show_attribute'': False}">
                        <tree string="Variants" editable="bottom" decoration-info="value_count &lt;= 1">
                            <field name="value_count" column_invisible="True"/>
                            <field name="sequence" widget="handle"/>
                            <field name="attribute_id" readonly="id"/>
                            <field name="value_ids" widget="many2many_tags" options="{''no_create_edit'': True, ''color_field'': ''color''}" context="{''default_attribute_id'': attribute_id, ''show_attribute'': False}"/>
                            <button string="Configure" class="float-end btn-secondary" type="object" name="action_open_attribute_values" groups="product.group_product_variant"/>
                        </tree>
                    </field>
                        <p class="oe_grey oe_edit_only">
                        <strong>Warning</strong>: adding or deleting attributes
                        will delete and recreate existing variants and lead
                        to the loss of their possible customizations.
                    </p>
                </page>
            </xpath>
            <xpath expr="//group[@name=''group_standard_price'']" position="after">
                <field name="product_properties" columns="2"/>
            </xpath>
        </data>', false, true, '2026-05-10 01:11:49.207732', '2026-05-10 01:11:49.207732', NULL);
INSERT INTO public.ir_ui_view VALUES (498, 16, NULL, 1, 1, 'Product.template.product.kanban', 'product.template', NULL, 'kanban', 'product/views/product_template_views.xml', 'primary', '{"en_US": "<kanban sample=\"1\">\n                <field name=\"id\"/>\n                <field name=\"product_variant_count\"/>\n                <field name=\"currency_id\"/>\n                <field name=\"activity_state\"/>\n                <field name=\"categ_id\"/>\n                <progressbar field=\"activity_state\" colors=\"{&quot;planned&quot;: &quot;success&quot;, &quot;today&quot;: &quot;warning&quot;, &quot;overdue&quot;: &quot;danger&quot;}\"/>\n                <templates>\n                    <t t-name=\"kanban-box\">\n                        <div class=\"oe_kanban_card oe_kanban_global_click\">\n                            <div class=\"o_kanban_image me-1\">\n                                <img t-att-src=\"kanban_image(''product.template'', ''image_128'', record.id.raw_value)\" alt=\"Product\" class=\"o_image_64_contain\"/>\n                            </div>\n                            <div class=\"oe_kanban_details\">\n                                <div class=\"o_kanban_record_top mb-0\">\n                                    <div class=\"o_kanban_record_headings\">\n                                        <strong class=\"o_kanban_record_title\">\n                                            <field name=\"name\"/>\n                                        </strong>\n                                    </div>\n                                    <field name=\"priority\" widget=\"priority\"/>\n                                </div>\n                                <t t-if=\"record.default_code.value\">[<field name=\"default_code\"/>]</t>\n                                <div t-if=\"record.product_variant_count.value &gt; 1\" groups=\"product.group_product_variant\">\n                                    <strong>\n                                        <t t-esc=\"record.product_variant_count.value\"/> Variants\n                                    </strong>\n                                </div>\n                                <div name=\"product_lst_price\" class=\"mt-1\">\n                                    Price: <field name=\"list_price\" widget=\"monetary\" options=\"{''currency_field'': ''currency_id'', ''field_digits'': True}\"/>\n                                </div>\n                                <div>\n                                    <field name=\"product_properties\" widget=\"properties\"/>\n                                </div>\n                            </div>\n                        </div>\n                    </t>\n                </templates>\n            </kanban>"}', '<?xml version="1.0"?>
<kanban sample="1">
                <field name="id"/>
                <field name="product_variant_count"/>
                <field name="currency_id"/>
                <field name="activity_state"/>
                <field name="categ_id"/>
                <progressbar field="activity_state" colors="{&quot;planned&quot;: &quot;success&quot;, &quot;today&quot;: &quot;warning&quot;, &quot;overdue&quot;: &quot;danger&quot;}"/>
                <templates>
                    <t t-name="kanban-box">
                        <div class="oe_kanban_card oe_kanban_global_click">
                            <div class="o_kanban_image me-1">
                                <img t-att-src="kanban_image(''product.template'', ''image_128'', record.id.raw_value)" alt="Product" class="o_image_64_contain"/>
                            </div>
                            <div class="oe_kanban_details">
                                <div class="o_kanban_record_top mb-0">
                                    <div class="o_kanban_record_headings">
                                        <strong class="o_kanban_record_title">
                                            <field name="name"/>
                                        </strong>
                                    </div>
                                    <field name="priority" widget="priority"/>
                                </div>
                                <t t-if="record.default_code.value">[<field name="default_code"/>]</t>
                                <div t-if="record.product_variant_count.value &gt; 1" groups="product.group_product_variant">
                                    <strong>
                                        <t t-esc="record.product_variant_count.value"/> Variants
                                    </strong>
                                </div>
                                <div name="product_lst_price" class="mt-1">
                                    Price: <field name="list_price" widget="monetary" options="{''currency_field'': ''currency_id'', ''field_digits'': True}"/>
                                </div>
                                <div>
                                    <field name="product_properties" widget="properties"/>
                                </div>
                            </div>
                        </div>
                    </t>
                </templates>
            </kanban>
        ', false, true, '2026-05-10 01:11:49.207732', '2026-05-10 01:11:49.207732', NULL);
INSERT INTO public.ir_ui_view VALUES (499, 16, NULL, 1, 1, 'product.template.activity', 'product.template', NULL, 'activity', 'product/views/product_template_views.xml', 'primary', '{"en_US": "<activity string=\"Products\">\n                <field name=\"id\"/>\n                <templates>\n                    <div t-name=\"activity-box\">\n                        <img t-att-src=\"activity_image(''product.template'', ''image_128'', record.id.raw_value)\" role=\"img\" t-att-title=\"record.id.value\" t-att-alt=\"record.id.value\"/>\n                        <div class=\"ms-2\">\n                            <field name=\"name\" display=\"full\" class=\"o_text_block\"/>\n                            <div t-if=\"record.default_code.value\" class=\"o_text_block text-muted\">\n                                [<field name=\"default_code\"/>]\n                            </div>\n                        </div>\n                    </div>\n                </templates>\n            </activity>"}', '<?xml version="1.0"?>
<activity string="Products">
                <field name="id"/>
                <templates>
                    <div t-name="activity-box">
                        <img t-att-src="activity_image(''product.template'', ''image_128'', record.id.raw_value)" role="img" t-att-title="record.id.value" t-att-alt="record.id.value"/>
                        <div class="ms-2">
                            <field name="name" display="full" class="o_text_block"/>
                            <div t-if="record.default_code.value" class="o_text_block text-muted">
                                [<field name="default_code"/>]
                            </div>
                        </div>
                    </div>
                </templates>
            </activity>
        ', false, true, '2026-05-10 01:11:49.207732', '2026-05-10 01:11:49.207732', NULL);
