INSERT INTO public.ir_ui_view VALUES (502, 16, NULL, 1, 1, 'report_simple_label2x7', NULL, 'product.report_simple_label2x7', 'qweb', 'product/report/product_product_templates.xml', 'primary', '{"en_US": "<t t-name=\"product.report_simple_label2x7\">\n            <t t-set=\"barcode_size\" t-value=\"''width:33mm;height:14mm''\"/>\n            <t t-set=\"table_style\" t-value=\"''width:97mm;height:37.1mm;'' + table_style\"/>\n            <td t-att-style=\"make_invisible and ''visibility:hidden;''\">\n                <div class=\"o_label_full\" t-att-style=\"table_style\">\n                    <div class=\"o_label_name\">\n                        <strong t-field=\"product.display_name\"/>\n                    </div>\n                    <div class=\"o_label_data\">\n                        <div class=\"text-center o_label_left_column\">\n                            <span class=\"text-nowrap\" t-field=\"product.default_code\"/>\n                            <t t-if=\"barcode\">\n                                <div t-out=\"barcode\" t-options=\"{''widget'': ''barcode'', ''symbology'': ''auto'', ''img_style'': barcode_size}\"/>\n                                <span class=\"text-center\" t-out=\"barcode\"/>\n                            </t>\n                        </div>\n                        <div class=\"text-end\" style=\"line-height:normal\">\n                            <div class=\"o_label_extra_data\">\n                                <t t-out=\"extra_html\"/>\n                            </div>\n                            <strong class=\"o_label_price\" t-out=\"pricelist._get_product_price(product, 1, currency=pricelist.currency_id or product.currency_id)\" t-options=\"{''widget'': ''monetary'', ''display_currency'': pricelist.currency_id or product.currency_id, ''label_price'': True}\"/>\n                        </div>\n                        <div class=\"o_label_clear\"/>\n                    </div>\n                </div>\n            </td>\n        </t>"}', '<?xml version="1.0"?>
<t t-name="product.report_simple_label2x7">
