                            <strong class="o_label_price" t-out="pricelist._get_product_price(product, 1, currency=pricelist.currency_id or product.currency_id)" t-options="{''widget'': ''monetary'', ''display_currency'': pricelist.currency_id or product.currency_id, ''label_price'': True}"/>
                        </div>
                        <div class="o_label_clear"/>
                    </div>
                </div>
            </td>
        </t>

        ', false, true, '2026-05-10 01:11:49.207732', '2026-05-10 01:11:49.207732', NULL);
INSERT INTO public.ir_ui_view VALUES (516, 16, NULL, 1, 1, 'report_pricelist', NULL, 'product.report_pricelist', 'qweb', 'product/report/product_pricelist_report_templates.xml', 'primary', '{"en_US": "<t t-name=\"product.report_pricelist\">\n        <t t-call=\"web.basic_layout\">\n            <div class=\"page\">\n                <t t-call=\"product.report_pricelist_page\"/>\n            </div>\n            <p style=\"page-break-before:always;\"> </p>\n            <div class=\"oe_structure\"/>\n        </t>\n    </t>"}', '<?xml version="1.0"?>
