INSERT INTO public.ir_ui_view VALUES (506, 16, NULL, 1, 1, 'report_simple_label_dymo', NULL, 'product.report_simple_label_dymo', 'qweb', 'product/report/product_product_templates.xml', 'primary', '{"en_US": "<t t-name=\"product.report_simple_label_dymo\">\n            <div class=\"o_label_sheet o_label_dymo\" t-att-style=\"padding_page\">\n                <div class=\"o_label_full\" t-att-style=\"table_style\">\n                    <div class=\"text-start o_label_small_barcode\">\n                        <t t-if=\"barcode\">\n                            <!-- `quiet=0` to remove the left and right margins on the barcode -->\n                            <div t-out=\"barcode\" style=\"padding:0\" t-options=\"{''widget'': ''barcode'', ''quiet'': 0, ''symbology'': ''auto'', ''img_style'': barcode_size}\"/>\n                            <div class=\"o_label_name\" style=\"height:1.7em;background-color: transparent;\">\n                                <span t-out=\"barcode\"/>\n                            </div>\n                        </t>\n                    </div>\n                    <div class=\"o_label_name\" style=\"line-height: 100%;background-color: transparent;padding-top: 1px;\">\n                        <span t-if=\"product.is_product_variant\" t-field=\"product.display_name\"/>\n                        <span t-else=\"\" t-field=\"product.name\"/>\n                    </div>\n                    <div class=\"o_label_left_column\">\n                        <small class=\"text-nowrap\" t-field=\"product.default_code\"/>\n                    </div>\n                    <div class=\"text-end\" style=\"padding: 0 4px;\">\n                        <strong class=\"o_label_price_small\" t-out=\"pricelist._get_product_price(product, 1, currency=pricelist.currency_id or product.currency_id)\" t-options=\"{''widget'': ''monetary'', ''display_currency'': pricelist.currency_id or product.currency_id, ''label_price'': True}\"/>\n                        <div t-if=\"False\" class=\"o_label_extra_data\">\n                            <t t-out=\"extra_html\"/>\n                        </div>\n                    </div>\n                </div>\n            </div>\n        </t>"}', '<?xml version="1.0"?>
<t t-name="product.report_simple_label_dymo">
            <div class="o_label_sheet o_label_dymo" t-att-style="padding_page">
                <div class="o_label_full" t-att-style="table_style">
                    <div class="text-start o_label_small_barcode">
                        <t t-if="barcode">
                            <!-- `quiet=0` to remove the left and right margins on the barcode -->
                            <div t-out="barcode" style="padding:0" t-options="{''widget'': ''barcode'', ''quiet'': 0, ''symbology'': ''auto'', ''img_style'': barcode_size}"/>
                            <div class="o_label_name" style="height:1.7em;background-color: transparent;">
                                <span t-out="barcode"/>
                            </div>
                        </t>
                    </div>
                    <div class="o_label_name" style="line-height: 100%;background-color: transparent;padding-top: 1px;">
                        <span t-if="product.is_product_variant" t-field="product.display_name"/>
                        <span t-else="" t-field="product.name"/>
                    </div>
                    <div class="o_label_left_column">
                        <small class="text-nowrap" t-field="product.default_code"/>
                    </div>
                    <div class="text-end" style="padding: 0 4px;">
                        <strong class="o_label_price_small" t-out="pricelist._get_product_price(product, 1, currency=pricelist.currency_id or product.currency_id)" t-options="{''widget'': ''monetary'', ''display_currency'': pricelist.currency_id or product.currency_id, ''label_price'': True}"/>
                        <div t-if="False" class="o_label_extra_data">
                            <t t-out="extra_html"/>
                        </div>
                    </div>
                </div>
            </div>
        </t>

        ', false, true, '2026-05-10 01:11:49.207732', '2026-05-10 01:11:49.207732', NULL);
INSERT INTO public.ir_ui_view VALUES (507, 16, NULL, 1, 1, 'report_productlabel', NULL, 'product.report_productlabel', 'qweb', 'product/report/product_product_templates.xml', 'primary', '{"en_US": "<t t-name=\"product.report_productlabel\">\n            <t t-call=\"web.html_container\">\n                <t t-if=\"columns and rows\">\n                    <t t-if=\"columns == 2 and rows == 7\">\n                        <t t-set=\"padding_page\" t-value=\"''padding: 14mm 3mm''\"/>\n                        <t t-set=\"report_to_call\" t-value=\"''2x7''\"/>\n                    </t>\n                    <t t-if=\"columns == 4 and rows == 7\">\n                        <t t-set=\"padding_page\" t-value=\"''padding: 14mm 3mm''\"/>\n                        <t t-set=\"report_to_call\" t-value=\"''4x7''\"/>\n                    </t>\n                    <t t-if=\"columns == 4 and rows == 12\">\n                        <t t-set=\"padding_page\" t-value=\"''padding: 20mm 8mm''\"/>\n                        <t t-set=\"report_to_call\" t-value=\"''4x12''\"/>\n                    </t>\n                    <t t-foreach=\"range(page_numbers)\" t-as=\"page\">\n                        <div class=\"o_label_sheet\" t-att-style=\"padding_page\">\n                            <table class=\"my-0 table table-sm table-borderless\">\n                                <t t-foreach=\"range(rows)\" t-as=\"row\">\n                                    <tr>\n                                        <t t-foreach=\"range(columns)\" t-as=\"column\">\n                                            <t t-if=\"not current_quantity and quantity and not (current_data and current_data[1])\">\n                                                <t t-set=\"current_data\" t-value=\"quantity.popitem()\"/>\n                                                <t t-set=\"product\" t-value=\"current_data[0]\"/>\n                                                <t t-set=\"barcode_and_qty\" t-value=\"current_data[1].pop()\"/>\n                                                <t t-set=\"barcode\" t-value=\"barcode_and_qty[0]\"/>\n                                                <t t-set=\"current_quantity\" t-value=\"barcode_and_qty[1]\"/>\n                                            </t>\n                                            <t t-if=\"current_quantity\">\n                                                <t t-set=\"make_invisible\" t-value=\"False\"/>\n                                                <t t-set=\"current_quantity\" t-value=\"current_quantity - 1\"/>\n                                            </t>\n                                            <t t-elif=\"current_data and current_data[1]\">\n                                                <t t-set=\"barcode_and_qty\" t-value=\"current_data[1].pop()\"/>\n                                                <t t-set=\"barcode\" t-value=\"barcode_and_qty[0]\"/>\n                                                <t t-set=\"current_quantity\" t-value=\"barcode_and_qty[1] - 1\"/>\n                                            </t>\n                                            <t t-else=\"\">\n                                                <t t-set=\"make_invisible\" t-value=\"True\"/>\n                                            </t>\n                                            <t t-set=\"table_style\" t-value=\"''border: 1px solid %s;'' % (product.env.user.company_id.primary_color or ''black'')\"/>\n                                            <!-- IMPORTANT: explictly call templates in place of {{template}} otherwise studio won''t load report correctly -->\n                                            <t t-if=\"report_to_call == ''2x7''\">\n                                                <t t-call=\"product.report_simple_label2x7\"/>\n                                            </t>\n                                            <t t-elif=\"report_to_call == ''4x7''\">\n                                                <t t-call=\"product.report_simple_label4x7\"/>\n                                            </t>\n                                            <t t-elif=\"report_to_call == ''4x12''\">\n                                                <t t-if=\"price_included\">\n                                                    <t t-call=\"product.report_simple_label4x12\"/>\n                                                </t>\n                                                <t t-else=\"\">\n                                                    <t t-call=\"product.report_simple_label4x12_no_price\"/>\n                                                </t>\n                                            </t>\n                                        </t>\n                                    </tr>\n                                </t>\n                            </table>\n                        </div>\n                    </t>\n                </t>\n            </t>\n        </t>"}', '<?xml version="1.0"?>
<t t-name="product.report_productlabel">
            <t t-call="web.html_container">
                <t t-if="columns and rows">
                    <t t-if="columns == 2 and rows == 7">
                        <t t-set="padding_page" t-value="''padding: 14mm 3mm''"/>
                        <t t-set="report_to_call" t-value="''2x7''"/>
                    </t>
                    <t t-if="columns == 4 and rows == 7">
                        <t t-set="padding_page" t-value="''padding: 14mm 3mm''"/>
                        <t t-set="report_to_call" t-value="''4x7''"/>
                    </t>
                    <t t-if="columns == 4 and rows == 12">
                        <t t-set="padding_page" t-value="''padding: 20mm 8mm''"/>
                        <t t-set="report_to_call" t-value="''4x12''"/>
                    </t>
                    <t t-foreach="range(page_numbers)" t-as="page">
                        <div class="o_label_sheet" t-att-style="padding_page">
                            <table class="my-0 table table-sm table-borderless">
                                <t t-foreach="range(rows)" t-as="row">
                                    <tr>
                                        <t t-foreach="range(columns)" t-as="column">
                                            <t t-if="not current_quantity and quantity and not (current_data and current_data[1])">
                                                <t t-set="current_data" t-value="quantity.popitem()"/>
                                                <t t-set="product" t-value="current_data[0]"/>
                                                <t t-set="barcode_and_qty" t-value="current_data[1].pop()"/>
                                                <t t-set="barcode" t-value="barcode_and_qty[0]"/>
                                                <t t-set="current_quantity" t-value="barcode_and_qty[1]"/>
                                            </t>
                                            <t t-if="current_quantity">
                                                <t t-set="make_invisible" t-value="False"/>
                                                <t t-set="current_quantity" t-value="current_quantity - 1"/>
                                            </t>
                                            <t t-elif="current_data and current_data[1]">
                                                <t t-set="barcode_and_qty" t-value="current_data[1].pop()"/>
                                                <t t-set="barcode" t-value="barcode_and_qty[0]"/>
                                                <t t-set="current_quantity" t-value="barcode_and_qty[1] - 1"/>
                                            </t>
                                            <t t-else="">
                                                <t t-set="make_invisible" t-value="True"/>
                                            </t>
                                            <t t-set="table_style" t-value="''border: 1px solid %s;'' % (product.env.user.company_id.primary_color or ''black'')"/>
                                            <!-- IMPORTANT: explictly call templates in place of {{template}} otherwise studio won''t load report correctly -->
                                            <t t-if="report_to_call == ''2x7''">
                                                <t t-call="product.report_simple_label2x7"/>
                                            </t>
                                            <t t-elif="report_to_call == ''4x7''">
                                                <t t-call="product.report_simple_label4x7"/>
                                            </t>
                                            <t t-elif="report_to_call == ''4x12''">
                                                <t t-if="price_included">
                                                    <t t-call="product.report_simple_label4x12"/>
                                                </t>
                                                <t t-else="">
                                                    <t t-call="product.report_simple_label4x12_no_price"/>
                                                </t>
                                            </t>
                                        </t>
                                    </tr>
                                </t>
                            </table>
                        </div>
                    </t>
                </t>
            </t>
        </t>

        ', false, true, '2026-05-10 01:11:49.207732', '2026-05-10 01:11:49.207732', NULL);
INSERT INTO public.ir_ui_view VALUES (508, 16, NULL, 1, 1, 'report_productlabel_dymo', NULL, 'product.report_productlabel_dymo', 'qweb', 'product/report/product_product_templates.xml', 'primary', '{"en_US": "<t t-name=\"product.report_productlabel_dymo\">\n            <t t-call=\"web.html_container\">\n                <t t-set=\"barcode_size\" t-value=\"''width:45.5mm;height:7.5mm''\"/>\n                <t t-set=\"table_style\" t-value=\"''width:100%;height:32mm;''\"/>\n                <t t-set=\"padding_page\" t-value=\"''padding: 2mm''\"/>\n                <t t-foreach=\"quantity.items()\" t-as=\"barcode_and_qty_by_product\">\n                    <t t-set=\"product\" t-value=\"barcode_and_qty_by_product[0]\"/>\n                    <t t-foreach=\"barcode_and_qty_by_product[1]\" t-as=\"barcode_and_qty\">\n                        <t t-set=\"barcode\" t-value=\"barcode_and_qty[0]\"/>\n                        <t t-foreach=\"range(barcode_and_qty[1])\" t-as=\"qty\">\n                            <t t-call=\"product.report_simple_label_dymo\"/>\n                        </t>\n                    </t>\n                </t>\n            </t>\n        </t>"}', '<?xml version="1.0"?>
<t t-name="product.report_productlabel_dymo">
            <t t-call="web.html_container">
                <t t-set="barcode_size" t-value="''width:45.5mm;height:7.5mm''"/>
                <t t-set="table_style" t-value="''width:100%;height:32mm;''"/>
                <t t-set="padding_page" t-value="''padding: 2mm''"/>
                <t t-foreach="quantity.items()" t-as="barcode_and_qty_by_product">
                    <t t-set="product" t-value="barcode_and_qty_by_product[0]"/>
                    <t t-foreach="barcode_and_qty_by_product[1]" t-as="barcode_and_qty">
                        <t t-set="barcode" t-value="barcode_and_qty[0]"/>
                        <t t-foreach="range(barcode_and_qty[1])" t-as="qty">
                            <t t-call="product.report_simple_label_dymo"/>
                        </t>
                    </t>
                </t>
            </t>
        </t>
    ', false, true, '2026-05-10 01:11:49.207732', '2026-05-10 01:11:49.207732', NULL);
INSERT INTO public.ir_ui_view VALUES (509, 16, NULL, 1, 1, 'report_producttemplatelabel2x7', NULL, 'product.report_producttemplatelabel2x7', 'qweb', 'product/report/product_template_templates.xml', 'primary', '{"en_US": "<t t-name=\"product.report_producttemplatelabel2x7\">\n    <t t-call=\"web.basic_layout\">\n        <div class=\"page\">\n            <t t-set=\"columns\" t-value=\"2\"/>\n            <t t-set=\"rows\" t-value=\"7\"/>\n            <t t-call=\"product.report_productlabel\"/>\n        </div>\n    </t>\n</t>"}', '<?xml version="1.0"?>
