INSERT INTO public.ir_ui_view VALUES (514, 16, NULL, 1, 1, 'report_packagingbarcode', NULL, 'product.report_packagingbarcode', 'qweb', 'product/report/product_packaging.xml', 'primary', '{"en_US": "<t t-name=\"product.report_packagingbarcode\">\n            <t t-call=\"web.basic_layout\">\n                <div class=\"page\">\n                    <div class=\"oe_structure\"/>\n                    <t t-foreach=\"docs\" t-as=\"packaging\">\n                        <div class=\"col-4\" style=\"padding:0;\">\n                            <div class=\"oe_structure\"/>\n                            <table class=\"table table-condensed\" style=\"border-bottom: 0px solid white !important;width: 3in;\">\n                                <tr>\n                                    <th style=\"text-align: left;\">\n                                        <strong><span t-field=\"packaging.name\">Package Type A</span></strong>\n                                    </th>\n                                </tr>\n                                <tr>\n                                    <td>\n                                        <strong><span t-field=\"packaging.product_id.display_name\">Eco-friendly Wooden Chair</span></strong>\n                                    </td>\n                                </tr>\n                                <tr>\n                                    <td>\n                                        <div class=\"o_row\">\n                                            <strong>Qty: </strong>\n                                            <strong><span t-field=\"packaging.qty\">10</span></strong>\n                                            <strong><span t-field=\"packaging.product_uom_id\" groups=\"uom.group_uom\">Units</span></strong>\n                                        </div>\n                                    </td>\n                                </tr>\n                                  <t t-if=\"packaging.barcode\">\n                                    <tr>\n                                    <td style=\"text-align: center; vertical-align: middle;\" class=\"col-5\">\n                                        <div t-field=\"packaging.barcode\" t-options=\"{''widget'': ''barcode'', ''symbology'': ''auto'', ''width'': 600, ''height'': 150, ''img_style'': ''width:100%;height:20%;''}\"/>\n                                        <span t-field=\"packaging.barcode\">123456789012</span>\n                                    </td>\n                                </tr>\n                              </t>\n                            </table>\n                            <div class=\"oe_structure\"/>\n                        </div>\n                    </t>\n                    <div class=\"oe_structure\"/>\n                </div>\n            </t>\n        </t>"}', '<?xml version="1.0"?>
<t t-name="product.report_packagingbarcode">
            <t t-call="web.basic_layout">
                <div class="page">
                    <div class="oe_structure"/>
                    <t t-foreach="docs" t-as="packaging">
                        <div class="col-4" style="padding:0;">
                            <div class="oe_structure"/>
                            <table class="table table-condensed" style="border-bottom: 0px solid white !important;width: 3in;">
                                <tr>
                                    <th style="text-align: left;">
                                        <strong><span t-field="packaging.name">Package Type A</span></strong>
                                    </th>
                                </tr>
                                <tr>
                                    <td>
                                        <strong><span t-field="packaging.product_id.display_name">Eco-friendly Wooden Chair</span></strong>
                                    </td>
                                </tr>
                                <tr>
                                    <td>
                                        <div class="o_row">
                                            <strong>Qty: </strong>
                                            <strong><span t-field="packaging.qty">10</span></strong>
                                            <strong><span t-field="packaging.product_uom_id" groups="uom.group_uom">Units</span></strong>
                                        </div>
                                    </td>
                                </tr>
                                  <t t-if="packaging.barcode">
                                    <tr>
                                    <td style="text-align: center; vertical-align: middle;" class="col-5">
                                        <div t-field="packaging.barcode" t-options="{''widget'': ''barcode'', ''symbology'': ''auto'', ''width'': 600, ''height'': 150, ''img_style'': ''width:100%;height:20%;''}"/>
                                        <span t-field="packaging.barcode">123456789012</span>
                                    </td>
                                </tr>
                              </t>
                            </table>
                            <div class="oe_structure"/>
                        </div>
                    </t>
                    <div class="oe_structure"/>
                </div>
            </t>
        </t>
    ', false, true, '2026-05-10 01:11:49.207732', '2026-05-10 01:11:49.207732', NULL);
INSERT INTO public.ir_ui_view VALUES (517, 16, NULL, 1, 1, 'sales.team.crm.tag.view.form', 'crm.tag', NULL, 'form', 'sales_team/views/crm_tag_views.xml', 'primary', '{"en_US": "<form string=\"Tags\">\n                <sheet>\n                    <div class=\"oe_title\">\n                        <label for=\"name\"/>\n                        <h1>\n                            <field name=\"name\" placeholder=\"e.g. Services\"/>\n                        </h1>\n                    </div>\n                    <group>\n                        <group>\n                            <field name=\"color\" required=\"True\" widget=\"color_picker\"/>\n                        </group>\n                    </group>\n                </sheet>\n            </form>"}', '<?xml version="1.0"?>
<form string="Tags">
                <sheet>
                    <div class="oe_title">
                        <label for="name"/>
                        <h1>
                            <field name="name" placeholder="e.g. Services"/>
                        </h1>
                    </div>
                    <group>
                        <group>
                            <field name="color" required="True" widget="color_picker"/>
                        </group>
                    </group>
                </sheet>
            </form>
        ', false, true, '2026-05-10 01:11:51.899028', '2026-05-10 01:11:51.899028', NULL);
INSERT INTO public.ir_ui_view VALUES (518, 16, NULL, 1, 1, 'sales.team.crm.tag.view.tree', 'crm.tag', NULL, 'tree', 'sales_team/views/crm_tag_views.xml', 'primary', '{"en_US": "<tree string=\"Tags\" editable=\"bottom\" sample=\"1\">\n                <field name=\"name\"/>\n                <field name=\"color\" widget=\"color_picker\"/>\n            </tree>"}', '<?xml version="1.0"?>
