INSERT INTO public.ir_ui_view VALUES (519, 16, NULL, 1, 1, 'crm.team.view.search', 'crm.team', NULL, 'search', 'sales_team/views/crm_team_views.xml', 'primary', '{"en_US": "<search string=\"Salesteams Search\">\n                <filter string=\"Archived\" name=\"inactive\" domain=\"[(''active'',''='',False)]\"/>\n                <field name=\"name\"/>\n                <field name=\"user_id\"/>\n                <field name=\"member_ids\"/>\n                <group expand=\"0\" string=\"Group By...\">\n                    <filter string=\"Company\" name=\"company\" domain=\"[]\" context=\"{''group_by'': ''company_id''}\" groups=\"base.group_multi_company\"/>\n                    <filter string=\"Team Leader\" name=\"team_leader\" domain=\"[]\" context=\"{''group_by'': ''user_id''}\"/>\n                </group>\n            </search>"}', '<?xml version="1.0"?>
<search string="Salesteams Search">
                <filter string="Archived" name="inactive" domain="[(''active'',''='',False)]"/>
                <field name="name"/>
                <field name="user_id"/>
                <field name="member_ids"/>
                <group expand="0" string="Group By...">
                    <filter string="Company" name="company" domain="[]" context="{''group_by'': ''company_id''}" groups="base.group_multi_company"/>
                    <filter string="Team Leader" name="team_leader" domain="[]" context="{''group_by'': ''user_id''}"/>
                </group>
            </search>
        ', false, true, '2026-05-10 01:11:51.899028', '2026-05-10 01:11:51.899028', NULL);
INSERT INTO public.ir_ui_view VALUES (520, 16, NULL, 1, 1, 'crm.team.form', 'crm.team', NULL, 'form', 'sales_team/views/crm_team_views.xml', 'primary', '{"en_US": "<form string=\"Sales Team\" class=\"o_crm_team_form_view\">\n                <div class=\"alert alert-info text-center\" role=\"alert\" invisible=\"is_membership_multi or not member_warning\">\n                    <field name=\"member_warning\"/>\n                </div>\n                <sheet>\n                    <div class=\"oe_button_box\" name=\"button_box\"/>\n                    <widget name=\"web_ribbon\" title=\"Archived\" bg_color=\"text-bg-danger\" invisible=\"active\"/>\n                    <div class=\"oe_title\">\n                        <label for=\"name\" string=\"Sales Team\"/>\n                        <h1>\n                            <field class=\"text-break\" name=\"name\" placeholder=\"e.g. North America\"/>\n                        </h1>\n                        <div name=\"options_active\" class=\"o_row\"/>\n                    </div>\n                    <group>\n                        <group name=\"left\" string=\"Team Details\">\n                            <field name=\"active\" invisible=\"1\"/>\n                            <field name=\"sequence\" invisible=\"1\"/>\n                            <field name=\"is_membership_multi\" invisible=\"1\"/>\n                            <field name=\"user_id\" widget=\"many2one_avatar_user\" domain=\"[(''share'', ''='', False)]\"/>\n                            <field name=\"company_id\" options=\"{''no_create'': True}\" groups=\"base.group_multi_company\"/>\n                            <field name=\"currency_id\" invisible=\"1\"/>\n                            <field name=\"member_company_ids\" invisible=\"1\"/>\n                        </group>\n                        <group name=\"right\">\n                        </group>\n                    </group>\n                    <notebook>\n                        <page string=\"Members\" name=\"members_users\">\n                            <field name=\"member_ids\" mode=\"kanban\" class=\"w-100\">\n                                <kanban>\n                                    <field name=\"id\"/>\n                                    <field name=\"name\"/>\n                                    <field name=\"email\"/>\n                                    <field name=\"avatar_128\"/>\n                                    <templates>\n                                        <t t-name=\"kanban-box\">\n                                            <div class=\"oe_kanban_card oe_kanban_global_click\">\n                                                <div class=\"o_kanban_card_content d-flex\">\n                                                    <div>\n                                                        <img t-att-src=\"kanban_image(''res.users'', ''avatar_128'', record.id.raw_value)\" class=\"o_kanban_image o_image_64_cover\" alt=\"Avatar\"/>\n                                                    </div>\n                                                    <div class=\"oe_kanban_details d-flex flex-column ms-3\">\n                                                        <strong class=\"o_kanban_record_title oe_partner_heading\"><field name=\"name\"/></strong>\n                                                        <div class=\"d-flex align-items-baseline text-break\">\n                                                            <i class=\"fa fa-envelope me-1\" role=\"img\" aria-label=\"Email\" title=\"Email\"/><field name=\"email\"/>\n                                                        </div>\n                                                    </div>\n                                                </div>\n                                            </div>\n                                        </t>\n                                    </templates>\n                                </kanban>\n                            </field>\n                            <field name=\"crm_team_member_ids\" mode=\"kanban\" class=\"w-100\" invisible=\"is_membership_multi or not is_membership_multi\" context=\"{                                     ''kanban_view_ref'': ''sales_team.crm_team_member_view_kanban_from_team'',                                     ''form_view_ref'': ''sales_team.crm_team_member_view_form_from_team'',                                     ''tree_view_ref'': ''sales_team.crm_team_member_view_tree_from_team'',                                     ''default_crm_team_id'': id,                                 }\"/>\n                        </page>\n                    </notebook>\n                </sheet>\n                <div class=\"oe_chatter\">\n                    <field name=\"message_follower_ids\" help=\"Follow this salesteam to automatically track the events associated to users of this team.\"/>\n                    <field name=\"message_ids\"/>\n                </div>\n            </form>"}', '<?xml version="1.0"?>
<form string="Sales Team" class="o_crm_team_form_view">
                <div class="alert alert-info text-center" role="alert" invisible="is_membership_multi or not member_warning">
                    <field name="member_warning"/>
                </div>
                <sheet>
                    <div class="oe_button_box" name="button_box"/>
                    <widget name="web_ribbon" title="Archived" bg_color="text-bg-danger" invisible="active"/>
                    <div class="oe_title">
                        <label for="name" string="Sales Team"/>
                        <h1>
                            <field class="text-break" name="name" placeholder="e.g. North America"/>
                        </h1>
                        <div name="options_active" class="o_row"/>
                    </div>
                    <group>
                        <group name="left" string="Team Details">
                            <field name="active" invisible="1"/>
                            <field name="sequence" invisible="1"/>
                            <field name="is_membership_multi" invisible="1"/>
                            <field name="user_id" widget="many2one_avatar_user" domain="[(''share'', ''='', False)]"/>
                            <field name="company_id" options="{''no_create'': True}" groups="base.group_multi_company"/>
                            <field name="currency_id" invisible="1"/>
                            <field name="member_company_ids" invisible="1"/>
                        </group>
                        <group name="right">
                        </group>
                    </group>
                    <notebook>
                        <page string="Members" name="members_users">
                            <field name="member_ids" mode="kanban" class="w-100">
                                <kanban>
                                    <field name="id"/>
                                    <field name="name"/>
                                    <field name="email"/>
                                    <field name="avatar_128"/>
                                    <templates>
                                        <t t-name="kanban-box">
                                            <div class="oe_kanban_card oe_kanban_global_click">
                                                <div class="o_kanban_card_content d-flex">
                                                    <div>
                                                        <img t-att-src="kanban_image(''res.users'', ''avatar_128'', record.id.raw_value)" class="o_kanban_image o_image_64_cover" alt="Avatar"/>
                                                    </div>
                                                    <div class="oe_kanban_details d-flex flex-column ms-3">
                                                        <strong class="o_kanban_record_title oe_partner_heading"><field name="name"/></strong>
                                                        <div class="d-flex align-items-baseline text-break">
                                                            <i class="fa fa-envelope me-1" role="img" aria-label="Email" title="Email"/><field name="email"/>
                                                        </div>
                                                    </div>
                                                </div>
                                            </div>
                                        </t>
                                    </templates>
                                </kanban>
                            </field>
                            <field name="crm_team_member_ids" mode="kanban" class="w-100" invisible="is_membership_multi or not is_membership_multi" context="{                                     ''kanban_view_ref'': ''sales_team.crm_team_member_view_kanban_from_team'',                                     ''form_view_ref'': ''sales_team.crm_team_member_view_form_from_team'',                                     ''tree_view_ref'': ''sales_team.crm_team_member_view_tree_from_team'',                                     ''default_crm_team_id'': id,                                 }"/>
                        </page>
                    </notebook>
                </sheet>
                <div class="oe_chatter">
                    <field name="message_follower_ids" help="Follow this salesteam to automatically track the events associated to users of this team."/>
                    <field name="message_ids"/>
                </div>
            </form>
        ', false, true, '2026-05-10 01:11:51.899028', '2026-05-10 01:11:51.899028', NULL);
INSERT INTO public.ir_ui_view VALUES (521, 16, NULL, 1, 1, 'crm.team.tree', 'crm.team', NULL, 'tree', 'sales_team/views/crm_team_views.xml', 'primary', '{"en_US": "<tree string=\"Sales Team\" sample=\"1\" multi_edit=\"1\">\n                <field name=\"sequence\" widget=\"handle\"/>\n                <field name=\"name\" readonly=\"1\"/>\n                <field name=\"active\" column_invisible=\"True\"/>\n                <field name=\"user_id\" domain=\"[(''share'', ''='', False)]\" widget=\"many2one_avatar_user\"/>\n                <field name=\"company_id\" groups=\"base.group_multi_company\"/>\n            </tree>"}', '<?xml version="1.0"?>
<tree string="Sales Team" sample="1" multi_edit="1">
                <field name="sequence" widget="handle"/>
