INSERT INTO public.ir_ui_view VALUES (523, 10, NULL, 1, 1, 'crm.team.view.kanban.dashboard', 'crm.team', NULL, 'kanban', 'sales_team/views/crm_team_views.xml', 'primary', '{"en_US": "<kanban class=\"o_kanban_dashboard o_crm_team_kanban\" create=\"0\" sample=\"1\">\n                <field name=\"name\"/>\n                <field name=\"user_id\"/>\n                <field name=\"member_ids\"/>\n                <field name=\"color\"/>\n                <field name=\"currency_id\"/>\n                <field name=\"is_favorite\"/>\n                <templates>\n                    <t t-name=\"kanban-menu\">\n                        <div class=\"container\">\n                            <div class=\"row\">\n                                <div class=\"col-4 o_kanban_card_manage_section o_kanban_manage_view\">\n                                    <h5 role=\"menuitem\" class=\" o_kanban_card_manage_title\">\n                                        <span>View</span>\n                                    </h5>\n                                </div>\n                                <div class=\"col-4 o_kanban_card_manage_section o_kanban_manage_new\">\n                                    <h5 role=\"menuitem\" class=\"o_kanban_card_manage_title\">\n                                        <span>New</span>\n                                    </h5>\n                                </div>\n                                <div class=\"col-4 o_kanban_card_manage_section o_kanban_manage_reports\">\n                                    <h5 role=\"menuitem\" class=\"o_kanban_card_manage_title\">\n                                        <span>Reporting</span>\n                                    </h5>\n                                    <div name=\"o_team_kanban_report_separator\"/>\n                                </div>\n                            </div>\n\n                            <div t-if=\"widget.editable\" class=\"o_kanban_card_manage_settings row\" groups=\"sales_team.group_sale_manager\">\n                                <div role=\"menuitem\" aria-haspopup=\"true\" class=\"col-8\">\n                                    <ul class=\"oe_kanban_colorpicker\" data-field=\"color\" role=\"menu\"/>\n                                </div>\n                                <div role=\"menuitem\" class=\"col-4\">\n                                    <a class=\"dropdown-item\" type=\"edit\">Configuration</a>\n                                </div>\n                            </div>\n                        </div>\n                    </t>\n                    <t t-name=\"kanban-box\">\n                        <div t-attf-class=\"#{!selection_mode ? kanban_color(record.color.raw_value) : ''''}\">\n                            <div t-attf-class=\"o_kanban_card_header\">\n                                <div class=\"o_kanban_card_header_title\">\n                                    <div class=\"o_primary o_text_overflow\"><field name=\"name\"/></div>\n                                </div>\n                            </div>\n                            <div class=\"container o_kanban_card_content\">\n                                <div class=\"row o_kanban_card_upper_content\">\n                                    <div class=\"col-4 o_kanban_primary_left\" name=\"to_replace_in_sale_crm\">\n                                        <button type=\"object\" class=\"btn btn-primary\" name=\"action_primary_channel_button\"><field name=\"dashboard_button_name\"/></button>\n                                    </div>\n                                    <div class=\"col-8 o_kanban_primary_right\" style=\"padding-bottom:0;\">\n                                        <t name=\"first_options\"/>\n                                        <t name=\"second_options\"/>\n                                        <t name=\"third_options\"/>\n                                    </div>\n                                </div>\n                                <div class=\"row\">\n                                    <div class=\"col-12 o_kanban_primary_bottom\">\n                                        <t t-call=\"SalesTeamDashboardGraph\"/>\n                                    </div>\n                                </div>\n                            </div>\n                        </div>\n                    </t>\n                    <t t-name=\"SalesTeamDashboardGraph\">\n                        <div t-if=\"record.dashboard_graph_data.raw_value\" class=\"o_sales_team_kanban_graph_section\">\n                            <field name=\"dashboard_graph_data\" widget=\"dashboard_graph\" t-att-graph_type=\"''bar''\"/>\n                        </div>\n                    </t>\n                </templates>\n            </kanban>"}', '<?xml version="1.0"?>
<kanban class="o_kanban_dashboard o_crm_team_kanban" create="0" sample="1">
                <field name="name"/>
                <field name="user_id"/>
                <field name="member_ids"/>
                <field name="color"/>
                <field name="currency_id"/>
                <field name="is_favorite"/>
                <templates>
                    <t t-name="kanban-menu">
                        <div class="container">
                            <div class="row">
                                <div class="col-4 o_kanban_card_manage_section o_kanban_manage_view">
                                    <h5 role="menuitem" class=" o_kanban_card_manage_title">
                                        <span>View</span>
                                    </h5>
                                </div>
                                <div class="col-4 o_kanban_card_manage_section o_kanban_manage_new">
                                    <h5 role="menuitem" class="o_kanban_card_manage_title">
                                        <span>New</span>
                                    </h5>
                                </div>
                                <div class="col-4 o_kanban_card_manage_section o_kanban_manage_reports">
                                    <h5 role="menuitem" class="o_kanban_card_manage_title">
                                        <span>Reporting</span>
                                    </h5>
                                    <div name="o_team_kanban_report_separator"/>
                                </div>
                            </div>

                            <div t-if="widget.editable" class="o_kanban_card_manage_settings row" groups="sales_team.group_sale_manager">
                                <div role="menuitem" aria-haspopup="true" class="col-8">
                                    <ul class="oe_kanban_colorpicker" data-field="color" role="menu"/>
                                </div>
                                <div role="menuitem" class="col-4">
                                    <a class="dropdown-item" type="edit">Configuration</a>
                                </div>
                            </div>
                        </div>
                    </t>
                    <t t-name="kanban-box">
                        <div t-attf-class="#{!selection_mode ? kanban_color(record.color.raw_value) : ''''}">
                            <div t-attf-class="o_kanban_card_header">
                                <div class="o_kanban_card_header_title">
                                    <div class="o_primary o_text_overflow"><field name="name"/></div>
                                </div>
                            </div>
                            <div class="container o_kanban_card_content">
                                <div class="row o_kanban_card_upper_content">
                                    <div class="col-4 o_kanban_primary_left" name="to_replace_in_sale_crm">
                                        <button type="object" class="btn btn-primary" name="action_primary_channel_button"><field name="dashboard_button_name"/></button>
                                    </div>
                                    <div class="col-8 o_kanban_primary_right" style="padding-bottom:0;">
                                        <t name="first_options"/>
                                        <t name="second_options"/>
                                        <t name="third_options"/>
                                    </div>
                                </div>
                                <div class="row">
                                    <div class="col-12 o_kanban_primary_bottom">
                                        <t t-call="SalesTeamDashboardGraph"/>
                                    </div>
                                </div>
                            </div>
                        </div>
                    </t>
                    <t t-name="SalesTeamDashboardGraph">
                        <div t-if="record.dashboard_graph_data.raw_value" class="o_sales_team_kanban_graph_section">
                            <field name="dashboard_graph_data" widget="dashboard_graph" t-att-graph_type="''bar''"/>
                        </div>
                    </t>
                </templates>
            </kanban>
        ', false, true, '2026-05-10 01:11:51.899028', '2026-05-10 01:11:51.899028', NULL);
