INSERT INTO public.ir_ui_view VALUES (527, 16, NULL, 1, 1, 'crm.team.member.view.kanban', 'crm.team.member', NULL, 'kanban', 'sales_team/views/crm_team_member_views.xml', 'primary', '{"en_US": "<kanban quick_create=\"false\" group_create=\"0\" records_draggable=\"0\" sample=\"1\" default_group_by=\"crm_team_id\" class=\"o_crm_team_member_kanban\">\n                <field name=\"user_id\"/>\n                <field name=\"active\"/>\n                <templates>\n                    <t t-name=\"kanban-box\">\n                        <div class=\"oe_kanban_card oe_kanban_global_click\">\n                            <div class=\"ribbon ribbon-top-right\" invisible=\"active\">\n                                <span class=\"text-bg-danger\">Archived</span>\n                            </div>\n                            <div class=\"o_kanban_card_content d-flex\">\n                                <div>\n                                    <img t-att-src=\"kanban_image(''res.users'', ''avatar_128'', record.user_id.raw_value)\" class=\"o_kanban_image o_image_64_cover\" alt=\"Avatar\"/>\n                                </div>\n                                <div class=\"oe_kanban_details d-flex flex-column ms-3\">\n                                    <strong class=\"o_kanban_record_title oe_partner_heading\"><field name=\"user_id\"/></strong>\n                                    <a type=\"open\" class=\"nav-link p-0\"><field name=\"crm_team_id\"/></a>\n                                    <div class=\"d-flex align-items-baseline text-break\">\n                                        <i class=\"fa fa-envelope me-1\" role=\"img\" aria-label=\"Email\" title=\"Email\"/><field name=\"email\"/>\n                                    </div>\n                                </div>\n                            </div>\n                        </div>\n                    </t>\n                </templates>\n            </kanban>"}', '<?xml version="1.0"?>
<kanban quick_create="false" group_create="0" records_draggable="0" sample="1" default_group_by="crm_team_id" class="o_crm_team_member_kanban">
                <field name="user_id"/>
                <field name="active"/>
                <templates>
                    <t t-name="kanban-box">
                        <div class="oe_kanban_card oe_kanban_global_click">
                            <div class="ribbon ribbon-top-right" invisible="active">
                                <span class="text-bg-danger">Archived</span>
                            </div>
                            <div class="o_kanban_card_content d-flex">
                                <div>
                                    <img t-att-src="kanban_image(''res.users'', ''avatar_128'', record.user_id.raw_value)" class="o_kanban_image o_image_64_cover" alt="Avatar"/>
                                </div>
                                <div class="oe_kanban_details d-flex flex-column ms-3">
                                    <strong class="o_kanban_record_title oe_partner_heading"><field name="user_id"/></strong>
