INSERT INTO public.ir_ui_view VALUES (529, 16, NULL, 1, 1, 'crm.team.member.view.form', 'crm.team.member', NULL, 'form', 'sales_team/views/crm_team_member_views.xml', 'primary', '{"en_US": "<form string=\"Sales Men\">\n                <field name=\"active\" invisible=\"1\"/>\n                <field name=\"company_id\" invisible=\"1\"/>\n                <field name=\"is_membership_multi\" invisible=\"1\"/>\n                <field name=\"member_warning\" invisible=\"1\"/>\n                <field name=\"user_in_teams_ids\" invisible=\"1\"/>\n                <field name=\"user_company_ids\" invisible=\"1\"/>\n                <sheet>\n                    <div class=\"alert alert-info text-center\" role=\"alert\" invisible=\"not member_warning\">\n                        <field name=\"member_warning\"/>\n                    </div>\n                    <widget name=\"web_ribbon\" title=\"Archived\" bg_color=\"text-bg-danger\" invisible=\"active\"/>\n                    <field name=\"image_1920\" widget=\"image\" class=\"oe_avatar\" invisible=\"not user_id\" options=\"{&quot;preview_image&quot;: &quot;image_128&quot;}\"/>\n                    <div class=\"oe_title\">\n                        <label for=\"user_id\" class=\"oe_edit_only\"/>\n                        <h1 class=\"d-flex\">\n                            <field name=\"user_id\" class=\"flex-grow-1\" options=\"{''no_quick_create'': True}\"/>\n                        </h1>\n                    </div>\n                    <group name=\"member_partner_info\">\n                        <group name=\"group_owner\">\n                            <field name=\"crm_team_id\" context=\"{''kanban_view_ref'': ''sales_team.crm_team_view_kanban''}\"/>\n                        </group>\n                        <group class=\"ps-0\" name=\"group_user\">\n                            <field name=\"company_id\" invisible=\"not user_id\" groups=\"base.group_multi_company\"/>\n                            <field name=\"email\" invisible=\"not user_id\"/>\n                            <field name=\"mobile\" invisible=\"not user_id\"/>\n                            <field name=\"phone\" invisible=\"not user_id\"/>\n                        </group>\n                    </group>\n                </sheet>\n                <div class=\"oe_chatter\">\n                    <field name=\"message_follower_ids\"/>\n                    <field name=\"message_ids\"/>\n                </div>\n            </form>"}', '<?xml version="1.0"?>
<form string="Sales Men">
                <field name="active" invisible="1"/>
                <field name="company_id" invisible="1"/>
                <field name="is_membership_multi" invisible="1"/>
                <field name="member_warning" invisible="1"/>
                <field name="user_in_teams_ids" invisible="1"/>
                <field name="user_company_ids" invisible="1"/>
                <sheet>
                    <div class="alert alert-info text-center" role="alert" invisible="not member_warning">
                        <field name="member_warning"/>
                    </div>
                    <widget name="web_ribbon" title="Archived" bg_color="text-bg-danger" invisible="active"/>
                    <field name="image_1920" widget="image" class="oe_avatar" invisible="not user_id" options="{&quot;preview_image&quot;: &quot;image_128&quot;}"/>
                    <div class="oe_title">
                        <label for="user_id" class="oe_edit_only"/>
                        <h1 class="d-flex">
                            <field name="user_id" class="flex-grow-1" options="{''no_quick_create'': True}"/>
                        </h1>
                    </div>
                    <group name="member_partner_info">
                        <group name="group_owner">
                            <field name="crm_team_id" context="{''kanban_view_ref'': ''sales_team.crm_team_view_kanban''}"/>
                        </group>
                        <group class="ps-0" name="group_user">
                            <field name="company_id" invisible="not user_id" groups="base.group_multi_company"/>
                            <field name="email" invisible="not user_id"/>
                            <field name="mobile" invisible="not user_id"/>
                            <field name="phone" invisible="not user_id"/>
                        </group>
                    </group>
                </sheet>
                <div class="oe_chatter">
                    <field name="message_follower_ids"/>
                    <field name="message_ids"/>
                </div>
            </form>
        ', false, true, '2026-05-10 01:11:51.899028', '2026-05-10 01:11:51.899028', NULL);
