        ', false, true, '2026-05-10 01:11:52.397405', '2026-05-10 01:11:52.397405', NULL);
INSERT INTO public.ir_ui_view VALUES (536, 16, NULL, 1, 1, 'portal_share_template', NULL, 'portal.portal_share_template', 'qweb', 'portal/data/mail_templates.xml', 'primary', '{"en_US": "<t t-name=\"portal.portal_share_template\">\n        <div>\n            <br/>\n            <p>Dear <span t-esc=\"partner.name\"/>,</p>\n            <p><span t-out=\"user.name\"/> has invited you to access the following <span t-out=\"model_description\"/>:</p>\n            <br/>\n            <a t-attf-href=\"#{share_link}\" style=\"background-color: #875A7B; padding: 10px; text-decoration: none; color: #fff; border-radius: 5px; font-size: 12px;\"><strong>Open </strong><strong t-esc=\"record.display_name\"/></a><br/>\n            <br/>\n            <p t-if=\"note\" style=\"white-space: pre-wrap;\" t-esc=\"note\"/>\n        </div>\n    </t>"}', '<?xml version="1.0"?>
<t t-name="portal.portal_share_template">
        <div>
            <br/>
            <p>Dear <span t-esc="partner.name"/>,</p>
            <p><span t-out="user.name"/> has invited you to access the following <span t-out="model_description"/>:</p>
            <br/>
            <a t-attf-href="#{share_link}" style="background-color: #875A7B; padding: 10px; text-decoration: none; color: #fff; border-radius: 5px; font-size: 12px;"><strong>Open </strong><strong t-esc="record.display_name"/></a><br/>
            <br/>
            <p t-if="note" style="white-space: pre-wrap;" t-esc="note"/>
        </div>
    </t>

', false, true, '2026-05-10 01:11:52.573269', '2026-05-10 01:11:52.573269', false);
INSERT INTO public.ir_ui_view VALUES (537, 16, 380, 1, 1, 'message_document_unfollowed', NULL, 'portal.message_document_unfollowed', 'qweb', 'portal/views/mail_templates_public.xml', 'extension', '{"en_US": "<data inherit_id=\"mail.message_document_unfollowed\">\n        <xpath expr=\"//t[@t-call=''mail.public_layout'']\" position=\"attributes\">\n            <attribute name=\"t-call\">portal.portal_layout</attribute>\n        </xpath>\n    </data>"}', '<?xml version="1.0"?>
<data inherit_id="mail.message_document_unfollowed">
        <xpath expr="//t[@t-call=''mail.public_layout'']" position="attributes">
            <attribute name="t-call">portal.portal_layout</attribute>
        </xpath>
    </data>
', false, true, '2026-05-10 01:11:52.573269', '2026-05-10 01:11:52.573269', false);
INSERT INTO public.ir_ui_view VALUES (538, 16, 181, 1, 1, 'Main Frontend Layout', NULL, 'portal.frontend_layout', 'qweb', 'portal/views/portal_templates.xml', 'extension', '{"en_US": "<data name=\"Main Frontend Layout\" inherit_id=\"web.frontend_layout\">\n        <xpath expr=\"//html\" position=\"attributes\">\n            <attribute name=\"t-att-dir\" add=\"request.env[''res.lang'']._lang_get_direction(request.env.lang)\" separator=\" \"/>\n        </xpath>\n        <xpath expr=\"//div[@id=''wrapwrap'']\" position=\"attributes\">\n            <attribute name=\"t-attf-class\" add=\"#{request.env[''res.lang'']._lang_get_direction(request.env.lang) == ''rtl'' and ''o_rtl'' or ''''}\" separator=\" \"/>\n            <attribute name=\"t-attf-class\" add=\"#{''o_portal'' if is_portal else ''''}\" separator=\" \"/>\n        </xpath>\n        <xpath expr=\"//div[@id=''wrapwrap'']/header/img\" position=\"replace\">\n            <t t-cache=\"res_company\">\n                <nav class=\"navbar navbar-expand navbar-light bg-light\">\n                    <div class=\"container\">\n                        <a href=\"/\" class=\"navbar-brand logo\">\n                            <img t-att-src=\"''/logo.png?company=%s'' % res_company.id\" t-att-alt=\"''Logo of %s'' % res_company.name\" t-att-title=\"res_company.name\"/>\n                        </a>\n                        <ul id=\"top_menu\" class=\"nav navbar-nav ms-auto\">\n                            <t t-call=\"portal.placeholder_user_sign_in\">\n                                <t t-set=\"_item_class\" t-value=\"''nav-item''\"/>\n                                <t t-set=\"_link_class\" t-value=\"''nav-link''\"/>\n                            </t>\n                            <t t-call=\"portal.user_dropdown\">\n                                <t t-set=\"_user_name\" t-value=\"true\"/>\n                                <t t-set=\"_item_class\" t-value=\"''nav-item dropdown''\"/>\n                                <t t-set=\"_link_class\" t-value=\"''nav-link''\"/>\n                                <t t-set=\"_dropdown_menu_class\" t-value=\"''dropdown-menu-end''\"/>\n                            </t>\n                        </ul>\n                    </div>\n                </nav>\n            </t>\n        </xpath>\n        <xpath expr=\"//div[@id=''wrapwrap'']/main/t[@t-out=''0'']\" position=\"before\">\n            <div t-if=\"o_portal_fullwidth_alert\" class=\"container mt-3\">\n                <div class=\"alert alert-info alert-dismissible fade show d-print-none css_editable_mode_hidden\">\n                    <t t-out=\"o_portal_fullwidth_alert\"/>\n                </div>\n            </div>\n        </xpath>\n        <xpath expr=\"//head/meta\" position=\"after\">\n            <t t-if=\"preview_object\">\n                <!-- Remove seo_object to not define og and twitter tags twice when wesbite is installed -->\n                <t t-set=\"seo_object\" t-value=\"False\"/>\n                <t t-set=\"company\" t-value=\"preview_object.company_id or request.env.company\"/>\n                <t t-set=\"not_uses_default_logo\" t-value=\"company and not company.uses_default_logo\"/>\n                <meta property=\"og:title\" t-att-content=\"preview_object.name\"/>\n                <meta property=\"og:description\" t-att-content=\"preview_object.description.striptags() if preview_object.description else ''''\"/>\n                <meta property=\"og:site_name\" t-att-content=\"company.name if company else ''''\"/>\n                <t t-if=\"not_uses_default_logo\">\n                    <meta property=\"og:image\" t-attf-content=\"/web/binary/company_logo?company={{ company.id }}\"/>\n                </t>\n                <meta property=\"og:image:width\" content=\"300\"/>\n                <meta property=\"og:image:height\" content=\"200\"/>\n                <meta name=\"twitter:card\" content=\"summary_large_image\"/>\n                <meta property=\"twitter:title\" t-att-content=\"preview_object.name\"/>\n                <meta property=\"twitter:description\" t-att-content=\"preview_object.description.striptags() if preview_object.description else ''''\"/>\n                <t t-if=\"not_uses_default_logo\">\n                    <meta property=\"twitter:image\" t-attf-content=\"/web/binary/company_logo?company={{ company.id }}\"/>\n                </t>\n            </t>\n        </xpath>\n    </data>"}', '<?xml version="1.0"?>
<data name="Main Frontend Layout" inherit_id="web.frontend_layout">
        <xpath expr="//html" position="attributes">
            <attribute name="t-att-dir" add="request.env[''res.lang'']._lang_get_direction(request.env.lang)" separator=" "/>
        </xpath>
        <xpath expr="//div[@id=''wrapwrap'']" position="attributes">
            <attribute name="t-attf-class" add="#{request.env[''res.lang'']._lang_get_direction(request.env.lang) == ''rtl'' and ''o_rtl'' or ''''}" separator=" "/>
            <attribute name="t-attf-class" add="#{''o_portal'' if is_portal else ''''}" separator=" "/>
        </xpath>
        <xpath expr="//div[@id=''wrapwrap'']/header/img" position="replace">
            <t t-cache="res_company">
                <nav class="navbar navbar-expand navbar-light bg-light">
                    <div class="container">
                        <a href="/" class="navbar-brand logo">
                            <img t-att-src="''/logo.png?company=%s'' % res_company.id" t-att-alt="''Logo of %s'' % res_company.name" t-att-title="res_company.name"/>
                        </a>
                        <ul id="top_menu" class="nav navbar-nav ms-auto">
                            <t t-call="portal.placeholder_user_sign_in">
                                <t t-set="_item_class" t-value="''nav-item''"/>
                                <t t-set="_link_class" t-value="''nav-link''"/>
                            </t>
                            <t t-call="portal.user_dropdown">
                                <t t-set="_user_name" t-value="true"/>
                                <t t-set="_item_class" t-value="''nav-item dropdown''"/>
                                <t t-set="_link_class" t-value="''nav-link''"/>
                                <t t-set="_dropdown_menu_class" t-value="''dropdown-menu-end''"/>
                            </t>
                        </ul>
                    </div>
                </nav>
            </t>
        </xpath>
        <xpath expr="//div[@id=''wrapwrap'']/main/t[@t-out=''0'']" position="before">
            <div t-if="o_portal_fullwidth_alert" class="container mt-3">
                <div class="alert alert-info alert-dismissible fade show d-print-none css_editable_mode_hidden">
                    <t t-out="o_portal_fullwidth_alert"/>
                </div>
            </div>
        </xpath>
        <xpath expr="//head/meta" position="after">
            <t t-if="preview_object">
                <!-- Remove seo_object to not define og and twitter tags twice when wesbite is installed -->
                <t t-set="seo_object" t-value="False"/>
                <t t-set="company" t-value="preview_object.company_id or request.env.company"/>
                <t t-set="not_uses_default_logo" t-value="company and not company.uses_default_logo"/>
                <meta property="og:title" t-att-content="preview_object.name"/>
                <meta property="og:description" t-att-content="preview_object.description.striptags() if preview_object.description else ''''"/>
                <meta property="og:site_name" t-att-content="company.name if company else ''''"/>
                <t t-if="not_uses_default_logo">
                    <meta property="og:image" t-attf-content="/web/binary/company_logo?company={{ company.id }}"/>
                </t>
                <meta property="og:image:width" content="300"/>
                <meta property="og:image:height" content="200"/>
                <meta name="twitter:card" content="summary_large_image"/>
                <meta property="twitter:title" t-att-content="preview_object.name"/>
                <meta property="twitter:description" t-att-content="preview_object.description.striptags() if preview_object.description else ''''"/>
                <t t-if="not_uses_default_logo">
                    <meta property="twitter:image" t-attf-content="/web/binary/company_logo?company={{ company.id }}"/>
                </t>
            </t>
        </xpath>
    </data>

    ', false, true, '2026-05-10 01:11:52.573269', '2026-05-10 01:11:52.573269', false);
INSERT INTO public.ir_ui_view VALUES (540, 16, NULL, 1, 1, 'Language Selector', NULL, 'portal.language_selector', 'qweb', 'portal/views/portal_templates.xml', 'primary', '{"en_US": "<t name=\"Language Selector\" t-name=\"portal.language_selector\">\n        <t t-nocache=\"The query strings can change for the same page and the same rendering.\" t-nocache-no_text=\"no_text\" t-nocache-codes=\"codes\" t-nocache-_div_classes=\"_div_classes\" t-nocache-_btn_class=\"_btn_class\" t-nocache-_txt_class=\"_txt_class\" t-nocache-_dropdown_menu_class=\"_dropdown_menu_class\">\n            <t t-set=\"active_lang\" t-value=\"list(filter(lambda lg : lg[0] == lang, languages))[0]\"/>\n            <t t-set=\"language_selector_visible\" t-value=\"len(languages) &gt; 1\"/>\n            <div t-attf-class=\"js_language_selector #{_div_classes} d-print-none\" t-if=\"language_selector_visible\">\n                <button t-attf-class=\"btn border-0 dropdown-toggle #{_btn_class or ''btn-sm btn-outline-secondary''}\" type=\"button\" data-bs-toggle=\"dropdown\" aria-haspopup=\"true\" aria-expanded=\"true\">\n                    <span t-if=\"not no_text\" t-attf-class=\"align-middle #{_txt_class}\" t-esc=\"active_lang[2].split(''/'').pop()\"/>\n                    <span t-elif=\"codes\" class=\"align-middle\" t-esc=\"active_lang[1].split(''_'').pop(0).upper()\"/>\n                </button>\n                <div t-attf-class=\"dropdown-menu #{_dropdown_menu_class}\" role=\"menu\">\n                    <t t-foreach=\"languages\" t-as=\"lg\">\n                        <a class=\"dropdown-item\" t-att-href=\"url_for(request.httprequest.path + ''?'' + keep_query(), lang_code=lg[0])\" t-attf-class=\"dropdown-item js_change_lang #{active_lang == lg and ''active''}\" t-att-data-url_code=\"lg[1]\" t-att-title=\"lg[2].split(''/'').pop()\" role=\"menuitem\">\n                            <span t-if=\"not no_text\" t-esc=\"lg[2].split(''/'').pop()\" t-attf-class=\"#{_txt_class}\"/>\n                            <span t-elif=\"codes\" t-esc=\"lg[1].split(''_'').pop(0).upper()\" t-attf-class=\"align-middle #{_txt_class}\"/>\n                        </a>\n                    </t>\n                </div>\n            </div>\n        </t>\n    </t>"}', '<?xml version="1.0"?>
<t name="Language Selector" t-name="portal.language_selector">
        <t t-nocache="The query strings can change for the same page and the same rendering." t-nocache-no_text="no_text" t-nocache-codes="codes" t-nocache-_div_classes="_div_classes" t-nocache-_btn_class="_btn_class" t-nocache-_txt_class="_txt_class" t-nocache-_dropdown_menu_class="_dropdown_menu_class">
            <t t-set="active_lang" t-value="list(filter(lambda lg : lg[0] == lang, languages))[0]"/>
            <t t-set="language_selector_visible" t-value="len(languages) &gt; 1"/>
            <div t-attf-class="js_language_selector #{_div_classes} d-print-none" t-if="language_selector_visible">
                <button t-attf-class="btn border-0 dropdown-toggle #{_btn_class or ''btn-sm btn-outline-secondary''}" type="button" data-bs-toggle="dropdown" aria-haspopup="true" aria-expanded="true">
                    <span t-if="not no_text" t-attf-class="align-middle #{_txt_class}" t-esc="active_lang[2].split(''/'').pop()"/>
                    <span t-elif="codes" class="align-middle" t-esc="active_lang[1].split(''_'').pop(0).upper()"/>
                </button>
                <div t-attf-class="dropdown-menu #{_dropdown_menu_class}" role="menu">
                    <t t-foreach="languages" t-as="lg">
                        <a class="dropdown-item" t-att-href="url_for(request.httprequest.path + ''?'' + keep_query(), lang_code=lg[0])" t-attf-class="dropdown-item js_change_lang #{active_lang == lg and ''active''}" t-att-data-url_code="lg[1]" t-att-title="lg[2].split(''/'').pop()" role="menuitem">
                            <span t-if="not no_text" t-esc="lg[2].split(''/'').pop()" t-attf-class="#{_txt_class}"/>
                            <span t-elif="codes" t-esc="lg[1].split(''_'').pop(0).upper()" t-attf-class="align-middle #{_txt_class}"/>
                        </a>
                    </t>
                </div>
            </div>
        </t>
    </t>

    ', false, true, '2026-05-10 01:11:52.573269', '2026-05-10 01:11:52.573269', false);
INSERT INTO public.ir_ui_view VALUES (541, 16, NULL, 1, 1, 'Portal User Dropdown', NULL, 'portal.user_dropdown', 'qweb', 'portal/views/portal_templates.xml', 'primary', '{"en_US": "<t name=\"Portal User Dropdown\" t-name=\"portal.user_dropdown\">\n        <t t-nocache=\"Each user is different regardless of the page visited.\" t-nocache-_avatar=\"_avatar\" t-nocache-_icon=\"_icon\" t-nocache-_icon_class=\"_icon_class\" t-nocache-_icon_wrap_class=\"_icon_wrap_class\" t-nocache-_no_caret=\"_no_caret\" t-nocache-_user_name=\"_user_name\" t-nocache-_user_name_class=\"_user_name_class\" t-nocache-_item_class=\"_item_class\" t-nocache-_link_class=\"_link_class\" t-nocache-_dropdown_menu_class=\"_dropdown_menu_class\">\n            <t t-set=\"is_connected\" t-value=\"not user_id._is_public()\"/>\n            <li t-if=\"is_connected\" t-attf-class=\"#{_item_class} o_no_autohide_item\">\n                <a href=\"#\" role=\"button\" data-bs-toggle=\"dropdown\" t-attf-class=\"#{'''' if _no_caret else ''dropdown-toggle''} btn #{_link_class}\">\n                    <t t-if=\"_avatar\">\n                        <t t-set=\"avatar_source\" t-value=\"image_data_uri(user_id.avatar_256)\"/>\n                        <img t-att-src=\"avatar_source\" t-attf-class=\"rounded-circle o_object_fit_cover #{_avatar_class}\" width=\"24\" height=\"24\" alt=\"\" loading=\"eager\"/>\n                    </t>\n                    <div t-if=\"_icon\" t-attf-class=\"#{_icon_wrap_class}\">\n                        <i t-attf-class=\"fa fa-1x fa-fw fa-user #{_icon_class}\"/>\n                    </div>\n                    <span t-if=\"_user_name\" t-attf-class=\"#{_user_name_class}\" t-esc=\"user_id.name[:23] + ''...'' if user_id.name and len(user_id.name) &gt; 25 else user_id.name\"/>\n                </a>\n                <div t-attf-class=\"dropdown-menu js_usermenu #{_dropdown_menu_class}\" role=\"menu\">\n                    <a groups=\"base.group_user\" href=\"/web\" role=\"menuitem\" class=\"dropdown-item ps-3\" id=\"o_backend_user_dropdown_link\">\n                        <i class=\"fa fa-fw fa-th me-1 small text-primary\"/> Apps\n                    </a>\n                    <div id=\"o_logout_divider\" class=\"dropdown-divider\"/>\n                    <a t-attf-href=\"/web/session/logout?redirect=/\" role=\"menuitem\" id=\"o_logout\" class=\"dropdown-item ps-3\">\n                        <i class=\"fa fa-fw fa-sign-out me-1 small text-primary\"/> Logout\n                    </a>\n                </div>\n            </li>\n        </t>\n    </t>"}', '<?xml version="1.0"?>
<t name="Portal User Dropdown" t-name="portal.user_dropdown">
        <t t-nocache="Each user is different regardless of the page visited." t-nocache-_avatar="_avatar" t-nocache-_icon="_icon" t-nocache-_icon_class="_icon_class" t-nocache-_icon_wrap_class="_icon_wrap_class" t-nocache-_no_caret="_no_caret" t-nocache-_user_name="_user_name" t-nocache-_user_name_class="_user_name_class" t-nocache-_item_class="_item_class" t-nocache-_link_class="_link_class" t-nocache-_dropdown_menu_class="_dropdown_menu_class">
            <t t-set="is_connected" t-value="not user_id._is_public()"/>
            <li t-if="is_connected" t-attf-class="#{_item_class} o_no_autohide_item">
                <a href="#" role="button" data-bs-toggle="dropdown" t-attf-class="#{'''' if _no_caret else ''dropdown-toggle''} btn #{_link_class}">
                    <t t-if="_avatar">
                        <t t-set="avatar_source" t-value="image_data_uri(user_id.avatar_256)"/>
                        <img t-att-src="avatar_source" t-attf-class="rounded-circle o_object_fit_cover #{_avatar_class}" width="24" height="24" alt="" loading="eager"/>
                    </t>
                    <div t-if="_icon" t-attf-class="#{_icon_wrap_class}">
                        <i t-attf-class="fa fa-1x fa-fw fa-user #{_icon_class}"/>
                    </div>
                    <span t-if="_user_name" t-attf-class="#{_user_name_class}" t-esc="user_id.name[:23] + ''...'' if user_id.name and len(user_id.name) &gt; 25 else user_id.name"/>
                </a>
                <div t-attf-class="dropdown-menu js_usermenu #{_dropdown_menu_class}" role="menu">
                    <a groups="base.group_user" href="/web" role="menuitem" class="dropdown-item ps-3" id="o_backend_user_dropdown_link">
                        <i class="fa fa-fw fa-th me-1 small text-primary"/> Apps
                    </a>
                    <div id="o_logout_divider" class="dropdown-divider"/>
                    <a t-attf-href="/web/session/logout?redirect=/" role="menuitem" id="o_logout" class="dropdown-item ps-3">
                        <i class="fa fa-fw fa-sign-out me-1 small text-primary"/> Logout
                    </a>
                </div>
            </li>
        </t>
    </t>

    ', false, true, '2026-05-10 01:11:52.573269', '2026-05-10 01:11:52.573269', false);
INSERT INTO public.ir_ui_view VALUES (542, 16, NULL, 1, 1, 'Portal Breadcrumbs', NULL, 'portal.portal_breadcrumbs', 'qweb', 'portal/views/portal_templates.xml', 'primary', '{"en_US": "<t name=\"Portal Breadcrumbs\" t-name=\"portal.portal_breadcrumbs\">\n        <ol t-if=\"page_name != ''home''\" class=\"o_portal_submenu breadcrumb mb-0 flex-grow-1 px-0\">\n            <li class=\"breadcrumb-item ms-1\"><a href=\"/my/home\" aria-label=\"Home\" title=\"Home\"><i class=\"fa fa-home\"/></a></li>\n            <li t-if=\"page_name == ''my_details''\" class=\"breadcrumb-item\">Details</li>\n        </ol>\n    </t>"}', '<?xml version="1.0"?>
<t name="Portal Breadcrumbs" t-name="portal.portal_breadcrumbs">
        <ol t-if="page_name != ''home''" class="o_portal_submenu breadcrumb mb-0 flex-grow-1 px-0">
            <li class="breadcrumb-item ms-1"><a href="/my/home" aria-label="Home" title="Home"><i class="fa fa-home"/></a></li>
            <li t-if="page_name == ''my_details''" class="breadcrumb-item">Details</li>
        </ol>
    </t>

    ', false, true, '2026-05-10 01:11:52.573269', '2026-05-10 01:11:52.573269', false);
INSERT INTO public.ir_ui_view VALUES (543, 16, NULL, 1, 1, 'Back to edit mode', NULL, 'portal.portal_back_in_edit_mode', 'qweb', 'portal/views/portal_templates.xml', 'primary', '{"en_US": "<t name=\"Back to edit mode\" t-name=\"portal.portal_back_in_edit_mode\">\n        <div t-ignore=\"true\" class=\"text-center\">\n            <t t-if=\"custom_html\" t-out=\"custom_html\"/>\n            <t t-else=\"\">This is a preview of the customer portal.</t>\n            <a t-att-href=\"backend_url\" class=\"alert-link\"><i class=\"oi oi-arrow-right me-1\"/>Back to edit mode</a>\n        </div>\n        <button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"alert\" aria-label=\"Close\"/>\n    </t>"}', '<?xml version="1.0"?>
<t name="Back to edit mode" t-name="portal.portal_back_in_edit_mode">
        <div t-ignore="true" class="text-center">
            <t t-if="custom_html" t-out="custom_html"/>
            <t t-else="">This is a preview of the customer portal.</t>
            <a t-att-href="backend_url" class="alert-link"><i class="oi oi-arrow-right me-1"/>Back to edit mode</a>
        </div>
        <button type="button" class="btn-close" data-bs-dismiss="alert" aria-label="Close"/>
    </t>

    ', false, true, '2026-05-10 01:11:52.573269', '2026-05-10 01:11:52.573269', false);
INSERT INTO public.ir_ui_view VALUES (544, 16, NULL, 1, 1, 'Portal Layout', NULL, 'portal.portal_layout', 'qweb', 'portal/views/portal_templates.xml', 'primary', '{"en_US": "<t name=\"Portal Layout\" t-name=\"portal.portal_layout\">\n        <t t-call=\"portal.frontend_layout\">\n            <t t-set=\"is_portal\" t-value=\"True\"/>\n\n            <div t-if=\"not no_breadcrumbs and not my_details and not breadcrumbs_searchbar\" class=\"o_portal container mt-3\">\n                <div class=\"d-flex justify-content-between align-items-center\">\n                    <t t-call=\"portal.portal_breadcrumbs\"/>\n                    <t t-if=\"prev_record or next_record\" t-call=\"portal.record_pager\"/>\n                </div>\n            </div>\n            <div id=\"wrap\" class=\"o_portal_wrap\">\n                <div class=\"container pt-3\">\n                    <t t-if=\"my_details\">\n                        <div class=\"wrapper col-12 d-flex flex-wrap justify-content-between align-items-center\">\n                            <h3 class=\"my-3\">My account</h3>\n                            <button class=\"btn py-0 d-flex align-items-center gap-2 d-lg-none ms-auto\" data-bs-toggle=\"offcanvas\" data-bs-target=\"#accountOffCanvas\">\n                                <img class=\"o_avatar rounded\" t-att-src=\"image_data_uri(user_id.partner_id.avatar_1024)\" alt=\"Contact\"/>\n                            </button>\n                        </div>\n                        <div class=\"row justify-content-between\">\n                            <div t-attf-class=\"o_portal_content col-12 col-lg-8 mb-5\">\n                                <t t-out=\"0\"/>\n                            </div>\n                            <div class=\"d-none d-lg-flex justify-content-end col-lg-4\">\n                                <t t-call=\"portal.side_content\"/>\n                            </div>\n                            <div class=\"offcanvas offcanvas-start d-lg-none\" id=\"accountOffCanvas\">\n                                <t t-call=\"portal.side_content\">\n                                    <t t-set=\"isOffcanvas\" t-value=\"true\"/>\n                                </t>\n                            </div>\n                        </div>\n                    </t>\n                    <t t-else=\"\">\n                        <t t-out=\"0\"/>\n                    </t>\n                </div>\n            </div>\n        </t>\n    </t>"}', '<?xml version="1.0"?>
<t name="Portal Layout" t-name="portal.portal_layout">
        <t t-call="portal.frontend_layout">
            <t t-set="is_portal" t-value="True"/>

            <div t-if="not no_breadcrumbs and not my_details and not breadcrumbs_searchbar" class="o_portal container mt-3">
                <div class="d-flex justify-content-between align-items-center">
                    <t t-call="portal.portal_breadcrumbs"/>
                    <t t-if="prev_record or next_record" t-call="portal.record_pager"/>
                </div>
            </div>
            <div id="wrap" class="o_portal_wrap">
                <div class="container pt-3">
                    <t t-if="my_details">
                        <div class="wrapper col-12 d-flex flex-wrap justify-content-between align-items-center">
                            <h3 class="my-3">My account</h3>
                            <button class="btn py-0 d-flex align-items-center gap-2 d-lg-none ms-auto" data-bs-toggle="offcanvas" data-bs-target="#accountOffCanvas">
                                <img class="o_avatar rounded" t-att-src="image_data_uri(user_id.partner_id.avatar_1024)" alt="Contact"/>
                            </button>
                        </div>
                        <div class="row justify-content-between">
                            <div t-attf-class="o_portal_content col-12 col-lg-8 mb-5">
                                <t t-out="0"/>
                            </div>
                            <div class="d-none d-lg-flex justify-content-end col-lg-4">
                                <t t-call="portal.side_content"/>
                            </div>
                            <div class="offcanvas offcanvas-start d-lg-none" id="accountOffCanvas">
                                <t t-call="portal.side_content">
                                    <t t-set="isOffcanvas" t-value="true"/>
                                </t>
                            </div>
                        </div>
                    </t>
                    <t t-else="">
                        <t t-out="0"/>
                    </t>
                </div>
            </div>
        </t>
    </t>

    ', false, true, '2026-05-10 01:11:52.573269', '2026-05-10 01:11:52.573269', false);
INSERT INTO public.ir_ui_view VALUES (545, 16, NULL, 1, 1, 'User Sign In Placeholder', NULL, 'portal.placeholder_user_sign_in', 'qweb', 'portal/views/portal_templates.xml', 'primary', '{"en_US": "<t name=\"User Sign In Placeholder\" t-name=\"portal.placeholder_user_sign_in\"/>"}', '<?xml version="1.0"?>
<t name="User Sign In Placeholder" t-name="portal.placeholder_user_sign_in"/>

    ', false, true, '2026-05-10 01:11:52.573269', '2026-05-10 01:11:52.573269', false);
INSERT INTO public.ir_ui_view VALUES (546, 16, 545, 1, 1, 'User Sign In', NULL, 'portal.user_sign_in', 'qweb', 'portal/views/portal_templates.xml', 'extension', '{"en_US": "<data name=\"User Sign In\" inherit_id=\"portal.placeholder_user_sign_in\">\n        <xpath expr=\".\" position=\"inside\">\n            <li t-nocache=\"Profile session and user group can change unrelated to parent caches.\" t-nocache-_item_class=\"_item_class\" t-nocache-_link_class=\"_link_class\" groups=\"base.group_public\" t-attf-class=\"#{_item_class} o_no_autohide_item\">\n                <a t-attf-href=\"/web/login\" t-attf-class=\"#{_link_class}\">Sign in<span t-if=\"request.session.profile_session\" class=\"text-danger fa fa-circle\"/></a>\n            </li>\n        </xpath>\n    </data>"}', '<?xml version="1.0"?>
<data name="User Sign In" inherit_id="portal.placeholder_user_sign_in">
        <xpath expr="." position="inside">
            <li t-nocache="Profile session and user group can change unrelated to parent caches." t-nocache-_item_class="_item_class" t-nocache-_link_class="_link_class" groups="base.group_public" t-attf-class="#{_item_class} o_no_autohide_item">
                <a t-attf-href="/web/login" t-attf-class="#{_link_class}">Sign in<span t-if="request.session.profile_session" class="text-danger fa fa-circle"/></a>
            </li>
        </xpath>
    </data>

    ', false, true, '2026-05-10 01:11:52.573269', '2026-05-10 01:11:52.573269', false);
INSERT INTO public.ir_ui_view VALUES (547, 16, 546, 1, 1, 'User Sign In redirect', NULL, 'portal.user_sign_in_redirect', 'qweb', 'portal/views/portal_templates.xml', 'primary', '{"en_US": "<data name=\"User Sign In redirect\" inherit_id=\"portal.user_sign_in\" primary=\"True\">\n        <xpath expr=\"//a\" position=\"attributes\">\n            <attribute name=\"t-attf-href\">/web/login?redirect={{request.httprequest.path}}</attribute>\n        </xpath>\n    <xpath expr=\".\" position=\"attributes\"><attribute name=\"t-name\">portal.user_sign_in_redirect</attribute></xpath></data>"}', '<?xml version="1.0"?>
<data name="User Sign In redirect" inherit_id="portal.user_sign_in" primary="True">
        <xpath expr="//a" position="attributes">
            <attribute name="t-attf-href">/web/login?redirect={{request.httprequest.path}}</attribute>
        </xpath>
    <xpath expr="." position="attributes"><attribute name="t-name">portal.user_sign_in_redirect</attribute></xpath></data>

    ', false, true, '2026-05-10 01:11:52.573269', '2026-05-10 01:11:52.573269', false);
INSERT INTO public.ir_ui_view VALUES (548, 16, NULL, 1, 1, 'My Portal', NULL, 'portal.portal_my_home', 'qweb', 'portal/views/portal_templates.xml', 'primary', '{"en_US": "<t name=\"My Portal\" t-name=\"portal.portal_my_home\">\n        <t t-call=\"portal.portal_layout\">\n            <t t-set=\"my_details\" t-value=\"True\"/>\n            <div class=\"o_portal_my_home\">\n                <div class=\"oe_structure\" id=\"oe_structure_portal_my_home_1\"/>\n                <div class=\"o_portal_docs row g-2\">\n                    <div class=\"o_portal_doc_spinner spinner-border text-o-color-2 align-self-center mt-5\"/>\n                    <div t-if=\"portal_alert_category_enable\" class=\"o_portal_category row g-2 mt-3\" id=\"portal_alert_category\"/>\n                    <div t-if=\"portal_client_category_enable\" class=\"o_portal_category row g-2 mt-3\" id=\"portal_client_category\"/>\n                    <div t-if=\"portal_service_category_enable\" class=\"o_portal_category row g-2 mt-3\" id=\"portal_service_category\"/>\n                    <div t-if=\"portal_vendor_category_enable\" class=\"o_portal_category row g-2 mt-3\" id=\"portal_vendor_category\"/>\n                    <div class=\"o_portal_category row g-2 mt-3\" id=\"portal_common_category\">\n                        <t t-call=\"portal.portal_docs_entry\" t-if=\"False\"/>\n                        <t t-call=\"portal.portal_docs_entry\">\n                            <t t-set=\"icon\" t-value=\"''/portal/static/src/img/portal-connection.svg''\"/>\n                            <t t-set=\"title\">Connection &amp; Security</t>\n                            <t t-set=\"text\">Configure your connection parameters</t>\n                            <t t-set=\"url\" t-value=\"''/my/security''\"/>\n                            <t t-set=\"config_card\" t-value=\"True\"/>\n                        </t>\n                    </div>\n                </div>\n            </div>\n            <div class=\"oe_structure\" id=\"oe_structure_portal_my_home_2\"/>\n        </t>\n    </t>"}', '<?xml version="1.0"?>
<t name="My Portal" t-name="portal.portal_my_home">
        <t t-call="portal.portal_layout">
            <t t-set="my_details" t-value="True"/>
            <div class="o_portal_my_home">
                <div class="oe_structure" id="oe_structure_portal_my_home_1"/>
                <div class="o_portal_docs row g-2">
                    <div class="o_portal_doc_spinner spinner-border text-o-color-2 align-self-center mt-5"/>
                    <div t-if="portal_alert_category_enable" class="o_portal_category row g-2 mt-3" id="portal_alert_category"/>
                    <div t-if="portal_client_category_enable" class="o_portal_category row g-2 mt-3" id="portal_client_category"/>
                    <div t-if="portal_service_category_enable" class="o_portal_category row g-2 mt-3" id="portal_service_category"/>
                    <div t-if="portal_vendor_category_enable" class="o_portal_category row g-2 mt-3" id="portal_vendor_category"/>
                    <div class="o_portal_category row g-2 mt-3" id="portal_common_category">
                        <t t-call="portal.portal_docs_entry" t-if="False"/>
                        <t t-call="portal.portal_docs_entry">
                            <t t-set="icon" t-value="''/portal/static/src/img/portal-connection.svg''"/>
                            <t t-set="title">Connection &amp; Security</t>
                            <t t-set="text">Configure your connection parameters</t>
                            <t t-set="url" t-value="''/my/security''"/>
                            <t t-set="config_card" t-value="True"/>
                        </t>
                    </div>
                </div>
            </div>
            <div class="oe_structure" id="oe_structure_portal_my_home_2"/>
        </t>
    </t>

    ', false, true, '2026-05-10 01:11:52.573269', '2026-05-10 01:11:52.573269', false);
INSERT INTO public.ir_ui_view VALUES (549, 16, NULL, 1, 1, 'My Portal Docs Entry', NULL, 'portal.portal_docs_entry', 'qweb', 'portal/views/portal_templates.xml', 'primary', '{"en_US": "<t name=\"My Portal Docs Entry\" t-name=\"portal.portal_docs_entry\">\n        <div t-att-class=\"''o_portal_index_card '' +  ('''' if config_card else ''d-none '') + (''col-12 order-0'' if show_count else ''col-md-6 order-2'')\">\n            <a t-att-href=\"url\" t-att-title=\"title\" t-attf-class=\"d-flex justify-content-start gap-2 gap-md-3 align-items-center py-3 pe-2 px-md-3 h-100 rounded text-decoration-none text-reset #{bg_color if bg_color else ''text-bg-light''}\">\n                <div t-if=\"icon\" class=\"o_portal_icon align-self-start\">\n                    <img t-attf-src=\"#{icon}\"/>\n                </div>\n                <div>\n                    <h5 t-attf-class=\"mt-0 mb-1 #{''d-flex gap-2'' if placeholder_count or count else ''''}\">\n                        <t t-out=\"count\"/>\n                        <span t-if=\"placeholder_count\" t-att-class=\"'''' if show_count else ''d-none''\" t-att-data-placeholder_count=\"placeholder_count\"/>\n                        <span t-out=\"title\"/>\n                    </h5>\n                    <p class=\"m-0 text-600\">\n                        <t t-out=\"text\"/>\n                    </p>\n                </div>\n            </a>\n        </div>\n    </t>"}', '<?xml version="1.0"?>
<t name="My Portal Docs Entry" t-name="portal.portal_docs_entry">
        <div t-att-class="''o_portal_index_card '' +  ('''' if config_card else ''d-none '') + (''col-12 order-0'' if show_count else ''col-md-6 order-2'')">
            <a t-att-href="url" t-att-title="title" t-attf-class="d-flex justify-content-start gap-2 gap-md-3 align-items-center py-3 pe-2 px-md-3 h-100 rounded text-decoration-none text-reset #{bg_color if bg_color else ''text-bg-light''}">
                <div t-if="icon" class="o_portal_icon align-self-start">
                    <img t-attf-src="#{icon}"/>
                </div>
                <div>
                    <h5 t-attf-class="mt-0 mb-1 #{''d-flex gap-2'' if placeholder_count or count else ''''}">
                        <t t-out="count"/>
                        <span t-if="placeholder_count" t-att-class="'''' if show_count else ''d-none''" t-att-data-placeholder_count="placeholder_count"/>
                        <span t-out="title"/>
                    </h5>
                    <p class="m-0 text-600">
                        <t t-out="text"/>
                    </p>
                </div>
            </a>
        </div>
    </t>

    ', false, true, '2026-05-10 01:11:52.573269', '2026-05-10 01:11:52.573269', false);
INSERT INTO public.ir_ui_view VALUES (550, 16, NULL, 1, 1, 'My Portal Table', NULL, 'portal.portal_table', 'qweb', 'portal/views/portal_templates.xml', 'primary', '{"en_US": "<t name=\"My Portal Table\" t-name=\"portal.portal_table\">\n        <div t-attf-class=\"table-responsive border-0 #{classes if classes else ''''}\">\n            <table class=\"o_list_table position-relative table table-sm o_list_table_ungrouped table-striped o_portal_my_doc_table mb-0\">\n                <t t-out=\"0\"/>\n            </table>\n        </div>\n        <div t-if=\"pager\" class=\"o_portal_pager d-flex justify-content-center my-3\">\n            <t t-call=\"portal.pager\"/>\n        </div>\n    </t>"}', '<?xml version="1.0"?>
<t name="My Portal Table" t-name="portal.portal_table">
        <div t-attf-class="table-responsive border-0 #{classes if classes else ''''}">
            <table class="o_list_table position-relative table table-sm o_list_table_ungrouped table-striped o_portal_my_doc_table mb-0">
                <t t-out="0"/>
            </table>
        </div>
        <div t-if="pager" class="o_portal_pager d-flex justify-content-center my-3">
            <t t-call="portal.pager"/>
        </div>
    </t>

    ', false, true, '2026-05-10 01:11:52.573269', '2026-05-10 01:11:52.573269', false);
INSERT INTO public.ir_ui_view VALUES (561, 16, NULL, 1, 1, 'message_thread', NULL, 'portal.message_thread', 'qweb', 'portal/views/portal_templates.xml', 'primary', '{"en_US": "<t t-name=\"portal.message_thread\">\n        <div id=\"discussion\" data-anchor=\"true\" class=\"d-print-none o_portal_chatter o_not_editable p-0\" t-att-data-token=\"token\" t-att-data-res_model=\"object._name\" t-att-data-pid=\"pid\" t-att-data-hash=\"hash\" t-att-data-res_id=\"object.id\" t-att-data-pager_step=\"message_per_page or 10\" t-att-data-allow_composer=\"''0'' if disable_composer else ''1''\" t-att-data-two_columns=\"''true'' if two_columns else ''false''\">\n        </div>\n    </t>"}', '<?xml version="1.0"?>
<t t-name="portal.message_thread">
        <div id="discussion" data-anchor="true" class="d-print-none o_portal_chatter o_not_editable p-0" t-att-data-token="token" t-att-data-res_model="object._name" t-att-data-pid="pid" t-att-data-hash="hash" t-att-data-res_id="object.id" t-att-data-pager_step="message_per_page or 10" t-att-data-allow_composer="''0'' if disable_composer else ''1''" t-att-data-two_columns="''true'' if two_columns else ''false''">
        </div>
    </t>

    ', false, true, '2026-05-10 01:11:52.573269', '2026-05-10 01:11:52.573269', false);
INSERT INTO public.ir_ui_view VALUES (551, 16, NULL, 1, 1, 'My Portal Record Sidebar', NULL, 'portal.portal_record_sidebar', 'qweb', 'portal/views/portal_templates.xml', 'primary', '{"en_US": "<t name=\"My Portal Record Sidebar\" t-name=\"portal.portal_record_sidebar\">\n        <div t-attf-class=\"#{classes}\">\n            <div class=\"o_portal_sidebar_content d-lg-inline-block mb-4 mb-lg-0 p-3 p-lg-0\" id=\"sidebar_content\">\n                <div t-if=\"title\" class=\"position-relative d-flex align-items-center justify-content-md-center justify-content-lg-between flex-wrap gap-2\">\n                    <t t-out=\"title\"/>\n                </div>\n                <t t-if=\"entries\" t-out=\"entries\"/>\n                <div class=\"d-none d-lg-block mt-5 small text-center text-muted\">\n                    Powered by <a target=\"_blank\" href=\"http://www.odoo.com?utm_source=db&amp;utm_medium=portal\" title=\"odoo\"><img src=\"/web/static/img/logo.png\" alt=\"Odoo Logo\" height=\"15\"/></a>\n                </div>\n            </div>\n        </div>\n    </t>"}', '<?xml version="1.0"?>
<t name="My Portal Record Sidebar" t-name="portal.portal_record_sidebar">
        <div t-attf-class="#{classes}">
            <div class="o_portal_sidebar_content d-lg-inline-block mb-4 mb-lg-0 p-3 p-lg-0" id="sidebar_content">
                <div t-if="title" class="position-relative d-flex align-items-center justify-content-md-center justify-content-lg-between flex-wrap gap-2">
                    <t t-out="title"/>
                </div>
                <t t-if="entries" t-out="entries"/>
                <div class="d-none d-lg-block mt-5 small text-center text-muted">
                    Powered by <a target="_blank" href="http://www.odoo.com?utm_source=db&amp;utm_medium=portal" title="odoo"><img src="/web/static/img/logo.png" alt="Odoo Logo" height="15"/></a>
                </div>
            </div>
        </div>
    </t>

    ', false, true, '2026-05-10 01:11:52.573269', '2026-05-10 01:11:52.573269', false);
INSERT INTO public.ir_ui_view VALUES (552, 16, NULL, 1, 1, 'Portal Search Bar', NULL, 'portal.portal_searchbar', 'qweb', 'portal/views/portal_templates.xml', 'primary', '{"en_US": "<t name=\"Portal Search Bar\" t-name=\"portal.portal_searchbar\">\n        <nav t-attf-class=\"navbar navbar-expand-lg flex-wrap mb-4 p-0 o_portal_navbar {{classes if classes else ''''}}\">\n            <!--  Navbar breadcrumb or title  -->\n            <t t-if=\"breadcrumbs_searchbar\">\n                <t t-call=\"portal.portal_breadcrumbs\"/>\n            </t>\n            <span t-else=\"\" class=\"navbar-brand mb-0 h1 me-auto\" t-esc=\"title or ''No title''\"/>\n\n            <!--  Collapse button -->\n            <button class=\"navbar-toggler\" type=\"button\" data-bs-toggle=\"collapse\" data-bs-target=\"#o_portal_navbar_content\" aria-controls=\"navbarSupportedContent\" aria-expanded=\"false\" aria-label=\"Toggle filters\">\n                <span class=\"fa fa-fw fa-bars\"/>\n            </button>\n\n            <!--  Collapsable content  -->\n            <div class=\"collapse navbar-collapse flex-wrap-reverse justify-content-end gap-3\" id=\"o_portal_navbar_content\">\n                <div class=\"nav flex-column flex-sm-row gap-2 ms-auto p-0 mb-3 mb-lg-0 mt-1 mt-lg-0\">\n                    <div t-if=\"searchbar_sortings\">\n                        <span class=\"small me-1 navbar-text\">Sort By:</span>\n                        <div class=\"btn-group\">\n                            <button id=\"portal_searchbar_sortby\" data-bs-toggle=\"dropdown\" class=\"btn btn-secondary dropdown-toggle\">\n                                <t t-esc=\"searchbar_sortings[sortby].get(''label'', ''Newest'')\"/>\n                            </button>\n                            <div class=\"dropdown-menu dropdown-menu-end\" aria-labelledby=\"portal_searchbar_sortby\">\n                                <t t-foreach=\"searchbar_sortings\" t-as=\"option\">\n                                    <a t-att-href=\"request.httprequest.path + ''?'' + keep_query(''*'', sortby=option)\" t-attf-class=\"dropdown-item#{sortby == option and '' active'' or ''''}\">\n                                        <span t-esc=\"searchbar_sortings[option].get(''label'')\"/>\n                                    </a>\n                                </t>\n                            </div>\n                        </div>\n                    </div>\n                    <div t-if=\"searchbar_filters\" class=\"ms-lg-2\">\n                        <span class=\"small me-1 navbar-text\">Filter By:</span>\n                        <div class=\"btn-group\">\n                            <button id=\"portal_searchbar_filters\" data-bs-toggle=\"dropdown\" class=\"btn btn-secondary dropdown-toggle\">\n                                <t t-esc=\"searchbar_filters.get(filterby,searchbar_filters.get(''all'')).get(''label'', ''All'')\"/>\n                            </button>\n                            <div class=\"dropdown-menu dropdown-menu-end\" aria-labelledby=\"portal_searchbar_filters\">\n                                <t t-foreach=\"searchbar_filters\" t-as=\"option\">\n                                    <a t-att-href=\"default_url + ''?'' + keep_query(''*'', filterby=option)\" t-attf-class=\"dropdown-item#{filterby == option and '' active'' or ''''}\">\n                                        <span t-esc=\"searchbar_filters[option].get(''label'')\"/>\n                                    </a>\n                                </t>\n                            </div>\n                        </div>\n                    </div>\n                    <div t-if=\"searchbar_groupby\" class=\"ms-lg-2\">\n                        <span class=\"small me-1 navbar-text\">Group By:</span>\n                        <div class=\"btn-group\">\n                            <button id=\"portal_searchbar_groupby\" data-bs-toggle=\"dropdown\" class=\"btn btn-secondary dropdown-toggle\">\n                                <t t-esc=\"searchbar_groupby[groupby].get(''label'', ''None'')\"/>\n                            </button>\n                            <div class=\"dropdown-menu dropdown-menu-end\" aria-labelledby=\"portal_searchbar_groupby\">\n                                <t t-foreach=\"searchbar_groupby\" t-as=\"option\">\n                                    <a t-att-href=\"default_url + ''?'' + keep_query(''*'', groupby=option)\" t-attf-class=\"dropdown-item#{groupby == option and '' active'' or ''''}\">\n                                        <span t-esc=\"searchbar_groupby[option].get(''label'')\"/>\n                                    </a>\n                                </t>\n                            </div>\n                        </div>\n                    </div>\n                    <t t-out=\"0\"/>\n                </div>\n                <form t-if=\"searchbar_inputs\" class=\"o_portal_search_panel col-md-5 col-xl-4 ms-lg-2\">\n                    <div class=\"input-group w-100\">\n                        <button type=\"button\" class=\"btn btn-secondary border-end dropdown-toggle\" data-bs-toggle=\"dropdown\"/>\n                        <div class=\"dropdown-menu dropdown-menu-end\" role=\"menu\">\n                            <t t-foreach=\"searchbar_inputs\" t-as=\"input\">\n                                <a t-att-href=\"''#'' + input_value[''input'']\" t-attf-class=\"dropdown-item#{search_in == input_value[''input''] and '' active'' or ''''}\">\n                                    <span t-out=\"input_value[''label'']\"/>\n                                </a>\n                            </t>\n                        </div>\n                        <input type=\"text\" class=\"form-control\" placeholder=\"Search\" t-att-value=\"search\" name=\"search\"/>\n                        <button class=\"btn btn-secondary o_wait_lazy_js\" type=\"submit\">\n                            <span class=\"oi oi-search\"/>\n                        </button>\n                    </div>\n                </form>\n            </div>\n        </nav>\n    </t>"}', '<?xml version="1.0"?>
<t name="Portal Search Bar" t-name="portal.portal_searchbar">
        <nav t-attf-class="navbar navbar-expand-lg flex-wrap mb-4 p-0 o_portal_navbar {{classes if classes else ''''}}">
            <!--  Navbar breadcrumb or title  -->
            <t t-if="breadcrumbs_searchbar">
                <t t-call="portal.portal_breadcrumbs"/>
            </t>
            <span t-else="" class="navbar-brand mb-0 h1 me-auto" t-esc="title or ''No title''"/>

            <!--  Collapse button -->
            <button class="navbar-toggler" type="button" data-bs-toggle="collapse" data-bs-target="#o_portal_navbar_content" aria-controls="navbarSupportedContent" aria-expanded="false" aria-label="Toggle filters">
                <span class="fa fa-fw fa-bars"/>
            </button>

            <!--  Collapsable content  -->
            <div class="collapse navbar-collapse flex-wrap-reverse justify-content-end gap-3" id="o_portal_navbar_content">
                <div class="nav flex-column flex-sm-row gap-2 ms-auto p-0 mb-3 mb-lg-0 mt-1 mt-lg-0">
                    <div t-if="searchbar_sortings">
                        <span class="small me-1 navbar-text">Sort By:</span>
                        <div class="btn-group">
                            <button id="portal_searchbar_sortby" data-bs-toggle="dropdown" class="btn btn-secondary dropdown-toggle">
                                <t t-esc="searchbar_sortings[sortby].get(''label'', ''Newest'')"/>
                            </button>
                            <div class="dropdown-menu dropdown-menu-end" aria-labelledby="portal_searchbar_sortby">
                                <t t-foreach="searchbar_sortings" t-as="option">
                                    <a t-att-href="request.httprequest.path + ''?'' + keep_query(''*'', sortby=option)" t-attf-class="dropdown-item#{sortby == option and '' active'' or ''''}">
                                        <span t-esc="searchbar_sortings[option].get(''label'')"/>
                                    </a>
                                </t>
                            </div>
                        </div>
                    </div>
                    <div t-if="searchbar_filters" class="ms-lg-2">
                        <span class="small me-1 navbar-text">Filter By:</span>
                        <div class="btn-group">
                            <button id="portal_searchbar_filters" data-bs-toggle="dropdown" class="btn btn-secondary dropdown-toggle">
                                <t t-esc="searchbar_filters.get(filterby,searchbar_filters.get(''all'')).get(''label'', ''All'')"/>
                            </button>
                            <div class="dropdown-menu dropdown-menu-end" aria-labelledby="portal_searchbar_filters">
                                <t t-foreach="searchbar_filters" t-as="option">
                                    <a t-att-href="default_url + ''?'' + keep_query(''*'', filterby=option)" t-attf-class="dropdown-item#{filterby == option and '' active'' or ''''}">
                                        <span t-esc="searchbar_filters[option].get(''label'')"/>
                                    </a>
                                </t>
                            </div>
                        </div>
                    </div>
                    <div t-if="searchbar_groupby" class="ms-lg-2">
                        <span class="small me-1 navbar-text">Group By:</span>
                        <div class="btn-group">
                            <button id="portal_searchbar_groupby" data-bs-toggle="dropdown" class="btn btn-secondary dropdown-toggle">
                                <t t-esc="searchbar_groupby[groupby].get(''label'', ''None'')"/>
                            </button>
                            <div class="dropdown-menu dropdown-menu-end" aria-labelledby="portal_searchbar_groupby">
                                <t t-foreach="searchbar_groupby" t-as="option">
                                    <a t-att-href="default_url + ''?'' + keep_query(''*'', groupby=option)" t-attf-class="dropdown-item#{groupby == option and '' active'' or ''''}">
                                        <span t-esc="searchbar_groupby[option].get(''label'')"/>
                                    </a>
                                </t>
                            </div>
                        </div>
                    </div>
                    <t t-out="0"/>
                </div>
                <form t-if="searchbar_inputs" class="o_portal_search_panel col-md-5 col-xl-4 ms-lg-2">
                    <div class="input-group w-100">
                        <button type="button" class="btn btn-secondary border-end dropdown-toggle" data-bs-toggle="dropdown"/>
                        <div class="dropdown-menu dropdown-menu-end" role="menu">
                            <t t-foreach="searchbar_inputs" t-as="input">
                                <a t-att-href="''#'' + input_value[''input'']" t-attf-class="dropdown-item#{search_in == input_value[''input''] and '' active'' or ''''}">
                                    <span t-out="input_value[''label'']"/>
                                </a>
                            </t>
                        </div>
                        <input type="text" class="form-control" placeholder="Search" t-att-value="search" name="search"/>
                        <button class="btn btn-secondary o_wait_lazy_js" type="submit">
                            <span class="oi oi-search"/>
                        </button>
                    </div>
                </form>
            </div>
        </nav>
    </t>

    ', false, true, '2026-05-10 01:11:52.573269', '2026-05-10 01:11:52.573269', false);
INSERT INTO public.ir_ui_view VALUES (553, 16, NULL, 1, 1, 'Portal single record layout', NULL, 'portal.portal_record_layout', 'qweb', 'portal/views/portal_templates.xml', 'primary', '{"en_US": "<t name=\"Portal single record layout\" t-name=\"portal.portal_record_layout\">\n        <div t-attf-class=\"card mt-0 rounded #{classes if classes else ''''}\">\n            <div t-if=\"card_header\" t-attf-class=\"card-header #{header_classes if header_classes else ''''}\">\n                <t t-out=\"card_header\"/>\n            </div>\n            <div t-if=\"card_body\" t-attf-class=\"card-body #{body_classes if body_classes else ''''}\">\n                <t t-out=\"card_body\"/>\n            </div>\n        </div>\n    </t>"}', '<?xml version="1.0"?>
<t name="Portal single record layout" t-name="portal.portal_record_layout">
        <div t-attf-class="card mt-0 rounded #{classes if classes else ''''}">
