    ', false, true, '2026-05-10 01:11:52.573269', '2026-05-10 01:11:52.573269', false);
INSERT INTO public.ir_ui_view VALUES (554, 16, NULL, 1, 1, 'Contact', NULL, 'portal.portal_contact', 'qweb', 'portal/views/portal_templates.xml', 'primary', '{"en_US": "<t name=\"Contact\" t-name=\"portal.portal_contact\">\n        <div class=\"o_portal_contact_details mb-5\">\n            <h4>Your contact</h4>\n            <hr class=\"mt-1 mb0\"/>\n            <h6 class=\"mb-1\"><b t-esc=\"sales_user.name\"/></h6>\n            <div t-if=\"sales_user.email_normalized\" class=\"d-flex align-items-center mb-1\">\n                <div class=\"fa fa-envelope fa-fw me-1\"/>\n                <a t-att-href=\"''mailto:''+sales_user.email\" t-esc=\"sales_user.email\"/>\n            </div>\n            <div class=\"d-flex flex-nowrap align-items-center mb-1\">\n                <div class=\"fa fa-phone fa-fw me-1\"/>\n                <span t-esc=\"sales_user.phone\"/>\n            </div>\n            <div class=\"d-flex flex-nowrap align-items-center mb-1\">\n                <div class=\"fa fa-map-marker fa-fw me-1\"/>\n                <span t-esc=\"sales_user.city\"/>\n            </div>\n        </div>\n    </t>"}', '<?xml version="1.0"?>
<t name="Contact" t-name="portal.portal_contact">
        <div class="o_portal_contact_details mb-5">
            <h4>Your contact</h4>
            <hr class="mt-1 mb0"/>
            <h6 class="mb-1"><b t-esc="sales_user.name"/></h6>
            <div t-if="sales_user.email_normalized" class="d-flex align-items-center mb-1">
                <div class="fa fa-envelope fa-fw me-1"/>
                <a t-att-href="''mailto:''+sales_user.email" t-esc="sales_user.email"/>
            </div>
            <div class="d-flex flex-nowrap align-items-center mb-1">
                <div class="fa fa-phone fa-fw me-1"/>
                <span t-esc="sales_user.phone"/>
            </div>
            <div class="d-flex flex-nowrap align-items-center mb-1">
                <div class="fa fa-map-marker fa-fw me-1"/>
                <span t-esc="sales_user.city"/>
            </div>
        </div>
    </t>

