INSERT INTO public.ir_ui_view VALUES (562, 16, NULL, 1, 1, 'Ask Signature', NULL, 'portal.signature_form', 'qweb', 'portal/views/portal_templates.xml', 'primary', '{"en_US": "<t name=\"Ask Signature\" t-name=\"portal.signature_form\">\n        <t t-set=\"signature_form_props\" t-value=\"{             ''callUrl'': call_url,             ''defaultName'': default_name,             ''mode'': mode,             ''sendLabel'': send_label,             ''signatureRatio'': signature_ratio,             ''signatureType'': signature_type,             ''fontColor'': font_color         }\"/>\n        <owl-component name=\"portal.signature_form\" t-att-props=\"json.dumps(signature_form_props)\"/>\n    </t>"}', '<?xml version="1.0"?>
<t name="Ask Signature" t-name="portal.signature_form">
        <t t-set="signature_form_props" t-value="{             ''callUrl'': call_url,             ''defaultName'': default_name,             ''mode'': mode,             ''sendLabel'': send_label,             ''signatureRatio'': signature_ratio,             ''signatureType'': signature_type,             ''fontColor'': font_color         }"/>
        <owl-component name="portal.signature_form" t-att-props="json.dumps(signature_form_props)"/>
    </t>

    ', false, true, '2026-05-10 01:11:52.573269', '2026-05-10 01:11:52.573269', false);
INSERT INTO public.ir_ui_view VALUES (555, 16, NULL, 1, 1, 'portal_my_details_fields', NULL, 'portal.portal_my_details_fields', 'qweb', 'portal/views/portal_templates.xml', 'primary', '{"en_US": "<t t-name=\"portal.portal_my_details_fields\">\n        <input type=\"hidden\" name=\"csrf_token\" t-att-value=\"request.csrf_token()\"/>\n        <div t-if=\"error_message\" class=\"alert alert-danger\" role=\"alert\">\n            <div class=\"col-lg-12\">\n                <t t-foreach=\"error_message\" t-as=\"err\"><t t-esc=\"err\"/><br/></t>\n            </div>\n        </div>\n        <div t-if=\"not partner_can_edit_vat\" class=\"col-12 d-none d-xl-block\">\n            <small class=\"form-text text-muted\">\n                Company name, VAT Number and country can not be changed once document(s) have been issued for your account.\n                <br/>Please contact us directly for that operation.\n            </small>\n        </div>\n        <div t-attf-class=\"mb-3 #{error.get(''name'') and ''o_has_error'' or ''''} col-xl-6\">\n            <label class=\"col-form-label\" for=\"name\">Name</label>\n            <input type=\"text\" name=\"name\" t-attf-class=\"form-control #{error.get(''name'') and ''is-invalid'' or ''''}\" t-att-value=\"name or partner.name\"/>\n        </div>\n        <div t-attf-class=\"mb-3 #{error.get(''email'') and ''o_has_error'' or ''''} col-xl-6\">\n            <label class=\"col-form-label\" for=\"email\">Email</label>\n            <input type=\"email\" name=\"email\" t-attf-class=\"form-control #{error.get(''email'') and ''is-invalid'' or ''''}\" t-att-value=\"email or partner.email\"/>\n        </div>\n\n        <div class=\"clearfix\"/>\n        <div t-attf-class=\"mb-1 #{error.get(''company_name'') and ''o_has_error'' or ''''} col-xl-6\">\n            <label class=\"col-form-label label-optional\" for=\"company_name\">Company Name</label>\n            <!-- The <input> use \"disabled\" attribute to avoid sending an unauthorized value on form submit.\n                 The user might not have rights to change company_name but should still be able to see it.\n            -->\n            <input type=\"text\" name=\"company_name\" t-attf-class=\"form-control #{error.get(''company_name'') and ''is-invalid'' or ''''}\" t-att-value=\"company_name or partner.commercial_company_name\" t-att-disabled=\"None if partner_can_edit_vat else ''1''\"/>\n            <small t-if=\"not partner_can_edit_vat\" class=\"form-text text-muted d-block d-xl-none\">\n                Changing company name is not allowed once document(s) have been issued for your account. Please contact us directly for this operation.\n            </small>\n        </div>\n        <div t-attf-class=\"mb-1 #{error.get(''vat'') and ''o_has_error'' or ''''} col-xl-6\">\n            <label class=\"col-form-label label-optional\" for=\"vat\">VAT Number</label>\n            <!-- The <input> use \"disabled\" attribute to avoid sending an unauthorized value on form submit.\n                 The user might not have rights to change company_name but should still be able to see it.\n            -->\n            <input type=\"text\" name=\"vat\" t-attf-class=\"form-control #{error.get(''vat'') and ''is-invalid'' or ''''}\" t-att-value=\"vat or partner.vat\" t-att-disabled=\"None if partner_can_edit_vat else ''1''\"/>\n            <small t-if=\"not partner_can_edit_vat\" class=\"form-text text-muted d-block d-xl-none\">Changing VAT number is not allowed once document(s) have been issued for your account. Please contact us directly for this operation.</small>\n        </div>\n        <div t-attf-class=\"mb-3 #{error.get(''phone'') and ''o_has_error'' or ''''} col-xl-6\">\n            <label class=\"col-form-label\" for=\"phone\">Phone</label>\n            <input type=\"tel\" name=\"phone\" t-attf-class=\"form-control #{error.get(''phone'') and ''is-invalid'' or ''''}\" t-att-value=\"phone or partner.phone\"/>\n        </div>\n\n        <div class=\"clearfix\"/>\n        <div t-attf-class=\"mb-3 #{error.get(''street'') and ''o_has_error'' or ''''} col-xl-6\">\n            <label class=\"col-form-label\" for=\"street\">Street</label>\n            <input type=\"text\" name=\"street\" t-attf-class=\"form-control #{error.get(''street'') and ''is-invalid'' or ''''}\" t-att-value=\"street or partner.street\"/>\n        </div>\n        <div t-attf-class=\"mb-3 #{error.get(''city'') and ''o_has_error'' or ''''} col-xl-6\">\n            <label class=\"col-form-label\" for=\"city\">City</label>\n            <input type=\"text\" name=\"city\" t-attf-class=\"form-control #{error.get(''city'') and ''is-invalid'' or ''''}\" t-att-value=\"city or partner.city\"/>\n        </div>\n        <div t-attf-class=\"mb-3 #{error.get(''zip'') and ''o_has_error'' or ''''} col-xl-6\">\n            <label class=\"col-form-label label-optional\" for=\"zipcode\">Zip / Postal Code</label>\n            <input type=\"text\" name=\"zipcode\" t-attf-class=\"form-control #{error.get(''zip'') and ''is-invalid'' or ''''}\" t-att-value=\"zipcode or partner.zip\"/>\n        </div>\n        <div t-attf-class=\"mb-3 #{error.get(''country_id'') and ''o_has_error'' or ''''} col-xl-6\">\n            <label class=\"col-form-label\" for=\"country_id\">Country</label>\n            <select name=\"country_id\" t-attf-class=\"form-select #{error.get(''country_id'') and ''is-invalid'' or ''''}\" t-att-disabled=\"None if partner_can_edit_vat else ''1''\">\n                <option value=\"\">Country...</option>\n                <t t-foreach=\"countries or []\" t-as=\"country\">\n                    <option t-att-value=\"country.id\" t-att-selected=\"country.id == (False if country_id == ''False'' else int(country_id)) if country_id else country.id == partner.country_id.id\">\n                        <t t-esc=\"country.name\"/>\n                    </option>\n                </t>\n            </select>\n            <small t-if=\"not partner_can_edit_vat\" class=\"form-text text-muted d-block d-xl-none\">Changing the country is not allowed once document(s) have been issued for your account. Please contact us directly for this operation.</small>\n        </div>\n        <div t-attf-class=\"mb-3 #{error.get(''state_id'') and ''o_has_error'' or ''''} col-xl-6\">\n            <label class=\"col-form-label label-optional\" for=\"state_id\">State / Province</label>\n            <select name=\"state_id\" t-attf-class=\"form-select #{error.get(''state_id'') and ''is-invalid'' or ''''}\">\n                <option value=\"\">select...</option>\n                <t t-foreach=\"states or []\" t-as=\"state\">\n                    <option t-att-value=\"state.id\" style=\"display:none;\" t-att-data-country_id=\"state.country_id.id\" t-att-selected=\"state.id == int(state_id) if state_id else state.id == partner.state_id.id\">\n                        <t t-esc=\"state.name\"/>\n                    </option>\n                </t>\n            </select>\n        </div>\n    </t>"}', '<?xml version="1.0"?>
<t t-name="portal.portal_my_details_fields">
        <input type="hidden" name="csrf_token" t-att-value="request.csrf_token()"/>
        <div t-if="error_message" class="alert alert-danger" role="alert">
            <div class="col-lg-12">
                <t t-foreach="error_message" t-as="err"><t t-esc="err"/><br/></t>
            </div>
        </div>
        <div t-if="not partner_can_edit_vat" class="col-12 d-none d-xl-block">
            <small class="form-text text-muted">
                Company name, VAT Number and country can not be changed once document(s) have been issued for your account.
                <br/>Please contact us directly for that operation.
            </small>
        </div>
        <div t-attf-class="mb-3 #{error.get(''name'') and ''o_has_error'' or ''''} col-xl-6">
            <label class="col-form-label" for="name">Name</label>
            <input type="text" name="name" t-attf-class="form-control #{error.get(''name'') and ''is-invalid'' or ''''}" t-att-value="name or partner.name"/>
        </div>
        <div t-attf-class="mb-3 #{error.get(''email'') and ''o_has_error'' or ''''} col-xl-6">
            <label class="col-form-label" for="email">Email</label>
            <input type="email" name="email" t-attf-class="form-control #{error.get(''email'') and ''is-invalid'' or ''''}" t-att-value="email or partner.email"/>
        </div>

        <div class="clearfix"/>
        <div t-attf-class="mb-1 #{error.get(''company_name'') and ''o_has_error'' or ''''} col-xl-6">
            <label class="col-form-label label-optional" for="company_name">Company Name</label>
            <!-- The <input> use "disabled" attribute to avoid sending an unauthorized value on form submit.
                 The user might not have rights to change company_name but should still be able to see it.
            -->
            <input type="text" name="company_name" t-attf-class="form-control #{error.get(''company_name'') and ''is-invalid'' or ''''}" t-att-value="company_name or partner.commercial_company_name" t-att-disabled="None if partner_can_edit_vat else ''1''"/>
            <small t-if="not partner_can_edit_vat" class="form-text text-muted d-block d-xl-none">
                Changing company name is not allowed once document(s) have been issued for your account. Please contact us directly for this operation.
            </small>
        </div>
        <div t-attf-class="mb-1 #{error.get(''vat'') and ''o_has_error'' or ''''} col-xl-6">
            <label class="col-form-label label-optional" for="vat">VAT Number</label>
            <!-- The <input> use "disabled" attribute to avoid sending an unauthorized value on form submit.
                 The user might not have rights to change company_name but should still be able to see it.
            -->
            <input type="text" name="vat" t-attf-class="form-control #{error.get(''vat'') and ''is-invalid'' or ''''}" t-att-value="vat or partner.vat" t-att-disabled="None if partner_can_edit_vat else ''1''"/>
            <small t-if="not partner_can_edit_vat" class="form-text text-muted d-block d-xl-none">Changing VAT number is not allowed once document(s) have been issued for your account. Please contact us directly for this operation.</small>
        </div>
        <div t-attf-class="mb-3 #{error.get(''phone'') and ''o_has_error'' or ''''} col-xl-6">
            <label class="col-form-label" for="phone">Phone</label>
            <input type="tel" name="phone" t-attf-class="form-control #{error.get(''phone'') and ''is-invalid'' or ''''}" t-att-value="phone or partner.phone"/>
        </div>

        <div class="clearfix"/>
        <div t-attf-class="mb-3 #{error.get(''street'') and ''o_has_error'' or ''''} col-xl-6">
            <label class="col-form-label" for="street">Street</label>
            <input type="text" name="street" t-attf-class="form-control #{error.get(''street'') and ''is-invalid'' or ''''}" t-att-value="street or partner.street"/>
        </div>
        <div t-attf-class="mb-3 #{error.get(''city'') and ''o_has_error'' or ''''} col-xl-6">
            <label class="col-form-label" for="city">City</label>
            <input type="text" name="city" t-attf-class="form-control #{error.get(''city'') and ''is-invalid'' or ''''}" t-att-value="city or partner.city"/>
        </div>
        <div t-attf-class="mb-3 #{error.get(''zip'') and ''o_has_error'' or ''''} col-xl-6">
            <label class="col-form-label label-optional" for="zipcode">Zip / Postal Code</label>
            <input type="text" name="zipcode" t-attf-class="form-control #{error.get(''zip'') and ''is-invalid'' or ''''}" t-att-value="zipcode or partner.zip"/>
        </div>
        <div t-attf-class="mb-3 #{error.get(''country_id'') and ''o_has_error'' or ''''} col-xl-6">
            <label class="col-form-label" for="country_id">Country</label>
            <select name="country_id" t-attf-class="form-select #{error.get(''country_id'') and ''is-invalid'' or ''''}" t-att-disabled="None if partner_can_edit_vat else ''1''">
                <option value="">Country...</option>
                <t t-foreach="countries or []" t-as="country">
                    <option t-att-value="country.id" t-att-selected="country.id == (False if country_id == ''False'' else int(country_id)) if country_id else country.id == partner.country_id.id">
                        <t t-esc="country.name"/>
                    </option>
                </t>
            </select>
            <small t-if="not partner_can_edit_vat" class="form-text text-muted d-block d-xl-none">Changing the country is not allowed once document(s) have been issued for your account. Please contact us directly for this operation.</small>
        </div>
        <div t-attf-class="mb-3 #{error.get(''state_id'') and ''o_has_error'' or ''''} col-xl-6">
            <label class="col-form-label label-optional" for="state_id">State / Province</label>
            <select name="state_id" t-attf-class="form-select #{error.get(''state_id'') and ''is-invalid'' or ''''}">
                <option value="">select...</option>
                <t t-foreach="states or []" t-as="state">
                    <option t-att-value="state.id" style="display:none;" t-att-data-country_id="state.country_id.id" t-att-selected="state.id == int(state_id) if state_id else state.id == partner.state_id.id">
                        <t t-esc="state.name"/>
                    </option>
                </t>
            </select>
        </div>
    </t>

    ', false, true, '2026-05-10 01:11:52.573269', '2026-05-10 01:11:52.573269', false);
INSERT INTO public.ir_ui_view VALUES (556, 16, NULL, 1, 1, 'portal_my_details', NULL, 'portal.portal_my_details', 'qweb', 'portal/views/portal_templates.xml', 'primary', '{"en_US": "<t t-name=\"portal.portal_my_details\">\n        <t t-call=\"portal.portal_layout\">\n            <t t-set=\"additional_title\">Contact Details</t>\n            <form action=\"/my/account\" method=\"post\">\n                <div class=\"row o_portal_details\">\n                    <div class=\"col-lg-8\">\n                        <div class=\"row\">\n                            <t t-call=\"portal.portal_my_details_fields\"/>\n                            <input type=\"hidden\" name=\"redirect\" t-att-value=\"redirect\"/>\n                        </div>\n                        <div class=\"clearfix text-end mb-5\">\n                            <a href=\"/my/\" class=\"btn btn-secondary me-2\">\n                                Discard\n                            </a>\n                            <button type=\"submit\" class=\"btn btn-primary float-end\">\n                                Save\n                            </button>\n                        </div>\n                    </div>\n                </div>\n            </form>\n        </t>\n    </t>"}', '<?xml version="1.0"?>
<t t-name="portal.portal_my_details">
        <t t-call="portal.portal_layout">
            <t t-set="additional_title">Contact Details</t>
            <form action="/my/account" method="post">
                <div class="row o_portal_details">
                    <div class="col-lg-8">
                        <div class="row">
                            <t t-call="portal.portal_my_details_fields"/>
                            <input type="hidden" name="redirect" t-att-value="redirect"/>
                        </div>
                        <div class="clearfix text-end mb-5">
                            <a href="/my/" class="btn btn-secondary me-2">
                                Discard
                            </a>
                            <button type="submit" class="btn btn-primary float-end">
                                Save
                            </button>
                        </div>
                    </div>
                </div>
            </form>
        </t>
    </t>

    ', false, true, '2026-05-10 01:11:52.573269', '2026-05-10 01:11:52.573269', false);
INSERT INTO public.ir_ui_view VALUES (557, 16, NULL, 1, 1, 'portal_my_security', NULL, 'portal.portal_my_security', 'qweb', 'portal/views/portal_templates.xml', 'primary', '{"en_US": "<t t-name=\"portal.portal_my_security\">\n        <t t-call=\"portal.portal_layout\"><div class=\"o_portal_security_body w-md-75 w-lg-50 pb-5\">\n            <t t-set=\"additional_title\">Security</t>\n            <t t-set=\"no_breadcrumbs\" t-value=\"1\"/>\n            <div class=\"alert alert-danger\" role=\"alert\" t-if=\"get_error(errors)\">\n                <t t-esc=\"errors\"/>\n            </div>\n            <div class=\"d-flex gap-2 my-3\">\n                <a href=\"/my/\" title=\"Go Back\" class=\"btn btn-light px-2\"><i class=\"oi oi-chevron-left\"/></a>\n                <h3 class=\"my-0\">Connection &amp; Security</h3>\n            </div>\n            <section name=\"portal_change_password\">\n                <h4>Change Password</h4>\n                <t t-set=\"path\">password</t>\n                <div class=\"alert alert-success\" role=\"alert\" t-if=\"success and success.get(''password'')\">\n                    Password Updated!\n                </div>\n                <div class=\"alert alert-danger\" role=\"alert\" t-if=\"get_error(errors, ''password'')\">\n                    <t t-esc=\"errors[''password'']\"/>\n                </div>\n                <form action=\"/my/security\" method=\"post\" class=\"oe_reset_password_form\">\n                    <input type=\"hidden\" name=\"csrf_token\" t-att-value=\"request.csrf_token()\"/>\n                    <input type=\"hidden\" name=\"op\" value=\"password\"/>\n                    <div class=\"mb-3\">\n                        <label for=\"current\">Password:</label>\n                        <input type=\"password\" t-attf-class=\"form-control form-control-sm {{ ''is-invalid'' if get_error(errors, ''password.old'') else '''' }}\" id=\"current\" name=\"old\" autocomplete=\"current-password\" required=\"required\"/>\n                        <div class=\"invalid-feedback\">\n                            <t t-esc=\"get_error(errors, ''password.old'')\"/>\n                        </div>\n                    </div>\n                    <div class=\"mb-3\">\n                        <label for=\"new\">New Password:</label>\n                        <input type=\"password\" t-attf-class=\"form-control form-control-sm {{ ''is-invalid'' if get_error(errors, ''password.new1'') else '''' }}\" id=\"new\" name=\"new1\" autocomplete=\"new-password\" required=\"required\"/>\n                        <div class=\"invalid-feedback\">\n                            <t t-esc=\"get_error(errors, ''password.new1'')\"/>\n                        </div>\n                    </div>\n                    <div class=\"mb-3\">\n                        <label for=\"new2\">Verify New Password:</label>\n                        <input type=\"password\" t-attf-class=\"form-control form-control-sm {{ ''is-invalid'' if get_error(errors, ''password.new2'') else '''' }}\" id=\"new2\" name=\"new2\" autocomplete=\"new-password\" required=\"required\"/>\n                        <div class=\"invalid-feedback\">\n                            <t t-esc=\"get_error(errors, ''password.new2'')\"/>\n                        </div>\n                    </div>\n                    <button type=\"submit\" class=\"btn btn-secondary\">Change Password</button>\n                </form>\n            </section>\n            <section name=\"portal_revoke_all_devices_popup\">\n            <h4>Revoke All Sessions</h4>\n                <t t-set=\"path\"/>\n                    <button type=\"button\" class=\"btn btn-secondary\" id=\"portal_revoke_all_sessions_popup\">\n                        Log out from all devices\n                    </button>\n            </section>\n            <section t-if=\"debug and allow_api_keys\">\n                <h4>\n                Developer API Keys\n                    <a href=\"https://www.odoo.com/documentation/17.0/developer/misc/api/external_api.html#api-keys\" target=\"_blank\">\n                        <i title=\"Documentation\" class=\"fa fa-fw o_button_icon fa-info-circle\"/>\n                    </a>\n                </h4>\n                <div>\n                    <table class=\"table o_main_table\">\n                        <thead>\n                            <tr>\n                                <th>Description</th>\n                                <th>Scope</th>\n                                <th>Added On</th>\n                                <th/>\n                            </tr>\n                        </thead>\n                        <tbody>\n                            <t t-foreach=\"request.env.user.api_key_ids\" t-as=\"key\">\n                                <tr>\n                                    <td><span t-field=\"key.name\"/></td>\n                                    <td><span t-field=\"key.scope\"/></td>\n                                    <td><span t-field=\"key.create_date\"/></td>\n                                    <td>\n                                        <i class=\"fa fa-trash text-danger o_portal_remove_api_key\" type=\"button\" t-att-id=\"key.id\"/>\n                                    </td>\n                                </tr>\n                            </t>\n                        </tbody>\n                    </table>\n                </div>\n                <div>\n                    <button type=\"submit\" class=\"btn btn-secondary o_portal_new_api_key\">New API Key</button>\n                </div>\n            </section>\n            <section name=\"portal_deactivate_account\" groups=\"base.group_portal\">\n                <h4>Delete Account</h4>\n                <t t-set=\"deactivate_error\" t-value=\"get_error(errors, ''deactivate'')\"/>\n                <button class=\"btn btn-secondary\" data-bs-toggle=\"modal\" data-bs-target=\"#portal_deactivate_account_modal\">\n                    Delete Account\n                </button>\n                <div t-attf-class=\"modal #{''show d-block'' if open_deactivate_modal else ''''}\" id=\"portal_deactivate_account_modal\" tabindex=\"-1\" role=\"dialog\">\n                    <div class=\"modal-dialog\" role=\"document\">\n                        <div class=\"modal-content\">\n                            <div class=\"modal-header bg-danger\">\n                                <h5 class=\"modal-title\">Are you sure you want to do this?</h5>\n                                <button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"modal\"/>\n                            </div>\n                            <form action=\"/my/deactivate_account\" method=\"post\" class=\"modal-body\" id=\"portal_deactivate_account_form\">\n                                <div>\n                                    <div class=\"alert alert-danger\" t-esc=\"get_error(errors, ''deactivate.other'')\"/>\n                                    <p class=\"text-muted\">\n                                        Disable your account, preventing any further login.<br/>\n                                        <b>\n                                            <i class=\"fa fa-exclamation-triangle text-danger\"/>\n                                            This action cannot be undone.\n                                        </b>\n                                    </p>\n                                    <hr/>\n                                    <p>1. Enter your password to confirm you own this account</p>\n                                    <input name=\"password\" type=\"password\" required=\"1\" t-attf-class=\"form-control #{''is-invalid'' if deactivate_error == ''password'' else ''''}\" placeholder=\"Password\"/>\n                                    <div t-if=\"deactivate_error == ''password''\" class=\"invalid-feedback\">\n                                        Wrong password.\n                                    </div>\n                                    <hr/>\n                                    <p>\n                                        2. Confirm you want to delete your account by\n                                        copying down your login (<t t-esc=\"env.user.login\"/>).\n                                    </p>\n                                    <input name=\"validation\" type=\"text\" required=\"1\" t-attf-class=\"form-control #{''is-invalid'' if deactivate_error == ''validation'' else ''''}\"/>\n                                    <div t-if=\"deactivate_error == ''validation''\" class=\"invalid-feedback\">\n                                        You should enter \"<t t-esc=\"env.user.login\"/>\" to validate your action.\n                                    </div>\n                                    <div class=\"d-flex flex-row align-items-center\">\n                                        <input type=\"checkbox\" name=\"request_blacklist\" id=\"request_blacklist\" checked=\"1\"/>\n                                        <label for=\"request_blacklist\" class=\"ms-2 mw-100 fw-normal mt-3\">\n                                            Put my email and phone in a block list to make sure I''m never contacted again\n                                        </label>\n                                    </div>\n                                </div>\n                                <input type=\"hidden\" name=\"csrf_token\" t-att-value=\"request.csrf_token()\"/>\n                            </form>\n                            <div class=\"modal-footer justify-content-start\">\n                                <input type=\"submit\" class=\"btn btn-danger\" form=\"portal_deactivate_account_form\" value=\"Delete Account\"/>\n                                <button type=\"button\" class=\"btn\" data-bs-dismiss=\"modal\">\n                                    Cancel\n                                </button>\n                            </div>\n                        </div>\n                    </div>\n                </div>\n            </section>\n        </div></t>\n    </t>"}', '<?xml version="1.0"?>
<t t-name="portal.portal_my_security">
        <t t-call="portal.portal_layout"><div class="o_portal_security_body w-md-75 w-lg-50 pb-5">
            <t t-set="additional_title">Security</t>
            <t t-set="no_breadcrumbs" t-value="1"/>
            <div class="alert alert-danger" role="alert" t-if="get_error(errors)">
                <t t-esc="errors"/>
            </div>
            <div class="d-flex gap-2 my-3">
                <a href="/my/" title="Go Back" class="btn btn-light px-2"><i class="oi oi-chevron-left"/></a>
                <h3 class="my-0">Connection &amp; Security</h3>
            </div>
            <section name="portal_change_password">
                <h4>Change Password</h4>
                <t t-set="path">password</t>
                <div class="alert alert-success" role="alert" t-if="success and success.get(''password'')">
                    Password Updated!
                </div>
                <div class="alert alert-danger" role="alert" t-if="get_error(errors, ''password'')">
                    <t t-esc="errors[''password'']"/>
                </div>
                <form action="/my/security" method="post" class="oe_reset_password_form">
                    <input type="hidden" name="csrf_token" t-att-value="request.csrf_token()"/>
                    <input type="hidden" name="op" value="password"/>
                    <div class="mb-3">
                        <label for="current">Password:</label>
                        <input type="password" t-attf-class="form-control form-control-sm {{ ''is-invalid'' if get_error(errors, ''password.old'') else '''' }}" id="current" name="old" autocomplete="current-password" required="required"/>
                        <div class="invalid-feedback">
                            <t t-esc="get_error(errors, ''password.old'')"/>
                        </div>
                    </div>
                    <div class="mb-3">
                        <label for="new">New Password:</label>
                        <input type="password" t-attf-class="form-control form-control-sm {{ ''is-invalid'' if get_error(errors, ''password.new1'') else '''' }}" id="new" name="new1" autocomplete="new-password" required="required"/>
                        <div class="invalid-feedback">
                            <t t-esc="get_error(errors, ''password.new1'')"/>
                        </div>
                    </div>
                    <div class="mb-3">
                        <label for="new2">Verify New Password:</label>
                        <input type="password" t-attf-class="form-control form-control-sm {{ ''is-invalid'' if get_error(errors, ''password.new2'') else '''' }}" id="new2" name="new2" autocomplete="new-password" required="required"/>
                        <div class="invalid-feedback">
                            <t t-esc="get_error(errors, ''password.new2'')"/>
                        </div>
                    </div>
                    <button type="submit" class="btn btn-secondary">Change Password</button>
                </form>
            </section>
            <section name="portal_revoke_all_devices_popup">
            <h4>Revoke All Sessions</h4>
                <t t-set="path"/>
                    <button type="button" class="btn btn-secondary" id="portal_revoke_all_sessions_popup">
                        Log out from all devices
                    </button>
            </section>
            <section t-if="debug and allow_api_keys">
                <h4>
                Developer API Keys
                    <a href="https://www.odoo.com/documentation/17.0/developer/misc/api/external_api.html#api-keys" target="_blank">
                        <i title="Documentation" class="fa fa-fw o_button_icon fa-info-circle"/>
                    </a>
                </h4>
                <div>
                    <table class="table o_main_table">
                        <thead>
                            <tr>
                                <th>Description</th>
                                <th>Scope</th>
                                <th>Added On</th>
                                <th/>
                            </tr>
                        </thead>
                        <tbody>
                            <t t-foreach="request.env.user.api_key_ids" t-as="key">
                                <tr>
                                    <td><span t-field="key.name"/></td>
                                    <td><span t-field="key.scope"/></td>
                                    <td><span t-field="key.create_date"/></td>
                                    <td>
                                        <i class="fa fa-trash text-danger o_portal_remove_api_key" type="button" t-att-id="key.id"/>
                                    </td>
                                </tr>
                            </t>
                        </tbody>
                    </table>
                </div>
                <div>
                    <button type="submit" class="btn btn-secondary o_portal_new_api_key">New API Key</button>
                </div>
            </section>
            <section name="portal_deactivate_account" groups="base.group_portal">
                <h4>Delete Account</h4>
                <t t-set="deactivate_error" t-value="get_error(errors, ''deactivate'')"/>
                <button class="btn btn-secondary" data-bs-toggle="modal" data-bs-target="#portal_deactivate_account_modal">
                    Delete Account
                </button>
                <div t-attf-class="modal #{''show d-block'' if open_deactivate_modal else ''''}" id="portal_deactivate_account_modal" tabindex="-1" role="dialog">
                    <div class="modal-dialog" role="document">
                        <div class="modal-content">
                            <div class="modal-header bg-danger">
                                <h5 class="modal-title">Are you sure you want to do this?</h5>
                                <button type="button" class="btn-close" data-bs-dismiss="modal"/>
                            </div>
                            <form action="/my/deactivate_account" method="post" class="modal-body" id="portal_deactivate_account_form">
                                <div>
                                    <div class="alert alert-danger" t-esc="get_error(errors, ''deactivate.other'')"/>
                                    <p class="text-muted">
                                        Disable your account, preventing any further login.<br/>
                                        <b>
                                            <i class="fa fa-exclamation-triangle text-danger"/>
                                            This action cannot be undone.
                                        </b>
                                    </p>
                                    <hr/>
                                    <p>1. Enter your password to confirm you own this account</p>
                                    <input name="password" type="password" required="1" t-attf-class="form-control #{''is-invalid'' if deactivate_error == ''password'' else ''''}" placeholder="Password"/>
                                    <div t-if="deactivate_error == ''password''" class="invalid-feedback">
                                        Wrong password.
                                    </div>
                                    <hr/>
                                    <p>
                                        2. Confirm you want to delete your account by
                                        copying down your login (<t t-esc="env.user.login"/>).
                                    </p>
                                    <input name="validation" type="text" required="1" t-attf-class="form-control #{''is-invalid'' if deactivate_error == ''validation'' else ''''}"/>
                                    <div t-if="deactivate_error == ''validation''" class="invalid-feedback">
                                        You should enter "<t t-esc="env.user.login"/>" to validate your action.
                                    </div>
                                    <div class="d-flex flex-row align-items-center">
                                        <input type="checkbox" name="request_blacklist" id="request_blacklist" checked="1"/>
                                        <label for="request_blacklist" class="ms-2 mw-100 fw-normal mt-3">
                                            Put my email and phone in a block list to make sure I''m never contacted again
                                        </label>
                                    </div>
                                </div>
                                <input type="hidden" name="csrf_token" t-att-value="request.csrf_token()"/>
                            </form>
                            <div class="modal-footer justify-content-start">
                                <input type="submit" class="btn btn-danger" form="portal_deactivate_account_form" value="Delete Account"/>
                                <button type="button" class="btn" data-bs-dismiss="modal">
                                    Cancel
                                </button>
                            </div>
                        </div>
                    </div>
                </div>
            </section>
        </div></t>
    </t>

    ', false, true, '2026-05-10 01:11:52.573269', '2026-05-10 01:11:52.573269', false);
INSERT INTO public.ir_ui_view VALUES (558, 16, NULL, 1, 1, 'Portal Record Pager', NULL, 'portal.record_pager', 'qweb', 'portal/views/portal_templates.xml', 'primary', '{"en_US": "<t name=\"Portal Record Pager\" t-name=\"portal.record_pager\">\n        <t t-if=\"prev_record or next_record\">\n            <div class=\"record_pager btn-group\" role=\"group\">\n                <a role=\"button\" t-att-class=\"''btn btn-light %s'' % (''disabled'' if not prev_record else '''')\" t-att-href=\"prev_record or ''#''\"><i class=\"oi oi-chevron-left\" role=\"img\" aria-label=\"Previous\" title=\"Previous\"/></a>\n                <a role=\"button\" t-att-class=\"''btn btn-light %s'' % (''disabled'' if not next_record else '''')\" t-att-href=\"next_record or ''#''\"><i class=\"oi oi-chevron-right\" role=\"img\" aria-label=\"Next\" title=\"Next\"/></a>\n            </div>\n        </t>\n    </t>"}', '<?xml version="1.0"?>
<t name="Portal Record Pager" t-name="portal.record_pager">
        <t t-if="prev_record or next_record">
            <div class="record_pager btn-group" role="group">
                <a role="button" t-att-class="''btn btn-light %s'' % (''disabled'' if not prev_record else '''')" t-att-href="prev_record or ''#''"><i class="oi oi-chevron-left" role="img" aria-label="Previous" title="Previous"/></a>
                <a role="button" t-att-class="''btn btn-light %s'' % (''disabled'' if not next_record else '''')" t-att-href="next_record or ''#''"><i class="oi oi-chevron-right" role="img" aria-label="Next" title="Next"/></a>
            </div>
        </t>
    </t>

    ', false, true, '2026-05-10 01:11:52.573269', '2026-05-10 01:11:52.573269', false);
INSERT INTO public.ir_ui_view VALUES (559, 16, NULL, 1, 1, 'Pager', NULL, 'portal.pager', 'qweb', 'portal/views/portal_templates.xml', 'primary', '{"en_US": "<t name=\"Pager\" t-name=\"portal.pager\">\n        <ul t-if=\"pager[''page_count''] &gt; 1\" t-attf-class=\"#{ classname or '''' } pagination m-0 #{_classes}\" t-att-style=\"style or None\">\n            <li t-attf-class=\"page-item #{''disabled'' if pager[''page''][''num''] == 1 else ''''}\">\n                <a t-att-href=\" pager[''page_previous''][''url''] if pager[''page''][''num''] != 1 else None\" t-attf-class=\"page-link #{extraLinkClass}\">\n                    <span class=\"fa fa-chevron-left\" role=\"img\" aria-label=\"Previous\" title=\"Previous\"/>\n                </a>\n            </li>\n            <t t-foreach=\"pager[''pages'']\" t-as=\"page\">\n                <li t-attf-class=\"page-item #{''active'' if page[''num''] == pager[''page''][''num''] else ''''}\"> <a t-att-href=\"page[''url'']\" t-attf-class=\"page-link #{extraLinkClass}\" t-out=\"page[''num'']\"/></li>\n            </t>\n            <li t-attf-class=\"page-item #{''disabled'' if pager[''page''][''num''] == pager[''page_count''] else ''''}\">\n                <a t-att-href=\"pager[''page_next''][''url''] if pager[''page''][''num''] != pager[''page_count''] else None\" t-attf-class=\"page-link #{extraLinkClass}\">\n                    <span class=\"fa fa-chevron-right\" role=\"img\" aria-label=\"Next\" title=\"Next\"/>\n                </a>\n            </li>\n        </ul>\n    </t>"}', '<?xml version="1.0"?>
<t name="Pager" t-name="portal.pager">
        <ul t-if="pager[''page_count''] &gt; 1" t-attf-class="#{ classname or '''' } pagination m-0 #{_classes}" t-att-style="style or None">
            <li t-attf-class="page-item #{''disabled'' if pager[''page''][''num''] == 1 else ''''}">
                <a t-att-href=" pager[''page_previous''][''url''] if pager[''page''][''num''] != 1 else None" t-attf-class="page-link #{extraLinkClass}">
                    <span class="fa fa-chevron-left" role="img" aria-label="Previous" title="Previous"/>
                </a>
            </li>
            <t t-foreach="pager[''pages'']" t-as="page">
                <li t-attf-class="page-item #{''active'' if page[''num''] == pager[''page''][''num''] else ''''}"> <a t-att-href="page[''url'']" t-attf-class="page-link #{extraLinkClass}" t-out="page[''num'']"/></li>
            </t>
            <li t-attf-class="page-item #{''disabled'' if pager[''page''][''num''] == pager[''page_count''] else ''''}">
                <a t-att-href="pager[''page_next''][''url''] if pager[''page''][''num''] != pager[''page_count''] else None" t-attf-class="page-link #{extraLinkClass}">
                    <span class="fa fa-chevron-right" role="img" aria-label="Next" title="Next"/>
                </a>
            </li>
        </ul>
    </t>

    ', false, true, '2026-05-10 01:11:52.573269', '2026-05-10 01:11:52.573269', false);
INSERT INTO public.ir_ui_view VALUES (560, 16, 541, 1, 1, 'Link to frontend portal', NULL, 'portal.my_account_link', 'qweb', 'portal/views/portal_templates.xml', 'extension', '{"en_US": "<data name=\"Link to frontend portal\" inherit_id=\"portal.user_dropdown\">\n        <xpath expr=\"//*[@id=''o_logout_divider'']\" position=\"before\">\n            <a href=\"/my/home\" role=\"menuitem\" class=\"dropdown-item ps-3\">\n                <i class=\"fa fa-fw fa-id-card-o me-1 small text-primary\"/> My Account\n            </a>\n        </xpath>\n    </data>"}', '<?xml version="1.0"?>
<data name="Link to frontend portal" inherit_id="portal.user_dropdown">
        <xpath expr="//*[@id=''o_logout_divider'']" position="before">
            <a href="/my/home" role="menuitem" class="dropdown-item ps-3">
                <i class="fa fa-fw fa-id-card-o me-1 small text-primary"/> My Account
            </a>
        </xpath>
    </data>

    ', false, true, '2026-05-10 01:11:52.573269', '2026-05-10 01:11:52.573269', false);
INSERT INTO public.ir_ui_view VALUES (564, 16, NULL, 1, 1, 'side_content', NULL, 'portal.side_content', 'qweb', 'portal/views/portal_templates.xml', 'primary', '{"en_US": "<t t-name=\"portal.side_content\">\n        <div t-if=\"isOffcanvas\" class=\"offcanvas-header justify-content-end\">\n            <button type=\"button\" class=\"btn-close text-reset\" data-bs-dismiss=\"offcanvas\" aria-label=\"Close\"/>\n        </div>\n        <div t-attf-class=\"{{''offcanvas-body'' if isOffcanvas else ''mt-3''}}\">\n            <div class=\"d-flex justify-content-start align-items-center gap-3 mb-4\">\n                <img class=\"o_portal_contact_img rounded o_object_fit_cover\" t-att-src=\"image_data_uri(user_id.partner_id.avatar_128)\" alt=\"Contact\" width=\"50\"/>\n                <div class=\"d-flex flex-column justify-content-center\">\n                    <h5 class=\"mb-0\" t-out=\"user_id.name\"/>\n                    <p class=\"mb-0 text-muted\" t-out=\"user_id.company_name\"/>\n                </div>\n            </div>\n            <div class=\"o_portal_my_details\">\n                <div t-field=\"user_id.partner_id\" t-options=\"{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;email&quot;, &quot;phone&quot;, &quot;address&quot;]}\"/>\n            </div>\n            <a role=\"button\" href=\"/my/account\" class=\"btn btn-link p-0 mt-3\"><i class=\"fa fa-pencil\"/> Edit information</a>\n            <hr t-if=\"sales_user\"/>\n            <div class=\"o_my_contact\" t-if=\"sales_user\">\n                <t t-call=\"portal.portal_contact\"/>\n            </div>\n        </div>\n    </t>"}', '<?xml version="1.0"?>
<t t-name="portal.side_content">
        <div t-if="isOffcanvas" class="offcanvas-header justify-content-end">
            <button type="button" class="btn-close text-reset" data-bs-dismiss="offcanvas" aria-label="Close"/>
        </div>
        <div t-attf-class="{{''offcanvas-body'' if isOffcanvas else ''mt-3''}}">
            <div class="d-flex justify-content-start align-items-center gap-3 mb-4">
                <img class="o_portal_contact_img rounded o_object_fit_cover" t-att-src="image_data_uri(user_id.partner_id.avatar_128)" alt="Contact" width="50"/>
                <div class="d-flex flex-column justify-content-center">
                    <h5 class="mb-0" t-out="user_id.name"/>
                    <p class="mb-0 text-muted" t-out="user_id.company_name"/>
                </div>
            </div>
            <div class="o_portal_my_details">
                <div t-field="user_id.partner_id" t-options="{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;email&quot;, &quot;phone&quot;, &quot;address&quot;]}"/>
            </div>
            <a role="button" href="/my/account" class="btn btn-link p-0 mt-3"><i class="fa fa-pencil"/> Edit information</a>
            <hr t-if="sales_user"/>
            <div class="o_my_contact" t-if="sales_user">
                <t t-call="portal.portal_contact"/>
            </div>
        </div>
    </t>
', false, true, '2026-05-10 01:11:52.573269', '2026-05-10 01:11:52.573269', false);
INSERT INTO public.ir_ui_view VALUES (565, 40, 223, 1, 1, 'res.config.settings.view.form.inherit.portal', 'res.config.settings', NULL, 'form', 'portal/views/res_config_settings_views.xml', 'extension', '{"en_US": "<xpath expr=\"//button[@name=72]//ancestor::setting\" position=\"inside\">\n                    <div groups=\"base.group_no_one\">\n                        <div class=\"mt16 content-group\">\n                            <field name=\"portal_allow_api_keys\"/>\n                            <label string=\"Customers can generate API Keys\" for=\"portal_allow_api_keys\"/>\n                        </div>\n                    </div>\n                </xpath>"}', '<?xml version="1.0"?>
<xpath expr="//button[@name=72]//ancestor::setting" position="inside">
                    <div groups="base.group_no_one">
                        <div class="mt16 content-group">
                            <field name="portal_allow_api_keys"/>
                            <label string="Customers can generate API Keys" for="portal_allow_api_keys"/>
                        </div>
                    </div>
                </xpath>
            ', false, true, '2026-05-10 01:11:52.573269', '2026-05-10 01:11:52.573269', false);
INSERT INTO public.ir_ui_view VALUES (566, 16, NULL, 1, 1, 'portal.share.wizard', 'portal.share', NULL, 'form', 'portal/wizard/portal_share_views.xml', 'primary', '{"en_US": "<form string=\"Share Document\">\n                <p class=\"alert alert-warning\" invisible=\"access_warning == ''''\" role=\"alert\"><field name=\"access_warning\"/></p>\n                <group name=\"share_link\">\n                    <field name=\"res_model\" invisible=\"1\"/>\n                    <field name=\"res_id\" invisible=\"1\"/>\n                    <field name=\"share_link\" widget=\"CopyClipboardChar\" options=\"{''string'': ''Copy Link''}\"/>\n                    <field name=\"partner_ids\" widget=\"many2many_tags_email\" placeholder=\"Add contacts to share the document...\"/>\n                    <field name=\"note\" placeholder=\"Add a note\"/>\n                </group>\n                <footer>\n                    <button string=\"Send\" name=\"action_send_mail\" invisible=\"access_warning != ''''\" type=\"object\" class=\"btn-primary\" data-hotkey=\"q\"/>\n                    <button string=\"Cancel\" class=\"btn-default\" special=\"cancel\" data-hotkey=\"x\"/>\n                </footer>\n            </form>"}', '<?xml version="1.0"?>
<form string="Share Document">
                <p class="alert alert-warning" invisible="access_warning == ''''" role="alert"><field name="access_warning"/></p>
                <group name="share_link">
                    <field name="res_model" invisible="1"/>
                    <field name="res_id" invisible="1"/>
                    <field name="share_link" widget="CopyClipboardChar" options="{''string'': ''Copy Link''}"/>
                    <field name="partner_ids" widget="many2many_tags_email" placeholder="Add contacts to share the document..."/>
                    <field name="note" placeholder="Add a note"/>
                </group>
                <footer>
                    <button string="Send" name="action_send_mail" invisible="access_warning != ''''" type="object" class="btn-primary" data-hotkey="q"/>
                    <button string="Cancel" class="btn-default" special="cancel" data-hotkey="x"/>
                </footer>
            </form>
        ', false, true, '2026-05-10 01:11:52.573269', '2026-05-10 01:11:52.573269', false);
INSERT INTO public.ir_ui_view VALUES (567, 16, NULL, 1, 1, 'Grant portal access', 'portal.wizard', NULL, 'form', 'portal/wizard/portal_wizard_views.xml', 'primary', '{"en_US": "<form string=\"Portal Access Management\">\n                    <div class=\"mb-3\">\n                        Select which contacts should belong to the portal in the list below.\n                        The email address of each selected contact must be valid and unique.\n                        If necessary, you can fix any contact''s email address directly in the list.\n                    </div>\n                    <field name=\"welcome_message\" placeholder=\"This text is included at the end of the email sent to new portal users.\" class=\"mb-3\"/>\n                    <field name=\"user_ids\" class=\"o_portal_wizard_user_one2many\" widget=\"portal_wizard_user_one2many\">\n                        <tree string=\"Contacts\" editable=\"bottom\" create=\"false\" delete=\"false\">\n                            <field name=\"partner_id\" force_save=\"1\"/>\n                            <field name=\"email\" readonly=\"is_internal\"/>\n                            <field name=\"email_state\" column_invisible=\"True\"/>\n                            <button name=\"action_refresh_modal\" type=\"object\" icon=\"fa-check text-success\" invisible=\"email_state != ''ok''\" title=\"Valid Email Address\"/>\n                            <button name=\"action_refresh_modal\" type=\"object\" icon=\"fa-times text-danger\" invisible=\"email_state != ''ko''\" title=\"Invalid Email Address\"/>\n                            <button name=\"action_refresh_modal\" type=\"object\" icon=\"fa-user-times text-danger\" invisible=\"email_state != ''exist''\" title=\"Email Address already taken by another user\"/>\n                            <field name=\"login_date\"/>\n                            <field name=\"is_portal\" column_invisible=\"True\"/>\n                            <field name=\"is_internal\" column_invisible=\"True\"/>\n                            <button string=\"Grant Access\" name=\"action_grant_access\" type=\"object\" class=\"btn-secondary\" invisible=\"is_portal or is_internal or email_state != ''ok''\"/>\n                            <button string=\"Revoke Access\" name=\"action_revoke_access\" type=\"object\" class=\"btn-secondary\" invisible=\"not is_portal or is_internal\"/>\n                            <button string=\"Re-Invite\" name=\"action_invite_again\" type=\"object\" class=\"btn-secondary\" invisible=\"not is_portal or is_internal or email_state != ''ok''\"/>\n                            <button string=\"Internal User\" invisible=\"not is_internal\" disabled=\"True\" title=\"This partner is linked to an internal User and already has access to the Portal.\"/>\n                        </tree>\n                    </field>\n                    <footer>\n                        <button string=\"Close\" class=\"btn-primary\" special=\"save\" data-hotkey=\"v\"/>\n                    </footer>\n                </form>"}', '<?xml version="1.0"?>
<form string="Portal Access Management">
                    <div class="mb-3">
                        Select which contacts should belong to the portal in the list below.
                        The email address of each selected contact must be valid and unique.
                        If necessary, you can fix any contact''s email address directly in the list.
                    </div>
                    <field name="welcome_message" placeholder="This text is included at the end of the email sent to new portal users." class="mb-3"/>
                    <field name="user_ids" class="o_portal_wizard_user_one2many" widget="portal_wizard_user_one2many">
                        <tree string="Contacts" editable="bottom" create="false" delete="false">
                            <field name="partner_id" force_save="1"/>
                            <field name="email" readonly="is_internal"/>
                            <field name="email_state" column_invisible="True"/>
                            <button name="action_refresh_modal" type="object" icon="fa-check text-success" invisible="email_state != ''ok''" title="Valid Email Address"/>
                            <button name="action_refresh_modal" type="object" icon="fa-times text-danger" invisible="email_state != ''ko''" title="Invalid Email Address"/>
                            <button name="action_refresh_modal" type="object" icon="fa-user-times text-danger" invisible="email_state != ''exist''" title="Email Address already taken by another user"/>
                            <field name="login_date"/>
                            <field name="is_portal" column_invisible="True"/>
                            <field name="is_internal" column_invisible="True"/>
                            <button string="Grant Access" name="action_grant_access" type="object" class="btn-secondary" invisible="is_portal or is_internal or email_state != ''ok''"/>
                            <button string="Revoke Access" name="action_revoke_access" type="object" class="btn-secondary" invisible="not is_portal or is_internal"/>
                            <button string="Re-Invite" name="action_invite_again" type="object" class="btn-secondary" invisible="not is_portal or is_internal or email_state != ''ok''"/>
                            <button string="Internal User" invisible="not is_internal" disabled="True" title="This partner is linked to an internal User and already has access to the Portal."/>
                        </tree>
                    </field>
                    <footer>
                        <button string="Close" class="btn-primary" special="save" data-hotkey="v"/>
                    </footer>
                </form>
            ', false, true, '2026-05-10 01:11:52.573269', '2026-05-10 01:11:52.573269', false);
INSERT INTO public.ir_ui_view VALUES (568, 16, NULL, 1, 1, 'sms.composer.view.form', 'sms.composer', NULL, 'form', 'sms/wizard/sms_composer_views.xml', 'primary', '{"en_US": "<form string=\"Send an SMS\">\n                <!-- Single mode information (invalid number) -->\n                <div class=\"alert alert-danger text-center\" role=\"alert\" invisible=\"not res_model_description or not comment_single_recipient or recipient_single_valid\">\n                    <p class=\"my-0\">\n                        <strong>Invalid number:</strong>\n                        <span> make sure to set a country on the </span>\n                        <span><field name=\"res_model_description\"/></span>\n                        <span> or to specify the country code.</span>\n                    </p>\n                </div>\n\n                <!-- Mass mode information (res_ids versus active domain) -->\n                <div class=\"alert alert-info text-center\" role=\"alert\" invisible=\"comment_single_recipient or recipient_invalid_count == 0\">\n                    <p class=\"my-0\">\n                        <field class=\"oe_inline fw-bold\" name=\"recipient_invalid_count\"/> out of\n                        <field class=\"oe_inline fw-bold\" name=\"res_ids_count\"/> recipients have an invalid phone number and will not receive this text message.\n                    </p>\n                </div>\n                <sheet>\n                    <group>\n                        <field name=\"composition_mode\" invisible=\"1\"/>\n                        <field name=\"comment_single_recipient\" invisible=\"1\"/>\n                        <field name=\"res_id\" invisible=\"1\"/>\n                        <field name=\"res_ids\" invisible=\"1\"/>\n                        <field name=\"res_model\" invisible=\"1\"/>\n                        <field name=\"mass_force_send\" invisible=\"1\"/>\n                        <field name=\"recipient_single_valid\" invisible=\"1\"/>\n                        <field name=\"recipient_single_number\" invisible=\"1\"/>\n                        <field name=\"number_field_name\" invisible=\"1\"/>\n                        <field name=\"numbers\" invisible=\"1\"/>\n                        <field name=\"sanitized_numbers\" invisible=\"1\"/>\n                        <field name=\"template_id\" invisible=\"1\"/>\n\n                        <label for=\"recipient_single_description\" string=\"Recipient\" class=\"fw-bold\" invisible=\"not comment_single_recipient\"/>\n                        <div invisible=\"not comment_single_recipient\">\n                            <field name=\"recipient_single_description\" class=\"oe_inline\" invisible=\"not recipient_single_description\"/>\n                            <field name=\"recipient_single_number_itf\" class=\"oe_inline\" nolabel=\"1\" onchange_on_keydown=\"True\" placeholder=\"e.g. +1 415 555 0100\"/>\n                        </div>\n                        <field name=\"body\" widget=\"sms_widget\" invisible=\"not comment_single_recipient or recipient_single_valid\"/>\n                        <field name=\"body\" widget=\"sms_widget\" invisible=\"comment_single_recipient and not recipient_single_valid\" default_focus=\"1\"/>\n                        <field name=\"mass_keep_log\" invisible=\"1\"/>\n                    </group>\n                </sheet>\n                <footer>\n                    <!-- attrs doesn''t work for ''disabled''-->\n                    <button string=\"Send SMS\" type=\"object\" class=\"oe_highlight\" name=\"action_send_sms\" data-hotkey=\"q\" invisible=\"composition_mode not in (''comment'', ''numbers'') or not recipient_single_valid\"/>\n                    <button string=\"Send SMS\" type=\"object\" class=\"oe_highlight\" name=\"action_send_sms\" data-hotkey=\"q\" invisible=\"composition_mode not in (''comment'', ''numbers'') or recipient_single_valid\" disabled=\"1\"/>\n                    <button string=\"Put in queue\" type=\"object\" class=\"oe_highlight\" name=\"action_send_sms\" data-hotkey=\"q\" invisible=\"composition_mode != ''mass''\"/>\n                    <button string=\"Send Now\" type=\"object\" name=\"action_send_sms_mass_now\" data-hotkey=\"w\" invisible=\"composition_mode != ''mass''\"/>\n                    <button string=\"Close\" class=\"btn btn-secondary\" special=\"cancel\" data-hotkey=\"x\"/>\n                </footer>\n            </form>"}', '<?xml version="1.0"?>
<form string="Send an SMS">
                <!-- Single mode information (invalid number) -->
                <div class="alert alert-danger text-center" role="alert" invisible="not res_model_description or not comment_single_recipient or recipient_single_valid">
                    <p class="my-0">
                        <strong>Invalid number:</strong>
                        <span> make sure to set a country on the </span>
                        <span><field name="res_model_description"/></span>
                        <span> or to specify the country code.</span>
                    </p>
                </div>

                <!-- Mass mode information (res_ids versus active domain) -->
                <div class="alert alert-info text-center" role="alert" invisible="comment_single_recipient or recipient_invalid_count == 0">
                    <p class="my-0">
                        <field class="oe_inline fw-bold" name="recipient_invalid_count"/> out of
                        <field class="oe_inline fw-bold" name="res_ids_count"/> recipients have an invalid phone number and will not receive this text message.
                    </p>
                </div>
                <sheet>
                    <group>
                        <field name="composition_mode" invisible="1"/>
                        <field name="comment_single_recipient" invisible="1"/>
                        <field name="res_id" invisible="1"/>
                        <field name="res_ids" invisible="1"/>
                        <field name="res_model" invisible="1"/>
                        <field name="mass_force_send" invisible="1"/>
                        <field name="recipient_single_valid" invisible="1"/>
                        <field name="recipient_single_number" invisible="1"/>
                        <field name="number_field_name" invisible="1"/>
                        <field name="numbers" invisible="1"/>
                        <field name="sanitized_numbers" invisible="1"/>
                        <field name="template_id" invisible="1"/>

                        <label for="recipient_single_description" string="Recipient" class="fw-bold" invisible="not comment_single_recipient"/>
                        <div invisible="not comment_single_recipient">
                            <field name="recipient_single_description" class="oe_inline" invisible="not recipient_single_description"/>
                            <field name="recipient_single_number_itf" class="oe_inline" nolabel="1" onchange_on_keydown="True" placeholder="e.g. +1 415 555 0100"/>
                        </div>
                        <field name="body" widget="sms_widget" invisible="not comment_single_recipient or recipient_single_valid"/>
                        <field name="body" widget="sms_widget" invisible="comment_single_recipient and not recipient_single_valid" default_focus="1"/>
                        <field name="mass_keep_log" invisible="1"/>
                    </group>
                </sheet>
                <footer>
                    <!-- attrs doesn''t work for ''disabled''-->
                    <button string="Send SMS" type="object" class="oe_highlight" name="action_send_sms" data-hotkey="q" invisible="composition_mode not in (''comment'', ''numbers'') or not recipient_single_valid"/>
                    <button string="Send SMS" type="object" class="oe_highlight" name="action_send_sms" data-hotkey="q" invisible="composition_mode not in (''comment'', ''numbers'') or recipient_single_valid" disabled="1"/>
                    <button string="Put in queue" type="object" class="oe_highlight" name="action_send_sms" data-hotkey="q" invisible="composition_mode != ''mass''"/>
                    <button string="Send Now" type="object" name="action_send_sms_mass_now" data-hotkey="w" invisible="composition_mode != ''mass''"/>
                    <button string="Close" class="btn btn-secondary" special="cancel" data-hotkey="x"/>
                </footer>
            </form>
        ', false, true, '2026-05-10 01:11:52.961149', '2026-05-10 01:11:52.961149', false);
INSERT INTO public.ir_ui_view VALUES (713, 16, NULL, 1, 1, 'account.tax.search.filters', 'account.tax', NULL, 'search', 'account/views/account_tax_views.xml', 'primary', '{"en_US": "<search string=\"Search Taxes\">\n                    <field name=\"name\" filter_domain=\"[''|'', ''|'', (''name'', ''ilike'', self), (''description'', ''ilike'', self), (''invoice_label'', ''ilike'', self)]\" string=\"Tax\"/>\n                    <field name=\"company_id\" groups=\"base.group_multi_company\"/>\n                </search>"}', '<?xml version="1.0"?>
<search string="Search Taxes">
                    <field name="name" filter_domain="[''|'', ''|'', (''name'', ''ilike'', self), (''description'', ''ilike'', self), (''invoice_label'', ''ilike'', self)]" string="Tax"/>
                    <field name="company_id" groups="base.group_multi_company"/>
                </search>
            ', false, true, '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295', false);
INSERT INTO public.ir_ui_view VALUES (569, 16, NULL, 1, 1, 'sms.template.preview.form', 'sms.template.preview', NULL, 'form', 'sms/wizard/sms_template_preview_views.xml', 'primary', '{"en_US": "<form string=\"SMS Preview\">\n                    <h3>Preview of <field name=\"sms_template_id\" readonly=\"1\" nolabel=\"1\" class=\"oe_inline\"/></h3>\n                    <field name=\"no_record\" invisible=\"1\"/>\n                    <div class=\"o_row\">\n                        <span>Choose an example <field name=\"model_id\" readonly=\"1\"/> record:</span>\n                        <div>\n                            <field name=\"resource_ref\" class=\"oe_inline\" options=\"{''hide_model'': True, ''no_create'': True, ''no_open'': True}\" invisible=\"no_record\"/>\n                            <span class=\"text-warning\" invisible=\"not no_record\">No records</span>\n                        </div>\n                    </div>\n                    <p>Choose a language: <field name=\"lang\" class=\"oe_inline ml8\"/></p>\n                    <label for=\"body\" string=\"SMS content\"/>\n                    <hr/>\n                        <field name=\"body\" readonly=\"1\" nolabel=\"1\" options=\"{&quot;safe&quot;: True}\"/>\n                    <hr/>\n                    <footer>\n                        <button string=\"Discard\" class=\"btn-secondary\" special=\"cancel\" data-hotkey=\"x\"/>\n                    </footer>\n                </form>"}', '<?xml version="1.0"?>
<form string="SMS Preview">
                    <h3>Preview of <field name="sms_template_id" readonly="1" nolabel="1" class="oe_inline"/></h3>
                    <field name="no_record" invisible="1"/>
                    <div class="o_row">
                        <span>Choose an example <field name="model_id" readonly="1"/> record:</span>
                        <div>
                            <field name="resource_ref" class="oe_inline" options="{''hide_model'': True, ''no_create'': True, ''no_open'': True}" invisible="no_record"/>
                            <span class="text-warning" invisible="not no_record">No records</span>
                        </div>
                    </div>
                    <p>Choose a language: <field name="lang" class="oe_inline ml8"/></p>
                    <label for="body" string="SMS content"/>
                    <hr/>
                        <field name="body" readonly="1" nolabel="1" options="{&quot;safe&quot;: True}"/>
                    <hr/>
                    <footer>
                        <button string="Discard" class="btn-secondary" special="cancel" data-hotkey="x"/>
                    </footer>
                </form>
            ', false, true, '2026-05-10 01:11:52.961149', '2026-05-10 01:11:52.961149', false);
INSERT INTO public.ir_ui_view VALUES (570, 16, NULL, 1, 1, 'sms.resend.form', 'sms.resend', NULL, 'form', 'sms/wizard/sms_resend_views.xml', 'primary', '{"en_US": "<form string=\"Edit Partners\">\n                <field name=\"mail_message_id\" invisible=\"1\"/>\n                <field name=\"can_resend\" invisible=\"1\"/>\n                <field name=\"has_insufficient_credit\" invisible=\"1\"/>\n                <field name=\"has_unregistered_account\" invisible=\"1\"/>\n                <field name=\"recipient_ids\">\n                    <tree string=\"Recipient\" editable=\"top\" create=\"0\" delete=\"0\">\n                        <field name=\"partner_name\"/>\n                        <field name=\"sms_number\"/>\n                        <field name=\"failure_type\" string=\"Reason\" class=\"text-wrap\"/>\n                        <field name=\"resend\" widget=\"boolean_toggle\"/>\n                        <field name=\"notification_id\" column_invisible=\"True\"/>\n                    </tree>\n                </field>\n                <footer>\n                    <button string=\"Buy credits\" name=\"action_buy_credits\" type=\"object\" class=\"btn-primary o_mail_send\" invisible=\"not has_insufficient_credit\" data-hotkey=\"q\"/>\n                    <button string=\"Set up an account\" name=\"action_buy_credits\" type=\"object\" class=\"btn-primary o_mail_send\" invisible=\"not has_unregistered_account\" data-hotkey=\"q\"/>\n                    <button string=\"Send &amp; Close\" name=\"action_resend\" type=\"object\" class=\"btn-primary o_mail_send\" invisible=\"not has_unregistered_account or not can_resend\" data-hotkey=\"w\"/>\n                    <button string=\"Ignore all\" name=\"action_cancel\" type=\"object\" class=\"btn-primary\" invisible=\"has_insufficient_credit or has_unregistered_account or has_unregistered_account and can_resend\" data-hotkey=\"z\"/>\n                    <button string=\"Ignore all\" name=\"action_cancel\" type=\"object\" class=\"btn-secondary\" invisible=\"not has_insufficient_credit and not has_unregistered_account and (not has_unregistered_account or not can_resend)\" data-hotkey=\"z\"/>\n                    <button string=\"Close\" class=\"btn-secondary\" special=\"cancel\" data-hotkey=\"x\"/>\n                </footer>\n            </form>"}', '<?xml version="1.0"?>
<form string="Edit Partners">
                <field name="mail_message_id" invisible="1"/>
                <field name="can_resend" invisible="1"/>
                <field name="has_insufficient_credit" invisible="1"/>
                <field name="has_unregistered_account" invisible="1"/>
                <field name="recipient_ids">
                    <tree string="Recipient" editable="top" create="0" delete="0">
                        <field name="partner_name"/>
                        <field name="sms_number"/>
                        <field name="failure_type" string="Reason" class="text-wrap"/>
                        <field name="resend" widget="boolean_toggle"/>
                        <field name="notification_id" column_invisible="True"/>
                    </tree>
                </field>
                <footer>
                    <button string="Buy credits" name="action_buy_credits" type="object" class="btn-primary o_mail_send" invisible="not has_insufficient_credit" data-hotkey="q"/>
                    <button string="Set up an account" name="action_buy_credits" type="object" class="btn-primary o_mail_send" invisible="not has_unregistered_account" data-hotkey="q"/>
                    <button string="Send &amp; Close" name="action_resend" type="object" class="btn-primary o_mail_send" invisible="not has_unregistered_account or not can_resend" data-hotkey="w"/>
                    <button string="Ignore all" name="action_cancel" type="object" class="btn-primary" invisible="has_insufficient_credit or has_unregistered_account or has_unregistered_account and can_resend" data-hotkey="z"/>
                    <button string="Ignore all" name="action_cancel" type="object" class="btn-secondary" invisible="not has_insufficient_credit and not has_unregistered_account and (not has_unregistered_account or not can_resend)" data-hotkey="z"/>
                    <button string="Close" class="btn-secondary" special="cancel" data-hotkey="x"/>
                </footer>
            </form>
        ', false, true, '2026-05-10 01:11:52.961149', '2026-05-10 01:11:52.961149', false);
INSERT INTO public.ir_ui_view VALUES (571, 1000, NULL, 1, 1, 'sms.template.reset.view.form', 'sms.template.reset', NULL, 'form', 'sms/wizard/sms_template_reset_views.xml', 'primary', '{"en_US": "<form>\n                <div>\n                    Are you sure you want to reset these sms templates to their original configuration? Changes and translations will be lost.\n                </div>\n                <footer>\n                    <button string=\"Proceed\" class=\"btn btn-primary\" type=\"object\" name=\"reset_template\" data-hotkey=\"q\"/>\n                    <button string=\"Cancel\" class=\"btn-secondary\" special=\"cancel\" data-hotkey=\"x\"/>\n                </footer>\n            </form>"}', '<?xml version="1.0"?>
<form>
                <div>
                    Are you sure you want to reset these sms templates to their original configuration? Changes and translations will be lost.
                </div>
                <footer>
                    <button string="Proceed" class="btn btn-primary" type="object" name="reset_template" data-hotkey="q"/>
                    <button string="Cancel" class="btn-secondary" special="cancel" data-hotkey="x"/>
                </footer>
            </form>
        ', false, true, '2026-05-10 01:11:52.961149', '2026-05-10 01:11:52.961149', false);
INSERT INTO public.ir_ui_view VALUES (572, 16, 17, 1, 1, 'ir.actions.server.view.form.inherit.sms', 'ir.actions.server', NULL, 'form', 'sms/views/ir_actions_server_views.xml', 'extension', '{"en_US": "<xpath expr=\"//field[@name=''link_field_id'']\" position=\"after\">\n                <field name=\"sms_template_id\" placeholder=\"Choose a template...\" context=\"{''default_model'': model_name}\" invisible=\"state != ''sms''\" required=\"state == ''sms''\"/>\n                <label for=\"sms_method\" invisible=\"state != ''sms''\"/>\n                    <div class=\"d-flex flex-column\" invisible=\"state != ''sms''\">\n                        <field name=\"sms_method\" required=\"state == ''sms''\"/>\n                        <div class=\"text-muted\">\n                            <span invisible=\"sms_method != ''sms''\">\n                                The message will be sent as an SMS to the recipients of the template\n                                and will not appear in the messaging history.\n                            </span>\n                            <span invisible=\"sms_method != ''note''\">\n                                The SMS will not be sent, it will only be posted as an\n                                internal note in the messaging history.\n                            </span>\n                            <span invisible=\"sms_method != ''comment''\">\n                                The SMS will be sent as an SMS to the recipients of the\n                                template and it will also be posted as an internal note\n                                in the messaging history.\n                            </span>\n                        </div>\n                    </div>\n            </xpath>"}', '<?xml version="1.0"?>
<xpath expr="//field[@name=''link_field_id'']" position="after">
                <field name="sms_template_id" placeholder="Choose a template..." context="{''default_model'': model_name}" invisible="state != ''sms''" required="state == ''sms''"/>
                <label for="sms_method" invisible="state != ''sms''"/>
                    <div class="d-flex flex-column" invisible="state != ''sms''">
                        <field name="sms_method" required="state == ''sms''"/>
                        <div class="text-muted">
                            <span invisible="sms_method != ''sms''">
                                The message will be sent as an SMS to the recipients of the template
                                and will not appear in the messaging history.
                            </span>
                            <span invisible="sms_method != ''note''">
                                The SMS will not be sent, it will only be posted as an
                                internal note in the messaging history.
                            </span>
                            <span invisible="sms_method != ''comment''">
                                The SMS will be sent as an SMS to the recipients of the
                                template and it will also be posted as an internal note
                                in the messaging history.
                            </span>
                        </div>
                    </div>
            </xpath>
        ', false, true, '2026-05-10 01:11:52.961149', '2026-05-10 01:11:52.961149', false);
