INSERT INTO public.ir_ui_view VALUES (576, 10, 125, 1, 1, 'res.partner.view.form.inherit.sms', 'res.partner', NULL, 'form', 'sms/views/res_partner_views.xml', 'extension', '{"en_US": "<data><xpath expr=\"//field[@name=''mobile'']\" position=\"after\">\n                <field name=\"phone_sanitized\" groups=\"base.group_no_one\" invisible=\"1\"/>\n            </xpath>\n            <xpath expr=\"//field[@name=''phone'']\" position=\"replace\">\n                <field name=\"phone_blacklisted\" invisible=\"1\"/>\n                <field name=\"mobile_blacklisted\" invisible=\"1\"/>\n                <label for=\"phone\" class=\"oe_inline\"/>\n                <div class=\"o_row o_row_readonly\">\n                    <button name=\"phone_action_blacklist_remove\" class=\"fa fa-ban text-danger\" title=\"This phone number is blacklisted for SMS Marketing. Click to unblacklist.\" type=\"object\" context=\"{''default_phone'': phone}\" groups=\"base.group_user\" invisible=\"not phone_blacklisted\"/>\n                    <field name=\"phone\" widget=\"phone\"/>\n                </div>\n            </xpath>\n            <xpath expr=\"//field[@name=''mobile'']\" position=\"replace\">\n                <field name=\"phone_blacklisted\" invisible=\"1\"/>\n                <field name=\"mobile_blacklisted\" invisible=\"1\"/>\n                <label for=\"mobile\" class=\"oe_inline\"/>\n                <div class=\"o_row o_row_readonly\">\n                    <button name=\"phone_action_blacklist_remove\" class=\"fa fa-ban text-danger\" title=\"This phone number is blacklisted for SMS Marketing. Click to unblacklist.\" type=\"object\" context=\"{''default_phone'': mobile}\" groups=\"base.group_user\" invisible=\"not mobile_blacklisted\"/>\n                    <field name=\"mobile\" widget=\"phone\"/>\n                </div>\n            </xpath>\n        </data>"}', '<?xml version="1.0"?>
<data><xpath expr="//field[@name=''mobile'']" position="after">
                <field name="phone_sanitized" groups="base.group_no_one" invisible="1"/>
            </xpath>
            <xpath expr="//field[@name=''phone'']" position="replace">
                <field name="phone_blacklisted" invisible="1"/>
                <field name="mobile_blacklisted" invisible="1"/>
                <label for="phone" class="oe_inline"/>
                <div class="o_row o_row_readonly">
                    <button name="phone_action_blacklist_remove" class="fa fa-ban text-danger" title="This phone number is blacklisted for SMS Marketing. Click to unblacklist." type="object" context="{''default_phone'': phone}" groups="base.group_user" invisible="not phone_blacklisted"/>
                    <field name="phone" widget="phone"/>
                </div>
            </xpath>
            <xpath expr="//field[@name=''mobile'']" position="replace">
                <field name="phone_blacklisted" invisible="1"/>
                <field name="mobile_blacklisted" invisible="1"/>
                <label for="mobile" class="oe_inline"/>
                <div class="o_row o_row_readonly">
                    <button name="phone_action_blacklist_remove" class="fa fa-ban text-danger" title="This phone number is blacklisted for SMS Marketing. Click to unblacklist." type="object" context="{''default_phone'': mobile}" groups="base.group_user" invisible="not mobile_blacklisted"/>
                    <field name="mobile" widget="phone"/>
                </div>
            </xpath>
        </data>', false, true, '2026-05-10 01:11:52.961149', '2026-05-10 01:11:52.961149', false);
INSERT INTO public.ir_ui_view VALUES (577, 16, 127, 1, 1, 'res.partner.view.search.inherit.sms', 'res.partner', NULL, 'search', 'sms/views/res_partner_views.xml', 'extension', '{"en_US": "<xpath expr=\"//field[@name=''phone'']\" position=\"replace\">\n                <field name=\"phone_mobile_search\"/>\n            </xpath>"}', '<?xml version="1.0"?>
