INSERT INTO public.ir_ui_view VALUES (578, 16, NULL, 1, 1, 'sms.sms.view.form', 'sms.sms', NULL, 'form', 'sms/views/sms_sms_views.xml', 'primary', '{"en_US": "<form string=\"SMS\">\n                <header>\n                    <field name=\"to_delete\" invisible=\"1\"/>\n                    <button name=\"send\" string=\"Send Now\" type=\"object\" invisible=\"state != ''outgoing'' or to_delete\" class=\"oe_highlight\"/>\n                    <button name=\"action_set_outgoing\" string=\"Retry\" type=\"object\" invisible=\"state not in (''error'', ''canceled'')\"/>\n                    <button name=\"action_set_canceled\" string=\"Cancel\" type=\"object\" invisible=\"state not in (''error'', ''outgoing'')\"/>\n                    <field name=\"state\" widget=\"statusbar\" statusbar_visible=\"outgoing,sent,error,canceled\"/>\n                </header>\n                <sheet>\n                    <group>\n                        <group>\n                            <field name=\"partner_id\" string=\"Contact\"/>\n                            <field name=\"mail_message_id\" readonly=\"1\" invisible=\"not mail_message_id\"/>\n                        </group>\n                        <group>\n                            <field name=\"number\" required=\"1\"/>\n                            <field name=\"failure_type\" readonly=\"1\" invisible=\"not failure_type\"/>\n                        </group>\n                    </group>\n                    <group>\n                        <field name=\"body\" widget=\"sms_widget\" string=\"Message\" required=\"1\" readonly=\"state in (''process'', ''sent'')\"/>\n                    </group>\n                </sheet>\n            </form>"}', '<?xml version="1.0"?>
<form string="SMS">
                <header>
                    <field name="to_delete" invisible="1"/>
                    <button name="send" string="Send Now" type="object" invisible="state != ''outgoing'' or to_delete" class="oe_highlight"/>
                    <button name="action_set_outgoing" string="Retry" type="object" invisible="state not in (''error'', ''canceled'')"/>
                    <button name="action_set_canceled" string="Cancel" type="object" invisible="state not in (''error'', ''outgoing'')"/>
                    <field name="state" widget="statusbar" statusbar_visible="outgoing,sent,error,canceled"/>
                </header>
                <sheet>
                    <group>
                        <group>
                            <field name="partner_id" string="Contact"/>
                            <field name="mail_message_id" readonly="1" invisible="not mail_message_id"/>
                        </group>
                        <group>
                            <field name="number" required="1"/>
                            <field name="failure_type" readonly="1" invisible="not failure_type"/>
                        </group>
                    </group>
                    <group>
                        <field name="body" widget="sms_widget" string="Message" required="1" readonly="state in (''process'', ''sent'')"/>
                    </group>
                </sheet>
            </form>
        ', false, true, '2026-05-10 01:11:52.961149', '2026-05-10 01:11:52.961149', false);
INSERT INTO public.ir_ui_view VALUES (579, 16, NULL, 1, 1, 'sms.sms.view.tree', 'sms.sms', NULL, 'tree', 'sms/views/sms_sms_views.xml', 'primary', '{"en_US": "<tree string=\"SMS Templates\">\n                <field name=\"number\"/>\n                <field name=\"partner_id\"/>\n                <field name=\"failure_type\"/>\n                <field name=\"state\" widget=\"badge\" decoration-info=\"state == ''outgoing''\" decoration-muted=\"state == ''canceled''\" decoration-success=\"state == ''sent''\" decoration-danger=\"state == ''error''\"/>\n                <button name=\"send\" string=\"Send Now\" type=\"object\" icon=\"fa-paper-plane\" invisible=\"state != ''outgoing''\"/>\n                <button name=\"action_set_outgoing\" string=\"Retry\" type=\"object\" icon=\"fa-repeat\" invisible=\"state not in (''error'', ''canceled'')\"/>\n                <button name=\"action_set_canceled\" string=\"Cancel\" type=\"object\" icon=\"fa-times-circle\" invisible=\"state not in (''error'', ''outgoing'')\"/>\n            </tree>"}', '<?xml version="1.0"?>
<tree string="SMS Templates">
                <field name="number"/>
                <field name="partner_id"/>
                <field name="failure_type"/>
                <field name="state" widget="badge" decoration-info="state == ''outgoing''" decoration-muted="state == ''canceled''" decoration-success="state == ''sent''" decoration-danger="state == ''error''"/>
                <button name="send" string="Send Now" type="object" icon="fa-paper-plane" invisible="state != ''outgoing''"/>
                <button name="action_set_outgoing" string="Retry" type="object" icon="fa-repeat" invisible="state not in (''error'', ''canceled'')"/>
                <button name="action_set_canceled" string="Cancel" type="object" icon="fa-times-circle" invisible="state not in (''error'', ''outgoing'')"/>
            </tree>
        ', false, true, '2026-05-10 01:11:52.961149', '2026-05-10 01:11:52.961149', false);
INSERT INTO public.ir_ui_view VALUES (580, 16, NULL, 1, 1, 'sms.sms.view.search', 'sms.sms', NULL, 'search', 'sms/views/sms_sms_views.xml', 'primary', '{"en_US": "<search string=\"Search SMS Templates\">\n                <field name=\"number\"/>\n                <field name=\"partner_id\"/>\n            </search>"}', '<?xml version="1.0"?>
<search string="Search SMS Templates">
                <field name="number"/>
                <field name="partner_id"/>
            </search>
        ', false, true, '2026-05-10 01:11:52.961149', '2026-05-10 01:11:52.961149', false);
INSERT INTO public.ir_ui_view VALUES (581, 16, NULL, 1, 1, 'sms.template.view.form', 'sms.template', NULL, 'form', 'sms/views/sms_template_views.xml', 'primary', '{"en_US": "<form string=\"SMS Templates\">\n                <header>\n                    <field name=\"template_fs\" invisible=\"1\"/>\n                    <button string=\"Reset Template\" name=\"201\" type=\"action\" groups=\"base.group_system\" invisible=\"not template_fs\"/>\n                </header>\n                <sheet>\n                    <div class=\"oe_button_box\" name=\"button_box\">\n                        <field name=\"sidebar_action_id\" invisible=\"1\"/>\n                        <button name=\"action_create_sidebar_action\" type=\"object\" groups=\"base.group_no_one\" class=\"oe_stat_button\" invisible=\"sidebar_action_id\" icon=\"fa-plus\" help=\"Add a contextual action on the related model to open a sms composer with this template\">\n                            <div class=\"o_field_widget o_stat_info\">\n                                <span class=\"o_stat_text\">Add</span>\n                                <span class=\"o_stat_text\">Context Action</span>\n                            </div>\n                        </button>\n                        <button name=\"action_unlink_sidebar_action\" type=\"object\" groups=\"base.group_no_one\" class=\"oe_stat_button\" icon=\"fa-minus\" invisible=\"not sidebar_action_id\" help=\"Remove the contextual action of the related model\" widget=\"statinfo\">\n                            <div class=\"o_field_widget o_stat_info\">\n                                <span class=\"o_stat_text\">Remove</span>\n                                <span class=\"o_stat_text\">Context Action</span>\n                            </div>\n                        </button>\n                        <button class=\"oe_stat_button\" name=\"199\" icon=\"fa-search-plus\" type=\"action\" target=\"new\">\n                            <div class=\"o_field_widget o_stat_info\">\n                                <span class=\"o_stat_text\">Preview</span>\n                            </div>\n                        </button>\n                    </div>\n                    <div class=\"oe_title\">\n                        <label for=\"name\" string=\"SMS Template\"/>\n                        <h1><field name=\"name\" placeholder=\"e.g. Calendar Reminder\" required=\"1\"/></h1>\n                        <group>\n                            <field name=\"model_id\" placeholder=\"e.g. Contact\" required=\"1\" options=\"{''no_create'': True}\"/>\n                            <field name=\"model\" invisible=\"1\"/>\n                            <field name=\"lang\" groups=\"base.group_no_one\" placeholder=\"e.g. en_US or {{ object.partner_id.lang }}\"/>\n                        </group>\n                    </div>\n                    <notebook>\n                        <page string=\"Content\" name=\"content\">\n                            <group>\n                                <field name=\"body\" widget=\"sms_widget\" nolabel=\"1\" colspan=\"2\"/>\n                            </group>\n                        </page>\n                    </notebook>\n                </sheet>\n            </form>"}', '<?xml version="1.0"?>
<form string="SMS Templates">
                <header>
                    <field name="template_fs" invisible="1"/>
                    <button string="Reset Template" name="201" type="action" groups="base.group_system" invisible="not template_fs"/>
                </header>
                <sheet>
                    <div class="oe_button_box" name="button_box">
                        <field name="sidebar_action_id" invisible="1"/>
                        <button name="action_create_sidebar_action" type="object" groups="base.group_no_one" class="oe_stat_button" invisible="sidebar_action_id" icon="fa-plus" help="Add a contextual action on the related model to open a sms composer with this template">
                            <div class="o_field_widget o_stat_info">
                                <span class="o_stat_text">Add</span>
                                <span class="o_stat_text">Context Action</span>
                            </div>
                        </button>
                        <button name="action_unlink_sidebar_action" type="object" groups="base.group_no_one" class="oe_stat_button" icon="fa-minus" invisible="not sidebar_action_id" help="Remove the contextual action of the related model" widget="statinfo">
                            <div class="o_field_widget o_stat_info">
                                <span class="o_stat_text">Remove</span>
                                <span class="o_stat_text">Context Action</span>
                            </div>
                        </button>
                        <button class="oe_stat_button" name="199" icon="fa-search-plus" type="action" target="new">
                            <div class="o_field_widget o_stat_info">
                                <span class="o_stat_text">Preview</span>
                            </div>
                        </button>
                    </div>
                    <div class="oe_title">
                        <label for="name" string="SMS Template"/>
                        <h1><field name="name" placeholder="e.g. Calendar Reminder" required="1"/></h1>
                        <group>
                            <field name="model_id" placeholder="e.g. Contact" required="1" options="{''no_create'': True}"/>
                            <field name="model" invisible="1"/>
                            <field name="lang" groups="base.group_no_one" placeholder="e.g. en_US or {{ object.partner_id.lang }}"/>
                        </group>
                    </div>
                    <notebook>
                        <page string="Content" name="content">
                            <group>
                                <field name="body" widget="sms_widget" nolabel="1" colspan="2"/>
                            </group>
                        </page>
                    </notebook>
                </sheet>
            </form>
        ', false, true, '2026-05-10 01:11:52.961149', '2026-05-10 01:11:52.961149', false);
INSERT INTO public.ir_ui_view VALUES (582, 16, NULL, 1, 1, 'sms.template.view.tree', 'sms.template', NULL, 'tree', 'sms/views/sms_template_views.xml', 'primary', '{"en_US": "<tree string=\"SMS Templates\">\n                <field name=\"name\"/>\n                <field name=\"model_id\"/>\n            </tree>"}', '<?xml version="1.0"?>
<tree string="SMS Templates">
                <field name="name"/>
                <field name="model_id"/>
            </tree>
        ', false, true, '2026-05-10 01:11:52.961149', '2026-05-10 01:11:52.961149', false);
INSERT INTO public.ir_ui_view VALUES (586, 16, NULL, 1, 1, 'snailmail.letter.tree', 'snailmail.letter', NULL, 'tree', 'snailmail/views/snailmail_views.xml', 'primary', '{"en_US": "<tree decoration-danger=\"state==''error''\" decoration-muted=\"state==''sent''\" string=\"Letters\">\n                <field name=\"attachment_id\" string=\"Document\"/>\n                <field name=\"partner_id\"/>\n                <field name=\"user_id\"/>\n                <field name=\"state\" column_invisible=\"True\"/>\n                <field name=\"info_msg\" widget=\"html\"/>\n                <field name=\"company_id\" groups=\"base.group_multi_company\"/>\n            </tree>"}', '<?xml version="1.0"?>
<tree decoration-danger="state==''error''" decoration-muted="state==''sent''" string="Letters">
                <field name="attachment_id" string="Document"/>
                <field name="partner_id"/>
                <field name="user_id"/>
                <field name="state" column_invisible="True"/>
                <field name="info_msg" widget="html"/>
                <field name="company_id" groups="base.group_multi_company"/>
            </tree>
        ', false, true, '2026-05-10 01:11:54.209435', '2026-05-10 01:11:54.209435', false);
INSERT INTO public.ir_ui_view VALUES (587, 16, NULL, 1, 1, 'snailmail.letter.form', 'snailmail.letter', NULL, 'form', 'snailmail/views/snailmail_views.xml', 'primary', '{"en_US": "<form>\n                <header>\n                    <button name=\"snailmail_print\" string=\"Send Now\" type=\"object\" invisible=\"state not in (''pending'', ''error'')\" class=\"oe_highlight\"/>\n                    <button name=\"cancel\" string=\"Cancel\" type=\"object\" invisible=\"state not in (''pending'', ''error'')\"/>\n                    <field name=\"state\" widget=\"statusbar\" statusbar_visible=\"pending,sent,canceled\"/>\n                </header>\n                <sheet>\n                    <div class=\"oe_title\">\n                        <h1><field name=\"display_name\"/></h1>\n                    </div>\n                    <group>\n                        <field name=\"reference\" widget=\"reference\"/>\n                        <field name=\"attachment_datas\" filename=\"attachment_fname\"/>\n                        <field name=\"attachment_fname\" invisible=\"1\"/>\n                        <field name=\"partner_id\"/>\n                        <field name=\"user_id\"/>\n                        <field name=\"info_msg\" widget=\"html\"/>\n                    </group>\n                    <group groups=\"base.group_no_one\">\n                        <field name=\"model\"/>\n                        <field name=\"res_id\"/>\n                        <field name=\"color\"/>\n                        <field name=\"duplex\"/>\n                    </group>\n                </sheet>\n            </form>"}', '<?xml version="1.0"?>
<form>
                <header>
                    <button name="snailmail_print" string="Send Now" type="object" invisible="state not in (''pending'', ''error'')" class="oe_highlight"/>
                    <button name="cancel" string="Cancel" type="object" invisible="state not in (''pending'', ''error'')"/>
                    <field name="state" widget="statusbar" statusbar_visible="pending,sent,canceled"/>
                </header>
                <sheet>
                    <div class="oe_title">
                        <h1><field name="display_name"/></h1>
                    </div>
                    <group>
                        <field name="reference" widget="reference"/>
                        <field name="attachment_datas" filename="attachment_fname"/>
                        <field name="attachment_fname" invisible="1"/>
                        <field name="partner_id"/>
                        <field name="user_id"/>
                        <field name="info_msg" widget="html"/>
                    </group>
                    <group groups="base.group_no_one">
                        <field name="model"/>
                        <field name="res_id"/>
                        <field name="color"/>
                        <field name="duplex"/>
                    </group>
                </sheet>
            </form>
        ', false, true, '2026-05-10 01:11:54.209435', '2026-05-10 01:11:54.209435', false);
INSERT INTO public.ir_ui_view VALUES (588, 16, NULL, 1, 1, 'snailmail.letter.format.error.form', 'snailmail.letter.format.error', NULL, 'form', 'snailmail/wizard/snailmail_letter_format_error_views.xml', 'primary', '{"en_US": "<form string=\"Cancel notification in failure\">\n                <p>Our service cannot read your letter due to its format.<br/>\n                Please modify the format of the template or update your settings\n                to automatically add a blank cover page to all letters.</p>\n                <field name=\"snailmail_cover\"/>\n                <label string=\"Add a Cover Page\" class=\"o_light_label\" for=\"snailmail_cover\"/>\n                <footer>\n                    <button string=\"Update Config and Re-send\" name=\"update_resend_action\" type=\"object\" class=\"btn-primary\" data-hotkey=\"q\"/>\n                    <button string=\"Cancel Letter\" name=\"cancel_letter_action\" type=\"object\" class=\"btn-primary\" data-hotkey=\"w\"/>\n                    <button string=\"Close\" class=\"btn-secondary\" special=\"cancel\" data-hotkey=\"x\"/>\n                </footer>\n            </form>"}', '<?xml version="1.0"?>
<form string="Cancel notification in failure">
                <p>Our service cannot read your letter due to its format.<br/>
                Please modify the format of the template or update your settings
                to automatically add a blank cover page to all letters.</p>
                <field name="snailmail_cover"/>
                <label string="Add a Cover Page" class="o_light_label" for="snailmail_cover"/>
                <footer>
                    <button string="Update Config and Re-send" name="update_resend_action" type="object" class="btn-primary" data-hotkey="q"/>
                    <button string="Cancel Letter" name="cancel_letter_action" type="object" class="btn-primary" data-hotkey="w"/>
                    <button string="Close" class="btn-secondary" special="cancel" data-hotkey="x"/>
                </footer>
            </form>
        ', false, true, '2026-05-10 01:11:54.209435', '2026-05-10 01:11:54.209435', false);
INSERT INTO public.ir_ui_view VALUES (589, 16, NULL, 1, 1, 'snailmail.letter.missing.required.fields.form', 'snailmail.letter.missing.required.fields', NULL, 'form', 'snailmail/wizard/snailmail_letter_missing_required_fields_views.xml', 'primary', '{"en_US": "<form>\n                <!-- Field present for correct default_get behavior -->\n                <field name=\"letter_id\" invisible=\"1\"/>\n                <p>The customer address is not complete. Update the address here and re-send the letter.</p>\n                <group>\n                    <label for=\"partner_id\" string=\"Address\"/>\n                    <div class=\"o_address_format\">\n                        <field name=\"partner_id\" readonly=\"1\" options=\"{''no_open'': True}\" force_save=\"1\"/>\n                        <field name=\"street\" placeholder=\"Street...\" class=\"o_address_street\"/>\n                        <field name=\"street2\" placeholder=\"Street 2...\" class=\"o_address_street\"/>\n                        <field name=\"city\" placeholder=\"City\" class=\"o_address_city\"/>\n                        <field name=\"state_id\" class=\"o_address_state\" placeholder=\"State\" options=\"{&quot;no_open&quot;: True}\"/>\n                        <field name=\"zip\" placeholder=\"ZIP\" class=\"o_address_zip\"/>\n                        <field name=\"country_id\" placeholder=\"Country\" class=\"o_address_country\" options=\"{&quot;no_open&quot;: True, &quot;no_create&quot;: True}\"/>\n                    </div>\n                </group>\n                <footer>\n                    <button string=\"Update address and re-send\" type=\"object\" name=\"update_address_save\" class=\"btn-primary\" data-hotkey=\"q\"/>\n                    <button string=\"Cancel letter\" type=\"object\" name=\"update_address_cancel\" class=\"btn-secondary\" data-hotkey=\"w\"/>\n                    <button string=\"Close\" special=\"cancel\" class=\"btn-secondary\" data-hotkey=\"x\"/>\n                </footer>\n            </form>"}', '<?xml version="1.0"?>
<form>
                <!-- Field present for correct default_get behavior -->
                <field name="letter_id" invisible="1"/>
                <p>The customer address is not complete. Update the address here and re-send the letter.</p>
                <group>
                    <label for="partner_id" string="Address"/>
                    <div class="o_address_format">
                        <field name="partner_id" readonly="1" options="{''no_open'': True}" force_save="1"/>
                        <field name="street" placeholder="Street..." class="o_address_street"/>
                        <field name="street2" placeholder="Street 2..." class="o_address_street"/>
                        <field name="city" placeholder="City" class="o_address_city"/>
                        <field name="state_id" class="o_address_state" placeholder="State" options="{&quot;no_open&quot;: True}"/>
                        <field name="zip" placeholder="ZIP" class="o_address_zip"/>
                        <field name="country_id" placeholder="Country" class="o_address_country" options="{&quot;no_open&quot;: True, &quot;no_create&quot;: True}"/>
                    </div>
                </group>
                <footer>
                    <button string="Update address and re-send" type="object" name="update_address_save" class="btn-primary" data-hotkey="q"/>
                    <button string="Cancel letter" type="object" name="update_address_cancel" class="btn-secondary" data-hotkey="w"/>
                    <button string="Close" special="cancel" class="btn-secondary" data-hotkey="x"/>
                </footer>
            </form>
        ', false, true, '2026-05-10 01:11:54.209435', '2026-05-10 01:11:54.209435', false);
INSERT INTO public.ir_ui_view VALUES (590, 16, 557, 1, 1, 'TOTP Portal hook', NULL, 'auth_totp_portal.totp_portal_hook', 'qweb', 'auth_totp_portal/views/templates.xml', 'extension', '{"en_US": "<data name=\"TOTP Portal hook\" inherit_id=\"portal.portal_my_security\">\n        <xpath expr=\"//section[@name=''portal_change_password'']\" position=\"after\">\n            <!--\n                portal users don''t have access to non-qweb views anymore, so\n                embed the target view as a *data island* of sorts, a JSON embed\n                of the fields_view_get could have been nice but at 14k it''d be a\n                bit ridiculous\n            -->\n            <div class=\"d-none\" id=\"totp_wizard_view\">\n                <t t-esc=\"env.ref(''auth_totp.view_totp_wizard'').sudo().get_combined_arch()\"/>\n            </div>\n            <section>\n                <h4>\n                    Two-factor authentication\n                    <a href=\"https://www.odoo.com/documentation/17.0/applications/general/auth/2fa.html\" target=\"_blank\">\n                        <i title=\"Documentation\" class=\"fa fa-fw o_button_icon fa-info-circle\"/>\n                    </a>\n                </h4>\n                <t t-if=\"not user_id.totp_enabled\">\n                    <div class=\"alert alert-secondary\" role=\"status\">\n                        <i class=\"fa fa-warning\"/>\n                        Two-factor authentication not enabled\n                    </div>\n                    <button type=\"button\" class=\"btn btn-secondary\" id=\"auth_totp_portal_enable\">\n                        Enable two-factor authentication\n                    </button>\n                </t>\n                <t t-else=\"\">\n                    <span class=\"text-success\">\n                        <i class=\"fa fa-check-circle\"/>\n                        Two-factor authentication enabled\n                    </span>\n                    <button type=\"button\" class=\"btn btn-link\" id=\"auth_totp_portal_disable\">\n                        (Disable two-factor authentication)\n                    </button>\n                    <t t-if=\"len(user_id.totp_trusted_device_ids)\">\n                        <table class=\"table o_main_table\">\n                            <thead>\n                                <tr>\n                                    <th><strong>Trusted Device</strong></th>\n                                    <th><strong>Added On</strong></th>\n                                </tr>\n                            </thead>\n                            <tbody>\n                                <tr t-foreach=\"user_id.totp_trusted_device_ids\" t-as=\"td\">\n                                    <td>\n                                        <span t-field=\"td.name\"/>\n                                    </td>\n                                    <td>\n                                        <span t-field=\"td.create_date\"/>\n                                    </td>\n                                    <td>\n                                        <i class=\"fa fa-trash text-danger\" type=\"button\" t-att-id=\"td.id\"/>\n                                    </td>\n                                </tr>\n                            </tbody>\n                        </table>\n                        <button class=\"btn btn-primary\" type=\"button\" id=\"auth_totp_portal_revoke_all_devices\">\n                            Revoke All\n                        </button>\n                    </t>\n                </t>\n            </section>\n        </xpath>\n    </data>"}', '<?xml version="1.0"?>
<data name="TOTP Portal hook" inherit_id="portal.portal_my_security">
        <xpath expr="//section[@name=''portal_change_password'']" position="after">
            <!--
                portal users don''t have access to non-qweb views anymore, so
                embed the target view as a *data island* of sorts, a JSON embed
                of the fields_view_get could have been nice but at 14k it''d be a
                bit ridiculous
            -->
            <div class="d-none" id="totp_wizard_view">
                <t t-esc="env.ref(''auth_totp.view_totp_wizard'').sudo().get_combined_arch()"/>
            </div>
            <section>
                <h4>
                    Two-factor authentication
                    <a href="https://www.odoo.com/documentation/17.0/applications/general/auth/2fa.html" target="_blank">
                        <i title="Documentation" class="fa fa-fw o_button_icon fa-info-circle"/>
                    </a>
                </h4>
                <t t-if="not user_id.totp_enabled">
                    <div class="alert alert-secondary" role="status">
                        <i class="fa fa-warning"/>
                        Two-factor authentication not enabled
                    </div>
                    <button type="button" class="btn btn-secondary" id="auth_totp_portal_enable">
                        Enable two-factor authentication
                    </button>
                </t>
                <t t-else="">
                    <span class="text-success">
                        <i class="fa fa-check-circle"/>
                        Two-factor authentication enabled
                    </span>
                    <button type="button" class="btn btn-link" id="auth_totp_portal_disable">
                        (Disable two-factor authentication)
                    </button>
                    <t t-if="len(user_id.totp_trusted_device_ids)">
                        <table class="table o_main_table">
                            <thead>
                                <tr>
                                    <th><strong>Trusted Device</strong></th>
                                    <th><strong>Added On</strong></th>
                                </tr>
                            </thead>
                            <tbody>
                                <tr t-foreach="user_id.totp_trusted_device_ids" t-as="td">
                                    <td>
                                        <span t-field="td.name"/>
                                    </td>
                                    <td>
                                        <span t-field="td.create_date"/>
                                    </td>
                                    <td>
                                        <i class="fa fa-trash text-danger" type="button" t-att-id="td.id"/>
                                    </td>
                                </tr>
                            </tbody>
                        </table>
                        <button class="btn btn-primary" type="button" id="auth_totp_portal_revoke_all_devices">
                            Revoke All
                        </button>
                    </t>
                </t>
            </section>
        </xpath>
    </data>
', false, true, '2026-05-10 01:11:54.512731', '2026-05-10 01:11:54.512731', false);
INSERT INTO public.ir_ui_view VALUES (591, 16, NULL, 1, 1, 'digest_mail_layout', NULL, 'digest.digest_mail_layout', 'qweb', 'digest/data/digest_data.xml', 'primary', '{"en_US": "<t t-name=\"digest.digest_mail_layout\">\n&lt;!DOCTYPE html&gt;\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\n    <head>\n        <meta http-equiv=\"Content-Type\" content=\"text/html; charset=UTF-8\"/>\n        <meta name=\"format-detection\" content=\"telephone=no\"/>\n        <meta name=\"viewport\" content=\"width=device-width; initial-scale=1.0; maximum-scale=1.0; user-scalable=no;\"/>\n        <meta http-equiv=\"X-UA-Compatible\" content=\"IE=9; IE=8; IE=7; IE=EDGE\"/>\n        <style type=\"text/css\">\n            <t t-set=\"color_company\" t-value=\"company.email_secondary_color or ''#714B67''\"/>\n            /* Remove space around the email design. */\n            html,\n            body {\n                margin: 0 auto !important;\n                padding: 0 !important;\n                height: 100% !important;\n                width: 100% !important;\n                font-family: Arial, Helvetica, Verdana, sans-serif;\n            }\n            /* Prevent Windows 10 Mail from underlining links. Styles for underlined links should be inline. */\n            a {\n                text-decoration: none;\n            }\n            #header_background {\n                padding-top:20px;\n            }\n            #header {\n                border-top: 1px solid #d8dadd;\n            }\n            .global_layout {\n                width: 588px;\n                margin: 0 auto;\n                background-color: #ffffff;\n                border-left: 1px solid #d8dadd;\n                border-right: 1px solid #d8dadd;\n            }\n            .company_name {\n                display: inline;\n                vertical-align: middle;\n                color: #878d97;\n                font-weight: bold;\n                font-size: 24px;\n            }\n            .header_title {\n                color: #374151;\n                font-size: 18px;\n                word-break: break-all;\n            }\n            .td_button {\n                border-radius: 3px;\n                white-space: nowrap;\n            }\n            .td_button_connect {\n                background-color: <t t-out=\"color_company\"/>;\n            }\n            #button_connect {\n                color: #ffffff;\n                font-size: 16px;\n            }\n            #button_open_report {\n                color: #007e84;\n                font-size: 14px;\n            }\n            .header_date {\n                color: #878d97;\n                font-size: 14px;\n            }\n            .tip_title {\n                margin-top: 0;\n                font-weight: bold;\n                font-size: 20px;\n            }\n            .tip_content {\n                margin: 0 auto;\n                color: #374151;\n                text-align: justify;\n                text-justify: inter-word;\n                margin: 15px auto 0 auto;\n                font-size: 16px;\n                line-height: 25px;\n            }\n            .tip_button {\n                background-color: <t t-out=\"color_company\"/>;\n                border-radius: 3px;\n                padding: 10px;\n                text-decoration: none;\n            }\n            .tip_button_text {\n                color: #ffffff;\n            }\n            .illustration_border {\n                width: 100%;\n                border: 1px solid #d8dadd;\n                margin-top: 20px;\n            }\n            .kpi_row_footer {\n                padding-bottom: 20px;\n            }\n            .kpi_header {\n                font-size: 14px;\n                font-weight: bold;\n                color: #374151;\n            }\n            .kpi_cell {\n                width: 33%;\n                text-align: center;\n                padding-top: 10px;\n                padding: 0;\n            }\n            .kpi_value {\n                color: #374151;\n                font-weight: bold;\n                text-decoration: none;\n                font-size: 28px;\n            }\n            .kpi_border_col {\n                color: #374151;\n            }\n            .kpi_value_label {\n                display: inline-block;\n                margin-bottom: 10px;\n                color: #878d97;\n                font-size: 14px;\n            }\n            .kpi_margin_margin {\n                margin-bottom: 10px;\n            }\n            .download_app {\n                margin-bottom: 5px;\n                display: inline-block;\n            }\n            .preference {\n                margin-bottom: 15px;\n                color: #374151;\n                font-size: 14px;\n            }\n            .by_odoo {\n                color: #878d97;\n                font-size: 12px;\n            }\n            .odoo_link_text {\n                font-weight: bold;\n                color: <t t-out=\"color_company\"/>;\n            }\n            .run_business {\n                color: #374151;\n                margin: 15px auto;\n                font-size: 18px;\n            }\n            #footer {\n                background-color: #F9FAFB;\n                color: #878d97;\n                text-align: center;\n                font-size: 20px;\n                border: 1px solid #F9FAFB;\n                border-top: 0;\n            }\n            #stock_tip {\n                overflow: auto;\n                margin-top: 20px;\n            }\n            #stock_div_img {\n                text-align: center;\n            }\n            #stock_img {\n                width: 70%;\n            }\n            @media only screen and (max-width: 650px) {\n                .global_layout {\n                    width: 100% !important;\n                }\n                .d-block {\n                    display: block !important;\n                }\n                #header_background {\n                    padding-top: 0px;\n                }\n                #header {\n                    padding: 15px 20px;\n                    border: 1px solid #F9FAFB;\n                }\n                .company_name {\n                    font-size: 15px;\n                }\n                .header_title {\n                    margin: 5px auto;\n                }\n                .td_button_connect {\n                    padding: 0px 8px !important;\n                    height: 22px !important;\n                    font-size: 12px;\n                }\n                .td_button_open_report {\n                    padding: 0px 10px !important;\n                    font-size: 12px;\n                }\n                #button_connect {\n                    font-size: 12px;\n                }\n                .header_date {\n                    margin-top: 10px;\n                    font-size: 10px;\n                }\n                .tip_title {\n                    font-size: 14px;\n                }\n                .tip_content {\n                    margin: 10px auto 0 auto;\n                    font-size: 12px;\n                    line-height: 20px;\n                }\n                .illustration_border {\n                    margin-top: 15px;\n                }\n                .kpi_value {\n                    font-size: 20px;\n                }\n                .kpi_margin {\n                    font-size: 10px !important;\n                }\n                .kpi_margin_margin {\n                    margin-bottom: 5px;\n                }\n                .preference {\n                    font-size: 12px;\n                }\n                .by_odoo {\n                    font-size: 10px;\n                }\n                .run_business {\n                    margin: 20px auto;\n                    font-size: 12px;\n                }\n                #footer {\n                    font-size: 15px;\n                }\n                #powered {\n                    margin-top: 15px;\n                }\n                .tip_twocol {\n                    overflow: auto;\n                    margin-top: 15px;\n                }\n                .tip_twocol_left {\n                    text-align: left;\n                }\n                .tip_twocol_img {\n                    width: 90%;\n                }\n                .global_td {\n                    padding: 20px;\n                }\n                .p0 {\n                    padding: 0 !important;\n                }\n            }\n        </style>\n    </head>\n    <body>\n        <t t-out=\"body\"/>\n    </body>\n</html>\n    </t>"}', '<?xml version="1.0"?>
<t t-name="digest.digest_mail_layout">
&lt;!DOCTYPE html&gt;
<html xmlns="http://www.w3.org/1999/xhtml">
    <head>
        <meta http-equiv="Content-Type" content="text/html; charset=UTF-8"/>
        <meta name="format-detection" content="telephone=no"/>
        <meta name="viewport" content="width=device-width; initial-scale=1.0; maximum-scale=1.0; user-scalable=no;"/>
        <meta http-equiv="X-UA-Compatible" content="IE=9; IE=8; IE=7; IE=EDGE"/>
        <style type="text/css">
            <t t-set="color_company" t-value="company.email_secondary_color or ''#714B67''"/>
            /* Remove space around the email design. */
            html,
            body {
                margin: 0 auto !important;
                padding: 0 !important;
                height: 100% !important;
                width: 100% !important;
                font-family: Arial, Helvetica, Verdana, sans-serif;
            }
            /* Prevent Windows 10 Mail from underlining links. Styles for underlined links should be inline. */
            a {
                text-decoration: none;
            }
            #header_background {
                padding-top:20px;
            }
            #header {
                border-top: 1px solid #d8dadd;
            }
            .global_layout {
                width: 588px;
                margin: 0 auto;
                background-color: #ffffff;
                border-left: 1px solid #d8dadd;
                border-right: 1px solid #d8dadd;
            }
            .company_name {
                display: inline;
                vertical-align: middle;
                color: #878d97;
                font-weight: bold;
                font-size: 24px;
            }
            .header_title {
                color: #374151;
                font-size: 18px;
                word-break: break-all;
            }
            .td_button {
                border-radius: 3px;
                white-space: nowrap;
            }
            .td_button_connect {
                background-color: <t t-out="color_company"/>;
            }
            #button_connect {
                color: #ffffff;
                font-size: 16px;
            }
            #button_open_report {
                color: #007e84;
                font-size: 14px;
            }
            .header_date {
                color: #878d97;
                font-size: 14px;
            }
            .tip_title {
                margin-top: 0;
                font-weight: bold;
                font-size: 20px;
            }
            .tip_content {
                margin: 0 auto;
                color: #374151;
                text-align: justify;
                text-justify: inter-word;
                margin: 15px auto 0 auto;
                font-size: 16px;
                line-height: 25px;
            }
            .tip_button {
                background-color: <t t-out="color_company"/>;
                border-radius: 3px;
                padding: 10px;
                text-decoration: none;
            }
            .tip_button_text {
                color: #ffffff;
            }
            .illustration_border {
                width: 100%;
                border: 1px solid #d8dadd;
                margin-top: 20px;
            }
            .kpi_row_footer {
                padding-bottom: 20px;
            }
            .kpi_header {
                font-size: 14px;
                font-weight: bold;
                color: #374151;
            }
            .kpi_cell {
                width: 33%;
                text-align: center;
                padding-top: 10px;
                padding: 0;
            }
            .kpi_value {
                color: #374151;
                font-weight: bold;
                text-decoration: none;
                font-size: 28px;
            }
            .kpi_border_col {
                color: #374151;
            }
            .kpi_value_label {
                display: inline-block;
                margin-bottom: 10px;
                color: #878d97;
                font-size: 14px;
            }
            .kpi_margin_margin {
                margin-bottom: 10px;
            }
            .download_app {
                margin-bottom: 5px;
                display: inline-block;
            }
            .preference {
                margin-bottom: 15px;
                color: #374151;
                font-size: 14px;
            }
            .by_odoo {
                color: #878d97;
                font-size: 12px;
            }
            .odoo_link_text {
                font-weight: bold;
                color: <t t-out="color_company"/>;
            }
            .run_business {
                color: #374151;
                margin: 15px auto;
                font-size: 18px;
            }
            #footer {
                background-color: #F9FAFB;
                color: #878d97;
                text-align: center;
                font-size: 20px;
                border: 1px solid #F9FAFB;
                border-top: 0;
            }
            #stock_tip {
                overflow: auto;
                margin-top: 20px;
            }
            #stock_div_img {
                text-align: center;
            }
            #stock_img {
                width: 70%;
            }
            @media only screen and (max-width: 650px) {
                .global_layout {
                    width: 100% !important;
                }
                .d-block {
                    display: block !important;
                }
                #header_background {
                    padding-top: 0px;
                }
                #header {
                    padding: 15px 20px;
                    border: 1px solid #F9FAFB;
                }
                .company_name {
                    font-size: 15px;
                }
                .header_title {
                    margin: 5px auto;
                }
                .td_button_connect {
                    padding: 0px 8px !important;
                    height: 22px !important;
                    font-size: 12px;
                }
                .td_button_open_report {
                    padding: 0px 10px !important;
                    font-size: 12px;
                }
                #button_connect {
                    font-size: 12px;
                }
                .header_date {
                    margin-top: 10px;
                    font-size: 10px;
                }
                .tip_title {
                    font-size: 14px;
                }
                .tip_content {
                    margin: 10px auto 0 auto;
                    font-size: 12px;
                    line-height: 20px;
                }
                .illustration_border {
                    margin-top: 15px;
                }
                .kpi_value {
                    font-size: 20px;
                }
                .kpi_margin {
                    font-size: 10px !important;
                }
                .kpi_margin_margin {
                    margin-bottom: 5px;
                }
                .preference {
                    font-size: 12px;
                }
                .by_odoo {
                    font-size: 10px;
                }
                .run_business {
                    margin: 20px auto;
                    font-size: 12px;
                }
                #footer {
                    font-size: 15px;
                }
                #powered {
                    margin-top: 15px;
                }
                .tip_twocol {
                    overflow: auto;
                    margin-top: 15px;
                }
                .tip_twocol_left {
                    text-align: left;
                }
                .tip_twocol_img {
                    width: 90%;
                }
                .global_td {
                    padding: 20px;
                }
                .p0 {
                    padding: 0 !important;
                }
            }
        </style>
    </head>
    <body>
        <t t-out="body"/>
    </body>
</html>
    </t>

    ', false, true, '2026-05-10 01:11:54.58877', '2026-05-10 01:11:54.58877', false);
INSERT INTO public.ir_ui_view VALUES (592, 16, NULL, 1, 1, 'digest_mail_main', NULL, 'digest.digest_mail_main', 'qweb', 'digest/data/digest_data.xml', 'primary', '{"en_US": "<t t-name=\"digest.digest_mail_main\">\n<table cellspacing=\"0\" cellpadding=\"0\" style=\"width: 100%;background-color: #F9FAFB;\" align=\"center\">\n    <tbody>\n        <tr>\n            <td id=\"header_background\" align=\"center\">\n                <table cellspacing=\"0\" cellpadding=\"0\" border=\"0\" id=\"header\" class=\"global_layout\">\n                    <tbody>\n                        <tr>\n                            <td style=\"padding: 20px 20px 5px 20px;\" class=\"p0\"><p t-field=\"company.name\" class=\"company_name\"/></td>\n                            <td align=\"right\" style=\"padding: 20px 20px 5px 0px;\" class=\"p0\">\n                                <table>\n                                    <tbody>\n                                        <tr>\n                                            <td class=\"td_button td_button_connect\" style=\"height: 29px;padding: 3px 10px;\">\n                                                <a t-att-href=\"top_button_url\" target=\"_blank\">\n                                                    <span t-esc=\"top_button_label\" class=\"button\" id=\"button_connect\"/>\n                                                </a>\n                                            </td>\n                                        </tr>\n                                    </tbody>\n                                </table>\n                            </td>\n                        </tr>\n                        <tr>\n                            <td style=\"padding-left: 20px\" class=\"p0\" colspan=\"2\">\n                                <div class=\"header_title\">\n                                    <p t-esc=\"title\"/>\n                                    <p t-if=\"sub_title\" t-esc=\"sub_title\"/>\n                                </div>\n                            </td>\n                        </tr>\n                        <tr>\n                            <td style=\"padding: 10px 0px 20px 20px;\" class=\"p0\" colspan=\"2\">\n                                <span t-esc=\"formatted_date\" class=\"header_date\"/>\n                            </td>\n                        </tr>\n                    </tbody>\n                </table>\n            </td>\n        </tr>\n    </tbody>\n</table>\n<table cellspacing=\"0\" cellpadding=\"0\" border=\"0\" style=\"width: 100%;background-color: #F9FAFB;\">\n    <tbody>\n        <tr>\n            <td align=\"center\">\n                <table cellspacing=\"0\" cellpadding=\"0\" border=\"0\" class=\"global_layout\">\n                    <tbody>\n                        <tr t-if=\"tips\" t-foreach=\"tips\" t-as=\"tip\">\n                            <td colspan=\"3\" style=\"width: 100%;padding: 20px;border: 1px solid #F9FAFB;\">\n                                <table>\n                                    <tbody>\n                                        <tr>\n                                            <td t-out=\"tip\"/>\n                                        </tr>\n                                    </tbody>\n                                </table>\n                            </td>\n                        </tr>\n                        <tr t-if=\"kpi_data\">\n                            <td style=\"padding: 20px 20px 0px 20px;\" class=\"global_td\">\n                                <table t-foreach=\"kpi_data\" t-as=\"kpi_info\" style=\"width: 100%;\" cellspacing=\"0\" cellpadding=\"0\">\n                                    <tr>\n                                        <td style=\"padding-bottom: 20px;\">\n                                            <table t-if=\"kpi_info.get(''kpi_col1'') or kpi_info.get(''kpi_col2'') or kpi_info.get(''kpi_col3'')\" t-att-data-field=\"kpi_info[''kpi_name'']\" cellspacing=\"0\" cellpadding=\"10\" style=\"width: 100%;margin-bottom: 5px;\">\n                                                <tr class=\"kpi_header\">\n                                                    <td colspan=\"2\" style=\"padding: 0px 0px 5px 0px;\">\n                                                        <span style=\"text-transform: uppercase;\" t-esc=\"kpi_info[''kpi_fullname'']\"/>\n                                                    </td>\n                                                    <td t-if=\"kpi_info[''kpi_action'']\" align=\"right\" style=\"padding: 0px 0px 5px 0px;\">\n                                                        <table>\n                                                            <tbody>\n                                                                <tr>\n                                                                    <td class=\"td_button td_button_open_report\" style=\"padding: 1px 5px;height: 24px;\">\n                                                                        <a t-att-href=\"''/web#action=%s'' % kpi_info[''kpi_action'']\">\n                                                                            <span class=\"button\" id=\"button_open_report\">➔ Open Report</span>\n                                                                        </a>\n                                                                    </td>\n                                                                </tr>\n                                                            </tbody>\n                                                        </table>\n                                                    </td>\n                                                </tr>\n                                                <tr style=\"vertical-align: top;\">\n                                                    <td t-if=\"kpi_info.get(''kpi_col1'')\" class=\"kpi_cell\" style=\"padding-top: 10px; border-top: 1px solid #e6e6e6;\">\n                                                        <div t-call=\"digest.digest_tool_kpi\">\n                                                            <t t-set=\"kpi_value\" t-value=\"kpi_info[''kpi_col1''][''value'']\"/>\n                                                            <t t-set=\"kpi_margin\" t-value=\"kpi_info[''kpi_col1''].get(''margin'')\"/>\n                                                            <t t-set=\"kpi_subtitle\" t-value=\"kpi_info[''kpi_col1''][''col_subtitle'']\"/>\n                                                        </div>\n                                                    </td>\n                                                    <td t-if=\"kpi_info.get(''kpi_col2'')\" class=\"kpi_cell\" style=\"padding-top: 10px; border-top: 1px solid #e6e6e6;\">\n                                                        <div t-call=\"digest.digest_tool_kpi\">\n                                                            <t t-set=\"kpi_value\" t-value=\"kpi_info[''kpi_col2''][''value'']\"/>\n                                                            <t t-set=\"kpi_margin\" t-value=\"kpi_info[''kpi_col2''].get(''margin'')\"/>\n                                                            <t t-set=\"kpi_subtitle\" t-value=\"kpi_info[''kpi_col2''][''col_subtitle'']\"/>\n                                                        </div>\n                                                    </td>\n                                                    <td t-if=\"kpi_info.get(''kpi_col3'')\" class=\"kpi_cell\" style=\"padding-top: 10px; border-top: 1px solid #e6e6e6;\">\n                                                        <div t-call=\"digest.digest_tool_kpi\">\n                                                            <t t-set=\"kpi_value\" t-value=\"kpi_info[''kpi_col3''][''value'']\"/>\n                                                            <t t-set=\"kpi_margin\" t-value=\"kpi_info[''kpi_col3''].get(''margin'')\"/>\n                                                            <t t-set=\"kpi_subtitle\" t-value=\"kpi_info[''kpi_col3''][''col_subtitle'']\"/>\n                                                        </div>\n                                                    </td>\n                                                </tr>\n                                            </table>\n                                        </td>\n                                    </tr>\n                                </table>\n                            </td>\n                        </tr>\n                        <tr t-if=\"body\">\n                            <td style=\"padding: 20px 20px 0px 20px;\" class=\"global_td\"><t t-out=\"body\"/></td>\n                        </tr>\n                    </tbody>\n                    <tfoot>\n                        <tr>\n                            <td style=\"padding: 20px; border-bottom: 1px solid #d8dadd;\">\n                                <table border=\"0\" width=\"100%\">\n                                    <tbody>\n                                        <tr style=\"background-color: #F9FAFB;\">\n                                            <td align=\"center\" colspan=\"3\" valign=\"center\" style=\"padding: 15px;\">\n                                                <div t-if=\"preferences\" t-foreach=\"preferences\" t-as=\"preference\" class=\"preference\">\n                                                    <t t-out=\"preference\"/>\n                                                </div>\n                                                <div class=\"by_odoo\" style=\"margin-bottom: 15px;\">\n                                                    Sent by <a href=\"https://www.odoo.com\" target=\"_blank\">\n                                                    <span class=\"odoo_link_text\">Odoo</span></a>\n                                                    <t t-if=\"unsubscribe_token\">\n                                                        –\n                                                        <a t-attf-href=\"/digest/#{object.id}/unsubscribe?token=#{unsubscribe_token}&amp;user_id=#{user.id}\" target=\"_blank\" style=\"text-decoration: none;\">\n                                                            <span style=\"color: #878d97;\">Unsubscribe</span>\n                                                        </a>\n                                                    </t>\n                                                    <t t-elif=\"object and object._name == ''digest.digest''\">\n                                                        –\n                                                        <a t-att-href=\"''/web#view_type=form&amp;model=digest.digest&amp;id=%s'' % object.id\" target=\"_blank\" style=\"text-decoration: none;\">\n                                                            <span style=\"color: #878d97;\">Unsubscribe</span>\n                                                        </a>\n                                                    </t>\n                                                </div>\n                                            </td>\n                                        </tr>\n                                    </tbody>\n                                </table>\n                            </td>\n                        </tr>\n                        <tr t-if=\"display_mobile_banner\" t-call=\"digest.digest_section_mobile\"/>\n                    </tfoot>\n                </table>\n            </td>\n        </tr>\n    </tbody>\n    <tfoot>\n        <tr>\n            <td align=\"center\" style=\"padding: 20px 0px 0px 0px;\">\n                <table align=\"center\">\n                    <tbody>\n                        <tr>\n                            <div id=\"footer\">\n                                <p style=\"font-weight: bold;\" t-esc=\"company.name\"/>\n                                <p class=\"by_odoo\" id=\"powered\">\n                                    Powered by <a href=\"https://www.odoo.com\" target=\"_blank\" class=\"odoo_link\">\n                                        <span class=\"odoo_link_text\">Odoo</span></a>\n                                </p>\n                            </div>\n                        </tr>\n                    </tbody>\n                </table>\n            </td>\n        </tr>\n    </tfoot>\n</table>\n    </t>"}', '<?xml version="1.0"?>
<t t-name="digest.digest_mail_main">
