INSERT INTO public.ir_ui_view VALUES (593, 16, NULL, 1, 1, 'digest_section_mobile', NULL, 'digest.digest_section_mobile', 'qweb', 'digest/data/digest_data.xml', 'primary', '{"en_US": "<t t-name=\"digest.digest_section_mobile\">\n<td colspan=\"3\" style=\"padding: 20px;width:100%; border-bottom: 1px solid #d8dadd;\">\n    <table>\n        <tbody>\n            <tr>\n                <td align=\"right\" style=\"width: 33%;\">\n                    <img src=\"https://www.odoo.com/web/image/38874595-16ef5349/odoo-mobile.png\" alt=\"Odoo Mobile\"/>\n                </td>\n                <td align=\"left\" style=\"width: 66%;\">\n                    <table>\n                        <tbody>\n                            <tr>\n                                <td>\n                                    <p class=\"run_business\">Run your business from anywhere with <b>Odoo Mobile</b>.</p>\n                                </td>\n                            </tr>\n                            <tr>\n                                <td>\n                                    <a href=\"https://play.google.com/store/apps/details?id=com.odoo.mobile\" target=\"_blank\">\n                                            <img class=\"download_app\" height=\"40\" width=\"135\" src=\"https://download.odoocdn.com/digests/digest/static/src/img/google_play.png\"/>\n                                    </a>\n                                </td>\n                            </tr>\n                            <tr>\n                                <td>\n                                    <a href=\"https://itunes.apple.com/us/app/odoo/id1272543640\" target=\"_blank\">\n                                        <img class=\"download_app\" height=\"40\" width=\"135\" src=\"https://download.odoocdn.com/digests/digest/static/src/img/app_store.png\"/>\n                                    </a>\n                                </td>\n                            </tr>\n                        </tbody>\n                    </table>\n                </td>\n            </tr>\n        </tbody>\n    </table>\n</td>\n    </t>"}', '<?xml version="1.0"?>
<t t-name="digest.digest_section_mobile">
<td colspan="3" style="padding: 20px;width:100%; border-bottom: 1px solid #d8dadd;">
    <table>
        <tbody>
