INSERT INTO public.ir_ui_view VALUES (594, 16, NULL, 1, 1, 'digest_tool_kpi', NULL, 'digest.digest_tool_kpi', 'qweb', 'digest/data/digest_data.xml', 'primary', '{"en_US": "<t t-name=\"digest.digest_tool_kpi\">\n<span t-esc=\"kpi_value\" style=\"color: #374151;text-decoration: none;\" class=\"kpi_value kpi_border_col\"/>\n<br/>\n<span t-esc=\"kpi_subtitle\" class=\"kpi_value_label\"/>\n<table t-if=\"kpi_margin\" class=\"kpi_margin_margin\" align=\"center\" border=\"0\" cellspacing=\"0\" cellpadding=\"0\">\n    <tr>\n        <td t-if=\"kpi_margin &gt; 0.0\" class=\"kpi_margin positive_kpi_margin\" style=\"padding: 3px 10px;font-size: 12px;text-decoration: none;border-radius: 50px;border: 1px solid #c4ecd7;border-radius: 5px; background-color: #c4ecd7;color: #17613a;\">\n            ⬆ <t t-esc=\"''%.2f'' % kpi_margin\"/> %\n        </td>\n        <td t-elif=\"kpi_margin &lt; 0.0\" class=\"kpi_margin negative_kpi_margin\" style=\"padding: 3px 10px;font-size: 12px;text-decoration: none;border-radius: 50px;border: 1px solid #f4cfce;background-color: #f7dddc;color: #712b29;\">\n            ⬇ <t t-esc=\"''%.2f'' % kpi_margin\"/> %\n        </td>\n    </tr>\n</table>\n    </t>"}', '<?xml version="1.0"?>
<t t-name="digest.digest_tool_kpi">
<span t-esc="kpi_value" style="color: #374151;text-decoration: none;" class="kpi_value kpi_border_col"/>
<br/>
<span t-esc="kpi_subtitle" class="kpi_value_label"/>
<table t-if="kpi_margin" class="kpi_margin_margin" align="center" border="0" cellspacing="0" cellpadding="0">
    <tr>
        <td t-if="kpi_margin &gt; 0.0" class="kpi_margin positive_kpi_margin" style="padding: 3px 10px;font-size: 12px;text-decoration: none;border-radius: 50px;border: 1px solid #c4ecd7;border-radius: 5px; background-color: #c4ecd7;color: #17613a;">
            ⬆ <t t-esc="''%.2f'' % kpi_margin"/> %
        </td>
        <td t-elif="kpi_margin &lt; 0.0" class="kpi_margin negative_kpi_margin" style="padding: 3px 10px;font-size: 12px;text-decoration: none;border-radius: 50px;border: 1px solid #f4cfce;background-color: #f7dddc;color: #712b29;">
            ⬇ <t t-esc="''%.2f'' % kpi_margin"/> %
        </td>
    </tr>
</table>
    </t>

', false, true, '2026-05-10 01:11:54.58877', '2026-05-10 01:11:54.58877', false);
INSERT INTO public.ir_ui_view VALUES (595, 16, NULL, 1, 1, 'digest.digest.view.tree', 'digest.digest', NULL, 'tree', 'digest/views/digest_views.xml', 'primary', '{"en_US": "<tree string=\"KPI Digest\">\n                <field name=\"name\" string=\"Title\"/>\n                <field name=\"periodicity\"/>\n                <field name=\"next_run_date\" groups=\"base.group_no_one\"/>\n                <field name=\"company_id\" groups=\"base.group_multi_company\"/>\n                <field name=\"state\" groups=\"base.group_no_one\" widget=\"badge\" decoration-success=\"state == ''activated''\"/>\n            </tree>"}', '<?xml version="1.0"?>
<tree string="KPI Digest">
                <field name="name" string="Title"/>
                <field name="periodicity"/>
                <field name="next_run_date" groups="base.group_no_one"/>
                <field name="company_id" groups="base.group_multi_company"/>
                <field name="state" groups="base.group_no_one" widget="badge" decoration-success="state == ''activated''"/>
            </tree>
        ', false, true, '2026-05-10 01:11:54.58877', '2026-05-10 01:11:54.58877', false);
INSERT INTO public.ir_ui_view VALUES (596, 16, NULL, 1, 1, 'digest.digest.view.form', 'digest.digest', NULL, 'form', 'digest/views/digest_views.xml', 'primary', '{"en_US": "<form string=\"KPI Digest\">\n                <field name=\"is_subscribed\" invisible=\"1\"/>\n                <header>\n                    <button type=\"object\" name=\"action_send_manual\" string=\"Send Now\" class=\"oe_highlight\" invisible=\"state == ''deactivated''\" groups=\"base.group_system\"/>\n                    <button type=\"object\" name=\"action_deactivate\" string=\"Deactivate\" invisible=\"state == ''deactivated''\" groups=\"base.group_system\"/>\n                    <button type=\"object\" name=\"action_activate\" string=\"Activate\" class=\"oe_highlight\" invisible=\"state == ''activated''\" groups=\"base.group_system\"/>\n                    <field name=\"state\" widget=\"statusbar\" statusbar_visible=\"0\"/>\n                </header>\n                <sheet>\n                    <div class=\"oe_title\">\n                        <label for=\"name\" string=\"Digest Title\"/>\n                        <h1>\n                            <field name=\"name\" placeholder=\"e.g. Your Weekly Digest\"/>\n                        </h1>\n                    </div>\n                    <group>\n                        <group>\n                            <field name=\"periodicity\" widget=\"radio\" options=\"{''horizontal'': true}\"/>\n                            <field name=\"company_id\" options=\"{''no_create'': True}\" invisible=\"1\"/>\n                        </group>\n                        <group>\n                            <field name=\"next_run_date\" groups=\"base.group_system\"/>\n                        </group>\n                    </group>\n                    <notebook>\n                        <page name=\"kpis\" string=\"KPIs\">\n                            <group name=\"kpis\">\n                                <group name=\"kpi_general\" string=\"General\" groups=\"base.group_system\">\n                                    <field name=\"kpi_res_users_connected\"/>\n                                    <field name=\"kpi_mail_message_total\"/>\n                                </group>\n                                <group name=\"kpi_sales\"/>\n                                <group name=\"custom\" string=\"Custom\" groups=\"base.group_system\">\n                                    <div colspan=\"2\">\n                                        <p>Want to add your own KPIs?<br/>\n                                        <a href=\"https://www.odoo.com/documentation/17.0/applications/general/digest_emails.html#custom-digest-emails\" target=\"_blank\"><i class=\"oi oi-arrow-right\"/> Check our Documentation</a></p>\n                                    </div>\n                                </group>\n                            </group>\n                        </page>\n                        <page name=\"recipients\" string=\"Recipients\" groups=\"base.group_system\">\n                            <field name=\"user_ids\" options=\"{''no_create'': True}\">\n                                <tree string=\"Recipients\">\n                                    <field name=\"name\"/>\n                                    <field name=\"email\" string=\"Email Address\"/>\n                                </tree>\n                            </field>\n                        </page>\n                    </notebook>\n                </sheet>\n            </form>"}', '<?xml version="1.0"?>
<form string="KPI Digest">
                <field name="is_subscribed" invisible="1"/>
                <header>
                    <button type="object" name="action_send_manual" string="Send Now" class="oe_highlight" invisible="state == ''deactivated''" groups="base.group_system"/>
                    <button type="object" name="action_deactivate" string="Deactivate" invisible="state == ''deactivated''" groups="base.group_system"/>
                    <button type="object" name="action_activate" string="Activate" class="oe_highlight" invisible="state == ''activated''" groups="base.group_system"/>
                    <field name="state" widget="statusbar" statusbar_visible="0"/>
                </header>
                <sheet>
                    <div class="oe_title">
                        <label for="name" string="Digest Title"/>
                        <h1>
                            <field name="name" placeholder="e.g. Your Weekly Digest"/>
                        </h1>
                    </div>
                    <group>
                        <group>
                            <field name="periodicity" widget="radio" options="{''horizontal'': true}"/>
                            <field name="company_id" options="{''no_create'': True}" invisible="1"/>
                        </group>
                        <group>
                            <field name="next_run_date" groups="base.group_system"/>
                        </group>
                    </group>
                    <notebook>
                        <page name="kpis" string="KPIs">
                            <group name="kpis">
                                <group name="kpi_general" string="General" groups="base.group_system">
                                    <field name="kpi_res_users_connected"/>
                                    <field name="kpi_mail_message_total"/>
                                </group>
                                <group name="kpi_sales"/>
                                <group name="custom" string="Custom" groups="base.group_system">
                                    <div colspan="2">
                                        <p>Want to add your own KPIs?<br/>
                                        <a href="https://www.odoo.com/documentation/17.0/applications/general/digest_emails.html#custom-digest-emails" target="_blank"><i class="oi oi-arrow-right"/> Check our Documentation</a></p>
                                    </div>
                                </group>
                            </group>
                        </page>
                        <page name="recipients" string="Recipients" groups="base.group_system">
                            <field name="user_ids" options="{''no_create'': True}">
                                <tree string="Recipients">
                                    <field name="name"/>
                                    <field name="email" string="Email Address"/>
                                </tree>
                            </field>
                        </page>
                    </notebook>
                </sheet>
            </form>
        ', false, true, '2026-05-10 01:11:54.58877', '2026-05-10 01:11:54.58877', false);
INSERT INTO public.ir_ui_view VALUES (597, 16, NULL, 1, 1, 'digest.digest.view.search', 'digest.digest', NULL, 'search', 'digest/views/digest_views.xml', 'primary', '{"en_US": "<search>\n                <field name=\"name\"/>\n                <field name=\"user_ids\"/>\n                <filter name=\"filter_activated\" string=\"Activated\" domain=\"[(''state'', ''='', ''activated'')]\"/>\n                <filter name=\"filter_deactivated\" string=\"Deactivated\" domain=\"[(''state'', ''='', ''deactivated'')]\"/>\n                <group expand=\"1\" string=\"Group by\">\n                    <filter string=\"Periodicity\" name=\"periodicity\" context=\"{''group_by'': ''periodicity''}\"/>\n                </group>\n            </search>"}', '<?xml version="1.0"?>
<search>
                <field name="name"/>
                <field name="user_ids"/>
                <filter name="filter_activated" string="Activated" domain="[(''state'', ''='', ''activated'')]"/>
                <filter name="filter_deactivated" string="Deactivated" domain="[(''state'', ''='', ''deactivated'')]"/>
                <group expand="1" string="Group by">
                    <filter string="Periodicity" name="periodicity" context="{''group_by'': ''periodicity''}"/>
                </group>
            </search>
        ', false, true, '2026-05-10 01:11:54.58877', '2026-05-10 01:11:54.58877', false);
