INSERT INTO public.ir_ui_view VALUES (601, 16, NULL, 1, 1, 'Unsubscription', NULL, 'digest.portal_digest_unsubscribed', 'qweb', 'digest/views/digest_templates.xml', 'primary', '{"en_US": "<t name=\"Unsubscription\" t-name=\"digest.portal_digest_unsubscribed\">\n        <t t-call=\"portal.portal_layout\">\n            <div class=\"container mt8\">\n                <div class=\"row\">\n                    <div class=\"col-lg-6 offset-lg-3\">\n                        <h3>Digest Subscriptions</h3>\n                        <div class=\"alert alert-success text-center\" role=\"status\">\n                            <p>You have been successfully unsubscribed from:<br/>\n                            <strong t-field=\"digest.name\"/></p>\n                        </div>\n                    </div>\n                </div>\n            </div>\n        </t>\n    </t>"}', '<?xml version="1.0"?>
<t name="Unsubscription" t-name="digest.portal_digest_unsubscribed">
        <t t-call="portal.portal_layout">
            <div class="container mt8">
                <div class="row">
                    <div class="col-lg-6 offset-lg-3">
                        <h3>Digest Subscriptions</h3>
                        <div class="alert alert-success text-center" role="status">
                            <p>You have been successfully unsubscribed from:<br/>
                            <strong t-field="digest.name"/></p>
                        </div>
                    </div>
                </div>
            </div>
        </t>
    </t>
', false, true, '2026-05-10 01:11:54.58877', '2026-05-10 01:11:54.58877', false);
INSERT INTO public.ir_ui_view VALUES (602, 16, 223, 1, 1, 'res.config.settings.view.form.inherit.digest', 'res.config.settings', NULL, 'form', 'digest/views/res_config_settings_views.xml', 'extension', '{"en_US": "<xpath expr=\"//div[@id=''contacts_settings'']\" position=\"before\">\n                <div id=\"statistics\">\n                    <block title=\"Statistics\" id=\"statistics_div\">\n                        <setting string=\"Digest Email\" help=\"Add new users as recipient of a periodic email with key metrics\" documentation=\"/applications/general/digest_emails.html\" title=\"New users are automatically added as recipient of the following digest email.\" name=\"digest_email_setting_container\">\n                            <field name=\"digest_emails\"/>\n                            <div class=\"content-group\" invisible=\"not digest_emails\">\n                                <div class=\"mt16\">\n                                    <label for=\"digest_id\" class=\"o_light_label mr8\"/>\n                                    <field name=\"digest_id\" class=\"oe_inline\"/>\n                                </div>\n                                <div class=\"mt8\">\n                                    <button type=\"action\" name=\"212\" string=\"Configure Digest Emails\" icon=\"oi-arrow-right\" class=\"btn-link\"/>\n                                </div>\n                            </div>\n                        </setting>\n                    </block>\n                </div>\n            </xpath>"}', '<?xml version="1.0"?>
<xpath expr="//div[@id=''contacts_settings'']" position="before">
                <div id="statistics">
                    <block title="Statistics" id="statistics_div">
                        <setting string="Digest Email" help="Add new users as recipient of a periodic email with key metrics" documentation="/applications/general/digest_emails.html" title="New users are automatically added as recipient of the following digest email." name="digest_email_setting_container">
                            <field name="digest_emails"/>
                            <div class="content-group" invisible="not digest_emails">
                                <div class="mt16">
                                    <label for="digest_id" class="o_light_label mr8"/>
                                    <field name="digest_id" class="oe_inline"/>
                                </div>
                                <div class="mt8">
                                    <button type="action" name="212" string="Configure Digest Emails" icon="oi-arrow-right" class="btn-link"/>
                                </div>
                            </div>
                        </setting>
                    </block>
                </div>
            </xpath>
        ', false, true, '2026-05-10 01:11:54.58877', '2026-05-10 01:11:54.58877', false);
INSERT INTO public.ir_ui_view VALUES (603, 16, NULL, 1, 1, 'Payment Express Checkout', NULL, 'payment.express_checkout', 'qweb', 'payment/views/express_checkout_templates.xml', 'primary', '{"en_US": "<t name=\"Payment Express Checkout\" t-name=\"payment.express_checkout\">\n        <!-- Parameters description:\n            - reference_prefix: The custom prefix to compute the full transaction reference.\n            - amount: The amount to pay.\n            - minor_amount: The amount to pay in the minor units of its currency.\n            - currency: The currency of the payment, as a `res.currency` record.\n            - providers_sudo: The compatible providers, as a sudoed `payment.provider` recordset.\n            - merchant_name: The merchant name.\n            - payment_method_unknown_id: The ID of the \"Unknown\" payment method record, to use as\n                                         the generic express checkout method.\n            - payment_access_token: The access token used to authenticate the partner. Since this\n                                    template is loaded in the shopping cart, this parameter is\n                                    called `payment_access_token` to prevent mixing up with the\n                                    `access_token` used for abandoned carts.\n            - shipping_info_required: Whether the shipping information is required or not.\n            - transaction_route: The route used to create a transaction when the user clicks Pay.\n            - shipping_address_update_route: The route where available carriers are computed based\n                                             on the (partial) shipping information available.\n                                             Optional.\n            - express_checkout_route: The route where the billing and shipping information are sent.\n            - landing_route: The route the user is redirected to after the transaction.\n            - payment_access_token: The access token used to authenticate the partner. Since this\n                                    template is loaded in the shopping cart, this parameter is\n                                    called `payment_access_token` to prevent mixing up with the\n                                    `access_token` used for abandoned carts.\n        -->\n        <form name=\"o_payment_express_checkout_form\" class=\"container\" t-att-data-reference-prefix=\"reference_prefix\" t-att-data-amount=\"amount\" t-att-data-minor-amount=\"minor_amount\" t-att-data-currency-id=\"currency and currency.id\" t-att-data-currency-name=\"currency.name.lower()\" t-att-data-merchant-name=\"merchant_name\" t-att-data-partner-id=\"partner_id\" t-att-data-payment-method-unknown-id=\"payment_method_unknown_id\" t-att-data-access-token=\"payment_access_token\" t-att-data-shipping-info-required=\"shipping_info_required\" t-att-data-transaction-route=\"transaction_route\" t-att-data-shipping-address-update-route=\"shipping_address_update_route\" t-att-data-express-checkout-route=\"express_checkout_route\" t-att-data-landing-route=\"landing_route\">\n            <t t-set=\"provider_sudo\" t-value=\"providers_sudo[:1]\"/>\n            <t t-set=\"express_checkout_form_xml_id\" t-value=\"provider_sudo.express_checkout_form_view_id.xml_id\"/>\n            <t t-if=\"express_checkout_form_xml_id\">\n                <t t-call=\"{{express_checkout_form_xml_id}}\"/>\n            </t>\n        </form>\n    </t>"}', '<?xml version="1.0"?>
<t name="Payment Express Checkout" t-name="payment.express_checkout">
        <!-- Parameters description:
            - reference_prefix: The custom prefix to compute the full transaction reference.
            - amount: The amount to pay.
            - minor_amount: The amount to pay in the minor units of its currency.
            - currency: The currency of the payment, as a `res.currency` record.
            - providers_sudo: The compatible providers, as a sudoed `payment.provider` recordset.
            - merchant_name: The merchant name.
            - payment_method_unknown_id: The ID of the "Unknown" payment method record, to use as
                                         the generic express checkout method.
            - payment_access_token: The access token used to authenticate the partner. Since this
                                    template is loaded in the shopping cart, this parameter is
                                    called `payment_access_token` to prevent mixing up with the
                                    `access_token` used for abandoned carts.
            - shipping_info_required: Whether the shipping information is required or not.
            - transaction_route: The route used to create a transaction when the user clicks Pay.
            - shipping_address_update_route: The route where available carriers are computed based
                                             on the (partial) shipping information available.
                                             Optional.
            - express_checkout_route: The route where the billing and shipping information are sent.
            - landing_route: The route the user is redirected to after the transaction.
            - payment_access_token: The access token used to authenticate the partner. Since this
                                    template is loaded in the shopping cart, this parameter is
                                    called `payment_access_token` to prevent mixing up with the
                                    `access_token` used for abandoned carts.
        -->
        <form name="o_payment_express_checkout_form" class="container" t-att-data-reference-prefix="reference_prefix" t-att-data-amount="amount" t-att-data-minor-amount="minor_amount" t-att-data-currency-id="currency and currency.id" t-att-data-currency-name="currency.name.lower()" t-att-data-merchant-name="merchant_name" t-att-data-partner-id="partner_id" t-att-data-payment-method-unknown-id="payment_method_unknown_id" t-att-data-access-token="payment_access_token" t-att-data-shipping-info-required="shipping_info_required" t-att-data-transaction-route="transaction_route" t-att-data-shipping-address-update-route="shipping_address_update_route" t-att-data-express-checkout-route="express_checkout_route" t-att-data-landing-route="landing_route">
            <t t-set="provider_sudo" t-value="providers_sudo[:1]"/>
            <t t-set="express_checkout_form_xml_id" t-value="provider_sudo.express_checkout_form_view_id.xml_id"/>
            <t t-if="express_checkout_form_xml_id">
                <t t-call="{{express_checkout_form_xml_id}}"/>
            </t>
        </form>
    </t>

', false, true, '2026-05-10 01:11:54.802158', '2026-05-10 01:11:54.802158', false);
INSERT INTO public.ir_ui_view VALUES (604, 16, NULL, 1, 1, 'Payment Form', NULL, 'payment.form', 'qweb', 'payment/views/payment_form_templates.xml', 'primary', '{"en_US": "<t name=\"Payment Form\" t-name=\"payment.form\">\n        <!-- Form customization parameters:\n            - mode: The operation mode of the form: `payment` or `validation`; default: `payment`.\n            - allow_token_selection: Whether tokens can be selected for payment or assignation\n                                     (through the `assign_token_route` parameter); default: `True`.\n            - allow_token_deletion: Whether tokens can be deleted (archived); default: `False`.\n            - default_token_id: The id of the token that should be pre-selected; default: `None`.\n            - show_tokenize_input_mapping: For each provider, whether the tokenization checkbox is\n                                           shown; used only in `payment` mode.\n            - display_submit_button: Whether the submit button is displayed; default: `True`.\n            - submit_button_label: The label of the submit button; default: ''Pay''/''Save''.\n        -->\n        <!-- Payment context:\n            - reference_prefix: The custom prefix to compute the full transaction reference.\n            - amount: The amount to pay.\n            - currency: The currency of the payment, as a `res.currency` record.\n            - partner_id: The id of the partner on behalf of whom the payment should be made.\n            - providers_sudo: The compatible providers, as a sudoed `payment.provider` recordset.\n            - payment_methods_sudo: The compatible payment methods, as a sudoed `payment.method`\n                                    recordset.\n            - tokens_sudo: The available payment tokens, as a sudoed `payment.token` recordset.\n            - transaction_route: The route to call to create the transaction.\n            - assign_token_route: The route to call to assign a new or existing token to a record.\n            - landing_route: The route the user is redirected to after payment.\n            - access_token: The access token used to authenticate the partner.\n        -->\n        <t t-set=\"mode\" t-value=\"mode or ''payment''\"/>\n        <t t-set=\"allow_token_selection\" t-value=\"True if allow_token_selection is None else allow_token_selection\"/>\n        <t t-set=\"allow_token_deletion\" t-value=\"allow_token_deletion or False\"/>\n        <t t-set=\"selected_token_id\" t-value=\"allow_token_selection and (default_token_id or tokens_sudo[:1].id)\"/>\n        <t t-set=\"selected_method_id\" t-value=\"not selected_token_id                     and len(payment_methods_sudo) == 1                     and payment_methods_sudo[:1].id\"/>\n        <t t-set=\"collapse_payment_methods\" t-value=\"tokens_sudo and allow_token_selection and payment_methods_sudo\"/>\n        <t t-set=\"display_submit_button\" t-value=\"True if display_submit_button is None else display_submit_button\"/>\n        <t t-set=\"pay_label\">Pay</t> <!-- Allow translating the label. -->\n        <t t-set=\"save_label\">Save</t> <!-- Allow translating the label. -->\n        <t t-set=\"submit_button_label\" t-value=\"submit_button_label or (pay_label if mode == ''payment'' else save_label)\"/>\n        <form id=\"o_payment_form\" class=\"o_payment_form\" t-att-data-mode=\"mode\" t-att-data-reference-prefix=\"reference_prefix\" t-att-data-amount=\"amount\" t-att-data-currency-id=\"currency and currency.id\" t-att-data-partner-id=\"partner_id\" t-att-data-transaction-route=\"transaction_route\" t-att-data-assign-token-route=\"assign_token_route\" t-att-data-landing-route=\"landing_route\" t-att-data-access-token=\"access_token\">\n            <div id=\"o_payment_form_options\" class=\"d-flex flex-column gap-3\">\n                <!-- === Payment tokens === -->\n                <div t-if=\"tokens_sudo\">\n                    <!-- === Header === -->\n                    <h4 id=\"o_payment_tokens_heading\" class=\"fs-6 small text-uppercase fw-bolder\">\n                        Your payment methods\n                    </h4>\n                    <!-- === Body === -->\n                    <ul class=\"list-group\">\n                        <t t-foreach=\"tokens_sudo\" t-as=\"token_sudo\">\n                            <li name=\"o_payment_option\" t-att-class=\"''list-group-item d-flex flex-column gap-2 py-3''                                              + ('' o_outline'' if allow_token_selection else '''')\">\n                                <t t-call=\"payment.token_form\">\n                                    <t t-set=\"is_selected\" t-value=\"token_sudo.id == selected_token_id\"/>\n                                </t>\n                            </li>\n                        </t>\n                    </ul>\n                </div>\n                <!-- === Payment methods === -->\n                <div t-if=\"payment_methods_sudo\" id=\"o_payment_methods\" t-att-class=\"''collapse'' if collapse_payment_methods else ''''\">\n                    <!-- === Header === -->\n                    <h4 class=\"fs-6 small text-uppercase fw-bolder\">\n                        <t t-if=\"not collapse_payment_methods\">Choose a payment method</t>\n                        <t t-else=\"\">Other payment methods</t>\n                    </h4>\n                    <!-- === Body === -->\n                    <ul class=\"list-group\">\n                        <t t-foreach=\"payment_methods_sudo\" t-as=\"pm_sudo\">\n                            <li name=\"o_payment_option\" class=\"list-group-item d-flex flex-column gap-2 py-3 o_outline\">\n                                <t t-call=\"payment.method_form\">\n                                    <t t-set=\"is_selected\" t-value=\"pm_sudo.id == selected_method_id\"/>\n                                </t>\n                            </li>\n                        </t>\n                    </ul>\n                </div>\n            </div>\n            <div class=\"d-flex justify-content-end flex-column flex-md-row gap-2 my-2\">\n                <!-- === Expand payment methods button === -->\n                <button t-if=\"collapse_payment_methods\" name=\"o_payment_expand_button\" type=\"button\" href=\"#o_payment_methods\" class=\"btn btn-link\" data-bs-toggle=\"collapse\">\n                    Choose another method <i class=\"oi oi-arrow-down\"/>\n                </button>\n                <!-- === Submit button === -->\n                <t t-if=\"display_submit_button\" t-call=\"payment.submit_button\"/>\n            </div>\n        </form>\n    </t>"}', '<?xml version="1.0"?>
<t name="Payment Form" t-name="payment.form">
        <!-- Form customization parameters:
            - mode: The operation mode of the form: `payment` or `validation`; default: `payment`.
            - allow_token_selection: Whether tokens can be selected for payment or assignation
                                     (through the `assign_token_route` parameter); default: `True`.
            - allow_token_deletion: Whether tokens can be deleted (archived); default: `False`.
            - default_token_id: The id of the token that should be pre-selected; default: `None`.
            - show_tokenize_input_mapping: For each provider, whether the tokenization checkbox is
                                           shown; used only in `payment` mode.
            - display_submit_button: Whether the submit button is displayed; default: `True`.
            - submit_button_label: The label of the submit button; default: ''Pay''/''Save''.
        -->
        <!-- Payment context:
            - reference_prefix: The custom prefix to compute the full transaction reference.
            - amount: The amount to pay.
            - currency: The currency of the payment, as a `res.currency` record.
            - partner_id: The id of the partner on behalf of whom the payment should be made.
            - providers_sudo: The compatible providers, as a sudoed `payment.provider` recordset.
            - payment_methods_sudo: The compatible payment methods, as a sudoed `payment.method`
                                    recordset.
            - tokens_sudo: The available payment tokens, as a sudoed `payment.token` recordset.
            - transaction_route: The route to call to create the transaction.
            - assign_token_route: The route to call to assign a new or existing token to a record.
            - landing_route: The route the user is redirected to after payment.
            - access_token: The access token used to authenticate the partner.
        -->
        <t t-set="mode" t-value="mode or ''payment''"/>
        <t t-set="allow_token_selection" t-value="True if allow_token_selection is None else allow_token_selection"/>
        <t t-set="allow_token_deletion" t-value="allow_token_deletion or False"/>
        <t t-set="selected_token_id" t-value="allow_token_selection and (default_token_id or tokens_sudo[:1].id)"/>
        <t t-set="selected_method_id" t-value="not selected_token_id                     and len(payment_methods_sudo) == 1                     and payment_methods_sudo[:1].id"/>
        <t t-set="collapse_payment_methods" t-value="tokens_sudo and allow_token_selection and payment_methods_sudo"/>
        <t t-set="display_submit_button" t-value="True if display_submit_button is None else display_submit_button"/>
        <t t-set="pay_label">Pay</t> <!-- Allow translating the label. -->
        <t t-set="save_label">Save</t> <!-- Allow translating the label. -->
        <t t-set="submit_button_label" t-value="submit_button_label or (pay_label if mode == ''payment'' else save_label)"/>
        <form id="o_payment_form" class="o_payment_form" t-att-data-mode="mode" t-att-data-reference-prefix="reference_prefix" t-att-data-amount="amount" t-att-data-currency-id="currency and currency.id" t-att-data-partner-id="partner_id" t-att-data-transaction-route="transaction_route" t-att-data-assign-token-route="assign_token_route" t-att-data-landing-route="landing_route" t-att-data-access-token="access_token">
            <div id="o_payment_form_options" class="d-flex flex-column gap-3">
                <!-- === Payment tokens === -->
                <div t-if="tokens_sudo">
                    <!-- === Header === -->
                    <h4 id="o_payment_tokens_heading" class="fs-6 small text-uppercase fw-bolder">
                        Your payment methods
                    </h4>
                    <!-- === Body === -->
                    <ul class="list-group">
                        <t t-foreach="tokens_sudo" t-as="token_sudo">
                            <li name="o_payment_option" t-att-class="''list-group-item d-flex flex-column gap-2 py-3''                                              + ('' o_outline'' if allow_token_selection else '''')">
                                <t t-call="payment.token_form">
                                    <t t-set="is_selected" t-value="token_sudo.id == selected_token_id"/>
                                </t>
                            </li>
                        </t>
                    </ul>
                </div>
                <!-- === Payment methods === -->
                <div t-if="payment_methods_sudo" id="o_payment_methods" t-att-class="''collapse'' if collapse_payment_methods else ''''">
                    <!-- === Header === -->
                    <h4 class="fs-6 small text-uppercase fw-bolder">
                        <t t-if="not collapse_payment_methods">Choose a payment method</t>
                        <t t-else="">Other payment methods</t>
                    </h4>
                    <!-- === Body === -->
                    <ul class="list-group">
                        <t t-foreach="payment_methods_sudo" t-as="pm_sudo">
                            <li name="o_payment_option" class="list-group-item d-flex flex-column gap-2 py-3 o_outline">
                                <t t-call="payment.method_form">
                                    <t t-set="is_selected" t-value="pm_sudo.id == selected_method_id"/>
                                </t>
                            </li>
                        </t>
                    </ul>
                </div>
            </div>
            <div class="d-flex justify-content-end flex-column flex-md-row gap-2 my-2">
                <!-- === Expand payment methods button === -->
                <button t-if="collapse_payment_methods" name="o_payment_expand_button" type="button" href="#o_payment_methods" class="btn btn-link" data-bs-toggle="collapse">
                    Choose another method <i class="oi oi-arrow-down"/>
                </button>
                <!-- === Submit button === -->
                <t t-if="display_submit_button" t-call="payment.submit_button"/>
            </div>
        </form>
    </t>

    ', false, true, '2026-05-10 01:11:54.802158', '2026-05-10 01:11:54.802158', false);
INSERT INTO public.ir_ui_view VALUES (605, 16, NULL, 1, 1, 'Payment Token Form', NULL, 'payment.token_form', 'qweb', 'payment/views/payment_form_templates.xml', 'primary', '{"en_US": "<t name=\"Payment Token Form\" t-name=\"payment.token_form\">\n        <!-- Parameters description:\n            - token_sudo: The token to display, as a sudoed `payment.token` recordset.\n            - allow_token_selection: Whether tokens can be selected for payment or assignation (if\n                                     the `assign_route` parameter is provided); default: `True`.\n            - is_selected: Whether the radio button of the token should be checked.\n        -->\n        <t t-set=\"provider_sudo\" t-value=\"token_sudo.provider_id\"/>\n        <t t-set=\"is_test\" t-value=\"provider_sudo.state == ''test''\"/>\n        <t t-set=\"is_unpublished\" t-value=\"not provider_sudo.is_published\"/>\n        <t t-set=\"inline_form_xml_id\" t-value=\"provider_sudo.token_inline_form_view_id.xml_id\"/>\n        <div class=\"d-flex gap-3 align-items-start align-items-md-center\">\n            <!-- === Delete button === -->\n            <button t-if=\"allow_token_deletion\" name=\"o_payment_delete_token\" t-att-class=\"''btn btn-link px-2 py-0 lh-lg z-index-1''                                  + ('' d-none'' if mode != ''validation'' else '''')\" t-attf-data-linked-radio=\"o_payment_token_{{token_sudo.id}}\">\n                <i class=\"fa fa-trash\" title=\"Delete payment method\" data-bs-toggle=\"tooltip\" data-bs-placement=\"top\" data-bs-delay=\"0\"/>\n            </button>\n            <div class=\"row flex-column flex-md-row flex-grow-1 gap-lg-3 align-items-start                         align-items-md-center\">\n                <div class=\"col col-lg-5\">\n                    <div t-att-class=\"''form-check mb-0''                                       + ('' ps-0'' if not allow_token_selection else '''')\">\n                        <!-- === Radio button === -->\n                        <input t-attf-id=\"o_payment_token_{{token_sudo.id}}\" name=\"o_payment_radio\" type=\"radio\" t-att-checked=\"is_selected\" t-att-disabled=\"not allow_token_selection\" t-att-class=\"''form-check-input''                                             + ('' d-none'' if not allow_token_selection else '''')\" data-payment-option-type=\"token\" t-att-data-payment-option-id=\"token_sudo.id\" t-att-data-provider-code=\"token_sudo.provider_id._get_code()\" t-att-data-provider-id=\"token_sudo.provider_id.id\"/>\n                        <div class=\"d-flex align-items-center flex-wrap gap-2\">\n                            <!-- === Token label === -->\n                            <label t-out=\"token_sudo.payment_method_id.name\" class=\"o_payment_option_label text-break\" t-attf-for=\"o_payment_token_{{token_sudo.id}}\"/>\n                            <div class=\"d-flex flex-nowrap gap-2\">\n                                <!-- === \"Unpublished\" icon === -->\n                                <t t-if=\"is_unpublished\" t-call=\"payment.form_icon\">\n                                    <t t-set=\"icon_name\" t-value=\"''eye-slash''\"/>\n                                    <t t-set=\"color_name\" t-value=\"''danger''\"/>\n                                    <t t-set=\"title\" t-value=\"''Unpublished''\"/>\n                                </t>\n                                <!-- === \"Test mode\" icon === -->\n                                <t t-if=\"is_test\" t-call=\"payment.form_icon\">\n                                    <t t-set=\"icon_name\" t-value=\"''exclamation-triangle''\"/>\n                                    <t t-set=\"color_name\" t-value=\"''warning''\"/>\n                                    <t t-set=\"title\" t-value=\"''Test mode''\"/>\n                                </t>\n                            </div>\n                        </div>\n                    </div>\n                </div>\n                <!-- === Token name (payment details) === -->\n                <div class=\"col\">\n                    <p t-out=\"token_sudo.display_name\" t-att-class=\"''mb-0 small fw-bold text-break''                                     + ('' ms-4 ms-md-0'' if allow_token_selection else '''')\"/>\n                </div>\n                <!-- === Provider name (only for desktop and tablet) === -->\n                <div class=\"col d-none d-md-block\">\n                    <p name=\"o_payment_secured_by_desktop\" t-att-class=\"''mb-0 small text-600''                                     + ('' ms-4 ms-md-0'' if allow_token_selection else '''')                                     + ('' d-none'' if provider_sudo.code == ''custom'' else '''')\">\n                        <span><i class=\"fa fa-lock\"/> Secured by</span>\n                        <span t-out=\"dict(provider_sudo._fields[''code'']._description_selection(                                          provider_sudo.env                                      ))[provider_sudo.code]\" class=\"text-break\"/>\n                    </p>\n                </div>\n            </div>\n            <!-- === Payment method logo === -->\n            <div t-call=\"payment.form_logo\">\n                <t t-set=\"logo_pm_sudo\" t-value=\"token_sudo.payment_method_id\"/>\n            </div>\n        </div>\n        <!-- === Inline form === -->\n        <div t-if=\"inline_form_xml_id\" name=\"o_payment_inline_form\" class=\"position-relative d-none\">\n            <t t-call=\"{{inline_form_xml_id}}\"/>\n        </div>\n        <!-- === Provider name (only for mobile) === -->\n        <p name=\"o_payment_secured_by_mobile\" t-att-class=\"''align-self-end d-block d-md-none mb-0 small text-600''                         + ('' d-none'' if provider_sudo.code == ''custom'' else '''')\">\n            <span><i class=\"fa fa-lock\"/> Secured by</span>\n            <span t-out=\"dict(provider_sudo._fields[''code'']._description_selection(                              provider_sudo.env                          ))[provider_sudo.code]\" class=\"text-break\"/>\n        </p>\n    </t>"}', '<?xml version="1.0"?>
<t name="Payment Token Form" t-name="payment.token_form">
        <!-- Parameters description:
            - token_sudo: The token to display, as a sudoed `payment.token` recordset.
            - allow_token_selection: Whether tokens can be selected for payment or assignation (if
                                     the `assign_route` parameter is provided); default: `True`.
            - is_selected: Whether the radio button of the token should be checked.
        -->
        <t t-set="provider_sudo" t-value="token_sudo.provider_id"/>
        <t t-set="is_test" t-value="provider_sudo.state == ''test''"/>
        <t t-set="is_unpublished" t-value="not provider_sudo.is_published"/>
        <t t-set="inline_form_xml_id" t-value="provider_sudo.token_inline_form_view_id.xml_id"/>
        <div class="d-flex gap-3 align-items-start align-items-md-center">
            <!-- === Delete button === -->
            <button t-if="allow_token_deletion" name="o_payment_delete_token" t-att-class="''btn btn-link px-2 py-0 lh-lg z-index-1''                                  + ('' d-none'' if mode != ''validation'' else '''')" t-attf-data-linked-radio="o_payment_token_{{token_sudo.id}}">
                <i class="fa fa-trash" title="Delete payment method" data-bs-toggle="tooltip" data-bs-placement="top" data-bs-delay="0"/>
            </button>
            <div class="row flex-column flex-md-row flex-grow-1 gap-lg-3 align-items-start                         align-items-md-center">
                <div class="col col-lg-5">
                    <div t-att-class="''form-check mb-0''                                       + ('' ps-0'' if not allow_token_selection else '''')">
                        <!-- === Radio button === -->
                        <input t-attf-id="o_payment_token_{{token_sudo.id}}" name="o_payment_radio" type="radio" t-att-checked="is_selected" t-att-disabled="not allow_token_selection" t-att-class="''form-check-input''                                             + ('' d-none'' if not allow_token_selection else '''')" data-payment-option-type="token" t-att-data-payment-option-id="token_sudo.id" t-att-data-provider-code="token_sudo.provider_id._get_code()" t-att-data-provider-id="token_sudo.provider_id.id"/>
                        <div class="d-flex align-items-center flex-wrap gap-2">
                            <!-- === Token label === -->
                            <label t-out="token_sudo.payment_method_id.name" class="o_payment_option_label text-break" t-attf-for="o_payment_token_{{token_sudo.id}}"/>
                            <div class="d-flex flex-nowrap gap-2">
                                <!-- === "Unpublished" icon === -->
                                <t t-if="is_unpublished" t-call="payment.form_icon">
                                    <t t-set="icon_name" t-value="''eye-slash''"/>
                                    <t t-set="color_name" t-value="''danger''"/>
                                    <t t-set="title" t-value="''Unpublished''"/>
                                </t>
                                <!-- === "Test mode" icon === -->
                                <t t-if="is_test" t-call="payment.form_icon">
                                    <t t-set="icon_name" t-value="''exclamation-triangle''"/>
                                    <t t-set="color_name" t-value="''warning''"/>
                                    <t t-set="title" t-value="''Test mode''"/>
                                </t>
                            </div>
                        </div>
                    </div>
                </div>
                <!-- === Token name (payment details) === -->
                <div class="col">
                    <p t-out="token_sudo.display_name" t-att-class="''mb-0 small fw-bold text-break''                                     + ('' ms-4 ms-md-0'' if allow_token_selection else '''')"/>
                </div>
                <!-- === Provider name (only for desktop and tablet) === -->
                <div class="col d-none d-md-block">
                    <p name="o_payment_secured_by_desktop" t-att-class="''mb-0 small text-600''                                     + ('' ms-4 ms-md-0'' if allow_token_selection else '''')                                     + ('' d-none'' if provider_sudo.code == ''custom'' else '''')">
                        <span><i class="fa fa-lock"/> Secured by</span>
                        <span t-out="dict(provider_sudo._fields[''code'']._description_selection(                                          provider_sudo.env                                      ))[provider_sudo.code]" class="text-break"/>
                    </p>
                </div>
            </div>
            <!-- === Payment method logo === -->
            <div t-call="payment.form_logo">
                <t t-set="logo_pm_sudo" t-value="token_sudo.payment_method_id"/>
            </div>
        </div>
        <!-- === Inline form === -->
        <div t-if="inline_form_xml_id" name="o_payment_inline_form" class="position-relative d-none">
            <t t-call="{{inline_form_xml_id}}"/>
        </div>
        <!-- === Provider name (only for mobile) === -->
        <p name="o_payment_secured_by_mobile" t-att-class="''align-self-end d-block d-md-none mb-0 small text-600''                         + ('' d-none'' if provider_sudo.code == ''custom'' else '''')">
            <span><i class="fa fa-lock"/> Secured by</span>
            <span t-out="dict(provider_sudo._fields[''code'']._description_selection(                              provider_sudo.env                          ))[provider_sudo.code]" class="text-break"/>
        </p>
    </t>

