    </t>

    ', false, true, '2026-05-10 01:11:54.802158', '2026-05-10 01:11:54.802158', false);
INSERT INTO public.ir_ui_view VALUES (608, 16, NULL, 1, 1, 'Form Logo', NULL, 'payment.form_logo', 'qweb', 'payment/views/payment_form_templates.xml', 'primary', '{"en_US": "<t name=\"Form Logo\" t-name=\"payment.form_logo\">\n        <!-- Parameters description:\n            - logo_pm_sudo: The payment method whose logo to display, as a sudoed `payment.method`\n                            record.\n        -->\n        <span t-field=\"logo_pm_sudo.image_payment_form\" t-options=\"{''widget'': ''image'', ''alt-field'': ''name''}\" class=\"position-relative d-block rounded overflow-hidden z-index-1 shadow-sm\" t-att-title=\"logo_pm_sudo.name\" data-bs-toggle=\"tooltip\" data-bs-placement=\"top\" data-bs-delay=\"0\"/>\n    </t>"}', '<?xml version="1.0"?>
<t name="Form Logo" t-name="payment.form_logo">
