        <span t-field="logo_pm_sudo.image_payment_form" t-options="{''widget'': ''image'', ''alt-field'': ''name''}" class="position-relative d-block rounded overflow-hidden z-index-1 shadow-sm" t-att-title="logo_pm_sudo.name" data-bs-toggle="tooltip" data-bs-placement="top" data-bs-delay="0"/>
    </t>

    ', false, true, '2026-05-10 01:11:54.802158', '2026-05-10 01:11:54.802158', false);
INSERT INTO public.ir_ui_view VALUES (609, 16, NULL, 1, 1, 'Submit Button', NULL, 'payment.submit_button', 'qweb', 'payment/views/payment_form_templates.xml', 'primary', '{"en_US": "<t name=\"Submit Button\" t-name=\"payment.submit_button\">\n        <!-- Parameters description:\n            - label: The label of the submit button.\n        -->\n        <button name=\"o_payment_submit_button\" type=\"submit\" t-out=\"submit_button_label\" class=\"btn btn-primary w-100 w-md-auto ms-auto px-5\" disabled=\"true\"/>\n    </t>"}', '<?xml version="1.0"?>
<t name="Submit Button" t-name="payment.submit_button">
