INSERT INTO public.ir_ui_view VALUES (610, 16, 564, 1, 1, 'payment.pay_meth_link', NULL, 'payment.pay_meth_link', 'qweb', 'payment/views/portal_templates.xml', 'extension', '{"en_US": "<data inherit_id=\"portal.side_content\">\n          <!--<xpath expr=\"//div[hasclass(''o_portal_my_details'')]\" position=\"inside\">\n            <t t-set=\"partner\" t-value=\"request.env.user.partner_id\"/>\n            <t t-set=\"providers_allowing_tokenization\"\n               t-value=\"request.env[''payment.provider''].sudo()._get_compatible_providers(request.env.company.id, partner.id, 0., force_tokenization=True, is_validation=True)\"/>\n            <t t-set=\"existing_tokens\" t-value=\"partner.payment_token_ids + partner.commercial_partner_id.sudo().payment_token_ids\"/>\n             Only show the link if a token can be created or if one already exists\n            <div t-if=\"providers_allowing_tokenization or existing_tokens\"\n                 class=''manage_payment_method mt16''>\n                <a href=\"/my/payment_method\">Manage payment methods</a>\n            </div>\n        </xpath>\n        -->\n    </data>"}', '<?xml version="1.0"?>
<data inherit_id="portal.side_content">
          <!--<xpath expr="//div[hasclass(''o_portal_my_details'')]" position="inside">
            <t t-set="partner" t-value="request.env.user.partner_id"/>
            <t t-set="providers_allowing_tokenization"
               t-value="request.env[''payment.provider''].sudo()._get_compatible_providers(request.env.company.id, partner.id, 0., force_tokenization=True, is_validation=True)"/>
            <t t-set="existing_tokens" t-value="partner.payment_token_ids + partner.commercial_partner_id.sudo().payment_token_ids"/>
             Only show the link if a token can be created or if one already exists
            <div t-if="providers_allowing_tokenization or existing_tokens"
                 class=''manage_payment_method mt16''>
                <a href="/my/payment_method">Manage payment methods</a>
            </div>
        </xpath>
        -->
    </data>

    ', false, true, '2026-05-10 01:11:54.802158', '2026-05-10 01:11:54.802158', false);
INSERT INTO public.ir_ui_view VALUES (633, 16, NULL, 1, 1, 'payment.token.list', 'payment.token', NULL, 'tree', 'payment/views/payment_token_views.xml', 'primary', '{"en_US": "<tree string=\"Payment Tokens\" create=\"false\">\n                <field name=\"payment_details\"/>\n                <field name=\"partner_id\"/>\n                <field name=\"payment_method_id\"/>\n                <field name=\"provider_id\"/>\n                <field name=\"provider_ref\"/>\n                <field name=\"company_id\" groups=\"base.group_multi_company\" optional=\"show\"/>\n            </tree>"}', '<?xml version="1.0"?>
<tree string="Payment Tokens" create="false">
                <field name="payment_details"/>
                <field name="partner_id"/>
                <field name="payment_method_id"/>
                <field name="provider_id"/>
                <field name="provider_ref"/>
                <field name="company_id" groups="base.group_multi_company" optional="show"/>
            </tree>
        ', false, true, '2026-05-10 01:11:54.802158', '2026-05-10 01:11:54.802158', false);
INSERT INTO public.ir_ui_view VALUES (611, 16, NULL, 1, 1, 'payment.pay', NULL, 'payment.pay', 'qweb', 'payment/views/portal_templates.xml', 'primary', '{"en_US": "<t t-name=\"payment.pay\">\n        <!-- Parameters description:\n            - reference_prefix: The custom prefix to compute the full transaction reference.\n            - amount: The amount to pay.\n            - currency: The currency of the payment, as a `res.currency` record.\n            - partner_id: The id of the partner on behalf of whom the payment should be made.\n            - payment_methods_sudo: The compatible payment methods, as a sudoed `payment.method`\n                                    recordset.\n            - tokens_sudo: The available payment tokens, as a sudoed `payment.token` recordset.\n            - res_company: The company in which the payment if made (for the company logo).\n            - company_mismatch: Whether the user should make the payment in another company.\n            - expected_company: The record of the company that the user should switch to.\n            - partner_is_different: Whether the partner logged in is the one making the payment.\n        -->\n        <t t-call=\"portal.frontend_layout\">\n            <t t-set=\"page_title\" t-value=\"''Payment''\"/>\n            <t t-set=\"additional_title\"><t t-esc=\"page_title\"/></t>\n            <div class=\"wrap\">\n                <div class=\"container\">\n                    <!-- Portal breadcrumb -->\n                    <t t-call=\"payment.portal_breadcrumb\"/>\n                    <!-- Payment page -->\n                    <div class=\"row justify-content-center my-3\">\n                        <div class=\"col-lg-7\">\n                            <div t-if=\"not amount\" class=\"alert alert-info\">\n                                There is nothing to pay.\n                            </div>\n                            <div t-elif=\"not currency\" class=\"alert alert-warning\">\n                                <strong>Warning</strong> The currency is missing or incorrect.\n                            </div>\n                            <div t-elif=\"not partner_id\" class=\"alert alert-warning\">\n                                <strong>Warning</strong> You must be logged in to pay.\n                            </div>\n                            <div t-elif=\"company_mismatch\">\n                                <t t-call=\"payment.company_mismatch_warning\"/>\n                            </div>\n                            <div t-elif=\"not payment_methods_sudo and not tokens_sudo\" class=\"alert alert-warning\">\n                                <strong>No suitable payment method could be found.</strong><br/>\n                                If you believe that it is an error, please contact the website\n                                administrator.\n                            </div>\n                            <t t-else=\"\">\n                                <div t-if=\"partner_is_different\" class=\"alert alert-warning\">\n                                    <strong>Warning</strong> Make sure you are logged in as the\n                                    correct partner before making this payment.\n                                </div>\n                                <div class=\"o_cc o_cc2 row row-cols-1 row-cols-md-2 mx-0 py-2 rounded\">\n                                    <t t-call=\"payment.summary_item\">\n                                        <t t-set=\"name\" t-value=\"''amount''\"/>\n                                        <t t-set=\"label\">Amount</t>\n                                        <t t-set=\"value\" t-value=\"amount\"/>\n                                        <t t-set=\"options\" t-value=\"{''widget'': ''monetary'', ''display_currency'': currency}\"/>\n                                    </t>\n                                    <t t-call=\"payment.summary_item\">\n                                        <t t-set=\"name\" t-value=\"''reference''\"/>\n                                        <t t-set=\"label\">Reference</t>\n                                        <t t-set=\"value\" t-value=\"reference_prefix\"/>\n                                        <t t-set=\"include_separator\" t-value=\"True\"/>\n                                    </t>\n                                </div>\n                                <div class=\"mt-4\">\n                                    <t t-call=\"payment.form\"/>\n                                </div>\n                            </t>\n                        </div>\n                    </div>\n                </div>\n            </div>\n        </t>\n    </t>"}', '<?xml version="1.0"?>
<t t-name="payment.pay">
        <!-- Parameters description:
            - reference_prefix: The custom prefix to compute the full transaction reference.
            - amount: The amount to pay.
            - currency: The currency of the payment, as a `res.currency` record.
            - partner_id: The id of the partner on behalf of whom the payment should be made.
            - payment_methods_sudo: The compatible payment methods, as a sudoed `payment.method`
                                    recordset.
            - tokens_sudo: The available payment tokens, as a sudoed `payment.token` recordset.
            - res_company: The company in which the payment if made (for the company logo).
            - company_mismatch: Whether the user should make the payment in another company.
            - expected_company: The record of the company that the user should switch to.
            - partner_is_different: Whether the partner logged in is the one making the payment.
        -->
        <t t-call="portal.frontend_layout">
            <t t-set="page_title" t-value="''Payment''"/>
            <t t-set="additional_title"><t t-esc="page_title"/></t>
            <div class="wrap">
                <div class="container">
                    <!-- Portal breadcrumb -->
                    <t t-call="payment.portal_breadcrumb"/>
                    <!-- Payment page -->
                    <div class="row justify-content-center my-3">
                        <div class="col-lg-7">
                            <div t-if="not amount" class="alert alert-info">
                                There is nothing to pay.
                            </div>
                            <div t-elif="not currency" class="alert alert-warning">
                                <strong>Warning</strong> The currency is missing or incorrect.
                            </div>
                            <div t-elif="not partner_id" class="alert alert-warning">
                                <strong>Warning</strong> You must be logged in to pay.
                            </div>
                            <div t-elif="company_mismatch">
                                <t t-call="payment.company_mismatch_warning"/>
                            </div>
                            <div t-elif="not payment_methods_sudo and not tokens_sudo" class="alert alert-warning">
                                <strong>No suitable payment method could be found.</strong><br/>
                                If you believe that it is an error, please contact the website
                                administrator.
                            </div>
                            <t t-else="">
                                <div t-if="partner_is_different" class="alert alert-warning">
                                    <strong>Warning</strong> Make sure you are logged in as the
                                    correct partner before making this payment.
                                </div>
                                <div class="o_cc o_cc2 row row-cols-1 row-cols-md-2 mx-0 py-2 rounded">
                                    <t t-call="payment.summary_item">
                                        <t t-set="name" t-value="''amount''"/>
                                        <t t-set="label">Amount</t>
                                        <t t-set="value" t-value="amount"/>
                                        <t t-set="options" t-value="{''widget'': ''monetary'', ''display_currency'': currency}"/>
                                    </t>
                                    <t t-call="payment.summary_item">
                                        <t t-set="name" t-value="''reference''"/>
                                        <t t-set="label">Reference</t>
                                        <t t-set="value" t-value="reference_prefix"/>
                                        <t t-set="include_separator" t-value="True"/>
                                    </t>
                                </div>
                                <div class="mt-4">
                                    <t t-call="payment.form"/>
                                </div>
                            </t>
                        </div>
                    </div>
                </div>
            </div>
        </t>
    </t>

    ', false, true, '2026-05-10 01:11:54.802158', '2026-05-10 01:11:54.802158', false);
INSERT INTO public.ir_ui_view VALUES (612, 16, NULL, 1, 1, 'Company Mismatch Warning', NULL, 'payment.company_mismatch_warning', 'qweb', 'payment/views/portal_templates.xml', 'primary', '{"en_US": "<t name=\"Company Mismatch Warning\" t-name=\"payment.company_mismatch_warning\">\n        <!-- Parameters description:\n            - expected_company: The record of the company that the user should switch to.\n        -->\n        <div class=\"row mr16\">\n            <div class=\"alert alert-warning col-lg-12 ms-3 me-3\" role=\"alert\">\n                <p>\n                    Please switch to company <t t-esc=\"expected_company.name\"/> to make this\n                    payment.\n                </p>\n            </div>\n        </div>\n    </t>"}', '<?xml version="1.0"?>
<t name="Company Mismatch Warning" t-name="payment.company_mismatch_warning">
        <!-- Parameters description:
            - expected_company: The record of the company that the user should switch to.
        -->
        <div class="row mr16">
            <div class="alert alert-warning col-lg-12 ms-3 me-3" role="alert">
                <p>
                    Please switch to company <t t-esc="expected_company.name"/> to make this
                    payment.
                </p>
            </div>
        </div>
    </t>

    ', false, true, '2026-05-10 01:11:54.802158', '2026-05-10 01:11:54.802158', false);
INSERT INTO public.ir_ui_view VALUES (613, 16, NULL, 1, 1, 'Payment Methods', NULL, 'payment.payment_methods', 'qweb', 'payment/views/portal_templates.xml', 'primary', '{"en_US": "<t name=\"Payment Methods\" t-name=\"payment.payment_methods\">\n        <t t-call=\"portal.frontend_layout\">\n            <t t-set=\"page_title\" t-value=\"''Payment Methods''\"/>\n            <t t-set=\"additional_title\"><t t-esc=\"page_title\"/></t>\n            <div class=\"wrap\">\n                <div class=\"container\">\n                    <!-- Portal breadcrumb -->\n                    <t t-call=\"payment.portal_breadcrumb\"/>\n                    <!-- Payment methods page -->\n                    <div class=\"row justify-content-center\">\n                        <div class=\"col-lg-7\">\n                            <div t-if=\"not payment_methods_sudo and not tokens_sudo\" class=\"alert alert-warning\">\n                                <strong>No suitable payment method could be found.</strong><br/>\n                                If you believe that it is an error, please contact the website\n                                administrator.\n                            </div>\n                            <t t-else=\"\" t-call=\"payment.form\"/>\n                        </div>\n                    </div>\n                </div>\n            </div>\n        </t>\n    </t>"}', '<?xml version="1.0"?>
<t name="Payment Methods" t-name="payment.payment_methods">
        <t t-call="portal.frontend_layout">
            <t t-set="page_title" t-value="''Payment Methods''"/>
            <t t-set="additional_title"><t t-esc="page_title"/></t>
            <div class="wrap">
                <div class="container">
                    <!-- Portal breadcrumb -->
                    <t t-call="payment.portal_breadcrumb"/>
                    <!-- Payment methods page -->
                    <div class="row justify-content-center">
                        <div class="col-lg-7">
                            <div t-if="not payment_methods_sudo and not tokens_sudo" class="alert alert-warning">
                                <strong>No suitable payment method could be found.</strong><br/>
                                If you believe that it is an error, please contact the website
                                administrator.
                            </div>
                            <t t-else="" t-call="payment.form"/>
                        </div>
                    </div>
                </div>
            </div>
        </t>
    </t>

    ', false, true, '2026-05-10 01:11:54.802158', '2026-05-10 01:11:54.802158', false);
INSERT INTO public.ir_ui_view VALUES (614, 16, NULL, 1, 1, 'Payment Status', NULL, 'payment.payment_status', 'qweb', 'payment/views/portal_templates.xml', 'primary', '{"en_US": "<t name=\"Payment Status\" t-name=\"payment.payment_status\">\n        <t t-call=\"portal.frontend_layout\">\n            <t t-set=\"page_title\" t-value=\"''Payment Status''\"/>\n            <t t-set=\"additional_title\"><t t-esc=\"page_title\"/></t>\n            <div class=\"wrap\">\n                <div class=\"container\">\n                    <!-- Portal breadcrumb -->\n                    <t t-call=\"payment.portal_breadcrumb\"/>\n                    <!-- Status page -->\n                    <div name=\"o_payment_status\" class=\"row justify-content-center my-3\">\n                        <div name=\"o_payment_status_content\" class=\"col-12 col-lg-8\">\n                            <!-- The content is generated in JavaScript -->\n                        </div>\n                    </div>\n                </div>\n            </div>\n        </t>\n    </t>"}', '<?xml version="1.0"?>
<t name="Payment Status" t-name="payment.payment_status">
