                            <!-- The content is generated in JavaScript -->
                        </div>
                    </div>
                </div>
            </div>
        </t>
    </t>

    ', false, true, '2026-05-10 01:11:54.802158', '2026-05-10 01:11:54.802158', false);
INSERT INTO public.ir_ui_view VALUES (615, 16, NULL, 1, 1, 'payment.confirm', NULL, 'payment.confirm', 'qweb', 'payment/views/portal_templates.xml', 'primary', '{"en_US": "<t t-name=\"payment.confirm\">\n        <!-- Parameters description:\n            - tx: The transaction to display.\n        -->\n        <t t-call=\"portal.frontend_layout\">\n            <t t-set=\"page_title\" t-value=\"''Payment Confirmation''\"/>\n            <t t-set=\"additional_title\"><t t-esc=\"page_title\"/></t>\n            <t t-set=\"show_pm\" t-value=\"tx.payment_method_code != ''unknown''\"/>\n            <div class=\"wrap\">\n                <div class=\"container\">\n                    <!-- Portal breadcrumb -->\n                    <t t-call=\"payment.portal_breadcrumb\"/>\n                    <div class=\"row justify-content-center my-3\">\n                    <div class=\"col-12 col-lg-7\">\n                        <!-- Confirmation page -->\n                        <div class=\"row\">\n                            <div class=\"col\">\n                                <t t-call=\"payment.transaction_status\"/>\n                            </div>\n                        </div>\n                        <div t-att-class=\"''o_cc o_cc2 row row-cols-1 mx-0 mb-3 py-2 rounded''                                           + ('' row-cols-md-4'' if show_pm else '' row-cols-md-3'')\">\n                            <t t-call=\"payment.summary_item\">\n                                <t t-set=\"name\" t-value=\"''amount''\"/>\n                                <t t-set=\"label\">Amount</t>\n                                <t t-set=\"value\" t-value=\"tx.amount\"/>\n                                <t t-set=\"options\" t-value=\"{''widget'': ''monetary'', ''display_currency'': tx.currency_id}\"/>\n                            </t>\n                            <t t-call=\"payment.summary_item\">\n                                <t t-set=\"name\" t-value=\"''reference''\"/>\n                                <t t-set=\"label\">Reference</t>\n                                <t t-set=\"value\" t-value=\"tx.reference\"/>\n                                <t t-set=\"include_separator\" t-value=\"True\"/>\n                            </t>\n                            <t t-if=\"tx.payment_method_code != ''unknown''\">\n                               <t t-call=\"payment.summary_item\">\n                                    <t t-set=\"name\" t-value=\"''method''\"/>\n                                    <t t-set=\"label\">Payment Method</t>\n                                    <t t-set=\"value\" t-value=\"tx.payment_method_id.name\"/>\n                                    <t t-set=\"include_separator\" t-value=\"True\"/>\n                               </t>\n                            </t>\n                            <t t-call=\"payment.summary_item\">\n                                <t t-set=\"name\" t-value=\"''provider''\"/>\n                                <t t-set=\"label\">Processed by</t>\n                                <t t-set=\"value\" t-value=\"tx.provider_id.sudo().name\"/>\n                                <t t-set=\"include_separator\" t-value=\"True\"/>\n                            </t>\n                        </div>\n\n                        <div class=\"row\">\n                            <div class=\"col offset-md-3 ps-0\">\n                                <a role=\"button\" class=\"btn btn-primary float-end\" href=\"/my/home\">\n                                    Go to my Account <i class=\"oi oi-arrow-right ms-2\"/>\n                                </a>\n                            </div>\n                        </div>\n                    </div>\n                    </div>\n                </div>\n            </div>\n        </t>\n    </t>"}', '<?xml version="1.0"?>
<t t-name="payment.confirm">
        <!-- Parameters description:
            - tx: The transaction to display.
        -->
        <t t-call="portal.frontend_layout">
            <t t-set="page_title" t-value="''Payment Confirmation''"/>
            <t t-set="additional_title"><t t-esc="page_title"/></t>
            <t t-set="show_pm" t-value="tx.payment_method_code != ''unknown''"/>
            <div class="wrap">
                <div class="container">
                    <!-- Portal breadcrumb -->
                    <t t-call="payment.portal_breadcrumb"/>
                    <div class="row justify-content-center my-3">
                    <div class="col-12 col-lg-7">
                        <!-- Confirmation page -->
                        <div class="row">
                            <div class="col">
                                <t t-call="payment.transaction_status"/>
                            </div>
                        </div>
                        <div t-att-class="''o_cc o_cc2 row row-cols-1 mx-0 mb-3 py-2 rounded''                                           + ('' row-cols-md-4'' if show_pm else '' row-cols-md-3'')">
                            <t t-call="payment.summary_item">
                                <t t-set="name" t-value="''amount''"/>
                                <t t-set="label">Amount</t>
                                <t t-set="value" t-value="tx.amount"/>
                                <t t-set="options" t-value="{''widget'': ''monetary'', ''display_currency'': tx.currency_id}"/>
                            </t>
                            <t t-call="payment.summary_item">
                                <t t-set="name" t-value="''reference''"/>
                                <t t-set="label">Reference</t>
                                <t t-set="value" t-value="tx.reference"/>
                                <t t-set="include_separator" t-value="True"/>
                            </t>
                            <t t-if="tx.payment_method_code != ''unknown''">
                               <t t-call="payment.summary_item">
                                    <t t-set="name" t-value="''method''"/>
                                    <t t-set="label">Payment Method</t>
                                    <t t-set="value" t-value="tx.payment_method_id.name"/>
                                    <t t-set="include_separator" t-value="True"/>
                               </t>
                            </t>
                            <t t-call="payment.summary_item">
                                <t t-set="name" t-value="''provider''"/>
                                <t t-set="label">Processed by</t>
                                <t t-set="value" t-value="tx.provider_id.sudo().name"/>
                                <t t-set="include_separator" t-value="True"/>
                            </t>
                        </div>

                        <div class="row">
                            <div class="col offset-md-3 ps-0">
                                <a role="button" class="btn btn-primary float-end" href="/my/home">
                                    Go to my Account <i class="oi oi-arrow-right ms-2"/>
                                </a>
                            </div>
                        </div>
                    </div>
                    </div>
                </div>
            </div>
        </t>
    </t>

    ', false, true, '2026-05-10 01:11:54.802158', '2026-05-10 01:11:54.802158', false);
INSERT INTO public.ir_ui_view VALUES (616, 16, NULL, 1, 1, 'payment.portal_breadcrumb', NULL, 'payment.portal_breadcrumb', 'qweb', 'payment/views/portal_templates.xml', 'primary', '{"en_US": "<t t-name=\"payment.portal_breadcrumb\">\n        <!-- Parameters description:\n            - page_title: The title of the breadcrumb item.\n        -->\n        <div class=\"row\">\n            <div class=\"col-md-6\">\n                <ol class=\"breadcrumb px-0 mt16\">\n                    <li id=\"o_payment_portal_home\" class=\"breadcrumb-item\">\n                        <a href=\"/my/home\">\n                            <i class=\"fa fa-home\" role=\"img\" title=\"Home\" aria-label=\"Home\"/>\n                        </a>\n                    </li>\n                    <li class=\"breadcrumb-item\"><t t-esc=\"page_title\"/></li>\n                </ol>\n            </div>\n        </div>\n    </t>"}', '<?xml version="1.0"?>
<t t-name="payment.portal_breadcrumb">
        <!-- Parameters description:
            - page_title: The title of the breadcrumb item.
        -->
        <div class="row">
            <div class="col-md-6">
                <ol class="breadcrumb px-0 mt16">
                    <li id="o_payment_portal_home" class="breadcrumb-item">
                        <a href="/my/home">
                            <i class="fa fa-home" role="img" title="Home" aria-label="Home"/>
                        </a>
                    </li>
                    <li class="breadcrumb-item"><t t-esc="page_title"/></li>
                </ol>
            </div>
        </div>
    </t>

    ', false, true, '2026-05-10 01:11:54.802158', '2026-05-10 01:11:54.802158', false);
INSERT INTO public.ir_ui_view VALUES (617, 16, NULL, 1, 1, 'payment.summary_item', NULL, 'payment.summary_item', 'qweb', 'payment/views/portal_templates.xml', 'primary', '{"en_US": "<t t-name=\"payment.summary_item\">\n        <!-- Parameters description:\n            - name: The summary item name that is suffixed to `o_payment_summary_` to create the id.\n            - label: The label that is displayed.\n            - value: The value of the summary item.\n            - options: The widget options to set.\n            - include_separator: Whether the summary item should be preceded by a separator.\n        -->\n        <t t-set=\"options\" t-value=\"options or {''widget'': ''string''}\"/>\n        <hr t-if=\"include_separator\" class=\"d-md-none m-0 text-300 opacity-100\"/>\n        <div t-att-class=\"''col my-3 text-break''                           + ('' o_payment_summary_separator'' if include_separator else '''')\">\n            <label t-attf-for=\"o_payment_summary_{{name}}\" t-out=\"label\" class=\"d-block small text-muted\"/>\n            <span t-attf-id=\"o_payment_summary_{{name}}\" t-out=\"value\" t-options=\"options\" class=\"fs-5 fw-bold\"/>\n        </div>\n    </t>"}', '<?xml version="1.0"?>
<t t-name="payment.summary_item">
        <!-- Parameters description:
            - name: The summary item name that is suffixed to `o_payment_summary_` to create the id.
            - label: The label that is displayed.
            - value: The value of the summary item.
            - options: The widget options to set.
            - include_separator: Whether the summary item should be preceded by a separator.
        -->
        <t t-set="options" t-value="options or {''widget'': ''string''}"/>
        <hr t-if="include_separator" class="d-md-none m-0 text-300 opacity-100"/>
        <div t-att-class="''col my-3 text-break''                           + ('' o_payment_summary_separator'' if include_separator else '''')">
            <label t-attf-for="o_payment_summary_{{name}}" t-out="label" class="d-block small text-muted"/>
            <span t-attf-id="o_payment_summary_{{name}}" t-out="value" t-options="options" class="fs-5 fw-bold"/>
        </div>
    </t>

    ', false, true, '2026-05-10 01:11:54.802158', '2026-05-10 01:11:54.802158', false);
INSERT INTO public.ir_ui_view VALUES (618, 16, NULL, 1, 1, 'payment.transaction_status', NULL, 'payment.transaction_status', 'qweb', 'payment/views/portal_templates.xml', 'primary', '{"en_US": "<t t-name=\"payment.transaction_status\">\n        <!-- Parameters description:\n            - tx: The transaction whose status must be displayed.\n        -->\n        <t t-if=\"tx.state == ''draft''\">\n            <t t-set=\"alert_style\" t-value=\"''info''\"/>\n            <t t-set=\"status_message\">\n                <p>Your payment has not been processed yet.</p>\n            </t>\n        </t>\n        <t t-elif=\"tx.state == ''pending''\">\n            <t t-set=\"alert_style\" t-value=\"''warning''\"/>\n            <t t-set=\"status_message\" t-value=\"tx.provider_id.sudo().pending_msg\"/>\n        </t>\n        <t t-elif=\"tx.state == ''authorized''\">\n            <t t-set=\"alert_style\" t-value=\"''success''\"/>\n            <t t-set=\"status_message\" t-value=\"tx.provider_id.sudo().auth_msg\"/>\n        </t>\n        <t t-elif=\"tx.state == ''done''\">\n            <t t-set=\"alert_style\" t-value=\"''success''\"/>\n            <t t-set=\"status_heading\">Thank you!</t>\n            <t t-set=\"status_message\" t-value=\"tx.provider_id.sudo().done_msg\"/>\n        </t>\n        <t t-elif=\"tx.state == ''cancel''\">\n            <t t-set=\"alert_style\" t-value=\"''danger''\"/>\n            <t t-set=\"status_message\" t-value=\"tx.provider_id.sudo().cancel_msg\"/>\n        </t>\n        <t t-elif=\"tx.state == ''error''\">\n            <t t-set=\"alert_style\" t-value=\"''danger''\"/>\n            <t t-set=\"status_message\">\n                <p class=\"mb-0\">An error occurred during the processing of your payment.</p>\n            </t>\n        </t>\n\n        <t t-if=\"is_html_empty(status_message)\" t-set=\"status_message\" t-value=\"''''\"/>\n        <t t-set=\"o_payment_status_alert_class\" t-value=\"''alert alert-''+ alert_style +'' d-flex gap-3''\"/>\n\n        <div t-if=\"status_message or tx.state_message\" name=\"o_payment_status_alert\" t-attf-class=\"{{o_payment_status_alert_class}}\">\n            <div id=\"o_payment_status_icon\">\n                <i t-attf-class=\"fa fa-{{''check'' if alert_style == ''success'' else ''info-circle''                                  if alert_style == ''info'' else ''exclamation-triangle''}}\"/>\n            </div>\n            <div id=\"o_payment_status_message\" class=\"w-100\">\n                <h5 t-if=\"status_heading\" t-out=\"status_heading\" class=\"alert-heading mb-0\"/>\n                <t t-if=\"status_message\" t-out=\"status_message\" class=\"mb-0\"/>\n                <t t-if=\"tx.state_message\" t-out=\"tx.state_message\" class=\"mb-0\"/>\n            </div>\n        </div>\n    </t>"}', '<?xml version="1.0"?>
<t t-name="payment.transaction_status">
        <!-- Parameters description:
            - tx: The transaction whose status must be displayed.
        -->
        <t t-if="tx.state == ''draft''">
            <t t-set="alert_style" t-value="''info''"/>
            <t t-set="status_message">
                <p>Your payment has not been processed yet.</p>
            </t>
        </t>
        <t t-elif="tx.state == ''pending''">
            <t t-set="alert_style" t-value="''warning''"/>
            <t t-set="status_message" t-value="tx.provider_id.sudo().pending_msg"/>
        </t>
        <t t-elif="tx.state == ''authorized''">
            <t t-set="alert_style" t-value="''success''"/>
            <t t-set="status_message" t-value="tx.provider_id.sudo().auth_msg"/>
        </t>
        <t t-elif="tx.state == ''done''">
            <t t-set="alert_style" t-value="''success''"/>
            <t t-set="status_heading">Thank you!</t>
            <t t-set="status_message" t-value="tx.provider_id.sudo().done_msg"/>
        </t>
        <t t-elif="tx.state == ''cancel''">
            <t t-set="alert_style" t-value="''danger''"/>
            <t t-set="status_message" t-value="tx.provider_id.sudo().cancel_msg"/>
        </t>
        <t t-elif="tx.state == ''error''">
            <t t-set="alert_style" t-value="''danger''"/>
            <t t-set="status_message">
                <p class="mb-0">An error occurred during the processing of your payment.</p>
            </t>
        </t>

        <t t-if="is_html_empty(status_message)" t-set="status_message" t-value="''''"/>
        <t t-set="o_payment_status_alert_class" t-value="''alert alert-''+ alert_style +'' d-flex gap-3''"/>

        <div t-if="status_message or tx.state_message" name="o_payment_status_alert" t-attf-class="{{o_payment_status_alert_class}}">
            <div id="o_payment_status_icon">
                <i t-attf-class="fa fa-{{''check'' if alert_style == ''success'' else ''info-circle''                                  if alert_style == ''info'' else ''exclamation-triangle''}}"/>
            </div>
            <div id="o_payment_status_message" class="w-100">
                <h5 t-if="status_heading" t-out="status_heading" class="alert-heading mb-0"/>
                <t t-if="status_message" t-out="status_message" class="mb-0"/>
                <t t-if="tx.state_message" t-out="tx.state_message" class="mb-0"/>
            </div>
        </div>
    </t>

    ', false, true, '2026-05-10 01:11:54.802158', '2026-05-10 01:11:54.802158', false);
INSERT INTO public.ir_ui_view VALUES (619, 60, 548, 1, 1, 'Show Payment Method', NULL, 'payment.portal_my_home_payment', 'qweb', 'payment/views/portal_templates.xml', 'extension', '{"en_US": "<data name=\"Show Payment Method\" customize_show=\"True\" inherit_id=\"portal.portal_my_home\" priority=\"60\">\n        <xpath expr=\"//div[hasclass(''o_portal_docs'')]\" position=\"before\">\n            <t t-set=\"portal_client_category_enable\" t-value=\"True\"/>\n        </xpath>\n        <div id=\"portal_client_category\" position=\"inside\">\n            <t t-set=\"partner_sudo\" t-value=\"request.env.user.partner_id\"/>\n            <t t-set=\"providers_sudo\" t-value=\"request.env[''payment.provider''].sudo()._get_compatible_providers(request.env.company.id, partner_sudo.id, 0., force_tokenization=True, is_validation=True)\"/>\n            <t t-set=\"methods_allowing_tokenization\" t-value=\"request.env[''payment.method''].sudo()._get_compatible_payment_methods(                             providers_sudo.ids,                             partner_sudo.id,                             force_tokenization=True,                         )\"/>\n            <t t-set=\"existing_tokens\" t-value=\"partner_sudo.payment_token_ids + partner_sudo.commercial_partner_id.payment_token_ids\"/>\n            <t t-if=\"methods_allowing_tokenization or existing_tokens\" t-call=\"portal.portal_docs_entry\">\n                <t t-set=\"icon\" t-value=\"''/payment/static/img/payment-methods.svg''\"/>\n                <t t-set=\"title\">Payment methods</t>\n                <t t-set=\"text\">Manage your payment methods</t>\n                <t t-set=\"url\" t-value=\"''/my/payment_method''\"/>\n                <t t-set=\"config_card\" t-value=\"True\"/>\n            </t>\n        </div>\n    </data>"}', '<?xml version="1.0"?>
<data name="Show Payment Method" customize_show="True" inherit_id="portal.portal_my_home" priority="60">
        <xpath expr="//div[hasclass(''o_portal_docs'')]" position="before">
            <t t-set="portal_client_category_enable" t-value="True"/>
        </xpath>
        <div id="portal_client_category" position="inside">
            <t t-set="partner_sudo" t-value="request.env.user.partner_id"/>
            <t t-set="providers_sudo" t-value="request.env[''payment.provider''].sudo()._get_compatible_providers(request.env.company.id, partner_sudo.id, 0., force_tokenization=True, is_validation=True)"/>
            <t t-set="methods_allowing_tokenization" t-value="request.env[''payment.method''].sudo()._get_compatible_payment_methods(                             providers_sudo.ids,                             partner_sudo.id,                             force_tokenization=True,                         )"/>
            <t t-set="existing_tokens" t-value="partner_sudo.payment_token_ids + partner_sudo.commercial_partner_id.payment_token_ids"/>
            <t t-if="methods_allowing_tokenization or existing_tokens" t-call="portal.portal_docs_entry">
                <t t-set="icon" t-value="''/payment/static/img/payment-methods.svg''"/>
                <t t-set="title">Payment methods</t>
                <t t-set="text">Manage your payment methods</t>
                <t t-set="url" t-value="''/my/payment_method''"/>
                <t t-set="config_card" t-value="True"/>
            </t>
        </div>
    </data>

', false, true, '2026-05-10 01:11:54.802158', '2026-05-10 01:11:54.802158', true);
INSERT INTO public.ir_ui_view VALUES (620, 16, NULL, 1, 1, 'payment.provider.form', 'payment.provider', NULL, 'form', 'payment/views/payment_provider_views.xml', 'primary', '{"en_US": "<form string=\"Payment provider\">\n                <field name=\"company_id\" invisible=\"1\"/>\n                <field name=\"is_published\" invisible=\"1\"/>\n                <field name=\"main_currency_id\" invisible=\"1\"/>\n                <field name=\"support_manual_capture\" invisible=\"1\"/>\n                <field name=\"support_tokenization\" invisible=\"1\"/>\n                <field name=\"support_express_checkout\" invisible=\"1\"/>\n                <field name=\"module_id\" invisible=\"1\"/>\n                <field name=\"module_state\" invisible=\"1\"/>\n                <field name=\"module_to_buy\" invisible=\"1\"/>\n                <field name=\"show_credentials_page\" invisible=\"1\"/>\n                <field name=\"show_allow_express_checkout\" invisible=\"1\"/>\n                <field name=\"show_allow_tokenization\" invisible=\"1\"/>\n                <field name=\"show_pre_msg\" invisible=\"1\"/>\n                <field name=\"show_pending_msg\" invisible=\"1\"/>\n                <field name=\"show_auth_msg\" invisible=\"1\"/>\n                <field name=\"show_done_msg\" invisible=\"1\"/>\n                <field name=\"show_cancel_msg\" invisible=\"1\"/>\n                <field name=\"require_currency\" invisible=\"1\"/>\n                <field name=\"code\" invisible=\"1\"/>\n                <sheet>\n                    <!-- === Stat Buttons === -->\n                    <div class=\"oe_button_box\" name=\"button_box\" invisible=\"module_state != ''installed''\">\n                        <button name=\"action_toggle_is_published\" invisible=\"not is_published\" class=\"oe_stat_button\" type=\"object\" icon=\"fa-globe\">\n                            <div class=\"o_stat_info o_field_widget\">\n                                <span class=\"o_stat_text text-success\">Published</span>\n                            </div>\n                        </button>\n                        <button name=\"action_toggle_is_published\" invisible=\"is_published\" class=\"oe_stat_button\" type=\"object\" icon=\"fa-eye-slash\">\n                            <div class=\"o_stat_info o_field_widget\">\n                                <span class=\"o_stat_text text-danger\">Unpublished</span>\n                            </div>\n                        </button>\n                    </div>\n                    <field name=\"image_128\" widget=\"image\" class=\"oe_avatar\" readonly=\"module_state != ''installed''\"/>\n                    <widget name=\"web_ribbon\" title=\"Disabled\" bg_color=\"text-bg-danger\" invisible=\"module_state != ''installed'' or state != ''disabled''\"/>\n                    <widget name=\"web_ribbon\" title=\"Test Mode\" bg_color=\"text-bg-warning\" invisible=\"module_state != ''installed'' or state != ''test''\"/>\n                    <div class=\"oe_title\">\n                        <h1><field name=\"name\" placeholder=\"Name\"/></h1>\n                        <div invisible=\"module_state == ''installed'' or not module_id\">\n                            <a invisible=\"not module_to_buy\" href=\"https://odoo.com/pricing?utm_source=db&amp;utm_medium=module\" target=\"_blank\" class=\"btn btn-info\" role=\"button\">Upgrade</a>\n                            <button invisible=\"module_to_buy\" type=\"object\" class=\"btn btn-primary\" name=\"button_immediate_install\" string=\"Install\"/>\n                        </div>\n                    </div>\n                    <div id=\"provider_creation_warning\" invisible=\"id\" class=\"alert alert-warning\" role=\"alert\">\n                        <strong>Warning</strong> Creating a payment provider from the <em>CREATE</em> button is not supported.\n                        Please use the <em>Duplicate</em> action instead.\n                    </div>\n                    <group>\n                        <group name=\"payment_state\" invisible=\"module_state not in (''installed'', False)\">\n                            <field name=\"code\" groups=\"base.group_no_one\" readonly=\"id\"/>\n                            <field name=\"state\" widget=\"radio\"/>\n                            <field name=\"company_id\" groups=\"base.group_multi_company\" options=\"{&quot;no_open&quot;:True}\"/>\n                        </group>\n                    </group>\n                    <notebook invisible=\"module_id and module_state != ''installed''\">\n                        <page string=\"Credentials\" name=\"credentials\" invisible=\"code == ''none'' or not show_credentials_page\">\n                            <group name=\"provider_credentials\"/>\n                        </page>\n                        <page string=\"Configuration\" name=\"configuration\">\n                            <group name=\"provider_config\">\n                                <group string=\"Payment Form\" name=\"payment_form\">\n                                    <field name=\"payment_method_ids\" string=\"Payment Methods\" domain=\"[(''is_primary'', ''='', True)]\" readonly=\"True\" invisible=\"state == ''disabled''\" widget=\"many2many_tags\"/>\n                                    <div colspan=\"2\">\n                                        <a type=\"object\" name=\"action_view_payment_methods\" class=\"btn btn-link\" role=\"button\" invisible=\"state == ''disabled''\">\n                                            <i class=\"oi oi-fw o_button_icon oi-arrow-right\"/>\n                                            Enable Payment Methods\n                                        </a>\n                                    </div>\n                                    <field name=\"allow_tokenization\" invisible=\"not support_tokenization or not show_allow_tokenization\"/>\n                                    <field name=\"capture_manually\" invisible=\"not support_manual_capture\"/>\n                                    <field name=\"allow_express_checkout\" invisible=\"not support_express_checkout or not show_allow_express_checkout\"/>\n                                </group>\n                                <group string=\"Availability\" name=\"availability\">\n                                    <field name=\"maximum_amount\"/>\n                                    <label for=\"available_currency_ids\"/>\n                                    <!-- Use `o_row` to allow placing a button next to the field in overrides. -->\n                                    <div name=\"available_currencies\" class=\"o_row\">\n                                        <field name=\"available_currency_ids\" widget=\"many2many_tags\" placeholder=\"Select currencies. Leave empty not to restrict any.\" context=\"{''active_test'': False}\" options=\"{''no_create'': True}\" required=\"require_currency and state != ''disabled''\"/>\n                                    </div>\n                                    <field name=\"available_country_ids\" widget=\"many2many_tags\" placeholder=\"Select countries. Leave empty to make available everywhere.\" options=\"{''no_create'': True}\"/>\n                                </group>\n                                <group string=\"Payment Followup\" name=\"payment_followup\" invisible=\"1\"/>\n                            </group>\n                        </page>\n                        <page string=\"Messages\" name=\"messages\" invisible=\"module_id and module_state != ''installed''\">\n                            <group>\n                                <field name=\"pre_msg\" invisible=\"not show_pre_msg\"/>\n                                <field name=\"pending_msg\" invisible=\"not show_pending_msg\"/>\n                                <field name=\"auth_msg\" invisible=\"not support_manual_capture or not show_auth_msg\"/>\n                                <field name=\"done_msg\" invisible=\"not show_done_msg\"/>\n                                <field name=\"cancel_msg\" invisible=\"not show_cancel_msg\"/>\n                            </group>\n                        </page>\n                    </notebook>\n                </sheet>\n            </form>"}', '<?xml version="1.0"?>
<form string="Payment provider">
                <field name="company_id" invisible="1"/>
                <field name="is_published" invisible="1"/>
                <field name="main_currency_id" invisible="1"/>
                <field name="support_manual_capture" invisible="1"/>
                <field name="support_tokenization" invisible="1"/>
                <field name="support_express_checkout" invisible="1"/>
                <field name="module_id" invisible="1"/>
                <field name="module_state" invisible="1"/>
                <field name="module_to_buy" invisible="1"/>
                <field name="show_credentials_page" invisible="1"/>
                <field name="show_allow_express_checkout" invisible="1"/>
                <field name="show_allow_tokenization" invisible="1"/>
                <field name="show_pre_msg" invisible="1"/>
                <field name="show_pending_msg" invisible="1"/>
                <field name="show_auth_msg" invisible="1"/>
                <field name="show_done_msg" invisible="1"/>
                <field name="show_cancel_msg" invisible="1"/>
                <field name="require_currency" invisible="1"/>
                <field name="code" invisible="1"/>
                <sheet>
                    <!-- === Stat Buttons === -->
                    <div class="oe_button_box" name="button_box" invisible="module_state != ''installed''">
                        <button name="action_toggle_is_published" invisible="not is_published" class="oe_stat_button" type="object" icon="fa-globe">
                            <div class="o_stat_info o_field_widget">
                                <span class="o_stat_text text-success">Published</span>
                            </div>
                        </button>
                        <button name="action_toggle_is_published" invisible="is_published" class="oe_stat_button" type="object" icon="fa-eye-slash">
                            <div class="o_stat_info o_field_widget">
                                <span class="o_stat_text text-danger">Unpublished</span>
                            </div>
                        </button>
                    </div>
                    <field name="image_128" widget="image" class="oe_avatar" readonly="module_state != ''installed''"/>
                    <widget name="web_ribbon" title="Disabled" bg_color="text-bg-danger" invisible="module_state != ''installed'' or state != ''disabled''"/>
                    <widget name="web_ribbon" title="Test Mode" bg_color="text-bg-warning" invisible="module_state != ''installed'' or state != ''test''"/>
                    <div class="oe_title">
                        <h1><field name="name" placeholder="Name"/></h1>
                        <div invisible="module_state == ''installed'' or not module_id">
                            <a invisible="not module_to_buy" href="https://odoo.com/pricing?utm_source=db&amp;utm_medium=module" target="_blank" class="btn btn-info" role="button">Upgrade</a>
                            <button invisible="module_to_buy" type="object" class="btn btn-primary" name="button_immediate_install" string="Install"/>
                        </div>
                    </div>
                    <div id="provider_creation_warning" invisible="id" class="alert alert-warning" role="alert">
                        <strong>Warning</strong> Creating a payment provider from the <em>CREATE</em> button is not supported.
                        Please use the <em>Duplicate</em> action instead.
                    </div>
                    <group>
                        <group name="payment_state" invisible="module_state not in (''installed'', False)">
                            <field name="code" groups="base.group_no_one" readonly="id"/>
                            <field name="state" widget="radio"/>
                            <field name="company_id" groups="base.group_multi_company" options="{&quot;no_open&quot;:True}"/>
                        </group>
                    </group>
                    <notebook invisible="module_id and module_state != ''installed''">
                        <page string="Credentials" name="credentials" invisible="code == ''none'' or not show_credentials_page">
                            <group name="provider_credentials"/>
                        </page>
                        <page string="Configuration" name="configuration">
                            <group name="provider_config">
                                <group string="Payment Form" name="payment_form">
                                    <field name="payment_method_ids" string="Payment Methods" domain="[(''is_primary'', ''='', True)]" readonly="True" invisible="state == ''disabled''" widget="many2many_tags"/>
                                    <div colspan="2">
                                        <a type="object" name="action_view_payment_methods" class="btn btn-link" role="button" invisible="state == ''disabled''">
                                            <i class="oi oi-fw o_button_icon oi-arrow-right"/>
                                            Enable Payment Methods
                                        </a>
                                    </div>
                                    <field name="allow_tokenization" invisible="not support_tokenization or not show_allow_tokenization"/>
                                    <field name="capture_manually" invisible="not support_manual_capture"/>
                                    <field name="allow_express_checkout" invisible="not support_express_checkout or not show_allow_express_checkout"/>
                                </group>
                                <group string="Availability" name="availability">
                                    <field name="maximum_amount"/>
                                    <label for="available_currency_ids"/>
                                    <!-- Use `o_row` to allow placing a button next to the field in overrides. -->
                                    <div name="available_currencies" class="o_row">
                                        <field name="available_currency_ids" widget="many2many_tags" placeholder="Select currencies. Leave empty not to restrict any." context="{''active_test'': False}" options="{''no_create'': True}" required="require_currency and state != ''disabled''"/>
                                    </div>
                                    <field name="available_country_ids" widget="many2many_tags" placeholder="Select countries. Leave empty to make available everywhere." options="{''no_create'': True}"/>
                                </group>
                                <group string="Payment Followup" name="payment_followup" invisible="1"/>
                            </group>
                        </page>
                        <page string="Messages" name="messages" invisible="module_id and module_state != ''installed''">
                            <group>
                                <field name="pre_msg" invisible="not show_pre_msg"/>
                                <field name="pending_msg" invisible="not show_pending_msg"/>
                                <field name="auth_msg" invisible="not support_manual_capture or not show_auth_msg"/>
                                <field name="done_msg" invisible="not show_done_msg"/>
                                <field name="cancel_msg" invisible="not show_cancel_msg"/>
                            </group>
                        </page>
                    </notebook>
                </sheet>
            </form>
        ', false, true, '2026-05-10 01:11:54.802158', '2026-05-10 01:11:54.802158', false);
INSERT INTO public.ir_ui_view VALUES (621, 16, NULL, 1, 1, 'payment.provider.list', 'payment.provider', NULL, 'tree', 'payment/views/payment_provider_views.xml', 'primary', '{"en_US": "<tree string=\"Payment Providers\" create=\"false\">\n                <field name=\"sequence\" widget=\"handle\"/>\n                <field name=\"name\"/>\n                <field name=\"code\" groups=\"base.group_no_one\"/>\n                <field name=\"state\"/>\n                <field name=\"available_country_ids\" widget=\"many2many_tags\" optional=\"hide\"/>\n                <field name=\"company_id\" groups=\"base.group_multi_company\" optional=\"show\"/>\n            </tree>"}', '<?xml version="1.0"?>
<tree string="Payment Providers" create="false">
                <field name="sequence" widget="handle"/>
                <field name="name"/>
                <field name="code" groups="base.group_no_one"/>
                <field name="state"/>
                <field name="available_country_ids" widget="many2many_tags" optional="hide"/>
                <field name="company_id" groups="base.group_multi_company" optional="show"/>
            </tree>
        ', false, true, '2026-05-10 01:11:54.802158', '2026-05-10 01:11:54.802158', false);
INSERT INTO public.ir_ui_view VALUES (622, 16, NULL, 1, 1, 'payment.provider.kanban', 'payment.provider', NULL, 'kanban', 'payment/views/payment_provider_views.xml', 'primary', '{"en_US": "<kanban create=\"false\" quick_create=\"false\" class=\"o_kanban_dashboard\">\n                <field name=\"id\"/>\n                <field name=\"name\"/>\n                <field name=\"state\"/>\n                <field name=\"is_published\"/>\n                <field name=\"code\"/>\n                <field name=\"module_id\"/>\n                <field name=\"module_state\"/>\n                <field name=\"module_to_buy\"/>\n                <field name=\"color\"/>\n                <templates>\n                    <t t-name=\"kanban-box\">\n                        <t t-set=\"installed\" t-value=\"!record.module_id.value || (record.module_id.value &amp;&amp; record.module_state.raw_value === ''installed'')\"/>\n                        <t t-set=\"to_buy\" t-value=\"record.module_to_buy.raw_value === true\"/>\n                        <t t-set=\"is_disabled\" t-value=\"record.state.raw_value==''disabled''\"/>\n                        <t t-set=\"is_published\" t-value=\"record.is_published.raw_value === true\"/>\n                        <t t-set=\"to_upgrade\" t-value=\"!installed and to_buy\"/>\n                        <div t-attf-class=\"oe_kanban_global_click\" class=\"d-flex p-2\">\n                            <div class=\"o_payment_provider_desc d-flex gap-2\">\n                                <img type=\"open\" t-att-src=\"kanban_image(''payment.provider'', ''image_128'', record.id.raw_value)\" class=\"mb-0 o_image_64_max\" alt=\"provider\"/>\n                                <div class=\"d-flex flex-column justify-content-between w-100\">\n                                    <div class=\"o_payment_kanban_info\">\n                                        <h4 class=\"mb-0\"><t t-esc=\"record.name.value\"/></h4>\n                                        <t t-if=\"installed\">\n                                            <field name=\"state\" widget=\"label_selection\" options=\"{''classes'': {''enabled'': ''success'', ''test'': ''warning'', ''disabled'' : ''light''}}\"/>\n                                            <t t-if=\"!is_disabled\">\n                                                <span t-if=\"is_published and installed\" class=\"badge text-bg-success ms-1\">\n                                                    Published\n                                                </span>\n                                                <span t-if=\"!is_published and installed\" class=\"badge text-bg-info ms-1\">\n                                                    Unpublished\n                                                </span>\n                                            </t>\n                                        </t>\n                                        <span t-if=\"to_upgrade\" class=\"badge text-bg-primary ms-1\">Enterprise</span>\n                                    </div>\n                                    <div class=\"o_payment_kanban_button text-end\">\n                                        <button t-if=\"!installed and !selection_mode and !to_buy\" type=\"object\" class=\"btn btn-sm btn-primary float-end\" name=\"button_immediate_install\">Install</button>\n                                        <button t-if=\"installed and is_disabled and !selection_mode\" type=\"edit\" class=\"btn btn-sm btn-secondary float-end\">Activate</button>\n                                        <button t-if=\"!installed and to_buy\" href=\"https://odoo.com/pricing?utm_source=db&amp;utm_medium=module\" target=\"_blank\" class=\"btn btn-sm btn-primary float-end\">Upgrade</button>\n                                    </div>\n                                </div>\n                            </div>\n                        </div>\n                    </t>\n                </templates>\n            </kanban>"}', '<?xml version="1.0"?>
<kanban create="false" quick_create="false" class="o_kanban_dashboard">
                <field name="id"/>
                <field name="name"/>
                <field name="state"/>
                <field name="is_published"/>
                <field name="code"/>
                <field name="module_id"/>
                <field name="module_state"/>
                <field name="module_to_buy"/>
                <field name="color"/>
                <templates>
                    <t t-name="kanban-box">
                        <t t-set="installed" t-value="!record.module_id.value || (record.module_id.value &amp;&amp; record.module_state.raw_value === ''installed'')"/>
                        <t t-set="to_buy" t-value="record.module_to_buy.raw_value === true"/>
                        <t t-set="is_disabled" t-value="record.state.raw_value==''disabled''"/>
                        <t t-set="is_published" t-value="record.is_published.raw_value === true"/>
                        <t t-set="to_upgrade" t-value="!installed and to_buy"/>
                        <div t-attf-class="oe_kanban_global_click" class="d-flex p-2">
                            <div class="o_payment_provider_desc d-flex gap-2">
                                <img type="open" t-att-src="kanban_image(''payment.provider'', ''image_128'', record.id.raw_value)" class="mb-0 o_image_64_max" alt="provider"/>
                                <div class="d-flex flex-column justify-content-between w-100">
                                    <div class="o_payment_kanban_info">
                                        <h4 class="mb-0"><t t-esc="record.name.value"/></h4>
                                        <t t-if="installed">
                                            <field name="state" widget="label_selection" options="{''classes'': {''enabled'': ''success'', ''test'': ''warning'', ''disabled'' : ''light''}}"/>
                                            <t t-if="!is_disabled">
                                                <span t-if="is_published and installed" class="badge text-bg-success ms-1">
                                                    Published
                                                </span>
                                                <span t-if="!is_published and installed" class="badge text-bg-info ms-1">
                                                    Unpublished
                                                </span>
                                            </t>
                                        </t>
                                        <span t-if="to_upgrade" class="badge text-bg-primary ms-1">Enterprise</span>
                                    </div>
                                    <div class="o_payment_kanban_button text-end">
                                        <button t-if="!installed and !selection_mode and !to_buy" type="object" class="btn btn-sm btn-primary float-end" name="button_immediate_install">Install</button>
                                        <button t-if="installed and is_disabled and !selection_mode" type="edit" class="btn btn-sm btn-secondary float-end">Activate</button>
                                        <button t-if="!installed and to_buy" href="https://odoo.com/pricing?utm_source=db&amp;utm_medium=module" target="_blank" class="btn btn-sm btn-primary float-end">Upgrade</button>
                                    </div>
                                </div>
                            </div>
                        </div>
                    </t>
                </templates>
            </kanban>
        ', false, true, '2026-05-10 01:11:54.802158', '2026-05-10 01:11:54.802158', false);
INSERT INTO public.ir_ui_view VALUES (623, 16, NULL, 1, 1, 'payment.provider.search', 'payment.provider', NULL, 'search', 'payment/views/payment_provider_views.xml', 'primary', '{"en_US": "<search>\n                <field name=\"name\" string=\"provider\" filter_domain=\"[(''name'', ''ilike'', self)]\"/>\n                <field name=\"payment_method_ids\" string=\"payment method\" context=\"{''active_test'': False}\" filter_domain=\"[                             ''|'',                             (''payment_method_ids.name'', ''ilike'', self),                             (''payment_method_ids.code'', ''ilike'', self),                        ]\"/>\n                <filter name=\"provider_installed\" string=\"Installed\" domain=\"[(''module_state'', ''='', ''installed'')]\"/>\n                <group expand=\"0\" string=\"Group By\">\n                    <filter string=\"Provider\" name=\"code\" context=\"{''group_by'': ''code''}\"/>\n                    <filter string=\"State\" name=\"state\" context=\"{''group_by'': ''state''}\"/>\n                    <filter string=\"Company\" name=\"company\" context=\"{''group_by'': ''company_id''}\" groups=\"base.group_multi_company\"/>\n                </group>\n            </search>"}', '<?xml version="1.0"?>
<search>
                <field name="name" string="provider" filter_domain="[(''name'', ''ilike'', self)]"/>
                <field name="payment_method_ids" string="payment method" context="{''active_test'': False}" filter_domain="[                             ''|'',                             (''payment_method_ids.name'', ''ilike'', self),                             (''payment_method_ids.code'', ''ilike'', self),                        ]"/>
                <filter name="provider_installed" string="Installed" domain="[(''module_state'', ''='', ''installed'')]"/>
                <group expand="0" string="Group By">
                    <filter string="Provider" name="code" context="{''group_by'': ''code''}"/>
                    <filter string="State" name="state" context="{''group_by'': ''state''}"/>
                    <filter string="Company" name="company" context="{''group_by'': ''company_id''}" groups="base.group_multi_company"/>
                </group>
            </search>
        ', false, true, '2026-05-10 01:11:54.802158', '2026-05-10 01:11:54.802158', false);
INSERT INTO public.ir_ui_view VALUES (624, 16, NULL, 1, 1, 'payment.method.form', 'payment.method', NULL, 'form', 'payment/views/payment_method_views.xml', 'primary', '{"en_US": "<form string=\"Payment Method\">\n                <sheet>\n                    <field name=\"is_primary\" invisible=\"True\"/>\n                    <field name=\"image\" widget=\"image\" class=\"oe_avatar\"/>\n                    <div class=\"oe_title\">\n                        <h1><field name=\"name\" placeholder=\"Name\"/></h1>\n                    </div>\n                    <group>\n                        <field name=\"code\" readonly=\"id\" groups=\"base.group_no_one\"/>\n                        <field name=\"primary_payment_method_id\" invisible=\"is_primary\"/>\n                        <field name=\"active\"/>\n                        <label for=\"supported_country_ids\"/>\n                        <div>\n                            <field name=\"supported_country_ids\" class=\"oe_inline\" widget=\"many2many_tags\" readonly=\"1\"/>\n                            <span class=\"oe_inline text-muted\" invisible=\"supported_country_ids\">\n                                All countries are supported.\n                            </span>\n                        </div>\n                        <label for=\"supported_currency_ids\"/>\n                        <div>\n                            <field name=\"supported_currency_ids\" class=\"oe_inline\" widget=\"many2many_tags\" readonly=\"1\"/>\n                            <span class=\"oe_inline text-muted\" invisible=\"supported_currency_ids\">\n                                All currencies are supported.\n                            </span>\n                        </div>\n                    </group>\n                    <notebook>\n                        <page string=\"Providers\" name=\"providers\">\n                            <field name=\"provider_ids\" readonly=\"1\">\n                                <tree decoration-muted=\"state == ''disabled''\" editable=\"bottom\">\n                                    <field name=\"name\"/>\n                                    <field name=\"state\"/>\n                                </tree>\n                            </field>\n                        </page>\n                        <page string=\"Brands\" name=\"brands\" invisible=\"not is_primary\">\n                            <field name=\"brand_ids\"/>\n                        </page>\n                        <page string=\"Configuration\" name=\"configuration\" groups=\"base.group_no_one\">\n                            <div class=\"alert alert-warning\" role=\"alert\">\n                                <i class=\"fa fa-exclamation-triangle\"/> These properties are set to\n                                match the behavior of providers and that of their integration with\n                                Odoo regarding this payment method. Any change may result in errors\n                                and should be tested on a test database first.\n                            </div>\n                            <group>\n                                <field name=\"support_tokenization\"/>\n                                <field name=\"support_express_checkout\"/>\n                                <field name=\"support_refund\"/>\n                                <field name=\"supported_country_ids\" widget=\"many2many_tags\" placeholder=\"Select countries. Leave empty to allow any.\"/>\n                                <field name=\"supported_currency_ids\" widget=\"many2many_tags\" placeholder=\"Select currencies. Leave empty to allow any.\"/>\n                                <field name=\"provider_ids\" string=\"Supported by\" widget=\"many2many_tags\"/>\n                            </group>\n                        </page>\n                    </notebook>\n                </sheet>\n            </form>"}', '<?xml version="1.0"?>
<form string="Payment Method">
                <sheet>
                    <field name="is_primary" invisible="True"/>
                    <field name="image" widget="image" class="oe_avatar"/>
                    <div class="oe_title">
                        <h1><field name="name" placeholder="Name"/></h1>
                    </div>
                    <group>
                        <field name="code" readonly="id" groups="base.group_no_one"/>
                        <field name="primary_payment_method_id" invisible="is_primary"/>
                        <field name="active"/>
                        <label for="supported_country_ids"/>
                        <div>
                            <field name="supported_country_ids" class="oe_inline" widget="many2many_tags" readonly="1"/>
                            <span class="oe_inline text-muted" invisible="supported_country_ids">
                                All countries are supported.
                            </span>
                        </div>
                        <label for="supported_currency_ids"/>
                        <div>
                            <field name="supported_currency_ids" class="oe_inline" widget="many2many_tags" readonly="1"/>
                            <span class="oe_inline text-muted" invisible="supported_currency_ids">
                                All currencies are supported.
                            </span>
                        </div>
                    </group>
                    <notebook>
                        <page string="Providers" name="providers">
                            <field name="provider_ids" readonly="1">
                                <tree decoration-muted="state == ''disabled''" editable="bottom">
                                    <field name="name"/>
                                    <field name="state"/>
                                </tree>
                            </field>
                        </page>
                        <page string="Brands" name="brands" invisible="not is_primary">
                            <field name="brand_ids"/>
                        </page>
                        <page string="Configuration" name="configuration" groups="base.group_no_one">
                            <div class="alert alert-warning" role="alert">
                                <i class="fa fa-exclamation-triangle"/> These properties are set to
                                match the behavior of providers and that of their integration with
                                Odoo regarding this payment method. Any change may result in errors
                                and should be tested on a test database first.
                            </div>
                            <group>
                                <field name="support_tokenization"/>
                                <field name="support_express_checkout"/>
                                <field name="support_refund"/>
                                <field name="supported_country_ids" widget="many2many_tags" placeholder="Select countries. Leave empty to allow any."/>
                                <field name="supported_currency_ids" widget="many2many_tags" placeholder="Select currencies. Leave empty to allow any."/>
                                <field name="provider_ids" string="Supported by" widget="many2many_tags"/>
                            </group>
                        </page>
                    </notebook>
                </sheet>
            </form>
        ', false, true, '2026-05-10 01:11:54.802158', '2026-05-10 01:11:54.802158', false);
INSERT INTO public.ir_ui_view VALUES (625, 16, NULL, 1, 1, 'payment.method.tree', 'payment.method', NULL, 'tree', 'payment/views/payment_method_views.xml', 'primary', '{"en_US": "<tree multi_edit=\"True\" decoration-muted=\"not active\">\n                <field name=\"sequence\" widget=\"handle\"/>\n                <field name=\"name\"/>\n                <field name=\"active\" widget=\"boolean_toggle\"/>\n            </tree>"}', '<?xml version="1.0"?>
<tree multi_edit="True" decoration-muted="not active">
                <field name="sequence" widget="handle"/>
                <field name="name"/>
                <field name="active" widget="boolean_toggle"/>
            </tree>
        ', false, true, '2026-05-10 01:11:54.802158', '2026-05-10 01:11:54.802158', false);
INSERT INTO public.ir_ui_view VALUES (626, 1, NULL, 1, 1, 'payment.method.kanban', 'payment.method', NULL, 'kanban', 'payment/views/payment_method_views.xml', 'primary', '{"en_US": "<kanban>\n                <templates>\n                    <t t-name=\"kanban-box\">\n                        <div t-attf-class=\"oe_kanban_content oe_kanban_global_click\">\n                            <div class=\"row\">\n                                <div class=\"col-6\">\n                                    <strong><field name=\"name\"/></strong>\n                                </div>\n                                <div class=\"col-6\">\n                                    <span class=\"float-end\">\n                                        <field name=\"image\" widget=\"image\" class=\"oe_avatar\"/>\n                                    </span>\n                                </div>\n                            </div>\n                        </div>\n                    </t>\n                </templates>\n            </kanban>"}', '<?xml version="1.0"?>
<kanban>
                <templates>
                    <t t-name="kanban-box">
                        <div t-attf-class="oe_kanban_content oe_kanban_global_click">
                            <div class="row">
                                <div class="col-6">
                                    <strong><field name="name"/></strong>
                                </div>
                                <div class="col-6">
                                    <span class="float-end">
                                        <field name="image" widget="image" class="oe_avatar"/>
                                    </span>
                                </div>
                            </div>
                        </div>
                    </t>
                </templates>
            </kanban>
        ', false, true, '2026-05-10 01:11:54.802158', '2026-05-10 01:11:54.802158', false);
INSERT INTO public.ir_ui_view VALUES (627, 16, NULL, 1, 1, 'payment.method.search', 'payment.method', NULL, 'search', 'payment/views/payment_method_views.xml', 'primary', '{"en_US": "<search>\n                <field name=\"name\" string=\"Name\"/>\n                <filter name=\"available_pms\" string=\"Available methods\" domain=\"[(''provider_ids.state'', ''!='', ''disabled'')]\"/>\n            </search>"}', '<?xml version="1.0"?>
<search>
                <field name="name" string="Name"/>
                <filter name="available_pms" string="Available methods" domain="[(''provider_ids.state'', ''!='', ''disabled'')]"/>
            </search>
        ', false, true, '2026-05-10 01:11:54.802158', '2026-05-10 01:11:54.802158', false);
INSERT INTO public.ir_ui_view VALUES (646, 16, NULL, 1, 1, 'account.payment.graph', 'account.payment', NULL, 'graph', 'account/views/account_payment_view.xml', 'primary', '{"en_US": "<graph string=\"Invoices\" sample=\"1\">\n                    <field name=\"payment_type\"/>\n                    <field name=\"journal_id\"/>\n                    <field name=\"amount\" type=\"measure\"/>\n                </graph>"}', '<?xml version="1.0"?>
<graph string="Invoices" sample="1">
                    <field name="payment_type"/>
                    <field name="journal_id"/>
                    <field name="amount" type="measure"/>
                </graph>
            ', false, true, '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295', false);
INSERT INTO public.ir_ui_view VALUES (628, 16, NULL, 1, 1, 'payment.transaction.form', 'payment.transaction', NULL, 'form', 'payment/views/payment_transaction_views.xml', 'primary', '{"en_US": "<form string=\"Payment Transactions\" create=\"false\" edit=\"false\">\n                <header>\n                    <button type=\"object\" name=\"action_capture\" invisible=\"state != ''authorized''\" string=\"Capture Transaction\" class=\"oe_highlight\"/>\n                    <button type=\"object\" name=\"action_void\" invisible=\"state != ''authorized''\" string=\"Void Transaction\" confirm=\"Are you sure you want to void the authorized transaction? This action can''t be undone.\"/>\n                    <field name=\"state\" widget=\"statusbar\"/>\n                </header>\n                <sheet>\n                    <div class=\"oe_button_box\" name=\"button_box\">\n                        <button name=\"action_view_refunds\" type=\"object\" class=\"oe_stat_button\" icon=\"fa-money\" invisible=\"refunds_count == 0\">\n                            <field name=\"refunds_count\" widget=\"statinfo\" string=\"Refunds\"/>\n                        </button>\n                    </div>\n                    <group>\n                        <group name=\"transaction_details\">\n                            <field name=\"reference\"/>\n                            <field name=\"source_transaction_id\" invisible=\"not source_transaction_id\"/>\n                            <field name=\"amount\"/>\n                            <field name=\"currency_id\" invisible=\"1\"/>\n                            <field name=\"payment_method_id\"/>\n                            <field name=\"provider_id\"/>\n                            <field name=\"company_id\" groups=\"base.group_multi_company\"/>\n                            <!-- Used by some provider-specific views -->\n                            <field name=\"provider_code\" invisible=\"1\"/>\n                            <field name=\"provider_reference\"/>\n                            <field name=\"token_id\" invisible=\"not token_id\"/>\n                            <field name=\"create_date\"/>\n                            <field name=\"last_state_change\"/>\n                            <field name=\"is_post_processed\" groups=\"base.group_no_one\"/>\n                        </group>\n                        <group name=\"transaction_partner\">\n                            <field name=\"partner_id\" widget=\"res_partner_many2one\"/>\n                            <label for=\"partner_address\" string=\"Address\"/>\n                            <div class=\"o_address_format\">\n                                <field name=\"partner_address\" placeholder=\"Address\" class=\"o_address_street\"/>\n                                <field name=\"partner_city\" placeholder=\"City\" class=\"o_address_city\"/>\n                                <field name=\"partner_state_id\" placeholder=\"State\" class=\"o_address_state\" options=\"{''no_open'': True}\"/>\n                                <field name=\"partner_zip\" placeholder=\"ZIP\" class=\"o_address_zip\"/>\n                                <field name=\"partner_country_id\" placeholder=\"Country\" class=\"o_address_country\" options=\"{''no_open'': True}\"/>\n                            </div>\n                            <field name=\"partner_email\" widget=\"email\"/>\n                            <field name=\"partner_phone\" widget=\"phone\"/>\n                            <field name=\"partner_lang\"/>\n                        </group>\n                    </group>\n                    <separator string=\"Child transactions\" invisible=\"not child_transaction_ids\"/>\n                    <field name=\"child_transaction_ids\" invisible=\"not child_transaction_ids\"/>\n                    <group string=\"Message\" invisible=\"not state_message\">\n                        <field name=\"state_message\" colspan=\"2\" nolabel=\"1\"/>\n                    </group>\n                </sheet>\n            </form>"}', '<?xml version="1.0"?>
<form string="Payment Transactions" create="false" edit="false">
                <header>
                    <button type="object" name="action_capture" invisible="state != ''authorized''" string="Capture Transaction" class="oe_highlight"/>
                    <button type="object" name="action_void" invisible="state != ''authorized''" string="Void Transaction" confirm="Are you sure you want to void the authorized transaction? This action can''t be undone."/>
                    <field name="state" widget="statusbar"/>
                </header>
                <sheet>
                    <div class="oe_button_box" name="button_box">
                        <button name="action_view_refunds" type="object" class="oe_stat_button" icon="fa-money" invisible="refunds_count == 0">
                            <field name="refunds_count" widget="statinfo" string="Refunds"/>
                        </button>
                    </div>
                    <group>
                        <group name="transaction_details">
                            <field name="reference"/>
                            <field name="source_transaction_id" invisible="not source_transaction_id"/>
                            <field name="amount"/>
                            <field name="currency_id" invisible="1"/>
                            <field name="payment_method_id"/>
                            <field name="provider_id"/>
                            <field name="company_id" groups="base.group_multi_company"/>
                            <!-- Used by some provider-specific views -->
                            <field name="provider_code" invisible="1"/>
                            <field name="provider_reference"/>
                            <field name="token_id" invisible="not token_id"/>
                            <field name="create_date"/>
                            <field name="last_state_change"/>
                            <field name="is_post_processed" groups="base.group_no_one"/>
                        </group>
                        <group name="transaction_partner">
                            <field name="partner_id" widget="res_partner_many2one"/>
                            <label for="partner_address" string="Address"/>
                            <div class="o_address_format">
                                <field name="partner_address" placeholder="Address" class="o_address_street"/>
                                <field name="partner_city" placeholder="City" class="o_address_city"/>
                                <field name="partner_state_id" placeholder="State" class="o_address_state" options="{''no_open'': True}"/>
                                <field name="partner_zip" placeholder="ZIP" class="o_address_zip"/>
                                <field name="partner_country_id" placeholder="Country" class="o_address_country" options="{''no_open'': True}"/>
                            </div>
                            <field name="partner_email" widget="email"/>
                            <field name="partner_phone" widget="phone"/>
                            <field name="partner_lang"/>
                        </group>
                    </group>
                    <separator string="Child transactions" invisible="not child_transaction_ids"/>
                    <field name="child_transaction_ids" invisible="not child_transaction_ids"/>
                    <group string="Message" invisible="not state_message">
                        <field name="state_message" colspan="2" nolabel="1"/>
                    </group>
                </sheet>
            </form>
        ', false, true, '2026-05-10 01:11:54.802158', '2026-05-10 01:11:54.802158', false);
INSERT INTO public.ir_ui_view VALUES (629, 16, NULL, 1, 1, 'payment.transaction.list', 'payment.transaction', NULL, 'tree', 'payment/views/payment_transaction_views.xml', 'primary', '{"en_US": "<tree string=\"Payment Transactions\" create=\"false\">\n                <field name=\"reference\"/>\n                <field name=\"create_date\"/>\n                <field name=\"payment_method_id\"/>\n                <field name=\"provider_id\"/>\n                <field name=\"partner_id\"/>\n                <field name=\"partner_name\"/>\n                <!-- Needed to display the currency of the amounts -->\n                <field name=\"currency_id\" column_invisible=\"True\"/>\n                <field name=\"amount\"/>\n                <field name=\"state\"/>\n                <field name=\"company_id\" groups=\"base.group_multi_company\" optional=\"show\"/>\n            </tree>"}', '<?xml version="1.0"?>
<tree string="Payment Transactions" create="false">
                <field name="reference"/>
                <field name="create_date"/>
                <field name="payment_method_id"/>
                <field name="provider_id"/>
                <field name="partner_id"/>
                <field name="partner_name"/>
                <!-- Needed to display the currency of the amounts -->
                <field name="currency_id" column_invisible="True"/>
                <field name="amount"/>
                <field name="state"/>
                <field name="company_id" groups="base.group_multi_company" optional="show"/>
            </tree>
        ', false, true, '2026-05-10 01:11:54.802158', '2026-05-10 01:11:54.802158', false);
INSERT INTO public.ir_ui_view VALUES (630, 16, NULL, 1, 1, 'payment.transaction.kanban', 'payment.transaction', NULL, 'kanban', 'payment/views/payment_transaction_views.xml', 'primary', '{"en_US": "<kanban class=\"o_kanban_mobile\" create=\"false\">\n                <templates>\n                    <t t-name=\"kanban-box\">\n                        <div t-attf-class=\"oe_kanban_content oe_kanban_global_click\">\n                            <div class=\"row\">\n                                <div class=\"col-6\">\n                                    <strong><field name=\"reference\"/></strong>\n                                </div>\n                                <div class=\"col-6\">\n                                    <span><field name=\"partner_name\"/></span>\n                                </div>\n                                <div class=\"col-6\">\n                                    <span class=\"float-end\">\n                                        <field name=\"amount\"/>\n                                        <field name=\"currency_id\" invisible=\"1\"/>\n                                    </span>\n                                </div>\n                            </div>\n                        </div>\n                    </t>\n                </templates>\n            </kanban>"}', '<?xml version="1.0"?>
<kanban class="o_kanban_mobile" create="false">
                <templates>
                    <t t-name="kanban-box">
                        <div t-attf-class="oe_kanban_content oe_kanban_global_click">
                            <div class="row">
                                <div class="col-6">
                                    <strong><field name="reference"/></strong>
                                </div>
                                <div class="col-6">
                                    <span><field name="partner_name"/></span>
                                </div>
                                <div class="col-6">
                                    <span class="float-end">
                                        <field name="amount"/>
                                        <field name="currency_id" invisible="1"/>
                                    </span>
                                </div>
                            </div>
                        </div>
                    </t>
                </templates>
            </kanban>
        ', false, true, '2026-05-10 01:11:54.802158', '2026-05-10 01:11:54.802158', false);
INSERT INTO public.ir_ui_view VALUES (631, 16, NULL, 1, 1, 'payment.transaction.search', 'payment.transaction', NULL, 'search', 'payment/views/payment_transaction_views.xml', 'primary', '{"en_US": "<search>\n                <field name=\"reference\"/>\n                <field name=\"provider_id\"/>\n                <field name=\"partner_id\"/>\n                <field name=\"partner_name\"/>\n                <group expand=\"1\" string=\"Group By\">\n                    <filter string=\"Provider\" name=\"provider_id\" context=\"{''group_by'': ''provider_id''}\"/>\n                    <filter string=\"Partner\" name=\"partner_id\" context=\"{''group_by'': ''partner_id''}\"/>\n                    <filter string=\"Status\" name=\"state\" context=\"{''group_by'': ''state''}\"/>\n                    <filter string=\"Company\" name=\"company\" context=\"{''group_by'': ''company_id''}\" groups=\"base.group_multi_company\"/>\n                </group>\n            </search>"}', '<?xml version="1.0"?>
<search>
                <field name="reference"/>
                <field name="provider_id"/>
                <field name="partner_id"/>
                <field name="partner_name"/>
                <group expand="1" string="Group By">
                    <filter string="Provider" name="provider_id" context="{''group_by'': ''provider_id''}"/>
                    <filter string="Partner" name="partner_id" context="{''group_by'': ''partner_id''}"/>
                    <filter string="Status" name="state" context="{''group_by'': ''state''}"/>
                    <filter string="Company" name="company" context="{''group_by'': ''company_id''}" groups="base.group_multi_company"/>
                </group>
            </search>
        ', false, true, '2026-05-10 01:11:54.802158', '2026-05-10 01:11:54.802158', false);
INSERT INTO public.ir_ui_view VALUES (632, 16, NULL, 1, 1, 'payment.token.form', 'payment.token', NULL, 'form', 'payment/views/payment_token_views.xml', 'primary', '{"en_US": "<form string=\"Payment Tokens\" create=\"false\" edit=\"false\">\n                <sheet>\n                    <field name=\"active\" invisible=\"1\"/>\n                    <div class=\"oe_button_box\" name=\"button_box\">\n                        <button class=\"oe_stat_button\" name=\"218\" type=\"action\" icon=\"fa-money\" string=\"Payments\">\n                        </button>\n                    </div>\n                    <widget name=\"web_ribbon\" title=\"Archived\" bg_color=\"text-bg-danger\" invisible=\"active\"/>\n                    <group>\n                        <group name=\"general_information\">\n                            <field name=\"payment_details\"/>\n                            <field name=\"payment_method_id\"/>\n                            <field name=\"partner_id\"/>\n                        </group>\n                        <group name=\"technical_information\">\n                            <field name=\"provider_id\"/>\n                            <field name=\"provider_ref\"/>\n                            <field name=\"company_id\" groups=\"base.group_multi_company\"/>\n                        </group>\n                    </group>\n                </sheet>\n            </form>"}', '<?xml version="1.0"?>
<form string="Payment Tokens" create="false" edit="false">
                <sheet>
                    <field name="active" invisible="1"/>
                    <div class="oe_button_box" name="button_box">
                        <button class="oe_stat_button" name="218" type="action" icon="fa-money" string="Payments">
                        </button>
                    </div>
                    <widget name="web_ribbon" title="Archived" bg_color="text-bg-danger" invisible="active"/>
                    <group>
                        <group name="general_information">
                            <field name="payment_details"/>
                            <field name="payment_method_id"/>
                            <field name="partner_id"/>
                        </group>
                        <group name="technical_information">
                            <field name="provider_id"/>
                            <field name="provider_ref"/>
                            <field name="company_id" groups="base.group_multi_company"/>
                        </group>
                    </group>
                </sheet>
            </form>
        ', false, true, '2026-05-10 01:11:54.802158', '2026-05-10 01:11:54.802158', false);
INSERT INTO public.ir_ui_view VALUES (634, 16, NULL, 1, 1, 'payment.token.search', 'payment.token', NULL, 'search', 'payment/views/payment_token_views.xml', 'primary', '{"en_US": "<search string=\"Payment Tokens\">\n                <field name=\"partner_id\"/>\n                <separator/>\n                <filter string=\"Archived\" name=\"inactive\" domain=\"[(''active'', ''='', False)]\"/>\n                <group expand=\"1\" string=\"Group By\">\n                    <filter string=\"Provider\" name=\"provider_id\" context=\"{''group_by'': ''provider_id''}\"/>\n                    <filter string=\"Partner\" name=\"partner_id\" context=\"{''group_by'': ''partner_id''}\"/>\n                    <filter string=\"Company\" name=\"company\" context=\"{''group_by'': ''company_id''}\" groups=\"base.group_multi_company\"/>\n                </group>\n            </search>"}', '<?xml version="1.0"?>
<search string="Payment Tokens">
                <field name="partner_id"/>
                <separator/>
                <filter string="Archived" name="inactive" domain="[(''active'', ''='', False)]"/>
                <group expand="1" string="Group By">
                    <filter string="Provider" name="provider_id" context="{''group_by'': ''provider_id''}"/>
                    <filter string="Partner" name="partner_id" context="{''group_by'': ''partner_id''}"/>
                    <filter string="Company" name="company" context="{''group_by'': ''company_id''}" groups="base.group_multi_company"/>
                </group>
            </search>
        ', false, true, '2026-05-10 01:11:54.802158', '2026-05-10 01:11:54.802158', false);
INSERT INTO public.ir_ui_view VALUES (635, 15, 125, 1, 1, 'view.res.partner.form.payment.defaultcreditcard', 'res.partner', NULL, 'form', 'payment/views/res_partner_views.xml', 'extension', '{"en_US": "<div name=\"button_box\" position=\"inside\">\n                <button type=\"action\" class=\"oe_stat_button\" icon=\"fa-credit-card-alt\" name=\"219\" context=\"{''search_default_partner_id'': id, ''create'': False, ''edit'': False}\" invisible=\"payment_token_count == 0\">\n                    <div class=\"o_form_field o_stat_info\">\n                        <span class=\"o_stat_value\">\n                            <field name=\"payment_token_count\" widget=\"statinfo\" nolabel=\"1\"/>\n                        </span>\n                        <span class=\"o_stat_text\">Saved Payment Methods</span>\n                    </div>\n                </button>\n            </div>"}', '<?xml version="1.0"?>
<div name="button_box" position="inside">
                <button type="action" class="oe_stat_button" icon="fa-credit-card-alt" name="219" context="{''search_default_partner_id'': id, ''create'': False, ''edit'': False}" invisible="payment_token_count == 0">
                    <div class="o_form_field o_stat_info">
                        <span class="o_stat_value">
                            <field name="payment_token_count" widget="statinfo" nolabel="1"/>
                        </span>
                        <span class="o_stat_text">Saved Payment Methods</span>
                    </div>
                </button>
            </div>
        ', false, true, '2026-05-10 01:11:54.802158', '2026-05-10 01:11:54.802158', false);
INSERT INTO public.ir_ui_view VALUES (636, 16, NULL, 1, 1, 'payment.capture.wizard.form', 'payment.capture.wizard', NULL, 'form', 'payment/wizards/payment_capture_wizard_views.xml', 'primary', '{"en_US": "<form string=\"Capture\">\n                <field name=\"transaction_ids\" invisible=\"1\"/>\n                <field name=\"is_amount_to_capture_valid\" invisible=\"1\"/>\n                <field name=\"currency_id\" invisible=\"1\"/>\n                <field name=\"support_partial_capture\" invisible=\"1\"/>\n                <field name=\"has_draft_children\" invisible=\"1\"/>\n                <field name=\"has_remaining_amount\" invisible=\"1\"/>\n                <div id=\"alert_draft_capture_tx\" role=\"alert\" class=\"alert alert-warning\" invisible=\"not has_draft_children\">\n                    <strong>Warning!</strong> There is a partial capture pending. Please wait a\n                    moment for it to be processed. Check your payment provider configuration if\n                    the capture is still pending after a few minutes.\n                </div>\n                <group name=\"readonly_fields\">\n                    <field name=\"authorized_amount\"/>\n                    <field name=\"captured_amount\" invisible=\"captured_amount &lt;= 0\"/>\n                    <field name=\"voided_amount\" invisible=\"voided_amount &lt;= 0\"/>\n                </group>\n                <hr/>\n                <group name=\"input_fields\">\n                    <label for=\"amount_to_capture\" class=\"oe_inline\"/>\n                    <div class=\"o_row\">\n                        <field name=\"amount_to_capture\" class=\"oe_inline\" readonly=\"support_partial_capture == ''full_only''\"/>\n                        <i class=\"fa fa-info-circle oe_inline\" invisible=\"support_partial_capture != ''full_only''\" title=\"Some of the transactions you intend to capture can only be captured in full. Handle the transactions individually to capture a partial amount.\"/>\n                    </div>\n                    <field name=\"void_remaining_amount\" readonly=\"not has_remaining_amount\"/>\n                </group>\n                <div id=\"alert_amount_to_capture_above_authorized_amount\" role=\"alert\" class=\"alert alert-warning mb-2\" invisible=\"is_amount_to_capture_valid\">\n                    <strong>Warning!</strong> You can not capture a negative amount nor more\n                    than <field name=\"available_amount\" class=\"oe_inline\" widget=\"monetary\"/>.\n                </div>\n                <footer>\n                    <button string=\"Capture\" type=\"object\" name=\"action_capture\" class=\"btn-primary\"/>\n                    <button string=\"Close\" special=\"cancel\" class=\"btn-secondary\"/>\n                </footer>\n            </form>"}', '<?xml version="1.0"?>
<form string="Capture">
                <field name="transaction_ids" invisible="1"/>
                <field name="is_amount_to_capture_valid" invisible="1"/>
                <field name="currency_id" invisible="1"/>
                <field name="support_partial_capture" invisible="1"/>
                <field name="has_draft_children" invisible="1"/>
                <field name="has_remaining_amount" invisible="1"/>
                <div id="alert_draft_capture_tx" role="alert" class="alert alert-warning" invisible="not has_draft_children">
                    <strong>Warning!</strong> There is a partial capture pending. Please wait a
                    moment for it to be processed. Check your payment provider configuration if
                    the capture is still pending after a few minutes.
                </div>
                <group name="readonly_fields">
                    <field name="authorized_amount"/>
                    <field name="captured_amount" invisible="captured_amount &lt;= 0"/>
                    <field name="voided_amount" invisible="voided_amount &lt;= 0"/>
                </group>
                <hr/>
                <group name="input_fields">
                    <label for="amount_to_capture" class="oe_inline"/>
                    <div class="o_row">
                        <field name="amount_to_capture" class="oe_inline" readonly="support_partial_capture == ''full_only''"/>
                        <i class="fa fa-info-circle oe_inline" invisible="support_partial_capture != ''full_only''" title="Some of the transactions you intend to capture can only be captured in full. Handle the transactions individually to capture a partial amount."/>
                    </div>
                    <field name="void_remaining_amount" readonly="not has_remaining_amount"/>
                </group>
                <div id="alert_amount_to_capture_above_authorized_amount" role="alert" class="alert alert-warning mb-2" invisible="is_amount_to_capture_valid">
                    <strong>Warning!</strong> You can not capture a negative amount nor more
                    than <field name="available_amount" class="oe_inline" widget="monetary"/>.
                </div>
                <footer>
                    <button string="Capture" type="object" name="action_capture" class="btn-primary"/>
                    <button string="Close" special="cancel" class="btn-secondary"/>
                </footer>
            </form>
        ', false, true, '2026-05-10 01:11:54.802158', '2026-05-10 01:11:54.802158', false);
INSERT INTO public.ir_ui_view VALUES (637, 16, NULL, 1, 1, 'payment.link.wizard.form', 'payment.link.wizard', NULL, 'form', 'payment/wizards/payment_link_wizard_views.xml', 'primary', '{"en_US": "<form string=\"Generate Payment Link\">\n                <div class=\"alert alert-warning fw-bold\" role=\"alert\" invisible=\"partner_email\">\n                     This partner has no email, which may cause issues with some payment providers.\n                     Setting an email for this partner is advised.\n                </div>\n                <group>\n                    <group>\n                        <field name=\"res_id\" invisible=\"1\"/>\n                        <field name=\"res_model\" invisible=\"1\"/>\n                        <field name=\"partner_id\" invisible=\"1\"/>\n                        <field name=\"partner_email\" invisible=\"1\"/>\n                        <field name=\"amount_max\" invisible=\"1\"/>\n                        <field name=\"amount\"/>\n                        <field name=\"warning_message\" invisible=\"1\"/>\n                        <field name=\"currency_id\" invisible=\"1\"/>\n                    </group>\n                </group>\n                <div name=\"payment_link_warning_information\" class=\"alert alert-warning text-center fw-bold\" role=\"alert\" invisible=\"warning_message == ''''\">\n                    <field name=\"warning_message\"/>\n                </div>\n                <footer>\n                    <field name=\"link\" string=\"Generate and Copy Payment Link\" readonly=\"1\" disabled=\"bool(warning_message)\" widget=\"PaymentWizardCopyClipboardButtonField\" data-hotkey=\"q\"/>\n                    <button string=\"Close\" class=\"btn btn-secondary rounded-2\" special=\"cancel\" data-hotkey=\"x\"/>\n                </footer>\n            </form>"}', '<?xml version="1.0"?>
<form string="Generate Payment Link">
                <div class="alert alert-warning fw-bold" role="alert" invisible="partner_email">
                     This partner has no email, which may cause issues with some payment providers.
                     Setting an email for this partner is advised.
                </div>
                <group>
                    <group>
                        <field name="res_id" invisible="1"/>
                        <field name="res_model" invisible="1"/>
                        <field name="partner_id" invisible="1"/>
                        <field name="partner_email" invisible="1"/>
                        <field name="amount_max" invisible="1"/>
                        <field name="amount"/>
                        <field name="warning_message" invisible="1"/>
                        <field name="currency_id" invisible="1"/>
                    </group>
                </group>
                <div name="payment_link_warning_information" class="alert alert-warning text-center fw-bold" role="alert" invisible="warning_message == ''''">
                    <field name="warning_message"/>
                </div>
                <footer>
                    <field name="link" string="Generate and Copy Payment Link" readonly="1" disabled="bool(warning_message)" widget="PaymentWizardCopyClipboardButtonField" data-hotkey="q"/>
                    <button string="Close" class="btn btn-secondary rounded-2" special="cancel" data-hotkey="x"/>
                </footer>
            </form>
        ', false, true, '2026-05-10 01:11:54.802158', '2026-05-10 01:11:54.802158', false);
INSERT INTO public.ir_ui_view VALUES (638, 16, NULL, 1, 1, 'payment.provider.onboarding.wizard.form', 'payment.provider.onboarding.wizard', NULL, 'form', 'payment/wizards/payment_onboarding_views.xml', 'primary', '{"en_US": "<form string=\"Choose a payment method\" class=\"o_onboarding_payment_provider_wizard\">\n                <div class=\"container\">\n                    <div class=\"row align-items-start\">\n                        <div class=\"col col-4\" name=\"left-column\">\n                                <field name=\"payment_method\" widget=\"radio\"/>\n                        </div>\n                        <div class=\"col\" name=\"right-column\">\n                            <div invisible=\"payment_method != ''paypal''\">\n                                <group>\n                                    <field name=\"paypal_email_account\" required=\"payment_method == ''paypal''\" string=\"Email\"/>\n                                    <field name=\"paypal_pdt_token\" password=\"True\" required=\"payment_method == ''paypal''\"/>\n                                </group>\n                                <a href=\"https://www.odoo.com/documentation/17.0/applications/finance/payment_providers/paypal.html\" target=\"_blank\">\n                                    <span><i class=\"oi oi-arrow-right\"/> How to configure your PayPal account</span>\n                                </a>\n                            </div>\n\n                            <div invisible=\"payment_method != ''manual''\">\n                                <group>\n                                    <field name=\"manual_name\" required=\"payment_method == ''manual''\"/>\n                                    <field name=\"journal_name\" required=\"payment_method == ''manual''\"/>\n                                    <field name=\"acc_number\" required=\"payment_method == ''manual''\"/>\n                                    <field name=\"manual_post_msg\" required=\"payment_method == ''manual''\"/>\n                                </group>\n                            </div>\n                        </div>\n                    </div>\n                </div>\n                <footer>\n                    <button name=\"add_payment_methods\" string=\"Apply\" class=\"oe_highlight\" type=\"object\" data-hotkey=\"q\"/>\n                    <button special=\"cancel\" data-hotkey=\"x\" string=\"Cancel\"/>\n                </footer>\n            </form>"}', '<?xml version="1.0"?>
<form string="Choose a payment method" class="o_onboarding_payment_provider_wizard">
                <div class="container">
                    <div class="row align-items-start">
                        <div class="col col-4" name="left-column">
                                <field name="payment_method" widget="radio"/>
                        </div>
                        <div class="col" name="right-column">
                            <div invisible="payment_method != ''paypal''">
                                <group>
                                    <field name="paypal_email_account" required="payment_method == ''paypal''" string="Email"/>
                                    <field name="paypal_pdt_token" password="True" required="payment_method == ''paypal''"/>
                                </group>
                                <a href="https://www.odoo.com/documentation/17.0/applications/finance/payment_providers/paypal.html" target="_blank">
                                    <span><i class="oi oi-arrow-right"/> How to configure your PayPal account</span>
                                </a>
                            </div>

                            <div invisible="payment_method != ''manual''">
                                <group>
                                    <field name="manual_name" required="payment_method == ''manual''"/>
                                    <field name="journal_name" required="payment_method == ''manual''"/>
                                    <field name="acc_number" required="payment_method == ''manual''"/>
                                    <field name="manual_post_msg" required="payment_method == ''manual''"/>
                                </group>
                            </div>
                        </div>
                    </div>
                </div>
                <footer>
                    <button name="add_payment_methods" string="Apply" class="oe_highlight" type="object" data-hotkey="q"/>
                    <button special="cancel" data-hotkey="x" string="Cancel"/>
                </footer>
            </form>
        ', false, true, '2026-05-10 01:11:54.802158', '2026-05-10 01:11:54.802158', false);
INSERT INTO public.ir_ui_view VALUES (639, 16, NULL, 1, 1, 'Public spreadsheet layout', NULL, 'spreadsheet.public_spreadsheet_layout', 'qweb', 'spreadsheet/views/public_readonly_spreadsheet_templates.xml', 'primary', '{"en_US": "<t name=\"Public spreadsheet layout\" t-name=\"spreadsheet.public_spreadsheet_layout\">\n    <t t-call=\"web.layout\">\n        <t t-set=\"head\">\n            <script>\n                odoo.__session_info__ = <t t-out=\"json.dumps(session_info)\"/>;\n                odoo.__session_info__.spreadsheet_public_props = <t t-out=\"json.dumps(props)\"/>;\n            </script>\n            <t t-call-assets=\"spreadsheet.public_spreadsheet\"/>\n        </t>\n        <div class=\"d-flex flex-column justify-content vh-100 o-public-spreadsheet\">\n            <header class=\"container-fluid p-0 d-flex align-items-center justify-content-between border-bottom\">\n                <div t-out=\"spreadsheet_name\" class=\"text-primary fw-bold ps-3\"/>\n                <div class=\"fst-italic flex-fill ps-3\">\n                    Frozen and copied on <span t-field=\"share.create_date\"/>\n                    <div class=\"d-inline-flex\">\n                        <a class=\"btn btn-secondary btn-block o_download_btn\" t-if=\"props[''downloadExcelUrl'']\" t-att-href=\"props[''downloadExcelUrl'']\" title=\"Download\"><i class=\"fa fa-download\"/></a>\n                    </div>\n                </div>\n                <div class=\"nav d-table my-auto\">\n                    <t t-call=\"portal.user_dropdown\">\n                        <t t-set=\"_user_name\" t-value=\"True\"/>\n                        <t t-set=\"_item_class\" t-valuef=\"nav-item d-table-cell text-center\"/>\n                        <t t-set=\"_link_class\" t-valuef=\"nav-link fw-bold\"/>\n                    </t>\n                    <t t-call=\"portal.user_sign_in_redirect\">\n                        <t t-set=\"_item_class\" t-valuef=\"nav-item d-table-cell text-center\"/>\n                        <t t-set=\"_link_class\" t-valuef=\"nav-link fw-bold\"/>\n                    </t>\n                </div>\n            </header>\n            <main id=\"spreadsheet-mount-anchor\" class=\"flex-fill\"/>\n        </div>\n    </t>\n</t>"}', '<?xml version="1.0"?>
<t name="Public spreadsheet layout" t-name="spreadsheet.public_spreadsheet_layout">
    <t t-call="web.layout">
        <t t-set="head">
            <script>
                odoo.__session_info__ = <t t-out="json.dumps(session_info)"/>;
                odoo.__session_info__.spreadsheet_public_props = <t t-out="json.dumps(props)"/>;
            </script>
            <t t-call-assets="spreadsheet.public_spreadsheet"/>
        </t>
        <div class="d-flex flex-column justify-content vh-100 o-public-spreadsheet">
            <header class="container-fluid p-0 d-flex align-items-center justify-content-between border-bottom">
                <div t-out="spreadsheet_name" class="text-primary fw-bold ps-3"/>
                <div class="fst-italic flex-fill ps-3">
                    Frozen and copied on <span t-field="share.create_date"/>
                    <div class="d-inline-flex">
                        <a class="btn btn-secondary btn-block o_download_btn" t-if="props[''downloadExcelUrl'']" t-att-href="props[''downloadExcelUrl'']" title="Download"><i class="fa fa-download"/></a>
                    </div>
                </div>
                <div class="nav d-table my-auto">
                    <t t-call="portal.user_dropdown">
                        <t t-set="_user_name" t-value="True"/>
                        <t t-set="_item_class" t-valuef="nav-item d-table-cell text-center"/>
                        <t t-set="_link_class" t-valuef="nav-link fw-bold"/>
                    </t>
                    <t t-call="portal.user_sign_in_redirect">
                        <t t-set="_item_class" t-valuef="nav-item d-table-cell text-center"/>
                        <t t-set="_link_class" t-valuef="nav-link fw-bold"/>
                    </t>
                </div>
            </header>
            <main id="spreadsheet-mount-anchor" class="flex-fill"/>
        </div>
    </t>
</t>

', false, true, '2026-05-10 01:11:56.797975', '2026-05-10 01:11:56.797975', false);
INSERT INTO public.ir_ui_view VALUES (640, 16, NULL, 1, 1, 'account.payment.tree', 'account.payment', NULL, 'tree', 'account/views/account_payment_view.xml', 'primary', '{"en_US": "<tree edit=\"false\" sample=\"1\" decoration-info=\"state == ''draft''\" decoration-muted=\"state == ''cancel''\">\n                    <header>\n                        <button name=\"action_post\" type=\"object\" string=\"Confirm\"/>\n                    </header>\n                    <field name=\"company_currency_id\" column_invisible=\"True\"/>\n                    <field name=\"suitable_journal_ids\" column_invisible=\"True\"/>\n                    <field name=\"available_payment_method_line_ids\" column_invisible=\"True\"/>\n                    <field name=\"date\" readonly=\"state in [''cancel'', ''posted'']\"/>\n                    <field name=\"name\"/>\n                    <field name=\"journal_id\"/>\n                    <field name=\"company_id\" optional=\"hide\" groups=\"base.group_multi_company\"/>\n                    <field name=\"payment_method_line_id\"/>\n                    <field name=\"partner_id\" string=\"Customer\"/>\n                    <field name=\"amount_signed\" string=\"Amount in Currency\" optional=\"hide\" groups=\"!base.group_multi_currency\"/>\n                    <field name=\"amount_signed\" string=\"Amount in Currency\" optional=\"show\" groups=\"base.group_multi_currency\"/>\n                    <field name=\"currency_id\" string=\"Payment Currency\" optional=\"hide\"/>\n                    <field name=\"activity_ids\" widget=\"list_activity\" optional=\"hide\"/>\n                    <field name=\"amount_company_currency_signed\" widget=\"monetary\" string=\"Amount\" sum=\"Total\"/>\n                    <field name=\"state\" widget=\"badge\" decoration-info=\"state == ''draft''\" decoration-success=\"state == ''posted''\"/>\n                </tree>"}', '<?xml version="1.0"?>
<tree edit="false" sample="1" decoration-info="state == ''draft''" decoration-muted="state == ''cancel''">
                    <header>
                        <button name="action_post" type="object" string="Confirm"/>
                    </header>
                    <field name="company_currency_id" column_invisible="True"/>
                    <field name="suitable_journal_ids" column_invisible="True"/>
                    <field name="available_payment_method_line_ids" column_invisible="True"/>
                    <field name="date" readonly="state in [''cancel'', ''posted'']"/>
                    <field name="name"/>
                    <field name="journal_id"/>
                    <field name="company_id" optional="hide" groups="base.group_multi_company"/>
                    <field name="payment_method_line_id"/>
                    <field name="partner_id" string="Customer"/>
                    <field name="amount_signed" string="Amount in Currency" optional="hide" groups="!base.group_multi_currency"/>
                    <field name="amount_signed" string="Amount in Currency" optional="show" groups="base.group_multi_currency"/>
                    <field name="currency_id" string="Payment Currency" optional="hide"/>
                    <field name="activity_ids" widget="list_activity" optional="hide"/>
                    <field name="amount_company_currency_signed" widget="monetary" string="Amount" sum="Total"/>
                    <field name="state" widget="badge" decoration-info="state == ''draft''" decoration-success="state == ''posted''"/>
                </tree>
            ', false, true, '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295', false);
