INSERT INTO public.ir_ui_view VALUES (643, 16, NULL, 1, 1, 'account.payment.kanban', 'account.payment', NULL, 'kanban', 'account/views/account_payment_view.xml', 'primary', '{"en_US": "<kanban class=\"o_kanban_mobile\" create=\"0\" group_create=\"0\" sample=\"1\">\n                    <field name=\"name\"/>\n                    <field name=\"partner_id\"/>\n                    <field name=\"date\"/>\n                    <field name=\"state\"/>\n                    <templates>\n                        <t t-name=\"kanban-box\">\n                            <div t-attf-class=\"oe_kanban_global_click\">\n                                <div class=\"row mb4\">\n                                    <div class=\"col-6\">\n                                        <strong><span><field name=\"name\"/></span></strong>\n                                    </div>\n                                    <div class=\"col-6 text-end\">\n                                        <strong><i class=\"fa fa-clock-o\" role=\"img\" aria-label=\"Date\" title=\"Date\"/> <t t-out=\"record.date.value\"/></strong>\n                                    </div>\n                                </div>\n                                <div class=\"row\">\n                                    <div class=\"col-12\">\n                                        <span><field name=\"partner_id\"/></span>\n                                    </div>\n                                </div>\n                                <div class=\"row\">\n                                    <div class=\"col-6\">\n                                        <field name=\"amount\" widget=\"monetary\"/>\n                                        <field name=\"currency_id\" invisible=\"1\"/>\n                                    </div>\n                                    <div class=\"col-6\">\n                                        <span class=\"float-end\">\n                                            <field name=\"state\" widget=\"label_selection\" options=\"{''classes'': {''draft'': ''secondary'', ''sent'': ''success''}}\"/>\n                                        </span>\n                                    </div>\n                                </div>\n                            </div>\n                        </t>\n                    </templates>\n                </kanban>"}', '<?xml version="1.0"?>
<kanban class="o_kanban_mobile" create="0" group_create="0" sample="1">
                    <field name="name"/>
                    <field name="partner_id"/>
                    <field name="date"/>
                    <field name="state"/>
                    <templates>
                        <t t-name="kanban-box">
                            <div t-attf-class="oe_kanban_global_click">
                                <div class="row mb4">
                                    <div class="col-6">
                                        <strong><span><field name="name"/></span></strong>
                                    </div>
                                    <div class="col-6 text-end">
                                        <strong><i class="fa fa-clock-o" role="img" aria-label="Date" title="Date"/> <t t-out="record.date.value"/></strong>
                                    </div>
                                </div>
                                <div class="row">
                                    <div class="col-12">
                                        <span><field name="partner_id"/></span>
                                    </div>
                                </div>
                                <div class="row">
                                    <div class="col-6">
                                        <field name="amount" widget="monetary"/>
                                        <field name="currency_id" invisible="1"/>
                                    </div>
                                    <div class="col-6">
                                        <span class="float-end">
                                            <field name="state" widget="label_selection" options="{''classes'': {''draft'': ''secondary'', ''sent'': ''success''}}"/>
                                        </span>
                                    </div>
                                </div>
                            </div>
                        </t>
                    </templates>
                </kanban>
            ', false, true, '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295', false);
INSERT INTO public.ir_ui_view VALUES (644, 16, NULL, 1, 1, 'account.payment.search', 'account.payment', NULL, 'search', 'account/views/account_payment_view.xml', 'primary', '{"en_US": "<search string=\"Payments\">\n                    <field name=\"name\" string=\"Payment\" filter_domain=\"[''|'', ''|'', ''|'', ''|'', (''name'', ''ilike'', self), (''partner_id'', ''ilike'', self), (''ref'', ''ilike'', self), (''amount_company_currency_signed'' , ''ilike'', self), (''amount'', ''ilike'', self)]\"/>\n                    <field name=\"partner_id\" string=\"Customer/Vendor\"/>\n                    <field name=\"journal_id\"/>\n                    <field name=\"is_internal_transfer\"/>\n                    <separator/>\n                    <filter string=\"Customer Payments\" name=\"inbound_filter\" domain=\"[(''partner_type'', ''='', ''customer''), (''is_internal_transfer'', ''='', False)]\"/>\n                    <filter string=\"Vendor Payments\" name=\"outbound_filter\" domain=\"[(''partner_type'', ''='', ''supplier''), (''is_internal_transfer'', ''='', False)]\"/>\n                    <filter string=\"Internal Transfers\" name=\"transfers_filter\" domain=\"[(''is_internal_transfer'', ''='', True)]\"/>\n                    <separator/>\n                    <filter string=\"Draft\" name=\"state_draft\" domain=\"[(''state'', ''='', ''draft'')]\"/>\n                    <filter string=\"Posted\" name=\"state_posted\" domain=\"[(''state'', ''='', ''posted'')]\"/>\n                    <separator/>\n                    <filter string=\"Sent\" name=\"state_sent\" domain=\"[(''is_move_sent'', ''='', True)]\"/>\n                    <filter string=\"No Bank Matching\" name=\"unmatched\" domain=\"[(''is_matched'', ''='', False)]\"/>\n                    <filter string=\"Reconciled\" name=\"reconciled\" domain=\"[(''is_reconciled'', ''='', True)]\"/>\n                    <separator/>\n                    <filter string=\"Payment Date\" name=\"date\" date=\"date\"/>\n                    <separator/>\n                    <field name=\"company_id\" groups=\"base.group_multi_company\"/>\n                    <filter string=\"Customer/Vendor\" name=\"partner\" domain=\"[]\" context=\"{''group_by'': ''partner_id''}\"/>\n                    <filter string=\"Journal\" name=\"journal\" domain=\"[]\" context=\"{''group_by'': ''journal_id''}\"/>\n                    <filter string=\"Payment Method Line\" name=\"paymentmethodline\" domain=\"[]\" context=\"{''group_by'': ''payment_method_line_id''}\"/>\n                    <filter string=\"Status\" name=\"state\" domain=\"[]\" context=\"{''group_by'': ''state''}\"/>\n                    <filter string=\"Payment Date\" name=\"groupby_date\" domain=\"[]\" context=\"{''group_by'': ''date''}\"/>\n                    <filter string=\"Currency\" name=\"currency\" domain=\"[]\" context=\"{''group_by'': ''currency_id''}\" groups=\"base.group_multi_currency\"/>\n                    <filter string=\"Company\" name=\"company\" domain=\"[]\" context=\"{''group_by'': ''company_id''}\" groups=\"base.group_multi_company\"/>\n                    <separator/>\n                    <filter invisible=\"1\" string=\"Late Activities\" name=\"activities_overdue\" domain=\"[(''my_activity_date_deadline'', ''&lt;'', context_today().strftime(''%Y-%m-%d''))]\" help=\"Show all records which has next action date is before today\"/>\n                    <filter invisible=\"1\" string=\"Today Activities\" name=\"activities_today\" domain=\"[(''my_activity_date_deadline'', ''='', context_today().strftime(''%Y-%m-%d''))]\"/>\n                    <filter invisible=\"1\" string=\"Future Activities\" name=\"activities_upcoming_all\" domain=\"[(''my_activity_date_deadline'', ''&gt;'', context_today().strftime(''%Y-%m-%d''))]\"/>\n                </search>"}', '<?xml version="1.0"?>
<search string="Payments">
                    <field name="name" string="Payment" filter_domain="[''|'', ''|'', ''|'', ''|'', (''name'', ''ilike'', self), (''partner_id'', ''ilike'', self), (''ref'', ''ilike'', self), (''amount_company_currency_signed'' , ''ilike'', self), (''amount'', ''ilike'', self)]"/>
                    <field name="partner_id" string="Customer/Vendor"/>
                    <field name="journal_id"/>
                    <field name="is_internal_transfer"/>
                    <separator/>
                    <filter string="Customer Payments" name="inbound_filter" domain="[(''partner_type'', ''='', ''customer''), (''is_internal_transfer'', ''='', False)]"/>
                    <filter string="Vendor Payments" name="outbound_filter" domain="[(''partner_type'', ''='', ''supplier''), (''is_internal_transfer'', ''='', False)]"/>
                    <filter string="Internal Transfers" name="transfers_filter" domain="[(''is_internal_transfer'', ''='', True)]"/>
                    <separator/>
                    <filter string="Draft" name="state_draft" domain="[(''state'', ''='', ''draft'')]"/>
                    <filter string="Posted" name="state_posted" domain="[(''state'', ''='', ''posted'')]"/>
                    <separator/>
                    <filter string="Sent" name="state_sent" domain="[(''is_move_sent'', ''='', True)]"/>
                    <filter string="No Bank Matching" name="unmatched" domain="[(''is_matched'', ''='', False)]"/>
                    <filter string="Reconciled" name="reconciled" domain="[(''is_reconciled'', ''='', True)]"/>
                    <separator/>
                    <filter string="Payment Date" name="date" date="date"/>
                    <separator/>
                    <field name="company_id" groups="base.group_multi_company"/>
                    <filter string="Customer/Vendor" name="partner" domain="[]" context="{''group_by'': ''partner_id''}"/>
                    <filter string="Journal" name="journal" domain="[]" context="{''group_by'': ''journal_id''}"/>
                    <filter string="Payment Method Line" name="paymentmethodline" domain="[]" context="{''group_by'': ''payment_method_line_id''}"/>
                    <filter string="Status" name="state" domain="[]" context="{''group_by'': ''state''}"/>
                    <filter string="Payment Date" name="groupby_date" domain="[]" context="{''group_by'': ''date''}"/>
                    <filter string="Currency" name="currency" domain="[]" context="{''group_by'': ''currency_id''}" groups="base.group_multi_currency"/>
                    <filter string="Company" name="company" domain="[]" context="{''group_by'': ''company_id''}" groups="base.group_multi_company"/>
                    <separator/>
                    <filter invisible="1" string="Late Activities" name="activities_overdue" domain="[(''my_activity_date_deadline'', ''&lt;'', context_today().strftime(''%Y-%m-%d''))]" help="Show all records which has next action date is before today"/>
                    <filter invisible="1" string="Today Activities" name="activities_today" domain="[(''my_activity_date_deadline'', ''='', context_today().strftime(''%Y-%m-%d''))]"/>
                    <filter invisible="1" string="Future Activities" name="activities_upcoming_all" domain="[(''my_activity_date_deadline'', ''&gt;'', context_today().strftime(''%Y-%m-%d''))]"/>
                </search>
            ', false, true, '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295', false);
INSERT INTO public.ir_ui_view VALUES (645, 16, NULL, 1, 1, 'account.payment.form', 'account.payment', NULL, 'form', 'account/views/account_payment_view.xml', 'primary', '{"en_US": "<form string=\"Register Payment\">\n                    <header>\n                        <button name=\"action_post\" string=\"Confirm\" type=\"object\" class=\"oe_highlight\" invisible=\"state != ''draft''\" data-hotkey=\"q\"/>\n                        <button name=\"action_draft\" string=\"Reset To Draft\" type=\"object\" class=\"btn btn-secondary\" invisible=\"not show_reset_to_draft_button\" groups=\"account.group_account_invoice\" data-hotkey=\"w\"/>\n                        <button name=\"action_cancel\" string=\"Cancel\" type=\"object\" invisible=\"not id or state != ''draft''\" data-hotkey=\"x\"/>\n                        <button string=\"Request Cancel\" name=\"button_request_cancel\" type=\"object\" groups=\"account.group_account_invoice\" invisible=\"state != ''posted'' or show_reset_to_draft_button or not need_cancel_request\" data-hotkey=\"w\"/>\n                        <button name=\"mark_as_sent\" string=\"Mark as Sent\" type=\"object\" data-hotkey=\"v\" invisible=\"state != ''posted'' or is_move_sent or payment_method_code != ''manual''\"/>\n                        <button name=\"unmark_as_sent\" string=\"Unmark as Sent\" type=\"object\" data-hotkey=\"k\" invisible=\"state != ''posted'' or not is_move_sent or payment_method_code != ''manual''\"/>\n                        <field name=\"state\" widget=\"statusbar\" statusbar_visible=\"draft,posted\"/>\n                    </header>\n                    <div class=\"alert alert-warning text-center\" role=\"alert\" invisible=\"not is_internal_transfer or not require_partner_bank_account or partner_bank_id\">\n                        The selected payment method requires a bank account but none is set on\n                        <button class=\"oe_link alert-link\" type=\"object\" name=\"action_open_destination_journal\" style=\"padding: 0; vertical-align: baseline;\">the destination journal</button>.\n                    </div>\n                    <sheet>\n                        <!-- Invisible fields -->\n                        <field name=\"id\" invisible=\"1\"/>\n                        <field name=\"is_move_sent\" invisible=\"1\"/>\n                        <field name=\"need_cancel_request\" invisible=\"1\"/>\n                        <field name=\"show_reset_to_draft_button\" invisible=\"1\"/>\n                        <field name=\"is_reconciled\" invisible=\"1\"/>\n                        <field name=\"is_matched\" invisible=\"1\"/>\n                        <field name=\"payment_method_code\" invisible=\"1\"/>\n                        <field name=\"show_partner_bank_account\" invisible=\"1\"/>\n                        <field name=\"require_partner_bank_account\" invisible=\"1\"/>\n                        <field name=\"available_payment_method_line_ids\" invisible=\"1\"/>\n                        <field name=\"available_partner_bank_ids\" invisible=\"1\"/>\n                        <field name=\"suitable_journal_ids\" invisible=\"1\"/>\n                        <field name=\"country_code\" invisible=\"1\"/>\n                        <field name=\"partner_type\" invisible=\"1\"/>\n                        <field name=\"posted_before\" invisible=\"1\"/>\n                        <field name=\"reconciled_invoices_type\" invisible=\"1\"/>\n                        <field name=\"company_id\" invisible=\"1\"/>\n                        <field name=\"paired_internal_transfer_payment_id\" invisible=\"1\"/>\n                        <field name=\"available_journal_ids\" invisible=\"1\"/>\n                        <field name=\"currency_id\" invisible=\"1\"/>\n\n                        <div class=\"oe_button_box\" name=\"button_box\">\n                            <!-- Invoice stat button -->\n                            <button name=\"button_open_invoices\" type=\"object\" class=\"oe_stat_button\" icon=\"fa-bars\" invisible=\"reconciled_invoices_count == 0\">\n                                <div class=\"o_form_field o_stat_info\">\n                                    <span class=\"o_stat_text\">\n                                        <field name=\"reconciled_invoices_count\"/>\n                                        <span invisible=\"reconciled_invoices_type != ''invoice''\"> Invoice</span>\n                                        <span invisible=\"reconciled_invoices_type == ''invoice''\"> Credit Note</span>\n                                    </span>\n                                </div>\n                            </button>\n\n                            <!-- Bill stat button -->\n                            <button name=\"button_open_bills\" type=\"object\" class=\"oe_stat_button\" icon=\"fa-bars\" invisible=\"reconciled_bills_count == 0\">\n                                <div class=\"o_form_field o_stat_info\">\n                                    <span class=\"o_stat_text\">\n                                        <field name=\"reconciled_bills_count\"/>\n                                        <span> Bill</span>\n                                    </span>\n                                </div>\n                            </button>\n\n                            <!-- Statement stat button -->\n                            <button name=\"button_open_statement_lines\" type=\"object\" class=\"oe_stat_button\" icon=\"fa-bars\" invisible=\"reconciled_statement_lines_count == 0\">\n                                <div class=\"o_form_field o_stat_info\">\n                                    <field name=\"reconciled_statement_lines_count\"/>\n                                    <span class=\"o_stat_text\">Transaction</span>\n                                </div>\n                            </button>\n\n                            <!-- Journal Entry  button -->\n                            <button name=\"button_open_journal_entry\" type=\"object\" class=\"oe_stat_button\" icon=\"fa-bars\" groups=\"account.group_account_user,account.group_account_readonly\">\n                                <div class=\"o_stat_info\">\n                                    <span class=\"o_stat_text\">Journal Entry</span>\n                                </div>\n                            </button>\n                        </div>\n\n                        <widget name=\"web_ribbon\" text=\"Invoicing App Legacy\" bg_color=\"text-bg-info\" invisible=\"state != ''invoicing_legacy''\" tooltip=\"This payment has been generated through the Invoicing app, before installing Accounting. It has been disabled by the ''Invoicing Switch Threshold Date'' setting so that it does not impact your accounting.\"/>\n\n                        <div class=\"oe_title\">\n                            <h1 invisible=\"state != ''draft''\"><span>Draft</span></h1>\n                            <h1 invisible=\"state == ''draft''\"><field name=\"name\" readonly=\"1\"/></h1>\n                        </div>\n\n                        <group name=\"main_group\">\n                            <group name=\"group1\">\n                                <label for=\"is_internal_transfer\"/>\n                                <div>\n                                    <field name=\"is_internal_transfer\" readonly=\"state != ''draft''\"/>\n                                    <span invisible=\"paired_internal_transfer_payment_id or not is_internal_transfer or state != ''draft''\" class=\"fst-italic\">\n                                        A second payment will be created in the destination journal.\n                                    </span>\n                                </div>\n                                <field name=\"payment_type\" widget=\"radio\" options=\"{''horizontal'': True}\" readonly=\"state != ''draft''\"/>\n                                <field name=\"partner_id\" context=\"{''default_is_company'': True}\" string=\"Customer\" options=\"{''no_quick_create'': True}\" invisible=\"partner_type != ''customer'' or is_internal_transfer\" readonly=\"state != ''draft''\"/>\n                                <field name=\"partner_id\" context=\"{''default_is_company'': True}\" string=\"Vendor\" options=\"{''no_quick_create'': True}\" invisible=\"partner_type != ''supplier'' or is_internal_transfer\" readonly=\"state != ''draft''\"/>\n                                <label for=\"amount\"/>\n                                <div name=\"amount_div\" class=\"o_row\">\n                                    <field name=\"amount\" readonly=\"state != ''draft''\"/>\n                                    <field name=\"currency_id\" options=\"{''no_create'': True, ''no_open'': True}\" required=\"1\" readonly=\"state != ''draft''\" groups=\"base.group_multi_currency\"/>\n                                </div>\n                                <field name=\"date\" readonly=\"state != ''draft''\"/>\n                                <field name=\"ref\" string=\"Memo\"/>\n                            </group>\n                            <group name=\"group2\">\n                                <field name=\"journal_id\" domain=\"[(''id'', ''in'', available_journal_ids)]\" readonly=\"state != ''draft''\"/>\n                                <field name=\"payment_method_line_id\" options=\"{''no_create'': True, ''no_open'': True}\" required=\"1\" readonly=\"state != ''draft''\"/>\n\n                                <field name=\"partner_bank_id\" string=\"Customer Bank Account\" context=\"{''default_partner_id'': partner_id, ''display_account_trust'': True}\" invisible=\"not show_partner_bank_account or partner_type != ''customer'' or is_internal_transfer or payment_type == ''inbound''\" required=\"require_partner_bank_account and not is_internal_transfer\"/>\n\n                                <field name=\"partner_bank_id\" string=\"Vendor Bank Account\" context=\"{''default_partner_id'': partner_id, ''display_account_trust'': True}\" invisible=\"not show_partner_bank_account or partner_type != ''supplier'' or is_internal_transfer or payment_type == ''inbound''\" required=\"require_partner_bank_account and not is_internal_transfer\"/>\n\n                                <!-- This field should always be readonly but using readonly=\"1\" overrides the other partner_bank_id\n                                fields readonly condition in the framework, preventing the modification of these fields -->\n                                <field name=\"partner_bank_id\" string=\"Company Bank Account\" context=\"{''default_partner_id'': partner_id, ''display_account_trust'': True}\" invisible=\"not show_partner_bank_account or is_internal_transfer or payment_type == ''outbound''\" required=\"require_partner_bank_account and not is_internal_transfer\"/>\n\n                                <field name=\"destination_journal_id\" placeholder=\"e.g. Cash\" context=\"{''default_partner_id'': partner_id}\" invisible=\"not is_internal_transfer\" readonly=\"state != ''draft''\" required=\"is_internal_transfer and state == ''draft''\"/>\n                            </group>\n                            <group>\n                                <field name=\"qr_code\" invisible=\"1\"/>\n                                <div invisible=\"not qr_code\" colspan=\"2\" class=\"text-center\">\n                                    <field name=\"qr_code\" widget=\"html\"/>\n                                </div>\n                            </group>\n                        </group>\n                        <group>\n                            <!-- To be used in localizations requiring to add a page -->\n                            <notebook name=\"payment_notebook\" colspan=\"2\"/>\n                        </group>\n                    </sheet>\n                    <div class=\"o_attachment_preview\"/>\n                    <div class=\"oe_chatter\">\n                        <field name=\"message_follower_ids\" groups=\"base.group_user\"/>\n                        <field name=\"activity_ids\"/>\n                        <field name=\"message_ids\"/>\n                    </div>\n                </form>"}', '<?xml version="1.0"?>
<form string="Register Payment">
                    <header>
                        <button name="action_post" string="Confirm" type="object" class="oe_highlight" invisible="state != ''draft''" data-hotkey="q"/>
                        <button name="action_draft" string="Reset To Draft" type="object" class="btn btn-secondary" invisible="not show_reset_to_draft_button" groups="account.group_account_invoice" data-hotkey="w"/>
                        <button name="action_cancel" string="Cancel" type="object" invisible="not id or state != ''draft''" data-hotkey="x"/>
                        <button string="Request Cancel" name="button_request_cancel" type="object" groups="account.group_account_invoice" invisible="state != ''posted'' or show_reset_to_draft_button or not need_cancel_request" data-hotkey="w"/>
                        <button name="mark_as_sent" string="Mark as Sent" type="object" data-hotkey="v" invisible="state != ''posted'' or is_move_sent or payment_method_code != ''manual''"/>
                        <button name="unmark_as_sent" string="Unmark as Sent" type="object" data-hotkey="k" invisible="state != ''posted'' or not is_move_sent or payment_method_code != ''manual''"/>
                        <field name="state" widget="statusbar" statusbar_visible="draft,posted"/>
                    </header>
                    <div class="alert alert-warning text-center" role="alert" invisible="not is_internal_transfer or not require_partner_bank_account or partner_bank_id">
                        The selected payment method requires a bank account but none is set on
                        <button class="oe_link alert-link" type="object" name="action_open_destination_journal" style="padding: 0; vertical-align: baseline;">the destination journal</button>.
                    </div>
                    <sheet>
                        <!-- Invisible fields -->
                        <field name="id" invisible="1"/>
                        <field name="is_move_sent" invisible="1"/>
                        <field name="need_cancel_request" invisible="1"/>
                        <field name="show_reset_to_draft_button" invisible="1"/>
                        <field name="is_reconciled" invisible="1"/>
                        <field name="is_matched" invisible="1"/>
                        <field name="payment_method_code" invisible="1"/>
                        <field name="show_partner_bank_account" invisible="1"/>
                        <field name="require_partner_bank_account" invisible="1"/>
                        <field name="available_payment_method_line_ids" invisible="1"/>
                        <field name="available_partner_bank_ids" invisible="1"/>
                        <field name="suitable_journal_ids" invisible="1"/>
                        <field name="country_code" invisible="1"/>
                        <field name="partner_type" invisible="1"/>
                        <field name="posted_before" invisible="1"/>
                        <field name="reconciled_invoices_type" invisible="1"/>
                        <field name="company_id" invisible="1"/>
                        <field name="paired_internal_transfer_payment_id" invisible="1"/>
                        <field name="available_journal_ids" invisible="1"/>
                        <field name="currency_id" invisible="1"/>

                        <div class="oe_button_box" name="button_box">
                            <!-- Invoice stat button -->
                            <button name="button_open_invoices" type="object" class="oe_stat_button" icon="fa-bars" invisible="reconciled_invoices_count == 0">
                                <div class="o_form_field o_stat_info">
                                    <span class="o_stat_text">
                                        <field name="reconciled_invoices_count"/>
                                        <span invisible="reconciled_invoices_type != ''invoice''"> Invoice</span>
                                        <span invisible="reconciled_invoices_type == ''invoice''"> Credit Note</span>
                                    </span>
                                </div>
                            </button>

                            <!-- Bill stat button -->
                            <button name="button_open_bills" type="object" class="oe_stat_button" icon="fa-bars" invisible="reconciled_bills_count == 0">
                                <div class="o_form_field o_stat_info">
                                    <span class="o_stat_text">
                                        <field name="reconciled_bills_count"/>
                                        <span> Bill</span>
                                    </span>
                                </div>
                            </button>

                            <!-- Statement stat button -->
                            <button name="button_open_statement_lines" type="object" class="oe_stat_button" icon="fa-bars" invisible="reconciled_statement_lines_count == 0">
                                <div class="o_form_field o_stat_info">
                                    <field name="reconciled_statement_lines_count"/>
                                    <span class="o_stat_text">Transaction</span>
                                </div>
                            </button>

                            <!-- Journal Entry  button -->
                            <button name="button_open_journal_entry" type="object" class="oe_stat_button" icon="fa-bars" groups="account.group_account_user,account.group_account_readonly">
                                <div class="o_stat_info">
                                    <span class="o_stat_text">Journal Entry</span>
                                </div>
                            </button>
                        </div>

                        <widget name="web_ribbon" text="Invoicing App Legacy" bg_color="text-bg-info" invisible="state != ''invoicing_legacy''" tooltip="This payment has been generated through the Invoicing app, before installing Accounting. It has been disabled by the ''Invoicing Switch Threshold Date'' setting so that it does not impact your accounting."/>

                        <div class="oe_title">
                            <h1 invisible="state != ''draft''"><span>Draft</span></h1>
                            <h1 invisible="state == ''draft''"><field name="name" readonly="1"/></h1>
                        </div>

                        <group name="main_group">
                            <group name="group1">
                                <label for="is_internal_transfer"/>
                                <div>
                                    <field name="is_internal_transfer" readonly="state != ''draft''"/>
                                    <span invisible="paired_internal_transfer_payment_id or not is_internal_transfer or state != ''draft''" class="fst-italic">
                                        A second payment will be created in the destination journal.
                                    </span>
                                </div>
                                <field name="payment_type" widget="radio" options="{''horizontal'': True}" readonly="state != ''draft''"/>
                                <field name="partner_id" context="{''default_is_company'': True}" string="Customer" options="{''no_quick_create'': True}" invisible="partner_type != ''customer'' or is_internal_transfer" readonly="state != ''draft''"/>
                                <field name="partner_id" context="{''default_is_company'': True}" string="Vendor" options="{''no_quick_create'': True}" invisible="partner_type != ''supplier'' or is_internal_transfer" readonly="state != ''draft''"/>
                                <label for="amount"/>
                                <div name="amount_div" class="o_row">
                                    <field name="amount" readonly="state != ''draft''"/>
                                    <field name="currency_id" options="{''no_create'': True, ''no_open'': True}" required="1" readonly="state != ''draft''" groups="base.group_multi_currency"/>
                                </div>
                                <field name="date" readonly="state != ''draft''"/>
                                <field name="ref" string="Memo"/>
                            </group>
                            <group name="group2">
                                <field name="journal_id" domain="[(''id'', ''in'', available_journal_ids)]" readonly="state != ''draft''"/>
                                <field name="payment_method_line_id" options="{''no_create'': True, ''no_open'': True}" required="1" readonly="state != ''draft''"/>

                                <field name="partner_bank_id" string="Customer Bank Account" context="{''default_partner_id'': partner_id, ''display_account_trust'': True}" invisible="not show_partner_bank_account or partner_type != ''customer'' or is_internal_transfer or payment_type == ''inbound''" required="require_partner_bank_account and not is_internal_transfer"/>

                                <field name="partner_bank_id" string="Vendor Bank Account" context="{''default_partner_id'': partner_id, ''display_account_trust'': True}" invisible="not show_partner_bank_account or partner_type != ''supplier'' or is_internal_transfer or payment_type == ''inbound''" required="require_partner_bank_account and not is_internal_transfer"/>

                                <!-- This field should always be readonly but using readonly="1" overrides the other partner_bank_id
                                fields readonly condition in the framework, preventing the modification of these fields -->
                                <field name="partner_bank_id" string="Company Bank Account" context="{''default_partner_id'': partner_id, ''display_account_trust'': True}" invisible="not show_partner_bank_account or is_internal_transfer or payment_type == ''outbound''" required="require_partner_bank_account and not is_internal_transfer"/>

                                <field name="destination_journal_id" placeholder="e.g. Cash" context="{''default_partner_id'': partner_id}" invisible="not is_internal_transfer" readonly="state != ''draft''" required="is_internal_transfer and state == ''draft''"/>
                            </group>
                            <group>
                                <field name="qr_code" invisible="1"/>
                                <div invisible="not qr_code" colspan="2" class="text-center">
                                    <field name="qr_code" widget="html"/>
                                </div>
                            </group>
                        </group>
                        <group>
                            <!-- To be used in localizations requiring to add a page -->
                            <notebook name="payment_notebook" colspan="2"/>
                        </group>
                    </sheet>
                    <div class="o_attachment_preview"/>
                    <div class="oe_chatter">
                        <field name="message_follower_ids" groups="base.group_user"/>
                        <field name="activity_ids"/>
                        <field name="message_ids"/>
                    </div>
                </form>
            ', false, true, '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295', false);
INSERT INTO public.ir_ui_view VALUES (647, 16, NULL, 1, 1, 'account.automatic.entry.wizard.form', 'account.automatic.entry.wizard', NULL, 'form', 'account/wizard/account_automatic_entry_wizard_views.xml', 'primary', '{"en_US": "<form>\n                    <field name=\"account_type\" invisible=\"1\"/>\n                    <field name=\"company_id\" invisible=\"1\"/>\n                    <field name=\"move_line_ids\" invisible=\"1\"/>\n                    <field name=\"display_currency_helper\" invisible=\"1\"/>\n                    <field name=\"action\" invisible=\"1\"/>\n                    <div invisible=\"not display_currency_helper\" class=\"alert alert-info text-center\" role=\"status\">\n                        The selected destination account is set to use a specific currency. Every entry transferred to it will be converted into this currency, causing\n                        the loss of any pre-existing foreign currency amount.\n                    </div>\n                    <div invisible=\"not lock_date_message\" class=\"alert alert-warning text-center\" role=\"status\">\n                        <field name=\"lock_date_message\" nolabel=\"1\"/>\n                    </div>\n                    <group>\n                        <group invisible=\"action != ''change_period''\">\n                            <field name=\"date\" string=\"Recognition Date\"/>\n                            <field name=\"expense_accrual_account\" string=\"Accrued Account\" invisible=\"account_type != ''expense''\" required=\"account_type == ''expense'' and action == ''change_period''\"/>\n                            <field name=\"revenue_accrual_account\" string=\"Accrued Account\" invisible=\"account_type != ''income''\" required=\"account_type == ''income'' and action == ''change_period''\"/>\n                        </group>\n                        <group invisible=\"action != ''change_account''\">\n                            <field name=\"date\" string=\"Transfer Date\"/>\n                            <field name=\"destination_account_id\" required=\"action == ''change_account''\" domain=\"[(''company_id'', ''='', company_id)]\"/>\n                        </group>\n                        <group>\n                            <label for=\"total_amount\" string=\"Adjusting Amount\" invisible=\"action != ''change_period''\"/>\n                            <div invisible=\"action != ''change_period''\">\n                                <field name=\"percentage\" style=\"width:40% !important\" readonly=\"action != ''change_period''\"/>%<span class=\"px-3\"/>(<field name=\"total_amount\" class=\"oe_inline\"/>)\n                            </div>\n                            <field name=\"total_amount\" readonly=\"1\" invisible=\"action == ''change_period''\"/>\n                            <field name=\"journal_id\"/>\n                        </group>\n                    </group>\n                    <label for=\"preview_move_data\" string=\"The following Journal Entries will be generated\"/>\n                    <field name=\"preview_move_data\" widget=\"grouped_view_widget\" class=\"d-block\"/>\n                    <footer>\n                        <button string=\"Create Journal Entries\" name=\"do_action\" type=\"object\" class=\"oe_highlight\" data-hotkey=\"q\"/>\n                        <button string=\"Cancel\" class=\"btn btn-secondary\" special=\"cancel\" data-hotkey=\"x\"/>\n                    </footer>\n                </form>"}', '<?xml version="1.0"?>
<form>
                    <field name="account_type" invisible="1"/>
                    <field name="company_id" invisible="1"/>
                    <field name="move_line_ids" invisible="1"/>
                    <field name="display_currency_helper" invisible="1"/>
                    <field name="action" invisible="1"/>
                    <div invisible="not display_currency_helper" class="alert alert-info text-center" role="status">
                        The selected destination account is set to use a specific currency. Every entry transferred to it will be converted into this currency, causing
                        the loss of any pre-existing foreign currency amount.
                    </div>
                    <div invisible="not lock_date_message" class="alert alert-warning text-center" role="status">
                        <field name="lock_date_message" nolabel="1"/>
                    </div>
                    <group>
                        <group invisible="action != ''change_period''">
                            <field name="date" string="Recognition Date"/>
                            <field name="expense_accrual_account" string="Accrued Account" invisible="account_type != ''expense''" required="account_type == ''expense'' and action == ''change_period''"/>
                            <field name="revenue_accrual_account" string="Accrued Account" invisible="account_type != ''income''" required="account_type == ''income'' and action == ''change_period''"/>
                        </group>
                        <group invisible="action != ''change_account''">
                            <field name="date" string="Transfer Date"/>
                            <field name="destination_account_id" required="action == ''change_account''" domain="[(''company_id'', ''='', company_id)]"/>
                        </group>
                        <group>
                            <label for="total_amount" string="Adjusting Amount" invisible="action != ''change_period''"/>
                            <div invisible="action != ''change_period''">
                                <field name="percentage" style="width:40% !important" readonly="action != ''change_period''"/>%<span class="px-3"/>(<field name="total_amount" class="oe_inline"/>)
                            </div>
                            <field name="total_amount" readonly="1" invisible="action == ''change_period''"/>
                            <field name="journal_id"/>
                        </group>
                    </group>
                    <label for="preview_move_data" string="The following Journal Entries will be generated"/>
                    <field name="preview_move_data" widget="grouped_view_widget" class="d-block"/>
                    <footer>
                        <button string="Create Journal Entries" name="do_action" type="object" class="oe_highlight" data-hotkey="q"/>
                        <button string="Cancel" class="btn btn-secondary" special="cancel" data-hotkey="x"/>
                    </footer>
                </form>
            ', false, true, '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295', false);
INSERT INTO public.ir_ui_view VALUES (648, 16, NULL, 1, 1, 'Unreconcile Entries', 'account.unreconcile', NULL, 'form', 'account/wizard/account_unreconcile_view.xml', 'primary', '{"en_US": "<form string=\"Unreconcile\">\n                <separator string=\"Unreconcile Transactions\"/>\n                <form class=\"o_form_label\">If you unreconcile transactions, you must also verify all the actions that are linked to those transactions because they will not be disabled</form>\n                <footer>\n                    <button string=\"Unreconcile\" name=\"trans_unrec\" type=\"object\" default_focus=\"1\" class=\"btn-primary\" data-hotkey=\"q\"/>\n                    <button string=\"Cancel\" class=\"btn-secondary\" special=\"cancel\" data-hotkey=\"x\"/>\n                </footer>\n            </form>"}', '<?xml version="1.0"?>
<form string="Unreconcile">
                <separator string="Unreconcile Transactions"/>
                <form class="o_form_label">If you unreconcile transactions, you must also verify all the actions that are linked to those transactions because they will not be disabled</form>
                <footer>
                    <button string="Unreconcile" name="trans_unrec" type="object" default_focus="1" class="btn-primary" data-hotkey="q"/>
                    <button string="Cancel" class="btn-secondary" special="cancel" data-hotkey="x"/>
                </footer>
            </form>
            ', false, true, '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295', false);
INSERT INTO public.ir_ui_view VALUES (649, 16, NULL, 1, 1, 'account.move.reversal.form', 'account.move.reversal', NULL, 'form', 'account/wizard/account_move_reversal_view.xml', 'primary', '{"en_US": "<form string=\"Reverse Journal Entry\">\n                    <field name=\"residual\" invisible=\"1\"/>\n                    <field name=\"company_id\" invisible=\"1\"/>\n                    <field name=\"move_ids\" invisible=\"1\"/>\n                    <field name=\"move_type\" invisible=\"1\"/>\n                    <field name=\"available_journal_ids\" invisible=\"1\"/>\n                    <group>\n                        <field name=\"reason\" invisible=\"move_type == ''entry''\"/>\n                        <field name=\"journal_id\" domain=\"[(''id'', ''in'', available_journal_ids)]\"/>\n                        <field name=\"date\" widget=\"date\" required=\"1\"/>\n                    </group>\n                    <footer>\n                        <button string=\"Reverse\" name=\"refund_moves\" type=\"object\" class=\"btn-primary\" data-hotkey=\"q\"/>\n                        <button string=\"Reverse and Create Invoice\" name=\"modify_moves\" type=\"object\" class=\"btn-secondary\" invisible=\"move_type  == ''entry''\"/>\n                        <button string=\"Discard\" class=\"btn-secondary\" special=\"cancel\" data-hotkey=\"x\"/>\n                    </footer>\n               </form>"}', '<?xml version="1.0"?>
<form string="Reverse Journal Entry">
                    <field name="residual" invisible="1"/>
                    <field name="company_id" invisible="1"/>
                    <field name="move_ids" invisible="1"/>
                    <field name="move_type" invisible="1"/>
                    <field name="available_journal_ids" invisible="1"/>
                    <group>
                        <field name="reason" invisible="move_type == ''entry''"/>
                        <field name="journal_id" domain="[(''id'', ''in'', available_journal_ids)]"/>
                        <field name="date" widget="date" required="1"/>
                    </group>
                    <footer>
                        <button string="Reverse" name="refund_moves" type="object" class="btn-primary" data-hotkey="q"/>
                        <button string="Reverse and Create Invoice" name="modify_moves" type="object" class="btn-secondary" invisible="move_type  == ''entry''"/>
                        <button string="Discard" class="btn-secondary" special="cancel" data-hotkey="x"/>
                    </footer>
               </form>
            ', false, true, '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295', false);
INSERT INTO public.ir_ui_view VALUES (650, 16, NULL, 1, 1, 'Re-sequence Journal Entries', 'account.resequence.wizard', NULL, 'form', 'account/wizard/account_resequence_views.xml', 'primary', '{"en_US": "<form string=\"Re-Sequence\">\n                <field name=\"move_ids\" invisible=\"1\"/>\n                <field name=\"new_values\" invisible=\"1\"/>\n                <field name=\"sequence_number_reset\" invisible=\"1\"/>\n                <group>\n                    <group>\n                        <field name=\"ordering\" widget=\"radio\"/>\n                    </group>\n                    <group>\n                        <field name=\"first_name\"/>\n                    </group>\n                </group>\n                <group>\n                    <label for=\"preview_moves\" string=\"Preview Modifications\" colspan=\"2\"/>\n                    <field name=\"preview_moves\" widget=\"account_resequence_widget\" nolabel=\"1\" colspan=\"2\"/>\n                </group>\n                <footer>\n                    <button string=\"Confirm\" name=\"resequence\" type=\"object\" default_focus=\"1\" class=\"btn-primary\" data-hotkey=\"q\"/>\n                    <button string=\"Cancel\" class=\"btn-secondary\" special=\"cancel\" data-hotkey=\"x\"/>\n                </footer>\n            </form>"}', '<?xml version="1.0"?>
<form string="Re-Sequence">
                <field name="move_ids" invisible="1"/>
                <field name="new_values" invisible="1"/>
                <field name="sequence_number_reset" invisible="1"/>
                <group>
                    <group>
                        <field name="ordering" widget="radio"/>
                    </group>
                    <group>
                        <field name="first_name"/>
                    </group>
                </group>
                <group>
                    <label for="preview_moves" string="Preview Modifications" colspan="2"/>
                    <field name="preview_moves" widget="account_resequence_widget" nolabel="1" colspan="2"/>
                </group>
                <footer>
                    <button string="Confirm" name="resequence" type="object" default_focus="1" class="btn-primary" data-hotkey="q"/>
                    <button string="Cancel" class="btn-secondary" special="cancel" data-hotkey="x"/>
                </footer>
            </form>
            ', false, true, '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295', false);
INSERT INTO public.ir_ui_view VALUES (651, 16, NULL, 1, 1, 'account.payment.register.form', 'account.payment.register', NULL, 'form', 'account/wizard/account_payment_register_views.xml', 'primary', '{"en_US": "<form string=\"Register Payment\">\n                    <!-- Invisible fields -->\n                    <field name=\"line_ids\" invisible=\"1\"/>\n                    <field name=\"can_edit_wizard\" invisible=\"1\" force_save=\"1\"/>\n                    <field name=\"can_group_payments\" invisible=\"1\" force_save=\"1\"/>\n                    <field name=\"early_payment_discount_mode\" invisible=\"1\" force_save=\"1\"/>\n                    <field name=\"payment_type\" invisible=\"1\" force_save=\"1\"/>\n                    <field name=\"partner_type\" invisible=\"1\" force_save=\"1\"/>\n                    <field name=\"source_amount\" invisible=\"1\" force_save=\"1\"/>\n                    <field name=\"source_amount_currency\" invisible=\"1\" force_save=\"1\"/>\n                    <field name=\"source_currency_id\" invisible=\"1\" force_save=\"1\"/>\n                    <field name=\"company_id\" invisible=\"1\" force_save=\"1\"/>\n                    <field name=\"partner_id\" invisible=\"1\" force_save=\"1\"/>\n                    <field name=\"country_code\" invisible=\"1\" force_save=\"1\"/>\n                    <field name=\"currency_id\" invisible=\"1\"/>\n\n                    <field name=\"show_partner_bank_account\" invisible=\"1\"/>\n                    <field name=\"require_partner_bank_account\" invisible=\"1\"/>\n                    <field name=\"available_journal_ids\" invisible=\"1\"/>\n                    <field name=\"available_payment_method_line_ids\" invisible=\"1\"/>\n                    <field name=\"available_partner_bank_ids\" invisible=\"1\"/>\n                    <field name=\"company_currency_id\" invisible=\"1\"/>\n                    <field name=\"hide_writeoff_section\" invisible=\"1\"/>\n                    <field name=\"writeoff_is_exchange_account\" invisible=\"1\"/>\n                    <field name=\"untrusted_bank_ids\" invisible=\"1\"/>\n\n                    <div role=\"alert\" class=\"alert alert-info\" invisible=\"not hide_writeoff_section\">\n                        <p class=\"m-0\"><b>Early Payment Discount of <field name=\"payment_difference\"/> has been applied.</b></p>\n                    </div>\n                    <div role=\"alert\" class=\"alert alert-warning\" invisible=\"untrusted_payments_count == 0\">\n                        <span class=\"fw-bold\"><field name=\"untrusted_payments_count\" class=\"oe_inline\"/> out of <field name=\"total_payments_amount\" class=\"oe_inline\"/> payments will be skipped due to <button class=\"oe_link p-0 align-baseline\" type=\"object\" name=\"action_open_untrusted_bank_accounts\">untrusted bank accounts</button>.</span>\n                    </div>\n                    <group>\n                        <group name=\"group1\">\n                            <field name=\"journal_id\" options=\"{''no_open'': True, ''no_create'': True}\" required=\"1\"/>\n                            <field name=\"payment_method_line_id\" required=\"1\" options=\"{''no_create'': True, ''no_open'': True}\"/>\n                            <field name=\"partner_bank_id\" invisible=\"not show_partner_bank_account or not can_edit_wizard or (can_group_payments and not group_payment)\" readonly=\"payment_type == ''inbound''\" required=\"require_partner_bank_account and can_edit_wizard and (not can_group_payments or not group_payment)\" context=\"{''display_account_trust'': True}\"/>\n                            <field name=\"group_payment\" invisible=\"not can_group_payments\"/>\n                        </group>\n                        <group name=\"group2\">\n                            <label for=\"amount\" invisible=\"not can_edit_wizard or can_group_payments and not group_payment\"/>\n                            <div name=\"amount_div\" class=\"o_row\" invisible=\"not can_edit_wizard or can_group_payments and not group_payment\">\n                                <field name=\"amount\"/>\n                                <field name=\"currency_id\" required=\"1\" options=\"{''no_create'': True, ''no_open'': True}\" groups=\"base.group_multi_currency\"/>\n                            </div>\n                            <field name=\"payment_date\"/>\n                            <field name=\"communication\" invisible=\"not can_edit_wizard or (can_group_payments and not group_payment)\"/>\n                        </group>\n                        <group name=\"group3\" invisible=\"payment_difference == 0.0 or early_payment_discount_mode or not can_edit_wizard or can_group_payments and not group_payment\">\n                            <label for=\"payment_difference\"/>\n                            <div>\n                                <field name=\"payment_difference\"/>\n                                <field name=\"payment_difference_handling\" widget=\"radio\" nolabel=\"1\"/>\n                                <div invisible=\"hide_writeoff_section or payment_difference_handling == ''open''\">\n                                    <label for=\"writeoff_account_id\" string=\"Post Difference In\" class=\"oe_edit_only\"/>\n                                    <field name=\"writeoff_account_id\" string=\"Post Difference In\" options=\"{''no_create'': True}\" required=\"payment_difference_handling == ''reconcile'' and not early_payment_discount_mode\"/>\n                                    <label for=\"writeoff_label\" class=\"oe_edit_only\" string=\"Label\" invisible=\"writeoff_is_exchange_account\"/>\n                                    <field name=\"writeoff_label\" required=\"payment_difference_handling == ''reconcile''\" invisible=\"writeoff_is_exchange_account\"/>\n                                </div>\n                            </div>\n                        </group>\n                        <field name=\"qr_code\" invisible=\"1\"/>\n                        <div invisible=\"not qr_code\" colspan=\"2\" class=\"text-center\">\n                            <field name=\"qr_code\"/>\n                        </div>\n                    </group>\n                    <footer>\n                        <button string=\"Create Payments\" name=\"action_create_payments\" type=\"object\" class=\"oe_highlight\" data-hotkey=\"q\" invisible=\"total_payments_amount == 1\"/>\n                        <button string=\"Create Payment\" name=\"action_create_payments\" type=\"object\" class=\"oe_highlight\" data-hotkey=\"q\" invisible=\"total_payments_amount != 1\"/>\n                        <button string=\"Discard\" class=\"btn btn-secondary\" special=\"cancel\" data-hotkey=\"x\"/>\n                    </footer>\n                </form>"}', '<?xml version="1.0"?>
<form string="Register Payment">
                    <!-- Invisible fields -->
                    <field name="line_ids" invisible="1"/>
                    <field name="can_edit_wizard" invisible="1" force_save="1"/>
                    <field name="can_group_payments" invisible="1" force_save="1"/>
                    <field name="early_payment_discount_mode" invisible="1" force_save="1"/>
                    <field name="payment_type" invisible="1" force_save="1"/>
                    <field name="partner_type" invisible="1" force_save="1"/>
                    <field name="source_amount" invisible="1" force_save="1"/>
                    <field name="source_amount_currency" invisible="1" force_save="1"/>
                    <field name="source_currency_id" invisible="1" force_save="1"/>
                    <field name="company_id" invisible="1" force_save="1"/>
                    <field name="partner_id" invisible="1" force_save="1"/>
                    <field name="country_code" invisible="1" force_save="1"/>
                    <field name="currency_id" invisible="1"/>

                    <field name="show_partner_bank_account" invisible="1"/>
                    <field name="require_partner_bank_account" invisible="1"/>
                    <field name="available_journal_ids" invisible="1"/>
                    <field name="available_payment_method_line_ids" invisible="1"/>
                    <field name="available_partner_bank_ids" invisible="1"/>
                    <field name="company_currency_id" invisible="1"/>
                    <field name="hide_writeoff_section" invisible="1"/>
                    <field name="writeoff_is_exchange_account" invisible="1"/>
                    <field name="untrusted_bank_ids" invisible="1"/>

                    <div role="alert" class="alert alert-info" invisible="not hide_writeoff_section">
                        <p class="m-0"><b>Early Payment Discount of <field name="payment_difference"/> has been applied.</b></p>
                    </div>
                    <div role="alert" class="alert alert-warning" invisible="untrusted_payments_count == 0">
                        <span class="fw-bold"><field name="untrusted_payments_count" class="oe_inline"/> out of <field name="total_payments_amount" class="oe_inline"/> payments will be skipped due to <button class="oe_link p-0 align-baseline" type="object" name="action_open_untrusted_bank_accounts">untrusted bank accounts</button>.</span>
                    </div>
                    <group>
                        <group name="group1">
                            <field name="journal_id" options="{''no_open'': True, ''no_create'': True}" required="1"/>
                            <field name="payment_method_line_id" required="1" options="{''no_create'': True, ''no_open'': True}"/>
                            <field name="partner_bank_id" invisible="not show_partner_bank_account or not can_edit_wizard or (can_group_payments and not group_payment)" readonly="payment_type == ''inbound''" required="require_partner_bank_account and can_edit_wizard and (not can_group_payments or not group_payment)" context="{''display_account_trust'': True}"/>
                            <field name="group_payment" invisible="not can_group_payments"/>
                        </group>
                        <group name="group2">
                            <label for="amount" invisible="not can_edit_wizard or can_group_payments and not group_payment"/>
                            <div name="amount_div" class="o_row" invisible="not can_edit_wizard or can_group_payments and not group_payment">
                                <field name="amount"/>
                                <field name="currency_id" required="1" options="{''no_create'': True, ''no_open'': True}" groups="base.group_multi_currency"/>
                            </div>
                            <field name="payment_date"/>
                            <field name="communication" invisible="not can_edit_wizard or (can_group_payments and not group_payment)"/>
                        </group>
                        <group name="group3" invisible="payment_difference == 0.0 or early_payment_discount_mode or not can_edit_wizard or can_group_payments and not group_payment">
                            <label for="payment_difference"/>
                            <div>
                                <field name="payment_difference"/>
                                <field name="payment_difference_handling" widget="radio" nolabel="1"/>
                                <div invisible="hide_writeoff_section or payment_difference_handling == ''open''">
                                    <label for="writeoff_account_id" string="Post Difference In" class="oe_edit_only"/>
                                    <field name="writeoff_account_id" string="Post Difference In" options="{''no_create'': True}" required="payment_difference_handling == ''reconcile'' and not early_payment_discount_mode"/>
                                    <label for="writeoff_label" class="oe_edit_only" string="Label" invisible="writeoff_is_exchange_account"/>
                                    <field name="writeoff_label" required="payment_difference_handling == ''reconcile''" invisible="writeoff_is_exchange_account"/>
                                </div>
                            </div>
                        </group>
                        <field name="qr_code" invisible="1"/>
                        <div invisible="not qr_code" colspan="2" class="text-center">
                            <field name="qr_code"/>
                        </div>
                    </group>
                    <footer>
                        <button string="Create Payments" name="action_create_payments" type="object" class="oe_highlight" data-hotkey="q" invisible="total_payments_amount == 1"/>
                        <button string="Create Payment" name="action_create_payments" type="object" class="oe_highlight" data-hotkey="q" invisible="total_payments_amount != 1"/>
                        <button string="Discard" class="btn btn-secondary" special="cancel" data-hotkey="x"/>
                    </footer>
                </form>
            ', false, true, '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295', false);
INSERT INTO public.ir_ui_view VALUES (652, 2, NULL, 1, 1, 'account.move.line.form', 'account.move.line', NULL, 'form', 'account/views/account_move_views.xml', 'primary', '{"en_US": "<form string=\"Journal Item\" create=\"false\">\n                    <sheet>\n                        <field name=\"company_id\" invisible=\"1\"/>\n                        <field name=\"parent_state\" invisible=\"1\"/>\n                        <group>\n                            <field name=\"name\"/>\n                            <field name=\"partner_id\" domain=\"[''|'', (''parent_id'', ''='', False), (''is_company'', ''='', True)]\" readonly=\"1\"/>\n                        </group>\n                        <notebook colspan=\"4\">\n                            <page string=\"Information\" name=\"information\">\n                                <group>\n                                    <group string=\"Amount\">\n                                        <field name=\"account_id\" options=\"{''no_create'': True}\" domain=\"[(''company_id'', ''parent_of'', company_id), (''deprecated'', ''='', False)]\" readonly=\"1\"/>\n                                        <field name=\"debit\" readonly=\"1\"/>\n                                        <field name=\"credit\" readonly=\"1\"/>\n                                        <field name=\"balance\" readonly=\"1\"/>\n                                        <field name=\"quantity\" readonly=\"1\"/>\n                                    </group>\n                                    <group string=\"Dates\">\n                                        <field name=\"date\" groups=\"account.group_account_readonly\"/>\n                                        <field name=\"date_maturity\"/>\n                                    </group>\n\n                                    <group string=\"Taxes\" invisible=\"not tax_line_id and not tax_ids\">\n                                        <field name=\"tax_line_id\" readonly=\"1\" invisible=\"not tax_line_id\"/>\n                                        <field name=\"tax_ids\" widget=\"many2many_tags\" readonly=\"1\" invisible=\"not tax_ids\"/>\n                                        <field name=\"tax_tag_invert\" readonly=\"1\" groups=\"base.group_no_one\"/>\n                                    </group>\n                                    <group string=\"Matching\" invisible=\"not matched_debit_ids and not matched_credit_ids\">\n                                        <label for=\"full_reconcile_id\"/>\n                                        <div>\n                                            <field name=\"full_reconcile_id\" invisible=\"not full_reconcile_id\"/>\n                                            <field name=\"matched_debit_ids\" invisible=\"1\"/>\n                                            <field name=\"matched_credit_ids\" invisible=\"1\"/>\n                                            <button name=\"open_reconcile_view\" class=\"oe_link\" type=\"object\" string=\"-&gt; View partially reconciled entries\" invisible=\"full_reconcile_id or not matched_debit_ids and not matched_credit_ids\">\n                                            </button>\n                                        </div>\n                                    </group>\n                                    <group string=\"Currency\" groups=\"base.group_multi_currency\">\n                                        <field name=\"currency_id\" invisible=\"1\"/>\n                                        <field name=\"display_type\" invisible=\"1\"/>\n                                        <field name=\"amount_currency\" readonly=\"display_type != ''tax'' or parent_state != ''draft''\"/>\n                                    </group>\n                                    <group string=\"Product\" invisible=\"not product_id\">\n                                        <field name=\"product_id\" readonly=\"1\"/>\n                                    </group>\n                                    <group string=\"States\">\n                                        <field name=\"blocked\"/>\n                                    </group>\n                                    <group string=\"Analytic\" groups=\"analytic.group_analytic_accounting\">\n                                        <field name=\"analytic_distribution\" widget=\"analytic_distribution\" groups=\"analytic.group_analytic_accounting\" readonly=\"1\"/>\n                                    </group>\n                                </group>\n                            </page>\n                            <page string=\"Analytic Lines\" name=\"analytic_lines\" groups=\"analytic.group_analytic_accounting\">\n                                <field name=\"date\" invisible=\"1\"/>\n                                <field name=\"analytic_line_ids\" context=\"{''tree_view_ref'':''analytic.view_account_analytic_line_tree'', ''default_general_account_id'':account_id, ''default_name'': name, ''default_date'':date, ''amount'': (debit or 0.0)-(credit or 0.0)}\"/>\n                            </page>\n                            <page string=\"Accounting documents\" name=\"page_accounting_documents\">\n                                <label for=\"move_id\" string=\"Journal Entry\"/>\n                                <field name=\"move_id\" readonly=\"1\" nolabel=\"1\"/>\n                                <group readonly=\"1\" invisible=\"not statement_line_id\">\n                                    <label for=\"statement_line_id\" string=\"Originator Statement Line\"/>\n                                    <field name=\"statement_line_id\"/>\n                                </group>\n                            </page>\n                        </notebook>\n                    </sheet>\n                </form>"}', '<?xml version="1.0"?>
<form string="Journal Item" create="false">
                    <sheet>
                        <field name="company_id" invisible="1"/>
                        <field name="parent_state" invisible="1"/>
                        <group>
                            <field name="name"/>
                            <field name="partner_id" domain="[''|'', (''parent_id'', ''='', False), (''is_company'', ''='', True)]" readonly="1"/>
                        </group>
                        <notebook colspan="4">
                            <page string="Information" name="information">
                                <group>
                                    <group string="Amount">
                                        <field name="account_id" options="{''no_create'': True}" domain="[(''company_id'', ''parent_of'', company_id), (''deprecated'', ''='', False)]" readonly="1"/>
                                        <field name="debit" readonly="1"/>
                                        <field name="credit" readonly="1"/>
                                        <field name="balance" readonly="1"/>
                                        <field name="quantity" readonly="1"/>
                                    </group>
                                    <group string="Dates">
                                        <field name="date" groups="account.group_account_readonly"/>
                                        <field name="date_maturity"/>
                                    </group>

                                    <group string="Taxes" invisible="not tax_line_id and not tax_ids">
                                        <field name="tax_line_id" readonly="1" invisible="not tax_line_id"/>
                                        <field name="tax_ids" widget="many2many_tags" readonly="1" invisible="not tax_ids"/>
                                        <field name="tax_tag_invert" readonly="1" groups="base.group_no_one"/>
                                    </group>
                                    <group string="Matching" invisible="not matched_debit_ids and not matched_credit_ids">
                                        <label for="full_reconcile_id"/>
                                        <div>
                                            <field name="full_reconcile_id" invisible="not full_reconcile_id"/>
                                            <field name="matched_debit_ids" invisible="1"/>
                                            <field name="matched_credit_ids" invisible="1"/>
                                            <button name="open_reconcile_view" class="oe_link" type="object" string="-&gt; View partially reconciled entries" invisible="full_reconcile_id or not matched_debit_ids and not matched_credit_ids">
                                            </button>
                                        </div>
                                    </group>
                                    <group string="Currency" groups="base.group_multi_currency">
                                        <field name="currency_id" invisible="1"/>
                                        <field name="display_type" invisible="1"/>
                                        <field name="amount_currency" readonly="display_type != ''tax'' or parent_state != ''draft''"/>
                                    </group>
                                    <group string="Product" invisible="not product_id">
                                        <field name="product_id" readonly="1"/>
                                    </group>
                                    <group string="States">
                                        <field name="blocked"/>
                                    </group>
                                    <group string="Analytic" groups="analytic.group_analytic_accounting">
                                        <field name="analytic_distribution" widget="analytic_distribution" groups="analytic.group_analytic_accounting" readonly="1"/>
                                    </group>
                                </group>
                            </page>
                            <page string="Analytic Lines" name="analytic_lines" groups="analytic.group_analytic_accounting">
                                <field name="date" invisible="1"/>
                                <field name="analytic_line_ids" context="{''tree_view_ref'':''analytic.view_account_analytic_line_tree'', ''default_general_account_id'':account_id, ''default_name'': name, ''default_date'':date, ''amount'': (debit or 0.0)-(credit or 0.0)}"/>
                            </page>
                            <page string="Accounting documents" name="page_accounting_documents">
                                <label for="move_id" string="Journal Entry"/>
                                <field name="move_id" readonly="1" nolabel="1"/>
                                <group readonly="1" invisible="not statement_line_id">
                                    <label for="statement_line_id" string="Originator Statement Line"/>
                                    <field name="statement_line_id"/>
                                </group>
                            </page>
                        </notebook>
                    </sheet>
                </form>
            ', false, true, '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295', false);
INSERT INTO public.ir_ui_view VALUES (653, 16, NULL, 1, 1, 'account.move.line.kanban', 'account.move.line', NULL, 'kanban', 'account/views/account_move_views.xml', 'primary', '{"en_US": "<kanban class=\"o_kanban_mobile\" create=\"false\" group_create=\"false\">\n                    <field name=\"company_currency_id\"/>\n                    <field name=\"partner_id\"/>\n                    <templates>\n                        <t t-name=\"kanban-box\">\n                            <div class=\"oe_kanban_global_click\">\n                                <div class=\"row mb4\">\n                                    <div class=\"col-8\">\n                                        <field name=\"account_id\"/>\n                                    </div>\n                                    <strong t-if=\"record.date_maturity.raw_value\" class=\"col-4 ps-0 text-end\">\n                                        <i class=\"fa fa-clock-o\" aria-label=\"Date\" role=\"img\" title=\"Date\"/> <field name=\"date_maturity\"/>\n                                    </strong>\n                                </div>\n                                <div class=\"row mb4\" style=\"min-height: 60px;\">\n                                    <em class=\"col-10\">\n                                        <field name=\"name\"/>\n                                    </em>\n                                    <div class=\"col-2 text-end\">\n                                        <img t-att-src=\"kanban_image(''res.partner'', ''avatar_128'', record.partner_id.raw_value)\" t-att-title=\"record.partner_id.value\" t-att-alt=\"record.partner_id.value\" class=\"oe_kanban_avatar o_avatar rounded\"/>\n                                    </div>\n                                </div>\n                                <div class=\"row\">\n                                    <div class=\"col-6\">\n                                        <field name=\"tax_ids\" widget=\"many2many_tags\"/>\n                                    </div>\n                                    <div class=\"col-6 text-end\">\n                                        <t t-if=\"record.debit.raw_value &gt; 0\">\n                                            <field name=\"debit\"/><span> (DR)</span>\n                                        </t>\n                                        <t t-if=\"record.credit.raw_value &gt; 0\">\n                                            <field name=\"credit\"/><span> (CR)</span>\n                                        </t>\n                                    </div>\n                                </div>\n                            </div>\n                        </t>\n                    </templates>\n                </kanban>"}', '<?xml version="1.0"?>
<kanban class="o_kanban_mobile" create="false" group_create="false">
                    <field name="company_currency_id"/>
                    <field name="partner_id"/>
                    <templates>
                        <t t-name="kanban-box">
                            <div class="oe_kanban_global_click">
                                <div class="row mb4">
                                    <div class="col-8">
                                        <field name="account_id"/>
                                    </div>
                                    <strong t-if="record.date_maturity.raw_value" class="col-4 ps-0 text-end">
                                        <i class="fa fa-clock-o" aria-label="Date" role="img" title="Date"/> <field name="date_maturity"/>
                                    </strong>
                                </div>
                                <div class="row mb4" style="min-height: 60px;">
                                    <em class="col-10">
                                        <field name="name"/>
                                    </em>
                                    <div class="col-2 text-end">
                                        <img t-att-src="kanban_image(''res.partner'', ''avatar_128'', record.partner_id.raw_value)" t-att-title="record.partner_id.value" t-att-alt="record.partner_id.value" class="oe_kanban_avatar o_avatar rounded"/>
                                    </div>
                                </div>
                                <div class="row">
                                    <div class="col-6">
                                        <field name="tax_ids" widget="many2many_tags"/>
                                    </div>
                                    <div class="col-6 text-end">
                                        <t t-if="record.debit.raw_value &gt; 0">
                                            <field name="debit"/><span> (DR)</span>
                                        </t>
                                        <t t-if="record.credit.raw_value &gt; 0">
                                            <field name="credit"/><span> (CR)</span>
                                        </t>
                                    </div>
                                </div>
                            </div>
                        </t>
                    </templates>
                </kanban>
            ', false, true, '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295', false);
