INSERT INTO public.ir_ui_view VALUES (656, 100, NULL, 1, 1, 'account.move.line.tree', 'account.move.line', NULL, 'tree', 'account/views/account_move_views.xml', 'primary', '{"en_US": "<tree string=\"Journal Items\" create=\"false\" edit=\"true\" expand=\"context.get(''expand'', False)\" multi_edit=\"1\" sample=\"1\">\n                    <field name=\"move_id\" column_invisible=\"True\"/>\n                    <field name=\"invoice_date\" string=\"Invoice Date\" optional=\"hide\"/>\n                    <field name=\"date\" readonly=\"1\"/>\n                    <field name=\"company_id\" column_invisible=\"True\"/>\n                    <field name=\"company_id\" groups=\"base.group_multi_company\" readonly=\"1\" optional=\"hide\"/>\n                    <field name=\"journal_id\" readonly=\"1\" options=\"{&quot;no_open&quot;:True}\" optional=\"hide\"/>\n                    <field name=\"move_name\" string=\"Journal Entry\" widget=\"open_move_widget\"/>\n                    <field name=\"account_id\" options=\"{''no_open'': True, ''no_create'': True}\" domain=\"[(''company_id'', ''parent_of'', company_id), (''deprecated'', ''='', False)]\" groups=\"account.group_account_readonly\"/>\n                    <field name=\"partner_id\" optional=\"show\" readonly=\"move_type != ''entry''\"/>\n                    <field name=\"ref\" optional=\"hide\" readonly=\"False\"/>\n                    <field name=\"product_id\" readonly=\"1\" optional=\"hide\"/>\n                    <field name=\"name\" optional=\"show\"/>\n                    <field name=\"tax_ids\" widget=\"many2many_tags\" optional=\"hide\" readonly=\"1\"/>\n                    <field name=\"amount_currency\" groups=\"base.group_multi_currency\" optional=\"show\" readonly=\"1\" invisible=\"is_same_currency\"/>\n                    <field name=\"currency_id\" groups=\"base.group_multi_currency\" optional=\"hide\" string=\"Currency\" readonly=\"1\" invisible=\"is_same_currency\"/>\n                    <field name=\"debit\" sum=\"Total Debit\" readonly=\"1\"/>\n                    <field name=\"credit\" sum=\"Total Credit\" readonly=\"1\"/>\n                    <field name=\"tax_tag_ids\" string=\"Tax Grids\" options=\"{''no_create'': True, ''no_create_edit'': True}\" domain=\"[(''applicability'', ''='', ''taxes'')]\" widget=\"many2many_tags\" optional=\"hide\"/>\n                    <field name=\"discount_date\" string=\"Discount Date\" optional=\"hide\"/>\n                    <field name=\"discount_amount_currency\" string=\"Discount Amount\" optional=\"hide\"/>\n                    <field name=\"tax_line_id\" string=\"Originator Tax\" optional=\"hide\" readonly=\"1\"/>\n                    <field name=\"date_maturity\" readonly=\"1\" optional=\"hide\"/>\n                    <field name=\"balance\" sum=\"Total Balance\" optional=\"hide\" readonly=\"1\"/>\n                    <field name=\"matching_number\" readonly=\"1\" optional=\"show\"/>\n                    <field name=\"amount_residual\" sum=\"Total Residual\" string=\"Residual\" optional=\"hide\" readonly=\"1\" invisible=\"not is_account_reconcile\"/>\n                    <field name=\"amount_residual_currency\" sum=\"Total Residual in Currency\" string=\"Residual in Currency\" optional=\"hide\" readonly=\"1\" invisible=\"is_same_currency or not is_account_reconcile\"/>\n                    <field name=\"analytic_distribution\" widget=\"analytic_distribution\" groups=\"analytic.group_analytic_accounting\" optional=\"show\" options=\"{''product_field'': ''product_id'', ''account_field'': ''account_id'', ''force_applicability'': ''optional''}\"/>\n\n                    <field name=\"move_type\" column_invisible=\"True\"/>\n                    <field name=\"parent_state\" column_invisible=\"True\"/>\n                    <field name=\"account_type\" column_invisible=\"True\"/>\n                    <field name=\"statement_line_id\" column_invisible=\"True\"/>\n                    <field name=\"company_currency_id\" column_invisible=\"True\"/>\n                    <field name=\"is_same_currency\" column_invisible=\"True\"/>\n                    <field name=\"is_account_reconcile\" column_invisible=\"True\"/>\n                    <field name=\"sequence\" column_invisible=\"True\"/>\n                    <groupby name=\"partner_id\">\n                        <button name=\"edit\" type=\"edit\" icon=\"fa-edit\" title=\"Edit\"/>\n                    </groupby>\n                </tree>"}', '<?xml version="1.0"?>
<tree string="Journal Items" create="false" edit="true" expand="context.get(''expand'', False)" multi_edit="1" sample="1">
                    <field name="move_id" column_invisible="True"/>
                    <field name="invoice_date" string="Invoice Date" optional="hide"/>
                    <field name="date" readonly="1"/>
                    <field name="company_id" column_invisible="True"/>
                    <field name="company_id" groups="base.group_multi_company" readonly="1" optional="hide"/>
                    <field name="journal_id" readonly="1" options="{&quot;no_open&quot;:True}" optional="hide"/>
                    <field name="move_name" string="Journal Entry" widget="open_move_widget"/>
                    <field name="account_id" options="{''no_open'': True, ''no_create'': True}" domain="[(''company_id'', ''parent_of'', company_id), (''deprecated'', ''='', False)]" groups="account.group_account_readonly"/>
                    <field name="partner_id" optional="show" readonly="move_type != ''entry''"/>
                    <field name="ref" optional="hide" readonly="False"/>
                    <field name="product_id" readonly="1" optional="hide"/>
                    <field name="name" optional="show"/>
                    <field name="tax_ids" widget="many2many_tags" optional="hide" readonly="1"/>
                    <field name="amount_currency" groups="base.group_multi_currency" optional="show" readonly="1" invisible="is_same_currency"/>
                    <field name="currency_id" groups="base.group_multi_currency" optional="hide" string="Currency" readonly="1" invisible="is_same_currency"/>
                    <field name="debit" sum="Total Debit" readonly="1"/>
                    <field name="credit" sum="Total Credit" readonly="1"/>
                    <field name="tax_tag_ids" string="Tax Grids" options="{''no_create'': True, ''no_create_edit'': True}" domain="[(''applicability'', ''='', ''taxes'')]" widget="many2many_tags" optional="hide"/>
                    <field name="discount_date" string="Discount Date" optional="hide"/>
                    <field name="discount_amount_currency" string="Discount Amount" optional="hide"/>
                    <field name="tax_line_id" string="Originator Tax" optional="hide" readonly="1"/>
                    <field name="date_maturity" readonly="1" optional="hide"/>
                    <field name="balance" sum="Total Balance" optional="hide" readonly="1"/>
                    <field name="matching_number" readonly="1" optional="show"/>
                    <field name="amount_residual" sum="Total Residual" string="Residual" optional="hide" readonly="1" invisible="not is_account_reconcile"/>
                    <field name="amount_residual_currency" sum="Total Residual in Currency" string="Residual in Currency" optional="hide" readonly="1" invisible="is_same_currency or not is_account_reconcile"/>
                    <field name="analytic_distribution" widget="analytic_distribution" groups="analytic.group_analytic_accounting" optional="show" options="{''product_field'': ''product_id'', ''account_field'': ''account_id'', ''force_applicability'': ''optional''}"/>

                    <field name="move_type" column_invisible="True"/>
                    <field name="parent_state" column_invisible="True"/>
                    <field name="account_type" column_invisible="True"/>
                    <field name="statement_line_id" column_invisible="True"/>
                    <field name="company_currency_id" column_invisible="True"/>
                    <field name="is_same_currency" column_invisible="True"/>
                    <field name="is_account_reconcile" column_invisible="True"/>
                    <field name="sequence" column_invisible="True"/>
                    <groupby name="partner_id">
                        <button name="edit" type="edit" icon="fa-edit" title="Edit"/>
                    </groupby>
                </tree>
            ', false, true, '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295', false);
