INSERT INTO public.ir_ui_view VALUES (662, 16, 656, 1, 1, 'account.move.line.tax.audit.tree', 'account.move.line', NULL, 'tree', 'account/views/account_move_views.xml', 'primary', '{"en_US": "<data><field name=\"matching_number\" position=\"replace\">\n                    <field name=\"tax_line_id\" string=\"Tax\"/>\n                    <field name=\"tax_base_amount\" sum=\"Total Base Amount\"/>\n                </field>\n                <field name=\"analytic_distribution\" position=\"attributes\">\n                    <attribute name=\"optional\">hide</attribute>\n                </field>\n                <field name=\"debit\" position=\"attributes\">\n                    <attribute name=\"optional\">show</attribute>\n                </field>\n                <field name=\"credit\" position=\"attributes\">\n                    <attribute name=\"optional\">show</attribute>\n                </field>\n                <field name=\"journal_id\" position=\"attributes\">\n                    <attribute name=\"optional\">show</attribute>\n                </field>\n            </data>"}', '<?xml version="1.0"?>
