INSERT INTO public.ir_ui_view VALUES (665, 200, NULL, 1, 1, 'account.move.line.payment.tree', 'account.move.line', NULL, 'tree', 'account/views/account_move_views.xml', 'primary', '{"en_US": "<tree string=\"Payment Items\" create=\"false\" edit=\"true\" expand=\"context.get(''expand'', False)\" multi_edit=\"1\" sample=\"1\" js_class=\"account_search_bar\" default_order=\"payment_date asc, id asc\">\n                    <header>\n                        <button name=\"action_register_payment\" type=\"object\" string=\"Register Payment\"/>\n                    </header>\n                    <field name=\"move_id\" column_invisible=\"True\"/>\n                    <field name=\"invoice_date\" string=\"Invoice Date\"/>\n                    <field name=\"date\" readonly=\"1\" optional=\"hide\"/>\n                    <field name=\"date_maturity\" string=\"Invoice Due Date\" readonly=\"1\" optional=\"hide\"/>\n                    <field name=\"discount_date\" string=\"Discount Date\" optional=\"hide\"/>\n                    <field name=\"payment_date\" string=\"Due Date\" readonly=\"1\"/>\n                    <field name=\"company_id\" column_invisible=\"True\"/>\n                    <field name=\"company_id\" groups=\"base.group_multi_company\" readonly=\"1\" optional=\"hide\"/>\n                    <field name=\"journal_id\" readonly=\"1\" options=\"{&quot;no_open&quot;:True}\" optional=\"hide\"/>\n                    <field name=\"move_name\" string=\"Journal Entry\" widget=\"open_move_widget\"/>\n                    <field name=\"partner_id\" optional=\"show\" readonly=\"move_type != ''entry''\"/>\n                    <field name=\"ref\" readonly=\"False\"/>\n                    <field name=\"name\" optional=\"show\"/>\n                    <field name=\"discount_amount_currency\" string=\"Discount Amount\" optional=\"show\" invisible=\"not discount_amount_currency\"/>\n                    <field name=\"amount_residual\" sum=\"Total Residual\" string=\"Residual\" readonly=\"1\" invisible=\"not is_account_reconcile\"/>\n                    <field name=\"amount_residual_currency\" string=\"Residual in Currency\" optional=\"hide\" readonly=\"1\" invisible=\"is_same_currency or not is_account_reconcile\"/>\n                    <field name=\"currency_id\" groups=\"base.group_multi_currency\" optional=\"hide\" string=\"Currency\" readonly=\"1\" invisible=\"is_same_currency\"/>\n                    <field name=\"company_currency_id\" column_invisible=\"True\"/>\n                    <field name=\"move_type\" column_invisible=\"True\"/>\n                    <field name=\"is_same_currency\" column_invisible=\"True\"/>\n                    <field name=\"is_account_reconcile\" column_invisible=\"True\"/>\n                    <field name=\"currency_id\" groups=\"!base.group_multi_currency\" column_invisible=\"True\"/>\n                    <groupby name=\"partner_id\">\n                        <button name=\"edit\" type=\"edit\" icon=\"fa-edit\" title=\"Edit\"/>\n                    </groupby>\n                </tree>"}', '<?xml version="1.0"?>
<tree string="Payment Items" create="false" edit="true" expand="context.get(''expand'', False)" multi_edit="1" sample="1" js_class="account_search_bar" default_order="payment_date asc, id asc">
                    <header>
                        <button name="action_register_payment" type="object" string="Register Payment"/>
                    </header>
                    <field name="move_id" column_invisible="True"/>
                    <field name="invoice_date" string="Invoice Date"/>
                    <field name="date" readonly="1" optional="hide"/>
                    <field name="date_maturity" string="Invoice Due Date" readonly="1" optional="hide"/>
                    <field name="discount_date" string="Discount Date" optional="hide"/>
                    <field name="payment_date" string="Due Date" readonly="1"/>
                    <field name="company_id" column_invisible="True"/>
                    <field name="company_id" groups="base.group_multi_company" readonly="1" optional="hide"/>
                    <field name="journal_id" readonly="1" options="{&quot;no_open&quot;:True}" optional="hide"/>
                    <field name="move_name" string="Journal Entry" widget="open_move_widget"/>
                    <field name="partner_id" optional="show" readonly="move_type != ''entry''"/>
                    <field name="ref" readonly="False"/>
                    <field name="name" optional="show"/>
                    <field name="discount_amount_currency" string="Discount Amount" optional="show" invisible="not discount_amount_currency"/>
                    <field name="amount_residual" sum="Total Residual" string="Residual" readonly="1" invisible="not is_account_reconcile"/>
                    <field name="amount_residual_currency" string="Residual in Currency" optional="hide" readonly="1" invisible="is_same_currency or not is_account_reconcile"/>
                    <field name="currency_id" groups="base.group_multi_currency" optional="hide" string="Currency" readonly="1" invisible="is_same_currency"/>
                    <field name="company_currency_id" column_invisible="True"/>
                    <field name="move_type" column_invisible="True"/>
                    <field name="is_same_currency" column_invisible="True"/>
                    <field name="is_account_reconcile" column_invisible="True"/>
                    <field name="currency_id" groups="!base.group_multi_currency" column_invisible="True"/>
                    <groupby name="partner_id">
                        <button name="edit" type="edit" icon="fa-edit" title="Edit"/>
                    </groupby>
                </tree>
            ', false, true, '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295', false);
