INSERT INTO public.ir_ui_view VALUES (667, 16, NULL, 1, 1, 'account.move.tree', 'account.move', NULL, 'tree', 'account/views/account_move_views.xml', 'primary', '{"en_US": "<tree string=\"Journal Entries\" sample=\"1\" decoration-info=\"state == ''draft''\" expand=\"context.get(''expand'', False)\">\n                    <field name=\"company_currency_id\" column_invisible=\"True\"/>\n                    <field name=\"made_sequence_hole\" column_invisible=\"True\"/>\n                    <field name=\"invoice_date\" string=\"Invoice Date\" optional=\"hide\" readonly=\"state != ''draft''\"/>\n                    <field name=\"date\" readonly=\"state in [''cancel'', ''posted'']\"/>\n                    <field name=\"name\" decoration-danger=\"made_sequence_hole\"/>\n                    <field name=\"partner_id\" optional=\"show\" readonly=\"state != ''draft''\"/>\n                    <field name=\"ref\" optional=\"show\"/>\n                    <field name=\"journal_id\"/>\n                    <field name=\"company_id\" groups=\"base.group_multi_company\" optional=\"show\"/>\n                    <field name=\"amount_total_signed\" sum=\"Total Amount\" string=\"Total\" decoration-bf=\"1\"/>\n                    <field name=\"state\" widget=\"badge\" decoration-info=\"state == ''draft''\" decoration-success=\"state == ''posted''\"/>\n                    <field name=\"currency_id\" column_invisible=\"True\" readonly=\"state in [''cancel'', ''posted'']\"/>\n                    <field name=\"to_check\" optional=\"hide\" widget=\"boolean_toggle\"/>\n                    <field name=\"activity_ids\" widget=\"list_activity\" optional=\"hide\"/>\n                </tree>"}', '<?xml version="1.0"?>
<tree string="Journal Entries" sample="1" decoration-info="state == ''draft''" expand="context.get(''expand'', False)">
                    <field name="company_currency_id" column_invisible="True"/>
                    <field name="made_sequence_hole" column_invisible="True"/>
                    <field name="invoice_date" string="Invoice Date" optional="hide" readonly="state != ''draft''"/>
                    <field name="date" readonly="state in [''cancel'', ''posted'']"/>
                    <field name="name" decoration-danger="made_sequence_hole"/>
                    <field name="partner_id" optional="show" readonly="state != ''draft''"/>
                    <field name="ref" optional="show"/>
                    <field name="journal_id"/>
                    <field name="company_id" groups="base.group_multi_company" optional="show"/>
                    <field name="amount_total_signed" sum="Total Amount" string="Total" decoration-bf="1"/>
                    <field name="state" widget="badge" decoration-info="state == ''draft''" decoration-success="state == ''posted''"/>
                    <field name="currency_id" column_invisible="True" readonly="state in [''cancel'', ''posted'']"/>
                    <field name="to_check" optional="hide" widget="boolean_toggle"/>
                    <field name="activity_ids" widget="list_activity" optional="hide"/>
                </tree>
            ', false, true, '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295', false);
INSERT INTO public.ir_ui_view VALUES (668, 16, NULL, 1, 1, 'account.invoice.tree', 'account.move', NULL, 'tree', 'account/views/account_move_views.xml', 'primary', '{"en_US": "<tree string=\"Invoices\" js_class=\"account_tree\" decoration-info=\"state == ''draft''\" decoration-muted=\"state == ''cancel''\" expand=\"context.get(''expand'', False)\" sample=\"1\">\n                    <header>\n                        <button name=\"action_register_payment\" type=\"object\" string=\"Register Payment\" groups=\"account.group_account_user\" invisible=\"context.get(''default_move_type'') not in (''out_invoice'', ''out_refund'', ''out_receipt'', ''in_invoice'', ''in_refund'',''in_receipt'')\"/>\n                    </header>\n                    <field name=\"made_sequence_hole\" column_invisible=\"True\"/>\n                    <field name=\"name\" decoration-bf=\"1\" decoration-danger=\"made_sequence_hole\"/>\n                    <field name=\"invoice_partner_display_name\" column_invisible=\"context.get(''default_move_type'') not in (''in_invoice'', ''in_refund'', ''in_receipt'')\" groups=\"base.group_user\" string=\"Vendor\"/>\n                    <field name=\"invoice_partner_display_name\" column_invisible=\"context.get(''default_move_type'') not in (''out_invoice'', ''out_refund'', ''out_receipt'')\" groups=\"base.group_user\" string=\"Customer\"/>\n                    <field name=\"invoice_date\" optional=\"show\" column_invisible=\"context.get(''default_move_type'') not in (''in_invoice'', ''in_refund'', ''in_receipt'')\" readonly=\"state != ''draft''\" string=\"Bill Date\"/>\n                    <field name=\"invoice_date\" optional=\"show\" column_invisible=\"context.get(''default_move_type'') not in (''out_invoice'', ''out_refund'', ''out_receipt'')\" readonly=\"state != ''draft''\" string=\"Invoice Date\"/>\n                    <field name=\"date\" optional=\"hide\" string=\"Accounting Date\" readonly=\"state in [''cancel'', ''posted'']\"/>\n                    <field name=\"invoice_date_due\" widget=\"remaining_days\" optional=\"show\" invisible=\"payment_state in (''paid'', ''in_payment'', ''reversed'') or state == ''cancel''\"/>\n                    <field name=\"invoice_origin\" optional=\"hide\" string=\"Source Document\"/>\n                    <field name=\"payment_reference\" optional=\"hide\" column_invisible=\"context.get(''default_move_type'') in (''out_invoice'', ''out_refund'', ''out_receipt'')\"/>\n                    <field name=\"ref\" optional=\"hide\"/>\n                    <field name=\"invoice_user_id\" optional=\"hide\" column_invisible=\"context.get(''default_move_type'') not in (''out_invoice'', ''out_refund'', ''out_receipt'')\" string=\"Salesperson\" widget=\"many2one_avatar_user\"/>\n                    <field name=\"activity_ids\" widget=\"list_activity\" optional=\"show\"/>\n                    <field name=\"company_id\" groups=\"base.group_multi_company\" options=\"{''no_create'': True}\" optional=\"hide\"/>\n                    <field name=\"company_id\" groups=\"!base.group_multi_company\" column_invisible=\"True\"/>\n                    <field name=\"amount_untaxed_signed\" string=\"Tax Excluded\" sum=\"Total\" optional=\"show\"/>\n                    <field name=\"amount_tax_signed\" string=\"Tax\" sum=\"Total\" optional=\"hide\"/>\n                    <field name=\"amount_total_signed\" string=\"Total\" sum=\"Total\" decoration-bf=\"1\" optional=\"show\"/>\n                    <field name=\"amount_total_in_currency_signed\" string=\"Total in Currency\" optional=\"show\" groups=\"base.group_multi_currency\"/>\n                    <field name=\"amount_total_in_currency_signed\" string=\"Total in Currency\" optional=\"hide\" groups=\"!base.group_multi_currency\"/>\n                    <field name=\"amount_residual_signed\" string=\"Amount Due\" sum=\"Amount Due\" optional=\"hide\"/>\n                    <field name=\"currency_id\" optional=\"hide\" readonly=\"state in [''cancel'', ''posted'']\"/>\n                    <field name=\"company_currency_id\" column_invisible=\"True\"/>\n                    <field name=\"to_check\" optional=\"hide\" widget=\"boolean_toggle\"/>\n                    <field name=\"payment_state\" string=\"Payment\" widget=\"badge\" decoration-danger=\"payment_state == ''not_paid''\" decoration-warning=\"payment_state in (''partial'', ''in_payment'')\" decoration-success=\"payment_state in (''paid'', ''reversed'')\" invisible=\"payment_state == ''invoicing_legacy'' or state != ''posted'' or move_type == ''entry''\" optional=\"show\"/>\n                    <field name=\"state\" widget=\"badge\" decoration-success=\"state == ''posted''\" decoration-info=\"state == ''draft''\" optional=\"show\"/>\n                    <field name=\"move_type\" column_invisible=\"context.get(''default_move_type'', True)\"/>\n                  </tree>"}', '<?xml version="1.0"?>
<tree string="Invoices" js_class="account_tree" decoration-info="state == ''draft''" decoration-muted="state == ''cancel''" expand="context.get(''expand'', False)" sample="1">
                    <header>
                        <button name="action_register_payment" type="object" string="Register Payment" groups="account.group_account_user" invisible="context.get(''default_move_type'') not in (''out_invoice'', ''out_refund'', ''out_receipt'', ''in_invoice'', ''in_refund'',''in_receipt'')"/>
                    </header>
                    <field name="made_sequence_hole" column_invisible="True"/>
                    <field name="name" decoration-bf="1" decoration-danger="made_sequence_hole"/>
                    <field name="invoice_partner_display_name" column_invisible="context.get(''default_move_type'') not in (''in_invoice'', ''in_refund'', ''in_receipt'')" groups="base.group_user" string="Vendor"/>
                    <field name="invoice_partner_display_name" column_invisible="context.get(''default_move_type'') not in (''out_invoice'', ''out_refund'', ''out_receipt'')" groups="base.group_user" string="Customer"/>
                    <field name="invoice_date" optional="show" column_invisible="context.get(''default_move_type'') not in (''in_invoice'', ''in_refund'', ''in_receipt'')" readonly="state != ''draft''" string="Bill Date"/>
                    <field name="invoice_date" optional="show" column_invisible="context.get(''default_move_type'') not in (''out_invoice'', ''out_refund'', ''out_receipt'')" readonly="state != ''draft''" string="Invoice Date"/>
                    <field name="date" optional="hide" string="Accounting Date" readonly="state in [''cancel'', ''posted'']"/>
                    <field name="invoice_date_due" widget="remaining_days" optional="show" invisible="payment_state in (''paid'', ''in_payment'', ''reversed'') or state == ''cancel''"/>
                    <field name="invoice_origin" optional="hide" string="Source Document"/>
                    <field name="payment_reference" optional="hide" column_invisible="context.get(''default_move_type'') in (''out_invoice'', ''out_refund'', ''out_receipt'')"/>
                    <field name="ref" optional="hide"/>
                    <field name="invoice_user_id" optional="hide" column_invisible="context.get(''default_move_type'') not in (''out_invoice'', ''out_refund'', ''out_receipt'')" string="Salesperson" widget="many2one_avatar_user"/>
                    <field name="activity_ids" widget="list_activity" optional="show"/>
                    <field name="company_id" groups="base.group_multi_company" options="{''no_create'': True}" optional="hide"/>
                    <field name="company_id" groups="!base.group_multi_company" column_invisible="True"/>
                    <field name="amount_untaxed_signed" string="Tax Excluded" sum="Total" optional="show"/>
                    <field name="amount_tax_signed" string="Tax" sum="Total" optional="hide"/>
                    <field name="amount_total_signed" string="Total" sum="Total" decoration-bf="1" optional="show"/>
                    <field name="amount_total_in_currency_signed" string="Total in Currency" optional="show" groups="base.group_multi_currency"/>
                    <field name="amount_total_in_currency_signed" string="Total in Currency" optional="hide" groups="!base.group_multi_currency"/>
                    <field name="amount_residual_signed" string="Amount Due" sum="Amount Due" optional="hide"/>
                    <field name="currency_id" optional="hide" readonly="state in [''cancel'', ''posted'']"/>
                    <field name="company_currency_id" column_invisible="True"/>
                    <field name="to_check" optional="hide" widget="boolean_toggle"/>
                    <field name="payment_state" string="Payment" widget="badge" decoration-danger="payment_state == ''not_paid''" decoration-warning="payment_state in (''partial'', ''in_payment'')" decoration-success="payment_state in (''paid'', ''reversed'')" invisible="payment_state == ''invoicing_legacy'' or state != ''posted'' or move_type == ''entry''" optional="show"/>
                    <field name="state" widget="badge" decoration-success="state == ''posted''" decoration-info="state == ''draft''" optional="show"/>
                    <field name="move_type" column_invisible="context.get(''default_move_type'', True)"/>
                  </tree>
            ', false, true, '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295', false);
