INSERT INTO public.ir_ui_view VALUES (680, 16, NULL, 1, 1, 'account.financial.year.op.setup.wizard.form', 'account.financial.year.op', NULL, 'form', 'account/wizard/setup_wizards_view.xml', 'primary', '{"en_US": "<form>\n                    <sheet>\n                        <group>\n                            <group string=\"Fiscal Years\">\n                                <field name=\"opening_move_posted\" invisible=\"1\"/>\n                                <field name=\"opening_date\" readonly=\"opening_move_posted\"/>\n\n                                <label for=\"fiscalyear_last_month\" string=\"Fiscal Year End\"/>\n                                <div>\n                                    <field name=\"fiscalyear_last_day\" class=\"text-center me-2\" style=\"width: 20% !important;\"/>\n                                    <field name=\"fiscalyear_last_month\" class=\"w-75\"/>\n                                </div>\n                            </group>\n                        </group>\n                    </sheet>\n                    <footer>\n                        <button name=\"action_save_onboarding_fiscal_year\" string=\"Apply\" class=\"oe_highlight\" type=\"object\" data-hotkey=\"q\"/>\n                        <button special=\"cancel\" data-hotkey=\"x\" string=\"Cancel\"/>\n                    </footer>\n                </form>"}', '<?xml version="1.0"?>
<form>
                    <sheet>
                        <group>
                            <group string="Fiscal Years">
