                                    <div class="col-8">
                                        <strong><field name="name"/></strong>
                                    </div>
                                    <div class="col-4 text-end">
                                        <span class="badge rounded-pill"><t t-out="record.code.value"/></span>
                                    </div>
                                </div>
                                <div>
                                    <strong>Type: </strong><t t-out="record.account_type.value"/>
                                </div>
                            </div>
                        </t>
                    </templates>
                </kanban>
            ', false, true, '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295', false);
INSERT INTO public.ir_ui_view VALUES (686, 16, NULL, 1, 1, 'account.account.search', 'account.account', NULL, 'search', 'account/views/account_account_views.xml', 'primary', '{"en_US": "<search string=\"Accounts\">\n                    <field name=\"name\" filter_domain=\"[''|'', (''name'', ''ilike'', self), (''code'', ''=ilike'', self + ''%'')]\" string=\"Account\"/>\n                    <filter string=\"Receivable\" name=\"receivableacc\" domain=\"[(''account_type'',''='',''asset_receivable'')]\"/>\n                    <filter string=\"Payable\" name=\"payableacc\" domain=\"[(''account_type'',''='',''liability_payable'')]\"/>\n                    <filter string=\"Equity\" name=\"equityacc\" domain=\"[(''internal_group'',''='', ''equity'')]\"/>\n                    <filter string=\"Assets\" name=\"assetsacc\" domain=\"[(''internal_group'',''='', ''asset'')]\"/>\n                    <filter string=\"Liability\" name=\"liabilityacc\" domain=\"[(''internal_group'',''='', ''liability'')]\"/>\n                    <filter string=\"Income\" name=\"incomeacc\" domain=\"[(''internal_group'',''='', ''income'')]\"/>\n                    <filter string=\"Expenses\" name=\"expensesacc\" domain=\"[(''internal_group'',''='', ''expense'')]\"/>\n                    <separator/>\n                    <filter string=\"Account with Entries\" name=\"used\" domain=\"[(''used'', ''='', True)]\"/>\n                    <filter string=\"Active Account\" name=\"activeacc\" domain=\"[(''deprecated'', ''='', False)]\"/>\n                    <separator/>\n                    <field name=\"account_type\"/>\n                    <group expand=\"0\" string=\"Group By\">\n                        <filter string=\"Account Type\" name=\"accounttype\" domain=\"\" context=\"{''group_by'':''account_type''}\"/>\n                    </group>\n                    <searchpanel class=\"account_root w-auto\">\n                        <field name=\"root_id\" icon=\"fa-filter\" limit=\"0\"/>\n                    </searchpanel>\n                </search>"}', '<?xml version="1.0"?>
<search string="Accounts">
                    <field name="name" filter_domain="[''|'', (''name'', ''ilike'', self), (''code'', ''=ilike'', self + ''%'')]" string="Account"/>
                    <filter string="Receivable" name="receivableacc" domain="[(''account_type'',''='',''asset_receivable'')]"/>
                    <filter string="Payable" name="payableacc" domain="[(''account_type'',''='',''liability_payable'')]"/>
                    <filter string="Equity" name="equityacc" domain="[(''internal_group'',''='', ''equity'')]"/>
                    <filter string="Assets" name="assetsacc" domain="[(''internal_group'',''='', ''asset'')]"/>
                    <filter string="Liability" name="liabilityacc" domain="[(''internal_group'',''='', ''liability'')]"/>
                    <filter string="Income" name="incomeacc" domain="[(''internal_group'',''='', ''income'')]"/>
                    <filter string="Expenses" name="expensesacc" domain="[(''internal_group'',''='', ''expense'')]"/>
                    <separator/>
                    <filter string="Account with Entries" name="used" domain="[(''used'', ''='', True)]"/>
                    <filter string="Active Account" name="activeacc" domain="[(''deprecated'', ''='', False)]"/>
                    <separator/>
                    <field name="account_type"/>
                    <group expand="0" string="Group By">
                        <filter string="Account Type" name="accounttype" domain="" context="{''group_by'':''account_type''}"/>
                    </group>
                    <searchpanel class="account_root w-auto">
                        <field name="root_id" icon="fa-filter" limit="0"/>
                    </searchpanel>
                </search>
            ', false, true, '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295', false);
