INSERT INTO public.ir_ui_view VALUES (691, 1, NULL, 1, 1, 'account.journal.form', 'account.journal', NULL, 'form', 'account/views/account_journal_views.xml', 'primary', '{"en_US": "<form string=\"Account Journal\">\n                    <field name=\"company_id\" invisible=\"1\"/>\n                    <field name=\"bank_statements_source\" invisible=\"1\"/>\n                    <sheet>\n                        <div name=\"button_box\" class=\"oe_button_box\">\n                            <button class=\"oe_stat_button\" type=\"action\" name=\"243\" icon=\"fa-book\" context=\"{''search_default_journal_id'':id}\">\n                                    <div class=\"o_stat_info\">\n                                        <span class=\"o_stat_text\">Journal Entries</span>\n                                    </div>\n                            </button>\n                        </div>\n                        <widget name=\"web_ribbon\" title=\"Archived\" bg_color=\"text-bg-danger\" invisible=\"active\"/>\n                        <div class=\"oe_title\">\n                            <label for=\"name\"/>\n                            <h1><field name=\"name\" placeholder=\"e.g. Customer Invoices\"/></h1>\n                        </div>\n                        <group>\n                            <group>\n                                <field name=\"active\" invisible=\"1\"/>\n                                <field name=\"type\"/>\n                            </group>\n                            <group>\n                                <field name=\"company_id\" options=\"{''no_create'': True}\" groups=\"base.group_multi_company\"/>\n                                <field name=\"country_code\" invisible=\"1\"/>\n                            </group>\n                        </group>\n                        <notebook>\n                            <page name=\"bank_account\" string=\"Journal Entries\">\n                                <group>\n                                    <group string=\"Accounting Information\">\n                                        <field name=\"default_account_type\" invisible=\"1\"/>\n                                        <label for=\"default_account_id\" string=\"Bank Account\" invisible=\"type != ''bank''\" groups=\"account.group_account_readonly\"/>\n                                        <label for=\"default_account_id\" string=\"Cash Account\" invisible=\"type != ''cash''\" groups=\"account.group_account_readonly\"/>\n                                        <label for=\"default_account_id\" string=\"Default Income Account\" invisible=\"type != ''sale''\" groups=\"account.group_account_readonly\"/>\n                                        <label for=\"default_account_id\" string=\"Default Expense Account\" invisible=\"type != ''purchase''\" groups=\"account.group_account_readonly\"/>\n                                        <label for=\"default_account_id\" string=\"Default Account\" help=\"If set, this account is used to automatically balance entries.\" invisible=\"type != ''general''\" groups=\"account.group_account_readonly\"/>\n                                        <field name=\"default_account_id\" nolabel=\"1\" invisible=\"not type\" required=\"(id and type in (''bank'', ''cash'')) or type in (''sale'', ''purchase'')\" options=\"{''no_quick_create'': True}\" groups=\"account.group_account_readonly\"/>\n                                        <field name=\"suspense_account_id\" invisible=\"type not in (''bank'', ''cash'')\" required=\"type in (''bank'', ''cash'')\" options=\"{''no_quick_create'': True}\" groups=\"account.group_account_readonly\"/>\n                                        <field name=\"profit_account_id\" invisible=\"type not in (''cash'', ''bank'')\"/>\n                                        <field name=\"loss_account_id\" invisible=\"type not in (''cash'', ''bank'')\"/>\n                                        <field name=\"refund_sequence\" invisible=\"type not in [''sale'', ''purchase'']\"/>\n                                        <field name=\"payment_sequence\" invisible=\"type not in (''bank'', ''cash'')\"/>\n                                        <field name=\"code\" placeholder=\"e.g. INV\"/>\n                                        <field name=\"currency_id\" options=\"{''no_create'': True}\" groups=\"base.group_multi_currency\"/>\n                                    </group>\n                                    <group name=\"bank_account_number\" string=\"Bank Account Number\" invisible=\"type != ''bank''\">\n                                        <field name=\"company_partner_id\" invisible=\"1\"/>\n                                        <field name=\"bank_account_id\" string=\"Account Number\" context=\"{''default_partner_id'': company_partner_id}\"/>\n                                        <field name=\"bank_id\" invisible=\"not bank_account_id\"/>\n                                        <field name=\"bank_statements_source\" widget=\"radio\" required=\"type == ''bank''\" groups=\"account.group_account_readonly\"/>\n                                    </group>\n                                </group>\n                            </page>\n                            <page id=\"inbound_payment_settings\" string=\"Incoming Payments\" name=\"page_incoming_payments\" invisible=\"type not in [''cash'', ''bank'']\">\n                                <field name=\"available_payment_method_ids\" invisible=\"1\"/>\n                                <field name=\"inbound_payment_method_line_ids\" nolabel=\"1\" context=\"{''default_payment_type'': ''inbound''}\">\n                                    <tree string=\"Payment Methods\" editable=\"bottom\">\n                                        <field name=\"available_payment_method_ids\" column_invisible=\"True\"/>\n                                        <field name=\"payment_type\" column_invisible=\"True\"/>\n                                        <field name=\"company_id\" column_invisible=\"True\"/>\n                                        <field name=\"sequence\" widget=\"handle\"/>\n                                        <field name=\"payment_method_id\" options=\"{''no_create'': True, ''no_open'': True}\"/>\n                                        <field name=\"name\"/>\n                                        <field name=\"payment_account_id\" placeholder=\"Leave empty to use the default outstanding account\" string=\"Outstanding Receipts accounts\" optional=\"hide\" options=\"{''no_quick_create'': True}\" groups=\"account.group_account_readonly\"/>\n                                    </tree>\n                                </field>\n                            </page>\n                            <page id=\"outbound_payment_settings\" string=\"Outgoing Payments\" name=\"page_outgoing_payments\" invisible=\"type not in [''cash'', ''bank'']\">\n                                    <field name=\"outbound_payment_method_line_ids\" nolabel=\"1\" context=\"{''default_payment_type'': ''outbound''}\">\n                                        <tree string=\"Payment Methods\" editable=\"bottom\" nolabel=\"1\">\n                                            <field name=\"available_payment_method_ids\" column_invisible=\"True\"/>\n                                            <field name=\"payment_type\" column_invisible=\"True\"/>\n                                            <field name=\"company_id\" column_invisible=\"True\"/>\n                                            <field name=\"sequence\" widget=\"handle\"/>\n                                            <field name=\"payment_method_id\" options=\"{''no_create'': True, ''no_open'': True}\"/>\n                                            <field name=\"name\"/>\n                                            <field name=\"payment_account_id\" placeholder=\"Leave empty to use the default outstanding account\" string=\"Outstanding Payments accounts\" optional=\"hide\" options=\"{''no_quick_create'': True}\" groups=\"account.group_account_readonly\"/>\n                                        </tree>\n                                    </field>\n                                    <field name=\"selected_payment_method_codes\" invisible=\"1\"/>\n                                    <group name=\"outgoing_payment\"/>\n                            </page>\n                            <page name=\"advanced_settings\" string=\"Advanced Settings\">\n                                <group>\n                                    <group string=\"Control-Access\" groups=\"account.group_account_manager\">\n                                        <div class=\"text-muted\" colspan=\"2\">Keep empty for no control</div>\n                                        <field name=\"account_control_ids\" widget=\"many2many_tags\" options=\"{''no_create_edit'': True}\"/>\n                                        <field name=\"restrict_mode_hash_table\" groups=\"account.group_account_readonly\" invisible=\"type in [''bank'', ''cash'']\"/>\n                                    </group>\n                                    <!-- email alias -->\n                                    <group class=\"oe_read_only\" name=\"group_alias_ro\" string=\"Create Invoices upon Emails\" invisible=\"type not in (''sale'', ''purchase'')\">\n                                       <field name=\"alias_id\"/>\n                                    </group>\n                                    <field name=\"display_alias_fields\" invisible=\"1\"/>\n                                    <group name=\"group_alias_no_domain\" string=\"Create Invoices upon Emails\" invisible=\"type not in (''sale'', ''purchase'') or display_alias_fields\">\n                                        <div class=\"content-group\" colspan=\"2\">\n                                            <a type=\"action\" name=\"220\" class=\"btn btn-link\" role=\"button\">\n                                                <i class=\"oi oi-fw o_button_icon oi-arrow-right\"/> Choose or Configure Email Servers\n                                            </a>\n                                        </div>\n                                    </group>\n                                    <group class=\"oe_edit_only\" name=\"group_alias_edit\" string=\"Create Invoices upon Emails\" invisible=\"type not in (''sale'', ''purchase'') or not display_alias_fields\">\n                                        <label string=\"Email Alias\" for=\"alias_name\"/>\n                                        <div class=\"oe_inline\" name=\"edit_alias\" style=\"display: inline;\" dir=\"ltr\">\n                                            <field name=\"alias_name\" class=\"oe_inline\"/>@\n                                            <field name=\"alias_domain_id\" class=\"oe_inline\" placeholder=\"e.g. domain.com\" options=\"{''no_create'': True, ''no_open'': True}\"/>\n                                        </div>\n                                    </group>\n                                    <!-- edi -->\n                                    <group name=\"group_edi_config\" string=\"Electronic Data Interchange\" invisible=\"1\"/>\n                                    <!-- email alias end -->\n                                    <group string=\"Payment Communications\" invisible=\"type != ''sale''\">\n                                        <field name=\"invoice_reference_type\"/>\n                                        <field name=\"invoice_reference_model\" invisible=\"invoice_reference_type == ''none''\"/>\n                                    </group>\n                                    <group string=\"Follow Customer Payments\" invisible=\"type != ''sale''\">\n                                        <field name=\"sale_activity_type_id\" options=\"{''no_quick_create'': True}\"/>\n                                        <field name=\"sale_activity_user_id\" invisible=\"not sale_activity_type_id\" options=\"{''no_quick_create'': True}\"/>\n                                        <field name=\"sale_activity_note\" placeholder=\"e.g. Give a phone call, check with others , ...\" invisible=\"not sale_activity_type_id\"/>\n                                    </group>\n                                </group>\n                            </page>\n                        </notebook>\n                    </sheet>\n                <div class=\"oe_chatter\">\n                    <field name=\"message_follower_ids\"/>\n                    <field name=\"activity_ids\"/>\n                    <field name=\"message_ids\"/>\n                </div>\n                </form>"}', '<?xml version="1.0"?>
<form string="Account Journal">
                    <field name="company_id" invisible="1"/>
                    <field name="bank_statements_source" invisible="1"/>
                    <sheet>
                        <div name="button_box" class="oe_button_box">
                            <button class="oe_stat_button" type="action" name="243" icon="fa-book" context="{''search_default_journal_id'':id}">
                                    <div class="o_stat_info">
                                        <span class="o_stat_text">Journal Entries</span>
                                    </div>
                            </button>
                        </div>
                        <widget name="web_ribbon" title="Archived" bg_color="text-bg-danger" invisible="active"/>
                        <div class="oe_title">
                            <label for="name"/>
                            <h1><field name="name" placeholder="e.g. Customer Invoices"/></h1>
                        </div>
                        <group>
                            <group>
                                <field name="active" invisible="1"/>
                                <field name="type"/>
                            </group>
                            <group>
                                <field name="company_id" options="{''no_create'': True}" groups="base.group_multi_company"/>
                                <field name="country_code" invisible="1"/>
                            </group>
                        </group>
                        <notebook>
                            <page name="bank_account" string="Journal Entries">
                                <group>
                                    <group string="Accounting Information">
                                        <field name="default_account_type" invisible="1"/>
                                        <label for="default_account_id" string="Bank Account" invisible="type != ''bank''" groups="account.group_account_readonly"/>
                                        <label for="default_account_id" string="Cash Account" invisible="type != ''cash''" groups="account.group_account_readonly"/>
                                        <label for="default_account_id" string="Default Income Account" invisible="type != ''sale''" groups="account.group_account_readonly"/>
                                        <label for="default_account_id" string="Default Expense Account" invisible="type != ''purchase''" groups="account.group_account_readonly"/>
                                        <label for="default_account_id" string="Default Account" help="If set, this account is used to automatically balance entries." invisible="type != ''general''" groups="account.group_account_readonly"/>
                                        <field name="default_account_id" nolabel="1" invisible="not type" required="(id and type in (''bank'', ''cash'')) or type in (''sale'', ''purchase'')" options="{''no_quick_create'': True}" groups="account.group_account_readonly"/>
                                        <field name="suspense_account_id" invisible="type not in (''bank'', ''cash'')" required="type in (''bank'', ''cash'')" options="{''no_quick_create'': True}" groups="account.group_account_readonly"/>
                                        <field name="profit_account_id" invisible="type not in (''cash'', ''bank'')"/>
                                        <field name="loss_account_id" invisible="type not in (''cash'', ''bank'')"/>
                                        <field name="refund_sequence" invisible="type not in [''sale'', ''purchase'']"/>
                                        <field name="payment_sequence" invisible="type not in (''bank'', ''cash'')"/>
                                        <field name="code" placeholder="e.g. INV"/>
                                        <field name="currency_id" options="{''no_create'': True}" groups="base.group_multi_currency"/>
                                    </group>
                                    <group name="bank_account_number" string="Bank Account Number" invisible="type != ''bank''">
                                        <field name="company_partner_id" invisible="1"/>
                                        <field name="bank_account_id" string="Account Number" context="{''default_partner_id'': company_partner_id}"/>
                                        <field name="bank_id" invisible="not bank_account_id"/>
                                        <field name="bank_statements_source" widget="radio" required="type == ''bank''" groups="account.group_account_readonly"/>
                                    </group>
                                </group>
                            </page>
                            <page id="inbound_payment_settings" string="Incoming Payments" name="page_incoming_payments" invisible="type not in [''cash'', ''bank'']">
                                <field name="available_payment_method_ids" invisible="1"/>
                                <field name="inbound_payment_method_line_ids" nolabel="1" context="{''default_payment_type'': ''inbound''}">
                                    <tree string="Payment Methods" editable="bottom">
                                        <field name="available_payment_method_ids" column_invisible="True"/>
                                        <field name="payment_type" column_invisible="True"/>
                                        <field name="company_id" column_invisible="True"/>
                                        <field name="sequence" widget="handle"/>
                                        <field name="payment_method_id" options="{''no_create'': True, ''no_open'': True}"/>
                                        <field name="name"/>
                                        <field name="payment_account_id" placeholder="Leave empty to use the default outstanding account" string="Outstanding Receipts accounts" optional="hide" options="{''no_quick_create'': True}" groups="account.group_account_readonly"/>
                                    </tree>
                                </field>
                            </page>
                            <page id="outbound_payment_settings" string="Outgoing Payments" name="page_outgoing_payments" invisible="type not in [''cash'', ''bank'']">
                                    <field name="outbound_payment_method_line_ids" nolabel="1" context="{''default_payment_type'': ''outbound''}">
                                        <tree string="Payment Methods" editable="bottom" nolabel="1">
                                            <field name="available_payment_method_ids" column_invisible="True"/>
                                            <field name="payment_type" column_invisible="True"/>
                                            <field name="company_id" column_invisible="True"/>
                                            <field name="sequence" widget="handle"/>
                                            <field name="payment_method_id" options="{''no_create'': True, ''no_open'': True}"/>
                                            <field name="name"/>
                                            <field name="payment_account_id" placeholder="Leave empty to use the default outstanding account" string="Outstanding Payments accounts" optional="hide" options="{''no_quick_create'': True}" groups="account.group_account_readonly"/>
                                        </tree>
                                    </field>
                                    <field name="selected_payment_method_codes" invisible="1"/>
                                    <group name="outgoing_payment"/>
                            </page>
                            <page name="advanced_settings" string="Advanced Settings">
                                <group>
                                    <group string="Control-Access" groups="account.group_account_manager">
                                        <div class="text-muted" colspan="2">Keep empty for no control</div>
                                        <field name="account_control_ids" widget="many2many_tags" options="{''no_create_edit'': True}"/>
                                        <field name="restrict_mode_hash_table" groups="account.group_account_readonly" invisible="type in [''bank'', ''cash'']"/>
                                    </group>
                                    <!-- email alias -->
                                    <group class="oe_read_only" name="group_alias_ro" string="Create Invoices upon Emails" invisible="type not in (''sale'', ''purchase'')">
                                       <field name="alias_id"/>
                                    </group>
                                    <field name="display_alias_fields" invisible="1"/>
                                    <group name="group_alias_no_domain" string="Create Invoices upon Emails" invisible="type not in (''sale'', ''purchase'') or display_alias_fields">
                                        <div class="content-group" colspan="2">
                                            <a type="action" name="220" class="btn btn-link" role="button">
                                                <i class="oi oi-fw o_button_icon oi-arrow-right"/> Choose or Configure Email Servers
                                            </a>
                                        </div>
                                    </group>
                                    <group class="oe_edit_only" name="group_alias_edit" string="Create Invoices upon Emails" invisible="type not in (''sale'', ''purchase'') or not display_alias_fields">
                                        <label string="Email Alias" for="alias_name"/>
                                        <div class="oe_inline" name="edit_alias" style="display: inline;" dir="ltr">
                                            <field name="alias_name" class="oe_inline"/>@
                                            <field name="alias_domain_id" class="oe_inline" placeholder="e.g. domain.com" options="{''no_create'': True, ''no_open'': True}"/>
                                        </div>
                                    </group>
                                    <!-- edi -->
                                    <group name="group_edi_config" string="Electronic Data Interchange" invisible="1"/>
                                    <!-- email alias end -->
                                    <group string="Payment Communications" invisible="type != ''sale''">
                                        <field name="invoice_reference_type"/>
                                        <field name="invoice_reference_model" invisible="invoice_reference_type == ''none''"/>
                                    </group>
                                    <group string="Follow Customer Payments" invisible="type != ''sale''">
                                        <field name="sale_activity_type_id" options="{''no_quick_create'': True}"/>
                                        <field name="sale_activity_user_id" invisible="not sale_activity_type_id" options="{''no_quick_create'': True}"/>
                                        <field name="sale_activity_note" placeholder="e.g. Give a phone call, check with others , ..." invisible="not sale_activity_type_id"/>
                                    </group>
                                </group>
                            </page>
                        </notebook>
                    </sheet>
                <div class="oe_chatter">
                    <field name="message_follower_ids"/>
                    <field name="activity_ids"/>
                    <field name="message_ids"/>
                </div>
                </form>
            ', false, true, '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295', false);
INSERT INTO public.ir_ui_view VALUES (692, 1, NULL, 1, 1, 'account.journal.kanban', 'account.journal', NULL, 'kanban', 'account/views/account_journal_views.xml', 'primary', '{"en_US": "<kanban class=\"o_kanban_mobile\">\n                    <templates>\n                        <t t-name=\"kanban-box\">\n                            <div t-attf-class=\"oe_kanban_content oe_kanban_global_click\">\n                                <div class=\"row\">\n                                    <div class=\"col-6\">\n                                        <strong><field name=\"name\"/></strong>\n                                    </div>\n                                    <div class=\"col-6\">\n                                        <span class=\"float-end\"><field name=\"type\"/></span>\n                                    </div>\n                                </div>\n                            </div>\n                        </t>\n                    </templates>\n                </kanban>"}', '<?xml version="1.0"?>
