INSERT INTO public.ir_ui_view VALUES (693, 1, NULL, 1, 1, 'account.journal.search', 'account.journal', NULL, 'search', 'account/views/account_journal_views.xml', 'primary', '{"en_US": "<search string=\"Search Account Journal\">\n                    <field name=\"name\" string=\"Journal\" filter_domain=\"[''|'', (''name'', ''ilike'', self), (''code'', ''ilike'', self)]\"/>\n                    <filter name=\"dashboard\" string=\"Favorites\" domain=\"[(''show_on_dashboard'', ''='', True)]\"/>\n                    <separator/>\n                    <filter name=\"sales\" string=\"Sales\" domain=\"[(''type'', ''='', ''sale'')]\"/>\n                    <filter name=\"purchases\" string=\"Purchases\" domain=\"[(''type'', ''='', ''purchase'')]\"/>\n                    <filter name=\"liquidity\" string=\"Liquidity\" domain=\"[''|'', (''type'', ''='', ''cash''), (''type'', ''='', ''bank'')]\"/>\n                    <filter name=\"miscellaneous\" string=\"Miscellaneous\" domain=\"[(''type'', ''not in'', [''sale'', ''purchase'', ''cash'', ''bank''])]\"/>\n                    <separator/>\n                    <filter name=\"inactive\" string=\"Archived\" domain=\"[(''active'', ''='', False)]\"/>\n                </search>"}', '<?xml version="1.0"?>
<search string="Search Account Journal">
                    <field name="name" string="Journal" filter_domain="[''|'', (''name'', ''ilike'', self), (''code'', ''ilike'', self)]"/>
                    <filter name="dashboard" string="Favorites" domain="[(''show_on_dashboard'', ''='', True)]"/>
                    <separator/>
                    <filter name="sales" string="Sales" domain="[(''type'', ''='', ''sale'')]"/>
                    <filter name="purchases" string="Purchases" domain="[(''type'', ''='', ''purchase'')]"/>
                    <filter name="liquidity" string="Liquidity" domain="[''|'', (''type'', ''='', ''cash''), (''type'', ''='', ''bank'')]"/>
                    <filter name="miscellaneous" string="Miscellaneous" domain="[(''type'', ''not in'', [''sale'', ''purchase'', ''cash'', ''bank''])]"/>
                    <separator/>
                    <filter name="inactive" string="Archived" domain="[(''active'', ''='', False)]"/>
                </search>
            ', false, true, '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295', false);
INSERT INTO public.ir_ui_view VALUES (694, 1, NULL, 1, 1, 'account.journal.group.tree', 'account.journal.group', NULL, 'tree', 'account/views/account_journal_views.xml', 'primary', '{"en_US": "<tree editable=\"bottom\">\n                    <field name=\"company_id\" column_invisible=\"True\"/>\n                    <field name=\"sequence\" widget=\"handle\"/>\n                    <field name=\"name\"/>\n                    <field name=\"excluded_journal_ids\" widget=\"many2many_tags\" options=\"{''no_create'': True}\"/>\n                    <field name=\"company_id\" groups=\"base.group_multi_company\"/>\n                </tree>"}', '<?xml version="1.0"?>
