INSERT INTO public.ir_ui_view VALUES (695, 1, NULL, 1, 1, 'account.journal.group.form', 'account.journal.group', NULL, 'form', 'account/views/account_journal_views.xml', 'primary', '{"en_US": "<form string=\"Journal Groups\">\n                    <sheet>\n                        <group>\n                            <field name=\"company_id\" invisible=\"1\"/>\n                            <field name=\"name\" placeholder=\"e.g. GAAP, IFRS, ...\"/>\n                            <field name=\"excluded_journal_ids\" widget=\"many2many_tags\" options=\"{''no_create'': True}\"/>\n                            <field name=\"sequence\" groups=\"base.group_no_one\"/>\n                            <field name=\"company_id\" groups=\"base.group_multi_company\"/>\n                        </group>\n                    </sheet>\n                </form>"}', '<?xml version="1.0"?>
