INSERT INTO public.ir_ui_view VALUES (700, 16, NULL, 1, 1, 'account.bank.statement.search', 'account.bank.statement', NULL, 'search', 'account/views/account_bank_statement_views.xml', 'primary', '{"en_US": "<search string=\"Search Bank Statements\">\n                    <field name=\"name\" string=\"Bank Statement\"/>\n                    <field name=\"date\"/>\n                    <filter string=\"Empty\" name=\"empty\" domain=\"[(''line_ids'',''='',False)]\"/>\n                    <filter name=\"invalid\" string=\"Invalid\" domain=\"[''|'', (''is_valid'', ''='', False),(''is_complete'', ''='', False)]\"/>\n                    <separator/>\n                    <filter name=\"filter_date\" date=\"date\"/>\n                    <field name=\"journal_id\" domain=\"[(''type'', ''in'', (''bank'', ''cash''))]\"/>\n                    <group expand=\"0\" string=\"Group By\">\n                        <filter string=\"Journal\" name=\"journal\" context=\"{''group_by'': ''journal_id''}\"/>\n                        <filter string=\"Date\" name=\"date\" context=\"{''group_by'': ''date''}\"/>\n                    </group>\n                </search>"}', '<?xml version="1.0"?>
