INSERT INTO public.ir_ui_view VALUES (703, 16, NULL, 1, 1, 'account.reconcile.model.line.form', 'account.reconcile.model.line', NULL, 'form', 'account/views/account_reconcile_model_views.xml', 'primary', '{"en_US": "<form>\n                    <field name=\"model_id\" invisible=\"1\"/>\n                    <field name=\"allow_payment_tolerance\" invisible=\"1\"/>\n                    <field name=\"payment_tolerance_param\" invisible=\"1\"/>\n                    <field name=\"rule_type\" invisible=\"1\"/>\n                    <group>\n                        <group>\n                            <field name=\"account_id\" options=\"{''no_create'': True}\" domain=\"[(''company_id'', ''='', company_id)]\" required=\"rule_type != ''invoice_matching'' or (rule_type == ''invoice_matching'' and allow_payment_tolerance and payment_tolerance_param != 0.0)\"/>\n                            <field name=\"amount_type\"/>\n                            <field name=\"tax_ids\" domain=\"[(''company_id'', ''='', company_id)]\" options=\"{''no_create'': True}\" context=\"{''append_type_to_tax_name'': True}\" widget=\"many2many_tags\"/>\n                            <field name=\"show_force_tax_included\" invisible=\"1\"/>\n                            <field name=\"force_tax_included\" invisible=\"not show_force_tax_included\" force_save=\"1\"/>\n                            <field name=\"analytic_distribution\" widget=\"analytic_distribution\" groups=\"analytic.group_analytic_accounting\" options=\"{''account_field'': ''account_id'', ''business_domain'': ''general''}\"/>\n                            <field name=\"company_id\" invisible=\"1\"/>\n                        </group>\n                        <group>\n                            <field name=\"label\"/>\n                            <label for=\"amount_string\"/>\n                            <div>\n                                <field name=\"amount_string\" class=\"oe_inline\"/>\n                                <span class=\"o_form_label oe_inline\" invisible=\"amount_type != ''percentage''\">%</span>\n                            </div>\n                        </group>\n                    </group>\n                </form>"}', '<?xml version="1.0"?>
<form>
                    <field name="model_id" invisible="1"/>
                    <field name="allow_payment_tolerance" invisible="1"/>
                    <field name="payment_tolerance_param" invisible="1"/>
                    <field name="rule_type" invisible="1"/>
                    <group>
                        <group>
                            <field name="account_id" options="{''no_create'': True}" domain="[(''company_id'', ''='', company_id)]" required="rule_type != ''invoice_matching'' or (rule_type == ''invoice_matching'' and allow_payment_tolerance and payment_tolerance_param != 0.0)"/>
                            <field name="amount_type"/>
                            <field name="tax_ids" domain="[(''company_id'', ''='', company_id)]" options="{''no_create'': True}" context="{''append_type_to_tax_name'': True}" widget="many2many_tags"/>
                            <field name="show_force_tax_included" invisible="1"/>
                            <field name="force_tax_included" invisible="not show_force_tax_included" force_save="1"/>
                            <field name="analytic_distribution" widget="analytic_distribution" groups="analytic.group_analytic_accounting" options="{''account_field'': ''account_id'', ''business_domain'': ''general''}"/>
                            <field name="company_id" invisible="1"/>
                        </group>
                        <group>
                            <field name="label"/>
                            <label for="amount_string"/>
                            <div>
                                <field name="amount_string" class="oe_inline"/>
                                <span class="o_form_label oe_inline" invisible="amount_type != ''percentage''">%</span>
                            </div>
                        </group>
                    </group>
                </form>
            ', false, true, '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295', false);
INSERT INTO public.ir_ui_view VALUES (704, 16, NULL, 1, 1, 'account.reconcile.model.tree', 'account.reconcile.model', NULL, 'tree', 'account/views/account_reconcile_model_views.xml', 'primary', '{"en_US": "<tree string=\"Bank Reconciliation Move Presets\">\n                    <field name=\"sequence\" widget=\"handle\"/>\n                    <field name=\"name\"/>\n                    <field name=\"rule_type\"/>\n                    <field name=\"auto_reconcile\"/>\n                    <field name=\"match_journal_ids\" optional=\"hidden\" widget=\"many2many_tags\"/>\n                </tree>"}', '<?xml version="1.0"?>
