INSERT INTO public.ir_ui_view VALUES (705, 16, NULL, 1, 1, 'account.reconcile.model.form', 'account.reconcile.model', NULL, 'form', 'account/views/account_reconcile_model_views.xml', 'primary', '{"en_US": "<form string=\"Operation Templates\">\n                    <field name=\"active\" invisible=\"1\"/>\n                    <field name=\"payment_tolerance_param\" invisible=\"1\"/>\n                    <field name=\"company_id\" invisible=\"1\"/>\n                    <sheet>\n                        <div class=\"oe_button_box\" name=\"button_box\">\n                            <button type=\"object\" name=\"action_reconcile_stat\" class=\"oe_stat_button\" icon=\"fa-book\">\n                                <field name=\"number_entries\" string=\"Journal Entries\" widget=\"statinfo\"/>\n                            </button>\n                        </div>\n                        <div class=\"oe_title\">\n                            <label for=\"name\" placeholder=\"Model Name\"/>\n                            <h1><field name=\"name\" placeholder=\"e.g. Bank Fees\"/></h1>\n                        </div>\n                        <group>\n                            <group>\n                                <field name=\"rule_type\" widget=\"radio\"/>\n                            </group>\n                            <group>\n                                <field name=\"auto_reconcile\" invisible=\"rule_type == ''writeoff_button''\"/>\n                                <field name=\"to_check\" invisible=\"rule_type != ''writeoff_button''\"/>\n                                <field name=\"past_months_limit\" invisible=\"rule_type != ''invoice_matching''\"/>\n                                <field name=\"matching_order\" invisible=\"rule_type != ''invoice_matching''\"/>\n                            </group>\n                        </group>\n                        <notebook>\n                            <page id=\"conditions_tab\" string=\"Bank Transactions Conditions\" name=\"page_bank_transactions_conditions\">\n                                <group id=\"conditions_tab_group\">\n                                    <group id=\"left_column\" class=\"col-6\">\n                                        <label for=\"match_journal_ids\"/>\n                                        <div>\n                                            <field name=\"match_journal_ids\" widget=\"many2many_tags\" nolabel=\"1\" options=\"{''no_create'': True}\"/>\n                                        </div>\n                                        <field name=\"match_nature\" invisible=\"rule_type == ''writeoff_button''\"/>\n                                        <label for=\"match_amount\" invisible=\"rule_type == ''writeoff_button''\"/>\n                                        <div class=\"d-flex gap-2\" invisible=\"rule_type == ''writeoff_button''\">\n                                            <field name=\"match_amount\"/>\n                                            <field name=\"match_amount_min\" invisible=\"match_amount in (False, ''lower'')\" required=\"match_amount\"/>\n                                            <span class=\"o_form_label\" invisible=\"match_amount != ''between''\">and</span>\n                                            <field name=\"match_amount_max\" invisible=\"match_amount in (False, ''greater'')\" required=\"match_amount == ''between''\"/>\n                                        </div>\n                                        <label for=\"allow_payment_tolerance\" invisible=\"rule_type != ''invoice_matching''\"/>\n                                        <div class=\"d-flex gap-2\" invisible=\"rule_type != ''invoice_matching''\">\n                                            <field name=\"allow_payment_tolerance\"/>\n                                            <span invisible=\"not allow_payment_tolerance\" class=\"d-flex gap-2 w-100\">\n                                                <field name=\"payment_tolerance_param\"/>\n                                                <field name=\"payment_tolerance_type\"/>\n                                            </span>\n                                        </div>\n                                        <field name=\"match_same_currency\" invisible=\"rule_type != ''invoice_matching''\"/>\n                                    </group>\n                                    <group id=\"right column\" class=\"col-6\">\n                                        <span invisible=\"rule_type != ''invoice_matching''\" class=\"o_form_label o_td_label\">Match Invoice/bill with</span>\n                                        <div class=\"d-flex gap-3\" invisible=\"rule_type != ''invoice_matching''\">\n                                            <label for=\"match_text_location_label\" string=\"Label\"/>\n                                            <field name=\"match_text_location_label\"/>\n                                            <label for=\"match_text_location_note\" string=\"Note\"/>\n                                            <field name=\"match_text_location_note\"/>\n                                            <label for=\"match_text_location_reference\" string=\"Reference\"/>\n                                            <field name=\"match_text_location_reference\"/>\n                                        </div>\n                                        <label for=\"match_label\" invisible=\"rule_type == ''writeoff_button''\"/>\n                                        <div class=\"d-flex gap-3\" invisible=\"rule_type == ''writeoff_button''\">\n                                            <field name=\"match_label\"/>\n                                            <field name=\"match_label_param\" invisible=\"not match_label\" required=\"match_label\"/>\n                                        </div>\n                                        <label for=\"match_note\" invisible=\"rule_type == ''writeoff_button''\"/>\n                                        <div class=\"d-flex gap-3\" invisible=\"rule_type == ''writeoff_button''\">\n                                            <field name=\"match_note\"/>\n                                            <field name=\"match_note_param\" invisible=\"not match_note\" required=\"match_note\"/>\n                                        </div>\n                                        <label for=\"match_transaction_type\" invisible=\"rule_type == ''writeoff_button''\"/>\n                                        <div class=\"d-flex gap-3\" invisible=\"rule_type == ''writeoff_button''\">\n                                            <field name=\"match_transaction_type\"/>\n                                            <field name=\"match_transaction_type_param\" invisible=\"not match_transaction_type\" required=\"match_transaction_type\"/>\n                                        </div>\n                                        <field name=\"match_partner\" invisible=\"rule_type == ''writeoff_button''\"/>\n                                        <label for=\"match_partner_ids\" class=\"ml16\" invisible=\"not match_partner or rule_type == ''writeoff_button''\"/>\n                                        <field name=\"match_partner_ids\" nolabel=\"1\" widget=\"many2many_tags\" options=\"{''no_quick_create'': True}\" invisible=\"not match_partner or rule_type == ''writeoff_button''\"/>\n                                        <label for=\"match_partner_category_ids\" class=\"ml16\" invisible=\"not match_partner or rule_type == ''writeoff_button''\"/>\n                                        <field name=\"match_partner_category_ids\" nolabel=\"1\" widget=\"many2many_tags\" invisible=\"not match_partner or rule_type == ''writeoff_button''\"/>\n                                    </group>\n                                </group>\n                                <group string=\"Counterpart Entries\" colespan=\"4\" class=\"oe_inline\" invisible=\"rule_type == ''invoice_matching'' and (not allow_payment_tolerance or allow_payment_tolerance and payment_tolerance_param == 0.0)\">\n                                    <group>\n                                        <field name=\"show_decimal_separator\" invisible=\"1\"/>\n                                        <field name=\"decimal_separator\" invisible=\"not show_decimal_separator\" groups=\"base.group_no_one\"/>\n                                    </group>\n                                    <field name=\"line_ids\" default=\"{''default_model_id'': self, ''default_company_id'': self.company_id}\" nolabel=\"1\">\n                                        <tree editable=\"bottom\">\n                                            <field name=\"show_force_tax_included\" column_invisible=\"True\"/>\n                                            <field name=\"company_id\" column_invisible=\"True\"/>\n\n                                            <field name=\"sequence\" widget=\"handle\"/>\n                                            <field name=\"account_id\"/>\n                                            <field name=\"amount_type\"/>\n                                            <field name=\"journal_id\" column_invisible=\"parent.rule_type != ''writeoff_button''\" optional=\"hide\"/>\n                                            <field name=\"amount_string\"/>\n                                            <field name=\"tax_ids\" widget=\"many2many_tags\" optional=\"hide\"/>\n                                            <field name=\"analytic_distribution\" widget=\"analytic_distribution\" groups=\"analytic.group_analytic_accounting\" options=\"{''account_field'': ''account_id'', ''business_domain'': ''general''}\"/>\n                                            <field name=\"force_tax_included\" widget=\"boolean_toggle\" options=\"{''autosave'': False}\" invisible=\"not show_force_tax_included\" optional=\"hide\"/>\n                                            <field name=\"label\"/>\n                                        </tree>\n                                    </field>\n                                </group>\n                            </page>\n                            <page id=\"partner_tab\" string=\"Partner Mapping\" name=\"page_partner_mapping\" invisible=\"rule_type not in (''invoice_matching'', ''writeoff_suggestion'')\">\n                                <field name=\"partner_mapping_line_ids\" nolabel=\"1\">\n                                    <tree editable=\"bottom\">\n                                        <field name=\"company_id\"/>\n                                        <field name=\"payment_ref_regex\" required=\"not narration_regex\"/>\n                                        <field name=\"narration_regex\" required=\"not payment_ref_regex\"/>\n                                        <field name=\"partner_id\"/>\n                                    </tree>\n                                </field>\n                            </page>\n                        </notebook>\n\n                    </sheet>\n\n                    <div class=\"oe_chatter\">\n                        <field name=\"message_follower_ids\" groups=\"base.group_user\"/>\n                        <field name=\"message_ids\"/>\n                    </div>\n                </form>"}', '<?xml version="1.0"?>
<form string="Operation Templates">
                    <field name="active" invisible="1"/>
                    <field name="payment_tolerance_param" invisible="1"/>
                    <field name="company_id" invisible="1"/>
                    <sheet>
                        <div class="oe_button_box" name="button_box">
                            <button type="object" name="action_reconcile_stat" class="oe_stat_button" icon="fa-book">
                                <field name="number_entries" string="Journal Entries" widget="statinfo"/>
                            </button>
                        </div>
                        <div class="oe_title">
                            <label for="name" placeholder="Model Name"/>
                            <h1><field name="name" placeholder="e.g. Bank Fees"/></h1>
                        </div>
                        <group>
                            <group>
                                <field name="rule_type" widget="radio"/>
                            </group>
                            <group>
                                <field name="auto_reconcile" invisible="rule_type == ''writeoff_button''"/>
                                <field name="to_check" invisible="rule_type != ''writeoff_button''"/>
                                <field name="past_months_limit" invisible="rule_type != ''invoice_matching''"/>
                                <field name="matching_order" invisible="rule_type != ''invoice_matching''"/>
                            </group>
                        </group>
                        <notebook>
                            <page id="conditions_tab" string="Bank Transactions Conditions" name="page_bank_transactions_conditions">
                                <group id="conditions_tab_group">
                                    <group id="left_column" class="col-6">
                                        <label for="match_journal_ids"/>
                                        <div>
                                            <field name="match_journal_ids" widget="many2many_tags" nolabel="1" options="{''no_create'': True}"/>
                                        </div>
                                        <field name="match_nature" invisible="rule_type == ''writeoff_button''"/>
                                        <label for="match_amount" invisible="rule_type == ''writeoff_button''"/>
                                        <div class="d-flex gap-2" invisible="rule_type == ''writeoff_button''">
                                            <field name="match_amount"/>
                                            <field name="match_amount_min" invisible="match_amount in (False, ''lower'')" required="match_amount"/>
                                            <span class="o_form_label" invisible="match_amount != ''between''">and</span>
                                            <field name="match_amount_max" invisible="match_amount in (False, ''greater'')" required="match_amount == ''between''"/>
                                        </div>
                                        <label for="allow_payment_tolerance" invisible="rule_type != ''invoice_matching''"/>
                                        <div class="d-flex gap-2" invisible="rule_type != ''invoice_matching''">
                                            <field name="allow_payment_tolerance"/>
                                            <span invisible="not allow_payment_tolerance" class="d-flex gap-2 w-100">
                                                <field name="payment_tolerance_param"/>
                                                <field name="payment_tolerance_type"/>
                                            </span>
                                        </div>
                                        <field name="match_same_currency" invisible="rule_type != ''invoice_matching''"/>
                                    </group>
                                    <group id="right column" class="col-6">
                                        <span invisible="rule_type != ''invoice_matching''" class="o_form_label o_td_label">Match Invoice/bill with</span>
                                        <div class="d-flex gap-3" invisible="rule_type != ''invoice_matching''">
                                            <label for="match_text_location_label" string="Label"/>
                                            <field name="match_text_location_label"/>
                                            <label for="match_text_location_note" string="Note"/>
                                            <field name="match_text_location_note"/>
                                            <label for="match_text_location_reference" string="Reference"/>
                                            <field name="match_text_location_reference"/>
                                        </div>
                                        <label for="match_label" invisible="rule_type == ''writeoff_button''"/>
                                        <div class="d-flex gap-3" invisible="rule_type == ''writeoff_button''">
                                            <field name="match_label"/>
                                            <field name="match_label_param" invisible="not match_label" required="match_label"/>
                                        </div>
                                        <label for="match_note" invisible="rule_type == ''writeoff_button''"/>
                                        <div class="d-flex gap-3" invisible="rule_type == ''writeoff_button''">
                                            <field name="match_note"/>
                                            <field name="match_note_param" invisible="not match_note" required="match_note"/>
                                        </div>
                                        <label for="match_transaction_type" invisible="rule_type == ''writeoff_button''"/>
                                        <div class="d-flex gap-3" invisible="rule_type == ''writeoff_button''">
                                            <field name="match_transaction_type"/>
                                            <field name="match_transaction_type_param" invisible="not match_transaction_type" required="match_transaction_type"/>
                                        </div>
                                        <field name="match_partner" invisible="rule_type == ''writeoff_button''"/>
                                        <label for="match_partner_ids" class="ml16" invisible="not match_partner or rule_type == ''writeoff_button''"/>
                                        <field name="match_partner_ids" nolabel="1" widget="many2many_tags" options="{''no_quick_create'': True}" invisible="not match_partner or rule_type == ''writeoff_button''"/>
                                        <label for="match_partner_category_ids" class="ml16" invisible="not match_partner or rule_type == ''writeoff_button''"/>
                                        <field name="match_partner_category_ids" nolabel="1" widget="many2many_tags" invisible="not match_partner or rule_type == ''writeoff_button''"/>
                                    </group>
                                </group>
                                <group string="Counterpart Entries" colespan="4" class="oe_inline" invisible="rule_type == ''invoice_matching'' and (not allow_payment_tolerance or allow_payment_tolerance and payment_tolerance_param == 0.0)">
                                    <group>
                                        <field name="show_decimal_separator" invisible="1"/>
                                        <field name="decimal_separator" invisible="not show_decimal_separator" groups="base.group_no_one"/>
                                    </group>
                                    <field name="line_ids" default="{''default_model_id'': self, ''default_company_id'': self.company_id}" nolabel="1">
                                        <tree editable="bottom">
                                            <field name="show_force_tax_included" column_invisible="True"/>
                                            <field name="company_id" column_invisible="True"/>

                                            <field name="sequence" widget="handle"/>
                                            <field name="account_id"/>
                                            <field name="amount_type"/>
                                            <field name="journal_id" column_invisible="parent.rule_type != ''writeoff_button''" optional="hide"/>
                                            <field name="amount_string"/>
                                            <field name="tax_ids" widget="many2many_tags" optional="hide"/>
                                            <field name="analytic_distribution" widget="analytic_distribution" groups="analytic.group_analytic_accounting" options="{''account_field'': ''account_id'', ''business_domain'': ''general''}"/>
                                            <field name="force_tax_included" widget="boolean_toggle" options="{''autosave'': False}" invisible="not show_force_tax_included" optional="hide"/>
                                            <field name="label"/>
                                        </tree>
                                    </field>
                                </group>
                            </page>
                            <page id="partner_tab" string="Partner Mapping" name="page_partner_mapping" invisible="rule_type not in (''invoice_matching'', ''writeoff_suggestion'')">
                                <field name="partner_mapping_line_ids" nolabel="1">
                                    <tree editable="bottom">
                                        <field name="company_id"/>
                                        <field name="payment_ref_regex" required="not narration_regex"/>
                                        <field name="narration_regex" required="not payment_ref_regex"/>
                                        <field name="partner_id"/>
                                    </tree>
                                </field>
                            </page>
                        </notebook>

                    </sheet>

                    <div class="oe_chatter">
                        <field name="message_follower_ids" groups="base.group_user"/>
                        <field name="message_ids"/>
                    </div>
                </form>
            ', false, true, '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295', false);
