INSERT INTO public.ir_ui_view VALUES (711, 16, NULL, 1, 1, 'account.tax.kanban', 'account.tax', NULL, 'kanban', 'account/views/account_tax_views.xml', 'primary', '{"en_US": "<kanban class=\"o_kanban_mobile\">\n                    <field name=\"name\"/>\n                    <field name=\"type_tax_use\"/>\n                    <field name=\"tax_scope\"/>\n                    <templates>\n                        <t t-name=\"kanban-box\">\n                            <div t-attf-class=\"oe_kanban_card oe_kanban_global_click\">\n                                <div class=\"row mb4\">\n                                    <div class=\"col-6\">\n                                        <strong><span><t t-out=\"record.name.value\"/></span></strong>\n                                    </div>\n                                    <div class=\"col-6 text-end\">\n                                        <span class=\"badge rounded-pill\"><t t-out=\"record.type_tax_use.value\"/></span>\n                                        <span class=\"badge rounded-pill\"><t t-out=\"record.tax_scope.value\"/></span>\n                                    </div>\n                                </div>\n                            </div>\n                        </t>\n                    </templates>\n                </kanban>"}', '<?xml version="1.0"?>
