INSERT INTO public.ir_ui_view VALUES (712, 16, NULL, 1, 1, 'account.tax.search', 'account.tax', NULL, 'search', 'account/views/account_tax_views.xml', 'primary', '{"en_US": "<search string=\"Search Taxes\">\n                    <field name=\"name_searchable\" string=\"Name\"/>\n                    <field name=\"description\"/>\n                    <field name=\"amount\"/>\n                    <field name=\"company_id\" groups=\"base.group_multi_company\"/>\n                    <filter string=\"Sale\" name=\"sale\" domain=\"[(''type_tax_use'',''='',''sale'')]\"/>\n                    <filter string=\"Purchase\" name=\"purchase\" domain=\"[(''type_tax_use'',''='',''purchase'')]\"/>\n                    <separator/>\n                    <filter string=\"Services\" name=\"service\" domain=\"[(''tax_scope'',''='',''service'')]\"/>\n                    <filter string=\"Goods\" name=\"goods\" domain=\"[(''tax_scope'',''='',''consu'')]\"/>\n                    <separator/>\n                    <filter name=\"active\" string=\"Active\" domain=\"[(''active'',''='',True)]\" help=\"Show active taxes\"/>\n                    <filter name=\"inactive\" string=\"Inactive\" domain=\"[(''active'',''='',False)]\" help=\"Show inactive taxes\"/>\n                    <group string=\"Group By\">\n                        <filter string=\"Company\" name=\"company\" domain=\"[]\" context=\"{''group_by'':''company_id''}\" groups=\"base.group_multi_company\"/>\n                        <filter string=\"Tax Type\" name=\"taxapp\" domain=\"[]\" context=\"{''group_by'':''type_tax_use''}\"/>\n                        <filter string=\"Tax Scope\" name=\"taxapp\" domain=\"[]\" context=\"{''group_by'':''tax_scope''}\"/>\n                    </group>\n                </search>"}', '<?xml version="1.0"?>
<search string="Search Taxes">
                    <field name="name_searchable" string="Name"/>
                    <field name="description"/>
                    <field name="amount"/>
                    <field name="company_id" groups="base.group_multi_company"/>
                    <filter string="Sale" name="sale" domain="[(''type_tax_use'',''='',''sale'')]"/>
                    <filter string="Purchase" name="purchase" domain="[(''type_tax_use'',''='',''purchase'')]"/>
                    <separator/>
                    <filter string="Services" name="service" domain="[(''tax_scope'',''='',''service'')]"/>
                    <filter string="Goods" name="goods" domain="[(''tax_scope'',''='',''consu'')]"/>
                    <separator/>
                    <filter name="active" string="Active" domain="[(''active'',''='',True)]" help="Show active taxes"/>
                    <filter name="inactive" string="Inactive" domain="[(''active'',''='',False)]" help="Show inactive taxes"/>
                    <group string="Group By">
                        <filter string="Company" name="company" domain="[]" context="{''group_by'':''company_id''}" groups="base.group_multi_company"/>
                        <filter string="Tax Type" name="taxapp" domain="[]" context="{''group_by'':''type_tax_use''}"/>
                        <filter string="Tax Scope" name="taxapp" domain="[]" context="{''group_by'':''tax_scope''}"/>
                    </group>
                </search>
            ', false, true, '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295', false);
