INSERT INTO public.ir_ui_view VALUES (714, 16, NULL, 1, 1, 'account.tax.form', 'account.tax', NULL, 'form', 'account/views/account_tax_views.xml', 'primary', '{"en_US": "<form string=\"Account Tax\">\n                    <field name=\"company_id\" invisible=\"1\"/>\n                    <sheet>\n                    <group>\n                        <group>\n                            <field name=\"name\"/>\n                            <field name=\"description\"/>\n                            <field name=\"amount_type\"/>\n                            <field name=\"active\" widget=\"boolean_toggle\"/>\n                        </group>\n                        <group>\n                            <field name=\"is_used\" invisible=\"1\"/>\n                            <field name=\"type_tax_use\"/>\n                            <field name=\"tax_scope\"/>\n                            <label for=\"amount\" invisible=\"amount_type not in (''fixed'', ''percent'', ''division'')\"/>\n                            <div invisible=\"amount_type not in (''fixed'', ''percent'', ''division'')\">\n                                <field name=\"amount\" class=\"oe_inline\" nolabel=\"1\"/>\n                                <span class=\"o_form_label oe_inline\" invisible=\"amount_type == ''fixed''\">%</span>\n                            </div>\n                        </group>\n                    </group>\n                    <notebook>\n                        <page string=\"Definition\" name=\"definition\">\n                            <div invisible=\"amount_type == ''group''\">\n                                <field name=\"country_code\" invisible=\"1\"/>\n                                <group string=\"Distribution for Invoices\" class=\"mw-100\">\n                                    <field name=\"invoice_repartition_line_ids\" nolabel=\"1\" colspan=\"2\"/>\n                                </group>\n                                <group string=\"Distribution for Refunds\" class=\"mw-100\">\n                                    <field name=\"refund_repartition_line_ids\" nolabel=\"1\" colspan=\"2\"/>\n                                </group>\n                            </div>\n                            <field name=\"children_tax_ids\" invisible=\"amount_type != ''group'' or type_tax_use == ''none''\" domain=\"[(''type_tax_use'',''in'',(''none'',type_tax_use)), (''amount_type'',''!='',''group'')]\">\n                                <tree string=\"Children Taxes\">\n                                    <field name=\"sequence\" widget=\"handle\"/>\n                                    <field name=\"name\"/>\n                                    <field name=\"amount_type\"/>\n                                    <field name=\"amount\"/>\n                                </tree>\n                            </field>\n                        </page>\n                        <page string=\"Advanced Options\" name=\"advanced_options\">\n                            <group>\n                                <group>\n                                    <field name=\"invoice_label\"/>\n                                    <field name=\"tax_group_id\" invisible=\"amount_type == ''group''\" required=\"amount_type != ''group''\"/>\n                                    <field name=\"analytic\" invisible=\"amount_type == ''group''\" groups=\"analytic.group_analytic_accounting\"/>\n                                    <field name=\"company_id\" options=\"{''no_create'': True}\" groups=\"base.group_multi_company\"/>\n                                    <field name=\"country_id\" required=\"True\"/>\n                                </group>\n                                <group name=\"advanced_booleans\">\n                                    <field name=\"price_include\" invisible=\"amount_type == ''group''\"/>\n                                    <field name=\"include_base_amount\" invisible=\"amount_type == ''group''\"/>\n                                    <field name=\"is_base_affected\" invisible=\"amount_type == ''group'' or price_include\" groups=\"base.group_no_one\"/>\n                                    <field name=\"hide_tax_exigibility\" invisible=\"1\"/>\n                                    <field name=\"tax_exigibility\" widget=\"radio\" invisible=\"amount_type == ''group'' or not hide_tax_exigibility\"/>\n                                    <field name=\"cash_basis_transition_account_id\" options=\"{''no_create'': True}\" invisible=\"tax_exigibility == ''on_invoice''\" required=\"tax_exigibility == ''on_payment''\" groups=\"account.group_account_readonly\"/>\n                                </group>\n                            </group>\n                        </page>\n                    </notebook>\n                </sheet>\n                <div class=\"oe_chatter\">\n                    <field name=\"message_follower_ids\" widget=\"mail_followers\"/>\n                    <field name=\"message_ids\" widget=\"mail_thread\"/>\n                </div>\n                </form>"}', '<?xml version="1.0"?>
<form string="Account Tax">
                    <field name="company_id" invisible="1"/>
                    <sheet>
                    <group>
                        <group>
                            <field name="name"/>
                            <field name="description"/>
                            <field name="amount_type"/>
                            <field name="active" widget="boolean_toggle"/>
                        </group>
                        <group>
                            <field name="is_used" invisible="1"/>
                            <field name="type_tax_use"/>
                            <field name="tax_scope"/>
                            <label for="amount" invisible="amount_type not in (''fixed'', ''percent'', ''division'')"/>
                            <div invisible="amount_type not in (''fixed'', ''percent'', ''division'')">
                                <field name="amount" class="oe_inline" nolabel="1"/>
                                <span class="o_form_label oe_inline" invisible="amount_type == ''fixed''">%</span>
                            </div>
                        </group>
                    </group>
                    <notebook>
                        <page string="Definition" name="definition">
                            <div invisible="amount_type == ''group''">
                                <field name="country_code" invisible="1"/>
                                <group string="Distribution for Invoices" class="mw-100">
                                    <field name="invoice_repartition_line_ids" nolabel="1" colspan="2"/>
                                </group>
                                <group string="Distribution for Refunds" class="mw-100">
                                    <field name="refund_repartition_line_ids" nolabel="1" colspan="2"/>
                                </group>
                            </div>
                            <field name="children_tax_ids" invisible="amount_type != ''group'' or type_tax_use == ''none''" domain="[(''type_tax_use'',''in'',(''none'',type_tax_use)), (''amount_type'',''!='',''group'')]">
                                <tree string="Children Taxes">
                                    <field name="sequence" widget="handle"/>
                                    <field name="name"/>
                                    <field name="amount_type"/>
                                    <field name="amount"/>
                                </tree>
                            </field>
                        </page>
                        <page string="Advanced Options" name="advanced_options">
                            <group>
                                <group>
                                    <field name="invoice_label"/>
                                    <field name="tax_group_id" invisible="amount_type == ''group''" required="amount_type != ''group''"/>
                                    <field name="analytic" invisible="amount_type == ''group''" groups="analytic.group_analytic_accounting"/>
                                    <field name="company_id" options="{''no_create'': True}" groups="base.group_multi_company"/>
                                    <field name="country_id" required="True"/>
                                </group>
                                <group name="advanced_booleans">
                                    <field name="price_include" invisible="amount_type == ''group''"/>
                                    <field name="include_base_amount" invisible="amount_type == ''group''"/>
                                    <field name="is_base_affected" invisible="amount_type == ''group'' or price_include" groups="base.group_no_one"/>
                                    <field name="hide_tax_exigibility" invisible="1"/>
                                    <field name="tax_exigibility" widget="radio" invisible="amount_type == ''group'' or not hide_tax_exigibility"/>
                                    <field name="cash_basis_transition_account_id" options="{''no_create'': True}" invisible="tax_exigibility == ''on_invoice''" required="tax_exigibility == ''on_payment''" groups="account.group_account_readonly"/>
                                </group>
                            </group>
                        </page>
                    </notebook>
                </sheet>
                <div class="oe_chatter">
                    <field name="message_follower_ids" widget="mail_followers"/>
                    <field name="message_ids" widget="mail_thread"/>
                </div>
                </form>
              ', false, true, '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295', false);
