            ', false, true, '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295', false);
INSERT INTO public.ir_ui_view VALUES (721, 16, NULL, 1, 1, 'account.payment.term.form', 'account.payment.term', NULL, 'form', 'account/views/account_payment_term_views.xml', 'primary', '{"en_US": "<form string=\"Payment Terms\">\n                    <sheet>\n                        <field name=\"active\" invisible=\"1\"/>\n                        <field name=\"fiscal_country_codes\" invisible=\"1\"/>\n                        <field name=\"company_id\" invisible=\"1\"/>\n                        <widget name=\"web_ribbon\" title=\"Archived\" bg_color=\"text-bg-danger\" invisible=\"active\"/>\n                        <div class=\"oe_title\">\n                            <label for=\"name\" string=\"Payment Terms\"/>\n                            <h1><field name=\"name\" nolabel=\"1\" placeholder=\"e.g. 30 days\"/></h1>\n                        </div>\n                        <group>\n                            <field name=\"company_id\" options=\"{''no_create'': True}\" class=\"w-25\" groups=\"base.group_multi_company\"/>\n                            <label for=\"early_discount\"/>\n                            <div class=\"o_field_highlight\">\n                                <field name=\"early_discount\"/>\n                                <field name=\"discount_percentage\" class=\"text-end o_field_highlight o_input oe_inline\" invisible=\"not early_discount\"/>\n                                <span invisible=\"not early_discount\"> % if paid within </span>\n                                <field name=\"discount_days\" class=\"text-end o_field_highlight o_input oe_inline\" invisible=\"not early_discount\"/>\n                                <span invisible=\"not early_discount\"> days</span>\n                                <div invisible=\"not early_discount\">\n                                    <span> Reduced tax:\n                                        <field name=\"early_pay_discount_computation\" class=\"w-auto\"/>\n                                    </span>\n                                </div>\n                            </div>\n                        </group>\n                        <group>\n                            <group string=\"Due Terms\">\n                                <field name=\"line_ids\" widget=\"payment_term_line_ids\" nolabel=\"1\" colspan=\"2\">\n                                    <tree string=\"Payment Terms\" editable=\"bottom\" no_open=\"True\">\n                                        <field name=\"value_amount\"/>\n                                        <field name=\"value\" nolabel=\"1\"/>\n                                        <field name=\"nb_days\" string=\"After\"/>\n                                        <field name=\"delay_type\" nolabel=\"1\"/>\n                                    </tree>\n                                </field>\n                            </group>\n                            <group string=\"Preview\">\n                                <field name=\"currency_id\" invisible=\"1\"/>\n                                <div class=\"d-flex gap-2\" colspan=\"2\" col=\"4\">\n                                    Example:\n                                    <field name=\"example_amount\" class=\"oe_inline\"/>\n                                    on\n                                    <field name=\"example_date\" class=\"fw-bold border-bottom o_example_date\"/>\n                                </div>\n                                <div colspan=\"2\" class=\"py-1 bg-secondary\">\n                                    <field name=\"note\" placeholder=\"e.g. Payment terms: 30 days after invoice date\" class=\"border-bottom o_example_note\"/>\n                                    <field name=\"example_preview_discount\" class=\"ps-2\" invisible=\"not early_discount or not display_on_invoice\"/>\n                                    <field name=\"example_preview\" class=\"ps-2\" invisible=\"not display_on_invoice\"/>\n                                </div>\n                                <div colspan=\"2\">\n                                    <field name=\"display_on_invoice\" nolabel=\"1\"/>\n                                    <label for=\"display_on_invoice\"/>\n                                </div>\n                            </group>\n                        </group>\n                    </sheet>\n                </form>"}', '<?xml version="1.0"?>
<form string="Payment Terms">
                    <sheet>
                        <field name="active" invisible="1"/>
                        <field name="fiscal_country_codes" invisible="1"/>
                        <field name="company_id" invisible="1"/>
                        <widget name="web_ribbon" title="Archived" bg_color="text-bg-danger" invisible="active"/>
                        <div class="oe_title">
                            <label for="name" string="Payment Terms"/>
                            <h1><field name="name" nolabel="1" placeholder="e.g. 30 days"/></h1>
                        </div>
                        <group>
                            <field name="company_id" options="{''no_create'': True}" class="w-25" groups="base.group_multi_company"/>
                            <label for="early_discount"/>
                            <div class="o_field_highlight">
                                <field name="early_discount"/>
                                <field name="discount_percentage" class="text-end o_field_highlight o_input oe_inline" invisible="not early_discount"/>
                                <span invisible="not early_discount"> % if paid within </span>
                                <field name="discount_days" class="text-end o_field_highlight o_input oe_inline" invisible="not early_discount"/>
                                <span invisible="not early_discount"> days</span>
                                <div invisible="not early_discount">
                                    <span> Reduced tax:
                                        <field name="early_pay_discount_computation" class="w-auto"/>
                                    </span>
                                </div>
                            </div>
                        </group>
                        <group>
                            <group string="Due Terms">
                                <field name="line_ids" widget="payment_term_line_ids" nolabel="1" colspan="2">
                                    <tree string="Payment Terms" editable="bottom" no_open="True">
                                        <field name="value_amount"/>
                                        <field name="value" nolabel="1"/>
                                        <field name="nb_days" string="After"/>
                                        <field name="delay_type" nolabel="1"/>
                                    </tree>
                                </field>
                            </group>
                            <group string="Preview">
                                <field name="currency_id" invisible="1"/>
                                <div class="d-flex gap-2" colspan="2" col="4">
                                    Example:
                                    <field name="example_amount" class="oe_inline"/>
                                    on
                                    <field name="example_date" class="fw-bold border-bottom o_example_date"/>
                                </div>
                                <div colspan="2" class="py-1 bg-secondary">
                                    <field name="note" placeholder="e.g. Payment terms: 30 days after invoice date" class="border-bottom o_example_note"/>
                                    <field name="example_preview_discount" class="ps-2" invisible="not early_discount or not display_on_invoice"/>
                                    <field name="example_preview" class="ps-2" invisible="not display_on_invoice"/>
                                </div>
                                <div colspan="2">
                                    <field name="display_on_invoice" nolabel="1"/>
                                    <label for="display_on_invoice"/>
                                </div>
                            </group>
                        </group>
                    </sheet>
                </form>
            ', false, true, '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295', false);
INSERT INTO public.ir_ui_view VALUES (722, 16, NULL, 1, 1, 'account.payment.term.kanban', 'account.payment.term', NULL, 'kanban', 'account/views/account_payment_term_views.xml', 'primary', '{"en_US": "<kanban class=\"o_kanban_mobile\">\n                    <field name=\"name\"/>\n                    <field name=\"note\"/>\n                    <templates>\n                        <t t-name=\"kanban-box\">\n                            <div t-attf-class=\"oe_kanban_global_click\">\n                                <div><strong class=\"o_kanban_record_title\"><t t-out=\"record.name.value\"/></strong></div>\n                                <div t-if=\"!widget.isHtmlEmpty(record.note.raw_value)\"><t t-out=\"record.note.value\"/></div>\n                            </div>\n                        </t>\n                    </templates>\n                </kanban>"}', '<?xml version="1.0"?>
<kanban class="o_kanban_mobile">
                    <field name="name"/>
                    <field name="note"/>
                    <templates>
                        <t t-name="kanban-box">
                            <div t-attf-class="oe_kanban_global_click">
                                <div><strong class="o_kanban_record_title"><t t-out="record.name.value"/></strong></div>
                                <div t-if="!widget.isHtmlEmpty(record.note.raw_value)"><t t-out="record.note.value"/></div>
                            </div>
                        </t>
                    </templates>
                </kanban>
            ', false, true, '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295', false);
INSERT INTO public.ir_ui_view VALUES (723, 16, NULL, 1, 1, 'account.payment.method.line.tree', 'account.payment.method.line', NULL, 'tree', 'account/views/account_payment_method.xml', 'primary', '{"en_US": "<tree edit=\"0\">\n                <field name=\"name\" string=\"Payment Method Name\"/>\n                <field name=\"journal_id\"/>\n            </tree>"}', '<?xml version="1.0"?>
<tree edit="0">
                <field name="name" string="Payment Method Name"/>
                <field name="journal_id"/>
            </tree>
        ', false, true, '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295', false);
INSERT INTO public.ir_ui_view VALUES (724, 16, NULL, 1, 1, 'account.payment.method.line.kanban', 'account.payment.method.line', NULL, 'kanban', 'account/views/account_payment_method.xml', 'primary', '{"en_US": "<kanban>\n                <field name=\"name\"/>\n                <field name=\"journal_id\"/>\n                <templates>\n                    <t t-name=\"kanban-box\">\n                        <div class=\"oe_kanban_global_click\">\n                            <span><field name=\"name\"/> (<field name=\"journal_id\"/>)</span>\n                        </div>\n                    </t>\n                </templates>\n            </kanban>"}', '<?xml version="1.0"?>
<kanban>
                <field name="name"/>
                <field name="journal_id"/>
                <templates>
                    <t t-name="kanban-box">
                        <div class="oe_kanban_global_click">
                            <span><field name="name"/> (<field name="journal_id"/>)</span>
                        </div>
                    </t>
                </templates>
            </kanban>
        ', false, true, '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295', false);
INSERT INTO public.ir_ui_view VALUES (725, 14, 138, 1, 1, 'res.partner.bank.form.inherit.account', 'res.partner.bank', NULL, 'form', 'account/views/res_partner_bank_views.xml', 'primary', '{"en_US": "<data><xpath expr=\"//form[@name=''bank_account_form'']/sheet[1]\" position=\"after\">\n                    <div class=\"oe_chatter\">\n                        <field name=\"message_follower_ids\"/>\n                        <field name=\"message_ids\"/>\n                        <field name=\"activity_ids\"/>\n                    </div>\n                </xpath>\n\n                <xpath expr=\"//field[@name=''acc_number'']\" position=\"attributes\">\n                    <attribute name=\"readonly\">lock_trust_fields</attribute>\n                    <attribute name=\"force_save\">1</attribute>\n                </xpath>\n\n                <xpath expr=\"//field[@name=''partner_id'']\" position=\"attributes\">\n                    <attribute name=\"readonly\">lock_trust_fields</attribute>\n                    <attribute name=\"force_save\">1</attribute>\n                </xpath>\n\n                <xpath expr=\"//field[@name=''allow_out_payment'']\" position=\"replace\">\n                    <field name=\"user_has_group_validate_bank_account\" invisible=\"1\"/>\n                    <field name=\"lock_trust_fields\" invisible=\"1\"/>\n                    <label for=\"allow_out_payment\"/>\n                    <div class=\"d-flex gap-2\">\n                        <field name=\"allow_out_payment\" widget=\"boolean_toggle\" options=\"{''autosave'': False}\" readonly=\"not user_has_group_validate_bank_account\"/>\n                        <span class=\"d-flex gap-2 w-100\">\n                            <span invisible=\"allow_out_payment\" class=\"text-muted\">Untrusted</span>\n                            <span invisible=\"not allow_out_payment\" class=\"text-success\">Trusted</span>\n                        </span>\n                    </div>\n                    <div invisible=\"allow_out_payment\" colspan=\"2\">\n                        <field name=\"has_money_transfer_warning\" invisible=\"1\"/>\n                        <div invisible=\"not has_money_transfer_warning\" class=\"mb-1\">\n                            <span class=\"text-danger\">High risk</span>: <field name=\"money_transfer_service\" nolabel=\"1\" class=\"oe_inline\"/> is a money transfer service and not a bank.\n                            Double check if the account can be trusted by calling the vendor.<br/>\n                            <a target=\"_blank\" href=\"https://www.odoo.com/documentation/17.0/applications/finance/accounting/payables/pay/trusted_accounts.html\">Check why.</a>\n                        </div>\n                        <field name=\"has_iban_warning\" invisible=\"1\"/>\n                        <div invisible=\"not has_iban_warning\">\n                            <span class=\"text-warning\">Medium risk</span>: Iban <field name=\"sanitized_acc_number\" nolabel=\"1\" class=\"oe_inline fw-bold\"/>\n                            is not from the same country as the partner (<field name=\"partner_country_name\" nolabel=\"1\" class=\"oe_inline\"/>).<br/>\n                            <a target=\"_blank\" href=\"https://www.odoo.com/documentation/17.0/applications/finance/accounting/payables/pay/trusted_accounts.html\">Check why it''s risky.</a>\n                        </div>\n                    </div>\n                </xpath>\n            </data>"}', '<?xml version="1.0"?>
<data><xpath expr="//form[@name=''bank_account_form'']/sheet[1]" position="after">
                    <div class="oe_chatter">
                        <field name="message_follower_ids"/>
                        <field name="message_ids"/>
                        <field name="activity_ids"/>
                    </div>
                </xpath>

                <xpath expr="//field[@name=''acc_number'']" position="attributes">
                    <attribute name="readonly">lock_trust_fields</attribute>
                    <attribute name="force_save">1</attribute>
                </xpath>

                <xpath expr="//field[@name=''partner_id'']" position="attributes">
                    <attribute name="readonly">lock_trust_fields</attribute>
                    <attribute name="force_save">1</attribute>
                </xpath>

                <xpath expr="//field[@name=''allow_out_payment'']" position="replace">
                    <field name="user_has_group_validate_bank_account" invisible="1"/>
                    <field name="lock_trust_fields" invisible="1"/>
                    <label for="allow_out_payment"/>
                    <div class="d-flex gap-2">
                        <field name="allow_out_payment" widget="boolean_toggle" options="{''autosave'': False}" readonly="not user_has_group_validate_bank_account"/>
                        <span class="d-flex gap-2 w-100">
                            <span invisible="allow_out_payment" class="text-muted">Untrusted</span>
                            <span invisible="not allow_out_payment" class="text-success">Trusted</span>
                        </span>
                    </div>
                    <div invisible="allow_out_payment" colspan="2">
                        <field name="has_money_transfer_warning" invisible="1"/>
                        <div invisible="not has_money_transfer_warning" class="mb-1">
                            <span class="text-danger">High risk</span>: <field name="money_transfer_service" nolabel="1" class="oe_inline"/> is a money transfer service and not a bank.
                            Double check if the account can be trusted by calling the vendor.<br/>
                            <a target="_blank" href="https://www.odoo.com/documentation/17.0/applications/finance/accounting/payables/pay/trusted_accounts.html">Check why.</a>
                        </div>
                        <field name="has_iban_warning" invisible="1"/>
                        <div invisible="not has_iban_warning">
                            <span class="text-warning">Medium risk</span>: Iban <field name="sanitized_acc_number" nolabel="1" class="oe_inline fw-bold"/>
                            is not from the same country as the partner (<field name="partner_country_name" nolabel="1" class="oe_inline"/>).<br/>
                            <a target="_blank" href="https://www.odoo.com/documentation/17.0/applications/finance/accounting/payables/pay/trusted_accounts.html">Check why it''s risky.</a>
                        </div>
                    </div>
                </xpath>
            </data>', false, true, '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295', false);
INSERT INTO public.ir_ui_view VALUES (726, 16, 140, 1, 1, 'res.partner.bank.search.inherit', 'res.partner.bank', NULL, 'search', 'account/views/res_partner_bank_views.xml', 'extension', '{"en_US": "<xpath expr=\"//search\" position=\"inside\">\n                        <filter string=\"Trusted\" name=\"trusted\" domain=\"[(''allow_out_payment'', ''='', True)]\"/>\n                        <filter string=\"Untrusted\" name=\"untrusted\" domain=\"[(''allow_out_payment'', ''='', False)]\"/>\n                        <filter string=\"To validate\" name=\"to_validate\" domain=\"[(''allow_out_payment'', ''='', False), (''related_moves'', ''!='', False)]\"/>\n                        <separator/>\n                        <filter string=\"Customers\" name=\"customer\" domain=\"[(''partner_customer_rank'',''&gt;'', 0)]\"/>\n                        <filter string=\"Vendors\" name=\"supplier\" domain=\"[(''partner_supplier_rank'',''&gt;'', 0)]\"/>\n                        <separator/>\n                        <filter string=\"Phishing risk: High\" name=\"high_phishing_risk\" domain=\"[(''has_money_transfer_warning'', ''!='', False)]\"/>\n                        <filter string=\"Phishing risk: Medium\" name=\"medium_phishing_risk\" domain=\"[(''has_iban_warning'', ''!='', False)]\"/>\n                        <separator/>\n                        <filter string=\"Created On\" name=\"create_date\" date=\"create_date\"/>\n                        <group expand=\"1\" string=\"Group By\">\n                            <filter string=\"Created On\" name=\"groupby_create_date\" context=\"{''group_by'': ''create_date''}\"/>\n                            <filter string=\"Created By\" name=\"groupby_create_by\" context=\"{''group_by'': ''create_uid''}\"/>\n                        </group>\n                </xpath>"}', '<?xml version="1.0"?>
<xpath expr="//search" position="inside">
                        <filter string="Trusted" name="trusted" domain="[(''allow_out_payment'', ''='', True)]"/>
                        <filter string="Untrusted" name="untrusted" domain="[(''allow_out_payment'', ''='', False)]"/>
                        <filter string="To validate" name="to_validate" domain="[(''allow_out_payment'', ''='', False), (''related_moves'', ''!='', False)]"/>
                        <separator/>
                        <filter string="Customers" name="customer" domain="[(''partner_customer_rank'',''&gt;'', 0)]"/>
                        <filter string="Vendors" name="supplier" domain="[(''partner_supplier_rank'',''&gt;'', 0)]"/>
                        <separator/>
                        <filter string="Phishing risk: High" name="high_phishing_risk" domain="[(''has_money_transfer_warning'', ''!='', False)]"/>
                        <filter string="Phishing risk: Medium" name="medium_phishing_risk" domain="[(''has_iban_warning'', ''!='', False)]"/>
                        <separator/>
                        <filter string="Created On" name="create_date" date="create_date"/>
                        <group expand="1" string="Group By">
                            <filter string="Created On" name="groupby_create_date" context="{''group_by'': ''create_date''}"/>
                            <filter string="Created By" name="groupby_create_by" context="{''group_by'': ''create_uid''}"/>
                        </group>
                </xpath>
            ', false, true, '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295', false);
INSERT INTO public.ir_ui_view VALUES (737, 16, NULL, 1, 1, 'product.template.tree', 'product.template', NULL, 'tree', 'account/views/product_view.xml', 'primary', '{"en_US": "<tree string=\"Products\" sample=\"1\">\n                    <field name=\"default_code\"/>\n                    <field name=\"name\"/>\n                    <field name=\"list_price\"/>\n                    <field name=\"taxes_id\" widget=\"many2many_tags\"/>\n                    <field name=\"supplier_taxes_id\" widget=\"many2many_tags\"/>\n                    <field name=\"activity_exception_decoration\" widget=\"activity_exception\"/>\n                </tree>"}', '<?xml version="1.0"?>
<tree string="Products" sample="1">
                    <field name="default_code"/>
                    <field name="name"/>
                    <field name="list_price"/>
                    <field name="taxes_id" widget="many2many_tags"/>
                    <field name="supplier_taxes_id" widget="many2many_tags"/>
                    <field name="activity_exception_decoration" widget="activity_exception"/>
                </tree>
            ', false, true, '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295', false);
INSERT INTO public.ir_ui_view VALUES (727, 16, 204, 1, 1, 'report_statement_internal_layout', NULL, 'account.report_statement_internal_layout', 'qweb', 'account/views/report_statement.xml', 'primary', '{"en_US": "<data inherit_id=\"web.internal_layout\" primary=\"True\">\n            <xpath expr=\"//div[hasclass(''col-3'')]\" position=\"attributes\">\n                <attribute name=\"class\">col-4</attribute>\n            </xpath>\n            <xpath expr=\"//div[hasclass(''col-2'') and hasclass(''offset-2'') and hasclass(''text-center'')]\" position=\"attributes\">\n                <attribute name=\"class\">col-4 text-center</attribute>\n            </xpath>\n            <xpath expr=\"//div[hasclass(''col-2'') and hasclass(''offset-3'') and hasclass(''text-end'')]\" position=\"attributes\">\n                <attribute name=\"class\">col-2 offset-2 text-end</attribute>\n            </xpath>\n        <xpath expr=\".\" position=\"attributes\"><attribute name=\"t-name\">account.report_statement_internal_layout</attribute></xpath></data>"}', '<?xml version="1.0"?>
<data inherit_id="web.internal_layout" primary="True">
            <xpath expr="//div[hasclass(''col-3'')]" position="attributes">
                <attribute name="class">col-4</attribute>
            </xpath>
            <xpath expr="//div[hasclass(''col-2'') and hasclass(''offset-2'') and hasclass(''text-center'')]" position="attributes">
                <attribute name="class">col-4 text-center</attribute>
            </xpath>
            <xpath expr="//div[hasclass(''col-2'') and hasclass(''offset-3'') and hasclass(''text-end'')]" position="attributes">
                <attribute name="class">col-2 offset-2 text-end</attribute>
            </xpath>
        <xpath expr="." position="attributes"><attribute name="t-name">account.report_statement_internal_layout</attribute></xpath></data>

        ', false, true, '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295', false);
INSERT INTO public.ir_ui_view VALUES (728, 16, NULL, 1, 1, 'report_statement', NULL, 'account.report_statement', 'qweb', 'account/views/report_statement.xml', 'primary', '{"en_US": "<t t-name=\"account.report_statement\">\n            <t t-call=\"web.html_container\">\n                <t t-foreach=\"docs\" t-as=\"o\">\n                    <t t-call=\"account.report_statement_internal_layout\">\n                        <div class=\"page\">\n                        <div class=\"oe_structure\"/>\n                            <div class=\"border border-top-0 border-end-0 border-start-0 border-info\">\n                                <div class=\"row\">\n                                    <div class=\"col-12\">\n                                        <h4 class=\"text-center w-100\">\n                                            <strong>\n                                                <span t-if=\"o.journal_id.type == ''bank''\">Bank Statement</span>\n                                                <span t-else=\"\">Cash Statement</span>\n                                            </strong>\n                                        </h4>\n                                    </div>\n                                </div>\n                            </div>\n\n                            <div class=\"oe_structure\"/>\n                            <div class=\"pt-2 pb-2\">\n                                <div class=\"row\">\n                                    <div class=\"col-7\">\n                                        <h5>\n                                            <strong>\n                                                <span t-out=\"o.journal_id.display_name\">Journal Name</span>\n                                                <span t-if=\"o.journal_id.bank_account_id\">\n                                                    - <span t-out=\"o.journal_id.bank_account_id.display_name\">Bank Account Name</span>\n                                                </span>\n                                                <span t-if=\"o.journal_id.code\">\n                                                    - <span t-out=\"o.journal_id.code\">12345</span>\n                                                </span>\n                                            </strong>\n                                        </h5>\n                                    </div>\n                                    <div class=\"col-5\" style=\"text-align: end;\">\n                                        <h5>\n                                            <strong>\n                                                <span t-if=\"o.name\">\n                                                    <span t-field=\"o.name\">Statement Name</span>\n                                                - </span>\n                                                <span t-field=\"o.date\">2023-08-15</span>\n                                            </strong>\n                                        </h5>\n                                    </div>\n                                </div>\n                            </div>\n\n                            <div class=\"oe_structure\"/>\n                            <table class=\"table table-lg m-0 table-borderless border border-end-0 border-start-0 border-info\">\n                                <tbody>\n                                    <tr>\n                                        <td class=\"pt-2 pb-2 ps-0 pe-0\">\n                                            <table class=\"table table-borderless m-0\">\n                                                <tr>\n                                                    <td class=\"p-0 w-25\">\n                                                        <strong>Starting Balance</strong>\n                                                    </td>\n                                                    <td class=\"p-0\">\n                                                        <strong>\n                                                            <span t-out=\"o.line_ids and o.line_ids.sorted(lambda line: line.date)[0].date\" t-options=\"{&quot;widget&quot;: &quot;date&quot;}\">2023-08-11</span>\n                                                        </strong>\n                                                    </td>\n                                                    <td class=\"text-end p-0\">\n                                                        <strong>\n                                                            <span t-field=\"o.balance_start\">1000.0</span>\n                                                        </strong>\n                                                    </td>\n                                                </tr>\n                                                <tr>\n                                                    <td class=\"p-0 w-25\">\n                                                        <strong>Ending Balance</strong>\n                                                    </td>\n                                                    <td class=\"p-0\">\n                                                        <strong>\n                                                            <span t-out=\"o.line_ids and o.line_ids.sorted(lambda line: line.date)[-1].date\" t-options=\"{&quot;widget&quot;: &quot;date&quot;}\">2023-08-31</span>\n                                                        </strong>\n                                                    </td>\n                                                    <td class=\"text-end p-0\">\n                                                        <strong>\n                                                            <span t-field=\"o.balance_end_real\">1500.0</span>\n                                                        </strong>\n                                                    </td>\n                                                </tr>\n                                            </table>\n                                        </td>\n                                    </tr>\n                                </tbody>\n                            </table>\n\n                            <div class=\"oe_structure\"/>\n                            <table class=\"table table-borderless m-0\">\n                                <tbody>\n                                    <tr t-foreach=\"o.line_ids\" t-as=\"line\">\n                                        <td class=\"w-25 py-1\">\n                                            <span class=\"d-block fw-bold\" t-field=\"line.date\">2023-08-11</span>\n                                        </td>\n                                        <td class=\"py-1\">\n                                            <span class=\"d-block fw-bold\" t-if=\"line.partner_id\">\n                                                <span t-out=\"line.partner_id.name\">Marc Demo</span> <span t-if=\"line.partner_bank_id and line.partner_bank_id.partner_id != line.partner_id\">(<span t-out=\"line.partner_bank_id.partner_id.name\">Bank of odoo</span>)</span>\n                                            </span>\n                                            <span class=\"d-block\" t-if=\"line.partner_bank_id or line.account_number\" t-out=\"line.account_number or line.partner_bank_id.acc_number\">534677881234</span>\n                                            <span class=\"d-block\" t-if=\"line.payment_ref\" t-field=\"line.payment_ref\">Payment Reference</span>\n                                        </td>\n                                        <td class=\"text-end py-1\">\n                                            <span t-att-class=\"''d-block fw-bold'' + ('' text-danger'' if line.amount &lt; 0 else '''')\" t-field=\"line.amount\">100.0</span>\n                                        </td>\n                                    </tr>\n                                </tbody>\n                            </table>\n                            <div class=\"oe_structure\"/>\n                        </div>\n                    </t>\n                </t>\n            </t>\n        </t>"}', '<?xml version="1.0"?>
<t t-name="account.report_statement">
            <t t-call="web.html_container">
                <t t-foreach="docs" t-as="o">
                    <t t-call="account.report_statement_internal_layout">
                        <div class="page">
                        <div class="oe_structure"/>
                            <div class="border border-top-0 border-end-0 border-start-0 border-info">
                                <div class="row">
                                    <div class="col-12">
                                        <h4 class="text-center w-100">
                                            <strong>
                                                <span t-if="o.journal_id.type == ''bank''">Bank Statement</span>
                                                <span t-else="">Cash Statement</span>
                                            </strong>
                                        </h4>
                                    </div>
                                </div>
                            </div>

                            <div class="oe_structure"/>
                            <div class="pt-2 pb-2">
                                <div class="row">
                                    <div class="col-7">
                                        <h5>
                                            <strong>
                                                <span t-out="o.journal_id.display_name">Journal Name</span>
                                                <span t-if="o.journal_id.bank_account_id">
                                                    - <span t-out="o.journal_id.bank_account_id.display_name">Bank Account Name</span>
                                                </span>
                                                <span t-if="o.journal_id.code">
                                                    - <span t-out="o.journal_id.code">12345</span>
                                                </span>
                                            </strong>
                                        </h5>
                                    </div>
                                    <div class="col-5" style="text-align: end;">
                                        <h5>
                                            <strong>
                                                <span t-if="o.name">
                                                    <span t-field="o.name">Statement Name</span>
                                                - </span>
                                                <span t-field="o.date">2023-08-15</span>
                                            </strong>
                                        </h5>
                                    </div>
                                </div>
                            </div>

                            <div class="oe_structure"/>
                            <table class="table table-lg m-0 table-borderless border border-end-0 border-start-0 border-info">
                                <tbody>
                                    <tr>
                                        <td class="pt-2 pb-2 ps-0 pe-0">
                                            <table class="table table-borderless m-0">
                                                <tr>
                                                    <td class="p-0 w-25">
                                                        <strong>Starting Balance</strong>
                                                    </td>
                                                    <td class="p-0">
                                                        <strong>
                                                            <span t-out="o.line_ids and o.line_ids.sorted(lambda line: line.date)[0].date" t-options="{&quot;widget&quot;: &quot;date&quot;}">2023-08-11</span>
                                                        </strong>
                                                    </td>
                                                    <td class="text-end p-0">
                                                        <strong>
                                                            <span t-field="o.balance_start">1000.0</span>
                                                        </strong>
                                                    </td>
                                                </tr>
                                                <tr>
                                                    <td class="p-0 w-25">
                                                        <strong>Ending Balance</strong>
                                                    </td>
                                                    <td class="p-0">
                                                        <strong>
                                                            <span t-out="o.line_ids and o.line_ids.sorted(lambda line: line.date)[-1].date" t-options="{&quot;widget&quot;: &quot;date&quot;}">2023-08-31</span>
                                                        </strong>
                                                    </td>
                                                    <td class="text-end p-0">
                                                        <strong>
                                                            <span t-field="o.balance_end_real">1500.0</span>
                                                        </strong>
                                                    </td>
                                                </tr>
                                            </table>
                                        </td>
                                    </tr>
                                </tbody>
                            </table>

                            <div class="oe_structure"/>
                            <table class="table table-borderless m-0">
                                <tbody>
                                    <tr t-foreach="o.line_ids" t-as="line">
                                        <td class="w-25 py-1">
                                            <span class="d-block fw-bold" t-field="line.date">2023-08-11</span>
                                        </td>
                                        <td class="py-1">
                                            <span class="d-block fw-bold" t-if="line.partner_id">
                                                <span t-out="line.partner_id.name">Marc Demo</span> <span t-if="line.partner_bank_id and line.partner_bank_id.partner_id != line.partner_id">(<span t-out="line.partner_bank_id.partner_id.name">Bank of odoo</span>)</span>
                                            </span>
                                            <span class="d-block" t-if="line.partner_bank_id or line.account_number" t-out="line.account_number or line.partner_bank_id.acc_number">534677881234</span>
                                            <span class="d-block" t-if="line.payment_ref" t-field="line.payment_ref">Payment Reference</span>
                                        </td>
                                        <td class="text-end py-1">
                                            <span t-att-class="''d-block fw-bold'' + ('' text-danger'' if line.amount &lt; 0 else '''')" t-field="line.amount">100.0</span>
                                        </td>
                                    </tr>
                                </tbody>
                            </table>
                            <div class="oe_structure"/>
                        </div>
                    </t>
                </t>
            </t>
        </t>
    ', false, true, '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295', false);
INSERT INTO public.ir_ui_view VALUES (729, 16, NULL, 1, 1, 'Account Terms and Conditions Setting Banner', NULL, 'account.account_terms_conditions_setting_banner', 'qweb', 'account/views/terms_template.xml', 'primary', '{"en_US": "<t name=\"Account Terms and Conditions Setting Banner\" t-name=\"account.account_terms_conditions_setting_banner\">\n        <div id=\"terms_conditions\" t-ignore=\"true\" class=\"text-center\">\n            <span>This is a preview of your Terms &amp; Conditions.</span>\n            <a t-att-href=\"backend_url\"><i class=\"oi oi-arrow-right me-1\"/>Back to settings</a>\n        </div>\n        <button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"alert\" aria-label=\"Close\"/>\n    </t>"}', '<?xml version="1.0"?>
