    </t>

    ', false, true, '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295', false);
INSERT INTO public.ir_ui_view VALUES (730, 16, NULL, 1, 1, 'Terms & Conditions', NULL, 'account.account_terms_conditions_page', 'qweb', 'account/views/terms_template.xml', 'primary', '{"en_US": "<t name=\"Terms &amp; Conditions\" t-name=\"account.account_terms_conditions_page\">\n        <t t-call=\"web.frontend_layout\">\n            <t t-set=\"o_portal_fullwidth_alert\" groups=\"account.group_account_manager\">\n                <t t-call=\"account.account_terms_conditions_setting_banner\">\n                    <t t-set=\"backend_url\" t-value=\"''/web#action=account.action_open_settings&amp;model=res.config.settings''\"/>\n                </t>\n            </t>\n            <div class=\"oe_structure\" id=\"oe_structure_terms_conditions\"/>\n                <div class=\"container oe_website_terms_conditions\">\n                    <div id=\"o_terms_conditions\">\n                        <div t-field=\"company.invoice_terms_html\"/>\n                    </div>\n                </div>\n        </t>\n    </t>"}', '<?xml version="1.0"?>
<t name="Terms &amp; Conditions" t-name="account.account_terms_conditions_page">
