                <t t-call="account.account_terms_conditions_setting_banner">
                    <t t-set="backend_url" t-value="''/web#action=account.action_open_settings&amp;model=res.config.settings''"/>
                </t>
            </t>
            <div class="oe_structure" id="oe_structure_terms_conditions"/>
                <div class="container oe_website_terms_conditions">
                    <div id="o_terms_conditions">
                        <div t-field="company.invoice_terms_html"/>
                    </div>
                </div>
        </t>
    </t>

    ', false, true, '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295', false);
INSERT INTO public.ir_ui_view VALUES (738, 5, 453, 1, 1, 'product.template.form.inherit', 'product.template', NULL, 'form', 'account/views/product_view.xml', 'extension', '{"en_US": "<data><xpath expr=\"//page[@name=''purchase'']\" position=\"attributes\">\n                    <attribute name=\"invisible\" remove=\"1\" separator=\" or \"/>\n                </xpath>\n                <xpath expr=\"//field[@name=''company_id'']\" position=\"after\">\n                    <field name=\"fiscal_country_codes\" invisible=\"1\"/>\n                </xpath>\n                <page name=\"inventory\" position=\"after\">\n                    <page string=\"Accounting\" name=\"invoicing\" groups=\"account.group_account_readonly,account.group_account_invoice\">\n                        <group name=\"properties\" groups=\"account.group_account_readonly\">\n                            <group string=\"Receivables\">\n                                <field name=\"property_account_income_id\" groups=\"account.group_account_readonly\"/>\n                            </group>\n                            <group string=\"Payables\" name=\"payables\">\n                                <field name=\"property_account_expense_id\" groups=\"account.group_account_readonly\"/>\n                            </group>\n                        </group>\n                        <group name=\"accounting\" groups=\"account.group_account_readonly,account.group_account_invoice\"/>\n                    </page>\n                </page>\n                <xpath expr=\"//div[@name=''pricing'']\" position=\"after\">\n                    <field name=\"taxes_id\" widget=\"many2many_tags\" context=\"{''default_type_tax_use'':''sale'', ''search_default_sale'': 1, ''search_default_service'': type == ''service'', ''search_default_goods'': type == ''consu''}\"/>\n                </xpath>\n                <xpath expr=\"//div[@name=''pricing'']\" position=\"inside\">\n                    <span class=\"ms-2\"/><field name=\"tax_string\"/>\n                </xpath>\n                <group name=\"bill\" position=\"inside\">\n                    <field name=\"supplier_taxes_id\" widget=\"many2many_tags\" context=\"{''default_type_tax_use'':''purchase'', ''search_default_purchase'': 1, ''search_default_service'': type == ''service'', ''search_default_goods'': type == ''consu''}\"/>\n                </group>\n            </data>"}', '<?xml version="1.0"?>
<data><xpath expr="//page[@name=''purchase'']" position="attributes">
                    <attribute name="invisible" remove="1" separator=" or "/>
                </xpath>
                <xpath expr="//field[@name=''company_id'']" position="after">
                    <field name="fiscal_country_codes" invisible="1"/>
                </xpath>
                <page name="inventory" position="after">
                    <page string="Accounting" name="invoicing" groups="account.group_account_readonly,account.group_account_invoice">
                        <group name="properties" groups="account.group_account_readonly">
                            <group string="Receivables">
                                <field name="property_account_income_id" groups="account.group_account_readonly"/>
                            </group>
                            <group string="Payables" name="payables">
                                <field name="property_account_expense_id" groups="account.group_account_readonly"/>
                            </group>
                        </group>
                        <group name="accounting" groups="account.group_account_readonly,account.group_account_invoice"/>
                    </page>
                </page>
                <xpath expr="//div[@name=''pricing'']" position="after">
                    <field name="taxes_id" widget="many2many_tags" context="{''default_type_tax_use'':''sale'', ''search_default_sale'': 1, ''search_default_service'': type == ''service'', ''search_default_goods'': type == ''consu''}"/>
                </xpath>
                <xpath expr="//div[@name=''pricing'']" position="inside">
                    <span class="ms-2"/><field name="tax_string"/>
                </xpath>
                <group name="bill" position="inside">
                    <field name="supplier_taxes_id" widget="many2many_tags" context="{''default_type_tax_use'':''purchase'', ''search_default_purchase'': 1, ''search_default_service'': type == ''service'', ''search_default_goods'': type == ''consu''}"/>
                </group>
            </data>', false, true, '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295', false);
INSERT INTO public.ir_ui_view VALUES (731, 16, NULL, 1, 1, 'account_default_terms_and_conditions', NULL, 'account.account_default_terms_and_conditions', 'qweb', 'account/views/terms_template.xml', 'primary', '{"en_US": "<t t-name=\"account.account_default_terms_and_conditions\">\n        <div>\n            <h1>STANDARD TERMS AND CONDITIONS OF SALE</h1>\n            <p>You should update this document to reflect your T&amp;C.</p>\n            <p>Below text serves as a suggestion and doesn’t engage Odoo S.A. responsibility.</p>\n            <ol>\n                <li>\n                    The client explicitly waives its own standard terms and conditions, even if these were drawn up after these standard terms and conditions of sale. In order to be valid, any derogation must be expressly agreed to in advance in writing.\n                </li>\n                <li>\n                    Our invoices are payable within 21 working days, unless another payment timeframe is indicated on either the invoice or the order. In the event of non-payment by the due date, <t t-out=\"company_name\"/> reserves the right to request a fixed interest payment amounting to 10% of the sum remaining due. <t t-out=\"company_name\"/> will be authorized to suspend any provision of services without prior warning in the event of late payment.\n                </li>\n                <li>\n                    If a payment is still outstanding more than sixty (60) days after the due payment date, <t t-out=\"company_name\"/> reserves the right to call on the services of a debt recovery company. All legal expenses will be payable by the client.\n                </li>\n                <li>\n                    Certain countries apply withholding at source on the amount of invoices, in accordance with their internal legislation. Any withholding at source will be paid by the client to the tax authorities. Under no circumstances can <t t-out=\"company_name\"/> become involved in costs related to a country''s legislation. The amount of the invoice will therefore be due to <t t-out=\"company_name\"/> in its entirety and does not include any costs relating to the legislation of the country in which the client is located.\n                </li>\n                <li>\n                    <t t-out=\"company_name\"/> undertakes to do its best to supply performant services in due time in accordance with the agreed timeframes. However, none of its obligations can be considered as being an obligation to achieve results. <t t-out=\"company_name\"/> cannot under any circumstances, be required by the client to appear as a third party in the context of any claim for damages filed against the client by an end consumer.\n                </li>\n                <li>\n                    In order for it to be admissible, <t t-out=\"company_name\"/> must be notified of any claim by means of a letter sent by recorded delivery to its registered office within 8 days of the delivery of the goods or the provision of the services.\n                </li>\n                <li>\n                    All our contractual relations will be governed exclusively by <t t-out=\"company_country\"/> law.\n                </li>\n            </ol>\n        </div>\n    </t>"}', '<?xml version="1.0"?>
<t t-name="account.account_default_terms_and_conditions">
        <div>
            <h1>STANDARD TERMS AND CONDITIONS OF SALE</h1>
            <p>You should update this document to reflect your T&amp;C.</p>
            <p>Below text serves as a suggestion and doesn’t engage Odoo S.A. responsibility.</p>
            <ol>
                <li>
                    The client explicitly waives its own standard terms and conditions, even if these were drawn up after these standard terms and conditions of sale. In order to be valid, any derogation must be expressly agreed to in advance in writing.
                </li>
                <li>
                    Our invoices are payable within 21 working days, unless another payment timeframe is indicated on either the invoice or the order. In the event of non-payment by the due date, <t t-out="company_name"/> reserves the right to request a fixed interest payment amounting to 10% of the sum remaining due. <t t-out="company_name"/> will be authorized to suspend any provision of services without prior warning in the event of late payment.
                </li>
                <li>
                    If a payment is still outstanding more than sixty (60) days after the due payment date, <t t-out="company_name"/> reserves the right to call on the services of a debt recovery company. All legal expenses will be payable by the client.
                </li>
                <li>
                    Certain countries apply withholding at source on the amount of invoices, in accordance with their internal legislation. Any withholding at source will be paid by the client to the tax authorities. Under no circumstances can <t t-out="company_name"/> become involved in costs related to a country''s legislation. The amount of the invoice will therefore be due to <t t-out="company_name"/> in its entirety and does not include any costs relating to the legislation of the country in which the client is located.
                </li>
                <li>
                    <t t-out="company_name"/> undertakes to do its best to supply performant services in due time in accordance with the agreed timeframes. However, none of its obligations can be considered as being an obligation to achieve results. <t t-out="company_name"/> cannot under any circumstances, be required by the client to appear as a third party in the context of any claim for damages filed against the client by an end consumer.
                </li>
                <li>
                    In order for it to be admissible, <t t-out="company_name"/> must be notified of any claim by means of a letter sent by recorded delivery to its registered office within 8 days of the delivery of the goods or the provision of the services.
                </li>
                <li>
                    All our contractual relations will be governed exclusively by <t t-out="company_country"/> law.
                </li>
            </ol>
        </div>
    </t>

', false, true, '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295', false);
INSERT INTO public.ir_ui_view VALUES (732, 16, NULL, 1, 1, 'Post Journal Entries', 'validate.account.move', NULL, 'form', 'account/wizard/account_validate_move_view.xml', 'primary', '{"en_US": "<form string=\"Post Journal Entries\">\n                    <group>\n                        <field name=\"force_post\"/>\n                    </group>\n                    <span class=\"o_form_label\">All selected journal entries will be validated and posted. You won''t be able to modify them afterwards.</span>\n                    <footer>\n                        <button string=\"Post Journal Entries\" name=\"validate_move\" type=\"object\" default_focus=\"1\" class=\"btn-primary\" data-hotkey=\"q\" context=\"{''validate_analytic'': True}\"/>\n                        <button string=\"Cancel\" class=\"btn-secondary\" special=\"cancel\" data-hotkey=\"x\"/>\n                    </footer>\n                </form>"}', '<?xml version="1.0"?>
<form string="Post Journal Entries">
                    <group>
                        <field name="force_post"/>
                    </group>
                    <span class="o_form_label">All selected journal entries will be validated and posted. You won''t be able to modify them afterwards.</span>
                    <footer>
