                        <button string="Cancel" class="btn-secondary" special="cancel" data-hotkey="x"/>
                    </footer>
                </form>
            ', false, true, '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295', false);
INSERT INTO public.ir_ui_view VALUES (733, 16, 114, 1, 1, 'res.company.form.inherit.account', 'res.company', NULL, 'form', 'account/views/res_company_views.xml', 'extension', '{"en_US": "<data><xpath expr=\"//field[@name=''country_id'']\" position=\"after\">\n                <field name=\"country_code\" invisible=\"1\"/>\n                <field name=\"account_enabled_tax_country_ids\" invisible=\"1\"/>\n            </xpath>\n            <xpath expr=\"//sheet\" position=\"after\">\n                <div class=\"oe_chatter\">\n                    <field name=\"message_follower_ids\" groups=\"base.group_user\"/>\n                    <field name=\"message_ids\"/>\n                </div>\n            </xpath>\n        </data>"}', '<?xml version="1.0"?>
