INSERT INTO public.ir_ui_view VALUES (734, 1000, NULL, 1, 1, 'res.company.view.form.terms', 'res.company', NULL, 'form', 'account/views/res_company_views.xml', 'primary', '{"en_US": "<form>\n                <field name=\"invoice_terms_html\" class=\"oe_account_terms\" nolabel=\"1\"/>\n                <footer>\n                    <button string=\"Save\" special=\"save\" class=\"btn-primary\"/>\n                    <button string=\"Discard\" class=\"btn-secondary\" special=\"cancel\"/>\n                </footer>\n            </form>"}', '<?xml version="1.0"?>
