INSERT INTO public.ir_ui_view VALUES (735, 1000, 114, 1, 1, 'res.company.form.view.onboarding', 'res.company', NULL, 'form', 'account/views/res_company_views.xml', 'primary', '{"en_US": "<data><xpath expr=\"//group[@name=''social_media'']\" position=\"replace\"/>\n            <form position=\"attributes\">\n                <attribute name=\"js_class\">company_onboarding_form</attribute>\n            </form>\n        </data>"}', '<?xml version="1.0"?>
