INSERT INTO public.ir_ui_view VALUES (741, 9, 408, 1, 1, 'account.analytic.account.form.inherit', 'account.analytic.account', NULL, 'form', 'account/views/account_analytic_account_views.xml', 'extension', '{"en_US": "<div name=\"button_box\" position=\"inside\">\n                    <button class=\"oe_stat_button\" type=\"object\" name=\"action_view_invoice\" icon=\"fa-pencil-square-o\" invisible=\"invoice_count == 0\">\n                        <field string=\"Customer Invoices\" name=\"invoice_count\" widget=\"statinfo\"/>\n                    </button>\n                    <button class=\"oe_stat_button\" type=\"object\" name=\"action_view_vendor_bill\" icon=\"fa-file-text-o\" invisible=\"vendor_bill_count == 0\">\n                        <field string=\"Vendor Bills\" name=\"vendor_bill_count\" widget=\"statinfo\"/>\n                    </button>\n                </div>"}', '<?xml version="1.0"?>
