INSERT INTO public.ir_ui_view VALUES (742, 16, 409, 1, 1, 'account.analytic.account.list.inherit', 'account.analytic.account', NULL, 'tree', 'account/views/account_analytic_account_views.xml', 'extension', '{"en_US": "<data><field name=\"debit\" position=\"attributes\">\n                    <attribute name=\"column_invisible\">False</attribute>\n                </field>\n                <field name=\"credit\" position=\"attributes\">\n                    <attribute name=\"column_invisible\">False</attribute>\n                </field>\n            </data>"}', '<?xml version="1.0"?>
