INSERT INTO public.ir_ui_view VALUES (743, 16, 415, 1, 1, 'account.analytic.distribution.model.inherit.tree', 'account.analytic.distribution.model', NULL, 'tree', 'account/views/account_analytic_distribution_model_views.xml', 'extension', '{"en_US": "<data>\n                    <xpath expr=\"//field[@name=''partner_id'']\" position=\"before\">\n                            <field name=\"account_prefix\" optional=\"show\"/>\n                    </xpath>\n                    <xpath expr=\"//field[@name=''company_id'']\" position=\"before\">\n                            <field name=\"product_id\" optional=\"show\"/>\n                            <field name=\"product_categ_id\" optional=\"hide\"/>\n                    </xpath>\n                </data>"}', '<?xml version="1.0"?>
