INSERT INTO public.ir_ui_view VALUES (855, 16, 760, 1, 1, 'account.invoice.report.search.inherit', 'account.invoice.report', NULL, 'search', 'sale/report/account_invoice_report_views.xml', 'extension', '{"en_US": "<data><filter name=\"user\" position=\"after\">\n                <filter string=\"Sales Team\" name=\"sales_channel\" context=\"{''group_by'':''team_id''}\"/>\n            </filter>\n            <field name=\"invoice_user_id\" position=\"after\">\n                <field name=\"team_id\"/>\n            </field>\n        </data>"}', '<?xml version="1.0"?>
