INSERT INTO public.ir_ui_view VALUES (745, 16, 404, 1, 1, 'account.analytic.line.form.inherit.account', 'account.analytic.line', NULL, 'form', 'account/views/account_analytic_line_views.xml', 'extension', '{"en_US": "<data>\n                    <xpath expr=\"//field[@name=''amount'']\" position=\"after\">\n                        <field name=\"ref\"/>\n                        <field name=\"partner_id\"/>\n                    </xpath>\n                    <xpath expr=\"//field[@name=''product_uom_id'']\" position=\"before\">\n                        <field name=\"product_id\"/>\n                    </xpath>\n                    <group name=\"amount\" position=\"after\">\n                        <group/> <!-- put Accounting group under Amount group -->\n                        <group name=\"accounting\" string=\"Accounting\">\n                            <field name=\"move_line_id\" options=\"{''no_create'': True}\" widget=\"line_open_move_widget\"/>\n                            <field name=\"general_account_id\" readonly=\"move_line_id\"/>\n                        </group>\n                    </group>\n                </data>"}', '<?xml version="1.0"?>
<data>
                    <xpath expr="//field[@name=''amount'']" position="after">
                        <field name="ref"/>
                        <field name="partner_id"/>
                    </xpath>
                    <xpath expr="//field[@name=''product_uom_id'']" position="before">
                        <field name="product_id"/>
                    </xpath>
                    <group name="amount" position="after">
                        <group/> <!-- put Accounting group under Amount group -->
                        <group name="accounting" string="Accounting">
                            <field name="move_line_id" options="{''no_create'': True}" widget="line_open_move_widget"/>
                            <field name="general_account_id" readonly="move_line_id"/>
                        </group>
                    </group>
                </data>
            ', false, true, '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295', false);
INSERT INTO public.ir_ui_view VALUES (746, 16, 402, 1, 1, 'account.analytic.line.tree.inherit.account', 'account.analytic.line', NULL, 'tree', 'account/views/account_analytic_line_views.xml', 'extension', '{"en_US": "<data>\n                    <xpath expr=\"//field[@name=''account_id'']\" position=\"after\">\n                        <field name=\"ref\" column_invisible=\"context.get(''to_invoice'', False)\" optional=\"hide\"/>\n                        <field name=\"general_account_id\" optional=\"hide\"/>\n                        <field name=\"move_line_id\" widget=\"line_open_move_widget\" optional=\"hide\"/>\n                        <field name=\"product_id\" optional=\"hide\"/>\n                    </xpath>\n                </data>"}', '<?xml version="1.0"?>
<data>
