                        <field name="ref" column_invisible="context.get(''to_invoice'', False)" optional="hide"/>
                        <field name="general_account_id" optional="hide"/>
                        <field name="move_line_id" widget="line_open_move_widget" optional="hide"/>
                        <field name="product_id" optional="hide"/>
                    </xpath>
                </data>
            ', false, true, '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295', false);
INSERT INTO public.ir_ui_view VALUES (747, 16, 403, 1, 1, 'account.analytic.line.select.inherit.account', 'account.analytic.line', NULL, 'search', 'account/views/account_analytic_line_views.xml', 'primary', '{"en_US": "<data>\n                    <xpath expr=\"//field[@name=''date'']\" position=\"after\">\n                        <field name=\"auto_account_id\"/>\n                        <field name=\"account_id\"/>\n                        <field name=\"product_id\"/>\n                        <field name=\"general_account_id\"/>\n                        <field name=\"partner_id\" filter_domain=\"[(''partner_id'',''child_of'',self)]\"/>\n                    </xpath>\n                    <xpath expr=\"//group[@name=''groupby'']\" position=\"inside\">\n                        <separator/>\n                        <filter name=\"account_id\" context=\"{''group_by'': ''account_id''}\"/>\n                        <separator/>\n                        <filter string=\"Financial Account\" name=\"group_by_financial_account\" context=\"{''group_by'':''general_account_id''}\"/>\n                        <filter string=\"Category\" name=\"category\" context=\"{''group_by'': ''category''}\"/>\n                        <filter string=\"Product\" name=\"product\" context=\"{''group_by'':''product_id''}\"/>\n                        <filter string=\"Partner\" name=\"partner\" context=\"{''group_by'':''partner_id''}\"/>\n                    </xpath>\n                </data>"}', '<?xml version="1.0"?>
<data>
                    <xpath expr="//field[@name=''date'']" position="after">
                        <field name="auto_account_id"/>
                        <field name="account_id"/>
                        <field name="product_id"/>
                        <field name="general_account_id"/>
                        <field name="partner_id" filter_domain="[(''partner_id'',''child_of'',self)]"/>
                    </xpath>
                    <xpath expr="//group[@name=''groupby'']" position="inside">
                        <separator/>
                        <filter name="account_id" context="{''group_by'': ''account_id''}"/>
                        <separator/>
                        <filter string="Financial Account" name="group_by_financial_account" context="{''group_by'':''general_account_id''}"/>
                        <filter string="Category" name="category" context="{''group_by'': ''category''}"/>
                        <filter string="Product" name="product" context="{''group_by'':''product_id''}"/>
                        <filter string="Partner" name="partner" context="{''group_by'':''partner_id''}"/>
                    </xpath>
                </data>
            ', false, true, '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295', false);
INSERT INTO public.ir_ui_view VALUES (748, 16, 406, 1, 1, 'account.analytic.line.pivot', 'account.analytic.line', NULL, 'pivot', 'account/views/account_analytic_line_views.xml', 'extension', '{"en_US": "<field name=\"account_id\" position=\"after\">\n                    <field name=\"partner_id\" type=\"row\" invisible=\"1\"/>\n                </field>"}', '<?xml version="1.0"?>
<field name="account_id" position="after">
                    <field name="partner_id" type="row" invisible="1"/>
                </field>
            ', false, true, '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295', false);
INSERT INTO public.ir_ui_view VALUES (749, 16, NULL, 1, 1, 'report_invoice_document', NULL, 'account.report_invoice_document', 'qweb', 'account/views/report_invoice.xml', 'primary', '{"en_US": "<t t-name=\"account.report_invoice_document\">\n            <t t-call=\"web.external_layout\">\n                <t t-set=\"o\" t-value=\"o.with_context(lang=lang)\"/>\n                <t t-set=\"forced_vat\" t-value=\"o.fiscal_position_id.foreign_vat\"/> <!-- So that it appears in the footer of the report instead of the company VAT if it''s set -->\n                <div class=\"row\">\n                    <t t-if=\"o.partner_shipping_id and (o.partner_shipping_id != o.partner_id)\">\n                        <div class=\"col-6\">\n                            <t t-set=\"information_block\">\n                                <div groups=\"account.group_delivery_invoice_address\" name=\"shipping_address_block\">\n                                    <strong>Shipping Address:</strong>\n                                    <div t-field=\"o.partner_shipping_id\" t-options=\"{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;], &quot;no_marker&quot;: True}\"/>\n                                </div>\n                            </t>\n                        </div>\n                        <div class=\"col-6\" name=\"address_not_same_as_shipping\">\n                            <t t-set=\"address\">\n                                <address class=\"mb-0\" t-field=\"o.partner_id\" t-options=\"{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;], &quot;no_marker&quot;: True}\"/>\n                                <div t-if=\"o.partner_id.vat\" id=\"partner_vat_address_not_same_as_shipping\">\n                                    <t t-if=\"o.company_id.account_fiscal_country_id.vat_label\" t-out=\"o.company_id.account_fiscal_country_id.vat_label\" id=\"inv_tax_id_label\"/>\n                                    <t t-else=\"\">Tax ID</t>: <span t-field=\"o.partner_id.vat\"/>\n                                </div>\n                                <div t-if=\"o.partner_id.country_code == ''MA'' and o.partner_id.company_registry\">\n                                    ICE: <a t-field=\"o.partner_id.company_registry\"/>\n                                </div>\n                            </t>\n                        </div>\n                    </t>\n                    <t t-elif=\"o.partner_shipping_id and (o.partner_shipping_id == o.partner_id)\">\n                        <div class=\"offset-col-6 col-6\" name=\"address_same_as_shipping\">\n                            <t t-set=\"address\">\n                                <address class=\"mb-0\" t-field=\"o.partner_id\" t-options=\"{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;], &quot;no_marker&quot;: True}\"/>\n                                <div t-if=\"o.partner_id.vat\" id=\"partner_vat_address_same_as_shipping\">\n                                    <t t-if=\"o.company_id.account_fiscal_country_id.vat_label\" t-out=\"o.company_id.account_fiscal_country_id.vat_label\" id=\"inv_tax_id_label\"/>\n                                    <t t-else=\"\">Tax ID</t>: <span t-field=\"o.partner_id.vat\"/>\n                                </div>\n                                <div t-if=\"o.partner_id.country_code == ''MA'' and o.partner_id.company_registry\">\n                                    ICE: <a t-field=\"o.partner_id.company_registry\"/>\n                                </div>\n                            </t>\n                        </div>\n                    </t>\n                    <t t-else=\"\">\n                        <div class=\"offset-col-6 col-6\" name=\"no_shipping\">\n                            <t t-set=\"address\">\n                                <address class=\"mb-0\" t-field=\"o.partner_id\" t-options=\"{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;], &quot;no_marker&quot;: True}\"/>\n                                <div t-if=\"o.partner_id.vat\" id=\"partner_vat_no_shipping\">\n                                    <t t-if=\"o.company_id.account_fiscal_country_id.vat_label\" t-out=\"o.company_id.account_fiscal_country_id.vat_label\" id=\"inv_tax_id_label\"/>\n                                    <t t-else=\"\">Tax ID</t>: <span t-field=\"o.partner_id.vat\"/>\n                                </div>\n                                <div t-if=\"o.partner_id.country_code == ''MA'' and o.partner_id.company_registry\">\n                                    ICE: <a t-field=\"o.partner_id.company_registry\"/>\n                                </div>\n                            </t>\n                        </div>\n                    </t>\n                </div>\n                <div class=\"mt-5 clearfix\">\n                    <div class=\"page mb-4\">\n                        <h2>\n                            <span t-if=\"not proforma\"/>\n                            <span t-else=\"\">PROFORMA</span>\n                            <span t-if=\"o.move_type == ''out_invoice'' and o.state == ''posted''\">Invoice</span>\n                            <span t-elif=\"o.move_type == ''out_invoice'' and o.state == ''draft''\">Draft Invoice</span>\n                            <span t-elif=\"o.move_type == ''out_invoice'' and o.state == ''cancel''\">Cancelled Invoice</span>\n                            <span t-elif=\"o.move_type == ''out_refund'' and o.state == ''posted''\">Credit Note</span>\n                            <span t-elif=\"o.move_type == ''out_refund'' and o.state == ''draft''\">Draft Credit Note</span>\n                            <span t-elif=\"o.move_type == ''out_refund'' and o.state == ''cancel''\">Cancelled Credit Note</span>\n                            <span t-elif=\"o.move_type == ''in_refund''\">Vendor Credit Note</span>\n                            <span t-elif=\"o.move_type == ''in_invoice''\">Vendor Bill</span>\n                            <span t-if=\"o.name != ''/''\" t-field=\"o.name\">INV/2023/0001</span>\n                        </h2>\n                        <div class=\"oe_structure\"/>\n                        <div id=\"informations\" class=\"row mt-3 mb-1\">\n                            <div t-attf-class=\"#{''col-auto col-3 mw-100'' if report_type != ''html'' else ''col''} mb-2\" t-if=\"o.invoice_date\" name=\"invoice_date\">\n                                <t t-if=\"o.move_type == ''out_invoice''\"><strong>Invoice Date:</strong></t>\n                                <t t-elif=\"o.move_type == ''out_refund''\"><strong>Credit Note Date:</strong></t>\n                                <t t-elif=\"o.move_type == ''out_receipt''\"><strong>Receipt Date:</strong></t>\n                                <t t-else=\"\"><strong>Date:</strong></t><br/>\n                                <span t-field=\"o.invoice_date\">2023-09-12</span>\n                            </div>\n                            <div t-attf-class=\"#{''col-auto col-3 mw-100'' if report_type != ''html'' else ''col''} mb-2\" t-if=\"o.invoice_date_due and o.move_type == ''out_invoice'' and o.state == ''posted''\" name=\"due_date\">\n                                <strong>Due Date:</strong><br/>\n                                <span t-field=\"o.invoice_date_due\">2023-10-31</span>\n                            </div>\n                            <div t-attf-class=\"#{''col-auto col-3 mw-100'' if report_type != ''html'' else ''col''} mb-2\" t-if=\"o.delivery_date\" name=\"delivery_date\">\n                                <strong>Delivery Date:</strong><br/>\n                                <span t-field=\"o.delivery_date\">2023-09-25</span>\n                            </div>\n                            <div t-attf-class=\"#{''col-auto col-3 mw-100'' if report_type != ''html'' else ''col''} mb-2\" t-if=\"o.invoice_origin\" name=\"origin\">\n                                <strong>Source:</strong><br/>\n                                <span t-field=\"o.invoice_origin\">SO123</span>\n                            </div>\n                            <div t-attf-class=\"#{''col-auto col-3 mw-100'' if report_type != ''html'' else ''col''} mb-2\" t-if=\"o.partner_id.ref\" name=\"customer_code\">\n                                <strong>Customer Code:</strong><br/>\n                                <span t-field=\"o.partner_id.ref\"/>\n                            </div>\n                            <div t-attf-class=\"#{''col-auto col-3 mw-100'' if report_type != ''html'' else ''col''} mb-2\" t-if=\"o.ref\" name=\"reference\">\n                                <strong>Reference:</strong><br/>\n                                <span t-field=\"o.ref\">INV/2023/00001</span>\n                            </div>\n                            <div t-attf-class=\"#{''col-auto col-3 mw-100'' if report_type != ''html'' else ''col''} mb-2\" t-if=\"o.invoice_incoterm_id\" name=\"incoterm_id\">\n                                <strong>Incoterm:</strong><br/>\n                                <p t-if=\"o.incoterm_location\">\n                                    <span t-field=\"o.invoice_incoterm_id.code\"/> <br/>\n                                    <span t-field=\"o.incoterm_location\"/>\n                                </p>\n                                <span t-else=\"\" t-field=\"o.invoice_incoterm_id.code\" class=\"m-0\"/>\n                            </div>\n                        </div>\n\n                        <t t-set=\"display_discount\" t-value=\"any(l.discount for l in o.invoice_line_ids)\"/>\n                        <div class=\"oe_structure\"/>\n                        <t t-set=\"has_long_desc\" t-value=\"any(line.name and line.name.count(''\\n'') &gt; 30 for line in o.invoice_line_ids if line.name)\"/>\n                        <table class=\"table table-sm o_main_table table-borderless\" name=\"invoice_line_table\">\n                            <thead t-attf-style=\"#{has_long_desc and ''display: table-row-group;'' or ''''}\">\n                                <tr>\n                                    <th name=\"th_description\" class=\"text-start\"><span>Description</span></th>\n                                    <th name=\"th_quantity\" class=\"text-end\"><span>Quantity</span></th>\n                                    <th name=\"th_priceunit\" t-attf-class=\"text-end {{ ''d-none d-md-table-cell'' if report_type == ''html'' else '''' }}\"><span>Unit Price</span></th>\n                                    <th name=\"th_discount\" t-if=\"display_discount\" t-attf-class=\"text-end {{ ''d-none d-md-table-cell'' if report_type == ''html'' else '''' }}\">\n                                        <span>Disc.%</span>\n                                    </th>\n                                    <th name=\"th_taxes\" t-attf-class=\"text-end {{ ''d-none d-md-table-cell'' if report_type == ''html'' else '''' }}\"><span>Taxes</span></th>\n                                    <th name=\"th_subtotal\" class=\"text-end\">\n                                        <span>Amount</span>\n                                    </th>\n                                </tr>\n                            </thead>\n                            <tbody class=\"invoice_tbody\">\n                                <t t-set=\"current_subtotal\" t-value=\"0\"/>\n                                <t t-set=\"current_total\" t-value=\"0\"/>\n                                <t t-set=\"lines\" t-value=\"o.invoice_line_ids.sorted(key=lambda l: (-l.sequence, l.date, l.move_name, -l.id), reverse=True)\"/>\n\n                                <t t-foreach=\"lines\" t-as=\"line\">\n                                    <t t-set=\"current_subtotal\" t-value=\"current_subtotal + line.price_subtotal\"/>\n                                    <t t-set=\"current_total\" t-value=\"current_total + line.price_total\"/>\n\n                                    <tr t-att-class=\"''bg-200 fw-bold o_line_section'' if line.display_type == ''line_section'' else ''fst-italic o_line_note'' if line.display_type == ''line_note'' else ''''\">\n                                        <t t-if=\"line.display_type == ''product''\" name=\"account_invoice_line_accountable\">\n                                            <td name=\"account_invoice_line_name\"><span t-if=\"line.name\" t-field=\"line.name\" t-options=\"{''widget'': ''text''}\" dir=\"auto\">Bacon Burger</span></td>\n                                            <td name=\"td_quantity\" class=\"text-end\">\n                                                <span t-field=\"line.quantity\">3.00</span>\n                                                <span t-field=\"line.product_uom_id\" groups=\"uom.group_uom\">units</span>\n                                            </td>\n                                            <td name=\"td_price_unit\" t-attf-class=\"text-end {{ ''d-none d-md-table-cell'' if report_type == ''html'' else '''' }}\">\n                                                <span class=\"text-nowrap\" t-field=\"line.price_unit\">9.00</span>\n                                            </td>\n                                            <td name=\"td_discount\" t-if=\"display_discount\" t-attf-class=\"text-end {{ ''d-none d-md-table-cell'' if report_type == ''html'' else '''' }}\">\n                                                <span class=\"text-nowrap\" t-field=\"line.discount\">0</span>\n                                            </td>\n                                            <t t-set=\"taxes\" t-value=\"'', ''.join([(tax.invoice_label or tax.name) for tax in line.tax_ids])\"/>\n                                            <td name=\"td_taxes\" t-attf-class=\"text-end {{ ''d-none d-md-table-cell'' if report_type == ''html'' else '''' }} {{ ''text-nowrap'' if len(taxes) &lt; 10 else '''' }}\">\n                                                <span t-out=\"taxes\" id=\"line_tax_ids\">Tax 15%</span>\n                                            </td>\n                                            <td name=\"td_subtotal\" class=\"text-end o_price_total\">\n                                                <span class=\"text-nowrap\" t-field=\"line.price_subtotal\">27.00</span>\n                                            </td>\n                                        </t>\n                                        <t t-elif=\"line.display_type == ''line_section''\">\n                                            <td colspan=\"99\">\n                                                <span t-if=\"line.name\" t-field=\"line.name\" t-options=\"{''widget'': ''text''}\" dir=\"auto\">A section title</span>\n                                            </td>\n                                            <t t-set=\"current_section\" t-value=\"line\"/>\n                                            <t t-set=\"current_subtotal\" t-value=\"0\"/>\n                                        </t>\n                                        <t t-elif=\"line.display_type == ''line_note''\">\n                                            <td colspan=\"99\">\n                                                <span t-if=\"line.name\" t-field=\"line.name\" t-options=\"{''widget'': ''text''}\" dir=\"auto\">A note, whose content usually applies to the section or product above.</span>\n                                            </td>\n                                        </t>\n                                    </tr>\n\n                                    <t t-if=\"current_section and (line_last or lines[line_index+1].display_type == ''line_section'')\">\n                                        <tr class=\"is-subtotal text-end\">\n                                            <td colspan=\"99\">\n                                                <strong class=\"mr16\">Subtotal</strong>\n                                                <span t-out=\"current_subtotal\" t-options=\"{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: o.currency_id}\">31.05</span>\n                                            </td>\n                                        </tr>\n                                    </t>\n                                </t>\n                            </tbody>\n                        </table>\n                        <div>\n                            <div id=\"right-elements\" t-attf-class=\"#{''col-5'' if report_type != ''html'' else ''col-12 col-md-5''} ms-5 d-inline-block float-end\">\n                                <div id=\"total\" class=\"clearfix row\">\n                                    <div class=\"ms-auto\">\n                                        <table class=\"table table-sm table-borderless avoid-page-break-inside\">\n\n                                            <!--Tax totals-->\n                                            <t t-set=\"tax_totals\" t-value=\"o.tax_totals or {}\"/>\n                                            <t t-call=\"account.document_tax_totals\"/>\n\n                                            <!--Payments-->\n                                            <t t-if=\"print_with_payments\">\n                                                <t t-if=\"o.payment_state != ''invoicing_legacy''\">\n                                                    <t t-set=\"payments_vals\" t-value=\"o.sudo().invoice_payments_widget and o.sudo().invoice_payments_widget[''content''] or []\"/>\n                                                    <t t-foreach=\"payments_vals\" t-as=\"payment_vals\">\n                                                        <tr t-if=\"payment_vals[''is_exchange''] == 0\">\n                                                            <td>\n                                                                <i class=\"oe_form_field text-end oe_payment_label\">Paid on <t t-out=\"payment_vals[''date'']\" t-options=\"{&quot;widget&quot;: &quot;date&quot;}\">2021-09-19</t></i>\n                                                            </td>\n                                                            <td class=\"text-end\">\n                                                                <span t-out=\"payment_vals[''amount'']\" t-options=\"{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: o.currency_id}\">20.00</span>\n                                                            </td>\n                                                        </tr>\n                                                    </t>\n                                                    <t t-if=\"len(payments_vals) &gt; 0\">\n                                                        <tr class=\"border-black fw-bold\">\n                                                            <td>Amount Due</td>\n                                                            <td class=\"text-end\">\n                                                                <span t-field=\"o.amount_residual\">11.05</span>\n                                                            </td>\n                                                        </tr>\n                                                    </t>\n                                                </t>\n                                            </t>\n                                        </table>\n                                    </div>\n                                </div>\n                                <div class=\"mb-2\">\n                                    <p class=\"text-end lh-sm\" t-if=\"o.company_id.display_invoice_amount_total_words\">\n                                        Total amount in words: <br/>\n                                        <small class=\"text-muted lh-sm\"><span t-field=\"o.amount_total_words\">Thirty one dollar and Five cents</span></small>\n                                    </p>\n                                </div>\n                                <t t-call=\"account.document_tax_totals_company_currency_template\"/>\n                            </div>\n                            <div id=\"payment_term\" class=\"clearfix\">\n                                <div class=\"justify-text\">\n                                    <p t-if=\"not is_html_empty(o.fiscal_position_id.note)\" name=\"note\" class=\"mb-2\">\n                                        <span t-field=\"o.fiscal_position_id.note\"/>\n                                    </p>\n                                </div>\n                                <t t-set=\"payment_term_details\" t-value=\"o.payment_term_details\"/>\n                                <div class=\"mb-3\">\n                                    <span id=\"payment_terms_note_id\" t-if=\"o.invoice_payment_term_id.note\" t-field=\"o.invoice_payment_term_id.note\" name=\"payment_term\">Payment within 30 calendar day</span><br/>\n                                    <t t-if=\"o.invoice_payment_term_id.display_on_invoice and payment_term_details\">\n                                        <div t-if=\"o.show_payment_term_details\" id=\"total_payment_term_details_table\" class=\"row\">\n                                            <div t-attf-class=\"#{''col-10'' if report_type != ''html'' else ''col-sm-10 col-md-9''}\">\n                                                <t t-if=\"o._is_eligible_for_early_payment_discount(o.currency_id,o.invoice_date)\">\n                                                    <td>\n                                                        <span t-options=\"{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: o.currency_id}\" t-out=\"o.invoice_payment_term_id._get_amount_due_after_discount(o.amount_total, o.amount_tax)\">30.00</span> due if paid before\n                                                        <span t-out=\"o.invoice_payment_term_id._get_last_discount_date_formatted(o.invoice_date)\">2024-01-01</span>\n                                                    </td>\n                                                </t>\n                                                <t t-if=\"len(payment_term_details) &gt; 1\" t-foreach=\"payment_term_details\" t-as=\"term\">\n                                                    <div>\n                                                        <span t-out=\"term_index + 1\">1</span> - Installment of\n                                                        <t t-options=\"{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: o.currency_id}\" t-out=\"term.get(''amount'')\" class=\"text-end\">31.05</t>\n                                                        <span> due on </span>\n                                                        <t t-out=\"term.get(''date'')\" class=\"text-start\">2024-01-01</t>\n                                                    </div>\n                                                </t>\n                                            </div>\n                                        </div>\n                                    </t>\n                                </div>\n                                <div class=\"mb-3\" t-if=\"o.move_type in (''out_invoice'', ''in_refund'') and o.payment_reference\">\n                                    <p name=\"payment_communication\">\n                                        Payment Communication: <span class=\"fw-bold\" t-field=\"o.payment_reference\">INV/2023/00001</span>\n                                        <t t-if=\"o.partner_bank_id\">\n                                            <br/> on this account: <span t-field=\"o.partner_bank_id\" class=\"fw-bold\"/>\n                                        </t>\n                                    </p>\n                                </div>\n                                <t t-set=\"show_qr\" t-value=\"o.display_qr_code and o.amount_residual &gt; 0\"/>\n                                <div t-if=\"not show_qr\" name=\"qr_code_placeholder\" class=\"oe_structure\"/>\n                                <div id=\"qrcode\" class=\"d-flex mb-3 avoid-page-break-inside\" t-else=\"\">\n                                    <div class=\"qrcode me-3\" id=\"qrcode_image\">\n                                        <t t-set=\"qr_code_url\" t-value=\"o._generate_qr_code(silent_errors=True)\"/>\n                                        <p t-if=\"qr_code_url\" class=\"position-relative mb-0\">\n                                            <img t-att-src=\"qr_code_url\"/>\n                                            <img src=\"/account/static/src/img/Odoo_logo_O.svg\" id=\"qrcode_odoo_logo\" class=\"top-50 start-50 position-absolute bg-white border border-white border-3 rounded-circle\"/>\n                                        </p>\n                                    </div>\n                                    <div class=\"d-inline text-muted lh-sm fst-italic\" id=\"qrcode_info\" t-if=\"qr_code_url\">\n                                        <p>Scan this QR Code to<br/>pay with your mobile</p>\n                                    </div>\n                                </div>\n                                <!--terms and conditions-->\n                                <div class=\"text-muted mb-3\" t-attf-style=\"#{''text-align:justify;text-justify:inter-word;'' if o.company_id.terms_type != ''html'' else ''''}\" t-if=\"not is_html_empty(o.narration)\" name=\"comment\">\n                                    <span t-field=\"o.narration\"/>\n                                </div>\n                            </div>\n                        </div>\n                    </div>\n                </div>\n            </t>\n        </t>"}', '<?xml version="1.0"?>
<t t-name="account.report_invoice_document">
            <t t-call="web.external_layout">
                <t t-set="o" t-value="o.with_context(lang=lang)"/>
                <t t-set="forced_vat" t-value="o.fiscal_position_id.foreign_vat"/> <!-- So that it appears in the footer of the report instead of the company VAT if it''s set -->
                <div class="row">
                    <t t-if="o.partner_shipping_id and (o.partner_shipping_id != o.partner_id)">
                        <div class="col-6">
                            <t t-set="information_block">
                                <div groups="account.group_delivery_invoice_address" name="shipping_address_block">
                                    <strong>Shipping Address:</strong>
                                    <div t-field="o.partner_shipping_id" t-options="{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;], &quot;no_marker&quot;: True}"/>
                                </div>
                            </t>
                        </div>
                        <div class="col-6" name="address_not_same_as_shipping">
                            <t t-set="address">
                                <address class="mb-0" t-field="o.partner_id" t-options="{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;], &quot;no_marker&quot;: True}"/>
                                <div t-if="o.partner_id.vat" id="partner_vat_address_not_same_as_shipping">
                                    <t t-if="o.company_id.account_fiscal_country_id.vat_label" t-out="o.company_id.account_fiscal_country_id.vat_label" id="inv_tax_id_label"/>
                                    <t t-else="">Tax ID</t>: <span t-field="o.partner_id.vat"/>
                                </div>
                                <div t-if="o.partner_id.country_code == ''MA'' and o.partner_id.company_registry">
                                    ICE: <a t-field="o.partner_id.company_registry"/>
                                </div>
                            </t>
                        </div>
                    </t>
                    <t t-elif="o.partner_shipping_id and (o.partner_shipping_id == o.partner_id)">
                        <div class="offset-col-6 col-6" name="address_same_as_shipping">
                            <t t-set="address">
                                <address class="mb-0" t-field="o.partner_id" t-options="{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;], &quot;no_marker&quot;: True}"/>
                                <div t-if="o.partner_id.vat" id="partner_vat_address_same_as_shipping">
                                    <t t-if="o.company_id.account_fiscal_country_id.vat_label" t-out="o.company_id.account_fiscal_country_id.vat_label" id="inv_tax_id_label"/>
                                    <t t-else="">Tax ID</t>: <span t-field="o.partner_id.vat"/>
                                </div>
                                <div t-if="o.partner_id.country_code == ''MA'' and o.partner_id.company_registry">
                                    ICE: <a t-field="o.partner_id.company_registry"/>
                                </div>
                            </t>
                        </div>
                    </t>
                    <t t-else="">
                        <div class="offset-col-6 col-6" name="no_shipping">
                            <t t-set="address">
                                <address class="mb-0" t-field="o.partner_id" t-options="{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;], &quot;no_marker&quot;: True}"/>
                                <div t-if="o.partner_id.vat" id="partner_vat_no_shipping">
                                    <t t-if="o.company_id.account_fiscal_country_id.vat_label" t-out="o.company_id.account_fiscal_country_id.vat_label" id="inv_tax_id_label"/>
                                    <t t-else="">Tax ID</t>: <span t-field="o.partner_id.vat"/>
                                </div>
                                <div t-if="o.partner_id.country_code == ''MA'' and o.partner_id.company_registry">
                                    ICE: <a t-field="o.partner_id.company_registry"/>
                                </div>
                            </t>
                        </div>
                    </t>
                </div>
                <div class="mt-5 clearfix">
                    <div class="page mb-4">
                        <h2>
                            <span t-if="not proforma"/>
                            <span t-else="">PROFORMA</span>
                            <span t-if="o.move_type == ''out_invoice'' and o.state == ''posted''">Invoice</span>
                            <span t-elif="o.move_type == ''out_invoice'' and o.state == ''draft''">Draft Invoice</span>
                            <span t-elif="o.move_type == ''out_invoice'' and o.state == ''cancel''">Cancelled Invoice</span>
                            <span t-elif="o.move_type == ''out_refund'' and o.state == ''posted''">Credit Note</span>
                            <span t-elif="o.move_type == ''out_refund'' and o.state == ''draft''">Draft Credit Note</span>
                            <span t-elif="o.move_type == ''out_refund'' and o.state == ''cancel''">Cancelled Credit Note</span>
                            <span t-elif="o.move_type == ''in_refund''">Vendor Credit Note</span>
                            <span t-elif="o.move_type == ''in_invoice''">Vendor Bill</span>
                            <span t-if="o.name != ''/''" t-field="o.name">INV/2023/0001</span>
                        </h2>
                        <div class="oe_structure"/>
                        <div id="informations" class="row mt-3 mb-1">
                            <div t-attf-class="#{''col-auto col-3 mw-100'' if report_type != ''html'' else ''col''} mb-2" t-if="o.invoice_date" name="invoice_date">
                                <t t-if="o.move_type == ''out_invoice''"><strong>Invoice Date:</strong></t>
                                <t t-elif="o.move_type == ''out_refund''"><strong>Credit Note Date:</strong></t>
                                <t t-elif="o.move_type == ''out_receipt''"><strong>Receipt Date:</strong></t>
                                <t t-else=""><strong>Date:</strong></t><br/>
                                <span t-field="o.invoice_date">2023-09-12</span>
                            </div>
                            <div t-attf-class="#{''col-auto col-3 mw-100'' if report_type != ''html'' else ''col''} mb-2" t-if="o.invoice_date_due and o.move_type == ''out_invoice'' and o.state == ''posted''" name="due_date">
                                <strong>Due Date:</strong><br/>
                                <span t-field="o.invoice_date_due">2023-10-31</span>
                            </div>
                            <div t-attf-class="#{''col-auto col-3 mw-100'' if report_type != ''html'' else ''col''} mb-2" t-if="o.delivery_date" name="delivery_date">
                                <strong>Delivery Date:</strong><br/>
                                <span t-field="o.delivery_date">2023-09-25</span>
                            </div>
                            <div t-attf-class="#{''col-auto col-3 mw-100'' if report_type != ''html'' else ''col''} mb-2" t-if="o.invoice_origin" name="origin">
                                <strong>Source:</strong><br/>
                                <span t-field="o.invoice_origin">SO123</span>
                            </div>
                            <div t-attf-class="#{''col-auto col-3 mw-100'' if report_type != ''html'' else ''col''} mb-2" t-if="o.partner_id.ref" name="customer_code">
                                <strong>Customer Code:</strong><br/>
                                <span t-field="o.partner_id.ref"/>
                            </div>
                            <div t-attf-class="#{''col-auto col-3 mw-100'' if report_type != ''html'' else ''col''} mb-2" t-if="o.ref" name="reference">
                                <strong>Reference:</strong><br/>
                                <span t-field="o.ref">INV/2023/00001</span>
                            </div>
                            <div t-attf-class="#{''col-auto col-3 mw-100'' if report_type != ''html'' else ''col''} mb-2" t-if="o.invoice_incoterm_id" name="incoterm_id">
                                <strong>Incoterm:</strong><br/>
                                <p t-if="o.incoterm_location">
                                    <span t-field="o.invoice_incoterm_id.code"/> <br/>
                                    <span t-field="o.incoterm_location"/>
                                </p>
                                <span t-else="" t-field="o.invoice_incoterm_id.code" class="m-0"/>
                            </div>
                        </div>

                        <t t-set="display_discount" t-value="any(l.discount for l in o.invoice_line_ids)"/>
                        <div class="oe_structure"/>
                        <t t-set="has_long_desc" t-value="any(line.name and line.name.count(''\n'') &gt; 30 for line in o.invoice_line_ids if line.name)"/>
                        <table class="table table-sm o_main_table table-borderless" name="invoice_line_table">
                            <thead t-attf-style="#{has_long_desc and ''display: table-row-group;'' or ''''}">
                                <tr>
                                    <th name="th_description" class="text-start"><span>Description</span></th>
                                    <th name="th_quantity" class="text-end"><span>Quantity</span></th>
                                    <th name="th_priceunit" t-attf-class="text-end {{ ''d-none d-md-table-cell'' if report_type == ''html'' else '''' }}"><span>Unit Price</span></th>
                                    <th name="th_discount" t-if="display_discount" t-attf-class="text-end {{ ''d-none d-md-table-cell'' if report_type == ''html'' else '''' }}">
                                        <span>Disc.%</span>
                                    </th>
                                    <th name="th_taxes" t-attf-class="text-end {{ ''d-none d-md-table-cell'' if report_type == ''html'' else '''' }}"><span>Taxes</span></th>
                                    <th name="th_subtotal" class="text-end">
                                        <span>Amount</span>
                                    </th>
                                </tr>
                            </thead>
                            <tbody class="invoice_tbody">
                                <t t-set="current_subtotal" t-value="0"/>
                                <t t-set="current_total" t-value="0"/>
                                <t t-set="lines" t-value="o.invoice_line_ids.sorted(key=lambda l: (-l.sequence, l.date, l.move_name, -l.id), reverse=True)"/>

                                <t t-foreach="lines" t-as="line">
                                    <t t-set="current_subtotal" t-value="current_subtotal + line.price_subtotal"/>
                                    <t t-set="current_total" t-value="current_total + line.price_total"/>

                                    <tr t-att-class="''bg-200 fw-bold o_line_section'' if line.display_type == ''line_section'' else ''fst-italic o_line_note'' if line.display_type == ''line_note'' else ''''">
                                        <t t-if="line.display_type == ''product''" name="account_invoice_line_accountable">
                                            <td name="account_invoice_line_name"><span t-if="line.name" t-field="line.name" t-options="{''widget'': ''text''}" dir="auto">Bacon Burger</span></td>
                                            <td name="td_quantity" class="text-end">
                                                <span t-field="line.quantity">3.00</span>
                                                <span t-field="line.product_uom_id" groups="uom.group_uom">units</span>
                                            </td>
                                            <td name="td_price_unit" t-attf-class="text-end {{ ''d-none d-md-table-cell'' if report_type == ''html'' else '''' }}">
                                                <span class="text-nowrap" t-field="line.price_unit">9.00</span>
                                            </td>
                                            <td name="td_discount" t-if="display_discount" t-attf-class="text-end {{ ''d-none d-md-table-cell'' if report_type == ''html'' else '''' }}">
                                                <span class="text-nowrap" t-field="line.discount">0</span>
                                            </td>
                                            <t t-set="taxes" t-value="'', ''.join([(tax.invoice_label or tax.name) for tax in line.tax_ids])"/>
                                            <td name="td_taxes" t-attf-class="text-end {{ ''d-none d-md-table-cell'' if report_type == ''html'' else '''' }} {{ ''text-nowrap'' if len(taxes) &lt; 10 else '''' }}">
                                                <span t-out="taxes" id="line_tax_ids">Tax 15%</span>
                                            </td>
                                            <td name="td_subtotal" class="text-end o_price_total">
                                                <span class="text-nowrap" t-field="line.price_subtotal">27.00</span>
                                            </td>
                                        </t>
                                        <t t-elif="line.display_type == ''line_section''">
                                            <td colspan="99">
                                                <span t-if="line.name" t-field="line.name" t-options="{''widget'': ''text''}" dir="auto">A section title</span>
                                            </td>
                                            <t t-set="current_section" t-value="line"/>
                                            <t t-set="current_subtotal" t-value="0"/>
                                        </t>
                                        <t t-elif="line.display_type == ''line_note''">
                                            <td colspan="99">
                                                <span t-if="line.name" t-field="line.name" t-options="{''widget'': ''text''}" dir="auto">A note, whose content usually applies to the section or product above.</span>
                                            </td>
                                        </t>
                                    </tr>

                                    <t t-if="current_section and (line_last or lines[line_index+1].display_type == ''line_section'')">
                                        <tr class="is-subtotal text-end">
                                            <td colspan="99">
                                                <strong class="mr16">Subtotal</strong>
                                                <span t-out="current_subtotal" t-options="{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: o.currency_id}">31.05</span>
                                            </td>
                                        </tr>
                                    </t>
                                </t>
                            </tbody>
                        </table>
                        <div>
                            <div id="right-elements" t-attf-class="#{''col-5'' if report_type != ''html'' else ''col-12 col-md-5''} ms-5 d-inline-block float-end">
                                <div id="total" class="clearfix row">
                                    <div class="ms-auto">
                                        <table class="table table-sm table-borderless avoid-page-break-inside">

                                            <!--Tax totals-->
                                            <t t-set="tax_totals" t-value="o.tax_totals or {}"/>
                                            <t t-call="account.document_tax_totals"/>

                                            <!--Payments-->
                                            <t t-if="print_with_payments">
                                                <t t-if="o.payment_state != ''invoicing_legacy''">
                                                    <t t-set="payments_vals" t-value="o.sudo().invoice_payments_widget and o.sudo().invoice_payments_widget[''content''] or []"/>
                                                    <t t-foreach="payments_vals" t-as="payment_vals">
                                                        <tr t-if="payment_vals[''is_exchange''] == 0">
                                                            <td>
                                                                <i class="oe_form_field text-end oe_payment_label">Paid on <t t-out="payment_vals[''date'']" t-options="{&quot;widget&quot;: &quot;date&quot;}">2021-09-19</t></i>
                                                            </td>
                                                            <td class="text-end">
                                                                <span t-out="payment_vals[''amount'']" t-options="{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: o.currency_id}">20.00</span>
                                                            </td>
                                                        </tr>
                                                    </t>
                                                    <t t-if="len(payments_vals) &gt; 0">
                                                        <tr class="border-black fw-bold">
                                                            <td>Amount Due</td>
                                                            <td class="text-end">
                                                                <span t-field="o.amount_residual">11.05</span>
                                                            </td>
                                                        </tr>
                                                    </t>
                                                </t>
                                            </t>
                                        </table>
                                    </div>
                                </div>
                                <div class="mb-2">
                                    <p class="text-end lh-sm" t-if="o.company_id.display_invoice_amount_total_words">
                                        Total amount in words: <br/>
                                        <small class="text-muted lh-sm"><span t-field="o.amount_total_words">Thirty one dollar and Five cents</span></small>
                                    </p>
                                </div>
                                <t t-call="account.document_tax_totals_company_currency_template"/>
                            </div>
                            <div id="payment_term" class="clearfix">
                                <div class="justify-text">
                                    <p t-if="not is_html_empty(o.fiscal_position_id.note)" name="note" class="mb-2">
                                        <span t-field="o.fiscal_position_id.note"/>
                                    </p>
                                </div>
                                <t t-set="payment_term_details" t-value="o.payment_term_details"/>
                                <div class="mb-3">
                                    <span id="payment_terms_note_id" t-if="o.invoice_payment_term_id.note" t-field="o.invoice_payment_term_id.note" name="payment_term">Payment within 30 calendar day</span><br/>
                                    <t t-if="o.invoice_payment_term_id.display_on_invoice and payment_term_details">
                                        <div t-if="o.show_payment_term_details" id="total_payment_term_details_table" class="row">
                                            <div t-attf-class="#{''col-10'' if report_type != ''html'' else ''col-sm-10 col-md-9''}">
                                                <t t-if="o._is_eligible_for_early_payment_discount(o.currency_id,o.invoice_date)">
                                                    <td>
                                                        <span t-options="{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: o.currency_id}" t-out="o.invoice_payment_term_id._get_amount_due_after_discount(o.amount_total, o.amount_tax)">30.00</span> due if paid before
                                                        <span t-out="o.invoice_payment_term_id._get_last_discount_date_formatted(o.invoice_date)">2024-01-01</span>
                                                    </td>
                                                </t>
                                                <t t-if="len(payment_term_details) &gt; 1" t-foreach="payment_term_details" t-as="term">
                                                    <div>
                                                        <span t-out="term_index + 1">1</span> - Installment of
                                                        <t t-options="{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: o.currency_id}" t-out="term.get(''amount'')" class="text-end">31.05</t>
                                                        <span> due on </span>
                                                        <t t-out="term.get(''date'')" class="text-start">2024-01-01</t>
                                                    </div>
                                                </t>
                                            </div>
                                        </div>
                                    </t>
                                </div>
                                <div class="mb-3" t-if="o.move_type in (''out_invoice'', ''in_refund'') and o.payment_reference">
                                    <p name="payment_communication">
                                        Payment Communication: <span class="fw-bold" t-field="o.payment_reference">INV/2023/00001</span>
                                        <t t-if="o.partner_bank_id">
                                            <br/> on this account: <span t-field="o.partner_bank_id" class="fw-bold"/>
                                        </t>
                                    </p>
                                </div>
                                <t t-set="show_qr" t-value="o.display_qr_code and o.amount_residual &gt; 0"/>
                                <div t-if="not show_qr" name="qr_code_placeholder" class="oe_structure"/>
                                <div id="qrcode" class="d-flex mb-3 avoid-page-break-inside" t-else="">
                                    <div class="qrcode me-3" id="qrcode_image">
                                        <t t-set="qr_code_url" t-value="o._generate_qr_code(silent_errors=True)"/>
                                        <p t-if="qr_code_url" class="position-relative mb-0">
                                            <img t-att-src="qr_code_url"/>
                                            <img src="/account/static/src/img/Odoo_logo_O.svg" id="qrcode_odoo_logo" class="top-50 start-50 position-absolute bg-white border border-white border-3 rounded-circle"/>
                                        </p>
                                    </div>
                                    <div class="d-inline text-muted lh-sm fst-italic" id="qrcode_info" t-if="qr_code_url">
                                        <p>Scan this QR Code to<br/>pay with your mobile</p>
                                    </div>
                                </div>
                                <!--terms and conditions-->
                                <div class="text-muted mb-3" t-attf-style="#{''text-align:justify;text-justify:inter-word;'' if o.company_id.terms_type != ''html'' else ''''}" t-if="not is_html_empty(o.narration)" name="comment">
                                    <span t-field="o.narration"/>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            </t>
        </t>

        ', false, true, '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295', false);
INSERT INTO public.ir_ui_view VALUES (750, 16, NULL, 1, 1, 'document_tax_totals_template', NULL, 'account.document_tax_totals_template', 'qweb', 'account/views/report_invoice.xml', 'primary', '{"en_US": "<t t-name=\"account.document_tax_totals_template\">\n            <!--\n                Generic template to display tax totals in pdf reports.\n                Used by invoices, SO and PO.\n\n                ARGUMENTS:\n                - tax_totals: dict in the form generated by account.move''s _get_tax_totals.\n            -->\n            <t t-foreach=\"tax_totals.get(''subtotals'')\" t-as=\"subtotal\">\n                <tr class=\"border-black o_subtotal\">\n                    <td><strong t-out=\"subtotal[''name'']\">Untaxed Amount</strong></td>\n\n                    <td class=\"text-end\">\n                        <span t-att-class=\"oe_subtotal_footer_separator\" t-out=\"subtotal[''formatted_amount'']\">27.00</span>\n                    </td>\n                </tr>\n\n                <t t-set=\"subtotal_to_show\" t-value=\"subtotal[''name'']\"/>\n                <t t-call=\"account.tax_groups_totals\"/>\n            </t>\n\n            <tr t-if=\"''formatted_rounding_amount'' in tax_totals and tax_totals.get(''rounding_amount'') != 0\">\n                <td>Rounding</td>\n                <td class=\"text-end\">\n                    <span t-out=\"tax_totals.get(''formatted_rounding_amount'')\">0</span>\n                </td>\n            </tr>\n            \n            <!--Total amount with all taxes-->\n            <tr class=\"border-black o_total\">\n                <td><strong>Total</strong></td>\n                <td class=\"text-end\">\n                    <span t-out=\"tax_totals.get(''formatted_amount_total'')\">31.05</span>\n                </td>\n            </tr>\n        </t>"}', '<?xml version="1.0"?>
<t t-name="account.document_tax_totals_template">
            <!--
                Generic template to display tax totals in pdf reports.
                Used by invoices, SO and PO.

                ARGUMENTS:
                - tax_totals: dict in the form generated by account.move''s _get_tax_totals.
            -->
            <t t-foreach="tax_totals.get(''subtotals'')" t-as="subtotal">
                <tr class="border-black o_subtotal">
                    <td><strong t-out="subtotal[''name'']">Untaxed Amount</strong></td>

                    <td class="text-end">
                        <span t-att-class="oe_subtotal_footer_separator" t-out="subtotal[''formatted_amount'']">27.00</span>
                    </td>
                </tr>

                <t t-set="subtotal_to_show" t-value="subtotal[''name'']"/>
                <t t-call="account.tax_groups_totals"/>
            </t>

            <tr t-if="''formatted_rounding_amount'' in tax_totals and tax_totals.get(''rounding_amount'') != 0">
                <td>Rounding</td>
                <td class="text-end">
                    <span t-out="tax_totals.get(''formatted_rounding_amount'')">0</span>
                </td>
            </tr>
            
            <!--Total amount with all taxes-->
            <tr class="border-black o_total">
                <td><strong>Total</strong></td>
                <td class="text-end">
                    <span t-out="tax_totals.get(''formatted_amount_total'')">31.05</span>
                </td>
            </tr>
        </t>

         ', false, true, '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295', false);
INSERT INTO public.ir_ui_view VALUES (751, 16, 750, 1, 1, 'document_tax_totals', NULL, 'account.document_tax_totals', 'qweb', 'account/views/report_invoice.xml', 'primary', '{"en_US": "<data inherit_id=\"account.document_tax_totals_template\" primary=\"True\"><xpath expr=\".\" position=\"attributes\"><attribute name=\"t-name\">account.document_tax_totals</attribute></xpath></data>"}', '<?xml version="1.0"?>
<data inherit_id="account.document_tax_totals_template" primary="True"><xpath expr="." position="attributes"><attribute name="t-name">account.document_tax_totals</attribute></xpath></data>

        ', false, true, '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295', false);
INSERT INTO public.ir_ui_view VALUES (752, 16, NULL, 1, 1, 'tax_groups_totals', NULL, 'account.tax_groups_totals', 'qweb', 'account/views/report_invoice.xml', 'primary', '{"en_US": "<t t-name=\"account.tax_groups_totals\">\n            <!--\n                Generic template to display a list of tax groups with the related amounts.\n\n                ARGUMENTS:\n                - tax_totals: dict in the form generated by account.move''s _get_tax_totals.\n                - subtotal_to_show: The subtotal we need to render the groups from\n            -->\n            <t t-foreach=\"tax_totals[''groups_by_subtotal''][subtotal_to_show]\" t-as=\"amount_by_group\">\n                <t t-set=\"display_tax_base\" t-value=\"tax_totals[''display_tax_base'']\"/>\n                <tr>\n                    <t t-if=\"tax_totals[''display_tax_base'']\">\n                        <td>\n                            <span t-esc=\"amount_by_group[''tax_group_name'']\"/>\n                            <span t-if=\"not amount_by_group[''hide_base_amount'']\" class=\"text-nowrap\"> on\n                                <t t-esc=\"amount_by_group[''formatted_tax_group_base_amount'']\"/>\n                            </span>\n                        </td>\n                        <td class=\"text-end o_price_total\">\n                            <span class=\"text-nowrap\" t-out=\"amount_by_group[''formatted_tax_group_amount'']\">1.05</span>\n                        </td>\n                    </t>\n                    <t t-else=\"\">\n                        <td>\n                            <span t-out=\"amount_by_group[''tax_group_name'']\">Tax 15%</span>\n                        </td>\n                        <td class=\"text-end o_price_total\">\n                            <span class=\"text-nowrap\" t-out=\"amount_by_group[''formatted_tax_group_amount'']\">4.05</span>\n                        </td>\n                    </t>\n                </tr>\n            </t>\n        </t>"}', '<?xml version="1.0"?>
<t t-name="account.tax_groups_totals">
            <!--
                Generic template to display a list of tax groups with the related amounts.

                ARGUMENTS:
                - tax_totals: dict in the form generated by account.move''s _get_tax_totals.
                - subtotal_to_show: The subtotal we need to render the groups from
            -->
            <t t-foreach="tax_totals[''groups_by_subtotal''][subtotal_to_show]" t-as="amount_by_group">
                <t t-set="display_tax_base" t-value="tax_totals[''display_tax_base'']"/>
                <tr>
                    <t t-if="tax_totals[''display_tax_base'']">
                        <td>
                            <span t-esc="amount_by_group[''tax_group_name'']"/>
                            <span t-if="not amount_by_group[''hide_base_amount'']" class="text-nowrap"> on
                                <t t-esc="amount_by_group[''formatted_tax_group_base_amount'']"/>
                            </span>
                        </td>
                        <td class="text-end o_price_total">
                            <span class="text-nowrap" t-out="amount_by_group[''formatted_tax_group_amount'']">1.05</span>
                        </td>
                    </t>
                    <t t-else="">
                        <td>
                            <span t-out="amount_by_group[''tax_group_name'']">Tax 15%</span>
                        </td>
                        <td class="text-end o_price_total">
                            <span class="text-nowrap" t-out="amount_by_group[''formatted_tax_group_amount'']">4.05</span>
                        </td>
                    </t>
                </tr>
            </t>
        </t>

        ', false, true, '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295', false);
INSERT INTO public.ir_ui_view VALUES (753, 16, NULL, 1, 1, 'document_tax_totals_company_currency_template', NULL, 'account.document_tax_totals_company_currency_template', 'qweb', 'account/views/report_invoice.xml', 'primary', '{"en_US": "<t t-name=\"account.document_tax_totals_company_currency_template\">\n            <t t-set=\"show_company_taxes\" t-value=\"o.company_id.currency_id != o.currency_id and o.move_type in [''out_invoice'', ''out_refund'']\"/>\n            <div t-if=\"not show_company_taxes\" class=\"oe_structure\"/>\n            <div class=\"mb-2 mt-3 border p-2 avoid-page-break-inside totals_taxes_company_currency\" t-else=\"\">\n                <table class=\"table table-sm table-borderless mb-0\">\n                    <p class=\"tax_computation_company_currency\">\n                        Taxes <span t-field=\"o.company_currency_id\"/>\n                    </p>\n                    <t t-foreach=\"tax_totals[''subtotals'']\" t-as=\"subtotal\">\n                        <tr class=\"border-black o_subtotal\">\n                            <td><strong t-out=\"subtotal[''name'']\">Untaxed amount</strong></td>\n                            <td class=\"text-end\">\n                                <span t-out=\"subtotal[''amount_company_currency'']\" t-options=\"{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: o.company_currency_id}\">27.00</span>\n                            </td>\n                        </tr>\n                        <t t-set=\"subtotal_to_show\" t-value=\"subtotal[''name'']\"/>\n                        <t t-foreach=\"tax_totals[''groups_by_subtotal''][subtotal_to_show]\" t-as=\"amount_by_group\">\n                            <tr>\n                                <t t-if=\"tax_totals[''display_tax_base'']\">\n                                    <td>\n                                        <span t-out=\"amount_by_group[''tax_group_name'']\">Tax 15%</span>\n                                        <span> on </span>\n                                        <span class=\"text-nowrap\" t-out=\"amount_by_group[''tax_group_base_amount_company_currency'']\" t-options=\"{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: o.company_currency_id}\">\n                                               27.00\n                                        </span>\n                                    </td>\n                                    <td class=\"text-end o_price_total\">\n                                        <span class=\"text-nowrap\" t-out=\"amount_by_group[''tax_group_amount_company_currency'']\" t-options=\"{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: o.company_currency_id}\">4.05</span>\n                                    </td>\n                                </t>\n                                <t t-else=\"\">\n                                    <td><span class=\"text-nowrap\" t-out=\"amount_by_group[''tax_group_name'']\"/></td>\n                                    <td class=\"text-end o_price_total\">\n                                        <span class=\"text-nowrap\" t-out=\"amount_by_group[''tax_group_amount_company_currency'']\" t-options=\"{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: o.company_currency_id}\">31.05</span>\n                                    </td>\n                                </t>\n                            </tr>\n                        </t>\n                    </t>\n                    <!--Total amount with all taxes-->\n                    <tr class=\"border-black o_total\">\n                        <td><strong>Total</strong></td>\n                        <td class=\"text-end\">\n                            <span t-out=\"abs(o.amount_total_signed)\" t-options=\"{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: o.company_currency_id}\">\n                            31.05</span>\n                        </td>\n                    </tr>\n                </table>\n            </div>\n        </t>"}', '<?xml version="1.0"?>
<t t-name="account.document_tax_totals_company_currency_template">
            <t t-set="show_company_taxes" t-value="o.company_id.currency_id != o.currency_id and o.move_type in [''out_invoice'', ''out_refund'']"/>
            <div t-if="not show_company_taxes" class="oe_structure"/>
            <div class="mb-2 mt-3 border p-2 avoid-page-break-inside totals_taxes_company_currency" t-else="">
                <table class="table table-sm table-borderless mb-0">
                    <p class="tax_computation_company_currency">
                        Taxes <span t-field="o.company_currency_id"/>
                    </p>
                    <t t-foreach="tax_totals[''subtotals'']" t-as="subtotal">
                        <tr class="border-black o_subtotal">
                            <td><strong t-out="subtotal[''name'']">Untaxed amount</strong></td>
                            <td class="text-end">
                                <span t-out="subtotal[''amount_company_currency'']" t-options="{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: o.company_currency_id}">27.00</span>
                            </td>
                        </tr>
                        <t t-set="subtotal_to_show" t-value="subtotal[''name'']"/>
                        <t t-foreach="tax_totals[''groups_by_subtotal''][subtotal_to_show]" t-as="amount_by_group">
                            <tr>
                                <t t-if="tax_totals[''display_tax_base'']">
                                    <td>
                                        <span t-out="amount_by_group[''tax_group_name'']">Tax 15%</span>
                                        <span> on </span>
                                        <span class="text-nowrap" t-out="amount_by_group[''tax_group_base_amount_company_currency'']" t-options="{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: o.company_currency_id}">
                                               27.00
                                        </span>
                                    </td>
                                    <td class="text-end o_price_total">
                                        <span class="text-nowrap" t-out="amount_by_group[''tax_group_amount_company_currency'']" t-options="{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: o.company_currency_id}">4.05</span>
                                    </td>
                                </t>
                                <t t-else="">
                                    <td><span class="text-nowrap" t-out="amount_by_group[''tax_group_name'']"/></td>
                                    <td class="text-end o_price_total">
                                        <span class="text-nowrap" t-out="amount_by_group[''tax_group_amount_company_currency'']" t-options="{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: o.company_currency_id}">31.05</span>
                                    </td>
                                </t>
                            </tr>
                        </t>
                    </t>
                    <!--Total amount with all taxes-->
                    <tr class="border-black o_total">
                        <td><strong>Total</strong></td>
                        <td class="text-end">
                            <span t-out="abs(o.amount_total_signed)" t-options="{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: o.company_currency_id}">
                            31.05</span>
                        </td>
                    </tr>
                </table>
            </div>
        </t>

        ', false, true, '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295', false);
INSERT INTO public.ir_ui_view VALUES (754, 16, NULL, 1, 1, 'report_invoice', NULL, 'account.report_invoice', 'qweb', 'account/views/report_invoice.xml', 'primary', '{"en_US": "<t t-name=\"account.report_invoice\">\n            <t t-call=\"web.html_container\">\n                <t t-foreach=\"docs\" t-as=\"o\">\n                    <t t-set=\"lang\" t-value=\"o.partner_id.lang\"/>\n                    <t t-if=\"o._get_name_invoice_report() == ''account.report_invoice_document''\" t-call=\"account.report_invoice_document\" t-lang=\"lang\"/>\n                </t>\n            </t>\n        </t>"}', '<?xml version="1.0"?>
