INSERT INTO public.ir_ui_view VALUES (786, 16, NULL, 1, 1, 'account.move.send.form', 'account.move.send', NULL, 'form', 'account/wizard/account_move_send_views.xml', 'primary', '{"en_US": "<form>\n                <!-- Invisible fields -->\n                <field name=\"company_id\" invisible=\"1\"/>\n                <field name=\"move_ids\" invisible=\"1\"/>\n                <field name=\"mode\" invisible=\"1\"/>\n                <field name=\"enable_download\" invisible=\"1\"/>\n                <field name=\"enable_send_mail\" invisible=\"1\"/>\n                <field name=\"send_mail_readonly\" invisible=\"1\"/>\n                <field name=\"send_mail_warning_message\" invisible=\"1\"/>\n                <field name=\"display_mail_composer\" invisible=\"1\"/>\n                <field name=\"mail_lang\" invisible=\"1\"/>\n                <field name=\"display_attachments_widget\" invisible=\"1\"/>\n                <field name=\"attachments_not_supported\" invisible=\"1\"/>\n\n                <div class=\"m-0\" name=\"warnings\">\n                    <field name=\"send_mail_warning_message\" class=\"o_field_html\" widget=\"actionable_errors\"/>\n                </div>\n\n                <!-- Options -->\n                <div name=\"options\" class=\"row\">\n                    <div name=\"standard_options\" class=\"col-3\">\n                        <div name=\"option_download\" invisible=\"not enable_download\">\n                            <field name=\"checkbox_download\"/>\n                            <b><label for=\"checkbox_download\"/></b>\n                        </div>\n                        <div name=\"option_send_mail\" invisible=\"not enable_send_mail\">\n                            <field name=\"checkbox_send_mail\" readonly=\"send_mail_readonly\"/>\n                            <b><label for=\"checkbox_send_mail\"/></b>\n                            <i class=\"fa fa-question-circle ml4\" role=\"img\" aria-label=\"Warning\" title=\"The email address is unknown on the partner\" invisible=\"not send_mail_readonly\"/>\n                        </div>\n                    </div>\n                    <div name=\"advanced_options\" class=\"col-3\"/>\n                </div>\n\n                <!-- Mail -->\n                <div invisible=\"not checkbox_send_mail\">\n                    <group invisible=\"not display_mail_composer\">\n                        <label for=\"mail_partner_ids\" string=\"Recipients\"/>\n                        <div>\n                            <span>Followers of the document and</span>\n                            <field name=\"mail_partner_ids\" widget=\"many2many_tags_email\" placeholder=\"Add contacts to notify...\" options=\"{''no_quick_create'': True}\" context=\"{''show_email'': True, ''form_view_ref'': ''base.view_partner_simple_form''}\"/>\n                        </div>\n                        <field name=\"mail_subject\" placeholder=\"Subject...\" required=\"checkbox_send_mail and mode == ''invoice_single''\"/>\n                    </group>\n                    <field name=\"mail_body\" class=\"oe-bordered-editor\" options=\"{''style-inline'': true}\" invisible=\"not display_mail_composer\"/>\n                    <group>\n                        <group>\n                            <field name=\"mail_template_id\" required=\"mode == ''invoice_multi''\" options=\"{''no_create'': True, ''no_edit'': True}\" context=\"{''default_model'': ''account.move''}\"/>\n                        </group>\n                    </group>\n                </div>\n\n                <field name=\"mail_attachments_widget\" widget=\"mail_attachments\" string=\"Attach a file\" nolabel=\"1\" colspan=\"2\" invisible=\"not display_attachments_widget\"/>\n\n                <footer>\n                    <button string=\"Send &amp; Print\" data-hotkey=\"q\" name=\"action_send_and_print\" type=\"object\" class=\"print btn-primary o_mail_send\">\n                    </button>\n                    <button string=\"Cancel\" data-hotkey=\"x\" special=\"cancel\" class=\"btn-secondary\"/>\n                </footer>\n            </form>"}', '<?xml version="1.0"?>
<form>
                <!-- Invisible fields -->
                <field name="company_id" invisible="1"/>
                <field name="move_ids" invisible="1"/>
                <field name="mode" invisible="1"/>
                <field name="enable_download" invisible="1"/>
                <field name="enable_send_mail" invisible="1"/>
                <field name="send_mail_readonly" invisible="1"/>
                <field name="send_mail_warning_message" invisible="1"/>
                <field name="display_mail_composer" invisible="1"/>
                <field name="mail_lang" invisible="1"/>
                <field name="display_attachments_widget" invisible="1"/>
                <field name="attachments_not_supported" invisible="1"/>

                <div class="m-0" name="warnings">
                    <field name="send_mail_warning_message" class="o_field_html" widget="actionable_errors"/>
                </div>

                <!-- Options -->
                <div name="options" class="row">
                    <div name="standard_options" class="col-3">
                        <div name="option_download" invisible="not enable_download">
                            <field name="checkbox_download"/>
                            <b><label for="checkbox_download"/></b>
                        </div>
                        <div name="option_send_mail" invisible="not enable_send_mail">
                            <field name="checkbox_send_mail" readonly="send_mail_readonly"/>
                            <b><label for="checkbox_send_mail"/></b>
                            <i class="fa fa-question-circle ml4" role="img" aria-label="Warning" title="The email address is unknown on the partner" invisible="not send_mail_readonly"/>
                        </div>
                    </div>
                    <div name="advanced_options" class="col-3"/>
                </div>

                <!-- Mail -->
                <div invisible="not checkbox_send_mail">
                    <group invisible="not display_mail_composer">
                        <label for="mail_partner_ids" string="Recipients"/>
                        <div>
                            <span>Followers of the document and</span>
                            <field name="mail_partner_ids" widget="many2many_tags_email" placeholder="Add contacts to notify..." options="{''no_quick_create'': True}" context="{''show_email'': True, ''form_view_ref'': ''base.view_partner_simple_form''}"/>
                        </div>
                        <field name="mail_subject" placeholder="Subject..." required="checkbox_send_mail and mode == ''invoice_single''"/>
                    </group>
                    <field name="mail_body" class="oe-bordered-editor" options="{''style-inline'': true}" invisible="not display_mail_composer"/>
                    <group>
                        <group>
                            <field name="mail_template_id" required="mode == ''invoice_multi''" options="{''no_create'': True, ''no_edit'': True}" context="{''default_model'': ''account.move''}"/>
                        </group>
                    </group>
                </div>

                <field name="mail_attachments_widget" widget="mail_attachments" string="Attach a file" nolabel="1" colspan="2" invisible="not display_attachments_widget"/>

                <footer>
                    <button string="Send &amp; Print" data-hotkey="q" name="action_send_and_print" type="object" class="print btn-primary o_mail_send">
                    </button>
                    <button string="Cancel" data-hotkey="x" special="cancel" class="btn-secondary"/>
                </footer>
            </form>
        ', false, true, '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295', false);
INSERT INTO public.ir_ui_view VALUES (759, 16, NULL, 1, 1, 'account.invoice.report.view.tree', 'account.invoice.report', NULL, 'tree', 'account/report/account_invoice_report_view.xml', 'primary', '{"en_US": "<tree string=\"Invoices Analysis\">\n                <field name=\"move_id\" string=\"Invoice Number\"/>\n                <field name=\"journal_id\" optional=\"hide\"/>\n                <field name=\"partner_id\" optional=\"show\"/>\n                <field name=\"country_id\" optional=\"hide\"/>\n                <field name=\"invoice_date\" optional=\"show\"/>\n                <field name=\"invoice_date_due\" optional=\"show\"/>\n                <field name=\"invoice_user_id\" optional=\"hide\" widget=\"many2one_avatar_user\"/>\n                <field name=\"product_categ_id\" optional=\"hide\"/>\n                <field name=\"product_id\" optional=\"show\"/>\n                <field name=\"company_id\" groups=\"base.group_multi_company\"/>\n                <field name=\"price_average\" optional=\"hide\" sum=\"Total\"/>\n                <field name=\"quantity\" optional=\"hide\" sum=\"Total\"/>\n                <field name=\"price_subtotal\" optional=\"show\" sum=\"Total\"/>\n                <field name=\"price_total\" optional=\"show\" sum=\"Total\"/>\n                <field name=\"price_margin\" optional=\"hide\"/>\n                <field name=\"inventory_value\" optional=\"hide\" sum=\"Total\"/>\n                <field name=\"state\" optional=\"hide\"/>\n                <field name=\"payment_state\" optional=\"hide\"/>\n                <field name=\"move_type\" optional=\"hide\"/>\n             </tree>"}', '<?xml version="1.0"?>
<tree string="Invoices Analysis">
                <field name="move_id" string="Invoice Number"/>
                <field name="journal_id" optional="hide"/>
                <field name="partner_id" optional="show"/>
                <field name="country_id" optional="hide"/>
                <field name="invoice_date" optional="show"/>
                <field name="invoice_date_due" optional="show"/>
                <field name="invoice_user_id" optional="hide" widget="many2one_avatar_user"/>
                <field name="product_categ_id" optional="hide"/>
                <field name="product_id" optional="show"/>
                <field name="company_id" groups="base.group_multi_company"/>
                <field name="price_average" optional="hide" sum="Total"/>
                <field name="quantity" optional="hide" sum="Total"/>
                <field name="price_subtotal" optional="show" sum="Total"/>
                <field name="price_total" optional="show" sum="Total"/>
                <field name="price_margin" optional="hide"/>
                <field name="inventory_value" optional="hide" sum="Total"/>
                <field name="state" optional="hide"/>
                <field name="payment_state" optional="hide"/>
                <field name="move_type" optional="hide"/>
             </tree>
         ', false, true, '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295', false);
INSERT INTO public.ir_ui_view VALUES (760, 16, NULL, 1, 1, 'account.invoice.report.search', 'account.invoice.report', NULL, 'search', 'account/report/account_invoice_report_view.xml', 'primary', '{"en_US": "<search string=\"Invoices Analysis\">\n                <filter string=\"My Invoices\" name=\"my_invoice\" domain=\"[(''invoice_user_id'', ''='', uid)]\"/>\n                <separator/>\n                <field name=\"invoice_date\"/>\n                <separator/>\n                <filter string=\"To Invoice\" name=\"toinvoice\" domain=\"[(''state'',''='',''draft'')]\" help=\"Draft Invoices\"/>\n                <filter string=\"Invoiced\" name=\"current\" domain=\"[(''state'',''not in'', (''draft'',''cancel''))]\"/>\n                <separator/>\n                <filter string=\"Customers\" name=\"customer\" domain=\"[''|'', (''move_type'',''='',''out_invoice''),(''move_type'',''='',''out_refund'')]\"/>\n                <filter string=\"Vendors\" name=\"supplier\" domain=\"[''|'', (''move_type'',''='',''in_invoice''),(''move_type'',''='',''in_refund'')]\"/>\n                <separator/>\n                <filter string=\"Invoices\" name=\"invoice\" domain=\"[''|'', (''move_type'',''='',''out_invoice''),(''move_type'',''='',''in_invoice'')]\"/>\n                <filter string=\"Credit Notes\" name=\"creditnote\" domain=\"[''|'', (''move_type'',''='',''out_refund''),(''move_type'',''='',''in_refund'')]\"/>\n                <separator/>\n                <filter name=\"filter_invoice_date\" date=\"invoice_date\"/>\n                <filter name=\"invoice_date_due\" date=\"invoice_date_due\"/>\n                <field name=\"partner_id\" operator=\"child_of\"/>\n                <field name=\"invoice_user_id\"/>\n                <field name=\"product_id\"/>\n                <field name=\"product_categ_id\" filter_domain=\"[(''product_categ_id'', ''child_of'', self)]\"/>\n                <group expand=\"1\" string=\"Group By\">\n                    <filter string=\"Salesperson\" name=\"user\" context=\"{''group_by'':''invoice_user_id''}\"/>\n                    <filter string=\"Partner\" name=\"partner_id\" context=\"{''group_by'':''partner_id'',''residual_visible'':True}\"/>\n                    <filter string=\"Product Category\" name=\"category_product\" context=\"{''group_by'':''product_categ_id'',''residual_invisible'':True}\"/>\n                    <filter string=\"Status\" name=\"status\" context=\"{''group_by'':''state''}\"/>\n                    <filter string=\"Company\" name=\"company\" context=\"{''group_by'':''company_id''}\" groups=\"base.group_multi_company\"/>\n                    <separator orientation=\"vertical\"/>\n                    <filter string=\"Date\" name=\"invoice_date\" context=\"{''group_by'':''invoice_date''}\" invisible=\"context.get(''invoice_report_view_hide_invoice_date'')\"/>\n                    <filter string=\"Date\" name=\"group_by_invoice_date_week\" context=\"{''group_by'':''invoice_date:week''}\" invisible=\"not context.get(''invoice_report_view_hide_invoice_date'')\"/>\n                    <filter string=\"Due Date\" name=\"duemonth\" context=\"{''group_by'':''invoice_date_due:month''}\"/>\n                </group>\n            </search>"}', '<?xml version="1.0"?>
<search string="Invoices Analysis">
                <filter string="My Invoices" name="my_invoice" domain="[(''invoice_user_id'', ''='', uid)]"/>
                <separator/>
                <field name="invoice_date"/>
                <separator/>
                <filter string="To Invoice" name="toinvoice" domain="[(''state'',''='',''draft'')]" help="Draft Invoices"/>
                <filter string="Invoiced" name="current" domain="[(''state'',''not in'', (''draft'',''cancel''))]"/>
                <separator/>
                <filter string="Customers" name="customer" domain="[''|'', (''move_type'',''='',''out_invoice''),(''move_type'',''='',''out_refund'')]"/>
                <filter string="Vendors" name="supplier" domain="[''|'', (''move_type'',''='',''in_invoice''),(''move_type'',''='',''in_refund'')]"/>
                <separator/>
                <filter string="Invoices" name="invoice" domain="[''|'', (''move_type'',''='',''out_invoice''),(''move_type'',''='',''in_invoice'')]"/>
                <filter string="Credit Notes" name="creditnote" domain="[''|'', (''move_type'',''='',''out_refund''),(''move_type'',''='',''in_refund'')]"/>
                <separator/>
                <filter name="filter_invoice_date" date="invoice_date"/>
                <filter name="invoice_date_due" date="invoice_date_due"/>
                <field name="partner_id" operator="child_of"/>
                <field name="invoice_user_id"/>
                <field name="product_id"/>
                <field name="product_categ_id" filter_domain="[(''product_categ_id'', ''child_of'', self)]"/>
                <group expand="1" string="Group By">
                    <filter string="Salesperson" name="user" context="{''group_by'':''invoice_user_id''}"/>
                    <filter string="Partner" name="partner_id" context="{''group_by'':''partner_id'',''residual_visible'':True}"/>
                    <filter string="Product Category" name="category_product" context="{''group_by'':''product_categ_id'',''residual_invisible'':True}"/>
                    <filter string="Status" name="status" context="{''group_by'':''state''}"/>
                    <filter string="Company" name="company" context="{''group_by'':''company_id''}" groups="base.group_multi_company"/>
                    <separator orientation="vertical"/>
                    <filter string="Date" name="invoice_date" context="{''group_by'':''invoice_date''}" invisible="context.get(''invoice_report_view_hide_invoice_date'')"/>
                    <filter string="Date" name="group_by_invoice_date_week" context="{''group_by'':''invoice_date:week''}" invisible="not context.get(''invoice_report_view_hide_invoice_date'')"/>
                    <filter string="Due Date" name="duemonth" context="{''group_by'':''invoice_date_due:month''}"/>
                </group>
            </search>
        ', false, true, '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295', false);
INSERT INTO public.ir_ui_view VALUES (761, 16, NULL, 1, 1, 'account.cash.rounding.form', 'account.cash.rounding', NULL, 'form', 'account/views/account_cash_rounding_view.xml', 'primary', '{"en_US": "<form string=\"Rounding Form\">\n                    <sheet>\n                        <div class=\"oe_title\">\n                            <label for=\"name\"/>\n                            <h1><field name=\"name\" class=\"oe_inline\"/></h1>\n                        </div>\n                        <group>\n                            <group>\n                                <field name=\"rounding\"/>\n                                <field name=\"strategy\"/>\n                                <field name=\"profit_account_id\" options=\"{''no_create'': True}\" invisible=\"strategy != ''add_invoice_line''\" required=\"strategy == ''add_invoice_line''\" groups=\"account.group_account_invoice,account.group_account_readonly\" domain=\"[(''account_type'', ''not in'', (''asset_receivable'', ''liability_payable''))]\"/>\n                                <field name=\"loss_account_id\" options=\"{''no_create'': True}\" invisible=\"strategy != ''add_invoice_line''\" required=\"strategy == ''add_invoice_line''\" groups=\"account.group_account_invoice,account.group_account_readonly\" domain=\"[(''account_type'', ''not in'', (''asset_receivable'', ''liability_payable''))]\"/>\n                                <field name=\"rounding_method\"/>\n                            </group>\n                        </group>\n                    </sheet>\n                </form>"}', '<?xml version="1.0"?>
<form string="Rounding Form">
                    <sheet>
                        <div class="oe_title">
                            <label for="name"/>
                            <h1><field name="name" class="oe_inline"/></h1>
                        </div>
                        <group>
                            <group>
                                <field name="rounding"/>
                                <field name="strategy"/>
                                <field name="profit_account_id" options="{''no_create'': True}" invisible="strategy != ''add_invoice_line''" required="strategy == ''add_invoice_line''" groups="account.group_account_invoice,account.group_account_readonly" domain="[(''account_type'', ''not in'', (''asset_receivable'', ''liability_payable''))]"/>
                                <field name="loss_account_id" options="{''no_create'': True}" invisible="strategy != ''add_invoice_line''" required="strategy == ''add_invoice_line''" groups="account.group_account_invoice,account.group_account_readonly" domain="[(''account_type'', ''not in'', (''asset_receivable'', ''liability_payable''))]"/>
                                <field name="rounding_method"/>
                            </group>
                        </group>
                    </sheet>
                </form>
            ', false, true, '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295', false);
INSERT INTO public.ir_ui_view VALUES (762, 16, NULL, 1, 1, 'account.cash.rounding.search', 'account.cash.rounding', NULL, 'search', 'account/views/account_cash_rounding_view.xml', 'primary', '{"en_US": "<search>\n                    <field name=\"name\"/>\n                </search>"}', '<?xml version="1.0"?>
