INSERT INTO public.ir_ui_view VALUES (766, 16, NULL, 1, 1, 'account.fiscal.position.form', 'account.fiscal.position', NULL, 'form', 'account/views/partner_view.xml', 'primary', '{"en_US": "<form string=\"Fiscal Position\">\n                    <div groups=\"account.group_account_manager\" class=\"alert alert-info\" role=\"alert\" invisible=\"not foreign_vat_header_mode\">\n                        <div invisible=\"foreign_vat_header_mode not in (''templates_found'', ''no_template'')\">\n                            Click\n                            <button string=\"here\" type=\"object\" name=\"action_create_foreign_taxes\" class=\"oe_link\" style=\"padding: 0; vertical-align: baseline;\"/>\n                            to create the taxes for this country.\n                        </div>\n                    </div>\n\n                    <sheet>\n                    <div class=\"oe_button_box\" name=\"button_box\"/>\n                    <widget name=\"web_ribbon\" title=\"Archived\" bg_color=\"text-bg-danger\" invisible=\"active\"/>\n                    <group>\n                        <group>\n                            <field name=\"active\" invisible=\"1\"/>\n                            <field name=\"company_id\" invisible=\"1\"/>\n                            <field name=\"states_count\" invisible=\"1\"/>\n                            <field name=\"company_country_id\" invisible=\"1\"/>\n                            <field name=\"fiscal_country_codes\" invisible=\"1\"/>\n                            <field name=\"foreign_vat_header_mode\" invisible=\"1\"/>\n                            <field name=\"name\"/>\n                            <field name=\"company_id\" options=\"{''no_create'': True}\" groups=\"base.group_multi_company\"/>\n                        </group>\n                        <group>\n                            <field name=\"auto_apply\"/>\n                            <field name=\"vat_required\" invisible=\"not auto_apply\"/>\n                            <field name=\"foreign_vat\"/>\n                            <field name=\"country_group_id\" invisible=\"not auto_apply and not foreign_vat\" required=\"foreign_vat and not country_id\"/>\n                            <field name=\"country_id\" required=\"foreign_vat and not country_group_id\" options=\"{''no_open'': True, ''no_create'': True}\"/>\n                            <field name=\"state_ids\" widget=\"many2many_tags\" domain=\"[(''country_id'', ''='', country_id)]\" invisible=\"(not auto_apply and not foreign_vat) or not country_id or states_count == 0\"/>\n                            <label for=\"zip_from\" string=\"Zip Range\" invisible=\"not auto_apply or not country_id\"/>\n                            <div invisible=\"not auto_apply or not country_id\">\n                                <span> From </span>\n                                <field name=\"zip_from\" class=\"oe_inline\"/>\n                                <div class=\"oe_edit_only\"/>\n                                <span> To </span>\n                                <field name=\"zip_to\" class=\"oe_inline\"/>\n                            </div>\n                        </group>\n                    </group>\n                    <notebook>\n                        <page name=\"tax_mapping\" string=\"Tax Mapping\">\n                            <field name=\"tax_ids\" widget=\"one2many\" nolabel=\"1\" context=\"{''append_type_to_tax_name'': True}\">\n                                <tree name=\"tax_map_tree\" string=\"Tax Mapping\" editable=\"bottom\" no_open=\"1\" decoration-muted=\"tax_dest_id and not tax_dest_active\">\n                                    <field name=\"tax_dest_active\" column_invisible=\"1\"/>\n                                    <field name=\"tax_src_id\" domain=\"[                                             (''type_tax_use'', ''!='', ''none''),                                             (''country_id'', ''='', parent.company_country_id),                                             ''|'', (''company_id'', ''='', False), (''company_id'', ''parent_of'', parent.company_id)                                         ]\" context=\"{''append_type_to_tax_name'': True}\"/>\n\n                                    <field name=\"tax_dest_id\" domain=\"[                                             (''type_tax_use'', ''!='', ''none''),                                             (''country_id'', ''='', parent.country_id if parent.foreign_vat else parent.company_country_id),                                             ''|'', (''company_id'', ''='', False), (''company_id'', ''parent_of'', parent.company_id)]\" context=\"{''append_type_to_tax_name'': True}\"/>\n                                </tree>\n                                <form name=\"tax_map_form\" string=\"Tax Mapping\">\n                                    <group>\n                                        <field name=\"tax_src_id\" domain=\"[(''type_tax_use'', ''!='', ''none'')]\" context=\"{''append_type_to_tax_name'': True}\"/>\n                                        <field name=\"tax_dest_id\" domain=\"[(''type_tax_use'', ''!='', ''none'')]\" context=\"{''append_type_to_tax_name'': True}\"/>\n                                    </group>\n                                </form>\n                            </field>\n                        </page>\n                        <page name=\"account_mapping\" string=\"Account Mapping\" groups=\"account.group_account_readonly\">\n                            <field name=\"account_ids\" widget=\"one2many\" nolabel=\"1\">\n                                <tree string=\"Account Mapping\" editable=\"bottom\">\n                                    <field name=\"account_src_id\" domain=\"[''|'', ''|'', (''company_id'', ''='', False), (''company_id'', ''='', parent.company_id), (''account_type'', ''!='', ''off_balance'')]\"/>\n                                    <field name=\"account_dest_id\" domain=\"[''|'', ''|'', (''company_id'', ''='', False), (''company_id'', ''='', parent.company_id), (''account_type'', ''!='', ''off_balance'')]\"/>\n                                </tree>\n                                <form string=\"Account Mapping\">\n                                    <field name=\"account_src_id\" domain=\"[''|'', ''|'', (''company_id'', ''='', False), (''company_id'', ''='', parent.company_id), (''account_type'', ''!='', ''off_balance'')]\"/>\n                                    <field name=\"account_dest_id\" domain=\"[''|'', ''|'', (''company_id'', ''='', False), (''company_id'', ''='', parent.company_id), (''account_type'', ''!='', ''off_balance'')]\"/>\n                                </form>\n                            </field>\n                        </page>\n                    </notebook>\n                    <field name=\"note\" class=\"oe-bordered-editor\" placeholder=\"Legal Notes...\"/>\n                    </sheet>\n                </form>"}', '<?xml version="1.0"?>
<form string="Fiscal Position">
                    <div groups="account.group_account_manager" class="alert alert-info" role="alert" invisible="not foreign_vat_header_mode">
                        <div invisible="foreign_vat_header_mode not in (''templates_found'', ''no_template'')">
                            Click
                            <button string="here" type="object" name="action_create_foreign_taxes" class="oe_link" style="padding: 0; vertical-align: baseline;"/>
                            to create the taxes for this country.
                        </div>
                    </div>

                    <sheet>
                    <div class="oe_button_box" name="button_box"/>
                    <widget name="web_ribbon" title="Archived" bg_color="text-bg-danger" invisible="active"/>
                    <group>
                        <group>
                            <field name="active" invisible="1"/>
                            <field name="company_id" invisible="1"/>
                            <field name="states_count" invisible="1"/>
                            <field name="company_country_id" invisible="1"/>
                            <field name="fiscal_country_codes" invisible="1"/>
                            <field name="foreign_vat_header_mode" invisible="1"/>
                            <field name="name"/>
                            <field name="company_id" options="{''no_create'': True}" groups="base.group_multi_company"/>
                        </group>
                        <group>
                            <field name="auto_apply"/>
                            <field name="vat_required" invisible="not auto_apply"/>
                            <field name="foreign_vat"/>
                            <field name="country_group_id" invisible="not auto_apply and not foreign_vat" required="foreign_vat and not country_id"/>
                            <field name="country_id" required="foreign_vat and not country_group_id" options="{''no_open'': True, ''no_create'': True}"/>
                            <field name="state_ids" widget="many2many_tags" domain="[(''country_id'', ''='', country_id)]" invisible="(not auto_apply and not foreign_vat) or not country_id or states_count == 0"/>
                            <label for="zip_from" string="Zip Range" invisible="not auto_apply or not country_id"/>
                            <div invisible="not auto_apply or not country_id">
                                <span> From </span>
                                <field name="zip_from" class="oe_inline"/>
                                <div class="oe_edit_only"/>
                                <span> To </span>
                                <field name="zip_to" class="oe_inline"/>
                            </div>
                        </group>
                    </group>
                    <notebook>
                        <page name="tax_mapping" string="Tax Mapping">
                            <field name="tax_ids" widget="one2many" nolabel="1" context="{''append_type_to_tax_name'': True}">
                                <tree name="tax_map_tree" string="Tax Mapping" editable="bottom" no_open="1" decoration-muted="tax_dest_id and not tax_dest_active">
                                    <field name="tax_dest_active" column_invisible="1"/>
                                    <field name="tax_src_id" domain="[                                             (''type_tax_use'', ''!='', ''none''),                                             (''country_id'', ''='', parent.company_country_id),                                             ''|'', (''company_id'', ''='', False), (''company_id'', ''parent_of'', parent.company_id)                                         ]" context="{''append_type_to_tax_name'': True}"/>

                                    <field name="tax_dest_id" domain="[                                             (''type_tax_use'', ''!='', ''none''),                                             (''country_id'', ''='', parent.country_id if parent.foreign_vat else parent.company_country_id),                                             ''|'', (''company_id'', ''='', False), (''company_id'', ''parent_of'', parent.company_id)]" context="{''append_type_to_tax_name'': True}"/>
                                </tree>
                                <form name="tax_map_form" string="Tax Mapping">
                                    <group>
                                        <field name="tax_src_id" domain="[(''type_tax_use'', ''!='', ''none'')]" context="{''append_type_to_tax_name'': True}"/>
                                        <field name="tax_dest_id" domain="[(''type_tax_use'', ''!='', ''none'')]" context="{''append_type_to_tax_name'': True}"/>
                                    </group>
                                </form>
                            </field>
                        </page>
                        <page name="account_mapping" string="Account Mapping" groups="account.group_account_readonly">
                            <field name="account_ids" widget="one2many" nolabel="1">
                                <tree string="Account Mapping" editable="bottom">
                                    <field name="account_src_id" domain="[''|'', ''|'', (''company_id'', ''='', False), (''company_id'', ''='', parent.company_id), (''account_type'', ''!='', ''off_balance'')]"/>
                                    <field name="account_dest_id" domain="[''|'', ''|'', (''company_id'', ''='', False), (''company_id'', ''='', parent.company_id), (''account_type'', ''!='', ''off_balance'')]"/>
                                </tree>
                                <form string="Account Mapping">
                                    <field name="account_src_id" domain="[''|'', ''|'', (''company_id'', ''='', False), (''company_id'', ''='', parent.company_id), (''account_type'', ''!='', ''off_balance'')]"/>
                                    <field name="account_dest_id" domain="[''|'', ''|'', (''company_id'', ''='', False), (''company_id'', ''='', parent.company_id), (''account_type'', ''!='', ''off_balance'')]"/>
                                </form>
                            </field>
                        </page>
                    </notebook>
                    <field name="note" class="oe-bordered-editor" placeholder="Legal Notes..."/>
                    </sheet>
                </form>
            ', false, true, '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295', false);
INSERT INTO public.ir_ui_view VALUES (767, 16, NULL, 1, 1, 'account.fiscal.position.filter', 'account.fiscal.position', NULL, 'search', 'account/views/partner_view.xml', 'primary', '{"en_US": "<search string=\"Search Fiscal Positions\">\n                    <field name=\"name\" string=\"Fiscal Position\"/>\n                    <filter name=\"active\" string=\"Archived\" domain=\"[(''active'', ''='', False)]\"/>\n                </search>"}', '<?xml version="1.0"?>
<search string="Search Fiscal Positions">
                    <field name="name" string="Fiscal Position"/>
                    <filter name="active" string="Archived" domain="[(''active'', ''='', False)]"/>
                </search>
            ', false, true, '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295', false);
INSERT INTO public.ir_ui_view VALUES (768, 16, NULL, 1, 1, 'account.fiscal.position.tree', 'account.fiscal.position', NULL, 'tree', 'account/views/partner_view.xml', 'primary', '{"en_US": "<tree string=\"Fiscal Position\">\n                    <field name=\"sequence\" widget=\"handle\"/>\n                    <field name=\"name\"/>\n                    <field name=\"company_id\" groups=\"base.group_multi_company\" options=\"{''no_create'': True}\"/>\n                </tree>"}', '<?xml version="1.0"?>
<tree string="Fiscal Position">
                    <field name="sequence" widget="handle"/>
                    <field name="name"/>
                    <field name="company_id" groups="base.group_multi_company" options="{''no_create'': True}"/>
                </tree>
            ', false, true, '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295', false);
INSERT INTO public.ir_ui_view VALUES (769, 11, 125, 1, 1, 'partner.view.buttons', 'res.partner', NULL, 'form', 'account/views/partner_view.xml', 'extension', '{"en_US": "<data><div name=\"button_box\" position=\"inside\">\n                    <button type=\"object\" class=\"oe_stat_button\" icon=\"fa-pencil-square-o\" name=\"action_view_partner_invoices\" groups=\"account.group_account_invoice,account.group_account_readonly\" context=\"{''default_partner_id'': id}\">\n                        <div class=\"o_form_field o_stat_info\">\n                            <span class=\"o_stat_value\">\n                                <field name=\"currency_id\" invisible=\"1\"/>\n                                <field name=\"total_invoiced\" widget=\"monetary\" options=\"{''currency_field'': ''currency_id''}\"/>\n                            </span>\n                            <span class=\"o_stat_text\">Invoiced</span>\n                        </div>\n                    </button>\n                    <button class=\"oe_stat_button\" type=\"action\" name=\"285\" groups=\"account.group_account_invoice\" icon=\"fa-pencil-square-o\" help=\"Vendor Bills\" invisible=\"supplier_invoice_count == 0\">\n                        <field string=\"Vendor Bills\" name=\"supplier_invoice_count\" widget=\"statinfo\"/>\n                    </button>\n                </div>\n\n                <page name=\"internal_notes\" position=\"inside\">\n                    <group groups=\"account.group_account_invoice,account.group_account_readonly\">\n                        <group groups=\"account.group_warning_account\" col=\"2\">\n                            <separator string=\"Warning on the Invoice\" colspan=\"2\"/>\n                            <field name=\"invoice_warn\" nolabel=\"1\" colspan=\"2\" required=\"1\"/>\n                            <field name=\"invoice_warn_msg\" placeholder=\"Type a message...\" colspan=\"2\" nolabel=\"1\" invisible=\"invoice_warn in (False, ''no-message'')\" required=\"invoice_warn and invoice_warn != ''no-message''\"/>\n                        </group>\n                    </group>\n                </page>\n            </data>"}', '<?xml version="1.0"?>
<data><div name="button_box" position="inside">
                    <button type="object" class="oe_stat_button" icon="fa-pencil-square-o" name="action_view_partner_invoices" groups="account.group_account_invoice,account.group_account_readonly" context="{''default_partner_id'': id}">
                        <div class="o_form_field o_stat_info">
                            <span class="o_stat_value">
                                <field name="currency_id" invisible="1"/>
                                <field name="total_invoiced" widget="monetary" options="{''currency_field'': ''currency_id''}"/>
                            </span>
                            <span class="o_stat_text">Invoiced</span>
                        </div>
                    </button>
                    <button class="oe_stat_button" type="action" name="285" groups="account.group_account_invoice" icon="fa-pencil-square-o" help="Vendor Bills" invisible="supplier_invoice_count == 0">
                        <field string="Vendor Bills" name="supplier_invoice_count" widget="statinfo"/>
                    </button>
                </div>

                <page name="internal_notes" position="inside">
                    <group groups="account.group_account_invoice,account.group_account_readonly">
                        <group groups="account.group_warning_account" col="2">
                            <separator string="Warning on the Invoice" colspan="2"/>
                            <field name="invoice_warn" nolabel="1" colspan="2" required="1"/>
                            <field name="invoice_warn_msg" placeholder="Type a message..." colspan="2" nolabel="1" invisible="invoice_warn in (False, ''no-message'')" required="invoice_warn and invoice_warn != ''no-message''"/>
                        </group>
                    </group>
                </page>
            </data>', false, true, '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295', false);
INSERT INTO public.ir_ui_view VALUES (770, 2, 125, 1, 1, 'res.partner.property.form.inherit', 'res.partner', NULL, 'form', 'account/views/partner_view.xml', 'extension', '{"en_US": "<data><xpath expr=\"//field[@name=''company_id'']\" position=\"after\">\n                    <field name=\"fiscal_country_codes\" invisible=\"1\"/>\n                </xpath>\n                <xpath expr=\"//sheet\" position=\"before\">\n                    <div groups=\"account.group_account_invoice,account.group_account_readonly\" class=\"alert alert-warning\" role=\"alert\" invisible=\"duplicated_bank_account_partners_count == 0\">\n                        One or more Bank Accounts set on this partner are also used by other <bold><button class=\"alert-link\" type=\"object\" name=\"action_view_partner_with_same_bank\" role=\"button\" string=\"Partners\" style=\"padding: 0;vertical-align: baseline;\"/></bold>. Please make sure that this is a wanted behavior.\n                    </div>\n                </xpath>\n                <page name=\"sales_purchases\" position=\"after\">\n                    <page string=\"Invoicing\" name=\"accounting\" invisible=\"not is_company and parent_id\" groups=\"account.group_account_invoice,account.group_account_readonly\">\n                        <field name=\"duplicated_bank_account_partners_count\" invisible=\"1\"/>\n                        <field name=\"show_credit_limit\" invisible=\"1\"/>\n                        <group>\n                            <group string=\"Bank Accounts\" name=\"banks\" groups=\"account.group_account_invoice,account.group_account_readonly\">\n                                <field name=\"bank_ids\" nolabel=\"1\" colspan=\"2\" context=\"{''default_partner_id'': id}\" widget=\"auto_save_res_partner\">\n                                    <tree>\n                                        <field name=\"sequence\" widget=\"handle\"/>\n                                        <field name=\"acc_number\"/>\n                                        <field name=\"bank_id\"/>\n                                        <field name=\"allow_out_payment\"/>\n                                        <field name=\"acc_holder_name\" column_invisible=\"True\"/>\n                                    </tree>\n                                </field>\n                            </group>\n                            <group string=\"Accounting Entries\" name=\"accounting_entries\" groups=\"account.group_account_readonly\">\n                                <field name=\"currency_id\" invisible=\"1\"/>\n                                <field name=\"property_account_receivable_id\"/>\n                                <field name=\"property_account_payable_id\"/>\n                            </group>\n                            <group string=\"Credit Limits\" name=\"credit_limits\" groups=\"account.group_account_invoice,account.group_account_readonly\" invisible=\"not show_credit_limit\">\n                                <field name=\"credit\"/>\n                                <field name=\"days_sales_outstanding\"/>\n                                <label for=\"use_partner_credit_limit\"/>\n                                <div class=\"o_row\">\n                                    <field name=\"use_partner_credit_limit\"/>\n                                    <field name=\"credit_limit\" class=\"oe_inline\" widget=\"monetary\" options=\"{''currency_field'': ''currency_id''}\" invisible=\"not use_partner_credit_limit\"/>\n                                </div>\n                            </group>\n                        </group>\n                    </page>\n                    <page string=\"Invoicing\" name=\"accounting_disabled\" invisible=\"is_company or not parent_id\" groups=\"account.group_account_invoice,account.group_account_readonly\">\n                        <div>\n                            <p>Accounting-related settings are managed on <button name=\"open_commercial_entity\" type=\"object\" string=\"the parent company\" class=\"oe_link\"/></p>\n                        </div>\n                    </page>\n                </page>\n                <xpath expr=\"//group[@name=''misc'']\" position=\"before\">\n                    <group string=\"Fiscal Information\" name=\"fiscal_information\" priority=\"5\" groups=\"account.group_account_invoice,account.group_account_readonly\">\n                        <field name=\"property_account_position_id\" options=\"{''no_create'': True, ''no_open'': True}\"/>\n                    </group>\n                </xpath>\n                <group name=\"sale\" position=\"inside\">\n                    <field string=\"Payment Terms\" name=\"property_payment_term_id\" options=\"{''no_open'': True, ''no_create'': True}\" groups=\"account.group_account_invoice,account.group_account_readonly\"/>\n                </group>\n                <group name=\"purchase\" position=\"inside\">\n                    <field string=\"Payment Terms\" name=\"property_supplier_payment_term_id\" options=\"{''no_open'': True, ''no_create'': True}\" groups=\"account.group_account_invoice,account.group_account_readonly\"/>\n                </group>\n            </data>"}', '<?xml version="1.0"?>
<data><xpath expr="//field[@name=''company_id'']" position="after">
                    <field name="fiscal_country_codes" invisible="1"/>
                </xpath>
                <xpath expr="//sheet" position="before">
                    <div groups="account.group_account_invoice,account.group_account_readonly" class="alert alert-warning" role="alert" invisible="duplicated_bank_account_partners_count == 0">
                        One or more Bank Accounts set on this partner are also used by other <bold><button class="alert-link" type="object" name="action_view_partner_with_same_bank" role="button" string="Partners" style="padding: 0;vertical-align: baseline;"/></bold>. Please make sure that this is a wanted behavior.
                    </div>
                </xpath>
                <page name="sales_purchases" position="after">
                    <page string="Invoicing" name="accounting" invisible="not is_company and parent_id" groups="account.group_account_invoice,account.group_account_readonly">
                        <field name="duplicated_bank_account_partners_count" invisible="1"/>
                        <field name="show_credit_limit" invisible="1"/>
                        <group>
                            <group string="Bank Accounts" name="banks" groups="account.group_account_invoice,account.group_account_readonly">
                                <field name="bank_ids" nolabel="1" colspan="2" context="{''default_partner_id'': id}" widget="auto_save_res_partner">
                                    <tree>
                                        <field name="sequence" widget="handle"/>
                                        <field name="acc_number"/>
                                        <field name="bank_id"/>
                                        <field name="allow_out_payment"/>
                                        <field name="acc_holder_name" column_invisible="True"/>
                                    </tree>
                                </field>
                            </group>
                            <group string="Accounting Entries" name="accounting_entries" groups="account.group_account_readonly">
                                <field name="currency_id" invisible="1"/>
                                <field name="property_account_receivable_id"/>
                                <field name="property_account_payable_id"/>
                            </group>
                            <group string="Credit Limits" name="credit_limits" groups="account.group_account_invoice,account.group_account_readonly" invisible="not show_credit_limit">
                                <field name="credit"/>
                                <field name="days_sales_outstanding"/>
                                <label for="use_partner_credit_limit"/>
                                <div class="o_row">
                                    <field name="use_partner_credit_limit"/>
                                    <field name="credit_limit" class="oe_inline" widget="monetary" options="{''currency_field'': ''currency_id''}" invisible="not use_partner_credit_limit"/>
                                </div>
                            </group>
                        </group>
                    </page>
                    <page string="Invoicing" name="accounting_disabled" invisible="is_company or not parent_id" groups="account.group_account_invoice,account.group_account_readonly">
                        <div>
                            <p>Accounting-related settings are managed on <button name="open_commercial_entity" type="object" string="the parent company" class="oe_link"/></p>
                        </div>
                    </page>
                </page>
                <xpath expr="//group[@name=''misc'']" position="before">
                    <group string="Fiscal Information" name="fiscal_information" priority="5" groups="account.group_account_invoice,account.group_account_readonly">
                        <field name="property_account_position_id" options="{''no_create'': True, ''no_open'': True}"/>
                    </group>
                </xpath>
                <group name="sale" position="inside">
                    <field string="Payment Terms" name="property_payment_term_id" options="{''no_open'': True, ''no_create'': True}" groups="account.group_account_invoice,account.group_account_readonly"/>
                </group>
                <group name="purchase" position="inside">
                    <field string="Payment Terms" name="property_supplier_payment_term_id" options="{''no_open'': True, ''no_create'': True}" groups="account.group_account_invoice,account.group_account_readonly"/>
                </group>
            </data>', false, true, '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295', false);
INSERT INTO public.ir_ui_view VALUES (771, 16, 127, 1, 1, 'res.partner.search.inherit', 'res.partner', NULL, 'search', 'account/views/partner_view.xml', 'extension', '{"en_US": "<xpath expr=\"//filter[@name=''inactive'']\" position=\"before\">\n                   <field name=\"fiscal_country_codes\" invisible=\"1\"/>\n                   <filter string=\"Customer Invoices\" name=\"customer\" domain=\"[(''customer_rank'',''&gt;'', 0)]\"/>\n                   <filter string=\"Vendor Bills\" name=\"supplier\" domain=\"[(''supplier_rank'',''&gt;'', 0)]\"/>\n                   <separator/>\n                </xpath>"}', '<?xml version="1.0"?>
<xpath expr="//filter[@name=''inactive'']" position="before">
                   <field name="fiscal_country_codes" invisible="1"/>
                   <filter string="Customer Invoices" name="customer" domain="[(''customer_rank'',''&gt;'', 0)]"/>
                   <filter string="Vendor Bills" name="supplier" domain="[(''supplier_rank'',''&gt;'', 0)]"/>
                   <separator/>
                </xpath>
            ', false, true, '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295', false);
INSERT INTO public.ir_ui_view VALUES (772, 16, NULL, 1, 1, 'account.journal.dashboard.kanban', 'account.journal', NULL, 'kanban', 'account/views/account_journal_dashboard_view.xml', 'primary', '{"en_US": "<kanban create=\"false\" class=\"o_kanban_dashboard o_account_kanban\" banner_route=\"/onboarding/account_dashboard\" js_class=\"account_dashboard_kanban\">\n                <field name=\"id\"/>\n                <field name=\"name\"/>\n                <field name=\"type\"/>\n                <field name=\"color\"/>\n                <field name=\"show_on_dashboard\"/>\n                <field name=\"kanban_dashboard\"/>\n                <field name=\"activity_ids\"/>\n                <field name=\"activity_state\"/>\n                <field name=\"alias_domain_id\"/>\n                <templates>\n                    <t t-name=\"kanban-box\">\n                        <div t-attf-class=\"d-flex flex-column flex-fill\">\n                            <t t-value=\"JSON.parse(record.kanban_dashboard.raw_value)\" t-set=\"dashboard\"/>\n                            <t t-value=\"record.type.raw_value\" t-set=\"journal_type\"/>\n                            <t t-call=\"JournalTop\"/>\n                            <div t-att-class=\"''container o_kanban_card_content'' + (dashboard.is_sample_data ? '' o_sample_data'' : '''')\">\n                                <div class=\"row\">\n                                    <t t-if=\"(journal_type == ''bank'' || journal_type == ''cash'')\" t-call=\"JournalBodyBankCash\"/>\n                                    <t t-if=\"journal_type == ''sale'' || journal_type == ''purchase''\" t-call=\"JournalBodySalePurchase\"/>\n                                    <t t-if=\"journal_type == ''general''\" t-call=\"JournalMiscelaneous\"/>\n                                    <div class=\"col-12 col-sm-5 mb-3 mb-sm-0 o_kanban_primary_left\"/>\n                                    <div class=\"col-12 col-sm-7 o_kanban_primary_right\">\n                                        <t t-call=\"HasSequenceHoles\"/>\n                                    </div>\n                                </div>\n                                <div class=\"row mt-auto\">\n                                    <t t-if=\"[''bank'', ''cash'', ''sale'', ''purchase''].includes(journal_type)\" t-call=\"JournalBodyGraph\"/>\n                                </div>\n                            </div>\n                        </div>\n                    </t>\n\n                    <t t-name=\"JournalTop\">\n                        <div t-attf-class=\"o_kanban_card_header\">\n                            <div class=\"o_kanban_card_header_title\">\n                                <div class=\"o_primary\">\n                                    <a type=\"object\" name=\"open_action\"><field name=\"name\"/></a>\n                                    <t t-if=\"dashboard.show_company\">\n                                        <span groups=\"base.group_multi_company\" class=\"small\">- <field name=\"company_id\"/></span>\n                                    </t>\n                                </div>\n                                <div class=\"o_secondary\" t-att-title=\"dashboard.title\" t-if=\"journal_type == ''purchase'' &amp;&amp; record.alias_domain_id.raw_value\">\n                                    <field name=\"alias_id\"/>\n                                </div>\n                            </div>\n                        </div>\n                    </t>\n\n                    <t t-name=\"HasSequenceHoles\">\n                        <a t-if=\"dashboard.has_sequence_holes\" name=\"show_sequence_holes\" type=\"object\" class=\"text-warning\" title=\"Gaps due to canceled invoices, deleted entries or manual errors in open period.\">\n                            Gaps in the sequence\n                        </a>\n                    </t>\n\n                    <t t-name=\"kanban-menu\">\n                        <t t-value=\"JSON.parse(record.kanban_dashboard.raw_value)\" t-set=\"dashboard\"/>\n                        <t t-value=\"record.type.raw_value\" t-set=\"journal_type\"/>\n                        <div class=\"container\">\n                            <!-- For bank and cash -->\n                            <div t-if=\"journal_type == ''bank'' || journal_type == ''cash''\" class=\"row\" id=\"bank_and_cash_container\">\n                                <div class=\"col-4 o_kanban_card_manage_section o_kanban_manage_view\">\n                                    <h5 id=\"card_action_view_menus\" class=\"o_kanban_card_manage_title\">\n                                        <span role=\"separator\">View</span>\n                                    </h5>\n                                    <div id=\"action_card_statements\">\n                                        <a t-if=\"journal_type == ''bank''\" role=\"menuitem\" type=\"object\" name=\"open_action_with_context\" context=\"{''action_name'': ''action_bank_statement_tree'', ''search_default_journal'': True}\">Statements</a>\n                                        <a t-if=\"journal_type == ''cash''\" role=\"menuitem\" type=\"object\" name=\"open_action_with_context\" context=\"{''action_name'': ''action_view_bank_statement_tree'', ''search_default_journal'': True}\">Cash Registers</a>\n                                    </div>\n                                    <div>\n                                        <a role=\"menuitem\" type=\"object\" name=\"open_payments_action\">Payments</a>\n                                    </div>\n                                </div>\n\n                                <div class=\"col-4 o_kanban_card_manage_section o_kanban_manage_new\" groups=\"account.group_account_user\">\n                                    <h5 class=\"o_kanban_card_manage_title\">\n                                        <span role=\"separator\">New</span>\n                                    </h5>\n                                    <div t-if=\"journal_type == ''bank''\" name=\"bank_new_actions\">\n                                        <a role=\"menuitem\" type=\"object\" name=\"action_new_transaction\" groups=\"account.group_account_invoice\">New Transaction</a>\n                                    </div>\n                                    <div name=\"bank_customer_payment\">\n                                        <a role=\"menuitem\" type=\"object\" name=\"create_customer_payment\">Customer Payment</a>\n                                    </div>\n                                    <div>\n                                        <a role=\"menuitem\" type=\"object\" name=\"create_supplier_payment\">Vendor Payment</a>\n                                    </div>\n                                </div>\n\n                            </div>\n\n                            <!-- For purchase and sale -->\n                            <div t-if=\"journal_type == ''purchase'' || journal_type == ''sale''\" class=\"row\">\n                                <div class=\"col-4 o_kanban_card_manage_section o_kanban_manage_view\">\n                                    <h5 class=\"o_kanban_card_manage_title\">\n                                        <span>View</span>\n                                    </h5>\n                                    <div>\n                                        <a t-if=\"journal_type == ''sale''\" type=\"object\" name=\"open_action\" context=\"{''action_name'': ''action_move_out_invoice_type''}\">Invoices</a>\n                                        <a t-if=\"journal_type == ''purchase''\" type=\"object\" name=\"open_action\" context=\"{''action_name'': ''action_move_in_invoice_type''}\">Bills</a>\n                                    </div>\n                                    <div id=\"sale_purchase_refund\">\n                                        <a t-if=\"journal_type == ''sale''\" type=\"object\" name=\"open_action\" context=\"{''action_name'': ''action_move_out_refund_type''}\">Credit Notes</a>\n                                        <a t-if=\"journal_type == ''purchase''\" type=\"object\" name=\"open_action\" context=\"{''action_name'': ''action_move_in_refund_type''}\">Refund</a>\n                                    </div>\n                                    <div>\n                                        <a type=\"object\" name=\"open_action\" context=\"{''action_name'': ''action_account_moves_all_a''}\" groups=\"base.group_no_one\">Journal Items</a>\n                                    </div>\n                                </div>\n\n                                <div class=\"col-4 o_kanban_card_manage_section o_kanban_manage_new\" groups=\"account.group_account_invoice\">\n                                    <h5 class=\"o_kanban_card_manage_title\">\n                                        <span>New</span>\n                                    </h5>\n                                    <div>\n                                        <a type=\"object\" name=\"action_create_new\">\n                                            <span t-if=\"journal_type == ''sale''\">Invoice</span>\n                                            <span t-if=\"journal_type == ''purchase''\">Bill</span>\n                                        </a>\n                                    </div>\n                                    <div>\n                                        <a type=\"object\" name=\"action_create_new\" context=\"{''refund'':True}\">\n                                            <span t-if=\"journal_type == ''sale''\">Credit Note</span>\n                                            <span t-if=\"journal_type == ''purchase''\">Refund</span>\n                                        </a>\n                                    </div>\n                                    <div t-if=\"journal_type == ''sale''\">\n                                        <widget name=\"account_file_uploader\" title=\"Upload Invoices\" btnClass=\"file_upload_kanban_action_a\"/>\n                                    </div>\n                                </div>\n\n                                <div class=\"col-4 o_kanban_card_manage_section o_kanban_manage_reports\">\n                                    <h5 class=\"o_kanban_card_manage_title\">\n                                        <span>Reporting</span>\n                                    </h5>\n                                    <div>\n                                        <a t-if=\"journal_type == ''sale''\" type=\"action\" name=\"281\" groups=\"account.group_account_readonly\">Invoices Analysis</a>\n                                        <a t-if=\"journal_type == ''purchase''\" type=\"action\" name=\"280\" groups=\"account.group_account_readonly\">Bills Analysis</a>\n                                    </div>\n                                </div>\n                            </div>\n\n                            <!-- For general and situation -->\n                            <div t-if=\"journal_type == ''general'' || journal_type == ''situation''\" class=\"row\">\n                                <div class=\"col-4 o_kanban_card_manage_section o_kanban_manage_view\">\n                                    <h5 class=\"o_kanban_card_manage_title\">\n                                        <span>View</span>\n                                    </h5>\n                                    <div>\n                                        <a type=\"object\" name=\"open_action\" context=\"{''action_name'': ''action_move_journal_line''}\">Journal Entries</a>\n                                    </div>\n                                    <div>\n                                        <a type=\"object\" name=\"open_action\" context=\"{''action_name'': ''action_move_journal_line'', ''search_default_unposted'': 1}\">Entries to Review</a>\n                                    </div>\n                                    <div>\n                                        <a type=\"object\" name=\"open_action\" context=\"{''action_name'': ''action_account_moves_all_a''}\" groups=\"base.group_no_one\">Journal Items</a>\n                                    </div>\n                                </div>\n\n                                <div class=\"col-4 o_kanban_card_manage_section o_kanban_manage_new\" groups=\"account.group_account_user\">\n                                    <h5 class=\"o_kanban_card_manage_title\">\n                                        <span>New</span>\n                                    </h5>\n                                    <div>\n                                        <a type=\"object\" name=\"action_create_new\">Journal Entry</a>\n                                    </div>\n                                </div>\n\n                                <div class=\"col-4 o_kanban_card_manage_section o_kanban_manage_operations\">\n                                    <h5 class=\"o_kanban_card_manage_title\">\n                                        <span>Operations</span>\n                                    </h5>\n                                    <div>\n                                        <a type=\"object\" name=\"open_action_with_context\" context=\"{''action_name'': ''action_validate_account_move'', ''search_default_journal'': True}\" groups=\"account.group_account_user\">Post All Entries</a>\n                                    </div>\n                                </div>\n                            </div>\n\n                            <div t-if=\"widget.editable\" class=\"o_kanban_card_manage_settings row\">\n                                <div class=\"col-8\">\n                                    <ul class=\"oe_kanban_colorpicker\" data-field=\"color\"/>\n                                </div>\n                            </div>\n\n                            <div groups=\"account.group_account_manager\" class=\"row o_kanban_card_manage_settings\">\n                                <field name=\"show_on_dashboard\" widget=\"boolean_favorite\" class=\"col-6\"/>\n                                <div class=\"col-6 text-end\">\n                                    <a class=\"dropdown-item\" t-if=\"widget.editable\" type=\"edit\">Configuration</a>\n                                </div>\n                            </div>\n                        </div>\n                    </t>\n\n                    <t t-name=\"JournalMiscelaneous\">\n                        <div class=\"col-12 col-sm-4 mb-3 mb-sm-0 o_kanban_primary_left\">\n                            <button id=\"new_misc_entry_button\" type=\"object\" name=\"action_create_new\" class=\"btn btn-primary\" groups=\"account.group_account_invoice\">\n                                <span>New Entry</span>\n                            </button>\n                        </div>\n                        <div class=\"col-12 col-sm-8 o_kanban_primary_right\">\n                            <field name=\"json_activity_data\" widget=\"kanban_vat_activity\"/>\n                            <t t-if=\"dashboard.number_to_check &gt; 0\">\n                                <div class=\"row\">\n                                    <div class=\"col overflow-hidden text-start\">\n                                        <a type=\"object\" name=\"open_action\" context=\"{''action_name'': ''action_move_journal_line'', ''search_default_to_check'': True}\"><t t-out=\"dashboard.number_to_check\"/> to check</a>\n                                    </div>\n                                    <div class=\"col-auto text-end\">\n                                        <span class=\"o_kanban_monetary\"><t t-out=\"dashboard.to_check_balance\"/></span>\n                                    </div>\n                                </div>\n                            </t>\n                        </div>\n                    </t>\n\n                    <t t-name=\"JournalBodyBankCash\">\n                        <!-- On the left, display :\n                            - A button corresponding to the bank_statements_source, if it wasn''t configured, a button for each of them\n                            - If there are statements to reconcile, a link to reconcile them -->\n                        <div id=\"dashboard_bank_cash_left\" class=\"col-12 col-sm-5 mb-3 mb-sm-0 o_kanban_primary_left\">\n                            <t t-if=\"journal_type == ''bank''\">\n                                <t t-if=\"[''undefined'', ''online_sync''].includes(dashboard.bank_statements_source)\">\n                                    <button name=\"action_configure_bank_journal\" type=\"object\" class=\"btn btn-primary\" groups=\"account.group_account_invoice\">Connect</button>\n                                </t>\n                                <div id=\"transactions\" class=\"d-flex mt-3 mt-sm-0\" style=\"gap: 5px;\">\n                                    <div name=\"bank_journal_cta\" class=\"w-100\">\n                                        <div t-if=\"[''undefined'', ''file_import''].includes(dashboard.bank_statements_source)\" name=\"bank_journal_transactions\" class=\"w-100 d-flex\" style=\"gap: 5px;\">\n                                            <a id=\"create_transaction\" name=\"action_new_transaction\" type=\"object\" groups=\"account.group_account_invoice\">New Transaction</a>\n                                        </div>\n                                    </div>\n                                </div>\n                            </t>\n                            <t t-if=\"journal_type == ''cash''\">\n                                <button t-if=\"dashboard.number_to_reconcile == 0\" type=\"object\" name=\"action_new_transaction\" class=\"btn btn-primary\" groups=\"account.group_account_invoice\">New Transaction</button>\n                                <a t-if=\"dashboard.number_to_reconcile &gt; 0\" type=\"object\" name=\"action_new_transaction\" class=\"oe_inline\" groups=\"account.group_account_invoice\">New Transaction</a>\n                            </t>\n                        </div>\n                        <!-- On the right, show other common informations/actions -->\n                        <div id=\"dashboard_bank_cash_right\" class=\"col-12 col-sm-7 o_kanban_primary_right\">\n                            <div class=\"row\" t-if=\"dashboard.nb_lines_bank_account_balance &gt; 0\">\n                                <div id=\"dashboard_bank_cash_balance\" class=\"col overflow-hidden text-start\">\n                                    <span>Balance</span>\n                                </div>\n                                <div class=\"col-auto text-end\">\n                                    <span class=\"o_kanban_monetary\"><t t-out=\"dashboard.account_balance\"/></span>\n                                </div>\n                            </div>\n                            <t t-if=\"dashboard.has_at_least_one_statement and dashboard.account_balance != dashboard.last_balance\">\n                                <div class=\"row\" name=\"latest_statement\">\n                                    <div class=\"col overflow-hidden text-start\">\n                                        <span title=\"Latest Statement\">Last Statement</span>\n                                    </div>\n                                    <div class=\"col-auto text-end\">\n                                        <span class=\"o_kanban_monetary\"><t t-out=\"dashboard.last_balance\"/></span>\n                                    </div>\n                                </div>\n                            </t>\n                            <div class=\"row\" t-if=\"dashboard.nb_lines_outstanding_pay_account_balance &gt; 0\">\n                                <div id=\"dashboard_bank_cash_outstanding_balance\" class=\"col overflow-hidden text-start\">\n                                    <span title=\"Outstanding Payments/Receipts\">Payments</span>\n                                </div>\n                                <div class=\"col-auto text-end\">\n                                    <span><t t-out=\"dashboard.outstanding_pay_account_balance\"/></span>\n                                </div>\n                            </div>\n                            <div class=\"row\" t-if=\"dashboard.nb_misc_operations &gt; 0\">\n                                <div id=\"dashboard_bank_cash_misc_total\" class=\"col text-start\">\n                                    <a type=\"object\" name=\"open_bank_difference_action\" t-att-class=\"dashboard.misc_class\">Misc. Operations</a>\n                                </div>\n                                <div class=\"col-auto text-end\">\n                                    <span><t t-out=\"dashboard.misc_operations_balance\"/></span>\n                                </div>\n                            </div>\n                        </div>\n                    </t>\n                    <t t-name=\"JournalBodySalePurchase\" id=\"account.JournalBodySalePurchase\">\n                        <div class=\"col-12 col-sm-5 mb-3 mb-sm-0 o_kanban_primary_left\">\n                            <t t-if=\"journal_type == ''sale''\">\n                                <button type=\"object\" name=\"action_create_new\" class=\"btn btn-primary o_invoice_new\" groups=\"account.group_account_invoice\">\n                                    <span>New Invoice</span>\n                                </button>\n                            </t>\n                            <t t-if=\"journal_type == ''purchase''\">\n                                <t t-if=\"dashboard.entries_count &gt; 0\">\n                                    <widget name=\"account_file_uploader\" btnClass=\"btn btn-primary oe_kanban_action_button\"/>\n                                </t>\n                                <t t-else=\"\">\n                                    <button type=\"object\" name=\"action_create_vendor_bill\" class=\"btn btn-primary d-block\" journal_type=\"purchase\" groups=\"account.group_account_invoice\">\n                                        <span>Upload</span>\n                                    </button>\n                                </t>\n                                <a type=\"object\" name=\"action_create_new\" class=\"o_invoice_new\" groups=\"account.group_account_invoice\">Create Manually</a>\n                            </t>\n                        </div>\n                        <div class=\"col-12 col-sm-7 o_kanban_primary_right\">\n                            <div class=\"row\" t-if=\"dashboard.number_draft\">\n                                <div class=\"col overflow-hidden text-start\">\n                                    <a t-if=\"journal_type == ''sale''\" type=\"object\" name=\"open_action\" context=\"{''search_default_draft'': ''1''}\">\n                                        <span title=\"Invoices to Validate\"><t t-out=\"dashboard.number_draft\"/> Invoices to Validate</span>\n                                    </a>\n                                    <a t-if=\"journal_type == ''purchase''\" type=\"object\" name=\"open_action\" context=\"{''search_default_draft'': ''1''}\">\n                                        <span title=\"Bills to Validate\" id=\"account_dashboard_purchase_draft\"><t t-out=\"dashboard.number_draft\"/> Bills to Validate</span>\n                                    </a>\n                                </div>\n                                <div class=\"col-auto text-end\">\n                                    <span class=\"o_kanban_monetary\"><t t-out=\"dashboard.sum_draft\"/></span>\n                                </div>\n                            </div>\n                            <div class=\"row\" t-if=\"dashboard.number_waiting\">\n                                <div class=\"col overflow-hidden text-start\">\n                                    <a type=\"object\" t-if=\"journal_type == ''sale''\" name=\"open_action\" context=\"{''search_default_open'':1, ''search_default_posted'':1, ''search_default_partial'': 1}\" id=\"account_dashboard_sale_pay_link\">\n                                        <t t-out=\"dashboard.number_waiting\"/> Unpaid Invoices\n                                    </a>\n                                    <a type=\"object\" name=\"open_action\" t-if=\"journal_type == ''purchase''\" context=\"{''action_name'': ''action_open_payment_items'', ''search_default_purchases'': ''1''}\">\n                                        <t t-out=\"dashboard.number_waiting\"/> Bills to Pay\n                                    </a>\n                                </div>\n                                <div class=\"col-auto text-end\">\n                                    <span class=\"o_kanban_monetary\"><t t-out=\"dashboard.sum_waiting\"/></span>\n                                </div>\n                            </div>\n                            <div class=\"row\" t-if=\"dashboard.number_late\">\n                                <div class=\"col overflow-hidden text-start\">\n                                    <a type=\"object\" name=\"open_action\" t-if=\"journal_type == ''sale''\" context=\"{''search_default_late'': ''1''}\">\n                                        <span><t t-out=\"dashboard.number_late\"/> Late Invoices</span>\n                                    </a>\n                                    <a type=\"object\" t-if=\"journal_type == ''purchase''\" name=\"open_action\" context=\"{''action_name'': ''action_open_payment_items'', ''search_default_purchases'': ''1'', ''search_default_late'': ''1''}\">\n                                        <span><t t-out=\"dashboard.number_late\"/> Late Bills</span>\n                                    </a>\n                                </div>\n                                <div class=\"col-auto text-end\">\n                                    <span class=\"o_kanban_monetary\"><t t-out=\"dashboard.sum_late\"/></span>\n                                </div>\n                            </div>\n                            <t t-if=\"dashboard.number_to_check &gt; 0\">\n                                <div class=\"row\">\n                                    <div class=\"col overflow-hidden text-start\">\n                                        <a type=\"object\" name=\"open_action\" context=\"{''search_default_to_check'': True}\"><t t-out=\"dashboard.number_to_check\"/> to check</a>\n                                    </div>\n                                    <div class=\"col-auto text-end\">\n                                        <span class=\"o_kanban_monetary\"><t t-out=\"dashboard.to_check_balance\"/></span>\n                                    </div>\n                                </div>\n                            </t>\n                        </div>\n                    </t>\n                    <t t-name=\"JournalBodyGraph\">\n                        <field name=\"kanban_dashboard_graph\" t-att-graph_type=\"[''cash'',''bank''].includes(journal_type) ? ''line'' : ''bar''\" widget=\"dashboard_graph\"/>\n                    </t>\n            </templates>\n            </kanban>"}', '<?xml version="1.0"?>
<kanban create="false" class="o_kanban_dashboard o_account_kanban" banner_route="/onboarding/account_dashboard" js_class="account_dashboard_kanban">
                <field name="id"/>
                <field name="name"/>
                <field name="type"/>
                <field name="color"/>
                <field name="show_on_dashboard"/>
                <field name="kanban_dashboard"/>
                <field name="activity_ids"/>
                <field name="activity_state"/>
                <field name="alias_domain_id"/>
                <templates>
                    <t t-name="kanban-box">
                        <div t-attf-class="d-flex flex-column flex-fill">
                            <t t-value="JSON.parse(record.kanban_dashboard.raw_value)" t-set="dashboard"/>
                            <t t-value="record.type.raw_value" t-set="journal_type"/>
                            <t t-call="JournalTop"/>
                            <div t-att-class="''container o_kanban_card_content'' + (dashboard.is_sample_data ? '' o_sample_data'' : '''')">
                                <div class="row">
                                    <t t-if="(journal_type == ''bank'' || journal_type == ''cash'')" t-call="JournalBodyBankCash"/>
                                    <t t-if="journal_type == ''sale'' || journal_type == ''purchase''" t-call="JournalBodySalePurchase"/>
                                    <t t-if="journal_type == ''general''" t-call="JournalMiscelaneous"/>
                                    <div class="col-12 col-sm-5 mb-3 mb-sm-0 o_kanban_primary_left"/>
                                    <div class="col-12 col-sm-7 o_kanban_primary_right">
                                        <t t-call="HasSequenceHoles"/>
                                    </div>
                                </div>
                                <div class="row mt-auto">
                                    <t t-if="[''bank'', ''cash'', ''sale'', ''purchase''].includes(journal_type)" t-call="JournalBodyGraph"/>
                                </div>
                            </div>
                        </div>
                    </t>

                    <t t-name="JournalTop">
                        <div t-attf-class="o_kanban_card_header">
                            <div class="o_kanban_card_header_title">
                                <div class="o_primary">
                                    <a type="object" name="open_action"><field name="name"/></a>
                                    <t t-if="dashboard.show_company">
                                        <span groups="base.group_multi_company" class="small">- <field name="company_id"/></span>
                                    </t>
                                </div>
                                <div class="o_secondary" t-att-title="dashboard.title" t-if="journal_type == ''purchase'' &amp;&amp; record.alias_domain_id.raw_value">
                                    <field name="alias_id"/>
                                </div>
                            </div>
                        </div>
                    </t>

                    <t t-name="HasSequenceHoles">
                        <a t-if="dashboard.has_sequence_holes" name="show_sequence_holes" type="object" class="text-warning" title="Gaps due to canceled invoices, deleted entries or manual errors in open period.">
                            Gaps in the sequence
                        </a>
                    </t>

                    <t t-name="kanban-menu">
                        <t t-value="JSON.parse(record.kanban_dashboard.raw_value)" t-set="dashboard"/>
                        <t t-value="record.type.raw_value" t-set="journal_type"/>
                        <div class="container">
                            <!-- For bank and cash -->
                            <div t-if="journal_type == ''bank'' || journal_type == ''cash''" class="row" id="bank_and_cash_container">
                                <div class="col-4 o_kanban_card_manage_section o_kanban_manage_view">
                                    <h5 id="card_action_view_menus" class="o_kanban_card_manage_title">
                                        <span role="separator">View</span>
                                    </h5>
                                    <div id="action_card_statements">
                                        <a t-if="journal_type == ''bank''" role="menuitem" type="object" name="open_action_with_context" context="{''action_name'': ''action_bank_statement_tree'', ''search_default_journal'': True}">Statements</a>
                                        <a t-if="journal_type == ''cash''" role="menuitem" type="object" name="open_action_with_context" context="{''action_name'': ''action_view_bank_statement_tree'', ''search_default_journal'': True}">Cash Registers</a>
                                    </div>
                                    <div>
                                        <a role="menuitem" type="object" name="open_payments_action">Payments</a>
                                    </div>
                                </div>

                                <div class="col-4 o_kanban_card_manage_section o_kanban_manage_new" groups="account.group_account_user">
                                    <h5 class="o_kanban_card_manage_title">
                                        <span role="separator">New</span>
                                    </h5>
                                    <div t-if="journal_type == ''bank''" name="bank_new_actions">
                                        <a role="menuitem" type="object" name="action_new_transaction" groups="account.group_account_invoice">New Transaction</a>
                                    </div>
                                    <div name="bank_customer_payment">
                                        <a role="menuitem" type="object" name="create_customer_payment">Customer Payment</a>
                                    </div>
                                    <div>
                                        <a role="menuitem" type="object" name="create_supplier_payment">Vendor Payment</a>
                                    </div>
                                </div>

                            </div>

                            <!-- For purchase and sale -->
                            <div t-if="journal_type == ''purchase'' || journal_type == ''sale''" class="row">
                                <div class="col-4 o_kanban_card_manage_section o_kanban_manage_view">
                                    <h5 class="o_kanban_card_manage_title">
                                        <span>View</span>
                                    </h5>
                                    <div>
                                        <a t-if="journal_type == ''sale''" type="object" name="open_action" context="{''action_name'': ''action_move_out_invoice_type''}">Invoices</a>
                                        <a t-if="journal_type == ''purchase''" type="object" name="open_action" context="{''action_name'': ''action_move_in_invoice_type''}">Bills</a>
                                    </div>
                                    <div id="sale_purchase_refund">
                                        <a t-if="journal_type == ''sale''" type="object" name="open_action" context="{''action_name'': ''action_move_out_refund_type''}">Credit Notes</a>
                                        <a t-if="journal_type == ''purchase''" type="object" name="open_action" context="{''action_name'': ''action_move_in_refund_type''}">Refund</a>
                                    </div>
                                    <div>
                                        <a type="object" name="open_action" context="{''action_name'': ''action_account_moves_all_a''}" groups="base.group_no_one">Journal Items</a>
                                    </div>
                                </div>

                                <div class="col-4 o_kanban_card_manage_section o_kanban_manage_new" groups="account.group_account_invoice">
                                    <h5 class="o_kanban_card_manage_title">
                                        <span>New</span>
                                    </h5>
                                    <div>
                                        <a type="object" name="action_create_new">
                                            <span t-if="journal_type == ''sale''">Invoice</span>
                                            <span t-if="journal_type == ''purchase''">Bill</span>
                                        </a>
                                    </div>
                                    <div>
                                        <a type="object" name="action_create_new" context="{''refund'':True}">
                                            <span t-if="journal_type == ''sale''">Credit Note</span>
                                            <span t-if="journal_type == ''purchase''">Refund</span>
                                        </a>
                                    </div>
                                    <div t-if="journal_type == ''sale''">
                                        <widget name="account_file_uploader" title="Upload Invoices" btnClass="file_upload_kanban_action_a"/>
                                    </div>
                                </div>

                                <div class="col-4 o_kanban_card_manage_section o_kanban_manage_reports">
                                    <h5 class="o_kanban_card_manage_title">
                                        <span>Reporting</span>
                                    </h5>
                                    <div>
                                        <a t-if="journal_type == ''sale''" type="action" name="281" groups="account.group_account_readonly">Invoices Analysis</a>
                                        <a t-if="journal_type == ''purchase''" type="action" name="280" groups="account.group_account_readonly">Bills Analysis</a>
                                    </div>
                                </div>
                            </div>

                            <!-- For general and situation -->
                            <div t-if="journal_type == ''general'' || journal_type == ''situation''" class="row">
                                <div class="col-4 o_kanban_card_manage_section o_kanban_manage_view">
                                    <h5 class="o_kanban_card_manage_title">
                                        <span>View</span>
                                    </h5>
                                    <div>
                                        <a type="object" name="open_action" context="{''action_name'': ''action_move_journal_line''}">Journal Entries</a>
                                    </div>
                                    <div>
                                        <a type="object" name="open_action" context="{''action_name'': ''action_move_journal_line'', ''search_default_unposted'': 1}">Entries to Review</a>
                                    </div>
                                    <div>
                                        <a type="object" name="open_action" context="{''action_name'': ''action_account_moves_all_a''}" groups="base.group_no_one">Journal Items</a>
                                    </div>
                                </div>

                                <div class="col-4 o_kanban_card_manage_section o_kanban_manage_new" groups="account.group_account_user">
                                    <h5 class="o_kanban_card_manage_title">
                                        <span>New</span>
                                    </h5>
                                    <div>
                                        <a type="object" name="action_create_new">Journal Entry</a>
                                    </div>
                                </div>

                                <div class="col-4 o_kanban_card_manage_section o_kanban_manage_operations">
                                    <h5 class="o_kanban_card_manage_title">
                                        <span>Operations</span>
                                    </h5>
                                    <div>
                                        <a type="object" name="open_action_with_context" context="{''action_name'': ''action_validate_account_move'', ''search_default_journal'': True}" groups="account.group_account_user">Post All Entries</a>
                                    </div>
                                </div>
                            </div>

                            <div t-if="widget.editable" class="o_kanban_card_manage_settings row">
                                <div class="col-8">
                                    <ul class="oe_kanban_colorpicker" data-field="color"/>
                                </div>
                            </div>

                            <div groups="account.group_account_manager" class="row o_kanban_card_manage_settings">
                                <field name="show_on_dashboard" widget="boolean_favorite" class="col-6"/>
                                <div class="col-6 text-end">
                                    <a class="dropdown-item" t-if="widget.editable" type="edit">Configuration</a>
                                </div>
                            </div>
                        </div>
                    </t>

                    <t t-name="JournalMiscelaneous">
                        <div class="col-12 col-sm-4 mb-3 mb-sm-0 o_kanban_primary_left">
                            <button id="new_misc_entry_button" type="object" name="action_create_new" class="btn btn-primary" groups="account.group_account_invoice">
                                <span>New Entry</span>
                            </button>
                        </div>
                        <div class="col-12 col-sm-8 o_kanban_primary_right">
                            <field name="json_activity_data" widget="kanban_vat_activity"/>
                            <t t-if="dashboard.number_to_check &gt; 0">
                                <div class="row">
                                    <div class="col overflow-hidden text-start">
                                        <a type="object" name="open_action" context="{''action_name'': ''action_move_journal_line'', ''search_default_to_check'': True}"><t t-out="dashboard.number_to_check"/> to check</a>
                                    </div>
                                    <div class="col-auto text-end">
                                        <span class="o_kanban_monetary"><t t-out="dashboard.to_check_balance"/></span>
                                    </div>
                                </div>
                            </t>
                        </div>
                    </t>

                    <t t-name="JournalBodyBankCash">
                        <!-- On the left, display :
                            - A button corresponding to the bank_statements_source, if it wasn''t configured, a button for each of them
                            - If there are statements to reconcile, a link to reconcile them -->
                        <div id="dashboard_bank_cash_left" class="col-12 col-sm-5 mb-3 mb-sm-0 o_kanban_primary_left">
                            <t t-if="journal_type == ''bank''">
                                <t t-if="[''undefined'', ''online_sync''].includes(dashboard.bank_statements_source)">
                                    <button name="action_configure_bank_journal" type="object" class="btn btn-primary" groups="account.group_account_invoice">Connect</button>
                                </t>
                                <div id="transactions" class="d-flex mt-3 mt-sm-0" style="gap: 5px;">
                                    <div name="bank_journal_cta" class="w-100">
                                        <div t-if="[''undefined'', ''file_import''].includes(dashboard.bank_statements_source)" name="bank_journal_transactions" class="w-100 d-flex" style="gap: 5px;">
                                            <a id="create_transaction" name="action_new_transaction" type="object" groups="account.group_account_invoice">New Transaction</a>
                                        </div>
                                    </div>
                                </div>
                            </t>
                            <t t-if="journal_type == ''cash''">
                                <button t-if="dashboard.number_to_reconcile == 0" type="object" name="action_new_transaction" class="btn btn-primary" groups="account.group_account_invoice">New Transaction</button>
                                <a t-if="dashboard.number_to_reconcile &gt; 0" type="object" name="action_new_transaction" class="oe_inline" groups="account.group_account_invoice">New Transaction</a>
                            </t>
                        </div>
                        <!-- On the right, show other common informations/actions -->
                        <div id="dashboard_bank_cash_right" class="col-12 col-sm-7 o_kanban_primary_right">
                            <div class="row" t-if="dashboard.nb_lines_bank_account_balance &gt; 0">
                                <div id="dashboard_bank_cash_balance" class="col overflow-hidden text-start">
                                    <span>Balance</span>
                                </div>
                                <div class="col-auto text-end">
                                    <span class="o_kanban_monetary"><t t-out="dashboard.account_balance"/></span>
                                </div>
                            </div>
                            <t t-if="dashboard.has_at_least_one_statement and dashboard.account_balance != dashboard.last_balance">
                                <div class="row" name="latest_statement">
                                    <div class="col overflow-hidden text-start">
                                        <span title="Latest Statement">Last Statement</span>
                                    </div>
                                    <div class="col-auto text-end">
                                        <span class="o_kanban_monetary"><t t-out="dashboard.last_balance"/></span>
                                    </div>
                                </div>
                            </t>
                            <div class="row" t-if="dashboard.nb_lines_outstanding_pay_account_balance &gt; 0">
                                <div id="dashboard_bank_cash_outstanding_balance" class="col overflow-hidden text-start">
                                    <span title="Outstanding Payments/Receipts">Payments</span>
                                </div>
                                <div class="col-auto text-end">
                                    <span><t t-out="dashboard.outstanding_pay_account_balance"/></span>
                                </div>
                            </div>
                            <div class="row" t-if="dashboard.nb_misc_operations &gt; 0">
                                <div id="dashboard_bank_cash_misc_total" class="col text-start">
                                    <a type="object" name="open_bank_difference_action" t-att-class="dashboard.misc_class">Misc. Operations</a>
                                </div>
                                <div class="col-auto text-end">
                                    <span><t t-out="dashboard.misc_operations_balance"/></span>
                                </div>
                            </div>
                        </div>
                    </t>
                    <t t-name="JournalBodySalePurchase" id="account.JournalBodySalePurchase">
                        <div class="col-12 col-sm-5 mb-3 mb-sm-0 o_kanban_primary_left">
                            <t t-if="journal_type == ''sale''">
                                <button type="object" name="action_create_new" class="btn btn-primary o_invoice_new" groups="account.group_account_invoice">
                                    <span>New Invoice</span>
                                </button>
                            </t>
                            <t t-if="journal_type == ''purchase''">
                                <t t-if="dashboard.entries_count &gt; 0">
                                    <widget name="account_file_uploader" btnClass="btn btn-primary oe_kanban_action_button"/>
                                </t>
                                <t t-else="">
                                    <button type="object" name="action_create_vendor_bill" class="btn btn-primary d-block" journal_type="purchase" groups="account.group_account_invoice">
                                        <span>Upload</span>
                                    </button>
                                </t>
                                <a type="object" name="action_create_new" class="o_invoice_new" groups="account.group_account_invoice">Create Manually</a>
                            </t>
                        </div>
                        <div class="col-12 col-sm-7 o_kanban_primary_right">
                            <div class="row" t-if="dashboard.number_draft">
                                <div class="col overflow-hidden text-start">
                                    <a t-if="journal_type == ''sale''" type="object" name="open_action" context="{''search_default_draft'': ''1''}">
                                        <span title="Invoices to Validate"><t t-out="dashboard.number_draft"/> Invoices to Validate</span>
                                    </a>
                                    <a t-if="journal_type == ''purchase''" type="object" name="open_action" context="{''search_default_draft'': ''1''}">
                                        <span title="Bills to Validate" id="account_dashboard_purchase_draft"><t t-out="dashboard.number_draft"/> Bills to Validate</span>
                                    </a>
                                </div>
                                <div class="col-auto text-end">
                                    <span class="o_kanban_monetary"><t t-out="dashboard.sum_draft"/></span>
                                </div>
                            </div>
                            <div class="row" t-if="dashboard.number_waiting">
                                <div class="col overflow-hidden text-start">
                                    <a type="object" t-if="journal_type == ''sale''" name="open_action" context="{''search_default_open'':1, ''search_default_posted'':1, ''search_default_partial'': 1}" id="account_dashboard_sale_pay_link">
                                        <t t-out="dashboard.number_waiting"/> Unpaid Invoices
                                    </a>
                                    <a type="object" name="open_action" t-if="journal_type == ''purchase''" context="{''action_name'': ''action_open_payment_items'', ''search_default_purchases'': ''1''}">
                                        <t t-out="dashboard.number_waiting"/> Bills to Pay
                                    </a>
                                </div>
                                <div class="col-auto text-end">
                                    <span class="o_kanban_monetary"><t t-out="dashboard.sum_waiting"/></span>
                                </div>
                            </div>
                            <div class="row" t-if="dashboard.number_late">
                                <div class="col overflow-hidden text-start">
                                    <a type="object" name="open_action" t-if="journal_type == ''sale''" context="{''search_default_late'': ''1''}">
                                        <span><t t-out="dashboard.number_late"/> Late Invoices</span>
                                    </a>
                                    <a type="object" t-if="journal_type == ''purchase''" name="open_action" context="{''action_name'': ''action_open_payment_items'', ''search_default_purchases'': ''1'', ''search_default_late'': ''1''}">
                                        <span><t t-out="dashboard.number_late"/> Late Bills</span>
                                    </a>
                                </div>
                                <div class="col-auto text-end">
                                    <span class="o_kanban_monetary"><t t-out="dashboard.sum_late"/></span>
                                </div>
                            </div>
                            <t t-if="dashboard.number_to_check &gt; 0">
                                <div class="row">
                                    <div class="col overflow-hidden text-start">
                                        <a type="object" name="open_action" context="{''search_default_to_check'': True}"><t t-out="dashboard.number_to_check"/> to check</a>
                                    </div>
                                    <div class="col-auto text-end">
                                        <span class="o_kanban_monetary"><t t-out="dashboard.to_check_balance"/></span>
                                    </div>
                                </div>
                            </t>
                        </div>
                    </t>
                    <t t-name="JournalBodyGraph">
                        <field name="kanban_dashboard_graph" t-att-graph_type="[''cash'',''bank''].includes(journal_type) ? ''line'' : ''bar''" widget="dashboard_graph"/>
                    </t>
            </templates>
            </kanban>
        ', false, true, '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295', false);
INSERT INTO public.ir_ui_view VALUES (857, 16, NULL, 1, 1, 'report_saleorder_document', NULL, 'sale.report_saleorder_document', 'qweb', 'sale/report/ir_actions_report_templates.xml', 'primary', '{"en_US": "<t t-name=\"sale.report_saleorder_document\">\n    <t t-call=\"web.external_layout\">\n        <t t-set=\"doc\" t-value=\"doc.with_context(lang=doc.partner_id.lang)\"/>\n        <t t-set=\"forced_vat\" t-value=\"doc.fiscal_position_id.foreign_vat\"/> <!-- So that it appears in the footer of the report instead of the company VAT if it''s set -->\n        <t t-set=\"address\">\n            <div t-field=\"doc.partner_id\" t-options=\"{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;], &quot;no_marker&quot;: True}\"/>\n            <p t-if=\"doc.partner_id.vat\">\n                <t t-if=\"doc.company_id.account_fiscal_country_id.vat_label\" t-out=\"doc.company_id.account_fiscal_country_id.vat_label\"/>\n                <t t-else=\"\">Tax ID</t>: <span t-field=\"doc.partner_id.vat\"/>\n            </p>\n        </t>\n        <t t-if=\"doc.partner_shipping_id == doc.partner_invoice_id                              and doc.partner_invoice_id != doc.partner_id                              or doc.partner_shipping_id != doc.partner_invoice_id\">\n            <t t-set=\"information_block\">\n                <strong>\n                    <t t-if=\"doc.partner_shipping_id == doc.partner_invoice_id\">\n                        Invoicing and Shipping Address:\n                    </t>\n                    <t t-else=\"\">\n                        Invoicing Address:\n                    </t>\n                </strong>\n                <div t-field=\"doc.partner_invoice_id\" t-options=\"{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;, &quot;phone&quot;], &quot;no_marker&quot;: True, &quot;phone_icons&quot;: True}\"/>\n                <t t-if=\"doc.partner_shipping_id != doc.partner_invoice_id\">\n                    <strong>Shipping Address:</strong>\n                    <div t-field=\"doc.partner_shipping_id\" t-options=\"{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;, &quot;phone&quot;], &quot;no_marker&quot;: True, &quot;phone_icons&quot;: True}\"/>\n                </t>\n            </t>\n        </t>\n        <div class=\"page\">\n            <div class=\"oe_structure\"/>\n\n            <h2 class=\"mt-4\">\n                <span t-if=\"env.context.get(''proforma'', False) or is_pro_forma\">Pro-Forma Invoice # </span>\n                <span t-elif=\"doc.state in [''draft'',''sent'']\">Quotation # </span>\n                <span t-else=\"\">Order # </span>\n                <span t-field=\"doc.name\">SO0000</span>\n            </h2>\n\n            <div class=\"row mt-4 mb-2\" id=\"informations\">\n                <div t-if=\"doc.client_order_ref\" class=\"col-auto col-3 mw-100 mb-2\" name=\"informations_reference\">\n                    <strong>Your Reference:</strong><br/>\n                    <span class=\"m-0\" t-field=\"doc.client_order_ref\">SO0000</span>\n                </div>\n                <div t-if=\"doc.date_order\" class=\"col-auto col-3 mw-100 mb-2\" name=\"informations_date\">\n                    <strong t-if=\"doc.state in [''draft'', ''sent'']\">Quotation Date:</strong>\n                    <strong t-else=\"\">Order Date:</strong><br/>\n                    <span class=\"m-0\" t-field=\"doc.date_order\" t-options=\"{&quot;widget&quot;: &quot;date&quot;}\">2023-12-31</span>\n                </div>\n                <div t-if=\"doc.validity_date and doc.state in [''draft'', ''sent'']\" class=\"col-auto col-3 mw-100 mb-2\" name=\"expiration_date\">\n                    <strong>Expiration:</strong><br/>\n                    <span class=\"m-0\" t-field=\"doc.validity_date\">2023-12-31</span>\n                </div>\n                <div t-if=\"doc.user_id.name\" class=\"col-auto col-3 mw-100 mb-2\">\n                    <strong>Salesperson:</strong><br/>\n                    <span class=\"m-0\" t-field=\"doc.user_id\">Mitchell Admin</span>\n                </div>\n            </div>\n\n            <!-- Is there a discount on at least one line? -->\n            <t t-set=\"lines_to_report\" t-value=\"doc._get_order_lines_to_report()\"/>\n            <t t-set=\"display_discount\" t-value=\"any(l.discount for l in lines_to_report)\"/>\n\n            <div class=\"oe_structure\"/>\n            <table class=\"table table-sm o_main_table table-borderless mt-4\">\n                <!-- In case we want to repeat the header, remove \"display: table-row-group\" -->\n                <thead style=\"display: table-row-group\">\n                    <tr>\n                        <th name=\"th_description\" class=\"text-start\">Description</th>\n                        <th name=\"th_quantity\" class=\"text-end\">Quantity</th>\n                        <th name=\"th_priceunit\" class=\"text-end\">Unit Price</th>\n                        <th name=\"th_discount\" t-if=\"display_discount\" class=\"text-end\">\n                            <span>Disc.%</span>\n                        </th>\n                        <th name=\"th_taxes\" class=\"text-end\">Taxes</th>\n                        <th name=\"th_subtotal\" class=\"text-end\">\n                            <span>Amount</span>\n                        </th>\n                    </tr>\n                </thead>\n                <tbody class=\"sale_tbody\">\n\n                    <t t-set=\"current_subtotal\" t-value=\"0\"/>\n\n                    <t t-foreach=\"lines_to_report\" t-as=\"line\">\n\n                        <t t-set=\"current_subtotal\" t-value=\"current_subtotal + line.price_subtotal\"/>\n\n                        <tr t-att-class=\"''bg-200 fw-bold o_line_section'' if line.display_type == ''line_section'' else ''fst-italic o_line_note'' if line.display_type == ''line_note'' else ''''\">\n                            <t t-if=\"not line.display_type\">\n                                <td name=\"td_name\"><span t-field=\"line.name\">Bacon Burger</span></td>\n                                <td name=\"td_quantity\" class=\"text-end\">\n                                    <span t-field=\"line.product_uom_qty\">3</span>\n                                    <span t-field=\"line.product_uom\">units</span>\n                                    <span t-if=\"line.product_packaging_id\">\n                                        (<span t-field=\"line.product_packaging_qty\" t-options=\"{&quot;widget&quot;: &quot;integer&quot;}\"/> <span t-field=\"line.product_packaging_id\"/>)\n                                    </span>\n                                </td>\n                                <td name=\"td_priceunit\" class=\"text-end\">\n                                    <span t-field=\"line.price_unit\">3</span>\n                                </td>\n                                <td t-if=\"display_discount\" class=\"text-end\">\n                                    <span t-field=\"line.discount\">-</span>\n                                </td>\n                                <t t-set=\"taxes\" t-value=\"'', ''.join([(tax.invoice_label or tax.name) for tax in line.tax_id])\"/>\n                                <td name=\"td_taxes\" t-attf-class=\"text-end {{ ''text-nowrap'' if len(taxes) &lt; 10 else '''' }}\">\n                                    <span t-out=\"taxes\">Tax 15%</span>\n                                </td>\n                                <td t-if=\"not line.is_downpayment\" name=\"td_subtotal\" class=\"text-end o_price_total\">\n                                    <span t-field=\"line.price_subtotal\">27.00</span>\n                                </td>\n                            </t>\n                            <t t-elif=\"line.display_type == ''line_section''\">\n                                <td name=\"td_section_line\" colspan=\"99\">\n                                    <span t-field=\"line.name\">A section title</span>\n                                </td>\n                                <t t-set=\"current_section\" t-value=\"line\"/>\n                                <t t-set=\"current_subtotal\" t-value=\"0\"/>\n                            </t>\n                            <t t-elif=\"line.display_type == ''line_note''\">\n                                <td name=\"td_note_line\" colspan=\"99\">\n                                    <span t-field=\"line.name\">A note, whose content usually applies to the section or product above.</span>\n                                </td>\n                            </t>\n                        </tr>\n\n                        <t t-if=\"current_section and (line_last or lines_to_report[line_index+1].display_type == ''line_section'') and not line.is_downpayment\">\n                            <tr class=\"is-subtotal text-end\">\n                                <td name=\"td_section_subtotal\" colspan=\"99\">\n                                    <strong class=\"mr16\">Subtotal</strong>\n                                    <span t-out=\"current_subtotal\" t-options=\"{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: doc.currency_id}\">31.05</span>\n                                </td>\n                            </tr>\n                        </t>\n                    </t>\n                </tbody>\n            </table>\n            <div class=\"clearfix\" name=\"so_total_summary\">\n                <div id=\"total\" class=\"row\" name=\"total\">\n                    <div t-attf-class=\"#{''col-6'' if report_type != ''html'' else ''col-sm-7 col-md-6''} ms-auto\">\n                        <table class=\"table table-sm table-borderless\">\n                            <!-- Tax totals -->\n                            <t t-set=\"tax_totals\" t-value=\"doc.tax_totals\"/>\n                            <t t-call=\"sale.document_tax_totals\"/>\n                        </table>\n                    </div>\n                </div>\n            </div>\n            <div class=\"oe_structure\"/>\n\n            <div t-if=\"not doc.signature\" class=\"oe_structure\"/>\n            <div t-else=\"\" class=\"mt-4 ml64 mr4\" name=\"signature\">\n                <div class=\"offset-8\">\n                    <strong>Signature</strong>\n                </div>\n                <div class=\"offset-8\">\n                    <img t-att-src=\"image_data_uri(doc.signature)\" style=\"max-height: 4cm; max-width: 8cm;\"/>\n                </div>\n                <div class=\"offset-8 text-center\">\n                    <span t-field=\"doc.signed_by\">Oscar Morgan</span>\n                </div>\n            </div>\n            <div>\n                <span t-field=\"doc.note\" t-attf-style=\"#{''text-align:justify;text-justify:inter-word;'' if doc.company_id.terms_type != ''html'' else ''''}\" name=\"order_note\"/>\n                <p t-if=\"not is_html_empty(doc.payment_term_id.note)\">\n                    <span t-field=\"doc.payment_term_id.note\">The payment should also be transmitted with love</span>\n                </p>\n                <div class=\"oe_structure\"/>\n                <p t-if=\"doc.fiscal_position_id and not is_html_empty(doc.fiscal_position_id.sudo().note)\" id=\"fiscal_position_remark\">\n                    <strong>Fiscal Position Remark:</strong>\n                    <span t-field=\"doc.fiscal_position_id.sudo().note\">No further requirements for this payment</span>\n                </p>\n            </div>\n            <div class=\"oe_structure\"/>\n        </div>\n    </t>\n</t>"}', '<?xml version="1.0"?>
<t t-name="sale.report_saleorder_document">
    <t t-call="web.external_layout">
        <t t-set="doc" t-value="doc.with_context(lang=doc.partner_id.lang)"/>
        <t t-set="forced_vat" t-value="doc.fiscal_position_id.foreign_vat"/> <!-- So that it appears in the footer of the report instead of the company VAT if it''s set -->
        <t t-set="address">
            <div t-field="doc.partner_id" t-options="{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;], &quot;no_marker&quot;: True}"/>
            <p t-if="doc.partner_id.vat">
                <t t-if="doc.company_id.account_fiscal_country_id.vat_label" t-out="doc.company_id.account_fiscal_country_id.vat_label"/>
                <t t-else="">Tax ID</t>: <span t-field="doc.partner_id.vat"/>
            </p>
        </t>
        <t t-if="doc.partner_shipping_id == doc.partner_invoice_id                              and doc.partner_invoice_id != doc.partner_id                              or doc.partner_shipping_id != doc.partner_invoice_id">
            <t t-set="information_block">
                <strong>
                    <t t-if="doc.partner_shipping_id == doc.partner_invoice_id">
                        Invoicing and Shipping Address:
                    </t>
                    <t t-else="">
                        Invoicing Address:
                    </t>
                </strong>
                <div t-field="doc.partner_invoice_id" t-options="{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;, &quot;phone&quot;], &quot;no_marker&quot;: True, &quot;phone_icons&quot;: True}"/>
                <t t-if="doc.partner_shipping_id != doc.partner_invoice_id">
                    <strong>Shipping Address:</strong>
                    <div t-field="doc.partner_shipping_id" t-options="{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;, &quot;phone&quot;], &quot;no_marker&quot;: True, &quot;phone_icons&quot;: True}"/>
                </t>
            </t>
        </t>
        <div class="page">
            <div class="oe_structure"/>

            <h2 class="mt-4">
                <span t-if="env.context.get(''proforma'', False) or is_pro_forma">Pro-Forma Invoice # </span>
                <span t-elif="doc.state in [''draft'',''sent'']">Quotation # </span>
                <span t-else="">Order # </span>
                <span t-field="doc.name">SO0000</span>
            </h2>

            <div class="row mt-4 mb-2" id="informations">
                <div t-if="doc.client_order_ref" class="col-auto col-3 mw-100 mb-2" name="informations_reference">
                    <strong>Your Reference:</strong><br/>
                    <span class="m-0" t-field="doc.client_order_ref">SO0000</span>
                </div>
                <div t-if="doc.date_order" class="col-auto col-3 mw-100 mb-2" name="informations_date">
                    <strong t-if="doc.state in [''draft'', ''sent'']">Quotation Date:</strong>
                    <strong t-else="">Order Date:</strong><br/>
                    <span class="m-0" t-field="doc.date_order" t-options="{&quot;widget&quot;: &quot;date&quot;}">2023-12-31</span>
                </div>
                <div t-if="doc.validity_date and doc.state in [''draft'', ''sent'']" class="col-auto col-3 mw-100 mb-2" name="expiration_date">
                    <strong>Expiration:</strong><br/>
                    <span class="m-0" t-field="doc.validity_date">2023-12-31</span>
                </div>
                <div t-if="doc.user_id.name" class="col-auto col-3 mw-100 mb-2">
                    <strong>Salesperson:</strong><br/>
                    <span class="m-0" t-field="doc.user_id">Mitchell Admin</span>
                </div>
            </div>

            <!-- Is there a discount on at least one line? -->
            <t t-set="lines_to_report" t-value="doc._get_order_lines_to_report()"/>
            <t t-set="display_discount" t-value="any(l.discount for l in lines_to_report)"/>

            <div class="oe_structure"/>
            <table class="table table-sm o_main_table table-borderless mt-4">
                <!-- In case we want to repeat the header, remove "display: table-row-group" -->
                <thead style="display: table-row-group">
                    <tr>
                        <th name="th_description" class="text-start">Description</th>
                        <th name="th_quantity" class="text-end">Quantity</th>
                        <th name="th_priceunit" class="text-end">Unit Price</th>
                        <th name="th_discount" t-if="display_discount" class="text-end">
                            <span>Disc.%</span>
                        </th>
                        <th name="th_taxes" class="text-end">Taxes</th>
                        <th name="th_subtotal" class="text-end">
                            <span>Amount</span>
                        </th>
                    </tr>
                </thead>
                <tbody class="sale_tbody">

                    <t t-set="current_subtotal" t-value="0"/>

                    <t t-foreach="lines_to_report" t-as="line">

                        <t t-set="current_subtotal" t-value="current_subtotal + line.price_subtotal"/>

                        <tr t-att-class="''bg-200 fw-bold o_line_section'' if line.display_type == ''line_section'' else ''fst-italic o_line_note'' if line.display_type == ''line_note'' else ''''">
                            <t t-if="not line.display_type">
                                <td name="td_name"><span t-field="line.name">Bacon Burger</span></td>
                                <td name="td_quantity" class="text-end">
                                    <span t-field="line.product_uom_qty">3</span>
                                    <span t-field="line.product_uom">units</span>
                                    <span t-if="line.product_packaging_id">
                                        (<span t-field="line.product_packaging_qty" t-options="{&quot;widget&quot;: &quot;integer&quot;}"/> <span t-field="line.product_packaging_id"/>)
                                    </span>
                                </td>
                                <td name="td_priceunit" class="text-end">
                                    <span t-field="line.price_unit">3</span>
                                </td>
                                <td t-if="display_discount" class="text-end">
                                    <span t-field="line.discount">-</span>
                                </td>
                                <t t-set="taxes" t-value="'', ''.join([(tax.invoice_label or tax.name) for tax in line.tax_id])"/>
                                <td name="td_taxes" t-attf-class="text-end {{ ''text-nowrap'' if len(taxes) &lt; 10 else '''' }}">
                                    <span t-out="taxes">Tax 15%</span>
                                </td>
                                <td t-if="not line.is_downpayment" name="td_subtotal" class="text-end o_price_total">
                                    <span t-field="line.price_subtotal">27.00</span>
                                </td>
                            </t>
                            <t t-elif="line.display_type == ''line_section''">
                                <td name="td_section_line" colspan="99">
                                    <span t-field="line.name">A section title</span>
                                </td>
                                <t t-set="current_section" t-value="line"/>
                                <t t-set="current_subtotal" t-value="0"/>
                            </t>
                            <t t-elif="line.display_type == ''line_note''">
                                <td name="td_note_line" colspan="99">
                                    <span t-field="line.name">A note, whose content usually applies to the section or product above.</span>
                                </td>
                            </t>
                        </tr>

                        <t t-if="current_section and (line_last or lines_to_report[line_index+1].display_type == ''line_section'') and not line.is_downpayment">
                            <tr class="is-subtotal text-end">
                                <td name="td_section_subtotal" colspan="99">
                                    <strong class="mr16">Subtotal</strong>
                                    <span t-out="current_subtotal" t-options="{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: doc.currency_id}">31.05</span>
                                </td>
                            </tr>
                        </t>
                    </t>
                </tbody>
            </table>
            <div class="clearfix" name="so_total_summary">
                <div id="total" class="row" name="total">
                    <div t-attf-class="#{''col-6'' if report_type != ''html'' else ''col-sm-7 col-md-6''} ms-auto">
                        <table class="table table-sm table-borderless">
                            <!-- Tax totals -->
                            <t t-set="tax_totals" t-value="doc.tax_totals"/>
                            <t t-call="sale.document_tax_totals"/>
                        </table>
                    </div>
                </div>
            </div>
            <div class="oe_structure"/>

            <div t-if="not doc.signature" class="oe_structure"/>
            <div t-else="" class="mt-4 ml64 mr4" name="signature">
                <div class="offset-8">
                    <strong>Signature</strong>
                </div>
                <div class="offset-8">
                    <img t-att-src="image_data_uri(doc.signature)" style="max-height: 4cm; max-width: 8cm;"/>
                </div>
                <div class="offset-8 text-center">
                    <span t-field="doc.signed_by">Oscar Morgan</span>
                </div>
            </div>
            <div>
                <span t-field="doc.note" t-attf-style="#{''text-align:justify;text-justify:inter-word;'' if doc.company_id.terms_type != ''html'' else ''''}" name="order_note"/>
                <p t-if="not is_html_empty(doc.payment_term_id.note)">
                    <span t-field="doc.payment_term_id.note">The payment should also be transmitted with love</span>
                </p>
                <div class="oe_structure"/>
                <p t-if="doc.fiscal_position_id and not is_html_empty(doc.fiscal_position_id.sudo().note)" id="fiscal_position_remark">
                    <strong>Fiscal Position Remark:</strong>
                    <span t-field="doc.fiscal_position_id.sudo().note">No further requirements for this payment</span>
                </p>
            </div>
            <div class="oe_structure"/>
        </div>
    </t>
</t>

', false, true, '2026-05-10 01:12:05.269262', '2026-05-10 01:12:05.269262', false);
INSERT INTO public.ir_ui_view VALUES (773, 30, 542, 1, 1, 'Portal layout : invoice menu entries', NULL, 'account.portal_my_home_menu_invoice', 'qweb', 'account/views/account_portal_templates.xml', 'extension', '{"en_US": "<data name=\"Portal layout : invoice menu entries\" inherit_id=\"portal.portal_breadcrumbs\" priority=\"30\">\n        <xpath expr=\"//ol[hasclass(''o_portal_submenu'')]\" position=\"inside\">\n            <li t-if=\"page_name == ''invoice''\" t-attf-class=\"breadcrumb-item #{''active '' if not invoice else ''''}\">\n                <a t-if=\"invoice\" t-attf-href=\"/my/invoices?{{ keep_query() }}\">Invoices &amp; Bills</a>\n                <t t-else=\"\">Invoices &amp; Bills</t>\n            </li>\n            <li t-if=\"invoice\" class=\"breadcrumb-item active\">\n                <t t-out=\"invoice.name\" t-if=\"invoice.name != ''/''\"/>\n                <t t-else=\"\"><em>Draft Invoice</em></t>\n            </li>\n        </xpath>\n    </data>"}', '<?xml version="1.0"?>
<data name="Portal layout : invoice menu entries" inherit_id="portal.portal_breadcrumbs" priority="30">
        <xpath expr="//ol[hasclass(''o_portal_submenu'')]" position="inside">
            <li t-if="page_name == ''invoice''" t-attf-class="breadcrumb-item #{''active '' if not invoice else ''''}">
                <a t-if="invoice" t-attf-href="/my/invoices?{{ keep_query() }}">Invoices &amp; Bills</a>
                <t t-else="">Invoices &amp; Bills</t>
            </li>
            <li t-if="invoice" class="breadcrumb-item active">
                <t t-out="invoice.name" t-if="invoice.name != ''/''"/>
                <t t-else=""><em>Draft Invoice</em></t>
            </li>
        </xpath>
    </data>

    ', false, true, '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295', false);
INSERT INTO public.ir_ui_view VALUES (774, 30, 548, 1, 1, 'Show Invoices & Bills', NULL, 'account.portal_my_home_invoice', 'qweb', 'account/views/account_portal_templates.xml', 'extension', '{"en_US": "<data name=\"Show Invoices &amp; Bills\" inherit_id=\"portal.portal_my_home\" customize_show=\"True\" priority=\"30\">\n        <xpath expr=\"//div[hasclass(''o_portal_docs'')]\" position=\"before\">\n            <t t-set=\"portal_client_category_enable\" t-value=\"True\"/>\n            <t t-set=\"portal_vendor_category_enable\" t-value=\"True\"/>\n        </xpath>\n        <div id=\"portal_client_category\" position=\"inside\">\n            <t t-call=\"portal.portal_docs_entry\">\n                <t t-set=\"icon\" t-value=\"''/account/static/src/img/Bill.svg''\"/>\n                <t t-set=\"title\">Your Invoices</t>\n                <t t-set=\"url\" t-value=\"''/my/invoices?filterby=invoices''\"/>\n                <t t-set=\"text\">Follow, download or pay your invoices</t>\n                <t t-set=\"placeholder_count\" t-value=\"''invoice_count''\"/>\n            </t>\n        </div>\n        <div id=\"portal_vendor_category\" position=\"inside\">\n            <t t-call=\"portal.portal_docs_entry\">\n                <t t-set=\"icon\" t-value=\"''/account/static/src/img/Bill.svg''\"/>\n                <t t-set=\"title\">Our Invoices</t>\n                <t t-set=\"url\" t-value=\"''/my/invoices?filterby=bills''\"/>\n                <t t-set=\"text\">Follow, download or pay our invoices</t>\n                <t t-set=\"placeholder_count\" t-value=\"''bill_count''\"/>\n            </t>\n        </div>\n    </data>"}', '<?xml version="1.0"?>
<data name="Show Invoices &amp; Bills" inherit_id="portal.portal_my_home" customize_show="True" priority="30">
        <xpath expr="//div[hasclass(''o_portal_docs'')]" position="before">
            <t t-set="portal_client_category_enable" t-value="True"/>
            <t t-set="portal_vendor_category_enable" t-value="True"/>
        </xpath>
        <div id="portal_client_category" position="inside">
            <t t-call="portal.portal_docs_entry">
                <t t-set="icon" t-value="''/account/static/src/img/Bill.svg''"/>
                <t t-set="title">Your Invoices</t>
                <t t-set="url" t-value="''/my/invoices?filterby=invoices''"/>
                <t t-set="text">Follow, download or pay your invoices</t>
                <t t-set="placeholder_count" t-value="''invoice_count''"/>
            </t>
        </div>
        <div id="portal_vendor_category" position="inside">
            <t t-call="portal.portal_docs_entry">
                <t t-set="icon" t-value="''/account/static/src/img/Bill.svg''"/>
                <t t-set="title">Our Invoices</t>
                <t t-set="url" t-value="''/my/invoices?filterby=bills''"/>
                <t t-set="text">Follow, download or pay our invoices</t>
                <t t-set="placeholder_count" t-value="''bill_count''"/>
            </t>
        </div>
    </data>

    ', false, true, '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295', true);
INSERT INTO public.ir_ui_view VALUES (775, 16, NULL, 1, 1, 'My Invoices and Payments', NULL, 'account.portal_my_invoices', 'qweb', 'account/views/account_portal_templates.xml', 'primary', '{"en_US": "<t name=\"My Invoices and Payments\" t-name=\"account.portal_my_invoices\">\n      <t t-call=\"portal.portal_layout\">\n        <t t-set=\"breadcrumbs_searchbar\" t-value=\"True\"/>\n\n        <t t-call=\"portal.portal_searchbar\">\n            <t t-set=\"title\">Invoices</t>\n        </t>\n        <t t-if=\"not invoices\">\n            <p class=\"alert alert-warning\">There are currently no invoices and payments for your account.</p>\n        </t>\n        <t t-if=\"invoices\" t-call=\"portal.portal_table\">\n            <thead>\n                <tr class=\"active\">\n                    <th name=\"invoice_number\">Invoice #</th>\n                    <th name=\"invoice_date\">Invoice Date</th>\n                    <th name=\"due_date\" class=\"d-none d-md-table-cell\">Due Date</th>\n                    <th name=\"status\">Status</th>\n                    <th name=\"amount_due\" class=\"text-end\">Amount Due</th>\n                </tr>\n            </thead>\n            <tbody>\n                <t t-foreach=\"invoices\" t-as=\"invoice\">\n                    <tr>\n                        <td>\n                            <a t-att-href=\"invoice.get_portal_url()\" t-att-title=\"invoice.name\">\n                                <t t-out=\"invoice.name\" t-if=\"invoice.name != ''/''\"/>\n                                <em t-else=\"\">Draft Invoice</em>\n                            </a>\n                        </td>\n                        <td><span t-field=\"invoice.invoice_date\"/></td>\n                        <td class=\"d-none d-md-table-cell\"><span t-field=\"invoice.invoice_date_due\"/></td>\n                        <td name=\"invoice_status\">\n                            <t t-if=\"invoice.state == ''posted''\" name=\"invoice_status_posted\">\n                                <span t-if=\"invoice.payment_state in (''paid'', ''in_payment'')\" class=\"badge rounded-pill text-bg-success\">\n                                    <i class=\"fa fa-fw fa-check\" aria-label=\"Paid\" title=\"Paid\" role=\"img\"/>\n                                    <span class=\"d-none d-md-inline\"> Paid</span>\n                                </span>\n                                <span t-elif=\"invoice.payment_state == ''reversed''\" class=\"badge rounded-pill text-bg-success\">\n                                    <i class=\"fa fa-fw fa-check\" aria-label=\"Reversed\" title=\"Reversed\" role=\"img\"/>\n                                    <span class=\"d-none d-md-inline\"> Reversed</span>\n                                </span>\n                                <span t-else=\"\" class=\"badge rounded-pill text-bg-info\" name=\"invoice_status_waiting_for_payment\">\n                                    <i class=\"fa fa-fw fa-clock-o\" aria-label=\"Opened\" title=\"Opened\" role=\"img\"/>\n                                    <span class=\"d-none d-md-inline\"> Waiting for Payment</span>\n                                </span>\n                            </t>\n                            <t t-elif=\"invoice.state == ''cancel''\">\n                                <span class=\"badge rounded-pill text-bg-warning\">\n                                    <i class=\"fa fa-fw fa-remove\" aria-label=\"Cancelled\" title=\"Cancelled\" role=\"img\"/>\n                                    <span class=\"d-none d-md-inline\"> Cancelled</span>\n                                </span>\n                            </t>\n                        </td>\n                        <td class=\"text-end\"><span t-out=\"-invoice.amount_residual if invoice.move_type == ''out_refund'' else invoice.amount_residual\" t-options=\"{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: invoice.currency_id}\"/></td>\n                    </tr>\n                </t>\n            </tbody>\n        </t>\n      </t>\n    </t>"}', '<?xml version="1.0"?>
<t name="My Invoices and Payments" t-name="account.portal_my_invoices">
      <t t-call="portal.portal_layout">
        <t t-set="breadcrumbs_searchbar" t-value="True"/>

        <t t-call="portal.portal_searchbar">
            <t t-set="title">Invoices</t>
        </t>
        <t t-if="not invoices">
            <p class="alert alert-warning">There are currently no invoices and payments for your account.</p>
        </t>
        <t t-if="invoices" t-call="portal.portal_table">
            <thead>
                <tr class="active">
                    <th name="invoice_number">Invoice #</th>
                    <th name="invoice_date">Invoice Date</th>
                    <th name="due_date" class="d-none d-md-table-cell">Due Date</th>
                    <th name="status">Status</th>
                    <th name="amount_due" class="text-end">Amount Due</th>
                </tr>
            </thead>
            <tbody>
                <t t-foreach="invoices" t-as="invoice">
                    <tr>
                        <td>
                            <a t-att-href="invoice.get_portal_url()" t-att-title="invoice.name">
                                <t t-out="invoice.name" t-if="invoice.name != ''/''"/>
                                <em t-else="">Draft Invoice</em>
                            </a>
                        </td>
                        <td><span t-field="invoice.invoice_date"/></td>
                        <td class="d-none d-md-table-cell"><span t-field="invoice.invoice_date_due"/></td>
                        <td name="invoice_status">
                            <t t-if="invoice.state == ''posted''" name="invoice_status_posted">
                                <span t-if="invoice.payment_state in (''paid'', ''in_payment'')" class="badge rounded-pill text-bg-success">
                                    <i class="fa fa-fw fa-check" aria-label="Paid" title="Paid" role="img"/>
                                    <span class="d-none d-md-inline"> Paid</span>
                                </span>
                                <span t-elif="invoice.payment_state == ''reversed''" class="badge rounded-pill text-bg-success">
                                    <i class="fa fa-fw fa-check" aria-label="Reversed" title="Reversed" role="img"/>
                                    <span class="d-none d-md-inline"> Reversed</span>
                                </span>
                                <span t-else="" class="badge rounded-pill text-bg-info" name="invoice_status_waiting_for_payment">
                                    <i class="fa fa-fw fa-clock-o" aria-label="Opened" title="Opened" role="img"/>
                                    <span class="d-none d-md-inline"> Waiting for Payment</span>
                                </span>
                            </t>
                            <t t-elif="invoice.state == ''cancel''">
                                <span class="badge rounded-pill text-bg-warning">
                                    <i class="fa fa-fw fa-remove" aria-label="Cancelled" title="Cancelled" role="img"/>
                                    <span class="d-none d-md-inline"> Cancelled</span>
                                </span>
                            </t>
                        </td>
                        <td class="text-end"><span t-out="-invoice.amount_residual if invoice.move_type == ''out_refund'' else invoice.amount_residual" t-options="{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: invoice.currency_id}"/></td>
                    </tr>
                </t>
            </tbody>
        </t>
      </t>
    </t>

    ', false, true, '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295', false);
INSERT INTO public.ir_ui_view VALUES (776, 16, 563, 1, 1, 'Invoice/Bill', NULL, 'account.portal_invoice_page', 'qweb', 'account/views/account_portal_templates.xml', 'primary', '{"en_US": "<data name=\"Invoice/Bill\" inherit_id=\"portal.portal_sidebar\" primary=\"True\">\n        <xpath expr=\"//div[hasclass(''o_portal_sidebar'')]\" position=\"inside\">\n            <t t-set=\"o_portal_fullwidth_alert\" groups=\"sales_team.group_sale_salesman,account.group_account_invoice,account.group_account_readonly\">\n                <t t-call=\"portal.portal_back_in_edit_mode\">\n                    <t t-set=\"backend_url\" t-value=\"''/web#model=%s&amp;id=%s&amp;action=%s&amp;view_type=form'' % (invoice._name, invoice.id, invoice.env.ref(''account.action_move_out_invoice_type'').id)\"/>\n                </t>\n            </t>\n\n            <div class=\"row o_portal_invoice_sidebar\">\n                <!-- Sidebar -->\n                <t t-call=\"portal.portal_record_sidebar\">\n                    <t t-set=\"classes\" t-value=\"''col-lg-3 col-xl-4 d-print-none me-lg-auto''\"/>\n                    <t t-set=\"title\">\n                        <h2 t-if=\"0\">\n                            <span t-if=\"invoice.amount_residual &gt; 0\" t-field=\"invoice.amount_residual\"/>\n                            <span t-else=\"1\" t-field=\"invoice.amount_total\"/>\n                        </h2>\n                        <t t-set=\"early_payment\" t-value=\"installment_state == ''epd''\"/>\n                        <div t-if=\"early_payment\" class=\"alert alert-info w-100 text-center\" role=\"alert\">\n                            <span t-esc=\"epd_discount_msg\"/>\n                        </div>\n                        <h2 t-if=\"amount\">\n                            <t t-if=\"early_payment\">\n                                <span t-esc=\"next_amount_to_pay\" t-attf-class=\"ms-1 h5\" style=\"text-decoration: line-through; color: grey;\" t-options=\"{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: invoice.currency_id}\"/>\n                                <span t-esc=\"amount_due\" t-options=\"{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: invoice.currency_id}\"/>\n                            </t>\n                            <t t-else=\"1\">\n                                <span t-esc=\"amount\" t-options=\"{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: invoice.currency_id}\"/>\n                            </t>\n                        </h2>\n                        <h2 t-else=\"1\">\n                            <span t-esc=\"invoice.amount_total\" t-options=\"{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: invoice.currency_id}\"/>\n                        </h2>\n                        <div class=\"small\" t-if=\"invoice.payment_state not in (''paid'', ''in_payment'', ''reversed'') and invoice.move_type == ''out_invoice''\"><i class=\"fa fa-clock-o\"/><span class=\"o_portal_sidebar_timeago ml4\" t-att-datetime=\"invoice.invoice_date_due\"/></div>\n                    </t>\n\n                    <t t-set=\"entries\">\n                        <div class=\"d-flex flex-column gap-4\">\n                            <div class=\"flex-basis-100 flex-basis-sm-50 flex-basis-lg-100 order-1 order-lg-0\">\n                                <div class=\"o_download_pdf d-flex gap-1 flex-lg-column flex-xl-row\">\n                                    <div class=\"flex-grow-1\">\n                                        <a class=\"btn btn-secondary d-block o_download_btn\" t-att-href=\"invoice.get_portal_url(report_type=''pdf'', download=True)\" title=\"Download\"><i class=\"fa fa-download\"/> Download</a>\n                                    </div>\n                                </div>\n                            </div>\n                            <div t-if=\"invoice.invoice_user_id\" class=\"flex-grow-1\">\n                                <h6>\n                                    <small class=\"text-muted\">\n                                        <t t-if=\"invoice.move_type == ''out_invoice''\">\n                                            Salesperson\n                                        </t>\n                                        <t t-if=\"invoice.move_type == ''in_invoice''\">\n                                            Purchase Representative\n                                        </t>\n                                    </small>\n                                </h6>\n                                <div class=\"o_portal_contact_details d-flex flex-column gap-2\">\n                                    <div class=\"d-flex justify-content-start align-items-center gap-2\">\n                                        <img class=\"o_avatar o_portal_contact_img rounded\" t-att-src=\"image_data_uri(invoice.invoice_user_id.avatar_128)\" alt=\"Contact\"/>\n                                        <div>\n                                            <h6 class=\"mb-0\" t-out=\"invoice.invoice_user_id.name\"/>\n                                            <a href=\"#discussion\" class=\"d-flex align-items-center gap-2 small fw-bold\">\n                                            Send message\n                                            </a>\n                                        </div>\n                                    </div>\n                                    <div t-field=\"invoice.invoice_user_id\" t-options=\"{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;city&quot;, &quot;phone&quot;]}\"/>\n                                </div>\n                            </div>\n                        </div>\n                    </t>\n                </t>\n\n                <!-- Page Content -->\n                <div id=\"invoice_content\" class=\"o_portal_content col-12 col-lg-9 col-xl-8\">\n                    <t t-if=\"error or warning\" t-call=\"account.portal_invoice_error\"/>\n                    <t t-if=\"success and (not error and not warning)\" t-call=\"account.portal_invoice_success\"/>\n\n                    <div class=\"o_portal_html_view shadow p-3\">\n                        <div class=\"o_portal_html_loader text-center\">\n                            <i class=\"fa fa-circle-o-notch fa-spin fa-2x fa-fw text-black-50\"/>\n                        </div>\n                        <iframe id=\"invoice_html\" class=\"mt8 mb8\" width=\"100%\" height=\"100%\" frameborder=\"0\" scrolling=\"no\" t-att-src=\"invoice.get_portal_url(report_type=''html'')\"/>\n                    </div>\n                    <!-- chatter -->\n                    <div id=\"invoice_communication\" class=\"mt-4\">\n                        <h3>Communication history</h3>\n                        <t t-call=\"portal.message_thread\"/>\n                    </div>\n                </div>\n            </div>\n        </xpath>\n    <xpath expr=\".\" position=\"attributes\"><attribute name=\"t-name\">account.portal_invoice_page</attribute></xpath></data>"}', '<?xml version="1.0"?>
<data name="Invoice/Bill" inherit_id="portal.portal_sidebar" primary="True">
        <xpath expr="//div[hasclass(''o_portal_sidebar'')]" position="inside">
            <t t-set="o_portal_fullwidth_alert" groups="sales_team.group_sale_salesman,account.group_account_invoice,account.group_account_readonly">
                <t t-call="portal.portal_back_in_edit_mode">
                    <t t-set="backend_url" t-value="''/web#model=%s&amp;id=%s&amp;action=%s&amp;view_type=form'' % (invoice._name, invoice.id, invoice.env.ref(''account.action_move_out_invoice_type'').id)"/>
                </t>
            </t>

            <div class="row o_portal_invoice_sidebar">
                <!-- Sidebar -->
                <t t-call="portal.portal_record_sidebar">
                    <t t-set="classes" t-value="''col-lg-3 col-xl-4 d-print-none me-lg-auto''"/>
                    <t t-set="title">
                        <h2 t-if="0">
                            <span t-if="invoice.amount_residual &gt; 0" t-field="invoice.amount_residual"/>
                            <span t-else="1" t-field="invoice.amount_total"/>
                        </h2>
                        <t t-set="early_payment" t-value="installment_state == ''epd''"/>
                        <div t-if="early_payment" class="alert alert-info w-100 text-center" role="alert">
                            <span t-esc="epd_discount_msg"/>
                        </div>
                        <h2 t-if="amount">
                            <t t-if="early_payment">
                                <span t-esc="next_amount_to_pay" t-attf-class="ms-1 h5" style="text-decoration: line-through; color: grey;" t-options="{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: invoice.currency_id}"/>
                                <span t-esc="amount_due" t-options="{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: invoice.currency_id}"/>
                            </t>
                            <t t-else="1">
                                <span t-esc="amount" t-options="{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: invoice.currency_id}"/>
                            </t>
                        </h2>
                        <h2 t-else="1">
                            <span t-esc="invoice.amount_total" t-options="{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: invoice.currency_id}"/>
                        </h2>
                        <div class="small" t-if="invoice.payment_state not in (''paid'', ''in_payment'', ''reversed'') and invoice.move_type == ''out_invoice''"><i class="fa fa-clock-o"/><span class="o_portal_sidebar_timeago ml4" t-att-datetime="invoice.invoice_date_due"/></div>
                    </t>

                    <t t-set="entries">
                        <div class="d-flex flex-column gap-4">
                            <div class="flex-basis-100 flex-basis-sm-50 flex-basis-lg-100 order-1 order-lg-0">
                                <div class="o_download_pdf d-flex gap-1 flex-lg-column flex-xl-row">
                                    <div class="flex-grow-1">
                                        <a class="btn btn-secondary d-block o_download_btn" t-att-href="invoice.get_portal_url(report_type=''pdf'', download=True)" title="Download"><i class="fa fa-download"/> Download</a>
                                    </div>
                                </div>
                            </div>
                            <div t-if="invoice.invoice_user_id" class="flex-grow-1">
                                <h6>
                                    <small class="text-muted">
                                        <t t-if="invoice.move_type == ''out_invoice''">
                                            Salesperson
                                        </t>
                                        <t t-if="invoice.move_type == ''in_invoice''">
                                            Purchase Representative
                                        </t>
                                    </small>
                                </h6>
                                <div class="o_portal_contact_details d-flex flex-column gap-2">
                                    <div class="d-flex justify-content-start align-items-center gap-2">
                                        <img class="o_avatar o_portal_contact_img rounded" t-att-src="image_data_uri(invoice.invoice_user_id.avatar_128)" alt="Contact"/>
                                        <div>
                                            <h6 class="mb-0" t-out="invoice.invoice_user_id.name"/>
                                            <a href="#discussion" class="d-flex align-items-center gap-2 small fw-bold">
                                            Send message
                                            </a>
                                        </div>
                                    </div>
                                    <div t-field="invoice.invoice_user_id" t-options="{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;city&quot;, &quot;phone&quot;]}"/>
                                </div>
                            </div>
                        </div>
                    </t>
                </t>

                <!-- Page Content -->
                <div id="invoice_content" class="o_portal_content col-12 col-lg-9 col-xl-8">
                    <t t-if="error or warning" t-call="account.portal_invoice_error"/>
                    <t t-if="success and (not error and not warning)" t-call="account.portal_invoice_success"/>

                    <div class="o_portal_html_view shadow p-3">
                        <div class="o_portal_html_loader text-center">
                            <i class="fa fa-circle-o-notch fa-spin fa-2x fa-fw text-black-50"/>
                        </div>
                        <iframe id="invoice_html" class="mt8 mb8" width="100%" height="100%" frameborder="0" scrolling="no" t-att-src="invoice.get_portal_url(report_type=''html'')"/>
                    </div>
                    <!-- chatter -->
                    <div id="invoice_communication" class="mt-4">
                        <h3>Communication history</h3>
                        <t t-call="portal.message_thread"/>
                    </div>
                </div>
            </div>
        </xpath>
    <xpath expr="." position="attributes"><attribute name="t-name">account.portal_invoice_page</attribute></xpath></data>

    ', false, true, '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295', false);
INSERT INTO public.ir_ui_view VALUES (777, 16, NULL, 1, 1, 'Invoice error/warning display', NULL, 'account.portal_invoice_error', 'qweb', 'account/views/account_portal_templates.xml', 'primary', '{"en_US": "<t name=\"Invoice error/warning display\" t-name=\"account.portal_invoice_error\">\n        <div class=\"row mr16\">\n            <div t-attf-class=\"''col-lg-12 mr16 ml16 alert alert-dismissable'' #{''alert-danger'' if error else ''alert-warning''}\" role=\"alert\">\n                <a href=\"#\" class=\"close\" data-bs-dismiss=\"alert\" aria-label=\"close\" title=\"close\">×</a>\n                <t t-if=\"error == ''generic''\" name=\"generic\">\n                    There was an error processing this page.\n                </t>\n            </div>\n        </div>\n    </t>"}', '<?xml version="1.0"?>
<t name="Invoice error/warning display" t-name="account.portal_invoice_error">
        <div class="row mr16">
            <div t-attf-class="''col-lg-12 mr16 ml16 alert alert-dismissable'' #{''alert-danger'' if error else ''alert-warning''}" role="alert">
                <a href="#" class="close" data-bs-dismiss="alert" aria-label="close" title="close">×</a>
                <t t-if="error == ''generic''" name="generic">
                    There was an error processing this page.
                </t>
            </div>
        </div>
    </t>

    ', false, true, '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295', false);
INSERT INTO public.ir_ui_view VALUES (778, 16, NULL, 1, 1, 'Invoice success display', NULL, 'account.portal_invoice_success', 'qweb', 'account/views/account_portal_templates.xml', 'primary', '{"en_US": "<t name=\"Invoice success display\" t-name=\"account.portal_invoice_success\">\n        <div class=\"row mr16\">\n            <div class=\"col-lg-12 mr16 ml16 alert alert-dismissable alert-success\" role=\"status\">\n                <a href=\"#\" class=\"close\" data-bs-dismiss=\"alert\" aria-label=\"close\" title=\"close\">×</a>\n            </div>\n        </div>\n    </t>"}', '<?xml version="1.0"?>
<t name="Invoice success display" t-name="account.portal_invoice_success">
        <div class="row mr16">
            <div class="col-lg-12 mr16 ml16 alert alert-dismissable alert-success" role="status">
                <a href="#" class="close" data-bs-dismiss="alert" aria-label="close" title="close">×</a>
            </div>
        </div>
    </t>

    ', false, true, '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295', false);
INSERT INTO public.ir_ui_view VALUES (835, 16, 770, 1, 1, 'res.partner.property.form.inherit', 'res.partner', NULL, 'form', 'account_edi_ubl_cii/views/res_partner_views.xml', 'extension', '{"en_US": "<xpath expr=\"//group[@name=''banks'']\" position=\"after\">\n                <group string=\"Electronic Invoicing\" name=\"electronic_invoicing\">\n                    <field name=\"hide_peppol_fields\" invisible=\"True\"/>\n                    <field name=\"ubl_cii_format\" widget=\"selection\"/>\n                    <field name=\"peppol_eas\" widget=\"selection\" invisible=\"hide_peppol_fields\"/>\n                    <field name=\"peppol_endpoint\" invisible=\"hide_peppol_fields\"/>\n                </group>\n            </xpath>"}', '<?xml version="1.0"?>
<xpath expr="//group[@name=''banks'']" position="after">
                <group string="Electronic Invoicing" name="electronic_invoicing">
                    <field name="hide_peppol_fields" invisible="True"/>
                    <field name="ubl_cii_format" widget="selection"/>
                    <field name="peppol_eas" widget="selection" invisible="hide_peppol_fields"/>
                    <field name="peppol_endpoint" invisible="hide_peppol_fields"/>
                </group>
            </xpath>
        ', false, true, '2026-05-10 01:12:03.930547', '2026-05-10 01:12:03.930547', false);
INSERT INTO public.ir_ui_view VALUES (779, 16, NULL, 1, 1, 'portal_invoice_required_fields_form', NULL, 'account.portal_invoice_required_fields_form', 'qweb', 'account/views/account_portal_templates.xml', 'primary', '{"en_US": "<t t-name=\"account.portal_invoice_required_fields_form\">\n        <t t-foreach=\"required_fields\" t-as=\"required_field\">\n            <div t-attf-class=\"mb-3 #{error.get(required_field.name) and ''o_has_error'' or ''''} col-xl-6\">\n                <!-- select by default the value passed in the data or corresponding to the \"default\" attribute on the field -->\n                <t t-set=\"field_info\" t-value=\"env[required_field.model]._fields[required_field.name]\"/>\n                <t t-set=\"default_value\" t-value=\"extra_field_values.get(field_prefix + required_field.name) or field_info.default and field_info.default(required_field.model)\"/>\n                <t t-if=\"required_field.ttype == ''selection''\">\n                    <label class=\"col-form-label\" t-att-for=\"field_prefix + required_field.name\"><t t-out=\"required_field.field_description\"/></label>\n                    <select class=\"form-select\" t-att-name=\"field_prefix + required_field.name\" required=\"required\">\n                        <option t-att-selected=\"not default_value\" disabled=\"disabled\" value=\"\"><t t-out=\"''Select the %s ...'' % required_field.field_description.lower()\"/></option>\n                        <t t-foreach=\"required_field.selection_ids\" t-as=\"selection\">\n                            <option t-att-selected=\"default_value and default_value == selection.value\" t-att-value=\"selection.value\"><t t-out=\"selection.name\"/></option>\n                        </t>\n                    </select>\n                </t>\n            </div>\n        </t>\n    </t>"}', '<?xml version="1.0"?>
<t t-name="account.portal_invoice_required_fields_form">
        <t t-foreach="required_fields" t-as="required_field">
            <div t-attf-class="mb-3 #{error.get(required_field.name) and ''o_has_error'' or ''''} col-xl-6">
                <!-- select by default the value passed in the data or corresponding to the "default" attribute on the field -->
                <t t-set="field_info" t-value="env[required_field.model]._fields[required_field.name]"/>
                <t t-set="default_value" t-value="extra_field_values.get(field_prefix + required_field.name) or field_info.default and field_info.default(required_field.model)"/>
                <t t-if="required_field.ttype == ''selection''">
                    <label class="col-form-label" t-att-for="field_prefix + required_field.name"><t t-out="required_field.field_description"/></label>
                    <select class="form-select" t-att-name="field_prefix + required_field.name" required="required">
                        <option t-att-selected="not default_value" disabled="disabled" value=""><t t-out="''Select the %s ...'' % required_field.field_description.lower()"/></option>
                        <t t-foreach="required_field.selection_ids" t-as="selection">
                            <option t-att-selected="default_value and default_value == selection.value" t-att-value="selection.value"><t t-out="selection.name"/></option>
                        </t>
                    </select>
                </t>
            </div>
        </t>
    </t>
', false, true, '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295', false);
INSERT INTO public.ir_ui_view VALUES (780, 16, NULL, 1, 1, 'report_payment_receipt_document', NULL, 'account.report_payment_receipt_document', 'qweb', 'account/views/report_payment_receipt_templates.xml', 'primary', '{"en_US": "<t t-name=\"account.report_payment_receipt_document\">\n        <t t-call=\"web.external_layout\">\n            <t t-set=\"o\" t-value=\"o.with_context(lang=lang)\"/>\n            <t t-set=\"values\" t-value=\"o._get_payment_receipt_report_values()\"/>\n            <div class=\"page\">\n                <h3><strong id=\"payment_title\">Payment Receipt: <span t-field=\"o.name\">INV0001</span></strong></h3>\n\n                <div class=\"mb-4 mt-3\">\n                    <div name=\"date\" class=\"row\">\n                        <div class=\"col-6\" t-if=\"o.date\">\n                            Payment Date: <span t-field=\"o.date\">2023-01-01</span>\n                        </div>\n                    </div>\n                    <div class=\"oe_structure\"/>\n                    <div class=\"row\">\n                        <div class=\"col-6\" t-if=\"o.partner_type\">\n                            <t t-if=\"o.partner_type == ''customer''\">\n                                Customer:\n                            </t>\n                            <t t-else=\"o.partner_type == ''supplier''\">\n                                Vendor:\n                            </t><span t-field=\"o.partner_id\" data-oe-demo=\"Marc Demo\"/>\n                        </div>\n                        <div name=\"payment_method\" t-if=\"values[''display_payment_method''] and o.payment_method_id\" class=\"col-6\">\n                            Payment Method: <span t-field=\"o.payment_method_id.name\">Credit card</span>\n                        </div>\n                    </div>\n                    <div class=\"oe_structure\"/>\n                    <div class=\"row\">\n                        <div class=\"col-6\" t-if=\"o.amount\">\n                            Payment Amount: <span t-field=\"o.amount\" t-options=\"{''widget'': ''monetary'', ''display_currency'': o.currency_id}\">50 USD</span>\n                         </div>\n                        <div class=\"col-6\" t-if=\"o.ref\">\n                            Memo: <span t-field=\"o.ref\">Sample Memo</span>\n                         </div>\n                    </div>\n                </div>\n\n                <div class=\"oe_structure\"/>\n                <table name=\"invoices\" t-if=\"values[''display_invoices'']\" class=\"table table-sm\">\n                    <t t-set=\"invoices\" t-value=\"o.reconciled_invoice_ids or o.reconciled_bill_ids\"/>\n                    <!-- Check if invoices include different currencies -->\n                    <t t-foreach=\"invoices\" t-as=\"inv\">\n                        <t t-if=\"any(inv.currency_id != par[2].currency_id for par in inv._get_reconciled_invoices_partials()[0])\" t-set=\"otherCurrency\" t-value=\"True\"/>\n                    </t>\n                    <thead>\n                        <tr>\n                            <th><span>Invoice Date</span></th>\n                            <th><span>Invoice Number</span></th>\n                            <th><span>Reference</span></th>\n                            <!-- Add a column if there are different currencies -->\n                            <th t-if=\"otherCurrency\" class=\"text-end\"><span>Amount In Currency</span></th>\n                            <th class=\"text-end\"><span>Amount</span></th>\n                        </tr>\n                    </thead>\n                    <tbody>\n                        <t t-foreach=\"invoices\" t-as=\"inv\">\n                            <!-- MOVE -->\n                            <t t-if=\"inv.move_type != ''entry''\">\n                                <tr>\n                                    <td><span t-field=\"inv.invoice_date\">2023-01-01</span></td>\n                                    <td><span t-field=\"inv.name\">INV001</span></td>\n                                    <td><span t-field=\"inv.ref\" data-oe-demo=\"Sample Ref\"/></td>\n                                    <td t-if=\"otherCurrency\"/>\n                                    <td class=\"text-end\"><span t-field=\"inv.amount_total\">100.00 USD</span></td>\n                                </tr>\n                                <!-- PAYMENTS/REVERSALS -->\n                                <tr t-foreach=\"inv._get_reconciled_invoices_partials()[0]\" t-as=\"par\">\n                                    <t t-set=\"payment\" t-value=\"par[2].move_id\"/>\n                                    <td><span t-field=\"payment.date\">2023-01-05</span></td>\n                                    <td><span t-field=\"payment.name\">PAY001</span></td>\n                                    <td><span t-field=\"payment.ref\" data-oe-demo=\"Payment Ref\"/></td>\n                                    <t t-set=\"amountPayment\" t-value=\"-(par[0].debit_amount_currency if par[2].debit &gt; 0 else par[0].credit_amount_currency)\"/>\n                                    <t t-set=\"amountInvoice\" t-value=\"-par[1]\"/>\n                                    <t t-set=\"currencyPayment\" t-value=\"payment.currency_id\"/>\n                                    <t t-set=\"currencyInvoice\" t-value=\"inv.currency_id\"/>\n                                    <!-- Fill the column \"Amount In Currency\" only if necessary -->\n                                    <td t-if=\"otherCurrency\" class=\"text-end\"><span t-if=\"currencyPayment != currencyInvoice\" t-out=\"amountPayment\" t-options=\"{''widget'': ''monetary'', ''display_currency'': currencyPayment}\">50.00 EUR</span></td>\n                                    <td class=\"text-end\"><span t-out=\"amountInvoice\" t-options=\"{''widget'': ''monetary'', ''display_currency'': currencyInvoice}\">25.00 USD</span></td>\n                                </tr>\n                                <!-- BALANCE -->\n                                <tr>\n                                    <td/>\n                                    <td><strong>Due Amount for <span t-field=\"inv.name\">INV001</span></strong></td>\n                                    <td/>\n                                    <td t-if=\"otherCurrency\"/>\n                                    <td class=\"text-end\"><strong><span t-field=\"inv.amount_residual\">25.0 USD</span></strong></td>\n                                </tr>\n                            </t>\n                        </t>\n                    </tbody>\n                </table>\n            </div>\n            <div class=\"oe_structure\"/>\n        </t>\n    </t>"}', '<?xml version="1.0"?>
<t t-name="account.report_payment_receipt_document">
        <t t-call="web.external_layout">
            <t t-set="o" t-value="o.with_context(lang=lang)"/>
            <t t-set="values" t-value="o._get_payment_receipt_report_values()"/>
            <div class="page">
                <h3><strong id="payment_title">Payment Receipt: <span t-field="o.name">INV0001</span></strong></h3>

                <div class="mb-4 mt-3">
                    <div name="date" class="row">
                        <div class="col-6" t-if="o.date">
                            Payment Date: <span t-field="o.date">2023-01-01</span>
                        </div>
                    </div>
                    <div class="oe_structure"/>
                    <div class="row">
                        <div class="col-6" t-if="o.partner_type">
                            <t t-if="o.partner_type == ''customer''">
                                Customer:
                            </t>
                            <t t-else="o.partner_type == ''supplier''">
                                Vendor:
                            </t><span t-field="o.partner_id" data-oe-demo="Marc Demo"/>
                        </div>
                        <div name="payment_method" t-if="values[''display_payment_method''] and o.payment_method_id" class="col-6">
                            Payment Method: <span t-field="o.payment_method_id.name">Credit card</span>
                        </div>
                    </div>
                    <div class="oe_structure"/>
                    <div class="row">
                        <div class="col-6" t-if="o.amount">
                            Payment Amount: <span t-field="o.amount" t-options="{''widget'': ''monetary'', ''display_currency'': o.currency_id}">50 USD</span>
                         </div>
                        <div class="col-6" t-if="o.ref">
                            Memo: <span t-field="o.ref">Sample Memo</span>
                         </div>
                    </div>
                </div>

                <div class="oe_structure"/>
                <table name="invoices" t-if="values[''display_invoices'']" class="table table-sm">
                    <t t-set="invoices" t-value="o.reconciled_invoice_ids or o.reconciled_bill_ids"/>
                    <!-- Check if invoices include different currencies -->
                    <t t-foreach="invoices" t-as="inv">
                        <t t-if="any(inv.currency_id != par[2].currency_id for par in inv._get_reconciled_invoices_partials()[0])" t-set="otherCurrency" t-value="True"/>
                    </t>
                    <thead>
                        <tr>
                            <th><span>Invoice Date</span></th>
                            <th><span>Invoice Number</span></th>
                            <th><span>Reference</span></th>
                            <!-- Add a column if there are different currencies -->
                            <th t-if="otherCurrency" class="text-end"><span>Amount In Currency</span></th>
                            <th class="text-end"><span>Amount</span></th>
                        </tr>
                    </thead>
                    <tbody>
                        <t t-foreach="invoices" t-as="inv">
                            <!-- MOVE -->
                            <t t-if="inv.move_type != ''entry''">
                                <tr>
                                    <td><span t-field="inv.invoice_date">2023-01-01</span></td>
                                    <td><span t-field="inv.name">INV001</span></td>
                                    <td><span t-field="inv.ref" data-oe-demo="Sample Ref"/></td>
                                    <td t-if="otherCurrency"/>
                                    <td class="text-end"><span t-field="inv.amount_total">100.00 USD</span></td>
                                </tr>
                                <!-- PAYMENTS/REVERSALS -->
                                <tr t-foreach="inv._get_reconciled_invoices_partials()[0]" t-as="par">
                                    <t t-set="payment" t-value="par[2].move_id"/>
                                    <td><span t-field="payment.date">2023-01-05</span></td>
                                    <td><span t-field="payment.name">PAY001</span></td>
                                    <td><span t-field="payment.ref" data-oe-demo="Payment Ref"/></td>
                                    <t t-set="amountPayment" t-value="-(par[0].debit_amount_currency if par[2].debit &gt; 0 else par[0].credit_amount_currency)"/>
                                    <t t-set="amountInvoice" t-value="-par[1]"/>
                                    <t t-set="currencyPayment" t-value="payment.currency_id"/>
                                    <t t-set="currencyInvoice" t-value="inv.currency_id"/>
                                    <!-- Fill the column "Amount In Currency" only if necessary -->
                                    <td t-if="otherCurrency" class="text-end"><span t-if="currencyPayment != currencyInvoice" t-out="amountPayment" t-options="{''widget'': ''monetary'', ''display_currency'': currencyPayment}">50.00 EUR</span></td>
                                    <td class="text-end"><span t-out="amountInvoice" t-options="{''widget'': ''monetary'', ''display_currency'': currencyInvoice}">25.00 USD</span></td>
                                </tr>
                                <!-- BALANCE -->
                                <tr>
                                    <td/>
                                    <td><strong>Due Amount for <span t-field="inv.name">INV001</span></strong></td>
                                    <td/>
                                    <td t-if="otherCurrency"/>
                                    <td class="text-end"><strong><span t-field="inv.amount_residual">25.0 USD</span></strong></td>
                                </tr>
                            </t>
                        </t>
                    </tbody>
                </table>
            </div>
            <div class="oe_structure"/>
        </t>
    </t>

    ', false, true, '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295', false);
INSERT INTO public.ir_ui_view VALUES (781, 16, NULL, 1, 1, 'report_payment_receipt', NULL, 'account.report_payment_receipt', 'qweb', 'account/views/report_payment_receipt_templates.xml', 'primary', '{"en_US": "<t t-name=\"account.report_payment_receipt\">\n        <t t-call=\"web.html_container\">\n            <t t-foreach=\"docs\" t-as=\"o\">\n                <t t-set=\"lang\" t-value=\"o.partner_id.lang or o.company_id.partner_id.lang\"/>\n                <t t-call=\"account.report_payment_receipt_document\" t-lang=\"lang\"/>\n            </t>\n        </t>\n    </t>"}', '<?xml version="1.0"?>
<t t-name="account.report_payment_receipt">
        <t t-call="web.html_container">
            <t t-foreach="docs" t-as="o">
                <t t-set="lang" t-value="o.partner_id.lang or o.company_id.partner_id.lang"/>
                <t t-call="account.report_payment_receipt_document" t-lang="lang"/>
            </t>
        </t>
    </t>
', false, true, '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295', false);
INSERT INTO public.ir_ui_view VALUES (782, 16, NULL, 1, 1, 'account.incoterms.tree', 'account.incoterms', NULL, 'tree', 'account/views/account_incoterms_view.xml', 'primary', '{"en_US": "<tree string=\"Incoterms\" editable=\"bottom\">\n                    <field name=\"active\" column_invisible=\"True\"/>\n                    <field name=\"code\"/>\n                    <field colspan=\"4\" name=\"name\"/>\n                </tree>"}', '<?xml version="1.0"?>
<tree string="Incoterms" editable="bottom">
                    <field name="active" column_invisible="True"/>
                    <field name="code"/>
                    <field colspan="4" name="name"/>
