INSERT INTO public.ir_ui_view VALUES (783, 16, NULL, 1, 1, 'account.incoterms.form', 'account.incoterms', NULL, 'form', 'account/views/account_incoterms_view.xml', 'primary', '{"en_US": "<form string=\"Incoterms\">\n                    <sheet>\n                        <widget name=\"web_ribbon\" title=\"Archived\" bg_color=\"text-bg-danger\" invisible=\"active\"/>\n                        <group>\n                            <field name=\"active\" invisible=\"1\"/>\n                            <field name=\"name\"/>\n                            <field name=\"code\"/>\n                        </group>\n                    </sheet>\n                </form>"}', '<?xml version="1.0"?>
<form string="Incoterms">
