                        <widget name="web_ribbon" title="Archived" bg_color="text-bg-danger" invisible="active"/>
                        <group>
                            <field name="active" invisible="1"/>
                            <field name="name"/>
                            <field name="code"/>
                        </group>
                    </sheet>
                </form>
            ', false, true, '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295', false);
INSERT INTO public.ir_ui_view VALUES (784, 16, NULL, 1, 1, 'account.incoterms.search', 'account.incoterms', NULL, 'search', 'account/views/account_incoterms_view.xml', 'primary', '{"en_US": "<search string=\"Incoterms\">\n                    <field name=\"name\"/>\n                    <separator/>\n                    <filter string=\"Archived\" name=\"inactive\" domain=\"[(''active'', ''='', False)]\"/>\n                </search>"}', '<?xml version="1.0"?>
