INSERT INTO public.ir_ui_view VALUES (785, 30, 596, 1, 1, 'digest.digest.view.form.inherit.account.account', 'digest.digest', NULL, 'form', 'account/views/digest_views.xml', 'extension', '{"en_US": "<xpath expr=\"//group[@name=''kpis'']/group[last()]\" position=\"before\">\n                <group name=\"kpi_account\" string=\"Invoicing\" groups=\"account.group_account_manager\">\n                    <field name=\"kpi_account_total_revenue\"/>\n                </group>\n            </xpath>"}', '<?xml version="1.0"?>
