INSERT INTO public.ir_ui_view VALUES (787, 16, NULL, 1, 1, 'report_hash_integrity', NULL, 'account.report_hash_integrity', 'qweb', 'account/report/account_hash_integrity_templates.xml', 'primary', '{"en_US": "<t t-name=\"account.report_hash_integrity\">\n            <t t-call=\"web.html_container\">\n                <t t-foreach=\"docs\" t-as=\"company\">\n                    <t t-call=\"web.external_layout\">\n                        <div class=\"page\">\n                            <div class=\"row\" id=\"hash_header\">\n                                <div class=\"col-12\">\n                                    <br/>\n                                    <h2>Hash Integrity Result - <span t-out=\"data[''printing_date'']\"/></h2>\n                                    <br/>\n                                </div>\n                            </div>\n                            <div class=\"row\">\n                                <div class=\"col-12\" id=\"hash_config_review\">\n                                    <br/>\n                                    <h3>Configuration review</h3>\n                                    <br/>\n                                </div>\n                            </div>\n                            <div class=\"row\">\n                                <div class=\"col-12\">\n                                    <table class=\"table table-bordered\" style=\"table-layout: fixed\" id=\"hash_config_table\">\n                                        <thead style=\"display: table-row-group\">\n                                            <tr>\n                                                <th class=\"text-center\" style=\"width: 30%\" scope=\"col\">Journal</th>\n                                                <th class=\"text-center\" style=\"width: 20%\" scope=\"col\">Inalterability check</th>\n                                                <th class=\"text-center\" style=\"width: 50%\" scope=\"col\">Coverage</th>\n                                            </tr>\n                                        </thead>\n                                        <tbody>\n                                            <t t-foreach=\"data[''results'']\" t-as=\"result\">\n                                                <tr>\n                                                    <td>\n                                                        [<span t-out=\"result[''journal_code'']\"/>] <span t-out=\"result[''journal_name'']\"/>\n                                                    </td>\n                                                    <td class=\"text-center\"><span t-out=\"result[''restricted_by_hash_table'']\"/></td>\n                                                    <td><span t-out=\"result[''msg_cover'']\"/></td>\n                                                </tr>\n                                            </t>\n                                        </tbody>\n                                    </table>\n                                </div>\n                            </div>\n                            <t t-if=\"any(result[''first_hash''] != ''None'' for result in data[''results''])\">\n                                <div class=\"row\" style=\"page-break-before:always;\">\n                                    <div class=\"col-12\" id=\"hash_data_consistency\">\n                                        <br/>\n                                        <h3>Data consistency check</h3>\n                                        <br/>\n                                    </div>\n                                </div>\n                                <div class=\"row\">\n                                    <div class=\"col-12\" id=\"hash_data_consistency_table\">\n                                        <table class=\"table table-bordered\" style=\"table-layout: fixed\">\n                                            <thead style=\"display: table-row-group\">\n                                                <tr>\n                                                    <th class=\"text-center\" style=\"width: 20%\" scope=\"col\">Journal</th>\n                                                    <th class=\"text-center\" style=\"width: 20%\" scope=\"col\">First Hash</th>\n                                                    <th class=\"text-center\" style=\"width: 20%\" scope=\"col\">First Entry</th>\n                                                    <th class=\"text-center\" style=\"width: 20%\" scope=\"col\">Last Hash</th>\n                                                    <th class=\"text-center\" style=\"width: 20%\" scope=\"col\">Last Entry</th>\n                                                </tr>\n                                            </thead>\n                                            <tbody>\n                                                <t t-foreach=\"data[''results'']\" t-as=\"result\">\n                                                    <t t-if=\"result[''first_hash''] != ''None''\">\n                                                        <tr>\n                                                            <td><span t-out=\"result[''journal_code'']\"/></td>\n                                                            <td><span t-out=\"result[''first_hash'']\"/></td>\n                                                            <td>\n                                                                <span t-out=\"result[''first_move_name'']\"/> <br/>\n                                                                <span t-out=\"result[''first_move_date'']\"/>\n                                                            </td>\n                                                            <td><span t-out=\"result[''last_hash'']\"/></td>\n                                                            <td>\n                                                                <span t-out=\"result[''last_move_name'']\"/> <br/>\n                                                                <span t-out=\"result[''last_move_date'']\"/>\n                                                            </td>\n                                                        </tr>\n                                                    </t>\n                                                </t>\n                                            </tbody>\n                                        </table>\n                                    </div>\n                                </div>\n                                <div class=\"row\" id=\"hash_last_div\">\n                                    <div class=\"col-12\" id=\"hash_chain_compliant\">\n                                        <br/>\n                                        <h6>\n                                            The hash chain is compliant: it is not possible to alter the\n                                            data without breaking the hash chain for subsequent parts.\n                                        </h6>\n                                        <br/>\n                                    </div>\n                                </div>\n                            </t>\n                        </div>\n                    </t>\n                </t>\n            </t>\n        </t>"}', '<?xml version="1.0"?>
<t t-name="account.report_hash_integrity">
            <t t-call="web.html_container">
                <t t-foreach="docs" t-as="company">
                    <t t-call="web.external_layout">
                        <div class="page">
                            <div class="row" id="hash_header">
                                <div class="col-12">
                                    <br/>
                                    <h2>Hash Integrity Result - <span t-out="data[''printing_date'']"/></h2>
                                    <br/>
                                </div>
                            </div>
                            <div class="row">
                                <div class="col-12" id="hash_config_review">
                                    <br/>
                                    <h3>Configuration review</h3>
                                    <br/>
                                </div>
                            </div>
                            <div class="row">
                                <div class="col-12">
                                    <table class="table table-bordered" style="table-layout: fixed" id="hash_config_table">
                                        <thead style="display: table-row-group">
                                            <tr>
                                                <th class="text-center" style="width: 30%" scope="col">Journal</th>
                                                <th class="text-center" style="width: 20%" scope="col">Inalterability check</th>
                                                <th class="text-center" style="width: 50%" scope="col">Coverage</th>
                                            </tr>
                                        </thead>
                                        <tbody>
                                            <t t-foreach="data[''results'']" t-as="result">
                                                <tr>
                                                    <td>
                                                        [<span t-out="result[''journal_code'']"/>] <span t-out="result[''journal_name'']"/>
                                                    </td>
                                                    <td class="text-center"><span t-out="result[''restricted_by_hash_table'']"/></td>
                                                    <td><span t-out="result[''msg_cover'']"/></td>
                                                </tr>
                                            </t>
                                        </tbody>
                                    </table>
                                </div>
                            </div>
                            <t t-if="any(result[''first_hash''] != ''None'' for result in data[''results''])">
                                <div class="row" style="page-break-before:always;">
                                    <div class="col-12" id="hash_data_consistency">
                                        <br/>
                                        <h3>Data consistency check</h3>
                                        <br/>
                                    </div>
                                </div>
                                <div class="row">
                                    <div class="col-12" id="hash_data_consistency_table">
                                        <table class="table table-bordered" style="table-layout: fixed">
                                            <thead style="display: table-row-group">
                                                <tr>
                                                    <th class="text-center" style="width: 20%" scope="col">Journal</th>
                                                    <th class="text-center" style="width: 20%" scope="col">First Hash</th>
                                                    <th class="text-center" style="width: 20%" scope="col">First Entry</th>
                                                    <th class="text-center" style="width: 20%" scope="col">Last Hash</th>
                                                    <th class="text-center" style="width: 20%" scope="col">Last Entry</th>
                                                </tr>
                                            </thead>
                                            <tbody>
                                                <t t-foreach="data[''results'']" t-as="result">
                                                    <t t-if="result[''first_hash''] != ''None''">
                                                        <tr>
                                                            <td><span t-out="result[''journal_code'']"/></td>
                                                            <td><span t-out="result[''first_hash'']"/></td>
                                                            <td>
                                                                <span t-out="result[''first_move_name'']"/> <br/>
                                                                <span t-out="result[''first_move_date'']"/>
                                                            </td>
                                                            <td><span t-out="result[''last_hash'']"/></td>
                                                            <td>
                                                                <span t-out="result[''last_move_name'']"/> <br/>
                                                                <span t-out="result[''last_move_date'']"/>
                                                            </td>
                                                        </tr>
                                                    </t>
                                                </t>
                                            </tbody>
                                        </table>
                                    </div>
                                </div>
                                <div class="row" id="hash_last_div">
                                    <div class="col-12" id="hash_chain_compliant">
                                        <br/>
                                        <h6>
                                            The hash chain is compliant: it is not possible to alter the
                                            data without breaking the hash chain for subsequent parts.
                                        </h6>
                                        <br/>
                                    </div>
                                </div>
                            </t>
                        </div>
                    </t>
                </t>
            </t>
        </t>
    ', false, true, '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295', false);
INSERT INTO public.ir_ui_view VALUES (788, 16, 155, 1, 1, 'res.currency.form.inherit', 'res.currency', NULL, 'form', 'account/views/res_currency.xml', 'extension', '{"en_US": "<data><xpath expr=\"//field[@name=''is_current_company_currency'']\" position=\"after\">\n                    <field name=\"fiscal_country_codes\" invisible=\"1\"/>\n                </xpath>\n                <xpath expr=\"//sheet\" position=\"before\">\n                    <field name=\"display_rounding_warning\" invisible=\"1\"/>\n                    <div class=\"alert alert-warning\" role=\"alert\" invisible=\"not display_rounding_warning\">\n                        <strong>This currency has already been used to generate accounting entries.</strong> <br/>\n                        Changing its rounding factor now will not change the rounding made on previous entries; possibly causing an inconsistency with the new ones.\n                    </div>\n                </xpath>\n            </data>"}', '<?xml version="1.0"?>
<data><xpath expr="//field[@name=''is_current_company_currency'']" position="after">
                    <field name="fiscal_country_codes" invisible="1"/>
                </xpath>
                <xpath expr="//sheet" position="before">
                    <field name="display_rounding_warning" invisible="1"/>
                    <div class="alert alert-warning" role="alert" invisible="not display_rounding_warning">
                        <strong>This currency has already been used to generate accounting entries.</strong> <br/>
                        Changing its rounding factor now will not change the rounding made on previous entries; possibly causing an inconsistency with the new ones.
                    </div>
                </xpath>
            </data>', false, true, '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295', false);
INSERT INTO public.ir_ui_view VALUES (789, 16, NULL, 1, 1, 'account.tour.upload.bill', 'account.tour.upload.bill', NULL, 'form', 'account/wizard/account_tour_upload_bill.xml', 'primary', '{"en_US": "<form>\n                    <sheet>\n                        <h2>With Odoo, you won''t have to record bills manually</h2>\n                        <p>We process bills automatically so that you only have to validate them. Choose how you want to test our artificial intelligence engine:</p>\n                        <div class=\"grid\">\n                            <field name=\"selection\" widget=\"radio\" class=\"g-col-4\"/>\n                            <field name=\"preview_invoice\" widget=\"html\" invisible=\"selection != ''sample''\" class=\"g-col-8\"/>\n                            <field name=\"attachment_ids\" widget=\"many2many_binary\" string=\"Attach a file\" invisible=\"selection != ''upload''\" class=\"g-col-8\"/>\n                        </div>\n                    </sheet>\n                    <footer>\n                        <button string=\"Continue\" type=\"object\" name=\"apply\" class=\"btn-primary\" data-hotkey=\"q\"/>\n                        <button string=\"Discard\" class=\"btn-secondary\" special=\"cancel\" data-hotkey=\"x\"/>\n                    </footer>\n               </form>"}', '<?xml version="1.0"?>
<form>
                    <sheet>
                        <h2>With Odoo, you won''t have to record bills manually</h2>
                        <p>We process bills automatically so that you only have to validate them. Choose how you want to test our artificial intelligence engine:</p>
                        <div class="grid">
                            <field name="selection" widget="radio" class="g-col-4"/>
                            <field name="preview_invoice" widget="html" invisible="selection != ''sample''" class="g-col-8"/>
                            <field name="attachment_ids" widget="many2many_binary" string="Attach a file" invisible="selection != ''upload''" class="g-col-8"/>
                        </div>
                    </sheet>
                    <footer>
                        <button string="Continue" type="object" name="apply" class="btn-primary" data-hotkey="q"/>
                        <button string="Discard" class="btn-secondary" special="cancel" data-hotkey="x"/>
                    </footer>
               </form>
            ', false, true, '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295', false);
INSERT INTO public.ir_ui_view VALUES (790, 16, NULL, 1, 1, 'account.tour.upload.bill.email.confirm', 'account.tour.upload.bill.email.confirm', NULL, 'form', 'account/wizard/account_tour_upload_bill.xml', 'primary', '{"en_US": "<form>\n                    <field name=\"email_alias\" invisible=\"1\"/>\n                    <sheet>\n                        <p invisible=\"not email_alias\">Send your email to <field name=\"email_alias\" class=\"oe_inline\" widget=\"email\"/> with a pdf of an invoice as attachment.</p>\n                        <p invisible=\"not email_alias\">Once done, press continue.</p>\n                        <p invisible=\"email_alias\">Configure your email server first and send your bill by email.</p>\n                        <a type=\"action\" name=\"220\" class=\"btn btn-link\" role=\"button\" invisible=\"email_alias\"><i class=\"oi oi-fw o_button_icon oi-arrow-right\"/> Configure Email Servers</a>\n                    </sheet>\n                    <footer>\n                        <button string=\"Continue\" type=\"object\" name=\"apply\" class=\"btn-primary\" data-hotkey=\"q\" invisible=\"not email_alias\"/>\n                        <button string=\"Discard\" class=\"btn-secondary\" special=\"cancel\" data-hotkey=\"x\" invisible=\"not email_alias\"/>\n                        <button string=\"Close\" class=\"btn-secondary\" special=\"cancel\" data-hotkey=\"x\" invisible=\"email_alias\"/>\n                    </footer>\n               </form>"}', '<?xml version="1.0"?>
<form>
                    <field name="email_alias" invisible="1"/>
                    <sheet>
                        <p invisible="not email_alias">Send your email to <field name="email_alias" class="oe_inline" widget="email"/> with a pdf of an invoice as attachment.</p>
                        <p invisible="not email_alias">Once done, press continue.</p>
                        <p invisible="email_alias">Configure your email server first and send your bill by email.</p>
                        <a type="action" name="220" class="btn btn-link" role="button" invisible="email_alias"><i class="oi oi-fw o_button_icon oi-arrow-right"/> Configure Email Servers</a>
                    </sheet>
                    <footer>
                        <button string="Continue" type="object" name="apply" class="btn-primary" data-hotkey="q" invisible="not email_alias"/>
                        <button string="Discard" class="btn-secondary" special="cancel" data-hotkey="x" invisible="not email_alias"/>
                        <button string="Close" class="btn-secondary" special="cancel" data-hotkey="x" invisible="email_alias"/>
                    </footer>
               </form>
            ', false, true, '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295', false);
INSERT INTO public.ir_ui_view VALUES (836, 16, 127, 1, 1, 'res.partner.search.inherit', 'res.partner', NULL, 'search', 'account_edi_ubl_cii/views/res_partner_views.xml', 'extension', '{"en_US": "<xpath expr=\"//group[@name=''group_by'']\" position=\"after\">\n                <filter name=\"ubl_cii_format\" string=\"EDI Format\" context=\"{''group_by'':''ubl_cii_format''}\"/>\n            </xpath>"}', '<?xml version="1.0"?>
<xpath expr="//group[@name=''group_by'']" position="after">
                <filter name="ubl_cii_format" string="EDI Format" context="{''group_by'':''ubl_cii_format''}"/>
            </xpath>
        ', false, true, '2026-05-10 01:12:03.930547', '2026-05-10 01:12:03.930547', false);
INSERT INTO public.ir_ui_view VALUES (791, 16, NULL, 1, 1, 'account.accrued.orders.wizard.view', 'account.accrued.orders.wizard', NULL, 'form', 'account/wizard/accrued_orders.xml', 'primary', '{"en_US": "<form string=\"Make Accrual Entries\">\n                <field name=\"company_id\" invisible=\"1\"/>\n                <group>\n                    <div class=\"alert alert-info\" colspan=\"4\" role=\"alert\" invisible=\"not display_amount\">\n                      There doesn''t appear to be anything to invoice for the selected order. However, you can use the amount field to force an accrual entry.\n                    </div>\n                  <group>\n                    <field name=\"journal_id\"/>\n                    <field name=\"account_id\"/>\n                    <field name=\"amount\" invisible=\"not display_amount\"/>\n                    <field name=\"display_amount\" invisible=\"1\"/>\n                  </group>\n                  <group>\n                    <field name=\"date\"/>\n                    <field name=\"reversal_date\"/>\n                  </group>\n                </group>\n                <field name=\"preview_data\" widget=\"grouped_view_widget\" class=\"w-100\"/>\n                <footer>\n                    <button string=\"Create Entry\" name=\"create_entries\" type=\"object\" class=\"btn-primary\"/>\n                    <button string=\"Cancel\" class=\"btn-secondary\" special=\"cancel\"/>\n                </footer>\n            </form>"}', '<?xml version="1.0"?>
<form string="Make Accrual Entries">
                <field name="company_id" invisible="1"/>
                <group>
                    <div class="alert alert-info" colspan="4" role="alert" invisible="not display_amount">
                      There doesn''t appear to be anything to invoice for the selected order. However, you can use the amount field to force an accrual entry.
                    </div>
                  <group>
                    <field name="journal_id"/>
                    <field name="account_id"/>
                    <field name="amount" invisible="not display_amount"/>
                    <field name="display_amount" invisible="1"/>
                  </group>
                  <group>
                    <field name="date"/>
                    <field name="reversal_date"/>
                  </group>
                </group>
                <field name="preview_data" widget="grouped_view_widget" class="w-100"/>
                <footer>
                    <button string="Create Entry" name="create_entries" type="object" class="btn-primary"/>
                    <button string="Cancel" class="btn-secondary" special="cancel"/>
                </footer>
            </form>
        ', false, true, '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295', false);
INSERT INTO public.ir_ui_view VALUES (792, 16, NULL, 1, 1, 'bill_preview', NULL, 'account.bill_preview', 'qweb', 'account/views/bill_preview_template.xml', 'primary', '{"en_US": "<t t-name=\"account.bill_preview\">\n            <div id=\"wrapwrap\" class=\"p-4\">\n                <main class=\"shadow p-4\">\n                    <div class=\"article\">\n                        <div class=\"o_company_1_layout\">\n                            <div class=\"row\">\n                                <div class=\"col-4\" style=\"margin-bottom: 8px !important;\">\n                                    <img style=\"max-height: 60px;\" alt=\"Logo\" src=\"data:image/png;base64,\"/>\n                                </div>\n                            </div>\n                            <div class=\"row zero_min_height\">\n                                <div class=\"col-12\">\n                                    <div style=\"border-bottom: 1px solid black;\"/>\n                                </div>\n                            </div>\n                            <div class=\"row\">\n                                <div class=\"col-6\" name=\"company_address\"/>\n                            </div>\n                        </div>\n                        <div class=\"o_report_layout_standard o_company_1_layout \">\n                            <div class=\"pt-3\">\n                                <div id=\"addr\" class=\"page\" style=\"margin-top: 32px !important;\">\n                                    <div style=\"width:49%; display:inline-block;\"/>\n                                    <div style=\"width:50%; display:inline-block;\">\n                                        <address class=\"mb-0\" itemscope=\"itemscope\" itemtype=\"http://schema.org/Organization\" style=\"width:100%\">\n                                            <div>\n                                                <span itemprop=\"name\"><t t-out=\"company_name\"/></span>\n                                            </div>\n                                            <div itemprop=\"address\" itemscope=\"itemscope\" itemtype=\"http://schema.org/PostalAddress\">\n                                                <div class=\"d-flex align-items-baseline\">\n                                                    <span class=\"w-100 o_force_ltr d-block\" itemprop=\"streetAddress\">\n                                                        <t t-foreach=\"company_street_address\" t-as=\"line\">\n                                                            <t t-out=\"line\"/><br/>\n                                                        </t>\n                                                    </span>\n                                                </div>\n                                            </div>\n                                        </address>\n                                    </div>\n                                </div>\n                            </div>\n                            <div class=\"pt-3\" style=\"margin-top: 32px;\">\n                                <h2><t t-out=\"invoice_name\"/></h2>\n                                <div id=\"dates\" class=\"page\" style=\"margin-top: 28px !important;\">\n                                    <div style=\"width:25%; display:inline-block;\">\n                                        <strong>Invoice Date:</strong>\n                                        <p class=\"m-0\"><t t-out=\"invoice_date\"/></p>\n                                    </div>\n\n                                    <div style=\"width:25%; display:inline-block;\">\n                                        <div class=\"mb-0\" itemscope=\"itemscope\" itemtype=\"http://schema.org/Organization\" style=\"width:100%\">\n                                                <strong>Due Date:</strong>\n                                                <p class=\"m-0\"><t t-out=\"invoice_due_date\"/></p>\n                                        </div>\n                                    </div>\n                                </div>\n                            </div>\n                            <div class=\"page\" style=\"margin-top: 32px !important;\">\n                                <table class=\"table table-sm o_main_table\" name=\"invoice_line_table\" style=\"width: 100%;\">\n                                    <thead>\n                                        <tr>\n                                            <th name=\"th_description\" class=\"text-start\"><span>Description</span></th>\n                                            <th name=\"th_quantity\" class=\"text-end\"><span>Quantity</span></th>\n                                            <th name=\"th_priceunit\" class=\"text-end d-md-table-cell\"><span>Unit Price</span></th>\n                                            <th name=\"th_taxes\" class=\"text-end d-md-table-cell\"><span>Taxes</span></th>\n                                            <th name=\"th_subtotal\" class=\"text-end\"><span>Amount</span></th>\n                                        </tr>\n                                    </thead>\n                                    <tbody class=\"invoice_tbody\">\n                                        <tr class=\"\">\n                                            <td name=\"account_invoice_line_name\">\n                                                [FURN_8999] Three-Seat Sofa\n                                            </td>\n                                            <td class=\"text-end\">\n                                                <span>5.00</span>\n                                            </td>\n                                            <td class=\"text-end d-md-table-cell\">\n                                                <span class=\"text-nowrap\">1,500.00</span>\n                                            </td>\n                                            <td class=\"text-end d-md-table-cell\">\n                                                <span>Tax 0%</span>\n                                            </td>\n                                            <td class=\"text-end o_price_total\">\n                                                <span class=\"text-nowrap\">$ <span class=\"oe_currency_value\">7,500.00</span></span>\n                                            </td>\n                                        </tr>\n                                        <tr class=\"\">\n                                            <td name=\"account_invoice_line_name\">\n                                                [FURN_8220] Four Person Desk\n                                            </td>\n                                            <td class=\"text-end\">\n                                                <span>5.00</span>\n                                            </td>\n                                            <td class=\"text-end d-md-table-cell\">\n                                                <span class=\"text-nowrap\">2,350.00</span>\n                                            </td>\n                                            <td class=\"text-end d-md-table-cell\">\n                                                <span>Tax 0%</span>\n                                            </td>\n                                            <td class=\"text-end o_price_total\">\n                                                <span class=\"text-nowrap\">$ <span class=\"oe_currency_value\">11,750.00</span></span>\n                                            </td>\n                                        </tr>\n                                    </tbody>\n                                </table>\n                                <div id=\"total\" class=\"page\" style=\"margin-top: 32px !important;\">\n                                    <div style=\"width:49%; display:inline-block;\"/>\n                                    <div style=\"width:50%; display:inline-block;\">\n                                        <table class=\"table table-sm\" style=\"page-break-inside: avoid; width:100%\">\n                                            <tbody><tr class=\"border-black o_subtotal\" style=\"\">\n                                                <td><strong>Subtotal</strong></td>\n                                                <td class=\"text-end\">\n                                                    <span>$ <span class=\"oe_currency_value\">19,250.00</span></span>\n                                                </td>\n                                            </tr>\n                                            <tr class=\"border-black o_total\">\n                                                <td><strong>Total</strong></td>\n                                                <td class=\"text-end\">\n                                                    <span class=\"text-nowrap\">$ <span class=\"oe_currency_value\">19,250.00</span></span>\n                                                </td>\n                                            </tr>\n                                        </tbody></table>\n                                    </div>\n                                </div>\n                                <div class=\"mt-4\">\n                                    <p>Please use the following communication for your payment: <b><t t-out=\"invoice_ref\"/></b></p>\n                                    <p>Payment terms: 30 Days</p>\n                                </div>\n                            </div>\n                        </div>\n                        <div class=\"o_company_1_layout mt-4\">\n                            <div class=\"text-center\" style=\"border-top: 1px solid black;\">\n                                <ul class=\"list-inline mb4\"/>\n                            </div>\n                        </div>\n                    </div>\n                </main>\n            </div>\n        </t>"}', '<?xml version="1.0"?>
<t t-name="account.bill_preview">
            <div id="wrapwrap" class="p-4">
                <main class="shadow p-4">
                    <div class="article">
                        <div class="o_company_1_layout">
                            <div class="row">
                                <div class="col-4" style="margin-bottom: 8px !important;">
                                    <img style="max-height: 60px;" alt="Logo" src="data:image/png;base64,"/>
                                </div>
                            </div>
                            <div class="row zero_min_height">
                                <div class="col-12">
                                    <div style="border-bottom: 1px solid black;"/>
                                </div>
                            </div>
                            <div class="row">
                                <div class="col-6" name="company_address"/>
                            </div>
                        </div>
                        <div class="o_report_layout_standard o_company_1_layout ">
                            <div class="pt-3">
                                <div id="addr" class="page" style="margin-top: 32px !important;">
                                    <div style="width:49%; display:inline-block;"/>
                                    <div style="width:50%; display:inline-block;">
                                        <address class="mb-0" itemscope="itemscope" itemtype="http://schema.org/Organization" style="width:100%">
                                            <div>
                                                <span itemprop="name"><t t-out="company_name"/></span>
                                            </div>
                                            <div itemprop="address" itemscope="itemscope" itemtype="http://schema.org/PostalAddress">
                                                <div class="d-flex align-items-baseline">
                                                    <span class="w-100 o_force_ltr d-block" itemprop="streetAddress">
                                                        <t t-foreach="company_street_address" t-as="line">
                                                            <t t-out="line"/><br/>
                                                        </t>
                                                    </span>
                                                </div>
                                            </div>
                                        </address>
                                    </div>
                                </div>
                            </div>
                            <div class="pt-3" style="margin-top: 32px;">
                                <h2><t t-out="invoice_name"/></h2>
                                <div id="dates" class="page" style="margin-top: 28px !important;">
                                    <div style="width:25%; display:inline-block;">
                                        <strong>Invoice Date:</strong>
                                        <p class="m-0"><t t-out="invoice_date"/></p>
                                    </div>

                                    <div style="width:25%; display:inline-block;">
                                        <div class="mb-0" itemscope="itemscope" itemtype="http://schema.org/Organization" style="width:100%">
                                                <strong>Due Date:</strong>
                                                <p class="m-0"><t t-out="invoice_due_date"/></p>
                                        </div>
                                    </div>
                                </div>
                            </div>
                            <div class="page" style="margin-top: 32px !important;">
                                <table class="table table-sm o_main_table" name="invoice_line_table" style="width: 100%;">
                                    <thead>
                                        <tr>
                                            <th name="th_description" class="text-start"><span>Description</span></th>
                                            <th name="th_quantity" class="text-end"><span>Quantity</span></th>
                                            <th name="th_priceunit" class="text-end d-md-table-cell"><span>Unit Price</span></th>
                                            <th name="th_taxes" class="text-end d-md-table-cell"><span>Taxes</span></th>
                                            <th name="th_subtotal" class="text-end"><span>Amount</span></th>
                                        </tr>
                                    </thead>
                                    <tbody class="invoice_tbody">
                                        <tr class="">
                                            <td name="account_invoice_line_name">
                                                [FURN_8999] Three-Seat Sofa
                                            </td>
                                            <td class="text-end">
                                                <span>5.00</span>
                                            </td>
                                            <td class="text-end d-md-table-cell">
                                                <span class="text-nowrap">1,500.00</span>
                                            </td>
                                            <td class="text-end d-md-table-cell">
                                                <span>Tax 0%</span>
                                            </td>
                                            <td class="text-end o_price_total">
                                                <span class="text-nowrap">$ <span class="oe_currency_value">7,500.00</span></span>
                                            </td>
                                        </tr>
                                        <tr class="">
                                            <td name="account_invoice_line_name">
                                                [FURN_8220] Four Person Desk
                                            </td>
                                            <td class="text-end">
                                                <span>5.00</span>
                                            </td>
                                            <td class="text-end d-md-table-cell">
                                                <span class="text-nowrap">2,350.00</span>
                                            </td>
                                            <td class="text-end d-md-table-cell">
                                                <span>Tax 0%</span>
                                            </td>
                                            <td class="text-end o_price_total">
                                                <span class="text-nowrap">$ <span class="oe_currency_value">11,750.00</span></span>
                                            </td>
                                        </tr>
                                    </tbody>
                                </table>
                                <div id="total" class="page" style="margin-top: 32px !important;">
                                    <div style="width:49%; display:inline-block;"/>
                                    <div style="width:50%; display:inline-block;">
                                        <table class="table table-sm" style="page-break-inside: avoid; width:100%">
                                            <tbody><tr class="border-black o_subtotal" style="">
                                                <td><strong>Subtotal</strong></td>
                                                <td class="text-end">
                                                    <span>$ <span class="oe_currency_value">19,250.00</span></span>
                                                </td>
                                            </tr>
                                            <tr class="border-black o_total">
                                                <td><strong>Total</strong></td>
                                                <td class="text-end">
                                                    <span class="text-nowrap">$ <span class="oe_currency_value">19,250.00</span></span>
                                                </td>
                                            </tr>
                                        </tbody></table>
                                    </div>
                                </div>
                                <div class="mt-4">
                                    <p>Please use the following communication for your payment: <b><t t-out="invoice_ref"/></b></p>
                                    <p>Payment terms: 30 Days</p>
                                </div>
                            </div>
                        </div>
                        <div class="o_company_1_layout mt-4">
                            <div class="text-center" style="border-top: 1px solid black;">
                                <ul class="list-inline mb4"/>
                            </div>
                        </div>
                    </div>
                </main>
            </div>
        </t>
    ', false, true, '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295', false);
