INSERT INTO public.ir_ui_view VALUES (798, 15, 125, 1, 1, 'res.partner.form.inherit.account_peppol_partner_extra_fields', 'res.partner', NULL, 'form', 'account_add_gln/views/res_partner_views.xml', 'extension', '{"en_US": "<data><xpath expr=\".//page[@name=''sales_purchases'']//group[@name=''misc'']\" position=\"inside\">\n                <field name=\"global_location_number\" invisible=\"type != ''delivery''\"/>\n            </xpath>\n            <xpath expr=\".//page[@name=''contact_addresses'']/field[@name=''child_ids'']/form//field[@name=''mobile'']\" position=\"after\">\n                <field name=\"global_location_number\" invisible=\"type != ''delivery''\"/>\n            </xpath>\n        </data>"}', '<?xml version="1.0"?>
