INSERT INTO public.ir_ui_view VALUES (799, 16, NULL, 1, 1, 'account_invoice_line_facturx_export_22', NULL, 'account_edi_ubl_cii.account_invoice_line_facturx_export_22', 'qweb', 'account_edi_ubl_cii/data/cii_22_templates.xml', 'primary', '{"en_US": "<t t-name=\"account_edi_ubl_cii.account_invoice_line_facturx_export_22\">\n            <t t-set=\"line\" t-value=\"line_vals[''line'']\"/>\n            <t xmlns:ram=\"urn:un:unece:uncefact:data:standard:ReusableAggregateBusinessInformationEntity:100\" xmlns:rsm=\"urn:un:unece:uncefact:data:standard:CrossIndustryInvoice:100\" xmlns:udt=\"urn:un:unece:uncefact:data:standard:UnqualifiedDataType:100\" xmlns:qdt=\"urn:un:unece:uncefact:data:standard:QualifiedDataType:100\" xmlns:xsi=\"http://www.w3.org/2001/XMLSchema-instance\">\n\n                <ram:IncludedSupplyChainTradeLineItem>\n                    <!-- Line number. -->\n                    <ram:AssociatedDocumentLineDocument>\n                        <ram:LineID t-out=\"line_vals.get(''index'')\"/>\n                    </ram:AssociatedDocumentLineDocument>\n\n                    <!-- Product. -->\n                    <ram:SpecifiedTradeProduct>\n                        <ram:GlobalID schemeID=\"0160\" t-if=\"line.product_id and line.product_id.barcode\" t-out=\"line.product_id.barcode\"/>\n                        <ram:SellerAssignedID t-if=\"line.product_id and line.product_id.default_code\" t-out=\"line.product_id.default_code\"/>\n                        <!-- TODO:\n                        <ram:Name t-out=\"line.product_id.name or line.name\"/>\n                        <ram:Description t-out=\"line.name\" t-if=\"line.name != line.product_id.name\"/>\n                        -->\n                        <ram:Name t-out=\"line.name\"/>\n                    </ram:SpecifiedTradeProduct>\n\n                    <!-- Amounts. -->\n                    <ram:SpecifiedLineTradeAgreement>\n                        <!-- Line information: unit_price\n                        NB: the gross_price_unit should be the price tax excluded!\n                        if price_unit = 100 and tax 10% price_include -> then the gross_price_unit is 91\n                        -->\n                        <ram:GrossPriceProductTradePrice>\n                            <ram:ChargeAmount t-out=\"format_monetary(line_vals[''gross_price_total_unit''], 2)\"/>\n                            <!-- Discount. -->\n                            <ram:AppliedTradeAllowanceCharge t-if=\"line.discount\">\n                                <ram:ChargeIndicator>\n                                    <udt:Indicator t-translation=\"off\">false</udt:Indicator>\n                                </ram:ChargeIndicator>\n                                <ram:ActualAmount t-out=\"format_monetary(line_vals[''price_discount_unit''], 2)\"/>\n                            </ram:AppliedTradeAllowanceCharge>\n                        </ram:GrossPriceProductTradePrice>\n                        <!-- Line unit price, with discount applied -->\n                        <ram:NetPriceProductTradePrice>\n                            <ram:ChargeAmount t-out=\"format_monetary(line_vals[''price_subtotal_unit''], 2)\"/>\n                        </ram:NetPriceProductTradePrice>\n                    </ram:SpecifiedLineTradeAgreement>\n\n                    <!-- Quantity. -->\n                    <ram:SpecifiedLineTradeDelivery>\n                        <ram:BilledQuantity t-att-unitCode=\"line_vals.get(''unece_uom_code'')\" t-out=\"line_vals.get(''quantity'')\"/>\n                    </ram:SpecifiedLineTradeDelivery>\n\n                    <ram:SpecifiedLineTradeSettlement>\n                        <t t-foreach=\"tax_details[''tax_details_per_record''][line][''tax_details''].values()\" t-as=\"tax_detail_vals\">\n                            <ram:ApplicableTradeTax t-if=\"tax_detail_vals[''amount_type''] == ''percent''\">\n                                <ram:TypeCode t-translation=\"off\">VAT</ram:TypeCode>\n                                <ram:CategoryCode t-out=\"tax_detail_vals[''tax_category_code'']\"/>\n                                <ram:RateApplicablePercent t-out=\"tax_detail_vals[''amount'']\"/>\n                            </ram:ApplicableTradeTax>\n                        </t>\n\n                        <!-- Billing Period -->\n                        <ram:BillingSpecifiedPeriod t-if=\"line_vals.get(''billing_start'') and line_vals.get(''billing_end'')\"> \n                            <ram:StartDateTime>\n                                <udt:DateTimeString format=\"102\" t-out=\"format_date(line_vals[''billing_start''])\"/>\n                            </ram:StartDateTime>\n                            <ram:EndDateTime>\n                                <udt:DateTimeString format=\"102\" t-out=\"format_date(line_vals[''billing_end''])\"/>\n                            </ram:EndDateTime>\n                        </ram:BillingSpecifiedPeriod>\n\n                        <!-- Allowance/Charge on the line -->\n                        <t t-foreach=\"line_vals.get(''allowance_charge_vals_list'')\" t-as=\"allowance_charge_vals\">\n                            <ram:SpecifiedTradeAllowanceCharge>\n                                <ram:ChargeIndicator>\n                                    <udt:Indicator t-esc=\"allowance_charge_vals[''indicator'']\"/>\n                                </ram:ChargeIndicator>\n                                <ram:ActualAmount t-esc=\"format_monetary(allowance_charge_vals[''amount''], 2)\"/>\n                                <ram:ReasonCode t-esc=\"allowance_charge_vals[''reason_code'']\"/>\n                                <ram:Reason t-esc=\"allowance_charge_vals[''reason'']\"/>\n                            </ram:SpecifiedTradeAllowanceCharge>\n                        </t>\n\n                        <!-- Subtotal. -->\n                        <ram:SpecifiedTradeSettlementLineMonetarySummation>\n                            <ram:LineTotalAmount t-esc=\"format_monetary(line_vals[''line_total_amount''], 2)\"/>\n                        </ram:SpecifiedTradeSettlementLineMonetarySummation>\n\n                    </ram:SpecifiedLineTradeSettlement>\n                </ram:IncludedSupplyChainTradeLineItem>\n            </t>\n        </t>"}', '<?xml version="1.0"?>
<t t-name="account_edi_ubl_cii.account_invoice_line_facturx_export_22">
            <t t-set="line" t-value="line_vals[''line'']"/>
            <t xmlns:ram="urn:un:unece:uncefact:data:standard:ReusableAggregateBusinessInformationEntity:100" xmlns:rsm="urn:un:unece:uncefact:data:standard:CrossIndustryInvoice:100" xmlns:udt="urn:un:unece:uncefact:data:standard:UnqualifiedDataType:100" xmlns:qdt="urn:un:unece:uncefact:data:standard:QualifiedDataType:100" xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance">

                <ram:IncludedSupplyChainTradeLineItem>
                    <!-- Line number. -->
                    <ram:AssociatedDocumentLineDocument>
                        <ram:LineID t-out="line_vals.get(''index'')"/>
                    </ram:AssociatedDocumentLineDocument>

                    <!-- Product. -->
                    <ram:SpecifiedTradeProduct>
                        <ram:GlobalID schemeID="0160" t-if="line.product_id and line.product_id.barcode" t-out="line.product_id.barcode"/>
                        <ram:SellerAssignedID t-if="line.product_id and line.product_id.default_code" t-out="line.product_id.default_code"/>
                        <!-- TODO:
                        <ram:Name t-out="line.product_id.name or line.name"/>
                        <ram:Description t-out="line.name" t-if="line.name != line.product_id.name"/>
                        -->
                        <ram:Name t-out="line.name"/>
                    </ram:SpecifiedTradeProduct>

                    <!-- Amounts. -->
                    <ram:SpecifiedLineTradeAgreement>
                        <!-- Line information: unit_price
                        NB: the gross_price_unit should be the price tax excluded!
                        if price_unit = 100 and tax 10% price_include -> then the gross_price_unit is 91
                        -->
                        <ram:GrossPriceProductTradePrice>
                            <ram:ChargeAmount t-out="format_monetary(line_vals[''gross_price_total_unit''], 2)"/>
                            <!-- Discount. -->
                            <ram:AppliedTradeAllowanceCharge t-if="line.discount">
                                <ram:ChargeIndicator>
                                    <udt:Indicator t-translation="off">false</udt:Indicator>
                                </ram:ChargeIndicator>
                                <ram:ActualAmount t-out="format_monetary(line_vals[''price_discount_unit''], 2)"/>
                            </ram:AppliedTradeAllowanceCharge>
                        </ram:GrossPriceProductTradePrice>
                        <!-- Line unit price, with discount applied -->
                        <ram:NetPriceProductTradePrice>
                            <ram:ChargeAmount t-out="format_monetary(line_vals[''price_subtotal_unit''], 2)"/>
                        </ram:NetPriceProductTradePrice>
                    </ram:SpecifiedLineTradeAgreement>

                    <!-- Quantity. -->
                    <ram:SpecifiedLineTradeDelivery>
                        <ram:BilledQuantity t-att-unitCode="line_vals.get(''unece_uom_code'')" t-out="line_vals.get(''quantity'')"/>
                    </ram:SpecifiedLineTradeDelivery>

                    <ram:SpecifiedLineTradeSettlement>
                        <t t-foreach="tax_details[''tax_details_per_record''][line][''tax_details''].values()" t-as="tax_detail_vals">
                            <ram:ApplicableTradeTax t-if="tax_detail_vals[''amount_type''] == ''percent''">
                                <ram:TypeCode t-translation="off">VAT</ram:TypeCode>
                                <ram:CategoryCode t-out="tax_detail_vals[''tax_category_code'']"/>
                                <ram:RateApplicablePercent t-out="tax_detail_vals[''amount'']"/>
                            </ram:ApplicableTradeTax>
                        </t>

                        <!-- Billing Period -->
                        <ram:BillingSpecifiedPeriod t-if="line_vals.get(''billing_start'') and line_vals.get(''billing_end'')"> 
                            <ram:StartDateTime>
                                <udt:DateTimeString format="102" t-out="format_date(line_vals[''billing_start''])"/>
                            </ram:StartDateTime>
                            <ram:EndDateTime>
                                <udt:DateTimeString format="102" t-out="format_date(line_vals[''billing_end''])"/>
                            </ram:EndDateTime>
                        </ram:BillingSpecifiedPeriod>

                        <!-- Allowance/Charge on the line -->
                        <t t-foreach="line_vals.get(''allowance_charge_vals_list'')" t-as="allowance_charge_vals">
                            <ram:SpecifiedTradeAllowanceCharge>
                                <ram:ChargeIndicator>
                                    <udt:Indicator t-esc="allowance_charge_vals[''indicator'']"/>
                                </ram:ChargeIndicator>
                                <ram:ActualAmount t-esc="format_monetary(allowance_charge_vals[''amount''], 2)"/>
                                <ram:ReasonCode t-esc="allowance_charge_vals[''reason_code'']"/>
                                <ram:Reason t-esc="allowance_charge_vals[''reason'']"/>
                            </ram:SpecifiedTradeAllowanceCharge>
                        </t>

                        <!-- Subtotal. -->
                        <ram:SpecifiedTradeSettlementLineMonetarySummation>
                            <ram:LineTotalAmount t-esc="format_monetary(line_vals[''line_total_amount''], 2)"/>
                        </ram:SpecifiedTradeSettlementLineMonetarySummation>

                    </ram:SpecifiedLineTradeSettlement>
                </ram:IncludedSupplyChainTradeLineItem>
            </t>
        </t>

        ', false, true, '2026-05-10 01:12:03.930547', '2026-05-10 01:12:03.930547', false);
INSERT INTO public.ir_ui_view VALUES (800, 16, NULL, 1, 1, 'account_invoice_partner_facturx_export_22', NULL, 'account_edi_ubl_cii.account_invoice_partner_facturx_export_22', 'qweb', 'account_edi_ubl_cii/data/cii_22_templates.xml', 'primary', '{"en_US": "<t t-name=\"account_edi_ubl_cii.account_invoice_partner_facturx_export_22\">\n            <t xmlns:ram=\"urn:un:unece:uncefact:data:standard:ReusableAggregateBusinessInformationEntity:100\" xmlns:rsm=\"urn:un:unece:uncefact:data:standard:CrossIndustryInvoice:100\" xmlns:udt=\"urn:un:unece:uncefact:data:standard:UnqualifiedDataType:100\" xmlns:qdt=\"urn:un:unece:uncefact:data:standard:QualifiedDataType:100\" xmlns:xsi=\"http://www.w3.org/2001/XMLSchema-instance\">\n                <!-- Contact. -->\n                <ram:Name t-out=\"partner.display_name if partner.name else partner.commercial_partner_id.display_name\"/>\n                <ram:SpecifiedLegalOrganization t-if=\"specified_legal_organization_val\">\n                    <ram:ID t-att-schemeID=\"str(''0002'')\" t-out=\"specified_legal_organization_val\"/>\n                </ram:SpecifiedLegalOrganization>\n\n                <ram:DefinedTradeContact t-if=\"not hide_dtc\">\n                    <ram:PersonName t-out=\"partner.name\"/>\n                    <ram:TelephoneUniversalCommunication t-if=\"partner.phone or partner.mobile\">\n                        <ram:CompleteNumber t-out=\"partner.phone or partner.mobile\"/>\n                    </ram:TelephoneUniversalCommunication>\n                    <ram:EmailURIUniversalCommunication t-if=\"partner.email\">\n                        <ram:URIID t-out=\"partner.email\"/>\n                    </ram:EmailURIUniversalCommunication>\n                </ram:DefinedTradeContact>\n\n                <!-- Address. -->\n                <t t-call=\"account_edi_ubl_cii.account_invoice_address_facturx_export_22\"/>\n            </t>\n        </t>"}', '<?xml version="1.0"?>
<t t-name="account_edi_ubl_cii.account_invoice_partner_facturx_export_22">
            <t xmlns:ram="urn:un:unece:uncefact:data:standard:ReusableAggregateBusinessInformationEntity:100" xmlns:rsm="urn:un:unece:uncefact:data:standard:CrossIndustryInvoice:100" xmlns:udt="urn:un:unece:uncefact:data:standard:UnqualifiedDataType:100" xmlns:qdt="urn:un:unece:uncefact:data:standard:QualifiedDataType:100" xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance">
                <!-- Contact. -->
                <ram:Name t-out="partner.display_name if partner.name else partner.commercial_partner_id.display_name"/>
                <ram:SpecifiedLegalOrganization t-if="specified_legal_organization_val">
                    <ram:ID t-att-schemeID="str(''0002'')" t-out="specified_legal_organization_val"/>
                </ram:SpecifiedLegalOrganization>

                <ram:DefinedTradeContact t-if="not hide_dtc">
                    <ram:PersonName t-out="partner.name"/>
                    <ram:TelephoneUniversalCommunication t-if="partner.phone or partner.mobile">
                        <ram:CompleteNumber t-out="partner.phone or partner.mobile"/>
                    </ram:TelephoneUniversalCommunication>
                    <ram:EmailURIUniversalCommunication t-if="partner.email">
                        <ram:URIID t-out="partner.email"/>
                    </ram:EmailURIUniversalCommunication>
                </ram:DefinedTradeContact>

                <!-- Address. -->
                <t t-call="account_edi_ubl_cii.account_invoice_address_facturx_export_22"/>
            </t>
        </t>

        ', false, true, '2026-05-10 01:12:03.930547', '2026-05-10 01:12:03.930547', false);
INSERT INTO public.ir_ui_view VALUES (801, 16, NULL, 1, 1, 'account_invoice_address_facturx_export_22', NULL, 'account_edi_ubl_cii.account_invoice_address_facturx_export_22', 'qweb', 'account_edi_ubl_cii/data/cii_22_templates.xml', 'primary', '{"en_US": "<t t-name=\"account_edi_ubl_cii.account_invoice_address_facturx_export_22\">\n            <t xmlns:ram=\"urn:un:unece:uncefact:data:standard:ReusableAggregateBusinessInformationEntity:100\" xmlns:rsm=\"urn:un:unece:uncefact:data:standard:CrossIndustryInvoice:100\" xmlns:udt=\"urn:un:unece:uncefact:data:standard:UnqualifiedDataType:100\" xmlns:qdt=\"urn:un:unece:uncefact:data:standard:QualifiedDataType:100\" xmlns:xsi=\"http://www.w3.org/2001/XMLSchema-instance\">\n                <!-- Address. -->\n                <ram:PostalTradeAddress>\n                    <ram:PostcodeCode t-out=\"partner.zip\"/>\n                    <ram:LineOne t-out=\"partner.street\"/>\n                    <ram:LineTwo t-out=\"partner.street2\"/>\n                    <ram:CityName t-out=\"partner.city\"/>\n                    <ram:CountryID t-out=\"partner.country_id.code\"/>\n                </ram:PostalTradeAddress>\n            </t>\n        </t>"}', '<?xml version="1.0"?>
<t t-name="account_edi_ubl_cii.account_invoice_address_facturx_export_22">
            <t xmlns:ram="urn:un:unece:uncefact:data:standard:ReusableAggregateBusinessInformationEntity:100" xmlns:rsm="urn:un:unece:uncefact:data:standard:CrossIndustryInvoice:100" xmlns:udt="urn:un:unece:uncefact:data:standard:UnqualifiedDataType:100" xmlns:qdt="urn:un:unece:uncefact:data:standard:QualifiedDataType:100" xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance">
                <!-- Address. -->
                <ram:PostalTradeAddress>
                    <ram:PostcodeCode t-out="partner.zip"/>
                    <ram:LineOne t-out="partner.street"/>
                    <ram:LineTwo t-out="partner.street2"/>
                    <ram:CityName t-out="partner.city"/>
                    <ram:CountryID t-out="partner.country_id.code"/>
                </ram:PostalTradeAddress>
            </t>
        </t>

        ', false, true, '2026-05-10 01:12:03.930547', '2026-05-10 01:12:03.930547', false);
INSERT INTO public.ir_ui_view VALUES (802, 16, NULL, 1, 1, 'account_invoice_facturx_export_22', NULL, 'account_edi_ubl_cii.account_invoice_facturx_export_22', 'qweb', 'account_edi_ubl_cii/data/cii_22_templates.xml', 'primary', '{"en_US": "<t t-name=\"account_edi_ubl_cii.account_invoice_facturx_export_22\">\n            <t t-set=\"currency\" t-value=\"record.currency_id or record.company_currency_id\"/>\n            <rsm:CrossIndustryInvoice xmlns:ram=\"urn:un:unece:uncefact:data:standard:ReusableAggregateBusinessInformationEntity:100\" xmlns:rsm=\"urn:un:unece:uncefact:data:standard:CrossIndustryInvoice:100\" xmlns:udt=\"urn:un:unece:uncefact:data:standard:UnqualifiedDataType:100\" xmlns:qdt=\"urn:un:unece:uncefact:data:standard:QualifiedDataType:100\" xmlns:xsi=\"http://www.w3.org/2001/XMLSchema-instance\">\n                <!-- Factur-x level:\n                    * minimum or basicwl:   urn:factur-x.eu:1p0...\n                    * basic:                urn:cen.eu:en16931:2017:compliant:factur-x.eu:1p0:basic\n                    * en16931:              urn:cen.eu:en16931:2017\n                -->\n                <rsm:ExchangedDocumentContext>\n                    <ram:GuidelineSpecifiedDocumentContextParameter>\n                        <ram:ID t-out=\"document_context_id\"/>\n                    </ram:GuidelineSpecifiedDocumentContextParameter>\n                </rsm:ExchangedDocumentContext>\n\n                <!-- Document Headers. -->\n                <rsm:ExchangedDocument>\n                    <ram:ID t-out=\"ExchangedDocument_vals.get(''id'')\"/>\n                    <ram:TypeCode t-out=\"ExchangedDocument_vals.get(''type_code'')\"/>\n                    <ram:IssueDateTime t-if=\"ExchangedDocument_vals.get(''issue_date_time'')\">\n                        <udt:DateTimeString format=\"102\" t-out=\"format_date(ExchangedDocument_vals.get(''issue_date_time''))\"/>\n                    </ram:IssueDateTime>\n                    <ram:IncludedNote>\n                        <ram:Content t-out=\"ExchangedDocument_vals.get(''included_note'')\"/>\n                    </ram:IncludedNote>\n                </rsm:ExchangedDocument>\n\n                <rsm:SupplyChainTradeTransaction>\n                    <!-- Invoice lines. -->\n                    <t t-foreach=\"invoice_line_vals_list\" t-as=\"line_vals\">\n                        <t t-call=\"account_edi_ubl_cii.account_invoice_line_facturx_export_22\"/>\n                    </t>\n\n                    <!-- Partners. -->\n                    <ram:ApplicableHeaderTradeAgreement>\n                        <!-- \"Service Exécutant\" (Used by Chorus Pro) -->\n                        <ram:BuyerReference t-out=\"buyer_reference\"/>\n                        <!-- Seller. -->\n                        <ram:SellerTradeParty>\n                            <!-- Address. -->\n                            <t t-call=\"account_edi_ubl_cii.account_invoice_partner_facturx_export_22\">\n                                <t t-set=\"partner\" t-value=\"record.company_id.partner_id\"/>\n                                <t t-set=\"specified_legal_organization_val\" t-value=\"seller_specified_legal_organization\"/>\n                            </t>\n\n                            <!-- VAT. -->\n                            <ram:SpecifiedTaxRegistration t-if=\"record.fiscal_position_id.foreign_vat\">\n                                <ram:ID schemeID=\"VA\" t-out=\"record.fiscal_position_id.foreign_vat\"/>\n                            </ram:SpecifiedTaxRegistration>\n\n                            <ram:SpecifiedTaxRegistration t-elif=\"record.company_id.vat\">\n                                <ram:ID schemeID=\"VA\" t-out=\"record.company_id.vat\"/>\n                            </ram:SpecifiedTaxRegistration>\n                        </ram:SellerTradeParty>\n\n                        <!-- Customer. -->\n                        <ram:BuyerTradeParty>\n                            <!-- Address. -->\n                            <t t-call=\"account_edi_ubl_cii.account_invoice_partner_facturx_export_22\">\n                                <t t-set=\"partner\" t-value=\"record.partner_id\"/>\n                                <t t-set=\"specified_legal_organization_val\" t-value=\"buyer_specified_legal_organization\"/>\n                            </t>\n\n                            <!-- VAT. -->\n                            <ram:SpecifiedTaxRegistration t-if=\"record.commercial_partner_id.vat\">\n                                <ram:ID schemeID=\"VA\" t-out=\"record.commercial_partner_id.vat\"/>\n                            </ram:SpecifiedTaxRegistration>\n                        </ram:BuyerTradeParty>\n\n                        <!-- Reference. -->\n                        <ram:BuyerOrderReferencedDocument>\n                            <!-- \"Engagement Juridique\" (used by Chorus Pro) -->\n                            <ram:IssuerAssignedID t-out=\"purchase_order_reference\"/>\n                        </ram:BuyerOrderReferencedDocument>\n                        <ram:ContractReferencedDocument>\n                            <!-- \"Numéro de Marché\" (Used by Chorus Pro) -->\n                            <ram:IssuerAssignedID t-out=\"contract_reference\"/>\n                        </ram:ContractReferencedDocument>\n                    </ram:ApplicableHeaderTradeAgreement>\n\n                    <!-- Delivery -->\n                    <ram:ApplicableHeaderTradeDelivery>\n                        <ram:ShipToTradeParty>\n                            <t t-call=\"account_edi_ubl_cii.account_invoice_partner_facturx_export_22\">\n                                <t t-set=\"partner\" t-value=\"ship_to_trade_party\"/>\n                                <t t-set=\"hide_dtc\" t-value=\"document_context_id == ''urn:cen.eu:en16931:2017#compliant#urn:xoev-de:kosit:standard:xrechnung_2.2''\"/>\n                            </t>\n                        </ram:ShipToTradeParty>\n\n                        <ram:ActualDeliverySupplyChainEvent t-if=\"scheduled_delivery_time\">\n                            <ram:OccurrenceDateTime>\n                                <udt:DateTimeString t-att-format=\"102\" t-out=\"format_date(scheduled_delivery_time)\"/>\n                            </ram:OccurrenceDateTime>\n                        </ram:ActualDeliverySupplyChainEvent>\n                    </ram:ApplicableHeaderTradeDelivery>\n\n                    <!-- Taxes. -->\n                    <ram:ApplicableHeaderTradeSettlement>\n\n                        <ram:PaymentReference t-out=\"record.payment_reference\"/>\n                        <ram:InvoiceCurrencyCode t-out=\"currency.name\"/>\n\n                        <!-- Bank account. -->\n                        <ram:SpecifiedTradeSettlementPaymentMeans t-if=\"record.partner_bank_id.sanitized_acc_number\">\n                            <ram:TypeCode t-out=\"payment_means_code\"/>\n                            <ram:PayeePartyCreditorFinancialAccount>\n                                <ram:IBANID t-if=\"record.partner_bank_id.acc_type == ''iban''\" t-out=\"record.partner_bank_id.sanitized_acc_number\"/>\n                                <ram:ProprietaryID t-if=\"record.partner_bank_id.acc_type != ''iban''\" t-out=\"record.partner_bank_id.sanitized_acc_number\"/>\n                            </ram:PayeePartyCreditorFinancialAccount>\n                        </ram:SpecifiedTradeSettlementPaymentMeans>\n\n                        <!-- Tax Summary. -->\n                        <t t-foreach=\"tax_details.get(''tax_details'', {}).values()\" t-as=\"tax_detail_vals\">\n                            <ram:ApplicableTradeTax>\n                                <ram:CalculatedAmount t-out=\"format_monetary(tax_detail_vals.get(''calculated_amount''), 2)\"/>\n                                <ram:TypeCode t-translation=\"off\">VAT</ram:TypeCode>\n                                <ram:ExemptionReason t-out=\"tax_detail_vals.get(''tax_exemption_reason'')\"/>\n                                <ram:BasisAmount t-out=\"format_monetary(tax_detail_vals[''base_amount_currency''], 2)\"/>\n                                <ram:CategoryCode t-out=\"tax_detail_vals[''tax_category_code'']\"/>\n                                <ram:ExemptionReasonCode t-out=\"tax_detail_vals[''tax_exemption_reason_code'']\"/>\n                                <!-- 5 = Tax is exigible on the date on the invoice -->\n                                <ram:DueDateTypeCode>5</ram:DueDateTypeCode>\n                                <ram:RateApplicablePercent t-if=\"tax_detail_vals[''amount_type''] == ''percent''\" t-out=\"tax_detail_vals[''amount'']\"/>\n                            </ram:ApplicableTradeTax>\n                        </t>\n\n                        <!-- Billing Period -->\n                        <ram:BillingSpecifiedPeriod t-if=\"billing_start and billing_end\">\n                            <ram:StartDateTime>\n                                <udt:DateTimeString format=\"102\" t-out=\"format_date(billing_start)\"/>\n                            </ram:StartDateTime>\n                            <ram:EndDateTime>\n                                <udt:DateTimeString format=\"102\" t-out=\"format_date(billing_end)\"/>\n                            </ram:EndDateTime>\n                        </ram:BillingSpecifiedPeriod>\n\n                        <!-- Payment Term. -->\n                        <ram:SpecifiedTradePaymentTerms>\n                            <ram:Description t-if=\"record.invoice_payment_term_id\" t-out=\"record.invoice_payment_term_id.name\"/>\n                            <ram:DueDateDateTime t-if=\"record.invoice_date_due\">\n                                <udt:DateTimeString format=\"102\" t-out=\"format_date(record.invoice_date_due)\"/>\n                            </ram:DueDateDateTime>\n                            <ram:ApplicableTradePaymentDiscountTerms t-if=\"record.invoice_payment_term_id.early_discount and record.invoice_payment_term_id.early_pay_discount_computation == ''mixed''\">\n                                <ram:BasisPeriodMeasure unitCode=\"DAY\" t-out=\"record.invoice_payment_term_id.discount_days\"/>\n                                <ram:CalculationPercent t-out=\"record.invoice_payment_term_id.discount_percentage\"/>\n                            </ram:ApplicableTradePaymentDiscountTerms>\n                        </ram:SpecifiedTradePaymentTerms>\n\n                        <!-- Summary. -->\n                        <ram:SpecifiedTradeSettlementHeaderMonetarySummation>\n                            <ram:LineTotalAmount t-esc=\"format_monetary(tax_basis_total_amount, 2)\"/>\n                            <ram:TaxBasisTotalAmount t-esc=\"format_monetary(tax_basis_total_amount, 2)\"/>\n                            <ram:TaxTotalAmount t-att-currencyID=\"currency.name\" t-esc=\"format_monetary(tax_total_amount, 2)\"/>\n                            <ram:GrandTotalAmount t-out=\"format_monetary(record.amount_total, 2)\"/>\n                            <ram:TotalPrepaidAmount t-out=\"format_monetary(record.amount_total - record.amount_residual, 2)\"/>\n                            <ram:DuePayableAmount t-out=\"format_monetary(record.amount_residual, 2)\"/>\n                        </ram:SpecifiedTradeSettlementHeaderMonetarySummation>\n                    </ram:ApplicableHeaderTradeSettlement>\n                </rsm:SupplyChainTradeTransaction>\n            </rsm:CrossIndustryInvoice>\n        </t>"}', '<?xml version="1.0"?>
<t t-name="account_edi_ubl_cii.account_invoice_facturx_export_22">
            <t t-set="currency" t-value="record.currency_id or record.company_currency_id"/>
            <rsm:CrossIndustryInvoice xmlns:ram="urn:un:unece:uncefact:data:standard:ReusableAggregateBusinessInformationEntity:100" xmlns:rsm="urn:un:unece:uncefact:data:standard:CrossIndustryInvoice:100" xmlns:udt="urn:un:unece:uncefact:data:standard:UnqualifiedDataType:100" xmlns:qdt="urn:un:unece:uncefact:data:standard:QualifiedDataType:100" xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance">
                <!-- Factur-x level:
                    * minimum or basicwl:   urn:factur-x.eu:1p0...
                    * basic:                urn:cen.eu:en16931:2017:compliant:factur-x.eu:1p0:basic
                    * en16931:              urn:cen.eu:en16931:2017
                -->
                <rsm:ExchangedDocumentContext>
                    <ram:GuidelineSpecifiedDocumentContextParameter>
                        <ram:ID t-out="document_context_id"/>
                    </ram:GuidelineSpecifiedDocumentContextParameter>
                </rsm:ExchangedDocumentContext>

                <!-- Document Headers. -->
                <rsm:ExchangedDocument>
                    <ram:ID t-out="ExchangedDocument_vals.get(''id'')"/>
                    <ram:TypeCode t-out="ExchangedDocument_vals.get(''type_code'')"/>
                    <ram:IssueDateTime t-if="ExchangedDocument_vals.get(''issue_date_time'')">
                        <udt:DateTimeString format="102" t-out="format_date(ExchangedDocument_vals.get(''issue_date_time''))"/>
                    </ram:IssueDateTime>
                    <ram:IncludedNote>
                        <ram:Content t-out="ExchangedDocument_vals.get(''included_note'')"/>
                    </ram:IncludedNote>
                </rsm:ExchangedDocument>

                <rsm:SupplyChainTradeTransaction>
                    <!-- Invoice lines. -->
                    <t t-foreach="invoice_line_vals_list" t-as="line_vals">
                        <t t-call="account_edi_ubl_cii.account_invoice_line_facturx_export_22"/>
                    </t>

                    <!-- Partners. -->
                    <ram:ApplicableHeaderTradeAgreement>
                        <!-- "Service Exécutant" (Used by Chorus Pro) -->
                        <ram:BuyerReference t-out="buyer_reference"/>
                        <!-- Seller. -->
                        <ram:SellerTradeParty>
                            <!-- Address. -->
                            <t t-call="account_edi_ubl_cii.account_invoice_partner_facturx_export_22">
                                <t t-set="partner" t-value="record.company_id.partner_id"/>
                                <t t-set="specified_legal_organization_val" t-value="seller_specified_legal_organization"/>
                            </t>

                            <!-- VAT. -->
                            <ram:SpecifiedTaxRegistration t-if="record.fiscal_position_id.foreign_vat">
                                <ram:ID schemeID="VA" t-out="record.fiscal_position_id.foreign_vat"/>
                            </ram:SpecifiedTaxRegistration>

                            <ram:SpecifiedTaxRegistration t-elif="record.company_id.vat">
                                <ram:ID schemeID="VA" t-out="record.company_id.vat"/>
                            </ram:SpecifiedTaxRegistration>
                        </ram:SellerTradeParty>

                        <!-- Customer. -->
                        <ram:BuyerTradeParty>
                            <!-- Address. -->
                            <t t-call="account_edi_ubl_cii.account_invoice_partner_facturx_export_22">
                                <t t-set="partner" t-value="record.partner_id"/>
                                <t t-set="specified_legal_organization_val" t-value="buyer_specified_legal_organization"/>
                            </t>

                            <!-- VAT. -->
                            <ram:SpecifiedTaxRegistration t-if="record.commercial_partner_id.vat">
                                <ram:ID schemeID="VA" t-out="record.commercial_partner_id.vat"/>
                            </ram:SpecifiedTaxRegistration>
                        </ram:BuyerTradeParty>

                        <!-- Reference. -->
                        <ram:BuyerOrderReferencedDocument>
                            <!-- "Engagement Juridique" (used by Chorus Pro) -->
                            <ram:IssuerAssignedID t-out="purchase_order_reference"/>
                        </ram:BuyerOrderReferencedDocument>
                        <ram:ContractReferencedDocument>
                            <!-- "Numéro de Marché" (Used by Chorus Pro) -->
                            <ram:IssuerAssignedID t-out="contract_reference"/>
                        </ram:ContractReferencedDocument>
                    </ram:ApplicableHeaderTradeAgreement>

                    <!-- Delivery -->
                    <ram:ApplicableHeaderTradeDelivery>
                        <ram:ShipToTradeParty>
                            <t t-call="account_edi_ubl_cii.account_invoice_partner_facturx_export_22">
                                <t t-set="partner" t-value="ship_to_trade_party"/>
                                <t t-set="hide_dtc" t-value="document_context_id == ''urn:cen.eu:en16931:2017#compliant#urn:xoev-de:kosit:standard:xrechnung_2.2''"/>
                            </t>
                        </ram:ShipToTradeParty>

                        <ram:ActualDeliverySupplyChainEvent t-if="scheduled_delivery_time">
                            <ram:OccurrenceDateTime>
                                <udt:DateTimeString t-att-format="102" t-out="format_date(scheduled_delivery_time)"/>
                            </ram:OccurrenceDateTime>
                        </ram:ActualDeliverySupplyChainEvent>
                    </ram:ApplicableHeaderTradeDelivery>

                    <!-- Taxes. -->
                    <ram:ApplicableHeaderTradeSettlement>

                        <ram:PaymentReference t-out="record.payment_reference"/>
                        <ram:InvoiceCurrencyCode t-out="currency.name"/>

                        <!-- Bank account. -->
                        <ram:SpecifiedTradeSettlementPaymentMeans t-if="record.partner_bank_id.sanitized_acc_number">
                            <ram:TypeCode t-out="payment_means_code"/>
                            <ram:PayeePartyCreditorFinancialAccount>
                                <ram:IBANID t-if="record.partner_bank_id.acc_type == ''iban''" t-out="record.partner_bank_id.sanitized_acc_number"/>
                                <ram:ProprietaryID t-if="record.partner_bank_id.acc_type != ''iban''" t-out="record.partner_bank_id.sanitized_acc_number"/>
                            </ram:PayeePartyCreditorFinancialAccount>
                        </ram:SpecifiedTradeSettlementPaymentMeans>

                        <!-- Tax Summary. -->
                        <t t-foreach="tax_details.get(''tax_details'', {}).values()" t-as="tax_detail_vals">
                            <ram:ApplicableTradeTax>
                                <ram:CalculatedAmount t-out="format_monetary(tax_detail_vals.get(''calculated_amount''), 2)"/>
                                <ram:TypeCode t-translation="off">VAT</ram:TypeCode>
                                <ram:ExemptionReason t-out="tax_detail_vals.get(''tax_exemption_reason'')"/>
                                <ram:BasisAmount t-out="format_monetary(tax_detail_vals[''base_amount_currency''], 2)"/>
                                <ram:CategoryCode t-out="tax_detail_vals[''tax_category_code'']"/>
                                <ram:ExemptionReasonCode t-out="tax_detail_vals[''tax_exemption_reason_code'']"/>
                                <!-- 5 = Tax is exigible on the date on the invoice -->
                                <ram:DueDateTypeCode>5</ram:DueDateTypeCode>
                                <ram:RateApplicablePercent t-if="tax_detail_vals[''amount_type''] == ''percent''" t-out="tax_detail_vals[''amount'']"/>
                            </ram:ApplicableTradeTax>
                        </t>

                        <!-- Billing Period -->
                        <ram:BillingSpecifiedPeriod t-if="billing_start and billing_end">
                            <ram:StartDateTime>
                                <udt:DateTimeString format="102" t-out="format_date(billing_start)"/>
                            </ram:StartDateTime>
                            <ram:EndDateTime>
                                <udt:DateTimeString format="102" t-out="format_date(billing_end)"/>
                            </ram:EndDateTime>
                        </ram:BillingSpecifiedPeriod>

                        <!-- Payment Term. -->
                        <ram:SpecifiedTradePaymentTerms>
                            <ram:Description t-if="record.invoice_payment_term_id" t-out="record.invoice_payment_term_id.name"/>
                            <ram:DueDateDateTime t-if="record.invoice_date_due">
                                <udt:DateTimeString format="102" t-out="format_date(record.invoice_date_due)"/>
                            </ram:DueDateDateTime>
                            <ram:ApplicableTradePaymentDiscountTerms t-if="record.invoice_payment_term_id.early_discount and record.invoice_payment_term_id.early_pay_discount_computation == ''mixed''">
                                <ram:BasisPeriodMeasure unitCode="DAY" t-out="record.invoice_payment_term_id.discount_days"/>
                                <ram:CalculationPercent t-out="record.invoice_payment_term_id.discount_percentage"/>
                            </ram:ApplicableTradePaymentDiscountTerms>
                        </ram:SpecifiedTradePaymentTerms>

                        <!-- Summary. -->
                        <ram:SpecifiedTradeSettlementHeaderMonetarySummation>
                            <ram:LineTotalAmount t-esc="format_monetary(tax_basis_total_amount, 2)"/>
                            <ram:TaxBasisTotalAmount t-esc="format_monetary(tax_basis_total_amount, 2)"/>
                            <ram:TaxTotalAmount t-att-currencyID="currency.name" t-esc="format_monetary(tax_total_amount, 2)"/>
                            <ram:GrandTotalAmount t-out="format_monetary(record.amount_total, 2)"/>
                            <ram:TotalPrepaidAmount t-out="format_monetary(record.amount_total - record.amount_residual, 2)"/>
                            <ram:DuePayableAmount t-out="format_monetary(record.amount_residual, 2)"/>
                        </ram:SpecifiedTradeSettlementHeaderMonetarySummation>
                    </ram:ApplicableHeaderTradeSettlement>
                </rsm:SupplyChainTradeTransaction>
            </rsm:CrossIndustryInvoice>
        </t>

        ', false, true, '2026-05-10 01:12:03.930547', '2026-05-10 01:12:03.930547', false);
INSERT INTO public.ir_ui_view VALUES (803, 16, NULL, 1, 1, 'account_invoice_pdfa_3_facturx_metadata', NULL, 'account_edi_ubl_cii.account_invoice_pdfa_3_facturx_metadata', 'qweb', 'account_edi_ubl_cii/data/cii_22_templates.xml', 'primary', '{"en_US": "<t t-name=\"account_edi_ubl_cii.account_invoice_pdfa_3_facturx_metadata\">\n            <x:xmpmeta xmlns:x=\"adobe:ns:meta/\">\n                <rdf:RDF xmlns:rdf=\"http://www.w3.org/1999/02/22-rdf-syntax-ns#\">\n                    <rdf:Description xmlns:pdfaid=\"http://www.aiim.org/pdfa/ns/id/\" rdf:about=\"\">\n                        <pdfaid:part>3</pdfaid:part>\n                        <pdfaid:conformance>A</pdfaid:conformance>\n                    </rdf:Description>\n                    <rdf:Description xmlns:dc=\"http://purl.org/dc/elements/1.1/\" rdf:about=\"\">\n                        <dc:title>\n                            <rdf:Alt>\n                                <rdf:li t-att=\"{''xml:lang'': ''x-default''}\" t-out=\"title\"/>\n                            </rdf:Alt>\n                        </dc:title>\n                        <dc:creator>\n                            <rdf:Seq>\n                                <rdf:li>Odoo</rdf:li>\n                            </rdf:Seq>\n                        </dc:creator>\n                        <dc:description>\n                            <rdf:Alt>\n                                <rdf:li t-att=\"{''xml:lang'': ''x-default''}\">Invoice generated by Odoo</rdf:li>\n                            </rdf:Alt>\n                        </dc:description>\n                    </rdf:Description>\n                    <rdf:Description xmlns:pdf=\"http://ns.adobe.com/pdf/1.3/\" rdf:about=\"\">\n                        <pdf:Producer>Odoo</pdf:Producer>\n                    </rdf:Description>\n                    <rdf:Description xmlns:xmp=\"http://ns.adobe.com/xap/1.0/\" rdf:about=\"\">\n                        <xmp:CreatorTool>Odoo</xmp:CreatorTool>\n                        <xmp:CreateDate t-out=\"date\"/>\n                        <xmp:ModifyDate t-out=\"date\"/>\n                    </rdf:Description>\n                    <rdf:Description xmlns:pdfaExtension=\"http://www.aiim.org/pdfa/ns/extension/\" xmlns:pdfaSchema=\"http://www.aiim.org/pdfa/ns/schema#\" xmlns:pdfaProperty=\"http://www.aiim.org/pdfa/ns/property#\" rdf:about=\"\">\n                        <pdfaExtension:schemas>\n                            <rdf:Bag>\n                                <rdf:li rdf:parseType=\"Resource\">\n                                    <pdfaSchema:schema t-translation=\"off\">Factur-X PDFA Extension Schema</pdfaSchema:schema>\n                                    <pdfaSchema:namespaceURI>urn:factur-x:pdfa:CrossIndustryDocument:invoice:1p0#</pdfaSchema:namespaceURI>\n                                    <pdfaSchema:prefix>fx</pdfaSchema:prefix>\n                                    <pdfaSchema:property>\n                                        <rdf:Seq>\n                                            <rdf:li rdf:parseType=\"Resource\">\n                                                <pdfaProperty:name t-translation=\"off\">DocumentFileName</pdfaProperty:name>\n                                                <pdfaProperty:valueType t-translation=\"off\">Text</pdfaProperty:valueType>\n                                                <pdfaProperty:category t-translation=\"off\">external</pdfaProperty:category>\n                                                <pdfaProperty:description t-translation=\"off\">name of the embedded XML invoice file</pdfaProperty:description>\n                                            </rdf:li>\n                                            <rdf:li rdf:parseType=\"Resource\">\n                                                <pdfaProperty:name t-translation=\"off\">DocumentType</pdfaProperty:name>\n                                                <pdfaProperty:valueType t-translation=\"off\">Text</pdfaProperty:valueType>\n                                                <pdfaProperty:category t-translation=\"off\">external</pdfaProperty:category>\n                                                <pdfaProperty:description t-translation=\"off\">INVOICE</pdfaProperty:description>\n                                            </rdf:li>\n                                            <rdf:li rdf:parseType=\"Resource\">\n                                                <pdfaProperty:name t-translation=\"off\">Version</pdfaProperty:name>\n                                                <pdfaProperty:valueType t-translation=\"off\">Text</pdfaProperty:valueType>\n                                                <pdfaProperty:category t-translation=\"off\">external</pdfaProperty:category>\n                                                <pdfaProperty:description t-translation=\"off\">The actual version of the Factur-X XML schema</pdfaProperty:description>\n                                            </rdf:li>\n                                            <rdf:li rdf:parseType=\"Resource\">\n                                                <pdfaProperty:name t-translation=\"off\">ConformanceLevel</pdfaProperty:name>\n                                                <pdfaProperty:valueType t-translation=\"off\">Text</pdfaProperty:valueType>\n                                                <pdfaProperty:category t-translation=\"off\">external</pdfaProperty:category>\n                                                <pdfaProperty:description t-translation=\"off\">The conformance level of the embedded Factur-X data</pdfaProperty:description>\n                                            </rdf:li>\n                                        </rdf:Seq>\n                                    </pdfaSchema:property>\n                                </rdf:li>\n                            </rdf:Bag>\n                        </pdfaExtension:schemas>\n                    </rdf:Description>\n                    <rdf:Description xmlns:fx=\"urn:factur-x:pdfa:CrossIndustryDocument:invoice:1p0#\" rdf:about=\"\">\n                        <fx:ConformanceLevel>EN 16931</fx:ConformanceLevel>\n                        <fx:DocumentFileName>factur-x.xml</fx:DocumentFileName>\n                        <fx:DocumentType t-translation=\"off\">INVOICE</fx:DocumentType>\n                        <fx:Version>1.0</fx:Version>\n                    </rdf:Description>\n                </rdf:RDF>\n            </x:xmpmeta>\n        </t>"}', '<?xml version="1.0"?>
