INSERT INTO public.ir_ui_view VALUES (837, 16, 122, 1, 1, 'res.partner.tree.inherit', 'res.partner', NULL, 'tree', 'account_edi_ubl_cii/views/res_partner_views.xml', 'extension', '{"en_US": "<xpath expr=\"//field[@name=''vat'']\" position=\"after\">\n                <field name=\"ubl_cii_format\" string=\"EDI Format\" optional=\"hide\"/>\n            </xpath>"}', '<?xml version="1.0"?>
<xpath expr="//field[@name=''vat'']" position="after">
                <field name="ubl_cii_format" string="EDI Format" optional="hide"/>
