INSERT INTO public.ir_ui_view VALUES (816, 16, NULL, 1, 1, 'ubl_20_CommonLineType', NULL, 'account_edi_ubl_cii.ubl_20_CommonLineType', 'qweb', 'account_edi_ubl_cii/data/ubl_20_templates.xml', 'primary', '{"en_US": "<t t-name=\"account_edi_ubl_cii.ubl_20_CommonLineType\">\n        <t xmlns=\"urn:oasis:names:specification:ubl:schema:xsd:Invoice-2\" xmlns:cac=\"urn:oasis:names:specification:ubl:schema:xsd:CommonAggregateComponents-2\" xmlns:cbc=\"urn:oasis:names:specification:ubl:schema:xsd:CommonBasicComponents-2\">\n            <cbc:ID t-out=\"vals.get(''id'')\"/>\n            <cbc:Note t-out=\"vals.get(''note'')\"/>\n            <cbc:LineExtensionAmount t-att-currencyID=\"vals[''currency''].name\" t-out=\"format_float(vals.get(''line_extension_amount''), vals.get(''currency_dp''))\"/>\n            <cac:PricingReference>\n                <t t-set=\"pr_vals\" t-value=\"vals.get(''pricing_reference_vals'', {})\"/>\n                <cac:AlternativeConditionPrice t-foreach=\"pr_vals.get(''alternative_condition_price_vals'', [])\" t-as=\"foreach_vals\">\n                    <cbc:PriceAmount t-att-currencyID=\"foreach_vals[''currency''].name\" t-out=\"format_float(foreach_vals.get(''price_amount''), foreach_vals.get(''price_amount_dp''))\"/>\n                    <cbc:PriceTypeCode t-out=\"foreach_vals.get(''price_type_code'')\"/>\n                </cac:AlternativeConditionPrice>\n            </cac:PricingReference>\n            <cac:TaxTotal t-foreach=\"vals.get(''tax_total_vals'', [])\" t-as=\"foreach_vals\">\n                <t t-call=\"{{TaxTotalType_template}}\">\n                    <t t-set=\"vals\" t-value=\"foreach_vals\"/>\n                </t>\n            </cac:TaxTotal>\n            <cac:Item>\n                <t t-set=\"item_vals\" t-value=\"vals.get(''item_vals'', {})\"/>\n                <cbc:Description t-out=\"item_vals.get(''description'')\"/>\n                <cbc:Name t-out=\"item_vals.get(''name'')\"/>\n                <cac:SellersItemIdentification>\n                    <cbc:ID t-out=\"item_vals.get(''sellers_item_identification_vals'', {}).get(''id'')\"/>\n                </cac:SellersItemIdentification>\n                <cac:StandardItemIdentification>\n                    <t t-set=\"standard_item_identification_vals\" t-value=\"item_vals.get(''standard_item_identification_vals'', {})\"/>\n                    <cbc:ID t-att=\"standard_item_identification_vals.get(''id_attrs'')\" t-out=\"standard_item_identification_vals.get(''id'')\"/>\n                </cac:StandardItemIdentification>\n                <cac:CommodityClassification t-foreach=\"item_vals.get(''commodity_classification_vals'', [])\" t-as=\"foreach_vals\">\n                    <cbc:ItemClassificationCode t-att=\"foreach_vals.get(''item_classification_attrs'', {})\" t-out=\"foreach_vals.get(''item_classification_code'')\"/>\n                </cac:CommodityClassification>\n                <cac:ClassifiedTaxCategory t-foreach=\"item_vals.get(''classified_tax_category_vals'', [])\" t-as=\"foreach_vals\">\n                    <t t-call=\"{{TaxCategoryType_template}}\">\n                        <t t-set=\"vals\" t-value=\"foreach_vals\"/>\n                    </t>\n                </cac:ClassifiedTaxCategory>\n            </cac:Item>\n            <cac:Price>\n                <t t-set=\"price_vals\" t-value=\"vals.get(''price_vals'', {})\"/>\n                <cbc:PriceAmount t-att-currencyID=\"price_vals[''currency''].name\" t-out=\"price_vals.get(''price_amount'')\"/>\n                <!-- nbr of item units to which the price applies), i.e.: 1 Dozen = 12 units, not mandatory -->\n                <cbc:BaseQuantity t-att=\"price_vals.get(''base_quantity_attrs'', {})\" t-out=\"price_vals.get(''base_quantity'')\"/>\n            </cac:Price>\n        </t>\n    </t>"}', '<?xml version="1.0"?>
<t t-name="account_edi_ubl_cii.ubl_20_CommonLineType">
        <t xmlns="urn:oasis:names:specification:ubl:schema:xsd:Invoice-2" xmlns:cac="urn:oasis:names:specification:ubl:schema:xsd:CommonAggregateComponents-2" xmlns:cbc="urn:oasis:names:specification:ubl:schema:xsd:CommonBasicComponents-2">
            <cbc:ID t-out="vals.get(''id'')"/>
            <cbc:Note t-out="vals.get(''note'')"/>
            <cbc:LineExtensionAmount t-att-currencyID="vals[''currency''].name" t-out="format_float(vals.get(''line_extension_amount''), vals.get(''currency_dp''))"/>
            <cac:PricingReference>
                <t t-set="pr_vals" t-value="vals.get(''pricing_reference_vals'', {})"/>
                <cac:AlternativeConditionPrice t-foreach="pr_vals.get(''alternative_condition_price_vals'', [])" t-as="foreach_vals">
                    <cbc:PriceAmount t-att-currencyID="foreach_vals[''currency''].name" t-out="format_float(foreach_vals.get(''price_amount''), foreach_vals.get(''price_amount_dp''))"/>
                    <cbc:PriceTypeCode t-out="foreach_vals.get(''price_type_code'')"/>
                </cac:AlternativeConditionPrice>
            </cac:PricingReference>
            <cac:TaxTotal t-foreach="vals.get(''tax_total_vals'', [])" t-as="foreach_vals">
                <t t-call="{{TaxTotalType_template}}">
                    <t t-set="vals" t-value="foreach_vals"/>
                </t>
            </cac:TaxTotal>
            <cac:Item>
                <t t-set="item_vals" t-value="vals.get(''item_vals'', {})"/>
                <cbc:Description t-out="item_vals.get(''description'')"/>
                <cbc:Name t-out="item_vals.get(''name'')"/>
                <cac:SellersItemIdentification>
                    <cbc:ID t-out="item_vals.get(''sellers_item_identification_vals'', {}).get(''id'')"/>
                </cac:SellersItemIdentification>
                <cac:StandardItemIdentification>
                    <t t-set="standard_item_identification_vals" t-value="item_vals.get(''standard_item_identification_vals'', {})"/>
                    <cbc:ID t-att="standard_item_identification_vals.get(''id_attrs'')" t-out="standard_item_identification_vals.get(''id'')"/>
                </cac:StandardItemIdentification>
                <cac:CommodityClassification t-foreach="item_vals.get(''commodity_classification_vals'', [])" t-as="foreach_vals">
