                </cac:Delivery>
                <cac:PaymentMeans t-foreach="vals.get(''payment_means_vals_list'', [])" t-as="foreach_vals">
                    <t t-call="{{PaymentMeansType_template}}">
                        <t t-set="vals" t-value="foreach_vals"/>
                    </t>
                </cac:PaymentMeans>
                <cac:PaymentTerms t-foreach="vals.get(''payment_terms_vals'', [])" t-as="foreach_vals">
                    <t t-call="{{PaymentTermsType_template}}">
                        <t t-set="vals" t-value="foreach_vals"/>
                    </t>
                </cac:PaymentTerms>
            </t>
        </xpath>
    <xpath expr="." position="attributes"><attribute name="t-name">account_edi_ubl_cii.ubl_21_CreditNoteType</attribute></xpath></data>

    ', false, true, '2026-05-10 01:12:03.930547', '2026-05-10 01:12:03.930547', false);
INSERT INTO public.ir_ui_view VALUES (833, 16, 824, 1, 1, 'ubl_21_DebitNoteType', NULL, 'account_edi_ubl_cii.ubl_21_DebitNoteType', 'qweb', 'account_edi_ubl_cii/data/ubl_21_templates.xml', 'primary', '{"en_US": "<data inherit_id=\"account_edi_ubl_cii.ubl_20_DebitNoteType\" primary=\"True\">\n        <xpath expr=\"//*[local-name()=''TaxCurrencyCode'']\" position=\"after\">\n            <t xmlns:cbc=\"urn:oasis:names:specification:ubl:schema:xsd:CommonBasicComponents-2\">\n                <cbc:BuyerReference t-out=\"vals.get(''buyer_reference'')\"/>\n            </t>\n        </xpath>\n        <xpath expr=\"//*[local-name()=''TaxTotal'']\" position=\"before\">\n            <t xmlns:cac=\"urn:oasis:names:specification:ubl:schema:xsd:CommonAggregateComponents-2\">\n                <cac:AllowanceCharge t-foreach=\"vals.get(''allowance_charge_vals'', [])\" t-as=\"foreach_vals\">\n                    <t t-call=\"{{AllowanceChargeType_template}}\">\n                        <t t-set=\"vals\" t-value=\"foreach_vals\"/>\n                    </t>\n                </cac:AllowanceCharge>\n                <cac:Delivery t-foreach=\"vals.get(''delivery_vals_list'', [])\" t-as=\"foreach_vals\">\n                    <t t-call=\"{{DeliveryType_template}}\">\n                        <t t-set=\"vals\" t-value=\"foreach_vals\"/>\n                    </t>\n                </cac:Delivery>\n                <cac:PaymentMeans t-foreach=\"vals.get(''payment_means_vals_list'', [])\" t-as=\"foreach_vals\">\n                    <t t-call=\"{{PaymentMeansType_template}}\">\n                        <t t-set=\"vals\" t-value=\"foreach_vals\"/>\n                    </t>\n                </cac:PaymentMeans>\n                <cac:PaymentTerms t-foreach=\"vals.get(''payment_terms_vals'', [])\" t-as=\"foreach_vals\">\n                    <t t-call=\"{{PaymentTermsType_template}}\">\n                        <t t-set=\"vals\" t-value=\"foreach_vals\"/>\n                    </t>\n                </cac:PaymentTerms>\n            </t>\n        </xpath>\n    <xpath expr=\".\" position=\"attributes\"><attribute name=\"t-name\">account_edi_ubl_cii.ubl_21_DebitNoteType</attribute></xpath></data>"}', '<?xml version="1.0"?>
<data inherit_id="account_edi_ubl_cii.ubl_20_DebitNoteType" primary="True">
        <xpath expr="//*[local-name()=''TaxCurrencyCode'']" position="after">
            <t xmlns:cbc="urn:oasis:names:specification:ubl:schema:xsd:CommonBasicComponents-2">
                <cbc:BuyerReference t-out="vals.get(''buyer_reference'')"/>
            </t>
        </xpath>
        <xpath expr="//*[local-name()=''TaxTotal'']" position="before">
            <t xmlns:cac="urn:oasis:names:specification:ubl:schema:xsd:CommonAggregateComponents-2">
                <cac:AllowanceCharge t-foreach="vals.get(''allowance_charge_vals'', [])" t-as="foreach_vals">
                    <t t-call="{{AllowanceChargeType_template}}">
                        <t t-set="vals" t-value="foreach_vals"/>
                    </t>
                </cac:AllowanceCharge>
                <cac:Delivery t-foreach="vals.get(''delivery_vals_list'', [])" t-as="foreach_vals">
                    <t t-call="{{DeliveryType_template}}">
                        <t t-set="vals" t-value="foreach_vals"/>
                    </t>
                </cac:Delivery>
                <cac:PaymentMeans t-foreach="vals.get(''payment_means_vals_list'', [])" t-as="foreach_vals">
                    <t t-call="{{PaymentMeansType_template}}">
                        <t t-set="vals" t-value="foreach_vals"/>
                    </t>
                </cac:PaymentMeans>
                <cac:PaymentTerms t-foreach="vals.get(''payment_terms_vals'', [])" t-as="foreach_vals">
                    <t t-call="{{PaymentTermsType_template}}">
                        <t t-set="vals" t-value="foreach_vals"/>
                    </t>
                </cac:PaymentTerms>
            </t>
        </xpath>
    <xpath expr="." position="attributes"><attribute name="t-name">account_edi_ubl_cii.ubl_21_DebitNoteType</attribute></xpath></data>

', false, true, '2026-05-10 01:12:03.930547', '2026-05-10 01:12:03.930547', false);
INSERT INTO public.ir_ui_view VALUES (834, 16, 765, 1, 1, 'res.config.settings.view.form.inherit.account_edi_ubl_cii', 'res.config.settings', NULL, 'form', 'account_edi_ubl_cii/views/res_config_settings_views.xml', 'extension', '{"en_US": "<xpath expr=\"//setting[@id=''default_setting_options'']/div/div\" position=\"inside\">\n                <div>\n                    <field name=\"invoice_is_ubl_cii\"/>\n                    <label for=\"invoice_is_ubl_cii\"/>\n                    <span class=\"fa fa-lg fa-building-o\" title=\"Values set here are company-specific.\"/>\n                </div>\n            </xpath>"}', '<?xml version="1.0"?>
<xpath expr="//setting[@id=''default_setting_options'']/div/div" position="inside">
                <div>
                    <field name="invoice_is_ubl_cii"/>
                    <label for="invoice_is_ubl_cii"/>
                    <span class="fa fa-lg fa-building-o" title="Values set here are company-specific."/>
                </div>
            </xpath>
        ', false, true, '2026-05-10 01:12:03.930547', '2026-05-10 01:12:03.930547', false);
INSERT INTO public.ir_ui_view VALUES (838, 16, 786, 1, 1, 'account.move.send.form', 'account.move.send', NULL, 'form', 'account_edi_ubl_cii/wizard/account_move_send_views.xml', 'extension', '{"en_US": "<data><xpath expr=\"//div[@name=''warnings'']\" position=\"inside\">\n                <field name=\"show_ubl_company_warning\" invisible=\"1\"/>\n                <div class=\"alert alert-info\" role=\"alert\" invisible=\"not checkbox_ubl_cii_xml or not ubl_partner_warning\">\n                    <field name=\"ubl_partner_warning\"/>\n                </div>\n                <div class=\"alert alert-info\" role=\"alert\" invisible=\"not checkbox_ubl_cii_xml or not show_ubl_company_warning\">\n                    Please fill in Peppol EAS and Peppol Endpoint in your company form to generate a complete file.\n                </div>\n            </xpath>\n            <xpath expr=\"//div[@name=''advanced_options'']\" position=\"inside\">\n                <field name=\"enable_ubl_cii_xml\" invisible=\"1\"/>\n                <div name=\"option_xml\" invisible=\"not enable_ubl_cii_xml\">\n                    <!-- Use one field as the label for another -->\n                    <field name=\"checkbox_ubl_cii_xml\" nolabel=\"1\" style=\"display: inline-block\"/>\n                    <field name=\"checkbox_ubl_cii_label\" style=\"position: absolute\"/>\n                </div>\n            </xpath>\n        </data>"}', '<?xml version="1.0"?>
<data><xpath expr="//div[@name=''warnings'']" position="inside">
                <field name="show_ubl_company_warning" invisible="1"/>
                <div class="alert alert-info" role="alert" invisible="not checkbox_ubl_cii_xml or not ubl_partner_warning">
                    <field name="ubl_partner_warning"/>
                </div>
                <div class="alert alert-info" role="alert" invisible="not checkbox_ubl_cii_xml or not show_ubl_company_warning">
                    Please fill in Peppol EAS and Peppol Endpoint in your company form to generate a complete file.
                </div>
            </xpath>
            <xpath expr="//div[@name=''advanced_options'']" position="inside">
                <field name="enable_ubl_cii_xml" invisible="1"/>
                <div name="option_xml" invisible="not enable_ubl_cii_xml">
                    <!-- Use one field as the label for another -->
                    <field name="checkbox_ubl_cii_xml" nolabel="1" style="display: inline-block"/>
                    <field name="checkbox_ubl_cii_label" style="position: absolute"/>
                </div>
            </xpath>
        </data>', false, true, '2026-05-10 01:12:03.930547', '2026-05-10 01:12:03.930547', false);
INSERT INTO public.ir_ui_view VALUES (839, 16, 775, 1, 1, 'Payment on My Invoices', NULL, 'account_payment.portal_my_invoices_payment', 'qweb', 'account_payment/views/account_portal_templates.xml', 'extension', '{"en_US": "<data name=\"Payment on My Invoices\" inherit_id=\"account.portal_my_invoices\">\n        <xpath expr=\"//t[@t-call=''portal.portal_table'']/thead/tr/th[last()]\" position=\"before\">\n            <th/>\n        </xpath>\n        <xpath expr=\"//t[@t-foreach=''invoices'']/tr/td[last()]\" position=\"before\">\n            <td class=\"text-center\">\n                <a t-if=\"invoice._has_to_be_paid()\" t-att-href=\"invoice.get_portal_url(anchor=''portal_pay'')\" title=\"Pay Now\" aria-label=\"Pay now\" class=\"btn btn-sm btn-primary\" role=\"button\">\n                    <i class=\"fa fa-arrow-circle-right\"/><span class=\"d-none d-md-inline\"> Pay Now</span>\n                </a>\n            </td>\n        </xpath>\n        <xpath expr=\"//t[@name=''invoice_status_posted'']/span[1]\" position=\"before\">\n            <t t-set=\"tx_sudo\" t-value=\"invoice.get_portal_last_transaction()\"/>\n        </xpath>\n        <xpath expr=\"//span[@name=''invoice_status_waiting_for_payment'']\" position=\"before\">\n            <span t-elif=\"invoice.payment_state in (''not_paid'', ''partial'') and tx_sudo.state == ''authorized''\" class=\"badge rounded-pill text-bg-primary\">\n                <i class=\"fa fa-fw fa-check\"/>\n                <span class=\"d-none d-md-inline\"> Authorized</span>\n            </span>\n            <span t-elif=\"invoice.payment_state in (''not_paid'', ''partial'') and tx_sudo.state == ''pending'' and tx_sudo.provider_code not in (''none'', ''custom'')\" class=\"badge rounded-pill text-bg-warning\">\n                <span class=\"d-none d-md-inline\"> Pending</span>\n            </span>\n            <span t-elif=\"invoice.payment_state in (''paid'', ''in_payment'') and tx_sudo.state == ''done''\" class=\"badge rounded-pill text-bg-success\">\n                <i class=\"fa fa-fw fa-check\"/>\n                <span class=\"d-none d-md-inline\"> Paid</span>\n            </span>\n        </xpath>\n    </data>"}', '<?xml version="1.0"?>
<data name="Payment on My Invoices" inherit_id="account.portal_my_invoices">
        <xpath expr="//t[@t-call=''portal.portal_table'']/thead/tr/th[last()]" position="before">
            <th/>
        </xpath>
        <xpath expr="//t[@t-foreach=''invoices'']/tr/td[last()]" position="before">
            <td class="text-center">
                <a t-if="invoice._has_to_be_paid()" t-att-href="invoice.get_portal_url(anchor=''portal_pay'')" title="Pay Now" aria-label="Pay now" class="btn btn-sm btn-primary" role="button">
                    <i class="fa fa-arrow-circle-right"/><span class="d-none d-md-inline"> Pay Now</span>
                </a>
            </td>
        </xpath>
        <xpath expr="//t[@name=''invoice_status_posted'']/span[1]" position="before">
            <t t-set="tx_sudo" t-value="invoice.get_portal_last_transaction()"/>
        </xpath>
        <xpath expr="//span[@name=''invoice_status_waiting_for_payment'']" position="before">
            <span t-elif="invoice.payment_state in (''not_paid'', ''partial'') and tx_sudo.state == ''authorized''" class="badge rounded-pill text-bg-primary">
                <i class="fa fa-fw fa-check"/>
                <span class="d-none d-md-inline"> Authorized</span>
            </span>
            <span t-elif="invoice.payment_state in (''not_paid'', ''partial'') and tx_sudo.state == ''pending'' and tx_sudo.provider_code not in (''none'', ''custom'')" class="badge rounded-pill text-bg-warning">
                <span class="d-none d-md-inline"> Pending</span>
            </span>
            <span t-elif="invoice.payment_state in (''paid'', ''in_payment'') and tx_sudo.state == ''done''" class="badge rounded-pill text-bg-success">
                <i class="fa fa-fw fa-check"/>
                <span class="d-none d-md-inline"> Paid</span>
            </span>
        </xpath>
    </data>

    ', false, true, '2026-05-10 01:12:04.370996', '2026-05-10 01:12:04.370996', false);
INSERT INTO public.ir_ui_view VALUES (840, 16, NULL, 1, 1, 'Invoice Payment', NULL, 'account_payment.portal_invoice_payment', 'qweb', 'account_payment/views/account_portal_templates.xml', 'primary', '{"en_US": "<t name=\"Invoice Payment\" t-name=\"account_payment.portal_invoice_payment\">\n        <div class=\"row\">\n            <div class=\"modal fade\" id=\"pay_with\" role=\"dialog\">\n                <div class=\"modal-dialog\">\n                    <div class=\"modal-content\">\n                        <div class=\"modal-header\">\n                            <h3 class=\"modal-title\">Pay with</h3>\n                            <button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"modal\" aria-label=\"Close\"/>\n                        </div>\n                        <div class=\"modal-body\">\n                            <div t-if=\"company_mismatch\">\n                                <t t-call=\"payment.company_mismatch_warning\"/>\n                            </div>\n                            <div t-elif=\"not payment_methods_sudo and not tokens_sudo\" class=\"alert alert-warning\">\n                                <strong>No suitable payment method could be found.</strong><br/>\n                                If you believe that it is an error, please contact the website\n                                administrator.\n                            </div>\n                            <t t-else=\"\" t-call=\"payment.form\"/>\n                        </div>\n                    </div>\n                </div>\n            </div>\n        </div>\n    </t>"}', '<?xml version="1.0"?>
<t name="Invoice Payment" t-name="account_payment.portal_invoice_payment">
        <div class="row">
            <div class="modal fade" id="pay_with" role="dialog">
                <div class="modal-dialog">
                    <div class="modal-content">
                        <div class="modal-header">
                            <h3 class="modal-title">Pay with</h3>
                            <button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close"/>
                        </div>
                        <div class="modal-body">
                            <div t-if="company_mismatch">
                                <t t-call="payment.company_mismatch_warning"/>
                            </div>
                            <div t-elif="not payment_methods_sudo and not tokens_sudo" class="alert alert-warning">
                                <strong>No suitable payment method could be found.</strong><br/>
                                If you believe that it is an error, please contact the website
                                administrator.
                            </div>
                            <t t-else="" t-call="payment.form"/>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    </t>

    ', false, true, '2026-05-10 01:12:04.370996', '2026-05-10 01:12:04.370996', false);
INSERT INTO public.ir_ui_view VALUES (841, 16, 776, 1, 1, 'Payment on My Invoices', NULL, 'account_payment.portal_invoice_page_inherit_payment', 'qweb', 'account_payment/views/account_portal_templates.xml', 'extension', '{"en_US": "<data name=\"Payment on My Invoices\" inherit_id=\"account.portal_invoice_page\">\n        <xpath expr=\"//t[@t-call=''portal.portal_record_sidebar'']//h2[1]\" position=\"after\">\n            <t t-set=\"pending_txs\" t-value=\"invoice.transaction_ids.filtered(lambda tx: tx.state in (''pending'', ''authorized'') and tx.provider_code not in (''none'', ''custom''))\"/>\n            <div class=\"d-grid\">\n                <div t-if=\"invoice.payment_state in (''paid'', ''in_payment'')\" class=\"position-sm-absolute position-lg-relative me-auto me-lg-0 top-0 end-0 rounded text-bg-success fs-6 fw-normal badge\">\n                    <i class=\"fa fa-fw fa-check-circle\"/> Paid\n                </div>\n                <div t-elif=\"pending_txs\" class=\"position-sm-absolute position-lg-relative me-auto me-lg-0 top-0 end-0 rounded text-bg-info fw-normal fs-6 badge\">\n                    <i class=\"fa fa-fw fa-check-circle\"/> Pending\n                </div>\n            </div>\n        </xpath>\n        <xpath expr=\"//t[@t-call=''portal.portal_record_sidebar'']//div[hasclass(''o_download_pdf'')]\" position=\"before\">\n            <a t-if=\"invoice._has_to_be_paid()\" href=\"#\" class=\"btn btn-primary d-block mb-2\" data-bs-toggle=\"modal\" data-bs-target=\"#pay_with\">\n                <i class=\"fa fa-fw fa-arrow-circle-right\"/> Pay Now\n            </a>\n        </xpath>\n        <xpath expr=\"//div[@id=''invoice_content'']//div[hasclass(''o_portal_html_view'')]\" position=\"before\">\n            <t t-set=\"tx\" t-value=\"invoice.get_portal_last_transaction()\"/>\n            <div t-if=\"invoice.get_portal_last_transaction() and invoice.amount_total and not success and not error and (invoice.payment_state != ''not_paid'' or tx.state in (''pending'', ''authorized''))\" class=\"o_account_payment_tx_status\" t-att-data-invoice-id=\"invoice.id\">\n                <t t-call=\"payment.transaction_status\"/>\n            </div>\n            <div t-if=\"invoice._has_to_be_paid()\" id=\"portal_pay\">\n                <t t-call=\"account_payment.portal_invoice_payment\"/>\n            </div>\n        </xpath>\n    </data>"}', '<?xml version="1.0"?>
<data name="Payment on My Invoices" inherit_id="account.portal_invoice_page">
        <xpath expr="//t[@t-call=''portal.portal_record_sidebar'']//h2[1]" position="after">
            <t t-set="pending_txs" t-value="invoice.transaction_ids.filtered(lambda tx: tx.state in (''pending'', ''authorized'') and tx.provider_code not in (''none'', ''custom''))"/>
            <div class="d-grid">
                <div t-if="invoice.payment_state in (''paid'', ''in_payment'')" class="position-sm-absolute position-lg-relative me-auto me-lg-0 top-0 end-0 rounded text-bg-success fs-6 fw-normal badge">
                    <i class="fa fa-fw fa-check-circle"/> Paid
                </div>
                <div t-elif="pending_txs" class="position-sm-absolute position-lg-relative me-auto me-lg-0 top-0 end-0 rounded text-bg-info fw-normal fs-6 badge">
                    <i class="fa fa-fw fa-check-circle"/> Pending
                </div>
            </div>
        </xpath>
        <xpath expr="//t[@t-call=''portal.portal_record_sidebar'']//div[hasclass(''o_download_pdf'')]" position="before">
            <a t-if="invoice._has_to_be_paid()" href="#" class="btn btn-primary d-block mb-2" data-bs-toggle="modal" data-bs-target="#pay_with">
                <i class="fa fa-fw fa-arrow-circle-right"/> Pay Now
            </a>
        </xpath>
        <xpath expr="//div[@id=''invoice_content'']//div[hasclass(''o_portal_html_view'')]" position="before">
            <t t-set="tx" t-value="invoice.get_portal_last_transaction()"/>
            <div t-if="invoice.get_portal_last_transaction() and invoice.amount_total and not success and not error and (invoice.payment_state != ''not_paid'' or tx.state in (''pending'', ''authorized''))" class="o_account_payment_tx_status" t-att-data-invoice-id="invoice.id">
                <t t-call="payment.transaction_status"/>
            </div>
            <div t-if="invoice._has_to_be_paid()" id="portal_pay">
                <t t-call="account_payment.portal_invoice_payment"/>
            </div>
        </xpath>
    </data>

    ', false, true, '2026-05-10 01:12:04.370996', '2026-05-10 01:12:04.370996', false);
INSERT INTO public.ir_ui_view VALUES (846, 16, 645, 1, 1, 'view.account.payment.form.inherit.payment', 'account.payment', NULL, 'form', 'account_payment/views/account_payment_views.xml', 'extension', '{"en_US": "<data><xpath expr=\"//header/button[@name=''action_draft'']\" position=\"after\">\n                <field name=\"amount_available_for_refund\" invisible=\"1\"/>\n                <button name=\"action_refund_wizard\" type=\"object\" string=\"Refund\" groups=\"account.group_account_invoice\" invisible=\"amount_available_for_refund &lt;= 0\" class=\"btn-secondary\"/>\n            </xpath>\n            <xpath expr=\"//div[@name=''button_box'']\" position=\"inside\">\n                <button name=\"action_view_refunds\" type=\"object\" class=\"oe_stat_button\" icon=\"fa-money\" invisible=\"refunds_count == 0\">\n                    <field name=\"refunds_count\" widget=\"statinfo\" string=\"Refunds\"/>\n                </button>\n            </xpath>\n            <xpath expr=\"//group[2]\" position=\"inside\">\n                <field name=\"source_payment_id\" invisible=\"not source_payment_id\"/>\n                <field name=\"payment_transaction_id\" groups=\"base.group_no_one\" invisible=\"not use_electronic_payment_method\"/>\n            </xpath>\n            <field name=\"payment_method_line_id\" position=\"after\">\n                <field name=\"payment_method_code\" invisible=\"1\"/>\n                <field name=\"suitable_payment_token_ids\" invisible=\"1\"/>\n                <field name=\"use_electronic_payment_method\" invisible=\"1\"/>\n                <field name=\"payment_token_id\" options=\"{''no_create'': True}\" invisible=\"not use_electronic_payment_method\" readonly=\"state != ''draft''\"/>\n            </field>\n        </data>"}', '<?xml version="1.0"?>
<data><xpath expr="//header/button[@name=''action_draft'']" position="after">
                <field name="amount_available_for_refund" invisible="1"/>
                <button name="action_refund_wizard" type="object" string="Refund" groups="account.group_account_invoice" invisible="amount_available_for_refund &lt;= 0" class="btn-secondary"/>
            </xpath>
            <xpath expr="//div[@name=''button_box'']" position="inside">
                <button name="action_view_refunds" type="object" class="oe_stat_button" icon="fa-money" invisible="refunds_count == 0">
                    <field name="refunds_count" widget="statinfo" string="Refunds"/>
                </button>
            </xpath>
            <xpath expr="//group[2]" position="inside">
                <field name="source_payment_id" invisible="not source_payment_id"/>
                <field name="payment_transaction_id" groups="base.group_no_one" invisible="not use_electronic_payment_method"/>
            </xpath>
            <field name="payment_method_line_id" position="after">
                <field name="payment_method_code" invisible="1"/>
                <field name="suitable_payment_token_ids" invisible="1"/>
                <field name="use_electronic_payment_method" invisible="1"/>
                <field name="payment_token_id" options="{''no_create'': True}" invisible="not use_electronic_payment_method" readonly="state != ''draft''"/>
            </field>
        </data>', false, true, '2026-05-10 01:12:04.370996', '2026-05-10 01:12:04.370996', false);
INSERT INTO public.ir_ui_view VALUES (842, 16, 777, 1, 1, 'Invoice error display: payment errors', NULL, 'account_payment.portal_invoice_error', 'qweb', 'account_payment/views/account_portal_templates.xml', 'extension', '{"en_US": "<data name=\"Invoice error display: payment errors\" inherit_id=\"account.portal_invoice_error\">\n        <xpath expr=\"//t[@name=''generic'']\" position=\"after\">\n            <t t-if=\"error == ''pay_invoice_invalid_doc''\">\n                There was an error processing your payment: invalid invoice.\n            </t>\n            <t t-elif=\"error == ''pay_invoice_invalid_token''\">\n                There was en error processing your payment: invalid credit card ID.\n            </t>\n            <t t-elif=\"error == ''pay_invoice_tx_fail''\">\n                There was an error processing your payment: transaction failed.<br/>\n                <t t-set=\"tx_sudo\" t-value=\"invoice.get_portal_last_transaction()\"/>\n                <t t-if=\"tx_sudo and tx_sudo.state_message\">\n                    <t t-out=\"tx_sudo.state_message\"/>\n                </t>\n            </t>\n            <t t-elif=\"error == ''pay_invoice_tx_token''\">\n                There was an error processing your payment: issue with credit card ID validation.\n            </t>\n        </xpath>\n    </data>"}', '<?xml version="1.0"?>
<data name="Invoice error display: payment errors" inherit_id="account.portal_invoice_error">
        <xpath expr="//t[@name=''generic'']" position="after">
            <t t-if="error == ''pay_invoice_invalid_doc''">
                There was an error processing your payment: invalid invoice.
            </t>
            <t t-elif="error == ''pay_invoice_invalid_token''">
                There was en error processing your payment: invalid credit card ID.
            </t>
            <t t-elif="error == ''pay_invoice_tx_fail''">
                There was an error processing your payment: transaction failed.<br/>
                <t t-set="tx_sudo" t-value="invoice.get_portal_last_transaction()"/>
                <t t-if="tx_sudo and tx_sudo.state_message">
                    <t t-out="tx_sudo.state_message"/>
                </t>
            </t>
            <t t-elif="error == ''pay_invoice_tx_token''">
                There was an error processing your payment: issue with credit card ID validation.
            </t>
        </xpath>
    </data>

    ', false, true, '2026-05-10 01:12:04.370996', '2026-05-10 01:12:04.370996', false);
INSERT INTO public.ir_ui_view VALUES (843, 16, 778, 1, 1, 'Invoice success display: payment success', NULL, 'account_payment.portal_invoice_success', 'qweb', 'account_payment/views/account_portal_templates.xml', 'extension', '{"en_US": "<data name=\"Invoice success display: payment success\" inherit_id=\"account.portal_invoice_success\">\n        <xpath expr=\"//a[hasclass(''close'')]\" position=\"after\">\n            <t t-if=\"success == ''pay_invoice''\">\n                <t t-set=\"tx_sudo\" t-value=\"invoice.get_portal_last_transaction()\"/>\n                <span t-if=\"tx_sudo.provider_id.sudo().done_msg\" t-out=\"tx_sudo.provider_id.sudo().done_msg\"/>\n                <div t-if=\"tx_sudo.provider_id.sudo().pending_msg and tx_sudo.provider_code == ''custom'' and invoice.ref\">\n                    <b>Communication: </b><span t-out=\"invoice.ref\"/>\n                </div>\n            </t>\n            <t t-if=\"success == ''pay_invoice'' and invoice.payment_state in (''paid'', ''in_payment'')\">\n                Done, your online payment has been successfully processed. Thank you for your order.\n            </t>\n        </xpath>\n    </data>"}', '<?xml version="1.0"?>
<data name="Invoice success display: payment success" inherit_id="account.portal_invoice_success">
        <xpath expr="//a[hasclass(''close'')]" position="after">
            <t t-if="success == ''pay_invoice''">
                <t t-set="tx_sudo" t-value="invoice.get_portal_last_transaction()"/>
                <span t-if="tx_sudo.provider_id.sudo().done_msg" t-out="tx_sudo.provider_id.sudo().done_msg"/>
                <div t-if="tx_sudo.provider_id.sudo().pending_msg and tx_sudo.provider_code == ''custom'' and invoice.ref">
                    <b>Communication: </b><span t-out="invoice.ref"/>
                </div>
            </t>
            <t t-if="success == ''pay_invoice'' and invoice.payment_state in (''paid'', ''in_payment'')">
                Done, your online payment has been successfully processed. Thank you for your order.
            </t>
        </xpath>
    </data>
', false, true, '2026-05-10 01:12:04.370996', '2026-05-10 01:12:04.370996', false);
INSERT INTO public.ir_ui_view VALUES (844, 16, 676, 1, 1, 'account.move.view.form.inherit.payment', 'account.move', NULL, 'form', 'account_payment/views/account_move_views.xml', 'extension', '{"en_US": "<data><!--\n            The user must capture/void the authorized transactions before registering a new payment.\n            -->\n            <xpath expr=\"//button[@id=''account_invoice_payment_btn'']\" position=\"attributes\">\n                <attribute name=\"invisible\">state != ''posted'' or payment_state not in (''partial'', ''not_paid'') or move_type not in (''out_invoice'', ''out_refund'', ''in_invoice'', ''in_refund'', ''out_receipt'', ''in_receipt'') or authorized_transaction_ids</attribute>\n            </xpath>\n            <xpath expr=\"//button[@id=''account_invoice_payment_btn'']\" position=\"after\">\n                <field name=\"authorized_transaction_ids\" invisible=\"1\"/>\n                <button name=\"payment_action_capture\" type=\"object\" groups=\"account.group_account_invoice\" string=\"Capture Transaction\" class=\"oe_highlight\" data-hotkey=\"shift+g\" invisible=\"move_type not in (''out_invoice'', ''out_refund'', ''in_invoice'', ''in_refund'') or state != ''posted'' or not authorized_transaction_ids\"/>\n                <button name=\"payment_action_void\" type=\"object\" groups=\"account.group_account_invoice\" string=\"Void Transaction\" data-hotkey=\"shift+v\" confirm=\"Are you sure you want to void the authorized transaction? This action can''t be undone.\" invisible=\"move_type not in (''out_invoice'', ''out_refund'', ''in_invoice'', ''in_refund'') or state != ''posted'' or not authorized_transaction_ids\"/>\n            </xpath>\n            <xpath expr=\"//div[@name=''button_box'']\" position=\"inside\">\n                <field name=\"transaction_ids\" invisible=\"1\"/>\n                <button name=\"action_view_payment_transactions\" type=\"object\" groups=\"account.group_account_invoice\" class=\"oe_stat_button\" icon=\"fa-money\" invisible=\"not transaction_ids\">\n                        <div class=\"o_stat_info\">\n                            <span class=\"o_stat_text\">Payment Transaction</span>\n                        </div>\n                </button>\n            </xpath>\n        </data>"}', '<?xml version="1.0"?>
<data><!--
            The user must capture/void the authorized transactions before registering a new payment.
            -->
            <xpath expr="//button[@id=''account_invoice_payment_btn'']" position="attributes">
                <attribute name="invisible">state != ''posted'' or payment_state not in (''partial'', ''not_paid'') or move_type not in (''out_invoice'', ''out_refund'', ''in_invoice'', ''in_refund'', ''out_receipt'', ''in_receipt'') or authorized_transaction_ids</attribute>
            </xpath>
            <xpath expr="//button[@id=''account_invoice_payment_btn'']" position="after">
                <field name="authorized_transaction_ids" invisible="1"/>
                <button name="payment_action_capture" type="object" groups="account.group_account_invoice" string="Capture Transaction" class="oe_highlight" data-hotkey="shift+g" invisible="move_type not in (''out_invoice'', ''out_refund'', ''in_invoice'', ''in_refund'') or state != ''posted'' or not authorized_transaction_ids"/>
                <button name="payment_action_void" type="object" groups="account.group_account_invoice" string="Void Transaction" data-hotkey="shift+v" confirm="Are you sure you want to void the authorized transaction? This action can''t be undone." invisible="move_type not in (''out_invoice'', ''out_refund'', ''in_invoice'', ''in_refund'') or state != ''posted'' or not authorized_transaction_ids"/>
            </xpath>
            <xpath expr="//div[@name=''button_box'']" position="inside">
                <field name="transaction_ids" invisible="1"/>
                <button name="action_view_payment_transactions" type="object" groups="account.group_account_invoice" class="oe_stat_button" icon="fa-money" invisible="not transaction_ids">
                        <div class="o_stat_info">
                            <span class="o_stat_text">Payment Transaction</span>
                        </div>
                </button>
            </xpath>
        </data>', false, true, '2026-05-10 01:12:04.370996', '2026-05-10 01:12:04.370996', false);
INSERT INTO public.ir_ui_view VALUES (845, 16, 691, 1, 1, 'account.journal.form.inherit.payment', 'account.journal', NULL, 'form', 'account_payment/views/account_journal_views.xml', 'extension', '{"en_US": "<data><xpath expr=\"//field[@name=''inbound_payment_method_line_ids'']//field[@name=''payment_account_id'']\" position=\"after\">\n                <field name=\"code\" column_invisible=\"True\"/>\n                <field name=\"payment_provider_id\" options=\"{''no_open'': True, ''no_create'': True}\" optional=\"hide\" domain=\"[(''code'', ''='', code)]\" readonly=\"payment_provider_state in (''enabled'', ''test'')\"/>\n                <field name=\"payment_provider_state\" column_invisible=\"True\"/>\n                <button name=\"action_open_provider_form\" type=\"object\" string=\"SETUP\" class=\"float-end btn-secondary\" invisible=\"not payment_provider_id\" groups=\"base.group_system\"/>\n            </xpath>\n            <xpath expr=\"//field[@name=''inbound_payment_method_line_ids'']/tree\" position=\"attributes\">\n                <attribute name=\"decoration-muted\">payment_provider_state == ''disabled''</attribute>\n            </xpath>\n        </data>"}', '<?xml version="1.0"?>
<data><xpath expr="//field[@name=''inbound_payment_method_line_ids'']//field[@name=''payment_account_id'']" position="after">
                <field name="code" column_invisible="True"/>
                <field name="payment_provider_id" options="{''no_open'': True, ''no_create'': True}" optional="hide" domain="[(''code'', ''='', code)]" readonly="payment_provider_state in (''enabled'', ''test'')"/>
                <field name="payment_provider_state" column_invisible="True"/>
                <button name="action_open_provider_form" type="object" string="SETUP" class="float-end btn-secondary" invisible="not payment_provider_id" groups="base.group_system"/>
            </xpath>
            <xpath expr="//field[@name=''inbound_payment_method_line_ids'']/tree" position="attributes">
                <attribute name="decoration-muted">payment_provider_state == ''disabled''</attribute>
            </xpath>
        </data>', false, true, '2026-05-10 01:12:04.370996', '2026-05-10 01:12:04.370996', false);
INSERT INTO public.ir_ui_view VALUES (847, 16, 620, 1, 1, 'payment.provider.form', 'payment.provider', NULL, 'form', 'account_payment/views/payment_provider_views.xml', 'extension', '{"en_US": "<data><group name=\"payment_followup\" position=\"attributes\">\n                <attribute name=\"invisible\">\n                    0\n                </attribute>\n            </group>\n            <group name=\"payment_followup\" position=\"inside\">\n                <field name=\"journal_id\" context=\"{''default_type'': ''bank''}\" required=\"state != ''disabled'' and code not in [''none'', ''custom'']\"/>\n            </group>\n        </data>"}', '<?xml version="1.0"?>
<data><group name="payment_followup" position="attributes">
                <attribute name="invisible">
                    0
                </attribute>
            </group>
            <group name="payment_followup" position="inside">
                <field name="journal_id" context="{''default_type'': ''bank''}" required="state != ''disabled'' and code not in [''none'', ''custom'']"/>
            </group>
        </data>', false, true, '2026-05-10 01:12:04.370996', '2026-05-10 01:12:04.370996', false);
INSERT INTO public.ir_ui_view VALUES (848, 16, 628, 1, 1, 'payment.transaction.form', 'payment.transaction', NULL, 'form', 'account_payment/views/payment_transaction_views.xml', 'extension', '{"en_US": "<data><button name=\"action_view_refunds\" position=\"before\">\n                <button name=\"action_view_invoices\" type=\"object\" class=\"oe_stat_button\" icon=\"fa-money\" invisible=\"invoices_count == 0\">\n                    <field name=\"invoices_count\" widget=\"statinfo\" string=\"Invoice(s)\"/>\n                </button>\n            </button>\n            <field name=\"reference\" position=\"after\">\n                <field name=\"payment_id\"/>\n            </field>\n        </data>"}', '<?xml version="1.0"?>
<data><button name="action_view_refunds" position="before">
                <button name="action_view_invoices" type="object" class="oe_stat_button" icon="fa-money" invisible="invoices_count == 0">
                    <field name="invoices_count" widget="statinfo" string="Invoice(s)"/>
                </button>
            </button>
            <field name="reference" position="after">
                <field name="payment_id"/>
            </field>
        </data>', false, true, '2026-05-10 01:12:04.370996', '2026-05-10 01:12:04.370996', false);
INSERT INTO public.ir_ui_view VALUES (849, 16, 651, 1, 1, 'account.payment.register.form.inherit.payment', 'account.payment.register', NULL, 'form', 'account_payment/wizards/account_payment_register_views.xml', 'extension', '{"en_US": "<field name=\"payment_method_line_id\" position=\"after\">\n                <field name=\"payment_method_code\" invisible=\"1\"/>\n                <field name=\"suitable_payment_token_ids\" invisible=\"1\"/>\n                <field name=\"use_electronic_payment_method\" invisible=\"1\"/>\n                <field name=\"payment_token_id\" options=\"{''no_create'': True}\" invisible=\"not use_electronic_payment_method or not can_edit_wizard or (can_group_payments and not group_payment)\"/>\n            </field>"}', '<?xml version="1.0"?>
<field name="payment_method_line_id" position="after">
                <field name="payment_method_code" invisible="1"/>
                <field name="suitable_payment_token_ids" invisible="1"/>
                <field name="use_electronic_payment_method" invisible="1"/>
                <field name="payment_token_id" options="{''no_create'': True}" invisible="not use_electronic_payment_method or not can_edit_wizard or (can_group_payments and not group_payment)"/>
            </field>
        ', false, true, '2026-05-10 01:12:04.370996', '2026-05-10 01:12:04.370996', false);
INSERT INTO public.ir_ui_view VALUES (850, 16, NULL, 1, 1, 'payment.refund.wizard.form', 'payment.refund.wizard', NULL, 'form', 'account_payment/wizards/payment_refund_wizard_views.xml', 'primary', '{"en_US": "<form string=\"Refund\">\n                <field name=\"has_pending_refund\" invisible=\"1\"/>\n                <div class=\"alert alert-warning\" id=\"alert_draft_refund_tx\" role=\"alert\" invisible=\"not has_pending_refund\">\n                    <p>\n                        <strong>Warning!</strong> There is a refund pending for this payment.\n                        Wait a moment for it to be processed. If the refund is still pending in a\n                        few minutes, please check your payment provider configuration.\n                    </p>\n                </div>\n                <group>\n                    <group>\n                        <field name=\"payment_id\" invisible=\"1\"/>\n                        <field name=\"transaction_id\" invisible=\"1\"/>\n                        <field name=\"currency_id\" invisible=\"1\"/>\n                        <field name=\"support_refund\" invisible=\"1\"/>\n                        <field name=\"payment_amount\"/>\n                        <field name=\"refunded_amount\" invisible=\"refunded_amount &lt;= 0\"/>\n                        <field name=\"amount_available_for_refund\"/>\n                        <field name=\"amount_to_refund\" readonly=\"support_refund == ''full_only''\"/>\n                    </group>\n                </group>\n                <footer>\n                    <button string=\"Refund\" type=\"object\" name=\"action_refund\" class=\"btn-primary\"/>\n                    <button string=\"Close\" special=\"cancel\" class=\"btn-secondary\"/>\n                </footer>\n            </form>"}', '<?xml version="1.0"?>
<form string="Refund">
                <field name="has_pending_refund" invisible="1"/>
                <div class="alert alert-warning" id="alert_draft_refund_tx" role="alert" invisible="not has_pending_refund">
                    <p>
                        <strong>Warning!</strong> There is a refund pending for this payment.
                        Wait a moment for it to be processed. If the refund is still pending in a
                        few minutes, please check your payment provider configuration.
                    </p>
                </div>
                <group>
                    <group>
                        <field name="payment_id" invisible="1"/>
                        <field name="transaction_id" invisible="1"/>
                        <field name="currency_id" invisible="1"/>
                        <field name="support_refund" invisible="1"/>
                        <field name="payment_amount"/>
                        <field name="refunded_amount" invisible="refunded_amount &lt;= 0"/>
                        <field name="amount_available_for_refund"/>
                        <field name="amount_to_refund" readonly="support_refund == ''full_only''"/>
                    </group>
                </group>
                <footer>
                    <button string="Refund" type="object" name="action_refund" class="btn-primary"/>
                    <button string="Close" special="cancel" class="btn-secondary"/>
                </footer>
            </form>
        ', false, true, '2026-05-10 01:12:04.370996', '2026-05-10 01:12:04.370996', false);
INSERT INTO public.ir_ui_view VALUES (851, 16, 765, 1, 1, 'res.config.settings.view.form.inherit.account', 'res.config.settings', NULL, 'form', 'account_payment/wizards/res_config_settings_views.xml', 'extension', '{"en_US": "<field name=\"module_account_payment\" position=\"replace\">\n                <field name=\"pay_invoices_online\" string=\"Invoice Online Payment\"/>\n            </field>"}', '<?xml version="1.0"?>
