INSERT INTO public.ir_ui_view VALUES (852, 16, 721, 1, 1, 'account.payment.term.form', 'account.payment.term', NULL, 'form', 'account_payment_term/views/account_payment_term_views.xml', 'extension', '{"en_US": "<xpath expr=\"//field[@name=''line_ids'']/tree[''delay_type'']\" position=\"inside\">\n                    <field name=\"display_days_next_month\" column_invisible=\"1\"/>\n                    <field name=\"days_next_month\" width=\"30px\" nolabel=\"1\" invisible=\"not display_days_next_month\"/>\n                </xpath>"}', '<?xml version="1.0"?>
