INSERT INTO public.ir_ui_view VALUES (853, 100, 765, 1, 1, 'res.config.settings.view.form.inherit.snailmail.account', 'res.config.settings', NULL, 'form', 'snailmail_account/views/res_config_settings_views.xml', 'extension', '{"en_US": "<data><xpath expr=\"//div[@id=''send_default'']\" position=\"inside\">\n                <div invisible=\"not module_snailmail_account\">\n                    <field name=\"invoice_is_snailmail\"/>\n                    <label for=\"invoice_is_snailmail\"/>\n                    <span class=\"fa fa-lg fa-building-o\" title=\"Values set here are company-specific.\"/>\n                </div>\n            </xpath>\n\n            <setting id=\"send_invoices_followups\" position=\"inside\">\n                <div class=\"mt16\" invisible=\"not module_snailmail_account\">\n                    <div>\n                        <field name=\"snailmail_color\"/>\n                        <label for=\"snailmail_color\"/>\n                        <span class=\"fa fa-lg fa-building-o\" title=\"Values set here are company-specific.\"/>\n                    </div>\n                    <div>\n                        <field name=\"snailmail_duplex\"/>\n                        <label for=\"snailmail_duplex\"/>\n                        <span class=\"fa fa-lg fa-building-o\" title=\"Values set here are company-specific.\"/>\n                    </div>\n                    <div>\n                        <field name=\"snailmail_cover\"/>\n                        <label for=\"snailmail_cover\"/>\n                        <span class=\"fa fa-lg fa-building-o\" title=\"Values set here are company-specific.\"/>\n                    </div>\n                </div>\n                <widget name=\"iap_buy_more_credits\" service_name=\"snailmail\"/>\n            </setting>\n        </data>"}', '<?xml version="1.0"?>
<data><xpath expr="//div[@id=''send_default'']" position="inside">
                <div invisible="not module_snailmail_account">
                    <field name="invoice_is_snailmail"/>
                    <label for="invoice_is_snailmail"/>
                    <span class="fa fa-lg fa-building-o" title="Values set here are company-specific."/>
                </div>
            </xpath>

            <setting id="send_invoices_followups" position="inside">
                <div class="mt16" invisible="not module_snailmail_account">
                    <div>
                        <field name="snailmail_color"/>
                        <label for="snailmail_color"/>
                        <span class="fa fa-lg fa-building-o" title="Values set here are company-specific."/>
                    </div>
                    <div>
                        <field name="snailmail_duplex"/>
                        <label for="snailmail_duplex"/>
                        <span class="fa fa-lg fa-building-o" title="Values set here are company-specific."/>
                    </div>
                    <div>
                        <field name="snailmail_cover"/>
                        <label for="snailmail_cover"/>
                        <span class="fa fa-lg fa-building-o" title="Values set here are company-specific."/>
                    </div>
                </div>
                <widget name="iap_buy_more_credits" service_name="snailmail"/>
            </setting>
        </data>', false, true, '2026-05-10 01:12:04.848801', '2026-05-10 01:12:04.848801', false);
INSERT INTO public.ir_ui_view VALUES (854, 16, 786, 1, 1, 'account.move.send.form.inherit.snailmail', 'account.move.send', NULL, 'form', 'snailmail_account/wizard/account_move_send_views.xml', 'extension', '{"en_US": "<data><xpath expr=\"//div[@name=''standard_options'']\" position=\"inside\">\n                <field name=\"enable_send_by_post\" invisible=\"1\"/>\n                <field name=\"send_by_post_readonly\" invisible=\"1\"/>\n\n                <div name=\"option_send_by_post\" invisible=\"not enable_send_by_post\">\n                    <field name=\"checkbox_send_by_post\" readonly=\"send_by_post_readonly\"/>\n                    <b><label for=\"checkbox_send_by_post\" class=\"mr4\"/></b>\n                    <i class=\"fa fa-question-circle\" role=\"img\" aria-label=\"Warning\" title=\"The address is unknown on the partner\" invisible=\"not send_by_post_readonly\"/>\n\n                    <span invisible=\"send_by_post_cost in (0, 1) or not checkbox_send_by_post\">\n                        <b>(\n                            <field name=\"send_by_post_cost\" options=\"{''digits'':[0,0]}\" class=\"mr4\"/>\n                            <label for=\"send_by_post_cost\"/>\n                        )</b>\n                    </span>\n                </div>\n            </xpath>\n            <xpath expr=\"//div[@name=''warnings'']\" position=\"inside\">\n                <div class=\"alert alert-warning\" role=\"alert\" invisible=\"not send_by_post_warning_message\">\n                    <field name=\"send_by_post_warning_message\"/>\n                </div>\n            </xpath>\n        </data>"}', '<?xml version="1.0"?>
<data><xpath expr="//div[@name=''standard_options'']" position="inside">
                <field name="enable_send_by_post" invisible="1"/>
                <field name="send_by_post_readonly" invisible="1"/>

                <div name="option_send_by_post" invisible="not enable_send_by_post">
                    <field name="checkbox_send_by_post" readonly="send_by_post_readonly"/>
                    <b><label for="checkbox_send_by_post" class="mr4"/></b>
                    <i class="fa fa-question-circle" role="img" aria-label="Warning" title="The address is unknown on the partner" invisible="not send_by_post_readonly"/>

                    <span invisible="send_by_post_cost in (0, 1) or not checkbox_send_by_post">
                        <b>(
                            <field name="send_by_post_cost" options="{''digits'':[0,0]}" class="mr4"/>
                            <label for="send_by_post_cost"/>
                        )</b>
                    </span>
                </div>
            </xpath>
            <xpath expr="//div[@name=''warnings'']" position="inside">
                <div class="alert alert-warning" role="alert" invisible="not send_by_post_warning_message">
                    <field name="send_by_post_warning_message"/>
                </div>
            </xpath>
        </data>', false, true, '2026-05-10 01:12:04.848801', '2026-05-10 01:12:04.848801', false);
INSERT INTO public.ir_ui_view VALUES (860, 16, NULL, 1, 1, 'report_saleorder_pro_forma', NULL, 'sale.report_saleorder_pro_forma', 'qweb', 'sale/report/ir_actions_report_templates.xml', 'primary', '{"en_US": "<t t-name=\"sale.report_saleorder_pro_forma\">\n    <t t-call=\"web.html_container\">\n        <t t-set=\"is_pro_forma\" t-value=\"True\"/>\n        <t t-set=\"docs\" t-value=\"docs.with_context(proforma=True)\"/>\n        <t t-foreach=\"docs\" t-as=\"doc\">\n            <t t-call=\"sale.report_saleorder_document\" t-lang=\"doc.partner_id.lang\"/>\n        </t>\n    </t>\n</t>"}', '<?xml version="1.0"?>
<t t-name="sale.report_saleorder_pro_forma">
    <t t-call="web.html_container">
        <t t-set="is_pro_forma" t-value="True"/>
        <t t-set="docs" t-value="docs.with_context(proforma=True)"/>
        <t t-foreach="docs" t-as="doc">
            <t t-call="sale.report_saleorder_document" t-lang="doc.partner_id.lang"/>
        </t>
    </t>
</t>

 ', false, true, '2026-05-10 01:12:05.269262', '2026-05-10 01:12:05.269262', false);
