INSERT INTO public.ir_ui_view VALUES (862, 16, NULL, 1, 1, 'sale.report.pivot', 'sale.report', NULL, 'pivot', 'sale/report/sale_report_views.xml', 'primary', '{"en_US": "<pivot string=\"Sales Analysis\" sample=\"1\">\n                 <field name=\"team_id\" type=\"col\"/>\n                 <field name=\"date\" interval=\"month\" type=\"row\"/>\n                 <field name=\"price_subtotal\" type=\"measure\"/>\n             </pivot>"}', '<?xml version="1.0"?>
