             </pivot>
         ', false, true, '2026-05-10 01:12:05.269262', '2026-05-10 01:12:05.269262', false);
INSERT INTO public.ir_ui_view VALUES (863, 16, NULL, 1, 1, 'sale.report.graph', 'sale.report', NULL, 'graph', 'sale/report/sale_report_views.xml', 'primary', '{"en_US": "<graph string=\"Sales Analysis\" type=\"line\" sample=\"1\">\n                 <field name=\"date\" interval=\"day\"/>\n                 <field name=\"price_subtotal\" type=\"measure\"/>\n             </graph>"}', '<?xml version="1.0"?>
<graph string="Sales Analysis" type="line" sample="1">
