INSERT INTO public.ir_ui_view VALUES (866, 16, NULL, 1, 1, 'sale.report.view.tree', 'sale.report', NULL, 'tree', 'sale/report/sale_report_views.xml', 'primary', '{"en_US": "<tree string=\"Sales Analysis\">\n                <field name=\"date\" widget=\"date\"/>\n                <field name=\"order_reference\" optional=\"show\"/>\n                <field name=\"partner_id\" optional=\"hide\"/>\n                <field name=\"product_id\" string=\"Product\" optional=\"show\"/>\n                <field name=\"user_id\" optional=\"show\" widget=\"many2one_avatar_user\"/>\n                <field name=\"team_id\" optional=\"show\"/>\n                <field name=\"company_id\" optional=\"show\" groups=\"base.group_multi_company\"/>\n                <field name=\"price_subtotal\" optional=\"hide\" sum=\"Sum of Untaxed Total\"/>\n                <field name=\"price_total\" optional=\"show\" sum=\"Sum of Total\"/>\n                <field name=\"state\" optional=\"hide\"/>\n                <field name=\"invoice_status\" optional=\"hide\"/>\n                <field name=\"currency_id\" column_invisible=\"True\"/>\n            </tree>"}', '<?xml version="1.0"?>
<tree string="Sales Analysis">
                <field name="date" widget="date"/>
                <field name="order_reference" optional="show"/>
                <field name="partner_id" optional="hide"/>
                <field name="product_id" string="Product" optional="show"/>
                <field name="user_id" optional="show" widget="many2one_avatar_user"/>
                <field name="team_id" optional="show"/>
                <field name="company_id" optional="show" groups="base.group_multi_company"/>
                <field name="price_subtotal" optional="hide" sum="Sum of Untaxed Total"/>
                <field name="price_total" optional="show" sum="Sum of Total"/>
                <field name="state" optional="hide"/>
                <field name="invoice_status" optional="hide"/>
                <field name="currency_id" column_invisible="True"/>
            </tree>
        ', false, true, '2026-05-10 01:12:05.269262', '2026-05-10 01:12:05.269262', false);
INSERT INTO public.ir_ui_view VALUES (867, 16, NULL, 1, 1, 'sale.report.search', 'sale.report', NULL, 'search', 'sale/report/sale_report_views.xml', 'primary', '{"en_US": "<search string=\"Sales Analysis\">\n                <field name=\"date\"/>\n                <filter string=\"Date\" name=\"year\" invisible=\"1\" date=\"date\" default_period=\"this_year\"/>\n                <filter string=\"Quotations\" name=\"Quotations\" domain=\"[(''state'',''in'', (''draft'', ''sent''))]\"/>\n                <filter string=\"Sales Orders\" name=\"Sales\" domain=\"[(''state'',''not in'',(''draft'', ''cancel'', ''sent''))]\"/>\n                <separator/>\n                <filter name=\"filter_date\" date=\"date\" default_period=\"this_month\"/>\n                <filter name=\"filter_order_date\" invisible=\"1\" string=\"Order Date: Last 365 Days\" domain=\"[(''date'', ''&gt;='', (datetime.datetime.combine(context_today() + relativedelta(days=-365), datetime.time(0,0,0))).strftime(''%Y-%m-%d %H:%M:%S''))]\"/>\n                <separator/>\n                <field name=\"user_id\"/>\n                <field name=\"team_id\"/>\n                <field name=\"product_id\"/>\n                <field name=\"product_tmpl_id\"/>\n                <field name=\"categ_id\"/>\n                <filter name=\"to_invoice\" string=\"To Invoice\" domain=\"[(''invoice_status'', ''='', ''to invoice'')]\"/>\n                <filter name=\"fully_invoiced\" string=\"Fully Invoiced\" domain=\"[(''invoice_status'', ''='', ''invoiced'')]\"/>\n                <field name=\"partner_id\"/>\n                <field name=\"country_id\"/>\n                <field name=\"industry_id\"/>\n                <group expand=\"0\" string=\"Extended Filters\">\n                    <field name=\"categ_id\" filter_domain=\"[(''categ_id'', ''child_of'', self)]\"/>\n                    <field name=\"company_id\" groups=\"base.group_multi_company\"/>\n                </group>\n                <group expand=\"1\" string=\"Group By\">\n                    <filter string=\"Salesperson\" name=\"User\" context=\"{''group_by'':''user_id''}\"/>\n                    <filter string=\"Sales Team\" name=\"sales_channel\" context=\"{''group_by'':''team_id''}\"/>\n                    <filter string=\"Customer\" name=\"Customer\" context=\"{''group_by'':''partner_id''}\"/>\n                    <filter string=\"Customer Country\" name=\"country_id\" context=\"{''group_by'':''country_id''}\"/>\n                    <filter string=\"Customer Industry\" name=\"industry_id\" context=\"{''group_by'':''industry_id''}\"/>\n                    <filter string=\"Product\" name=\"product_tmpl_id\" context=\"{''group_by'':''product_tmpl_id''}\"/>\n                    <filter string=\"Product Variant\" name=\"product_id\" context=\"{''group_by'':''product_id''}\" groups=\"product.group_product_variant\"/>\n                    <filter string=\"Product Category\" name=\"Category\" context=\"{''group_by'':''categ_id''}\"/>\n                    <filter string=\"Status\" name=\"status\" context=\"{''group_by'':''state''}\"/>\n                    <filter string=\"Company\" name=\"company\" groups=\"base.group_multi_company\" context=\"{''group_by'':''company_id''}\"/>\n                    <separator/>\n                    <filter string=\"Order Date\" name=\"date\" context=\"{''group_by'':''date''}\" invisible=\"context.get(''sale_report_view_hide_date'')\"/>\n                    <filter string=\"Order Date\" name=\"group_by_date_day\" context=\"{''group_by'':''date:day''}\" invisible=\"not context.get(''sale_report_view_hide_date'')\"/>\n                </group>\n            </search>"}', '<?xml version="1.0"?>
<search string="Sales Analysis">
                <field name="date"/>
                <filter string="Date" name="year" invisible="1" date="date" default_period="this_year"/>
                <filter string="Quotations" name="Quotations" domain="[(''state'',''in'', (''draft'', ''sent''))]"/>
                <filter string="Sales Orders" name="Sales" domain="[(''state'',''not in'',(''draft'', ''cancel'', ''sent''))]"/>
                <separator/>
                <filter name="filter_date" date="date" default_period="this_month"/>
                <filter name="filter_order_date" invisible="1" string="Order Date: Last 365 Days" domain="[(''date'', ''&gt;='', (datetime.datetime.combine(context_today() + relativedelta(days=-365), datetime.time(0,0,0))).strftime(''%Y-%m-%d %H:%M:%S''))]"/>
                <separator/>
                <field name="user_id"/>
                <field name="team_id"/>
                <field name="product_id"/>
                <field name="product_tmpl_id"/>
                <field name="categ_id"/>
                <filter name="to_invoice" string="To Invoice" domain="[(''invoice_status'', ''='', ''to invoice'')]"/>
                <filter name="fully_invoiced" string="Fully Invoiced" domain="[(''invoice_status'', ''='', ''invoiced'')]"/>
                <field name="partner_id"/>
                <field name="country_id"/>
                <field name="industry_id"/>
                <group expand="0" string="Extended Filters">
                    <field name="categ_id" filter_domain="[(''categ_id'', ''child_of'', self)]"/>
                    <field name="company_id" groups="base.group_multi_company"/>
                </group>
                <group expand="1" string="Group By">
                    <filter string="Salesperson" name="User" context="{''group_by'':''user_id''}"/>
                    <filter string="Sales Team" name="sales_channel" context="{''group_by'':''team_id''}"/>
                    <filter string="Customer" name="Customer" context="{''group_by'':''partner_id''}"/>
                    <filter string="Customer Country" name="country_id" context="{''group_by'':''country_id''}"/>
                    <filter string="Customer Industry" name="industry_id" context="{''group_by'':''industry_id''}"/>
                    <filter string="Product" name="product_tmpl_id" context="{''group_by'':''product_tmpl_id''}"/>
                    <filter string="Product Variant" name="product_id" context="{''group_by'':''product_id''}" groups="product.group_product_variant"/>
                    <filter string="Product Category" name="Category" context="{''group_by'':''categ_id''}"/>
                    <filter string="Status" name="status" context="{''group_by'':''state''}"/>
                    <filter string="Company" name="company" groups="base.group_multi_company" context="{''group_by'':''company_id''}"/>
                    <separator/>
                    <filter string="Order Date" name="date" context="{''group_by'':''date''}" invisible="context.get(''sale_report_view_hide_date'')"/>
                    <filter string="Order Date" name="group_by_date_day" context="{''group_by'':''date:day''}" invisible="not context.get(''sale_report_view_hide_date'')"/>
                </group>
            </search>
        ', false, true, '2026-05-10 01:12:05.269262', '2026-05-10 01:12:05.269262', false);
INSERT INTO public.ir_ui_view VALUES (897, 16, 479, 1, 1, 'product.document.search.sale', 'product.document', NULL, 'search', 'sale/views/product_document_views.xml', 'extension', '{"en_US": "<search position=\"inside\">\n                <separator/>\n                <filter name=\"quotation\" string=\"Quotation\" domain=\"[(''attached_on'', ''='', ''quotation'')]\"/>\n                <filter name=\"sale_order\" string=\"Sales Order\" domain=\"[(''attached_on'', ''='', ''sale_order'')]\"/>\n            </search>"}', '<?xml version="1.0"?>
<search position="inside">
                <separator/>
                <filter name="quotation" string="Quotation" domain="[(''attached_on'', ''='', ''quotation'')]"/>
                <filter name="sale_order" string="Sales Order" domain="[(''attached_on'', ''='', ''sale_order'')]"/>
            </search>
        ', false, true, '2026-05-10 01:12:05.269262', '2026-05-10 01:12:05.269262', false);
INSERT INTO public.ir_ui_view VALUES (868, 16, NULL, 1, 1, 'sale.mass.cancel.orders.form', 'sale.mass.cancel.orders', NULL, 'form', 'sale/wizard/mass_cancel_orders_views.xml', 'primary', '{"en_US": "<form string=\"Cancel quotations\">\n                <field name=\"sale_order_ids\" invisible=\"1\"/>\n                <field name=\"sale_orders_count\" invisible=\"1\"/>\n                <field name=\"has_confirmed_order\" invisible=\"1\"/>\n                <div invisible=\"not has_confirmed_order\">\n                    <p class=\"alert alert-warning fw-bold\" role=\"alert\">\n                        Some confirmed sale orders are selected. Their related documents might be\n                        affected by the cancellation.\n                    </p>\n                </div>\n                <div invisible=\"sale_orders_count &gt; 1\">\n                    Are you sure you want to cancel the selected quotation?\n                </div>\n                <div invisible=\"sale_orders_count == 1\">\n                    Are you sure you want to cancel the <field name=\"sale_orders_count\"/> selected\n                    quotations?\n                </div>\n                <footer>\n                    <button class=\"btn-primary\" name=\"action_mass_cancel\" type=\"object\" string=\"Cancel quotations\"/>\n                    <button string=\"Discard\" special=\"cancel\"/>\n                </footer>\n            </form>"}', '<?xml version="1.0"?>
<form string="Cancel quotations">
                <field name="sale_order_ids" invisible="1"/>
                <field name="sale_orders_count" invisible="1"/>
                <field name="has_confirmed_order" invisible="1"/>
                <div invisible="not has_confirmed_order">
                    <p class="alert alert-warning fw-bold" role="alert">
                        Some confirmed sale orders are selected. Their related documents might be
                        affected by the cancellation.
                    </p>
                </div>
                <div invisible="sale_orders_count &gt; 1">
                    Are you sure you want to cancel the selected quotation?
                </div>
                <div invisible="sale_orders_count == 1">
                    Are you sure you want to cancel the <field name="sale_orders_count"/> selected
                    quotations?
                </div>
                <footer>
                    <button class="btn-primary" name="action_mass_cancel" type="object" string="Cancel quotations"/>
                    <button string="Discard" special="cancel"/>
                </footer>
            </form>
        ', false, true, '2026-05-10 01:12:05.269262', '2026-05-10 01:12:05.269262', false);
INSERT INTO public.ir_ui_view VALUES (869, 16, 637, 1, 1, 'payment.link.wizard.form', 'payment.link.wizard', NULL, 'form', 'sale/wizard/payment_link_wizard_views.xml', 'extension', '{"en_US": "<data><field name=\"amount\" position=\"after\">\n                <field name=\"amount_paid\" invisible=\"amount_paid &lt;= 0\"/>\n            </field>\n            <div name=\"payment_link_warning_information\" position=\"after\">\n                <span class=\"text-info text-center fw-bold\" role=\"alert\" invisible=\"not confirmation_message\">\n                    <field name=\"confirmation_message\"/>\n                </span>\n            </div>\n        </data>"}', '<?xml version="1.0"?>
<data><field name="amount" position="after">
                <field name="amount_paid" invisible="amount_paid &lt;= 0"/>
            </field>
            <div name="payment_link_warning_information" position="after">
                <span class="text-info text-center fw-bold" role="alert" invisible="not confirmation_message">
                    <field name="confirmation_message"/>
                </span>
            </div>
        </data>', false, true, '2026-05-10 01:12:05.269262', '2026-05-10 01:12:05.269262', false);
INSERT INTO public.ir_ui_view VALUES (870, 10, 176, 1, 1, 'res.config.settings.view.form.inherit.sale', 'res.config.settings', NULL, 'form', 'sale/wizard/res_config_settings_views.xml', 'extension', '{"en_US": "<xpath expr=\"//form\" position=\"inside\">\n                <app notApp=\"1\" string=\"Sales\" data-string=\"Sales\" name=\"sale_management\" groups=\"sales_team.group_sale_manager\">\n                    <block title=\"Product Catalog\" name=\"catalog_setting_container\">\n                        <setting id=\"variant_options\" help=\"Sell variants of a product using attributes (size, color, etc.)\" documentation=\"/applications/sales/sales/products_prices/products/variants.html\">\n                            <field name=\"group_product_variant\"/>\n                            <div class=\"content-group\" invisible=\"not group_product_variant\">\n                                <div class=\"mt8\">\n                                    <button name=\"172\" icon=\"oi-arrow-right\" type=\"action\" string=\"Attributes\" class=\"btn-link\"/>\n                                </div>\n                            </div>\n                        </setting>\n                        <setting string=\"Variant Grid Entry\" help=\"Add several variants to an order from a grid\" id=\"product_matrix\">\n                            <field name=\"module_sale_product_matrix\"/>\n                        </setting>\n                        <setting id=\"uom_settings\" help=\"Sell and purchase products in different units of measure\">\n                            <field name=\"group_uom\"/>\n                            <div class=\"content-group\" invisible=\"not group_uom\">\n                                <div class=\"mt8\">\n                                    <button name=\"88\" icon=\"oi-arrow-right\" type=\"action\" string=\"Units of Measure\" class=\"btn-link\"/>\n                                </div>\n                            </div>\n                        </setting>\n                        <setting id=\"email_template\" title=\"Sending an email is useful if you need to share specific information or content about a product (instructions, rules, links, media, etc.). Create and set the email template from the product detail form (in Accounting tab).\" string=\"Deliver Content by Email\" help=\"Send a product-specific email once the invoice is validated\">\n                            <field name=\"module_product_email_template\"/>\n                        </setting>\n                        <setting id=\"stock_packaging\" title=\"Ability to select a package type in sales orders and to force a quantity that is a multiple of the number of units per package.\" help=\"Sell products by multiple of unit # per package\">\n                            <field name=\"group_stock_packaging\"/>\n                        </setting>\n                    </block>\n                    <block title=\"Pricing\" id=\"pricing_setting_container\">\n                      <setting id=\"discount_sale_order_lines\" title=\"Apply manual discounts on sales order lines or display discounts computed from pricelists (option to activate in the pricelist configuration).\" help=\"Grant discounts on sales order lines\">\n                            <field name=\"group_discount_per_so_line\"/>\n                       </setting>\n                        <setting id=\"coupon_settings\" title=\"Boost your sales with multiple kinds of programs: Coupons, Promotions, Gift Card, Loyalty. Specific conditions can be set (products, customers, minimum purchase amount, period). Rewards can be discounts (% or amount) or free products.\" string=\"Discounts, Loyalty &amp; Gift Card\" help=\"Manage Promotions, coupons, loyalty cards, Gift cards &amp; eWallet\">\n                            <field name=\"module_loyalty\"/>\n                        </setting>\n                        <setting id=\"pricelist_configuration\" documentation=\"/applications/sales/sales/products_prices/prices/pricing.html\" help=\"Set multiple prices per product, automated discounts, etc.\">\n                            <field name=\"group_product_pricelist\"/>\n                            <div class=\"content-group\" invisible=\"not group_product_pricelist\">\n                                <div class=\"mt16\">\n                                    <field name=\"group_sale_pricelist\" invisible=\"1\"/>\n                                    <field name=\"product_pricelist_setting\" widget=\"radio\" class=\"o_light_label\"/>\n                                </div>\n                                <div class=\"mt8\">\n                                    <button name=\"175\" icon=\"oi-arrow-right\" type=\"action\" string=\"Pricelists\" groups=\"product.group_product_pricelist\" class=\"btn-link\"/>\n                                </div>\n                            </div>\n                        </setting>\n                        <setting id=\"auth_signup_documents\" title=\" To send invitations in B2B mode, open a contact or select several ones in list view and click on ''Portal Access Management'' option in the dropdown menu *Action*.\" help=\"Let your customers log in to see their documents\">\n                            <field name=\"auth_signup_uninvited\" class=\"o_light_label\" widget=\"radio\" options=\"{''horizontal'': true}\" required=\"True\"/>\n                        </setting>\n                        <setting id=\"show_margins\" help=\"Show margins on orders\" title=\"The margin is computed as the sum of product sales prices minus the cost set in their detail form.\">\n                            <field name=\"module_sale_margin\"/>\n                        </setting>\n                    </block>\n                    <block title=\"Quotations &amp; Orders\" name=\"quotation_order_setting_container\">\n                        <setting id=\"order_default_values\" string=\"Default values\" help=\"Default values used when creating new quotations. Those can still be changed on each quotation.\" company_dependent=\"1\">\n                            <div class=\"mt16\" id=\"order_default_values_div\">\n                                <div>\n                                    <field name=\"portal_confirmation_sign\" class=\"w-auto\"/>\n                                    <label for=\"portal_confirmation_sign\"/>\n                                    <a href=\"https://www.odoo.com/documentation/17.0/applications/sales/sales/send_quotations/get_signature_to_validate.html\" title=\"Documentation\" class=\"me-2 o_doc_link\" target=\"_blank\"/>\n                                </div>\n                                <div class=\"text-muted\">\n                                    Request an online signature to confirm orders\n                                </div>\n                                <div class=\"mt16\">\n                                    <field name=\"portal_confirmation_pay\" class=\"col-lg-4 oe_inline\"/>\n                                    <label for=\"portal_confirmation_pay\"/>\n                                    <a href=\"https://www.odoo.com/documentation/17.0/applications/sales/sales/send_quotations/get_paid_to_validate.html\" title=\"Documentation\" class=\"me-2 o_doc_link\" target=\"_blank\"/>\n                                </div>\n                                <div class=\"text-muted\">\n                                    Request an online prepayment from your customers to confirm orders. You can ask them to fully pay the order or partially with a downpayment\n                                </div>\n                                <div invisible=\"not portal_confirmation_pay\" class=\"text-nowrap fw-bold\">\n                                    Prepayment amount\n                                    <field name=\"prepayment_percent\" widget=\"percentage\" style=\"width: 3rem\"/>\n                                </div>\n                                <div class=\"mt8\" invisible=\"not portal_confirmation_pay\">\n                                    <button name=\"215\" icon=\"oi-arrow-right\" type=\"action\" string=\"Payment Providers\" class=\"btn-link\"/>\n                                </div>\n                                <div class=\"mt16\" title=\"Days between quotation proposal and expiration. 0 days means automatic expiration is disabled\">\n                                    <label for=\"quotation_validity_days\"/>\n                                    <field name=\"quotation_validity_days\" class=\"text-center\" style=\"width: 5rem;\"/>\n                                    <div class=\"d-inline-block\">days</div>\n                                </div>\n                            </div>\n                        </setting>\n                        <setting id=\"order_warnings\" string=\"Sale Warnings\" help=\"Get warnings in orders for products or customers\">\n                            <field name=\"group_warning_sale\"/>\n                        </setting>\n                        <setting id=\"sale_pdf_quote_builder\" string=\"PDF Quote builder\" help=\"Make your quote attractive by adding header pages, product descriptions and footer pages to your quote.\">\n                            <field name=\"module_sale_pdf_quote_builder\"/>\n                        </setting>\n                        <setting id=\"no_edit_order\" help=\"No longer edit orders once confirmed\">\n                            <field name=\"group_auto_done_setting\"/>\n                        </setting>\n                        <setting id=\"proforma_configuration\" help=\"Allows you to send Pro-Forma Invoice to your customers\">\n                            <field name=\"group_proforma_sales\"/>\n                        </setting>\n                    </block>\n                    <block title=\"Shipping\" name=\"sale_shipping_setting_container\">\n                        <setting id=\"delivery\" help=\"Compute shipping costs on orders\">\n                            <field name=\"module_delivery\"/>\n                        </setting>\n                        <setting id=\"ups\">\n                            <div class=\"o_form_label\">UPS Connector</div>\n                                <a href=\"https://www.odoo.com/documentation/17.0/applications/inventory_and_mrp/inventory/shipping/setup/third_party_shipper.html\" title=\"Documentation\" class=\"o_doc_link\" target=\"_blank\"/>\n                                <div class=\"text-muted\">\n                                    Compute shipping costs and ship with UPS<br/>\n                                    <strong>(please go to Home&gt;Apps to install)</strong>\n                                </div>\n                        </setting>\n                        <setting id=\"shipping_costs_dhl\">\n                            <div class=\"o_form_label\">DHL Connector</div>\n                                <a href=\"https://www.odoo.com/documentation/17.0/applications/inventory_and_mrp/inventory/shipping/setup/third_party_shipper.html\" title=\"Documentation\" class=\"o_doc_link\" target=\"_blank\"/>\n                                <div class=\"text-muted\">\n                                    Compute shipping costs and ship with DHL<br/>\n                                    <strong>(please go to Home&gt;Apps to install)</strong>\n                                </div>\n                        </setting>\n                        <setting id=\"shipping_costs_fedex\">\n                            <div class=\"o_form_label\">FedEx Connector</div>\n                                <a href=\"https://www.odoo.com/documentation/17.0/applications/inventory_and_mrp/inventory/shipping/setup/third_party_shipper.html\" title=\"Documentation\" class=\"o_doc_link\" target=\"_blank\"/>\n                                <div class=\"text-muted\">\n                                    Compute shipping costs and ship with FedEx<br/>\n                                    <strong>(please go to Home&gt;Apps to install)</strong>\n                                </div>\n                        </setting>\n                        <setting id=\"shipping_costs_usps\">\n                            <div class=\"o_form_label\">USPS Connector</div>\n                                <a href=\"https://www.odoo.com/documentation/17.0/applications/inventory_and_mrp/inventory/shipping/setup/third_party_shipper.html\" title=\"Documentation\" class=\"o_doc_link\" target=\"_blank\"/>\n                                <div class=\"text-muted\">\n                                    Compute shipping costs and ship with USPS<br/>\n                                    <strong>(please go to Home&gt;Apps to install)</strong>\n                                </div>\n                        </setting>\n                        <setting id=\"shipping_costs_bpost\" help=\"Compute shipping costs and ship with bpost\" documentation=\"/applications/inventory_and_mrp/inventory/shipping/setup/third_party_shipper.html\">\n                            <field name=\"module_delivery_bpost\" widget=\"upgrade_boolean\"/>\n                        </setting>\n                        <setting id=\"shipping_costs_easypost\" help=\"Compute shipping costs and ship with Easypost\" documentation=\"/applications/inventory_and_mrp/inventory/shipping/setup/third_party_shipper.html\">\n                            <field name=\"module_delivery_easypost\" widget=\"upgrade_boolean\"/>\n                        </setting>\n                        <setting id=\"shipping_costs_sendcloud\" help=\"Compute shipping costs and ship with Sendcloud\" documentation=\"/applications/inventory_and_mrp/inventory/shipping/setup/third_party_shipper.html\">\n                            <field name=\"module_delivery_sendcloud\" widget=\"upgrade_boolean\"/>\n                        </setting>\n                        <setting id=\"shipping_costs_shiprocket\" help=\"Compute shipping costs and ship with Shiprocket\" documentation=\"/applications/inventory_and_mrp/inventory/shipping/setup/third_party_shipper.html\">\n                            <field name=\"module_delivery_shiprocket\" widget=\"upgrade_boolean\"/>\n                        </setting>\n                    </block>\n                    <block title=\"Invoicing\" name=\"invoicing_setting_container\">\n                        <setting id=\"sales_settings_invoicing_policy\" title=\"This default value is applied to any new product created. This can be changed in the product detail form.\" documentation=\"/applications/sales/sales/invoicing/invoicing_policy.html\" help=\"Quantities to invoice from sales orders\">\n                            <field name=\"default_invoice_policy\" class=\"o_light_label\" widget=\"radio\"/>\n                        </setting>\n                        <setting id=\"automatic_invoicing\" help=\"Generate the invoice automatically when the online payment is confirmed\" invisible=\"default_invoice_policy != ''order'' or not portal_confirmation_pay\">\n                            <field name=\"automatic_invoice\"/>\n                            <div invisible=\"not automatic_invoice\" groups=\"base.group_no_one\">\n                                <label for=\"invoice_mail_template_id\" class=\"o_light_label me-2\"/>\n                                <field name=\"invoice_mail_template_id\" class=\"oe_inline\" options=\"{''no_create'': True}\"/>\n                            </div>\n                        </setting>\n                        <setting id=\"down_payments\" string=\"Down Payments\" help=\"Product used for down payments\" documentation=\"/applications/sales/sales/invoicing/down_payment.html\" company_dependent=\"1\">\n                            <field name=\"deposit_default_product_id\" context=\"{''default_detailed_type'': ''service''}\"/>\n                        </setting>\n                    </block>\n                    <block title=\"Connectors\" id=\"connectors_setting_container\">\n                        <setting id=\"amazon_connector\" documentation=\"/applications/sales/sales/amazon_connector/setup.html\" help=\"Import Amazon orders and sync deliveries\">\n                            <field name=\"module_sale_amazon\" widget=\"upgrade_boolean\"/>\n                            <div class=\"content-group\" name=\"amazon_connector\" invisible=\"not module_sale_amazon\"/>\n                        </setting>\n                    </block>\n                    <div id=\"sale_ebay\"/>\n                </app>\n            </xpath>"}', '<?xml version="1.0"?>
<xpath expr="//form" position="inside">
                <app notApp="1" string="Sales" data-string="Sales" name="sale_management" groups="sales_team.group_sale_manager">
                    <block title="Product Catalog" name="catalog_setting_container">
                        <setting id="variant_options" help="Sell variants of a product using attributes (size, color, etc.)" documentation="/applications/sales/sales/products_prices/products/variants.html">
                            <field name="group_product_variant"/>
                            <div class="content-group" invisible="not group_product_variant">
                                <div class="mt8">
                                    <button name="172" icon="oi-arrow-right" type="action" string="Attributes" class="btn-link"/>
                                </div>
                            </div>
                        </setting>
                        <setting string="Variant Grid Entry" help="Add several variants to an order from a grid" id="product_matrix">
                            <field name="module_sale_product_matrix"/>
                        </setting>
                        <setting id="uom_settings" help="Sell and purchase products in different units of measure">
                            <field name="group_uom"/>
                            <div class="content-group" invisible="not group_uom">
                                <div class="mt8">
                                    <button name="88" icon="oi-arrow-right" type="action" string="Units of Measure" class="btn-link"/>
                                </div>
                            </div>
                        </setting>
                        <setting id="email_template" title="Sending an email is useful if you need to share specific information or content about a product (instructions, rules, links, media, etc.). Create and set the email template from the product detail form (in Accounting tab)." string="Deliver Content by Email" help="Send a product-specific email once the invoice is validated">
                            <field name="module_product_email_template"/>
                        </setting>
                        <setting id="stock_packaging" title="Ability to select a package type in sales orders and to force a quantity that is a multiple of the number of units per package." help="Sell products by multiple of unit # per package">
                            <field name="group_stock_packaging"/>
                        </setting>
                    </block>
                    <block title="Pricing" id="pricing_setting_container">
                      <setting id="discount_sale_order_lines" title="Apply manual discounts on sales order lines or display discounts computed from pricelists (option to activate in the pricelist configuration)." help="Grant discounts on sales order lines">
                            <field name="group_discount_per_so_line"/>
                       </setting>
                        <setting id="coupon_settings" title="Boost your sales with multiple kinds of programs: Coupons, Promotions, Gift Card, Loyalty. Specific conditions can be set (products, customers, minimum purchase amount, period). Rewards can be discounts (% or amount) or free products." string="Discounts, Loyalty &amp; Gift Card" help="Manage Promotions, coupons, loyalty cards, Gift cards &amp; eWallet">
                            <field name="module_loyalty"/>
                        </setting>
                        <setting id="pricelist_configuration" documentation="/applications/sales/sales/products_prices/prices/pricing.html" help="Set multiple prices per product, automated discounts, etc.">
                            <field name="group_product_pricelist"/>
                            <div class="content-group" invisible="not group_product_pricelist">
                                <div class="mt16">
                                    <field name="group_sale_pricelist" invisible="1"/>
                                    <field name="product_pricelist_setting" widget="radio" class="o_light_label"/>
                                </div>
                                <div class="mt8">
                                    <button name="175" icon="oi-arrow-right" type="action" string="Pricelists" groups="product.group_product_pricelist" class="btn-link"/>
                                </div>
                            </div>
                        </setting>
                        <setting id="auth_signup_documents" title=" To send invitations in B2B mode, open a contact or select several ones in list view and click on ''Portal Access Management'' option in the dropdown menu *Action*." help="Let your customers log in to see their documents">
                            <field name="auth_signup_uninvited" class="o_light_label" widget="radio" options="{''horizontal'': true}" required="True"/>
                        </setting>
                        <setting id="show_margins" help="Show margins on orders" title="The margin is computed as the sum of product sales prices minus the cost set in their detail form.">
                            <field name="module_sale_margin"/>
                        </setting>
                    </block>
                    <block title="Quotations &amp; Orders" name="quotation_order_setting_container">
                        <setting id="order_default_values" string="Default values" help="Default values used when creating new quotations. Those can still be changed on each quotation." company_dependent="1">
                            <div class="mt16" id="order_default_values_div">
                                <div>
                                    <field name="portal_confirmation_sign" class="w-auto"/>
                                    <label for="portal_confirmation_sign"/>
                                    <a href="https://www.odoo.com/documentation/17.0/applications/sales/sales/send_quotations/get_signature_to_validate.html" title="Documentation" class="me-2 o_doc_link" target="_blank"/>
                                </div>
                                <div class="text-muted">
                                    Request an online signature to confirm orders
                                </div>
                                <div class="mt16">
                                    <field name="portal_confirmation_pay" class="col-lg-4 oe_inline"/>
                                    <label for="portal_confirmation_pay"/>
                                    <a href="https://www.odoo.com/documentation/17.0/applications/sales/sales/send_quotations/get_paid_to_validate.html" title="Documentation" class="me-2 o_doc_link" target="_blank"/>
                                </div>
                                <div class="text-muted">
                                    Request an online prepayment from your customers to confirm orders. You can ask them to fully pay the order or partially with a downpayment
                                </div>
                                <div invisible="not portal_confirmation_pay" class="text-nowrap fw-bold">
                                    Prepayment amount
                                    <field name="prepayment_percent" widget="percentage" style="width: 3rem"/>
                                </div>
                                <div class="mt8" invisible="not portal_confirmation_pay">
                                    <button name="215" icon="oi-arrow-right" type="action" string="Payment Providers" class="btn-link"/>
                                </div>
                                <div class="mt16" title="Days between quotation proposal and expiration. 0 days means automatic expiration is disabled">
                                    <label for="quotation_validity_days"/>
                                    <field name="quotation_validity_days" class="text-center" style="width: 5rem;"/>
                                    <div class="d-inline-block">days</div>
                                </div>
                            </div>
                        </setting>
                        <setting id="order_warnings" string="Sale Warnings" help="Get warnings in orders for products or customers">
                            <field name="group_warning_sale"/>
                        </setting>
                        <setting id="sale_pdf_quote_builder" string="PDF Quote builder" help="Make your quote attractive by adding header pages, product descriptions and footer pages to your quote.">
                            <field name="module_sale_pdf_quote_builder"/>
                        </setting>
                        <setting id="no_edit_order" help="No longer edit orders once confirmed">
                            <field name="group_auto_done_setting"/>
                        </setting>
                        <setting id="proforma_configuration" help="Allows you to send Pro-Forma Invoice to your customers">
                            <field name="group_proforma_sales"/>
                        </setting>
                    </block>
                    <block title="Shipping" name="sale_shipping_setting_container">
                        <setting id="delivery" help="Compute shipping costs on orders">
                            <field name="module_delivery"/>
                        </setting>
                        <setting id="ups">
                            <div class="o_form_label">UPS Connector</div>
                                <a href="https://www.odoo.com/documentation/17.0/applications/inventory_and_mrp/inventory/shipping/setup/third_party_shipper.html" title="Documentation" class="o_doc_link" target="_blank"/>
                                <div class="text-muted">
                                    Compute shipping costs and ship with UPS<br/>
                                    <strong>(please go to Home&gt;Apps to install)</strong>
                                </div>
                        </setting>
                        <setting id="shipping_costs_dhl">
                            <div class="o_form_label">DHL Connector</div>
                                <a href="https://www.odoo.com/documentation/17.0/applications/inventory_and_mrp/inventory/shipping/setup/third_party_shipper.html" title="Documentation" class="o_doc_link" target="_blank"/>
                                <div class="text-muted">
                                    Compute shipping costs and ship with DHL<br/>
                                    <strong>(please go to Home&gt;Apps to install)</strong>
                                </div>
                        </setting>
                        <setting id="shipping_costs_fedex">
                            <div class="o_form_label">FedEx Connector</div>
                                <a href="https://www.odoo.com/documentation/17.0/applications/inventory_and_mrp/inventory/shipping/setup/third_party_shipper.html" title="Documentation" class="o_doc_link" target="_blank"/>
                                <div class="text-muted">
                                    Compute shipping costs and ship with FedEx<br/>
                                    <strong>(please go to Home&gt;Apps to install)</strong>
                                </div>
                        </setting>
                        <setting id="shipping_costs_usps">
                            <div class="o_form_label">USPS Connector</div>
                                <a href="https://www.odoo.com/documentation/17.0/applications/inventory_and_mrp/inventory/shipping/setup/third_party_shipper.html" title="Documentation" class="o_doc_link" target="_blank"/>
                                <div class="text-muted">
                                    Compute shipping costs and ship with USPS<br/>
                                    <strong>(please go to Home&gt;Apps to install)</strong>
                                </div>
                        </setting>
                        <setting id="shipping_costs_bpost" help="Compute shipping costs and ship with bpost" documentation="/applications/inventory_and_mrp/inventory/shipping/setup/third_party_shipper.html">
                            <field name="module_delivery_bpost" widget="upgrade_boolean"/>
                        </setting>
                        <setting id="shipping_costs_easypost" help="Compute shipping costs and ship with Easypost" documentation="/applications/inventory_and_mrp/inventory/shipping/setup/third_party_shipper.html">
                            <field name="module_delivery_easypost" widget="upgrade_boolean"/>
                        </setting>
                        <setting id="shipping_costs_sendcloud" help="Compute shipping costs and ship with Sendcloud" documentation="/applications/inventory_and_mrp/inventory/shipping/setup/third_party_shipper.html">
                            <field name="module_delivery_sendcloud" widget="upgrade_boolean"/>
                        </setting>
                        <setting id="shipping_costs_shiprocket" help="Compute shipping costs and ship with Shiprocket" documentation="/applications/inventory_and_mrp/inventory/shipping/setup/third_party_shipper.html">
                            <field name="module_delivery_shiprocket" widget="upgrade_boolean"/>
                        </setting>
                    </block>
                    <block title="Invoicing" name="invoicing_setting_container">
                        <setting id="sales_settings_invoicing_policy" title="This default value is applied to any new product created. This can be changed in the product detail form." documentation="/applications/sales/sales/invoicing/invoicing_policy.html" help="Quantities to invoice from sales orders">
                            <field name="default_invoice_policy" class="o_light_label" widget="radio"/>
                        </setting>
                        <setting id="automatic_invoicing" help="Generate the invoice automatically when the online payment is confirmed" invisible="default_invoice_policy != ''order'' or not portal_confirmation_pay">
                            <field name="automatic_invoice"/>
                            <div invisible="not automatic_invoice" groups="base.group_no_one">
                                <label for="invoice_mail_template_id" class="o_light_label me-2"/>
                                <field name="invoice_mail_template_id" class="oe_inline" options="{''no_create'': True}"/>
                            </div>
                        </setting>
                        <setting id="down_payments" string="Down Payments" help="Product used for down payments" documentation="/applications/sales/sales/invoicing/down_payment.html" company_dependent="1">
                            <field name="deposit_default_product_id" context="{''default_detailed_type'': ''service''}"/>
                        </setting>
                    </block>
                    <block title="Connectors" id="connectors_setting_container">
                        <setting id="amazon_connector" documentation="/applications/sales/sales/amazon_connector/setup.html" help="Import Amazon orders and sync deliveries">
                            <field name="module_sale_amazon" widget="upgrade_boolean"/>
                            <div class="content-group" name="amazon_connector" invisible="not module_sale_amazon"/>
                        </setting>
                    </block>
                    <div id="sale_ebay"/>
                </app>
            </xpath>
        ', false, true, '2026-05-10 01:12:05.269262', '2026-05-10 01:12:05.269262', false);
INSERT INTO public.ir_ui_view VALUES (871, 16, NULL, 1, 1, 'Invoice Orders', 'sale.advance.payment.inv', NULL, 'form', 'sale/wizard/sale_make_invoice_advance_views.xml', 'primary', '{"en_US": "<form string=\"Invoice Sales Order\">\n                <field name=\"display_draft_invoice_warning\" invisible=\"1\"/>\n                <field name=\"has_down_payments\" invisible=\"1\"/>\n                <div class=\"alert alert-warning pb-1\" role=\"alert\" invisible=\"not display_draft_invoice_warning\">\n                    <p>There are existing <a name=\"view_draft_invoices\" type=\"object\">Draft Invoices</a> for this Sale Order.</p>\n                    <p invisible=\"advance_payment_method != ''delivered''\">\n                        The new invoice will deduct draft invoices linked to this sale order.\n                    </p>\n                </div>\n                <group>\n                    <field name=\"sale_order_ids\" invisible=\"1\"/>\n                    <field name=\"count\" invisible=\"count == 1\"/>\n                    <field name=\"consolidated_billing\" invisible=\"count == 1\"/>\n                    <field name=\"advance_payment_method\" class=\"oe_inline\" widget=\"radio\" invisible=\"count &gt; 1\"/>\n                </group>\n                <group name=\"down_payment_specification\" invisible=\"advance_payment_method not in (''fixed'', ''percentage'')\">\n                    <field name=\"company_id\" invisible=\"1\"/>\n                    <field name=\"product_id\" invisible=\"1\"/>\n                    <label for=\"fixed_amount\" invisible=\"advance_payment_method != ''fixed''\"/>\n                    <label for=\"amount\" invisible=\"advance_payment_method != ''percentage''\"/>\n                    <div id=\"payment_method_details\">\n                        <field name=\"currency_id\" invisible=\"1\"/>\n                        <field name=\"display_invoice_amount_warning\" invisible=\"1\"/>\n                        <field name=\"fixed_amount\" invisible=\"advance_payment_method != ''fixed''\" required=\"advance_payment_method == ''fixed''\" class=\"oe_inline\"/>\n                        <field name=\"amount\" invisible=\"advance_payment_method != ''percentage''\" required=\"advance_payment_method == ''percentage''\" class=\"oe_inline\"/>\n                        <span invisible=\"advance_payment_method != ''percentage''\" class=\"oe_inline\">% </span>\n                        <span invisible=\"not display_invoice_amount_warning\" class=\"oe_inline text-danger\" title=\"The Down Payment is greater than the amount remaining to be invoiced.\">\n                            <i class=\"fa fa-warning\"/>\n                        </span>\n                    </div>\n                    <field name=\"deposit_account_id\" options=\"{''no_create'': True}\" invisible=\"product_id\" groups=\"account.group_account_manager\"/>\n                </group>\n                <group invisible=\"not has_down_payments\">\n                    <field name=\"amount_invoiced\"/>\n                    <field name=\"amount_to_invoice\"/>\n                </group>\n                <footer>\n                    <button name=\"create_invoices\" type=\"object\" id=\"create_invoice_open\" string=\"Create Draft Invoice\" class=\"btn-primary\" data-hotkey=\"q\"/>\n                    <button string=\"Cancel\" class=\"btn-secondary\" special=\"cancel\" data-hotkey=\"x\"/>\n                </footer>\n            </form>"}', '<?xml version="1.0"?>
<form string="Invoice Sales Order">
                <field name="display_draft_invoice_warning" invisible="1"/>
                <field name="has_down_payments" invisible="1"/>
                <div class="alert alert-warning pb-1" role="alert" invisible="not display_draft_invoice_warning">
                    <p>There are existing <a name="view_draft_invoices" type="object">Draft Invoices</a> for this Sale Order.</p>
                    <p invisible="advance_payment_method != ''delivered''">
                        The new invoice will deduct draft invoices linked to this sale order.
                    </p>
                </div>
                <group>
                    <field name="sale_order_ids" invisible="1"/>
                    <field name="count" invisible="count == 1"/>
                    <field name="consolidated_billing" invisible="count == 1"/>
                    <field name="advance_payment_method" class="oe_inline" widget="radio" invisible="count &gt; 1"/>
                </group>
                <group name="down_payment_specification" invisible="advance_payment_method not in (''fixed'', ''percentage'')">
                    <field name="company_id" invisible="1"/>
                    <field name="product_id" invisible="1"/>
                    <label for="fixed_amount" invisible="advance_payment_method != ''fixed''"/>
                    <label for="amount" invisible="advance_payment_method != ''percentage''"/>
                    <div id="payment_method_details">
                        <field name="currency_id" invisible="1"/>
                        <field name="display_invoice_amount_warning" invisible="1"/>
                        <field name="fixed_amount" invisible="advance_payment_method != ''fixed''" required="advance_payment_method == ''fixed''" class="oe_inline"/>
                        <field name="amount" invisible="advance_payment_method != ''percentage''" required="advance_payment_method == ''percentage''" class="oe_inline"/>
                        <span invisible="advance_payment_method != ''percentage''" class="oe_inline">% </span>
                        <span invisible="not display_invoice_amount_warning" class="oe_inline text-danger" title="The Down Payment is greater than the amount remaining to be invoiced.">
                            <i class="fa fa-warning"/>
                        </span>
                    </div>
                    <field name="deposit_account_id" options="{''no_create'': True}" invisible="product_id" groups="account.group_account_manager"/>
                </group>
                <group invisible="not has_down_payments">
                    <field name="amount_invoiced"/>
                    <field name="amount_to_invoice"/>
                </group>
                <footer>
                    <button name="create_invoices" type="object" id="create_invoice_open" string="Create Draft Invoice" class="btn-primary" data-hotkey="q"/>
                    <button string="Cancel" class="btn-secondary" special="cancel" data-hotkey="x"/>
                </footer>
            </form>
        ', false, true, '2026-05-10 01:12:05.269262', '2026-05-10 01:12:05.269262', false);
INSERT INTO public.ir_ui_view VALUES (872, 16, NULL, 1, 1, 'sale.order.cancel.form', 'sale.order.cancel', NULL, 'form', 'sale/wizard/sale_order_cancel_views.xml', 'primary', '{"en_US": "<form>\n                <group col=\"1\">\n                    <field name=\"author_id\" invisible=\"1\"/>\n                    <field name=\"lang\" invisible=\"1\"/>\n                    <field name=\"render_model\" invisible=\"1\"/>\n                    <field name=\"order_id\" invisible=\"1\"/>\n                    <field name=\"template_id\" invisible=\"1\"/>\n                    <field name=\"display_invoice_alert\" invisible=\"1\"/>\n                    <div col=\"2\" class=\"alert alert-warning\" role=\"alert\">\n                        <span>Are you sure you want to cancel this order? <br/></span>\n                        <span id=\"display_invoice_alert\" invisible=\"not display_invoice_alert\">\n                            Draft invoices for this order will be cancelled. <br/>\n                        </span>\n                    </div>\n                    <group col=\"2\">\n                        <field name=\"recipient_ids\" widget=\"many2many_tags_email\" options=\"{''no_quick_create'': True}\" context=\"{''show_email'': True, ''form_view_ref'': ''base.view_partner_simple_form''}\"/>\n                    </group>\n                    <group col=\"2\">\n                        <field name=\"subject\" placeholder=\"Subject\"/>\n                    </group>\n                    <field name=\"body\" class=\"oe-bordered-editor\" options=\"{''style-inline'': true}\"/>\n                </group>\n                <footer>\n                    <button string=\"Send and cancel\" name=\"action_send_mail_and_cancel\" type=\"object\" class=\"btn-primary\"/>\n                    <button string=\"Cancel\" name=\"action_cancel\" type=\"object\" class=\"btn-primary mx-1\"/>\n                    <button string=\"Discard\" class=\"btn-secondary\" special=\"cancel\"/>\n                </footer>\n            </form>"}', '<?xml version="1.0"?>
<form>
                <group col="1">
                    <field name="author_id" invisible="1"/>
                    <field name="lang" invisible="1"/>
                    <field name="render_model" invisible="1"/>
                    <field name="order_id" invisible="1"/>
                    <field name="template_id" invisible="1"/>
                    <field name="display_invoice_alert" invisible="1"/>
                    <div col="2" class="alert alert-warning" role="alert">
                        <span>Are you sure you want to cancel this order? <br/></span>
                        <span id="display_invoice_alert" invisible="not display_invoice_alert">
                            Draft invoices for this order will be cancelled. <br/>
                        </span>
                    </div>
                    <group col="2">
                        <field name="recipient_ids" widget="many2many_tags_email" options="{''no_quick_create'': True}" context="{''show_email'': True, ''form_view_ref'': ''base.view_partner_simple_form''}"/>
                    </group>
                    <group col="2">
                        <field name="subject" placeholder="Subject"/>
                    </group>
                    <field name="body" class="oe-bordered-editor" options="{''style-inline'': true}"/>
                </group>
                <footer>
                    <button string="Send and cancel" name="action_send_mail_and_cancel" type="object" class="btn-primary"/>
                    <button string="Cancel" name="action_cancel" type="object" class="btn-primary mx-1"/>
                    <button string="Discard" class="btn-secondary" special="cancel"/>
                </footer>
            </form>
        ', false, true, '2026-05-10 01:12:05.269262', '2026-05-10 01:12:05.269262', false);
INSERT INTO public.ir_ui_view VALUES (873, 16, NULL, 1, 1, 'sale.order.line.wizard.form', 'sale.order.discount', NULL, 'form', 'sale/wizard/sale_order_discount_views.xml', 'primary', '{"en_US": "<form>\n                <sheet>\n                    <field name=\"sale_order_id\" invisible=\"1\"/>\n                    <field name=\"company_id\" invisible=\"1\"/>\n                    <field name=\"currency_id\" invisible=\"1\"/>\n                    <div class=\"row\">\n                        <div class=\"col-sm-5 col-md-4 col-lg-4 col-4\">\n                            <group>\n                                <label for=\"discount_amount\" string=\"Discount\" invisible=\"discount_type != ''amount''\"/>\n                                <field name=\"discount_amount\" invisible=\"discount_type != ''amount''\" nolabel=\"1\"/>\n                                <label for=\"discount_percentage\" string=\"Discount\" invisible=\"discount_type not in (''so_discount'', ''sol_discount'')\"/>\n                                <field name=\"discount_percentage\" invisible=\"discount_type not in (''so_discount'', ''sol_discount'')\" widget=\"percentage\" nolabel=\"1\"/>\n                            </group>\n                        </div>\n                        <div class=\"col-sm-7 col-md-8 col-lg-8 col-8\">\n                            <field name=\"discount_type\" widget=\"radio\"/>\n                        </div>\n                    </div>\n                </sheet>\n                <footer>\n                    <button type=\"object\" string=\"Apply\" name=\"action_apply_discount\" class=\"btn btn-primary\" data-hotkey=\"q\"/>\n                    <button special=\"cancel\" string=\"Discard\" class=\"btn btn-secondary\" data-hotkey=\"x\"/>\n                </footer>\n            </form>"}', '<?xml version="1.0"?>
<form>
                <sheet>
                    <field name="sale_order_id" invisible="1"/>
                    <field name="company_id" invisible="1"/>
                    <field name="currency_id" invisible="1"/>
                    <div class="row">
                        <div class="col-sm-5 col-md-4 col-lg-4 col-4">
                            <group>
                                <label for="discount_amount" string="Discount" invisible="discount_type != ''amount''"/>
                                <field name="discount_amount" invisible="discount_type != ''amount''" nolabel="1"/>
                                <label for="discount_percentage" string="Discount" invisible="discount_type not in (''so_discount'', ''sol_discount'')"/>
                                <field name="discount_percentage" invisible="discount_type not in (''so_discount'', ''sol_discount'')" widget="percentage" nolabel="1"/>
                            </group>
                        </div>
                        <div class="col-sm-7 col-md-8 col-lg-8 col-8">
                            <field name="discount_type" widget="radio"/>
                        </div>
                    </div>
                </sheet>
                <footer>
                    <button type="object" string="Apply" name="action_apply_discount" class="btn btn-primary" data-hotkey="q"/>
                    <button special="cancel" string="Discard" class="btn btn-secondary" data-hotkey="x"/>
                </footer>
            </form>
        ', false, true, '2026-05-10 01:12:05.269262', '2026-05-10 01:12:05.269262', false);
INSERT INTO public.ir_ui_view VALUES (898, 16, 482, 1, 1, 'product.packaging.form.view.sale', 'product.packaging', NULL, 'form', 'sale/views/product_packaging_views.xml', 'extension', '{"en_US": "<group name=\"group_product\" position=\"inside\">\n                <field name=\"sales\"/>\n            </group>"}', '<?xml version="1.0"?>
