INSERT INTO public.ir_ui_view VALUES (874, 16, NULL, 1, 1, 'sale.order.activity', 'sale.order', NULL, 'activity', 'sale/views/sale_order_views.xml', 'primary', '{"en_US": "<activity string=\"Sales Order\">\n                <field name=\"currency_id\"/>\n                <templates>\n                    <div t-name=\"activity-box\" class=\"d-block\">\n                        <div class=\"d-flex justify-content-between\">\n                            <field name=\"name\" display=\"full\" class=\"o_text_block o_text_bold\"/>\n                            <div class=\"m-1\"/>\n                            <field name=\"amount_total\" widget=\"monetary\"/>\n                        </div>\n                        <div class=\"d-flex justify-content-between\">\n                            <field name=\"partner_id\" muted=\"1\" display=\"full\" class=\"o_text_block\"/>\n                            <div class=\"m-1\"/>\n                            <field name=\"state\" widget=\"badge\" decoration-info=\"state == ''draft''\" decoration-success=\"state == ''sale''\"/>\n                        </div>\n                    </div>\n                </templates>\n            </activity>"}', '<?xml version="1.0"?>
<activity string="Sales Order">
                <field name="currency_id"/>
                <templates>
                    <div t-name="activity-box" class="d-block">
                        <div class="d-flex justify-content-between">
                            <field name="name" display="full" class="o_text_block o_text_bold"/>
                            <div class="m-1"/>
                            <field name="amount_total" widget="monetary"/>
                        </div>
                        <div class="d-flex justify-content-between">
                            <field name="partner_id" muted="1" display="full" class="o_text_block"/>
                            <div class="m-1"/>
                            <field name="state" widget="badge" decoration-info="state == ''draft''" decoration-success="state == ''sale''"/>
                        </div>
                    </div>
                </templates>
            </activity>
        ', false, true, '2026-05-10 01:12:05.269262', '2026-05-10 01:12:05.269262', false);
INSERT INTO public.ir_ui_view VALUES (875, 16, NULL, 1, 1, 'sale.order.calendar', 'sale.order', NULL, 'calendar', 'sale/views/sale_order_views.xml', 'primary', '{"en_US": "<calendar string=\"Sales Orders\" create=\"0\" mode=\"month\" date_start=\"activity_date_deadline\" color=\"state\" event_limit=\"5\" quick_create=\"0\">\n                <field name=\"currency_id\" invisible=\"1\"/>\n                <field name=\"state\" filters=\"1\" invisible=\"1\"/>\n                <field name=\"activity_ids\" options=\"{''icon'': ''fa fa-clock-o''}\"/>\n                <field name=\"partner_id\" avatar_field=\"avatar_128\" options=\"{''icon'': ''fa fa-users''}\"/>\n                <field name=\"amount_total\" widget=\"monetary\"/>\n                <field name=\"payment_term_id\"/>\n            </calendar>"}', '<?xml version="1.0"?>
<calendar string="Sales Orders" create="0" mode="month" date_start="activity_date_deadline" color="state" event_limit="5" quick_create="0">
                <field name="currency_id" invisible="1"/>
                <field name="state" filters="1" invisible="1"/>
                <field name="activity_ids" options="{''icon'': ''fa fa-clock-o''}"/>
                <field name="partner_id" avatar_field="avatar_128" options="{''icon'': ''fa fa-users''}"/>
                <field name="amount_total" widget="monetary"/>
                <field name="payment_term_id"/>
            </calendar>
        ', false, true, '2026-05-10 01:12:05.269262', '2026-05-10 01:12:05.269262', false);
