INSERT INTO public.ir_ui_view VALUES (878, 16, NULL, 1, 1, 'sale.order.kanban', 'sale.order', NULL, 'kanban', 'sale/views/sale_order_views.xml', 'primary', '{"en_US": "<kanban class=\"o_kanban_mobile\" sample=\"1\" quick_create=\"false\">\n                <field name=\"name\"/>\n                <field name=\"partner_id\"/>\n                <field name=\"amount_total\"/>\n                <field name=\"date_order\"/>\n                <field name=\"state\"/>\n                <field name=\"currency_id\"/>\n                <field name=\"activity_state\"/>\n                <progressbar field=\"activity_state\" colors=\"{&quot;planned&quot;: &quot;success&quot;, &quot;today&quot;: &quot;warning&quot;, &quot;overdue&quot;: &quot;danger&quot;}\"/>\n                <templates>\n                    <t t-name=\"kanban-box\">\n                        <div t-attf-class=\"oe_kanban_card oe_kanban_global_click\">\n                            <div class=\"o_kanban_record_top mb16\">\n                                <div class=\"o_kanban_record_headings mt4\">\n                                    <strong class=\"o_kanban_record_title\">\n                                        <span t-out=\"record.partner_id.value\"/>\n                                    </strong>\n                                </div>\n                                <strong>\n                                    <field name=\"amount_total\" widget=\"monetary\"/>\n                                </strong>\n                            </div>\n                            <div class=\"o_kanban_record_bottom\">\n                                <div class=\"oe_kanban_bottom_left text-muted\">\n                                    <span>\n                                        <t t-out=\"record.name.value\"/> <t t-out=\"record.date_order.value\"/>\n                                    </span>\n                                    <field name=\"activity_ids\" widget=\"kanban_activity\"/>\n                                </div>\n                                <div class=\"oe_kanban_bottom_right\">\n                                    <field name=\"state\" widget=\"label_selection\" options=\"{''classes'': {''draft'': ''info'', ''cancel'': ''default'', ''sale'': ''success''}}\"/>\n                                </div>\n                            </div>\n                        </div>\n                    </t>\n                </templates>\n            </kanban>"}', '<?xml version="1.0"?>
<kanban class="o_kanban_mobile" sample="1" quick_create="false">
                <field name="name"/>
                <field name="partner_id"/>
                <field name="amount_total"/>
                <field name="date_order"/>
                <field name="state"/>
                <field name="currency_id"/>
                <field name="activity_state"/>
                <progressbar field="activity_state" colors="{&quot;planned&quot;: &quot;success&quot;, &quot;today&quot;: &quot;warning&quot;, &quot;overdue&quot;: &quot;danger&quot;}"/>
                <templates>
                    <t t-name="kanban-box">
                        <div t-attf-class="oe_kanban_card oe_kanban_global_click">
                            <div class="o_kanban_record_top mb16">
                                <div class="o_kanban_record_headings mt4">
                                    <strong class="o_kanban_record_title">
                                        <span t-out="record.partner_id.value"/>
                                    </strong>
                                </div>
                                <strong>
                                    <field name="amount_total" widget="monetary"/>
                                </strong>
                            </div>
                            <div class="o_kanban_record_bottom">
                                <div class="oe_kanban_bottom_left text-muted">
                                    <span>
                                        <t t-out="record.name.value"/> <t t-out="record.date_order.value"/>
                                    </span>
                                    <field name="activity_ids" widget="kanban_activity"/>
                                </div>
                                <div class="oe_kanban_bottom_right">
                                    <field name="state" widget="label_selection" options="{''classes'': {''draft'': ''info'', ''cancel'': ''default'', ''sale'': ''success''}}"/>
                                </div>
                            </div>
                        </div>
                    </t>
                </templates>
            </kanban>
        ', false, true, '2026-05-10 01:12:05.269262', '2026-05-10 01:12:05.269262', false);
INSERT INTO public.ir_ui_view VALUES (879, 1000, NULL, 1, 1, 'sale.order.tree', 'sale.order', NULL, 'tree', 'sale/views/sale_order_views.xml', 'primary', '{"en_US": "<tree class=\"o_sale_order\" string=\"Sales Orders\" sample=\"1\" decoration-muted=\"state == ''cancel''\">\n                <header>\n                    <button name=\"313\" type=\"action\" string=\"Create Invoices\" class=\"btn-secondary\"/>\n                </header>\n                <field name=\"message_needaction\" column_invisible=\"True\"/>\n                <field name=\"currency_id\" column_invisible=\"True\"/>\n\n                <field name=\"name\" string=\"Number\" readonly=\"1\" decoration-bf=\"1\"/>\n                <field name=\"date_order\" widget=\"date\" optional=\"show\" readonly=\"state in [''cancel'', ''sale'']\"/>\n                <field name=\"commitment_date\" optional=\"hide\"/>\n                <field name=\"expected_date\" optional=\"hide\"/>\n                <field name=\"partner_id\" readonly=\"1\"/>\n                <field name=\"user_id\" widget=\"many2one_avatar_user\" optional=\"show\"/>\n                <field name=\"activity_ids\" widget=\"list_activity\" optional=\"show\"/>\n                <field name=\"team_id\" optional=\"hide\"/>\n                <field name=\"company_id\" groups=\"!base.group_multi_company\" column_invisible=\"True\"/>\n                <field name=\"company_id\" groups=\"base.group_multi_company\" optional=\"show\" readonly=\"1\"/>\n                <field name=\"amount_untaxed\" sum=\"Total Tax Excluded\" widget=\"monetary\" optional=\"hide\"/>\n                <field name=\"amount_tax\" sum=\"Tax Total\" widget=\"monetary\" optional=\"hide\"/>\n                <field name=\"amount_total\" sum=\"Total Tax Included\" widget=\"monetary\" decoration-bf=\"1\" decoration-info=\"invoice_status == ''to invoice''\" optional=\"show\"/>\n                <field name=\"tag_ids\" widget=\"many2many_tags\" options=\"{''color_field'': ''color''}\" optional=\"hide\"/>\n                <field name=\"state\" decoration-success=\"state == ''sale''\" decoration-info=\"state == ''draft''\" decoration-primary=\"state == ''sent''\" widget=\"badge\" optional=\"hide\"/>\n                <field name=\"invoice_status\" decoration-success=\"invoice_status == ''invoiced''\" decoration-info=\"invoice_status == ''to invoice''\" decoration-warning=\"invoice_status == ''upselling''\" widget=\"badge\" optional=\"show\"/>\n                <field name=\"amount_to_invoice\" optional=\"hide\"/>\n                <field name=\"client_order_ref\" optional=\"hide\"/>\n                <field name=\"validity_date\" optional=\"hide\"/>\n            </tree>"}', '<?xml version="1.0"?>
<tree class="o_sale_order" string="Sales Orders" sample="1" decoration-muted="state == ''cancel''">
                <header>
                    <button name="313" type="action" string="Create Invoices" class="btn-secondary"/>
                </header>
                <field name="message_needaction" column_invisible="True"/>
                <field name="currency_id" column_invisible="True"/>

                <field name="name" string="Number" readonly="1" decoration-bf="1"/>
                <field name="date_order" widget="date" optional="show" readonly="state in [''cancel'', ''sale'']"/>
                <field name="commitment_date" optional="hide"/>
                <field name="expected_date" optional="hide"/>
                <field name="partner_id" readonly="1"/>
                <field name="user_id" widget="many2one_avatar_user" optional="show"/>
                <field name="activity_ids" widget="list_activity" optional="show"/>
                <field name="team_id" optional="hide"/>
                <field name="company_id" groups="!base.group_multi_company" column_invisible="True"/>
                <field name="company_id" groups="base.group_multi_company" optional="show" readonly="1"/>
                <field name="amount_untaxed" sum="Total Tax Excluded" widget="monetary" optional="hide"/>
                <field name="amount_tax" sum="Tax Total" widget="monetary" optional="hide"/>
                <field name="amount_total" sum="Total Tax Included" widget="monetary" decoration-bf="1" decoration-info="invoice_status == ''to invoice''" optional="show"/>
                <field name="tag_ids" widget="many2many_tags" options="{''color_field'': ''color''}" optional="hide"/>
                <field name="state" decoration-success="state == ''sale''" decoration-info="state == ''draft''" decoration-primary="state == ''sent''" widget="badge" optional="hide"/>
                <field name="invoice_status" decoration-success="invoice_status == ''invoiced''" decoration-info="invoice_status == ''to invoice''" decoration-warning="invoice_status == ''upselling''" widget="badge" optional="show"/>
                <field name="amount_to_invoice" optional="hide"/>
                <field name="client_order_ref" optional="hide"/>
                <field name="validity_date" optional="hide"/>
            </tree>
        ', false, true, '2026-05-10 01:12:05.269262', '2026-05-10 01:12:05.269262', false);
