INSERT INTO public.ir_ui_view VALUES (883, 16, NULL, 1, 1, 'sale.order.form', 'sale.order', NULL, 'form', 'sale/views/sale_order_views.xml', 'primary', '{"en_US": "<form string=\"Sales Order\" class=\"o_sale_order\">\n            <header>\n                <field name=\"locked\" invisible=\"1\"/>\n                <field name=\"authorized_transaction_ids\" invisible=\"1\"/>\n                <button name=\"payment_action_capture\" type=\"object\" data-hotkey=\"shift+g\" string=\"Capture Transaction\" class=\"oe_highlight\" invisible=\"not authorized_transaction_ids\"/>\n                <button name=\"payment_action_void\" type=\"object\" string=\"Void Transaction\" data-hotkey=\"shift+v\" confirm=\"Are you sure you want to void the authorized transaction? This action can''t be undone.\" invisible=\"not authorized_transaction_ids\"/>\n                <button id=\"create_invoice\" name=\"313\" string=\"Create Invoice\" type=\"action\" class=\"btn-primary\" data-hotkey=\"q\" invisible=\"invoice_status != ''to invoice''\"/>\n                <button id=\"create_invoice_percentage\" name=\"313\" string=\"Create Invoice\" type=\"action\" context=\"{''default_advance_payment_method'': ''percentage''}\" data-hotkey=\"q\" invisible=\"invoice_status != ''no'' or state != ''sale''\"/>\n                <button name=\"action_quotation_send\" id=\"send_by_email_primary\" string=\"Send by Email\" type=\"object\" data-hotkey=\"g\" invisible=\"state != ''draft''\" class=\"btn-primary\" context=\"{''validate_analytic'': True}\"/>\n                <button name=\"action_quotation_send\" id=\"send_proforma_primary\" type=\"object\" string=\"Send PRO-FORMA Invoice\" class=\"btn-primary\" groups=\"sale.group_proforma_sales\" invisible=\"state != ''draft'' or invoice_count &gt;= 1\" context=\"{''proforma'': True, ''validate_analytic'': True}\"/>\n                <button name=\"action_confirm\" id=\"action_confirm\" data-hotkey=\"q\" string=\"Confirm\" class=\"btn-primary\" type=\"object\" context=\"{''validate_analytic'': True}\" invisible=\"state != ''sent''\"/>\n                <button name=\"action_confirm\" data-hotkey=\"q\" string=\"Confirm\" type=\"object\" context=\"{''validate_analytic'': True}\" invisible=\"state != ''draft''\"/>\n                <button name=\"action_quotation_send\" id=\"send_proforma\" type=\"object\" string=\"Send PRO-FORMA Invoice\" groups=\"sale.group_proforma_sales\" invisible=\"state == ''draft'' or invoice_count &gt;= 1\" context=\"{''proforma'': True, ''validate_analytic'': True}\"/>\n                <button name=\"action_quotation_send\" id=\"send_by_email\" string=\"Send by Email\" type=\"object\" invisible=\"state not in (''sent'', ''sale'')\" data-hotkey=\"g\" context=\"{''validate_analytic'': True}\"/>\n\n                <!-- allow to unlock locked orders even if setting is not enabled (e.g. orders synchronized from connectors) -->\n                <button name=\"action_unlock\" type=\"object\" string=\"Unlock\" invisible=\"not locked\" groups=\"sales_team.group_sale_manager\"/>\n                <button name=\"action_preview_sale_order\" string=\"Preview\" type=\"object\" class=\"btn-secondary\"/>\n                <button name=\"action_cancel\" type=\"object\" string=\"Cancel\" invisible=\"state not in [''draft'', ''sent'', ''sale''] or not id or locked\" data-hotkey=\"x\"/>\n                <button name=\"action_draft\" invisible=\"state != ''cancel''\" type=\"object\" string=\"Set to Quotation\" data-hotkey=\"w\"/>\n                <t groups=\"sale.group_auto_done_setting\">\n                    <button name=\"action_lock\" type=\"object\" string=\"Lock\" help=\"If the sale is locked, you can not modify it anymore. However, you will still be able to invoice or deliver.\" invisible=\"locked or state != ''sale''\" groups=\"sales_team.group_sale_manager\"/>\n                </t>\n                <field name=\"state\" widget=\"statusbar\" statusbar_visible=\"draft,sent,sale\"/>\n            </header>\n            <div class=\"alert alert-warning\" role=\"alert\" invisible=\"partner_credit_warning == ''''\">\n                <field name=\"partner_credit_warning\"/>\n            </div>\n            <sheet>\n                <div class=\"oe_button_box\" name=\"button_box\">\n                    <button name=\"action_view_invoice\" type=\"object\" class=\"oe_stat_button\" icon=\"fa-pencil-square-o\" invisible=\"invoice_count == 0\">\n                        <field name=\"invoice_count\" widget=\"statinfo\" string=\"Invoices\"/>\n                    </button>\n                </div>\n                <div class=\"badge rounded-pill text-bg-secondary float-end fs-6 border-0\" invisible=\"not locked\">\n                    <i class=\"fa fa-lock\"/>\n                    Locked\n                </div>\n                <div class=\"oe_title\">\n                    <h1>\n                        <field name=\"name\" readonly=\"1\"/>\n                    </h1>\n                </div>\n                <group name=\"sale_header\">\n                    <group name=\"partner_details\">\n                        <field name=\"partner_id\" widget=\"res_partner_many2one\" context=\"{''res_partner_search_mode'': ''customer'', ''show_address'': 1, ''show_vat'': True}\" placeholder=\"Type to find a customer...\" readonly=\"state in [''cancel'', ''sale'']\"/>\n                        <field name=\"partner_invoice_id\" groups=\"account.group_delivery_invoice_address\" context=\"{''default_type'':''invoice'', ''show_address'': False, ''show_vat'': False}\" readonly=\"state == ''cancel'' or locked\"/>\n                        <field name=\"partner_shipping_id\" groups=\"account.group_delivery_invoice_address\" context=\"{''default_type'':''delivery'', ''show_address'': False, ''show_vat'': False}\" readonly=\"state == ''cancel'' or locked\"/>\n                    </group>\n                    <group name=\"order_details\">\n                        <field name=\"validity_date\" invisible=\"state == ''sale''\" readonly=\"state in [''cancel'', ''sale'']\"/>\n                        <div class=\"o_td_label\" groups=\"base.group_no_one\" invisible=\"state in [''sale'', ''cancel'']\">\n                            <label for=\"date_order\" string=\"Quotation Date\"/>\n                        </div>\n                        <field name=\"date_order\" nolabel=\"1\" groups=\"base.group_no_one\" invisible=\"state in [''sale'', ''cancel'']\" readonly=\"state in [''cancel'', ''sale'']\"/>\n                        <div class=\"o_td_label\" invisible=\"state in [''draft'', ''sent'']\">\n                            <label for=\"date_order\" string=\"Order Date\"/>\n                        </div>\n                        <field name=\"date_order\" invisible=\"state in [''draft'', ''sent'']\" readonly=\"state in [''cancel'', ''sale'']\" nolabel=\"1\"/>\n                        <field name=\"has_active_pricelist\" invisible=\"1\"/>\n                        <field name=\"show_update_pricelist\" invisible=\"1\"/>\n                        <label for=\"pricelist_id\" groups=\"product.group_product_pricelist\" invisible=\"not has_active_pricelist\"/>\n                        <div groups=\"product.group_product_pricelist\" class=\"o_row\" invisible=\"not has_active_pricelist\">\n                            <field name=\"pricelist_id\" options=\"{''no_open'':True,''no_create'': True}\" readonly=\"state in [''cancel'', ''sale'']\"/>\n                            <button name=\"action_update_prices\" type=\"object\" string=\" Update Prices\" help=\"Recompute all prices based on this pricelist\" class=\"btn-link mb-1 px-0\" icon=\"fa-refresh\" confirm=\"This will update the unit price of all products based on the new pricelist.\" invisible=\"not show_update_pricelist or state in [''sale'', ''cancel'']\"/>\n                        </div>\n                        <field name=\"country_code\" invisible=\"1\"/>\n                        <field name=\"company_id\" invisible=\"1\"/>\n                        <field name=\"currency_id\" invisible=\"1\"/>\n                        <field name=\"pricelist_id\" invisible=\"1\" readonly=\"state in [''cancel'', ''sale'']\" groups=\"!product.group_product_pricelist\"/>\n                        <field name=\"tax_country_id\" invisible=\"1\"/>\n                        <field name=\"tax_calculation_rounding_method\" invisible=\"1\"/>\n                        <field name=\"payment_term_id\" options=\"{''no_open'': True, ''no_create'': True}\"/>\n                    </group>\n                </group>\n                <notebook>\n                    <page string=\"Order Lines\" name=\"order_lines\">\n                        <field name=\"order_line\" widget=\"section_and_note_one2many\" mode=\"tree,kanban\" readonly=\"state == ''cancel'' or locked\">\n                            <form>\n                                <field name=\"display_type\" invisible=\"1\"/>\n                                <!--\n                                    We need the sequence field to be here for new lines to be added at the correct position.\n                                    TODO: at some point we want to fix this in the framework so that an invisible field is not required.\n                                -->\n                                <field name=\"sequence\" invisible=\"1\"/>\n                                <field name=\"product_uom_category_id\" invisible=\"1\"/>\n                                <group>\n                                    <group invisible=\"display_type\">\n                                        <field name=\"product_updatable\" invisible=\"1\"/>\n                                        <field name=\"product_id\" domain=\"[(''sale_ok'', ''='', True)]\" context=\"{''partner_id'':parent.partner_id, ''quantity'':product_uom_qty, ''pricelist'':parent.pricelist_id, ''uom'':product_uom, ''company_id'': parent.company_id}\" readonly=\"not product_updatable\" required=\"not display_type\" force_save=\"1\" widget=\"many2one_barcode\"/>\n                                        <field name=\"product_type\" invisible=\"1\"/>\n                                        <field name=\"invoice_status\" invisible=\"1\"/>\n                                        <field name=\"qty_to_invoice\" invisible=\"1\"/>\n                                        <field name=\"qty_delivered_method\" invisible=\"1\"/>\n                                        <field name=\"price_total\" invisible=\"1\"/>\n                                        <field name=\"price_tax\" invisible=\"1\"/>\n                                        <field name=\"price_subtotal\" invisible=\"1\"/>\n                                        <field name=\"product_uom_readonly\" invisible=\"1\"/>\n                                        <label for=\"product_uom_qty\"/>\n                                        <div class=\"o_row\" name=\"ordered_qty\">\n                                            <field context=\"{''partner_id'':parent.partner_id, ''quantity'':product_uom_qty, ''pricelist'':parent.pricelist_id, ''uom'':product_uom, ''uom_qty_change'':True, ''company_id'': parent.company_id}\" name=\"product_uom_qty\"/>\n                                            <field name=\"product_uom\" invisible=\"1\" groups=\"!uom.group_uom\"/>\n                                            <field name=\"product_uom\" force_save=\"1\" groups=\"uom.group_uom\" class=\"oe_no_button\" readonly=\"product_uom_readonly\" required=\"not display_type\"/>\n                                        </div>\n                                        <label for=\"qty_delivered\" string=\"Delivered\" invisible=\"parent.state != ''sale''\"/>\n                                        <div name=\"delivered_qty\" invisible=\"parent.state != ''sale''\">\n                                            <field name=\"qty_delivered\" readonly=\"qty_delivered_method != ''manual''\"/>\n                                        </div>\n                                        <label for=\"qty_invoiced\" string=\"Invoiced\" invisible=\"parent.state != ''sale''\"/>\n                                        <div name=\"invoiced_qty\" invisible=\"parent.state != ''sale''\">\n                                            <field name=\"qty_invoiced\"/>\n                                        </div>\n                                        <field name=\"product_packaging_qty\" invisible=\"not product_id or not product_packaging_id\" groups=\"product.group_stock_packaging\"/>\n                                        <field name=\"product_packaging_id\" invisible=\"not product_id\" context=\"{''default_product_id'': product_id, ''tree_view_ref'':''product.product_packaging_tree_view'', ''form_view_ref'':''product.product_packaging_form_view''}\" groups=\"product.group_stock_packaging\"/>\n                                        <field name=\"price_unit\"/>\n                                        <field name=\"tax_id\" widget=\"many2many_tags\" options=\"{''no_create'': True}\" context=\"{''search_view_ref'': ''account.account_tax_view_search''}\" domain=\"[(''type_tax_use'', ''='', ''sale''), (''company_id'', ''parent_of'', parent.company_id), (''country_id'', ''='', parent.tax_country_id)]\" readonly=\"qty_invoiced &gt; 0\"/>\n                                        <t groups=\"product.group_discount_per_so_line\">\n                                            <label for=\"discount\"/>\n                                            <div name=\"discount\">\n                                                <field name=\"discount\" class=\"oe_inline\"/> %\n                                            </div>\n                                        </t>\n                                        <!--\n                                            We need the sequence field to be here\n                                            because we want to be able to overwrite the default sequence value in the JS\n                                            in order for new lines to be added at the correct position.\n                                            NOTE: at some point we want to fix this in the framework so that an invisible field is not required.\n                                        -->\n                                        <field name=\"sequence\" invisible=\"1\"/>\n                                    </group>\n                                    <group invisible=\"display_type\">\n                                        <label for=\"customer_lead\"/>\n                                        <div name=\"lead\">\n                                            <field name=\"customer_lead\" class=\"oe_inline\"/> days\n                                        </div>\n                                        <field name=\"analytic_distribution\" widget=\"analytic_distribution\" groups=\"analytic.group_analytic_accounting\" options=\"{''product_field'': ''product_id'', ''business_domain'': ''sale_order''}\"/>\n                                    </group>\n                                </group>\n                                <label for=\"name\" string=\"Description\" invisible=\"display_type\"/>\n                                <label for=\"name\" string=\"Section Name (eg. Products, Services)\" invisible=\"display_type != ''line_section''\"/>\n                                <label for=\"name\" string=\"Note\" invisible=\"display_type != ''line_note''\"/>\n                                <field name=\"name\"/>\n                                <div name=\"invoice_lines\" groups=\"base.group_no_one\" invisible=\"display_type\">\n                                    <label for=\"invoice_lines\"/>\n                                    <field name=\"invoice_lines\"/>\n                                </div>\n                                <field name=\"state\" invisible=\"1\"/>\n                                <field name=\"company_id\" invisible=\"1\"/>\n                            </form>\n                            <tree string=\"Sales Order Lines\" editable=\"bottom\" limit=\"200\">\n                                <control>\n                                    <create name=\"add_product_control\" string=\"Add a product\"/>\n                                    <create name=\"add_section_control\" string=\"Add a section\" context=\"{''default_display_type'': ''line_section''}\"/>\n                                    <create name=\"add_note_control\" string=\"Add a note\" context=\"{''default_display_type'': ''line_note''}\"/>\n                                    <button name=\"action_add_from_catalog\" string=\"Catalog\" type=\"object\" class=\"px-4 btn-link\" context=\"{''order_id'': parent.id}\"/>\n                                </control>\n\n                                <field name=\"sequence\" widget=\"handle\"/>\n                                <!-- We do not display the type because we don''t want the user to be bothered with that information if he has no section or note. -->\n                                <field name=\"display_type\" column_invisible=\"True\"/>\n                                <field name=\"product_uom_category_id\" column_invisible=\"True\"/>\n                                <field name=\"product_type\" column_invisible=\"True\"/>\n                                <field name=\"product_updatable\" column_invisible=\"True\"/>\n                                <field name=\"is_downpayment\" column_invisible=\"True\"/>\n                                <field name=\"product_id\" readonly=\"not product_updatable\" required=\"not display_type\" force_save=\"1\" context=\"{                                         ''partner_id'': parent.partner_id,                                         ''quantity'': product_uom_qty,                                         ''pricelist'': parent.pricelist_id,                                         ''uom'':product_uom,                                         ''company_id'': parent.company_id,                                         ''default_lst_price'': price_unit,                                         ''default_description_sale'': name                                     }\" options=\"{                                         ''no_open'': True,                                     }\" domain=\"[(''sale_ok'', ''='', True)]\" widget=\"sol_product_many2one\"/>\n                                <field name=\"product_template_id\" string=\"Product\" column_invisible=\"True\" readonly=\"not product_updatable\" required=\"not display_type\" context=\"{                                         ''partner_id'': parent.partner_id,                                         ''quantity'': product_uom_qty,                                         ''pricelist'': parent.pricelist_id,                                         ''uom'':product_uom,                                         ''company_id'': parent.company_id,                                         ''default_list_price'': price_unit,                                         ''default_description_sale'': name                                     }\" options=\"{                                         ''no_open'': True,                                     }\" domain=\"[(''sale_ok'', ''='', True)]\" widget=\"sol_product_many2one\" placeholder=\"Type to find a product...\"/>\n                                <field name=\"name\" widget=\"section_and_note_text\" optional=\"show\"/>\n                                <field name=\"analytic_distribution\" widget=\"analytic_distribution\" optional=\"hide\" groups=\"analytic.group_analytic_accounting\" options=\"{''product_field'': ''product_id'', ''business_domain'': ''sale_order'', ''amount_field'': ''price_subtotal''}\"/>\n                                <field name=\"product_uom_qty\" decoration-info=\"(not display_type and invoice_status == ''to invoice'')\" decoration-bf=\"(not display_type and invoice_status == ''to invoice'')\" context=\"{                                         ''partner_id'': parent.partner_id,                                         ''quantity'': product_uom_qty,                                         ''pricelist'': parent.pricelist_id,                                         ''uom'': product_uom,                                         ''company_id'': parent.company_id                                     }\" readonly=\"is_downpayment\"/>\n                                <field name=\"qty_delivered\" decoration-info=\"(not display_type and invoice_status == ''to invoice'')\" decoration-bf=\"(not display_type and invoice_status == ''to invoice'')\" string=\"Delivered\" column_invisible=\"parent.state != ''sale''\" readonly=\"qty_delivered_method != ''manual'' or is_downpayment\" optional=\"show\"/>\n                                <field name=\"qty_delivered_method\" column_invisible=\"True\"/>\n                                <field name=\"qty_invoiced\" decoration-info=\"(not display_type and invoice_status == ''to invoice'')\" decoration-bf=\"(not display_type and invoice_status == ''to invoice'')\" string=\"Invoiced\" column_invisible=\"parent.state != ''sale''\" optional=\"show\"/>\n                                <field name=\"qty_to_invoice\" column_invisible=\"True\"/>\n                                <field name=\"product_uom_readonly\" column_invisible=\"True\"/>\n                                <field name=\"product_uom\" column_invisible=\"True\" groups=\"!uom.group_uom\"/>\n                                <field name=\"product_uom\" force_save=\"1\" string=\"UoM\" readonly=\"product_uom_readonly\" required=\"not display_type\" context=\"{''company_id'': parent.company_id}\" groups=\"uom.group_uom\" options=\"{&quot;no_open&quot;: True}\" optional=\"show\"/>\n                                <field name=\"customer_lead\" optional=\"hide\" readonly=\"parent.state not in [''draft'', ''sent'', ''sale''] or is_downpayment\"/>\n                                <field name=\"product_packaging_qty\" invisible=\"not product_id or not product_packaging_id\" groups=\"product.group_stock_packaging\" optional=\"show\"/>\n                                <field name=\"product_packaging_id\" invisible=\"not product_id\" context=\"{''default_product_id'': product_id, ''tree_view_ref'':''product.product_packaging_tree_view'', ''form_view_ref'':''product.product_packaging_form_view''}\" groups=\"product.group_stock_packaging\" optional=\"show\"/>\n                                <field name=\"price_unit\" readonly=\"qty_invoiced &gt; 0\"/>\n                                <field name=\"tax_id\" widget=\"many2many_tags\" options=\"{''no_create'': True}\" domain=\"[(''type_tax_use'', ''='', ''sale''), (''company_id'', ''parent_of'', parent.company_id), (''country_id'', ''='', parent.tax_country_id)]\" context=\"{''active_test'': True}\" readonly=\"qty_invoiced &gt; 0 or is_downpayment\" optional=\"show\"/>\n                                <field name=\"discount\" string=\"Disc.%\" groups=\"product.group_discount_per_so_line\" optional=\"show\"/>\n                                <field name=\"is_downpayment\" column_invisible=\"True\"/>\n                                <field name=\"price_subtotal\" string=\"Tax excl.\" invisible=\"is_downpayment\"/>\n                                <field name=\"price_total\" string=\"Tax incl.\" column_invisible=\"parent.tax_calculation_rounding_method == ''round_globally''\" invisible=\"is_downpayment\" optional=\"hide\"/>\n                                <!-- Others fields -->\n                                <field name=\"tax_calculation_rounding_method\" column_invisible=\"True\"/>\n                                <field name=\"state\" column_invisible=\"True\"/>\n                                <field name=\"invoice_status\" column_invisible=\"True\"/>\n                                <field name=\"currency_id\" column_invisible=\"True\"/>\n                                <field name=\"price_tax\" column_invisible=\"True\"/>\n                                <field name=\"company_id\" column_invisible=\"True\"/>\n                            </tree>\n                            <kanban class=\"o_kanban_mobile\">\n                                <field name=\"name\"/>\n                                <field name=\"product_id\"/>\n                                <field name=\"product_uom_qty\"/>\n                                <field name=\"product_uom\"/>\n                                <field name=\"price_subtotal\"/>\n                                <field name=\"price_total\"/>\n                                <field name=\"price_tax\"/>\n                                <field name=\"price_total\"/>\n                                <field name=\"price_unit\"/>\n                                <field name=\"display_type\"/>\n                                <field name=\"tax_id\"/>\n                                <field name=\"company_id\"/>\n                                <field name=\"tax_calculation_rounding_method\"/>\n                                <control>\n                                    <create name=\"add_product_control\" string=\"Add a product\"/>\n                                    <create name=\"add_section_control\" string=\"Add a section\" context=\"{''default_display_type'': ''line_section''}\"/>\n                                    <create name=\"add_note_control\" string=\"Add a note\" context=\"{''default_display_type'': ''line_note''}\"/>\n                                    <button name=\"action_add_from_catalog\" context=\"{''order_id'': parent.id}\" string=\"Catalog\" type=\"object\" class=\"btn-secondary\"/>\n                                </control>\n                                <templates>\n                                    <t t-name=\"kanban-box\">\n                                        <div t-attf-class=\"oe_kanban_card oe_kanban_global_click ps-0 pe-0 {{ record.display_type.raw_value ? ''o_is_'' + record.display_type.raw_value : '''' }}\">\n                                            <t t-if=\"!record.display_type.raw_value\">\n                                                <div class=\"row g-0\">\n                                                    <div class=\"col-2 pe-3\">\n                                                        <img t-att-src=\"kanban_image(''product.product'', ''image_128'', record.product_id.raw_value)\" t-att-title=\"record.product_id.value\" t-att-alt=\"record.product_id.value\" style=\"max-width: 100%;\"/>\n                                                    </div>\n                                                    <div class=\"col-10\">\n                                                        <div class=\"row\">\n                                                            <div class=\"col\">\n                                                                <strong t-out=\"record.product_id.value\"/>\n                                                            </div>\n                                                            <div class=\"col-auto\">\n                                                                <strong>Tax excl.: </strong>\n                                                                <t t-set=\"line_price\" t-value=\"record.price_subtotal.value\"/>\n                                                                <strong class=\"float-end text-end\" t-out=\"line_price\"/>\n                                                            </div>\n                                                        </div>\n                                                        <div class=\"row\">\n                                                            <div class=\"col-12 text-muted\">\n                                                                Quantity:\n                                                                <t t-out=\"record.product_uom_qty.value\"/> <t t-out=\"record.product_uom.value\"/>\n                                                            </div>\n                                                        </div>\n                                                        <div class=\"row\">\n                                                            <div class=\"col text-muted\">\n                                                                Unit Price:\n                                                                <t t-out=\"record.price_unit.value\"/>\n                                                            </div>\n                                                            <div class=\"col-auto\" t-if=\"record.tax_calculation_rounding_method.raw_value === ''round_per_line''\">\n                                                                <strong>Tax incl.: </strong>\n                                                                <t t-set=\"line_price\" t-value=\"record.price_total.value\"/>\n                                                                <strong class=\"float-end text-end\" t-out=\"line_price\"/>\n                                                            </div>\n                                                        </div>\n                                                        <t t-if=\"record.discount?.raw_value\">\n                                                            <div class=\"row\">\n                                                                <div class=\"col-12 text-muted\">\n                                                                    Discount:\n                                                                    <t t-out=\"record.discount.value\"/>%\n                                                                </div>\n                                                            </div>\n                                                        </t>\n                                                    </div>\n                                                </div>\n                                            </t>\n                                            <t t-if=\"record.display_type.raw_value === ''line_section'' || record.display_type.raw_value === ''line_note''\">\n                                                <div class=\"row\">\n                                                    <div class=\"col-12\">\n                                                        <t t-out=\"record.name.value\"/>\n                                                    </div>\n                                                </div>\n                                            </t>\n                                        </div>\n                                    </t>\n                                </templates>\n                            </kanban>\n                        </field>\n                        <div class=\"float-end d-flex gap-1 mb-2 ms-1\" name=\"so_button_below_order_lines\">\n                            <button string=\"Discount\" name=\"action_open_discount_wizard\" type=\"object\" class=\"btn btn-secondary\" groups=\"product.group_discount_per_so_line\"/>\n                        </div>\n                        <group name=\"note_group\" col=\"6\" class=\"mt-2 mt-md-0\">\n                            <group colspan=\"4\">\n                                <field colspan=\"2\" name=\"note\" nolabel=\"1\" placeholder=\"Terms and conditions...\"/>\n                            </group>\n                            <group class=\"oe_subtotal_footer\" colspan=\"2\" name=\"sale_total\">\n                                <field name=\"tax_totals\" widget=\"account-tax-totals-field\" nolabel=\"1\" colspan=\"2\" readonly=\"1\"/>\n                            </group>\n                            <div class=\"clearfix\"/>\n                        </group>\n                    </page>\n                    <page string=\"Other Info\" name=\"other_information\">\n                        <group>\n                            <group name=\"sales_person\" string=\"Sales\">\n                                <field name=\"user_id\" widget=\"many2one_avatar_user\"/>\n                                <field name=\"team_id\" context=\"{''kanban_view_ref'': ''sales_team.crm_team_view_kanban''}\" options=\"{''no_create'': True}\"/>\n                                <field name=\"company_id\" options=\"{''no_create'': True}\" groups=\"base.group_multi_company\"/>\n                                <field name=\"require_signature\" readonly=\"state in [''cancel'', ''sale'']\"/>\n                                <label for=\"require_payment\"/>\n                                <div id=\"require_payment\">\n                                    <field name=\"require_payment\" readonly=\"state in [''cancel'', ''sale'']\"/>\n                                    <span class=\"mx-3\" invisible=\"not require_payment\">of</span>\n                                    <field name=\"prepayment_percent\" readonly=\"state in [''cancel'', ''sale'']\" invisible=\"not require_payment\" widget=\"percentage\" style=\"width: 3rem\"/>\n                                </div>\n                                <field name=\"reference\" readonly=\"1\" invisible=\"not reference\"/>\n                                <field name=\"client_order_ref\"/>\n                                <field name=\"tag_ids\" widget=\"many2many_tags\" options=\"{''color_field'': ''color'', ''no_create_edit'': True}\"/>\n                            </group>\n                            <group name=\"sale_info\" string=\"Invoicing\">\n                                <field name=\"show_update_fpos\" invisible=\"1\"/>\n                                <label for=\"fiscal_position_id\"/>\n                                <div class=\"o_row\">\n                                    <field name=\"fiscal_position_id\" options=\"{''no_create'': True}\"/>\n                                    <button name=\"action_update_taxes\" type=\"object\" string=\" Update Taxes\" help=\"Recompute all taxes based on this fiscal position\" class=\"btn-link mb-1 px-0\" icon=\"fa-refresh\" confirm=\"This will update all taxes based on the currently selected fiscal position.\" invisible=\"not show_update_fpos or state in [''sale'', ''cancel'']\"/>\n                                </div>\n                                <field name=\"partner_invoice_id\" groups=\"!account.group_delivery_invoice_address\" invisible=\"1\"/>\n                                <field name=\"analytic_account_id\" context=\"{''default_partner_id'':partner_invoice_id, ''default_name'':name}\" readonly=\"invoice_count != 0 and state == ''sale''\" groups=\"analytic.group_analytic_accounting\" force_save=\"1\"/>\n                                <field name=\"journal_id\" groups=\"base.group_no_one\" readonly=\"invoice_count != 0 and state == ''sale''\"/>\n                                <field name=\"invoice_status\" invisible=\"state != ''sale''\" groups=\"base.group_no_one\"/>\n                                <!-- test_event_configurator -->\n                                <field name=\"invoice_status\" invisible=\"1\" groups=\"!base.group_no_one\"/>\n                            </group>\n                            <group name=\"sale_shipping\" string=\"Shipping\">\n                                <label for=\"commitment_date\" string=\"Delivery Date\"/>\n                                <div name=\"commitment_date_div\" class=\"o_row\">\n                                    <field name=\"commitment_date\" readonly=\"state == ''cancel'' or locked\"/>\n                                    <span name=\"expected_date_span\" class=\"text-muted\">Expected: <field name=\"expected_date\" class=\"oe_inline\" widget=\"date\"/></span>\n                                </div>\n                            </group>\n                            <group string=\"Tracking\" name=\"sale_reporting\">\n                                <field name=\"origin\"/>\n                                <field name=\"campaign_id\" options=\"{''create_name_field'': ''title''}\"/>\n                                <field name=\"medium_id\"/>\n                                <field name=\"source_id\"/>\n                            </group>\n                        </group>\n                    </page>\n                    <page groups=\"base.group_no_one\" string=\"Customer Signature\" name=\"customer_signature\" invisible=\"not require_signature and not signed_by and not signature and not signed_on\">\n                        <group>\n                            <field name=\"signed_by\" readonly=\"signature\"/>\n                            <field name=\"signed_on\" readonly=\"signature\"/>\n                            <field name=\"signature\" widget=\"image\"/>\n                        </group>\n                    </page>\n                </notebook>\n            </sheet>\n            <div class=\"oe_chatter\">\n                <field name=\"message_follower_ids\"/>\n                <field name=\"activity_ids\"/>\n                <field name=\"message_ids\"/>\n            </div>\n            </form>"}', '<?xml version="1.0"?>
<form string="Sales Order" class="o_sale_order">
            <header>
                <field name="locked" invisible="1"/>
                <field name="authorized_transaction_ids" invisible="1"/>
                <button name="payment_action_capture" type="object" data-hotkey="shift+g" string="Capture Transaction" class="oe_highlight" invisible="not authorized_transaction_ids"/>
                <button name="payment_action_void" type="object" string="Void Transaction" data-hotkey="shift+v" confirm="Are you sure you want to void the authorized transaction? This action can''t be undone." invisible="not authorized_transaction_ids"/>
                <button id="create_invoice" name="313" string="Create Invoice" type="action" class="btn-primary" data-hotkey="q" invisible="invoice_status != ''to invoice''"/>
                <button id="create_invoice_percentage" name="313" string="Create Invoice" type="action" context="{''default_advance_payment_method'': ''percentage''}" data-hotkey="q" invisible="invoice_status != ''no'' or state != ''sale''"/>
                <button name="action_quotation_send" id="send_by_email_primary" string="Send by Email" type="object" data-hotkey="g" invisible="state != ''draft''" class="btn-primary" context="{''validate_analytic'': True}"/>
                <button name="action_quotation_send" id="send_proforma_primary" type="object" string="Send PRO-FORMA Invoice" class="btn-primary" groups="sale.group_proforma_sales" invisible="state != ''draft'' or invoice_count &gt;= 1" context="{''proforma'': True, ''validate_analytic'': True}"/>
                <button name="action_confirm" id="action_confirm" data-hotkey="q" string="Confirm" class="btn-primary" type="object" context="{''validate_analytic'': True}" invisible="state != ''sent''"/>
                <button name="action_confirm" data-hotkey="q" string="Confirm" type="object" context="{''validate_analytic'': True}" invisible="state != ''draft''"/>
                <button name="action_quotation_send" id="send_proforma" type="object" string="Send PRO-FORMA Invoice" groups="sale.group_proforma_sales" invisible="state == ''draft'' or invoice_count &gt;= 1" context="{''proforma'': True, ''validate_analytic'': True}"/>
                <button name="action_quotation_send" id="send_by_email" string="Send by Email" type="object" invisible="state not in (''sent'', ''sale'')" data-hotkey="g" context="{''validate_analytic'': True}"/>

                <!-- allow to unlock locked orders even if setting is not enabled (e.g. orders synchronized from connectors) -->
                <button name="action_unlock" type="object" string="Unlock" invisible="not locked" groups="sales_team.group_sale_manager"/>
                <button name="action_preview_sale_order" string="Preview" type="object" class="btn-secondary"/>
                <button name="action_cancel" type="object" string="Cancel" invisible="state not in [''draft'', ''sent'', ''sale''] or not id or locked" data-hotkey="x"/>
                <button name="action_draft" invisible="state != ''cancel''" type="object" string="Set to Quotation" data-hotkey="w"/>
                <t groups="sale.group_auto_done_setting">
                    <button name="action_lock" type="object" string="Lock" help="If the sale is locked, you can not modify it anymore. However, you will still be able to invoice or deliver." invisible="locked or state != ''sale''" groups="sales_team.group_sale_manager"/>
                </t>
                <field name="state" widget="statusbar" statusbar_visible="draft,sent,sale"/>
            </header>
            <div class="alert alert-warning" role="alert" invisible="partner_credit_warning == ''''">
                <field name="partner_credit_warning"/>
            </div>
            <sheet>
                <div class="oe_button_box" name="button_box">
                    <button name="action_view_invoice" type="object" class="oe_stat_button" icon="fa-pencil-square-o" invisible="invoice_count == 0">
                        <field name="invoice_count" widget="statinfo" string="Invoices"/>
                    </button>
                </div>
                <div class="badge rounded-pill text-bg-secondary float-end fs-6 border-0" invisible="not locked">
                    <i class="fa fa-lock"/>
                    Locked
                </div>
                <div class="oe_title">
                    <h1>
                        <field name="name" readonly="1"/>
                    </h1>
                </div>
                <group name="sale_header">
                    <group name="partner_details">
                        <field name="partner_id" widget="res_partner_many2one" context="{''res_partner_search_mode'': ''customer'', ''show_address'': 1, ''show_vat'': True}" placeholder="Type to find a customer..." readonly="state in [''cancel'', ''sale'']"/>
                        <field name="partner_invoice_id" groups="account.group_delivery_invoice_address" context="{''default_type'':''invoice'', ''show_address'': False, ''show_vat'': False}" readonly="state == ''cancel'' or locked"/>
                        <field name="partner_shipping_id" groups="account.group_delivery_invoice_address" context="{''default_type'':''delivery'', ''show_address'': False, ''show_vat'': False}" readonly="state == ''cancel'' or locked"/>
                    </group>
                    <group name="order_details">
                        <field name="validity_date" invisible="state == ''sale''" readonly="state in [''cancel'', ''sale'']"/>
                        <div class="o_td_label" groups="base.group_no_one" invisible="state in [''sale'', ''cancel'']">
                            <label for="date_order" string="Quotation Date"/>
                        </div>
                        <field name="date_order" nolabel="1" groups="base.group_no_one" invisible="state in [''sale'', ''cancel'']" readonly="state in [''cancel'', ''sale'']"/>
                        <div class="o_td_label" invisible="state in [''draft'', ''sent'']">
                            <label for="date_order" string="Order Date"/>
                        </div>
                        <field name="date_order" invisible="state in [''draft'', ''sent'']" readonly="state in [''cancel'', ''sale'']" nolabel="1"/>
                        <field name="has_active_pricelist" invisible="1"/>
                        <field name="show_update_pricelist" invisible="1"/>
                        <label for="pricelist_id" groups="product.group_product_pricelist" invisible="not has_active_pricelist"/>
                        <div groups="product.group_product_pricelist" class="o_row" invisible="not has_active_pricelist">
                            <field name="pricelist_id" options="{''no_open'':True,''no_create'': True}" readonly="state in [''cancel'', ''sale'']"/>
                            <button name="action_update_prices" type="object" string=" Update Prices" help="Recompute all prices based on this pricelist" class="btn-link mb-1 px-0" icon="fa-refresh" confirm="This will update the unit price of all products based on the new pricelist." invisible="not show_update_pricelist or state in [''sale'', ''cancel'']"/>
                        </div>
                        <field name="country_code" invisible="1"/>
                        <field name="company_id" invisible="1"/>
                        <field name="currency_id" invisible="1"/>
                        <field name="pricelist_id" invisible="1" readonly="state in [''cancel'', ''sale'']" groups="!product.group_product_pricelist"/>
                        <field name="tax_country_id" invisible="1"/>
                        <field name="tax_calculation_rounding_method" invisible="1"/>
                        <field name="payment_term_id" options="{''no_open'': True, ''no_create'': True}"/>
                    </group>
                </group>
                <notebook>
                    <page string="Order Lines" name="order_lines">
                        <field name="order_line" widget="section_and_note_one2many" mode="tree,kanban" readonly="state == ''cancel'' or locked">
                            <form>
                                <field name="display_type" invisible="1"/>
                                <!--
                                    We need the sequence field to be here for new lines to be added at the correct position.
                                    TODO: at some point we want to fix this in the framework so that an invisible field is not required.
                                -->
                                <field name="sequence" invisible="1"/>
                                <field name="product_uom_category_id" invisible="1"/>
                                <group>
                                    <group invisible="display_type">
                                        <field name="product_updatable" invisible="1"/>
                                        <field name="product_id" domain="[(''sale_ok'', ''='', True)]" context="{''partner_id'':parent.partner_id, ''quantity'':product_uom_qty, ''pricelist'':parent.pricelist_id, ''uom'':product_uom, ''company_id'': parent.company_id}" readonly="not product_updatable" required="not display_type" force_save="1" widget="many2one_barcode"/>
                                        <field name="product_type" invisible="1"/>
                                        <field name="invoice_status" invisible="1"/>
                                        <field name="qty_to_invoice" invisible="1"/>
                                        <field name="qty_delivered_method" invisible="1"/>
                                        <field name="price_total" invisible="1"/>
                                        <field name="price_tax" invisible="1"/>
                                        <field name="price_subtotal" invisible="1"/>
                                        <field name="product_uom_readonly" invisible="1"/>
                                        <label for="product_uom_qty"/>
                                        <div class="o_row" name="ordered_qty">
                                            <field context="{''partner_id'':parent.partner_id, ''quantity'':product_uom_qty, ''pricelist'':parent.pricelist_id, ''uom'':product_uom, ''uom_qty_change'':True, ''company_id'': parent.company_id}" name="product_uom_qty"/>
                                            <field name="product_uom" invisible="1" groups="!uom.group_uom"/>
                                            <field name="product_uom" force_save="1" groups="uom.group_uom" class="oe_no_button" readonly="product_uom_readonly" required="not display_type"/>
                                        </div>
                                        <label for="qty_delivered" string="Delivered" invisible="parent.state != ''sale''"/>
                                        <div name="delivered_qty" invisible="parent.state != ''sale''">
                                            <field name="qty_delivered" readonly="qty_delivered_method != ''manual''"/>
                                        </div>
                                        <label for="qty_invoiced" string="Invoiced" invisible="parent.state != ''sale''"/>
                                        <div name="invoiced_qty" invisible="parent.state != ''sale''">
                                            <field name="qty_invoiced"/>
                                        </div>
                                        <field name="product_packaging_qty" invisible="not product_id or not product_packaging_id" groups="product.group_stock_packaging"/>
                                        <field name="product_packaging_id" invisible="not product_id" context="{''default_product_id'': product_id, ''tree_view_ref'':''product.product_packaging_tree_view'', ''form_view_ref'':''product.product_packaging_form_view''}" groups="product.group_stock_packaging"/>
                                        <field name="price_unit"/>
                                        <field name="tax_id" widget="many2many_tags" options="{''no_create'': True}" context="{''search_view_ref'': ''account.account_tax_view_search''}" domain="[(''type_tax_use'', ''='', ''sale''), (''company_id'', ''parent_of'', parent.company_id), (''country_id'', ''='', parent.tax_country_id)]" readonly="qty_invoiced &gt; 0"/>
                                        <t groups="product.group_discount_per_so_line">
                                            <label for="discount"/>
                                            <div name="discount">
                                                <field name="discount" class="oe_inline"/> %
                                            </div>
                                        </t>
                                        <!--
                                            We need the sequence field to be here
                                            because we want to be able to overwrite the default sequence value in the JS
                                            in order for new lines to be added at the correct position.
                                            NOTE: at some point we want to fix this in the framework so that an invisible field is not required.
                                        -->
                                        <field name="sequence" invisible="1"/>
                                    </group>
                                    <group invisible="display_type">
                                        <label for="customer_lead"/>
                                        <div name="lead">
                                            <field name="customer_lead" class="oe_inline"/> days
                                        </div>
                                        <field name="analytic_distribution" widget="analytic_distribution" groups="analytic.group_analytic_accounting" options="{''product_field'': ''product_id'', ''business_domain'': ''sale_order''}"/>
                                    </group>
                                </group>
                                <label for="name" string="Description" invisible="display_type"/>
                                <label for="name" string="Section Name (eg. Products, Services)" invisible="display_type != ''line_section''"/>
                                <label for="name" string="Note" invisible="display_type != ''line_note''"/>
                                <field name="name"/>
                                <div name="invoice_lines" groups="base.group_no_one" invisible="display_type">
                                    <label for="invoice_lines"/>
                                    <field name="invoice_lines"/>
                                </div>
                                <field name="state" invisible="1"/>
                                <field name="company_id" invisible="1"/>
                            </form>
                            <tree string="Sales Order Lines" editable="bottom" limit="200">
                                <control>
                                    <create name="add_product_control" string="Add a product"/>
                                    <create name="add_section_control" string="Add a section" context="{''default_display_type'': ''line_section''}"/>
                                    <create name="add_note_control" string="Add a note" context="{''default_display_type'': ''line_note''}"/>
                                    <button name="action_add_from_catalog" string="Catalog" type="object" class="px-4 btn-link" context="{''order_id'': parent.id}"/>
                                </control>

                                <field name="sequence" widget="handle"/>
                                <!-- We do not display the type because we don''t want the user to be bothered with that information if he has no section or note. -->
                                <field name="display_type" column_invisible="True"/>
                                <field name="product_uom_category_id" column_invisible="True"/>
                                <field name="product_type" column_invisible="True"/>
                                <field name="product_updatable" column_invisible="True"/>
                                <field name="is_downpayment" column_invisible="True"/>
                                <field name="product_id" readonly="not product_updatable" required="not display_type" force_save="1" context="{                                         ''partner_id'': parent.partner_id,                                         ''quantity'': product_uom_qty,                                         ''pricelist'': parent.pricelist_id,                                         ''uom'':product_uom,                                         ''company_id'': parent.company_id,                                         ''default_lst_price'': price_unit,                                         ''default_description_sale'': name                                     }" options="{                                         ''no_open'': True,                                     }" domain="[(''sale_ok'', ''='', True)]" widget="sol_product_many2one"/>
                                <field name="product_template_id" string="Product" column_invisible="True" readonly="not product_updatable" required="not display_type" context="{                                         ''partner_id'': parent.partner_id,                                         ''quantity'': product_uom_qty,                                         ''pricelist'': parent.pricelist_id,                                         ''uom'':product_uom,                                         ''company_id'': parent.company_id,                                         ''default_list_price'': price_unit,                                         ''default_description_sale'': name                                     }" options="{                                         ''no_open'': True,                                     }" domain="[(''sale_ok'', ''='', True)]" widget="sol_product_many2one" placeholder="Type to find a product..."/>
                                <field name="name" widget="section_and_note_text" optional="show"/>
                                <field name="analytic_distribution" widget="analytic_distribution" optional="hide" groups="analytic.group_analytic_accounting" options="{''product_field'': ''product_id'', ''business_domain'': ''sale_order'', ''amount_field'': ''price_subtotal''}"/>
                                <field name="product_uom_qty" decoration-info="(not display_type and invoice_status == ''to invoice'')" decoration-bf="(not display_type and invoice_status == ''to invoice'')" context="{                                         ''partner_id'': parent.partner_id,                                         ''quantity'': product_uom_qty,                                         ''pricelist'': parent.pricelist_id,                                         ''uom'': product_uom,                                         ''company_id'': parent.company_id                                     }" readonly="is_downpayment"/>
                                <field name="qty_delivered" decoration-info="(not display_type and invoice_status == ''to invoice'')" decoration-bf="(not display_type and invoice_status == ''to invoice'')" string="Delivered" column_invisible="parent.state != ''sale''" readonly="qty_delivered_method != ''manual'' or is_downpayment" optional="show"/>
                                <field name="qty_delivered_method" column_invisible="True"/>
                                <field name="qty_invoiced" decoration-info="(not display_type and invoice_status == ''to invoice'')" decoration-bf="(not display_type and invoice_status == ''to invoice'')" string="Invoiced" column_invisible="parent.state != ''sale''" optional="show"/>
                                <field name="qty_to_invoice" column_invisible="True"/>
                                <field name="product_uom_readonly" column_invisible="True"/>
                                <field name="product_uom" column_invisible="True" groups="!uom.group_uom"/>
                                <field name="product_uom" force_save="1" string="UoM" readonly="product_uom_readonly" required="not display_type" context="{''company_id'': parent.company_id}" groups="uom.group_uom" options="{&quot;no_open&quot;: True}" optional="show"/>
                                <field name="customer_lead" optional="hide" readonly="parent.state not in [''draft'', ''sent'', ''sale''] or is_downpayment"/>
                                <field name="product_packaging_qty" invisible="not product_id or not product_packaging_id" groups="product.group_stock_packaging" optional="show"/>
                                <field name="product_packaging_id" invisible="not product_id" context="{''default_product_id'': product_id, ''tree_view_ref'':''product.product_packaging_tree_view'', ''form_view_ref'':''product.product_packaging_form_view''}" groups="product.group_stock_packaging" optional="show"/>
                                <field name="price_unit" readonly="qty_invoiced &gt; 0"/>
                                <field name="tax_id" widget="many2many_tags" options="{''no_create'': True}" domain="[(''type_tax_use'', ''='', ''sale''), (''company_id'', ''parent_of'', parent.company_id), (''country_id'', ''='', parent.tax_country_id)]" context="{''active_test'': True}" readonly="qty_invoiced &gt; 0 or is_downpayment" optional="show"/>
                                <field name="discount" string="Disc.%" groups="product.group_discount_per_so_line" optional="show"/>
                                <field name="is_downpayment" column_invisible="True"/>
                                <field name="price_subtotal" string="Tax excl." invisible="is_downpayment"/>
                                <field name="price_total" string="Tax incl." column_invisible="parent.tax_calculation_rounding_method == ''round_globally''" invisible="is_downpayment" optional="hide"/>
                                <!-- Others fields -->
                                <field name="tax_calculation_rounding_method" column_invisible="True"/>
                                <field name="state" column_invisible="True"/>
                                <field name="invoice_status" column_invisible="True"/>
                                <field name="currency_id" column_invisible="True"/>
                                <field name="price_tax" column_invisible="True"/>
                                <field name="company_id" column_invisible="True"/>
                            </tree>
                            <kanban class="o_kanban_mobile">
                                <field name="name"/>
                                <field name="product_id"/>
                                <field name="product_uom_qty"/>
                                <field name="product_uom"/>
                                <field name="price_subtotal"/>
                                <field name="price_total"/>
                                <field name="price_tax"/>
                                <field name="price_total"/>
                                <field name="price_unit"/>
                                <field name="display_type"/>
                                <field name="tax_id"/>
                                <field name="company_id"/>
                                <field name="tax_calculation_rounding_method"/>
                                <control>
                                    <create name="add_product_control" string="Add a product"/>
                                    <create name="add_section_control" string="Add a section" context="{''default_display_type'': ''line_section''}"/>
                                    <create name="add_note_control" string="Add a note" context="{''default_display_type'': ''line_note''}"/>
                                    <button name="action_add_from_catalog" context="{''order_id'': parent.id}" string="Catalog" type="object" class="btn-secondary"/>
                                </control>
                                <templates>
                                    <t t-name="kanban-box">
                                        <div t-attf-class="oe_kanban_card oe_kanban_global_click ps-0 pe-0 {{ record.display_type.raw_value ? ''o_is_'' + record.display_type.raw_value : '''' }}">
                                            <t t-if="!record.display_type.raw_value">
                                                <div class="row g-0">
                                                    <div class="col-2 pe-3">
                                                        <img t-att-src="kanban_image(''product.product'', ''image_128'', record.product_id.raw_value)" t-att-title="record.product_id.value" t-att-alt="record.product_id.value" style="max-width: 100%;"/>
                                                    </div>
                                                    <div class="col-10">
                                                        <div class="row">
                                                            <div class="col">
                                                                <strong t-out="record.product_id.value"/>
                                                            </div>
                                                            <div class="col-auto">
                                                                <strong>Tax excl.: </strong>
                                                                <t t-set="line_price" t-value="record.price_subtotal.value"/>
                                                                <strong class="float-end text-end" t-out="line_price"/>
                                                            </div>
                                                        </div>
                                                        <div class="row">
                                                            <div class="col-12 text-muted">
                                                                Quantity:
                                                                <t t-out="record.product_uom_qty.value"/> <t t-out="record.product_uom.value"/>
                                                            </div>
                                                        </div>
                                                        <div class="row">
                                                            <div class="col text-muted">
                                                                Unit Price:
                                                                <t t-out="record.price_unit.value"/>
                                                            </div>
                                                            <div class="col-auto" t-if="record.tax_calculation_rounding_method.raw_value === ''round_per_line''">
                                                                <strong>Tax incl.: </strong>
                                                                <t t-set="line_price" t-value="record.price_total.value"/>
                                                                <strong class="float-end text-end" t-out="line_price"/>
                                                            </div>
                                                        </div>
                                                        <t t-if="record.discount?.raw_value">
                                                            <div class="row">
                                                                <div class="col-12 text-muted">
                                                                    Discount:
                                                                    <t t-out="record.discount.value"/>%
                                                                </div>
                                                            </div>
                                                        </t>
                                                    </div>
                                                </div>
                                            </t>
                                            <t t-if="record.display_type.raw_value === ''line_section'' || record.display_type.raw_value === ''line_note''">
                                                <div class="row">
                                                    <div class="col-12">
                                                        <t t-out="record.name.value"/>
                                                    </div>
                                                </div>
                                            </t>
                                        </div>
                                    </t>
                                </templates>
                            </kanban>
                        </field>
                        <div class="float-end d-flex gap-1 mb-2 ms-1" name="so_button_below_order_lines">
                            <button string="Discount" name="action_open_discount_wizard" type="object" class="btn btn-secondary" groups="product.group_discount_per_so_line"/>
                        </div>
                        <group name="note_group" col="6" class="mt-2 mt-md-0">
                            <group colspan="4">
                                <field colspan="2" name="note" nolabel="1" placeholder="Terms and conditions..."/>
                            </group>
                            <group class="oe_subtotal_footer" colspan="2" name="sale_total">
                                <field name="tax_totals" widget="account-tax-totals-field" nolabel="1" colspan="2" readonly="1"/>
                            </group>
                            <div class="clearfix"/>
                        </group>
                    </page>
                    <page string="Other Info" name="other_information">
                        <group>
                            <group name="sales_person" string="Sales">
                                <field name="user_id" widget="many2one_avatar_user"/>
                                <field name="team_id" context="{''kanban_view_ref'': ''sales_team.crm_team_view_kanban''}" options="{''no_create'': True}"/>
                                <field name="company_id" options="{''no_create'': True}" groups="base.group_multi_company"/>
                                <field name="require_signature" readonly="state in [''cancel'', ''sale'']"/>
                                <label for="require_payment"/>
                                <div id="require_payment">
                                    <field name="require_payment" readonly="state in [''cancel'', ''sale'']"/>
                                    <span class="mx-3" invisible="not require_payment">of</span>
                                    <field name="prepayment_percent" readonly="state in [''cancel'', ''sale'']" invisible="not require_payment" widget="percentage" style="width: 3rem"/>
                                </div>
                                <field name="reference" readonly="1" invisible="not reference"/>
                                <field name="client_order_ref"/>
                                <field name="tag_ids" widget="many2many_tags" options="{''color_field'': ''color'', ''no_create_edit'': True}"/>
                            </group>
                            <group name="sale_info" string="Invoicing">
                                <field name="show_update_fpos" invisible="1"/>
                                <label for="fiscal_position_id"/>
                                <div class="o_row">
                                    <field name="fiscal_position_id" options="{''no_create'': True}"/>
                                    <button name="action_update_taxes" type="object" string=" Update Taxes" help="Recompute all taxes based on this fiscal position" class="btn-link mb-1 px-0" icon="fa-refresh" confirm="This will update all taxes based on the currently selected fiscal position." invisible="not show_update_fpos or state in [''sale'', ''cancel'']"/>
                                </div>
                                <field name="partner_invoice_id" groups="!account.group_delivery_invoice_address" invisible="1"/>
                                <field name="analytic_account_id" context="{''default_partner_id'':partner_invoice_id, ''default_name'':name}" readonly="invoice_count != 0 and state == ''sale''" groups="analytic.group_analytic_accounting" force_save="1"/>
                                <field name="journal_id" groups="base.group_no_one" readonly="invoice_count != 0 and state == ''sale''"/>
                                <field name="invoice_status" invisible="state != ''sale''" groups="base.group_no_one"/>
                                <!-- test_event_configurator -->
                                <field name="invoice_status" invisible="1" groups="!base.group_no_one"/>
                            </group>
                            <group name="sale_shipping" string="Shipping">
                                <label for="commitment_date" string="Delivery Date"/>
                                <div name="commitment_date_div" class="o_row">
                                    <field name="commitment_date" readonly="state == ''cancel'' or locked"/>
                                    <span name="expected_date_span" class="text-muted">Expected: <field name="expected_date" class="oe_inline" widget="date"/></span>
                                </div>
                            </group>
                            <group string="Tracking" name="sale_reporting">
                                <field name="origin"/>
                                <field name="campaign_id" options="{''create_name_field'': ''title''}"/>
                                <field name="medium_id"/>
                                <field name="source_id"/>
                            </group>
                        </group>
                    </page>
                    <page groups="base.group_no_one" string="Customer Signature" name="customer_signature" invisible="not require_signature and not signed_by and not signature and not signed_on">
                        <group>
                            <field name="signed_by" readonly="signature"/>
                            <field name="signed_on" readonly="signature"/>
                            <field name="signature" widget="image"/>
                        </group>
                    </page>
                </notebook>
            </sheet>
            <div class="oe_chatter">
                <field name="message_follower_ids"/>
                <field name="activity_ids"/>
                <field name="message_ids"/>
            </div>
            </form>
        ', false, true, '2026-05-10 01:12:05.269262', '2026-05-10 01:12:05.269262', false);
INSERT INTO public.ir_ui_view VALUES (884, 15, NULL, 1, 1, 'sale.order.list.select', 'sale.order', NULL, 'search', 'sale/views/sale_order_views.xml', 'primary', '{"en_US": "<search string=\"Search Sales Order\">\n                <field name=\"name\" string=\"Order\" filter_domain=\"[''|'', ''|'', (''name'', ''ilike'', self), (''client_order_ref'', ''ilike'', self), (''partner_id'', ''child_of'', self)]\"/>\n                <field name=\"partner_id\" operator=\"child_of\"/>\n                <field name=\"user_id\"/>\n                <field name=\"team_id\" string=\"Sales Team\"/>\n                <field name=\"order_line\" string=\"Product\" filter_domain=\"[(''order_line.product_id'', ''ilike'', self)]\"/>\n                <field name=\"analytic_account_id\" groups=\"analytic.group_analytic_accounting\"/>\n                <!-- We only allow to search on the following sale order line fields (product, name) because the other fields, such as price, quantity, ...\n                    will not be searched as often, and if they need to be searched it''s usually in the context of products\n                    and then they can be searched from the page listing the sale order lines related to a product (from the product itself).\n                -->\n                <filter string=\"My Orders\" domain=\"[(''user_id'', ''='', uid)]\" name=\"my_sale_orders_filter\"/>\n                <filter invisible=\"1\" string=\"Late Activities\" name=\"activities_overdue\" domain=\"[(''my_activity_date_deadline'', ''&lt;'', context_today().strftime(''%Y-%m-%d''))]\" help=\"Show all records which has next action date is before today\"/>\n                <filter invisible=\"1\" string=\"Today Activities\" name=\"activities_today\" domain=\"[(''my_activity_date_deadline'', ''='', context_today().strftime(''%Y-%m-%d''))]\"/>\n                <filter invisible=\"1\" string=\"Future Activities\" name=\"activities_upcoming_all\" domain=\"[(''my_activity_date_deadline'', ''&gt;'', context_today().strftime(''%Y-%m-%d''))]\"/>\n                <group expand=\"0\" string=\"Group By\">\n                    <filter string=\"Salesperson\" name=\"salesperson\" domain=\"[]\" context=\"{''group_by'': ''user_id''}\"/>\n                    <filter name=\"customer\" string=\"Customer\" domain=\"[]\" context=\"{''group_by'': ''partner_id''}\"/>\n                    <filter string=\"Order Date\" name=\"order_month\" domain=\"[]\" context=\"{''group_by'': ''date_order''}\"/>\n                </group>\n            </search>"}', '<?xml version="1.0"?>
<search string="Search Sales Order">
                <field name="name" string="Order" filter_domain="[''|'', ''|'', (''name'', ''ilike'', self), (''client_order_ref'', ''ilike'', self), (''partner_id'', ''child_of'', self)]"/>
                <field name="partner_id" operator="child_of"/>
                <field name="user_id"/>
                <field name="team_id" string="Sales Team"/>
                <field name="order_line" string="Product" filter_domain="[(''order_line.product_id'', ''ilike'', self)]"/>
                <field name="analytic_account_id" groups="analytic.group_analytic_accounting"/>
                <!-- We only allow to search on the following sale order line fields (product, name) because the other fields, such as price, quantity, ...
                    will not be searched as often, and if they need to be searched it''s usually in the context of products
                    and then they can be searched from the page listing the sale order lines related to a product (from the product itself).
                -->
                <filter string="My Orders" domain="[(''user_id'', ''='', uid)]" name="my_sale_orders_filter"/>
                <filter invisible="1" string="Late Activities" name="activities_overdue" domain="[(''my_activity_date_deadline'', ''&lt;'', context_today().strftime(''%Y-%m-%d''))]" help="Show all records which has next action date is before today"/>
                <filter invisible="1" string="Today Activities" name="activities_today" domain="[(''my_activity_date_deadline'', ''='', context_today().strftime(''%Y-%m-%d''))]"/>
                <filter invisible="1" string="Future Activities" name="activities_upcoming_all" domain="[(''my_activity_date_deadline'', ''&gt;'', context_today().strftime(''%Y-%m-%d''))]"/>
                <group expand="0" string="Group By">
                    <filter string="Salesperson" name="salesperson" domain="[]" context="{''group_by'': ''user_id''}"/>
                    <filter name="customer" string="Customer" domain="[]" context="{''group_by'': ''partner_id''}"/>
                    <filter string="Order Date" name="order_month" domain="[]" context="{''group_by'': ''date_order''}"/>
                </group>
            </search>
        ', false, true, '2026-05-10 01:12:05.269262', '2026-05-10 01:12:05.269262', false);
INSERT INTO public.ir_ui_view VALUES (885, 16, 884, 1, 1, 'sale.order.search.inherit.quotation', 'sale.order', NULL, 'search', 'sale/views/sale_order_views.xml', 'primary', '{"en_US": "<filter name=\"my_sale_orders_filter\" position=\"replace\">\n                <field name=\"campaign_id\"/>\n                <separator/>\n                <filter string=\"My Quotations\" name=\"my_quotation\" domain=\"[(''user_id'', ''='', uid)]\"/>\n                <separator/>\n                <filter string=\"Quotations\" name=\"draft\" domain=\"[(''state'', ''in'', (''draft'', ''sent''))]\"/>\n                <filter string=\"Sales Orders\" name=\"sales\" domain=\"[(''state'', ''='', ''sale'')]\"/>\n                <separator/>\n                <filter string=\"Create Date\" name=\"filter_create_date\" date=\"create_date\"/>\n            </filter>"}', '<?xml version="1.0"?>
<filter name="my_sale_orders_filter" position="replace">
                <field name="campaign_id"/>
                <separator/>
                <filter string="My Quotations" name="my_quotation" domain="[(''user_id'', ''='', uid)]"/>
                <separator/>
                <filter string="Quotations" name="draft" domain="[(''state'', ''in'', (''draft'', ''sent''))]"/>
                <filter string="Sales Orders" name="sales" domain="[(''state'', ''='', ''sale'')]"/>
                <separator/>
                <filter string="Create Date" name="filter_create_date" date="create_date"/>
            </filter>
        ', false, true, '2026-05-10 01:12:05.269262', '2026-05-10 01:12:05.269262', false);
INSERT INTO public.ir_ui_view VALUES (886, 16, 884, 1, 1, 'sale.order.search.inherit.sale', 'sale.order', NULL, 'search', 'sale/views/sale_order_views.xml', 'primary', '{"en_US": "<filter name=\"my_sale_orders_filter\" position=\"after\">\n                <separator/>\n                <filter string=\"To Invoice\" name=\"to_invoice\" domain=\"[(''invoice_status'',''='',''to invoice'')]\"/>\n                <filter string=\"To Upsell\" name=\"upselling\" domain=\"[(''invoice_status'',''='',''upselling'')]\"/>\n                <separator/>\n                <filter string=\"Order Date\" name=\"order_date\" date=\"date_order\"/>\n            </filter>"}', '<?xml version="1.0"?>
