        ', false, true, '2026-05-10 01:12:05.269262', '2026-05-10 01:12:05.269262', false);
INSERT INTO public.ir_ui_view VALUES (887, 16, 679, 1, 1, 'account.move.groupby', 'account.move', NULL, 'search', 'sale/views/account_views.xml', 'extension', '{"en_US": "<data><field name=\"invoice_user_id\" position=\"after\">\n                <field name=\"team_id\"/>\n            </field>\n            <xpath expr=\"//group/filter[@name=''status'']\" position=\"after\">\n                <filter string=\"Sales Team\" name=\"sales_channel\" domain=\"[]\" context=\"{''group_by'':''team_id''}\"/>\n            </xpath>\n        </data>"}', '<?xml version="1.0"?>
