INSERT INTO public.ir_ui_view VALUES (888, 16, 668, 1, 1, 'account.move.tree.inherit.sale', 'account.move', NULL, 'tree', 'sale/views/account_views.xml', 'extension', '{"en_US": "<field name=\"invoice_user_id\" position=\"after\">\n                <field name=\"team_id\" column_invisible=\"context.get(''default_move_type'') not in (''out_invoice'', ''out_refund'', ''out_receipt'')\" optional=\"hide\"/>\n            </field>"}', '<?xml version="1.0"?>
