INSERT INTO public.ir_ui_view VALUES (889, 16, 676, 1, 1, 'Account Invoice', 'account.move', NULL, 'form', 'sale/views/account_views.xml', 'extension', '{"en_US": "<data><xpath expr=\"//group[@name=''sale_info_group'']/field[@name=''invoice_user_id'']\" position=\"after\">\n                <field name=\"team_id\" context=\"{''kanban_view_ref'': ''sales_team.crm_team_view_kanban''}\"/>\n            </xpath>\n            <xpath expr=\"//group[@id=''other_tab_group'']\" position=\"inside\">\n                <group string=\"Marketing\" name=\"utm_link\" groups=\"base.group_no_one\" invisible=\"move_type not in (''out_invoice'', ''out_refund'')\">\n                    <field name=\"campaign_id\" options=\"{''create_name_field'': ''title''}\"/>\n                    <field name=\"medium_id\"/>\n                    <field name=\"source_id\"/>\n                </group>\n            </xpath>\n            <xpath expr=\"//div[@name=''button_box'']\" position=\"inside\">\n                <button class=\"oe_stat_button\" name=\"action_view_source_sale_orders\" type=\"object\" icon=\"fa-pencil-square-o\" invisible=\"sale_order_count == 0 or move_type not in (''out_invoice'', ''out_refund'', ''in_invoice'', ''in_refund'', ''out_receipt'', ''in_receipt'')\">\n                    <field string=\"Sale Orders\" name=\"sale_order_count\" widget=\"statinfo\"/>\n                </button>\n            </xpath>\n        </data>"}', '<?xml version="1.0"?>
<data><xpath expr="//group[@name=''sale_info_group'']/field[@name=''invoice_user_id'']" position="after">
                <field name="team_id" context="{''kanban_view_ref'': ''sales_team.crm_team_view_kanban''}"/>
            </xpath>
            <xpath expr="//group[@id=''other_tab_group'']" position="inside">
                <group string="Marketing" name="utm_link" groups="base.group_no_one" invisible="move_type not in (''out_invoice'', ''out_refund'')">
                    <field name="campaign_id" options="{''create_name_field'': ''title''}"/>
                    <field name="medium_id"/>
                    <field name="source_id"/>
                </group>
            </xpath>
            <xpath expr="//div[@name=''button_box'']" position="inside">
                <button class="oe_stat_button" name="action_view_source_sale_orders" type="object" icon="fa-pencil-square-o" invisible="sale_order_count == 0 or move_type not in (''out_invoice'', ''out_refund'', ''in_invoice'', ''in_refund'', ''out_receipt'', ''in_receipt'')">
                    <field string="Sale Orders" name="sale_order_count" widget="statinfo"/>
                </button>
