        </data>', false, true, '2026-05-10 01:12:05.269262', '2026-05-10 01:12:05.269262', false);
INSERT INTO public.ir_ui_view VALUES (890, 9, 520, 1, 1, 'crm.team.form', 'crm.team', NULL, 'form', 'sale/views/crm_team_views.xml', 'extension', '{"en_US": "<field name=\"company_id\" position=\"after\">\n                <label for=\"invoiced_target\"/>\n                <div class=\"o_row\">\n                    <field name=\"invoiced_target\" widget=\"monetary\" options=\"{''currency_field'': ''currency_id''}\" class=\"oe_inline\"/>\n                    <span class=\"flex-grow-1\">/ Month</span>\n                </div>\n            </field>"}', '<?xml version="1.0"?>
