        ', false, true, '2026-05-10 01:12:05.269262', '2026-05-10 01:12:05.269262', false);
INSERT INTO public.ir_ui_view VALUES (891, 16, 523, 1, 1, 'crm.team.view.kanban.dashboard.inherit.sale', 'crm.team', NULL, 'kanban', 'sale/views/crm_team_views.xml', 'extension', '{"en_US": "<data><xpath expr=\"//templates\" position=\"before\">\n                <field name=\"invoiced_target\"/>\n            </xpath>\n\n            <xpath expr=\"//t[@name=''second_options'']\" position=\"after\">\n                <div class=\"row\" t-if=\"record.quotations_count.raw_value\">\n                    <div class=\"col\">\n                        <a name=\"322\" type=\"action\" context=\"{''search_default_draft'': True, ''search_default_sent'': True}\">\n                            <field name=\"quotations_count\" class=\"me-1\"/>\n                            <t t-if=\"record.quotations_count.raw_value == 1\">Quotation</t>\n                            <t t-else=\"\">Quotations</t>\n                        </a>\n                    </div>\n                    <div class=\"col-auto text-truncate\">\n                        <field name=\"quotations_amount\" widget=\"monetary\"/>\n                    </div>\n                </div>\n                <div class=\"row\" name=\"orders_to_invoice\" t-if=\"record.sales_to_invoice_count.raw_value\">\n                    <div class=\"col-8\">\n                        <a name=\"325\" type=\"action\">\n                            <field name=\"sales_to_invoice_count\" class=\"me-1\"/>\n                            <t t-if=\"record.sales_to_invoice_count.raw_value == 1\">Order to Invoice</t>\n                            <t t-else=\"\">Orders to Invoice</t>\n                        </a>\n                    </div>\n                </div>\n            </xpath>\n\n            <xpath expr=\"//div[hasclass(''o_kanban_primary_bottom'')]\" position=\"after\">\n                <t groups=\"sales_team.group_sale_manager\">\n                    <div class=\"col-12 o_kanban_primary_bottom bottom_block\">\n                        <field name=\"invoiced\" widget=\"sales_team_progressbar\" title=\"Invoicing\" options=\"{''current_value'': ''invoiced'', ''max_value'': ''invoiced_target'', ''editable'': true, ''edit_max_value'': true, ''on_change'': ''update_invoiced_target''}\"/>\n                    </div>\n                </t>\n            </xpath>\n\n            <xpath expr=\"//div[hasclass(''o_kanban_manage_view'')]\" position=\"inside\">\n                <div>\n                    <a name=\"324\" type=\"action\">Sales Orders</a>\n                </div>\n                <div groups=\"account.group_account_invoice\">\n                    <a name=\"321\" type=\"action\">Invoices</a>\n                </div>\n            </xpath>\n\n            <div name=\"o_team_kanban_report_separator\" position=\"before\">\n                <div name=\"sales_report\">\n                    <a name=\"307\" type=\"action\">\n                        Sales\n                    </a>\n                </div>\n                <div groups=\"account.group_account_invoice\" name=\"invoices_report\">\n                    <a name=\"298\" type=\"action\">\n                        Invoices\n                    </a>\n                </div>\n            </div>\n        </data>"}', '<?xml version="1.0"?>
<data><xpath expr="//templates" position="before">
                <field name="invoiced_target"/>
            </xpath>

            <xpath expr="//t[@name=''second_options'']" position="after">
                <div class="row" t-if="record.quotations_count.raw_value">
                    <div class="col">
                        <a name="322" type="action" context="{''search_default_draft'': True, ''search_default_sent'': True}">
                            <field name="quotations_count" class="me-1"/>
                            <t t-if="record.quotations_count.raw_value == 1">Quotation</t>
                            <t t-else="">Quotations</t>
                        </a>
                    </div>
                    <div class="col-auto text-truncate">
                        <field name="quotations_amount" widget="monetary"/>
                    </div>
                </div>
                <div class="row" name="orders_to_invoice" t-if="record.sales_to_invoice_count.raw_value">
                    <div class="col-8">
                        <a name="325" type="action">
                            <field name="sales_to_invoice_count" class="me-1"/>
                            <t t-if="record.sales_to_invoice_count.raw_value == 1">Order to Invoice</t>
                            <t t-else="">Orders to Invoice</t>
                        </a>
                    </div>
                </div>
            </xpath>

            <xpath expr="//div[hasclass(''o_kanban_primary_bottom'')]" position="after">
                <t groups="sales_team.group_sale_manager">
                    <div class="col-12 o_kanban_primary_bottom bottom_block">
                        <field name="invoiced" widget="sales_team_progressbar" title="Invoicing" options="{''current_value'': ''invoiced'', ''max_value'': ''invoiced_target'', ''editable'': true, ''edit_max_value'': true, ''on_change'': ''update_invoiced_target''}"/>
                    </div>
                </t>
            </xpath>

            <xpath expr="//div[hasclass(''o_kanban_manage_view'')]" position="inside">
                <div>
                    <a name="324" type="action">Sales Orders</a>
                </div>
                <div groups="account.group_account_invoice">
                    <a name="321" type="action">Invoices</a>
                </div>
            </xpath>

            <div name="o_team_kanban_report_separator" position="before">
                <div name="sales_report">
                    <a name="307" type="action">
                        Sales
                    </a>
                </div>
                <div groups="account.group_account_invoice" name="invoices_report">
                    <a name="298" type="action">
                        Invoices
                    </a>
                </div>
            </div>
        </data>', false, true, '2026-05-10 01:12:05.269262', '2026-05-10 01:12:05.269262', false);
