INSERT INTO public.ir_ui_view VALUES (895, 16, 477, 1, 1, 'product.document.kanban.sale', 'product.document', NULL, 'kanban', 'sale/views/product_document_views.xml', 'extension', '{"en_US": "<div name=\"bottom\" position=\"inside\">\n                <div class=\"mt-2\">\n                    <span>Visibility</span>\n                    <field name=\"attached_on\" class=\"ms-2\" widget=\"selection\"/>\n                </div>\n            </div>"}', '<?xml version="1.0"?>
