INSERT INTO public.ir_ui_view VALUES (896, 16, 478, 1, 1, 'product.document.list.sale', 'product.document', NULL, 'tree', 'sale/views/product_document_views.xml', 'extension', '{"en_US": "<field name=\"name\" position=\"after\">\n                <field name=\"attached_on\"/>\n            </field>"}', '<?xml version="1.0"?>
