INSERT INTO public.ir_ui_view VALUES (901, 16, 460, 1, 1, 'product.product.sale.order', 'product.product', NULL, 'form', 'sale/views/product_views.xml', 'extension', '{"en_US": "<data><div name=\"button_box\" position=\"inside\">\n                <button class=\"oe_stat_button\" name=\"action_view_sales\" type=\"object\" icon=\"fa-signal\" help=\"Sold in the last 365 days\" groups=\"sales_team.group_sale_salesman\" invisible=\"not sale_ok\">\n                    <div class=\"o_field_widget o_stat_info\">\n                        <span class=\"o_stat_value d-flex gap-1\">\n                            <field name=\"sales_count\" widget=\"statinfo\" nolabel=\"1\" class=\"oe_inline\"/>\n                            <field name=\"uom_name\" class=\"oe_inline\"/>\n                        </span>\n                        <span class=\"o_stat_text\">Sold</span>\n                    </div>\n                </button>\n            </div>\n            <group name=\"description\" position=\"after\">\n                <t groups=\"sales_team.group_sale_salesman\">\n                    <group string=\"Warning when Selling this Product\" groups=\"sale.group_warning_sale\">\n                        <field name=\"sale_line_warn\" nolabel=\"1\" colspan=\"2\"/>\n                        <field name=\"sale_line_warn_msg\" colspan=\"2\" nolabel=\"1\" placeholder=\"Type a message...\" readonly=\"sale_line_warn == ''no-message''\" required=\"sale_line_warn != ''no-message''\"/>\n                    </group>\n                </t>\n            </group>\n        </data>"}', '<?xml version="1.0"?>
