INSERT INTO public.ir_ui_view VALUES (909, 16, NULL, 1, 1, 'sale.order.line.tree', 'sale.order.line', NULL, 'tree', 'sale/views/sale_order_line_views.xml', 'primary', '{"en_US": "<tree string=\"Sales Order Lines\" create=\"false\">\n                <field name=\"order_id\"/>\n                <field name=\"order_partner_id\"/>\n                <field name=\"name\"/>\n                <field name=\"salesman_id\"/>\n                <field name=\"product_uom_qty\" string=\"Qty\"/>\n                <field name=\"qty_delivered\"/>\n                <field name=\"qty_invoiced\"/>\n                <field name=\"qty_to_invoice\"/>\n                <field name=\"product_uom\" string=\"Unit of Measure\" groups=\"uom.group_uom\"/>\n                <field name=\"price_subtotal\" sum=\"Total\" widget=\"monetary\"/>\n                <field name=\"currency_id\" column_invisible=\"True\"/>\n            </tree>"}', '<?xml version="1.0"?>
<tree string="Sales Order Lines" create="false">
                <field name="order_id"/>
