                <field name="product_uom_qty" string="Qty"/>
                <field name="qty_delivered"/>
                <field name="qty_invoiced"/>
                <field name="qty_to_invoice"/>
                <field name="product_uom" string="Unit of Measure" groups="uom.group_uom"/>
                <field name="price_subtotal" sum="Total" widget="monetary"/>
                <field name="currency_id" column_invisible="True"/>
            </tree>
        ', false, true, '2026-05-10 01:12:05.269262', '2026-05-10 01:12:05.269262', false);
INSERT INTO public.ir_ui_view VALUES (910, 16, NULL, 1, 1, 'sale.order.line.form.readonly', 'sale.order.line', NULL, 'form', 'sale/views/sale_order_line_views.xml', 'primary', '{"en_US": "<form string=\"Sales Order Item\" edit=\"false\">\n                <field name=\"display_type\" invisible=\"1\"/>\n                <sheet>\n                    <div class=\"oe_title\">\n                        <h1>\n                            <field name=\"display_name\"/>\n                        </h1>\n                    </div>\n                    <group>\n                        <group>\n                            <field name=\"product_updatable\" invisible=\"1\"/>\n                            <field name=\"order_id\" readonly=\"1\" force_save=\"1\"/>\n                            <field name=\"product_uom_category_id\" invisible=\"1\"/>\n                            <field name=\"product_uom_readonly\" invisible=\"1\"/>\n                            <field name=\"qty_delivered_method\" invisible=\"1\"/>\n                            <field name=\"state\" invisible=\"1\"/>\n                            <field name=\"product_id\" readonly=\"id and not product_updatable\" required=\"not display_type\" force_save=\"1\" widget=\"many2one_barcode\"/>\n                            <field name=\"name\"/>\n                            <field name=\"product_uom_qty\"/>\n                            <field name=\"qty_delivered\" invisible=\"state not in [''sale'', ''done'']\" readonly=\"qty_delivered_method != ''manual''\"/>\n                            <field name=\"qty_invoiced\" invisible=\"state not in [''sale'', ''done'']\"/>\n                            <field name=\"product_uom\" force_save=\"1\" groups=\"uom.group_uom\" readonly=\"product_uom_readonly\" required=\"not display_type\"/>\n                            <field name=\"product_uom\" groups=\"!uom.group_uom\" invisible=\"1\"/>\n                            <field name=\"company_id\" options=\"{''no_create'': True}\" groups=\"base.group_multi_company\"/>\n                            <field name=\"order_partner_id\" invisible=\"1\"/>\n                            <field name=\"display_type\" invisible=\"1\"/>\n                            <field name=\"product_updatable\" invisible=\"1\"/>\n                        </group>\n                        <group>\n                            <field name=\"company_id\" invisible=\"1\"/>\n                            <field name=\"tax_country_id\" invisible=\"1\"/>\n                            <field name=\"price_unit\"/>\n                            <field name=\"discount\" groups=\"product.group_discount_per_so_line\"/>\n                            <field name=\"price_subtotal\" widget=\"monetary\"/>\n                            <field name=\"tax_id\" widget=\"many2many_tags\" options=\"{''no_create'': True}\" context=\"{''search_view_ref'': ''account.account_tax_view_search''}\" domain=\"[(''type_tax_use'', ''='', ''sale''), (''company_id'', ''='', company_id), (''country_id'', ''='', tax_country_id)]\" readonly=\"qty_invoiced &gt; 0\"/>\n                            <field name=\"price_tax\" widget=\"monetary\"/>\n                            <field name=\"price_total\" widget=\"monetary\"/>\n                            <field name=\"currency_id\" invisible=\"1\"/>\n                        </group>\n                    </group>\n                </sheet>\n            </form>"}', '<?xml version="1.0"?>
<form string="Sales Order Item" edit="false">
                <field name="display_type" invisible="1"/>
                <sheet>
                    <div class="oe_title">
                        <h1>
                            <field name="display_name"/>
                        </h1>
                    </div>
                    <group>
                        <group>
                            <field name="product_updatable" invisible="1"/>
                            <field name="order_id" readonly="1" force_save="1"/>
                            <field name="product_uom_category_id" invisible="1"/>
                            <field name="product_uom_readonly" invisible="1"/>
                            <field name="qty_delivered_method" invisible="1"/>
                            <field name="state" invisible="1"/>
                            <field name="product_id" readonly="id and not product_updatable" required="not display_type" force_save="1" widget="many2one_barcode"/>
                            <field name="name"/>
                            <field name="product_uom_qty"/>
                            <field name="qty_delivered" invisible="state not in [''sale'', ''done'']" readonly="qty_delivered_method != ''manual''"/>
                            <field name="qty_invoiced" invisible="state not in [''sale'', ''done'']"/>
                            <field name="product_uom" force_save="1" groups="uom.group_uom" readonly="product_uom_readonly" required="not display_type"/>
                            <field name="product_uom" groups="!uom.group_uom" invisible="1"/>
                            <field name="company_id" options="{''no_create'': True}" groups="base.group_multi_company"/>
                            <field name="order_partner_id" invisible="1"/>
                            <field name="display_type" invisible="1"/>
                            <field name="product_updatable" invisible="1"/>
                        </group>
                        <group>
                            <field name="company_id" invisible="1"/>
                            <field name="tax_country_id" invisible="1"/>
                            <field name="price_unit"/>
                            <field name="discount" groups="product.group_discount_per_so_line"/>
                            <field name="price_subtotal" widget="monetary"/>
                            <field name="tax_id" widget="many2many_tags" options="{''no_create'': True}" context="{''search_view_ref'': ''account.account_tax_view_search''}" domain="[(''type_tax_use'', ''='', ''sale''), (''company_id'', ''='', company_id), (''country_id'', ''='', tax_country_id)]" readonly="qty_invoiced &gt; 0"/>
                            <field name="price_tax" widget="monetary"/>
                            <field name="price_total" widget="monetary"/>
                            <field name="currency_id" invisible="1"/>
                        </group>
                    </group>
                </sheet>
            </form>
        ', false, true, '2026-05-10 01:12:05.269262', '2026-05-10 01:12:05.269262', false);
INSERT INTO public.ir_ui_view VALUES (1149, 16, 161, 1, 1, 'res.users.simple.form.inherit', 'res.users', NULL, 'form', 'sale_stock/views/res_users_views.xml', 'extension', '{"en_US": "<group name=\"phone_numbers\" position=\"after\">\n                    <group name=\"Warehouses\">\n                        <field name=\"property_warehouse_id\" groups=\"stock.group_stock_multi_warehouses\"/>\n                    </group>\n                </group>"}', '<?xml version="1.0"?>
