INSERT INTO public.ir_ui_view VALUES (911, 16, NULL, 1, 1, 'sale.order.line.select', 'sale.order.line', NULL, 'search', 'sale/views/sale_order_line_views.xml', 'primary', '{"en_US": "<search string=\"Search Sales Order\">\n                <filter string=\"To Invoice\" name=\"to_invoice\" domain=\"[(''qty_to_invoice'', ''!='', 0)]\" help=\"Sales Order Lines ready to be invoiced\"/>\n                <separator/>\n                <filter string=\"My Sales Order Lines\" name=\"my_sales_order_lines\" domain=\"[(''salesman_id'',''='',uid)]\" help=\"Sales Order Lines related to a Sales Order of mine\"/>\n                <field name=\"order_id\"/>\n                <field name=\"order_partner_id\" operator=\"child_of\"/>\n                <field name=\"product_id\"/>\n                <field name=\"salesman_id\"/>\n                <group expand=\"0\" string=\"Group By\">\n                    <filter string=\"Product\" name=\"product\" domain=\"[]\" context=\"{''group_by'':''product_id''}\"/>\n                    <filter string=\"Order\" name=\"order\" domain=\"[]\" context=\"{''group_by'':''order_id''}\"/>\n                    <filter string=\"Salesperson\" name=\"salesperson\" domain=\"[]\" context=\"{''group_by'':''salesman_id''}\"/>\n                </group>\n            </search>"}', '<?xml version="1.0"?>
<search string="Search Sales Order">
                <filter string="To Invoice" name="to_invoice" domain="[(''qty_to_invoice'', ''!='', 0)]" help="Sales Order Lines ready to be invoiced"/>
                <separator/>
                <filter string="My Sales Order Lines" name="my_sales_order_lines" domain="[(''salesman_id'',''='',uid)]" help="Sales Order Lines related to a Sales Order of mine"/>
                <field name="order_id"/>
                <field name="order_partner_id" operator="child_of"/>
                <field name="product_id"/>
                <field name="salesman_id"/>
                <group expand="0" string="Group By">
                    <filter string="Product" name="product" domain="[]" context="{''group_by'':''product_id''}"/>
                    <filter string="Order" name="order" domain="[]" context="{''group_by'':''order_id''}"/>
                    <filter string="Salesperson" name="salesperson" domain="[]" context="{''group_by'':''salesman_id''}"/>
                </group>
            </search>
        ', false, true, '2026-05-10 01:12:05.269262', '2026-05-10 01:12:05.269262', false);
INSERT INTO public.ir_ui_view VALUES (912, 16, NULL, 1, 1, 'sale.order.line.kanban', 'sale.order.line', NULL, 'kanban', 'sale/views/sale_order_line_views.xml', 'primary', '{"en_US": "<kanban class=\"o_kanban_mobile\">\n                <templates>\n                    <t t-name=\"kanban-box\">\n                        <div class=\"oe_kanban_content oe_kanban_global_click\">\n                            <div class=\"row\">\n                                <div class=\"col-12\">\n                                <field name=\"display_name\"/>\n                                </div>\n                            </div>\n                        </div>\n                    </t>\n                </templates>\n            </kanban>"}', '<?xml version="1.0"?>
