            </kanban>
        ', false, true, '2026-05-10 01:12:05.269262', '2026-05-10 01:12:05.269262', false);
INSERT INTO public.ir_ui_view VALUES (913, 20, 542, 1, 1, 'Portal layout : sales menu entries', NULL, 'sale.portal_my_home_menu_sale', 'qweb', 'sale/views/sale_portal_templates.xml', 'extension', '{"en_US": "<data name=\"Portal layout : sales menu entries\" inherit_id=\"portal.portal_breadcrumbs\" priority=\"20\">\n        <xpath expr=\"//ol[hasclass(''o_portal_submenu'')]\" position=\"inside\">\n            <li id=\"portal_breadcrumbs_sale\" t-if=\"page_name == ''quote'' or sale_order and sale_order.state in (''sent'', ''cancel'')\" t-attf-class=\"breadcrumb-item #{''active '' if not sale_order else ''''}\">\n                <a t-if=\"sale_order\" t-attf-href=\"/my/quotes?{{ keep_query() }}\">Quotations</a>\n                <t t-else=\"\">Quotations</t>\n            </li>\n            <li t-elif=\"page_name == ''order'' or sale_order and sale_order.state not in (''sent'', ''cancel'')\" t-attf-class=\"breadcrumb-item #{''active '' if not sale_order else ''''}\">\n                <a t-if=\"sale_order\" t-attf-href=\"/my/orders?{{ keep_query() }}\">Sales Orders</a>\n                <t t-else=\"\">Sales Orders</t>\n            </li>\n            <li t-if=\"sale_order\" class=\"breadcrumb-item active\">\n                <span t-field=\"sale_order.type_name\"/>\n                <t t-out=\"sale_order.name\"/>\n            </li>\n        </xpath>\n    </data>"}', '<?xml version="1.0"?>
<data name="Portal layout : sales menu entries" inherit_id="portal.portal_breadcrumbs" priority="20">
        <xpath expr="//ol[hasclass(''o_portal_submenu'')]" position="inside">
            <li id="portal_breadcrumbs_sale" t-if="page_name == ''quote'' or sale_order and sale_order.state in (''sent'', ''cancel'')" t-attf-class="breadcrumb-item #{''active '' if not sale_order else ''''}">
                <a t-if="sale_order" t-attf-href="/my/quotes?{{ keep_query() }}">Quotations</a>
                <t t-else="">Quotations</t>
            </li>
            <li t-elif="page_name == ''order'' or sale_order and sale_order.state not in (''sent'', ''cancel'')" t-attf-class="breadcrumb-item #{''active '' if not sale_order else ''''}">
                <a t-if="sale_order" t-attf-href="/my/orders?{{ keep_query() }}">Sales Orders</a>
                <t t-else="">Sales Orders</t>
            </li>
            <li t-if="sale_order" class="breadcrumb-item active">
                <span t-field="sale_order.type_name"/>
                <t t-out="sale_order.name"/>
            </li>
        </xpath>
    </data>

    ', false, true, '2026-05-10 01:12:05.269262', '2026-05-10 01:12:05.269262', false);
INSERT INTO public.ir_ui_view VALUES (914, 20, 548, 1, 1, 'Show Quotations / Sales Orders', NULL, 'sale.portal_my_home_sale', 'qweb', 'sale/views/sale_portal_templates.xml', 'extension', '{"en_US": "<data name=\"Show Quotations / Sales Orders\" customize_show=\"True\" inherit_id=\"portal.portal_my_home\" priority=\"20\">\n        <xpath expr=\"//div[hasclass(''o_portal_docs'')]\" position=\"before\">\n            <t t-set=\"portal_client_category_enable\" t-value=\"True\"/>\n            <t t-set=\"portal_alert_category_enable\" t-value=\"True\"/>\n        </xpath>\n        <div id=\"portal_alert_category\" position=\"inside\">\n            <t t-call=\"portal.portal_docs_entry\">\n                <t t-set=\"bg_color\" t-value=\"''alert alert-primary''\"/>\n                <t t-set=\"placeholder_count\" t-value=\"''quotation_count''\"/>\n                <t t-set=\"title\">Quotations to review</t>\n                <t t-set=\"url\" t-value=\"''/my/quotes''\"/>\n                <t t-set=\"show_count\" t-value=\"True\"/>\n            </t>\n        </div>\n        <div id=\"portal_client_category\" position=\"inside\">\n            <t t-call=\"portal.portal_docs_entry\">\n                <t t-set=\"icon\" t-value=\"''/sale/static/src/img/bag.svg''\"/>\n                <t t-set=\"title\">Your Orders</t>\n                <t t-set=\"url\" t-value=\"''/my/orders''\"/>\n                <t t-set=\"text\">Follow, view or pay your orders</t>\n                <t t-set=\"placeholder_count\" t-value=\"''order_count''\"/>\n            </t>\n        </div>\n    </data>"}', '<?xml version="1.0"?>
<data name="Show Quotations / Sales Orders" customize_show="True" inherit_id="portal.portal_my_home" priority="20">
        <xpath expr="//div[hasclass(''o_portal_docs'')]" position="before">
            <t t-set="portal_client_category_enable" t-value="True"/>
            <t t-set="portal_alert_category_enable" t-value="True"/>
        </xpath>
        <div id="portal_alert_category" position="inside">
            <t t-call="portal.portal_docs_entry">
                <t t-set="bg_color" t-value="''alert alert-primary''"/>
                <t t-set="placeholder_count" t-value="''quotation_count''"/>
                <t t-set="title">Quotations to review</t>
                <t t-set="url" t-value="''/my/quotes''"/>
                <t t-set="show_count" t-value="True"/>
            </t>
        </div>
        <div id="portal_client_category" position="inside">
            <t t-call="portal.portal_docs_entry">
                <t t-set="icon" t-value="''/sale/static/src/img/bag.svg''"/>
                <t t-set="title">Your Orders</t>
                <t t-set="url" t-value="''/my/orders''"/>
                <t t-set="text">Follow, view or pay your orders</t>
                <t t-set="placeholder_count" t-value="''order_count''"/>
            </t>
        </div>
    </data>

    ', false, true, '2026-05-10 01:12:05.269262', '2026-05-10 01:12:05.269262', true);
INSERT INTO public.ir_ui_view VALUES (915, 16, NULL, 1, 1, 'My Quotations', NULL, 'sale.portal_my_quotations', 'qweb', 'sale/views/sale_portal_templates.xml', 'primary', '{"en_US": "<t name=\"My Quotations\" t-name=\"sale.portal_my_quotations\">\n        <t t-call=\"portal.portal_layout\">\n            <t t-set=\"breadcrumbs_searchbar\" t-value=\"True\"/>\n\n            <t t-call=\"portal.portal_searchbar\">\n                <t t-set=\"title\">Quotations</t>\n            </t>\n            <div t-if=\"not quotations\" class=\"alert alert-warning\" role=\"alert\">\n                There are currently no quotations for your account.\n            </div>\n            <t t-if=\"quotations\" t-call=\"portal.portal_table\">\n                <thead>\n                    <tr class=\"active\">\n                        <th>Quotation #</th>\n                        <th class=\"text-end\">Quotation Date</th>\n                        <th class=\"text-end\">Valid Until</th>\n                        <th class=\"text-center\"/>\n                        <th class=\"text-end\">Total</th>\n                    </tr>\n                </thead>\n                <t t-foreach=\"quotations\" t-as=\"quotation\">\n                    <tr>\n                        <td><a t-att-href=\"quotation.get_portal_url()\"><t t-out=\"quotation.name\"/></a></td>\n                        <td class=\"text-end\"><span t-field=\"quotation.date_order\"/></td>\n                        <td class=\"text-end\"><span t-field=\"quotation.validity_date\"/></td>\n                        <td class=\"text-center\">\n                            <span t-if=\"quotation.state == ''cancel''\" class=\"badge rounded-pill text-bg-danger\">\n                                <i class=\"fa fa-fw fa-remove\"/> Cancelled</span>\n                            <span t-if=\"quotation.is_expired\" class=\"badge rounded-pill text-bg-danger\">\n                                <i class=\"fa fa-fw fa-clock-o\"/> Expired</span>\n                        </td>\n                        <td class=\"text-end\">\n                            <span t-field=\"quotation.amount_total\"/>\n                        </td>\n                    </tr>\n                </t>\n            </t>\n        </t>\n    </t>"}', '<?xml version="1.0"?>
<t name="My Quotations" t-name="sale.portal_my_quotations">
        <t t-call="portal.portal_layout">
            <t t-set="breadcrumbs_searchbar" t-value="True"/>

            <t t-call="portal.portal_searchbar">
                <t t-set="title">Quotations</t>
            </t>
            <div t-if="not quotations" class="alert alert-warning" role="alert">
                There are currently no quotations for your account.
            </div>
            <t t-if="quotations" t-call="portal.portal_table">
                <thead>
                    <tr class="active">
                        <th>Quotation #</th>
                        <th class="text-end">Quotation Date</th>
                        <th class="text-end">Valid Until</th>
                        <th class="text-center"/>
                        <th class="text-end">Total</th>
                    </tr>
                </thead>
                <t t-foreach="quotations" t-as="quotation">
                    <tr>
                        <td><a t-att-href="quotation.get_portal_url()"><t t-out="quotation.name"/></a></td>
                        <td class="text-end"><span t-field="quotation.date_order"/></td>
                        <td class="text-end"><span t-field="quotation.validity_date"/></td>
                        <td class="text-center">
                            <span t-if="quotation.state == ''cancel''" class="badge rounded-pill text-bg-danger">
                                <i class="fa fa-fw fa-remove"/> Cancelled</span>
                            <span t-if="quotation.is_expired" class="badge rounded-pill text-bg-danger">
                                <i class="fa fa-fw fa-clock-o"/> Expired</span>
                        </td>
                        <td class="text-end">
                            <span t-field="quotation.amount_total"/>
                        </td>
                    </tr>
                </t>
            </t>
        </t>
    </t>

    ', false, true, '2026-05-10 01:12:05.269262', '2026-05-10 01:12:05.269262', false);
INSERT INTO public.ir_ui_view VALUES (916, 16, NULL, 1, 1, 'My Sales Orders', NULL, 'sale.portal_my_orders', 'qweb', 'sale/views/sale_portal_templates.xml', 'primary', '{"en_US": "<t name=\"My Sales Orders\" t-name=\"sale.portal_my_orders\">\n        <t t-call=\"portal.portal_layout\">\n            <t t-set=\"breadcrumbs_searchbar\" t-value=\"True\"/>\n\n            <t t-call=\"portal.portal_searchbar\">\n                <t t-set=\"title\">Your Orders</t>\n            </t>\n            <div t-if=\"not orders\" class=\"alert alert-warning\" role=\"alert\">\n                There are currently no sales orders for your account.\n            </div>\n            <t t-if=\"orders\" t-call=\"portal.portal_table\">\n                <thead>\n                    <tr class=\"active\">\n                        <th>\n                            <span class=\"d-none d-md-inline\">Sales Order #</span>\n                            <span class=\"d-block d-md-none\">Ref.</span>\n                        </th>\n                        <th class=\"text-end\">Order Date</th>\n                        <th class=\"text-center\"/>\n                        <th class=\"text-end\">Total</th>\n                    </tr>\n                </thead>\n                <t t-foreach=\"orders\" t-as=\"order\">\n                    <tr>\n                        <td><a t-att-href=\"order.get_portal_url()\"><t t-out=\"order.name\"/></a></td>\n                        <td class=\"text-end\">\n                            <span t-field=\"order.date_order\" t-options=\"{''widget'': ''date''}\"/>&amp;nbsp;\n                            <span class=\"d-none d-md-inline\" t-field=\"order.date_order\" t-options=\"{''time_only'': True}\"/>\n                        </td>\n                        <td class=\"text-center\">\n                            <span t-if=\"order.locked\" class=\"badge rounded-pill text-bg-success\">\n                                <i class=\"fa fa-fw fa-check\" role=\"img\" aria-label=\"Done\" title=\"Done\"/>Done\n                            </span>\n                        </td>\n                        <td class=\"text-end\"><span t-field=\"order.amount_total\"/></td>\n                    </tr>\n                </t>\n            </t>\n        </t>\n    </t>"}', '<?xml version="1.0"?>
<t name="My Sales Orders" t-name="sale.portal_my_orders">
        <t t-call="portal.portal_layout">
            <t t-set="breadcrumbs_searchbar" t-value="True"/>

            <t t-call="portal.portal_searchbar">
                <t t-set="title">Your Orders</t>
            </t>
            <div t-if="not orders" class="alert alert-warning" role="alert">
                There are currently no sales orders for your account.
            </div>
            <t t-if="orders" t-call="portal.portal_table">
                <thead>
                    <tr class="active">
                        <th>
                            <span class="d-none d-md-inline">Sales Order #</span>
                            <span class="d-block d-md-none">Ref.</span>
                        </th>
                        <th class="text-end">Order Date</th>
                        <th class="text-center"/>
                        <th class="text-end">Total</th>
                    </tr>
                </thead>
                <t t-foreach="orders" t-as="order">
                    <tr>
                        <td><a t-att-href="order.get_portal_url()"><t t-out="order.name"/></a></td>
                        <td class="text-end">
                            <span t-field="order.date_order" t-options="{''widget'': ''date''}"/>&amp;nbsp;
                            <span class="d-none d-md-inline" t-field="order.date_order" t-options="{''time_only'': True}"/>
                        </td>
                        <td class="text-center">
                            <span t-if="order.locked" class="badge rounded-pill text-bg-success">
                                <i class="fa fa-fw fa-check" role="img" aria-label="Done" title="Done"/>Done
                            </span>
                        </td>
                        <td class="text-end"><span t-field="order.amount_total"/></td>
                    </tr>
                </t>
            </t>
        </t>
    </t>

    ', false, true, '2026-05-10 01:12:05.269262', '2026-05-10 01:12:05.269262', false);
INSERT INTO public.ir_ui_view VALUES (917, 16, 563, 1, 1, 'Sales Order', NULL, 'sale.sale_order_portal_template', 'qweb', 'sale/views/sale_portal_templates.xml', 'primary', '{"en_US": "<data name=\"Sales Order\" inherit_id=\"portal.portal_sidebar\" primary=\"True\">\n        <xpath expr=\"//div[hasclass(''o_portal_sidebar'')]\" position=\"inside\">\n            <t t-set=\"o_portal_fullwidth_alert\" groups=\"sales_team.group_sale_salesman\">\n                <!-- Uses backend_url provided in rendering values -->\n                <t t-call=\"portal.portal_back_in_edit_mode\"/>\n            </t>\n\n            <div class=\"row o_portal_sale_sidebar\">\n                <!-- Sidebar -->\n                <t t-call=\"portal.portal_record_sidebar\" id=\"sale_order_portal_sidebar\">\n                    <t t-set=\"classes\" t-value=\"''d-print-none col-lg-3 col-xl-4''\"/>\n\n                    <t t-set=\"title\">\n                        <h2 t-field=\"sale_order.amount_total\" data-id=\"total_amount\"/>\n                    </t>\n                    <t t-set=\"entries\">\n                        <div class=\"d-flex flex-column gap-4\">\n                            <div class=\"d-flex flex-column gap-2\" id=\"sale_order_sidebar_button\">\n                                <a t-if=\"sale_order._has_to_be_signed()\" role=\"button\" class=\"btn btn-primary d-block\" data-bs-toggle=\"modal\" data-bs-target=\"#modalaccept\" href=\"#\">\n                                    <i class=\"fa fa-check\"/><t t-if=\"sale_order._has_to_be_paid()\"> Sign &amp; Pay</t><t t-else=\"\"> Accept &amp; Sign</t>\n                                </a>\n                                <a t-elif=\"sale_order._has_to_be_paid()\" role=\"button\" id=\"o_sale_portal_paynow\" data-bs-toggle=\"modal\" data-bs-target=\"#modalaccept\" href=\"#\" t-att-class=\"''d-block %s'' % (''btn btn-light'' if sale_order.transaction_ids else ''btn btn-primary'')\">\n                                    <i class=\"fa fa-check\"/> <t t-if=\"not sale_order.signature\">Accept &amp; Pay</t><t t-else=\"\">Pay Now</t>\n                                </a>\n                                <div class=\"o_download_pdf d-flex gap-1 flex-lg-column flex-xl-row\">\n                                    <div class=\"flex-grow-1\">\n                                        <a class=\"btn btn-secondary o_print_btn o_portal_invoice_print d-block\" t-att-href=\"sale_order.get_portal_url(report_type=''pdf'')\" id=\"print_invoice_report\" title=\"View Details\" target=\"_blank\"><i class=\"fa fa-print\"/> View Details</a>\n                                    </div>\n                                </div>\n                            </div>\n\n                            <div class=\"navspy flex-grow-1 ps-0\" t-ignore=\"true\" role=\"complementary\">\n                                <ul class=\"nav flex-column bs-sidenav\"/>\n                            </div>\n\n                            <t t-if=\"not sale_order.is_expired and sale_order.state in [''draft'', ''sent'']\">\n                                <div t-if=\"sale_order.amount_undiscounted - sale_order.amount_untaxed &gt; 0.01\" class=\"list-group-item flex-grow-1\">\n                                    <small><b class=\"text-muted\">Your advantage</b></small>\n                                    <small>\n                                        <b t-field=\"sale_order.amount_undiscounted\" t-options=\"{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: sale_order.currency_id}\" style=\"text-decoration: line-through\" class=\"d-block mt-1\" data-id=\"amount_undiscounted\"/>\n                                    </small>\n                                    <t t-if=\"sale_order.amount_untaxed == sale_order.amount_total\">\n                                        <h4 t-field=\"sale_order.amount_total\" class=\"text-success\" data-id=\"total_amount\"/>\n                                    </t>\n                                    <t t-else=\"\">\n                                        <h4 t-field=\"sale_order.amount_untaxed\" class=\"text-success mb-0\" data-id=\"total_untaxed\"/>\n                                        <small>(<span t-field=\"sale_order.amount_total\" data-id=\"total_amount\"/> Incl. tax)</small>\n                                    </t>\n                                </div>\n                            </t>\n\n                            <div t-if=\"sale_order.user_id\">\n                                <h6><small class=\"text-muted\">Your contact</small></h6>\n                                <div class=\"o_portal_contact_details d-flex flex-column gap-2\">\n                                    <div class=\"d-flex justify-content-start align-items-center gap-2\">\n                                        <img class=\"o_avatar o_portal_contact_img rounded\" t-att-src=\"image_data_uri(sale_order.user_id.avatar_128)\" alt=\"Contact\"/>\n                                        <div>\n                                            <h6 class=\"mb-0\" t-out=\"sale_order.user_id.name\"/>\n                                            <a href=\"#discussion\" class=\"d-flex align-items-center gap-2 small fw-bold\">\n                                            Send message\n                                            </a>\n                                        </div>\n                                    </div>\n                                </div>\n                            </div>\n                        </div>\n                    </t>\n                </t>\n\n                <!-- Page content -->\n                <div id=\"quote_content\" class=\"col-12 col-lg-9 col-xl-8 mt-5 mt-lg-0\">\n\n                    <!-- modal relative to the actions sign and pay -->\n                    <div role=\"dialog\" class=\"modal fade\" id=\"modalaccept\">\n                        <div class=\"modal-dialog\" t-if=\"sale_order._has_to_be_signed()\">\n                            <form id=\"accept\" method=\"POST\" t-att-data-order-id=\"sale_order.id\" t-att-data-token=\"sale_order.access_token\" class=\"js_accept_json modal-content js_website_submit_form\">\n                                <input type=\"hidden\" name=\"csrf_token\" t-att-value=\"request.csrf_token()\"/>\n                                <header class=\"modal-header\">\n                                    <h4 class=\"modal-title\">Validate Order</h4>\n                                    <button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"modal\" aria-label=\"Close\"/>\n                                </header>\n                                <main class=\"modal-body\" id=\"sign-dialog\">\n                                    <p>\n                                        <span>By signing this proposal, I agree to the following terms:</span>\n                                        <ul>\n                                            <li>\n                                                <span>Accepted on the behalf of:</span> <b t-field=\"sale_order.partner_id.commercial_partner_id\"/>\n                                            </li>\n                                            <li>\n                                                <span>For an amount of:</span> <b data-id=\"total_amount\" t-field=\"sale_order.amount_total\"/>\n                                            </li>\n                                            <li t-if=\"sale_order.payment_term_id\">\n                                                <span>With payment terms:</span> <b t-field=\"sale_order.payment_term_id.note\"/>\n                                            </li>\n                                        </ul>\n                                    </p>\n                                    <t t-call=\"portal.signature_form\">\n                                        <t t-set=\"call_url\" t-value=\"sale_order.get_portal_url(suffix=''/accept'')\"/>\n                                        <t t-set=\"default_name\" t-value=\"sale_order.partner_id.name or sale_order.partner_id.commercial_partner_id.name\"/>\n                                    </t>\n                                </main>\n                            </form>\n                        </div>\n\n                        <div class=\"modal-dialog\" t-if=\"not sale_order._has_to_be_signed() and sale_order._has_to_be_paid()\">\n                            <div class=\"modal-content\">\n                                <header class=\"modal-header\">\n                                    <h4 class=\"modal-title\">Validate Order</h4>\n                                    <button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"modal\" aria-label=\"Close\"/>\n                                </header>\n                                <main class=\"modal-body\" id=\"sign-dialog\">\n                                    <t t-set=\"prepayment_amount\" t-value=\"sale_order._get_prepayment_required_amount()\"/>\n                                    <t t-set=\"prepayment_available\" t-value=\"sale_order.prepayment_percent and sale_order.prepayment_percent != 1.0\"/>\n                                    <!-- Display choices only if a pre payment can confirm the order. -->\n                                    <div t-if=\"prepayment_available\" id=\"o_sale_portal_prepayment_buttons\" class=\"d-flex justify-content-center d-grid gap-2 btn-group\">\n                                        <button name=\"o_sale_portal_amount_prepayment_button\" class=\"btn btn-primary rounded\">\n                                            Down payment <br/>\n                                            <span t-esc=\"prepayment_amount\" class=\"fw-bold\" t-options=\"{''widget'': ''monetary'', ''display_currency'': sale_order.currency_id}\"/>\n                                        </button>\n                                        <button name=\"o_sale_portal_amount_total_button\" class=\"btn btn-primary rounded\">\n                                            Full amount <br/>\n                                            <span t-field=\"sale_order.amount_total\"/>\n                                        </button>\n                                    </div>\n                                    <p>\n                                        <!-- The widget associated with this modal will hide and show divs in function of the amount selected. -->\n                                        <div id=\"o_sale_portal_use_amount_total\">\n                                            By paying this proposal, I agree to the following terms:\n                                        </div>\n                                        <div t-if=\"prepayment_available\" id=\"o_sale_portal_use_amount_prepayment\">\n                                            By paying this <u>down payment</u> of\n                                            <span t-esc=\"prepayment_amount\" class=\"fw-bold\" t-options=\"{''widget'': ''monetary'', ''display_currency'': sale_order.currency_id}\"/>\n                                            (<b t-esc=\"sale_order.prepayment_percent * 100\"/> %)\n                                            for this proposal, I agree to the following terms:\n                                        </div>\n                                        <ul>\n                                            <li>\n                                                <span>Accepted on the behalf of:</span> <b t-field=\"sale_order.partner_id.commercial_partner_id\"/>\n                                            </li>\n                                            <li>\n                                                <span>For an amount of:</span> <b data-id=\"total_amount\" t-field=\"sale_order.amount_total\"/>\n                                            </li>\n                                            <li t-if=\"sale_order.payment_term_id\">\n                                                <span>With payment terms:</span> <b t-field=\"sale_order.payment_term_id.note\"/>\n                                            </li>\n                                        </ul>\n                                    </p>\n                                    <div t-if=\"company_mismatch\">\n                                        <t t-call=\"payment.company_mismatch_warning\"/>\n                                    </div>\n                                    <div t-elif=\"not sale_order._has_to_be_paid()\" class=\"alert alert-danger\">\n                                        The order is not in a state requiring customer payment.\n                                    </div>\n                                    <div t-elif=\"not payment_methods_sudo and not tokens_sudo\" class=\"alert alert-warning\">\n                                        <strong>No suitable payment option could be found.</strong><br/>\n                                        If you believe that it is an error, please contact the website administrator.\n                                    </div>\n                                    <div t-else=\"\" id=\"payment_method\" class=\"text-start\">\n                                        <h3 class=\"mb-3\">Pay with</h3>\n                                        <t t-call=\"payment.form\">\n                                            <!-- Inject the order ID to allow Stripe to check if tokenization is required. -->\n                                            <t t-set=\"sale_order_id\" t-value=\"sale_order.id\"/>\n                                        </t>\n                                    </div>\n                                </main>\n                            </div>\n                        </div>\n                    </div>\n\n                    <!-- modal relative to the action reject -->\n                    <div role=\"dialog\" class=\"modal fade\" id=\"modaldecline\">\n                        <div class=\"modal-dialog\">\n                            <form id=\"decline\" method=\"POST\" t-attf-action=\"/my/orders/#{sale_order.id}/decline?access_token=#{sale_order.access_token}\" class=\"modal-content\">\n                                <input type=\"hidden\" name=\"csrf_token\" t-att-value=\"request.csrf_token()\"/>\n                                <header class=\"modal-header\">\n                                    <h4 class=\"modal-title\">Reject This Quotation</h4>\n                                    <button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"modal\" aria-label=\"Close\"/>\n                                </header>\n                                <main class=\"modal-body\">\n                                    <p>\n                                        Tell us why you are refusing this quotation, this will help us improve our services.\n                                    </p>\n                                    <textarea rows=\"4\" name=\"decline_message\" required=\"\" placeholder=\"Your feedback...\" class=\"form-control\"/>\n                                </main>\n                                <footer class=\"modal-footer\">\n                                    <button type=\"submit\" t-att-id=\"sale_order.id\" class=\"btn btn-danger\">\n                                        <i class=\"fa fa-times\"/> Reject\n                                    </button>\n                                    <button type=\"button\" class=\"btn btn-primary\" data-bs-dismiss=\"modal\">\n                                        Cancel\n                                    </button>\n                                </footer>\n                            </form>\n                        </div>\n                    </div>\n\n                    <!-- status messages -->\n                    <div t-if=\"message == ''sign_ok''\" class=\"alert alert-success alert-dismissible d-print-none\" role=\"status\">\n                        <button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"alert\" aria-label=\"Close\"/>\n                        <strong>Thank You!</strong><br/>\n                        <t t-if=\"message == ''sign_ok'' and sale_order.state == ''sale''\">\n                            Your order has been confirmed.\n                        </t>\n                        <t t-elif=\"message == ''sign_ok'' and sale_order._has_to_be_paid()\">\n                            Your order has been signed but still needs to be paid to be confirmed.\n                        </t>\n                        <t t-else=\"\">Your order has been signed.</t>\n                    </div>\n\n                    <div t-if=\"message == ''cant_reject''\" class=\"alert alert-danger alert-dismissible d-print-none\" role=\"alert\">\n                        <button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"alert\" aria-label=\"Close\"/>\n                        Your order is not in a state to be rejected.\n                    </div>\n\n                    <t t-if=\"sale_order.get_portal_last_transaction()\">\n                        <t t-call=\"payment.transaction_status\">\n                            <t t-set=\"tx\" t-value=\"sale_order.get_portal_last_transaction()\"/>\n                        </t>\n                    </t>\n\n                    <div t-if=\"sale_order.state == ''cancel''\" class=\"alert alert-danger alert-dismissible d-print-none\" role=\"alert\">\n                        <button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"alert\" aria-label=\"close\"/>\n                        <strong>This quotation has been canceled.</strong> <a role=\"button\" href=\"#discussion\"><i class=\"fa fa-comment\"/> Contact us to get a new quotation.</a>\n                    </div>\n\n                    <div t-if=\"sale_order.is_expired\" class=\"alert alert-warning alert-dismissible d-print-none\" role=\"alert\">\n                        <button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"alert\" aria-label=\"close\"/>\n                        <strong>This offer expired!</strong> <a role=\"button\" href=\"#discussion\"><i class=\"fa fa-comment\"/> Contact us to get a new quotation.</a>\n                    </div>\n\n                    <!-- main content -->\n                    <div t-attf-class=\"#{''pb-5'' if report_type == ''html'' else ''''}\" id=\"portal_sale_content\">\n                        <div t-call=\"#{sale_order._get_name_portal_content_view()}\"/>\n                    </div>\n\n                    <!-- bottom actions -->\n                    <div t-if=\"sale_order._has_to_be_signed() or sale_order._has_to_be_paid()\" class=\"d-flex justify-content-center gap-1 d-print-none\">\n\n                        <t t-if=\"sale_order._has_to_be_signed()\">\n                            <div class=\"col-sm-auto mt8\">\n                                <a role=\"button\" class=\"btn btn-primary\" data-bs-toggle=\"modal\" data-bs-target=\"#modalaccept\" href=\"#\"><i class=\"fa fa-check\"/><t t-if=\"sale_order._has_to_be_paid()\"> Sign &amp; Pay</t><t t-else=\"\"> Accept &amp; Sign</t></a>\n                            </div>\n                            <div class=\"col-sm-auto mt8\">\n                                <a role=\"button\" class=\"btn btn-secondary\" href=\"#discussion\"><i class=\"fa fa-comment\"/> Feedback</a>\n                            </div>\n                            <div class=\"col-sm-auto mt8\">\n                                <a role=\"button\" class=\"btn btn-danger\" data-bs-toggle=\"modal\" data-bs-target=\"#modaldecline\" href=\"#\"> <i class=\"fa fa-times\"/> Reject</a>\n                            </div>\n                        </t>\n                        <div t-elif=\"sale_order._has_to_be_paid()\" class=\"col-sm-auto mt8\">\n                            <a role=\"button\" data-bs-toggle=\"modal\" data-bs-target=\"#modalaccept\" href=\"#\" t-att-class=\"''%s'' % (''btn btn-light'' if sale_order.transaction_ids else ''btn btn-primary'')\">\n                                <i class=\"fa fa-check\"/> <t t-if=\"not sale_order.signature\">Accept &amp; Pay</t><t t-else=\"\">Pay Now</t>\n                            </a>\n                        </div>\n                    </div>\n\n                    <!-- chatter -->\n                    <hr/>\n                    <div id=\"sale_order_communication\">\n                        <h3>Communication history</h3>\n                        <t t-call=\"portal.message_thread\"/>\n                    </div>\n                </div><!-- // #quote_content -->\n            </div>\n        </xpath>\n    <xpath expr=\".\" position=\"attributes\"><attribute name=\"t-name\">sale.sale_order_portal_template</attribute></xpath></data>"}', '<?xml version="1.0"?>
<data name="Sales Order" inherit_id="portal.portal_sidebar" primary="True">
        <xpath expr="//div[hasclass(''o_portal_sidebar'')]" position="inside">
            <t t-set="o_portal_fullwidth_alert" groups="sales_team.group_sale_salesman">
                <!-- Uses backend_url provided in rendering values -->
                <t t-call="portal.portal_back_in_edit_mode"/>
            </t>

            <div class="row o_portal_sale_sidebar">
                <!-- Sidebar -->
                <t t-call="portal.portal_record_sidebar" id="sale_order_portal_sidebar">
                    <t t-set="classes" t-value="''d-print-none col-lg-3 col-xl-4''"/>

                    <t t-set="title">
                        <h2 t-field="sale_order.amount_total" data-id="total_amount"/>
                    </t>
                    <t t-set="entries">
                        <div class="d-flex flex-column gap-4">
                            <div class="d-flex flex-column gap-2" id="sale_order_sidebar_button">
                                <a t-if="sale_order._has_to_be_signed()" role="button" class="btn btn-primary d-block" data-bs-toggle="modal" data-bs-target="#modalaccept" href="#">
                                    <i class="fa fa-check"/><t t-if="sale_order._has_to_be_paid()"> Sign &amp; Pay</t><t t-else=""> Accept &amp; Sign</t>
                                </a>
                                <a t-elif="sale_order._has_to_be_paid()" role="button" id="o_sale_portal_paynow" data-bs-toggle="modal" data-bs-target="#modalaccept" href="#" t-att-class="''d-block %s'' % (''btn btn-light'' if sale_order.transaction_ids else ''btn btn-primary'')">
                                    <i class="fa fa-check"/> <t t-if="not sale_order.signature">Accept &amp; Pay</t><t t-else="">Pay Now</t>
                                </a>
                                <div class="o_download_pdf d-flex gap-1 flex-lg-column flex-xl-row">
                                    <div class="flex-grow-1">
                                        <a class="btn btn-secondary o_print_btn o_portal_invoice_print d-block" t-att-href="sale_order.get_portal_url(report_type=''pdf'')" id="print_invoice_report" title="View Details" target="_blank"><i class="fa fa-print"/> View Details</a>
                                    </div>
                                </div>
                            </div>

                            <div class="navspy flex-grow-1 ps-0" t-ignore="true" role="complementary">
                                <ul class="nav flex-column bs-sidenav"/>
                            </div>

                            <t t-if="not sale_order.is_expired and sale_order.state in [''draft'', ''sent'']">
                                <div t-if="sale_order.amount_undiscounted - sale_order.amount_untaxed &gt; 0.01" class="list-group-item flex-grow-1">
                                    <small><b class="text-muted">Your advantage</b></small>
                                    <small>
                                        <b t-field="sale_order.amount_undiscounted" t-options="{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: sale_order.currency_id}" style="text-decoration: line-through" class="d-block mt-1" data-id="amount_undiscounted"/>
                                    </small>
                                    <t t-if="sale_order.amount_untaxed == sale_order.amount_total">
                                        <h4 t-field="sale_order.amount_total" class="text-success" data-id="total_amount"/>
                                    </t>
                                    <t t-else="">
                                        <h4 t-field="sale_order.amount_untaxed" class="text-success mb-0" data-id="total_untaxed"/>
                                        <small>(<span t-field="sale_order.amount_total" data-id="total_amount"/> Incl. tax)</small>
                                    </t>
                                </div>
                            </t>

                            <div t-if="sale_order.user_id">
                                <h6><small class="text-muted">Your contact</small></h6>
                                <div class="o_portal_contact_details d-flex flex-column gap-2">
                                    <div class="d-flex justify-content-start align-items-center gap-2">
                                        <img class="o_avatar o_portal_contact_img rounded" t-att-src="image_data_uri(sale_order.user_id.avatar_128)" alt="Contact"/>
                                        <div>
                                            <h6 class="mb-0" t-out="sale_order.user_id.name"/>
                                            <a href="#discussion" class="d-flex align-items-center gap-2 small fw-bold">
                                            Send message
                                            </a>
                                        </div>
                                    </div>
                                </div>
                            </div>
                        </div>
                    </t>
                </t>

                <!-- Page content -->
                <div id="quote_content" class="col-12 col-lg-9 col-xl-8 mt-5 mt-lg-0">

                    <!-- modal relative to the actions sign and pay -->
                    <div role="dialog" class="modal fade" id="modalaccept">
                        <div class="modal-dialog" t-if="sale_order._has_to_be_signed()">
                            <form id="accept" method="POST" t-att-data-order-id="sale_order.id" t-att-data-token="sale_order.access_token" class="js_accept_json modal-content js_website_submit_form">
                                <input type="hidden" name="csrf_token" t-att-value="request.csrf_token()"/>
                                <header class="modal-header">
                                    <h4 class="modal-title">Validate Order</h4>
                                    <button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close"/>
                                </header>
                                <main class="modal-body" id="sign-dialog">
                                    <p>
                                        <span>By signing this proposal, I agree to the following terms:</span>
                                        <ul>
                                            <li>
                                                <span>Accepted on the behalf of:</span> <b t-field="sale_order.partner_id.commercial_partner_id"/>
                                            </li>
                                            <li>
                                                <span>For an amount of:</span> <b data-id="total_amount" t-field="sale_order.amount_total"/>
                                            </li>
                                            <li t-if="sale_order.payment_term_id">
                                                <span>With payment terms:</span> <b t-field="sale_order.payment_term_id.note"/>
                                            </li>
                                        </ul>
                                    </p>
                                    <t t-call="portal.signature_form">
                                        <t t-set="call_url" t-value="sale_order.get_portal_url(suffix=''/accept'')"/>
                                        <t t-set="default_name" t-value="sale_order.partner_id.name or sale_order.partner_id.commercial_partner_id.name"/>
                                    </t>
                                </main>
                            </form>
                        </div>

                        <div class="modal-dialog" t-if="not sale_order._has_to_be_signed() and sale_order._has_to_be_paid()">
                            <div class="modal-content">
                                <header class="modal-header">
                                    <h4 class="modal-title">Validate Order</h4>
                                    <button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close"/>
                                </header>
                                <main class="modal-body" id="sign-dialog">
                                    <t t-set="prepayment_amount" t-value="sale_order._get_prepayment_required_amount()"/>
                                    <t t-set="prepayment_available" t-value="sale_order.prepayment_percent and sale_order.prepayment_percent != 1.0"/>
                                    <!-- Display choices only if a pre payment can confirm the order. -->
                                    <div t-if="prepayment_available" id="o_sale_portal_prepayment_buttons" class="d-flex justify-content-center d-grid gap-2 btn-group">
                                        <button name="o_sale_portal_amount_prepayment_button" class="btn btn-primary rounded">
                                            Down payment <br/>
                                            <span t-esc="prepayment_amount" class="fw-bold" t-options="{''widget'': ''monetary'', ''display_currency'': sale_order.currency_id}"/>
                                        </button>
                                        <button name="o_sale_portal_amount_total_button" class="btn btn-primary rounded">
                                            Full amount <br/>
                                            <span t-field="sale_order.amount_total"/>
                                        </button>
                                    </div>
                                    <p>
                                        <!-- The widget associated with this modal will hide and show divs in function of the amount selected. -->
                                        <div id="o_sale_portal_use_amount_total">
                                            By paying this proposal, I agree to the following terms:
                                        </div>
                                        <div t-if="prepayment_available" id="o_sale_portal_use_amount_prepayment">
                                            By paying this <u>down payment</u> of
                                            <span t-esc="prepayment_amount" class="fw-bold" t-options="{''widget'': ''monetary'', ''display_currency'': sale_order.currency_id}"/>
                                            (<b t-esc="sale_order.prepayment_percent * 100"/> %)
                                            for this proposal, I agree to the following terms:
                                        </div>
                                        <ul>
                                            <li>
                                                <span>Accepted on the behalf of:</span> <b t-field="sale_order.partner_id.commercial_partner_id"/>
                                            </li>
                                            <li>
                                                <span>For an amount of:</span> <b data-id="total_amount" t-field="sale_order.amount_total"/>
                                            </li>
                                            <li t-if="sale_order.payment_term_id">
                                                <span>With payment terms:</span> <b t-field="sale_order.payment_term_id.note"/>
                                            </li>
                                        </ul>
                                    </p>
                                    <div t-if="company_mismatch">
                                        <t t-call="payment.company_mismatch_warning"/>
                                    </div>
                                    <div t-elif="not sale_order._has_to_be_paid()" class="alert alert-danger">
                                        The order is not in a state requiring customer payment.
                                    </div>
                                    <div t-elif="not payment_methods_sudo and not tokens_sudo" class="alert alert-warning">
                                        <strong>No suitable payment option could be found.</strong><br/>
                                        If you believe that it is an error, please contact the website administrator.
                                    </div>
                                    <div t-else="" id="payment_method" class="text-start">
                                        <h3 class="mb-3">Pay with</h3>
                                        <t t-call="payment.form">
                                            <!-- Inject the order ID to allow Stripe to check if tokenization is required. -->
                                            <t t-set="sale_order_id" t-value="sale_order.id"/>
                                        </t>
                                    </div>
                                </main>
                            </div>
                        </div>
                    </div>

                    <!-- modal relative to the action reject -->
                    <div role="dialog" class="modal fade" id="modaldecline">
                        <div class="modal-dialog">
                            <form id="decline" method="POST" t-attf-action="/my/orders/#{sale_order.id}/decline?access_token=#{sale_order.access_token}" class="modal-content">
                                <input type="hidden" name="csrf_token" t-att-value="request.csrf_token()"/>
                                <header class="modal-header">
                                    <h4 class="modal-title">Reject This Quotation</h4>
                                    <button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close"/>
                                </header>
                                <main class="modal-body">
                                    <p>
                                        Tell us why you are refusing this quotation, this will help us improve our services.
                                    </p>
                                    <textarea rows="4" name="decline_message" required="" placeholder="Your feedback..." class="form-control"/>
                                </main>
                                <footer class="modal-footer">
                                    <button type="submit" t-att-id="sale_order.id" class="btn btn-danger">
                                        <i class="fa fa-times"/> Reject
                                    </button>
                                    <button type="button" class="btn btn-primary" data-bs-dismiss="modal">
                                        Cancel
                                    </button>
                                </footer>
                            </form>
                        </div>
                    </div>

                    <!-- status messages -->
                    <div t-if="message == ''sign_ok''" class="alert alert-success alert-dismissible d-print-none" role="status">
                        <button type="button" class="btn-close" data-bs-dismiss="alert" aria-label="Close"/>
                        <strong>Thank You!</strong><br/>
                        <t t-if="message == ''sign_ok'' and sale_order.state == ''sale''">
                            Your order has been confirmed.
                        </t>
                        <t t-elif="message == ''sign_ok'' and sale_order._has_to_be_paid()">
                            Your order has been signed but still needs to be paid to be confirmed.
                        </t>
                        <t t-else="">Your order has been signed.</t>
                    </div>

                    <div t-if="message == ''cant_reject''" class="alert alert-danger alert-dismissible d-print-none" role="alert">
                        <button type="button" class="btn-close" data-bs-dismiss="alert" aria-label="Close"/>
                        Your order is not in a state to be rejected.
                    </div>

                    <t t-if="sale_order.get_portal_last_transaction()">
                        <t t-call="payment.transaction_status">
                            <t t-set="tx" t-value="sale_order.get_portal_last_transaction()"/>
                        </t>
                    </t>

                    <div t-if="sale_order.state == ''cancel''" class="alert alert-danger alert-dismissible d-print-none" role="alert">
                        <button type="button" class="btn-close" data-bs-dismiss="alert" aria-label="close"/>
                        <strong>This quotation has been canceled.</strong> <a role="button" href="#discussion"><i class="fa fa-comment"/> Contact us to get a new quotation.</a>
                    </div>

                    <div t-if="sale_order.is_expired" class="alert alert-warning alert-dismissible d-print-none" role="alert">
                        <button type="button" class="btn-close" data-bs-dismiss="alert" aria-label="close"/>
                        <strong>This offer expired!</strong> <a role="button" href="#discussion"><i class="fa fa-comment"/> Contact us to get a new quotation.</a>
                    </div>

                    <!-- main content -->
                    <div t-attf-class="#{''pb-5'' if report_type == ''html'' else ''''}" id="portal_sale_content">
                        <div t-call="#{sale_order._get_name_portal_content_view()}"/>
                    </div>

                    <!-- bottom actions -->
                    <div t-if="sale_order._has_to_be_signed() or sale_order._has_to_be_paid()" class="d-flex justify-content-center gap-1 d-print-none">

                        <t t-if="sale_order._has_to_be_signed()">
                            <div class="col-sm-auto mt8">
                                <a role="button" class="btn btn-primary" data-bs-toggle="modal" data-bs-target="#modalaccept" href="#"><i class="fa fa-check"/><t t-if="sale_order._has_to_be_paid()"> Sign &amp; Pay</t><t t-else=""> Accept &amp; Sign</t></a>
                            </div>
                            <div class="col-sm-auto mt8">
                                <a role="button" class="btn btn-secondary" href="#discussion"><i class="fa fa-comment"/> Feedback</a>
                            </div>
                            <div class="col-sm-auto mt8">
                                <a role="button" class="btn btn-danger" data-bs-toggle="modal" data-bs-target="#modaldecline" href="#"> <i class="fa fa-times"/> Reject</a>
                            </div>
                        </t>
                        <div t-elif="sale_order._has_to_be_paid()" class="col-sm-auto mt8">
                            <a role="button" data-bs-toggle="modal" data-bs-target="#modalaccept" href="#" t-att-class="''%s'' % (''btn btn-light'' if sale_order.transaction_ids else ''btn btn-primary'')">
                                <i class="fa fa-check"/> <t t-if="not sale_order.signature">Accept &amp; Pay</t><t t-else="">Pay Now</t>
                            </a>
                        </div>
                    </div>

                    <!-- chatter -->
                    <hr/>
                    <div id="sale_order_communication">
                        <h3>Communication history</h3>
                        <t t-call="portal.message_thread"/>
                    </div>
                </div><!-- // #quote_content -->
            </div>
        </xpath>
    <xpath expr="." position="attributes"><attribute name="t-name">sale.sale_order_portal_template</attribute></xpath></data>

    ', false, true, '2026-05-10 01:12:05.269262', '2026-05-10 01:12:05.269262', false);
INSERT INTO public.ir_ui_view VALUES (918, 16, NULL, 1, 1, 'Sales Order Portal Content', NULL, 'sale.sale_order_portal_content', 'qweb', 'sale/views/sale_portal_templates.xml', 'primary', '{"en_US": "<t name=\"Sales Order Portal Content\" t-name=\"sale.sale_order_portal_content\">\n        <!-- Intro -->\n        <div id=\"introduction\" t-attf-class=\"#{''border-bottom-0 pt-0 pb-3 bg-white'' if report_type == ''html'' else ''''}\">\n            <div class=\"row\" id=\"intro_row\">\n                <h2 class=\"my-0 col-12 col-lg flex-grow-1 mb-1 mb-lg-0\">\n                    <t t-out=\"sale_order.type_name\"/> -\n                    <em t-out=\"sale_order.name\"/>\n                </h2>\n            </div>\n        </div>\n        <div id=\"content\">\n            <div id=\"informations\" class=\"row\">\n                <span id=\"transaction_info\">\n                    <div t-if=\"sale_order.get_portal_last_transaction() and not invoices and sale_order.state in (''sent'', ''sale'') and portal_confirmation == ''pay'' and not success and not error\" t-att-data-order-id=\"sale_order.id\">\n                        <t t-if=\"sale_order.transaction_ids\">\n                            <t t-call=\"payment.transaction_status\">\n                            <t t-set=\"tx\" t-value=\"sale_order.get_portal_last_transaction()\"/>\n                        </t>\n                    </t>\n                    </div>\n                </span>\n                <!-- Information -->\n                <div id=\"sale_info\" class=\"col-12 col-lg-6 mb-4\">\n                    <span id=\"sale_info_title\">\n                        <h4 class=\"mb-1\">Sale Information</h4>\n                        <hr class=\"mt-1 mb-2\"/>\n                    </span>\n                    <table class=\"table table-borderless table-sm\">\n                        <tbody style=\"white-space:nowrap\" id=\"sale_info_table\">\n                            <tr>\n                                <th t-if=\"sale_order.state in [''sale'', ''cancel'']\" class=\"ps-0 pb-0\">Order Date:</th>\n                                <th t-else=\"\" class=\"ps-0 pb-0\">Date:</th>\n                                <td class=\"w-100 pb-0 text-wrap\"><span t-field=\"sale_order.date_order\" t-options=\"{&quot;widget&quot;: &quot;date&quot;}\"/></td>\n                            </tr>\n                            <tr t-if=\"sale_order.validity_date and sale_order.state in [''draft'', ''sent'']\">\n                                <th class=\"ps-0 pb-0\">Expiration Date:</th>\n                                <td class=\"w-100 pb-0 text-wrap\"><span t-field=\"sale_order.validity_date\" t-options=\"{&quot;widget&quot;: &quot;date&quot;}\"/></td>\n                            </tr>\n                            <tr t-if=\"sale_order.client_order_ref\">\n                                <th class=\"ps-0 pb-0\">Your Reference:</th>\n                                <td class=\"w-100 pb-0 text-wrap\"><span t-field=\"sale_order.client_order_ref\"/></td>\n                            </tr>\n                        </tbody>\n                    </table>\n                </div>\n\n                <!-- ======  Customer Information  ====== -->\n                <div id=\"customer_info\" class=\"col-12 col-lg-6 mb-4\">\n                    <h4 class=\"mb-1\">\n                        <t t-if=\"sale_order.partner_shipping_id == sale_order.partner_invoice_id\">\n                            Invoicing and Shipping Address\n                        </t>\n                        <t t-else=\"\">\n                            Invoicing Address\n                        </t>\n                        <small t-if=\"sale_order.partner_id == sale_order.partner_invoice_id == sale_order.env.user.partner_id\">\n                            <a class=\"small\" t-attf-href=\"/my/account?redirect={{sale_order.get_portal_url()}}\">\n                                <i class=\"fa fa-fw fa-pencil\"/>\n                            </a>\n                        </small>\n                    </h4>\n                    <hr class=\"mt-1 mb-2\"/>\n                    <div t-field=\"sale_order.partner_invoice_id\" t-options=\"{''widget'': ''contact'', ''fields'': [''name'', ''address'', ''phone'', ''email'']}\"/>\n                    <span t-if=\"sale_order.partner_shipping_id != sale_order.partner_invoice_id\" id=\"shipping_address\" class=\"col-lg-6\">\n                        <br/>\n                        <h4 class=\"mb-1\">\n                            Shipping Address\n                        </h4>\n                        <hr class=\"mt-1 mb-2\"/>\n                        <div t-field=\"sale_order.partner_shipping_id\" t-options=\"{ &quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [ &quot;name&quot;, &quot;address&quot;]}\"/>\n                    </span>\n                </div>\n                <t t-set=\"invoices\" t-value=\"sale_order.invoice_ids.filtered(lambda i: i.state not in [''draft'', ''cancel'']).sorted(''date'', reverse=True)[:3]\"/>\n                <div id=\"sale_invoices\" t-if=\"invoices and sale_order.state in [''sale'', ''cancel'']\" class=\"col-12 col-lg-6 mb-4\">\n                    <h4 class=\"mb-1\">Last Invoices</h4>\n                    <hr class=\"mt-1 mb-2\"/>\n                    <t t-foreach=\"invoices\" t-as=\"i\">\n                        <t t-set=\"report_url\" t-value=\"i.get_portal_url()\"/>\n                        <t t-set=\"authorized_tx_ids\" t-value=\"i.authorized_transaction_ids\"/>\n                        <div class=\"d-flex flex-column\">\n                            <div class=\"d-flex align-items-center justify-content-between\">\n                                <a t-att-href=\"report_url\">\n                                    <span t-out=\"i.name\"/>\n                                </a>\n                                <div t-if=\"i.payment_state in (''paid'', ''in_payment'')\" class=\"small badge text-bg-success orders_label_text_align\">\n                                    <i class=\"fa fa-fw fa-check\"/> Paid\n                                </div>\n                                <div t-elif=\"i.payment_state == ''reversed''\" class=\"small badge text-bg-success orders_label_text_align\">\n                                    <i class=\"fa fa-fw fa-check\"/> Reversed\n                                </div>\n                                <div t-elif=\"authorized_tx_ids\" class=\"small badge text-bg-success orders_label_text_align\">\n                                    <i class=\"fa fa-fw fa-check\"/> Authorized\n                                </div>\n                                <div t-else=\"\" class=\"small badge text-bg-info orders_label_text_align\">\n                                    <i class=\"fa fa-fw fa-clock-o\"/> Waiting Payment\n                                </div>\n                            </div>\n                            <div class=\"small d-lg-inline-block\">Date: <span class=\"text-muted\" t-field=\"i.invoice_date\"/></div>\n                        </div>\n                    </t>\n                </div>\n            </div>\n\n            <section id=\"details\" style=\"page-break-inside: auto;\">\n                <t t-if=\"product_documents\">\n                    <h4 id=\"details\">Documents</h4>\n                    <div class=\"d-flex flex-grow-1 flex-wrap gap-1 mb32\">\n                        <t t-foreach=\"product_documents\" t-as=\"document_sudo\">\n                            <div class=\"bg-light p-2 rounded\">\n                                <div class=\"position-relative text-center\">\n                                    <t t-set=\"attachment_sudo\" t-value=\"document_sudo.ir_attachment_id\"/>\n                                    <t t-set=\"target\" t-value=\"attachment_sudo.type == ''url'' and ''_blank'' or ''_self''\"/>\n                                    <a t-att-href=\"sale_order.get_portal_url(''/document/'' + str(document_sudo.id))\" t-att-target=\"target\" class=\"d-flex flex-row\">\n                                        <div class=\"o_image\" t-att-title=\"attachment_sudo.name\" t-att-data-mimetype=\"attachment_sudo.mimetype\" t-attf-data-src=\"/web/image/#{attachment_sudo.id}/100x80?access_token=#{attachment_sudo.access_token}\"/>\n                                        <div class=\"o_portal_product_document align-self-center\" t-out=\"attachment_sudo.name\"/>\n                                    </a>\n                                </div>\n                            </div>\n                        </t>\n                    </div>\n                </t>\n\n                <t t-set=\"display_discount\" t-value=\"True in [line.discount &gt; 0 for line in sale_order.order_line]\"/>\n\n                <div class=\"table-responsive\">\n                    <table t-att-data-order-id=\"sale_order.id\" t-att-data-token=\"sale_order.access_token\" class=\"table table-sm\" id=\"sales_order_table\">\n                        <thead class=\"bg-100\">\n                            <tr>\n                                <th class=\"text-start\" id=\"product_name_header\">Products</th>\n                                <th class=\"text-end\" id=\"product_qty_header\">Quantity</th>\n                                <th t-attf-class=\"text-end {{ ''d-none d-sm-table-cell'' if report_type == ''html'' else '''' }}\">\n                                    Unit Price\n                                </th>\n                                <th t-if=\"display_discount\" t-attf-class=\"text-end {{ ''d-none d-sm-table-cell'' if report_type == ''html'' else '''' }}\">\n                                    <span>Disc.%</span>\n                                </th>\n                                <th t-attf-class=\"text-end {{ ''d-none d-md-table-cell'' if report_type == ''html'' else '''' }}\" id=\"taxes_header\">\n                                    <span>Taxes</span>\n                                </th>\n                                <th class=\"text-end\" id=\"subtotal_header\">\n                                    <span>Amount</span>\n                                </th>\n                            </tr>\n                        </thead>\n                        <tbody class=\"sale_tbody\">\n\n                            <t t-set=\"current_subtotal\" t-value=\"0\"/>\n                            <t t-set=\"lines_to_report\" t-value=\"sale_order._get_order_lines_to_report()\"/>\n\n                            <t t-foreach=\"lines_to_report\" t-as=\"line\">\n\n                                <t t-set=\"current_subtotal\" t-value=\"current_subtotal + line.price_subtotal\"/>\n\n                                <tr t-att-class=\"''bg-200 fw-bold o_line_section'' if line.display_type == ''line_section'' else ''fst-italic o_line_note'' if line.display_type == ''line_note'' else ''''\">\n                                    <t t-if=\"not line.display_type\">\n                                        <td id=\"product_name\">\n                                            <span t-field=\"line.name\"/>\n                                        </td>\n                                        <td class=\"text-end\" id=\"quote_qty_td\">\n                                            <div id=\"quote_qty\">\n                                                <span t-field=\"line.product_uom_qty\"/>\n                                                <span t-field=\"line.product_uom\"/>\n                                            </div>\n                                        </td>\n                                        <td t-attf-class=\"text-end {{ ''d-none d-sm-table-cell'' if report_type == ''html'' else '''' }}\">\n                                            <div t-if=\"line.discount &gt;= 0\" t-field=\"line.price_unit\" t-att-style=\"line.discount and ''text-decoration: line-through'' or None\" t-att-class=\"(line.discount and ''text-danger'' or '''') + '' text-end''\"/>\n                                            <div t-if=\"line.discount\">\n                                                <t t-out=\"(1-line.discount / 100.0) * line.price_unit\" t-options=\"{&quot;widget&quot;: &quot;float&quot;, &quot;decimal_precision&quot;: &quot;Product Price&quot;}\"/>\n                                            </div>\n                                        </td>\n                                        <td t-if=\"display_discount\" t-attf-class=\"text-end {{ ''d-none d-sm-table-cell'' if report_type == ''html'' else '''' }}\">\n                                            <strong t-if=\"line.discount &gt; 0\" class=\"text-info\">\n                                                <t t-out=\"((line.discount % 1) and ''%s'' or ''%d'') % line.discount\"/>%\n                                            </strong>\n                                        </td>\n                                        <td t-attf-class=\"text-end {{ ''d-none d-md-table-cell'' if report_type == ''html'' else '''' }}\" id=\"taxes\">\n                                            <span t-out=\"'', ''.join(map(lambda x: (x.description or x.name), line.tax_id))\"/>\n                                        </td>\n                                        <td t-if=\"not line.is_downpayment\" class=\"text-end\" id=\"subtotal\">\n                                        <span class=\"oe_order_line_price_subtotal\" t-field=\"line.price_subtotal\"/>\n                                        </td>\n                                    </t>\n                                    <t t-if=\"line.display_type == ''line_section''\">\n                                        <td colspan=\"99\">\n                                            <span t-field=\"line.name\"/>\n                                        </td>\n                                        <t t-set=\"current_section\" t-value=\"line\"/>\n                                        <t t-set=\"current_subtotal\" t-value=\"0\"/>\n                                    </t>\n                                    <t t-if=\"line.display_type == ''line_note''\">\n                                        <td colspan=\"99\">\n                                            <span t-field=\"line.name\"/>\n                                        </td>\n                                    </t>\n                                </tr>\n                                <tr t-if=\"current_section and (line_last or lines_to_report[line_index+1].display_type == ''line_section'') and not line.is_downpayment\" class=\"is-subtotal text-end\">\n                                    <td colspan=\"99\">\n                                        <strong class=\"mr16\">Subtotal</strong>\n                                        <span t-out=\"current_subtotal\" t-options=\"{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: sale_order.currency_id}\"/>\n                                    </td>\n                                </tr>\n                            </t>\n                        </tbody>\n                    </table>\n                </div>\n\n                <div id=\"total\" name=\"total\" style=\"page-break-inside: avoid;\">\n                    <div class=\"col-xs-7 col-md-5 ms-auto\">\n                        <t t-call=\"sale.sale_order_portal_content_totals_table\"/>\n                    </div>\n                </div>\n            </section>\n\n            <section t-if=\"sale_order.signature\" id=\"signature\" name=\"Signature\">\n                <div class=\"row mt-4\" name=\"signature\">\n                    <div t-attf-class=\"#{''col-3'' if report_type != ''html'' else ''col-sm-7 col-md-4''} ms-auto text-center\">\n                        <h5>Signature</h5>\n                        <img t-att-src=\"image_data_uri(sale_order.signature)\" style=\"max-height: 6rem; max-width: 100%;\"/>\n                        <p t-field=\"sale_order.signed_by\"/>\n                    </div>\n                </div>\n            </section>\n\n            <section t-if=\"not is_html_empty(sale_order.note)\" id=\"terms\" class=\"mt-4\">\n                <h4 class=\"\">Terms &amp; Conditions</h4>\n                <hr class=\"mt-0 mb-1\"/>\n                <t t-if=\"sale_order.terms_type == ''html''\">\n                    <!-- Note is plain text. This ensures a clickable link  -->\n                    <t t-set=\"tc_url\" t-value=\"''%s/terms'' % (sale_order.get_base_url())\"/>\n                    <em>Terms &amp; Conditions: <a href=\"/terms\"><t t-out=\"tc_url\"/></a></em>\n                </t>\n                <t t-else=\"\">\n                    <em t-field=\"sale_order.note\"/>\n                </t>\n            </section>\n\n            <section t-if=\"sale_order.payment_term_id\" class=\"mt-4\">\n                <h4 class=\"\">Payment terms</h4>\n                <hr class=\"mt-0 mb-1\"/>\n                <span t-field=\"sale_order.payment_term_id.note\"/>\n            </section>\n        </div>\n    </t>"}', '<?xml version="1.0"?>
<t name="Sales Order Portal Content" t-name="sale.sale_order_portal_content">
        <!-- Intro -->
        <div id="introduction" t-attf-class="#{''border-bottom-0 pt-0 pb-3 bg-white'' if report_type == ''html'' else ''''}">
            <div class="row" id="intro_row">
                <h2 class="my-0 col-12 col-lg flex-grow-1 mb-1 mb-lg-0">
                    <t t-out="sale_order.type_name"/> -
                    <em t-out="sale_order.name"/>
                </h2>
            </div>
        </div>
        <div id="content">
            <div id="informations" class="row">
                <span id="transaction_info">
                    <div t-if="sale_order.get_portal_last_transaction() and not invoices and sale_order.state in (''sent'', ''sale'') and portal_confirmation == ''pay'' and not success and not error" t-att-data-order-id="sale_order.id">
                        <t t-if="sale_order.transaction_ids">
                            <t t-call="payment.transaction_status">
                            <t t-set="tx" t-value="sale_order.get_portal_last_transaction()"/>
                        </t>
                    </t>
                    </div>
                </span>
                <!-- Information -->
                <div id="sale_info" class="col-12 col-lg-6 mb-4">
                    <span id="sale_info_title">
                        <h4 class="mb-1">Sale Information</h4>
                        <hr class="mt-1 mb-2"/>
                    </span>
                    <table class="table table-borderless table-sm">
                        <tbody style="white-space:nowrap" id="sale_info_table">
                            <tr>
                                <th t-if="sale_order.state in [''sale'', ''cancel'']" class="ps-0 pb-0">Order Date:</th>
                                <th t-else="" class="ps-0 pb-0">Date:</th>
                                <td class="w-100 pb-0 text-wrap"><span t-field="sale_order.date_order" t-options="{&quot;widget&quot;: &quot;date&quot;}"/></td>
                            </tr>
                            <tr t-if="sale_order.validity_date and sale_order.state in [''draft'', ''sent'']">
                                <th class="ps-0 pb-0">Expiration Date:</th>
                                <td class="w-100 pb-0 text-wrap"><span t-field="sale_order.validity_date" t-options="{&quot;widget&quot;: &quot;date&quot;}"/></td>
                            </tr>
                            <tr t-if="sale_order.client_order_ref">
                                <th class="ps-0 pb-0">Your Reference:</th>
                                <td class="w-100 pb-0 text-wrap"><span t-field="sale_order.client_order_ref"/></td>
                            </tr>
                        </tbody>
                    </table>
                </div>

                <!-- ======  Customer Information  ====== -->
                <div id="customer_info" class="col-12 col-lg-6 mb-4">
                    <h4 class="mb-1">
                        <t t-if="sale_order.partner_shipping_id == sale_order.partner_invoice_id">
                            Invoicing and Shipping Address
                        </t>
                        <t t-else="">
                            Invoicing Address
                        </t>
                        <small t-if="sale_order.partner_id == sale_order.partner_invoice_id == sale_order.env.user.partner_id">
                            <a class="small" t-attf-href="/my/account?redirect={{sale_order.get_portal_url()}}">
                                <i class="fa fa-fw fa-pencil"/>
                            </a>
                        </small>
                    </h4>
                    <hr class="mt-1 mb-2"/>
                    <div t-field="sale_order.partner_invoice_id" t-options="{''widget'': ''contact'', ''fields'': [''name'', ''address'', ''phone'', ''email'']}"/>
                    <span t-if="sale_order.partner_shipping_id != sale_order.partner_invoice_id" id="shipping_address" class="col-lg-6">
                        <br/>
                        <h4 class="mb-1">
                            Shipping Address
                        </h4>
                        <hr class="mt-1 mb-2"/>
                        <div t-field="sale_order.partner_shipping_id" t-options="{ &quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [ &quot;name&quot;, &quot;address&quot;]}"/>
                    </span>
                </div>
                <t t-set="invoices" t-value="sale_order.invoice_ids.filtered(lambda i: i.state not in [''draft'', ''cancel'']).sorted(''date'', reverse=True)[:3]"/>
                <div id="sale_invoices" t-if="invoices and sale_order.state in [''sale'', ''cancel'']" class="col-12 col-lg-6 mb-4">
                    <h4 class="mb-1">Last Invoices</h4>
                    <hr class="mt-1 mb-2"/>
                    <t t-foreach="invoices" t-as="i">
                        <t t-set="report_url" t-value="i.get_portal_url()"/>
                        <t t-set="authorized_tx_ids" t-value="i.authorized_transaction_ids"/>
                        <div class="d-flex flex-column">
                            <div class="d-flex align-items-center justify-content-between">
                                <a t-att-href="report_url">
                                    <span t-out="i.name"/>
                                </a>
                                <div t-if="i.payment_state in (''paid'', ''in_payment'')" class="small badge text-bg-success orders_label_text_align">
                                    <i class="fa fa-fw fa-check"/> Paid
                                </div>
                                <div t-elif="i.payment_state == ''reversed''" class="small badge text-bg-success orders_label_text_align">
                                    <i class="fa fa-fw fa-check"/> Reversed
                                </div>
                                <div t-elif="authorized_tx_ids" class="small badge text-bg-success orders_label_text_align">
                                    <i class="fa fa-fw fa-check"/> Authorized
                                </div>
                                <div t-else="" class="small badge text-bg-info orders_label_text_align">
                                    <i class="fa fa-fw fa-clock-o"/> Waiting Payment
                                </div>
                            </div>
                            <div class="small d-lg-inline-block">Date: <span class="text-muted" t-field="i.invoice_date"/></div>
                        </div>
                    </t>
                </div>
            </div>

            <section id="details" style="page-break-inside: auto;">
                <t t-if="product_documents">
                    <h4 id="details">Documents</h4>
                    <div class="d-flex flex-grow-1 flex-wrap gap-1 mb32">
                        <t t-foreach="product_documents" t-as="document_sudo">
                            <div class="bg-light p-2 rounded">
                                <div class="position-relative text-center">
                                    <t t-set="attachment_sudo" t-value="document_sudo.ir_attachment_id"/>
                                    <t t-set="target" t-value="attachment_sudo.type == ''url'' and ''_blank'' or ''_self''"/>
                                    <a t-att-href="sale_order.get_portal_url(''/document/'' + str(document_sudo.id))" t-att-target="target" class="d-flex flex-row">
                                        <div class="o_image" t-att-title="attachment_sudo.name" t-att-data-mimetype="attachment_sudo.mimetype" t-attf-data-src="/web/image/#{attachment_sudo.id}/100x80?access_token=#{attachment_sudo.access_token}"/>
                                        <div class="o_portal_product_document align-self-center" t-out="attachment_sudo.name"/>
                                    </a>
                                </div>
                            </div>
                        </t>
                    </div>
                </t>

                <t t-set="display_discount" t-value="True in [line.discount &gt; 0 for line in sale_order.order_line]"/>

                <div class="table-responsive">
                    <table t-att-data-order-id="sale_order.id" t-att-data-token="sale_order.access_token" class="table table-sm" id="sales_order_table">
                        <thead class="bg-100">
                            <tr>
                                <th class="text-start" id="product_name_header">Products</th>
                                <th class="text-end" id="product_qty_header">Quantity</th>
                                <th t-attf-class="text-end {{ ''d-none d-sm-table-cell'' if report_type == ''html'' else '''' }}">
                                    Unit Price
                                </th>
                                <th t-if="display_discount" t-attf-class="text-end {{ ''d-none d-sm-table-cell'' if report_type == ''html'' else '''' }}">
                                    <span>Disc.%</span>
                                </th>
                                <th t-attf-class="text-end {{ ''d-none d-md-table-cell'' if report_type == ''html'' else '''' }}" id="taxes_header">
                                    <span>Taxes</span>
                                </th>
                                <th class="text-end" id="subtotal_header">
                                    <span>Amount</span>
                                </th>
                            </tr>
                        </thead>
                        <tbody class="sale_tbody">

                            <t t-set="current_subtotal" t-value="0"/>
                            <t t-set="lines_to_report" t-value="sale_order._get_order_lines_to_report()"/>

                            <t t-foreach="lines_to_report" t-as="line">

                                <t t-set="current_subtotal" t-value="current_subtotal + line.price_subtotal"/>

                                <tr t-att-class="''bg-200 fw-bold o_line_section'' if line.display_type == ''line_section'' else ''fst-italic o_line_note'' if line.display_type == ''line_note'' else ''''">
                                    <t t-if="not line.display_type">
                                        <td id="product_name">
                                            <span t-field="line.name"/>
                                        </td>
                                        <td class="text-end" id="quote_qty_td">
                                            <div id="quote_qty">
                                                <span t-field="line.product_uom_qty"/>
                                                <span t-field="line.product_uom"/>
                                            </div>
                                        </td>
                                        <td t-attf-class="text-end {{ ''d-none d-sm-table-cell'' if report_type == ''html'' else '''' }}">
                                            <div t-if="line.discount &gt;= 0" t-field="line.price_unit" t-att-style="line.discount and ''text-decoration: line-through'' or None" t-att-class="(line.discount and ''text-danger'' or '''') + '' text-end''"/>
                                            <div t-if="line.discount">
                                                <t t-out="(1-line.discount / 100.0) * line.price_unit" t-options="{&quot;widget&quot;: &quot;float&quot;, &quot;decimal_precision&quot;: &quot;Product Price&quot;}"/>
                                            </div>
                                        </td>
                                        <td t-if="display_discount" t-attf-class="text-end {{ ''d-none d-sm-table-cell'' if report_type == ''html'' else '''' }}">
                                            <strong t-if="line.discount &gt; 0" class="text-info">
                                                <t t-out="((line.discount % 1) and ''%s'' or ''%d'') % line.discount"/>%
                                            </strong>
                                        </td>
                                        <td t-attf-class="text-end {{ ''d-none d-md-table-cell'' if report_type == ''html'' else '''' }}" id="taxes">
                                            <span t-out="'', ''.join(map(lambda x: (x.description or x.name), line.tax_id))"/>
                                        </td>
                                        <td t-if="not line.is_downpayment" class="text-end" id="subtotal">
                                        <span class="oe_order_line_price_subtotal" t-field="line.price_subtotal"/>
                                        </td>
                                    </t>
                                    <t t-if="line.display_type == ''line_section''">
                                        <td colspan="99">
                                            <span t-field="line.name"/>
                                        </td>
                                        <t t-set="current_section" t-value="line"/>
                                        <t t-set="current_subtotal" t-value="0"/>
                                    </t>
                                    <t t-if="line.display_type == ''line_note''">
                                        <td colspan="99">
                                            <span t-field="line.name"/>
                                        </td>
                                    </t>
                                </tr>
                                <tr t-if="current_section and (line_last or lines_to_report[line_index+1].display_type == ''line_section'') and not line.is_downpayment" class="is-subtotal text-end">
                                    <td colspan="99">
                                        <strong class="mr16">Subtotal</strong>
                                        <span t-out="current_subtotal" t-options="{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: sale_order.currency_id}"/>
                                    </td>
                                </tr>
                            </t>
                        </tbody>
                    </table>
                </div>

                <div id="total" name="total" style="page-break-inside: avoid;">
                    <div class="col-xs-7 col-md-5 ms-auto">
                        <t t-call="sale.sale_order_portal_content_totals_table"/>
                    </div>
                </div>
            </section>

            <section t-if="sale_order.signature" id="signature" name="Signature">
                <div class="row mt-4" name="signature">
                    <div t-attf-class="#{''col-3'' if report_type != ''html'' else ''col-sm-7 col-md-4''} ms-auto text-center">
                        <h5>Signature</h5>
                        <img t-att-src="image_data_uri(sale_order.signature)" style="max-height: 6rem; max-width: 100%;"/>
                        <p t-field="sale_order.signed_by"/>
                    </div>
                </div>
            </section>

            <section t-if="not is_html_empty(sale_order.note)" id="terms" class="mt-4">
                <h4 class="">Terms &amp; Conditions</h4>
                <hr class="mt-0 mb-1"/>
                <t t-if="sale_order.terms_type == ''html''">
                    <!-- Note is plain text. This ensures a clickable link  -->
                    <t t-set="tc_url" t-value="''%s/terms'' % (sale_order.get_base_url())"/>
                    <em>Terms &amp; Conditions: <a href="/terms"><t t-out="tc_url"/></a></em>
                </t>
                <t t-else="">
                    <em t-field="sale_order.note"/>
                </t>
            </section>

            <section t-if="sale_order.payment_term_id" class="mt-4">
                <h4 class="">Payment terms</h4>
                <hr class="mt-0 mb-1"/>
                <span t-field="sale_order.payment_term_id.note"/>
            </section>
        </div>
    </t>

    ', false, true, '2026-05-10 01:12:05.269262', '2026-05-10 01:12:05.269262', false);
INSERT INTO public.ir_ui_view VALUES (919, 16, NULL, 1, 1, 'sale_order_portal_content_totals_table', NULL, 'sale.sale_order_portal_content_totals_table', 'qweb', 'sale/views/sale_portal_templates.xml', 'primary', '{"en_US": "<t t-name=\"sale.sale_order_portal_content_totals_table\">\n        <table class=\"table table-sm\">\n            <t t-set=\"tax_totals\" t-value=\"sale_order.tax_totals\"/>\n            <t t-call=\"#{sale_order._get_name_tax_totals_view()}\">\n                <!--\n                NOTE: This variable should not be used in templates before version 19.1, as it might\n                not be available in earlier versions if customer does not upgrade the `sale` module.\n                -->\n                <t t-set=\"doc\" t-value=\"sale_order\"/>\n            </t>\n        </table>\n    </t>"}', '<?xml version="1.0"?>
<t t-name="sale.sale_order_portal_content_totals_table">
        <table class="table table-sm">
            <t t-set="tax_totals" t-value="sale_order.tax_totals"/>
            <t t-call="#{sale_order._get_name_tax_totals_view()}">
                <!--
                NOTE: This variable should not be used in templates before version 19.1, as it might
                not be available in earlier versions if customer does not upgrade the `sale` module.
                -->
                <t t-set="doc" t-value="sale_order"/>
            </t>
        </table>
    </t>
', false, true, '2026-05-10 01:12:05.269262', '2026-05-10 01:12:05.269262', false);
INSERT INTO public.ir_ui_view VALUES (920, 16, 278, 1, 1, 'utm.campaign.view.kanban', 'utm.campaign', NULL, 'kanban', 'sale/views/utm_campaign_views.xml', 'extension', '{"en_US": "<xpath expr=\"//div[hasclass(''oe_kanban_bottom_left'')]\" position=\"inside\">\n                <a t-if=\"record.invoiced_amount\" href=\"#\" title=\"Revenues\" role=\"button\" groups=\"sales_team.group_sale_salesman\" data-type=\"object\" data-name=\"action_redirect_to_invoiced\" class=\"oe_kanban_action oe_kanban_action_a btn-outline-primary rounded-pill me-1 order-1\">\n                    <span class=\"badge\">\n                        <field name=\"currency_id\" invisible=\"True\"/>\n                        <field name=\"invoiced_amount\" widget=\"monetary\" options=\"{''currency_field'': ''currency_id''}\"/>\n                    </span>\n                </a>\n                <a t-if=\"record.quotation_count\" href=\"#\" title=\"Quotations\" role=\"button\" groups=\"sales_team.group_sale_salesman\" data-type=\"object\" data-name=\"action_redirect_to_quotations\" class=\"oe_kanban_action oe_kanban_action_a btn-outline-primary rounded-pill me-1 order-2\">\n                    <span class=\"badge\">\n                        <i class=\"fa fa-fw fa-money me-1\" aria-label=\"Quotations\" role=\"img\"/>\n                        <field name=\"quotation_count\"/>\n                    </span>\n                </a>\n            </xpath>"}', '<?xml version="1.0"?>
<xpath expr="//div[hasclass(''oe_kanban_bottom_left'')]" position="inside">
                <a t-if="record.invoiced_amount" href="#" title="Revenues" role="button" groups="sales_team.group_sale_salesman" data-type="object" data-name="action_redirect_to_invoiced" class="oe_kanban_action oe_kanban_action_a btn-outline-primary rounded-pill me-1 order-1">
                    <span class="badge">
                        <field name="currency_id" invisible="True"/>
                        <field name="invoiced_amount" widget="monetary" options="{''currency_field'': ''currency_id''}"/>
                    </span>
                </a>
                <a t-if="record.quotation_count" href="#" title="Quotations" role="button" groups="sales_team.group_sale_salesman" data-type="object" data-name="action_redirect_to_quotations" class="oe_kanban_action oe_kanban_action_a btn-outline-primary rounded-pill me-1 order-2">
                    <span class="badge">
                        <i class="fa fa-fw fa-money me-1" aria-label="Quotations" role="img"/>
                        <field name="quotation_count"/>
                    </span>
                </a>
            </xpath>
        ', false, true, '2026-05-10 01:12:05.269262', '2026-05-10 01:12:05.269262', false);
INSERT INTO public.ir_ui_view VALUES (921, 16, 275, 1, 1, 'utm.campaign.view.form', 'utm.campaign', NULL, 'form', 'sale/views/utm_campaign_views.xml', 'extension', '{"en_US": "<xpath expr=\"//div[hasclass(''oe_button_box'')]\" position=\"inside\">\n                <button name=\"action_redirect_to_invoiced\" type=\"object\" class=\"oe_stat_button order-1\" icon=\"fa-usd\" groups=\"sales_team.group_sale_salesman\">\n                    <field name=\"invoiced_amount\" widget=\"statinfo\" string=\"Revenues\"/>\n                </button>\n                <button name=\"action_redirect_to_quotations\" type=\"object\" class=\"oe_stat_button order-2\" icon=\"fa-money\" groups=\"sales_team.group_sale_salesman\">\n                    <field name=\"quotation_count\" widget=\"statinfo\" string=\"Quotations\"/>\n                </button>\n            </xpath>"}', '<?xml version="1.0"?>
<xpath expr="//div[hasclass(''oe_button_box'')]" position="inside">
                <button name="action_redirect_to_invoiced" type="object" class="oe_stat_button order-1" icon="fa-usd" groups="sales_team.group_sale_salesman">
                    <field name="invoiced_amount" widget="statinfo" string="Revenues"/>
                </button>
                <button name="action_redirect_to_quotations" type="object" class="oe_stat_button order-2" icon="fa-money" groups="sales_team.group_sale_salesman">
                    <field name="quotation_count" widget="statinfo" string="Quotations"/>
                </button>
            </xpath>
        ', false, true, '2026-05-10 01:12:05.269262', '2026-05-10 01:12:05.269262', false);
INSERT INTO public.ir_ui_view VALUES (939, 16, 765, 1, 1, 'res.config.settings.view.form.inherit.account.check.printing', 'res.config.settings', NULL, 'form', 'account_check_printing/views/res_config_settings_views.xml', 'extension', '{"en_US": "<setting id=\"print_checks\" position=\"inside\">\n                <div class=\"content-group\" invisible=\"not module_account_check_printing\">\n                    <div class=\"row mt16\">\n                        <label for=\"account_check_printing_layout\" class=\"col-lg-4 o_light_label\"/>\n                        <field name=\"account_check_printing_layout\" required=\"True\"/>\n                    </div>\n                    <div class=\"row\">\n                        <label for=\"account_check_printing_multi_stub\" class=\"col-lg-4 o_light_label\"/>\n                        <field name=\"account_check_printing_multi_stub\" class=\"w-50\"/>\n                    </div>\n                    <div class=\"row\">\n                        <label for=\"account_check_printing_margin_top\" class=\"col-lg-4 o_light_label\"/>\n                        <field name=\"account_check_printing_margin_top\"/>\n                    </div>\n                    <div class=\"row\">\n                        <label for=\"account_check_printing_margin_left\" class=\"col-lg-4 o_light_label\"/>\n                        <field name=\"account_check_printing_margin_left\"/>\n                    </div>\n                    <div class=\"row\" invisible=\"country_code != ''CA''\">\n                        <label for=\"account_check_printing_margin_right\" class=\"col-lg-4 o_light_label\"/>\n                        <field name=\"account_check_printing_margin_right\"/>\n                    </div>\n                    <div class=\"row\" invisible=\"country_code != ''CA''\">\n                      <label for=\"account_check_printing_date_label\" class=\"col-lg-4 o_light_label\"/>\n                      <field name=\"account_check_printing_date_label\"/>\n                    </div>\n                </div>\n            </setting>"}', '<?xml version="1.0"?>
<setting id="print_checks" position="inside">
                <div class="content-group" invisible="not module_account_check_printing">
                    <div class="row mt16">
                        <label for="account_check_printing_layout" class="col-lg-4 o_light_label"/>
                        <field name="account_check_printing_layout" required="True"/>
                    </div>
                    <div class="row">
                        <label for="account_check_printing_multi_stub" class="col-lg-4 o_light_label"/>
                        <field name="account_check_printing_multi_stub" class="w-50"/>
                    </div>
                    <div class="row">
                        <label for="account_check_printing_margin_top" class="col-lg-4 o_light_label"/>
                        <field name="account_check_printing_margin_top"/>
                    </div>
                    <div class="row">
                        <label for="account_check_printing_margin_left" class="col-lg-4 o_light_label"/>
                        <field name="account_check_printing_margin_left"/>
                    </div>
                    <div class="row" invisible="country_code != ''CA''">
                        <label for="account_check_printing_margin_right" class="col-lg-4 o_light_label"/>
                        <field name="account_check_printing_margin_right"/>
                    </div>
                    <div class="row" invisible="country_code != ''CA''">
                      <label for="account_check_printing_date_label" class="col-lg-4 o_light_label"/>
                      <field name="account_check_printing_date_label"/>
                    </div>
                </div>
            </setting>
        ', false, true, '2026-05-10 01:12:09.434736', '2026-05-10 01:12:09.434736', false);
INSERT INTO public.ir_ui_view VALUES (922, 16, 857, 1, 1, 'report_saleorder_document_inherit_sale_management', NULL, 'sale_management.report_saleorder_document_inherit_sale_management', 'qweb', 'sale_management/report/sale_report_templates.xml', 'extension', '{"en_US": "<data inherit_id=\"sale.report_saleorder_document\">\n    <xpath expr=\"//div[@name=''signature'']\" position=\"after\">\n        <div t-if=\"not (doc.sale_order_option_ids and doc.state in [''draft'', ''sent''])\" class=\"oe_structure\">​</div>\n        <div t-else=\"\">\n            <t t-set=\"has_option_discount\" t-value=\"any(option.discount != 0.0 for option in doc.sale_order_option_ids)\"/>\n            <h4 name=\"h_optional_products\">\n                <span>Options</span>\n            </h4>\n            <table name=\"table_optional_products\" class=\"table table-sm\">\n                <thead class=\"fw-bold\">\n                    <tr>\n                        <td name=\"th_option_name\" class=\"text-start\">Description</td>\n                        <td t-if=\"has_option_discount\" name=\"th_option_discount\" groups=\"product.group_discount_per_so_line\" class=\"text-start\">Disc.%</td>\n                        <td name=\"th_option_price_unit\" class=\"text-end\">Unit Price</td>\n                    </tr>\n                </thead>\n                <tbody class=\"sale_tbody\">\n                    <tr t-foreach=\"doc.sale_order_option_ids\" t-as=\"option\">\n                        <td name=\"td_option_name\">\n                            <span t-field=\"option.name\">Extra Chips</span>\n                        </td>\n                        <td t-if=\"has_option_discount\" name=\"td_option_discount\" groups=\"product.group_discount_per_so_line\">\n                            <strong t-if=\"option.discount != 0.0\" class=\"text-info\">\n                                <t t-out=\"((option.discount % 1) and ''%s'' or ''%d'') % option.discount\">-</t>%\n                            </strong>\n                        </td>\n                        <td name=\"td_option_price_unit\">\n                            <strong class=\"text-end\">\n                                <div t-field=\"option.price_unit\" t-options=\"{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: doc.currency_id}\" t-att-style=\"option.discount and ''text-decoration: line-through'' or None\" t-att-class=\"option.discount and ''text-danger'' or None\">1.5</div>\n                                <div t-if=\"option.discount\">\n                                    <t t-out=\"((1-option.discount / 100.0) * option.price_unit)\" t-options=\"{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: doc.currency_id}\"> </t>\n                                </div>\n                            </strong>\n                        </td>\n                    </tr>\n                </tbody>\n            </table>\n            <div class=\"oe_structure\">​</div>\n        </div>           \n    </xpath>\n</data>"}', '<?xml version="1.0"?>
<data inherit_id="sale.report_saleorder_document">
    <xpath expr="//div[@name=''signature'']" position="after">
        <div t-if="not (doc.sale_order_option_ids and doc.state in [''draft'', ''sent''])" class="oe_structure">​</div>
        <div t-else="">
            <t t-set="has_option_discount" t-value="any(option.discount != 0.0 for option in doc.sale_order_option_ids)"/>
            <h4 name="h_optional_products">
                <span>Options</span>
            </h4>
            <table name="table_optional_products" class="table table-sm">
                <thead class="fw-bold">
                    <tr>
                        <td name="th_option_name" class="text-start">Description</td>
                        <td t-if="has_option_discount" name="th_option_discount" groups="product.group_discount_per_so_line" class="text-start">Disc.%</td>
                        <td name="th_option_price_unit" class="text-end">Unit Price</td>
                    </tr>
                </thead>
                <tbody class="sale_tbody">
                    <tr t-foreach="doc.sale_order_option_ids" t-as="option">
                        <td name="td_option_name">
                            <span t-field="option.name">Extra Chips</span>
                        </td>
                        <td t-if="has_option_discount" name="td_option_discount" groups="product.group_discount_per_so_line">
                            <strong t-if="option.discount != 0.0" class="text-info">
                                <t t-out="((option.discount % 1) and ''%s'' or ''%d'') % option.discount">-</t>%
                            </strong>
                        </td>
                        <td name="td_option_price_unit">
                            <strong class="text-end">
                                <div t-field="option.price_unit" t-options="{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: doc.currency_id}" t-att-style="option.discount and ''text-decoration: line-through'' or None" t-att-class="option.discount and ''text-danger'' or None">1.5</div>
                                <div t-if="option.discount">
                                    <t t-out="((1-option.discount / 100.0) * option.price_unit)" t-options="{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: doc.currency_id}"> </t>
                                </div>
                            </strong>
                        </td>
                    </tr>
                </tbody>
            </table>
            <div class="oe_structure">​</div>
        </div>           
    </xpath>
</data>
', false, true, '2026-05-10 01:12:08.335307', '2026-05-10 01:12:08.335307', false);
INSERT INTO public.ir_ui_view VALUES (923, 16, NULL, 1, 1, 'sale.order.template.search', 'sale.order.template', NULL, 'search', 'sale_management/views/sale_order_template_views.xml', 'primary', '{"en_US": "<search string=\"Search Quotation Template\">\n                <field name=\"name\"/>\n                <filter string=\"Archived\" name=\"inactive\" domain=\"[(''active'',''='', False)]\"/>\n                <group expand=\"1\" string=\"Group By\">\n                    <filter string=\"Company\" name=\"company_id\" context=\"{''group_by'': ''company_id''}\" groups=\"base.group_multi_company\"/>\n                </group>\n            </search>"}', '<?xml version="1.0"?>
<search string="Search Quotation Template">
                <field name="name"/>
                <filter string="Archived" name="inactive" domain="[(''active'',''='', False)]"/>
                <group expand="1" string="Group By">
                    <filter string="Company" name="company_id" context="{''group_by'': ''company_id''}" groups="base.group_multi_company"/>
                </group>
            </search>
        ', false, true, '2026-05-10 01:12:08.335307', '2026-05-10 01:12:08.335307', false);
INSERT INTO public.ir_ui_view VALUES (924, 16, NULL, 1, 1, 'sale.order.template.form', 'sale.order.template', NULL, 'form', 'sale_management/views/sale_order_template_views.xml', 'primary', '{"en_US": "<form string=\"Quotation Template\">\n                <sheet>\n                    <div name=\"button_box\" class=\"oe_button_box\"/>\n                    <widget name=\"web_ribbon\" title=\"Archived\" bg_color=\"text-bg-danger\" invisible=\"active\"/>\n                    <div class=\"oe_title\" name=\"sale_order_template_title\">\n                        <label for=\"name\" id=\"sale_order_template_title\"/>\n                        <h1>\n                            <field name=\"name\" placeholder=\"e.g. Standard Consultancy Package\" class=\"d-block\"/>\n                        </h1>\n                    </div>\n                    <group>\n                        <group name=\"sale_info\">\n                            <field name=\"active\" invisible=\"1\"/>\n                            <label for=\"number_of_days\" string=\"Quotation Validity\"/>\n                            <div id=\"number_of_days\">\n                                <field name=\"number_of_days\" style=\"width: 3rem;\"/>\n                                <div class=\"d-inline-block\">days</div>\n                            </div>\n                            <field name=\"mail_template_id\" context=\"{''default_model'': ''sale.order''}\"/>\n                            <field name=\"company_id\" options=\"{''no_create'': True}\" groups=\"base.group_multi_company\"/>\n                            <field name=\"journal_id\"/>\n                        </group>\n                        <group name=\"so_confirmation\">\n                            <field name=\"require_signature\"/>\n                            <label for=\"require_payment\"/>\n                            <div id=\"require_payment\" class=\"o_row\">\n                                <field name=\"require_payment\" class=\"oe_inline\"/>\n                                <span invisible=\"not require_payment\">of</span>\n                                <field name=\"prepayment_percent\" invisible=\"not require_payment\" widget=\"percentage\" class=\"oe_inline\"/>\n                            </div>\n                        </group>\n                    </group>\n                    <notebook name=\"main_book\">\n                        <page string=\"Lines\" name=\"order_lines\">\n                        <field name=\"sale_order_template_line_ids\" widget=\"section_and_note_one2many\">\n                            <form string=\"Quotation Template Lines\">\n                                <!--\n                                    We need the sequence field to be here for new lines to be added at the correct position.\n                                    TODO: at some point we want to fix this in the framework so that an invisible field is not required.\n                                -->\n                                <field name=\"sequence\" invisible=\"1\"/>\n                                <field name=\"display_type\" invisible=\"1\"/>\n                                <field name=\"product_uom_category_id\" invisible=\"1\"/>\n                                <field name=\"company_id\" invisible=\"1\"/>\n                                <group invisible=\"display_type\">\n                                    <group>\n                                        <field name=\"product_id\" required=\"not display_type\"/>\n                                        <label for=\"product_uom_qty\"/>\n                                        <div>\n                                            <field name=\"product_uom_qty\" class=\"oe_inline\"/>\n                                        </div>\n                                    </group>\n                                </group>\n                                <notebook colspan=\"4\" name=\"description\">\n                                    <page string=\"Description\" name=\"order_description\" invisible=\"display_type\">\n                                        <field name=\"name\"/>\n                                    </page>\n                                    <page string=\"Section\" name=\"order_section\" invisible=\"display_type != ''line_section''\">\n                                        <field name=\"name\"/>\n                                    </page>\n                                    <page string=\"Note\" name=\"order_note\" invisible=\"display_type != ''line_note''\">\n                                        <field name=\"name\"/>\n                                    </page>\n                                </notebook>\n                            </form>\n                            <tree string=\"Quotation Template Lines\" editable=\"bottom\">\n                                <control>\n                                    <create name=\"add_product_control\" string=\"Add a product\"/>\n                                    <create name=\"add_section_control\" string=\"Add a section\" context=\"{''default_display_type'': ''line_section''}\"/>\n                                    <create name=\"add_note_control\" string=\"Add a note\" context=\"{''default_display_type'': ''line_note''}\"/>\n                                </control>\n\n                                <field name=\"display_type\" column_invisible=\"True\"/>\n                                <field name=\"company_id\" column_invisible=\"True\"/>\n                                <field name=\"sequence\" widget=\"handle\"/>\n                                <field name=\"product_id\"/>\n                                <field name=\"name\"/>\n                                <field name=\"product_uom_qty\"/>\n                                <field name=\"product_uom_category_id\" column_invisible=\"True\"/>\n                                <field name=\"product_uom_id\" groups=\"uom.group_uom\" required=\"not display_type\"/>\n                            </tree>\n                        </field>\n                    </page>\n                    <page string=\"Optional Products\" name=\"optional_products\">\n                        <field name=\"sale_order_template_option_ids\">\n                          <tree string=\"Quotation Template Lines\" editable=\"bottom\">\n                            <field name=\"product_id\"/>\n                            <field name=\"name\"/>\n                            <field name=\"quantity\"/>\n                            <field name=\"product_uom_category_id\" column_invisible=\"True\"/>\n                            <field name=\"uom_id\" groups=\"uom.group_uom\"/>\n                            <field name=\"company_id\" column_invisible=\"True\"/>\n                          </tree>\n                        </field>\n                    </page>\n                        <page string=\"Terms &amp; Conditions\" name=\"terms_and_conditions\">\n                            <field name=\"note\" nolabel=\"1\" placeholder=\"The Administrator can set default Terms &amp; Conditions in Sales Settings. Terms set here will show up instead if you select this quotation template.\"/>\n                        </page>\n                    </notebook>\n                </sheet>\n            </form>"}', '<?xml version="1.0"?>
<form string="Quotation Template">
                <sheet>
                    <div name="button_box" class="oe_button_box"/>
                    <widget name="web_ribbon" title="Archived" bg_color="text-bg-danger" invisible="active"/>
                    <div class="oe_title" name="sale_order_template_title">
                        <label for="name" id="sale_order_template_title"/>
                        <h1>
                            <field name="name" placeholder="e.g. Standard Consultancy Package" class="d-block"/>
                        </h1>
                    </div>
                    <group>
                        <group name="sale_info">
                            <field name="active" invisible="1"/>
                            <label for="number_of_days" string="Quotation Validity"/>
                            <div id="number_of_days">
                                <field name="number_of_days" style="width: 3rem;"/>
                                <div class="d-inline-block">days</div>
                            </div>
                            <field name="mail_template_id" context="{''default_model'': ''sale.order''}"/>
                            <field name="company_id" options="{''no_create'': True}" groups="base.group_multi_company"/>
                            <field name="journal_id"/>
                        </group>
                        <group name="so_confirmation">
                            <field name="require_signature"/>
                            <label for="require_payment"/>
                            <div id="require_payment" class="o_row">
                                <field name="require_payment" class="oe_inline"/>
                                <span invisible="not require_payment">of</span>
                                <field name="prepayment_percent" invisible="not require_payment" widget="percentage" class="oe_inline"/>
                            </div>
                        </group>
                    </group>
                    <notebook name="main_book">
                        <page string="Lines" name="order_lines">
                        <field name="sale_order_template_line_ids" widget="section_and_note_one2many">
                            <form string="Quotation Template Lines">
                                <!--
                                    We need the sequence field to be here for new lines to be added at the correct position.
                                    TODO: at some point we want to fix this in the framework so that an invisible field is not required.
                                -->
                                <field name="sequence" invisible="1"/>
                                <field name="display_type" invisible="1"/>
                                <field name="product_uom_category_id" invisible="1"/>
                                <field name="company_id" invisible="1"/>
                                <group invisible="display_type">
                                    <group>
                                        <field name="product_id" required="not display_type"/>
                                        <label for="product_uom_qty"/>
                                        <div>
                                            <field name="product_uom_qty" class="oe_inline"/>
                                        </div>
                                    </group>
                                </group>
                                <notebook colspan="4" name="description">
                                    <page string="Description" name="order_description" invisible="display_type">
                                        <field name="name"/>
                                    </page>
                                    <page string="Section" name="order_section" invisible="display_type != ''line_section''">
                                        <field name="name"/>
                                    </page>
                                    <page string="Note" name="order_note" invisible="display_type != ''line_note''">
                                        <field name="name"/>
                                    </page>
                                </notebook>
                            </form>
                            <tree string="Quotation Template Lines" editable="bottom">
                                <control>
                                    <create name="add_product_control" string="Add a product"/>
                                    <create name="add_section_control" string="Add a section" context="{''default_display_type'': ''line_section''}"/>
                                    <create name="add_note_control" string="Add a note" context="{''default_display_type'': ''line_note''}"/>
                                </control>

                                <field name="display_type" column_invisible="True"/>
                                <field name="company_id" column_invisible="True"/>
                                <field name="sequence" widget="handle"/>
                                <field name="product_id"/>
                                <field name="name"/>
                                <field name="product_uom_qty"/>
                                <field name="product_uom_category_id" column_invisible="True"/>
                                <field name="product_uom_id" groups="uom.group_uom" required="not display_type"/>
                            </tree>
                        </field>
                    </page>
                    <page string="Optional Products" name="optional_products">
                        <field name="sale_order_template_option_ids">
                          <tree string="Quotation Template Lines" editable="bottom">
                            <field name="product_id"/>
                            <field name="name"/>
                            <field name="quantity"/>
                            <field name="product_uom_category_id" column_invisible="True"/>
                            <field name="uom_id" groups="uom.group_uom"/>
                            <field name="company_id" column_invisible="True"/>
                          </tree>
                        </field>
                    </page>
                        <page string="Terms &amp; Conditions" name="terms_and_conditions">
                            <field name="note" nolabel="1" placeholder="The Administrator can set default Terms &amp; Conditions in Sales Settings. Terms set here will show up instead if you select this quotation template."/>
                        </page>
                    </notebook>
                </sheet>
            </form>
        ', false, true, '2026-05-10 01:12:08.335307', '2026-05-10 01:12:08.335307', false);
INSERT INTO public.ir_ui_view VALUES (925, 16, NULL, 1, 1, 'sale.order.template.tree', 'sale.order.template', NULL, 'tree', 'sale_management/views/sale_order_template_views.xml', 'primary', '{"en_US": "<tree string=\"Quotation Template\">\n                <field name=\"name\"/>\n                <field name=\"company_id\" groups=\"base.group_multi_company\"/>\n            </tree>"}', '<?xml version="1.0"?>
