INSERT INTO public.ir_ui_view VALUES (926, 10, 596, 1, 1, 'digest.digest.view.form.inherit.sale.order', 'digest.digest', NULL, 'form', 'sale_management/views/digest_views.xml', 'extension', '{"en_US": "<data><group name=\"kpi_sales\" position=\"attributes\">\n                <attribute name=\"string\">Sales</attribute>\n                <attribute name=\"groups\">sales_team.group_sale_salesman_all_leads</attribute>\n            </group>\n            <group name=\"kpi_sales\" position=\"inside\">\n                <field name=\"kpi_all_sale_total\"/>\n            </group>\n        </data>"}', '<?xml version="1.0"?>
<data><group name="kpi_sales" position="attributes">
