INSERT INTO public.ir_ui_view VALUES (927, 16, 870, 1, 1, 'res.config.settings.view.form.inherit.sale.management', 'res.config.settings', NULL, 'form', 'sale_management/views/res_config_settings_views.xml', 'extension', '{"en_US": "<data><setting id=\"order_default_values\" position=\"after\">\n                <setting id=\"standardized_offers_setting\" help=\"Create standardized offers with default products\" documentation=\"/applications/sales/sales/send_quotations/quote_template.html\">\n                    <field name=\"group_sale_order_template\"/>\n                    <div class=\"content-group\" invisible=\"not group_sale_order_template\">\n                        <div class=\"mt16\">\n                            <label for=\"company_so_template_id\" class=\"o_light_label mr8\"/>\n                            <field name=\"company_so_template_id\" class=\"oe_inline\"/>\n                            <span class=\"fa fa-lg fa-building-o p-2\" title=\"Values set here are company-specific.\" groups=\"base.group_multi_company\"/>\n                        </div>\n                        <div class=\"mt8\">\n                            <button name=\"331\" icon=\"oi-arrow-right\" type=\"action\" string=\"Quotation Templates\" class=\"btn-link\"/>\n                        </div>\n                    </div>\n                </setting>\n            </setting>\n            <xpath expr=\"//div[@id=''order_default_values_div'']\" position=\"before\">\n                <div invisible=\"not group_sale_order_template\" class=\"container text-info text-center border border-info\">\n                    Default values will be overwritten by values provided by the quotation template.\n                </div>\n            </xpath>\n            <app name=\"sale_management\" position=\"attributes\">\n                <attribute name=\"notApp\">0</attribute>\n            </app>\n        </data>"}', '<?xml version="1.0"?>
<data><setting id="order_default_values" position="after">
                <setting id="standardized_offers_setting" help="Create standardized offers with default products" documentation="/applications/sales/sales/send_quotations/quote_template.html">
                    <field name="group_sale_order_template"/>
                    <div class="content-group" invisible="not group_sale_order_template">
                        <div class="mt16">
                            <label for="company_so_template_id" class="o_light_label mr8"/>
                            <field name="company_so_template_id" class="oe_inline"/>
                            <span class="fa fa-lg fa-building-o p-2" title="Values set here are company-specific." groups="base.group_multi_company"/>
                        </div>
                        <div class="mt8">
                            <button name="331" icon="oi-arrow-right" type="action" string="Quotation Templates" class="btn-link"/>
                        </div>
                    </div>
                </setting>
            </setting>
            <xpath expr="//div[@id=''order_default_values_div'']" position="before">
                <div invisible="not group_sale_order_template" class="container text-info text-center border border-info">
                    Default values will be overwritten by values provided by the quotation template.
                </div>
            </xpath>
            <app name="sale_management" position="attributes">
                <attribute name="notApp">0</attribute>
            </app>
        </data>', false, true, '2026-05-10 01:12:08.335307', '2026-05-10 01:12:08.335307', false);
INSERT INTO public.ir_ui_view VALUES (928, 16, 883, 1, 1, 'sale.order.form.inherit.sale_management', 'sale.order', NULL, 'form', 'sale_management/views/sale_order_views.xml', 'extension', '{"en_US": "<data><page name=\"order_lines\" position=\"after\">\n                <page string=\"Optional Products\" name=\"optional_products\" invisible=\"state not in [''draft'', ''sent'']\">\n                    <field name=\"sale_order_option_ids\" mode=\"tree,kanban\" readonly=\"state in [''cancel'', ''sale'']\">\n                        <form string=\"Optional Products\">\n                            <group>\n                                <field name=\"product_id\" domain=\"[(''sale_ok'', ''='', True), ''|'', (''company_id'', ''='', False), (''company_id'', ''='', parent.company_id)]\"/>\n                                <field name=\"name\"/>\n                                <field name=\"quantity\"/>\n                                <field name=\"product_uom_category_id\" invisible=\"1\"/>\n                                <field name=\"uom_id\" groups=\"uom.group_uom\"/>\n                                <field name=\"price_unit\"/>\n                                <field name=\"discount\" groups=\"product.group_discount_per_so_line\"/>\n                                <field name=\"is_present\"/>\n                            </group>\n                        </form>\n                        <kanban class=\"o_kanban_mobile\">\n                            <field name=\"product_id\"/>\n                            <field name=\"quantity\"/>\n                            <field name=\"uom_id\" groups=\"uom.group_uom\"/>\n                            <field name=\"price_unit\"/>\n                            <field name=\"is_present\"/>\n                            <templates>\n                                <t t-name=\"kanban-box\">\n                                    <div class=\"oe_kanban_card oe_kanban_global_click\">\n                                        <div class=\"row\">\n                                            <div class=\"col-10\">\n                                                <strong>\n                                                    <span>\n                                                        <t t-out=\"record.product_id.value\"/>\n                                                    </span>\n                                                </strong>\n                                            </div>\n                                            <div class=\"col-2\">\n                                                <button name=\"button_add_to_order\" class=\"btn btn-link oe_link fa fa-shopping-cart\" title=\"Add to order lines\" type=\"object\" invisible=\"is_present\"/>\n                                            </div>\n                                        </div>\n                                        <div class=\"row\">\n                                            <div class=\"col-12 text-muted\">\n                                                <span>\n                                                    Quantity:\n                                                    <t t-out=\"record.quantity.value\"/>\n                                                    <t t-out=\"record.uom_id.value\" groups=\"uom.group_uom\"/>\n                                                </span>\n                                            </div>\n                                        </div>\n                                        <div class=\"row\">\n                                            <div class=\"col-12 text-muted\">\n                                                <span>\n                                                    Unit Price:\n                                                    <t t-out=\"record.price_unit.value\"/>\n                                                </span>\n                                            </div>\n                                        </div>\n                                    </div>\n                                </t>\n                            </templates>\n                        </kanban>\n                        <tree string=\"Sales Quotation Template Lines\" editable=\"bottom\" decoration-success=\"is_present == True\">\n                            <control>\n                                <create name=\"add_product_control\" string=\"Add a product\"/>\n                            </control>\n                            <field name=\"sequence\" widget=\"handle\"/>\n                            <field name=\"product_id\" domain=\"[(''sale_ok'', ''='', True), ''|'', (''company_id'', ''='', False), (''company_id'', ''='', parent.company_id)]\"/>\n                            <field name=\"name\" optional=\"show\"/>\n                            <field name=\"quantity\"/>\n                            <field name=\"uom_id\" string=\"UoM\" groups=\"uom.group_uom\" optional=\"show\"/>\n                            <field name=\"product_uom_category_id\" column_invisible=\"True\"/>\n                            <field name=\"price_unit\"/>\n                            <field name=\"discount\" string=\"Disc.%\" groups=\"product.group_discount_per_so_line\" optional=\"show\"/>\n                            <field name=\"is_present\" column_invisible=\"True\"/>\n                            <button name=\"button_add_to_order\" type=\"object\" class=\"oe_link\" icon=\"fa-shopping-cart\" title=\"Add to order lines\" invisible=\"is_present\"/>\n                        </tree>\n                    </field>\n                </page>\n            </page>\n\n            <field name=\"partner_shipping_id\" position=\"after\">\n                <field name=\"sale_order_template_id\" options=\"{''no_create'': True}\" groups=\"sale_management.group_sale_order_template\" readonly=\"state in [''cancel'', ''sale'']\"/>\n            </field>\n        </data>"}', '<?xml version="1.0"?>
<data><page name="order_lines" position="after">
                <page string="Optional Products" name="optional_products" invisible="state not in [''draft'', ''sent'']">
                    <field name="sale_order_option_ids" mode="tree,kanban" readonly="state in [''cancel'', ''sale'']">
                        <form string="Optional Products">
                            <group>
                                <field name="product_id" domain="[(''sale_ok'', ''='', True), ''|'', (''company_id'', ''='', False), (''company_id'', ''='', parent.company_id)]"/>
                                <field name="name"/>
                                <field name="quantity"/>
                                <field name="product_uom_category_id" invisible="1"/>
                                <field name="uom_id" groups="uom.group_uom"/>
                                <field name="price_unit"/>
                                <field name="discount" groups="product.group_discount_per_so_line"/>
                                <field name="is_present"/>
                            </group>
                        </form>
                        <kanban class="o_kanban_mobile">
                            <field name="product_id"/>
                            <field name="quantity"/>
                            <field name="uom_id" groups="uom.group_uom"/>
                            <field name="price_unit"/>
                            <field name="is_present"/>
                            <templates>
                                <t t-name="kanban-box">
                                    <div class="oe_kanban_card oe_kanban_global_click">
                                        <div class="row">
                                            <div class="col-10">
                                                <strong>
                                                    <span>
                                                        <t t-out="record.product_id.value"/>
                                                    </span>
                                                </strong>
                                            </div>
                                            <div class="col-2">
                                                <button name="button_add_to_order" class="btn btn-link oe_link fa fa-shopping-cart" title="Add to order lines" type="object" invisible="is_present"/>
                                            </div>
                                        </div>
                                        <div class="row">
                                            <div class="col-12 text-muted">
                                                <span>
                                                    Quantity:
                                                    <t t-out="record.quantity.value"/>
                                                    <t t-out="record.uom_id.value" groups="uom.group_uom"/>
                                                </span>
                                            </div>
                                        </div>
                                        <div class="row">
                                            <div class="col-12 text-muted">
                                                <span>
                                                    Unit Price:
                                                    <t t-out="record.price_unit.value"/>
                                                </span>
                                            </div>
                                        </div>
                                    </div>
                                </t>
                            </templates>
                        </kanban>
                        <tree string="Sales Quotation Template Lines" editable="bottom" decoration-success="is_present == True">
                            <control>
                                <create name="add_product_control" string="Add a product"/>
                            </control>
                            <field name="sequence" widget="handle"/>
                            <field name="product_id" domain="[(''sale_ok'', ''='', True), ''|'', (''company_id'', ''='', False), (''company_id'', ''='', parent.company_id)]"/>
                            <field name="name" optional="show"/>
                            <field name="quantity"/>
                            <field name="uom_id" string="UoM" groups="uom.group_uom" optional="show"/>
                            <field name="product_uom_category_id" column_invisible="True"/>
                            <field name="price_unit"/>
                            <field name="discount" string="Disc.%" groups="product.group_discount_per_so_line" optional="show"/>
                            <field name="is_present" column_invisible="True"/>
                            <button name="button_add_to_order" type="object" class="oe_link" icon="fa-shopping-cart" title="Add to order lines" invisible="is_present"/>
                        </tree>
                    </field>
                </page>
            </page>

            <field name="partner_shipping_id" position="after">
                <field name="sale_order_template_id" options="{''no_create'': True}" groups="sale_management.group_sale_order_template" readonly="state in [''cancel'', ''sale'']"/>
            </field>
        </data>', false, true, '2026-05-10 01:12:08.335307', '2026-05-10 01:12:08.335307', false);
INSERT INTO public.ir_ui_view VALUES (929, 16, 918, 1, 1, 'Order Options', NULL, 'sale_management.sale_order_portal_content_inherit_sale_management', 'qweb', 'sale_management/views/sale_portal_templates.xml', 'extension', '{"en_US": "<data name=\"Order Options\" inherit_id=\"sale.sale_order_portal_content\">\n\n        <xpath expr=\"//section[@id=''details'']//t[@t-set=''display_discount'']\" position=\"after\">\n            <t t-set=\"display_remove\" t-value=\"sale_order._can_be_edited_on_portal() and any(line._can_be_edited_on_portal() for line in sale_order.order_line)\"/>\n        </xpath>\n\n        <xpath expr=\"//section[@id=''details'']//table[@id=''sales_order_table'']/thead/tr\" position=\"inside\">\n            <!-- add blank Tr in thead for layout conciseness -->\n            <th t-if=\"display_remove\">\n            </th>\n        </xpath>\n\n        <xpath expr=\"//section[@id=''details'']//t[@t-if=''not line.display_type'']\" position=\"inside\">\n            <td class=\"text-center\" t-if=\"display_remove\">\n                <a t-if=\"line._can_be_edited_on_portal()\" t-att-data-line-id=\"line.id\" t-att-data-unlink=\"True\" href=\"#\" class=\"mb8 js_update_line_json d-print-none\" aria-label=\"Remove\" title=\"Remove\">\n                    <span class=\"fa fa-trash-o\"/>\n                </a>\n            </td>\n        </xpath>\n\n        <xpath expr=\"//section[@id=''signature'']\" position=\"after\">\n            <t t-if=\"sale_order._can_be_edited_on_portal() and any((not option.is_present) for option in sale_order.sale_order_option_ids)\">\n                <section>\n                    <h3>Options</h3>\n                    <t t-set=\"display_discount\" t-value=\"True in [option.discount &gt; 0 for option in sale_order.sale_order_option_ids]\"/>\n                    <table class=\"table table-sm\">\n                        <thead>\n                            <tr>\n                                <th class=\"text-start\">Product</th>\n                                <th t-if=\"display_discount\" class=\"text-end\">Disc.%\n                                </th>\n                                <th class=\"text-end\">Unit Price</th>\n                                <th t-if=\"sale_order._can_be_edited_on_portal() and report_type == ''html''\"/>\n                            </tr>\n                        </thead>\n                        <tbody>\n                            <tr t-foreach=\"sale_order.sale_order_option_ids\" t-as=\"option\">\n                                <t t-if=\"not option.is_present\">\n                                    <td>\n                                        <div t-field=\"option.name\"/>\n                                    </td>\n                                    <td t-if=\"display_discount\" class=\"text-end\">\n                                        <strong t-if=\"option.discount\" class=\"text-info\">\n                                            <t t-out=\"((option.discount % 1) and ''%s'' or ''%d'') % option.discount\"/>%\n                                        </strong>\n                                    </td>\n                                    <td>\n                                        <strong class=\"text-end\">\n                                            <div t-field=\"option.price_unit\" t-options=\"{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: sale_order.currency_id}\" t-att-style=\"option.discount and ''text-decoration: line-through'' or None\" t-att-class=\"option.discount and ''text-danger'' or None\"/>\n                                            <div t-if=\"option.discount\">\n                                                <t t-out=\"(1-option.discount / 100.0) * option.price_unit\" t-options=\"{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: sale_order.currency_id}\"/>\n                                            </div>\n                                        </strong>\n                                    </td>\n                                    <td class=\"text-center\" t-if=\"sale_order._can_be_edited_on_portal() and report_type == ''html''\">\n                                        <a t-att-data-option-id=\"option.id\" href=\"#\" class=\"mb8 js_add_optional_products d-print-none\" aria-label=\"Add to cart\" title=\"Add to cart\">\n                                            <span class=\"fa fa-shopping-cart\"/>\n                                        </a>\n                                    </td>\n                                </t>\n                            </tr>\n                        </tbody>\n                    </table>\n                </section>\n            </t>\n        </xpath>\n\n        <xpath expr=\"//section[@id=''details'']//div[@id=''quote_qty'']\" position=\"replace\">\n            <t t-if=\"line._can_be_edited_on_portal()\">\n                <div class=\"input-group js_quantity_container pull-right\">\n\n                    <span class=\"d-print-none input-group-text d-none d-md-inline-block\">\n                        <a t-att-data-line-id=\"line.id\" t-att-data-remove=\"True\" href=\"#\" class=\"js_update_line_json\" aria-label=\"Remove one\" title=\"Remove one\">\n                            <span class=\"fa fa-minus\"/>\n                        </a>\n                    </span>\n                    <!-- TODO add uom in this case too -->\n                    <input type=\"text\" class=\"js_quantity form-control\" t-att-data-line-id=\"line.id\" t-att-value=\"line.product_uom_qty\"/>\n                    <span class=\"d-print-none input-group-text d-none d-md-inline-block\">\n                        <a t-att-data-line-id=\"line.id\" href=\"#\" class=\"js_update_line_json\" aria-label=\"Add one\" title=\"Add one\">\n                            <span class=\"fa fa-plus\"/>\n                        </a>\n                    </span>\n                </div>\n            </t>\n            <t t-else=\"\">\n                <span t-field=\"line.product_uom_qty\"/>\n                <span t-field=\"line.product_uom\"/>\n            </t>\n        </xpath>\n\n    </data>"}', '<?xml version="1.0"?>
<data name="Order Options" inherit_id="sale.sale_order_portal_content">

        <xpath expr="//section[@id=''details'']//t[@t-set=''display_discount'']" position="after">
            <t t-set="display_remove" t-value="sale_order._can_be_edited_on_portal() and any(line._can_be_edited_on_portal() for line in sale_order.order_line)"/>
        </xpath>

        <xpath expr="//section[@id=''details'']//table[@id=''sales_order_table'']/thead/tr" position="inside">
            <!-- add blank Tr in thead for layout conciseness -->
            <th t-if="display_remove">
            </th>
        </xpath>

        <xpath expr="//section[@id=''details'']//t[@t-if=''not line.display_type'']" position="inside">
            <td class="text-center" t-if="display_remove">
                <a t-if="line._can_be_edited_on_portal()" t-att-data-line-id="line.id" t-att-data-unlink="True" href="#" class="mb8 js_update_line_json d-print-none" aria-label="Remove" title="Remove">
                    <span class="fa fa-trash-o"/>
                </a>
            </td>
        </xpath>

        <xpath expr="//section[@id=''signature'']" position="after">
            <t t-if="sale_order._can_be_edited_on_portal() and any((not option.is_present) for option in sale_order.sale_order_option_ids)">
                <section>
                    <h3>Options</h3>
                    <t t-set="display_discount" t-value="True in [option.discount &gt; 0 for option in sale_order.sale_order_option_ids]"/>
                    <table class="table table-sm">
                        <thead>
                            <tr>
                                <th class="text-start">Product</th>
                                <th t-if="display_discount" class="text-end">Disc.%
                                </th>
                                <th class="text-end">Unit Price</th>
                                <th t-if="sale_order._can_be_edited_on_portal() and report_type == ''html''"/>
                            </tr>
                        </thead>
                        <tbody>
                            <tr t-foreach="sale_order.sale_order_option_ids" t-as="option">
                                <t t-if="not option.is_present">
                                    <td>
                                        <div t-field="option.name"/>
                                    </td>
                                    <td t-if="display_discount" class="text-end">
                                        <strong t-if="option.discount" class="text-info">
                                            <t t-out="((option.discount % 1) and ''%s'' or ''%d'') % option.discount"/>%
                                        </strong>
                                    </td>
                                    <td>
                                        <strong class="text-end">
                                            <div t-field="option.price_unit" t-options="{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: sale_order.currency_id}" t-att-style="option.discount and ''text-decoration: line-through'' or None" t-att-class="option.discount and ''text-danger'' or None"/>
                                            <div t-if="option.discount">
                                                <t t-out="(1-option.discount / 100.0) * option.price_unit" t-options="{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: sale_order.currency_id}"/>
                                            </div>
                                        </strong>
                                    </td>
                                    <td class="text-center" t-if="sale_order._can_be_edited_on_portal() and report_type == ''html''">
                                        <a t-att-data-option-id="option.id" href="#" class="mb8 js_add_optional_products d-print-none" aria-label="Add to cart" title="Add to cart">
                                            <span class="fa fa-shopping-cart"/>
                                        </a>
                                    </td>
                                </t>
                            </tr>
                        </tbody>
                    </table>
                </section>
            </t>
        </xpath>

        <xpath expr="//section[@id=''details'']//div[@id=''quote_qty'']" position="replace">
            <t t-if="line._can_be_edited_on_portal()">
                <div class="input-group js_quantity_container pull-right">

                    <span class="d-print-none input-group-text d-none d-md-inline-block">
                        <a t-att-data-line-id="line.id" t-att-data-remove="True" href="#" class="js_update_line_json" aria-label="Remove one" title="Remove one">
                            <span class="fa fa-minus"/>
                        </a>
                    </span>
                    <!-- TODO add uom in this case too -->
                    <input type="text" class="js_quantity form-control" t-att-data-line-id="line.id" t-att-value="line.product_uom_qty"/>
                    <span class="d-print-none input-group-text d-none d-md-inline-block">
                        <a t-att-data-line-id="line.id" href="#" class="js_update_line_json" aria-label="Add one" title="Add one">
                            <span class="fa fa-plus"/>
                        </a>
                    </span>
                </div>
            </t>
            <t t-else="">
                <span t-field="line.product_uom_qty"/>
                <span t-field="line.product_uom"/>
            </t>
        </xpath>

    </data>

', false, true, '2026-05-10 01:12:08.335307', '2026-05-10 01:12:08.335307', false);
INSERT INTO public.ir_ui_view VALUES (930, 16, 453, 1, 1, 'product.template.form.inherit.sale.product.configurator', 'product.template', NULL, 'form', 'sale_product_configurator/views/product_template_views.xml', 'extension', '{"en_US": "<data><group name=\"upsell\" position=\"attributes\">\n                <attribute name=\"invisible\">0</attribute>\n            </group>\n            <group name=\"upsell\" position=\"inside\">\n                <field name=\"optional_product_ids\" widget=\"many2many_tags\" options=\"{''color_field'': ''color''}\" domain=\"[(''id'', ''!='', id), ''|'', (''company_id'', ''='', company_id), (''company_id'', ''='', False)]\" placeholder=\"Recommend when ''Adding to Cart'' or quotation\"/>\n            </group>\n        </data>"}', '<?xml version="1.0"?>
