INSERT INTO public.ir_ui_view VALUES (932, 16, 924, 1, 1, 'sale.order.template.form', 'sale.order.template', NULL, 'form', 'sale_pdf_quote_builder/views/sale_order_template_views.xml', 'extension', '{"en_US": "<notebook position=\"inside\">\n                <page name=\"pdf_quote\" string=\"PDF Quote Builder\">\n                    <group>\n                        <p class=\"text-muted\" colspan=\"2\">\n                            Provide header pages and footer pages to compose an attractive quotation\n                            with more information about your company, your products and your services.\n                            The pdf of your quotes will be built by putting together header pages,\n                            product descriptions, details of the quote and then the footer pages.\n                            If empty, it will use those define in the company settings.<br/>\n                            <a href=\"https://www.odoo.com/documentation/17.0/_downloads/5f0840ed187116c425fdac2ab4b592e1/pdfquotebuilderexamples.zip\">\n                                <i class=\"fa fa-arrow-right\"/> Download examples\n                            </a>\n                        </p>\n                        <group>\n                            <field name=\"sale_header_name\" invisible=\"1\"/>\n                            <field name=\"sale_header\" filename=\"sale_header_name\" options=\"{''accepted_file_extensions'': ''.pdf''}\"/>\n                            <field name=\"sale_footer_name\" invisible=\"1\"/>\n                            <field name=\"sale_footer\" filename=\"sale_footer_name\" options=\"{''accepted_file_extensions'': ''.pdf''}\"/>\n                        </group>\n                        <p class=\"text-muted\" colspan=\"2\">\n                            Products descriptions are pdf documents you can add directly on products.\n                            To do so, go on a product, find the \"product documents\" button, then add a\n                            new pdf document with a visibility set as \"Inside Quotes\". For each product\n                            in the quote, if the product has an \"inside quotes\" document, this document\n                            will be added after header pages and before the quotation details.\n                        </p>\n                        <p class=\"text-muted\" colspan=\"2\">\n                            Some information specific to the quote (customer name, quotation reference, ... )\n                            can be injected in these documents using pdf forms.\n                            Refer to the documentation to know more about this feature.\n                            <a href=\"https://www.odoo.com/documentation/17.0/applications/sales/sales/send_quotations/pdf_quote_builder.html\">\n                                Learn more from the documentation.\n                            </a>\n                        </p>\n                    </group>\n                </page>\n            </notebook>"}', '<?xml version="1.0"?>
<notebook position="inside">
                <page name="pdf_quote" string="PDF Quote Builder">
                    <group>
                        <p class="text-muted" colspan="2">
                            Provide header pages and footer pages to compose an attractive quotation
                            with more information about your company, your products and your services.
                            The pdf of your quotes will be built by putting together header pages,
                            product descriptions, details of the quote and then the footer pages.
                            If empty, it will use those define in the company settings.<br/>
                            <a href="https://www.odoo.com/documentation/17.0/_downloads/5f0840ed187116c425fdac2ab4b592e1/pdfquotebuilderexamples.zip">
                                <i class="fa fa-arrow-right"/> Download examples
                            </a>
                        </p>
                        <group>
                            <field name="sale_header_name" invisible="1"/>
                            <field name="sale_header" filename="sale_header_name" options="{''accepted_file_extensions'': ''.pdf''}"/>
                            <field name="sale_footer_name" invisible="1"/>
                            <field name="sale_footer" filename="sale_footer_name" options="{''accepted_file_extensions'': ''.pdf''}"/>
                        </group>
                        <p class="text-muted" colspan="2">
                            Products descriptions are pdf documents you can add directly on products.
                            To do so, go on a product, find the "product documents" button, then add a
                            new pdf document with a visibility set as "Inside Quotes". For each product
                            in the quote, if the product has an "inside quotes" document, this document
                            will be added after header pages and before the quotation details.
                        </p>
                        <p class="text-muted" colspan="2">
                            Some information specific to the quote (customer name, quotation reference, ... )
                            can be injected in these documents using pdf forms.
                            Refer to the documentation to know more about this feature.
                            <a href="https://www.odoo.com/documentation/17.0/applications/sales/sales/send_quotations/pdf_quote_builder.html">
                                Learn more from the documentation.
                            </a>
                        </p>
                    </group>
                </page>
            </notebook>
        ', false, true, '2026-05-10 01:12:09.242046', '2026-05-10 01:12:09.242046', false);
INSERT INTO public.ir_ui_view VALUES (933, 16, 927, 1, 1, 'res.config.settings.view.form.inherit.sale.pdf.quote.builder', 'res.config.settings', NULL, 'form', 'sale_pdf_quote_builder/wizards/res_config_settings_views.xml', 'extension', '{"en_US": "<setting id=\"sale_pdf_quote_builder\" position=\"replace\">\n                <setting id=\"sale_pdf_quote_builder\" string=\"PDF Quote builder\" help=\"Make your quote attractive by adding header pages, product descriptions and footer pages to your quote.\" documentation=\"/applications/sales/sales/send_quotations/pdf_quote_builder.html\" company_dependent=\"1\">\n                    <div class=\"mt16\">\n                        <field name=\"sale_header_name\" invisible=\"1\"/>\n                        <label for=\"sale_header\" class=\"me-2\"/>\n                        <field name=\"sale_header\" filename=\"sale_header_name\" options=\"{''accepted_file_extensions'': ''.pdf''}\"/>\n                    </div>\n                    <div class=\"mt16\">\n                        <field name=\"sale_footer_name\" invisible=\"1\"/>\n                        <label for=\"sale_footer\" class=\"me-2\"/>\n                        <field name=\"sale_footer\" filename=\"sale_footer_name\" options=\"{''accepted_file_extensions'': ''.pdf''}\"/>\n                    </div>\n                    <a href=\"https://www.odoo.com/documentation/17.0/_downloads/5f0840ed187116c425fdac2ab4b592e1/pdfquotebuilderexamples.zip\">\n                        <i class=\"fa fa-arrow-right\"/> Download examples\n                    </a>\n                </setting>\n            </setting>"}', '<?xml version="1.0"?>
<setting id="sale_pdf_quote_builder" position="replace">
                <setting id="sale_pdf_quote_builder" string="PDF Quote builder" help="Make your quote attractive by adding header pages, product descriptions and footer pages to your quote." documentation="/applications/sales/sales/send_quotations/pdf_quote_builder.html" company_dependent="1">
                    <div class="mt16">
                        <field name="sale_header_name" invisible="1"/>
                        <label for="sale_header" class="me-2"/>
                        <field name="sale_header" filename="sale_header_name" options="{''accepted_file_extensions'': ''.pdf''}"/>
                    </div>
                    <div class="mt16">
                        <field name="sale_footer_name" invisible="1"/>
                        <label for="sale_footer" class="me-2"/>
                        <field name="sale_footer" filename="sale_footer_name" options="{''accepted_file_extensions'': ''.pdf''}"/>
                    </div>
                    <a href="https://www.odoo.com/documentation/17.0/_downloads/5f0840ed187116c425fdac2ab4b592e1/pdfquotebuilderexamples.zip">
                        <i class="fa fa-arrow-right"/> Download examples
                    </a>
                </setting>
            </setting>
        ', false, true, '2026-05-10 01:12:09.242046', '2026-05-10 01:12:09.242046', false);
INSERT INTO public.ir_ui_view VALUES (934, 16, 772, 1, 1, 'account.journal.dashboard.kanban.inherited', 'account.journal', NULL, 'kanban', 'account_check_printing/views/account_journal_views.xml', 'extension', '{"en_US": "<xpath expr=\"//t[@t-name=''JournalBodyBankCash'']//div[hasclass(''o_kanban_primary_right'')]\" position=\"inside\">\n                    <div t-if=\"journal_type == ''bank'' and dashboard.num_checks_to_print != 0\">\n                        <div class=\"row\">\n                            <div class=\"col-12\">\n                                <a type=\"object\" name=\"action_checks_to_print\">\n                                    <t t-out=\"dashboard.num_checks_to_print\"/>\n                                    <span>&amp;nbsp;</span>\n                                    <t t-if=\"dashboard.num_checks_to_print == 1\">Check to print</t>\n                                    <t t-if=\"dashboard.num_checks_to_print != 1\">Checks to print</t>\n                                </a>\n                            </div>\n                        </div>\n                    </div>\n                </xpath>"}', '<?xml version="1.0"?>
