INSERT INTO public.ir_ui_view VALUES (935, 16, 691, 1, 1, 'account.journal.form.inherited', 'account.journal', NULL, 'form', 'account_check_printing/views/account_journal_views.xml', 'extension', '{"en_US": "<xpath expr=\"//page[@id=''outbound_payment_settings'']//group[@name=''outgoing_payment'']\" position=\"inside\">\n                    <group string=\"Check Printing\" invisible=\"'',check_printing,''.lower() not in (selected_payment_method_codes or '''').lower() or type != ''bank''\">\n                        <field name=\"check_sequence_id\" invisible=\"1\"/>\n                        <field name=\"check_manual_sequencing\"/>\n                        <field name=\"check_next_number\" invisible=\"not check_manual_sequencing\"/>\n                    </group>\n                </xpath>"}', '<?xml version="1.0"?>
