INSERT INTO public.ir_ui_view VALUES (937, 16, 645, 1, 1, 'account.payment.form.inherited', 'account.payment', NULL, 'form', 'account_check_printing/views/account_payment_views.xml', 'extension', '{"en_US": "<data><xpath expr=\"//button[@name=''action_post'']\" position=\"before\">\n                    <button name=\"print_checks\" class=\"oe_highlight\" invisible=\"payment_method_code != ''check_printing'' or state != ''posted'' or is_move_sent\" string=\"Print Check\" type=\"object\" data-hotkey=\"g\"/>\n                    <button name=\"action_unmark_sent\" invisible=\"payment_method_code != ''check_printing'' or not is_move_sent\" string=\"Unmark Sent\" type=\"object\" data-hotkey=\"l\"/>\n                    <button name=\"action_void_check\" invisible=\"payment_method_code != ''check_printing'' or state != ''posted'' or not is_move_sent\" string=\"Void Check\" type=\"object\" data-hotkey=\"o\"/>\n                </xpath>\n                <xpath expr=\"//div[@name=''amount_div'']\" position=\"after\">\n                    <field name=\"check_amount_in_words\" invisible=\"payment_method_code != ''check_printing''\" groups=\"base.group_no_one\"/>\n                </xpath>\n                <xpath expr=\"//field[@name=''payment_method_line_id'']\" position=\"after\">\n                    <field name=\"check_manual_sequencing\" invisible=\"1\"/>\n                    <field name=\"show_check_number\" invisible=\"1\"/>\n                    <field name=\"check_number\" invisible=\"not show_check_number\"/>\n                </xpath>\n                <xpath expr=\"//field[@name=''name'']\" position=\"before\">\n                    <widget name=\"web_ribbon\" title=\"Sent\" invisible=\"not is_move_sent\"/>\n                </xpath>\n            </data>"}', '<?xml version="1.0"?>
<data><xpath expr="//button[@name=''action_post'']" position="before">
                    <button name="print_checks" class="oe_highlight" invisible="payment_method_code != ''check_printing'' or state != ''posted'' or is_move_sent" string="Print Check" type="object" data-hotkey="g"/>
                    <button name="action_unmark_sent" invisible="payment_method_code != ''check_printing'' or not is_move_sent" string="Unmark Sent" type="object" data-hotkey="l"/>
                    <button name="action_void_check" invisible="payment_method_code != ''check_printing'' or state != ''posted'' or not is_move_sent" string="Void Check" type="object" data-hotkey="o"/>
                </xpath>
                <xpath expr="//div[@name=''amount_div'']" position="after">
                    <field name="check_amount_in_words" invisible="payment_method_code != ''check_printing''" groups="base.group_no_one"/>
                </xpath>
                <xpath expr="//field[@name=''payment_method_line_id'']" position="after">
                    <field name="check_manual_sequencing" invisible="1"/>
                    <field name="show_check_number" invisible="1"/>
                    <field name="check_number" invisible="not show_check_number"/>
                </xpath>
                <xpath expr="//field[@name=''name'']" position="before">
                    <widget name="web_ribbon" title="Sent" invisible="not is_move_sent"/>
                </xpath>
            </data>', false, true, '2026-05-10 01:12:09.434736', '2026-05-10 01:12:09.434736', false);
