INSERT INTO public.ir_ui_view VALUES (941, 16, NULL, 1, 1, 'Print Pre-numbered Checks', 'print.prenumbered.checks', NULL, 'form', 'account_check_printing/wizard/print_prenumbered_checks_views.xml', 'primary', '{"en_US": "<form string=\"Print Pre-numbered Checks\">\n                    <p>Please enter the number of the first pre-printed check that you are about to print on.</p>\n                    <p>This will allow to save on payments the number of the corresponding check.</p>\n                    <group>\n                        <field name=\"next_check_number\"/>\n                    </group>\n                    <footer>\n                        <button name=\"print_checks\" string=\"Print\" type=\"object\" class=\"oe_highlight\" data-hotkey=\"q\"/>\n                        <button string=\"Cancel\" class=\"btn btn-secondary\" special=\"cancel\" data-hotkey=\"x\"/>\n                    </footer>\n                </form>"}', '<?xml version="1.0"?>
<form string="Print Pre-numbered Checks">
                    <p>Please enter the number of the first pre-printed check that you are about to print on.</p>
                    <p>This will allow to save on payments the number of the corresponding check.</p>
                    <group>
                        <field name="next_check_number"/>
                    </group>
                    <footer>
                        <button name="print_checks" string="Print" type="object" class="oe_highlight" data-hotkey="q"/>
                        <button string="Cancel" class="btn btn-secondary" special="cancel" data-hotkey="x"/>
                    </footer>
                </form>
            ', false, true, '2026-05-10 01:12:09.434736', '2026-05-10 01:12:09.434736', false);
INSERT INTO public.ir_ui_view VALUES (942, 16, NULL, 1, 1, 'Barcode Nomenclatures', 'barcode.nomenclature', NULL, 'form', 'barcodes/views/barcodes_view.xml', 'primary', '{"en_US": "<form string=\"Barcode Nomenclature\">\n                    <sheet>\n                        <group name=\"general_attributes\" col=\"4\">\n                            <field name=\"name\"/>\n                            <field name=\"upc_ean_conv\"/>\n                        </group>\n                        <div>\n                            <p>\n                                <i>Barcodes Nomenclatures</i> define how barcodes are recognized and categorized.\n                                When a barcode is scanned it is associated to the <i>first</i> rule with a matching\n                                pattern. The pattern syntax is that of regular expression, and a barcode is matched\n                                if the regular expression matches a prefix of the barcode.\n                            </p><p>\n                                Patterns can also define how numerical values, such as weight or price, can be\n                                encoded into the barcode. They are indicated by <code>{NNN}</code> where the N''s\n                                define where the number''s digits are encoded. Floats are also supported with the\n                                decimals indicated with D''s, such as <code>{NNNDD}</code>. In these cases,\n                                the barcode field on the associated records <i>must</i> show these digits as\n                                zeroes.\n                            </p>\n                        </div>\n                        <field name=\"rule_ids\">\n                            <tree string=\"Tables\">\n                                <field name=\"sequence\" widget=\"handle\"/>\n                                <field name=\"name\"/>\n                                <field name=\"type\"/>\n                                <field name=\"encoding\"/>\n                                <field name=\"pattern\"/>\n                            </tree>\n                        </field>\n                    </sheet>\n                </form>"}', '<?xml version="1.0"?>
<form string="Barcode Nomenclature">
                    <sheet>
                        <group name="general_attributes" col="4">
                            <field name="name"/>
                            <field name="upc_ean_conv"/>
                        </group>
                        <div>
                            <p>
                                <i>Barcodes Nomenclatures</i> define how barcodes are recognized and categorized.
                                When a barcode is scanned it is associated to the <i>first</i> rule with a matching
                                pattern. The pattern syntax is that of regular expression, and a barcode is matched
                                if the regular expression matches a prefix of the barcode.
                            </p><p>
                                Patterns can also define how numerical values, such as weight or price, can be
                                encoded into the barcode. They are indicated by <code>{NNN}</code> where the N''s
                                define where the number''s digits are encoded. Floats are also supported with the
                                decimals indicated with D''s, such as <code>{NNNDD}</code>. In these cases,
                                the barcode field on the associated records <i>must</i> show these digits as
                                zeroes.
                            </p>
                        </div>
                        <field name="rule_ids">
                            <tree string="Tables">
                                <field name="sequence" widget="handle"/>
                                <field name="name"/>
                                <field name="type"/>
                                <field name="encoding"/>
                                <field name="pattern"/>
                            </tree>
                        </field>
                    </sheet>
                </form>
            ', false, true, '2026-05-10 01:12:17.435686', '2026-05-10 01:12:17.435686', false);
INSERT INTO public.ir_ui_view VALUES (943, 16, NULL, 1, 1, 'Barcode Nomenclatures', 'barcode.nomenclature', NULL, 'tree', 'barcodes/views/barcodes_view.xml', 'primary', '{"en_US": "<tree string=\"Barcode Nomenclatures\">\n                    <field name=\"name\"/>\n                </tree>"}', '<?xml version="1.0"?>
<tree string="Barcode Nomenclatures">
                    <field name="name"/>
                </tree>
            ', false, true, '2026-05-10 01:12:17.435686', '2026-05-10 01:12:17.435686', false);
INSERT INTO public.ir_ui_view VALUES (944, 16, NULL, 1, 1, 'Barcode Rule', 'barcode.rule', NULL, 'form', 'barcodes/views/barcodes_view.xml', 'primary', '{"en_US": "<form string=\"Barcode Rule\">\n                    <group>\n                        <field name=\"name\"/>\n                        <field name=\"sequence\"/>\n                        <field name=\"type\"/>\n                        <field name=\"encoding\" invisible=\"type == ''alias''\"/>\n                        <field name=\"pattern\"/>\n                        <field name=\"alias\" invisible=\"type != ''alias''\"/>\n                    </group>\n                </form>"}', '<?xml version="1.0"?>
<form string="Barcode Rule">
                    <group>
                        <field name="name"/>
                        <field name="sequence"/>
                        <field name="type"/>
                        <field name="encoding" invisible="type == ''alias''"/>
                        <field name="pattern"/>
                        <field name="alias" invisible="type != ''alias''"/>
                    </group>
                </form>
            ', false, true, '2026-05-10 01:12:17.435686', '2026-05-10 01:12:17.435686', false);
INSERT INTO public.ir_ui_view VALUES (945, 16, 942, 1, 1, 'Barcode Nomenclatures', 'barcode.nomenclature', NULL, 'form', 'barcodes_gs1_nomenclature/views/barcodes_view.xml', 'extension', '{"en_US": "<data><!-- Nomenclature form -->\n                <xpath expr=\"//field[@name=''upc_ean_conv'']\" position=\"attributes\">\n                    <attribute name=\"invisible\">is_gs1_nomenclature</attribute>\n                </xpath>\n                <xpath expr=\"//group[@name=''general_attributes'']\" position=\"after\">\n                    <group name=\"gs1_attributes\" col=\"4\">\n                        <field name=\"is_gs1_nomenclature\"/>\n                        <field name=\"gs1_separator_fnc1\" invisible=\"not is_gs1_nomenclature\"/>\n                    </group>\n                </xpath>\n                <!-- Rules table -->\n                <xpath expr=\"//field[@name=''rule_ids'']\" position=\"attributes\">\n                    <attribute name=\"context\">{''is_gs1'': is_gs1_nomenclature}</attribute>\n                </xpath>\n                <xpath expr=\"//field[@name=''encoding'']\" position=\"attributes\">\n                    <attribute name=\"column_invisible\">parent.is_gs1_nomenclature</attribute>\n                </xpath>\n                <xpath expr=\"//field[@name=''pattern'']\" position=\"after\">\n                    <field name=\"gs1_content_type\" column_invisible=\"not parent.is_gs1_nomenclature\"/>\n                    <field name=\"gs1_decimal_usage\" column_invisible=\"not parent.is_gs1_nomenclature\" invisible=\"gs1_content_type != ''measure''\"/>\n                    <field name=\"associated_uom_id\" column_invisible=\"not parent.is_gs1_nomenclature\" invisible=\"gs1_content_type != ''measure''\"/>\n                </xpath>\n            </data>"}', '<?xml version="1.0"?>
<data><!-- Nomenclature form -->
                <xpath expr="//field[@name=''upc_ean_conv'']" position="attributes">
                    <attribute name="invisible">is_gs1_nomenclature</attribute>
                </xpath>
                <xpath expr="//group[@name=''general_attributes'']" position="after">
                    <group name="gs1_attributes" col="4">
                        <field name="is_gs1_nomenclature"/>
                        <field name="gs1_separator_fnc1" invisible="not is_gs1_nomenclature"/>
                    </group>
                </xpath>
                <!-- Rules table -->
                <xpath expr="//field[@name=''rule_ids'']" position="attributes">
                    <attribute name="context">{''is_gs1'': is_gs1_nomenclature}</attribute>
                </xpath>
                <xpath expr="//field[@name=''encoding'']" position="attributes">
                    <attribute name="column_invisible">parent.is_gs1_nomenclature</attribute>
                </xpath>
                <xpath expr="//field[@name=''pattern'']" position="after">
                    <field name="gs1_content_type" column_invisible="not parent.is_gs1_nomenclature"/>
                    <field name="gs1_decimal_usage" column_invisible="not parent.is_gs1_nomenclature" invisible="gs1_content_type != ''measure''"/>
                    <field name="associated_uom_id" column_invisible="not parent.is_gs1_nomenclature" invisible="gs1_content_type != ''measure''"/>
                </xpath>
            </data>', false, true, '2026-05-10 01:12:18.082543', '2026-05-10 01:12:18.082543', false);
INSERT INTO public.ir_ui_view VALUES (946, 16, 943, 1, 1, 'Barcode Nomenclatures', 'barcode.nomenclature', NULL, 'tree', 'barcodes_gs1_nomenclature/views/barcodes_view.xml', 'extension', '{"en_US": "<xpath expr=\"//field[@name=''name'']\" position=\"after\">\n                    <field name=\"is_gs1_nomenclature\"/>\n                </xpath>"}', '<?xml version="1.0"?>
<xpath expr="//field[@name=''name'']" position="after">
                    <field name="is_gs1_nomenclature"/>
                </xpath>
            ', false, true, '2026-05-10 01:12:18.082543', '2026-05-10 01:12:18.082543', false);
INSERT INTO public.ir_ui_view VALUES (947, 16, 944, 1, 1, 'Barcode Rule', 'barcode.rule', NULL, 'form', 'barcodes_gs1_nomenclature/views/barcodes_view.xml', 'extension', '{"en_US": "<data><xpath expr=\"//field[@name=''encoding'']\" position=\"attributes\">\n                    <attribute name=\"invisible\">parent.is_gs1_nomenclature or type == ''alias''</attribute>\n                </xpath>\n                <xpath expr=\"//field[@name=''alias'']\" position=\"after\">\n                    <field name=\"gs1_content_type\" invisible=\"not parent.is_gs1_nomenclature\"/>\n                    <field name=\"gs1_decimal_usage\" invisible=\"not parent.is_gs1_nomenclature or gs1_content_type != ''measure''\"/>\n                    <field name=\"associated_uom_id\" invisible=\"not parent.is_gs1_nomenclature or gs1_content_type != ''measure''\"/>\n                    <field name=\"is_gs1_nomenclature\" invisible=\"1\"/>\n                </xpath>\n            </data>"}', '<?xml version="1.0"?>
<data><xpath expr="//field[@name=''encoding'']" position="attributes">
                    <attribute name="invisible">parent.is_gs1_nomenclature or type == ''alias''</attribute>
                </xpath>
                <xpath expr="//field[@name=''alias'']" position="after">
                    <field name="gs1_content_type" invisible="not parent.is_gs1_nomenclature"/>
                    <field name="gs1_decimal_usage" invisible="not parent.is_gs1_nomenclature or gs1_content_type != ''measure''"/>
                    <field name="associated_uom_id" invisible="not parent.is_gs1_nomenclature or gs1_content_type != ''measure''"/>
                    <field name="is_gs1_nomenclature" invisible="1"/>
                </xpath>
            </data>', false, true, '2026-05-10 01:12:18.082543', '2026-05-10 01:12:18.082543', false);
INSERT INTO public.ir_ui_view VALUES (948, 16, NULL, 1, 1, 'track_move_template', NULL, 'stock.track_move_template', 'qweb', 'stock/data/mail_templates.xml', 'primary', '{"en_US": "<t t-name=\"stock.track_move_template\">\n        <div>\n            <t t-call=\"stock.message_head\"/>\n            <t t-call=\"stock.message_body\"/>\n        </div>\n    </t>"}', '<?xml version="1.0"?>
<t t-name="stock.track_move_template">
        <div>
            <t t-call="stock.message_head"/>
            <t t-call="stock.message_body"/>
        </div>
    </t>

    ', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (949, 16, NULL, 1, 1, 'exception_on_picking', NULL, 'stock.exception_on_picking', 'qweb', 'stock/data/mail_templates.xml', 'primary', '{"en_US": "<t t-name=\"stock.exception_on_picking\">\n        <div> Exception(s) occurred on the picking\n            <a href=\"#\" data-oe-model=\"stock.picking\" t-att-data-oe-id=\"origin_picking.id\"><t t-esc=\"origin_picking.name\"/></a>.\n            Manual actions may be needed.\n            <div class=\"mt16\">\n                <p>Exception(s):</p>\n                <ul t-foreach=\"moves_information\" t-as=\"exception\">\n                    <t t-set=\"move\" t-value=\"exception[0]\"/>\n                    <t t-set=\"new_qty\" t-value=\"exception[1][0]\"/>\n                    <t t-set=\"old_qty\" t-value=\"exception[1][1]\"/>\n                    <li><t t-esc=\"new_qty\"/> <t t-esc=\"move.product_uom.name\"/>\n                    of <t t-esc=\"move.product_id.display_name\"/> processed instead of <t t-esc=\"old_qty\"/> <t t-esc=\"move.product_uom.name\"/></li>\n                </ul>\n            </div>\n            <div class=\"mt16\" t-if=\"impacted_pickings\">\n                <p>Next transfer(s) impacted:</p>\n                <ul t-foreach=\"impacted_pickings\" t-as=\"picking\">\n                    <li><a href=\"#\" data-oe-model=\"stock.picking\" t-att-data-oe-id=\"picking.id\"><t t-esc=\"picking.name\"/></a></li>\n                </ul>\n            </div>\n        </div>\n    </t>"}', '<?xml version="1.0"?>
<t t-name="stock.exception_on_picking">
        <div> Exception(s) occurred on the picking
            <a href="#" data-oe-model="stock.picking" t-att-data-oe-id="origin_picking.id"><t t-esc="origin_picking.name"/></a>.
            Manual actions may be needed.
            <div class="mt16">
                <p>Exception(s):</p>
                <ul t-foreach="moves_information" t-as="exception">
                    <t t-set="move" t-value="exception[0]"/>
                    <t t-set="new_qty" t-value="exception[1][0]"/>
                    <t t-set="old_qty" t-value="exception[1][1]"/>
                    <li><t t-esc="new_qty"/> <t t-esc="move.product_uom.name"/>
                    of <t t-esc="move.product_id.display_name"/> processed instead of <t t-esc="old_qty"/> <t t-esc="move.product_uom.name"/></li>
                </ul>
            </div>
            <div class="mt16" t-if="impacted_pickings">
                <p>Next transfer(s) impacted:</p>
                <ul t-foreach="impacted_pickings" t-as="picking">
                    <li><a href="#" data-oe-model="stock.picking" t-att-data-oe-id="picking.id"><t t-esc="picking.name"/></a></li>
                </ul>
            </div>
        </div>
    </t>
', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (950, 16, NULL, 1, 1, 'stock_report_view_graph', 'report.stock.quantity', NULL, 'graph', 'stock/report/report_stock_quantity.xml', 'primary', '{"en_US": "<graph string=\"report_stock_quantity_graph\" type=\"line\" sample=\"1\" disable_linking=\"1\">\n                    <field name=\"date\" interval=\"day\"/>\n                    <field name=\"product_id\"/>\n                    <field name=\"product_qty\" type=\"measure\"/>\n            </graph>"}', '<?xml version="1.0"?>
<graph string="report_stock_quantity_graph" type="line" sample="1" disable_linking="1">
                    <field name="date" interval="day"/>
                    <field name="product_id"/>
                    <field name="product_qty" type="measure"/>
            </graph>
        ', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (968, 16, NULL, 1, 1, 'report_inventory', NULL, 'stock.report_inventory', 'qweb', 'stock/report/report_stockinventory.xml', 'primary', '{"en_US": "<t t-name=\"stock.report_inventory\">\n            <t t-call=\"web.html_container\">\n                <div class=\"oe_structure\"/>\n                <t t-call=\"web.external_layout\">\n                    <div class=\"page\">\n                        <br/>\n                        <h2>Inventory Count Sheet</h2>\n                        <t t-set=\"locations\" t-value=\"docs.mapped(''location_id'')\"/>\n                        <div class=\"oe_structure\"/>\n                        <table class=\"table table-sm\">\n                            <thead>\n                                <tr>\n                                    <th groups=\"stock.group_stock_multi_locations\"><strong>Location</strong></th>\n                                    <th><strong>Product</strong></th>\n                                    <th groups=\"stock.group_production_lot\"><strong>Lot/Serial Number</strong></th>\n                                    <th groups=\"stock.group_tracking_lot\"><strong>Package</strong></th>\n                                    <th class=\"text-end\"><strong>Available Quantity</strong></th>\n                                    <th class=\"text-end\"><strong>On hand Quantity</strong></th>\n                                    <th class=\"text-end\"><strong>Counted Quantity</strong></th>\n                                </tr>\n                            </thead>\n                            <tbody>\n                                <t t-foreach=\"locations\" t-as=\"location\">\n                                    <tr groups=\"stock.group_stock_multi_locations\">\n                                        <td colspan=\"2\"><span t-out=\"location.display_name\">Shelf A</span></td>\n                                        <td groups=\"stock.group_production_lot\"/>\n                                        <td groups=\"stock.group_tracking_lot\"/>\n                                        <td/>\n                                    </tr>\n                                    <tr t-foreach=\"docs.filtered(lambda quant: quant.location_id.id == location.id)\" t-as=\"line\">\n                                        <td groups=\"stock.group_stock_multi_locations\"/>\n                                        <td><span t-field=\"line.product_id\">Laptop</span></td>\n                                        <td groups=\"stock.group_production_lot\"><span t-field=\"line.lot_id\"/></td>\n                                        <td groups=\"stock.group_tracking_lot\"><span t-field=\"line.package_id\"/></td>\n                                        <td class=\"text-end\"><span t-field=\"line.available_quantity\">2</span> <span t-field=\"line.product_uom_id\" groups=\"uom.group_uom\">Units</span></td>\n                                        <td class=\"text-end\"><span t-field=\"line.quantity\">5</span> <span t-field=\"line.product_uom_id\" groups=\"uom.group_uom\">Units</span></td>\n                                        <td class=\"text-end\">\n                                            <!-- If 0, then leave blank so users have space to write a number -->\n                                            <t t-if=\"line.inventory_quantity == 0\"><span/></t>\n                                            <t t-else=\"\"><span t-field=\"line.inventory_quantity\">7</span></t>\n                                            <span t-field=\"line.product_uom_id\" groups=\"uom.group_uom\">Units</span>\n                                        </td>\n                                    </tr>\n                                </t>\n                            </tbody>\n                        </table>\n                        <div class=\"oe_structure\"/>\n                    </div>\n                </t>\n            </t>\n        </t>"}', '<?xml version="1.0"?>
<t t-name="stock.report_inventory">
            <t t-call="web.html_container">
                <div class="oe_structure"/>
                <t t-call="web.external_layout">
                    <div class="page">
                        <br/>
                        <h2>Inventory Count Sheet</h2>
                        <t t-set="locations" t-value="docs.mapped(''location_id'')"/>
                        <div class="oe_structure"/>
                        <table class="table table-sm">
                            <thead>
                                <tr>
                                    <th groups="stock.group_stock_multi_locations"><strong>Location</strong></th>
                                    <th><strong>Product</strong></th>
                                    <th groups="stock.group_production_lot"><strong>Lot/Serial Number</strong></th>
                                    <th groups="stock.group_tracking_lot"><strong>Package</strong></th>
                                    <th class="text-end"><strong>Available Quantity</strong></th>
                                    <th class="text-end"><strong>On hand Quantity</strong></th>
                                    <th class="text-end"><strong>Counted Quantity</strong></th>
                                </tr>
                            </thead>
                            <tbody>
                                <t t-foreach="locations" t-as="location">
                                    <tr groups="stock.group_stock_multi_locations">
                                        <td colspan="2"><span t-out="location.display_name">Shelf A</span></td>
                                        <td groups="stock.group_production_lot"/>
                                        <td groups="stock.group_tracking_lot"/>
                                        <td/>
                                    </tr>
                                    <tr t-foreach="docs.filtered(lambda quant: quant.location_id.id == location.id)" t-as="line">
                                        <td groups="stock.group_stock_multi_locations"/>
                                        <td><span t-field="line.product_id">Laptop</span></td>
                                        <td groups="stock.group_production_lot"><span t-field="line.lot_id"/></td>
                                        <td groups="stock.group_tracking_lot"><span t-field="line.package_id"/></td>
                                        <td class="text-end"><span t-field="line.available_quantity">2</span> <span t-field="line.product_uom_id" groups="uom.group_uom">Units</span></td>
                                        <td class="text-end"><span t-field="line.quantity">5</span> <span t-field="line.product_uom_id" groups="uom.group_uom">Units</span></td>
                                        <td class="text-end">
                                            <!-- If 0, then leave blank so users have space to write a number -->
                                            <t t-if="line.inventory_quantity == 0"><span/></t>
                                            <t t-else=""><span t-field="line.inventory_quantity">7</span></t>
                                            <span t-field="line.product_uom_id" groups="uom.group_uom">Units</span>
                                        </td>
                                    </tr>
                                </t>
                            </tbody>
                        </table>
                        <div class="oe_structure"/>
                    </div>
                </t>
            </t>
        </t>
    ', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (951, 16, NULL, 1, 1, 'report_reception_report_label', NULL, 'stock.report_reception_report_label', 'qweb', 'stock/report/report_stock_reception.xml', 'primary', '{"en_US": "<t t-name=\"stock.report_reception_report_label\">\n        <t t-if=\"quantity\" t-set=\"qtys\" t-value=\"[int(q) for q in quantity.split('','')]\"/>\n        <t t-else=\"\" t-set=\"qtys\" t-value=\"[1 for q in range(len(docs))]\"/>\n        <t t-call=\"web.basic_layout\">\n            <div class=\"page\">\n                <t t-foreach=\"range(len(docs))\" t-as=\"index\">\n                    <t t-set=\"move\" t-value=\"docs[index]\"/>\n                    <t t-set=\"qty\" t-value=\"qtys[index]\"/>\n                    <t t-set=\"source\" t-value=\"move._get_source_document()\"/>\n                    <t t-foreach=\"range(qty)\" t-as=\"j\">\n                        <div class=\"o_label_page o_label_dymo\">\n                            <span t-out=\"move.product_id.display_name\">Product Display Name</span> <br/>\n                            <span t-if=\"source\" t-out=\"source.name\">Source Name</span>\n                            <div class=\"address\" t-if=\"move.picking_id and move.picking_id.partner_id\" t-field=\"move.picking_id.partner_id\" t-options=\"{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;, &quot;phone&quot;], &quot;no_marker&quot;: True}\"/>\n                        </div>\n                    </t>\n                </t>\n            </div>\n        </t>\n    </t>"}', '<?xml version="1.0"?>
<t t-name="stock.report_reception_report_label">
        <t t-if="quantity" t-set="qtys" t-value="[int(q) for q in quantity.split('','')]"/>
        <t t-else="" t-set="qtys" t-value="[1 for q in range(len(docs))]"/>
        <t t-call="web.basic_layout">
            <div class="page">
                <t t-foreach="range(len(docs))" t-as="index">
                    <t t-set="move" t-value="docs[index]"/>
                    <t t-set="qty" t-value="qtys[index]"/>
                    <t t-set="source" t-value="move._get_source_document()"/>
                    <t t-foreach="range(qty)" t-as="j">
                        <div class="o_label_page o_label_dymo">
                            <span t-out="move.product_id.display_name">Product Display Name</span> <br/>
                            <span t-if="source" t-out="source.name">Source Name</span>
                            <div class="address" t-if="move.picking_id and move.picking_id.partner_id" t-field="move.picking_id.partner_id" t-options="{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;, &quot;phone&quot;], &quot;no_marker&quot;: True}"/>
                        </div>
                    </t>
                </t>
            </div>
        </t>
    </t>

    ', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (952, 16, NULL, 1, 1, 'report_reception_body', NULL, 'stock.report_reception_body', 'qweb', 'stock/report/report_stock_reception.xml', 'primary', '{"en_US": "<t t-name=\"stock.report_reception_body\">\n        <div class=\"o_report_reception justify-content-between\">\n            <div class=\"o_report_reception_header my-5\">\n                <h3>\n                    <t t-if=\"docs\">\n                        <t t-foreach=\"docs\" t-as=\"doc\">\n                            <div class=\"p-2\">\n                                <a href=\"#\" t-att-res-model=\"doc_model\" view-type=\"form\" t-att-res-id=\"doc.id\">\n                                    <span t-out=\"doc.display_name\">Demo Display Name</span>\n                                </a>\n                                <span t-field=\"doc.display_name\" t-options=\"{''widget'': ''barcode'', ''width'': 300, ''height'': 50}\">Display Name</span>\n                                <span t-field=\"doc.state\" t-attf-class=\"badge rounded-pill bg-opacity-50 #{''bg-success'' if doc.state == ''done'' else ''bg-info''}\">Andrwep</span>\n                            </div>\n                        </t>\n                    </t>\n                    <t t-else=\"\">\n                        <span t-out=\"reason\">Reason</span>\n                    </t>\n                </h3>\n            </div>\n            <table t-if=\"sources_to_lines\" class=\"o_report_reception_table table table-sm text-start\">\n                <t t-foreach=\"sources_to_lines\" t-as=\"source\">\n                    <thead t-if=\"any(line[''is_assigned''] for line in sources_to_lines[source])\">\n                        <tr class=\"bg-light\">\n                            <th>\n                                <span t-field=\"source[0].display_name\" t-options=\"{''widget'': ''barcode'', ''width'': 200, ''height'': 30}\">Display Name</span>\n                                <i t-if=\"source[0].priority == ''1''\" class=\"o_priority o_priority_star fa fa-star\"/>\n                                <a name=\"source_link\" href=\"#\" t-att-res-model=\"source[0]._name\" view-type=\"form\" t-att-res-id=\"source[0].id\">\n                                    <span t-out=\"source[0].display_name\">DEMO_SOURCE_DISPLAY_NAME</span>\n                                </a>\n                                <span t-if=\"len(source) &gt; 1\">\n                                    (<a name=\"origin_link\" href=\"#\" t-att-res-model=\"source[1]._name\" view-type=\"form\" t-att-res-id=\"source[1].id\">\n                                    <span t-out=\"source[1].display_name\">DEMO_ORIGIN_DISPLAY_NAME</span></a>)\n                                </span>\n                                <span t-if=\"source[0]._name == ''stock.picking'' and source[0].partner_id\">:\n                                    <a name=\"source_link\" href=\"#\" t-att-res-model=\"source[0].partner_id._name\" t-att-res-id=\"source[0].partner_id.id\" view-type=\"form\">\n                                        <span t-out=\"source[0].partner_id.name\">DEMO_PARTNER_NAME</span>\n                                    </a>\n                                </span>\n                            </th>\n                            <th>Expected Delivery: <span t-out=\"sources_to_formatted_scheduled_date[source]\">DEMO_DATE</span></th>\n                        </tr>\n                    </thead>\n                    <tbody>\n                        <t t-set=\"possible_moves\" t-value=\"sources_to_lines[source]\"/>\n                        <t t-foreach=\"possible_moves\" t-as=\"line\">\n                            <!-- don''t print non-assigned lines when printing pdf -->\n                            <tr t-if=\"line[''is_assigned'']\">\n                                <td>\n                                    <span t-out=\"line[''product''][''display_name'']\">DEMO_PRODUCT_DISPLAY_NAME</span>\n                                </td>\n                                <td>\n                                    <span t-out=\"line[''quantity'']\">DEMO_QUANTITY</span>\n                                    <span groups=\"uom.group_uom\" t-out=\"line[''uom'']\">DEMO_UOM</span>\n                                </td>\n                            </tr>\n                        </t>\n                    </tbody>\n                </t>\n            </table>\n            <p t-else=\"\">\n                No allocation need found.\n            </p>\n        </div>\n    </t>"}', '<?xml version="1.0"?>
<t t-name="stock.report_reception_body">
        <div class="o_report_reception justify-content-between">
            <div class="o_report_reception_header my-5">
                <h3>
                    <t t-if="docs">
                        <t t-foreach="docs" t-as="doc">
                            <div class="p-2">
                                <a href="#" t-att-res-model="doc_model" view-type="form" t-att-res-id="doc.id">
                                    <span t-out="doc.display_name">Demo Display Name</span>
                                </a>
                                <span t-field="doc.display_name" t-options="{''widget'': ''barcode'', ''width'': 300, ''height'': 50}">Display Name</span>
                                <span t-field="doc.state" t-attf-class="badge rounded-pill bg-opacity-50 #{''bg-success'' if doc.state == ''done'' else ''bg-info''}">Andrwep</span>
                            </div>
                        </t>
                    </t>
                    <t t-else="">
                        <span t-out="reason">Reason</span>
                    </t>
                </h3>
            </div>
            <table t-if="sources_to_lines" class="o_report_reception_table table table-sm text-start">
                <t t-foreach="sources_to_lines" t-as="source">
                    <thead t-if="any(line[''is_assigned''] for line in sources_to_lines[source])">
                        <tr class="bg-light">
                            <th>
                                <span t-field="source[0].display_name" t-options="{''widget'': ''barcode'', ''width'': 200, ''height'': 30}">Display Name</span>
                                <i t-if="source[0].priority == ''1''" class="o_priority o_priority_star fa fa-star"/>
                                <a name="source_link" href="#" t-att-res-model="source[0]._name" view-type="form" t-att-res-id="source[0].id">
                                    <span t-out="source[0].display_name">DEMO_SOURCE_DISPLAY_NAME</span>
                                </a>
                                <span t-if="len(source) &gt; 1">
                                    (<a name="origin_link" href="#" t-att-res-model="source[1]._name" view-type="form" t-att-res-id="source[1].id">
                                    <span t-out="source[1].display_name">DEMO_ORIGIN_DISPLAY_NAME</span></a>)
                                </span>
                                <span t-if="source[0]._name == ''stock.picking'' and source[0].partner_id">:
                                    <a name="source_link" href="#" t-att-res-model="source[0].partner_id._name" t-att-res-id="source[0].partner_id.id" view-type="form">
                                        <span t-out="source[0].partner_id.name">DEMO_PARTNER_NAME</span>
                                    </a>
                                </span>
                            </th>
                            <th>Expected Delivery: <span t-out="sources_to_formatted_scheduled_date[source]">DEMO_DATE</span></th>
                        </tr>
                    </thead>
                    <tbody>
                        <t t-set="possible_moves" t-value="sources_to_lines[source]"/>
                        <t t-foreach="possible_moves" t-as="line">
                            <!-- don''t print non-assigned lines when printing pdf -->
                            <tr t-if="line[''is_assigned'']">
                                <td>
                                    <span t-out="line[''product''][''display_name'']">DEMO_PRODUCT_DISPLAY_NAME</span>
                                </td>
                                <td>
                                    <span t-out="line[''quantity'']">DEMO_QUANTITY</span>
                                    <span groups="uom.group_uom" t-out="line[''uom'']">DEMO_UOM</span>
                                </td>
                            </tr>
                        </t>
                    </tbody>
                </t>
            </table>
            <p t-else="">
                No allocation need found.
            </p>
        </div>
    </t>

    ', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (953, 16, NULL, 1, 1, 'report_reception', NULL, 'stock.report_reception', 'qweb', 'stock/report/report_stock_reception.xml', 'primary', '{"en_US": "<t t-name=\"stock.report_reception\">\n        <t t-call=\"web.html_container\">\n            <t t-call=\"web.internal_layout\">\n                <t t-call=\"stock.report_reception_body\"/>\n            </t>\n        </t>\n    </t>"}', '<?xml version="1.0"?>
<t t-name="stock.report_reception">
