', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (954, 16, NULL, 1, 1, 'report_package_barcode', NULL, 'stock.report_package_barcode', 'qweb', 'stock/report/report_package_barcode.xml', 'primary', '{"en_US": "<t t-name=\"stock.report_package_barcode\">\n    <t t-call=\"web.basic_layout\">\n        <!-- quantity patterns are always 3 digit codes + 1 digit for number of digits (excluding units) -->\n        <t t-set=\"uom_unit_id\" t-value=\"env.ref(''uom.product_uom_unit'').id\"/>\n        <t t-set=\"gs1_uom_patterns\" t-value=\"{rule.associated_uom_id.id: rule.pattern[1:4] + str(len(str(''{:.10f}''.format(rule.associated_uom_id.rounding).rstrip(''0'')).split(''.'')[1])) for rule in env[''barcode.rule''].search([(''associated_uom_id'', ''!='', False), (''associated_uom_id.id'', ''!='', uom_unit_id), (''is_gs1_nomenclature'', ''='', True)])}\"/>\n        <t t-foreach=\"docs\" t-as=\"o\">\n            <t>\n                <div class=\"page\">\n                    <div class=\"oe_structure\"/>\n                    <div class=\"row mb-5\">\n                        <div class=\"col-6\">\n                            <h1><span t-field=\"o.name\" class=\"mt0 float-start\">Package Reference</span></h1>\n                        </div>\n                        <div class=\"col-6 d-flex flex-column justify-content-center align-item-center\" t-if=\"o.valid_sscc\">\n                            <t t-set=\"barcode\" t-value=\"''00'' + o.name\"/>\n                            <t t-if=\"o.pack_date\" t-set=\"barcode\" t-value=\"barcode + ''13'' + o.pack_date.strftime(''%y%m%d'')\"/>\n                            <div name=\"datamatrix_barcode\" t-out=\"barcode\" t-options=\"{''widget'': ''barcode'', ''symbology'': ''ECC200DataMatrix'', ''width'': 100, ''height'': 100}\">\n                                <div class=\"bg-light border-1 rounded d-flex flex-column align-items-center justify-content-center px-1 py-2 opacity-75 text-muted text-center\">\n                                    (package barcode)\n                                </div>\n                            </div>\n                        </div>\n                        <div t-else=\"\" class=\"col-6 d-flex flex-column justify-content-center align-item-center text-center\">\n                            <div t-field=\"o.name\" t-options=\"{''widget'': ''barcode'', ''width'': 600, ''height'': 100, ''img_style'': ''width:300px;height:50px;''}\">\n                                <div class=\"bg-light border-1 rounded d-flex flex-column align-items-center justify-content-center px-1 py-2 opacity-75 text-muted text-center\">\n                                    (package barcode)\n                                </div>\n                            </div>\n                            <span t-field=\"o.name\">Package Reference</span>\n                        </div>\n                    </div>\n                    <div class=\"oe_structure\"/>\n                    <div class=\"row mt32 mb32\">\n                        <div t-if=\"o.pack_date\" class=\"col-auto\">\n                            <strong>Pack Date:</strong>\n                            <span t-field=\"o.pack_date\">2021-9-01</span>\n                        </div>\n                        <div t-if=\"o.package_type_id\" class=\"o_packaging_type col-auto\">\n                            <strong>Package Type:</strong>\n                            <span t-field=\"o.package_type_id.name\">Pallet</span>\n                        </div>\n                    </div>\n                    <div class=\"oe_structure\"/>\n                    <t t-set=\"has_serial_number\" t-value=\"o.quant_ids.mapped(''lot_id'')\"/>\n                    <t t-set=\"has_ean_barcode\" t-value=\"any(valid_ean for valid_ean in o.quant_ids.product_id.mapped(''valid_ean''))\"/>\n                    <table class=\"table table-sm table-striped\">\n                        <thead>\n                            <tr>\n                                <th>Product</th>\n                                <th name=\"th_quantity\" class=\"text-end\">Quantity</th>\n                                <th name=\"th_uom\" groups=\"uom.group_uom\"/>\n                                <th name=\"th_serial\" class=\"text-end\" t-if=\"has_serial_number\">Lot/Serial Number</th>\n                                <th name=\"th_barcode\" class=\"text-end\" t-if=\"has_ean_barcode\"/>\n                            </tr>\n                        </thead>\n                        <tbody>\n                            <tr t-foreach=\"o.quant_ids\" t-as=\"l\">\n                                <td>\n                                   <span t-field=\"l.product_id.name\">Customizable Desk</span>\n                                </td>\n                                <td class=\"text-end\">\n                                    <span t-field=\"l.quantity\">3.00</span>\n                                </td>\n                                <td groups=\"uom.group_uom\">\n                                    <span t-field=\"l.product_id.uom_id.name\">units</span>\n                                </td>\n                                <td class=\"text-end\" t-if=\"has_serial_number\">\n                                    <t t-if=\"l.lot_id\"><span t-field=\"l.lot_id.name\">54326786758</span></t>\n                                </td>\n                                <td class=\"text-end\" t-if=\"has_ean_barcode\">\n                                    <t t-if=\"l.product_id.valid_ean\">\n                                        <t t-set=\"product_barcode\" t-value=\"''01'' + ''0'' * (14 - len(l.product_id.barcode)) + l.product_id.barcode\"/>\n                                        <t t-set=\"gs1_pattern\" t-value=\"gs1_uom_patterns.get(l.product_uom_id.id, False)\"/>\n                                        <t t-if=\"(gs1_pattern or l.product_uom_id.id == uom_unit_id) and l.quantity &gt;= 0\">\n                                            <t t-if=\"gs1_pattern\">\n                                                <t t-set=\"qty_str\" t-value=\"str(int(l.quantity/l.product_uom_id.rounding))\"/>\n                                                <t t-if=\"len(qty_str) &lt;= 6\" t-set=\"product_barcode\" t-value=\"product_barcode + gs1_pattern +  ''0'' * (6 - len(qty_str)) + qty_str\"/>\n                                            </t>\n                                            <t t-else=\"\">\n                                                <!-- GS1 have no decimal indicator for unit uom => round for now.. -->\n                                                <t t-set=\"qty_str\" t-value=\"str(int(round(l.quantity)))\"/>\n                                                <t t-if=\"len(qty_str) &lt;=8\" t-set=\"product_barcode\" t-value=\"product_barcode + ''30'' +  ''0'' * (8 - len(qty_str)) + qty_str\"/>\n                                            </t>\n                                        </t>\n                                        <!-- TODO: lot/sn ALWAYS has to be last part of barcode since left padding ''0''s = different sn/lot name match when scanning => fix when FNC1 can be used,  -->\n                                        <t name=\"product_barcode_lot_datamatrix\" t-if=\"l.product_id.tracking == ''lot'' and l.lot_id\" t-set=\"product_barcode\" t-value=\"product_barcode + ''10'' + l.lot_id.name\"/>\n                                        <t t-elif=\"l.product_id.tracking == ''serial'' and l.lot_id\" t-set=\"product_barcode\" t-value=\"product_barcode + ''21'' +  l.lot_id.name\"/>\n                                        <span t-out=\"product_barcode\" t-options=\"{''widget'': ''barcode'', ''symbology'': ''ECC200DataMatrix'', ''img_style'': ''width:17mm;height:17mm''}\">\n                                            <div class=\"bg-light border-1 rounded d-flex flex-column align-items-center justify-content-center px-1 py-2 opacity-75 text-muted text-center\">\n                                                (product barcode)\n                                            </div>\n                                        </span>\n                                    </t>\n                                </td>\n                            </tr>\n                        </tbody>\n                    </table>\n                </div>\n            </t>\n        </t>\n    </t>\n</t>"}', '<?xml version="1.0"?>
<t t-name="stock.report_package_barcode">
    <t t-call="web.basic_layout">
        <!-- quantity patterns are always 3 digit codes + 1 digit for number of digits (excluding units) -->
        <t t-set="uom_unit_id" t-value="env.ref(''uom.product_uom_unit'').id"/>
        <t t-set="gs1_uom_patterns" t-value="{rule.associated_uom_id.id: rule.pattern[1:4] + str(len(str(''{:.10f}''.format(rule.associated_uom_id.rounding).rstrip(''0'')).split(''.'')[1])) for rule in env[''barcode.rule''].search([(''associated_uom_id'', ''!='', False), (''associated_uom_id.id'', ''!='', uom_unit_id), (''is_gs1_nomenclature'', ''='', True)])}"/>
        <t t-foreach="docs" t-as="o">
            <t>
                <div class="page">
                    <div class="oe_structure"/>
                    <div class="row mb-5">
                        <div class="col-6">
                            <h1><span t-field="o.name" class="mt0 float-start">Package Reference</span></h1>
                        </div>
                        <div class="col-6 d-flex flex-column justify-content-center align-item-center" t-if="o.valid_sscc">
                            <t t-set="barcode" t-value="''00'' + o.name"/>
                            <t t-if="o.pack_date" t-set="barcode" t-value="barcode + ''13'' + o.pack_date.strftime(''%y%m%d'')"/>
                            <div name="datamatrix_barcode" t-out="barcode" t-options="{''widget'': ''barcode'', ''symbology'': ''ECC200DataMatrix'', ''width'': 100, ''height'': 100}">
                                <div class="bg-light border-1 rounded d-flex flex-column align-items-center justify-content-center px-1 py-2 opacity-75 text-muted text-center">
                                    (package barcode)
                                </div>
                            </div>
                        </div>
                        <div t-else="" class="col-6 d-flex flex-column justify-content-center align-item-center text-center">
                            <div t-field="o.name" t-options="{''widget'': ''barcode'', ''width'': 600, ''height'': 100, ''img_style'': ''width:300px;height:50px;''}">
                                <div class="bg-light border-1 rounded d-flex flex-column align-items-center justify-content-center px-1 py-2 opacity-75 text-muted text-center">
                                    (package barcode)
                                </div>
                            </div>
                            <span t-field="o.name">Package Reference</span>
                        </div>
                    </div>
                    <div class="oe_structure"/>
                    <div class="row mt32 mb32">
                        <div t-if="o.pack_date" class="col-auto">
                            <strong>Pack Date:</strong>
                            <span t-field="o.pack_date">2021-9-01</span>
                        </div>
                        <div t-if="o.package_type_id" class="o_packaging_type col-auto">
                            <strong>Package Type:</strong>
                            <span t-field="o.package_type_id.name">Pallet</span>
                        </div>
                    </div>
                    <div class="oe_structure"/>
                    <t t-set="has_serial_number" t-value="o.quant_ids.mapped(''lot_id'')"/>
                    <t t-set="has_ean_barcode" t-value="any(valid_ean for valid_ean in o.quant_ids.product_id.mapped(''valid_ean''))"/>
                    <table class="table table-sm table-striped">
                        <thead>
                            <tr>
                                <th>Product</th>
                                <th name="th_quantity" class="text-end">Quantity</th>
                                <th name="th_uom" groups="uom.group_uom"/>
                                <th name="th_serial" class="text-end" t-if="has_serial_number">Lot/Serial Number</th>
                                <th name="th_barcode" class="text-end" t-if="has_ean_barcode"/>
                            </tr>
                        </thead>
                        <tbody>
                            <tr t-foreach="o.quant_ids" t-as="l">
                                <td>
                                   <span t-field="l.product_id.name">Customizable Desk</span>
                                </td>
                                <td class="text-end">
                                    <span t-field="l.quantity">3.00</span>
                                </td>
                                <td groups="uom.group_uom">
                                    <span t-field="l.product_id.uom_id.name">units</span>
                                </td>
                                <td class="text-end" t-if="has_serial_number">
                                    <t t-if="l.lot_id"><span t-field="l.lot_id.name">54326786758</span></t>
                                </td>
                                <td class="text-end" t-if="has_ean_barcode">
                                    <t t-if="l.product_id.valid_ean">
                                        <t t-set="product_barcode" t-value="''01'' + ''0'' * (14 - len(l.product_id.barcode)) + l.product_id.barcode"/>
                                        <t t-set="gs1_pattern" t-value="gs1_uom_patterns.get(l.product_uom_id.id, False)"/>
                                        <t t-if="(gs1_pattern or l.product_uom_id.id == uom_unit_id) and l.quantity &gt;= 0">
                                            <t t-if="gs1_pattern">
                                                <t t-set="qty_str" t-value="str(int(l.quantity/l.product_uom_id.rounding))"/>
                                                <t t-if="len(qty_str) &lt;= 6" t-set="product_barcode" t-value="product_barcode + gs1_pattern +  ''0'' * (6 - len(qty_str)) + qty_str"/>
                                            </t>
                                            <t t-else="">
                                                <!-- GS1 have no decimal indicator for unit uom => round for now.. -->
                                                <t t-set="qty_str" t-value="str(int(round(l.quantity)))"/>
                                                <t t-if="len(qty_str) &lt;=8" t-set="product_barcode" t-value="product_barcode + ''30'' +  ''0'' * (8 - len(qty_str)) + qty_str"/>
                                            </t>
                                        </t>
                                        <!-- TODO: lot/sn ALWAYS has to be last part of barcode since left padding ''0''s = different sn/lot name match when scanning => fix when FNC1 can be used,  -->
                                        <t name="product_barcode_lot_datamatrix" t-if="l.product_id.tracking == ''lot'' and l.lot_id" t-set="product_barcode" t-value="product_barcode + ''10'' + l.lot_id.name"/>
                                        <t t-elif="l.product_id.tracking == ''serial'' and l.lot_id" t-set="product_barcode" t-value="product_barcode + ''21'' +  l.lot_id.name"/>
                                        <span t-out="product_barcode" t-options="{''widget'': ''barcode'', ''symbology'': ''ECC200DataMatrix'', ''img_style'': ''width:17mm;height:17mm''}">
                                            <div class="bg-light border-1 rounded d-flex flex-column align-items-center justify-content-center px-1 py-2 opacity-75 text-muted text-center">
                                                (product barcode)
                                            </div>
                                        </span>
                                    </t>
                                </td>
                            </tr>
                        </tbody>
                    </table>
                </div>
            </t>
        </t>
    </t>
</t>

', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (955, 16, NULL, 1, 1, 'report_package_barcode_small', NULL, 'stock.report_package_barcode_small', 'qweb', 'stock/report/report_package_barcode.xml', 'primary', '{"en_US": "<t t-name=\"stock.report_package_barcode_small\">\n    <t t-call=\"web.basic_layout\">\n        <t t-foreach=\"docs\" t-as=\"o\">\n            <t>\n                <div class=\"page\">\n                    <div class=\"oe_structure\"/>\n                    <t t-if=\"o.valid_sscc\">\n                        <div class=\"row\">\n                            <t t-set=\"barcode\" t-value=\"''00'' + o.name\"/>\n                            <t t-if=\"o.pack_date\" t-set=\"barcode\" t-value=\"barcode + ''13'' + o.pack_date.strftime(''%y%m%d'')\"/>\n                            <div class=\"col-5 text-end\" name=\"datamatrix_barcode\" style=\"margin: 0px 20px 40px 60px\">\n                                <span t-out=\"barcode\" t-options=\"{''widget'': ''barcode'', ''symbology'': ''ECC200DataMatrix'', ''width'': 200, ''height'': 200}\">Barcode Demo</span>\n                            </div>\n                            <div class=\"col-7 text-start\" style=\"font-size:20px;\">\n                                <div class=\"row\">SSCC: <span t-field=\"o.name\">SSCC Demo</span></div>\n                                <div t-if=\"o.pack_date\" class=\"row\">Pack Date: <span t-field=\"o.pack_date\">Pack Date Demo</span></div>\n                                <div t-if=\"o.package_type_id\" class=\"row\" name=\"datamatrix_pack_type\">Package Type: <span t-field=\"o.package_type_id.name\">Package Type Demo</span></div>\n                            </div>\n                        </div>\n                    </t>\n                    <t t-else=\"\">\n                        <div class=\"row\">\n                            <div class=\"text-center col-12\">\n                                <span t-field=\"o.name\" t-options=\"{''widget'': ''barcode'', ''width'': 600, ''height'': 100, ''img_style'': ''width:600px;height:100px;''}\">Name Demo</span>\n                                <span t-field=\"o.name\" style=\"font-size:20px; margin:100px; white-space: nowrap;\">Name Demo</span>\n                            </div>\n                        </div>\n                        <div t-if=\"o.pack_date\" class=\"col-12 text-center\" style=\"font-size:24px; font-weight:bold;\">Pack Date: <span t-field=\"o.pack_date\">2023-01-01</span></div>\n                        <div class=\"row o_packaging_type\" t-if=\"o.package_type_id\">\n                            <div class=\"col-12 text-center\" style=\"font-size:24px; font-weight:bold;\"><span>Package Type: </span><span t-field=\"o.package_type_id.name\">Package Type Demo</span></div>\n                        </div>\n                    </t>\n                    <div class=\"oe_structure\"/>\n                </div>\n            </t>\n        </t>\n    </t>\n</t>"}', '<?xml version="1.0"?>
<t t-name="stock.report_package_barcode_small">
    <t t-call="web.basic_layout">
        <t t-foreach="docs" t-as="o">
            <t>
                <div class="page">
                    <div class="oe_structure"/>
                    <t t-if="o.valid_sscc">
                        <div class="row">
                            <t t-set="barcode" t-value="''00'' + o.name"/>
                            <t t-if="o.pack_date" t-set="barcode" t-value="barcode + ''13'' + o.pack_date.strftime(''%y%m%d'')"/>
                            <div class="col-5 text-end" name="datamatrix_barcode" style="margin: 0px 20px 40px 60px">
                                <span t-out="barcode" t-options="{''widget'': ''barcode'', ''symbology'': ''ECC200DataMatrix'', ''width'': 200, ''height'': 200}">Barcode Demo</span>
                            </div>
                            <div class="col-7 text-start" style="font-size:20px;">
                                <div class="row">SSCC: <span t-field="o.name">SSCC Demo</span></div>
                                <div t-if="o.pack_date" class="row">Pack Date: <span t-field="o.pack_date">Pack Date Demo</span></div>
                                <div t-if="o.package_type_id" class="row" name="datamatrix_pack_type">Package Type: <span t-field="o.package_type_id.name">Package Type Demo</span></div>
                            </div>
                        </div>
                    </t>
                    <t t-else="">
                        <div class="row">
                            <div class="text-center col-12">
                                <span t-field="o.name" t-options="{''widget'': ''barcode'', ''width'': 600, ''height'': 100, ''img_style'': ''width:600px;height:100px;''}">Name Demo</span>
                                <span t-field="o.name" style="font-size:20px; margin:100px; white-space: nowrap;">Name Demo</span>
                            </div>
                        </div>
                        <div t-if="o.pack_date" class="col-12 text-center" style="font-size:24px; font-weight:bold;">Pack Date: <span t-field="o.pack_date">2023-01-01</span></div>
                        <div class="row o_packaging_type" t-if="o.package_type_id">
                            <div class="col-12 text-center" style="font-size:24px; font-weight:bold;"><span>Package Type: </span><span t-field="o.package_type_id.name">Package Type Demo</span></div>
                        </div>
                    </t>
                    <div class="oe_structure"/>
                </div>
            </t>
        </t>
    </t>
</t>

', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (956, 16, NULL, 1, 1, 'report_picking_packages', NULL, 'stock.report_picking_packages', 'qweb', 'stock/report/report_package_barcode.xml', 'primary', '{"en_US": "<t t-name=\"stock.report_picking_packages\">\n    <t t-set=\"docs\" t-value=\"docs.move_line_ids.mapped(''result_package_id'')\"/>\n    <t t-call=\"stock.report_package_barcode\"/>\n</t>"}', '<?xml version="1.0"?>
<t t-name="stock.report_picking_packages">
    <t t-set="docs" t-value="docs.move_line_ids.mapped(''result_package_id'')"/>
    <t t-call="stock.report_package_barcode"/>
</t>
', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (957, 16, NULL, 1, 1, 'report_lot_label', NULL, 'stock.report_lot_label', 'qweb', 'stock/report/report_lot_barcode.xml', 'primary', '{"en_US": "<t t-name=\"stock.report_lot_label\">\n    <t t-call=\"web.basic_layout\">\n        <t t-set=\"nRows\" t-value=\"12\"/>\n        <t t-set=\"nCols\" t-value=\"4\"/>\n        <div class=\"oe_structure\"/>\n        <div t-foreach=\"[docs[x:x + nRows * nCols] for x in range(0, len(docs), nRows * nCols)]\" t-as=\"page_docs\" class=\"o_label_sheet\" t-att-style=\"''padding: 20mm 8mm''\">\n            <table class=\"my-0 table table-sm table-borderless\">\n                <t t-foreach=\"range(nRows)\" t-as=\"row\">\n                    <tr>\n                        <t t-foreach=\"range(nCols)\" t-as=\"col\">\n                            <t t-set=\"barcode_index\" t-value=\"(row * nCols + col)\"/>\n                            <t t-if=\"barcode_index &lt; len(page_docs)\">\n                                <t t-set=\"o\" t-value=\"page_docs[barcode_index]\"/>\n                            </t>\n                            <t t-else=\"\">\n                                <t t-set=\"o\" t-value=\"page_docs[0]\"/>\n                            </t>\n                            <td t-att-style=\"barcode_index &gt;= len(page_docs) and ''visibility:hidden''\">\n                                <div t-att-style=\"''position:relative; width:43mm; height:19mm; border: 1px solid %s;'' % (o.env.user.company_id.primary_color or ''black'')\">\n                                    <t t-set=\"final_barcode\" t-value=\"''''\"/>\n                                    <t t-if=\"env.user.has_group(''stock.group_stock_lot_print_gs1'')\">\n                                        <t t-if=\"o.product_id.valid_ean\" t-set=\"final_barcode\" t-value=\"''01'' + ''0'' * (14 - len(o.product_id.barcode)) + o.product_id.barcode\"/>\n                                        <t name=\"gs1_datamatrix_lot\" t-if=\"o.product_id.tracking == ''lot''\" t-set=\"final_barcode\" t-value=\"(final_barcode or '''') + ''10'' + o.name\"/>\n                                        <t t-elif=\"o.product_id.tracking == ''serial''\" t-set=\"final_barcode\" t-value=\"(final_barcode or '''') + ''21'' + o.name\"/>\n                                    </t>\n                                    <div t-if=\"o.product_id.default_code\" class=\"o_label_4x12\" t-att-style=\"''width:22mm'' if final_barcode else ''''\">\n                                        <span class=\"o_label_4x12 lh-1\">[<t t-out=\"o.product_id.default_code\"/>]</span>\n                                    </div>\n                                    <div class=\"o_label_4x12\" t-att-style=\"''width:22mm'' if final_barcode else ''''\">\n                                        <span class=\"o_label_4x12 lh-1\" t-field=\"o.product_id.name\">Demo Product</span>\n                                    </div>\n                                    <div class=\"o_label_4x12\" name=\"lot_name\" t-att-style=\"''width:22mm; '' if final_barcode else ''''\">\n                                        <span class=\"o_label_4x12 lh-1\" name=\"lot_name\" t-field=\"o.name\">Demo Name</span>\n                                    </div>\n                                    <t t-if=\"env.user.has_group(''stock.group_stock_lot_print_gs1'')\">\n                                        <div t-if=\"final_barcode\" t-att-style=\"''position:absolute; right:.5px; bottom:.5px''\">\n                                            <span t-out=\"final_barcode\" t-options=\"{''widget'': ''barcode'', ''symbology'': ''ECC200DataMatrix'', ''img_style'': ''width:17mm; height:17mm''}\">12345678901</span>\n                                        </div>\n                                    </t>\n                                    <t t-else=\"\">\n                                        <span t-field=\"o.name\" t-options=\"{''widget'': ''barcode'', ''img_style'': ''width:100%; height:35%''}\">Customizable Desk</span>\n                                    </t>\n                                </div>\n                            </td>\n                        </t>\n                    </tr>\n                </t>\n            </table>\n            <div class=\"oe_structure\"/>\n        </div>\n    </t>\n</t>"}', '<?xml version="1.0"?>
<t t-name="stock.report_lot_label">
    <t t-call="web.basic_layout">
        <t t-set="nRows" t-value="12"/>
        <t t-set="nCols" t-value="4"/>
        <div class="oe_structure"/>
        <div t-foreach="[docs[x:x + nRows * nCols] for x in range(0, len(docs), nRows * nCols)]" t-as="page_docs" class="o_label_sheet" t-att-style="''padding: 20mm 8mm''">
            <table class="my-0 table table-sm table-borderless">
                <t t-foreach="range(nRows)" t-as="row">
                    <tr>
                        <t t-foreach="range(nCols)" t-as="col">
                            <t t-set="barcode_index" t-value="(row * nCols + col)"/>
                            <t t-if="barcode_index &lt; len(page_docs)">
                                <t t-set="o" t-value="page_docs[barcode_index]"/>
                            </t>
                            <t t-else="">
                                <t t-set="o" t-value="page_docs[0]"/>
                            </t>
                            <td t-att-style="barcode_index &gt;= len(page_docs) and ''visibility:hidden''">
                                <div t-att-style="''position:relative; width:43mm; height:19mm; border: 1px solid %s;'' % (o.env.user.company_id.primary_color or ''black'')">
                                    <t t-set="final_barcode" t-value="''''"/>
                                    <t t-if="env.user.has_group(''stock.group_stock_lot_print_gs1'')">
                                        <t t-if="o.product_id.valid_ean" t-set="final_barcode" t-value="''01'' + ''0'' * (14 - len(o.product_id.barcode)) + o.product_id.barcode"/>
                                        <t name="gs1_datamatrix_lot" t-if="o.product_id.tracking == ''lot''" t-set="final_barcode" t-value="(final_barcode or '''') + ''10'' + o.name"/>
                                        <t t-elif="o.product_id.tracking == ''serial''" t-set="final_barcode" t-value="(final_barcode or '''') + ''21'' + o.name"/>
                                    </t>
                                    <div t-if="o.product_id.default_code" class="o_label_4x12" t-att-style="''width:22mm'' if final_barcode else ''''">
                                        <span class="o_label_4x12 lh-1">[<t t-out="o.product_id.default_code"/>]</span>
                                    </div>
                                    <div class="o_label_4x12" t-att-style="''width:22mm'' if final_barcode else ''''">
                                        <span class="o_label_4x12 lh-1" t-field="o.product_id.name">Demo Product</span>
                                    </div>
                                    <div class="o_label_4x12" name="lot_name" t-att-style="''width:22mm; '' if final_barcode else ''''">
                                        <span class="o_label_4x12 lh-1" name="lot_name" t-field="o.name">Demo Name</span>
                                    </div>
                                    <t t-if="env.user.has_group(''stock.group_stock_lot_print_gs1'')">
                                        <div t-if="final_barcode" t-att-style="''position:absolute; right:.5px; bottom:.5px''">
                                            <span t-out="final_barcode" t-options="{''widget'': ''barcode'', ''symbology'': ''ECC200DataMatrix'', ''img_style'': ''width:17mm; height:17mm''}">12345678901</span>
                                        </div>
                                    </t>
                                    <t t-else="">
                                        <span t-field="o.name" t-options="{''widget'': ''barcode'', ''img_style'': ''width:100%; height:35%''}">Customizable Desk</span>
                                    </t>
                                </div>
                            </td>
                        </t>
                    </tr>
                </t>
            </table>
            <div class="oe_structure"/>
        </div>
    </t>
</t>
', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (958, 16, NULL, 1, 1, 'report_generic_barcode', NULL, 'stock.report_generic_barcode', 'qweb', 'stock/report/report_location_barcode.xml', 'primary', '{"en_US": "<t t-name=\"stock.report_generic_barcode\">\n    <t t-call=\"web.basic_layout\">\n        <t t-call=\"web.html_container\">\n            <div class=\"oe_structure\"/>\n            <t t-set=\"nRows\" t-value=\"7\"/>\n            <t t-set=\"nCols\" t-value=\"4\"/>\n            <t t-foreach=\"[docs[x:x + nRows * nCols] for x in range(0, len(docs), nRows * nCols)]\" t-as=\"page_docs\">\n                <div class=\"o_label_sheet\" style=\"padding: 10mm 3mm;\">\n                    <table class=\"my-0 table table-sm table-borderless\">\n                        <t t-foreach=\"range(nRows)\" t-as=\"row\">\n                            <tr>\n                                <t t-foreach=\"range(nCols)\" t-as=\"col\">\n                                    <t t-set=\"barcode_index\" t-value=\"(row * nCols + col)\"/>\n                                    <t t-if=\"barcode_index &lt; len(page_docs)\">\n                                        <t t-set=\"o\" t-value=\"page_docs[barcode_index]\"/>\n                                        <td>\n                                            <div class=\"o_label_full\" style=\"width:47mm;height:37.1mm;border: 1px solid black;\">\n                                                <div class=\"o_label_name text-center\">\n                                                    <strong><span t-field=\"o.name\">WH/Stock</span></strong>\n                                                </div>\n                                                <div class=\"text-center mt-3\">\n                                                    <span t-if=\"o.barcode\" t-field=\"o.barcode\" style=\"padding:0\" t-options=\"{''widget'': ''barcode'', ''humanreadable'': 1, ''symbology'': ''auto'', ''img_style'': ''width:47mm;height:11mm''}\">1234567890</span>\n                                                </div>\n                                            </div>\n                                        </td>\n                                    </t>\n                                </t>\n                            </tr>\n                        </t>\n                    </table>\n                </div>\n            </t>\n        </t>\n        <div class=\"oe_structure\"/>\n    </t>\n</t>"}', '<?xml version="1.0"?>
<t t-name="stock.report_generic_barcode">
    <t t-call="web.basic_layout">
        <t t-call="web.html_container">
            <div class="oe_structure"/>
            <t t-set="nRows" t-value="7"/>
            <t t-set="nCols" t-value="4"/>
            <t t-foreach="[docs[x:x + nRows * nCols] for x in range(0, len(docs), nRows * nCols)]" t-as="page_docs">
                <div class="o_label_sheet" style="padding: 10mm 3mm;">
                    <table class="my-0 table table-sm table-borderless">
                        <t t-foreach="range(nRows)" t-as="row">
                            <tr>
                                <t t-foreach="range(nCols)" t-as="col">
                                    <t t-set="barcode_index" t-value="(row * nCols + col)"/>
                                    <t t-if="barcode_index &lt; len(page_docs)">
                                        <t t-set="o" t-value="page_docs[barcode_index]"/>
                                        <td>
                                            <div class="o_label_full" style="width:47mm;height:37.1mm;border: 1px solid black;">
                                                <div class="o_label_name text-center">
                                                    <strong><span t-field="o.name">WH/Stock</span></strong>
                                                </div>
                                                <div class="text-center mt-3">
                                                    <span t-if="o.barcode" t-field="o.barcode" style="padding:0" t-options="{''widget'': ''barcode'', ''humanreadable'': 1, ''symbology'': ''auto'', ''img_style'': ''width:47mm;height:11mm''}">1234567890</span>
                                                </div>
                                            </div>
                                        </td>
                                    </t>
                                </t>
                            </tr>
                        </t>
                    </table>
                </div>
            </t>
        </t>
        <div class="oe_structure"/>
    </t>
</t>

', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (959, 16, NULL, 1, 1, 'report_location_barcode', NULL, 'stock.report_location_barcode', 'qweb', 'stock/report/report_location_barcode.xml', 'primary', '{"en_US": "<t t-name=\"stock.report_location_barcode\">\n    <t t-set=\"title\">Locations</t>\n    <t t-call=\"stock.report_generic_barcode\"/>\n</t>"}', '<?xml version="1.0"?>
<t t-name="stock.report_location_barcode">
    <t t-set="title">Locations</t>
    <t t-call="stock.report_generic_barcode"/>
</t>
', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (960, 16, NULL, 1, 1, 'report_picking', NULL, 'stock.report_picking', 'qweb', 'stock/report/report_stockpicking_operations.xml', 'primary', '{"en_US": "<t t-name=\"stock.report_picking\">\n            <t t-call=\"web.html_container\">\n                <t t-foreach=\"docs\" t-as=\"o\">\n                    <t t-call=\"web.external_layout\">\n                        <t t-set=\"address\" t-value=\"None\"/>\n                        <div class=\"page\">\n                            <div class=\"row justify-content-end mb16\">\n                                <div class=\"col-4\" name=\"right_box\">\n                                    <div t-field=\"o.name\" t-options=\"{''widget'': ''barcode'', ''width'': 600, ''height'': 100, ''img_style'': ''width:300px;height:50px;''}\">\n                                        <div class=\"bg-light border-1 rounded d-flex flex-column align-items-center justify-content-center p-3 opacity-75 text-muted text-center\">\n                                            (document barcode)\n                                        </div>\n                                    </div>\n                                </div>\n                            </div>\n                            <div class=\"row\">\n                                <div class=\"col-6\" name=\"div_outgoing_address\">\n                                    <div t-if=\"o.should_print_delivery_address()\">\n                                        <span><strong>Delivery Address:</strong></span>\n                                        <div t-out=\"o.move_ids[0].partner_id or o.partner_id\" t-options=\"{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;, &quot;phone&quot;], &quot;no_marker&quot;: True, &quot;phone_icons&quot;: True}\">\n                                                <div class=\"bg-light border-1 rounded h-100 d-flex flex-column align-items-center justify-content-center p-4 opacity-75 text-muted text-center\">\n                                                    <strong>Delivery address</strong>\n                                                    <div>Presence depends on the type of operation.</div>\n                                                </div>\n                                        </div>\n                                    </div>\n                                    <div t-elif=\"o.picking_type_id.code != ''internal'' and o.picking_type_id.warehouse_id.partner_id\">\n                                        <span><strong>Warehouse Address:</strong></span>\n                                        <div t-field=\"o.picking_type_id.warehouse_id.partner_id\" t-options=\"{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;, &quot;phone&quot;], &quot;no_marker&quot;: True, &quot;phone_icons&quot;: True}\">\n                                                <div class=\"bg-light border-1 rounded h-100 d-flex flex-column align-items-center justify-content-center p-4 opacity-75 text-muted text-center\">\n                                                    <strong>Warehouse address</strong>\n                                                    <div>Presence depends on the type of operation.</div>\n                                                </div>\n                                        </div>\n                                    </div>\n                                </div>\n                                <div class=\"col-5 offset-1\" name=\"div_incoming_address\">\n                                    <t t-set=\"show_partner\" t-value=\"False\"/>\n                                    <div t-if=\"o.picking_type_id.code==''incoming'' and o.partner_id\">\n                                        <span><strong>Vendor Address:</strong></span>\n                                        <t t-set=\"show_partner\" t-value=\"True\"/>\n                                    </div>\n                                    <div t-elif=\"o.picking_type_id.code==''internal'' and o.partner_id\">\n                                        <span><strong>Warehouse Address:</strong></span>\n                                        <t t-set=\"show_partner\" t-value=\"True\"/>\n                                    </div>\n                                    <div t-elif=\"o.picking_type_id.code==''outgoing'' and o.partner_id and o.partner_id != o.partner_id.commercial_partner_id\">\n                                        <span><strong>Customer Address:</strong></span>\n                                        <t t-set=\"show_partner\" t-value=\"True\"/>\n                                    </div>\n                                    <div t-if=\"show_partner\" name=\"partner_header\">\n                                        <div t-field=\"o.partner_id.commercial_partner_id\" t-options=\"{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;, &quot;phone&quot;, &quot;vat&quot;], &quot;no_marker&quot;: True, &quot;phone_icons&quot;: True}\">\n                                             <div class=\"bg-light border-1 rounded h-100 d-flex flex-column align-items-center justify-content-center p-4 opacity-75 text-muted text-center\">\n                                                <strong>Recipient address</strong>\n                                                <div>Presence depends on the type of operation.</div>\n                                            </div>\n                                        </div>\n                                    </div>\n                                </div>\n                                <!-- This node is incompatible (in wkhtmltopdf) with its siblings which together take all space. We can''t remove it in stable for stability reasons -->\n                                <div class=\"oe_structure\" style=\"display: none;\"/>\n                            </div>\n                            <div class=\"oe_structure\"/>\n                            <h1 t-field=\"o.name\" class=\"mt0\">WH/OUT/00001</h1>\n                            <div class=\"oe_structure\"/>\n                            <div class=\"row mt32 mb32\">\n                                <div t-if=\"o.origin\" class=\"col-auto\" name=\"div_origin\">\n                                    <strong>Order:</strong>\n                                    <p t-field=\"o.origin\">S0001</p>\n                                </div>\n                                <div class=\"col-auto\" name=\"div_state\">\n                                    <strong>Status:</strong>\n                                    <p t-field=\"o.state\">Draft</p>\n                                </div>\n                                <div t-if=\"o.scheduled_date\" class=\"col-auto\" name=\"div_sched_date\">\n                                    <strong>Scheduled Date:</strong>\n                                    <p t-field=\"o.scheduled_date\">2023-09-24</p>\n                                </div>\n                            </div>\n                            <table class=\"table table-sm\" t-if=\"o.move_line_ids and o.move_ids_without_package\">\n                                <t t-set=\"has_barcode\" t-value=\"any(move_line.product_id and move_line.product_id.sudo().barcode or move_line.package_id for move_line in o.move_line_ids)\"/>\n                                <t t-set=\"has_serial_number\" t-value=\"any(move_line.lot_id or move_line.lot_name for move_line in o.move_line_ids)\" groups=\"stock.group_production_lot\"/>\n                                <thead>\n                                    <tr>\n                                        <th name=\"th_product\">\n                                            <strong>Product</strong>\n                                        </th>\n                                        <th>\n                                            <strong>Quantity</strong>\n                                        </th>\n                                        <th name=\"th_from\" t-if=\"o.picking_type_id.code != ''incoming''\" align=\"left\" groups=\"stock.group_stock_multi_locations\">\n                                            <strong>From</strong>\n                                        </th>\n                                        <th name=\"th_to\" t-if=\"o.picking_type_id.code != ''outgoing''\" groups=\"stock.group_stock_multi_locations\">\n                                            <strong>To</strong>\n                                        </th>\n                                        <th name=\"th_serial_number\" class=\"text-center\" t-if=\"has_serial_number\">\n                                           <strong>Lot/Serial Number</strong>\n                                        </th>\n                                        <th name=\"th_barcode\" class=\"text-center\" t-if=\"has_barcode\">\n                                            <strong>Product Barcode</strong>\n                                        </th>\n                                    </tr>\n                                </thead>\n                                <tbody>\n                                    <!-- In case you come across duplicated lines, ask NIM or LAP -->\n                                    <tr t-foreach=\"o.move_line_ids_without_package.sorted(lambda ml: (ml.location_id.complete_name, ml.location_dest_id.complete_name))\" t-as=\"ml\">\n                                        <td>\n                                            <span t-field=\"ml.product_id.display_name\">Customizable Desk</span><br/>\n                                            <span t-if=\"ml.product_id.description_picking\" t-field=\"ml.product_id.description_picking\">Description on transfer</span>\n                                        </td>\n                                        <td>\n                                            <span t-field=\"ml.quantity\">3.00</span>\n                                            <span t-field=\"ml.product_uom_id\" groups=\"uom.group_uom\">units</span>\n                                            <span t-if=\"ml.move_id.product_packaging_id\">\n                                                <span t-if=\"o.state != ''done''\">\n                                                    (<span t-field=\"ml.product_packaging_qty\" t-options=\"{&quot;widget&quot;: &quot;integer&quot;}\"/> <span t-field=\"ml.move_id.product_packaging_id.name\"/>)\n                                                </span>\n                                                <span t-if=\"o.state == ''done''\">\n                                                    (<span t-field=\"ml.product_packaging_qty\" t-options=\"{&quot;widget&quot;: &quot;integer&quot;}\"/> <span t-field=\"ml.move_id.product_packaging_id.name\"/>)\n                                                </span>\n                                            </span>\n                                        </td>\n                                        <td t-if=\"o.picking_type_id.code != ''incoming''\" groups=\"stock.group_stock_multi_locations\">\n                                            <span t-esc=\"ml.location_id.display_name\">WH/Stock</span>\n                                                <t t-if=\"ml.package_id\">\n                                                    <span t-field=\"ml.package_id\">Package A</span>\n                                                </t>\n                                        </td>\n                                        <td t-if=\"o.picking_type_id.code != ''outgoing''\" groups=\"stock.group_stock_multi_locations\">\n                                            <div>\n                                                <span t-field=\"ml.location_dest_id\">WH/Outgoing</span>\n                                                <t t-if=\"ml.result_package_id\">\n                                                    <span t-field=\"ml.result_package_id\">Package B</span>\n                                                </t>\n                                            </div>\n                                        </td>\n                                        <td class=\" text-center h6\" t-if=\"has_serial_number\">\n                                            <span t-if=\"has_serial_number and (ml.lot_id or ml.lot_name)\" t-esc=\"ml.lot_id.name or ml.lot_name\" t-options=\"{''widget'': ''barcode'', ''humanreadable'': 1, ''width'': 400, ''height'': 100, ''img_style'': ''width:100%;height:35px;''}\">\n                                                <div class=\"bg-light border-1 rounded d-flex flex-column align-items-center justify-content-center px-1 py-2 opacity-75 text-muted text-center\">\n                                                    (serial barcode)\n                                                </div>\n                                            </span>\n                                        </td>\n                                        <td class=\"text-center\" t-if=\"has_barcode\">\n                                            <t t-if=\"product_barcode != ml.product_id.barcode\">\n                                                <span t-if=\"ml.product_id and ml.product_id.barcode\">\n                                                    <div t-field=\"ml.product_id.barcode\" t-options=\"{''widget'': ''barcode'', ''symbology'': ''auto'', ''width'': 400, ''height'': 100, ''quiet'': 0, ''img_style'': ''height:35px;''}\">\n                                                        <div class=\"bg-light border-1 rounded d-flex flex-column align-items-center justify-content-center px-1 py-2 opacity-75 text-muted text-center\">\n                                                            (product barcode)\n                                                        </div>\n                                                    </div>\n                                                </span>\n                                                <t t-set=\"product_barcode\" t-value=\"ml.product_id.barcode\"/>\n                                            </t>\n                                        </td>\n                                    </tr>\n                                  </tbody>\n                            </table>\n                            <div t-if=\"not (o.package_level_ids and o.picking_type_entire_packs and o.state in [''assigned'', ''done''])\" class=\"oe_structure\"/>\n                            <table t-else=\"\" class=\"table table-sm\">\n                                <thead>\n                                    <tr>\n                                        <th name=\"th_package\">Package</th>\n                                        <th name=\"th_pko_from\" t-if=\"o.picking_type_id.code != ''incoming''\" groups=\"stock.group_stock_multi_locations\">From</th>\n                                        <th name=\"th_pki_from\" t-if=\"o.picking_type_id.code != ''outgoing''\" groups=\"stock.group_stock_multi_locations\">To</th>\n                                    </tr>\n                                </thead>\n                                <tbody>\n                                    <tr t-foreach=\"o.package_level_ids.sorted(key=lambda p: p.package_id.name)\" t-as=\"package\">\n                                        <td name=\"td_pk_barcode\">\n                                            <t t-set=\"package\" t-value=\"package.with_context(picking_id=o.id)\"/>\n                                            <div t-field=\"package.package_id.name\" t-options=\"{''widget'': ''barcode'', ''humanreadable'': 1, ''width'': 600, ''height'': 100, ''img_style'': ''width:300px;height:50px;margin-left: -50px;''}\">\n                                                <div class=\"bg-light border-1 rounded d-flex flex-column align-items-center justify-content-center px-1 py-2  opacity-75 text-muted text-center\">\n                                                    (package barcode)\n                                                </div>\n                                            </div>\n                                                <br/>\n                                        </td>\n                                        <td t-if=\"o.picking_type_id.code != ''incoming''\" groups=\"stock.group_stock_multi_locations\">\n                                            <span t-field=\"package.location_id\"/>\n                                        </td>\n                                        <td t-if=\"o.picking_type_id.code != ''outgoing''\" groups=\"stock.group_stock_multi_locations\">\n                                            <span t-field=\"package.location_dest_id\"/>\n                                        </td>\n                                    </tr>\n                                </tbody>\n                            </table>\n\n                            <t t-set=\"no_reserved_product\" t-value=\"o.move_ids.filtered(lambda x: x.product_uom_qty != x.quantity and x.move_line_ids and x.state!=''done'')\"/>\n                            <p t-if=\"o.state in [''draft'', ''waiting'', ''confirmed''] or no_reserved_product\"><i class=\"fa fa-exclamation-triangle\"/>\n                                All products could not be reserved. Click on the \"Check Availability\" button to try to reserve products.\n                            </p>\n                            <p t-else=\"\"/>\n                            <div class=\"oe_structure\"/>\n                            <p t-field=\"o.note\"/>\n                            <div class=\"oe_structure\"/>\n                        </div>\n                    </t>\n                </t>\n            </t>\n        </t>"}', '<?xml version="1.0"?>
<t t-name="stock.report_picking">
            <t t-call="web.html_container">
                <t t-foreach="docs" t-as="o">
                    <t t-call="web.external_layout">
                        <t t-set="address" t-value="None"/>
                        <div class="page">
                            <div class="row justify-content-end mb16">
                                <div class="col-4" name="right_box">
                                    <div t-field="o.name" t-options="{''widget'': ''barcode'', ''width'': 600, ''height'': 100, ''img_style'': ''width:300px;height:50px;''}">
                                        <div class="bg-light border-1 rounded d-flex flex-column align-items-center justify-content-center p-3 opacity-75 text-muted text-center">
                                            (document barcode)
                                        </div>
                                    </div>
                                </div>
                            </div>
                            <div class="row">
                                <div class="col-6" name="div_outgoing_address">
                                    <div t-if="o.should_print_delivery_address()">
                                        <span><strong>Delivery Address:</strong></span>
                                        <div t-out="o.move_ids[0].partner_id or o.partner_id" t-options="{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;, &quot;phone&quot;], &quot;no_marker&quot;: True, &quot;phone_icons&quot;: True}">
                                                <div class="bg-light border-1 rounded h-100 d-flex flex-column align-items-center justify-content-center p-4 opacity-75 text-muted text-center">
                                                    <strong>Delivery address</strong>
                                                    <div>Presence depends on the type of operation.</div>
                                                </div>
                                        </div>
                                    </div>
                                    <div t-elif="o.picking_type_id.code != ''internal'' and o.picking_type_id.warehouse_id.partner_id">
                                        <span><strong>Warehouse Address:</strong></span>
                                        <div t-field="o.picking_type_id.warehouse_id.partner_id" t-options="{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;, &quot;phone&quot;], &quot;no_marker&quot;: True, &quot;phone_icons&quot;: True}">
                                                <div class="bg-light border-1 rounded h-100 d-flex flex-column align-items-center justify-content-center p-4 opacity-75 text-muted text-center">
                                                    <strong>Warehouse address</strong>
                                                    <div>Presence depends on the type of operation.</div>
                                                </div>
                                        </div>
                                    </div>
                                </div>
                                <div class="col-5 offset-1" name="div_incoming_address">
                                    <t t-set="show_partner" t-value="False"/>
                                    <div t-if="o.picking_type_id.code==''incoming'' and o.partner_id">
                                        <span><strong>Vendor Address:</strong></span>
                                        <t t-set="show_partner" t-value="True"/>
                                    </div>
                                    <div t-elif="o.picking_type_id.code==''internal'' and o.partner_id">
                                        <span><strong>Warehouse Address:</strong></span>
                                        <t t-set="show_partner" t-value="True"/>
                                    </div>
                                    <div t-elif="o.picking_type_id.code==''outgoing'' and o.partner_id and o.partner_id != o.partner_id.commercial_partner_id">
                                        <span><strong>Customer Address:</strong></span>
                                        <t t-set="show_partner" t-value="True"/>
                                    </div>
                                    <div t-if="show_partner" name="partner_header">
                                        <div t-field="o.partner_id.commercial_partner_id" t-options="{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;, &quot;phone&quot;, &quot;vat&quot;], &quot;no_marker&quot;: True, &quot;phone_icons&quot;: True}">
                                             <div class="bg-light border-1 rounded h-100 d-flex flex-column align-items-center justify-content-center p-4 opacity-75 text-muted text-center">
                                                <strong>Recipient address</strong>
                                                <div>Presence depends on the type of operation.</div>
                                            </div>
                                        </div>
                                    </div>
                                </div>
                                <!-- This node is incompatible (in wkhtmltopdf) with its siblings which together take all space. We can''t remove it in stable for stability reasons -->
                                <div class="oe_structure" style="display: none;"/>
                            </div>
                            <div class="oe_structure"/>
                            <h1 t-field="o.name" class="mt0">WH/OUT/00001</h1>
                            <div class="oe_structure"/>
                            <div class="row mt32 mb32">
                                <div t-if="o.origin" class="col-auto" name="div_origin">
                                    <strong>Order:</strong>
                                    <p t-field="o.origin">S0001</p>
                                </div>
                                <div class="col-auto" name="div_state">
                                    <strong>Status:</strong>
                                    <p t-field="o.state">Draft</p>
                                </div>
                                <div t-if="o.scheduled_date" class="col-auto" name="div_sched_date">
                                    <strong>Scheduled Date:</strong>
                                    <p t-field="o.scheduled_date">2023-09-24</p>
                                </div>
                            </div>
                            <table class="table table-sm" t-if="o.move_line_ids and o.move_ids_without_package">
                                <t t-set="has_barcode" t-value="any(move_line.product_id and move_line.product_id.sudo().barcode or move_line.package_id for move_line in o.move_line_ids)"/>
                                <t t-set="has_serial_number" t-value="any(move_line.lot_id or move_line.lot_name for move_line in o.move_line_ids)" groups="stock.group_production_lot"/>
                                <thead>
                                    <tr>
                                        <th name="th_product">
                                            <strong>Product</strong>
                                        </th>
                                        <th>
                                            <strong>Quantity</strong>
                                        </th>
                                        <th name="th_from" t-if="o.picking_type_id.code != ''incoming''" align="left" groups="stock.group_stock_multi_locations">
                                            <strong>From</strong>
                                        </th>
                                        <th name="th_to" t-if="o.picking_type_id.code != ''outgoing''" groups="stock.group_stock_multi_locations">
                                            <strong>To</strong>
                                        </th>
                                        <th name="th_serial_number" class="text-center" t-if="has_serial_number">
                                           <strong>Lot/Serial Number</strong>
                                        </th>
                                        <th name="th_barcode" class="text-center" t-if="has_barcode">
                                            <strong>Product Barcode</strong>
                                        </th>
                                    </tr>
                                </thead>
                                <tbody>
                                    <!-- In case you come across duplicated lines, ask NIM or LAP -->
                                    <tr t-foreach="o.move_line_ids_without_package.sorted(lambda ml: (ml.location_id.complete_name, ml.location_dest_id.complete_name))" t-as="ml">
                                        <td>
                                            <span t-field="ml.product_id.display_name">Customizable Desk</span><br/>
                                            <span t-if="ml.product_id.description_picking" t-field="ml.product_id.description_picking">Description on transfer</span>
                                        </td>
                                        <td>
                                            <span t-field="ml.quantity">3.00</span>
                                            <span t-field="ml.product_uom_id" groups="uom.group_uom">units</span>
                                            <span t-if="ml.move_id.product_packaging_id">
                                                <span t-if="o.state != ''done''">
                                                    (<span t-field="ml.product_packaging_qty" t-options="{&quot;widget&quot;: &quot;integer&quot;}"/> <span t-field="ml.move_id.product_packaging_id.name"/>)
                                                </span>
                                                <span t-if="o.state == ''done''">
                                                    (<span t-field="ml.product_packaging_qty" t-options="{&quot;widget&quot;: &quot;integer&quot;}"/> <span t-field="ml.move_id.product_packaging_id.name"/>)
                                                </span>
                                            </span>
                                        </td>
                                        <td t-if="o.picking_type_id.code != ''incoming''" groups="stock.group_stock_multi_locations">
                                            <span t-esc="ml.location_id.display_name">WH/Stock</span>
                                                <t t-if="ml.package_id">
                                                    <span t-field="ml.package_id">Package A</span>
                                                </t>
                                        </td>
                                        <td t-if="o.picking_type_id.code != ''outgoing''" groups="stock.group_stock_multi_locations">
                                            <div>
                                                <span t-field="ml.location_dest_id">WH/Outgoing</span>
                                                <t t-if="ml.result_package_id">
                                                    <span t-field="ml.result_package_id">Package B</span>
                                                </t>
                                            </div>
                                        </td>
                                        <td class=" text-center h6" t-if="has_serial_number">
                                            <span t-if="has_serial_number and (ml.lot_id or ml.lot_name)" t-esc="ml.lot_id.name or ml.lot_name" t-options="{''widget'': ''barcode'', ''humanreadable'': 1, ''width'': 400, ''height'': 100, ''img_style'': ''width:100%;height:35px;''}">
                                                <div class="bg-light border-1 rounded d-flex flex-column align-items-center justify-content-center px-1 py-2 opacity-75 text-muted text-center">
                                                    (serial barcode)
                                                </div>
                                            </span>
                                        </td>
                                        <td class="text-center" t-if="has_barcode">
                                            <t t-if="product_barcode != ml.product_id.barcode">
                                                <span t-if="ml.product_id and ml.product_id.barcode">
                                                    <div t-field="ml.product_id.barcode" t-options="{''widget'': ''barcode'', ''symbology'': ''auto'', ''width'': 400, ''height'': 100, ''quiet'': 0, ''img_style'': ''height:35px;''}">
                                                        <div class="bg-light border-1 rounded d-flex flex-column align-items-center justify-content-center px-1 py-2 opacity-75 text-muted text-center">
                                                            (product barcode)
                                                        </div>
                                                    </div>
                                                </span>
                                                <t t-set="product_barcode" t-value="ml.product_id.barcode"/>
                                            </t>
                                        </td>
                                    </tr>
                                  </tbody>
                            </table>
                            <div t-if="not (o.package_level_ids and o.picking_type_entire_packs and o.state in [''assigned'', ''done''])" class="oe_structure"/>
                            <table t-else="" class="table table-sm">
                                <thead>
                                    <tr>
                                        <th name="th_package">Package</th>
                                        <th name="th_pko_from" t-if="o.picking_type_id.code != ''incoming''" groups="stock.group_stock_multi_locations">From</th>
                                        <th name="th_pki_from" t-if="o.picking_type_id.code != ''outgoing''" groups="stock.group_stock_multi_locations">To</th>
                                    </tr>
                                </thead>
                                <tbody>
                                    <tr t-foreach="o.package_level_ids.sorted(key=lambda p: p.package_id.name)" t-as="package">
                                        <td name="td_pk_barcode">
                                            <t t-set="package" t-value="package.with_context(picking_id=o.id)"/>
                                            <div t-field="package.package_id.name" t-options="{''widget'': ''barcode'', ''humanreadable'': 1, ''width'': 600, ''height'': 100, ''img_style'': ''width:300px;height:50px;margin-left: -50px;''}">
                                                <div class="bg-light border-1 rounded d-flex flex-column align-items-center justify-content-center px-1 py-2  opacity-75 text-muted text-center">
                                                    (package barcode)
                                                </div>
                                            </div>
                                                <br/>
                                        </td>
                                        <td t-if="o.picking_type_id.code != ''incoming''" groups="stock.group_stock_multi_locations">
                                            <span t-field="package.location_id"/>
                                        </td>
                                        <td t-if="o.picking_type_id.code != ''outgoing''" groups="stock.group_stock_multi_locations">
                                            <span t-field="package.location_dest_id"/>
                                        </td>
                                    </tr>
                                </tbody>
                            </table>

                            <t t-set="no_reserved_product" t-value="o.move_ids.filtered(lambda x: x.product_uom_qty != x.quantity and x.move_line_ids and x.state!=''done'')"/>
                            <p t-if="o.state in [''draft'', ''waiting'', ''confirmed''] or no_reserved_product"><i class="fa fa-exclamation-triangle"/>
                                All products could not be reserved. Click on the "Check Availability" button to try to reserve products.
                            </p>
                            <p t-else=""/>
                            <div class="oe_structure"/>
                            <p t-field="o.note"/>
                            <div class="oe_structure"/>
                        </div>
                    </t>
                </t>
            </t>
        </t>
        ', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (961, 16, NULL, 1, 1, 'report_picking_type_label', NULL, 'stock.report_picking_type_label', 'qweb', 'stock/report/report_stockpicking_operations.xml', 'primary', '{"en_US": "<t t-name=\"stock.report_picking_type_label\">\n            <t t-set=\"title\">Operation Types</t>\n            <t t-call=\"stock.report_generic_barcode\"/>\n        </t>"}', '<?xml version="1.0"?>
<t t-name="stock.report_picking_type_label">
            <t t-set="title">Operation Types</t>
            <t t-call="stock.report_generic_barcode"/>
        </t>
    ', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (962, 16, NULL, 1, 1, 'report_delivery_document', NULL, 'stock.report_delivery_document', 'qweb', 'stock/report/report_deliveryslip.xml', 'primary', '{"en_US": "<t t-name=\"stock.report_delivery_document\">\n        <t t-call=\"web.html_container\">\n            <t t-call=\"web.external_layout\">\n                <t t-set=\"o\" t-value=\"o.with_context(lang=o._get_report_lang())\"/>\n                <t t-set=\"partner\" t-value=\"o.partner_id or (o.move_ids and o.move_ids[0].partner_id) or False\"/>\n\n                <t t-set=\"address\">\n                    <div name=\"div_outgoing_address\">\n                        <div name=\"outgoing_delivery_address\" t-if=\"o.should_print_delivery_address()\">\n                            <span><strong>Delivery Address:</strong></span>\n                            <div t-out=\"o.move_ids[0].partner_id or o.partner_id\" t-options=\"{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;, &quot;phone&quot;], &quot;no_marker&quot;: True, &quot;phone_icons&quot;: True}\"/>\n                        </div>\n                        <div name=\"outgoing_warehouse_address\" t-elif=\"o.picking_type_id.code != ''internal'' and o.picking_type_id.warehouse_id.partner_id\">\n                            <span><strong>Warehouse Address:</strong></span>\n                            <div t-field=\"o.picking_type_id.warehouse_id.partner_id\" t-options=\"{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;, &quot;phone&quot;], &quot;no_marker&quot;: True, &quot;phone_icons&quot;: True}\"/>\n                        </div>\n                    </div>\n                </t>\n                <t t-set=\"information_block\">\n                    <div class=\"row\">\n                        <div class=\"col-7\" name=\"div_incoming_address\">\n                            <t t-set=\"show_partner\" t-value=\"False\"/>\n                            <div name=\"vendor_address\" t-if=\"o.picking_type_id.code==''incoming'' and partner\">\n                                <span><strong>Vendor Address:</strong></span>\n                                <t t-set=\"show_partner\" t-value=\"True\"/>\n                            </div>\n                            <div name=\"customer_address\" t-if=\"o.picking_type_id.code==''outgoing'' and partner and partner != partner.commercial_partner_id\">\n                                <span><strong>Customer Address:</strong></span>\n                                <t t-set=\"show_partner\" t-value=\"True\"/>\n                            </div>\n                            <div t-if=\"show_partner\" name=\"partner_header\">\n                                <div t-field=\"partner.commercial_partner_id\" t-options=\"{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;, &quot;phone&quot;, &quot;vat&quot;], &quot;no_marker&quot;: True, &quot;phone_icons&quot;: True}\"/>\n                            </div>\n                        </div>\n                    </div>\n                </t>\n                <div class=\"page\">\n                    <h2>\n                        <span t-field=\"o.name\">WH/OUT/0001</span>\n                    </h2>\n                    <div class=\"oe_structure\"/>\n                    <div class=\"report-wrapping-flexbox clearfix row mt32 mb32\">\n                        <div t-if=\"o.origin\" class=\"col-auto col-3 mw-100 mb-2\" name=\"div_origin\">\n                            <strong>Order:</strong>\n                            <p t-field=\"o.origin\" class=\"m-0\">S0001</p>\n                        </div>\n                        <div t-if=\"o.state\" class=\"col-auto col-3 mw-100 mb-2\" name=\"div_sched_date\">\n                            <strong>Shipping Date:</strong>\n                                <p t-if=\"o.state == ''done''\" t-field=\"o.date_done\" class=\"m-0\"/>\n                                <p t-else=\"\" t-field=\"o.scheduled_date\" class=\"m-0\"/>\n                        </div>\n                    </div>\n                    <div class=\"oe_structure\"/>\n                    <table class=\"table table-sm\" t-if=\"o.state!=''done''\" name=\"stock_move_table\">\n                        <thead>\n                            <tr>\n                                <th name=\"th_sm_product\"><strong>Product</strong></th>\n                                <th name=\"th_sm_ordered\"><strong>Ordered</strong></th>\n                                <th name=\"th_sm_quantity\"><strong>Delivered</strong></th>\n                            </tr>\n                        </thead>\n                        <tbody>\n                            <t t-set=\"lines\" t-value=\"o.move_ids.filtered(lambda x: x.product_uom_qty)\"/>\n                            <tr t-foreach=\"lines\" t-as=\"move\">\n                                <td>\n                                    <span t-field=\"move.product_id\">Customizable Desk</span>\n                                    <p t-if=\"move.description_picking and move.description_picking != move.product_id.name and move.description_picking != move.product_id.display_name\">\n                                        <span t-field=\"move.description_picking\">Description on transfer</span>\n                                    </p>\n                                </td>\n                                <td>\n                                    <span t-field=\"move.product_uom_qty\">3.00</span>\n                                    <span t-field=\"move.product_uom\" groups=\"uom.group_uom\">units</span>\n                                    <span t-if=\"move.product_packaging_id\">\n                                        (<span t-field=\"move.product_packaging_qty\" t-options=\"{&quot;widget&quot;: &quot;integer&quot;}\"/> <span t-field=\"move.product_packaging_id\"/>)\n                                    </span>\n                                </td>\n                                <td>\n                                    <span t-field=\"move.quantity\">3.00</span>\n                                    <span t-field=\"move.product_uom\" groups=\"uom.group_uom\">units</span>\n                                    <span t-if=\"move.product_packaging_id\">\n                                        (<span t-field=\"move.product_packaging_quantity\" t-options=\"{&quot;widget&quot;: &quot;integer&quot;}\"/> <span t-field=\"move.product_packaging_id\"/>)\n                                    </span>\n                                </td>\n                            </tr>\n                        </tbody>\n                    </table>\n                    <table class=\"table table-sm mt48\" t-elif=\"o.move_line_ids and o.state==''done''\" name=\"stock_move_line_table\">\n                        <t t-set=\"has_serial_number\" t-value=\"False\"/>\n                        <t t-set=\"has_serial_number\" t-value=\"o.move_line_ids.mapped(''lot_id'')\" groups=\"stock.group_lot_on_delivery_slip\"/>\n                        <thead>\n                            <tr>\n                                <th name=\"th_sml_product\"><strong>Product</strong></th>\n                                <th name=\"th_sml_qty_ordered\" class=\"text-center\" t-if=\"not has_serial_number\">\n                                    <strong>Ordered</strong>\n                                </th>\n                                <th name=\"lot_serial\" t-else=\"\">\n                                    Lot/Serial Number\n                                </th>\n                                <th name=\"th_sml_quantity\" class=\"text-center\"><strong>Delivered</strong></th>\n                            </tr>\n                        </thead>\n                        <tbody>\n                        <!-- This part gets complicated with different use cases (additional use cases in extensions of this report):\n                                1. If serial numbers are used and set to print on delivery slip => print lines as is, otherwise group them by overlapping\n                                    product + description + uom combinations\n                                2. If any packages are assigned => split products up by package (or non-package) and then apply use case 1 -->\n                            <!-- If has destination packages => create sections of corresponding products -->\n                            <t t-if=\"o.has_packages\" name=\"has_packages\">\n                                <t t-set=\"packages\" t-value=\"o.move_line_ids.mapped(''result_package_id'')\"/>\n                                <t t-foreach=\"packages\" t-as=\"package\">\n                                    <t t-call=\"stock.stock_report_delivery_package_section_line\"/>\n                                    <t t-set=\"package_move_lines\" t-value=\"o.move_line_ids.filtered(lambda l: l.result_package_id == package)\"/>\n                                    <!-- If printing lots/serial numbers => keep products in original lines -->\n                                    <t t-if=\"has_serial_number\">\n                                        <tr t-foreach=\"package_move_lines\" t-as=\"move_line\">\n                                            <t t-call=\"stock.stock_report_delivery_has_serial_move_line\"/>\n                                        </tr>\n                                    </t>\n                                    <!-- If not printing lots/serial numbers => merge lines with same product+description+uom -->\n                                    <t t-else=\"\">\n                                        <t t-set=\"aggregated_lines\" t-value=\"package_move_lines._get_aggregated_product_quantities(strict=True)\"/>\n                                        <t t-call=\"stock.stock_report_delivery_aggregated_move_lines\"/>\n                                    </t>\n                                </t>\n                                <!-- Make sure we do another section for package-less products if they exist -->\n                                <t t-set=\"move_lines\" t-value=\"o.move_line_ids.filtered(lambda l: not l.result_package_id)\"/>\n                                <t t-set=\"aggregated_lines\" t-value=\"o.move_line_ids._get_aggregated_product_quantities(except_package=True)\"/>\n                                <t t-if=\"move_lines or aggregated_lines\" name=\"no_package_move_lines\">\n                                    <t t-call=\"stock.stock_report_delivery_no_package_section_line\" name=\"no_package_section\"/>\n                                    <t t-if=\"has_serial_number\">\n                                        <tr t-foreach=\"move_lines\" t-as=\"move_line\">\n                                            <t t-call=\"stock.stock_report_delivery_has_serial_move_line\"/>\n                                        </tr>\n                                    </t>\n                                    <t t-elif=\"aggregated_lines\">\n                                        <t t-call=\"stock.stock_report_delivery_aggregated_move_lines\"/>\n                                    </t>\n                                </t>\n                            </t>\n                            <!-- No destination packages -->\n                            <t t-else=\"\">\n                                <!-- If printing lots/serial numbers => keep products in original lines -->\n                                <t t-if=\"has_serial_number\">\n                                    <tr t-foreach=\"o.move_line_ids\" t-as=\"move_line\">\n                                        <t t-call=\"stock.stock_report_delivery_has_serial_move_line\"/>\n                                    </tr>\n                                </t>\n                                <!-- If not printing lots/serial numbers => merge lines with same product -->\n                                <t t-else=\"\" name=\"aggregated_move_lines\">\n                                    <t t-set=\"aggregated_lines\" t-value=\"o.move_line_ids._get_aggregated_product_quantities()\"/>\n                                    <t t-call=\"stock.stock_report_delivery_aggregated_move_lines\"/>\n                                </t>\n                            </t>\n                        </tbody>\n                    </table>\n                    <div class=\"oe_structure\"/>\n                    <t t-set=\"backorders\" t-value=\"o.backorder_ids.filtered(lambda x: x.state not in (''done'', ''cancel''))\"/>\n                    <div t-if=\"not (o.backorder_ids and backorders)\" class=\"oe_structure\"/>\n                    <div t-else=\"\">\n                        <p class=\"mt-5\">\n                            <span>Remaining quantities not yet delivered:</span>\n                        </p>\n                        <table class=\"table table-sm\" name=\"stock_backorder_table\" style=\"table-layout: fixed;\">\n                            <thead>\n                                <tr>\n                                    <th name=\"th_sb_product\"><strong>Product</strong></th>\n                                    <th/>\n                                    <th name=\"th_sb_quantity\" class=\"text-center\"><strong>Quantity</strong></th>\n                                </tr>\n                            </thead>\n                            <tbody>\n                                <tr t-foreach=\"backorders.mapped(''move_ids'').filtered(lambda x: x.product_uom_qty)\" t-as=\"bo_line\">\n                                    <td class=\"w-auto\">\n                                        <span t-field=\"bo_line.product_id\">Office Chair</span>\n                                        <p t-if=\"bo_line.description_picking and bo_line.description_picking != bo_line.product_id.name and bo_line.description_picking != bo_line.product_id.display_name\">\n                                            <span t-field=\"bo_line.description_picking\">Description on transfer</span>\n                                        </p>\n                                    </td>\n                                    <td/>\n                                    <td class=\"text-center w-auto\">\n                                        <span t-field=\"bo_line.product_uom_qty\">3.00</span>\n                                        <span t-field=\"bo_line.product_uom\" groups=\"uom.group_uom\">units</span>\n                                    </td>\n                                </tr>\n                            </tbody>\n                        </table>\n                    </div>\n\n                    <div t-if=\"not o.signature\" class=\"oe_structure\"/>\n                    <div t-else=\"\" class=\"mt32 ml64 mr4\" name=\"signature\">\n                        <div class=\"offset-8\">\n                            <strong>Signature</strong>\n                        </div>\n                        <div class=\"offset-8\">\n                            <img t-att-src=\"image_data_uri(o.signature)\" style=\"max-height: 4cm; max-width: 8cm;\"/>\n                        </div>\n                        <div t-if=\"o.partner_id.name\" class=\"offset-8 text-center\">\n                            <p t-field=\"o.partner_id.name\">John Doe</p>\n                        </div>\n                    </div>\n                </div>\n            </t>\n         </t>\n    </t>"}', '<?xml version="1.0"?>
<t t-name="stock.report_delivery_document">
        <t t-call="web.html_container">
            <t t-call="web.external_layout">
                <t t-set="o" t-value="o.with_context(lang=o._get_report_lang())"/>
                <t t-set="partner" t-value="o.partner_id or (o.move_ids and o.move_ids[0].partner_id) or False"/>

                <t t-set="address">
                    <div name="div_outgoing_address">
                        <div name="outgoing_delivery_address" t-if="o.should_print_delivery_address()">
                            <span><strong>Delivery Address:</strong></span>
                            <div t-out="o.move_ids[0].partner_id or o.partner_id" t-options="{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;, &quot;phone&quot;], &quot;no_marker&quot;: True, &quot;phone_icons&quot;: True}"/>
                        </div>
                        <div name="outgoing_warehouse_address" t-elif="o.picking_type_id.code != ''internal'' and o.picking_type_id.warehouse_id.partner_id">
                            <span><strong>Warehouse Address:</strong></span>
                            <div t-field="o.picking_type_id.warehouse_id.partner_id" t-options="{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;, &quot;phone&quot;], &quot;no_marker&quot;: True, &quot;phone_icons&quot;: True}"/>
                        </div>
                    </div>
                </t>
                <t t-set="information_block">
                    <div class="row">
                        <div class="col-7" name="div_incoming_address">
                            <t t-set="show_partner" t-value="False"/>
                            <div name="vendor_address" t-if="o.picking_type_id.code==''incoming'' and partner">
                                <span><strong>Vendor Address:</strong></span>
                                <t t-set="show_partner" t-value="True"/>
                            </div>
                            <div name="customer_address" t-if="o.picking_type_id.code==''outgoing'' and partner and partner != partner.commercial_partner_id">
                                <span><strong>Customer Address:</strong></span>
                                <t t-set="show_partner" t-value="True"/>
                            </div>
                            <div t-if="show_partner" name="partner_header">
                                <div t-field="partner.commercial_partner_id" t-options="{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;, &quot;phone&quot;, &quot;vat&quot;], &quot;no_marker&quot;: True, &quot;phone_icons&quot;: True}"/>
                            </div>
                        </div>
                    </div>
                </t>
                <div class="page">
                    <h2>
                        <span t-field="o.name">WH/OUT/0001</span>
                    </h2>
                    <div class="oe_structure"/>
                    <div class="report-wrapping-flexbox clearfix row mt32 mb32">
                        <div t-if="o.origin" class="col-auto col-3 mw-100 mb-2" name="div_origin">
                            <strong>Order:</strong>
                            <p t-field="o.origin" class="m-0">S0001</p>
                        </div>
                        <div t-if="o.state" class="col-auto col-3 mw-100 mb-2" name="div_sched_date">
                            <strong>Shipping Date:</strong>
                                <p t-if="o.state == ''done''" t-field="o.date_done" class="m-0"/>
                                <p t-else="" t-field="o.scheduled_date" class="m-0"/>
                        </div>
                    </div>
                    <div class="oe_structure"/>
                    <table class="table table-sm" t-if="o.state!=''done''" name="stock_move_table">
                        <thead>
                            <tr>
                                <th name="th_sm_product"><strong>Product</strong></th>
                                <th name="th_sm_ordered"><strong>Ordered</strong></th>
                                <th name="th_sm_quantity"><strong>Delivered</strong></th>
                            </tr>
                        </thead>
                        <tbody>
                            <t t-set="lines" t-value="o.move_ids.filtered(lambda x: x.product_uom_qty)"/>
                            <tr t-foreach="lines" t-as="move">
                                <td>
                                    <span t-field="move.product_id">Customizable Desk</span>
                                    <p t-if="move.description_picking and move.description_picking != move.product_id.name and move.description_picking != move.product_id.display_name">
                                        <span t-field="move.description_picking">Description on transfer</span>
                                    </p>
                                </td>
                                <td>
                                    <span t-field="move.product_uom_qty">3.00</span>
                                    <span t-field="move.product_uom" groups="uom.group_uom">units</span>
                                    <span t-if="move.product_packaging_id">
                                        (<span t-field="move.product_packaging_qty" t-options="{&quot;widget&quot;: &quot;integer&quot;}"/> <span t-field="move.product_packaging_id"/>)
                                    </span>
                                </td>
                                <td>
                                    <span t-field="move.quantity">3.00</span>
                                    <span t-field="move.product_uom" groups="uom.group_uom">units</span>
                                    <span t-if="move.product_packaging_id">
                                        (<span t-field="move.product_packaging_quantity" t-options="{&quot;widget&quot;: &quot;integer&quot;}"/> <span t-field="move.product_packaging_id"/>)
                                    </span>
                                </td>
                            </tr>
                        </tbody>
                    </table>
                    <table class="table table-sm mt48" t-elif="o.move_line_ids and o.state==''done''" name="stock_move_line_table">
                        <t t-set="has_serial_number" t-value="False"/>
                        <t t-set="has_serial_number" t-value="o.move_line_ids.mapped(''lot_id'')" groups="stock.group_lot_on_delivery_slip"/>
                        <thead>
                            <tr>
                                <th name="th_sml_product"><strong>Product</strong></th>
                                <th name="th_sml_qty_ordered" class="text-center" t-if="not has_serial_number">
                                    <strong>Ordered</strong>
                                </th>
                                <th name="lot_serial" t-else="">
                                    Lot/Serial Number
                                </th>
                                <th name="th_sml_quantity" class="text-center"><strong>Delivered</strong></th>
                            </tr>
                        </thead>
                        <tbody>
                        <!-- This part gets complicated with different use cases (additional use cases in extensions of this report):
                                1. If serial numbers are used and set to print on delivery slip => print lines as is, otherwise group them by overlapping
                                    product + description + uom combinations
                                2. If any packages are assigned => split products up by package (or non-package) and then apply use case 1 -->
                            <!-- If has destination packages => create sections of corresponding products -->
                            <t t-if="o.has_packages" name="has_packages">
                                <t t-set="packages" t-value="o.move_line_ids.mapped(''result_package_id'')"/>
                                <t t-foreach="packages" t-as="package">
                                    <t t-call="stock.stock_report_delivery_package_section_line"/>
                                    <t t-set="package_move_lines" t-value="o.move_line_ids.filtered(lambda l: l.result_package_id == package)"/>
                                    <!-- If printing lots/serial numbers => keep products in original lines -->
                                    <t t-if="has_serial_number">
                                        <tr t-foreach="package_move_lines" t-as="move_line">
                                            <t t-call="stock.stock_report_delivery_has_serial_move_line"/>
                                        </tr>
                                    </t>
                                    <!-- If not printing lots/serial numbers => merge lines with same product+description+uom -->
                                    <t t-else="">
                                        <t t-set="aggregated_lines" t-value="package_move_lines._get_aggregated_product_quantities(strict=True)"/>
                                        <t t-call="stock.stock_report_delivery_aggregated_move_lines"/>
                                    </t>
                                </t>
                                <!-- Make sure we do another section for package-less products if they exist -->
                                <t t-set="move_lines" t-value="o.move_line_ids.filtered(lambda l: not l.result_package_id)"/>
                                <t t-set="aggregated_lines" t-value="o.move_line_ids._get_aggregated_product_quantities(except_package=True)"/>
                                <t t-if="move_lines or aggregated_lines" name="no_package_move_lines">
                                    <t t-call="stock.stock_report_delivery_no_package_section_line" name="no_package_section"/>
                                    <t t-if="has_serial_number">
                                        <tr t-foreach="move_lines" t-as="move_line">
                                            <t t-call="stock.stock_report_delivery_has_serial_move_line"/>
                                        </tr>
                                    </t>
                                    <t t-elif="aggregated_lines">
                                        <t t-call="stock.stock_report_delivery_aggregated_move_lines"/>
                                    </t>
                                </t>
                            </t>
                            <!-- No destination packages -->
                            <t t-else="">
                                <!-- If printing lots/serial numbers => keep products in original lines -->
                                <t t-if="has_serial_number">
                                    <tr t-foreach="o.move_line_ids" t-as="move_line">
                                        <t t-call="stock.stock_report_delivery_has_serial_move_line"/>
                                    </tr>
                                </t>
                                <!-- If not printing lots/serial numbers => merge lines with same product -->
                                <t t-else="" name="aggregated_move_lines">
                                    <t t-set="aggregated_lines" t-value="o.move_line_ids._get_aggregated_product_quantities()"/>
                                    <t t-call="stock.stock_report_delivery_aggregated_move_lines"/>
                                </t>
                            </t>
                        </tbody>
                    </table>
                    <div class="oe_structure"/>
                    <t t-set="backorders" t-value="o.backorder_ids.filtered(lambda x: x.state not in (''done'', ''cancel''))"/>
                    <div t-if="not (o.backorder_ids and backorders)" class="oe_structure"/>
                    <div t-else="">
                        <p class="mt-5">
                            <span>Remaining quantities not yet delivered:</span>
                        </p>
                        <table class="table table-sm" name="stock_backorder_table" style="table-layout: fixed;">
                            <thead>
                                <tr>
                                    <th name="th_sb_product"><strong>Product</strong></th>
                                    <th/>
                                    <th name="th_sb_quantity" class="text-center"><strong>Quantity</strong></th>
                                </tr>
                            </thead>
                            <tbody>
                                <tr t-foreach="backorders.mapped(''move_ids'').filtered(lambda x: x.product_uom_qty)" t-as="bo_line">
                                    <td class="w-auto">
                                        <span t-field="bo_line.product_id">Office Chair</span>
                                        <p t-if="bo_line.description_picking and bo_line.description_picking != bo_line.product_id.name and bo_line.description_picking != bo_line.product_id.display_name">
                                            <span t-field="bo_line.description_picking">Description on transfer</span>
                                        </p>
                                    </td>
                                    <td/>
                                    <td class="text-center w-auto">
                                        <span t-field="bo_line.product_uom_qty">3.00</span>
                                        <span t-field="bo_line.product_uom" groups="uom.group_uom">units</span>
                                    </td>
                                </tr>
                            </tbody>
                        </table>
                    </div>

                    <div t-if="not o.signature" class="oe_structure"/>
                    <div t-else="" class="mt32 ml64 mr4" name="signature">
                        <div class="offset-8">
                            <strong>Signature</strong>
                        </div>
                        <div class="offset-8">
                            <img t-att-src="image_data_uri(o.signature)" style="max-height: 4cm; max-width: 8cm;"/>
                        </div>
                        <div t-if="o.partner_id.name" class="offset-8 text-center">
                            <p t-field="o.partner_id.name">John Doe</p>
                        </div>
                    </div>
                </div>
            </t>
         </t>
    </t>

    ', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (963, 16, NULL, 1, 1, 'stock_report_delivery_has_serial_move_line', NULL, 'stock.stock_report_delivery_has_serial_move_line', 'qweb', 'stock/report/report_deliveryslip.xml', 'primary', '{"en_US": "<t t-name=\"stock.stock_report_delivery_has_serial_move_line\">\n        <td>\n            <span t-field=\"move_line.product_id\"/>\n            <!-- this is an annoying workaround for the multiple types of descriptions (often auto-filled) that we do not want to print -->\n            <!-- this makes it so we can pre-filter the descriptions in inherited templates since we cannot extend the standard \"if\" condition -->\n            <!-- let''s agree that pre-filtered descriptions will be set to \"\" -->\n            <t t-if=\"not description and description != ''''\">\n                <t t-set=\"description\" t-value=\"move_line.move_id.description_picking\"/>\n            </t>\n            <p t-if=\"description != '''' and                      description != move_line.product_id.display_name and                      description != move_line.product_id.name\">\n                <span t-esc=\"description\"/>\n            </p>\n        </td>\n        <t t-if=\"has_serial_number\" name=\"move_line_lot\">\n            <td><span t-field=\"move_line.lot_id.name\"/></td>\n        </t>\n        <td class=\"text-center\" name=\"move_line_lot_quantity\">\n            <span t-field=\"move_line.quantity\"/>\n            <span t-field=\"move_line.product_uom_id\"/>\n            <span t-if=\"move_line.move_id.product_packaging_id\" groups=\"product.group_stock_packaging\">\n                (<span t-field=\"move_line.product_packaging_qty\" t-options=\"{&quot;widget&quot;: &quot;integer&quot;}\"/> <span t-field=\"move_line.move_id.product_packaging_id.display_name\"/>)\n            </span>\n        </td>\n    </t>"}', '<?xml version="1.0"?>
<t t-name="stock.stock_report_delivery_has_serial_move_line">
        <td>
            <span t-field="move_line.product_id"/>
            <!-- this is an annoying workaround for the multiple types of descriptions (often auto-filled) that we do not want to print -->
            <!-- this makes it so we can pre-filter the descriptions in inherited templates since we cannot extend the standard "if" condition -->
            <!-- let''s agree that pre-filtered descriptions will be set to "" -->
            <t t-if="not description and description != ''''">
                <t t-set="description" t-value="move_line.move_id.description_picking"/>
            </t>
            <p t-if="description != '''' and                      description != move_line.product_id.display_name and                      description != move_line.product_id.name">
                <span t-esc="description"/>
            </p>
        </td>
        <t t-if="has_serial_number" name="move_line_lot">
            <td><span t-field="move_line.lot_id.name"/></td>
        </t>
        <td class="text-center" name="move_line_lot_quantity">
            <span t-field="move_line.quantity"/>
            <span t-field="move_line.product_uom_id"/>
            <span t-if="move_line.move_id.product_packaging_id" groups="product.group_stock_packaging">
                (<span t-field="move_line.product_packaging_qty" t-options="{&quot;widget&quot;: &quot;integer&quot;}"/> <span t-field="move_line.move_id.product_packaging_id.display_name"/>)
            </span>
        </td>
    </t>
    ', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (964, 16, NULL, 1, 1, 'stock_report_delivery_aggregated_move_lines', NULL, 'stock.stock_report_delivery_aggregated_move_lines', 'qweb', 'stock/report/report_deliveryslip.xml', 'primary', '{"en_US": "<t t-name=\"stock.stock_report_delivery_aggregated_move_lines\">\n        <tr t-foreach=\"aggregated_lines\" t-as=\"line\">\n            <td>\n                <span t-esc=\"aggregated_lines[line][''name'']\"/>\n                <p t-if=\"aggregated_lines[line][''description'']\">\n                    <span t-esc=\"aggregated_lines[line][''description'']\" t-options=\"{''widget'': ''text''}\"/>\n                </p>\n            </td>\n            <td class=\"text-center\" name=\"move_line_aggregated_qty_ordered\">\n                <span t-esc=\"aggregated_lines[line][''qty_ordered'']\" t-options=\"{''widget'': ''float'', ''decimal_precision'': ''Product Unit of Measure''}\"/>\n                <span t-esc=\"aggregated_lines[line][''product_uom''].name\"/>\n                <span t-if=\"aggregated_lines[line][''packaging''].name\">\n                    (<span t-out=\"aggregated_lines[line][''packaging_qty'']\" t-options=\"{&quot;widget&quot;: &quot;integer&quot;}\"/> <span t-out=\"aggregated_lines[line][''packaging''].name\"/>)\n                </span>\n            </td>\n            <td class=\"text-center\" name=\"move_line_aggregated_quantity\">\n                <t t-if=\"aggregated_lines[line][''quantity'']\">\n                    <span t-esc=\"aggregated_lines[line][''quantity'']\" t-options=\"{''widget'': ''float'', ''decimal_precision'': ''Product Unit of Measure''}\"/>\n                    <span t-esc=\"aggregated_lines[line][''product_uom''].name\"/>\n                    <span t-if=\"aggregated_lines[line][''packaging''].name\">\n                        (<span t-out=\"aggregated_lines[line][''packaging_quantity'']\" t-options=\"{&quot;widget&quot;: &quot;integer&quot;}\"/> <span t-out=\"aggregated_lines[line][''packaging''].name\"/>)\n                    </span>\n                </t>\n            </td>\n        </tr>\n    </t>"}', '<?xml version="1.0"?>
<t t-name="stock.stock_report_delivery_aggregated_move_lines">
        <tr t-foreach="aggregated_lines" t-as="line">
            <td>
                <span t-esc="aggregated_lines[line][''name'']"/>
                <p t-if="aggregated_lines[line][''description'']">
                    <span t-esc="aggregated_lines[line][''description'']" t-options="{''widget'': ''text''}"/>
                </p>
            </td>
            <td class="text-center" name="move_line_aggregated_qty_ordered">
                <span t-esc="aggregated_lines[line][''qty_ordered'']" t-options="{''widget'': ''float'', ''decimal_precision'': ''Product Unit of Measure''}"/>
                <span t-esc="aggregated_lines[line][''product_uom''].name"/>
                <span t-if="aggregated_lines[line][''packaging''].name">
                    (<span t-out="aggregated_lines[line][''packaging_qty'']" t-options="{&quot;widget&quot;: &quot;integer&quot;}"/> <span t-out="aggregated_lines[line][''packaging''].name"/>)
                </span>
            </td>
            <td class="text-center" name="move_line_aggregated_quantity">
                <t t-if="aggregated_lines[line][''quantity'']">
                    <span t-esc="aggregated_lines[line][''quantity'']" t-options="{''widget'': ''float'', ''decimal_precision'': ''Product Unit of Measure''}"/>
                    <span t-esc="aggregated_lines[line][''product_uom''].name"/>
                    <span t-if="aggregated_lines[line][''packaging''].name">
                        (<span t-out="aggregated_lines[line][''packaging_quantity'']" t-options="{&quot;widget&quot;: &quot;integer&quot;}"/> <span t-out="aggregated_lines[line][''packaging''].name"/>)
                    </span>
                </t>
            </td>
        </tr>
    </t>

    ', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
