    </t>
    ', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (971, 16, NULL, 1, 1, 'report_stock_rule_vertical_bar', NULL, 'stock.report_stock_rule_vertical_bar', 'qweb', 'stock/report/report_stock_rule.xml', 'primary', '{"en_US": "<t t-name=\"stock.report_stock_rule_vertical_bar\">\n        <div class=\"o_report_stock_rule_vertical_bar\">\n            <svg width=\"100%\" height=\"100%\" viewBox=\"0 0 1 1\">\n                <line y1=\"-12\" x2=\"0\" y2=\"12\" x1=\"0\" t-attf-style=\"stroke: #{color};\"/>\n            </svg>\n        </div>\n    </t>"}', '<?xml version="1.0"?>
<t t-name="stock.report_stock_rule_vertical_bar">
