INSERT INTO public.ir_ui_view VALUES (972, 16, NULL, 1, 1, 'report_stock_rule_right_arrow', NULL, 'stock.report_stock_rule_right_arrow', 'qweb', 'stock/report/report_stock_rule.xml', 'primary', '{"en_US": "<t t-name=\"stock.report_stock_rule_right_arrow\">\n        <div t-attf-class=\"o_report_stock_rule_arrow {{ ''o_report_stock_rule_rtl'' if is_rtl else '''' }}\">\n            <svg width=\"100%\" height=\"100%\" viewBox=\"0 0 10 10\">\n                <polygon points=\"0,0 0,10 10,5\" t-attf-style=\"stroke: #{color}; fill: #{color};\"/>\n            </svg>\n        </div>\n    </t>"}', '<?xml version="1.0"?>
<t t-name="stock.report_stock_rule_right_arrow">
        <div t-attf-class="o_report_stock_rule_arrow {{ ''o_report_stock_rule_rtl'' if is_rtl else '''' }}">
            <svg width="100%" height="100%" viewBox="0 0 10 10">
                <polygon points="0,0 0,10 10,5" t-attf-style="stroke: #{color}; fill: #{color};"/>
