    ', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (973, 16, NULL, 1, 1, 'report_stock_rule_left_arrow', NULL, 'stock.report_stock_rule_left_arrow', 'qweb', 'stock/report/report_stock_rule.xml', 'primary', '{"en_US": "<t t-name=\"stock.report_stock_rule_left_arrow\">\n        <div t-attf-class=\"o_report_stock_rule_arrow {{ ''o_report_stock_rule_rtl'' if is_rtl else '''' }}\">\n            <svg width=\"100%\" height=\"100%\" viewBox=\"0 0 10 10\">\n                <polygon points=\"0,5 10,10 10,0\" t-attf-style=\"stroke: #{color}; fill: #{color};\"/>\n            </svg>\n        </div>\n    </t>"}', '<?xml version="1.0"?>
