INSERT INTO public.ir_ui_view VALUES (980, 16, NULL, 1, 1, 'label_lot_template_view', NULL, 'stock.label_lot_template_view', 'qweb', 'stock/report/product_templates.xml', 'primary', '{"en_US": "<t t-name=\"stock.label_lot_template_view\">\n            <t t-foreach=\"docs\" t-as=\"lot\">\n                <t t-translation=\"off\">\n^XA^CI28\n^FO100,50\n^A0N,44,33^FD<t t-out=\"lot[''display_name_markup'']\"/>^FS\n^FO100,100\n^A0N,44,33^FDLN/SN: <t t-out=\"lot[''name'']\"/>^FS\n                    <t t-if=\"env.user.has_group(''stock.group_stock_lot_print_gs1'')\">\n                        <t t-set=\"final_barcode\" t-value=\"''''\"/>\n                        <t t-if=\"lot[''lot_record''].product_id.valid_ean\" t-set=\"final_barcode\" t-value=\"''01'' + ''0'' * (14 - len(lot[''lot_record''].product_id.barcode)) + lot[''lot_record''].product_id.barcode\"/>\n                        <!-- TODO: must keep lot/sn as last value in barcode because we cannot pad ''0''s without changing lot/sn name until we can scan in FNC1. -->\n                        <t t-if=\"lot[''lot_record''].product_id.tracking == ''lot''\" name=\"datamatrix_lot\" t-set=\"final_barcode\" t-value=\"(final_barcode or '''') + ''10'' + lot[''name'']\"/>\n                        <t t-elif=\"lot[''lot_record''].product_id.tracking == ''serial''\" t-set=\"final_barcode\" t-value=\"(final_barcode or '''') + ''21'' + lot[''name'']\"/>\n^FO425,150^BY3\n^BXN,8,200\n^FD<t t-out=\"final_barcode\"/>^FS\n                    </t>\n                    <t t-else=\"\" name=\"code128_barcode\">\n^FO100,150^BY3\n^BCN,100,Y,N,N\n^FD<t t-out=\"lot[''name'']\"/>^FS\n                    </t>\n^XZ\n                </t>\n            </t>\n        </t>"}', '<?xml version="1.0"?>
<t t-name="stock.label_lot_template_view">
            <t t-foreach="docs" t-as="lot">
                <t t-translation="off">
^XA^CI28
^FO100,50
^A0N,44,33^FD<t t-out="lot[''display_name_markup'']"/>^FS
^FO100,100
^A0N,44,33^FDLN/SN: <t t-out="lot[''name'']"/>^FS
                    <t t-if="env.user.has_group(''stock.group_stock_lot_print_gs1'')">
                        <t t-set="final_barcode" t-value="''''"/>
                        <t t-if="lot[''lot_record''].product_id.valid_ean" t-set="final_barcode" t-value="''01'' + ''0'' * (14 - len(lot[''lot_record''].product_id.barcode)) + lot[''lot_record''].product_id.barcode"/>
                        <!-- TODO: must keep lot/sn as last value in barcode because we cannot pad ''0''s without changing lot/sn name until we can scan in FNC1. -->
                        <t t-if="lot[''lot_record''].product_id.tracking == ''lot''" name="datamatrix_lot" t-set="final_barcode" t-value="(final_barcode or '''') + ''10'' + lot[''name'']"/>
                        <t t-elif="lot[''lot_record''].product_id.tracking == ''serial''" t-set="final_barcode" t-value="(final_barcode or '''') + ''21'' + lot[''name'']"/>
^FO425,150^BY3
^BXN,8,200
^FD<t t-out="final_barcode"/>^FS
                    </t>
                    <t t-else="" name="code128_barcode">
^FO100,150^BY3
^BCN,100,Y,N,N
^FD<t t-out="lot[''name'']"/>^FS
                    </t>
^XZ
                </t>
            </t>
        </t>
    ', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (975, 16, NULL, 1, 1, 'label_package_template_view', NULL, 'stock.label_package_template_view', 'qweb', 'stock/report/package_templates.xml', 'primary', '{"en_US": "<t t-name=\"stock.label_package_template_view\">\n            <t t-foreach=\"docs\" t-as=\"package\">\n                <t t-translation=\"off\">\n^XA\n                    <t t-if=\"package.valid_sscc\">\n                        <t t-set=\"barcode\" t-value=\"''00'' + package.name\"/>\n                        <t t-if=\"package.pack_date\" name=\"datamatrix_pack_date\" t-set=\"barcode\" t-value=\"barcode + ''13'' + package.pack_date.strftime(''%y%m%d'')\"/>\n^FO310,50\n^A0N,44,33^FDSSCC: <t t-out=\"package.name\"/>^FS\n^FO310,100^BY3\n<t t-if=\"package.pack_date\">^A0N,44,33^FDPack Date: <t t-out=\"package.pack_date\" t-options=\"{&quot;widget&quot;: &quot;date&quot;}\"/>^FS</t>\n^FO310,150^BY3\n<t t-if=\"package.package_type_id\">^A0N,44,33^FDPackage Type: <t t-out=\"package.package_type_id.name\"/>^FS</t>\n^FO100,50^BY3\n^BXN,10,200\n^FD<t t-out=\"barcode\"/>^FS\n                    </t>\n                    <t t-else=\"\">\n^FO100,50\n^A0N,44,33^FD<t t-out=\"package.name\"/>^FS\n^FO100,100^BY3\n^BCN,100,Y,N,N\n^FD<t t-out=\"package.name\"/>^FS\n                    </t>\n^XZ\n                </t>\n            </t>\n        </t>"}', '<?xml version="1.0"?>
<t t-name="stock.label_package_template_view">
            <t t-foreach="docs" t-as="package">
                <t t-translation="off">
^XA
                    <t t-if="package.valid_sscc">
                        <t t-set="barcode" t-value="''00'' + package.name"/>
                        <t t-if="package.pack_date" name="datamatrix_pack_date" t-set="barcode" t-value="barcode + ''13'' + package.pack_date.strftime(''%y%m%d'')"/>
^FO310,50
^A0N,44,33^FDSSCC: <t t-out="package.name"/>^FS
^FO310,100^BY3
<t t-if="package.pack_date">^A0N,44,33^FDPack Date: <t t-out="package.pack_date" t-options="{&quot;widget&quot;: &quot;date&quot;}"/>^FS</t>
^FO310,150^BY3
<t t-if="package.package_type_id">^A0N,44,33^FDPackage Type: <t t-out="package.package_type_id.name"/>^FS</t>
^FO100,50^BY3
^BXN,10,200
^FD<t t-out="barcode"/>^FS
                    </t>
                    <t t-else="">
^FO100,50
^A0N,44,33^FD<t t-out="package.name"/>^FS
^FO100,100^BY3
^BCN,100,Y,N,N
^FD<t t-out="package.name"/>^FS
                    </t>
^XZ
                </t>
            </t>
        </t>
    ', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (976, 16, NULL, 1, 1, 'label_transfer_template_view_zpl', NULL, 'stock.label_transfer_template_view_zpl', 'qweb', 'stock/report/picking_templates.xml', 'primary', '{"en_US": "<t t-name=\"stock.label_transfer_template_view_zpl\">\n            <t t-set=\"uom_categ_unit\" t-value=\"env.ref(''uom.product_uom_categ_unit'')\"/>\n            <t t-foreach=\"docs\" t-as=\"picking\">\n\n                <t t-set=\"picking_quantity\" t-value=\"any(picking.move_ids.move_line_ids.mapped(''quantity''))\"/>\n                <t t-foreach=\"picking.move_ids\" t-as=\"move\">\n                    <t t-foreach=\"move.move_line_ids\" t-as=\"move_line\">\n                        <t t-if=\"move_line.product_uom_id.category_id == uom_categ_unit\">\n                            <t t-if=\"picking_quantity\">\n                                <t t-set=\"qty\" t-value=\"int(move_line.quantity)\"/>\n                            </t>\n                            <t t-else=\"\">\n                                <t t-set=\"qty\" t-value=\"int(move_line.reserved_uom_qty)\"/>\n                            </t>\n                        </t>\n                        <t t-else=\"\">\n                            <t t-set=\"qty\" t-value=\"1\"/>\n                        </t>\n                        <t t-foreach=\"range(qty)\" t-as=\"item\">\n                            <t t-translation=\"off\">\n^XA\n^FO100,50\n^A0N,44,33^FD<t t-esc=\"move_line.product_id.display_name\"/>^FS\n^FO100,100\n<t t-if=\"move_line.product_id.tracking != ''none'' and (move_line.lot_id or move_line.lot_name)\">\n^A0N,44,33^FDLN/SN: <t t-esc=\"move_line.lot_id.name or move_line.lot_name\"/>^FS\n^FO100,150^BY3\n^BCN,100,Y,N,N\n^FD<t t-esc=\"move_line.lot_id.name or move_line.lot_name\"/>^FS\n</t>\n<t t-if=\"move_line.product_id.tracking == ''none'' and move_line.product_id.barcode\">\n^BCN,100,Y,N,N\n^FD<t t-esc=\"move_line.product_id.barcode\"/>^FS\n</t>\n^XZ\n                            </t>\n                        </t>\n                    </t>\n                </t>\n            </t>\n        </t>"}', '<?xml version="1.0"?>
<t t-name="stock.label_transfer_template_view_zpl">
            <t t-set="uom_categ_unit" t-value="env.ref(''uom.product_uom_categ_unit'')"/>
            <t t-foreach="docs" t-as="picking">

                <t t-set="picking_quantity" t-value="any(picking.move_ids.move_line_ids.mapped(''quantity''))"/>
                <t t-foreach="picking.move_ids" t-as="move">
                    <t t-foreach="move.move_line_ids" t-as="move_line">
                        <t t-if="move_line.product_uom_id.category_id == uom_categ_unit">
                            <t t-if="picking_quantity">
                                <t t-set="qty" t-value="int(move_line.quantity)"/>
                            </t>
                            <t t-else="">
                                <t t-set="qty" t-value="int(move_line.reserved_uom_qty)"/>
                            </t>
                        </t>
                        <t t-else="">
                            <t t-set="qty" t-value="1"/>
                        </t>
                        <t t-foreach="range(qty)" t-as="item">
                            <t t-translation="off">
^XA
^FO100,50
^A0N,44,33^FD<t t-esc="move_line.product_id.display_name"/>^FS
^FO100,100
<t t-if="move_line.product_id.tracking != ''none'' and (move_line.lot_id or move_line.lot_name)">
^A0N,44,33^FDLN/SN: <t t-esc="move_line.lot_id.name or move_line.lot_name"/>^FS
^FO100,150^BY3
^BCN,100,Y,N,N
^FD<t t-esc="move_line.lot_id.name or move_line.lot_name"/>^FS
</t>
<t t-if="move_line.product_id.tracking == ''none'' and move_line.product_id.barcode">
^BCN,100,Y,N,N
^FD<t t-esc="move_line.product_id.barcode"/>^FS
</t>
^XZ
                            </t>
                        </t>
                    </t>
                </t>
            </t>
        </t>

        ', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (977, 16, NULL, 1, 1, 'label_transfer_template_view_pdf', NULL, 'stock.label_transfer_template_view_pdf', 'qweb', 'stock/report/picking_templates.xml', 'primary', '{"en_US": "<t t-name=\"stock.label_transfer_template_view_pdf\">\n            <t t-call=\"web.basic_layout\">\n                <div class=\"page\">\n                    <t t-set=\"uom_categ_unit\" t-value=\"env.ref(''uom.product_uom_categ_unit'')\"/>\n                    <t t-foreach=\"docs\" t-as=\"picking\">\n                        <t t-set=\"picking_quantity\" t-value=\"any(picking.move_ids.move_line_ids.mapped(''quantity''))\"/>\n                        <t t-foreach=\"picking.move_ids\" t-as=\"move\">\n                            <t t-foreach=\"move.move_line_ids\" t-as=\"move_line\">\n                                <t t-if=\"move_line.product_uom_id.category_id == uom_categ_unit\">\n                                    <t t-if=\"picking_quantity\">\n                                        <t t-set=\"qty\" t-value=\"int(move_line.quantity)\"/>\n                                    </t>\n                                    <t t-else=\"\">\n                                        <t t-set=\"qty\" t-value=\"int(move_line.reserved_uom_qty)\"/>\n                                    </t>\n                                </t>\n                                <t t-else=\"\">\n                                    <t t-set=\"qty\" t-value=\"1\"/>\n                                </t>\n                                <t t-foreach=\"range(qty)\" t-as=\"item\">\n                                    <t t-translation=\"off\">\n                                        <div style=\"display: inline-table; height: 10rem; width: 32%;\">\n                                            <table class=\"table table-bordered\" style=\"border: 2px solid black;\" t-if=\"picking.move_ids\">\n                                                <tr>\n                                                    <th class=\"table-active text-start\" style=\"height:4rem;\">\n                                                        <span t-esc=\"move.product_id.display_name\"/>\n                                                    </th>\n                                                </tr>\n                                                <t t-if=\"move_line.product_id.tracking != ''none''\">\n                                                    <tr>\n                                                        <td class=\"text-center align-middle\">\n                                                            <t t-if=\"move_line.lot_name or move_line.lot_id\">\n                                                                <div t-field=\"move_line.lot_name\" t-options=\"{''widget'': ''barcode'', ''width'': 600, ''height'': 150, ''img_style'': ''width:100%;height:4rem''}\"/>\n                                                                <span t-esc=\"move_line.lot_name or move_line.lot_id.name\"/>\n                                                            </t>\n                                                            <t t-else=\"\">\n                                                                <span class=\"text-muted\">No barcode available</span>\n                                                            </t>\n                                                        </td>\n                                                    </tr>\n                                                </t>\n                                                <t t-if=\"move_line.product_id.tracking == ''none''\">\n                                                    <tr>\n                                                        <td class=\"text-center align-middle\" style=\"height: 6rem;\">\n                                                            <t t-if=\"move_line.product_id.barcode\">\n                                                                <div t-field=\"move_line.product_id.barcode\" t-options=\"{''widget'': ''barcode'', ''width'': 600, ''height'': 150, ''img_style'': ''width:100%;height:4rem''}\"/>\n                                                                <span t-esc=\"move_line.product_id.barcode\"/>\n                                                            </t>\n                                                            <t t-else=\"\">\n                                                                <span class=\"text-muted\">No barcode available</span>\n                                                            </t>\n                                                        </td>\n                                                    </tr>\n                                                </t>\n                                            </table>\n                                        </div>\n                                    </t>\n                                </t>\n                            </t>\n                        </t>\n                    </t>\n                </div>\n            </t>\n        </t>"}', '<?xml version="1.0"?>
<t t-name="stock.label_transfer_template_view_pdf">
            <t t-call="web.basic_layout">
                <div class="page">
                    <t t-set="uom_categ_unit" t-value="env.ref(''uom.product_uom_categ_unit'')"/>
                    <t t-foreach="docs" t-as="picking">
                        <t t-set="picking_quantity" t-value="any(picking.move_ids.move_line_ids.mapped(''quantity''))"/>
                        <t t-foreach="picking.move_ids" t-as="move">
                            <t t-foreach="move.move_line_ids" t-as="move_line">
                                <t t-if="move_line.product_uom_id.category_id == uom_categ_unit">
                                    <t t-if="picking_quantity">
                                        <t t-set="qty" t-value="int(move_line.quantity)"/>
                                    </t>
                                    <t t-else="">
                                        <t t-set="qty" t-value="int(move_line.reserved_uom_qty)"/>
                                    </t>
                                </t>
                                <t t-else="">
                                    <t t-set="qty" t-value="1"/>
                                </t>
                                <t t-foreach="range(qty)" t-as="item">
                                    <t t-translation="off">
                                        <div style="display: inline-table; height: 10rem; width: 32%;">
                                            <table class="table table-bordered" style="border: 2px solid black;" t-if="picking.move_ids">
                                                <tr>
                                                    <th class="table-active text-start" style="height:4rem;">
                                                        <span t-esc="move.product_id.display_name"/>
                                                    </th>
                                                </tr>
                                                <t t-if="move_line.product_id.tracking != ''none''">
                                                    <tr>
                                                        <td class="text-center align-middle">
                                                            <t t-if="move_line.lot_name or move_line.lot_id">
                                                                <div t-field="move_line.lot_name" t-options="{''widget'': ''barcode'', ''width'': 600, ''height'': 150, ''img_style'': ''width:100%;height:4rem''}"/>
                                                                <span t-esc="move_line.lot_name or move_line.lot_id.name"/>
                                                            </t>
                                                            <t t-else="">
                                                                <span class="text-muted">No barcode available</span>
                                                            </t>
                                                        </td>
                                                    </tr>
                                                </t>
                                                <t t-if="move_line.product_id.tracking == ''none''">
                                                    <tr>
                                                        <td class="text-center align-middle" style="height: 6rem;">
                                                            <t t-if="move_line.product_id.barcode">
                                                                <div t-field="move_line.product_id.barcode" t-options="{''widget'': ''barcode'', ''width'': 600, ''height'': 150, ''img_style'': ''width:100%;height:4rem''}"/>
                                                                <span t-esc="move_line.product_id.barcode"/>
                                                            </t>
                                                            <t t-else="">
                                                                <span class="text-muted">No barcode available</span>
                                                            </t>
                                                        </td>
                                                    </tr>
                                                </t>
                                            </table>
                                        </div>
                                    </t>
                                </t>
                            </t>
                        </t>
                    </t>
                </div>
            </t>
        </t>

        ', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (978, 16, NULL, 1, 1, 'label_picking_type_view', NULL, 'stock.label_picking_type_view', 'qweb', 'stock/report/picking_templates.xml', 'primary', '{"en_US": "<t t-name=\"stock.label_picking_type_view\">\n            <t t-foreach=\"docs\" t-as=\"operation\">\n                <t t-translation=\"off\">\n^XA\n^FO100,50\n^A0N,44,33^FD<t t-esc=\"operation.name\"/>^FS\n<t t-if=\"operation.barcode\">\n^FO100,100\n^BCN,100,Y,N,N\n^FD<t t-esc=\"operation.barcode\"/>^FS\n</t>\n^XZ\n                </t>\n            </t>\n        </t>"}', '<?xml version="1.0"?>
