        </t>
    ', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (979, 16, NULL, 1, 1, 'label_product_product_view', NULL, 'stock.label_product_product_view', 'qweb', 'stock/report/product_templates.xml', 'primary', '{"en_US": "<t t-name=\"stock.label_product_product_view\">\n\t\t<t t-foreach=\"quantity.items()\" t-as=\"barcode_and_qty_by_product\">\n                <t t-set=\"product\" t-value=\"barcode_and_qty_by_product[0]\"/>\n                <t t-foreach=\"barcode_and_qty_by_product[1]\" t-as=\"product_info\">\n                    <t t-set=\"barcode\" t-value=\"product_info[''barcode'']\"/>\n                    <t t-set=\"currency_id\" t-value=\"pricelist.currency_id or product.currency_id\"/>\n                    <t t-foreach=\"range(product_info[''quantity''])\" t-as=\"qty\">\n                        <t t-translation=\"off\">\n^XA^CI28\n^FT100,80^A0N,40,30^FD<t t-out=\"product_info[''display_name_markup'']\"/>^FS\n<t t-if=\"product.default_code and len(product.default_code) &gt; 15\">\n^FT100,115^A0N,30,24^FD<t t-out=\"product_info[''default_code''][0]\"/>^FS\n^FT100,150^A0N,30,24^FD<t t-out=\"product_info[''default_code''][1]\"/>^FS\n</t>\n<t t-else=\"\">\n^FT100,150^A0N,30,24^FD<t t-out=\"product_info[''default_code''][0]\"/>^FS\n</t>\n<t t-if=\"price_included\">\n^FO600,100,1\n<t t-if=\"currency_id.position == ''after''\">\n^A0N,66,48^FH^FD<t t-esc=\"pricelist._get_product_price(product, 1, currency_id)\" t-options=\"{&quot;widget&quot;: &quot;float&quot;, &quot;precision&quot;: 2}\"/><t t-esc=\"currency_id.symbol\"/>^FS\n</t>\n<t t-if=\"currency_id.position == ''before''\">\n^A0N,66,48^FH^FD<t t-esc=\"currency_id.symbol\"/><t t-esc=\"pricelist._get_product_price(product, 1, currency_id)\" t-options=\"{&quot;widget&quot;: &quot;float&quot;, &quot;precision&quot;: 2}\"/>^FS\n</t>\n</t>\n<t t-if=\"barcode\">\n^FO100,160^BY3\n^BCN,100,Y,N,N\n^FD<t t-out=\"barcode\"/>^FS\n</t>\n^XZ\n                        </t>\n                    </t>\n                </t>\n            </t>\n        </t>"}', '<?xml version="1.0"?>
<t t-name="stock.label_product_product_view">
		<t t-foreach="quantity.items()" t-as="barcode_and_qty_by_product">
                <t t-set="product" t-value="barcode_and_qty_by_product[0]"/>
                <t t-foreach="barcode_and_qty_by_product[1]" t-as="product_info">
                    <t t-set="barcode" t-value="product_info[''barcode'']"/>
                    <t t-set="currency_id" t-value="pricelist.currency_id or product.currency_id"/>
                    <t t-foreach="range(product_info[''quantity''])" t-as="qty">
                        <t t-translation="off">
^XA^CI28
^FT100,80^A0N,40,30^FD<t t-out="product_info[''display_name_markup'']"/>^FS
<t t-if="product.default_code and len(product.default_code) &gt; 15">
^FT100,115^A0N,30,24^FD<t t-out="product_info[''default_code''][0]"/>^FS
^FT100,150^A0N,30,24^FD<t t-out="product_info[''default_code''][1]"/>^FS
</t>
<t t-else="">
^FT100,150^A0N,30,24^FD<t t-out="product_info[''default_code''][0]"/>^FS
</t>
<t t-if="price_included">
^FO600,100,1
<t t-if="currency_id.position == ''after''">
^A0N,66,48^FH^FD<t t-esc="pricelist._get_product_price(product, 1, currency_id)" t-options="{&quot;widget&quot;: &quot;float&quot;, &quot;precision&quot;: 2}"/><t t-esc="currency_id.symbol"/>^FS
</t>
<t t-if="currency_id.position == ''before''">
^A0N,66,48^FH^FD<t t-esc="currency_id.symbol"/><t t-esc="pricelist._get_product_price(product, 1, currency_id)" t-options="{&quot;widget&quot;: &quot;float&quot;, &quot;precision&quot;: 2}"/>^FS
</t>
</t>
<t t-if="barcode">
^FO100,160^BY3
^BCN,100,Y,N,N
^FD<t t-out="barcode"/>^FS
</t>
^XZ
                        </t>
                    </t>
                </t>
            </t>
        </t>

        ', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (1046, 16, NULL, 1, 1, 'stock.picking.view.activity', 'stock.picking', NULL, 'activity', 'stock/views/stock_picking_views.xml', 'primary', '{"en_US": "<activity string=\"Activity view\">\n                    <templates>\n                        <div t-name=\"activity-box\" class=\"d-block\">\n                            <field name=\"name\" display=\"full\" class=\"o_text_block o_text_bold\"/>\n                            <field name=\"scheduled_date\" widget=\"date\"/>\n                        </div>\n                    </templates>\n                </activity>"}', '<?xml version="1.0"?>
<activity string="Activity view">
                    <templates>
                        <div t-name="activity-box" class="d-block">
                            <field name="name" display="full" class="o_text_block o_text_bold"/>
                            <field name="scheduled_date" widget="date"/>
                        </div>
                    </templates>
                </activity>
            ', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (981, 16, NULL, 1, 1, 'label_product_packaging_view', NULL, 'stock.label_product_packaging_view', 'qweb', 'stock/report/product_packaging.xml', 'primary', '{"en_US": "<t t-name=\"stock.label_product_packaging_view\">\n            <t t-foreach=\"docs\" t-as=\"packaging\">\n                <t t-translation=\"off\">\n^XA\n^FO100,50\n^A0N,44,33^FD<t t-esc=\"packaging.name\"/>^FS\n^FO100,100\n^A0N,44,33^FD<t t-esc=\"packaging.product_id.display_name\"/>^FS\n^FO100,150\n^A0N,44,33^FDQty: <t t-esc=\"packaging.qty\"/> <t t-esc=\"packaging.product_uom_id.name\" groups=\"uom.group_uom\"/>^FS\n<t t-if=\"packaging.barcode\">\n^FO100,200^BY3\n^BCN,100,Y,N,N\n^FD<t t-esc=\"packaging.barcode\"/>^FS\n</t>\n^XZ\n                </t>\n            </t>\n        </t>"}', '<?xml version="1.0"?>
<t t-name="stock.label_product_packaging_view">
            <t t-foreach="docs" t-as="packaging">
                <t t-translation="off">
^XA
^FO100,50
^A0N,44,33^FD<t t-esc="packaging.name"/>^FS
^FO100,100
^A0N,44,33^FD<t t-esc="packaging.product_id.display_name"/>^FS
^FO100,150
^A0N,44,33^FDQty: <t t-esc="packaging.qty"/> <t t-esc="packaging.product_uom_id.name" groups="uom.group_uom"/>^FS
<t t-if="packaging.barcode">
^FO100,200^BY3
^BCN,100,Y,N,N
^FD<t t-esc="packaging.barcode"/>^FS
</t>
^XZ
                </t>
            </t>
        </t>
    ', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (982, 16, NULL, 1, 1, 'stock.report_return_slip', NULL, 'stock.report_return_slip', 'qweb', 'stock/report/report_return_slip.xml', 'primary', '{"en_US": "<t t-name=\"stock.report_return_slip\">\n        <t t-call=\"web.html_container\">\n            <t t-foreach=\"docs\" t-as=\"o\">\n                <t t-call=\"web.external_layout\">\n                <div class=\"page\">\n                    <div class=\"oe_structure\"/>\n                    <div class=\"row mt8\">\n                        <div class=\"col-8\">\n                            <h2>\n                                <span>RETURN OF <span t-out=\"o.name\">Default Return Name</span></span>\n                            </h2>\n                            <p>\n                                Please put this document inside your return parcel.<br/>\n                                Your parcel must be sent to this address:\n                            </p>\n                            <span t-field=\"(o if o.picking_type_code == ''incoming'' else o.location_id.warehouse_id).partner_id\" t-options=\"{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;], &quot;no_marker&quot;: True}\">Demo Address and Name</span>\n                        </div>\n                        <div class=\"col-4 text-center mt-4\">\n                            <div>\n                                <span t-field=\"o.name\" t-options=\"{''widget'': ''barcode'', ''img_style'': ''width:100%;''}\">Default Barcode Name</span>\n                                <span t-out=\"o.name\">Default Name</span>\n                            </div>\n                            <div style=\"margin-top:200px;\">\n                                <span t-out=\"''O-BTN.return''\" t-options=\"{''widget'': ''barcode'', ''img_style'': ''width:100%;''}\">Default O-BTN.return Barcode</span>\n                                <span>O-BTN.return</span>\n                            </div>\n                        </div>\n                    </div>\n                    <div class=\"oe_structure\"/>\n                </div>\n            </t>\n            </t>\n        </t>\n    </t>"}', '<?xml version="1.0"?>
<t t-name="stock.report_return_slip">
        <t t-call="web.html_container">
            <t t-foreach="docs" t-as="o">
                <t t-call="web.external_layout">
                <div class="page">
                    <div class="oe_structure"/>
                    <div class="row mt8">
                        <div class="col-8">
                            <h2>
                                <span>RETURN OF <span t-out="o.name">Default Return Name</span></span>
                            </h2>
                            <p>
                                Please put this document inside your return parcel.<br/>
                                Your parcel must be sent to this address:
                            </p>
                            <span t-field="(o if o.picking_type_code == ''incoming'' else o.location_id.warehouse_id).partner_id" t-options="{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;], &quot;no_marker&quot;: True}">Demo Address and Name</span>
                        </div>
                        <div class="col-4 text-center mt-4">
                            <div>
                                <span t-field="o.name" t-options="{''widget'': ''barcode'', ''img_style'': ''width:100%;''}">Default Barcode Name</span>
                                <span t-out="o.name">Default Name</span>
                            </div>
                            <div style="margin-top:200px;">
                                <span t-out="''O-BTN.return''" t-options="{''widget'': ''barcode'', ''img_style'': ''width:100%;''}">Default O-BTN.return Barcode</span>
                                <span>O-BTN.return</span>
                            </div>
                        </div>
                    </div>
                    <div class="oe_structure"/>
                </div>
            </t>
            </t>
        </t>
    </t>

    ', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (983, 16, NULL, 1, 1, 'stock_assign_serial_numbers', 'stock.assign.serial', NULL, 'form', 'stock/wizard/stock_assign_serial_views.xml', 'primary', '{"en_US": "<form string=\"Assign Serial Numbers\">\n                <group>\n                    <field name=\"move_id\" invisible=\"1\"/>\n                    <field name=\"product_id\" readonly=\"1\"/>\n                    <field name=\"next_serial_number\"/>\n                    <field name=\"next_serial_count\"/>\n                </group>\n                <footer>\n                    <button name=\"generate_serial_numbers\" type=\"object\" data-hotkey=\"q\" string=\"Assign Serial Numbers\" class=\"oe_highlight\"/>\n                    <button special=\"cancel\" data-hotkey=\"x\" string=\"Cancel\"/>\n                </footer>\n            </form>"}', '<?xml version="1.0"?>
<form string="Assign Serial Numbers">
                <group>
                    <field name="move_id" invisible="1"/>
                    <field name="product_id" readonly="1"/>
                    <field name="next_serial_number"/>
                    <field name="next_serial_count"/>
                </group>
                <footer>
                    <button name="generate_serial_numbers" type="object" data-hotkey="q" string="Assign Serial Numbers" class="oe_highlight"/>
                    <button special="cancel" data-hotkey="x" string="Cancel"/>
                </footer>
            </form>
        ', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (984, 16, NULL, 1, 1, 'Change Product Quantity', 'stock.change.product.qty', NULL, 'form', 'stock/wizard/stock_change_product_qty_views.xml', 'primary', '{"en_US": "<form string=\"Update Product Quantity\">\n                    <div class=\"container\">\n                        <field name=\"product_tmpl_id\" invisible=\"1\"/>\n                        <field name=\"product_variant_count\" invisible=\"1\"/>\n                        <div class=\"row\" invisible=\"context.get(''default_product_id'')\">\n                            <label for=\"product_id\" class=\"col-5 col-md-4 col-lg-3\"/>\n                            <field name=\"product_id\" class=\"col-6\" options=\"{''no_open'': True, ''no_create'': True}\" domain=\"[(''product_tmpl_id'', ''='', product_tmpl_id)]\" readonly=\"context.get(''default_product_id'')\" invisible=\"product_variant_count == 1\"/>\n                        </div>\n                        <div class=\"row\">\n                            <label for=\"new_quantity\" class=\"col-5 col-md-4 col-lg-3\"/>\n                            <div class=\"col-6 col-md-5 col-lg-4 row\">\n                                <field name=\"new_quantity\" class=\"col-4 pe-0\"/>\n                                <field name=\"product_uom_id\" groups=\"uom.group_uom\" options=\"{''no_open'': True}\" class=\"col-8 ps-2\"/>\n                            </div>\n                        </div>\n                    </div>\n                    <footer>\n                        <button name=\"change_product_qty\" string=\"Apply\" type=\"object\" class=\"btn-primary\" data-hotkey=\"q\"/>\n                        <button string=\"Discard\" class=\"btn-secondary\" special=\"cancel\" data-hotkey=\"x\"/>\n                    </footer>\n                </form>"}', '<?xml version="1.0"?>
<form string="Update Product Quantity">
                    <div class="container">
                        <field name="product_tmpl_id" invisible="1"/>
                        <field name="product_variant_count" invisible="1"/>
                        <div class="row" invisible="context.get(''default_product_id'')">
                            <label for="product_id" class="col-5 col-md-4 col-lg-3"/>
                            <field name="product_id" class="col-6" options="{''no_open'': True, ''no_create'': True}" domain="[(''product_tmpl_id'', ''='', product_tmpl_id)]" readonly="context.get(''default_product_id'')" invisible="product_variant_count == 1"/>
                        </div>
                        <div class="row">
                            <label for="new_quantity" class="col-5 col-md-4 col-lg-3"/>
                            <div class="col-6 col-md-5 col-lg-4 row">
                                <field name="new_quantity" class="col-4 pe-0"/>
                                <field name="product_uom_id" groups="uom.group_uom" options="{''no_open'': True}" class="col-8 ps-2"/>
                            </div>
                        </div>
                    </div>
                    <footer>
                        <button name="change_product_qty" string="Apply" type="object" class="btn-primary" data-hotkey="q"/>
                        <button string="Discard" class="btn-secondary" special="cancel" data-hotkey="x"/>
                    </footer>
                </form>
            ', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (985, 16, NULL, 1, 1, 'Return lines', 'stock.return.picking', NULL, 'form', 'stock/wizard/stock_picking_return_views.xml', 'primary', '{"en_US": "<form>\n                <field name=\"move_dest_exists\" invisible=\"1\"/>\n                <field name=\"picking_id\" invisible=\"1\" force_save=\"1\"/>\n                <field name=\"parent_location_id\" invisible=\"1\"/>\n                <field name=\"original_location_id\" invisible=\"1\"/>\n                <field name=\"company_id\" invisible=\"1\"/>\n                <div class=\"oe_grey\" invisible=\"not move_dest_exists\">\n                    <p>This picking appears to be chained with another operation. Later, if you receive the goods you are returning now, make sure to <b>reverse</b> the returned picking in order to avoid logistic rules to be applied again (which would create duplicated operations)</p>\n                </div>\n                <field name=\"product_return_moves\">\n                    <tree editable=\"top\" create=\"0\">\n                        <field name=\"product_id\" options=\"{''no_create'': True, ''no_open'': True}\" force_save=\"1\"/>\n                        <field name=\"quantity\"/>\n                        <field name=\"uom_id\" groups=\"uom.group_uom\"/>\n                        <field name=\"move_id\" column_invisible=\"True\"/>\n                    </tree>\n                </field>\n                <group>\n                    <field name=\"location_id\" options=\"{''no_create'': True, ''no_open'': True}\" groups=\"stock.group_stock_multi_locations\" required=\"1\"/>\n                </group>\n                <footer>\n                    <button name=\"create_returns\" string=\"Return\" type=\"object\" class=\"btn-primary\" data-hotkey=\"q\"/>\n                    <button string=\"Cancel\" class=\"btn-secondary\" special=\"cancel\" data-hotkey=\"x\"/>\n                </footer>\n            </form>"}', '<?xml version="1.0"?>
<form>
                <field name="move_dest_exists" invisible="1"/>
                <field name="picking_id" invisible="1" force_save="1"/>
                <field name="parent_location_id" invisible="1"/>
                <field name="original_location_id" invisible="1"/>
                <field name="company_id" invisible="1"/>
                <div class="oe_grey" invisible="not move_dest_exists">
                    <p>This picking appears to be chained with another operation. Later, if you receive the goods you are returning now, make sure to <b>reverse</b> the returned picking in order to avoid logistic rules to be applied again (which would create duplicated operations)</p>
                </div>
                <field name="product_return_moves">
                    <tree editable="top" create="0">
                        <field name="product_id" options="{''no_create'': True, ''no_open'': True}" force_save="1"/>
                        <field name="quantity"/>
                        <field name="uom_id" groups="uom.group_uom"/>
                        <field name="move_id" column_invisible="True"/>
                    </tree>
                </field>
                <group>
                    <field name="location_id" options="{''no_create'': True, ''no_open'': True}" groups="stock.group_stock_multi_locations" required="1"/>
                </group>
                <footer>
                    <button name="create_returns" string="Return" type="object" class="btn-primary" data-hotkey="q"/>
                    <button string="Cancel" class="btn-secondary" special="cancel" data-hotkey="x"/>
                </footer>
            </form>
        ', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (986, 16, NULL, 1, 1, 'Run Schedulers Manually', 'stock.scheduler.compute', NULL, 'form', 'stock/wizard/stock_scheduler_compute_views.xml', 'primary', '{"en_US": "<form string=\"Parameters\">\n                <p>\n                The stock will be reserved for operations waiting for availability and the reordering rules will be triggered.\n                </p>\n                <footer>\n                    <button name=\"procure_calculation\" string=\"Run Scheduler\" type=\"object\" class=\"btn-primary\" data-hotkey=\"q\"/>\n                    <button string=\"Cancel\" class=\"btn-secondary\" special=\"cancel\" data-hotkey=\"x\"/>\n                </footer>\n            </form>"}', '<?xml version="1.0"?>
<form string="Parameters">
                <p>
                The stock will be reserved for operations waiting for availability and the reordering rules will be triggered.
                </p>
                <footer>
                    <button name="procure_calculation" string="Run Scheduler" type="object" class="btn-primary" data-hotkey="q"/>
                    <button string="Cancel" class="btn-secondary" special="cancel" data-hotkey="x"/>
                </footer>
            </form>
        ', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (987, 16, NULL, 1, 1, 'stock.inventory.conflict.form.view', 'stock.inventory.conflict', NULL, 'form', 'stock/wizard/stock_inventory_conflict.xml', 'primary', '{"en_US": "<form>\n                <div>\n                    <strong>Due to some stock moves done between your initial update of the quantity and now, the difference of quantity is not consistent anymore.</strong>\n                </div>\n                <div>\n                    You can either :\n                    <ul>\n                        <li>Keep the <strong>Counted Quantity</strong> (the Difference will be updated)</li>\n                        <li>Keep the <strong>Difference</strong> (the Counted Quantity will be updated to reflect the same difference as when you counted)</li>\n                        <li>Discard and manually resolve the conflict</li>\n                    </ul>\n                </div>\n                <div>\n                    <br/>\n                    <field name=\"quant_ids\" invisible=\"1\"/>\n                    <field name=\"quant_to_fix_ids\" readonly=\"1\" style=\"margin-top:10px;\">\n                        <tree editable=\"bottom\" create=\"0\" delete=\"0\">\n                            <field name=\"id\" column_invisible=\"True\"/>\n                            <field name=\"tracking\" column_invisible=\"True\"/>\n                            <field name=\"company_id\" column_invisible=\"True\"/>\n                            <field name=\"product_id\" readonly=\"context.get(''single_product'', False) or id\" column_invisible=\"context.get(''single_product'', False)\" force_save=\"1\" options=\"{''no_create'': True}\"/>\n                            <field name=\"location_id\" column_invisible=\"context.get(''hide_location'', False)\" readonly=\"id\" options=\"{''no_create'': True}\"/>\n                            <field name=\"lot_id\" groups=\"stock.group_production_lot\" column_invisible=\"context.get(''hide_lot'', False)\" readonly=\"id or tracking not in [''serial'', ''lot'']\" required=\"tracking != ''none''\" context=\"{''default_product_id'': product_id, ''default_company_id'': company_id}\"/>\n                            <field name=\"package_id\" groups=\"stock.group_tracking_lot\" readonly=\"id\"/>\n                            <field name=\"owner_id\" groups=\"stock.group_tracking_owner\" readonly=\"id\" options=\"{''no_create'': True}\"/>\n                            <field name=\"quantity\" string=\"Quantity\"/>\n                            <field name=\"inventory_quantity\" string=\"Counted Quantity\" decoration-muted=\"inventory_quantity == 0\" readonly=\"0\"/>\n                            <field name=\"inventory_diff_quantity\" string=\"Difference\" decoration-muted=\"inventory_quantity == 0\" decoration-danger=\"inventory_diff_quantity &lt; 0\" decoration-success=\"inventory_diff_quantity &gt; 0\" decoration-bf=\"inventory_diff_quantity != 0\"/>\n                            <field name=\"product_uom_id\" groups=\"uom.group_uom\"/>\n                            <field name=\"company_id\" groups=\"base.group_multi_company\" optional=\"show\"/>\n                        </tree>\n                    </field>\n                </div>\n                <footer>\n                    <button name=\"action_keep_counted_quantity\" string=\"Keep Counted Quantity\" type=\"object\" class=\"btn-primary\" data-hotkey=\"q\"/>\n                    <button name=\"action_keep_difference\" string=\"Keep Difference\" type=\"object\" class=\"btn-primary\" data-hotkey=\"w\"/>\n                    <button name=\"cancel_button\" string=\"Discard\" class=\"btn-secondary\" special=\"cancel\" data-hotkey=\"x\"/>\n                </footer>\n            </form>"}', '<?xml version="1.0"?>
<form>
                <div>
                    <strong>Due to some stock moves done between your initial update of the quantity and now, the difference of quantity is not consistent anymore.</strong>
                </div>
                <div>
                    You can either :
                    <ul>
                        <li>Keep the <strong>Counted Quantity</strong> (the Difference will be updated)</li>
                        <li>Keep the <strong>Difference</strong> (the Counted Quantity will be updated to reflect the same difference as when you counted)</li>
                        <li>Discard and manually resolve the conflict</li>
                    </ul>
                </div>
                <div>
                    <br/>
                    <field name="quant_ids" invisible="1"/>
                    <field name="quant_to_fix_ids" readonly="1" style="margin-top:10px;">
                        <tree editable="bottom" create="0" delete="0">
                            <field name="id" column_invisible="True"/>
                            <field name="tracking" column_invisible="True"/>
                            <field name="company_id" column_invisible="True"/>
                            <field name="product_id" readonly="context.get(''single_product'', False) or id" column_invisible="context.get(''single_product'', False)" force_save="1" options="{''no_create'': True}"/>
                            <field name="location_id" column_invisible="context.get(''hide_location'', False)" readonly="id" options="{''no_create'': True}"/>
                            <field name="lot_id" groups="stock.group_production_lot" column_invisible="context.get(''hide_lot'', False)" readonly="id or tracking not in [''serial'', ''lot'']" required="tracking != ''none''" context="{''default_product_id'': product_id, ''default_company_id'': company_id}"/>
                            <field name="package_id" groups="stock.group_tracking_lot" readonly="id"/>
                            <field name="owner_id" groups="stock.group_tracking_owner" readonly="id" options="{''no_create'': True}"/>
                            <field name="quantity" string="Quantity"/>
                            <field name="inventory_quantity" string="Counted Quantity" decoration-muted="inventory_quantity == 0" readonly="0"/>
                            <field name="inventory_diff_quantity" string="Difference" decoration-muted="inventory_quantity == 0" decoration-danger="inventory_diff_quantity &lt; 0" decoration-success="inventory_diff_quantity &gt; 0" decoration-bf="inventory_diff_quantity != 0"/>
                            <field name="product_uom_id" groups="uom.group_uom"/>
                            <field name="company_id" groups="base.group_multi_company" optional="show"/>
                        </tree>
                    </field>
                </div>
                <footer>
                    <button name="action_keep_counted_quantity" string="Keep Counted Quantity" type="object" class="btn-primary" data-hotkey="q"/>
                    <button name="action_keep_difference" string="Keep Difference" type="object" class="btn-primary" data-hotkey="w"/>
                    <button name="cancel_button" string="Discard" class="btn-secondary" special="cancel" data-hotkey="x"/>
                </footer>
            </form>
        ', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (988, 16, NULL, 1, 1, 'stock_backorder_confirmation', 'stock.backorder.confirmation', NULL, 'form', 'stock/wizard/stock_backorder_confirmation_views.xml', 'primary', '{"en_US": "<form string=\"Backorder creation\">\n                <group>\n                    <group>\n                        <div colspan=\"2\"><p name=\"explanation-text\">\n                            You have processed less products than the initial demand.\n                        </p></div>\n                    </group>\n                    <group>\n                        <div colspan=\"2\" class=\"text-muted\">\n                            Create a backorder if you expect to process the remaining\n                            products later. Do not create a backorder if you will not\n                            process the remaining products.\n                        </div>\n                    </group>\n                </group>\n\n                <!-- Added to ensure a correct default_get behavior\n\n                The wizard is always opened with default_pick_ids values in context,\n                which are used to generate the backorder_confirmation_line_ids.\n\n                To ensure default_pick_ids is correctly converted from the context\n                by default_get, the field has to be present in the view.\n                -->\n                <field name=\"pick_ids\" invisible=\"1\"/>\n\n                <field name=\"show_transfers\" invisible=\"1\"/>\n                <field name=\"backorder_confirmation_line_ids\" nolabel=\"1\" invisible=\"not show_transfers\">\n                    <tree create=\"0\" delete=\"0\" editable=\"top\">\n                        <field name=\"picking_id\"/>\n                        <field name=\"to_backorder\" widget=\"boolean_toggle\"/>\n                    </tree>\n                </field>\n\n                <footer>\n                    <button name=\"process\" string=\"Create Backorder\" type=\"object\" class=\"oe_highlight\" data-hotkey=\"q\"/>\n                    <button name=\"process_cancel_backorder\" string=\"No Backorder\" type=\"object\" class=\"btn-danger text-uppercase\" invisible=\"show_transfers\" data-hotkey=\"w\"/>\n                    <button string=\"Discard\" class=\"btn-secondary\" special=\"cancel\" data-hotkey=\"x\"/>\n                </footer>\n            </form>"}', '<?xml version="1.0"?>
<form string="Backorder creation">
                <group>
                    <group>
                        <div colspan="2"><p name="explanation-text">
                            You have processed less products than the initial demand.
                        </p></div>
                    </group>
                    <group>
                        <div colspan="2" class="text-muted">
                            Create a backorder if you expect to process the remaining
                            products later. Do not create a backorder if you will not
                            process the remaining products.
                        </div>
                    </group>
                </group>

                <!-- Added to ensure a correct default_get behavior

                The wizard is always opened with default_pick_ids values in context,
                which are used to generate the backorder_confirmation_line_ids.

                To ensure default_pick_ids is correctly converted from the context
                by default_get, the field has to be present in the view.
                -->
                <field name="pick_ids" invisible="1"/>

                <field name="show_transfers" invisible="1"/>
                <field name="backorder_confirmation_line_ids" nolabel="1" invisible="not show_transfers">
                    <tree create="0" delete="0" editable="top">
                        <field name="picking_id"/>
                        <field name="to_backorder" widget="boolean_toggle"/>
                    </tree>
                </field>

                <footer>
                    <button name="process" string="Create Backorder" type="object" class="oe_highlight" data-hotkey="q"/>
                    <button name="process_cancel_backorder" string="No Backorder" type="object" class="btn-danger text-uppercase" invisible="show_transfers" data-hotkey="w"/>
                    <button string="Discard" class="btn-secondary" special="cancel" data-hotkey="x"/>
                </footer>
            </form>
        ', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (989, 16, NULL, 1, 1, 'Inventory Report at Date', 'stock.quantity.history', NULL, 'form', 'stock/wizard/stock_quantity_history.xml', 'primary', '{"en_US": "<form string=\"Choose your date\">\n                <group>\n                    <field name=\"inventory_datetime\"/>\n                </group>\n                <footer>\n                    <button name=\"open_at_date\" string=\"Confirm\" type=\"object\" class=\"btn-primary\" data-hotkey=\"q\"/>\n                    <button string=\"Cancel\" class=\"btn-secondary\" special=\"cancel\" data-hotkey=\"x\"/>\n                </footer>\n            </form>"}', '<?xml version="1.0"?>
<form string="Choose your date">
                <group>
