                <footer>
                    <button name="open_at_date" string="Confirm" type="object" class="btn-primary" data-hotkey="q"/>
                    <button string="Cancel" class="btn-secondary" special="cancel" data-hotkey="x"/>
                </footer>
            </form>
        ', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (990, 16, NULL, 1, 1, 'stock.request.count.form.view', 'stock.request.count', NULL, 'form', 'stock/wizard/stock_request_count.xml', 'primary', '{"en_US": "<form>\n                <group>\n                    <field name=\"quant_ids\" invisible=\"1\"/>\n                    <field name=\"inventory_date\"/>\n                    <field name=\"user_id\"/>\n                    <field name=\"set_count\" widget=\"radio\"/>\n                </group>\n                <footer>\n                    <button name=\"action_request_count\" string=\"Confirm\" type=\"object\" class=\"btn-primary\" data-hotkey=\"q\"/>\n                    <button string=\"Discard\" class=\"btn-secondary\" special=\"cancel\" data-hotkey=\"x\"/>\n                </footer>\n            </form>"}', '<?xml version="1.0"?>
<form>
                <group>
                    <field name="quant_ids" invisible="1"/>
                    <field name="inventory_date"/>
                    <field name="user_id"/>
                    <field name="set_count" widget="radio"/>
                </group>
                <footer>
                    <button name="action_request_count" string="Confirm" type="object" class="btn-primary" data-hotkey="q"/>
                    <button string="Discard" class="btn-secondary" special="cancel" data-hotkey="x"/>
                </footer>
            </form>
        ', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (991, 16, NULL, 1, 1, 'Stock Replenishment Information', 'stock.replenishment.info', NULL, 'form', 'stock/wizard/stock_replenishment_info.xml', 'primary', '{"en_US": "<form>\n                <field name=\"orderpoint_id\" invisible=\"1\"/>\n                <field name=\"qty_to_order\" invisible=\"1\"/>\n                <group>\n                    <group>\n                        <field nolabel=\"1\" name=\"json_lead_days\" colspan=\"2\" widget=\"lead_days_widget\"/>\n                    </group>\n                    <group>\n                        <field nolabel=\"1\" name=\"json_replenishment_history\" colspan=\"2\" widget=\"replenishment_history_widget\"/>\n                    </group>\n                </group>\n                <notebook>\n                    <field name=\"warehouseinfo_ids\" invisible=\"1\"/>\n                    <page string=\"Warehouses\" name=\"page_warehouses\" invisible=\"not warehouseinfo_ids\">\n                        <field name=\"wh_replenishment_option_ids\"/>\n                    </page>\n                </notebook>\n                <footer>\n                    <button string=\"Close\" class=\"btn-secondary\" special=\"cancel\" data-hotkey=\"x\"/>\n                </footer>\n            </form>"}', '<?xml version="1.0"?>
<form>
                <field name="orderpoint_id" invisible="1"/>
                <field name="qty_to_order" invisible="1"/>
                <group>
                    <group>
                        <field nolabel="1" name="json_lead_days" colspan="2" widget="lead_days_widget"/>
                    </group>
                    <group>
                        <field nolabel="1" name="json_replenishment_history" colspan="2" widget="replenishment_history_widget"/>
                    </group>
                </group>
                <notebook>
                    <field name="warehouseinfo_ids" invisible="1"/>
                    <page string="Warehouses" name="page_warehouses" invisible="not warehouseinfo_ids">
                        <field name="wh_replenishment_option_ids"/>
                    </page>
                </notebook>
                <footer>
                    <button string="Close" class="btn-secondary" special="cancel" data-hotkey="x"/>
                </footer>
            </form>
        ', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (992, 16, NULL, 1, 1, 'stock.replenishment.option.tree.view', 'stock.replenishment.option', NULL, 'tree', 'stock/wizard/stock_replenishment_info.xml', 'primary', '{"en_US": "<tree>\n                <field name=\"qty_to_order\" column_invisible=\"True\"/>\n                <field name=\"warehouse_id\" string=\"Warehouse\"/>\n                <field name=\"location_id\" string=\"Warehouse Location\"/>\n                <field name=\"free_qty\" decoration-danger=\"free_qty &lt; qty_to_order\" string=\"Available Quantity\"/>\n                <field name=\"uom\" string=\"UoM\"/>\n                <field name=\"route_id\"/>\n                <field name=\"lead_time\"/>\n                <button name=\"select_route\" string=\"Select Route\" type=\"object\" class=\"btn btn-link\"/>\n            </tree>"}', '<?xml version="1.0"?>
<tree>
                <field name="qty_to_order" column_invisible="True"/>
                <field name="warehouse_id" string="Warehouse"/>
                <field name="location_id" string="Warehouse Location"/>
                <field name="free_qty" decoration-danger="free_qty &lt; qty_to_order" string="Available Quantity"/>
                <field name="uom" string="UoM"/>
                <field name="route_id"/>
                <field name="lead_time"/>
                <button name="select_route" string="Select Route" type="object" class="btn btn-link"/>
            </tree>
        ', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (993, 100, NULL, 1, 1, 'stock.replenishment.warning.view', 'stock.replenishment.option', NULL, 'form', 'stock/wizard/stock_replenishment_info.xml', 'primary', '{"en_US": "<form>\n                <div>\n                    <field name=\"warning_message\"/>\n                </div>\n                <footer>\n                    <button name=\"order_avbl\" type=\"object\" class=\"btn-primary\" invisible=\"free_qty &lt;= 0.0\">\n                        Order <field name=\"free_qty\"/>\n                    </button>\n                    <button name=\"order_all\" type=\"object\">\n                        Order <field name=\"qty_to_order\"/>\n                    </button>\n                    <button string=\"Cancel\" class=\"btn-secondary\" special=\"cancel\"/>\n                </footer>\n            </form>"}', '<?xml version="1.0"?>
<form>
                <div>
                    <field name="warning_message"/>
                </div>
                <footer>
                    <button name="order_avbl" type="object" class="btn-primary" invisible="free_qty &lt;= 0.0">
                        Order <field name="free_qty"/>
                    </button>
                    <button name="order_all" type="object">
                        Order <field name="qty_to_order"/>
                    </button>
                    <button string="Cancel" class="btn-secondary" special="cancel"/>
                </footer>
            </form>
        ', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (994, 16, NULL, 1, 1, 'Stock Rules Report', 'stock.rules.report', NULL, 'form', 'stock/wizard/stock_rules_report_views.xml', 'primary', '{"en_US": "<form string=\"Product Routes Report\">\n                <group>\n                    <field name=\"product_tmpl_id\" invisible=\"1\"/>\n                    <field name=\"product_has_variants\" invisible=\"1\"/>\n                    <field name=\"product_id\" domain=\"[(''product_tmpl_id'', ''='', product_tmpl_id)]\" readonly=\"not product_has_variants\" options=\"{''no_create'': True}\"/>\n                    <field name=\"warehouse_ids\" groups=\"stock.group_stock_multi_warehouses\" widget=\"many2many_tags\"/>\n                </group>\n                <footer>\n                    <button name=\"print_report\" string=\"Overview\" type=\"object\" data-hotkey=\"q\" class=\"btn-primary\"/>\n                    <button string=\"Cancel\" class=\"btn-default\" special=\"cancel\" data-hotkey=\"x\"/>\n                </footer>\n            </form>"}', '<?xml version="1.0"?>
<form string="Product Routes Report">
                <group>
                    <field name="product_tmpl_id" invisible="1"/>
                    <field name="product_has_variants" invisible="1"/>
                    <field name="product_id" domain="[(''product_tmpl_id'', ''='', product_tmpl_id)]" readonly="not product_has_variants" options="{''no_create'': True}"/>
                    <field name="warehouse_ids" groups="stock.group_stock_multi_warehouses" widget="many2many_tags"/>
                </group>
                <footer>
                    <button name="print_report" string="Overview" type="object" data-hotkey="q" class="btn-primary"/>
                    <button string="Cancel" class="btn-default" special="cancel" data-hotkey="x"/>
                </footer>
            </form>
        ', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (995, 16, NULL, 1, 1, 'stock.warn.insufficient.qty', 'stock.warn.insufficient.qty', NULL, 'form', 'stock/wizard/stock_warn_insufficient_qty_views.xml', 'primary', '{"en_US": "<form>\n                <field name=\"product_id\" invisible=\"True\"/>\n                <div>\n                    The product is not available in sufficient quantity\n                    <span class=\"oe_inline\" groups=\"stock.group_stock_multi_locations\"> in\n                        <strong><field name=\"location_id\" readonly=\"True\"/></strong>.\n                    </span>\n                </div>\n                <div invisible=\"not quant_ids\">\n                    <br/>\n                    <strong>Current Inventory: </strong>\n                    <field name=\"quant_ids\" style=\"margin-top:10px;\">\n                        <tree>\n                            <field name=\"location_id\" options=\"{''no_create'': True}\"/>\n                            <field name=\"lot_id\" groups=\"stock.group_production_lot\"/>\n                            <field name=\"quantity\"/>\n                        </tree>\n                    </field>\n                </div>\n                <div name=\"description\">\n                </div>\n                <footer>\n                    <button name=\"cancel_button\" string=\"Discard\" class=\"btn-primary\" special=\"cancel\" data-hotkey=\"x\"/>\n                    <button string=\"Confirm\" name=\"action_done\" type=\"object\" class=\"btn-secondary\" data-hotkey=\"q\"/>\n                </footer>\n            </form>"}', '<?xml version="1.0"?>
<form>
                <field name="product_id" invisible="True"/>
                <div>
                    The product is not available in sufficient quantity
                    <span class="oe_inline" groups="stock.group_stock_multi_locations"> in
                        <strong><field name="location_id" readonly="True"/></strong>.
                    </span>
                </div>
                <div invisible="not quant_ids">
                    <br/>
                    <strong>Current Inventory: </strong>
                    <field name="quant_ids" style="margin-top:10px;">
                        <tree>
                            <field name="location_id" options="{''no_create'': True}"/>
                            <field name="lot_id" groups="stock.group_production_lot"/>
                            <field name="quantity"/>
                        </tree>
                    </field>
                </div>
                <div name="description">
                </div>
                <footer>
                    <button name="cancel_button" string="Discard" class="btn-primary" special="cancel" data-hotkey="x"/>
                    <button string="Confirm" name="action_done" type="object" class="btn-secondary" data-hotkey="q"/>
                </footer>
            </form>
        ', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (996, 16, 995, 1, 1, 'stock.warn.insufficient.qty.scrap', 'stock.warn.insufficient.qty.scrap', NULL, 'form', 'stock/wizard/stock_warn_insufficient_qty_views.xml', 'primary', '{"en_US": "<data><xpath expr=\"//div[@name=''description'']\" position=\"inside\">\n                Do you confirm you want to scrap <strong><field name=\"quantity\" readonly=\"True\"/></strong><field name=\"product_uom_name\" readonly=\"True\" class=\"mx-1\"/>from location <strong><field name=\"location_id\" readonly=\"True\"/></strong>? This may lead to inconsistencies in your inventory.\n            </xpath>\n            <xpath expr=\"//button[@name=''cancel_button'']\" position=\"replace\">\n                <button string=\"Discard\" name=\"action_cancel\" type=\"object\" class=\"btn-primary\"/>\n            </xpath>\n        </data>"}', '<?xml version="1.0"?>
<data><xpath expr="//div[@name=''description'']" position="inside">
                Do you confirm you want to scrap <strong><field name="quantity" readonly="True"/></strong><field name="product_uom_name" readonly="True" class="mx-1"/>from location <strong><field name="location_id" readonly="True"/></strong>? This may lead to inconsistencies in your inventory.
            </xpath>
            <xpath expr="//button[@name=''cancel_button'']" position="replace">
                <button string="Discard" name="action_cancel" type="object" class="btn-primary"/>
            </xpath>
        </data>', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (997, 16, NULL, 1, 1, 'Replenish', 'product.replenish', NULL, 'form', 'stock/wizard/product_replenish_views.xml', 'primary', '{"en_US": "<form string=\"Replenish wizard\">\n                <p>\n                    The forecasted quantity of\n                    <field name=\"product_id\" domain=\"[(''product_tmpl_id'', ''='', product_tmpl_id)]\" readonly=\"not product_has_variants\" options=\"{''no_open'': 1, ''no_create'': 1}\" class=\"fw-bold\"/> is\n                    <field name=\"forecasted_quantity\"/>\n                    <field class=\"ps-1\" name=\"forecast_uom_id\" domain=\"[(''category_id'', ''='', product_uom_category_id)]\" groups=\"uom.group_uom\" readonly=\"1\"/>\n                    <field name=\"forecast_uom_id\" groups=\"!uom.group_uom\" invisible=\"1\"/>\n                </p>\n                <group>\n                    <group>\n                        <field name=\"product_tmpl_id\" invisible=\"1\"/>\n                        <field name=\"product_has_variants\" invisible=\"1\"/>\n                        <field name=\"product_uom_category_id\" invisible=\"1\"/>\n                        <field name=\"allowed_route_ids\" invisible=\"1\"/>\n                        <field name=\"company_id\" invisible=\"1\"/>\n                        <label for=\"quantity\"/>\n                        <div class=\"o_row\">\n                            <field name=\"quantity\"/>\n                            <field name=\"product_uom_id\" groups=\"!uom.group_uom\" invisible=\"1\"/>\n                            <field name=\"product_uom_id\" domain=\"[(''category_id'', ''='', product_uom_category_id)]\" groups=\"uom.group_uom\" options=\"{''no_open'': 1, ''no_create'': 1}\"/>\n                        </div>\n                        <field name=\"date_planned\" widget=\"date\"/>\n                        <field name=\"warehouse_id\" groups=\"stock.group_stock_multi_warehouses\"/>\n                        <field name=\"route_id\" domain=\"[(''id'', ''in'', allowed_route_ids)]\"/>\n                    </group>\n                </group>\n                <footer>\n                    <button name=\"launch_replenishment\" string=\"Confirm\" type=\"object\" data-hotkey=\"q\" class=\"btn-primary\"/>\n                    <button string=\"Discard\" class=\"btn-secondary\" special=\"cancel\" data-hotkey=\"x\"/>\n                </footer>\n            </form>"}', '<?xml version="1.0"?>
<form string="Replenish wizard">
                <p>
                    The forecasted quantity of
                    <field name="product_id" domain="[(''product_tmpl_id'', ''='', product_tmpl_id)]" readonly="not product_has_variants" options="{''no_open'': 1, ''no_create'': 1}" class="fw-bold"/> is
                    <field name="forecasted_quantity"/>
                    <field class="ps-1" name="forecast_uom_id" domain="[(''category_id'', ''='', product_uom_category_id)]" groups="uom.group_uom" readonly="1"/>
                    <field name="forecast_uom_id" groups="!uom.group_uom" invisible="1"/>
                </p>
                <group>
                    <group>
                        <field name="product_tmpl_id" invisible="1"/>
                        <field name="product_has_variants" invisible="1"/>
                        <field name="product_uom_category_id" invisible="1"/>
                        <field name="allowed_route_ids" invisible="1"/>
                        <field name="company_id" invisible="1"/>
                        <label for="quantity"/>
                        <div class="o_row">
                            <field name="quantity"/>
                            <field name="product_uom_id" groups="!uom.group_uom" invisible="1"/>
                            <field name="product_uom_id" domain="[(''category_id'', ''='', product_uom_category_id)]" groups="uom.group_uom" options="{''no_open'': 1, ''no_create'': 1}"/>
                        </div>
                        <field name="date_planned" widget="date"/>
                        <field name="warehouse_id" groups="stock.group_stock_multi_warehouses"/>
                        <field name="route_id" domain="[(''id'', ''in'', allowed_route_ids)]"/>
                    </group>
                </group>
                <footer>
                    <button name="launch_replenishment" string="Confirm" type="object" data-hotkey="q" class="btn-primary"/>
                    <button string="Discard" class="btn-secondary" special="cancel" data-hotkey="x"/>
                </footer>
            </form>
        ', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (998, 25, 450, 1, 1, 'product.label.layout.form', 'product.label.layout', NULL, 'form', 'stock/wizard/product_label_layout_views.xml', 'primary', '{"en_US": "<data><xpath expr=\"//field[@name=&quot;custom_quantity&quot;]\" position=\"before\">\n                <field name=\"move_quantity\"/>\n            </xpath>\n            <xpath expr=\"//field[@name=''custom_quantity'']\" position=\"attributes\">\n                <attribute name=\"invisible\">move_quantity == ''move''</attribute>\n            </xpath>\n        </data>"}', '<?xml version="1.0"?>
<data><xpath expr="//field[@name=&quot;custom_quantity&quot;]" position="before">
                <field name="move_quantity"/>
            </xpath>
            <xpath expr="//field[@name=''custom_quantity'']" position="attributes">
                <attribute name="invisible">move_quantity == ''move''</attribute>
            </xpath>
        </data>', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (999, 16, NULL, 1, 1, 'stock.track.confirmation.view.form', 'stock.track.confirmation', NULL, 'form', 'stock/wizard/stock_track_confirmation_views.xml', 'primary', '{"en_US": "<form string=\"Lots or serial numbers were not provided for tracked products\">\n                <field name=\"product_ids\" invisible=\"1\"/>\n                <field name=\"quant_ids\" invisible=\"1\"/>\n                <p>\n                    Those products you added are tracked but lots/serials were not defined. Once applied those can''t be changed.<br/>\n                    Apply anyway?\n                </p>\n                <strong>Tracked product(s):</strong>\n                <field name=\"tracking_line_ids\" readonly=\"1\">\n                    <tree>\n                        <field name=\"product_display_name\"/>\n                        <field name=\"tracking\"/>\n                    </tree>\n                </field>\n                <footer>\n                    <button name=\"action_confirm\" string=\"Apply\" type=\"object\" class=\"btn-primary\" data-hotkey=\"q\"/>\n                    <button string=\"Discard\" special=\"cancel\" data-hotkey=\"x\" class=\"btn-secondary\"/>\n                </footer>\n            </form>"}', '<?xml version="1.0"?>
<form string="Lots or serial numbers were not provided for tracked products">
                <field name="product_ids" invisible="1"/>
                <field name="quant_ids" invisible="1"/>
                <p>
                    Those products you added are tracked but lots/serials were not defined. Once applied those can''t be changed.<br/>
                    Apply anyway?
                </p>
                <strong>Tracked product(s):</strong>
                <field name="tracking_line_ids" readonly="1">
                    <tree>
                        <field name="product_display_name"/>
                        <field name="tracking"/>
                    </tree>
                </field>
                <footer>
                    <button name="action_confirm" string="Apply" type="object" class="btn-primary" data-hotkey="q"/>
                    <button string="Discard" special="cancel" data-hotkey="x" class="btn-secondary"/>
                </footer>
            </form>
        ', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (1000, 16, NULL, 1, 1, 'Stock Orderpoint Snooze', 'stock.orderpoint.snooze', NULL, 'form', 'stock/wizard/stock_orderpoint_snooze_views.xml', 'primary', '{"en_US": "<form string=\"Snooze\">\n                <group>\n                    <field name=\"orderpoint_ids\" invisible=\"1\"/>\n                    <field name=\"predefined_date\" widget=\"radio\"/>\n                    <field name=\"snoozed_until\" readonly=\"predefined_date != ''custom''\" force_save=\"1\"/>\n                </group>\n                <footer>\n                    <button string=\"Snooze\" name=\"action_snooze\" type=\"object\" class=\"btn-primary\" data-hotkey=\"q\"/>\n                    <button string=\"Discard\" name=\"cancel_button\" class=\"btn-secondary\" special=\"cancel\" data-hotkey=\"x\"/>\n                </footer>\n            </form>"}', '<?xml version="1.0"?>
<form string="Snooze">
                <group>
                    <field name="orderpoint_ids" invisible="1"/>
                    <field name="predefined_date" widget="radio"/>
                    <field name="snoozed_until" readonly="predefined_date != ''custom''" force_save="1"/>
                </group>
                <footer>
                    <button string="Snooze" name="action_snooze" type="object" class="btn-primary" data-hotkey="q"/>
                    <button string="Discard" name="cancel_button" class="btn-secondary" special="cancel" data-hotkey="x"/>
                </footer>
            </form>
        ', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (1001, 16, NULL, 1, 1, 'stock.package.destination.view', 'stock.package.destination', NULL, 'form', 'stock/wizard/stock_package_destination_views.xml', 'primary', '{"en_US": "<form>\n                <div>\n                    You are trying to put products going to different locations into the same package\n                </div>\n                <div>\n                    <field name=\"move_line_ids\" style=\"margin-top:10px;\">\n                        <tree>\n                            <field name=\"product_id\"/>\n                            <field name=\"location_dest_id\"/>\n                            <field name=\"quantity\" String=\"quantity\"/>\n                            <field name=\"lot_id\" groups=\"stock.group_production_lot\"/>\n                        </tree>\n                        <kanban>\n                            <field name=\"product_id\"/>\n                            <field name=\"quantity\"/>\n                            <field name=\"location_dest_id\"/>\n                            <templates>\n                                <t t-name=\"kanban-box\">\n                                    <div class=\"container o_kanban_card_content\">\n                                        <div class=\"row\">\n                                            <div class=\"col-6 o_kanban_primary_left\">\n                                                <field name=\"product_id\"/>\n                                            </div>\n                                            <div class=\"col-6 o_kanban_primary_right\">\n                                                <field name=\"quantity\" String=\"quantity\"/>\n                                            </div>\n                                        </div>\n                                        <div class=\"row\">\n                                            <div class=\"col-12\">\n                                                <field name=\"location_dest_id\"/>\n                                            </div>\n                                        </div>\n                                    </div>\n                                </t>\n                            </templates>\n                        </kanban>\n                    </field>\n                </div>\n                <div>\n                    <strong>Where do you want to send the products?</strong>\n                </div>\n                <div>\n                    <field name=\"filtered_location\" invisible=\"1\"/>\n                    <field name=\"location_dest_id\" domain=\"[(''id'', ''in'', filtered_location)]\" options=\"{''no_create'': True, ''no_open'': True}\"/>\n                </div>\n                <footer>\n                    <button string=\"Confirm\" name=\"action_done\" type=\"object\" class=\"btn-primary\" data-hotkey=\"q\"/>\n                    <button string=\"Discard\" name=\"cancel_button\" class=\"btn-secondary\" special=\"cancel\" data-hotkey=\"x\"/>\n                </footer>\n            </form>"}', '<?xml version="1.0"?>
<form>
                <div>
                    You are trying to put products going to different locations into the same package
                </div>
                <div>
                    <field name="move_line_ids" style="margin-top:10px;">
                        <tree>
                            <field name="product_id"/>
                            <field name="location_dest_id"/>
                            <field name="quantity" String="quantity"/>
                            <field name="lot_id" groups="stock.group_production_lot"/>
                        </tree>
                        <kanban>
                            <field name="product_id"/>
                            <field name="quantity"/>
                            <field name="location_dest_id"/>
                            <templates>
                                <t t-name="kanban-box">
                                    <div class="container o_kanban_card_content">
                                        <div class="row">
                                            <div class="col-6 o_kanban_primary_left">
                                                <field name="product_id"/>
                                            </div>
                                            <div class="col-6 o_kanban_primary_right">
                                                <field name="quantity" String="quantity"/>
                                            </div>
                                        </div>
                                        <div class="row">
                                            <div class="col-12">
                                                <field name="location_dest_id"/>
                                            </div>
                                        </div>
                                    </div>
                                </t>
                            </templates>
                        </kanban>
                    </field>
                </div>
                <div>
                    <strong>Where do you want to send the products?</strong>
                </div>
                <div>
                    <field name="filtered_location" invisible="1"/>
                    <field name="location_dest_id" domain="[(''id'', ''in'', filtered_location)]" options="{''no_create'': True, ''no_open'': True}"/>
                </div>
                <footer>
                    <button string="Confirm" name="action_done" type="object" class="btn-primary" data-hotkey="q"/>
                    <button string="Discard" name="cancel_button" class="btn-secondary" special="cancel" data-hotkey="x"/>
                </footer>
            </form>
        ', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (1002, 16, NULL, 1, 1, 'stock.inventory.adjustment.name.form.view', 'stock.inventory.adjustment.name', NULL, 'form', 'stock/wizard/stock_inventory_adjustment_name.xml', 'primary', '{"en_US": "<form>\n                <div>\n                    <group>\n                        <field name=\"inventory_adjustment_name\"/>\n                    </group>\n                </div>\n                <footer>\n                    <button name=\"action_apply\" string=\"Update Quantities\" type=\"object\" class=\"btn-primary\" data-hotkey=\"q\"/>\n                    <button name=\"cancel_button\" string=\"Discard\" class=\"btn-secondary\" special=\"cancel\" data-hotkey=\"x\"/>\n                </footer>\n            </form>"}', '<?xml version="1.0"?>
