INSERT INTO public.ir_ui_view VALUES (1005, 25, NULL, 1, 1, 'picking.label.type.form', 'picking.label.type', NULL, 'form', 'stock/wizard/stock_label_type.xml', 'primary', '{"en_US": "<form>\n                <group>\n                    <field name=\"label_type\" widget=\"radio\"/>\n                </group>\n                <footer>\n                    <button name=\"process\" string=\"Confirm\" type=\"object\" class=\"btn-primary\" data-hotkey=\"q\"/>\n                    <button string=\"Cancel\" class=\"btn-secondary\" special=\"cancel\" data-hotkey=\"x\"/>\n                </footer>\n            </form>"}', '<?xml version="1.0"?>
