INSERT INTO public.ir_ui_view VALUES (1006, 25, NULL, 1, 1, 'lot.label.layout.form', 'lot.label.layout', NULL, 'form', 'stock/wizard/stock_lot_label_layout.xml', 'primary', '{"en_US": "<form>\n                <group>\n                    <field name=\"label_quantity\" widget=\"radio\"/>\n                    <field name=\"print_format\" widget=\"radio\"/>\n                </group>\n                <footer>\n                    <button name=\"process\" string=\"Confirm\" type=\"object\" class=\"btn-primary\" data-hotkey=\"q\"/>\n                    <button string=\"Cancel\" class=\"btn-secondary\" special=\"cancel\" data-hotkey=\"x\"/>\n                </footer>\n            </form>"}', '<?xml version="1.0"?>
