        ', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (1009, 16, 125, 1, 1, 'res.partner.stock.warning', 'res.partner', NULL, 'form', 'stock/views/res_partner_views.xml', 'extension', '{"en_US": "<page name=\"internal_notes\" position=\"inside\">\n                <group groups=\"stock.group_warning_stock\">\n                    <group col=\"2\">\n                        <separator string=\"Warning on the Picking\" colspan=\"2\"/>\n                        <field name=\"picking_warn\" nolabel=\"1\" colspan=\"2\" required=\"1\"/>\n                        <field name=\"picking_warn_msg\" placeholder=\"Type a message...\" colspan=\"2\" nolabel=\"1\" invisible=\"picking_warn in (False, ''no-message'')\" required=\"picking_warn and picking_warn != ''no-message''\"/>\n                    </group>\n                </group>\n            </page>"}', '<?xml version="1.0"?>
<page name="internal_notes" position="inside">
                <group groups="stock.group_warning_stock">
                    <group col="2">
                        <separator string="Warning on the Picking" colspan="2"/>
                        <field name="picking_warn" nolabel="1" colspan="2" required="1"/>
                        <field name="picking_warn_msg" placeholder="Type a message..." colspan="2" nolabel="1" invisible="picking_warn in (False, ''no-message'')" required="picking_warn and picking_warn != ''no-message''"/>
                    </group>
                </group>
            </page>
        ', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (1010, 16, NULL, 1, 1, 'stock.putaway.rule.tree', 'stock.putaway.rule', NULL, 'tree', 'stock/views/product_strategy_views.xml', 'primary', '{"en_US": "<tree string=\"Putaway Rules\" editable=\"bottom\" sample=\"1\">\n                <field name=\"company_id\" column_invisible=\"True\"/>\n                <field name=\"package_type_ids\" column_invisible=\"True\"/>\n                <field name=\"sequence\" widget=\"handle\" column_invisible=\"context.get(''invisible_handle'', False)\"/>\n                <field name=\"location_in_id\" string=\"When product arrives in\" options=\"{''no_create'': True}\" readonly=\"context.get(''fixed_location'', False)\"/>\n                <field name=\"product_id\" string=\"Product\" options=\"{''no_create'': True, ''no_open'': True}\" readonly=\"context.get(''single_product'', False) or category_id\" required=\"not category_id and not package_type_ids\" force_save=\"1\"/>\n                <field name=\"category_id\" string=\"Product Category\" options=\"{''no_create'': True, ''no_open'': True}\" readonly=\"context.get(''fixed_category'', False) or product_id\" required=\"not product_id and not package_type_ids\" force_save=\"1\"/>\n                <field name=\"package_type_ids\" string=\"Package type\" options=\"{''no_create'': True, ''no_open'': True}\" groups=\"stock.group_tracking_lot\" widget=\"many2many_tags\" optional=\"show\"/>\n                <field name=\"location_out_id\" readonly=\"not location_in_id\" options=\"{''no_create'': True}\" optional=\"show\"/>\n                <field name=\"storage_category_id\" string=\"Having Category\" groups=\"stock.group_stock_storage_categories\" options=\"{''no_create'': True}\" optional=\"show\"/>\n                <field name=\"company_id\" groups=\"stock.group_stock_multi_locations\" force_save=\"1\" readonly=\"context.get(''fixed_location'', False)\" options=\"{''no_create'': True}\" optional=\"show\"/>\n            </tree>"}', '<?xml version="1.0"?>
<tree string="Putaway Rules" editable="bottom" sample="1">
                <field name="company_id" column_invisible="True"/>
                <field name="package_type_ids" column_invisible="True"/>
                <field name="sequence" widget="handle" column_invisible="context.get(''invisible_handle'', False)"/>
                <field name="location_in_id" string="When product arrives in" options="{''no_create'': True}" readonly="context.get(''fixed_location'', False)"/>
                <field name="product_id" string="Product" options="{''no_create'': True, ''no_open'': True}" readonly="context.get(''single_product'', False) or category_id" required="not category_id and not package_type_ids" force_save="1"/>
                <field name="category_id" string="Product Category" options="{''no_create'': True, ''no_open'': True}" readonly="context.get(''fixed_category'', False) or product_id" required="not product_id and not package_type_ids" force_save="1"/>
                <field name="package_type_ids" string="Package type" options="{''no_create'': True, ''no_open'': True}" groups="stock.group_tracking_lot" widget="many2many_tags" optional="show"/>
                <field name="location_out_id" readonly="not location_in_id" options="{''no_create'': True}" optional="show"/>
                <field name="storage_category_id" string="Having Category" groups="stock.group_stock_storage_categories" options="{''no_create'': True}" optional="show"/>
                <field name="company_id" groups="stock.group_stock_multi_locations" force_save="1" readonly="context.get(''fixed_location'', False)" options="{''no_create'': True}" optional="show"/>
            </tree>
        ', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (1011, 16, NULL, 1, 1, 'product.removal.form', 'product.removal', NULL, 'form', 'stock/views/product_strategy_views.xml', 'primary', '{"en_US": "<form string=\"Removal\">\n                <group col=\"4\">\n                    <field name=\"name\"/>\n                    <field name=\"method\"/>\n                </group>\n           </form>"}', '<?xml version="1.0"?>
