INSERT INTO public.ir_ui_view VALUES (1012, 16, NULL, 1, 1, 'stock.putaway.rule.search', 'stock.putaway.rule', NULL, 'search', 'stock/views/product_strategy_views.xml', 'primary', '{"en_US": "<search string=\"Putaway Rules\">\n                <field name=\"product_id\"/>\n                <field name=\"category_id\"/>\n                <field name=\"location_in_id\"/>\n                <field name=\"location_out_id\"/>\n                <group expand=\"0\" string=\"Filters\">\n                    <filter name=\"filter_to_rules_on_product\" string=\"Rules on Products\" domain=\"[(''product_id'', ''!='', False)]\"/>\n                    <filter name=\"filter_to_rules_on_category\" string=\"Rules on Categories\" domain=\"[(''category_id'' ,''!='', False)]\"/>\n                </group>\n                <group expand=\"0\" string=\"Group By\">\n                        <filter string=\"Location: When arrives to\" name=\"location_in\" context=\"{''group_by'':''location_in_id''}\"/>\n                        <filter string=\"Location: Store to\" name=\"location_out\" context=\"{''group_by'':''location_out_id''}\"/>\n                    </group>\n            </search>"}', '<?xml version="1.0"?>
<search string="Putaway Rules">
                <field name="product_id"/>
                <field name="category_id"/>
                <field name="location_in_id"/>
                <field name="location_out_id"/>
                <group expand="0" string="Filters">
                    <filter name="filter_to_rules_on_product" string="Rules on Products" domain="[(''product_id'', ''!='', False)]"/>
                    <filter name="filter_to_rules_on_category" string="Rules on Categories" domain="[(''category_id'' ,''!='', False)]"/>
                </group>
                <group expand="0" string="Group By">
                        <filter string="Location: When arrives to" name="location_in" context="{''group_by'':''location_in_id''}"/>
                        <filter string="Location: Store to" name="location_out" context="{''group_by'':''location_out_id''}"/>
                    </group>
            </search>
        ', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (1013, 10, NULL, 1, 1, 'stock.production.lot.form', 'stock.lot', NULL, 'form', 'stock/views/stock_lot_views.xml', 'primary', '{"en_US": "<form string=\"Lots/Serial Numbers\">\n                <sheet>\n                <field name=\"company_id\" invisible=\"1\"/>\n                <field name=\"display_complete\" invisible=\"1\"/>\n                <div class=\"oe_button_box\" name=\"button_box\" invisible=\"not display_complete\">\n                        <button class=\"oe_stat_button\" name=\"action_lot_open_transfers\" type=\"object\" icon=\"fa-truck\" help=\"Transfers\" invisible=\"delivery_count == 0\">\n                            <field name=\"delivery_count\" widget=\"statinfo\" string=\"Transfers\"/>\n                        </button>\n                        <button name=\"action_lot_open_quants\" icon=\"fa-arrows\" class=\"oe_stat_button\" type=\"object\">\n                            <div class=\"o_stat_info\">\n                                <span class=\"o_stat_text\">Location</span>\n                            </div>\n                        </button>\n                        <button name=\"336\" icon=\"oi-arrow-up\" class=\"oe_stat_button\" type=\"action\">\n                            <div class=\"o_stat_info\">\n                                <span class=\"o_stat_text\">Traceability</span>\n                            </div>\n                        </button>\n                </div>\n                <div class=\"oe_title\">\n                    <label for=\"name\"/>\n                    <h1>\n                        <field name=\"name\" placeholder=\"e.g. LOT/0001/20121\"/>\n                    </h1>\n                </div>\n                <group name=\"main_group\">\n                    <group>\n                        <field name=\"product_id\" context=\"{''default_detailed_type'': ''product'', ''default_tracking'': ''lot''}\" readonly=\"context.get(''set_product_readonly'', False)\" force_save=\"1\" help=\"Product this lot/serial number contains. You cannot change it anymore if it has already been moved.\"/>\n                        <label for=\"product_qty\" invisible=\"not display_complete\"/>\n                        <div class=\"o_row\" invisible=\"not display_complete\">\n                            <field name=\"product_qty\"/>\n                            <field name=\"product_uom_id\" groups=\"uom.group_uom\"/>\n                        </div>\n                        <field name=\"ref\"/>\n                        <field name=\"company_id\" groups=\"base.group_multi_company\"/>\n                        <field name=\"location_id\" invisible=\"not location_id\" groups=\"stock.group_stock_manager\"/>\n                        <field name=\"last_delivery_partner_id\" invisible=\"not last_delivery_partner_id\" groups=\"stock.group_stock_manager\"/>\n                    </group>\n                    <group/>\n                    <field name=\"lot_properties\" nolabel=\"1\" columns=\"2\" hideAddButton=\"1\"/>\n                </group>\n                <notebook invisible=\"not display_complete\">\n                    <page string=\"Description\" name=\"description\">\n                        <field name=\"note\"/>\n                    </page>\n                </notebook>\n                </sheet>\n                <div class=\"oe_chatter\">\n                    <field name=\"message_follower_ids\"/>\n                    <field name=\"activity_ids\"/>\n                    <field name=\"message_ids\"/>\n                </div>\n            </form>"}', '<?xml version="1.0"?>
<form string="Lots/Serial Numbers">
                <sheet>
                <field name="company_id" invisible="1"/>
                <field name="display_complete" invisible="1"/>
                <div class="oe_button_box" name="button_box" invisible="not display_complete">
                        <button class="oe_stat_button" name="action_lot_open_transfers" type="object" icon="fa-truck" help="Transfers" invisible="delivery_count == 0">
                            <field name="delivery_count" widget="statinfo" string="Transfers"/>
                        </button>
                        <button name="action_lot_open_quants" icon="fa-arrows" class="oe_stat_button" type="object">
                            <div class="o_stat_info">
                                <span class="o_stat_text">Location</span>
                            </div>
                        </button>
                        <button name="336" icon="oi-arrow-up" class="oe_stat_button" type="action">
                            <div class="o_stat_info">
                                <span class="o_stat_text">Traceability</span>
                            </div>
                        </button>
                </div>
                <div class="oe_title">
                    <label for="name"/>
                    <h1>
                        <field name="name" placeholder="e.g. LOT/0001/20121"/>
                    </h1>
                </div>
                <group name="main_group">
                    <group>
                        <field name="product_id" context="{''default_detailed_type'': ''product'', ''default_tracking'': ''lot''}" readonly="context.get(''set_product_readonly'', False)" force_save="1" help="Product this lot/serial number contains. You cannot change it anymore if it has already been moved."/>
                        <label for="product_qty" invisible="not display_complete"/>
                        <div class="o_row" invisible="not display_complete">
                            <field name="product_qty"/>
                            <field name="product_uom_id" groups="uom.group_uom"/>
                        </div>
                        <field name="ref"/>
                        <field name="company_id" groups="base.group_multi_company"/>
                        <field name="location_id" invisible="not location_id" groups="stock.group_stock_manager"/>
                        <field name="last_delivery_partner_id" invisible="not last_delivery_partner_id" groups="stock.group_stock_manager"/>
                    </group>
                    <group/>
                    <field name="lot_properties" nolabel="1" columns="2" hideAddButton="1"/>
                </group>
                <notebook invisible="not display_complete">
                    <page string="Description" name="description">
                        <field name="note"/>
                    </page>
                </notebook>
                </sheet>
                <div class="oe_chatter">
                    <field name="message_follower_ids"/>
                    <field name="activity_ids"/>
                    <field name="message_ids"/>
                </div>
            </form>
        ', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (1205, 16, NULL, 1, 1, 'report_purchaseorder', NULL, 'purchase.report_purchaseorder', 'qweb', 'purchase/report/purchase_order_templates.xml', 'primary', '{"en_US": "<t t-name=\"purchase.report_purchaseorder\">\n    <t t-call=\"web.html_container\">\n        <t t-foreach=\"docs\" t-as=\"o\">\n            <t t-call=\"purchase.report_purchaseorder_document\" t-lang=\"o.partner_id.lang\"/>\n        </t>\n    </t>\n</t>"}', '<?xml version="1.0"?>
<t t-name="purchase.report_purchaseorder">
    <t t-call="web.html_container">
        <t t-foreach="docs" t-as="o">
            <t t-call="purchase.report_purchaseorder_document" t-lang="o.partner_id.lang"/>
        </t>
    </t>
</t>

 ', false, true, '2026-05-10 01:12:29.662147', '2026-05-10 01:12:29.662147', false);
INSERT INTO public.ir_ui_view VALUES (1014, 16, NULL, 1, 1, 'stock.production.lot.tree', 'stock.lot', NULL, 'tree', 'stock/views/stock_lot_views.xml', 'primary', '{"en_US": "<tree string=\"Lots/Serial Numbers\" multi_edit=\"1\">\n                <field name=\"name\" decoration-bf=\"1\"/>\n                <field name=\"ref\" optional=\"show\"/>\n                <field name=\"product_id\" readonly=\"1\"/>\n                <field name=\"create_date\" optional=\"show\"/>\n                <field name=\"company_id\" groups=\"base.group_multi_company\"/>\n                <field name=\"last_delivery_partner_id\" optional=\"hide\" string=\"Transfer to\"/>\n                <field name=\"activity_ids\" widget=\"list_activity\" optional=\"show\"/>\n                <field name=\"lot_properties\" optional=\"hide\"/>\n                <field name=\"product_qty\" optional=\"hide\"/>\n            </tree>"}', '<?xml version="1.0"?>
<tree string="Lots/Serial Numbers" multi_edit="1">
                <field name="name" decoration-bf="1"/>
                <field name="ref" optional="show"/>
                <field name="product_id" readonly="1"/>
                <field name="create_date" optional="show"/>
                <field name="company_id" groups="base.group_multi_company"/>
                <field name="last_delivery_partner_id" optional="hide" string="Transfer to"/>
                <field name="activity_ids" widget="list_activity" optional="show"/>
                <field name="lot_properties" optional="hide"/>
                <field name="product_qty" optional="hide"/>
            </tree>
        ', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (1015, 16, NULL, 1, 1, 'stock.production.lot.kanban', 'stock.lot', NULL, 'kanban', 'stock/views/stock_lot_views.xml', 'primary', '{"en_US": "<kanban group_create=\"false\" group_delete=\"false\">\n                <field name=\"name\"/>\n                <field name=\"ref\"/>\n                <field name=\"product_id\"/>\n                <field name=\"create_date\"/>\n                <field name=\"company_id\" groups=\"base.group_multi_company\"/>\n                <field name=\"last_delivery_partner_id\"/>\n                <field name=\"lot_properties\"/>\n                <templates>\n                    <t t-name=\"kanban-box\">\n                        <div class=\"oe_kanban_global_click\">\n                            <div class=\"oe_kanban_details\">\n                                <strong class=\"o_kanban_record_title\">\n                                    <field name=\"name\"/>\n                                </strong>\n                                <div name=\"product_name\">\n                                    <small><field name=\"product_id\"/></small>\n                                </div>\n                                <div>\n                                    <field name=\"lot_properties\" widget=\"properties\"/>\n                                </div>\n                            </div>\n                            <field name=\"activity_ids\" widget=\"kanban_activity\"/>\n                        </div>\n                    </t>\n                </templates>\n            </kanban>"}', '<?xml version="1.0"?>
<kanban group_create="false" group_delete="false">
                <field name="name"/>
                <field name="ref"/>
                <field name="product_id"/>
                <field name="create_date"/>
                <field name="company_id" groups="base.group_multi_company"/>
                <field name="last_delivery_partner_id"/>
                <field name="lot_properties"/>
                <templates>
                    <t t-name="kanban-box">
                        <div class="oe_kanban_global_click">
                            <div class="oe_kanban_details">
                                <strong class="o_kanban_record_title">
                                    <field name="name"/>
                                </strong>
                                <div name="product_name">
                                    <small><field name="product_id"/></small>
                                </div>
                                <div>
                                    <field name="lot_properties" widget="properties"/>
                                </div>
                            </div>
                            <field name="activity_ids" widget="kanban_activity"/>
                        </div>
                    </t>
                </templates>
            </kanban>
        ', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (1016, 16, NULL, 1, 1, 'Production Lots Filter', 'stock.lot', NULL, 'search', 'stock/views/stock_lot_views.xml', 'primary', '{"en_US": "<search string=\"Product Lots Filter\">\n                <field name=\"name\" string=\"Lot/Serial Number\" filter_domain=\"[''|'', (''name'', ''ilike'', self),(''ref'', ''ilike'', self)]\"/>\n                <field name=\"product_id\"/>\n                <field name=\"lot_properties\"/>\n                <field name=\"create_date\"/>\n                <filter string=\"At Customer\" name=\"at_customer\" domain=\"[(''quant_ids.location_id.usage'',''='',''customer''), (''quant_ids.quantity'', ''&gt;'', 0)]\"/>\n                <filter string=\"On Hand\" name=\"on_hand\" domain=\"[(''product_qty'', ''&gt;'', 0)]\"/>\n                <filter string=\"Creation Date\" name=\"creation_date\" date=\"create_date\"/>\n                <group expand=\"0\" string=\"Group By\">\n                    <filter name=\"group_by_product\" string=\"Product\" domain=\"[]\" context=\"{''group_by'': ''product_id''}\"/>\n                    <filter name=\"group_by_location\" string=\"Location\" domain=\"[]\" context=\"{''group_by'': ''location_id''}\"/>\n                    <filter name=\"group_by_creation_date\" string=\"Creation date\" domain=\"[]\" context=\"{''group_by'': ''create_date''}\"/>\n                    <filter name=\"group_by_Company\" string=\"Company\" domain=\"[]\" context=\"{''group_by'': ''company_id''}\"/>\n                </group>\n            </search>"}', '<?xml version="1.0"?>
<search string="Product Lots Filter">
                <field name="name" string="Lot/Serial Number" filter_domain="[''|'', (''name'', ''ilike'', self),(''ref'', ''ilike'', self)]"/>
                <field name="product_id"/>
                <field name="lot_properties"/>
                <field name="create_date"/>
                <filter string="At Customer" name="at_customer" domain="[(''quant_ids.location_id.usage'',''='',''customer''), (''quant_ids.quantity'', ''&gt;'', 0)]"/>
                <filter string="On Hand" name="on_hand" domain="[(''product_qty'', ''&gt;'', 0)]"/>
                <filter string="Creation Date" name="creation_date" date="create_date"/>
                <group expand="0" string="Group By">
                    <filter name="group_by_product" string="Product" domain="[]" context="{''group_by'': ''product_id''}"/>
                    <filter name="group_by_location" string="Location" domain="[]" context="{''group_by'': ''location_id''}"/>
                    <filter name="group_by_creation_date" string="Creation date" domain="[]" context="{''group_by'': ''create_date''}"/>
                    <filter name="group_by_Company" string="Company" domain="[]" context="{''group_by'': ''company_id''}"/>
                </group>
            </search>
        ', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (1017, 16, NULL, 1, 1, 'stock.scrap.search', 'stock.scrap', NULL, 'search', 'stock/views/stock_scrap_views.xml', 'primary', '{"en_US": "<search string=\"Search Scrap\">\n                    <field name=\"name\" string=\"Reference\"/>\n                    <field name=\"product_id\"/>\n                    <field name=\"location_id\"/>\n                    <field name=\"scrap_location_id\"/>\n                    <field name=\"create_date\"/>\n                    <group expand=\"0\" string=\"Group By\">\n                        <filter string=\"Product\" name=\"product\" domain=\"[]\" context=\"{''group_by'':''product_id''}\"/>\n                        <filter string=\"Location\" name=\"location\" domain=\"[]\" context=\"{''group_by'':''location_id''}\"/>\n                        <filter string=\"Scrap Location\" name=\"scrap_location\" domain=\"[]\" context=\"{''group_by'':''scrap_location_id''}\"/>\n                        <filter string=\"Transfer\" name=\"transfer\" domain=\"[]\" context=\"{''group_by'':''picking_id''}\"/>\n                    </group>\n                </search>"}', '<?xml version="1.0"?>
<search string="Search Scrap">
                    <field name="name" string="Reference"/>
                    <field name="product_id"/>
                    <field name="location_id"/>
                    <field name="scrap_location_id"/>
                    <field name="create_date"/>
                    <group expand="0" string="Group By">
                        <filter string="Product" name="product" domain="[]" context="{''group_by'':''product_id''}"/>
                        <filter string="Location" name="location" domain="[]" context="{''group_by'':''location_id''}"/>
                        <filter string="Scrap Location" name="scrap_location" domain="[]" context="{''group_by'':''scrap_location_id''}"/>
                        <filter string="Transfer" name="transfer" domain="[]" context="{''group_by'':''picking_id''}"/>
                    </group>
                </search>
            ', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (1206, 16, 750, 1, 1, 'document_tax_totals', NULL, 'purchase.document_tax_totals', 'qweb', 'purchase/report/purchase_order_templates.xml', 'primary', '{"en_US": "<data inherit_id=\"account.document_tax_totals_template\" primary=\"True\"><xpath expr=\".\" position=\"attributes\"><attribute name=\"t-name\">purchase.document_tax_totals</attribute></xpath></data>"}', '<?xml version="1.0"?>
<data inherit_id="account.document_tax_totals_template" primary="True"><xpath expr="." position="attributes"><attribute name="t-name">purchase.document_tax_totals</attribute></xpath></data>

