INSERT INTO public.ir_ui_view VALUES (1018, 16, NULL, 1, 1, 'stock.scrap.form', 'stock.scrap', NULL, 'form', 'stock/views/stock_scrap_views.xml', 'primary', '{"en_US": "<form string=\"Scrap\">\n                    <header>\n                        <button name=\"action_validate\" invisible=\"state != ''draft''\" string=\"Validate\" type=\"object\" class=\"oe_highlight\" context=\"{''not_unlink_on_discard'': True}\" data-hotkey=\"v\"/>\n                        <field name=\"state\" widget=\"statusbar\" statusbar_visible=\"draft,done\"/>\n                    </header>\n                    <sheet>\n                        <div class=\"oe_button_box\" name=\"button_box\">\n                            <button class=\"oe_stat_button\" name=\"action_get_stock_picking\" string=\"Stock Operation\" type=\"object\" invisible=\"not picking_id\" icon=\"fa-cogs\"/>\n                            <field name=\"picking_id\" invisible=\"1\" readonly=\"state == ''done''\"/>\n                            <button class=\"oe_stat_button\" name=\"action_get_stock_move_lines\" type=\"object\" invisible=\"not move_ids\" icon=\"fa-exchange\">\n                                    <div class=\"o_stat_info\">\n                                        <span class=\"o_stat_text\">Product Moves</span>\n                                    </div>\n                            </button>\n                            <field name=\"move_ids\" invisible=\"1\"/>\n                        </div>\n                        <div class=\"oe_title\">\n                            <h1><field name=\"name\" nolabel=\"1\"/></h1>\n                        </div>\n                        <group>\n                            <group>\n                                <field name=\"product_id\" context=\"{''default_detailed_type'': ''product''}\" readonly=\"state == ''done''\"/>\n                                <field name=\"tracking\" invisible=\"1\"/>\n                                <label for=\"scrap_qty\"/>\n                                <div class=\"o_row\">\n                                    <field name=\"scrap_qty\" readonly=\"state == ''done'' or tracking == ''serial''\"/>\n                                    <field name=\"product_uom_category_id\" invisible=\"1\"/>\n                                    <field name=\"product_uom_id\" readonly=\"state == ''done'' or tracking == ''serial''\" groups=\"uom.group_uom\" force_save=\"1\"/>\n                                </div>\n                                <field name=\"lot_id\" context=\"{''default_product_id'': product_id, ''default_company_id'': company_id}\" invisible=\"not product_id or tracking == ''none''\" readonly=\"state == ''done''\" required=\"tracking != ''none''\" groups=\"stock.group_production_lot\"/>\n                            </group>\n                            <group>\n                                <field name=\"company_id\" invisible=\"1\" readonly=\"state == ''done''\"/>\n                                <field name=\"package_id\" groups=\"stock.group_tracking_lot\" readonly=\"state == ''done''\"/>\n                                <field name=\"owner_id\" groups=\"stock.group_tracking_owner\" readonly=\"state == ''done''\"/>\n                                <field name=\"location_id\" options=\"{''no_create'': True, ''no_open'': True}\" groups=\"stock.group_stock_multi_locations\" force_save=\"1\" readonly=\"state == ''done''\"/>\n                                <field name=\"scrap_location_id\" options=\"{''no_create'': True, ''no_open'': True}\" groups=\"stock.group_stock_multi_locations\" force_save=\"1\" readonly=\"state == ''done''\"/>\n                                <field name=\"origin\"/>\n                                <field name=\"date_done\" invisible=\"state == ''draft''\"/>\n                                <field name=\"picking_id\" invisible=\"not picking_id\" readonly=\"state == ''done''\"/>\n                                <field name=\"company_id\" groups=\"base.group_multi_company\" readonly=\"state == ''done''\"/>\n                                <field name=\"should_replenish\" readonly=\"state == ''done''\"/>\n                            </group>\n                        </group>\n                    </sheet>\n                    <div class=\"oe_chatter\">\n                        <field name=\"message_follower_ids\"/>\n                        <field name=\"message_ids\"/>\n                    </div>\n                </form>"}', '<?xml version="1.0"?>
<form string="Scrap">
                    <header>
                        <button name="action_validate" invisible="state != ''draft''" string="Validate" type="object" class="oe_highlight" context="{''not_unlink_on_discard'': True}" data-hotkey="v"/>
                        <field name="state" widget="statusbar" statusbar_visible="draft,done"/>
                    </header>
                    <sheet>
                        <div class="oe_button_box" name="button_box">
                            <button class="oe_stat_button" name="action_get_stock_picking" string="Stock Operation" type="object" invisible="not picking_id" icon="fa-cogs"/>
                            <field name="picking_id" invisible="1" readonly="state == ''done''"/>
                            <button class="oe_stat_button" name="action_get_stock_move_lines" type="object" invisible="not move_ids" icon="fa-exchange">
                                    <div class="o_stat_info">
                                        <span class="o_stat_text">Product Moves</span>
                                    </div>
                            </button>
                            <field name="move_ids" invisible="1"/>
                        </div>
                        <div class="oe_title">
                            <h1><field name="name" nolabel="1"/></h1>
                        </div>
                        <group>
                            <group>
                                <field name="product_id" context="{''default_detailed_type'': ''product''}" readonly="state == ''done''"/>
                                <field name="tracking" invisible="1"/>
                                <label for="scrap_qty"/>
                                <div class="o_row">
                                    <field name="scrap_qty" readonly="state == ''done'' or tracking == ''serial''"/>
                                    <field name="product_uom_category_id" invisible="1"/>
                                    <field name="product_uom_id" readonly="state == ''done'' or tracking == ''serial''" groups="uom.group_uom" force_save="1"/>
                                </div>
                                <field name="lot_id" context="{''default_product_id'': product_id, ''default_company_id'': company_id}" invisible="not product_id or tracking == ''none''" readonly="state == ''done''" required="tracking != ''none''" groups="stock.group_production_lot"/>
                            </group>
                            <group>
                                <field name="company_id" invisible="1" readonly="state == ''done''"/>
                                <field name="package_id" groups="stock.group_tracking_lot" readonly="state == ''done''"/>
                                <field name="owner_id" groups="stock.group_tracking_owner" readonly="state == ''done''"/>
                                <field name="location_id" options="{''no_create'': True, ''no_open'': True}" groups="stock.group_stock_multi_locations" force_save="1" readonly="state == ''done''"/>
                                <field name="scrap_location_id" options="{''no_create'': True, ''no_open'': True}" groups="stock.group_stock_multi_locations" force_save="1" readonly="state == ''done''"/>
                                <field name="origin"/>
                                <field name="date_done" invisible="state == ''draft''"/>
                                <field name="picking_id" invisible="not picking_id" readonly="state == ''done''"/>
                                <field name="company_id" groups="base.group_multi_company" readonly="state == ''done''"/>
                                <field name="should_replenish" readonly="state == ''done''"/>
                            </group>
                        </group>
                    </sheet>
                    <div class="oe_chatter">
                        <field name="message_follower_ids"/>
                        <field name="message_ids"/>
                    </div>
                </form>
            ', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (1019, 16, NULL, 1, 1, 'stock.scrap.kanban', 'stock.scrap', NULL, 'kanban', 'stock/views/stock_scrap_views.xml', 'primary', '{"en_US": "<kanban class=\"o_kanban_mobile\" sample=\"1\">\n                    <field name=\"name\"/>\n                    <field name=\"product_id\"/>\n                    <field name=\"date_done\"/>\n                    <field name=\"scrap_qty\"/>\n                    <field name=\"state\"/>\n                    <templates>\n                        <t t-name=\"kanban-box\">\n                            <div class=\"oe_kanban_global_click\">\n                                <div class=\"row mb4\">\n                                    <strong class=\"col-6\">\n                                        <span t-esc=\"record.name.value\"/>\n                                    </strong>\n                                    <strong t-if=\"record.date_done.value\" class=\"col-6 text-end\">\n                                        <i class=\"fa fa-clock-o\" role=\"img\" aria-label=\"Date\" title=\"Date\"/><span t-esc=\"record.date_done.value\"/>\n                                    </strong>\n                                    <div class=\"col-12\">\n                                        <span t-esc=\"record.product_id.value\"/>\n                                    </div>\n                                    <div class=\"col-6\">\n                                        <span t-esc=\"record.scrap_qty.value\"/>\n                                    </div>\n                                    <div class=\"col-6\">\n                                        <span class=\"float-end badge text-bg-secondary\">\n                                            <field name=\"state\"/>\n                                        </span>\n                                    </div>\n                                </div>\n                            </div>\n                        </t>\n                    </templates>\n                </kanban>"}', '<?xml version="1.0"?>
<kanban class="o_kanban_mobile" sample="1">
                    <field name="name"/>
                    <field name="product_id"/>
                    <field name="date_done"/>
                    <field name="scrap_qty"/>
                    <field name="state"/>
                    <templates>
                        <t t-name="kanban-box">
                            <div class="oe_kanban_global_click">
                                <div class="row mb4">
                                    <strong class="col-6">
                                        <span t-esc="record.name.value"/>
                                    </strong>
                                    <strong t-if="record.date_done.value" class="col-6 text-end">
                                        <i class="fa fa-clock-o" role="img" aria-label="Date" title="Date"/><span t-esc="record.date_done.value"/>
                                    </strong>
                                    <div class="col-12">
                                        <span t-esc="record.product_id.value"/>
                                    </div>
                                    <div class="col-6">
                                        <span t-esc="record.scrap_qty.value"/>
                                    </div>
                                    <div class="col-6">
                                        <span class="float-end badge text-bg-secondary">
                                            <field name="state"/>
                                        </span>
                                    </div>
                                </div>
                            </div>
                        </t>
                    </templates>
                </kanban>
            ', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (1020, 16, NULL, 1, 1, 'stock.scrap.tree', 'stock.scrap', NULL, 'tree', 'stock/views/stock_scrap_views.xml', 'primary', '{"en_US": "<tree multi_edit=\"1\" sample=\"1\" decoration-info=\"state == ''draft''\">\n                    <field name=\"company_id\" column_invisible=\"True\" readonly=\"state == ''done''\"/>\n                    <field name=\"product_uom_category_id\" column_invisible=\"True\"/>\n                    <field name=\"name\" decoration-bf=\"1\"/>\n                    <field name=\"date_done\"/>\n                    <field name=\"product_id\" readonly=\"1\"/>\n                    <field name=\"scrap_qty\" readonly=\"state == ''done''\"/>\n                    <field name=\"product_uom_id\" groups=\"uom.group_uom\" readonly=\"state == ''done''\"/>\n                    <field name=\"location_id\" options=\"{''no_create'': True}\" groups=\"stock.group_stock_multi_locations\" readonly=\"state == ''done''\"/>\n                    <field name=\"scrap_location_id\" options=\"{''no_create'': True}\" groups=\"stock.group_stock_multi_locations\" readonly=\"state == ''done''\"/>\n                    <field name=\"company_id\" readonly=\"1\" groups=\"base.group_multi_company\"/>\n                    <field name=\"state\" widget=\"badge\" decoration-success=\"state == ''done''\" decoration-muted=\"state == ''draft''\"/>\n                </tree>"}', '<?xml version="1.0"?>
<tree multi_edit="1" sample="1" decoration-info="state == ''draft''">
