INSERT INTO public.ir_ui_view VALUES (1021, 16, NULL, 1, 1, 'stock.scrap.form2', 'stock.scrap', NULL, 'form', 'stock/views/stock_scrap_views.xml', 'primary', '{"en_US": "<form string=\"Scrap\">\n                    <group>\n                        <group>\n                            <field name=\"state\" invisible=\"1\"/>\n                            <field name=\"product_id\" options=\"{''no_create'': True}\" domain=\"[(''id'', ''in'', context.get(''product_ids'', []))]\" readonly=\"state == ''done''\"/>\n                            <field name=\"tracking\" invisible=\"1\"/>\n                            <label for=\"scrap_qty\"/>\n                            <div class=\"o_row\">\n                                <field name=\"scrap_qty\" readonly=\"tracking == ''serial''\"/>\n                                <field name=\"product_uom_category_id\" invisible=\"1\"/>\n                                <field name=\"product_uom_id\" readonly=\"tracking == ''serial''\" groups=\"uom.group_uom\"/>\n                            </div>\n                            <field name=\"lot_id\" groups=\"stock.group_production_lot\" context=\"{''default_company_id'': company_id, ''default_product_id'': product_id}\" invisible=\"not product_id or tracking == ''none''\" readonly=\"state == ''done''\" required=\"tracking != ''none''\"/>\n                        </group>\n                        <group>\n                            <field name=\"picking_id\" invisible=\"1\" readonly=\"state == ''done''\"/>\n                            <field name=\"package_id\" groups=\"stock.group_tracking_lot\" readonly=\"state == ''done''\"/>\n                            <field name=\"owner_id\" groups=\"stock.group_tracking_owner\" readonly=\"state == ''done''\"/>\n                            <field name=\"company_id\" invisible=\"1\" readonly=\"state == ''done''\"/>\n                            <field name=\"location_id\" groups=\"stock.group_stock_multi_locations\" options=\"{''no_open'': True, ''no_create'': True}\" readonly=\"state == ''done''\"/>\n                            <field name=\"scrap_location_id\" groups=\"stock.group_stock_multi_locations\" options=\"{''no_open'': True, ''no_create'': True}\" readonly=\"state == ''done''\"/>\n                            <field name=\"should_replenish\" readonly=\"state == ''done''\"/>\n                        </group>\n                    </group>\n                    <footer>\n                        <button name=\"action_validate\" string=\"Scrap Products\" type=\"object\" class=\"btn-primary\" data-hotkey=\"q\"/>\n                        <button string=\"Discard\" class=\"btn-secondary\" special=\"cancel\" data-hotkey=\"x\"/>\n                    </footer>\n                </form>"}', '<?xml version="1.0"?>
<form string="Scrap">
                    <group>
                        <group>
                            <field name="state" invisible="1"/>
                            <field name="product_id" options="{''no_create'': True}" domain="[(''id'', ''in'', context.get(''product_ids'', []))]" readonly="state == ''done''"/>
                            <field name="tracking" invisible="1"/>
                            <label for="scrap_qty"/>
                            <div class="o_row">
                                <field name="scrap_qty" readonly="tracking == ''serial''"/>
                                <field name="product_uom_category_id" invisible="1"/>
                                <field name="product_uom_id" readonly="tracking == ''serial''" groups="uom.group_uom"/>
                            </div>
                            <field name="lot_id" groups="stock.group_production_lot" context="{''default_company_id'': company_id, ''default_product_id'': product_id}" invisible="not product_id or tracking == ''none''" readonly="state == ''done''" required="tracking != ''none''"/>
                        </group>
                        <group>
                            <field name="picking_id" invisible="1" readonly="state == ''done''"/>
                            <field name="package_id" groups="stock.group_tracking_lot" readonly="state == ''done''"/>
                            <field name="owner_id" groups="stock.group_tracking_owner" readonly="state == ''done''"/>
                            <field name="company_id" invisible="1" readonly="state == ''done''"/>
                            <field name="location_id" groups="stock.group_stock_multi_locations" options="{''no_open'': True, ''no_create'': True}" readonly="state == ''done''"/>
                            <field name="scrap_location_id" groups="stock.group_stock_multi_locations" options="{''no_open'': True, ''no_create'': True}" readonly="state == ''done''"/>
                            <field name="should_replenish" readonly="state == ''done''"/>
                        </group>
                    </group>
                    <footer>
                        <button name="action_validate" string="Scrap Products" type="object" class="btn-primary" data-hotkey="q"/>
                        <button string="Discard" class="btn-secondary" special="cancel" data-hotkey="x"/>
                    </footer>
                </form>
            ', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (1022, 10, NULL, 1, 1, 'stock.quant.search', 'stock.quant', NULL, 'search', 'stock/views/stock_quant_views.xml', 'primary', '{"en_US": "<search string=\"Quants\">\n                <field name=\"product_id\"/>\n                <field name=\"location_id\"/>\n                <field name=\"warehouse_id\"/>\n                <field name=\"storage_category_id\" groups=\"stock.group_stock_storage_categories\"/>\n                <field name=\"user_id\"/>\n                <field name=\"inventory_date\"/>\n                <field name=\"product_categ_id\"/>\n                <field name=\"product_tmpl_id\"/>\n                <field name=\"package_id\" groups=\"stock.group_tracking_lot\"/>\n                <field name=\"lot_id\" groups=\"stock.group_production_lot\"/>\n                <field name=\"owner_id\" groups=\"stock.group_tracking_owner\"/>\n                <field name=\"lot_properties\"/>\n                <group expand=\"0\" string=\"Filters\">\n                    <filter name=\"internal_loc\" string=\"Internal Locations\" domain=\"[(''location_id.usage'',''='', ''internal'')]\"/>\n                    <filter name=\"transit_loc\" string=\"Transit Locations\" domain=\"[(''location_id.usage'' ,''='', ''transit'')]\"/>\n                    <separator/>\n                    <filter name=\"on_hand\" string=\"On Hand\" domain=\"[(''on_hand'', ''='', True)]\"/>\n                    <filter name=\"to_count\" string=\"To Count\" domain=\"[(''inventory_date'', ''&lt;='', context_today().strftime(''%Y-%m-%d''))]\"/>\n                    <filter name=\"to_apply\" string=\"To Apply\" domain=\"[(''inventory_quantity_set'', ''='', True)]\"/>\n                    <filter name=\"priority_products\" string=\"Starred Products\" domain=\"[(''priority'', ''='', 1)]\"/>\n                    <separator/>\n                    <filter name=\"in_stock\" string=\"In Stock\" domain=\"[(''quantity'', ''&gt;'', 0.0)]\"/>\n                    <filter name=\"conflicts\" string=\"Conflicts\" domain=\"[(''is_outdated'', ''='', True)]\"/>\n                    <filter name=\"negative\" string=\"Negative Stock\" domain=\"[(''quantity'', ''&lt;'', 0.0)]\"/>\n                    <filter name=\"reserved\" string=\"Reservations\" domain=\"[(''reserved_quantity'', ''&gt;'', 0.0)]\"/>\n                    <separator/>\n                    <filter name=\"filter_in_date\" date=\"in_date\"/>\n                    <separator/>\n                    <filter name=\"my_count\" string=\"My Counts\" domain=\"[(''user_id'', ''='', uid)]\"/>\n                </group>\n                <group expand=\"0\" string=\"Group by...\">\n                    <filter string=\"Product\" name=\"productgroup\" context=\"{''group_by'': ''product_id''}\"/>\n                    <filter string=\"Location\" name=\"locationgroup\" domain=\"[]\" context=\"{''group_by'': ''location_id''}\"/>\n                    <filter string=\"Storage Category\" name=\"storagecategorygroup\" domain=\"[]\" context=\"{''group_by'': ''storage_category_id''}\"/>\n                    <filter string=\"Owner\" name=\"owner\" context=\"{''group_by'': ''owner_id''}\" groups=\"stock.group_tracking_owner\"/>\n                    <filter string=\"Lot/Serial Number\" name=\"Lot_Serial_number\" context=\"{''group_by'': ''lot_id''}\" groups=\"stock.group_production_lot\"/>\n                    <filter string=\"Package\" name=\"package\" domain=\"[]\" context=\"{''group_by'': ''package_id''}\" groups=\"stock.group_tracking_lot\"/>\n                    <filter string=\"Company\" name=\"company\" domain=\"[]\" context=\"{''group_by'': ''company_id''}\" groups=\"base.group_multi_company\"/>\n               </group>\n            </search>"}', '<?xml version="1.0"?>
<search string="Quants">
                <field name="product_id"/>
                <field name="location_id"/>
                <field name="warehouse_id"/>
                <field name="storage_category_id" groups="stock.group_stock_storage_categories"/>
                <field name="user_id"/>
                <field name="inventory_date"/>
                <field name="product_categ_id"/>
                <field name="product_tmpl_id"/>
                <field name="package_id" groups="stock.group_tracking_lot"/>
                <field name="lot_id" groups="stock.group_production_lot"/>
                <field name="owner_id" groups="stock.group_tracking_owner"/>
                <field name="lot_properties"/>
                <group expand="0" string="Filters">
                    <filter name="internal_loc" string="Internal Locations" domain="[(''location_id.usage'',''='', ''internal'')]"/>
                    <filter name="transit_loc" string="Transit Locations" domain="[(''location_id.usage'' ,''='', ''transit'')]"/>
                    <separator/>
                    <filter name="on_hand" string="On Hand" domain="[(''on_hand'', ''='', True)]"/>
                    <filter name="to_count" string="To Count" domain="[(''inventory_date'', ''&lt;='', context_today().strftime(''%Y-%m-%d''))]"/>
                    <filter name="to_apply" string="To Apply" domain="[(''inventory_quantity_set'', ''='', True)]"/>
                    <filter name="priority_products" string="Starred Products" domain="[(''priority'', ''='', 1)]"/>
                    <separator/>
                    <filter name="in_stock" string="In Stock" domain="[(''quantity'', ''&gt;'', 0.0)]"/>
                    <filter name="conflicts" string="Conflicts" domain="[(''is_outdated'', ''='', True)]"/>
                    <filter name="negative" string="Negative Stock" domain="[(''quantity'', ''&lt;'', 0.0)]"/>
                    <filter name="reserved" string="Reservations" domain="[(''reserved_quantity'', ''&gt;'', 0.0)]"/>
                    <separator/>
                    <filter name="filter_in_date" date="in_date"/>
                    <separator/>
                    <filter name="my_count" string="My Counts" domain="[(''user_id'', ''='', uid)]"/>
                </group>
                <group expand="0" string="Group by...">
                    <filter string="Product" name="productgroup" context="{''group_by'': ''product_id''}"/>
                    <filter string="Location" name="locationgroup" domain="[]" context="{''group_by'': ''location_id''}"/>
                    <filter string="Storage Category" name="storagecategorygroup" domain="[]" context="{''group_by'': ''storage_category_id''}"/>
                    <filter string="Owner" name="owner" context="{''group_by'': ''owner_id''}" groups="stock.group_tracking_owner"/>
                    <filter string="Lot/Serial Number" name="Lot_Serial_number" context="{''group_by'': ''lot_id''}" groups="stock.group_production_lot"/>
                    <filter string="Package" name="package" domain="[]" context="{''group_by'': ''package_id''}" groups="stock.group_tracking_lot"/>
                    <filter string="Company" name="company" domain="[]" context="{''group_by'': ''company_id''}" groups="base.group_multi_company"/>
               </group>
            </search>
        ', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
