INSERT INTO public.ir_ui_view VALUES (1023, 11, NULL, 1, 1, 'stock.quant.form.editable', 'stock.quant', NULL, 'form', 'stock/views/stock_quant_views.xml', 'primary', '{"en_US": "<form string=\"Inventory Valuation\" create=\"false\" edit=\"false\" delete=\"false\">\n                <sheet>\n                    <group>\n                        <group>\n                            <field name=\"tracking\" invisible=\"1\"/>\n                            <field name=\"company_id\" invisible=\"1\"/>\n                            <field name=\"product_id\" readonly=\"0\" options=\"{''no_create'': True}\"/>\n                            <field name=\"location_id\" readonly=\"0\" options=\"{''no_create'': True}\"/>\n                            <field name=\"lot_id\" groups=\"stock.group_production_lot\" readonly=\"tracking not in [''serial'', ''lot'']\" required=\"tracking != ''none''\" context=\"{''default_product_id'': product_id, ''default_company_id'': company_id}\"/>\n                            <field name=\"package_id\" readonly=\"0\" groups=\"stock.group_tracking_lot\"/>\n                            <field name=\"owner_id\" readonly=\"0\" groups=\"stock.group_tracking_owner\" options=\"{''no_create'': True}\"/>\n                            <field name=\"company_id\" groups=\"base.group_multi_company\"/>\n                        </group>\n                        <group>\n                            <label for=\"quantity\" string=\"Quantity On Hand\"/>\n                            <div class=\"o_row\">\n                                <field name=\"quantity\"/>\n                                <field name=\"product_uom_id\" groups=\"uom.group_uom\"/>\n                            </div>\n                            <label for=\"available_quantity\" string=\"Available Quantity\"/>\n                            <div class=\"o_row\">\n                                <field name=\"available_quantity\"/>\n                                <field name=\"product_uom_id\" groups=\"uom.group_uom\"/>\n                            </div>\n                            <label for=\"reserved_quantity\" string=\"Quantity Reserved\"/>\n                            <div class=\"o_row\">\n                                <field name=\"reserved_quantity\"/>\n                                <field name=\"product_uom_id\" groups=\"uom.group_uom\"/>\n                            </div>\n                        </group>\n                    </group>\n                </sheet>\n            </form>"}', '<?xml version="1.0"?>
<form string="Inventory Valuation" create="false" edit="false" delete="false">
                <sheet>
                    <group>
                        <group>
                            <field name="tracking" invisible="1"/>
                            <field name="company_id" invisible="1"/>
