                            <field name="lot_id" groups="stock.group_production_lot" readonly="tracking not in [''serial'', ''lot'']" required="tracking != ''none''" context="{''default_product_id'': product_id, ''default_company_id'': company_id}"/>
                            <field name="package_id" readonly="0" groups="stock.group_tracking_lot"/>
