INSERT INTO public.ir_ui_view VALUES (1024, 5, NULL, 1, 1, 'stock.quant.tree.editable', 'stock.quant', NULL, 'tree', 'stock/views/stock_quant_views.xml', 'primary', '{"en_US": "<tree editable=\"bottom\" create=\"1\" edit=\"1\" js_class=\"inventory_report_list\" sample=\"1\" duplicate=\"0\">\n                <header>\n                    <button name=\"action_inventory_at_date\" string=\"Inventory at Date\" type=\"object\" invisible=\"((context.get(''inventory_mode'') and not context.get(''inventory_report_mode'')) or context.get(''no_at_date''))\" class=\"btn-primary ms-1\" display=\"always\"/>\n                    <button name=\"action_stock_quant_relocate\" string=\"Relocate\" type=\"object\" groups=\"stock.group_stock_manager\" invisible=\"context.get(''hide_location'', False)\" context=\"{''action_ref'': ''stock.action_view_quants''}\"/>\n                </header>\n                <field name=\"create_date\" column_invisible=\"True\"/>\n                <field name=\"write_date\" column_invisible=\"True\"/>\n                <field name=\"id\" column_invisible=\"True\"/>\n                <field name=\"tracking\" column_invisible=\"True\"/>\n                <field name=\"company_id\" column_invisible=\"True\"/>\n                <field name=\"location_id\" column_invisible=\"context.get(''hide_location'', False)\" readonly=\"id\" options=\"{''no_create'': True}\"/>\n                <field name=\"storage_category_id\" optional=\"hide\"/>\n                <field name=\"product_id\" readonly=\"context.get(''single_product'', False) or id\" force_save=\"1\" options=\"{''no_create'': True}\" widget=\"many2one\"/>\n                <field name=\"product_categ_id\" optional=\"hide\"/>\n                <field name=\"company_id\" groups=\"base.group_multi_company\" optional=\"hidden\"/>\n                <field name=\"package_id\" groups=\"stock.group_tracking_lot\" readonly=\"id\"/>\n                <field name=\"lot_id\" groups=\"stock.group_production_lot\" column_invisible=\"context.get(''hide_lot'', False)\" readonly=\"id or tracking not in [''serial'', ''lot'']\" context=\"{''default_product_id'': product_id, ''default_company_id'': company_id}\"/>\n                <field name=\"owner_id\" groups=\"stock.group_tracking_owner\" readonly=\"id\" options=\"{''no_create'': True}\"/>\n                <field name=\"inventory_quantity_auto_apply\" string=\"On Hand Quantity\" readonly=\"0\" sum=\"Total On Hand\"/>\n                <button name=\"372\" title=\"Inventory Adjustment\" type=\"action\" class=\"btn-link\" icon=\"fa-pencil\" context=\"{''search_default_product_id'': product_id, ''default_product_id'': product_id}\"/>\n                <field name=\"reserved_quantity\" optional=\"show\" sum=\"Total Reserved\"/>\n                <field name=\"product_uom_id\" string=\"Unit\" groups=\"uom.group_uom\"/>\n                <field name=\"lot_properties\" optional=\"hide\"/>\n                <button name=\"action_view_stock_moves\" string=\"History\" type=\"object\" class=\"btn-link\" icon=\"fa-history\"/>\n                <button name=\"action_view_orderpoints\" string=\"Replenishment\" type=\"object\" context=\"{''default_product_id'': product_id, ''search_default_location_id'': location_id}\" class=\"btn-link\" icon=\"fa-refresh\"/>\n            </tree>"}', '<?xml version="1.0"?>
<tree editable="bottom" create="1" edit="1" js_class="inventory_report_list" sample="1" duplicate="0">
                <header>
                    <button name="action_inventory_at_date" string="Inventory at Date" type="object" invisible="((context.get(''inventory_mode'') and not context.get(''inventory_report_mode'')) or context.get(''no_at_date''))" class="btn-primary ms-1" display="always"/>
                    <button name="action_stock_quant_relocate" string="Relocate" type="object" groups="stock.group_stock_manager" invisible="context.get(''hide_location'', False)" context="{''action_ref'': ''stock.action_view_quants''}"/>
                </header>
                <field name="create_date" column_invisible="True"/>
                <field name="write_date" column_invisible="True"/>
                <field name="id" column_invisible="True"/>
                <field name="tracking" column_invisible="True"/>
                <field name="company_id" column_invisible="True"/>
                <field name="location_id" column_invisible="context.get(''hide_location'', False)" readonly="id" options="{''no_create'': True}"/>
                <field name="storage_category_id" optional="hide"/>
                <field name="product_id" readonly="context.get(''single_product'', False) or id" force_save="1" options="{''no_create'': True}" widget="many2one"/>
                <field name="product_categ_id" optional="hide"/>
                <field name="company_id" groups="base.group_multi_company" optional="hidden"/>
                <field name="package_id" groups="stock.group_tracking_lot" readonly="id"/>
                <field name="lot_id" groups="stock.group_production_lot" column_invisible="context.get(''hide_lot'', False)" readonly="id or tracking not in [''serial'', ''lot'']" context="{''default_product_id'': product_id, ''default_company_id'': company_id}"/>
                <field name="owner_id" groups="stock.group_tracking_owner" readonly="id" options="{''no_create'': True}"/>
                <field name="inventory_quantity_auto_apply" string="On Hand Quantity" readonly="0" sum="Total On Hand"/>
                <button name="372" title="Inventory Adjustment" type="action" class="btn-link" icon="fa-pencil" context="{''search_default_product_id'': product_id, ''default_product_id'': product_id}"/>
                <field name="reserved_quantity" optional="show" sum="Total Reserved"/>
                <field name="product_uom_id" string="Unit" groups="uom.group_uom"/>
                <field name="lot_properties" optional="hide"/>
                <button name="action_view_stock_moves" string="History" type="object" class="btn-link" icon="fa-history"/>
                <button name="action_view_orderpoints" string="Replenishment" type="object" context="{''default_product_id'': product_id, ''search_default_location_id'': location_id}" class="btn-link" icon="fa-refresh"/>
            </tree>
        ', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
