INSERT INTO public.ir_ui_view VALUES (1030, 10, NULL, 1, 1, 'stock.quant.package.form', 'stock.quant.package', NULL, 'form', 'stock/views/stock_quant_views.xml', 'primary', '{"en_US": "<form string=\"Package\">\n                <header>\n                    <button name=\"unpack\" string=\"Unpack\" type=\"object\"/>\n                </header>\n                <sheet>\n                    <div class=\"oe_button_box\" name=\"button_box\">\n                        <button class=\"oe_stat_button\" name=\"action_view_picking\" string=\"Package Transfers\" type=\"object\" widget=\"statinfo\" icon=\"oi-arrows-v\"/>\n                    </div>\n                    <div class=\"oe_title\">\n                        <label for=\"name\" string=\"Package Reference\"/>\n                        <h1><field name=\"name\" class=\"oe_inline\" placeholder=\"e.g. PACK0000007\"/></h1>\n                    </div>\n                    <group>\n                        <group>\n                            <field name=\"package_type_id\"/>\n                            <field name=\"company_id\" groups=\"base.group_multi_company\"/>\n                            <field name=\"owner_id\" groups=\"stock.group_tracking_owner\"/>\n                            <field name=\"location_id\" options=\"{''no_create'': True}\"/>\n                        </group>\n                        <group>\n                            <field name=\"pack_date\"/>\n                        </group>\n                    </group>\n                    <separator string=\"Content\"/>\n                    <field name=\"quant_ids\">\n                        <tree>\n                            <field name=\"product_id\"/>\n                            <field name=\"lot_id\" groups=\"stock.group_production_lot\"/>\n                            <field name=\"quantity\"/>\n                            <field name=\"product_uom_id\" groups=\"uom.group_uom\"/>\n                        </tree>\n                    </field>\n                </sheet>\n            </form>"}', '<?xml version="1.0"?>
<form string="Package">
                <header>
                    <button name="unpack" string="Unpack" type="object"/>
                </header>
                <sheet>
                    <div class="oe_button_box" name="button_box">
                        <button class="oe_stat_button" name="action_view_picking" string="Package Transfers" type="object" widget="statinfo" icon="oi-arrows-v"/>
                    </div>
                    <div class="oe_title">
                        <label for="name" string="Package Reference"/>
                        <h1><field name="name" class="oe_inline" placeholder="e.g. PACK0000007"/></h1>
                    </div>
                    <group>
                        <group>
                            <field name="package_type_id"/>
                            <field name="company_id" groups="base.group_multi_company"/>
                            <field name="owner_id" groups="stock.group_tracking_owner"/>
                            <field name="location_id" options="{''no_create'': True}"/>
                        </group>
                        <group>
                            <field name="pack_date"/>
                        </group>
                    </group>
                    <separator string="Content"/>
                    <field name="quant_ids">
                        <tree>
                            <field name="product_id"/>
                            <field name="lot_id" groups="stock.group_production_lot"/>
                            <field name="quantity"/>
                            <field name="product_uom_id" groups="uom.group_uom"/>
                        </tree>
                    </field>
                </sheet>
            </form>
        ', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
