INSERT INTO public.ir_ui_view VALUES (1032, 16, NULL, 1, 1, 'stock.quant.package.kanban', 'stock.quant.package', NULL, 'kanban', 'stock/views/stock_quant_views.xml', 'primary', '{"en_US": "<kanban sample=\"1\">\n                <templates>\n                <field name=\"name\"/>\n                    <t t-name=\"kanban-box\">\n                        <div class=\"oe_kanban_global_click\">\n                            <div class=\"o_kanban_record_top mb0\">\n                                <div class=\"col-6\">\n                                    <strong class=\"o_kanban_record_title\"><field name=\"name\"/></strong>\n                                </div>\n                                <div class=\"col-6\">\n                                    <field name=\"package_type_id\"/>\n                                </div>\n                            </div>\n                        </div>\n                    </t>\n                </templates>\n            </kanban>"}', '<?xml version="1.0"?>
