INSERT INTO public.ir_ui_view VALUES (1034, 100, NULL, 1, 1, 'view.stock.quant.form', 'stock.quant', NULL, 'form', 'stock/views/stock_quant_views.xml', 'primary', '{"en_US": "<form string=\"Create Stock\">\n                <div class=\"alert alert-warning\" role=\"alert\" invisible=\"context.get(''readonly_form'')\">\n                You are going to pick products that are not referenced\nin this location. That leads to a negative stock.\n                </div>\n                <group>\n                    <group>\n                        <field name=\"location_id\" invisible=\"1\"/>\n                        <field name=\"company_id\" invisible=\"1\"/>\n                        <field name=\"product_id\" invisible=\"1\"/>\n                        <field name=\"product_id\" force_save=\"1\" invisible=\"1\"/>\n                        <field name=\"lot_id\" domain=\"[(''product_id'', ''='', product_id)]\" groups=\"stock.group_production_lot\" readonly=\"context.get(''readonly_form'')\" context=\"{''default_product_id'': product_id, ''default_company_id'': company_id, ''active_picking_id'': context.get(''active_picking_id'')}\"/>\n                        <field name=\"location_id\" groups=\"stock.group_stock_multi_locations\" readonly=\"context.get(''readonly_form'')\"/>\n                        <field name=\"package_id\" groups=\"stock.group_tracking_lot\" invisible=\"context.get(''readonly_form'')\"/>\n                        <field name=\"owner_id\" groups=\"stock.group_tracking_owner\" invisible=\"context.get(''readonly_form'')\"/>\n                    </group>\n                </group>\n            </form>"}', '<?xml version="1.0"?>
<form string="Create Stock">
                <div class="alert alert-warning" role="alert" invisible="context.get(''readonly_form'')">
                You are going to pick products that are not referenced
in this location. That leads to a negative stock.
                </div>
                <group>
                    <group>
                        <field name="location_id" invisible="1"/>
                        <field name="company_id" invisible="1"/>
                        <field name="product_id" invisible="1"/>
                        <field name="product_id" force_save="1" invisible="1"/>
                        <field name="lot_id" domain="[(''product_id'', ''='', product_id)]" groups="stock.group_production_lot" readonly="context.get(''readonly_form'')" context="{''default_product_id'': product_id, ''default_company_id'': company_id, ''active_picking_id'': context.get(''active_picking_id'')}"/>
                        <field name="location_id" groups="stock.group_stock_multi_locations" readonly="context.get(''readonly_form'')"/>
                        <field name="package_id" groups="stock.group_tracking_lot" invisible="context.get(''readonly_form'')"/>
                        <field name="owner_id" groups="stock.group_tracking_owner" invisible="context.get(''readonly_form'')"/>
                    </group>
                </group>
            </form>
        ', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (1056, 16, NULL, 1, 1, 'stock.move.pivot', 'stock.move', NULL, 'pivot', 'stock/views/stock_move_views.xml', 'primary', '{"en_US": "<pivot string=\"Stock Moves Analysis\" sample=\"1\">\n                    <field name=\"location_dest_id\" groups=\"stock.group_stock_multi_locations\" type=\"row\"/>\n                    <field name=\"picking_type_id\" type=\"col\"/>\n                    <field name=\"date\" interval=\"month\" type=\"row\"/>\n                </pivot>"}', '<?xml version="1.0"?>
