INSERT INTO public.ir_ui_view VALUES (1035, 10, NULL, 1, 1, 'stock.quant.inventory.tree.editable', 'stock.quant', NULL, 'tree', 'stock/views/stock_quant_views.xml', 'primary', '{"en_US": "<tree default_order=\"location_id, inventory_date, product_id, package_id, lot_id, owner_id\" decoration-warning=\"is_outdated\" editable=\"bottom\" create=\"1\" edit=\"1\" import=\"1\" js_class=\"inventory_report_list\" sample=\"1\">\n                <header>\n                    <button name=\"action_inventory_at_date\" string=\"Inventory at Date\" type=\"object\" invisible=\"((context.get(''inventory_mode'') and not context.get(''inventory_report_mode'')) or context.get(''no_at_date''))\" class=\"btn-primary ms-1\" display=\"always\"/>\n                    <button name=\"stock.action_stock_inventory_adjustement_name\" groups=\"stock.group_stock_manager\" type=\"action\" string=\"Apply\"/>\n                    <button name=\"action_reset\" type=\"object\" string=\"Clear\" groups=\"stock.group_stock_manager\"/>\n                    <button name=\"stock.action_stock_request_count\" groups=\"stock.group_stock_manager\" type=\"action\" string=\"Request a Count\"/>\n                    <button name=\"action_stock_quant_relocate\" string=\"Relocate\" type=\"object\" groups=\"stock.group_stock_manager\" invisible=\"context.get(''hide_location'', False)\" context=\"{''action_ref'': ''stock.action_view_inventory_tree''}\"/>\n                </header>\n                <field name=\"create_date\" column_invisible=\"True\"/>\n                <field name=\"write_date\" column_invisible=\"True\"/>\n                <field name=\"id\" column_invisible=\"True\"/>\n                <field name=\"is_outdated\" column_invisible=\"True\"/>\n                <field name=\"sn_duplicated\" column_invisible=\"True\"/>\n                <field name=\"tracking\" column_invisible=\"True\"/>\n                <field name=\"inventory_quantity_set\" column_invisible=\"True\"/>\n                <field name=\"company_id\" column_invisible=\"True\"/>\n                <field name=\"location_id\" domain=\"[(''usage'', ''in'', [''internal'', ''transit''])]\" column_invisible=\"context.get(''hide_location'', False)\" readonly=\"id\" options=\"{''no_create'': True}\"/>\n                <field name=\"storage_category_id\" groups=\"stock.group_stock_storage_categories\" column_invisible=\"context.get(''hide_location'', False)\" options=\"{''no_create'': True}\" optional=\"hidden\"/>\n                <field name=\"cyclic_inventory_frequency\" column_invisible=\"context.get(''hide_location'', False)\" options=\"{''no_create'': True}\" optional=\"hidden\"/>\n                <field name=\"priority\" widget=\"priority\" nolabel=\"1\" optional=\"hidden\"/>\n                <field name=\"product_id\" readonly=\"context.get(''single_product'', False) or id\" force_save=\"1\" options=\"{''no_create'': True}\"/>\n                <field name=\"product_categ_id\" optional=\"hide\"/>\n                <button name=\"action_warning_duplicated_sn\" type=\"object\" invisible=\"not sn_duplicated\" title=\"This lot/serial number is already in another location\" class=\"btn btn-secondary text-warning float-end\" icon=\"fa-warning\"/>\n                <field name=\"lot_id\" groups=\"stock.group_production_lot\" column_invisible=\"context.get(''hide_lot'', False)\" readonly=\"tracking not in [''serial'', ''lot''] or (id and (lot_id or quantity != 0))\" context=\"{''default_product_id'': product_id, ''default_company_id'': company_id}\" decoration-warning=\"sn_duplicated\" force_save=\"1\"/>\n                <field name=\"package_id\" groups=\"stock.group_tracking_lot\" readonly=\"id\"/>\n                <field name=\"owner_id\" groups=\"stock.group_tracking_owner\" readonly=\"id\" options=\"{''no_create'': True}\"/>\n                <field name=\"last_count_date\" optional=\"hidden\" readonly=\"1\"/>\n                <field name=\"available_quantity\" string=\"Available Quantity\" decoration-danger=\"available_quantity &lt; 0\" optional=\"hidden\"/>\n                <field name=\"quantity\" optional=\"show\" decoration-warning=\"quantity &lt; 0\" string=\"On Hand Quantity\"/>\n                <field name=\"product_uom_id\" groups=\"uom.group_uom\" string=\"UoM\"/>\n                <field name=\"inventory_quantity\" widget=\"counted_quantity_widget\"/>\n                <field name=\"inventory_diff_quantity\" string=\"Difference\" invisible=\"not inventory_quantity_set\" decoration-muted=\"inventory_diff_quantity == 0\" decoration-danger=\"inventory_diff_quantity &lt; 0\" decoration-success=\"inventory_diff_quantity &gt; 0\" decoration-bf=\"inventory_diff_quantity != 0\"/>\n                <field name=\"inventory_date\" optional=\"show\"/>\n                <field name=\"user_id\" string=\"User\" optional=\"show\"/>\n                <field name=\"company_id\" groups=\"base.group_multi_company\" optional=\"hide\"/>\n                <field name=\"lot_properties\" optional=\"hide\"/>\n                <button name=\"action_inventory_history\" type=\"object\" class=\"btn btn-link text-info\" icon=\"fa-history\" string=\"History\"/>\n                <button name=\"action_apply_inventory\" groups=\"stock.group_stock_manager\" type=\"object\" string=\"Apply\" class=\"btn btn-link\" icon=\"fa-save\" invisible=\"not inventory_quantity_set\"/>\n                <button name=\"action_set_inventory_quantity\" type=\"object\" string=\"Set\" class=\"btn btn-link\" icon=\"fa-bullseye\" invisible=\"inventory_quantity_set\"/>\n                <button name=\"action_clear_inventory_quantity\" type=\"object\" string=\"Clear\" class=\"btn text-warning\" icon=\"fa-times\" invisible=\"not inventory_quantity_set\"/>\n            </tree>"}', '<?xml version="1.0"?>
<tree default_order="location_id, inventory_date, product_id, package_id, lot_id, owner_id" decoration-warning="is_outdated" editable="bottom" create="1" edit="1" import="1" js_class="inventory_report_list" sample="1">
                <header>
                    <button name="action_inventory_at_date" string="Inventory at Date" type="object" invisible="((context.get(''inventory_mode'') and not context.get(''inventory_report_mode'')) or context.get(''no_at_date''))" class="btn-primary ms-1" display="always"/>
                    <button name="stock.action_stock_inventory_adjustement_name" groups="stock.group_stock_manager" type="action" string="Apply"/>
                    <button name="action_reset" type="object" string="Clear" groups="stock.group_stock_manager"/>
                    <button name="stock.action_stock_request_count" groups="stock.group_stock_manager" type="action" string="Request a Count"/>
                    <button name="action_stock_quant_relocate" string="Relocate" type="object" groups="stock.group_stock_manager" invisible="context.get(''hide_location'', False)" context="{''action_ref'': ''stock.action_view_inventory_tree''}"/>
                </header>
                <field name="create_date" column_invisible="True"/>
                <field name="write_date" column_invisible="True"/>
                <field name="id" column_invisible="True"/>
                <field name="is_outdated" column_invisible="True"/>
                <field name="sn_duplicated" column_invisible="True"/>
                <field name="tracking" column_invisible="True"/>
                <field name="inventory_quantity_set" column_invisible="True"/>
                <field name="company_id" column_invisible="True"/>
                <field name="location_id" domain="[(''usage'', ''in'', [''internal'', ''transit''])]" column_invisible="context.get(''hide_location'', False)" readonly="id" options="{''no_create'': True}"/>
                <field name="storage_category_id" groups="stock.group_stock_storage_categories" column_invisible="context.get(''hide_location'', False)" options="{''no_create'': True}" optional="hidden"/>
                <field name="cyclic_inventory_frequency" column_invisible="context.get(''hide_location'', False)" options="{''no_create'': True}" optional="hidden"/>
                <field name="priority" widget="priority" nolabel="1" optional="hidden"/>
                <field name="product_id" readonly="context.get(''single_product'', False) or id" force_save="1" options="{''no_create'': True}"/>
                <field name="product_categ_id" optional="hide"/>
                <button name="action_warning_duplicated_sn" type="object" invisible="not sn_duplicated" title="This lot/serial number is already in another location" class="btn btn-secondary text-warning float-end" icon="fa-warning"/>
                <field name="lot_id" groups="stock.group_production_lot" column_invisible="context.get(''hide_lot'', False)" readonly="tracking not in [''serial'', ''lot''] or (id and (lot_id or quantity != 0))" context="{''default_product_id'': product_id, ''default_company_id'': company_id}" decoration-warning="sn_duplicated" force_save="1"/>
                <field name="package_id" groups="stock.group_tracking_lot" readonly="id"/>
                <field name="owner_id" groups="stock.group_tracking_owner" readonly="id" options="{''no_create'': True}"/>
                <field name="last_count_date" optional="hidden" readonly="1"/>
                <field name="available_quantity" string="Available Quantity" decoration-danger="available_quantity &lt; 0" optional="hidden"/>
                <field name="quantity" optional="show" decoration-warning="quantity &lt; 0" string="On Hand Quantity"/>
                <field name="product_uom_id" groups="uom.group_uom" string="UoM"/>
                <field name="inventory_quantity" widget="counted_quantity_widget"/>
                <field name="inventory_diff_quantity" string="Difference" invisible="not inventory_quantity_set" decoration-muted="inventory_diff_quantity == 0" decoration-danger="inventory_diff_quantity &lt; 0" decoration-success="inventory_diff_quantity &gt; 0" decoration-bf="inventory_diff_quantity != 0"/>
                <field name="inventory_date" optional="show"/>
                <field name="user_id" string="User" optional="show"/>
                <field name="company_id" groups="base.group_multi_company" optional="hide"/>
                <field name="lot_properties" optional="hide"/>
                <button name="action_inventory_history" type="object" class="btn btn-link text-info" icon="fa-history" string="History"/>
                <button name="action_apply_inventory" groups="stock.group_stock_manager" type="object" string="Apply" class="btn btn-link" icon="fa-save" invisible="not inventory_quantity_set"/>
                <button name="action_set_inventory_quantity" type="object" string="Set" class="btn btn-link" icon="fa-bullseye" invisible="inventory_quantity_set"/>
                <button name="action_clear_inventory_quantity" type="object" string="Clear" class="btn text-warning" icon="fa-times" invisible="not inventory_quantity_set"/>
            </tree>
        ', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (1036, 16, NULL, 1, 1, 'stock.warehouse', 'stock.warehouse', NULL, 'form', 'stock/views/stock_warehouse_views.xml', 'primary', '{"en_US": "<form string=\"Warehouse\">\n                    <sheet>\n                        <div class=\"oe_button_box\" name=\"button_box\">\n                            <button name=\"action_view_all_routes\" string=\"Routes\" icon=\"fa-refresh\" class=\"oe_stat_button\" type=\"object\">\n                                    <div class=\"o_stat_info\">\n                                        <span class=\"o_stat_text\">Routes</span>\n                                    </div>\n                            </button>\n                        </div>\n                        <widget name=\"web_ribbon\" title=\"Archived\" bg_color=\"text-bg-danger\" invisible=\"active\"/>\n                        <label for=\"name\"/>\n                        <h1><field name=\"name\" placeholder=\"e.g. Central Warehouse\" class=\"w-100\"/></h1>\n                        <group>\n                            <group>\n                                <field name=\"active\" invisible=\"1\"/>\n                                <field name=\"company_id\" invisible=\"1\"/>\n                                <field name=\"code\" placeholder=\"e.g. CW\"/>\n                            </group>\n                            <group>\n                                <field name=\"company_id\" groups=\"base.group_multi_company\" options=\"{''no_create'': True}\"/>\n                                <field name=\"partner_id\"/>\n                            </group>\n                        </group>\n                        <notebook colspan=\"4\" groups=\"stock.group_adv_location,stock.group_stock_multi_warehouses\">\n                            <page string=\"Warehouse Configuration\" name=\"warehouse_config\" colspan=\"4\">\n                                <group colspan=\"4\">\n                                    <group string=\"Shipments\" groups=\"stock.group_adv_location\">\n                                        <field name=\"reception_steps\" widget=\"radio\"/>\n                                        <field name=\"delivery_steps\" widget=\"radio\"/>\n                                    </group>\n                                    <group name=\"group_resupply\" string=\"Resupply\" groups=\"stock.group_stock_multi_warehouses\">\n                                        <field name=\"resupply_wh_ids\" domain=\"[(''id'', ''!='', id), (''company_id'', ''='', company_id)]\" widget=\"many2many_checkboxes\" groups=\"stock.group_stock_multi_warehouses\"/>\n                                    </group>\n                                </group>\n                            </page>\n                            <page string=\"Technical Information\" name=\"technical_info\" groups=\"base.group_no_one\">\n                                <group>\n                                    <group string=\"Locations\">\n                                        <field name=\"view_location_id\" string=\"Warehouse view location\" readonly=\"1\" required=\"0\"/>\n                                        <field name=\"lot_stock_id\" readonly=\"1\" required=\"0\"/>\n                                        <field name=\"wh_input_stock_loc_id\" readonly=\"1\"/>\n                                        <field name=\"wh_qc_stock_loc_id\" readonly=\"1\"/>\n                                        <field name=\"wh_pack_stock_loc_id\" readonly=\"1\"/>\n                                        <field name=\"wh_output_stock_loc_id\" readonly=\"1\"/>\n                                    </group>\n                                    <group string=\"Operation Types\">\n                                        <field name=\"in_type_id\" readonly=\"1\"/>\n                                        <field name=\"int_type_id\" readonly=\"1\"/>\n                                        <field name=\"pick_type_id\" readonly=\"1\"/>\n                                        <field name=\"pack_type_id\" readonly=\"1\"/>\n                                        <field name=\"out_type_id\" readonly=\"1\"/>\n                                    </group>\n                                </group>\n                            </page>\n                        </notebook>\n                    </sheet>\n                </form>"}', '<?xml version="1.0"?>
<form string="Warehouse">
                    <sheet>
                        <div class="oe_button_box" name="button_box">
                            <button name="action_view_all_routes" string="Routes" icon="fa-refresh" class="oe_stat_button" type="object">
                                    <div class="o_stat_info">
                                        <span class="o_stat_text">Routes</span>
                                    </div>
                            </button>
                        </div>
                        <widget name="web_ribbon" title="Archived" bg_color="text-bg-danger" invisible="active"/>
                        <label for="name"/>
                        <h1><field name="name" placeholder="e.g. Central Warehouse" class="w-100"/></h1>
                        <group>
                            <group>
                                <field name="active" invisible="1"/>
                                <field name="company_id" invisible="1"/>
                                <field name="code" placeholder="e.g. CW"/>
                            </group>
                            <group>
                                <field name="company_id" groups="base.group_multi_company" options="{''no_create'': True}"/>
                                <field name="partner_id"/>
                            </group>
                        </group>
                        <notebook colspan="4" groups="stock.group_adv_location,stock.group_stock_multi_warehouses">
                            <page string="Warehouse Configuration" name="warehouse_config" colspan="4">
                                <group colspan="4">
                                    <group string="Shipments" groups="stock.group_adv_location">
                                        <field name="reception_steps" widget="radio"/>
                                        <field name="delivery_steps" widget="radio"/>
                                    </group>
                                    <group name="group_resupply" string="Resupply" groups="stock.group_stock_multi_warehouses">
                                        <field name="resupply_wh_ids" domain="[(''id'', ''!='', id), (''company_id'', ''='', company_id)]" widget="many2many_checkboxes" groups="stock.group_stock_multi_warehouses"/>
                                    </group>
                                </group>
                            </page>
                            <page string="Technical Information" name="technical_info" groups="base.group_no_one">
                                <group>
                                    <group string="Locations">
                                        <field name="view_location_id" string="Warehouse view location" readonly="1" required="0"/>
                                        <field name="lot_stock_id" readonly="1" required="0"/>
                                        <field name="wh_input_stock_loc_id" readonly="1"/>
                                        <field name="wh_qc_stock_loc_id" readonly="1"/>
                                        <field name="wh_pack_stock_loc_id" readonly="1"/>
                                        <field name="wh_output_stock_loc_id" readonly="1"/>
                                    </group>
                                    <group string="Operation Types">
                                        <field name="in_type_id" readonly="1"/>
                                        <field name="int_type_id" readonly="1"/>
                                        <field name="pick_type_id" readonly="1"/>
                                        <field name="pack_type_id" readonly="1"/>
                                        <field name="out_type_id" readonly="1"/>
                                    </group>
                                </group>
                            </page>
                        </notebook>
                    </sheet>
                </form>
            ', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (1037, 16, NULL, 1, 1, 'stock.warehouse.tree', 'stock.warehouse', NULL, 'tree', 'stock/views/stock_warehouse_views.xml', 'primary', '{"en_US": "<tree string=\"Warehouse\">\n                    <field name=\"sequence\" widget=\"handle\"/>\n                    <field name=\"name\"/>\n                    <field name=\"active\" column_invisible=\"True\"/>\n                    <field name=\"lot_stock_id\" groups=\"stock.group_stock_multi_locations\"/>\n                    <field name=\"partner_id\"/>\n                    <field name=\"company_id\" groups=\"base.group_multi_company\"/>\n                </tree>"}', '<?xml version="1.0"?>
<tree string="Warehouse">
