                    <field name="partner_id"/>
                    <field name="company_id" groups="base.group_multi_company"/>
                </tree>
            ', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (1038, 16, NULL, 1, 1, 'stock.warehouse.search', 'stock.warehouse', NULL, 'search', 'stock/views/stock_warehouse_views.xml', 'primary', '{"en_US": "<search string=\"Warehouse\">\n                    <field name=\"name\"/>\n                    <filter string=\"Archived\" name=\"inactive\" domain=\"[(''active'',''='',False)]\"/>\n                </search>"}', '<?xml version="1.0"?>
