INSERT INTO public.ir_ui_view VALUES (1039, 16, NULL, 1, 1, 'stock.move.line.tree', 'stock.move.line', NULL, 'tree', 'stock/views/stock_move_line_views.xml', 'primary', '{"en_US": "<tree string=\"Move Lines\" create=\"0\" default_order=\"id desc\" action=\"action_open_reference\" type=\"object\" duplicate=\"0\">\n                <field name=\"location_usage\" column_invisible=\"True\"/>\n                <field name=\"location_dest_usage\" column_invisible=\"True\"/>\n                <field name=\"date\"/>\n                <field name=\"reference\" string=\"Reference\" column_invisible=\"context.get(''no_reference'', False)\"/>\n                <field name=\"product_id\"/>\n                <field name=\"lot_id\" optional=\"show\" groups=\"stock.group_production_lot\"/>\n                <field name=\"package_id\" optional=\"hide\" groups=\"stock.group_tracking_lot\"/>\n                <field name=\"result_package_id\" optional=\"hide\" groups=\"stock.group_tracking_lot\"/>\n                <field name=\"location_id\"/>\n                <field name=\"location_dest_id\"/>\n                <field name=\"company_id\" optional=\"hide\" groups=\"base.group_multi_company\" force_save=\"1\"/>\n                <field name=\"quantity\" string=\"Quantity\" decoration-danger=\"(location_usage in (''internal'',''transit'')) and (location_dest_usage not in (''internal'',''transit''))\" decoration-success=\"(location_usage not in (''internal'',''transit'')) and (location_dest_usage in (''internal'',''transit''))\"/>\n                <field name=\"product_uom_id\" options=\"{''no_open'': True, ''no_create'': True}\" string=\"Unit\" groups=\"uom.group_uom\"/>\n                <field name=\"state\" widget=\"badge\" optional=\"show\" decoration-danger=\"state==''cancel''\" decoration-info=\"state== ''assigned''\" decoration-muted=\"state == ''draft''\" decoration-success=\"state == ''done''\" decoration-warning=\"state not in (''draft'',''cancel'',''done'',''assigned'')\"/>\n                <field name=\"create_uid\" string=\"Done By\" widget=\"many2one_avatar_user\" optional=\"hide\"/>\n            </tree>"}', '<?xml version="1.0"?>
<tree string="Move Lines" create="0" default_order="id desc" action="action_open_reference" type="object" duplicate="0">
                <field name="location_usage" column_invisible="True"/>
                <field name="location_dest_usage" column_invisible="True"/>
                <field name="date"/>
                <field name="reference" string="Reference" column_invisible="context.get(''no_reference'', False)"/>
                <field name="product_id"/>
                <field name="lot_id" optional="show" groups="stock.group_production_lot"/>
                <field name="package_id" optional="hide" groups="stock.group_tracking_lot"/>
                <field name="result_package_id" optional="hide" groups="stock.group_tracking_lot"/>
                <field name="location_id"/>
                <field name="location_dest_id"/>
                <field name="company_id" optional="hide" groups="base.group_multi_company" force_save="1"/>
                <field name="quantity" string="Quantity" decoration-danger="(location_usage in (''internal'',''transit'')) and (location_dest_usage not in (''internal'',''transit''))" decoration-success="(location_usage not in (''internal'',''transit'')) and (location_dest_usage in (''internal'',''transit''))"/>
                <field name="product_uom_id" options="{''no_open'': True, ''no_create'': True}" string="Unit" groups="uom.group_uom"/>
                <field name="state" widget="badge" optional="show" decoration-danger="state==''cancel''" decoration-info="state== ''assigned''" decoration-muted="state == ''draft''" decoration-success="state == ''done''" decoration-warning="state not in (''draft'',''cancel'',''done'',''assigned'')"/>
                <field name="create_uid" string="Done By" widget="many2one_avatar_user" optional="hide"/>
            </tree>
        ', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (1055, 16, NULL, 1, 1, 'stock.picking.type.kanban', 'stock.picking.type', NULL, 'kanban', 'stock/views/stock_picking_type_views.xml', 'primary', '{"en_US": "<kanban class=\"o_kanban_dashboard o_emphasize_colors\" create=\"0\" group_create=\"false\">\n                <field name=\"color\"/>\n                <field name=\"code\" readonly=\"1\"/>\n                <field name=\"count_picking_ready\"/>\n                <field name=\"count_picking_draft\"/>\n                <field name=\"count_picking_waiting\"/>\n                <field name=\"count_picking_late\"/>\n                <field name=\"count_picking_backorders\"/>\n                <field name=\"show_picking_type\" invisible=\"1\"/>\n                <templates>\n                    <t t-name=\"kanban-menu\" t-if=\"!selection_mode\">\n                        <div class=\"container\" t-if=\"record.show_picking_type.raw_value\">\n                            <div class=\"row\">\n                                <div class=\"col-6 o_kanban_card_manage_section o_kanban_manage_view\">\n                                    <h5 role=\"menuitem\" class=\"o_kanban_card_manage_title\">\n                                        <span t-if=\"record.code.raw_value == ''internal''\">Transfers</span>\n                                        <span t-else=\"\">View</span>\n                                    </h5>\n                                    <div role=\"menuitem\">\n                                        <a name=\"get_stock_picking_action_picking_type\" type=\"object\">All</a>\n                                    </div>\n                                    <div role=\"menuitem\">\n                                        <a name=\"get_action_picking_tree_ready\" type=\"object\">Ready</a>\n                                    </div>\n                                    <div role=\"menuitem\">\n                                        <a name=\"get_action_picking_tree_waiting\" type=\"object\">Waiting</a>\n                                    </div>\n                                    <div role=\"menuitem\">\n                                        <a name=\"get_action_picking_type_operations\" type=\"object\">Operations</a>\n                                    </div>\n                                </div>\n                                <div class=\"col-6 o_kanban_card_manage_section o_kanban_manage_new\">\n                                    <h5 role=\"menuitem\" class=\"o_kanban_card_manage_title\">\n                                        <a name=\"397\" type=\"action\">New</a>\n                                    </h5>\n                                </div>\n                            </div>\n\n                            <div t-if=\"widget.editable\" class=\"o_kanban_card_manage_settings row\">\n                                <div class=\"col-8\" role=\"menuitem\" aria-haspopup=\"true\">\n                                    <ul class=\"oe_kanban_colorpicker\" data-field=\"color\" role=\"menu\"/>\n                                </div>\n                                <div role=\"menuitem\" class=\"col-4\">\n                                    <a class=\"dropdown-item\" role=\"menuitem\" type=\"edit\">Configuration</a>\n                                </div>\n                            </div>\n                        </div>\n                    </t>\n                    <t t-name=\"kanban-box\">\n                        <div t-if=\"record.show_picking_type.raw_value\" t-attf-class=\"#{!selection_mode ? kanban_color(record.color.raw_value) : ''''}\" name=\"stock_picking\">\n                            <div t-attf-class=\"o_kanban_card_header\">\n                                <div class=\"o_kanban_card_header_title\">\n                                    <div class=\"o_primary\" t-if=\"!selection_mode\">\n                                        <a type=\"object\" name=\"get_stock_picking_action_picking_type\">\n                                            <field name=\"name\"/>\n                                        </a>\n                                    </div>\n                                    <div class=\"o_primary\" t-if=\"selection_mode\">\n                                        <field name=\"name\"/>\n                                    </div>\n                                    <div class=\"o_secondary\"><field class=\"o_secondary\" name=\"warehouse_id\" readonly=\"1\" groups=\"stock.group_stock_multi_warehouses\"/></div>\n                                </div>\n                            </div>\n                            <div class=\"container o_kanban_card_content\" t-if=\"!selection_mode\">\n                                <div class=\"row\">\n                                    <div class=\"col-6 o_kanban_primary_left\">\n                                        <button class=\"btn btn-primary\" name=\"get_action_picking_tree_ready\" type=\"object\">\n                                            <span><t t-esc=\"record.count_picking_ready.value\"/> To Process</span>\n                                        </button>\n                                    </div>\n                                    <div class=\"col-6 o_kanban_primary_right\">\n                                        <div t-if=\"record.count_picking_ready.raw_value &gt; 0\" class=\"row\">\n                                        </div>\n\n                                        <div t-if=\"record.count_picking_waiting.raw_value &gt; 0\" class=\"row\">\n                                            <div class=\"col-12\">\n                                                <a name=\"get_action_picking_tree_waiting\" type=\"object\">\n                                                    <field name=\"count_picking_waiting\"/>\n                                                    Waiting\n                                                </a>\n                                            </div>\n                                        </div>\n\n                                        <div t-if=\"record.count_picking_late.raw_value &gt; 0\" class=\"row\">\n                                            <div class=\"col-12\">\n                                                <a class=\"oe_kanban_stock_picking_type_list\" name=\"get_action_picking_tree_late\" type=\"object\">\n                                                    <field name=\"count_picking_late\"/>\n                                                    Late\n                                                </a>\n                                            </div>\n                                        </div>\n\n                                        <div t-if=\"record.count_picking_backorders.raw_value &gt; 0\" class=\"row\" name=\"picking_type_backorder_count\">\n                                            <div class=\"col-12\">\n                                                <a class=\"oe_kanban_stock_picking_type_list\" name=\"get_action_picking_tree_backorder\" type=\"object\">\n                                                    <field name=\"count_picking_backorders\"/>\n                                                    Back Orders\n                                                </a>\n                                            </div>\n                                        </div>\n                                    </div>\n                                </div>\n                            </div>\n                        </div>\n                    </t>\n                </templates>\n            </kanban>"}', '<?xml version="1.0"?>
<kanban class="o_kanban_dashboard o_emphasize_colors" create="0" group_create="false">
                <field name="color"/>
                <field name="code" readonly="1"/>
                <field name="count_picking_ready"/>
                <field name="count_picking_draft"/>
                <field name="count_picking_waiting"/>
                <field name="count_picking_late"/>
                <field name="count_picking_backorders"/>
                <field name="show_picking_type" invisible="1"/>
                <templates>
                    <t t-name="kanban-menu" t-if="!selection_mode">
                        <div class="container" t-if="record.show_picking_type.raw_value">
                            <div class="row">
                                <div class="col-6 o_kanban_card_manage_section o_kanban_manage_view">
                                    <h5 role="menuitem" class="o_kanban_card_manage_title">
                                        <span t-if="record.code.raw_value == ''internal''">Transfers</span>
                                        <span t-else="">View</span>
                                    </h5>
                                    <div role="menuitem">
                                        <a name="get_stock_picking_action_picking_type" type="object">All</a>
                                    </div>
                                    <div role="menuitem">
                                        <a name="get_action_picking_tree_ready" type="object">Ready</a>
                                    </div>
                                    <div role="menuitem">
                                        <a name="get_action_picking_tree_waiting" type="object">Waiting</a>
                                    </div>
                                    <div role="menuitem">
                                        <a name="get_action_picking_type_operations" type="object">Operations</a>
                                    </div>
                                </div>
                                <div class="col-6 o_kanban_card_manage_section o_kanban_manage_new">
                                    <h5 role="menuitem" class="o_kanban_card_manage_title">
                                        <a name="397" type="action">New</a>
                                    </h5>
                                </div>
                            </div>

                            <div t-if="widget.editable" class="o_kanban_card_manage_settings row">
                                <div class="col-8" role="menuitem" aria-haspopup="true">
                                    <ul class="oe_kanban_colorpicker" data-field="color" role="menu"/>
                                </div>
                                <div role="menuitem" class="col-4">
                                    <a class="dropdown-item" role="menuitem" type="edit">Configuration</a>
                                </div>
                            </div>
                        </div>
                    </t>
                    <t t-name="kanban-box">
                        <div t-if="record.show_picking_type.raw_value" t-attf-class="#{!selection_mode ? kanban_color(record.color.raw_value) : ''''}" name="stock_picking">
                            <div t-attf-class="o_kanban_card_header">
                                <div class="o_kanban_card_header_title">
                                    <div class="o_primary" t-if="!selection_mode">
                                        <a type="object" name="get_stock_picking_action_picking_type">
                                            <field name="name"/>
                                        </a>
                                    </div>
                                    <div class="o_primary" t-if="selection_mode">
                                        <field name="name"/>
                                    </div>
                                    <div class="o_secondary"><field class="o_secondary" name="warehouse_id" readonly="1" groups="stock.group_stock_multi_warehouses"/></div>
                                </div>
                            </div>
                            <div class="container o_kanban_card_content" t-if="!selection_mode">
                                <div class="row">
                                    <div class="col-6 o_kanban_primary_left">
                                        <button class="btn btn-primary" name="get_action_picking_tree_ready" type="object">
                                            <span><t t-esc="record.count_picking_ready.value"/> To Process</span>
                                        </button>
                                    </div>
                                    <div class="col-6 o_kanban_primary_right">
                                        <div t-if="record.count_picking_ready.raw_value &gt; 0" class="row">
                                        </div>

                                        <div t-if="record.count_picking_waiting.raw_value &gt; 0" class="row">
                                            <div class="col-12">
                                                <a name="get_action_picking_tree_waiting" type="object">
                                                    <field name="count_picking_waiting"/>
                                                    Waiting
                                                </a>
                                            </div>
                                        </div>

                                        <div t-if="record.count_picking_late.raw_value &gt; 0" class="row">
                                            <div class="col-12">
                                                <a class="oe_kanban_stock_picking_type_list" name="get_action_picking_tree_late" type="object">
                                                    <field name="count_picking_late"/>
                                                    Late
                                                </a>
                                            </div>
                                        </div>

                                        <div t-if="record.count_picking_backorders.raw_value &gt; 0" class="row" name="picking_type_backorder_count">
                                            <div class="col-12">
                                                <a class="oe_kanban_stock_picking_type_list" name="get_action_picking_tree_backorder" type="object">
                                                    <field name="count_picking_backorders"/>
                                                    Back Orders
                                                </a>
                                            </div>
                                        </div>
                                    </div>
                                </div>
                            </div>
                        </div>
                    </t>
                </templates>
            </kanban>
        ', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (1040, 25, NULL, 1, 1, 'stock.move.line.tree.detailed', 'stock.move.line', NULL, 'tree', 'stock/views/stock_move_line_views.xml', 'primary', '{"en_US": "<tree string=\"Move Lines\" create=\"0\" default_order=\"date\">\n                <field name=\"date\" optional=\"hide\"/>\n                <field name=\"picking_id\"/>\n                <field name=\"picking_partner_id\"/>\n                <field name=\"product_id\"/>\n                <field name=\"lot_id\" groups=\"stock.group_production_lot\" optional=\"hide\"/>\n                <field name=\"location_id\" groups=\"stock.group_stock_multi_locations\"/>\n                <field name=\"location_dest_id\" groups=\"stock.group_stock_multi_locations\"/>\n                <field name=\"package_id\" groups=\"stock.group_tracking_lot\"/>\n                <field name=\"quantity\" string=\"Quantity\" optional=\"hide\"/>\n                <field name=\"product_uom_id\" options=\"{''no_open'': True, ''no_create'': True}\" optional=\"hide\" string=\"Unit of Measure\" groups=\"uom.group_uom\"/>\n                <field name=\"company_id\" groups=\"base.group_multi_company\" force_save=\"1\" optional=\"hide\"/>\n                <field name=\"state\" widget=\"badge\" optional=\"show\" decoration-danger=\"state==''cancel''\" decoration-info=\"state== ''assigned''\" decoration-muted=\"state == ''draft''\" decoration-success=\"state == ''done''\" decoration-warning=\"state not in (''draft'',''cancel'',''done'',''assigned'')\"/>\n            </tree>"}', '<?xml version="1.0"?>
<tree string="Move Lines" create="0" default_order="date">
