                <field name="location_dest_id" groups="stock.group_stock_multi_locations"/>
                <field name="package_id" groups="stock.group_tracking_lot"/>
                <field name="quantity" string="Quantity" optional="hide"/>
                <field name="product_uom_id" options="{''no_open'': True, ''no_create'': True}" optional="hide" string="Unit of Measure" groups="uom.group_uom"/>
                <field name="company_id" groups="base.group_multi_company" force_save="1" optional="hide"/>
                <field name="state" widget="badge" optional="show" decoration-danger="state==''cancel''" decoration-info="state== ''assigned''" decoration-muted="state == ''draft''" decoration-success="state == ''done''" decoration-warning="state not in (''draft'',''cancel'',''done'',''assigned'')"/>
            </tree>
        ', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (1041, 16, NULL, 1, 1, 'stock.move.line.form', 'stock.move.line', NULL, 'form', 'stock/views/stock_move_line_views.xml', 'primary', '{"en_US": "<form string=\"Move Lines\" create=\"0\" edit=\"0\">\n                <header>\n                    <field name=\"state\" widget=\"statusbar\" statusbar_visible=\"draft,confirmed,partially_available,assigned,done\"/>\n                </header>\n                <sheet>\n                    <field name=\"company_id\" invisible=\"1\"/>\n                    <field name=\"picking_id\" invisible=\"1\"/>\n                    <field name=\"location_id\" invisible=\"1\"/>\n                    <field name=\"location_dest_id\" invisible=\"1\"/>\n                    <field name=\"package_id\" invisible=\"1\"/>\n                    <field name=\"product_uom_category_id\" invisible=\"1\"/>\n                    <field name=\"tracking\" invisible=\"1\"/>\n                    <group>\n                        <group>\n                            <field name=\"date\"/>\n                            <field name=\"reference\" string=\"Reference\"/>\n                            <field name=\"origin\"/>\n                            <field name=\"product_id\" readonly=\"context.get(''default_product_id'')\"/>\n                            <field name=\"location_id\" options=\"{''no_create'': True}\" groups=\"stock.group_stock_multi_locations\"/>\n                            <field name=\"location_dest_id\" options=\"{''no_create'': True}\" groups=\"stock.group_stock_multi_locations\"/>\n                        </group>\n                        <group>\n                            <label for=\"quantity\" string=\"Quantity\"/>\n                            <div class=\"o_row\">\n                                <field name=\"quantity\"/>\n                                <field name=\"product_uom_id\" options=\"{''no_create'': True}\" string=\"Unit of Measure\" groups=\"uom.group_uom\"/>\n                            </div>\n                            <field name=\"lot_id\" groups=\"stock.group_production_lot\" context=\"{''default_product_id'': product_id, ''active_picking_id'': picking_id, ''default_company_id'': company_id}\" invisible=\"tracking == ''none'' or not lot_id and lot_name\"/>\n                            <field name=\"lot_name\" groups=\"stock.group_production_lot\" invisible=\"tracking == ''none'' or lot_id or not lot_name\"/>\n                            <field name=\"package_id\" string=\"Source Package\" groups=\"stock.group_tracking_lot\"/>\n                            <field name=\"result_package_id\" string=\"Destination Package\" groups=\"stock.group_tracking_lot\"/>\n                            <field name=\"owner_id\" string=\"Owner\" groups=\"stock.group_tracking_owner\"/>\n                            <field name=\"create_uid\" string=\"Done By\" widget=\"many2one_avatar_user\" optional=\"hide\"/>\n                        </group>\n                    </group>\n                </sheet>\n            </form>"}', '<?xml version="1.0"?>
<form string="Move Lines" create="0" edit="0">
                <header>
                    <field name="state" widget="statusbar" statusbar_visible="draft,confirmed,partially_available,assigned,done"/>
                </header>
                <sheet>
                    <field name="company_id" invisible="1"/>
                    <field name="picking_id" invisible="1"/>
                    <field name="location_id" invisible="1"/>
                    <field name="location_dest_id" invisible="1"/>
                    <field name="package_id" invisible="1"/>
                    <field name="product_uom_category_id" invisible="1"/>
                    <field name="tracking" invisible="1"/>
                    <group>
                        <group>
                            <field name="date"/>
                            <field name="reference" string="Reference"/>
                            <field name="origin"/>
                            <field name="product_id" readonly="context.get(''default_product_id'')"/>
                            <field name="location_id" options="{''no_create'': True}" groups="stock.group_stock_multi_locations"/>
                            <field name="location_dest_id" options="{''no_create'': True}" groups="stock.group_stock_multi_locations"/>
                        </group>
                        <group>
                            <label for="quantity" string="Quantity"/>
                            <div class="o_row">
                                <field name="quantity"/>
                                <field name="product_uom_id" options="{''no_create'': True}" string="Unit of Measure" groups="uom.group_uom"/>
                            </div>
                            <field name="lot_id" groups="stock.group_production_lot" context="{''default_product_id'': product_id, ''active_picking_id'': picking_id, ''default_company_id'': company_id}" invisible="tracking == ''none'' or not lot_id and lot_name"/>
                            <field name="lot_name" groups="stock.group_production_lot" invisible="tracking == ''none'' or lot_id or not lot_name"/>
                            <field name="package_id" string="Source Package" groups="stock.group_tracking_lot"/>
                            <field name="result_package_id" string="Destination Package" groups="stock.group_tracking_lot"/>
                            <field name="owner_id" string="Owner" groups="stock.group_tracking_owner"/>
                            <field name="create_uid" string="Done By" widget="many2one_avatar_user" optional="hide"/>
                        </group>
                    </group>
                </sheet>
            </form>
        ', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (1042, 1000, 1041, 1, 1, 'stock.move.line.mobile.form', 'stock.move.line', NULL, 'form', 'stock/views/stock_move_line_views.xml', 'extension', '{"en_US": "<xpath expr=\"//form\" position=\"attributes\">\n                <attribute name=\"edit\">1</attribute>\n            </xpath>"}', '<?xml version="1.0"?>
<xpath expr="//form" position="attributes">
                <attribute name="edit">1</attribute>
            </xpath>
        ', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (1043, 16, NULL, 1, 1, 'stock.move.line.search', 'stock.move.line', NULL, 'search', 'stock/views/stock_move_line_views.xml', 'primary', '{"en_US": "<search string=\"Stock Moves\">\n                <field name=\"location_id\" string=\"Location\" filter_domain=\"[''|'',(''location_id'', ''ilike'', self),(''location_dest_id'', ''ilike'', self)]\" groups=\"stock.group_stock_multi_locations\"/>\n                <field name=\"product_id\"/>\n                <field name=\"picking_id\" string=\"Transfer\"/>\n                <field name=\"reference\" string=\"Reference\"/>\n                <field name=\"product_category_name\" string=\"Category\"/>\n                <field name=\"lot_id\" string=\"Lot/Serial Number\" groups=\"stock.group_production_lot\"/>\n                <field name=\"package_id\" string=\"Source Package\" groups=\"stock.group_tracking_lot\"/>\n                <field name=\"result_package_id\" string=\"Destination Package\" groups=\"stock.group_tracking_lot\"/>\n                <field name=\"owner_id\" string=\"Owner\" groups=\"stock.group_tracking_owner\"/>\n                <separator/>\n                <filter string=\"To Do\" name=\"todo\" domain=\"[(''state'', ''not in'', [''done'', ''draft'', ''cancel''])]\"/>\n                <filter string=\"Done\" name=\"done\" domain=\"[(''state'', ''='', ''done'')]\"/>\n                <separator/>\n                <filter string=\"Incoming\" name=\"incoming\" domain=\"[(''picking_id.picking_type_id.code'', ''='', ''incoming'')]\"/>\n                <filter string=\"Outgoing\" name=\"outgoing\" domain=\"[(''picking_id.picking_type_id.code'', ''='', ''outgoing'')]\"/>\n                <filter string=\"Internal\" name=\"internal\" domain=\"[(''picking_id.picking_type_id.code'', ''='', ''internal'')]\"/>\n                <filter string=\"Manufacturing\" name=\"manufacturing\" domain=\"[(''picking_id.picking_type_id.code'', ''='', ''mrp_operation'')]\" invisible=\"1\"/>\n                <separator/>\n                <filter name=\"date\" date=\"date\" default_period=\"this_month\"/>\n                <filter string=\"Last 30 Days\" name=\"filter_last_30_days\" domain=\"[(''date'',''&gt;='', (context_today() - relativedelta(days=30)).strftime(''%Y-%m-%d''))]\"/>\n                <filter string=\"Last 3 Months\" name=\"filter_last_3_months\" domain=\"[(''date'',''&gt;='', (context_today() - relativedelta(months=3)).strftime(''%Y-%m-%d''))]\"/>\n                <filter string=\"Last 12 Months\" name=\"filter_last_12_months\" domain=\"[(''date'',''&gt;='', (context_today() - relativedelta(years=1)).strftime(''%Y-%m-%d''))]\"/>\n                <separator/>\n                <filter string=\"Inventory\" name=\"inventory\" domain=\"[(''is_inventory'', ''='', True)]\"/>\n                <separator/>\n                <group expand=\"0\" string=\"Group By\" name=\"groupby\">\n                    <filter string=\"Product\" name=\"groupby_product_id\" domain=\"[]\" context=\"{''group_by'': ''product_id''}\"/>\n                    <filter string=\"Status\" name=\"by_state\" domain=\"[]\" context=\"{''group_by'': ''state''}\"/>\n                    <filter string=\"Date\" name=\"by_date\" domain=\"[]\" context=\"{''group_by'': ''date''}\"/>\n                    <filter string=\"Transfers\" name=\"by_picking\" domain=\"[]\" context=\"{''group_by'': ''picking_id''}\"/>\n                    <filter string=\"Location\" name=\"by_location\" domain=\"[]\" context=\"{''group_by'': ''location_id''}\"/>\n                    <filter string=\"Category\" name=\"by_category\" domain=\"[]\" context=\"{''group_by'': ''product_category_name''}\"/>\n                </group>\n            </search>"}', '<?xml version="1.0"?>
<search string="Stock Moves">
                <field name="location_id" string="Location" filter_domain="[''|'',(''location_id'', ''ilike'', self),(''location_dest_id'', ''ilike'', self)]" groups="stock.group_stock_multi_locations"/>
                <field name="product_id"/>
                <field name="picking_id" string="Transfer"/>
                <field name="reference" string="Reference"/>
                <field name="product_category_name" string="Category"/>
                <field name="lot_id" string="Lot/Serial Number" groups="stock.group_production_lot"/>
                <field name="package_id" string="Source Package" groups="stock.group_tracking_lot"/>
                <field name="result_package_id" string="Destination Package" groups="stock.group_tracking_lot"/>
                <field name="owner_id" string="Owner" groups="stock.group_tracking_owner"/>
                <separator/>
                <filter string="To Do" name="todo" domain="[(''state'', ''not in'', [''done'', ''draft'', ''cancel''])]"/>
                <filter string="Done" name="done" domain="[(''state'', ''='', ''done'')]"/>
                <separator/>
                <filter string="Incoming" name="incoming" domain="[(''picking_id.picking_type_id.code'', ''='', ''incoming'')]"/>
                <filter string="Outgoing" name="outgoing" domain="[(''picking_id.picking_type_id.code'', ''='', ''outgoing'')]"/>
                <filter string="Internal" name="internal" domain="[(''picking_id.picking_type_id.code'', ''='', ''internal'')]"/>
                <filter string="Manufacturing" name="manufacturing" domain="[(''picking_id.picking_type_id.code'', ''='', ''mrp_operation'')]" invisible="1"/>
                <separator/>
                <filter name="date" date="date" default_period="this_month"/>
                <filter string="Last 30 Days" name="filter_last_30_days" domain="[(''date'',''&gt;='', (context_today() - relativedelta(days=30)).strftime(''%Y-%m-%d''))]"/>
                <filter string="Last 3 Months" name="filter_last_3_months" domain="[(''date'',''&gt;='', (context_today() - relativedelta(months=3)).strftime(''%Y-%m-%d''))]"/>
                <filter string="Last 12 Months" name="filter_last_12_months" domain="[(''date'',''&gt;='', (context_today() - relativedelta(years=1)).strftime(''%Y-%m-%d''))]"/>
                <separator/>
                <filter string="Inventory" name="inventory" domain="[(''is_inventory'', ''='', True)]"/>
                <separator/>
                <group expand="0" string="Group By" name="groupby">
                    <filter string="Product" name="groupby_product_id" domain="[]" context="{''group_by'': ''product_id''}"/>
                    <filter string="Status" name="by_state" domain="[]" context="{''group_by'': ''state''}"/>
                    <filter string="Date" name="by_date" domain="[]" context="{''group_by'': ''date''}"/>
                    <filter string="Transfers" name="by_picking" domain="[]" context="{''group_by'': ''picking_id''}"/>
                    <filter string="Location" name="by_location" domain="[]" context="{''group_by'': ''location_id''}"/>
                    <filter string="Category" name="by_category" domain="[]" context="{''group_by'': ''product_category_name''}"/>
                </group>
            </search>
        ', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (1044, 16, NULL, 1, 1, 'stock.move.line.kanban', 'stock.move.line', NULL, 'kanban', 'stock/views/stock_move_line_views.xml', 'primary', '{"en_US": "<kanban class=\"o_kanban_mobile\">\n                <templates>\n                    <t t-name=\"kanban-box\">\n                        <div t-attf-class=\"oe_kanban_card oe_kanban_global_click\">\n                            <field name=\"picking_id\" invisible=\"1\"/>\n                            <field name=\"quant_id\" invisible=\"1\"/>\n                            <div class=\"row\">\n                                <div class=\"col-6\">\n                                    <field name=\"reference\"/>\n                                </div>\n                                <div class=\"col-6 text-end\">\n                                    <field name=\"date\"/>\n                                </div>\n                            </div>\n                            <div>\n                                <strong><field name=\"product_id\"/></strong>\n                            </div>\n                            <div groups=\"stock.group_stock_multi_locations\">\n                                <field name=\"location_id\"/>\n                                →\n                                <field name=\"location_dest_id\"/>\n                            </div>\n                            <div groups=\"stock.group_production_lot\" invisible=\"not lot_id and not lot_name\">\n                                Lot/SN:\n                                <field name=\"lot_id\" invisible=\"not lot_id and lot_name\"/>\n                                <field name=\"lot_name\" invisible=\"lot_id or not lot_name\"/>\n                            </div>\n                            <div class=\"row\">\n                                <div class=\"col-6\">\n                                    <field name=\"quantity\" string=\"Quantity\"/>\n                                    <field name=\"product_uom_id\" string=\"Unit of Measure\" groups=\"uom.group_uom\"/>\n                                </div>\n                                <div class=\"col-6 text-end\">\n                                    <field name=\"state\" widget=\"label_selection\" options=\"{''classes'': {''draft'': ''default'', ''cancel'': ''danger'', ''waiting'': ''warning'', ''confirmed'': ''warning'', ''done'': ''success''}}\"/>\n                                </div>\n                            </div>\n                        </div>\n                    </t>\n                </templates>\n            </kanban>"}', '<?xml version="1.0"?>
<kanban class="o_kanban_mobile">
                <templates>
                    <t t-name="kanban-box">
                        <div t-attf-class="oe_kanban_card oe_kanban_global_click">
                            <field name="picking_id" invisible="1"/>
                            <field name="quant_id" invisible="1"/>
                            <div class="row">
                                <div class="col-6">
                                    <field name="reference"/>
                                </div>
                                <div class="col-6 text-end">
                                    <field name="date"/>
                                </div>
                            </div>
                            <div>
                                <strong><field name="product_id"/></strong>
                            </div>
                            <div groups="stock.group_stock_multi_locations">
                                <field name="location_id"/>
                                →
                                <field name="location_dest_id"/>
                            </div>
                            <div groups="stock.group_production_lot" invisible="not lot_id and not lot_name">
                                Lot/SN:
                                <field name="lot_id" invisible="not lot_id and lot_name"/>
                                <field name="lot_name" invisible="lot_id or not lot_name"/>
                            </div>
                            <div class="row">
                                <div class="col-6">
                                    <field name="quantity" string="Quantity"/>
                                    <field name="product_uom_id" string="Unit of Measure" groups="uom.group_uom"/>
                                </div>
                                <div class="col-6 text-end">
                                    <field name="state" widget="label_selection" options="{''classes'': {''draft'': ''default'', ''cancel'': ''danger'', ''waiting'': ''warning'', ''confirmed'': ''warning'', ''done'': ''success''}}"/>
                                </div>
                            </div>
                        </div>
                    </t>
                </templates>
            </kanban>
        ', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (1045, 16, NULL, 1, 1, 'stock.move.line.pivot', 'stock.move.line', NULL, 'pivot', 'stock/views/stock_move_line_views.xml', 'primary', '{"en_US": "<pivot string=\"Moves History\">\n                <field name=\"product_category_name\" type=\"col\"/>\n                <field name=\"date\" interval=\"month\" type=\"row\"/>\n            </pivot>"}', '<?xml version="1.0"?>
<pivot string="Moves History">
                <field name="product_category_name" type="col"/>
                <field name="date" interval="month" type="row"/>
            </pivot>
        ', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (1048, 16, NULL, 1, 1, 'stock.picking.kanban', 'stock.picking', NULL, 'kanban', 'stock/views/stock_picking_views.xml', 'primary', '{"en_US": "<kanban class=\"o_kanban_mobile\" sample=\"1\">\n                    <field name=\"name\"/>\n                    <field name=\"partner_id\"/>\n                    <field name=\"location_dest_id\"/>\n                    <field name=\"state\"/>\n                    <field name=\"scheduled_date\"/>\n                    <field name=\"activity_state\"/>\n                    <field name=\"picking_type_id\"/>\n                    <progressbar field=\"activity_state\" colors=\"{&quot;planned&quot;: &quot;success&quot;, &quot;today&quot;: &quot;warning&quot;, &quot;overdue&quot;: &quot;danger&quot;}\"/>\n                    <templates>\n                        <t t-name=\"kanban-box\">\n                            <div t-attf-class=\"oe_kanban_card oe_kanban_global_click\">\n                                <div class=\"o_kanban_record_top mb8\">\n                                    <field name=\"priority\" widget=\"priority\"/>\n                                    <div class=\"o_kanban_record_headings ms-1\">\n                                        <strong class=\"o_kanban_record_title\"><span><t t-esc=\"record.name.value\"/></span></strong>\n                                    </div>\n                                    <strong>\n                                            <field name=\"state\" widget=\"label_selection\" options=\"{''classes'': {''draft'': ''default'', ''cancel'': ''danger'', ''waiting'': ''warning'', ''confirmed'': ''warning'', ''done'': ''success''}}\"/>\n                                    </strong>\n                                </div>\n                                <div class=\"o_kanban_record_body\">\n                                    <field name=\"picking_properties\" widget=\"properties\"/>\n                                </div>\n                                <div class=\"o_kanban_record_bottom\">\n                                    <div class=\"oe_kanban_bottom_left\">\n                                        <t t-esc=\"record.partner_id.value\"/>\n                                        <field name=\"activity_ids\" widget=\"kanban_activity\"/>\n                                        <field name=\"json_popover\" nolabel=\"1\" widget=\"stock_rescheduling_popover\" invisible=\"not json_popover\"/>\n                                    </div>\n                                    <div class=\"oe_kanban_bottom_right\">\n                                        <t t-esc=\"record.scheduled_date.value and record.scheduled_date.value.split('' '')[0] or False\"/>\n                                        <field name=\"user_id\" widget=\"many2one_avatar_user\" invisible=\"not user_id\" readonly=\"state in [''cancel'', ''done'']\"/>\n                                    </div>\n                                </div>\n                            </div>\n                        </t>\n                    </templates>\n                </kanban>"}', '<?xml version="1.0"?>
<kanban class="o_kanban_mobile" sample="1">
                    <field name="name"/>
                    <field name="partner_id"/>
                    <field name="location_dest_id"/>
                    <field name="state"/>
                    <field name="scheduled_date"/>
                    <field name="activity_state"/>
                    <field name="picking_type_id"/>
                    <progressbar field="activity_state" colors="{&quot;planned&quot;: &quot;success&quot;, &quot;today&quot;: &quot;warning&quot;, &quot;overdue&quot;: &quot;danger&quot;}"/>
                    <templates>
                        <t t-name="kanban-box">
                            <div t-attf-class="oe_kanban_card oe_kanban_global_click">
                                <div class="o_kanban_record_top mb8">
                                    <field name="priority" widget="priority"/>
                                    <div class="o_kanban_record_headings ms-1">
                                        <strong class="o_kanban_record_title"><span><t t-esc="record.name.value"/></span></strong>
                                    </div>
                                    <strong>
                                            <field name="state" widget="label_selection" options="{''classes'': {''draft'': ''default'', ''cancel'': ''danger'', ''waiting'': ''warning'', ''confirmed'': ''warning'', ''done'': ''success''}}"/>
                                    </strong>
                                </div>
                                <div class="o_kanban_record_body">
                                    <field name="picking_properties" widget="properties"/>
                                </div>
                                <div class="o_kanban_record_bottom">
                                    <div class="oe_kanban_bottom_left">
                                        <t t-esc="record.partner_id.value"/>
                                        <field name="activity_ids" widget="kanban_activity"/>
                                        <field name="json_popover" nolabel="1" widget="stock_rescheduling_popover" invisible="not json_popover"/>
                                    </div>
                                    <div class="oe_kanban_bottom_right">
                                        <t t-esc="record.scheduled_date.value and record.scheduled_date.value.split('' '')[0] or False"/>
                                        <field name="user_id" widget="many2one_avatar_user" invisible="not user_id" readonly="state in [''cancel'', ''done'']"/>
                                    </div>
                                </div>
                            </div>
                        </t>
                    </templates>
                </kanban>
            ', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (1049, 16, NULL, 1, 1, 'stock.picking.tree', 'stock.picking', NULL, 'tree', 'stock/views/stock_picking_views.xml', 'primary', '{"en_US": "<tree string=\"Picking list\" multi_edit=\"1\" sample=\"1\">\n                    <header>\n                        <button name=\"do_unreserve\" type=\"object\" string=\"Unreserve\"/>\n                        <button name=\"action_assign\" type=\"object\" string=\"Check Availability\"/>\n                    </header>\n                    <field name=\"company_id\" column_invisible=\"True\"/>\n                    <field name=\"priority\" optional=\"show\" widget=\"priority\" nolabel=\"1\"/>\n                    <field name=\"name\" decoration-bf=\"1\"/>\n                    <field name=\"location_id\" options=\"{''no_create'': True}\" string=\"From\" groups=\"stock.group_stock_multi_locations\" optional=\"show\" readonly=\"state == ''done''\"/>\n                    <field name=\"location_dest_id\" options=\"{''no_create'': True}\" string=\"To\" groups=\"stock.group_stock_multi_locations\" optional=\"show\" readonly=\"state == ''done''\"/>\n                    <field name=\"partner_id\" optional=\"show\" readonly=\"state in [''cancel'', ''done'']\"/>\n                    <field name=\"is_signed\" string=\"Signed\" optional=\"hide\" groups=\"stock.group_stock_sign_delivery\"/>\n                    <field name=\"user_id\" optional=\"hide\" widget=\"many2one_avatar_user\" readonly=\"state in [''cancel'', ''done'']\"/>\n                    <field name=\"scheduled_date\" optional=\"show\" widget=\"remaining_days\" invisible=\"state in (''done'', ''cancel'')\" readonly=\"state in [''cancel'', ''done'']\"/>\n                    <field name=\"picking_type_code\" column_invisible=\"True\"/>\n                    <field name=\"products_availability_state\" column_invisible=\"True\" options=\"{&quot;lazy&quot;: true}\"/>\n                    <field name=\"products_availability\" options=\"{&quot;lazy&quot;: true}\" optional=\"hide\" invisible=\"picking_type_code != ''outgoing'' or state not in [''confirmed'', ''waiting'', ''assigned'']\" decoration-success=\"state == ''assigned'' or products_availability_state == ''available''\" decoration-warning=\"state != ''assigned'' and products_availability_state in (''expected'', ''available'')\" decoration-danger=\"state != ''assigned'' and products_availability_state == ''late''\"/>\n                    <field name=\"date_deadline\" optional=\"hide\" widget=\"remaining_days\" invisible=\"state in (''done'', ''cancel'')\"/>\n                    <field name=\"date_done\" string=\"Effective Date\" optional=\"hide\"/>\n                    <field name=\"origin\" optional=\"show\" readonly=\"state in [''cancel'', ''done'']\"/>\n                    <field name=\"backorder_id\" optional=\"hide\"/>\n                    <field name=\"picking_type_id\" optional=\"hide\"/>\n                    <field name=\"company_id\" groups=\"base.group_multi_company\" optional=\"show\"/>\n                    <field name=\"state\" optional=\"show\" widget=\"badge\" decoration-danger=\"state==''cancel''\" decoration-info=\"state== ''assigned''\" decoration-muted=\"state == ''draft''\" decoration-success=\"state == ''done''\" decoration-warning=\"state not in (''draft'',''cancel'',''done'',''assigned'')\"/>\n                    <field name=\"activity_exception_decoration\" widget=\"activity_exception\"/>\n                    <field name=\"json_popover\" widget=\"stock_rescheduling_popover\" nolabel=\"1\" invisible=\"not json_popover\"/>\n                </tree>"}', '<?xml version="1.0"?>
<tree string="Picking list" multi_edit="1" sample="1">
                    <header>
                        <button name="do_unreserve" type="object" string="Unreserve"/>
                        <button name="action_assign" type="object" string="Check Availability"/>
                    </header>
                    <field name="company_id" column_invisible="True"/>
                    <field name="priority" optional="show" widget="priority" nolabel="1"/>
                    <field name="name" decoration-bf="1"/>
                    <field name="location_id" options="{''no_create'': True}" string="From" groups="stock.group_stock_multi_locations" optional="show" readonly="state == ''done''"/>
                    <field name="location_dest_id" options="{''no_create'': True}" string="To" groups="stock.group_stock_multi_locations" optional="show" readonly="state == ''done''"/>
                    <field name="partner_id" optional="show" readonly="state in [''cancel'', ''done'']"/>
                    <field name="is_signed" string="Signed" optional="hide" groups="stock.group_stock_sign_delivery"/>
                    <field name="user_id" optional="hide" widget="many2one_avatar_user" readonly="state in [''cancel'', ''done'']"/>
                    <field name="scheduled_date" optional="show" widget="remaining_days" invisible="state in (''done'', ''cancel'')" readonly="state in [''cancel'', ''done'']"/>
                    <field name="picking_type_code" column_invisible="True"/>
                    <field name="products_availability_state" column_invisible="True" options="{&quot;lazy&quot;: true}"/>
                    <field name="products_availability" options="{&quot;lazy&quot;: true}" optional="hide" invisible="picking_type_code != ''outgoing'' or state not in [''confirmed'', ''waiting'', ''assigned'']" decoration-success="state == ''assigned'' or products_availability_state == ''available''" decoration-warning="state != ''assigned'' and products_availability_state in (''expected'', ''available'')" decoration-danger="state != ''assigned'' and products_availability_state == ''late''"/>
                    <field name="date_deadline" optional="hide" widget="remaining_days" invisible="state in (''done'', ''cancel'')"/>
                    <field name="date_done" string="Effective Date" optional="hide"/>
                    <field name="origin" optional="show" readonly="state in [''cancel'', ''done'']"/>
                    <field name="backorder_id" optional="hide"/>
                    <field name="picking_type_id" optional="hide"/>
                    <field name="company_id" groups="base.group_multi_company" optional="show"/>
                    <field name="state" optional="show" widget="badge" decoration-danger="state==''cancel''" decoration-info="state== ''assigned''" decoration-muted="state == ''draft''" decoration-success="state == ''done''" decoration-warning="state not in (''draft'',''cancel'',''done'',''assigned'')"/>
                    <field name="activity_exception_decoration" widget="activity_exception"/>
                    <field name="json_popover" widget="stock_rescheduling_popover" nolabel="1" invisible="not json_popover"/>
                </tree>
            ', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (1050, 12, NULL, 1, 1, 'stock.picking.form', 'stock.picking', NULL, 'form', 'stock/views/stock_picking_views.xml', 'primary', '{"en_US": "<form string=\"Transfer\" js_class=\"picking_form\">\n\n                <field name=\"is_locked\" invisible=\"1\"/>\n                <field name=\"show_check_availability\" invisible=\"1\"/>\n                <field name=\"show_lots_text\" invisible=\"1\"/>\n                <field name=\"picking_type_code\" invisible=\"1\"/>\n                <field name=\"hide_picking_type\" invisible=\"1\"/>\n                <field name=\"show_allocation\" invisible=\"1\"/>\n                <field name=\"show_reserved\" invisible=\"1\" readonly=\"1\"/>\n                <field name=\"move_line_exist\" invisible=\"1\"/>\n                <field name=\"has_packages\" invisible=\"1\"/>\n                <field name=\"picking_type_entire_packs\" invisible=\"1\"/>\n                <field name=\"use_create_lots\" invisible=\"1\"/>\n                <field name=\"company_id\" invisible=\"1\"/>\n\n                <header>\n                    <button name=\"action_confirm\" invisible=\"state != ''draft''\" string=\"Mark as Todo\" type=\"object\" class=\"oe_highlight\" groups=\"base.group_user\" data-hotkey=\"q\"/>\n                    <button name=\"action_assign\" invisible=\"not show_check_availability\" string=\"Check Availability\" type=\"object\" class=\"oe_highlight\" groups=\"base.group_user\" data-hotkey=\"w\"/>\n                    <button name=\"button_validate\" invisible=\"state in (''draft'', ''confirmed'', ''done'', ''cancel'')\" string=\"Validate\" type=\"object\" class=\"oe_highlight\" groups=\"stock.group_stock_user\" data-hotkey=\"v\"/>\n                    <button name=\"button_validate\" invisible=\"state in (''waiting'', ''assigned'', ''done'', ''cancel'')\" string=\"Validate\" type=\"object\" groups=\"stock.group_stock_user\" class=\"o_btn_validate\" data-hotkey=\"v\"/>\n                    <widget name=\"signature\" string=\"Sign\" highlight=\"1\" invisible=\"not id or picking_type_code != ''outgoing'' or state != ''done''\" full_name=\"partner_id\" groups=\"stock.group_stock_sign_delivery\"/>\n                    <widget name=\"signature\" string=\"Sign\" invisible=\"not id or picking_type_code != ''outgoing'' or state == ''done''\" full_name=\"partner_id\" groups=\"stock.group_stock_sign_delivery\"/>\n                    <button name=\"do_print_picking\" string=\"Print\" groups=\"stock.group_stock_user\" type=\"object\" invisible=\"state != ''assigned''\" data-hotkey=\"o\"/>\n                    <button string=\"Print Labels\" type=\"object\" name=\"action_open_label_type\"/>\n                    <button name=\"340\" string=\"Print\" invisible=\"state != ''done''\" type=\"action\" groups=\"base.group_user\" data-hotkey=\"o\"/>\n                    <button name=\"358\" string=\"Return\" invisible=\"state != ''done''\" type=\"action\" groups=\"base.group_user\" data-hotkey=\"k\"/>\n                    <field name=\"state\" widget=\"statusbar\" invisible=\"picking_type_code != ''incoming''\" statusbar_visible=\"draft,assigned,done\"/>\n                    <field name=\"state\" widget=\"statusbar\" invisible=\"picking_type_code == ''incoming''\" statusbar_visible=\"draft,confirmed,assigned,done\"/>\n                    <button name=\"action_cancel\" invisible=\"state not in (''assigned'', ''confirmed'', ''draft'', ''waiting'')\" string=\"Cancel\" groups=\"base.group_user\" type=\"object\" confirm=\"Are you sure you want to cancel this transfer?\" data-hotkey=\"x\"/>\n                </header>\n                <sheet>\n                    <div class=\"oe_button_box\" name=\"button_box\">\n                        <field name=\"has_scrap_move\" invisible=\"True\"/>\n                        <field name=\"has_tracking\" invisible=\"True\"/>\n                        <button name=\"action_see_returns\" type=\"object\" class=\"oe_stat_button\" icon=\"fa-rotate-left\" invisible=\"return_count == 0\">\n                            <field string=\"Returns\" name=\"return_count\" widget=\"statinfo\"/>\n                        </button>\n                        <button name=\"action_see_move_scrap\" string=\"Scraps\" type=\"object\" class=\"oe_stat_button\" icon=\"oi-arrows-v\" invisible=\"not has_scrap_move\"/>\n                        <button name=\"action_see_packages\" string=\"Packages\" type=\"object\" class=\"oe_stat_button\" icon=\"fa-cubes\" invisible=\"not has_packages\"/>\n                        <button name=\"336\" icon=\"oi-arrow-up\" class=\"oe_stat_button\" type=\"action\" invisible=\"state != ''done'' or not has_tracking\" groups=\"stock.group_production_lot\">\n                            <div class=\"o_stat_info\">\n                                <span class=\"o_stat_text\">Traceability</span>\n                            </div>\n                        </button>\n                        <button name=\"action_view_reception_report\" type=\"object\" context=\"{''default_picking_ids'': [id]}\" class=\"oe_stat_button\" icon=\"fa-list\" invisible=\"not show_allocation\" groups=\"stock.group_reception_report\">\n                            <div class=\"o_stat_info\">\n                                <span class=\"o_stat_text\">Allocation</span>\n                            </div>\n                        </button>\n                        <!-- Use the following button to avoid onchange on one2many -->\n                        <button name=\"action_picking_move_tree\" class=\"oe_stat_button\" icon=\"oi-arrows-v\" type=\"object\" help=\"List view of operations\" groups=\"base.group_no_one\" invisible=\"(is_locked or state == ''done'') or state == ''done'' and is_locked\" context=\"{''picking_type_code'': picking_type_code, ''default_picking_id'': id, ''form_view_ref'':''stock.view_move_form'', ''address_in_id'': partner_id, ''default_picking_type_id'': picking_type_id, ''default_location_id'': location_id, ''default_location_dest_id'': location_dest_id}\">\n                            <div class=\"o_form_field o_stat_info\">\n                                <span class=\"o_stat_text\">Operations</span>\n                            </div>\n                        </button>\n                        <button name=\"action_detailed_operations\" class=\"oe_stat_button\" icon=\"fa-bars\" type=\"object\" help=\"List view of detailed operations\">\n                            <div class=\"o_form_field o_stat_info\">\n                                <span class=\"o_stat_text\">Detailed Operations</span>\n                            </div>\n                        </button>\n                    </div>\n                    <div class=\"oe_title\">\n                        <h1 class=\"d-flex\">\n                            <field name=\"priority\" widget=\"priority\" class=\"me-3\" invisible=\"name == ''/''\"/>\n                            <field name=\"name\" invisible=\"name == ''/''\"/>\n                        </h1>\n                    </div>\n                    <group>\n                        <group>\n                            <div class=\"o_td_label\">\n                                <label for=\"partner_id\" string=\"Delivery Address\" style=\"font-weight:bold;\" invisible=\"picking_type_code != ''outgoing''\"/>\n                                <label for=\"partner_id\" string=\"Receive From\" style=\"font-weight:bold;\" invisible=\"picking_type_code != ''incoming''\"/>\n                                <label for=\"partner_id\" string=\"Contact\" style=\"font-weight:bold;\" invisible=\"picking_type_code in [''incoming'', ''outgoing'']\"/>\n                            </div>\n                            <field name=\"partner_id\" nolabel=\"1\" readonly=\"state in [''cancel'', ''done'']\"/>\n                            <field name=\"picking_type_id\" options=\"{''no_open'': True}\" invisible=\"hide_picking_type\" readonly=\"state != ''draft'' and id\" domain=\"context.get(''restricted_picking_type_code'') and [(''code'', ''='', context.get(''restricted_picking_type_code''))] or [(1,''='',1)]\"/>\n                            <field name=\"location_id\" groups=\"!stock.group_stock_multi_locations\" invisible=\"1\" readonly=\"state == ''done''\"/>\n                            <field name=\"location_dest_id\" groups=\"!stock.group_stock_multi_locations\" invisible=\"1\" readonly=\"state == ''done''\"/>\n                            <field name=\"location_id\" options=\"{''no_create'': True}\" groups=\"stock.group_stock_multi_locations\" invisible=\"picking_type_code == ''incoming''\" readonly=\"state == ''done''\"/>\n                            <field name=\"location_dest_id\" options=\"{''no_create'': True}\" groups=\"stock.group_stock_multi_locations\" invisible=\"picking_type_code == ''outgoing''\" readonly=\"state == ''done''\"/>\n                            <field name=\"backorder_id\" invisible=\"not backorder_id\"/>\n                        </group>\n                        <group>\n                            <label for=\"scheduled_date\"/>\n                            <div class=\"o_row\">\n                                <field name=\"scheduled_date\" readonly=\"state in [''cancel'', ''done'']\" required=\"id\" decoration-warning=\"state not in (''done'', ''cancel'') and scheduled_date &lt; now\" decoration-danger=\"state not in (''done'', ''cancel'') and scheduled_date &lt; current_date\" decoration-bf=\"state not in (''done'', ''cancel'') and (scheduled_date &lt; current_date or scheduled_date &lt; now)\"/>\n                                <field name=\"json_popover\" nolabel=\"1\" widget=\"stock_rescheduling_popover\" invisible=\"not json_popover\"/>\n                            </div>\n                            <field name=\"date_deadline\" invisible=\"state in (''done'', ''cancel'') or not date_deadline\" decoration-danger=\"date_deadline and date_deadline &lt; current_date\" decoration-bf=\"date_deadline and date_deadline &lt; current_date\"/>\n                            <field name=\"products_availability_state\" invisible=\"1\"/>\n                            <field name=\"products_availability\" invisible=\"picking_type_code != ''outgoing'' or state not in [''confirmed'', ''waiting'', ''assigned'']\" decoration-success=\"state == ''assigned'' or products_availability_state == ''available''\" decoration-warning=\"state != ''assigned'' and products_availability_state in (''expected'', ''available'')\" decoration-danger=\"state != ''assigned'' and products_availability_state == ''late''\"/>\n                            <field name=\"date_done\" string=\"Effective Date\" invisible=\"state != ''done''\"/>\n                            <field name=\"origin\" placeholder=\"e.g. PO0032\" readonly=\"state in [''cancel'', ''done'']\"/>\n                            <field name=\"owner_id\" groups=\"stock.group_tracking_owner\" invisible=\"picking_type_code != ''incoming''\" readonly=\"state in [''cancel'', ''done'']\"/>\n                        </group>\n                    </group>\n                    <field name=\"picking_properties\" columns=\"2\"/>\n                    <notebook>\n                        <page string=\"Operations\" name=\"operations\">\n                            <field name=\"move_ids_without_package\" mode=\"tree,kanban\" widget=\"stock_move_one2many\" readonly=\"state == ''done'' and is_locked\" context=\"{''default_company_id'': company_id, ''default_date'': scheduled_date, ''default_date_deadline'': date_deadline, ''picking_type_code'': picking_type_code, ''default_picking_id'': id, ''form_view_ref'': ''stock.view_stock_move_operations'', ''address_in_id'': partner_id, ''default_picking_type_id'': picking_type_id, ''default_location_id'': location_id, ''default_location_dest_id'': location_dest_id, ''default_partner_id'': partner_id}\" add-label=\"Add a Product\">\n                                <tree decoration-muted=\"scrapped == True or state == ''cancel'' or (state == ''done'' and is_locked == True)\" string=\"Stock Moves\" editable=\"1\">\n                                    <field name=\"company_id\" column_invisible=\"True\"/>\n                                    <field name=\"picking_id\" column_invisible=\"True\"/>\n                                    <field name=\"name\" column_invisible=\"True\"/>\n                                    <field name=\"state\" readonly=\"0\" column_invisible=\"True\"/>\n                                    <field name=\"picking_type_id\" column_invisible=\"True\"/>\n                                    <field name=\"move_line_ids\" column_invisible=\"True\"/>\n                                    <field name=\"location_id\" column_invisible=\"True\"/>\n                                    <field name=\"location_dest_id\" column_invisible=\"True\"/>\n                                    <field name=\"partner_id\" column_invisible=\"True\" readonly=\"state == ''done''\"/>\n                                    <field name=\"scrapped\" column_invisible=\"True\"/>\n                                    <field name=\"picking_code\" column_invisible=\"True\"/>\n                                    <field name=\"product_type\" column_invisible=\"True\"/>\n                                    <field name=\"show_details_visible\" column_invisible=\"True\"/>\n                                    <field name=\"show_reserved\" column_invisible=\"True\"/>\n                                    <field name=\"additional\" column_invisible=\"True\"/>\n                                    <field name=\"move_lines_count\" column_invisible=\"True\"/>\n                                    <field name=\"is_locked\" column_invisible=\"True\"/>\n                                    <field name=\"product_uom_category_id\" column_invisible=\"True\"/>\n                                    <field name=\"has_tracking\" column_invisible=\"True\"/>\n                                    <field name=\"display_assign_serial\" column_invisible=\"True\"/>\n                                    <field name=\"product_id\" context=\"{''default_detailed_type'': ''product''}\" required=\"1\" readonly=\"(state != ''draft'' and not additional) or move_lines_count &gt; 0\" force_save=\"1\"/>\n                                    <field name=\"description_picking\" string=\"Description\" optional=\"hide\"/>\n                                    <field name=\"date\" optional=\"hide\"/>\n                                    <field name=\"date_deadline\" optional=\"hide\"/>\n                                    <field name=\"is_quantity_done_editable\" column_invisible=\"True\"/>\n                                    <field name=\"show_quant\" column_invisible=\"True\"/>\n                                    <field name=\"show_lots_text\" column_invisible=\"True\"/>\n                                    <field name=\"show_lots_m2o\" column_invisible=\"True\"/>\n                                    <field name=\"display_assign_serial\" column_invisible=\"True\"/>\n                                    <field name=\"is_initial_demand_editable\" column_invisible=\"True\"/>\n                                    <field name=\"display_import_lot\" column_invisible=\"True\"/>\n                                    <field name=\"picking_type_entire_packs\" column_invisible=\"True\"/>\n                                    <field name=\"product_packaging_id\" groups=\"product.group_stock_packaging\" context=\"{''default_product_id'': product_id}\" readonly=\"not product_id\"/>\n                                    <field name=\"product_uom_qty\" string=\"Demand\" readonly=\"not is_initial_demand_editable\"/>\n                                    <field name=\"forecast_expected_date\" column_invisible=\"True\"/>\n                                    <field name=\"forecast_availability\" string=\"Forecast\" optional=\"hide\" column_invisible=\"parent.state in (''draft'', ''done'') or parent.picking_type_code != ''outgoing''\" widget=\"forecast_widget\"/>\n                                    <field name=\"product_qty\" readonly=\"1\" column_invisible=\"True\"/>\n                                    <field name=\"quantity\" string=\"Quantity\" readonly=\"not is_quantity_done_editable\" column_invisible=\"parent.state==''draft''\" decoration-danger=\"product_uom_qty and quantity &gt; product_uom_qty and parent.state not in [''done'', ''cancel'']\"/>\n                                    <field name=\"product_uom\" readonly=\"state != ''draft'' and not additional\" options=\"{''no_open'': True, ''no_create'': True}\" string=\"Unit\" groups=\"uom.group_uom\"/>\n                                    <field name=\"product_uom\" groups=\"!uom.group_uom\" column_invisible=\"True\"/>\n                                    <field name=\"picked\" optional=\"hide\" column_invisible=\"parent.state==''draft''\"/>\n                                    <field name=\"lot_ids\" widget=\"many2many_tags\" column_invisible=\"parent.state == ''draft''\" groups=\"stock.group_production_lot\" invisible=\"not show_details_visible or has_tracking == ''none''\" optional=\"hide\" options=\"{''create'': [(''parent.use_create_lots'', ''='', True)]}\" context=\"{''default_company_id'': company_id, ''default_product_id'': product_id, ''active_picking_id'': parent.id}\" domain=\"[(''product_id'',''='',product_id)]\"/>\n                                    <button name=\"action_assign_serial\" type=\"object\" icon=\"fa-plus-square\" role=\"img\" title=\"Assign Serial Numbers\" invisible=\"not display_assign_serial\"/>\n                                    <button type=\"object\" name=\"action_product_forecast_report\" title=\"Forecast Report\" icon=\"fa-area-chart\" invisible=\"quantity == 0 and forecast_availability &lt;= 0 or (parent.picking_type_code == ''outgoing'' and state != ''draft'')\"/>\n                                    <button type=\"object\" name=\"action_product_forecast_report\" title=\"Forecast Report\" icon=\"fa-area-chart text-danger\" invisible=\"quantity &gt; 0 or forecast_availability &gt; 0 or (parent.picking_type_code == ''outgoing'' and state != ''draft'')\"/>\n                                </tree>\n                            </field>\n                            <field name=\"id\" invisible=\"1\"/>\n                            <field name=\"package_level_ids\" context=\"{''default_location_id'': location_id, ''default_location_dest_id'': location_dest_id, ''default_company_id'': company_id}\" invisible=\"not picking_type_entire_packs\" readonly=\"state == ''done''\"/>\n                            <button class=\"btn-secondary float-end\" name=\"action_put_in_pack\" type=\"object\" string=\"Put in Pack\" invisible=\"state in (''draft'', ''done'', ''cancel'')\" groups=\"stock.group_tracking_lot\" data-hotkey=\"shift+g\"/>\n                        </page>\n                        <page string=\"Additional Info\" name=\"extra\">\n                            <group>\n                                <group string=\"Other Information\" name=\"other_infos\">\n                                    <field name=\"picking_type_code\" invisible=\"1\"/>\n                                    <field name=\"move_type\" invisible=\"picking_type_code == ''incoming''\" readonly=\"state in [''cancel'', ''done'']\"/>\n                                    <field name=\"user_id\" widget=\"many2one_avatar_user\" domain=\"[(''share'', ''='', False)]\" readonly=\"state in [''cancel'', ''done'']\"/>\n                                    <field name=\"group_id\" groups=\"base.group_no_one\"/>\n                                    <field name=\"company_id\" groups=\"base.group_multi_company\" options=\"{''no_create'': True}\" force_save=\"1\"/>\n                                </group>\n                            </group>\n                        </page>\n                        <page string=\"Note\" name=\"note\">\n                            <field name=\"note\" string=\"Note\" placeholder=\"Add an internal note that will be printed on the Picking Operations sheet\"/>\n                        </page>\n                    </notebook>\n                </sheet>\n                <div class=\"oe_chatter\">\n                    <field name=\"message_follower_ids\"/>\n                    <field name=\"activity_ids\"/>\n                    <field name=\"message_ids\"/>\n                </div>\n                </form>"}', '<?xml version="1.0"?>
<form string="Transfer" js_class="picking_form">

                <field name="is_locked" invisible="1"/>
                <field name="show_check_availability" invisible="1"/>
                <field name="show_lots_text" invisible="1"/>
                <field name="picking_type_code" invisible="1"/>
                <field name="hide_picking_type" invisible="1"/>
                <field name="show_allocation" invisible="1"/>
                <field name="show_reserved" invisible="1" readonly="1"/>
                <field name="move_line_exist" invisible="1"/>
                <field name="has_packages" invisible="1"/>
                <field name="picking_type_entire_packs" invisible="1"/>
                <field name="use_create_lots" invisible="1"/>
                <field name="company_id" invisible="1"/>

                <header>
                    <button name="action_confirm" invisible="state != ''draft''" string="Mark as Todo" type="object" class="oe_highlight" groups="base.group_user" data-hotkey="q"/>
                    <button name="action_assign" invisible="not show_check_availability" string="Check Availability" type="object" class="oe_highlight" groups="base.group_user" data-hotkey="w"/>
                    <button name="button_validate" invisible="state in (''draft'', ''confirmed'', ''done'', ''cancel'')" string="Validate" type="object" class="oe_highlight" groups="stock.group_stock_user" data-hotkey="v"/>
                    <button name="button_validate" invisible="state in (''waiting'', ''assigned'', ''done'', ''cancel'')" string="Validate" type="object" groups="stock.group_stock_user" class="o_btn_validate" data-hotkey="v"/>
                    <widget name="signature" string="Sign" highlight="1" invisible="not id or picking_type_code != ''outgoing'' or state != ''done''" full_name="partner_id" groups="stock.group_stock_sign_delivery"/>
                    <widget name="signature" string="Sign" invisible="not id or picking_type_code != ''outgoing'' or state == ''done''" full_name="partner_id" groups="stock.group_stock_sign_delivery"/>
                    <button name="do_print_picking" string="Print" groups="stock.group_stock_user" type="object" invisible="state != ''assigned''" data-hotkey="o"/>
                    <button string="Print Labels" type="object" name="action_open_label_type"/>
                    <button name="340" string="Print" invisible="state != ''done''" type="action" groups="base.group_user" data-hotkey="o"/>
                    <button name="358" string="Return" invisible="state != ''done''" type="action" groups="base.group_user" data-hotkey="k"/>
                    <field name="state" widget="statusbar" invisible="picking_type_code != ''incoming''" statusbar_visible="draft,assigned,done"/>
                    <field name="state" widget="statusbar" invisible="picking_type_code == ''incoming''" statusbar_visible="draft,confirmed,assigned,done"/>
                    <button name="action_cancel" invisible="state not in (''assigned'', ''confirmed'', ''draft'', ''waiting'')" string="Cancel" groups="base.group_user" type="object" confirm="Are you sure you want to cancel this transfer?" data-hotkey="x"/>
                </header>
                <sheet>
                    <div class="oe_button_box" name="button_box">
                        <field name="has_scrap_move" invisible="True"/>
                        <field name="has_tracking" invisible="True"/>
                        <button name="action_see_returns" type="object" class="oe_stat_button" icon="fa-rotate-left" invisible="return_count == 0">
                            <field string="Returns" name="return_count" widget="statinfo"/>
                        </button>
                        <button name="action_see_move_scrap" string="Scraps" type="object" class="oe_stat_button" icon="oi-arrows-v" invisible="not has_scrap_move"/>
                        <button name="action_see_packages" string="Packages" type="object" class="oe_stat_button" icon="fa-cubes" invisible="not has_packages"/>
                        <button name="336" icon="oi-arrow-up" class="oe_stat_button" type="action" invisible="state != ''done'' or not has_tracking" groups="stock.group_production_lot">
                            <div class="o_stat_info">
                                <span class="o_stat_text">Traceability</span>
                            </div>
                        </button>
                        <button name="action_view_reception_report" type="object" context="{''default_picking_ids'': [id]}" class="oe_stat_button" icon="fa-list" invisible="not show_allocation" groups="stock.group_reception_report">
                            <div class="o_stat_info">
                                <span class="o_stat_text">Allocation</span>
                            </div>
                        </button>
                        <!-- Use the following button to avoid onchange on one2many -->
                        <button name="action_picking_move_tree" class="oe_stat_button" icon="oi-arrows-v" type="object" help="List view of operations" groups="base.group_no_one" invisible="(is_locked or state == ''done'') or state == ''done'' and is_locked" context="{''picking_type_code'': picking_type_code, ''default_picking_id'': id, ''form_view_ref'':''stock.view_move_form'', ''address_in_id'': partner_id, ''default_picking_type_id'': picking_type_id, ''default_location_id'': location_id, ''default_location_dest_id'': location_dest_id}">
                            <div class="o_form_field o_stat_info">
                                <span class="o_stat_text">Operations</span>
                            </div>
                        </button>
                        <button name="action_detailed_operations" class="oe_stat_button" icon="fa-bars" type="object" help="List view of detailed operations">
                            <div class="o_form_field o_stat_info">
                                <span class="o_stat_text">Detailed Operations</span>
                            </div>
                        </button>
                    </div>
                    <div class="oe_title">
                        <h1 class="d-flex">
                            <field name="priority" widget="priority" class="me-3" invisible="name == ''/''"/>
                            <field name="name" invisible="name == ''/''"/>
                        </h1>
                    </div>
                    <group>
                        <group>
                            <div class="o_td_label">
                                <label for="partner_id" string="Delivery Address" style="font-weight:bold;" invisible="picking_type_code != ''outgoing''"/>
                                <label for="partner_id" string="Receive From" style="font-weight:bold;" invisible="picking_type_code != ''incoming''"/>
                                <label for="partner_id" string="Contact" style="font-weight:bold;" invisible="picking_type_code in [''incoming'', ''outgoing'']"/>
                            </div>
                            <field name="partner_id" nolabel="1" readonly="state in [''cancel'', ''done'']"/>
                            <field name="picking_type_id" options="{''no_open'': True}" invisible="hide_picking_type" readonly="state != ''draft'' and id" domain="context.get(''restricted_picking_type_code'') and [(''code'', ''='', context.get(''restricted_picking_type_code''))] or [(1,''='',1)]"/>
                            <field name="location_id" groups="!stock.group_stock_multi_locations" invisible="1" readonly="state == ''done''"/>
                            <field name="location_dest_id" groups="!stock.group_stock_multi_locations" invisible="1" readonly="state == ''done''"/>
                            <field name="location_id" options="{''no_create'': True}" groups="stock.group_stock_multi_locations" invisible="picking_type_code == ''incoming''" readonly="state == ''done''"/>
                            <field name="location_dest_id" options="{''no_create'': True}" groups="stock.group_stock_multi_locations" invisible="picking_type_code == ''outgoing''" readonly="state == ''done''"/>
                            <field name="backorder_id" invisible="not backorder_id"/>
                        </group>
                        <group>
                            <label for="scheduled_date"/>
                            <div class="o_row">
                                <field name="scheduled_date" readonly="state in [''cancel'', ''done'']" required="id" decoration-warning="state not in (''done'', ''cancel'') and scheduled_date &lt; now" decoration-danger="state not in (''done'', ''cancel'') and scheduled_date &lt; current_date" decoration-bf="state not in (''done'', ''cancel'') and (scheduled_date &lt; current_date or scheduled_date &lt; now)"/>
                                <field name="json_popover" nolabel="1" widget="stock_rescheduling_popover" invisible="not json_popover"/>
                            </div>
                            <field name="date_deadline" invisible="state in (''done'', ''cancel'') or not date_deadline" decoration-danger="date_deadline and date_deadline &lt; current_date" decoration-bf="date_deadline and date_deadline &lt; current_date"/>
                            <field name="products_availability_state" invisible="1"/>
                            <field name="products_availability" invisible="picking_type_code != ''outgoing'' or state not in [''confirmed'', ''waiting'', ''assigned'']" decoration-success="state == ''assigned'' or products_availability_state == ''available''" decoration-warning="state != ''assigned'' and products_availability_state in (''expected'', ''available'')" decoration-danger="state != ''assigned'' and products_availability_state == ''late''"/>
                            <field name="date_done" string="Effective Date" invisible="state != ''done''"/>
                            <field name="origin" placeholder="e.g. PO0032" readonly="state in [''cancel'', ''done'']"/>
                            <field name="owner_id" groups="stock.group_tracking_owner" invisible="picking_type_code != ''incoming''" readonly="state in [''cancel'', ''done'']"/>
                        </group>
                    </group>
                    <field name="picking_properties" columns="2"/>
                    <notebook>
                        <page string="Operations" name="operations">
                            <field name="move_ids_without_package" mode="tree,kanban" widget="stock_move_one2many" readonly="state == ''done'' and is_locked" context="{''default_company_id'': company_id, ''default_date'': scheduled_date, ''default_date_deadline'': date_deadline, ''picking_type_code'': picking_type_code, ''default_picking_id'': id, ''form_view_ref'': ''stock.view_stock_move_operations'', ''address_in_id'': partner_id, ''default_picking_type_id'': picking_type_id, ''default_location_id'': location_id, ''default_location_dest_id'': location_dest_id, ''default_partner_id'': partner_id}" add-label="Add a Product">
                                <tree decoration-muted="scrapped == True or state == ''cancel'' or (state == ''done'' and is_locked == True)" string="Stock Moves" editable="1">
                                    <field name="company_id" column_invisible="True"/>
                                    <field name="picking_id" column_invisible="True"/>
                                    <field name="name" column_invisible="True"/>
                                    <field name="state" readonly="0" column_invisible="True"/>
                                    <field name="picking_type_id" column_invisible="True"/>
                                    <field name="move_line_ids" column_invisible="True"/>
                                    <field name="location_id" column_invisible="True"/>
                                    <field name="location_dest_id" column_invisible="True"/>
                                    <field name="partner_id" column_invisible="True" readonly="state == ''done''"/>
                                    <field name="scrapped" column_invisible="True"/>
                                    <field name="picking_code" column_invisible="True"/>
                                    <field name="product_type" column_invisible="True"/>
                                    <field name="show_details_visible" column_invisible="True"/>
                                    <field name="show_reserved" column_invisible="True"/>
                                    <field name="additional" column_invisible="True"/>
                                    <field name="move_lines_count" column_invisible="True"/>
                                    <field name="is_locked" column_invisible="True"/>
                                    <field name="product_uom_category_id" column_invisible="True"/>
                                    <field name="has_tracking" column_invisible="True"/>
                                    <field name="display_assign_serial" column_invisible="True"/>
                                    <field name="product_id" context="{''default_detailed_type'': ''product''}" required="1" readonly="(state != ''draft'' and not additional) or move_lines_count &gt; 0" force_save="1"/>
                                    <field name="description_picking" string="Description" optional="hide"/>
                                    <field name="date" optional="hide"/>
                                    <field name="date_deadline" optional="hide"/>
                                    <field name="is_quantity_done_editable" column_invisible="True"/>
                                    <field name="show_quant" column_invisible="True"/>
                                    <field name="show_lots_text" column_invisible="True"/>
                                    <field name="show_lots_m2o" column_invisible="True"/>
                                    <field name="display_assign_serial" column_invisible="True"/>
                                    <field name="is_initial_demand_editable" column_invisible="True"/>
                                    <field name="display_import_lot" column_invisible="True"/>
                                    <field name="picking_type_entire_packs" column_invisible="True"/>
                                    <field name="product_packaging_id" groups="product.group_stock_packaging" context="{''default_product_id'': product_id}" readonly="not product_id"/>
                                    <field name="product_uom_qty" string="Demand" readonly="not is_initial_demand_editable"/>
                                    <field name="forecast_expected_date" column_invisible="True"/>
                                    <field name="forecast_availability" string="Forecast" optional="hide" column_invisible="parent.state in (''draft'', ''done'') or parent.picking_type_code != ''outgoing''" widget="forecast_widget"/>
                                    <field name="product_qty" readonly="1" column_invisible="True"/>
                                    <field name="quantity" string="Quantity" readonly="not is_quantity_done_editable" column_invisible="parent.state==''draft''" decoration-danger="product_uom_qty and quantity &gt; product_uom_qty and parent.state not in [''done'', ''cancel'']"/>
                                    <field name="product_uom" readonly="state != ''draft'' and not additional" options="{''no_open'': True, ''no_create'': True}" string="Unit" groups="uom.group_uom"/>
                                    <field name="product_uom" groups="!uom.group_uom" column_invisible="True"/>
                                    <field name="picked" optional="hide" column_invisible="parent.state==''draft''"/>
                                    <field name="lot_ids" widget="many2many_tags" column_invisible="parent.state == ''draft''" groups="stock.group_production_lot" invisible="not show_details_visible or has_tracking == ''none''" optional="hide" options="{''create'': [(''parent.use_create_lots'', ''='', True)]}" context="{''default_company_id'': company_id, ''default_product_id'': product_id, ''active_picking_id'': parent.id}" domain="[(''product_id'',''='',product_id)]"/>
                                    <button name="action_assign_serial" type="object" icon="fa-plus-square" role="img" title="Assign Serial Numbers" invisible="not display_assign_serial"/>
                                    <button type="object" name="action_product_forecast_report" title="Forecast Report" icon="fa-area-chart" invisible="quantity == 0 and forecast_availability &lt;= 0 or (parent.picking_type_code == ''outgoing'' and state != ''draft'')"/>
                                    <button type="object" name="action_product_forecast_report" title="Forecast Report" icon="fa-area-chart text-danger" invisible="quantity &gt; 0 or forecast_availability &gt; 0 or (parent.picking_type_code == ''outgoing'' and state != ''draft'')"/>
                                </tree>
                            </field>
                            <field name="id" invisible="1"/>
                            <field name="package_level_ids" context="{''default_location_id'': location_id, ''default_location_dest_id'': location_dest_id, ''default_company_id'': company_id}" invisible="not picking_type_entire_packs" readonly="state == ''done''"/>
                            <button class="btn-secondary float-end" name="action_put_in_pack" type="object" string="Put in Pack" invisible="state in (''draft'', ''done'', ''cancel'')" groups="stock.group_tracking_lot" data-hotkey="shift+g"/>
                        </page>
                        <page string="Additional Info" name="extra">
                            <group>
                                <group string="Other Information" name="other_infos">
                                    <field name="picking_type_code" invisible="1"/>
                                    <field name="move_type" invisible="picking_type_code == ''incoming''" readonly="state in [''cancel'', ''done'']"/>
                                    <field name="user_id" widget="many2one_avatar_user" domain="[(''share'', ''='', False)]" readonly="state in [''cancel'', ''done'']"/>
                                    <field name="group_id" groups="base.group_no_one"/>
                                    <field name="company_id" groups="base.group_multi_company" options="{''no_create'': True}" force_save="1"/>
                                </group>
                            </group>
                        </page>
                        <page string="Note" name="note">
                            <field name="note" string="Note" placeholder="Add an internal note that will be printed on the Picking Operations sheet"/>
                        </page>
                    </notebook>
                </sheet>
                <div class="oe_chatter">
                    <field name="message_follower_ids"/>
                    <field name="activity_ids"/>
                    <field name="message_ids"/>
                </div>
                </form>
            ', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (1051, 16, NULL, 1, 1, 'stock.picking.internal.search', 'stock.picking', NULL, 'search', 'stock/views/stock_picking_views.xml', 'primary', '{"en_US": "<search string=\"Picking Lists\">\n                    <field name=\"name\" string=\"Transfer\" filter_domain=\"[''|'', (''name'', ''ilike'', self), (''origin'', ''ilike'', self)]\"/>\n                    <field name=\"partner_id\" filter_domain=\"[(''partner_id'', ''child_of'', self)]\"/>\n                    <field name=\"origin\"/>\n                    <field name=\"product_id\"/>\n                    <field name=\"picking_type_id\"/>\n                    <field name=\"move_line_ids\" string=\"Package\" filter_domain=\"[''|'', (''move_line_ids.package_id.name'', ''ilike'', self), (''move_line_ids.result_package_id.name'', ''ilike'', self)]\" groups=\"stock.group_tracking_lot\"/>\n                    <field name=\"lot_id\" groups=\"stock.group_production_lot\"/>\n                    <filter name=\"to_do_transfers\" string=\"To Do\" domain=\"[''&amp;'',(''user_id'', ''in'', [uid, False]),(''state'',''not in'',[''done'',''cancel''])]\"/>\n                    <filter name=\"my_transfers\" string=\"My Transfers\" domain=\"[(''user_id'', ''='', uid)]\"/>\n                    <filter string=\"Starred\" name=\"starred\" domain=\"[(''priority'', ''='', ''1'')]\"/>\n                    <separator/>\n                    <filter name=\"draft\" string=\"Draft\" domain=\"[(''state'', ''='', ''draft'')]\" help=\"Draft Moves\"/>\n                    <filter name=\"waiting\" string=\"Waiting\" domain=\"[(''state'', ''in'', (''confirmed'', ''waiting''))]\" help=\"Waiting Moves\"/>\n                    <filter name=\"available\" string=\"Ready\" domain=\"[(''state'', ''='', ''assigned'')]\" help=\"Assigned Moves\"/>\n                    <separator/>\n                    <filter name=\"reception\" string=\"Receipts\" domain=\"[(''picking_type_code'', ''='', ''incoming'')]\"/>\n                    <filter name=\"delivery\" string=\"Deliveries\" domain=\"[(''picking_type_code'', ''='', ''outgoing'')]\"/>\n                    <filter name=\"internal\" string=\"Internal\" domain=\"[(''picking_type_code'', ''='', ''internal'')]\"/>\n                    <separator/>\n                    <filter name=\"late\" string=\"Late\" help=\"Deadline exceed or/and by the scheduled\" domain=\"[(''state'', ''in'', (''assigned'', ''waiting'', ''confirmed'')), ''|'', ''|'', (''has_deadline_issue'', ''='', True), (''date_deadline'', ''&lt;'', current_date), (''scheduled_date'', ''&lt;'', current_date)]\"/>\n                    <filter string=\"Planning Issues\" name=\"planning_issues\" help=\"Transfers that are late on scheduled time or one of pickings will be late\" domain=\"[''|'', (''delay_alert_date'', ''!='', False), ''&amp;'', (''scheduled_date'',''&lt;'', time.strftime(''%Y-%m-%d %H:%M:%S'')), (''state'', ''in'', (''assigned'', ''waiting'', ''confirmed''))]\"/>\n                    <separator/>\n                    <filter name=\"backorder\" string=\"Backorders\" domain=\"[(''backorder_id'', ''!='', False), (''state'', ''in'', (''assigned'', ''waiting'', ''confirmed''))]\" help=\"Remaining parts of picking partially processed\"/>\n                    <separator/>\n                    <filter invisible=\"1\" string=\"Late Activities\" name=\"activities_overdue\" domain=\"[(''my_activity_date_deadline'', ''&lt;'', context_today().strftime(''%Y-%m-%d''))]\" help=\"Show all records which has next action date is before today\"/>\n                    <filter invisible=\"1\" string=\"Today Activities\" name=\"activities_today\" domain=\"[(''my_activity_date_deadline'', ''='', context_today().strftime(''%Y-%m-%d''))]\"/>\n                    <filter invisible=\"1\" string=\"Future Activities\" name=\"activities_upcoming_all\" domain=\"[(''my_activity_date_deadline'', ''&gt;'', context_today().strftime(''%Y-%m-%d''))]\"/>\n                    <separator/>\n                    <filter string=\"Warnings\" name=\"activities_exception\" domain=\"[(''activity_exception_decoration'', ''!='', False)]\"/>\n                    <group expand=\"0\" string=\"Group By\">\n                        <filter string=\"Status\" name=\"status\" domain=\"[]\" context=\"{''group_by'': ''state''}\"/>\n                        <filter string=\"Scheduled Date\" name=\"expected_date\" domain=\"[]\" context=\"{''group_by'': ''scheduled_date''}\"/>\n                        <filter string=\"Source Document\" name=\"origin\" domain=\"[]\" context=\"{''group_by'': ''origin''}\"/>\n                        <filter string=\"Operation Type\" name=\"picking_type\" domain=\"[]\" context=\"{''group_by'': ''picking_type_id''}\"/>\n                    </group>\n                </search>"}', '<?xml version="1.0"?>
<search string="Picking Lists">
                    <field name="name" string="Transfer" filter_domain="[''|'', (''name'', ''ilike'', self), (''origin'', ''ilike'', self)]"/>
                    <field name="partner_id" filter_domain="[(''partner_id'', ''child_of'', self)]"/>
                    <field name="origin"/>
                    <field name="product_id"/>
                    <field name="picking_type_id"/>
                    <field name="move_line_ids" string="Package" filter_domain="[''|'', (''move_line_ids.package_id.name'', ''ilike'', self), (''move_line_ids.result_package_id.name'', ''ilike'', self)]" groups="stock.group_tracking_lot"/>
                    <field name="lot_id" groups="stock.group_production_lot"/>
                    <filter name="to_do_transfers" string="To Do" domain="[''&amp;'',(''user_id'', ''in'', [uid, False]),(''state'',''not in'',[''done'',''cancel''])]"/>
                    <filter name="my_transfers" string="My Transfers" domain="[(''user_id'', ''='', uid)]"/>
                    <filter string="Starred" name="starred" domain="[(''priority'', ''='', ''1'')]"/>
                    <separator/>
                    <filter name="draft" string="Draft" domain="[(''state'', ''='', ''draft'')]" help="Draft Moves"/>
                    <filter name="waiting" string="Waiting" domain="[(''state'', ''in'', (''confirmed'', ''waiting''))]" help="Waiting Moves"/>
                    <filter name="available" string="Ready" domain="[(''state'', ''='', ''assigned'')]" help="Assigned Moves"/>
                    <separator/>
                    <filter name="reception" string="Receipts" domain="[(''picking_type_code'', ''='', ''incoming'')]"/>
                    <filter name="delivery" string="Deliveries" domain="[(''picking_type_code'', ''='', ''outgoing'')]"/>
                    <filter name="internal" string="Internal" domain="[(''picking_type_code'', ''='', ''internal'')]"/>
                    <separator/>
                    <filter name="late" string="Late" help="Deadline exceed or/and by the scheduled" domain="[(''state'', ''in'', (''assigned'', ''waiting'', ''confirmed'')), ''|'', ''|'', (''has_deadline_issue'', ''='', True), (''date_deadline'', ''&lt;'', current_date), (''scheduled_date'', ''&lt;'', current_date)]"/>
                    <filter string="Planning Issues" name="planning_issues" help="Transfers that are late on scheduled time or one of pickings will be late" domain="[''|'', (''delay_alert_date'', ''!='', False), ''&amp;'', (''scheduled_date'',''&lt;'', time.strftime(''%Y-%m-%d %H:%M:%S'')), (''state'', ''in'', (''assigned'', ''waiting'', ''confirmed''))]"/>
                    <separator/>
                    <filter name="backorder" string="Backorders" domain="[(''backorder_id'', ''!='', False), (''state'', ''in'', (''assigned'', ''waiting'', ''confirmed''))]" help="Remaining parts of picking partially processed"/>
                    <separator/>
                    <filter invisible="1" string="Late Activities" name="activities_overdue" domain="[(''my_activity_date_deadline'', ''&lt;'', context_today().strftime(''%Y-%m-%d''))]" help="Show all records which has next action date is before today"/>
                    <filter invisible="1" string="Today Activities" name="activities_today" domain="[(''my_activity_date_deadline'', ''='', context_today().strftime(''%Y-%m-%d''))]"/>
                    <filter invisible="1" string="Future Activities" name="activities_upcoming_all" domain="[(''my_activity_date_deadline'', ''&gt;'', context_today().strftime(''%Y-%m-%d''))]"/>
                    <separator/>
                    <filter string="Warnings" name="activities_exception" domain="[(''activity_exception_decoration'', ''!='', False)]"/>
                    <group expand="0" string="Group By">
                        <filter string="Status" name="status" domain="[]" context="{''group_by'': ''state''}"/>
                        <filter string="Scheduled Date" name="expected_date" domain="[]" context="{''group_by'': ''scheduled_date''}"/>
                        <filter string="Source Document" name="origin" domain="[]" context="{''group_by'': ''origin''}"/>
                        <filter string="Operation Type" name="picking_type" domain="[]" context="{''group_by'': ''picking_type_id''}"/>
                    </group>
                </search>
            ', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (1052, 16, NULL, 1, 1, 'stock.picking.type.filter', 'stock.picking.type', NULL, 'search', 'stock/views/stock_picking_type_views.xml', 'primary', '{"en_US": "<search string=\"Operation Type\">\n                <field name=\"name\"/>\n                <field name=\"warehouse_id\"/>\n                <filter string=\"Archived\" name=\"inactive\" domain=\"[(''active'',''='',False)]\"/>\n                <group expand=\"0\" string=\"Group By\">\n                    <filter string=\"Type of Operation\" name=\"groupby_code\" domain=\"[]\" context=\"{''group_by'': ''code''}\"/>\n                    <filter string=\"Warehouse\" name=\"groupby_warehouse_id\" domain=\"[]\" context=\"{''group_by'': ''warehouse_id''}\"/>\n                </group>\n            </search>"}', '<?xml version="1.0"?>
<search string="Operation Type">
                <field name="name"/>
                <field name="warehouse_id"/>
                <filter string="Archived" name="inactive" domain="[(''active'',''='',False)]"/>
                <group expand="0" string="Group By">
                    <filter string="Type of Operation" name="groupby_code" domain="[]" context="{''group_by'': ''code''}"/>
                    <filter string="Warehouse" name="groupby_warehouse_id" domain="[]" context="{''group_by'': ''warehouse_id''}"/>
                </group>
            </search>
        ', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (1053, 16, NULL, 1, 1, 'Operation types', 'stock.picking.type', NULL, 'tree', 'stock/views/stock_picking_type_views.xml', 'primary', '{"en_US": "<tree string=\"Operation Types\">\n                <field name=\"sequence\" widget=\"handle\"/>\n                <field name=\"name\"/>\n                <field name=\"active\" column_invisible=\"True\"/>\n                <field name=\"warehouse_id\" groups=\"stock.group_stock_multi_warehouses\"/>\n                <field name=\"sequence_id\" groups=\"base.group_no_one\"/>\n                <field name=\"company_id\" groups=\"base.group_multi_company\"/>\n                <field name=\"company_id\" groups=\"!base.group_multi_company\" column_invisible=\"True\"/>\n            </tree>"}', '<?xml version="1.0"?>
<tree string="Operation Types">
                <field name="sequence" widget="handle"/>
                <field name="name"/>
                <field name="active" column_invisible="True"/>
                <field name="warehouse_id" groups="stock.group_stock_multi_warehouses"/>
                <field name="sequence_id" groups="base.group_no_one"/>
                <field name="company_id" groups="base.group_multi_company"/>
                <field name="company_id" groups="!base.group_multi_company" column_invisible="True"/>
            </tree>
        ', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (1054, 16, NULL, 1, 1, 'Operation Types', 'stock.picking.type', NULL, 'form', 'stock/views/stock_picking_type_views.xml', 'primary', '{"en_US": "<form string=\"Operation Types\">\n                <sheet>\n                    <widget name=\"web_ribbon\" title=\"Archived\" bg_color=\"text-bg-danger\" invisible=\"active\"/>\n                    <label for=\"name\"/>\n                    <h1><field name=\"name\" placeholder=\"e.g. Receptions\"/></h1>\n                    <notebook>\n                        <page name=\"general\" string=\"General\">\n                            <group name=\"first\">\n                                <group>\n                                    <field name=\"code\"/>\n                                    <field name=\"active\" invisible=\"1\"/>\n                                    <field name=\"company_id\" invisible=\"1\"/>\n                                    <field name=\"hide_reservation_method\" invisible=\"1\"/>\n                                    <field name=\"show_picking_type\" invisible=\"1\"/>\n                                    <field name=\"sequence_id\" groups=\"base.group_no_one\"/>\n                                    <field name=\"sequence_code\"/>\n                                    <field name=\"warehouse_id\" groups=\"stock.group_stock_multi_warehouses\" force_save=\"1\"/>\n                                    <field name=\"reservation_method\" invisible=\"hide_reservation_method\" widget=\"radio\"/>\n                                    <label for=\"reservation_days_before\" string=\"Reserve before scheduled date\" invisible=\"code == ''incoming'' or reservation_method != ''by_date''\"/>\n                                    <div class=\"o_row\" invisible=\"code == ''incoming'' or reservation_method != ''by_date''\">\n                                        <span><field name=\"reservation_days_before\" style=\"width: 23px;\"/> days before/</span>\n                                        <span><field name=\"reservation_days_before_priority\" style=\"width: 23px;\"/> days before when starred</span>\n                                    </div>\n                                    <field name=\"auto_show_reception_report\" invisible=\"code not in [''incoming'', ''internal'']\" groups=\"stock.group_reception_report\"/>\n                                </group>\n                                <group>\n                                    <field name=\"company_id\" groups=\"base.group_multi_company\" options=\"{''no_create'': True}\"/>\n                                    <field invisible=\"code not in [''incoming'', ''outgoing'', ''internal'']\" name=\"return_picking_type_id\" string=\"Returns Type\"/>\n                                    <field name=\"default_location_return_id\" invisible=\"code not in [''incoming'', ''outgoing'', ''internal'']\" groups=\"stock.group_stock_multi_locations\"/>\n                                    <field name=\"create_backorder\"/>\n                                </group>\n                            </group>\n                            <group name=\"second\">\n                                <group invisible=\"code not in [''incoming'', ''outgoing'', ''internal'']\" string=\"Lots/Serial Numbers\" groups=\"stock.group_production_lot\" name=\"stock_picking_type_lot\">\n                                    <field name=\"use_create_lots\" string=\"Create New\"/>\n                                    <field name=\"use_existing_lots\" string=\"Use Existing ones\"/>\n                                </group>\n                                <group invisible=\"code not in [''incoming'', ''outgoing'', ''internal'']\" string=\"Packages\" groups=\"stock.group_tracking_lot\">\n                                    <field name=\"show_entire_packs\"/>\n                                </group>\n                                <!-- As this group will be hidden without multi_loccation, you will not be able to create a\n                                    picking type with the code ''Internal'', which make sense, but as the field ''code'' on picking\n                                    types can''t be partially hidden, you can still select the code internal in the form view -->\n                                <group string=\"Locations\" groups=\"stock.group_stock_multi_locations\" name=\"locations\">\n                                    <field name=\"default_location_src_id\" options=\"{''no_create'': True}\" required=\"code in (''internal'', ''outgoing'')\"/>\n                                    <field name=\"default_location_dest_id\" options=\"{''no_create'': True}\" required=\"code in (''internal'', ''incoming'')\"/>\n                                </group>\n                            </group>\n                        </page>\n                        <page name=\"hardware\" string=\"Hardware\" invisible=\"code not in [''incoming'', ''outgoing'', ''internal'']\">\n                            <group name=\"auto_print\">\n                                <group string=\"Print on Validation\">\n                                    <field name=\"auto_print_delivery_slip\" string=\"Delivery Slip\"/>\n                                    <field name=\"auto_print_return_slip\" string=\"Return Slip\"/>\n                                    <label for=\"auto_print_product_labels\" string=\"Product Labels\"/>\n                                    <div class=\"o_row\">\n                                        <field name=\"auto_print_product_labels\" string=\"Product Labels\"/>\n                                        <label for=\"product_label_format\" string=\"Print label as:\" invisible=\"not auto_print_product_labels\" class=\"fw-bold\"/>\n                                        <field name=\"product_label_format\" invisible=\"not auto_print_product_labels\"/>\n                                    </div>\n                                    <label for=\"auto_print_lot_labels\" string=\"Lot/SN Labels\" groups=\"stock.group_production_lot\"/>\n                                    <div class=\"o_row\" groups=\"stock.group_production_lot\">\n                                        <field name=\"auto_print_lot_labels\" string=\"Lot/SN Labels\"/>\n                                        <label for=\"lot_label_format\" string=\"Print label as:\" invisible=\"not auto_print_lot_labels\" class=\"fw-bold\"/>\n                                        <field name=\"lot_label_format\" invisible=\"not auto_print_lot_labels\"/>\n                                    </div>\n                                    <field name=\"auto_print_reception_report\" string=\"Reception Report\" invisible=\"code == ''outgoing''\" groups=\"stock.group_reception_report\"/>\n                                    <field name=\"auto_print_reception_report_labels\" string=\"Reception Report Labels\" invisible=\"code == ''outgoing''\" groups=\"stock.group_reception_report\"/>\n                                    <field name=\"auto_print_packages\" string=\"Package Content\" groups=\"stock.group_tracking_lot\"/>\n                                </group>\n                                <group string=\"\">\n                                    <div colspan=\"2\">\n                                        Odoo opens a PDF preview by default. If you (Enterprise users only) want to print instantly,\n                                        install the IoT App on a computer that is on the same local network as the\n                                        barcode operator and configure the routing of the reports.\n                                        <a href=\"https://www.odoo.com/documentation/17.0/applications/productivity/iot/devices/printer.html\" target=\"_blank\" class=\"fa fa-arrow-right\">\n                                            Documentation\n                                        </a>\n                                    </div>\n                                </group>\n                                <group string=\"Print on &quot;Put in Pack&quot;\" groups=\"stock.group_tracking_lot\">\n                                    <label for=\"auto_print_package_label\" string=\"Package Label\"/>\n                                    <div class=\"o_row\">\n                                        <field name=\"auto_print_package_label\" string=\"Package Label\"/>\n                                        <label for=\"package_label_to_print\" string=\"Print label as:\" invisible=\"not auto_print_package_label\" class=\"fw-bold\"/>\n                                        <field name=\"package_label_to_print\" invisible=\"not auto_print_package_label\"/>\n                                    </div>\n                                </group>\n                            </group>\n                        </page>\n                    </notebook>\n                </sheet>\n            </form>"}', '<?xml version="1.0"?>
<form string="Operation Types">
                <sheet>
                    <widget name="web_ribbon" title="Archived" bg_color="text-bg-danger" invisible="active"/>
                    <label for="name"/>
                    <h1><field name="name" placeholder="e.g. Receptions"/></h1>
                    <notebook>
                        <page name="general" string="General">
                            <group name="first">
                                <group>
                                    <field name="code"/>
                                    <field name="active" invisible="1"/>
                                    <field name="company_id" invisible="1"/>
                                    <field name="hide_reservation_method" invisible="1"/>
                                    <field name="show_picking_type" invisible="1"/>
                                    <field name="sequence_id" groups="base.group_no_one"/>
                                    <field name="sequence_code"/>
                                    <field name="warehouse_id" groups="stock.group_stock_multi_warehouses" force_save="1"/>
                                    <field name="reservation_method" invisible="hide_reservation_method" widget="radio"/>
                                    <label for="reservation_days_before" string="Reserve before scheduled date" invisible="code == ''incoming'' or reservation_method != ''by_date''"/>
                                    <div class="o_row" invisible="code == ''incoming'' or reservation_method != ''by_date''">
                                        <span><field name="reservation_days_before" style="width: 23px;"/> days before/</span>
                                        <span><field name="reservation_days_before_priority" style="width: 23px;"/> days before when starred</span>
                                    </div>
                                    <field name="auto_show_reception_report" invisible="code not in [''incoming'', ''internal'']" groups="stock.group_reception_report"/>
                                </group>
                                <group>
                                    <field name="company_id" groups="base.group_multi_company" options="{''no_create'': True}"/>
                                    <field invisible="code not in [''incoming'', ''outgoing'', ''internal'']" name="return_picking_type_id" string="Returns Type"/>
                                    <field name="default_location_return_id" invisible="code not in [''incoming'', ''outgoing'', ''internal'']" groups="stock.group_stock_multi_locations"/>
                                    <field name="create_backorder"/>
                                </group>
                            </group>
                            <group name="second">
                                <group invisible="code not in [''incoming'', ''outgoing'', ''internal'']" string="Lots/Serial Numbers" groups="stock.group_production_lot" name="stock_picking_type_lot">
                                    <field name="use_create_lots" string="Create New"/>
                                    <field name="use_existing_lots" string="Use Existing ones"/>
                                </group>
                                <group invisible="code not in [''incoming'', ''outgoing'', ''internal'']" string="Packages" groups="stock.group_tracking_lot">
                                    <field name="show_entire_packs"/>
                                </group>
                                <!-- As this group will be hidden without multi_loccation, you will not be able to create a
                                    picking type with the code ''Internal'', which make sense, but as the field ''code'' on picking
                                    types can''t be partially hidden, you can still select the code internal in the form view -->
                                <group string="Locations" groups="stock.group_stock_multi_locations" name="locations">
                                    <field name="default_location_src_id" options="{''no_create'': True}" required="code in (''internal'', ''outgoing'')"/>
                                    <field name="default_location_dest_id" options="{''no_create'': True}" required="code in (''internal'', ''incoming'')"/>
                                </group>
                            </group>
                        </page>
                        <page name="hardware" string="Hardware" invisible="code not in [''incoming'', ''outgoing'', ''internal'']">
                            <group name="auto_print">
                                <group string="Print on Validation">
                                    <field name="auto_print_delivery_slip" string="Delivery Slip"/>
                                    <field name="auto_print_return_slip" string="Return Slip"/>
                                    <label for="auto_print_product_labels" string="Product Labels"/>
                                    <div class="o_row">
                                        <field name="auto_print_product_labels" string="Product Labels"/>
                                        <label for="product_label_format" string="Print label as:" invisible="not auto_print_product_labels" class="fw-bold"/>
                                        <field name="product_label_format" invisible="not auto_print_product_labels"/>
                                    </div>
                                    <label for="auto_print_lot_labels" string="Lot/SN Labels" groups="stock.group_production_lot"/>
                                    <div class="o_row" groups="stock.group_production_lot">
                                        <field name="auto_print_lot_labels" string="Lot/SN Labels"/>
                                        <label for="lot_label_format" string="Print label as:" invisible="not auto_print_lot_labels" class="fw-bold"/>
                                        <field name="lot_label_format" invisible="not auto_print_lot_labels"/>
                                    </div>
                                    <field name="auto_print_reception_report" string="Reception Report" invisible="code == ''outgoing''" groups="stock.group_reception_report"/>
                                    <field name="auto_print_reception_report_labels" string="Reception Report Labels" invisible="code == ''outgoing''" groups="stock.group_reception_report"/>
                                    <field name="auto_print_packages" string="Package Content" groups="stock.group_tracking_lot"/>
                                </group>
                                <group string="">
                                    <div colspan="2">
                                        Odoo opens a PDF preview by default. If you (Enterprise users only) want to print instantly,
                                        install the IoT App on a computer that is on the same local network as the
                                        barcode operator and configure the routing of the reports.
                                        <a href="https://www.odoo.com/documentation/17.0/applications/productivity/iot/devices/printer.html" target="_blank" class="fa fa-arrow-right">
                                            Documentation
                                        </a>
                                    </div>
                                </group>
                                <group string="Print on &quot;Put in Pack&quot;" groups="stock.group_tracking_lot">
                                    <label for="auto_print_package_label" string="Package Label"/>
                                    <div class="o_row">
                                        <field name="auto_print_package_label" string="Package Label"/>
                                        <label for="package_label_to_print" string="Print label as:" invisible="not auto_print_package_label" class="fw-bold"/>
                                        <field name="package_label_to_print" invisible="not auto_print_package_label"/>
                                    </div>
                                </group>
                            </group>
                        </page>
                    </notebook>
                </sheet>
            </form>
        ', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (1058, 8, NULL, 1, 1, 'stock.move.tree', 'stock.move', NULL, 'tree', 'stock/views/stock_move_views.xml', 'primary', '{"en_US": "<tree string=\"Moves\" create=\"0\" default_order=\"date desc\" duplicate=\"0\">\n                    <field name=\"date\" groups=\"base.group_no_one\" decoration-danger=\"(state not in (''cancel'',''done'')) and date &gt; current_date\"/>\n                    <field name=\"reference\"/>\n                    <field name=\"picking_type_id\" column_invisible=\"True\"/>\n                    <field name=\"location_usage\" column_invisible=\"True\"/>\n                    <field name=\"location_dest_usage\" column_invisible=\"True\"/>\n                    <field name=\"product_id\" readonly=\"state == ''done''\"/>\n                    <field name=\"location_id\" options=\"{''no_create'': True}\" string=\"From\" decoration-muted=\"location_usage not in (''internal'',''transit'')\"/>\n                    <field name=\"location_dest_id\" options=\"{''no_create'': True}\" string=\"To\" decoration-muted=\"location_dest_usage not in (''internal'',''transit'')\"/>\n                    <field name=\"product_packaging_id\" groups=\"product.group_stock_packaging\" optional=\"hide\" context=\"{''default_product_id'': product_id}\" readonly=\"not product_id\"/>\n                    <field name=\"product_uom_qty\" sum=\"Total Demand\" readonly=\"state == ''done''\"/>\n                    <field name=\"quantity\" string=\"Quantity\" sum=\"Total Quantity\" decoration-danger=\"(location_usage in (''internal'',''transit'')) and (location_dest_usage not in (''internal'',''transit''))\" decoration-success=\"(location_usage not in (''internal'',''transit'')) and (location_dest_usage in (''internal'',''transit''))\"/>\n                    <field name=\"product_uom\" options=\"{''no_open'': True, ''no_create'': True}\" string=\"Unit\" groups=\"uom.group_uom\"/>\n                    <field name=\"company_id\" groups=\"base.group_multi_company\"/>\n                    <field name=\"state\" widget=\"badge\" optional=\"show\" decoration-danger=\"state==''cancel''\" decoration-info=\"state== ''assigned''\" decoration-muted=\"state == ''draft''\" decoration-success=\"state == ''done''\" decoration-warning=\"state not in (''draft'',''cancel'',''done'',''assigned'')\"/>\n                </tree>"}', '<?xml version="1.0"?>
<tree string="Moves" create="0" default_order="date desc" duplicate="0">
                    <field name="date" groups="base.group_no_one" decoration-danger="(state not in (''cancel'',''done'')) and date &gt; current_date"/>
                    <field name="reference"/>
                    <field name="picking_type_id" column_invisible="True"/>
                    <field name="location_usage" column_invisible="True"/>
                    <field name="location_dest_usage" column_invisible="True"/>
                    <field name="product_id" readonly="state == ''done''"/>
                    <field name="location_id" options="{''no_create'': True}" string="From" decoration-muted="location_usage not in (''internal'',''transit'')"/>
                    <field name="location_dest_id" options="{''no_create'': True}" string="To" decoration-muted="location_dest_usage not in (''internal'',''transit'')"/>
                    <field name="product_packaging_id" groups="product.group_stock_packaging" optional="hide" context="{''default_product_id'': product_id}" readonly="not product_id"/>
                    <field name="product_uom_qty" sum="Total Demand" readonly="state == ''done''"/>
                    <field name="quantity" string="Quantity" sum="Total Quantity" decoration-danger="(location_usage in (''internal'',''transit'')) and (location_dest_usage not in (''internal'',''transit''))" decoration-success="(location_usage not in (''internal'',''transit'')) and (location_dest_usage in (''internal'',''transit''))"/>
                    <field name="product_uom" options="{''no_open'': True, ''no_create'': True}" string="Unit" groups="uom.group_uom"/>
                    <field name="company_id" groups="base.group_multi_company"/>
                    <field name="state" widget="badge" optional="show" decoration-danger="state==''cancel''" decoration-info="state== ''assigned''" decoration-muted="state == ''draft''" decoration-success="state == ''done''" decoration-warning="state not in (''draft'',''cancel'',''done'',''assigned'')"/>
                </tree>
            ', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (1059, 50, NULL, 1, 1, 'stock.picking.move.tree', 'stock.move', NULL, 'tree', 'stock/views/stock_move_views.xml', 'primary', '{"en_US": "<tree decoration-muted=\"scrapped == True or state == ''cancel'' or (state == ''done'' and is_locked == True)\" string=\"Stock Moves\" editable=\"bottom\">\n                    <field name=\"company_id\" column_invisible=\"True\"/>\n                    <field name=\"name\" column_invisible=\"True\"/>\n                    <field name=\"date\" column_invisible=\"True\"/>\n                    <field name=\"state\" readonly=\"0\" column_invisible=\"True\"/>\n                    <field name=\"picking_type_id\" column_invisible=\"True\"/>\n                    <field name=\"location_id\" column_invisible=\"True\"/>\n                    <field name=\"location_dest_id\" column_invisible=\"True\"/>\n                    <field name=\"scrapped\" column_invisible=\"True\"/>\n                    <field name=\"picking_code\" column_invisible=\"True\"/>\n                    <field name=\"product_type\" column_invisible=\"True\"/>\n                    <field name=\"show_details_visible\" column_invisible=\"True\"/>\n                    <field name=\"additional\" column_invisible=\"True\"/>\n                    <field name=\"move_lines_count\" column_invisible=\"True\"/>\n                    <field name=\"is_locked\" column_invisible=\"True\"/>\n                    <field name=\"product_uom_category_id\" column_invisible=\"True\"/>\n                    <field name=\"product_id\" required=\"1\" readonly=\"(state != ''draft'' and not additional) or move_lines_count &gt; 0\"/>\n                    <field name=\"is_initial_demand_editable\" column_invisible=\"True\"/>\n                    <field name=\"is_quantity_done_editable\" column_invisible=\"True\"/>\n                    <field name=\"product_uom_qty\" string=\"Demand\" readonly=\"not is_initial_demand_editable\"/>\n                    <field name=\"quantity\" string=\"Quantity\" readonly=\"not is_quantity_done_editable\"/>\n                    <field name=\"picked\"/>\n                    <field name=\"product_uom\" readonly=\"state != ''draft'' and id\" options=\"{''no_open'': True, ''no_create'': True}\" string=\"Unit of Measure\" groups=\"uom.group_uom\"/>\n                </tree>"}', '<?xml version="1.0"?>
<tree decoration-muted="scrapped == True or state == ''cancel'' or (state == ''done'' and is_locked == True)" string="Stock Moves" editable="bottom">
                    <field name="company_id" column_invisible="True"/>
                    <field name="name" column_invisible="True"/>
                    <field name="date" column_invisible="True"/>
                    <field name="state" readonly="0" column_invisible="True"/>
                    <field name="picking_type_id" column_invisible="True"/>
                    <field name="location_id" column_invisible="True"/>
                    <field name="location_dest_id" column_invisible="True"/>
                    <field name="scrapped" column_invisible="True"/>
                    <field name="picking_code" column_invisible="True"/>
                    <field name="product_type" column_invisible="True"/>
                    <field name="show_details_visible" column_invisible="True"/>
                    <field name="additional" column_invisible="True"/>
                    <field name="move_lines_count" column_invisible="True"/>
                    <field name="is_locked" column_invisible="True"/>
                    <field name="product_uom_category_id" column_invisible="True"/>
                    <field name="product_id" required="1" readonly="(state != ''draft'' and not additional) or move_lines_count &gt; 0"/>
                    <field name="is_initial_demand_editable" column_invisible="True"/>
                    <field name="is_quantity_done_editable" column_invisible="True"/>
                    <field name="product_uom_qty" string="Demand" readonly="not is_initial_demand_editable"/>
                    <field name="quantity" string="Quantity" readonly="not is_quantity_done_editable"/>
                    <field name="picked"/>
                    <field name="product_uom" readonly="state != ''draft'' and id" options="{''no_open'': True, ''no_create'': True}" string="Unit of Measure" groups="uom.group_uom"/>
                </tree>
            ', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (1060, 10, NULL, 1, 1, 'stock.move.kanban', 'stock.move', NULL, 'kanban', 'stock/views/stock_move_views.xml', 'primary', '{"en_US": "<kanban class=\"o_kanban_mobile\">\n                    <field name=\"product_id\"/>\n                    <field name=\"show_details_visible\"/>\n                    <field name=\"product_uom_qty\"/>\n                    <field name=\"product_qty\" readonly=\"1\" force_save=\"0\"/>\n                    <field name=\"quantity\"/>\n                    <field name=\"is_inventory\"/>\n                    <field name=\"state\"/>\n                    <field name=\"name\"/>\n                    <field name=\"product_uom\"/>\n                    <field name=\"location_id\"/>\n                    <field name=\"location_dest_id\"/>\n                    <templates>\n                        <t t-name=\"kanban-box\">\n                            <div t-attf-class=\"oe_kanban_global_click\">\n                                <div class=\"o_kanban_record_top\">\n                                    <div class=\"o_kanban_record_headings\">\n                                        <strong class=\"o_kanban_record_title\"><span><field name=\"product_id\" readonly=\"state == ''done''\"/></span></strong>\n                                    </div>\n                                </div>\n                                <div class=\"o_kanban_record_body\">\n                                    <div invisible=\"not is_inventory\">\n                                        <span>Initial Demand <field name=\"product_uom_qty\" readonly=\"state == ''done''\"/></span><br/>\n                                        <span>Quantity <field name=\"quantity\"/></span>\n                                    </div>\n                                    <div invisible=\"is_inventory\">\n                                        <span>\n                                            Quantity <field name=\"quantity\"/> /\n                                            <field name=\"product_uom_qty\" readonly=\"state != ''draft''\"/>\n                                            <field name=\"product_uom\" groups=\"uom.group_uom\" class=\"ms-1\"/>\n                                        </span>\n                                    </div>\n                                </div>\n                            </div>\n                        </t>\n                    </templates>\n                </kanban>"}', '<?xml version="1.0"?>
<kanban class="o_kanban_mobile">
                    <field name="product_id"/>
                    <field name="show_details_visible"/>
                    <field name="product_uom_qty"/>
                    <field name="product_qty" readonly="1" force_save="0"/>
                    <field name="quantity"/>
                    <field name="is_inventory"/>
                    <field name="state"/>
                    <field name="name"/>
                    <field name="product_uom"/>
                    <field name="location_id"/>
                    <field name="location_dest_id"/>
                    <templates>
                        <t t-name="kanban-box">
                            <div t-attf-class="oe_kanban_global_click">
                                <div class="o_kanban_record_top">
                                    <div class="o_kanban_record_headings">
                                        <strong class="o_kanban_record_title"><span><field name="product_id" readonly="state == ''done''"/></span></strong>
                                    </div>
                                </div>
                                <div class="o_kanban_record_body">
                                    <div invisible="not is_inventory">
                                        <span>Initial Demand <field name="product_uom_qty" readonly="state == ''done''"/></span><br/>
                                        <span>Quantity <field name="quantity"/></span>
                                    </div>
                                    <div invisible="is_inventory">
                                        <span>
                                            Quantity <field name="quantity"/> /
                                            <field name="product_uom_qty" readonly="state != ''draft''"/>
                                            <field name="product_uom" groups="uom.group_uom" class="ms-1"/>
                                        </span>
                                    </div>
                                </div>
                            </div>
                        </t>
                    </templates>
                </kanban>
            ', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (1061, 1000, NULL, 1, 1, 'stock.move.operations.form', 'stock.move', NULL, 'form', 'stock/views/stock_move_views.xml', 'primary', '{"en_US": "<form string=\"Move Detail\">\n                    <field name=\"sequence\" invisible=\"1\"/>\n                    <field name=\"company_id\" invisible=\"1\"/>\n                    <field name=\"state\" invisible=\"1\"/>\n                    <field name=\"location_id\" invisible=\"1\"/>\n                    <field name=\"location_dest_id\" invisible=\"1\"/>\n                    <field name=\"picking_id\" invisible=\"1\" readonly=\"state == ''done''\"/>\n                    <field name=\"picking_type_id\" invisible=\"1\"/>\n                    <field name=\"is_locked\" invisible=\"1\"/>\n                    <field name=\"picking_type_entire_packs\" invisible=\"1\"/>\n                    <field name=\"display_assign_serial\" invisible=\"1\"/>\n                    <field name=\"display_import_lot\" invisible=\"1\"/>\n                    <field name=\"product_uom_category_id\" invisible=\"1\"/>\n                    <field name=\"product_uom\" invisible=\"1\" groups=\"!uom.group_uom\"/>\n                    <field name=\"picking_code\" invisible=\"1\"/>\n                    <field name=\"has_tracking\" invisible=\"1\"/>\n                    <field name=\"show_reserved\" invisible=\"1\"/>\n                    <field name=\"show_quant\" invisible=\"1\"/>\n                    <field name=\"show_lots_text\" invisible=\"1\"/>\n                    <field name=\"show_lots_m2o\" invisible=\"1\"/>\n                    <field name=\"quantity\" invisible=\"1\"/>\n                    <group>\n                        <group>\n                            <field name=\"product_id\" readonly=\"id or move_line_ids\"/>\n                            <label for=\"product_uom_qty\"/>\n                            <div class=\"o_row\">\n                                <span><field name=\"product_uom_qty\" readonly=\"state != ''draft''\" nolabel=\"1\"/></span>\n                                <span><field name=\"product_uom\" groups=\"uom.group_uom\" readonly=\"state != ''draft''\" nolabel=\"1\" options=\"{''no_open'': True}\"/></span>\n                            </div>\n                        </group>\n                        <group/>\n                    </group>\n                    <div class=\"d-flex\">\n                        <widget class=\"btn btn-link btn-group\" name=\"generate_serials\" invisible=\"not display_assign_serial\"/>\n                        <widget class=\"btn btn-link btn-group\" name=\"import_lots\" invisible=\"not display_import_lot\"/>\n                    </div>\n                    <field name=\"move_line_ids\" readonly=\"state == ''cancel'' or (state == ''done'' and is_locked) or not product_id\" context=\"{''tree_view_ref'': ''stock.view_stock_move_line_operation_tree'', ''form_view_ref'': ''stock.view_move_line_mobile_form'', ''default_picking_id'': picking_id, ''default_move_id'': id, ''default_product_id'': product_id, ''default_location_id'': location_id, ''default_location_dest_id'': location_dest_id, ''default_company_id'': company_id, ''active_picking_id'': picking_id}\" widget=\"sml_x2_many\"/>\n                </form>"}', '<?xml version="1.0"?>
<form string="Move Detail">
                    <field name="sequence" invisible="1"/>
                    <field name="company_id" invisible="1"/>
                    <field name="state" invisible="1"/>
                    <field name="location_id" invisible="1"/>
                    <field name="location_dest_id" invisible="1"/>
                    <field name="picking_id" invisible="1" readonly="state == ''done''"/>
                    <field name="picking_type_id" invisible="1"/>
                    <field name="is_locked" invisible="1"/>
