INSERT INTO public.ir_ui_view VALUES (1063, 1000, NULL, 1, 1, 'stock.move.line.operations.tree', 'stock.move.line', NULL, 'tree', 'stock/views/stock_move_views.xml', 'primary', '{"en_US": "<tree editable=\"bottom\" decoration-muted=\"(state == ''done'' and is_locked == True)\" multi_edit=\"1\" default_order=\"result_package_id desc, location_id asc, location_dest_id asc, picking_id asc, id\">\n                    <header>\n                        <button class=\"btn-primary\" name=\"action_put_in_pack\" type=\"object\" string=\"Put in Pack\" groups=\"stock.group_tracking_lot\"/>\n                    </header>\n                    <field name=\"product_id\" context=\"{''default_detailed_type'': ''product''}\" required=\"1\" readonly=\"state == ''done'' or move_id\"/>\n                    <field name=\"company_id\" column_invisible=\"True\"/>\n                    <field name=\"move_id\" column_invisible=\"True\"/>\n                    <field name=\"picking_id\" column_invisible=\"True\"/>\n                    <field name=\"picking_code\" column_invisible=\"True\"/>\n                    <field name=\"picking_location_id\" column_invisible=\"True\"/>\n                    <field name=\"picking_location_dest_id\" column_invisible=\"True\"/>\n                    <field name=\"product_uom_category_id\" column_invisible=\"True\"/>\n                    <field name=\"location_id\" column_invisible=\"True\"/>\n                    <field name=\"location_dest_id\" column_invisible=\"True\"/>\n                    <field name=\"quant_id\" column_invisible=\"context.get(''picking_code'') == ''incoming''\" domain=\"[(''product_id'', ''='', product_id), (''location_id'', ''child_of'', picking_location_id)]\" context=\"{''default_location_id'': location_id, ''default_product_id'': product_id, ''search_view_ref'': ''stock.quant_search_view'', ''tree_view_ref'': ''stock.view_stock_quant_tree_simple'', ''form_view_ref'': ''stock.view_stock_quant_form'', ''readonly_form'': False}\" readonly=\"state in (''done'', ''cancel'') and is_locked\" widget=\"pick_from\" options=\"{''no_open'': True}\"/>\n                    <field name=\"lot_id\" column_invisible=\"context.get(''picking_code'') != ''incoming'' or context.get(''show_lots_text'')\" groups=\"stock.group_production_lot\" invisible=\"not lots_visible\" readonly=\"state in (''done'', ''cancel'') and is_locked\" context=\"{''default_product_id'': product_id, ''default_company_id'': company_id, ''active_picking_id'': picking_id}\" optional=\"show\"/>\n                    <field name=\"lot_name\" column_invisible=\"context.get(''picking_code'') != ''incoming'' or not context.get(''show_lots_text'')\" groups=\"stock.group_production_lot\" invisible=\"not lots_visible\" readonly=\"state in (''done'', ''cancel'') and is_locked\" context=\"{''default_product_id'': product_id}\"/>\n                    <field name=\"location_dest_id\" options=\"{''no_create'': True}\" column_invisible=\"context.get(''picking_code'') == ''outgoing''\" readonly=\"state in (''done'', ''cancel'') and is_locked\" groups=\"stock.group_stock_multi_locations\" domain=\"[(''id'', ''child_of'', picking_location_dest_id), ''|'', (''company_id'', ''='', False), (''company_id'', ''='', company_id), (''usage'', ''!='', ''view'')]\"/>\n                    <field name=\"package_id\" readonly=\"state in (''done'', ''cancel'') and is_locked\" column_invisible=\"True\"/>\n                    <field name=\"result_package_id\" column_invisible=\"True\"/>\n                    <field name=\"result_package_id\" readonly=\"state in (''done'', ''cancel'') and is_locked\" groups=\"stock.group_tracking_lot\"/>\n                    <field name=\"lots_visible\" column_invisible=\"True\"/>\n                    <field name=\"owner_id\" groups=\"stock.group_tracking_owner\" column_invisible=\"context.get(''picking_code'') == ''incoming''\" readonly=\"state in (''done'', ''cancel'') and is_locked\"/>\n                    <field name=\"state\" column_invisible=\"True\"/>\n                    <field name=\"is_locked\" column_invisible=\"True\"/>\n                    <field name=\"quantity\" readonly=\"state in (''done'', ''cancel'') and is_locked\" force_save=\"1\"/>\n                    <field name=\"product_uom_id\" force_save=\"1\" readonly=\"state != ''draft'' and id\" groups=\"uom.group_uom\"/>\n                </tree>"}', '<?xml version="1.0"?>
<tree editable="bottom" decoration-muted="(state == ''done'' and is_locked == True)" multi_edit="1" default_order="result_package_id desc, location_id asc, location_dest_id asc, picking_id asc, id">
                    <header>
                        <button class="btn-primary" name="action_put_in_pack" type="object" string="Put in Pack" groups="stock.group_tracking_lot"/>
                    </header>
                    <field name="product_id" context="{''default_detailed_type'': ''product''}" required="1" readonly="state == ''done'' or move_id"/>
                    <field name="company_id" column_invisible="True"/>
                    <field name="move_id" column_invisible="True"/>
                    <field name="picking_id" column_invisible="True"/>
                    <field name="picking_code" column_invisible="True"/>
                    <field name="picking_location_id" column_invisible="True"/>
                    <field name="picking_location_dest_id" column_invisible="True"/>
                    <field name="product_uom_category_id" column_invisible="True"/>
                    <field name="location_id" column_invisible="True"/>
                    <field name="location_dest_id" column_invisible="True"/>
                    <field name="quant_id" column_invisible="context.get(''picking_code'') == ''incoming''" domain="[(''product_id'', ''='', product_id), (''location_id'', ''child_of'', picking_location_id)]" context="{''default_location_id'': location_id, ''default_product_id'': product_id, ''search_view_ref'': ''stock.quant_search_view'', ''tree_view_ref'': ''stock.view_stock_quant_tree_simple'', ''form_view_ref'': ''stock.view_stock_quant_form'', ''readonly_form'': False}" readonly="state in (''done'', ''cancel'') and is_locked" widget="pick_from" options="{''no_open'': True}"/>
                    <field name="lot_id" column_invisible="context.get(''picking_code'') != ''incoming'' or context.get(''show_lots_text'')" groups="stock.group_production_lot" invisible="not lots_visible" readonly="state in (''done'', ''cancel'') and is_locked" context="{''default_product_id'': product_id, ''default_company_id'': company_id, ''active_picking_id'': picking_id}" optional="show"/>
                    <field name="lot_name" column_invisible="context.get(''picking_code'') != ''incoming'' or not context.get(''show_lots_text'')" groups="stock.group_production_lot" invisible="not lots_visible" readonly="state in (''done'', ''cancel'') and is_locked" context="{''default_product_id'': product_id}"/>
                    <field name="location_dest_id" options="{''no_create'': True}" column_invisible="context.get(''picking_code'') == ''outgoing''" readonly="state in (''done'', ''cancel'') and is_locked" groups="stock.group_stock_multi_locations" domain="[(''id'', ''child_of'', picking_location_dest_id), ''|'', (''company_id'', ''='', False), (''company_id'', ''='', company_id), (''usage'', ''!='', ''view'')]"/>
                    <field name="package_id" readonly="state in (''done'', ''cancel'') and is_locked" column_invisible="True"/>
                    <field name="result_package_id" column_invisible="True"/>
                    <field name="result_package_id" readonly="state in (''done'', ''cancel'') and is_locked" groups="stock.group_tracking_lot"/>
                    <field name="lots_visible" column_invisible="True"/>
                    <field name="owner_id" groups="stock.group_tracking_owner" column_invisible="context.get(''picking_code'') == ''incoming''" readonly="state in (''done'', ''cancel'') and is_locked"/>
                    <field name="state" column_invisible="True"/>
                    <field name="is_locked" column_invisible="True"/>
                    <field name="quantity" readonly="state in (''done'', ''cancel'') and is_locked" force_save="1"/>
                    <field name="product_uom_id" force_save="1" readonly="state != ''draft'' and id" groups="uom.group_uom"/>
                </tree>
            ', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (1064, 1, NULL, 1, 1, 'stock.move.form', 'stock.move', NULL, 'form', 'stock/views/stock_move_views.xml', 'primary', '{"en_US": "<form string=\"Stock Moves\" create=\"0\" edit=\"0\">\n                <field name=\"company_id\" invisible=\"1\"/>\n                <header>\n                    <field name=\"state\" widget=\"statusbar\" statusbar_visible=\"draft,confirmed,assigned,done\"/>\n                </header>\n                <sheet>\n                    <div class=\"oe_button_box\" name=\"button_box\">\n                    </div>\n                    <group>\n                        <group name=\"main_grp\" colspan=\"2\">\n                            <group name=\"main_grp_col1\">\n                                <field name=\"reference\"/>\n                                <field name=\"location_id\" options=\"{''no_create'': True}\"/>\n                                <field name=\"location_dest_id\" options=\"{''no_create'': True}\"/>\n                                <field name=\"company_id\" groups=\"base.group_multi_company\"/>\n                            </group>\n                            <group name=\"main_grp_col2\">\n                                <field name=\"product_id\" readonly=\"state == ''done''\"/>\n                                <field name=\"product_uom_category_id\" invisible=\"1\"/>\n                                <label for=\"product_uom_qty\"/>\n                                <div class=\"o_row\">\n                                    <field name=\"product_uom_qty\" readonly=\"state == ''done''\"/>\n                                    <field name=\"product_uom\" options=\"{''no_open'': True, ''no_create'': True}\" groups=\"uom.group_uom\"/>\n                                </div>\n                                <field name=\"name\" invisible=\"1\"/>\n                                <div class=\"o_td_label\">\n                                    <label for=\"date\" string=\"Date Scheduled\" invisible=\"state == ''done''\"/>\n                                    <label for=\"date\" string=\"Date Processing\" invisible=\"state != ''done''\"/>\n                                </div>\n                                <field name=\"date\" readonly=\"1\" nolabel=\"1\"/>\n                                <field name=\"date_deadline\" force_save=\"1\"/>\n                            </group>\n                        </group>\n                        <group name=\"origin_grp\" string=\"Origin\" groups=\"base.group_no_one\">\n                            <field name=\"origin\"/>\n                            <field name=\"group_id\"/>\n                            <field name=\"procure_method\" readonly=\"state != ''draft''\" groups=\"stock.group_adv_location\"/>\n                        </group>\n                        <group name=\"linked_group\" string=\"Linked Moves\" groups=\"base.group_no_one\" colspan=\"2\">\n                            <field name=\"move_orig_ids\" string=\"Origin Moves\" readonly=\"1\">\n                                <tree>\n                                    <field name=\"location_id\"/>\n                                    <field name=\"location_dest_id\"/>\n                                    <field name=\"product_uom_qty\" readonly=\"state == ''done''\"/>\n                                    <field name=\"product_uom\"/>\n                                    <field name=\"state\"/>\n                                </tree>\n                            </field>\n                            <field name=\"move_dest_ids\" string=\"Destination Moves\" readonly=\"1\">\n                                <tree>\n                                    <field name=\"location_id\"/>\n                                    <field name=\"location_dest_id\"/>\n                                    <field name=\"product_uom_qty\" readonly=\"state == ''done''\"/>\n                                    <field name=\"product_uom\"/>\n                                    <field name=\"state\"/>\n                                </tree>\n                            </field>\n                        </group>\n                    </group>\n                </sheet>\n                </form>"}', '<?xml version="1.0"?>
<form string="Stock Moves" create="0" edit="0">
                <field name="company_id" invisible="1"/>
                <header>
                    <field name="state" widget="statusbar" statusbar_visible="draft,confirmed,assigned,done"/>
                </header>
                <sheet>
                    <div class="oe_button_box" name="button_box">
                    </div>
                    <group>
                        <group name="main_grp" colspan="2">
                            <group name="main_grp_col1">
                                <field name="reference"/>
                                <field name="location_id" options="{''no_create'': True}"/>
                                <field name="location_dest_id" options="{''no_create'': True}"/>
                                <field name="company_id" groups="base.group_multi_company"/>
                            </group>
                            <group name="main_grp_col2">
                                <field name="product_id" readonly="state == ''done''"/>
                                <field name="product_uom_category_id" invisible="1"/>
                                <label for="product_uom_qty"/>
                                <div class="o_row">
                                    <field name="product_uom_qty" readonly="state == ''done''"/>
                                    <field name="product_uom" options="{''no_open'': True, ''no_create'': True}" groups="uom.group_uom"/>
                                </div>
                                <field name="name" invisible="1"/>
                                <div class="o_td_label">
                                    <label for="date" string="Date Scheduled" invisible="state == ''done''"/>
                                    <label for="date" string="Date Processing" invisible="state != ''done''"/>
                                </div>
                                <field name="date" readonly="1" nolabel="1"/>
                                <field name="date_deadline" force_save="1"/>
                            </group>
                        </group>
                        <group name="origin_grp" string="Origin" groups="base.group_no_one">
                            <field name="origin"/>
                            <field name="group_id"/>
                            <field name="procure_method" readonly="state != ''draft''" groups="stock.group_adv_location"/>
                        </group>
                        <group name="linked_group" string="Linked Moves" groups="base.group_no_one" colspan="2">
                            <field name="move_orig_ids" string="Origin Moves" readonly="1">
                                <tree>
                                    <field name="location_id"/>
                                    <field name="location_dest_id"/>
                                    <field name="product_uom_qty" readonly="state == ''done''"/>
                                    <field name="product_uom"/>
                                    <field name="state"/>
                                </tree>
                            </field>
                            <field name="move_dest_ids" string="Destination Moves" readonly="1">
                                <tree>
                                    <field name="location_id"/>
                                    <field name="location_dest_id"/>
                                    <field name="product_uom_qty" readonly="state == ''done''"/>
                                    <field name="product_uom"/>
                                    <field name="state"/>
                                </tree>
                            </field>
                        </group>
                    </group>
                </sheet>
                </form>
            ', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (1065, 3, NULL, 1, 1, 'stock.move.search', 'stock.move', NULL, 'search', 'stock/views/stock_move_views.xml', 'primary', '{"en_US": "<search string=\"Stock Moves\">\n                    <field name=\"name\" string=\"Location\" filter_domain=\"[''|'',(''location_id'', ''ilike'', self),(''location_dest_id'', ''ilike'', self)]\" groups=\"stock.group_stock_multi_locations\"/>\n                    <field name=\"product_id\"/>\n                    <field name=\"origin\" filter_domain=\"[''|'', ''|'', (''origin'', ''ilike'', self), (''name'', ''ilike'', self), (''picking_id'', ''ilike'', self)]\" string=\"Reference\"/>\n                    <field name=\"location_id\" string=\"Source Location\" groups=\"stock.group_stock_multi_locations\"/>\n                    <field name=\"location_dest_id\" string=\"Destination Location\" groups=\"stock.group_stock_multi_locations\"/>\n                    <field name=\"partner_id\" string=\"Partner\" filter_domain=\"[(''picking_id.partner_id'', ''child_of'', self)]\"/>\n                    <filter string=\"Ready\" name=\"ready\" domain=\"[(''state'',''='',''assigned'')]\" help=\"Stock moves that are Available (Ready to process)\"/>\n                    <filter string=\"To Do\" name=\"future\" domain=\"[(''state'',''in'',(''assigned'',''confirmed'',''waiting''))]\" help=\"Stock moves that are Confirmed, Available or Waiting\"/>\n                    <filter string=\"Done\" name=\"done\" domain=\"[(''state'',''='',''done'')]\" help=\"Stock moves that have been processed\"/>\n                    <separator/>\n                    <filter string=\"Incoming\" name=\"incoming\" domain=\"[(''location_id.usage'', ''not in'', (''internal'', ''transit'')), (''location_dest_id.usage'', ''in'', (''internal'', ''transit''))]\"/>\n                    <filter string=\"Outgoing\" name=\"outgoing\" domain=\"[(''location_id.usage'', ''in'', (''internal'', ''transit'')), (''location_dest_id.usage'', ''not in'', (''internal'', ''transit''))]\"/>\n                    <filter string=\"Inventory\" name=\"inventory\" domain=\"[(''is_inventory'', ''='', True)]\"/>\n                    <separator/>\n                    <filter string=\"Date\" name=\"today\" date=\"date\" help=\"Scheduled or processing date\"/>\n                    <group expand=\"0\" string=\"Group By\">\n                        <filter string=\"Product\" name=\"by_product\" domain=\"[]\" context=\"{''group_by'': ''product_id''}\"/>\n                        <filter string=\"Operation Type\" name=\"groupby_picking_type_id\" domain=\"[]\" context=\"{''group_by'': ''picking_type_id''}\"/>\n                        <filter string=\"Picking\" name=\"groupby_picking_id\" domain=\"[]\" context=\"{''group_by'': ''picking_id''}\"/>\n                        <filter string=\"Source Location\" name=\"groupby_location_id\" domain=\"[]\" context=\"{''group_by'': ''location_id''}\" groups=\"stock.group_stock_multi_locations\"/>\n                        <filter string=\"Destination Location\" name=\"groupby_dest_location_id\" domain=\"[]\" context=\"{''group_by'': ''location_dest_id''}\" groups=\"stock.group_stock_multi_locations\"/>\n                        <filter string=\"Status\" name=\"status\" domain=\"[]\" context=\"{''group_by'': ''state''}\"/>\n                        <filter string=\"Creation Date\" name=\"groupby_create_date\" domain=\"[]\" context=\"{''group_by'': ''create_date''}\" groups=\"base.group_no_one\"/>\n                        <filter string=\"Scheduled Date\" name=\"groupby_date\" domain=\"[]\" context=\"{''group_by'': ''date''}\"/>\n                    </group>\n                </search>"}', '<?xml version="1.0"?>
<search string="Stock Moves">
                    <field name="name" string="Location" filter_domain="[''|'',(''location_id'', ''ilike'', self),(''location_dest_id'', ''ilike'', self)]" groups="stock.group_stock_multi_locations"/>
                    <field name="product_id"/>
                    <field name="origin" filter_domain="[''|'', ''|'', (''origin'', ''ilike'', self), (''name'', ''ilike'', self), (''picking_id'', ''ilike'', self)]" string="Reference"/>
                    <field name="location_id" string="Source Location" groups="stock.group_stock_multi_locations"/>
                    <field name="location_dest_id" string="Destination Location" groups="stock.group_stock_multi_locations"/>
                    <field name="partner_id" string="Partner" filter_domain="[(''picking_id.partner_id'', ''child_of'', self)]"/>
                    <filter string="Ready" name="ready" domain="[(''state'',''='',''assigned'')]" help="Stock moves that are Available (Ready to process)"/>
                    <filter string="To Do" name="future" domain="[(''state'',''in'',(''assigned'',''confirmed'',''waiting''))]" help="Stock moves that are Confirmed, Available or Waiting"/>
                    <filter string="Done" name="done" domain="[(''state'',''='',''done'')]" help="Stock moves that have been processed"/>
                    <separator/>
                    <filter string="Incoming" name="incoming" domain="[(''location_id.usage'', ''not in'', (''internal'', ''transit'')), (''location_dest_id.usage'', ''in'', (''internal'', ''transit''))]"/>
                    <filter string="Outgoing" name="outgoing" domain="[(''location_id.usage'', ''in'', (''internal'', ''transit'')), (''location_dest_id.usage'', ''not in'', (''internal'', ''transit''))]"/>
                    <filter string="Inventory" name="inventory" domain="[(''is_inventory'', ''='', True)]"/>
                    <separator/>
                    <filter string="Date" name="today" date="date" help="Scheduled or processing date"/>
                    <group expand="0" string="Group By">
                        <filter string="Product" name="by_product" domain="[]" context="{''group_by'': ''product_id''}"/>
                        <filter string="Operation Type" name="groupby_picking_type_id" domain="[]" context="{''group_by'': ''picking_type_id''}"/>
                        <filter string="Picking" name="groupby_picking_id" domain="[]" context="{''group_by'': ''picking_id''}"/>
                        <filter string="Source Location" name="groupby_location_id" domain="[]" context="{''group_by'': ''location_id''}" groups="stock.group_stock_multi_locations"/>
                        <filter string="Destination Location" name="groupby_dest_location_id" domain="[]" context="{''group_by'': ''location_dest_id''}" groups="stock.group_stock_multi_locations"/>
                        <filter string="Status" name="status" domain="[]" context="{''group_by'': ''state''}"/>
                        <filter string="Creation Date" name="groupby_create_date" domain="[]" context="{''group_by'': ''create_date''}" groups="base.group_no_one"/>
                        <filter string="Scheduled Date" name="groupby_date" domain="[]" context="{''group_by'': ''date''}"/>
                    </group>
                </search>
            ', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (1066, 6, NULL, 1, 1, 'stock.move.tree2', 'stock.move', NULL, 'tree', 'stock/views/stock_move_views.xml', 'primary', '{"en_US": "<tree decoration-muted=\"state == ''cancel''\" default_order=\"date, picking_id, sequence\" string=\"Moves\" create=\"0\">\n                    <field name=\"date\" column_invisible=\"True\"/>\n                    <field name=\"date_deadline\" optional=\"hide\"/>\n                    <field name=\"picking_id\" string=\"Reference\" column_invisible=\"True\" readonly=\"state == ''done''\"/>\n                    <field name=\"sequence\" column_invisible=\"True\"/>\n                    <field name=\"origin\" optional=\"show\"/>\n                    <field name=\"product_id\" readonly=\"state == ''done''\"/>\n                    <field name=\"product_uom_qty\" readonly=\"state == ''done''\"/>\n                    <field name=\"product_uom\" options=\"{''no_open'': True, ''no_create'': True}\" string=\"Unit of Measure\" groups=\"uom.group_uom\"/>\n                    <field name=\"location_id\" options=\"{''no_create'': True}\" column_invisible=\"True\"/>\n                    <field name=\"location_dest_id\" column_invisible=\"True\"/>\n                    <field name=\"state\" optional=\"show\"/>\n                    <field name=\"company_id\" column_invisible=\"True\"/>\n                </tree>"}', '<?xml version="1.0"?>
<tree decoration-muted="state == ''cancel''" default_order="date, picking_id, sequence" string="Moves" create="0">
                    <field name="date" column_invisible="True"/>
                    <field name="date_deadline" optional="hide"/>
                    <field name="picking_id" string="Reference" column_invisible="True" readonly="state == ''done''"/>
                    <field name="sequence" column_invisible="True"/>
                    <field name="origin" optional="show"/>
                    <field name="product_id" readonly="state == ''done''"/>
                    <field name="product_uom_qty" readonly="state == ''done''"/>
                    <field name="product_uom" options="{''no_open'': True, ''no_create'': True}" string="Unit of Measure" groups="uom.group_uom"/>
                    <field name="location_id" options="{''no_create'': True}" column_invisible="True"/>
                    <field name="location_dest_id" column_invisible="True"/>
                    <field name="state" optional="show"/>
                    <field name="company_id" column_invisible="True"/>
                </tree>
            ', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (1067, 16, 473, 1, 1, 'product.category.form', 'product.category', NULL, 'form', 'stock/views/product_views.xml', 'extension', '{"en_US": "<data><div name=\"button_box\" position=\"inside\">\n                    <button string=\"Putaway Rules\" class=\"oe_stat_button\" icon=\"fa-random\" name=\"367\" type=\"action\" groups=\"stock.group_stock_multi_locations\"/>\n                </div>\n                <group name=\"first\" position=\"after\">\n                    <group>\n                        <group name=\"logistics\" string=\"Logistics\">\n                            <field name=\"route_ids\" widget=\"many2many_tags\" groups=\"stock.group_adv_location\"/>\n                            <field name=\"total_route_ids\" widget=\"many2many_tags\" groups=\"stock.group_adv_location\" invisible=\"not parent_id\"/>\n                            <field name=\"removal_strategy_id\" options=\"{''no_create'': True}\"/>\n                            <field name=\"packaging_reserve_method\" widget=\"radio\" groups=\"product.group_stock_packaging\"/>\n                        </group>\n                    </group>\n                </group>\n            </data>"}', '<?xml version="1.0"?>
<data><div name="button_box" position="inside">
                    <button string="Putaway Rules" class="oe_stat_button" icon="fa-random" name="367" type="action" groups="stock.group_stock_multi_locations"/>
                </div>
                <group name="first" position="after">
                    <group>
                        <group name="logistics" string="Logistics">
                            <field name="route_ids" widget="many2many_tags" groups="stock.group_adv_location"/>
                            <field name="total_route_ids" widget="many2many_tags" groups="stock.group_adv_location" invisible="not parent_id"/>
                            <field name="removal_strategy_id" options="{''no_create'': True}"/>
                            <field name="packaging_reserve_method" widget="radio" groups="product.group_stock_packaging"/>
                        </group>
                    </group>
                </group>
            </data>', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (1068, 16, 457, 1, 1, 'product.stock.tree.inherit', 'product.product', NULL, 'tree', 'stock/views/product_views.xml', 'extension', '{"en_US": "<field name=\"type\" position=\"after\">\n                    <field name=\"qty_available\" invisible=\"type != ''product''\" string=\"On Hand\" optional=\"show\" decoration-danger=\"virtual_available &lt; 0\" decoration-warning=\"virtual_available == 0\" decoration-bf=\"1\" groups=\"stock.group_stock_user\"/>\n                    <field name=\"virtual_available\" invisible=\"type != ''product''\" string=\"Forecasted\" optional=\"show\" decoration-danger=\"virtual_available &lt; 0\" decoration-warning=\"virtual_available == 0\" groups=\"stock.group_stock_user\"/>\n                </field>"}', '<?xml version="1.0"?>
<field name="type" position="after">
                    <field name="qty_available" invisible="type != ''product''" string="On Hand" optional="show" decoration-danger="virtual_available &lt; 0" decoration-warning="virtual_available == 0" decoration-bf="1" groups="stock.group_stock_user"/>
                    <field name="virtual_available" invisible="type != ''product''" string="Forecasted" optional="show" decoration-danger="virtual_available &lt; 0" decoration-warning="virtual_available == 0" groups="stock.group_stock_user"/>
                </field>
            ', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (1069, 16, 496, 1, 1, 'product.template.stock.tree.inherit', 'product.template', NULL, 'tree', 'stock/views/product_views.xml', 'extension', '{"en_US": "<data><field name=\"uom_id\" position=\"before\">\n                    <field name=\"show_on_hand_qty_status_button\" column_invisible=\"True\" groups=\"stock.group_stock_user\"/>\n                    <field name=\"qty_available\" invisible=\"not show_on_hand_qty_status_button\" string=\"On Hand\" optional=\"show\" decoration-danger=\"qty_available &lt; 0\" groups=\"stock.group_stock_user\"/>\n                    <field name=\"virtual_available\" invisible=\"not show_on_hand_qty_status_button\" string=\"Forecasted\" optional=\"show\" decoration-danger=\"virtual_available &lt; 0\" decoration-bf=\"1\" groups=\"stock.group_stock_user\"/>\n                </field>\n                <field name=\"default_code\" position=\"after\">\n                    <field name=\"responsible_id\" widget=\"many2one_avatar_user\" optional=\"hide\" groups=\"stock.group_stock_user\"/>\n                </field>\n            </data>"}', '<?xml version="1.0"?>
<data><field name="uom_id" position="before">
                    <field name="show_on_hand_qty_status_button" column_invisible="True" groups="stock.group_stock_user"/>
                    <field name="qty_available" invisible="not show_on_hand_qty_status_button" string="On Hand" optional="show" decoration-danger="qty_available &lt; 0" groups="stock.group_stock_user"/>
                    <field name="virtual_available" invisible="not show_on_hand_qty_status_button" string="Forecasted" optional="show" decoration-danger="virtual_available &lt; 0" decoration-bf="1" groups="stock.group_stock_user"/>
                </field>
                <field name="default_code" position="after">
                    <field name="responsible_id" widget="many2one_avatar_user" optional="hide" groups="stock.group_stock_user"/>
                </field>
            </data>', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (1070, 16, 454, 1, 1, 'product.template.search.stock.form', 'product.template', NULL, 'search', 'stock/views/product_views.xml', 'primary', '{"en_US": "<xpath expr=\"//field[@name=''attribute_line_ids'']\" position=\"after\">\n                    <separator/>\n                    <field name=\"location_id\" context=\"{''location'': self}\" filter_domain=\"[]\"/>\n                    <field name=\"warehouse_id\" context=\"{''warehouse'': self}\" filter_domain=\"[]\"/>\n                    <separator/>\n                    <filter name=\"real_stock_available\" string=\"Available Products\" domain=\"[(''qty_available'',''&gt;'',0)]\"/>\n                    <filter name=\"real_stock_negative\" string=\"Negative Forecasted Quantity\" domain=\"[(''virtual_available'',''&lt;'',0)]\"/>\n                </xpath>"}', '<?xml version="1.0"?>
<xpath expr="//field[@name=''attribute_line_ids'']" position="after">
                    <separator/>
                    <field name="location_id" context="{''location'': self}" filter_domain="[]"/>
                    <field name="warehouse_id" context="{''warehouse'': self}" filter_domain="[]"/>
                    <separator/>
                    <filter name="real_stock_available" string="Available Products" domain="[(''qty_available'',''&gt;'',0)]"/>
                    <filter name="real_stock_negative" string="Negative Forecasted Quantity" domain="[(''virtual_available'',''&lt;'',0)]"/>
                </xpath>
            ', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (1071, 16, 455, 1, 1, 'product.product.search.stock.form', 'product.product', NULL, 'search', 'stock/views/product_views.xml', 'primary', '{"en_US": "<xpath expr=\"//filter[@name=''inactive'']\" position=\"after\">\n                    <separator/>\n                    <filter name=\"real_stock_available\" string=\"Available Products\" domain=\"[(''qty_available'',''&gt;'',0)]\"/>\n                    <filter name=\"real_stock_negative\" string=\"Negative Forecasted Quantity\" domain=\"[(''virtual_available'',''&lt;'',0)]\"/>\n                </xpath>"}', '<?xml version="1.0"?>
<xpath expr="//filter[@name=''inactive'']" position="after">
                    <separator/>
                    <filter name="real_stock_available" string="Available Products" domain="[(''qty_available'',''&gt;'',0)]"/>
                    <filter name="real_stock_negative" string="Negative Forecasted Quantity" domain="[(''virtual_available'',''&lt;'',0)]"/>
                </xpath>
            ', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (1072, 16, 453, 1, 1, 'product.template.stock.property.form.inherit', 'product.template', NULL, 'form', 'stock/views/product_views.xml', 'extension', '{"en_US": "<data><xpath expr=\"//group[@name=''group_lots_and_weight'']\" position=\"inside\">\n                    <label for=\"sale_delay\" invisible=\"not sale_ok\"/>\n                    <div invisible=\"not sale_ok\">\n                        <field name=\"sale_delay\" class=\"oe_inline\" style=\"vertical-align:baseline\"/> days\n                    </div>\n                </xpath>\n                <xpath expr=\"//group[@name=''group_lots_and_weight'']\" position=\"before\">\n                    <field name=\"has_available_route_ids\" invisible=\"1\"/>\n                    <group string=\"Operations\" name=\"operations\">\n                        <label for=\"route_ids\" invisible=\"type == ''service''\"/>\n                        <div>\n                            <field name=\"route_ids\" class=\"mb-0\" widget=\"many2many_checkboxes\" invisible=\"not has_available_route_ids or type == ''service''\"/>\n                            <button id=\"stock.view_diagram_button\" string=\"View Diagram\" type=\"action\" name=\"402\" icon=\"oi-arrow-right\" invisible=\"type not in [''product'', ''consu'']\" class=\"btn btn-link pt-0\" context=\"{''default_product_tmpl_id'': id}\"/>\n                        </div>\n                        <field name=\"route_from_categ_ids\" widget=\"many2many_tags\" invisible=\"not route_from_categ_ids\"/>\n                    </group>\n                </xpath>\n                <xpath expr=\"//group[@name=''group_lots_and_weight'']\" position=\"after\">\n                    <group string=\"Traceability\" name=\"traceability\" groups=\"stock.group_production_lot\" invisible=\"type == ''consu''\">\n                        <field name=\"tracking\" widget=\"radio\" invisible=\"type == ''service''\"/>\n                    </group>\n                     <group string=\"Counterpart Locations\" name=\"stock_property\" groups=\"base.group_no_one\">\n                        <field name=\"property_stock_production\"/>\n                        <field name=\"property_stock_inventory\"/>\n                    </group>\n                </xpath>\n                <page name=\"inventory\" position=\"inside\">\n                    <group>\n                        <group string=\"Description for Receipts\">\n                            <field name=\"description_pickingin\" colspan=\"2\" nolabel=\"1\" placeholder=\"This note is added to receipt orders (e.g. where to store the product in the warehouse).\"/>\n                        </group>\n                        <group string=\"Description for Delivery Orders\">\n                            <field name=\"description_pickingout\" colspan=\"2\" nolabel=\"1\" placeholder=\"This note is added to delivery orders.\"/>\n                        </group>\n                        <group string=\"Description for Internal Transfers\" groups=\"stock.group_stock_multi_locations\">\n                            <field name=\"description_picking\" colspan=\"2\" placeholder=\"This note is added to internal transfer orders (e.g. where to pick the product in the warehouse).\" nolabel=\"1\"/>\n                        </group>\n                    </group>\n                </page>\n                <xpath expr=\"//page[@name=''inventory'']\" position=\"attributes\">\n                    <attribute name=\"groups\" add=\"stock.group_stock_user\" separator=\",\"/>\n                </xpath>\n            </data>"}', '<?xml version="1.0"?>
<data><xpath expr="//group[@name=''group_lots_and_weight'']" position="inside">
                    <label for="sale_delay" invisible="not sale_ok"/>
                    <div invisible="not sale_ok">
                        <field name="sale_delay" class="oe_inline" style="vertical-align:baseline"/> days
                    </div>
                </xpath>
                <xpath expr="//group[@name=''group_lots_and_weight'']" position="before">
                    <field name="has_available_route_ids" invisible="1"/>
                    <group string="Operations" name="operations">
                        <label for="route_ids" invisible="type == ''service''"/>
                        <div>
                            <field name="route_ids" class="mb-0" widget="many2many_checkboxes" invisible="not has_available_route_ids or type == ''service''"/>
                            <button id="stock.view_diagram_button" string="View Diagram" type="action" name="402" icon="oi-arrow-right" invisible="type not in [''product'', ''consu'']" class="btn btn-link pt-0" context="{''default_product_tmpl_id'': id}"/>
                        </div>
                        <field name="route_from_categ_ids" widget="many2many_tags" invisible="not route_from_categ_ids"/>
                    </group>
                </xpath>
                <xpath expr="//group[@name=''group_lots_and_weight'']" position="after">
                    <group string="Traceability" name="traceability" groups="stock.group_production_lot" invisible="type == ''consu''">
                        <field name="tracking" widget="radio" invisible="type == ''service''"/>
                    </group>
                     <group string="Counterpart Locations" name="stock_property" groups="base.group_no_one">
                        <field name="property_stock_production"/>
                        <field name="property_stock_inventory"/>
                    </group>
                </xpath>
                <page name="inventory" position="inside">
                    <group>
                        <group string="Description for Receipts">
                            <field name="description_pickingin" colspan="2" nolabel="1" placeholder="This note is added to receipt orders (e.g. where to store the product in the warehouse)."/>
                        </group>
                        <group string="Description for Delivery Orders">
                            <field name="description_pickingout" colspan="2" nolabel="1" placeholder="This note is added to delivery orders."/>
                        </group>
                        <group string="Description for Internal Transfers" groups="stock.group_stock_multi_locations">
                            <field name="description_picking" colspan="2" placeholder="This note is added to internal transfer orders (e.g. where to pick the product in the warehouse)." nolabel="1"/>
                        </group>
                    </group>
                </page>
                <xpath expr="//page[@name=''inventory'']" position="attributes">
                    <attribute name="groups" add="stock.group_stock_user" separator=","/>
                </xpath>
            </data>', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (1102, 16, NULL, 1, 1, 'message_head', NULL, 'stock.message_head', 'qweb', 'stock/views/stock_template.xml', 'primary', '{"en_US": "<t t-name=\"stock.message_head\">\n        <t t-if=\"move.state != ''done''\">\n            <strong>The initial demand has been updated.</strong>\n        </t>\n        <t t-if=\"move.state == ''done''\">\n            <strong>\n                The done move line has been corrected.\n            </strong>\n        </t>\n    </t>"}', '<?xml version="1.0"?>
<t t-name="stock.message_head">
        <t t-if="move.state != ''done''">
            <strong>The initial demand has been updated.</strong>
        </t>
        <t t-if="move.state == ''done''">
            <strong>
                The done move line has been corrected.
            </strong>
        </t>
    </t>

    ', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (1073, 16, 498, 1, 1, 'Product Template Kanban Stock', 'product.template', NULL, 'kanban', 'stock/views/product_views.xml', 'extension', '{"en_US": "<data><xpath expr=\"//kanban\" position=\"inside\">\n                    <field name=\"type\"/>\n                    <field name=\"show_on_hand_qty_status_button\" groups=\"stock.group_stock_user\"/>\n                </xpath>\n                <xpath expr=\"//div[@name=''product_lst_price'']\" position=\"after\">\n                    <t groups=\"stock.group_stock_user\">\n                    <div t-if=\"record.show_on_hand_qty_status_button.raw_value\">On hand: <field name=\"qty_available\"/> <field name=\"uom_id\"/></div>\n                    </t>\n                </xpath>\n            </data>"}', '<?xml version="1.0"?>
<data><xpath expr="//kanban" position="inside">
                    <field name="type"/>
                    <field name="show_on_hand_qty_status_button" groups="stock.group_stock_user"/>
                </xpath>
                <xpath expr="//div[@name=''product_lst_price'']" position="after">
                    <t groups="stock.group_stock_user">
                    <div t-if="record.show_on_hand_qty_status_button.raw_value">On hand: <field name="qty_available"/> <field name="uom_id"/></div>
                    </t>
                </xpath>
            </data>', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (1074, 16, 480, 1, 1, 'product.packaging.tree.view.stock', 'product.packaging', NULL, 'tree', 'stock/views/product_views.xml', 'extension', '{"en_US": "<xpath expr=\"//field[@name=''name'']\" position=\"after\">\n                    <field name=\"package_type_id\" groups=\"stock.group_tracking_lot\"/>\n                    <field name=\"route_ids\" groups=\"stock.group_adv_location\" optional=\"hide\" widget=\"many2many_tags\"/>\n                </xpath>"}', '<?xml version="1.0"?>
