INSERT INTO public.ir_ui_view VALUES (1079, 16, 460, 1, 1, 'product.product.procurement', 'product.product', NULL, 'form', 'stock/views/product_views.xml', 'extension', '{"en_US": "<data>\n                    <xpath expr=\"//header/button\" position=\"before\">\n                        <button string=\"Update Quantity\" type=\"object\" groups=\"stock.group_stock_manager\" name=\"action_update_quantity_on_hand\" invisible=\"type != ''product''\"/>\n                        <button string=\"Replenish\" type=\"action\" name=\"363\" context=\"{''default_product_id'': id}\" groups=\"stock.group_stock_user\" invisible=\"type not in [''consu'', ''product'']\"/>\n                    </xpath>\n                    <div name=\"button_box\" position=\"inside\">\n                        <t groups=\"stock.group_stock_user\">\n                            <field name=\"tracking\" invisible=\"1\"/>\n                            <field name=\"show_on_hand_qty_status_button\" invisible=\"1\"/>\n                            <field name=\"show_forecasted_qty_status_button\" invisible=\"1\"/>\n                            <button class=\"oe_stat_button\" name=\"action_update_quantity_on_hand\" icon=\"fa-cubes\" type=\"object\" invisible=\"not show_on_hand_qty_status_button\">\n                                <div class=\"o_field_widget o_stat_info\">\n                                        <span class=\"o_stat_value d-flex gap-1\">\n                                            <field name=\"qty_available\" nolabel=\"1\" class=\"oe_inline\"/>\n                                            <field name=\"uom_name\" class=\"oe_inline\"/>\n                                        </span>\n                                        <span class=\"o_stat_text\">On Hand</span>\n                                </div>\n                            </button>\n                            <button type=\"object\" name=\"action_product_forecast_report\" invisible=\"not show_forecasted_qty_status_button\" context=\"{''default_product_id'': id, ''active_model'': ''product.template''}\" class=\"oe_stat_button\" icon=\"fa-area-chart\">\n                                <div class=\"o_field_widget o_stat_info\">\n                                    <span class=\"o_stat_value d-flex gap-1\">\n                                        <field name=\"virtual_available\" class=\"oe_inline\"/>\n                                        <field name=\"uom_name\" class=\"oe_inline\"/>\n                                    </span>\n                                    <span class=\"o_stat_text\">Forecasted</span>\n                                </div>\n                            </button>\n                            <button type=\"object\" name=\"action_view_stock_move_lines\" invisible=\"type not in [''product'', ''consu'']\" class=\"oe_stat_button\" icon=\"fa-exchange\" groups=\"stock.group_stock_user\">\n                                <div class=\"d-flex flex-column\">\n                                    <div class=\"o_field_widget o_stat_info align-items-baseline flex-row gap-1 me-1\">\n                                        <span class=\"o_stat_text\">In:</span>\n                                        <span class=\"o_stat_value\"><field name=\"nbr_moves_in\"/></span>\n                                    </div>\n                                    <div class=\"o_field_widget o_stat_info align-items-baseline flex-row gap-1 me-1\">\n                                        <span class=\"o_stat_text\">Out:</span>\n                                        <span class=\"o_stat_value\"><field name=\"nbr_moves_out\"/></span>\n                                    </div>\n                                </div>\n                            </button>\n                            <button name=\"action_view_orderpoints\" type=\"object\" invisible=\"type not in [''product'', ''consu''] or nbr_reordering_rules != 1\" class=\"oe_stat_button\" icon=\"fa-refresh\">\n                                <div class=\"d-flex flex-column\">\n                                    <div class=\"o_field_widget o_stat_info align-items-baseline flex-row gap-1 me-1\">\n                                        <span class=\"o_stat_text\">Min:</span>\n                                        <span class=\"o_stat_value\"><field name=\"reordering_min_qty\"/></span>\n                                    </div>\n                                    <div class=\"o_field_widget o_stat_info align-items-baseline flex-row gap-1 me-1\">\n                                        <span class=\"o_stat_text\">Max:</span>\n                                        <span class=\"o_stat_value\"><field name=\"reordering_max_qty\"/></span>\n                                    </div>\n                                </div>\n                            </button>\n                            <button type=\"object\" name=\"action_view_orderpoints\" invisible=\"type != ''product'' or nbr_reordering_rules == 1\" class=\"oe_stat_button\" icon=\"fa-refresh\">\n                                <field name=\"nbr_reordering_rules\" widget=\"statinfo\"/>\n                            </button>\n                            <button type=\"object\" name=\"action_open_product_lot\" invisible=\"tracking == ''none''\" class=\"oe_stat_button\" icon=\"fa-bars\" groups=\"stock.group_production_lot\">\n                                <div class=\"o_stat_info\">\n                                    <span class=\"o_stat_text\">Lot/Serial Numbers</span>\n                                </div>\n                            </button>\n                            <button type=\"object\" name=\"action_view_related_putaway_rules\" class=\"oe_stat_button\" icon=\"fa-random\" groups=\"stock.group_stock_multi_locations\" invisible=\"type == ''service''\" context=\"{                                     ''invisible_handle'': True,                                     ''single_product'': product_variant_count == 1,                                 }\">\n                                    <div class=\"o_stat_info\">\n                                        <span class=\"o_stat_text\">Putaway Rules</span>\n                                    </div>\n                             </button>\n                            <button type=\"object\" string=\"Storage Capacities\" name=\"action_view_storage_category_capacity\" groups=\"stock.group_stock_storage_categories\" invisible=\"type == ''service''\" class=\"oe_stat_button\" icon=\"fa-cubes\"/>\n                        </t>\n                    </div>\n                    <xpath expr=\"//button[@name=''402'']\" position=\"attributes\">\n                        <attribute name=\"context\">\n                            {''default_product_id'': id}\n                        </attribute>\n                    </xpath>\n                </data>"}', '<?xml version="1.0"?>
<data>
                    <xpath expr="//header/button" position="before">
                        <button string="Update Quantity" type="object" groups="stock.group_stock_manager" name="action_update_quantity_on_hand" invisible="type != ''product''"/>
                        <button string="Replenish" type="action" name="363" context="{''default_product_id'': id}" groups="stock.group_stock_user" invisible="type not in [''consu'', ''product'']"/>
                    </xpath>
                    <div name="button_box" position="inside">
                        <t groups="stock.group_stock_user">
                            <field name="tracking" invisible="1"/>
                            <field name="show_on_hand_qty_status_button" invisible="1"/>
                            <field name="show_forecasted_qty_status_button" invisible="1"/>
                            <button class="oe_stat_button" name="action_update_quantity_on_hand" icon="fa-cubes" type="object" invisible="not show_on_hand_qty_status_button">
                                <div class="o_field_widget o_stat_info">
                                        <span class="o_stat_value d-flex gap-1">
                                            <field name="qty_available" nolabel="1" class="oe_inline"/>
                                            <field name="uom_name" class="oe_inline"/>
                                        </span>
                                        <span class="o_stat_text">On Hand</span>
                                </div>
                            </button>
                            <button type="object" name="action_product_forecast_report" invisible="not show_forecasted_qty_status_button" context="{''default_product_id'': id, ''active_model'': ''product.template''}" class="oe_stat_button" icon="fa-area-chart">
                                <div class="o_field_widget o_stat_info">
                                    <span class="o_stat_value d-flex gap-1">
                                        <field name="virtual_available" class="oe_inline"/>
                                        <field name="uom_name" class="oe_inline"/>
                                    </span>
                                    <span class="o_stat_text">Forecasted</span>
                                </div>
                            </button>
                            <button type="object" name="action_view_stock_move_lines" invisible="type not in [''product'', ''consu'']" class="oe_stat_button" icon="fa-exchange" groups="stock.group_stock_user">
                                <div class="d-flex flex-column">
                                    <div class="o_field_widget o_stat_info align-items-baseline flex-row gap-1 me-1">
                                        <span class="o_stat_text">In:</span>
                                        <span class="o_stat_value"><field name="nbr_moves_in"/></span>
                                    </div>
                                    <div class="o_field_widget o_stat_info align-items-baseline flex-row gap-1 me-1">
                                        <span class="o_stat_text">Out:</span>
                                        <span class="o_stat_value"><field name="nbr_moves_out"/></span>
                                    </div>
                                </div>
                            </button>
                            <button name="action_view_orderpoints" type="object" invisible="type not in [''product'', ''consu''] or nbr_reordering_rules != 1" class="oe_stat_button" icon="fa-refresh">
                                <div class="d-flex flex-column">
                                    <div class="o_field_widget o_stat_info align-items-baseline flex-row gap-1 me-1">
                                        <span class="o_stat_text">Min:</span>
                                        <span class="o_stat_value"><field name="reordering_min_qty"/></span>
                                    </div>
                                    <div class="o_field_widget o_stat_info align-items-baseline flex-row gap-1 me-1">
                                        <span class="o_stat_text">Max:</span>
                                        <span class="o_stat_value"><field name="reordering_max_qty"/></span>
                                    </div>
                                </div>
                            </button>
                            <button type="object" name="action_view_orderpoints" invisible="type != ''product'' or nbr_reordering_rules == 1" class="oe_stat_button" icon="fa-refresh">
                                <field name="nbr_reordering_rules" widget="statinfo"/>
                            </button>
                            <button type="object" name="action_open_product_lot" invisible="tracking == ''none''" class="oe_stat_button" icon="fa-bars" groups="stock.group_production_lot">
                                <div class="o_stat_info">
                                    <span class="o_stat_text">Lot/Serial Numbers</span>
                                </div>
                            </button>
                            <button type="object" name="action_view_related_putaway_rules" class="oe_stat_button" icon="fa-random" groups="stock.group_stock_multi_locations" invisible="type == ''service''" context="{                                     ''invisible_handle'': True,                                     ''single_product'': product_variant_count == 1,                                 }">
                                    <div class="o_stat_info">
                                        <span class="o_stat_text">Putaway Rules</span>
                                    </div>
                             </button>
                            <button type="object" string="Storage Capacities" name="action_view_storage_category_capacity" groups="stock.group_stock_storage_categories" invisible="type == ''service''" class="oe_stat_button" icon="fa-cubes"/>
                        </t>
                    </div>
                    <xpath expr="//button[@name=''402'']" position="attributes">
                        <attribute name="context">
                            {''default_product_id'': id}
                        </attribute>
                    </xpath>
                </data>
            ', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
