                                <field name="nbr_reordering_rules" widget="statinfo"/>
                            </button>
                            <button type="object" name="action_open_product_lot" invisible="tracking == ''none''" class="oe_stat_button" icon="fa-bars" groups="stock.group_production_lot">
                                <div class="o_stat_info">
                                    <span class="o_stat_text">Lot/Serial Numbers</span>
                                </div>
                            </button>
                            <button type="object" name="action_view_related_putaway_rules" class="oe_stat_button" icon="fa-random" groups="stock.group_stock_multi_locations" invisible="type == ''service''" context="{                                     ''invisible_handle'': True,                                     ''single_product'': product_variant_count == 1,                                 }">
                                    <div class="o_stat_info">
                                        <span class="o_stat_text">Putaway Rules</span>
                                    </div>
                             </button>
                             <button type="object" name="action_view_storage_category_capacity" groups="stock.group_stock_storage_categories" invisible="type == ''service''" class="oe_stat_button" icon="fa-cubes">
                                <div class="o_stat_info">
                                    <span class="o_stat_text">Storage Capacities</span>
                                </div>
                            </button>
                        </t>
                    </div>

                    <xpath expr="//label[@for=''weight'']" position="before">
                        <field name="responsible_id" domain="[(''share'', ''='', False)]" widget="many2one_avatar_user" groups="stock.group_stock_user"/>
                    </xpath>
                </data>
            ', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (1081, 100, NULL, 1, 1, 'product.product.stock.tree', 'product.product', NULL, 'tree', 'stock/views/product_views.xml', 'primary', '{"en_US": "<tree sample=\"1\" js_class=\"stock_report_list_view\" duplicate=\"0\">\n                    <field name=\"id\" column_invisible=\"True\"/>\n                    <field name=\"display_name\" string=\"Product\"/>\n                    <field name=\"categ_id\" optional=\"hide\"/>\n                    <field name=\"qty_available\" string=\"On Hand\" sum=\"Total On Hand\"/>\n                    <button name=\"372\" title=\"Inventory Adjustment\" type=\"action\" class=\"btn-link\" icon=\"fa-pencil\" context=\"{''search_default_product_id'': id, ''default_product_id'': id}\"/>\n                    <field name=\"free_qty\" string=\"Free to Use\" sum=\"Total Free to Use\"/>\n                    <field name=\"incoming_qty\" optional=\"show\" sum=\"Total Incoming\"/>\n                    <field name=\"outgoing_qty\" optional=\"show\" sum=\"Total Outgoing\"/>\n                    <field name=\"virtual_available\" string=\"Forecasted\" optional=\"hide\" sum=\"Total Forecasted\"/>\n                    <field name=\"uom_id\" string=\"Unit\" groups=\"uom.group_uom\" options=\"{''no_create'': True}\"/>\n                    <button name=\"381\" string=\"History\" type=\"action\" class=\"btn-link\" icon=\"fa-history\" context=\"{''search_default_product_id'': id, ''default_product_id'': id}\"/>\n                    <button name=\"action_view_orderpoints\" string=\"Replenishment\" type=\"object\" class=\"btn-link\" icon=\"fa-refresh\" context=\"{''search_default_product_id'': id, ''is_stock_report'': True}\"/>\n                    <button name=\"373\" string=\"Locations\" type=\"action\" class=\"btn-link\" groups=\"stock.group_stock_multi_locations\" icon=\"fa-cubes\" context=\"{''search_default_product_id'': id, ''default_product_id'': id}\" invisible=\"qty_available == 0\"/>\n                    <button name=\"action_product_forecast_report\" string=\"Forecast\" type=\"object\" class=\"btn-link\" icon=\"fa-area-chart\" context=\"{''default_product_id'': id}\" invisible=\"incoming_qty == 0 and outgoing_qty == 0\"/>\n                </tree>"}', '<?xml version="1.0"?>
<tree sample="1" js_class="stock_report_list_view" duplicate="0">
                    <field name="id" column_invisible="True"/>
                    <field name="display_name" string="Product"/>
                    <field name="categ_id" optional="hide"/>
                    <field name="qty_available" string="On Hand" sum="Total On Hand"/>
                    <button name="372" title="Inventory Adjustment" type="action" class="btn-link" icon="fa-pencil" context="{''search_default_product_id'': id, ''default_product_id'': id}"/>
                    <field name="free_qty" string="Free to Use" sum="Total Free to Use"/>
                    <field name="incoming_qty" optional="show" sum="Total Incoming"/>
                    <field name="outgoing_qty" optional="show" sum="Total Outgoing"/>
                    <field name="virtual_available" string="Forecasted" optional="hide" sum="Total Forecasted"/>
                    <field name="uom_id" string="Unit" groups="uom.group_uom" options="{''no_create'': True}"/>
                    <button name="381" string="History" type="action" class="btn-link" icon="fa-history" context="{''search_default_product_id'': id, ''default_product_id'': id}"/>
                    <button name="action_view_orderpoints" string="Replenishment" type="object" class="btn-link" icon="fa-refresh" context="{''search_default_product_id'': id, ''is_stock_report'': True}"/>
                    <button name="373" string="Locations" type="action" class="btn-link" groups="stock.group_stock_multi_locations" icon="fa-cubes" context="{''search_default_product_id'': id, ''default_product_id'': id}" invisible="qty_available == 0"/>
                    <button name="action_product_forecast_report" string="Forecast" type="object" class="btn-link" icon="fa-area-chart" context="{''default_product_id'': id}" invisible="incoming_qty == 0 and outgoing_qty == 0"/>
                </tree>
            ', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (1082, 16, 1071, 1, 1, 'product.product.search.stock.form.stock.report', 'product.product', NULL, 'search', 'stock/views/product_views.xml', 'primary', '{"en_US": "<data><filter name=\"services\" position=\"attributes\">\n                    <attribute name=\"invisible\">1</attribute>\n                </filter>\n                <filter name=\"consumable\" position=\"attributes\">\n                    <attribute name=\"invisible\">1</attribute>\n                </filter>\n                <filter name=\"real_stock_negative\" position=\"after\">\n                    <searchpanel>\n                        <field name=\"categ_id\" icon=\"fa-filter\" string=\"Category\" select=\"multi\"/>\n                    </searchpanel>\n                </filter>\n            </data>"}', '<?xml version="1.0"?>
<data><filter name="services" position="attributes">
                    <attribute name="invisible">1</attribute>
                </filter>
                <filter name="consumable" position="attributes">
                    <attribute name="invisible">1</attribute>
                </filter>
                <filter name="real_stock_negative" position="after">
                    <searchpanel>
                        <field name="categ_id" icon="fa-filter" string="Category" select="multi"/>
                    </searchpanel>
                </filter>
            </data>', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (1083, 16, NULL, 1, 1, 'stock.location.form', 'stock.location', NULL, 'form', 'stock/views/stock_location_views.xml', 'primary', '{"en_US": "<form string=\"Stock Location\">\n                <field name=\"company_id\" invisible=\"1\"/>\n                <sheet>\n                    <div class=\"oe_button_box\" name=\"button_box\">\n                        <button string=\"Putaway Rules\" class=\"oe_stat_button\" icon=\"fa-random\" name=\"368\" type=\"action\" groups=\"stock.group_stock_multi_locations\" context=\"{''default_company_id'': company_id}\"/>\n                        <button string=\"Current Stock\" class=\"oe_stat_button\" icon=\"fa-cubes\" name=\"375\" type=\"action\"/>\n                    </div>\n                    <widget name=\"web_ribbon\" title=\"Archived\" bg_color=\"text-bg-danger\" invisible=\"active\"/>\n                    <label for=\"name\"/>\n                    <h1><field name=\"name\" placeholder=\"e.g. Spare Stock\"/></h1>\n                    <label for=\"location_id\"/>\n                    <h2><field name=\"location_id\" placeholder=\"e.g. Physical Locations\" options=\"{''no_create'': True}\"/></h2>\n\n                    <group>\n                        <group string=\"Additional Information\" name=\"additional_info\">\n                            <field name=\"active\" invisible=\"1\"/>\n                            <field name=\"usage\"/>\n                            <field name=\"storage_category_id\" invisible=\"usage != ''internal''\" groups=\"stock.group_stock_storage_categories\"/>\n                            <field name=\"company_id\" groups=\"base.group_multi_company\" options=\"{''no_create'': True}\"/>\n                            <field name=\"scrap_location\" invisible=\"usage not in (''inventory'', ''internal'')\"/>\n                            <field name=\"return_location\"/>\n                            <field name=\"replenish_location\" invisible=\"usage != ''internal''\"/>\n                        </group>\n                        <group string=\"Cyclic Counting\" invisible=\"usage not in (''internal'', ''transit'') or not company_id\">\n                            <field name=\"cyclic_inventory_frequency\"/>\n                            <field name=\"last_inventory_date\"/>\n                            <field name=\"next_inventory_date\" invisible=\"not active\"/>\n                        </group>\n                        <group string=\"Logistics\" groups=\"stock.group_adv_location\">\n                            <field name=\"removal_strategy_id\" options=\"{''no_create'': True}\" invisible=\"usage in (''supplier'', ''customer'', ''inventory'', ''production'') or scrap_location or usage == ''transit'' and not company_id\"/>\n                        </group>\n                    </group>\n                    <field name=\"comment\" placeholder=\"External note...\"/>\n                </sheet>\n            </form>"}', '<?xml version="1.0"?>
<form string="Stock Location">
                <field name="company_id" invisible="1"/>
                <sheet>
                    <div class="oe_button_box" name="button_box">
                        <button string="Putaway Rules" class="oe_stat_button" icon="fa-random" name="368" type="action" groups="stock.group_stock_multi_locations" context="{''default_company_id'': company_id}"/>
                        <button string="Current Stock" class="oe_stat_button" icon="fa-cubes" name="375" type="action"/>
                    </div>
                    <widget name="web_ribbon" title="Archived" bg_color="text-bg-danger" invisible="active"/>
                    <label for="name"/>
                    <h1><field name="name" placeholder="e.g. Spare Stock"/></h1>
                    <label for="location_id"/>
                    <h2><field name="location_id" placeholder="e.g. Physical Locations" options="{''no_create'': True}"/></h2>

                    <group>
                        <group string="Additional Information" name="additional_info">
                            <field name="active" invisible="1"/>
                            <field name="usage"/>
                            <field name="storage_category_id" invisible="usage != ''internal''" groups="stock.group_stock_storage_categories"/>
                            <field name="company_id" groups="base.group_multi_company" options="{''no_create'': True}"/>
                            <field name="scrap_location" invisible="usage not in (''inventory'', ''internal'')"/>
                            <field name="return_location"/>
                            <field name="replenish_location" invisible="usage != ''internal''"/>
                        </group>
                        <group string="Cyclic Counting" invisible="usage not in (''internal'', ''transit'') or not company_id">
                            <field name="cyclic_inventory_frequency"/>
                            <field name="last_inventory_date"/>
                            <field name="next_inventory_date" invisible="not active"/>
                        </group>
                        <group string="Logistics" groups="stock.group_adv_location">
                            <field name="removal_strategy_id" options="{''no_create'': True}" invisible="usage in (''supplier'', ''customer'', ''inventory'', ''production'') or scrap_location or usage == ''transit'' and not company_id"/>
                        </group>
                    </group>
                    <field name="comment" placeholder="External note..."/>
                </sheet>
            </form>
        ', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (1084, 16, 1083, 1, 1, 'stock.location.form.editable', 'stock.location', NULL, 'form', 'stock/views/stock_location_views.xml', 'extension', '{"en_US": "<xpath expr=\"//form\" position=\"attributes\">\n                <attribute name=\"create\">false</attribute>\n            </xpath>"}', '<?xml version="1.0"?>
<xpath expr="//form" position="attributes">
