INSERT INTO public.ir_ui_view VALUES (1085, 16, NULL, 1, 1, 'stock.location.search', 'stock.location', NULL, 'search', 'stock/views/stock_location_views.xml', 'primary', '{"en_US": "<search string=\"Stock Locations\">\n                <field name=\"complete_name\" string=\"Stock Locations\"/>\n                <filter name=\"in_location\" string=\"Internal\" domain=\"[(''usage'', ''='', ''internal'')]\" help=\"Internal Locations\"/>\n                <filter name=\"customer\" string=\"Customer\" domain=\"[(''usage'', ''='', ''customer'')]\" help=\"Customer Locations\"/>\n                <filter name=\"prod_inv_location\" string=\"Production\" domain=\"[(''usage'', ''in'', [''inventory'', ''production''])]\" help=\"Production Locations\"/>\n                <filter name=\"supplier\" string=\"Vendor\" domain=\"[(''usage'', ''='', ''supplier'')]\" help=\"Vendor Locations\"/>\n                <field name=\"location_id\" string=\"Parent Location\"/>\n                <field name=\"usage\" string=\"Location Type\"/>\n                <field name=\"warehouse_id\" string=\"Warehouse\"/>\n                <separator/>\n                <filter string=\"Archived\" name=\"inactive\" domain=\"[(''active'',''='',False)]\"/>\n                <group expand=\"0\" string=\"Group By\">\n                    <filter string=\"Warehouse\" name=\"warehouse\" domain=\"[]\" context=\"{''group_by'': ''warehouse_id''}\"/>\n                    <filter string=\"Location Type\" name=\"usage\" domain=\"[]\" context=\"{''group_by'': ''usage''}\"/>\n                </group>\n            </search>"}', '<?xml version="1.0"?>
<search string="Stock Locations">
                <field name="complete_name" string="Stock Locations"/>
                <filter name="in_location" string="Internal" domain="[(''usage'', ''='', ''internal'')]" help="Internal Locations"/>
                <filter name="customer" string="Customer" domain="[(''usage'', ''='', ''customer'')]" help="Customer Locations"/>
                <filter name="prod_inv_location" string="Production" domain="[(''usage'', ''in'', [''inventory'', ''production''])]" help="Production Locations"/>
                <filter name="supplier" string="Vendor" domain="[(''usage'', ''='', ''supplier'')]" help="Vendor Locations"/>
                <field name="location_id" string="Parent Location"/>
                <field name="usage" string="Location Type"/>
                <field name="warehouse_id" string="Warehouse"/>
                <separator/>
                <filter string="Archived" name="inactive" domain="[(''active'',''='',False)]"/>
                <group expand="0" string="Group By">
                    <filter string="Warehouse" name="warehouse" domain="[]" context="{''group_by'': ''warehouse_id''}"/>
                    <filter string="Location Type" name="usage" domain="[]" context="{''group_by'': ''usage''}"/>
                </group>
            </search>
        ', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (1086, 2, NULL, 1, 1, 'stock.location.tree', 'stock.location', NULL, 'tree', 'stock/views/stock_location_views.xml', 'primary', '{"en_US": "<tree string=\"Stock Location\" decoration-info=\"usage==''view''\" decoration-danger=\"usage==''internal''\" multi_edit=\"1\">\n                <field name=\"company_id\" column_invisible=\"True\"/>\n                <field name=\"active\" column_invisible=\"True\"/>\n                <field name=\"complete_name\" string=\"Location\"/>\n                <field name=\"usage\"/>\n                <field name=\"storage_category_id\" readonly=\"usage != ''internal''\" groups=\"stock.group_stock_storage_categories\"/>\n                <field name=\"company_id\" groups=\"base.group_multi_company\"/>\n            </tree>"}', '<?xml version="1.0"?>
<tree string="Stock Location" decoration-info="usage==''view''" decoration-danger="usage==''internal''" multi_edit="1">
                <field name="company_id" column_invisible="True"/>
                <field name="active" column_invisible="True"/>
                <field name="complete_name" string="Location"/>
                <field name="usage"/>
                <field name="storage_category_id" readonly="usage != ''internal''" groups="stock.group_stock_storage_categories"/>
                <field name="company_id" groups="base.group_multi_company"/>
            </tree>
        ', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (1087, 16, 1086, 1, 1, 'stock.location.tree2.editable', 'stock.location', NULL, 'tree', 'stock/views/stock_location_views.xml', 'extension', '{"en_US": "<xpath expr=\"//tree\" position=\"attributes\">\n                <attribute name=\"create\">false</attribute>\n            </xpath>"}', '<?xml version="1.0"?>
