INSERT INTO public.ir_ui_view VALUES (1088, 16, NULL, 1, 1, 'stock.location.route.tree', 'stock.route', NULL, 'tree', 'stock/views/stock_location_views.xml', 'primary', '{"en_US": "<tree string=\"Routes\">\n                    <field name=\"sequence\" widget=\"handle\"/>\n                    <field name=\"name\"/>\n                    <field name=\"active\" column_invisible=\"True\"/>\n                    <field name=\"company_id\" groups=\"base.group_multi_company\"/>\n                </tree>"}', '<?xml version="1.0"?>
