INSERT INTO public.ir_ui_view VALUES (1089, 7, NULL, 1, 1, 'stock.location.route.form', 'stock.route', NULL, 'form', 'stock/views/stock_location_views.xml', 'primary', '{"en_US": "<form string=\"Route\">\n                    <field name=\"company_id\" invisible=\"1\"/>\n                    <sheet>\n                        <widget name=\"web_ribbon\" title=\"Archived\" bg_color=\"text-bg-danger\" invisible=\"active\"/>\n                        <div class=\"oe_title\">\n                            <label for=\"name\"/>\n                            <h1><field name=\"name\" placeholder=\"e.g. Two-steps reception\"/></h1>\n                        </div>\n                    <group>\n                        <group>\n                            <field name=\"sequence\" string=\"Sequence\" groups=\"base.group_no_one\"/>\n                            <field name=\"supplied_wh_id\" groups=\"base.group_no_one\"/>\n                            <field name=\"active\" invisible=\"1\"/>\n                            <field name=\"company_id\" groups=\"base.group_multi_company\" options=\"{''no_create'': True}\"/>\n                        </group>\n                    </group>\n                    <group string=\"Applicable On\" name=\"route_selector\">\n                        <p colspan=\"2\" class=\"oe_grey\">Select the places where this route can be selected</p>\n                        <group>\n                            <field name=\"product_categ_selectable\" string=\"Product Categories\"/>\n                            <field name=\"product_selectable\" string=\"Products\"/>\n                            <field name=\"packaging_selectable\" string=\"Packagings\" groups=\"product.group_stock_packaging\"/>\n                        </group>\n                        <group>\n                            <label for=\"warehouse_selectable\" string=\"Warehouses\"/>\n                            <div class=\"o_row\">\n                                <field name=\"warehouse_selectable\" class=\"oe_inline\" nolabel=\"1\"/>\n                                <field name=\"warehouse_domain_ids\" invisible=\"1\"/>\n                                <field name=\"warehouse_ids\" widget=\"many2many_tags\" class=\"o_field_highlighted\" placeholder=\"e.g. Central Warehouse\" nolabel=\"1\" invisible=\"not warehouse_selectable\"/>\n                            </div>\n                        </group>\n                    </group>\n                    <group string=\"Rules\">\n                        <field name=\"rule_ids\" colspan=\"2\" nolabel=\"1\" context=\"{''default_company_id'': company_id, ''form_view_ref'':''stock.view_route_rule_form''}\">\n                            <tree>\n                                <field name=\"sequence\" widget=\"handle\"/>\n                                <field name=\"action\"/>\n                                <field name=\"location_src_id\" options=\"{''no_create'': True}\"/>\n                                <field name=\"location_dest_id\" options=\"{''no_create'': True}\"/>\n                            </tree>\n                        </field>\n                    </group>\n                    </sheet>\n                </form>"}', '<?xml version="1.0"?>
<form string="Route">
                    <field name="company_id" invisible="1"/>
                    <sheet>
                        <widget name="web_ribbon" title="Archived" bg_color="text-bg-danger" invisible="active"/>
                        <div class="oe_title">
                            <label for="name"/>
                            <h1><field name="name" placeholder="e.g. Two-steps reception"/></h1>
                        </div>
                    <group>
                        <group>
                            <field name="sequence" string="Sequence" groups="base.group_no_one"/>
                            <field name="supplied_wh_id" groups="base.group_no_one"/>
                            <field name="active" invisible="1"/>
                            <field name="company_id" groups="base.group_multi_company" options="{''no_create'': True}"/>
                        </group>
                    </group>
                    <group string="Applicable On" name="route_selector">
                        <p colspan="2" class="oe_grey">Select the places where this route can be selected</p>
                        <group>
                            <field name="product_categ_selectable" string="Product Categories"/>
                            <field name="product_selectable" string="Products"/>
                            <field name="packaging_selectable" string="Packagings" groups="product.group_stock_packaging"/>
                        </group>
                        <group>
                            <label for="warehouse_selectable" string="Warehouses"/>
                            <div class="o_row">
                                <field name="warehouse_selectable" class="oe_inline" nolabel="1"/>
                                <field name="warehouse_domain_ids" invisible="1"/>
                                <field name="warehouse_ids" widget="many2many_tags" class="o_field_highlighted" placeholder="e.g. Central Warehouse" nolabel="1" invisible="not warehouse_selectable"/>
                            </div>
                        </group>
                    </group>
                    <group string="Rules">
                        <field name="rule_ids" colspan="2" nolabel="1" context="{''default_company_id'': company_id, ''form_view_ref'':''stock.view_route_rule_form''}">
                            <tree>
                                <field name="sequence" widget="handle"/>
                                <field name="action"/>
                                <field name="location_src_id" options="{''no_create'': True}"/>
                                <field name="location_dest_id" options="{''no_create'': True}"/>
                            </tree>
                        </field>
                    </group>
                    </sheet>
                </form>
            ', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (1090, 16, NULL, 1, 1, 'stock.location.route.search', 'stock.route', NULL, 'search', 'stock/views/stock_location_views.xml', 'primary', '{"en_US": "<search string=\"Route\">\n                    <field name=\"name\"/>\n                    <filter string=\"Archived\" name=\"inactive\" domain=\"[(''active'',''='',False)]\"/>\n                </search>"}', '<?xml version="1.0"?>
