                    <filter string="Archived" name="inactive" domain="[(''active'',''='',False)]"/>
                </search>
            ', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (1091, 16, NULL, 1, 1, 'stock.warehouse.orderpoint.kanban', 'stock.warehouse.orderpoint', NULL, 'kanban', 'stock/views/stock_orderpoint_views.xml', 'primary', '{"en_US": "<kanban class=\"o_kanban_mobile\">\n                <field name=\"name\"/>\n                <field name=\"product_id\"/>\n                <field name=\"trigger\"/>\n                <field name=\"product_min_qty\"/>\n                <field name=\"product_max_qty\"/>\n                <templates>\n                    <t t-name=\"kanban-box\">\n                        <div t-attf-class=\"oe_kanban_global_click\">\n                            <div class=\"o_kanban_record_top\">\n                                <div class=\"o_kanban_record_headings\">\n                                    <strong class=\"o_kanban_record_title\"><t t-esc=\"record.name.value\"/></strong>\n                                </div>\n                                <span class=\"badge rounded-pill\"><strong>Min qty:</strong><t t-esc=\"record.product_min_qty.value\"/></span>\n                            </div>\n                            <div class=\"o_kanban_record_bottom\">\n                                <div class=\"oe_kanban_bottom_left\">\n                                    <span><t t-esc=\"record.product_id.value\"/></span>\n                                </div>\n                                <div class=\"oe_kanban_bottom_right\">\n                                    <span class=\"badge rounded-pill\"><strong>Max qty:</strong><t t-esc=\"record.product_max_qty.value\"/></span>\n                                </div>\n                            </div>\n                        </div>\n                    </t>\n                </templates>\n            </kanban>"}', '<?xml version="1.0"?>
<kanban class="o_kanban_mobile">
                <field name="name"/>
                <field name="product_id"/>
                <field name="trigger"/>
                <field name="product_min_qty"/>
                <field name="product_max_qty"/>
                <templates>
                    <t t-name="kanban-box">
                        <div t-attf-class="oe_kanban_global_click">
                            <div class="o_kanban_record_top">
                                <div class="o_kanban_record_headings">
                                    <strong class="o_kanban_record_title"><t t-esc="record.name.value"/></strong>
                                </div>
                                <span class="badge rounded-pill"><strong>Min qty:</strong><t t-esc="record.product_min_qty.value"/></span>
                            </div>
                            <div class="o_kanban_record_bottom">
                                <div class="oe_kanban_bottom_left">
                                    <span><t t-esc="record.product_id.value"/></span>
                                </div>
                                <div class="oe_kanban_bottom_right">
                                    <span class="badge rounded-pill"><strong>Max qty:</strong><t t-esc="record.product_max_qty.value"/></span>
                                </div>
                            </div>
                        </div>
                    </t>
                </templates>
            </kanban>
        ', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (1092, 16, NULL, 1, 1, 'stock.warehouse.orderpoint.tree.editable', 'stock.warehouse.orderpoint', NULL, 'tree', 'stock/views/stock_orderpoint_views.xml', 'primary', '{"en_US": "<tree string=\"Reordering Rules\" editable=\"bottom\" js_class=\"stock_orderpoint_list\" sample=\"1\" multi_edit=\"1\" export_xlsx=\"0\">\n                <field name=\"active\" column_invisible=\"True\"/>\n                <field name=\"company_id\" column_invisible=\"True\"/>\n                <field name=\"product_category_id\" column_invisible=\"True\"/>\n                <field name=\"product_tmpl_id\" column_invisible=\"True\"/>\n                <field name=\"unwanted_replenish\" column_invisible=\"True\"/>\n                <field name=\"product_id\" readonly=\"product_id\" force_save=\"1\" context=\"{''default_detailed_type'': ''product''}\"/>\n                <field name=\"location_id\" options=\"{''no_create'': True}\" groups=\"stock.group_stock_multi_locations\"/>\n                <field name=\"warehouse_id\" options=\"{''no_create'': True}\" groups=\"stock.group_stock_multi_warehouses\" optional=\"hide\"/>\n                <field name=\"qty_on_hand\" force_save=\"1\"/>\n                <field name=\"qty_forecast\" force_save=\"1\"/>\n                <button name=\"action_product_forecast_report\" type=\"object\" icon=\"fa-area-chart\" title=\"Forecast Report\" invisible=\"not id or unwanted_replenish\"/>\n                <button name=\"action_product_forecast_report\" type=\"object\" icon=\"fa-warning text-warning\" title=\"Due to receipts scheduled in the future, you might end up with excessive stock . Check the Forecasted Report  before reordering\" invisible=\"not id or not unwanted_replenish\"/>\n                <field name=\"visibility_days\" optional=\"hidden\"/>\n                <field name=\"route_id\" options=\"{''no_create'': True, ''no_open'': True}\" optional=\"hidden\"/>\n                <button name=\"action_stock_replenishment_info\" type=\"object\" icon=\"fa-info-circle\" title=\"Replenishment Information\" invisible=\"not id\"/>\n                <field name=\"trigger\" optional=\"hide\"/>\n                <field name=\"group_id\" optional=\"hide\" groups=\"stock.group_adv_location\"/>\n                <field name=\"product_min_qty\" optional=\"show\"/>\n                <field name=\"product_max_qty\" optional=\"show\"/>\n                <field name=\"qty_multiple\" optional=\"hide\"/>\n                <field name=\"qty_to_order\"/>\n                <field name=\"product_uom_name\" string=\"UoM\" groups=\"uom.group_uom\"/>\n                <field name=\"company_id\" optional=\"hide\" readonly=\"1\" groups=\"base.group_multi_company\"/>\n                <button name=\"action_replenish\" string=\"Order Once\" type=\"object\" class=\"o_replenish_buttons\" icon=\"fa-truck\" invisible=\"qty_to_order &lt;= 0.0\"/>\n                <button name=\"action_replenish_auto\" string=\"Automate\" type=\"object\" class=\"o_replenish_buttons\" icon=\"fa-refresh\" invisible=\"qty_to_order &lt;= 0.0 or trigger == ''auto''\"/>\n                <button name=\"364\" string=\"Snooze\" type=\"action\" class=\"text-warning\" icon=\"fa-bell-slash\" invisible=\"trigger != ''manual''\" context=\"{''default_orderpoint_ids'': [id]}\"/>\n            </tree>"}', '<?xml version="1.0"?>
<tree string="Reordering Rules" editable="bottom" js_class="stock_orderpoint_list" sample="1" multi_edit="1" export_xlsx="0">
                <field name="active" column_invisible="True"/>
                <field name="company_id" column_invisible="True"/>
                <field name="product_category_id" column_invisible="True"/>
                <field name="product_tmpl_id" column_invisible="True"/>
                <field name="unwanted_replenish" column_invisible="True"/>
                <field name="product_id" readonly="product_id" force_save="1" context="{''default_detailed_type'': ''product''}"/>
                <field name="location_id" options="{''no_create'': True}" groups="stock.group_stock_multi_locations"/>
                <field name="warehouse_id" options="{''no_create'': True}" groups="stock.group_stock_multi_warehouses" optional="hide"/>
                <field name="qty_on_hand" force_save="1"/>
                <field name="qty_forecast" force_save="1"/>
                <button name="action_product_forecast_report" type="object" icon="fa-area-chart" title="Forecast Report" invisible="not id or unwanted_replenish"/>
                <button name="action_product_forecast_report" type="object" icon="fa-warning text-warning" title="Due to receipts scheduled in the future, you might end up with excessive stock . Check the Forecasted Report  before reordering" invisible="not id or not unwanted_replenish"/>
                <field name="visibility_days" optional="hidden"/>
                <field name="route_id" options="{''no_create'': True, ''no_open'': True}" optional="hidden"/>
                <button name="action_stock_replenishment_info" type="object" icon="fa-info-circle" title="Replenishment Information" invisible="not id"/>
                <field name="trigger" optional="hide"/>
                <field name="group_id" optional="hide" groups="stock.group_adv_location"/>
                <field name="product_min_qty" optional="show"/>
                <field name="product_max_qty" optional="show"/>
                <field name="qty_multiple" optional="hide"/>
                <field name="qty_to_order"/>
                <field name="product_uom_name" string="UoM" groups="uom.group_uom"/>
                <field name="company_id" optional="hide" readonly="1" groups="base.group_multi_company"/>
                <button name="action_replenish" string="Order Once" type="object" class="o_replenish_buttons" icon="fa-truck" invisible="qty_to_order &lt;= 0.0"/>
                <button name="action_replenish_auto" string="Automate" type="object" class="o_replenish_buttons" icon="fa-refresh" invisible="qty_to_order &lt;= 0.0 or trigger == ''auto''"/>
                <button name="364" string="Snooze" type="action" class="text-warning" icon="fa-bell-slash" invisible="trigger != ''manual''" context="{''default_orderpoint_ids'': [id]}"/>
            </tree>
        ', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (1093, 16, NULL, 1, 1, 'stock.warehouse.orderpoint.reorder.search', 'stock.warehouse.orderpoint', NULL, 'search', 'stock/views/stock_orderpoint_views.xml', 'primary', '{"en_US": "<search string=\"Replenishment Report Search\">\n                <field name=\"product_id\"/>\n                <field name=\"trigger\"/>\n                <field name=\"product_category_id\"/>\n                <field name=\"group_id\" groups=\"stock.group_adv_location\"/>\n                <field name=\"warehouse_id\" groups=\"stock.group_stock_multi_warehouses\"/>\n                <field name=\"location_id\" groups=\"stock.group_stock_multi_locations\"/>\n                <field name=\"name\" string=\"Reordering Rule\"/>\n                <filter string=\"Trigger Manual\" name=\"filter_creation_trigger\" domain=\"[(''trigger'', ''='', ''manual'')]\"/>\n                <separator/>\n                <filter string=\"To Reorder\" name=\"filter_to_reorder\" domain=\"[(''qty_to_order'', ''&gt;'', 0.0)]\"/>\n                <separator/>\n                <filter string=\"Not Snoozed\" name=\"filter_not_snoozed\" domain=\"[''|'', (''snoozed_until'', ''='', False), (''snoozed_until'', ''&lt;='', datetime.date.today().strftime(''%Y-%m-%d''))]\"/>\n                <group expand=\"0\" string=\"Group By\">\n                    <filter string=\"Warehouse\" name=\"groupby_warehouse\" domain=\"[]\" context=\"{''group_by'': ''warehouse_id''}\" groups=\"stock.group_stock_multi_warehouses\"/>\n                    <filter string=\"Location\" name=\"groupby_location\" domain=\"[]\" context=\"{''group_by'': ''location_id''}\" groups=\"stock.group_stock_multi_locations\"/>\n                    <filter string=\"Product\" name=\"groupby_product\" domain=\"[]\" context=\"{''group_by'': ''product_id''}\"/>\n                    <filter string=\"Category\" name=\"groupby_category\" domain=\"[]\" context=\"{''group_by'': ''product_category_id''}\"/>\n                </group>\n                <searchpanel>\n                    <field name=\"location_id\" string=\"Locations\" groups=\"stock.group_stock_multi_locations\" enable_counters=\"1\"/>\n                    <field name=\"trigger\" string=\"Trigger\" enable_counters=\"1\"/>\n                </searchpanel>\n            </search>"}', '<?xml version="1.0"?>
<search string="Replenishment Report Search">
                <field name="product_id"/>
                <field name="trigger"/>
                <field name="product_category_id"/>
                <field name="group_id" groups="stock.group_adv_location"/>
                <field name="warehouse_id" groups="stock.group_stock_multi_warehouses"/>
                <field name="location_id" groups="stock.group_stock_multi_locations"/>
                <field name="name" string="Reordering Rule"/>
                <filter string="Trigger Manual" name="filter_creation_trigger" domain="[(''trigger'', ''='', ''manual'')]"/>
                <separator/>
                <filter string="To Reorder" name="filter_to_reorder" domain="[(''qty_to_order'', ''&gt;'', 0.0)]"/>
                <separator/>
                <filter string="Not Snoozed" name="filter_not_snoozed" domain="[''|'', (''snoozed_until'', ''='', False), (''snoozed_until'', ''&lt;='', datetime.date.today().strftime(''%Y-%m-%d''))]"/>
                <group expand="0" string="Group By">
                    <filter string="Warehouse" name="groupby_warehouse" domain="[]" context="{''group_by'': ''warehouse_id''}" groups="stock.group_stock_multi_warehouses"/>
                    <filter string="Location" name="groupby_location" domain="[]" context="{''group_by'': ''location_id''}" groups="stock.group_stock_multi_locations"/>
                    <filter string="Product" name="groupby_product" domain="[]" context="{''group_by'': ''product_id''}"/>
                    <filter string="Category" name="groupby_category" domain="[]" context="{''group_by'': ''product_category_id''}"/>
                </group>
                <searchpanel>
                    <field name="location_id" string="Locations" groups="stock.group_stock_multi_locations" enable_counters="1"/>
                    <field name="trigger" string="Trigger" enable_counters="1"/>
                </searchpanel>
            </search>
        ', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (1094, 16, NULL, 1, 1, 'stock.warehouse.orderpoint.search', 'stock.warehouse.orderpoint', NULL, 'search', 'stock/views/stock_orderpoint_views.xml', 'primary', '{"en_US": "<search string=\"Reordering Rules Search\">\n                <field name=\"product_id\"/>\n                <field name=\"name\" string=\"Reordering Rule\"/>\n                <field name=\"trigger\"/>\n                <field name=\"group_id\" groups=\"stock.group_adv_location\"/>\n                <field name=\"warehouse_id\" groups=\"stock.group_stock_multi_warehouses\"/>\n                <field name=\"location_id\" groups=\"stock.group_stock_multi_locations\"/>\n                <filter string=\"Archived\" name=\"inactive\" domain=\"[(''active'', ''='', False)]\"/>\n                <group expand=\"0\" string=\"Group By\">\n                    <filter string=\"Warehouse\" name=\"warehouse\" domain=\"[]\" context=\"{''group_by'': ''warehouse_id''}\" groups=\"stock.group_stock_multi_warehouses\"/>\n                    <filter string=\"Location\" name=\"location\" domain=\"[]\" context=\"{''group_by'': ''location_id''}\" groups=\"stock.group_stock_multi_locations\"/>\n                    <filter string=\"Product\" name=\"product\" domain=\"[]\" context=\"{''group_by'': ''product_id''}\"/>\n                </group>\n            </search>"}', '<?xml version="1.0"?>
<search string="Reordering Rules Search">
