INSERT INTO public.ir_ui_view VALUES (1095, 16, NULL, 1, 1, 'stock.warehouse.orderpoint.form', 'stock.warehouse.orderpoint', NULL, 'form', 'stock/views/stock_orderpoint_views.xml', 'primary', '{"en_US": "<form string=\"Reordering Rules\">\n                <div class=\"alert alert-info\" role=\"alert\">\n                    <a style=\"cursor: pointer\" class=\"alert-link o_form_uri\" type=\"action\" name=\"359\">Run the scheduler</a> manually to trigger the reordering rules right now.\n                </div>\n                <sheet>\n                    <widget name=\"web_ribbon\" title=\"Archived\" bg_color=\"text-bg-danger\" invisible=\"active\"/>\n                    <div class=\"oe_title\">\n                        <h1>\n                            <field name=\"name\"/>\n                        </h1>\n                    </div>\n                    <group>\n                        <group>\n                            <field name=\"active\" invisible=\"1\"/>\n                            <field name=\"company_id\" invisible=\"1\"/>\n                            <field name=\"route_id\" invisible=\"1\"/>\n                            <field name=\"product_id\"/>\n                            <label for=\"product_min_qty\"/>\n                            <div class=\"o_row\">\n                                <field name=\"product_min_qty\"/>\n                                <field name=\"product_uom_name\"/>\n                                <button name=\"stock.action_stock_replenishment_info\" string=\"Forecast Description\" type=\"action\" icon=\"fa-area-chart\" invisible=\"not id\"/>\n                            </div>\n                            <label for=\"product_max_qty\"/>\n                            <div class=\"o_row\">\n                                <field name=\"product_max_qty\"/>\n                                <field name=\"product_uom_name\"/>\n                            </div>\n                            <field name=\"qty_multiple\" string=\"Quantity Multiple\"/>\n                        </group>\n                        <group>\n                            <field name=\"allowed_location_ids\" invisible=\"1\"/>\n                            <field name=\"warehouse_id\" options=\"{''no_open'': True, ''no_create'': True}\" groups=\"stock.group_stock_multi_locations\"/>\n                            <field name=\"location_id\" options=\"{''no_create'': True}\" groups=\"stock.group_stock_multi_locations\" domain=\"[(''id'', ''in'', allowed_location_ids)]\"/>\n                            <label for=\"group_id\" groups=\"base.group_no_one\"/>\n                            <div groups=\"base.group_no_one\">\n                                <field name=\"group_id\" groups=\"stock.group_adv_location\"/>\n                            </div>\n                            <field name=\"company_id\" groups=\"base.group_multi_company\" options=\"{''no_create'': True}\"/>\n                            <field name=\"visibility_days\"/>\n                        </group>\n                    </group>\n                </sheet>\n            </form>"}', '<?xml version="1.0"?>
<form string="Reordering Rules">
                <div class="alert alert-info" role="alert">
                    <a style="cursor: pointer" class="alert-link o_form_uri" type="action" name="359">Run the scheduler</a> manually to trigger the reordering rules right now.
                </div>
                <sheet>
                    <widget name="web_ribbon" title="Archived" bg_color="text-bg-danger" invisible="active"/>
                    <div class="oe_title">
                        <h1>
                            <field name="name"/>
                        </h1>
                    </div>
                    <group>
                        <group>
                            <field name="active" invisible="1"/>
                            <field name="company_id" invisible="1"/>
                            <field name="route_id" invisible="1"/>
                            <field name="product_id"/>
                            <label for="product_min_qty"/>
                            <div class="o_row">
                                <field name="product_min_qty"/>
                                <field name="product_uom_name"/>
                                <button name="stock.action_stock_replenishment_info" string="Forecast Description" type="action" icon="fa-area-chart" invisible="not id"/>
                            </div>
                            <label for="product_max_qty"/>
                            <div class="o_row">
                                <field name="product_max_qty"/>
                                <field name="product_uom_name"/>
                            </div>
                            <field name="qty_multiple" string="Quantity Multiple"/>
                        </group>
                        <group>
                            <field name="allowed_location_ids" invisible="1"/>
                            <field name="warehouse_id" options="{''no_open'': True, ''no_create'': True}" groups="stock.group_stock_multi_locations"/>
                            <field name="location_id" options="{''no_create'': True}" groups="stock.group_stock_multi_locations" domain="[(''id'', ''in'', allowed_location_ids)]"/>
                            <label for="group_id" groups="base.group_no_one"/>
                            <div groups="base.group_no_one">
                                <field name="group_id" groups="stock.group_adv_location"/>
                            </div>
                            <field name="company_id" groups="base.group_multi_company" options="{''no_create'': True}"/>
                            <field name="visibility_days"/>
                        </group>
                    </group>
                </sheet>
            </form>
        ', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (1103, 16, NULL, 1, 1, 'message_body', NULL, 'stock.message_body', 'qweb', 'stock/views/stock_template.xml', 'primary', '{"en_US": "<t t-name=\"stock.message_body\">\n        <ul>\n            <li>\n                <t t-esc=\"move.product_id.display_name\"/>:\n            </li>\n            <t t-if=\"move.state != ''done''\">\n                <t t-if=\"''product_uom_qty'' in vals\">\n                    <li>\n                        Quantity: <t t-esc=\"move.product_uom_qty\"/> -&gt; <t t-esc=\"float(vals.get(''product_uom_qty''))\"/>\n                    </li>\n                </t>\n            </t>\n            <t t-if=\"''quantity'' in vals\">\n                <li>\n                    Quantity: <t t-esc=\"move.quantity\"/> -&gt; <t t-esc=\"float(vals.get(''quantity''))\"/>\n                </li>\n            </t>\n            <t t-if=\"''location_id'' in vals\">\n                <li>\n                    Source Location:\n                    <t t-if=\"move.location_id\">\n                        <t t-esc=\"move.location_id.name\"/> -&gt;\n                    </t>\n                    <t t-esc=\"vals[''location_name'']\"/>\n                </li>\n            </t>\n            <t t-if=\"''location_dest_id'' in vals\">\n                <li>\n                    Destination Location:\n                    <t t-if=\"move.location_dest_id\">\n                        <t t-esc=\"move.location_dest_id.name\"/> -&gt;\n                    </t>\n                    <t t-esc=\"vals[''location_dest_name'']\"/>\n                </li>\n            </t>\n            <t t-if=\"''lot_name'' in vals\">\n                <li>\n                    Lot/Serial:\n                    <t t-if=\"move.lot_id\">\n                        <t t-esc=\"move.lot_id.name\"/> -&gt;\n                    </t>\n                    <t t-esc=\"vals[''lot_name'']\"/>\n                </li>\n            </t>\n            <t t-if=\"''package_name'' in vals\">\n                <li>\n                    Source Package:\n                    <t t-if=\"move.package_id\">\n                        <t t-esc=\"move.package_id.name\"/> -&gt;\n                    </t>\n                    <t t-esc=\"vals[''package_name'']\"/>\n                </li>\n            </t>\n            <t t-if=\"''result_package_name'' in vals\">\n                <li>\n                    Destination Package:\n                    <t t-if=\"move.result_package_id\">\n                        <t t-esc=\"move.result_package_id.name\"/> -&gt;\n                    </t>\n                    <t t-esc=\"vals[''result_package_name'']\"/>\n                </li>\n            </t>\n            <t t-if=\"''owner_name'' in vals\">\n                <li>\n                    Owner:\n                    <t t-if=\"move.owner_id\">\n                        <t t-esc=\"move.owner_id.name\"/> -&gt;\n                    </t>\n                    <t t-esc=\"vals[''owner_name'']\"/>\n                </li>\n            </t>\n        </ul>\n    </t>"}', '<?xml version="1.0"?>
<t t-name="stock.message_body">
        <ul>
            <li>
                <t t-esc="move.product_id.display_name"/>:
            </li>
            <t t-if="move.state != ''done''">
                <t t-if="''product_uom_qty'' in vals">
                    <li>
                        Quantity: <t t-esc="move.product_uom_qty"/> -&gt; <t t-esc="float(vals.get(''product_uom_qty''))"/>
                    </li>
                </t>
            </t>
            <t t-if="''quantity'' in vals">
                <li>
                    Quantity: <t t-esc="move.quantity"/> -&gt; <t t-esc="float(vals.get(''quantity''))"/>
                </li>
            </t>
            <t t-if="''location_id'' in vals">
                <li>
                    Source Location:
                    <t t-if="move.location_id">
                        <t t-esc="move.location_id.name"/> -&gt;
                    </t>
                    <t t-esc="vals[''location_name'']"/>
                </li>
            </t>
            <t t-if="''location_dest_id'' in vals">
                <li>
                    Destination Location:
                    <t t-if="move.location_dest_id">
                        <t t-esc="move.location_dest_id.name"/> -&gt;
                    </t>
                    <t t-esc="vals[''location_dest_name'']"/>
                </li>
            </t>
            <t t-if="''lot_name'' in vals">
                <li>
                    Lot/Serial:
                    <t t-if="move.lot_id">
                        <t t-esc="move.lot_id.name"/> -&gt;
                    </t>
                    <t t-esc="vals[''lot_name'']"/>
                </li>
            </t>
            <t t-if="''package_name'' in vals">
                <li>
                    Source Package:
                    <t t-if="move.package_id">
                        <t t-esc="move.package_id.name"/> -&gt;
                    </t>
                    <t t-esc="vals[''package_name'']"/>
                </li>
            </t>
            <t t-if="''result_package_name'' in vals">
                <li>
                    Destination Package:
                    <t t-if="move.result_package_id">
                        <t t-esc="move.result_package_id.name"/> -&gt;
                    </t>
                    <t t-esc="vals[''result_package_name'']"/>
                </li>
            </t>
            <t t-if="''owner_name'' in vals">
                <li>
                    Owner:
                    <t t-if="move.owner_id">
                        <t t-esc="move.owner_id.name"/> -&gt;
                    </t>
                    <t t-esc="vals[''owner_name'']"/>
                </li>
            </t>
        </ul>
    </t>
', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (1096, 16, NULL, 1, 1, 'stock.storage.category.form', 'stock.storage.category', NULL, 'form', 'stock/views/stock_storage_category_views.xml', 'primary', '{"en_US": "<form string=\"Storage Category\">\n                <field name=\"company_id\" invisible=\"1\"/>\n                <sheet>\n                    <div class=\"oe_button_box\" name=\"button_box\">\n                        <button name=\"407\" string=\"Locations\" type=\"action\" class=\"oe_stat_button\" icon=\"oi-arrows-v\"/>\n                    </div>\n                    <group>\n                        <group>\n                            <field name=\"name\"/>\n                            <field name=\"allow_new_product\"/>\n                        </group>\n                        <group>\n                            <label for=\"max_weight\"/>\n                            <div class=\"o_row\">\n                                <field name=\"max_weight\"/>\n                                <span><field name=\"weight_uom_name\"/></span>\n                            </div>\n                            <field name=\"company_id\" groups=\"base.group_multi_company\"/>\n                        </group>\n                    </group>\n                    <notebook>\n                        <page string=\"Capacity by Package\" name=\"package_capacity\" groups=\"stock.group_tracking_lot\">\n                            <field name=\"package_capacity_ids\" context=\"{''default_storage_category_id'': id, ''default_company_id'': company_id}\">\n                                <tree editable=\"bottom\">\n                                    <field name=\"package_type_id\" required=\"1\"/>\n                                    <field name=\"quantity\"/>\n                                    <field name=\"company_id\" column_invisible=\"True\"/>\n                                </tree>\n                            </field>\n                        </page>\n                        <page string=\"Capacity by Product\" name=\"product_capacity\">\n                            <field name=\"product_capacity_ids\" context=\"{''default_storage_category_id'': id, ''default_company_id'': company_id}\">\n                                <tree editable=\"bottom\">\n                                    <field name=\"product_id\" required=\"1\" context=\"{''default_detailed_type'': ''product''}\"/>\n                                    <field name=\"quantity\"/>\n                                    <field name=\"product_uom_id\" groups=\"uom.group_uom\" options=\"{''no_create'': True, ''no_open'': True}\"/>\n                                    <field name=\"company_id\" column_invisible=\"True\"/>\n                                </tree>\n                            </field>\n                        </page>\n                    </notebook>\n                </sheet>\n            </form>"}', '<?xml version="1.0"?>
<form string="Storage Category">
                <field name="company_id" invisible="1"/>
                <sheet>
                    <div class="oe_button_box" name="button_box">
                        <button name="407" string="Locations" type="action" class="oe_stat_button" icon="oi-arrows-v"/>
                    </div>
                    <group>
                        <group>
                            <field name="name"/>
                            <field name="allow_new_product"/>
                        </group>
                        <group>
                            <label for="max_weight"/>
                            <div class="o_row">
                                <field name="max_weight"/>
                                <span><field name="weight_uom_name"/></span>
                            </div>
                            <field name="company_id" groups="base.group_multi_company"/>
                        </group>
