            ', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (1105, 16, NULL, 1, 1, 'stock.rule.select', 'stock.rule', NULL, 'search', 'stock/views/stock_rule_views.xml', 'primary', '{"en_US": "<search string=\"Search Procurement\">\n                    <field name=\"name\"/>\n                    <filter string=\"Archived\" name=\"inactive\" domain=\"[(''active'',''='',False)]\"/>\n                    <group expand=\"0\" string=\"Group by...\">\n                        <filter string=\"Route\" name=\"groupby_route\" context=\"{''group_by'': ''route_id''}\"/>\n                        <filter string=\"Warehouse\" name=\"groupby_warehouse\" context=\"{''group_by'': ''warehouse_id''}\" groups=\"stock.group_stock_multi_warehouses\"/>\n                   </group>\n                </search>"}', '<?xml version="1.0"?>
<search string="Search Procurement">
                    <field name="name"/>
                    <filter string="Archived" name="inactive" domain="[(''active'',''='',False)]"/>
                    <group expand="0" string="Group by...">
                        <filter string="Route" name="groupby_route" context="{''group_by'': ''route_id''}"/>
                        <filter string="Warehouse" name="groupby_warehouse" context="{''group_by'': ''warehouse_id''}" groups="stock.group_stock_multi_warehouses"/>
                   </group>
                </search>
            ', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (1106, 16, NULL, 1, 1, 'stock.rule.tree', 'stock.rule', NULL, 'tree', 'stock/views/stock_rule_views.xml', 'primary', '{"en_US": "<tree string=\"Rules\">\n                    <field name=\"action\"/>\n                    <field name=\"location_src_id\" options=\"{''no_create'': True}\"/>\n                    <field name=\"location_dest_id\" options=\"{''no_create'': True}\"/>\n                    <field name=\"route_id\"/>\n                    <field name=\"company_id\" groups=\"base.group_multi_company\"/>\n                </tree>"}', '<?xml version="1.0"?>
<tree string="Rules">
                    <field name="action"/>
                    <field name="location_src_id" options="{''no_create'': True}"/>
                    <field name="location_dest_id" options="{''no_create'': True}"/>
                    <field name="route_id"/>
                    <field name="company_id" groups="base.group_multi_company"/>
                </tree>
            ', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (1107, 16, NULL, 1, 1, 'stock.rule.form', 'stock.rule', NULL, 'form', 'stock/views/stock_rule_views.xml', 'primary', '{"en_US": "<form string=\"Rules\">\n                    <sheet>\n                        <widget name=\"web_ribbon\" title=\"Archived\" bg_color=\"text-bg-danger\" invisible=\"active\"/>\n                        <div class=\"oe_title\">\n                            <label for=\"name\"/>\n                            <h1><field name=\"name\"/></h1>\n                        </div>\n                        <group>\n                            <group>\n                                <field name=\"active\" invisible=\"1\"/>\n                                <field name=\"company_id\" invisible=\"1\"/>\n                                <field name=\"picking_type_code_domain\" invisible=\"1\"/>\n                                <field name=\"action\"/>\n                                <field name=\"picking_type_id\"/>\n                                <field name=\"location_src_id\" options=\"{''no_create'': True}\" required=\"action in [''pull'', ''push'', ''pull_push'']\"/>\n                                <field name=\"location_dest_id\" options=\"{''no_create'': True}\"/>\n                                <field name=\"auto\" invisible=\"action not in [''push'', ''pull_push'']\"/>\n                                <field name=\"procure_method\" invisible=\"action not in [''pull'', ''pull_push'']\"/>\n                            </group>\n                            <group>\n                                <div colspan=\"2\">\n                                    <label for=\"rule_message\" invisible=\"1\"/>\n                                    <div>\n                                        <field name=\"rule_message\" readonly=\"1\"/>\n                                    </div>\n                                </div>\n                            </group>\n                        </group>\n                        <group>\n                            <group name=\"apply_on\" string=\"Applicability\">\n                                <field name=\"route_id\"/>\n                                <field name=\"warehouse_id\" invisible=\"action == ''push''\" groups=\"base.group_no_one\"/>\n                                <field name=\"route_company_id\" invisible=\"1\"/>\n                                <field name=\"company_id\" options=\"{''no_create'': True}\" required=\"action == ''push''\" groups=\"base.group_multi_company\"/>\n                                <field name=\"sequence\" string=\"Sequence\" groups=\"base.group_no_one\"/>\n                            </group>\n                            <group name=\"propagation_group\" string=\"Propagation\" invisible=\"action == ''push''\" groups=\"base.group_no_one\">\n                                <field name=\"group_propagation_option\"/>\n                                <field name=\"group_id\" invisible=\"group_propagation_option != ''fixed''\" required=\"group_propagation_option == ''fixed''\"/>\n                                <field name=\"propagate_cancel\"/>\n                                <field name=\"propagate_warehouse_id\"/>\n                            </group>\n                            <group string=\"Options\" invisible=\"action not in [''pull'', ''push'', ''pull_push'']\">\n                                <field name=\"partner_address_id\" invisible=\"action == ''push''\"/>\n                                <label for=\"delay\"/>\n                                <div><field name=\"delay\" class=\"oe_inline\"/> days</div>\n                            </group>\n                        </group>\n                    </sheet>\n                </form>"}', '<?xml version="1.0"?>
<form string="Rules">
                    <sheet>
                        <widget name="web_ribbon" title="Archived" bg_color="text-bg-danger" invisible="active"/>
                        <div class="oe_title">
                            <label for="name"/>
                            <h1><field name="name"/></h1>
                        </div>
                        <group>
                            <group>
                                <field name="active" invisible="1"/>
                                <field name="company_id" invisible="1"/>
                                <field name="picking_type_code_domain" invisible="1"/>
                                <field name="action"/>
                                <field name="picking_type_id"/>
                                <field name="location_src_id" options="{''no_create'': True}" required="action in [''pull'', ''push'', ''pull_push'']"/>
                                <field name="location_dest_id" options="{''no_create'': True}"/>
                                <field name="auto" invisible="action not in [''push'', ''pull_push'']"/>
                                <field name="procure_method" invisible="action not in [''pull'', ''pull_push'']"/>
                            </group>
                            <group>
                                <div colspan="2">
                                    <label for="rule_message" invisible="1"/>
                                    <div>
                                        <field name="rule_message" readonly="1"/>
                                    </div>
                                </div>
                            </group>
                        </group>
                        <group>
                            <group name="apply_on" string="Applicability">
                                <field name="route_id"/>
                                <field name="warehouse_id" invisible="action == ''push''" groups="base.group_no_one"/>
                                <field name="route_company_id" invisible="1"/>
                                <field name="company_id" options="{''no_create'': True}" required="action == ''push''" groups="base.group_multi_company"/>
                                <field name="sequence" string="Sequence" groups="base.group_no_one"/>
                            </group>
                            <group name="propagation_group" string="Propagation" invisible="action == ''push''" groups="base.group_no_one">
                                <field name="group_propagation_option"/>
                                <field name="group_id" invisible="group_propagation_option != ''fixed''" required="group_propagation_option == ''fixed''"/>
                                <field name="propagate_cancel"/>
                                <field name="propagate_warehouse_id"/>
                            </group>
                            <group string="Options" invisible="action not in [''pull'', ''push'', ''pull_push'']">
                                <field name="partner_address_id" invisible="action == ''push''"/>
                                <label for="delay"/>
                                <div><field name="delay" class="oe_inline"/> days</div>
                            </group>
                        </group>
                    </sheet>
                </form>
            ', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (1108, 16, 1107, 1, 1, 'stock.rule.form', 'stock.rule', NULL, 'form', 'stock/views/stock_rule_views.xml', 'primary', '{"en_US": "<data><xpath expr=\"//field[@name=''route_id'']\" position=\"replace\"/>\n                <xpath expr=\"//group[@name=''apply_on'']\" position=\"attributes\">\n                    <attribute name=\"groups\">base.group_multi_company,base.group_no_one</attribute>\n                </xpath>\n                <xpath expr=\"//form\" position=\"inside\">\n                    <field name=\"route_company_id\" invisible=\"1\"/>\n                </xpath>\n            </data>"}', '<?xml version="1.0"?>
<data><xpath expr="//field[@name=''route_id'']" position="replace"/>
                <xpath expr="//group[@name=''apply_on'']" position="attributes">
                    <attribute name="groups">base.group_multi_company,base.group_no_one</attribute>
                </xpath>
                <xpath expr="//form" position="inside">
                    <field name="route_company_id" invisible="1"/>
                </xpath>
            </data>', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (1109, 16, NULL, 1, 1, 'Package Level', 'stock.package_level', NULL, 'form', 'stock/views/stock_package_level_views.xml', 'primary', '{"en_US": "<form create=\"false\" edit=\"false\">\n                <header>\n                    <field name=\"state\" widget=\"statusbar\" statusbar_visible=\"draft,confirmed,assigned,done\"/>\n                </header>\n                <group>\n                    <field name=\"company_id\" invisible=\"1\"/>\n                    <field name=\"picking_id\" invisible=\"1\"/>\n                    <field name=\"show_lots_m2o\" invisible=\"1\"/>\n                    <field name=\"show_lots_text\" invisible=\"1\"/>\n                    <field name=\"picking_type_code\" invisible=\"1\"/>\n                    <group>\n                        <field name=\"package_id\"/>\n                        <field name=\"location_id\" options=\"{''no_create'': True}\" invisible=\"picking_type_code == ''incoming''\" groups=\"stock.group_stock_multi_locations\"/>\n                        <field name=\"location_dest_id\" options=\"{''no_create'': True}\" invisible=\"picking_type_code == ''outgoing''\" groups=\"stock.group_stock_multi_locations\"/>\n                        <field name=\"is_done\"/>\n                        <field name=\"company_id\" groups=\"base.group_multi_company\"/>\n                    </group>\n                    <field name=\"move_ids\" invisible=\"state in (''new'', ''draft'', ''assigned'', ''done'')\">\n                        <tree>\n                            <field name=\"product_id\" readonly=\"state == ''done''\"/>\n                            <field name=\"product_uom_qty\" readonly=\"state == ''done''\"/>\n                            <field name=\"quantity\"/>\n                            <field name=\"product_uom\" groups=\"uom.group_uom\"/>\n                            <field name=\"state\" column_invisible=\"True\"/>\n                        </tree>\n                    </field>\n                    <field name=\"move_line_ids\" invisible=\"state in (''confirmed'', ''cancel'')\">\n                        <tree>\n                            <field name=\"product_id\"/>\n                            <field name=\"lot_id\" column_invisible=\"not parent.show_lots_m2o\" groups=\"stock.group_production_lot\"/>\n                            <field name=\"lot_name\" column_invisible=\"not parent.show_lots_text\" groups=\"stock.group_production_lot\"/>\n                            <field name=\"owner_id\" groups=\"stock.group_tracking_owner\"/>\n                            <field name=\"quantity\"/>\n                            <field name=\"product_uom_id\" options=\"{''no_open'': True, ''no_create'': True}\" readonly=\"quantity != 0.0\" string=\"Unit of Measure\" groups=\"uom.group_uom\"/>\n                            <field name=\"state\" column_invisible=\"True\"/>\n                        </tree>\n                    </field>\n                </group>\n            </form>"}', '<?xml version="1.0"?>
<form create="false" edit="false">
                <header>
                    <field name="state" widget="statusbar" statusbar_visible="draft,confirmed,assigned,done"/>
                </header>
                <group>
                    <field name="company_id" invisible="1"/>
                    <field name="picking_id" invisible="1"/>
                    <field name="show_lots_m2o" invisible="1"/>
                    <field name="show_lots_text" invisible="1"/>
                    <field name="picking_type_code" invisible="1"/>
                    <group>
                        <field name="package_id"/>
                        <field name="location_id" options="{''no_create'': True}" invisible="picking_type_code == ''incoming''" groups="stock.group_stock_multi_locations"/>
                        <field name="location_dest_id" options="{''no_create'': True}" invisible="picking_type_code == ''outgoing''" groups="stock.group_stock_multi_locations"/>
                        <field name="is_done"/>
                        <field name="company_id" groups="base.group_multi_company"/>
                    </group>
                    <field name="move_ids" invisible="state in (''new'', ''draft'', ''assigned'', ''done'')">
                        <tree>
                            <field name="product_id" readonly="state == ''done''"/>
                            <field name="product_uom_qty" readonly="state == ''done''"/>
                            <field name="quantity"/>
                            <field name="product_uom" groups="uom.group_uom"/>
                            <field name="state" column_invisible="True"/>
                        </tree>
                    </field>
                    <field name="move_line_ids" invisible="state in (''confirmed'', ''cancel'')">
                        <tree>
                            <field name="product_id"/>
                            <field name="lot_id" column_invisible="not parent.show_lots_m2o" groups="stock.group_production_lot"/>
                            <field name="lot_name" column_invisible="not parent.show_lots_text" groups="stock.group_production_lot"/>
                            <field name="owner_id" groups="stock.group_tracking_owner"/>
                            <field name="quantity"/>
                            <field name="product_uom_id" options="{''no_open'': True, ''no_create'': True}" readonly="quantity != 0.0" string="Unit of Measure" groups="uom.group_uom"/>
                            <field name="state" column_invisible="True"/>
                        </tree>
                    </field>
                </group>
            </form>
        ', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (1110, 16, 1109, 1, 1, 'Package Level', 'stock.package_level', NULL, 'form', 'stock/views/stock_package_level_views.xml', 'primary', '{"en_US": "<xpath expr=\"//form\" position=\"inside\">\n                <footer class=\"oe_edit_only\">\n                    <button string=\"Confirm\" special=\"save\" data-hotkey=\"q\" class=\"oe_highlight\"/>\n                    <button string=\"Discard\" special=\"cancel\" data-hotkey=\"x\"/>\n                </footer>\n            </xpath>"}', '<?xml version="1.0"?>
<xpath expr="//form" position="inside">
                <footer class="oe_edit_only">
                    <button string="Confirm" special="save" data-hotkey="q" class="oe_highlight"/>
                    <button string="Discard" special="cancel" data-hotkey="x"/>
                </footer>
            </xpath>
        ', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (1111, 1000, NULL, 1, 1, 'Package Level Tree Picking', 'stock.package_level', NULL, 'tree', 'stock/views/stock_package_level_views.xml', 'primary', '{"en_US": "<tree editable=\"bottom\" decoration-muted=\"state == ''done''\">\n                <field name=\"is_fresh_package\" column_invisible=\"True\"/>\n                <field name=\"company_id\" column_invisible=\"True\"/>\n                <field name=\"package_id\" readonly=\"state in (''confirmed'', ''assigned'', ''done'', ''cancel'')\" options=\"{''no_create'': True}\"/>\n                <field name=\"location_id\" options=\"{''no_create'': True}\" column_invisible=\"parent.picking_type_code == ''incoming''\" groups=\"stock.group_stock_multi_locations\"/>\n                <field name=\"location_dest_id\" options=\"{''no_create'': True}\" column_invisible=\"parent.picking_type_code == ''outgoing''\" groups=\"stock.group_stock_multi_locations\"/>\n                <field name=\"state\"/>\n                <field name=\"is_done\" readonly=\"parent.state in (''draft'', ''new'', ''done'') or is_fresh_package\"/>\n                <button name=\"action_show_package_details\" title=\"Display package content\" type=\"object\" icon=\"fa-list\"/>\n            </tree>"}', '<?xml version="1.0"?>
<tree editable="bottom" decoration-muted="state == ''done''">
                <field name="is_fresh_package" column_invisible="True"/>
                <field name="company_id" column_invisible="True"/>
                <field name="package_id" readonly="state in (''confirmed'', ''assigned'', ''done'', ''cancel'')" options="{''no_create'': True}"/>
                <field name="location_id" options="{''no_create'': True}" column_invisible="parent.picking_type_code == ''incoming''" groups="stock.group_stock_multi_locations"/>
                <field name="location_dest_id" options="{''no_create'': True}" column_invisible="parent.picking_type_code == ''outgoing''" groups="stock.group_stock_multi_locations"/>
                <field name="state"/>
                <field name="is_done" readonly="parent.state in (''draft'', ''new'', ''done'') or is_fresh_package"/>
                <button name="action_show_package_details" title="Display package content" type="object" icon="fa-list"/>
            </tree>
        ', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (1112, 16, NULL, 1, 1, 'stock.package.type.form', 'stock.package.type', NULL, 'form', 'stock/views/stock_package_type_view.xml', 'primary', '{"en_US": "<form string=\"Package Type\">\n            <sheet>\n                <div class=\"oe_button_box\" name=\"button_box\"/>\n                <label for=\"name\"/>\n                <h1>\n                    <field name=\"name\"/>\n                </h1>\n                <group name=\"delivery\">\n                    <group>\n                        <label for=\"length_uom_name\" string=\"Size\"/>\n                        <div class=\"o_row\" name=\"size\">\n                            <field name=\"packaging_length\" placeholder=\"Length\"/>\n                            <span>×</span>\n                            <field name=\"width\" placeholder=\"Width\"/>\n                            <span>×</span>\n                            <field name=\"height\" placeholder=\"Height\"/>\n                            <span><field name=\"length_uom_name\" help=\"Size: Length × Width × Height\"/></span>\n                        </div>\n                        <label for=\"base_weight\"/>\n                        <div class=\"o_row\" name=\"base_weight\">\n                            <field name=\"base_weight\"/>\n                            <span><field name=\"weight_uom_name\"/></span>\n                        </div>\n                        <label for=\"max_weight\"/>\n                        <div class=\"o_row\" name=\"max_weight\">\n                            <field name=\"max_weight\"/>\n                            <span><field name=\"weight_uom_name\"/></span>\n                        </div>\n                        <field name=\"barcode\"/>\n                        <field name=\"company_id\" groups=\"base.group_multi_company\"/>\n                    </group>\n                </group>\n                <group name=\"storage_categories\" groups=\"stock.group_stock_storage_categories\">\n                    <group>\n                        <field name=\"storage_category_capacity_ids\" context=\"{''default_package_type_id'': id}\">\n                            <tree editable=\"bottom\">\n                                <field name=\"storage_category_id\"/>\n                                <field name=\"quantity\"/>\n                            </tree>\n                        </field>\n                    </group>\n                </group>\n            </sheet>\n        </form>"}', '<?xml version="1.0"?>
<form string="Package Type">
            <sheet>
                <div class="oe_button_box" name="button_box"/>
                <label for="name"/>
                <h1>
                    <field name="name"/>
                </h1>
                <group name="delivery">
                    <group>
                        <label for="length_uom_name" string="Size"/>
                        <div class="o_row" name="size">
                            <field name="packaging_length" placeholder="Length"/>
                            <span>×</span>
                            <field name="width" placeholder="Width"/>
                            <span>×</span>
                            <field name="height" placeholder="Height"/>
                            <span><field name="length_uom_name" help="Size: Length × Width × Height"/></span>
                        </div>
                        <label for="base_weight"/>
                        <div class="o_row" name="base_weight">
                            <field name="base_weight"/>
                            <span><field name="weight_uom_name"/></span>
                        </div>
                        <label for="max_weight"/>
                        <div class="o_row" name="max_weight">
                            <field name="max_weight"/>
                            <span><field name="weight_uom_name"/></span>
                        </div>
                        <field name="barcode"/>
                        <field name="company_id" groups="base.group_multi_company"/>
                    </group>
                </group>
                <group name="storage_categories" groups="stock.group_stock_storage_categories">
                    <group>
                        <field name="storage_category_capacity_ids" context="{''default_package_type_id'': id}">
                            <tree editable="bottom">
                                <field name="storage_category_id"/>
                                <field name="quantity"/>
                            </tree>
                        </field>
                    </group>
                </group>
            </sheet>
        </form>
    ', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
INSERT INTO public.ir_ui_view VALUES (1113, 16, NULL, 1, 1, 'stock.package.type.tree', 'stock.package.type', NULL, 'tree', 'stock/views/stock_package_type_view.xml', 'primary', '{"en_US": "<tree string=\"Package Types\">\n            <field name=\"sequence\" widget=\"handle\"/>\n            <field name=\"name\"/>\n            <field name=\"height\"/>\n            <field name=\"width\"/>\n            <field name=\"packaging_length\"/>\n            <field name=\"max_weight\"/>\n            <field name=\"barcode\" optional=\"hide\"/>\n        </tree>"}', '<?xml version="1.0"?>
