            <field name="sequence" widget="handle"/>
            <field name="name"/>
            <field name="height"/>
            <field name="width"/>
            <field name="packaging_length"/>
            <field name="max_weight"/>
            <field name="barcode" optional="hide"/>
        </tree>
    ', false, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927', false);
