INSERT INTO public.ir_ui_view VALUES (1118, 16, 1099, 1, 1, 'res.config.settings.view.form.inherit.stock.account', 'res.config.settings', NULL, 'form', 'stock_account/views/res_config_settings_views.xml', 'extension', '{"en_US": "<block id=\"production_lot_info\" position=\"after\">\n                    <block title=\"Valuation\" name=\"valuation_setting_container\">\n                        <setting id=\"additional_cost_setting\" title=\"Affect landed costs on reception operations and split them among products to update their cost price.\" documentation=\"/applications/inventory_and_mrp/inventory/management/reporting/integrating_landed_costs.html\" help=\"Add additional cost (transport, customs, ...) in the value of the product.\">\n                            <field name=\"module_stock_landed_costs\"/>\n                            <div class=\"content-group\">\n                                <div name=\"landed_cost_info\"/>\n                            </div>\n                        </setting>\n                        <setting invisible=\"not group_stock_production_lot\" id=\"group_lot_on_invoice\" help=\"Lots &amp; Serial numbers will appear on the invoice\">\n                            <field name=\"group_lot_on_invoice\"/>\n                        </setting>\n                    </block>\n                </block>"}', '<?xml version="1.0"?>
<block id="production_lot_info" position="after">
                    <block title="Valuation" name="valuation_setting_container">
                        <setting id="additional_cost_setting" title="Affect landed costs on reception operations and split them among products to update their cost price." documentation="/applications/inventory_and_mrp/inventory/management/reporting/integrating_landed_costs.html" help="Add additional cost (transport, customs, ...) in the value of the product.">
                            <field name="module_stock_landed_costs"/>
                            <div class="content-group">
                                <div name="landed_cost_info"/>
                            </div>
                        </setting>
                        <setting invisible="not group_stock_production_lot" id="group_lot_on_invoice" help="Lots &amp; Serial numbers will appear on the invoice">
                            <field name="group_lot_on_invoice"/>
                        </setting>
                    </block>
                </block>
            ', false, true, '2026-05-10 01:12:23.260984', '2026-05-10 01:12:23.260984', false);
INSERT INTO public.ir_ui_view VALUES (1119, 16, 749, 1, 1, 'stock_account_report_invoice_document', NULL, 'stock_account.stock_account_report_invoice_document', 'qweb', 'stock_account/views/report_invoice.xml', 'extension', '{"en_US": "<data inherit_id=\"account.report_invoice_document\">\n        <xpath expr=\"//div[@id=''right-elements'']\" position=\"after\">\n          <t groups=\"stock_account.group_lot_on_invoice\">\n            <t t-set=\"lot_values\" t-value=\"o._get_invoiced_lot_values()\"/>\n            <div t-if=\"not lot_values\" class=\"oe_structure\">​</div>\n            <table t-else=\"\" class=\"table table-sm mt-2\" style=\"width: 50%;\" name=\"invoice_snln_table\">\n                <thead>\n                    <tr>\n                        <th><span>Product</span></th>\n                        <th class=\"text-end\"><span>Quantity</span></th>\n                        <th class=\"text-end\"><span>SN/LN</span></th>\n                    </tr>\n                </thead>\n                <tbody>\n                    <tr t-foreach=\"lot_values\" t-as=\"snln_line\">\n                        <td><t t-esc=\"snln_line[''product_name'']\">Bacon</t></td>\n                        <td class=\"text-end\">\n                            <t t-esc=\"snln_line[''quantity'']\">6.00</t>\n                            <t t-esc=\"snln_line[''uom_name'']\" groups=\"uom.group_uom\">units</t>\n                        </td>\n                        <td><t class=\"text-end\" t-esc=\"snln_line[''lot_name'']\">BC46282798</t></td>\n                    </tr>\n                </tbody>\n            </table>\n          </t>\n        </xpath>\n    </data>"}', '<?xml version="1.0"?>
<data inherit_id="account.report_invoice_document">
        <xpath expr="//div[@id=''right-elements'']" position="after">
          <t groups="stock_account.group_lot_on_invoice">
            <t t-set="lot_values" t-value="o._get_invoiced_lot_values()"/>
            <div t-if="not lot_values" class="oe_structure">​</div>
            <table t-else="" class="table table-sm mt-2" style="width: 50%;" name="invoice_snln_table">
                <thead>
                    <tr>
                        <th><span>Product</span></th>
                        <th class="text-end"><span>Quantity</span></th>
                        <th class="text-end"><span>SN/LN</span></th>
                    </tr>
                </thead>
                <tbody>
                    <tr t-foreach="lot_values" t-as="snln_line">
                        <td><t t-esc="snln_line[''product_name'']">Bacon</t></td>
                        <td class="text-end">
                            <t t-esc="snln_line[''quantity'']">6.00</t>
                            <t t-esc="snln_line[''uom_name'']" groups="uom.group_uom">units</t>
                        </td>
                        <td><t class="text-end" t-esc="snln_line[''lot_name'']">BC46282798</t></td>
                    </tr>
                </tbody>
            </table>
          </t>
        </xpath>
    </data>
', false, true, '2026-05-10 01:12:23.260984', '2026-05-10 01:12:23.260984', false);
INSERT INTO public.ir_ui_view VALUES (1120, 16, NULL, 1, 1, 'stock.valuation.layer.form', 'stock.valuation.layer', NULL, 'form', 'stock_account/views/stock_valuation_layer_views.xml', 'primary', '{"en_US": "<form edit=\"0\" create=\"0\">\n                <sheet>\n                    <group>\n                        <group>\n                            <field name=\"create_date\" string=\"Date\"/>\n                            <field name=\"product_id\"/>\n                            <field name=\"stock_move_id\" invisible=\"not stock_move_id\"/>\n                        </group>\n                    </group>\n                    <notebook>\n                        <page string=\"Valuation\" name=\"valuation\">\n                            <group>\n                                <field name=\"quantity\"/>\n                                <field name=\"uom_id\" groups=\"uom.group_uom\"/>\n                                <field name=\"currency_id\" invisible=\"1\"/>\n                                <field name=\"unit_cost\"/>\n                                <field name=\"value\"/>\n                                <field name=\"remaining_qty\"/>\n                            </group>\n                        </page>\n                        <page string=\"Other Info\" name=\"other_info\">\n                            <group>\n                                <field name=\"description\"/>\n                                <field name=\"account_move_id\" groups=\"account.group_account_invoice\" invisible=\"not account_move_id\"/>\n                                <field name=\"company_id\" groups=\"base.group_multi_company\"/>\n                                <field name=\"stock_valuation_layer_id\" invisible=\"not stock_valuation_layer_id\"/>\n                            </group>\n                        </page>\n                    </notebook>\n                </sheet>\n            </form>"}', '<?xml version="1.0"?>
<form edit="0" create="0">
                <sheet>
                    <group>
                        <group>
                            <field name="create_date" string="Date"/>
                            <field name="product_id"/>
                            <field name="stock_move_id" invisible="not stock_move_id"/>
                        </group>
                    </group>
                    <notebook>
                        <page string="Valuation" name="valuation">
                            <group>
                                <field name="quantity"/>
                                <field name="uom_id" groups="uom.group_uom"/>
                                <field name="currency_id" invisible="1"/>
                                <field name="unit_cost"/>
                                <field name="value"/>
                                <field name="remaining_qty"/>
                            </group>
                        </page>
                        <page string="Other Info" name="other_info">
                            <group>
                                <field name="description"/>
                                <field name="account_move_id" groups="account.group_account_invoice" invisible="not account_move_id"/>
                                <field name="company_id" groups="base.group_multi_company"/>
                                <field name="stock_valuation_layer_id" invisible="not stock_valuation_layer_id"/>
                            </group>
                        </page>
                    </notebook>
                </sheet>
            </form>
        ', false, true, '2026-05-10 01:12:23.260984', '2026-05-10 01:12:23.260984', false);
INSERT INTO public.ir_ui_view VALUES (1129, 16, 1024, 1, 1, 'stock.quant.tree.editable.inherit', 'stock.quant', NULL, 'tree', 'stock_account/views/stock_quant_views.xml', 'extension', '{"en_US": "<data><xpath expr=\"//field[@name=''product_uom_id'']\" position=\"after\">\n                <field name=\"currency_id\" column_invisible=\"True\"/>\n                <field name=\"cost_method\" column_invisible=\"True\"/>\n                <field name=\"value\" optional=\"hidden\" sum=\"Total Value\"/>\n            </xpath>\n            <xpath expr=\"//button[@name=''action_view_orderpoints'']\" position=\"after\">\n                <button name=\"422\" title=\"Stock Valuation\" string=\"Valuation\" type=\"action\" class=\"btn-link\" icon=\"fa-bar-chart\" context=\"{''search_default_product_id'': product_id}\" invisible=\"cost_method != ''fifo''\"/>\n            </xpath>\n        </data>"}', '<?xml version="1.0"?>
<data><xpath expr="//field[@name=''product_uom_id'']" position="after">
                <field name="currency_id" column_invisible="True"/>
                <field name="cost_method" column_invisible="True"/>
