INSERT INTO public.ir_ui_view VALUES (1121, 16, NULL, 1, 1, 'stock.valuation.layer.tree', 'stock.valuation.layer', NULL, 'tree', 'stock_account/views/stock_valuation_layer_views.xml', 'primary', '{"en_US": "<tree default_order=\"id desc\" create=\"0\" import=\"0\" js_class=\"inventory_report_list\" action=\"action_open_reference\" type=\"object\" duplicate=\"0\">\n                <header>\n                    <button name=\"action_valuation_at_date\" string=\"Valuation at Date\" type=\"object\" invisible=\"((context.get(''inventory_mode'') and not context.get(''inventory_report_mode'')) or context.get(''no_at_date''))\" class=\"btn-primary ms-1\" display=\"always\"/>\n                </header>\n                <field name=\"create_date\" string=\"Date\"/>\n                <field name=\"reference\"/>\n                <field name=\"account_move_id\" optional=\"hide\" groups=\"account.group_account_user\"/>\n                <button name=\"action_open_journal_entry\" groups=\"account.group_account_user\" type=\"object\" title=\"Journal Entry\" icon=\"fa-book\" invisible=\"not account_move_id\"/>\n                <field name=\"product_id\"/>\n                <field name=\"company_id\" groups=\"base.group_multi_company\"/>\n                <field name=\"quantity\" string=\"Moved Quantity\" optional=\"show\" sum=\"Total Moved Quantity\"/>\n                <field name=\"remaining_qty\" type=\"measure\" optional=\"hide\" sum=\"Total Remaining Quantity\"/>\n                <field name=\"unit_cost\" optional=\"hide\"/>\n                <field name=\"uom_id\" groups=\"uom.group_uom\"/>\n                <field name=\"currency_id\" column_invisible=\"True\"/>\n                <field name=\"value\" sum=\"Total Value\" optional=\"show\"/>\n                <field name=\"description\" optional=\"hide\"/>\n                <field name=\"remaining_value\" type=\"measure\" optional=\"hide\" sum=\"Total Remaining Value\"/>\n                <groupby name=\"product_id\">\n                    <field name=\"cost_method\" invisible=\"1\"/>\n                    <field name=\"quantity_svl\" invisible=\"1\"/>\n                    <button name=\"action_revaluation\" icon=\"fa-plus\" title=\"Add Manual Valuation\" type=\"object\" invisible=\"cost_method == ''standard'' or quantity_svl &lt;= 0\"/>\n                </groupby>\n            </tree>"}', '<?xml version="1.0"?>
<tree default_order="id desc" create="0" import="0" js_class="inventory_report_list" action="action_open_reference" type="object" duplicate="0">
                <header>
                    <button name="action_valuation_at_date" string="Valuation at Date" type="object" invisible="((context.get(''inventory_mode'') and not context.get(''inventory_report_mode'')) or context.get(''no_at_date''))" class="btn-primary ms-1" display="always"/>
                </header>
                <field name="create_date" string="Date"/>
                <field name="reference"/>
                <field name="account_move_id" optional="hide" groups="account.group_account_user"/>
                <button name="action_open_journal_entry" groups="account.group_account_user" type="object" title="Journal Entry" icon="fa-book" invisible="not account_move_id"/>
                <field name="product_id"/>
                <field name="company_id" groups="base.group_multi_company"/>
                <field name="quantity" string="Moved Quantity" optional="show" sum="Total Moved Quantity"/>
                <field name="remaining_qty" type="measure" optional="hide" sum="Total Remaining Quantity"/>
                <field name="unit_cost" optional="hide"/>
                <field name="uom_id" groups="uom.group_uom"/>
                <field name="currency_id" column_invisible="True"/>
                <field name="value" sum="Total Value" optional="show"/>
                <field name="description" optional="hide"/>
                <field name="remaining_value" type="measure" optional="hide" sum="Total Remaining Value"/>
                <groupby name="product_id">
                    <field name="cost_method" invisible="1"/>
                    <field name="quantity_svl" invisible="1"/>
                    <button name="action_revaluation" icon="fa-plus" title="Add Manual Valuation" type="object" invisible="cost_method == ''standard'' or quantity_svl &lt;= 0"/>
                </groupby>
            </tree>
        ', false, true, '2026-05-10 01:12:23.260984', '2026-05-10 01:12:23.260984', false);
