INSERT INTO public.ir_ui_view VALUES (1125, 16, NULL, 1, 1, 'Inventory Valuation', 'stock.valuation.layer', NULL, 'search', 'stock_account/views/stock_valuation_layer_views.xml', 'primary', '{"en_US": "<search string=\"Inventory Valuation\">\n                <field name=\"product_id\"/>\n                <field name=\"reference\"/>\n                <field name=\"categ_id\"/>\n                <field name=\"product_tmpl_id\"/>\n                <field name=\"warehouse_id\" groups=\"stock.group_stock_multi_warehouses\"/>\n                <field name=\"company_id\" groups=\"base.group_multi_company\"/>\n                <separator/>\n                <filter string=\"Incoming\" name=\"incoming\" domain=\"[(''stock_move_id.location_id.usage'', ''not in'', (''internal'', ''transit'')), (''stock_move_id.location_dest_id.usage'', ''in'', (''internal'', ''transit''))]\"/>\n                <filter string=\"Outgoing\" name=\"outgoing\" domain=\"[(''stock_move_id.location_id.usage'', ''in'', (''internal'', ''transit'')), (''stock_move_id.location_dest_id.usage'', ''not in'', (''internal'', ''transit''))]\"/>\n                <separator/>\n                <filter string=\"Has Remaining Qty\" name=\"has_remaining_qty\" domain=\"[(''remaining_qty'', ''&gt;'', 0)]\"/>\n                <group expand=\"0\" string=\"Group by...\">\n                    <filter string=\"Product\" name=\"group_by_product_id\" context=\"{''group_by'': ''product_id''}\"/>\n                    <filter string=\"Product Category\" name=\"group_by_categ_id\" context=\"{''group_by'': ''categ_id''}\"/>\n                    <filter string=\"Date\" name=\"group_by_created_date\" context=\"{''group_by'': ''create_date''}\"/>\n                    <filter string=\"Company\" name=\"group_by_company_id\" context=\"{''group_by'': ''company_id''}\" groups=\"base.group_multi_company\"/>\n                </group>\n            </search>"}', '<?xml version="1.0"?>
<search string="Inventory Valuation">
                <field name="product_id"/>
                <field name="reference"/>
                <field name="categ_id"/>
                <field name="product_tmpl_id"/>
                <field name="warehouse_id" groups="stock.group_stock_multi_warehouses"/>
                <field name="company_id" groups="base.group_multi_company"/>
                <separator/>
                <filter string="Incoming" name="incoming" domain="[(''stock_move_id.location_id.usage'', ''not in'', (''internal'', ''transit'')), (''stock_move_id.location_dest_id.usage'', ''in'', (''internal'', ''transit''))]"/>
                <filter string="Outgoing" name="outgoing" domain="[(''stock_move_id.location_id.usage'', ''in'', (''internal'', ''transit'')), (''stock_move_id.location_dest_id.usage'', ''not in'', (''internal'', ''transit''))]"/>
                <separator/>
                <filter string="Has Remaining Qty" name="has_remaining_qty" domain="[(''remaining_qty'', ''&gt;'', 0)]"/>
                <group expand="0" string="Group by...">
                    <filter string="Product" name="group_by_product_id" context="{''group_by'': ''product_id''}"/>
                    <filter string="Product Category" name="group_by_categ_id" context="{''group_by'': ''categ_id''}"/>
                    <filter string="Date" name="group_by_created_date" context="{''group_by'': ''create_date''}"/>
                    <filter string="Company" name="group_by_company_id" context="{''group_by'': ''company_id''}" groups="base.group_multi_company"/>
                </group>
            </search>
        ', false, true, '2026-05-10 01:12:23.260984', '2026-05-10 01:12:23.260984', false);
