INSERT INTO public.ir_ui_view VALUES (1132, 16, 739, 1, 1, 'product.category.stock.property.form.inherit', 'product.category', NULL, 'form', 'stock_account/views/product_views.xml', 'extension', '{"en_US": "<group name=\"account_property\" position=\"inside\">\n                    <group name=\"account_stock_property\" string=\"Account Stock Properties\" groups=\"account.group_account_readonly\" invisible=\"property_valuation == ''manual_periodic''\">\n                        <field name=\"property_valuation\" invisible=\"1\"/>\n                        <field name=\"property_stock_valuation_account_id\" options=\"{''no_create'': True}\" required=\"property_valuation == ''real_time''\"/>\n                        <field name=\"property_stock_journal\" required=\"property_valuation == ''real_time''\"/>\n                        <field name=\"property_stock_account_input_categ_id\" options=\"{''no_create'': True}\" required=\"property_valuation == ''real_time''\"/>\n                        <field name=\"property_stock_account_output_categ_id\" options=\"{''no_create'': True}\" required=\"property_valuation == ''real_time''\"/>\n                        <div colspan=\"2\" class=\"alert alert-info mt16\" role=\"status\">\n                            <b>Set other input/output accounts on specific </b><button name=\"409\" role=\"button\" type=\"action\" class=\"btn-link\" style=\"padding: 0;vertical-align: baseline;\" string=\"locations\"/>.\n                        </div>\n                    </group>\n                </group>"}', '<?xml version="1.0"?>
<group name="account_property" position="inside">
                    <group name="account_stock_property" string="Account Stock Properties" groups="account.group_account_readonly" invisible="property_valuation == ''manual_periodic''">
                        <field name="property_valuation" invisible="1"/>
                        <field name="property_stock_valuation_account_id" options="{''no_create'': True}" required="property_valuation == ''real_time''"/>
                        <field name="property_stock_journal" required="property_valuation == ''real_time''"/>
                        <field name="property_stock_account_input_categ_id" options="{''no_create'': True}" required="property_valuation == ''real_time''"/>
                        <field name="property_stock_account_output_categ_id" options="{''no_create'': True}" required="property_valuation == ''real_time''"/>
                        <div colspan="2" class="alert alert-info mt16" role="status">
                            <b>Set other input/output accounts on specific </b><button name="409" role="button" type="action" class="btn-link" style="padding: 0;vertical-align: baseline;" string="locations"/>.
                        </div>
                    </group>
                </group>
            ', false, true, '2026-05-10 01:12:23.260984', '2026-05-10 01:12:23.260984', false);
INSERT INTO public.ir_ui_view VALUES (1133, 16, 1081, 1, 1, 'product.product.stock.tree.inherit.stock.account', 'product.product', NULL, 'tree', 'stock_account/views/product_views.xml', 'extension', '{"en_US": "<field name=\"qty_available\" position=\"before\">\n                    <field name=\"company_currency_id\" column_invisible=\"True\"/>\n                    <field name=\"cost_method\" column_invisible=\"True\"/>\n                    <field name=\"avg_cost\" string=\"Unit Cost\" optional=\"show\" widget=\"monetary\" options=\"{''currency_field'': ''company_currency_id''}\"/>\n                    <field name=\"total_value\" string=\"Total Value\" optional=\"show\" widget=\"monetary\" options=\"{''currency_field'': ''company_currency_id''}\" sum=\"Total Value\"/>\n                    <button name=\"421\" title=\"Valuation Report\" type=\"action\" class=\"btn-link\" icon=\"fa-bar-chart\" context=\"{''search_default_product_id'': id, ''default_product_id'': id}\" invisible=\"cost_method != ''average''\"/>\n                    <button name=\"422\" title=\"Valuation Report\" type=\"action\" class=\"btn-link\" icon=\"fa-bar-chart\" context=\"{''search_default_product_id'': id, ''default_product_id'': id}\" invisible=\"cost_method != ''fifo''\"/>\n                </field>"}', '<?xml version="1.0"?>
<field name="qty_available" position="before">
                    <field name="company_currency_id" column_invisible="True"/>
                    <field name="cost_method" column_invisible="True"/>
                    <field name="avg_cost" string="Unit Cost" optional="show" widget="monetary" options="{''currency_field'': ''company_currency_id''}"/>
                    <field name="total_value" string="Total Value" optional="show" widget="monetary" options="{''currency_field'': ''company_currency_id''}" sum="Total Value"/>
                    <button name="421" title="Valuation Report" type="action" class="btn-link" icon="fa-bar-chart" context="{''search_default_product_id'': id, ''default_product_id'': id}" invisible="cost_method != ''average''"/>
                    <button name="422" title="Valuation Report" type="action" class="btn-link" icon="fa-bar-chart" context="{''search_default_product_id'': id, ''default_product_id'': id}" invisible="cost_method != ''fifo''"/>
                </field>
            ', false, true, '2026-05-10 01:12:23.260984', '2026-05-10 01:12:23.260984', false);
INSERT INTO public.ir_ui_view VALUES (1134, 16, 990, 1, 1, 'stock.request.count.form.view.inherit.stock.account', 'stock.request.count', NULL, 'form', 'stock_account/wizard/stock_request_count.xml', 'extension', '{"en_US": "<field name=\"user_id\" position=\"after\">\n                <field name=\"accounting_date\"/>\n            </field>"}', '<?xml version="1.0"?>
