INSERT INTO public.ir_ui_view VALUES (1135, 16, NULL, 1, 1, 'stock.valuation.layer.revaluation.form', 'stock.valuation.layer.revaluation', NULL, 'form', 'stock_account/wizard/stock_valuation_layer_revaluation_views.xml', 'primary', '{"en_US": "<form string=\"Product Revaluation\">\n                <sheet>\n                    <group>\n                        <label for=\"current_value_svl\" string=\"Current Value\"/>\n                        <div class=\"o_row\">\n                            <span>\n                            <field name=\"current_value_svl\" class=\"oe_inline\" widget=\"monetary\"/> for <field name=\"current_quantity_svl\" class=\"oe_inline\"/> <field name=\"product_uom_name\" class=\"oe_inline\"/>\n                            </span>\n                        </div>\n                        <label for=\"added_value\" string=\"Added Value\"/>\n                        <div class=\"o_row\">\n                            <span><field name=\"added_value\" class=\"oe_inline\"/> = <field name=\"new_value\" class=\"oe_inline\"/> (<field name=\"new_value_by_qty\" class=\"oe_inline ms-1\"/> by <field name=\"product_uom_name\" class=\"oe_inline me-1\"/>)\n                            <small class=\"mx-2 fst-italic\">Use a negative added value to record a decrease in the product value</small></span>\n                        </div>\n                        <field name=\"company_id\" invisible=\"1\"/>\n                        <field name=\"currency_id\" invisible=\"1\"/>\n                        <field name=\"product_id\" invisible=\"1\"/>\n                    </group>\n                    <group>\n                        <field name=\"property_valuation\" invisible=\"1\"/>\n                        <group>\n                            <field name=\"reason\"/>\n                            <field name=\"account_journal_id\" invisible=\"property_valuation != ''real_time''\" required=\"property_valuation == ''real_time''\"/>\n                        </group>\n                        <group>\n                            <field name=\"account_id\" invisible=\"property_valuation != ''real_time''\" required=\"property_valuation == ''real_time''\"/>\n                            <field name=\"date\" invisible=\"property_valuation != ''real_time''\"/>\n                        </group>\n                    </group>\n                </sheet>\n                <footer>\n                    <button name=\"action_validate_revaluation\" string=\"Revalue\" type=\"object\" class=\"btn-primary\" data-hotkey=\"q\"/>\n                    <button string=\"Cancel\" class=\"btn-secondary\" special=\"cancel\" data-hotkey=\"x\"/>\n                </footer>\n            </form>"}', '<?xml version="1.0"?>
<form string="Product Revaluation">
                <sheet>
                    <group>
                        <label for="current_value_svl" string="Current Value"/>
                        <div class="o_row">
                            <span>
                            <field name="current_value_svl" class="oe_inline" widget="monetary"/> for <field name="current_quantity_svl" class="oe_inline"/> <field name="product_uom_name" class="oe_inline"/>
                            </span>
                        </div>
                        <label for="added_value" string="Added Value"/>
                        <div class="o_row">
                            <span><field name="added_value" class="oe_inline"/> = <field name="new_value" class="oe_inline"/> (<field name="new_value_by_qty" class="oe_inline ms-1"/> by <field name="product_uom_name" class="oe_inline me-1"/>)
                            <small class="mx-2 fst-italic">Use a negative added value to record a decrease in the product value</small></span>
                        </div>
                        <field name="company_id" invisible="1"/>
                        <field name="currency_id" invisible="1"/>
                        <field name="product_id" invisible="1"/>
                    </group>
                    <group>
                        <field name="property_valuation" invisible="1"/>
                        <group>
                            <field name="reason"/>
                            <field name="account_journal_id" invisible="property_valuation != ''real_time''" required="property_valuation == ''real_time''"/>
                        </group>
                        <group>
                            <field name="account_id" invisible="property_valuation != ''real_time''" required="property_valuation == ''real_time''"/>
                            <field name="date" invisible="property_valuation != ''real_time''"/>
                        </group>
                    </group>
                </sheet>
                <footer>
                    <button name="action_validate_revaluation" string="Revalue" type="object" class="btn-primary" data-hotkey="q"/>
                    <button string="Cancel" class="btn-secondary" special="cancel" data-hotkey="x"/>
                </footer>
            </form>
        ', false, true, '2026-05-10 01:12:23.260984', '2026-05-10 01:12:23.260984', false);
INSERT INTO public.ir_ui_view VALUES (1136, 16, 989, 1, 1, 'Valuation Report at Date', 'stock.quantity.history', NULL, 'form', 'stock_account/wizard/stock_quantity_history.xml', 'extension', '{"en_US": "<data><!-- ensure string/description matches the model we''re looking at the history of -->\n            <field name=\"inventory_datetime\" position=\"attributes\">\n                <attribute name=\"invisible\">\n                    context.get(''active_model'') != ''stock.quant''\n                </attribute>\n            </field>\n            <field name=\"inventory_datetime\" position=\"after\">\n                <field name=\"inventory_datetime\" string=\"Valuation at Date\" help=\"Choose a date to get the valuation at that date\" invisible=\"context.get(''active_model'') != ''stock.valuation.layer''\"/>\n            </field>\n        </data>"}', '<?xml version="1.0"?>
<data><!-- ensure string/description matches the model we''re looking at the history of -->
            <field name="inventory_datetime" position="attributes">
                <attribute name="invisible">
                    context.get(''active_model'') != ''stock.quant''
                </attribute>
            </field>
            <field name="inventory_datetime" position="after">
                <field name="inventory_datetime" string="Valuation at Date" help="Choose a date to get the valuation at that date" invisible="context.get(''active_model'') != ''stock.valuation.layer''"/>
            </field>
        </data>', false, true, '2026-05-10 01:12:23.260984', '2026-05-10 01:12:23.260984', false);
INSERT INTO public.ir_ui_view VALUES (1137, 16, 1099, 1, 1, 'res.config.settings.view.form.inherit.delivery.stock', 'res.config.settings', NULL, 'form', 'stock_sms/views/res_config_settings_views.xml', 'extension', '{"en_US": "<data><xpath expr=\"//field[@name=''module_stock_sms'']\" position=\"replace\">\n                <field name=\"stock_move_sms_validation\"/>\n            </xpath>\n            <xpath expr=\"//setting[@id=''stock_sms'']\" position=\"attributes\">\n                <attribute name=\"string\">SMS Confirmation</attribute>\n            </xpath>\n            <xpath expr=\"//setting[@id=''stock_sms'']\" position=\"inside\">\n                <div class=\"row mt16\" invisible=\"not stock_move_sms_validation\">\n                    <label for=\"stock_sms_confirmation_template_id\" string=\"SMS Template\" class=\"col-lg-4 o_light_label\"/>\n                    <field name=\"stock_sms_confirmation_template_id\" class=\"oe_inline\" required=\"stock_move_sms_validation\" context=\"{''default_model'': ''stock.picking''}\"/>\n                </div>\n                <widget name=\"iap_buy_more_credits\" service_name=\"sms\" invisible=\"not stock_move_sms_validation\"/>\n            </xpath>\n        </data>"}', '<?xml version="1.0"?>
<data><xpath expr="//field[@name=''module_stock_sms'']" position="replace">
                <field name="stock_move_sms_validation"/>
            </xpath>
            <xpath expr="//setting[@id=''stock_sms'']" position="attributes">
                <attribute name="string">SMS Confirmation</attribute>
            </xpath>
            <xpath expr="//setting[@id=''stock_sms'']" position="inside">
                <div class="row mt16" invisible="not stock_move_sms_validation">
                    <label for="stock_sms_confirmation_template_id" string="SMS Template" class="col-lg-4 o_light_label"/>
                    <field name="stock_sms_confirmation_template_id" class="oe_inline" required="stock_move_sms_validation" context="{''default_model'': ''stock.picking''}"/>
                </div>
                <widget name="iap_buy_more_credits" service_name="sms" invisible="not stock_move_sms_validation"/>
            </xpath>
        </data>', false, true, '2026-05-10 01:12:24.139284', '2026-05-10 01:12:24.139284', false);
INSERT INTO public.ir_ui_view VALUES (1138, 16, NULL, 1, 1, 'stock_confirm_sms', 'confirm.stock.sms', NULL, 'form', 'stock_sms/wizard/confirm_stock_sms_views.xml', 'primary', '{"en_US": "<form string=\"SMS\">\n                You are about to confirm this Delivery Order by SMS Text Message.<br/>\n                This feature can easily be disabled from the Settings of Inventory or by clicking on \"Disable SMS\".<br/>\n                <footer>\n                    <button name=\"send_sms\" type=\"object\" data-hotkey=\"q\" string=\"Confirm\" class=\"oe_highlight\"/>\n                    <button name=\"dont_send_sms\" type=\"object\" data-hotkey=\"w\" string=\"Disable SMS\" class=\"btn btn-secondary\"/>\n                    <button special=\"cancel\" data-hotkey=\"x\" string=\"Cancel\"/>\n                </footer>\n            </form>"}', '<?xml version="1.0"?>
<form string="SMS">
                You are about to confirm this Delivery Order by SMS Text Message.<br/>
                This feature can easily be disabled from the Settings of Inventory or by clicking on "Disable SMS".<br/>
                <footer>
                    <button name="send_sms" type="object" data-hotkey="q" string="Confirm" class="oe_highlight"/>
                    <button name="dont_send_sms" type="object" data-hotkey="w" string="Disable SMS" class="btn btn-secondary"/>
                    <button special="cancel" data-hotkey="x" string="Cancel"/>
                </footer>
            </form>
        ', false, true, '2026-05-10 01:12:24.139284', '2026-05-10 01:12:24.139284', false);
INSERT INTO public.ir_ui_view VALUES (1139, 16, 883, 1, 1, 'sale.order.form.sale.stock', 'sale.order', NULL, 'form', 'sale_stock/views/sale_order_views.xml', 'extension', '{"en_US": "<data><xpath expr=\"//button[@name=''action_view_invoice'']\" position=\"before\">\n                    <button type=\"object\" name=\"action_view_delivery\" class=\"oe_stat_button\" icon=\"fa-truck\" invisible=\"delivery_count == 0\" groups=\"stock.group_stock_user\">\n                        <field name=\"delivery_count\" widget=\"statinfo\" string=\"Delivery\"/>\n                    </button>\n                </xpath>\n                <xpath expr=\"//group[@name=''sale_shipping'']\" position=\"attributes\">\n                    <attribute name=\"groups\"/><!-- Remove the res.group on the group and set it on the field directly-->\n                    <attribute name=\"string\">Delivery</attribute>\n                </xpath>\n                <xpath expr=\"//label[@for=''commitment_date'']\" position=\"before\">\n                    <field name=\"warehouse_id\" invisible=\"1\" readonly=\"state == ''sale''\"/>  <!-- needed for js logic -->\n                    <field name=\"warehouse_id\" options=\"{''no_create'': True}\" groups=\"stock.group_stock_multi_warehouses\" force_save=\"1\" readonly=\"state == ''sale''\"/>\n                    <field name=\"incoterm\" options=\"{''no_open'': True, ''no_create'': True}\"/>\n                    <field name=\"incoterm_location\"/>\n                    <field name=\"picking_policy\" required=\"True\" readonly=\"state not in [''draft'', ''sent'']\"/>\n                </xpath>\n                <xpath expr=\"//span[@name=''expected_date_span'']\" position=\"attributes\">\n                    <attribute name=\"invisible\">effective_date and commitment_date</attribute>\n                </xpath>\n                <xpath expr=\"//div[@name=''commitment_date_div'']\" position=\"replace\">\n                    <div class=\"o_row\">\n                        <field name=\"commitment_date\"/>\n                        <span class=\"text-muted\" invisible=\"effective_date and commitment_date\">Expected: <field name=\"expected_date\" class=\"oe_inline\" widget=\"date\"/></span>\n                    </div>\n                    <field name=\"effective_date\" invisible=\"not effective_date\"/>\n                </xpath>\n                <field name=\"effective_date\" position=\"after\">\n                    <field name=\"delivery_status\" invisible=\"state != ''sale''\"/>\n                </field>\n                <xpath expr=\"//page[@name=''other_information'']//field[@name=''expected_date'']\" position=\"after\">\n                    <field name=\"show_json_popover\" invisible=\"1\"/>\n                    <field string=\" \" name=\"json_popover\" widget=\"stock_rescheduling_popover\" invisible=\"not show_json_popover\"/>\n                </xpath>\n                <xpath expr=\"//field[@name=''order_line'']/form/group/group/field[@name=''analytic_distribution'']\" position=\"before\">\n                    <field name=\"route_id\" groups=\"stock.group_adv_location\" options=\"{''no_create'': True}\"/>\n                </xpath>\n                <xpath expr=\"//field[@name=''order_line'']/tree/field[@name=''analytic_distribution'']\" position=\"after\">\n                    <field name=\"route_id\" groups=\"stock.group_adv_location\" options=\"{''no_create'': True}\" optional=\"hide\"/>\n                </xpath>\n           </data>"}', '<?xml version="1.0"?>
<data><xpath expr="//button[@name=''action_view_invoice'']" position="before">
                    <button type="object" name="action_view_delivery" class="oe_stat_button" icon="fa-truck" invisible="delivery_count == 0" groups="stock.group_stock_user">
                        <field name="delivery_count" widget="statinfo" string="Delivery"/>
                    </button>
                </xpath>
                <xpath expr="//group[@name=''sale_shipping'']" position="attributes">
                    <attribute name="groups"/><!-- Remove the res.group on the group and set it on the field directly-->
                    <attribute name="string">Delivery</attribute>
                </xpath>
                <xpath expr="//label[@for=''commitment_date'']" position="before">
                    <field name="warehouse_id" invisible="1" readonly="state == ''sale''"/>  <!-- needed for js logic -->
                    <field name="warehouse_id" options="{''no_create'': True}" groups="stock.group_stock_multi_warehouses" force_save="1" readonly="state == ''sale''"/>
                    <field name="incoterm" options="{''no_open'': True, ''no_create'': True}"/>
                    <field name="incoterm_location"/>
                    <field name="picking_policy" required="True" readonly="state not in [''draft'', ''sent'']"/>
                </xpath>
                <xpath expr="//span[@name=''expected_date_span'']" position="attributes">
                    <attribute name="invisible">effective_date and commitment_date</attribute>
                </xpath>
                <xpath expr="//div[@name=''commitment_date_div'']" position="replace">
                    <div class="o_row">
                        <field name="commitment_date"/>
                        <span class="text-muted" invisible="effective_date and commitment_date">Expected: <field name="expected_date" class="oe_inline" widget="date"/></span>
                    </div>
                    <field name="effective_date" invisible="not effective_date"/>
                </xpath>
                <field name="effective_date" position="after">
                    <field name="delivery_status" invisible="state != ''sale''"/>
                </field>
                <xpath expr="//page[@name=''other_information'']//field[@name=''expected_date'']" position="after">
                    <field name="show_json_popover" invisible="1"/>
                    <field string=" " name="json_popover" widget="stock_rescheduling_popover" invisible="not show_json_popover"/>
                </xpath>
                <xpath expr="//field[@name=''order_line'']/form/group/group/field[@name=''analytic_distribution'']" position="before">
                    <field name="route_id" groups="stock.group_adv_location" options="{''no_create'': True}"/>
                </xpath>
                <xpath expr="//field[@name=''order_line'']/tree/field[@name=''analytic_distribution'']" position="after">
                    <field name="route_id" groups="stock.group_adv_location" options="{''no_create'': True}" optional="hide"/>
                </xpath>
           </data>', false, true, '2026-05-10 01:12:24.498351', '2026-05-10 01:12:24.498351', false);
INSERT INTO public.ir_ui_view VALUES (1140, 16, 879, 1, 1, 'sale.order.tree.inherit.sale.stock', 'sale.order', NULL, 'tree', 'sale_stock/views/sale_order_views.xml', 'extension', '{"en_US": "<field name=\"tag_ids\" position=\"after\">\n                    <field name=\"warehouse_id\" options=\"{''no_create'': True}\" groups=\"stock.group_stock_multi_warehouses\" optional=\"hide\" readonly=\"state == ''sale''\"/>\n                </field>"}', '<?xml version="1.0"?>
<field name="tag_ids" position="after">
                    <field name="warehouse_id" options="{''no_create'': True}" groups="stock.group_stock_multi_warehouses" optional="hide" readonly="state == ''sale''"/>
                </field>
            ', false, true, '2026-05-10 01:12:24.498351', '2026-05-10 01:12:24.498351', false);
INSERT INTO public.ir_ui_view VALUES (1147, 16, 1013, 1, 1, 'stock.production.lot.view.form', 'stock.lot', NULL, 'form', 'sale_stock/views/stock_lot_views.xml', 'extension', '{"en_US": "<data><xpath expr=\"//div[hasclass(''oe_button_box'')]/button\" position=\"before\">\n                <button class=\"oe_stat_button\" name=\"action_view_so\" type=\"object\" icon=\"fa-pencil-square-o\" help=\"Sale Orders\" invisible=\"sale_order_count == 0 or not display_complete\">\n                    <div class=\"o_field_widget o_stat_info\">\n                        <span class=\"o_stat_value\">\n                            <field name=\"sale_order_count\" widget=\"statinfo\" nolabel=\"1\" class=\"mr4\"/>\n                        </span>\n                        <span class=\"o_stat_text\">Sales</span>\n                    </div>\n                </button>\n            </xpath>\n            <xpath expr=\"//group[@name=''main_group'']\" position=\"after\">\n                <group>\n                    <field name=\"sale_order_ids\" widget=\"many2many\" readonly=\"True\" invisible=\"not sale_order_ids or display_complete\">\n                        <tree>\n                            <field name=\"name\" readonly=\"state != ''draft''\"/>\n                            <field name=\"partner_id\" readonly=\"state in [''cancel'', ''sale'']\"/>\n                            <field name=\"date_order\" readonly=\"state in [''cancel'', ''sale'']\"/>\n                            <field name=\"state\" column_invisible=\"True\"/>\n                        </tree>\n                    </field>\n                </group>\n            </xpath>\n        </data>"}', '<?xml version="1.0"?>
<data><xpath expr="//div[hasclass(''oe_button_box'')]/button" position="before">
                <button class="oe_stat_button" name="action_view_so" type="object" icon="fa-pencil-square-o" help="Sale Orders" invisible="sale_order_count == 0 or not display_complete">
                    <div class="o_field_widget o_stat_info">
                        <span class="o_stat_value">
                            <field name="sale_order_count" widget="statinfo" nolabel="1" class="mr4"/>
                        </span>
                        <span class="o_stat_text">Sales</span>
                    </div>
                </button>
            </xpath>
            <xpath expr="//group[@name=''main_group'']" position="after">
                <group>
                    <field name="sale_order_ids" widget="many2many" readonly="True" invisible="not sale_order_ids or display_complete">
                        <tree>
                            <field name="name" readonly="state != ''draft''"/>
                            <field name="partner_id" readonly="state in [''cancel'', ''sale'']"/>
                            <field name="date_order" readonly="state in [''cancel'', ''sale'']"/>
                            <field name="state" column_invisible="True"/>
                        </tree>
                    </field>
                </group>
            </xpath>
        </data>', false, true, '2026-05-10 01:12:24.498351', '2026-05-10 01:12:24.498351', false);
INSERT INTO public.ir_ui_view VALUES (1141, 16, 880, 1, 1, 'sale.order.tree.inherit.sale.stock', 'sale.order', NULL, 'tree', 'sale_stock/views/sale_order_views.xml', 'extension', '{"en_US": "<field name=\"invoice_status\" position=\"before\">\n                    <field name=\"effective_date\" column_invisible=\"True\"/>\n                    <field name=\"delivery_status\" optional=\"hide\" widget=\"badge\" decoration-success=\"commitment_date and (commitment_date &gt; datetime.datetime.combine(datetime.date.today(), datetime.time(23,59,59)).to_utc().strftime(''%Y-%m-%d %H:%M:%S'') or delivery_status==''full'' and effective_date &lt;= commitment_date)\" decoration-danger=\"commitment_date and (commitment_date &lt; effective_date or commitment_date &lt; datetime.datetime.combine(datetime.date.today(), datetime.time(0,0,0)).to_utc().strftime(''%Y-%m-%d %H:%M:%S'') and delivery_status!=''full'' and effective_date &lt;= commitment_date)\" decoration-warning=\"commitment_date and commitment_date &gt;= datetime.datetime.combine(datetime.date.today(), datetime.time(0,0,0)).to_utc().strftime(''%Y-%m-%d %H:%M:%S'') and commitment_date &lt;= datetime.datetime.combine(datetime.date.today(), datetime.time(23,59,59)).to_utc().strftime(''%Y-%m-%d %H:%M:%S'') and delivery_status!=''full''\"/>\n                </field>"}', '<?xml version="1.0"?>
<field name="invoice_status" position="before">
                    <field name="effective_date" column_invisible="True"/>
                    <field name="delivery_status" optional="hide" widget="badge" decoration-success="commitment_date and (commitment_date &gt; datetime.datetime.combine(datetime.date.today(), datetime.time(23,59,59)).to_utc().strftime(''%Y-%m-%d %H:%M:%S'') or delivery_status==''full'' and effective_date &lt;= commitment_date)" decoration-danger="commitment_date and (commitment_date &lt; effective_date or commitment_date &lt; datetime.datetime.combine(datetime.date.today(), datetime.time(0,0,0)).to_utc().strftime(''%Y-%m-%d %H:%M:%S'') and delivery_status!=''full'' and effective_date &lt;= commitment_date)" decoration-warning="commitment_date and commitment_date &gt;= datetime.datetime.combine(datetime.date.today(), datetime.time(0,0,0)).to_utc().strftime(''%Y-%m-%d %H:%M:%S'') and commitment_date &lt;= datetime.datetime.combine(datetime.date.today(), datetime.time(23,59,59)).to_utc().strftime(''%Y-%m-%d %H:%M:%S'') and delivery_status!=''full''"/>
                </field>
            ', false, true, '2026-05-10 01:12:24.498351', '2026-05-10 01:12:24.498351', false);
INSERT INTO public.ir_ui_view VALUES (1142, 16, 909, 1, 1, 'sale.order.line.tree.sale.stock.location', 'sale.order.line', NULL, 'tree', 'sale_stock/views/sale_order_views.xml', 'extension', '{"en_US": "<xpath expr=\"//field[@name=''price_subtotal'']\" position=\"before\">\n                    <field name=\"route_id\" groups=\"stock.group_adv_location\" options=\"{''no_create'': True}\"/>\n                </xpath>"}', '<?xml version="1.0"?>
