INSERT INTO public.ir_ui_view VALUES (1144, 16, 1089, 1, 1, 'stock.route.form', 'stock.route', NULL, 'form', 'sale_stock/views/stock_route_views.xml', 'extension', '{"en_US": "<xpath expr=\"//group[@name=''route_selector'']/group[last()]\" position=\"inside\">\n                <field name=\"sale_selectable\" string=\"Sales Order Lines\"/>\n            </xpath>"}', '<?xml version="1.0"?>
