INSERT INTO public.ir_ui_view VALUES (1145, 16, 1099, 1, 1, 'res.config.settings.view.form.inherit.sale.stock.stock', 'res.config.settings', NULL, 'form', 'sale_stock/views/res_config_settings_views.xml', 'extension', '{"en_US": "<data><setting id=\"warning_info\" position=\"after\">\n                <setting help=\"When to start shipping\">\n                    <field name=\"default_picking_policy\" class=\"o_light_label w-auto\" widget=\"selection\"/>\n                </setting>\n            </setting>\n            <xpath expr=\"//block[@id=''schedule_info'']\" position=\"attributes\">\n                <attribute name=\"invisible\">0</attribute>\n            </xpath>\n            <div id=\"sale_security_lead\" position=\"replace\">\n                <setting company_dependent=\"1\" help=\"Schedule deliveries earlier to avoid delays\" documentation=\"/applications/inventory_and_mrp/inventory/management/planning/scheduled_dates.html\" title=\"Margin of error for dates promised to customers. Products will be scheduled for procurement and delivery that many days earlier than the actual promised date, to cope with unexpected delays in the supply chain.\">\n                    <field name=\"use_security_lead\"/>\n                    <div class=\"content-group\">\n                        <div class=\"mt16\" invisible=\"not use_security_lead\">\n                            <span>Move forward expected delivery dates by <field name=\"security_lead\" class=\"oe_inline\"/> days</span>\n                        </div>\n                    </div>\n                </setting>\n            </div>\n        </data>"}', '<?xml version="1.0"?>
<data><setting id="warning_info" position="after">
                <setting help="When to start shipping">
                    <field name="default_picking_policy" class="o_light_label w-auto" widget="selection"/>
                </setting>
            </setting>
            <xpath expr="//block[@id=''schedule_info'']" position="attributes">
                <attribute name="invisible">0</attribute>
            </xpath>
            <div id="sale_security_lead" position="replace">
                <setting company_dependent="1" help="Schedule deliveries earlier to avoid delays" documentation="/applications/inventory_and_mrp/inventory/management/planning/scheduled_dates.html" title="Margin of error for dates promised to customers. Products will be scheduled for procurement and delivery that many days earlier than the actual promised date, to cope with unexpected delays in the supply chain.">
                    <field name="use_security_lead"/>
                    <div class="content-group">
                        <div class="mt16" invisible="not use_security_lead">
                            <span>Move forward expected delivery dates by <field name="security_lead" class="oe_inline"/> days</span>
                        </div>
                    </div>
                </setting>
            </div>
        </data>', false, true, '2026-05-10 01:12:24.498351', '2026-05-10 01:12:24.498351', false);
INSERT INTO public.ir_ui_view VALUES (1146, 16, 918, 1, 1, 'Orders Shipping Followup', NULL, 'sale_stock.sale_order_portal_content_inherit_sale_stock', 'qweb', 'sale_stock/views/sale_stock_portal_template.xml', 'extension', '{"en_US": "<data name=\"Orders Shipping Followup\" inherit_id=\"sale.sale_order_portal_content\">\n        <tbody id=\"sale_info_table\" position=\"inside\">\n            <tr t-if=\"sale_order.incoterm\">\n                <th class=\"pb-0\">Incoterm:</th>\n                <td class=\"w-100 pb-0 text-wrap\">\n                    <p t-if=\"sale_order.incoterm_location\">\n                        <span t-field=\"sale_order.incoterm.code\"/> <br/>\n                        <span t-field=\"sale_order.incoterm_location\"/>\n                    </p>\n                    <p t-else=\"\" t-field=\"sale_order.incoterm.code\" class=\"m-0\"/>\n                </td>\n            </tr>\n        </tbody>\n\n        <div id=\"sale_invoices\" position=\"after\">\n            <t t-set=\"delivery_orders\" t-value=\"sale_order.picking_ids.filtered(lambda picking: picking.picking_type_id.code == ''outgoing'').sorted(''date'', reverse=True)[:3]\"/>\n            <div t-if=\"delivery_orders\" class=\"col-12 col-lg-6 mb-4\">\n                <h4 class=\"mb-1\">Last Delivery Orders</h4>\n                <hr class=\"mt-1 mb-2\"/>\n                <div>\n                    <t t-foreach=\"delivery_orders\" t-as=\"picking\">\n                        <t t-set=\"delivery_report_url\" t-value=\"''/my/picking/pdf/%s?%s'' % (picking.id, keep_query())\"/>\n                        <div name=\"delivery_order\" class=\"d-flex flex-column\">\n                            <div name=\"delivery_details\" class=\"d-flex align-items-center justify-content-between\">\n                                <a t-att-href=\"delivery_report_url\">\n                                    <span t-esc=\"picking.name\"/>\n                                </a>\n                                <div t-if=\"picking.state == ''done''\">\n                                    <span class=\"small badge text-bg-success orders_label_text_align\">\n                                        <i class=\"fa fa-fw fa-truck\"/> Shipped\n                                    </span>\n                                    <a class=\"badge text-bg-secondary orders_label_text_align\" target=\"_blank\" t-att-href=\"''/my/picking/return/pdf/%s?%s'' % (picking.id, keep_query())\">\n                                        RETURN\n                                    </a>\n                                </div>\n                                <span t-elif=\"picking.state == ''cancel''\" class=\"small badge text-bg-danger orders_label_text_align\">\n                                    <i class=\"fa fa-fw fa-times\"/>Cancelled\n                                </span>\n                                <span t-elif=\"picking.state in [''draft'', ''waiting'', ''confirmed'', ''assigned'']\" class=\"small badge text-bg-info orders_label_text_align\">\n                                    <i class=\"fa fa-fw fa-clock-o\"/>Preparation\n                                </span>\n                            </div>\n                            <div class=\"small d-lg-inline-block\" t-if=\"picking.date_done or picking.scheduled_date\">\n                                Date:\n                                <span class=\"text-muted\" t-field=\"picking.date_done\" t-options=\"{''date_only'': True}\"/>\n                                <span t-if=\"picking.state in [''draft'', ''waiting'', ''confirmed'', ''assigned'']\" class=\"text-muted\" t-field=\"picking.scheduled_date\" t-options=\"{''date_only'': True}\"/>\n                            </div>\n                        </div>\n                    </t>\n                </div>\n            </div>\n            <t t-set=\"returns\" t-value=\"sale_order.picking_ids.filtered(lambda picking: picking.picking_type_id.code == ''incoming'')\"/>\n            <div t-if=\"returns\" class=\"col-12 col-lg-6 mb-4\">\n                <h4 class=\"mb-1\">Returns</h4>\n                <hr class=\"mt-1 mb-2\"/>\n                <t t-foreach=\"returns\" t-as=\"picking\">\n                    <t t-set=\"delivery_report_url\" t-value=\"''/my/picking/pdf/%s?%s'' % (picking.id, keep_query())\"/>\n                    <div name=\"return\">\n                        <div name=\"return_details\" class=\"d-flex justify-content-between align-items-center\">\n                            <a t-att-href=\"delivery_report_url\">\n                                <span t-esc=\"picking.name\"/>\n                            </a>\n                            <span t-if=\"picking.state == ''done''\" class=\"small badge text-bg-success orders_label_text_align\">\n                                <i class=\"fa fa-fw fa-truck\"/> Received\n                            </span>\n                            <span t-elif=\"picking.state == ''cancel''\" class=\"small badge text-bg-danger orders_label_text_align\">\n                                <i class=\"fa fa-fw fa-times\"/> Cancelled\n                            </span>\n                            <span t-elif=\"picking.state in [''draft'', ''waiting'', ''confirmed'', ''assigned'']\" class=\"small badge text-bg-info orders_label_text_align\">\n                                <i class=\"fa fa-fw fa-clock-o\"/> Awaiting arrival\n                            </span>\n                        </div>\n                        <div class=\"small d-lg-inline-block\">\n                            Date:\n                            <span class=\"text-muted\" t-field=\"picking.date_done\" t-options=\"{''date_only'': True}\"/>\n                            <span t-if=\"picking.state in [''draft'', ''waiting'', ''confirmed'', ''assigned'']\" class=\"text-muted\" t-field=\"picking.scheduled_date\" t-options=\"{''date_only'': True}\"/>\n                        </div>\n                    </div>\n                </t>\n            </div>\n        </div>\n    </data>"}', '<?xml version="1.0"?>
<data name="Orders Shipping Followup" inherit_id="sale.sale_order_portal_content">
        <tbody id="sale_info_table" position="inside">
            <tr t-if="sale_order.incoterm">
                <th class="pb-0">Incoterm:</th>
                <td class="w-100 pb-0 text-wrap">
                    <p t-if="sale_order.incoterm_location">
                        <span t-field="sale_order.incoterm.code"/> <br/>
                        <span t-field="sale_order.incoterm_location"/>
                    </p>
                    <p t-else="" t-field="sale_order.incoterm.code" class="m-0"/>
                </td>
            </tr>
        </tbody>

        <div id="sale_invoices" position="after">
            <t t-set="delivery_orders" t-value="sale_order.picking_ids.filtered(lambda picking: picking.picking_type_id.code == ''outgoing'').sorted(''date'', reverse=True)[:3]"/>
            <div t-if="delivery_orders" class="col-12 col-lg-6 mb-4">
                <h4 class="mb-1">Last Delivery Orders</h4>
                <hr class="mt-1 mb-2"/>
                <div>
                    <t t-foreach="delivery_orders" t-as="picking">
                        <t t-set="delivery_report_url" t-value="''/my/picking/pdf/%s?%s'' % (picking.id, keep_query())"/>
                        <div name="delivery_order" class="d-flex flex-column">
                            <div name="delivery_details" class="d-flex align-items-center justify-content-between">
                                <a t-att-href="delivery_report_url">
                                    <span t-esc="picking.name"/>
                                </a>
                                <div t-if="picking.state == ''done''">
                                    <span class="small badge text-bg-success orders_label_text_align">
                                        <i class="fa fa-fw fa-truck"/> Shipped
                                    </span>
                                    <a class="badge text-bg-secondary orders_label_text_align" target="_blank" t-att-href="''/my/picking/return/pdf/%s?%s'' % (picking.id, keep_query())">
                                        RETURN
                                    </a>
                                </div>
                                <span t-elif="picking.state == ''cancel''" class="small badge text-bg-danger orders_label_text_align">
                                    <i class="fa fa-fw fa-times"/>Cancelled
                                </span>
                                <span t-elif="picking.state in [''draft'', ''waiting'', ''confirmed'', ''assigned'']" class="small badge text-bg-info orders_label_text_align">
                                    <i class="fa fa-fw fa-clock-o"/>Preparation
                                </span>
                            </div>
                            <div class="small d-lg-inline-block" t-if="picking.date_done or picking.scheduled_date">
                                Date:
                                <span class="text-muted" t-field="picking.date_done" t-options="{''date_only'': True}"/>
                                <span t-if="picking.state in [''draft'', ''waiting'', ''confirmed'', ''assigned'']" class="text-muted" t-field="picking.scheduled_date" t-options="{''date_only'': True}"/>
                            </div>
                        </div>
                    </t>
                </div>
            </div>
            <t t-set="returns" t-value="sale_order.picking_ids.filtered(lambda picking: picking.picking_type_id.code == ''incoming'')"/>
            <div t-if="returns" class="col-12 col-lg-6 mb-4">
                <h4 class="mb-1">Returns</h4>
                <hr class="mt-1 mb-2"/>
                <t t-foreach="returns" t-as="picking">
                    <t t-set="delivery_report_url" t-value="''/my/picking/pdf/%s?%s'' % (picking.id, keep_query())"/>
                    <div name="return">
                        <div name="return_details" class="d-flex justify-content-between align-items-center">
                            <a t-att-href="delivery_report_url">
                                <span t-esc="picking.name"/>
                            </a>
                            <span t-if="picking.state == ''done''" class="small badge text-bg-success orders_label_text_align">
                                <i class="fa fa-fw fa-truck"/> Received
                            </span>
                            <span t-elif="picking.state == ''cancel''" class="small badge text-bg-danger orders_label_text_align">
                                <i class="fa fa-fw fa-times"/> Cancelled
                            </span>
                            <span t-elif="picking.state in [''draft'', ''waiting'', ''confirmed'', ''assigned'']" class="small badge text-bg-info orders_label_text_align">
                                <i class="fa fa-fw fa-clock-o"/> Awaiting arrival
                            </span>
                        </div>
                        <div class="small d-lg-inline-block">
                            Date:
                            <span class="text-muted" t-field="picking.date_done" t-options="{''date_only'': True}"/>
                            <span t-if="picking.state in [''draft'', ''waiting'', ''confirmed'', ''assigned'']" class="text-muted" t-field="picking.scheduled_date" t-options="{''date_only'': True}"/>
                        </div>
                    </div>
                </t>
            </div>
        </div>
    </data>

', false, true, '2026-05-10 01:12:24.498351', '2026-05-10 01:12:24.498351', false);
INSERT INTO public.ir_ui_view VALUES (1151, 16, 857, 1, 1, 'report_saleorder_document_inherit_sale_stock', NULL, 'sale_stock.report_saleorder_document_inherit_sale_stock', 'qweb', 'sale_stock/report/sale_order_report_templates.xml', 'extension', '{"en_US": "<data inherit_id=\"sale.report_saleorder_document\">\n        <xpath expr=\"//div[@name=''expiration_date'']\" position=\"after\">\n            <div class=\"col-auto col-3 mw-100 mb-2\" t-if=\"doc.incoterm\">\n                <strong>Incoterm:</strong>\n                <p t-if=\"doc.incoterm_location\">\n                    <span t-field=\"doc.incoterm.code\"/> <br/>\n                    <span t-field=\"doc.incoterm_location\"/>\n                </p>\n                <p t-else=\"\" t-field=\"doc.incoterm.code\" class=\"m-0\"/>\n            </div>\n        </xpath>\n    </data>"}', '<?xml version="1.0"?>
<data inherit_id="sale.report_saleorder_document">
        <xpath expr="//div[@name=''expiration_date'']" position="after">
            <div class="col-auto col-3 mw-100 mb-2" t-if="doc.incoterm">
                <strong>Incoterm:</strong>
                <p t-if="doc.incoterm_location">
                    <span t-field="doc.incoterm.code"/> <br/>
                    <span t-field="doc.incoterm_location"/>
                </p>
                <p t-else="" t-field="doc.incoterm.code" class="m-0"/>
            </div>
        </xpath>
    </data>
', false, true, '2026-05-10 01:12:24.498351', '2026-05-10 01:12:24.498351', false);
INSERT INTO public.ir_ui_view VALUES (1152, 16, 962, 1, 1, 'report_delivery_document_inherit_sale_stock', NULL, 'sale_stock.report_delivery_document_inherit_sale_stock', 'qweb', 'sale_stock/report/stock_report_deliveryslip.xml', 'extension', '{"en_US": "<data inherit_id=\"stock.report_delivery_document\">\n        <xpath expr=\"//div[@name=''div_sched_date'']\" position=\"after\">\n            <div t-if=\"o.sudo().sale_id.client_order_ref\" class=\"col-auto col-3 mw-100 mb-2\">\n                <strong>Customer Reference:</strong>\n                <p t-field=\"o.sudo().sale_id.client_order_ref\" class=\"m-0\">Customer reference</p>\n            </div>\n            <div class=\"col-auto col-3 justify-content-end\" t-if=\"o.sudo().sale_id.incoterm\">\n                <strong>Incoterm:</strong>\n                <p t-if=\"o.sudo().sale_id.incoterm_location\" t-out=\"''%s %s'' % (o.sudo().sale_id.incoterm.code, o.sudo().sale_id.incoterm_location)\">Incoterm details</p>\n                <p t-else=\"\" t-field=\"o.sudo().sale_id.incoterm.display_name\">Incoterm details</p>\n            </div>\n        </xpath>\n    </data>"}', '<?xml version="1.0"?>
<data inherit_id="stock.report_delivery_document">
        <xpath expr="//div[@name=''div_sched_date'']" position="after">
            <div t-if="o.sudo().sale_id.client_order_ref" class="col-auto col-3 mw-100 mb-2">
                <strong>Customer Reference:</strong>
                <p t-field="o.sudo().sale_id.client_order_ref" class="m-0">Customer reference</p>
            </div>
            <div class="col-auto col-3 justify-content-end" t-if="o.sudo().sale_id.incoterm">
                <strong>Incoterm:</strong>
                <p t-if="o.sudo().sale_id.incoterm_location" t-out="''%s %s'' % (o.sudo().sale_id.incoterm.code, o.sudo().sale_id.incoterm_location)">Incoterm details</p>
                <p t-else="" t-field="o.sudo().sale_id.incoterm.display_name">Incoterm details</p>
            </div>
        </xpath>
    </data>
', false, true, '2026-05-10 01:12:24.498351', '2026-05-10 01:12:24.498351', false);
INSERT INTO public.ir_ui_view VALUES (1153, 16, NULL, 1, 1, 'exception_on_so', NULL, 'sale_stock.exception_on_so', 'qweb', 'sale_stock/data/mail_templates.xml', 'primary', '{"en_US": "<t t-name=\"sale_stock.exception_on_so\">\n            <div>\n                Exception(s) occurred on the sale order(s):\n                <t t-foreach=\"sale_order_ids\" t-as=\"sale_order\">\n                    <a href=\"#\" data-oe-model=\"sale.order\" t-att-data-oe-id=\"sale_order.id\"><t t-esc=\"sale_order.name\"/></a>.\n                </t>\n                Manual actions may be needed.\n                <div class=\"mt16\">\n                    <p>Exception(s):</p>\n                    <ul t-foreach=\"order_exceptions\" t-as=\"exception\">\n                        <li>\n                            <t t-set=\"order_line\" t-value=\"exception[0]\"/>\n                            <t t-set=\"new_qty\" t-value=\"exception[1][0]\"/>\n                            <t t-set=\"old_qty\" t-value=\"exception[1][1]\"/>\n                                <a href=\"#\" data-oe-model=\"sale.order\" t-att-data-oe-id=\"order_line.order_id.id\"><t t-esc=\"order_line.order_id.name\"/></a>:\n                                <t t-esc=\"new_qty\"/> <t t-esc=\"order_line.product_uom.name\"/> of <t t-esc=\"order_line.product_id.name\"/>\n                                <t t-if=\"cancel\">\n                                    cancelled\n                                </t>\n                                <t t-if=\"not cancel\">\n                                    ordered instead of <t t-esc=\"old_qty\"/> <t t-esc=\"order_line.product_uom.name\"/>\n                                </t>\n                          </li>\n                    </ul>\n                </div>\n                <div class=\"mt16\" t-if=\"not cancel and impacted_pickings\">\n                    <p>Impacted Transfer(s):</p>\n                    <ul t-foreach=\"impacted_pickings\" t-as=\"picking\">\n                        <li><a href=\"#\" data-oe-model=\"stock.picking\" t-att-data-oe-id=\"picking.id\"><t t-esc=\"picking.name\"/></a></li>\n                    </ul>\n                </div>\n            </div>\n        </t>"}', '<?xml version="1.0"?>
<t t-name="sale_stock.exception_on_so">
            <div>
                Exception(s) occurred on the sale order(s):
                <t t-foreach="sale_order_ids" t-as="sale_order">
                    <a href="#" data-oe-model="sale.order" t-att-data-oe-id="sale_order.id"><t t-esc="sale_order.name"/></a>.
                </t>
                Manual actions may be needed.
                <div class="mt16">
                    <p>Exception(s):</p>
                    <ul t-foreach="order_exceptions" t-as="exception">
                        <li>
                            <t t-set="order_line" t-value="exception[0]"/>
                            <t t-set="new_qty" t-value="exception[1][0]"/>
                            <t t-set="old_qty" t-value="exception[1][1]"/>
                                <a href="#" data-oe-model="sale.order" t-att-data-oe-id="order_line.order_id.id"><t t-esc="order_line.order_id.name"/></a>:
                                <t t-esc="new_qty"/> <t t-esc="order_line.product_uom.name"/> of <t t-esc="order_line.product_id.name"/>
                                <t t-if="cancel">
                                    cancelled
                                </t>
                                <t t-if="not cancel">
                                    ordered instead of <t t-esc="old_qty"/> <t t-esc="order_line.product_uom.name"/>
                                </t>
                          </li>
                    </ul>
                </div>
                <div class="mt16" t-if="not cancel and impacted_pickings">
                    <p>Impacted Transfer(s):</p>
                    <ul t-foreach="impacted_pickings" t-as="picking">
                        <li><a href="#" data-oe-model="stock.picking" t-att-data-oe-id="picking.id"><t t-esc="picking.name"/></a></li>
                    </ul>
                </div>
            </div>
        </t>

        ', false, true, '2026-05-10 01:12:24.498351', '2026-05-10 01:12:24.498351', false);
INSERT INTO public.ir_ui_view VALUES (1154, 16, NULL, 1, 1, 'exception_on_picking', NULL, 'sale_stock.exception_on_picking', 'qweb', 'sale_stock/data/mail_templates.xml', 'primary', '{"en_US": "<t t-name=\"sale_stock.exception_on_picking\">\n            <div>\n                Exception(s) occurred on the picking:\n                <a href=\"#\" data-oe-model=\"stock.picking\" t-att-data-oe-id=\"origin_picking.id\"><t t-esc=\"origin_picking.name\"/></a>.\n                Manual actions may be needed.\n                <div class=\"mt16\">\n                    <p>Exception(s):</p>\n                    <ul t-foreach=\"moves_information\" t-as=\"exception\">\n                        <t t-set=\"move\" t-value=\"exception[0]\"/>\n                        <t t-set=\"new_qty\" t-value=\"exception[1][0]\"/>\n                        <t t-set=\"old_qty\" t-value=\"exception[1][1]\"/>\n                        <li>\n                        <t t-esc=\"new_qty\"/> <t t-esc=\"move.product_uom.name\"/>\n                        of <t t-esc=\"move.product_id.display_name\"/> processed instead of <t t-esc=\"old_qty\"/> <t t-esc=\"move.product_uom.name\"/></li>\n                    </ul>\n                </div>\n            </div>\n        </t>"}', '<?xml version="1.0"?>
<t t-name="sale_stock.exception_on_picking">
            <div>
                Exception(s) occurred on the picking:
                <a href="#" data-oe-model="stock.picking" t-att-data-oe-id="origin_picking.id"><t t-esc="origin_picking.name"/></a>.
                Manual actions may be needed.
                <div class="mt16">
                    <p>Exception(s):</p>
                    <ul t-foreach="moves_information" t-as="exception">
                        <t t-set="move" t-value="exception[0]"/>
                        <t t-set="new_qty" t-value="exception[1][0]"/>
                        <t t-set="old_qty" t-value="exception[1][1]"/>
                        <li>
                        <t t-esc="new_qty"/> <t t-esc="move.product_uom.name"/>
                        of <t t-esc="move.product_id.display_name"/> processed instead of <t t-esc="old_qty"/> <t t-esc="move.product_uom.name"/></li>
                    </ul>
                </div>
            </div>
        </t>
    ', false, true, '2026-05-10 01:12:24.498351', '2026-05-10 01:12:24.498351', false);
INSERT INTO public.ir_ui_view VALUES (1155, 16, 994, 1, 1, 'Stock Rules Report Sale', 'stock.rules.report', NULL, 'form', 'sale_stock/wizard/stock_rules_report_views.xml', 'extension', '{"en_US": "<xpath expr=\"//field[@name=''warehouse_ids'']\" position=\"after\">\n                <field name=\"so_route_ids\" widget=\"many2many_tags\" groups=\"stock.group_adv_location\"/>\n            </xpath>"}', '<?xml version="1.0"?>
<xpath expr="//field[@name=''warehouse_ids'']" position="after">
                <field name="so_route_ids" widget="many2many_tags" groups="stock.group_adv_location"/>
            </xpath>
