INSERT INTO public.ir_ui_view VALUES (1156, 16, 872, 1, 1, 'sale.order.cancel.form.inherit', 'sale.order.cancel', NULL, 'form', 'sale_stock/wizard/sale_order_cancel_views.xml', 'extension', '{"en_US": "<span id=\"display_invoice_alert\" position=\"after\">\n                <field name=\"display_delivery_alert\" invisible=\"1\"/>\n                <span invisible=\"not display_delivery_alert\">\n                    Some deliveries are already done. Returns can be created from the Delivery Orders.\n                </span>\n            </span>"}', '<?xml version="1.0"?>
<span id="display_invoice_alert" position="after">
                <field name="display_delivery_alert" invisible="1"/>
                <span invisible="not display_delivery_alert">
                    Some deliveries are already done. Returns can be created from the Delivery Orders.
                </span>
            </span>
