INSERT INTO public.ir_ui_view VALUES (1157, 16, 676, 1, 1, 'account.move.inherit.purchase', 'account.move', NULL, 'form', 'purchase/views/account_move_views.xml', 'extension', '{"en_US": "<data><!-- Auto-complete could be done from either a bill either a purchase order -->\n            <field name=\"invoice_vendor_bill_id\" position=\"after\">\n                <t groups=\"purchase.group_purchase_user\">\n                    <field name=\"purchase_id\" invisible=\"1\" readonly=\"state != ''draft''\"/>\n                    <label for=\"purchase_vendor_bill_id\" string=\"Auto-Complete\" class=\"oe_edit_only\" invisible=\"state != ''draft'' or move_type != ''in_invoice''\"/>\n                    <field name=\"purchase_vendor_bill_id\" nolabel=\"1\" invisible=\"state != ''draft'' or move_type != ''in_invoice''\" readonly=\"state != ''draft''\" class=\"oe_edit_only\" domain=\"partner_id and [(''partner_id.commercial_partner_id'', ''='', commercial_partner_id)] or []\" placeholder=\"Select a purchase order or an old bill\" context=\"{''show_total_amount'': True}\" options=\"{''no_create'': True, ''no_open'': True}\"/>\n                </t>\n            </field>\n            <label name=\"invoice_vendor_bill_id_label\" position=\"attributes\">\n                <attribute name=\"groups\">!purchase.group_purchase_user</attribute>\n            </label>\n            <field name=\"invoice_vendor_bill_id\" position=\"attributes\">\n                <attribute name=\"groups\">!purchase.group_purchase_user</attribute>\n            </field>\n            <!-- Add link to purchase_line_id to account.move.line -->\n            <xpath expr=\"//field[@name=''invoice_line_ids'']/tree/field[@name=''company_id'']\" position=\"after\">\n                <field name=\"purchase_line_id\" groups=\"purchase.group_purchase_user\" column_invisible=\"True\"/>\n                <field name=\"purchase_order_id\" groups=\"purchase.group_purchase_user\" column_invisible=\"parent.move_type != ''in_invoice''\" optional=\"hide\"/>\n            </xpath>\n            <xpath expr=\"//field[@name=''line_ids'']/tree/field[@name=''company_id'']\" position=\"after\">\n                <field name=\"purchase_line_id\" groups=\"purchase.group_purchase_user\" column_invisible=\"True\"/>\n            </xpath>\n            <xpath expr=\"//div[@name=''button_box'']\" position=\"inside\">\n                <button class=\"oe_stat_button\" name=\"action_view_source_purchase_orders\" type=\"object\" groups=\"purchase.group_purchase_user\" icon=\"fa-pencil-square-o\" invisible=\"purchase_order_count == 0 or move_type not in (''out_invoice'', ''out_refund'', ''in_invoice'', ''in_refund'', ''out_receipt'', ''in_receipt'')\">\n                    <field string=\"Purchases\" name=\"purchase_order_count\" widget=\"statinfo\"/>\n                </button>\n            </xpath>\n        </data>"}', '<?xml version="1.0"?>
<data><!-- Auto-complete could be done from either a bill either a purchase order -->
            <field name="invoice_vendor_bill_id" position="after">
                <t groups="purchase.group_purchase_user">
                    <field name="purchase_id" invisible="1" readonly="state != ''draft''"/>
                    <label for="purchase_vendor_bill_id" string="Auto-Complete" class="oe_edit_only" invisible="state != ''draft'' or move_type != ''in_invoice''"/>
                    <field name="purchase_vendor_bill_id" nolabel="1" invisible="state != ''draft'' or move_type != ''in_invoice''" readonly="state != ''draft''" class="oe_edit_only" domain="partner_id and [(''partner_id.commercial_partner_id'', ''='', commercial_partner_id)] or []" placeholder="Select a purchase order or an old bill" context="{''show_total_amount'': True}" options="{''no_create'': True, ''no_open'': True}"/>
                </t>
            </field>
            <label name="invoice_vendor_bill_id_label" position="attributes">
                <attribute name="groups">!purchase.group_purchase_user</attribute>
            </label>
            <field name="invoice_vendor_bill_id" position="attributes">
                <attribute name="groups">!purchase.group_purchase_user</attribute>
            </field>
            <!-- Add link to purchase_line_id to account.move.line -->
            <xpath expr="//field[@name=''invoice_line_ids'']/tree/field[@name=''company_id'']" position="after">
                <field name="purchase_line_id" groups="purchase.group_purchase_user" column_invisible="True"/>
                <field name="purchase_order_id" groups="purchase.group_purchase_user" column_invisible="parent.move_type != ''in_invoice''" optional="hide"/>
            </xpath>
            <xpath expr="//field[@name=''line_ids'']/tree/field[@name=''company_id'']" position="after">
                <field name="purchase_line_id" groups="purchase.group_purchase_user" column_invisible="True"/>
            </xpath>
            <xpath expr="//div[@name=''button_box'']" position="inside">
                <button class="oe_stat_button" name="action_view_source_purchase_orders" type="object" groups="purchase.group_purchase_user" icon="fa-pencil-square-o" invisible="purchase_order_count == 0 or move_type not in (''out_invoice'', ''out_refund'', ''in_invoice'', ''in_refund'', ''out_receipt'', ''in_receipt'')">
                    <field string="Purchases" name="purchase_order_count" widget="statinfo"/>
                </button>
            </xpath>
        </data>', false, true, '2026-05-10 01:12:29.662147', '2026-05-10 01:12:29.662147', false);
INSERT INTO public.ir_ui_view VALUES (1158, 2, NULL, 1, 1, 'purchase.order.calendar', 'purchase.order', NULL, 'calendar', 'purchase/views/purchase_views.xml', 'primary', '{"en_US": "<calendar string=\"Calendar View\" date_start=\"date_calendar_start\" color=\"partner_id\" hide_time=\"true\" event_limit=\"5\" create=\"false\">\n                    <field name=\"currency_id\" invisible=\"1\"/>\n                    <field name=\"partner_ref\"/>\n                    <field name=\"amount_total\" widget=\"monetary\"/>\n                    <field name=\"partner_id\" filters=\"1\"/>\n                </calendar>"}', '<?xml version="1.0"?>
<calendar string="Calendar View" date_start="date_calendar_start" color="partner_id" hide_time="true" event_limit="5" create="false">
                    <field name="currency_id" invisible="1"/>
                    <field name="partner_ref"/>
                    <field name="amount_total" widget="monetary"/>
                    <field name="partner_id" filters="1"/>
                </calendar>
            ', false, true, '2026-05-10 01:12:29.662147', '2026-05-10 01:12:29.662147', false);
INSERT INTO public.ir_ui_view VALUES (1159, 16, NULL, 1, 1, 'purchase.order.pivot', 'purchase.order', NULL, 'pivot', 'purchase/views/purchase_views.xml', 'primary', '{"en_US": "<pivot string=\"Purchase Order\" display_quantity=\"1\" sample=\"1\">\n                    <field name=\"partner_id\" type=\"row\"/>\n                    <field name=\"amount_total\" type=\"measure\"/>\n                </pivot>"}', '<?xml version="1.0"?>
