INSERT INTO public.ir_ui_view VALUES (1160, 16, NULL, 1, 1, 'purchase.order.graph', 'purchase.order', NULL, 'graph', 'purchase/views/purchase_views.xml', 'primary', '{"en_US": "<graph string=\"Purchase Order\" sample=\"1\">\n                    <field name=\"partner_id\"/>\n                    <field name=\"amount_total\" type=\"measure\"/>\n                </graph>"}', '<?xml version="1.0"?>
