INSERT INTO public.ir_ui_view VALUES (1161, 16, NULL, 1, 1, 'purchase.order.form', 'purchase.order', NULL, 'form', 'purchase/views/purchase_views.xml', 'primary', '{"en_US": "<form string=\"Purchase Order\" class=\"o_purchase_order\">\n                <header>\n                    <button name=\"action_rfq_send\" invisible=\"state != ''draft''\" string=\"Send by Email\" type=\"object\" context=\"{''send_rfq'':True}\" class=\"oe_highlight\" data-hotkey=\"g\"/>\n                    <button name=\"print_quotation\" string=\"Print RFQ\" type=\"object\" invisible=\"state != ''draft''\" class=\"oe_highlight\" groups=\"base.group_user\" data-hotkey=\"k\"/>\n                    <button name=\"button_confirm\" type=\"object\" invisible=\"state != ''sent''\" string=\"Confirm Order\" context=\"{''validate_analytic'': True}\" class=\"oe_highlight\" id=\"bid_confirm\" data-hotkey=\"q\"/>\n                    <button name=\"button_approve\" type=\"object\" invisible=\"state != ''to approve''\" string=\"Approve Order\" class=\"oe_highlight\" groups=\"purchase.group_purchase_manager\" data-hotkey=\"z\"/>\n                    <button name=\"action_create_invoice\" string=\"Create Bill\" type=\"object\" class=\"oe_highlight\" context=\"{''create_bill'':True}\" invisible=\"state not in (''purchase'', ''done'') or invoice_status in (''no'', ''invoiced'')\" data-hotkey=\"w\"/>\n                    <button name=\"action_rfq_send\" invisible=\"state != ''sent''\" string=\"Re-Send by Email\" type=\"object\" context=\"{''send_rfq'':True}\" data-hotkey=\"g\"/>\n                    <button name=\"print_quotation\" string=\"Print RFQ\" type=\"object\" invisible=\"state != ''sent''\" groups=\"base.group_user\" data-hotkey=\"k\"/>\n                    <button name=\"button_confirm\" type=\"object\" invisible=\"state != ''draft''\" context=\"{''validate_analytic'': True}\" string=\"Confirm Order\" id=\"draft_confirm\" data-hotkey=\"q\"/>\n                    <button name=\"action_rfq_send\" invisible=\"state != ''purchase''\" string=\"Send PO by Email\" type=\"object\" context=\"{''send_rfq'':False}\" data-hotkey=\"g\"/>\n                    <button name=\"confirm_reminder_mail\" string=\"Confirm Receipt Date\" type=\"object\" invisible=\"state not in (''purchase'', ''done'') or mail_reminder_confirmed or not date_planned\" groups=\"base.group_no_one\" data-hotkey=\"o\"/>\n                    <button name=\"action_create_invoice\" string=\"Create Bill\" type=\"object\" context=\"{''create_bill'':True}\" invisible=\"state not in (''purchase'', ''done'') or invoice_status not in (''no'', ''invoiced'') or not order_line\" data-hotkey=\"w\"/>\n                    <button name=\"button_draft\" invisible=\"state != ''cancel''\" string=\"Set to Draft\" type=\"object\" data-hotkey=\"o\"/>\n                    <button name=\"button_cancel\" invisible=\"state not in (''draft'', ''to approve'', ''sent'', ''purchase'')\" string=\"Cancel\" type=\"object\" data-hotkey=\"x\"/>\n                    <button name=\"button_done\" type=\"object\" string=\"Lock\" invisible=\"state != ''purchase''\" data-hotkey=\"l\"/>\n                    <button name=\"button_unlock\" type=\"object\" string=\"Unlock\" invisible=\"state != ''done''\" groups=\"purchase.group_purchase_manager\" data-hotkey=\"l\"/>\n                    <field name=\"state\" widget=\"statusbar\" statusbar_visible=\"draft,sent,purchase\" readonly=\"1\"/>\n                </header>\n                <sheet>\n                    <div class=\"oe_button_box\" name=\"button_box\">\n                        <button type=\"object\" name=\"action_view_invoice\" class=\"oe_stat_button\" icon=\"fa-pencil-square-o\" invisible=\"invoice_count == 0 or state in (''draft'', ''sent'', ''to approve'')\">\n                            <field name=\"invoice_count\" widget=\"statinfo\" string=\"Vendor Bills\"/>\n                            <field name=\"invoice_ids\" invisible=\"1\"/>\n                        </button>\n                    </div>\n                    <div class=\"oe_title\">\n                        <span class=\"o_form_label\" invisible=\"state not in (''draft'', ''sent'')\">Request for Quotation </span>\n                        <span class=\"o_form_label\" invisible=\"state in (''draft'', ''sent'')\">Purchase Order </span>\n                        <h1 class=\"d-flex\">\n                            <field name=\"priority\" widget=\"priority\" class=\"me-3\"/>\n                            <field name=\"name\" readonly=\"1\"/>\n                        </h1>\n                    </div>\n                    <group>\n                        <group>\n                            <field name=\"partner_id\" widget=\"res_partner_many2one\" context=\"{''res_partner_search_mode'': ''supplier'', ''show_vat'': True}\" placeholder=\"Name, TIN, Email, or Reference\" readonly=\"state in [''cancel'', ''done'', ''purchase'']\"/>\n                            <field name=\"partner_ref\"/>\n                            <field name=\"currency_id\" groups=\"base.group_multi_currency\" force_save=\"1\" readonly=\"state in [''cancel'', ''done'', ''purchase'']\"/>\n                            <field name=\"id\" invisible=\"1\"/>\n                            <field name=\"company_id\" invisible=\"1\" readonly=\"state in [''cancel'', ''done'', ''purchase'']\"/>\n                            <field name=\"currency_id\" invisible=\"1\" readonly=\"state in [''cancel'', ''done'', ''purchase'']\" groups=\"!base.group_multi_currency\"/>\n                            <field name=\"tax_calculation_rounding_method\" invisible=\"1\"/>\n                        </group>\n                        <group>\n                            <field name=\"date_order\" invisible=\"state in (''purchase'', ''done'')\" readonly=\"state in [''cancel'', ''done'', ''purchase'']\"/>\n                            <label for=\"date_approve\" invisible=\"state not in (''purchase'', ''done'')\"/>\n                            <div name=\"date_approve\" invisible=\"state not in (''purchase'', ''done'')\" class=\"o_row\">\n                                <field name=\"date_approve\"/>\n                                <field name=\"mail_reception_confirmed\" invisible=\"1\"/>\n                                <span class=\"text-muted\" invisible=\"not mail_reception_confirmed\">(confirmed by vendor)</span>\n                            </div>\n                            <label for=\"date_planned\"/>\n                            <div name=\"date_planned_div\" class=\"o_row\">\n                                <field name=\"date_planned\" readonly=\"state not in (''draft'', ''sent'', ''to approve'', ''purchase'')\"/>\n                                <field name=\"mail_reminder_confirmed\" invisible=\"1\"/>\n                                <span class=\"text-muted\" invisible=\"not mail_reminder_confirmed\">(confirmed by vendor)</span>\n                            </div>\n                            <label for=\"receipt_reminder_email\" class=\"d-none\" groups=\"purchase.group_send_reminder\"/>\n                            <div name=\"reminder\" class=\"o_row\" groups=\"purchase.group_send_reminder\" title=\"Automatically send a confirmation email to the vendor X days before the expected receipt date, asking him to confirm the exact date.\">\n                                <field name=\"receipt_reminder_email\"/>\n                                <span>Ask confirmation</span>\n                                <div class=\"o_row oe_inline\" invisible=\"not receipt_reminder_email\">\n                                    <field name=\"reminder_date_before_receipt\"/>\n                                    day(s) before\n                                    <widget name=\"toaster_button\" button_name=\"send_reminder_preview\" title=\"Preview the reminder email by sending it to yourself.\" invisible=\"not id\"/>\n                                </div>\n                            </div>\n                        </group>\n                    </group>\n                    <notebook>\n                        <page string=\"Products\" name=\"products\">\n                            <field name=\"tax_country_id\" invisible=\"1\"/>\n                            <field name=\"order_line\" widget=\"section_and_note_one2many\" mode=\"tree,kanban\" context=\"{''default_state'': ''draft''}\" readonly=\"state in (''done'', ''cancel'')\">\n                                <tree string=\"Purchase Order Lines\" editable=\"bottom\">\n                                    <control>\n                                        <create name=\"add_product_control\" string=\"Add a product\"/>\n                                        <create name=\"add_section_control\" string=\"Add a section\" context=\"{''default_display_type'': ''line_section''}\"/>\n                                        <create name=\"add_note_control\" string=\"Add a note\" context=\"{''default_display_type'': ''line_note''}\"/>\n                                        <button name=\"action_add_from_catalog\" string=\"Catalog\" type=\"object\" class=\"px-4 btn-link\" context=\"{''order_id'': parent.id}\"/>\n                                    </control>\n                                    <field name=\"tax_calculation_rounding_method\" column_invisible=\"True\"/>\n                                    <field name=\"display_type\" column_invisible=\"True\"/>\n                                    <field name=\"company_id\" column_invisible=\"True\"/>\n                                    <field name=\"currency_id\" column_invisible=\"True\"/>\n                                    <field name=\"state\" column_invisible=\"True\"/>\n                                    <field name=\"product_type\" column_invisible=\"True\"/>\n                                    <field name=\"product_uom\" column_invisible=\"True\" groups=\"!uom.group_uom\"/>\n                                    <field name=\"product_uom_category_id\" column_invisible=\"True\"/>\n                                    <field name=\"invoice_lines\" column_invisible=\"True\"/>\n                                    <field name=\"sequence\" widget=\"handle\"/>\n                                    <field name=\"product_id\" readonly=\"state in (''purchase'', ''to approve'', ''done'', ''cancel'')\" required=\"not display_type\" width=\"35%\" context=\"{''partner_id'': parent.partner_id, ''quantity'': product_qty, ''company_id'': parent.company_id, ''use_partner_name'': False}\" force_save=\"1\" domain=\"[(''purchase_ok'', ''='', True), ''|'', (''company_id'', ''='', False), (''company_id'', ''parent_of'', parent.company_id)]\"/>\n                                    <field name=\"name\" widget=\"section_and_note_text\"/>\n                                    <field name=\"date_planned\" optional=\"hide\" required=\"not display_type\" force_save=\"1\"/>\n                                    <field name=\"analytic_distribution\" widget=\"analytic_distribution\" optional=\"hide\" groups=\"analytic.group_analytic_accounting\" options=\"{''product_field'': ''product_id'', ''business_domain'': ''purchase_order'', ''amount_field'': ''price_subtotal''}\"/>\n                                    <field name=\"product_qty\"/>\n                                    <field name=\"qty_received_manual\" column_invisible=\"True\"/>\n                                    <field name=\"qty_received_method\" column_invisible=\"True\"/>\n                                    <field name=\"qty_received\" string=\"Received\" column_invisible=\"parent.state not in (''purchase'', ''done'')\" readonly=\"qty_received_method != ''manual''\" optional=\"show\"/>\n                                    <field name=\"qty_invoiced\" string=\"Billed\" column_invisible=\"parent.state not in (''purchase'', ''done'')\" optional=\"show\"/>\n                                    <field name=\"product_uom\" string=\"UoM\" groups=\"uom.group_uom\" readonly=\"state in (''purchase'', ''done'', ''cancel'')\" required=\"not display_type\" options=\"{''no_open'': True}\" force_save=\"1\" optional=\"show\"/>\n                                    <field name=\"product_packaging_qty\" invisible=\"not product_id or not product_packaging_id\" groups=\"product.group_stock_packaging\" optional=\"show\"/>\n                                    <field name=\"product_packaging_id\" invisible=\"not product_id\" context=\"{''default_product_id'': product_id, ''tree_view_ref'':''product.product_packaging_tree_view'', ''form_view_ref'':''product.product_packaging_form_view''}\" groups=\"product.group_stock_packaging\" optional=\"show\"/>\n                                    <field name=\"price_unit\" readonly=\"qty_invoiced != 0\"/>\n                                    <button name=\"action_purchase_history\" type=\"object\" icon=\"fa-history\" title=\"Purchase History\" invisible=\"not id\"/>\n                                    <field name=\"taxes_id\" widget=\"many2many_tags\" domain=\"[(''type_tax_use'', ''='', ''purchase''), (''company_id'', ''parent_of'', parent.company_id), (''country_id'', ''='', parent.tax_country_id), (''active'', ''='', True)]\" context=\"{''default_type_tax_use'': ''purchase'', ''search_view_ref'': ''account.account_tax_view_search''}\" options=\"{''no_create'': True}\" optional=\"show\"/>\n                                    <field name=\"discount\" string=\"Disc.%\" readonly=\"qty_invoiced != 0\" optional=\"hide\"/>\n                                    <field name=\"price_subtotal\" string=\"Tax excl.\"/>\n                                    <field name=\"price_total\" string=\"Tax incl.\" column_invisible=\"parent.tax_calculation_rounding_method == ''round_globally''\" optional=\"hide\"/>\n                                </tree>\n                                <form string=\"Purchase Order Line\">\n                                        <field name=\"tax_calculation_rounding_method\" invisible=\"1\"/>\n                                        <field name=\"state\" invisible=\"1\"/>\n                                        <field name=\"display_type\" invisible=\"1\"/>\n                                        <field name=\"company_id\" invisible=\"1\"/>\n                                        <group invisible=\"display_type\">\n                                            <group>\n                                                <field name=\"product_uom_category_id\" invisible=\"1\"/>\n                                                <field name=\"product_id\" context=\"{''partner_id'': parent.partner_id}\" widget=\"many2one_barcode\" domain=\"[(''purchase_ok'', ''='', True), ''|'', (''company_id'', ''='', False), (''company_id'', ''='', parent.company_id)]\" readonly=\"state in (''purchase'', ''to approve'', ''done'', ''cancel'')\"/>\n                                                <label for=\"product_qty\"/>\n                                                <div class=\"o_row\">\n                                                    <field name=\"product_qty\"/>\n                                                    <field name=\"product_uom\" groups=\"uom.group_uom\" required=\"not display_type\"/>\n                                                </div>\n                                                <field name=\"qty_received_method\" invisible=\"1\"/>\n                                                <field name=\"qty_received\" string=\"Received Quantity\" invisible=\"parent.state not in (''purchase'', ''done'')\" readonly=\"qty_received_method != ''manual''\"/>\n                                                <field name=\"qty_invoiced\" string=\"Billed Quantity\" invisible=\"parent.state not in (''purchase'', ''done'')\"/>\n                                                <field name=\"product_packaging_qty\" invisible=\"not product_id or not product_packaging_id\" groups=\"product.group_stock_packaging\"/>\n                                                <field name=\"product_packaging_id\" invisible=\"not product_id\" context=\"{''default_product_id'': product_id, ''tree_view_ref'':''product.product_packaging_tree_view'', ''form_view_ref'':''product.product_packaging_form_view''}\" groups=\"product.group_stock_packaging\"/>\n                                                <field name=\"price_unit\"/>\n                                                <field name=\"discount\"/>\n                                                <field name=\"taxes_id\" widget=\"many2many_tags\" domain=\"[(''type_tax_use'', ''='', ''purchase''), (''company_id'', ''parent_of'', parent.company_id), (''country_id'', ''='', parent.tax_country_id)]\" options=\"{''no_create'': True}\"/>\n                                            </group>\n                                            <group>\n                                                <field name=\"date_planned\" widget=\"date\" required=\"not display_type\"/>\n                                                <field name=\"analytic_distribution\" widget=\"analytic_distribution\" groups=\"analytic.group_analytic_accounting\" options=\"{''product_field'': ''product_id'', ''business_domain'': ''purchase_order''}\"/>\n                                            </group>\n                                            <group>\n                                            <notebook colspan=\"4\">\n                                                <page string=\"Notes\" name=\"notes\">\n                                                    <field name=\"name\"/>\n                                                </page>\n                                                <page string=\"Invoices and Incoming Shipments\" name=\"invoices_incoming_shiptments\">\n                                                    <field name=\"invoice_lines\"/>\n                                                </page>\n                                            </notebook>\n                                            </group>\n                                        </group>\n                                        <label for=\"name\" string=\"Section Name (eg. Products, Services)\" invisible=\"display_type != ''line_section''\"/>\n                                        <label for=\"name\" string=\"Note\" invisible=\"display_type != ''line_note''\"/>\n                                        <field name=\"name\" nolabel=\"1\" invisible=\"not display_type\"/>\n                                </form>\n                                <kanban class=\"o_kanban_mobile\">\n                                     <field name=\"name\"/>\n                                     <field name=\"product_id\"/>\n                                     <field name=\"product_qty\"/>\n                                     <field name=\"product_uom\" groups=\"uom.group_uom\"/>\n                                     <field name=\"price_subtotal\"/>\n                                     <field name=\"price_tax\"/>\n                                     <field name=\"price_total\"/>\n                                     <field name=\"price_unit\"/>\n                                     <field name=\"discount\"/>\n                                     <field name=\"display_type\"/>\n                                     <field name=\"taxes_id\"/>\n                                     <field name=\"tax_calculation_rounding_method\"/>\n                                     <templates>\n                                         <t t-name=\"kanban-box\">\n                                             <div t-attf-class=\"oe_kanban_card oe_kanban_global_click {{ record.display_type.raw_value ? ''o_is_'' + record.display_type.raw_value : '''' }}\">\n                                                 <t t-if=\"!record.display_type.raw_value\">\n                                                     <div class=\"row\">\n                                                         <div class=\"col-8\">\n                                                             <strong>\n                                                                 <span t-esc=\"record.product_id.value\"/>\n                                                             </strong>\n                                                         </div>\n                                                         <div class=\"col-4\">\n                                                             <strong>\n                                                                 <span>\n                                                                     Tax excl.: <t t-esc=\"record.price_subtotal.value\" class=\"float-end text-end\"/>\n                                                                 </span>\n                                                             </strong>\n                                                         </div>\n                                                     </div>\n                                                     <div class=\"row\">\n                                                         <div class=\"col-8 text-muted\">\n                                                             <span>\n                                                                 Quantity:\n                                                                 <t t-esc=\"record.product_qty.value\"/>\n                                                                 <small> <t t-esc=\"record.product_uom.value\" groups=\"uom.group_uom\"/></small>\n                                                             </span>\n                                                         </div>\n                                                         <div class=\"col-4\" t-if=\"record.tax_calculation_rounding_method.raw_value === ''round_per_line''\">\n                                                             <strong>\n                                                                <span>\n                                                                    Tax incl.: <t t-esc=\"record.price_total.value\"/>\n                                                                </span>\n                                                             </strong>\n                                                         </div>\n                                                     </div>\n                                                     <div class=\"row\">\n                                                         <div class=\"col-12 text-muted\">\n                                                             <span>\n                                                                 Unit Price:\n                                                                 <field name=\"price_unit\"/>\n                                                             </span>\n                                                         </div>\n                                                     </div>\n                                                     <div class=\"row\" t-if=\"record.discount.raw_value\">\n                                                         <div class=\"col-12 text-muted\">\n                                                            <span>\n                                                                Discount: <t t-out=\"record.discount.value\"/>%\n                                                            </span>\n                                                         </div>\n                                                     </div>\n                                                 </t>\n                                                 <div t-elif=\"record.display_type.raw_value === ''line_section'' || record.display_type.raw_value === ''line_note''\" class=\"row\">\n                                                     <div class=\"col-12\">\n                                                         <span t-esc=\"record.name.value\"/>\n                                                     </div>\n                                                 </div>\n                                             </div>\n                                         </t>\n                                     </templates>\n                                 </kanban>\n                            </field>\n                            <group>\n                                <group>\n                                    <field colspan=\"2\" name=\"notes\" nolabel=\"1\" placeholder=\"Define your terms and conditions ...\"/>\n                                </group>\n                                <group class=\"oe_subtotal_footer\">\n                                    <field name=\"tax_totals\" widget=\"account-tax-totals-field\" nolabel=\"1\" colspan=\"2\" readonly=\"1\"/>\n                                </group>\n                            </group>\n                            <div class=\"clearfix\"/>\n                        </page>\n                        <page string=\"Other Information\" name=\"purchase_delivery_invoice\">\n                            <group>\n                                <group name=\"other_info\">\n                                    <field name=\"user_id\" domain=\"[(''share'', ''='', False)]\" widget=\"many2one_avatar_user\"/>\n                                    <field name=\"company_id\" groups=\"base.group_multi_company\" options=\"{''no_create'': True}\" readonly=\"state in [''cancel'', ''done'', ''purchase'']\"/>\n                                    <field name=\"origin\"/>\n                                </group>\n                                <group name=\"invoice_info\">\n                                    <field name=\"invoice_status\" invisible=\"state in (''draft'', ''sent'', ''to approve'', ''cancel'')\"/>\n                                    <field name=\"payment_term_id\" readonly=\"invoice_status == ''invoiced'' or state == ''done''\" options=\"{''no_create'': True}\"/>\n                                    <field name=\"fiscal_position_id\" options=\"{''no_create'': True}\" readonly=\"invoice_status == ''invoiced'' or state == ''done''\"/>\n                                </group>\n                            </group>\n                        </page>\n                    </notebook>\n                </sheet>\n                <div class=\"oe_chatter\">\n                    <field name=\"message_follower_ids\"/>\n                    <field name=\"activity_ids\"/>\n                    <field name=\"message_ids\"/>\n                </div>\n                </form>"}', '<?xml version="1.0"?>
<form string="Purchase Order" class="o_purchase_order">
                <header>
                    <button name="action_rfq_send" invisible="state != ''draft''" string="Send by Email" type="object" context="{''send_rfq'':True}" class="oe_highlight" data-hotkey="g"/>
                    <button name="print_quotation" string="Print RFQ" type="object" invisible="state != ''draft''" class="oe_highlight" groups="base.group_user" data-hotkey="k"/>
                    <button name="button_confirm" type="object" invisible="state != ''sent''" string="Confirm Order" context="{''validate_analytic'': True}" class="oe_highlight" id="bid_confirm" data-hotkey="q"/>
                    <button name="button_approve" type="object" invisible="state != ''to approve''" string="Approve Order" class="oe_highlight" groups="purchase.group_purchase_manager" data-hotkey="z"/>
                    <button name="action_create_invoice" string="Create Bill" type="object" class="oe_highlight" context="{''create_bill'':True}" invisible="state not in (''purchase'', ''done'') or invoice_status in (''no'', ''invoiced'')" data-hotkey="w"/>
                    <button name="action_rfq_send" invisible="state != ''sent''" string="Re-Send by Email" type="object" context="{''send_rfq'':True}" data-hotkey="g"/>
                    <button name="print_quotation" string="Print RFQ" type="object" invisible="state != ''sent''" groups="base.group_user" data-hotkey="k"/>
                    <button name="button_confirm" type="object" invisible="state != ''draft''" context="{''validate_analytic'': True}" string="Confirm Order" id="draft_confirm" data-hotkey="q"/>
                    <button name="action_rfq_send" invisible="state != ''purchase''" string="Send PO by Email" type="object" context="{''send_rfq'':False}" data-hotkey="g"/>
                    <button name="confirm_reminder_mail" string="Confirm Receipt Date" type="object" invisible="state not in (''purchase'', ''done'') or mail_reminder_confirmed or not date_planned" groups="base.group_no_one" data-hotkey="o"/>
                    <button name="action_create_invoice" string="Create Bill" type="object" context="{''create_bill'':True}" invisible="state not in (''purchase'', ''done'') or invoice_status not in (''no'', ''invoiced'') or not order_line" data-hotkey="w"/>
                    <button name="button_draft" invisible="state != ''cancel''" string="Set to Draft" type="object" data-hotkey="o"/>
                    <button name="button_cancel" invisible="state not in (''draft'', ''to approve'', ''sent'', ''purchase'')" string="Cancel" type="object" data-hotkey="x"/>
                    <button name="button_done" type="object" string="Lock" invisible="state != ''purchase''" data-hotkey="l"/>
                    <button name="button_unlock" type="object" string="Unlock" invisible="state != ''done''" groups="purchase.group_purchase_manager" data-hotkey="l"/>
                    <field name="state" widget="statusbar" statusbar_visible="draft,sent,purchase" readonly="1"/>
                </header>
                <sheet>
                    <div class="oe_button_box" name="button_box">
                        <button type="object" name="action_view_invoice" class="oe_stat_button" icon="fa-pencil-square-o" invisible="invoice_count == 0 or state in (''draft'', ''sent'', ''to approve'')">
                            <field name="invoice_count" widget="statinfo" string="Vendor Bills"/>
                            <field name="invoice_ids" invisible="1"/>
                        </button>
                    </div>
                    <div class="oe_title">
                        <span class="o_form_label" invisible="state not in (''draft'', ''sent'')">Request for Quotation </span>
                        <span class="o_form_label" invisible="state in (''draft'', ''sent'')">Purchase Order </span>
                        <h1 class="d-flex">
                            <field name="priority" widget="priority" class="me-3"/>
                            <field name="name" readonly="1"/>
                        </h1>
                    </div>
                    <group>
                        <group>
                            <field name="partner_id" widget="res_partner_many2one" context="{''res_partner_search_mode'': ''supplier'', ''show_vat'': True}" placeholder="Name, TIN, Email, or Reference" readonly="state in [''cancel'', ''done'', ''purchase'']"/>
                            <field name="partner_ref"/>
                            <field name="currency_id" groups="base.group_multi_currency" force_save="1" readonly="state in [''cancel'', ''done'', ''purchase'']"/>
                            <field name="id" invisible="1"/>
                            <field name="company_id" invisible="1" readonly="state in [''cancel'', ''done'', ''purchase'']"/>
                            <field name="currency_id" invisible="1" readonly="state in [''cancel'', ''done'', ''purchase'']" groups="!base.group_multi_currency"/>
                            <field name="tax_calculation_rounding_method" invisible="1"/>
                        </group>
                        <group>
                            <field name="date_order" invisible="state in (''purchase'', ''done'')" readonly="state in [''cancel'', ''done'', ''purchase'']"/>
                            <label for="date_approve" invisible="state not in (''purchase'', ''done'')"/>
                            <div name="date_approve" invisible="state not in (''purchase'', ''done'')" class="o_row">
                                <field name="date_approve"/>
                                <field name="mail_reception_confirmed" invisible="1"/>
                                <span class="text-muted" invisible="not mail_reception_confirmed">(confirmed by vendor)</span>
                            </div>
                            <label for="date_planned"/>
                            <div name="date_planned_div" class="o_row">
                                <field name="date_planned" readonly="state not in (''draft'', ''sent'', ''to approve'', ''purchase'')"/>
                                <field name="mail_reminder_confirmed" invisible="1"/>
                                <span class="text-muted" invisible="not mail_reminder_confirmed">(confirmed by vendor)</span>
                            </div>
                            <label for="receipt_reminder_email" class="d-none" groups="purchase.group_send_reminder"/>
                            <div name="reminder" class="o_row" groups="purchase.group_send_reminder" title="Automatically send a confirmation email to the vendor X days before the expected receipt date, asking him to confirm the exact date.">
                                <field name="receipt_reminder_email"/>
                                <span>Ask confirmation</span>
                                <div class="o_row oe_inline" invisible="not receipt_reminder_email">
                                    <field name="reminder_date_before_receipt"/>
                                    day(s) before
                                    <widget name="toaster_button" button_name="send_reminder_preview" title="Preview the reminder email by sending it to yourself." invisible="not id"/>
                                </div>
                            </div>
                        </group>
                    </group>
                    <notebook>
                        <page string="Products" name="products">
                            <field name="tax_country_id" invisible="1"/>
                            <field name="order_line" widget="section_and_note_one2many" mode="tree,kanban" context="{''default_state'': ''draft''}" readonly="state in (''done'', ''cancel'')">
                                <tree string="Purchase Order Lines" editable="bottom">
                                    <control>
                                        <create name="add_product_control" string="Add a product"/>
                                        <create name="add_section_control" string="Add a section" context="{''default_display_type'': ''line_section''}"/>
                                        <create name="add_note_control" string="Add a note" context="{''default_display_type'': ''line_note''}"/>
                                        <button name="action_add_from_catalog" string="Catalog" type="object" class="px-4 btn-link" context="{''order_id'': parent.id}"/>
                                    </control>
                                    <field name="tax_calculation_rounding_method" column_invisible="True"/>
                                    <field name="display_type" column_invisible="True"/>
                                    <field name="company_id" column_invisible="True"/>
                                    <field name="currency_id" column_invisible="True"/>
                                    <field name="state" column_invisible="True"/>
                                    <field name="product_type" column_invisible="True"/>
                                    <field name="product_uom" column_invisible="True" groups="!uom.group_uom"/>
                                    <field name="product_uom_category_id" column_invisible="True"/>
                                    <field name="invoice_lines" column_invisible="True"/>
                                    <field name="sequence" widget="handle"/>
                                    <field name="product_id" readonly="state in (''purchase'', ''to approve'', ''done'', ''cancel'')" required="not display_type" width="35%" context="{''partner_id'': parent.partner_id, ''quantity'': product_qty, ''company_id'': parent.company_id, ''use_partner_name'': False}" force_save="1" domain="[(''purchase_ok'', ''='', True), ''|'', (''company_id'', ''='', False), (''company_id'', ''parent_of'', parent.company_id)]"/>
                                    <field name="name" widget="section_and_note_text"/>
                                    <field name="date_planned" optional="hide" required="not display_type" force_save="1"/>
                                    <field name="analytic_distribution" widget="analytic_distribution" optional="hide" groups="analytic.group_analytic_accounting" options="{''product_field'': ''product_id'', ''business_domain'': ''purchase_order'', ''amount_field'': ''price_subtotal''}"/>
                                    <field name="product_qty"/>
                                    <field name="qty_received_manual" column_invisible="True"/>
                                    <field name="qty_received_method" column_invisible="True"/>
                                    <field name="qty_received" string="Received" column_invisible="parent.state not in (''purchase'', ''done'')" readonly="qty_received_method != ''manual''" optional="show"/>
                                    <field name="qty_invoiced" string="Billed" column_invisible="parent.state not in (''purchase'', ''done'')" optional="show"/>
                                    <field name="product_uom" string="UoM" groups="uom.group_uom" readonly="state in (''purchase'', ''done'', ''cancel'')" required="not display_type" options="{''no_open'': True}" force_save="1" optional="show"/>
                                    <field name="product_packaging_qty" invisible="not product_id or not product_packaging_id" groups="product.group_stock_packaging" optional="show"/>
                                    <field name="product_packaging_id" invisible="not product_id" context="{''default_product_id'': product_id, ''tree_view_ref'':''product.product_packaging_tree_view'', ''form_view_ref'':''product.product_packaging_form_view''}" groups="product.group_stock_packaging" optional="show"/>
                                    <field name="price_unit" readonly="qty_invoiced != 0"/>
                                    <button name="action_purchase_history" type="object" icon="fa-history" title="Purchase History" invisible="not id"/>
                                    <field name="taxes_id" widget="many2many_tags" domain="[(''type_tax_use'', ''='', ''purchase''), (''company_id'', ''parent_of'', parent.company_id), (''country_id'', ''='', parent.tax_country_id), (''active'', ''='', True)]" context="{''default_type_tax_use'': ''purchase'', ''search_view_ref'': ''account.account_tax_view_search''}" options="{''no_create'': True}" optional="show"/>
                                    <field name="discount" string="Disc.%" readonly="qty_invoiced != 0" optional="hide"/>
                                    <field name="price_subtotal" string="Tax excl."/>
                                    <field name="price_total" string="Tax incl." column_invisible="parent.tax_calculation_rounding_method == ''round_globally''" optional="hide"/>
                                </tree>
                                <form string="Purchase Order Line">
                                        <field name="tax_calculation_rounding_method" invisible="1"/>
                                        <field name="state" invisible="1"/>
                                        <field name="display_type" invisible="1"/>
                                        <field name="company_id" invisible="1"/>
                                        <group invisible="display_type">
                                            <group>
                                                <field name="product_uom_category_id" invisible="1"/>
                                                <field name="product_id" context="{''partner_id'': parent.partner_id}" widget="many2one_barcode" domain="[(''purchase_ok'', ''='', True), ''|'', (''company_id'', ''='', False), (''company_id'', ''='', parent.company_id)]" readonly="state in (''purchase'', ''to approve'', ''done'', ''cancel'')"/>
                                                <label for="product_qty"/>
                                                <div class="o_row">
                                                    <field name="product_qty"/>
                                                    <field name="product_uom" groups="uom.group_uom" required="not display_type"/>
                                                </div>
                                                <field name="qty_received_method" invisible="1"/>
                                                <field name="qty_received" string="Received Quantity" invisible="parent.state not in (''purchase'', ''done'')" readonly="qty_received_method != ''manual''"/>
                                                <field name="qty_invoiced" string="Billed Quantity" invisible="parent.state not in (''purchase'', ''done'')"/>
                                                <field name="product_packaging_qty" invisible="not product_id or not product_packaging_id" groups="product.group_stock_packaging"/>
                                                <field name="product_packaging_id" invisible="not product_id" context="{''default_product_id'': product_id, ''tree_view_ref'':''product.product_packaging_tree_view'', ''form_view_ref'':''product.product_packaging_form_view''}" groups="product.group_stock_packaging"/>
                                                <field name="price_unit"/>
                                                <field name="discount"/>
                                                <field name="taxes_id" widget="many2many_tags" domain="[(''type_tax_use'', ''='', ''purchase''), (''company_id'', ''parent_of'', parent.company_id), (''country_id'', ''='', parent.tax_country_id)]" options="{''no_create'': True}"/>
                                            </group>
                                            <group>
                                                <field name="date_planned" widget="date" required="not display_type"/>
                                                <field name="analytic_distribution" widget="analytic_distribution" groups="analytic.group_analytic_accounting" options="{''product_field'': ''product_id'', ''business_domain'': ''purchase_order''}"/>
                                            </group>
                                            <group>
                                            <notebook colspan="4">
                                                <page string="Notes" name="notes">
                                                    <field name="name"/>
                                                </page>
                                                <page string="Invoices and Incoming Shipments" name="invoices_incoming_shiptments">
                                                    <field name="invoice_lines"/>
                                                </page>
                                            </notebook>
                                            </group>
                                        </group>
                                        <label for="name" string="Section Name (eg. Products, Services)" invisible="display_type != ''line_section''"/>
                                        <label for="name" string="Note" invisible="display_type != ''line_note''"/>
                                        <field name="name" nolabel="1" invisible="not display_type"/>
                                </form>
                                <kanban class="o_kanban_mobile">
                                     <field name="name"/>
                                     <field name="product_id"/>
                                     <field name="product_qty"/>
                                     <field name="product_uom" groups="uom.group_uom"/>
                                     <field name="price_subtotal"/>
                                     <field name="price_tax"/>
                                     <field name="price_total"/>
                                     <field name="price_unit"/>
                                     <field name="discount"/>
                                     <field name="display_type"/>
                                     <field name="taxes_id"/>
                                     <field name="tax_calculation_rounding_method"/>
                                     <templates>
                                         <t t-name="kanban-box">
                                             <div t-attf-class="oe_kanban_card oe_kanban_global_click {{ record.display_type.raw_value ? ''o_is_'' + record.display_type.raw_value : '''' }}">
                                                 <t t-if="!record.display_type.raw_value">
                                                     <div class="row">
                                                         <div class="col-8">
                                                             <strong>
                                                                 <span t-esc="record.product_id.value"/>
                                                             </strong>
                                                         </div>
                                                         <div class="col-4">
                                                             <strong>
                                                                 <span>
                                                                     Tax excl.: <t t-esc="record.price_subtotal.value" class="float-end text-end"/>
                                                                 </span>
                                                             </strong>
                                                         </div>
                                                     </div>
                                                     <div class="row">
                                                         <div class="col-8 text-muted">
                                                             <span>
                                                                 Quantity:
                                                                 <t t-esc="record.product_qty.value"/>
                                                                 <small> <t t-esc="record.product_uom.value" groups="uom.group_uom"/></small>
                                                             </span>
                                                         </div>
                                                         <div class="col-4" t-if="record.tax_calculation_rounding_method.raw_value === ''round_per_line''">
                                                             <strong>
                                                                <span>
                                                                    Tax incl.: <t t-esc="record.price_total.value"/>
                                                                </span>
                                                             </strong>
                                                         </div>
                                                     </div>
                                                     <div class="row">
                                                         <div class="col-12 text-muted">
                                                             <span>
                                                                 Unit Price:
                                                                 <field name="price_unit"/>
                                                             </span>
                                                         </div>
                                                     </div>
                                                     <div class="row" t-if="record.discount.raw_value">
                                                         <div class="col-12 text-muted">
                                                            <span>
                                                                Discount: <t t-out="record.discount.value"/>%
                                                            </span>
                                                         </div>
                                                     </div>
                                                 </t>
                                                 <div t-elif="record.display_type.raw_value === ''line_section'' || record.display_type.raw_value === ''line_note''" class="row">
                                                     <div class="col-12">
                                                         <span t-esc="record.name.value"/>
                                                     </div>
                                                 </div>
                                             </div>
                                         </t>
                                     </templates>
                                 </kanban>
                            </field>
                            <group>
                                <group>
                                    <field colspan="2" name="notes" nolabel="1" placeholder="Define your terms and conditions ..."/>
                                </group>
                                <group class="oe_subtotal_footer">
                                    <field name="tax_totals" widget="account-tax-totals-field" nolabel="1" colspan="2" readonly="1"/>
                                </group>
                            </group>
                            <div class="clearfix"/>
                        </page>
                        <page string="Other Information" name="purchase_delivery_invoice">
                            <group>
                                <group name="other_info">
                                    <field name="user_id" domain="[(''share'', ''='', False)]" widget="many2one_avatar_user"/>
                                    <field name="company_id" groups="base.group_multi_company" options="{''no_create'': True}" readonly="state in [''cancel'', ''done'', ''purchase'']"/>
                                    <field name="origin"/>
                                </group>
                                <group name="invoice_info">
                                    <field name="invoice_status" invisible="state in (''draft'', ''sent'', ''to approve'', ''cancel'')"/>
                                    <field name="payment_term_id" readonly="invoice_status == ''invoiced'' or state == ''done''" options="{''no_create'': True}"/>
                                    <field name="fiscal_position_id" options="{''no_create'': True}" readonly="invoice_status == ''invoiced'' or state == ''done''"/>
                                </group>
                            </group>
                        </page>
                    </notebook>
                </sheet>
                <div class="oe_chatter">
                    <field name="message_follower_ids"/>
                    <field name="activity_ids"/>
                    <field name="message_ids"/>
                </div>
                </form>
            ', false, true, '2026-05-10 01:12:29.662147', '2026-05-10 01:12:29.662147', false);
INSERT INTO public.ir_ui_view VALUES (1162, 16, NULL, 1, 1, 'request.quotation.select', 'purchase.order', NULL, 'search', 'purchase/views/purchase_views.xml', 'primary', '{"en_US": "<search string=\"Search Purchase Order\">\n                    <field name=\"name\" string=\"Order\" filter_domain=\"[''|'', ''|'', (''name'', ''ilike'', self), (''partner_ref'', ''ilike'', self), (''partner_id'', ''child_of'', self)]\"/>\n                    <field name=\"partner_id\" operator=\"child_of\"/>\n                    <field name=\"user_id\"/>\n                    <field name=\"product_id\"/>\n                    <field name=\"origin\"/>\n                    <filter name=\"my_purchases\" string=\"My Purchases\" domain=\"[(''user_id'', ''='', uid)]\"/>\n                    <filter string=\"Starred\" name=\"starred\" domain=\"[(''priority'', ''='', ''1'')]\"/>\n                    <separator/>\n                    <filter name=\"draft\" string=\"RFQs\" domain=\"[(''state'', ''in'', (''draft'', ''sent'', ''to approve''))]\"/>\n                    <separator/>\n                    <filter name=\"approved\" string=\"Purchase Orders\" domain=\"[(''state'', ''in'', (''purchase'', ''done''))]\"/>\n                    <filter name=\"to_approve\" string=\"To Approve\" domain=\"[(''state'', ''='', ''to approve'')]\"/>\n                    <separator/>\n                    <filter name=\"order_date\" string=\"Order Date\" date=\"date_order\"/>\n                    <filter name=\"draft_rfqs\" string=\"Draft RFQs\" domain=\"[(''state'', ''='', ''draft'')]\"/>\n                    <filter name=\"waiting_rfqs\" string=\"Waiting RFQs\" domain=\"[(''state'', ''='', ''sent''), (''date_order'', ''&gt;='', datetime.datetime.now())]\"/>\n                    <filter name=\"late_rfqs\" string=\"Late RFQs\" domain=\"[(''state'', ''in'', [''draft'', ''sent'', ''to approve'']),(''date_order'', ''&lt;'', datetime.datetime.now())]\"/>\n                    <separator/>\n                    <filter invisible=\"1\" string=\"Late Activities\" name=\"activities_overdue\" domain=\"[(''my_activity_date_deadline'', ''&lt;'', context_today().strftime(''%Y-%m-%d''))]\" help=\"Show all records which has next action date is before today\"/>\n                    <filter invisible=\"1\" string=\"Today Activities\" name=\"activities_today\" domain=\"[(''my_activity_date_deadline'', ''='', context_today().strftime(''%Y-%m-%d''))]\"/>\n                    <filter invisible=\"1\" string=\"Future Activities\" name=\"activities_upcoming_all\" domain=\"[(''my_activity_date_deadline'', ''&gt;'', context_today().strftime(''%Y-%m-%d''))]\"/>\n                    <separator/>\n                    <filter string=\"Warnings\" name=\"activities_exception\" domain=\"[(''activity_exception_decoration'', ''!='', False)]\"/>\n                    <group expand=\"0\" string=\"Group By\">\n                        <filter string=\"Vendor\" name=\"vendor\" domain=\"[]\" context=\"{''group_by'': ''partner_id''}\"/>\n                        <filter string=\"Buyer\" name=\"representative\" domain=\"[]\" context=\"{''group_by'': ''user_id''}\"/>\n                        <filter string=\"Order Date\" name=\"order_date\" domain=\"[]\" context=\"{''group_by'': ''date_order''}\"/>\n                    </group>\n                </search>"}', '<?xml version="1.0"?>
<search string="Search Purchase Order">
                    <field name="name" string="Order" filter_domain="[''|'', ''|'', (''name'', ''ilike'', self), (''partner_ref'', ''ilike'', self), (''partner_id'', ''child_of'', self)]"/>
                    <field name="partner_id" operator="child_of"/>
                    <field name="user_id"/>
                    <field name="product_id"/>
                    <field name="origin"/>
                    <filter name="my_purchases" string="My Purchases" domain="[(''user_id'', ''='', uid)]"/>
                    <filter string="Starred" name="starred" domain="[(''priority'', ''='', ''1'')]"/>
                    <separator/>
                    <filter name="draft" string="RFQs" domain="[(''state'', ''in'', (''draft'', ''sent'', ''to approve''))]"/>
                    <separator/>
                    <filter name="approved" string="Purchase Orders" domain="[(''state'', ''in'', (''purchase'', ''done''))]"/>
                    <filter name="to_approve" string="To Approve" domain="[(''state'', ''='', ''to approve'')]"/>
                    <separator/>
                    <filter name="order_date" string="Order Date" date="date_order"/>
                    <filter name="draft_rfqs" string="Draft RFQs" domain="[(''state'', ''='', ''draft'')]"/>
                    <filter name="waiting_rfqs" string="Waiting RFQs" domain="[(''state'', ''='', ''sent''), (''date_order'', ''&gt;='', datetime.datetime.now())]"/>
                    <filter name="late_rfqs" string="Late RFQs" domain="[(''state'', ''in'', [''draft'', ''sent'', ''to approve'']),(''date_order'', ''&lt;'', datetime.datetime.now())]"/>
                    <separator/>
                    <filter invisible="1" string="Late Activities" name="activities_overdue" domain="[(''my_activity_date_deadline'', ''&lt;'', context_today().strftime(''%Y-%m-%d''))]" help="Show all records which has next action date is before today"/>
                    <filter invisible="1" string="Today Activities" name="activities_today" domain="[(''my_activity_date_deadline'', ''='', context_today().strftime(''%Y-%m-%d''))]"/>
                    <filter invisible="1" string="Future Activities" name="activities_upcoming_all" domain="[(''my_activity_date_deadline'', ''&gt;'', context_today().strftime(''%Y-%m-%d''))]"/>
                    <separator/>
                    <filter string="Warnings" name="activities_exception" domain="[(''activity_exception_decoration'', ''!='', False)]"/>
                    <group expand="0" string="Group By">
                        <filter string="Vendor" name="vendor" domain="[]" context="{''group_by'': ''partner_id''}"/>
                        <filter string="Buyer" name="representative" domain="[]" context="{''group_by'': ''user_id''}"/>
                        <filter string="Order Date" name="order_date" domain="[]" context="{''group_by'': ''date_order''}"/>
                    </group>
                </search>
            ', false, true, '2026-05-10 01:12:29.662147', '2026-05-10 01:12:29.662147', false);
INSERT INTO public.ir_ui_view VALUES (1163, 16, NULL, 1, 1, 'purchase.order.select', 'purchase.order', NULL, 'search', 'purchase/views/purchase_views.xml', 'primary', '{"en_US": "<search string=\"Search Purchase Order\">\n                    <field name=\"name\" string=\"Order\" filter_domain=\"[''|'', ''|'', (''name'', ''ilike'', self), (''partner_ref'', ''ilike'', self), (''partner_id'', ''child_of'', self)]\"/>\n                    <field name=\"partner_id\" operator=\"child_of\"/>\n                    <field name=\"user_id\"/>\n                    <field name=\"product_id\"/>\n                    <filter name=\"my_Orders\" string=\"My Orders\" domain=\"[(''user_id'', ''='', uid)]\"/>\n                    <filter string=\"Starred\" name=\"starred\" domain=\"[(''priority'', ''='', ''1'')]\"/>\n                    <separator/>\n                    <filter name=\"unconfirmed\" string=\"Not Acknowledged\" domain=\"[(''mail_reception_confirmed'', ''='', False), (''state'', ''='', ''purchase'')]\"/>\n                    <filter name=\"not_invoiced\" string=\"Waiting Bills\" domain=\"[(''invoice_status'', ''='', ''to invoice'')]\" help=\"Purchase orders that include lines not invoiced.\"/>\n                    <filter name=\"invoiced\" string=\"Bills Received\" domain=\"[(''invoice_status'', ''='', ''invoiced'')]\" help=\"Purchase orders that have been invoiced.\"/>\n                    <separator/>\n                    <filter name=\"order_date\" string=\"Order Date\" date=\"date_order\"/>\n                    <separator/>\n                    <filter invisible=\"1\" string=\"Late Activities\" name=\"activities_overdue\" domain=\"[(''my_activity_date_deadline'', ''&lt;'', context_today().strftime(''%Y-%m-%d''))]\" help=\"Show all records which has next action date is before today\"/>\n                    <filter invisible=\"1\" string=\"Today Activities\" name=\"activities_today\" domain=\"[(''my_activity_date_deadline'', ''='', context_today().strftime(''%Y-%m-%d''))]\"/>\n                    <filter invisible=\"1\" string=\"Future Activities\" name=\"activities_upcoming_all\" domain=\"[(''my_activity_date_deadline'', ''&gt;'', context_today().strftime(''%Y-%m-%d''))]\"/>\n                    <separator/>\n                    <filter string=\"Warnings\" name=\"activities_exception\" domain=\"[(''activity_exception_decoration'', ''!='', False)]\"/>\n                    <group expand=\"0\" string=\"Group By\">\n                        <filter string=\"Vendor\" name=\"vendor\" domain=\"[]\" context=\"{''group_by'': ''partner_id''}\"/>\n                        <filter string=\"Buyer\" name=\"representative\" domain=\"[]\" context=\"{''group_by'': ''user_id''}\"/>\n                        <filter string=\"Order Date\" name=\"order_date\" domain=\"[]\" context=\"{''group_by'': ''date_order''}\"/>\n                    </group>\n                </search>"}', '<?xml version="1.0"?>
<search string="Search Purchase Order">
                    <field name="name" string="Order" filter_domain="[''|'', ''|'', (''name'', ''ilike'', self), (''partner_ref'', ''ilike'', self), (''partner_id'', ''child_of'', self)]"/>
                    <field name="partner_id" operator="child_of"/>
                    <field name="user_id"/>
                    <field name="product_id"/>
                    <filter name="my_Orders" string="My Orders" domain="[(''user_id'', ''='', uid)]"/>
                    <filter string="Starred" name="starred" domain="[(''priority'', ''='', ''1'')]"/>
                    <separator/>
                    <filter name="unconfirmed" string="Not Acknowledged" domain="[(''mail_reception_confirmed'', ''='', False), (''state'', ''='', ''purchase'')]"/>
                    <filter name="not_invoiced" string="Waiting Bills" domain="[(''invoice_status'', ''='', ''to invoice'')]" help="Purchase orders that include lines not invoiced."/>
                    <filter name="invoiced" string="Bills Received" domain="[(''invoice_status'', ''='', ''invoiced'')]" help="Purchase orders that have been invoiced."/>
                    <separator/>
                    <filter name="order_date" string="Order Date" date="date_order"/>
                    <separator/>
                    <filter invisible="1" string="Late Activities" name="activities_overdue" domain="[(''my_activity_date_deadline'', ''&lt;'', context_today().strftime(''%Y-%m-%d''))]" help="Show all records which has next action date is before today"/>
                    <filter invisible="1" string="Today Activities" name="activities_today" domain="[(''my_activity_date_deadline'', ''='', context_today().strftime(''%Y-%m-%d''))]"/>
                    <filter invisible="1" string="Future Activities" name="activities_upcoming_all" domain="[(''my_activity_date_deadline'', ''&gt;'', context_today().strftime(''%Y-%m-%d''))]"/>
                    <separator/>
                    <filter string="Warnings" name="activities_exception" domain="[(''activity_exception_decoration'', ''!='', False)]"/>
                    <group expand="0" string="Group By">
                        <filter string="Vendor" name="vendor" domain="[]" context="{''group_by'': ''partner_id''}"/>
                        <filter string="Buyer" name="representative" domain="[]" context="{''group_by'': ''user_id''}"/>
                        <filter string="Order Date" name="order_date" domain="[]" context="{''group_by'': ''date_order''}"/>
                    </group>
                </search>
            ', false, true, '2026-05-10 01:12:29.662147', '2026-05-10 01:12:29.662147', false);
INSERT INTO public.ir_ui_view VALUES (1164, 16, NULL, 1, 1, 'purchase.order.kanban', 'purchase.order', NULL, 'kanban', 'purchase/views/purchase_views.xml', 'primary', '{"en_US": "<kanban class=\"o_kanban_mobile\" js_class=\"purchase_dashboard_kanban\" sample=\"1\" quick_create=\"false\">\n                    <field name=\"name\"/>\n                    <field name=\"partner_id\" readonly=\"1\"/>\n                    <field name=\"amount_total\"/>\n                    <field name=\"state\"/>\n                    <field name=\"date_order\"/>\n                    <field name=\"currency_id\" readonly=\"1\"/>\n                    <field name=\"activity_state\"/>\n                    <progressbar field=\"activity_state\" colors=\"{&quot;planned&quot;: &quot;success&quot;, &quot;today&quot;: &quot;warning&quot;, &quot;overdue&quot;: &quot;danger&quot;}\"/>\n                    <templates>\n                        <t t-name=\"kanban-box\">\n                            <div t-attf-class=\"oe_kanban_card oe_kanban_global_click\">\n                                <div class=\"o_kanban_record_top mb16\">\n                                    <field name=\"priority\" widget=\"priority\"/>\n                                    <div class=\"o_kanban_record_headings ms-1\">\n                                        <strong class=\"o_kanban_record_title\"><span><t t-esc=\"record.partner_id.value\"/></span></strong>\n                                    </div>\n                                    <strong><field name=\"amount_total\" widget=\"monetary\"/></strong>\n                                </div>\n                                <div class=\"o_kanban_record_bottom\">\n                                    <div class=\"oe_kanban_bottom_left\">\n                                        <span><t t-esc=\"record.name.value\"/> <t t-esc=\"record.date_order.value and record.date_order.value.split('' '')[0] or False\"/></span>\n                                        <field name=\"activity_ids\" widget=\"kanban_activity\"/>\n                                    </div>\n                                    <div class=\"oe_kanban_bottom_right\">\n                                        <field name=\"state\" widget=\"label_selection\" options=\"{''classes'': {''draft'': ''default'', ''cancel'': ''default'', ''done'': ''success'', ''approved'': ''warning''}}\"/>\n                                    </div>\n                                </div>\n                            </div>\n                        </t>\n                    </templates>\n                </kanban>"}', '<?xml version="1.0"?>
<kanban class="o_kanban_mobile" js_class="purchase_dashboard_kanban" sample="1" quick_create="false">
                    <field name="name"/>
                    <field name="partner_id" readonly="1"/>
                    <field name="amount_total"/>
                    <field name="state"/>
                    <field name="date_order"/>
                    <field name="currency_id" readonly="1"/>
                    <field name="activity_state"/>
                    <progressbar field="activity_state" colors="{&quot;planned&quot;: &quot;success&quot;, &quot;today&quot;: &quot;warning&quot;, &quot;overdue&quot;: &quot;danger&quot;}"/>
                    <templates>
                        <t t-name="kanban-box">
                            <div t-attf-class="oe_kanban_card oe_kanban_global_click">
                                <div class="o_kanban_record_top mb16">
                                    <field name="priority" widget="priority"/>
                                    <div class="o_kanban_record_headings ms-1">
                                        <strong class="o_kanban_record_title"><span><t t-esc="record.partner_id.value"/></span></strong>
                                    </div>
                                    <strong><field name="amount_total" widget="monetary"/></strong>
                                </div>
                                <div class="o_kanban_record_bottom">
                                    <div class="oe_kanban_bottom_left">
                                        <span><t t-esc="record.name.value"/> <t t-esc="record.date_order.value and record.date_order.value.split('' '')[0] or False"/></span>
                                        <field name="activity_ids" widget="kanban_activity"/>
                                    </div>
                                    <div class="oe_kanban_bottom_right">
                                        <field name="state" widget="label_selection" options="{''classes'': {''draft'': ''default'', ''cancel'': ''default'', ''done'': ''success'', ''approved'': ''warning''}}"/>
                                    </div>
                                </div>
                            </div>
                        </t>
                    </templates>
                </kanban>
            ', false, true, '2026-05-10 01:12:29.662147', '2026-05-10 01:12:29.662147', false);
INSERT INTO public.ir_ui_view VALUES (1165, 20, 1164, 1, 1, 'purchase.order.view.kanban.without.dashboard', 'purchase.order', NULL, 'kanban', 'purchase/views/purchase_views.xml', 'primary', '{"en_US": "<xpath expr=\"//kanban\" position=\"attributes\">\n                    <attribute name=\"js_class\"/>\n                </xpath>"}', '<?xml version="1.0"?>
<xpath expr="//kanban" position="attributes">
                    <attribute name="js_class"/>
                </xpath>
            ', false, true, '2026-05-10 01:12:29.662147', '2026-05-10 01:12:29.662147', false);
INSERT INTO public.ir_ui_view VALUES (1166, 1, NULL, 1, 1, 'purchase.order.tree', 'purchase.order', NULL, 'tree', 'purchase/views/purchase_views.xml', 'primary', '{"en_US": "<tree string=\"Purchase Order\" decoration-muted=\"state==''cancel''\" sample=\"1\">\n                    <field name=\"priority\" optional=\"show\" widget=\"priority\" nolabel=\"1\"/>\n                    <field name=\"partner_ref\" optional=\"hide\"/>\n                    <field name=\"name\" string=\"Reference\" readonly=\"1\" decoration-info=\"state in (''draft'',''sent'')\"/>\n                    <field name=\"date_order\" column_invisible=\"not context.get(''quotation_only'', False)\" readonly=\"state in [''cancel'', ''done'', ''purchase'']\" optional=\"show\"/>\n                    <field name=\"date_approve\" column_invisible=\"context.get(''quotation_only'', False)\" optional=\"show\"/>\n                    <field name=\"partner_id\" readonly=\"1\"/>\n                    <field name=\"company_id\" readonly=\"1\" options=\"{''no_create'': True}\" groups=\"base.group_multi_company\" optional=\"show\"/>\n                    <field name=\"user_id\" optional=\"show\"/>\n                    <field name=\"origin\" optional=\"show\"/>\n                    <field name=\"amount_untaxed\" sum=\"Total Untaxed amount\" string=\"Untaxed\" widget=\"monetary\" optional=\"hide\"/>\n                    <field name=\"amount_total\" sum=\"Total amount\" widget=\"monetary\" optional=\"show\"/>\n                    <field name=\"currency_id\" column_invisible=\"True\" readonly=\"state in [''cancel'', ''done'', ''purchase'']\"/>\n                    <field name=\"state\" optional=\"show\"/>\n                    <field name=\"date_planned\" column_invisible=\"context.get(''quotation_only'', False)\" optional=\"show\"/>\n                    <field name=\"invoice_status\" column_invisible=\"context.get(''quotation_only'', False)\" optional=\"hide\"/>\n                    <field name=\"activity_exception_decoration\" widget=\"activity_exception\"/>\n                </tree>"}', '<?xml version="1.0"?>
<tree string="Purchase Order" decoration-muted="state==''cancel''" sample="1">
                    <field name="priority" optional="show" widget="priority" nolabel="1"/>
                    <field name="partner_ref" optional="hide"/>
                    <field name="name" string="Reference" readonly="1" decoration-info="state in (''draft'',''sent'')"/>
                    <field name="date_order" column_invisible="not context.get(''quotation_only'', False)" readonly="state in [''cancel'', ''done'', ''purchase'']" optional="show"/>
                    <field name="date_approve" column_invisible="context.get(''quotation_only'', False)" optional="show"/>
                    <field name="partner_id" readonly="1"/>
                    <field name="company_id" readonly="1" options="{''no_create'': True}" groups="base.group_multi_company" optional="show"/>
                    <field name="user_id" optional="show"/>
                    <field name="origin" optional="show"/>
                    <field name="amount_untaxed" sum="Total Untaxed amount" string="Untaxed" widget="monetary" optional="hide"/>
                    <field name="amount_total" sum="Total amount" widget="monetary" optional="show"/>
                    <field name="currency_id" column_invisible="True" readonly="state in [''cancel'', ''done'', ''purchase'']"/>
                    <field name="state" optional="show"/>
                    <field name="date_planned" column_invisible="context.get(''quotation_only'', False)" optional="show"/>
                    <field name="invoice_status" column_invisible="context.get(''quotation_only'', False)" optional="hide"/>
                    <field name="activity_exception_decoration" widget="activity_exception"/>
                </tree>
            ', false, true, '2026-05-10 01:12:29.662147', '2026-05-10 01:12:29.662147', false);
INSERT INTO public.ir_ui_view VALUES (1167, 10, NULL, 1, 1, 'purchase.order.inherit.purchase.order.tree', 'purchase.order', NULL, 'tree', 'purchase/views/purchase_views.xml', 'primary', '{"en_US": "<tree string=\"Purchase Order\" decoration-info=\"state in [''draft'', ''sent'']\" decoration-muted=\"state == ''cancel''\" class=\"o_purchase_order\" js_class=\"purchase_dashboard_list\" sample=\"1\">\n                    <header>\n                        <button name=\"action_create_invoice\" type=\"object\" string=\"Create Bills\"/>\n                    </header>\n                    <field name=\"priority\" optional=\"show\" widget=\"priority\" nolabel=\"1\"/>\n                    <field name=\"partner_ref\" optional=\"hide\"/>\n                    <field name=\"name\" string=\"Reference\" readonly=\"1\" decoration-bf=\"1\"/>\n                    <field name=\"date_approve\" column_invisible=\"context.get(''quotation_only'', False)\" optional=\"show\"/>\n                    <field name=\"partner_id\" readonly=\"1\"/>\n                    <field name=\"company_id\" readonly=\"1\" options=\"{''no_create'': True}\" groups=\"base.group_multi_company\" optional=\"show\"/>\n                    <field name=\"company_id\" groups=\"!base.group_multi_company\" column_invisible=\"True\" readonly=\"state in [''cancel'', ''done'', ''purchase'']\"/>\n                    <field name=\"date_planned\" column_invisible=\"context.get(''quotation_only'', False)\" optional=\"show\"/>\n                    <field name=\"user_id\" optional=\"show\" widget=\"many2one_avatar_user\"/>\n                    <field name=\"date_order\" invisible=\"state == ''purchase'' or state == ''done'' or state == ''cancel''\" column_invisible=\"not context.get(''quotation_only'', False)\" readonly=\"state in [''cancel'', ''done'', ''purchase'']\" widget=\"remaining_days\" optional=\"show\"/>\n                    <field name=\"activity_ids\" widget=\"list_activity\" optional=\"show\"/>\n                    <field name=\"origin\" optional=\"show\"/>\n                    <field name=\"amount_untaxed\" sum=\"Total Untaxed amount\" string=\"Untaxed\" widget=\"monetary\" optional=\"hide\"/>\n                    <field name=\"amount_total\" sum=\"Total amount\" widget=\"monetary\" optional=\"show\" decoration-bf=\"state in [''purchase'', ''done'']\"/>\n                    <field name=\"currency_id\" column_invisible=\"True\" readonly=\"state in [''cancel'', ''done'', ''purchase'']\"/>\n                    <field name=\"state\" optional=\"show\" widget=\"badge\" decoration-success=\"state == ''purchase'' or state == ''done''\" decoration-warning=\"state == ''to approve''\" decoration-info=\"state == ''draft'' or state == ''sent''\"/>\n                    <field name=\"invoice_status\" optional=\"hide\"/>\n                </tree>"}', '<?xml version="1.0"?>
<tree string="Purchase Order" decoration-info="state in [''draft'', ''sent'']" decoration-muted="state == ''cancel''" class="o_purchase_order" js_class="purchase_dashboard_list" sample="1">
                    <header>
                        <button name="action_create_invoice" type="object" string="Create Bills"/>
                    </header>
                    <field name="priority" optional="show" widget="priority" nolabel="1"/>
                    <field name="partner_ref" optional="hide"/>
                    <field name="name" string="Reference" readonly="1" decoration-bf="1"/>
                    <field name="date_approve" column_invisible="context.get(''quotation_only'', False)" optional="show"/>
                    <field name="partner_id" readonly="1"/>
                    <field name="company_id" readonly="1" options="{''no_create'': True}" groups="base.group_multi_company" optional="show"/>
                    <field name="company_id" groups="!base.group_multi_company" column_invisible="True" readonly="state in [''cancel'', ''done'', ''purchase'']"/>
                    <field name="date_planned" column_invisible="context.get(''quotation_only'', False)" optional="show"/>
                    <field name="user_id" optional="show" widget="many2one_avatar_user"/>
                    <field name="date_order" invisible="state == ''purchase'' or state == ''done'' or state == ''cancel''" column_invisible="not context.get(''quotation_only'', False)" readonly="state in [''cancel'', ''done'', ''purchase'']" widget="remaining_days" optional="show"/>
                    <field name="activity_ids" widget="list_activity" optional="show"/>
                    <field name="origin" optional="show"/>
                    <field name="amount_untaxed" sum="Total Untaxed amount" string="Untaxed" widget="monetary" optional="hide"/>
                    <field name="amount_total" sum="Total amount" widget="monetary" optional="show" decoration-bf="state in [''purchase'', ''done'']"/>
                    <field name="currency_id" column_invisible="True" readonly="state in [''cancel'', ''done'', ''purchase'']"/>
                    <field name="state" optional="show" widget="badge" decoration-success="state == ''purchase'' or state == ''done''" decoration-warning="state == ''to approve''" decoration-info="state == ''draft'' or state == ''sent''"/>
                    <field name="invoice_status" optional="hide"/>
                </tree>
            ', false, true, '2026-05-10 01:12:29.662147', '2026-05-10 01:12:29.662147', false);
INSERT INTO public.ir_ui_view VALUES (1173, 16, NULL, 1, 1, 'purchase.history.tree', 'purchase.order.line', NULL, 'tree', 'purchase/views/purchase_views.xml', 'primary', '{"en_US": "<tree create=\"false\" default_order=\"order_id asc\">\n                <field name=\"order_id\" widget=\"many2one\"/>\n                <field name=\"date_approve\" widget=\"date\"/>\n                <field name=\"partner_id\"/>\n                <field name=\"product_uom_qty\"/>\n                <field name=\"price_unit\"/>\n            </tree>"}', '<?xml version="1.0"?>
<tree create="false" default_order="order_id asc">
                <field name="order_id" widget="many2one"/>
                <field name="date_approve" widget="date"/>
                <field name="partner_id"/>
                <field name="product_uom_qty"/>
                <field name="price_unit"/>
            </tree>
        ', false, true, '2026-05-10 01:12:29.662147', '2026-05-10 01:12:29.662147', false);
INSERT INTO public.ir_ui_view VALUES (1174, 25, 176, 1, 1, 'res.config.settings.view.form.inherit.purchase', 'res.config.settings', NULL, 'form', 'purchase/views/res_config_settings_views.xml', 'extension', '{"en_US": "<xpath expr=\"//form\" position=\"inside\">\n                <app data-string=\"Purchase\" string=\"Purchase\" name=\"purchase\" groups=\"purchase.group_purchase_manager\">\n                    <field name=\"po_double_validation\" invisible=\"1\"/>\n                    <field name=\"company_currency_id\" invisible=\"1\"/>\n                    <field name=\"po_lock\" invisible=\"1\"/>\n                    <block title=\"Orders\" name=\"purchase_setting_container\">\n                        <setting id=\"po_order_approval\" company_dependent=\"1\" help=\"Request managers to approve orders above a minimum amount\">\n                            <field name=\"po_order_approval\"/>\n                            <div class=\"content-group\" invisible=\"not po_order_approval\">\n                                <div class=\"row mt16\">\n                                    <label for=\"po_double_validation_amount\" class=\"col-lg-4 o_light_label\"/>\n                                    <field name=\"po_double_validation_amount\"/>\n                                </div>\n                            </div>\n                        </setting>\n                        <setting id=\"automatic_lock_confirmed_orders\" help=\"Automatically lock confirmed orders to prevent editing\">\n                            <field name=\"lock_confirmed_po\"/>\n                        </setting>\n                        <setting id=\"get_order_warnings\" string=\"Warnings\" help=\"Get warnings in orders for products or vendors\">\n                            <field name=\"group_warning_purchase\"/>\n                        </setting>\n                        <setting id=\"manage_purchase_agreements\" title=\"Calls for tenders are when you want to generate requests for quotations with several vendors for a given set of products to compare offers.\" documentation=\"/applications/inventory_and_mrp/purchase/manage_deals/agreements.html\" help=\"Manage your purchase agreements (call for tenders, blanket orders)\">\n                            <field name=\"module_purchase_requisition\"/>\n                            <div class=\"content-group\" invisible=\"not module_purchase_requisition\">\n                                <div id=\"use_purchase_requisition\"/>\n                            </div>\n                        </setting>\n                        <setting id=\"auto_receipt_reminder\" help=\"Automatically remind the receipt date to your vendors\">\n                            <field name=\"group_send_reminder\"/>\n                        </setting>\n                    </block>\n                    <block title=\"Invoicing\" name=\"invoicing_settings_container\">\n                        <setting id=\"quantities_billed_vendor\" title=\"This default value is applied to any new product created. This can be changed in the product detail form.\" documentation=\"/applications/inventory_and_mrp/purchase/manage_deals/control_bills.html\" help=\"Quantities billed by vendors\">\n                            <field name=\"default_purchase_method\" class=\"o_light_label\" widget=\"radio\"/>\n                        </setting>\n                        <setting id=\"three_way_matching\" title=\"If enabled, activates 3-way matching on vendor bills : the items must be received in order to pay the invoice.\" documentation=\"/applications/inventory_and_mrp/purchase/manage_deals/control_bills.html\" help=\"Make sure you only pay bills for which you received the goods you ordered\">\n                            <field name=\"module_account_3way_match\" string=\"3-way matching\" widget=\"upgrade_boolean\"/>\n                        </setting>\n                    </block>\n                    <block title=\"Products\" name=\"matrix_setting_container\">\n                        <setting id=\"variant_options\" help=\"Purchase variants of a product using attributes (size, color, etc.)\" documentation=\"/applications/sales/sales/products_prices/products/variants.html\">\n                            <field name=\"group_product_variant\"/>\n                            <div class=\"content-group\" invisible=\"not group_product_variant\">\n                                <div class=\"mt8\">\n                                    <button name=\"172\" icon=\"oi-arrow-right\" type=\"action\" string=\"Attributes\" class=\"btn-link\"/>\n                                </div>\n                            </div>\n                        </setting>\n                        <setting id=\"product_matrix\" title=\"If installed, the product variants will be added to purchase orders through a grid entry.\" string=\"Variant Grid Entry\" help=\"Add several variants to the purchase order from a grid\">\n                            <field name=\"module_purchase_product_matrix\"/>\n                        </setting>\n                        <setting id=\"stock_packaging_purchase\" help=\"Purchase products by multiple of unit # per package\" title=\"Ability to select a package type in purchase orders and to force a quantity that is a multiple of the number of units per package.\">\n                            <field name=\"group_stock_packaging\"/>\n                        </setting>\n                        <setting id=\"sell_purchase_uom\" help=\"Sell and purchase products in different units of measure\" documentation=\"/applications/inventory_and_mrp/inventory/management/products/uom.html\">\n                            <field name=\"group_uom\"/>\n                            <div class=\"content-group\">\n                                <div class=\"mt8\" invisible=\"not group_uom\">\n                                    <button name=\"88\" icon=\"oi-arrow-right\" type=\"action\" string=\"Units Of Measure\" class=\"btn-link\"/>\n                                </div>\n                            </div>\n                        </setting>\n                    </block>\n                </app>\n            </xpath>"}', '<?xml version="1.0"?>
<xpath expr="//form" position="inside">
                <app data-string="Purchase" string="Purchase" name="purchase" groups="purchase.group_purchase_manager">
                    <field name="po_double_validation" invisible="1"/>
                    <field name="company_currency_id" invisible="1"/>
                    <field name="po_lock" invisible="1"/>
                    <block title="Orders" name="purchase_setting_container">
                        <setting id="po_order_approval" company_dependent="1" help="Request managers to approve orders above a minimum amount">
                            <field name="po_order_approval"/>
                            <div class="content-group" invisible="not po_order_approval">
                                <div class="row mt16">
                                    <label for="po_double_validation_amount" class="col-lg-4 o_light_label"/>
                                    <field name="po_double_validation_amount"/>
                                </div>
                            </div>
                        </setting>
                        <setting id="automatic_lock_confirmed_orders" help="Automatically lock confirmed orders to prevent editing">
                            <field name="lock_confirmed_po"/>
                        </setting>
                        <setting id="get_order_warnings" string="Warnings" help="Get warnings in orders for products or vendors">
                            <field name="group_warning_purchase"/>
                        </setting>
                        <setting id="manage_purchase_agreements" title="Calls for tenders are when you want to generate requests for quotations with several vendors for a given set of products to compare offers." documentation="/applications/inventory_and_mrp/purchase/manage_deals/agreements.html" help="Manage your purchase agreements (call for tenders, blanket orders)">
                            <field name="module_purchase_requisition"/>
                            <div class="content-group" invisible="not module_purchase_requisition">
                                <div id="use_purchase_requisition"/>
                            </div>
                        </setting>
                        <setting id="auto_receipt_reminder" help="Automatically remind the receipt date to your vendors">
                            <field name="group_send_reminder"/>
                        </setting>
                    </block>
                    <block title="Invoicing" name="invoicing_settings_container">
                        <setting id="quantities_billed_vendor" title="This default value is applied to any new product created. This can be changed in the product detail form." documentation="/applications/inventory_and_mrp/purchase/manage_deals/control_bills.html" help="Quantities billed by vendors">
                            <field name="default_purchase_method" class="o_light_label" widget="radio"/>
                        </setting>
                        <setting id="three_way_matching" title="If enabled, activates 3-way matching on vendor bills : the items must be received in order to pay the invoice." documentation="/applications/inventory_and_mrp/purchase/manage_deals/control_bills.html" help="Make sure you only pay bills for which you received the goods you ordered">
                            <field name="module_account_3way_match" string="3-way matching" widget="upgrade_boolean"/>
                        </setting>
                    </block>
                    <block title="Products" name="matrix_setting_container">
                        <setting id="variant_options" help="Purchase variants of a product using attributes (size, color, etc.)" documentation="/applications/sales/sales/products_prices/products/variants.html">
                            <field name="group_product_variant"/>
                            <div class="content-group" invisible="not group_product_variant">
                                <div class="mt8">
                                    <button name="172" icon="oi-arrow-right" type="action" string="Attributes" class="btn-link"/>
                                </div>
                            </div>
                        </setting>
                        <setting id="product_matrix" title="If installed, the product variants will be added to purchase orders through a grid entry." string="Variant Grid Entry" help="Add several variants to the purchase order from a grid">
                            <field name="module_purchase_product_matrix"/>
                        </setting>
                        <setting id="stock_packaging_purchase" help="Purchase products by multiple of unit # per package" title="Ability to select a package type in purchase orders and to force a quantity that is a multiple of the number of units per package.">
                            <field name="group_stock_packaging"/>
                        </setting>
                        <setting id="sell_purchase_uom" help="Sell and purchase products in different units of measure" documentation="/applications/inventory_and_mrp/inventory/management/products/uom.html">
                            <field name="group_uom"/>
                            <div class="content-group">
                                <div class="mt8" invisible="not group_uom">
                                    <button name="88" icon="oi-arrow-right" type="action" string="Units Of Measure" class="btn-link"/>
                                </div>
                            </div>
                        </setting>
                    </block>
                </app>
            </xpath>
        ', false, true, '2026-05-10 01:12:29.662147', '2026-05-10 01:12:29.662147', false);
INSERT INTO public.ir_ui_view VALUES (1168, 16, NULL, 1, 1, 'purchase.order.view.tree', 'purchase.order', NULL, 'tree', 'purchase/views/purchase_views.xml', 'primary', '{"en_US": "<tree decoration-muted=\"state == ''cancel''\" decoration-info=\"invoice_status == ''to invoice''\" string=\"Purchase Order\" class=\"o_purchase_order\" sample=\"1\">\n                    <header>\n                        <button name=\"action_create_invoice\" type=\"object\" string=\"Create Bills\"/>\n                    </header>\n                    <field name=\"priority\" optional=\"show\" widget=\"priority\" nolabel=\"1\"/>\n                    <field name=\"partner_ref\" optional=\"hide\"/>\n                    <field name=\"name\" string=\"Reference\" readonly=\"1\" decoration-bf=\"1\" decoration-info=\"state in (''draft'',''sent'')\"/>\n                    <field name=\"date_approve\" widget=\"date\" column_invisible=\"context.get(''quotation_only'', False)\" optional=\"show\"/>\n                    <field name=\"partner_id\" readonly=\"state in [''cancel'', ''done'', ''purchase'']\"/>\n                    <field name=\"company_id\" groups=\"base.group_multi_company\" options=\"{''no_create'': True}\" optional=\"show\" readonly=\"state in [''cancel'', ''done'', ''purchase'']\"/>\n                    <field name=\"company_id\" groups=\"!base.group_multi_company\" column_invisible=\"True\" readonly=\"state in [''cancel'', ''done'', ''purchase'']\"/>\n                    <field name=\"user_id\" widget=\"many2one_avatar_user\" optional=\"show\"/>\n                    <field name=\"date_order\" column_invisible=\"not context.get(''quotation_only'', False)\" readonly=\"state in [''cancel'', ''done'', ''purchase'']\" optional=\"show\"/>\n                    <field name=\"activity_ids\" widget=\"list_activity\" optional=\"show\"/>\n                    <field name=\"origin\" optional=\"show\"/>\n                    <field name=\"amount_untaxed\" sum=\"Total Untaxed amount\" string=\"Untaxed\" widget=\"monetary\" optional=\"hide\"/>\n                    <field name=\"amount_total\" sum=\"Total amount\" widget=\"monetary\" optional=\"show\" decoration-bf=\"1\"/>\n                    <field name=\"currency_id\" column_invisible=\"True\" readonly=\"state in [''cancel'', ''done'', ''purchase'']\"/>\n                    <field name=\"state\" column_invisible=\"True\"/>\n                    <field name=\"invoice_status\" widget=\"badge\" decoration-success=\"invoice_status == ''invoiced''\" decoration-info=\"invoice_status == ''to invoice''\" optional=\"show\"/>\n                    <field name=\"date_planned\" column_invisible=\"context.get(''quotation_only'', False)\" optional=\"show\"/>\n                </tree>"}', '<?xml version="1.0"?>
<tree decoration-muted="state == ''cancel''" decoration-info="invoice_status == ''to invoice''" string="Purchase Order" class="o_purchase_order" sample="1">
                    <header>
                        <button name="action_create_invoice" type="object" string="Create Bills"/>
                    </header>
                    <field name="priority" optional="show" widget="priority" nolabel="1"/>
                    <field name="partner_ref" optional="hide"/>
                    <field name="name" string="Reference" readonly="1" decoration-bf="1" decoration-info="state in (''draft'',''sent'')"/>
                    <field name="date_approve" widget="date" column_invisible="context.get(''quotation_only'', False)" optional="show"/>
                    <field name="partner_id" readonly="state in [''cancel'', ''done'', ''purchase'']"/>
                    <field name="company_id" groups="base.group_multi_company" options="{''no_create'': True}" optional="show" readonly="state in [''cancel'', ''done'', ''purchase'']"/>
                    <field name="company_id" groups="!base.group_multi_company" column_invisible="True" readonly="state in [''cancel'', ''done'', ''purchase'']"/>
                    <field name="user_id" widget="many2one_avatar_user" optional="show"/>
                    <field name="date_order" column_invisible="not context.get(''quotation_only'', False)" readonly="state in [''cancel'', ''done'', ''purchase'']" optional="show"/>
                    <field name="activity_ids" widget="list_activity" optional="show"/>
                    <field name="origin" optional="show"/>
                    <field name="amount_untaxed" sum="Total Untaxed amount" string="Untaxed" widget="monetary" optional="hide"/>
                    <field name="amount_total" sum="Total amount" widget="monetary" optional="show" decoration-bf="1"/>
                    <field name="currency_id" column_invisible="True" readonly="state in [''cancel'', ''done'', ''purchase'']"/>
                    <field name="state" column_invisible="True"/>
                    <field name="invoice_status" widget="badge" decoration-success="invoice_status == ''invoiced''" decoration-info="invoice_status == ''to invoice''" optional="show"/>
                    <field name="date_planned" column_invisible="context.get(''quotation_only'', False)" optional="show"/>
                </tree>
            ', false, true, '2026-05-10 01:12:29.662147', '2026-05-10 01:12:29.662147', false);
INSERT INTO public.ir_ui_view VALUES (1169, 16, NULL, 1, 1, 'purchase.order.activity', 'purchase.order', NULL, 'activity', 'purchase/views/purchase_views.xml', 'primary', '{"en_US": "<activity string=\"Purchase Order\">\n                    <field name=\"currency_id\"/>\n                    <templates>\n                        <div t-name=\"activity-box\" class=\"d-block\">\n                            <div class=\"d-flex justify-content-between\">\n                                <field name=\"name\" display=\"full\" class=\"o_text_block o_text_bold\"/>\n                                <div class=\"m-1\"/>\n                                <field name=\"amount_total\" widget=\"monetary\"/>\n                            </div>\n                            <div class=\"d-flex justify-content-between\">\n                                <field name=\"partner_id\" muted=\"1\" display=\"full\" class=\"o_text_block\"/>\n                                <div class=\"m-1\"/>\n                                <field name=\"state\" widget=\"badge\" decoration-success=\"state == ''purchase'' or state == ''done''\" decoration-warning=\"state == ''to approve''\" decoration-info=\"state == ''draft'' or state == ''sent''\"/>\n                            </div>\n                        </div>\n                    </templates>\n                </activity>"}', '<?xml version="1.0"?>
<activity string="Purchase Order">
                    <field name="currency_id"/>
                    <templates>
                        <div t-name="activity-box" class="d-block">
                            <div class="d-flex justify-content-between">
                                <field name="name" display="full" class="o_text_block o_text_bold"/>
                                <div class="m-1"/>
                                <field name="amount_total" widget="monetary"/>
                            </div>
                            <div class="d-flex justify-content-between">
                                <field name="partner_id" muted="1" display="full" class="o_text_block"/>
                                <div class="m-1"/>
                                <field name="state" widget="badge" decoration-success="state == ''purchase'' or state == ''done''" decoration-warning="state == ''to approve''" decoration-info="state == ''draft'' or state == ''sent''"/>
                            </div>
                        </div>
                    </templates>
                </activity>
            ', false, true, '2026-05-10 01:12:29.662147', '2026-05-10 01:12:29.662147', false);
INSERT INTO public.ir_ui_view VALUES (1170, 16, NULL, 1, 1, 'purchase.order.line.tree', 'purchase.order.line', NULL, 'tree', 'purchase/views/purchase_views.xml', 'primary', '{"en_US": "<tree string=\"Purchase Order Lines\" create=\"false\">\n                    <field name=\"order_id\"/>\n                    <field name=\"name\"/>\n                    <field name=\"partner_id\" string=\"Vendor\"/>\n                    <field name=\"product_id\"/>\n                    <field name=\"price_unit\"/>\n                    <field name=\"product_qty\"/>\n                    <field name=\"product_uom\" groups=\"uom.group_uom\"/>\n                    <field name=\"price_subtotal\" widget=\"monetary\"/>\n                    <field name=\"currency_id\" column_invisible=\"True\"/>\n                    <field name=\"date_planned\" widget=\"date\"/>\n                </tree>"}', '<?xml version="1.0"?>
<tree string="Purchase Order Lines" create="false">
                    <field name="order_id"/>
                    <field name="name"/>
                    <field name="partner_id" string="Vendor"/>
                    <field name="product_id"/>
                    <field name="price_unit"/>
                    <field name="product_qty"/>
                    <field name="product_uom" groups="uom.group_uom"/>
                    <field name="price_subtotal" widget="monetary"/>
                    <field name="currency_id" column_invisible="True"/>
                    <field name="date_planned" widget="date"/>
                </tree>
            ', false, true, '2026-05-10 01:12:29.662147', '2026-05-10 01:12:29.662147', false);
INSERT INTO public.ir_ui_view VALUES (1171, 20, NULL, 1, 1, 'purchase.order.line.form2', 'purchase.order.line', NULL, 'form', 'purchase/views/purchase_views.xml', 'primary', '{"en_US": "<form string=\"Purchase Order Line\" create=\"false\">\n                    <sheet>\n                        <label for=\"order_id\"/>\n                        <h1>\n                            <field name=\"order_id\" class=\"oe_inline\"/>\n                            <label string=\",\" for=\"date_order\" invisible=\"not date_order\"/>\n                            <field name=\"date_order\" class=\"oe_inline\"/>\n                        </h1>\n                        <label for=\"partner_id\"/>\n                        <h2><field name=\"partner_id\"/></h2>\n                        <group>\n                            <group>\n                                <field name=\"product_id\" readonly=\"1\"/>\n                                <label for=\"product_qty\"/>\n                                <div class=\"o_row\">\n                                    <field name=\"product_qty\" readonly=\"1\"/>\n                                    <field name=\"product_uom\" readonly=\"1\" groups=\"uom.group_uom\"/>\n                                </div>\n                                <field name=\"price_unit\"/>\n                            </group>\n                            <group>\n                                <field name=\"taxes_id\" widget=\"many2many_tags\" domain=\"[(''type_tax_use'', ''='', ''purchase'')]\"/>\n                                <field name=\"date_planned\" widget=\"date\" readonly=\"1\"/>\n                                <field name=\"company_id\" groups=\"base.group_multi_company\" options=\"{''no_create'': True}\"/>\n                                <field name=\"analytic_distribution\" widget=\"analytic_distribution\" groups=\"analytic.group_analytic_accounting\" options=\"{''product_field'': ''product_id'', ''business_domain'': ''purchase_order''}\"/>\n                            </group>\n                        </group>\n                        <field name=\"name\"/>\n                        <separator string=\"Manual Invoices\"/>\n                        <field name=\"invoice_lines\"/>\n                    </sheet>\n                </form>"}', '<?xml version="1.0"?>
<form string="Purchase Order Line" create="false">
                    <sheet>
                        <label for="order_id"/>
                        <h1>
                            <field name="order_id" class="oe_inline"/>
                            <label string="," for="date_order" invisible="not date_order"/>
                            <field name="date_order" class="oe_inline"/>
                        </h1>
                        <label for="partner_id"/>
                        <h2><field name="partner_id"/></h2>
                        <group>
                            <group>
                                <field name="product_id" readonly="1"/>
                                <label for="product_qty"/>
                                <div class="o_row">
                                    <field name="product_qty" readonly="1"/>
                                    <field name="product_uom" readonly="1" groups="uom.group_uom"/>
                                </div>
                                <field name="price_unit"/>
                            </group>
                            <group>
                                <field name="taxes_id" widget="many2many_tags" domain="[(''type_tax_use'', ''='', ''purchase'')]"/>
                                <field name="date_planned" widget="date" readonly="1"/>
                                <field name="company_id" groups="base.group_multi_company" options="{''no_create'': True}"/>
                                <field name="analytic_distribution" widget="analytic_distribution" groups="analytic.group_analytic_accounting" options="{''product_field'': ''product_id'', ''business_domain'': ''purchase_order''}"/>
                            </group>
                        </group>
                        <field name="name"/>
                        <separator string="Manual Invoices"/>
                        <field name="invoice_lines"/>
                    </sheet>
                </form>
            ', false, true, '2026-05-10 01:12:29.662147', '2026-05-10 01:12:29.662147', false);
INSERT INTO public.ir_ui_view VALUES (1172, 16, NULL, 1, 1, 'purchase.order.line.search', 'purchase.order.line', NULL, 'search', 'purchase/views/purchase_views.xml', 'primary', '{"en_US": "<search string=\"Search Purchase Order\">\n                    <field name=\"order_id\"/>\n                    <field name=\"product_id\"/>\n                    <field name=\"partner_id\" string=\"Vendor\"/>\n                    <filter name=\"hide_cancelled\" string=\"Hide cancelled lines\" domain=\"[(''state'', ''!='', ''cancel'')]\"/>\n                    <group expand=\"0\" string=\"Group By\">\n                        <filter name=\"groupby_supplier\" string=\"Vendor\" domain=\"[]\" context=\"{''group_by'' : ''partner_id''}\"/>\n                        <filter name=\"groupby_product\" string=\"Product\" domain=\"[]\" context=\"{''group_by'' : ''product_id''}\"/>\n                        <filter string=\"Order Reference\" name=\"order_reference\" domain=\"[]\" context=\"{''group_by'' :''order_id''}\"/>\n                        <filter string=\"Status\" name=\"status\" domain=\"[]\" context=\"{''group_by'' : ''state''}\"/>\n                    </group>\n                </search>"}', '<?xml version="1.0"?>
<search string="Search Purchase Order">
                    <field name="order_id"/>
                    <field name="product_id"/>
                    <field name="partner_id" string="Vendor"/>
                    <filter name="hide_cancelled" string="Hide cancelled lines" domain="[(''state'', ''!='', ''cancel'')]"/>
                    <group expand="0" string="Group By">
                        <filter name="groupby_supplier" string="Vendor" domain="[]" context="{''group_by'' : ''partner_id''}"/>
                        <filter name="groupby_product" string="Product" domain="[]" context="{''group_by'' : ''product_id''}"/>
                        <filter string="Order Reference" name="order_reference" domain="[]" context="{''group_by'' :''order_id''}"/>
                        <filter string="Status" name="status" domain="[]" context="{''group_by'' : ''state''}"/>
                    </group>
                </search>
            ', false, true, '2026-05-10 01:12:29.662147', '2026-05-10 01:12:29.662147', false);
INSERT INTO public.ir_ui_view VALUES (1175, 1000, 495, 1, 1, 'product.supplierinfo.tree.view2', 'product.supplierinfo', NULL, 'tree', 'purchase/views/product_views.xml', 'primary', '{"en_US": "<data><xpath expr=\"//tree\" position=\"attributes\">\n                    <attribute name=\"editable\">bottom</attribute>\n                </xpath>\n                <xpath expr=\"//tree\" position=\"inside\">\n                    <field name=\"company_id\" column_invisible=\"True\"/>\n                </xpath>\n                <xpath expr=\"//field[@name=''company_id'']\" position=\"attributes\">\n                    <attribute name=\"readonly\">0</attribute>\n                    <attribute name=\"optional\">hide</attribute>\n                </xpath>\n                <xpath expr=\"//field[@name=''partner_id'']\" position=\"attributes\">\n                    <attribute name=\"readonly\">0</attribute>\n                </xpath>\n                <xpath expr=\"//field[@name=''product_id'']\" position=\"attributes\">\n                    <attribute name=\"readonly\">0</attribute>\n                    <attribute name=\"options\">{''no_create'': True, ''no_open'': True}</attribute>\n                </xpath>\n                <xpath expr=\"//field[@name=''delay'']\" position=\"attributes\">\n                    <attribute name=\"optional\">show</attribute>\n                </xpath>\n            </data>"}', '<?xml version="1.0"?>
<data><xpath expr="//tree" position="attributes">
                    <attribute name="editable">bottom</attribute>
                </xpath>
                <xpath expr="//tree" position="inside">
                    <field name="company_id" column_invisible="True"/>
                </xpath>
                <xpath expr="//field[@name=''company_id'']" position="attributes">
                    <attribute name="readonly">0</attribute>
                    <attribute name="optional">hide</attribute>
                </xpath>
                <xpath expr="//field[@name=''partner_id'']" position="attributes">
                    <attribute name="readonly">0</attribute>
                </xpath>
                <xpath expr="//field[@name=''product_id'']" position="attributes">
                    <attribute name="readonly">0</attribute>
                    <attribute name="options">{''no_create'': True, ''no_open'': True}</attribute>
                </xpath>
                <xpath expr="//field[@name=''delay'']" position="attributes">
                    <attribute name="optional">show</attribute>
                </xpath>
            </data>', false, true, '2026-05-10 01:12:29.662147', '2026-05-10 01:12:29.662147', false);
INSERT INTO public.ir_ui_view VALUES (1176, 16, 453, 1, 1, 'product.template.supplier.form.inherit', 'product.template', NULL, 'form', 'purchase/views/product_views.xml', 'extension', '{"en_US": "<data><xpath expr=\"//page[@name=''purchase'']\" position=\"attributes\">\n                    <attribute name=\"invisible\" remove=\"1\" separator=\" or \"/>\n                    <attribute name=\"groups\">purchase.group_purchase_user</attribute>\n                </xpath>\n                <group name=\"purchase\" position=\"before\">\n                    <field name=\"seller_ids\" context=\"{''default_product_tmpl_id'': id, ''product_template_invisible_variant'': True, ''tree_view_ref'':''purchase.product_supplierinfo_tree_view2''}\" nolabel=\"1\" invisible=\"product_variant_count &gt; 1\" readonly=\"product_variant_count &gt; 1\"/>\n                    <field name=\"variant_seller_ids\" context=\"{''model'': ''product.template'', ''active_id'': id, ''tree_view_ref'':''purchase.product_supplierinfo_tree_view2''}\" nolabel=\"1\" invisible=\"product_variant_count &lt;= 1\" readonly=\"product_variant_count &lt;= 1\"/>\n                </group>\n                <group name=\"bill\" position=\"attributes\">\n                    <attribute name=\"groups\">purchase.group_purchase_manager</attribute>\n                </group>\n                <group name=\"bill\" position=\"inside\">\n                    <field name=\"purchase_method\" widget=\"radio\"/>\n                </group>\n                <group name=\"purchase\" position=\"inside\">\n                    <group col=\"1\">\n                        <group string=\"Purchase Description\">\n                           <field name=\"description_purchase\" nolabel=\"1\" colspan=\"2\" placeholder=\"This note is added to purchase orders.\"/>\n                        </group>\n                        <group string=\"Warning when Purchasing this Product\" groups=\"purchase.group_warning_purchase\">\n                            <field name=\"purchase_line_warn\" nolabel=\"1\" colspan=\"2\"/>\n                            <field name=\"purchase_line_warn_msg\" colspan=\"2\" nolabel=\"1\" placeholder=\"Type a message...\" invisible=\"purchase_line_warn == ''no-message''\" readonly=\"purchase_line_warn == ''no-message''\" required=\"purchase_line_warn != ''no-message''\"/>\n                        </group>\n                    </group>\n                </group>\n            </data>"}', '<?xml version="1.0"?>
<data><xpath expr="//page[@name=''purchase'']" position="attributes">
                    <attribute name="invisible" remove="1" separator=" or "/>
                    <attribute name="groups">purchase.group_purchase_user</attribute>
                </xpath>
                <group name="purchase" position="before">
                    <field name="seller_ids" context="{''default_product_tmpl_id'': id, ''product_template_invisible_variant'': True, ''tree_view_ref'':''purchase.product_supplierinfo_tree_view2''}" nolabel="1" invisible="product_variant_count &gt; 1" readonly="product_variant_count &gt; 1"/>
                    <field name="variant_seller_ids" context="{''model'': ''product.template'', ''active_id'': id, ''tree_view_ref'':''purchase.product_supplierinfo_tree_view2''}" nolabel="1" invisible="product_variant_count &lt;= 1" readonly="product_variant_count &lt;= 1"/>
                </group>
                <group name="bill" position="attributes">
                    <attribute name="groups">purchase.group_purchase_manager</attribute>
                </group>
                <group name="bill" position="inside">
                    <field name="purchase_method" widget="radio"/>
                </group>
                <group name="purchase" position="inside">
                    <group col="1">
                        <group string="Purchase Description">
                           <field name="description_purchase" nolabel="1" colspan="2" placeholder="This note is added to purchase orders."/>
                        </group>
                        <group string="Warning when Purchasing this Product" groups="purchase.group_warning_purchase">
                            <field name="purchase_line_warn" nolabel="1" colspan="2"/>
                            <field name="purchase_line_warn_msg" colspan="2" nolabel="1" placeholder="Type a message..." invisible="purchase_line_warn == ''no-message''" readonly="purchase_line_warn == ''no-message''" required="purchase_line_warn != ''no-message''"/>
                        </group>
                    </group>
                </group>
            </data>', false, true, '2026-05-10 01:12:29.662147', '2026-05-10 01:12:29.662147', false);
INSERT INTO public.ir_ui_view VALUES (1177, 16, 460, 1, 1, 'product.product.form', 'product.product', NULL, 'form', 'purchase/views/product_views.xml', 'extension', '{"en_US": "<data><field name=\"seller_ids\" position=\"attributes\">\n                    <attribute name=\"context\">{''default_product_tmpl_id'': product_tmpl_id, ''product_template_invisible_variant'': True, ''tree_view_ref'':''purchase.product_supplierinfo_tree_view2''}</attribute>\n                </field>\n                <field name=\"variant_seller_ids\" position=\"attributes\">\n                    <attribute name=\"context\">{''model'': ''product.product'', ''active_id'': id, ''tree_view_ref'':''purchase.product_supplierinfo_tree_view2''}</attribute>\n                </field>\n            </data>"}', '<?xml version="1.0"?>
