INSERT INTO public.ir_ui_view VALUES (1185, 16, 128, 1, 1, 'res.partner.kanban.purchaseorder.inherit', 'res.partner', NULL, 'kanban', 'purchase/views/res_partner_views.xml', 'extension', '{"en_US": "<data><field name=\"mobile\" position=\"after\">\n                    <field name=\"purchase_order_count\" groups=\"purchase.group_purchase_user\"/>\n                </field>\n                <xpath expr=\"//div[hasclass(''oe_kanban_bottom_left'')]\" position=\"inside\">\n                    <a t-if=\"record.purchase_order_count.value&gt;0\" data-type=\"action\" data-name=\"438\" groups=\"purchase.group_purchase_user\" href=\"#\" class=\"oe_kanban_action oe_kanban_action_a me-1\">\n                        <span class=\"badge rounded-pill\">\n                            <i class=\"fa fa-fw fa-credit-card\" role=\"img\" aria-label=\"Purchases\" title=\"Purchases\"/>\n                            <t t-out=\"record.purchase_order_count.value\"/>\n                        </span>\n                    </a>\n                </xpath>\n            </data>"}', '<?xml version="1.0"?>
