INSERT INTO public.ir_ui_view VALUES (1229, 16, 463, 1, 1, 'product.view.kanban.catalog.purchase_stock', 'product.product', NULL, 'kanban', 'purchase_stock/views/product_views.xml', 'primary', '{"en_US": "<div name=\"o_kanban_qty_available\" position=\"after\">\n                <div t-if=\"record.detailed_type.raw_value == ''product''\" name=\"o_kanban_qty_forecasted\">\n                    <span>Forecasted: </span>\n                    <field name=\"virtual_available\"/>\n                    <field name=\"uom_id\" class=\"ms-1\" groups=\"uom.group_uom\"/>\n                </div>\n            </div>"}', '<?xml version="1.0"?>
