INSERT INTO public.ir_ui_view VALUES (1186, 9, 125, 1, 1, 'res.partner.view.purchase.buttons', 'res.partner', NULL, 'form', 'purchase/views/res_partner_views.xml', 'extension', '{"en_US": "<data><div name=\"button_box\" position=\"inside\">\n                    <button class=\"oe_stat_button\" name=\"438\" type=\"action\" groups=\"purchase.group_purchase_user\" icon=\"fa-credit-card\">\n                        <field string=\"Purchases\" name=\"purchase_order_count\" widget=\"statinfo\"/>\n                    </button>\n                </div>\n                <page name=\"internal_notes\" position=\"inside\">\n                    <group groups=\"purchase.group_purchase_user\">\n                        <group groups=\"purchase.group_warning_purchase\" col=\"2\">\n                            <separator string=\"Warning on the Purchase Order\" colspan=\"2\"/>\n                            <field name=\"purchase_warn\" nolabel=\"1\" colspan=\"2\" required=\"1\"/>\n                            <field name=\"purchase_warn_msg\" colspan=\"2\" placeholder=\"Type a message...\" nolabel=\"1\" invisible=\"purchase_warn in (False, ''no-message'')\" required=\"purchase_warn and purchase_warn != ''no-message''\"/>\n                        </group>\n                    </group>\n                </page>\n            </data>"}', '<?xml version="1.0"?>
<data><div name="button_box" position="inside">
                    <button class="oe_stat_button" name="438" type="action" groups="purchase.group_purchase_user" icon="fa-credit-card">
                        <field string="Purchases" name="purchase_order_count" widget="statinfo"/>
                    </button>
                </div>
                <page name="internal_notes" position="inside">
                    <group groups="purchase.group_purchase_user">
                        <group groups="purchase.group_warning_purchase" col="2">
                            <separator string="Warning on the Purchase Order" colspan="2"/>
                            <field name="purchase_warn" nolabel="1" colspan="2" required="1"/>
                            <field name="purchase_warn_msg" colspan="2" placeholder="Type a message..." nolabel="1" invisible="purchase_warn in (False, ''no-message'')" required="purchase_warn and purchase_warn != ''no-message''"/>
                        </group>
                    </group>
                </page>
            </data>', false, true, '2026-05-10 01:12:29.662147', '2026-05-10 01:12:29.662147', false);
INSERT INTO public.ir_ui_view VALUES (1187, 12, 125, 1, 1, 'res.partner.view.purchase.account.buttons', 'res.partner', NULL, 'form', 'purchase/views/res_partner_views.xml', 'extension', '{"en_US": "<div name=\"button_box\" position=\"inside\">\n                </div>"}', '<?xml version="1.0"?>
