INSERT INTO public.ir_ui_view VALUES (1188, 16, NULL, 1, 1, 'purchase.bill.union.select', 'purchase.bill.union', NULL, 'search', 'purchase/report/purchase_bill_views.xml', 'primary', '{"en_US": "<search string=\"Search Reference Document\">\n                <field name=\"name\" string=\"Reference\" filter_domain=\"[''|'', (''name'',''ilike'',self), (''reference'',''=like'',self+''%'')]\"/>\n                <field name=\"amount\"/>\n                <separator/>\n                <field name=\"partner_id\" operator=\"child_of\"/>\n                <separator/>\n                <filter name=\"purchase_orders\" string=\"Purchase Orders\" domain=\"[(''purchase_order_id'', ''!='', False)]\"/>\n                <filter name=\"vendor_bills\" string=\"Vendor Bills\" domain=\"[(''vendor_bill_id'', ''!='', False)]\"/>\n            </search>"}', '<?xml version="1.0"?>
<search string="Search Reference Document">
                <field name="name" string="Reference" filter_domain="[''|'', (''name'',''ilike'',self), (''reference'',''=like'',self+''%'')]"/>
                <field name="amount"/>
                <separator/>
                <field name="partner_id" operator="child_of"/>
                <separator/>
                <filter name="purchase_orders" string="Purchase Orders" domain="[(''purchase_order_id'', ''!='', False)]"/>
                <filter name="vendor_bills" string="Vendor Bills" domain="[(''vendor_bill_id'', ''!='', False)]"/>
            </search>
        ', false, true, '2026-05-10 01:12:29.662147', '2026-05-10 01:12:29.662147', false);
INSERT INTO public.ir_ui_view VALUES (1189, 16, NULL, 1, 1, 'purchase.bill.union.tree', 'purchase.bill.union', NULL, 'tree', 'purchase/report/purchase_bill_views.xml', 'primary', '{"en_US": "<tree string=\"Reference Document\">\n                <field name=\"name\"/>\n                <field name=\"reference\"/>\n                <field name=\"partner_id\"/>\n                <field name=\"date\"/>\n                <field name=\"amount\"/>\n                <field name=\"currency_id\" column_invisible=\"True\"/>\n                <field name=\"company_id\" groups=\"base.group_multi_company\" options=\"{''no_create'': True}\"/>\n            </tree>"}', '<?xml version="1.0"?>
<tree string="Reference Document">
                <field name="name"/>
                <field name="reference"/>
                <field name="partner_id"/>
                <field name="date"/>
                <field name="amount"/>
                <field name="currency_id" column_invisible="True"/>
                <field name="company_id" groups="base.group_multi_company" options="{''no_create'': True}"/>
            </tree>
        ', false, true, '2026-05-10 01:12:29.662147', '2026-05-10 01:12:29.662147', false);
INSERT INTO public.ir_ui_view VALUES (1190, 16, NULL, 1, 1, 'product.month.pivot', 'purchase.report', NULL, 'pivot', 'purchase/report/purchase_report_views.xml', 'primary', '{"en_US": "<pivot string=\"Purchase Analysis\" display_quantity=\"1\" sample=\"1\">\n                    <field name=\"category_id\" type=\"row\"/>\n                    <field name=\"order_id\" type=\"row\"/>\n                    <field name=\"untaxed_total\" type=\"measure\"/>\n                    <field name=\"price_total\" type=\"measure\"/>\n                </pivot>"}', '<?xml version="1.0"?>
<pivot string="Purchase Analysis" display_quantity="1" sample="1">
                    <field name="category_id" type="row"/>
                    <field name="order_id" type="row"/>
                    <field name="untaxed_total" type="measure"/>
                    <field name="price_total" type="measure"/>
                </pivot>
            ', false, true, '2026-05-10 01:12:29.662147', '2026-05-10 01:12:29.662147', false);
INSERT INTO public.ir_ui_view VALUES (1191, 16, NULL, 1, 1, 'product.month.graph', 'purchase.report', NULL, 'graph', 'purchase/report/purchase_report_views.xml', 'primary', '{"en_US": "<graph string=\"Purchase Analysis\" type=\"line\" sample=\"1\">\n                    <field name=\"date_approve\" interval=\"day\"/>\n                    <field name=\"untaxed_total\" type=\"measure\"/>\n                </graph>"}', '<?xml version="1.0"?>
