INSERT INTO public.ir_ui_view VALUES (1192, 16, NULL, 1, 1, 'purchase.report.view.tree', 'purchase.report', NULL, 'tree', 'purchase/report/purchase_report_views.xml', 'primary', '{"en_US": "<tree string=\"Purchase Analysis\">\n                    <field name=\"date_order\" widget=\"date\"/>\n                    <field name=\"order_id\" optional=\"show\"/>\n                    <field name=\"partner_id\" optional=\"show\"/>\n                    <field name=\"product_id\" optional=\"show\"/>\n                    <field name=\"category_id\" optional=\"show\"/>\n                    <field name=\"user_id\" optional=\"show\" widget=\"many2one_avatar_user\"/>\n                    <field name=\"company_id\" optional=\"show\" groups=\"base.group_multi_company\"/>\n                    <field name=\"qty_ordered\" optional=\"hide\" sum=\"Sum of Qty Ordered\"/>\n                    <field name=\"qty_received\" optional=\"hide\" sum=\"Sum of Qty Received\"/>\n                    <field name=\"qty_billed\" optional=\"hide\" sum=\"Sum of Qty Billed\"/>\n                    <field name=\"currency_id\" optional=\"show\" column_invisible=\"True\"/>\n                    <field name=\"untaxed_total\" optional=\"hide\" widget=\"monetary\" sum=\"Sum of Untaxed Total\"/>\n                    <field name=\"price_total\" optional=\"show\" widget=\"monetary\" sum=\"Sum of Total\"/>\n                    <field name=\"state\" optional=\"show\"/>\n                </tree>"}', '<?xml version="1.0"?>
<tree string="Purchase Analysis">
                    <field name="date_order" widget="date"/>
                    <field name="order_id" optional="show"/>
                    <field name="partner_id" optional="show"/>
                    <field name="product_id" optional="show"/>
                    <field name="category_id" optional="show"/>
                    <field name="user_id" optional="show" widget="many2one_avatar_user"/>
                    <field name="company_id" optional="show" groups="base.group_multi_company"/>
                    <field name="qty_ordered" optional="hide" sum="Sum of Qty Ordered"/>
                    <field name="qty_received" optional="hide" sum="Sum of Qty Received"/>
                    <field name="qty_billed" optional="hide" sum="Sum of Qty Billed"/>
                    <field name="currency_id" optional="show" column_invisible="True"/>
                    <field name="untaxed_total" optional="hide" widget="monetary" sum="Sum of Untaxed Total"/>
                    <field name="price_total" optional="show" widget="monetary" sum="Sum of Total"/>
                    <field name="state" optional="show"/>
                </tree>
            ', false, true, '2026-05-10 01:12:29.662147', '2026-05-10 01:12:29.662147', false);
INSERT INTO public.ir_ui_view VALUES (1193, 16, NULL, 1, 1, 'report.purchase.order.search', 'purchase.report', NULL, 'search', 'purchase/report/purchase_report_views.xml', 'primary', '{"en_US": "<search string=\"Purchase Orders\">\n                <filter string=\"Requests for Quotation\" name=\"quotes\" domain=\"[(''state'',''in'',(''draft'',''sent''))]\"/>\n                <filter string=\"Purchase Orders\" name=\"orders\" domain=\"[(''state'',''!='',''draft''), (''state'',''!='',''sent''), (''state'',''!='',''cancel'')]\"/>\n                <filter string=\"Confirmation Date Last Year\" name=\"later_than_a_year_ago\" domain=\"[(''date_approve'', ''&gt;='', ((context_today()-relativedelta(years=1)).strftime(''%Y-%m-%d'')))]\"/>\n                <filter name=\"filter_date_order\" date=\"date_order\"/>\n                <filter name=\"filter_date_approve\" date=\"date_approve\" default_period=\"this_month\"/>\n                <field name=\"partner_id\"/>\n                <field name=\"product_id\"/>\n                <group expand=\"0\" string=\"Extended Filters\">\n                    <field name=\"user_id\"/>\n                    <field name=\"company_id\" groups=\"base.group_multi_company\"/>\n                    <field name=\"date_order\"/>\n                    <field name=\"date_approve\"/>\n                    <field name=\"category_id\" filter_domain=\"[(''category_id'', ''child_of'', self)]\"/>\n                </group>\n                <group expand=\"1\" string=\"Group By\">\n                    <filter string=\"Vendor\" name=\"group_partner_id\" context=\"{''group_by'':''partner_id''}\"/>\n                    <filter string=\"Vendor Country\" name=\"country_id\" context=\"{''group_by'':''country_id''}\"/>\n                    <filter string=\"Buyer\" name=\"user_id\" context=\"{''group_by'':''user_id''}\"/>\n                    <filter string=\"Product\" name=\"group_product_id\" context=\"{''group_by'':''product_id''}\"/>\n                    <filter string=\"Product Category\" name=\"group_category_id\" context=\"{''group_by'':''category_id''}\"/>\n                    <filter string=\"Status\" name=\"status\" context=\"{''group_by'':''state''}\"/>\n                    <filter string=\"Company\" name=\"company\" context=\"{''group_by'':''company_id''}\" groups=\"base.group_multi_company\"/>\n                    <separator/>\n                    <filter string=\"Order Date\" name=\"order_month\" context=\"{''group_by'': ''date_order:month''}\"/>\n                    <filter string=\"Confirmation Date\" name=\"group_date_approve_month\" context=\"{''group_by'': ''date_approve:month''}\"/>\n                </group>\n            </search>"}', '<?xml version="1.0"?>
<search string="Purchase Orders">
                <filter string="Requests for Quotation" name="quotes" domain="[(''state'',''in'',(''draft'',''sent''))]"/>
                <filter string="Purchase Orders" name="orders" domain="[(''state'',''!='',''draft''), (''state'',''!='',''sent''), (''state'',''!='',''cancel'')]"/>
                <filter string="Confirmation Date Last Year" name="later_than_a_year_ago" domain="[(''date_approve'', ''&gt;='', ((context_today()-relativedelta(years=1)).strftime(''%Y-%m-%d'')))]"/>
                <filter name="filter_date_order" date="date_order"/>
                <filter name="filter_date_approve" date="date_approve" default_period="this_month"/>
                <field name="partner_id"/>
                <field name="product_id"/>
                <group expand="0" string="Extended Filters">
                    <field name="user_id"/>
                    <field name="company_id" groups="base.group_multi_company"/>
                    <field name="date_order"/>
                    <field name="date_approve"/>
                    <field name="category_id" filter_domain="[(''category_id'', ''child_of'', self)]"/>
                </group>
                <group expand="1" string="Group By">
                    <filter string="Vendor" name="group_partner_id" context="{''group_by'':''partner_id''}"/>
                    <filter string="Vendor Country" name="country_id" context="{''group_by'':''country_id''}"/>
                    <filter string="Buyer" name="user_id" context="{''group_by'':''user_id''}"/>
                    <filter string="Product" name="group_product_id" context="{''group_by'':''product_id''}"/>
                    <filter string="Product Category" name="group_category_id" context="{''group_by'':''category_id''}"/>
                    <filter string="Status" name="status" context="{''group_by'':''state''}"/>
                    <filter string="Company" name="company" context="{''group_by'':''company_id''}" groups="base.group_multi_company"/>
                    <separator/>
                    <filter string="Order Date" name="order_month" context="{''group_by'': ''date_order:month''}"/>
                    <filter string="Confirmation Date" name="group_date_approve_month" context="{''group_by'': ''date_approve:month''}"/>
                </group>
            </search>
        ', false, true, '2026-05-10 01:12:29.662147', '2026-05-10 01:12:29.662147', false);
INSERT INTO public.ir_ui_view VALUES (1194, 16, NULL, 1, 1, 'track_po_line_template', NULL, 'purchase.track_po_line_template', 'qweb', 'purchase/data/mail_templates.xml', 'primary', '{"en_US": "<t t-name=\"purchase.track_po_line_template\">\n        <div>\n            <strong>The ordered quantity has been updated.</strong>\n            <ul>\n                <li><t t-esc=\"line.product_id.display_name\"/>:</li>\n                Ordered Quantity: <t t-esc=\"line.product_qty\"/> -&gt; <t t-esc=\"float(product_qty)\"/><br/>\n                <t t-if=\"line.order_id.product_id.type in (&quot;consu&quot;, &quot;product&quot;)\">\n                    Received Quantity: <t t-esc=\"line.qty_received\"/><br/>\n                </t>\n                Billed Quantity: <t t-esc=\"line.qty_invoiced\"/>\n            </ul>\n        </div>\n    </t>"}', '<?xml version="1.0"?>
<t t-name="purchase.track_po_line_template">
        <div>
            <strong>The ordered quantity has been updated.</strong>
            <ul>
                <li><t t-esc="line.product_id.display_name"/>:</li>
                Ordered Quantity: <t t-esc="line.product_qty"/> -&gt; <t t-esc="float(product_qty)"/><br/>
                <t t-if="line.order_id.product_id.type in (&quot;consu&quot;, &quot;product&quot;)">
                    Received Quantity: <t t-esc="line.qty_received"/><br/>
                </t>
                Billed Quantity: <t t-esc="line.qty_invoiced"/>
            </ul>
        </div>
    </t>

    ', false, true, '2026-05-10 01:12:29.662147', '2026-05-10 01:12:29.662147', false);
INSERT INTO public.ir_ui_view VALUES (1195, 16, NULL, 1, 1, 'track_po_line_qty_received_template', NULL, 'purchase.track_po_line_qty_received_template', 'qweb', 'purchase/data/mail_templates.xml', 'primary', '{"en_US": "<t t-name=\"purchase.track_po_line_qty_received_template\">\n        <div>\n            <strong>The received quantity has been updated.</strong>\n            <ul>\n                <li><t t-esc=\"line.product_id.display_name\"/>:</li>\n                Received Quantity: <t t-esc=\"line.qty_received\"/> -&gt; <t t-esc=\"float(qty_received)\"/><br/>\n            </ul>\n        </div>\n    </t>"}', '<?xml version="1.0"?>
<t t-name="purchase.track_po_line_qty_received_template">
        <div>
            <strong>The received quantity has been updated.</strong>
            <ul>
                <li><t t-esc="line.product_id.display_name"/>:</li>
                Received Quantity: <t t-esc="line.qty_received"/> -&gt; <t t-esc="float(qty_received)"/><br/>
