', false, true, '2026-05-10 01:12:29.662147', '2026-05-10 01:12:29.662147', false);
INSERT INTO public.ir_ui_view VALUES (1196, 25, 542, 1, 1, 'Portal layout : purchase menu entries', NULL, 'purchase.portal_my_home_menu_purchase', 'qweb', 'purchase/views/portal_templates.xml', 'extension', '{"en_US": "<data name=\"Portal layout : purchase menu entries\" inherit_id=\"portal.portal_breadcrumbs\" priority=\"25\">\n    <xpath expr=\"//ol[hasclass(''o_portal_submenu'')]\" position=\"inside\">\n      <li t-if=\"page_name == ''rfq'' or order and order.state == ''sent''\" t-attf-class=\"breadcrumb-item #{''active '' if not order else ''''}\">\n        <a t-if=\"order\" t-attf-href=\"/my/rfq?{{ keep_query() }}\">Requests for Quotation</a>\n        <t t-else=\"\">Requests for Quotation</t>\n      </li>\n      <li t-if=\"page_name == ''purchase'' or order and order.state != ''sent''\" t-attf-class=\"breadcrumb-item #{''active '' if not order else ''''}\">\n        <a t-if=\"order\" t-attf-href=\"/my/purchase?{{ keep_query() }}\">Purchase Orders</a>\n        <t t-else=\"\">Purchase Orders</t>\n      </li>\n      <li t-if=\"order\" class=\"breadcrumb-item active\">\n        <t t-esc=\"order.name\"/>\n      </li>\n    </xpath>\n  </data>"}', '<?xml version="1.0"?>
<data name="Portal layout : purchase menu entries" inherit_id="portal.portal_breadcrumbs" priority="25">
    <xpath expr="//ol[hasclass(''o_portal_submenu'')]" position="inside">
      <li t-if="page_name == ''rfq'' or order and order.state == ''sent''" t-attf-class="breadcrumb-item #{''active '' if not order else ''''}">
        <a t-if="order" t-attf-href="/my/rfq?{{ keep_query() }}">Requests for Quotation</a>
        <t t-else="">Requests for Quotation</t>
      </li>
      <li t-if="page_name == ''purchase'' or order and order.state != ''sent''" t-attf-class="breadcrumb-item #{''active '' if not order else ''''}">
        <a t-if="order" t-attf-href="/my/purchase?{{ keep_query() }}">Purchase Orders</a>
        <t t-else="">Purchase Orders</t>
      </li>
      <li t-if="order" class="breadcrumb-item active">
        <t t-esc="order.name"/>
      </li>
    </xpath>
  </data>

  ', false, true, '2026-05-10 01:12:29.662147', '2026-05-10 01:12:29.662147', false);
INSERT INTO public.ir_ui_view VALUES (1203, 16, 1200, 1, 1, 'Portal: My Purchase Order Update Dates', NULL, 'purchase.portal_my_purchase_order_update_date', 'qweb', 'purchase/views/portal_templates.xml', 'primary', '{"en_US": "<data name=\"Portal: My Purchase Order Update Dates\" inherit_id=\"purchase.portal_my_purchase_order\" primary=\"True\">\n    <xpath expr=\"////div[@id=''portal_purchase_content'']\" position=\"replace\">\n      <div id=\"portal_purchase_content\">\n        <t t-set=\"update_dates\" t-value=\"True\"/>\n        <div t-call=\"purchase.purchase_order_portal_content\"/>\n      </div>\n    </xpath>\n  <xpath expr=\".\" position=\"attributes\"><attribute name=\"t-name\">purchase.portal_my_purchase_order_update_date</attribute></xpath></data>"}', '<?xml version="1.0"?>
<data name="Portal: My Purchase Order Update Dates" inherit_id="purchase.portal_my_purchase_order" primary="True">
    <xpath expr="////div[@id=''portal_purchase_content'']" position="replace">
      <div id="portal_purchase_content">
        <t t-set="update_dates" t-value="True"/>
        <div t-call="purchase.purchase_order_portal_content"/>
      </div>
    </xpath>
  <xpath expr="." position="attributes"><attribute name="t-name">purchase.portal_my_purchase_order_update_date</attribute></xpath></data>

', false, true, '2026-05-10 01:12:29.662147', '2026-05-10 01:12:29.662147', false);
INSERT INTO public.ir_ui_view VALUES (1204, 16, NULL, 1, 1, 'report_purchaseorder_document', NULL, 'purchase.report_purchaseorder_document', 'qweb', 'purchase/report/purchase_order_templates.xml', 'primary', '{"en_US": "<t t-name=\"purchase.report_purchaseorder_document\">\n    <t t-call=\"web.external_layout\">\n        <t t-set=\"o\" t-value=\"o.with_context(lang=o.partner_id.lang)\"/>\n        <t t-set=\"address\">\n            <div t-field=\"o.partner_id\" t-options=\"{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;, &quot;phone&quot;, &quot;vat&quot;], &quot;no_marker&quot;: True, &quot;phone_icons&quot;: True}\"/>\n        </t>\n        <t t-if=\"o.dest_address_id\">\n            <t t-set=\"information_block\">\n                <strong>Shipping address:</strong>\n                <div t-if=\"o.dest_address_id\">\n                    <div t-field=\"o.dest_address_id\" t-options=\"{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;, &quot;phone&quot;], &quot;no_marker&quot;: True, &quot;phone_icons&quot;: True}\" name=\"purchase_shipping_address\"/>\n                </div>\n\n            </t>\n        </t>\n        <div class=\"page\">\n            <div class=\"oe_structure\"/>\n\n            <div class=\"mt-4\">\n                <h2 t-if=\"o.state in [''draft'', ''sent'', ''to approve'']\">Request for Quotation #<span t-field=\"o.name\"/></h2>\n                <h2 t-if=\"o.state in [''purchase'', ''done'']\">Purchase Order #<span t-field=\"o.name\"/></h2>\n                <h2 t-if=\"o.state == ''cancel''\">Cancelled Purchase Order #<span t-field=\"o.name\"/></h2>\n            </div>\n\n            <div id=\"informations\" class=\"row mt-4 mb32\">\n                <div t-if=\"o.user_id\" class=\"col-3 bm-2\">\n                    <strong>Buyer:</strong>\n                    <p t-field=\"o.user_id\" class=\"m-0\"/>\n                </div>\n                <div t-if=\"o.partner_ref\" class=\"col-3 bm-2\">\n                    <strong>Your Order Reference:</strong>\n                    <p t-field=\"o.partner_ref\" class=\"m-0\"/>\n                </div>\n                <div t-if=\"o.state in [''purchase'',''done''] and o.date_approve\" class=\"col-3 bm-2\">\n                    <strong>Order Date:</strong>\n                    <p t-field=\"o.date_approve\" class=\"m-0\"/>\n                </div>\n                <div t-elif=\"o.date_order\" class=\"col-3 bm-2\">\n                    <strong>Order Deadline:</strong>\n                    <p t-field=\"o.date_order\" class=\"m-0\"/>\n                </div>\n            </div>\n\n            <table class=\"table table-sm o_main_table table-borderless mt-4\">\n                <thead style=\"display: table-row-group\">\n                    <tr>\n                        <th name=\"th_description\"><strong>Description</strong></th>\n                        <th name=\"th_date_req\" class=\"text-center\"><strong>Date Req.</strong></th>\n                        <th name=\"th_quantity\" class=\"text-end\"><strong>Qty</strong></th>\n                        <th name=\"th_price_unit\" class=\"text-end\"><strong>Unit Price</strong></th>\n                        <th name=\"th_discount\" class=\"text-end\"><strong>Disc.</strong></th>\n                        <th name=\"th_taxes\" class=\"text-end\"><strong>Taxes</strong></th>\n                        <th name=\"th_subtotal\" class=\"text-end\">\n                            <strong>Amount</strong>\n                        </th>\n                    </tr>\n                </thead>\n                <tbody>\n                    <t t-set=\"current_subtotal\" t-value=\"0\"/>\n                    <t t-foreach=\"o.order_line\" t-as=\"line\">\n                        <t t-set=\"current_subtotal\" t-value=\"current_subtotal + line.price_subtotal\"/>\n\n                        <tr t-att-class=\"''bg-200 fw-bold o_line_section'' if line.display_type == ''line_section'' else ''fst-italic o_line_note'' if line.display_type == ''line_note'' else ''''\">\n                            <t t-if=\"not line.display_type\">\n                                <td id=\"product\">\n                                    <span t-field=\"line.name\"/>\n                                </td>\n                                <td class=\"text-center\">\n                                    <span t-field=\"line.date_planned\"/>\n                                </td>\n                                <td class=\"text-end\">\n                                    <span t-field=\"line.product_qty\"/>\n                                    <span t-field=\"line.product_uom.name\" groups=\"uom.group_uom\"/>\n                                    <span t-if=\"line.product_packaging_id\">\n                                        (<span t-field=\"line.product_packaging_qty\" t-options=\"{&quot;widget&quot;: &quot;integer&quot;}\"/> <span t-field=\"line.product_packaging_id\"/>)\n                                    </span>\n                                </td>\n                                <td class=\"text-end\">\n                                    <span t-field=\"line.price_unit\"/>\n                                </td>\n                                <td class=\"text-end\">\n                                    <span class=\"text-align-bottom\"><span t-field=\"line.discount\"/>%</span>\n                                </td>\n                                <t t-set=\"taxes\" t-value=\"'', ''.join([(tax.invoice_label or tax.name) for tax in line.taxes_id])\"/>\n                                <td name=\"td_taxes\" t-attf-class=\"text-end {{ ''text-nowrap'' if len(taxes) &lt; 10 else '''' }}\">\n                                    <span t-out=\"taxes\">Tax 15%</span>\n                                </td>\n                                <td class=\"text-end\">\n                                    <span t-field=\"line.price_subtotal\" t-options=\"{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: o.currency_id}\"/>\n                                </td>\n                            </t>\n                            <t t-if=\"line.display_type == ''line_section''\">\n                                <td colspan=\"99\" id=\"section\">\n                                    <span t-field=\"line.name\"/>\n                                </td>\n                                <t t-set=\"current_section\" t-value=\"line\"/>\n                                <t t-set=\"current_subtotal\" t-value=\"0\"/>\n                            </t>\n                            <t t-if=\"line.display_type == ''line_note''\">\n                                <td colspan=\"99\" id=\"note\">\n                                    <span t-field=\"line.name\"/>\n                                </td>\n                            </t>\n                        </tr>\n                        <t t-if=\"current_section and (line_last or o.order_line[line_index+1].display_type == ''line_section'')\">\n                            <tr class=\"is-subtotal text-end\">\n                                <td colspan=\"99\" id=\"subtotal\">\n                                    <strong class=\"mr16\">Subtotal</strong>\n                                    <span t-esc=\"current_subtotal\" t-options=\"{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: o.currency_id}\"/>\n                                </td>\n                            </tr>\n                        </t>\n                    </t>\n                </tbody>\n            </table>\n\n            <div id=\"total\" class=\"row justify-content-end\">\n                <div class=\"col-4\">\n                    <table class=\"table table-sm table-borderless\">\n                        <t t-set=\"tax_totals\" t-value=\"o.tax_totals\"/>\n                        <t t-call=\"purchase.document_tax_totals\"/>\n                    </table>\n                </div>\n            </div>\n\n            <p t-field=\"o.notes\" class=\"mt-4\"/>\n            <div class=\"oe_structure\"/>\n        </div>\n    </t>\n</t>"}', '<?xml version="1.0"?>
<t t-name="purchase.report_purchaseorder_document">
    <t t-call="web.external_layout">
        <t t-set="o" t-value="o.with_context(lang=o.partner_id.lang)"/>
        <t t-set="address">
            <div t-field="o.partner_id" t-options="{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;, &quot;phone&quot;, &quot;vat&quot;], &quot;no_marker&quot;: True, &quot;phone_icons&quot;: True}"/>
        </t>
        <t t-if="o.dest_address_id">
            <t t-set="information_block">
                <strong>Shipping address:</strong>
                <div t-if="o.dest_address_id">
                    <div t-field="o.dest_address_id" t-options="{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;, &quot;phone&quot;], &quot;no_marker&quot;: True, &quot;phone_icons&quot;: True}" name="purchase_shipping_address"/>
                </div>

            </t>
        </t>
        <div class="page">
            <div class="oe_structure"/>

            <div class="mt-4">
                <h2 t-if="o.state in [''draft'', ''sent'', ''to approve'']">Request for Quotation #<span t-field="o.name"/></h2>
                <h2 t-if="o.state in [''purchase'', ''done'']">Purchase Order #<span t-field="o.name"/></h2>
                <h2 t-if="o.state == ''cancel''">Cancelled Purchase Order #<span t-field="o.name"/></h2>
            </div>

            <div id="informations" class="row mt-4 mb32">
                <div t-if="o.user_id" class="col-3 bm-2">
                    <strong>Buyer:</strong>
                    <p t-field="o.user_id" class="m-0"/>
                </div>
                <div t-if="o.partner_ref" class="col-3 bm-2">
                    <strong>Your Order Reference:</strong>
                    <p t-field="o.partner_ref" class="m-0"/>
                </div>
                <div t-if="o.state in [''purchase'',''done''] and o.date_approve" class="col-3 bm-2">
                    <strong>Order Date:</strong>
                    <p t-field="o.date_approve" class="m-0"/>
                </div>
                <div t-elif="o.date_order" class="col-3 bm-2">
                    <strong>Order Deadline:</strong>
                    <p t-field="o.date_order" class="m-0"/>
                </div>
            </div>

            <table class="table table-sm o_main_table table-borderless mt-4">
                <thead style="display: table-row-group">
                    <tr>
                        <th name="th_description"><strong>Description</strong></th>
                        <th name="th_date_req" class="text-center"><strong>Date Req.</strong></th>
                        <th name="th_quantity" class="text-end"><strong>Qty</strong></th>
                        <th name="th_price_unit" class="text-end"><strong>Unit Price</strong></th>
                        <th name="th_discount" class="text-end"><strong>Disc.</strong></th>
                        <th name="th_taxes" class="text-end"><strong>Taxes</strong></th>
                        <th name="th_subtotal" class="text-end">
                            <strong>Amount</strong>
                        </th>
                    </tr>
                </thead>
                <tbody>
                    <t t-set="current_subtotal" t-value="0"/>
                    <t t-foreach="o.order_line" t-as="line">
                        <t t-set="current_subtotal" t-value="current_subtotal + line.price_subtotal"/>

                        <tr t-att-class="''bg-200 fw-bold o_line_section'' if line.display_type == ''line_section'' else ''fst-italic o_line_note'' if line.display_type == ''line_note'' else ''''">
                            <t t-if="not line.display_type">
                                <td id="product">
                                    <span t-field="line.name"/>
                                </td>
                                <td class="text-center">
                                    <span t-field="line.date_planned"/>
                                </td>
                                <td class="text-end">
                                    <span t-field="line.product_qty"/>
                                    <span t-field="line.product_uom.name" groups="uom.group_uom"/>
                                    <span t-if="line.product_packaging_id">
                                        (<span t-field="line.product_packaging_qty" t-options="{&quot;widget&quot;: &quot;integer&quot;}"/> <span t-field="line.product_packaging_id"/>)
                                    </span>
                                </td>
                                <td class="text-end">
                                    <span t-field="line.price_unit"/>
                                </td>
                                <td class="text-end">
                                    <span class="text-align-bottom"><span t-field="line.discount"/>%</span>
                                </td>
                                <t t-set="taxes" t-value="'', ''.join([(tax.invoice_label or tax.name) for tax in line.taxes_id])"/>
                                <td name="td_taxes" t-attf-class="text-end {{ ''text-nowrap'' if len(taxes) &lt; 10 else '''' }}">
                                    <span t-out="taxes">Tax 15%</span>
                                </td>
                                <td class="text-end">
                                    <span t-field="line.price_subtotal" t-options="{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: o.currency_id}"/>
                                </td>
                            </t>
                            <t t-if="line.display_type == ''line_section''">
                                <td colspan="99" id="section">
                                    <span t-field="line.name"/>
                                </td>
                                <t t-set="current_section" t-value="line"/>
                                <t t-set="current_subtotal" t-value="0"/>
                            </t>
                            <t t-if="line.display_type == ''line_note''">
                                <td colspan="99" id="note">
                                    <span t-field="line.name"/>
                                </td>
                            </t>
                        </tr>
                        <t t-if="current_section and (line_last or o.order_line[line_index+1].display_type == ''line_section'')">
                            <tr class="is-subtotal text-end">
                                <td colspan="99" id="subtotal">
                                    <strong class="mr16">Subtotal</strong>
                                    <span t-esc="current_subtotal" t-options="{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: o.currency_id}"/>
                                </td>
                            </tr>
                        </t>
                    </t>
                </tbody>
            </table>

            <div id="total" class="row justify-content-end">
                <div class="col-4">
                    <table class="table table-sm table-borderless">
                        <t t-set="tax_totals" t-value="o.tax_totals"/>
                        <t t-call="purchase.document_tax_totals"/>
                    </table>
                </div>
            </div>

            <p t-field="o.notes" class="mt-4"/>
            <div class="oe_structure"/>
        </div>
    </t>
</t>

', false, true, '2026-05-10 01:12:29.662147', '2026-05-10 01:12:29.662147', false);
INSERT INTO public.ir_ui_view VALUES (1197, 25, 548, 1, 1, 'Show Requests for Quotation / Purchase Orders', NULL, 'purchase.portal_my_home_purchase', 'qweb', 'purchase/views/portal_templates.xml', 'extension', '{"en_US": "<data name=\"Show Requests for Quotation / Purchase Orders\" customize_show=\"True\" inherit_id=\"portal.portal_my_home\" priority=\"25\">\n    <xpath expr=\"//div[hasclass(''o_portal_docs'')]\" position=\"before\">\n          <t t-set=\"portal_vendor_category_enable\" t-value=\"True\"/>\n      </xpath>\n      <div id=\"portal_vendor_category\" position=\"inside\">\n          <t t-call=\"portal.portal_docs_entry\">\n              <t t-set=\"icon\" t-value=\"''/purchase/static/src/img/rfq.svg''\"/>\n              <t t-set=\"text\">Follow your Requests for Quotation</t>\n              <t t-set=\"title\">Requests for Quotation</t>\n              <t t-set=\"url\" t-value=\"''/my/rfq''\"/>\n              <t t-set=\"placeholder_count\" t-value=\"''rfq_count''\"/>\n          </t>\n          <t t-call=\"portal.portal_docs_entry\">\n              <t t-set=\"icon\" t-value=\"''/purchase/static/src/img/calculator.svg''\"/>\n              <t t-set=\"text\">Follow orders you have to fulfill</t>\n              <t t-set=\"title\">Our Orders</t>\n              <t t-set=\"url\" t-value=\"''/my/purchase''\"/>\n              <t t-set=\"placeholder_count\" t-value=\"''purchase_count''\"/>\n          </t>\n      </div>\n  </data>"}', '<?xml version="1.0"?>
<data name="Show Requests for Quotation / Purchase Orders" customize_show="True" inherit_id="portal.portal_my_home" priority="25">
    <xpath expr="//div[hasclass(''o_portal_docs'')]" position="before">
          <t t-set="portal_vendor_category_enable" t-value="True"/>
      </xpath>
      <div id="portal_vendor_category" position="inside">
          <t t-call="portal.portal_docs_entry">
              <t t-set="icon" t-value="''/purchase/static/src/img/rfq.svg''"/>
              <t t-set="text">Follow your Requests for Quotation</t>
              <t t-set="title">Requests for Quotation</t>
              <t t-set="url" t-value="''/my/rfq''"/>
              <t t-set="placeholder_count" t-value="''rfq_count''"/>
          </t>
          <t t-call="portal.portal_docs_entry">
              <t t-set="icon" t-value="''/purchase/static/src/img/calculator.svg''"/>
              <t t-set="text">Follow orders you have to fulfill</t>
              <t t-set="title">Our Orders</t>
              <t t-set="url" t-value="''/my/purchase''"/>
              <t t-set="placeholder_count" t-value="''purchase_count''"/>
          </t>
      </div>
  </data>

  ', false, true, '2026-05-10 01:12:29.662147', '2026-05-10 01:12:29.662147', true);
INSERT INTO public.ir_ui_view VALUES (1198, 16, NULL, 1, 1, 'My Requests For Quotation', NULL, 'purchase.portal_my_purchase_rfqs', 'qweb', 'purchase/views/portal_templates.xml', 'primary', '{"en_US": "<t name=\"My Requests For Quotation\" t-name=\"purchase.portal_my_purchase_rfqs\">\n      <t t-call=\"portal.portal_layout\">\n          <t t-set=\"breadcrumbs_searchbar\" t-value=\"True\"/>\n\n          <t t-call=\"portal.portal_searchbar\">\n              <t t-set=\"title\">Requests For Quotation</t>\n          </t>\n          <t t-if=\"not rfqs\">\n              <p class=\"alert alert-warning\">There are currently no requests for quotation for your account.</p>\n          </t>\n          <t t-if=\"rfqs\" t-call=\"portal.portal_table\">\n              <thead>\n                  <tr class=\"active\">\n                    <th>\n                        <span class=\"d-none d-md-inline\">Request for Quotation #</span>\n                        <span class=\"d-block d-md-none\">Ref.</span>\n                    </th>\n                      <th class=\"text-end\">Order Deadline</th>\n                      <th class=\"text-end\">Total</th>\n                  </tr>\n              </thead>\n              <t t-foreach=\"rfqs\" t-as=\"rfq\">\n                  <tr>\n                      <td><a t-att-href=\"rfq.get_portal_url()\"><t t-esc=\"rfq.name\"/></a></td>\n                      <td class=\"text-end\">\n                          <span t-field=\"rfq.date_order\" t-options=\"{''widget'': ''date''}\"/>&amp;nbsp;\n                          <span class=\"d-none d-md-inline\" t-field=\"rfq.date_order\" t-options=\"{''time_only'': True}\"/>\n                      </td>\n                      <td class=\"text-end\">\n                          <span t-field=\"rfq.amount_total\"/>\n                      </td>\n                  </tr>\n              </t>\n          </t>\n      </t>\n  </t>"}', '<?xml version="1.0"?>
<t name="My Requests For Quotation" t-name="purchase.portal_my_purchase_rfqs">
      <t t-call="portal.portal_layout">
          <t t-set="breadcrumbs_searchbar" t-value="True"/>

          <t t-call="portal.portal_searchbar">
              <t t-set="title">Requests For Quotation</t>
          </t>
          <t t-if="not rfqs">
              <p class="alert alert-warning">There are currently no requests for quotation for your account.</p>
          </t>
          <t t-if="rfqs" t-call="portal.portal_table">
              <thead>
                  <tr class="active">
                    <th>
                        <span class="d-none d-md-inline">Request for Quotation #</span>
                        <span class="d-block d-md-none">Ref.</span>
                    </th>
                      <th class="text-end">Order Deadline</th>
                      <th class="text-end">Total</th>
                  </tr>
              </thead>
              <t t-foreach="rfqs" t-as="rfq">
                  <tr>
                      <td><a t-att-href="rfq.get_portal_url()"><t t-esc="rfq.name"/></a></td>
                      <td class="text-end">
                          <span t-field="rfq.date_order" t-options="{''widget'': ''date''}"/>&amp;nbsp;
                          <span class="d-none d-md-inline" t-field="rfq.date_order" t-options="{''time_only'': True}"/>
                      </td>
                      <td class="text-end">
                          <span t-field="rfq.amount_total"/>
                      </td>
                  </tr>
              </t>
          </t>
      </t>
  </t>

  ', false, true, '2026-05-10 01:12:29.662147', '2026-05-10 01:12:29.662147', false);
INSERT INTO public.ir_ui_view VALUES (1199, 16, NULL, 1, 1, 'My Purchase Orders', NULL, 'purchase.portal_my_purchase_orders', 'qweb', 'purchase/views/portal_templates.xml', 'primary', '{"en_US": "<t name=\"My Purchase Orders\" t-name=\"purchase.portal_my_purchase_orders\">\n      <t t-call=\"portal.portal_layout\">\n          <t t-set=\"breadcrumbs_searchbar\" t-value=\"True\"/>\n\n          <t t-call=\"portal.portal_searchbar\">\n              <t t-set=\"title\">Purchase Orders</t>\n          </t>\n          <t t-if=\"not orders\">\n              <p class=\"alert alert-warning\">There are currently no purchase orders for your account.</p>\n          </t>\n          <t t-if=\"orders\" t-call=\"portal.portal_table\">\n              <thead>\n                  <tr class=\"active\">\n                      <th>\n                          <span class=\"d-none d-md-inline\">Purchase Order #</span>\n                          <span class=\"d-block d-md-none\">Ref.</span>\n                      </th>\n                      <th class=\"text-end\">\n                          <span class=\"d-none d-md-inline\">Confirmation Date</span>\n                          <span class=\"d-block d-md-none\">Confirmation</span>\n                      </th>\n                      <th class=\"text-center\"/>\n                      <th class=\"text-end\">Total</th>\n                  </tr>\n              </thead>\n              <t t-foreach=\"orders\" t-as=\"order\">\n                  <tr>\n                      <td><a t-att-href=\"order.get_portal_url()\"><t t-esc=\"order.name\"/></a></td>\n                      <td class=\"text-end\">\n                          <span t-field=\"order.date_approve\" t-options=\"{''widget'': ''date''}\"/>&amp;nbsp;\n                          <span class=\"d-none d-md-inline\" t-field=\"order.date_approve\" t-options=\"{''time_only'': True}\"/>\n                      </td>\n                      <td class=\"text-center\">\n                          <span t-if=\"order.invoice_status == ''to invoice''\" class=\"badge rounded-pill text-bg-info\">\n                              <i class=\"fa fa-fw fa-file-text\" role=\"img\" aria-label=\"Waiting for Bill\" title=\"Waiting for Bill\"/><span class=\"d-none d-md-inline\"> Waiting for Bill</span>\n                          </span>\n                          <span t-if=\"order.state == ''cancel''\" class=\"badge rounded-pill text-bg-secondary\">\n                              <i class=\"fa fa-fw fa-remove\" role=\"img\" aria-label=\"Cancelled\" title=\"Cancelled\"/><span class=\"d-none d-md-inline\"> Cancelled</span>\n                          </span>\n                          <span t-if=\"order.state == ''done''\" class=\"badge rounded-pill text-bg-success\">\n                              <i class=\"fa fa-fw fa-check\" role=\"img\" aria-label=\"Done\" title=\"Done\"/><span class=\"d-none d-md-inline\"> Done</span>\n                          </span>\n                      </td>\n                      <td class=\"text-end\"><span t-field=\"order.amount_total\"/></td>\n                  </tr>\n              </t>\n          </t>\n      </t>\n  </t>"}', '<?xml version="1.0"?>
<t name="My Purchase Orders" t-name="purchase.portal_my_purchase_orders">
      <t t-call="portal.portal_layout">
          <t t-set="breadcrumbs_searchbar" t-value="True"/>

          <t t-call="portal.portal_searchbar">
              <t t-set="title">Purchase Orders</t>
          </t>
          <t t-if="not orders">
              <p class="alert alert-warning">There are currently no purchase orders for your account.</p>
          </t>
          <t t-if="orders" t-call="portal.portal_table">
              <thead>
                  <tr class="active">
                      <th>
                          <span class="d-none d-md-inline">Purchase Order #</span>
                          <span class="d-block d-md-none">Ref.</span>
                      </th>
                      <th class="text-end">
                          <span class="d-none d-md-inline">Confirmation Date</span>
                          <span class="d-block d-md-none">Confirmation</span>
                      </th>
                      <th class="text-center"/>
                      <th class="text-end">Total</th>
                  </tr>
              </thead>
              <t t-foreach="orders" t-as="order">
                  <tr>
                      <td><a t-att-href="order.get_portal_url()"><t t-esc="order.name"/></a></td>
                      <td class="text-end">
                          <span t-field="order.date_approve" t-options="{''widget'': ''date''}"/>&amp;nbsp;
                          <span class="d-none d-md-inline" t-field="order.date_approve" t-options="{''time_only'': True}"/>
                      </td>
                      <td class="text-center">
                          <span t-if="order.invoice_status == ''to invoice''" class="badge rounded-pill text-bg-info">
                              <i class="fa fa-fw fa-file-text" role="img" aria-label="Waiting for Bill" title="Waiting for Bill"/><span class="d-none d-md-inline"> Waiting for Bill</span>
                          </span>
                          <span t-if="order.state == ''cancel''" class="badge rounded-pill text-bg-secondary">
                              <i class="fa fa-fw fa-remove" role="img" aria-label="Cancelled" title="Cancelled"/><span class="d-none d-md-inline"> Cancelled</span>
                          </span>
                          <span t-if="order.state == ''done''" class="badge rounded-pill text-bg-success">
                              <i class="fa fa-fw fa-check" role="img" aria-label="Done" title="Done"/><span class="d-none d-md-inline"> Done</span>
                          </span>
                      </td>
                      <td class="text-end"><span t-field="order.amount_total"/></td>
                  </tr>
              </t>
          </t>
      </t>
  </t>

  ', false, true, '2026-05-10 01:12:29.662147', '2026-05-10 01:12:29.662147', false);
INSERT INTO public.ir_ui_view VALUES (1200, 16, 563, 1, 1, 'Purchase Order', NULL, 'purchase.portal_my_purchase_order', 'qweb', 'purchase/views/portal_templates.xml', 'primary', '{"en_US": "<data name=\"Purchase Order\" inherit_id=\"portal.portal_sidebar\" primary=\"True\">\n      <xpath expr=\"//div[hasclass(''o_portal_sidebar'')]\" position=\"inside\">\n          <t t-set=\"o_portal_fullwidth_alert\" groups=\"purchase.group_purchase_manager\">\n              <t t-call=\"portal.portal_back_in_edit_mode\">\n                  <t t-set=\"backend_url\" t-value=\"''/web#model=%s&amp;id=%s&amp;action=%s&amp;view_type=form'' % (order._name, order.id, order.env.ref(''purchase.purchase_rfq'').id)\"/>\n              </t>\n          </t>\n\n          <div class=\"row o_portal_purchase_sidebar\">\n              <!-- Sidebar -->\n              <t t-call=\"portal.portal_record_sidebar\">\n                  <t t-set=\"classes\" t-value=\"''col-lg-3 col-xl-4 d-print-none''\"/>\n\n                  <t t-set=\"title\">\n                      <h2 t-field=\"order.amount_total\" data-id=\"total_amount\"/>\n                  </t>\n                  <t t-set=\"entries\">\n                      <div class=\"d-flex flex-column gap-4\">\n                          <div class=\"flex-grow-1 order-md-last order-lg-first\">\n                              <div class=\"o_download_pdf btn-toolbar flex-sm-nowrap\">\n                                  <div class=\"btn-group flex-grow-1 mb-1\">\n                                      <a class=\"btn btn-secondary btn-block o_print_btn o_portal_invoice_print\" t-att-href=\"order.get_portal_url(report_type=''pdf'')\" id=\"print_invoice_report\" title=\"View Details\" target=\"_blank\"><i class=\"fa fa-print\"/> View Details</a>\n                                  </div>\n                              </div>\n                          </div>\n\n                          <div class=\"navspy flex-grow-1 ps-0\" t-ignore=\"true\" role=\"complementary\">\n                              <ul class=\"nav flex-column bs-sidenav\"/>\n                          </div>\n\n                          <div t-if=\"order.user_id\">\n                              <h6><small class=\"text-muted\">Purchase Representative</small></h6>\n                              <div class=\"o_portal_contact_details d-flex flex-column gap-2\">\n                                <div class=\"d-flex justify-content-start align-items-center gap-2\">\n                                    <img class=\"o_avatar o_portal_contact_img rounded\" t-att-src=\"image_data_uri(order.user_id.avatar_128)\" alt=\"Contact\"/>\n                                    <div>\n                                        <h6 class=\"mb-0\" t-out=\"order.user_id.name\"/>\n                                        <a href=\"#discussion\" class=\"small fw-bold\">Send message</a>\n                                    </div>\n                                </div>\n                                <div t-field=\"order.user_id\" t-options=\"{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;phone&quot;], &quot;no_marker&quot;: False}\"/>\n                            </div>\n                          </div>\n                      </div>\n                  </t>\n              </t>\n\n              <!-- Page content -->\n              <div id=\"quote_content\" class=\"o_portal_content col-12 col-lg-9 col-xl-8\">\n\n                  <!-- status messages -->\n                  <div t-if=\"order.state == ''cancel''\" class=\"alert alert-danger alert-dismissable d-print-none\" role=\"alert\">\n                      <button type=\"button\" class=\"btn-close\" data-bs-dismiss=\"alert\" aria-label=\"close\"/>\n                      <strong>This purchase has been canceled.</strong>\n                  </div>\n\n                  <!-- main content -->\n                  <div id=\"portal_purchase_content\">\n                      <div t-call=\"purchase.purchase_order_portal_content\"/>\n                  </div>\n\n                  <!-- chatter -->\n                  <hr/>\n                  <div id=\"purchase_order_communication\">\n                      <h3>Communication history</h3>\n                      <t t-call=\"portal.message_thread\"/>\n                  </div>\n              </div><!-- // #quote_content -->\n          </div>\n      </xpath>\n  <xpath expr=\".\" position=\"attributes\"><attribute name=\"t-name\">purchase.portal_my_purchase_order</attribute></xpath></data>"}', '<?xml version="1.0"?>
<data name="Purchase Order" inherit_id="portal.portal_sidebar" primary="True">
      <xpath expr="//div[hasclass(''o_portal_sidebar'')]" position="inside">
          <t t-set="o_portal_fullwidth_alert" groups="purchase.group_purchase_manager">
              <t t-call="portal.portal_back_in_edit_mode">
                  <t t-set="backend_url" t-value="''/web#model=%s&amp;id=%s&amp;action=%s&amp;view_type=form'' % (order._name, order.id, order.env.ref(''purchase.purchase_rfq'').id)"/>
              </t>
          </t>

          <div class="row o_portal_purchase_sidebar">
              <!-- Sidebar -->
              <t t-call="portal.portal_record_sidebar">
                  <t t-set="classes" t-value="''col-lg-3 col-xl-4 d-print-none''"/>

                  <t t-set="title">
                      <h2 t-field="order.amount_total" data-id="total_amount"/>
                  </t>
                  <t t-set="entries">
                      <div class="d-flex flex-column gap-4">
                          <div class="flex-grow-1 order-md-last order-lg-first">
                              <div class="o_download_pdf btn-toolbar flex-sm-nowrap">
                                  <div class="btn-group flex-grow-1 mb-1">
                                      <a class="btn btn-secondary btn-block o_print_btn o_portal_invoice_print" t-att-href="order.get_portal_url(report_type=''pdf'')" id="print_invoice_report" title="View Details" target="_blank"><i class="fa fa-print"/> View Details</a>
                                  </div>
                              </div>
                          </div>

                          <div class="navspy flex-grow-1 ps-0" t-ignore="true" role="complementary">
                              <ul class="nav flex-column bs-sidenav"/>
                          </div>

                          <div t-if="order.user_id">
                              <h6><small class="text-muted">Purchase Representative</small></h6>
                              <div class="o_portal_contact_details d-flex flex-column gap-2">
                                <div class="d-flex justify-content-start align-items-center gap-2">
                                    <img class="o_avatar o_portal_contact_img rounded" t-att-src="image_data_uri(order.user_id.avatar_128)" alt="Contact"/>
                                    <div>
                                        <h6 class="mb-0" t-out="order.user_id.name"/>
                                        <a href="#discussion" class="small fw-bold">Send message</a>
                                    </div>
                                </div>
                                <div t-field="order.user_id" t-options="{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;phone&quot;], &quot;no_marker&quot;: False}"/>
                            </div>
                          </div>
                      </div>
                  </t>
              </t>

              <!-- Page content -->
              <div id="quote_content" class="o_portal_content col-12 col-lg-9 col-xl-8">

                  <!-- status messages -->
                  <div t-if="order.state == ''cancel''" class="alert alert-danger alert-dismissable d-print-none" role="alert">
                      <button type="button" class="btn-close" data-bs-dismiss="alert" aria-label="close"/>
                      <strong>This purchase has been canceled.</strong>
                  </div>

                  <!-- main content -->
                  <div id="portal_purchase_content">
                      <div t-call="purchase.purchase_order_portal_content"/>
                  </div>

                  <!-- chatter -->
                  <hr/>
                  <div id="purchase_order_communication">
                      <h3>Communication history</h3>
                      <t t-call="portal.message_thread"/>
                  </div>
              </div><!-- // #quote_content -->
          </div>
      </xpath>
  <xpath expr="." position="attributes"><attribute name="t-name">purchase.portal_my_purchase_order</attribute></xpath></data>

  ', false, true, '2026-05-10 01:12:29.662147', '2026-05-10 01:12:29.662147', false);
INSERT INTO public.ir_ui_view VALUES (1201, 16, NULL, 1, 1, 'Purchase Order Portal Content', NULL, 'purchase.purchase_order_portal_content', 'qweb', 'purchase/views/portal_templates.xml', 'primary', '{"en_US": "<t name=\"Purchase Order Portal Content\" t-name=\"purchase.purchase_order_portal_content\">\n      <!-- Intro -->\n      <div id=\"introduction\" class=\"mt-5 mt-lg-0 pb-2 pt-0\">\n        <h2 class=\"my-0\">\n          <t t-if=\"order.state in [''draft'', ''sent'']\">Request for Quotation</t>\n          <t t-else=\"1\">\n            Purchase Order\n          </t>\n          <em t-esc=\"order.name\"/>\n        </h2>\n      </div>\n\n      <div>\n          <!-- Informations -->\n          <div id=\"informations\">\n              <div class=\"row\" id=\"po_date\">\n                  <div class=\"mb-3 col-6\">\n                    <t t-if=\"order.state in [''draft'', ''sent'']\">\n                      <strong>Request For Quotation Date:</strong>\n                    </t>\n                    <t t-if=\"order.state in [''purchase'', ''done'', ''cancel'']\">\n                      <strong>Order Date:</strong>\n                    </t>\n                    <span t-field=\"order.date_order\" t-options=\"{&quot;widget&quot;: &quot;date&quot;}\"/>\n                  </div>\n              </div>\n              <div class=\"row\">\n                  <div class=\"col-lg-6\">\n                    <strong class=\"d-block mb-1\">From:</strong>\n                    <address t-field=\"order.company_id.partner_id\" t-options=\"{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;], &quot;no_marker&quot;: True}\"/>\n                    <strong>Confirmation Date:</strong> <span t-field=\"order.date_approve\" t-options=\"{&quot;widget&quot;: &quot;date&quot;}\"/><br/>\n                    <div t-att-class=\"''d-inline'' if order.date_planned else ''d-none''\">\n                      <strong>Receipt Date:</strong><span class=\"ms-1\" t-field=\"order.date_planned\" t-options=\"{&quot;widget&quot;: &quot;date&quot;}\"/>\n                    </div>\n                  </div>\n              </div>\n\n              <t t-set=\"invoices\" t-value=\"[i for i in order.invoice_ids if i.state not in [''draft'', ''cancel'']]\"/>\n              <div t-if=\"invoices\" class=\"row\">\n                  <div class=\"col\">\n                      <strong class=\"d-block mb-1\">Invoices</strong>\n                      <ul class=\"list-group mb-4\">\n                          <t t-foreach=\"invoices\" t-as=\"i\">\n                              <t t-set=\"report_url\" t-value=\"i.get_portal_url(report_type=''pdf'', download=True)\"/>\n                              <div class=\"d-flex flex-wrap align-items-center justify-content-between\">\n                                  <div>\n                                      <a t-att-href=\"report_url\">\n                                          <span t-esc=\"i.name\"/>\n                                      </a>\n                                      <div class=\"small d-lg-inline-block\">Date: <span class=\"text-muted\" t-field=\"i.invoice_date\"/></div>\n                                  </div>\n                                  <span t-if=\"i.payment_state in (''paid'', ''in_payment'')\" class=\"badge text-bg-success small\"><i class=\"fa fa-fw fa-check\"/>Paid</span>\n                                  <span t-elif=\"i.payment_state == ''reversed''\" class=\"badge text-bg-success small\"><i class=\"fa fa-fw fa-check\"/>Reversed</span>\n                                  <span t-else=\"\" class=\"small badge text-bg-primary\"><i class=\"fa fa-fw fa-clock-o\"/>Waiting Payment</span>\n                              </div>\n                          </t>\n                      </ul>\n                  </div>\n              </div>\n          </div>\n\n          <section id=\"details\" style=\"page-break-inside: auto;\" class=\"mt32\">\n              <h3 id=\"details\">Pricing</h3>\n\n              <div class=\"table-responsive\">\n                <table t-att-data-order-id=\"order.id\" t-att-data-token=\"order.access_token\" class=\"table table-sm\" id=\"purchase_order_table\">\n                    <thead class=\"bg-100\">\n                        <tr>\n                            <th class=\"text-start\">Products</th>\n                            <th class=\"text-end\">Quantity</th>\n                            <th t-if=\"update_dates\" class=\"text-end\">Scheduled Date</th>\n                            <th t-if=\"not update_dates and order.state in [''purchase'', ''done'']\" t-attf-class=\"text-end {{ ''d-none d-sm-table-cell'' if report_type == ''html'' else '''' }}\">Unit Price</th>\n                            <th t-if=\"not update_dates and order.state in [''purchase'', ''done'']\" t-attf-class=\"text-end {{ ''d-none d-md-table-cell'' if report_type == ''html'' else '''' }}\">\n                                <span>Taxes</span>\n                            </th>\n                            <th class=\"text-end\" t-if=\"order.state in [''purchase'', ''done'']\">\n                                <span>Amount</span>\n                            </th>\n                        </tr>\n                    </thead>\n                    <tbody class=\"purchase_tbody\">\n\n                          <t t-set=\"current_subtotal\" t-value=\"0\"/>\n\n                          <t t-foreach=\"order.order_line\" t-as=\"line\">\n\n                              <t t-set=\"current_subtotal\" t-value=\"current_subtotal + line.price_subtotal\"/>\n\n                            <tr t-att-class=\"''bg-200 fw-bold o_line_section'' if line.display_type == ''line_section'' else ''fst-italic text-break'' if line.display_type == ''line_note'' else ''''\">\n                                <t t-if=\"not line.display_type\">\n                                    <td id=\"product_name\">\n                                        <img t-att-src=\"image_data_uri(resize_to_48(line.product_id.image_1024))\" alt=\"Product\" class=\"d-none d-lg-inline\"/>\n                                        <span t-field=\"line.name\"/>\n                                    </td>\n                                    <td class=\"text-end\">\n                                        <div id=\"quote_qty\">\n                                            <span t-field=\"line.product_qty\"/>\n                                            <span t-field=\"line.product_uom\" groups=\"uom.group_uom\"/>\n                                        </div>\n                                    </td>\n                                    <td t-if=\"update_dates\" class=\"text-end\">\n                                        <div class=\"container\">\n                                          <div class=\"mb-3\">\n                                            <div class=\"input-group date\">\n                                                <input type=\"text\" class=\"form-control datetimepicker-input o-purchase-datetimepicker text-end\" t-att-data-access-token=\"order.access_token\" t-att-data-order-id=\"order.id\" t-att-data-line-id=\"line.id\" t-att-data-value=\"line.date_planned.isoformat()\"/>\n                                            </div>\n                                          </div>\n                                        </div>\n                                    </td>\n                                    <td t-if=\"not update_dates and order.state in [''purchase'', ''done'']\" t-attf-class=\"text-end {{ ''d-none d-sm-table-cell'' if report_type == ''html'' else '''' }}\">\n                                        <div t-field=\"line.price_unit\" class=\"text-end\"/>\n                                    </td>\n                                    <td t-if=\"not update_dates and order.state in [''purchase'', ''done'']\" t-attf-class=\"text-end {{ ''d-none d-md-table-cell'' if report_type == ''html'' else '''' }}\">\n                                        <span t-esc=\"'', ''.join(map(lambda x: (x.description or x.name), line.taxes_id))\"/>\n                                    </td>\n                                    <td class=\"text-end\" t-if=\"not update_dates and order.state in [''purchase'', ''done'']\">\n                                        <span class=\"oe_order_line_price_subtotal\" t-field=\"line.price_subtotal\"/>\n                                    </td>\n                                </t>\n                                <t t-if=\"line.display_type == ''line_section''\">\n                                    <td colspan=\"99\">\n                                        <span t-field=\"line.name\"/>\n                                    </td>\n                                    <t t-set=\"current_section\" t-value=\"line\"/>\n                                    <t t-set=\"current_subtotal\" t-value=\"0\"/>\n                                </t>\n                                <t t-if=\"line.display_type == ''line_note''\">\n                                    <td colspan=\"99\">\n                                        <span t-field=\"line.name\"/>\n                                    </td>\n                                </t>\n                            </tr>\n\n                            <t t-if=\"current_section and (line_last or order.order_line[line_index+1].display_type == ''line_section'') and order.state in [''purchase'', ''done'']\">\n                                <tr class=\"is-subtotal text-end\">\n                                    <td colspan=\"99\">\n                                        <strong class=\"mr16\">Subtotal</strong>\n                                        <span t-esc=\"current_subtotal\" t-options=\"{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: order.currency_id}\"/>\n                                    </td>\n                                </tr>\n                            </t>\n                        </t>\n                    </tbody>\n                </table>\n              </div>\n\n              <div id=\"total\" t-if=\"order.state in [''purchase'', ''done'']\" class=\"row\" name=\"total\" style=\"page-break-inside: avoid;\">\n                  <div t-attf-class=\"#{''col-4'' if report_type != ''html'' else ''col-sm-7 col-md-5''} ms-auto\">\n                      <t t-call=\"purchase.purchase_order_portal_content_totals_table\"/>\n                  </div>\n              </div>\n          </section>\n\n          <section id=\"terms\" class=\"mt-5\" t-if=\"order.notes\">\n              <h3 class=\"\">Terms &amp; Conditions</h3>\n              <hr class=\"mt-0 mb-1\"/>\n              <em t-field=\"order.notes\"/>\n          </section>\n\n          <section class=\"mt-5\" t-if=\"order.payment_term_id\">\n              <h3 class=\"\">Payment terms</h3>\n              <hr class=\"mt-0 mb-1\"/>\n              <span t-field=\"order.payment_term_id\"/>\n          </section>\n      </div>\n  </t>"}', '<?xml version="1.0"?>
<t name="Purchase Order Portal Content" t-name="purchase.purchase_order_portal_content">
      <!-- Intro -->
      <div id="introduction" class="mt-5 mt-lg-0 pb-2 pt-0">
        <h2 class="my-0">
          <t t-if="order.state in [''draft'', ''sent'']">Request for Quotation</t>
          <t t-else="1">
            Purchase Order
          </t>
          <em t-esc="order.name"/>
        </h2>
      </div>

      <div>
          <!-- Informations -->
          <div id="informations">
              <div class="row" id="po_date">
                  <div class="mb-3 col-6">
                    <t t-if="order.state in [''draft'', ''sent'']">
                      <strong>Request For Quotation Date:</strong>
                    </t>
                    <t t-if="order.state in [''purchase'', ''done'', ''cancel'']">
                      <strong>Order Date:</strong>
                    </t>
                    <span t-field="order.date_order" t-options="{&quot;widget&quot;: &quot;date&quot;}"/>
                  </div>
              </div>
              <div class="row">
                  <div class="col-lg-6">
                    <strong class="d-block mb-1">From:</strong>
                    <address t-field="order.company_id.partner_id" t-options="{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;], &quot;no_marker&quot;: True}"/>
                    <strong>Confirmation Date:</strong> <span t-field="order.date_approve" t-options="{&quot;widget&quot;: &quot;date&quot;}"/><br/>
                    <div t-att-class="''d-inline'' if order.date_planned else ''d-none''">
                      <strong>Receipt Date:</strong><span class="ms-1" t-field="order.date_planned" t-options="{&quot;widget&quot;: &quot;date&quot;}"/>
                    </div>
                  </div>
              </div>

              <t t-set="invoices" t-value="[i for i in order.invoice_ids if i.state not in [''draft'', ''cancel'']]"/>
              <div t-if="invoices" class="row">
                  <div class="col">
                      <strong class="d-block mb-1">Invoices</strong>
                      <ul class="list-group mb-4">
                          <t t-foreach="invoices" t-as="i">
                              <t t-set="report_url" t-value="i.get_portal_url(report_type=''pdf'', download=True)"/>
                              <div class="d-flex flex-wrap align-items-center justify-content-between">
                                  <div>
                                      <a t-att-href="report_url">
                                          <span t-esc="i.name"/>
                                      </a>
                                      <div class="small d-lg-inline-block">Date: <span class="text-muted" t-field="i.invoice_date"/></div>
                                  </div>
                                  <span t-if="i.payment_state in (''paid'', ''in_payment'')" class="badge text-bg-success small"><i class="fa fa-fw fa-check"/>Paid</span>
                                  <span t-elif="i.payment_state == ''reversed''" class="badge text-bg-success small"><i class="fa fa-fw fa-check"/>Reversed</span>
                                  <span t-else="" class="small badge text-bg-primary"><i class="fa fa-fw fa-clock-o"/>Waiting Payment</span>
                              </div>
                          </t>
                      </ul>
                  </div>
              </div>
          </div>

          <section id="details" style="page-break-inside: auto;" class="mt32">
              <h3 id="details">Pricing</h3>

              <div class="table-responsive">
                <table t-att-data-order-id="order.id" t-att-data-token="order.access_token" class="table table-sm" id="purchase_order_table">
                    <thead class="bg-100">
                        <tr>
                            <th class="text-start">Products</th>
                            <th class="text-end">Quantity</th>
                            <th t-if="update_dates" class="text-end">Scheduled Date</th>
                            <th t-if="not update_dates and order.state in [''purchase'', ''done'']" t-attf-class="text-end {{ ''d-none d-sm-table-cell'' if report_type == ''html'' else '''' }}">Unit Price</th>
                            <th t-if="not update_dates and order.state in [''purchase'', ''done'']" t-attf-class="text-end {{ ''d-none d-md-table-cell'' if report_type == ''html'' else '''' }}">
                                <span>Taxes</span>
                            </th>
                            <th class="text-end" t-if="order.state in [''purchase'', ''done'']">
                                <span>Amount</span>
                            </th>
                        </tr>
                    </thead>
                    <tbody class="purchase_tbody">

                          <t t-set="current_subtotal" t-value="0"/>

                          <t t-foreach="order.order_line" t-as="line">

                              <t t-set="current_subtotal" t-value="current_subtotal + line.price_subtotal"/>

                            <tr t-att-class="''bg-200 fw-bold o_line_section'' if line.display_type == ''line_section'' else ''fst-italic text-break'' if line.display_type == ''line_note'' else ''''">
                                <t t-if="not line.display_type">
                                    <td id="product_name">
                                        <img t-att-src="image_data_uri(resize_to_48(line.product_id.image_1024))" alt="Product" class="d-none d-lg-inline"/>
                                        <span t-field="line.name"/>
                                    </td>
                                    <td class="text-end">
                                        <div id="quote_qty">
                                            <span t-field="line.product_qty"/>
                                            <span t-field="line.product_uom" groups="uom.group_uom"/>
                                        </div>
                                    </td>
                                    <td t-if="update_dates" class="text-end">
                                        <div class="container">
                                          <div class="mb-3">
                                            <div class="input-group date">
                                                <input type="text" class="form-control datetimepicker-input o-purchase-datetimepicker text-end" t-att-data-access-token="order.access_token" t-att-data-order-id="order.id" t-att-data-line-id="line.id" t-att-data-value="line.date_planned.isoformat()"/>
                                            </div>
                                          </div>
                                        </div>
                                    </td>
                                    <td t-if="not update_dates and order.state in [''purchase'', ''done'']" t-attf-class="text-end {{ ''d-none d-sm-table-cell'' if report_type == ''html'' else '''' }}">
                                        <div t-field="line.price_unit" class="text-end"/>
                                    </td>
                                    <td t-if="not update_dates and order.state in [''purchase'', ''done'']" t-attf-class="text-end {{ ''d-none d-md-table-cell'' if report_type == ''html'' else '''' }}">
                                        <span t-esc="'', ''.join(map(lambda x: (x.description or x.name), line.taxes_id))"/>
                                    </td>
                                    <td class="text-end" t-if="not update_dates and order.state in [''purchase'', ''done'']">
                                        <span class="oe_order_line_price_subtotal" t-field="line.price_subtotal"/>
                                    </td>
                                </t>
                                <t t-if="line.display_type == ''line_section''">
                                    <td colspan="99">
                                        <span t-field="line.name"/>
                                    </td>
                                    <t t-set="current_section" t-value="line"/>
                                    <t t-set="current_subtotal" t-value="0"/>
                                </t>
                                <t t-if="line.display_type == ''line_note''">
                                    <td colspan="99">
                                        <span t-field="line.name"/>
                                    </td>
                                </t>
                            </tr>

                            <t t-if="current_section and (line_last or order.order_line[line_index+1].display_type == ''line_section'') and order.state in [''purchase'', ''done'']">
                                <tr class="is-subtotal text-end">
                                    <td colspan="99">
                                        <strong class="mr16">Subtotal</strong>
                                        <span t-esc="current_subtotal" t-options="{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: order.currency_id}"/>
                                    </td>
                                </tr>
                            </t>
                        </t>
                    </tbody>
                </table>
              </div>

              <div id="total" t-if="order.state in [''purchase'', ''done'']" class="row" name="total" style="page-break-inside: avoid;">
                  <div t-attf-class="#{''col-4'' if report_type != ''html'' else ''col-sm-7 col-md-5''} ms-auto">
                      <t t-call="purchase.purchase_order_portal_content_totals_table"/>
                  </div>
              </div>
          </section>

          <section id="terms" class="mt-5" t-if="order.notes">
              <h3 class="">Terms &amp; Conditions</h3>
              <hr class="mt-0 mb-1"/>
              <em t-field="order.notes"/>
          </section>

          <section class="mt-5" t-if="order.payment_term_id">
              <h3 class="">Payment terms</h3>
              <hr class="mt-0 mb-1"/>
              <span t-field="order.payment_term_id"/>
          </section>
      </div>
  </t>

  ', false, true, '2026-05-10 01:12:29.662147', '2026-05-10 01:12:29.662147', false);
INSERT INTO public.ir_ui_view VALUES (1202, 16, NULL, 1, 1, 'purchase_order_portal_content_totals_table', NULL, 'purchase.purchase_order_portal_content_totals_table', 'qweb', 'purchase/views/portal_templates.xml', 'primary', '{"en_US": "<t t-name=\"purchase.purchase_order_portal_content_totals_table\">\n      <table class=\"table table-sm\">\n          <t t-set=\"tax_totals\" t-value=\"order.tax_totals\"/>\n          <t t-call=\"purchase.document_tax_totals\"/>\n      </table>\n  </t>"}', '<?xml version="1.0"?>
<t t-name="purchase.purchase_order_portal_content_totals_table">
      <table class="table table-sm">
          <t t-set="tax_totals" t-value="order.tax_totals"/>
          <t t-call="purchase.document_tax_totals"/>
      </table>
  </t>

  ', false, true, '2026-05-10 01:12:29.662147', '2026-05-10 01:12:29.662147', false);
INSERT INTO public.ir_ui_view VALUES (1230, 16, 1193, 1, 1, 'purchase.report.search.stock', 'purchase.report', NULL, 'search', 'purchase_stock/report/purchase_report_views.xml', 'extension', '{"en_US": "<xpath expr=\"//field[@name=''user_id'']\" position=\"after\">\n                <field name=\"picking_type_id\"/>\n            </xpath>"}', '<?xml version="1.0"?>
<xpath expr="//field[@name=''user_id'']" position="after">
                <field name="picking_type_id"/>
            </xpath>
        ', false, true, '2026-05-10 01:12:32.247193', '2026-05-10 01:12:32.247193', false);
INSERT INTO public.ir_ui_view VALUES (1207, 16, NULL, 1, 1, 'report_purchasequotation_document', NULL, 'purchase.report_purchasequotation_document', 'qweb', 'purchase/report/purchase_quotation_templates.xml', 'primary', '{"en_US": "<t t-name=\"purchase.report_purchasequotation_document\">\n    <t t-call=\"web.external_layout\">\n        <t t-set=\"o\" t-value=\"o.with_context(lang=o.partner_id.lang)\"/>\n        <t t-set=\"forced_vat\" t-value=\"o.fiscal_position_id.foreign_vat\"/> <!-- So that it appears in the footer of the report instead of the company VAT if it''s set -->\n        <t t-set=\"address\">\n            <div t-field=\"o.partner_id\" t-options=\"{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;, &quot;phone&quot;, &quot;vat&quot;], &quot;no_marker&quot;: True, &quot;phone_icons&quot;: True}\"/>\n        </t>\n        <t t-if=\"o.dest_address_id\">\n            <t t-set=\"information_block\">\n                <strong>Shipping address:</strong>\n                <div t-field=\"o.dest_address_id\" t-options=\"{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;, &quot;phone&quot;], &quot;no_marker&quot;: True, &quot;phone_icons&quot;: True}\" name=\"purchase_shipping_address\"/>\n            </t>\n        </t>\n        <div class=\"page\">\n            <div class=\"oe_structure\"/>\n\n            <h2 class=\"mt-4\">Request for Quotation <span t-field=\"o.name\"/></h2>\n\n            <table class=\"table table-sm mt-4\">\n                <thead style=\"display: table-row-group\">\n                    <tr>\n                        <th name=\"th_description\"><strong>Description</strong></th>\n                        <th name=\"th_expected_date\" class=\"text-center\"><strong>Expected Date</strong></th>\n                        <th name=\"th_quantity\" class=\"text-end\"><strong>Qty</strong></th>\n                    </tr>\n                </thead>\n                <tbody>\n                    <t t-foreach=\"o.order_line\" t-as=\"order_line\">\n                        <tr t-att-class=\"''bg-200 fw-bold o_line_section'' if order_line.display_type == ''line_section'' else ''fst-italic o_line_note'' if order_line.display_type == ''line_note'' else ''''\">\n                            <t t-if=\"not order_line.display_type\">\n                                <td id=\"product\">\n                                    <span t-field=\"order_line.name\"/>\n                                </td>\n                                <td class=\"text-center\">\n                                    <span t-field=\"order_line.date_planned\"/>\n                                </td>\n                                <td class=\"text-end\">\n                                    <span t-field=\"order_line.product_qty\"/>\n                                    <span t-field=\"order_line.product_uom\" groups=\"uom.group_uom\"/>\n                                    <span t-if=\"order_line.product_packaging_id\">\n                                        (<span t-field=\"order_line.product_packaging_qty\" t-options=\"{&quot;widget&quot;: &quot;integer&quot;}\"/> <span t-field=\"order_line.product_packaging_id\"/>)\n                                    </span>\n                                </td>\n                            </t>\n                            <t t-else=\"\">\n                                <td colspan=\"99\" id=\"section\">\n                                    <span t-field=\"order_line.name\"/>\n                                </td>\n                            </t>\n                        </tr>\n                    </t>\n                </tbody>\n            </table>\n\n            <p t-field=\"o.notes\" class=\"mt-4\"/>\n\n            <div class=\"oe_structure\"/>\n        </div>\n    </t>\n</t>"}', '<?xml version="1.0"?>
<t t-name="purchase.report_purchasequotation_document">
    <t t-call="web.external_layout">
        <t t-set="o" t-value="o.with_context(lang=o.partner_id.lang)"/>
        <t t-set="forced_vat" t-value="o.fiscal_position_id.foreign_vat"/> <!-- So that it appears in the footer of the report instead of the company VAT if it''s set -->
        <t t-set="address">
            <div t-field="o.partner_id" t-options="{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;, &quot;phone&quot;, &quot;vat&quot;], &quot;no_marker&quot;: True, &quot;phone_icons&quot;: True}"/>
        </t>
        <t t-if="o.dest_address_id">
            <t t-set="information_block">
                <strong>Shipping address:</strong>
                <div t-field="o.dest_address_id" t-options="{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;, &quot;phone&quot;], &quot;no_marker&quot;: True, &quot;phone_icons&quot;: True}" name="purchase_shipping_address"/>
            </t>
        </t>
        <div class="page">
            <div class="oe_structure"/>

            <h2 class="mt-4">Request for Quotation <span t-field="o.name"/></h2>

            <table class="table table-sm mt-4">
                <thead style="display: table-row-group">
                    <tr>
                        <th name="th_description"><strong>Description</strong></th>
                        <th name="th_expected_date" class="text-center"><strong>Expected Date</strong></th>
                        <th name="th_quantity" class="text-end"><strong>Qty</strong></th>
                    </tr>
                </thead>
                <tbody>
                    <t t-foreach="o.order_line" t-as="order_line">
                        <tr t-att-class="''bg-200 fw-bold o_line_section'' if order_line.display_type == ''line_section'' else ''fst-italic o_line_note'' if order_line.display_type == ''line_note'' else ''''">
                            <t t-if="not order_line.display_type">
                                <td id="product">
                                    <span t-field="order_line.name"/>
                                </td>
                                <td class="text-center">
                                    <span t-field="order_line.date_planned"/>
                                </td>
                                <td class="text-end">
                                    <span t-field="order_line.product_qty"/>
                                    <span t-field="order_line.product_uom" groups="uom.group_uom"/>
                                    <span t-if="order_line.product_packaging_id">
                                        (<span t-field="order_line.product_packaging_qty" t-options="{&quot;widget&quot;: &quot;integer&quot;}"/> <span t-field="order_line.product_packaging_id"/>)
                                    </span>
                                </td>
                            </t>
                            <t t-else="">
                                <td colspan="99" id="section">
                                    <span t-field="order_line.name"/>
                                </td>
                            </t>
                        </tr>
                    </t>
                </tbody>
            </table>

            <p t-field="o.notes" class="mt-4"/>

            <div class="oe_structure"/>
        </div>
    </t>
</t>

', false, true, '2026-05-10 01:12:29.662147', '2026-05-10 01:12:29.662147', false);
