INSERT INTO public.ir_ui_view VALUES (1211, 10, 408, 1, 1, 'account.analytic.account.form.purchase', 'account.analytic.account', NULL, 'form', 'purchase/views/analytic_account_views.xml', 'extension', '{"en_US": "<div name=\"button_box\" position=\"inside\">\n                <button class=\"oe_stat_button\" type=\"object\" name=\"action_view_purchase_orders\" icon=\"fa-credit-card\" invisible=\"purchase_order_count == 0\" groups=\"purchase.group_purchase_user\">\n                    <field string=\"Purchase Orders\" name=\"purchase_order_count\" widget=\"statinfo\"/>\n                </button>\n            </div>"}', '<?xml version="1.0"?>
<div name="button_box" position="inside">
                <button class="oe_stat_button" type="object" name="action_view_purchase_orders" icon="fa-credit-card" invisible="purchase_order_count == 0" groups="purchase.group_purchase_user">
                    <field string="Purchase Orders" name="purchase_order_count" widget="statinfo"/>
