INSERT INTO public.ir_ui_view VALUES (1212, 16, NULL, 1, 1, 'exception_on_po', NULL, 'purchase_stock.exception_on_po', 'qweb', 'purchase_stock/data/mail_templates.xml', 'primary', '{"en_US": "<t t-name=\"purchase_stock.exception_on_po\">\n        <div>\n          Exception(s) occurred on the purchase order(s):\n          <t t-foreach=\"purchase_order_ids\" t-as=\"purchase_order\">\n              <a href=\"#\" data-oe-model=\"purchase.order\" t-att-data-oe-id=\"purchase_order.id\"><t t-esc=\"purchase_order.name\"/></a>.\n          </t>\n          Manual actions may be needed.\n          <div class=\"mt16\">\n              <p>Exception(s):</p>\n              <ul t-foreach=\"order_exceptions\" t-as=\"exception\">\n                  <li>\n                      <t t-set=\"order_line\" t-value=\"exception[0]\"/>\n                      <t t-set=\"new_qty\" t-value=\"exception[1][0]\"/>\n                      <t t-set=\"old_qty\" t-value=\"exception[1][1]\"/>\n                      <t t-esc=\"new_qty\"/> <t t-esc=\"order_line.product_uom.name\"/> of <t t-esc=\"order_line.product_id.name\"/>\n                      ordered instead of <t t-esc=\"old_qty\"/> <t t-esc=\"order_line.product_uom.name\"/>\n                  </li>\n              </ul>\n          </div>\n          <div class=\"mt16\" t-if=\"impacted_pickings\">\n              <p>Next transfer(s) impacted:</p>\n              <ul t-foreach=\"impacted_pickings\" t-as=\"picking\">\n                  <li><a href=\"#\" data-oe-model=\"stock.picking\" t-att-data-oe-id=\"picking.id\"><t t-esc=\"picking.name\"/></a></li>\n              </ul>\n          </div>\n        </div>\n    </t>"}', '<?xml version="1.0"?>
<t t-name="purchase_stock.exception_on_po">
        <div>
          Exception(s) occurred on the purchase order(s):
          <t t-foreach="purchase_order_ids" t-as="purchase_order">
              <a href="#" data-oe-model="purchase.order" t-att-data-oe-id="purchase_order.id"><t t-esc="purchase_order.name"/></a>.
          </t>
          Manual actions may be needed.
          <div class="mt16">
              <p>Exception(s):</p>
              <ul t-foreach="order_exceptions" t-as="exception">
                  <li>
                      <t t-set="order_line" t-value="exception[0]"/>
                      <t t-set="new_qty" t-value="exception[1][0]"/>
                      <t t-set="old_qty" t-value="exception[1][1]"/>
                      <t t-esc="new_qty"/> <t t-esc="order_line.product_uom.name"/> of <t t-esc="order_line.product_id.name"/>
                      ordered instead of <t t-esc="old_qty"/> <t t-esc="order_line.product_uom.name"/>
                  </li>
              </ul>
          </div>
          <div class="mt16" t-if="impacted_pickings">
              <p>Next transfer(s) impacted:</p>
              <ul t-foreach="impacted_pickings" t-as="picking">
                  <li><a href="#" data-oe-model="stock.picking" t-att-data-oe-id="picking.id"><t t-esc="picking.name"/></a></li>
              </ul>
          </div>
        </div>
    </t>
', false, true, '2026-05-10 01:12:32.247193', '2026-05-10 01:12:32.247193', false);
INSERT INTO public.ir_ui_view VALUES (1213, 16, NULL, 1, 1, 'vendor.delay.report.search', 'vendor.delay.report', NULL, 'search', 'purchase_stock/report/vendor_delay_report.xml', 'primary', '{"en_US": "<search string=\"On-time Delivery\">\n                <field name=\"partner_id\"/>\n                <field name=\"product_id\"/>\n                <filter string=\"Effective Date Last Year\" name=\"later_than_a_year_ago\" domain=\"[(''date'', ''&gt;='', ((context_today()-relativedelta(years=1)).strftime(''%Y-%m-%d'')))]\"/>\n            </search>"}', '<?xml version="1.0"?>
