INSERT INTO public.ir_ui_view VALUES (1215, 16, 1161, 1, 1, 'purchase.order.form.inherit', 'purchase.order', NULL, 'form', 'purchase_stock/views/purchase_views.xml', 'extension', '{"en_US": "<data><xpath expr=\"//header/button[@name=''action_rfq_send'']\" position=\"after\">\n                <button name=\"action_view_picking\" string=\"Receive Products\" class=\"oe_highlight\" type=\"object\" invisible=\"is_shipped or state not in (''purchase'', ''done'') or incoming_picking_count == 0\" data-hotkey=\"y\" groups=\"stock.group_stock_user\"/>\n            </xpath>\n            <xpath expr=\"//header/button[@name=''confirm_reminder_mail'']\" position=\"attributes\">\n                <attribute name=\"invisible\">state not in (''purchase'', ''done'') or mail_reminder_confirmed or not date_planned or effective_date</attribute>\n            </xpath>\n            <xpath expr=\"//div[hasclass(''oe_button_box'')]\" position=\"inside\">\n                <button type=\"object\" name=\"action_view_picking\" class=\"oe_stat_button\" icon=\"fa-truck\" invisible=\"incoming_picking_count == 0\" groups=\"stock.group_stock_user\">\n                    <field name=\"incoming_picking_count\" widget=\"statinfo\" string=\"Receipt\" help=\"Incoming Shipments\"/>\n                </button>\n            </xpath>\n            <xpath expr=\"//field[@name=''currency_id'']\" position=\"after\">\n                <field name=\"is_shipped\" invisible=\"1\"/>\n            </xpath>\n            <xpath expr=\"//field[@name=''order_line'']/tree//field[@name=''date_planned'']\" position=\"after\">\n                <field name=\"move_dest_ids\" column_invisible=\"True\"/>\n            </xpath>\n            <xpath expr=\"//page/field[@name=''order_line'']/tree/field[@name=''product_qty'']\" position=\"after\">\n                <field name=\"forecasted_issue\" column_invisible=\"True\"/>\n                <button type=\"object\" name=\"action_product_forecast_report\" title=\"Forecast Report\" icon=\"fa-area-chart\" invisible=\"not id or not forecasted_issue or product_type != ''product''\" class=\"text-danger\"/>\n                <button type=\"object\" name=\"action_product_forecast_report\" title=\"Forecast Report\" icon=\"fa-area-chart\" invisible=\"not id or forecasted_issue or product_type != ''product''\"/>\n            </xpath>\n            <xpath expr=\"//div[@name=''date_planned_div'']\" position=\"inside\">\n                <div>\n                    <button name=\"441\" class=\"oe_link\" type=\"action\" context=\"{''search_default_partner_id'': partner_id}\" invisible=\"state in [''purchase'', ''done''] or not partner_id\">\n                        <span invisible=\"on_time_rate &lt; 0\"><field name=\"on_time_rate\" widget=\"integer\" class=\"oe_inline\"/>% On-Time Delivery</span>\n                        <span invisible=\"on_time_rate &gt;= 0\">No On-time Delivery Data</span>\n                    </button>\n                </div>\n            </xpath>\n            <xpath expr=\"//label[@for=''receipt_reminder_email'']\" position=\"attributes\">\n                <attribute name=\"invisible\">effective_date</attribute>\n            </xpath>\n            <xpath expr=\"//div[@name=''reminder'']\" position=\"attributes\">\n                <attribute name=\"invisible\">effective_date</attribute>\n            </xpath>\n            <xpath expr=\"//div[@name=''reminder'']\" position=\"after\">\n                <field name=\"effective_date\" invisible=\"not effective_date\"/>\n            </xpath>\n            <xpath expr=\"//field[@name=''order_line'']/form//field[@name=''invoice_lines'']\" position=\"after\">\n                <field name=\"move_ids\"/>\n            </xpath>\n            <field name=\"invoice_status\" position=\"before\">\n                <field name=\"receipt_status\" invisible=\"state not in (''purchase'', ''done'')\"/>\n            </field>\n            <xpath expr=\"//field[@name=''order_line'']/form//field[@name=''analytic_distribution'']\" position=\"before\">\n                <field name=\"propagate_cancel\" groups=\"base.group_no_one\"/>\n            </xpath>\n            <xpath expr=\"//field[@name=''order_line'']/tree//field[@name=''analytic_distribution'']\" position=\"before\">\n                <field name=\"propagate_cancel\" groups=\"base.group_no_one\" optional=\"hide\"/>\n            </xpath>\n            <xpath expr=\"//field[@name=''order_line'']/tree//field[@name=''qty_received'']\" position=\"attributes\">\n                <attribute name=\"column_invisible\">parent.state not in (''purchase'', ''done'')</attribute>\n                <attribute name=\"readonly\">product_type in (''consu'', ''product'')</attribute>\n            </xpath>\n            <xpath expr=\"//page[@name=''purchase_delivery_invoice'']/group/group\" position=\"inside\">\n                <field name=\"default_location_dest_id_usage\" invisible=\"1\"/>\n                <field name=\"incoterm_id\" readonly=\"state == ''done''\"/>\n                <field name=\"incoterm_location\" readonly=\"state == ''done''\"/>\n            </xpath>\n            <xpath expr=\"//div[@name=''reminder'']\" position=\"after\">\n                <field name=\"picking_type_id\" domain=\"[(''code'',''='',''incoming''), ''|'', (''warehouse_id'', ''='', False), (''warehouse_id.company_id'', ''='', company_id)]\" options=\"{''no_create'': True}\" groups=\"stock.group_stock_multi_locations\" readonly=\"state in [''cancel'', ''done'', ''purchase'']\"/>\n                <field name=\"dest_address_id\" groups=\"stock.group_stock_multi_locations\" invisible=\"default_location_dest_id_usage != ''customer''\" readonly=\"state in [''cancel'', ''done'', ''purchase'']\" required=\"default_location_dest_id_usage == ''customer''\"/>\n            </xpath>\n        </data>"}', '<?xml version="1.0"?>
<data><xpath expr="//header/button[@name=''action_rfq_send'']" position="after">
                <button name="action_view_picking" string="Receive Products" class="oe_highlight" type="object" invisible="is_shipped or state not in (''purchase'', ''done'') or incoming_picking_count == 0" data-hotkey="y" groups="stock.group_stock_user"/>
            </xpath>
            <xpath expr="//header/button[@name=''confirm_reminder_mail'']" position="attributes">
                <attribute name="invisible">state not in (''purchase'', ''done'') or mail_reminder_confirmed or not date_planned or effective_date</attribute>
            </xpath>
            <xpath expr="//div[hasclass(''oe_button_box'')]" position="inside">
                <button type="object" name="action_view_picking" class="oe_stat_button" icon="fa-truck" invisible="incoming_picking_count == 0" groups="stock.group_stock_user">
                    <field name="incoming_picking_count" widget="statinfo" string="Receipt" help="Incoming Shipments"/>
                </button>
            </xpath>
            <xpath expr="//field[@name=''currency_id'']" position="after">
                <field name="is_shipped" invisible="1"/>
            </xpath>
            <xpath expr="//field[@name=''order_line'']/tree//field[@name=''date_planned'']" position="after">
                <field name="move_dest_ids" column_invisible="True"/>
            </xpath>
            <xpath expr="//page/field[@name=''order_line'']/tree/field[@name=''product_qty'']" position="after">
                <field name="forecasted_issue" column_invisible="True"/>
                <button type="object" name="action_product_forecast_report" title="Forecast Report" icon="fa-area-chart" invisible="not id or not forecasted_issue or product_type != ''product''" class="text-danger"/>
                <button type="object" name="action_product_forecast_report" title="Forecast Report" icon="fa-area-chart" invisible="not id or forecasted_issue or product_type != ''product''"/>
            </xpath>
            <xpath expr="//div[@name=''date_planned_div'']" position="inside">
                <div>
                    <button name="441" class="oe_link" type="action" context="{''search_default_partner_id'': partner_id}" invisible="state in [''purchase'', ''done''] or not partner_id">
                        <span invisible="on_time_rate &lt; 0"><field name="on_time_rate" widget="integer" class="oe_inline"/>% On-Time Delivery</span>
                        <span invisible="on_time_rate &gt;= 0">No On-time Delivery Data</span>
                    </button>
                </div>
            </xpath>
            <xpath expr="//label[@for=''receipt_reminder_email'']" position="attributes">
                <attribute name="invisible">effective_date</attribute>
            </xpath>
            <xpath expr="//div[@name=''reminder'']" position="attributes">
                <attribute name="invisible">effective_date</attribute>
            </xpath>
            <xpath expr="//div[@name=''reminder'']" position="after">
                <field name="effective_date" invisible="not effective_date"/>
            </xpath>
            <xpath expr="//field[@name=''order_line'']/form//field[@name=''invoice_lines'']" position="after">
                <field name="move_ids"/>
            </xpath>
            <field name="invoice_status" position="before">
                <field name="receipt_status" invisible="state not in (''purchase'', ''done'')"/>
            </field>
            <xpath expr="//field[@name=''order_line'']/form//field[@name=''analytic_distribution'']" position="before">
                <field name="propagate_cancel" groups="base.group_no_one"/>
            </xpath>
            <xpath expr="//field[@name=''order_line'']/tree//field[@name=''analytic_distribution'']" position="before">
                <field name="propagate_cancel" groups="base.group_no_one" optional="hide"/>
            </xpath>
            <xpath expr="//field[@name=''order_line'']/tree//field[@name=''qty_received'']" position="attributes">
                <attribute name="column_invisible">parent.state not in (''purchase'', ''done'')</attribute>
                <attribute name="readonly">product_type in (''consu'', ''product'')</attribute>
            </xpath>
            <xpath expr="//page[@name=''purchase_delivery_invoice'']/group/group" position="inside">
                <field name="default_location_dest_id_usage" invisible="1"/>
                <field name="incoterm_id" readonly="state == ''done''"/>
                <field name="incoterm_location" readonly="state == ''done''"/>
            </xpath>
            <xpath expr="//div[@name=''reminder'']" position="after">
                <field name="picking_type_id" domain="[(''code'',''='',''incoming''), ''|'', (''warehouse_id'', ''='', False), (''warehouse_id.company_id'', ''='', company_id)]" options="{''no_create'': True}" groups="stock.group_stock_multi_locations" readonly="state in [''cancel'', ''done'', ''purchase'']"/>
                <field name="dest_address_id" groups="stock.group_stock_multi_locations" invisible="default_location_dest_id_usage != ''customer''" readonly="state in [''cancel'', ''done'', ''purchase'']" required="default_location_dest_id_usage == ''customer''"/>
            </xpath>
        </data>', false, true, '2026-05-10 01:12:32.247193', '2026-05-10 01:12:32.247193', false);
INSERT INTO public.ir_ui_view VALUES (1216, 16, 1171, 1, 1, 'purchase.order.line.form.inherit', 'purchase.order.line', NULL, 'form', 'purchase_stock/views/purchase_views.xml', 'extension', '{"en_US": "<xpath expr=\"//field[@name=''invoice_lines'']\" position=\"after\">\n                <separator string=\"Stock Moves\"/>\n                <field name=\"move_ids\"/>\n            </xpath>"}', '<?xml version="1.0"?>
