INSERT INTO public.ir_ui_view VALUES (1217, 16, 1168, 1, 1, 'purchase.order.tree.inherit', 'purchase.order', NULL, 'tree', 'purchase_stock/views/purchase_views.xml', 'extension', '{"en_US": "<field name=\"invoice_status\" position=\"before\">\n                <field name=\"effective_date\" column_invisible=\"True\"/>\n                <field name=\"receipt_status\" optional=\"hide\" widget=\"badge\" decoration-success=\"date_planned and (date_planned &gt; datetime.datetime.combine(datetime.date.today(), datetime.time(23,59,59)).to_utc().strftime(''%Y-%m-%d %H:%M:%S'') or receipt_status==''full'' and effective_date &lt;= date_planned)\" decoration-danger=\"date_planned and (date_planned &lt; effective_date or date_planned &lt; datetime.datetime.combine(datetime.date.today(), datetime.time(0,0,0)).to_utc().strftime(''%Y-%m-%d %H:%M:%S'') and receipt_status!=''full'' and effective_date &lt;= date_planned)\" decoration-warning=\"date_planned and date_planned &gt;= datetime.datetime.combine(datetime.date.today(), datetime.time(0,0,0)).to_utc().strftime(''%Y-%m-%d %H:%M:%S'') and date_planned &lt;= datetime.datetime.combine(datetime.date.today(), datetime.time(23,59,59)).to_utc().strftime(''%Y-%m-%d %H:%M:%S'') and receipt_status!=''full''\"/>\n            </field>"}', '<?xml version="1.0"?>
<field name="invoice_status" position="before">
                <field name="effective_date" column_invisible="True"/>
                <field name="receipt_status" optional="hide" widget="badge" decoration-success="date_planned and (date_planned &gt; datetime.datetime.combine(datetime.date.today(), datetime.time(23,59,59)).to_utc().strftime(''%Y-%m-%d %H:%M:%S'') or receipt_status==''full'' and effective_date &lt;= date_planned)" decoration-danger="date_planned and (date_planned &lt; effective_date or date_planned &lt; datetime.datetime.combine(datetime.date.today(), datetime.time(0,0,0)).to_utc().strftime(''%Y-%m-%d %H:%M:%S'') and receipt_status!=''full'' and effective_date &lt;= date_planned)" decoration-warning="date_planned and date_planned &gt;= datetime.datetime.combine(datetime.date.today(), datetime.time(0,0,0)).to_utc().strftime(''%Y-%m-%d %H:%M:%S'') and date_planned &lt;= datetime.datetime.combine(datetime.date.today(), datetime.time(23,59,59)).to_utc().strftime(''%Y-%m-%d %H:%M:%S'') and receipt_status!=''full''"/>
            </field>
        ', false, true, '2026-05-10 01:12:32.247193', '2026-05-10 01:12:32.247193', false);
