INSERT INTO public.ir_ui_view VALUES (1223, 25, 1174, 1, 1, 'res.config.settings.view.form.inherit.purchase', 'res.config.settings', NULL, 'form', 'purchase_stock/views/res_config_settings_views.xml', 'extension', '{"en_US": "<xpath expr=\"//app[@name=''purchase'']\" position=\"inside\">\n\t\t\t\t<field name=\"is_installed_sale\" invisible=\"1\"/>\n\t\t\t\t<block title=\"Logistics\" invisible=\"not is_installed_sale\" name=\"request_vendor_setting_container\">\n\t\t\t\t\t<setting title=\"This adds a dropshipping route to apply on products in order to request your vendors to deliver to your customers. A product to dropship will generate a purchase request for quotation once the sales order confirmed. This is a on-demand flow. The requested delivery address will be the customer delivery address and not your warehouse.\" help=\"Request your vendors to deliver to your customers\" documentation=\"/applications/inventory_and_mrp/inventory/shipping/operation/dropshipping.html\">\n\t\t\t\t\t\t<field name=\"module_stock_dropshipping\"/>\n\t\t\t\t\t</setting>\n\t\t\t\t</block>\n\t\t\t</xpath>"}', '<?xml version="1.0"?>
<xpath expr="//app[@name=''purchase'']" position="inside">
				<field name="is_installed_sale" invisible="1"/>
				<block title="Logistics" invisible="not is_installed_sale" name="request_vendor_setting_container">
					<setting title="This adds a dropshipping route to apply on products in order to request your vendors to deliver to your customers. A product to dropship will generate a purchase request for quotation once the sales order confirmed. This is a on-demand flow. The requested delivery address will be the customer delivery address and not your warehouse." help="Request your vendors to deliver to your customers" documentation="/applications/inventory_and_mrp/inventory/shipping/operation/dropshipping.html">
						<field name="module_stock_dropshipping"/>
					</setting>
				</block>
			</xpath>
		', false, true, '2026-05-10 01:12:32.247193', '2026-05-10 01:12:32.247193', false);
INSERT INTO public.ir_ui_view VALUES (1224, 16, 1099, 1, 1, 'res.config.settings.view.form.inherit.purchase.stock', 'res.config.settings', NULL, 'form', 'purchase_stock/views/res_config_settings_views.xml', 'extension', '{"en_US": "<data><xpath expr=\"//block[@id=''schedule_info'']\" position=\"attributes\">\n\t\t\t\t<attribute name=\"invisible\">0</attribute>\n\t\t\t</xpath>\n\t\t\t<div id=\"purchase_po_lead\" position=\"replace\">\n\t\t\t\t<setting company_dependent=\"1\" help=\"Schedule request for quotations earlier to avoid delays\" documentation=\"/applications/inventory_and_mrp/inventory/management/planning/scheduled_dates.html\" title=\"Margin of error for vendor lead times. When the system generates Purchase Orders for reordering products,they will be scheduled that many days earlier to cope with unexpected vendor delays.\" name=\"schedule_receivings_setting_container\">\n\t\t\t\t\t<field name=\"use_po_lead\"/>\n\t\t\t\t\t<div class=\"content-group\">\n\t\t\t\t\t\t<div class=\"mt16\" invisible=\"not use_po_lead\">\n\t\t\t\t\t\t\t<span>Move forward expected request creation date by <field name=\"po_lead\" class=\"oe_inline\"/> days</span>\n\t\t\t\t\t\t</div>\n\t\t\t\t\t</div>\n\t\t\t\t</setting>\n\t\t\t\t<setting company_dependent=\"1\" help=\"Days needed to confirm a PO\">\n\t\t\t\t\t<field name=\"days_to_purchase\" class=\"oe_inline\"/><span> days</span>\n\t\t\t\t</setting>\n\t\t\t</div>\n\t\t</data>"}', '<?xml version="1.0"?>
<data><xpath expr="//block[@id=''schedule_info'']" position="attributes">
				<attribute name="invisible">0</attribute>
			</xpath>
			<div id="purchase_po_lead" position="replace">
				<setting company_dependent="1" help="Schedule request for quotations earlier to avoid delays" documentation="/applications/inventory_and_mrp/inventory/management/planning/scheduled_dates.html" title="Margin of error for vendor lead times. When the system generates Purchase Orders for reordering products,they will be scheduled that many days earlier to cope with unexpected vendor delays." name="schedule_receivings_setting_container">
					<field name="use_po_lead"/>
					<div class="content-group">
						<div class="mt16" invisible="not use_po_lead">
							<span>Move forward expected request creation date by <field name="po_lead" class="oe_inline"/> days</span>
						</div>
					</div>
				</setting>
				<setting company_dependent="1" help="Days needed to confirm a PO">
					<field name="days_to_purchase" class="oe_inline"/><span> days</span>
				</setting>
			</div>
		</data>', false, true, '2026-05-10 01:12:32.247193', '2026-05-10 01:12:32.247193', false);
INSERT INTO public.ir_ui_view VALUES (1225, 16, 1186, 1, 1, 'res.partner.purchase.stock.form.inherit', 'res.partner', NULL, 'form', 'purchase_stock/views/res_partner_views.xml', 'extension', '{"en_US": "<xpath expr=\"//field[@name=''purchase_order_count'']/..\" position=\"after\">\n                    <button class=\"oe_stat_button\" name=\"441\" type=\"action\" groups=\"purchase.group_purchase_user\" icon=\"fa-truck\" context=\"{''search_default_partner_id'': id}\">\n                        <div class=\"o_form_field o_stat_info\">\n                            <div class=\"o_row\" invisible=\"on_time_rate &lt; 0\">\n                                <span class=\"o_stat_value\">\n                                    <field string=\"On-time Rate\" name=\"on_time_rate\" widget=\"integer\"/>\n                                </span>\n                                <span class=\"o_stat_value\">%</span>\n                            </div>\n                            <div class=\"o_stat_value\" invisible=\"on_time_rate &gt;= 0\">\n                                No data yet\n                            </div>\n                            <span class=\"o_stat_text\">On-time Rate</span>\n                        </div>\n                    </button>\n                </xpath>"}', '<?xml version="1.0"?>
<xpath expr="//field[@name=''purchase_order_count'']/.." position="after">
                    <button class="oe_stat_button" name="441" type="action" groups="purchase.group_purchase_user" icon="fa-truck" context="{''search_default_partner_id'': id}">
                        <div class="o_form_field o_stat_info">
                            <div class="o_row" invisible="on_time_rate &lt; 0">
                                <span class="o_stat_value">
                                    <field string="On-time Rate" name="on_time_rate" widget="integer"/>
                                </span>
                                <span class="o_stat_value">%</span>
                            </div>
                            <div class="o_stat_value" invisible="on_time_rate &gt;= 0">
                                No data yet
                            </div>
                            <span class="o_stat_text">On-time Rate</span>
                        </div>
                    </button>
                </xpath>
            ', false, true, '2026-05-10 01:12:32.247193', '2026-05-10 01:12:32.247193', false);
INSERT INTO public.ir_ui_view VALUES (1226, 16, 1013, 1, 1, 'stock.production.lot.view.form', 'stock.lot', NULL, 'form', 'purchase_stock/views/stock_lot_views.xml', 'extension', '{"en_US": "<data><xpath expr=\"//div[hasclass(''oe_button_box'')]/button\" position=\"before\">\n                <button class=\"oe_stat_button\" name=\"action_view_po\" type=\"object\" icon=\"fa-credit-card\" help=\"Purchase Orders\" invisible=\"purchase_order_count == 0 or not display_complete\">\n                    <div class=\"o_field_widget o_stat_info\">\n                        <span class=\"o_stat_value\">\n                            <field name=\"purchase_order_count\" widget=\"statinfo\" nolabel=\"1\" class=\"mr4\"/>\n                        </span>\n                        <span class=\"o_stat_text\">Purchases</span>\n                    </div>\n                </button>\n            </xpath>\n            <xpath expr=\"//group[@name=''main_group'']\" position=\"after\">\n                <group>\n                    <field name=\"purchase_order_ids\" widget=\"many2many\" readonly=\"True\" invisible=\"not purchase_order_ids or display_complete\">\n                        <tree>\n                            <field name=\"name\"/>\n                            <field name=\"partner_id\" readonly=\"state in [''cancel'', ''done'', ''purchase'']\"/>\n                            <field name=\"date_order\" readonly=\"state in [''cancel'', ''done'', ''purchase'']\"/>\n                            <field name=\"state\" column_invisible=\"True\"/>\n                        </tree>\n                    </field>\n                </group>\n            </xpath>\n        </data>"}', '<?xml version="1.0"?>
<data><xpath expr="//div[hasclass(''oe_button_box'')]/button" position="before">
                <button class="oe_stat_button" name="action_view_po" type="object" icon="fa-credit-card" help="Purchase Orders" invisible="purchase_order_count == 0 or not display_complete">
                    <div class="o_field_widget o_stat_info">
                        <span class="o_stat_value">
                            <field name="purchase_order_count" widget="statinfo" nolabel="1" class="mr4"/>
                        </span>
                        <span class="o_stat_text">Purchases</span>
                    </div>
                </button>
            </xpath>
            <xpath expr="//group[@name=''main_group'']" position="after">
                <group>
                    <field name="purchase_order_ids" widget="many2many" readonly="True" invisible="not purchase_order_ids or display_complete">
                        <tree>
                            <field name="name"/>
                            <field name="partner_id" readonly="state in [''cancel'', ''done'', ''purchase'']"/>
                            <field name="date_order" readonly="state in [''cancel'', ''done'', ''purchase'']"/>
                            <field name="state" column_invisible="True"/>
                        </tree>
                    </field>
                </group>
            </xpath>
        </data>', false, true, '2026-05-10 01:12:32.247193', '2026-05-10 01:12:32.247193', false);
