INSERT INTO public.ir_ui_view VALUES (1231, 16, 1204, 1, 1, 'report_purchaseorder_document', NULL, 'purchase_stock.report_purchaseorder_document', 'qweb', 'purchase_stock/report/purchase_report_templates.xml', 'extension', '{"en_US": "<data inherit_id=\"purchase.report_purchaseorder_document\">\n        <xpath expr=\"//t[@t-if=''o.dest_address_id'']\" position=\"after\">\n            <t t-else=\"\">\n                <t t-set=\"information_block\">\n                    <strong>Shipping address:</strong>\n                    <div t-if=\"o.picking_type_id and o.picking_type_id.warehouse_id\">\n                        <span t-field=\"o.picking_type_id.warehouse_id.name\"/>\n                        <div t-field=\"o.picking_type_id.warehouse_id.partner_id\" t-options=\"{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;phone&quot;], &quot;no_marker&quot;: True, &quot;phone_icons&quot;: True}\"/>\n                    </div>\n                </t>\n            </t>\n        </xpath>\n        <xpath expr=\"//div[@t-elif=''o.date_order'']\" position=\"after\">\n            <div t-if=\"o.incoterm_id\" class=\"col-3 bm-2\">\n                <strong>Incoterm:</strong>\n                <p t-if=\"o.incoterm_location\">\n                    <span t-field=\"o.incoterm_id.code\"/> <br/>\n                    <span t-field=\"o.incoterm_location\"/>\n                </p>\n                <p t-else=\"\" t-field=\"o.incoterm_id.code\" class=\"m-0\"/>\n            </div>\n        </xpath>\n    </data>"}', '<?xml version="1.0"?>
<data inherit_id="purchase.report_purchaseorder_document">
        <xpath expr="//t[@t-if=''o.dest_address_id'']" position="after">
            <t t-else="">
                <t t-set="information_block">
                    <strong>Shipping address:</strong>
                    <div t-if="o.picking_type_id and o.picking_type_id.warehouse_id">
                        <span t-field="o.picking_type_id.warehouse_id.name"/>
                        <div t-field="o.picking_type_id.warehouse_id.partner_id" t-options="{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;phone&quot;], &quot;no_marker&quot;: True, &quot;phone_icons&quot;: True}"/>
                    </div>
                </t>
            </t>
        </xpath>
        <xpath expr="//div[@t-elif=''o.date_order'']" position="after">
            <div t-if="o.incoterm_id" class="col-3 bm-2">
                <strong>Incoterm:</strong>
                <p t-if="o.incoterm_location">
                    <span t-field="o.incoterm_id.code"/> <br/>
                    <span t-field="o.incoterm_location"/>
                </p>
                <p t-else="" t-field="o.incoterm_id.code" class="m-0"/>
            </div>
        </xpath>
    </data>

    ', false, true, '2026-05-10 01:12:32.247193', '2026-05-10 01:12:32.247193', false);
INSERT INTO public.ir_ui_view VALUES (1232, 16, 1207, 1, 1, 'report_purchasequotation_document', NULL, 'purchase_stock.report_purchasequotation_document', 'qweb', 'purchase_stock/report/purchase_report_templates.xml', 'extension', '{"en_US": "<data inherit_id=\"purchase.report_purchasequotation_document\">\n        <xpath expr=\"//t[@t-if=''o.dest_address_id'']\" position=\"after\">\n            <t t-else=\"\">\n                <t t-set=\"information_block\">\n                    <strong>Shipping address:</strong>\n                    <div t-if=\"o.picking_type_id and o.picking_type_id.warehouse_id\">\n                        <span t-field=\"o.picking_type_id.warehouse_id.name\"/>\n                        <div t-field=\"o.picking_type_id.warehouse_id.partner_id\" t-options=\"{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;phone&quot;], &quot;no_marker&quot;: True, &quot;phone_icons&quot;: True}\"/>\n                    </div>\n                </t>\n            </t>\n        </xpath>\n        <xpath expr=\"//span[@t-field=''o.name'']/..\" position=\"after\">\n            <div id=\"informations\" class=\"row mt16 mb16\">\n                <div t-if=\"o.incoterm_id\" class=\"col-3 bm-2\">\n                    <strong>Incoterm:</strong>\n                    <p t-if=\"o.incoterm_location\">\n                        <span t-field=\"o.incoterm_id.code\"/> <br/>\n                        <span t-field=\"o.incoterm_location\"/>\n                    </p>\n                    <p t-else=\"\" t-field=\"o.incoterm_id.code\" class=\"m-0\"/>\n                </div>\n            </div>\n        </xpath>\n    </data>"}', '<?xml version="1.0"?>
<data inherit_id="purchase.report_purchasequotation_document">
        <xpath expr="//t[@t-if=''o.dest_address_id'']" position="after">
            <t t-else="">
                <t t-set="information_block">
                    <strong>Shipping address:</strong>
                    <div t-if="o.picking_type_id and o.picking_type_id.warehouse_id">
                        <span t-field="o.picking_type_id.warehouse_id.name"/>
                        <div t-field="o.picking_type_id.warehouse_id.partner_id" t-options="{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;phone&quot;], &quot;no_marker&quot;: True, &quot;phone_icons&quot;: True}"/>
                    </div>
                </t>
            </t>
        </xpath>
        <xpath expr="//span[@t-field=''o.name'']/.." position="after">
            <div id="informations" class="row mt16 mb16">
                <div t-if="o.incoterm_id" class="col-3 bm-2">
                    <strong>Incoterm:</strong>
                    <p t-if="o.incoterm_location">
                        <span t-field="o.incoterm_id.code"/> <br/>
                        <span t-field="o.incoterm_location"/>
                    </p>
                    <p t-else="" t-field="o.incoterm_id.code" class="m-0"/>
                </div>
            </div>
        </xpath>
    </data>

', false, true, '2026-05-10 01:12:32.247193', '2026-05-10 01:12:32.247193', false);
INSERT INTO public.ir_ui_view VALUES (1233, 16, 969, 1, 1, 'purchase_report_stock_rule', NULL, 'purchase_stock.purchase_report_stock_rule', 'qweb', 'purchase_stock/report/report_stock_rule.xml', 'extension', '{"en_US": "<data inherit_id=\"stock.report_stock_rule\">\n        <xpath expr=\"//div[hasclass(''o_report_stock_rule_rule'')]/t\" position=\"before\">\n            <t t-if=\"rule[0].action == ''buy''\">\n                <t t-if=\"rule[1] == ''origin''\">\n                    <t t-call=\"stock.report_stock_rule_left_arrow\"/>\n                </t>\n            </t>\n        </xpath>\n        <xpath expr=\"//div[hasclass(''o_report_stock_rule_rule'')]/t[last()]\" position=\"after\">\n            <t t-if=\"rule[0].action == ''buy''\">\n                <t t-if=\"rule[1] == ''destination''\">\n                    <t t-call=\"stock.report_stock_rule_right_arrow\"/>\n                </t>\n            </t>\n        </xpath>\n        <xpath expr=\"//div[hasclass(''o_report_stock_rule_rule_name'')]/span\" position=\"before\">\n            <t t-if=\"rule[0].action == ''buy''\">\n                <i class=\"fa fa-credit-card fa-fw\" t-attf-style=\"color: #{color};\"/>\n            </t>\n        </xpath>\n        <xpath expr=\"//div[hasclass(''o_report_stock_rule_legend'')]\" position=\"inside\">\n            <div class=\"o_report_stock_rule_legend_line\">\n                <div class=\"o_report_stock_rule_legend_label\">Buy</div>\n                <div class=\"o_report_stock_rule_legend_symbol\">\n                    <div class=\"fa fa-credit-card fa-fw\" t-attf-style=\"color: #{color};\"/>\n                </div>\n            </div>\n        </xpath>\n    </data>"}', '<?xml version="1.0"?>
<data inherit_id="stock.report_stock_rule">
        <xpath expr="//div[hasclass(''o_report_stock_rule_rule'')]/t" position="before">
            <t t-if="rule[0].action == ''buy''">
                <t t-if="rule[1] == ''origin''">
                    <t t-call="stock.report_stock_rule_left_arrow"/>
                </t>
            </t>
        </xpath>
        <xpath expr="//div[hasclass(''o_report_stock_rule_rule'')]/t[last()]" position="after">
            <t t-if="rule[0].action == ''buy''">
                <t t-if="rule[1] == ''destination''">
                    <t t-call="stock.report_stock_rule_right_arrow"/>
                </t>
            </t>
        </xpath>
        <xpath expr="//div[hasclass(''o_report_stock_rule_rule_name'')]/span" position="before">
            <t t-if="rule[0].action == ''buy''">
                <i class="fa fa-credit-card fa-fw" t-attf-style="color: #{color};"/>
            </t>
        </xpath>
        <xpath expr="//div[hasclass(''o_report_stock_rule_legend'')]" position="inside">
            <div class="o_report_stock_rule_legend_line">
                <div class="o_report_stock_rule_legend_label">Buy</div>
                <div class="o_report_stock_rule_legend_symbol">
                    <div class="fa fa-credit-card fa-fw" t-attf-style="color: #{color};"/>
                </div>
            </div>
        </xpath>
    </data>
', false, true, '2026-05-10 01:12:32.247193', '2026-05-10 01:12:32.247193', false);
INSERT INTO public.ir_ui_view VALUES (1234, 100, 495, 1, 1, 'product.supplierinfo.replenishment.tree.view', 'product.supplierinfo', NULL, 'tree', 'purchase_stock/wizard/stock_replenishment_info.xml', 'primary', '{"en_US": "<data><field name=\"delay\" position=\"after\">\n                <field name=\"show_set_supplier_button\" column_invisible=\"True\"/>\n                <field name=\"last_purchase_date\"/>\n                <button name=\"action_set_supplier\" type=\"object\" string=\"Set as Supplier\" class=\"btn btn-link\" invisible=\"not show_set_supplier_button\"/>\n            </field>\n            <xpath expr=\"//tree\" position=\"attributes\">\n                <attribute name=\"decoration-bf\">parent.supplierinfo_id == id</attribute>\n            </xpath>\n            <field name=\"min_qty\" position=\"attributes\">\n                <attribute name=\"decoration-danger\">min_qty &gt; parent.qty_to_order</attribute>\n            </field>\n            <field name=\"company_id\" position=\"attributes\">\n                <attribute name=\"optional\">hide</attribute>\n            </field>\n            <field name=\"delay\" position=\"attributes\">\n                <attribute name=\"optional\">show</attribute>\n            </field>\n        </data>"}', '<?xml version="1.0"?>
<data><field name="delay" position="after">
                <field name="show_set_supplier_button" column_invisible="True"/>
                <field name="last_purchase_date"/>
                <button name="action_set_supplier" type="object" string="Set as Supplier" class="btn btn-link" invisible="not show_set_supplier_button"/>
            </field>
            <xpath expr="//tree" position="attributes">
                <attribute name="decoration-bf">parent.supplierinfo_id == id</attribute>
            </xpath>
            <field name="min_qty" position="attributes">
                <attribute name="decoration-danger">min_qty &gt; parent.qty_to_order</attribute>
            </field>
            <field name="company_id" position="attributes">
                <attribute name="optional">hide</attribute>
            </field>
            <field name="delay" position="attributes">
                <attribute name="optional">show</attribute>
            </field>
        </data>', false, true, '2026-05-10 01:12:32.247193', '2026-05-10 01:12:32.247193', false);
INSERT INTO public.ir_ui_view VALUES (1235, 16, 991, 1, 1, 'stock.replenishment.information.purchase.stock.inherit', 'stock.replenishment.info', NULL, 'form', 'purchase_stock/wizard/stock_replenishment_info.xml', 'extension', '{"en_US": "<xpath expr=\"//page\" position=\"before\">\n                <page string=\"Vendors\" name=\"page_vendors\">\n                    <field name=\"supplierinfo_id\" invisible=\"1\"/>\n                    <field name=\"supplierinfo_ids\" readonly=\"1\" context=\"{''tree_view_ref'': ''purchase_stock.product_supplierinfo_replenishment_tree_view'', ''stock_replenishment_info_id'': id, ''orderpoint_id'': orderpoint_id}\"/>\n                </page>\n            </xpath>"}', '<?xml version="1.0"?>
