INSERT INTO public.ir_ui_view VALUES (1236, 16, 997, 1, 1, 'product.replenish.form.inherit.stock', 'product.replenish', NULL, 'form', 'purchase_stock/wizard/product_replenish_views.xml', 'extension', '{"en_US": "<xpath expr=\"//field[@name=''route_id'']\" position=\"after\">\n                <label for=\"supplier_id\" invisible=\"not show_vendor\"/>\n                <div class=\"o_row\">\n                    <field name=\"show_vendor\" invisible=\"1\"/>\n                    <field name=\"supplier_id\" invisible=\"not show_vendor\" required=\"show_vendor\" domain=\"[(''product_tmpl_id'', ''='', product_tmpl_id)]\" options=\"{''no_open'': 1, ''no_create'': 1}\"/>\n                </div>\n            </xpath>"}', '<?xml version="1.0"?>
