INSERT INTO public.ir_ui_view VALUES (1237, 16, NULL, 1, 1, 'Message: Alert on purchase orders when ordered quantity decreased on Sales Orders', NULL, 'sale_purchase.exception_purchase_on_sale_quantity_decreased', 'qweb', 'sale_purchase/data/mail_templates.xml', 'primary', '{"en_US": "<t name=\"Message: Alert on purchase orders when ordered quantity decreased on Sales Orders\" t-name=\"sale_purchase.exception_purchase_on_sale_quantity_decreased\">\n    <div>\n        <p>\n            Exception(s) occurred on the sale order(s):\n            <t t-foreach=\"sale_orders\" t-as=\"sale_order\">\n                <a href=\"#\" data-oe-model=\"sale.order\" t-att-data-oe-id=\"sale_order.id\"><t t-esc=\"sale_order.name\"/></a>.\n            </t>\n            Manual actions may be needed.\n        </p>\n        <div class=\"mt16\">\n            <p>Exception(s):</p>\n            <ul t-foreach=\"sale_lines\" t-as=\"sale_line\">\n                <li>\n                    <t t-set=\"new_qty\" t-value=\"sale_line.product_uom_qty\"/>\n                    <t t-set=\"old_qty\" t-value=\"origin_values.get(sale_line.id, 0.0)\"/>\n\n                    <a href=\"#\" data-oe-model=\"sale.order\" t-att-data-oe-id=\"sale_line.order_id.id\"><t t-esc=\"sale_line.order_id.name\"/></a>:\n                    <t t-esc=\"new_qty\"/> <t t-esc=\"sale_line.product_uom.name\"/> of <t t-esc=\"sale_line.product_id.name\"/> ordered instead of <t t-esc=\"old_qty\"/> <t t-esc=\"sale_line.product_uom.name\"/>\n                  </li>\n            </ul>\n        </div>\n    </div>\n</t>"}', '<?xml version="1.0"?>
<t name="Message: Alert on purchase orders when ordered quantity decreased on Sales Orders" t-name="sale_purchase.exception_purchase_on_sale_quantity_decreased">
    <div>
        <p>
            Exception(s) occurred on the sale order(s):
            <t t-foreach="sale_orders" t-as="sale_order">
                <a href="#" data-oe-model="sale.order" t-att-data-oe-id="sale_order.id"><t t-esc="sale_order.name"/></a>.
            </t>
            Manual actions may be needed.
        </p>
        <div class="mt16">
            <p>Exception(s):</p>
            <ul t-foreach="sale_lines" t-as="sale_line">
                <li>
                    <t t-set="new_qty" t-value="sale_line.product_uom_qty"/>
                    <t t-set="old_qty" t-value="origin_values.get(sale_line.id, 0.0)"/>

                    <a href="#" data-oe-model="sale.order" t-att-data-oe-id="sale_line.order_id.id"><t t-esc="sale_line.order_id.name"/></a>:
                    <t t-esc="new_qty"/> <t t-esc="sale_line.product_uom.name"/> of <t t-esc="sale_line.product_id.name"/> ordered instead of <t t-esc="old_qty"/> <t t-esc="sale_line.product_uom.name"/>
                  </li>
            </ul>
        </div>
    </div>
</t>

', false, true, '2026-05-10 01:12:33.365524', '2026-05-10 01:12:33.365524', false);
INSERT INTO public.ir_ui_view VALUES (1238, 16, NULL, 1, 1, 'Message: Alert on purchase orders when sales orders are cancelled', NULL, 'sale_purchase.exception_purchase_on_sale_cancellation', 'qweb', 'sale_purchase/data/mail_templates.xml', 'primary', '{"en_US": "<t name=\"Message: Alert on purchase orders when sales orders are cancelled\" t-name=\"sale_purchase.exception_purchase_on_sale_cancellation\">\n    <div>\n        <p>\n            Exception(s) occurred on the sale order(s):\n            <t t-foreach=\"sale_orders\" t-as=\"sale_order\">\n                <a href=\"#\" data-oe-model=\"sale.order\" t-att-data-oe-id=\"sale_order.id\"><t t-esc=\"sale_order.name\"/></a>\n            </t>.\n            Manual actions may be needed.\n        </p>\n        <div class=\"mt16\">\n            <p>Exception(s):</p>\n            <ul t-foreach=\"sale_order_lines\" t-as=\"sale_line\">\n                <li>\n                    <a href=\"#\" data-oe-model=\"sale.order\" t-att-data-oe-id=\"sale_line.order_id.id\"><t t-esc=\"sale_line.order_id.name\"/></a>: <t t-esc=\"sale_line.product_uom_qty\"/> <t t-esc=\"sale_line.product_uom.name\"/> of <t t-esc=\"sale_line.product_id.name\"/> cancelled\n                </li>\n            </ul>\n        </div>\n    </div>\n</t>"}', '<?xml version="1.0"?>
<t name="Message: Alert on purchase orders when sales orders are cancelled" t-name="sale_purchase.exception_purchase_on_sale_cancellation">
    <div>
        <p>
            Exception(s) occurred on the sale order(s):
            <t t-foreach="sale_orders" t-as="sale_order">
                <a href="#" data-oe-model="sale.order" t-att-data-oe-id="sale_order.id"><t t-esc="sale_order.name"/></a>
            </t>.
            Manual actions may be needed.
        </p>
        <div class="mt16">
            <p>Exception(s):</p>
            <ul t-foreach="sale_order_lines" t-as="sale_line">
                <li>
                    <a href="#" data-oe-model="sale.order" t-att-data-oe-id="sale_line.order_id.id"><t t-esc="sale_line.order_id.name"/></a>: <t t-esc="sale_line.product_uom_qty"/> <t t-esc="sale_line.product_uom.name"/> of <t t-esc="sale_line.product_id.name"/> cancelled
                </li>
            </ul>
        </div>
    </div>
