INSERT INTO public.ir_ui_view VALUES (1239, 16, NULL, 1, 1, 'Message: Alert on sale orders when purchase orders are cancelled', NULL, 'sale_purchase.exception_sale_on_purchase_cancellation', 'qweb', 'sale_purchase/data/mail_templates.xml', 'primary', '{"en_US": "<t name=\"Message: Alert on sale orders when purchase orders are cancelled\" t-name=\"sale_purchase.exception_sale_on_purchase_cancellation\">\n    <div>\n        <p>\n            Exception(s) occurred on the purchase order(s):\n            <t t-foreach=\"purchase_orders\" t-as=\"purchase_order\">\n                <a href=\"#\" data-oe-model=\"purchase.order\" t-att-data-oe-id=\"purchase_order.id\"><t t-esc=\"purchase_order.name\"/></a>\n            </t>.\n            Manual actions may be needed.\n        </p>\n        <div class=\"mt16\">\n            <p>Exception(s):</p>\n            <ul t-foreach=\"purchase_order_lines\" t-as=\"purchase_line\">\n                <li>\n                    <a href=\"#\" data-oe-model=\"purchase.order\" t-att-data-oe-id=\"purchase_line.order_id.id\"><t t-esc=\"purchase_line.order_id.name\"/></a>: <t t-esc=\"purchase_line.product_qty\"/> <t t-esc=\"purchase_line.product_uom.name\"/> of <t t-esc=\"purchase_line.product_id.name\"/> cancelled\n                </li>\n            </ul>\n        </div>\n    </div>\n</t>"}', '<?xml version="1.0"?>
<t name="Message: Alert on sale orders when purchase orders are cancelled" t-name="sale_purchase.exception_sale_on_purchase_cancellation">
    <div>
        <p>
            Exception(s) occurred on the purchase order(s):
            <t t-foreach="purchase_orders" t-as="purchase_order">
                <a href="#" data-oe-model="purchase.order" t-att-data-oe-id="purchase_order.id"><t t-esc="purchase_order.name"/></a>
            </t>.
            Manual actions may be needed.
        </p>
        <div class="mt16">
            <p>Exception(s):</p>
            <ul t-foreach="purchase_order_lines" t-as="purchase_line">
                <li>
                    <a href="#" data-oe-model="purchase.order" t-att-data-oe-id="purchase_line.order_id.id"><t t-esc="purchase_line.order_id.name"/></a>: <t t-esc="purchase_line.product_qty"/> <t t-esc="purchase_line.product_uom.name"/> of <t t-esc="purchase_line.product_id.name"/> cancelled
                </li>
            </ul>
        </div>
    </div>
</t>

', false, true, '2026-05-10 01:12:33.365524', '2026-05-10 01:12:33.365524', false);
