INSERT INTO public.mail_template VALUES (1, 98, NULL, NULL, NULL, 1, 1, 'auth_signup/data/mail_template_data.xml', '{{ object.lang }}', 'res.users', '{{ (object.company_id.email_formatted or user.email_formatted) }}', '{{ object.email_formatted }}', NULL, NULL, NULL, NULL, NULL, '{"en_US": "Settings: New Portal Signup"}', '{"en_US": "Sent to new user after you invited them"}', '{"en_US": "{{ object.create_uid.name }} from {{ object.company_id.name }} invites you to connect to Odoo"}', '{"en_US": "<table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" style=\"padding-top: 16px; background-color: #FFFFFF; font-family:Verdana, Arial,sans-serif; color: #454748; width: 100%; border-collapse:separate;\"><tr><td align=\"center\">\n<table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"590\" style=\"padding: 16px; background-color: #FFFFFF; color: #454748; border-collapse:separate;\">\n<tbody>\n    <!-- HEADER -->\n    <tr>\n        <td align=\"center\" style=\"min-width: 590px;\">\n            <table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"590\" style=\"min-width: 590px; background-color: white; padding: 0px 8px 0px 8px; border-collapse:separate;\">\n                <tr><td valign=\"middle\">\n                    <span style=\"font-size: 10px;\">Welcome to Odoo</span><br>\n                    <span style=\"font-size: 20px; font-weight: bold;\">\n                        <t t-out=\"object.name or ''''\">Marc Demo</t>\n                    </span>\n                </td><td valign=\"middle\" align=\"right\" t-if=\"not object.company_id.uses_default_logo\">\n                    <img t-attf-src=\"/logo.png?company={{ object.company_id.id }}\" style=\"padding: 0px; margin: 0px; height: auto; width: 80px;\" t-att-alt=\"object.company_id.name\">\n                </td></tr>\n                <tr><td colspan=\"2\" style=\"text-align:center;\">\n                  <hr width=\"100%\" style=\"background-color:rgb(204,204,204);border:medium none;clear:both;display:block;font-size:0px;min-height:1px;line-height:0; margin: 16px 0px 16px 0px;\">\n                </td></tr>\n            </table>\n        </td>\n    </tr>\n    <!-- CONTENT -->\n    <tr>\n        <td align=\"center\" style=\"min-width: 590px;\">\n            <table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"590\" style=\"min-width: 590px; background-color: white; padding: 0px 8px 0px 8px; border-collapse:separate;\">\n                <tr><td valign=\"top\" style=\"font-size: 13px;\">\n                    <div>\n                        Dear <t t-out=\"object.name or ''''\">Marc Demo</t>,<br><br>\n                        You have been invited by <t t-out=\"object.create_uid.name or ''''\">OdooBot</t> of <t t-out=\"object.company_id.name or ''''\">YourCompany</t> to connect on Odoo.\n                        <div style=\"margin: 16px 0px 16px 0px;\">\n                            <a t-att-href=\"object.signup_url\" style=\"background-color: #875A7B; padding: 8px 16px 8px 16px; text-decoration: none; color: #fff; border-radius: 5px; font-size:13px;\">\n                                Accept invitation\n                            </a>\n                        </div>\n                        <t t-set=\"website_url\" t-value=\"object.get_base_url()\"></t>\n                        Your Odoo domain is: <b><a t-att-href=\"website_url\" t-out=\"website_url or ''''\">http://yourcompany.odoo.com</a></b><br>\n                        Your sign in email is: <b><a t-attf-href=\"/web/login?login={{ object.email }}\" target=\"_blank\" t-out=\"object.email or ''''\">mark.brown23@example.com</a></b><br><br>\n                        Never heard of Odoo? It’s an all-in-one business software loved by 7+ million users. It will considerably improve your experience at work and increase your productivity.\n                        <br><br>\n                        Have a look at the <a href=\"https://www.odoo.com/page/tour?utm_source=db&amp;utm_medium=auth\" style=\"color: #875A7B;\">Odoo Tour</a> to discover the tool.\n                        <br><br>\n                        Enjoy Odoo!<br>\n                        --<br>The <t t-out=\"object.company_id.name or ''''\">YourCompany</t> Team\n                    </div>\n                </td></tr>\n                <tr><td style=\"text-align:center;\">\n                  <hr width=\"100%\" style=\"background-color:rgb(204,204,204);border:medium none;clear:both;display:block;font-size:0px;min-height:1px;line-height:0; margin: 16px 0px 16px 0px;\">\n                </td></tr>\n            </table>\n        </td>\n    </tr>\n    <!-- FOOTER -->\n    <tr>\n        <td align=\"center\" style=\"min-width: 590px;\">\n            <table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"590\" style=\"min-width: 590px; background-color: white; font-size: 11px; padding: 0px 8px 0px 8px; border-collapse:separate;\">\n                <tr><td valign=\"middle\" align=\"left\">\n                    <t t-out=\"object.company_id.name or ''''\">YourCompany</t>\n                </td></tr>\n                <tr><td valign=\"middle\" align=\"left\" style=\"opacity: 0.7;\">\n                    <t t-out=\"object.company_id.phone or ''''\">+1 650-123-4567</t>\n                    <t t-if=\"object.company_id.email\">\n                        | <a t-att-href=\"''mailto:%s'' % object.company_id.email\" style=\"text-decoration:none; color: #454748;\" t-out=\"object.company_id.email or ''''\">info@yourcompany.com</a>\n                    </t>\n                    <t t-if=\"object.company_id.website\">\n                        | <a t-att-href=\"''%s'' % object.company_id.website\" style=\"text-decoration:none; color: #454748;\" t-out=\"object.company_id.website or ''''\">http://www.example.com</a>\n                    </t>\n                </td></tr>\n            </table>\n        </td>\n    </tr>\n</tbody>\n</table>\n</td></tr>\n<!-- POWERED BY -->\n<tr><td align=\"center\" style=\"min-width: 590px;\">\n    <table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"590\" style=\"min-width: 590px; background-color: #F1F1F1; color: #454748; padding: 8px; border-collapse:separate;\">\n      <tr><td style=\"text-align: center; font-size: 13px;\">\n        Powered by <a target=\"_blank\" href=\"https://www.odoo.com?utm_source=db&amp;utm_medium=auth\" style=\"color: #875A7B;\">Odoo</a>\n      </td></tr>\n    </table>\n</td></tr>\n</table>"}', true, NULL, true, '2026-05-10 01:11:47.474459', '2026-05-10 01:11:47.474459');
INSERT INTO public.mail_template VALUES (2, 98, NULL, NULL, NULL, 1, 1, 'auth_signup/data/mail_template_data.xml', '{{ object.partner_id.lang }}', 'res.users', '{{ (object.company_id.email_formatted or user.email_formatted) }}', '{{ object.email_formatted }}', NULL, NULL, NULL, NULL, NULL, '{"en_US": "Settings: Unregistered User Reminder"}', '{"en_US": "Sent automatically to admin if new user haven''t responded to the invitation"}', '{"en_US": "Reminder for unregistered users"}', '{"en_US": "<table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" style=\"background-color: #FFFFFF; font-family:Verdana, Arial,sans-serif; color: #454748; width: 100%; border-collapse:separate;\"><tr><td align=\"center\">\n<table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"590\" style=\"padding: 16px; background-color: #FFFFFF; color: #454748; border-collapse:separate;\">\n<tbody>\n    <!-- CONTENT -->\n    <tr>\n        <td align=\"center\" style=\"min-width: 590px;\">\n            <table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"590\" style=\"min-width: 590px; background-color: white; padding: 0px 8px 0px 8px; border-collapse:separate;\">\n                <t t-set=\"invited_users\" t-value=\"ctx.get(''invited_users'', [])\"></t>\n                <td style=\"text-align : left\">\n                    <span style=\"font-size: 20px; font-weight: bold;\">\n                        Pending Invitations\n                    </span><br><br>\n                </td>\n                <tr><td valign=\"top\" style=\"font-size: 13px;\">\n                    <div>\n                        Dear <t t-out=\"object.name or ''''\">Mitchell Admin</t>,<br> <br>\n                        You added the following user(s) to your database but they haven''t registered yet:\n                        <ul>\n                            <t t-foreach=\"invited_users\" t-as=\"invited_user\">\n                                <li t-out=\"invited_user or ''''\">demo@example.com</li>\n                            </t>\n                        </ul>\n                        Follow up with them so they can access your database and start working with you.\n                        <br><br>\n                        Have a nice day!<br>\n                        --<br>The <t t-out=\"object.company_id.name or ''''\">YourCompany</t> Team\n                    </div>\n                </td></tr>\n                <tr><td style=\"text-align:center;\">\n                  <hr width=\"100%\" style=\"background-color:rgb(204,204,204);border:medium none;clear:both;display:block;font-size:0px;min-height:1px;line-height:0; margin: 16px 0px 16px 0px;\">\n                </td></tr>\n            </table>\n        </td>\n    </tr>\n</tbody>\n</table>\n</td></tr>\n</table>\n            "}', true, NULL, true, '2026-05-10 01:11:47.474459', '2026-05-10 01:11:47.474459');
INSERT INTO public.mail_template VALUES (3, 98, NULL, NULL, NULL, 1, 1, 'auth_signup/data/mail_template_data.xml', '{{ object.lang }}', 'res.users', '{{ (object.company_id.email_formatted or user.email_formatted) }}', '{{ object.email_formatted }}', NULL, NULL, NULL, NULL, NULL, '{"en_US": "Settings: New User Invite"}', '{"en_US": "Sent to portal user who registered themselves"}', '{"en_US": "Welcome to {{ object.company_id.name }}!"}', '{"en_US": "<table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" style=\"padding-top: 16px; background-color: #FFFFFF; font-family:Verdana, Arial,sans-serif; color: #454748; width: 100%; border-collapse:separate;\"><tr><td align=\"center\">\n<table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"590\" style=\"padding: 16px; background-color: #FFFFFF; color: #454748; border-collapse:separate;\">\n<tbody>\n    <!-- HEADER -->\n    <tr>\n        <td align=\"center\" style=\"min-width: 590px;\">\n            <table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"590\" style=\"min-width: 590px; background-color: white; padding: 0px 8px 0px 8px; border-collapse:separate;\">\n                <tr><td valign=\"middle\">\n                    <span style=\"font-size: 10px;\">Your Account</span><br>\n                    <span style=\"font-size: 20px; font-weight: bold;\">\n                        <t t-out=\"object.name or ''''\">Marc Demo</t>\n                    </span>\n                </td><td valign=\"middle\" align=\"right\" t-if=\"not object.company_id.uses_default_logo\">\n                    <img t-attf-src=\"/logo.png?company={{ object.company_id.id }}\" style=\"padding: 0px; margin: 0px; height: auto; width: 80px;\" t-att-alt=\"object.company_id.name\">\n                </td></tr>\n                <tr><td colspan=\"2\" style=\"text-align:center;\">\n                  <hr width=\"100%\" style=\"background-color:rgb(204,204,204);border:medium none;clear:both;display:block;font-size:0px;min-height:1px;line-height:0; margin: 16px 0px 16px 0px;\">\n                </td></tr>\n            </table>\n        </td>\n    </tr>\n    <!-- CONTENT -->\n    <tr>\n        <td align=\"center\" style=\"min-width: 590px;\">\n            <table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"590\" style=\"min-width: 590px; background-color: white; padding: 0px 8px 0px 8px; border-collapse:separate;\">\n                <tr><td valign=\"top\" style=\"font-size: 13px;\">\n                    <div>\n                        Dear <t t-out=\"object.name or ''''\">Marc Demo</t>,<br><br>\n                        Your account has been successfully created!<br>\n                        Your login is <strong><t t-out=\"object.email or ''''\">mark.brown23@example.com</t></strong><br>\n                        To gain access to your account, you can use the following link:\n                        <div style=\"margin: 16px 0px 16px 0px;\">\n                            <a t-attf-href=\"/web/login?auth_login={{object.email}}\" style=\"background-color: #875A7B; padding: 8px 16px 8px 16px; text-decoration: none; color: #fff; border-radius: 5px; font-size:13px;\">\n                                Go to My Account\n                            </a>\n                        </div>\n                        Thanks,<br>\n                        <t t-if=\"user.signature\">\n                            <br>\n                            <t t-out=\"user.signature or ''''\">--<br>Mitchell Admin</t>\n                        </t>\n                    </div>\n                </td></tr>\n                <tr><td style=\"text-align:center;\">\n                  <hr width=\"100%\" style=\"background-color:rgb(204,204,204);border:medium none;clear:both;display:block;font-size:0px;min-height:1px;line-height:0; margin: 16px 0px 16px 0px;\">\n                </td></tr>\n            </table>\n        </td>\n    </tr>\n    <!-- FOOTER -->\n    <tr>\n        <td align=\"center\" style=\"min-width: 590px;\">\n            <table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"590\" style=\"min-width: 590px; background-color: white; font-size: 11px; padding: 0px 8px 0px 8px; border-collapse:separate;\">\n                <tr><td valign=\"middle\" align=\"left\">\n                    <t t-out=\"object.company_id.name or ''''\">YourCompany</t>\n                </td></tr>\n                <tr><td valign=\"middle\" align=\"left\" style=\"opacity: 0.7;\">\n                    <t t-out=\"object.company_id.phone or ''''\">+1 650-123-4567</t>\n                    <t t-if=\"object.company_id.email\">\n                        | <a t-attf-href=\"mailto:{{object.company_id.email}}\" style=\"text-decoration:none; color: #454748;\" t-out=\"object.company_id.email or ''''\">info@yourcompany.com</a>\n                    </t>\n                    <t t-if=\"object.company_id.website\">\n                        | <a t-att-href=\"object.company_id.website\" style=\"text-decoration:none; color: #454748;\" t-out=\"object.company_id.website or ''''\">http://www.example.com</a>\n                    </t>\n                </td></tr>\n            </table>\n        </td>\n    </tr>\n</tbody>\n</table>\n</td></tr>\n<!-- POWERED BY -->\n<tr><td align=\"center\" style=\"min-width: 590px;\">\n    <table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"590\" style=\"min-width: 590px; background-color: #F1F1F1; color: #454748; padding: 8px; border-collapse:separate;\">\n      <tr><td style=\"text-align: center; font-size: 13px;\">\n        Powered by <a target=\"_blank\" href=\"https://www.odoo.com?utm_source=db&amp;utm_medium=auth\" style=\"color: #875A7B;\">Odoo</a>\n      </td></tr>\n    </table>\n</td></tr>\n</table>"}', true, NULL, true, '2026-05-10 01:11:47.474459', '2026-05-10 01:11:47.474459');
INSERT INTO public.mail_template VALUES (4, 98, NULL, NULL, NULL, 1, 1, 'auth_totp_mail/data/mail_template_data.xml', '{{ object.partner_id.lang }}', 'res.users', '{{ (object.company_id.email_formatted or user.email_formatted) }}', NULL, '{{ object.partner_id.id }}', NULL, NULL, NULL, NULL, '{"en_US": "Settings: 2Fa Invitation"}', NULL, '{"en_US": "Invitation to activate two-factor authentication on your Odoo account"}', '{"en_US": "<div style=\"margin: 0px; padding: 0px; font-size: 13px;\">\n    <p style=\"margin: 0px; padding: 0px; font-size: 13px;\">\n        Dear <t t-out=\"object.partner_id.name or ''''\"></t><br><br>\n        <t t-out=\"user.name  or ''''\"></t> requested you activate two-factor authentication to protect your account.<br><br>\n        Two-factor Authentication (\"2FA\") is a system of double authentication.\n        The first one is done with your password and the second one with a code you get from a dedicated mobile app.\n        Popular ones include Authy, Google Authenticator or the Microsoft Authenticator.\n\n        <p style=\"margin: 16px 0px 16px 0px; text-align: center;\">\n            <a t-att-href=\"object.get_totp_invite_url()\" style=\"background-color:#875A7B; padding: 8px 16px 8px 16px; text-decoration: none; color: #fff; border-radius: 5px;\">\n                Activate my two-factor Authentication\n            </a>\n        </p>\n    </p>\n</div>\n        "}', true, NULL, true, '2026-05-10 01:11:47.631208', '2026-05-10 01:11:47.631208');
INSERT INTO public.mail_template VALUES (5, 366, NULL, NULL, NULL, 1, 1, 'base_install_request/data/mail_template_data.xml', '{{ ctx[''partner''].lang or user.lang }}', 'base.module.install.request', '{{ object.user_id.email_formatted or user.email_formatted }}', NULL, '{{ ctx[''partner''].id}}', NULL, NULL, NULL, NULL, '{"en_US": "Mail: Install Request"}', NULL, '{"en_US": "Module Activation Request for \"{{ object.module_id.shortdesc }}\""}', '{"en_US": "<div style=\"margin: 0px; padding: 0px;\">\n    <p style=\"margin: 0px; padding: 0px; font-size: 13px;\">\n        Hello,\n        <br><br>\n        <span style=\"font-weight: bold;\" t-out=\"object.user_id.name\"></span> has requested to activate the <span style=\"font-weight: bold;\" t-out=\"object.module_id.shortdesc\"></span> module. This module is included in your subscription. It has <span style=\"color: #875A7B; font-weight: bold;\">no extra cost</span>, but an administrator role is required to activate it.\n        <br><br>\n        <blockquote>\n            <t t-out=\"object.body_html\"></t>\n        </blockquote>\n        <br><br>\n        <a style=\"background-color:#875A7B; padding:8px 16px 8px 16px; text-decoration:none; color:#fff; border-radius:5px\" t-attf-href=\"/web?#action=base_install_request.action_base_module_install_review&amp;active_id={{ object.module_id.id }}&amp;menu_id={{ ctx[''menu_id''] }}\">Review Request</a>\n        <br><br>\n        Thanks,\n        <t t-if=\"not is_html_empty(object.user_id.signature)\">\n            <br><br>\n            <t t-out=\"object.user_id.signature or ''''\">--<br>Mitchell Admin</t>\n        </t>\n        <br><br>\n    </p>\n</div>\n            "}', true, NULL, true, '2026-05-10 01:11:47.730558', '2026-05-10 01:11:47.730558');
INSERT INTO public.mail_template VALUES (6, 407, NULL, NULL, NULL, 1, 1, 'portal/data/mail_template_data.xml', '{{ object.partner_id.lang }}', 'portal.wizard.user', NULL, '{{ object.user_id.email_formatted }}', NULL, NULL, NULL, NULL, NULL, '{"en_US": "Portal: User Invite"}', '{"en_US": "Invitation email to contacts to create a user account"}', '{"en_US": "Your account at {{ object.user_id.company_id.name }}"}', '{"en_US": "<table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" style=\"padding-top: 16px; background-color: #F1F1F1; font-family:Verdana, Arial,sans-serif; color: #454748; width: 100%; border-collapse:separate;\"><tr><td align=\"center\">\n<table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"590\" style=\"padding: 16px; background-color: white; color: #454748; border-collapse:separate;\">\n<tbody>\n    <!-- HEADER -->\n    <tr>\n        <td align=\"center\" style=\"min-width: 590px;\">\n            <table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"590\" style=\"min-width: 590px; background-color: white; padding: 0px 8px 0px 8px; border-collapse:separate;\">\n                <tr><td valign=\"middle\">\n                    <span style=\"font-size: 10px;\">Your Account</span><br>\n                    <span style=\"font-size: 20px; font-weight: bold;\" t-out=\"object.user_id.name or ''''\">Marc Demo</span>\n                </td><td valign=\"middle\" align=\"right\" t-if=\"not object.user_id.company_id.uses_default_logo\">\n                    <img t-attf-src=\"/logo.png?company={{ object.user_id.company_id.id }}\" style=\"padding: 0px; margin: 0px; height: auto; width: 80px;\" t-att-alt=\"object.user_id.company_id.name\">\n                </td></tr>\n                <tr><td colspan=\"2\" style=\"text-align:center;\">\n                  <hr width=\"100%\" style=\"background-color:rgb(204,204,204);border:medium none;clear:both;display:block;font-size:0px;min-height:1px;line-height:0; margin:16px 0px 16px 0px;\">\n                </td></tr>\n            </table>\n        </td>\n    </tr>\n    <!-- CONTENT -->\n    <tr>\n        <td align=\"center\" style=\"min-width: 590px;\">\n            <table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"590\" style=\"min-width: 590px; background-color: white; padding: 0px 8px 0px 8px; border-collapse:separate;\">\n                <tr><td valign=\"top\" style=\"font-size: 13px;\">\n                    <div>\n                        Dear <t t-out=\"object.user_id.name or ''''\">Marc Demo</t>,<br> <br>\n                        Welcome to <t t-out=\"object.user_id.company_id.name\">YourCompany</t>''s Portal!<br><br>\n                        An account has been created for you with the following login: <t t-out=\"object.user_id.login\">demo</t><br><br>\n                        Click on the button below to pick a password and activate your account.\n                        <div style=\"margin: 16px 0px 16px 0px; text-align: center;\">\n                            <a t-att-href=\"object.user_id.signup_url\" style=\"display: inline-block; padding: 10px; text-decoration: none; font-size: 12px; background-color: #875A7B; color: #fff; border-radius: 5px;\">\n                                <strong>Activate Account</strong>\n                            </a>\n                        </div>\n                        <t t-out=\"object.wizard_id.welcome_message or ''''\">Welcome to our company''s portal.</t>\n                    </div>\n                </td></tr>\n                <tr><td style=\"text-align:center;\">\n                  <hr width=\"100%\" style=\"background-color:rgb(204,204,204);border:medium none;clear:both;display:block;font-size:0px;min-height:1px;line-height:0; margin: 16px 0px 16px 0px;\">\n                </td></tr>\n            </table>\n        </td>\n    </tr>\n    <!-- FOOTER -->\n    <tr>\n        <td align=\"center\" style=\"min-width: 590px;\">\n            <table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"590\" style=\"min-width: 590px; background-color: white; font-size: 11px; padding: 0px 8px 0px 8px; border-collapse:separate;\">\n                <tr><td valign=\"middle\" align=\"left\">\n                    <t t-out=\"object.user_id.company_id.name or ''''\">YourCompany</t>\n                </td></tr>\n                <tr><td valign=\"middle\" align=\"left\" style=\"opacity: 0.7;\">\n                    <t t-out=\"object.user_id.company_id.phone or ''''\">+1 650-123-4567</t>\n                    <t t-if=\"object.user_id.company_id.email\">\n                        | <a t-attf-href=\"''mailto:%s'' % {{ object.user_id.company_id.email }}\" style=\"text-decoration:none; color: #454748;\" t-out=\"object.user_id.company_id.email or ''''\">info@yourcompany.com</a>\n                    </t>\n                    <t t-if=\"object.user_id.company_id.website\">\n                        | <a t-attf-href=\"''%s'' % {{ object.user_id.company_id.website }}\" style=\"text-decoration:none; color: #454748;\" t-out=\"object.user_id.company_id.website or ''''\">http://www.example.com</a>\n                    </t>\n                </td></tr>\n            </table>\n        </td>\n    </tr>\n</tbody>\n</table>\n</td></tr>\n<!-- POWERED BY -->\n<tr><td align=\"center\" style=\"min-width: 590px;\">\n    <table border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"590\" style=\"min-width: 590px; background-color: #F1F1F1; color: #454748; padding: 8px; border-collapse:separate;\">\n      <tr><td style=\"text-align: center; font-size: 13px;\">\n        Powered by <a target=\"_blank\" href=\"https://www.odoo.com?utm_source=db&amp;utm_medium=portalinvite\" style=\"color: #875A7B;\">Odoo</a>\n      </td></tr>\n    </table>\n</td></tr>\n</table>\n            "}', true, NULL, true, '2026-05-10 01:11:52.573269', '2026-05-10 01:11:52.573269');
INSERT INTO public.mail_template VALUES (7, 451, NULL, NULL, NULL, 1, 1, 'account/data/mail_template_data.xml', '{{ object.partner_id.lang }}', 'account.move', '{{ (object.invoice_user_id.email_formatted or object.company_id.email_formatted or user.email_formatted) }}', NULL, '{{ object.partner_id.id }}', NULL, NULL, NULL, NULL, '{"en_US": "Invoice: Sending"}', '{"en_US": "Sent to customers with their invoices in attachment"}', '{"en_US": "{{ object.company_id.name }} Invoice (Ref {{ object.name or ''n/a'' }})"}', '{"en_US": "<div style=\"margin: 0px; padding: 0px;\">\n    <p style=\"margin: 0px; padding: 0px; font-size: 13px;\">\n        Dear\n        <t t-if=\"object.partner_id.parent_id\">\n            <t t-out=\"object.partner_id.name or ''''\">Brandon Freeman</t> (<t t-out=\"object.partner_id.parent_id.name or ''''\">Azure Interior</t>),\n        </t>\n        <t t-else=\"\">\n            <t t-out=\"object.partner_id.name or ''''\">Brandon Freeman</t>,\n        </t>\n        <br><br>\n        Here is your\n        <t t-if=\"object.name\">\n            invoice <span style=\"font-weight:bold;\" t-out=\"object.name or ''''\">INV/2021/05/0005</span>\n        </t>\n        <t t-else=\"\">\n            invoice\n        </t>\n        <t t-if=\"object.invoice_origin\">\n            (with reference: <t t-out=\"object.invoice_origin or ''''\">SUB003</t>)\n        </t>\n        amounting in <span style=\"font-weight:bold;\" t-out=\"format_amount(object.amount_total, object.currency_id) or ''''\">$ 143,750.00</span>\n        from <t t-out=\"object.company_id.name or ''''\">YourCompany</t>.\n        <t t-if=\"object.payment_state in (''paid'', ''in_payment'')\">\n            This invoice is already paid.\n        </t>\n        <t t-else=\"\">\n            Please remit payment at your earliest convenience.\n            <t t-if=\"object.payment_reference\">\n                <br><br>\n                Please use the following communication for your payment: <strong t-out=\"object.payment_reference or ''''\">INV/2021/05/0005</strong>\n                <t t-if=\"object.partner_bank_id\">\n                    on the account <strong t-out=\"object.partner_bank_id.acc_number\"></strong>\n                </t>\n                .\n            </t>\n        </t>\n        <t t-if=\"hasattr(object, ''timesheet_count'') and object.timesheet_count\">\n            <br><br>\n            PS: you can review your timesheets <a t-att-href=\"''my/timesheets?search_in=invoice&amp;search=%s'' % object.name\">from the portal.</a>\n        </t>\n        <br><br>\n        Do not hesitate to contact us if you have any questions.\n        <t t-if=\"not is_html_empty(object.invoice_user_id.signature)\">\n            <br><br>\n            <t t-out=\"object.invoice_user_id.signature or ''''\">--<br>Mitchell Admin</t>\n        </t>\n    </p>\n</div>\n            "}', true, NULL, true, '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295');
INSERT INTO public.mail_template VALUES (9, 451, NULL, NULL, NULL, 1, 1, 'account/data/mail_template_data.xml', '{{ object.partner_id.lang }}', 'account.move', '{{ (object.invoice_user_id.email_formatted or object.company_id.email_formatted or user.email_formatted) }}', NULL, '{{ object.partner_id.id }}', NULL, NULL, NULL, NULL, '{"en_US": "Credit Note: Sending"}', '{"en_US": "Sent to customers with the credit note in attachment"}', '{"en_US": "{{ object.company_id.name }} Credit Note (Ref {{ object.name or ''n/a'' }})"}', '{"en_US": "<div style=\"margin: 0px; padding: 0px;\">\n    <p style=\"margin: 0px; padding: 0px; font-size: 13px;\">\n        Dear\n        <t t-if=\"object.partner_id.parent_id\">\n            <t t-out=\"object.partner_id.name or ''''\">Brandon Freeman</t> (<t t-out=\"object.partner_id.parent_id.name or ''''\">Azure Interior</t>),\n        </t>\n        <t t-else=\"\">\n            <t t-out=\"object.partner_id.name or ''''\">Brandon Freeman</t>,\n        </t>\n        <br><br>\n        Here is your\n        <t t-if=\"object.name\">\n            credit note <span style=\"font-weight:bold;\" t-out=\"object.name or ''''\">RINV/2021/05/0001</span>\n        </t>\n        <t t-else=\"\">\n            credit note\n        </t>\n        <t t-if=\"object.invoice_origin\">\n            (with reference: <t t-out=\"object.invoice_origin or ''''\">SUB003</t>)\n        </t>\n        amounting in <span style=\"font-weight:bold;\" t-out=\"format_amount(object.amount_total, object.currency_id) or ''''\">$ 143,750.00</span>\n        from <t t-out=\"object.company_id.name or ''''\">YourCompany</t>.\n        <br><br>\n        Do not hesitate to contact us if you have any questions.\n        <t t-if=\"not is_html_empty(object.invoice_user_id.signature)\">\n            <br><br>\n            <t t-out=\"object.invoice_user_id.signature or ''''\">--<br>Mitchell Admin</t>\n        </t>\n    </p>\n</div>\n            "}', true, NULL, true, '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295');
INSERT INTO public.mail_template VALUES (8, 455, NULL, NULL, NULL, 1, 1, 'account/data/mail_template_data.xml', '{{ object.partner_id.lang }}', 'account.payment', NULL, NULL, '{{ object.partner_id.id }}', NULL, NULL, NULL, NULL, '{"en_US": "Payment: Payment Receipt"}', '{"en_US": "Sent manually to customer when clicking on ''Send receipt by email'' in payment action"}', '{"en_US": "{{ object.company_id.name }} Payment Receipt (Ref {{ object.name or ''n/a'' }})"}', '{"en_US": "<div style=\"margin: 0px; padding: 0px;\">\n    <p style=\"margin: 0px; padding: 0px; font-size: 13px;\">\n        Dear <t t-out=\"object.partner_id.name or ''''\">Azure Interior</t><br><br>\n        Thank you for your payment.\n        Here is your payment receipt <span style=\"font-weight:bold;\" t-out=\"(object.name or '''').replace(''/'',''-'') or ''''\">BNK1-2021-05-0002</span> amounting\n        to <span style=\"font-weight:bold;\" t-out=\"format_amount(object.amount, object.currency_id) or ''''\">$ 10.00</span> from <t t-out=\"object.company_id.name or ''''\">YourCompany</t>.\n        <br><br>\n        Do not hesitate to contact us if you have any questions.\n        <br><br>\n        Best regards,\n        <t t-if=\"not is_html_empty(user.signature)\">\n            <br><br>\n            <t t-out=\"user.signature or ''''\">--<br>Mitchell Admin</t>\n        </t>\n    </p>\n</div>\n"}', true, NULL, true, '2026-05-10 01:11:56.885295', '2026-05-10 01:11:56.885295');
INSERT INTO public.mail_template VALUES (10, 499, NULL, NULL, NULL, 1, 1, 'sale/data/mail_template_data.xml', '{{ object.partner_id.lang }}', 'sale.order', '{{ (object.user_id.email_formatted or object.company_id.email_formatted or user.email_formatted) }}', NULL, '{{ object.partner_id.id }}', NULL, NULL, NULL, NULL, '{"en_US": "Sales: Send Quotation"}', '{"en_US": "Used by salespeople when they send quotations or proforma to prospects"}', '{"en_US": "{{ object.company_id.name }} {{ object.state in (''draft'', ''sent'') and (ctx.get(''proforma'') and ''Proforma'' or ''Quotation'') or ''Order'' }} (Ref {{ object.name or ''n/a'' }})"}', '{"en_US": "<div style=\"margin: 0px; padding: 0px;\">\n    <p style=\"margin: 0px; padding: 0px; font-size: 13px;\">\n        <t t-set=\"doc_name\" t-value=\"''quotation'' if object.state in (''draft'', ''sent'') else ''order''\"></t>\n        Hello,\n        <br><br>\n        Your\n        <t t-if=\"ctx.get(''proforma'')\">\n            Pro forma invoice for <t t-out=\"doc_name or ''''\">quotation</t> <span style=\"font-weight: bold;\" t-out=\"object.name or ''''\">S00052</span>\n            <t t-if=\"object.origin\">\n                (with reference: <t t-out=\"object.origin or ''''\"></t> )\n            </t>\n            amounting in <span style=\"font-weight: bold;\" t-out=\"format_amount(object.amount_total, object.currency_id) or ''''\">$ 10.00</span> is available.\n        </t>\n        <t t-else=\"\">\n            <t t-out=\"doc_name or ''''\">quotation</t> <span style=\"font-weight: bold;\" t-out=\"object.name or ''''\"></span>\n            <t t-if=\"object.origin\">\n                (with reference: <t t-out=\"object.origin or ''''\">S00052</t> )\n            </t>\n            amounting in <span style=\"font-weight: bold;\" t-out=\"format_amount(object.amount_total, object.currency_id) or ''''\">$ 10.00</span> is ready for review.\n        </t>\n        <br><br>\n        Do not hesitate to contact us if you have any questions.\n        <t t-if=\"not is_html_empty(object.user_id.signature)\">\n            <br><br>\n            <t t-out=\"object.user_id.signature or ''''\">--<br>Mitchell Admin</t>\n        </t>\n        <br><br>\n    </p>\n</div>\n            "}', true, NULL, true, '2026-05-10 01:12:05.269262', '2026-05-10 01:12:05.269262');
INSERT INTO public.mail_template VALUES (11, 499, NULL, NULL, NULL, 1, 1, 'sale/data/mail_template_data.xml', '{{ object.partner_id.lang }}', 'sale.order', '{{ (object.user_id.email_formatted or object.company_id.email_formatted or user.email_formatted) }}', NULL, '{{ object.partner_id.id }}', NULL, NULL, NULL, NULL, '{"en_US": "Sales: Order Confirmation"}', '{"en_US": "Sent to customers on order confirmation"}', '{"en_US": "{{ object.company_id.name }} {{ (object.get_portal_last_transaction().state == ''pending'') and ''Pending Order'' or ''Order'' }} (Ref {{ object.name or ''n/a'' }})"}', '{"en_US": "<div style=\"margin: 0px; padding: 0px;\">\n    <p style=\"margin: 0px; padding: 0px; font-size: 12px;\">\n        Hello,\n        <br><br>\n        <t t-set=\"tx_sudo\" t-value=\"object.get_portal_last_transaction()\"></t>\n        Your order <span style=\"font-weight:bold;\" t-out=\"object.name or ''''\">S00049</span> amounting in <span style=\"font-weight:bold;\" t-out=\"format_amount(object.amount_total, object.currency_id) or ''''\">$ 10.00</span>\n        <t t-if=\"object.state == ''sale'' or (tx_sudo and tx_sudo.state in (''done'', ''authorized''))\">\n            has been confirmed.<br>\n            Thank you for your trust!\n        </t>\n        <t t-elif=\"tx_sudo and tx_sudo.state == ''pending''\">\n            is pending. It will be confirmed when the payment is received.\n            <t t-if=\"object.reference\">\n                Your payment reference is <span style=\"font-weight:bold;\" t-out=\"object.reference or ''''\"></span>.\n            </t>\n        </t>\n        <br><br>\n        Do not hesitate to contact us if you have any questions.\n        <t t-if=\"not is_html_empty(object.user_id.signature)\">\n            <br><br>\n            <t t-out=\"object.user_id.signature or ''''\">--<br>Mitchell Admin</t>\n        </t>\n        <br><br>\n    </p>\n<t t-if=\"hasattr(object, ''website_id'') and object.website_id\">\n    <div style=\"margin: 0px; padding: 0px;\">\n        <table width=\"100%\" style=\"color: #454748; font-size: 12px; border-collapse: collapse;\">\n            <tr style=\"border-bottom: 2px solid #dee2e6;\">\n                <td style=\"width: 150px;\"><span style=\"font-weight:bold;\">Products</span></td>\n                <td></td>\n                <td width=\"15%\" align=\"center\"><span style=\"font-weight:bold;\">Quantity</span></td>\n                <td width=\"20%\" align=\"right\">\n                    <span style=\"font-weight:bold;\">\n                        <t t-if=\"object.website_id.show_line_subtotals_tax_selection == ''tax_excluded''\">\n                            VAT Excl.\n                        </t>\n                        <t t-else=\"\">\n                            VAT Incl.\n                        </t>\n                    </span>\n                </td>\n            </tr>\n        </table>\n        <t t-foreach=\"object.order_line\" t-as=\"line\">\n            <t t-if=\"(not hasattr(line, ''is_delivery'') or not line.is_delivery) and line.display_type in [''line_section'', ''line_note'']\">\n                <table width=\"100%\" style=\"color: #454748; font-size: 12px; border-collapse: collapse;\">\n                    <t t-set=\"loop_cycle_number\" t-value=\"loop_cycle_number or 0\"></t>\n                    <tr t-att-style=\"''background-color: #f2f2f2'' if loop_cycle_number % 2 == 0 else ''background-color: #ffffff''\">\n                        <t t-set=\"loop_cycle_number\" t-value=\"loop_cycle_number + 1\"></t>\n                        <td colspan=\"4\">\n                            <t t-if=\"line.display_type == ''line_section''\">\n                                <span style=\"font-weight:bold;\" t-out=\"line.name or ''''\">Taking care of Trees Course</span>\n                            </t>\n                            <t t-elif=\"line.display_type == ''line_note''\">\n                                <i t-out=\"line.name or ''''\">Taking care of Trees Course</i>\n                            </t>\n                        </td>\n                    </tr>\n                </table>\n            </t>\n            <t t-elif=\"(not hasattr(line, ''is_delivery'') or not line.is_delivery)\">\n                <table width=\"100%\" style=\"color: #454748; font-size: 12px; border-collapse: collapse;\">\n                    <t t-set=\"loop_cycle_number\" t-value=\"loop_cycle_number or 0\"></t>\n                    <tr t-att-style=\"''background-color: #f2f2f2'' if loop_cycle_number % 2 == 0 else ''background-color: #ffffff''\">\n                        <t t-set=\"loop_cycle_number\" t-value=\"loop_cycle_number + 1\"></t>\n                        <td style=\"width: 150px;\">\n                            <img t-attf-src=\"/web/image/product.product/{{ line.product_id.id }}/image_128\" style=\"width: 64px; height: 64px; object-fit: contain;\" alt=\"Product image\">\n                        </td>\n                        <td align=\"left\" t-out=\"line.product_id.name or ''''\">\tTaking care of Trees Course</td>\n                        <td width=\"15%\" align=\"center\" t-out=\"line.product_uom_qty or ''''\">1</td>\n                        <td width=\"20%\" align=\"right\"><span style=\"font-weight:bold;\">\n                        <t t-if=\"object.website_id.show_line_subtotals_tax_selection == ''tax_excluded''\">\n                            <t t-out=\"format_amount(line.price_reduce_taxexcl, object.currency_id) or ''''\">$ 10.00</t>\n                        </t>\n                        <t t-else=\"\">\n                            <t t-out=\"format_amount(line.price_reduce_taxinc, object.currency_id) or ''''\">$ 10.00</t>\n                        </t>\n                        </span></td>\n                    </tr>\n                </table>\n            </t>\n        </t>\n    </div>\n    <div style=\"margin: 0px; padding: 0px;\" t-if=\"hasattr(object, ''carrier_id'') and object.carrier_id\">\n        <table width=\"100%\" style=\"color: #454748; font-size: 12px; border-spacing: 0px 4px;\" align=\"right\">\n            <tr>\n                <td style=\"width: 60%\"></td>\n                <td style=\"width: 30%; border-top: 1px solid #dee2e6;\" align=\"right\"><span style=\"font-weight:bold;\">Delivery:</span></td>\n                <td style=\"width: 10%; border-top: 1px solid #dee2e6;\" align=\"right\" t-out=\"format_amount(object.amount_delivery, object.currency_id) or ''''\">$ 0.00</td>\n            </tr>\n            <tr>\n                <td style=\"width: 60%\"></td>\n                <td style=\"width: 30%;\" align=\"right\"><span style=\"font-weight:bold;\">SubTotal:</span></td>\n                <td style=\"width: 10%;\" align=\"right\" t-out=\"format_amount(object.amount_untaxed, object.currency_id) or ''''\">$ 10.00</td>\n            </tr>\n        </table>\n    </div>\n    <div style=\"margin: 0px; padding: 0px;\" t-else=\"\">\n        <table width=\"100%\" style=\"color: #454748; font-size: 12px; border-spacing: 0px 4px;\" align=\"right\">\n            <tr>\n                <td style=\"width: 60%\"></td>\n                <td style=\"width: 30%; border-top: 1px solid #dee2e6;\" align=\"right\"><span style=\"font-weight:bold;\">SubTotal:</span></td>\n                <td style=\"width: 10%; border-top: 1px solid #dee2e6;\" align=\"right\" t-out=\"format_amount(object.amount_untaxed, object.currency_id) or ''''\">$ 10.00</td>\n            </tr>\n        </table>\n    </div>\n    <div style=\"margin: 0px; padding: 0px;\">\n        <table width=\"100%\" style=\"color: #454748; font-size: 12px; border-spacing: 0px 4px;\" align=\"right\">\n            <tr>\n                <td style=\"width: 60%\"></td>\n                <td style=\"width: 30%;\" align=\"right\"><span style=\"font-weight:bold;\">Taxes:</span></td>\n                <td style=\"width: 10%;\" align=\"right\" t-out=\"format_amount(object.amount_tax, object.currency_id) or ''''\">$ 0.00</td>\n            </tr>\n            <tr>\n                <td style=\"width: 60%\"></td>\n                <td style=\"width: 30%; border-top: 1px solid #dee2e6;\" align=\"right\"><span style=\"font-weight:bold;\">Total:</span></td>\n                <td style=\"width: 10%; border-top: 1px solid #dee2e6;\" align=\"right\" t-out=\"format_amount(object.amount_total, object.currency_id) or ''''\">$ 10.00</td>\n            </tr>\n        </table>\n    </div>\n    <div t-if=\"object.partner_invoice_id\" style=\"margin: 0px; padding: 0px;\">\n        <table width=\"100%\" style=\"color: #454748; font-size: 12px;\">\n            <tr>\n                <td style=\"padding-top: 10px;\">\n                    <span style=\"font-weight:bold;\">Bill to:</span>\n                    <t t-out=\"object.partner_invoice_id.street or ''''\">1201 S Figueroa St</t>\n                    <t t-out=\"object.partner_invoice_id.city or ''''\">Los Angeles</t>\n                    <t t-out=\"object.partner_invoice_id.state_id.name or ''''\">California</t>\n                    <t t-out=\"object.partner_invoice_id.zip or ''''\">90015</t>\n                    <t t-out=\"object.partner_invoice_id.country_id.name or ''''\">United States</t>\n                </td>\n            </tr>\n            <tr>\n                <td>\n                    <span style=\"font-weight:bold;\">Payment Method:</span>\n                    <t t-if=\"tx_sudo.token_id\">\n                        <t t-out=\"tx_sudo.token_id.display_name or ''''\"></t>\n                    </t>\n                    <t t-else=\"\">\n                        <t t-out=\"tx_sudo.provider_id.sudo().name or ''''\"></t>\n                    </t>\n                    (<t t-out=\"format_amount(tx_sudo.amount, object.currency_id) or ''''\">$ 10.00</t>)\n                </td>\n            </tr>\n        </table>\n    </div>\n    <div t-if=\"object.partner_shipping_id and not object.only_services\" style=\"margin: 0px; padding: 0px;\">\n        <table width=\"100%\" style=\"color: #454748; font-size: 12px;\">\n            <tr>\n                <td>\n                    <br>\n                    <span style=\"font-weight:bold;\">Ship to:</span>\n                    <t t-out=\"object.partner_shipping_id.street or ''''\">1201 S Figueroa St</t>\n                    <t t-out=\"object.partner_shipping_id.city or ''''\">Los Angeles</t>\n                    <t t-out=\"object.partner_shipping_id.state_id.name or ''''\">California</t>\n                    <t t-out=\"object.partner_shipping_id.zip or ''''\">90015</t>\n                    <t t-out=\"object.partner_shipping_id.country_id.name or ''''\">United States</t>\n                </td>\n            </tr>\n        </table>\n        <table t-if=\"hasattr(object, ''carrier_id'') and object.carrier_id\" width=\"100%\" style=\"color: #454748; font-size: 12px;\">\n            <tr>\n                <td>\n                    <span style=\"font-weight:bold;\">Shipping Method:</span>\n                    <t t-out=\"object.carrier_id.name or ''''\"></t>\n                    <t t-if=\"object.amount_delivery == 0.0\">\n                        (Free)\n                    </t>\n                    <t t-else=\"\">\n                        (<t t-out=\"format_amount(object.amount_delivery, object.currency_id) or ''''\">$ 10.00</t>)\n                    </t>\n                </td>\n            </tr>\n            <tr t-if=\"object.carrier_id.carrier_description\">\n                <td>\n                    <strong>Shipping Description:</strong>\n                    <t t-out=\"object.carrier_id.carrier_description\"></t>\n                </td>\n            </tr>\n        </table>\n    </div>\n</t>\n</div>"}', true, NULL, true, '2026-05-10 01:12:05.269262', '2026-05-10 01:12:05.269262');
INSERT INTO public.mail_template VALUES (12, 499, NULL, NULL, NULL, 1, 1, 'sale/data/mail_template_data.xml', '{{ object.partner_id.lang }}', 'sale.order', '{{ (object.user_id.email_formatted or user.email_formatted) }}', NULL, '{{ object.partner_id.id }}', NULL, NULL, NULL, NULL, '{"en_US": "Sales: Payment Done"}', '{"en_US": "Sent to customers when a payment is received but doesn''t immediately confirm their order"}', '{"en_US": "{{ object.company_id.name }} {{ (object.get_portal_last_transaction().state == ''pending'') and ''Pending Order'' or ''Order'' }} (Ref {{ object.name or ''n/a'' }})"}', '{"en_US": "<div style=\"margin: 0px; padding: 0px;\">\n    <p style=\"margin: 0px; padding: 0px; font-size: 12px;\">\n        <t t-set=\"transaction_sudo\" t-value=\"object.get_portal_last_transaction()\"></t>\n        Hello,\n        <br><br>\n        A payment with reference\n        <span style=\"font-weight:bold;\" t-out=\"transaction_sudo.reference or ''''\">SOOO49</span>\n        amounting\n        <span style=\"font-weight:bold;\" t-out=\"format_amount(transaction_sudo.amount, object.currency_id) or ''''\">$ 10.00</span>\n        for your order\n        <span style=\"font-weight:bold;\" t-out=\"object.name or ''''\">S00049</span>\n        <t t-if=\"transaction_sudo and transaction_sudo.state == ''pending''\">\n            is pending.\n            <br>\n            <t t-if=\"object.currency_id.compare_amounts(object.amount_paid + transaction_sudo.amount, object.amount_total) &gt;= 0 and object.state in (''draft'', ''sent'')\">\n                Your order will be confirmed once the payment is confirmed.\n            </t>\n            <t t-else=\"\">\n                Once confirmed,\n                <span style=\"font-weight:bold;\" t-out=\"format_amount(object.amount_total - object.amount_paid - transaction_sudo.amount, object.currency_id) or ''''\">$ 10.00</span>\n                will remain to be paid.\n            </t>\n        </t>\n        <t t-else=\"\">\n            has been confirmed.\n            <t t-if=\"object.currency_id.compare_amounts(object.amount_paid, object.amount_total) &lt; 0\">\n                <br>\n                <span style=\"font-weight:bold;\" t-out=\"format_amount(object.amount_total - object.amount_paid, object.currency_id) or ''''\">$ 10.00</span>\n                remains to be paid.\n            </t>\n        </t>\n        <br><br>\n        Thank you for your trust!\n        <br>\n        Do not hesitate to contact us if you have any questions.\n        <t t-if=\"not is_html_empty(object.user_id.signature)\">\n            <br><br>\n            <t t-out=\"object.user_id.signature or ''''\">--<br>Mitchell Admin</t>\n        </t>\n        <br><br>\n    </p>\n</div>\n            "}', true, NULL, true, '2026-05-10 01:12:05.269262', '2026-05-10 01:12:05.269262');
INSERT INTO public.mail_template VALUES (13, 499, NULL, NULL, NULL, 1, 1, 'sale/data/mail_template_data.xml', '{{ object.partner_id.lang }}', 'sale.order', '{{ (object.user_id.email_formatted or object.company_id.email_formatted or user.email_formatted) }}', NULL, '{{ object.partner_id.id }}', NULL, NULL, NULL, NULL, '{"en_US": "Sales: Order Cancellation"}', '{"en_US": "Sent automatically to customers when you cancel an order"}', '{"en_US": "{{ object.company_id.name }} {{ object.type_name }} Cancelled (Ref {{ object.name or ''n/a'' }})"}', '{"en_US": "<div style=\"margin: 0px; padding: 0px;\">\n    <p style=\"margin: 0px; padding: 0px; font-size: 13px;\">\n        <t t-set=\"doc_name\" t-value=\"object.type_name\"></t>\n        Dear <t t-out=\"object.partner_id.name or ''''\">user</t>,\n        <br><br>\n        Please be advised that your\n        <t t-out=\"doc_name or ''''\">quotation</t> <strong t-out=\"object.name or ''''\">S00052</strong>\n        <t t-if=\"object.origin\">\n            (with reference: <t t-out=\"object.origin or ''''\">S00052</t> )\n        </t>\n        has been cancelled. Therefore, you should not be charged further for this order.\n        If any refund is necessary, this will be executed at best convenience.\n        <br><br>\n        Do not hesitate to contact us if you have any questions.\n        <br>\n    </p>\n</div>\n            "}', true, NULL, true, '2026-05-10 01:12:05.269262', '2026-05-10 01:12:05.269262');
INSERT INTO public.mail_template VALUES (14, 527, NULL, NULL, NULL, 1, 1, 'stock/data/mail_template_data.xml', '{{ object.partner_id.lang }}', 'stock.picking', NULL, NULL, '{{ object.partner_id.email and object.partner_id.id or object.partner_id.parent_id.id }}', NULL, NULL, NULL, NULL, '{"en_US": "Shipping: Send by Email"}', '{"en_US": "Sent to the customers when orders are delivered, if the setting is enabled"}', '{"en_US": "{{ object.company_id.name }} Delivery Order (Ref {{ object.name or ''n/a'' }})"}', '{"en_US": "<div style=\"margin: 0px; padding: 0px;\">\n    <p style=\"margin: 0px; padding: 0px; font-size: 13px;\">\n        Hello <t t-out=\"object.partner_id.name or ''''\">Brandon Freeman</t>,<br><br>\n        We are glad to inform you that your order has been shipped.\n        <t t-if=\"hasattr(object, ''carrier_tracking_ref'') and object.carrier_tracking_ref\">\n            Your tracking reference is\n            <strong>\n            <t t-if=\"object.carrier_tracking_url\">\n                <t t-set=\"multiple_carrier_tracking\" t-value=\"object.get_multiple_carrier_tracking()\"></t>\n                <t t-if=\"multiple_carrier_tracking\">\n                    <t t-foreach=\"multiple_carrier_tracking\" t-as=\"line\">\n                        <br><a t-att-href=\"line[1]\" target=\"_blank\" t-out=\"line[0] or ''''\"></a>\n                    </t>\n                </t>\n                <t t-else=\"\">\n                    <a t-attf-href=\"{{ object.carrier_tracking_url }}\" target=\"_blank\" t-out=\"object.carrier_tracking_ref or ''''\"></a>.\n                </t>\n            </t>\n            <t t-else=\"\">\n                <t t-out=\"object.carrier_tracking_ref or ''''\"></t>.\n            </t>\n            </strong>\n        </t>\n        <br><br>\n        Please find your delivery order attached for more details.<br><br>\n        Thank you,\n        <t t-if=\"user.signature\">\n            <br>\n            <t t-out=\"user.signature or ''''\">--<br>Mitchell Admin</t>\n        </t>\n    </p>\n</div>\n        "}', true, NULL, true, '2026-05-10 01:12:18.247927', '2026-05-10 01:12:18.247927');
INSERT INTO public.mail_template VALUES (15, 573, NULL, NULL, NULL, 1, 1, 'purchase/data/mail_template_data.xml', '{{ object.partner_id.lang }}', 'purchase.order', NULL, NULL, '{{ object.partner_id.id }}', NULL, NULL, NULL, NULL, '{"en_US": "Purchase: Request For Quotation"}', '{"en_US": "Sent manually to vendor to request a quotation"}', '{"en_US": "{{ object.company_id.name }} Order (Ref {{ object.name or ''n/a'' }})"}', '{"en_US": "<div style=\"margin: 0px; padding: 0px;\">\n    <p style=\"margin: 0px; padding: 0px; font-size: 13px;\">\n        Dear <t t-out=\"object.partner_id.name or ''''\">Brandon Freeman</t>\n        <t t-if=\"object.partner_id.parent_id\">\n            (<t t-out=\"object.partner_id.parent_id.name or ''''\">Azure Interior</t>)\n        </t>\n        <br><br>\n        Here is in attachment a request for quotation <span style=\"font-weight:bold;\" t-out=\"object.name or ''''\">P00015</span>\n        <t t-if=\"object.partner_ref\">\n            with reference: <t t-out=\"object.partner_ref or ''''\">REF_XXX</t>\n        </t>\n        from <t t-out=\"object.company_id.name or ''''\">YourCompany</t>.\n        <br><br>\n        If you have any questions, please do not hesitate to contact us.\n        <br><br>\n        Best regards,\n        <t t-if=\"not is_html_empty(object.user_id.signature)\">\n            <br><br>\n            <t t-out=\"object.user_id.signature or ''''\">--<br>Mitchell Admin</t>\n        </t>\n    </p>\n</div>"}', true, NULL, true, '2026-05-10 01:12:29.662147', '2026-05-10 01:12:29.662147');
INSERT INTO public.mail_template VALUES (16, 573, NULL, NULL, NULL, 1, 1, 'purchase/data/mail_template_data.xml', '{{ object.partner_id.lang }}', 'purchase.order', NULL, NULL, '{{ object.partner_id.id }}', NULL, NULL, NULL, NULL, '{"en_US": "Purchase: Purchase Order"}', '{"en_US": "Sent to vendor with the purchase order in attachment"}', '{"en_US": "{{ object.company_id.name }} Order (Ref {{ object.name or ''n/a'' }})"}', '{"en_US": "<div style=\"margin: 0px; padding: 0px;\">\n    <p style=\"margin: 0px; padding: 0px; font-size: 13px;\">\n        Dear <t t-out=\"object.partner_id.name or ''''\">Brandon Freeman</t>\n        <t t-if=\"object.partner_id.parent_id\">\n            (<t t-out=\"object.partner_id.parent_id.name or ''''\">Azure Interior</t>)\n        </t>\n        <br><br>\n        Here is in attachment a purchase order <span style=\"font-weight:bold;\" t-out=\"object.name or ''''\">P00015</span>\n        <t t-if=\"object.partner_ref\">\n            with reference: <t t-out=\"object.partner_ref or ''''\">REF_XXX</t>\n        </t>\n        amounting in <span style=\"font-weight:bold;\" t-out=\"format_amount(object.amount_total, object.currency_id) or ''''\">$ 10.00</span>\n        from <t t-out=\"object.company_id.name or ''''\">YourCompany</t>. \n        <br><br>\n        <t t-if=\"object.date_planned\">\n            The receipt is expected for <span style=\"font-weight:bold;\" t-out=\"format_date(object.date_planned) or ''''\">05/05/2021</span>.\n            <br><br>\n            Could you please acknowledge the receipt of this order?\n        </t>\n        <t t-if=\"not is_html_empty(object.user_id.signature)\">\n            <br><br>\n            <t t-out=\"object.user_id.signature or ''''\">--<br>Mitchell Admin</t>\n        </t>\n        <br><br>\n    </p>\n</div>"}', true, NULL, true, '2026-05-10 01:12:29.662147', '2026-05-10 01:12:29.662147');
INSERT INTO public.mail_template VALUES (17, 573, NULL, NULL, NULL, 1, 1, 'purchase/data/mail_template_data.xml', '{{ object.partner_id.lang }}', 'purchase.order', '{{ (object.user_id.email_formatted or user.email_formatted) }}', NULL, '{{ object.partner_id.id }}', NULL, NULL, NULL, NULL, '{"en_US": "Purchase: Vendor Reminder"}', '{"en_US": "Sent to vendors before expected arrival, based on the purchase order setting"}', '{"en_US": "{{ object.company_id.name }} Order (Ref {{ object.name or ''n/a'' }})"}', '{"en_US": "<div style=\"margin: 0px; padding: 0px;\">\n    <p style=\"margin: 0px; padding: 0px; font-size: 13px;\">\n        Dear <t t-out=\"object.partner_id.name or ''''\">Brandon Freeman</t>\n        <t t-if=\"object.partner_id.parent_id\">\n            (<t t-out=\"object.partner_id.parent_id.name or ''''\">Azure Interior</t>)\n        </t>\n        <br><br>\n        Here is a reminder that the delivery of the purchase order <span style=\"font-weight:bold;\" t-out=\"object.name or ''''\">P00015</span>\n        <t t-if=\"object.partner_ref\">\n            <span style=\"font-weight:bold;\">(<t t-out=\"object.partner_ref or ''''\">REF_XXX</t>)</span>\n        </t>\n        is expected for \n        <t t-if=\"object.date_planned\">\n            <span style=\"font-weight:bold;\" t-out=\"format_date(object.date_planned) or ''''\">05/05/2021</span>.\n        </t>\n         <t t-else=\"\">\n            <span style=\"font-weight:bold;\">undefined</span>.\n        </t>\n        Could you please confirm it will be delivered on time?\n        <t t-if=\"not is_html_empty(object.user_id.signature)\">\n            <br><br>\n            <t t-out=\"object.user_id.signature or ''''\">--<br>Mitchell Admin</t>\n        </t>\n        <br><br>\n    </p>\n</div>"}', true, NULL, true, '2026-05-10 01:12:29.662147', '2026-05-10 01:12:29.662147');


